
-- load extension trgm
CREATE EXTENSION IF NOT EXISTS pg_trgm;

DROP TABLE IF EXISTS surah;
DROP TABLE IF EXISTS ayah;

CREATE TABLE surah (
  number INT PRIMARY KEY,
  name TEXT,
  english_name TEXT,
  english_name_translation TEXT,
  revelation_type TEXT,
  number_of_ayahs INT
);

CREATE TABLE ayah (
  surah_number_fk INT NOT NULL REFERENCES surah(number),
  number INT PRIMARY KEY,
  text TEXT,
  imlaei_simple_text TEXT,
  qpc_tajweed_text TEXT,
  number_in_surah INT,
  juz INT,
  manzil INT,
  page INT,
  ruku INT,
  hizb_quarter INT,
  sajda JSONB
);



-- Surah Al-Faatiha
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (1, 'سُورَةُ ٱلْفَاتِحَةِ', 'Al-Faatiha', 'The Opening', 'Meccan', 7);

  -- Ayah 2 Surah Al-Faatiha
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    1,
    2,
    'ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'الحمد لله رب العالمين',
    'ٱلۡحَمۡدُ لِلَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 1, 1, 1, 1, 1, 'false'
  );
  
  -- Ayah 3 Surah Al-Faatiha
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    1,
    3,
    'ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ',
    'الرحمن الرحيم',
    'ٱ<rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مِ ٣',
    3, 1, 1, 1, 1, 1, 'false'
  );
  
  -- Ayah 4 Surah Al-Faatiha
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    1,
    4,
    'مَـٰلِكِ یَوۡمِ ٱلدِّینِ',
    'مالك يوم الدين',
    'مَ<rule class=madda_normal>ـٰ</rule>لِكِ يَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ٤',
    4, 1, 1, 1, 1, 1, 'false'
  );
  
  -- Ayah 5 Surah Al-Faatiha
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    1,
    5,
    'إِیَّاكَ نَعۡبُدُ وَإِیَّاكَ نَسۡتَعِینُ',
    'اياك نعبد واياك نستعين',
    'إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَع<rule class=madda_permissible>ِي</rule>نُ ٥',
    5, 1, 1, 1, 1, 1, 'false'
  );
  
  -- Ayah 6 Surah Al-Faatiha
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    1,
    6,
    'ٱهۡدِنَا ٱلصِّرَ ٰ⁠طَ ٱلۡمُسۡتَقِیمَ',
    'اهدنا الصراط المستقيم',
    'ٱهۡدِنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّر<rule class=madda_normal>ٰ</rule>طَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَق<rule class=madda_permissible>ِي</rule>مَ ٦',
    6, 1, 1, 1, 1, 1, 'false'
  );
  
  -- Ayah 7 Surah Al-Faatiha
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    1,
    7,
    'صِرَ ٰ⁠طَ ٱلَّذِینَ أَنۡعَمۡتَ عَلَیۡهِمۡ غَیۡرِ ٱلۡمَغۡضُوبِ عَلَیۡهِمۡ وَلَا ٱلضَّاۤلِّینَ',
    'صراط الذين انعمت عليهم غير المغضوب عليهم ولا الضالين',
    'صِر<rule class=madda_normal>ٰ</rule>طَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضّ<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 1, 1, 1, 1, 1, 'false'
  );
  

-- Surah Al-Baqara
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (2, 'سُورَةُ البَقَرَةِ', 'Al-Baqara', 'The Cow', 'Medinan', 286);

  -- Ayah 1 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    8,
    'الۤمۤ',
    'الم',
    'ا<rule class=madda_necessary>لٓ</rule><rule class=madda_necessary>مٓ</rule> ١',
    1, 1, 1, 2, 2, 1, 'false'
  );
  
  -- Ayah 2 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    9,
    'ذَ ٰ⁠لِكَ ٱلۡكِتَـٰبُ لَا رَیۡبَۛ فِیهِۛ هُدࣰى لِّلۡمُتَّقِینَ',
    'ذلك الكتاب لا ريب فيه هدى للمتقين',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بُ لَا رَيۡبَ‌ۛ فِيهِ‌ۛ هُ<rule class=idgham_wo_ghunnah>دًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 1, 1, 2, 2, 1, 'false'
  );
  
  -- Ayah 3 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    10,
    'ٱلَّذِینَ یُؤۡمِنُونَ بِٱلۡغَیۡبِ وَیُقِیمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ',
    'الذين يؤمنون بالغيب ويقيمون الصلاة ومما رزقناهم ينفقون',
    'ٱلَّذِينَ يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَيُقِيمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَمِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ يُ<rule class=ikhafa>نف</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 1, 1, 2, 2, 1, 'false'
  );
  
  -- Ayah 4 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    11,
    'وَٱلَّذِینَ یُؤۡمِنُونَ بِمَاۤ أُنزِلَ إِلَیۡكَ وَمَاۤ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ',
    'والذين يؤمنون بما انزل اليك وما انزل من قبلك وبالاخرة هم يوقنون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡمِنُونَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ وَبِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمۡ يُوقِن<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 1, 1, 2, 2, 1, 'false'
  );
  
  -- Ayah 5 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    12,
    'أُو۟لَـٰۤىِٕكَ عَلَىٰ هُدࣰى مِّن رَّبِّهِمۡۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'اولئك على هدى من ربهم واولئك هم المفلحون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ عَلَىٰ هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 1, 1, 2, 2, 1, 'false'
  );
  
  -- Ayah 6 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    13,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ سَوَاۤءٌ عَلَیۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا یُؤۡمِنُونَ',
    'ان الذين كفروا سواء عليهم اانذرتهم ام لم تنذرهم لا يؤمنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ عَلَيۡهِمۡ ءَأَ<rule class=ikhafa>نذ</rule>َرۡتَهُمۡ أَمۡ لَمۡ تُ<rule class=ikhafa>نذ</rule>ِرۡهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 1, 1, 3, 2, 1, 'false'
  );
  
  -- Ayah 7 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    14,
    'خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰۤ أَبۡصَـٰرِهِمۡ غِشَـٰوَةࣱۖ وَلَهُمۡ عَذَابٌ عَظِیمࣱ',
    'ختم الله على قلوبهم وعلى سمعهم وعلى ابصارهم غشاوة ولهم عذاب عظيم',
    'خَتَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡ‌ۖ وَعَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ غِشَ<rule class=madda_normal>ـٰ</rule>وَ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٧',
    7, 1, 1, 3, 2, 1, 'false'
  );
  
  -- Ayah 8 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    15,
    'وَمِنَ ٱلنَّاسِ مَن یَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَمَا هُم بِمُؤۡمِنِینَ',
    'ومن الناس من يقول امنا بالله وباليوم الاخر وما هم بمؤمنين',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُ ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَبِ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَمَا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 9 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    16,
    'یُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِینَ ءَامَنُوا۟ وَمَا یَخۡدَعُونَ إِلَّاۤ أَنفُسَهُمۡ وَمَا یَشۡعُرُونَ',
    'يخادعون الله والذين امنوا وما يخدعون الا انفسهم وما يشعرون',
    'يُخَ<rule class=madda_normal>ـٰ</rule>دِعُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَمَا يَخۡدَعُونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَمَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 10 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    17,
    'فِی قُلُوبِهِم مَّرَضࣱ فَزَادَهُمُ ٱللَّهُ مَرَضࣰاۖ وَلَهُمۡ عَذَابٌ أَلِیمُۢ بِمَا كَانُوا۟ یَكۡذِبُونَ',
    'في قلوبهم مرض فزادهم الله مرضا ولهم عذاب اليم بما كانوا يكذبون',
    'فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَ<rule class=ikhafa>ضٌ</rule> <rule class=ikhafa>ف</rule>َزَادَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مَرَ<rule class=idgham_ghunnah>ضًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ عَذَابٌ أَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡذِب<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 11 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    18,
    'وَإِذَا قِیلَ لَهُمۡ لَا تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ قَالُوۤا۟ إِنَّمَا نَحۡنُ مُصۡلِحُونَ',
    'واذا قيل لهم لا تفسدوا في الارض قالوا انما نحن مصلحون',
    'وَإِذَا قِيلَ لَهُمۡ لَا تُفۡسِدُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا نَحۡنُ مُصۡلِح<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 12 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    19,
    'أَلَاۤ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَـٰكِن لَّا یَشۡعُرُونَ',
    'الا انهم هم المفسدون ولكن لا يشعرون',
    'أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِدُونَ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 13 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    20,
    'وَإِذَا قِیلَ لَهُمۡ ءَامِنُوا۟ كَمَاۤ ءَامَنَ ٱلنَّاسُ قَالُوۤا۟ أَنُؤۡمِنُ كَمَاۤ ءَامَنَ ٱلسُّفَهَاۤءُۗ أَلَاۤ إِنَّهُمۡ هُمُ ٱلسُّفَهَاۤءُ وَلَـٰكِن لَّا یَعۡلَمُونَ',
    'واذا قيل لهم امنوا كما امن الناس قالوا انؤمن كما امن السفهاء الا انهم هم السفهاء ولكن لا يعلمون',
    'وَإِذَا قِيلَ لَهُمۡ ءَامِنُو<rule class=slnt>اۡ</rule> كَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَنُؤۡمِنُ كَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّفَه<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّفَه<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 14 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    21,
    'وَإِذَا لَقُوا۟ ٱلَّذِینَ ءَامَنُوا۟ قَالُوۤا۟ ءَامَنَّا وَإِذَا خَلَوۡا۟ إِلَىٰ شَیَـٰطِینِهِمۡ قَالُوۤا۟ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ',
    'واذا لقوا الذين امنوا قالوا امنا واذا خلوا الى شياطينهم قالوا انا معكم انما نحن مستهزئون',
    'وَإِذَا لَقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا وَإِذَا خَلَوۡ<rule class=slnt>اۡ</rule> إِلَىٰ شَيَ<rule class=madda_normal>ـٰ</rule>طِينِهِمۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا مَعَكُمۡ إِ<rule class=ghunnah>نّ</rule>َمَا نَحۡنُ مُسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 15 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    22,
    'ٱللَّهُ یَسۡتَهۡزِئُ بِهِمۡ وَیَمُدُّهُمۡ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ',
    'الله يستهزئ بهم ويمدهم في طغيانهم يعمهون',
    'ٱللَّهُ يَسۡتَهۡزِئُ بِهِمۡ وَيَمُدُّهُمۡ فِى طُغۡيَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ يَعۡمَه<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 16 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    23,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمۡ وَمَا كَانُوا۟ مُهۡتَدِینَ',
    'اولئك الذين اشتروا الضلالة بالهدى فما ربحت تجارتهم وما كانوا مهتدين',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>شۡتَرَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لَةَ بِ<rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ فَمَا رَبِحَت تِّجَ<rule class=madda_normal>ـٰ</rule>رَتُهُمۡ وَمَا كَانُو<rule class=slnt>اۡ</rule> مُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ١٦',
    16, 1, 1, 3, 3, 1, 'false'
  );
  
  -- Ayah 17 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    24,
    'مَثَلُهُمۡ كَمَثَلِ ٱلَّذِی ٱسۡتَوۡقَدَ نَارࣰا فَلَمَّاۤ أَضَاۤءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِی ظُلُمَـٰتࣲ لَّا یُبۡصِرُونَ',
    'مثلهم كمثل الذي استوقد نارا فلما اضاءت ما حوله ذهب الله بنورهم وتركهم في ظلمات لا يبصرون',
    'مَثَلُهُمۡ كَمَثَلِ <rule class=ham_wasl>ٱ</rule>لَّذِى <rule class=ham_wasl>ٱ</rule>سۡتَوۡقَدَ نَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَض<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ مَا حَوۡلَهُ<rule class=madda_normal>ۥ</rule> ذَهَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِى ظُلُمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 1, 1, 4, 3, 1, 'false'
  );
  
  -- Ayah 18 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    25,
    'صُمُّۢ بُكۡمٌ عُمۡیࣱ فَهُمۡ لَا یَرۡجِعُونَ',
    'صم بكم عمي فهم لا يرجعون',
    'صُم<rule class=iqlab>ُّۢ</rule> <rule class=iqlab>ب</rule>ُكۡمٌ عُمۡ<rule class=ikhafa>ىٌ</rule> <rule class=ikhafa>ف</rule>َهُمۡ لَا يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 1, 1, 4, 3, 1, 'false'
  );
  
  -- Ayah 19 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    26,
    'أَوۡ كَصَیِّبࣲ مِّنَ ٱلسَّمَاۤءِ فِیهِ ظُلُمَـٰتࣱ وَرَعۡدࣱ وَبَرۡقࣱ یَجۡعَلُونَ أَصَـٰبِعَهُمۡ فِیۤ ءَاذَانِهِم مِّنَ ٱلصَّوَ ٰ⁠عِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِیطُۢ بِٱلۡكَـٰفِرِینَ',
    'او كصيب من السماء فيه ظلمات ورعد وبرق يجعلون اصابعهم في اذانهم من الصواعق حذر الموت والله محيط بالكافرين',
    'أَوۡ كَصَيِّ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فِيهِ ظُلُمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>و</rule>َرَعۡ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َبَرۡ<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>عَلُونَ أَصَ<rule class=madda_normal>ـٰ</rule>بِعَهُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاذَانِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّو<rule class=madda_normal>ٰ</rule>عِقِ حَذَرَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ مُحِي<rule class=iqlab>طُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٩',
    19, 1, 1, 4, 3, 1, 'false'
  );
  
  -- Ayah 20 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    27,
    'یَكَادُ ٱلۡبَرۡقُ یَخۡطَفُ أَبۡصَـٰرَهُمۡۖ كُلَّمَاۤ أَضَاۤءَ لَهُم مَّشَوۡا۟ فِیهِ وَإِذَاۤ أَظۡلَمَ عَلَیۡهِمۡ قَامُوا۟ۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَـٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'يكاد البرق يخطف ابصارهم كلما اضاء لهم مشوا فيه واذا اظلم عليهم قاموا ولو شاء الله لذهب بسمعهم وابصارهم ان الله على كل شيء قدير',
    'يَكَادُ <rule class=ham_wasl>ٱ</rule>لۡبَرۡقُ يَخۡطَفُ أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَهُمۡ‌ۖ كُلَّم<rule class=madda_obligatory_monfasel>َآ</rule> أَض<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّشَوۡ<rule class=slnt>اۡ</rule> فِيهِ وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَظۡلَمَ عَلَيۡهِمۡ قَامُو<rule class=slnt>اۡ‌ۚ</rule> وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٢٠',
    20, 1, 1, 4, 3, 1, 'false'
  );
  
  -- Ayah 21 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    28,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ ٱعۡبُدُوا۟ رَبَّكُمُ ٱلَّذِی خَلَقَكُمۡ وَٱلَّذِینَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ',
    'يا ايها الناس اعبدوا ربكم الذي خلقكم والذين من قبلكم لعلكم تتقون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> رَبَّكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَكُمۡ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ لَعَلَّكُمۡ تَتَّق<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 1, 1, 4, 4, 1, 'false'
  );
  
  -- Ayah 22 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    29,
    'ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَ ٰ⁠شࣰا وَٱلسَّمَاۤءَ بِنَاۤءࣰ وَأَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَ ٰ⁠تِ رِزۡقࣰا لَّكُمۡۖ فَلَا تَجۡعَلُوا۟ لِلَّهِ أَندَادࣰا وَأَنتُمۡ تَعۡلَمُونَ',
    'الذي جعل لكم الارض فراشا والسماء بناء وانزل من السماء ماء فاخرج به من الثمرات رزقا لكم فلا تجعلوا لله اندادا وانتم تعلمون',
    'ٱلَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>شًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِن<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَخۡرَجَ بِه<rule class=madda_normal>ِۦ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ رِزۡ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ فَلَا تَ<rule class=qalaqah>جۡ</rule>عَلُو<rule class=slnt>اۡ</rule> لِلَّهِ أَ<rule class=ikhafa>ند</rule>َا<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 1, 1, 4, 4, 1, 'false'
  );
  
  -- Ayah 23 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    30,
    'وَإِن كُنتُمۡ فِی رَیۡبࣲ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُوا۟ بِسُورَةࣲ مِّن مِّثۡلِهِۦ وَٱدۡعُوا۟ شُهَدَاۤءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَـٰدِقِینَ',
    'وان كنتم في ريب مما نزلنا على عبدنا فاتوا بسورة من مثله وادعوا شهداءكم من دون الله ان كنتم صادقين',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ فِى رَيۡ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا نَزَّلۡنَا عَلَىٰ عَ<rule class=qalaqah>بۡ</rule>دِنَا فَأۡتُو<rule class=slnt>اۡ</rule> بِسُورَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٢٣',
    23, 1, 1, 4, 4, 1, 'false'
  );
  
  -- Ayah 24 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    31,
    'فَإِن لَّمۡ تَفۡعَلُوا۟ وَلَن تَفۡعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِی وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَـٰفِرِینَ',
    'فان لم تفعلوا ولن تفعلوا فاتقوا النار التي وقودها الناس والحجارة اعدت للكافرين',
    'فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَفۡعَلُو<rule class=slnt>اۡ</rule> وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َفۡعَلُو<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ <rule class=ham_wasl>ٱ</rule>لَّتِى وَقُودُهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ وَ<rule class=ham_wasl>ٱ</rule>لۡحِجَارَةُ‌ۖ أُعِدَّتۡ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 1, 1, 4, 4, 1, 'false'
  );
  
  -- Ayah 25 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    32,
    'وَبَشِّرِ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ كُلَّمَا رُزِقُوا۟ مِنۡهَا مِن ثَمَرَةࣲ رِّزۡقࣰا قَالُوا۟ هَـٰذَا ٱلَّذِی رُزِقۡنَا مِن قَبۡلُۖ وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهࣰاۖ وَلَهُمۡ فِیهَاۤ أَزۡوَ ٰ⁠جࣱ مُّطَهَّرَةࣱۖ وَهُمۡ فِیهَا خَـٰلِدُونَ',
    'وبشر الذين امنوا وعملوا الصالحات ان لهم جنات تجري من تحتها الانهار كلما رزقوا منها من ثمرة رزقا قالوا هذا الذي رزقنا من قبل واتوا به متشابها ولهم فيها ازواج مطهرة وهم فيها خالدون',
    'وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ أَ<rule class=ghunnah>نّ</rule>َ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۖ كُلَّمَا رُزِقُو<rule class=slnt>اۡ</rule> مِنۡهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َمَرَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّزۡ<rule class=ikhafa>قًا‌ۙ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى رُزِ<rule class=qalaqah>قۡ</rule>نَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ وَأُتُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> مُتَشَ<rule class=madda_normal>ـٰ</rule>بِ<rule class=idgham_ghunnah>هًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّطَهَّرَ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 1, 1, 5, 4, 1, 'false'
  );
  
  -- Ayah 26 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    33,
    '۞ إِنَّ ٱللَّهَ لَا یَسۡتَحۡیِۦۤ أَن یَضۡرِبَ مَثَلࣰا مَّا بَعُوضَةࣰ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ فَیَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِینَ كَفَرُوا۟ فَیَقُولُونَ مَاذَاۤ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلࣰاۘ یُضِلُّ بِهِۦ كَثِیرࣰا وَیَهۡدِی بِهِۦ كَثِیرࣰاۚ وَمَا یُضِلُّ بِهِۦۤ إِلَّا ٱلۡفَـٰسِقِینَ',
    'ان الله لا يستحيي ان يضرب مثلا ما بعوضة فما فوقها فاما الذين امنوا فيعلمون انه الحق من ربهم واما الذين كفروا فيقولون ماذا اراد الله بهذا مثلا يضل به كثيرا ويهدي به كثيرا وما يضل به الا الفاسقين',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَسۡتَحۡى<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضۡرِبَ مَثَل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا بَعُوضَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َمَا فَوۡقَهَا‌ۚ فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> فَيَعۡلَمُونَ أَ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ‌ۖ وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فَيَقُولُونَ مَاذ<rule class=madda_obligatory_monfasel>َآ</rule> أَرَادَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِهَ<rule class=madda_normal>ـٰ</rule>ذَا مَثَل<rule class=idgham_ghunnah>اً‌ۘ</rule> <rule class=idgham_ghunnah>ي</rule>ُضِلُّ بِه<rule class=madda_normal>ِۦ</rule> كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َيَهۡدِى بِه<rule class=madda_normal>ِۦ</rule> كَثِي<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا يُضِلُّ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٢٦',
    26, 1, 1, 5, 4, 2, 'false'
  );
  
  -- Ayah 27 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    34,
    'ٱلَّذِینَ یَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِیثَـٰقِهِۦ وَیَقۡطَعُونَ مَاۤ أَمَرَ ٱللَّهُ بِهِۦۤ أَن یُوصَلَ وَیُفۡسِدُونَ فِی ٱلۡأَرۡضِۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ',
    'الذين ينقضون عهد الله من بعد ميثاقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اولئك هم الخاسرون',
    'ٱلَّذِينَ يَ<rule class=ikhafa>نق</rule>ُضُونَ عَهۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مِيثَ<rule class=madda_normal>ـٰ</rule>قِه<rule class=madda_normal>ِۦ</rule> وَيَ<rule class=qalaqah>قۡ</rule>طَعُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَمَرَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُوصَلَ وَيُفۡسِدُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 1, 1, 5, 4, 2, 'false'
  );
  
  -- Ayah 28 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    35,
    'كَیۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَ ٰ⁠تࣰا فَأَحۡیَـٰكُمۡۖ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡ ثُمَّ إِلَیۡهِ تُرۡجَعُونَ',
    'كيف تكفرون بالله وكنتم امواتا فاحياكم ثم يميتكم ثم يحييكم ثم اليه ترجعون',
    'كَيۡفَ تَكۡفُرُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَكُ<rule class=ikhafa>نت</rule>ُمۡ أَمۡو<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تًا</rule> <rule class=ikhafa>ف</rule>َأَحۡيَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ يُمِيتُكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يُحۡيِيكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ إِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 1, 1, 5, 4, 2, 'false'
  );
  
  -- Ayah 29 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    36,
    'هُوَ ٱلَّذِی خَلَقَ لَكُم مَّا فِی ٱلۡأَرۡضِ جَمِیعࣰا ثُمَّ ٱسۡتَوَىٰۤ إِلَى ٱلسَّمَاۤءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲۚ وَهُوَ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'هو الذي خلق لكم ما في الارض جميعا ثم استوى الى السماء فسواهن سبع سماوات وهو بكل شيء عليم',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَوَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَسَوَّ<rule class=madda_normal>ٮٰ</rule>هُ<rule class=ghunnah>نّ</rule>َ سَ<rule class=qalaqah>بۡ</rule>عَ سَمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٩',
    29, 1, 1, 5, 4, 2, 'false'
  );
  
  -- Ayah 30 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    37,
    'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰۤىِٕكَةِ إِنِّی جَاعِلࣱ فِی ٱلۡأَرۡضِ خَلِیفَةࣰۖ قَالُوۤا۟ أَتَجۡعَلُ فِیهَا مَن یُفۡسِدُ فِیهَا وَیَسۡفِكُ ٱلدِّمَاۤءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّیۤ أَعۡلَمُ مَا لَا تَعۡلَمُونَ',
    'واذ قال ربك للملائكة اني جاعل في الارض خليفة قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون',
    'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ إِ<rule class=ghunnah>نّ</rule>ِى جَاعِ<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ خَلِيفَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَتَ<rule class=qalaqah>جۡ</rule>عَلُ فِيهَا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُفۡسِدُ فِيهَا وَيَسۡفِكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَ‌ۖ قَالَ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡلَمُ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 1, 1, 6, 5, 2, 'false'
  );
  
  -- Ayah 31 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    38,
    'وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَاۤءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَـٰۤىِٕكَةِ فَقَالَ أَنۢبِـُٔونِی بِأَسۡمَاۤءِ هَـٰۤؤُلَاۤءِ إِن كُنتُمۡ صَـٰدِقِینَ',
    'وعلم ادم الاسماء كلها ثم عرضهم على الملائكة فقال انبئوني باسماء هؤلاء ان كنتم صادقين',
    'وَعَلَّمَ ءَادَمَ <rule class=ham_wasl>ٱ</rule>لۡأَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ كُلَّهَا ثُ<rule class=ghunnah>مّ</rule>َ عَرَضَهُمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ فَقَالَ أَ<rule class=iqlab>نۢب</rule>ِــُٔونِى بِأَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 1, 1, 6, 5, 2, 'false'
  );
  
  -- Ayah 32 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    39,
    'قَالُوا۟ سُبۡحَـٰنَكَ لَا عِلۡمَ لَنَاۤ إِلَّا مَا عَلَّمۡتَنَاۤۖ إِنَّكَ أَنتَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ',
    'قالوا سبحانك لا علم لنا الا ما علمتنا انك انت العليم الحكيم',
    'قَالُو<rule class=slnt>اۡ</rule> سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ لَا عِلۡمَ لَن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا مَا عَلَّمۡتَن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَلِيمُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٣٢',
    32, 1, 1, 6, 5, 2, 'false'
  );
  
  -- Ayah 33 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    40,
    'قَالَ یَـٰۤـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَاۤىِٕهِمۡۖ فَلَمَّاۤ أَنۢبَأَهُم بِأَسۡمَاۤىِٕهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّیۤ أَعۡلَمُ غَیۡبَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ',
    'قال يا ادم انبئهم باسمائهم فلما انباهم باسمائهم قال الم اقل لكم اني اعلم غيب السماوات والارض واعلم ما تبدون وما كنتم تكتمون',
    'قَالَ يَ<rule class=madda_obligatory_mottasel>ـٰٓـ</rule>ــَٔادَمُ أَ<rule class=iqlab>نۢب</rule>ِئۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ‌ۖ فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=iqlab>نۢب</rule>َأَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡلَمُ غَيۡبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَأَعۡلَمُ مَا تُ<rule class=qalaqah>بۡ</rule>دُونَ وَمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡتُم<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 1, 1, 6, 5, 2, 'false'
  );
  
  -- Ayah 34 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    41,
    'وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَـٰفِرِینَ',
    'واذ قلنا للملائكة اسجدوا لادم فسجدوا الا ابليس ابى واستكبر وكان من الكافرين',
    'وَإِذۡ قُلۡنَا لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ <rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> لِأَدَمَ فَسَجَد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>لِيسَ أَبَىٰ وَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرَ وَكَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 1, 1, 6, 5, 2, 'false'
  );
  
  -- Ayah 35 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    42,
    'وَقُلۡنَا یَـٰۤـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَیۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِینَ',
    'وقلنا يا ادم اسكن انت وزوجك الجنة وكلا منها رغدا حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظالمين',
    'وَقُلۡنَا يَ<rule class=madda_obligatory_mottasel>ـٰٓـ</rule>ــَٔادَمُ <rule class=ham_wasl>ٱ</rule>سۡكُنۡ أَ<rule class=ikhafa>نت</rule>َ وَزَوۡجُكَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ وَكُلَا مِنۡهَا رَغَدًا حَيۡثُ شِئۡتُمَا وَلَا تَ<rule class=qalaqah>قۡ</rule>رَبَا هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرَةَ فَتَكُونَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٣٥',
    35, 1, 1, 6, 5, 2, 'false'
  );
  
  -- Ayah 36 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    43,
    'فَأَزَلَّهُمَا ٱلشَّیۡطَـٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِیهِۖ وَقُلۡنَا ٱهۡبِطُوا۟ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ وَلَكُمۡ فِی ٱلۡأَرۡضِ مُسۡتَقَرࣱّ وَمَتَـٰعٌ إِلَىٰ حِینࣲ',
    'فازلهما الشيطان عنها فاخرجهما مما كانا فيه وقلنا اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتاع الى حين',
    'فَأَزَلَّهُمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ عَنۡهَا فَأَخۡرَجَهُمَا مِ<rule class=ghunnah>مّ</rule>َا كَانَا فِيهِ‌ۖ وَقُلۡنَا <rule class=ham_wasl>ٱ</rule>هۡبِطُو<rule class=slnt>اۡ</rule> بَعۡضُكُمۡ لِبَعۡضٍ عَدُ<rule class=idgham_ghunnah>وٌّ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُسۡتَقَ<rule class=idgham_ghunnah>رٌّ</rule> <rule class=idgham_ghunnah>و</rule>َمَتَ<rule class=madda_normal>ـٰ</rule>عٌ إِلَىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٣٦',
    36, 1, 1, 6, 5, 2, 'false'
  );
  
  -- Ayah 37 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    44,
    'فَتَلَقَّىٰۤ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتࣲ فَتَابَ عَلَیۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ',
    'فتلقى ادم من ربه كلمات فتاب عليه انه هو التواب الرحيم',
    'فَتَلَقَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَادَمُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule> كَلِمَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>َتَابَ عَلَيۡهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوَّابُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٣٧',
    37, 1, 1, 6, 5, 2, 'false'
  );
  
  -- Ayah 38 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    45,
    'قُلۡنَا ٱهۡبِطُوا۟ مِنۡهَا جَمِیعࣰاۖ فَإِمَّا یَأۡتِیَنَّكُم مِّنِّی هُدࣰى فَمَن تَبِعَ هُدَایَ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'قلنا اهبطوا منها جميعا فاما ياتينكم مني هدى فمن تبع هداي فلا خوف عليهم ولا هم يحزنون',
    'قُلۡنَا <rule class=ham_wasl>ٱ</rule>هۡبِطُو<rule class=slnt>اۡ</rule> مِنۡهَا جَمِي<rule class=ikhafa>عًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>مّ</rule>َا يَأۡتِيَ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>نّ</rule>ِى هُ<rule class=ikhafa>دًى</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبِعَ هُدَاىَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 1, 1, 7, 5, 2, 'false'
  );
  
  -- Ayah 39 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    46,
    'وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'والذين كفروا وكذبوا باياتنا اولئك اصحاب النار هم فيها خالدون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَكَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 1, 1, 7, 5, 2, 'false'
  );
  
  -- Ayah 40 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    47,
    'یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱذۡكُرُوا۟ نِعۡمَتِیَ ٱلَّتِیۤ أَنۡعَمۡتُ عَلَیۡكُمۡ وَأَوۡفُوا۟ بِعَهۡدِیۤ أُوفِ بِعَهۡدِكُمۡ وَإِیَّـٰیَ فَٱرۡهَبُونِ',
    'يا بني اسرائيل اذكروا نعمتي التي انعمت عليكم واوفوا بعهدي اوف بعهدكم واياي فارهبون',
    'يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَتِىَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَوۡفُو<rule class=slnt>اۡ</rule> بِعَهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُوفِ بِعَهۡدِكُمۡ وَإِيَّ<rule class=madda_normal>ـٰ</rule>ىَ فَ<rule class=ham_wasl>ٱ</rule>رۡهَب<rule class=madda_permissible>ُو</rule>نِ ٤٠',
    40, 1, 1, 7, 6, 2, 'false'
  );
  
  -- Ayah 41 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    48,
    'وَءَامِنُوا۟ بِمَاۤ أَنزَلۡتُ مُصَدِّقࣰا لِّمَا مَعَكُمۡ وَلَا تَكُونُوۤا۟ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُوا۟ بِـَٔایَـٰتِی ثَمَنࣰا قَلِیلࣰا وَإِیَّـٰیَ فَٱتَّقُونِ',
    'وامنوا بما انزلت مصدقا لما معكم ولا تكونوا اول كافر به ولا تشتروا باياتي ثمنا قليلا واياي فاتقون',
    'وَءَامِنُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡتُ مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا مَعَكُمۡ وَلَا تَكُون<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوَّلَ كَافِ<rule class=iqlab>رِۭ</rule> <rule class=iqlab>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَلَا تَشۡتَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِى ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َإِيَّ<rule class=madda_normal>ـٰ</rule>ىَ فَ<rule class=ham_wasl>ٱ</rule>تَّق<rule class=madda_permissible>ُو</rule>نِ ٤١',
    41, 1, 1, 7, 6, 2, 'false'
  );
  
  -- Ayah 42 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    49,
    'وَلَا تَلۡبِسُوا۟ ٱلۡحَقَّ بِٱلۡبَـٰطِلِ وَتَكۡتُمُوا۟ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ',
    'ولا تلبسوا الحق بالباطل وتكتموا الحق وانتم تعلمون',
    'وَلَا تَلۡبِسُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَقَّ بِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ وَتَكۡتُمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 1, 1, 7, 6, 2, 'false'
  );
  
  -- Ayah 43 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    50,
    'وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرۡكَعُوا۟ مَعَ ٱلرَّ ٰ⁠كِعِینَ',
    'واقيموا الصلاة واتوا الزكاة واركعوا مع الراكعين',
    'وَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>رۡكَعُو<rule class=slnt>اۡ</rule> مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>كِع<rule class=madda_permissible>ِي</rule>نَ ٤٣',
    43, 1, 1, 7, 6, 2, 'false'
  );
  
  -- Ayah 44 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    51,
    '۞ أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَـٰبَۚ أَفَلَا تَعۡقِلُونَ',
    'اتامرون الناس بالبر وتنسون انفسكم وانتم تتلون الكتاب افلا تعقلون',
    '۞أَتَأۡمُرُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ بِ<rule class=ham_wasl>ٱ</rule>لۡبِرِّ وَتَ<rule class=ikhafa>نس</rule>َوۡنَ أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَتۡلُونَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ‌ۚ أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 1, 1, 7, 6, 3, 'false'
  );
  
  -- Ayah 45 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    52,
    'وَٱسۡتَعِینُوا۟ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِیرَةٌ إِلَّا عَلَى ٱلۡخَـٰشِعِینَ',
    'واستعينوا بالصبر والصلاة وانها لكبيرة الا على الخاشعين',
    'وَ<rule class=ham_wasl>ٱ</rule>سۡتَعِينُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=qalaqah>بۡ</rule>رِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َهَا لَكَبِيرَةٌ إِلَّا عَلَى <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>شِع<rule class=madda_permissible>ِي</rule>نَ ٤٥',
    45, 1, 1, 7, 6, 3, 'false'
  );
  
  -- Ayah 46 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    53,
    'ٱلَّذِینَ یَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ رَبِّهِمۡ وَأَنَّهُمۡ إِلَیۡهِ رَ ٰ⁠جِعُونَ',
    'الذين يظنون انهم ملاقو ربهم وانهم اليه راجعون',
    'ٱلَّذِينَ يَظُ<rule class=ghunnah>نّ</rule>ُونَ أَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلَ<rule class=madda_normal>ـٰ</rule>قُو<rule class=slnt>اۡ</rule> رَبِّهِمۡ وَأَ<rule class=ghunnah>نّ</rule>َهُمۡ إِلَيۡهِ ر<rule class=madda_normal>ٰ</rule>جِع<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 1, 1, 7, 6, 3, 'false'
  );
  
  -- Ayah 47 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    54,
    'یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱذۡكُرُوا۟ نِعۡمَتِیَ ٱلَّتِیۤ أَنۡعَمۡتُ عَلَیۡكُمۡ وَأَنِّی فَضَّلۡتُكُمۡ عَلَى ٱلۡعَـٰلَمِینَ',
    'يا بني اسرائيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم على العالمين',
    'يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَتِىَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَ<rule class=ghunnah>نّ</rule>ِى فَضَّلۡتُكُمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 1, 1, 7, 7, 3, 'false'
  );
  
  -- Ayah 48 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    55,
    'وَٱتَّقُوا۟ یَوۡمࣰا لَّا تَجۡزِی نَفۡسٌ عَن نَّفۡسࣲ شَیۡـࣰٔا وَلَا یُقۡبَلُ مِنۡهَا شَفَـٰعَةࣱ وَلَا یُؤۡخَذُ مِنۡهَا عَدۡلࣱ وَلَا هُمۡ یُنصَرُونَ',
    'واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها شفاعة ولا يؤخذ منها عدل ولا هم ينصرون',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> يَوۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَ<rule class=qalaqah>جۡ</rule>زِى نَفۡسٌ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ش</rule>َيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُ<rule class=qalaqah>قۡ</rule>بَلُ مِنۡهَا شَفَ<rule class=madda_normal>ـٰ</rule>عَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُؤۡخَذُ مِنۡهَا عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا هُمۡ يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 1, 1, 7, 7, 3, 'false'
  );
  
  -- Ayah 49 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    56,
    'وَإِذۡ نَجَّیۡنَـٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ یَسُومُونَكُمۡ سُوۤءَ ٱلۡعَذَابِ یُذَبِّحُونَ أَبۡنَاۤءَكُمۡ وَیَسۡتَحۡیُونَ نِسَاۤءَكُمۡۚ وَفِی ذَ ٰ⁠لِكُم بَلَاۤءࣱ مِّن رَّبِّكُمۡ عَظِیمࣱ',
    'واذ نجيناكم من ال فرعون يسومونكم سوء العذاب يذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم',
    'وَإِذۡ نَجَّيۡنَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ يُذَبِّحُونَ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ وَيَسۡتَحۡيُونَ نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ‌ۚ وَفِى ذ<rule class=madda_normal>ٰ</rule>لِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َل<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٤٩',
    49, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 50 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    57,
    'وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَیۡنَـٰكُمۡ وَأَغۡرَقۡنَاۤ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ',
    'واذ فرقنا بكم البحر فانجيناكم واغرقنا ال فرعون وانتم تنظرون',
    'وَإِذۡ فَرَ<rule class=qalaqah>قۡ</rule>نَا بِكُمُ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَ فَأَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ وَأَغۡرَ<rule class=qalaqah>قۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> ءَالَ فِرۡعَوۡنَ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 51 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    58,
    'وَإِذۡ وَ ٰ⁠عَدۡنَا مُوسَىٰۤ أَرۡبَعِینَ لَیۡلَةࣰ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَـٰلِمُونَ',
    'واذ واعدنا موسى اربعين ليلة ثم اتخذتم العجل من بعده وانتم ظالمون',
    'وَإِذۡ و<rule class=madda_normal>ٰ</rule>عَ<rule class=qalaqah>دۡ</rule>نَا مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَرۡبَعِينَ لَيۡلَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>تَّخَذۡتُمُ <rule class=ham_wasl>ٱ</rule>لۡعِ<rule class=qalaqah>جۡ</rule>لَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> وَأَ<rule class=ikhafa>نت</rule>ُمۡ ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 52 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    59,
    'ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَ ٰ⁠لِكَ لَعَلَّكُمۡ تَشۡكُرُونَ',
    'ثم عفونا عنكم من بعد ذلك لعلكم تشكرون',
    'ثُ<rule class=ghunnah>مّ</rule>َ عَفَوۡنَا عَ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ لَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 53 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    60,
    'وَإِذۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ',
    'واذ اتينا موسى الكتاب والفرقان لعلكم تهتدون',
    'وَإِذۡ ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 54 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    61,
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ یَـٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوۤا۟ إِلَىٰ بَارِىِٕكُمۡ فَٱقۡتُلُوۤا۟ أَنفُسَكُمۡ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ عِندَ بَارِىِٕكُمۡ فَتَابَ عَلَیۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ',
    'واذ قال موسى لقومه يا قوم انكم ظلمتم انفسكم باتخاذكم العجل فتوبوا الى بارئكم فاقتلوا انفسكم ذلكم خير لكم عند بارئكم فتاب عليكم انه هو التواب الرحيم',
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِه<rule class=madda_normal>ِۦ</rule> يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ghunnah>نّ</rule>َكُمۡ ظَلَمۡتُمۡ أَ<rule class=ikhafa>نف</rule>ُسَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>تِّخَاذِكُمُ <rule class=ham_wasl>ٱ</rule>لۡعِ<rule class=qalaqah>جۡ</rule>لَ فَتُوب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ بَارِئِكُمۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ عِ<rule class=ikhafa>ند</rule>َ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوَّابُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٥٤',
    54, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 55 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    62,
    'وَإِذۡ قُلۡتُمۡ یَـٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةࣰ فَأَخَذَتۡكُمُ ٱلصَّـٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ',
    'واذ قلتم يا موسى لن نؤمن لك حتى نرى الله جهرة فاخذتكم الصاعقة وانتم تنظرون',
    'وَإِذۡ قُلۡتُمۡ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى <rule class=ham_wasl>ٱ</rule>للَّهَ جَهۡرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َأَخَذَتۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>عِقَةُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 56 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    63,
    'ثُمَّ بَعَثۡنَـٰكُم مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ',
    'ثم بعثناكم من بعد موتكم لعلكم تشكرون',
    'ثُ<rule class=ghunnah>مّ</rule>َ بَعَثۡنَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 57 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    64,
    'وَظَلَّلۡنَا عَلَیۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَیۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡۚ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'وظللنا عليكم الغمام وانزلنا عليكم المن والسلوى كلوا من طيبات ما رزقناكم وما ظلمونا ولكن كانوا انفسهم يظلمون',
    'وَظَلَّلۡنَا عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡغَمَامَ وَأَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=ghunnah>نّ</rule>َ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلۡوَىٰ‌ۖ كُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=madda_normal>ـٰ</rule>تِ مَا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ وَمَا ظَلَمُونَا وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 1, 1, 8, 7, 3, 'false'
  );
  
  -- Ayah 58 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    65,
    'وَإِذۡ قُلۡنَا ٱدۡخُلُوا۟ هَـٰذِهِ ٱلۡقَرۡیَةَ فَكُلُوا۟ مِنۡهَا حَیۡثُ شِئۡتُمۡ رَغَدࣰا وَٱدۡخُلُوا۟ ٱلۡبَابَ سُجَّدࣰا وَقُولُوا۟ حِطَّةࣱ نَّغۡفِرۡ لَكُمۡ خَطَـٰیَـٰكُمۡۚ وَسَنَزِیدُ ٱلۡمُحۡسِنِینَ',
    'واذ قلنا ادخلوا هذه القرية فكلوا منها حيث شئتم رغدا وادخلوا الباب سجدا وقولوا حطة نغفر لكم خطاياكم وسنزيد المحسنين',
    'وَإِذۡ قُلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةَ فَكُلُو<rule class=slnt>اۡ</rule> مِنۡهَا حَيۡثُ شِئۡتُمۡ رَغَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡبَابَ سُجَّ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َقُولُو<rule class=slnt>اۡ</rule> حِطَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ن</rule>َّغۡفِرۡ لَكُمۡ خَطَ<rule class=madda_normal>ـٰ</rule>يَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۚ وَسَنَزِيدُ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 1, 1, 9, 7, 3, 'false'
  );
  
  -- Ayah 59 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    66,
    'فَبَدَّلَ ٱلَّذِینَ ظَلَمُوا۟ قَوۡلًا غَیۡرَ ٱلَّذِی قِیلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِینَ ظَلَمُوا۟ رِجۡزࣰا مِّنَ ٱلسَّمَاۤءِ بِمَا كَانُوا۟ یَفۡسُقُونَ',
    'فبدل الذين ظلموا قولا غير الذي قيل لهم فانزلنا على الذين ظلموا رجزا من السماء بما كانوا يفسقون',
    'فَبَدَّلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> قَوۡلاً غَيۡرَ <rule class=ham_wasl>ٱ</rule>لَّذِى قِيلَ لَهُمۡ فَأَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> رِ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>زًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡسُق<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 1, 1, 9, 7, 3, 'false'
  );
  
  -- Ayah 60 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    67,
    '۞ وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَیۡنࣰاۖ قَدۡ عَلِمَ كُلُّ أُنَاسࣲ مَّشۡرَبَهُمۡۖ كُلُوا۟ وَٱشۡرَبُوا۟ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ',
    'واذ استسقى موسى لقومه فقلنا اضرب بعصاك الحجر فانفجرت منه اثنتا عشرة عينا قد علم كل اناس مشربهم كلوا واشربوا من رزق الله ولا تعثوا في الارض مفسدين',
    '۞وَإِذِ <rule class=ham_wasl>ٱ</rule>سۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِه<rule class=madda_normal>ِۦ</rule> فَقُلۡنَا <rule class=ham_wasl>ٱ</rule>ضۡرِب بِّعَصَاكَ <rule class=ham_wasl>ٱ</rule>لۡحَجَرَ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>َجَرَتۡ مِنۡهُ <rule class=ham_wasl>ٱ</rule>ثۡنَتَا عَشۡرَةَ عَيۡ<rule class=ikhafa>نًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> عَلِمَ كُلُّ أُنَا<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّشۡرَبَهُمۡ‌ۖ كُلُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>شۡرَبُو<rule class=slnt>اۡ</rule> م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّزۡقِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا تَعۡثَوۡ<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٦٠',
    60, 1, 1, 9, 8, 4, 'false'
  );
  
  -- Ayah 61 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    68,
    'وَإِذۡ قُلۡتُمۡ یَـٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامࣲ وَ ٰ⁠حِدࣲ فَٱدۡعُ لَنَا رَبَّكَ یُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّاۤىِٕهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِی هُوَ أَدۡنَىٰ بِٱلَّذِی هُوَ خَیۡرٌۚ ٱهۡبِطُوا۟ مِصۡرࣰا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَیۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَاۤءُو بِغَضَبࣲ مِّنَ ٱللَّهِۗ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ كَانُوا۟ یَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَیَقۡتُلُونَ ٱلنَّبِیِّـۧنَ بِغَیۡرِ ٱلۡحَقِّۗ ذَ ٰ⁠لِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ یَعۡتَدُونَ',
    'واذ قلتم يا موسى لن نصبر على طعام واحد فادع لنا ربك يخرج لنا مما تنبت الارض من بقلها وقثائها وفومها وعدسها وبصلها قال اتستبدلون الذي هو ادنى بالذي هو خير اهبطوا مصرا فان لكم ما سالتم وضربت عليهم الذلة والمسكنة وباءوا بغضب من الله ذلك بانهم كانوا يكفرون بايات الله ويقتلون النبيين بغير الحق ذلك بما عصوا وكانوا يعتدون',
    'وَإِذۡ قُلۡتُمۡ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّصۡبِرَ عَلَىٰ طَعَا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ لَنَا رَبَّكَ يُخۡرِ<rule class=qalaqah>جۡ</rule> لَنَا مِ<rule class=ghunnah>مّ</rule>َا تُ<rule class=iqlab>نۢب</rule>ِتُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َ<rule class=qalaqah>قۡ</rule>لِهَا وَقِثّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا‌ۖ قَالَ أَتَسۡتَ<rule class=qalaqah>بۡ</rule>دِلُونَ <rule class=ham_wasl>ٱ</rule>لَّذِى هُوَ أَ<rule class=qalaqah>دۡ</rule>نَىٰ بِ<rule class=ham_wasl>ٱ</rule>لَّذِى هُوَ خَيۡرٌ‌ۚ <rule class=ham_wasl>ٱ</rule>هۡبِطُو<rule class=slnt>اۡ</rule> مِصۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا سَأَلۡتُمۡ‌ۗ وَضُرِبَتۡ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّلَّةُ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسۡكَنَةُ وَب<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو بِغَضَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> يَكۡفُرُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَ<rule class=qalaqah>قۡ</rule>تُلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۗ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِمَا عَصَو<rule class=slnt>اۡ</rule> وَّكَانُو<rule class=slnt>اۡ</rule> يَعۡتَد<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 1, 1, 9, 8, 4, 'false'
  );
  
  -- Ayah 62 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    69,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَادُوا۟ وَٱلنَّصَـٰرَىٰ وَٱلصَّـٰبِـِٔینَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَعَمِلَ صَـٰلِحࣰا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'ان الذين امنوا والذين هادوا والنصارى والصابئين من امن بالله واليوم الاخر وعمل صالحا فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هَادُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَىٰ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِــِٔينَ مَنۡ ءَامَنَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َلَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رُهُمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 1, 1, 10, 9, 4, 'false'
  );
  
  -- Ayah 63 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    70,
    'وَإِذۡ أَخَذۡنَا مِیثَـٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُوا۟ مَاۤ ءَاتَیۡنَـٰكُم بِقُوَّةࣲ وَٱذۡكُرُوا۟ مَا فِیهِ لَعَلَّكُمۡ تَتَّقُونَ',
    'واذ اخذنا ميثاقكم ورفعنا فوقكم الطور خذوا ما اتيناكم بقوة واذكروا ما فيه لعلكم تتقون',
    'وَإِذۡ أَخَذۡنَا مِيثَ<rule class=madda_normal>ـٰ</rule>قَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّورَ خُذُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِقُوَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> مَا فِيهِ لَعَلَّكُمۡ تَتَّق<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 1, 1, 10, 9, 4, 'false'
  );
  
  -- Ayah 64 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    71,
    'ثُمَّ تَوَلَّیۡتُم مِّنۢ بَعۡدِ ذَ ٰ⁠لِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ ٱلۡخَـٰسِرِینَ',
    'ثم توليتم من بعد ذلك فلولا فضل الله عليكم ورحمته لكنتم من الخاسرين',
    'ثُ<rule class=ghunnah>مّ</rule>َ تَوَلَّيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۖ فَلَوۡلَا فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُ<rule class=madda_normal>ۥ</rule> لَكُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٦٤',
    64, 1, 1, 10, 9, 4, 'false'
  );
  
  -- Ayah 65 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    72,
    'وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِینَ ٱعۡتَدَوۡا۟ مِنكُمۡ فِی ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُوا۟ قِرَدَةً خَـٰسِـِٔینَ',
    'ولقد علمتم الذين اعتدوا منكم في السبت فقلنا لهم كونوا قردة خاسئين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> عَلِمۡتُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>عۡتَدَوۡ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=qalaqah>بۡ</rule>تِ فَقُلۡنَا لَهُمۡ كُونُو<rule class=slnt>اۡ</rule> قِرَدَةً خَ<rule class=madda_normal>ـٰ</rule>سِــٔ<rule class=madda_permissible>ِي</rule>نَ ٦٥',
    65, 1, 1, 10, 9, 4, 'false'
  );
  
  -- Ayah 66 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    73,
    'فَجَعَلۡنَـٰهَا نَكَـٰلࣰا لِّمَا بَیۡنَ یَدَیۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةࣰ لِّلۡمُتَّقِینَ',
    'فجعلناها نكالا لما بين يديها وما خلفها وموعظة للمتقين',
    'فَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هَا نَكَ<rule class=madda_normal>ـٰ</rule>ل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَيۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 1, 1, 10, 9, 4, 'false'
  );
  
  -- Ayah 67 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    74,
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦۤ إِنَّ ٱللَّهَ یَأۡمُرُكُمۡ أَن تَذۡبَحُوا۟ بَقَرَةࣰۖ قَالُوۤا۟ أَتَتَّخِذُنَا هُزُوࣰاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَـٰهِلِینَ',
    'واذ قال موسى لقومه ان الله يامركم ان تذبحوا بقرة قالوا اتتخذنا هزوا قال اعوذ بالله ان اكون من الجاهلين',
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَأۡمُرُكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َذۡبَحُو<rule class=slnt>اۡ</rule> بَقَرَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَتَتَّخِذُنَا هُزُ<rule class=ikhafa>وًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ أَعُوذُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ أَنۡ أَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِل<rule class=madda_permissible>ِي</rule>نَ ٦٧',
    67, 1, 1, 10, 9, 4, 'false'
  );
  
  -- Ayah 68 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    75,
    'قَالُوا۟ ٱدۡعُ لَنَا رَبَّكَ یُبَیِّن لَّنَا مَا هِیَۚ قَالَ إِنَّهُۥ یَقُولُ إِنَّهَا بَقَرَةࣱ لَّا فَارِضࣱ وَلَا بِكۡرٌ عَوَانُۢ بَیۡنَ ذَ ٰ⁠لِكَۖ فَٱفۡعَلُوا۟ مَا تُؤۡمَرُونَ',
    'قالوا ادع لنا ربك يبين لنا ما هي قال انه يقول انها بقرة لا فارض ولا بكر عوان بين ذلك فافعلوا ما تؤمرون',
    'قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ لَنَا رَبَّكَ يُبَيّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّنَا مَا هِىَ‌ۚ قَالَ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَقُولُ إِ<rule class=ghunnah>نّ</rule>َهَا بَقَرَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا فَارِ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا بِكۡرٌ عَوَا<rule class=iqlab>نُۢ</rule> <rule class=iqlab>ب</rule>َيۡنَ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>فۡعَلُو<rule class=slnt>اۡ</rule> مَا تُؤۡمَر<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 1, 1, 10, 9, 4, 'false'
  );
  
  -- Ayah 69 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    76,
    'قَالُوا۟ ٱدۡعُ لَنَا رَبَّكَ یُبَیِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ یَقُولُ إِنَّهَا بَقَرَةࣱ صَفۡرَاۤءُ فَاقِعࣱ لَّوۡنُهَا تَسُرُّ ٱلنَّـٰظِرِینَ',
    'قالوا ادع لنا ربك يبين لنا ما لونها قال انه يقول انها بقرة صفراء فاقع لونها تسر الناظرين',
    'قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ لَنَا رَبَّكَ يُبَيّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّنَا مَا لَوۡنُهَا‌ۚ قَالَ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَقُولُ إِ<rule class=ghunnah>نّ</rule>َهَا بَقَرَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ص</rule>َفۡر<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فَاقِ<rule class=idgham_wo_ghunnah>عٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡنُهَا تَسُرُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>ظِر<rule class=madda_permissible>ِي</rule>نَ ٦٩',
    69, 1, 1, 10, 9, 4, 'false'
  );
  
  -- Ayah 70 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    77,
    'قَالُوا۟ ٱدۡعُ لَنَا رَبَّكَ یُبَیِّن لَّنَا مَا هِیَ إِنَّ ٱلۡبَقَرَ تَشَـٰبَهَ عَلَیۡنَا وَإِنَّاۤ إِن شَاۤءَ ٱللَّهُ لَمُهۡتَدُونَ',
    'قالوا ادع لنا ربك يبين لنا ما هي ان البقر تشابه علينا وانا ان شاء الله لمهتدون',
    'قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ لَنَا رَبَّكَ يُبَيّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّنَا مَا هِىَ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡبَقَرَ تَشَ<rule class=madda_normal>ـٰ</rule>بَهَ عَلَيۡنَا وَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَمُهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 1, 1, 11, 9, 4, 'false'
  );
  
  -- Ayah 71 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    78,
    'قَالَ إِنَّهُۥ یَقُولُ إِنَّهَا بَقَرَةࣱ لَّا ذَلُولࣱ تُثِیرُ ٱلۡأَرۡضَ وَلَا تَسۡقِی ٱلۡحَرۡثَ مُسَلَّمَةࣱ لَّا شِیَةَ فِیهَاۚ قَالُوا۟ ٱلۡـَٔـٰنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُوا۟ یَفۡعَلُونَ',
    'قال انه يقول انها بقرة لا ذلول تثير الارض ولا تسقي الحرث مسلمة لا شية فيها قالوا الان جئت بالحق فذبحوها وما كادوا يفعلون',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَقُولُ إِ<rule class=ghunnah>نّ</rule>َهَا بَقَرَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا ذَلُو<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ت</rule>ُثِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَلَا تَسۡقِى <rule class=ham_wasl>ٱ</rule>لۡحَرۡثَ مُسَلَّمَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا شِيَةَ فِيهَا‌ۚ قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡـَٔ<rule class=madda_normal>ـٰ</rule>نَ جِئۡتَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ فَذَبَحُوهَا وَمَا كَادُو<rule class=slnt>اۡ</rule> يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 1, 1, 11, 9, 4, 'false'
  );
  
  -- Ayah 72 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    79,
    'وَإِذۡ قَتَلۡتُمۡ نَفۡسࣰا فَٱدَّ ٰ⁠رَ ٰٔۡ ⁠تُمۡ فِیهَاۖ وَٱللَّهُ مُخۡرِجࣱ مَّا كُنتُمۡ تَكۡتُمُونَ',
    'واذ قتلتم نفسا فاداراتم فيها والله مخرج ما كنتم تكتمون',
    'وَإِذۡ قَتَلۡتُمۡ نَفۡ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>دّ<rule class=madda_normal>ٰ</rule>رٰٔۡتُمۡ فِيهَا‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ مُخۡرِ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡتُم<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 1, 1, 11, 10, 4, 'false'
  );
  
  -- Ayah 73 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    80,
    'فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَ ٰ⁠لِكَ یُحۡیِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَیُرِیكُمۡ ءَایَـٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ',
    'فقلنا اضربوه ببعضها كذلك يحيي الله الموتى ويريكم اياته لعلكم تعقلون',
    'فَقُلۡنَا <rule class=ham_wasl>ٱ</rule>ضۡرِبُوهُ بِبَعۡضِهَا‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُحۡىِ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ وَيُرِيكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> لَعَلَّكُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 1, 1, 11, 10, 4, 'false'
  );
  
  -- Ayah 74 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    81,
    'ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَ ٰ⁠لِكَ فَهِیَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةࣰۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا یَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَـٰرُۚ وَإِنَّ مِنۡهَا لَمَا یَشَّقَّقُ فَیَخۡرُجُ مِنۡهُ ٱلۡمَاۤءُۚ وَإِنَّ مِنۡهَا لَمَا یَهۡبِطُ مِنۡ خَشۡیَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ',
    'ثم قست قلوبكم من بعد ذلك فهي كالحجارة او اشد قسوة وان من الحجارة لما يتفجر منه الانهار وان منها لما يشقق فيخرج منه الماء وان منها لما يهبط من خشية الله وما الله بغافل عما تعملون',
    'ثُ<rule class=ghunnah>مّ</rule>َ قَسَتۡ قُلُوبُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَهِىَ كَ<rule class=ham_wasl>ٱ</rule>لۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحِجَارَةِ لَمَا يَتَفَجَّرُ مِنۡهُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ مِنۡهَا لَمَا يَشَّقَّقُ فَيَخۡرُجُ مِنۡهُ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ مِنۡهَا لَمَا يَهۡبِطُ مِنۡ خَشۡيَةِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>للَّهُ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٧٤',
    74, 1, 1, 11, 10, 4, 'false'
  );
  
  -- Ayah 75 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    82,
    '۞ أَفَتَطۡمَعُونَ أَن یُؤۡمِنُوا۟ لَكُمۡ وَقَدۡ كَانَ فَرِیقࣱ مِّنۡهُمۡ یَسۡمَعُونَ كَلَـٰمَ ٱللَّهِ ثُمَّ یُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ یَعۡلَمُونَ',
    'افتطمعون ان يؤمنوا لكم وقد كان فريق منهم يسمعون كلام الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون',
    '۞أَفَتَ<rule class=qalaqah>طۡ</rule>مَعُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُو<rule class=slnt>اۡ</rule> لَكُمۡ وَقَ<rule class=qalaqah>دۡ</rule> كَانَ فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ يَسۡمَعُونَ كَلَ<rule class=madda_normal>ـٰ</rule>مَ <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ يُحَرِّفُونَهُ<rule class=madda_normal>ۥ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا عَقَلُوهُ وَهُمۡ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 1, 1, 11, 10, 5, 'false'
  );
  
  -- Ayah 76 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    83,
    'وَإِذَا لَقُوا۟ ٱلَّذِینَ ءَامَنُوا۟ قَالُوۤا۟ ءَامَنَّا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضࣲ قَالُوۤا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَیۡكُمۡ لِیُحَاۤجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ',
    'واذا لقوا الذين امنوا قالوا امنا واذا خلا بعضهم الى بعض قالوا اتحدثونهم بما فتح الله عليكم ليحاجوكم به عند ربكم افلا تعقلون',
    'وَإِذَا لَقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَتُحَدِّثُونَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا فَتَحَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡكُمۡ لِيُح<rule class=madda_necessary>َا</rule>ٓجُّوك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> عِ<rule class=ikhafa>ند</rule>َ رَبِّكُمۡ‌ۚ أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٧٦',
    76, 1, 1, 11, 10, 5, 'false'
  );
  
  -- Ayah 77 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    84,
    'أَوَلَا یَعۡلَمُونَ أَنَّ ٱللَّهَ یَعۡلَمُ مَا یُسِرُّونَ وَمَا یُعۡلِنُونَ',
    'اولا يعلمون ان الله يعلم ما يسرون وما يعلنون',
    'أَوَلَا يَعۡلَمُونَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِن<rule class=madda_permissible>ُو</rule>نَ ٧٧',
    77, 1, 1, 12, 10, 5, 'false'
  );
  
  -- Ayah 78 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    85,
    'وَمِنۡهُمۡ أُمِّیُّونَ لَا یَعۡلَمُونَ ٱلۡكِتَـٰبَ إِلَّاۤ أَمَانِیَّ وَإِنۡ هُمۡ إِلَّا یَظُنُّونَ',
    'ومنهم اميون لا يعلمون الكتاب الا اماني وان هم الا يظنون',
    'وَمِنۡهُمۡ أُ<rule class=ghunnah>مّ</rule>ِيُّونَ لَا يَعۡلَمُونَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَمَانِىَّ وَإِنۡ هُمۡ إِلَّا يَظُ<rule class=ghunnah>نّ</rule><rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 1, 1, 12, 10, 5, 'false'
  );
  
  -- Ayah 79 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    86,
    'فَوَیۡلࣱ لِّلَّذِینَ یَكۡتُبُونَ ٱلۡكِتَـٰبَ بِأَیۡدِیهِمۡ ثُمَّ یَقُولُونَ هَـٰذَا مِنۡ عِندِ ٱللَّهِ لِیَشۡتَرُوا۟ بِهِۦ ثَمَنࣰا قَلِیلࣰاۖ فَوَیۡلࣱ لَّهُم مِّمَّا كَتَبَتۡ أَیۡدِیهِمۡ وَوَیۡلࣱ لَّهُم مِّمَّا یَكۡسِبُونَ',
    'فويل للذين يكتبون الكتاب بايديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا فويل لهم مما كتبت ايديهم وويل لهم مما يكسبون',
    'فَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ يَكۡتُبُونَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِأَيۡدِيهِمۡ ثُ<rule class=ghunnah>مّ</rule>َ يَقُولُونَ هَ<rule class=madda_normal>ـٰ</rule>ذَا مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ لِيَشۡتَرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيل<rule class=ikhafa>اً‌ۖ</rule> <rule class=ikhafa>ف</rule>َوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا كَتَبَتۡ أَيۡدِيهِمۡ وَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 1, 1, 12, 10, 5, 'false'
  );
  
  -- Ayah 80 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    87,
    'وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّاۤ أَیَّامࣰا مَّعۡدُودَةࣰۚ قُلۡ أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدࣰا فَلَن یُخۡلِفَ ٱللَّهُ عَهۡدَهُۥۤۖ أَمۡ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ',
    'وقالوا لن تمسنا النار الا اياما معدودة قل اتخذتم عند الله عهدا فلن يخلف الله عهده ام تقولون على الله ما لا تعلمون',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمَسَّنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَيَّا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّعۡدُودَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ق</rule>ُلۡ أَتَّخَذۡتُمۡ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ عَهۡ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡلِفَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَهۡدَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> أَمۡ تَقُولُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 1, 1, 12, 10, 5, 'false'
  );
  
  -- Ayah 81 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    88,
    'بَلَىٰۚ مَن كَسَبَ سَیِّئَةࣰ وَأَحَـٰطَتۡ بِهِۦ خَطِیۤـَٔتُهُۥ فَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'بلى من كسب سيئة واحاطت به خطيئته فاولئك اصحاب النار هم فيها خالدون',
    'بَلَىٰ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َسَبَ سَيِّئَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَحَ<rule class=madda_normal>ـٰ</rule>طَتۡ بِه<rule class=madda_normal>ِۦ</rule> خَطِ<rule class=madda_obligatory_mottasel>يٓ</rule>ــَٔتُهُ<rule class=madda_normal>ۥ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 1, 1, 12, 10, 5, 'false'
  );
  
  -- Ayah 82 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    89,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'والذين امنوا وعملوا الصالحات اولئك اصحاب الجنة هم فيها خالدون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 1, 1, 12, 10, 5, 'false'
  );
  
  -- Ayah 83 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    90,
    'وَإِذۡ أَخَذۡنَا مِیثَـٰقَ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَ ٰ⁠لِدَیۡنِ إِحۡسَانࣰا وَذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَقُولُوا۟ لِلنَّاسِ حُسۡنࣰا وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّیۡتُمۡ إِلَّا قَلِیلࣰا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ',
    'واذ اخذنا ميثاق بني اسرائيل لا تعبدون الا الله وبالوالدين احسانا وذي القربى واليتامى والمساكين وقولوا للناس حسنا واقيموا الصلاة واتوا الزكاة ثم توليتم الا قليلا منكم وانتم معرضون',
    'وَإِذۡ أَخَذۡنَا مِيثَ<rule class=madda_normal>ـٰ</rule>قَ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ لَا تَعۡبُدُونَ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَ وَبِ<rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِدَيۡنِ إِحۡسَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َذِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينِ وَقُولُو<rule class=slnt>اۡ</rule> لِل<rule class=ghunnah>نّ</rule>َاسِ حُسۡ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ ثُ<rule class=ghunnah>مّ</rule>َ تَوَلَّيۡتُمۡ إِلَّا قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ وَأَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٨٣',
    83, 1, 1, 12, 11, 5, 'false'
  );
  
  -- Ayah 84 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    91,
    'وَإِذۡ أَخَذۡنَا مِیثَـٰقَكُمۡ لَا تَسۡفِكُونَ دِمَاۤءَكُمۡ وَلَا تُخۡرِجُونَ أَنفُسَكُم مِّن دِیَـٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ',
    'واذ اخذنا ميثاقكم لا تسفكون دماءكم ولا تخرجون انفسكم من دياركم ثم اقررتم وانتم تشهدون',
    'وَإِذۡ أَخَذۡنَا مِيثَ<rule class=madda_normal>ـٰ</rule>قَكُمۡ لَا تَسۡفِكُونَ دِم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ وَلَا تُخۡرِجُونَ أَ<rule class=ikhafa>نف</rule>ُسَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=qalaqah>قۡ</rule>رَرۡتُمۡ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَشۡهَد<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 1, 1, 13, 11, 5, 'false'
  );
  
  -- Ayah 85 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    92,
    'ثُمَّ أَنتُمۡ هَـٰۤؤُلَاۤءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِیقࣰا مِّنكُم مِّن دِیَـٰرِهِمۡ تَظَـٰهَرُونَ عَلَیۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰ⁠نِ وَإِن یَأۡتُوكُمۡ أُسَـٰرَىٰ تُفَـٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَیۡكُمۡ إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَـٰبِ وَتَكۡفُرُونَ بِبَعۡضࣲۚ فَمَا جَزَاۤءُ مَن یَفۡعَلُ ذَ ٰ⁠لِكَ مِنكُمۡ إِلَّا خِزۡیࣱ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ یُرَدُّونَ إِلَىٰۤ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ',
    'ثم انتم هؤلاء تقتلون انفسكم وتخرجون فريقا منكم من ديارهم تظاهرون عليهم بالاثم والعدوان وان ياتوكم اسارى تفادوهم وهو محرم عليكم اخراجهم افتؤمنون ببعض الكتاب وتكفرون ببعض فما جزاء من يفعل ذلك منكم الا خزي في الحياة الدنيا ويوم القيامة يردون الى اشد العذاب وما الله بغافل عما تعملون',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=ikhafa>نت</rule>ُمۡ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ تَ<rule class=qalaqah>قۡ</rule>تُلُونَ أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ وَتُخۡرِجُونَ فَرِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ تَظَ<rule class=madda_normal>ـٰ</rule>هَرُونَ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَ<rule class=ham_wasl>ٱ</rule>لۡعُ<rule class=qalaqah>دۡ</rule>و<rule class=madda_normal>ٰ</rule>نِ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتُوكُمۡ أُسَ<rule class=madda_normal>ـٰ</rule>رَىٰ تُفَ<rule class=madda_normal>ـٰ</rule>دُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَيۡكُمۡ إِخۡرَاجُهُمۡ‌ۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَتَكۡفُرُونَ بِبَعۡ<rule class=ikhafa>ضٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َمَا جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلُ ذ<rule class=madda_normal>ٰ</rule>لِكَ مِ<rule class=ikhafa>نك</rule>ُمۡ إِلَّا خِزۡ<rule class=ikhafa>ىٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ يُرَدُّونَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَشَدِّ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>للَّهُ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٨٥',
    85, 1, 1, 13, 11, 5, 'false'
  );
  
  -- Ayah 86 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    93,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا بِٱلۡـَٔاخِرَةِۖ فَلَا یُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ یُنصَرُونَ',
    'اولئك الذين اشتروا الحياة الدنيا بالاخرة فلا يخفف عنهم العذاب ولا هم ينصرون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>شۡتَرَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ فَلَا يُخَفَّفُ عَنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ وَلَا هُمۡ يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٨٦',
    86, 1, 1, 13, 11, 5, 'false'
  );
  
  -- Ayah 87 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    94,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَقَفَّیۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَیۡنَا عِیسَى ٱبۡنَ مَرۡیَمَ ٱلۡبَیِّنَـٰتِ وَأَیَّدۡنَـٰهُ بِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَاۤءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰۤ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ فَفَرِیقࣰا كَذَّبۡتُمۡ وَفَرِیقࣰا تَقۡتُلُونَ',
    'ولقد اتينا موسى الكتاب وقفينا من بعده بالرسل واتينا عيسى ابن مريم البينات وايدناه بروح القدس افكلما جاءكم رسول بما لا تهوى انفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَقَفَّيۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلِ‌ۖ وَءَاتَيۡنَا عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَأَيَّ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ بِرُوحِ <rule class=ham_wasl>ٱ</rule>لۡقُدُسِ‌ۗ أَفَكُلَّمَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ رَسُو<rule class=iqlab>لُۢ</rule> <rule class=iqlab>ب</rule>ِمَا لَا تَهۡوَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسُكُمُ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرۡتُمۡ فَفَرِي<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ك</rule>َذَّ<rule class=qalaqah>بۡ</rule>تُمۡ وَفَرِي<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>قۡ</rule>تُل<rule class=madda_permissible>ُو</rule>نَ ٨٧',
    87, 1, 1, 13, 12, 5, 'false'
  );
  
  -- Ayah 88 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    95,
    'وَقَالُوا۟ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِیلࣰا مَّا یُؤۡمِنُونَ',
    'وقالوا قلوبنا غلف بل لعنهم الله بكفرهم فقليلا ما يؤمنون',
    'وَقَالُو<rule class=slnt>اۡ</rule> قُلُوبُنَا غُلۡ<rule class=iqlab>فُۢ‌ۚ</rule> <rule class=iqlab>ب</rule>َل لَّعَنَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِكُفۡرِهِمۡ فَقَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 1, 1, 13, 12, 5, 'false'
  );
  
  -- Ayah 89 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    96,
    'وَلَمَّا جَاۤءَهُمۡ كِتَـٰبࣱ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمۡ وَكَانُوا۟ مِن قَبۡلُ یَسۡتَفۡتِحُونَ عَلَى ٱلَّذِینَ كَفَرُوا۟ فَلَمَّا جَاۤءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَـٰفِرِینَ',
    'ولما جاءهم كتاب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون على الذين كفروا فلما جاءهم ما عرفوا كفروا به فلعنة الله على الكافرين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ مُصَدِّ<rule class=idgham_wo_ghunnah>قٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا مَعَهُمۡ وَكَانُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ يَسۡتَفۡتِحُونَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا عَرَفُو<rule class=slnt>اۡ</rule> كَفَرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule>‌ۚ فَلَعۡنَةُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٨٩',
    89, 1, 1, 14, 12, 5, 'false'
  );
  
  -- Ayah 90 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    97,
    'بِئۡسَمَا ٱشۡتَرَوۡا۟ بِهِۦۤ أَنفُسَهُمۡ أَن یَكۡفُرُوا۟ بِمَاۤ أَنزَلَ ٱللَّهُ بَغۡیًا أَن یُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۖ فَبَاۤءُو بِغَضَبٍ عَلَىٰ غَضَبࣲۚ وَلِلۡكَـٰفِرِینَ عَذَابࣱ مُّهِینࣱ',
    'بئسما اشتروا به انفسهم ان يكفروا بما انزل الله بغيا ان ينزل الله من فضله على من يشاء من عباده فباءوا بغضب على غضب وللكافرين عذاب مهين',
    'بِئۡسَمَا <rule class=ham_wasl>ٱ</rule>شۡتَرَوۡ<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ بَغۡيًا أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُنَزِّلَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> عَلَىٰ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَب<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو بِغَضَبٍ عَلَىٰ غَضَ<rule class=idgham_ghunnah>بٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّه<rule class=madda_permissible>ِي</rule>نٌ ٩٠',
    90, 1, 1, 14, 12, 5, 'false'
  );
  
  -- Ayah 91 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    98,
    'وَإِذَا قِیلَ لَهُمۡ ءَامِنُوا۟ بِمَاۤ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤۡمِنُ بِمَاۤ أُنزِلَ عَلَیۡنَا وَیَكۡفُرُونَ بِمَا وَرَاۤءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقࣰا لِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِیَاۤءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِینَ',
    'واذا قيل لهم امنوا بما انزل الله قالوا نؤمن بما انزل علينا ويكفرون بما وراءه وهو الحق مصدقا لما معهم قل فلم تقتلون انبياء الله من قبل ان كنتم مؤمنين',
    'وَإِذَا قِيلَ لَهُمۡ ءَامِنُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ قَالُو<rule class=slnt>اۡ</rule> نُؤۡمِنُ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡنَا وَيَكۡفُرُونَ بِمَا وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_normal>ۥ</rule> وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا مَعَهُمۡ‌ۗ قُلۡ فَلِمَ تَ<rule class=qalaqah>قۡ</rule>تُلُونَ أَ<rule class=iqlab>نۢب</rule>ِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 1, 1, 14, 12, 5, 'false'
  );
  
  -- Ayah 92 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    99,
    '۞ وَلَقَدۡ جَاۤءَكُم مُّوسَىٰ بِٱلۡبَیِّنَـٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَـٰلِمُونَ',
    'ولقد جاءكم موسى بالبينات ثم اتخذتم العجل من بعده وانتم ظالمون',
    '۞وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوسَىٰ بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>تَّخَذۡتُمُ <rule class=ham_wasl>ٱ</rule>لۡعِ<rule class=qalaqah>جۡ</rule>لَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> وَأَ<rule class=ikhafa>نت</rule>ُمۡ ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٩٢',
    92, 1, 1, 14, 12, 6, 'false'
  );
  
  -- Ayah 93 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    100,
    'وَإِذۡ أَخَذۡنَا مِیثَـٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُوا۟ مَاۤ ءَاتَیۡنَـٰكُم بِقُوَّةࣲ وَٱسۡمَعُوا۟ۖ قَالُوا۟ سَمِعۡنَا وَعَصَیۡنَا وَأُشۡرِبُوا۟ فِی قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا یَأۡمُرُكُم بِهِۦۤ إِیمَـٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِینَ',
    'واذ اخذنا ميثاقكم ورفعنا فوقكم الطور خذوا ما اتيناكم بقوة واسمعوا قالوا سمعنا وعصينا واشربوا في قلوبهم العجل بكفرهم قل بئسما يامركم به ايمانكم ان كنتم مؤمنين',
    'وَإِذۡ أَخَذۡنَا مِيثَ<rule class=madda_normal>ـٰ</rule>قَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّورَ خُذُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِقُوَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>سۡمَعُو<rule class=slnt>اۡ‌ۖ</rule> قَالُو<rule class=slnt>اۡ</rule> سَمِعۡنَا وَعَصَيۡنَا وَأُشۡرِبُو<rule class=slnt>اۡ</rule> فِى قُلُوبِهِمُ <rule class=ham_wasl>ٱ</rule>لۡعِ<rule class=qalaqah>جۡ</rule>لَ بِكُفۡرِهِمۡ‌ۚ قُلۡ بِئۡسَمَا يَأۡمُرُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِيمَ<rule class=madda_normal>ـٰ</rule>نُكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٩٣',
    93, 1, 1, 14, 12, 6, 'false'
  );
  
  -- Ayah 94 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    101,
    'قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةࣰ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلۡمَوۡتَ إِن كُنتُمۡ صَـٰدِقِینَ',
    'قل ان كانت لكم الدار الاخرة عند الله خالصة من دون الناس فتمنوا الموت ان كنتم صادقين',
    'قُلۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَتۡ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ خَالِصَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ فَتَمَ<rule class=ghunnah>نّ</rule>َوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٩٤',
    94, 1, 1, 15, 12, 6, 'false'
  );
  
  -- Ayah 95 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    102,
    'وَلَن یَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَیۡدِیهِمۡۚ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ',
    'ولن يتمنوه ابدا بما قدمت ايديهم والله عليم بالظالمين',
    'وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَمَ<rule class=ghunnah>نّ</rule>َوۡهُ أَبَد<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِمَا قَدَّمَتۡ أَيۡدِيهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٩٥',
    95, 1, 1, 15, 12, 6, 'false'
  );
  
  -- Ayah 96 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    103,
    'وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَیَوٰةࣲ وَمِنَ ٱلَّذِینَ أَشۡرَكُوا۟ۚ یَوَدُّ أَحَدُهُمۡ لَوۡ یُعَمَّرُ أَلۡفَ سَنَةࣲ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن یُعَمَّرَۗ وَٱللَّهُ بَصِیرُۢ بِمَا یَعۡمَلُونَ',
    'ولتجدنهم احرص الناس على حياة ومن الذين اشركوا يود احدهم لو يعمر الف سنة وما هو بمزحزحه من العذاب ان يعمر والله بصير بما يعملون',
    'وَلَتَجِدَ<rule class=ghunnah>نّ</rule>َهُمۡ أَحۡرَصَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ عَلَىٰ حَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَشۡرَكُو<rule class=slnt>اۡ‌ۚ</rule> يَوَدُّ أَحَدُهُمۡ لَوۡ يُعَ<rule class=ghunnah>مّ</rule>َرُ أَلۡفَ سَنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا هُوَ بِمُزَحۡزِحِه<rule class=madda_normal>ِۦ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعَ<rule class=ghunnah>مّ</rule>َرَ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بَصِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 1, 1, 15, 12, 6, 'false'
  );
  
  -- Ayah 97 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    104,
    'قُلۡ مَن كَانَ عَدُوࣰّا لِّجِبۡرِیلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ وَهُدࣰى وَبُشۡرَىٰ لِلۡمُؤۡمِنِینَ',
    'قل من كان عدوا لجبريل فانه نزله على قلبك باذن الله مصدقا لما بين يديه وهدى وبشرى للمؤمنين',
    'قُلۡ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ عَدُو<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّجِ<rule class=qalaqah>بۡ</rule>رِيلَ فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> نَزَّلَهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ قَلۡبِكَ بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَيۡهِ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َبُشۡرَىٰ لِلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٩٧',
    97, 1, 1, 15, 13, 6, 'false'
  );
  
  -- Ayah 98 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    105,
    'مَن كَانَ عَدُوࣰّا لِّلَّهِ وَمَلَـٰۤىِٕكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِیلَ وَمِیكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوࣱّ لِّلۡكَـٰفِرِینَ',
    'من كان عدوا لله وملائكته ورسله وجبريل وميكال فان الله عدو للكافرين',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ عَدُو<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّهِ وَمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَتِه<rule class=madda_normal>ِۦ</rule> وَرُسُلِه<rule class=madda_normal>ِۦ</rule> وَجِ<rule class=qalaqah>بۡ</rule>رِيلَ وَمِيكَ<rule class=madda_normal>ـٰ</rule>لَ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَدُ<rule class=idgham_wo_ghunnah>وٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٩٨',
    98, 1, 1, 15, 13, 6, 'false'
  );
  
  -- Ayah 99 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    106,
    'وَلَقَدۡ أَنزَلۡنَاۤ إِلَیۡكَ ءَایَـٰتِۭ بَیِّنَـٰتࣲۖ وَمَا یَكۡفُرُ بِهَاۤ إِلَّا ٱلۡفَـٰسِقُونَ',
    'ولقد انزلنا اليك ايات بينات وما يكفر بها الا الفاسقون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا يَكۡفُرُ بِه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٩٩',
    99, 1, 1, 15, 13, 6, 'false'
  );
  
  -- Ayah 100 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    107,
    'أَوَكُلَّمَا عَـٰهَدُوا۟ عَهۡدࣰا نَّبَذَهُۥ فَرِیقࣱ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ لَا یُؤۡمِنُونَ',
    'اوكلما عاهدوا عهدا نبذه فريق منهم بل اكثرهم لا يؤمنون',
    'أَوَكُلَّمَا عَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> عَهۡ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>ن</rule>َّبَذَهُ<rule class=madda_normal>ۥ</rule> فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=ikhafa_shafawi>ُم‌ۚ</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ أَكۡثَرُهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٠٠',
    100, 1, 1, 15, 13, 6, 'false'
  );
  
  -- Ayah 101 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    108,
    'وَلَمَّا جَاۤءَهُمۡ رَسُولࣱ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمۡ نَبَذَ فَرِیقࣱ مِّنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ كِتَـٰبَ ٱللَّهِ وَرَاۤءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا یَعۡلَمُونَ',
    'ولما جاءهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين اوتوا الكتاب كتاب الله وراء ظهورهم كانهم لا يعلمون',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ مُصَدِّ<rule class=idgham_wo_ghunnah>قٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا مَعَهُمۡ نَبَذَ فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ كِتَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ظُهُورِهِمۡ كَأَ<rule class=ghunnah>نّ</rule>َهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٠١',
    101, 1, 1, 15, 13, 6, 'false'
  );
  
  -- Ayah 102 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    109,
    'وَٱتَّبَعُوا۟ مَا تَتۡلُوا۟ ٱلشَّیَـٰطِینُ عَلَىٰ مُلۡكِ سُلَیۡمَـٰنَۖ وَمَا كَفَرَ سُلَیۡمَـٰنُ وَلَـٰكِنَّ ٱلشَّیَـٰطِینَ كَفَرُوا۟ یُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ وَمَاۤ أُنزِلَ عَلَى ٱلۡمَلَكَیۡنِ بِبَابِلَ هَـٰرُوتَ وَمَـٰرُوتَۚ وَمَا یُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ یَقُولَاۤ إِنَّمَا نَحۡنُ فِتۡنَةࣱ فَلَا تَكۡفُرۡۖ فَیَتَعَلَّمُونَ مِنۡهُمَا مَا یُفَرِّقُونَ بِهِۦ بَیۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ وَمَا هُم بِضَاۤرِّینَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَیَتَعَلَّمُونَ مَا یَضُرُّهُمۡ وَلَا یَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُوا۟ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِی ٱلۡـَٔاخِرَةِ مِنۡ خَلَـٰقࣲۚ وَلَبِئۡسَ مَا شَرَوۡا۟ بِهِۦۤ أَنفُسَهُمۡۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ',
    'واتبعوا ما تتلو الشياطين على ملك سليمان وما كفر سليمان ولكن الشياطين كفروا يعلمون الناس السحر وما انزل على الملكين ببابل هاروت وماروت وما يعلمان من احد حتى يقولا انما نحن فتنة فلا تكفر فيتعلمون منهما ما يفرقون به بين المرء وزوجه وما هم بضارين به من احد الا باذن الله ويتعلمون ما يضرهم ولا ينفعهم ولقد علموا لمن اشتراه ما له في الاخرة من خلاق ولبئس ما شروا به انفسهم لو كانوا يعلمون',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> مَا تَتۡلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينُ عَلَىٰ مُلۡكِ سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ‌ۖ وَمَا كَفَرَ سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينَ كَفَرُو<rule class=slnt>اۡ</rule> يُعَلِّمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّحۡرَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمَلَكَيۡنِ بِبَابِلَ هَ<rule class=madda_normal>ـٰ</rule>رُوتَ وَمَ<rule class=madda_normal>ـٰ</rule>رُوتَ‌ۚ وَمَا يُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ يَقُول<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا نَحۡنُ فِتۡنَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َلَا تَكۡفُرۡ‌ۖ فَيَتَعَلَّمُونَ مِنۡهُمَا مَا يُفَرِّقُونَ بِه<rule class=madda_normal>ِۦ</rule> بَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡمَرۡءِ وَزَوۡجِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَمَا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِض<rule class=madda_necessary>َا</rule>ٓرِّينَ بِه<rule class=madda_normal>ِۦ</rule> مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمۡ وَلَا يَ<rule class=ikhafa>نف</rule>َعُهُمۡ‌ۚ وَلَقَ<rule class=qalaqah>دۡ</rule> عَلِمُو<rule class=slnt>اۡ</rule> لَمَنِ <rule class=ham_wasl>ٱ</rule>شۡتَرَ<rule class=madda_normal>ٮٰ</rule>هُ مَا لَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ مِنۡ خَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>قٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَبِئۡسَ مَا شَرَوۡ<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ‌ۚ لَوۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٠٢',
    102, 1, 1, 16, 13, 6, 'false'
  );
  
  -- Ayah 103 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    110,
    'وَلَوۡ أَنَّهُمۡ ءَامَنُوا۟ وَٱتَّقَوۡا۟ لَمَثُوبَةࣱ مِّنۡ عِندِ ٱللَّهِ خَیۡرࣱۚ لَّوۡ كَانُوا۟ یَعۡلَمُونَ',
    'ولو انهم امنوا واتقوا لمثوبة من عند الله خير لو كانوا يعلمون',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> لَمَثُوبَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ خَيۡ<rule class=idgham_wo_ghunnah>رٌ‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٠٣',
    103, 1, 1, 16, 13, 6, 'false'
  );
  
  -- Ayah 104 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    111,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَ ٰ⁠عِنَا وَقُولُوا۟ ٱنظُرۡنَا وَٱسۡمَعُوا۟ۗ وَلِلۡكَـٰفِرِینَ عَذَابٌ أَلِیمࣱ',
    'يا ايها الذين امنوا لا تقولوا راعنا وقولوا انظرنا واسمعوا وللكافرين عذاب اليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَقُولُو<rule class=slnt>اۡ</rule> ر<rule class=madda_normal>ٰ</rule>عِنَا وَقُولُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡنَا وَ<rule class=ham_wasl>ٱ</rule>سۡمَعُو<rule class=slnt>اۡ‌ۗ</rule> وَلِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١٠٤',
    104, 1, 1, 16, 14, 6, 'false'
  );
  
  -- Ayah 105 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    112,
    'مَّا یَوَدُّ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ وَلَا ٱلۡمُشۡرِكِینَ أَن یُنَزَّلَ عَلَیۡكُم مِّنۡ خَیۡرࣲ مِّن رَّبِّكُمۡۚ وَٱللَّهُ یَخۡتَصُّ بِرَحۡمَتِهِۦ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ',
    'ما يود الذين كفروا من اهل الكتاب ولا المشركين ان ينزل عليكم من خير من ربكم والله يختص برحمته من يشاء والله ذو الفضل العظيم',
    'مَّا يَوَدُّ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَلَا <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُنَزَّلَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خَيۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَخۡتَصُّ بِرَحۡمَتِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ ذُو <rule class=ham_wasl>ٱ</rule>لۡفَضۡلِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ١٠٥',
    105, 1, 1, 16, 14, 6, 'false'
  );
  
  -- Ayah 106 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    113,
    '۞ مَا نَنسَخۡ مِنۡ ءَایَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَیۡرࣲ مِّنۡهَاۤ أَوۡ مِثۡلِهَاۤۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'ما ننسخ من اية او ننسها نات بخير منها او مثلها الم تعلم ان الله على كل شيء قدير',
    '۞مَا نَ<rule class=ikhafa>نس</rule>َخۡ مِنۡ ءَايَةٍ أَوۡ نُ<rule class=ikhafa>نس</rule>ِهَا نَأۡتِ بِخَيۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ مِثۡلِه<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> أَلَمۡ تَعۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١٠٦',
    106, 1, 1, 17, 14, 7, 'false'
  );
  
  -- Ayah 107 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    114,
    'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرٍ',
    'الم تعلم ان الله له ملك السماوات والارض وما لكم من دون الله من ولي ولا نصير',
    'أَلَمۡ تَعۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَمَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَص<rule class=madda_permissible>ِي</rule>رٍ ١٠٧',
    107, 1, 1, 17, 14, 7, 'false'
  );
  
  -- Ayah 108 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    115,
    'أَمۡ تُرِیدُونَ أَن تَسۡـَٔلُوا۟ رَسُولَكُمۡ كَمَا سُىِٕلَ مُوسَىٰ مِن قَبۡلُۗ وَمَن یَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِیمَـٰنِ فَقَدۡ ضَلَّ سَوَاۤءَ ٱلسَّبِیلِ',
    'ام تريدون ان تسالوا رسولكم كما سئل موسى من قبل ومن يتبدل الكفر بالايمان فقد ضل سواء السبيل',
    'أَمۡ تُرِيدُونَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡــَٔلُو<rule class=slnt>اۡ</rule> رَسُولَكُمۡ كَمَا سُئِلَ مُوسَىٰ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَبَدَّلِ <rule class=ham_wasl>ٱ</rule>لۡكُفۡرَ بِ<rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ فَقَ<rule class=qalaqah>دۡ</rule> ضَلَّ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لِ ١٠٨',
    108, 1, 1, 17, 14, 7, 'false'
  );
  
  -- Ayah 109 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    116,
    'وَدَّ كَثِیرࣱ مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَوۡ یَرُدُّونَكُم مِّنۢ بَعۡدِ إِیمَـٰنِكُمۡ كُفَّارًا حَسَدࣰا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَیَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُوا۟ وَٱصۡفَحُوا۟ حَتَّىٰ یَأۡتِیَ ٱللَّهُ بِأَمۡرِهِۦۤۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'ود كثير من اهل الكتاب لو يردونكم من بعد ايمانكم كفارا حسدا من عند انفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتى ياتي الله بامره ان الله على كل شيء قدير',
    'وَدَّ كَثِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَوۡ يَرُدُّونَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ إِيمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ كُفَّارًا حَسَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ أَ<rule class=ikhafa>نف</rule>ُسِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا تَبَيَّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>عۡفُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>صۡفَحُو<rule class=slnt>اۡ</rule> حَتَّىٰ يَأۡتِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِأَمۡرِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١٠٩',
    109, 1, 1, 17, 14, 7, 'false'
  );
  
  -- Ayah 110 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    117,
    'وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنۡ خَیۡرࣲ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِیرࣱ',
    'واقيموا الصلاة واتوا الزكاة وما تقدموا لانفسكم من خير تجدوه عند الله ان الله بما تعملون بصير',
    'وَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ‌ۚ وَمَا تُقَدِّمُو<rule class=slnt>اۡ</rule> لِأَ<rule class=ikhafa>نف</rule>ُسِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ت</rule>َجِدُوهُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ١١٠',
    110, 1, 1, 17, 14, 7, 'false'
  );
  
  -- Ayah 111 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    118,
    'وَقَالُوا۟ لَن یَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَـٰرَىٰۗ تِلۡكَ أَمَانِیُّهُمۡۗ قُلۡ هَاتُوا۟ بُرۡهَـٰنَكُمۡ إِن كُنتُمۡ صَـٰدِقِینَ',
    'وقالوا لن يدخل الجنة الا من كان هودا او نصارى تلك امانيهم قل هاتوا برهانكم ان كنتم صادقين',
    'وَقَالُو<rule class=slnt>اۡ</rule> ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>خُلَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ هُودًا أَوۡ نَصَ<rule class=madda_normal>ـٰ</rule>رَىٰ‌ۗ تِلۡكَ أَمَانِيُّهُمۡ‌ۗ قُلۡ هَاتُو<rule class=slnt>اۡ</rule> بُرۡهَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١١١',
    111, 1, 1, 17, 14, 7, 'false'
  );
  
  -- Ayah 112 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    119,
    'بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنࣱ فَلَهُۥۤ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'بلى من اسلم وجهه لله وهو محسن فله اجره عند ربه ولا خوف عليهم ولا هم يحزنون',
    'بَلَىٰ مَنۡ أَسۡلَمَ وَ<rule class=qalaqah>جۡ</rule>هَهُ<rule class=madda_normal>ۥ</rule> لِلَّهِ وَهُوَ مُحۡسِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=qalaqah>جۡ</rule>رُهُ<rule class=madda_normal>ۥ</rule> عِ<rule class=ikhafa>ند</rule>َ رَبِّه<rule class=madda_normal>ِۦ</rule> وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ١١٢',
    112, 1, 1, 17, 14, 7, 'false'
  );
  
  -- Ayah 113 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    120,
    'وَقَالَتِ ٱلۡیَهُودُ لَیۡسَتِ ٱلنَّصَـٰرَىٰ عَلَىٰ شَیۡءࣲ وَقَالَتِ ٱلنَّصَـٰرَىٰ لَیۡسَتِ ٱلۡیَهُودُ عَلَىٰ شَیۡءࣲ وَهُمۡ یَتۡلُونَ ٱلۡكِتَـٰبَۗ كَذَ ٰ⁠لِكَ قَالَ ٱلَّذِینَ لَا یَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ یَحۡكُمُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ',
    'وقالت اليهود ليست النصارى على شيء وقالت النصارى ليست اليهود على شيء وهم يتلون الكتاب كذلك قال الذين لا يعلمون مثل قولهم فالله يحكم بينهم يوم القيامة فيما كانوا فيه يختلفون',
    'وَقَالَتِ <rule class=ham_wasl>ٱ</rule>لۡيَهُودُ لَيۡسَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَىٰ عَلَىٰ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَىٰ لَيۡسَتِ <rule class=ham_wasl>ٱ</rule>لۡيَهُودُ عَلَىٰ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ يَتۡلُونَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ‌ۗ كَذ<rule class=madda_normal>ٰ</rule>لِكَ قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فِيمَا كَانُو<rule class=slnt>اۡ</rule> فِيهِ يَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ١١٣',
    113, 1, 1, 18, 15, 7, 'false'
  );
  
  -- Ayah 114 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    121,
    'وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَـٰجِدَ ٱللَّهِ أَن یُذۡكَرَ فِیهَا ٱسۡمُهُۥ وَسَعَىٰ فِی خَرَابِهَاۤۚ أُو۟لَـٰۤىِٕكَ مَا كَانَ لَهُمۡ أَن یَدۡخُلُوهَاۤ إِلَّا خَاۤىِٕفِینَۚ لَهُمۡ فِی ٱلدُّنۡیَا خِزۡیࣱ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابٌ عَظِیمࣱ',
    'ومن اظلم ممن منع مساجد الله ان يذكر فيها اسمه وسعى في خرابها اولئك ما كان لهم ان يدخلوها الا خائفين لهم في الدنيا خزي ولهم في الاخرة عذاب عظيم',
    'وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّنَعَ مَسَ<rule class=madda_normal>ـٰ</rule>جِدَ <rule class=ham_wasl>ٱ</rule>للَّهِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُذۡكَرَ فِيهَا <rule class=ham_wasl>ٱ</rule>سۡمُهُ<rule class=madda_normal>ۥ</rule> وَسَعَىٰ فِى خَرَابِه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مَا كَانَ لَهُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>خُلُوه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا خ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفِينَ‌ۚ لَهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا خِزۡ<rule class=idgham_ghunnah>ىٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١١٤',
    114, 1, 1, 18, 15, 7, 'false'
  );
  
  -- Ayah 115 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    122,
    'وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَیۡنَمَا تُوَلُّوا۟ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَ ٰ⁠سِعٌ عَلِیمࣱ',
    'ولله المشرق والمغرب فاينما تولوا فثم وجه الله ان الله واسع عليم',
    'وَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡمَشۡرِقُ وَ<rule class=ham_wasl>ٱ</rule>لۡمَغۡرِبُ‌ۚ فَأَيۡنَمَا تُوَلُّو<rule class=slnt>اۡ</rule> فَثَ<rule class=ghunnah>مّ</rule>َ وَ<rule class=qalaqah>جۡ</rule>هُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ و<rule class=madda_normal>ٰ</rule>سِعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١١٥',
    115, 1, 1, 18, 15, 7, 'false'
  );
  
  -- Ayah 116 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    123,
    'وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدࣰاۗ سُبۡحَـٰنَهُۥۖ بَل لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ كُلࣱّ لَّهُۥ قَـٰنِتُونَ',
    'وقالوا اتخذ الله ولدا سبحانه بل له ما في السماوات والارض كل له قانتون',
    'وَقَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَ<rule class=ikhafa>دًا‌ۗ</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule>‌ۖ بَل لَّهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ كُ<rule class=idgham_wo_ghunnah>لٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> قَ<rule class=madda_normal>ـٰ</rule>نِت<rule class=madda_permissible>ُو</rule>نَ ١١٦',
    116, 1, 1, 18, 15, 7, 'false'
  );
  
  -- Ayah 117 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    124,
    'بَدِیعُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ وَإِذَا قَضَىٰۤ أَمۡرࣰا فَإِنَّمَا یَقُولُ لَهُۥ كُن فَیَكُونُ',
    'بديع السماوات والارض واذا قضى امرا فانما يقول له كن فيكون',
    'بَدِيعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَإِذَا قَضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َمَا يَقُولُ لَهُ<rule class=madda_normal>ۥ</rule> كُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َيَك<rule class=madda_permissible>ُو</rule>نُ ١١٧',
    117, 1, 1, 18, 15, 7, 'false'
  );
  
  -- Ayah 118 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    125,
    'وَقَالَ ٱلَّذِینَ لَا یَعۡلَمُونَ لَوۡلَا یُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِینَاۤ ءَایَةࣱۗ كَذَ ٰ⁠لِكَ قَالَ ٱلَّذِینَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَـٰبَهَتۡ قُلُوبُهُمۡۗ قَدۡ بَیَّنَّا ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یُوقِنُونَ',
    'وقال الذين لا يعلمون لولا يكلمنا الله او تاتينا اية كذلك قال الذين من قبلهم مثل قولهم تشابهت قلوبهم قد بينا الايات لقوم يوقنون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَعۡلَمُونَ لَوۡلَا يُكَلِّمُنَا <rule class=ham_wasl>ٱ</rule>للَّهُ أَوۡ تَأۡتِين<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=ikhafa>ةٌ‌ۗ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّثۡلَ قَوۡلِهِمۡ‌ۘ تَشَ<rule class=madda_normal>ـٰ</rule>بَهَتۡ قُلُوبُهُمۡ‌ۗ قَ<rule class=qalaqah>دۡ</rule> بَيَّ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوقِن<rule class=madda_permissible>ُو</rule>نَ ١١٨',
    118, 1, 1, 18, 15, 7, 'false'
  );
  
  -- Ayah 119 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    126,
    'إِنَّاۤ أَرۡسَلۡنَـٰكَ بِٱلۡحَقِّ بَشِیرࣰا وَنَذِیرࣰاۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَـٰبِ ٱلۡجَحِیمِ',
    'انا ارسلناك بالحق بشيرا ونذيرا ولا تسال عن اصحاب الجحيم',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ بَشِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَذِي<rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تُسۡــَٔلُ عَنۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ١١٩',
    119, 1, 1, 18, 15, 7, 'false'
  );
  
  -- Ayah 120 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    127,
    'وَلَن تَرۡضَىٰ عَنكَ ٱلۡیَهُودُ وَلَا ٱلنَّصَـٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَىِٕنِ ٱتَّبَعۡتَ أَهۡوَاۤءَهُم بَعۡدَ ٱلَّذِی جَاۤءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرٍ',
    'ولن ترضى عنك اليهود ولا النصارى حتى تتبع ملتهم قل ان هدى الله هو الهدى ولئن اتبعت اهواءهم بعد الذي جاءك من العلم ما لك من الله من ولي ولا نصير',
    'وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرۡضَىٰ عَ<rule class=ikhafa>نك</rule>َ <rule class=ham_wasl>ٱ</rule>لۡيَهُودُ وَلَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡ‌ۗ قُلۡ إِ<rule class=ghunnah>نّ</rule>َ هُدَى <rule class=ham_wasl>ٱ</rule>للَّهِ هُوَ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ‌ۗ وَلَئِنِ <rule class=ham_wasl>ٱ</rule>تَّبَعۡتَ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡدَ <rule class=ham_wasl>ٱ</rule>لَّذِى ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ‌ۙ مَا لَكَ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَص<rule class=madda_permissible>ِي</rule>رٍ ١٢٠',
    120, 1, 1, 19, 15, 7, 'false'
  );
  
  -- Ayah 121 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    128,
    'ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦۤ أُو۟لَـٰۤىِٕكَ یُؤۡمِنُونَ بِهِۦۗ وَمَن یَكۡفُرۡ بِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ',
    'الذين اتيناهم الكتاب يتلونه حق تلاوته اولئك يؤمنون به ومن يكفر به فاولئك هم الخاسرون',
    'ٱلَّذِينَ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يَتۡلُونَهُ<rule class=madda_normal>ۥ</rule> حَقَّ تِلَاوَتِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يُؤۡمِنُونَ بِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرۡ بِه<rule class=madda_normal>ِۦ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ١٢١',
    121, 1, 1, 19, 15, 7, 'false'
  );
  
  -- Ayah 122 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    129,
    'یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱذۡكُرُوا۟ نِعۡمَتِیَ ٱلَّتِیۤ أَنۡعَمۡتُ عَلَیۡكُمۡ وَأَنِّی فَضَّلۡتُكُمۡ عَلَى ٱلۡعَـٰلَمِینَ',
    'يا بني اسرائيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم على العالمين',
    'يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَتِىَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡعَمۡتُ عَلَيۡكُمۡ وَأَ<rule class=ghunnah>نّ</rule>ِى فَضَّلۡتُكُمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٢٢',
    122, 1, 1, 19, 16, 7, 'false'
  );
  
  -- Ayah 123 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    130,
    'وَٱتَّقُوا۟ یَوۡمࣰا لَّا تَجۡزِی نَفۡسٌ عَن نَّفۡسࣲ شَیۡـࣰٔا وَلَا یُقۡبَلُ مِنۡهَا عَدۡلࣱ وَلَا تَنفَعُهَا شَفَـٰعَةࣱ وَلَا هُمۡ یُنصَرُونَ',
    'واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها عدل ولا تنفعها شفاعة ولا هم ينصرون',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> يَوۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَ<rule class=qalaqah>جۡ</rule>زِى نَفۡسٌ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ش</rule>َيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُ<rule class=qalaqah>قۡ</rule>بَلُ مِنۡهَا عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَ<rule class=ikhafa>نف</rule>َعُهَا شَفَ<rule class=madda_normal>ـٰ</rule>عَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا هُمۡ يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ١٢٣',
    123, 1, 1, 19, 16, 7, 'false'
  );
  
  -- Ayah 124 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    131,
    '۞ وَإِذِ ٱبۡتَلَىٰۤ إِبۡرَ ٰ⁠هِـۧمَ رَبُّهُۥ بِكَلِمَـٰتࣲ فَأَتَمَّهُنَّۖ قَالَ إِنِّی جَاعِلُكَ لِلنَّاسِ إِمَامࣰاۖ قَالَ وَمِن ذُرِّیَّتِیۖ قَالَ لَا یَنَالُ عَهۡدِی ٱلظَّـٰلِمِینَ',
    'واذ ابتلى ابراهيم ربه بكلمات فاتمهن قال اني جاعلك للناس اماما قال ومن ذريتي قال لا ينال عهدي الظالمين',
    '۞وَإِذِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ رَبُّهُ<rule class=madda_normal>ۥ</rule> بِكَلِمَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>َأَتَ<rule class=ghunnah>مّ</rule>َهُ<rule class=ghunnah>نّ</rule>َ‌ۖ قَالَ إِ<rule class=ghunnah>نّ</rule>ِى جَاعِلُكَ لِل<rule class=ghunnah>نّ</rule>َاسِ إِمَا<rule class=ikhafa>مًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُرِّيَّتِى‌ۖ قَالَ لَا يَنَالُ عَهۡدِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٢٤',
    124, 1, 1, 19, 16, 8, 'false'
  );
  
  -- Ayah 125 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    132,
    'وَإِذۡ جَعَلۡنَا ٱلۡبَیۡتَ مَثَابَةࣰ لِّلنَّاسِ وَأَمۡنࣰا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبۡرَ ٰ⁠هِـۧمَ مُصَلࣰّىۖ وَعَهِدۡنَاۤ إِلَىٰۤ إِبۡرَ ٰ⁠هِـۧمَ وَإِسۡمَـٰعِیلَ أَن طَهِّرَا بَیۡتِیَ لِلطَّاۤىِٕفِینَ وَٱلۡعَـٰكِفِینَ وَٱلرُّكَّعِ ٱلسُّجُودِ',
    'واذ جعلنا البيت مثابة للناس وامنا واتخذوا من مقام ابراهيم مصلى وعهدنا الى ابراهيم واسماعيل ان طهرا بيتي للطائفين والعاكفين والركع السجود',
    'وَإِذۡ جَعَلۡنَا <rule class=ham_wasl>ٱ</rule>لۡبَيۡتَ مَثَابَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ وَأَمۡ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّخِذُو<rule class=slnt>اۡ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّقَامِ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ مُصَل<rule class=idgham_ghunnah>ًّى‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َعَهِ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َهِّرَا بَيۡتِىَ لِلطّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>كِفِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّكَّعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّج<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ِ ١٢٥',
    125, 1, 1, 19, 16, 8, 'false'
  );
  
  -- Ayah 126 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    133,
    'وَإِذۡ قَالَ إِبۡرَ ٰ⁠هِـۧمُ رَبِّ ٱجۡعَلۡ هَـٰذَا بَلَدًا ءَامِنࣰا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَ ٰ⁠تِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِیلࣰا ثُمَّ أَضۡطَرُّهُۥۤ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'واذ قال ابراهيم رب اجعل هذا بلدا امنا وارزق اهله من الثمرات من امن منهم بالله واليوم الاخر قال ومن كفر فامتعه قليلا ثم اضطره الى عذاب النار وبئس المصير',
    'وَإِذۡ قَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مُ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا بَلَدًا ءَامِ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>رۡزُ<rule class=qalaqah>قۡ</rule> أَهۡلَهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ مَنۡ ءَامَنَ مِنۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ‌ۖ قَالَ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ فَأُمَتِّعُهُ<rule class=madda_normal>ۥ</rule> قَلِيل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ أَضۡطَرُّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَىٰ عَذَابِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٢٦',
    126, 1, 1, 19, 16, 8, 'false'
  );
  
  -- Ayah 127 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    134,
    'وَإِذۡ یَرۡفَعُ إِبۡرَ ٰ⁠هِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَیۡتِ وَإِسۡمَـٰعِیلُ رَبَّنَا تَقَبَّلۡ مِنَّاۤۖ إِنَّكَ أَنتَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'واذ يرفع ابراهيم القواعد من البيت واسماعيل ربنا تقبل منا انك انت السميع العليم',
    'وَإِذۡ يَرۡفَعُ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مُ <rule class=ham_wasl>ٱ</rule>لۡقَوَاعِدَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتِ وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلُ رَبَّنَا تَقَبَّلۡ مِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ١٢٧',
    127, 1, 1, 20, 16, 8, 'false'
  );
  
  -- Ayah 128 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    135,
    'رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَیۡنِ لَكَ وَمِن ذُرِّیَّتِنَاۤ أُمَّةࣰ مُّسۡلِمَةࣰ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَیۡنَاۤۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِیمُ',
    'ربنا واجعلنا مسلمين لك ومن ذريتنا امة مسلمة لك وارنا مناسكنا وتب علينا انك انت التواب الرحيم',
    'رَبَّنَا وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُرِّيَّتِن<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡلِمَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكَ وَأَرِنَا مَنَاسِكَنَا وَتُ<rule class=qalaqah>بۡ</rule> عَلَيۡن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوَّابُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٢٨',
    128, 1, 1, 20, 16, 8, 'false'
  );
  
  -- Ayah 129 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    136,
    'رَبَّنَا وَٱبۡعَثۡ فِیهِمۡ رَسُولࣰا مِّنۡهُمۡ یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِكَ وَیُعَلِّمُهُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَیُزَكِّیهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'ربنا وابعث فيهم رسولا منهم يتلو عليهم اياتك ويعلمهم الكتاب والحكمة ويزكيهم انك انت العزيز الحكيم',
    'رَبَّنَا وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>عَثۡ فِيهِمۡ رَسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ يَتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِكَ وَيُعَلِّمُهُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَيُزَكِّيهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ١٢٩',
    129, 1, 1, 20, 16, 8, 'false'
  );
  
  -- Ayah 130 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    137,
    'وَمَن یَرۡغَبُ عَن مِّلَّةِ إِبۡرَ ٰ⁠هِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَیۡنَـٰهُ فِی ٱلدُّنۡیَاۖ وَإِنَّهُۥ فِی ٱلۡـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِینَ',
    'ومن يرغب عن ملة ابراهيم الا من سفه نفسه ولقد اصطفيناه في الدنيا وانه في الاخرة لمن الصالحين',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َرۡغَبُ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>ِّلَّةِ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َفِهَ نَفۡسَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَلَقَدِ <rule class=ham_wasl>ٱ</rule>صۡطَفَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ١٣٠',
    130, 1, 1, 20, 17, 8, 'false'
  );
  
  -- Ayah 131 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    138,
    'إِذۡ قَالَ لَهُۥ رَبُّهُۥۤ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَـٰلَمِینَ',
    'اذ قال له ربه اسلم قال اسلمت لرب العالمين',
    'إِذۡ قَالَ لَهُ<rule class=madda_normal>ۥ</rule> رَبُّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَسۡلِمۡ‌ۖ قَالَ أَسۡلَمۡتُ لِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٣١',
    131, 1, 1, 20, 17, 8, 'false'
  );
  
  -- Ayah 132 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    139,
    'وَوَصَّىٰ بِهَاۤ إِبۡرَ ٰ⁠هِـۧمُ بَنِیهِ وَیَعۡقُوبُ یَـٰبَنِیَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّینَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ',
    'ووصى بها ابراهيم بنيه ويعقوب يا بني ان الله اصطفى لكم الدين فلا تموتن الا وانتم مسلمون',
    'وَوَصَّىٰ بِه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مُ بَنِيهِ وَيَعۡقُوبُ يَ<rule class=madda_normal>ـٰ</rule>بَنِىَّ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>صۡطَفَىٰ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ فَلَا تَمُوتُ<rule class=ghunnah>نّ</rule>َ إِلَّا وَأَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٣٢',
    132, 1, 1, 20, 17, 8, 'false'
  );
  
  -- Ayah 133 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    140,
    'أَمۡ كُنتُمۡ شُهَدَاۤءَ إِذۡ حَضَرَ یَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِیهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِیۖ قَالُوا۟ نَعۡبُدُ إِلَـٰهَكَ وَإِلَـٰهَ ءَابَاۤىِٕكَ إِبۡرَ ٰ⁠هِـۧمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ إِلَـٰهࣰا وَ ٰ⁠حِدࣰا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ',
    'ام كنتم شهداء اذ حضر يعقوب الموت اذ قال لبنيه ما تعبدون من بعدي قالوا نعبد الهك واله ابائك ابراهيم واسماعيل واسحاق الها واحدا ونحن له مسلمون',
    'أَمۡ كُ<rule class=ikhafa>نت</rule>ُمۡ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِذۡ حَضَرَ يَعۡقُوبَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِى قَالُو<rule class=slnt>اۡ</rule> نَعۡبُدُ إِلَ<rule class=madda_normal>ـٰ</rule>هَكَ وَإِلَ<rule class=madda_normal>ـٰ</rule>هَ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َنَحۡنُ لَهُ<rule class=madda_normal>ۥ</rule> مُسۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٣٣',
    133, 1, 1, 20, 17, 8, 'false'
  );
  
  -- Ayah 134 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    141,
    'تِلۡكَ أُمَّةࣱ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُوا۟ یَعۡمَلُونَ',
    'تلك امة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسالون عما كانوا يعملون',
    'تِلۡكَ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> خَلَتۡ‌ۖ لَهَا مَا كَسَبَتۡ وَلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَسَ<rule class=qalaqah>بۡ</rule>تُمۡ‌ۖ وَلَا تُسۡــَٔلُونَ عَ<rule class=ghunnah>مّ</rule>َا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٣٤',
    134, 1, 1, 20, 17, 8, 'false'
  );
  
  -- Ayah 135 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    142,
    'وَقَالُوا۟ كُونُوا۟ هُودًا أَوۡ نَصَـٰرَىٰ تَهۡتَدُوا۟ۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَ ٰ⁠هِـۧمَ حَنِیفࣰاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ',
    'وقالوا كونوا هودا او نصارى تهتدوا قل بل ملة ابراهيم حنيفا وما كان من المشركين',
    'وَقَالُو<rule class=slnt>اۡ</rule> كُونُو<rule class=slnt>اۡ</rule> هُودًا أَوۡ نَصَ<rule class=madda_normal>ـٰ</rule>رَىٰ تَهۡتَدُو<rule class=slnt>اۡ‌ۗ</rule> قُلۡ بَلۡ مِلَّةَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ حَنِي<rule class=idgham_ghunnah>فًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١٣٥',
    135, 1, 1, 21, 17, 8, 'false'
  );
  
  -- Ayah 136 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    143,
    'قُولُوۤا۟ ءَامَنَّا بِٱللَّهِ وَمَاۤ أُنزِلَ إِلَیۡنَا وَمَاۤ أُنزِلَ إِلَىٰۤ إِبۡرَ ٰ⁠هِـۧمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَاۤ أُوتِیَ مُوسَىٰ وَعِیسَىٰ وَمَاۤ أُوتِیَ ٱلنَّبِیُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَیۡنَ أَحَدࣲ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ',
    'قولوا امنا بالله وما انزل الينا وما انزل الى ابراهيم واسماعيل واسحاق ويعقوب والاسباط وما اوتي موسى وعيسى وما اوتي النبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون',
    'قُول<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡنَا وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَسۡبَاطِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيُّونَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ وَنَحۡنُ لَهُ<rule class=madda_normal>ۥ</rule> مُسۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٣٦',
    136, 1, 1, 21, 17, 8, 'false'
  );
  
  -- Ayah 137 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    144,
    'فَإِنۡ ءَامَنُوا۟ بِمِثۡلِ مَاۤ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَوا۟ۖ وَّإِن تَوَلَّوۡا۟ فَإِنَّمَا هُمۡ فِی شِقَاقࣲۖ فَسَیَكۡفِیكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'فان امنوا بمثل ما امنتم به فقد اهتدوا وان تولوا فانما هم في شقاق فسيكفيكهم الله وهو السميع العليم',
    'فَإِنۡ ءَامَنُو<rule class=slnt>اۡ</rule> بِمِثۡلِ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> فَقَدِ <rule class=ham_wasl>ٱ</rule>هۡتَدَو<rule class=slnt>اۡ‌ۖ</rule> وَّإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َمَا هُمۡ فِى شِقَا<rule class=ikhafa>قٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َسَيَكۡفِيكَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ١٣٧',
    137, 1, 1, 21, 17, 8, 'false'
  );
  
  -- Ayah 138 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    145,
    'صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةࣰۖ وَنَحۡنُ لَهُۥ عَـٰبِدُونَ',
    'صبغة الله ومن احسن من الله صبغة ونحن له عابدون',
    'صِ<rule class=qalaqah>بۡ</rule>غَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَمَنۡ أَحۡسَنُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ صِ<rule class=qalaqah>بۡ</rule>غَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َنَحۡنُ لَهُ<rule class=madda_normal>ۥ</rule> عَ<rule class=madda_normal>ـٰ</rule>بِد<rule class=madda_permissible>ُو</rule>نَ ١٣٨',
    138, 1, 1, 21, 17, 8, 'false'
  );
  
  -- Ayah 139 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    146,
    'قُلۡ أَتُحَاۤجُّونَنَا فِی ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَاۤ أَعۡمَـٰلُنَا وَلَكُمۡ أَعۡمَـٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ',
    'قل اتحاجوننا في الله وهو ربنا وربكم ولنا اعمالنا ولكم اعمالكم ونحن له مخلصون',
    'قُلۡ أَتُح<rule class=madda_necessary>َا</rule>ٓجُّونَنَا فِى <rule class=ham_wasl>ٱ</rule>للَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَن<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُنَا وَلَكُمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُكُمۡ وَنَحۡنُ لَهُ<rule class=madda_normal>ۥ</rule> مُخۡلِص<rule class=madda_permissible>ُو</rule>نَ ١٣٩',
    139, 1, 1, 21, 17, 8, 'false'
  );
  
  -- Ayah 140 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    147,
    'أَمۡ تَقُولُونَ إِنَّ إِبۡرَ ٰ⁠هِـۧمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ وَٱلۡأَسۡبَاطَ كَانُوا۟ هُودًا أَوۡ نَصَـٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَـٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ',
    'ام تقولون ان ابراهيم واسماعيل واسحاق ويعقوب والاسباط كانوا هودا او نصارى قل اانتم اعلم ام الله ومن اظلم ممن كتم شهادة عنده من الله وما الله بغافل عما تعملون',
    'أَمۡ تَقُولُونَ إِ<rule class=ghunnah>نّ</rule>َ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَسۡبَاطَ كَانُو<rule class=slnt>اۡ</rule> هُودًا أَوۡ نَصَ<rule class=madda_normal>ـٰ</rule>رَىٰ‌ۗ قُلۡ ءَأَ<rule class=ikhafa>نت</rule>ُمۡ أَعۡلَمُ أَمِ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َتَمَ شَهَ<rule class=madda_normal>ـٰ</rule>دَةً عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>للَّهُ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٤٠',
    140, 1, 1, 21, 17, 8, 'false'
  );
  
  -- Ayah 141 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    148,
    'تِلۡكَ أُمَّةࣱ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُوا۟ یَعۡمَلُونَ',
    'تلك امة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسالون عما كانوا يعملون',
    'تِلۡكَ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> خَلَتۡ‌ۖ لَهَا مَا كَسَبَتۡ وَلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَسَ<rule class=qalaqah>بۡ</rule>تُمۡ‌ۖ وَلَا تُسۡــَٔلُونَ عَ<rule class=ghunnah>مّ</rule>َا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٤١',
    141, 1, 1, 21, 17, 8, 'false'
  );
  
  -- Ayah 142 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    149,
    '۞ سَیَقُولُ ٱلسُّفَهَاۤءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِی كَانُوا۟ عَلَیۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ یَهۡدِی مَن یَشَاۤءُ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'سيقول السفهاء من الناس ما ولاهم عن قبلتهم التي كانوا عليها قل لله المشرق والمغرب يهدي من يشاء الى صراط مستقيم',
    '۞سَيَقُولُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّفَه<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ مَا وَلَّ<rule class=madda_normal>ـٰ</rule>هُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ِ<rule class=qalaqah>بۡ</rule>لَتِهِمُ <rule class=ham_wasl>ٱ</rule>لَّتِى كَانُو<rule class=slnt>اۡ</rule> عَلَيۡهَا‌ۚ قُل لِّلَّهِ <rule class=ham_wasl>ٱ</rule>لۡمَشۡرِقُ وَ<rule class=ham_wasl>ٱ</rule>لۡمَغۡرِبُ‌ۚ يَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ١٤٢',
    142, 2, 1, 22, 18, 9, 'false'
  );
  
  -- Ayah 143 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    150,
    'وَكَذَ ٰ⁠لِكَ جَعَلۡنَـٰكُمۡ أُمَّةࣰ وَسَطࣰا لِّتَكُونُوا۟ شُهَدَاۤءَ عَلَى ٱلنَّاسِ وَیَكُونَ ٱلرَّسُولُ عَلَیۡكُمۡ شَهِیدࣰاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِی كُنتَ عَلَیۡهَاۤ إِلَّا لِنَعۡلَمَ مَن یَتَّبِعُ ٱلرَّسُولَ مِمَّن یَنقَلِبُ عَلَىٰ عَقِبَیۡهِۚ وَإِن كَانَتۡ لَكَبِیرَةً إِلَّا عَلَى ٱلَّذِینَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِیُضِیعَ إِیمَـٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفࣱ رَّحِیمࣱ',
    'وكذلك جعلناكم امة وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا وما جعلنا القبلة التي كنت عليها الا لنعلم من يتبع الرسول ممن ينقلب على عقبيه وان كانت لكبيرة الا على الذين هدى الله وما كان الله ليضيع ايمانكم ان الله بالناس لرءوف رحيم',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َسَ<rule class=idgham_wo_ghunnah>طًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتَكُونُو<rule class=slnt>اۡ</rule> شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَيَكُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ عَلَيۡكُمۡ شَهِي<rule class=idgham_ghunnah>دًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َمَا جَعَلۡنَا <rule class=ham_wasl>ٱ</rule>لۡقِ<rule class=qalaqah>بۡ</rule>لَةَ <rule class=ham_wasl>ٱ</rule>لَّتِى كُ<rule class=ikhafa>نت</rule>َ عَلَيۡه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا لِنَعۡلَمَ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّبِعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ مِ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نق</rule>َلِبُ عَلَىٰ عَقِبَيۡهِ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَتۡ لَكَبِيرَةً إِلَّا عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَدَى <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ وَمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيُضِيعَ إِيمَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَرَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٤٣',
    143, 2, 1, 22, 18, 9, 'false'
  );
  
  -- Ayah 144 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    151,
    'قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِی ٱلسَّمَاۤءِۖ فَلَنُوَلِّیَنَّكَ قِبۡلَةࣰ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَیۡثُ مَا كُنتُمۡ فَوَلُّوا۟ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ لَیَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا یَعۡمَلُونَ',
    'قد نرى تقلب وجهك في السماء فلنولينك قبلة ترضاها فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره وان الذين اوتوا الكتاب ليعلمون انه الحق من ربهم وما الله بغافل عما يعملون',
    'قَ<rule class=qalaqah>دۡ</rule> نَرَىٰ تَقَلُّبَ وَ<rule class=qalaqah>جۡ</rule>هِكَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۖ فَلَنُوَلِّيَ<rule class=ghunnah>نّ</rule>َكَ قِ<rule class=qalaqah>بۡ</rule>لَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َرۡضَ<rule class=madda_normal>ـٰ</rule>هَا‌ۚ فَوَلِّ وَ<rule class=qalaqah>جۡ</rule>هَكَ شَ<rule class=qalaqah>طۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ‌ۚ وَحَيۡثُ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ فَوَلُّو<rule class=slnt>اۡ</rule> وُجُوهَكُمۡ شَ<rule class=qalaqah>طۡ</rule>رَهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ لَيَعۡلَمُونَ أَ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>للَّهُ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٤٤',
    144, 2, 1, 22, 18, 9, 'false'
  );
  
  -- Ayah 145 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    152,
    'وَلَىِٕنۡ أَتَیۡتَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ بِكُلِّ ءَایَةࣲ مَّا تَبِعُوا۟ قِبۡلَتَكَۚ وَمَاۤ أَنتَ بِتَابِعࣲ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعࣲ قِبۡلَةَ بَعۡضࣲۚ وَلَىِٕنِ ٱتَّبَعۡتَ أَهۡوَاۤءَهُم مِّنۢ بَعۡدِ مَا جَاۤءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذࣰا لَّمِنَ ٱلظَّـٰلِمِینَ',
    'ولئن اتيت الذين اوتوا الكتاب بكل اية ما تبعوا قبلتك وما انت بتابع قبلتهم وما بعضهم بتابع قبلة بعض ولئن اتبعت اهواءهم من بعد ما جاءك من العلم انك اذا لمن الظالمين',
    'وَلَئِنۡ أَتَيۡتَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِكُلِّ ءَايَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا تَبِعُو<rule class=slnt>اۡ</rule> قِ<rule class=qalaqah>بۡ</rule>لَتَكَ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ بِتَابِ<rule class=ikhafa>عٍ</rule> <rule class=ikhafa>ق</rule>ِ<rule class=qalaqah>بۡ</rule>لَتَهُمۡ‌ۚ وَمَا بَعۡضُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِتَابِ<rule class=ikhafa>عٍ</rule> <rule class=ikhafa>ق</rule>ِ<rule class=qalaqah>بۡ</rule>لَةَ بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَئِنِ <rule class=ham_wasl>ٱ</rule>تَّبَعۡتَ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ‌ۙ إِ<rule class=ghunnah>نّ</rule>َكَ إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٤٥',
    145, 2, 1, 22, 18, 9, 'false'
  );
  
  -- Ayah 146 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    153,
    'ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَعۡرِفُونَهُۥ كَمَا یَعۡرِفُونَ أَبۡنَاۤءَهُمۡۖ وَإِنَّ فَرِیقࣰا مِّنۡهُمۡ لَیَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ یَعۡلَمُونَ',
    'الذين اتيناهم الكتاب يعرفونه كما يعرفون ابناءهم وان فريقا منهم ليكتمون الحق وهم يعلمون',
    'ٱلَّذِينَ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يَعۡرِفُونَهُ<rule class=madda_normal>ۥ</rule> كَمَا يَعۡرِفُونَ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َ فَرِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ لَيَكۡتُمُونَ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَهُمۡ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٤٦',
    146, 2, 1, 23, 18, 9, 'false'
  );
  
  -- Ayah 147 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    154,
    'ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِینَ',
    'الحق من ربك فلا تكونن من الممترين',
    'ٱلۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۖ فَلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُمۡتَر<rule class=madda_permissible>ِي</rule>نَ ١٤٧',
    147, 2, 1, 23, 18, 9, 'false'
  );
  
  -- Ayah 148 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    155,
    'وَلِكُلࣲّ وِجۡهَةٌ هُوَ مُوَلِّیهَاۖ فَٱسۡتَبِقُوا۟ ٱلۡخَیۡرَ ٰ⁠تِۚ أَیۡنَ مَا تَكُونُوا۟ یَأۡتِ بِكُمُ ٱللَّهُ جَمِیعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'ولكل وجهة هو موليها فاستبقوا الخيرات اين ما تكونوا يات بكم الله جميعا ان الله على كل شيء قدير',
    'وَلِكُ<rule class=idgham_ghunnah>لٍّ</rule> <rule class=idgham_ghunnah>و</rule>ِ<rule class=qalaqah>جۡ</rule>هَةٌ هُوَ مُوَلِّيهَا‌ۖ فَ<rule class=ham_wasl>ٱ</rule>سۡتَبِقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تِ‌ۚ أَيۡنَ مَا تَكُونُو<rule class=slnt>اۡ</rule> يَأۡتِ بِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ جَمِيعًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١٤٨',
    148, 2, 1, 23, 19, 9, 'false'
  );
  
  -- Ayah 149 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    156,
    'وَمِنۡ حَیۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ',
    'ومن حيث خرجت فول وجهك شطر المسجد الحرام وانه للحق من ربك وما الله بغافل عما تعملون',
    'وَمِنۡ حَيۡثُ خَرَ<rule class=qalaqah>جۡ</rule>تَ فَوَلِّ وَ<rule class=qalaqah>جۡ</rule>هَكَ شَ<rule class=qalaqah>طۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَلۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>للَّهُ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٤٩',
    149, 2, 1, 23, 19, 9, 'false'
  );
  
  -- Ayah 150 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    157,
    'وَمِنۡ حَیۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَیۡثُ مَا كُنتُمۡ فَوَلُّوا۟ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا یَكُونَ لِلنَّاسِ عَلَیۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِینَ ظَلَمُوا۟ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِی وَلِأُتِمَّ نِعۡمَتِی عَلَیۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ',
    'ومن حيث خرجت فول وجهك شطر المسجد الحرام وحيث ما كنتم فولوا وجوهكم شطره لئلا يكون للناس عليكم حجة الا الذين ظلموا منهم فلا تخشوهم واخشوني ولاتم نعمتي عليكم ولعلكم تهتدون',
    'وَمِنۡ حَيۡثُ خَرَ<rule class=qalaqah>جۡ</rule>تَ فَوَلِّ وَ<rule class=qalaqah>جۡ</rule>هَكَ شَ<rule class=qalaqah>طۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ‌ۚ وَحَيۡثُ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ فَوَلُّو<rule class=slnt>اۡ</rule> وُجُوهَكُمۡ شَ<rule class=qalaqah>طۡ</rule>رَهُ<rule class=madda_normal>ۥ</rule> لِئَلَّا يَكُونَ لِل<rule class=ghunnah>نّ</rule>َاسِ عَلَيۡكُمۡ حُجَّةٌ إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَ<rule class=ham_wasl>ٱ</rule>خۡشَوۡنِى وَلِأُتِ<rule class=ghunnah>مّ</rule>َ نِعۡمَتِى عَلَيۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٥٠',
    150, 2, 1, 23, 19, 9, 'false'
  );
  
  -- Ayah 151 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    158,
    'كَمَاۤ أَرۡسَلۡنَا فِیكُمۡ رَسُولࣰا مِّنكُمۡ یَتۡلُوا۟ عَلَیۡكُمۡ ءَایَـٰتِنَا وَیُزَكِّیكُمۡ وَیُعَلِّمُكُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَیُعَلِّمُكُم مَّا لَمۡ تَكُونُوا۟ تَعۡلَمُونَ',
    'كما ارسلنا فيكم رسولا منكم يتلو عليكم اياتنا ويزكيكم ويعلمكم الكتاب والحكمة ويعلمكم ما لم تكونوا تعلمون',
    'كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا فِيكُمۡ رَسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ يَتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَيُزَكِّيكُمۡ وَيُعَلِّمُكُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَيُعَلِّمُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا لَمۡ تَكُونُو<rule class=slnt>اۡ</rule> تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٥١',
    151, 2, 1, 23, 19, 9, 'false'
  );
  
  -- Ayah 152 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    159,
    'فَٱذۡكُرُونِیۤ أَذۡكُرۡكُمۡ وَٱشۡكُرُوا۟ لِی وَلَا تَكۡفُرُونِ',
    'فاذكروني اذكركم واشكروا لي ولا تكفرون',
    'فَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُون<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَذۡكُرۡكُمۡ وَ<rule class=ham_wasl>ٱ</rule>شۡكُرُو<rule class=slnt>اۡ</rule> لِى وَلَا تَكۡفُر<rule class=madda_permissible>ُو</rule>نِ ١٥٢',
    152, 2, 1, 23, 19, 9, 'false'
  );
  
  -- Ayah 153 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    160,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱسۡتَعِینُوا۟ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِینَ',
    'يا ايها الذين امنوا استعينوا بالصبر والصلاة ان الله مع الصابرين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>سۡتَعِينُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=qalaqah>بۡ</rule>رِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ١٥٣',
    153, 2, 1, 23, 20, 9, 'false'
  );
  
  -- Ayah 154 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    161,
    'وَلَا تَقُولُوا۟ لِمَن یُقۡتَلُ فِی سَبِیلِ ٱللَّهِ أَمۡوَ ٰ⁠تُۢۚ بَلۡ أَحۡیَاۤءࣱ وَلَـٰكِن لَّا تَشۡعُرُونَ',
    'ولا تقولوا لمن يقتل في سبيل الله اموات بل احياء ولكن لا تشعرون',
    'وَلَا تَقُولُو<rule class=slnt>اۡ</rule> لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>قۡ</rule>تَلُ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَمۡو<rule class=madda_normal>ٰ</rule><rule class=iqlab>تُۢ‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ أَحۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ١٥٤',
    154, 2, 1, 24, 20, 9, 'false'
  );
  
  -- Ayah 155 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    162,
    'وَلَنَبۡلُوَنَّكُم بِشَیۡءࣲ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصࣲ مِّنَ ٱلۡأَمۡوَ ٰ⁠لِ وَٱلۡأَنفُسِ وَٱلثَّمَرَ ٰ⁠تِۗ وَبَشِّرِ ٱلصَّـٰبِرِینَ',
    'ولنبلونكم بشيء من الخوف والجوع ونقص من الاموال والانفس والثمرات وبشر الصابرين',
    'وَلَنَ<rule class=qalaqah>بۡ</rule>لُوَ<rule class=ghunnah>نّ</rule>َك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡخَوۡفِ وَ<rule class=ham_wasl>ٱ</rule>لۡجُوعِ وَنَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>صٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡو<rule class=madda_normal>ٰ</rule>لِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>ُسِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ‌ۗ وَبَشِّرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ١٥٥',
    155, 2, 1, 24, 20, 9, 'false'
  );
  
  -- Ayah 156 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    163,
    'ٱلَّذِینَ إِذَاۤ أَصَـٰبَتۡهُم مُّصِیبَةࣱ قَالُوۤا۟ إِنَّا لِلَّهِ وَإِنَّاۤ إِلَیۡهِ رَ ٰ⁠جِعُونَ',
    'الذين اذا اصابتهم مصيبة قالوا انا لله وانا اليه راجعون',
    'ٱلَّذِينَ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَصَ<rule class=madda_normal>ـٰ</rule>بَتۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّصِيبَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا لِلَّهِ وَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ ر<rule class=madda_normal>ٰ</rule>جِع<rule class=madda_permissible>ُو</rule>نَ ١٥٦',
    156, 2, 1, 24, 20, 9, 'false'
  );
  
  -- Ayah 157 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    164,
    'أُو۟لَـٰۤىِٕكَ عَلَیۡهِمۡ صَلَوَ ٰ⁠تࣱ مِّن رَّبِّهِمۡ وَرَحۡمَةࣱۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُهۡتَدُونَ',
    'اولئك عليهم صلوات من ربهم ورحمة واولئك هم المهتدون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ عَلَيۡهِمۡ صَلَو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ وَرَحۡمَ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٥٧',
    157, 2, 1, 24, 20, 9, 'false'
  );
  
  -- Ayah 158 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    165,
    '۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَاۤىِٕرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَیۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَیۡهِ أَن یَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَیۡرࣰا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِیمٌ',
    'ان الصفا والمروة من شعائر الله فمن حج البيت او اعتمر فلا جناح عليه ان يطوف بهما ومن تطوع خيرا فان الله شاكر عليم',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّفَا وَ<rule class=ham_wasl>ٱ</rule>لۡمَرۡوَةَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َع<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ فَمَنۡ حَجَّ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتَ أَوِ <rule class=ham_wasl>ٱ</rule>عۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َطَّوَّفَ بِهِمَا‌ۚ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َطَوَّعَ خَيۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَاكِرٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٥٨',
    158, 2, 1, 24, 20, 10, 'false'
  );
  
  -- Ayah 159 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    166,
    'إِنَّ ٱلَّذِینَ یَكۡتُمُونَ مَاۤ أَنزَلۡنَا مِنَ ٱلۡبَیِّنَـٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَیَّنَّـٰهُ لِلنَّاسِ فِی ٱلۡكِتَـٰبِ أُو۟لَـٰۤىِٕكَ یَلۡعَنُهُمُ ٱللَّهُ وَیَلۡعَنُهُمُ ٱللَّـٰعِنُونَ',
    'ان الذين يكتمون ما انزلنا من البينات والهدى من بعد ما بيناه للناس في الكتاب اولئك يلعنهم الله ويلعنهم اللاعنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَكۡتُمُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا بَيَّ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هُ لِل<rule class=ghunnah>نّ</rule>َاسِ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ‌ۙ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَلۡعَنُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَيَلۡعَنُهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّ<rule class=madda_normal>ـٰ</rule>عِن<rule class=madda_permissible>ُو</rule>نَ ١٥٩',
    159, 2, 1, 24, 20, 10, 'false'
  );
  
  -- Ayah 160 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    167,
    'إِلَّا ٱلَّذِینَ تَابُوا۟ وَأَصۡلَحُوا۟ وَبَیَّنُوا۟ فَأُو۟لَـٰۤىِٕكَ أَتُوبُ عَلَیۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِیمُ',
    'الا الذين تابوا واصلحوا وبينوا فاولئك اتوب عليهم وانا التواب الرحيم',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَابُو<rule class=slnt>اۡ</rule> وَأَصۡلَحُو<rule class=slnt>اۡ</rule> وَبَيَّنُو<rule class=slnt>اۡ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَتُوبُ عَلَيۡهِمۡ‌ۚ وَأَنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوَّابُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٦٠',
    160, 2, 1, 24, 20, 10, 'false'
  );
  
  -- Ayah 161 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    168,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمۡ كُفَّارٌ أُو۟لَـٰۤىِٕكَ عَلَیۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَـٰۤىِٕكَةِ وَٱلنَّاسِ أَجۡمَعِینَ',
    'ان الذين كفروا وماتوا وهم كفار اولئك عليهم لعنة الله والملائكة والناس اجمعين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَمَاتُو<rule class=slnt>اۡ</rule> وَهُمۡ كُفَّارٌ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ عَلَيۡهِمۡ لَعۡنَةُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ١٦١',
    161, 2, 1, 24, 20, 10, 'false'
  );
  
  -- Ayah 162 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    169,
    'خَـٰلِدِینَ فِیهَا لَا یُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ یُنظَرُونَ',
    'خالدين فيها لا يخفف عنهم العذاب ولا هم ينظرون',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۖ لَا يُخَفَّفُ عَنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ وَلَا هُمۡ يُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ُو</rule>نَ ١٦٢',
    162, 2, 1, 24, 20, 10, 'false'
  );
  
  -- Ayah 163 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    170,
    'وَإِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰ⁠حِدࣱۖ لَّاۤ إِلَـٰهَ إِلَّا هُوَ ٱلرَّحۡمَـٰنُ ٱلرَّحِیمُ',
    'والهكم اله واحد لا اله الا هو الرحمن الرحيم',
    'وَإِلَ<rule class=madda_normal>ـٰ</rule>هُكُمۡ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_wo_ghunnah>دٌ‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٦٣',
    163, 2, 1, 24, 20, 10, 'false'
  );
  
  -- Ayah 164 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    171,
    'إِنَّ فِی خَلۡقِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَٱخۡتِلَـٰفِ ٱلَّیۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِی تَجۡرِی فِی ٱلۡبَحۡرِ بِمَا یَنفَعُ ٱلنَّاسَ وَمَاۤ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَاۤءِ مِن مَّاۤءࣲ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِیهَا مِن كُلِّ دَاۤبَّةࣲ وَتَصۡرِیفِ ٱلرِّیَـٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَیۡنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ',
    'ان في خلق السماوات والارض واختلاف الليل والنهار والفلك التي تجري في البحر بما ينفع الناس وما انزل الله من السماء من ماء فاحيا به الارض بعد موتها وبث فيها من كل دابة وتصريف الرياح والسحاب المسخر بين السماء والارض لايات لقوم يعقلون',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى خَلۡقِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule>خۡتِلَ<rule class=madda_normal>ـٰ</rule>فِ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَ<rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ <rule class=ham_wasl>ٱ</rule>لَّتِى تَ<rule class=qalaqah>جۡ</rule>رِى فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ بِمَا يَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ف</rule>َأَحۡيَا بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ د<rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َتَصۡرِيفِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَابِ <rule class=ham_wasl>ٱ</rule>لۡمُسَخَّرِ بَيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٦٤',
    164, 2, 1, 25, 21, 10, 'false'
  );
  
  -- Ayah 165 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    172,
    'وَمِنَ ٱلنَّاسِ مَن یَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادࣰا یُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِینَ ءَامَنُوۤا۟ أَشَدُّ حُبࣰّا لِّلَّهِۗ وَلَوۡ یَرَى ٱلَّذِینَ ظَلَمُوۤا۟ إِذۡ یَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِیعࣰا وَأَنَّ ٱللَّهَ شَدِیدُ ٱلۡعَذَابِ',
    'ومن الناس من يتخذ من دون الله اندادا يحبونهم كحب الله والذين امنوا اشد حبا لله ولو يرى الذين ظلموا اذ يرون العذاب ان القوة لله جميعا وان الله شديد العذاب',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَ<rule class=ikhafa>ند</rule>َا<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>ي</rule>ُحِبُّونَهُمۡ كَحُبِّ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَشَدُّ حُب<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّهِ‌ۗ وَلَوۡ يَرَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذۡ يَرَوۡنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡقُوَّةَ لِلَّهِ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعَذ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٦٥',
    165, 2, 1, 25, 21, 10, 'false'
  );
  
  -- Ayah 166 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    173,
    'إِذۡ تَبَرَّأَ ٱلَّذِینَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِینَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ',
    'اذ تبرا الذين اتبعوا من الذين اتبعوا وراوا العذاب وتقطعت بهم الاسباب',
    'إِذۡ تَبَرَّأَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تُّبِعُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> وَرَأَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَسۡب<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ُ ١٦٦',
    166, 2, 1, 25, 21, 10, 'false'
  );
  
  -- Ayah 167 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    174,
    'وَقَالَ ٱلَّذِینَ ٱتَّبَعُوا۟ لَوۡ أَنَّ لَنَا كَرَّةࣰ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُوا۟ مِنَّاۗ كَذَ ٰ⁠لِكَ یُرِیهِمُ ٱللَّهُ أَعۡمَـٰلَهُمۡ حَسَرَ ٰ⁠تٍ عَلَیۡهِمۡۖ وَمَا هُم بِخَـٰرِجِینَ مِنَ ٱلنَّارِ',
    'وقال الذين اتبعوا لو ان لنا كرة فنتبرا منهم كما تبرءوا منا كذلك يريهم الله اعمالهم حسرات عليهم وما هم بخارجين من النار',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> لَوۡ أَ<rule class=ghunnah>نّ</rule>َ لَنَا كَرَّ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>نّ</rule>َا‌ۗ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُرِيهِمُ <rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ حَسَر<rule class=madda_normal>ٰ</rule>تٍ عَلَيۡهِمۡ‌ۖ وَمَا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَ<rule class=madda_normal>ـٰ</rule>رِجِينَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ١٦٧',
    167, 2, 1, 25, 21, 10, 'false'
  );
  
  -- Ayah 168 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    175,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِی ٱلۡأَرۡضِ حَلَـٰلࣰا طَیِّبࣰا وَلَا تَتَّبِعُوا۟ خُطُوَ ٰ⁠تِ ٱلشَّیۡطَـٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینٌ',
    'يا ايها الناس كلوا مما في الارض حلالا طيبا ولا تتبعوا خطوات الشيطان انه لكم عدو مبين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ كُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ حَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ط</rule>َيِّ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَتَّبِعُو<rule class=slnt>اۡ</rule> خُطُو<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَكُمۡ عَدُ<rule class=idgham_ghunnah>وٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٦٨',
    168, 2, 1, 25, 22, 10, 'false'
  );
  
  -- Ayah 169 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    176,
    'إِنَّمَا یَأۡمُرُكُم بِٱلسُّوۤءِ وَٱلۡفَحۡشَاۤءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ',
    'انما يامركم بالسوء والفحشاء وان تقولوا على الله ما لا تعلمون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا يَأۡمُرُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡفَحۡش<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٦٩',
    169, 2, 1, 25, 22, 10, 'false'
  );
  
  -- Ayah 170 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    177,
    'وَإِذَا قِیلَ لَهُمُ ٱتَّبِعُوا۟ مَاۤ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلۡ نَتَّبِعُ مَاۤ أَلۡفَیۡنَا عَلَیۡهِ ءَابَاۤءَنَاۤۚ أَوَلَوۡ كَانَ ءَابَاۤؤُهُمۡ لَا یَعۡقِلُونَ شَیۡـࣰٔا وَلَا یَهۡتَدُونَ',
    'واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما الفينا عليه اباءنا اولو كان اباؤهم لا يعقلون شيئا ولا يهتدون',
    'وَإِذَا قِيلَ لَهُمُ <rule class=ham_wasl>ٱ</rule>تَّبِعُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ قَالُو<rule class=slnt>اۡ</rule> بَلۡ نَتَّبِعُ م<rule class=madda_obligatory_monfasel>َآ</rule> أَلۡفَيۡنَا عَلَيۡهِ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَن<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> أَوَلَوۡ كَانَ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٧٠',
    170, 2, 1, 26, 22, 10, 'false'
  );
  
  -- Ayah 171 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    178,
    'وَمَثَلُ ٱلَّذِینَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِی یَنۡعِقُ بِمَا لَا یَسۡمَعُ إِلَّا دُعَاۤءࣰ وَنِدَاۤءࣰۚ صُمُّۢ بُكۡمٌ عُمۡیࣱ فَهُمۡ لَا یَعۡقِلُونَ',
    'ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع الا دعاء ونداء صم بكم عمي فهم لا يعقلون',
    'وَمَثَلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> كَمَثَلِ <rule class=ham_wasl>ٱ</rule>لَّذِى يَنۡعِقُ بِمَا لَا يَسۡمَعُ إِلَّا دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َنِد<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً‌ۚ</rule> <rule class=ikhafa>ص</rule>ُم<rule class=iqlab>ُّۢ</rule> <rule class=iqlab>ب</rule>ُكۡمٌ عُمۡ<rule class=ikhafa>ىٌ</rule> <rule class=ikhafa>ف</rule>َهُمۡ لَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٧١',
    171, 2, 1, 26, 22, 10, 'false'
  );
  
  -- Ayah 172 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    179,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡ وَٱشۡكُرُوا۟ لِلَّهِ إِن كُنتُمۡ إِیَّاهُ تَعۡبُدُونَ',
    'يا ايها الذين امنوا كلوا من طيبات ما رزقناكم واشكروا لله ان كنتم اياه تعبدون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> كُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=madda_normal>ـٰ</rule>تِ مَا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ وَ<rule class=ham_wasl>ٱ</rule>شۡكُرُو<rule class=slnt>اۡ</rule> لِلَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ إِيَّاهُ تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ١٧٢',
    172, 2, 1, 26, 22, 10, 'false'
  );
  
  -- Ayah 173 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    180,
    'إِنَّمَا حَرَّمَ عَلَیۡكُمُ ٱلۡمَیۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِیرِ وَمَاۤ أُهِلَّ بِهِۦ لِغَیۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَیۡرَ بَاغࣲ وَلَا عَادࣲ فَلَاۤ إِثۡمَ عَلَیۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ',
    'انما حرم عليكم الميتة والدم ولحم الخنزير وما اهل به لغير الله فمن اضطر غير باغ ولا عاد فلا اثم عليه ان الله غفور رحيم',
    'إِ<rule class=ghunnah>نّ</rule>َمَا حَرَّمَ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَيۡتَةَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّمَ وَلَحۡمَ <rule class=ham_wasl>ٱ</rule>لۡخِ<rule class=ikhafa>نز</rule>ِيرِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُهِلَّ بِه<rule class=madda_normal>ِۦ</rule> لِغَيۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ فَمَنِ <rule class=ham_wasl>ٱ</rule>ضۡطُرَّ غَيۡرَ بَا<rule class=idgham_ghunnah>غٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا عَا<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>َل<rule class=madda_obligatory_monfasel>َآ</rule> إِثۡمَ عَلَيۡهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٧٣',
    173, 2, 1, 26, 22, 10, 'false'
  );
  
  -- Ayah 174 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    181,
    'إِنَّ ٱلَّذِینَ یَكۡتُمُونَ مَاۤ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَـٰبِ وَیَشۡتَرُونَ بِهِۦ ثَمَنࣰا قَلِیلًا أُو۟لَـٰۤىِٕكَ مَا یَأۡكُلُونَ فِی بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا یُكَلِّمُهُمُ ٱللَّهُ یَوۡمَ ٱلۡقِیَـٰمَةِ وَلَا یُزَكِّیهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمٌ',
    'ان الذين يكتمون ما انزل الله من الكتاب ويشترون به ثمنا قليلا اولئك ما ياكلون في بطونهم الا النار ولا يكلمهم الله يوم القيامة ولا يزكيهم ولهم عذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَكۡتُمُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَيَشۡتَرُونَ بِه<rule class=madda_normal>ِۦ</rule> ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيلاً‌ۙ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مَا يَأۡكُلُونَ فِى بُطُونِهِمۡ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ وَلَا يُكَلِّمُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١٧٤',
    174, 2, 1, 26, 22, 10, 'false'
  );
  
  -- Ayah 175 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    182,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَاۤ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ',
    'اولئك الذين اشتروا الضلالة بالهدى والعذاب بالمغفرة فما اصبرهم على النار',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>شۡتَرَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لَةَ بِ<rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡعَذَابَ بِ<rule class=ham_wasl>ٱ</rule>لۡمَغۡفِرَةِ‌ۚ فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَصۡبَرَهُمۡ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ١٧٥',
    175, 2, 1, 26, 22, 10, 'false'
  );
  
  -- Ayah 176 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    183,
    'ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِینَ ٱخۡتَلَفُوا۟ فِی ٱلۡكِتَـٰبِ لَفِی شِقَاقِۭ بَعِیدࣲ',
    'ذلك بان الله نزل الكتاب بالحق وان الذين اختلفوا في الكتاب لفي شقاق بعيد',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ نَزَّلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَفِى شِقَا<rule class=iqlab>قِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ١٧٦',
    176, 2, 1, 26, 22, 10, 'false'
  );
  
  -- Ayah 177 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    184,
    '۞ لَّیۡسَ ٱلۡبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَـٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَٱلۡمَلَـٰۤىِٕكَةِ وَٱلۡكِتَـٰبِ وَٱلنَّبِیِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینَ وَٱبۡنَ ٱلسَّبِیلِ وَٱلسَّاۤىِٕلِینَ وَفِی ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَـٰهَدُوا۟ۖ وَٱلصَّـٰبِرِینَ فِی ٱلۡبَأۡسَاۤءِ وَٱلضَّرَّاۤءِ وَحِینَ ٱلۡبَأۡسِۗ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ صَدَقُوا۟ۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُتَّقُونَ',
    'ليس البر ان تولوا وجوهكم قبل المشرق والمغرب ولكن البر من امن بالله واليوم الاخر والملائكة والكتاب والنبيين واتى المال على حبه ذوي القربى واليتامى والمساكين وابن السبيل والسائلين وفي الرقاب واقام الصلاة واتى الزكاة والموفون بعهدهم اذا عاهدوا والصابرين في الباساء والضراء وحين الباس اولئك الذين صدقوا واولئك هم المتقون',
    '۞لَّيۡسَ <rule class=ham_wasl>ٱ</rule>لۡبِرَّ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُوَلُّو<rule class=slnt>اۡ</rule> وُجُوهَكُمۡ قِبَلَ <rule class=ham_wasl>ٱ</rule>لۡمَشۡرِقِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَغۡرِبِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡبِرَّ مَنۡ ءَامَنَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ وَ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ وَءَاتَى <rule class=ham_wasl>ٱ</rule>لۡمَالَ عَلَىٰ حُبِّه<rule class=madda_normal>ِۦ</rule> ذَوِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِلِينَ وَفِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّقَابِ وَأَقَامَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ‌ۖ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِرِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡبَأۡس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَحِينَ <rule class=ham_wasl>ٱ</rule>لۡبَأۡسِ‌ۗ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ صَدَقُو<rule class=slnt>اۡ‌ۖ</rule> وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ُو</rule>نَ ١٧٧',
    177, 2, 1, 27, 23, 11, 'false'
  );
  
  -- Ayah 178 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    185,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُتِبَ عَلَیۡكُمُ ٱلۡقِصَاصُ فِی ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِیَ لَهُۥ مِنۡ أَخِیهِ شَیۡءࣱ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَاۤءٌ إِلَیۡهِ بِإِحۡسَـٰنࣲۗ ذَ ٰ⁠لِكَ تَخۡفِیفࣱ مِّن رَّبِّكُمۡ وَرَحۡمَةࣱۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَ ٰ⁠لِكَ فَلَهُۥ عَذَابٌ أَلِیمࣱ',
    'يا ايها الذين امنوا كتب عليكم القصاص في القتلى الحر بالحر والعبد بالعبد والانثى بالانثى فمن عفي له من اخيه شيء فاتباع بالمعروف واداء اليه باحسان ذلك تخفيف من ربكم ورحمة فمن اعتدى بعد ذلك فله عذاب اليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> كُتِبَ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡقِصَاصُ فِى <rule class=ham_wasl>ٱ</rule>لۡقَتۡلَى‌ۖ <rule class=ham_wasl>ٱ</rule>لۡحُرُّ بِ<rule class=ham_wasl>ٱ</rule>لۡحُرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>بۡ</rule>دُ بِ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>بۡ</rule>دِ وَ<rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َىٰ بِ<rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َىٰ‌ۚ فَمَنۡ عُفِىَ لَهُ<rule class=madda_normal>ۥ</rule> مِنۡ أَخِيهِ ش<rule class=ikhafa>َىۡءٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>تِّبَا<rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَأَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ إِلَيۡهِ بِإِحۡسَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نٍ‌ۗ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ تَخۡفِي<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَرَحۡمَ<rule class=ikhafa>ةٌ‌ۗ</rule> <rule class=ikhafa>ف</rule>َمَنِ <rule class=ham_wasl>ٱ</rule>عۡتَدَىٰ بَعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَلَهُ<rule class=madda_normal>ۥ</rule> عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١٧٨',
    178, 2, 1, 27, 23, 11, 'false'
  );
  
  -- Ayah 179 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    186,
    'وَلَكُمۡ فِی ٱلۡقِصَاصِ حَیَوٰةࣱ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ لَعَلَّكُمۡ تَتَّقُونَ',
    'ولكم في القصاص حياة يا اولي الالباب لعلكم تتقون',
    'وَلَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡقِصَاصِ حَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_normal>ـٰ</rule>بِ لَعَلَّكُمۡ تَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٧٩',
    179, 2, 1, 27, 23, 11, 'false'
  );
  
  -- Ayah 180 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    187,
    'كُتِبَ عَلَیۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَیۡرًا ٱلۡوَصِیَّةُ لِلۡوَ ٰ⁠لِدَیۡنِ وَٱلۡأَقۡرَبِینَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِینَ',
    'كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصية للوالدين والاقربين بالمعروف حقا على المتقين',
    'كُتِبَ عَلَيۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرَكَ خَيۡرًا <rule class=ham_wasl>ٱ</rule>لۡوَصِيَّةُ لِلۡو<rule class=madda_normal>ٰ</rule>لِدَيۡنِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>رَبِينَ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۖ حَقًّا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ١٨٠',
    180, 2, 1, 27, 23, 11, 'false'
  );
  
  -- Ayah 181 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    188,
    'فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَاۤ إِثۡمُهُۥ عَلَى ٱلَّذِینَ یُبَدِّلُونَهُۥۤۚ إِنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ',
    'فمن بدله بعدما سمعه فانما اثمه على الذين يبدلونه ان الله سميع عليم',
    'فَم<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>َدَّلَهُ<rule class=madda_normal>ۥ</rule> بَعۡدَ مَا سَمِعَهُ<rule class=madda_normal>ۥ</rule> فَإِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> إِثۡمُهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُبَدِّلُونَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٨١',
    181, 2, 1, 27, 23, 11, 'false'
  );
  
  -- Ayah 182 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    189,
    'فَمَنۡ خَافَ مِن مُّوصࣲ جَنَفًا أَوۡ إِثۡمࣰا فَأَصۡلَحَ بَیۡنَهُمۡ فَلَاۤ إِثۡمَ عَلَیۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'فمن خاف من موص جنفا او اثما فاصلح بينهم فلا اثم عليه ان الله غفور رحيم',
    'فَمَنۡ خَافَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّو<rule class=ikhafa>صٍ</rule> <rule class=ikhafa>ج</rule>َنَفًا أَوۡ إِثۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َأَصۡلَحَ بَيۡنَهُمۡ فَل<rule class=madda_obligatory_monfasel>َآ</rule> إِثۡمَ عَلَيۡهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٨٢',
    182, 2, 1, 28, 23, 11, 'false'
  );
  
  -- Ayah 183 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    190,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُتِبَ عَلَیۡكُمُ ٱلصِّیَامُ كَمَا كُتِبَ عَلَى ٱلَّذِینَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ',
    'يا ايها الذين امنوا كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> كُتِبَ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّيَامُ كَمَا كُتِبَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ لَعَلَّكُمۡ تَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٨٣',
    183, 2, 1, 28, 24, 11, 'false'
  );
  
  -- Ayah 184 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    191,
    'أَیَّامࣰا مَّعۡدُودَ ٰ⁠تࣲۚ فَمَن كَانَ مِنكُم مَّرِیضًا أَوۡ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ مِّنۡ أَیَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِینَ یُطِیقُونَهُۥ فِدۡیَةࣱ طَعَامُ مِسۡكِینࣲۖ فَمَن تَطَوَّعَ خَیۡرࣰا فَهُوَ خَیۡرࣱ لَّهُۥۚ وَأَن تَصُومُوا۟ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ',
    'اياما معدودات فمن كان منكم مريضا او على سفر فعدة من ايام اخر وعلى الذين يطيقونه فدية طعام مسكين فمن تطوع خيرا فهو خير له وان تصوموا خير لكم ان كنتم تعلمون',
    'أَيَّا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّعۡدُود<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرِيضًا أَوۡ عَلَىٰ سَفَ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َعِدَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَيَّامٍ أُخَرَ‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُطِيقُونَهُ<rule class=madda_normal>ۥ</rule> فِ<rule class=qalaqah>دۡ</rule>يَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ط</rule>َعَامُ مِسۡكِي<rule class=ikhafa>نٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َطَوَّعَ خَيۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َهُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصُومُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٨٤',
    184, 2, 1, 28, 24, 11, 'false'
  );
  
  -- Ayah 185 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    192,
    'شَهۡرُ رَمَضَانَ ٱلَّذِیۤ أُنزِلَ فِیهِ ٱلۡقُرۡءَانُ هُدࣰى لِّلنَّاسِ وَبَیِّنَـٰتࣲ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡیَصُمۡهُۖ وَمَن كَانَ مَرِیضًا أَوۡ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ مِّنۡ أَیَّامٍ أُخَرَۗ یُرِیدُ ٱللَّهُ بِكُمُ ٱلۡیُسۡرَ وَلَا یُرِیدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُوا۟ ٱلۡعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ',
    'شهر رمضان الذي انزل فيه القران هدى للناس وبينات من الهدى والفرقان فمن شهد منكم الشهر فليصمه ومن كان مريضا او على سفر فعدة من ايام اخر يريد الله بكم اليسر ولا يريد بكم العسر ولتكملوا العدة ولتكبروا الله على ما هداكم ولعلكم تشكرون',
    'شَهۡرُ رَمَضَانَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ فِيهِ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانُ هُ<rule class=idgham_wo_ghunnah>دًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ وَبَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡفُرۡقَانِ‌ۚ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َهِدَ مِ<rule class=ikhafa>نك</rule>ُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهۡرَ فَلۡيَصُمۡهُ‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مَرِيضًا أَوۡ عَلَىٰ سَفَ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َعِدَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَيَّامٍ أُخَرَ‌ۗ يُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِكُمُ <rule class=ham_wasl>ٱ</rule>لۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ <rule class=ham_wasl>ٱ</rule>لۡعُسۡرَ وَلِتُكۡمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِدَّةَ وَلِتُكَبِّرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ مَا هَدَ<rule class=madda_normal>ٮٰ</rule>كُمۡ وَلَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٨٥',
    185, 2, 1, 28, 24, 11, 'false'
  );
  
  -- Ayah 186 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    193,
    'وَإِذَا سَأَلَكَ عِبَادِی عَنِّی فَإِنِّی قَرِیبٌۖ أُجِیبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡیَسۡتَجِیبُوا۟ لِی وَلۡیُؤۡمِنُوا۟ بِی لَعَلَّهُمۡ یَرۡشُدُونَ',
    'واذا سالك عبادي عني فاني قريب اجيب دعوة الداع اذا دعان فليستجيبوا لي وليؤمنوا بي لعلهم يرشدون',
    'وَإِذَا سَأَلَكَ عِبَادِى عَ<rule class=ghunnah>نّ</rule>ِى فَإِ<rule class=ghunnah>نّ</rule>ِى قَرِيبٌ‌ۖ أُجِيبُ دَعۡوَةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّاعِ إِذَا دَعَانِ‌ۖ فَلۡيَسۡتَجِيبُو<rule class=slnt>اۡ</rule> لِى وَلۡيُؤۡمِنُو<rule class=slnt>اۡ</rule> بِى لَعَلَّهُمۡ يَرۡشُد<rule class=madda_permissible>ُو</rule>نَ ١٨٦',
    186, 2, 1, 28, 24, 11, 'false'
  );
  
  -- Ayah 187 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    194,
    'أُحِلَّ لَكُمۡ لَیۡلَةَ ٱلصِّیَامِ ٱلرَّفَثُ إِلَىٰ نِسَاۤىِٕكُمۡۚ هُنَّ لِبَاسࣱ لَّكُمۡ وَأَنتُمۡ لِبَاسࣱ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَیۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٔـٰنَ بَـٰشِرُوهُنَّ وَٱبۡتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُوا۟ وَٱشۡرَبُوا۟ حَتَّىٰ یَتَبَیَّنَ لَكُمُ ٱلۡخَیۡطُ ٱلۡأَبۡیَضُ مِنَ ٱلۡخَیۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّوا۟ ٱلصِّیَامَ إِلَى ٱلَّیۡلِۚ وَلَا تُبَـٰشِرُوهُنَّ وَأَنتُمۡ عَـٰكِفُونَ فِی ٱلۡمَسَـٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ ءَایَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ یَتَّقُونَ',
    'احل لكم ليلة الصيام الرفث الى نسائكم هن لباس لكم وانتم لباس لهن علم الله انكم كنتم تختانون انفسكم فتاب عليكم وعفا عنكم فالان باشروهن وابتغوا ما كتب الله لكم وكلوا واشربوا حتى يتبين لكم الخيط الابيض من الخيط الاسود من الفجر ثم اتموا الصيام الى الليل ولا تباشروهن وانتم عاكفون في المساجد تلك حدود الله فلا تقربوها كذلك يبين الله اياته للناس لعلهم يتقون',
    'أُحِلَّ لَكُمۡ لَيۡلَةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّيَامِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّفَثُ إِلَىٰ نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ‌ۚ هُ<rule class=ghunnah>نّ</rule>َ لِبَا<rule class=idgham_wo_ghunnah>سٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لِبَا<rule class=idgham_wo_ghunnah>سٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=ghunnah>نّ</rule>َ‌ۗ عَلِمَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=ghunnah>نّ</rule>َكُمۡ كُ<rule class=ikhafa>نت</rule>ُمۡ تَخۡتَانُونَ أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَ<rule class=ikhafa>نك</rule>ُمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>لۡـَٔ<rule class=madda_normal>ـٰ</rule>نَ بَ<rule class=madda_normal>ـٰ</rule>شِرُوهُ<rule class=ghunnah>نّ</rule>َ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> مَا كَتَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ‌ۚ وَكُلُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>شۡرَبُو<rule class=slnt>اۡ</rule> حَتَّىٰ يَتَبَيَّنَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡخَيۡطُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>يَضُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَيۡطِ <rule class=ham_wasl>ٱ</rule>لۡأَسۡوَدِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=qalaqah>جۡ</rule>رِ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ أَتِ<rule class=ghunnah>مّ</rule>ُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّيَامَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّيۡلِ‌ۚ وَلَا تُبَ<rule class=madda_normal>ـٰ</rule>شِرُوهُ<rule class=ghunnah>نّ</rule>َ وَأَ<rule class=ikhafa>نت</rule>ُمۡ عَ<rule class=madda_normal>ـٰ</rule>كِفُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>جِدِ‌ۗ تِلۡكَ حُدُودُ <rule class=ham_wasl>ٱ</rule>للَّهِ فَلَا تَ<rule class=qalaqah>قۡ</rule>رَبُوهَا‌ۗ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> لِل<rule class=ghunnah>نّ</rule>َاسِ لَعَلَّهُمۡ يَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٨٧',
    187, 2, 1, 29, 24, 11, 'false'
  );
  
  -- Ayah 188 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    195,
    'وَلَا تَأۡكُلُوۤا۟ أَمۡوَ ٰ⁠لَكُم بَیۡنَكُم بِٱلۡبَـٰطِلِ وَتُدۡلُوا۟ بِهَاۤ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُوا۟ فَرِیقࣰا مِّنۡ أَمۡوَ ٰ⁠لِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ',
    'ولا تاكلوا اموالكم بينكم بالباطل وتدلوا بها الى الحكام لتاكلوا فريقا من اموال الناس بالاثم وانتم تعلمون',
    'وَلَا تَأۡكُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ وَتُ<rule class=qalaqah>دۡ</rule>لُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡحُكَّامِ لِتَأۡكُلُو<rule class=slnt>اۡ</rule> فَرِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَمۡو<rule class=madda_normal>ٰ</rule>لِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِ<rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٨٨',
    188, 2, 1, 29, 24, 11, 'false'
  );
  
  -- Ayah 189 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    196,
    '۞ یَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِیَ مَوَ ٰ⁠قِیتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَیۡسَ ٱلۡبِرُّ بِأَن تَأۡتُوا۟ ٱلۡبُیُوتَ مِن ظُهُورِهَا وَلَـٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُوا۟ ٱلۡبُیُوتَ مِنۡ أَبۡوَ ٰ⁠بِهَاۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ',
    'يسالونك عن الاهلة قل هي مواقيت للناس والحج وليس البر بان تاتوا البيوت من ظهورها ولكن البر من اتقى واتوا البيوت من ابوابها واتقوا الله لعلكم تفلحون',
    '۞يَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡأَهِلَّةِ‌ۖ قُلۡ هِىَ مَو<rule class=madda_normal>ٰ</rule>قِيتُ لِل<rule class=ghunnah>نّ</rule>َاسِ وَ<rule class=ham_wasl>ٱ</rule>لۡحَجِّ‌ۗ وَلَيۡسَ <rule class=ham_wasl>ٱ</rule>لۡبِرُّ بِأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡبُيُوتَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>ُهُورِهَا وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡبِرَّ مَنِ <rule class=ham_wasl>ٱ</rule>تَّقَىٰ‌ۗ وَأۡتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡبُيُوتَ مِنۡ أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بِهَا‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٨٩',
    189, 2, 1, 29, 25, 12, 'false'
  );
  
  -- Ayah 190 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    197,
    'وَقَـٰتِلُوا۟ فِی سَبِیلِ ٱللَّهِ ٱلَّذِینَ یُقَـٰتِلُونَكُمۡ وَلَا تَعۡتَدُوۤا۟ۚ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡمُعۡتَدِینَ',
    'وقاتلوا في سبيل الله الذين يقاتلونكم ولا تعتدوا ان الله لا يحب المعتدين',
    'وَقَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَكُمۡ وَلَا تَعۡتَد<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُعۡتَد<rule class=madda_permissible>ِي</rule>نَ ١٩٠',
    190, 2, 1, 29, 25, 12, 'false'
  );
  
  -- Ayah 191 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    198,
    'وَٱقۡتُلُوهُمۡ حَیۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَیۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَـٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ یُقَـٰتِلُوكُمۡ فِیهِۖ فَإِن قَـٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَ ٰ⁠لِكَ جَزَاۤءُ ٱلۡكَـٰفِرِینَ',
    'واقتلوهم حيث ثقفتموهم واخرجوهم من حيث اخرجوكم والفتنة اشد من القتل ولا تقاتلوهم عند المسجد الحرام حتى يقاتلوكم فيه فان قاتلوكم فاقتلوهم كذلك جزاء الكافرين',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ حَيۡثُ أَخۡرَجُوكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡفِتۡنَةُ أَشَدُّ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَتۡلِ‌ۚ وَلَا تُقَ<rule class=madda_normal>ـٰ</rule>تِلُوهُمۡ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ حَتَّىٰ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُوكُمۡ فِيهِ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=madda_normal>ـٰ</rule>تَلُوكُمۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُلُوهُمۡ‌ۗ كَذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٩١',
    191, 2, 1, 30, 25, 12, 'false'
  );
  
  -- Ayah 192 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    199,
    'فَإِنِ ٱنتَهَوۡا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'فان انتهوا فان الله غفور رحيم',
    'فَإِنِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َهَوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٩٢',
    192, 2, 1, 30, 25, 12, 'false'
  );
  
  -- Ayah 193 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    200,
    'وَقَـٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةࣱ وَیَكُونَ ٱلدِّینُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡا۟ فَلَا عُدۡوَ ٰ⁠نَ إِلَّا عَلَى ٱلظَّـٰلِمِینَ',
    'وقاتلوهم حتى لا تكون فتنة ويكون الدين لله فان انتهوا فلا عدوان الا على الظالمين',
    'وَقَ<rule class=madda_normal>ـٰ</rule>تِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َيَكُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينُ لِلَّهِ‌ۖ فَإِنِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َهَوۡ<rule class=slnt>اۡ</rule> فَلَا عُ<rule class=qalaqah>دۡ</rule>و<rule class=madda_normal>ٰ</rule>نَ إِلَّا عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٩٣',
    193, 2, 1, 30, 25, 12, 'false'
  );
  
  -- Ayah 194 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    201,
    'ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَـٰتُ قِصَاصࣱۚ فَمَنِ ٱعۡتَدَىٰ عَلَیۡكُمۡ فَٱعۡتَدُوا۟ عَلَیۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَیۡكُمۡۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِینَ',
    'الشهر الحرام بالشهر الحرام والحرمات قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم واتقوا الله واعلموا ان الله مع المتقين',
    'ٱ<rule class=laam_shamsiyah>ل</rule>شَّهۡرُ <rule class=ham_wasl>ٱ</rule>لۡحَرَامُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ وَ<rule class=ham_wasl>ٱ</rule>لۡحُرُمَ<rule class=madda_normal>ـٰ</rule>تُ قِصَا<rule class=ikhafa>صٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َمَنِ <rule class=ham_wasl>ٱ</rule>عۡتَدَىٰ عَلَيۡكُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡتَدُو<rule class=slnt>اۡ</rule> عَلَيۡهِ بِمِثۡلِ مَا <rule class=ham_wasl>ٱ</rule>عۡتَدَىٰ عَلَيۡكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَعَ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ١٩٤',
    194, 2, 1, 30, 25, 12, 'false'
  );
  
  -- Ayah 195 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    202,
    'وَأَنفِقُوا۟ فِی سَبِیلِ ٱللَّهِ وَلَا تُلۡقُوا۟ بِأَیۡدِیكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوۤا۟ۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُحۡسِنِینَ',
    'وانفقوا في سبيل الله ولا تلقوا بايديكم الى التهلكة واحسنوا ان الله يحب المحسنين',
    'وَأَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا تُلۡقُو<rule class=slnt>اۡ</rule> بِأَيۡدِيكُمۡ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّهۡلُكَةِ‌ۛ وَأَحۡسِن<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۛ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٩٥',
    195, 2, 1, 30, 25, 12, 'false'
  );
  
  -- Ayah 196 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    203,
    'وَأَتِمُّوا۟ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَیۡسَرَ مِنَ ٱلۡهَدۡیِۖ وَلَا تَحۡلِقُوا۟ رُءُوسَكُمۡ حَتَّىٰ یَبۡلُغَ ٱلۡهَدۡیُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِیضًا أَوۡ بِهِۦۤ أَذࣰى مِّن رَّأۡسِهِۦ فَفِدۡیَةࣱ مِّن صِیَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكࣲۚ فَإِذَاۤ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَیۡسَرَ مِنَ ٱلۡهَدۡیِۚ فَمَن لَّمۡ یَجِدۡ فَصِیَامُ ثَلَـٰثَةِ أَیَّامࣲ فِی ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةࣱ كَامِلَةࣱۗ ذَ ٰ⁠لِكَ لِمَن لَّمۡ یَكُنۡ أَهۡلُهُۥ حَاضِرِی ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ',
    'واتموا الحج والعمرة لله فان احصرتم فما استيسر من الهدي ولا تحلقوا رءوسكم حتى يبلغ الهدي محله فمن كان منكم مريضا او به اذى من راسه ففدية من صيام او صدقة او نسك فاذا امنتم فمن تمتع بالعمرة الى الحج فما استيسر من الهدي فمن لم يجد فصيام ثلاثة ايام في الحج وسبعة اذا رجعتم تلك عشرة كاملة ذلك لمن لم يكن اهله حاضري المسجد الحرام واتقوا الله واعلموا ان الله شديد العقاب',
    'وَأَتِ<rule class=ghunnah>مّ</rule>ُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَجَّ وَ<rule class=ham_wasl>ٱ</rule>لۡعُمۡرَةَ لِلَّهِ‌ۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا <rule class=ham_wasl>ٱ</rule>سۡتَيۡسَرَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡهَ<rule class=qalaqah>دۡ</rule>ىِ‌ۖ وَلَا تَحۡلِقُو<rule class=slnt>اۡ</rule> رُءُوسَكُمۡ حَتَّىٰ يَ<rule class=qalaqah>بۡ</rule>لُغَ <rule class=ham_wasl>ٱ</rule>لۡهَ<rule class=qalaqah>دۡ</rule>ىُ مَحِلَّهُ<rule class=madda_normal>ۥ</rule>‌ۚ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرِيضًا أَوۡ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَ<rule class=idgham_ghunnah>ذًى</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّأۡسِه<rule class=madda_normal>ِۦ</rule> فَفِ<rule class=qalaqah>دۡ</rule>يَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>ِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُ<rule class=ikhafa>كٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَمِ<rule class=ikhafa>نت</rule>ُمۡ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمَتَّعَ بِ<rule class=ham_wasl>ٱ</rule>لۡعُمۡرَةِ إِلَى <rule class=ham_wasl>ٱ</rule>لۡحَجِّ فَمَا <rule class=ham_wasl>ٱ</rule>سۡتَيۡسَرَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡهَ<rule class=qalaqah>دۡ</rule>ىِ‌ۚ فَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَجِ<rule class=qalaqah>دۡ</rule> فَصِيَامُ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَةِ أَيَّا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡحَجِّ وَسَ<rule class=qalaqah>بۡ</rule>عَةٍ إِذَا رَجَعۡتُمۡ‌ۗ تِلۡكَ عَشَرَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ك</rule>َامِلَ<rule class=ikhafa>ةٌ‌ۗ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ لِم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَكُنۡ أَهۡلُهُ<rule class=madda_normal>ۥ</rule> حَاضِرِى <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٩٦',
    196, 2, 1, 30, 25, 12, 'false'
  );
  
  -- Ayah 197 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    204,
    'ٱلۡحَجُّ أَشۡهُرࣱ مَّعۡلُومَـٰتࣱۚ فَمَن فَرَضَ فِیهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِی ٱلۡحَجِّۗ وَمَا تَفۡعَلُوا۟ مِنۡ خَیۡرࣲ یَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُوا۟ فَإِنَّ خَیۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ',
    'الحج اشهر معلومات فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج وما تفعلوا من خير يعلمه الله وتزودوا فان خير الزاد التقوى واتقون يا اولي الالباب',
    'ٱلۡحَجُّ أَشۡهُ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡلُومَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َرَضَ فِيهِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى <rule class=ham_wasl>ٱ</rule>لۡحَجِّ‌ۗ وَمَا تَفۡعَلُو<rule class=slnt>اۡ</rule> مِنۡ خَيۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَمۡهُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ وَتَزَوَّدُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ خَيۡرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّادِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=qalaqah>قۡ</rule>وَىٰ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُونِ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ١٩٧',
    197, 2, 1, 31, 26, 12, 'false'
  );
  
  -- Ayah 198 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    205,
    'لَیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَن تَبۡتَغُوا۟ فَضۡلࣰا مِّن رَّبِّكُمۡۚ فَإِذَاۤ أَفَضۡتُم مِّنۡ عَرَفَـٰتࣲ فَٱذۡكُرُوا۟ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّاۤلِّینَ',
    'ليس عليكم جناح ان تبتغوا فضلا من ربكم فاذا افضتم من عرفات فاذكروا الله عند المشعر الحرام واذكروه كما هداكم وان كنتم من قبله لمن الضالين',
    'لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> فَضۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۚ فَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَفَضۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَرَفَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمَشۡعَرِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُوهُ كَمَا هَدَ<rule class=madda_normal>ٮٰ</rule>كُمۡ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضّ<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ِي</rule>نَ ١٩٨',
    198, 2, 1, 31, 26, 12, 'false'
  );
  
  -- Ayah 199 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    206,
    'ثُمَّ أَفِیضُوا۟ مِنۡ حَیۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'ثم افيضوا من حيث افاض الناس واستغفروا الله ان الله غفور رحيم',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَفِيضُو<rule class=slnt>اۡ</rule> مِنۡ حَيۡثُ أَفَاضَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٩٩',
    199, 2, 1, 31, 26, 12, 'false'
  );
  
  -- Ayah 200 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    207,
    'فَإِذَا قَضَیۡتُم مَّنَـٰسِكَكُمۡ فَٱذۡكُرُوا۟ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَاۤءَكُمۡ أَوۡ أَشَدَّ ذِكۡرࣰاۗ فَمِنَ ٱلنَّاسِ مَن یَقُولُ رَبَّنَاۤ ءَاتِنَا فِی ٱلدُّنۡیَا وَمَا لَهُۥ فِی ٱلۡـَٔاخِرَةِ مِنۡ خَلَـٰقࣲ',
    'فاذا قضيتم مناسككم فاذكروا الله كذكركم اباءكم او اشد ذكرا فمن الناس من يقول ربنا اتنا في الدنيا وما له في الاخرة من خلاق',
    'فَإِذَا قَضَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنَ<rule class=madda_normal>ـٰ</rule>سِكَكُمۡ فَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ كَذِكۡرِكُمۡ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ أَوۡ أَشَدَّ ذِكۡ<rule class=ikhafa>رًا‌ۗ</rule> <rule class=ikhafa>ف</rule>َمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتِنَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَمَا لَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ مِنۡ خَلَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ق</rule>ٍ ٢٠٠',
    200, 2, 1, 31, 26, 12, 'false'
  );
  
  -- Ayah 201 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    208,
    'وَمِنۡهُم مَّن یَقُولُ رَبَّنَاۤ ءَاتِنَا فِی ٱلدُّنۡیَا حَسَنَةࣰ وَفِی ٱلۡـَٔاخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ',
    'ومنهم من يقول ربنا اتنا في الدنيا حسنة وفي الاخرة حسنة وقنا عذاب النار',
    'وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتِنَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا حَسَنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َفِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ حَسَنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َقِنَا عَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٢٠١',
    201, 2, 1, 31, 26, 12, 'false'
  );
  
  -- Ayah 202 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    209,
    'أُو۟لَـٰۤىِٕكَ لَهُمۡ نَصِیبࣱ مِّمَّا كَسَبُوا۟ۚ وَٱللَّهُ سَرِیعُ ٱلۡحِسَابِ',
    'اولئك لهم نصيب مما كسبوا والله سريع الحساب',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ نَصِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا كَسَبُو<rule class=slnt>اۡ‌ۚ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢٠٢',
    202, 2, 1, 31, 26, 12, 'false'
  );
  
  -- Ayah 203 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    210,
    '۞ وَٱذۡكُرُوا۟ ٱللَّهَ فِیۤ أَیَّامࣲ مَّعۡدُودَ ٰ⁠تࣲۚ فَمَن تَعَجَّلَ فِی یَوۡمَیۡنِ فَلَاۤ إِثۡمَ عَلَیۡهِ وَمَن تَأَخَّرَ فَلَاۤ إِثۡمَ عَلَیۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّكُمۡ إِلَیۡهِ تُحۡشَرُونَ',
    'واذكروا الله في ايام معدودات فمن تعجل في يومين فلا اثم عليه ومن تاخر فلا اثم عليه لمن اتقى واتقوا الله واعلموا انكم اليه تحشرون',
    '۞وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَيَّا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡدُود<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعَجَّلَ فِى يَوۡمَيۡنِ فَل<rule class=madda_obligatory_monfasel>َآ</rule> إِثۡمَ عَلَيۡهِ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأَخَّرَ فَل<rule class=madda_obligatory_monfasel>َآ</rule> إِثۡمَ عَلَيۡهِ‌ۚ لِمَنِ <rule class=ham_wasl>ٱ</rule>تَّقَىٰ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َكُمۡ إِلَيۡهِ تُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٢٠٣',
    203, 2, 1, 32, 26, 13, 'false'
  );
  
  -- Ayah 204 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    211,
    'وَمِنَ ٱلنَّاسِ مَن یُعۡجِبُكَ قَوۡلُهُۥ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَیُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِی قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ',
    'ومن الناس من يعجبك قوله في الحياة الدنيا ويشهد الله على ما في قلبه وهو الد الخصام',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعۡجِبُكَ قَوۡلُهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَيُشۡهِدُ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ مَا فِى قَلۡبِه<rule class=madda_normal>ِۦ</rule> وَهُوَ أَلَدُّ <rule class=ham_wasl>ٱ</rule>لۡخِص<rule class=madda_permissible>َا</rule>مِ ٢٠٤',
    204, 2, 1, 32, 26, 13, 'false'
  );
  
  -- Ayah 205 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    212,
    'وَإِذَا تَوَلَّىٰ سَعَىٰ فِی ٱلۡأَرۡضِ لِیُفۡسِدَ فِیهَا وَیُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا یُحِبُّ ٱلۡفَسَادَ',
    'واذا تولى سعى في الارض ليفسد فيها ويهلك الحرث والنسل والله لا يحب الفساد',
    'وَإِذَا تَوَلَّىٰ سَعَىٰ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ <rule class=ham_wasl>ٱ</rule>لۡحَرۡثَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َسۡلَ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡفَس<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>َ ٢٠٥',
    205, 2, 1, 32, 26, 13, 'false'
  );
  
  -- Ayah 206 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    213,
    'وَإِذَا قِیلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ',
    'واذا قيل له اتق الله اخذته العزة بالاثم فحسبه جهنم ولبئس المهاد',
    'وَإِذَا قِيلَ لَهُ <rule class=ham_wasl>ٱ</rule>تَّقِ <rule class=ham_wasl>ٱ</rule>للَّهَ أَخَذَتۡهُ <rule class=ham_wasl>ٱ</rule>لۡعِزَّةُ بِ<rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ‌ۚ فَحَسۡبُهُ<rule class=madda_normal>ۥ</rule> جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۚ وَلَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمِه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ُ ٢٠٦',
    206, 2, 1, 32, 26, 13, 'false'
  );
  
  -- Ayah 207 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    214,
    'وَمِنَ ٱلنَّاسِ مَن یَشۡرِی نَفۡسَهُ ٱبۡتِغَاۤءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ',
    'ومن الناس من يشري نفسه ابتغاء مرضات الله والله رءوف بالعباد',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َشۡرِى نَفۡسَهُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَرۡضَاتِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ رَءُو<rule class=iqlab>فُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعِب<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٢٠٧',
    207, 2, 1, 32, 26, 13, 'false'
  );
  
  -- Ayah 208 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    215,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱدۡخُلُوا۟ فِی ٱلسِّلۡمِ كَاۤفَّةࣰ وَلَا تَتَّبِعُوا۟ خُطُوَ ٰ⁠تِ ٱلشَّیۡطَـٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینࣱ',
    'يا ايها الذين امنوا ادخلوا في السلم كافة ولا تتبعوا خطوات الشيطان انه لكم عدو مبين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّلۡمِ ك<rule class=madda_necessary>َا</rule>ٓفَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَتَّبِعُو<rule class=slnt>اۡ</rule> خُطُو<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَكُمۡ عَدُ<rule class=idgham_ghunnah>وٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٢٠٨',
    208, 2, 1, 32, 26, 13, 'false'
  );
  
  -- Ayah 209 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    216,
    'فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَاۤءَتۡكُمُ ٱلۡبَیِّنَـٰتُ فَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ عَزِیزٌ حَكِیمٌ',
    'فان زللتم من بعد ما جاءتكم البينات فاعلموا ان الله عزيز حكيم',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>َلَلۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تُ فَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٢٠٩',
    209, 2, 1, 32, 26, 13, 'false'
  );
  
  -- Ayah 210 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    217,
    'هَلۡ یَنظُرُونَ إِلَّاۤ أَن یَأۡتِیَهُمُ ٱللَّهُ فِی ظُلَلࣲ مِّنَ ٱلۡغَمَامِ وَٱلۡمَلَـٰۤىِٕكَةُ وَقُضِیَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ',
    'هل ينظرون الا ان ياتيهم الله في ظلل من الغمام والملائكة وقضي الامر والى الله ترجع الامور',
    'هَلۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى ظُلَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡغَمَامِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ وَقُضِىَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ‌ۚ وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تُرۡجَعُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رُ ٢١٠',
    210, 2, 1, 32, 26, 13, 'false'
  );
  
  -- Ayah 211 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    218,
    'سَلۡ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ كَمۡ ءَاتَیۡنَـٰهُم مِّنۡ ءَایَةِۭ بَیِّنَةࣲۗ وَمَن یُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَاۤءَتۡهُ فَإِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ',
    'سل بني اسرائيل كم اتيناهم من اية بينة ومن يبدل نعمة الله من بعد ما جاءته فان الله شديد العقاب',
    'سَلۡ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ كَمۡ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ ءَايَ<rule class=iqlab>ةِۭ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=idgham_ghunnah>ةٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُبَدِّلۡ نِعۡمَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢١١',
    211, 2, 1, 33, 27, 13, 'false'
  );
  
  -- Ayah 212 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    219,
    'زُیِّنَ لِلَّذِینَ كَفَرُوا۟ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَیَسۡخَرُونَ مِنَ ٱلَّذِینَ ءَامَنُوا۟ۘ وَٱلَّذِینَ ٱتَّقَوۡا۟ فَوۡقَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۗ وَٱللَّهُ یَرۡزُقُ مَن یَشَاۤءُ بِغَیۡرِ حِسَابࣲ',
    'زين للذين كفروا الحياة الدنيا ويسخرون من الذين امنوا والذين اتقوا فوقهم يوم القيامة والله يرزق من يشاء بغير حساب',
    'زُيِّنَ لِلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَيَسۡخَرُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ‌ۘ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> فَوۡقَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَرۡزُقُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بِغَيۡرِ حِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٢١٢',
    212, 2, 1, 33, 27, 13, 'false'
  );
  
  -- Ayah 213 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    220,
    'كَانَ ٱلنَّاسُ أُمَّةࣰ وَ ٰ⁠حِدَةࣰ فَبَعَثَ ٱللَّهُ ٱلنَّبِیِّـۧنَ مُبَشِّرِینَ وَمُنذِرِینَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ لِیَحۡكُمَ بَیۡنَ ٱلنَّاسِ فِیمَا ٱخۡتَلَفُوا۟ فِیهِۚ وَمَا ٱخۡتَلَفَ فِیهِ إِلَّا ٱلَّذِینَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَـٰتُ بَغۡیَۢا بَیۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ لِمَا ٱخۡتَلَفُوا۟ فِیهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ یَهۡدِی مَن یَشَاۤءُ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمٍ',
    'كان الناس امة واحدة فبعث الله النبيين مبشرين ومنذرين وانزل معهم الكتاب بالحق ليحكم بين الناس فيما اختلفوا فيه وما اختلف فيه الا الذين اوتوه من بعد ما جاءتهم البينات بغيا بينهم فهدى الله الذين امنوا لما اختلفوا فيه من الحق باذنه والله يهدي من يشاء الى صراط مستقيم',
    'كَانَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َبَعَثَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ مُبَشِّرِينَ وَمُ<rule class=ikhafa>نذ</rule>ِرِينَ وَأَ<rule class=ikhafa>نز</rule>َلَ مَعَهُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ لِيَحۡكُمَ بَيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ فِيمَا <rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> فِيهِ‌ۚ وَمَا <rule class=ham_wasl>ٱ</rule>خۡتَلَفَ فِيهِ إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُوهُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تُ بَغۡي<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَهُمۡ‌ۖ فَهَدَى <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لِمَا <rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> فِيهِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ بِإِذۡنِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٢١٣',
    213, 2, 1, 33, 27, 13, 'false'
  );
  
  -- Ayah 214 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    221,
    'أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُوا۟ ٱلۡجَنَّةَ وَلَمَّا یَأۡتِكُم مَّثَلُ ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَاۤءُ وَٱلضَّرَّاۤءُ وَزُلۡزِلُوا۟ حَتَّىٰ یَقُولَ ٱلرَّسُولُ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَاۤ إِنَّ نَصۡرَ ٱللَّهِ قَرِیبࣱ',
    'ام حسبتم ان تدخلوا الجنة ولما ياتكم مثل الذين خلوا من قبلكم مستهم الباساء والضراء وزلزلوا حتى يقول الرسول والذين امنوا معه متى نصر الله الا ان نصر الله قريب',
    'أَمۡ حَسِ<rule class=qalaqah>بۡ</rule>تُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ وَلَ<rule class=ghunnah>مّ</rule>َا يَأۡتِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّثَلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَلَوۡ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِك<rule class=idgham_shafawi>ُم‌ۖ</rule> <rule class=idgham_shafawi>م</rule>َّسَّتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَأۡس<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَزُلۡزِلُو<rule class=slnt>اۡ</rule> حَتَّىٰ يَقُولَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> مَتَىٰ نَصۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ نَصۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ قَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٢١٤',
    214, 2, 1, 33, 27, 13, 'false'
  );
  
  -- Ayah 215 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    222,
    'یَسۡـَٔلُونَكَ مَاذَا یُنفِقُونَۖ قُلۡ مَاۤ أَنفَقۡتُم مِّنۡ خَیۡرࣲ فَلِلۡوَ ٰ⁠لِدَیۡنِ وَٱلۡأَقۡرَبِینَ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱبۡنِ ٱلسَّبِیلِۗ وَمَا تَفۡعَلُوا۟ مِنۡ خَیۡرࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِیمࣱ',
    'يسالونك ماذا ينفقون قل ما انفقتم من خير فللوالدين والاقربين واليتامى والمساكين وابن السبيل وما تفعلوا من خير فان الله به عليم',
    'يَسۡــَٔلُونَكَ مَاذَا يُ<rule class=ikhafa>نف</rule>ِقُونَ‌ۖ قُلۡ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َ<rule class=qalaqah>قۡ</rule>ت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َلِلۡو<rule class=madda_normal>ٰ</rule>لِدَيۡنِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>رَبِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ‌ۗ وَمَا تَفۡعَلُو<rule class=slnt>اۡ</rule> مِنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِه<rule class=madda_normal>ِۦ</rule> عَل<rule class=madda_permissible>ِي</rule>مٌ ٢١٥',
    215, 2, 1, 33, 27, 13, 'false'
  );
  
  -- Ayah 216 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    223,
    'كُتِبَ عَلَیۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهࣱ لَّكُمۡۖ وَعَسَىٰۤ أَن تَكۡرَهُوا۟ شَیۡـࣰٔا وَهُوَ خَیۡرࣱ لَّكُمۡۖ وَعَسَىٰۤ أَن تُحِبُّوا۟ شَیۡـࣰٔا وَهُوَ شَرࣱّ لَّكُمۡۚ وَٱللَّهُ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ',
    'كتب عليكم القتال وهو كره لكم وعسى ان تكرهوا شيئا وهو خير لكم وعسى ان تحبوا شيئا وهو شر لكم والله يعلم وانتم لا تعلمون',
    'كُتِبَ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡقِتَالُ وَهُوَ كُرۡ<rule class=idgham_wo_ghunnah>هٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ وَعَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكۡرَهُو<rule class=slnt>اۡ</rule> شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ وَعَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُحِبُّو<rule class=slnt>اۡ</rule> شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ شَ<rule class=idgham_wo_ghunnah>رٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢١٦',
    216, 2, 1, 34, 27, 13, 'false'
  );
  
  -- Ayah 217 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    224,
    'یَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالࣲ فِیهِۖ قُلۡ قِتَالࣱ فِیهِ كَبِیرࣱۚ وَصَدٌّ عَن سَبِیلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا یَزَالُونَ یُقَـٰتِلُونَكُمۡ حَتَّىٰ یَرُدُّوكُمۡ عَن دِینِكُمۡ إِنِ ٱسۡتَطَـٰعُوا۟ۚ وَمَن یَرۡتَدِدۡ مِنكُمۡ عَن دِینِهِۦ فَیَمُتۡ وَهُوَ كَافِرࣱ فَأُو۟لَـٰۤىِٕكَ حَبِطَتۡ أَعۡمَـٰلُهُمۡ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۖ وَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'يسالونك عن الشهر الحرام قتال فيه قل قتال فيه كبير وصد عن سبيل الله وكفر به والمسجد الحرام واخراج اهله منه اكبر عند الله والفتنة اكبر من القتل ولا يزالون يقاتلونكم حتى يردوكم عن دينكم ان استطاعوا ومن يرتدد منكم عن دينه فيمت وهو كافر فاولئك حبطت اعمالهم في الدنيا والاخرة واولئك اصحاب النار هم فيها خالدون',
    'يَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ قِتَا<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>ِيهِ‌ۖ قُلۡ قِتَا<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ف</rule>ِيهِ كَبِي<rule class=idgham_ghunnah>رٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َصَدٌّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَكُفۡ<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ وَإِخۡرَاجُ أَهۡلِه<rule class=madda_normal>ِۦ</rule> مِنۡهُ أَكۡبَرُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡفِتۡنَةُ أَكۡبَرُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَتۡلِ‌ۗ وَلَا يَزَالُونَ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِينِكُمۡ إِنِ <rule class=ham_wasl>ٱ</rule>سۡتَطَ<rule class=madda_normal>ـٰ</rule>عُو<rule class=slnt>اۡ‌ۚ</rule> وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َرۡتَدِ<rule class=qalaqah>دۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِينِه<rule class=madda_normal>ِۦ</rule> فَيَمُتۡ وَهُوَ كَافِ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ حَبِطَتۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٢١٧',
    217, 2, 1, 34, 28, 13, 'false'
  );
  
  -- Ayah 218 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    225,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَاجَرُوا۟ وَجَـٰهَدُوا۟ فِی سَبِیلِ ٱللَّهِ أُو۟لَـٰۤىِٕكَ یَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'ان الذين امنوا والذين هاجروا وجاهدوا في سبيل الله اولئك يرجون رحمت الله والله غفور رحيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هَاجَرُو<rule class=slnt>اۡ</rule> وَجَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَرۡجُونَ رَحۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٢١٨',
    218, 2, 1, 34, 28, 13, 'false'
  );
  
  -- Ayah 219 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    226,
    '۞ یَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَیۡسِرِۖ قُلۡ فِیهِمَاۤ إِثۡمࣱ كَبِیرࣱ وَمَنَـٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَاۤ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَیَسۡـَٔلُونَكَ مَاذَا یُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ',
    'يسالونك عن الخمر والميسر قل فيهما اثم كبير ومنافع للناس واثمهما اكبر من نفعهما ويسالونك ماذا ينفقون قل العفو كذلك يبين الله لكم الايات لعلكم تتفكرون',
    '۞يَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡخَمۡرِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَيۡسِرِ‌ۖ قُلۡ فِيهِم<rule class=madda_obligatory_monfasel>َآ</rule> إِثۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ك</rule>َبِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَنَ<rule class=madda_normal>ـٰ</rule>فِعُ لِل<rule class=ghunnah>نّ</rule>َاسِ وَإِثۡمُهُم<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡبَرُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡعِهِمَا‌ۗ وَيَسۡــَٔلُونَكَ مَاذَا يُ<rule class=ikhafa>نف</rule>ِقُونَ قُلِ <rule class=ham_wasl>ٱ</rule>لۡعَفۡوَ‌ۗ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لَعَلَّكُمۡ تَتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢١٩',
    219, 2, 1, 34, 28, 14, 'false'
  );
  
  -- Ayah 220 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    227,
    'فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۗ وَیَسۡـَٔلُونَكَ عَنِ ٱلۡیَتَـٰمَىٰۖ قُلۡ إِصۡلَاحࣱ لَّهُمۡ خَیۡرࣱۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَ ٰ⁠نُكُمۡۚ وَٱللَّهُ یَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ',
    'في الدنيا والاخرة ويسالونك عن اليتامى قل اصلاح لهم خير وان تخالطوهم فاخوانكم والله يعلم المفسد من المصلح ولو شاء الله لاعنتكم ان الله عزيز حكيم',
    'فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۗ وَيَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ‌ۖ قُلۡ إِصۡلَا<rule class=idgham_wo_ghunnah>حٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ خَيۡ<rule class=idgham_ghunnah>رٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُخَالِطُوهُمۡ فَإِخۡو<rule class=madda_normal>ٰ</rule>نُكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِدَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُصۡلِحِ‌ۚ وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَأَعۡنَتَكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٢٢٠',
    220, 2, 1, 35, 28, 14, 'false'
  );
  
  -- Ayah 221 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    228,
    'وَلَا تَنكِحُوا۟ ٱلۡمُشۡرِكَـٰتِ حَتَّىٰ یُؤۡمِنَّۚ وَلَأَمَةࣱ مُّؤۡمِنَةٌ خَیۡرࣱ مِّن مُّشۡرِكَةࣲ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُوا۟ ٱلۡمُشۡرِكِینَ حَتَّىٰ یُؤۡمِنُوا۟ۚ وَلَعَبۡدࣱ مُّؤۡمِنٌ خَیۡرࣱ مِّن مُّشۡرِكࣲ وَلَوۡ أَعۡجَبَكُمۡۗ أُو۟لَـٰۤىِٕكَ یَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ یَدۡعُوۤا۟ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَیُبَیِّنُ ءَایَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ یَتَذَكَّرُونَ',
    'ولا تنكحوا المشركات حتى يؤمن ولامة مؤمنة خير من مشركة ولو اعجبتكم ولا تنكحوا المشركين حتى يؤمنوا ولعبد مؤمن خير من مشرك ولو اعجبكم اولئك يدعون الى النار والله يدعو الى الجنة والمغفرة باذنه ويبين اياته للناس لعلهم يتذكرون',
    'وَلَا تَ<rule class=ikhafa>نك</rule>ِحُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكَ<rule class=madda_normal>ـٰ</rule>تِ حَتَّىٰ يُؤۡمِ<rule class=ghunnah>نّ</rule>َ‌ۚ وَلَأَمَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنَةٌ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّشۡرِكَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ أَعۡجَبَتۡكُمۡ‌ۗ وَلَا تُ<rule class=ikhafa>نك</rule>ِحُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُو<rule class=slnt>اۡ‌ۚ</rule> وَلَعَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنٌ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّشۡرِ<rule class=idgham_ghunnah>كٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ أَعۡجَبَكُمۡ‌ۗ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَ<rule class=qalaqah>دۡ</rule>عُونَ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=qalaqah>دۡ</rule>ع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَغۡفِرَةِ بِإِذۡنِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَيُبَيِّنُ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> لِل<rule class=ghunnah>نّ</rule>َاسِ لَعَلَّهُمۡ يَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٢١',
    221, 2, 1, 35, 28, 14, 'false'
  );
  
  -- Ayah 222 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    229,
    'وَیَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِیضِۖ قُلۡ هُوَ أَذࣰى فَٱعۡتَزِلُوا۟ ٱلنِّسَاۤءَ فِی ٱلۡمَحِیضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ یَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَیۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلتَّوَّ ٰ⁠بِینَ وَیُحِبُّ ٱلۡمُتَطَهِّرِینَ',
    'ويسالونك عن المحيض قل هو اذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فاذا تطهرن فاتوهن من حيث امركم الله ان الله يحب التوابين ويحب المتطهرين',
    'وَيَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمَحِيضِ‌ۖ قُلۡ هُوَ أَ<rule class=ikhafa>ذًى</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>عۡتَزِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فِى <rule class=ham_wasl>ٱ</rule>لۡمَحِيضِ‌ۖ وَلَا تَ<rule class=qalaqah>قۡ</rule>رَبُوهُ<rule class=ghunnah>نّ</rule>َ حَتَّىٰ يَ<rule class=qalaqah>طۡ</rule>هُرۡنَ‌ۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُ<rule class=ghunnah>نّ</rule>َ مِنۡ حَيۡثُ أَمَرَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوّ<rule class=madda_normal>ٰ</rule>بِينَ وَيُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُتَطَهِّر<rule class=madda_permissible>ِي</rule>نَ ٢٢٢',
    222, 2, 1, 35, 29, 14, 'false'
  );
  
  -- Ayah 223 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    230,
    'نِسَاۤؤُكُمۡ حَرۡثࣱ لَّكُمۡ فَأۡتُوا۟ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُوا۟ لِأَنفُسِكُمۡۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّكُم مُّلَـٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ',
    'نساؤكم حرث لكم فاتوا حرثكم انى شئتم وقدموا لانفسكم واتقوا الله واعلموا انكم ملاقوه وبشر المؤمنين',
    'نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ حَرۡ<rule class=idgham_wo_ghunnah>ثٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ فَأۡتُو<rule class=slnt>اۡ</rule> حَرۡثَكُمۡ أَ<rule class=ghunnah>نّ</rule>َىٰ شِئۡتُمۡ‌ۖ وَقَدِّمُو<rule class=slnt>اۡ</rule> لِأَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلَ<rule class=madda_normal>ـٰ</rule>قُوهُ‌ۗ وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢٢٣',
    223, 2, 1, 35, 29, 14, 'false'
  );
  
  -- Ayah 224 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    231,
    'وَلَا تَجۡعَلُوا۟ ٱللَّهَ عُرۡضَةࣰ لِّأَیۡمَـٰنِكُمۡ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصۡلِحُوا۟ بَیۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِیعٌ عَلِیمࣱ',
    'ولا تجعلوا الله عرضة لايمانكم ان تبروا وتتقوا وتصلحوا بين الناس والله سميع عليم',
    'وَلَا تَ<rule class=qalaqah>جۡ</rule>عَلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ عُرۡضَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأَيۡمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبَرُّو<rule class=slnt>اۡ</rule> وَتَتَّقُو<rule class=slnt>اۡ</rule> وَتُصۡلِحُو<rule class=slnt>اۡ</rule> بَيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٢٤',
    224, 2, 1, 35, 29, 14, 'false'
  );
  
  -- Ayah 225 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    232,
    'لَّا یُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِیۤ أَیۡمَـٰنِكُمۡ وَلَـٰكِن یُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِیمࣱ',
    'لا يؤاخذكم الله باللغو في ايمانكم ولكن يؤاخذكم بما كسبت قلوبكم والله غفور حليم',
    'لَّا يُؤَاخِذُكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّغۡوِ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤَاخِذُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَسَبَتۡ قُلُوبُكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُورٌ حَل<rule class=madda_permissible>ِي</rule>مٌ ٢٢٥',
    225, 2, 1, 36, 29, 14, 'false'
  );
  
  -- Ayah 226 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    233,
    'لِّلَّذِینَ یُؤۡلُونَ مِن نِّسَاۤىِٕهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرࣲۖ فَإِن فَاۤءُو فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'للذين يؤلون من نسائهم تربص اربعة اشهر فان فاءوا فان الله غفور رحيم',
    'لِّلَّذِينَ يُؤۡلُونَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ِّس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُ<rule class=ikhafa>رٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءُو فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٢٢٦',
    226, 2, 1, 36, 29, 14, 'false'
  );
  
  -- Ayah 227 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    234,
    'وَإِنۡ عَزَمُوا۟ ٱلطَّلَـٰقَ فَإِنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ',
    'وان عزموا الطلاق فان الله سميع عليم',
    'وَإِنۡ عَزَمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّلَ<rule class=madda_normal>ـٰ</rule>قَ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٢٧',
    227, 2, 1, 36, 29, 14, 'false'
  );
  
  -- Ayah 228 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    235,
    'وَٱلۡمُطَلَّقَـٰتُ یَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَـٰثَةَ قُرُوۤءࣲۚ وَلَا یَحِلُّ لَهُنَّ أَن یَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِیۤ أَرۡحَامِهِنَّ إِن كُنَّ یُؤۡمِنَّ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِی ذَ ٰ⁠لِكَ إِنۡ أَرَادُوۤا۟ إِصۡلَـٰحࣰاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِی عَلَیۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَیۡهِنَّ دَرَجَةࣱۗ وَٱللَّهُ عَزِیزٌ حَكِیمٌ',
    'والمطلقات يتربصن بانفسهن ثلاثة قروء ولا يحل لهن ان يكتمن ما خلق الله في ارحامهن ان كن يؤمن بالله واليوم الاخر وبعولتهن احق بردهن في ذلك ان ارادوا اصلاحا ولهن مثل الذي عليهن بالمعروف وللرجال عليهن درجة والله عزيز حكيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡمُطَلَّقَ<rule class=madda_normal>ـٰ</rule>تُ يَتَرَبَّصۡنَ بِأَ<rule class=ikhafa>نف</rule>ُسِهِ<rule class=ghunnah>نّ</rule>َ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَةَ قُر<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=idgham_ghunnah>ءٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَحِلُّ لَهُ<rule class=ghunnah>نّ</rule>َ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡتُمۡنَ مَا خَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡحَامِهِ<rule class=ghunnah>نّ</rule>َ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َ يُؤۡمِ<rule class=ghunnah>نّ</rule>َ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ‌ۚ وَبُعُولَتُهُ<rule class=ghunnah>نّ</rule>َ أَحَقُّ بِرَدِّهِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ إِنۡ أَرَاد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِصۡلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>حًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُ<rule class=ghunnah>نّ</rule>َ مِثۡلُ <rule class=ham_wasl>ٱ</rule>لَّذِى عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۚ وَلِلرِّجَالِ عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ دَرَجَ<rule class=idgham_ghunnah>ةٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٢٢٨',
    228, 2, 1, 36, 29, 14, 'false'
  );
  
  -- Ayah 229 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    236,
    'ٱلطَّلَـٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِیحُۢ بِإِحۡسَـٰنࣲۗ وَلَا یَحِلُّ لَكُمۡ أَن تَأۡخُذُوا۟ مِمَّاۤ ءَاتَیۡتُمُوهُنَّ شَیۡـًٔا إِلَّاۤ أَن یَخَافَاۤ أَلَّا یُقِیمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا یُقِیمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَیۡهِمَا فِیمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن یَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ',
    'الطلاق مرتان فامساك بمعروف او تسريح باحسان ولا يحل لكم ان تاخذوا مما اتيتموهن شيئا الا ان يخافا الا يقيما حدود الله فان خفتم الا يقيما حدود الله فلا جناح عليهما فيما افتدت به تلك حدود الله فلا تعتدوها ومن يتعد حدود الله فاولئك هم الظالمون',
    'ٱ<rule class=laam_shamsiyah>ل</rule>طَّلَ<rule class=madda_normal>ـٰ</rule>قُ مَرَّتَانِ‌ۖ فَإِمۡسَا<rule class=iqlab>كُۢ</rule> <rule class=iqlab>ب</rule>ِمَعۡرُوفٍ أَوۡ تَسۡرِي<rule class=iqlab>حُۢ</rule> <rule class=iqlab>ب</rule>ِإِحۡسَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَحِلُّ لَكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡخُذُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡتُمُوهُ<rule class=ghunnah>نّ</rule>َ شَيۡــًٔا إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخَاف<rule class=madda_obligatory_monfasel>َآ</rule> أَلَّا يُقِيمَا حُدُودَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ فَإِنۡ خِفۡتُمۡ أَلَّا يُقِيمَا حُدُودَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَلَا جُنَاحَ عَلَيۡهِمَا فِيمَا <rule class=ham_wasl>ٱ</rule>فۡتَدَتۡ بِه<rule class=madda_normal>ِۦ</rule>‌ۗ تِلۡكَ حُدُودُ <rule class=ham_wasl>ٱ</rule>للَّهِ فَلَا تَعۡتَدُوهَا‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَعَدَّ حُدُودَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٢٢٩',
    229, 2, 1, 36, 30, 14, 'false'
  );
  
  -- Ayah 230 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    237,
    'فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَیۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَیۡهِمَاۤ أَن یَتَرَاجَعَاۤ إِن ظَنَّاۤ أَن یُقِیمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ یُبَیِّنُهَا لِقَوۡمࣲ یَعۡلَمُونَ',
    'فان طلقها فلا تحل له من بعد حتى تنكح زوجا غيره فان طلقها فلا جناح عليهما ان يتراجعا ان ظنا ان يقيما حدود الله وتلك حدود الله يبينها لقوم يعلمون',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َلَّقَهَا فَلَا تَحِلُّ لَهُ<rule class=madda_normal>ۥ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدُ حَتَّىٰ تَ<rule class=ikhafa>نك</rule>ِحَ زَوۡجًا غَيۡرَهُ<rule class=madda_normal>ۥ</rule>‌ۗ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َلَّقَهَا فَلَا جُنَاحَ عَلَيۡهِم<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَرَاجَع<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>َ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُقِيمَا حُدُودَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَتِلۡكَ حُدُودُ <rule class=ham_wasl>ٱ</rule>للَّهِ يُبَيِّنُهَا لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٣٠',
    230, 2, 1, 36, 30, 14, 'false'
  );
  
  -- Ayah 231 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    238,
    'وَإِذَا طَلَّقۡتُمُ ٱلنِّسَاۤءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفࣲۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارࣰا لِّتَعۡتَدُوا۟ۚ وَمَن یَفۡعَلۡ ذَ ٰ⁠لِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوۤا۟ ءَایَـٰتِ ٱللَّهِ هُزُوࣰاۚ وَٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡ وَمَاۤ أَنزَلَ عَلَیۡكُم مِّنَ ٱلۡكِتَـٰبِ وَٱلۡحِكۡمَةِ یَعِظُكُم بِهِۦۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'واذا طلقتم النساء فبلغن اجلهن فامسكوهن بمعروف او سرحوهن بمعروف ولا تمسكوهن ضرارا لتعتدوا ومن يفعل ذلك فقد ظلم نفسه ولا تتخذوا ايات الله هزوا واذكروا نعمت الله عليكم وما انزل عليكم من الكتاب والحكمة يعظكم به واتقوا الله واعلموا ان الله بكل شيء عليم',
    'وَإِذَا طَلَّ<rule class=qalaqah>قۡ</rule>تُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَبَلَغۡنَ أَجَلَهُ<rule class=ghunnah>نّ</rule>َ فَأَمۡسِكُوهُ<rule class=ghunnah>نّ</rule>َ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُ<rule class=ghunnah>نّ</rule>َ بِمَعۡرُو<rule class=idgham_ghunnah>فٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تُمۡسِكُوهُ<rule class=ghunnah>نّ</rule>َ ضِرَا<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتَعۡتَدُو<rule class=slnt>اۡ‌ۚ</rule> وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلۡ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَقَ<rule class=qalaqah>دۡ</rule> ظَلَمَ نَفۡسَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَلَا تَتَّخِذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ هُزُ<rule class=idgham_ghunnah>وًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةِ يَعِظُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٣١',
    231, 2, 1, 37, 30, 14, 'false'
  );
  
  -- Ayah 232 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    239,
    'وَإِذَا طَلَّقۡتُمُ ٱلنِّسَاۤءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن یَنكِحۡنَ أَزۡوَ ٰ⁠جَهُنَّ إِذَا تَرَ ٰ⁠ضَوۡا۟ بَیۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَ ٰ⁠لِكَ یُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۗ ذَ ٰ⁠لِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ',
    'واذا طلقتم النساء فبلغن اجلهن فلا تعضلوهن ان ينكحن ازواجهن اذا تراضوا بينهم بالمعروف ذلك يوعظ به من كان منكم يؤمن بالله واليوم الاخر ذلكم ازكى لكم واطهر والله يعلم وانتم لا تعلمون',
    'وَإِذَا طَلَّ<rule class=qalaqah>قۡ</rule>تُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَبَلَغۡنَ أَجَلَهُ<rule class=ghunnah>نّ</rule>َ فَلَا تَعۡضُلُوهُ<rule class=ghunnah>نّ</rule>َ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نك</rule>ِحۡنَ أَزۡو<rule class=madda_normal>ٰ</rule>جَهُ<rule class=ghunnah>نّ</rule>َ إِذَا تَر<rule class=madda_normal>ٰ</rule>ضَوۡ<rule class=slnt>اۡ</rule> بَيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۗ ذ<rule class=madda_normal>ٰ</rule>لِكَ يُوعَظُ بِه<rule class=madda_normal>ِۦ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِ<rule class=ikhafa>نك</rule>ُمۡ يُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ‌ۗ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَ<rule class=qalaqah>طۡ</rule>هَرُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٣٢',
    232, 2, 1, 37, 31, 14, 'false'
  );
  
  -- Ayah 233 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    240,
    '۞ وَٱلۡوَ ٰ⁠لِدَ ٰ⁠تُ یُرۡضِعۡنَ أَوۡلَـٰدَهُنَّ حَوۡلَیۡنِ كَامِلَیۡنِۖ لِمَنۡ أَرَادَ أَن یُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَاۤرَّ وَ ٰ⁠لِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودࣱ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَ ٰ⁠لِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضࣲ مِّنۡهُمَا وَتَشَاوُرࣲ فَلَا جُنَاحَ عَلَیۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوۤا۟ أَوۡلَـٰدَكُمۡ فَلَا جُنَاحَ عَلَیۡكُمۡ إِذَا سَلَّمۡتُم مَّاۤ ءَاتَیۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِیرࣱ',
    'والوالدات يرضعن اولادهن حولين كاملين لمن اراد ان يتم الرضاعة وعلى المولود له رزقهن وكسوتهن بالمعروف لا تكلف نفس الا وسعها لا تضار والدة بولدها ولا مولود له بولده وعلى الوارث مثل ذلك فان ارادا فصالا عن تراض منهما وتشاور فلا جناح عليهما وان اردتم ان تسترضعوا اولادكم فلا جناح عليكم اذا سلمتم ما اتيتم بالمعروف واتقوا الله واعلموا ان الله بما تعملون بصير',
    '۞وَ<rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِد<rule class=madda_normal>ٰ</rule>تُ يُرۡضِعۡنَ أَوۡلَ<rule class=madda_normal>ـٰ</rule>دَهُ<rule class=ghunnah>نّ</rule>َ حَوۡلَيۡنِ كَامِلَيۡنِ‌ۖ لِمَنۡ أَرَادَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُتِ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّضَاعَةَ‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>لۡمَوۡلُودِ لَهُ<rule class=madda_normal>ۥ</rule> رِزۡقُهُ<rule class=ghunnah>نّ</rule>َ وَكِسۡوَتُهُ<rule class=ghunnah>نّ</rule>َ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَا‌ۚ لَا تُض<rule class=madda_necessary>َا</rule>ٓرَّ و<rule class=madda_normal>ٰ</rule>لِدَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِوَلَدِهَا وَلَا مَوۡلُو<rule class=idgham_wo_ghunnah>دٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> بِوَلَدِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>لۡوَارِثِ مِثۡلُ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۗ فَإِنۡ أَرَادَا فِصَالاً عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرَا<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمَا وَتَشَاوُ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َلَا جُنَاحَ عَلَيۡهِمَا‌ۗ وَإِنۡ أَرَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَرۡضِع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دَكُمۡ فَلَا جُنَاحَ عَلَيۡكُمۡ إِذَا سَلَّمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٢٣٣',
    233, 2, 1, 37, 31, 15, 'false'
  );
  
  -- Ayah 234 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    241,
    'وَٱلَّذِینَ یُتَوَفَّوۡنَ مِنكُمۡ وَیَذَرُونَ أَزۡوَ ٰ⁠جࣰا یَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرࣲ وَعَشۡرࣰاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَیۡكُمۡ فِیمَا فَعَلۡنَ فِیۤ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ',
    'والذين يتوفون منكم ويذرون ازواجا يتربصن بانفسهن اربعة اشهر وعشرا فاذا بلغن اجلهن فلا جناح عليكم فيما فعلن في انفسهن بالمعروف والله بما تعملون خبير',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُتَوَفَّوۡنَ مِ<rule class=ikhafa>نك</rule>ُمۡ وَيَذَرُونَ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>ي</rule>َتَرَبَّصۡنَ بِأَ<rule class=ikhafa>نف</rule>ُسِهِ<rule class=ghunnah>نّ</rule>َ أَرۡبَعَةَ أَشۡهُ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَشۡ<rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِذَا بَلَغۡنَ أَجَلَهُ<rule class=ghunnah>نّ</rule>َ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِ<rule class=ghunnah>نّ</rule>َ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ٢٣٤',
    234, 2, 1, 38, 31, 15, 'false'
  );
  
  -- Ayah 235 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    242,
    'وَلَا جُنَاحَ عَلَیۡكُمۡ فِیمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَاۤءِ أَوۡ أَكۡنَنتُمۡ فِیۤ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَـٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّاۤ أَن تَقُولُوا۟ قَوۡلࣰا مَّعۡرُوفࣰاۚ وَلَا تَعۡزِمُوا۟ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ یَبۡلُغَ ٱلۡكِتَـٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِیۤ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِیمࣱ',
    'ولا جناح عليكم فيما عرضتم به من خطبة النساء او اكننتم في انفسكم علم الله انكم ستذكرونهن ولكن لا تواعدوهن سرا الا ان تقولوا قولا معروفا ولا تعزموا عقدة النكاح حتى يبلغ الكتاب اجله واعلموا ان الله يعلم ما في انفسكم فاحذروه واعلموا ان الله غفور حليم',
    'وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مِنۡ خِ<rule class=qalaqah>طۡ</rule>بَةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَوۡ أَكۡنَ<rule class=ikhafa>نت</rule>ُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۚ عَلِمَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=ghunnah>نّ</rule>َكُمۡ سَتَذۡكُرُونَهُ<rule class=ghunnah>نّ</rule>َ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تُوَاعِدُوهُ<rule class=ghunnah>نّ</rule>َ سِرًّا إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولُو<rule class=slnt>اۡ</rule> قَوۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُو<rule class=idgham_ghunnah>فًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَعۡزِمُو<rule class=slnt>اۡ</rule> عُ<rule class=qalaqah>قۡ</rule>دَةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِكَاحِ حَتَّىٰ يَ<rule class=qalaqah>بۡ</rule>لُغَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بُ أَجَلَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ مَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ فَ<rule class=ham_wasl>ٱ</rule>حۡذَرُوهُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُورٌ حَل<rule class=madda_permissible>ِي</rule>مٌ ٢٣٥',
    235, 2, 1, 38, 31, 15, 'false'
  );
  
  -- Ayah 236 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    243,
    'لَّا جُنَاحَ عَلَیۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَاۤءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُوا۟ لَهُنَّ فَرِیضَةࣰۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَـٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِینَ',
    'لا جناح عليكم ان طلقتم النساء ما لم تمسوهن او تفرضوا لهن فريضة ومتعوهن على الموسع قدره وعلى المقتر قدره متاعا بالمعروف حقا على المحسنين',
    'لَّا جُنَاحَ عَلَيۡكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َلَّ<rule class=qalaqah>قۡ</rule>تُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا لَمۡ تَمَسُّوهُ<rule class=ghunnah>نّ</rule>َ أَوۡ تَفۡرِضُو<rule class=slnt>اۡ</rule> لَهُ<rule class=ghunnah>نّ</rule>َ فَرِيضَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَتِّعُوهُ<rule class=ghunnah>نّ</rule>َ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُوسِعِ قَدَرُهُ<rule class=madda_normal>ۥ</rule> وَعَلَى <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>قۡ</rule>تِرِ قَدَرُهُ<rule class=madda_normal>ۥ</rule> مَتَ<rule class=madda_normal>ـٰ</rule>ع<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۖ حَقًّا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٢٣٦',
    236, 2, 1, 38, 32, 15, 'false'
  );
  
  -- Ayah 237 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    244,
    'وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِیضَةࣰ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّاۤ أَن یَعۡفُونَ أَوۡ یَعۡفُوَا۟ ٱلَّذِی بِیَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوۤا۟ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُا۟ ٱلۡفَضۡلَ بَیۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِیرٌ',
    'وان طلقتموهن من قبل ان تمسوهن وقد فرضتم لهن فريضة فنصف ما فرضتم الا ان يعفون او يعفو الذي بيده عقدة النكاح وان تعفوا اقرب للتقوى ولا تنسوا الفضل بينكم ان الله بما تعملون بصير',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َلَّ<rule class=qalaqah>قۡ</rule>تُمُوهُ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمَسُّوهُ<rule class=ghunnah>نّ</rule>َ وَقَ<rule class=qalaqah>دۡ</rule> فَرَضۡتُمۡ لَهُ<rule class=ghunnah>نّ</rule>َ فَرِيضَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َنِصۡفُ مَا فَرَضۡتُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡفُونَ أَوۡ يَعۡفُوَ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِى بِيَدِه<rule class=madda_normal>ِۦ</rule> عُ<rule class=qalaqah>قۡ</rule>دَةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِكَاحِ‌ۚ وَأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡف<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>قۡ</rule>رَبُ لِلتَّ<rule class=qalaqah>قۡ</rule>وَىٰ‌ۚ وَلَا تَ<rule class=ikhafa>نس</rule>َوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡفَضۡلَ بَيۡنَكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٢٣٧',
    237, 2, 1, 38, 32, 15, 'false'
  );
  
  -- Ayah 238 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    245,
    'حَـٰفِظُوا۟ عَلَى ٱلصَّلَوَ ٰ⁠تِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُوا۟ لِلَّهِ قَـٰنِتِینَ',
    'حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين',
    'حَ<rule class=madda_normal>ـٰ</rule>فِظُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَو<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule>لۡوُسۡطَىٰ وَقُومُو<rule class=slnt>اۡ</rule> لِلَّهِ قَ<rule class=madda_normal>ـٰ</rule>نِت<rule class=madda_permissible>ِي</rule>نَ ٢٣٨',
    238, 2, 1, 39, 32, 15, 'false'
  );
  
  -- Ayah 239 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    246,
    'فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانࣰاۖ فَإِذَاۤ أَمِنتُمۡ فَٱذۡكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُوا۟ تَعۡلَمُونَ',
    'فان خفتم فرجالا او ركبانا فاذا امنتم فاذكروا الله كما علمكم ما لم تكونوا تعلمون',
    'فَإِنۡ خِفۡتُمۡ فَرِجَالاً أَوۡ رُكۡبَا<rule class=ikhafa>نًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَمِ<rule class=ikhafa>نت</rule>ُمۡ فَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ كَمَا عَلَّمَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا لَمۡ تَكُونُو<rule class=slnt>اۡ</rule> تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٣٩',
    239, 2, 1, 39, 32, 15, 'false'
  );
  
  -- Ayah 240 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    247,
    'وَٱلَّذِینَ یُتَوَفَّوۡنَ مِنكُمۡ وَیَذَرُونَ أَزۡوَ ٰ⁠جࣰا وَصِیَّةࣰ لِّأَزۡوَ ٰ⁠جِهِم مَّتَـٰعًا إِلَى ٱلۡحَوۡلِ غَیۡرَ إِخۡرَاجࣲۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَیۡكُمۡ فِی مَا فَعَلۡنَ فِیۤ أَنفُسِهِنَّ مِن مَّعۡرُوفࣲۗ وَٱللَّهُ عَزِیزٌ حَكِیمࣱ',
    'والذين يتوفون منكم ويذرون ازواجا وصية لازواجهم متاعا الى الحول غير اخراج فان خرجن فلا جناح عليكم في ما فعلن في انفسهن من معروف والله عزيز حكيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُتَوَفَّوۡنَ مِ<rule class=ikhafa>نك</rule>ُمۡ وَيَذَرُونَ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َصِيَّ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأَزۡو<rule class=madda_normal>ٰ</rule>جِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّتَ<rule class=madda_normal>ـٰ</rule>عًا إِلَى <rule class=ham_wasl>ٱ</rule>لۡحَوۡلِ غَيۡرَ إِخۡرَا<rule class=ikhafa>جٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِنۡ خَرَ<rule class=qalaqah>جۡ</rule>نَ فَلَا جُنَاحَ عَلَيۡكُمۡ فِى مَا فَعَلۡنَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِ<rule class=ghunnah>نّ</rule>َ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُو<rule class=idgham_ghunnah>فٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٢٤٠',
    240, 2, 1, 39, 32, 15, 'false'
  );
  
  -- Ayah 241 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    248,
    'وَلِلۡمُطَلَّقَـٰتِ مَتَـٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِینَ',
    'وللمطلقات متاع بالمعروف حقا على المتقين',
    'وَلِلۡمُطَلَّقَ<rule class=madda_normal>ـٰ</rule>تِ مَتَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۖ حَقًّا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٢٤١',
    241, 2, 1, 39, 32, 15, 'false'
  );
  
  -- Ayah 242 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    249,
    'كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ لَكُمۡ ءَایَـٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ',
    'كذلك يبين الله لكم اياته لعلكم تعقلون',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> لَعَلَّكُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٢٤٢',
    242, 2, 1, 39, 32, 15, 'false'
  );
  
  -- Ayah 243 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    250,
    '۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ خَرَجُوا۟ مِن دِیَـٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحۡیَـٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَشۡكُرُونَ',
    'الم تر الى الذين خرجوا من ديارهم وهم الوف حذر الموت فقال لهم الله موتوا ثم احياهم ان الله لذو فضل على الناس ولكن اكثر الناس لا يشكرون',
    '۞أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَرَجُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ فَقَالَ لَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مُوتُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ أَحۡيَ<rule class=madda_normal>ـٰ</rule>هُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَذُو فَضۡلٍ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٢٤٣',
    243, 2, 1, 39, 33, 16, 'false'
  );
  
  -- Ayah 244 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    251,
    'وَقَـٰتِلُوا۟ فِی سَبِیلِ ٱللَّهِ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ',
    'وقاتلوا في سبيل الله واعلموا ان الله سميع عليم',
    'وَقَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٤٤',
    244, 2, 1, 39, 33, 16, 'false'
  );
  
  -- Ayah 245 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    252,
    'مَّن ذَا ٱلَّذِی یُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنࣰا فَیُضَـٰعِفَهُۥ لَهُۥۤ أَضۡعَافࣰا كَثِیرَةࣰۚ وَٱللَّهُ یَقۡبِضُ وَیَبۡصُۜطُ وَإِلَیۡهِ تُرۡجَعُونَ',
    'من ذا الذي يقرض الله قرضا حسنا فيضاعفه له اضعافا كثيرة والله يقبض ويبسط واليه ترجعون',
    'مَّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِى يُ<rule class=qalaqah>قۡ</rule>رِضُ <rule class=ham_wasl>ٱ</rule>للَّهَ قَرۡضًا حَسَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َيُضَ<rule class=madda_normal>ـٰ</rule>عِفَهُ<rule class=madda_normal>ۥ</rule> لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَضۡعَا<rule class=ikhafa>فًا</rule> <rule class=ikhafa>ك</rule>َثِيرَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=qalaqah>قۡ</rule>بِضُ وَيَ<rule class=qalaqah>بۡ</rule>صُۜطُ وَإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٢٤٥',
    245, 2, 1, 39, 33, 16, 'false'
  );
  
  -- Ayah 246 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    253,
    'أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ مِنۢ بَعۡدِ مُوسَىٰۤ إِذۡ قَالُوا۟ لِنَبِیࣲّ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكࣰا نُّقَـٰتِلۡ فِی سَبِیلِ ٱللَّهِۖ قَالَ هَلۡ عَسَیۡتُمۡ إِن كُتِبَ عَلَیۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَـٰتِلُوا۟ۖ قَالُوا۟ وَمَا لَنَاۤ أَلَّا نُقَـٰتِلَ فِی سَبِیلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِیَـٰرِنَا وَأَبۡنَاۤىِٕنَاۖ فَلَمَّا كُتِبَ عَلَیۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡا۟ إِلَّا قَلِیلࣰا مِّنۡهُمۡۚ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ',
    'الم تر الى الملا من بني اسرائيل من بعد موسى اذ قالوا لنبي لهم ابعث لنا ملكا نقاتل في سبيل الله قال هل عسيتم ان كتب عليكم القتال الا تقاتلوا قالوا وما لنا الا نقاتل في سبيل الله وقد اخرجنا من ديارنا وابنائنا فلما كتب عليهم القتال تولوا الا قليلا منهم والله عليم بالظالمين',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡمَلَإِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذۡ قَالُو<rule class=slnt>اۡ</rule> لِنَبِ<rule class=idgham_wo_ghunnah>ىٍّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>عَثۡ لَنَا مَلِ<rule class=idgham_ghunnah>كًا</rule> <rule class=idgham_ghunnah>ن</rule>ُّقَ<rule class=madda_normal>ـٰ</rule>تِلۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ قَالَ هَلۡ عَسَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُتِبَ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡقِتَالُ أَلَّا تُقَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ‌ۖ</rule> قَالُو<rule class=slnt>اۡ</rule> وَمَا لَن<rule class=madda_obligatory_monfasel>َآ</rule> أَلَّا نُقَ<rule class=madda_normal>ـٰ</rule>تِلَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَقَ<rule class=qalaqah>دۡ</rule> أُخۡرِ<rule class=qalaqah>جۡ</rule>نَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِنَا وَأَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنَا‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا كُتِبَ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡقِتَالُ تَوَلَّوۡ<rule class=slnt>اۡ</rule> إِلَّا قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٤٦',
    246, 2, 1, 40, 33, 16, 'false'
  );
  
  -- Ayah 247 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    254,
    'وَقَالَ لَهُمۡ نَبِیُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكࣰاۚ قَالُوۤا۟ أَنَّىٰ یَكُونُ لَهُ ٱلۡمُلۡكُ عَلَیۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ یُؤۡتَ سَعَةࣰ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَیۡكُمۡ وَزَادَهُۥ بَسۡطَةࣰ فِی ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ یُؤۡتِی مُلۡكَهُۥ مَن یَشَاۤءُۚ وَٱللَّهُ وَ ٰ⁠سِعٌ عَلِیمࣱ',
    'وقال لهم نبيهم ان الله قد بعث لكم طالوت ملكا قالوا انى يكون له الملك علينا ونحن احق بالملك منه ولم يؤت سعة من المال قال ان الله اصطفاه عليكم وزاده بسطة في العلم والجسم والله يؤتي ملكه من يشاء والله واسع عليم',
    'وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَ<rule class=qalaqah>دۡ</rule> بَعَثَ لَكُمۡ طَالُوتَ مَلِ<rule class=ikhafa>كًا‌ۚ</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َىٰ يَكُونُ لَهُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِ<rule class=ham_wasl>ٱ</rule>لۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمَالِ‌ۚ قَالَ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>صۡطَفَ<rule class=madda_normal>ـٰ</rule>هُ عَلَيۡكُمۡ وَزَادَهُ<rule class=madda_normal>ۥ</rule> بَسۡطَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ وَ<rule class=ham_wasl>ٱ</rule>لۡجِسۡمِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُؤۡتِى مُلۡكَهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ و<rule class=madda_normal>ٰ</rule>سِعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٤٧',
    247, 2, 1, 40, 33, 16, 'false'
  );
  
  -- Ayah 248 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    255,
    'وَقَالَ لَهُمۡ نَبِیُّهُمۡ إِنَّ ءَایَةَ مُلۡكِهِۦۤ أَن یَأۡتِیَكُمُ ٱلتَّابُوتُ فِیهِ سَكِینَةࣱ مِّن رَّبِّكُمۡ وَبَقِیَّةࣱ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَـٰرُونَ تَحۡمِلُهُ ٱلۡمَلَـٰۤىِٕكَةُۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِینَ',
    'وقال لهم نبيهم ان اية ملكه ان ياتيكم التابوت فيه سكينة من ربكم وبقية مما ترك ال موسى وال هارون تحمله الملائكة ان في ذلك لاية لكم ان كنتم مؤمنين',
    'وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِ<rule class=ghunnah>نّ</rule>َ ءَايَةَ مُلۡكِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّابُوتُ فِيهِ سَكِينَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَبَقِيَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَ<rule class=madda_normal>ـٰ</rule>رُونَ تَحۡمِلُهُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢٤٨',
    248, 2, 1, 40, 33, 16, 'false'
  );
  
  -- Ayah 249 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    256,
    'فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِیكُم بِنَهَرࣲ فَمَن شَرِبَ مِنۡهُ فَلَیۡسَ مِنِّی وَمَن لَّمۡ یَطۡعَمۡهُ فَإِنَّهُۥ مِنِّیۤ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِیَدِهِۦۚ فَشَرِبُوا۟ مِنۡهُ إِلَّا قَلِیلࣰا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلۡیَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِینَ یَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةࣲ قَلِیلَةٍ غَلَبَتۡ فِئَةࣰ كَثِیرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِینَ',
    'فلما فصل طالوت بالجنود قال ان الله مبتليكم بنهر فمن شرب منه فليس مني ومن لم يطعمه فانه مني الا من اغترف غرفة بيده فشربوا منه الا قليلا منهم فلما جاوزه هو والذين امنوا معه قالوا لا طاقة لنا اليوم بجالوت وجنوده قال الذين يظنون انهم ملاقو الله كم من فئة قليلة غلبت فئة كثيرة باذن الله والله مع الصابرين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا فَصَلَ طَالُوتُ بِ<rule class=ham_wasl>ٱ</rule>لۡجُنُودِ قَالَ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مُ<rule class=qalaqah>بۡ</rule>تَلِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِنَهَ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َرِبَ مِنۡهُ فَلَيۡسَ مِ<rule class=ghunnah>نّ</rule>ِى وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَ<rule class=qalaqah>طۡ</rule>عَمۡهُ فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَّا مَنِ <rule class=ham_wasl>ٱ</rule>غۡتَرَفَ غُرۡفَ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>ِيَدِه<rule class=madda_normal>ِۦ</rule>‌ۚ فَشَرِبُو<rule class=slnt>اۡ</rule> مِنۡهُ إِلَّا قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ‌ۚ فَلَ<rule class=ghunnah>مّ</rule>َا جَاوَزَهُ<rule class=madda_normal>ۥ</rule> هُوَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> قَالُو<rule class=slnt>اۡ</rule> لَا طَاقَةَ لَنَا <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ بِجَالُوتَ وَجُنُودِه<rule class=madda_normal>ِۦ</rule>‌ۚ قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَظُ<rule class=ghunnah>نّ</rule>ُونَ أَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلَ<rule class=madda_normal>ـٰ</rule>قُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهِ ك<rule class=idgham_shafawi>َم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِئَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ق</rule>َلِيلَةٍ غَلَبَتۡ فِئَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ك</rule>َثِيرَ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>ِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٢٤٩',
    249, 2, 1, 41, 34, 16, 'false'
  );
  
  -- Ayah 250 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    257,
    'وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَاۤ أَفۡرِغۡ عَلَیۡنَا صَبۡرࣰا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ',
    'ولما برزوا لجالوت وجنوده قالوا ربنا افرغ علينا صبرا وثبت اقدامنا وانصرنا على القوم الكافرين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا بَرَزُو<rule class=slnt>اۡ</rule> لِجَالُوتَ وَجُنُودِه<rule class=madda_normal>ِۦ</rule> قَالُو<rule class=slnt>اۡ</rule> رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَفۡرِغۡ عَلَيۡنَا صَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َثَبِّتۡ أَ<rule class=qalaqah>قۡ</rule>دَامَنَا وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نص</rule>ُرۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٢٥٠',
    250, 2, 1, 41, 34, 16, 'false'
  );
  
  -- Ayah 251 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    258,
    'فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا یَشَاۤءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَـٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَـٰلَمِینَ',
    'فهزموهم باذن الله وقتل داوود جالوت واتاه الله الملك والحكمة وعلمه مما يشاء ولولا دفع الله الناس بعضهم ببعض لفسدت الارض ولكن الله ذو فضل على العالمين',
    'فَهَزَمُوه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَقَتَلَ دَاوُ<rule class=madda_normal>ۥ</rule>دُ جَالُوتَ وَءَاتَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَعَلَّمَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ghunnah>مّ</rule>َا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَلَوۡلَا دَفۡعُ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ بَعۡضَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَعۡ<rule class=idgham_wo_ghunnah>ضٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّفَسَدَتِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ ذُو فَضۡلٍ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٢٥١',
    251, 2, 1, 41, 34, 16, 'false'
  );
  
  -- Ayah 252 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    259,
    'تِلۡكَ ءَایَـٰتُ ٱللَّهِ نَتۡلُوهَا عَلَیۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِینَ',
    'تلك ايات الله نتلوها عليك بالحق وانك لمن المرسلين',
    'تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>للَّهِ نَتۡلُوهَا عَلَيۡكَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َكَ لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٢٥٢',
    252, 2, 1, 41, 34, 16, 'false'
  );
  
  -- Ayah 253 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    260,
    '۞ تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَـٰتࣲۚ وَءَاتَیۡنَا عِیسَى ٱبۡنَ مَرۡیَمَ ٱلۡبَیِّنَـٰتِ وَأَیَّدۡنَـٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَاۤءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِینَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَـٰتُ وَلَـٰكِنِ ٱخۡتَلَفُوا۟ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَاۤءَ ٱللَّهُ مَا ٱقۡتَتَلُوا۟ وَلَـٰكِنَّ ٱللَّهَ یَفۡعَلُ مَا یُرِیدُ',
    'تلك الرسل فضلنا بعضهم على بعض منهم من كلم الله ورفع بعضهم درجات واتينا عيسى ابن مريم البينات وايدناه بروح القدس ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينات ولكن اختلفوا فمنهم من امن ومنهم من كفر ولو شاء الله ما اقتتلوا ولكن الله يفعل ما يريد',
    '۞تِلۡكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۘ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َلَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َءَاتَيۡنَا عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَأَيَّ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ بِرُوحِ <rule class=ham_wasl>ٱ</rule>لۡقُدُسِ‌ۗ وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تَتَلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تُ وَلَ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> فَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ ءَامَنَ وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ‌ۚ وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تَتَلُو<rule class=slnt>اۡ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَفۡعَلُ مَا يُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٢٥٣',
    253, 3, 1, 42, 34, 17, 'false'
  );
  
  -- Ayah 254 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    261,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَنفِقُوا۟ مِمَّا رَزَقۡنَـٰكُم مِّن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا بَیۡعࣱ فِیهِ وَلَا خُلَّةࣱ وَلَا شَفَـٰعَةࣱۗ وَٱلۡكَـٰفِرُونَ هُمُ ٱلظَّـٰلِمُونَ',
    'يا ايها الذين امنوا انفقوا مما رزقناكم من قبل ان ياتي يوم لا بيع فيه ولا خلة ولا شفاعة والكافرون هم الظالمون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِىَ يَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا بَيۡ<rule class=ikhafa>عٌ</rule> <rule class=ikhafa>ف</rule>ِيهِ وَلَا خُلَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا شَفَ<rule class=madda_normal>ـٰ</rule>عَ<rule class=idgham_ghunnah>ةٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرُونَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٢٥٤',
    254, 3, 1, 42, 35, 17, 'false'
  );
  
  -- Ayah 255 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    262,
    'ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡحَیُّ ٱلۡقَیُّومُۚ لَا تَأۡخُذُهُۥ سِنَةࣱ وَلَا نَوۡمࣱۚ لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِی یَشۡفَعُ عِندَهُۥۤ إِلَّا بِإِذۡنِهِۦۚ یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا یُحِیطُونَ بِشَیۡءࣲ مِّنۡ عِلۡمِهِۦۤ إِلَّا بِمَا شَاۤءَۚ وَسِعَ كُرۡسِیُّهُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَۖ وَلَا یَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِیُّ ٱلۡعَظِیمُ',
    'الله لا اله الا هو الحي القيوم لا تاخذه سنة ولا نوم له ما في السماوات وما في الارض من ذا الذي يشفع عنده الا باذنه يعلم ما بين ايديهم وما خلفهم ولا يحيطون بشيء من علمه الا بما شاء وسع كرسيه السماوات والارض ولا يئوده حفظهما وهو العلي العظيم',
    'ٱللَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَىُّ <rule class=ham_wasl>ٱ</rule>لۡقَيُّومُ‌ۚ لَا تَأۡخُذُهُ<rule class=madda_normal>ۥ</rule> سِنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَوۡ<rule class=idgham_wo_ghunnah>مٌ‌ۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِى يَشۡفَعُ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا بِإِذۡنِه<rule class=madda_normal>ِۦ</rule>‌ۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ‌ۖ وَلَا يُحِيطُونَ بِش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِلۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا بِمَا ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ وَسِعَ كُرۡسِيُّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ‌ۖ وَلَا يَــُٔودُهُ<rule class=madda_normal>ۥ</rule> حِفۡظُهُمَا‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِىُّ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٢٥٥',
    255, 3, 1, 42, 35, 17, 'false'
  );
  
  -- Ayah 256 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    263,
    'لَاۤ إِكۡرَاهَ فِی ٱلدِّینِۖ قَد تَّبَیَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَیِّۚ فَمَن یَكۡفُرۡ بِٱلطَّـٰغُوتِ وَیُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِیعٌ عَلِیمٌ',
    'لا اكراه في الدين قد تبين الرشد من الغي فمن يكفر بالطاغوت ويؤمن بالله فقد استمسك بالعروة الوثقى لا انفصام لها والله سميع عليم',
    'ل<rule class=madda_obligatory_monfasel>َآ</rule> إِكۡرَاهَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ‌ۖ قَ<rule class=idgham_mutajanisayn>د</rule> تَّبَيَّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّشۡدُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَىِّ‌ۚ فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرۡ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّ<rule class=madda_normal>ـٰ</rule>غُوتِ وَيُؤۡم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ فَقَدِ <rule class=ham_wasl>ٱ</rule>سۡتَمۡسَكَ بِ<rule class=ham_wasl>ٱ</rule>لۡعُرۡوَةِ <rule class=ham_wasl>ٱ</rule>لۡوُثۡقَىٰ لَا <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>ِصَامَ لَهَا‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٥٦',
    256, 3, 1, 42, 35, 17, 'false'
  );
  
  -- Ayah 257 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    264,
    'ٱللَّهُ وَلِیُّ ٱلَّذِینَ ءَامَنُوا۟ یُخۡرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِینَ كَفَرُوۤا۟ أَوۡلِیَاۤؤُهُمُ ٱلطَّـٰغُوتُ یُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَـٰتِۗ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'الله ولي الذين امنوا يخرجهم من الظلمات الى النور والذين كفروا اولياؤهم الطاغوت يخرجونهم من النور الى الظلمات اولئك اصحاب النار هم فيها خالدون',
    'ٱللَّهُ وَلِىُّ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> يُخۡرِجُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّ<rule class=madda_normal>ـٰ</rule>غُوتُ يُخۡرِجُونَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ‌ۗ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٢٥٧',
    257, 3, 1, 43, 35, 17, 'false'
  );
  
  -- Ayah 258 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    265,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِی حَاۤجَّ إِبۡرَ ٰ⁠هِـۧمَ فِی رَبِّهِۦۤ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَ ٰ⁠هِـۧمُ رَبِّیَ ٱلَّذِی یُحۡیِۦ وَیُمِیتُ قَالَ أَنَا۠ أُحۡیِۦ وَأُمِیتُۖ قَالَ إِبۡرَ ٰ⁠هِـۧمُ فَإِنَّ ٱللَّهَ یَأۡتِی بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِی كَفَرَۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'الم تر الى الذي حاج ابراهيم في ربه ان اتاه الله الملك اذ قال ابراهيم ربي الذي يحيي ويميت قال انا احيي واميت قال ابراهيم فان الله ياتي بالشمس من المشرق فات بها من المغرب فبهت الذي كفر والله لا يهدي القوم الظالمين',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِى ح<rule class=madda_necessary>َا</rule>ٓجَّ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مَ فِى رَبِّه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَنۡ ءَاتَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكَ إِذۡ قَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مُ رَبِّىَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُ قَالَ أَنَاۡ أُحۡى<rule class=madda_normal>ِۦ</rule> وَأُمِيتُ‌ۖ قَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مُ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَأۡتِى بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَغۡرِبِ فَبُهِتَ <rule class=ham_wasl>ٱ</rule>لَّذِى كَفَرَ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٥٨',
    258, 3, 1, 43, 36, 17, 'false'
  );
  
  -- Ayah 259 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    266,
    'أَوۡ كَٱلَّذِی مَرَّ عَلَىٰ قَرۡیَةࣲ وَهِیَ خَاوِیَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ یُحۡیِۦ هَـٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامࣲ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ یَوۡمًا أَوۡ بَعۡضَ یَوۡمࣲۖ قَالَ بَل لَّبِثۡتَ مِا۟ئَةَ عَامࣲ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ یَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَایَةࣰ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَیۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمࣰاۚ فَلَمَّا تَبَیَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'او كالذي مر على قرية وهي خاوية على عروشها قال انى يحيي هذه الله بعد موتها فاماته الله مائة عام ثم بعثه قال كم لبثت قال لبثت يوما او بعض يوم قال بل لبثت مائة عام فانظر الى طعامك وشرابك لم يتسنه وانظر الى حمارك ولنجعلك اية للناس وانظر الى العظام كيف ننشزها ثم نكسوها لحما فلما تبين له قال اعلم ان الله على كل شيء قدير',
    'أَوۡ كَ<rule class=ham_wasl>ٱ</rule>لَّذِى مَرَّ عَلَىٰ قَرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَ<rule class=ghunnah>نّ</rule>َىٰ يُحۡى<rule class=madda_normal>ِۦ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>للَّهُ بَعۡدَ مَوۡتِهَا‌ۖ فَأَمَاتَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=slnt>اۡ</rule>ئَةَ عَا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ بَعَثَهُ<rule class=madda_normal>ۥ</rule>‌ۖ قَالَ كَمۡ لَبِثۡتَ‌ۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡ<rule class=ikhafa>مٍ‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ بَل لَّبِثۡتَ مِ<rule class=slnt>اۡ</rule>ئَةَ عَا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَ<rule class=ghunnah>نّ</rule>َهۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ إِلَىٰ حِمَارِكَ وَلِنَ<rule class=qalaqah>جۡ</rule>عَلَكَ ءَايَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡعِظَامِ كَيۡفَ نُ<rule class=ikhafa>نش</rule>ِزُهَا ثُ<rule class=ghunnah>مّ</rule>َ نَكۡسُوهَا لَحۡ<rule class=ikhafa>مًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َلَ<rule class=ghunnah>مّ</rule>َا تَبَيَّنَ لَهُ<rule class=madda_normal>ۥ</rule> قَالَ أَعۡلَمُ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٢٥٩',
    259, 3, 1, 43, 36, 17, 'false'
  );
  
  -- Ayah 260 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    267,
    'وَإِذۡ قَالَ إِبۡرَ ٰ⁠هِـۧمُ رَبِّ أَرِنِی كَیۡفَ تُحۡیِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَلَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَـٰكِن لِّیَطۡمَىِٕنَّ قَلۡبِیۖ قَالَ فَخُذۡ أَرۡبَعَةࣰ مِّنَ ٱلطَّیۡرِ فَصُرۡهُنَّ إِلَیۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلࣲ مِّنۡهُنَّ جُزۡءࣰا ثُمَّ ٱدۡعُهُنَّ یَأۡتِینَكَ سَعۡیࣰاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ',
    'واذ قال ابراهيم رب ارني كيف تحيي الموتى قال اولم تؤمن قال بلى ولكن ليطمئن قلبي قال فخذ اربعة من الطير فصرهن اليك ثم اجعل على كل جبل منهن جزءا ثم ادعهن ياتينك سعيا واعلم ان الله عزيز حكيم',
    'وَإِذۡ قَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِـ<rule class=madda_normal>ـۧ</rule>مُ رَبِّ أَرِنِى كَيۡفَ تُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ‌ۖ قَالَ أَوَلَمۡ تُؤۡمِ<rule class=ikhafa>ن‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ بَلَىٰ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>َ قَلۡبِى‌ۖ قَالَ فَخُذۡ أَرۡبَعَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرِ فَصُرۡهُ<rule class=ghunnah>نّ</rule>َ إِلَيۡكَ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡ عَلَىٰ كُلِّ جَبَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ<rule class=ghunnah>نّ</rule>َ جُزۡ<rule class=ikhafa>ءًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُهُ<rule class=ghunnah>نّ</rule>َ يَأۡتِينَكَ سَعۡ<rule class=idgham_ghunnah>يًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>عۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٢٦٠',
    260, 3, 1, 44, 36, 17, 'false'
  );
  
  -- Ayah 261 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    268,
    'مَّثَلُ ٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰ⁠لَهُمۡ فِی سَبِیلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِی كُلِّ سُنۢبُلَةࣲ مِّا۟ئَةُ حَبَّةࣲۗ وَٱللَّهُ یُضَـٰعِفُ لِمَن یَشَاۤءُۚ وَٱللَّهُ وَ ٰ⁠سِعٌ عَلِیمٌ',
    'مثل الذين ينفقون اموالهم في سبيل الله كمثل حبة انبتت سبع سنابل في كل سنبلة مائة حبة والله يضاعف لمن يشاء والله واسع عليم',
    'مَّثَلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُ<rule class=ikhafa>نف</rule>ِقُونَ أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ كَمَثَلِ حَبَّةٍ أَ<rule class=iqlab>نۢب</rule>َتَتۡ سَ<rule class=qalaqah>بۡ</rule>عَ سَنَابِلَ فِى كُلِّ سُ<rule class=iqlab>نۢب</rule>ُلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=slnt>اۡ</rule>ئَةُ حَبَّ<rule class=idgham_ghunnah>ةٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ يُضَ<rule class=madda_normal>ـٰ</rule>عِفُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ و<rule class=madda_normal>ٰ</rule>سِعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٦١',
    261, 3, 1, 44, 37, 17, 'false'
  );
  
  -- Ayah 262 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    269,
    'ٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰ⁠لَهُمۡ فِی سَبِیلِ ٱللَّهِ ثُمَّ لَا یُتۡبِعُونَ مَاۤ أَنفَقُوا۟ مَنࣰّا وَلَاۤ أَذࣰى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'الذين ينفقون اموالهم في سبيل الله ثم لا يتبعون ما انفقوا منا ولا اذى لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون',
    'ٱلَّذِينَ يُ<rule class=ikhafa>نف</rule>ِقُونَ أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ لَا يُتۡبِعُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ</rule> مَن<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=idgham_wo_ghunnah>ذًى‌ۙ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ أَ<rule class=qalaqah>جۡ</rule>رُهُمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٢٦٢',
    262, 3, 1, 44, 37, 17, 'false'
  );
  
  -- Ayah 263 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    270,
    '۞ قَوۡلࣱ مَّعۡرُوفࣱ وَمَغۡفِرَةٌ خَیۡرࣱ مِّن صَدَقَةࣲ یَتۡبَعُهَاۤ أَذࣰىۗ وَٱللَّهُ غَنِیٌّ حَلِیمࣱ',
    'قول معروف ومغفرة خير من صدقة يتبعها اذى والله غني حليم',
    '۞قَوۡ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُو<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَغۡفِرَةٌ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َدَقَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتۡبَعُه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=idgham_ghunnah>ذًى‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ غَنِىٌّ حَل<rule class=madda_permissible>ِي</rule>مٌ ٢٦٣',
    263, 3, 1, 44, 37, 18, 'false'
  );
  
  -- Ayah 264 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    271,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُبۡطِلُوا۟ صَدَقَـٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِی یُنفِقُ مَالَهُۥ رِئَاۤءَ ٱلنَّاسِ وَلَا یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَیۡهِ تُرَابࣱ فَأَصَابَهُۥ وَابِلࣱ فَتَرَكَهُۥ صَلۡدࣰاۖ لَّا یَقۡدِرُونَ عَلَىٰ شَیۡءࣲ مِّمَّا كَسَبُوا۟ۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡكَـٰفِرِینَ',
    'يا ايها الذين امنوا لا تبطلوا صدقاتكم بالمن والاذى كالذي ينفق ماله رئاء الناس ولا يؤمن بالله واليوم الاخر فمثله كمثل صفوان عليه تراب فاصابه وابل فتركه صلدا لا يقدرون على شيء مما كسبوا والله لا يهدي القوم الكافرين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تُ<rule class=qalaqah>بۡ</rule>طِلُو<rule class=slnt>اۡ</rule> صَدَقَ<rule class=madda_normal>ـٰ</rule>تِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَذَىٰ كَ<rule class=ham_wasl>ٱ</rule>لَّذِى يُ<rule class=ikhafa>نف</rule>ِقُ مَالَهُ<rule class=madda_normal>ۥ</rule> رِئ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَا يُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ‌ۖ فَمَثَلُهُ<rule class=madda_normal>ۥ</rule> كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ف</rule>َأَصَابَهُ<rule class=madda_normal>ۥ</rule> وَابِ<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ف</rule>َتَرَكَهُ<rule class=madda_normal>ۥ</rule> صَلۡ<rule class=idgham_wo_ghunnah>دًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَ<rule class=qalaqah>قۡ</rule>دِرُونَ عَلَىٰ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا كَسَبُو<rule class=slnt>اۡ‌ۗ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٢٦٤',
    264, 3, 1, 44, 37, 18, 'false'
  );
  
  -- Ayah 265 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    272,
    'وَمَثَلُ ٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰ⁠لَهُمُ ٱبۡتِغَاۤءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِیتࣰا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلࣱ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَیۡنِ فَإِن لَّمۡ یُصِبۡهَا وَابِلࣱ فَطَلࣱّۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرٌ',
    'ومثل الذين ينفقون اموالهم ابتغاء مرضات الله وتثبيتا من انفسهم كمثل جنة بربوة اصابها وابل فاتت اكلها ضعفين فان لم يصبها وابل فطل والله بما تعملون بصير',
    'وَمَثَلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُ<rule class=ikhafa>نف</rule>ِقُونَ أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَرۡضَاتِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَتَثۡبِي<rule class=idgham_ghunnah>تًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ كَمَثَلِ جَ<rule class=ghunnah>نّ</rule>َ<rule class=iqlab>ةِۭ</rule> <rule class=iqlab>ب</rule>ِرَ<rule class=qalaqah>بۡ</rule>وَةٍ أَصَابَهَا وَابِ<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ف</rule>َـَٔـاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يُصِ<rule class=qalaqah>بۡ</rule>هَا وَابِ<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ف</rule>َطَ<rule class=idgham_ghunnah>لٌّ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٢٦٥',
    265, 3, 1, 45, 37, 18, 'false'
  );
  
  -- Ayah 266 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    273,
    'أَیَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةࣱ مِّن نَّخِیلࣲ وَأَعۡنَابࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ لَهُۥ فِیهَا مِن كُلِّ ٱلثَّمَرَ ٰ⁠تِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّیَّةࣱ ضُعَفَاۤءُ فَأَصَابَهَاۤ إِعۡصَارࣱ فِیهِ نَارࣱ فَٱحۡتَرَقَتۡۗ كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ',
    'ايود احدكم ان تكون له جنة من نخيل واعناب تجري من تحتها الانهار له فيها من كل الثمرات واصابه الكبر وله ذرية ضعفاء فاصابها اعصار فيه نار فاحترقت كذلك يبين الله لكم الايات لعلكم تتفكرون',
    'أَيَوَدُّ أَحَدُكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونَ لَهُ<rule class=madda_normal>ۥ</rule> جَ<rule class=ghunnah>نّ</rule>َ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّخِي<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَعۡنَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ لَهُ<rule class=madda_normal>ۥ</rule> فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ وَأَصَابَهُ <rule class=ham_wasl>ٱ</rule>لۡكِبَرُ وَلَهُ<rule class=madda_normal>ۥ</rule> ذُرِّيَّ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ض</rule>ُعَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فَأَصَابَه<rule class=madda_obligatory_monfasel>َآ</rule> إِعۡصَا<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>ِيهِ نَا<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>حۡتَرَقَتۡ‌ۗ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لَعَلَّكُمۡ تَتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٦٦',
    266, 3, 1, 45, 37, 18, 'false'
  );
  
  -- Ayah 267 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    274,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَنفِقُوا۟ مِن طَیِّبَـٰتِ مَا كَسَبۡتُمۡ وَمِمَّاۤ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَیَمَّمُوا۟ ٱلۡخَبِیثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِیهِ إِلَّاۤ أَن تُغۡمِضُوا۟ فِیهِۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ غَنِیٌّ حَمِیدٌ',
    'يا ايها الذين امنوا انفقوا من طيبات ما كسبتم ومما اخرجنا لكم من الارض ولا تيمموا الخبيث منه تنفقون ولستم باخذيه الا ان تغمضوا فيه واعلموا ان الله غني حميد',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=madda_normal>ـٰ</rule>تِ مَا كَسَ<rule class=qalaqah>بۡ</rule>تُمۡ وَمِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَخۡرَ<rule class=qalaqah>جۡ</rule>نَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَلَا تَيَ<rule class=ghunnah>مّ</rule>َمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَبِيثَ مِنۡهُ تُ<rule class=ikhafa>نف</rule>ِقُونَ وَلَسۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـاخِذِيهِ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُغۡمِضُو<rule class=slnt>اۡ</rule> فِيهِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَنِىٌّ حَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٢٦٧',
    267, 3, 1, 45, 38, 18, 'false'
  );
  
  -- Ayah 268 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    275,
    'ٱلشَّیۡطَـٰنُ یَعِدُكُمُ ٱلۡفَقۡرَ وَیَأۡمُرُكُم بِٱلۡفَحۡشَاۤءِۖ وَٱللَّهُ یَعِدُكُم مَّغۡفِرَةࣰ مِّنۡهُ وَفَضۡلࣰاۗ وَٱللَّهُ وَ ٰ⁠سِعٌ عَلِیمࣱ',
    'الشيطان يعدكم الفقر ويامركم بالفحشاء والله يعدكم مغفرة منه وفضلا والله واسع عليم',
    'ٱ<rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ يَعِدُكُمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=qalaqah>قۡ</rule>رَ وَيَأۡمُرُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡفَحۡش<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعِدُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ وَفَضۡل<rule class=idgham_ghunnah>اً‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ و<rule class=madda_normal>ٰ</rule>سِعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٦٨',
    268, 3, 1, 45, 38, 18, 'false'
  );
  
  -- Ayah 269 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    276,
    'یُؤۡتِی ٱلۡحِكۡمَةَ مَن یَشَاۤءُۚ وَمَن یُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِیَ خَیۡرࣰا كَثِیرࣰاۗ وَمَا یَذَّكَّرُ إِلَّاۤ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ',
    'يؤتي الحكمة من يشاء ومن يؤت الحكمة فقد اوتي خيرا كثيرا وما يذكر الا اولو الالباب',
    'يُؤۡتِى <rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡتَ <rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ فَقَ<rule class=qalaqah>دۡ</rule> أُوتِىَ خَيۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َثِي<rule class=idgham_ghunnah>رًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َمَا يَذَّكَّرُ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٢٦٩',
    269, 3, 1, 45, 38, 18, 'false'
  );
  
  -- Ayah 270 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    277,
    'وَمَاۤ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرࣲ فَإِنَّ ٱللَّهَ یَعۡلَمُهُۥۗ وَمَا لِلظَّـٰلِمِینَ مِنۡ أَنصَارٍ',
    'وما انفقتم من نفقة او نذرتم من نذر فان الله يعلمه وما للظالمين من انصار',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َ<rule class=qalaqah>قۡ</rule>ت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّفَقَةٍ أَوۡ نَذَرۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّذۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَمَا لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ مِنۡ أَ<rule class=ikhafa>نص</rule><rule class=madda_permissible>َا</rule>رٍ ٢٧٠',
    270, 3, 1, 46, 38, 18, 'false'
  );
  
  -- Ayah 271 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    278,
    'إِن تُبۡدُوا۟ ٱلصَّدَقَـٰتِ فَنِعِمَّا هِیَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَاۤءَ فَهُوَ خَیۡرࣱ لَّكُمۡۚ وَیُكَفِّرُ عَنكُم مِّن سَیِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ',
    'ان تبدوا الصدقات فنعما هي وان تخفوها وتؤتوها الفقراء فهو خير لكم ويكفر عنكم من سيئاتكم والله بما تعملون خبير',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>بۡ</rule>دُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّدَقَ<rule class=madda_normal>ـٰ</rule>تِ فَنِعِ<rule class=ghunnah>مّ</rule>َا هِىَ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُخۡفُوهَا وَتُؤۡتُوهَا <rule class=ham_wasl>ٱ</rule>لۡفُقَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَهُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۚ وَيُكَفِّرُ عَ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َيِّـَٔـاتِكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ٢٧١',
    271, 3, 1, 46, 38, 18, 'false'
  );
  
  -- Ayah 272 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    279,
    '۞ لَّیۡسَ عَلَیۡكَ هُدَىٰهُمۡ وَلَـٰكِنَّ ٱللَّهَ یَهۡدِی مَن یَشَاۤءُۗ وَمَا تُنفِقُوا۟ مِنۡ خَیۡرࣲ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَاۤءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُوا۟ مِنۡ خَیۡرࣲ یُوَفَّ إِلَیۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ',
    'ليس عليك هداهم ولكن الله يهدي من يشاء وما تنفقوا من خير فلانفسكم وما تنفقون الا ابتغاء وجه الله وما تنفقوا من خير يوف اليكم وانتم لا تظلمون',
    '۞لَّيۡسَ عَلَيۡكَ هُدَ<rule class=madda_normal>ٮٰ</rule>هُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَمَا تُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َلِأَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۚ وَمَا تُ<rule class=ikhafa>نف</rule>ِقُونَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَ<rule class=qalaqah>جۡ</rule>هِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَمَا تُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِنۡ خَيۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوَفَّ إِلَيۡكُمۡ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٧٢',
    272, 3, 1, 46, 38, 19, 'false'
  );
  
  -- Ayah 273 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    280,
    'لِلۡفُقَرَاۤءِ ٱلَّذِینَ أُحۡصِرُوا۟ فِی سَبِیلِ ٱللَّهِ لَا یَسۡتَطِیعُونَ ضَرۡبࣰا فِی ٱلۡأَرۡضِ یَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِیَاۤءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِیمَـٰهُمۡ لَا یَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافࣰاۗ وَمَا تُنفِقُوا۟ مِنۡ خَیۡرࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِیمٌ',
    'للفقراء الذين احصروا في سبيل الله لا يستطيعون ضربا في الارض يحسبهم الجاهل اغنياء من التعفف تعرفهم بسيماهم لا يسالون الناس الحافا وما تنفقوا من خير فان الله به عليم',
    'لِلۡفُقَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُحۡصِرُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا يَسۡتَطِيعُونَ ضَرۡ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يَحۡسَبُهُمُ <rule class=ham_wasl>ٱ</rule>لۡجَاهِلُ أَغۡنِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّعَفُّفِ تَعۡرِفُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسِيمَ<rule class=madda_normal>ـٰ</rule>هُمۡ لَا يَسۡــَٔلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ إِلۡحَا<rule class=idgham_ghunnah>فًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َمَا تُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِه<rule class=madda_normal>ِۦ</rule> عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٧٣',
    273, 3, 1, 46, 38, 19, 'false'
  );
  
  -- Ayah 274 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    281,
    'ٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰ⁠لَهُم بِٱلَّیۡلِ وَٱلنَّهَارِ سِرࣰّا وَعَلَانِیَةࣰ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'الذين ينفقون اموالهم بالليل والنهار سرا وعلانية فلهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون',
    'ٱلَّذِينَ يُ<rule class=ikhafa>نف</rule>ِقُونَ أَمۡو<rule class=madda_normal>ٰ</rule>لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ سِر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َعَلَانِيَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َلَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رُهُمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٢٧٤',
    274, 3, 1, 46, 39, 19, 'false'
  );
  
  -- Ayah 275 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    282,
    'ٱلَّذِینَ یَأۡكُلُونَ ٱلرِّبَوٰا۟ لَا یَقُومُونَ إِلَّا كَمَا یَقُومُ ٱلَّذِی یَتَخَبَّطُهُ ٱلشَّیۡطَـٰنُ مِنَ ٱلۡمَسِّۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَالُوۤا۟ إِنَّمَا ٱلۡبَیۡعُ مِثۡلُ ٱلرِّبَوٰا۟ۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَیۡعَ وَحَرَّمَ ٱلرِّبَوٰا۟ۚ فَمَن جَاۤءَهُۥ مَوۡعِظَةࣱ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥۤ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'الذين ياكلون الربا لا يقومون الا كما يقوم الذي يتخبطه الشيطان من المس ذلك بانهم قالوا انما البيع مثل الربا واحل الله البيع وحرم الربا فمن جاءه موعظة من ربه فانتهى فله ما سلف وامره الى الله ومن عاد فاولئك اصحاب النار هم فيها خالدون',
    'ٱلَّذِينَ يَأۡكُلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّبَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>اۡ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ <rule class=ham_wasl>ٱ</rule>لَّذِى يَتَخَبَّطُهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَسِّ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡبَيۡعُ مِثۡلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّبَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>اۡ‌ۗ وَأَحَلَّ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡبَيۡعَ وَحَرَّمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّبَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>اۡ‌ۚ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_normal>ۥ</rule> مَوۡعِظَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule> فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َهَىٰ فَلَهُ<rule class=madda_normal>ۥ</rule> مَا سَلَفَ وَأَمۡرُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَمَنۡ عَادَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٢٧٥',
    275, 3, 1, 47, 39, 19, 'false'
  );
  
  -- Ayah 276 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    283,
    'یَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَیُرۡبِی ٱلصَّدَقَـٰتِۗ وَٱللَّهُ لَا یُحِبُّ كُلَّ كَفَّارٍ أَثِیمٍ',
    'يمحق الله الربا ويربي الصدقات والله لا يحب كل كفار اثيم',
    'يَمۡحَقُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّبَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>اۡ وَيُرۡبِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّدَقَ<rule class=madda_normal>ـٰ</rule>تِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَث<rule class=madda_permissible>ِي</rule>مٍ ٢٧٦',
    276, 3, 1, 47, 39, 19, 'false'
  );
  
  -- Ayah 277 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    284,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'ان الذين امنوا وعملوا الصالحات واقاموا الصلاة واتوا الزكاة لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَأَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ لَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رُهُمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٢٧٧',
    277, 3, 1, 47, 39, 19, 'false'
  );
  
  -- Ayah 278 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    285,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِیَ مِنَ ٱلرِّبَوٰۤا۟ إِن كُنتُم مُّؤۡمِنِینَ',
    'يا ايها الذين امنوا اتقوا الله وذروا ما بقي من الربا ان كنتم مؤمنين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَذَرُو<rule class=slnt>اۡ</rule> مَا بَقِىَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّبَ<rule class=madda_obligatory_monfasel><rule class=slnt>و</rule>ٰٓاۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢٧٨',
    278, 3, 1, 47, 39, 19, 'false'
  );
  
  -- Ayah 279 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    286,
    'فَإِن لَّمۡ تَفۡعَلُوا۟ فَأۡذَنُوا۟ بِحَرۡبࣲ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَ ٰ⁠لِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ',
    'فان لم تفعلوا فاذنوا بحرب من الله ورسوله وان تبتم فلكم رءوس اموالكم لا تظلمون ولا تظلمون',
    'فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَفۡعَلُو<rule class=slnt>اۡ</rule> فَأۡذَنُو<rule class=slnt>اۡ</rule> بِحَرۡ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>بۡ</rule>تُمۡ فَلَكُمۡ رُءُوسُ أَمۡو<rule class=madda_normal>ٰ</rule>لِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٧٩',
    279, 3, 1, 47, 39, 19, 'false'
  );
  
  -- Ayah 280 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    287,
    'وَإِن كَانَ ذُو عُسۡرَةࣲ فَنَظِرَةٌ إِلَىٰ مَیۡسَرَةࣲۚ وَأَن تَصَدَّقُوا۟ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ',
    'وان كان ذو عسرة فنظرة الى ميسرة وان تصدقوا خير لكم ان كنتم تعلمون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ ذُو عُسۡرَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َنَظِرَةٌ إِلَىٰ مَيۡسَرَ<rule class=idgham_ghunnah>ةٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصَدَّقُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٨٠',
    280, 3, 1, 47, 39, 19, 'false'
  );
  
  -- Ayah 281 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    288,
    'وَٱتَّقُوا۟ یَوۡمࣰا تُرۡجَعُونَ فِیهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا یُظۡلَمُونَ',
    'واتقوا يوما ترجعون فيه الى الله ثم توفى كل نفس ما كسبت وهم لا يظلمون',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> يَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ت</rule>ُرۡجَعُونَ فِيهِ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ تُوَفَّىٰ كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٨١',
    281, 3, 1, 47, 39, 19, 'false'
  );
  
  -- Ayah 282 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    289,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا تَدَایَنتُم بِدَیۡنٍ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى فَٱكۡتُبُوهُۚ وَلۡیَكۡتُب بَّیۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا یَأۡبَ كَاتِبٌ أَن یَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡیَكۡتُبۡ وَلۡیُمۡلِلِ ٱلَّذِی عَلَیۡهِ ٱلۡحَقُّ وَلۡیَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا یَبۡخَسۡ مِنۡهُ شَیۡـࣰٔاۚ فَإِن كَانَ ٱلَّذِی عَلَیۡهِ ٱلۡحَقُّ سَفِیهًا أَوۡ ضَعِیفًا أَوۡ لَا یَسۡتَطِیعُ أَن یُمِلَّ هُوَ فَلۡیُمۡلِلۡ وَلِیُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُوا۟ شَهِیدَیۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ یَكُونَا رَجُلَیۡنِ فَرَجُلࣱ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَاۤءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا یَأۡبَ ٱلشُّهَدَاۤءُ إِذَا مَا دُعُوا۟ۚ وَلَا تَسۡـَٔمُوۤا۟ أَن تَكۡتُبُوهُ صَغِیرًا أَوۡ كَبِیرًا إِلَىٰۤ أَجَلِهِۦۚ ذَ ٰ⁠لِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَـٰدَةِ وَأَدۡنَىٰۤ أَلَّا تَرۡتَابُوۤا۟ إِلَّاۤ أَن تَكُونَ تِجَـٰرَةً حَاضِرَةࣰ تُدِیرُونَهَا بَیۡنَكُمۡ فَلَیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوۤا۟ إِذَا تَبَایَعۡتُمۡۚ وَلَا یُضَاۤرَّ كَاتِبࣱ وَلَا شَهِیدࣱۚ وَإِن تَفۡعَلُوا۟ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُوا۟ ٱللَّهَۖ وَیُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'يا ايها الذين امنوا اذا تداينتم بدين الى اجل مسمى فاكتبوه وليكتب بينكم كاتب بالعدل ولا ياب كاتب ان يكتب كما علمه الله فليكتب وليملل الذي عليه الحق وليتق الله ربه ولا يبخس منه شيئا فان كان الذي عليه الحق سفيها او ضعيفا او لا يستطيع ان يمل هو فليملل وليه بالعدل واستشهدوا شهيدين من رجالكم فان لم يكونا رجلين فرجل وامراتان ممن ترضون من الشهداء ان تضل احداهما فتذكر احداهما الاخرى ولا ياب الشهداء اذا ما دعوا ولا تساموا ان تكتبوه صغيرا او كبيرا الى اجله ذلكم اقسط عند الله واقوم للشهادة وادنى الا ترتابوا الا ان تكون تجارة حاضرة تديرونها بينكم فليس عليكم جناح الا تكتبوها واشهدوا اذا تبايعتم ولا يضار كاتب ولا شهيد وان تفعلوا فانه فسوق بكم واتقوا الله ويعلمكم الله والله بكل شيء عليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا تَدَايَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِدَيۡنٍ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=ikhafa>ًّى</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>كۡتُبُوهُ‌ۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِ<rule class=iqlab>بُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>دۡ</rule>لِ‌ۚ وَلَا يَأۡبَ كَاتِبٌ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡتُبَ كَمَا عَلَّمَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ فَلۡيَكۡتُ<rule class=qalaqah>بۡ</rule> وَلۡيُمۡلِلِ <rule class=ham_wasl>ٱ</rule>لَّذِى عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَلۡيَتَّقِ <rule class=ham_wasl>ٱ</rule>للَّهَ رَبَّهُ<rule class=madda_normal>ۥ</rule> وَلَا يَ<rule class=qalaqah>بۡ</rule>خَسۡ مِنۡهُ شَيۡـ<rule class=ikhafa>ـًٔا‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ <rule class=ham_wasl>ٱ</rule>لَّذِى عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ سَفِيهًا أَوۡ ضَعِيفًا أَوۡ لَا يَسۡتَطِيعُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُمِلَّ هُوَ فَلۡيُمۡلِلۡ وَلِيُّهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>دۡ</rule>لِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>سۡتَشۡهِدُو<rule class=slnt>اۡ</rule> شَهِيدَيۡنِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّجَالِكُمۡ‌ۖ فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَكُونَا رَجُلَيۡنِ فَرَجُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>مۡرَأَتَانِ مِ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرۡضَوۡنَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َضِلَّ إِحۡدَ<rule class=madda_normal>ٮٰ</rule>هُمَا فَتُذَكِّرَ إِحۡدَ<rule class=madda_normal>ٮٰ</rule>هُمَا <rule class=ham_wasl>ٱ</rule>لۡأُخۡرَىٰ‌ۚ وَلَا يَأۡبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِذَا مَا دُعُو<rule class=slnt>اۡ‌ۚ</rule> وَلَا تَسۡــَٔم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكۡتُبُوهُ صَغِيرًا أَوۡ كَبِيرًا إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَلِه<rule class=madda_normal>ِۦ</rule>‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ أَ<rule class=qalaqah>قۡ</rule>سَطُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَأَ<rule class=qalaqah>قۡ</rule>وَمُ لِلشَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ وَأَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَلَّا تَرۡتَاب<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۖ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونَ تِجَ<rule class=madda_normal>ـٰ</rule>رَةً حَاضِرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>ُدِيرُونَهَا بَيۡنَكُمۡ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَا‌ۗ وَأَشۡهِد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا تَبَايَعۡتُمۡ‌ۚ وَلَا يُض<rule class=madda_necessary>َا</rule>ٓرَّ كَاتِ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا شَهِي<rule class=idgham_ghunnah>دٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َفۡعَلُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> فُسُو<rule class=iqlab>قُۢ</rule> <rule class=iqlab>ب</rule>ِكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ وَيُعَلِّمُكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٨٢',
    282, 3, 1, 48, 40, 19, 'false'
  );
  
  -- Ayah 283 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    290,
    '۞ وَإِن كُنتُمۡ عَلَىٰ سَفَرࣲ وَلَمۡ تَجِدُوا۟ كَاتِبࣰا فَرِهَـٰنࣱ مَّقۡبُوضَةࣱۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضࣰا فَلۡیُؤَدِّ ٱلَّذِی ٱؤۡتُمِنَ أَمَـٰنَتَهُۥ وَلۡیَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُوا۟ ٱلشَّهَـٰدَةَۚ وَمَن یَكۡتُمۡهَا فَإِنَّهُۥۤ ءَاثِمࣱ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِیمࣱ',
    'وان كنتم على سفر ولم تجدوا كاتبا فرهان مقبوضة فان امن بعضكم بعضا فليؤد الذي اؤتمن امانته وليتق الله ربه ولا تكتموا الشهادة ومن يكتمها فانه اثم قلبه والله بما تعملون عليم',
    '۞وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ عَلَىٰ سَفَ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ تَجِدُو<rule class=slnt>اۡ</rule> كَاتِ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َرِهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>قۡ</rule>بُوضَ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِنۡ أَمِنَ بَعۡضُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡ<rule class=ikhafa>ضًا</rule> <rule class=ikhafa>ف</rule>َلۡيُؤَدِّ <rule class=ham_wasl>ٱ</rule>لَّذِى <rule class=ham_wasl>ٱ</rule>ؤۡتُمِنَ أَمَ<rule class=madda_normal>ـٰ</rule>نَتَهُ<rule class=madda_normal>ۥ</rule> وَلۡيَتَّقِ <rule class=ham_wasl>ٱ</rule>للَّهَ رَبَّهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَلَا تَكۡتُمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةَ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡتُمۡهَا فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> ءَاثِ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ق</rule>َلۡبُهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٨٣',
    283, 3, 1, 49, 40, 20, 'false'
  );
  
  -- Ayah 284 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    291,
    'لِّلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۗ وَإِن تُبۡدُوا۟ مَا فِیۤ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ یُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَیَغۡفِرُ لِمَن یَشَاۤءُ وَیُعَذِّبُ مَن یَشَاۤءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'لله ما في السماوات وما في الارض وان تبدوا ما في انفسكم او تخفوه يحاسبكم به الله فيغفر لمن يشاء ويعذب من يشاء والله على كل شيء قدير',
    'لِّلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>بۡ</rule>دُو<rule class=slnt>اۡ</rule> مَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ أَوۡ تُخۡفُوهُ يُحَاسِ<rule class=qalaqah>بۡ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ فَيَغۡفِرُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيُعَذِّبُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٢٨٤',
    284, 3, 1, 49, 41, 20, 'false'
  );
  
  -- Ayah 285 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    292,
    'ءَامَنَ ٱلرَّسُولُ بِمَاۤ أُنزِلَ إِلَیۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰۤىِٕكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَیۡنَ أَحَدࣲ مِّن رُّسُلِهِۦۚ وَقَالُوا۟ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَیۡكَ ٱلۡمَصِیرُ',
    'امن الرسول بما انزل اليه من ربه والمؤمنون كل امن بالله وملائكته وكتبه ورسله لا نفرق بين احد من رسله وقالوا سمعنا واطعنا غفرانك ربنا واليك المصير',
    'ءَامَنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡهِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ‌ۚ كُلٌّ ءَامَنَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَتِه<rule class=madda_normal>ِۦ</rule> وَكُتُبِه<rule class=madda_normal>ِۦ</rule> وَرُسُلِه<rule class=madda_normal>ِۦ</rule> لَا نُفَرِّقُ بَيۡنَ أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّسُلِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَقَالُو<rule class=slnt>اۡ</rule> سَمِعۡنَا وَأَطَعۡنَا‌ۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٢٨٥',
    285, 3, 1, 49, 41, 20, 'false'
  );
  
  -- Ayah 286 Surah Al-Baqara
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    2,
    293,
    'لَا یُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَیۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَاۤ إِن نَّسِینَاۤ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَیۡنَاۤ إِصۡرࣰا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِینَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۤۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ',
    'لا يكلف الله نفسا الا وسعها لها ما كسبت وعليها ما اكتسبت ربنا لا تؤاخذنا ان نسينا او اخطانا ربنا ولا تحمل علينا اصرا كما حملته على الذين من قبلنا ربنا ولا تحملنا ما لا طاقة لنا به واعف عنا واغفر لنا وارحمنا انت مولانا فانصرنا على القوم الكافرين',
    'لَا يُكَلِّفُ <rule class=ham_wasl>ٱ</rule>للَّهُ نَفۡسًا إِلَّا وُسۡعَهَا‌ۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا <rule class=ham_wasl>ٱ</rule>كۡتَسَبَتۡ‌ۗ رَبَّنَا لَا تُؤَاخِذۡن<rule class=madda_obligatory_monfasel>َآ</rule> إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّسِين<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ أَخۡطَأۡنَا‌ۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِصۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َمَا حَمَلۡتَهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِنَا‌ۚ رَبَّنَا وَلَا تُحَ<rule class=ghunnah>مّ</rule>ِلۡنَا مَا لَا طَاقَةَ لَنَا بِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَ<rule class=ham_wasl>ٱ</rule>عۡفُ عَ<rule class=ghunnah>نّ</rule>َا وَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَنَا وَ<rule class=ham_wasl>ٱ</rule>رۡحَمۡن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أَ<rule class=ikhafa>نت</rule>َ مَوۡلَ<rule class=madda_normal>ـٰ</rule>نَا فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نص</rule>ُرۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٢٨٦',
    286, 3, 1, 49, 41, 20, 'false'
  );
  

-- Surah Aal-i-Imraan
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (3, 'سُورَةُ آلِ عِمۡرَانَ', 'Aal-i-Imraan', 'The Family of Imraan', 'Medinan', 200);

  -- Ayah 1 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    294,
    'الۤمۤ',
    'الم',
    'ا<rule class=madda_necessary>لٓ</rule><rule class=madda_necessary>مٓ</rule> ١',
    1, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 2 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    295,
    'ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡحَیُّ ٱلۡقَیُّومُ',
    'الله لا اله الا هو الحي القيوم',
    'ٱللَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَىُّ <rule class=ham_wasl>ٱ</rule>لۡقَيّ<rule class=madda_permissible>ُو</rule>مُ ٢',
    2, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 3 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    296,
    'نَزَّلَ عَلَیۡكَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَ',
    'نزل عليك الكتاب بالحق مصدقا لما بين يديه وانزل التوراة والانجيل',
    'نَزَّلَ عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَيۡهِ وَأَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule><rule class=madda_permissible>ِي</rule>لَ ٣',
    3, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 4 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    297,
    'مِن قَبۡلُ هُدࣰى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ لَهُمۡ عَذَابࣱ شَدِیدࣱۗ وَٱللَّهُ عَزِیزࣱ ذُو ٱنتِقَامٍ',
    'من قبل هدى للناس وانزل الفرقان ان الذين كفروا بايات الله لهم عذاب شديد والله عزيز ذو انتقام',
    'مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ هُ<rule class=idgham_wo_ghunnah>دًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ وَأَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>لۡفُرۡقَانَ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَهُمۡ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عَزِي<rule class=ikhafa>زٌ</rule> <rule class=ikhafa>ذ</rule>ُو <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>ِق<rule class=madda_permissible>َا</rule>مٍ ٤',
    4, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 5 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    298,
    'إِنَّ ٱللَّهَ لَا یَخۡفَىٰ عَلَیۡهِ شَیۡءࣱ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِ',
    'ان الله لا يخفى عليه شيء في الارض ولا في السماء',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَخۡفَىٰ عَلَيۡهِ ش<rule class=ikhafa>َىۡءٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ٥',
    5, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 6 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    299,
    'هُوَ ٱلَّذِی یُصَوِّرُكُمۡ فِی ٱلۡأَرۡحَامِ كَیۡفَ یَشَاۤءُۚ لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'هو الذي يصوركم في الارحام كيف يشاء لا اله الا هو العزيز الحكيم',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُصَوِّرُكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡحَامِ كَيۡفَ يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٦',
    6, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 7 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    300,
    'هُوَ ٱلَّذِیۤ أَنزَلَ عَلَیۡكَ ٱلۡكِتَـٰبَ مِنۡهُ ءَایَـٰتࣱ مُّحۡكَمَـٰتٌ هُنَّ أُمُّ ٱلۡكِتَـٰبِ وَأُخَرُ مُتَشَـٰبِهَـٰتࣱۖ فَأَمَّا ٱلَّذِینَ فِی قُلُوبِهِمۡ زَیۡغࣱ فَیَتَّبِعُونَ مَا تَشَـٰبَهَ مِنۡهُ ٱبۡتِغَاۤءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَاۤءَ تَأۡوِیلِهِۦۖ وَمَا یَعۡلَمُ تَأۡوِیلَهُۥۤ إِلَّا ٱللَّهُۗ وَٱلرَّ ٰ⁠سِخُونَ فِی ٱلۡعِلۡمِ یَقُولُونَ ءَامَنَّا بِهِۦ كُلࣱّ مِّنۡ عِندِ رَبِّنَاۗ وَمَا یَذَّكَّرُ إِلَّاۤ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ',
    'هو الذي انزل عليك الكتاب منه ايات محكمات هن ام الكتاب واخر متشابهات فاما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنة وابتغاء تاويله وما يعلم تاويله الا الله والراسخون في العلم يقولون امنا به كل من عند ربنا وما يذكر الا اولو الالباب',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلَ عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِنۡهُ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّحۡكَمَ<rule class=madda_normal>ـٰ</rule>تٌ هُ<rule class=ghunnah>نّ</rule>َ أُ<rule class=ghunnah>مّ</rule>ُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَأُخَرُ مُتَشَ<rule class=madda_normal>ـٰ</rule>بِهَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى قُلُوبِهِمۡ زَيۡ<rule class=ikhafa>غٌ</rule> <rule class=ikhafa>ف</rule>َيَتَّبِعُونَ مَا تَشَ<rule class=madda_normal>ـٰ</rule>بَهَ مِنۡهُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡفِتۡنَةِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ تَأۡوِيلِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَمَا يَعۡلَمُ تَأۡوِيلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>سِخُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ يَقُولُونَ ءَامَ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_normal>ِۦ</rule> كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ رَبِّنَا‌ۗ وَمَا يَذَّكَّرُ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٧',
    7, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 8 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    301,
    'رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَیۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ',
    'ربنا لا تزغ قلوبنا بعد اذ هديتنا وهب لنا من لدنك رحمة انك انت الوهاب',
    'رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَ<rule class=qalaqah>بۡ</rule> لَنَا م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ikhafa>نك</rule>َ رَحۡمَةً‌ۚ إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡوَهّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ُ ٨',
    8, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 9 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    302,
    'رَبَّنَاۤ إِنَّكَ جَامِعُ ٱلنَّاسِ لِیَوۡمࣲ لَّا رَیۡبَ فِیهِۚ إِنَّ ٱللَّهَ لَا یُخۡلِفُ ٱلۡمِیعَادَ',
    'ربنا انك جامع الناس ليوم لا ريب فيه ان الله لا يخلف الميعاد',
    'رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ جَامِعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لِيَوۡ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا رَيۡبَ فِيهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُخۡلِفُ <rule class=ham_wasl>ٱ</rule>لۡمِيع<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>َ ٩',
    9, 3, 1, 50, 42, 20, 'false'
  );
  
  -- Ayah 10 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    303,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ لَن تُغۡنِیَ عَنۡهُمۡ أَمۡوَ ٰ⁠لُهُمۡ وَلَاۤ أَوۡلَـٰدُهُم مِّنَ ٱللَّهِ شَیۡـࣰٔاۖ وَأُو۟لَـٰۤىِٕكَ هُمۡ وَقُودُ ٱلنَّارِ',
    'ان الذين كفروا لن تغني عنهم اموالهم ولا اولادهم من الله شيئا واولئك هم وقود النار',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُغۡنِىَ عَنۡهُمۡ أَمۡو<rule class=madda_normal>ٰ</rule>لُهُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمۡ وَقُودُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ١٠',
    10, 3, 1, 51, 43, 20, 'false'
  );
  
  -- Ayah 11 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    304,
    'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَذَّبُوا۟ بِـَٔایَـٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِیدُ ٱلۡعِقَابِ',
    'كداب ال فرعون والذين من قبلهم كذبوا باياتنا فاخذهم الله بذنوبهم والله شديد العقاب',
    'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَأَخَذَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِذُنُوبِهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١١',
    11, 3, 1, 51, 43, 20, 'false'
  );
  
  -- Ayah 12 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    305,
    'قُل لِّلَّذِینَ كَفَرُوا۟ سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ',
    'قل للذين كفروا ستغلبون وتحشرون الى جهنم وبئس المهاد',
    'قُل لِّلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۚ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمِه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ُ ١٢',
    12, 3, 1, 51, 43, 20, 'false'
  );
  
  -- Ayah 13 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    306,
    'قَدۡ كَانَ لَكُمۡ ءَایَةࣱ فِی فِئَتَیۡنِ ٱلۡتَقَتَاۖ فِئَةࣱ تُقَـٰتِلُ فِی سَبِیلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةࣱ یَرَوۡنَهُم مِّثۡلَیۡهِمۡ رَأۡیَ ٱلۡعَیۡنِۚ وَٱللَّهُ یُؤَیِّدُ بِنَصۡرِهِۦ مَن یَشَاۤءُۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَعِبۡرَةࣰ لِّأُو۟لِی ٱلۡأَبۡصَـٰرِ',
    'قد كان لكم اية في فئتين التقتا فئة تقاتل في سبيل الله واخرى كافرة يرونهم مثليهم راي العين والله يؤيد بنصره من يشاء ان في ذلك لعبرة لاولي الابصار',
    'قَ<rule class=qalaqah>دۡ</rule> كَانَ لَكُمۡ ءَايَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى فِئَتَيۡنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ۡتَقَتَا‌ۖ فِئَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>ُقَ<rule class=madda_normal>ـٰ</rule>تِلُ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَأُخۡرَىٰ كَافِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َرَوۡنَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّثۡلَيۡهِمۡ رَأۡىَ <rule class=ham_wasl>ٱ</rule>لۡعَيۡنِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُؤَيِّدُ بِنَصۡرِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَعِ<rule class=qalaqah>بۡ</rule>رَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_permissible>ـٰ</rule>رِ ١٣',
    13, 3, 1, 51, 43, 20, 'false'
  );
  
  -- Ayah 14 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    307,
    'زُیِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَ ٰ⁠تِ مِنَ ٱلنِّسَاۤءِ وَٱلۡبَنِینَ وَٱلۡقَنَـٰطِیرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَیۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَـٰمِ وَٱلۡحَرۡثِۗ ذَ ٰ⁠لِكَ مَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ',
    'زين للناس حب الشهوات من النساء والبنين والقناطير المقنطرة من الذهب والفضة والخيل المسومة والانعام والحرث ذلك متاع الحياة الدنيا والله عنده حسن الماب',
    'زُيِّنَ لِل<rule class=ghunnah>نّ</rule>َاسِ حُبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَو<rule class=madda_normal>ٰ</rule>تِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡبَنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَنَ<rule class=madda_normal>ـٰ</rule>طِيرِ <rule class=ham_wasl>ٱ</rule>لۡمُقَ<rule class=ikhafa>نط</rule>َرَةِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذَّهَبِ وَ<rule class=ham_wasl>ٱ</rule>لۡفِضَّةِ وَ<rule class=ham_wasl>ٱ</rule>لۡخَيۡلِ <rule class=ham_wasl>ٱ</rule>لۡمُسَوَّمَةِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ وَ<rule class=ham_wasl>ٱ</rule>لۡحَرۡثِ‌ۗ ذ<rule class=madda_normal>ٰ</rule>لِكَ مَتَ<rule class=madda_normal>ـٰ</rule>عُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> حُسۡنُ <rule class=ham_wasl>ٱ</rule>لۡمَـَٔـ<rule class=madda_permissible>ا</rule><rule class=qalaqah>ب</rule>ِ ١٤',
    14, 3, 1, 51, 43, 20, 'false'
  );
  
  -- Ayah 15 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    308,
    '۞ قُلۡ أَؤُنَبِّئُكُم بِخَیۡرࣲ مِّن ذَ ٰ⁠لِكُمۡۖ لِلَّذِینَ ٱتَّقَوۡا۟ عِندَ رَبِّهِمۡ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا وَأَزۡوَ ٰ⁠جࣱ مُّطَهَّرَةࣱ وَرِضۡوَ ٰ⁠نࣱ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِیرُۢ بِٱلۡعِبَادِ',
    'قل اؤنبئكم بخير من ذلكم للذين اتقوا عند ربهم جنات تجري من تحتها الانهار خالدين فيها وازواج مطهرة ورضوان من الله والله بصير بالعباد',
    '۞قُلۡ أَؤُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَيۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكُمۡ‌ۚ لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا وَأَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّطَهَّرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َرِضۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بَصِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعِب<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ١٥',
    15, 3, 1, 51, 43, 21, 'false'
  );
  
  -- Ayah 16 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    309,
    'ٱلَّذِینَ یَقُولُونَ رَبَّنَاۤ إِنَّنَاۤ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ',
    'الذين يقولون ربنا اننا امنا فاغفر لنا ذنوبنا وقنا عذاب النار',
    'ٱلَّذِينَ يَقُولُونَ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َن<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا فَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ١٦',
    16, 3, 1, 52, 43, 21, 'false'
  );
  
  -- Ayah 17 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    310,
    'ٱلصَّـٰبِرِینَ وَٱلصَّـٰدِقِینَ وَٱلۡقَـٰنِتِینَ وَٱلۡمُنفِقِینَ وَٱلۡمُسۡتَغۡفِرِینَ بِٱلۡأَسۡحَارِ',
    'الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالاسحار',
    'ٱ<rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِرِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِقِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>نِتِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نف</rule>ِقِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُسۡتَغۡفِرِينَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَسۡح<rule class=madda_permissible>َا</rule>رِ ١٧',
    17, 3, 1, 52, 43, 21, 'false'
  );
  
  -- Ayah 18 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    311,
    'شَهِدَ ٱللَّهُ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّا هُوَ وَٱلۡمَلَـٰۤىِٕكَةُ وَأُو۟لُوا۟ ٱلۡعِلۡمِ قَاۤىِٕمَۢا بِٱلۡقِسۡطِۚ لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'شهد الله انه لا اله الا هو والملائكة واولو العلم قائما بالقسط لا اله الا هو العزيز الحكيم',
    'شَهِدَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ وَأُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِم<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۚ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ١٨',
    18, 3, 1, 52, 43, 21, 'false'
  );
  
  -- Ayah 19 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    312,
    'إِنَّ ٱلدِّینَ عِندَ ٱللَّهِ ٱلۡإِسۡلَـٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَهُمُ ٱلۡعِلۡمُ بَغۡیَۢا بَیۡنَهُمۡۗ وَمَن یَكۡفُرۡ بِـَٔایَـٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ',
    'ان الدين عند الله الاسلام وما اختلف الذين اوتوا الكتاب الا من بعد ما جاءهم العلم بغيا بينهم ومن يكفر بايات الله فان الله سريع الحساب',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡإِسۡلَ<rule class=madda_normal>ـٰ</rule>مُ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>خۡتَلَفَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ إِلَّا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمُ بَغۡي<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَهُمۡ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرۡ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٩',
    19, 3, 1, 52, 43, 21, 'false'
  );
  
  -- Ayah 20 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    313,
    'فَإِنۡ حَاۤجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِیَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ وَٱلۡأُمِّیِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُوا۟ فَقَدِ ٱهۡتَدَوا۟ۖ وَّإِن تَوَلَّوۡا۟ فَإِنَّمَا عَلَیۡكَ ٱلۡبَلَـٰغُۗ وَٱللَّهُ بَصِیرُۢ بِٱلۡعِبَادِ',
    'فان حاجوك فقل اسلمت وجهي لله ومن اتبعن وقل للذين اوتوا الكتاب والاميين ااسلمتم فان اسلموا فقد اهتدوا وان تولوا فانما عليك البلاغ والله بصير بالعباد',
    'فَإِنۡ ح<rule class=madda_necessary>َا</rule>ٓجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَ<rule class=qalaqah>جۡ</rule>هِىَ لِلَّهِ وَمَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَنِ‌ۗ وَقُل لِّلَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ghunnah>مّ</rule>ِيِّـ<rule class=madda_normal>ـۧ</rule>نَ ءَأَسۡلَمۡتُمۡ‌ۚ فَإِنۡ أَسۡلَمُو<rule class=slnt>اۡ</rule> فَقَدِ <rule class=ham_wasl>ٱ</rule>هۡتَدَو<rule class=slnt>اۡ‌ۖ</rule> وَّإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َمَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بَصِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعِب<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٢٠',
    20, 3, 1, 52, 43, 21, 'false'
  );
  
  -- Ayah 21 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    314,
    'إِنَّ ٱلَّذِینَ یَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَیَقۡتُلُونَ ٱلنَّبِیِّـۧنَ بِغَیۡرِ حَقࣲّ وَیَقۡتُلُونَ ٱلَّذِینَ یَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِیمٍ',
    'ان الذين يكفرون بايات الله ويقتلون النبيين بغير حق ويقتلون الذين يامرون بالقسط من الناس فبشرهم بعذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَكۡفُرُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَ<rule class=qalaqah>قۡ</rule>تُلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ بِغَيۡرِ حَ<rule class=idgham_ghunnah>قٍّ</rule> <rule class=idgham_ghunnah>و</rule>َيَ<rule class=qalaqah>قۡ</rule>تُلُونَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَأۡمُرُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ فَبَشِّرۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِعَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٢١',
    21, 3, 1, 52, 44, 21, 'false'
  );
  
  -- Ayah 22 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    315,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ حَبِطَتۡ أَعۡمَـٰلُهُمۡ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِینَ',
    'اولئك الذين حبطت اعمالهم في الدنيا والاخرة وما لهم من ناصرين',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ حَبِطَتۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَمَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ٢٢',
    22, 3, 1, 52, 44, 21, 'false'
  );
  
  -- Ayah 23 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    316,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِینَ أُوتُوا۟ نَصِیبࣰا مِّنَ ٱلۡكِتَـٰبِ یُدۡعَوۡنَ إِلَىٰ كِتَـٰبِ ٱللَّهِ لِیَحۡكُمَ بَیۡنَهُمۡ ثُمَّ یَتَوَلَّىٰ فَرِیقࣱ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ',
    'الم تر الى الذين اوتوا نصيبا من الكتاب يدعون الى كتاب الله ليحكم بينهم ثم يتولى فريق منهم وهم معرضون',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> نَصِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ يُ<rule class=qalaqah>دۡ</rule>عَوۡنَ إِلَىٰ كِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>للَّهِ لِيَحۡكُمَ بَيۡنَهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يَتَوَلَّىٰ فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 3, 1, 53, 44, 21, 'false'
  );
  
  -- Ayah 24 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    317,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّاۤ أَیَّامࣰا مَّعۡدُودَ ٰ⁠تࣲۖ وَغَرَّهُمۡ فِی دِینِهِم مَّا كَانُوا۟ یَفۡتَرُونَ',
    'ذلك بانهم قالوا لن تمسنا النار الا اياما معدودات وغرهم في دينهم ما كانوا يفترون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَالُو<rule class=slnt>اۡ</rule> لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمَسَّنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَيَّا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّعۡدُود<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َغَرَّهُمۡ فِى دِينِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 3, 1, 53, 44, 21, 'false'
  );
  
  -- Ayah 25 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    318,
    'فَكَیۡفَ إِذَا جَمَعۡنَـٰهُمۡ لِیَوۡمࣲ لَّا رَیۡبَ فِیهِ وَوُفِّیَتۡ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا یُظۡلَمُونَ',
    'فكيف اذا جمعناهم ليوم لا ريب فيه ووفيت كل نفس ما كسبت وهم لا يظلمون',
    'فَكَيۡفَ إِذَا جَمَعۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ لِيَوۡ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا رَيۡبَ فِيهِ وَوُفِّيَتۡ كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 3, 1, 53, 44, 21, 'false'
  );
  
  -- Ayah 26 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    319,
    'قُلِ ٱللَّهُمَّ مَـٰلِكَ ٱلۡمُلۡكِ تُؤۡتِی ٱلۡمُلۡكَ مَن تَشَاۤءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَاۤءُ وَتُعِزُّ مَن تَشَاۤءُ وَتُذِلُّ مَن تَشَاۤءُۖ بِیَدِكَ ٱلۡخَیۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'قل اللهم مالك الملك تؤتي الملك من تشاء وتنزع الملك ممن تشاء وتعز من تشاء وتذل من تشاء بيدك الخير انك على كل شيء قدير',
    'قُلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّهُ<rule class=ghunnah>مّ</rule>َ مَ<rule class=madda_normal>ـٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكِ تُؤۡتِى <rule class=ham_wasl>ٱ</rule>لۡمُلۡكَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَتَ<rule class=ikhafa>نز</rule>ِعُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكَ مِ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَتُعِزُّ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَتُذِلُّ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ بِيَدِكَ <rule class=ham_wasl>ٱ</rule>لۡخَيۡرُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٢٦',
    26, 3, 1, 53, 44, 21, 'false'
  );
  
  -- Ayah 27 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    320,
    'تُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِۖ وَتُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَتُخۡرِجُ ٱلۡمَیِّتَ مِنَ ٱلۡحَیِّۖ وَتَرۡزُقُ مَن تَشَاۤءُ بِغَیۡرِ حِسَابࣲ',
    'تولج الليل في النهار وتولج النهار في الليل وتخرج الحي من الميت وتخرج الميت من الحي وترزق من تشاء بغير حساب',
    'تُولِجُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَتُولِجُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ فِى <rule class=ham_wasl>ٱ</rule>لَّيۡلِ‌ۖ وَتُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡحَىَّ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَيِّتِ وَتُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡمَيِّتَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَىِّ‌ۖ وَتَرۡزُقُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بِغَيۡرِ حِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٢٧',
    27, 3, 1, 53, 44, 21, 'false'
  );
  
  -- Ayah 28 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    321,
    'لَّا یَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَـٰفِرِینَ أَوۡلِیَاۤءَ مِن دُونِ ٱلۡمُؤۡمِنِینَۖ وَمَن یَفۡعَلۡ ذَ ٰ⁠لِكَ فَلَیۡسَ مِنَ ٱللَّهِ فِی شَیۡءٍ إِلَّاۤ أَن تَتَّقُوا۟ مِنۡهُمۡ تُقَىٰةࣰۗ وَیُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِیرُ',
    'لا يتخذ المؤمنون الكافرين اولياء من دون المؤمنين ومن يفعل ذلك فليس من الله في شيء الا ان تتقوا منهم تقاة ويحذركم الله نفسه والى الله المصير',
    'لَّا يَتَّخِذِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلۡ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَلَيۡسَ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ فِى شَىۡءٍ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَّقُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ تُقَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>ةً‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َيُحَذِّرُكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ نَفۡسَهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٢٨',
    28, 3, 1, 53, 44, 21, 'false'
  );
  
  -- Ayah 29 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    322,
    'قُلۡ إِن تُخۡفُوا۟ مَا فِی صُدُورِكُمۡ أَوۡ تُبۡدُوهُ یَعۡلَمۡهُ ٱللَّهُۗ وَیَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'قل ان تخفوا ما في صدوركم او تبدوه يعلمه الله ويعلم ما في السماوات وما في الارض والله على كل شيء قدير',
    'قُلۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُخۡفُو<rule class=slnt>اۡ</rule> مَا فِى صُدُورِكُمۡ أَوۡ تُ<rule class=qalaqah>بۡ</rule>دُوهُ يَعۡلَمۡهُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ وَيَعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٢٩',
    29, 3, 1, 53, 44, 21, 'false'
  );
  
  -- Ayah 30 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    323,
    'یَوۡمَ تَجِدُ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ مِنۡ خَیۡرࣲ مُّحۡضَرࣰا وَمَا عَمِلَتۡ مِن سُوۤءࣲ تَوَدُّ لَوۡ أَنَّ بَیۡنَهَا وَبَیۡنَهُۥۤ أَمَدَۢا بَعِیدࣰاۗ وَیُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ',
    'يوم تجد كل نفس ما عملت من خير محضرا وما عملت من سوء تود لو ان بينها وبينه امدا بعيدا ويحذركم الله نفسه والله رءوف بالعباد',
    'يَوۡمَ تَجِدُ كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا عَمِلَتۡ مِنۡ خَيۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّحۡضَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َمَا عَمِلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ت</rule>َوَدُّ لَوۡ أَ<rule class=ghunnah>نّ</rule>َ بَيۡنَهَا وَبَيۡنَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَمَد<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َعِي<rule class=idgham_ghunnah>دًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َيُحَذِّرُكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ نَفۡسَهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ رَءُو<rule class=iqlab>فُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعِب<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٣٠',
    30, 3, 1, 54, 44, 21, 'false'
  );
  
  -- Ayah 31 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    324,
    'قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِی یُحۡبِبۡكُمُ ٱللَّهُ وَیَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'قل ان كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم',
    'قُلۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تُحِبُّونَ <rule class=ham_wasl>ٱ</rule>للَّهَ فَ<rule class=ham_wasl>ٱ</rule>تَّبِعُونِى يُحۡبِ<rule class=qalaqah>بۡ</rule>كُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٣١',
    31, 3, 1, 54, 45, 21, 'false'
  );
  
  -- Ayah 32 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    325,
    'قُلۡ أَطِیعُوا۟ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡا۟ فَإِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡكَـٰفِرِینَ',
    'قل اطيعوا الله والرسول فان تولوا فان الله لا يحب الكافرين',
    'قُلۡ أَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 3, 1, 54, 45, 21, 'false'
  );
  
  -- Ayah 33 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    326,
    '۞ إِنَّ ٱللَّهَ ٱصۡطَفَىٰۤ ءَادَمَ وَنُوحࣰا وَءَالَ إِبۡرَ ٰ⁠هِیمَ وَءَالَ عِمۡرَ ٰ⁠نَ عَلَى ٱلۡعَـٰلَمِینَ',
    'ان الله اصطفى ادم ونوحا وال ابراهيم وال عمران على العالمين',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>صۡطَفَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَادَمَ وَنُو<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َءَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَءَالَ عِمۡر<rule class=madda_normal>ٰ</rule>نَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٣٣',
    33, 3, 1, 54, 45, 22, 'false'
  );
  
  -- Ayah 34 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    327,
    'ذُرِّیَّةَۢ بَعۡضُهَا مِنۢ بَعۡضࣲۗ وَٱللَّهُ سَمِیعٌ عَلِیمٌ',
    'ذرية بعضها من بعض والله سميع عليم',
    'ذُرِّيَّ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>َعۡضُهَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡ<rule class=idgham_ghunnah>ضٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٣٤',
    34, 3, 1, 54, 45, 22, 'false'
  );
  
  -- Ayah 35 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    328,
    'إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَ ٰ⁠نَ رَبِّ إِنِّی نَذَرۡتُ لَكَ مَا فِی بَطۡنِی مُحَرَّرࣰا فَتَقَبَّلۡ مِنِّیۤۖ إِنَّكَ أَنتَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'اذ قالت امرات عمران رب اني نذرت لك ما في بطني محررا فتقبل مني انك انت السميع العليم',
    'إِذۡ قَالَتِ <rule class=ham_wasl>ٱ</rule>مۡرَأَتُ عِمۡر<rule class=madda_normal>ٰ</rule>نَ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى نَذَرۡتُ لَكَ مَا فِى بَ<rule class=qalaqah>طۡ</rule>نِى مُحَرَّ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َتَقَبَّلۡ مِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٣٥',
    35, 3, 1, 54, 45, 22, 'false'
  );
  
  -- Ayah 36 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    329,
    'فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّی وَضَعۡتُهَاۤ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَیۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّی سَمَّیۡتُهَا مَرۡیَمَ وَإِنِّیۤ أُعِیذُهَا بِكَ وَذُرِّیَّتَهَا مِنَ ٱلشَّیۡطَـٰنِ ٱلرَّجِیمِ',
    'فلما وضعتها قالت رب اني وضعتها انثى والله اعلم بما وضعت وليس الذكر كالانثى واني سميتها مريم واني اعيذها بك وذريتها من الشيطان الرجيم',
    'فَلَ<rule class=ghunnah>مّ</rule>َا وَضَعَتۡهَا قَالَتۡ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى وَضَعۡتُه<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نث</rule>َىٰ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَيۡسَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذَّكَرُ كَ<rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َىٰ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>ِى سَ<rule class=ghunnah>مّ</rule>َيۡتُهَا مَرۡيَمَ وَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّج<rule class=madda_permissible>ِي</rule>مِ ٣٦',
    36, 3, 1, 54, 45, 22, 'false'
  );
  
  -- Ayah 37 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    330,
    'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنࣲ وَأَنۢبَتَهَا نَبَاتًا حَسَنࣰا وَكَفَّلَهَا زَكَرِیَّاۖ كُلَّمَا دَخَلَ عَلَیۡهَا زَكَرِیَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقࣰاۖ قَالَ یَـٰمَرۡیَمُ أَنَّىٰ لَكِ هَـٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ یَرۡزُقُ مَن یَشَاۤءُ بِغَیۡرِ حِسَابٍ',
    'فتقبلها ربها بقبول حسن وانبتها نباتا حسنا وكفلها زكريا كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يا مريم انى لك هذا قالت هو من عند الله ان الله يرزق من يشاء بغير حساب',
    'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَ<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=iqlab>نۢب</rule>َتَهَا نَبَاتًا حَسَ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َكَفَّلَهَا زَكَرِيَّا‌ۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا <rule class=ham_wasl>ٱ</rule>لۡمِحۡرَابَ وَجَدَ عِ<rule class=ikhafa>ند</rule>َهَا رِزۡ<rule class=ikhafa>قًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ يَ<rule class=madda_normal>ـٰ</rule>مَرۡيَمُ أَ<rule class=ghunnah>نّ</rule>َىٰ لَكِ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۖ قَالَتۡ هُوَ مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَرۡزُقُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بِغَيۡرِ حِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٣٧',
    37, 3, 1, 54, 45, 22, 'false'
  );
  
  -- Ayah 38 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    331,
    'هُنَالِكَ دَعَا زَكَرِیَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِی مِن لَّدُنكَ ذُرِّیَّةࣰ طَیِّبَةًۖ إِنَّكَ سَمِیعُ ٱلدُّعَاۤءِ',
    'هنالك دعا زكريا ربه قال رب هب لي من لدنك ذرية طيبة انك سميع الدعاء',
    'هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُ<rule class=madda_normal>ۥ</rule>‌ۖ قَالَ رَبِّ هَ<rule class=qalaqah>بۡ</rule> لِى م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ikhafa>نك</rule>َ ذُرِّيَّ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ط</rule>َيِّبَةً‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ سَمِيعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّع<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ٣٨',
    38, 3, 1, 55, 45, 22, 'false'
  );
  
  -- Ayah 39 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    332,
    'فَنَادَتۡهُ ٱلۡمَلَـٰۤىِٕكَةُ وَهُوَ قَاۤىِٕمࣱ یُصَلِّی فِی ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ یُبَشِّرُكَ بِیَحۡیَىٰ مُصَدِّقَۢا بِكَلِمَةࣲ مِّنَ ٱللَّهِ وَسَیِّدࣰا وَحَصُورࣰا وَنَبِیࣰّا مِّنَ ٱلصَّـٰلِحِینَ',
    'فنادته الملائكة وهو قائم يصلي في المحراب ان الله يبشرك بيحيى مصدقا بكلمة من الله وسيدا وحصورا ونبيا من الصالحين',
    'فَنَادَتۡهُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ وَهُوَ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُصَلِّى فِى <rule class=ham_wasl>ٱ</rule>لۡمِحۡرَابِ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّق<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِكَلِمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَسَيِّ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َحَصُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَبِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٣٩',
    39, 3, 1, 55, 45, 22, 'false'
  );
  
  -- Ayah 40 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    333,
    'قَالَ رَبِّ أَنَّىٰ یَكُونُ لِی غُلَـٰمࣱ وَقَدۡ بَلَغَنِیَ ٱلۡكِبَرُ وَٱمۡرَأَتِی عَاقِرࣱۖ قَالَ كَذَ ٰ⁠لِكَ ٱللَّهُ یَفۡعَلُ مَا یَشَاۤءُ',
    'قال رب انى يكون لي غلام وقد بلغني الكبر وامراتي عاقر قال كذلك الله يفعل ما يشاء',
    'قَالَ رَبِّ أَ<rule class=ghunnah>نّ</rule>َىٰ يَكُونُ لِى غُلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َقَ<rule class=qalaqah>دۡ</rule> بَلَغَنِىَ <rule class=ham_wasl>ٱ</rule>لۡكِبَرُ وَ<rule class=ham_wasl>ٱ</rule>مۡرَأَتِى عَاقِ<rule class=ikhafa>رٌ‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ كَذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>للَّهُ يَفۡعَلُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ ٤٠',
    40, 3, 1, 55, 45, 22, 'false'
  );
  
  -- Ayah 41 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    334,
    'قَالَ رَبِّ ٱجۡعَل لِّیۤ ءَایَةࣰۖ قَالَ ءَایَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَةَ أَیَّامٍ إِلَّا رَمۡزࣰاۗ وَٱذۡكُر رَّبَّكَ كَثِیرࣰا وَسَبِّحۡ بِٱلۡعَشِیِّ وَٱلۡإِبۡكَـٰرِ',
    'قال رب اجعل لي اية قال ايتك الا تكلم الناس ثلاثة ايام الا رمزا واذكر ربك كثيرا وسبح بالعشي والابكار',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَل لّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ ءَايَتُكَ أَلَّا تُكَلِّمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَةَ أَيَّامٍ إِلَّا رَمۡ<rule class=idgham_ghunnah>زًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُر رَّبَّكَ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َسَبِّحۡ بِ<rule class=ham_wasl>ٱ</rule>لۡعَشِىِّ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=qalaqah>بۡ</rule>كَ<rule class=madda_permissible>ـٰ</rule>رِ ٤١',
    41, 3, 1, 55, 45, 22, 'false'
  );
  
  -- Ayah 42 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    335,
    'وَإِذۡ قَالَتِ ٱلۡمَلَـٰۤىِٕكَةُ یَـٰمَرۡیَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَاۤءِ ٱلۡعَـٰلَمِینَ',
    'واذ قالت الملائكة يا مريم ان الله اصطفاك وطهرك واصطفاك على نساء العالمين',
    'وَإِذۡ قَالَتِ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ يَ<rule class=madda_normal>ـٰ</rule>مَرۡيَمُ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>صۡطَفَ<rule class=madda_normal>ـٰ</rule>كِ وَطَهَّرَكِ وَ<rule class=ham_wasl>ٱ</rule>صۡطَفَ<rule class=madda_normal>ـٰ</rule>كِ عَلَىٰ نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 3, 1, 55, 46, 22, 'false'
  );
  
  -- Ayah 43 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    336,
    'یَـٰمَرۡیَمُ ٱقۡنُتِی لِرَبِّكِ وَٱسۡجُدِی وَٱرۡكَعِی مَعَ ٱلرَّ ٰ⁠كِعِینَ',
    'يا مريم اقنتي لربك واسجدي واركعي مع الراكعين',
    'يَ<rule class=madda_normal>ـٰ</rule>مَرۡيَمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>نُتِى لِرَبِّكِ وَ<rule class=ham_wasl>ٱ</rule>سۡجُدِى وَ<rule class=ham_wasl>ٱ</rule>رۡكَعِى مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>كِع<rule class=madda_permissible>ِي</rule>نَ ٤٣',
    43, 3, 1, 55, 46, 22, 'false'
  );
  
  -- Ayah 44 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    337,
    'ذَ ٰ⁠لِكَ مِنۡ أَنۢبَاۤءِ ٱلۡغَیۡبِ نُوحِیهِ إِلَیۡكَۚ وَمَا كُنتَ لَدَیۡهِمۡ إِذۡ یُلۡقُونَ أَقۡلَـٰمَهُمۡ أَیُّهُمۡ یَكۡفُلُ مَرۡیَمَ وَمَا كُنتَ لَدَیۡهِمۡ إِذۡ یَخۡتَصِمُونَ',
    'ذلك من انباء الغيب نوحيه اليك وما كنت لديهم اذ يلقون اقلامهم ايهم يكفل مريم وما كنت لديهم اذ يختصمون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ مِنۡ أَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ نُوحِيهِ إِلَيۡكَ‌ۚ وَمَا كُ<rule class=ikhafa>نت</rule>َ لَدَيۡهِمۡ إِذۡ يُلۡقُونَ أَ<rule class=qalaqah>قۡ</rule>لَ<rule class=madda_normal>ـٰ</rule>مَهُمۡ أَيُّهُمۡ يَكۡفُلُ مَرۡيَمَ وَمَا كُ<rule class=ikhafa>نت</rule>َ لَدَيۡهِمۡ إِذۡ يَخۡتَصِم<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 3, 1, 55, 46, 22, 'false'
  );
  
  -- Ayah 45 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    338,
    'إِذۡ قَالَتِ ٱلۡمَلَـٰۤىِٕكَةُ یَـٰمَرۡیَمُ إِنَّ ٱللَّهَ یُبَشِّرُكِ بِكَلِمَةࣲ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِیحُ عِیسَى ٱبۡنُ مَرۡیَمَ وَجِیهࣰا فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَمِنَ ٱلۡمُقَرَّبِینَ',
    'اذ قالت الملائكة يا مريم ان الله يبشرك بكلمة منه اسمه المسيح عيسى ابن مريم وجيها في الدنيا والاخرة ومن المقربين',
    'إِذۡ قَالَتِ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ يَ<rule class=madda_normal>ـٰ</rule>مَرۡيَمُ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُبَشِّرُكِ بِكَلِمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ <rule class=ham_wasl>ٱ</rule>سۡمُهُ <rule class=ham_wasl>ٱ</rule>لۡمَسِيحُ عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ وَجِي<rule class=ikhafa>هًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡمُقَرَّب<rule class=madda_permissible>ِي</rule>نَ ٤٥',
    45, 3, 1, 55, 46, 22, 'false'
  );
  
  -- Ayah 46 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    339,
    'وَیُكَلِّمُ ٱلنَّاسَ فِی ٱلۡمَهۡدِ وَكَهۡلࣰا وَمِنَ ٱلصَّـٰلِحِینَ',
    'ويكلم الناس في المهد وكهلا ومن الصالحين',
    'وَيُكَلِّمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ فِى <rule class=ham_wasl>ٱ</rule>لۡمَهۡدِ وَكَهۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 3, 1, 56, 46, 22, 'false'
  );
  
  -- Ayah 47 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    340,
    'قَالَتۡ رَبِّ أَنَّىٰ یَكُونُ لِی وَلَدࣱ وَلَمۡ یَمۡسَسۡنِی بَشَرࣱۖ قَالَ كَذَ ٰ⁠لِكِ ٱللَّهُ یَخۡلُقُ مَا یَشَاۤءُۚ إِذَا قَضَىٰۤ أَمۡرࣰا فَإِنَّمَا یَقُولُ لَهُۥ كُن فَیَكُونُ',
    'قالت رب انى يكون لي ولد ولم يمسسني بشر قال كذلك الله يخلق ما يشاء اذا قضى امرا فانما يقول له كن فيكون',
    'قَالَتۡ رَبِّ أَ<rule class=ghunnah>نّ</rule>َىٰ يَكُونُ لِى وَلَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ يَمۡسَسۡنِى بَشَ<rule class=ikhafa>رٌ‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ كَذ<rule class=madda_normal>ٰ</rule>لِكِ <rule class=ham_wasl>ٱ</rule>للَّهُ يَخۡلُقُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ إِذَا قَضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َمَا يَقُولُ لَهُ<rule class=madda_normal>ۥ</rule> كُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َيَك<rule class=madda_permissible>ُو</rule>نُ ٤٧',
    47, 3, 1, 56, 46, 22, 'false'
  );
  
  -- Ayah 48 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    341,
    'وَیُعَلِّمُهُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَ',
    'ويعلمه الكتاب والحكمة والتوراة والانجيل',
    'وَيُعَلِّمُهُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule><rule class=madda_permissible>ِي</rule>لَ ٤٨',
    48, 3, 1, 56, 46, 22, 'false'
  );
  
  -- Ayah 49 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    342,
    'وَرَسُولًا إِلَىٰ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ أَنِّی قَدۡ جِئۡتُكُم بِـَٔایَةࣲ مِّن رَّبِّكُمۡ أَنِّیۤ أَخۡلُقُ لَكُم مِّنَ ٱلطِّینِ كَهَیۡـَٔةِ ٱلطَّیۡرِ فَأَنفُخُ فِیهِ فَیَكُونُ طَیۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡیِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِی بُیُوتِكُمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِینَ',
    'ورسولا الى بني اسرائيل اني قد جئتكم باية من ربكم اني اخلق لكم من الطين كهيئة الطير فانفخ فيه فيكون طيرا باذن الله وابرئ الاكمه والابرص واحيي الموتى باذن الله وانبئكم بما تاكلون وما تدخرون في بيوتكم ان في ذلك لاية لكم ان كنتم مؤمنين',
    'وَرَسُولاً إِلَىٰ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ أَ<rule class=ghunnah>نّ</rule>ِى قَ<rule class=qalaqah>دۡ</rule> جِئۡتُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۖ أَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخۡلُقُ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طِّينِ كَهَيۡــَٔةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرِ فَأَ<rule class=ikhafa>نف</rule>ُخُ فِيهِ فَيَكُونُ طَيۡر<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَأُ<rule class=qalaqah>بۡ</rule>رِئُ <rule class=ham_wasl>ٱ</rule>لۡأَكۡمَهَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>رَصَ وَأُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَأُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٤٩',
    49, 3, 1, 56, 46, 22, 'false'
  );
  
  -- Ayah 50 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    343,
    'وَمُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِی حُرِّمَ عَلَیۡكُمۡۚ وَجِئۡتُكُم بِـَٔایَةࣲ مِّن رَّبِّكُمۡ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ',
    'ومصدقا لما بين يدي من التوراة ولاحل لكم بعض الذي حرم عليكم وجئتكم باية من ربكم فاتقوا الله واطيعون',
    'وَمُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَىَّ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةِ وَلِأُحِلَّ لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضَ <rule class=ham_wasl>ٱ</rule>لَّذِى حُرِّمَ عَلَيۡكُمۡ‌ۚ وَجِئۡتُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطِيع<rule class=madda_permissible>ُو</rule>نِ ٥٠',
    50, 3, 1, 56, 46, 22, 'false'
  );
  
  -- Ayah 51 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    344,
    'إِنَّ ٱللَّهَ رَبِّی وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَـٰذَا صِرَ ٰ⁠طࣱ مُّسۡتَقِیمࣱ',
    'ان الله ربي وربكم فاعبدوه هذا صراط مستقيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ رَبِّى وَرَبُّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡبُدُوهُ‌ۗ هَ<rule class=madda_normal>ـٰ</rule>ذَا صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٌ ٥١',
    51, 3, 1, 56, 46, 22, 'false'
  );
  
  -- Ayah 52 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    345,
    '۞ فَلَمَّاۤ أَحَسَّ عِیسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِیۤ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِیُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ',
    'فلما احس عيسى منهم الكفر قال من انصاري الى الله قال الحواريون نحن انصار الله امنا بالله واشهد بانا مسلمون',
    '۞فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَحَسَّ عِيسَىٰ مِنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡكُفۡرَ قَالَ مَنۡ أَ<rule class=ikhafa>نص</rule>َار<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ قَالَ <rule class=ham_wasl>ٱ</rule>لۡحَوَارِيُّونَ نَحۡنُ أَ<rule class=ikhafa>نص</rule>َارُ <rule class=ham_wasl>ٱ</rule>للَّهِ ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>شۡهَ<rule class=qalaqah>دۡ</rule> بِأَ<rule class=ghunnah>نّ</rule>َا مُسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 3, 1, 56, 46, 23, 'false'
  );
  
  -- Ayah 53 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    346,
    'رَبَّنَاۤ ءَامَنَّا بِمَاۤ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِینَ',
    'ربنا امنا بما انزلت واتبعنا الرسول فاكتبنا مع الشاهدين',
    'رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡتَ وَ<rule class=ham_wasl>ٱ</rule>تَّبَعۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ فَ<rule class=ham_wasl>ٱ</rule>كۡتُ<rule class=qalaqah>بۡ</rule>نَا مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>هِد<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 3, 1, 57, 46, 23, 'false'
  );
  
  -- Ayah 54 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    347,
    'وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَیۡرُ ٱلۡمَـٰكِرِینَ',
    'ومكروا ومكر الله والله خير الماكرين',
    'وَمَكَرُو<rule class=slnt>اۡ</rule> وَمَكَرَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ٥٤',
    54, 3, 1, 57, 46, 23, 'false'
  );
  
  -- Ayah 55 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    348,
    'إِذۡ قَالَ ٱللَّهُ یَـٰعِیسَىٰۤ إِنِّی مُتَوَفِّیكَ وَرَافِعُكَ إِلَیَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِینَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِینَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِینَ كَفَرُوۤا۟ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِۖ ثُمَّ إِلَیَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَیۡنَكُمۡ فِیمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ',
    'اذ قال الله يا عيسى اني متوفيك ورافعك الي ومطهرك من الذين كفروا وجاعل الذين اتبعوك فوق الذين كفروا الى يوم القيامة ثم الي مرجعكم فاحكم بينكم فيما كنتم فيه تختلفون',
    'إِذۡ قَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=madda_normal>ـٰ</rule>عِيسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>ِى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَجَاعِلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّبَعُوكَ فَوۡقَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ إِلَىَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَيۡنَكُمۡ فِيمَا كُ<rule class=ikhafa>نت</rule>ُمۡ فِيهِ تَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 3, 1, 57, 47, 23, 'false'
  );
  
  -- Ayah 56 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    349,
    'فَأَمَّا ٱلَّذِینَ كَفَرُوا۟ فَأُعَذِّبُهُمۡ عَذَابࣰا شَدِیدࣰا فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِینَ',
    'فاما الذين كفروا فاعذبهم عذابا شديدا في الدنيا والاخرة وما لهم من ناصرين',
    'فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فَأُعَذِّبُهُمۡ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَمَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ٥٦',
    56, 3, 1, 57, 47, 23, 'false'
  );
  
  -- Ayah 57 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    350,
    'وَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَیُوَفِّیهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا یُحِبُّ ٱلظَّـٰلِمِینَ',
    'واما الذين امنوا وعملوا الصالحات فيوفيهم اجورهم والله لا يحب الظالمين',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥٧',
    57, 3, 1, 57, 47, 23, 'false'
  );
  
  -- Ayah 58 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    351,
    'ذَ ٰ⁠لِكَ نَتۡلُوهُ عَلَیۡكَ مِنَ ٱلۡـَٔایَـٰتِ وَٱلذِّكۡرِ ٱلۡحَكِیمِ',
    'ذلك نتلوه عليك من الايات والذكر الحكيم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ نَتۡلُوهُ عَلَيۡكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ٥٨',
    58, 3, 1, 57, 47, 23, 'false'
  );
  
  -- Ayah 59 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    352,
    'إِنَّ مَثَلَ عِیسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابࣲ ثُمَّ قَالَ لَهُۥ كُن فَیَكُونُ',
    'ان مثل عيسى عند الله كمثل ادم خلقه من تراب ثم قال له كن فيكون',
    'إِ<rule class=ghunnah>نّ</rule>َ مَثَلَ عِيسَىٰ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ كَمَثَلِ ءَادَمَ‌ۖ خَلَقَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ قَالَ لَهُ<rule class=madda_normal>ۥ</rule> كُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َيَك<rule class=madda_permissible>ُو</rule>نُ ٥٩',
    59, 3, 1, 57, 47, 23, 'false'
  );
  
  -- Ayah 60 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    353,
    'ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِینَ',
    'الحق من ربك فلا تكن من الممترين',
    'ٱلۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ فَلَا تَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُمۡتَر<rule class=madda_permissible>ِي</rule>نَ ٦٠',
    60, 3, 1, 57, 47, 23, 'false'
  );
  
  -- Ayah 61 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    354,
    'فَمَنۡ حَاۤجَّكَ فِیهِ مِنۢ بَعۡدِ مَا جَاۤءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡا۟ نَدۡعُ أَبۡنَاۤءَنَا وَأَبۡنَاۤءَكُمۡ وَنِسَاۤءَنَا وَنِسَاۤءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَـٰذِبِینَ',
    'فمن حاجك فيه من بعد ما جاءك من العلم فقل تعالوا ندع ابناءنا وابناءكم ونساءنا ونساءكم وانفسنا وانفسكم ثم نبتهل فنجعل لعنت الله على الكاذبين',
    'فَمَنۡ ح<rule class=madda_necessary>َا</rule>ٓجَّكَ فِيهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ فَقُلۡ تَعَالَوۡ<rule class=slnt>اۡ</rule> نَ<rule class=qalaqah>دۡ</rule>عُ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا وَأَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ وَنِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا وَنِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ وَأَ<rule class=ikhafa>نف</rule>ُسَنَا وَأَ<rule class=ikhafa>نف</rule>ُسَكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ نَ<rule class=qalaqah>بۡ</rule>تَهِلۡ فَنَ<rule class=qalaqah>جۡ</rule>عَل لَّعۡنَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٦١',
    61, 3, 1, 57, 47, 23, 'false'
  );
  
  -- Ayah 62 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    355,
    'إِنَّ هَـٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَـٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'ان هذا لهو القصص الحق وما من اله الا الله وان الله لهو العزيز الحكيم',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡقَصَصُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۚ وَمَا مِنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٦٢',
    62, 3, 1, 58, 47, 23, 'false'
  );
  
  -- Ayah 63 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    356,
    'فَإِن تَوَلَّوۡا۟ فَإِنَّ ٱللَّهَ عَلِیمُۢ بِٱلۡمُفۡسِدِینَ',
    'فان تولوا فان الله عليم بالمفسدين',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٦٣',
    63, 3, 1, 58, 47, 23, 'false'
  );
  
  -- Ayah 64 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    357,
    'قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ تَعَالَوۡا۟ إِلَىٰ كَلِمَةࣲ سَوَاۤءِۭ بَیۡنَنَا وَبَیۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَیۡـࣰٔا وَلَا یَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابࣰا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡا۟ فَقُولُوا۟ ٱشۡهَدُوا۟ بِأَنَّا مُسۡلِمُونَ',
    'قل يا اهل الكتاب تعالوا الى كلمة سواء بيننا وبينكم الا نعبد الا الله ولا نشرك به شيئا ولا يتخذ بعضنا بعضا اربابا من دون الله فان تولوا فقولوا اشهدوا بانا مسلمون',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ تَعَالَوۡ<rule class=slnt>اۡ</rule> إِلَىٰ كَلِمَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>س</rule>َو<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءِۭ</rule> <rule class=iqlab>ب</rule>َيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَ وَلَا نُشۡرِكَ بِه<rule class=madda_normal>ِۦ</rule> شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَقُولُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>شۡهَدُو<rule class=slnt>اۡ</rule> بِأَ<rule class=ghunnah>نّ</rule>َا مُسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 3, 1, 58, 48, 23, 'false'
  );
  
  -- Ayah 65 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    358,
    'یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تُحَاۤجُّونَ فِیۤ إِبۡرَ ٰ⁠هِیمَ وَمَاۤ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِیلُ إِلَّا مِنۢ بَعۡدِهِۦۤۚ أَفَلَا تَعۡقِلُونَ',
    'يا اهل الكتاب لم تحاجون في ابراهيم وما انزلت التوراة والانجيل الا من بعده افلا تعقلون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لِمَ تُح<rule class=madda_necessary>َا</rule>ٓجُّونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةُ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلُ إِلَّا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 3, 1, 58, 48, 23, 'false'
  );
  
  -- Ayah 66 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    359,
    'هَـٰۤأَنتُمۡ هَـٰۤؤُلَاۤءِ حَـٰجَجۡتُمۡ فِیمَا لَكُم بِهِۦ عِلۡمࣱ فَلِمَ تُحَاۤجُّونَ فِیمَا لَیۡسَ لَكُم بِهِۦ عِلۡمࣱۚ وَٱللَّهُ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ',
    'ها انتم هؤلاء حاججتم فيما لكم به علم فلم تحاجون فيما ليس لكم به علم والله يعلم وانتم لا تعلمون',
    'هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَ<rule class=ikhafa>نت</rule>ُمۡ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ حَ<rule class=madda_normal>ـٰ</rule>جَ<rule class=qalaqah>جۡ</rule>تُمۡ فِيمَا لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> عِلۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ف</rule>َلِمَ تُح<rule class=madda_necessary>َا</rule>ٓجُّونَ فِيمَا لَيۡسَ لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> عِلۡ<rule class=idgham_ghunnah>مٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 3, 1, 58, 48, 23, 'false'
  );
  
  -- Ayah 67 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    360,
    'مَا كَانَ إِبۡرَ ٰ⁠هِیمُ یَهُودِیࣰّا وَلَا نَصۡرَانِیࣰّا وَلَـٰكِن كَانَ حَنِیفࣰا مُّسۡلِمࣰا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ',
    'ما كان ابراهيم يهوديا ولا نصرانيا ولكن كان حنيفا مسلما وما كان من المشركين',
    'مَا كَانَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمُ يَهُودِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصۡرَانِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ حَنِي<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡلِ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٦٧',
    67, 3, 1, 58, 48, 23, 'false'
  );
  
  -- Ayah 68 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    361,
    'إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَ ٰ⁠هِیمَ لَلَّذِینَ ٱتَّبَعُوهُ وَهَـٰذَا ٱلنَّبِیُّ وَٱلَّذِینَ ءَامَنُوا۟ۗ وَٱللَّهُ وَلِیُّ ٱلۡمُؤۡمِنِینَ',
    'ان اولى الناس بابراهيم للذين اتبعوه وهذا النبي والذين امنوا والله ولي المؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َ أَوۡلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِإِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ لَلَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّبَعُوهُ وَهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ‌ۗ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ وَلِىُّ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٦٨',
    68, 3, 1, 58, 48, 23, 'false'
  );
  
  -- Ayah 69 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    362,
    'وَدَّت طَّاۤىِٕفَةࣱ مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَوۡ یُضِلُّونَكُمۡ وَمَا یُضِلُّونَ إِلَّاۤ أَنفُسَهُمۡ وَمَا یَشۡعُرُونَ',
    'ودت طائفة من اهل الكتاب لو يضلونكم وما يضلون الا انفسهم وما يشعرون',
    'وَدَّ<rule class=idgham_mutajanisayn>ت</rule> طّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَوۡ يُضِلُّونَكُمۡ وَمَا يُضِلُّونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَمَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 3, 1, 58, 48, 23, 'false'
  );
  
  -- Ayah 70 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    363,
    'یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ',
    'يا اهل الكتاب لم تكفرون بايات الله وانتم تشهدون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لِمَ تَكۡفُرُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَشۡهَد<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 3, 1, 58, 48, 23, 'false'
  );
  
  -- Ayah 71 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    364,
    'یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَـٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ',
    'يا اهل الكتاب لم تلبسون الحق بالباطل وتكتمون الحق وانتم تعلمون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لِمَ تَلۡبِسُونَ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ بِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ وَتَكۡتُمُونَ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 3, 1, 59, 48, 23, 'false'
  );
  
  -- Ayah 72 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    365,
    'وَقَالَت طَّاۤىِٕفَةࣱ مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ ءَامِنُوا۟ بِٱلَّذِیۤ أُنزِلَ عَلَى ٱلَّذِینَ ءَامَنُوا۟ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوۤا۟ ءَاخِرَهُۥ لَعَلَّهُمۡ یَرۡجِعُونَ',
    'وقالت طائفة من اهل الكتاب امنوا بالذي انزل على الذين امنوا وجه النهار واكفروا اخره لعلهم يرجعون',
    'وَقَالَ<rule class=idgham_mutajanisayn>ت</rule> طّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ ءَامِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=qalaqah>جۡ</rule>هَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَ<rule class=ham_wasl>ٱ</rule>كۡفُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَاخِرَهُ<rule class=madda_normal>ۥ</rule> لَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 3, 1, 59, 49, 23, 'false'
  );
  
  -- Ayah 73 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    366,
    'وَلَا تُؤۡمِنُوۤا۟ إِلَّا لِمَن تَبِعَ دِینَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن یُؤۡتَىٰۤ أَحَدࣱ مِّثۡلَ مَاۤ أُوتِیتُمۡ أَوۡ یُحَاۤجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِیَدِ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۗ وَٱللَّهُ وَ ٰ⁠سِعٌ عَلِیمࣱ',
    'ولا تؤمنوا الا لمن تبع دينكم قل ان الهدى هدى الله ان يؤتى احد مثل ما اوتيتم او يحاجوكم عند ربكم قل ان الفضل بيد الله يؤتيه من يشاء والله واسع عليم',
    'وَلَا تُؤۡمِن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا لِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبِعَ دِينَكُمۡ قُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ هُدَى <rule class=ham_wasl>ٱ</rule>للَّهِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡتَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَحَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلَ م<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِيتُمۡ أَوۡ يُح<rule class=madda_necessary>َا</rule>ٓجُّوكُمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّكُمۡ‌ۗ قُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡفَضۡلَ بِيَدِ <rule class=ham_wasl>ٱ</rule>للَّهِ يُؤۡتِيهِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ و<rule class=madda_normal>ٰ</rule>سِعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٧٣',
    73, 3, 1, 59, 49, 23, 'false'
  );
  
  -- Ayah 74 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    367,
    'یَخۡتَصُّ بِرَحۡمَتِهِۦ مَن یَشَاۤءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ',
    'يختص برحمته من يشاء والله ذو الفضل العظيم',
    'يَخۡتَصُّ بِرَحۡمَتِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ ذُو <rule class=ham_wasl>ٱ</rule>لۡفَضۡلِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٧٤',
    74, 3, 1, 59, 49, 23, 'false'
  );
  
  -- Ayah 75 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    368,
    '۞ وَمِنۡ أَهۡلِ ٱلۡكِتَـٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارࣲ یُؤَدِّهِۦۤ إِلَیۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِینَارࣲ لَّا یُؤَدِّهِۦۤ إِلَیۡكَ إِلَّا مَا دُمۡتَ عَلَیۡهِ قَاۤىِٕمࣰاۗ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَالُوا۟ لَیۡسَ عَلَیۡنَا فِی ٱلۡأُمِّیِّـۧنَ سَبِیلࣱ وَیَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ یَعۡلَمُونَ',
    'ومن اهل الكتاب من ان تامنه بقنطار يؤده اليك ومنهم من ان تامنه بدينار لا يؤده اليك الا ما دمت عليه قائما ذلك بانهم قالوا ليس علينا في الاميين سبيل ويقولون على الله الكذب وهم يعلمون',
    '۞وَمِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مَنۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡمَنۡهُ بِقِ<rule class=ikhafa>نط</rule>َا<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤَدِّه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَيۡكَ وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡمَنۡهُ بِدِينَا<rule class=idgham_wo_ghunnah>رٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤَدِّه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَيۡكَ إِلَّا مَا دُمۡتَ عَلَيۡهِ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=ikhafa>مًا‌ۗ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَالُو<rule class=slnt>اۡ</rule> لَيۡسَ عَلَيۡنَا فِى <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ghunnah>مّ</rule>ِيِّـ<rule class=madda_normal>ـۧ</rule>نَ سَبِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>و</rule>َيَقُولُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ وَهُمۡ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 3, 1, 59, 49, 24, 'false'
  );
  
  -- Ayah 76 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    369,
    'بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُتَّقِینَ',
    'بلى من اوفى بعهده واتقى فان الله يحب المتقين',
    'بَلَىٰ مَنۡ أَوۡفَىٰ بِعَهۡدِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّقَىٰ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٧٦',
    76, 3, 1, 59, 49, 24, 'false'
  );
  
  -- Ayah 77 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    370,
    'إِنَّ ٱلَّذِینَ یَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَیۡمَـٰنِهِمۡ ثَمَنࣰا قَلِیلًا أُو۟لَـٰۤىِٕكَ لَا خَلَـٰقَ لَهُمۡ فِی ٱلۡـَٔاخِرَةِ وَلَا یُكَلِّمُهُمُ ٱللَّهُ وَلَا یَنظُرُ إِلَیۡهِمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ وَلَا یُزَكِّیهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ',
    'ان الذين يشترون بعهد الله وايمانهم ثمنا قليلا اولئك لا خلاق لهم في الاخرة ولا يكلمهم الله ولا ينظر اليهم يوم القيامة ولا يزكيهم ولهم عذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَشۡتَرُونَ بِعَهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَأَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيلاً أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَا خَلَ<rule class=madda_normal>ـٰ</rule>قَ لَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَلَا يُكَلِّمُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَا يَ<rule class=ikhafa>نظ</rule>ُرُ إِلَيۡهِمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ وَلَا يُزَكِّيهِمۡ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٧٧',
    77, 3, 1, 59, 49, 24, 'false'
  );
  
  -- Ayah 78 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    371,
    'وَإِنَّ مِنۡهُمۡ لَفَرِیقࣰا یَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَـٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَـٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَـٰبِ وَیَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِ وَیَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ یَعۡلَمُونَ',
    'وان منهم لفريقا يلوون السنتهم بالكتاب لتحسبوه من الكتاب وما هو من الكتاب ويقولون هو من عند الله وما هو من عند الله ويقولون على الله الكذب وهم يعلمون',
    'وَإِ<rule class=ghunnah>نّ</rule>َ مِنۡهُمۡ لَفَرِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>ي</rule>َلۡوُ<rule class=madda_normal>ۥ</rule>نَ أَلۡسِنَتَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لِتَحۡسَبُوهُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَمَا هُوَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَيَقُولُونَ هُوَ مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَا هُوَ مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَقُولُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ وَهُمۡ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 3, 1, 60, 49, 24, 'false'
  );
  
  -- Ayah 79 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    372,
    'مَا كَانَ لِبَشَرٍ أَن یُؤۡتِیَهُ ٱللَّهُ ٱلۡكِتَـٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ یَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادࣰا لِّی مِن دُونِ ٱللَّهِ وَلَـٰكِن كُونُوا۟ رَبَّـٰنِیِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَـٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ',
    'ما كان لبشر ان يؤتيه الله الكتاب والحكم والنبوة ثم يقول للناس كونوا عبادا لي من دون الله ولكن كونوا ربانيين بما كنتم تعلمون الكتاب وبما كنتم تدرسون',
    'مَا كَانَ لِبَشَرٍ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡتِيَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحُكۡمَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُبُوَّةَ ثُ<rule class=ghunnah>مّ</rule>َ يَقُولَ لِل<rule class=ghunnah>نّ</rule>َاسِ كُونُو<rule class=slnt>اۡ</rule> عِبَا<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُونُو<rule class=slnt>اۡ</rule> رَبَّ<rule class=madda_normal>ـٰ</rule>نِيِّـ<rule class=madda_normal>ـۧ</rule>نَ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تُعَلِّمُونَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَبِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَ<rule class=qalaqah>دۡ</rule>رُس<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 3, 1, 60, 49, 24, 'false'
  );
  
  -- Ayah 80 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    373,
    'وَلَا یَأۡمُرَكُمۡ أَن تَتَّخِذُوا۟ ٱلۡمَلَـٰۤىِٕكَةَ وَٱلنَّبِیِّـۧنَ أَرۡبَابًاۗ أَیَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ',
    'ولا يامركم ان تتخذوا الملائكة والنبيين اربابا ايامركم بالكفر بعد اذ انتم مسلمون',
    'وَلَا يَأۡمُرَكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَّخِذُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ أَرۡبَابًا‌ۗ أَيَأۡمُرُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ بَعۡدَ إِذۡ أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 3, 1, 60, 49, 24, 'false'
  );
  
  -- Ayah 81 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    374,
    'وَإِذۡ أَخَذَ ٱللَّهُ مِیثَـٰقَ ٱلنَّبِیِّـۧنَ لَمَاۤ ءَاتَیۡتُكُم مِّن كِتَـٰبࣲ وَحِكۡمَةࣲ ثُمَّ جَاۤءَكُمۡ رَسُولࣱ مُّصَدِّقࣱ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَ ٰ⁠لِكُمۡ إِصۡرِیۖ قَالُوۤا۟ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّـٰهِدِینَ',
    'واذ اخذ الله ميثاق النبيين لما اتيتكم من كتاب وحكمة ثم جاءكم رسول مصدق لما معكم لتؤمنن به ولتنصرنه قال ااقررتم واخذتم على ذلكم اصري قالوا اقررنا قال فاشهدوا وانا معكم من الشاهدين',
    'وَإِذۡ أَخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِيثَ<rule class=madda_normal>ـٰ</rule>قَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ لَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡتُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َحِكۡمَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّصَدِّ<rule class=idgham_wo_ghunnah>قٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا مَعَكُمۡ لَتُؤۡمِنُ<rule class=ghunnah>نّ</rule>َ بِه<rule class=madda_normal>ِۦ</rule> وَلَتَ<rule class=ikhafa>نص</rule>ُرُ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule>‌ۚ قَالَ ءَأَ<rule class=qalaqah>قۡ</rule>رَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ إِصۡرِى‌ۖ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>قۡ</rule>رَرۡنَا‌ۚ قَالَ فَ<rule class=ham_wasl>ٱ</rule>شۡهَدُو<rule class=slnt>اۡ</rule> وَأَنَاۡ مَعَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>هِد<rule class=madda_permissible>ِي</rule>نَ ٨١',
    81, 3, 1, 60, 50, 24, 'false'
  );
  
  -- Ayah 82 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    375,
    'فَمَن تَوَلَّىٰ بَعۡدَ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ',
    'فمن تولى بعد ذلك فاولئك هم الفاسقون',
    'فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّىٰ بَعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 3, 1, 60, 50, 24, 'false'
  );
  
  -- Ayah 83 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    376,
    'أَفَغَیۡرَ دِینِ ٱللَّهِ یَبۡغُونَ وَلَهُۥۤ أَسۡلَمَ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ طَوۡعࣰا وَكَرۡهࣰا وَإِلَیۡهِ یُرۡجَعُونَ',
    'افغير دين الله يبغون وله اسلم من في السماوات والارض طوعا وكرها واليه يرجعون',
    'أَفَغَيۡرَ دِينِ <rule class=ham_wasl>ٱ</rule>للَّهِ يَ<rule class=qalaqah>بۡ</rule>غُونَ وَلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَسۡلَمَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ طَوۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َكَرۡ<rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule>َإِلَيۡهِ يُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٨٣',
    83, 3, 1, 60, 50, 24, 'false'
  );
  
  -- Ayah 84 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    377,
    'قُلۡ ءَامَنَّا بِٱللَّهِ وَمَاۤ أُنزِلَ عَلَیۡنَا وَمَاۤ أُنزِلَ عَلَىٰۤ إِبۡرَ ٰ⁠هِیمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَاۤ أُوتِیَ مُوسَىٰ وَعِیسَىٰ وَٱلنَّبِیُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَیۡنَ أَحَدࣲ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ',
    'قل امنا بالله وما انزل علينا وما انزل على ابراهيم واسماعيل واسحاق ويعقوب والاسباط وما اوتي موسى وعيسى والنبيون من ربهم لا نفرق بين احد منهم ونحن له مسلمون',
    'قُلۡ ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡنَا وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَسۡبَاطِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيُّونَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ لَا نُفَرِّقُ بَيۡنَ أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ وَنَحۡنُ لَهُ<rule class=madda_normal>ۥ</rule> مُسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 3, 1, 61, 50, 24, 'false'
  );
  
  -- Ayah 85 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    378,
    'وَمَن یَبۡتَغِ غَیۡرَ ٱلۡإِسۡلَـٰمِ دِینࣰا فَلَن یُقۡبَلَ مِنۡهُ وَهُوَ فِی ٱلۡـَٔاخِرَةِ مِنَ ٱلۡخَـٰسِرِینَ',
    'ومن يبتغ غير الاسلام دينا فلن يقبل منه وهو في الاخرة من الخاسرين',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>تَغِ غَيۡرَ <rule class=ham_wasl>ٱ</rule>لۡإِسۡلَ<rule class=madda_normal>ـٰ</rule>مِ دِي<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>قۡ</rule>بَلَ مِنۡهُ وَهُوَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 3, 1, 61, 50, 24, 'false'
  );
  
  -- Ayah 86 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    379,
    'كَیۡفَ یَهۡدِی ٱللَّهُ قَوۡمࣰا كَفَرُوا۟ بَعۡدَ إِیمَـٰنِهِمۡ وَشَهِدُوۤا۟ أَنَّ ٱلرَّسُولَ حَقࣱّ وَجَاۤءَهُمُ ٱلۡبَیِّنَـٰتُۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'كيف يهدي الله قوما كفروا بعد ايمانهم وشهدوا ان الرسول حق وجاءهم البينات والله لا يهدي القوم الظالمين',
    'كَيۡفَ يَهۡدِى <rule class=ham_wasl>ٱ</rule>للَّهُ قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ك</rule>َفَرُو<rule class=slnt>اۡ</rule> بَعۡدَ إِيمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ وَشَهِد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ حَ<rule class=idgham_ghunnah>قٌّ</rule> <rule class=idgham_ghunnah>و</rule>َج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 3, 1, 61, 50, 24, 'false'
  );
  
  -- Ayah 87 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    380,
    'أُو۟لَـٰۤىِٕكَ جَزَاۤؤُهُمۡ أَنَّ عَلَیۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَـٰۤىِٕكَةِ وَٱلنَّاسِ أَجۡمَعِینَ',
    'اولئك جزاؤهم ان عليهم لعنة الله والملائكة والناس اجمعين',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُمۡ أَ<rule class=ghunnah>نّ</rule>َ عَلَيۡهِمۡ لَعۡنَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 3, 1, 61, 50, 24, 'false'
  );
  
  -- Ayah 88 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    381,
    'خَـٰلِدِینَ فِیهَا لَا یُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ یُنظَرُونَ',
    'خالدين فيها لا يخفف عنهم العذاب ولا هم ينظرون',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا لَا يُخَفَّفُ عَنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ وَلَا هُمۡ يُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 3, 1, 61, 50, 24, 'false'
  );
  
  -- Ayah 89 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    382,
    'إِلَّا ٱلَّذِینَ تَابُوا۟ مِنۢ بَعۡدِ ذَ ٰ⁠لِكَ وَأَصۡلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ',
    'الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَابُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ وَأَصۡلَحُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٨٩',
    89, 3, 1, 61, 50, 24, 'false'
  );
  
  -- Ayah 90 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    383,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ بَعۡدَ إِیمَـٰنِهِمۡ ثُمَّ ٱزۡدَادُوا۟ كُفۡرࣰا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلضَّاۤلُّونَ',
    'ان الذين كفروا بعد ايمانهم ثم ازدادوا كفرا لن تقبل توبتهم واولئك هم الضالون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بَعۡدَ إِيمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>زۡدَادُو<rule class=slnt>اۡ</rule> كُفۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>قۡ</rule>بَلَ تَوۡبَتُهُمۡ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضّ<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ُو</rule>نَ ٩٠',
    90, 3, 1, 61, 50, 24, 'false'
  );
  
  -- Ayah 91 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    384,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمۡ كُفَّارࣱ فَلَن یُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبࣰا وَلَوِ ٱفۡتَدَىٰ بِهِۦۤۗ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ أَلِیمࣱ وَمَا لَهُم مِّن نَّـٰصِرِینَ',
    'ان الذين كفروا وماتوا وهم كفار فلن يقبل من احدهم ملء الارض ذهبا ولو افتدى به اولئك لهم عذاب اليم وما لهم من ناصرين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَمَاتُو<rule class=slnt>اۡ</rule> وَهُمۡ كُفَّا<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>قۡ</rule>بَلَ مِنۡ أَحَدِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّلۡءُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ ذَهَ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َلَوِ <rule class=ham_wasl>ٱ</rule>فۡتَدَىٰ بِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عَذَابٌ أَلِي<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 3, 1, 61, 50, 24, 'false'
  );
  
  -- Ayah 92 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    385,
    'لَن تَنَالُوا۟ ٱلۡبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُوا۟ مِن شَیۡءࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِیمࣱ',
    'لن تنالوا البر حتى تنفقوا مما تحبون وما تنفقوا من شيء فان الله به عليم',
    'لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َنَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡبِرَّ حَتَّىٰ تُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا تُحِبُّونَ‌ۚ وَمَا تُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِه<rule class=madda_normal>ِۦ</rule> عَل<rule class=madda_permissible>ِي</rule>مٌ ٩٢',
    92, 3, 1, 62, 51, 24, 'false'
  );
  
  -- Ayah 93 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    386,
    '۞ كُلُّ ٱلطَّعَامِ كَانَ حِلࣰّا لِّبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ إِلَّا مَا حَرَّمَ إِسۡرَ ٰ⁠ۤءِیلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُوا۟ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَاۤ إِن كُنتُمۡ صَـٰدِقِینَ',
    'كل الطعام كان حلا لبني اسرائيل الا ما حرم اسرائيل على نفسه من قبل ان تنزل التوراة قل فاتوا بالتوراة فاتلوها ان كنتم صادقين',
    '۞كُلُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّعَامِ كَانَ حِل<rule class=idgham_wo_ghunnah>اًّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّبَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ إِلَّا مَا حَرَّمَ إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلُ عَلَىٰ نَفۡسِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُنَزَّلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةُ‌ۗ قُلۡ فَأۡتُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةِ فَ<rule class=ham_wasl>ٱ</rule>تۡلُوه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٩٣',
    93, 4, 1, 62, 51, 25, 'false'
  );
  
  -- Ayah 94 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    387,
    'فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ',
    'فمن افترى على الله الكذب من بعد ذلك فاولئك هم الظالمون',
    'فَمَنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٩٤',
    94, 4, 1, 62, 51, 25, 'false'
  );
  
  -- Ayah 95 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    388,
    'قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُوا۟ مِلَّةَ إِبۡرَ ٰ⁠هِیمَ حَنِیفࣰاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ',
    'قل صدق الله فاتبعوا ملة ابراهيم حنيفا وما كان من المشركين',
    'قُلۡ صَدَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ فَ<rule class=ham_wasl>ٱ</rule>تَّبِعُو<rule class=slnt>اۡ</rule> مِلَّةَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ حَنِي<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٩٥',
    95, 4, 1, 62, 51, 25, 'false'
  );
  
  -- Ayah 96 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    389,
    'إِنَّ أَوَّلَ بَیۡتࣲ وُضِعَ لِلنَّاسِ لَلَّذِی بِبَكَّةَ مُبَارَكࣰا وَهُدࣰى لِّلۡعَـٰلَمِینَ',
    'ان اول بيت وضع للناس للذي ببكة مباركا وهدى للعالمين',
    'إِ<rule class=ghunnah>نّ</rule>َ أَوَّلَ بَيۡ<rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>ُضِعَ لِل<rule class=ghunnah>نّ</rule>َاسِ لَلَّذِى بِبَكَّةَ مُبَارَ<rule class=idgham_ghunnah>كًا</rule> <rule class=idgham_ghunnah>و</rule>َهُ<rule class=idgham_wo_ghunnah>دًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٩٦',
    96, 4, 1, 62, 51, 25, 'false'
  );
  
  -- Ayah 97 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    390,
    'فِیهِ ءَایَـٰتُۢ بَیِّنَـٰتࣱ مَّقَامُ إِبۡرَ ٰ⁠هِیمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنࣰاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَیۡتِ مَنِ ٱسۡتَطَاعَ إِلَیۡهِ سَبِیلࣰاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِیٌّ عَنِ ٱلۡعَـٰلَمِینَ',
    'فيه ايات بينات مقام ابراهيم ومن دخله كان امنا ولله على الناس حج البيت من استطاع اليه سبيلا ومن كفر فان الله غني عن العالمين',
    'فِيهِ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تُۢ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>َّقَامُ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>َخَلَهُ<rule class=madda_normal>ۥ</rule> كَانَ ءَامِ<rule class=idgham_ghunnah>نًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َلِلَّهِ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ حِجُّ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتِ مَنِ <rule class=ham_wasl>ٱ</rule>سۡتَطَاعَ إِلَيۡهِ سَبِيل<rule class=idgham_ghunnah>اً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَنِىٌّ عَنِ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٩٧',
    97, 4, 1, 62, 51, 25, 'false'
  );
  
  -- Ayah 98 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    391,
    'قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَٱللَّهُ شَهِیدٌ عَلَىٰ مَا تَعۡمَلُونَ',
    'قل يا اهل الكتاب لم تكفرون بايات الله والله شهيد على ما تعملون',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لِمَ تَكۡفُرُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٨',
    98, 4, 1, 62, 51, 25, 'false'
  );
  
  -- Ayah 99 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    392,
    'قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تَصُدُّونَ عَن سَبِیلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجࣰا وَأَنتُمۡ شُهَدَاۤءُۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ',
    'قل يا اهل الكتاب لم تصدون عن سبيل الله من امن تبغونها عوجا وانتم شهداء وما الله بغافل عما تعملون',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لِمَ تَصُدُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَنۡ ءَامَنَ تَ<rule class=qalaqah>بۡ</rule>غُونَهَا عِوَ<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نت</rule>ُمۡ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>للَّهُ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٩',
    99, 4, 1, 62, 51, 25, 'false'
  );
  
  -- Ayah 100 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    393,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن تُطِیعُوا۟ فَرِیقࣰا مِّنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ یَرُدُّوكُم بَعۡدَ إِیمَـٰنِكُمۡ كَـٰفِرِینَ',
    'يا ايها الذين امنوا ان تطيعوا فريقا من الذين اوتوا الكتاب يردوكم بعد ايمانكم كافرين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُطِيعُو<rule class=slnt>اۡ</rule> فَرِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يَرُدُّوك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡدَ إِيمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٠٠',
    100, 4, 1, 62, 51, 25, 'false'
  );
  
  -- Ayah 101 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    394,
    'وَكَیۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَیۡكُمۡ ءَایَـٰتُ ٱللَّهِ وَفِیكُمۡ رَسُولُهُۥۗ وَمَن یَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِیَ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'وكيف تكفرون وانتم تتلى عليكم ايات الله وفيكم رسوله ومن يعتصم بالله فقد هدي الى صراط مستقيم',
    'وَكَيۡفَ تَكۡفُرُونَ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تُتۡلَىٰ عَلَيۡكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَفِيكُمۡ رَسُولُهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡتَص<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ فَقَ<rule class=qalaqah>دۡ</rule> هُدِىَ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ١٠١',
    101, 4, 1, 63, 51, 25, 'false'
  );
  
  -- Ayah 102 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    395,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ',
    'يا ايها الذين امنوا اتقوا الله حق تقاته ولا تموتن الا وانتم مسلمون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ حَقَّ تُقَاتِه<rule class=madda_normal>ِۦ</rule> وَلَا تَمُوتُ<rule class=ghunnah>نّ</rule>َ إِلَّا وَأَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٠٢',
    102, 4, 1, 63, 52, 25, 'false'
  );
  
  -- Ayah 103 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    396,
    'وَٱعۡتَصِمُوا۟ بِحَبۡلِ ٱللَّهِ جَمِیعࣰا وَلَا تَفَرَّقُوا۟ۚ وَٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَاۤءࣰ فَأَلَّفَ بَیۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦۤ إِخۡوَ ٰ⁠نࣰا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةࣲ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ لَكُمۡ ءَایَـٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ',
    'واعتصموا بحبل الله جميعا ولا تفرقوا واذكروا نعمت الله عليكم اذ كنتم اعداء فالف بين قلوبكم فاصبحتم بنعمته اخوانا وكنتم على شفا حفرة من النار فانقذكم منها كذلك يبين الله لكم اياته لعلكم تهتدون',
    'وَ<rule class=ham_wasl>ٱ</rule>عۡتَصِمُو<rule class=slnt>اۡ</rule> بِحَ<rule class=qalaqah>بۡ</rule>لِ <rule class=ham_wasl>ٱ</rule>للَّهِ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَفَرَّقُو<rule class=slnt>اۡ‌ۚ</rule> وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ إِذۡ كُ<rule class=ikhafa>نت</rule>ُمۡ أَعۡد<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِنِعۡمَتِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِخۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َكُ<rule class=ikhafa>نت</rule>ُمۡ عَلَىٰ شَفَا حُفۡرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ فَأَ<rule class=ikhafa>نق</rule>َذَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا‌ۗ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> لَعَلَّكُمۡ تَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٠٣',
    103, 4, 1, 63, 52, 25, 'false'
  );
  
  -- Ayah 104 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    397,
    'وَلۡتَكُن مِّنكُمۡ أُمَّةࣱ یَدۡعُونَ إِلَى ٱلۡخَیۡرِ وَیَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَیَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'ولتكن منكم امة يدعون الى الخير ويامرون بالمعروف وينهون عن المنكر واولئك هم المفلحون',
    'وَلۡتَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>عُونَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ وَيَأۡمُرُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ‌ۚ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٠٤',
    104, 4, 1, 63, 52, 25, 'false'
  );
  
  -- Ayah 105 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    398,
    'وَلَا تَكُونُوا۟ كَٱلَّذِینَ تَفَرَّقُوا۟ وَٱخۡتَلَفُوا۟ مِنۢ بَعۡدِ مَا جَاۤءَهُمُ ٱلۡبَیِّنَـٰتُۚ وَأُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ عَظِیمࣱ',
    'ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينات واولئك لهم عذاب عظيم',
    'وَلَا تَكُونُو<rule class=slnt>اۡ</rule> كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ تَفَرَّقُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تُ‌ۚ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٠٥',
    105, 4, 1, 63, 52, 25, 'false'
  );
  
  -- Ayah 106 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    399,
    'یَوۡمَ تَبۡیَضُّ وُجُوهࣱ وَتَسۡوَدُّ وُجُوهࣱۚ فَأَمَّا ٱلَّذِینَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِیمَـٰنِكُمۡ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ',
    'يوم تبيض وجوه وتسود وجوه فاما الذين اسودت وجوههم اكفرتم بعد ايمانكم فذوقوا العذاب بما كنتم تكفرون',
    'يَوۡمَ تَ<rule class=qalaqah>بۡ</rule>يَضُّ وُجُو<rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule>َتَسۡوَدُّ وُجُو<rule class=ikhafa>هٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡدَ إِيمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ فَذُوقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ١٠٦',
    106, 4, 1, 63, 52, 25, 'false'
  );
  
  -- Ayah 107 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    400,
    'وَأَمَّا ٱلَّذِینَ ٱبۡیَضَّتۡ وُجُوهُهُمۡ فَفِی رَحۡمَةِ ٱللَّهِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'واما الذين ابيضت وجوههم ففي رحمة الله هم فيها خالدون',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>يَضَّتۡ وُجُوهُهُمۡ فَفِى رَحۡمَةِ <rule class=ham_wasl>ٱ</rule>للَّهِ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ١٠٧',
    107, 4, 1, 63, 52, 25, 'false'
  );
  
  -- Ayah 108 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    401,
    'تِلۡكَ ءَایَـٰتُ ٱللَّهِ نَتۡلُوهَا عَلَیۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ یُرِیدُ ظُلۡمࣰا لِّلۡعَـٰلَمِینَ',
    'تلك ايات الله نتلوها عليك بالحق وما الله يريد ظلما للعالمين',
    'تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>للَّهِ نَتۡلُوهَا عَلَيۡكَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>للَّهُ يُرِيدُ ظُلۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٠٨',
    108, 4, 1, 63, 52, 25, 'false'
  );
  
  -- Ayah 109 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    402,
    'وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ',
    'ولله ما في السماوات وما في الارض والى الله ترجع الامور',
    'وَلِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تُرۡجَعُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رُ ١٠٩',
    109, 4, 1, 64, 52, 25, 'false'
  );
  
  -- Ayah 110 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    403,
    'كُنتُمۡ خَیۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَـٰبِ لَكَانَ خَیۡرࣰا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَـٰسِقُونَ',
    'كنتم خير امة اخرجت للناس تامرون بالمعروف وتنهون عن المنكر وتؤمنون بالله ولو امن اهل الكتاب لكان خيرا لهم منهم المؤمنون واكثرهم الفاسقون',
    'كُ<rule class=ikhafa>نت</rule>ُمۡ خَيۡرَ أُ<rule class=ghunnah>مّ</rule>َةٍ أُخۡرِجَتۡ لِل<rule class=ghunnah>نّ</rule>َاسِ تَأۡمُرُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ وَتُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَلَوۡ ءَامَنَ أَهۡلُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَكَانَ خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّه<rule class=idgham_shafawi>ُم‌ۚ</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ١١٠',
    110, 4, 1, 64, 53, 25, 'false'
  );
  
  -- Ayah 111 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    404,
    'لَن یَضُرُّوكُمۡ إِلَّاۤ أَذࣰىۖ وَإِن یُقَـٰتِلُوكُمۡ یُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا یُنصَرُونَ',
    'لن يضروكم الا اذى وان يقاتلوكم يولوكم الادبار ثم لا ينصرون',
    'ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضُرُّوكُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=idgham_ghunnah>ذًى‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُقَ<rule class=madda_normal>ـٰ</rule>تِلُوكُمۡ يُوَلُّوكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>دۡ</rule>بَارَ ثُ<rule class=ghunnah>مّ</rule>َ لَا يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ١١١',
    111, 4, 1, 64, 53, 25, 'false'
  );
  
  -- Ayah 112 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    405,
    'ضُرِبَتۡ عَلَیۡهِمُ ٱلذِّلَّةُ أَیۡنَ مَا ثُقِفُوۤا۟ إِلَّا بِحَبۡلࣲ مِّنَ ٱللَّهِ وَحَبۡلࣲ مِّنَ ٱلنَّاسِ وَبَاۤءُو بِغَضَبࣲ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَیۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ كَانُوا۟ یَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَیَقۡتُلُونَ ٱلۡأَنۢبِیَاۤءَ بِغَیۡرِ حَقࣲّۚ ذَ ٰ⁠لِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ یَعۡتَدُونَ',
    'ضربت عليهم الذلة اين ما ثقفوا الا بحبل من الله وحبل من الناس وباءوا بغضب من الله وضربت عليهم المسكنة ذلك بانهم كانوا يكفرون بايات الله ويقتلون الانبياء بغير حق ذلك بما عصوا وكانوا يعتدون',
    'ضُرِبَتۡ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّلَّةُ أَيۡنَ مَا ثُقِف<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا بِحَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَحَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَب<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو بِغَضَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَضُرِبَتۡ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡمَسۡكَنَةُ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> يَكۡفُرُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَ<rule class=qalaqah>قۡ</rule>تُلُونَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=iqlab>نۢب</rule>ِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِغَيۡرِ حَ<rule class=ikhafa>قٍّ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ بِمَا عَصَو<rule class=slnt>اۡ</rule> وَّكَانُو<rule class=slnt>اۡ</rule> يَعۡتَد<rule class=madda_permissible>ُو</rule>نَ ١١٢',
    112, 4, 1, 64, 53, 25, 'false'
  );
  
  -- Ayah 113 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    406,
    '۞ لَیۡسُوا۟ سَوَاۤءࣰۗ مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ أُمَّةࣱ قَاۤىِٕمَةࣱ یَتۡلُونَ ءَایَـٰتِ ٱللَّهِ ءَانَاۤءَ ٱلَّیۡلِ وَهُمۡ یَسۡجُدُونَ',
    'ليسوا سواء من اهل الكتاب امة قائمة يتلون ايات الله اناء الليل وهم يسجدون',
    '۞لَيۡسُو<rule class=slnt>اۡ</rule> سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً‌ۗ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِمَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َتۡلُونَ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ ءَان<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَهُمۡ يَسۡجُد<rule class=madda_permissible>ُو</rule>نَ ١١٣',
    113, 4, 1, 64, 53, 26, 'false'
  );
  
  -- Ayah 114 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    407,
    'یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَیَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَیَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَیُسَـٰرِعُونَ فِی ٱلۡخَیۡرَ ٰ⁠تِۖ وَأُو۟لَـٰۤىِٕكَ مِنَ ٱلصَّـٰلِحِینَ',
    'يؤمنون بالله واليوم الاخر ويامرون بالمعروف وينهون عن المنكر ويسارعون في الخيرات واولئك من الصالحين',
    'يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَيَأۡمُرُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ وَيُسَ<rule class=madda_normal>ـٰ</rule>رِعُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تِ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ١١٤',
    114, 4, 1, 64, 53, 26, 'false'
  );
  
  -- Ayah 115 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    408,
    'وَمَا یَفۡعَلُوا۟ مِنۡ خَیۡرࣲ فَلَن یُكۡفَرُوهُۗ وَٱللَّهُ عَلِیمُۢ بِٱلۡمُتَّقِینَ',
    'وما يفعلوا من خير فلن يكفروه والله عليم بالمتقين',
    'وَمَا يَفۡعَلُو<rule class=slnt>اۡ</rule> مِنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُكۡفَرُوهُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ١١٥',
    115, 4, 1, 64, 53, 26, 'false'
  );
  
  -- Ayah 116 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    409,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ لَن تُغۡنِیَ عَنۡهُمۡ أَمۡوَ ٰ⁠لُهُمۡ وَلَاۤ أَوۡلَـٰدُهُم مِّنَ ٱللَّهِ شَیۡـࣰٔاۖ وَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'ان الذين كفروا لن تغني عنهم اموالهم ولا اولادهم من الله شيئا واولئك اصحاب النار هم فيها خالدون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُغۡنِىَ عَنۡهُمۡ أَمۡو<rule class=madda_normal>ٰ</rule>لُهُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۚ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ١١٦',
    116, 4, 1, 65, 53, 26, 'false'
  );
  
  -- Ayah 117 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    410,
    'مَثَلُ مَا یُنفِقُونَ فِی هَـٰذِهِ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا كَمَثَلِ رِیحࣲ فِیهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمࣲ ظَلَمُوۤا۟ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِنۡ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'مثل ما ينفقون في هذه الحياة الدنيا كمثل ريح فيها صر اصابت حرث قوم ظلموا انفسهم فاهلكته وما ظلمهم الله ولكن انفسهم يظلمون',
    'مَثَلُ مَا يُ<rule class=ikhafa>نف</rule>ِقُونَ فِى هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا كَمَثَلِ رِي<rule class=ikhafa>حٍ</rule> <rule class=ikhafa>ف</rule>ِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ظ</rule>َلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ فَأَهۡلَكَتۡهُ‌ۚ وَمَا ظَلَمَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَ<rule class=madda_normal>ـٰ</rule>كِنۡ أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ١١٧',
    117, 4, 1, 65, 53, 26, 'false'
  );
  
  -- Ayah 118 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    411,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةࣰ مِّن دُونِكُمۡ لَا یَأۡلُونَكُمۡ خَبَالࣰا وَدُّوا۟ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَاۤءُ مِنۡ أَفۡوَ ٰ⁠هِهِمۡ وَمَا تُخۡفِی صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَیَّنَّا لَكُمُ ٱلۡـَٔایَـٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ',
    'يا ايها الذين امنوا لا تتخذوا بطانة من دونكم لا يالونكم خبالا ودوا ما عنتم قد بدت البغضاء من افواههم وما تخفي صدورهم اكبر قد بينا لكم الايات ان كنتم تعقلون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَتَّخِذُو<rule class=slnt>اۡ</rule> بِطَانَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِكُمۡ لَا يَأۡلُونَكُمۡ خَبَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َدُّو<rule class=slnt>اۡ</rule> مَا عَنِتُّمۡ قَ<rule class=qalaqah>دۡ</rule> بَدَتِ <rule class=ham_wasl>ٱ</rule>لۡبَغۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ أَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ وَمَا تُخۡفِى صُدُورُهُمۡ أَكۡبَرُ‌ۚ قَ<rule class=qalaqah>دۡ</rule> بَيَّ<rule class=ghunnah>نّ</rule>َا لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١١٨',
    118, 4, 1, 65, 53, 26, 'false'
  );
  
  -- Ayah 119 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    412,
    'هَـٰۤأَنتُمۡ أُو۟لَاۤءِ تُحِبُّونَهُمۡ وَلَا یُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَـٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوۤا۟ ءَامَنَّا وَإِذَا خَلَوۡا۟ عَضُّوا۟ عَلَیۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَیۡظِۚ قُلۡ مُوتُوا۟ بِغَیۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'ها انتم اولاء تحبونهم ولا يحبونكم وتؤمنون بالكتاب كله واذا لقوكم قالوا امنا واذا خلوا عضوا عليكم الانامل من الغيظ قل موتوا بغيظكم ان الله عليم بذات الصدور',
    'هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَ<rule class=ikhafa>نت</rule>ُمۡ أُ<rule class=slnt>وۡ</rule>ل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ تُحِبُّونَهُمۡ وَلَا يُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ كُلِّه<rule class=madda_normal>ِۦ</rule> وَإِذَا لَقُوكُمۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا وَإِذَا خَلَوۡ<rule class=slnt>اۡ</rule> عَضُّو<rule class=slnt>اۡ</rule> عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَنَامِلَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَيۡظِ‌ۚ قُلۡ مُوتُو<rule class=slnt>اۡ</rule> بِغَيۡظِكُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ١١٩',
    119, 4, 1, 65, 53, 26, 'false'
  );
  
  -- Ayah 120 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    413,
    'إِن تَمۡسَسۡكُمۡ حَسَنَةࣱ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَیِّئَةࣱ یَفۡرَحُوا۟ بِهَاۖ وَإِن تَصۡبِرُوا۟ وَتَتَّقُوا۟ لَا یَضُرُّكُمۡ كَیۡدُهُمۡ شَیۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا یَعۡمَلُونَ مُحِیطࣱ',
    'ان تمسسكم حسنة تسؤهم وان تصبكم سيئة يفرحوا بها وان تصبروا وتتقوا لا يضركم كيدهم شيئا ان الله بما يعملون محيط',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمۡسَسۡكُمۡ حَسَنَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>َسُؤۡهُمۡ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِ<rule class=qalaqah>بۡ</rule>كُمۡ سَيِّئَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َفۡرَحُو<rule class=slnt>اۡ</rule> بِهَا‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصۡبِرُو<rule class=slnt>اۡ</rule> وَتَتَّقُو<rule class=slnt>اۡ</rule> لَا يَضُرُّكُمۡ كَيۡدُهُمۡ شَيۡــًٔا‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِمَا يَعۡمَلُونَ مُح<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ط</rule>ٌ ١٢٠',
    120, 4, 1, 65, 53, 26, 'false'
  );
  
  -- Ayah 121 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    414,
    'وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِینَ مَقَـٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِیعٌ عَلِیمٌ',
    'واذ غدوت من اهلك تبوئ المؤمنين مقاعد للقتال والله سميع عليم',
    'وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ مَقَ<rule class=madda_normal>ـٰ</rule>عِدَ لِلۡقِتَالِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٢١',
    121, 4, 1, 65, 54, 26, 'false'
  );
  
  -- Ayah 122 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    415,
    'إِذۡ هَمَّت طَّاۤىِٕفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِیُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ',
    'اذ همت طائفتان منكم ان تفشلا والله وليهما وعلى الله فليتوكل المؤمنون',
    'إِذۡ هَ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_mutajanisayn>ت</rule> طّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَتَانِ مِ<rule class=ikhafa>نك</rule>ُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َفۡشَلَا وَ<rule class=ham_wasl>ٱ</rule>للَّهُ وَلِيُّهُمَا‌ۗ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٢٢',
    122, 4, 1, 66, 54, 26, 'false'
  );
  
  -- Ayah 123 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    416,
    'وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرࣲ وَأَنتُمۡ أَذِلَّةࣱۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ',
    'ولقد نصركم الله ببدر وانتم اذلة فاتقوا الله لعلكم تشكرون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> نَصَرَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِبَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نت</rule>ُمۡ أَذِلَّ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٢٣',
    123, 4, 1, 66, 54, 26, 'false'
  );
  
  -- Ayah 124 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    417,
    'إِذۡ تَقُولُ لِلۡمُؤۡمِنِینَ أَلَن یَكۡفِیَكُمۡ أَن یُمِدَّكُمۡ رَبُّكُم بِثَلَـٰثَةِ ءَالَـٰفࣲ مِّنَ ٱلۡمَلَـٰۤىِٕكَةِ مُنزَلِینَ',
    'اذ تقول للمؤمنين الن يكفيكم ان يمدكم ربكم بثلاثة الاف من الملائكة منزلين',
    'إِذۡ تَقُولُ لِلۡمُؤۡمِنِينَ أَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفِيَكُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُمِدَّكُمۡ رَبُّك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِثَلَ<rule class=madda_normal>ـٰ</rule>ثَةِ ءَالَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ مُ<rule class=ikhafa>نز</rule>َل<rule class=madda_permissible>ِي</rule>نَ ١٢٤',
    124, 4, 1, 66, 54, 26, 'false'
  );
  
  -- Ayah 125 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    418,
    'بَلَىٰۤۚ إِن تَصۡبِرُوا۟ وَتَتَّقُوا۟ وَیَأۡتُوكُم مِّن فَوۡرِهِمۡ هَـٰذَا یُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَـٰفࣲ مِّنَ ٱلۡمَلَـٰۤىِٕكَةِ مُسَوِّمِینَ',
    'بلى ان تصبروا وتتقوا وياتوكم من فورهم هذا يمددكم ربكم بخمسة الاف من الملائكة مسومين',
    'بَلَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۚ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصۡبِرُو<rule class=slnt>اۡ</rule> وَتَتَّقُو<rule class=slnt>اۡ</rule> وَيَأۡتُوك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡرِهِمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا يُمۡدِ<rule class=qalaqah>دۡ</rule>كُمۡ رَبُّك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَمۡسَةِ ءَالَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ مُسَوِّم<rule class=madda_permissible>ِي</rule>نَ ١٢٥',
    125, 4, 1, 66, 54, 26, 'false'
  );
  
  -- Ayah 126 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    419,
    'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَىِٕنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ',
    'وما جعله الله الا بشرى لكم ولتطمئن قلوبكم به وما النصر الا من عند الله العزيز الحكيم',
    'وَمَا جَعَلَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>َ قُلُوبُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصۡرُ إِلَّا مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ١٢٦',
    126, 4, 1, 66, 54, 26, 'false'
  );
  
  -- Ayah 127 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    420,
    'لِیَقۡطَعَ طَرَفࣰا مِّنَ ٱلَّذِینَ كَفَرُوۤا۟ أَوۡ یَكۡبِتَهُمۡ فَیَنقَلِبُوا۟ خَاۤىِٕبِینَ',
    'ليقطع طرفا من الذين كفروا او يكبتهم فينقلبوا خائبين',
    'لِيَ<rule class=qalaqah>قۡ</rule>طَعَ طَرَ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡ يَكۡبِتَهُمۡ فَيَ<rule class=ikhafa>نق</rule>َلِبُو<rule class=slnt>اۡ</rule> خ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِب<rule class=madda_permissible>ِي</rule>نَ ١٢٧',
    127, 4, 1, 66, 54, 26, 'false'
  );
  
  -- Ayah 128 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    421,
    'لَیۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَیۡءٌ أَوۡ یَتُوبَ عَلَیۡهِمۡ أَوۡ یُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَـٰلِمُونَ',
    'ليس لك من الامر شيء او يتوب عليهم او يعذبهم فانهم ظالمون',
    'لَيۡسَ لَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ شَىۡءٌ أَوۡ يَتُوبَ عَلَيۡهِمۡ أَوۡ يُعَذِّبَهُمۡ فَإِ<rule class=ghunnah>نّ</rule>َهُمۡ ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ١٢٨',
    128, 4, 1, 66, 54, 26, 'false'
  );
  
  -- Ayah 129 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    422,
    'وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ یَغۡفِرُ لِمَن یَشَاۤءُ وَیُعَذِّبُ مَن یَشَاۤءُۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'ولله ما في السماوات وما في الارض يغفر لمن يشاء ويعذب من يشاء والله غفور رحيم',
    'وَلِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ يَغۡفِرُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيُعَذِّبُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٢٩',
    129, 4, 1, 66, 54, 26, 'false'
  );
  
  -- Ayah 130 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    423,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَأۡكُلُوا۟ ٱلرِّبَوٰۤا۟ أَضۡعَـٰفࣰا مُّضَـٰعَفَةࣰۖ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ',
    'يا ايها الذين امنوا لا تاكلوا الربا اضعافا مضاعفة واتقوا الله لعلكم تفلحون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَأۡكُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّبَ<rule class=madda_obligatory_monfasel><rule class=slnt>و</rule>ٰٓاۡ</rule> أَضۡعَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ُّضَ<rule class=madda_normal>ـٰ</rule>عَفَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٣٠',
    130, 4, 1, 66, 55, 26, 'false'
  );
  
  -- Ayah 131 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    424,
    'وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِیۤ أُعِدَّتۡ لِلۡكَـٰفِرِینَ',
    'واتقوا النار التي اعدت للكافرين',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُعِدَّتۡ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٣١',
    131, 4, 1, 66, 55, 26, 'false'
  );
  
  -- Ayah 132 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    425,
    'وَأَطِیعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ',
    'واطيعوا الله والرسول لعلكم ترحمون',
    'وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ لَعَلَّكُمۡ تُرۡحَم<rule class=madda_permissible>ُو</rule>نَ ١٣٢',
    132, 4, 1, 66, 55, 26, 'false'
  );
  
  -- Ayah 133 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    426,
    '۞ وَسَارِعُوۤا۟ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَـٰوَ ٰ⁠تُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِینَ',
    'وسارعوا الى مغفرة من ربكم وجنة عرضها السماوات والارض اعدت للمتقين',
    '۞وَسَارِع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ مَغۡفِرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَجَ<rule class=ghunnah>نّ</rule>َةٍ عَرۡضُهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ١٣٣',
    133, 4, 1, 67, 55, 27, 'false'
  );
  
  -- Ayah 134 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    427,
    'ٱلَّذِینَ یُنفِقُونَ فِی ٱلسَّرَّاۤءِ وَٱلضَّرَّاۤءِ وَٱلۡكَـٰظِمِینَ ٱلۡغَیۡظَ وَٱلۡعَافِینَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ یُحِبُّ ٱلۡمُحۡسِنِینَ',
    'الذين ينفقون في السراء والضراء والكاظمين الغيظ والعافين عن الناس والله يحب المحسنين',
    'ٱلَّذِينَ يُ<rule class=ikhafa>نف</rule>ِقُونَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ظِمِينَ <rule class=ham_wasl>ٱ</rule>لۡغَيۡظَ وَ<rule class=ham_wasl>ٱ</rule>لۡعَافِينَ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٣٤',
    134, 4, 1, 67, 55, 27, 'false'
  );
  
  -- Ayah 135 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    428,
    'وَٱلَّذِینَ إِذَا فَعَلُوا۟ فَـٰحِشَةً أَوۡ ظَلَمُوۤا۟ أَنفُسَهُمۡ ذَكَرُوا۟ ٱللَّهَ فَٱسۡتَغۡفَرُوا۟ لِذُنُوبِهِمۡ وَمَن یَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ یُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمۡ یَعۡلَمُونَ',
    'والذين اذا فعلوا فاحشة او ظلموا انفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب الا الله ولم يصروا على ما فعلوا وهم يعلمون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ إِذَا فَعَلُو<rule class=slnt>اۡ</rule> فَ<rule class=madda_normal>ـٰ</rule>حِشَةً أَوۡ ظَلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ ذَكَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ فَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفَرُو<rule class=slnt>اۡ</rule> لِذُنُوبِهِمۡ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغۡفِرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذُّنُوبَ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَمۡ يُصِرُّو<rule class=slnt>اۡ</rule> عَلَىٰ مَا فَعَلُو<rule class=slnt>اۡ</rule> وَهُمۡ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٣٥',
    135, 4, 1, 67, 55, 27, 'false'
  );
  
  -- Ayah 136 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    429,
    'أُو۟لَـٰۤىِٕكَ جَزَاۤؤُهُم مَّغۡفِرَةࣱ مِّن رَّبِّهِمۡ وَجَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَـٰمِلِینَ',
    'اولئك جزاؤهم مغفرة من ربهم وجنات تجري من تحتها الانهار خالدين فيها ونعم اجر العاملين',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ وَجَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ وَنِعۡمَ أَ<rule class=qalaqah>جۡ</rule>رُ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>مِل<rule class=madda_permissible>ِي</rule>نَ ١٣٦',
    136, 4, 1, 67, 55, 27, 'false'
  );
  
  -- Ayah 137 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    430,
    'قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنࣱ فَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُكَذِّبِینَ',
    'قد خلت من قبلكم سنن فسيروا في الارض فانظروا كيف كان عاقبة المكذبين',
    'قَ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ سُنَ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُكَذِّب<rule class=madda_permissible>ِي</rule>نَ ١٣٧',
    137, 4, 1, 67, 55, 27, 'false'
  );
  
  -- Ayah 138 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    431,
    'هَـٰذَا بَیَانࣱ لِّلنَّاسِ وَهُدࣰى وَمَوۡعِظَةࣱ لِّلۡمُتَّقِینَ',
    'هذا بيان للناس وهدى وموعظة للمتقين',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا بَيَا<rule class=idgham_wo_ghunnah>نٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َمَوۡعِظَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ١٣٨',
    138, 4, 1, 67, 55, 27, 'false'
  );
  
  -- Ayah 139 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    432,
    'وَلَا تَهِنُوا۟ وَلَا تَحۡزَنُوا۟ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِینَ',
    'ولا تهنوا ولا تحزنوا وانتم الاعلون ان كنتم مؤمنين',
    'وَلَا تَهِنُو<rule class=slnt>اۡ</rule> وَلَا تَحۡزَنُو<rule class=slnt>اۡ</rule> وَأَ<rule class=ikhafa>نت</rule>ُمُ <rule class=ham_wasl>ٱ</rule>لۡأَعۡلَوۡنَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٣٩',
    139, 4, 1, 67, 55, 27, 'false'
  );
  
  -- Ayah 140 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    433,
    'إِن یَمۡسَسۡكُمۡ قَرۡحࣱ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحࣱ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَیَّامُ نُدَاوِلُهَا بَیۡنَ ٱلنَّاسِ وَلِیَعۡلَمَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَیَتَّخِذَ مِنكُمۡ شُهَدَاۤءَۗ وَٱللَّهُ لَا یُحِبُّ ٱلظَّـٰلِمِینَ',
    'ان يمسسكم قرح فقد مس القوم قرح مثله وتلك الايام نداولها بين الناس وليعلم الله الذين امنوا ويتخذ منكم شهداء والله لا يحب الظالمين',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡسَسۡكُمۡ قَرۡ<rule class=ikhafa>حٌ</rule> <rule class=ikhafa>ف</rule>َقَ<rule class=qalaqah>دۡ</rule> مَسَّ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ قَرۡ<rule class=idgham_ghunnah>حٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَتِلۡكَ <rule class=ham_wasl>ٱ</rule>لۡأَيَّامُ نُدَاوِلُهَا بَيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلِيَعۡلَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَيَتَّخِذَ مِ<rule class=ikhafa>نك</rule>ُمۡ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٤٠',
    140, 4, 1, 67, 55, 27, 'false'
  );
  
  -- Ayah 141 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    434,
    'وَلِیُمَحِّصَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَیَمۡحَقَ ٱلۡكَـٰفِرِینَ',
    'وليمحص الله الذين امنوا ويمحق الكافرين',
    'وَلِيُمَحِّصَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَيَمۡحَقَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٤١',
    141, 4, 1, 68, 55, 27, 'false'
  );
  
  -- Ayah 142 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    435,
    'أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُوا۟ ٱلۡجَنَّةَ وَلَمَّا یَعۡلَمِ ٱللَّهُ ٱلَّذِینَ جَـٰهَدُوا۟ مِنكُمۡ وَیَعۡلَمَ ٱلصَّـٰبِرِینَ',
    'ام حسبتم ان تدخلوا الجنة ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين',
    'أَمۡ حَسِ<rule class=qalaqah>بۡ</rule>تُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ وَلَ<rule class=ghunnah>مّ</rule>َا يَعۡلَمِ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ جَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ وَيَعۡلَمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ١٤٢',
    142, 4, 1, 68, 55, 27, 'false'
  );
  
  -- Ayah 143 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    436,
    'وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَیۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ',
    'ولقد كنتم تمنون الموت من قبل ان تلقوه فقد رايتموه وانتم تنظرون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> كُ<rule class=ikhafa>نت</rule>ُمۡ تَمَ<rule class=ghunnah>نّ</rule>َوۡنَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َلۡقَوۡهُ فَقَ<rule class=qalaqah>دۡ</rule> رَأَيۡتُمُوهُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ١٤٣',
    143, 4, 1, 68, 55, 27, 'false'
  );
  
  -- Ayah 144 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    437,
    'وَمَا مُحَمَّدٌ إِلَّا رَسُولࣱ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِی۟ن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰۤ أَعۡقَـٰبِكُمۡۚ وَمَن یَنقَلِبۡ عَلَىٰ عَقِبَیۡهِ فَلَن یَضُرَّ ٱللَّهَ شَیۡـࣰٔاۗ وَسَیَجۡزِی ٱللَّهُ ٱلشَّـٰكِرِینَ',
    'وما محمد الا رسول قد خلت من قبله الرسل افان مات او قتل انقلبتم على اعقابكم ومن ينقلب على عقبيه فلن يضر الله شيئا وسيجزي الله الشاكرين',
    'وَمَا مُحَ<rule class=ghunnah>مّ</rule>َدٌ إِلَّا رَسُو<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلُ‌ۚ أَفَإِ<rule class=slnt>يۡ</rule><rule class=idgham_ghunnah>ن</rule> <rule class=idgham_ghunnah>م</rule>َّاتَ أَوۡ قُتِلَ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>َلَ<rule class=qalaqah>بۡ</rule>تُمۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَعۡقَ<rule class=madda_normal>ـٰ</rule>بِكُمۡ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نق</rule>َلِ<rule class=qalaqah>بۡ</rule> عَلَىٰ عَقِبَيۡهِ فَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضُرَّ <rule class=ham_wasl>ٱ</rule>للَّهَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َسَيَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ١٤٤',
    144, 4, 1, 68, 56, 27, 'false'
  );
  
  -- Ayah 145 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    438,
    'وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَـٰبࣰا مُّؤَجَّلࣰاۗ وَمَن یُرِدۡ ثَوَابَ ٱلدُّنۡیَا نُؤۡتِهِۦ مِنۡهَا وَمَن یُرِدۡ ثَوَابَ ٱلۡـَٔاخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِی ٱلشَّـٰكِرِینَ',
    'وما كان لنفس ان تموت الا باذن الله كتابا مؤجلا ومن يرد ثواب الدنيا نؤته منها ومن يرد ثواب الاخرة نؤته منها وسنجزي الشاكرين',
    'وَمَا كَانَ لِنَفۡسٍ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمُوتَ إِلَّا بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ُّؤَجَّل<rule class=idgham_ghunnah>اً‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِ<rule class=qalaqah>دۡ</rule> ثَوَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا نُؤۡتِه<rule class=madda_normal>ِۦ</rule> مِنۡهَا وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِ<rule class=qalaqah>دۡ</rule> ثَوَابَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ نُؤۡتِه<rule class=madda_normal>ِۦ</rule> مِنۡهَا‌ۚ وَسَنَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ١٤٥',
    145, 4, 1, 68, 56, 27, 'false'
  );
  
  -- Ayah 146 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    439,
    'وَكَأَیِّن مِّن نَّبِیࣲّ قَـٰتَلَ مَعَهُۥ رِبِّیُّونَ كَثِیرࣱ فَمَا وَهَنُوا۟ لِمَاۤ أَصَابَهُمۡ فِی سَبِیلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسۡتَكَانُوا۟ۗ وَٱللَّهُ یُحِبُّ ٱلصَّـٰبِرِینَ',
    'وكاين من نبي قاتل معه ربيون كثير فما وهنوا لما اصابهم في سبيل الله وما ضعفوا وما استكانوا والله يحب الصابرين',
    'وَكَأَيّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّبِ<rule class=ikhafa>ىٍّ</rule> <rule class=ikhafa>ق</rule>َ<rule class=madda_normal>ـٰ</rule>تَلَ مَعَهُ<rule class=madda_normal>ۥ</rule> رِبِّيُّونَ كَثِي<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َمَا وَهَنُو<rule class=slnt>اۡ</rule> لِم<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَهُمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَا ضَعُفُو<rule class=slnt>اۡ</rule> وَمَا <rule class=ham_wasl>ٱ</rule>سۡتَكَانُو<rule class=slnt>اۡ‌ۗ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُحِبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ١٤٦',
    146, 4, 1, 68, 56, 27, 'false'
  );
  
  -- Ayah 147 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    440,
    'وَمَا كَانَ قَوۡلَهُمۡ إِلَّاۤ أَن قَالُوا۟ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِیۤ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ',
    'وما كان قولهم الا ان قالوا ربنا اغفر لنا ذنوبنا واسرافنا في امرنا وثبت اقدامنا وانصرنا على القوم الكافرين',
    'وَمَا كَانَ قَوۡلَهُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> رَبَّنَا <rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمۡرِنَا وَثَبِّتۡ أَ<rule class=qalaqah>قۡ</rule>دَامَنَا وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نص</rule>ُرۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٤٧',
    147, 4, 1, 68, 56, 27, 'false'
  );
  
  -- Ayah 148 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    441,
    'فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡیَا وَحُسۡنَ ثَوَابِ ٱلۡـَٔاخِرَةِۗ وَٱللَّهُ یُحِبُّ ٱلۡمُحۡسِنِینَ',
    'فاتاهم الله ثواب الدنيا وحسن ثواب الاخرة والله يحب المحسنين',
    'فَـَٔـاتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ ثَوَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَحُسۡنَ ثَوَابِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٤٨',
    148, 4, 1, 68, 56, 27, 'false'
  );
  
  -- Ayah 149 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    442,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن تُطِیعُوا۟ ٱلَّذِینَ كَفَرُوا۟ یَرُدُّوكُمۡ عَلَىٰۤ أَعۡقَـٰبِكُمۡ فَتَنقَلِبُوا۟ خَـٰسِرِینَ',
    'يا ايها الذين امنوا ان تطيعوا الذين كفروا يردوكم على اعقابكم فتنقلبوا خاسرين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> يَرُدُّوكُمۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَعۡقَ<rule class=madda_normal>ـٰ</rule>بِكُمۡ فَتَ<rule class=ikhafa>نق</rule>َلِبُو<rule class=slnt>اۡ</rule> خَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ١٤٩',
    149, 4, 1, 69, 57, 27, 'false'
  );
  
  -- Ayah 150 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    443,
    'بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَیۡرُ ٱلنَّـٰصِرِینَ',
    'بل الله مولاكم وهو خير الناصرين',
    'بَلِ <rule class=ham_wasl>ٱ</rule>للَّهُ مَوۡلَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ وَهُوَ خَيۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ١٥٠',
    150, 4, 1, 69, 57, 27, 'false'
  );
  
  -- Ayah 151 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    444,
    'سَنُلۡقِی فِی قُلُوبِ ٱلَّذِینَ كَفَرُوا۟ ٱلرُّعۡبَ بِمَاۤ أَشۡرَكُوا۟ بِٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ سُلۡطَـٰنࣰاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّـٰلِمِینَ',
    'سنلقي في قلوب الذين كفروا الرعب بما اشركوا بالله ما لم ينزل به سلطانا وماواهم النار وبئس مثوى الظالمين',
    'سَنُلۡقِى فِى قُلُوبِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّعۡبَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡرَكُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَمۡ يُنَزِّلۡ بِه<rule class=madda_normal>ِۦ</rule> سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ‌ۚ وَبِئۡسَ مَثۡوَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٥١',
    151, 4, 1, 69, 57, 27, 'false'
  );
  
  -- Ayah 152 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    445,
    'وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥۤ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰۤ إِذَا فَشِلۡتُمۡ وَتَنَـٰزَعۡتُمۡ فِی ٱلۡأَمۡرِ وَعَصَیۡتُم مِّنۢ بَعۡدِ مَاۤ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن یُرِیدُ ٱلدُّنۡیَا وَمِنكُم مَّن یُرِیدُ ٱلۡـَٔاخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِیَبۡتَلِیَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِینَ',
    'ولقد صدقكم الله وعده اذ تحسونهم باذنه حتى اذا فشلتم وتنازعتم في الامر وعصيتم من بعد ما اراكم ما تحبون منكم من يريد الدنيا ومنكم من يريد الاخرة ثم صرفكم عنهم ليبتليكم ولقد عفا عنكم والله ذو فضل على المؤمنين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> صَدَقَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَعۡدَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِذۡ تَحُسُّونَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِإِذۡنِه<rule class=madda_normal>ِۦ</rule>‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا فَشِلۡتُمۡ وَتَنَ<rule class=madda_normal>ـٰ</rule>زَعۡتُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ وَعَصَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ م<rule class=madda_obligatory_monfasel>َآ</rule> أَرَ<rule class=madda_normal>ٮٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا تُحِبُّونَ‌ۚ مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَمِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيدُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ‌ۚ ثُ<rule class=ghunnah>مّ</rule>َ صَرَفَكُمۡ عَنۡهُمۡ لِيَ<rule class=qalaqah>بۡ</rule>تَلِيَكُمۡ‌ۖ وَلَقَ<rule class=qalaqah>دۡ</rule> عَفَا عَ<rule class=ikhafa>نك</rule>ُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ ذُو فَضۡلٍ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٥٢',
    152, 4, 1, 69, 57, 27, 'false'
  );
  
  -- Ayah 153 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    446,
    '۞ إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰۤ أَحَدࣲ وَٱلرَّسُولُ یَدۡعُوكُمۡ فِیۤ أُخۡرَىٰكُمۡ فَأَثَـٰبَكُمۡ غَمَّۢا بِغَمࣲّ لِّكَیۡلَا تَحۡزَنُوا۟ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَاۤ أَصَـٰبَكُمۡۗ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ',
    'اذ تصعدون ولا تلوون على احد والرسول يدعوكم في اخراكم فاثابكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما اصابكم والله خبير بما تعملون',
    '۞إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُ<rule class=madda_normal>ۥ</rule>نَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ يَ<rule class=qalaqah>دۡ</rule>عُوكُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُخۡرَ<rule class=madda_normal>ٮٰ</rule>كُمۡ فَأَثَ<rule class=madda_normal>ـٰ</rule>بَكُمۡ غَ<rule class=ghunnah>مّ</rule><rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِغَ<rule class=idgham_wo_ghunnah>مٍّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكَيۡلَا تَحۡزَنُو<rule class=slnt>اۡ</rule> عَلَىٰ مَا فَاتَكُمۡ وَلَا م<rule class=madda_obligatory_monfasel>َآ</rule> أَصَ<rule class=madda_normal>ـٰ</rule>بَكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٥٣',
    153, 4, 1, 69, 57, 28, 'false'
  );
  
  -- Ayah 154 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    447,
    'ثُمَّ أَنزَلَ عَلَیۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةࣰ نُّعَاسࣰا یَغۡشَىٰ طَاۤىِٕفَةࣰ مِّنكُمۡۖ وَطَاۤىِٕفَةࣱ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ یَظُنُّونَ بِٱللَّهِ غَیۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَـٰهِلِیَّةِۖ یَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَیۡءࣲۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ یُخۡفُونَ فِیۤ أَنفُسِهِم مَّا لَا یُبۡدُونَ لَكَۖ یَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَیۡءࣱ مَّا قُتِلۡنَا هَـٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِی بُیُوتِكُمۡ لَبَرَزَ ٱلَّذِینَ كُتِبَ عَلَیۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِیَبۡتَلِیَ ٱللَّهُ مَا فِی صُدُورِكُمۡ وَلِیُمَحِّصَ مَا فِی قُلُوبِكُمۡۚ وَٱللَّهُ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'ثم انزل عليكم من بعد الغم امنة نعاسا يغشى طائفة منكم وطائفة قد اهمتهم انفسهم يظنون بالله غير الحق ظن الجاهلية يقولون هل لنا من الامر من شيء قل ان الامر كله لله يخفون في انفسهم ما لا يبدون لك يقولون لو كان لنا من الامر شيء ما قتلنا هاهنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل الى مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=ikhafa>نز</rule>َلَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=ghunnah>مّ</rule>ِ أَمَنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ن</rule>ُّعَا<rule class=idgham_ghunnah>سًا</rule> <rule class=idgham_ghunnah>ي</rule>َغۡشَىٰ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ‌ۖ وَط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> أَهَ<rule class=ghunnah>مّ</rule>َتۡهُمۡ أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ يَظُ<rule class=ghunnah>نّ</rule>ُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ غَيۡرَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ ظَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِلِيَّةِ‌ۖ يَقُولُونَ هَل لَّنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۗ</rule> <rule class=ikhafa>ق</rule>ُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرَ كُلَّهُ<rule class=madda_normal>ۥ</rule> لِلَّهِ‌ۗ يُخۡفُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا لَا يُ<rule class=qalaqah>بۡ</rule>دُونَ لَكَ‌ۖ يَقُولُونَ لَوۡ كَانَ لَنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ ش<rule class=idgham_ghunnah>َىۡءٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا قُتِلۡنَا هَ<rule class=madda_normal>ـٰ</rule>هُنَا‌ۗ قُل لَّوۡ كُ<rule class=ikhafa>نت</rule>ُمۡ فِى بُيُوتِكُمۡ لَبَرَزَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كُتِبَ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡ‌ۖ وَلِيَ<rule class=qalaqah>بۡ</rule>تَلِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا فِى صُدُورِكُمۡ وَلِيُمَحِّصَ مَا فِى قُلُوبِكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ١٥٤',
    154, 4, 1, 70, 57, 28, 'false'
  );
  
  -- Ayah 155 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    448,
    'إِنَّ ٱلَّذِینَ تَوَلَّوۡا۟ مِنكُمۡ یَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّیۡطَـٰنُ بِبَعۡضِ مَا كَسَبُوا۟ۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِیمࣱ',
    'ان الذين تولوا منكم يوم التقى الجمعان انما استزلهم الشيطان ببعض ما كسبوا ولقد عفا الله عنهم ان الله غفور حليم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَوَلَّوۡ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ۡتَقَى <rule class=ham_wasl>ٱ</rule>لۡجَمۡعَانِ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>سۡتَزَلَّهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ بِبَعۡضِ مَا كَسَبُو<rule class=slnt>اۡ‌ۖ</rule> وَلَقَ<rule class=qalaqah>دۡ</rule> عَفَا <rule class=ham_wasl>ٱ</rule>للَّهُ عَنۡهُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُورٌ حَل<rule class=madda_permissible>ِي</rule>مٌ ١٥٥',
    155, 4, 1, 70, 57, 28, 'false'
  );
  
  -- Ayah 156 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    449,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِینَ كَفَرُوا۟ وَقَالُوا۟ لِإِخۡوَ ٰ⁠نِهِمۡ إِذَا ضَرَبُوا۟ فِی ٱلۡأَرۡضِ أَوۡ كَانُوا۟ غُزࣰّى لَّوۡ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِیَجۡعَلَ ٱللَّهُ ذَ ٰ⁠لِكَ حَسۡرَةࣰ فِی قُلُوبِهِمۡۗ وَٱللَّهُ یُحۡیِۦ وَیُمِیتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ',
    'يا ايها الذين امنوا لا تكونوا كالذين كفروا وقالوا لاخوانهم اذا ضربوا في الارض او كانوا غزى لو كانوا عندنا ما ماتوا وما قتلوا ليجعل الله ذلك حسرة في قلوبهم والله يحيي ويميت والله بما تعملون بصير',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَكُونُو<rule class=slnt>اۡ</rule> كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَقَالُو<rule class=slnt>اۡ</rule> لِإِخۡو<rule class=madda_normal>ٰ</rule>نِهِمۡ إِذَا ضَرَبُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَوۡ كَانُو<rule class=slnt>اۡ</rule> غُز<rule class=idgham_wo_ghunnah>ًّى</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡ كَانُو<rule class=slnt>اۡ</rule> عِ<rule class=ikhafa>ند</rule>َنَا مَا مَاتُو<rule class=slnt>اۡ</rule> وَمَا قُتِلُو<rule class=slnt>اۡ</rule> لِيَ<rule class=qalaqah>جۡ</rule>عَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ ذ<rule class=madda_normal>ٰ</rule>لِكَ حَسۡرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى قُلُوبِهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ١٥٦',
    156, 4, 1, 70, 58, 28, 'false'
  );
  
  -- Ayah 157 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    450,
    'وَلَىِٕن قُتِلۡتُمۡ فِی سَبِیلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةࣱ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَیۡرࣱ مِّمَّا یَجۡمَعُونَ',
    'ولئن قتلتم في سبيل الله او متم لمغفرة من الله ورحمة خير مما يجمعون',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُتِلۡتُمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَحۡمَةٌ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ُو</rule>نَ ١٥٧',
    157, 4, 1, 70, 58, 28, 'false'
  );
  
  -- Ayah 158 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    451,
    'وَلَىِٕن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ',
    'ولئن متم او قتلتم لالى الله تحشرون',
    'وَلَئ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ١٥٨',
    158, 4, 1, 71, 58, 28, 'false'
  );
  
  -- Ayah 159 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    452,
    'فَبِمَا رَحۡمَةࣲ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِیظَ ٱلۡقَلۡبِ لَٱنفَضُّوا۟ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِی ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُتَوَكِّلِینَ',
    'فبما رحمة من الله لنت لهم ولو كنت فظا غليظ القلب لانفضوا من حولك فاعف عنهم واستغفر لهم وشاورهم في الامر فاذا عزمت فتوكل على الله ان الله يحب المتوكلين',
    'فَبِمَا رَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ لِ<rule class=ikhafa>نت</rule>َ لَهُمۡ‌ۖ وَلَوۡ كُ<rule class=ikhafa>نت</rule>َ فَظًّا غَلِيظَ <rule class=ham_wasl>ٱ</rule>لۡقَلۡبِ لَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>َضُّو<rule class=slnt>اۡ</rule> مِنۡ حَوۡلِكَ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>عۡفُ عَنۡهُمۡ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ‌ۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُتَوَكِّل<rule class=madda_permissible>ِي</rule>نَ ١٥٩',
    159, 4, 1, 71, 58, 28, 'false'
  );
  
  -- Ayah 160 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    453,
    'إِن یَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن یَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِی یَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ',
    'ان ينصركم الله فلا غالب لكم وان يخذلكم فمن ذا الذي ينصركم من بعده وعلى الله فليتوكل المؤمنون',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرۡكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ فَلَا غَالِبَ لَكُمۡ‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡذُلۡكُمۡ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِى يَ<rule class=ikhafa>نص</rule>ُرُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٦٠',
    160, 4, 1, 71, 58, 28, 'false'
  );
  
  -- Ayah 161 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    454,
    'وَمَا كَانَ لِنَبِیٍّ أَن یَغُلَّۚ وَمَن یَغۡلُلۡ یَأۡتِ بِمَا غَلَّ یَوۡمَ ٱلۡقِیَـٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا یُظۡلَمُونَ',
    'وما كان لنبي ان يغل ومن يغلل يات بما غل يوم القيامة ثم توفى كل نفس ما كسبت وهم لا يظلمون',
    'وَمَا كَانَ لِنَبِىٍّ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغُلَّ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغۡلُلۡ يَأۡتِ بِمَا غَلَّ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ ثُ<rule class=ghunnah>مّ</rule>َ تُوَفَّىٰ كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا كَسَبَتۡ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٦١',
    161, 4, 1, 71, 58, 28, 'false'
  );
  
  -- Ayah 162 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    455,
    'أَفَمَنِ ٱتَّبَعَ رِضۡوَ ٰ⁠نَ ٱللَّهِ كَمَنۢ بَاۤءَ بِسَخَطࣲ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'افمن اتبع رضوان الله كمن باء بسخط من الله وماواه جهنم وبئس المصير',
    'أَفَمَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَ رِضۡو<rule class=madda_normal>ٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ كَم<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِسَخَ<rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۚ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٦٢',
    162, 4, 1, 71, 58, 28, 'false'
  );
  
  -- Ayah 163 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    456,
    'هُمۡ دَرَجَـٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِیرُۢ بِمَا یَعۡمَلُونَ',
    'هم درجات عند الله والله بصير بما يعملون',
    'هُمۡ دَرَجَ<rule class=madda_normal>ـٰ</rule>تٌ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بَصِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٦٣',
    163, 4, 1, 71, 58, 28, 'false'
  );
  
  -- Ayah 164 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    457,
    'لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِینَ إِذۡ بَعَثَ فِیهِمۡ رَسُولࣰا مِّنۡ أَنفُسِهِمۡ یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِهِۦ وَیُزَكِّیهِمۡ وَیُعَلِّمُهُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُوا۟ مِن قَبۡلُ لَفِی ضَلَـٰلࣲ مُّبِینٍ',
    'لقد من الله على المؤمنين اذ بعث فيهم رسولا من انفسهم يتلو عليهم اياته ويزكيهم ويعلمهم الكتاب والحكمة وان كانوا من قبل لفي ضلال مبين',
    'لَقَ<rule class=qalaqah>دۡ</rule> مَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ إِذۡ بَعَثَ فِيهِمۡ رَسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ يَتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ لَفِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١٦٤',
    164, 4, 1, 71, 58, 28, 'false'
  );
  
  -- Ayah 165 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    458,
    'أَوَلَمَّاۤ أَصَـٰبَتۡكُم مُّصِیبَةࣱ قَدۡ أَصَبۡتُم مِّثۡلَیۡهَا قُلۡتُمۡ أَنَّىٰ هَـٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'اولما اصابتكم مصيبة قد اصبتم مثليها قلتم انى هذا قل هو من عند انفسكم ان الله على كل شيء قدير',
    'أَوَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَصَ<rule class=madda_normal>ـٰ</rule>بَتۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّصِيبَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> أَصَ<rule class=qalaqah>بۡ</rule>ت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّثۡلَيۡهَا قُلۡتُمۡ أَ<rule class=ghunnah>نّ</rule>َىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۖ قُلۡ هُوَ مِنۡ عِ<rule class=ikhafa>ند</rule>ِ أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١٦٥',
    165, 4, 1, 71, 58, 28, 'false'
  );
  
  -- Ayah 166 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    459,
    'وَمَاۤ أَصَـٰبَكُمۡ یَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِیَعۡلَمَ ٱلۡمُؤۡمِنِینَ',
    'وما اصابكم يوم التقى الجمعان فباذن الله وليعلم المؤمنين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَصَ<rule class=madda_normal>ـٰ</rule>بَكُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ۡتَقَى <rule class=ham_wasl>ٱ</rule>لۡجَمۡعَانِ فَبِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلِيَعۡلَمَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٦٦',
    166, 4, 1, 72, 58, 28, 'false'
  );
  
  -- Ayah 167 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    460,
    'وَلِیَعۡلَمَ ٱلَّذِینَ نَافَقُوا۟ۚ وَقِیلَ لَهُمۡ تَعَالَوۡا۟ قَـٰتِلُوا۟ فِی سَبِیلِ ٱللَّهِ أَوِ ٱدۡفَعُوا۟ۖ قَالُوا۟ لَوۡ نَعۡلَمُ قِتَالࣰا لَّٱتَّبَعۡنَـٰكُمۡۗ هُمۡ لِلۡكُفۡرِ یَوۡمَىِٕذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِیمَـٰنِۚ یَقُولُونَ بِأَفۡوَ ٰ⁠هِهِم مَّا لَیۡسَ فِی قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا یَكۡتُمُونَ',
    'وليعلم الذين نافقوا وقيل لهم تعالوا قاتلوا في سبيل الله او ادفعوا قالوا لو نعلم قتالا لاتبعناكم هم للكفر يومئذ اقرب منهم للايمان يقولون بافواههم ما ليس في قلوبهم والله اعلم بما يكتمون',
    'وَلِيَعۡلَمَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ نَافَقُو<rule class=slnt>اۡ‌ۚ</rule> وَقِيلَ لَهُمۡ تَعَالَوۡ<rule class=slnt>اۡ</rule> قَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>فَعُو<rule class=slnt>اۡ‌ۖ</rule> قَالُو<rule class=slnt>اۡ</rule> لَوۡ نَعۡلَمُ قِتَال<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ham_wasl>ٱ</rule>تَّبَعۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۗ هُمۡ لِلۡكُفۡرِ يَوۡمَئِذٍ أَ<rule class=qalaqah>قۡ</rule>رَبُ مِنۡهُمۡ لِلۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ يَقُولُونَ بِأَفۡو<rule class=madda_normal>ٰ</rule>هِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا لَيۡسَ فِى قُلُوبِهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِمَا يَكۡتُم<rule class=madda_permissible>ُو</rule>نَ ١٦٧',
    167, 4, 1, 72, 58, 28, 'false'
  );
  
  -- Ayah 168 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    461,
    'ٱلَّذِینَ قَالُوا۟ لِإِخۡوَ ٰ⁠نِهِمۡ وَقَعَدُوا۟ لَوۡ أَطَاعُونَا مَا قُتِلُوا۟ۗ قُلۡ فَٱدۡرَءُوا۟ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَـٰدِقِینَ',
    'الذين قالوا لاخوانهم وقعدوا لو اطاعونا ما قتلوا قل فادرءوا عن انفسكم الموت ان كنتم صادقين',
    'ٱلَّذِينَ قَالُو<rule class=slnt>اۡ</rule> لِإِخۡو<rule class=madda_normal>ٰ</rule>نِهِمۡ وَقَعَدُو<rule class=slnt>اۡ</rule> لَوۡ أَطَاعُونَا مَا قُتِلُو<rule class=slnt>اۡ‌ۗ</rule> قُلۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>رَءُو<rule class=slnt>اۡ</rule> عَنۡ أَ<rule class=ikhafa>نف</rule>ُسِكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٦٨',
    168, 4, 1, 72, 58, 28, 'false'
  );
  
  -- Ayah 169 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    462,
    'وَلَا تَحۡسَبَنَّ ٱلَّذِینَ قُتِلُوا۟ فِی سَبِیلِ ٱللَّهِ أَمۡوَ ٰ⁠تَۢاۚ بَلۡ أَحۡیَاۤءٌ عِندَ رَبِّهِمۡ یُرۡزَقُونَ',
    'ولا تحسبن الذين قتلوا في سبيل الله امواتا بل احياء عند ربهم يرزقون',
    'وَلَا تَحۡسَبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قُتِلُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَمۡو<rule class=madda_normal>ٰ</rule>ت<rule class=iqlab>َۢا‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ أَحۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ يُرۡزَق<rule class=madda_permissible>ُو</rule>نَ ١٦٩',
    169, 4, 1, 72, 58, 28, 'false'
  );
  
  -- Ayah 170 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    463,
    'فَرِحِینَ بِمَاۤ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَیَسۡتَبۡشِرُونَ بِٱلَّذِینَ لَمۡ یَلۡحَقُوا۟ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'فرحين بما اتاهم الله من فضله ويستبشرون بالذين لم يلحقوا بهم من خلفهم الا خوف عليهم ولا هم يحزنون',
    'فَرِحِينَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> وَيَسۡتَ<rule class=qalaqah>بۡ</rule>شِرُونَ بِ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَمۡ يَلۡحَقُو<rule class=slnt>اۡ</rule> بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ١٧٠',
    170, 4, 1, 72, 58, 28, 'false'
  );
  
  -- Ayah 171 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    464,
    '۞ یَسۡتَبۡشِرُونَ بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ وَأَنَّ ٱللَّهَ لَا یُضِیعُ أَجۡرَ ٱلۡمُؤۡمِنِینَ',
    'يستبشرون بنعمة من الله وفضل وان الله لا يضيع اجر المؤمنين',
    '۞يَسۡتَ<rule class=qalaqah>بۡ</rule>شِرُونَ بِنِعۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَفَضۡ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُضِيعُ أَ<rule class=qalaqah>جۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٧١',
    171, 4, 1, 72, 58, 29, 'false'
  );
  
  -- Ayah 172 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    465,
    'ٱلَّذِینَ ٱسۡتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَاۤ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِینَ أَحۡسَنُوا۟ مِنۡهُمۡ وَٱتَّقَوۡا۟ أَجۡرٌ عَظِیمٌ',
    'الذين استجابوا لله والرسول من بعد ما اصابهم القرح للذين احسنوا منهم واتقوا اجر عظيم',
    'ٱلَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَجَابُو<rule class=slnt>اۡ</rule> لِلَّهِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ م<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَهُمُ <rule class=ham_wasl>ٱ</rule>لۡقَرۡحُ‌ۚ لِلَّذِينَ أَحۡسَنُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ وَ<rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>جۡ</rule>رٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٧٢',
    172, 4, 1, 72, 59, 29, 'false'
  );
  
  -- Ayah 173 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    466,
    'ٱلَّذِینَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُوا۟ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِیمَـٰنࣰا وَقَالُوا۟ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِیلُ',
    'الذين قال لهم الناس ان الناس قد جمعوا لكم فاخشوهم فزادهم ايمانا وقالوا حسبنا الله ونعم الوكيل',
    'ٱلَّذِينَ قَالَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ قَ<rule class=qalaqah>دۡ</rule> جَمَعُو<rule class=slnt>اۡ</rule> لَكُمۡ فَ<rule class=ham_wasl>ٱ</rule>خۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َقَالُو<rule class=slnt>اۡ</rule> حَسۡبُنَا <rule class=ham_wasl>ٱ</rule>للَّهُ وَنِعۡمَ <rule class=ham_wasl>ٱ</rule>لۡوَك<rule class=madda_permissible>ِي</rule>لُ ١٧٣',
    173, 4, 1, 72, 59, 29, 'false'
  );
  
  -- Ayah 174 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    467,
    'فَٱنقَلَبُوا۟ بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ لَّمۡ یَمۡسَسۡهُمۡ سُوۤءࣱ وَٱتَّبَعُوا۟ رِضۡوَ ٰ⁠نَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِیمٍ',
    'فانقلبوا بنعمة من الله وفضل لم يمسسهم سوء واتبعوا رضوان الله والله ذو فضل عظيم',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>َلَبُو<rule class=slnt>اۡ</rule> بِنِعۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَفَضۡ<rule class=idgham_wo_ghunnah>لٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَمۡسَسۡهُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> رِضۡو<rule class=madda_normal>ٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ ذُو فَضۡلٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ١٧٤',
    174, 4, 1, 73, 59, 29, 'false'
  );
  
  -- Ayah 175 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    468,
    'إِنَّمَا ذَ ٰ⁠لِكُمُ ٱلشَّیۡطَـٰنُ یُخَوِّفُ أَوۡلِیَاۤءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِینَ',
    'انما ذلكم الشيطان يخوف اولياءه فلا تخافوهم وخافون ان كنتم مؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َمَا ذ<rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ يُخَوِّفُ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_normal>ۥ</rule> فَلَا تَخَافُوهُمۡ وَخَافُونِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٧٥',
    175, 4, 1, 73, 59, 29, 'false'
  );
  
  -- Ayah 176 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    469,
    'وَلَا یَحۡزُنكَ ٱلَّذِینَ یُسَـٰرِعُونَ فِی ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن یَضُرُّوا۟ ٱللَّهَ شَیۡـࣰٔاۗ یُرِیدُ ٱللَّهُ أَلَّا یَجۡعَلَ لَهُمۡ حَظࣰّا فِی ٱلۡـَٔاخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِیمٌ',
    'ولا يحزنك الذين يسارعون في الكفر انهم لن يضروا الله شيئا يريد الله الا يجعل لهم حظا في الاخرة ولهم عذاب عظيم',
    'وَلَا يَحۡزُ<rule class=ikhafa>نك</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُسَ<rule class=madda_normal>ـٰ</rule>رِعُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُمۡ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضُرُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۗ</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ أَلَّا يَ<rule class=qalaqah>جۡ</rule>عَلَ لَهُمۡ حَظ<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ وَلَهُمۡ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٧٦',
    176, 4, 1, 73, 59, 29, 'false'
  );
  
  -- Ayah 177 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    470,
    'إِنَّ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلۡكُفۡرَ بِٱلۡإِیمَـٰنِ لَن یَضُرُّوا۟ ٱللَّهَ شَیۡـࣰٔاۖ وَلَهُمۡ عَذَابٌ أَلِیمࣱ',
    'ان الذين اشتروا الكفر بالايمان لن يضروا الله شيئا ولهم عذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>شۡتَرَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكُفۡرَ بِ<rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضُرُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١٧٧',
    177, 4, 1, 73, 59, 29, 'false'
  );
  
  -- Ayah 178 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    471,
    'وَلَا یَحۡسَبَنَّ ٱلَّذِینَ كَفَرُوۤا۟ أَنَّمَا نُمۡلِی لَهُمۡ خَیۡرࣱ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِی لَهُمۡ لِیَزۡدَادُوۤا۟ إِثۡمࣰاۖ وَلَهُمۡ عَذَابࣱ مُّهِینࣱ',
    'ولا يحسبن الذين كفروا انما نملي لهم خير لانفسهم انما نملي لهم ليزدادوا اثما ولهم عذاب مهين',
    'وَلَا يَحۡسَبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َمَا نُمۡلِى لَهُمۡ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َمَا نُمۡلِى لَهُمۡ لِيَزۡدَاد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِثۡ<rule class=idgham_ghunnah>مًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّه<rule class=madda_permissible>ِي</rule>نٌ ١٧٨',
    178, 4, 1, 73, 59, 29, 'false'
  );
  
  -- Ayah 179 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    472,
    'مَّا كَانَ ٱللَّهُ لِیَذَرَ ٱلۡمُؤۡمِنِینَ عَلَىٰ مَاۤ أَنتُمۡ عَلَیۡهِ حَتَّىٰ یَمِیزَ ٱلۡخَبِیثَ مِنَ ٱلطَّیِّبِۗ وَمَا كَانَ ٱللَّهُ لِیُطۡلِعَكُمۡ عَلَى ٱلۡغَیۡبِ وَلَـٰكِنَّ ٱللَّهَ یَجۡتَبِی مِن رُّسُلِهِۦ مَن یَشَاۤءُۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمۡ أَجۡرٌ عَظِیمࣱ',
    'ما كان الله ليذر المؤمنين على ما انتم عليه حتى يميز الخبيث من الطيب وما كان الله ليطلعكم على الغيب ولكن الله يجتبي من رسله من يشاء فامنوا بالله ورسله وان تؤمنوا وتتقوا فلكم اجر عظيم',
    'مَّا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيَذَرَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ عَلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ عَلَيۡهِ حَتَّىٰ يَمِيزَ <rule class=ham_wasl>ٱ</rule>لۡخَبِيثَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبِ‌ۗ وَمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيُ<rule class=qalaqah>طۡ</rule>لِعَكُمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>جۡ</rule>تَبِى م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّسُلِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ فَـَٔـامِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرُسُلِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُؤۡمِنُو<rule class=slnt>اۡ</rule> وَتَتَّقُو<rule class=slnt>اۡ</rule> فَلَكُمۡ أَ<rule class=qalaqah>جۡ</rule>رٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٧٩',
    179, 4, 1, 73, 59, 29, 'false'
  );
  
  -- Ayah 180 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    473,
    'وَلَا یَحۡسَبَنَّ ٱلَّذِینَ یَبۡخَلُونَ بِمَاۤ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَیۡرࣰا لَّهُمۖ بَلۡ هُوَ شَرࣱّ لَّهُمۡۖ سَیُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ یَوۡمَ ٱلۡقِیَـٰمَةِۗ وَلِلَّهِ مِیرَ ٰ⁠ثُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ',
    'ولا يحسبن الذين يبخلون بما اتاهم الله من فضله هو خيرا لهم بل هو شر لهم سيطوقون ما بخلوا به يوم القيامة ولله ميراث السماوات والارض والله بما تعملون خبير',
    'وَلَا يَحۡسَبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>بۡ</rule>خَلُونَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> هُوَ خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّه<rule class=ikhafa_shafawi>ُم‌ۖ</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ هُوَ شَ<rule class=idgham_wo_ghunnah>رٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ‌ۖ سَيُطَوَّقُونَ مَا بَخِلُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ وَلِلَّهِ مِير<rule class=madda_normal>ٰ</rule>ثُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ١٨٠',
    180, 4, 1, 73, 59, 29, 'false'
  );
  
  -- Ayah 181 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    474,
    'لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ فَقِیرࣱ وَنَحۡنُ أَغۡنِیَاۤءُۘ سَنَكۡتُبُ مَا قَالُوا۟ وَقَتۡلَهُمُ ٱلۡأَنۢبِیَاۤءَ بِغَیۡرِ حَقࣲّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلۡحَرِیقِ',
    'لقد سمع الله قول الذين قالوا ان الله فقير ونحن اغنياء سنكتب ما قالوا وقتلهم الانبياء بغير حق ونقول ذوقوا عذاب الحريق',
    'لَّقَ<rule class=qalaqah>دۡ</rule> سَمِعَ <rule class=ham_wasl>ٱ</rule>للَّهُ قَوۡلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ فَقِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َنَحۡنُ أَغۡنِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۘ سَنَكۡتُبُ مَا قَالُو<rule class=slnt>اۡ</rule> وَقَتۡلَهُمُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=iqlab>نۢب</rule>ِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِغَيۡرِ حَ<rule class=idgham_ghunnah>قٍّ</rule> <rule class=idgham_ghunnah>و</rule>َنَقُولُ ذُوقُو<rule class=slnt>اۡ</rule> عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡحَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ِ ١٨١',
    181, 4, 1, 74, 60, 29, 'false'
  );
  
  -- Ayah 182 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    475,
    'ذَ ٰ⁠لِكَ بِمَا قَدَّمَتۡ أَیۡدِیكُمۡ وَأَنَّ ٱللَّهَ لَیۡسَ بِظَلَّامࣲ لِّلۡعَبِیدِ',
    'ذلك بما قدمت ايديكم وان الله ليس بظلام للعبيد',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَيۡسَ بِظَلَّا<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَب<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ١٨٢',
    182, 4, 1, 74, 60, 29, 'false'
  );
  
  -- Ayah 183 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    476,
    'ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَیۡنَاۤ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ یَأۡتِیَنَا بِقُرۡبَانࣲ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَاۤءَكُمۡ رُسُلࣱ مِّن قَبۡلِی بِٱلۡبَیِّنَـٰتِ وَبِٱلَّذِی قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَـٰدِقِینَ',
    'الذين قالوا ان الله عهد الينا الا نؤمن لرسول حتى ياتينا بقربان تاكله النار قل قد جاءكم رسل من قبلي بالبينات وبالذي قلتم فلم قتلتموهم ان كنتم صادقين',
    'ٱلَّذِينَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَهِدَ إِلَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ يَأۡتِيَنَا بِقُرۡبَا<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ت</rule>َأۡكُلُهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ‌ۗ قُلۡ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ رُسُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِى بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَبِ<rule class=ham_wasl>ٱ</rule>لَّذِى قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٨٣',
    183, 4, 1, 74, 60, 29, 'false'
  );
  
  -- Ayah 184 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    477,
    'فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلࣱ مِّن قَبۡلِكَ جَاۤءُو بِٱلۡبَیِّنَـٰتِ وَٱلزُّبُرِ وَٱلۡكِتَـٰبِ ٱلۡمُنِیرِ',
    'فان كذبوك فقد كذب رسل من قبلك جاءوا بالبينات والزبر والكتاب المنير',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبُوكَ فَقَ<rule class=qalaqah>دۡ</rule> كُذِّبَ رُسُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زُّبُرِ وَ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡمُن<rule class=madda_permissible>ِي</rule>رِ ١٨٤',
    184, 4, 1, 74, 60, 29, 'false'
  );
  
  -- Ayah 185 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    478,
    'كُلُّ نَفۡسࣲ ذَاۤىِٕقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا مَتَـٰعُ ٱلۡغُرُورِ',
    'كل نفس ذائقة الموت وانما توفون اجوركم يوم القيامة فمن زحزح عن النار وادخل الجنة فقد فاز وما الحياة الدنيا الا متاع الغرور',
    'كُلُّ نَفۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِقَةُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َمَا تُوَفَّوۡنَ أُجُورَكُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۖ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>ُحۡزِحَ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ وَأُ<rule class=qalaqah>دۡ</rule>خِلَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ فَقَ<rule class=qalaqah>دۡ</rule> فَازَ‌ۗ وَمَا <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡي<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا مَتَ<rule class=madda_normal>ـٰ</rule>عُ <rule class=ham_wasl>ٱ</rule>لۡغُر<rule class=madda_permissible>ُو</rule>رِ ١٨٥',
    185, 4, 1, 74, 60, 29, 'false'
  );
  
  -- Ayah 186 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    479,
    '۞ لَتُبۡلَوُنَّ فِیۤ أَمۡوَ ٰ⁠لِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِینَ أَشۡرَكُوۤا۟ أَذࣰى كَثِیرࣰاۚ وَإِن تَصۡبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَ ٰ⁠لِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ',
    'لتبلون في اموالكم وانفسكم ولتسمعن من الذين اوتوا الكتاب من قبلكم ومن الذين اشركوا اذى كثيرا وان تصبروا وتتقوا فان ذلك من عزم الامور',
    '۞لَتُ<rule class=qalaqah>بۡ</rule>لَوُ<rule class=ghunnah>نّ</rule>َ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لِكُمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِكُمۡ وَلَتَسۡمَعُ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ وَمِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَشۡرَك<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ذًى</rule> <rule class=ikhafa>ك</rule>َثِي<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصۡبِرُو<rule class=slnt>اۡ</rule> وَتَتَّقُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ مِنۡ عَزۡمِ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رِ ١٨٦',
    186, 4, 1, 74, 60, 30, 'false'
  );
  
  -- Ayah 187 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    480,
    'وَإِذۡ أَخَذَ ٱللَّهُ مِیثَـٰقَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ لَتُبَیِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَاۤءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡا۟ بِهِۦ ثَمَنࣰا قَلِیلࣰاۖ فَبِئۡسَ مَا یَشۡتَرُونَ',
    'واذ اخذ الله ميثاق الذين اوتوا الكتاب لتبيننه للناس ولا تكتمونه فنبذوه وراء ظهورهم واشتروا به ثمنا قليلا فبئس ما يشترون',
    'وَإِذۡ أَخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِيثَ<rule class=madda_normal>ـٰ</rule>قَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ لَتُبَيِّنُ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لِل<rule class=ghunnah>نّ</rule>َاسِ وَلَا تَكۡتُمُونَهُ<rule class=madda_normal>ۥ</rule> فَنَبَذُوهُ وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ظُهُورِهِمۡ وَ<rule class=ham_wasl>ٱ</rule>شۡتَرَوۡ<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيل<rule class=ikhafa>اً‌ۖ</rule> <rule class=ikhafa>ف</rule>َبِئۡسَ مَا يَشۡتَر<rule class=madda_permissible>ُو</rule>نَ ١٨٧',
    187, 4, 1, 75, 60, 30, 'false'
  );
  
  -- Ayah 188 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    481,
    'لَا تَحۡسَبَنَّ ٱلَّذِینَ یَفۡرَحُونَ بِمَاۤ أَتَوا۟ وَّیُحِبُّونَ أَن یُحۡمَدُوا۟ بِمَا لَمۡ یَفۡعَلُوا۟ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةࣲ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِیمࣱ',
    'لا تحسبن الذين يفرحون بما اتوا ويحبون ان يحمدوا بما لم يفعلوا فلا تحسبنهم بمفازة من العذاب ولهم عذاب اليم',
    'لَا تَحۡسَبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَفۡرَحُونَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَتَو<rule class=slnt>اۡ</rule> وَّيُحِبُّونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحۡمَدُو<rule class=slnt>اۡ</rule> بِمَا لَمۡ يَفۡعَلُو<rule class=slnt>اۡ</rule> فَلَا تَحۡسَبَ<rule class=ghunnah>نّ</rule>َه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَفَازَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ‌ۖ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١٨٨',
    188, 4, 1, 75, 60, 30, 'false'
  );
  
  -- Ayah 189 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    482,
    'وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'ولله ملك السماوات والارض والله على كل شيء قدير',
    'وَلِلَّهِ مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١٨٩',
    189, 4, 1, 75, 60, 30, 'false'
  );
  
  -- Ayah 190 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    483,
    'إِنَّ فِی خَلۡقِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَٱخۡتِلَـٰفِ ٱلَّیۡلِ وَٱلنَّهَارِ لَـَٔایَـٰتࣲ لِّأُو۟لِی ٱلۡأَلۡبَـٰبِ',
    'ان في خلق السماوات والارض واختلاف الليل والنهار لايات لاولي الالباب',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى خَلۡقِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule>خۡتِلَ<rule class=madda_normal>ـٰ</rule>فِ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ١٩٠',
    190, 4, 1, 75, 61, 30, 'false'
  );
  
  -- Ayah 191 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    484,
    'ٱلَّذِینَ یَذۡكُرُونَ ٱللَّهَ قِیَـٰمࣰا وَقُعُودࣰا وَعَلَىٰ جُنُوبِهِمۡ وَیَتَفَكَّرُونَ فِی خَلۡقِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَـٰذَا بَـٰطِلࣰا سُبۡحَـٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ',
    'الذين يذكرون الله قياما وقعودا وعلى جنوبهم ويتفكرون في خلق السماوات والارض ربنا ما خلقت هذا باطلا سبحانك فقنا عذاب النار',
    'ٱلَّذِينَ يَذۡكُرُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ قِيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َقُعُو<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َعَلَىٰ جُنُوبِهِمۡ وَيَتَفَكَّرُونَ فِى خَلۡقِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ رَبَّنَا مَا خَلَ<rule class=qalaqah>قۡ</rule>تَ هَ<rule class=madda_normal>ـٰ</rule>ذَا بَ<rule class=madda_normal>ـٰ</rule>طِل<rule class=ikhafa>اً</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ فَقِنَا عَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ١٩١',
    191, 4, 1, 75, 61, 30, 'false'
  );
  
  -- Ayah 192 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    485,
    'رَبَّنَاۤ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَیۡتَهُۥۖ وَمَا لِلظَّـٰلِمِینَ مِنۡ أَنصَارࣲ',
    'ربنا انك من تدخل النار فقد اخزيته وما للظالمين من انصار',
    'رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>دۡ</rule>خِلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ فَقَ<rule class=qalaqah>دۡ</rule> أَخۡزَيۡتَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَمَا لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ مِنۡ أَ<rule class=ikhafa>نص</rule><rule class=madda_permissible>َا</rule>رٍ ١٩٢',
    192, 4, 1, 75, 61, 30, 'false'
  );
  
  -- Ayah 193 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    486,
    'رَّبَّنَاۤ إِنَّنَا سَمِعۡنَا مُنَادِیࣰا یُنَادِی لِلۡإِیمَـٰنِ أَنۡ ءَامِنُوا۟ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَیِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ',
    'ربنا اننا سمعنا مناديا ينادي للايمان ان امنوا بربكم فامنا ربنا فاغفر لنا ذنوبنا وكفر عنا سيئاتنا وتوفنا مع الابرار',
    'رَّبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َنَا سَمِعۡنَا مُنَادِ<rule class=idgham_ghunnah>يًا</rule> <rule class=idgham_ghunnah>ي</rule>ُنَادِى لِلۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ أَنۡ ءَامِنُو<rule class=slnt>اۡ</rule> بِرَبِّكُمۡ فَـَٔـامَ<rule class=ghunnah>نّ</rule>َا‌ۚ رَبَّنَا فَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَ<rule class=ghunnah>نّ</rule>َا سَيِّـَٔـاتِنَا وَتَوَفَّنَا مَعَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_permissible>َا</rule>رِ ١٩٣',
    193, 4, 1, 75, 61, 30, 'false'
  );
  
  -- Ayah 194 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    487,
    'رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا یَوۡمَ ٱلۡقِیَـٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِیعَادَ',
    'ربنا واتنا ما وعدتنا على رسلك ولا تخزنا يوم القيامة انك لا تخلف الميعاد',
    'رَبَّنَا وَءَاتِنَا مَا وَعَ<rule class=idgham_mutajanisayn>د</rule>تَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َكَ لَا تُخۡلِفُ <rule class=ham_wasl>ٱ</rule>لۡمِيع<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>َ ١٩٤',
    194, 4, 1, 75, 61, 30, 'false'
  );
  
  -- Ayah 195 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    488,
    'فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّی لَاۤ أُضِیعُ عَمَلَ عَـٰمِلࣲ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضࣲۖ فَٱلَّذِینَ هَاجَرُوا۟ وَأُخۡرِجُوا۟ مِن دِیَـٰرِهِمۡ وَأُوذُوا۟ فِی سَبِیلِی وَقَـٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ ثَوَابࣰا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ',
    'فاستجاب لهم ربهم اني لا اضيع عمل عامل منكم من ذكر او انثى بعضكم من بعض فالذين هاجروا واخرجوا من ديارهم واوذوا في سبيلي وقاتلوا وقتلوا لاكفرن عنهم سيئاتهم ولادخلنهم جنات تجري من تحتها الانهار ثوابا من عند الله والله عنده حسن الثواب',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَ<rule class=ghunnah>نّ</rule>ِى ل<rule class=madda_obligatory_monfasel>َآ</rule> أُضِيعُ عَمَلَ عَ<rule class=madda_normal>ـٰ</rule>مِ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َكَرٍ أَوۡ أُ<rule class=ikhafa>نث</rule>َىٰ‌ۖ بَعۡضُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡ<rule class=ikhafa>ضٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هَاجَرُو<rule class=slnt>اۡ</rule> وَأُخۡرِجُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ وَأُوذُو<rule class=slnt>اۡ</rule> فِى سَبِيلِى وَقَ<rule class=madda_normal>ـٰ</rule>تَلُو<rule class=slnt>اۡ</rule> وَقُتِلُو<rule class=slnt>اۡ</rule> لَأُكَفِّرَ<rule class=ghunnah>نّ</rule>َ عَنۡهُمۡ سَيِّـَٔـاتِهِمۡ وَلَأُ<rule class=qalaqah>دۡ</rule>خِلَ<rule class=ghunnah>نّ</rule>َهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ ثَوَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> حُسۡنُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّو<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٩٥',
    195, 4, 1, 76, 61, 30, 'false'
  );
  
  -- Ayah 196 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    489,
    'لَا یَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِینَ كَفَرُوا۟ فِی ٱلۡبِلَـٰدِ',
    'لا يغرنك تقلب الذين كفروا في البلاد',
    'لَا يَغُرَّ<rule class=ghunnah>نّ</rule>َكَ تَقَلُّبُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡبِلَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>د</rule>ِ ١٩٦',
    196, 4, 1, 76, 61, 30, 'false'
  );
  
  -- Ayah 197 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    490,
    'مَتَـٰعࣱ قَلِیلࣱ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ',
    'متاع قليل ثم ماواهم جهنم وبئس المهاد',
    'مَتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>عٌ</rule> <rule class=ikhafa>ق</rule>َلِي<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ مَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۚ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمِه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ُ ١٩٧',
    197, 4, 1, 76, 61, 30, 'false'
  );
  
  -- Ayah 198 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    491,
    'لَـٰكِنِ ٱلَّذِینَ ٱتَّقَوۡا۟ رَبَّهُمۡ لَهُمۡ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا نُزُلࣰا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَیۡرࣱ لِّلۡأَبۡرَارِ',
    'لكن الذين اتقوا ربهم لهم جنات تجري من تحتها الانهار خالدين فيها نزلا من عند الله وما عند الله خير للابرار',
    'لَ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> رَبَّهُمۡ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا نُزُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَمَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡأَ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_permissible>َا</rule>رِ ١٩٨',
    198, 4, 1, 76, 61, 30, 'false'
  );
  
  -- Ayah 199 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    492,
    'وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَمَن یُؤۡمِنُ بِٱللَّهِ وَمَاۤ أُنزِلَ إِلَیۡكُمۡ وَمَاۤ أُنزِلَ إِلَیۡهِمۡ خَـٰشِعِینَ لِلَّهِ لَا یَشۡتَرُونَ بِـَٔایَـٰتِ ٱللَّهِ ثَمَنࣰا قَلِیلًاۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ',
    'وان من اهل الكتاب لمن يؤمن بالله وما انزل اليكم وما انزل اليهم خاشعين لله لا يشترون بايات الله ثمنا قليلا اولئك لهم اجرهم عند ربهم ان الله سريع الحساب',
    'وَإِ<rule class=ghunnah>نّ</rule>َ مِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكُمۡ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡهِمۡ خَ<rule class=madda_normal>ـٰ</rule>شِعِينَ لِلَّهِ لَا يَشۡتَرُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيلاً‌ۗ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رُهُمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٩٩',
    199, 4, 1, 76, 61, 30, 'false'
  );
  
  -- Ayah 200 Surah Aal-i-Imraan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    3,
    493,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱصۡبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ',
    'يا ايها الذين امنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم تفلحون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>صۡبِرُو<rule class=slnt>اۡ</rule> وَصَابِرُو<rule class=slnt>اۡ</rule> وَرَابِطُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٢٠٠',
    200, 4, 1, 76, 61, 30, 'false'
  );
  

-- Surah An-Nisaa
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (4, 'سُورَةُ النِّسَاءِ', 'An-Nisaa', 'The Women', 'Medinan', 176);

  -- Ayah 1 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    494,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِی خَلَقَكُم مِّن نَّفۡسࣲ وَ ٰ⁠حِدَةࣲ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالࣰا كَثِیرࣰا وَنِسَاۤءࣰۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِی تَسَاۤءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَیۡكُمۡ رَقِیبࣰا',
    'يا ايها الناس اتقوا ربكم الذي خلقكم من نفس واحدة وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا الله الذي تساءلون به والارحام ان الله كان عليكم رقيبا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> رَبَّكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَال<rule class=ikhafa>اً</rule> <rule class=ikhafa>ك</rule>َثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنِس<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذِى تَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَلُونَ بِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡحَامَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلَيۡكُمۡ رَقِيبًا ١',
    1, 4, 1, 77, 62, 31, 'false'
  );
  
  -- Ayah 2 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    495,
    'وَءَاتُوا۟ ٱلۡیَتَـٰمَىٰۤ أَمۡوَ ٰ⁠لَهُمۡۖ وَلَا تَتَبَدَّلُوا۟ ٱلۡخَبِیثَ بِٱلطَّیِّبِۖ وَلَا تَأۡكُلُوۤا۟ أَمۡوَ ٰ⁠لَهُمۡ إِلَىٰۤ أَمۡوَ ٰ⁠لِكُمۡۚ إِنَّهُۥ كَانَ حُوبࣰا كَبِیرࣰا',
    'واتوا اليتامى اموالهم ولا تتبدلوا الخبيث بالطيب ولا تاكلوا اموالهم الى اموالكم انه كان حوبا كبيرا',
    'وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ‌ۖ وَلَا تَتَبَدَّلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَبِيثَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبِ‌ۖ وَلَا تَأۡكُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لِكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ حُو<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٢',
    2, 4, 1, 77, 62, 31, 'false'
  );
  
  -- Ayah 3 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    496,
    'وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُوا۟ فِی ٱلۡیَتَـٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَاۤءِ مَثۡنَىٰ وَثُلَـٰثَ وَرُبَـٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُوا۟ فَوَ ٰ⁠حِدَةً أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُكُمۡۚ ذَ ٰ⁠لِكَ أَدۡنَىٰۤ أَلَّا تَعُولُوا۟',
    'وان خفتم الا تقسطوا في اليتامى فانكحوا ما طاب لكم من النساء مثنى وثلاث ورباع فان خفتم الا تعدلوا فواحدة او ما ملكت ايمانكم ذلك ادنى الا تعولوا',
    'وَإِنۡ خِفۡتُمۡ أَلَّا تُ<rule class=qalaqah>قۡ</rule>سِطُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نك</rule>ِحُو<rule class=slnt>اۡ</rule> مَا طَابَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مَثۡنَىٰ وَثُلَ<rule class=madda_normal>ـٰ</rule>ثَ وَرُبَ<rule class=madda_normal>ـٰ</rule>عَ‌ۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُو<rule class=slnt>اۡ</rule> فَو<rule class=madda_normal>ٰ</rule>حِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُكُمۡ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ أَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَلَّا تَعُولُو<rule class=slnt>اۡ</rule> ٣',
    3, 4, 1, 77, 62, 31, 'false'
  );
  
  -- Ayah 4 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    497,
    'وَءَاتُوا۟ ٱلنِّسَاۤءَ صَدُقَـٰتِهِنَّ نِحۡلَةࣰۚ فَإِن طِبۡنَ لَكُمۡ عَن شَیۡءࣲ مِّنۡهُ نَفۡسࣰا فَكُلُوهُ هَنِیۤـࣰٔا مَّرِیۤـࣰٔا',
    'واتوا النساء صدقاتهن نحلة فان طبن لكم عن شيء منه نفسا فكلوه هنيئا مريئا',
    'وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ صَدُقَ<rule class=madda_normal>ـٰ</rule>تِهِ<rule class=ghunnah>نّ</rule>َ نِحۡلَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>ِ<rule class=qalaqah>بۡ</rule>نَ لَكُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ نَفۡ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ف</rule>َكُلُوهُ هَنِ<rule class=madda_obligatory_mottasel>يٓ</rule>ـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>م</rule>َّرِ<rule class=madda_obligatory_mottasel>يٓ</rule>ــًٔا ٤',
    4, 4, 1, 77, 62, 31, 'false'
  );
  
  -- Ayah 5 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    498,
    'وَلَا تُؤۡتُوا۟ ٱلسُّفَهَاۤءَ أَمۡوَ ٰ⁠لَكُمُ ٱلَّتِی جَعَلَ ٱللَّهُ لَكُمۡ قِیَـٰمࣰا وَٱرۡزُقُوهُمۡ فِیهَا وَٱكۡسُوهُمۡ وَقُولُوا۟ لَهُمۡ قَوۡلࣰا مَّعۡرُوفࣰا',
    'ولا تؤتوا السفهاء اموالكم التي جعل الله لكم قياما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا',
    'وَلَا تُؤۡتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّفَه<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡو<rule class=madda_normal>ٰ</rule>لَكُمُ <rule class=ham_wasl>ٱ</rule>لَّتِى جَعَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ قِيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>رۡزُقُوهُمۡ فِيهَا وَ<rule class=ham_wasl>ٱ</rule>كۡسُوهُمۡ وَقُولُو<rule class=slnt>اۡ</rule> لَهُمۡ قَوۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُوفًا ٥',
    5, 4, 1, 77, 62, 31, 'false'
  );
  
  -- Ayah 6 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    499,
    'وَٱبۡتَلُوا۟ ٱلۡیَتَـٰمَىٰ حَتَّىٰۤ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدࣰا فَٱدۡفَعُوۤا۟ إِلَیۡهِمۡ أَمۡوَ ٰ⁠لَهُمۡۖ وَلَا تَأۡكُلُوهَاۤ إِسۡرَافࣰا وَبِدَارًا أَن یَكۡبَرُوا۟ۚ وَمَن كَانَ غَنِیࣰّا فَلۡیَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِیرࣰا فَلۡیَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَیۡهِمۡ أَمۡوَ ٰ⁠لَهُمۡ فَأَشۡهِدُوا۟ عَلَیۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِیبࣰا',
    'وابتلوا اليتامى حتى اذا بلغوا النكاح فان انستم منهم رشدا فادفعوا اليهم اموالهم ولا تاكلوها اسرافا وبدارا ان يكبروا ومن كان غنيا فليستعفف ومن كان فقيرا فلياكل بالمعروف فاذا دفعتم اليهم اموالهم فاشهدوا عليهم وكفى بالله حسيبا',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا بَلَغُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِكَاحَ فَإِنۡ ءَانَسۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُمۡ رُشۡ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>فَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِمۡ أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ‌ۖ وَلَا تَأۡكُلُوه<rule class=madda_obligatory_monfasel>َآ</rule> إِسۡرَا<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َبِدَارًا أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡبَرُو<rule class=slnt>اۡ‌ۚ</rule> وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ غَنِي<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ف</rule>َلۡيَسۡتَعۡفِفۡ‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ فَقِي<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َلۡيَأۡكُلۡ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ فَأَشۡهِدُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ‌ۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ حَسِيبًا ٦',
    6, 4, 1, 77, 62, 31, 'false'
  );
  
  -- Ayah 7 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    500,
    'لِّلرِّجَالِ نَصِیبࣱ مِّمَّا تَرَكَ ٱلۡوَ ٰ⁠لِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَاۤءِ نَصِیبࣱ مِّمَّا تَرَكَ ٱلۡوَ ٰ⁠لِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِیبࣰا مَّفۡرُوضࣰا',
    'للرجال نصيب مما ترك الوالدان والاقربون وللنساء نصيب مما ترك الوالدان والاقربون مما قل منه او كثر نصيبا مفروضا',
    'لِّلرِّجَالِ نَصِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَرَكَ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِدَانِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>رَبُونَ وَلِل<rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ نَصِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَرَكَ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِدَانِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>رَبُونَ مِ<rule class=ghunnah>مّ</rule>َا قَلَّ مِنۡهُ أَوۡ كَثُرَ‌ۚ نَصِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>َّفۡرُوضًا ٧',
    7, 4, 1, 78, 62, 31, 'false'
  );
  
  -- Ayah 8 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    501,
    'وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُو۟لُوا۟ ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُوا۟ لَهُمۡ قَوۡلࣰا مَّعۡرُوفࣰا',
    'واذا حضر القسمة اولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا',
    'وَإِذَا حَضَرَ <rule class=ham_wasl>ٱ</rule>لۡقِسۡمَةَ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينُ فَ<rule class=ham_wasl>ٱ</rule>رۡزُقُوه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ وَقُولُو<rule class=slnt>اۡ</rule> لَهُمۡ قَوۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُوفًا ٨',
    8, 4, 1, 78, 62, 31, 'false'
  );
  
  -- Ayah 9 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    502,
    'وَلۡیَخۡشَ ٱلَّذِینَ لَوۡ تَرَكُوا۟ مِنۡ خَلۡفِهِمۡ ذُرِّیَّةࣰ ضِعَـٰفًا خَافُوا۟ عَلَیۡهِمۡ فَلۡیَتَّقُوا۟ ٱللَّهَ وَلۡیَقُولُوا۟ قَوۡلࣰا سَدِیدًا',
    'وليخش الذين لو تركوا من خلفهم ذرية ضعافا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا',
    'وَلۡيَخۡشَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَوۡ تَرَكُو<rule class=slnt>اۡ</rule> مِنۡ خَلۡفِهِمۡ ذُرِّيَّ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ض</rule>ِعَ<rule class=madda_normal>ـٰ</rule>فًا خَافُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ فَلۡيَتَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَلۡيَقُولُو<rule class=slnt>اۡ</rule> قَوۡل<rule class=ikhafa>اً</rule> <rule class=ikhafa>س</rule>َدِيدًا ٩',
    9, 4, 1, 78, 62, 31, 'false'
  );
  
  -- Ayah 10 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    503,
    'إِنَّ ٱلَّذِینَ یَأۡكُلُونَ أَمۡوَ ٰ⁠لَ ٱلۡیَتَـٰمَىٰ ظُلۡمًا إِنَّمَا یَأۡكُلُونَ فِی بُطُونِهِمۡ نَارࣰاۖ وَسَیَصۡلَوۡنَ سَعِیرࣰا',
    'ان الذين ياكلون اموال اليتامى ظلما انما ياكلون في بطونهم نارا وسيصلون سعيرا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَأۡكُلُونَ أَمۡو<rule class=madda_normal>ٰ</rule>لَ <rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ ظُلۡمًا إِ<rule class=ghunnah>نّ</rule>َمَا يَأۡكُلُونَ فِى بُطُونِهِمۡ نَا<rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َسَيَصۡلَوۡنَ سَعِيرًا ١٠',
    10, 4, 1, 78, 62, 31, 'false'
  );
  
  -- Ayah 11 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    504,
    'یُوصِیكُمُ ٱللَّهُ فِیۤ أَوۡلَـٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَیَیۡنِۚ فَإِن كُنَّ نِسَاۤءࣰ فَوۡقَ ٱثۡنَتَیۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَ ٰ⁠حِدَةࣰ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَیۡهِ لِكُلِّ وَ ٰ⁠حِدࣲ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدࣱۚ فَإِن لَّمۡ یَكُن لَّهُۥ وَلَدࣱ وَوَرِثَهُۥۤ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥۤ إِخۡوَةࣱ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِیَّةࣲ یُوصِی بِهَاۤ أَوۡ دَیۡنٍۗ ءَابَاۤؤُكُمۡ وَأَبۡنَاۤؤُكُمۡ لَا تَدۡرُونَ أَیُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعࣰاۚ فَرِیضَةࣰ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا',
    'يوصيكم الله في اولادكم للذكر مثل حظ الانثيين فان كن نساء فوق اثنتين فلهن ثلثا ما ترك وان كانت واحدة فلها النصف ولابويه لكل واحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوة فلامه السدس من بعد وصية يوصي بها او دين اباؤكم وابناؤكم لا تدرون ايهم اقرب لكم نفعا فريضة من الله ان الله كان عليما حكيما',
    'يُوصِيكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دِكُمۡ‌ۖ لِلذَّكَرِ مِثۡلُ حَظِّ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َيَيۡنِ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َ نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َوۡقَ <rule class=ham_wasl>ٱ</rule>ثۡنَتَيۡنِ فَلَهُ<rule class=ghunnah>نّ</rule>َ ثُلُثَا مَا تَرَكَ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَتۡ و<rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َلَهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِصۡفُ‌ۚ وَلِأَبَوَيۡهِ لِكُلِّ و<rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّدُسُ مِ<rule class=ghunnah>مّ</rule>َا تَرَكَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ لَهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=ikhafa>دٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َوَرِثَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَبَوَاهُ فَلِأُ<rule class=ghunnah>مّ</rule>ِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثُّلُثُ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِخۡوَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َلِأُ<rule class=ghunnah>مّ</rule>ِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّدُسُ‌ۚ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ وَصِيَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوصِى بِه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ دَيۡنٍ‌ۗ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ وَأَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ لَا تَ<rule class=qalaqah>دۡ</rule>رُونَ أَيُّهُمۡ أَ<rule class=qalaqah>قۡ</rule>رَبُ لَكُمۡ نَفۡ<rule class=ikhafa>عًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َرِيضَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلِيمًا حَكِيمًا ١١',
    11, 4, 1, 78, 63, 31, 'false'
  );
  
  -- Ayah 12 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    505,
    '۞ وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَ ٰ⁠جُكُمۡ إِن لَّمۡ یَكُن لَّهُنَّ وَلَدࣱۚ فَإِن كَانَ لَهُنَّ وَلَدࣱ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِیَّةࣲ یُوصِینَ بِهَاۤ أَوۡ دَیۡنࣲۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ یَكُن لَّكُمۡ وَلَدࣱۚ فَإِن كَانَ لَكُمۡ وَلَدࣱ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِیَّةࣲ تُوصُونَ بِهَاۤ أَوۡ دَیۡنࣲۗ وَإِن كَانَ رَجُلࣱ یُورَثُ كَلَـٰلَةً أَوِ ٱمۡرَأَةࣱ وَلَهُۥۤ أَخٌ أَوۡ أُخۡتࣱ فَلِكُلِّ وَ ٰ⁠حِدࣲ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوۤا۟ أَكۡثَرَ مِن ذَ ٰ⁠لِكَ فَهُمۡ شُرَكَاۤءُ فِی ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِیَّةࣲ یُوصَىٰ بِهَاۤ أَوۡ دَیۡنٍ غَیۡرَ مُضَاۤرࣲّۚ وَصِیَّةࣰ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِیمٌ حَلِیمࣱ',
    'ولكم نصف ما ترك ازواجكم ان لم يكن لهن ولد فان كان لهن ولد فلكم الربع مما تركن من بعد وصية يوصين بها او دين ولهن الربع مما تركتم ان لم يكن لكم ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصية توصون بها او دين وان كان رجل يورث كلالة او امراة وله اخ او اخت فلكل واحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصية يوصى بها او دين غير مضار وصية من الله والله عليم حليم',
    '۞وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡو<rule class=madda_normal>ٰ</rule>جُكُمۡ إ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=ghunnah>نّ</rule>َ وَلَ<rule class=ikhafa>دٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ لَهُ<rule class=ghunnah>نّ</rule>َ وَلَ<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َلَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّبُعُ مِ<rule class=ghunnah>مّ</rule>َا تَرَكۡنَ‌ۚ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ وَصِيَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوصِينَ بِه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ دَيۡ<rule class=idgham_ghunnah>نٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّبُعُ مِ<rule class=ghunnah>مّ</rule>َا تَرَكۡتُمۡ إ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَلَ<rule class=ikhafa>دٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ لَكُمۡ وَلَ<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َلَهُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثُّمُنُ مِ<rule class=ghunnah>مّ</rule>َا تَرَكۡت<rule class=idgham_shafawi>ُم‌ۚ</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ وَصِيَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ت</rule>ُوصُونَ بِه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ دَيۡ<rule class=idgham_ghunnah>نٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ رَجُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُورَثُ كَلَ<rule class=madda_normal>ـٰ</rule>لَةً أَوِ <rule class=ham_wasl>ٱ</rule>مۡرَأَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَخٌ أَوۡ أُخۡ<rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ف</rule>َلِكُلِّ و<rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّدُسُ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَكۡثَرَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ فَهُمۡ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثُّلُثِ‌ۚ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ وَصِيَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوصَىٰ بِه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ دَيۡنٍ غَيۡرَ مُض<rule class=madda_necessary>َا</rule>ٓ<rule class=idgham_ghunnah>رٍّ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َصِيَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَل<rule class=madda_permissible>ِي</rule>مٌ ١٢',
    12, 4, 1, 79, 63, 32, 'false'
  );
  
  -- Ayah 13 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    506,
    'تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ یُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'تلك حدود الله ومن يطع الله ورسوله يدخله جنات تجري من تحتها الانهار خالدين فيها وذلك الفوز العظيم',
    'تِلۡكَ حُدُودُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُطِعِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> يُ<rule class=qalaqah>دۡ</rule>خِلۡهُ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ١٣',
    13, 4, 1, 79, 63, 32, 'false'
  );
  
  -- Ayah 14 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    507,
    'وَمَن یَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَیَتَعَدَّ حُدُودَهُۥ یُدۡخِلۡهُ نَارًا خَـٰلِدࣰا فِیهَا وَلَهُۥ عَذَابࣱ مُّهِینࣱ',
    'ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خالدا فيها وله عذاب مهين',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡصِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> وَيَتَعَدَّ حُدُودَهُ<rule class=madda_normal>ۥ</rule> يُ<rule class=qalaqah>دۡ</rule>خِلۡهُ نَارًا خَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>ِيهَا وَلَهُ<rule class=madda_normal>ۥ</rule> عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّه<rule class=madda_permissible>ِي</rule>نٌ ١٤',
    14, 4, 1, 79, 63, 32, 'false'
  );
  
  -- Ayah 15 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    508,
    'وَٱلَّـٰتِی یَأۡتِینَ ٱلۡفَـٰحِشَةَ مِن نِّسَاۤىِٕكُمۡ فَٱسۡتَشۡهِدُوا۟ عَلَیۡهِنَّ أَرۡبَعَةࣰ مِّنكُمۡۖ فَإِن شَهِدُوا۟ فَأَمۡسِكُوهُنَّ فِی ٱلۡبُیُوتِ حَتَّىٰ یَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ یَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِیلࣰا',
    'واللاتي ياتين الفاحشة من نسائكم فاستشهدوا عليهن اربعة منكم فان شهدوا فامسكوهن في البيوت حتى يتوفاهن الموت او يجعل الله لهن سبيلا',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>تِى يَأۡتِينَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>حِشَةَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ِّس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَشۡهِدُو<rule class=slnt>اۡ</rule> عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ أَرۡبَعَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َهِدُو<rule class=slnt>اۡ</rule> فَأَمۡسِكُوهُ<rule class=ghunnah>نّ</rule>َ فِى <rule class=ham_wasl>ٱ</rule>لۡبُيُوتِ حَتَّىٰ يَتَوَفَّ<rule class=madda_normal>ـٰ</rule>هُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ أَوۡ يَ<rule class=qalaqah>جۡ</rule>عَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُ<rule class=ghunnah>نّ</rule>َ سَبِيلاً ١٥',
    15, 4, 1, 80, 64, 32, 'false'
  );
  
  -- Ayah 16 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    509,
    'وَٱلَّذَانِ یَأۡتِیَـٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُوا۟ عَنۡهُمَاۤۗ إِنَّ ٱللَّهَ كَانَ تَوَّابࣰا رَّحِیمًا',
    'واللذان ياتيانها منكم فاذوهما فان تابا واصلحا فاعرضوا عنهما ان الله كان توابا رحيما',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذَانِ يَأۡتِيَ<rule class=madda_normal>ـٰ</rule>نِهَا مِ<rule class=ikhafa>نك</rule>ُمۡ فَـَٔـاذُوهُمَا‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابَا وَأَصۡلَحَا فَأَعۡرِضُو<rule class=slnt>اۡ</rule> عَنۡهُم<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ تَوَّا<rule class=idgham_wo_ghunnah>بًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ١٦',
    16, 4, 1, 80, 64, 32, 'false'
  );
  
  -- Ayah 17 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    510,
    'إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِینَ یَعۡمَلُونَ ٱلسُّوۤءَ بِجَهَـٰلَةࣲ ثُمَّ یَتُوبُونَ مِن قَرِیبࣲ فَأُو۟لَـٰۤىِٕكَ یَتُوبُ ٱللَّهُ عَلَیۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا',
    'انما التوبة على الله للذين يعملون السوء بجهالة ثم يتوبون من قريب فاولئك يتوب الله عليهم وكان الله عليما حكيما',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡبَةُ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ لِلَّذِينَ يَعۡمَلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ بِجَهَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ يَتُوبُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرِي<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ف</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَتُوبُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمۡ‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمًا حَكِيمًا ١٧',
    17, 4, 1, 80, 64, 32, 'false'
  );
  
  -- Ayah 18 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    511,
    'وَلَیۡسَتِ ٱلتَّوۡبَةُ لِلَّذِینَ یَعۡمَلُونَ ٱلسَّیِّـَٔاتِ حَتَّىٰۤ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّی تُبۡتُ ٱلۡـَٔـٰنَ وَلَا ٱلَّذِینَ یَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُو۟لَـٰۤىِٕكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِیمࣰا',
    'وليست التوبة للذين يعملون السيئات حتى اذا حضر احدهم الموت قال اني تبت الان ولا الذين يموتون وهم كفار اولئك اعتدنا لهم عذابا اليما',
    'وَلَيۡسَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا حَضَرَ أَحَدَهُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ قَالَ إِ<rule class=ghunnah>نّ</rule>ِى تُ<rule class=qalaqah>بۡ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡـَٔ<rule class=madda_normal>ـٰ</rule>نَ وَلَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لَهُمۡ عَذَابًا أَلِيمًا ١٨',
    18, 4, 1, 80, 64, 32, 'false'
  );
  
  -- Ayah 19 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    512,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا یَحِلُّ لَكُمۡ أَن تَرِثُوا۟ ٱلنِّسَاۤءَ كَرۡهࣰاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُوا۟ بِبَعۡضِ مَاۤ ءَاتَیۡتُمُوهُنَّ إِلَّاۤ أَن یَأۡتِینَ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰۤ أَن تَكۡرَهُوا۟ شَیۡـࣰٔا وَیَجۡعَلَ ٱللَّهُ فِیهِ خَیۡرࣰا كَثِیرࣰا',
    'يا ايها الذين امنوا لا يحل لكم ان ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض ما اتيتموهن الا ان ياتين بفاحشة مبينة وعاشروهن بالمعروف فان كرهتموهن فعسى ان تكرهوا شيئا ويجعل الله فيه خيرا كثيرا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا يَحِلُّ لَكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرِثُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ كَرۡ<rule class=idgham_ghunnah>هًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَعۡضُلُوهُ<rule class=ghunnah>نّ</rule>َ لِتَذۡهَبُو<rule class=slnt>اۡ</rule> بِبَعۡضِ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡتُمُوهُ<rule class=ghunnah>نّ</rule>َ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِينَ بِفَ<rule class=madda_normal>ـٰ</rule>حِشَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّبَيِّنَ<rule class=idgham_ghunnah>ةٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َعَاشِرُوهُ<rule class=ghunnah>نّ</rule>َ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َرِهۡتُمُوهُ<rule class=ghunnah>نّ</rule>َ فَعَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكۡرَهُو<rule class=slnt>اۡ</rule> شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َيَ<rule class=qalaqah>جۡ</rule>عَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ فِيهِ خَيۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َثِيرًا ١٩',
    19, 4, 1, 80, 64, 32, 'false'
  );
  
  -- Ayah 20 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    513,
    'وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجࣲ مَّكَانَ زَوۡجࣲ وَءَاتَیۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارࣰا فَلَا تَأۡخُذُوا۟ مِنۡهُ شَیۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَـٰنࣰا وَإِثۡمࣰا مُّبِینࣰا',
    'وان اردتم استبدال زوج مكان زوج واتيتم احداهن قنطارا فلا تاخذوا منه شيئا اتاخذونه بهتانا واثما مبينا',
    'وَإِنۡ أَرَ<rule class=idgham_mutajanisayn>د</rule>تُّمُ <rule class=ham_wasl>ٱ</rule>سۡتِ<rule class=qalaqah>بۡ</rule>دَالَ زَوۡ<rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>م</rule>َّكَانَ زَوۡ<rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>و</rule>َءَاتَيۡتُمۡ إِحۡدَ<rule class=madda_normal>ٮٰ</rule>هُ<rule class=ghunnah>نّ</rule>َ قِ<rule class=ikhafa>نط</rule>َا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َلَا تَأۡخُذُو<rule class=slnt>اۡ</rule> مِنۡهُ شَيۡــًٔا‌ۚ أَتَأۡخُذُونَهُ<rule class=madda_normal>ۥ</rule> بُهۡتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َإِثۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ٢٠',
    20, 4, 1, 81, 64, 32, 'false'
  );
  
  -- Ayah 21 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    514,
    'وَكَیۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضࣲ وَأَخَذۡنَ مِنكُم مِّیثَـٰقًا غَلِیظࣰا',
    'وكيف تاخذونه وقد افضى بعضكم الى بعض واخذن منكم ميثاقا غليظا',
    'وَكَيۡفَ تَأۡخُذُونَهُ<rule class=madda_normal>ۥ</rule> وَقَ<rule class=qalaqah>دۡ</rule> أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَخَذۡنَ مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule>قًا غَلِيظًا ٢١',
    21, 4, 1, 81, 64, 32, 'false'
  );
  
  -- Ayah 22 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    515,
    'وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَاۤؤُكُم مِّنَ ٱلنِّسَاۤءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَـٰحِشَةࣰ وَمَقۡتࣰا وَسَاۤءَ سَبِیلًا',
    'ولا تنكحوا ما نكح اباؤكم من النساء الا ما قد سلف انه كان فاحشة ومقتا وساء سبيلا',
    'وَلَا تَ<rule class=ikhafa>نك</rule>ِحُو<rule class=slnt>اۡ</rule> مَا نَكَحَ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِلَّا مَا قَ<rule class=qalaqah>دۡ</rule> سَلَفَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ فَ<rule class=madda_normal>ـٰ</rule>حِشَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َمَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>تًا</rule> <rule class=idgham_ghunnah>و</rule>َس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ سَبِيلاً ٢٢',
    22, 4, 1, 81, 64, 32, 'false'
  );
  
  -- Ayah 23 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    516,
    'حُرِّمَتۡ عَلَیۡكُمۡ أُمَّهَـٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَ ٰ⁠تُكُمۡ وَعَمَّـٰتُكُمۡ وَخَـٰلَـٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَـٰتُكُمُ ٱلَّـٰتِیۤ أَرۡضَعۡنَكُمۡ وَأَخَوَ ٰ⁠تُكُم مِّنَ ٱلرَّضَـٰعَةِ وَأُمَّهَـٰتُ نِسَاۤىِٕكُمۡ وَرَبَـٰۤىِٕبُكُمُ ٱلَّـٰتِی فِی حُجُورِكُم مِّن نِّسَاۤىِٕكُمُ ٱلَّـٰتِی دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُوا۟ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَیۡكُمۡ وَحَلَـٰۤىِٕلُ أَبۡنَاۤىِٕكُمُ ٱلَّذِینَ مِنۡ أَصۡلَـٰبِكُمۡ وَأَن تَجۡمَعُوا۟ بَیۡنَ ٱلۡأُخۡتَیۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا',
    'حرمت عليكم امهاتكم وبناتكم واخواتكم وعماتكم وخالاتكم وبنات الاخ وبنات الاخت وامهاتكم اللاتي ارضعنكم واخواتكم من الرضاعة وامهات نسائكم وربائبكم اللاتي في حجوركم من نسائكم اللاتي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم وحلائل ابنائكم الذين من اصلابكم وان تجمعوا بين الاختين الا ما قد سلف ان الله كان غفورا رحيما',
    'حُرِّمَتۡ عَلَيۡكُمۡ أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تُكُمۡ وَبَنَاتُكُمۡ وَأَخَو<rule class=madda_normal>ٰ</rule>تُكُمۡ وَعَ<rule class=ghunnah>مّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُكُمۡ وَخَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تُكُمۡ وَبَنَاتُ <rule class=ham_wasl>ٱ</rule>لۡأَخِ وَبَنَاتُ <rule class=ham_wasl>ٱ</rule>لۡأُخۡتِ وَأُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تُكُمُ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>ت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡضَعۡنَكُمۡ وَأَخَو<rule class=madda_normal>ٰ</rule>تُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّضَ<rule class=madda_normal>ـٰ</rule>عَةِ وَأُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تُ نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ وَرَبَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِبُكُمُ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>تِى فِى حُجُورِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ِّس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمُ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>تِى دَخَلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِ<rule class=ghunnah>نّ</rule>َ فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَكُونُو<rule class=slnt>اۡ</rule> دَخَلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِ<rule class=ghunnah>نّ</rule>َ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِلُ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِنۡ أَصۡلَ<rule class=madda_normal>ـٰ</rule>بِكُمۡ وَأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>مَعُو<rule class=slnt>اۡ</rule> بَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡأُخۡتَيۡنِ إِلَّا مَا قَ<rule class=qalaqah>دۡ</rule> سَلَفَ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٢٣',
    23, 4, 1, 81, 65, 32, 'false'
  );
  
  -- Ayah 24 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    517,
    '۞ وَٱلۡمُحۡصَنَـٰتُ مِنَ ٱلنِّسَاۤءِ إِلَّا مَا مَلَكَتۡ أَیۡمَـٰنُكُمۡۖ كِتَـٰبَ ٱللَّهِ عَلَیۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَاۤءَ ذَ ٰ⁠لِكُمۡ أَن تَبۡتَغُوا۟ بِأَمۡوَ ٰ⁠لِكُم مُّحۡصِنِینَ غَیۡرَ مُسَـٰفِحِینَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِیضَةࣰۚ وَلَا جُنَاحَ عَلَیۡكُمۡ فِیمَا تَرَ ٰ⁠ضَیۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِیضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا',
    'والمحصنات من النساء الا ما ملكت ايمانكم كتاب الله عليكم واحل لكم ما وراء ذلكم ان تبتغوا باموالكم محصنين غير مسافحين فما استمتعتم به منهن فاتوهن اجورهن فريضة ولا جناح عليكم فيما تراضيتم به من بعد الفريضة ان الله كان عليما حكيما',
    '۞وَ<rule class=ham_wasl>ٱ</rule>لۡمُحۡصَنَ<rule class=madda_normal>ـٰ</rule>تُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِلَّا مَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُكُمۡ‌ۖ كِتَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ‌ۚ وَأُحِلَّ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> بِأَمۡو<rule class=madda_normal>ٰ</rule>لِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّحۡصِنِينَ غَيۡرَ مُسَ<rule class=madda_normal>ـٰ</rule>فِحِينَ‌ۚ فَمَا <rule class=ham_wasl>ٱ</rule>سۡتَمۡتَعۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مِنۡهُ<rule class=ghunnah>نّ</rule>َ فَـَٔـاتُوهُ<rule class=ghunnah>نّ</rule>َ أُجُورَهُ<rule class=ghunnah>نّ</rule>َ فَرِيضَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَر<rule class=madda_normal>ٰ</rule>ضَيۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ <rule class=ham_wasl>ٱ</rule>لۡفَرِيضَةِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلِيمًا حَكِيمًا ٢٤',
    24, 5, 1, 82, 65, 33, 'false'
  );
  
  -- Ayah 25 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    518,
    'وَمَن لَّمۡ یَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن یَنكِحَ ٱلۡمُحۡصَنَـٰتِ ٱلۡمُؤۡمِنَـٰتِ فَمِن مَّا مَلَكَتۡ أَیۡمَـٰنُكُم مِّن فَتَیَـٰتِكُمُ ٱلۡمُؤۡمِنَـٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِیمَـٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضࣲۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَـٰتٍ غَیۡرَ مُسَـٰفِحَـٰتࣲ وَلَا مُتَّخِذَ ٰ⁠تِ أَخۡدَانࣲۚ فَإِذَاۤ أُحۡصِنَّ فَإِنۡ أَتَیۡنَ بِفَـٰحِشَةࣲ فَعَلَیۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَـٰتِ مِنَ ٱلۡعَذَابِۚ ذَ ٰ⁠لِكَ لِمَنۡ خَشِیَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُوا۟ خَیۡرࣱ لَّكُمۡۗ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'ومن لم يستطع منكم طولا ان ينكح المحصنات المؤمنات فمن ما ملكت ايمانكم من فتياتكم المؤمنات والله اعلم بايمانكم بعضكم من بعض فانكحوهن باذن اهلهن واتوهن اجورهن بالمعروف محصنات غير مسافحات ولا متخذات اخدان فاذا احصن فان اتين بفاحشة فعليهن نصف ما على المحصنات من العذاب ذلك لمن خشي العنت منكم وان تصبروا خير لكم والله غفور رحيم',
    'وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَسۡتَطِعۡ مِ<rule class=ikhafa>نك</rule>ُمۡ طَوۡلاً أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نك</rule>ِحَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡصَنَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ فَم<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َتَيَ<rule class=madda_normal>ـٰ</rule>تِكُمُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِإِيمَ<rule class=madda_normal>ـٰ</rule>نِك<rule class=ikhafa_shafawi>ُم‌ۚ</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡ<rule class=ikhafa>ضٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نك</rule>ِحُوهُ<rule class=ghunnah>نّ</rule>َ بِإِذۡنِ أَهۡلِهِ<rule class=ghunnah>نّ</rule>َ وَءَاتُوهُ<rule class=ghunnah>نّ</rule>َ أُجُورَهُ<rule class=ghunnah>نّ</rule>َ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ مُحۡصَنَ<rule class=madda_normal>ـٰ</rule>تٍ غَيۡرَ مُسَ<rule class=madda_normal>ـٰ</rule>فِحَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا مُتَّخِذ<rule class=madda_normal>ٰ</rule>تِ أَخۡدَا<rule class=ikhafa>نٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أُحۡصِ<rule class=ghunnah>نّ</rule>َ فَإِنۡ أَتَيۡنَ بِفَ<rule class=madda_normal>ـٰ</rule>حِشَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َعَلَيۡهِ<rule class=ghunnah>نّ</rule>َ نِصۡفُ مَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُحۡصَنَ<rule class=madda_normal>ـٰ</rule>تِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ لِمَنۡ خَشِىَ <rule class=ham_wasl>ٱ</rule>لۡعَنَتَ مِ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ وَأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصۡبِرُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٢٥',
    25, 5, 1, 82, 65, 33, 'false'
  );
  
  -- Ayah 26 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    519,
    'یُرِیدُ ٱللَّهُ لِیُبَیِّنَ لَكُمۡ وَیَهۡدِیَكُمۡ سُنَنَ ٱلَّذِینَ مِن قَبۡلِكُمۡ وَیَتُوبَ عَلَیۡكُمۡۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'يريد الله ليبين لكم ويهديكم سنن الذين من قبلكم ويتوب عليكم والله عليم حكيم',
    'يُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ وَيَتُوبَ عَلَيۡكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٢٦',
    26, 5, 1, 82, 66, 33, 'false'
  );
  
  -- Ayah 27 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    520,
    'وَٱللَّهُ یُرِیدُ أَن یَتُوبَ عَلَیۡكُمۡ وَیُرِیدُ ٱلَّذِینَ یَتَّبِعُونَ ٱلشَّهَوَ ٰ⁠تِ أَن تَمِیلُوا۟ مَیۡلًا عَظِیمࣰا',
    'والله يريد ان يتوب عليكم ويريد الذين يتبعون الشهوات ان تميلوا ميلا عظيما',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتُوبَ عَلَيۡكُمۡ وَيُرِيدُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَتَّبِعُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَو<rule class=madda_normal>ٰ</rule>تِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمِيلُو<rule class=slnt>اۡ</rule> مَيۡلاً عَظِيمًا ٢٧',
    27, 5, 1, 83, 66, 33, 'false'
  );
  
  -- Ayah 28 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    521,
    'یُرِیدُ ٱللَّهُ أَن یُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَـٰنُ ضَعِیفࣰا',
    'يريد الله ان يخفف عنكم وخلق الانسان ضعيفا',
    'يُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُخَفِّفَ عَ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ وَخُلِقَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ ضَعِيفًا ٢٨',
    28, 5, 1, 83, 66, 33, 'false'
  );
  
  -- Ayah 29 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    522,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَأۡكُلُوۤا۟ أَمۡوَ ٰ⁠لَكُم بَیۡنَكُم بِٱلۡبَـٰطِلِ إِلَّاۤ أَن تَكُونَ تِجَـٰرَةً عَن تَرَاضࣲ مِّنكُمۡۚ وَلَا تَقۡتُلُوۤا۟ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِیمࣰا',
    'يا ايها الذين امنوا لا تاكلوا اموالكم بينكم بالباطل الا ان تكون تجارة عن تراض منكم ولا تقتلوا انفسكم ان الله كان بكم رحيما',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَأۡكُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونَ تِجَ<rule class=madda_normal>ـٰ</rule>رَةً عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرَا<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ وَلَا تَ<rule class=qalaqah>قۡ</rule>تُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِكُمۡ رَحِيمًا ٢٩',
    29, 5, 1, 83, 66, 33, 'false'
  );
  
  -- Ayah 30 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    523,
    'وَمَن یَفۡعَلۡ ذَ ٰ⁠لِكَ عُدۡوَ ٰ⁠نࣰا وَظُلۡمࣰا فَسَوۡفَ نُصۡلِیهِ نَارࣰاۚ وَكَانَ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرًا',
    'ومن يفعل ذلك عدوانا وظلما فسوف نصليه نارا وكان ذلك على الله يسيرا',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلۡ ذ<rule class=madda_normal>ٰ</rule>لِكَ عُ<rule class=qalaqah>دۡ</rule>و<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َظُلۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َسَوۡفَ نُصۡلِيهِ نَا<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَسِيرًا ٣٠',
    30, 5, 1, 83, 66, 33, 'false'
  );
  
  -- Ayah 31 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    524,
    'إِن تَجۡتَنِبُوا۟ كَبَاۤىِٕرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلࣰا كَرِیمࣰا',
    'ان تجتنبوا كبائر ما تنهون عنه نكفر عنكم سيئاتكم وندخلكم مدخلا كريما',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>تَنِبُو<rule class=slnt>اۡ</rule> كَب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَ<rule class=ikhafa>نك</rule>ُمۡ سَيِّـَٔـاتِكُمۡ وَنُ<rule class=qalaqah>دۡ</rule>خِلۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>دۡ</rule>خَل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ك</rule>َرِيمًا ٣١',
    31, 5, 1, 83, 66, 33, 'false'
  );
  
  -- Ayah 32 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    525,
    'وَلَا تَتَمَنَّوۡا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضࣲۚ لِّلرِّجَالِ نَصِیبࣱ مِّمَّا ٱكۡتَسَبُوا۟ۖ وَلِلنِّسَاۤءِ نَصِیبࣱ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُوا۟ ٱللَّهَ مِن فَضۡلِهِۦۤۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَیۡءٍ عَلِیمࣰا',
    'ولا تتمنوا ما فضل الله به بعضكم على بعض للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن واسالوا الله من فضله ان الله كان بكل شيء عليما',
    'وَلَا تَتَمَ<rule class=ghunnah>نّ</rule>َوۡ<rule class=slnt>اۡ</rule> مَا فَضَّلَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِه<rule class=madda_normal>ِۦ</rule> بَعۡضَكُمۡ عَلَىٰ بَعۡ<rule class=idgham_wo_ghunnah>ضٍ‌ۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلرِّجَالِ نَصِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>كۡتَسَبُو<rule class=slnt>اۡ‌ۖ</rule> وَلِل<rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ نَصِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>كۡتَسَ<rule class=qalaqah>بۡ</rule>نَ‌ۚ وَسۡــَٔلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِكُلِّ شَىۡءٍ عَلِيمًا ٣٢',
    32, 5, 1, 83, 66, 33, 'false'
  );
  
  -- Ayah 33 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    526,
    'وَلِكُلࣲّ جَعَلۡنَا مَوَ ٰ⁠لِیَ مِمَّا تَرَكَ ٱلۡوَ ٰ⁠لِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِینَ عَقَدَتۡ أَیۡمَـٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِیبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدًا',
    'ولكل جعلنا موالي مما ترك الوالدان والاقربون والذين عقدت ايمانكم فاتوهم نصيبهم ان الله كان على كل شيء شهيدا',
    'وَلِكُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>ج</rule>َعَلۡنَا مَو<rule class=madda_normal>ٰ</rule>لِىَ مِ<rule class=ghunnah>مّ</rule>َا تَرَكَ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِدَانِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>رَبُونَ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ عَقَدَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُكُمۡ فَـَٔـاتُوهُمۡ نَصِيبَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ش</rule>َهِيدًا ٣٣',
    33, 5, 1, 83, 66, 33, 'false'
  );
  
  -- Ayah 34 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    527,
    'ٱلرِّجَالُ قَوَّ ٰ⁠مُونَ عَلَى ٱلنِّسَاۤءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲ وَبِمَاۤ أَنفَقُوا۟ مِنۡ أَمۡوَ ٰ⁠لِهِمۡۚ فَٱلصَّـٰلِحَـٰتُ قَـٰنِتَـٰتٌ حَـٰفِظَـٰتࣱ لِّلۡغَیۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّـٰتِی تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِی ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُوا۟ عَلَیۡهِنَّ سَبِیلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِیࣰّا كَبِیرࣰا',
    'الرجال قوامون على النساء بما فضل الله بعضهم على بعض وبما انفقوا من اموالهم فالصالحات قانتات حافظات للغيب بما حفظ الله واللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان اطعنكم فلا تبغوا عليهن سبيلا ان الله كان عليا كبيرا',
    'ٱ<rule class=laam_shamsiyah>ل</rule>رِّجَالُ قَوّ<rule class=madda_normal>ٰ</rule>مُونَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بِمَا فَضَّلَ <rule class=ham_wasl>ٱ</rule>للَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>و</rule>َبِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ</rule> مِنۡ أَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ‌ۚ فَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تُ قَ<rule class=madda_normal>ـٰ</rule>نِتَ<rule class=madda_normal>ـٰ</rule>تٌ حَ<rule class=madda_normal>ـٰ</rule>فِظَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡغَيۡبِ بِمَا حَفِظَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>تِى تَخَافُونَ نُشُوزَهُ<rule class=ghunnah>نّ</rule>َ فَعِظُوهُ<rule class=ghunnah>نّ</rule>َ وَ<rule class=ham_wasl>ٱ</rule>هۡجُرُوهُ<rule class=ghunnah>نّ</rule>َ فِى <rule class=ham_wasl>ٱ</rule>لۡمَضَاجِعِ وَ<rule class=ham_wasl>ٱ</rule>ضۡرِبُوهُ<rule class=ghunnah>نّ</rule>َ‌ۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَ<rule class=qalaqah>بۡ</rule>غُو<rule class=slnt>اۡ</rule> عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ سَبِيلاً‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلِي<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٣٤',
    34, 5, 1, 84, 67, 33, 'false'
  );
  
  -- Ayah 35 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    528,
    'وَإِنۡ خِفۡتُمۡ شِقَاقَ بَیۡنِهِمَا فَٱبۡعَثُوا۟ حَكَمࣰا مِّنۡ أَهۡلِهِۦ وَحَكَمࣰا مِّنۡ أَهۡلِهَاۤ إِن یُرِیدَاۤ إِصۡلَـٰحࣰا یُوَفِّقِ ٱللَّهُ بَیۡنَهُمَاۤۗ إِنَّ ٱللَّهَ كَانَ عَلِیمًا خَبِیرࣰا',
    'وان خفتم شقاق بينهما فابعثوا حكما من اهله وحكما من اهلها ان يريدا اصلاحا يوفق الله بينهما ان الله كان عليما خبيرا',
    'وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>عَثُو<rule class=slnt>اۡ</rule> حَكَ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِه<rule class=madda_normal>ِۦ</rule> وَحَكَ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِه<rule class=madda_obligatory_monfasel>َآ</rule> إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيد<rule class=madda_obligatory_monfasel>َآ</rule> إِصۡلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>ي</rule>ُوَفِّقِ <rule class=ham_wasl>ٱ</rule>للَّهُ بَيۡنَهُم<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلِيمًا خَبِيرًا ٣٥',
    35, 5, 1, 84, 67, 33, 'false'
  );
  
  -- Ayah 36 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    529,
    '۞ وَٱعۡبُدُوا۟ ٱللَّهَ وَلَا تُشۡرِكُوا۟ بِهِۦ شَیۡـࣰٔاۖ وَبِٱلۡوَ ٰ⁠لِدَیۡنِ إِحۡسَـٰنࣰا وَبِذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱلۡجَارِ ذِی ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِیلِ وَمَا مَلَكَتۡ أَیۡمَـٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا یُحِبُّ مَن كَانَ مُخۡتَالࣰا فَخُورًا',
    'واعبدوا الله ولا تشركوا به شيئا وبالوالدين احسانا وبذي القربى واليتامى والمساكين والجار ذي القربى والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت ايمانكم ان الله لا يحب من كان مختالا فخورا',
    '۞وَ<rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَلَا تُشۡرِكُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َبِ<rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِدَيۡنِ إِحۡسَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َبِذِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينِ وَ<rule class=ham_wasl>ٱ</rule>لۡجَارِ ذِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡجَارِ <rule class=ham_wasl>ٱ</rule>لۡجُنُبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّاحِبِ بِ<rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=iqlab>نۢب</rule>ِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُكُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مُخۡتَال<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>َخُورًا ٣٦',
    36, 5, 1, 84, 67, 34, 'false'
  );
  
  -- Ayah 37 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    530,
    'ٱلَّذِینَ یَبۡخَلُونَ وَیَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَیَكۡتُمُونَ مَاۤ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَـٰفِرِینَ عَذَابࣰا مُّهِینࣰا',
    'الذين يبخلون ويامرون الناس بالبخل ويكتمون ما اتاهم الله من فضله واعتدنا للكافرين عذابا مهينا',
    'ٱلَّذِينَ يَ<rule class=qalaqah>بۡ</rule>خَلُونَ وَيَأۡمُرُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ بِ<rule class=ham_wasl>ٱ</rule>لۡبُخۡلِ وَيَكۡتُمُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَأَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ُّهِينًا ٣٧',
    37, 5, 1, 84, 67, 34, 'false'
  );
  
  -- Ayah 38 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    531,
    'وَٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰ⁠لَهُمۡ رِئَاۤءَ ٱلنَّاسِ وَلَا یُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡیَوۡمِ ٱلۡـَٔاخِرِۗ وَمَن یَكُنِ ٱلشَّیۡطَـٰنُ لَهُۥ قَرِینࣰا فَسَاۤءَ قَرِینࣰا',
    'والذين ينفقون اموالهم رئاء الناس ولا يؤمنون بالله ولا باليوم الاخر ومن يكن الشيطان له قرينا فساء قرينا',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُ<rule class=ikhafa>نف</rule>ِقُونَ أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ رِئ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا بِ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ لَهُ<rule class=madda_normal>ۥ</rule> قَرِي<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ قَرِينًا ٣٨',
    38, 5, 1, 85, 67, 34, 'false'
  );
  
  -- Ayah 39 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    532,
    'وَمَاذَا عَلَیۡهِمۡ لَوۡ ءَامَنُوا۟ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِیمًا',
    'وماذا عليهم لو امنوا بالله واليوم الاخر وانفقوا مما رزقهم الله وكان الله بهم عليما',
    'وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَأَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَقَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِهِمۡ عَلِيمًا ٣٩',
    39, 5, 1, 85, 67, 34, 'false'
  );
  
  -- Ayah 40 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    533,
    'إِنَّ ٱللَّهَ لَا یَظۡلِمُ مِثۡقَالَ ذَرَّةࣲۖ وَإِن تَكُ حَسَنَةࣰ یُضَـٰعِفۡهَا وَیُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِیمࣰا',
    'ان الله لا يظلم مثقال ذرة وان تك حسنة يضاعفها ويؤت من لدنه اجرا عظيما',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّ<rule class=idgham_ghunnah>ةٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُ حَسَنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>ُضَ<rule class=madda_normal>ـٰ</rule>عِفۡهَا وَيُؤۡتِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُنۡهُ أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ٤٠',
    40, 5, 1, 85, 67, 34, 'false'
  );
  
  -- Ayah 41 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    534,
    'فَكَیۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِیدࣲ وَجِئۡنَا بِكَ عَلَىٰ هَـٰۤؤُلَاۤءِ شَهِیدࣰا',
    'فكيف اذا جئنا من كل امة بشهيد وجئنا بك على هؤلاء شهيدا',
    'فَكَيۡفَ إِذَا جِئۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=iqlab>ةِۭ</rule> <rule class=iqlab>ب</rule>ِشَهِي<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َجِئۡنَا بِكَ عَلَىٰ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ شَهِيدًا ٤١',
    41, 5, 1, 85, 67, 34, 'false'
  );
  
  -- Ayah 42 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    535,
    'یَوۡمَىِٕذࣲ یَوَدُّ ٱلَّذِینَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا یَكۡتُمُونَ ٱللَّهَ حَدِیثࣰا',
    'يومئذ يود الذين كفروا وعصوا الرسول لو تسوى بهم الارض ولا يكتمون الله حديثا',
    'يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َوَدُّ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَعَصَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَلَا يَكۡتُمُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ حَدِيثًا ٤٢',
    42, 5, 1, 85, 67, 34, 'false'
  );
  
  -- Ayah 43 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    536,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَقۡرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَـٰرَىٰ حَتَّىٰ تَعۡلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِی سَبِیلٍ حَتَّىٰ تَغۡتَسِلُوا۟ۚ وَإِن كُنتُم مَّرۡضَىٰۤ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَاۤءَ أَحَدࣱ مِّنكُم مِّنَ ٱلۡغَاۤىِٕطِ أَوۡ لَـٰمَسۡتُمُ ٱلنِّسَاۤءَ فَلَمۡ تَجِدُوا۟ مَاۤءࣰ فَتَیَمَّمُوا۟ صَعِیدࣰا طَیِّبࣰا فَٱمۡسَحُوا۟ بِوُجُوهِكُمۡ وَأَیۡدِیكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا',
    'يا ايها الذين امنوا لا تقربوا الصلاة وانتم سكارى حتى تعلموا ما تقولون ولا جنبا الا عابري سبيل حتى تغتسلوا وان كنتم مرضى او على سفر او جاء احد منكم من الغائط او لامستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم ان الله كان عفوا غفورا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَ<rule class=qalaqah>قۡ</rule>رَبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَ<rule class=ikhafa>نت</rule>ُمۡ سُكَ<rule class=madda_normal>ـٰ</rule>رَىٰ حَتَّىٰ تَعۡلَمُو<rule class=slnt>اۡ</rule> مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغۡتَسِلُو<rule class=slnt>اۡ‌ۚ</rule> وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرۡضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَوۡ عَلَىٰ سَفَرٍ أَوۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَحَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡغ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِطِ أَوۡ لَ<rule class=madda_normal>ـٰ</rule>مَسۡتُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَلَمۡ تَجِدُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َتَيَ<rule class=ghunnah>مّ</rule>َمُو<rule class=slnt>اۡ</rule> صَعِي<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ط</rule>َيِّ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>مۡسَحُو<rule class=slnt>اۡ</rule> بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَفُوًّا غَفُورًا ٤٣',
    43, 5, 1, 85, 68, 34, 'false'
  );
  
  -- Ayah 44 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    537,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِینَ أُوتُوا۟ نَصِیبࣰا مِّنَ ٱلۡكِتَـٰبِ یَشۡتَرُونَ ٱلضَّلَـٰلَةَ وَیُرِیدُونَ أَن تَضِلُّوا۟ ٱلسَّبِیلَ',
    'الم تر الى الذين اوتوا نصيبا من الكتاب يشترون الضلالة ويريدون ان تضلوا السبيل',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> نَصِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ يَشۡتَرُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لَةَ وَيُرِيدُونَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َضِلُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لَ ٤٤',
    44, 5, 1, 85, 68, 34, 'false'
  );
  
  -- Ayah 45 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    538,
    'وَٱللَّهُ أَعۡلَمُ بِأَعۡدَاۤىِٕكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِیࣰّا وَكَفَىٰ بِٱللَّهِ نَصِیرࣰا',
    'والله اعلم باعدائكم وكفى بالله وليا وكفى بالله نصيرا',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِأَعۡد<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ‌ۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ نَصِيرًا ٤٥',
    45, 5, 1, 86, 68, 34, 'false'
  );
  
  -- Ayah 46 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    539,
    'مِّنَ ٱلَّذِینَ هَادُوا۟ یُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَیَقُولُونَ سَمِعۡنَا وَعَصَیۡنَا وَٱسۡمَعۡ غَیۡرَ مُسۡمَعࣲ وَرَ ٰ⁠عِنَا لَیَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنࣰا فِی ٱلدِّینِۚ وَلَوۡ أَنَّهُمۡ قَالُوا۟ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَیۡرࣰا لَّهُمۡ وَأَقۡوَمَ وَلَـٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا یُؤۡمِنُونَ إِلَّا قَلِیلࣰا',
    'من الذين هادوا يحرفون الكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع وراعنا ليا بالسنتهم وطعنا في الدين ولو انهم قالوا سمعنا واطعنا واسمع وانظرنا لكان خيرا لهم واقوم ولكن لعنهم الله بكفرهم فلا يؤمنون الا قليلا',
    'مِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَادُو<rule class=slnt>اۡ</rule> يُحَرِّفُونَ <rule class=ham_wasl>ٱ</rule>لۡكَلِمَ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّوَاضِعِه<rule class=madda_normal>ِۦ</rule> وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا وَ<rule class=ham_wasl>ٱ</rule>سۡمَعۡ غَيۡرَ مُسۡمَ<rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_normal>ٰ</rule>عِنَا لَيّ<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِأَلۡسِنَتِهِمۡ وَطَعۡ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ‌ۚ وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ قَالُو<rule class=slnt>اۡ</rule> سَمِعۡنَا وَأَطَعۡنَا وَ<rule class=ham_wasl>ٱ</rule>سۡمَعۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡنَا لَكَانَ خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ وَأَ<rule class=qalaqah>قۡ</rule>وَمَ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَنَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلاً ٤٦',
    46, 5, 1, 86, 68, 34, 'false'
  );
  
  -- Ayah 47 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    540,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ ءَامِنُوا۟ بِمَا نَزَّلۡنَا مُصَدِّقࣰا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهࣰا فَنَرُدَّهَا عَلَىٰۤ أَدۡبَارِهَاۤ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّاۤ أَصۡحَـٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا',
    'يا ايها الذين اوتوا الكتاب امنوا بما نزلنا مصدقا لما معكم من قبل ان نطمس وجوها فنردها على ادبارها او نلعنهم كما لعنا اصحاب السبت وكان امر الله مفعولا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ ءَامِنُو<rule class=slnt>اۡ</rule> بِمَا نَزَّلۡنَا مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا مَعَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>طۡ</rule>مِسَ وُجُو<rule class=ikhafa>هًا</rule> <rule class=ikhafa>ف</rule>َنَرُدَّهَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=qalaqah>دۡ</rule>بَارِه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=qalaqah>بۡ</rule>تِ‌ۚ وَكَانَ أَمۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ مَفۡعُولاً ٤٧',
    47, 5, 1, 86, 68, 34, 'false'
  );
  
  -- Ayah 48 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    541,
    'إِنَّ ٱللَّهَ لَا یَغۡفِرُ أَن یُشۡرَكَ بِهِۦ وَیَغۡفِرُ مَا دُونَ ذَ ٰ⁠لِكَ لِمَن یَشَاۤءُۚ وَمَن یُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰۤ إِثۡمًا عَظِیمًا',
    'ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد افترى اثما عظيما',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَغۡفِرُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُشۡرَكَ بِه<rule class=madda_normal>ِۦ</rule> وَيَغۡفِرُ مَا دُونَ ذ<rule class=madda_normal>ٰ</rule>لِكَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُشۡرِكۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ فَقَدِ <rule class=ham_wasl>ٱ</rule>فۡتَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِثۡمًا عَظِيمًا ٤٨',
    48, 5, 1, 86, 68, 34, 'false'
  );
  
  -- Ayah 49 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    542,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِینَ یُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ یُزَكِّی مَن یَشَاۤءُ وَلَا یُظۡلَمُونَ فَتِیلًا',
    'الم تر الى الذين يزكون انفسهم بل الله يزكي من يشاء ولا يظلمون فتيلا',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُزَكُّونَ أَ<rule class=ikhafa>نف</rule>ُسَه<rule class=ikhafa_shafawi>ُم‌ۚ</rule> <rule class=ikhafa_shafawi>ب</rule>َلِ <rule class=ham_wasl>ٱ</rule>للَّهُ يُزَكِّى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَلَا يُظۡلَمُونَ فَتِيلاً ٤٩',
    49, 5, 1, 86, 68, 34, 'false'
  );
  
  -- Ayah 50 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    543,
    'ٱنظُرۡ كَیۡفَ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦۤ إِثۡمࣰا مُّبِینًا',
    'انظر كيف يفترون على الله الكذب وكفى به اثما مبينا',
    'ٱ<rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ‌ۖ وَكَفَىٰ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِثۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ٥٠',
    50, 5, 1, 86, 68, 34, 'false'
  );
  
  -- Ayah 51 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    544,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِینَ أُوتُوا۟ نَصِیبࣰا مِّنَ ٱلۡكِتَـٰبِ یُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّـٰغُوتِ وَیَقُولُونَ لِلَّذِینَ كَفَرُوا۟ هَـٰۤؤُلَاۤءِ أَهۡدَىٰ مِنَ ٱلَّذِینَ ءَامَنُوا۟ سَبِیلًا',
    'الم تر الى الذين اوتوا نصيبا من الكتاب يؤمنون بالجبت والطاغوت ويقولون للذين كفروا هؤلاء اهدى من الذين امنوا سبيلا',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> نَصِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=qalaqah>بۡ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّ<rule class=madda_normal>ـٰ</rule>غُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَهۡدَىٰ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> سَبِيلاً ٥١',
    51, 5, 1, 86, 69, 34, 'false'
  );
  
  -- Ayah 52 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    545,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَعَنَهُمُ ٱللَّهُۖ وَمَن یَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِیرًا',
    'اولئك الذين لعنهم الله ومن يلعن الله فلن تجد له نصيرا',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَعَنَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َلۡعَنِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لَهُ<rule class=madda_normal>ۥ</rule> نَصِيرًا ٥٢',
    52, 5, 1, 87, 69, 34, 'false'
  );
  
  -- Ayah 53 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    546,
    'أَمۡ لَهُمۡ نَصِیبࣱ مِّنَ ٱلۡمُلۡكِ فَإِذࣰا لَّا یُؤۡتُونَ ٱلنَّاسَ نَقِیرًا',
    'ام لهم نصيب من الملك فاذا لا يؤتون الناس نقيرا',
    'أَمۡ لَهُمۡ نَصِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكِ فَإِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ نَقِيرًا ٥٣',
    53, 5, 1, 87, 69, 34, 'false'
  );
  
  -- Ayah 54 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    547,
    'أَمۡ یَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَاۤ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَیۡنَاۤ ءَالَ إِبۡرَ ٰ⁠هِیمَ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَءَاتَیۡنَـٰهُم مُّلۡكًا عَظِیمࣰا',
    'ام يحسدون الناس على ما اتاهم الله من فضله فقد اتينا ال ابراهيم الكتاب والحكمة واتيناهم ملكا عظيما',
    'أَمۡ يَحۡسُدُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ عَلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> ءَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلۡكًا عَظِيمًا ٥٤',
    54, 5, 1, 87, 69, 34, 'false'
  );
  
  -- Ayah 55 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    548,
    'فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِیرًا',
    'فمنهم من امن به ومنهم من صد عنه وكفى بجهنم سعيرا',
    'فَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ ءَامَنَ بِه<rule class=madda_normal>ِۦ</rule> وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َدَّ عَنۡهُ‌ۚ وَكَفَىٰ بِجَهَ<rule class=ghunnah>نّ</rule>َمَ سَعِيرًا ٥٥',
    55, 5, 1, 87, 69, 34, 'false'
  );
  
  -- Ayah 56 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    549,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِنَا سَوۡفَ نُصۡلِیهِمۡ نَارࣰا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَـٰهُمۡ جُلُودًا غَیۡرَهَا لِیَذُوقُوا۟ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِیزًا حَكِیمࣰا',
    'ان الذين كفروا باياتنا سوف نصليهم نارا كلما نضجت جلودهم بدلناهم جلودا غيرها ليذوقوا العذاب ان الله كان عزيزا حكيما',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا سَوۡفَ نُصۡلِيهِمۡ نَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>ُلَّمَا نَضِجَتۡ جُلُودُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َدَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَزِيزًا حَكِيمًا ٥٦',
    56, 5, 1, 87, 69, 34, 'false'
  );
  
  -- Ayah 57 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    550,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ لَّهُمۡ فِیهَاۤ أَزۡوَ ٰ⁠جࣱ مُّطَهَّرَةࣱۖ وَنُدۡخِلُهُمۡ ظِلࣰّا ظَلِیلًا',
    'والذين امنوا وعملوا الصالحات سندخلهم جنات تجري من تحتها الانهار خالدين فيها ابدا لهم فيها ازواج مطهرة وندخلهم ظلا ظليلا',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ سَنُ<rule class=qalaqah>دۡ</rule>خِلُهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=idgham_wo_ghunnah>دًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّطَهَّرَ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َنُ<rule class=qalaqah>دۡ</rule>خِلُهُمۡ ظِل<rule class=ikhafa>اًّ</rule> <rule class=ikhafa>ظ</rule>َلِيلاً ٥٧',
    57, 5, 1, 87, 69, 34, 'false'
  );
  
  -- Ayah 58 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    551,
    '۞ إِنَّ ٱللَّهَ یَأۡمُرُكُمۡ أَن تُؤَدُّوا۟ ٱلۡأَمَـٰنَـٰتِ إِلَىٰۤ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَیۡنَ ٱلنَّاسِ أَن تَحۡكُمُوا۟ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا یَعِظُكُم بِهِۦۤۗ إِنَّ ٱللَّهَ كَانَ سَمِیعَۢا بَصِیرࣰا',
    'ان الله يامركم ان تؤدوا الامانات الى اهلها واذا حكمتم بين الناس ان تحكموا بالعدل ان الله نعما يعظكم به ان الله كان سميعا بصيرا',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَأۡمُرُكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُؤَدُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَمَ<rule class=madda_normal>ـٰ</rule>نَ<rule class=madda_normal>ـٰ</rule>تِ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِهَا وَإِذَا حَكَمۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡكُمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>دۡ</rule>لِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ نِعِ<rule class=ghunnah>مّ</rule>َا يَعِظُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ سَمِيع<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َصِيرًا ٥٨',
    58, 5, 1, 87, 69, 35, 'false'
  );
  
  -- Ayah 59 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    552,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَ وَأُو۟لِی ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَـٰزَعۡتُمۡ فِی شَیۡءࣲ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ ذَ ٰ⁠لِكَ خَیۡرࣱ وَأَحۡسَنُ تَأۡوِیلًا',
    'يا ايها الذين امنوا اطيعوا الله واطيعوا الرسول واولي الامر منكم فان تنازعتم في شيء فردوه الى الله والرسول ان كنتم تؤمنون بالله واليوم الاخر ذلك خير واحسن تاويلا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ وَأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ مِ<rule class=ikhafa>نك</rule>ُمۡ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َنَ<rule class=madda_normal>ـٰ</rule>زَعۡتُمۡ فِى ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َرُدُّوهُ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَحۡسَنُ تَأۡوِيلاً ٥٩',
    59, 5, 1, 87, 69, 35, 'false'
  );
  
  -- Ayah 60 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    553,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِینَ یَزۡعُمُونَ أَنَّهُمۡ ءَامَنُوا۟ بِمَاۤ أُنزِلَ إِلَیۡكَ وَمَاۤ أُنزِلَ مِن قَبۡلِكَ یُرِیدُونَ أَن یَتَحَاكَمُوۤا۟ إِلَى ٱلطَّـٰغُوتِ وَقَدۡ أُمِرُوۤا۟ أَن یَكۡفُرُوا۟ بِهِۦۖ وَیُرِیدُ ٱلشَّیۡطَـٰنُ أَن یُضِلَّهُمۡ ضَلَـٰلَۢا بَعِیدࣰا',
    'الم تر الى الذين يزعمون انهم امنوا بما انزل اليك وما انزل من قبلك يريدون ان يتحاكموا الى الطاغوت وقد امروا ان يكفروا به ويريد الشيطان ان يضلهم ضلالا بعيدا',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَزۡعُمُونَ أَ<rule class=ghunnah>نّ</rule>َهُمۡ ءَامَنُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ يُرِيدُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَحَاكَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّ<rule class=madda_normal>ـٰ</rule>غُوتِ وَقَ<rule class=qalaqah>دۡ</rule> أُمِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> وَيُرِيدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضِلَّهُمۡ ضَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=iqlab>اَۢ</rule> <rule class=iqlab>ب</rule>َعِيدًا ٦٠',
    60, 5, 1, 88, 70, 35, 'false'
  );
  
  -- Ayah 61 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    554,
    'وَإِذَا قِیلَ لَهُمۡ تَعَالَوۡا۟ إِلَىٰ مَاۤ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَیۡتَ ٱلۡمُنَـٰفِقِینَ یَصُدُّونَ عَنكَ صُدُودࣰا',
    'واذا قيل لهم تعالوا الى ما انزل الله والى الرسول رايت المنافقين يصدون عنك صدودا',
    'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡ<rule class=slnt>اۡ</rule> إِلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَإِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ رَأَيۡتَ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ يَصُدُّونَ عَ<rule class=ikhafa>نك</rule>َ صُدُودًا ٦١',
    61, 5, 1, 88, 70, 35, 'false'
  );
  
  -- Ayah 62 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    555,
    'فَكَیۡفَ إِذَاۤ أَصَـٰبَتۡهُم مُّصِیبَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ ثُمَّ جَاۤءُوكَ یَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَاۤ إِلَّاۤ إِحۡسَـٰنࣰا وَتَوۡفِیقًا',
    'فكيف اذا اصابتهم مصيبة بما قدمت ايديهم ثم جاءوك يحلفون بالله ان اردنا الا احسانا وتوفيقا',
    'فَكَيۡفَ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَصَ<rule class=madda_normal>ـٰ</rule>بَتۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّصِيبَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِمَا قَدَّمَتۡ أَيۡدِيهِمۡ ثُ<rule class=ghunnah>مّ</rule>َ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوكَ يَحۡلِفُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ إِنۡ أَرَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِحۡسَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َتَوۡفِيقًا ٦٢',
    62, 5, 1, 88, 70, 35, 'false'
  );
  
  -- Ayah 63 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    556,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ یَعۡلَمُ ٱللَّهُ مَا فِی قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِیۤ أَنفُسِهِمۡ قَوۡلَۢا بَلِیغࣰا',
    'اولئك الذين يعلم الله ما في قلوبهم فاعرض عنهم وعظهم وقل لهم في انفسهم قولا بليغا',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَعۡلَمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا فِى قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ قَوۡل<rule class=iqlab>اَۢ</rule> <rule class=iqlab>ب</rule>َلِيغًا ٦٣',
    63, 5, 1, 88, 70, 35, 'false'
  );
  
  -- Ayah 64 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    557,
    'وَمَاۤ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِیُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوۤا۟ أَنفُسَهُمۡ جَاۤءُوكَ فَٱسۡتَغۡفَرُوا۟ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابࣰا رَّحِیمࣰا',
    'وما ارسلنا من رسول الا ليطاع باذن الله ولو انهم اذ ظلموا انفسهم جاءوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ إِ<rule class=idgham_mutajanisayn>ذ</rule> ظَّلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوكَ فَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفَرَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ لَوَجَدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ تَوَّا<rule class=idgham_wo_ghunnah>بًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٦٤',
    64, 5, 1, 88, 70, 35, 'false'
  );
  
  -- Ayah 65 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    558,
    'فَلَا وَرَبِّكَ لَا یُؤۡمِنُونَ حَتَّىٰ یُحَكِّمُوكَ فِیمَا شَجَرَ بَیۡنَهُمۡ ثُمَّ لَا یَجِدُوا۟ فِیۤ أَنفُسِهِمۡ حَرَجࣰا مِّمَّا قَضَیۡتَ وَیُسَلِّمُوا۟ تَسۡلِیمࣰا',
    'فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في انفسهم حرجا مما قضيت ويسلموا تسليما',
    'فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ لَا يَجِدُو<rule class=slnt>اۡ</rule> ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ حَرَ<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا قَضَيۡتَ وَيُسَلِّمُو<rule class=slnt>اۡ</rule> تَسۡلِيمًا ٦٥',
    65, 5, 1, 88, 70, 35, 'false'
  );
  
  -- Ayah 66 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    559,
    'وَلَوۡ أَنَّا كَتَبۡنَا عَلَیۡهِمۡ أَنِ ٱقۡتُلُوۤا۟ أَنفُسَكُمۡ أَوِ ٱخۡرُجُوا۟ مِن دِیَـٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِیلࣱ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُوا۟ مَا یُوعَظُونَ بِهِۦ لَكَانَ خَیۡرࣰا لَّهُمۡ وَأَشَدَّ تَثۡبِیتࣰا',
    'ولو انا كتبنا عليهم ان اقتلوا انفسكم او اخرجوا من دياركم ما فعلوه الا قليل منهم ولو انهم فعلوا ما يوعظون به لكان خيرا لهم واشد تثبيتا',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َا كَتَ<rule class=qalaqah>بۡ</rule>نَا عَلَيۡهِمۡ أَنِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ أَوِ <rule class=ham_wasl>ٱ</rule>خۡرُجُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا فَعَلُوهُ إِلَّا قَلِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ‌ۖ وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ فَعَلُو<rule class=slnt>اۡ</rule> مَا يُوعَظُونَ بِه<rule class=madda_normal>ِۦ</rule> لَكَانَ خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ وَأَشَدَّ تَثۡبِيتًا ٦٦',
    66, 5, 1, 89, 70, 35, 'false'
  );
  
  -- Ayah 67 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    560,
    'وَإِذࣰا لَّـَٔاتَیۡنَـٰهُم مِّن لَّدُنَّاۤ أَجۡرًا عَظِیمࣰا',
    'واذا لاتيناهم من لدنا اجرا عظيما',
    'وَإِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّأَتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ٦٧',
    67, 5, 1, 89, 70, 35, 'false'
  );
  
  -- Ayah 68 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    561,
    'وَلَهَدَیۡنَـٰهُمۡ صِرَ ٰ⁠طࣰا مُّسۡتَقِیمࣰا',
    'ولهديناهم صراطا مستقيما',
    'وَلَهَدَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طًا</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقِيمًا ٦٨',
    68, 5, 1, 89, 70, 35, 'false'
  );
  
  -- Ayah 69 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    562,
    'وَمَن یُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَـٰۤىِٕكَ مَعَ ٱلَّذِینَ أَنۡعَمَ ٱللَّهُ عَلَیۡهِم مِّنَ ٱلنَّبِیِّـۧنَ وَٱلصِّدِّیقِینَ وَٱلشُّهَدَاۤءِ وَٱلصَّـٰلِحِینَۚ وَحَسُنَ أُو۟لَـٰۤىِٕكَ رَفِیقࣰا',
    'ومن يطع الله والرسول فاولئك مع الذين انعم الله عليهم من النبيين والصديقين والشهداء والصالحين وحسن اولئك رفيقا',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُطِعِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مَعَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَنۡعَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّدِّيقِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحِينَ‌ۚ وَحَسُنَ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ رَفِيقًا ٦٩',
    69, 5, 1, 89, 70, 35, 'false'
  );
  
  -- Ayah 70 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    563,
    'ذَ ٰ⁠لِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِیمࣰا',
    'ذلك الفضل من الله وكفى بالله عليما',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَضۡلُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ عَلِيمًا ٧٠',
    70, 5, 1, 89, 70, 35, 'false'
  );
  
  -- Ayah 71 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    564,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ خُذُوا۟ حِذۡرَكُمۡ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِیعࣰا',
    'يا ايها الذين امنوا خذوا حذركم فانفروا ثبات او انفروا جميعا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> خُذُو<rule class=slnt>اۡ</rule> حِذۡرَكُمۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>ِرُو<rule class=slnt>اۡ</rule> ثُبَاتٍ أَوِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>ِرُو<rule class=slnt>اۡ</rule> جَمِيعًا ٧١',
    71, 5, 1, 89, 71, 35, 'false'
  );
  
  -- Ayah 72 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    565,
    'وَإِنَّ مِنكُمۡ لَمَن لَّیُبَطِّئَنَّ فَإِنۡ أَصَـٰبَتۡكُم مُّصِیبَةࣱ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَیَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِیدࣰا',
    'وان منكم لمن ليبطئن فان اصابتكم مصيبة قال قد انعم الله علي اذ لم اكن معهم شهيدا',
    'وَإِ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ikhafa>نك</rule>ُمۡ لَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيُبَطِّئَ<rule class=ghunnah>نّ</rule>َ فَإِنۡ أَصَ<rule class=madda_normal>ـٰ</rule>بَتۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّصِيبَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule>َالَ قَ<rule class=qalaqah>دۡ</rule> أَنۡعَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىَّ إِذۡ لَمۡ أَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>َّعَهُمۡ شَهِيدًا ٧٢',
    72, 5, 1, 89, 71, 35, 'false'
  );
  
  -- Ayah 73 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    566,
    'وَلَىِٕنۡ أَصَـٰبَكُمۡ فَضۡلࣱ مِّنَ ٱللَّهِ لَیَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَیۡنَكُمۡ وَبَیۡنَهُۥ مَوَدَّةࣱ یَـٰلَیۡتَنِی كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِیمࣰا',
    'ولئن اصابكم فضل من الله ليقولن كان لم تكن بينكم وبينه مودة يا ليتني كنت معهم فافوز فوزا عظيما',
    'وَلَئِنۡ أَصَ<rule class=madda_normal>ـٰ</rule>بَكُمۡ فَضۡ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ لَيَقُولَ<rule class=ghunnah>نّ</rule>َ كَأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَك<rule class=iqlab>ُنۢ</rule> <rule class=iqlab>ب</rule>َيۡنَكُمۡ وَبَيۡنَهُ<rule class=madda_normal>ۥ</rule> مَوَدَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_normal>ـٰ</rule>لَيۡتَنِى كُ<rule class=ikhafa>نت</rule>ُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِيمًا ٧٣',
    73, 5, 1, 89, 71, 35, 'false'
  );
  
  -- Ayah 74 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    567,
    '۞ فَلۡیُقَـٰتِلۡ فِی سَبِیلِ ٱللَّهِ ٱلَّذِینَ یَشۡرُونَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا بِٱلۡـَٔاخِرَةِۚ وَمَن یُقَـٰتِلۡ فِی سَبِیلِ ٱللَّهِ فَیُقۡتَلۡ أَوۡ یَغۡلِبۡ فَسَوۡفَ نُؤۡتِیهِ أَجۡرًا عَظِیمࣰا',
    'فليقاتل في سبيل الله الذين يشرون الحياة الدنيا بالاخرة ومن يقاتل في سبيل الله فيقتل او يغلب فسوف نؤتيه اجرا عظيما',
    '۞فَلۡيُقَ<rule class=madda_normal>ـٰ</rule>تِلۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَشۡرُونَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُقَ<rule class=madda_normal>ـٰ</rule>تِلۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَيُ<rule class=qalaqah>قۡ</rule>تَلۡ أَوۡ يَغۡلِ<rule class=qalaqah>بۡ</rule> فَسَوۡفَ نُؤۡتِيهِ أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ٧٤',
    74, 5, 1, 89, 71, 36, 'false'
  );
  
  -- Ayah 75 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    568,
    'وَمَا لَكُمۡ لَا تُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِینَ مِنَ ٱلرِّجَالِ وَٱلنِّسَاۤءِ وَٱلۡوِلۡدَ ٰ⁠نِ ٱلَّذِینَ یَقُولُونَ رَبَّنَاۤ أَخۡرِجۡنَا مِنۡ هَـٰذِهِ ٱلۡقَرۡیَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِیࣰّا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِیرًا',
    'وما لكم لا تقاتلون في سبيل الله والمستضعفين من الرجال والنساء والولدان الذين يقولون ربنا اخرجنا من هذه القرية الظالم اهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا',
    'وَمَا لَكُمۡ لَا تُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُسۡتَضۡعَفِينَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّجَالِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡوِلۡد<rule class=madda_normal>ٰ</rule>نِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَقُولُونَ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡرِ<rule class=qalaqah>جۡ</rule>نَا مِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّالِمِ أَهۡلُهَا وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَل لَّنَا م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ikhafa>نك</rule>َ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَل لَّنَا م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ikhafa>نك</rule>َ نَصِيرًا ٧٥',
    75, 5, 1, 90, 71, 36, 'false'
  );
  
  -- Ayah 76 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    569,
    'ٱلَّذِینَ ءَامَنُوا۟ یُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِۖ وَٱلَّذِینَ كَفَرُوا۟ یُقَـٰتِلُونَ فِی سَبِیلِ ٱلطَّـٰغُوتِ فَقَـٰتِلُوۤا۟ أَوۡلِیَاۤءَ ٱلشَّیۡطَـٰنِۖ إِنَّ كَیۡدَ ٱلشَّیۡطَـٰنِ كَانَ ضَعِیفًا',
    'الذين امنوا يقاتلون في سبيل الله والذين كفروا يقاتلون في سبيل الطاغوت فقاتلوا اولياء الشيطان ان كيد الشيطان كان ضعيفا',
    'ٱلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّ<rule class=madda_normal>ـٰ</rule>غُوتِ فَقَ<rule class=madda_normal>ـٰ</rule>تِل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ كَيۡدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ كَانَ ضَعِيفًا ٧٦',
    76, 5, 1, 90, 71, 36, 'false'
  );
  
  -- Ayah 77 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    570,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِینَ قِیلَ لَهُمۡ كُفُّوۤا۟ أَیۡدِیَكُمۡ وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَیۡهِمُ ٱلۡقِتَالُ إِذَا فَرِیقࣱ مِّنۡهُمۡ یَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡیَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡیَةࣰۚ وَقَالُوا۟ رَبَّنَا لِمَ كَتَبۡتَ عَلَیۡنَا ٱلۡقِتَالَ لَوۡلَاۤ أَخَّرۡتَنَاۤ إِلَىٰۤ أَجَلࣲ قَرِیبࣲۗ قُلۡ مَتَـٰعُ ٱلدُّنۡیَا قَلِیلࣱ وَٱلۡـَٔاخِرَةُ خَیۡرࣱ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِیلًا',
    'الم تر الى الذين قيل لهم كفوا ايديكم واقيموا الصلاة واتوا الزكاة فلما كتب عليهم القتال اذا فريق منهم يخشون الناس كخشية الله او اشد خشية وقالوا ربنا لم كتبت علينا القتال لولا اخرتنا الى اجل قريب قل متاع الدنيا قليل والاخرة خير لمن اتقى ولا تظلمون فتيلا',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ قِيلَ لَهُمۡ كُفّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡدِيَكُمۡ وَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ فَلَ<rule class=ghunnah>مّ</rule>َا كُتِبَ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡقِتَالُ إِذَا فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ يَخۡشَوۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ كَخَشۡيَةِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡ أَشَدَّ خَشۡيَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َقَالُو<rule class=slnt>اۡ</rule> رَبَّنَا لِمَ كَتَ<rule class=qalaqah>بۡ</rule>تَ عَلَيۡنَا <rule class=ham_wasl>ٱ</rule>لۡقِتَالَ لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَخَّرۡتَن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ق</rule>َرِي<rule class=ikhafa>بٍ‌ۗ</rule> <rule class=ikhafa>ق</rule>ُلۡ مَتَ<rule class=madda_normal>ـٰ</rule>عُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا قَلِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةُ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَنِ <rule class=ham_wasl>ٱ</rule>تَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلاً ٧٧',
    77, 5, 1, 90, 72, 36, 'false'
  );
  
  -- Ayah 78 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    571,
    'أَیۡنَمَا تَكُونُوا۟ یُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِی بُرُوجࣲ مُّشَیَّدَةࣲۗ وَإِن تُصِبۡهُمۡ حَسَنَةࣱ یَقُولُوا۟ هَـٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَیِّئَةࣱ یَقُولُوا۟ هَـٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلࣱّ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَـٰۤؤُلَاۤءِ ٱلۡقَوۡمِ لَا یَكَادُونَ یَفۡقَهُونَ حَدِیثࣰا',
    'اينما تكونوا يدرككم الموت ولو كنتم في بروج مشيدة وان تصبهم حسنة يقولوا هذه من عند الله وان تصبهم سيئة يقولوا هذه من عندك قل كل من عند الله فمال هؤلاء القوم لا يكادون يفقهون حديثا',
    'أَيۡنَمَا تَكُونُو<rule class=slnt>اۡ</rule> يُ<rule class=qalaqah>دۡ</rule>رِككُّمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ وَلَوۡ كُ<rule class=ikhafa>نت</rule>ُمۡ فِى بُرُو<rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّشَيَّدَ<rule class=idgham_ghunnah>ةٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِ<rule class=qalaqah>بۡ</rule>هُمۡ حَسَنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِ<rule class=qalaqah>بۡ</rule>هُمۡ سَيِّئَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> مِنۡ عِ<rule class=ikhafa>ند</rule>ِكَ‌ۚ قُلۡ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ فَمَالِ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثًا ٧٨',
    78, 5, 1, 90, 72, 36, 'false'
  );
  
  -- Ayah 79 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    572,
    'مَّاۤ أَصَابَكَ مِنۡ حَسَنَةࣲ فَمِنَ ٱللَّهِۖ وَمَاۤ أَصَابَكَ مِن سَیِّئَةࣲ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَـٰكَ لِلنَّاسِ رَسُولࣰاۚ وَكَفَىٰ بِٱللَّهِ شَهِیدࣰا',
    'ما اصابك من حسنة فمن الله وما اصابك من سيئة فمن نفسك وارسلناك للناس رسولا وكفى بالله شهيدا',
    'مّ<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَكَ مِنۡ حَسَنَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َمِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َيِّئَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َم<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِكَ‌ۚ وَأَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ لِل<rule class=ghunnah>نّ</rule>َاسِ رَسُول<rule class=idgham_ghunnah>اً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ شَهِيدًا ٧٩',
    79, 5, 1, 90, 72, 36, 'false'
  );
  
  -- Ayah 80 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    573,
    'مَّن یُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَاۤ أَرۡسَلۡنَـٰكَ عَلَیۡهِمۡ حَفِیظࣰا',
    'من يطع الرسول فقد اطاع الله ومن تولى فما ارسلناك عليهم حفيظا',
    'مّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُطِعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ فَقَ<rule class=qalaqah>دۡ</rule> أَطَاعَ <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّىٰ فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ عَلَيۡهِمۡ حَفِيظًا ٨٠',
    80, 5, 1, 91, 72, 36, 'false'
  );
  
  -- Ayah 81 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    574,
    'وَیَقُولُونَ طَاعَةࣱ فَإِذَا بَرَزُوا۟ مِنۡ عِندِكَ بَیَّتَ طَاۤىِٕفَةࣱ مِّنۡهُمۡ غَیۡرَ ٱلَّذِی تَقُولُۖ وَٱللَّهُ یَكۡتُبُ مَا یُبَیِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلًا',
    'ويقولون طاعة فاذا برزوا من عندك بيت طائفة منهم غير الذي تقول والله يكتب ما يبيتون فاعرض عنهم وتوكل على الله وكفى بالله وكيلا',
    'وَيَقُولُونَ طَاعَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َإِذَا بَرَزُو<rule class=slnt>اۡ</rule> مِنۡ عِ<rule class=ikhafa>ند</rule>ِكَ بَيَّتَ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ غَيۡرَ <rule class=ham_wasl>ٱ</rule>لَّذِى تَقُولُ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَكۡتُبُ مَا يُبَيِّتُونَ‌ۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَكِيلاً ٨١',
    81, 5, 1, 91, 72, 36, 'false'
  );
  
  -- Ayah 82 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    575,
    'أَفَلَا یَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَیۡرِ ٱللَّهِ لَوَجَدُوا۟ فِیهِ ٱخۡتِلَـٰفࣰا كَثِیرࣰا',
    'افلا يتدبرون القران ولو كان من عند غير الله لوجدوا فيه اختلافا كثيرا',
    'أَفَلَا يَتَدَبَّرُونَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ‌ۚ وَلَوۡ كَانَ مِنۡ عِ<rule class=ikhafa>ند</rule>ِ غَيۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَوَجَدُو<rule class=slnt>اۡ</rule> فِيهِ <rule class=ham_wasl>ٱ</rule>خۡتِلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>فًا</rule> <rule class=ikhafa>ك</rule>َثِيرًا ٨٢',
    82, 5, 1, 91, 72, 36, 'false'
  );
  
  -- Ayah 83 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    576,
    'وَإِذَا جَاۤءَهُمۡ أَمۡرࣱ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُوا۟ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰۤ أُو۟لِی ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِینَ یَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّیۡطَـٰنَ إِلَّا قَلِیلࣰا',
    'واذا جاءهم امر من الامن او الخوف اذاعوا به ولو ردوه الى الرسول والى اولي الامر منهم لعلمه الذين يستنبطونه منهم ولولا فضل الله عليكم ورحمته لاتبعتم الشيطان الا قليلا',
    'وَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ أَمۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡنِ أَوِ <rule class=ham_wasl>ٱ</rule>لۡخَوۡفِ أَذَاعُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَلَوۡ رَدُّوهُ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ وَإِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَسۡتَ<rule class=iqlab>نۢب</rule>ِطُونَهُ<rule class=madda_normal>ۥ</rule> مِنۡهُمۡ‌ۗ وَلَوۡلَا فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُ<rule class=madda_normal>ۥ</rule> لَ<rule class=ham_wasl>ٱ</rule>تَّبَعۡتُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ إِلَّا قَلِيلاً ٨٣',
    83, 5, 1, 91, 72, 36, 'false'
  );
  
  -- Ayah 84 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    577,
    'فَقَـٰتِلۡ فِی سَبِیلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِینَۖ عَسَى ٱللَّهُ أَن یَكُفَّ بَأۡسَ ٱلَّذِینَ كَفَرُوا۟ۚ وَٱللَّهُ أَشَدُّ بَأۡسࣰا وَأَشَدُّ تَنكِیلࣰا',
    'فقاتل في سبيل الله لا تكلف الا نفسك وحرض المؤمنين عسى الله ان يكف باس الذين كفروا والله اشد باسا واشد تنكيلا',
    'فَقَ<rule class=madda_normal>ـٰ</rule>تِلۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَ‌ۚ وَحَرِّضِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ‌ۖ عَسَى <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُفَّ بَأۡسَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ‌ۚ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَشَدُّ بَأۡ<rule class=idgham_ghunnah>سًا</rule> <rule class=idgham_ghunnah>و</rule>َأَشَدُّ تَ<rule class=ikhafa>نك</rule>ِيلاً ٨٤',
    84, 5, 1, 91, 72, 36, 'false'
  );
  
  -- Ayah 85 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    578,
    'مَّن یَشۡفَعۡ شَفَـٰعَةً حَسَنَةࣰ یَكُن لَّهُۥ نَصِیبࣱ مِّنۡهَاۖ وَمَن یَشۡفَعۡ شَفَـٰعَةࣰ سَیِّئَةࣰ یَكُن لَّهُۥ كِفۡلࣱ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ مُّقِیتࣰا',
    'من يشفع شفاعة حسنة يكن له نصيب منها ومن يشفع شفاعة سيئة يكن له كفل منها وكان الله على كل شيء مقيتا',
    'مّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َشۡفَعۡ شَفَ<rule class=madda_normal>ـٰ</rule>عَةً حَسَنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> نَصِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َشۡفَعۡ شَفَ<rule class=madda_normal>ـٰ</rule>عَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>س</rule>َيِّئَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> كِفۡ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّقِيتًا ٨٥',
    85, 5, 1, 91, 72, 36, 'false'
  );
  
  -- Ayah 86 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    579,
    'وَإِذَا حُیِّیتُم بِتَحِیَّةࣲ فَحَیُّوا۟ بِأَحۡسَنَ مِنۡهَاۤ أَوۡ رُدُّوهَاۤۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَیۡءٍ حَسِیبًا',
    'واذا حييتم بتحية فحيوا باحسن منها او ردوها ان الله كان على كل شيء حسيبا',
    'وَإِذَا حُيِّيت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِتَحِيَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َحَيُّو<rule class=slnt>اۡ</rule> بِأَحۡسَنَ مِنۡه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ رُدُّوه<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلَىٰ كُلِّ شَىۡءٍ حَسِيبًا ٨٦',
    86, 5, 1, 91, 72, 36, 'false'
  );
  
  -- Ayah 87 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    580,
    'ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ لَیَجۡمَعَنَّكُمۡ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ لَا رَیۡبَ فِیهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِیثࣰا',
    'الله لا اله الا هو ليجمعنكم الى يوم القيامة لا ريب فيه ومن اصدق من الله حديثا',
    'ٱللَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۚ لَيَ<rule class=qalaqah>جۡ</rule>مَعَ<rule class=ghunnah>نّ</rule>َكُمۡ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ لَا رَيۡبَ فِيهِ‌ۗ وَمَنۡ أَصۡدَقُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَدِيثًا ٨٧',
    87, 5, 1, 92, 72, 36, 'false'
  );
  
  -- Ayah 88 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    581,
    '۞ فَمَا لَكُمۡ فِی ٱلۡمُنَـٰفِقِینَ فِئَتَیۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوۤا۟ۚ أَتُرِیدُونَ أَن تَهۡدُوا۟ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن یُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِیلࣰا',
    'فما لكم في المنافقين فئتين والله اركسهم بما كسبوا اتريدون ان تهدوا من اضل الله ومن يضلل الله فلن تجد له سبيلا',
    '۞فَمَا لَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ فِئَتَيۡنِ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَرۡكَسَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَسَب<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> أَتُرِيدُونَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َهۡدُو<rule class=slnt>اۡ</rule> مَنۡ أَضَلَّ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لَهُ<rule class=madda_normal>ۥ</rule> سَبِيلاً ٨٨',
    88, 5, 1, 92, 73, 37, 'false'
  );
  
  -- Ayah 89 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    582,
    'وَدُّوا۟ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَاۤءࣰۖ فَلَا تَتَّخِذُوا۟ مِنۡهُمۡ أَوۡلِیَاۤءَ حَتَّىٰ یُهَاجِرُوا۟ فِی سَبِیلِ ٱللَّهِۚ فَإِن تَوَلَّوۡا۟ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَیۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُوا۟ مِنۡهُمۡ وَلِیࣰّا وَلَا نَصِیرًا',
    'ودوا لو تكفرون كما كفروا فتكونون سواء فلا تتخذوا منهم اولياء حتى يهاجروا في سبيل الله فان تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا',
    'وَدُّو<rule class=slnt>اۡ</rule> لَوۡ تَكۡفُرُونَ كَمَا كَفَرُو<rule class=slnt>اۡ</rule> فَتَكُونُونَ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً‌ۖ</rule> <rule class=ikhafa>ف</rule>َلَا تَتَّخِذُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ حَتَّىٰ يُهَاجِرُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَخُذُوهُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُلُوهُمۡ حَيۡثُ وَجَ<rule class=idgham_mutajanisayn>د</rule>تُّمُوهُمۡ‌ۖ وَلَا تَتَّخِذُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصِيرًا ٨٩',
    89, 5, 1, 92, 73, 37, 'false'
  );
  
  -- Ayah 90 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    583,
    'إِلَّا ٱلَّذِینَ یَصِلُونَ إِلَىٰ قَوۡمِۭ بَیۡنَكُمۡ وَبَیۡنَهُم مِّیثَـٰقٌ أَوۡ جَاۤءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن یُقَـٰتِلُوكُمۡ أَوۡ یُقَـٰتِلُوا۟ قَوۡمَهُمۡۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَیۡكُمۡ فَلَقَـٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ یُقَـٰتِلُوكُمۡ وَأَلۡقَوۡا۟ إِلَیۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَیۡهِمۡ سَبِیلࣰا',
    'الا الذين يصلون الى قوم بينكم وبينهم ميثاق او جاءوكم حصرت صدورهم ان يقاتلوكم او يقاتلوا قومهم ولو شاء الله لسلطهم عليكم فلقاتلوكم فان اعتزلوكم فلم يقاتلوكم والقوا اليكم السلم فما جعل الله لكم عليهم سبيلا',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَصِلُونَ إِلَىٰ قَوۡ<rule class=iqlab>مِۭ</rule> <rule class=iqlab>ب</rule>َيۡنَكُمۡ وَبَيۡنَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule>قٌ أَوۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُقَ<rule class=madda_normal>ـٰ</rule>تِلُوكُمۡ أَوۡ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> قَوۡمَهُمۡ‌ۚ وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَ<rule class=madda_normal>ـٰ</rule>تَلُوكُمۡ‌ۚ فَإِنِ <rule class=ham_wasl>ٱ</rule>عۡتَزَلُوكُمۡ فَلَمۡ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُوكُمۡ وَأَلۡقَوۡ<rule class=slnt>اۡ</rule> إِلَيۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَمَ فَمَا جَعَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلاً ٩٠',
    90, 5, 1, 92, 73, 37, 'false'
  );
  
  -- Ayah 91 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    584,
    'سَتَجِدُونَ ءَاخَرِینَ یُرِیدُونَ أَن یَأۡمَنُوكُمۡ وَیَأۡمَنُوا۟ قَوۡمَهُمۡ كُلَّ مَا رُدُّوۤا۟ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُوا۟ فِیهَاۚ فَإِن لَّمۡ یَعۡتَزِلُوكُمۡ وَیُلۡقُوۤا۟ إِلَیۡكُمُ ٱلسَّلَمَ وَیَكُفُّوۤا۟ أَیۡدِیَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَیۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُو۟لَـٰۤىِٕكُمۡ جَعَلۡنَا لَكُمۡ عَلَیۡهِمۡ سُلۡطَـٰنࣰا مُّبِینࣰا',
    'ستجدون اخرين يريدون ان يامنوكم ويامنوا قومهم كل ما ردوا الى الفتنة اركسوا فيها فان لم يعتزلوكم ويلقوا اليكم السلم ويكفوا ايديهم فخذوهم واقتلوهم حيث ثقفتموهم واولئكم جعلنا لكم عليهم سلطانا مبينا',
    'سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡمَنُوكُمۡ وَيَأۡمَنُو<rule class=slnt>اۡ</rule> قَوۡمَهُمۡ كُلَّ مَا رُدّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡفِتۡنَةِ أُرۡكِسُو<rule class=slnt>اۡ</rule> فِيهَا‌ۚ فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡق<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَمَ وَيَكُفّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ‌ۚ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ٩١',
    91, 5, 1, 92, 73, 37, 'false'
  );
  
  -- Ayah 92 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    585,
    'وَمَا كَانَ لِمُؤۡمِنٍ أَن یَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـࣰٔاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـࣰٔا فَتَحۡرِیرُ رَقَبَةࣲ مُّؤۡمِنَةࣲ وَدِیَةࣱ مُّسَلَّمَةٌ إِلَىٰۤ أَهۡلِهِۦۤ إِلَّاۤ أَن یَصَّدَّقُوا۟ۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوࣲّ لَّكُمۡ وَهُوَ مُؤۡمِنࣱ فَتَحۡرِیرُ رَقَبَةࣲ مُّؤۡمِنَةࣲۖ وَإِن كَانَ مِن قَوۡمِۭ بَیۡنَكُمۡ وَبَیۡنَهُم مِّیثَـٰقࣱ فَدِیَةࣱ مُّسَلَّمَةٌ إِلَىٰۤ أَهۡلِهِۦ وَتَحۡرِیرُ رَقَبَةࣲ مُّؤۡمِنَةࣲۖ فَمَن لَّمۡ یَجِدۡ فَصِیَامُ شَهۡرَیۡنِ مُتَتَابِعَیۡنِ تَوۡبَةࣰ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا',
    'وما كان لمؤمن ان يقتل مؤمنا الا خطا ومن قتل مؤمنا خطا فتحرير رقبة مؤمنة ودية مسلمة الى اهله الا ان يصدقوا فان كان من قوم عدو لكم وهو مؤمن فتحرير رقبة مؤمنة وان كان من قوم بينكم وبينهم ميثاق فدية مسلمة الى اهله وتحرير رقبة مؤمنة فمن لم يجد فصيام شهرين متتابعين توبة من الله وكان الله عليما حكيما',
    'وَمَا كَانَ لِمُؤۡمِنٍ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>تُلَ مُؤۡمِنًا إِلَّا خَطَـ<rule class=idgham_ghunnah>ـًٔا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َتَلَ مُؤۡمِنًا خَطَـ<rule class=ikhafa>ـًٔا</rule> <rule class=ikhafa>ف</rule>َتَحۡرِيرُ رَقَبَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َدِيَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَلَّمَةٌ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َصَّدَّقُو<rule class=slnt>اۡ‌ۚ</rule> فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمٍ عَدُ<rule class=idgham_wo_ghunnah>وٍّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَهُوَ مُؤۡمِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َتَحۡرِيرُ رَقَبَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنَ<rule class=idgham_ghunnah>ةٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡ<rule class=iqlab>مِۭ</rule> <rule class=iqlab>ب</rule>َيۡنَكُمۡ وَبَيۡنَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>قٌ</rule> <rule class=ikhafa>ف</rule>َدِيَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَلَّمَةٌ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِه<rule class=madda_normal>ِۦ</rule> وَتَحۡرِيرُ رَقَبَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنَ<rule class=ikhafa>ةٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَجِ<rule class=qalaqah>دۡ</rule> فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمًا حَكِيمًا ٩٢',
    92, 5, 1, 93, 74, 37, 'false'
  );
  
  -- Ayah 93 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    586,
    'وَمَن یَقۡتُلۡ مُؤۡمِنࣰا مُّتَعَمِّدࣰا فَجَزَاۤؤُهُۥ جَهَنَّمُ خَـٰلِدࣰا فِیهَا وَغَضِبَ ٱللَّهُ عَلَیۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِیمࣰا',
    'ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه واعد له عذابا عظيما',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>تُلۡ مُؤۡمِ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ُّتَعَ<rule class=ghunnah>مّ</rule>ِ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َجَز<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُ<rule class=madda_normal>ۥ</rule> جَهَ<rule class=ghunnah>نّ</rule>َمُ خَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>ِيهَا وَغَضِبَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِ وَلَعَنَهُ<rule class=madda_normal>ۥ</rule> وَأَعَدَّ لَهُ<rule class=madda_normal>ۥ</rule> عَذَابًا عَظِيمًا ٩٣',
    93, 5, 1, 93, 74, 37, 'false'
  );
  
  -- Ayah 94 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    587,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا ضَرَبۡتُمۡ فِی سَبِیلِ ٱللَّهِ فَتَبَیَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنۡ أَلۡقَىٰۤ إِلَیۡكُمُ ٱلسَّلَـٰمَ لَسۡتَ مُؤۡمِنࣰا تَبۡتَغُونَ عَرَضَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِیرَةࣱۚ كَذَ ٰ⁠لِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَیۡكُمۡ فَتَبَیَّنُوۤا۟ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا',
    'يا ايها الذين امنوا اذا ضربتم في سبيل الله فتبينوا ولا تقولوا لمن القى اليكم السلام لست مؤمنا تبتغون عرض الحياة الدنيا فعند الله مغانم كثيرة كذلك كنتم من قبل فمن الله عليكم فتبينوا ان الله كان بما تعملون خبيرا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا ضَرَ<rule class=qalaqah>بۡ</rule>تُمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَتَبَيَّنُو<rule class=slnt>اۡ</rule> وَلَا تَقُولُو<rule class=slnt>اۡ</rule> لِمَنۡ أَلۡقَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَ<rule class=madda_normal>ـٰ</rule>مَ لَسۡتَ مُؤۡمِ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>بۡ</rule>تَغُونَ عَرَضَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا فَعِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ مَغَانِمُ كَثِيرَ<rule class=ikhafa>ةٌ‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ كُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ فَمَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡكُمۡ فَتَبَيَّن<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرًا ٩٤',
    94, 5, 1, 93, 74, 37, 'false'
  );
  
  -- Ayah 95 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    588,
    'لَّا یَسۡتَوِی ٱلۡقَـٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِینَ غَیۡرُ أُو۟لِی ٱلضَّرَرِ وَٱلۡمُجَـٰهِدُونَ فِی سَبِیلِ ٱللَّهِ بِأَمۡوَ ٰ⁠لِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَـٰهِدِینَ بِأَمۡوَ ٰ⁠لِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَـٰعِدِینَ دَرَجَةࣰۚ وَكُلࣰّا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَـٰهِدِینَ عَلَى ٱلۡقَـٰعِدِینَ أَجۡرًا عَظِیمࣰا',
    'لا يستوي القاعدون من المؤمنين غير اولي الضرر والمجاهدون في سبيل الله باموالهم وانفسهم فضل الله المجاهدين باموالهم وانفسهم على القاعدين درجة وكلا وعد الله الحسنى وفضل الله المجاهدين على القاعدين اجرا عظيما',
    'لَّا يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>عِدُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ غَيۡرُ أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّرَرِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُجَ<rule class=madda_normal>ـٰ</rule>هِدُونَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۚ فَضَّلَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُجَ<rule class=madda_normal>ـٰ</rule>هِدِينَ بِأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>عِدِينَ دَرَجَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكُل<rule class=idgham_ghunnah>اًّ</rule> <rule class=idgham_ghunnah>و</rule>َعَدَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ‌ۚ وَفَضَّلَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُجَ<rule class=madda_normal>ـٰ</rule>هِدِينَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>عِدِينَ أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ٩٥',
    95, 5, 1, 94, 74, 37, 'false'
  );
  
  -- Ayah 96 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    589,
    'دَرَجَـٰتࣲ مِّنۡهُ وَمَغۡفِرَةࣰ وَرَحۡمَةࣰۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمًا',
    'درجات منه ومغفرة ورحمة وكان الله غفورا رحيما',
    'دَرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ وَمَغۡفِرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٩٦',
    96, 5, 1, 94, 74, 37, 'false'
  );
  
  -- Ayah 97 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    590,
    'إِنَّ ٱلَّذِینَ تَوَفَّىٰهُمُ ٱلۡمَلَـٰۤىِٕكَةُ ظَالِمِیۤ أَنفُسِهِمۡ قَالُوا۟ فِیمَ كُنتُمۡۖ قَالُوا۟ كُنَّا مُسۡتَضۡعَفِینَ فِی ٱلۡأَرۡضِۚ قَالُوۤا۟ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَ ٰ⁠سِعَةࣰ فَتُهَاجِرُوا۟ فِیهَاۚ فَأُو۟لَـٰۤىِٕكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَاۤءَتۡ مَصِیرًا',
    'ان الذين توفاهم الملائكة ظالمي انفسهم قالوا فيم كنتم قالوا كنا مستضعفين في الارض قالوا الم تكن ارض الله واسعة فتهاجروا فيها فاولئك ماواهم جهنم وساءت مصيرا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَوَفَّ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ ظَالِم<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ قَالُو<rule class=slnt>اۡ</rule> فِيمَ كُ<rule class=ikhafa>نت</rule>ُمۡ‌ۖ قَالُو<rule class=slnt>اۡ</rule> كُ<rule class=ghunnah>نّ</rule>َا مُسۡتَضۡعَفِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَلَمۡ تَكُنۡ أَرۡضُ <rule class=ham_wasl>ٱ</rule>للَّهِ و<rule class=madda_normal>ٰ</rule>سِعَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َتُهَاجِرُو<rule class=slnt>اۡ</rule> فِيهَا‌ۚ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۖ وَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ مَصِيرًا ٩٧',
    97, 5, 1, 94, 75, 37, 'false'
  );
  
  -- Ayah 98 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    591,
    'إِلَّا ٱلۡمُسۡتَضۡعَفِینَ مِنَ ٱلرِّجَالِ وَٱلنِّسَاۤءِ وَٱلۡوِلۡدَ ٰ⁠نِ لَا یَسۡتَطِیعُونَ حِیلَةࣰ وَلَا یَهۡتَدُونَ سَبِیلࣰا',
    'الا المستضعفين من الرجال والنساء والولدان لا يستطيعون حيلة ولا يهتدون سبيلا',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَضۡعَفِينَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّجَالِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡوِلۡد<rule class=madda_normal>ٰ</rule>نِ لَا يَسۡتَطِيعُونَ حِيلَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَهۡتَدُونَ سَبِيلاً ٩٨',
    98, 5, 1, 94, 75, 37, 'false'
  );
  
  -- Ayah 99 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    592,
    'فَأُو۟لَـٰۤىِٕكَ عَسَى ٱللَّهُ أَن یَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورࣰا',
    'فاولئك عسى الله ان يعفو عنهم وكان الله عفوا غفورا',
    'فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ عَسَى <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡفُوَ عَنۡهُمۡ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَفُوًّا غَفُورًا ٩٩',
    99, 5, 1, 94, 75, 37, 'false'
  );
  
  -- Ayah 100 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    593,
    '۞ وَمَن یُهَاجِرۡ فِی سَبِیلِ ٱللَّهِ یَجِدۡ فِی ٱلۡأَرۡضِ مُرَ ٰ⁠غَمࣰا كَثِیرࣰا وَسَعَةࣰۚ وَمَن یَخۡرُجۡ مِنۢ بَیۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ یُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا',
    'ومن يهاجر في سبيل الله يجد في الارض مراغما كثيرا وسعة ومن يخرج من بيته مهاجرا الى الله ورسوله ثم يدركه الموت فقد وقع اجره على الله وكان الله غفورا رحيما',
    '۞وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُهَاجِرۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ يَجِ<rule class=qalaqah>دۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُر<rule class=madda_normal>ٰ</rule>غَ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ك</rule>َثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َسَعَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡرُ<rule class=qalaqah>جۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡتِه<rule class=madda_normal>ِۦ</rule> مُهَاجِرًا إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> ثُ<rule class=ghunnah>مّ</rule>َ يُ<rule class=qalaqah>دۡ</rule>رِكۡهُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ فَقَ<rule class=qalaqah>دۡ</rule> وَقَعَ أَ<rule class=qalaqah>جۡ</rule>رُهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ١٠٠',
    100, 5, 1, 94, 75, 38, 'false'
  );
  
  -- Ayah 101 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    594,
    'وَإِذَا ضَرَبۡتُمۡ فِی ٱلۡأَرۡضِ فَلَیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَن تَقۡصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن یَفۡتِنَكُمُ ٱلَّذِینَ كَفَرُوۤا۟ۚ إِنَّ ٱلۡكَـٰفِرِینَ كَانُوا۟ لَكُمۡ عَدُوࣰّا مُّبِینࣰا',
    'واذا ضربتم في الارض فليس عليكم جناح ان تقصروا من الصلاة ان خفتم ان يفتنكم الذين كفروا ان الكافرين كانوا لكم عدوا مبينا',
    'وَإِذَا ضَرَ<rule class=qalaqah>بۡ</rule>تُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>قۡ</rule>صُرُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ إِنۡ خِفۡتُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡتِنَكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ كَانُو<rule class=slnt>اۡ</rule> لَكُمۡ عَدُو<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ١٠١',
    101, 5, 1, 94, 76, 38, 'false'
  );
  
  -- Ayah 102 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    595,
    'وَإِذَا كُنتَ فِیهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَاۤىِٕفَةࣱ مِّنۡهُم مَّعَكَ وَلۡیَأۡخُذُوۤا۟ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُوا۟ فَلۡیَكُونُوا۟ مِن وَرَاۤىِٕكُمۡ وَلۡتَأۡتِ طَاۤىِٕفَةٌ أُخۡرَىٰ لَمۡ یُصَلُّوا۟ فَلۡیُصَلُّوا۟ مَعَكَ وَلۡیَأۡخُذُوا۟ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِینَ كَفَرُوا۟ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَیَمِیلُونَ عَلَیۡكُم مَّیۡلَةࣰ وَ ٰ⁠حِدَةࣰۚ وَلَا جُنَاحَ عَلَیۡكُمۡ إِن كَانَ بِكُمۡ أَذࣰى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰۤ أَن تَضَعُوۤا۟ أَسۡلِحَتَكُمۡۖ وَخُذُوا۟ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَـٰفِرِینَ عَذَابࣰا مُّهِینࣰا',
    'واذا كنت فيهم فاقمت لهم الصلاة فلتقم طائفة منهم معك ولياخذوا اسلحتهم فاذا سجدوا فليكونوا من ورائكم ولتات طائفة اخرى لم يصلوا فليصلوا معك ولياخذوا حذرهم واسلحتهم ود الذين كفروا لو تغفلون عن اسلحتكم وامتعتكم فيميلون عليكم ميلة واحدة ولا جناح عليكم ان كان بكم اذى من مطر او كنتم مرضى ان تضعوا اسلحتكم وخذوا حذركم ان الله اعد للكافرين عذابا مهينا',
    'وَإِذَا كُ<rule class=ikhafa>نت</rule>َ فِيهِمۡ فَأَقَمۡتَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ فَلۡتَقُمۡ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّعَكَ وَلۡيَأۡخُذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَسۡلِحَتَهُمۡ فَإِذَا سَجَدُو<rule class=slnt>اۡ</rule> فَلۡيَكُونُو<rule class=slnt>اۡ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ وَلۡتَأۡتِ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّو<rule class=slnt>اۡ</rule> فَلۡيُصَلُّو<rule class=slnt>اۡ</rule> مَعَكَ وَلۡيَأۡخُذُو<rule class=slnt>اۡ</rule> حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡ‌ۗ وَدَّ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّيۡلَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَا جُنَاحَ عَلَيۡكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ بِكُمۡ أَ<rule class=idgham_ghunnah>ذًى</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّطَرٍ أَوۡ كُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرۡضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َضَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَسۡلِحَتَكُمۡ‌ۖ وَخُذُو<rule class=slnt>اۡ</rule> حِذۡرَكُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ أَعَدَّ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ُّهِينًا ١٠٢',
    102, 5, 1, 95, 76, 38, 'false'
  );
  
  -- Ayah 103 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    596,
    'فَإِذَا قَضَیۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُوا۟ ٱللَّهَ قِیَـٰمࣰا وَقُعُودࣰا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِیمُوا۟ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِینَ كِتَـٰبࣰا مَّوۡقُوتࣰا',
    'فاذا قضيتم الصلاة فاذكروا الله قياما وقعودا وعلى جنوبكم فاذا اطماننتم فاقيموا الصلاة ان الصلاة كانت على المؤمنين كتابا موقوتا',
    'فَإِذَا قَضَيۡتُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ فَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ قِيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َقُعُو<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َعَلَىٰ جُنُوبِكُمۡ‌ۚ فَإِذَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>طۡ</rule>مَأۡنَ<rule class=ikhafa>نت</rule>ُمۡ فَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ كَانَتۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>َّوۡقُوتًا ١٠٣',
    103, 5, 1, 95, 76, 38, 'false'
  );
  
  -- Ayah 104 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    597,
    'وَلَا تَهِنُوا۟ فِی ٱبۡتِغَاۤءِ ٱلۡقَوۡمِۖ إِن تَكُونُوا۟ تَأۡلَمُونَ فَإِنَّهُمۡ یَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا یَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمًا',
    'ولا تهنوا في ابتغاء القوم ان تكونوا تالمون فانهم يالمون كما تالمون وترجون من الله ما لا يرجون وكان الله عليما حكيما',
    'وَلَا تَهِنُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونُو<rule class=slnt>اۡ</rule> تَأۡلَمُونَ فَإِ<rule class=ghunnah>نّ</rule>َهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَ‌ۖ وَتَرۡجُونَ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَرۡجُونَ‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمًا حَكِيمًا ١٠٤',
    104, 5, 1, 95, 76, 38, 'false'
  );
  
  -- Ayah 105 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    598,
    'إِنَّاۤ أَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَیۡنَ ٱلنَّاسِ بِمَاۤ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَاۤىِٕنِینَ خَصِیمࣰا',
    'انا انزلنا اليك الكتاب بالحق لتحكم بين الناس بما اراك الله ولا تكن للخائنين خصيما',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ لِتَحۡكُمَ بَيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَرَ<rule class=madda_normal>ٮٰ</rule>كَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَلَا تَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡخ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنِينَ خَصِيمًا ١٠٥',
    105, 5, 1, 95, 77, 38, 'false'
  );
  
  -- Ayah 106 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    599,
    'وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا',
    'واستغفر الله ان الله كان غفورا رحيما',
    'وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرِ <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ١٠٦',
    106, 5, 1, 96, 77, 38, 'false'
  );
  
  -- Ayah 107 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    600,
    'وَلَا تُجَـٰدِلۡ عَنِ ٱلَّذِینَ یَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا یُحِبُّ مَن كَانَ خَوَّانًا أَثِیمࣰا',
    'ولا تجادل عن الذين يختانون انفسهم ان الله لا يحب من كان خوانا اثيما',
    'وَلَا تُجَ<rule class=madda_normal>ـٰ</rule>دِلۡ عَنِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَخۡتَانُونَ أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ خَوَّانًا أَثِيمًا ١٠٧',
    107, 5, 1, 96, 77, 38, 'false'
  );
  
  -- Ayah 108 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    601,
    'یَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا یَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ یُبَیِّتُونَ مَا لَا یَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا یَعۡمَلُونَ مُحِیطًا',
    'يستخفون من الناس ولا يستخفون من الله وهو معهم اذ يبيتون ما لا يرضى من القول وكان الله بما يعملون محيطا',
    'يَسۡتَخۡفُونَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَا يَسۡتَخۡفُونَ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا ١٠٨',
    108, 5, 1, 96, 77, 38, 'false'
  );
  
  -- Ayah 109 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    602,
    'هَـٰۤأَنتُمۡ هَـٰۤؤُلَاۤءِ جَـٰدَلۡتُمۡ عَنۡهُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا فَمَن یُجَـٰدِلُ ٱللَّهَ عَنۡهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ أَم مَّن یَكُونُ عَلَیۡهِمۡ وَكِیلࣰا',
    'ها انتم هؤلاء جادلتم عنهم في الحياة الدنيا فمن يجادل الله عنهم يوم القيامة ام من يكون عليهم وكيلا',
    'هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَ<rule class=ikhafa>نت</rule>ُمۡ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ جَ<rule class=madda_normal>ـٰ</rule>دَلۡتُمۡ عَنۡهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجَ<rule class=madda_normal>ـٰ</rule>دِلُ <rule class=ham_wasl>ٱ</rule>للَّهَ عَنۡهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ أ<rule class=idgham_shafawi>َم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونُ عَلَيۡهِمۡ وَكِيلاً ١٠٩',
    109, 5, 1, 96, 77, 38, 'false'
  );
  
  -- Ayah 110 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    603,
    'وَمَن یَعۡمَلۡ سُوۤءًا أَوۡ یَظۡلِمۡ نَفۡسَهُۥ ثُمَّ یَسۡتَغۡفِرِ ٱللَّهَ یَجِدِ ٱللَّهَ غَفُورࣰا رَّحِیمࣰا',
    'ومن يعمل سوءا او يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ يَسۡتَغۡفِرِ <rule class=ham_wasl>ٱ</rule>للَّهَ يَجِدِ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ١١٠',
    110, 5, 1, 96, 77, 38, 'false'
  );
  
  -- Ayah 111 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    604,
    'وَمَن یَكۡسِبۡ إِثۡمࣰا فَإِنَّمَا یَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا',
    'ومن يكسب اثما فانما يكسبه على نفسه وكان الله عليما حكيما',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡسِ<rule class=qalaqah>بۡ</rule> إِثۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َمَا يَكۡسِبُهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ نَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمًا حَكِيمًا ١١١',
    111, 5, 1, 96, 77, 38, 'false'
  );
  
  -- Ayah 112 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    605,
    'وَمَن یَكۡسِبۡ خَطِیۤـَٔةً أَوۡ إِثۡمࣰا ثُمَّ یَرۡمِ بِهِۦ بَرِیۤـࣰٔا فَقَدِ ٱحۡتَمَلَ بُهۡتَـٰنࣰا وَإِثۡمࣰا مُّبِینࣰا',
    'ومن يكسب خطيئة او اثما ثم يرم به بريئا فقد احتمل بهتانا واثما مبينا',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡسِ<rule class=qalaqah>بۡ</rule> خَطِ<rule class=madda_obligatory_mottasel>يٓ</rule>ــَٔةً أَوۡ إِثۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ يَرۡمِ بِه<rule class=madda_normal>ِۦ</rule> بَرِ<rule class=madda_obligatory_mottasel>يٓ</rule>ـ<rule class=ikhafa>ـًٔا</rule> <rule class=ikhafa>ف</rule>َقَدِ <rule class=ham_wasl>ٱ</rule>حۡتَمَلَ بُهۡتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َإِثۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ١١٢',
    112, 5, 1, 96, 77, 38, 'false'
  );
  
  -- Ayah 113 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    606,
    'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّاۤىِٕفَةࣱ مِّنۡهُمۡ أَن یُضِلُّوكَ وَمَا یُضِلُّونَ إِلَّاۤ أَنفُسَهُمۡۖ وَمَا یَضُرُّونَكَ مِن شَیۡءࣲۚ وَأَنزَلَ ٱللَّهُ عَلَیۡكَ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَیۡكَ عَظِیمࣰا',
    'ولولا فضل الله عليك ورحمته لهمت طائفة منهم ان يضلوك وما يضلون الا انفسهم وما يضرونك من شيء وانزل الله عليك الكتاب والحكمة وعلمك ما لم تكن تعلم وكان فضل الله عليك عظيما',
    'وَلَوۡلَا فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكَ وَرَحۡمَتُهُ<rule class=madda_normal>ۥ</rule> لَهَ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_mutajanisayn>ت</rule> طّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضِلُّوكَ وَمَا يُضِلُّونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ‌ۖ وَمَا يَضُرُّونَكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_ghunnah>َىۡءٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡلَمُ‌ۚ وَكَانَ فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكَ عَظِيمًا ١١٣',
    113, 5, 1, 96, 78, 38, 'false'
  );
  
  -- Ayah 114 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    607,
    '۞ لَّا خَیۡرَ فِی كَثِیرࣲ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَـٰحِۭ بَیۡنَ ٱلنَّاسِۚ وَمَن یَفۡعَلۡ ذَ ٰ⁠لِكَ ٱبۡتِغَاۤءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِیهِ أَجۡرًا عَظِیمࣰا',
    'لا خير في كثير من نجواهم الا من امر بصدقة او معروف او اصلاح بين الناس ومن يفعل ذلك ابتغاء مرضات الله فسوف نؤتيه اجرا عظيما',
    '۞لَّا خَيۡرَ فِى كَثِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>جۡ</rule>وَ<rule class=madda_normal>ٮٰ</rule>هُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>حِۭ</rule> <rule class=iqlab>ب</rule>َيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلۡ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَرۡضَاتِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَسَوۡفَ نُؤۡتِيهِ أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ١١٤',
    114, 5, 1, 97, 78, 39, 'false'
  );
  
  -- Ayah 115 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    608,
    'وَمَن یُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَیَّنَ لَهُ ٱلۡهُدَىٰ وَیَتَّبِعۡ غَیۡرَ سَبِیلِ ٱلۡمُؤۡمِنِینَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَاۤءَتۡ مَصِیرًا',
    'ومن يشاقق الرسول من بعد ما تبين له الهدى ويتبع غير سبيل المؤمنين نوله ما تولى ونصله جهنم وساءت مصيرا',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُشَاقِقِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا تَبَيَّنَ لَهُ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ نُوَلِّه<rule class=madda_normal>ِۦ</rule> مَا تَوَلَّىٰ وَنُصۡلِه<rule class=madda_normal>ِۦ</rule> جَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۖ وَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ مَصِيرًا ١١٥',
    115, 5, 1, 97, 78, 39, 'false'
  );
  
  -- Ayah 116 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    609,
    'إِنَّ ٱللَّهَ لَا یَغۡفِرُ أَن یُشۡرَكَ بِهِۦ وَیَغۡفِرُ مَا دُونَ ذَ ٰ⁠لِكَ لِمَن یَشَاۤءُۚ وَمَن یُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَـٰلَۢا بَعِیدًا',
    'ان الله لا يغفر ان يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد ضل ضلالا بعيدا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَغۡفِرُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُشۡرَكَ بِه<rule class=madda_normal>ِۦ</rule> وَيَغۡفِرُ مَا دُونَ ذ<rule class=madda_normal>ٰ</rule>لِكَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُشۡرِكۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ فَقَ<rule class=qalaqah>دۡ</rule> ضَلَّ ضَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=iqlab>اَۢ</rule> <rule class=iqlab>ب</rule>َعِيدًا ١١٦',
    116, 5, 1, 97, 79, 39, 'false'
  );
  
  -- Ayah 117 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    610,
    'إِن یَدۡعُونَ مِن دُونِهِۦۤ إِلَّاۤ إِنَـٰثࣰا وَإِن یَدۡعُونَ إِلَّا شَیۡطَـٰنࣰا مَّرِیدࣰا',
    'ان يدعون من دونه الا اناثا وان يدعون الا شيطانا مريدا',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>ثًا</rule> <rule class=idgham_ghunnah>و</rule>َإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>عُونَ إِلَّا شَيۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>َّرِيدًا ١١٧',
    117, 5, 1, 97, 79, 39, 'false'
  );
  
  -- Ayah 118 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    611,
    'لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِیبࣰا مَّفۡرُوضࣰا',
    'لعنه الله وقال لاتخذن من عبادك نصيبا مفروضا',
    'لَّعَنَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۘ وَقَالَ لَأَتَّخِذَ<rule class=ghunnah>نّ</rule>َ مِنۡ عِبَادِكَ نَصِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>َّفۡرُوضًا ١١٨',
    118, 5, 1, 97, 79, 39, 'false'
  );
  
  -- Ayah 119 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    612,
    'وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّیَنَّهُمۡ وَلَـَٔامُرَنَّهُمۡ فَلَیُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَـٰمِ وَلَـَٔامُرَنَّهُمۡ فَلَیُغَیِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن یَتَّخِذِ ٱلشَّیۡطَـٰنَ وَلِیࣰّا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانࣰا مُّبِینࣰا',
    'ولاضلنهم ولامنينهم ولامرنهم فليبتكن اذان الانعام ولامرنهم فليغيرن خلق الله ومن يتخذ الشيطان وليا من دون الله فقد خسر خسرانا مبينا',
    'وَلَأُضِلَّ<rule class=ghunnah>نّ</rule>َهُمۡ وَلَأُمَ<rule class=ghunnah>نّ</rule>ِيَ<rule class=ghunnah>نّ</rule>َهُمۡ وَلَأَمُرَ<rule class=ghunnah>نّ</rule>َهُمۡ فَلَيُبَتِّكُ<rule class=ghunnah>نّ</rule>َ ءَاذَانَ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ وَلَأَمُرَ<rule class=ghunnah>نّ</rule>َهُمۡ فَلَيُغَيِّرُ<rule class=ghunnah>نّ</rule>َ خَلۡقَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَقَ<rule class=qalaqah>دۡ</rule> خَسِرَ خُسۡرَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ١١٩',
    119, 5, 1, 97, 79, 39, 'false'
  );
  
  -- Ayah 120 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    613,
    'یَعِدُهُمۡ وَیُمَنِّیهِمۡۖ وَمَا یَعِدُهُمُ ٱلشَّیۡطَـٰنُ إِلَّا غُرُورًا',
    'يعدهم ويمنيهم وما يعدهم الشيطان الا غرورا',
    'يَعِدُهُمۡ وَيُمَ<rule class=ghunnah>نّ</rule>ِيهِمۡ‌ۖ وَمَا يَعِدُهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ إِلَّا غُرُورًا ١٢٠',
    120, 5, 1, 97, 79, 39, 'false'
  );
  
  -- Ayah 121 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    614,
    'أُو۟لَـٰۤىِٕكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا یَجِدُونَ عَنۡهَا مَحِیصࣰا',
    'اولئك ماواهم جهنم ولا يجدون عنها محيصا',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصًا ١٢١',
    121, 5, 1, 97, 79, 39, 'false'
  );
  
  -- Ayah 122 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    615,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ وَعۡدَ ٱللَّهِ حَقࣰّاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِیلࣰا',
    'والذين امنوا وعملوا الصالحات سندخلهم جنات تجري من تحتها الانهار خالدين فيها ابدا وعد الله حقا ومن اصدق من الله قيلا',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ سَنُ<rule class=qalaqah>دۡ</rule>خِلُهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=idgham_ghunnah>دًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَق<rule class=idgham_ghunnah>ًّا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَنۡ أَصۡدَقُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ قِيلاً ١٢٢',
    122, 5, 1, 98, 79, 39, 'false'
  );
  
  -- Ayah 123 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    616,
    'لَّیۡسَ بِأَمَانِیِّكُمۡ وَلَاۤ أَمَانِیِّ أَهۡلِ ٱلۡكِتَـٰبِۗ مَن یَعۡمَلۡ سُوۤءࣰا یُجۡزَ بِهِۦ وَلَا یَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِیࣰّا وَلَا نَصِیرࣰا',
    'ليس بامانيكم ولا اماني اهل الكتاب من يعمل سوءا يجز به ولا يجد له من دون الله وليا ولا نصيرا',
    'لَّيۡسَ بِأَمَانِيِّكُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَمَانِىِّ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ‌ۗ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=idgham_ghunnah>ءًا</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>جۡ</rule>زَ بِه<rule class=madda_normal>ِۦ</rule> وَلَا يَجِ<rule class=qalaqah>دۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصِيرًا ١٢٣',
    123, 5, 1, 98, 79, 39, 'false'
  );
  
  -- Ayah 124 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    617,
    'وَمَن یَعۡمَلۡ مِنَ ٱلصَّـٰلِحَـٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَأُو۟لَـٰۤىِٕكَ یَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا یُظۡلَمُونَ نَقِیرࣰا',
    'ومن يعمل من الصالحات من ذكر او انثى وهو مؤمن فاولئك يدخلون الجنة ولا يظلمون نقيرا',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلۡ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َكَرٍ أَوۡ أُ<rule class=ikhafa>نث</rule>َىٰ وَهُوَ مُؤۡمِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَ<rule class=qalaqah>دۡ</rule>خُلُونَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ وَلَا يُظۡلَمُونَ نَقِيرًا ١٢٤',
    124, 5, 1, 98, 79, 39, 'false'
  );
  
  -- Ayah 125 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    618,
    'وَمَنۡ أَحۡسَنُ دِینࣰا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنࣱ وَٱتَّبَعَ مِلَّةَ إِبۡرَ ٰ⁠هِیمَ حَنِیفࣰاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَ ٰ⁠هِیمَ خَلِیلࣰا',
    'ومن احسن دينا ممن اسلم وجهه لله وهو محسن واتبع ملة ابراهيم حنيفا واتخذ الله ابراهيم خليلا',
    'وَمَنۡ أَحۡسَنُ دِي<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َنۡ أَسۡلَمَ وَ<rule class=qalaqah>جۡ</rule>هَهُ<rule class=madda_normal>ۥ</rule> لِلَّهِ وَهُوَ مُحۡسِ<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّبَعَ مِلَّةَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ حَنِي<rule class=idgham_ghunnah>فًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ خَلِيلاً ١٢٥',
    125, 5, 1, 98, 79, 39, 'false'
  );
  
  -- Ayah 126 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    619,
    'وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَیۡءࣲ مُّحِیطࣰا',
    'ولله ما في السماوات وما في الارض وكان الله بكل شيء محيطا',
    'وَلِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّحِيطًا ١٢٦',
    126, 5, 1, 98, 79, 39, 'false'
  );
  
  -- Ayah 127 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    620,
    'وَیَسۡتَفۡتُونَكَ فِی ٱلنِّسَاۤءِۖ قُلِ ٱللَّهُ یُفۡتِیكُمۡ فِیهِنَّ وَمَا یُتۡلَىٰ عَلَیۡكُمۡ فِی ٱلۡكِتَـٰبِ فِی یَتَـٰمَى ٱلنِّسَاۤءِ ٱلَّـٰتِی لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِینَ مِنَ ٱلۡوِلۡدَ ٰ⁠نِ وَأَن تَقُومُوا۟ لِلۡیَتَـٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُوا۟ مِنۡ خَیۡرࣲ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِیمࣰا',
    'ويستفتونك في النساء قل الله يفتيكم فيهن وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تؤتونهن ما كتب لهن وترغبون ان تنكحوهن والمستضعفين من الولدان وان تقوموا لليتامى بالقسط وما تفعلوا من خير فان الله كان به عليما',
    'وَيَسۡتَفۡتُونَكَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۖ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ يُفۡتِيكُمۡ فِيهِ<rule class=ghunnah>نّ</rule>َ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ فِى يَتَ<rule class=madda_normal>ـٰ</rule>مَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>تِى لَا تُؤۡتُونَهُ<rule class=ghunnah>نّ</rule>َ مَا كُتِبَ لَهُ<rule class=ghunnah>نّ</rule>َ وَتَرۡغَبُونَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نك</rule>ِحُوهُ<rule class=ghunnah>نّ</rule>َ وَ<rule class=ham_wasl>ٱ</rule>لۡمُسۡتَضۡعَفِينَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡوِلۡد<rule class=madda_normal>ٰ</rule>نِ وَأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُومُو<rule class=slnt>اۡ</rule> لِلۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۚ وَمَا تَفۡعَلُو<rule class=slnt>اۡ</rule> مِنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِه<rule class=madda_normal>ِۦ</rule> عَلِيمًا ١٢٧',
    127, 5, 1, 98, 80, 39, 'false'
  );
  
  -- Ayah 128 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    621,
    'وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضࣰا فَلَا جُنَاحَ عَلَیۡهِمَاۤ أَن یُصۡلِحَا بَیۡنَهُمَا صُلۡحࣰاۚ وَٱلصُّلۡحُ خَیۡرࣱۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا',
    'وان امراة خافت من بعلها نشوزا او اعراضا فلا جناح عليهما ان يصلحا بينهما صلحا والصلح خير واحضرت الانفس الشح وان تحسنوا وتتقوا فان الله كان بما تعملون خبيرا',
    'وَإِنِ <rule class=ham_wasl>ٱ</rule>مۡرَأَةٌ خَافَتۡ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡلِهَا نُشُوزًا أَوۡ إِعۡرَا<rule class=ikhafa>ضًا</rule> <rule class=ikhafa>ف</rule>َلَا جُنَاحَ عَلَيۡهِم<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُصۡلِحَا بَيۡنَهُمَا صُلۡ<rule class=idgham_ghunnah>حًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّلۡحُ خَيۡ<rule class=idgham_ghunnah>رٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َأُحۡضِرَتِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>ُسُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّحَّ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُحۡسِنُو<rule class=slnt>اۡ</rule> وَتَتَّقُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرًا ١٢٨',
    128, 5, 1, 99, 80, 39, 'false'
  );
  
  -- Ayah 129 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    622,
    'وَلَن تَسۡتَطِیعُوۤا۟ أَن تَعۡدِلُوا۟ بَیۡنَ ٱلنِّسَاۤءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِیلُوا۟ كُلَّ ٱلۡمَیۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا',
    'ولن تستطيعوا ان تعدلوا بين النساء ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقة وان تصلحوا وتتقوا فان الله كان غفورا رحيما',
    'وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَطِيع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡدِلُو<rule class=slnt>اۡ</rule> بَيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَلَوۡ حَرَصۡتُمۡ‌ۖ فَلَا تَمِيلُو<rule class=slnt>اۡ</rule> كُلَّ <rule class=ham_wasl>ٱ</rule>لۡمَيۡلِ فَتَذَرُوهَا كَ<rule class=ham_wasl>ٱ</rule>لۡمُعَلَّقَةِ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصۡلِحُو<rule class=slnt>اۡ</rule> وَتَتَّقُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ١٢٩',
    129, 5, 1, 99, 80, 39, 'false'
  );
  
  -- Ayah 130 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    623,
    'وَإِن یَتَفَرَّقَا یُغۡنِ ٱللَّهُ كُلࣰّا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَ ٰ⁠سِعًا حَكِیمࣰا',
    'وان يتفرقا يغن الله كلا من سعته وكان الله واسعا حكيما',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَرَّقَا يُغۡنِ <rule class=ham_wasl>ٱ</rule>للَّهُ كُل<rule class=idgham_ghunnah>اًّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َعَتِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ و<rule class=madda_normal>ٰ</rule>سِعًا حَكِيمًا ١٣٠',
    130, 5, 1, 99, 80, 39, 'false'
  );
  
  -- Ayah 131 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    624,
    'وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّیۡنَا ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلِكُمۡ وَإِیَّاكُمۡ أَنِ ٱتَّقُوا۟ ٱللَّهَۚ وَإِن تَكۡفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِیًّا حَمِیدࣰا',
    'ولله ما في السماوات وما في الارض ولقد وصينا الذين اوتوا الكتاب من قبلكم واياكم ان اتقوا الله وان تكفروا فان لله ما في السماوات وما في الارض وكان الله غنيا حميدا',
    'وَلِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَلَقَ<rule class=qalaqah>دۡ</rule> وَصَّيۡنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ وَإِيَّاكُمۡ أَنِ <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكۡفُرُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَنِيًّا حَمِيدًا ١٣١',
    131, 5, 1, 99, 80, 39, 'false'
  );
  
  -- Ayah 132 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    625,
    'وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلًا',
    'ولله ما في السماوات وما في الارض وكفى بالله وكيلا',
    'وَلِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَكِيلاً ١٣٢',
    132, 5, 1, 99, 80, 39, 'false'
  );
  
  -- Ayah 133 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    626,
    'إِن یَشَأۡ یُذۡهِبۡكُمۡ أَیُّهَا ٱلنَّاسُ وَیَأۡتِ بِـَٔاخَرِینَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَ ٰ⁠لِكَ قَدِیرࣰا',
    'ان يشا يذهبكم ايها الناس ويات باخرين وكان الله على ذلك قديرا',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َشَأۡ يُذۡهِ<rule class=qalaqah>بۡ</rule>كُمۡ أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ وَيَأۡتِ بِـَٔـاخَرِينَ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ ذ<rule class=madda_normal>ٰ</rule>لِكَ قَدِيرًا ١٣٣',
    133, 5, 1, 99, 80, 39, 'false'
  );
  
  -- Ayah 134 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    627,
    'مَّن كَانَ یُرِیدُ ثَوَابَ ٱلدُّنۡیَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۚ وَكَانَ ٱللَّهُ سَمِیعَۢا بَصِیرࣰا',
    'من كان يريد ثواب الدنيا فعند الله ثواب الدنيا والاخرة وكان الله سميعا بصيرا',
    'مَّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يُرِيدُ ثَوَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا فَعِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ ثَوَابُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيع<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َصِيرًا ١٣٤',
    134, 5, 1, 99, 80, 39, 'false'
  );
  
  -- Ayah 135 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    628,
    '۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُونُوا۟ قَوَّ ٰ⁠مِینَ بِٱلۡقِسۡطِ شُهَدَاۤءَ لِلَّهِ وَلَوۡ عَلَىٰۤ أَنفُسِكُمۡ أَوِ ٱلۡوَ ٰ⁠لِدَیۡنِ وَٱلۡأَقۡرَبِینَۚ إِن یَكُنۡ غَنِیًّا أَوۡ فَقِیرࣰا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُوا۟ ٱلۡهَوَىٰۤ أَن تَعۡدِلُوا۟ۚ وَإِن تَلۡوُۥۤا۟ أَوۡ تُعۡرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا',
    'يا ايها الذين امنوا كونوا قوامين بالقسط شهداء لله ولو على انفسكم او الوالدين والاقربين ان يكن غنيا او فقيرا فالله اولى بهما فلا تتبعوا الهوى ان تعدلوا وان تلووا او تعرضوا فان الله كان بما تعملون خبيرا',
    '۞يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> كُونُو<rule class=slnt>اۡ</rule> قَوّ<rule class=madda_normal>ٰ</rule>مِينَ بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لِلَّهِ وَلَوۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ أَوِ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِدَيۡنِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>رَبِينَ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َكُنۡ غَنِيًّا أَوۡ فَقِي<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ أَوۡلَىٰ بِهِمَا‌ۖ فَلَا تَتَّبِعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡهَوَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡدِلُو<rule class=slnt>اۡ‌ۚ</rule> وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َلۡوُ<rule class=madda_obligatory_monfasel>ۥٓاۡ</rule> أَوۡ تُعۡرِضُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرًا ١٣٥',
    135, 5, 1, 100, 81, 40, 'false'
  );
  
  -- Ayah 136 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    629,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَـٰبِ ٱلَّذِی نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَـٰبِ ٱلَّذِیۤ أَنزَلَ مِن قَبۡلُۚ وَمَن یَكۡفُرۡ بِٱللَّهِ وَمَلَـٰۤىِٕكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ فَقَدۡ ضَلَّ ضَلَـٰلَۢا بَعِیدًا',
    'يا ايها الذين امنوا امنوا بالله ورسوله والكتاب الذي نزل على رسوله والكتاب الذي انزل من قبل ومن يكفر بالله وملائكته وكتبه ورسله واليوم الاخر فقد ضل ضلالا بعيدا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لَّذِى نَزَّلَ عَلَىٰ رَسُولِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَتِه<rule class=madda_normal>ِۦ</rule> وَكُتُبِه<rule class=madda_normal>ِۦ</rule> وَرُسُلِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ فَقَ<rule class=qalaqah>دۡ</rule> ضَلَّ ضَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=iqlab>اَۢ</rule> <rule class=iqlab>ب</rule>َعِيدًا ١٣٦',
    136, 5, 1, 100, 81, 40, 'false'
  );
  
  -- Ayah 137 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    630,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزۡدَادُوا۟ كُفۡرࣰا لَّمۡ یَكُنِ ٱللَّهُ لِیَغۡفِرَ لَهُمۡ وَلَا لِیَهۡدِیَهُمۡ سَبِیلَۢا',
    'ان الذين امنوا ثم كفروا ثم امنوا ثم كفروا ثم ازدادوا كفرا لم يكن الله ليغفر لهم ولا ليهديهم سبيلا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ كَفَرُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ ءَامَنُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ كَفَرُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>زۡدَادُو<rule class=slnt>اۡ</rule> كُفۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَكُنِ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلاَۢ ١٣٧',
    137, 5, 1, 100, 81, 40, 'false'
  );
  
  -- Ayah 138 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    631,
    'بَشِّرِ ٱلۡمُنَـٰفِقِینَ بِأَنَّ لَهُمۡ عَذَابًا أَلِیمًا',
    'بشر المنافقين بان لهم عذابا اليما',
    'بَشِّرِ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ بِأَ<rule class=ghunnah>نّ</rule>َ لَهُمۡ عَذَابًا أَلِيمًا ١٣٨',
    138, 5, 1, 100, 81, 40, 'false'
  );
  
  -- Ayah 139 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    632,
    'ٱلَّذِینَ یَتَّخِذُونَ ٱلۡكَـٰفِرِینَ أَوۡلِیَاۤءَ مِن دُونِ ٱلۡمُؤۡمِنِینَۚ أَیَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِیعࣰا',
    'الذين يتخذون الكافرين اولياء من دون المؤمنين ايبتغون عندهم العزة فان العزة لله جميعا',
    'ٱلَّذِينَ يَتَّخِذُونَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ‌ۚ أَيَ<rule class=qalaqah>بۡ</rule>تَغُونَ عِ<rule class=ikhafa>ند</rule>َهُمُ <rule class=ham_wasl>ٱ</rule>لۡعِزَّةَ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعِزَّةَ لِلَّهِ جَمِيعًا ١٣٩',
    139, 5, 1, 100, 81, 40, 'false'
  );
  
  -- Ayah 140 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    633,
    'وَقَدۡ نَزَّلَ عَلَیۡكُمۡ فِی ٱلۡكِتَـٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَایَـٰتِ ٱللَّهِ یُكۡفَرُ بِهَا وَیُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُوا۟ مَعَهُمۡ حَتَّىٰ یَخُوضُوا۟ فِی حَدِیثٍ غَیۡرِهِۦۤ إِنَّكُمۡ إِذࣰا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَـٰفِقِینَ وَٱلۡكَـٰفِرِینَ فِی جَهَنَّمَ جَمِیعًا',
    'وقد نزل عليكم في الكتاب ان اذا سمعتم ايات الله يكفر بها ويستهزا بها فلا تقعدوا معهم حتى يخوضوا في حديث غيره انكم اذا مثلهم ان الله جامع المنافقين والكافرين في جهنم جميعا',
    'وَقَ<rule class=qalaqah>دۡ</rule> نَزَّلَ عَلَيۡكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَ<rule class=qalaqah>قۡ</rule>عُدُو<rule class=slnt>اۡ</rule> مَعَهُمۡ حَتَّىٰ يَخُوضُو<rule class=slnt>اۡ</rule> فِى حَدِيثٍ غَيۡرِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َكُمۡ إِ<rule class=idgham_ghunnah>ذًا</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُهُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ جَامِعُ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ فِى جَهَ<rule class=ghunnah>نّ</rule>َمَ جَمِيعًا ١٤٠',
    140, 5, 1, 100, 81, 40, 'false'
  );
  
  -- Ayah 141 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    634,
    'ٱلَّذِینَ یَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحࣱ مِّنَ ٱللَّهِ قَالُوۤا۟ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَـٰفِرِینَ نَصِیبࣱ قَالُوۤا۟ أَلَمۡ نَسۡتَحۡوِذۡ عَلَیۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِینَۚ فَٱللَّهُ یَحۡكُمُ بَیۡنَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۗ وَلَن یَجۡعَلَ ٱللَّهُ لِلۡكَـٰفِرِینَ عَلَى ٱلۡمُؤۡمِنِینَ سَبِیلًا',
    'الذين يتربصون بكم فان كان لكم فتح من الله قالوا الم نكن معكم وان كان للكافرين نصيب قالوا الم نستحوذ عليكم ونمنعكم من المؤمنين فالله يحكم بينكم يوم القيامة ولن يجعل الله للكافرين على المؤمنين سبيلا',
    'ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ لَكُمۡ فَتۡ<rule class=idgham_ghunnah>حٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَلَمۡ نَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>َّعَكُمۡ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ نَصِي<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>عَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ سَبِيلاً ١٤١',
    141, 5, 1, 101, 81, 40, 'false'
  );
  
  -- Ayah 142 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    635,
    'إِنَّ ٱلۡمُنَـٰفِقِینَ یُخَـٰدِعُونَ ٱللَّهَ وَهُوَ خَـٰدِعُهُمۡ وَإِذَا قَامُوۤا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ یُرَاۤءُونَ ٱلنَّاسَ وَلَا یَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِیلࣰا',
    'ان المنافقين يخادعون الله وهو خادعهم واذا قاموا الى الصلاة قاموا كسالى يراءون الناس ولا يذكرون الله الا قليلا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ يُخَ<rule class=madda_normal>ـٰ</rule>دِعُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَهُوَ خَ<rule class=madda_normal>ـٰ</rule>دِعُهُمۡ وَإِذَا قَام<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ قَامُو<rule class=slnt>اۡ</rule> كُسَالَىٰ يُر<rule class=madda_obligatory_mottasel>َا</rule>ٓءُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ وَلَا يَذۡكُرُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ إِلَّا قَلِيلاً ١٤٢',
    142, 5, 1, 101, 82, 40, 'false'
  );
  
  -- Ayah 143 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    636,
    'مُّذَبۡذَبِینَ بَیۡنَ ذَ ٰ⁠لِكَ لَاۤ إِلَىٰ هَـٰۤؤُلَاۤءِ وَلَاۤ إِلَىٰ هَـٰۤؤُلَاۤءِۚ وَمَن یُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِیلࣰا',
    'مذبذبين بين ذلك لا الى هؤلاء ولا الى هؤلاء ومن يضلل الله فلن تجد له سبيلا',
    'مُّذَ<rule class=qalaqah>بۡ</rule>ذَبِينَ بَيۡنَ ذ<rule class=madda_normal>ٰ</rule>لِكَ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لَهُ<rule class=madda_normal>ۥ</rule> سَبِيلاً ١٤٣',
    143, 5, 1, 101, 82, 40, 'false'
  );
  
  -- Ayah 144 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    637,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلۡكَـٰفِرِینَ أَوۡلِیَاۤءَ مِن دُونِ ٱلۡمُؤۡمِنِینَۚ أَتُرِیدُونَ أَن تَجۡعَلُوا۟ لِلَّهِ عَلَیۡكُمۡ سُلۡطَـٰنࣰا مُّبِینًا',
    'يا ايها الذين امنوا لا تتخذوا الكافرين اولياء من دون المؤمنين اتريدون ان تجعلوا لله عليكم سلطانا مبينا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَتَّخِذُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ‌ۚ أَتُرِيدُونَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>عَلُو<rule class=slnt>اۡ</rule> لِلَّهِ عَلَيۡكُمۡ سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ١٤٤',
    144, 5, 1, 101, 82, 40, 'false'
  );
  
  -- Ayah 145 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    638,
    'إِنَّ ٱلۡمُنَـٰفِقِینَ فِی ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِیرًا',
    'ان المنافقين في الدرك الاسفل من النار ولن تجد لهم نصيرا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّرۡكِ <rule class=ham_wasl>ٱ</rule>لۡأَسۡفَلِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لَهُمۡ نَصِيرًا ١٤٥',
    145, 5, 1, 101, 82, 40, 'false'
  );
  
  -- Ayah 146 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    639,
    'إِلَّا ٱلَّذِینَ تَابُوا۟ وَأَصۡلَحُوا۟ وَٱعۡتَصَمُوا۟ بِٱللَّهِ وَأَخۡلَصُوا۟ دِینَهُمۡ لِلَّهِ فَأُو۟لَـٰۤىِٕكَ مَعَ ٱلۡمُؤۡمِنِینَۖ وَسَوۡفَ یُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِینَ أَجۡرًا عَظِیمࣰا',
    'الا الذين تابوا واصلحوا واعتصموا بالله واخلصوا دينهم لله فاولئك مع المؤمنين وسوف يؤت الله المؤمنين اجرا عظيما',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَابُو<rule class=slnt>اۡ</rule> وَأَصۡلَحُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>عۡتَصَمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَأَخۡلَصُو<rule class=slnt>اۡ</rule> دِينَهُمۡ لِلَّهِ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مَعَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ‌ۖ وَسَوۡفَ يُؤۡتِ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ١٤٦',
    146, 5, 1, 101, 82, 40, 'false'
  );
  
  -- Ayah 147 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    640,
    'مَّا یَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِیمࣰا',
    'ما يفعل الله بعذابكم ان شكرتم وامنتم وكان الله شاكرا عليما',
    'مَّا يَفۡعَلُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِعَذَابِكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َكَرۡتُمۡ وَءَامَ<rule class=ikhafa>نت</rule>ُمۡ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ شَاكِرًا عَلِيمًا ١٤٧',
    147, 5, 1, 101, 82, 40, 'false'
  );
  
  -- Ayah 148 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    641,
    '۞ لَّا یُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوۤءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِیعًا عَلِیمًا',
    'لا يحب الله الجهر بالسوء من القول الا من ظلم وكان الله سميعا عليما',
    '۞لَّا يُحِبُّ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡجَهۡرَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>ُلِمَ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعًا عَلِيمًا ١٤٨',
    148, 6, 1, 102, 82, 41, 'false'
  );
  
  -- Ayah 149 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    642,
    'إِن تُبۡدُوا۟ خَیۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُوا۟ عَن سُوۤءࣲ فَإِنَّ ٱللَّهَ كَانَ عَفُوࣰّا قَدِیرًا',
    'ان تبدوا خيرا او تخفوه او تعفوا عن سوء فان الله كان عفوا قديرا',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>بۡ</rule>دُو<rule class=slnt>اۡ</rule> خَيۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَفُو<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ق</rule>َدِيرًا ١٤٩',
    149, 6, 1, 102, 82, 41, 'false'
  );
  
  -- Ayah 150 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    643,
    'إِنَّ ٱلَّذِینَ یَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَیُرِیدُونَ أَن یُفَرِّقُوا۟ بَیۡنَ ٱللَّهِ وَرُسُلِهِۦ وَیَقُولُونَ نُؤۡمِنُ بِبَعۡضࣲ وَنَكۡفُرُ بِبَعۡضࣲ وَیُرِیدُونَ أَن یَتَّخِذُوا۟ بَیۡنَ ذَ ٰ⁠لِكَ سَبِیلًا',
    'ان الذين يكفرون بالله ورسله ويريدون ان يفرقوا بين الله ورسله ويقولون نؤمن ببعض ونكفر ببعض ويريدون ان يتخذوا بين ذلك سبيلا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَكۡفُرُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرُسُلِه<rule class=madda_normal>ِۦ</rule> وَيُرِيدُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُفَرِّقُو<rule class=slnt>اۡ</rule> بَيۡنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرُسُلِه<rule class=madda_normal>ِۦ</rule> وَيَقُولُونَ نُؤۡمِنُ بِبَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>و</rule>َنَكۡفُرُ بِبَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>و</rule>َيُرِيدُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذُو<rule class=slnt>اۡ</rule> بَيۡنَ ذ<rule class=madda_normal>ٰ</rule>لِكَ سَبِيلاً ١٥٠',
    150, 6, 1, 102, 82, 41, 'false'
  );
  
  -- Ayah 151 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    644,
    'أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡكَـٰفِرُونَ حَقࣰّاۚ وَأَعۡتَدۡنَا لِلۡكَـٰفِرِینَ عَذَابࣰا مُّهِینࣰا',
    'اولئك هم الكافرون حقا واعتدنا للكافرين عذابا مهينا',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرُونَ حَق<rule class=idgham_ghunnah>ًّا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ُّهِينًا ١٥١',
    151, 6, 1, 102, 82, 41, 'false'
  );
  
  -- Ayah 152 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    645,
    'وَٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ یُفَرِّقُوا۟ بَیۡنَ أَحَدࣲ مِّنۡهُمۡ أُو۟لَـٰۤىِٕكَ سَوۡفَ یُؤۡتِیهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا',
    'والذين امنوا بالله ورسله ولم يفرقوا بين احد منهم اولئك سوف يؤتيهم اجورهم وكان الله غفورا رحيما',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرُسُلِه<rule class=madda_normal>ِۦ</rule> وَلَمۡ يُفَرِّقُو<rule class=slnt>اۡ</rule> بَيۡنَ أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ سَوۡفَ يُؤۡتِيهِمۡ أُجُورَهُمۡ‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ١٥٢',
    152, 6, 1, 102, 82, 41, 'false'
  );
  
  -- Ayah 153 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    646,
    'یَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَـٰبِ أَن تُنَزِّلَ عَلَیۡهِمۡ كِتَـٰبࣰا مِّنَ ٱلسَّمَاۤءِۚ فَقَدۡ سَأَلُوا۟ مُوسَىٰۤ أَكۡبَرَ مِن ذَ ٰ⁠لِكَ فَقَالُوۤا۟ أَرِنَا ٱللَّهَ جَهۡرَةࣰ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُوا۟ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَـٰتُ فَعَفَوۡنَا عَن ذَ ٰ⁠لِكَۚ وَءَاتَیۡنَا مُوسَىٰ سُلۡطَـٰنࣰا مُّبِینࣰا',
    'يسالك اهل الكتاب ان تنزل عليهم كتابا من السماء فقد سالوا موسى اكبر من ذلك فقالوا ارنا الله جهرة فاخذتهم الصاعقة بظلمهم ثم اتخذوا العجل من بعد ما جاءتهم البينات فعفونا عن ذلك واتينا موسى سلطانا مبينا',
    'يَسۡــَٔلُكَ أَهۡلُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُنَزِّلَ عَلَيۡهِمۡ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ فَقَ<rule class=qalaqah>دۡ</rule> سَأَلُو<rule class=slnt>اۡ</rule> مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَكۡبَرَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ فَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَرِنَا <rule class=ham_wasl>ٱ</rule>للَّهَ جَهۡرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َأَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>عِقَةُ بِظُلۡمِهِمۡ‌ۚ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِ<rule class=qalaqah>جۡ</rule>لَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تُ فَعَفَوۡنَا عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ‌ۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ١٥٣',
    153, 6, 1, 102, 83, 41, 'false'
  );
  
  -- Ayah 154 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    647,
    'وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِیثَـٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُوا۟ ٱلۡبَابَ سُجَّدࣰا وَقُلۡنَا لَهُمۡ لَا تَعۡدُوا۟ فِی ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّیثَـٰقًا غَلِیظࣰا',
    'ورفعنا فوقهم الطور بميثاقهم وقلنا لهم ادخلوا الباب سجدا وقلنا لهم لا تعدوا في السبت واخذنا منهم ميثاقا غليظا',
    'وَرَفَعۡنَا فَوۡقَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّورَ بِمِيثَ<rule class=madda_normal>ـٰ</rule>قِهِمۡ وَقُلۡنَا لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡبَابَ سُجَّ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َقُلۡنَا لَهُمۡ لَا تَعۡدُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=qalaqah>بۡ</rule>تِ وَأَخَذۡنَا مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule>قًا غَلِيظًا ١٥٤',
    154, 6, 1, 102, 83, 41, 'false'
  );
  
  -- Ayah 155 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    648,
    'فَبِمَا نَقۡضِهِم مِّیثَـٰقَهُمۡ وَكُفۡرِهِم بِـَٔایَـٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِیَاۤءَ بِغَیۡرِ حَقࣲّ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَیۡهَا بِكُفۡرِهِمۡ فَلَا یُؤۡمِنُونَ إِلَّا قَلِیلࣰا',
    'فبما نقضهم ميثاقهم وكفرهم بايات الله وقتلهم الانبياء بغير حق وقولهم قلوبنا غلف بل طبع الله عليها بكفرهم فلا يؤمنون الا قليلا',
    'فَبِمَا نَ<rule class=qalaqah>قۡ</rule>ضِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule>قَهُمۡ وَكُفۡرِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَقَتۡلِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=iqlab>نۢب</rule>ِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِغَيۡرِ حَ<rule class=idgham_ghunnah>قٍّ</rule> <rule class=idgham_ghunnah>و</rule>َقَوۡلِهِمۡ قُلُوبُنَا غُلۡ<rule class=iqlab>فُۢ‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ طَبَعَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلاً ١٥٥',
    155, 6, 1, 103, 83, 41, 'false'
  );
  
  -- Ayah 156 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    649,
    'وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡیَمَ بُهۡتَـٰنًا عَظِیمࣰا',
    'وبكفرهم وقولهم على مريم بهتانا عظيما',
    'وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَ<rule class=madda_normal>ـٰ</rule>نًا عَظِيمًا ١٥٦',
    156, 6, 1, 103, 83, 41, 'false'
  );
  
  -- Ayah 157 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    650,
    'وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِیحَ عِیسَى ٱبۡنَ مَرۡیَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَـٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِینَ ٱخۡتَلَفُوا۟ فِیهِ لَفِی شَكࣲّ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ یَقِینَۢا',
    'وقولهم انا قتلنا المسيح عيسى ابن مريم رسول الله وما قتلوه وما صلبوه ولكن شبه لهم وان الذين اختلفوا فيه لفي شك منه ما لهم به من علم الا اتباع الظن وما قتلوه يقينا',
    'وَقَوۡلِهِمۡ إِ<rule class=ghunnah>نّ</rule>َا قَتَلۡنَا <rule class=ham_wasl>ٱ</rule>لۡمَسِيحَ عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ رَسُولَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ُبِّهَ لَهُمۡ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> فِيهِ لَفِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ‌ۚ مَا لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مِنۡ عِلۡمٍ إِلَّا <rule class=ham_wasl>ٱ</rule>تِّبَاعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>ِ‌ۚ وَمَا قَتَلُوهُ يَقِينَۢا ١٥٧',
    157, 6, 1, 103, 83, 41, 'false'
  );
  
  -- Ayah 158 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    651,
    'بَل رَّفَعَهُ ٱللَّهُ إِلَیۡهِۚ وَكَانَ ٱللَّهُ عَزِیزًا حَكِیمࣰا',
    'بل رفعه الله اليه وكان الله عزيزا حكيما',
    'بَ<rule class=idgham_mutaqaribayn>ل</rule> رَّفَعَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَيۡهِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزًا حَكِيمًا ١٥٨',
    158, 6, 1, 103, 83, 41, 'false'
  );
  
  -- Ayah 159 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    652,
    'وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ إِلَّا لَیُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ یَكُونُ عَلَیۡهِمۡ شَهِیدࣰا',
    'وان من اهل الكتاب الا ليؤمنن به قبل موته ويوم القيامة يكون عليهم شهيدا',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ إِلَّا لَيُؤۡمِنَ<rule class=ghunnah>نّ</rule>َ بِه<rule class=madda_normal>ِۦ</rule> قَ<rule class=qalaqah>بۡ</rule>لَ مَوۡتِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدًا ١٥٩',
    159, 6, 1, 103, 83, 41, 'false'
  );
  
  -- Ayah 160 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    653,
    'فَبِظُلۡمࣲ مِّنَ ٱلَّذِینَ هَادُوا۟ حَرَّمۡنَا عَلَیۡهِمۡ طَیِّبَـٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِیلِ ٱللَّهِ كَثِیرࣰا',
    'فبظلم من الذين هادوا حرمنا عليهم طيبات احلت لهم وبصدهم عن سبيل الله كثيرا',
    'فَبِظُلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَادُو<rule class=slnt>اۡ</rule> حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَ<rule class=madda_normal>ـٰ</rule>تٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ كَثِيرًا ١٦٠',
    160, 6, 1, 103, 83, 41, 'false'
  );
  
  -- Ayah 161 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    654,
    'وَأَخۡذِهِمُ ٱلرِّبَوٰا۟ وَقَدۡ نُهُوا۟ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَ ٰ⁠لَ ٱلنَّاسِ بِٱلۡبَـٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَـٰفِرِینَ مِنۡهُمۡ عَذَابًا أَلِیمࣰا',
    'واخذهم الربا وقد نهوا عنه واكلهم اموال الناس بالباطل واعتدنا للكافرين منهم عذابا اليما',
    'وَأَخۡذِهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّبَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>اۡ وَقَ<rule class=qalaqah>دۡ</rule> نُهُو<rule class=slnt>اۡ</rule> عَنۡهُ وَأَكۡلِهِمۡ أَمۡو<rule class=madda_normal>ٰ</rule>لَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ‌ۚ وَأَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمًا ١٦١',
    161, 6, 1, 103, 83, 41, 'false'
  );
  
  -- Ayah 162 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    655,
    'لَّـٰكِنِ ٱلرَّ ٰ⁠سِخُونَ فِی ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ یُؤۡمِنُونَ بِمَاۤ أُنزِلَ إِلَیۡكَ وَمَاۤ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِیمِینَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ أُو۟لَـٰۤىِٕكَ سَنُؤۡتِیهِمۡ أَجۡرًا عَظِیمًا',
    'لكن الراسخون في العلم منهم والمؤمنون يؤمنون بما انزل اليك وما انزل من قبلك والمقيمين الصلاة والمؤتون الزكاة والمؤمنون بالله واليوم الاخر اولئك سنؤتيهم اجرا عظيما',
    'لَّ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>سِخُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ مِنۡهُمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡمُقِيمِينَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ سَنُؤۡتِيهِمۡ أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ١٦٢',
    162, 6, 1, 103, 83, 41, 'false'
  );
  
  -- Ayah 163 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    656,
    '۞ إِنَّاۤ أَوۡحَیۡنَاۤ إِلَیۡكَ كَمَاۤ أَوۡحَیۡنَاۤ إِلَىٰ نُوحࣲ وَٱلنَّبِیِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَیۡنَاۤ إِلَىٰۤ إِبۡرَ ٰ⁠هِیمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِیسَىٰ وَأَیُّوبَ وَیُونُسَ وَهَـٰرُونَ وَسُلَیۡمَـٰنَۚ وَءَاتَیۡنَا دَاوُۥدَ زَبُورࣰا',
    'انا اوحينا اليك كما اوحينا الى نوح والنبيين من بعده واوحينا الى ابراهيم واسماعيل واسحاق ويعقوب والاسباط وعيسى وايوب ويونس وهارون وسليمان واتينا داوود زبورا',
    '۞إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَ<rule class=madda_normal>ـٰ</rule>رُونَ وَسُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ‌ۚ وَءَاتَيۡنَا دَاوُ<rule class=madda_normal>ۥ</rule>دَ زَبُورًا ١٦٣',
    163, 6, 1, 104, 84, 42, 'false'
  );
  
  -- Ayah 164 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    657,
    'وَرُسُلࣰا قَدۡ قَصَصۡنَـٰهُمۡ عَلَیۡكَ مِن قَبۡلُ وَرُسُلࣰا لَّمۡ نَقۡصُصۡهُمۡ عَلَیۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِیمࣰا',
    'ورسلا قد قصصناهم عليك من قبل ورسلا لم نقصصهم عليك وكلم الله موسى تكليما',
    'وَرُسُل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> قَصَصۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ عَلَيۡكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَرُسُل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ نَ<rule class=qalaqah>قۡ</rule>صُصۡهُمۡ عَلَيۡكَ‌ۚ وَكَلَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ مُوسَىٰ تَكۡلِيمًا ١٦٤',
    164, 6, 1, 104, 84, 42, 'false'
  );
  
  -- Ayah 165 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    658,
    'رُّسُلࣰا مُّبَشِّرِینَ وَمُنذِرِینَ لِئَلَّا یَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِیزًا حَكِیمࣰا',
    'رسلا مبشرين ومنذرين لئلا يكون للناس على الله حجة بعد الرسل وكان الله عزيزا حكيما',
    'رُّسُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ُّبَشِّرِينَ وَمُ<rule class=ikhafa>نذ</rule>ِرِينَ لِئَلَّا يَكُونَ لِل<rule class=ghunnah>نّ</rule>َاسِ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ حُجَّ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>َعۡدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزًا حَكِيمًا ١٦٥',
    165, 6, 1, 104, 84, 42, 'false'
  );
  
  -- Ayah 166 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    659,
    'لَّـٰكِنِ ٱللَّهُ یَشۡهَدُ بِمَاۤ أَنزَلَ إِلَیۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَـٰۤىِٕكَةُ یَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِیدًا',
    'لكن الله يشهد بما انزل اليك انزله بعلمه والملائكة يشهدون وكفى بالله شهيدا',
    'لَّ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule>للَّهُ يَشۡهَدُ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ إِلَيۡكَ‌ۖ أَ<rule class=ikhafa>نز</rule>َلَهُ<rule class=madda_normal>ۥ</rule> بِعِلۡمِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ يَشۡهَدُونَ‌ۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ شَهِيدًا ١٦٦',
    166, 6, 1, 104, 84, 42, 'false'
  );
  
  -- Ayah 167 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    660,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ قَدۡ ضَلُّوا۟ ضَلَـٰلَۢا بَعِیدًا',
    'ان الذين كفروا وصدوا عن سبيل الله قد ضلوا ضلالا بعيدا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَصَدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ قَ<rule class=qalaqah>دۡ</rule> ضَلُّو<rule class=slnt>اۡ</rule> ضَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=iqlab>اَۢ</rule> <rule class=iqlab>ب</rule>َعِيدًا ١٦٧',
    167, 6, 1, 104, 84, 42, 'false'
  );
  
  -- Ayah 168 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    661,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَظَلَمُوا۟ لَمۡ یَكُنِ ٱللَّهُ لِیَغۡفِرَ لَهُمۡ وَلَا لِیَهۡدِیَهُمۡ طَرِیقًا',
    'ان الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَظَلَمُو<rule class=slnt>اۡ</rule> لَمۡ يَكُنِ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ طَرِيقًا ١٦٨',
    168, 6, 1, 104, 84, 42, 'false'
  );
  
  -- Ayah 169 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    662,
    'إِلَّا طَرِیقَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۚ وَكَانَ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣰا',
    'الا طريق جهنم خالدين فيها ابدا وكان ذلك على الله يسيرا',
    'إِلَّا طَرِيقَ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=idgham_ghunnah>دًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَسِيرًا ١٦٩',
    169, 6, 1, 104, 84, 42, 'false'
  );
  
  -- Ayah 170 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    663,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ قَدۡ جَاۤءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُوا۟ خَیۡرࣰا لَّكُمۡۚ وَإِن تَكۡفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا',
    'يا ايها الناس قد جاءكم الرسول بالحق من ربكم فامنوا خيرا لكم وان تكفروا فان لله ما في السماوات والارض وكان الله عليما حكيما',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ فَـَٔـامِنُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكۡفُرُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمًا حَكِيمًا ١٧٠',
    170, 6, 1, 104, 84, 42, 'false'
  );
  
  -- Ayah 171 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    664,
    'یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لَا تَغۡلُوا۟ فِی دِینِكُمۡ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِیحُ عِیسَى ٱبۡنُ مَرۡیَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥۤ أَلۡقَىٰهَاۤ إِلَىٰ مَرۡیَمَ وَرُوحࣱ مِّنۡهُۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌۚ ٱنتَهُوا۟ خَیۡرࣰا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَـٰهࣱ وَ ٰ⁠حِدࣱۖ سُبۡحَـٰنَهُۥۤ أَن یَكُونَ لَهُۥ وَلَدࣱۘ لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِیلࣰا',
    'يا اهل الكتاب لا تغلوا في دينكم ولا تقولوا على الله الا الحق انما المسيح عيسى ابن مريم رسول الله وكلمته القاها الى مريم وروح منه فامنوا بالله ورسله ولا تقولوا ثلاثة انتهوا خيرا لكم انما الله اله واحد سبحانه ان يكون له ولد له ما في السماوات وما في الارض وكفى بالله وكيلا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَا تَغۡلُو<rule class=slnt>اۡ</rule> فِى دِينِكُمۡ وَلَا تَقُولُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡحَقَّ‌ۚ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡمَسِيحُ عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ رَسُولُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَكَلِمَتُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَلۡقَ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مَرۡيَمَ وَرُو<rule class=idgham_ghunnah>حٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ‌ۖ فَـَٔـامِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرُسُلِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَلَا تَقُولُو<rule class=slnt>اۡ</rule> ثَلَ<rule class=madda_normal>ـٰ</rule>ثَةٌ‌ۚ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َهُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=ikhafa>دٌ‌ۖ</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ لَهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=idgham_wo_ghunnah>دٌ‌ۘ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَكِيلاً ١٧١',
    171, 6, 1, 105, 84, 42, 'false'
  );
  
  -- Ayah 172 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    665,
    'لَّن یَسۡتَنكِفَ ٱلۡمَسِیحُ أَن یَكُونَ عَبۡدࣰا لِّلَّهِ وَلَا ٱلۡمَلَـٰۤىِٕكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن یَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَیَسۡتَكۡبِرۡ فَسَیَحۡشُرُهُمۡ إِلَیۡهِ جَمِیعࣰا',
    'لن يستنكف المسيح ان يكون عبدا لله ولا الملائكة المقربون ومن يستنكف عن عبادته ويستكبر فسيحشرهم اليه جميعا',
    'لّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَ<rule class=ikhafa>نك</rule>ِفَ <rule class=ham_wasl>ٱ</rule>لۡمَسِيحُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ عَ<rule class=qalaqah>بۡ</rule><rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّهِ وَلَا <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ <rule class=ham_wasl>ٱ</rule>لۡمُقَرَّبُونَ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَ<rule class=ikhafa>نك</rule>ِفۡ عَنۡ عِبَادَتِه<rule class=madda_normal>ِۦ</rule> وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعًا ١٧٢',
    172, 6, 1, 105, 85, 42, 'false'
  );
  
  -- Ayah 173 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    666,
    'فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَیُوَفِّیهِمۡ أُجُورَهُمۡ وَیَزِیدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِینَ ٱسۡتَنكَفُوا۟ وَٱسۡتَكۡبَرُوا۟ فَیُعَذِّبُهُمۡ عَذَابًا أَلِیمࣰا وَلَا یَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِیࣰّا وَلَا نَصِیرࣰا',
    'فاما الذين امنوا وعملوا الصالحات فيوفيهم اجورهم ويزيدهم من فضله واما الذين استنكفوا واستكبروا فيعذبهم عذابا اليما ولا يجدون لهم من دون الله وليا ولا نصيرا',
    'فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَ<rule class=ikhafa>نك</rule>َفُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> فَيُعَذِّبُهُمۡ عَذَابًا أَلِي<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَجِدُونَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصِيرًا ١٧٣',
    173, 6, 1, 105, 85, 42, 'false'
  );
  
  -- Ayah 174 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    667,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ قَدۡ جَاۤءَكُم بُرۡهَـٰنࣱ مِّن رَّبِّكُمۡ وَأَنزَلۡنَاۤ إِلَیۡكُمۡ نُورࣰا مُّبِینࣰا',
    'يا ايها الناس قد جاءكم برهان من ربكم وانزلنا اليكم نورا مبينا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ُرۡهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَأَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكُمۡ نُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ١٧٤',
    174, 6, 1, 105, 85, 42, 'false'
  );
  
  -- Ayah 175 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    668,
    'فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَٱعۡتَصَمُوا۟ بِهِۦ فَسَیُدۡخِلُهُمۡ فِی رَحۡمَةࣲ مِّنۡهُ وَفَضۡلࣲ وَیَهۡدِیهِمۡ إِلَیۡهِ صِرَ ٰ⁠طࣰا مُّسۡتَقِیمࣰا',
    'فاما الذين امنوا بالله واعتصموا به فسيدخلهم في رحمة منه وفضل ويهديهم اليه صراطا مستقيما',
    'فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>عۡتَصَمُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> فَسَيُ<rule class=qalaqah>دۡ</rule>خِلُهُمۡ فِى رَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ وَفَضۡ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َيَهۡدِيهِمۡ إِلَيۡهِ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طًا</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقِيمًا ١٧٥',
    175, 6, 1, 105, 85, 42, 'false'
  );
  
  -- Ayah 176 Surah An-Nisaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    4,
    669,
    'یَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ یُفۡتِیكُمۡ فِی ٱلۡكَلَـٰلَةِۚ إِنِ ٱمۡرُؤٌا۟ هَلَكَ لَیۡسَ لَهُۥ وَلَدࣱ وَلَهُۥۤ أُخۡتࣱ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ یَرِثُهَاۤ إِن لَّمۡ یَكُن لَّهَا وَلَدࣱۚ فَإِن كَانَتَا ٱثۡنَتَیۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوۤا۟ إِخۡوَةࣰ رِّجَالࣰا وَنِسَاۤءࣰ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَیَیۡنِۗ یُبَیِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّوا۟ۗ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمُۢ',
    'يستفتونك قل الله يفتيكم في الكلالة ان امرؤ هلك ليس له ولد وله اخت فلها نصف ما ترك وهو يرثها ان لم يكن لها ولد فان كانتا اثنتين فلهما الثلثان مما ترك وان كانوا اخوة رجالا ونساء فللذكر مثل حظ الانثيين يبين الله لكم ان تضلوا والله بكل شيء عليم',
    'يَسۡتَفۡتُونَكَ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ يُفۡتِيكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكَلَ<rule class=madda_normal>ـٰ</rule>لَةِ‌ۚ إِنِ <rule class=ham_wasl>ٱ</rule>مۡرُؤٌاۡ هَلَكَ لَيۡسَ لَهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أُخۡ<rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ف</rule>َلَهَا نِصۡفُ مَا تَرَكَ‌ۚ وَهُوَ يَرِثُه<rule class=madda_obligatory_monfasel>َآ</rule> إ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهَا وَلَ<rule class=ikhafa>دٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَتَا <rule class=ham_wasl>ٱ</rule>ثۡنَتَيۡنِ فَلَهُمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثُّلُثَانِ مِ<rule class=ghunnah>مّ</rule>َا تَرَكَ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِخۡوَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّجَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َنِس<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َلِلذَّكَرِ مِثۡلُ حَظِّ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َيَيۡنِ‌ۗ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َضِلُّو<rule class=slnt>اۡ‌ۗ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مُۢ ١٧٦',
    176, 6, 1, 106, 85, 42, 'false'
  );
  

-- Surah Al-Maaida
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (5, 'سُورَةُ المَائـِدَةِ', 'Al-Maaida', 'The Table', 'Medinan', 120);

  -- Ayah 1 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    670,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَوۡفُوا۟ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِیمَةُ ٱلۡأَنۡعَـٰمِ إِلَّا مَا یُتۡلَىٰ عَلَیۡكُمۡ غَیۡرَ مُحِلِّی ٱلصَّیۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ یَحۡكُمُ مَا یُرِیدُ',
    'يا ايها الذين امنوا اوفوا بالعقود احلت لكم بهيمة الانعام الا ما يتلى عليكم غير محلي الصيد وانتم حرم ان الله يحكم ما يريد',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡفُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡعُقُودِ‌ۚ أُحِلَّتۡ لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َهِيمَةُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ غَيۡرَ مُحِلِّى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡدِ وَأَ<rule class=ikhafa>نت</rule>ُمۡ حُرُمٌ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَحۡكُمُ مَا يُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ١',
    1, 6, 2, 106, 86, 43, 'false'
  );
  
  -- Ayah 2 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    671,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَـٰۤىِٕرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡیَ وَلَا ٱلۡقَلَـٰۤىِٕدَ وَلَاۤ ءَاۤمِّینَ ٱلۡبَیۡتَ ٱلۡحَرَامَ یَبۡتَغُونَ فَضۡلࣰا مِّن رَّبِّهِمۡ وَرِضۡوَ ٰ⁠نࣰاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُوا۟ۚ وَلَا یَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُوا۟ۘ وَتَعَاوَنُوا۟ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰ⁠نِۚ وَٱتَّقُوا۟ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ',
    'يا ايها الذين امنوا لا تحلوا شعائر الله ولا الشهر الحرام ولا الهدي ولا القلائد ولا امين البيت الحرام يبتغون فضلا من ربهم ورضوانا واذا حللتم فاصطادوا ولا يجرمنكم شنان قوم ان صدوكم عن المسجد الحرام ان تعتدوا وتعاونوا على البر والتقوى ولا تعاونوا على الاثم والعدوان واتقوا الله ان الله شديد العقاب',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تُحِلُّو<rule class=slnt>اۡ</rule> شَعَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهۡرَ <rule class=ham_wasl>ٱ</rule>لۡحَرَامَ وَلَا <rule class=ham_wasl>ٱ</rule>لۡهَ<rule class=qalaqah>دۡ</rule>ىَ وَلَا <rule class=ham_wasl>ٱ</rule>لۡقَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِدَ وَل<rule class=madda_obligatory_monfasel>َآ</rule> ء<rule class=madda_necessary>َا</rule>ٓ<rule class=ghunnah>مّ</rule>ِينَ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتَ <rule class=ham_wasl>ٱ</rule>لۡحَرَامَ يَ<rule class=qalaqah>بۡ</rule>تَغُونَ فَضۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ وَرِضۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِذَا حَلَلۡتُمۡ فَ<rule class=ham_wasl>ٱ</rule>صۡطَادُو<rule class=slnt>اۡ‌ۚ</rule> وَلَا يَ<rule class=qalaqah>جۡ</rule>رِمَ<rule class=ghunnah>نّ</rule>َكُمۡ شَنَـَٔـانُ قَوۡمٍ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َدُّوكُمۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡتَدُو<rule class=slnt>اۡ‌ۘ</rule> وَتَعَاوَنُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لۡبِرِّ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=qalaqah>قۡ</rule>وَىٰ‌ۖ وَلَا تَعَاوَنُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَ<rule class=ham_wasl>ٱ</rule>لۡعُ<rule class=qalaqah>دۡ</rule>و<rule class=madda_normal>ٰ</rule>نِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢',
    2, 6, 2, 106, 86, 43, 'false'
  );
  
  -- Ayah 3 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    672,
    'حُرِّمَتۡ عَلَیۡكُمُ ٱلۡمَیۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِیرِ وَمَاۤ أُهِلَّ لِغَیۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّیَةُ وَٱلنَّطِیحَةُ وَمَاۤ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّیۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُوا۟ بِٱلۡأَزۡلَـٰمِۚ ذَ ٰ⁠لِكُمۡ فِسۡقٌۗ ٱلۡیَوۡمَ یَىِٕسَ ٱلَّذِینَ كَفَرُوا۟ مِن دِینِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡیَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِینَكُمۡ وَأَتۡمَمۡتُ عَلَیۡكُمۡ نِعۡمَتِی وَرَضِیتُ لَكُمُ ٱلۡإِسۡلَـٰمَ دِینࣰاۚ فَمَنِ ٱضۡطُرَّ فِی مَخۡمَصَةٍ غَیۡرَ مُتَجَانِفࣲ لِّإِثۡمࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'حرمت عليكم الميتة والدم ولحم الخنزير وما اهل لغير الله به والمنخنقة والموقوذة والمتردية والنطيحة وما اكل السبع الا ما ذكيتم وما ذبح على النصب وان تستقسموا بالازلام ذلكم فسق اليوم يئس الذين كفروا من دينكم فلا تخشوهم واخشون اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلام دينا فمن اضطر في مخمصة غير متجانف لاثم فان الله غفور رحيم',
    'حُرِّمَتۡ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَيۡتَةُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّمُ وَلَحۡمُ <rule class=ham_wasl>ٱ</rule>لۡخِ<rule class=ikhafa>نز</rule>ِيرِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُهِلَّ لِغَيۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡمُنۡخَنِقَةُ وَ<rule class=ham_wasl>ٱ</rule>لۡمَوۡقُوذَةُ وَ<rule class=ham_wasl>ٱ</rule>لۡمُتَرَدِّيَةُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َطِيحَةُ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَكَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبُعُ إِلَّا مَا ذَكَّيۡتُمۡ وَمَا ذُبِحَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُصُبِ وَأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَ<rule class=qalaqah>قۡ</rule>سِمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡأَزۡلَ<rule class=madda_normal>ـٰ</rule>مِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ فِسۡقٌ‌ۗ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ يَئِسَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِينِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَ<rule class=ham_wasl>ٱ</rule>خۡشَوۡنِ‌ۚ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِى وَرَضِيتُ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡإِسۡلَ<rule class=madda_normal>ـٰ</rule>مَ دِي<rule class=ikhafa>نًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َمَنِ <rule class=ham_wasl>ٱ</rule>ضۡطُرَّ فِى مَخۡمَصَةٍ غَيۡرَ مُتَجَانِ<rule class=idgham_wo_ghunnah>فٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّإٍِثۡ<rule class=ikhafa>مٍ‌ۙ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٣',
    3, 6, 2, 107, 86, 43, 'false'
  );
  
  -- Ayah 4 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    673,
    'یَسۡـَٔلُونَكَ مَاذَاۤ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّیِّبَـٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِینَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُوا۟ مِمَّاۤ أَمۡسَكۡنَ عَلَیۡكُمۡ وَٱذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ عَلَیۡهِۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ',
    'يسالونك ماذا احل لهم قل احل لكم الطيبات وما علمتم من الجوارح مكلبين تعلمونهن مما علمكم الله فكلوا مما امسكن عليكم واذكروا اسم الله عليه واتقوا الله ان الله سريع الحساب',
    'يَسۡــَٔلُونَكَ مَاذ<rule class=madda_obligatory_monfasel>َآ</rule> أُحِلَّ لَهُمۡ‌ۖ قُلۡ أُحِلَّ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تُ‌ۙ وَمَا عَلَّمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ghunnah>مّ</rule>َا عَلَّمَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ فَكُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَمۡسَكۡنَ عَلَيۡكُمۡ وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>سۡمَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡهِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٤',
    4, 6, 2, 107, 86, 43, 'false'
  );
  
  -- Ayah 5 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    674,
    'ٱلۡیَوۡمَ أُحِلَّ لَكُمُ ٱلطَّیِّبَـٰتُۖ وَطَعَامُ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ حِلࣱّ لَّكُمۡ وَطَعَامُكُمۡ حِلࣱّ لَّهُمۡۖ وَٱلۡمُحۡصَنَـٰتُ مِنَ ٱلۡمُؤۡمِنَـٰتِ وَٱلۡمُحۡصَنَـٰتُ مِنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلِكُمۡ إِذَاۤ ءَاتَیۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِینَ غَیۡرَ مُسَـٰفِحِینَ وَلَا مُتَّخِذِیۤ أَخۡدَانࣲۗ وَمَن یَكۡفُرۡ بِٱلۡإِیمَـٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِی ٱلۡـَٔاخِرَةِ مِنَ ٱلۡخَـٰسِرِینَ',
    'اليوم احل لكم الطيبات وطعام الذين اوتوا الكتاب حل لكم وطعامكم حل لهم والمحصنات من المؤمنات والمحصنات من الذين اوتوا الكتاب من قبلكم اذا اتيتموهن اجورهن محصنين غير مسافحين ولا متخذي اخدان ومن يكفر بالايمان فقد حبط عمله وهو في الاخرة من الخاسرين',
    'ٱلۡيَوۡمَ أُحِلَّ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تُ‌ۖ وَطَعَامُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ حِ<rule class=idgham_wo_ghunnah>لٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَطَعَامُكُمۡ حِ<rule class=idgham_wo_ghunnah>لٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لۡمُحۡصَنَ<rule class=madda_normal>ـٰ</rule>تُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُحۡصَنَ<rule class=madda_normal>ـٰ</rule>تُ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡتُمُوهُ<rule class=ghunnah>نّ</rule>َ أُجُورَهُ<rule class=ghunnah>نّ</rule>َ مُحۡصِنِينَ غَيۡرَ مُسَ<rule class=madda_normal>ـٰ</rule>فِحِينَ وَلَا مُتَّخِذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخۡدَا<rule class=idgham_ghunnah>نٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرۡ بِ<rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ فَقَ<rule class=qalaqah>دۡ</rule> حَبِطَ عَمَلُهُ<rule class=madda_normal>ۥ</rule> وَهُوَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 6, 2, 107, 86, 43, 'false'
  );
  
  -- Ayah 6 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    675,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُوا۟ وُجُوهَكُمۡ وَأَیۡدِیَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُوا۟ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَیۡنِۚ وَإِن كُنتُمۡ جُنُبࣰا فَٱطَّهَّرُوا۟ۚ وَإِن كُنتُم مَّرۡضَىٰۤ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَاۤءَ أَحَدࣱ مِّنكُم مِّنَ ٱلۡغَاۤىِٕطِ أَوۡ لَـٰمَسۡتُمُ ٱلنِّسَاۤءَ فَلَمۡ تَجِدُوا۟ مَاۤءࣰ فَتَیَمَّمُوا۟ صَعِیدࣰا طَیِّبࣰا فَٱمۡسَحُوا۟ بِوُجُوهِكُمۡ وَأَیۡدِیكُم مِّنۡهُۚ مَا یُرِیدُ ٱللَّهُ لِیَجۡعَلَ عَلَیۡكُم مِّنۡ حَرَجࣲ وَلَـٰكِن یُرِیدُ لِیُطَهِّرَكُمۡ وَلِیُتِمَّ نِعۡمَتَهُۥ عَلَیۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ',
    'يا ايها الذين امنوا اذا قمتم الى الصلاة فاغسلوا وجوهكم وايديكم الى المرافق وامسحوا برءوسكم وارجلكم الى الكعبين وان كنتم جنبا فاطهروا وان كنتم مرضى او على سفر او جاء احد منكم من الغائط او لامستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وايديكم منه ما يريد الله ليجعل عليكم من حرج ولكن يريد ليطهركم وليتم نعمته عليكم لعلكم تشكرون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا قُمۡتُمۡ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ فَ<rule class=ham_wasl>ٱ</rule>غۡسِلُو<rule class=slnt>اۡ</rule> وُجُوهَكُمۡ وَأَيۡدِيَكُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡمَرَافِقِ وَ<rule class=ham_wasl>ٱ</rule>مۡسَحُو<rule class=slnt>اۡ</rule> بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡكَعۡبَيۡنِ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ جُنُ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>طَّهَّرُو<rule class=slnt>اۡ‌ۚ</rule> وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرۡضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَوۡ عَلَىٰ سَفَرٍ أَوۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَحَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡغ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِطِ أَوۡ لَ<rule class=madda_normal>ـٰ</rule>مَسۡتُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَلَمۡ تَجِدُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َتَيَ<rule class=ghunnah>مّ</rule>َمُو<rule class=slnt>اۡ</rule> صَعِي<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ط</rule>َيِّ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>مۡسَحُو<rule class=slnt>اۡ</rule> بِوُجُوهِكُمۡ وَأَيۡدِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ‌ۚ مَا يُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيَ<rule class=qalaqah>جۡ</rule>عَلَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ حَرَ<rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيدُ لِيُطَهِّرَكُمۡ وَلِيُتِ<rule class=ghunnah>مّ</rule>َ نِعۡمَتَهُ<rule class=madda_normal>ۥ</rule> عَلَيۡكُمۡ لَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 6, 2, 108, 87, 43, 'false'
  );
  
  -- Ayah 7 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    676,
    'وَٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ وَمِیثَـٰقَهُ ٱلَّذِی وَاثَقَكُم بِهِۦۤ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'واذكروا نعمة الله عليكم وميثاقه الذي واثقكم به اذ قلتم سمعنا واطعنا واتقوا الله ان الله عليم بذات الصدور',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ وَمِيثَ<rule class=madda_normal>ـٰ</rule>قَهُ <rule class=ham_wasl>ٱ</rule>لَّذِى وَاثَقَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَا‌ۖ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٧',
    7, 6, 2, 108, 87, 43, 'false'
  );
  
  -- Ayah 8 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    677,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُونُوا۟ قَوَّ ٰ⁠مِینَ لِلَّهِ شُهَدَاۤءَ بِٱلۡقِسۡطِۖ وَلَا یَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰۤ أَلَّا تَعۡدِلُوا۟ۚ ٱعۡدِلُوا۟ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا تَعۡمَلُونَ',
    'يا ايها الذين امنوا كونوا قوامين لله شهداء بالقسط ولا يجرمنكم شنان قوم على الا تعدلوا اعدلوا هو اقرب للتقوى واتقوا الله ان الله خبير بما تعملون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> كُونُو<rule class=slnt>اۡ</rule> قَوّ<rule class=madda_normal>ٰ</rule>مِينَ لِلَّهِ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۖ وَلَا يَ<rule class=qalaqah>جۡ</rule>رِمَ<rule class=ghunnah>نّ</rule>َكُمۡ شَنَـَٔـانُ قَوۡمٍ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَلَّا تَعۡدِلُو<rule class=slnt>اۡ‌ۚ</rule> <rule class=ham_wasl>ٱ</rule>عۡدِلُو<rule class=slnt>اۡ</rule> هُوَ أَ<rule class=qalaqah>قۡ</rule>رَبُ لِلتَّ<rule class=qalaqah>قۡ</rule>وَىٰ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 6, 2, 108, 87, 43, 'false'
  );
  
  -- Ayah 9 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    678,
    'وَعَدَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرٌ عَظِیمࣱ',
    'وعد الله الذين امنوا وعملوا الصالحات لهم مغفرة واجر عظيم',
    'وَعَدَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ‌ۙ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule>رٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٩',
    9, 6, 2, 108, 87, 43, 'false'
  );
  
  -- Ayah 10 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    679,
    'وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ',
    'والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَكَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ١٠',
    10, 6, 2, 109, 87, 43, 'false'
  );
  
  -- Ayah 11 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    680,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن یَبۡسُطُوۤا۟ إِلَیۡكُمۡ أَیۡدِیَهُمۡ فَكَفَّ أَیۡدِیَهُمۡ عَنكُمۡۖ وَٱتَّقُوا۟ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ',
    'يا ايها الذين امنوا اذكروا نعمت الله عليكم اذ هم قوم ان يبسطوا اليكم ايديهم فكف ايديهم عنكم واتقوا الله وعلى الله فليتوكل المؤمنون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ إِذۡ هَ<rule class=ghunnah>مّ</rule>َ قَوۡمٌ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>سُط<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡكُمۡ أَيۡدِيَهُمۡ فَكَفَّ أَيۡدِيَهُمۡ عَ<rule class=ikhafa>نك</rule>ُمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 6, 2, 109, 87, 43, 'false'
  );
  
  -- Ayah 12 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    681,
    '۞ وَلَقَدۡ أَخَذَ ٱللَّهُ مِیثَـٰقَ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَیۡ عَشَرَ نَقِیبࣰاۖ وَقَالَ ٱللَّهُ إِنِّی مَعَكُمۡۖ لَىِٕنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَیۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِی وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنࣰا لَّأُكَفِّرَنَّ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَ ٰ⁠لِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَاۤءَ ٱلسَّبِیلِ',
    'ولقد اخذ الله ميثاق بني اسرائيل وبعثنا منهم اثني عشر نقيبا وقال الله اني معكم لئن اقمتم الصلاة واتيتم الزكاة وامنتم برسلي وعزرتموهم واقرضتم الله قرضا حسنا لاكفرن عنكم سيئاتكم ولادخلنكم جنات تجري من تحتها الانهار فمن كفر بعد ذلك منكم فقد ضل سواء السبيل',
    '۞وَلَقَ<rule class=qalaqah>دۡ</rule> أَخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِيثَ<rule class=madda_normal>ـٰ</rule>قَ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ وَبَعَثۡنَا مِنۡهُمُ <rule class=ham_wasl>ٱ</rule>ثۡنَىۡ عَشَرَ نَقِي<rule class=idgham_ghunnah>بًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِ<rule class=ghunnah>نّ</rule>ِى مَعَكُمۡ‌ۖ لَئِنۡ أَقَمۡتُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتَيۡتُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَامَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرُسُلِى وَعَزَّرۡتُمُوهُمۡ وَأَ<rule class=qalaqah>قۡ</rule>رَضۡتُمُ <rule class=ham_wasl>ٱ</rule>للَّهَ قَرۡضًا حَسَ<rule class=idgham_wo_ghunnah>نًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّأُكَفِّرَ<rule class=ghunnah>نّ</rule>َ عَ<rule class=ikhafa>نك</rule>ُمۡ سَيِّـَٔـاتِكُمۡ وَلَأُ<rule class=qalaqah>دۡ</rule>خِلَ<rule class=ghunnah>نّ</rule>َكُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۚ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ بَعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ مِ<rule class=ikhafa>نك</rule>ُمۡ فَقَ<rule class=qalaqah>دۡ</rule> ضَلَّ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لِ ١٢',
    12, 6, 2, 109, 88, 44, 'false'
  );
  
  -- Ayah 13 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    682,
    'فَبِمَا نَقۡضِهِم مِّیثَـٰقَهُمۡ لَعَنَّـٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَـٰسِیَةࣰۖ یُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُوا۟ حَظࣰّا مِّمَّا ذُكِّرُوا۟ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَاۤىِٕنَةࣲ مِّنۡهُمۡ إِلَّا قَلِیلࣰا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُحۡسِنِینَ',
    'فبما نقضهم ميثاقهم لعناهم وجعلنا قلوبهم قاسية يحرفون الكلم عن مواضعه ونسوا حظا مما ذكروا به ولا تزال تطلع على خائنة منهم الا قليلا منهم فاعف عنهم واصفح ان الله يحب المحسنين',
    'فَبِمَا نَ<rule class=qalaqah>قۡ</rule>ضِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule>قَهُمۡ لَعَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَ<rule class=madda_normal>ـٰ</rule>سِيَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>ي</rule>ُحَرِّفُونَ <rule class=ham_wasl>ٱ</rule>لۡكَلِمَ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّوَاضِعِه<rule class=madda_normal>ِۦ</rule>‌ۙ وَنَسُو<rule class=slnt>اۡ</rule> حَظ<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا ذُكِّرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ إِلَّا قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>عۡفُ عَنۡهُمۡ وَ<rule class=ham_wasl>ٱ</rule>صۡفَحۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 6, 2, 109, 88, 44, 'false'
  );
  
  -- Ayah 14 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    683,
    'وَمِنَ ٱلَّذِینَ قَالُوۤا۟ إِنَّا نَصَـٰرَىٰۤ أَخَذۡنَا مِیثَـٰقَهُمۡ فَنَسُوا۟ حَظࣰّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغۡرَیۡنَا بَیۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَاۤءَ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِۚ وَسَوۡفَ یُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ یَصۡنَعُونَ',
    'ومن الذين قالوا انا نصارى اخذنا ميثاقهم فنسوا حظا مما ذكروا به فاغرينا بينهم العداوة والبغضاء الى يوم القيامة وسوف ينبئهم الله بما كانوا يصنعون',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا نَصَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَخَذۡنَا مِيثَ<rule class=madda_normal>ـٰ</rule>قَهُمۡ فَنَسُو<rule class=slnt>اۡ</rule> حَظ<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا ذُكِّرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> فَأَغۡرَيۡنَا بَيۡنَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَدَاوَةَ وَ<rule class=ham_wasl>ٱ</rule>لۡبَغۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ وَسَوۡفَ يُنَبِّئُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَصۡنَع<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 6, 2, 110, 88, 44, 'false'
  );
  
  -- Ayah 15 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    684,
    'یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ قَدۡ جَاۤءَكُمۡ رَسُولُنَا یُبَیِّنُ لَكُمۡ كَثِیرࣰا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَـٰبِ وَیَعۡفُوا۟ عَن كَثِیرࣲۚ قَدۡ جَاۤءَكُم مِّنَ ٱللَّهِ نُورࣱ وَكِتَـٰبࣱ مُّبِینࣱ',
    'يا اهل الكتاب قد جاءكم رسولنا يبين لكم كثيرا مما كنتم تخفون من الكتاب ويعفو عن كثير قد جاءكم من الله نور وكتاب مبين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا كُ<rule class=ikhafa>نت</rule>ُمۡ تُخۡفُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَيَعۡفُو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َثِي<rule class=ikhafa>رٍ‌ۚ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ نُو<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َكِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٥',
    15, 6, 2, 110, 88, 44, 'false'
  );
  
  -- Ayah 16 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    685,
    'یَهۡدِی بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَ ٰ⁠نَهُۥ سُبُلَ ٱلسَّلَـٰمِ وَیُخۡرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَیَهۡدِیهِمۡ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'يهدي به الله من اتبع رضوانه سبل السلام ويخرجهم من الظلمات الى النور باذنه ويهديهم الى صراط مستقيم',
    'يَهۡدِى بِهِ <rule class=ham_wasl>ٱ</rule>للَّهُ مَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَ رِضۡو<rule class=madda_normal>ٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> سُبُلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَ<rule class=madda_normal>ـٰ</rule>مِ وَيُخۡرِجُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِ بِإِذۡنِه<rule class=madda_normal>ِۦ</rule> وَيَهۡدِيهِمۡ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ١٦',
    16, 6, 2, 110, 88, 44, 'false'
  );
  
  -- Ayah 17 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    686,
    'لَّقَدۡ كَفَرَ ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِیحُ ٱبۡنُ مَرۡیَمَۚ قُلۡ فَمَن یَمۡلِكُ مِنَ ٱللَّهِ شَیۡـًٔا إِنۡ أَرَادَ أَن یُهۡلِكَ ٱلۡمَسِیحَ ٱبۡنَ مَرۡیَمَ وَأُمَّهُۥ وَمَن فِی ٱلۡأَرۡضِ جَمِیعࣰاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۚ یَخۡلُقُ مَا یَشَاۤءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم قل فمن يملك من الله شيئا ان اراد ان يهلك المسيح ابن مريم وامه ومن في الارض جميعا ولله ملك السماوات والارض وما بينهما يخلق ما يشاء والله على كل شيء قدير',
    'لَّقَ<rule class=qalaqah>دۡ</rule> كَفَرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡمَسِيحُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ‌ۚ قُلۡ فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡلِكُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡــًٔا إِنۡ أَرَادَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُهۡلِكَ <rule class=ham_wasl>ٱ</rule>لۡمَسِيحَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ وَأُ<rule class=ghunnah>مّ</rule>َهُ<rule class=madda_normal>ۥ</rule> وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَمِي<rule class=idgham_ghunnah>عًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َلِلَّهِ مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا‌ۚ يَخۡلُقُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١٧',
    17, 6, 2, 110, 88, 44, 'false'
  );
  
  -- Ayah 18 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    687,
    'وَقَالَتِ ٱلۡیَهُودُ وَٱلنَّصَـٰرَىٰ نَحۡنُ أَبۡنَـٰۤؤُا۟ ٱللَّهِ وَأَحِبَّـٰۤؤُهُۥۚ قُلۡ فَلِمَ یُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرࣱ مِّمَّنۡ خَلَقَۚ یَغۡفِرُ لِمَن یَشَاۤءُ وَیُعَذِّبُ مَن یَشَاۤءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۖ وَإِلَیۡهِ ٱلۡمَصِیرُ',
    'وقالت اليهود والنصارى نحن ابناء الله واحباؤه قل فلم يعذبكم بذنوبكم بل انتم بشر ممن خلق يغفر لمن يشاء ويعذب من يشاء ولله ملك السماوات والارض وما بينهما واليه المصير',
    'وَقَالَتِ <rule class=ham_wasl>ٱ</rule>لۡيَهُودُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَىٰ نَحۡنُ أَ<rule class=qalaqah>بۡ</rule>نَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهِ وَأَحِبَّ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُهُ<rule class=madda_normal>ۥ</rule>‌ۚ قُلۡ فَلِمَ يُعَذِّبُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذُنُوبِك<rule class=ikhafa_shafawi>ُم‌ۖ</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َنۡ خَلَقَ‌ۚ يَغۡفِرُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيُعَذِّبُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَلِلَّهِ مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا‌ۖ وَإِلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٨',
    18, 6, 2, 111, 88, 44, 'false'
  );
  
  -- Ayah 19 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    688,
    'یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ قَدۡ جَاۤءَكُمۡ رَسُولُنَا یُبَیِّنُ لَكُمۡ عَلَىٰ فَتۡرَةࣲ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَاۤءَنَا مِنۢ بَشِیرࣲ وَلَا نَذِیرࣲۖ فَقَدۡ جَاۤءَكُم بَشِیرࣱ وَنَذِیرࣱۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'يا اهل الكتاب قد جاءكم رسولنا يبين لكم على فترة من الرسل ان تقولوا ما جاءنا من بشير ولا نذير فقد جاءكم بشير ونذير والله على كل شيء قدير',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ رَسُولُنَا يُبَيِّنُ لَكُمۡ عَلَىٰ فَتۡرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولُو<rule class=slnt>اۡ</rule> مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َشِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَذِي<rule class=ikhafa>رٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َشِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َنَذِي<rule class=idgham_ghunnah>رٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١٩',
    19, 6, 2, 111, 88, 44, 'false'
  );
  
  -- Ayah 20 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    689,
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ یَـٰقَوۡمِ ٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ جَعَلَ فِیكُمۡ أَنۢبِیَاۤءَ وَجَعَلَكُم مُّلُوكࣰا وَءَاتَىٰكُم مَّا لَمۡ یُؤۡتِ أَحَدࣰا مِّنَ ٱلۡعَـٰلَمِینَ',
    'واذ قال موسى لقومه يا قوم اذكروا نعمة الله عليكم اذ جعل فيكم انبياء وجعلكم ملوكا واتاكم ما لم يؤت احدا من العالمين',
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِه<rule class=madda_normal>ِۦ</rule> يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ إِذۡ جَعَلَ فِيكُمۡ أَ<rule class=iqlab>نۢب</rule>ِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَجَعَلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلُو<rule class=idgham_ghunnah>كًا</rule> <rule class=idgham_ghunnah>و</rule>َءَاتَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا لَمۡ يُؤۡتِ أَحَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 6, 2, 111, 89, 44, 'false'
  );
  
  -- Ayah 21 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    690,
    'یَـٰقَوۡمِ ٱدۡخُلُوا۟ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِی كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّوا۟ عَلَىٰۤ أَدۡبَارِكُمۡ فَتَنقَلِبُوا۟ خَـٰسِرِینَ',
    'يا قوم ادخلوا الارض المقدسة التي كتب الله لكم ولا ترتدوا على ادباركم فتنقلبوا خاسرين',
    'يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ <rule class=ham_wasl>ٱ</rule>لۡمُقَدَّسَةَ <rule class=ham_wasl>ٱ</rule>لَّتِى كَتَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ وَلَا تَرۡتَدُّو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=qalaqah>دۡ</rule>بَارِكُمۡ فَتَ<rule class=ikhafa>نق</rule>َلِبُو<rule class=slnt>اۡ</rule> خَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٢١',
    21, 6, 2, 111, 89, 44, 'false'
  );
  
  -- Ayah 22 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    691,
    'قَالُوا۟ یَـٰمُوسَىٰۤ إِنَّ فِیهَا قَوۡمࣰا جَبَّارِینَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ یَخۡرُجُوا۟ مِنۡهَا فَإِن یَخۡرُجُوا۟ مِنۡهَا فَإِنَّا دَ ٰ⁠خِلُونَ',
    'قالوا يا موسى ان فيها قوما جبارين وانا لن ندخلها حتى يخرجوا منها فان يخرجوا منها فانا داخلون',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِيهَا قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ج</rule>َبَّارِينَ وَإِ<rule class=ghunnah>نّ</rule>َا ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>دۡ</rule>خُلَهَا حَتَّىٰ يَخۡرُجُو<rule class=slnt>اۡ</rule> مِنۡهَا فَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡرُجُو<rule class=slnt>اۡ</rule> مِنۡهَا فَإِ<rule class=ghunnah>نّ</rule>َا د<rule class=madda_normal>ٰ</rule>خِل<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 6, 2, 111, 89, 44, 'false'
  );
  
  -- Ayah 23 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    692,
    'قَالَ رَجُلَانِ مِنَ ٱلَّذِینَ یَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَیۡهِمَا ٱدۡخُلُوا۟ عَلَیۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَـٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوۤا۟ إِن كُنتُم مُّؤۡمِنِینَ',
    'قال رجلان من الذين يخافون انعم الله عليهما ادخلوا عليهم الباب فاذا دخلتموه فانكم غالبون وعلى الله فتوكلوا ان كنتم مؤمنين',
    'قَالَ رَجُلَانِ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَخَافُونَ أَنۡعَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِ<rule class=ghunnah>نّ</rule>َكُمۡ غَ<rule class=madda_normal>ـٰ</rule>لِبُونَ‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَتَوَكَّل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢٣',
    23, 6, 2, 111, 89, 44, 'false'
  );
  
  -- Ayah 24 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    693,
    'قَالُوا۟ یَـٰمُوسَىٰۤ إِنَّا لَن نَّدۡخُلَهَاۤ أَبَدࣰا مَّا دَامُوا۟ فِیهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَـٰتِلَاۤ إِنَّا هَـٰهُنَا قَـٰعِدُونَ',
    'قالوا يا موسى انا لن ندخلها ابدا ما داموا فيها فاذهب انت وربك فقاتلا انا هاهنا قاعدون',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َا ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>دۡ</rule>خُلَه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>َّا دَامُو<rule class=slnt>اۡ</rule> فِيهَا‌ۖ فَ<rule class=ham_wasl>ٱ</rule>ذۡهَ<rule class=qalaqah>بۡ</rule> أَ<rule class=ikhafa>نت</rule>َ وَرَبُّكَ فَقَ<rule class=madda_normal>ـٰ</rule>تِل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا هَ<rule class=madda_normal>ـٰ</rule>هُنَا قَ<rule class=madda_normal>ـٰ</rule>عِد<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 6, 2, 112, 89, 44, 'false'
  );
  
  -- Ayah 25 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    694,
    'قَالَ رَبِّ إِنِّی لَاۤ أَمۡلِكُ إِلَّا نَفۡسِی وَأَخِیۖ فَٱفۡرُقۡ بَیۡنَنَا وَبَیۡنَ ٱلۡقَوۡمِ ٱلۡفَـٰسِقِینَ',
    'قال رب اني لا املك الا نفسي واخي فافرق بيننا وبين القوم الفاسقين',
    'قَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى ل<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡلِكُ إِلَّا نَفۡسِى وَأَخِى‌ۖ فَ<rule class=ham_wasl>ٱ</rule>فۡرُ<rule class=qalaqah>قۡ</rule> بَيۡنَنَا وَبَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 6, 2, 112, 89, 44, 'false'
  );
  
  -- Ayah 26 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    695,
    'قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَیۡهِمۡۛ أَرۡبَعِینَ سَنَةࣰۛ یَتِیهُونَ فِی ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَـٰسِقِینَ',
    'قال فانها محرمة عليهم اربعين سنة يتيهون في الارض فلا تاس على القوم الفاسقين',
    'قَالَ فَإِ<rule class=ghunnah>نّ</rule>َهَا مُحَرَّمَةٌ عَلَيۡهِمۡ‌ۛ أَرۡبَعِينَ سَنَ<rule class=idgham_ghunnah>ةً‌ۛ</rule> <rule class=idgham_ghunnah>ي</rule>َتِيهُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ فَلَا تَأۡسَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٢٦',
    26, 6, 2, 112, 89, 44, 'false'
  );
  
  -- Ayah 27 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    696,
    '۞ وَٱتۡلُ عَلَیۡهِمۡ نَبَأَ ٱبۡنَیۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانࣰا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ یُتَقَبَّلۡ مِنَ ٱلۡـَٔاخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا یَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِینَ',
    'واتل عليهم نبا ابني ادم بالحق اذ قربا قربانا فتقبل من احدهما ولم يتقبل من الاخر قال لاقتلنك قال انما يتقبل الله من المتقين',
    '۞وَ<rule class=ham_wasl>ٱ</rule>تۡلُ عَلَيۡهِمۡ نَبَأَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_monfasel>َىۡ</rule> ءَادَمَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ إِذۡ قَرَّبَا قُرۡبَا<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ يُتَقَبَّلۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَخَرِ قَالَ لَأَ<rule class=qalaqah>قۡ</rule>تُلَ<rule class=ghunnah>نّ</rule>َكَ‌ۖ قَالَ إِ<rule class=ghunnah>نّ</rule>َمَا يَتَقَبَّلُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 6, 2, 112, 90, 45, 'false'
  );
  
  -- Ayah 28 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    697,
    'لَىِٕنۢ بَسَطتَ إِلَیَّ یَدَكَ لِتَقۡتُلَنِی مَاۤ أَنَا۠ بِبَاسِطࣲ یَدِیَ إِلَیۡكَ لِأَقۡتُلَكَۖ إِنِّیۤ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَـٰلَمِینَ',
    'لئن بسطت الي يدك لتقتلني ما انا بباسط يدي اليك لاقتلك اني اخاف الله رب العالمين',
    'لَئ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َسَطتَ إِلَىَّ يَدَكَ لِتَ<rule class=qalaqah>قۡ</rule>تُلَنِى م<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ بِبَاسِ<rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>ي</rule>َدِىَ إِلَيۡكَ لِأَ<rule class=qalaqah>قۡ</rule>تُلَكَ‌ۖ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ <rule class=ham_wasl>ٱ</rule>للَّهَ رَبَّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٢٨',
    28, 6, 2, 112, 90, 45, 'false'
  );
  
  -- Ayah 29 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    698,
    'إِنِّیۤ أُرِیدُ أَن تَبُوۤأَ بِإِثۡمِی وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَـٰبِ ٱلنَّارِۚ وَذَ ٰ⁠لِكَ جَزَ ٰ⁠ۤؤُا۟ ٱلظَّـٰلِمِینَ',
    'اني اريد ان تبوء باثمي واثمك فتكون من اصحاب النار وذلك جزاء الظالمين',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُرِيدُ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َب<rule class=madda_obligatory_mottasel>ُو</rule>ٓأَ بِإِثۡمِى وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>ٰ</rule>ٓؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 6, 2, 112, 90, 45, 'false'
  );
  
  -- Ayah 30 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    699,
    'فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِیهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَـٰسِرِینَ',
    'فطوعت له نفسه قتل اخيه فقتله فاصبح من الخاسرين',
    'فَطَوَّعَتۡ لَهُ<rule class=madda_normal>ۥ</rule> نَفۡسُهُ<rule class=madda_normal>ۥ</rule> قَتۡلَ أَخِيهِ فَقَتَلَهُ<rule class=madda_normal>ۥ</rule> فَأَصۡبَحَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٣٠',
    30, 6, 2, 112, 90, 45, 'false'
  );
  
  -- Ayah 31 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    700,
    'فَبَعَثَ ٱللَّهُ غُرَابࣰا یَبۡحَثُ فِی ٱلۡأَرۡضِ لِیُرِیَهُۥ كَیۡفَ یُوَ ٰ⁠رِی سَوۡءَةَ أَخِیهِۚ قَالَ یَـٰوَیۡلَتَىٰۤ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَـٰذَا ٱلۡغُرَابِ فَأُوَ ٰ⁠رِیَ سَوۡءَةَ أَخِیۖ فَأَصۡبَحَ مِنَ ٱلنَّـٰدِمِینَ',
    'فبعث الله غرابا يبحث في الارض ليريه كيف يواري سوءة اخيه قال يا ويلتا اعجزت ان اكون مثل هذا الغراب فاواري سوءة اخي فاصبح من النادمين',
    'فَبَعَثَ <rule class=ham_wasl>ٱ</rule>للَّهُ غُرَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>حَثُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لِيُرِيَهُ<rule class=madda_normal>ۥ</rule> كَيۡفَ يُو<rule class=madda_normal>ٰ</rule>رِى سَوۡءَةَ أَخِيهِ‌ۚ قَالَ يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَتَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡغُرَابِ فَأُو<rule class=madda_normal>ٰ</rule>رِىَ سَوۡءَةَ أَخِى‌ۖ فَأَصۡبَحَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>دِم<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 6, 2, 112, 90, 45, 'false'
  );
  
  -- Ayah 32 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    701,
    'مِنۡ أَجۡلِ ذَ ٰ⁠لِكَ كَتَبۡنَا عَلَىٰ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَیۡرِ نَفۡسٍ أَوۡ فَسَادࣲ فِی ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِیعࣰا وَمَنۡ أَحۡیَاهَا فَكَأَنَّمَاۤ أَحۡیَا ٱلنَّاسَ جَمِیعࣰاۚ وَلَقَدۡ جَاۤءَتۡهُمۡ رُسُلُنَا بِٱلۡبَیِّنَـٰتِ ثُمَّ إِنَّ كَثِیرࣰا مِّنۡهُم بَعۡدَ ذَ ٰ⁠لِكَ فِی ٱلۡأَرۡضِ لَمُسۡرِفُونَ',
    'من اجل ذلك كتبنا على بني اسرائيل انه من قتل نفسا بغير نفس او فساد في الارض فكانما قتل الناس جميعا ومن احياها فكانما احيا الناس جميعا ولقد جاءتهم رسلنا بالبينات ثم ان كثيرا منهم بعد ذلك في الارض لمسرفون',
    'مِنۡ أَ<rule class=qalaqah>جۡ</rule>لِ ذ<rule class=madda_normal>ٰ</rule>لِكَ كَتَ<rule class=qalaqah>بۡ</rule>نَا عَلَىٰ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َتَلَ نَفۡس<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِغَيۡرِ نَفۡسٍ أَوۡ فَسَا<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَكَأَ<rule class=ghunnah>نّ</rule>َمَا قَتَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َمَنۡ أَحۡيَاهَا فَكَأَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَحۡيَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ جَمِي<rule class=idgham_ghunnah>عًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ رُسُلُنَا بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لَمُسۡرِف<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 6, 2, 113, 90, 45, 'false'
  );
  
  -- Ayah 33 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    702,
    'إِنَّمَا جَزَ ٰ⁠ۤؤُا۟ ٱلَّذِینَ یُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَیَسۡعَوۡنَ فِی ٱلۡأَرۡضِ فَسَادًا أَن یُقَتَّلُوۤا۟ أَوۡ یُصَلَّبُوۤا۟ أَوۡ تُقَطَّعَ أَیۡدِیهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَـٰفٍ أَوۡ یُنفَوۡا۟ مِنَ ٱلۡأَرۡضِۚ ذَ ٰ⁠لِكَ لَهُمۡ خِزۡیࣱ فِی ٱلدُّنۡیَاۖ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابٌ عَظِیمٌ',
    'انما جزاء الذين يحاربون الله ورسوله ويسعون في الارض فسادا ان يقتلوا او يصلبوا او تقطع ايديهم وارجلهم من خلاف او ينفوا من الارض ذلك لهم خزي في الدنيا ولهم في الاخرة عذاب عظيم',
    'إِ<rule class=ghunnah>نّ</rule>َمَا جَز<rule class=madda_obligatory_mottasel>ٰ</rule>ٓؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُحَارِبُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> وَيَسۡعَوۡنَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَسَادًا أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُقَتَّل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡ يُصَلَّب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ وَأَرۡجُلُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خِلَ<rule class=madda_normal>ـٰ</rule>فٍ أَوۡ يُ<rule class=ikhafa>نف</rule>َوۡ<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ لَهُمۡ خِزۡ<rule class=ikhafa>ىٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَلَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٣٣',
    33, 6, 2, 113, 90, 45, 'false'
  );
  
  -- Ayah 34 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    703,
    'إِلَّا ٱلَّذِینَ تَابُوا۟ مِن قَبۡلِ أَن تَقۡدِرُوا۟ عَلَیۡهِمۡۖ فَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'الا الذين تابوا من قبل ان تقدروا عليهم فاعلموا ان الله غفور رحيم',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَابُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>قۡ</rule>دِرُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٣٤',
    34, 6, 2, 113, 90, 45, 'false'
  );
  
  -- Ayah 35 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    704,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبۡتَغُوۤا۟ إِلَیۡهِ ٱلۡوَسِیلَةَ وَجَـٰهِدُوا۟ فِی سَبِیلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ',
    'يا ايها الذين امنوا اتقوا الله وابتغوا اليه الوسيلة وجاهدوا في سبيله لعلكم تفلحون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡوَسِيلَةَ وَجَ<rule class=madda_normal>ـٰ</rule>هِدُو<rule class=slnt>اۡ</rule> فِى سَبِيلِه<rule class=madda_normal>ِۦ</rule> لَعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 6, 2, 113, 91, 45, 'false'
  );
  
  -- Ayah 36 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    705,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ لَوۡ أَنَّ لَهُم مَّا فِی ٱلۡأَرۡضِ جَمِیعࣰا وَمِثۡلَهُۥ مَعَهُۥ لِیَفۡتَدُوا۟ بِهِۦ مِنۡ عَذَابِ یَوۡمِ ٱلۡقِیَـٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِیمࣱ',
    'ان الذين كفروا لو ان لهم ما في الارض جميعا ومثله معه ليفتدوا به من عذاب يوم القيامة ما تقبل منهم ولهم عذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَوۡ أَ<rule class=ghunnah>نّ</rule>َ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َمِثۡلَهُ<rule class=madda_normal>ۥ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> لِيَفۡتَدُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> مِنۡ عَذَابِ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ مَا تُقُبِّلَ مِنۡهُمۡ‌ۖ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٣٦',
    36, 6, 2, 113, 91, 45, 'false'
  );
  
  -- Ayah 37 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    706,
    'یُرِیدُونَ أَن یَخۡرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَـٰرِجِینَ مِنۡهَاۖ وَلَهُمۡ عَذَابࣱ مُّقِیمࣱ',
    'يريدون ان يخرجوا من النار وما هم بخارجين منها ولهم عذاب مقيم',
    'يُرِيدُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡرُجُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ وَمَا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَ<rule class=madda_normal>ـٰ</rule>رِجِينَ مِنۡهَا‌ۖ وَلَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّق<rule class=madda_permissible>ِي</rule>مٌ ٣٧',
    37, 6, 2, 114, 91, 45, 'false'
  );
  
  -- Ayah 38 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    707,
    'وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوۤا۟ أَیۡدِیَهُمَا جَزَاۤءَۢ بِمَا كَسَبَا نَكَـٰلࣰا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِیزٌ حَكِیمࣱ',
    'والسارق والسارقة فاقطعوا ايديهما جزاء بما كسبا نكالا من الله والله عزيز حكيم',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّارِقُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّارِقَةُ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>طَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡدِيَهُمَا جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءَۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَسَبَا نَكَ<rule class=madda_normal>ـٰ</rule>ل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٣٨',
    38, 6, 2, 114, 91, 45, 'false'
  );
  
  -- Ayah 39 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    708,
    'فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ یَتُوبُ عَلَیۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ',
    'فمن تاب من بعد ظلمه واصلح فان الله يتوب عليه ان الله غفور رحيم',
    'فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ظُلۡمِه<rule class=madda_normal>ِۦ</rule> وَأَصۡلَحَ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَتُوبُ عَلَيۡهِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٣٩',
    39, 6, 2, 114, 91, 45, 'false'
  );
  
  -- Ayah 40 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    709,
    'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ یُعَذِّبُ مَن یَشَاۤءُ وَیَغۡفِرُ لِمَن یَشَاۤءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'الم تعلم ان الله له ملك السماوات والارض يعذب من يشاء ويغفر لمن يشاء والله على كل شيء قدير',
    'أَلَمۡ تَعۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يُعَذِّبُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَغۡفِرُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٤٠',
    40, 6, 2, 114, 91, 45, 'false'
  );
  
  -- Ayah 41 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    710,
    '۞ یَـٰۤأَیُّهَا ٱلرَّسُولُ لَا یَحۡزُنكَ ٱلَّذِینَ یُسَـٰرِعُونَ فِی ٱلۡكُفۡرِ مِنَ ٱلَّذِینَ قَالُوۤا۟ ءَامَنَّا بِأَفۡوَ ٰ⁠هِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِینَ هَادُوا۟ۛ سَمَّـٰعُونَ لِلۡكَذِبِ سَمَّـٰعُونَ لِقَوۡمٍ ءَاخَرِینَ لَمۡ یَأۡتُوكَۖ یُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ یَقُولُونَ إِنۡ أُوتِیتُمۡ هَـٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُوا۟ۚ وَمَن یُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَیۡـًٔاۚ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَمۡ یُرِدِ ٱللَّهُ أَن یُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِی ٱلدُّنۡیَا خِزۡیࣱۖ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابٌ عَظِیمࣱ',
    'يا ايها الرسول لا يحزنك الذين يسارعون في الكفر من الذين قالوا امنا بافواههم ولم تؤمن قلوبهم ومن الذين هادوا سماعون للكذب سماعون لقوم اخرين لم ياتوك يحرفون الكلم من بعد مواضعه يقولون ان اوتيتم هذا فخذوه وان لم تؤتوه فاحذروا ومن يرد الله فتنته فلن تملك له من الله شيئا اولئك الذين لم يرد الله ان يطهر قلوبهم لهم في الدنيا خزي ولهم في الاخرة عذاب عظيم',
    '۞يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ لَا يَحۡزُ<rule class=ikhafa>نك</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُسَ<rule class=madda_normal>ـٰ</rule>رِعُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِأَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ وَلَمۡ تُؤۡمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُلُوبُهُمۡ‌ۛ وَمِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَادُو<rule class=slnt>اۡ‌ۛ</rule> سَ<rule class=ghunnah>مّ</rule>َ<rule class=madda_normal>ـٰ</rule>عُونَ لِلۡكَذِبِ سَ<rule class=ghunnah>مّ</rule>َ<rule class=madda_normal>ـٰ</rule>عُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَ‌ۖ يُحَرِّفُونَ <rule class=ham_wasl>ٱ</rule>لۡكَلِمَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَوَاضِعِه<rule class=madda_normal>ِۦ</rule>‌ۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا فَخُذُوهُ وَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تُؤۡتَوۡهُ فَ<rule class=ham_wasl>ٱ</rule>حۡذَرُو<rule class=slnt>اۡ‌ۚ</rule> وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِدِ <rule class=ham_wasl>ٱ</rule>للَّهُ فِتۡنَتَهُ<rule class=madda_normal>ۥ</rule> فَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمۡلِكَ لَهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡــًٔا‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَمۡ يُرِدِ <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُطَهِّرَ قُلُوبَهُمۡ‌ۚ لَهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا خِزۡ<rule class=idgham_ghunnah>ىٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٤١',
    41, 6, 2, 114, 91, 46, 'false'
  );
  
  -- Ayah 42 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    711,
    'سَمَّـٰعُونَ لِلۡكَذِبِ أَكَّـٰلُونَ لِلسُّحۡتِۚ فَإِن جَاۤءُوكَ فَٱحۡكُم بَیۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن یَضُرُّوكَ شَیۡـࣰٔاۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَیۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُقۡسِطِینَ',
    'سماعون للكذب اكالون للسحت فان جاءوك فاحكم بينهم او اعرض عنهم وان تعرض عنهم فلن يضروك شيئا وان حكمت فاحكم بينهم بالقسط ان الله يحب المقسطين',
    'سَ<rule class=ghunnah>مّ</rule>َ<rule class=madda_normal>ـٰ</rule>عُونَ لِلۡكَذِبِ أَكَّ<rule class=madda_normal>ـٰ</rule>لُونَ لِلسُّحۡتِ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءُوكَ فَ<rule class=ham_wasl>ٱ</rule>حۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُعۡرِضۡ عَنۡهُمۡ فَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضُرُّوكَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِنۡ حَكَمۡتَ فَ<rule class=ham_wasl>ٱ</rule>حۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>قۡ</rule>سِط<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 6, 2, 115, 91, 46, 'false'
  );
  
  -- Ayah 43 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    712,
    'وَكَیۡفَ یُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِیهَا حُكۡمُ ٱللَّهِ ثُمَّ یَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَ ٰ⁠لِكَۚ وَمَاۤ أُو۟لَـٰۤىِٕكَ بِٱلۡمُؤۡمِنِینَ',
    'وكيف يحكمونك وعندهم التوراة فيها حكم الله ثم يتولون من بعد ذلك وما اولئك بالمؤمنين',
    'وَكَيۡفَ يُحَكِّمُونَكَ وَعِ<rule class=ikhafa>ند</rule>َهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةُ فِيهَا حُكۡمُ <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ يَتَوَلَّوۡنَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ بِ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٤٣',
    43, 6, 2, 115, 91, 46, 'false'
  );
  
  -- Ayah 44 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    713,
    'إِنَّاۤ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِیهَا هُدࣰى وَنُورࣱۚ یَحۡكُمُ بِهَا ٱلنَّبِیُّونَ ٱلَّذِینَ أَسۡلَمُوا۟ لِلَّذِینَ هَادُوا۟ وَٱلرَّبَّـٰنِیُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُوا۟ مِن كِتَـٰبِ ٱللَّهِ وَكَانُوا۟ عَلَیۡهِ شُهَدَاۤءَۚ فَلَا تَخۡشَوُا۟ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُوا۟ بِـَٔایَـٰتِی ثَمَنࣰا قَلِیلࣰاۚ وَمَن لَّمۡ یَحۡكُم بِمَاۤ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡكَـٰفِرُونَ',
    'انا انزلنا التوراة فيها هدى ونور يحكم بها النبيون الذين اسلموا للذين هادوا والربانيون والاحبار بما استحفظوا من كتاب الله وكانوا عليه شهداء فلا تخشوا الناس واخشون ولا تشتروا باياتي ثمنا قليلا ومن لم يحكم بما انزل الله فاولئك هم الكافرون',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةَ فِيهَا هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َنُو<rule class=idgham_ghunnah>رٌ‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>َحۡكُمُ بِهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيُّونَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَسۡلَمُو<rule class=slnt>اۡ</rule> لِلَّذِينَ هَادُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّبَّ<rule class=madda_normal>ـٰ</rule>نِيُّونَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَحۡبَارُ بِمَا <rule class=ham_wasl>ٱ</rule>سۡتُحۡفِظُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَكَانُو<rule class=slnt>اۡ</rule> عَلَيۡهِ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ فَلَا تَخۡشَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ وَ<rule class=ham_wasl>ٱ</rule>خۡشَوۡنِ وَلَا تَشۡتَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِى ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيل<rule class=idgham_ghunnah>اً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَحۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 6, 2, 115, 92, 46, 'false'
  );
  
  -- Ayah 45 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    714,
    'وَكَتَبۡنَا عَلَیۡهِمۡ فِیهَاۤ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَیۡنَ بِٱلۡعَیۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصࣱۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةࣱ لَّهُۥۚ وَمَن لَّمۡ یَحۡكُم بِمَاۤ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ',
    'وكتبنا عليهم فيها ان النفس بالنفس والعين بالعين والانف بالانف والاذن بالاذن والسن بالسن والجروح قصاص فمن تصدق به فهو كفارة له ومن لم يحكم بما انزل الله فاولئك هم الظالمون',
    'وَكَتَ<rule class=qalaqah>بۡ</rule>نَا عَلَيۡهِمۡ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َفۡسَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َفۡسِ وَ<rule class=ham_wasl>ٱ</rule>لۡعَيۡنَ بِ<rule class=ham_wasl>ٱ</rule>لۡعَيۡنِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>َ بِ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡأُذُنَ بِ<rule class=ham_wasl>ٱ</rule>لۡأُذُنِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=ghunnah>نّ</rule>َ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡجُرُوحَ قِصَا<rule class=ikhafa>صٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصَدَّقَ بِه<rule class=madda_normal>ِۦ</rule> فَهُوَ كَفَّارَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَحۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 6, 2, 115, 92, 46, 'false'
  );
  
  -- Ayah 46 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    715,
    'وَقَفَّیۡنَا عَلَىٰۤ ءَاثَـٰرِهِم بِعِیسَى ٱبۡنِ مَرۡیَمَ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَیۡنَـٰهُ ٱلۡإِنجِیلَ فِیهِ هُدࣰى وَنُورࣱ وَمُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدࣰى وَمَوۡعِظَةࣰ لِّلۡمُتَّقِینَ',
    'وقفينا على اثارهم بعيسى ابن مريم مصدقا لما بين يديه من التوراة واتيناه الانجيل فيه هدى ونور ومصدقا لما بين يديه من التوراة وهدى وموعظة للمتقين',
    'وَقَفَّيۡنَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاثَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِعِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ مَرۡيَمَ مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَيۡهِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةِ‌ۖ وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلَ فِيهِ هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َنُو<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َمُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَيۡهِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةِ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َمَوۡعِظَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 6, 2, 116, 92, 46, 'false'
  );
  
  -- Ayah 47 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    716,
    'وَلۡیَحۡكُمۡ أَهۡلُ ٱلۡإِنجِیلِ بِمَاۤ أَنزَلَ ٱللَّهُ فِیهِۚ وَمَن لَّمۡ یَحۡكُم بِمَاۤ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ',
    'وليحكم اهل الانجيل بما انزل الله فيه ومن لم يحكم بما انزل الله فاولئك هم الفاسقون',
    'وَلۡيَحۡكُمۡ أَهۡلُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلِ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ فِيهِ‌ۚ وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَحۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 6, 2, 116, 92, 46, 'false'
  );
  
  -- Ayah 48 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    717,
    'وَأَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ مِنَ ٱلۡكِتَـٰبِ وَمُهَیۡمِنًا عَلَیۡهِۖ فَٱحۡكُم بَیۡنَهُم بِمَاۤ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَاۤءَهُمۡ عَمَّا جَاۤءَكَ مِنَ ٱلۡحَقِّۚ لِكُلࣲّ جَعَلۡنَا مِنكُمۡ شِرۡعَةࣰ وَمِنۡهَاجࣰاۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةࣰ وَ ٰ⁠حِدَةࣰ وَلَـٰكِن لِّیَبۡلُوَكُمۡ فِی مَاۤ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُوا۟ ٱلۡخَیۡرَ ٰ⁠تِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِیعࣰا فَیُنَبِّئُكُم بِمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ',
    'وانزلنا اليك الكتاب بالحق مصدقا لما بين يديه من الكتاب ومهيمنا عليه فاحكم بينهم بما انزل الله ولا تتبع اهواءهم عما جاءك من الحق لكل جعلنا منكم شرعة ومنهاجا ولو شاء الله لجعلكم امة واحدة ولكن ليبلوكم في ما اتاكم فاستبقوا الخيرات الى الله مرجعكم جميعا فينبئكم بما كنتم فيه تختلفون',
    'وَأَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَيۡهِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَمُهَيۡمِنًا عَلَيۡهِ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>حۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَلَا تَتَّبِعۡ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ عَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ لِكُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>ج</rule>َعَلۡنَا مِ<rule class=ikhafa>نك</rule>ُمۡ شِرۡعَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َمِنۡهَا<rule class=idgham_ghunnah>جًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَجَعَلَكُمۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَ<rule class=qalaqah>بۡ</rule>لُوَكُمۡ فِى م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>سۡتَبِقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تِ‌ۚ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَرۡجِعُكُمۡ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َيُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ فِيهِ تَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 6, 2, 116, 92, 46, 'false'
  );
  
  -- Ayah 49 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    718,
    'وَأَنِ ٱحۡكُم بَیۡنَهُم بِمَاۤ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَاۤءَهُمۡ وَٱحۡذَرۡهُمۡ أَن یَفۡتِنُوكَ عَنۢ بَعۡضِ مَاۤ أَنزَلَ ٱللَّهُ إِلَیۡكَۖ فَإِن تَوَلَّوۡا۟ فَٱعۡلَمۡ أَنَّمَا یُرِیدُ ٱللَّهُ أَن یُصِیبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِیرࣰا مِّنَ ٱلنَّاسِ لَفَـٰسِقُونَ',
    'وان احكم بينهم بما انزل الله ولا تتبع اهواءهم واحذرهم ان يفتنوك عن بعض ما انزل الله اليك فان تولوا فاعلم انما يريد الله ان يصيبهم ببعض ذنوبهم وان كثيرا من الناس لفاسقون',
    'وَأَنِ <rule class=ham_wasl>ٱ</rule>حۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَا تَتَّبِعۡ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ وَ<rule class=ham_wasl>ٱ</rule>حۡذَرۡهُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡتِنُوكَ ع<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>َعۡضِ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَيۡكَ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule>عۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َمَا يُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُصِيبَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَعۡضِ ذُنُوبِهِمۡ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 6, 2, 116, 92, 46, 'false'
  );
  
  -- Ayah 50 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    719,
    'أَفَحُكۡمَ ٱلۡجَـٰهِلِیَّةِ یَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمࣰا لِّقَوۡمࣲ یُوقِنُونَ',
    'افحكم الجاهلية يبغون ومن احسن من الله حكما لقوم يوقنون',
    'أَفَحُكۡمَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِلِيَّةِ يَ<rule class=qalaqah>بۡ</rule>غُونَ‌ۚ وَمَنۡ أَحۡسَنُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ حُكۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوقِن<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 6, 2, 116, 92, 46, 'false'
  );
  
  -- Ayah 51 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    720,
    '۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلۡیَهُودَ وَٱلنَّصَـٰرَىٰۤ أَوۡلِیَاۤءَۘ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضࣲۚ وَمَن یَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'يا ايها الذين امنوا لا تتخذوا اليهود والنصارى اولياء بعضهم اولياء بعض ومن يتولهم منكم فانه منهم ان الله لا يهدي القوم الظالمين',
    '۞يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَتَّخِذُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَهُودَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۘ بَعۡضُهُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَلَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مِنۡهُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥١',
    51, 6, 2, 117, 93, 47, 'false'
  );
  
  -- Ayah 52 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    721,
    'فَتَرَى ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ یُسَـٰرِعُونَ فِیهِمۡ یَقُولُونَ نَخۡشَىٰۤ أَن تُصِیبَنَا دَاۤىِٕرَةࣱۚ فَعَسَى ٱللَّهُ أَن یَأۡتِیَ بِٱلۡفَتۡحِ أَوۡ أَمۡرࣲ مِّنۡ عِندِهِۦ فَیُصۡبِحُوا۟ عَلَىٰ مَاۤ أَسَرُّوا۟ فِیۤ أَنفُسِهِمۡ نَـٰدِمِینَ',
    'فترى الذين في قلوبهم مرض يسارعون فيهم يقولون نخشى ان تصيبنا دائرة فعسى الله ان ياتي بالفتح او امر من عنده فيصبحوا على ما اسروا في انفسهم نادمين',
    'فَتَرَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُسَ<rule class=madda_normal>ـٰ</rule>رِعُونَ فِيهِمۡ يَقُولُونَ نَخۡشَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِيبَنَا د<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرَ<rule class=ikhafa>ةٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َعَسَى <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِىَ بِ<rule class=ham_wasl>ٱ</rule>لۡفَتۡحِ أَوۡ أَمۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِه<rule class=madda_normal>ِۦ</rule> فَيُصۡبِحُو<rule class=slnt>اۡ</rule> عَلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أَسَرُّو<rule class=slnt>اۡ</rule> ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ نَ<rule class=madda_normal>ـٰ</rule>دِم<rule class=madda_permissible>ِي</rule>نَ ٥٢',
    52, 6, 2, 117, 93, 47, 'false'
  );
  
  -- Ayah 53 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    722,
    'وَیَقُولُ ٱلَّذِینَ ءَامَنُوۤا۟ أَهَـٰۤؤُلَاۤءِ ٱلَّذِینَ أَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَـٰلُهُمۡ فَأَصۡبَحُوا۟ خَـٰسِرِینَ',
    'ويقول الذين امنوا اهؤلاء الذين اقسموا بالله جهد ايمانهم انهم لمعكم حبطت اعمالهم فاصبحوا خاسرين',
    'وَيَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَ<rule class=qalaqah>قۡ</rule>سَمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ جَهۡدَ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ‌ۙ إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَمَعَكُمۡ‌ۚ حَبِطَتۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ فَأَصۡبَحُو<rule class=slnt>اۡ</rule> خَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 6, 2, 117, 93, 47, 'false'
  );
  
  -- Ayah 54 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    723,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ مَن یَرۡتَدَّ مِنكُمۡ عَن دِینِهِۦ فَسَوۡفَ یَأۡتِی ٱللَّهُ بِقَوۡمࣲ یُحِبُّهُمۡ وَیُحِبُّونَهُۥۤ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِینَ أَعِزَّةٍ عَلَى ٱلۡكَـٰفِرِینَ یُجَـٰهِدُونَ فِی سَبِیلِ ٱللَّهِ وَلَا یَخَافُونَ لَوۡمَةَ لَاۤىِٕمࣲۚ ذَ ٰ⁠لِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ وَ ٰ⁠سِعٌ عَلِیمٌ',
    'يا ايها الذين امنوا من يرتد منكم عن دينه فسوف ياتي الله بقوم يحبهم ويحبونه اذلة على المؤمنين اعزة على الكافرين يجاهدون في سبيل الله ولا يخافون لومة لائم ذلك فضل الله يؤتيه من يشاء والله واسع عليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َرۡتَدَّ مِ<rule class=ikhafa>نك</rule>ُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِينِه<rule class=madda_normal>ِۦ</rule> فَسَوۡفَ يَأۡتِى <rule class=ham_wasl>ٱ</rule>للَّهُ بِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُحِبُّهُمۡ وَيُحِبُّونَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَذِلَّةٍ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ يُجَ<rule class=madda_normal>ـٰ</rule>هِدُونَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا يَخَافُونَ لَوۡمَةَ ل<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=ikhafa>مٍ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ يُؤۡتِيهِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ و<rule class=madda_normal>ٰ</rule>سِعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٥٤',
    54, 6, 2, 117, 93, 47, 'false'
  );
  
  -- Ayah 55 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    724,
    'إِنَّمَا وَلِیُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِینَ ءَامَنُوا۟ ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَ ٰ⁠كِعُونَ',
    'انما وليكم الله ورسوله والذين امنوا الذين يقيمون الصلاة ويؤتون الزكاة وهم راكعون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا وَلِيُّكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُقِيمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَيُؤۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَهُمۡ ر<rule class=madda_normal>ٰ</rule>كِع<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 6, 2, 117, 93, 47, 'false'
  );
  
  -- Ayah 56 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    725,
    'وَمَن یَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِینَ ءَامَنُوا۟ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَـٰلِبُونَ',
    'ومن يتول الله ورسوله والذين امنوا فان حزب الله هم الغالبون',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَلَّ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ حِزۡبَ <rule class=ham_wasl>ٱ</rule>للَّهِ هُمُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>لِب<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 6, 2, 117, 93, 47, 'false'
  );
  
  -- Ayah 57 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    726,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِینَ ٱتَّخَذُوا۟ دِینَكُمۡ هُزُوࣰا وَلَعِبࣰا مِّنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِیَاۤءَۚ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِینَ',
    'يا ايها الذين امنوا لا تتخذوا الذين اتخذوا دينكم هزوا ولعبا من الذين اوتوا الكتاب من قبلكم والكفار اولياء واتقوا الله ان كنتم مؤمنين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَتَّخِذُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> دِينَكُمۡ هُزُ<rule class=idgham_ghunnah>وًا</rule> <rule class=idgham_ghunnah>و</rule>َلَعِ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡكُفَّارَ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٥٧',
    57, 6, 2, 117, 94, 47, 'false'
  );
  
  -- Ayah 58 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    727,
    'وَإِذَا نَادَیۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوࣰا وَلَعِبࣰاۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَعۡقِلُونَ',
    'واذا ناديتم الى الصلاة اتخذوها هزوا ولعبا ذلك بانهم قوم لا يعقلون',
    'وَإِذَا نَادَيۡتُمۡ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule>تَّخَذُوهَا هُزُ<rule class=idgham_ghunnah>وًا</rule> <rule class=idgham_ghunnah>و</rule>َلَعِ<rule class=ikhafa>بًا‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 6, 2, 118, 94, 47, 'false'
  );
  
  -- Ayah 59 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    728,
    'قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ هَلۡ تَنقِمُونَ مِنَّاۤ إِلَّاۤ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَاۤ أُنزِلَ إِلَیۡنَا وَمَاۤ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَـٰسِقُونَ',
    'قل يا اهل الكتاب هل تنقمون منا الا ان امنا بالله وما انزل الينا وما انزل من قبل وان اكثركم فاسقون',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ هَلۡ تَ<rule class=ikhafa>نق</rule>ِمُونَ مِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡ ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡنَا وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَأَ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَكُمۡ فَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 6, 2, 118, 94, 47, 'false'
  );
  
  -- Ayah 60 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    729,
    'قُلۡ هَلۡ أُنَبِّئُكُم بِشَرࣲّ مِّن ذَ ٰ⁠لِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَیۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِیرَ وَعَبَدَ ٱلطَّـٰغُوتَۚ أُو۟لَـٰۤىِٕكَ شَرࣱّ مَّكَانࣰا وَأَضَلُّ عَن سَوَاۤءِ ٱلسَّبِیلِ',
    'قل هل انبئكم بشر من ذلك مثوبة عند الله من لعنه الله وغضب عليه وجعل منهم القردة والخنازير وعبد الطاغوت اولئك شر مكانا واضل عن سواء السبيل',
    'قُلۡ هَلۡ أُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِشَ<rule class=idgham_ghunnah>رٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ مَثُوبَةً عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَنَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَغَضِبَ عَلَيۡهِ وَجَعَلَ مِنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡقِرَدَةَ وَ<rule class=ham_wasl>ٱ</rule>لۡخَنَازِيرَ وَعَبَدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّ<rule class=madda_normal>ـٰ</rule>غُوتَ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ شَ<rule class=idgham_ghunnah>رٌّ</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َأَضَلُّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َو<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لِ ٦٠',
    60, 6, 2, 118, 94, 47, 'false'
  );
  
  -- Ayah 61 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    730,
    'وَإِذَا جَاۤءُوكُمۡ قَالُوۤا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُوا۟ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُوا۟ یَكۡتُمُونَ',
    'واذا جاءوكم قالوا امنا وقد دخلوا بالكفر وهم قد خرجوا به والله اعلم بما كانوا يكتمون',
    'وَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوكُمۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا وَقَد دَّخَلُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ وَهُمۡ قَ<rule class=qalaqah>دۡ</rule> خَرَجُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡتُم<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 6, 2, 118, 94, 47, 'false'
  );
  
  -- Ayah 62 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    731,
    'وَتَرَىٰ كَثِیرࣰا مِّنۡهُمۡ یُسَـٰرِعُونَ فِی ٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰ⁠نِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'وترى كثيرا منهم يسارعون في الاثم والعدوان واكلهم السحت لبئس ما كانوا يعملون',
    'وَتَرَىٰ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ يُسَ<rule class=madda_normal>ـٰ</rule>رِعُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَ<rule class=ham_wasl>ٱ</rule>لۡعُ<rule class=qalaqah>دۡ</rule>و<rule class=madda_normal>ٰ</rule>نِ وَأَكۡلِهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّحۡتَ‌ۚ لَبِئۡسَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 6, 2, 118, 94, 47, 'false'
  );
  
  -- Ayah 63 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    732,
    'لَوۡلَا یَنۡهَىٰهُمُ ٱلرَّبَّـٰنِیُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُوا۟ یَصۡنَعُونَ',
    'لولا ينهاهم الربانيون والاحبار عن قولهم الاثم واكلهم السحت لبئس ما كانوا يصنعون',
    'لَوۡلَا يَنۡهَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّبَّ<rule class=madda_normal>ـٰ</rule>نِيُّونَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَحۡبَارُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡلِهِمُ <rule class=ham_wasl>ٱ</rule>لۡإِثۡمَ وَأَكۡلِهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّحۡتَ‌ۚ لَبِئۡسَ مَا كَانُو<rule class=slnt>اۡ</rule> يَصۡنَع<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 6, 2, 118, 94, 47, 'false'
  );
  
  -- Ayah 64 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    733,
    'وَقَالَتِ ٱلۡیَهُودُ یَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَیۡدِیهِمۡ وَلُعِنُوا۟ بِمَا قَالُوا۟ۘ بَلۡ یَدَاهُ مَبۡسُوطَتَانِ یُنفِقُ كَیۡفَ یَشَاۤءُۚ وَلَیَزِیدَنَّ كَثِیرࣰا مِّنۡهُم مَّاۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ طُغۡیَـٰنࣰا وَكُفۡرࣰاۚ وَأَلۡقَیۡنَا بَیۡنَهُمُ ٱلۡعَدَ ٰ⁠وَةَ وَٱلۡبَغۡضَاۤءَ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِۚ كُلَّمَاۤ أَوۡقَدُوا۟ نَارࣰا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَیَسۡعَوۡنَ فِی ٱلۡأَرۡضِ فَسَادࣰاۚ وَٱللَّهُ لَا یُحِبُّ ٱلۡمُفۡسِدِینَ',
    'وقالت اليهود يد الله مغلولة غلت ايديهم ولعنوا بما قالوا بل يداه مبسوطتان ينفق كيف يشاء وليزيدن كثيرا منهم ما انزل اليك من ربك طغيانا وكفرا والقينا بينهم العداوة والبغضاء الى يوم القيامة كلما اوقدوا نارا للحرب اطفاها الله ويسعون في الارض فسادا والله لا يحب المفسدين',
    'وَقَالَتِ <rule class=ham_wasl>ٱ</rule>لۡيَهُودُ يَدُ <rule class=ham_wasl>ٱ</rule>للَّهِ مَغۡلُولَةٌ‌ۚ غُلَّتۡ أَيۡدِيهِمۡ وَلُعِنُو<rule class=slnt>اۡ</rule> بِمَا قَالُو<rule class=slnt>اۡ‌ۘ</rule> بَلۡ يَدَاهُ مَ<rule class=qalaqah>بۡ</rule>سُوطَتَانِ يُ<rule class=ikhafa>نف</rule>ِقُ كَيۡفَ يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَلَيَزِيدَ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ طُغۡيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َكُفۡ<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَلۡقَيۡنَا بَيۡنَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَد<rule class=madda_normal>ٰ</rule>وَةَ وَ<rule class=ham_wasl>ٱ</rule>لۡبَغۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ كُلَّم<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡقَدُو<rule class=slnt>اۡ</rule> نَا<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡحَرۡبِ أَ<rule class=qalaqah>طۡ</rule>فَأَهَا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَيَسۡعَوۡنَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَسَا<rule class=idgham_ghunnah>دًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٦٤',
    64, 6, 2, 118, 94, 47, 'false'
  );
  
  -- Ayah 65 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    734,
    'وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَـٰبِ ءَامَنُوا۟ وَٱتَّقَوۡا۟ لَكَفَّرۡنَا عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَـٰهُمۡ جَنَّـٰتِ ٱلنَّعِیمِ',
    'ولو ان اهل الكتاب امنوا واتقوا لكفرنا عنهم سيئاتهم ولادخلناهم جنات النعيم',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َ أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> لَكَفَّرۡنَا عَنۡهُمۡ سَيِّـَٔـاتِهِمۡ وَلَأَ<rule class=qalaqah>دۡ</rule>خَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َع<rule class=madda_permissible>ِي</rule>مِ ٦٥',
    65, 6, 2, 119, 94, 47, 'false'
  );
  
  -- Ayah 66 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    735,
    'وَلَوۡ أَنَّهُمۡ أَقَامُوا۟ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَ وَمَاۤ أُنزِلَ إِلَیۡهِم مِّن رَّبِّهِمۡ لَأَكَلُوا۟ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةࣱ مُّقۡتَصِدَةࣱۖ وَكَثِیرࣱ مِّنۡهُمۡ سَاۤءَ مَا یَعۡمَلُونَ',
    'ولو انهم اقاموا التوراة والانجيل وما انزل اليهم من ربهم لاكلوا من فوقهم ومن تحت ارجلهم منهم امة مقتصدة وكثير منهم ساء ما يعملون',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ أَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ لَأَكَلُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهِمۡ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِ أَرۡجُلِه<rule class=idgham_shafawi>ِم‌ۚ</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُمۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَصِدَ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َكَثِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 6, 2, 119, 94, 47, 'false'
  );
  
  -- Ayah 67 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    736,
    '۞ یَـٰۤأَیُّهَا ٱلرَّسُولُ بَلِّغۡ مَاۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ یَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡكَـٰفِرِینَ',
    'يا ايها الرسول بلغ ما انزل اليك من ربك وان لم تفعل فما بلغت رسالته والله يعصمك من الناس ان الله لا يهدي القوم الكافرين',
    '۞يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ بَلِّغۡ م<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۖ وَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡصِمُكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٦٧',
    67, 6, 2, 119, 95, 48, 'false'
  );
  
  -- Ayah 68 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    737,
    'قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لَسۡتُمۡ عَلَىٰ شَیۡءٍ حَتَّىٰ تُقِیمُوا۟ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَ وَمَاۤ أُنزِلَ إِلَیۡكُم مِّن رَّبِّكُمۡۗ وَلَیَزِیدَنَّ كَثِیرࣰا مِّنۡهُم مَّاۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ طُغۡیَـٰنࣰا وَكُفۡرࣰاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ',
    'قل يا اهل الكتاب لستم على شيء حتى تقيموا التوراة والانجيل وما انزل اليكم من ربكم وليزيدن كثيرا منهم ما انزل اليك من ربك طغيانا وكفرا فلا تاس على القوم الكافرين',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَسۡتُمۡ عَلَىٰ شَىۡءٍ حَتَّىٰ تُقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۗ وَلَيَزِيدَ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ طُغۡيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َكُفۡ<rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َلَا تَأۡسَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٦٨',
    68, 6, 2, 119, 95, 48, 'false'
  );
  
  -- Ayah 69 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    738,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَادُوا۟ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَـٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَعَمِلَ صَـٰلِحࣰا فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'ان الذين امنوا والذين هادوا والصابئون والنصارى من امن بالله واليوم الاخر وعمل صالحا فلا خوف عليهم ولا هم يحزنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هَادُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِــُٔونَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَىٰ مَنۡ ءَامَنَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 6, 2, 119, 95, 48, 'false'
  );
  
  -- Ayah 70 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    739,
    'لَقَدۡ أَخَذۡنَا مِیثَـٰقَ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ وَأَرۡسَلۡنَاۤ إِلَیۡهِمۡ رُسُلࣰاۖ كُلَّمَا جَاۤءَهُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰۤ أَنفُسُهُمۡ فَرِیقࣰا كَذَّبُوا۟ وَفَرِیقࣰا یَقۡتُلُونَ',
    'لقد اخذنا ميثاق بني اسرائيل وارسلنا اليهم رسلا كلما جاءهم رسول بما لا تهوى انفسهم فريقا كذبوا وفريقا يقتلون',
    'لَقَ<rule class=qalaqah>دۡ</rule> أَخَذۡنَا مِيثَ<rule class=madda_normal>ـٰ</rule>قَ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ وَأَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِمۡ رُسُل<rule class=ikhafa>اً‌ۖ</rule> <rule class=ikhafa>ك</rule>ُلَّمَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ رَسُو<rule class=iqlab>لُۢ</rule> <rule class=iqlab>ب</rule>ِمَا لَا تَهۡوَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ فَرِي<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ك</rule>َذَّبُو<rule class=slnt>اۡ</rule> وَفَرِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>تُل<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 6, 2, 119, 95, 48, 'false'
  );
  
  -- Ayah 71 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    740,
    'وَحَسِبُوۤا۟ أَلَّا تَكُونَ فِتۡنَةࣱ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَیۡهِمۡ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِیرࣱ مِّنۡهُمۡۚ وَٱللَّهُ بَصِیرُۢ بِمَا یَعۡمَلُونَ',
    'وحسبوا الا تكون فتنة فعموا وصموا ثم تاب الله عليهم ثم عموا وصموا كثير منهم والله بصير بما يعملون',
    'وَحَسِب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَلَّا تَكُونَ فِتۡنَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َعَمُو<rule class=slnt>اۡ</rule> وَصَ<rule class=ghunnah>مّ</rule>ُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ تَابَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمۡ ثُ<rule class=ghunnah>مّ</rule>َ عَمُو<rule class=slnt>اۡ</rule> وَصَ<rule class=ghunnah>مّ</rule>ُو<rule class=slnt>اۡ</rule> كَثِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بَصِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 6, 2, 120, 95, 48, 'false'
  );
  
  -- Ayah 72 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    741,
    'لَقَدۡ كَفَرَ ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِیحُ ٱبۡنُ مَرۡیَمَۖ وَقَالَ ٱلۡمَسِیحُ یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱعۡبُدُوا۟ ٱللَّهَ رَبِّی وَرَبَّكُمۡۖ إِنَّهُۥ مَن یُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَیۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّـٰلِمِینَ مِنۡ أَنصَارࣲ',
    'لقد كفر الذين قالوا ان الله هو المسيح ابن مريم وقال المسيح يا بني اسرائيل اعبدوا الله ربي وربكم انه من يشرك بالله فقد حرم الله عليه الجنة وماواه النار وما للظالمين من انصار',
    'لَقَ<rule class=qalaqah>دۡ</rule> كَفَرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡمَسِيحُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ‌ۖ وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَسِيحُ يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ رَبِّى وَرَبَّكُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُشۡرِكۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ فَقَ<rule class=qalaqah>دۡ</rule> حَرَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ وَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ‌ۖ وَمَا لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ مِنۡ أَ<rule class=ikhafa>نص</rule><rule class=madda_permissible>َا</rule>رٍ ٧٢',
    72, 6, 2, 120, 95, 48, 'false'
  );
  
  -- Ayah 73 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    742,
    'لَّقَدۡ كَفَرَ ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَـٰثَةࣲۘ وَمَا مِنۡ إِلَـٰهٍ إِلَّاۤ إِلَـٰهࣱ وَ ٰ⁠حِدࣱۚ وَإِن لَّمۡ یَنتَهُوا۟ عَمَّا یَقُولُونَ لَیَمَسَّنَّ ٱلَّذِینَ كَفَرُوا۟ مِنۡهُمۡ عَذَابٌ أَلِیمٌ',
    'لقد كفر الذين قالوا ان الله ثالث ثلاثة وما من اله الا اله واحد وان لم ينتهوا عما يقولون ليمسن الذين كفروا منهم عذاب اليم',
    'لَّقَ<rule class=qalaqah>دۡ</rule> كَفَرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ ثَالِثُ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَ<rule class=idgham_ghunnah>ةٍ‌ۘ</rule> <rule class=idgham_ghunnah>و</rule>َمَا مِنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَ<rule class=ikhafa>نت</rule>َهُو<rule class=slnt>اۡ</rule> عَ<rule class=ghunnah>مّ</rule>َا يَقُولُونَ لَيَمَسَّ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٧٣',
    73, 6, 2, 120, 95, 48, 'false'
  );
  
  -- Ayah 74 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    743,
    'أَفَلَا یَتُوبُونَ إِلَى ٱللَّهِ وَیَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'افلا يتوبون الى الله ويستغفرونه والله غفور رحيم',
    'أَفَلَا يَتُوبُونَ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَسۡتَغۡفِرُونَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٧٤',
    74, 6, 2, 120, 95, 48, 'false'
  );
  
  -- Ayah 75 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    744,
    'مَّا ٱلۡمَسِیحُ ٱبۡنُ مَرۡیَمَ إِلَّا رَسُولࣱ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّیقَةࣱۖ كَانَا یَأۡكُلَانِ ٱلطَّعَامَۗ ٱنظُرۡ كَیۡفَ نُبَیِّنُ لَهُمُ ٱلۡـَٔایَـٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ یُؤۡفَكُونَ',
    'ما المسيح ابن مريم الا رسول قد خلت من قبله الرسل وامه صديقة كانا ياكلان الطعام انظر كيف نبين لهم الايات ثم انظر انى يؤفكون',
    'مَّا <rule class=ham_wasl>ٱ</rule>لۡمَسِيحُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ إِلَّا رَسُو<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلُ وَأُ<rule class=ghunnah>مّ</rule>ُهُ<rule class=madda_normal>ۥ</rule> صِدِّيقَ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ك</rule>َانَا يَأۡكُلَانِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّعَامَ‌ۗ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ نُبَيِّنُ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ أَ<rule class=ghunnah>نّ</rule>َىٰ يُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 6, 2, 120, 95, 48, 'false'
  );
  
  -- Ayah 76 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    745,
    'قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَمۡلِكُ لَكُمۡ ضَرࣰّا وَلَا نَفۡعࣰاۚ وَٱللَّهُ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'قل اتعبدون من دون الله ما لا يملك لكم ضرا ولا نفعا والله هو السميع العليم',
    'قُلۡ أَتَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَمۡلِكُ لَكُمۡ ضَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَفۡ<rule class=idgham_ghunnah>عًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٧٦',
    76, 6, 2, 120, 95, 48, 'false'
  );
  
  -- Ayah 77 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    746,
    'قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لَا تَغۡلُوا۟ فِی دِینِكُمۡ غَیۡرَ ٱلۡحَقِّ وَلَا تَتَّبِعُوۤا۟ أَهۡوَاۤءَ قَوۡمࣲ قَدۡ ضَلُّوا۟ مِن قَبۡلُ وَأَضَلُّوا۟ كَثِیرࣰا وَضَلُّوا۟ عَن سَوَاۤءِ ٱلسَّبِیلِ',
    'قل يا اهل الكتاب لا تغلوا في دينكم غير الحق ولا تتبعوا اهواء قوم قد ضلوا من قبل واضلوا كثيرا وضلوا عن سواء السبيل',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَا تَغۡلُو<rule class=slnt>اۡ</rule> فِى دِينِكُمۡ غَيۡرَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَلَا تَتَّبِع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ قَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> ضَلُّو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَأَضَلُّو<rule class=slnt>اۡ</rule> كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َضَلُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َو<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لِ ٧٧',
    77, 6, 2, 121, 95, 48, 'false'
  );
  
  -- Ayah 78 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    747,
    'لُعِنَ ٱلَّذِینَ كَفَرُوا۟ مِنۢ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِیسَى ٱبۡنِ مَرۡیَمَۚ ذَ ٰ⁠لِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ یَعۡتَدُونَ',
    'لعن الذين كفروا من بني اسرائيل على لسان داوود وعيسى ابن مريم ذلك بما عصوا وكانوا يعتدون',
    'لُعِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ عَلَىٰ لِسَانِ دَاوُ<rule class=madda_normal>ۥ</rule>دَ وَعِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ مَرۡيَمَ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِمَا عَصَو<rule class=slnt>اۡ</rule> وَّكَانُو<rule class=slnt>اۡ</rule> يَعۡتَد<rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 6, 2, 121, 96, 48, 'false'
  );
  
  -- Ayah 79 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    748,
    'كَانُوا۟ لَا یَتَنَاهَوۡنَ عَن مُّنكَرࣲ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُوا۟ یَفۡعَلُونَ',
    'كانوا لا يتناهون عن منكر فعلوه لبئس ما كانوا يفعلون',
    'كَانُو<rule class=slnt>اۡ</rule> لَا يَتَنَاهَوۡنَ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=ikhafa>نك</rule>َ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َعَلُوهُ‌ۚ لَبِئۡسَ مَا كَانُو<rule class=slnt>اۡ</rule> يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 6, 2, 121, 96, 48, 'false'
  );
  
  -- Ayah 80 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    749,
    'تَرَىٰ كَثِیرࣰا مِّنۡهُمۡ یَتَوَلَّوۡنَ ٱلَّذِینَ كَفَرُوا۟ۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ أَن سَخِطَ ٱللَّهُ عَلَیۡهِمۡ وَفِی ٱلۡعَذَابِ هُمۡ خَـٰلِدُونَ',
    'ترى كثيرا منهم يتولون الذين كفروا لبئس ما قدمت لهم انفسهم ان سخط الله عليهم وفي العذاب هم خالدون',
    'تَرَىٰ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ يَتَوَلَّوۡنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ‌ۚ</rule> لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َخِطَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمۡ وَفِى <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ هُمۡ خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 6, 2, 121, 96, 48, 'false'
  );
  
  -- Ayah 81 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    750,
    'وَلَوۡ كَانُوا۟ یُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِیِّ وَمَاۤ أُنزِلَ إِلَیۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِیَاۤءَ وَلَـٰكِنَّ كَثِیرࣰا مِّنۡهُمۡ فَـٰسِقُونَ',
    'ولو كانوا يؤمنون بالله والنبي وما انزل اليه ما اتخذوهم اولياء ولكن كثيرا منهم فاسقون',
    'وَلَوۡ كَانُو<rule class=slnt>اۡ</rule> يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡهِ مَا <rule class=ham_wasl>ٱ</rule>تَّخَذُوهُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ فَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 6, 2, 121, 96, 48, 'false'
  );
  
  -- Ayah 82 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    751,
    '۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَ ٰ⁠وَةࣰ لِّلَّذِینَ ءَامَنُوا۟ ٱلۡیَهُودَ وَٱلَّذِینَ أَشۡرَكُوا۟ۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةࣰ لِّلَّذِینَ ءَامَنُوا۟ ٱلَّذِینَ قَالُوۤا۟ إِنَّا نَصَـٰرَىٰۚ ذَ ٰ⁠لِكَ بِأَنَّ مِنۡهُمۡ قِسِّیسِینَ وَرُهۡبَانࣰا وَأَنَّهُمۡ لَا یَسۡتَكۡبِرُونَ',
    'لتجدن اشد الناس عداوة للذين امنوا اليهود والذين اشركوا ولتجدن اقربهم مودة للذين امنوا الذين قالوا انا نصارى ذلك بان منهم قسيسين ورهبانا وانهم لا يستكبرون',
    '۞لَتَجِدَ<rule class=ghunnah>نّ</rule>َ أَشَدَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ عَد<rule class=madda_normal>ٰ</rule>وَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَهُودَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ أَشۡرَكُو<rule class=slnt>اۡ‌ۖ</rule> وَلَتَجِدَ<rule class=ghunnah>نّ</rule>َ أَ<rule class=qalaqah>قۡ</rule>رَبَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوَدَّ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا نَصَ<rule class=madda_normal>ـٰ</rule>رَىٰ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ مِنۡهُمۡ قِسِّيسِينَ وَرُهۡبَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َهُمۡ لَا يَسۡتَكۡبِر<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 7, 2, 121, 96, 49, 'false'
  );
  
  -- Ayah 83 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    752,
    'وَإِذَا سَمِعُوا۟ مَاۤ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰۤ أَعۡیُنَهُمۡ تَفِیضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُوا۟ مِنَ ٱلۡحَقِّۖ یَقُولُونَ رَبَّنَاۤ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِینَ',
    'واذا سمعوا ما انزل الى الرسول ترى اعينهم تفيض من الدمع مما عرفوا من الحق يقولون ربنا امنا فاكتبنا مع الشاهدين',
    'وَإِذَا سَمِعُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ تَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَعۡيُنَهُمۡ تَفِيضُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّمۡعِ مِ<rule class=ghunnah>مّ</rule>َا عَرَفُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ يَقُولُونَ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا فَ<rule class=ham_wasl>ٱ</rule>كۡتُ<rule class=qalaqah>بۡ</rule>نَا مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>هِد<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 7, 2, 122, 96, 49, 'false'
  );
  
  -- Ayah 84 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    753,
    'وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَاۤءَنَا مِنَ ٱلۡحَقِّ وَنَطۡمَعُ أَن یُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّـٰلِحِینَ',
    'وما لنا لا نؤمن بالله وما جاءنا من الحق ونطمع ان يدخلنا ربنا مع القوم الصالحين',
    'وَمَا لَنَا لَا نُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَمَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَنَ<rule class=qalaqah>طۡ</rule>مَعُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>دۡ</rule>خِلَنَا رَبُّنَا مَعَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٨٤',
    84, 7, 2, 122, 96, 49, 'false'
  );
  
  -- Ayah 85 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    754,
    'فَأَثَـٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَذَ ٰ⁠لِكَ جَزَاۤءُ ٱلۡمُحۡسِنِینَ',
    'فاثابهم الله بما قالوا جنات تجري من تحتها الانهار خالدين فيها وذلك جزاء المحسنين',
    'فَأَثَ<rule class=madda_normal>ـٰ</rule>بَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا قَالُو<rule class=slnt>اۡ</rule> جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 7, 2, 122, 96, 49, 'false'
  );
  
  -- Ayah 86 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    755,
    'وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ',
    'والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَكَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ٨٦',
    86, 7, 2, 122, 96, 49, 'false'
  );
  
  -- Ayah 87 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    756,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَیِّبَـٰتِ مَاۤ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوۤا۟ۚ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡمُعۡتَدِینَ',
    'يا ايها الذين امنوا لا تحرموا طيبات ما احل الله لكم ولا تعتدوا ان الله لا يحب المعتدين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تُحَرِّمُو<rule class=slnt>اۡ</rule> طَيِّبَ<rule class=madda_normal>ـٰ</rule>تِ م<rule class=madda_obligatory_monfasel>َآ</rule> أَحَلَّ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ وَلَا تَعۡتَد<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُعۡتَد<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 7, 2, 122, 97, 49, 'false'
  );
  
  -- Ayah 88 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    757,
    'وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَـٰلࣰا طَیِّبࣰاۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ أَنتُم بِهِۦ مُؤۡمِنُونَ',
    'وكلوا مما رزقكم الله حلالا طيبا واتقوا الله الذي انتم به مؤمنون',
    'وَكُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَقَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ حَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ط</rule>َيِّ<rule class=idgham_ghunnah>بًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 7, 2, 122, 97, 49, 'false'
  );
  
  -- Ayah 89 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    758,
    'لَا یُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِیۤ أَیۡمَـٰنِكُمۡ وَلَـٰكِن یُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَیۡمَـٰنَۖ فَكَفَّـٰرَتُهُۥۤ إِطۡعَامُ عَشَرَةِ مَسَـٰكِینَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِیكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِیرُ رَقَبَةࣲۖ فَمَن لَّمۡ یَجِدۡ فَصِیَامُ ثَلَـٰثَةِ أَیَّامࣲۚ ذَ ٰ⁠لِكَ كَفَّـٰرَةُ أَیۡمَـٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوۤا۟ أَیۡمَـٰنَكُمۡۚ كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ لَكُمۡ ءَایَـٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ',
    'لا يؤاخذكم الله باللغو في ايمانكم ولكن يؤاخذكم بما عقدتم الايمان فكفارته اطعام عشرة مساكين من اوسط ما تطعمون اهليكم او كسوتهم او تحرير رقبة فمن لم يجد فصيام ثلاثة ايام ذلك كفارة ايمانكم اذا حلفتم واحفظوا ايمانكم كذلك يبين الله لكم اياته لعلكم تشكرون',
    'لَا يُؤَاخِذُكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّغۡوِ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤَاخِذُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا عَقَّ<rule class=idgham_mutajanisayn>د</rule>تُّمُ <rule class=ham_wasl>ٱ</rule>لۡأَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ‌ۖ فَكَفَّ<rule class=madda_normal>ـٰ</rule>رَتُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=qalaqah>طۡ</rule>عَامُ عَشَرَةِ مَسَ<rule class=madda_normal>ـٰ</rule>كِينَ مِنۡ أَوۡسَطِ مَا تُ<rule class=qalaqah>طۡ</rule>عِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَ<rule class=ikhafa>ةٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَجِ<rule class=qalaqah>دۡ</rule> فَصِيَامُ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَةِ أَيَّا<rule class=ikhafa>مٍ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ كَفَّ<rule class=madda_normal>ـٰ</rule>رَةُ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ إِذَا حَلَفۡتُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>حۡفَظ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> لَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٨٩',
    89, 7, 2, 122, 97, 49, 'false'
  );
  
  -- Ayah 90 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    759,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَیۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَـٰمُ رِجۡسࣱ مِّنۡ عَمَلِ ٱلشَّیۡطَـٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ',
    'يا ايها الذين امنوا انما الخمر والميسر والانصاب والازلام رجس من عمل الشيطان فاجتنبوه لعلكم تفلحون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡخَمۡرُ وَ<rule class=ham_wasl>ٱ</rule>لۡمَيۡسِرُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نص</rule>َابُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَزۡلَ<rule class=madda_normal>ـٰ</rule>مُ رِ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عَمَلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَنِبُوهُ لَعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٩٠',
    90, 7, 2, 123, 97, 49, 'false'
  );
  
  -- Ayah 91 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    760,
    'إِنَّمَا یُرِیدُ ٱلشَّیۡطَـٰنُ أَن یُوقِعَ بَیۡنَكُمُ ٱلۡعَدَ ٰ⁠وَةَ وَٱلۡبَغۡضَاۤءَ فِی ٱلۡخَمۡرِ وَٱلۡمَیۡسِرِ وَیَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ',
    'انما يريد الشيطان ان يوقع بينكم العداوة والبغضاء في الخمر والميسر ويصدكم عن ذكر الله وعن الصلاة فهل انتم منتهون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا يُرِيدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُوقِعَ بَيۡنَكُمُ <rule class=ham_wasl>ٱ</rule>لۡعَد<rule class=madda_normal>ٰ</rule>وَةَ وَ<rule class=ham_wasl>ٱ</rule>لۡبَغۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فِى <rule class=ham_wasl>ٱ</rule>لۡخَمۡرِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَيۡسِرِ وَيَصُدَّكُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَعَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ‌ۖ فَهَلۡ أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=ikhafa>نت</rule>َه<rule class=madda_permissible>ُو</rule>نَ ٩١',
    91, 7, 2, 123, 97, 49, 'false'
  );
  
  -- Ayah 92 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    761,
    'وَأَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَ وَٱحۡذَرُوا۟ۚ فَإِن تَوَلَّیۡتُمۡ فَٱعۡلَمُوۤا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ',
    'واطيعوا الله واطيعوا الرسول واحذروا فان توليتم فاعلموا انما على رسولنا البلاغ المبين',
    'وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ وَ<rule class=ham_wasl>ٱ</rule>حۡذَرُو<rule class=slnt>اۡ‌ۚ</rule> فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّيۡتُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َمَا عَلَىٰ رَسُولِنَا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ٩٢',
    92, 7, 2, 123, 97, 49, 'false'
  );
  
  -- Ayah 93 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    762,
    'لَیۡسَ عَلَى ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جُنَاحࣱ فِیمَا طَعِمُوۤا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحۡسَنُوا۟ۚ وَٱللَّهُ یُحِبُّ ٱلۡمُحۡسِنِینَ',
    'ليس على الذين امنوا وعملوا الصالحات جناح فيما طعموا اذا ما اتقوا وامنوا وعملوا الصالحات ثم اتقوا وامنوا ثم اتقوا واحسنوا والله يحب المحسنين',
    'لَيۡسَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ جُنَا<rule class=ikhafa>حٌ</rule> <rule class=ikhafa>ف</rule>ِيمَا طَعِم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا مَا <rule class=ham_wasl>ٱ</rule>تَّقَو<rule class=slnt>اۡ</rule> وَّءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>تَّقَو<rule class=slnt>اۡ</rule> وَّءَامَنُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>تَّقَو<rule class=slnt>اۡ</rule> وَّأَحۡسَنُو<rule class=slnt>اۡ‌ۗ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٩٣',
    93, 7, 2, 123, 97, 49, 'false'
  );
  
  -- Ayah 94 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    763,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَیَبۡلُوَنَّكُمُ ٱللَّهُ بِشَیۡءࣲ مِّنَ ٱلصَّیۡدِ تَنَالُهُۥۤ أَیۡدِیكُمۡ وَرِمَاحُكُمۡ لِیَعۡلَمَ ٱللَّهُ مَن یَخَافُهُۥ بِٱلۡغَیۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَ ٰ⁠لِكَ فَلَهُۥ عَذَابٌ أَلِیمࣱ',
    'يا ايها الذين امنوا ليبلونكم الله بشيء من الصيد تناله ايديكم ورماحكم ليعلم الله من يخافه بالغيب فمن اعتدى بعد ذلك فله عذاب اليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَيَ<rule class=qalaqah>بۡ</rule>لُوَ<rule class=ghunnah>نّ</rule>َكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡدِ تَنَالُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَيۡدِيكُمۡ وَرِمَاحُكُمۡ لِيَعۡلَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخَافُهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ‌ۚ فَمَنِ <rule class=ham_wasl>ٱ</rule>عۡتَدَىٰ بَعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَلَهُ<rule class=madda_normal>ۥ</rule> عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٩٤',
    94, 7, 2, 123, 98, 49, 'false'
  );
  
  -- Ayah 95 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    764,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَقۡتُلُوا۟ ٱلصَّیۡدَ وَأَنتُمۡ حُرُمࣱۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدࣰا فَجَزَاۤءࣱ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ یَحۡكُمُ بِهِۦ ذَوَا عَدۡلࣲ مِّنكُمۡ هَدۡیَۢا بَـٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّـٰرَةࣱ طَعَامُ مَسَـٰكِینَ أَوۡ عَدۡلُ ذَ ٰ⁠لِكَ صِیَامࣰا لِّیَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا سَلَفَۚ وَمَنۡ عَادَ فَیَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِیزࣱ ذُو ٱنتِقَامٍ',
    'يا ايها الذين امنوا لا تقتلوا الصيد وانتم حرم ومن قتله منكم متعمدا فجزاء مثل ما قتل من النعم يحكم به ذوا عدل منكم هديا بالغ الكعبة او كفارة طعام مساكين او عدل ذلك صياما ليذوق وبال امره عفا الله عما سلف ومن عاد فينتقم الله منه والله عزيز ذو انتقام',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَ<rule class=qalaqah>قۡ</rule>تُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡدَ وَأَ<rule class=ikhafa>نت</rule>ُمۡ حُرُ<rule class=idgham_ghunnah>مٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َتَلَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّتَعَ<rule class=ghunnah>مّ</rule>ِ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َجَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُ مَا قَتَلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َعَمِ يَحۡكُمُ بِه<rule class=madda_normal>ِۦ</rule> ذَوَا عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ هَ<rule class=qalaqah>دۡ</rule>ي<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َ<rule class=madda_normal>ـٰ</rule>لِغَ <rule class=ham_wasl>ٱ</rule>لۡكَعۡبَةِ أَوۡ كَفَّ<rule class=madda_normal>ـٰ</rule>رَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ط</rule>َعَامُ مَسَ<rule class=madda_normal>ـٰ</rule>كِينَ أَوۡ عَ<rule class=qalaqah>دۡ</rule>لُ ذ<rule class=madda_normal>ٰ</rule>لِكَ صِيَا<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَذُوقَ وَبَالَ أَمۡرِه<rule class=madda_normal>ِۦ</rule>‌ۗ عَفَا <rule class=ham_wasl>ٱ</rule>للَّهُ عَ<rule class=ghunnah>مّ</rule>َا سَلَفَ‌ۚ وَمَنۡ عَادَ فَيَ<rule class=ikhafa>نت</rule>َقِمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنۡهُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَزِي<rule class=ikhafa>زٌ</rule> <rule class=ikhafa>ذ</rule>ُو <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>ِق<rule class=madda_permissible>َا</rule>مٍ ٩٥',
    95, 7, 2, 123, 98, 49, 'false'
  );
  
  -- Ayah 96 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    765,
    'أُحِلَّ لَكُمۡ صَیۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَـٰعࣰا لَّكُمۡ وَلِلسَّیَّارَةِۖ وَحُرِّمَ عَلَیۡكُمۡ صَیۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمࣰاۗ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ إِلَیۡهِ تُحۡشَرُونَ',
    'احل لكم صيد البحر وطعامه متاعا لكم وللسيارة وحرم عليكم صيد البر ما دمتم حرما واتقوا الله الذي اليه تحشرون',
    'أُحِلَّ لَكُمۡ صَيۡدُ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ وَطَعَامُهُ<rule class=madda_normal>ۥ</rule> مَتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>عًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَلِلسَّيَّارَةِ‌ۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ <rule class=ham_wasl>ٱ</rule>لۡبَرِّ مَا دُمۡتُمۡ حُرُ<rule class=idgham_ghunnah>مًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ تُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 7, 2, 124, 98, 49, 'false'
  );
  
  -- Ayah 97 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    766,
    '۞ جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَیۡتَ ٱلۡحَرَامَ قِیَـٰمࣰا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡیَ وَٱلۡقَلَـٰۤىِٕدَۚ ذَ ٰ⁠لِكَ لِتَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمٌ',
    'جعل الله الكعبة البيت الحرام قياما للناس والشهر الحرام والهدي والقلائد ذلك لتعلموا ان الله يعلم ما في السماوات وما في الارض وان الله بكل شيء عليم',
    '۞جَعَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡكَعۡبَةَ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتَ <rule class=ham_wasl>ٱ</rule>لۡحَرَامَ قِيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهۡرَ <rule class=ham_wasl>ٱ</rule>لۡحَرَامَ وَ<rule class=ham_wasl>ٱ</rule>لۡهَ<rule class=qalaqah>دۡ</rule>ىَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِدَ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ لِتَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٩٧',
    97, 7, 2, 124, 98, 50, 'false'
  );
  
  -- Ayah 98 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    767,
    'ٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'اعلموا ان الله شديد العقاب وان الله غفور رحيم',
    'ٱعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِقَابِ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٩٨',
    98, 7, 2, 124, 98, 50, 'false'
  );
  
  -- Ayah 99 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    768,
    'مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَـٰغُۗ وَٱللَّهُ یَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ',
    'ما على الرسول الا البلاغ والله يعلم ما تبدون وما تكتمون',
    'مَّا عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ مَا تُ<rule class=qalaqah>بۡ</rule>دُونَ وَمَا تَكۡتُم<rule class=madda_permissible>ُو</rule>نَ ٩٩',
    99, 7, 2, 124, 98, 50, 'false'
  );
  
  -- Ayah 100 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    769,
    'قُل لَّا یَسۡتَوِی ٱلۡخَبِیثُ وَٱلطَّیِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِیثِۚ فَٱتَّقُوا۟ ٱللَّهَ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ',
    'قل لا يستوي الخبيث والطيب ولو اعجبك كثرة الخبيث فاتقوا الله يا اولي الالباب لعلكم تفلحون',
    'قُل لَّا يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡخَبِيثُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ <rule class=ham_wasl>ٱ</rule>لۡخَبِيثِ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_normal>ـٰ</rule>بِ لَعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٠٠',
    100, 7, 2, 124, 98, 50, 'false'
  );
  
  -- Ayah 101 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    770,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَسۡـَٔلُوا۟ عَنۡ أَشۡیَاۤءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُوا۟ عَنۡهَا حِینَ یُنَزَّلُ ٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِیمࣱ',
    'يا ايها الذين امنوا لا تسالوا عن اشياء ان تبد لكم تسؤكم وان تسالوا عنها حين ينزل القران تبد لكم عفا الله عنها والله غفور حليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَسۡــَٔلُو<rule class=slnt>اۡ</rule> عَنۡ أَشۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>بۡ</rule>دَ لَكُمۡ تَسُؤۡكُمۡ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡــَٔلُو<rule class=slnt>اۡ</rule> عَنۡهَا حِينَ يُنَزَّلُ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانُ تُ<rule class=qalaqah>بۡ</rule>دَ لَكُمۡ عَفَا <rule class=ham_wasl>ٱ</rule>للَّهُ عَنۡهَا‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُورٌ حَل<rule class=madda_permissible>ِي</rule>مٌ ١٠١',
    101, 7, 2, 124, 99, 50, 'false'
  );
  
  -- Ayah 102 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    771,
    'قَدۡ سَأَلَهَا قَوۡمࣱ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُوا۟ بِهَا كَـٰفِرِینَ',
    'قد سالها قوم من قبلكم ثم اصبحوا بها كافرين',
    'قَ<rule class=qalaqah>دۡ</rule> سَأَلَهَا قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ أَصۡبَحُو<rule class=slnt>اۡ</rule> بِهَا كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٠٢',
    102, 7, 2, 124, 99, 50, 'false'
  );
  
  -- Ayah 103 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    772,
    'مَا جَعَلَ ٱللَّهُ مِنۢ بَحِیرَةࣲ وَلَا سَاۤىِٕبَةࣲ وَلَا وَصِیلَةࣲ وَلَا حَامࣲ وَلَـٰكِنَّ ٱلَّذِینَ كَفَرُوا۟ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا یَعۡقِلُونَ',
    'ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام ولكن الذين كفروا يفترون على الله الكذب واكثرهم لا يعقلون',
    'مَا جَعَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َحِيرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا س<rule class=madda_obligatory_mottasel>َا</rule>ٓئِبَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا وَصِيلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا حَا<rule class=idgham_ghunnah>مٍ‌ۙ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> يَفۡتَرُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ‌ۖ وَأَكۡثَرُهُمۡ لَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٠٣',
    103, 7, 2, 124, 99, 50, 'false'
  );
  
  -- Ayah 104 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    773,
    'وَإِذَا قِیلَ لَهُمۡ تَعَالَوۡا۟ إِلَىٰ مَاۤ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسۡبُنَا مَا وَجَدۡنَا عَلَیۡهِ ءَابَاۤءَنَاۤۚ أَوَلَوۡ كَانَ ءَابَاۤؤُهُمۡ لَا یَعۡلَمُونَ شَیۡـࣰٔا وَلَا یَهۡتَدُونَ',
    'واذا قيل لهم تعالوا الى ما انزل الله والى الرسول قالوا حسبنا ما وجدنا عليه اباءنا اولو كان اباؤهم لا يعلمون شيئا ولا يهتدون',
    'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡ<rule class=slnt>اۡ</rule> إِلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَإِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ قَالُو<rule class=slnt>اۡ</rule> حَسۡبُنَا مَا وَجَ<rule class=qalaqah>دۡ</rule>نَا عَلَيۡهِ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أَوَلَوۡ كَانَ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُمۡ لَا يَعۡلَمُونَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٠٤',
    104, 7, 2, 125, 99, 50, 'false'
  );
  
  -- Ayah 105 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    774,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ عَلَیۡكُمۡ أَنفُسَكُمۡۖ لَا یَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَیۡتُمۡۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِیعࣰا فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'يا ايها الذين امنوا عليكم انفسكم لا يضركم من ضل اذا اهتديتم الى الله مرجعكم جميعا فينبئكم بما كنتم تعملون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> عَلَيۡكُمۡ أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ‌ۖ لَا يَضُرُّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَّ إِذَا <rule class=ham_wasl>ٱ</rule>هۡتَدَيۡتُمۡ‌ۚ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَرۡجِعُكُمۡ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َيُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٠٥',
    105, 7, 2, 125, 99, 50, 'false'
  );
  
  -- Ayah 106 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    775,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ شَهَـٰدَةُ بَیۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِینَ ٱلۡوَصِیَّةِ ٱثۡنَانِ ذَوَا عَدۡلࣲ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَیۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِی ٱلۡأَرۡضِ فَأَصَـٰبَتۡكُم مُّصِیبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَیُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِی بِهِۦ ثَمَنࣰا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَـٰدَةَ ٱللَّهِ إِنَّاۤ إِذࣰا لَّمِنَ ٱلۡـَٔاثِمِینَ',
    'يا ايها الذين امنوا شهادة بينكم اذا حضر احدكم الموت حين الوصية اثنان ذوا عدل منكم او اخران من غيركم ان انتم ضربتم في الارض فاصابتكم مصيبة الموت تحبسونهما من بعد الصلاة فيقسمان بالله ان ارتبتم لا نشتري به ثمنا ولو كان ذا قربى ولا نكتم شهادة الله انا اذا لمن الاثمين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> شَهَ<rule class=madda_normal>ـٰ</rule>دَةُ بَيۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ حِينَ <rule class=ham_wasl>ٱ</rule>لۡوَصِيَّةِ <rule class=ham_wasl>ٱ</rule>ثۡنَانِ ذَوَا عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَيۡرِكُمۡ إِنۡ أَ<rule class=ikhafa>نت</rule>ُمۡ ضَرَ<rule class=qalaqah>بۡ</rule>تُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَأَصَ<rule class=madda_normal>ـٰ</rule>بَتۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّصِيبَةُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ‌ۚ تَحۡبِسُونَهُمَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ فَيُ<rule class=qalaqah>قۡ</rule>سِمَانِ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ إِنِ <rule class=ham_wasl>ٱ</rule>رۡتَ<rule class=qalaqah>بۡ</rule>تُمۡ لَا نَشۡتَرِى بِه<rule class=madda_normal>ِۦ</rule> ثَمَ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ كَانَ ذَا قُرۡبَىٰ‌ۙ وَلَا نَكۡتُمُ شَهَ<rule class=madda_normal>ـٰ</rule>دَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمِنَ <rule class=ham_wasl>ٱ</rule>لۡأَثِم<rule class=madda_permissible>ِي</rule>نَ ١٠٦',
    106, 7, 2, 125, 99, 50, 'false'
  );
  
  -- Ayah 107 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    776,
    'فَإِنۡ عُثِرَ عَلَىٰۤ أَنَّهُمَا ٱسۡتَحَقَّاۤ إِثۡمࣰا فَـَٔاخَرَانِ یَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِینَ ٱسۡتَحَقَّ عَلَیۡهِمُ ٱلۡأَوۡلَیَـٰنِ فَیُقۡسِمَانِ بِٱللَّهِ لَشَهَـٰدَتُنَاۤ أَحَقُّ مِن شَهَـٰدَتِهِمَا وَمَا ٱعۡتَدَیۡنَاۤ إِنَّاۤ إِذࣰا لَّمِنَ ٱلظَّـٰلِمِینَ',
    'فان عثر على انهما استحقا اثما فاخران يقومان مقامهما من الذين استحق عليهم الاوليان فيقسمان بالله لشهادتنا احق من شهادتهما وما اعتدينا انا اذا لمن الظالمين',
    'فَإِنۡ عُثِرَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمَا <rule class=ham_wasl>ٱ</rule>سۡتَحَقّ<rule class=madda_obligatory_monfasel>َآ</rule> إِثۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َـَٔـاخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَحَقَّ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَوۡلَيَ<rule class=madda_normal>ـٰ</rule>نِ فَيُ<rule class=qalaqah>قۡ</rule>سِمَانِ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ لَشَهَ<rule class=madda_normal>ـٰ</rule>دَتُن<rule class=madda_obligatory_monfasel>َآ</rule> أَحَقُّ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َهَ<rule class=madda_normal>ـٰ</rule>دَتِهِمَا وَمَا <rule class=ham_wasl>ٱ</rule>عۡتَدَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٠٧',
    107, 7, 2, 125, 99, 50, 'false'
  );
  
  -- Ayah 108 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    777,
    'ذَ ٰ⁠لِكَ أَدۡنَىٰۤ أَن یَأۡتُوا۟ بِٱلشَّهَـٰدَةِ عَلَىٰ وَجۡهِهَاۤ أَوۡ یَخَافُوۤا۟ أَن تُرَدَّ أَیۡمَـٰنُۢ بَعۡدَ أَیۡمَـٰنِهِمۡۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱسۡمَعُوا۟ۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ',
    'ذلك ادنى ان ياتوا بالشهادة على وجهها او يخافوا ان ترد ايمان بعد ايمانهم واتقوا الله واسمعوا والله لا يهدي القوم الفاسقين',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ أَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ عَلَىٰ وَ<rule class=qalaqah>جۡ</rule>هِه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ يَخَاف<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرَدَّ أَيۡمَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>نُۢ</rule> <rule class=iqlab>ب</rule>َعۡدَ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>سۡمَعُو<rule class=slnt>اۡ‌ۗ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ١٠٨',
    108, 7, 2, 125, 99, 50, 'false'
  );
  
  -- Ayah 109 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    778,
    '۞ یَوۡمَ یَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَیَقُولُ مَاذَاۤ أُجِبۡتُمۡۖ قَالُوا۟ لَا عِلۡمَ لَنَاۤۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُیُوبِ',
    'يوم يجمع الله الرسل فيقول ماذا اجبتم قالوا لا علم لنا انك انت علام الغيوب',
    '۞يَوۡمَ يَ<rule class=qalaqah>جۡ</rule>مَعُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلَ فَيَقُولُ مَاذ<rule class=madda_obligatory_monfasel>َآ</rule> أُجِ<rule class=qalaqah>بۡ</rule>تُمۡ‌ۖ قَالُو<rule class=slnt>اۡ</rule> لَا عِلۡمَ لَن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ عَلَّ<rule class=madda_normal>ـٰ</rule>مُ <rule class=ham_wasl>ٱ</rule>لۡغُي<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ِ ١٠٩',
    109, 7, 2, 126, 100, 51, 'false'
  );
  
  -- Ayah 110 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    779,
    'إِذۡ قَالَ ٱللَّهُ یَـٰعِیسَى ٱبۡنَ مَرۡیَمَ ٱذۡكُرۡ نِعۡمَتِی عَلَیۡكَ وَعَلَىٰ وَ ٰ⁠لِدَتِكَ إِذۡ أَیَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِی ٱلۡمَهۡدِ وَكَهۡلࣰاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّینِ كَهَیۡـَٔةِ ٱلطَّیۡرِ بِإِذۡنِی فَتَنفُخُ فِیهَا فَتَكُونُ طَیۡرَۢا بِإِذۡنِیۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِیۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِیۖ وَإِذۡ كَفَفۡتُ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَیِّنَـٰتِ فَقَالَ ٱلَّذِینَ كَفَرُوا۟ مِنۡهُمۡ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ',
    'اذ قال الله يا عيسى ابن مريم اذكر نعمتي عليك وعلى والدتك اذ ايدتك بروح القدس تكلم الناس في المهد وكهلا واذ علمتك الكتاب والحكمة والتوراة والانجيل واذ تخلق من الطين كهيئة الطير باذني فتنفخ فيها فتكون طيرا باذني وتبرئ الاكمه والابرص باذني واذ تخرج الموتى باذني واذ كففت بني اسرائيل عنك اذ جئتهم بالبينات فقال الذين كفروا منهم ان هذا الا سحر مبين',
    'إِذۡ قَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=madda_normal>ـٰ</rule>عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ <rule class=ham_wasl>ٱ</rule>ذۡكُرۡ نِعۡمَتِى عَلَيۡكَ وَعَلَىٰ و<rule class=madda_normal>ٰ</rule>لِدَتِكَ إِذۡ أَيَّ<rule class=idgham_mutajanisayn>د</rule>تُّكَ بِرُوحِ <rule class=ham_wasl>ٱ</rule>لۡقُدُسِ تُكَلِّمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ فِى <rule class=ham_wasl>ٱ</rule>لۡمَهۡدِ وَكَهۡل<rule class=idgham_ghunnah>اً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِذۡ عَلَّمۡتُكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلَ‌ۖ وَإِذۡ تَخۡلُقُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طِّينِ كَهَيۡــَٔةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرِ بِإِذۡنِى فَتَ<rule class=ikhafa>نف</rule>ُخُ فِيهَا فَتَكُونُ طَيۡر<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِإِذۡنِى‌ۖ وَتُ<rule class=qalaqah>بۡ</rule>رِئُ <rule class=ham_wasl>ٱ</rule>لۡأَكۡمَهَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>رَصَ بِإِذۡنِى‌ۖ وَإِذۡ تُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ بِإِذۡنِى‌ۖ وَإِذۡ كَفَفۡتُ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ عَ<rule class=ikhafa>نك</rule>َ إِذۡ جِئۡتَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١١٠',
    110, 7, 2, 126, 100, 51, 'false'
  );
  
  -- Ayah 111 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    780,
    'وَإِذۡ أَوۡحَیۡتُ إِلَى ٱلۡحَوَارِیِّـۧنَ أَنۡ ءَامِنُوا۟ بِی وَبِرَسُولِی قَالُوۤا۟ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ',
    'واذ اوحيت الى الحواريين ان امنوا بي وبرسولي قالوا امنا واشهد باننا مسلمون',
    'وَإِذۡ أَوۡحَيۡتُ إِلَى <rule class=ham_wasl>ٱ</rule>لۡحَوَارِيِّـ<rule class=madda_normal>ـۧ</rule>نَ أَنۡ ءَامِنُو<rule class=slnt>اۡ</rule> بِى وَبِرَسُولِى قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا وَ<rule class=ham_wasl>ٱ</rule>شۡهَ<rule class=qalaqah>دۡ</rule> بِأَ<rule class=ghunnah>نّ</rule>َنَا مُسۡلِم<rule class=madda_permissible>ُو</rule>نَ ١١١',
    111, 7, 2, 126, 100, 51, 'false'
  );
  
  -- Ayah 112 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    781,
    'إِذۡ قَالَ ٱلۡحَوَارِیُّونَ یَـٰعِیسَى ٱبۡنَ مَرۡیَمَ هَلۡ یَسۡتَطِیعُ رَبُّكَ أَن یُنَزِّلَ عَلَیۡنَا مَاۤىِٕدَةࣰ مِّنَ ٱلسَّمَاۤءِۖ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِینَ',
    'اذ قال الحواريون يا عيسى ابن مريم هل يستطيع ربك ان ينزل علينا مائدة من السماء قال اتقوا الله ان كنتم مؤمنين',
    'إِذۡ قَالَ <rule class=ham_wasl>ٱ</rule>لۡحَوَارِيُّونَ يَ<rule class=madda_normal>ـٰ</rule>عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ هَلۡ يَسۡتَطِيعُ رَبُّكَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُنَزِّلَ عَلَيۡنَا م<rule class=madda_obligatory_mottasel>َا</rule>ٓئِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۖ قَالَ <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١١٢',
    112, 7, 2, 126, 100, 51, 'false'
  );
  
  -- Ayah 113 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    782,
    'قَالُوا۟ نُرِیدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَىِٕنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَیۡهَا مِنَ ٱلشَّـٰهِدِینَ',
    'قالوا نريد ان ناكل منها وتطمئن قلوبنا ونعلم ان قد صدقتنا ونكون عليها من الشاهدين',
    'قَالُو<rule class=slnt>اۡ</rule> نُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّأۡكُلَ مِنۡهَا وَتَ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>َ قُلُوبُنَا وَنَعۡلَمَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> صَدَ<rule class=qalaqah>قۡ</rule>تَنَا وَنَكُونَ عَلَيۡهَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>هِد<rule class=madda_permissible>ِي</rule>نَ ١١٣',
    113, 7, 2, 126, 100, 51, 'false'
  );
  
  -- Ayah 114 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    783,
    'قَالَ عِیسَى ٱبۡنُ مَرۡیَمَ ٱللَّهُمَّ رَبَّنَاۤ أَنزِلۡ عَلَیۡنَا مَاۤىِٕدَةࣰ مِّنَ ٱلسَّمَاۤءِ تَكُونُ لَنَا عِیدࣰا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَایَةࣰ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ',
    'قال عيسى ابن مريم اللهم ربنا انزل علينا مائدة من السماء تكون لنا عيدا لاولنا واخرنا واية منك وارزقنا وانت خير الرازقين',
    'قَالَ عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّهُ<rule class=ghunnah>مّ</rule>َ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>ِلۡ عَلَيۡنَا م<rule class=madda_obligatory_mottasel>َا</rule>ٓئِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ تَكُونُ لَنَا عِي<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>َ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>رۡزُ<rule class=qalaqah>قۡ</rule>نَا وَأَ<rule class=ikhafa>نت</rule>َ خَيۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>زِق<rule class=madda_permissible>ِي</rule>نَ ١١٤',
    114, 7, 2, 127, 100, 51, 'false'
  );
  
  -- Ayah 115 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    784,
    'قَالَ ٱللَّهُ إِنِّی مُنَزِّلُهَا عَلَیۡكُمۡۖ فَمَن یَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّیۤ أُعَذِّبُهُۥ عَذَابࣰا لَّاۤ أُعَذِّبُهُۥۤ أَحَدࣰا مِّنَ ٱلۡعَـٰلَمِینَ',
    'قال الله اني منزلها عليكم فمن يكفر بعد منكم فاني اعذبه عذابا لا اعذبه احدا من العالمين',
    'قَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِ<rule class=ghunnah>نّ</rule>ِى مُنَزِّلُهَا عَلَيۡكُمۡ‌ۖ فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرۡ بَعۡدُ مِ<rule class=ikhafa>نك</rule>ُمۡ فَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُعَذِّبُهُ<rule class=madda_normal>ۥ</rule> عَذَا<rule class=idgham_wo_ghunnah>بًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أُعَذِّبُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَحَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١١٥',
    115, 7, 2, 127, 100, 51, 'false'
  );
  
  -- Ayah 116 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    785,
    'وَإِذۡ قَالَ ٱللَّهُ یَـٰعِیسَى ٱبۡنَ مَرۡیَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِی وَأُمِّیَ إِلَـٰهَیۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَـٰنَكَ مَا یَكُونُ لِیۤ أَنۡ أَقُولَ مَا لَیۡسَ لِی بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِی نَفۡسِی وَلَاۤ أَعۡلَمُ مَا فِی نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُیُوبِ',
    'واذ قال الله يا عيسى ابن مريم اانت قلت للناس اتخذوني وامي الهين من دون الله قال سبحانك ما يكون لي ان اقول ما ليس لي بحق ان كنت قلته فقد علمته تعلم ما في نفسي ولا اعلم ما في نفسك انك انت علام الغيوب',
    'وَإِذۡ قَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=madda_normal>ـٰ</rule>عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ ءَأَ<rule class=ikhafa>نت</rule>َ قُلۡتَ لِل<rule class=ghunnah>نّ</rule>َاسِ <rule class=ham_wasl>ٱ</rule>تَّخِذُونِى وَأُ<rule class=ghunnah>مّ</rule>ِىَ إِلَ<rule class=madda_normal>ـٰ</rule>هَيۡنِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ قَالَ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ مَا يَكُونُ ل<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡ أَقُولَ مَا لَيۡسَ لِى بِحَقٍّ‌ۚ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُ قُلۡتُهُ<rule class=madda_normal>ۥ</rule> فَقَ<rule class=qalaqah>دۡ</rule> عَلِمۡتَهُ<rule class=madda_normal>ۥ</rule>‌ۚ تَعۡلَمُ مَا فِى نَفۡسِى وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡلَمُ مَا فِى نَفۡسِكَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ عَلَّ<rule class=madda_normal>ـٰ</rule>مُ <rule class=ham_wasl>ٱ</rule>لۡغُي<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ِ ١١٦',
    116, 7, 2, 127, 101, 51, 'false'
  );
  
  -- Ayah 117 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    786,
    'مَا قُلۡتُ لَهُمۡ إِلَّا مَاۤ أَمَرۡتَنِی بِهِۦۤ أَنِ ٱعۡبُدُوا۟ ٱللَّهَ رَبِّی وَرَبَّكُمۡۚ وَكُنتُ عَلَیۡهِمۡ شَهِیدࣰا مَّا دُمۡتُ فِیهِمۡۖ فَلَمَّا تَوَفَّیۡتَنِی كُنتَ أَنتَ ٱلرَّقِیبَ عَلَیۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ',
    'ما قلت لهم الا ما امرتني به ان اعبدوا الله ربي وربكم وكنت عليهم شهيدا ما دمت فيهم فلما توفيتني كنت انت الرقيب عليهم وانت على كل شيء شهيد',
    'مَا قُلۡتُ لَهُمۡ إِلَّا م<rule class=madda_obligatory_monfasel>َآ</rule> أَمَرۡتَنِى بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَنِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ رَبِّى وَرَبَّكُمۡ‌ۚ وَكُ<rule class=ikhafa>نت</rule>ُ عَلَيۡهِمۡ شَهِي<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>َّا دُمۡتُ فِيهِمۡ‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا تَوَفَّيۡتَنِى كُ<rule class=ikhafa>نت</rule>َ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّقِيبَ عَلَيۡهِمۡ‌ۚ وَأَ<rule class=ikhafa>نت</rule>َ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ش</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١١٧',
    117, 7, 2, 127, 101, 51, 'false'
  );
  
  -- Ayah 118 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    787,
    'إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'ان تعذبهم فانهم عبادك وان تغفر لهم فانك انت العزيز الحكيم',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُعَذِّ<rule class=qalaqah>بۡ</rule>هُمۡ فَإِ<rule class=ghunnah>نّ</rule>َهُمۡ عِبَادُكَ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َغۡفِرۡ لَهُمۡ فَإِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ١١٨',
    118, 7, 2, 127, 101, 51, 'false'
  );
  
  -- Ayah 119 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    788,
    'قَالَ ٱللَّهُ هَـٰذَا یَوۡمُ یَنفَعُ ٱلصَّـٰدِقِینَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ رَّضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'قال الله هذا يوم ينفع الصادقين صدقهم لهم جنات تجري من تحتها الانهار خالدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك الفوز العظيم',
    'قَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ هَ<rule class=madda_normal>ـٰ</rule>ذَا يَوۡمُ يَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِقِينَ صِ<rule class=qalaqah>دۡ</rule>قُهُمۡ‌ۚ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=idgham_wo_ghunnah>دًا‌ۚ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّضِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَنۡهُمۡ وَرَضُو<rule class=slnt>اۡ</rule> عَنۡهُ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ١١٩',
    119, 7, 2, 127, 101, 51, 'false'
  );
  
  -- Ayah 120 Surah Al-Maaida
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    5,
    789,
    'لِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا فِیهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرُۢ',
    'لله ملك السماوات والارض وما فيهن وهو على كل شيء قدير',
    'لِلَّهِ مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا فِيهِ<rule class=ghunnah>نّ</rule>َ‌ۚ وَهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رُۢ ١٢٠',
    120, 7, 2, 127, 101, 51, 'false'
  );
  

-- Surah Al-Anaam
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (6, 'سُورَةُ الأَنۡعَامِ', 'Al-Anaam', 'The Cattle', 'Meccan', 165);

  -- Ayah 1 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    790,
    'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡ یَعۡدِلُونَ',
    'الحمد لله الذي خلق السماوات والارض وجعل الظلمات والنور ثم الذين كفروا بربهم يعدلون',
    'ٱلۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَجَعَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورَ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِرَبِّهِمۡ يَعۡدِل<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 7, 2, 128, 102, 51, 'false'
  );
  
  -- Ayah 2 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    791,
    'هُوَ ٱلَّذِی خَلَقَكُم مِّن طِینࣲ ثُمَّ قَضَىٰۤ أَجَلࣰاۖ وَأَجَلࣱ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ',
    'هو الذي خلقكم من طين ثم قضى اجلا واجل مسمى عنده ثم انتم تمترون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>ِي<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ قَضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَل<rule class=idgham_ghunnah>اً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأَجَ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَ<rule class=ghunnah>مّ</rule>ًى عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule>‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=ikhafa>نت</rule>ُمۡ تَمۡتَر<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 7, 2, 128, 102, 51, 'false'
  );
  
  -- Ayah 3 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    792,
    'وَهُوَ ٱللَّهُ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَفِی ٱلۡأَرۡضِ یَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَیَعۡلَمُ مَا تَكۡسِبُونَ',
    'وهو الله في السماوات وفي الارض يعلم سركم وجهركم ويعلم ما تكسبون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَفِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ يَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَيَعۡلَمُ مَا تَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 7, 2, 128, 102, 51, 'false'
  );
  
  -- Ayah 4 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    793,
    'وَمَا تَأۡتِیهِم مِّنۡ ءَایَةࣲ مِّنۡ ءَایَـٰتِ رَبِّهِمۡ إِلَّا كَانُوا۟ عَنۡهَا مُعۡرِضِینَ',
    'وما تاتيهم من اية من ايات ربهم الا كانوا عنها معرضين',
    'وَمَا تَأۡتِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ ءَايَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ إِلَّا كَانُو<rule class=slnt>اۡ</rule> عَنۡهَا مُعۡرِض<rule class=madda_permissible>ِي</rule>نَ ٤',
    4, 7, 2, 128, 102, 51, 'false'
  );
  
  -- Ayah 5 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    794,
    'فَقَدۡ كَذَّبُوا۟ بِٱلۡحَقِّ لَمَّا جَاۤءَهُمۡ فَسَوۡفَ یَأۡتِیهِمۡ أَنۢبَـٰۤؤُا۟ مَا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'فقد كذبوا بالحق لما جاءهم فسوف ياتيهم انباء ما كانوا به يستهزئون',
    'فَقَ<rule class=qalaqah>دۡ</rule> كَذَّبُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ‌ۖ فَسَوۡفَ يَأۡتِيهِمۡ أَ<rule class=iqlab>نۢب</rule>َ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> مَا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 7, 2, 128, 102, 51, 'false'
  );
  
  -- Ayah 6 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    795,
    'أَلَمۡ یَرَوۡا۟ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنࣲ مَّكَّنَّـٰهُمۡ فِی ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَاۤءَ عَلَیۡهِم مِّدۡرَارࣰا وَجَعَلۡنَا ٱلۡأَنۡهَـٰرَ تَجۡرِی مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَـٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِینَ',
    'الم يروا كم اهلكنا من قبلهم من قرن مكناهم في الارض ما لم نمكن لكم وارسلنا السماء عليهم مدرارا وجعلنا الانهار تجري من تحتهم فاهلكناهم بذنوبهم وانشانا من بعدهم قرنا اخرين',
    'أَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> كَمۡ أَهۡلَكۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡ<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>َّكَّ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مَا لَمۡ نُمَكّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَأَرۡسَلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=qalaqah>دۡ</rule>رَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلۡنَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رَ تَ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهِمۡ فَأَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذُنُوبِهِمۡ وَأَ<rule class=ikhafa>نش</rule>َأۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ قَرۡنًا ءَاخَر<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 7, 2, 128, 102, 51, 'false'
  );
  
  -- Ayah 7 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    796,
    'وَلَوۡ نَزَّلۡنَا عَلَیۡكَ كِتَـٰبࣰا فِی قِرۡطَاسࣲ فَلَمَسُوهُ بِأَیۡدِیهِمۡ لَقَالَ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ',
    'ولو نزلنا عليك كتابا في قرطاس فلمسوه بايديهم لقال الذين كفروا ان هذا الا سحر مبين',
    'وَلَوۡ نَزَّلۡنَا عَلَيۡكَ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>ِى قِرۡطَا<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ف</rule>َلَمَسُوهُ بِأَيۡدِيهِمۡ لَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٧',
    7, 7, 2, 128, 102, 51, 'false'
  );
  
  -- Ayah 8 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    797,
    'وَقَالُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ مَلَكࣱۖ وَلَوۡ أَنزَلۡنَا مَلَكࣰا لَّقُضِیَ ٱلۡأَمۡرُ ثُمَّ لَا یُنظَرُونَ',
    'وقالوا لولا انزل عليه ملك ولو انزلنا ملكا لقضي الامر ثم لا ينظرون',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡهِ مَلَ<rule class=idgham_ghunnah>كٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ أَ<rule class=ikhafa>نز</rule>َلۡنَا مَلَ<rule class=idgham_wo_ghunnah>كًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّقُضِىَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ ثُ<rule class=ghunnah>مّ</rule>َ لَا يُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 7, 2, 128, 102, 51, 'false'
  );
  
  -- Ayah 9 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    798,
    'وَلَوۡ جَعَلۡنَـٰهُ مَلَكࣰا لَّجَعَلۡنَـٰهُ رَجُلࣰا وَلَلَبَسۡنَا عَلَیۡهِم مَّا یَلۡبِسُونَ',
    'ولو جعلناه ملكا لجعلناه رجلا وللبسنا عليهم ما يلبسون',
    'وَلَوۡ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ مَلَ<rule class=idgham_wo_ghunnah>كًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ رَجُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َلَلَبَسۡنَا عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا يَلۡبِس<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 7, 2, 129, 102, 51, 'false'
  );
  
  -- Ayah 10 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    799,
    'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلࣲ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِینَ سَخِرُوا۟ مِنۡهُم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون',
    'وَلَقَدِ <rule class=ham_wasl>ٱ</rule>سۡتُهۡزِئَ بِرُسُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ فَحَاقَ بِ<rule class=ham_wasl>ٱ</rule>لَّذِينَ سَخِرُو<rule class=slnt>اۡ</rule> مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 7, 2, 129, 102, 51, 'false'
  );
  
  -- Ayah 11 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    800,
    'قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ ثُمَّ ٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُكَذِّبِینَ',
    'قل سيروا في الارض ثم انظروا كيف كان عاقبة المكذبين',
    'قُلۡ سِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُكَذِّب<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 7, 2, 129, 103, 51, 'false'
  );
  
  -- Ayah 12 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    801,
    'قُل لِّمَن مَّا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَیَجۡمَعَنَّكُمۡ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ لَا رَیۡبَ فِیهِۚ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ فَهُمۡ لَا یُؤۡمِنُونَ',
    'قل لمن ما في السماوات والارض قل لله كتب على نفسه الرحمة ليجمعنكم الى يوم القيامة لا ريب فيه الذين خسروا انفسهم فهم لا يؤمنون',
    'قُل لِّم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ قُل لِّلَّهِ‌ۚ كَتَبَ عَلَىٰ نَفۡسِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَةَ‌ۚ لَيَ<rule class=qalaqah>جۡ</rule>مَعَ<rule class=ghunnah>نّ</rule>َكُمۡ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ لَا رَيۡبَ فِيهِ‌ۚ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَسِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ فَهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 7, 2, 129, 103, 51, 'false'
  );
  
  -- Ayah 13 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    802,
    '۞ وَلَهُۥ مَا سَكَنَ فِی ٱلَّیۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'وله ما سكن في الليل والنهار وهو السميع العليم',
    '۞وَلَهُ<rule class=madda_normal>ۥ</rule> مَا سَكَنَ فِى <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ١٣',
    13, 7, 2, 129, 103, 52, 'false'
  );
  
  -- Ayah 14 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    803,
    'قُلۡ أَغَیۡرَ ٱللَّهِ أَتَّخِذُ وَلِیࣰّا فَاطِرِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَهُوَ یُطۡعِمُ وَلَا یُطۡعَمُۗ قُلۡ إِنِّیۤ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِینَ',
    'قل اغير الله اتخذ وليا فاطر السماوات والارض وهو يطعم ولا يطعم قل اني امرت ان اكون اول من اسلم ولا تكونن من المشركين',
    'قُلۡ أَغَيۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ أَتَّخِذُ وَلِي<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ف</rule>َاطِرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَهُوَ يُ<rule class=qalaqah>طۡ</rule>عِمُ وَلَا يُ<rule class=qalaqah>طۡ</rule>عَمُ‌ۗ قُلۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَ‌ۖ وَلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١٤',
    14, 7, 2, 129, 103, 52, 'false'
  );
  
  -- Ayah 15 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    804,
    'قُلۡ إِنِّیۤ أَخَافُ إِنۡ عَصَیۡتُ رَبِّی عَذَابَ یَوۡمٍ عَظِیمࣲ',
    'قل اني اخاف ان عصيت ربي عذاب يوم عظيم',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ إِنۡ عَصَيۡتُ رَبِّى عَذَابَ يَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ١٥',
    15, 7, 2, 129, 103, 52, 'false'
  );
  
  -- Ayah 16 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    805,
    'مَّن یُصۡرَفۡ عَنۡهُ یَوۡمَىِٕذࣲ فَقَدۡ رَحِمَهُۥۚ وَذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡمُبِینُ',
    'من يصرف عنه يومئذ فقد رحمه وذلك الفوز المبين',
    'مّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُصۡرَفۡ عَنۡهُ يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ف</rule>َقَ<rule class=qalaqah>دۡ</rule> رَحِمَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ١٦',
    16, 7, 2, 129, 103, 52, 'false'
  );
  
  -- Ayah 17 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    806,
    'وَإِن یَمۡسَسۡكَ ٱللَّهُ بِضُرࣲّ فَلَا كَاشِفَ لَهُۥۤ إِلَّا هُوَۖ وَإِن یَمۡسَسۡكَ بِخَیۡرࣲ فَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'وان يمسسك الله بضر فلا كاشف له الا هو وان يمسسك بخير فهو على كل شيء قدير',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡسَسۡكَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِضُ<rule class=ikhafa>رٍّ</rule> <rule class=ikhafa>ف</rule>َلَا كَاشِفَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا هُوَ‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡسَسۡكَ بِخَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١٧',
    17, 7, 2, 129, 103, 52, 'false'
  );
  
  -- Ayah 18 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    807,
    'وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡخَبِیرُ',
    'وهو القاهر فوق عباده وهو الحكيم الخبير',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡقَاهِرُ فَوۡقَ عِبَادِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡحَكِيمُ <rule class=ham_wasl>ٱ</rule>لۡخَب<rule class=madda_permissible>ِي</rule>رُ ١٨',
    18, 7, 2, 129, 103, 52, 'false'
  );
  
  -- Ayah 19 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    808,
    'قُلۡ أَیُّ شَیۡءٍ أَكۡبَرُ شَهَـٰدَةࣰۖ قُلِ ٱللَّهُۖ شَهِیدُۢ بَیۡنِی وَبَیۡنَكُمۡۚ وَأُوحِیَ إِلَیَّ هَـٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَىِٕنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّاۤ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَـٰهࣱ وَ ٰ⁠حِدࣱ وَإِنَّنِی بَرِیۤءࣱ مِّمَّا تُشۡرِكُونَ',
    'قل اي شيء اكبر شهادة قل الله شهيد بيني وبينكم واوحي الي هذا القران لانذركم به ومن بلغ ائنكم لتشهدون ان مع الله الهة اخرى قل لا اشهد قل انما هو اله واحد وانني بريء مما تشركون',
    'قُلۡ أَىُّ شَىۡءٍ أَكۡبَرُ شَهَ<rule class=madda_normal>ـٰ</rule>دَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ق</rule>ُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ شَهِي<rule class=iqlab>دُۢ</rule> <rule class=iqlab>ب</rule>َيۡنِى وَبَيۡنَكُمۡ‌ۚ وَأُوحِىَ إِلَىَّ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانُ لِأُ<rule class=ikhafa>نذ</rule>ِرَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> وَم<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>َلَغَ‌ۚ أَئِ<rule class=ghunnah>نّ</rule>َكُمۡ لَتَشۡهَدُونَ أَ<rule class=ghunnah>نّ</rule>َ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ ءَالِهَةً أُخۡرَىٰ‌ۚ قُل لّ<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡهَدُ‌ۚ قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا هُوَ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َنِى بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 7, 2, 130, 103, 52, 'false'
  );
  
  -- Ayah 20 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    809,
    'ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَعۡرِفُونَهُۥ كَمَا یَعۡرِفُونَ أَبۡنَاۤءَهُمُۘ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ فَهُمۡ لَا یُؤۡمِنُونَ',
    'الذين اتيناهم الكتاب يعرفونه كما يعرفون ابناءهم الذين خسروا انفسهم فهم لا يؤمنون',
    'ٱلَّذِينَ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يَعۡرِفُونَهُ<rule class=madda_normal>ۥ</rule> كَمَا يَعۡرِفُونَ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ‌ۘ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَسِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ فَهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 7, 2, 130, 103, 52, 'false'
  );
  
  -- Ayah 21 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    810,
    'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔایَـٰتِهِۦۤۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ',
    'ومن اظلم ممن افترى على الله كذبا او كذب باياته انه لا يفلح الظالمون',
    'وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 7, 2, 130, 104, 52, 'false'
  );
  
  -- Ayah 22 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    811,
    'وَیَوۡمَ نَحۡشُرُهُمۡ جَمِیعࣰا ثُمَّ نَقُولُ لِلَّذِینَ أَشۡرَكُوۤا۟ أَیۡنَ شُرَكَاۤؤُكُمُ ٱلَّذِینَ كُنتُمۡ تَزۡعُمُونَ',
    'ويوم نحشرهم جميعا ثم نقول للذين اشركوا اين شركاؤكم الذين كنتم تزعمون',
    'وَيَوۡمَ نَحۡشُرُهُمۡ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ نَقُولُ لِلَّذِينَ أَشۡرَك<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡنَ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كُ<rule class=ikhafa>نت</rule>ُمۡ تَزۡعُم<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 7, 2, 130, 104, 52, 'false'
  );
  
  -- Ayah 23 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    812,
    'ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّاۤ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِینَ',
    'ثم لم تكن فتنتهم الا ان قالوا والله ربنا ما كنا مشركين',
    'ثُ<rule class=ghunnah>مّ</rule>َ لَمۡ تَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِتۡنَتُهُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهِ رَبِّنَا مَا كُ<rule class=ghunnah>نّ</rule>َا مُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٢٣',
    23, 7, 2, 130, 104, 52, 'false'
  );
  
  -- Ayah 24 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    813,
    'ٱنظُرۡ كَیۡفَ كَذَبُوا۟ عَلَىٰۤ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ',
    'انظر كيف كذبوا على انفسهم وضل عنهم ما كانوا يفترون',
    'ٱ<rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَذَبُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۚ وَضَلَّ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 7, 2, 130, 104, 52, 'false'
  );
  
  -- Ayah 25 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    814,
    'وَمِنۡهُم مَّن یَسۡتَمِعُ إِلَیۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن یَفۡقَهُوهُ وَفِیۤ ءَاذَانِهِمۡ وَقۡرࣰاۚ وَإِن یَرَوۡا۟ كُلَّ ءَایَةࣲ لَّا یُؤۡمِنُوا۟ بِهَاۖ حَتَّىٰۤ إِذَا جَاۤءُوكَ یُجَـٰدِلُونَكَ یَقُولُ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ',
    'ومنهم من يستمع اليك وجعلنا على قلوبهم اكنة ان يفقهوه وفي اذانهم وقرا وان يروا كل اية لا يؤمنوا بها حتى اذا جاءوك يجادلونك يقول الذين كفروا ان هذا الا اساطير الاولين',
    'وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَمِعُ إِلَيۡكَ‌ۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِ<rule class=ghunnah>نّ</rule>َةً أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡقَهُوهُ وَف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاذَانِهِمۡ وَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َرَوۡ<rule class=slnt>اۡ</rule> كُلَّ ءَايَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِنُو<rule class=slnt>اۡ</rule> بِهَا‌ۚ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوكَ يُجَ<rule class=madda_normal>ـٰ</rule>دِلُونَكَ يَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 7, 2, 130, 104, 52, 'false'
  );
  
  -- Ayah 26 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    815,
    'وَهُمۡ یَنۡهَوۡنَ عَنۡهُ وَیَنۡـَٔوۡنَ عَنۡهُۖ وَإِن یُهۡلِكُونَ إِلَّاۤ أَنفُسَهُمۡ وَمَا یَشۡعُرُونَ',
    'وهم ينهون عنه ويناون عنه وان يهلكون الا انفسهم وما يشعرون',
    'وَهُمۡ يَنۡهَوۡنَ عَنۡهُ وَيَنۡــَٔوۡنَ عَنۡهُ‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُهۡلِكُونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَمَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 7, 2, 130, 104, 52, 'false'
  );
  
  -- Ayah 27 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    816,
    'وَلَوۡ تَرَىٰۤ إِذۡ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ یَـٰلَیۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔایَـٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ',
    'ولو ترى اذ وقفوا على النار فقالوا يا ليتنا نرد ولا نكذب بايات ربنا ونكون من المؤمنين',
    'وَلَوۡ تَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذۡ وُقِفُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ فَقَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّنَا وَنَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 7, 2, 130, 104, 52, 'false'
  );
  
  -- Ayah 28 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    817,
    'بَلۡ بَدَا لَهُم مَّا كَانُوا۟ یُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنۡهُ وَإِنَّهُمۡ لَكَـٰذِبُونَ',
    'بل بدا لهم ما كانوا يخفون من قبل ولو ردوا لعادوا لما نهوا عنه وانهم لكاذبون',
    'بَلۡ بَدَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يُخۡفُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ وَلَوۡ رُدُّو<rule class=slnt>اۡ</rule> لَعَادُو<rule class=slnt>اۡ</rule> لِمَا نُهُو<rule class=slnt>اۡ</rule> عَنۡهُ وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ لَكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 7, 2, 131, 104, 52, 'false'
  );
  
  -- Ayah 29 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    818,
    'وَقَالُوۤا۟ إِنۡ هِیَ إِلَّا حَیَاتُنَا ٱلدُّنۡیَا وَمَا نَحۡنُ بِمَبۡعُوثِینَ',
    'وقالوا ان هي الا حياتنا الدنيا وما نحن بمبعوثين',
    'وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ هِىَ إِلَّا حَيَاتُنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَمَا نَحۡنُ بِمَ<rule class=qalaqah>بۡ</rule>عُوث<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 7, 2, 131, 104, 52, 'false'
  );
  
  -- Ayah 30 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    819,
    'وَلَوۡ تَرَىٰۤ إِذۡ وُقِفُوا۟ عَلَىٰ رَبِّهِمۡۚ قَالَ أَلَیۡسَ هَـٰذَا بِٱلۡحَقِّۚ قَالُوا۟ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ',
    'ولو ترى اذ وقفوا على ربهم قال اليس هذا بالحق قالوا بلى وربنا قال فذوقوا العذاب بما كنتم تكفرون',
    'وَلَوۡ تَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذۡ وُقِفُو<rule class=slnt>اۡ</rule> عَلَىٰ رَبِّهِمۡ‌ۚ قَالَ أَلَيۡسَ هَ<rule class=madda_normal>ـٰ</rule>ذَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ قَالُو<rule class=slnt>اۡ</rule> بَلَىٰ وَرَبِّنَا‌ۚ قَالَ فَذُوقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 7, 2, 131, 104, 52, 'false'
  );
  
  -- Ayah 31 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    820,
    'قَدۡ خَسِرَ ٱلَّذِینَ كَذَّبُوا۟ بِلِقَاۤءِ ٱللَّهِۖ حَتَّىٰۤ إِذَا جَاۤءَتۡهُمُ ٱلسَّاعَةُ بَغۡتَةࣰ قَالُوا۟ یَـٰحَسۡرَتَنَا عَلَىٰ مَا فَرَّطۡنَا فِیهَا وَهُمۡ یَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡۚ أَلَا سَاۤءَ مَا یَزِرُونَ',
    'قد خسر الذين كذبوا بلقاء الله حتى اذا جاءتهم الساعة بغتة قالوا يا حسرتنا على ما فرطنا فيها وهم يحملون اوزارهم على ظهورهم الا ساء ما يزرون',
    'قَ<rule class=qalaqah>دۡ</rule> خَسِرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ بَغۡتَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>حَسۡرَتَنَا عَلَىٰ مَا فَرَّ<rule class=qalaqah>طۡ</rule>نَا فِيهَا وَهُمۡ يَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡ‌ۚ أَلَا س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا يَزِر<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 7, 2, 131, 105, 52, 'false'
  );
  
  -- Ayah 32 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    821,
    'وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا لَعِبࣱ وَلَهۡوࣱۖ وَلَلدَّارُ ٱلۡـَٔاخِرَةُ خَیۡرࣱ لِّلَّذِینَ یَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ',
    'وما الحياة الدنيا الا لعب ولهو وللدار الاخرة خير للذين يتقون افلا تعقلون',
    'وَمَا <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡي<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا لَعِ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَهۡ<rule class=idgham_ghunnah>وٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَلدَّارُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةُ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ يَتَّقُونَ‌ۗ أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 7, 2, 131, 105, 52, 'false'
  );
  
  -- Ayah 33 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    822,
    'قَدۡ نَعۡلَمُ إِنَّهُۥ لَیَحۡزُنُكَ ٱلَّذِی یَقُولُونَۖ فَإِنَّهُمۡ لَا یُكَذِّبُونَكَ وَلَـٰكِنَّ ٱلظَّـٰلِمِینَ بِـَٔایَـٰتِ ٱللَّهِ یَجۡحَدُونَ',
    'قد نعلم انه ليحزنك الذي يقولون فانهم لا يكذبونك ولكن الظالمين بايات الله يجحدون',
    'قَ<rule class=qalaqah>دۡ</rule> نَعۡلَمُ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَيَحۡزُنُكَ <rule class=ham_wasl>ٱ</rule>لَّذِى يَقُولُونَ‌ۖ فَإِ<rule class=ghunnah>نّ</rule>َهُمۡ لَا يُكَذِّبُونَكَ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ يَ<rule class=qalaqah>جۡ</rule>حَد<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 7, 2, 131, 105, 52, 'false'
  );
  
  -- Ayah 34 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    823,
    'وَلَقَدۡ كُذِّبَتۡ رُسُلࣱ مِّن قَبۡلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰۤ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَـٰتِ ٱللَّهِۚ وَلَقَدۡ جَاۤءَكَ مِن نَّبَإِی۟ ٱلۡمُرۡسَلِینَ',
    'ولقد كذبت رسل من قبلك فصبروا على ما كذبوا واوذوا حتى اتاهم نصرنا ولا مبدل لكلمات الله ولقد جاءك من نبا المرسلين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> كُذِّبَتۡ رُسُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ فَصَبَرُو<rule class=slnt>اۡ</rule> عَلَىٰ مَا كُذِّبُو<rule class=slnt>اۡ</rule> وَأُوذُو<rule class=slnt>اۡ</rule> حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَتَ<rule class=madda_normal>ـٰ</rule>هُمۡ نَصۡرُنَا‌ۚ وَلَا مُبَدِّلَ لِكَلِمَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّبَإِ<rule class=slnt>ىۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 7, 2, 131, 105, 52, 'false'
  );
  
  -- Ayah 35 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    824,
    'وَإِن كَانَ كَبُرَ عَلَیۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِیَ نَفَقࣰا فِی ٱلۡأَرۡضِ أَوۡ سُلَّمࣰا فِی ٱلسَّمَاۤءِ فَتَأۡتِیَهُم بِـَٔایَةࣲۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَـٰهِلِینَ',
    'وان كان كبر عليك اعراضهم فان استطعت ان تبتغي نفقا في الارض او سلما في السماء فتاتيهم باية ولو شاء الله لجمعهم على الهدى فلا تكونن من الجاهلين',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ كَبُرَ عَلَيۡكَ إِعۡرَاضُهُمۡ فَإِنِ <rule class=ham_wasl>ٱ</rule>سۡتَطَعۡتَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>بۡ</rule>تَغِىَ نَفَ<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَوۡ سُلَّ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَتَأۡتِيَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=idgham_ghunnah>ةٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَجَمَعَهُمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ‌ۚ فَلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِل<rule class=madda_permissible>ِي</rule>نَ ٣٥',
    35, 7, 2, 131, 105, 52, 'false'
  );
  
  -- Ayah 36 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    825,
    '۞ إِنَّمَا یَسۡتَجِیبُ ٱلَّذِینَ یَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ یَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَیۡهِ یُرۡجَعُونَ',
    'انما يستجيب الذين يسمعون والموتى يبعثهم الله ثم اليه يرجعون',
    '۞إِ<rule class=ghunnah>نّ</rule>َمَا يَسۡتَجِيبُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَسۡمَعُونَ‌ۘ وَ<rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ يَ<rule class=qalaqah>بۡ</rule>عَثُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ ثُ<rule class=ghunnah>مّ</rule>َ إِلَيۡهِ يُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 7, 2, 132, 105, 53, 'false'
  );
  
  -- Ayah 37 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    826,
    'وَقَالُوا۟ لَوۡلَا نُزِّلَ عَلَیۡهِ ءَایَةࣱ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰۤ أَن یُنَزِّلَ ءَایَةࣰ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'وقالوا لولا نزل عليه اية من ربه قل ان الله قادر على ان ينزل اية ولكن اكثرهم لا يعلمون',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَوۡلَا نُزِّلَ عَلَيۡهِ ءَايَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule>‌ۚ قُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَادِرٌ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُنَزِّلَ ءَايَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 7, 2, 132, 105, 53, 'false'
  );
  
  -- Ayah 38 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    827,
    'وَمَا مِن دَاۤبَّةࣲ فِی ٱلۡأَرۡضِ وَلَا طَـٰۤىِٕرࣲ یَطِیرُ بِجَنَاحَیۡهِ إِلَّاۤ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِی ٱلۡكِتَـٰبِ مِن شَیۡءࣲۚ ثُمَّ إِلَىٰ رَبِّهِمۡ یُحۡشَرُونَ',
    'وما من دابة في الارض ولا طائر يطير بجناحيه الا امم امثالكم ما فرطنا في الكتاب من شيء ثم الى ربهم يحشرون',
    'وَمَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا طَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>ي</rule>َطِيرُ بِجَنَاحَيۡهِ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أُمَمٌ أَمۡثَالُك<rule class=idgham_shafawi>ُم‌ۚ</rule> <rule class=idgham_shafawi>م</rule>َّا فَرَّ<rule class=qalaqah>طۡ</rule>نَا فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ إِلَىٰ رَبِّهِمۡ يُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 7, 2, 132, 105, 53, 'false'
  );
  
  -- Ayah 39 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    828,
    'وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا صُمࣱّ وَبُكۡمࣱ فِی ٱلظُّلُمَـٰتِۗ مَن یَشَإِ ٱللَّهُ یُضۡلِلۡهُ وَمَن یَشَأۡ یَجۡعَلۡهُ عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'والذين كذبوا باياتنا صم وبكم في الظلمات من يشا الله يضلله ومن يشا يجعله على صراط مستقيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا صُ<rule class=idgham_ghunnah>مٌّ</rule> <rule class=idgham_ghunnah>و</rule>َبُكۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ‌ۗ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َشَإِ <rule class=ham_wasl>ٱ</rule>للَّهُ يُضۡلِلۡهُ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َشَأۡ يَ<rule class=qalaqah>جۡ</rule>عَلۡهُ عَلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٣٩',
    39, 7, 2, 132, 105, 53, 'false'
  );
  
  -- Ayah 40 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    829,
    'قُلۡ أَرَءَیۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ أَوۡ أَتَتۡكُمُ ٱلسَّاعَةُ أَغَیۡرَ ٱللَّهِ تَدۡعُونَ إِن كُنتُمۡ صَـٰدِقِینَ',
    'قل ارايتكم ان اتاكم عذاب الله او اتتكم الساعة اغير الله تدعون ان كنتم صادقين',
    'قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَ<rule class=madda_normal>ـٰ</rule>كُمۡ عَذَابُ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡ أَتَتۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ أَغَيۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ تَ<rule class=qalaqah>دۡ</rule>عُونَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 7, 2, 132, 105, 53, 'false'
  );
  
  -- Ayah 41 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    830,
    'بَلۡ إِیَّاهُ تَدۡعُونَ فَیَكۡشِفُ مَا تَدۡعُونَ إِلَیۡهِ إِن شَاۤءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ',
    'بل اياه تدعون فيكشف ما تدعون اليه ان شاء وتنسون ما تشركون',
    'بَلۡ إِيَّاهُ تَ<rule class=qalaqah>دۡ</rule>عُونَ فَيَكۡشِفُ مَا تَ<rule class=qalaqah>دۡ</rule>عُونَ إِلَيۡهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَتَ<rule class=ikhafa>نس</rule>َوۡنَ مَا تُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 7, 2, 132, 105, 53, 'false'
  );
  
  -- Ayah 42 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    831,
    'وَلَقَدۡ أَرۡسَلۡنَاۤ إِلَىٰۤ أُمَمࣲ مِّن قَبۡلِكَ فَأَخَذۡنَـٰهُم بِٱلۡبَأۡسَاۤءِ وَٱلضَّرَّاۤءِ لَعَلَّهُمۡ یَتَضَرَّعُونَ',
    'ولقد ارسلنا الى امم من قبلك فاخذناهم بالباساء والضراء لعلهم يتضرعون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُمَ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ فَأَخَذۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَأۡس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ لَعَلَّهُمۡ يَتَضَرَّع<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 7, 2, 132, 106, 53, 'false'
  );
  
  -- Ayah 43 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    832,
    'فَلَوۡلَاۤ إِذۡ جَاۤءَهُم بَأۡسُنَا تَضَرَّعُوا۟ وَلَـٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ مَا كَانُوا۟ یَعۡمَلُونَ',
    'فلولا اذ جاءهم باسنا تضرعوا ولكن قست قلوبهم وزين لهم الشيطان ما كانوا يعملون',
    'فَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َأۡسُنَا تَضَرَّعُو<rule class=slnt>اۡ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َسَتۡ قُلُوبُهُمۡ وَزَيَّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 7, 2, 132, 106, 53, 'false'
  );
  
  -- Ayah 44 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    833,
    'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحۡنَا عَلَیۡهِمۡ أَبۡوَ ٰ⁠بَ كُلِّ شَیۡءٍ حَتَّىٰۤ إِذَا فَرِحُوا۟ بِمَاۤ أُوتُوۤا۟ أَخَذۡنَـٰهُم بَغۡتَةࣰ فَإِذَا هُم مُّبۡلِسُونَ',
    'فلما نسوا ما ذكروا به فتحنا عليهم ابواب كل شيء حتى اذا فرحوا بما اوتوا اخذناهم بغتة فاذا هم مبلسون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا نَسُو<rule class=slnt>اۡ</rule> مَا ذُكِّرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> فَتَحۡنَا عَلَيۡهِمۡ أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بَ كُلِّ شَىۡءٍ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا فَرِحُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُوت<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَخَذۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َغۡتَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َإِذَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>بۡ</rule>لِس<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 7, 2, 132, 106, 53, 'false'
  );
  
  -- Ayah 45 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    834,
    'فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِینَ ظَلَمُوا۟ۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'فقطع دابر القوم الذين ظلموا والحمد لله رب العالمين',
    'فَقُطِعَ دَابِرُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ‌ۚ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٤٥',
    45, 7, 2, 133, 106, 53, 'false'
  );
  
  -- Ayah 46 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    835,
    'قُلۡ أَرَءَیۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَـٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِ یَأۡتِیكُم بِهِۗ ٱنظُرۡ كَیۡفَ نُصَرِّفُ ٱلۡـَٔایَـٰتِ ثُمَّ هُمۡ یَصۡدِفُونَ',
    'قل ارايتم ان اخذ الله سمعكم وابصاركم وختم على قلوبكم من اله غير الله ياتيكم به انظر كيف نصرف الايات ثم هم يصدفون',
    'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ سَمۡعَكُمۡ وَأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٌ غَيۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ يَأۡتِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِ‌ۗ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ نُصَرِّفُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ ثُ<rule class=ghunnah>مّ</rule>َ هُمۡ يَصۡدِف<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 7, 2, 133, 106, 53, 'false'
  );
  
  -- Ayah 47 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    836,
    'قُلۡ أَرَءَیۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ یُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلظَّـٰلِمُونَ',
    'قل ارايتكم ان اتاكم عذاب الله بغتة او جهرة هل يهلك الا القوم الظالمون',
    'قُلۡ أَرَءَيۡتَكُمۡ إِنۡ أَتَ<rule class=madda_normal>ـٰ</rule>كُمۡ عَذَابُ <rule class=ham_wasl>ٱ</rule>للَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ يُهۡلَكُ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡقَوۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 7, 2, 133, 106, 53, 'false'
  );
  
  -- Ayah 48 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    837,
    'وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِینَ إِلَّا مُبَشِّرِینَ وَمُنذِرِینَۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'وما نرسل المرسلين الا مبشرين ومنذرين فمن امن واصلح فلا خوف عليهم ولا هم يحزنون',
    'وَمَا نُرۡسِلُ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُ<rule class=ikhafa>نذ</rule>ِرِينَ‌ۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 7, 2, 133, 106, 53, 'false'
  );
  
  -- Ayah 49 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    838,
    'وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا یَمَسُّهُمُ ٱلۡعَذَابُ بِمَا كَانُوا۟ یَفۡسُقُونَ',
    'والذين كذبوا باياتنا يمسهم العذاب بما كانوا يفسقون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا يَمَسُّهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡسُق<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 7, 2, 133, 106, 53, 'false'
  );
  
  -- Ayah 50 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    839,
    'قُل لَّاۤ أَقُولُ لَكُمۡ عِندِی خَزَاۤىِٕنُ ٱللَّهِ وَلَاۤ أَعۡلَمُ ٱلۡغَیۡبَ وَلَاۤ أَقُولُ لَكُمۡ إِنِّی مَلَكٌۖ إِنۡ أَتَّبِعُ إِلَّا مَا یُوحَىٰۤ إِلَیَّۚ قُلۡ هَلۡ یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُۚ أَفَلَا تَتَفَكَّرُونَ',
    'قل لا اقول لكم عندي خزائن الله ولا اعلم الغيب ولا اقول لكم اني ملك ان اتبع الا ما يوحى الي قل هل يستوي الاعمى والبصير افلا تتفكرون',
    'قُل لّ<rule class=madda_obligatory_monfasel>َآ</rule> أَقُولُ لَكُمۡ عِ<rule class=ikhafa>ند</rule>ِى خَز<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبَ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَقُولُ لَكُمۡ إِ<rule class=ghunnah>نّ</rule>ِى مَلَكٌ‌ۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىَّ‌ۚ قُلۡ هَلۡ يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡأَعۡمَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡبَصِيرُ‌ۚ أَفَلَا تَتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 7, 2, 133, 106, 53, 'false'
  );
  
  -- Ayah 51 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    840,
    'وَأَنذِرۡ بِهِ ٱلَّذِینَ یَخَافُونَ أَن یُحۡشَرُوۤا۟ إِلَىٰ رَبِّهِمۡ لَیۡسَ لَهُم مِّن دُونِهِۦ وَلِیࣱّ وَلَا شَفِیعࣱ لَّعَلَّهُمۡ یَتَّقُونَ',
    'وانذر به الذين يخافون ان يحشروا الى ربهم ليس لهم من دونه ولي ولا شفيع لعلهم يتقون',
    'وَأَ<rule class=ikhafa>نذ</rule>ِرۡ بِهِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَخَافُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحۡشَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ رَبِّهِمۡ‌ۙ لَيۡسَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> وَلِ<rule class=idgham_ghunnah>ىٌّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا شَفِي<rule class=idgham_wo_ghunnah>عٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّهُمۡ يَتَّق<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 7, 2, 133, 107, 53, 'false'
  );
  
  -- Ayah 52 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    841,
    'وَلَا تَطۡرُدِ ٱلَّذِینَ یَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِیِّ یُرِیدُونَ وَجۡهَهُۥۖ مَا عَلَیۡكَ مِنۡ حِسَابِهِم مِّن شَیۡءࣲ وَمَا مِنۡ حِسَابِكَ عَلَیۡهِم مِّن شَیۡءࣲ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّـٰلِمِینَ',
    'ولا تطرد الذين يدعون ربهم بالغداة والعشي يريدون وجهه ما عليك من حسابهم من شيء وما من حسابك عليهم من شيء فتطردهم فتكون من الظالمين',
    'وَلَا تَ<rule class=qalaqah>طۡ</rule>رُدِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ رَبَّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡغَدَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَ<rule class=ham_wasl>ٱ</rule>لۡعَشِىِّ يُرِيدُونَ وَ<rule class=qalaqah>جۡ</rule>هَهُ<rule class=madda_normal>ۥ</rule>‌ۖ مَا عَلَيۡكَ مِنۡ حِسَابِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا مِنۡ حِسَابِكَ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َتَ<rule class=qalaqah>طۡ</rule>رُدَهُمۡ فَتَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥٢',
    52, 7, 2, 133, 107, 53, 'false'
  );
  
  -- Ayah 53 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    842,
    'وَكَذَ ٰ⁠لِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضࣲ لِّیَقُولُوۤا۟ أَهَـٰۤؤُلَاۤءِ مَنَّ ٱللَّهُ عَلَیۡهِم مِّنۢ بَیۡنِنَاۤۗ أَلَیۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّـٰكِرِینَ',
    'وكذلك فتنا بعضهم ببعض ليقولوا اهؤلاء من الله عليهم من بيننا اليس الله باعلم بالشاكرين',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ فَتَ<rule class=ghunnah>نّ</rule>َا بَعۡضَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَعۡ<rule class=idgham_wo_ghunnah>ضٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَقُول<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِن<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> أَلَيۡسَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِأَعۡلَمَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 7, 2, 134, 107, 53, 'false'
  );
  
  -- Ayah 54 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    843,
    'وَإِذَا جَاۤءَكَ ٱلَّذِینَ یُؤۡمِنُونَ بِـَٔایَـٰتِنَا فَقُلۡ سَلَـٰمٌ عَلَیۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوۤءَۢا بِجَهَـٰلَةࣲ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورࣱ رَّحِیمࣱ',
    'واذا جاءك الذين يؤمنون باياتنا فقل سلام عليكم كتب ربكم على نفسه الرحمة انه من عمل منكم سوءا بجهالة ثم تاب من بعده واصلح فانه غفور رحيم',
    'وَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡمِنُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَقُلۡ سَلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَيۡكُمۡ‌ۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَةَ‌ۖ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مَنۡ عَمِلَ مِ<rule class=ikhafa>نك</rule>ُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓء<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِجَهَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ تَابَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> وَأَصۡلَحَ فَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٥٤',
    54, 7, 2, 134, 107, 53, 'false'
  );
  
  -- Ayah 55 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    844,
    'وَكَذَ ٰ⁠لِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ وَلِتَسۡتَبِینَ سَبِیلُ ٱلۡمُجۡرِمِینَ',
    'وكذلك نفصل الايات ولتستبين سبيل المجرمين',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نُفَصِّلُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ وَلِتَسۡتَبِينَ سَبِيلُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 7, 2, 134, 107, 53, 'false'
  );
  
  -- Ayah 56 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    845,
    'قُلۡ إِنِّی نُهِیتُ أَنۡ أَعۡبُدَ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّاۤ أَتَّبِعُ أَهۡوَاۤءَكُمۡ قَدۡ ضَلَلۡتُ إِذࣰا وَمَاۤ أَنَا۠ مِنَ ٱلۡمُهۡتَدِینَ',
    'قل اني نهيت ان اعبد الذين تدعون من دون الله قل لا اتبع اهواءكم قد ضللت اذا وما انا من المهتدين',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>ِى نُهِيتُ أَنۡ أَعۡبُدَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ قُل لّ<rule class=madda_obligatory_monfasel>َآ</rule> أَتَّبِعُ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ‌ۙ قَ<rule class=qalaqah>دۡ</rule> ضَلَلۡتُ إِ<rule class=idgham_ghunnah>ذًا</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ٥٦',
    56, 7, 2, 134, 108, 53, 'false'
  );
  
  -- Ayah 57 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    846,
    'قُلۡ إِنِّی عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّی وَكَذَّبۡتُم بِهِۦۚ مَا عِندِی مَا تَسۡتَعۡجِلُونَ بِهِۦۤۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ یَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَیۡرُ ٱلۡفَـٰصِلِینَ',
    'قل اني على بينة من ربي وكذبتم به ما عندي ما تستعجلون به ان الحكم الا لله يقص الحق وهو خير الفاصلين',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>ِى عَلَىٰ بَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّى وَكَذَّ<rule class=qalaqah>بۡ</rule>ت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۚ مَا عِ<rule class=ikhafa>ند</rule>ِى مَا تَسۡتَعۡجِلُونَ بِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِنِ <rule class=ham_wasl>ٱ</rule>لۡحُكۡمُ إِلَّا لِلَّهِ‌ۖ يَقُصُّ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ‌ۖ وَهُوَ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>صِل<rule class=madda_permissible>ِي</rule>نَ ٥٧',
    57, 7, 2, 134, 108, 53, 'false'
  );
  
  -- Ayah 58 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    847,
    'قُل لَّوۡ أَنَّ عِندِی مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِیَ ٱلۡأَمۡرُ بَیۡنِی وَبَیۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّـٰلِمِینَ',
    'قل لو ان عندي ما تستعجلون به لقضي الامر بيني وبينكم والله اعلم بالظالمين',
    'قُل لَّوۡ أَ<rule class=ghunnah>نّ</rule>َ عِ<rule class=ikhafa>ند</rule>ِى مَا تَسۡتَعۡجِلُونَ بِه<rule class=madda_normal>ِۦ</rule> لَقُضِىَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ بَيۡنِى وَبَيۡنَكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 7, 2, 134, 108, 53, 'false'
  );
  
  -- Ayah 59 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    848,
    '۞ وَعِندَهُۥ مَفَاتِحُ ٱلۡغَیۡبِ لَا یَعۡلَمُهَاۤ إِلَّا هُوَۚ وَیَعۡلَمُ مَا فِی ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا یَعۡلَمُهَا وَلَا حَبَّةࣲ فِی ظُلُمَـٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبࣲ وَلَا یَابِسٍ إِلَّا فِی كِتَـٰبࣲ مُّبِینࣲ',
    'وعنده مفاتح الغيب لا يعلمها الا هو ويعلم ما في البر والبحر وما تسقط من ورقة الا يعلمها ولا حبة في ظلمات الارض ولا رطب ولا يابس الا في كتاب مبين',
    '۞وَعِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> مَفَاتِحُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ لَا يَعۡلَمُه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا هُوَ‌ۚ وَيَعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule>لۡبَرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ‌ۚ وَمَا تَسۡقُطُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َرَقَةٍ إِلَّا يَعۡلَمُهَا وَلَا حَبَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى ظُلُمَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا رَ<rule class=qalaqah>طۡ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَابِسٍ إِلَّا فِى كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٥٩',
    59, 7, 2, 134, 108, 54, 'false'
  );
  
  -- Ayah 60 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    849,
    'وَهُوَ ٱلَّذِی یَتَوَفَّىٰكُم بِٱلَّیۡلِ وَیَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ یَبۡعَثُكُمۡ فِیهِ لِیُقۡضَىٰۤ أَجَلࣱ مُّسَمࣰّىۖ ثُمَّ إِلَیۡهِ مَرۡجِعُكُمۡ ثُمَّ یُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'وهو الذي يتوفاكم بالليل ويعلم ما جرحتم بالنهار ثم يبعثكم فيه ليقضى اجل مسمى ثم اليه مرجعكم ثم ينبئكم بما كنتم تعملون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يَتَوَفَّ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَيَعۡلَمُ مَا جَرَحۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ ثُ<rule class=ghunnah>مّ</rule>َ يَ<rule class=qalaqah>بۡ</rule>عَثُكُمۡ فِيهِ لِيُ<rule class=qalaqah>قۡ</rule>ضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=ikhafa>ًّى‌ۖ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ إِلَيۡهِ مَرۡجِعُكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 7, 2, 135, 108, 54, 'false'
  );
  
  -- Ayah 61 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    850,
    'وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَیُرۡسِلُ عَلَیۡكُمۡ حَفَظَةً حَتَّىٰۤ إِذَا جَاۤءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا یُفَرِّطُونَ',
    'وهو القاهر فوق عباده ويرسل عليكم حفظة حتى اذا جاء احدكم الموت توفته رسلنا وهم لا يفرطون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡقَاهِرُ فَوۡقَ عِبَادِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَحَدَكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّط<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 7, 2, 135, 109, 54, 'false'
  );
  
  -- Ayah 62 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    851,
    'ثُمَّ رُدُّوۤا۟ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَـٰسِبِینَ',
    'ثم ردوا الى الله مولاهم الحق الا له الحكم وهو اسرع الحاسبين',
    'ثُ<rule class=ghunnah>مّ</rule>َ رُدّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَوۡلَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ أَلَا لَهُ <rule class=ham_wasl>ٱ</rule>لۡحُكۡمُ وَهُوَ أَسۡرَعُ <rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>سِب<rule class=madda_permissible>ِي</rule>نَ ٦٢',
    62, 7, 2, 135, 109, 54, 'false'
  );
  
  -- Ayah 63 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    852,
    'قُلۡ مَن یُنَجِّیكُم مِّن ظُلُمَـٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعࣰا وَخُفۡیَةࣰ لَّىِٕنۡ أَنجَىٰنَا مِنۡ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِینَ',
    'قل من ينجيكم من ظلمات البر والبحر تدعونه تضرعا وخفية لئن انجانا من هذه لنكونن من الشاكرين',
    'قُلۡ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُنَجِّيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>ُلُمَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡبَرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ تَ<rule class=qalaqah>دۡ</rule>عُونَهُ<rule class=madda_normal>ۥ</rule> تَضَرُّ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َخُفۡيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّئِنۡ أَ<rule class=ikhafa>نج</rule>َ<rule class=madda_normal>ـٰ</rule>نَا مِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> لَنَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ٦٣',
    63, 7, 2, 135, 109, 54, 'false'
  );
  
  -- Ayah 64 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    853,
    'قُلِ ٱللَّهُ یُنَجِّیكُم مِّنۡهَا وَمِن كُلِّ كَرۡبࣲ ثُمَّ أَنتُمۡ تُشۡرِكُونَ',
    'قل الله ينجيكم منها ومن كل كرب ثم انتم تشركون',
    'قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ يُنَجِّيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ كَرۡ<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=ikhafa>نت</rule>ُمۡ تُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 7, 2, 135, 109, 54, 'false'
  );
  
  -- Ayah 65 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    854,
    'قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰۤ أَن یَبۡعَثَ عَلَیۡكُمۡ عَذَابࣰا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ یَلۡبِسَكُمۡ شِیَعࣰا وَیُذِیقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَیۡفَ نُصَرِّفُ ٱلۡـَٔایَـٰتِ لَعَلَّهُمۡ یَفۡقَهُونَ',
    'قل هو القادر على ان يبعث عليكم عذابا من فوقكم او من تحت ارجلكم او يلبسكم شيعا ويذيق بعضكم باس بعض انظر كيف نصرف الايات لعلهم يفقهون',
    'قُلۡ هُوَ <rule class=ham_wasl>ٱ</rule>لۡقَادِرُ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>عَثَ عَلَيۡكُمۡ عَذَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِكُمۡ أَوۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َيُذِيقَ بَعۡضَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َأۡسَ بَعۡضٍ‌ۗ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ نُصَرِّفُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لَعَلَّهُمۡ يَفۡقَه<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 7, 2, 135, 109, 54, 'false'
  );
  
  -- Ayah 66 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    855,
    'وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَیۡكُم بِوَكِیلࣲ',
    'وكذب به قومك وهو الحق قل لست عليكم بوكيل',
    'وَكَذَّبَ بِه<rule class=madda_normal>ِۦ</rule> قَوۡمُكَ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۚ قُل لَّسۡتُ عَلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِوَك<rule class=madda_permissible>ِي</rule>لٍ ٦٦',
    66, 7, 2, 135, 109, 54, 'false'
  );
  
  -- Ayah 67 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    856,
    'لِّكُلِّ نَبَإࣲ مُّسۡتَقَرࣱّۚ وَسَوۡفَ تَعۡلَمُونَ',
    'لكل نبا مستقر وسوف تعلمون',
    'لِّكُلِّ نَبَ<rule class=idgham_ghunnah>إٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقَ<rule class=idgham_ghunnah>رٌّ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َسَوۡفَ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 7, 2, 135, 109, 54, 'false'
  );
  
  -- Ayah 68 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    857,
    'وَإِذَا رَأَیۡتَ ٱلَّذِینَ یَخُوضُونَ فِیۤ ءَایَـٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ یَخُوضُوا۟ فِی حَدِیثٍ غَیۡرِهِۦۚ وَإِمَّا یُنسِیَنَّكَ ٱلشَّیۡطَـٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'واذا رايت الذين يخوضون في اياتنا فاعرض عنهم حتى يخوضوا في حديث غيره واما ينسينك الشيطان فلا تقعد بعد الذكرى مع القوم الظالمين',
    'وَإِذَا رَأَيۡتَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَخُوضُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ يَخُوضُو<rule class=slnt>اۡ</rule> فِى حَدِيثٍ غَيۡرِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَإِ<rule class=ghunnah>مّ</rule>َا يُ<rule class=ikhafa>نس</rule>ِيَ<rule class=ghunnah>نّ</rule>َكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ فَلَا تَ<rule class=qalaqah>قۡ</rule>عُ<rule class=qalaqah>دۡ</rule> بَعۡدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَىٰ مَعَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٦٨',
    68, 7, 2, 135, 109, 54, 'false'
  );
  
  -- Ayah 69 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    858,
    'وَمَا عَلَى ٱلَّذِینَ یَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَیۡءࣲ وَلَـٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ یَتَّقُونَ',
    'وما على الذين يتقون من حسابهم من شيء ولكن ذكرى لعلهم يتقون',
    'وَمَا عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَتَّقُونَ مِنۡ حِسَابِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرَىٰ لَعَلَّهُمۡ يَتَّق<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 7, 2, 136, 109, 54, 'false'
  );
  
  -- Ayah 70 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    859,
    'وَذَرِ ٱلَّذِینَ ٱتَّخَذُوا۟ دِینَهُمۡ لَعِبࣰا وَلَهۡوࣰا وَغَرَّتۡهُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۚ وَذَكِّرۡ بِهِۦۤ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَیۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِیࣱّ وَلَا شَفِیعࣱ وَإِن تَعۡدِلۡ كُلَّ عَدۡلࣲ لَّا یُؤۡخَذۡ مِنۡهَاۤۗ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ أُبۡسِلُوا۟ بِمَا كَسَبُوا۟ۖ لَهُمۡ شَرَابࣱ مِّنۡ حَمِیمࣲ وَعَذَابٌ أَلِیمُۢ بِمَا كَانُوا۟ یَكۡفُرُونَ',
    'وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحياة الدنيا وذكر به ان تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع وان تعدل كل عدل لا يؤخذ منها اولئك الذين ابسلوا بما كسبوا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون',
    'وَذَرِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> دِينَهُمۡ لَعِ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َلَهۡ<rule class=idgham_ghunnah>وًا</rule> <rule class=idgham_ghunnah>و</rule>َغَرَّتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۚ وَذَكِّرۡ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>بۡ</rule>سَلَ نَفۡ<rule class=iqlab>سُۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَسَبَتۡ لَيۡسَ لَهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلِ<rule class=idgham_ghunnah>ىٌّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا شَفِي<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡدِلۡ كُلَّ عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_wo_ghunnah>لٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡخَذۡ مِنۡه<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُ<rule class=qalaqah>بۡ</rule>سِلُو<rule class=slnt>اۡ</rule> بِمَا كَسَبُو<rule class=slnt>اۡ‌ۖ</rule> لَهُمۡ شَرَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ حَمِي<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَذَابٌ أَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 7, 2, 136, 109, 54, 'false'
  );
  
  -- Ayah 71 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    860,
    'قُلۡ أَنَدۡعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا یَنفَعُنَا وَلَا یَضُرُّنَا وَنُرَدُّ عَلَىٰۤ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِی ٱسۡتَهۡوَتۡهُ ٱلشَّیَـٰطِینُ فِی ٱلۡأَرۡضِ حَیۡرَانَ لَهُۥۤ أَصۡحَـٰبࣱ یَدۡعُونَهُۥۤ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَـٰلَمِینَ',
    'قل اندعو من دون الله ما لا ينفعنا ولا يضرنا ونرد على اعقابنا بعد اذ هدانا الله كالذي استهوته الشياطين في الارض حيران له اصحاب يدعونه الى الهدى ائتنا قل ان هدى الله هو الهدى وامرنا لنسلم لرب العالمين',
    'قُلۡ أَنَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَ<rule class=ikhafa>نف</rule>َعُنَا وَلَا يَضُرُّنَا وَنُرَدُّ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَ<rule class=madda_normal>ٮٰ</rule>نَا <rule class=ham_wasl>ٱ</rule>للَّهُ كَ<rule class=ham_wasl>ٱ</rule>لَّذِى <rule class=ham_wasl>ٱ</rule>سۡتَهۡوَتۡهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ حَيۡرَانَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>عُونَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡهُدَى <rule class=ham_wasl>ٱ</rule>ئۡتِنَا‌ۗ قُلۡ إِ<rule class=ghunnah>نّ</rule>َ هُدَى <rule class=ham_wasl>ٱ</rule>للَّهِ هُوَ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ‌ۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٧١',
    71, 7, 2, 136, 110, 54, 'false'
  );
  
  -- Ayah 72 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    861,
    'وَأَنۡ أَقِیمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِیۤ إِلَیۡهِ تُحۡشَرُونَ',
    'وان اقيموا الصلاة واتقوه وهو الذي اليه تحشرون',
    'وَأَنۡ أَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>تَّقُوهُ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ تُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 7, 2, 136, 110, 54, 'false'
  );
  
  -- Ayah 73 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    862,
    'وَهُوَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَیَوۡمَ یَقُولُ كُن فَیَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ یَوۡمَ یُنفَخُ فِی ٱلصُّورِۚ عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡخَبِیرُ',
    'وهو الذي خلق السماوات والارض بالحق ويوم يقول كن فيكون قوله الحق وله الملك يوم ينفخ في الصور عالم الغيب والشهادة وهو الحكيم الخبير',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ وَيَوۡمَ يَقُولُ كُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َيَكُونُ‌ۚ قَوۡلُهُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۚ وَلَهُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكُ يَوۡمَ يُ<rule class=ikhafa>نف</rule>َخُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ‌ۚ عَ<rule class=madda_normal>ـٰ</rule>لِمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡحَكِيمُ <rule class=ham_wasl>ٱ</rule>لۡخَب<rule class=madda_permissible>ِي</rule>رُ ٧٣',
    73, 7, 2, 136, 110, 54, 'false'
  );
  
  -- Ayah 74 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    863,
    '۞ وَإِذۡ قَالَ إِبۡرَ ٰ⁠هِیمُ لِأَبِیهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّیۤ أَرَىٰكَ وَقَوۡمَكَ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'واذ قال ابراهيم لابيه ازر اتتخذ اصناما الهة اني اراك وقومك في ضلال مبين',
    '۞وَإِذۡ قَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً‌ۖ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَ<rule class=madda_normal>ٮٰ</rule>كَ وَقَوۡمَكَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٧٤',
    74, 7, 2, 137, 110, 55, 'false'
  );
  
  -- Ayah 75 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    864,
    'وَكَذَ ٰ⁠لِكَ نُرِیۤ إِبۡرَ ٰ⁠هِیمَ مَلَكُوتَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَلِیَكُونَ مِنَ ٱلۡمُوقِنِینَ',
    'وكذلك نري ابراهيم ملكوت السماوات والارض وليكون من الموقنين',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نُر<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ مَلَكُوتَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلِيَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُوقِن<rule class=madda_permissible>ِي</rule>نَ ٧٥',
    75, 7, 2, 137, 110, 55, 'false'
  );
  
  -- Ayah 76 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    865,
    'فَلَمَّا جَنَّ عَلَیۡهِ ٱلَّیۡلُ رَءَا كَوۡكَبࣰاۖ قَالَ هَـٰذَا رَبِّیۖ فَلَمَّاۤ أَفَلَ قَالَ لَاۤ أُحِبُّ ٱلۡـَٔافِلِینَ',
    'فلما جن عليه الليل راى كوكبا قال هذا ربي فلما افل قال لا احب الافلين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا جَ<rule class=ghunnah>نّ</rule>َ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لَّيۡلُ رَءَا كَوۡكَ<rule class=ikhafa>بًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا رَبِّى‌ۖ فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَفَلَ قَالَ ل<rule class=madda_obligatory_monfasel>َآ</rule> أُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡأَفِل<rule class=madda_permissible>ِي</rule>نَ ٧٦',
    76, 7, 2, 137, 110, 55, 'false'
  );
  
  -- Ayah 77 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    866,
    'فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغࣰا قَالَ هَـٰذَا رَبِّیۖ فَلَمَّاۤ أَفَلَ قَالَ لَىِٕن لَّمۡ یَهۡدِنِی رَبِّی لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّاۤلِّینَ',
    'فلما راى القمر بازغا قال هذا ربي فلما افل قال لئن لم يهدني ربي لاكونن من القوم الضالين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا رَءَا <rule class=ham_wasl>ٱ</rule>لۡقَمَرَ بَازِ<rule class=ikhafa>غًا</rule> <rule class=ikhafa>ق</rule>َالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا رَبِّى‌ۖ فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَفَلَ قَالَ لَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَهۡدِنِى رَبِّى لَأَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضّ<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ِي</rule>نَ ٧٧',
    77, 7, 2, 137, 110, 55, 'false'
  );
  
  -- Ayah 78 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    867,
    'فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةࣰ قَالَ هَـٰذَا رَبِّی هَـٰذَاۤ أَكۡبَرُۖ فَلَمَّاۤ أَفَلَتۡ قَالَ یَـٰقَوۡمِ إِنِّی بَرِیۤءࣱ مِّمَّا تُشۡرِكُونَ',
    'فلما راى الشمس بازغة قال هذا ربي هذا اكبر فلما افلت قال يا قوم اني بريء مما تشركون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا رَءَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ بَازِغَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ق</rule>َالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا رَبِّى هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡبَرُ‌ۖ فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَفَلَتۡ قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ghunnah>نّ</rule>ِى بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 7, 2, 137, 110, 55, 'false'
  );
  
  -- Ayah 79 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    868,
    'إِنِّی وَجَّهۡتُ وَجۡهِیَ لِلَّذِی فَطَرَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ حَنِیفࣰاۖ وَمَاۤ أَنَا۠ مِنَ ٱلۡمُشۡرِكِینَ',
    'اني وجهت وجهي للذي فطر السماوات والارض حنيفا وما انا من المشركين',
    'إِ<rule class=ghunnah>نّ</rule>ِى وَجَّهۡتُ وَ<rule class=qalaqah>جۡ</rule>هِىَ لِلَّذِى فَطَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ حَنِي<rule class=idgham_ghunnah>فًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٧٩',
    79, 7, 2, 137, 110, 55, 'false'
  );
  
  -- Ayah 80 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    869,
    'وَحَاۤجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَـٰۤجُّوۤنِّی فِی ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَاۤ أَخَافُ مَا تُشۡرِكُونَ بِهِۦۤ إِلَّاۤ أَن یَشَاۤءَ رَبِّی شَیۡـࣰٔاۚ وَسِعَ رَبِّی كُلَّ شَیۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ',
    'وحاجه قومه قال اتحاجوني في الله وقد هدان ولا اخاف ما تشركون به الا ان يشاء ربي شيئا وسع ربي كل شيء علما افلا تتذكرون',
    'وَح<rule class=madda_necessary>َا</rule>ٓجَّهُ<rule class=madda_normal>ۥ</rule> قَوۡمُهُ<rule class=madda_normal>ۥ</rule>‌ۚ قَالَ أَتُحَ<rule class=madda_necessary>ـٰٓ</rule>جّ<rule class=madda_necessary>ُو</rule>ٓ<rule class=ghunnah>نّ</rule>ِى فِى <rule class=ham_wasl>ٱ</rule>للَّهِ وَقَ<rule class=qalaqah>دۡ</rule> هَدَ<rule class=madda_normal>ٮٰ</rule>نِ‌ۚ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَخَافُ مَا تُشۡرِكُونَ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبِّى شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َسِعَ رَبِّى كُلَّ شَىۡءٍ عِلۡمًا‌ۗ أَفَلَا تَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 7, 2, 137, 110, 55, 'false'
  );
  
  -- Ayah 81 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    870,
    'وَكَیۡفَ أَخَافُ مَاۤ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ عَلَیۡكُمۡ سُلۡطَـٰنࣰاۚ فَأَیُّ ٱلۡفَرِیقَیۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ',
    'وكيف اخاف ما اشركتم ولا تخافون انكم اشركتم بالله ما لم ينزل به عليكم سلطانا فاي الفريقين احق بالامن ان كنتم تعلمون',
    'وَكَيۡفَ أَخَافُ م<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَ<rule class=ghunnah>نّ</rule>َكُمۡ أَشۡرَكۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَمۡ يُنَزِّلۡ بِه<rule class=madda_normal>ِۦ</rule> عَلَيۡكُمۡ سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َأَىُّ <rule class=ham_wasl>ٱ</rule>لۡفَرِيقَيۡنِ أَحَقُّ بِ<rule class=ham_wasl>ٱ</rule>لۡأَمۡنِ‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 7, 2, 137, 110, 55, 'false'
  );
  
  -- Ayah 82 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    871,
    'ٱلَّذِینَ ءَامَنُوا۟ وَلَمۡ یَلۡبِسُوۤا۟ إِیمَـٰنَهُم بِظُلۡمٍ أُو۟لَـٰۤىِٕكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ',
    'الذين امنوا ولم يلبسوا ايمانهم بظلم اولئك لهم الامن وهم مهتدون',
    'ٱلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَلَمۡ يَلۡبِس<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِيمَ<rule class=madda_normal>ـٰ</rule>نَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِظُلۡمٍ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡنُ وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 7, 2, 138, 110, 55, 'false'
  );
  
  -- Ayah 83 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    872,
    'وَتِلۡكَ حُجَّتُنَاۤ ءَاتَیۡنَـٰهَاۤ إِبۡرَ ٰ⁠هِیمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَـٰتࣲ مَّن نَّشَاۤءُۗ إِنَّ رَبَّكَ حَكِیمٌ عَلِیمࣱ',
    'وتلك حجتنا اتيناها ابراهيم على قومه نرفع درجات من نشاء ان ربك حكيم عليم',
    'وَتِلۡكَ حُجَّتُن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ عَلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule>‌ۚ نَرۡفَعُ دَرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ حَكِيمٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٨٣',
    83, 7, 2, 138, 111, 55, 'false'
  );
  
  -- Ayah 84 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    873,
    'وَوَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَۚ كُلًّا هَدَیۡنَاۚ وَنُوحًا هَدَیۡنَا مِن قَبۡلُۖ وَمِن ذُرِّیَّتِهِۦ دَاوُۥدَ وَسُلَیۡمَـٰنَ وَأَیُّوبَ وَیُوسُفَ وَمُوسَىٰ وَهَـٰرُونَۚ وَكَذَ ٰ⁠لِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ',
    'ووهبنا له اسحاق ويعقوب كلا هدينا ونوحا هدينا من قبل ومن ذريته داوود وسليمان وايوب ويوسف وموسى وهارون وكذلك نجزي المحسنين',
    'وَوَهَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ‌ۚ كُلاًّ هَدَيۡنَا‌ۚ وَنُوحًا هَدَيۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُرِّيَّتِه<rule class=madda_normal>ِۦ</rule> دَاوُ<rule class=madda_normal>ۥ</rule>دَ وَسُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ وَأَيُّوبَ وَيُوسُفَ وَمُوسَىٰ وَهَ<rule class=madda_normal>ـٰ</rule>رُونَ‌ۚ وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٨٤',
    84, 7, 2, 138, 111, 55, 'false'
  );
  
  -- Ayah 85 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    874,
    'وَزَكَرِیَّا وَیَحۡیَىٰ وَعِیسَىٰ وَإِلۡیَاسَۖ كُلࣱّ مِّنَ ٱلصَّـٰلِحِینَ',
    'وزكريا ويحيى وعيسى والياس كل من الصالحين',
    'وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَ‌ۖ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 7, 2, 138, 111, 55, 'false'
  );
  
  -- Ayah 86 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    875,
    'وَإِسۡمَـٰعِیلَ وَٱلۡیَسَعَ وَیُونُسَ وَلُوطࣰاۚ وَكُلࣰّا فَضَّلۡنَا عَلَى ٱلۡعَـٰلَمِینَ',
    'واسماعيل واليسع ويونس ولوطا وكلا فضلنا على العالمين',
    'وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَ<rule class=ham_wasl>ٱ</rule>لۡيَسَعَ وَيُونُسَ وَلُو<rule class=idgham_ghunnah>طًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكُل<rule class=ikhafa>اًّ</rule> <rule class=ikhafa>ف</rule>َضَّلۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 7, 2, 138, 111, 55, 'false'
  );
  
  -- Ayah 87 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    876,
    'وَمِنۡ ءَابَاۤىِٕهِمۡ وَذُرِّیَّـٰتِهِمۡ وَإِخۡوَ ٰ⁠نِهِمۡۖ وَٱجۡتَبَیۡنَـٰهُمۡ وَهَدَیۡنَـٰهُمۡ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'ومن ابائهم وذرياتهم واخوانهم واجتبيناهم وهديناهم الى صراط مستقيم',
    'وَمِنۡ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ وَذُرِّيَّ<rule class=madda_normal>ـٰ</rule>تِهِمۡ وَإِخۡو<rule class=madda_normal>ٰ</rule>نِهِمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَبَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَهَدَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٨٧',
    87, 7, 2, 138, 111, 55, 'false'
  );
  
  -- Ayah 88 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    877,
    'ذَ ٰ⁠لِكَ هُدَى ٱللَّهِ یَهۡدِی بِهِۦ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُوا۟ لَحَبِطَ عَنۡهُم مَّا كَانُوا۟ یَعۡمَلُونَ',
    'ذلك هدى الله يهدي به من يشاء من عباده ولو اشركوا لحبط عنهم ما كانوا يعملون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ هُدَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَهۡدِى بِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَلَوۡ أَشۡرَكُو<rule class=slnt>اۡ</rule> لَحَبِطَ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 7, 2, 138, 111, 55, 'false'
  );
  
  -- Ayah 89 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    878,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن یَكۡفُرۡ بِهَا هَـٰۤؤُلَاۤءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمࣰا لَّیۡسُوا۟ بِهَا بِكَـٰفِرِینَ',
    'اولئك الذين اتيناهم الكتاب والحكم والنبوة فان يكفر بها هؤلاء فقد وكلنا بها قوما ليسوا بها بكافرين',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحُكۡمَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُبُوَّةَ‌ۚ فَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرۡ بِهَا هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَقَ<rule class=qalaqah>دۡ</rule> وَكَّلۡنَا بِهَا قَوۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيۡسُو<rule class=slnt>اۡ</rule> بِهَا بِكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٨٩',
    89, 7, 2, 138, 111, 55, 'false'
  );
  
  -- Ayah 90 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    879,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَـٰلَمِینَ',
    'اولئك الذين هدى الله فبهداهم اقتده قل لا اسالكم عليه اجرا ان هو الا ذكرى للعالمين',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَدَى <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ فَبِهُدَ<rule class=madda_normal>ٮٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تَدِهۡ‌ۗ قُل لّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ أَ<rule class=qalaqah>جۡ</rule>رًا‌ۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٩٠',
    90, 7, 2, 138, 111, 55, 'false'
  );
  
  -- Ayah 91 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    880,
    'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدۡرِهِۦۤ إِذۡ قَالُوا۟ مَاۤ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرࣲ مِّن شَیۡءࣲۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَـٰبَ ٱلَّذِی جَاۤءَ بِهِۦ مُوسَىٰ نُورࣰا وَهُدࣰى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِیسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِیرࣰاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوۤا۟ أَنتُمۡ وَلَاۤ ءَابَاۤؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِی خَوۡضِهِمۡ یَلۡعَبُونَ',
    'وما قدروا الله حق قدره اذ قالوا ما انزل الله على بشر من شيء قل من انزل الكتاب الذي جاء به موسى نورا وهدى للناس تجعلونه قراطيس تبدونها وتخفون كثيرا وعلمتم ما لم تعلموا انتم ولا اباؤكم قل الله ثم ذرهم في خوضهم يلعبون',
    'وَمَا قَدَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ حَقَّ قَ<rule class=qalaqah>دۡ</rule>رِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِذۡ قَالُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ بَشَ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۗ</rule> <rule class=ikhafa>ق</rule>ُلۡ مَنۡ أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لَّذِى ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِه<rule class=madda_normal>ِۦ</rule> مُوسَىٰ نُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َهُ<rule class=idgham_wo_ghunnah>دًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ‌ۖ تَ<rule class=qalaqah>جۡ</rule>عَلُونَهُ<rule class=madda_normal>ۥ</rule> قَرَاطِيسَ تُ<rule class=qalaqah>بۡ</rule>دُونَهَا وَتُخۡفُونَ كَثِي<rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َعُلِّمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا لَمۡ تَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ‌ۖ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ ذَرۡهُمۡ فِى خَوۡضِهِمۡ يَلۡعَب<rule class=madda_permissible>ُو</rule>نَ ٩١',
    91, 7, 2, 139, 112, 55, 'false'
  );
  
  -- Ayah 92 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    881,
    'وَهَـٰذَا كِتَـٰبٌ أَنزَلۡنَـٰهُ مُبَارَكࣱ مُّصَدِّقُ ٱلَّذِی بَیۡنَ یَدَیۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِینَ یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ یُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ یُحَافِظُونَ',
    'وهذا كتاب انزلناه مبارك مصدق الذي بين يديه ولتنذر ام القرى ومن حولها والذين يؤمنون بالاخرة يؤمنون به وهم على صلاتهم يحافظون',
    'وَهَ<rule class=madda_normal>ـٰ</rule>ذَا كِتَ<rule class=madda_normal>ـٰ</rule>بٌ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ مُبَارَ<rule class=idgham_ghunnah>كٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّصَدِّقُ <rule class=ham_wasl>ٱ</rule>لَّذِى بَيۡنَ يَدَيۡهِ وَلِتُ<rule class=ikhafa>نذ</rule>ِرَ أُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ وَمَنۡ حَوۡلَهَا‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ يُؤۡمِنُونَ بِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظ<rule class=madda_permissible>ُو</rule>نَ ٩٢',
    92, 7, 2, 139, 112, 55, 'false'
  );
  
  -- Ayah 93 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    882,
    'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِیَ إِلَیَّ وَلَمۡ یُوحَ إِلَیۡهِ شَیۡءࣱ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَاۤ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰۤ إِذِ ٱلظَّـٰلِمُونَ فِی غَمَرَ ٰ⁠تِ ٱلۡمَوۡتِ وَٱلۡمَلَـٰۤىِٕكَةُ بَاسِطُوۤا۟ أَیۡدِیهِمۡ أَخۡرِجُوۤا۟ أَنفُسَكُمُۖ ٱلۡیَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَیۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَایَـٰتِهِۦ تَسۡتَكۡبِرُونَ',
    'ومن اظلم ممن افترى على الله كذبا او قال اوحي الي ولم يوح اليه شيء ومن قال سانزل مثل ما انزل الله ولو ترى اذ الظالمون في غمرات الموت والملائكة باسطو ايديهم اخرجوا انفسكم اليوم تجزون عذاب الهون بما كنتم تقولون على الله غير الحق وكنتم عن اياته تستكبرون',
    'وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا أَوۡ قَالَ أُوحِىَ إِلَىَّ وَلَمۡ يُوحَ إِلَيۡهِ ش<rule class=idgham_ghunnah>َىۡءٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َالَ سَأُ<rule class=ikhafa>نز</rule>ِلُ مِثۡلَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ وَلَوۡ تَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ فِى غَمَر<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ بَاسِط<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡدِيهِمۡ أَخۡرِج<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَكُمُ‌ۖ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ تُ<rule class=qalaqah>جۡ</rule>زَوۡنَ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡهُونِ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَقُولُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ غَيۡرَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَكُ<rule class=ikhafa>نت</rule>ُمۡ عَنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> تَسۡتَكۡبِر<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 7, 2, 139, 112, 55, 'false'
  );
  
  -- Ayah 94 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    883,
    'وَلَقَدۡ جِئۡتُمُونَا فُرَ ٰ⁠دَىٰ كَمَا خَلَقۡنَـٰكُمۡ أَوَّلَ مَرَّةࣲ وَتَرَكۡتُم مَّا خَوَّلۡنَـٰكُمۡ وَرَاۤءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَاۤءَكُمُ ٱلَّذِینَ زَعَمۡتُمۡ أَنَّهُمۡ فِیكُمۡ شُرَكَـٰۤؤُا۟ۚ لَقَد تَّقَطَّعَ بَیۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ',
    'ولقد جئتمونا فرادى كما خلقناكم اول مرة وتركتم ما خولناكم وراء ظهوركم وما نرى معكم شفعاءكم الذين زعمتم انهم فيكم شركاء لقد تقطع بينكم وضل عنكم ما كنتم تزعمون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> جِئۡتُمُونَا فُر<rule class=madda_normal>ٰ</rule>دَىٰ كَمَا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ أَوَّلَ مَرَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َتَرَكۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا خَوَّلۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ظُهُورِكُمۡ‌ۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ زَعَمۡتُمۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ فِيكُمۡ شُرَكَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule>‌ۚ لَقَ<rule class=idgham_mutajanisayn>د</rule> تَّقَطَّعَ بَيۡنَكُمۡ وَضَلَّ عَ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كُ<rule class=ikhafa>نت</rule>ُمۡ تَزۡعُم<rule class=madda_permissible>ُو</rule>نَ ٩٤',
    94, 7, 2, 139, 112, 55, 'false'
  );
  
  -- Ayah 95 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    884,
    '۞ إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ یُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَمُخۡرِجُ ٱلۡمَیِّتِ مِنَ ٱلۡحَیِّۚ ذَ ٰ⁠لِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ',
    'ان الله فالق الحب والنوى يخرج الحي من الميت ومخرج الميت من الحي ذلكم الله فانى تؤفكون',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ فَالِقُ <rule class=ham_wasl>ٱ</rule>لۡحَبِّ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َوَىٰ‌ۖ يُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡحَىَّ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَيِّتِ وَمُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡمَيِّتِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَىِّ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ فَأَ<rule class=ghunnah>نّ</rule>َىٰ تُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٩٥',
    95, 7, 2, 140, 113, 56, 'false'
  );
  
  -- Ayah 96 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    885,
    'فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّیۡلَ سَكَنࣰا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانࣰاۚ ذَ ٰ⁠لِكَ تَقۡدِیرُ ٱلۡعَزِیزِ ٱلۡعَلِیمِ',
    'فالق الاصباح وجعل الليل سكنا والشمس والقمر حسبانا ذلك تقدير العزيز العليم',
    'فَالِقُ <rule class=ham_wasl>ٱ</rule>لۡإِصۡبَاحِ وَجَعَلَ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ سَكَ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ حُسۡبَا<rule class=ikhafa>نًا‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ تَ<rule class=qalaqah>قۡ</rule>دِيرُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مِ ٩٦',
    96, 7, 2, 140, 113, 56, 'false'
  );
  
  -- Ayah 97 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    886,
    'وَهُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُوا۟ بِهَا فِی ظُلُمَـٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡلَمُونَ',
    'وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر قد فصلنا الايات لقوم يعلمون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُجُومَ لِتَهۡتَدُو<rule class=slnt>اۡ</rule> بِهَا فِى ظُلُمَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡبَرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ‌ۗ قَ<rule class=qalaqah>دۡ</rule> فَصَّلۡنَا <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٩٧',
    97, 7, 2, 140, 113, 56, 'false'
  );
  
  -- Ayah 98 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    887,
    'وَهُوَ ٱلَّذِیۤ أَنشَأَكُم مِّن نَّفۡسࣲ وَ ٰ⁠حِدَةࣲ فَمُسۡتَقَرࣱّ وَمُسۡتَوۡدَعࣱۗ قَدۡ فَصَّلۡنَا ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَفۡقَهُونَ',
    'وهو الذي انشاكم من نفس واحدة فمستقر ومستودع قد فصلنا الايات لقوم يفقهون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نش</rule>َأَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َمُسۡتَقَ<rule class=idgham_ghunnah>رٌّ</rule> <rule class=idgham_ghunnah>و</rule>َمُسۡتَوۡدَ<rule class=ikhafa>عٌ‌ۗ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> فَصَّلۡنَا <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َفۡقَه<rule class=madda_permissible>ُو</rule>نَ ٩٨',
    98, 7, 2, 140, 113, 56, 'false'
  );
  
  -- Ayah 99 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    888,
    'وَهُوَ ٱلَّذِیۤ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَیۡءࣲ فَأَخۡرَجۡنَا مِنۡهُ خَضِرࣰا نُّخۡرِجُ مِنۡهُ حَبࣰّا مُّتَرَاكِبࣰا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانࣱ دَانِیَةࣱ وَجَنَّـٰتࣲ مِّنۡ أَعۡنَابࣲ وَٱلزَّیۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهࣰا وَغَیۡرَ مُتَشَـٰبِهٍۗ ٱنظُرُوۤا۟ إِلَىٰ ثَمَرِهِۦۤ إِذَاۤ أَثۡمَرَ وَیَنۡعِهِۦۤۚ إِنَّ فِی ذَ ٰ⁠لِكُمۡ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'وهو الذي انزل من السماء ماء فاخرجنا به نبات كل شيء فاخرجنا منه خضرا نخرج منه حبا متراكبا ومن النخل من طلعها قنوان دانية وجنات من اعناب والزيتون والرمان مشتبها وغير متشابه انظروا الى ثمره اذا اثمر وينعه ان في ذلكم لايات لقوم يؤمنون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَخۡرَ<rule class=qalaqah>جۡ</rule>نَا بِه<rule class=madda_normal>ِۦ</rule> نَبَاتَ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َأَخۡرَ<rule class=qalaqah>جۡ</rule>نَا مِنۡهُ خَضِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>ن</rule>ُّخۡرِجُ مِنۡهُ حَب<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ُّتَرَاكِ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َخۡلِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َلۡعِهَا قِنۡوَا<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>د</rule>َانِيَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َجَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَعۡنَا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّيۡتُونَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّ<rule class=ghunnah>مّ</rule>َانَ مُشۡتَبِ<rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule>َغَيۡرَ مُتَشَ<rule class=madda_normal>ـٰ</rule>بِهٍ‌ۗ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ ثَمَرِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَثۡمَرَ وَيَنۡعِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٩٩',
    99, 7, 2, 140, 113, 56, 'false'
  );
  
  -- Ayah 100 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    889,
    'وَجَعَلُوا۟ لِلَّهِ شُرَكَاۤءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُوا۟ لَهُۥ بَنِینَ وَبَنَـٰتِۭ بِغَیۡرِ عِلۡمࣲۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یَصِفُونَ',
    'وجعلوا لله شركاء الجن وخلقهم وخرقوا له بنين وبنات بغير علم سبحانه وتعالى عما يصفون',
    'وَجَعَلُو<rule class=slnt>اۡ</rule> لِلَّهِ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>َ وَخَلَقَهُمۡ‌ۖ وَخَرَقُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> بَنِينَ وَبَنَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>ِغَيۡرِ عِلۡ<rule class=ikhafa>مٍ‌ۚ</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> وَتَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يَصِف<rule class=madda_permissible>ُو</rule>نَ ١٠٠',
    100, 7, 2, 140, 113, 56, 'false'
  );
  
  -- Ayah 101 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    890,
    'بَدِیعُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ أَنَّىٰ یَكُونُ لَهُۥ وَلَدࣱ وَلَمۡ تَكُن لَّهُۥ صَـٰحِبَةࣱۖ وَخَلَقَ كُلَّ شَیۡءࣲۖ وَهُوَ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'بديع السماوات والارض انى يكون له ولد ولم تكن له صاحبة وخلق كل شيء وهو بكل شيء عليم',
    'بَدِيعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ أَ<rule class=ghunnah>نّ</rule>َىٰ يَكُونُ لَهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ تَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> صَ<rule class=madda_normal>ـٰ</rule>حِبَ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َخَلَقَ كُلَّ ش<rule class=idgham_ghunnah>َىۡءٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٠١',
    101, 7, 2, 140, 114, 56, 'false'
  );
  
  -- Ayah 102 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    891,
    'ذَ ٰ⁠لِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ خَـٰلِقُ كُلِّ شَیۡءࣲ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ وَكِیلࣱ',
    'ذلكم الله ربكم لا اله الا هو خالق كل شيء فاعبدوه وهو على كل شيء وكيل',
    'ذ<rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّكُمۡ‌ۖ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۖ خَ<rule class=madda_normal>ـٰ</rule>لِقُ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>عۡبُدُوهُ‌ۚ وَهُوَ عَلَىٰ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َك<rule class=madda_permissible>ِي</rule>لٌ ١٠٢',
    102, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 103 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    892,
    'لَّا تُدۡرِكُهُ ٱلۡأَبۡصَـٰرُ وَهُوَ یُدۡرِكُ ٱلۡأَبۡصَـٰرَۖ وَهُوَ ٱللَّطِیفُ ٱلۡخَبِیرُ',
    'لا تدركه الابصار وهو يدرك الابصار وهو اللطيف الخبير',
    'لَّا تُ<rule class=qalaqah>دۡ</rule>رِكُهُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُ وَهُوَ يُ<rule class=qalaqah>دۡ</rule>رِكُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّطِيفُ <rule class=ham_wasl>ٱ</rule>لۡخَب<rule class=madda_permissible>ِي</rule>رُ ١٠٣',
    103, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 104 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    893,
    'قَدۡ جَاۤءَكُم بَصَاۤىِٕرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِیَ فَعَلَیۡهَاۚ وَمَاۤ أَنَا۠ عَلَیۡكُم بِحَفِیظࣲ',
    'قد جاءكم بصائر من ربكم فمن ابصر فلنفسه ومن عمي فعليها وما انا عليكم بحفيظ',
    'قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َص<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۖ فَمَنۡ أَ<rule class=qalaqah>بۡ</rule>صَرَ فَلِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَنۡ عَمِىَ فَعَلَيۡهَا‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ عَلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِحَف<rule class=madda_permissible>ِي</rule>ظٍ ١٠٤',
    104, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 105 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    894,
    'وَكَذَ ٰ⁠لِكَ نُصَرِّفُ ٱلۡـَٔایَـٰتِ وَلِیَقُولُوا۟ دَرَسۡتَ وَلِنُبَیِّنَهُۥ لِقَوۡمࣲ یَعۡلَمُونَ',
    'وكذلك نصرف الايات وليقولوا درست ولنبينه لقوم يعلمون',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نُصَرِّفُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ وَلِيَقُولُو<rule class=slnt>اۡ</rule> دَرَسۡتَ وَلِنُبَيِّنَهُ<rule class=madda_normal>ۥ</rule> لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٠٥',
    105, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 106 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    895,
    'ٱتَّبِعۡ مَاۤ أُوحِیَ إِلَیۡكَ مِن رَّبِّكَۖ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِینَ',
    'اتبع ما اوحي اليك من ربك لا اله الا هو واعرض عن المشركين',
    'ٱتَّبِعۡ م<rule class=madda_obligatory_monfasel>َآ</rule> أُوحِىَ إِلَيۡكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۖ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۖ وَأَعۡرِضۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١٠٦',
    106, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 107 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    896,
    'وَلَوۡ شَاۤءَ ٱللَّهُ مَاۤ أَشۡرَكُوا۟ۗ وَمَا جَعَلۡنَـٰكَ عَلَیۡهِمۡ حَفِیظࣰاۖ وَمَاۤ أَنتَ عَلَیۡهِم بِوَكِیلࣲ',
    'ولو شاء الله ما اشركوا وما جعلناك عليهم حفيظا وما انت عليهم بوكيل',
    'وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡرَكُو<rule class=slnt>اۡ‌ۗ</rule> وَمَا جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ عَلَيۡهِمۡ حَفِي<rule class=idgham_ghunnah>ظًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِوَك<rule class=madda_permissible>ِي</rule>لٍ ١٠٧',
    107, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 108 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    897,
    'وَلَا تَسُبُّوا۟ ٱلَّذِینَ یَدۡعُونَ مِن دُونِ ٱللَّهِ فَیَسُبُّوا۟ ٱللَّهَ عَدۡوَۢا بِغَیۡرِ عِلۡمࣲۗ كَذَ ٰ⁠لِكَ زَیَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَیُنَبِّئُهُم بِمَا كَانُوا۟ یَعۡمَلُونَ',
    'ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل امة عملهم ثم الى ربهم مرجعهم فينبئهم بما كانوا يعملون',
    'وَلَا تَسُبُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَيَسُبُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ عَ<rule class=qalaqah>دۡ</rule>و<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِغَيۡرِ عِلۡ<rule class=ikhafa>مٍ‌ۗ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ زَيَّ<rule class=ghunnah>نّ</rule>َا لِكُلِّ أُ<rule class=ghunnah>مّ</rule>َةٍ عَمَلَهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ إِلَىٰ رَبِّه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرۡجِعُهُمۡ فَيُنَبِّئُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٠٨',
    108, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 109 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    898,
    'وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَىِٕن جَاۤءَتۡهُمۡ ءَایَةࣱ لَّیُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡـَٔایَـٰتُ عِندَ ٱللَّهِۖ وَمَا یُشۡعِرُكُمۡ أَنَّهَاۤ إِذَا جَاۤءَتۡ لَا یُؤۡمِنُونَ',
    'واقسموا بالله جهد ايمانهم لئن جاءتهم اية ليؤمنن بها قل انما الايات عند الله وما يشعركم انها اذا جاءت لا يؤمنون',
    'وَأَ<rule class=qalaqah>قۡ</rule>سَمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ جَهۡدَ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ لَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ ءَايَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيُؤۡمِنُ<rule class=ghunnah>نّ</rule>َ بِهَا‌ۚ قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَمَا يُشۡعِرُكُمۡ أَ<rule class=ghunnah>نّ</rule>َه<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٠٩',
    109, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 110 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    899,
    'وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَـٰرَهُمۡ كَمَا لَمۡ یُؤۡمِنُوا۟ بِهِۦۤ أَوَّلَ مَرَّةࣲ وَنَذَرُهُمۡ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ',
    'ونقلب افئدتهم وابصارهم كما لم يؤمنوا به اول مرة ونذرهم في طغيانهم يعمهون',
    'وَنُقَلِّبُ أَفۡــِٔدَتَهُمۡ وَأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَهُمۡ كَمَا لَمۡ يُؤۡمِنُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوَّلَ مَرَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َنَذَرُهُمۡ فِى طُغۡيَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ يَعۡمَه<rule class=madda_permissible>ُو</rule>نَ ١١٠',
    110, 7, 2, 141, 114, 56, 'false'
  );
  
  -- Ayah 111 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    900,
    '۞ وَلَوۡ أَنَّنَا نَزَّلۡنَاۤ إِلَیۡهِمُ ٱلۡمَلَـٰۤىِٕكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَیۡهِمۡ كُلَّ شَیۡءࣲ قُبُلࣰا مَّا كَانُوا۟ لِیُؤۡمِنُوۤا۟ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُ وَلَـٰكِنَّ أَكۡثَرَهُمۡ یَجۡهَلُونَ',
    'ولو اننا نزلنا اليهم الملائكة وكلمهم الموتى وحشرنا عليهم كل شيء قبلا ما كانوا ليؤمنوا الا ان يشاء الله ولكن اكثرهم يجهلون',
    '۞وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َنَا نَزَّلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةَ وَكَلَّمَهُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ وَحَشَرۡنَا عَلَيۡهِمۡ كُلَّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>ُبُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> لِيُؤۡمِن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ يَ<rule class=qalaqah>جۡ</rule>هَل<rule class=madda_permissible>ُو</rule>نَ ١١١',
    111, 8, 2, 142, 115, 57, 'false'
  );
  
  -- Ayah 112 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    901,
    'وَكَذَ ٰ⁠لِكَ جَعَلۡنَا لِكُلِّ نَبِیٍّ عَدُوࣰّا شَیَـٰطِینَ ٱلۡإِنسِ وَٱلۡجِنِّ یُوحِی بَعۡضُهُمۡ إِلَىٰ بَعۡضࣲ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورࣰاۚ وَلَوۡ شَاۤءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا یَفۡتَرُونَ',
    'وكذلك جعلنا لكل نبي عدوا شياطين الانس والجن يوحي بعضهم الى بعض زخرف القول غرورا ولو شاء ربك ما فعلوه فذرهم وما يفترون',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ جَعَلۡنَا لِكُلِّ نَبِىٍّ عَدُو<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ش</rule>َيَ<rule class=madda_normal>ـٰ</rule>طِينَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ يُوحِى بَعۡضُهُمۡ إِلَىٰ بَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ز</rule>ُخۡرُفَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ غُرُو<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبُّكَ مَا فَعَلُوهُ‌ۖ فَذَرۡهُمۡ وَمَا يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ١١٢',
    112, 8, 2, 142, 115, 57, 'false'
  );
  
  -- Ayah 113 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    902,
    'وَلِتَصۡغَىٰۤ إِلَیۡهِ أَفۡـِٔدَةُ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ وَلِیَرۡضَوۡهُ وَلِیَقۡتَرِفُوا۟ مَا هُم مُّقۡتَرِفُونَ',
    'ولتصغى اليه افئدة الذين لا يؤمنون بالاخرة وليرضوه وليقترفوا ما هم مقترفون',
    'وَلِتَصۡغَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡهِ أَفۡــِٔدَةُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَلِيَرۡضَوۡهُ وَلِيَ<rule class=qalaqah>قۡ</rule>تَرِفُو<rule class=slnt>اۡ</rule> مَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَرِف<rule class=madda_permissible>ُو</rule>نَ ١١٣',
    113, 8, 2, 142, 115, 57, 'false'
  );
  
  -- Ayah 114 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    903,
    'أَفَغَیۡرَ ٱللَّهِ أَبۡتَغِی حَكَمࣰا وَهُوَ ٱلَّذِیۤ أَنزَلَ إِلَیۡكُمُ ٱلۡكِتَـٰبَ مُفَصَّلࣰاۚ وَٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَعۡلَمُونَ أَنَّهُۥ مُنَزَّلࣱ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِینَ',
    'افغير الله ابتغي حكما وهو الذي انزل اليكم الكتاب مفصلا والذين اتيناهم الكتاب يعلمون انه منزل من ربك بالحق فلا تكونن من الممترين',
    'أَفَغَيۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ أَ<rule class=qalaqah>بۡ</rule>تَغِى حَكَ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلَ إِلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مُفَصَّل<rule class=idgham_ghunnah>اً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يَعۡلَمُونَ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مُنَزَّ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ فَلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُمۡتَر<rule class=madda_permissible>ِي</rule>نَ ١١٤',
    114, 8, 2, 142, 115, 57, 'false'
  );
  
  -- Ayah 115 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    904,
    'وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقࣰا وَعَدۡلࣰاۚ لَّا مُبَدِّلَ لِكَلِمَـٰتِهِۦۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'وتمت كلمت ربك صدقا وعدلا لا مبدل لكلماته وهو السميع العليم',
    'وَتَ<rule class=ghunnah>مّ</rule>َتۡ كَلِمَتُ رَبِّكَ صِ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>و</rule>َعَ<rule class=qalaqah>دۡ</rule>ل<rule class=idgham_wo_ghunnah>اً‌ۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا مُبَدِّلَ لِكَلِمَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ١١٥',
    115, 8, 2, 142, 115, 57, 'false'
  );
  
  -- Ayah 116 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    905,
    'وَإِن تُطِعۡ أَكۡثَرَ مَن فِی ٱلۡأَرۡضِ یُضِلُّوكَ عَن سَبِیلِ ٱللَّهِۚ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا یَخۡرُصُونَ',
    'وان تطع اكثر من في الارض يضلوك عن سبيل الله ان يتبعون الا الظن وان هم الا يخرصون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُطِعۡ أَكۡثَرَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يُضِلُّوكَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّبِعُونَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>َ وَإِنۡ هُمۡ إِلَّا يَخۡرُص<rule class=madda_permissible>ُو</rule>نَ ١١٦',
    116, 8, 2, 142, 115, 57, 'false'
  );
  
  -- Ayah 117 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    906,
    'إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن یَضِلُّ عَن سَبِیلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ',
    'ان ربك هو اعلم من يضل عن سبيله وهو اعلم بالمهتدين',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ أَعۡلَمُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضِلُّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَهُوَ أَعۡلَمُ بِ<rule class=ham_wasl>ٱ</rule>لۡمُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ١١٧',
    117, 8, 2, 142, 115, 57, 'false'
  );
  
  -- Ayah 118 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    907,
    'فَكُلُوا۟ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَیۡهِ إِن كُنتُم بِـَٔایَـٰتِهِۦ مُؤۡمِنِینَ',
    'فكلوا مما ذكر اسم الله عليه ان كنتم باياته مؤمنين',
    'فَكُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا ذُكِرَ <rule class=ham_wasl>ٱ</rule>سۡمُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> مُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١١٨',
    118, 8, 2, 142, 115, 57, 'false'
  );
  
  -- Ayah 119 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    908,
    'وَمَا لَكُمۡ أَلَّا تَأۡكُلُوا۟ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَیۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَیۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَیۡهِۗ وَإِنَّ كَثِیرࣰا لَّیُضِلُّونَ بِأَهۡوَاۤىِٕهِم بِغَیۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِینَ',
    'وما لكم الا تاكلوا مما ذكر اسم الله عليه وقد فصل لكم ما حرم عليكم الا ما اضطررتم اليه وان كثيرا ليضلون باهوائهم بغير علم ان ربك هو اعلم بالمعتدين',
    'وَمَا لَكُمۡ أَلَّا تَأۡكُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا ذُكِرَ <rule class=ham_wasl>ٱ</rule>سۡمُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡهِ وَقَ<rule class=qalaqah>دۡ</rule> فَصَّلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا حَرَّمَ عَلَيۡكُمۡ إِلَّا مَا <rule class=ham_wasl>ٱ</rule>ضۡطُرِرۡتُمۡ إِلَيۡهِ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيُضِلُّونَ بِأَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓئِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِغَيۡرِ عِلۡمٍ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ أَعۡلَمُ بِ<rule class=ham_wasl>ٱ</rule>لۡمُعۡتَد<rule class=madda_permissible>ِي</rule>نَ ١١٩',
    119, 8, 2, 143, 115, 57, 'false'
  );
  
  -- Ayah 120 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    909,
    'وَذَرُوا۟ ظَـٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥۤۚ إِنَّ ٱلَّذِینَ یَكۡسِبُونَ ٱلۡإِثۡمَ سَیُجۡزَوۡنَ بِمَا كَانُوا۟ یَقۡتَرِفُونَ',
    'وذروا ظاهر الاثم وباطنه ان الذين يكسبون الاثم سيجزون بما كانوا يقترفون',
    'وَذَرُو<rule class=slnt>اۡ</rule> ظَ<rule class=madda_normal>ـٰ</rule>هِرَ <rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَبَاطِنَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَكۡسِبُونَ <rule class=ham_wasl>ٱ</rule>لۡإِثۡمَ سَيُ<rule class=qalaqah>جۡ</rule>زَوۡنَ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَ<rule class=qalaqah>قۡ</rule>تَرِف<rule class=madda_permissible>ُو</rule>نَ ١٢٠',
    120, 8, 2, 143, 115, 57, 'false'
  );
  
  -- Ayah 121 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    910,
    'وَلَا تَأۡكُلُوا۟ مِمَّا لَمۡ یُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَیۡهِ وَإِنَّهُۥ لَفِسۡقࣱۗ وَإِنَّ ٱلشَّیَـٰطِینَ لَیُوحُونَ إِلَىٰۤ أَوۡلِیَاۤىِٕهِمۡ لِیُجَـٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ',
    'ولا تاكلوا مما لم يذكر اسم الله عليه وانه لفسق وان الشياطين ليوحون الى اوليائهم ليجادلوكم وان اطعتموهم انكم لمشركون',
    'وَلَا تَأۡكُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا لَمۡ يُذۡكَرِ <rule class=ham_wasl>ٱ</rule>سۡمُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡهِ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَفِسۡ<rule class=idgham_ghunnah>قٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينَ لَيُوحُونَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ لِيُجَ<rule class=madda_normal>ـٰ</rule>دِلُوكُمۡ‌ۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِ<rule class=ghunnah>نّ</rule>َكُمۡ لَمُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ١٢١',
    121, 8, 2, 143, 115, 57, 'false'
  );
  
  -- Ayah 122 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    911,
    'أَوَمَن كَانَ مَیۡتࣰا فَأَحۡیَیۡنَـٰهُ وَجَعَلۡنَا لَهُۥ نُورࣰا یَمۡشِی بِهِۦ فِی ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِی ٱلظُّلُمَـٰتِ لَیۡسَ بِخَارِجࣲ مِّنۡهَاۚ كَذَ ٰ⁠لِكَ زُیِّنَ لِلۡكَـٰفِرِینَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'اومن كان ميتا فاحييناه وجعلنا له نورا يمشي به في الناس كمن مثله في الظلمات ليس بخارج منها كذلك زين للكافرين ما كانوا يعملون',
    'أَوَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مَيۡ<rule class=ikhafa>تًا</rule> <rule class=ikhafa>ف</rule>َأَحۡيَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَجَعَلۡنَا لَهُ<rule class=madda_normal>ۥ</rule> نُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>ي</rule>َمۡشِى بِه<rule class=madda_normal>ِۦ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ كَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّثَلُهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ لَيۡسَ بِخَارِ<rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ زُيِّنَ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٢٢',
    122, 8, 2, 143, 116, 57, 'false'
  );
  
  -- Ayah 123 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    912,
    'وَكَذَ ٰ⁠لِكَ جَعَلۡنَا فِی كُلِّ قَرۡیَةٍ أَكَـٰبِرَ مُجۡرِمِیهَا لِیَمۡكُرُوا۟ فِیهَاۖ وَمَا یَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا یَشۡعُرُونَ',
    'وكذلك جعلنا في كل قرية اكابر مجرميها ليمكروا فيها وما يمكرون الا بانفسهم وما يشعرون',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ جَعَلۡنَا فِى كُلِّ قَرۡيَةٍ أَكَ<rule class=madda_normal>ـٰ</rule>بِرَ مُ<rule class=qalaqah>جۡ</rule>رِمِيهَا لِيَمۡكُرُو<rule class=slnt>اۡ</rule> فِيهَا‌ۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ وَمَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ١٢٣',
    123, 8, 2, 143, 116, 57, 'false'
  );
  
  -- Ayah 124 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    913,
    'وَإِذَا جَاۤءَتۡهُمۡ ءَایَةࣱ قَالُوا۟ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَاۤ أُوتِیَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَیۡثُ یَجۡعَلُ رِسَالَتَهُۥۗ سَیُصِیبُ ٱلَّذِینَ أَجۡرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابࣱ شَدِیدُۢ بِمَا كَانُوا۟ یَمۡكُرُونَ',
    'واذا جاءتهم اية قالوا لن نؤمن حتى نؤتى مثل ما اوتي رسل الله الله اعلم حيث يجعل رسالته سيصيب الذين اجرموا صغار عند الله وعذاب شديد بما كانوا يمكرون',
    'وَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ ءَايَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ م<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِىَ رُسُلُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۘ <rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ حَيۡثُ يَ<rule class=qalaqah>جۡ</rule>عَلُ رِسَالَتَهُ<rule class=madda_normal>ۥ</rule>‌ۗ سَيُصِيبُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَ<rule class=qalaqah>جۡ</rule>رَمُو<rule class=slnt>اۡ</rule> صَغَارٌ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَعَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=iqlab>دُۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَمۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٢٤',
    124, 8, 2, 143, 116, 57, 'false'
  );
  
  -- Ayah 125 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    914,
    'فَمَن یُرِدِ ٱللَّهُ أَن یَهۡدِیَهُۥ یَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَـٰمِۖ وَمَن یُرِدۡ أَن یُضِلَّهُۥ یَجۡعَلۡ صَدۡرَهُۥ ضَیِّقًا حَرَجࣰا كَأَنَّمَا یَصَّعَّدُ فِی ٱلسَّمَاۤءِۚ كَذَ ٰ⁠لِكَ یَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِینَ لَا یُؤۡمِنُونَ',
    'فمن يرد الله ان يهديه يشرح صدره للاسلام ومن يرد ان يضله يجعل صدره ضيقا حرجا كانما يصعد في السماء كذلك يجعل الله الرجس على الذين لا يؤمنون',
    'فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِدِ <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِيَهُ<rule class=madda_normal>ۥ</rule> يَشۡرَحۡ صَ<rule class=qalaqah>دۡ</rule>رَهُ<rule class=madda_normal>ۥ</rule> لِلۡإِسۡلَ<rule class=madda_normal>ـٰ</rule>مِ‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِ<rule class=qalaqah>دۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضِلَّهُ<rule class=madda_normal>ۥ</rule> يَ<rule class=qalaqah>جۡ</rule>عَلۡ صَ<rule class=qalaqah>دۡ</rule>رَهُ<rule class=madda_normal>ۥ</rule> ضَيِّقًا حَرَ<rule class=ikhafa>جًا</rule> <rule class=ikhafa>ك</rule>َأَ<rule class=ghunnah>نّ</rule>َمَا يَصَّعَّدُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَ<rule class=qalaqah>جۡ</rule>عَلُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّ<rule class=qalaqah>جۡ</rule>سَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٢٥',
    125, 8, 2, 144, 116, 57, 'false'
  );
  
  -- Ayah 126 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    915,
    'وَهَـٰذَا صِرَ ٰ⁠طُ رَبِّكَ مُسۡتَقِیمࣰاۗ قَدۡ فَصَّلۡنَا ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَذَّكَّرُونَ',
    'وهذا صراط ربك مستقيما قد فصلنا الايات لقوم يذكرون',
    'وَهَ<rule class=madda_normal>ـٰ</rule>ذَا صِر<rule class=madda_normal>ٰ</rule>طُ رَبِّكَ مُسۡتَقِي<rule class=ikhafa>مًا‌ۗ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> فَصَّلۡنَا <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َذَّكَّر<rule class=madda_permissible>ُو</rule>نَ ١٢٦',
    126, 8, 2, 144, 116, 57, 'false'
  );
  
  -- Ayah 127 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    916,
    '۞ لَهُمۡ دَارُ ٱلسَّلَـٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِیُّهُم بِمَا كَانُوا۟ یَعۡمَلُونَ',
    'لهم دار السلام عند ربهم وهو وليهم بما كانوا يعملون',
    '۞لَهُمۡ دَارُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَ<rule class=madda_normal>ـٰ</rule>مِ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ‌ۖ وَهُوَ وَلِيُّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٢٧',
    127, 8, 2, 144, 116, 58, 'false'
  );
  
  -- Ayah 128 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    917,
    'وَیَوۡمَ یَحۡشُرُهُمۡ جَمِیعࣰا یَـٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِیَاۤؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضࣲ وَبَلَغۡنَاۤ أَجَلَنَا ٱلَّذِیۤ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَـٰلِدِینَ فِیهَاۤ إِلَّا مَا شَاۤءَ ٱللَّهُۗ إِنَّ رَبَّكَ حَكِیمٌ عَلِیمࣱ',
    'ويوم يحشرهم جميعا يا معشر الجن قد استكثرتم من الانس وقال اولياؤهم من الانس ربنا استمتع بعضنا ببعض وبلغنا اجلنا الذي اجلت لنا قال النار مثواكم خالدين فيها الا ما شاء الله ان ربك حكيم عليم',
    'وَيَوۡمَ يَحۡشُرُهُمۡ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_normal>ـٰ</rule>مَعۡشَرَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ قَدِ <rule class=ham_wasl>ٱ</rule>سۡتَكۡثَرۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ‌ۖ وَقَالَ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ رَبَّنَا <rule class=ham_wasl>ٱ</rule>سۡتَمۡتَعَ بَعۡضُنَا بِبَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>و</rule>َبَلَغۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَجَلَنَا <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَجَّلۡتَ لَنَا‌ۚ قَالَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ مَثۡوَ<rule class=madda_normal>ٮٰ</rule>كُمۡ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا مَا ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ حَكِيمٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٢٨',
    128, 8, 2, 144, 116, 58, 'false'
  );
  
  -- Ayah 129 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    918,
    'وَكَذَ ٰ⁠لِكَ نُوَلِّی بَعۡضَ ٱلظَّـٰلِمِینَ بَعۡضَۢا بِمَا كَانُوا۟ یَكۡسِبُونَ',
    'وكذلك نولي بعض الظالمين بعضا بما كانوا يكسبون',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نُوَلِّى بَعۡضَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ بَعۡض<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ١٢٩',
    129, 8, 2, 144, 116, 58, 'false'
  );
  
  -- Ayah 130 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    919,
    'یَـٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ یَأۡتِكُمۡ رُسُلࣱ مِّنكُمۡ یَقُصُّونَ عَلَیۡكُمۡ ءَایَـٰتِی وَیُنذِرُونَكُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَاۚ قَالُوا۟ شَهِدۡنَا عَلَىٰۤ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَشَهِدُوا۟ عَلَىٰۤ أَنفُسِهِمۡ أَنَّهُمۡ كَانُوا۟ كَـٰفِرِینَ',
    'يا معشر الجن والانس الم ياتكم رسل منكم يقصون عليكم اياتي وينذرونكم لقاء يومكم هذا قالوا شهدنا على انفسنا وغرتهم الحياة الدنيا وشهدوا على انفسهم انهم كانوا كافرين',
    'يَ<rule class=madda_normal>ـٰ</rule>مَعۡشَرَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ أَلَمۡ يَأۡتِكُمۡ رُسُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِى وَيُ<rule class=ikhafa>نذ</rule>ِرُونَكُمۡ لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ يَوۡمِكُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۚ قَالُو<rule class=slnt>اۡ</rule> شَهِ<rule class=qalaqah>دۡ</rule>نَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِنَا‌ۖ وَغَرَّتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَشَهِدُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٣٠',
    130, 8, 2, 144, 117, 58, 'false'
  );
  
  -- Ayah 131 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    920,
    'ذَ ٰ⁠لِكَ أَن لَّمۡ یَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمࣲ وَأَهۡلُهَا غَـٰفِلُونَ',
    'ذلك ان لم يكن ربك مهلك القرى بظلم واهلها غافلون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبُّكَ مُهۡلِكَ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ بِظُلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَهۡلُهَا غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ١٣١',
    131, 8, 2, 144, 117, 58, 'false'
  );
  
  -- Ayah 132 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    921,
    'وَلِكُلࣲّ دَرَجَـٰتࣱ مِّمَّا عَمِلُوا۟ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا یَعۡمَلُونَ',
    'ولكل درجات مما عملوا وما ربك بغافل عما يعملون',
    'وَلِكُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>د</rule>َرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا عَمِلُو<rule class=slnt>اۡ‌ۚ</rule> وَمَا رَبُّكَ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٣٢',
    132, 8, 2, 145, 117, 58, 'false'
  );
  
  -- Ayah 133 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    922,
    'وَرَبُّكَ ٱلۡغَنِیُّ ذُو ٱلرَّحۡمَةِۚ إِن یَشَأۡ یُذۡهِبۡكُمۡ وَیَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا یَشَاۤءُ كَمَاۤ أَنشَأَكُم مِّن ذُرِّیَّةِ قَوۡمٍ ءَاخَرِینَ',
    'وربك الغني ذو الرحمة ان يشا يذهبكم ويستخلف من بعدكم ما يشاء كما انشاكم من ذرية قوم اخرين',
    'وَرَبُّكَ <rule class=ham_wasl>ٱ</rule>لۡغَنِىُّ ذُو <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَةِ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َشَأۡ يُذۡهِ<rule class=qalaqah>بۡ</rule>كُمۡ وَيَسۡتَخۡلِفۡ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نش</rule>َأَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُرِّيَّةِ قَوۡمٍ ءَاخَر<rule class=madda_permissible>ِي</rule>نَ ١٣٣',
    133, 8, 2, 145, 117, 58, 'false'
  );
  
  -- Ayah 134 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    923,
    'إِنَّ مَا تُوعَدُونَ لَـَٔاتࣲۖ وَمَاۤ أَنتُم بِمُعۡجِزِینَ',
    'ان ما توعدون لات وما انتم بمعجزين',
    'إِ<rule class=ghunnah>نّ</rule>َ مَا تُوعَدُونَ لَأَ<rule class=idgham_ghunnah>تٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُعۡجِز<rule class=madda_permissible>ِي</rule>نَ ١٣٤',
    134, 8, 2, 145, 117, 58, 'false'
  );
  
  -- Ayah 135 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    924,
    'قُلۡ یَـٰقَوۡمِ ٱعۡمَلُوا۟ عَلَىٰ مَكَانَتِكُمۡ إِنِّی عَامِلࣱۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ',
    'قل يا قوم اعملوا على مكانتكم اني عامل فسوف تعلمون من تكون له عاقبة الدار انه لا يفلح الظالمون',
    'قُلۡ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡمَلُو<rule class=slnt>اۡ</rule> عَلَىٰ مَكَانَتِكُمۡ إِ<rule class=ghunnah>نّ</rule>ِى عَامِ<rule class=ikhafa>لٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َسَوۡفَ تَعۡلَمُونَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونُ لَهُ<rule class=madda_normal>ۥ</rule> عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ١٣٥',
    135, 8, 2, 145, 117, 58, 'false'
  );
  
  -- Ayah 136 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    925,
    'وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَـٰمِ نَصِیبࣰا فَقَالُوا۟ هَـٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَـٰذَا لِشُرَكَاۤىِٕنَاۖ فَمَا كَانَ لِشُرَكَاۤىِٕهِمۡ فَلَا یَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ یَصِلُ إِلَىٰ شُرَكَاۤىِٕهِمۡۗ سَاۤءَ مَا یَحۡكُمُونَ',
    'وجعلوا لله مما ذرا من الحرث والانعام نصيبا فقالوا هذا لله بزعمهم وهذا لشركائنا فما كان لشركائهم فلا يصل الى الله وما كان لله فهو يصل الى شركائهم ساء ما يحكمون',
    'وَجَعَلُو<rule class=slnt>اۡ</rule> لِلَّهِ مِ<rule class=ghunnah>مّ</rule>َا ذَرَأَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَرۡثِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ نَصِي<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َقَالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَ<rule class=madda_normal>ـٰ</rule>ذَا لِشُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنَا‌ۖ فَمَا كَانَ لِشُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ فَلَا يَصِلُ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ‌ۗ س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا يَحۡكُم<rule class=madda_permissible>ُو</rule>نَ ١٣٦',
    136, 8, 2, 145, 117, 58, 'false'
  );
  
  -- Ayah 137 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    926,
    'وَكَذَ ٰ⁠لِكَ زَیَّنَ لِكَثِیرࣲ مِّنَ ٱلۡمُشۡرِكِینَ قَتۡلَ أَوۡلَـٰدِهِمۡ شُرَكَاۤؤُهُمۡ لِیُرۡدُوهُمۡ وَلِیَلۡبِسُوا۟ عَلَیۡهِمۡ دِینَهُمۡۖ وَلَوۡ شَاۤءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا یَفۡتَرُونَ',
    'وكذلك زين لكثير من المشركين قتل اولادهم شركاؤهم ليردوهم وليلبسوا عليهم دينهم ولو شاء الله ما فعلوه فذرهم وما يفترون',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ زَيَّنَ لِكَثِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ قَتۡلَ أَوۡلَ<rule class=madda_normal>ـٰ</rule>دِهِمۡ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ دِينَهُمۡ‌ۖ وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا فَعَلُوهُ‌ۖ فَذَرۡهُمۡ وَمَا يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ١٣٧',
    137, 8, 2, 145, 117, 58, 'false'
  );
  
  -- Ayah 138 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    927,
    'وَقَالُوا۟ هَـٰذِهِۦۤ أَنۡعَـٰمࣱ وَحَرۡثٌ حِجۡرࣱ لَّا یَطۡعَمُهَاۤ إِلَّا مَن نَّشَاۤءُ بِزَعۡمِهِمۡ وَأَنۡعَـٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَـٰمࣱ لَّا یَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَیۡهَا ٱفۡتِرَاۤءً عَلَیۡهِۚ سَیَجۡزِیهِم بِمَا كَانُوا۟ یَفۡتَرُونَ',
    'وقالوا هذه انعام وحرث حجر لا يطعمها الا من نشاء بزعمهم وانعام حرمت ظهورها وانعام لا يذكرون اسم الله عليها افتراء عليه سيجزيهم بما كانوا يفترون',
    'وَقَالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَنۡعَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َحَرۡثٌ حِ<rule class=qalaqah>جۡ</rule><rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَ<rule class=qalaqah>طۡ</rule>عَمُه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بِزَعۡمِهِمۡ وَأَنۡعَ<rule class=madda_normal>ـٰ</rule>مٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَذۡكُرُونَ <rule class=ham_wasl>ٱ</rule>سۡمَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡهَا <rule class=ham_wasl>ٱ</rule>فۡتِر<rule class=madda_obligatory_mottasel>َا</rule>ٓءً عَلَيۡهِ‌ۚ سَيَ<rule class=qalaqah>جۡ</rule>زِيه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ١٣٨',
    138, 8, 2, 146, 117, 58, 'false'
  );
  
  -- Ayah 139 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    928,
    'وَقَالُوا۟ مَا فِی بُطُونِ هَـٰذِهِ ٱلۡأَنۡعَـٰمِ خَالِصَةࣱ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰۤ أَزۡوَ ٰ⁠جِنَاۖ وَإِن یَكُن مَّیۡتَةࣰ فَهُمۡ فِیهِ شُرَكَاۤءُۚ سَیَجۡزِیهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِیمٌ عَلِیمࣱ',
    'وقالوا ما في بطون هذه الانعام خالصة لذكورنا ومحرم على ازواجنا وان يكن ميتة فهم فيه شركاء سيجزيهم وصفهم انه حكيم عليم',
    'وَقَالُو<rule class=slnt>اۡ</rule> مَا فِى بُطُونِ هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ خَالِصَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّذُكُورِنَا وَمُحَرَّمٌ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule>جِنَا‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>َّيۡتَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َهُمۡ فِيهِ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ سَيَ<rule class=qalaqah>جۡ</rule>زِيهِمۡ وَصۡفَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> حَكِيمٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٣٩',
    139, 8, 2, 146, 117, 58, 'false'
  );
  
  -- Ayah 140 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    929,
    'قَدۡ خَسِرَ ٱلَّذِینَ قَتَلُوۤا۟ أَوۡلَـٰدَهُمۡ سَفَهَۢا بِغَیۡرِ عِلۡمࣲ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَاۤءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّوا۟ وَمَا كَانُوا۟ مُهۡتَدِینَ',
    'قد خسر الذين قتلوا اولادهم سفها بغير علم وحرموا ما رزقهم الله افتراء على الله قد ضلوا وما كانوا مهتدين',
    'قَ<rule class=qalaqah>دۡ</rule> خَسِرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَتَل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دَهُمۡ سَفَه<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِغَيۡرِ عِلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َحَرَّمُو<rule class=slnt>اۡ</rule> مَا رَزَقَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>فۡتِر<rule class=madda_obligatory_mottasel>َا</rule>ٓءً عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ قَ<rule class=qalaqah>دۡ</rule> ضَلُّو<rule class=slnt>اۡ</rule> وَمَا كَانُو<rule class=slnt>اۡ</rule> مُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ١٤٠',
    140, 8, 2, 146, 117, 58, 'false'
  );
  
  -- Ayah 141 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    930,
    '۞ وَهُوَ ٱلَّذِیۤ أَنشَأَ جَنَّـٰتࣲ مَّعۡرُوشَـٰتࣲ وَغَیۡرَ مَعۡرُوشَـٰتࣲ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّیۡتُونَ وَٱلرُّمَّانَ مُتَشَـٰبِهࣰا وَغَیۡرَ مُتَشَـٰبِهࣲۚ كُلُوا۟ مِن ثَمَرِهِۦۤ إِذَاۤ أَثۡمَرَ وَءَاتُوا۟ حَقَّهُۥ یَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوۤا۟ۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡمُسۡرِفِینَ',
    'وهو الذي انشا جنات معروشات وغير معروشات والنخل والزرع مختلفا اكله والزيتون والرمان متشابها وغير متشابه كلوا من ثمره اذا اثمر واتوا حقه يوم حصاده ولا تسرفوا انه لا يحب المسرفين',
    '۞وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نش</rule>َأَ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُوشَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َغَيۡرَ مَعۡرُوشَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َخۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّرۡعَ مُخۡتَلِفًا أُكُلُهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّيۡتُونَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّ<rule class=ghunnah>مّ</rule>َانَ مُتَشَ<rule class=madda_normal>ـٰ</rule>بِ<rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule>َغَيۡرَ مُتَشَ<rule class=madda_normal>ـٰ</rule>بِ<rule class=ikhafa>هٍ‌ۚ</rule> <rule class=ikhafa>ك</rule>ُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َمَرِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَثۡمَرَ وَءَاتُو<rule class=slnt>اۡ</rule> حَقَّهُ<rule class=madda_normal>ۥ</rule> يَوۡمَ حَصَادِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَلَا تُسۡرِف<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُسۡرِف<rule class=madda_permissible>ِي</rule>نَ ١٤١',
    141, 8, 2, 146, 118, 59, 'false'
  );
  
  -- Ayah 142 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    931,
    'وَمِنَ ٱلۡأَنۡعَـٰمِ حَمُولَةࣰ وَفَرۡشࣰاۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَ ٰ⁠تِ ٱلشَّیۡطَـٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینࣱ',
    'ومن الانعام حمولة وفرشا كلوا مما رزقكم الله ولا تتبعوا خطوات الشيطان انه لكم عدو مبين',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ حَمُولَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َفَرۡ<rule class=ikhafa>شًا‌ۚ</rule> <rule class=ikhafa>ك</rule>ُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَقَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَا تَتَّبِعُو<rule class=slnt>اۡ</rule> خُطُو<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَكُمۡ عَدُ<rule class=idgham_ghunnah>وٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٤٢',
    142, 8, 2, 146, 118, 59, 'false'
  );
  
  -- Ayah 143 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    932,
    'ثَمَـٰنِیَةَ أَزۡوَ ٰ⁠جࣲۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَیۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَیۡنِۗ قُلۡ ءَاۤلذَّكَرَیۡنِ حَرَّمَ أَمِ ٱلۡأُنثَیَیۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَیۡهِ أَرۡحَامُ ٱلۡأُنثَیَیۡنِۖ نَبِّـُٔونِی بِعِلۡمٍ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ثمانية ازواج من الضان اثنين ومن المعز اثنين قل الذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين نبئوني بعلم ان كنتم صادقين',
    'ثَمَ<rule class=madda_normal>ـٰ</rule>نِيَةَ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جٍ‌ۖ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّأۡنِ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡمَعۡزِ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ‌ۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َيَيۡنِ أَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>شۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َيَيۡنِ‌ۖ نَبِّــُٔونِى بِعِلۡمٍ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٤٣',
    143, 8, 2, 147, 118, 59, 'false'
  );
  
  -- Ayah 144 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    933,
    'وَمِنَ ٱلۡإِبِلِ ٱثۡنَیۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَیۡنِۗ قُلۡ ءَاۤلذَّكَرَیۡنِ حَرَّمَ أَمِ ٱلۡأُنثَیَیۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَیۡهِ أَرۡحَامُ ٱلۡأُنثَیَیۡنِۖ أَمۡ كُنتُمۡ شُهَدَاۤءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَـٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰا لِّیُضِلَّ ٱلنَّاسَ بِغَیۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'ومن الابل اثنين ومن البقر اثنين قل الذكرين حرم ام الانثيين اما اشتملت عليه ارحام الانثيين ام كنتم شهداء اذ وصاكم الله بهذا فمن اظلم ممن افترى على الله كذبا ليضل الناس بغير علم ان الله لا يهدي القوم الظالمين',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡإِبِلِ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡبَقَرِ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ‌ۗ قُلۡ ءَآلذَّكَرَيۡنِ حَرَّمَ أَمِ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َيَيۡنِ أَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>شۡتَمَلَتۡ عَلَيۡهِ أَرۡحَامُ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َيَيۡنِ‌ۖ أَمۡ كُ<rule class=ikhafa>نت</rule>ُمۡ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِذۡ وَصَّ<rule class=madda_normal>ـٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِهَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۚ فَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِ<rule class=idgham_wo_ghunnah>بًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُضِلَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ بِغَيۡرِ عِلۡمٍ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٤٤',
    144, 8, 2, 147, 118, 59, 'false'
  );
  
  -- Ayah 145 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    934,
    'قُل لَّاۤ أَجِدُ فِی مَاۤ أُوحِیَ إِلَیَّ مُحَرَّمًا عَلَىٰ طَاعِمࣲ یَطۡعَمُهُۥۤ إِلَّاۤ أَن یَكُونَ مَیۡتَةً أَوۡ دَمࣰا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِیرࣲ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَیۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَیۡرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ رَبَّكَ غَفُورࣱ رَّحِیمࣱ',
    'قل لا اجد في ما اوحي الي محرما على طاعم يطعمه الا ان يكون ميتة او دما مسفوحا او لحم خنزير فانه رجس او فسقا اهل لغير الله به فمن اضطر غير باغ ولا عاد فان ربك غفور رحيم',
    'قُل لّ<rule class=madda_obligatory_monfasel>َآ</rule> أَجِدُ فِى م<rule class=madda_obligatory_monfasel>َآ</rule> أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>طۡ</rule>عَمُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ مَيۡتَةً أَوۡ دَ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّسۡفُوحًا أَوۡ لَحۡمَ خِ<rule class=ikhafa>نز</rule>ِي<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> رِ<rule class=qalaqah>جۡ</rule>سٌ أَوۡ فِسۡقًا أُهِلَّ لِغَيۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِه<rule class=madda_normal>ِۦ</rule>‌ۚ فَمَنِ <rule class=ham_wasl>ٱ</rule>ضۡطُرَّ غَيۡرَ بَا<rule class=idgham_ghunnah>غٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا عَا<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٤٥',
    145, 8, 2, 147, 119, 59, 'false'
  );
  
  -- Ayah 146 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    935,
    'وَعَلَى ٱلَّذِینَ هَادُوا۟ حَرَّمۡنَا كُلَّ ذِی ظُفُرࣲۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَیۡهِمۡ شُحُومَهُمَاۤ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَاۤ أَوِ ٱلۡحَوَایَاۤ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمࣲۚ ذَ ٰ⁠لِكَ جَزَیۡنَـٰهُم بِبَغۡیِهِمۡۖ وَإِنَّا لَصَـٰدِقُونَ',
    'وعلى الذين هادوا حرمنا كل ذي ظفر ومن البقر والغنم حرمنا عليهم شحومهما الا ما حملت ظهورهما او الحوايا او ما اختلط بعظم ذلك جزيناهم ببغيهم وانا لصادقون',
    'وَعَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَادُو<rule class=slnt>اۡ</rule> حَرَّمۡنَا كُلَّ ذِى ظُفُ<rule class=idgham_ghunnah>رٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule>لۡبَقَرِ وَ<rule class=ham_wasl>ٱ</rule>لۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا مَا حَمَلَتۡ ظُهُورُهُم<rule class=madda_obligatory_monfasel>َآ</rule> أَوِ <rule class=ham_wasl>ٱ</rule>لۡحَوَاي<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ مَا <rule class=ham_wasl>ٱ</rule>خۡتَلَطَ بِعَظۡ<rule class=ikhafa>مٍ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ جَزَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَغۡيِهِمۡ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َا لَصَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ُو</rule>نَ ١٤٦',
    146, 8, 2, 147, 119, 59, 'false'
  );
  
  -- Ayah 147 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    936,
    'فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةࣲ وَ ٰ⁠سِعَةࣲ وَلَا یُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِینَ',
    'فان كذبوك فقل ربكم ذو رحمة واسعة ولا يرد باسه عن القوم المجرمين',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبُوكَ فَقُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبُّكُمۡ ذُو رَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>سِعَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُرَدُّ بَأۡسُهُ<rule class=madda_normal>ۥ</rule> عَنِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ١٤٧',
    147, 8, 2, 148, 119, 59, 'false'
  );
  
  -- Ayah 148 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    937,
    'سَیَقُولُ ٱلَّذِینَ أَشۡرَكُوا۟ لَوۡ شَاۤءَ ٱللَّهُ مَاۤ أَشۡرَكۡنَا وَلَاۤ ءَابَاۤؤُنَا وَلَا حَرَّمۡنَا مِن شَیۡءࣲۚ كَذَ ٰ⁠لِكَ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُوا۟ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمࣲ فَتُخۡرِجُوهُ لَنَاۤۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ',
    'سيقول الذين اشركوا لو شاء الله ما اشركنا ولا اباؤنا ولا حرمنا من شيء كذلك كذب الذين من قبلهم حتى ذاقوا باسنا قل هل عندكم من علم فتخرجوه لنا ان تتبعون الا الظن وان انتم الا تخرصون',
    'سَيَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَشۡرَكُو<rule class=slnt>اۡ</rule> لَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡرَكۡنَا وَل<rule class=madda_obligatory_monfasel>َآ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا وَلَا حَرَّمۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ كَذَّبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ حَتَّىٰ ذَاقُو<rule class=slnt>اۡ</rule> بَأۡسَنَا‌ۗ قُلۡ هَلۡ عِ<rule class=ikhafa>ند</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عِلۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ف</rule>َتُخۡرِجُوهُ لَن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَّبِعُونَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>َ وَإِنۡ أَ<rule class=ikhafa>نت</rule>ُمۡ إِلَّا تَخۡرُص<rule class=madda_permissible>ُو</rule>نَ ١٤٨',
    148, 8, 2, 148, 119, 59, 'false'
  );
  
  -- Ayah 149 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    938,
    'قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَـٰلِغَةُۖ فَلَوۡ شَاۤءَ لَهَدَىٰكُمۡ أَجۡمَعِینَ',
    'قل فلله الحجة البالغة فلو شاء لهداكم اجمعين',
    'قُلۡ فَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡحُجَّةُ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>لِغَةُ‌ۖ فَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لَهَدَ<rule class=madda_normal>ٮٰ</rule>كُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ١٤٩',
    149, 8, 2, 148, 119, 59, 'false'
  );
  
  -- Ayah 150 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    939,
    'قُلۡ هَلُمَّ شُهَدَاۤءَكُمُ ٱلَّذِینَ یَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَـٰذَاۖ فَإِن شَهِدُوا۟ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَاۤءَ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ وَهُم بِرَبِّهِمۡ یَعۡدِلُونَ',
    'قل هلم شهداءكم الذين يشهدون ان الله حرم هذا فان شهدوا فلا تشهد معهم ولا تتبع اهواء الذين كذبوا باياتنا والذين لا يؤمنون بالاخرة وهم بربهم يعدلون',
    'قُلۡ هَلُ<rule class=ghunnah>مّ</rule>َ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَشۡهَدُونَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ حَرَّمَ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َهِدُو<rule class=slnt>اۡ</rule> فَلَا تَشۡهَ<rule class=qalaqah>دۡ</rule> مَعَهُمۡ‌ۚ وَلَا تَتَّبِعۡ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرَبِّهِمۡ يَعۡدِل<rule class=madda_permissible>ُو</rule>نَ ١٥٠',
    150, 8, 2, 148, 119, 59, 'false'
  );
  
  -- Ayah 151 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    940,
    '۞ قُلۡ تَعَالَوۡا۟ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَیۡكُمۡۖ أَلَّا تُشۡرِكُوا۟ بِهِۦ شَیۡـࣰٔاۖ وَبِٱلۡوَ ٰ⁠لِدَیۡنِ إِحۡسَـٰنࣰاۖ وَلَا تَقۡتُلُوۤا۟ أَوۡلَـٰدَكُم مِّنۡ إِمۡلَـٰقࣲ نَّحۡنُ نَرۡزُقُكُمۡ وَإِیَّاهُمۡۖ وَلَا تَقۡرَبُوا۟ ٱلۡفَوَ ٰ⁠حِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُوا۟ ٱلنَّفۡسَ ٱلَّتِی حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَ ٰ⁠لِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ',
    'قل تعالوا اتل ما حرم ربكم عليكم الا تشركوا به شيئا وبالوالدين احسانا ولا تقتلوا اولادكم من املاق نحن نرزقكم واياهم ولا تقربوا الفواحش ما ظهر منها وما بطن ولا تقتلوا النفس التي حرم الله الا بالحق ذلكم وصاكم به لعلكم تعقلون',
    '۞قُلۡ تَعَالَوۡ<rule class=slnt>اۡ</rule> أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡ‌ۖ أَلَّا تُشۡرِكُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َبِ<rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِدَيۡنِ إِحۡسَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَ<rule class=qalaqah>قۡ</rule>تُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِمۡلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>قٍ‌ۖ</rule> <rule class=idgham_ghunnah>ن</rule>َّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡ‌ۖ وَلَا تَ<rule class=qalaqah>قۡ</rule>رَبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡفَو<rule class=madda_normal>ٰ</rule>حِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ‌ۖ وَلَا تَ<rule class=qalaqah>قۡ</rule>تُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َفۡسَ <rule class=ham_wasl>ٱ</rule>لَّتِى حَرَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ وَصَّ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> لَعَلَّكُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٥١',
    151, 8, 2, 148, 120, 60, 'false'
  );
  
  -- Ayah 152 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    941,
    'وَلَا تَقۡرَبُوا۟ مَالَ ٱلۡیَتِیمِ إِلَّا بِٱلَّتِی هِیَ أَحۡسَنُ حَتَّىٰ یَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُوا۟ ٱلۡكَیۡلَ وَٱلۡمِیزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُوا۟ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُوا۟ۚ ذَ ٰ⁠لِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ',
    'ولا تقربوا مال اليتيم الا بالتي هي احسن حتى يبلغ اشده واوفوا الكيل والميزان بالقسط لا نكلف نفسا الا وسعها واذا قلتم فاعدلوا ولو كان ذا قربى وبعهد الله اوفوا ذلكم وصاكم به لعلكم تذكرون',
    'وَلَا تَ<rule class=qalaqah>قۡ</rule>رَبُو<rule class=slnt>اۡ</rule> مَالَ <rule class=ham_wasl>ٱ</rule>لۡيَتِيمِ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لَّتِى هِىَ أَحۡسَنُ حَتَّىٰ يَ<rule class=qalaqah>بۡ</rule>لُغَ أَشُدَّهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَأَوۡفُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكَيۡلَ وَ<rule class=ham_wasl>ٱ</rule>لۡمِيزَانَ بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَا‌ۖ وَإِذَا قُلۡتُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡدِلُو<rule class=slnt>اۡ</rule> وَلَوۡ كَانَ ذَا قُرۡبَىٰ‌ۖ وَبِعَهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡفُو<rule class=slnt>اۡ‌ۚ</rule> ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ وَصَّ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> لَعَلَّكُمۡ تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ١٥٢',
    152, 8, 2, 149, 120, 60, 'false'
  );
  
  -- Ayah 153 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    942,
    'وَأَنَّ هَـٰذَا صِرَ ٰ⁠طِی مُسۡتَقِیمࣰا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِیلِهِۦۚ ذَ ٰ⁠لِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ',
    'وان هذا صراطي مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصاكم به لعلكم تتقون',
    'وَأَ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا صِر<rule class=madda_normal>ٰ</rule>طِى مُسۡتَقِي<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>تَّبِعُوهُ‌ۖ وَلَا تَتَّبِعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّبُلَ فَتَفَرَّقَ بِكُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِه<rule class=madda_normal>ِۦ</rule>‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ وَصَّ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> لَعَلَّكُمۡ تَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٥٣',
    153, 8, 2, 149, 120, 60, 'false'
  );
  
  -- Ayah 154 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    943,
    'ثُمَّ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ تَمَامًا عَلَى ٱلَّذِیۤ أَحۡسَنَ وَتَفۡصِیلࣰا لِّكُلِّ شَیۡءࣲ وَهُدࣰى وَرَحۡمَةࣰ لَّعَلَّهُم بِلِقَاۤءِ رَبِّهِمۡ یُؤۡمِنُونَ',
    'ثم اتينا موسى الكتاب تماما على الذي احسن وتفصيلا لكل شيء وهدى ورحمة لعلهم بلقاء ربهم يؤمنون',
    'ثُ<rule class=ghunnah>مّ</rule>َ ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ تَمَامًا عَلَى <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡسَنَ وَتَفۡصِيل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رَبِّهِمۡ يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٥٤',
    154, 8, 2, 149, 120, 60, 'false'
  );
  
  -- Ayah 155 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    944,
    'وَهَـٰذَا كِتَـٰبٌ أَنزَلۡنَـٰهُ مُبَارَكࣱ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمۡ تُرۡحَمُونَ',
    'وهذا كتاب انزلناه مبارك فاتبعوه واتقوا لعلكم ترحمون',
    'وَهَ<rule class=madda_normal>ـٰ</rule>ذَا كِتَ<rule class=madda_normal>ـٰ</rule>بٌ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ مُبَارَ<rule class=ikhafa>كٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>تَّبِعُوهُ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> لَعَلَّكُمۡ تُرۡحَم<rule class=madda_permissible>ُو</rule>نَ ١٥٥',
    155, 8, 2, 149, 121, 60, 'false'
  );
  
  -- Ayah 156 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    945,
    'أَن تَقُولُوۤا۟ إِنَّمَاۤ أُنزِلَ ٱلۡكِتَـٰبُ عَلَىٰ طَاۤىِٕفَتَیۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَـٰفِلِینَ',
    'ان تقولوا انما انزل الكتاب على طائفتين من قبلنا وان كنا عن دراستهم لغافلين',
    'أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُول<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بُ عَلَىٰ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَتَيۡنِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِنَا وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِرَاسَتِهِمۡ لَغَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ١٥٦',
    156, 8, 2, 149, 121, 60, 'false'
  );
  
  -- Ayah 157 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    946,
    'أَوۡ تَقُولُوا۟ لَوۡ أَنَّاۤ أُنزِلَ عَلَیۡنَا ٱلۡكِتَـٰبُ لَكُنَّاۤ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَاۤءَكُم بَیِّنَةࣱ مِّن رَّبِّكُمۡ وَهُدࣰى وَرَحۡمَةࣱۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔایَـٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِی ٱلَّذِینَ یَصۡدِفُونَ عَنۡ ءَایَـٰتِنَا سُوۤءَ ٱلۡعَذَابِ بِمَا كَانُوا۟ یَصۡدِفُونَ',
    'او تقولوا لو انا انزل علينا الكتاب لكنا اهدى منهم فقد جاءكم بينة من ربكم وهدى ورحمة فمن اظلم ممن كذب بايات الله وصدف عنها سنجزي الذين يصدفون عن اياتنا سوء العذاب بما كانوا يصدفون',
    'أَوۡ تَقُولُو<rule class=slnt>اۡ</rule> لَوۡ أَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡنَا <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بُ لَكُ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَهۡدَىٰ مِنۡهُمۡ‌ۚ فَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيِّنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=ikhafa>ةٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَصَدَفَ عَنۡهَا‌ۗ سَنَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَصۡدِفُونَ عَنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَصۡدِف<rule class=madda_permissible>ُو</rule>نَ ١٥٧',
    157, 8, 2, 149, 121, 60, 'false'
  );
  
  -- Ayah 158 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    947,
    'هَلۡ یَنظُرُونَ إِلَّاۤ أَن تَأۡتِیَهُمُ ٱلۡمَلَـٰۤىِٕكَةُ أَوۡ یَأۡتِیَ رَبُّكَ أَوۡ یَأۡتِیَ بَعۡضُ ءَایَـٰتِ رَبِّكَۗ یَوۡمَ یَأۡتِی بَعۡضُ ءَایَـٰتِ رَبِّكَ لَا یَنفَعُ نَفۡسًا إِیمَـٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِیۤ إِیمَـٰنِهَا خَیۡرࣰاۗ قُلِ ٱنتَظِرُوۤا۟ إِنَّا مُنتَظِرُونَ',
    'هل ينظرون الا ان تاتيهم الملائكة او ياتي ربك او ياتي بعض ايات ربك يوم ياتي بعض ايات ربك لا ينفع نفسا ايمانها لم تكن امنت من قبل او كسبت في ايمانها خيرا قل انتظروا انا منتظرون',
    'هَلۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ أَوۡ يَأۡتِىَ رَبُّكَ أَوۡ يَأۡتِىَ بَعۡضُ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّكَ‌ۗ يَوۡمَ يَأۡتِى بَعۡضُ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّكَ لَا يَ<rule class=ikhafa>نف</rule>َعُ نَفۡسًا إِيمَ<rule class=madda_normal>ـٰ</rule>نُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ أَوۡ كَسَبَتۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِيمَ<rule class=madda_normal>ـٰ</rule>نِهَا خَيۡ<rule class=ikhafa>رًا‌ۗ</rule> <rule class=ikhafa>ق</rule>ُلِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َظِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا مُ<rule class=ikhafa>نت</rule>َظِر<rule class=madda_permissible>ُو</rule>نَ ١٥٨',
    158, 8, 2, 150, 121, 60, 'false'
  );
  
  -- Ayah 159 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    948,
    'إِنَّ ٱلَّذِینَ فَرَّقُوا۟ دِینَهُمۡ وَكَانُوا۟ شِیَعࣰا لَّسۡتَ مِنۡهُمۡ فِی شَیۡءٍۚ إِنَّمَاۤ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ یُنَبِّئُهُم بِمَا كَانُوا۟ یَفۡعَلُونَ',
    'ان الذين فرقوا دينهم وكانوا شيعا لست منهم في شيء انما امرهم الى الله ثم ينبئهم بما كانوا يفعلون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ فَرَّقُو<rule class=slnt>اۡ</rule> دِينَهُمۡ وَكَانُو<rule class=slnt>اۡ</rule> شِيَ<rule class=idgham_wo_ghunnah>عًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّسۡتَ مِنۡهُمۡ فِى شَىۡءٍ‌ۚ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡرُهُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ يُنَبِّئُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ١٥٩',
    159, 8, 2, 150, 121, 60, 'false'
  );
  
  -- Ayah 160 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    949,
    'مَن جَاۤءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَاۤءَ بِٱلسَّیِّئَةِ فَلَا یُجۡزَىٰۤ إِلَّا مِثۡلَهَا وَهُمۡ لَا یُظۡلَمُونَ',
    'من جاء بالحسنة فله عشر امثالها ومن جاء بالسيئة فلا يجزى الا مثلها وهم لا يظلمون',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَسَنَةِ فَلَهُ<rule class=madda_normal>ۥ</rule> عَشۡرُ أَمۡثَالِهَا‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةِ فَلَا يُ<rule class=qalaqah>جۡ</rule>زَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَّا مِثۡلَهَا وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٦٠',
    160, 8, 2, 150, 121, 60, 'false'
  );
  
  -- Ayah 161 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    950,
    'قُلۡ إِنَّنِی هَدَىٰنِی رَبِّیۤ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ دِینࣰا قِیَمࣰا مِّلَّةَ إِبۡرَ ٰ⁠هِیمَ حَنِیفࣰاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ',
    'قل انني هداني ربي الى صراط مستقيم دينا قيما ملة ابراهيم حنيفا وما كان من المشركين',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َنِى هَدَ<rule class=madda_normal>ٮٰ</rule>نِى رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقِي<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>د</rule>ِي<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>ِيَ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ِّلَّةَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ حَنِي<rule class=idgham_ghunnah>فًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١٦١',
    161, 8, 2, 150, 121, 60, 'false'
  );
  
  -- Ayah 162 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    951,
    'قُلۡ إِنَّ صَلَاتِی وَنُسُكِی وَمَحۡیَایَ وَمَمَاتِی لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'قل ان صلاتي ونسكي ومحياي ومماتي لله رب العالمين',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َ صَلَاتِى وَنُسُكِى وَمَحۡيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٦٢',
    162, 8, 2, 150, 121, 60, 'false'
  );
  
  -- Ayah 163 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    952,
    'لَا شَرِیكَ لَهُۥۖ وَبِذَ ٰ⁠لِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِینَ',
    'لا شريك له وبذلك امرت وانا اول المسلمين',
    'لَا شَرِيكَ لَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَبِذ<rule class=madda_normal>ٰ</rule>لِكَ أُمِرۡتُ وَأَنَاۡ أَوَّلُ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ١٦٣',
    163, 8, 2, 150, 121, 60, 'false'
  );
  
  -- Ayah 164 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    953,
    'قُلۡ أَغَیۡرَ ٱللَّهِ أَبۡغِی رَبࣰّا وَهُوَ رَبُّ كُلِّ شَیۡءࣲۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَیۡهَاۚ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَیُنَبِّئُكُم بِمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ',
    'قل اغير الله ابغي ربا وهو رب كل شيء ولا تكسب كل نفس الا عليها ولا تزر وازرة وزر اخرى ثم الى ربكم مرجعكم فينبئكم بما كنتم فيه تختلفون',
    'قُلۡ أَغَيۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ أَ<rule class=qalaqah>بۡ</rule>غِى رَب<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ رَبُّ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَا‌ۚ وَلَا تَزِرُ وَازِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>ِزۡرَ أُخۡرَىٰ‌ۚ ثُ<rule class=ghunnah>مّ</rule>َ إِلَىٰ رَبِّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرۡجِعُكُمۡ فَيُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ فِيهِ تَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ١٦٤',
    164, 8, 2, 150, 121, 60, 'false'
  );
  
  -- Ayah 165 Surah Al-Anaam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    6,
    954,
    'وَهُوَ ٱلَّذِی جَعَلَكُمۡ خَلَـٰۤىِٕفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضࣲ دَرَجَـٰتࣲ لِّیَبۡلُوَكُمۡ فِی مَاۤ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِیعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورࣱ رَّحِیمُۢ',
    'وهو الذي جعلكم خلائف الارض ورفع بعضكم فوق بعض درجات ليبلوكم في ما اتاكم ان ربك سريع العقاب وانه لغفور رحيم',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَكُمۡ خَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِفَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>د</rule>َرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَ<rule class=qalaqah>بۡ</rule>لُوَكُمۡ فِى م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡعِقَابِ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَغَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مُۢ ١٦٥',
    165, 8, 2, 150, 121, 60, 'false'
  );
  

-- Surah Al-Araaf
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (7, 'سُورَةُ الأَعۡرَافِ', 'Al-Araaf', 'The Heights', 'Meccan', 206);

  -- Ayah 1 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    955,
    'الۤمۤصۤ',
    'المص',
    'ا<rule class=madda_necessary>لٓ</rule><rule class=madda_necessary>مٓ</rule><rule class=madda_necessary>صٓ</rule> ١',
    1, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 2 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    956,
    'كِتَـٰبٌ أُنزِلَ إِلَیۡكَ فَلَا یَكُن فِی صَدۡرِكَ حَرَجࣱ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِینَ',
    'كتاب انزل اليك فلا يكن في صدرك حرج منه لتنذر به وذكرى للمؤمنين',
    'كِتَ<rule class=madda_normal>ـٰ</rule>بٌ أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ فَلَا يَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى صَ<rule class=qalaqah>دۡ</rule>رِكَ حَرَ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ لِتُ<rule class=ikhafa>نذ</rule>ِرَ بِه<rule class=madda_normal>ِۦ</rule> وَذِكۡرَىٰ لِلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 3 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    957,
    'ٱتَّبِعُوا۟ مَاۤ أُنزِلَ إِلَیۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦۤ أَوۡلِیَاۤءَۗ قَلِیلࣰا مَّا تَذَكَّرُونَ',
    'اتبعوا ما انزل اليكم من ربكم ولا تتبعوا من دونه اولياء قليلا ما تذكرون',
    'ٱتَّبِعُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَلَا تَتَّبِعُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۗ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 4 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    958,
    'وَكَم مِّن قَرۡیَةٍ أَهۡلَكۡنَـٰهَا فَجَاۤءَهَا بَأۡسُنَا بَیَـٰتًا أَوۡ هُمۡ قَاۤىِٕلُونَ',
    'وكم من قرية اهلكناها فجاءها باسنا بياتا او هم قائلون',
    'وَك<rule class=idgham_shafawi>َم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ أَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>هَا فَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهَا بَأۡسُنَا بَيَ<rule class=madda_normal>ـٰ</rule>تًا أَوۡ هُمۡ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِل<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 5 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    959,
    'فَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَاۤءَهُم بَأۡسُنَاۤ إِلَّاۤ أَن قَالُوۤا۟ إِنَّا كُنَّا ظَـٰلِمِینَ',
    'فما كان دعواهم اذ جاءهم باسنا الا ان قالوا انا كنا ظالمين',
    'فَمَا كَانَ دَعۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َأۡسُن<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 6 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    960,
    'فَلَنَسۡـَٔلَنَّ ٱلَّذِینَ أُرۡسِلَ إِلَیۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِینَ',
    'فلنسالن الذين ارسل اليهم ولنسالن المرسلين',
    'فَلَنَسۡــَٔلَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡــَٔلَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 7 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    961,
    'فَلَنَقُصَّنَّ عَلَیۡهِم بِعِلۡمࣲۖ وَمَا كُنَّا غَاۤىِٕبِینَ',
    'فلنقصن عليهم بعلم وما كنا غائبين',
    'فَلَنَقُصَّ<rule class=ghunnah>نّ</rule>َ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِعِلۡ<rule class=idgham_ghunnah>مٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كُ<rule class=ghunnah>نّ</rule>َا غ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِب<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 8 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    962,
    'وَٱلۡوَزۡنُ یَوۡمَىِٕذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَ ٰ⁠زِینُهُۥ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'والوزن يومئذ الحق فمن ثقلت موازينه فاولئك هم المفلحون',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡوَزۡنُ يَوۡمَئِذٍ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۚ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َقُلَتۡ مَو<rule class=madda_normal>ٰ</rule>زِينُهُ<rule class=madda_normal>ۥ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 9 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    963,
    'وَمَنۡ خَفَّتۡ مَوَ ٰ⁠زِینُهُۥ فَأُو۟لَـٰۤىِٕكَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔایَـٰتِنَا یَظۡلِمُونَ',
    'ومن خفت موازينه فاولئك الذين خسروا انفسهم بما كانوا باياتنا يظلمون',
    'وَمَنۡ خَفَّتۡ مَو<rule class=madda_normal>ٰ</rule>زِينُهُ<rule class=madda_normal>ۥ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَسِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 10 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    964,
    'وَلَقَدۡ مَكَّنَّـٰكُمۡ فِی ٱلۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِیهَا مَعَـٰیِشَۗ قَلِیلࣰا مَّا تَشۡكُرُونَ',
    'ولقد مكناكم في الارض وجعلنا لكم فيها معايش قليلا ما تشكرون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> مَكَّ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>كُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَ<rule class=madda_normal>ـٰ</rule>يِشَ‌ۗ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 8, 2, 151, 122, 61, 'false'
  );
  
  -- Ayah 11 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    965,
    'وَلَقَدۡ خَلَقۡنَـٰكُمۡ ثُمَّ صَوَّرۡنَـٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ لَمۡ یَكُن مِّنَ ٱلسَّـٰجِدِینَ',
    'ولقد خلقناكم ثم صورناكم ثم قلنا للملائكة اسجدوا لادم فسجدوا الا ابليس لم يكن من الساجدين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ ثُ<rule class=ghunnah>مّ</rule>َ صَوَّرۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ ثُ<rule class=ghunnah>مّ</rule>َ قُلۡنَا لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ <rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> لِأَدَمَ فَسَجَد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>لِيسَ لَمۡ يَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 8, 2, 151, 123, 61, 'false'
  );
  
  -- Ayah 12 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    966,
    'قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَیۡرࣱ مِّنۡهُ خَلَقۡتَنِی مِن نَّارࣲ وَخَلَقۡتَهُۥ مِن طِینࣲ',
    'قال ما منعك الا تسجد اذ امرتك قال انا خير منه خلقتني من نار وخلقته من طين',
    'قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَ‌ۖ قَالَ أَنَاۡ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ خَلَ<rule class=qalaqah>قۡ</rule>تَنِى م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّا<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َخَلَ<rule class=qalaqah>قۡ</rule>تَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule><rule class=madda_permissible>ِي</rule>نٍ ١٢',
    12, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 13 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    967,
    'قَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا یَكُونُ لَكَ أَن تَتَكَبَّرَ فِیهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّـٰغِرِینَ',
    'قال فاهبط منها فما يكون لك ان تتكبر فيها فاخرج انك من الصاغرين',
    'قَالَ فَ<rule class=ham_wasl>ٱ</rule>هۡبِ<rule class=qalaqah>طۡ</rule> مِنۡهَا فَمَا يَكُونُ لَكَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَكَبَّرَ فِيهَا فَ<rule class=ham_wasl>ٱ</rule>خۡرُ<rule class=qalaqah>جۡ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>غِر<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 14 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    968,
    'قَالَ أَنظِرۡنِیۤ إِلَىٰ یَوۡمِ یُبۡعَثُونَ',
    'قال انظرني الى يوم يبعثون',
    'قَالَ أَ<rule class=ikhafa>نظ</rule>ِرۡن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ يَوۡمِ يُ<rule class=qalaqah>بۡ</rule>عَث<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 15 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    969,
    'قَالَ إِنَّكَ مِنَ ٱلۡمُنظَرِینَ',
    'قال انك من المنظرين',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ِي</rule>نَ ١٥',
    15, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 16 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    970,
    'قَالَ فَبِمَاۤ أَغۡوَیۡتَنِی لَأَقۡعُدَنَّ لَهُمۡ صِرَ ٰ⁠طَكَ ٱلۡمُسۡتَقِیمَ',
    'قال فبما اغويتني لاقعدن لهم صراطك المستقيم',
    'قَالَ فَبِم<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡوَيۡتَنِى لَأَ<rule class=qalaqah>قۡ</rule>عُدَ<rule class=ghunnah>نّ</rule>َ لَهُمۡ صِر<rule class=madda_normal>ٰ</rule>طَكَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَق<rule class=madda_permissible>ِي</rule>مَ ١٦',
    16, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 17 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    971,
    'ثُمَّ لَـَٔاتِیَنَّهُم مِّنۢ بَیۡنِ أَیۡدِیهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَیۡمَـٰنِهِمۡ وَعَن شَمَاۤىِٕلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَـٰكِرِینَ',
    'ثم لاتينهم من بين ايديهم ومن خلفهم وعن ايمانهم وعن شمائلهم ولا تجد اكثرهم شاكرين',
    'ثُ<rule class=ghunnah>مّ</rule>َ لَأَتِيَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ وَعَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َم<rule class=madda_obligatory_mottasel>َا</rule>ٓئِلِهِمۡ‌ۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 18 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    972,
    'قَالَ ٱخۡرُجۡ مِنۡهَا مَذۡءُومࣰا مَّدۡحُورࣰاۖ لَّمَن تَبِعَكَ مِنۡهُمۡ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكُمۡ أَجۡمَعِینَ',
    'قال اخرج منها مذءوما مدحورا لمن تبعك منهم لاملان جهنم منكم اجمعين',
    'قَالَ <rule class=ham_wasl>ٱ</rule>خۡرُ<rule class=qalaqah>جۡ</rule> مِنۡهَا مَذۡءُو<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>دۡ</rule>حُو<rule class=idgham_wo_ghunnah>رًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبِعَكَ مِنۡهُمۡ لَأَمۡلَأَ<rule class=ghunnah>نّ</rule>َ جَهَ<rule class=ghunnah>نّ</rule>َمَ مِ<rule class=ikhafa>نك</rule>ُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ١٨',
    18, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 19 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    973,
    'وَیَـٰۤـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَیۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِینَ',
    'ويا ادم اسكن انت وزوجك الجنة فكلا من حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظالمين',
    'وَيَ<rule class=madda_obligatory_mottasel>ـٰٓـ</rule>ـَٔـادَمُ <rule class=ham_wasl>ٱ</rule>سۡكُنۡ أَ<rule class=ikhafa>نت</rule>َ وَزَوۡجُكَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَ<rule class=qalaqah>قۡ</rule>رَبَا هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرَةَ فَتَكُونَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٩',
    19, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 20 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    974,
    'فَوَسۡوَسَ لَهُمَا ٱلشَّیۡطَـٰنُ لِیُبۡدِیَ لَهُمَا مَا وُۥرِیَ عَنۡهُمَا مِن سَوۡءَ ٰ⁠ تِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَـٰذِهِ ٱلشَّجَرَةِ إِلَّاۤ أَن تَكُونَا مَلَكَیۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَـٰلِدِینَ',
    'فوسوس لهما الشيطان ليبدي لهما ما ووري عنهما من سواتهما وقال ما نهاكما ربكما عن هذه الشجرة الا ان تكونا ملكين او تكونا من الخالدين',
    'فَوَسۡوَسَ لَهُمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ لِيُ<rule class=qalaqah>بۡ</rule>دِىَ لَهُمَا مَا وُ<rule class=madda_normal>ۥ</rule>رِىَ عَنۡهُمَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َوۡء<rule class=madda_normal>ٰ</rule>تِهِمَا وَقَالَ مَا نَهَ<rule class=madda_normal>ـٰ</rule>كُمَا رَبُّكُمَا عَنۡ هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرَةِ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 21 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    975,
    'وَقَاسَمَهُمَاۤ إِنِّی لَكُمَا لَمِنَ ٱلنَّـٰصِحِینَ',
    'وقاسمهما اني لكما لمن الناصحين',
    'وَقَاسَمَهُم<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>ِى لَكُمَا لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>صِح<rule class=madda_permissible>ِي</rule>نَ ٢١',
    21, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 22 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    976,
    'فَدَلَّىٰهُمَا بِغُرُورࣲۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَ ٰ⁠ تُهُمَا وَطَفِقَا یَخۡصِفَانِ عَلَیۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَاۤ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَاۤ إِنَّ ٱلشَّیۡطَـٰنَ لَكُمَا عَدُوࣱّ مُّبِینࣱ',
    'فدلاهما بغرور فلما ذاقا الشجرة بدت لهما سواتهما وطفقا يخصفان عليهما من ورق الجنة وناداهما ربهما الم انهكما عن تلكما الشجرة واقل لكما ان الشيطان لكما عدو مبين',
    'فَدَلَّ<rule class=madda_normal>ـٰ</rule>هُمَا بِغُرُو<rule class=ikhafa>رٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َلَ<rule class=ghunnah>مّ</rule>َا ذَاقَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرَةَ بَدَتۡ لَهُمَا سَوۡء<rule class=madda_normal>ٰ</rule>تُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َرَقِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ‌ۖ وَنَادَ<rule class=madda_normal>ٮٰ</rule>هُمَا رَبُّهُم<rule class=madda_obligatory_monfasel>َآ</rule> أَلَمۡ أَنۡهَكُمَا عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ِلۡكُمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرَةِ وَأَقُل لَّكُم<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ لَكُمَا عَدُ<rule class=idgham_ghunnah>وٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٢٢',
    22, 8, 2, 152, 123, 61, 'false'
  );
  
  -- Ayah 23 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    977,
    'قَالَا رَبَّنَا ظَلَمۡنَاۤ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَـٰسِرِینَ',
    'قالا ربنا ظلمنا انفسنا وان لم تغفر لنا وترحمنا لنكونن من الخاسرين',
    'قَالَا رَبَّنَا ظَلَمۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسَنَا وَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٢٣',
    23, 8, 2, 153, 123, 61, 'false'
  );
  
  -- Ayah 24 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    978,
    'قَالَ ٱهۡبِطُوا۟ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ وَلَكُمۡ فِی ٱلۡأَرۡضِ مُسۡتَقَرࣱّ وَمَتَـٰعٌ إِلَىٰ حِینࣲ',
    'قال اهبطوا بعضكم لبعض عدو ولكم في الارض مستقر ومتاع الى حين',
    'قَالَ <rule class=ham_wasl>ٱ</rule>هۡبِطُو<rule class=slnt>اۡ</rule> بَعۡضُكُمۡ لِبَعۡضٍ عَدُ<rule class=idgham_ghunnah>وٌّ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُسۡتَقَ<rule class=idgham_ghunnah>رٌّ</rule> <rule class=idgham_ghunnah>و</rule>َمَتَ<rule class=madda_normal>ـٰ</rule>عٌ إِلَىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٢٤',
    24, 8, 2, 153, 123, 61, 'false'
  );
  
  -- Ayah 25 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    979,
    'قَالَ فِیهَا تَحۡیَوۡنَ وَفِیهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَجُونَ',
    'قال فيها تحيون وفيها تموتون ومنها تخرجون',
    'قَالَ فِيهَا تَحۡيَوۡنَ وَفِيهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَج<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 8, 2, 153, 123, 61, 'false'
  );
  
  -- Ayah 26 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    980,
    'یَـٰبَنِیۤ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَیۡكُمۡ لِبَاسࣰا یُوَ ٰ⁠رِی سَوۡءَ ٰ⁠ تِكُمۡ وَرِیشࣰاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَ ٰ⁠لِكَ خَیۡرࣱۚ ذَ ٰ⁠لِكَ مِنۡ ءَایَـٰتِ ٱللَّهِ لَعَلَّهُمۡ یَذَّكَّرُونَ',
    'يا بني ادم قد انزلنا عليكم لباسا يواري سواتكم وريشا ولباس التقوى ذلك خير ذلك من ايات الله لعلهم يذكرون',
    'يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَادَمَ قَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡكُمۡ لِبَا<rule class=idgham_ghunnah>سًا</rule> <rule class=idgham_ghunnah>ي</rule>ُو<rule class=madda_normal>ٰ</rule>رِى سَوۡء<rule class=madda_normal>ٰ</rule>تِكُمۡ وَرِي<rule class=idgham_ghunnah>شًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلِبَاسُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=qalaqah>قۡ</rule>وَىٰ ذ<rule class=madda_normal>ٰ</rule>لِكَ خَيۡ<rule class=ikhafa>رٌ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ مِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَعَلَّهُمۡ يَذَّكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 8, 2, 153, 124, 61, 'false'
  );
  
  -- Ayah 27 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    981,
    'یَـٰبَنِیۤ ءَادَمَ لَا یَفۡتِنَنَّكُمُ ٱلشَّیۡطَـٰنُ كَمَاۤ أَخۡرَجَ أَبَوَیۡكُم مِّنَ ٱلۡجَنَّةِ یَنزِعُ عَنۡهُمَا لِبَاسَهُمَا لِیُرِیَهُمَا سَوۡءَ ٰ⁠ تِهِمَاۤۚ إِنَّهُۥ یَرَىٰكُمۡ هُوَ وَقَبِیلُهُۥ مِنۡ حَیۡثُ لَا تَرَوۡنَهُمۡۗ إِنَّا جَعَلۡنَا ٱلشَّیَـٰطِینَ أَوۡلِیَاۤءَ لِلَّذِینَ لَا یُؤۡمِنُونَ',
    'يا بني ادم لا يفتننكم الشيطان كما اخرج ابويكم من الجنة ينزع عنهما لباسهما ليريهما سواتهما انه يراكم هو وقبيله من حيث لا ترونهم انا جعلنا الشياطين اولياء للذين لا يؤمنون',
    'يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَادَمَ لَا يَفۡتِنَ<rule class=ghunnah>نّ</rule>َكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡرَجَ أَبَوَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ يَ<rule class=ikhafa>نز</rule>ِعُ عَنۡهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوۡء<rule class=madda_normal>ٰ</rule>تِهِم<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَرَ<rule class=madda_normal>ٮٰ</rule>كُمۡ هُوَ وَقَبِيلُهُ<rule class=madda_normal>ۥ</rule> مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َا جَعَلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينَ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لِلَّذِينَ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 8, 2, 153, 124, 61, 'false'
  );
  
  -- Ayah 28 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    982,
    'وَإِذَا فَعَلُوا۟ فَـٰحِشَةࣰ قَالُوا۟ وَجَدۡنَا عَلَیۡهَاۤ ءَابَاۤءَنَا وَٱللَّهُ أَمَرَنَا بِهَاۗ قُلۡ إِنَّ ٱللَّهَ لَا یَأۡمُرُ بِٱلۡفَحۡشَاۤءِۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ',
    'واذا فعلوا فاحشة قالوا وجدنا عليها اباءنا والله امرنا بها قل ان الله لا يامر بالفحشاء اتقولون على الله ما لا تعلمون',
    'وَإِذَا فَعَلُو<rule class=slnt>اۡ</rule> فَ<rule class=madda_normal>ـٰ</rule>حِشَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> وَجَ<rule class=qalaqah>دۡ</rule>نَا عَلَيۡه<rule class=madda_obligatory_monfasel>َآ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَمَرَنَا بِهَا‌ۗ قُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَأۡمُرُ بِ<rule class=ham_wasl>ٱ</rule>لۡفَحۡش<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۖ أَتَقُولُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 8, 2, 153, 124, 61, 'false'
  );
  
  -- Ayah 29 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    983,
    'قُلۡ أَمَرَ رَبِّی بِٱلۡقِسۡطِۖ وَأَقِیمُوا۟ وُجُوهَكُمۡ عِندَ كُلِّ مَسۡجِدࣲ وَٱدۡعُوهُ مُخۡلِصِینَ لَهُ ٱلدِّینَۚ كَمَا بَدَأَكُمۡ تَعُودُونَ',
    'قل امر ربي بالقسط واقيموا وجوهكم عند كل مسجد وادعوه مخلصين له الدين كما بداكم تعودون',
    'قُلۡ أَمَرَ رَبِّى بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۖ وَأَقِيمُو<rule class=slnt>اۡ</rule> وُجُوهَكُمۡ عِ<rule class=ikhafa>ند</rule>َ كُلِّ مَسۡجِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُوهُ مُخۡلِصِينَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ‌ۚ كَمَا بَدَأَكُمۡ تَعُود<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 8, 2, 153, 124, 61, 'false'
  );
  
  -- Ayah 30 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    984,
    'فَرِیقًا هَدَىٰ وَفَرِیقًا حَقَّ عَلَیۡهِمُ ٱلضَّلَـٰلَةُۚ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّیَـٰطِینَ أَوۡلِیَاۤءَ مِن دُونِ ٱللَّهِ وَیَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ',
    'فريقا هدى وفريقا حق عليهم الضلالة انهم اتخذوا الشياطين اولياء من دون الله ويحسبون انهم مهتدون',
    'فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لَةُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َهُمُ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينَ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَحۡسَبُونَ أَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 8, 2, 153, 124, 61, 'false'
  );
  
  -- Ayah 31 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    985,
    '۞ یَـٰبَنِیۤ ءَادَمَ خُذُوا۟ زِینَتَكُمۡ عِندَ كُلِّ مَسۡجِدࣲ وَكُلُوا۟ وَٱشۡرَبُوا۟ وَلَا تُسۡرِفُوۤا۟ۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡمُسۡرِفِینَ',
    'يا بني ادم خذوا زينتكم عند كل مسجد وكلوا واشربوا ولا تسرفوا انه لا يحب المسرفين',
    '۞يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَادَمَ خُذُو<rule class=slnt>اۡ</rule> زِينَتَكُمۡ عِ<rule class=ikhafa>ند</rule>َ كُلِّ مَسۡجِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َكُلُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>شۡرَبُو<rule class=slnt>اۡ</rule> وَلَا تُسۡرِف<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُسۡرِف<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 8, 2, 154, 124, 62, 'false'
  );
  
  -- Ayah 32 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    986,
    'قُلۡ مَنۡ حَرَّمَ زِینَةَ ٱللَّهِ ٱلَّتِیۤ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّیِّبَـٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِیَ لِلَّذِینَ ءَامَنُوا۟ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا خَالِصَةࣰ یَوۡمَ ٱلۡقِیَـٰمَةِۗ كَذَ ٰ⁠لِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡلَمُونَ',
    'قل من حرم زينة الله التي اخرج لعباده والطيبات من الرزق قل هي للذين امنوا في الحياة الدنيا خالصة يوم القيامة كذلك نفصل الايات لقوم يعلمون',
    'قُلۡ مَنۡ حَرَّمَ زِينَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخۡرَجَ لِعِبَادِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقِ‌ۚ قُلۡ هِىَ لِلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا خَالِصَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نُفَصِّلُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 8, 2, 154, 125, 62, 'false'
  );
  
  -- Ayah 33 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    987,
    'قُلۡ إِنَّمَا حَرَّمَ رَبِّیَ ٱلۡفَوَ ٰ⁠حِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡیَ بِغَیۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُوا۟ بِٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ سُلۡطَـٰنࣰا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ',
    'قل انما حرم ربي الفواحش ما ظهر منها وما بطن والاثم والبغي بغير الحق وان تشركوا بالله ما لم ينزل به سلطانا وان تقولوا على الله ما لا تعلمون',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا حَرَّمَ رَبِّىَ <rule class=ham_wasl>ٱ</rule>لۡفَو<rule class=madda_normal>ٰ</rule>حِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَ<rule class=ham_wasl>ٱ</rule>لۡإِثۡمَ وَ<rule class=ham_wasl>ٱ</rule>لۡبَغۡىَ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُشۡرِكُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَمۡ يُنَزِّلۡ بِه<rule class=madda_normal>ِۦ</rule> سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 8, 2, 154, 125, 62, 'false'
  );
  
  -- Ayah 34 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    988,
    'وَلِكُلِّ أُمَّةٍ أَجَلࣱۖ فَإِذَا جَاۤءَ أَجَلُهُمۡ لَا یَسۡتَأۡخِرُونَ سَاعَةࣰ وَلَا یَسۡتَقۡدِمُونَ',
    'ولكل امة اجل فاذا جاء اجلهم لا يستاخرون ساعة ولا يستقدمون',
    'وَلِكُلِّ أُ<rule class=ghunnah>مّ</rule>َةٍ أَجَ<rule class=ikhafa>لٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَسۡتَ<rule class=qalaqah>قۡ</rule>دِم<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 8, 2, 154, 125, 62, 'false'
  );
  
  -- Ayah 35 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    989,
    'یَـٰبَنِیۤ ءَادَمَ إِمَّا یَأۡتِیَنَّكُمۡ رُسُلࣱ مِّنكُمۡ یَقُصُّونَ عَلَیۡكُمۡ ءَایَـٰتِی فَمَنِ ٱتَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'يا بني ادم اما ياتينكم رسل منكم يقصون عليكم اياتي فمن اتقى واصلح فلا خوف عليهم ولا هم يحزنون',
    'يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَادَمَ إِ<rule class=ghunnah>مّ</rule>َا يَأۡتِيَ<rule class=ghunnah>نّ</rule>َكُمۡ رُسُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِى‌ۙ فَمَنِ <rule class=ham_wasl>ٱ</rule>تَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 8, 2, 154, 125, 62, 'false'
  );
  
  -- Ayah 36 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    990,
    'وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَٱسۡتَكۡبَرُوا۟ عَنۡهَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'والذين كذبوا باياتنا واستكبروا عنها اولئك اصحاب النار هم فيها خالدون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> عَنۡه<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 8, 2, 154, 125, 62, 'false'
  );
  
  -- Ayah 37 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    991,
    'فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔایَـٰتِهِۦۤۚ أُو۟لَـٰۤىِٕكَ یَنَالُهُمۡ نَصِیبُهُم مِّنَ ٱلۡكِتَـٰبِۖ حَتَّىٰۤ إِذَا جَاۤءَتۡهُمۡ رُسُلُنَا یَتَوَفَّوۡنَهُمۡ قَالُوۤا۟ أَیۡنَ مَا كُنتُمۡ تَدۡعُونَ مِن دُونِ ٱللَّهِۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰۤ أَنفُسِهِمۡ أَنَّهُمۡ كَانُوا۟ كَـٰفِرِینَ',
    'فمن اظلم ممن افترى على الله كذبا او كذب باياته اولئك ينالهم نصيبهم من الكتاب حتى اذا جاءتهم رسلنا يتوفونهم قالوا اين ما كنتم تدعون من دون الله قالوا ضلوا عنا وشهدوا على انفسهم انهم كانوا كافرين',
    'فَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَنَالُهُمۡ نَصِيبُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ رُسُلُنَا يَتَوَفَّوۡنَهُمۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡنَ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ قَالُو<rule class=slnt>اۡ</rule> ضَلُّو<rule class=slnt>اۡ</rule> عَ<rule class=ghunnah>نّ</rule>َا وَشَهِدُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 8, 2, 154, 125, 62, 'false'
  );
  
  -- Ayah 38 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    992,
    'قَالَ ٱدۡخُلُوا۟ فِیۤ أُمَمࣲ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِی ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةࣱ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰۤ إِذَا ٱدَّارَكُوا۟ فِیهَا جَمِیعࣰا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَـٰۤؤُلَاۤءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابࣰا ضِعۡفࣰا مِّنَ ٱلنَّارِۖ قَالَ لِكُلࣲّ ضِعۡفࣱ وَلَـٰكِن لَّا تَعۡلَمُونَ',
    'قال ادخلوا في امم قد خلت من قبلكم من الجن والانس في النار كلما دخلت امة لعنت اختها حتى اذا اداركوا فيها جميعا قالت اخراهم لاولاهم ربنا هؤلاء اضلونا فاتهم عذابا ضعفا من النار قال لكل ضعف ولكن لا تعلمون',
    'قَالَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُمَ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ كُلَّمَا دَخَلَتۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَنَتۡ أُخۡتَهَا‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا <rule class=ham_wasl>ٱ</rule>دَّارَكُو<rule class=slnt>اۡ</rule> فِيهَا جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ق</rule>َالَتۡ أُخۡرَ<rule class=madda_normal>ٮٰ</rule>هُمۡ لِأُولَ<rule class=madda_normal>ـٰ</rule>هُمۡ رَبَّنَا هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَضَلُّونَا فَـَٔـاتِهِمۡ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ض</rule>ِعۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ قَالَ لِكُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>ض</rule>ِعۡ<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 8, 2, 155, 125, 62, 'false'
  );
  
  -- Ayah 39 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    993,
    'وَقَالَتۡ أُولَىٰهُمۡ لِأُخۡرَىٰهُمۡ فَمَا كَانَ لَكُمۡ عَلَیۡنَا مِن فَضۡلࣲ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡسِبُونَ',
    'وقالت اولاهم لاخراهم فما كان لكم علينا من فضل فذوقوا العذاب بما كنتم تكسبون',
    'وَقَالَتۡ أُولَ<rule class=madda_normal>ـٰ</rule>هُمۡ لِأُخۡرَ<rule class=madda_normal>ٮٰ</rule>هُمۡ فَمَا كَانَ لَكُمۡ عَلَيۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َذُوقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 8, 2, 155, 125, 62, 'false'
  );
  
  -- Ayah 40 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    994,
    'إِنَّ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَٱسۡتَكۡبَرُوا۟ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَ ٰ⁠بُ ٱلسَّمَاۤءِ وَلَا یَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ یَلِجَ ٱلۡجَمَلُ فِی سَمِّ ٱلۡخِیَاطِۚ وَكَذَ ٰ⁠لِكَ نَجۡزِی ٱلۡمُجۡرِمِینَ',
    'ان الذين كذبوا باياتنا واستكبروا عنها لا تفتح لهم ابواب السماء ولا يدخلون الجنة حتى يلج الجمل في سم الخياط وكذلك نجزي المجرمين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَلَا يَ<rule class=qalaqah>دۡ</rule>خُلُونَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ حَتَّىٰ يَلِجَ <rule class=ham_wasl>ٱ</rule>لۡجَمَلُ فِى سَ<rule class=ghunnah>مّ</rule>ِ <rule class=ham_wasl>ٱ</rule>لۡخِيَاطِ‌ۚ وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 8, 2, 155, 126, 62, 'false'
  );
  
  -- Ayah 41 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    995,
    'لَهُم مِّن جَهَنَّمَ مِهَادࣱ وَمِن فَوۡقِهِمۡ غَوَاشࣲۚ وَكَذَ ٰ⁠لِكَ نَجۡزِی ٱلظَّـٰلِمِینَ',
    'لهم من جهنم مهاد ومن فوقهم غواش وكذلك نجزي الظالمين',
    'لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َهَ<rule class=ghunnah>نّ</rule>َمَ مِهَا<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهِمۡ غَوَا<rule class=idgham_ghunnah>شٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤١',
    41, 8, 2, 155, 126, 62, 'false'
  );
  
  -- Ayah 42 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    996,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'والذين امنوا وعملوا الصالحات لا نكلف نفسا الا وسعها اولئك اصحاب الجنة هم فيها خالدون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَه<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 8, 2, 155, 126, 62, 'false'
  );
  
  -- Ayah 43 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    997,
    'وَنَزَعۡنَا مَا فِی صُدُورِهِم مِّنۡ غِلࣲّ تَجۡرِی مِن تَحۡتِهِمُ ٱلۡأَنۡهَـٰرُۖ وَقَالُوا۟ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی هَدَىٰنَا لِهَـٰذَا وَمَا كُنَّا لِنَهۡتَدِیَ لَوۡلَاۤ أَنۡ هَدَىٰنَا ٱللَّهُۖ لَقَدۡ جَاۤءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّۖ وَنُودُوۤا۟ أَن تِلۡكُمُ ٱلۡجَنَّةُ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'ونزعنا ما في صدورهم من غل تجري من تحتهم الانهار وقالوا الحمد لله الذي هدانا لهذا وما كنا لنهتدي لولا ان هدانا الله لقد جاءت رسل ربنا بالحق ونودوا ان تلكم الجنة اورثتموها بما كنتم تعملون',
    'وَنَزَعۡنَا مَا فِى صُدُورِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ غِ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۖ وَقَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى هَدَ<rule class=madda_normal>ٮٰ</rule>نَا لِهَ<rule class=madda_normal>ـٰ</rule>ذَا وَمَا كُ<rule class=ghunnah>نّ</rule>َا لِنَهۡتَدِىَ لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡ هَدَ<rule class=madda_normal>ٮٰ</rule>نَا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ لَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ رُسُلُ رَبِّنَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ وَنُود<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ِلۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةُ أُورِثۡتُمُوهَا بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 8, 2, 155, 126, 62, 'false'
  );
  
  -- Ayah 44 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    998,
    'وَنَادَىٰۤ أَصۡحَـٰبُ ٱلۡجَنَّةِ أَصۡحَـٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقࣰّا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقࣰّاۖ قَالُوا۟ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَیۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِینَ',
    'ونادى اصحاب الجنة اصحاب النار ان قد وجدنا ما وعدنا ربنا حقا فهل وجدتم ما وعد ربكم حقا قالوا نعم فاذن مؤذن بينهم ان لعنة الله على الظالمين',
    'وَنَادَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> وَجَ<rule class=qalaqah>دۡ</rule>نَا مَا وَعَدَنَا رَبُّنَا حَق<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ف</rule>َهَلۡ وَجَ<rule class=idgham_mutajanisayn>د</rule>تّ<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا وَعَدَ رَبُّكُمۡ حَق<rule class=ikhafa>ًّا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> نَعَمۡ‌ۚ فَأَذَّنَ مُؤَذِّ<rule class=iqlab>نُۢ</rule> <rule class=iqlab>ب</rule>َيۡنَهُمۡ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعۡنَةُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤٤',
    44, 8, 2, 156, 126, 62, 'false'
  );
  
  -- Ayah 45 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    999,
    'ٱلَّذِینَ یَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَیَبۡغُونَهَا عِوَجࣰا وَهُم بِٱلۡـَٔاخِرَةِ كَـٰفِرُونَ',
    'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخرة كافرون',
    'ٱلَّذِينَ يَصُدُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَ<rule class=qalaqah>بۡ</rule>غُونَهَا عِوَ<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 8, 2, 156, 126, 62, 'false'
  );
  
  -- Ayah 46 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1000,
    'وَبَیۡنَهُمَا حِجَابࣱۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالࣱ یَعۡرِفُونَ كُلَّۢا بِسِیمَىٰهُمۡۚ وَنَادَوۡا۟ أَصۡحَـٰبَ ٱلۡجَنَّةِ أَن سَلَـٰمٌ عَلَیۡكُمۡۚ لَمۡ یَدۡخُلُوهَا وَهُمۡ یَطۡمَعُونَ',
    'وبينهما حجاب وعلى الاعراف رجال يعرفون كلا بسيماهم ونادوا اصحاب الجنة ان سلام عليكم لم يدخلوها وهم يطمعون',
    'وَبَيۡنَهُمَا حِجَا<rule class=idgham_ghunnah>بٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َعَلَى <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَافِ رِجَا<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡرِفُونَ كُلا<rule class=iqlab>َّۢ</rule> <rule class=iqlab>ب</rule>ِسِيمَ<rule class=madda_normal>ـٰ</rule>هُمۡ‌ۚ وَنَادَوۡ<rule class=slnt>اۡ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَيۡكُمۡ‌ۚ لَمۡ يَ<rule class=qalaqah>دۡ</rule>خُلُوهَا وَهُمۡ يَ<rule class=qalaqah>طۡ</rule>مَع<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 8, 2, 156, 126, 62, 'false'
  );
  
  -- Ayah 47 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1001,
    '۞ وَإِذَا صُرِفَتۡ أَبۡصَـٰرُهُمۡ تِلۡقَاۤءَ أَصۡحَـٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'واذا صرفت ابصارهم تلقاء اصحاب النار قالوا ربنا لا تجعلنا مع القوم الظالمين',
    '۞وَإِذَا صُرِفَتۡ أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُهُمۡ تِلۡق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ قَالُو<rule class=slnt>اۡ</rule> رَبَّنَا لَا تَ<rule class=qalaqah>جۡ</rule>عَلۡنَا مَعَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 8, 2, 156, 126, 63, 'false'
  );
  
  -- Ayah 48 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1002,
    'وَنَادَىٰۤ أَصۡحَـٰبُ ٱلۡأَعۡرَافِ رِجَالࣰا یَعۡرِفُونَهُم بِسِیمَىٰهُمۡ قَالُوا۟ مَاۤ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ',
    'ونادى اصحاب الاعراف رجالا يعرفونهم بسيماهم قالوا ما اغنى عنكم جمعكم وما كنتم تستكبرون',
    'وَنَادَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَافِ رِجَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ي</rule>َعۡرِفُونَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسِيمَ<rule class=madda_normal>ـٰ</rule>هُمۡ قَالُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡنَىٰ عَ<rule class=ikhafa>نك</rule>ُمۡ جَمۡعُكُمۡ وَمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَسۡتَكۡبِر<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 8, 2, 156, 127, 63, 'false'
  );
  
  -- Ayah 49 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1003,
    'أَهَـٰۤؤُلَاۤءِ ٱلَّذِینَ أَقۡسَمۡتُمۡ لَا یَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُوا۟ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَیۡكُمۡ وَلَاۤ أَنتُمۡ تَحۡزَنُونَ',
    'اهؤلاء الذين اقسمتم لا ينالهم الله برحمة ادخلوا الجنة لا خوف عليكم ولا انتم تحزنون',
    'أَهَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَ<rule class=qalaqah>قۡ</rule>سَمۡتُمۡ لَا يَنَالُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِرَحۡمَةٍ‌ۚ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ لَا خَوۡفٌ عَلَيۡكُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ تَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 8, 2, 156, 127, 63, 'false'
  );
  
  -- Ayah 50 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1004,
    'وَنَادَىٰۤ أَصۡحَـٰبُ ٱلنَّارِ أَصۡحَـٰبَ ٱلۡجَنَّةِ أَنۡ أَفِیضُوا۟ عَلَیۡنَا مِنَ ٱلۡمَاۤءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوۤا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَـٰفِرِینَ',
    'ونادى اصحاب النار اصحاب الجنة ان افيضوا علينا من الماء او مما رزقكم الله قالوا ان الله حرمهما على الكافرين',
    'وَنَادَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ أَنۡ أَفِيضُو<rule class=slnt>اۡ</rule> عَلَيۡنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَوۡ مِ<rule class=ghunnah>مّ</rule>َا رَزَقَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ حَرَّمَهُمَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٥٠',
    50, 8, 2, 156, 127, 63, 'false'
  );
  
  -- Ayah 51 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1005,
    'ٱلَّذِینَ ٱتَّخَذُوا۟ دِینَهُمۡ لَهۡوࣰا وَلَعِبࣰا وَغَرَّتۡهُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۚ فَٱلۡیَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُوا۟ لِقَاۤءَ یَوۡمِهِمۡ هَـٰذَا وَمَا كَانُوا۟ بِـَٔایَـٰتِنَا یَجۡحَدُونَ',
    'الذين اتخذوا دينهم لهوا ولعبا وغرتهم الحياة الدنيا فاليوم ننساهم كما نسوا لقاء يومهم هذا وما كانوا باياتنا يجحدون',
    'ٱلَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> دِينَهُمۡ لَهۡ<rule class=idgham_ghunnah>وًا</rule> <rule class=idgham_ghunnah>و</rule>َلَعِ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َغَرَّتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۚ فَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ نَ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>هُمۡ كَمَا نَسُو<rule class=slnt>اۡ</rule> لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ يَوۡمِهِمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا وَمَا كَانُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا يَ<rule class=qalaqah>جۡ</rule>حَد<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 8, 2, 156, 127, 63, 'false'
  );
  
  -- Ayah 52 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1006,
    'وَلَقَدۡ جِئۡنَـٰهُم بِكِتَـٰبࣲ فَصَّلۡنَـٰهُ عَلَىٰ عِلۡمٍ هُدࣰى وَرَحۡمَةࣰ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'ولقد جئناهم بكتاب فصلناه على علم هدى ورحمة لقوم يؤمنون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> جِئۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِكِتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ف</rule>َصَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُ عَلَىٰ عِلۡمٍ هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 8, 2, 157, 127, 63, 'false'
  );
  
  -- Ayah 53 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1007,
    'هَلۡ یَنظُرُونَ إِلَّا تَأۡوِیلَهُۥۚ یَوۡمَ یَأۡتِی تَأۡوِیلُهُۥ یَقُولُ ٱلَّذِینَ نَسُوهُ مِن قَبۡلُ قَدۡ جَاۤءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّ فَهَل لَّنَا مِن شُفَعَاۤءَ فَیَشۡفَعُوا۟ لَنَاۤ أَوۡ نُرَدُّ فَنَعۡمَلَ غَیۡرَ ٱلَّذِی كُنَّا نَعۡمَلُۚ قَدۡ خَسِرُوۤا۟ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ',
    'هل ينظرون الا تاويله يوم ياتي تاويله يقول الذين نسوه من قبل قد جاءت رسل ربنا بالحق فهل لنا من شفعاء فيشفعوا لنا او نرد فنعمل غير الذي كنا نعمل قد خسروا انفسهم وضل عنهم ما كانوا يفترون',
    'هَلۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلَّا تَأۡوِيلَهُ<rule class=madda_normal>ۥ</rule>‌ۚ يَوۡمَ يَأۡتِى تَأۡوِيلُهُ<rule class=madda_normal>ۥ</rule> يَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ نَسُوهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ رُسُلُ رَبِّنَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ فَهَل لَّنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ُفَع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَيَشۡفَعُو<rule class=slnt>اۡ</rule> لَن<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ نُرَدُّ فَنَعۡمَلَ غَيۡرَ <rule class=ham_wasl>ٱ</rule>لَّذِى كُ<rule class=ghunnah>نّ</rule>َا نَعۡمَلُ‌ۚ قَ<rule class=qalaqah>دۡ</rule> خَسِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَضَلَّ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 8, 2, 157, 127, 63, 'false'
  );
  
  -- Ayah 54 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1008,
    'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ یُغۡشِی ٱلَّیۡلَ ٱلنَّهَارَ یَطۡلُبُهُۥ حَثِیثࣰا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَ ٰ⁠تِۭ بِأَمۡرِهِۦۤۗ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَـٰلَمِینَ',
    'ان ربكم الله الذي خلق السماوات والارض في ستة ايام ثم استوى على العرش يغشي الليل النهار يطلبه حثيثا والشمس والقمر والنجوم مسخرات بامره الا له الخلق والامر تبارك الله رب العالمين',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فِى سِتَّةِ أَيَّا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ يُغۡشِى <rule class=ham_wasl>ٱ</rule>لَّيۡلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ يَ<rule class=qalaqah>طۡ</rule>لُبُهُ<rule class=madda_normal>ۥ</rule> حَثِي<rule class=idgham_ghunnah>ثًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُجُومَ مُسَخَّر<rule class=madda_normal>ٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>ِأَمۡرِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> أَلَا لَهُ <rule class=ham_wasl>ٱ</rule>لۡخَلۡقُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ‌ۗ تَبَارَكَ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٥٤',
    54, 8, 2, 157, 128, 63, 'false'
  );
  
  -- Ayah 55 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1009,
    'ٱدۡعُوا۟ رَبَّكُمۡ تَضَرُّعࣰا وَخُفۡیَةًۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡمُعۡتَدِینَ',
    'ادعوا ربكم تضرعا وخفية انه لا يحب المعتدين',
    'ٱ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ تَضَرُّ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َخُفۡيَةً‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُعۡتَد<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 8, 2, 157, 128, 63, 'false'
  );
  
  -- Ayah 56 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1010,
    'وَلَا تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ بَعۡدَ إِصۡلَـٰحِهَا وَٱدۡعُوهُ خَوۡفࣰا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِیبࣱ مِّنَ ٱلۡمُحۡسِنِینَ',
    'ولا تفسدوا في الارض بعد اصلاحها وادعوه خوفا وطمعا ان رحمت الله قريب من المحسنين',
    'وَلَا تُفۡسِدُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بَعۡدَ إِصۡلَ<rule class=madda_normal>ـٰ</rule>حِهَا وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُوهُ خَوۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َطَمَعًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَحۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ قَرِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٥٦',
    56, 8, 2, 157, 128, 63, 'false'
  );
  
  -- Ayah 57 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1011,
    'وَهُوَ ٱلَّذِی یُرۡسِلُ ٱلرِّیَـٰحَ بُشۡرَۢا بَیۡنَ یَدَیۡ رَحۡمَتِهِۦۖ حَتَّىٰۤ إِذَاۤ أَقَلَّتۡ سَحَابࣰا ثِقَالࣰا سُقۡنَـٰهُ لِبَلَدࣲ مَّیِّتࣲ فَأَنزَلۡنَا بِهِ ٱلۡمَاۤءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَ ٰ⁠تِۚ كَذَ ٰ⁠لِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ',
    'وهو الذي يرسل الرياح بشرا بين يدي رحمته حتى اذا اقلت سحابا ثقالا سقناه لبلد ميت فانزلنا به الماء فاخرجنا به من كل الثمرات كذلك نخرج الموتى لعلكم تذكرون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُرۡسِلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حَ بُشۡر<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَ يَدَىۡ رَحۡمَتِه<rule class=madda_normal>ِۦ</rule>‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَقَلَّتۡ سَحَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ث</rule>ِقَال<rule class=ikhafa>اً</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ لِبَلَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>َّيِّ<rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=ikhafa>نز</rule>َلۡنَا بِهِ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَأَخۡرَ<rule class=qalaqah>جۡ</rule>نَا بِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 8, 2, 157, 128, 63, 'false'
  );
  
  -- Ayah 58 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1012,
    'وَٱلۡبَلَدُ ٱلطَّیِّبُ یَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِی خَبُثَ لَا یَخۡرُجُ إِلَّا نَكِدࣰاۚ كَذَ ٰ⁠لِكَ نُصَرِّفُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَشۡكُرُونَ',
    'والبلد الطيب يخرج نباته باذن ربه والذي خبث لا يخرج الا نكدا كذلك نصرف الايات لقوم يشكرون',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡبَلَدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبُ يَخۡرُجُ نَبَاتُهُ<rule class=madda_normal>ۥ</rule> بِإِذۡنِ رَبِّه<rule class=madda_normal>ِۦ</rule>‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِى خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِ<rule class=ikhafa>دًا‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ نُصَرِّفُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 8, 2, 158, 128, 63, 'false'
  );
  
  -- Ayah 59 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1013,
    'لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤ إِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمٍ عَظِیمࣲ',
    'لقد ارسلنا نوحا الى قومه فقال يا قوم اعبدوا الله ما لكم من اله غيره اني اخاف عليكم عذاب يوم عظيم',
    'لَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule> فَقَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ٥٩',
    59, 8, 2, 158, 129, 63, 'false'
  );
  
  -- Ayah 60 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1014,
    'قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦۤ إِنَّا لَنَرَىٰكَ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'قال الملا من قومه انا لنراك في ضلال مبين',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>َا لَنَرَ<rule class=madda_normal>ٮٰ</rule>كَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٦٠',
    60, 8, 2, 158, 129, 63, 'false'
  );
  
  -- Ayah 61 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1015,
    'قَالَ یَـٰقَوۡمِ لَیۡسَ بِی ضَلَـٰلَةࣱ وَلَـٰكِنِّی رَسُولࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ',
    'قال يا قوم ليس بي ضلالة ولكني رسول من رب العالمين',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ لَيۡسَ بِى ضَلَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>ِى رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٦١',
    61, 8, 2, 158, 129, 63, 'false'
  );
  
  -- Ayah 62 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1016,
    'أُبَلِّغُكُمۡ رِسَـٰلَـٰتِ رَبِّی وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ',
    'ابلغكم رسالات ربي وانصح لكم واعلم من الله ما لا تعلمون',
    'أُبَلِّغُكُمۡ رِسَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّى وَأَ<rule class=ikhafa>نص</rule>َحُ لَكُمۡ وَأَعۡلَمُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 8, 2, 158, 129, 63, 'false'
  );
  
  -- Ayah 63 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1017,
    'أَوَعَجِبۡتُمۡ أَن جَاۤءَكُمۡ ذِكۡرࣱ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلࣲ مِّنكُمۡ لِیُنذِرَكُمۡ وَلِتَتَّقُوا۟ وَلَعَلَّكُمۡ تُرۡحَمُونَ',
    'اوعجبتم ان جاءكم ذكر من ربكم على رجل منكم لينذركم ولتتقوا ولعلكم ترحمون',
    'أَوَعَجِ<rule class=qalaqah>بۡ</rule>تُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ ذِكۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ عَلَىٰ رَجُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ لِيُ<rule class=ikhafa>نذ</rule>ِرَكُمۡ وَلِتَتَّقُو<rule class=slnt>اۡ</rule> وَلَعَلَّكُمۡ تُرۡحَم<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 8, 2, 158, 129, 63, 'false'
  );
  
  -- Ayah 64 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1018,
    'فَكَذَّبُوهُ فَأَنجَیۡنَـٰهُ وَٱلَّذِینَ مَعَهُۥ فِی ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمًا عَمِینَ',
    'فكذبوه فانجيناه والذين معه في الفلك واغرقنا الذين كذبوا باياتنا انهم كانوا قوما عمين',
    'فَكَذَّبُوهُ فَأَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مَعَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ وَأَغۡرَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> قَوۡمًا عَم<rule class=madda_permissible>ِي</rule>نَ ٦٤',
    64, 8, 2, 158, 129, 63, 'false'
  );
  
  -- Ayah 65 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1019,
    '۞ وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤۚ أَفَلَا تَتَّقُونَ',
    'والى عاد اخاهم هودا قال يا قوم اعبدوا الله ما لكم من اله غيره افلا تتقون',
    '۞وَإِلَىٰ عَادٍ أَخَاهُمۡ هُو<rule class=ikhafa>دًا‌ۗ</rule> <rule class=ikhafa>ق</rule>َالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> أَفَلَا تَتَّق<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 8, 2, 158, 130, 64, 'false'
  );
  
  -- Ayah 66 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1020,
    'قَالَ ٱلۡمَلَأُ ٱلَّذِینَ كَفَرُوا۟ مِن قَوۡمِهِۦۤ إِنَّا لَنَرَىٰكَ فِی سَفَاهَةࣲ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَـٰذِبِینَ',
    'قال الملا الذين كفروا من قومه انا لنراك في سفاهة وانا لنظنك من الكاذبين',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>َا لَنَرَ<rule class=madda_normal>ٮٰ</rule>كَ فِى سَفَاهَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َا لَنَظُ<rule class=ghunnah>نّ</rule>ُكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 8, 2, 158, 130, 64, 'false'
  );
  
  -- Ayah 67 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1021,
    'قَالَ یَـٰقَوۡمِ لَیۡسَ بِی سَفَاهَةࣱ وَلَـٰكِنِّی رَسُولࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ',
    'قال يا قوم ليس بي سفاهة ولكني رسول من رب العالمين',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ لَيۡسَ بِى سَفَاهَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>ِى رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٦٧',
    67, 8, 2, 158, 130, 64, 'false'
  );
  
  -- Ayah 68 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1022,
    'أُبَلِّغُكُمۡ رِسَـٰلَـٰتِ رَبِّی وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِینٌ',
    'ابلغكم رسالات ربي وانا لكم ناصح امين',
    'أُبَلِّغُكُمۡ رِسَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّى وَأَنَاۡ لَكُمۡ نَاصِحٌ أَم<rule class=madda_permissible>ِي</rule>نٌ ٦٨',
    68, 8, 2, 159, 130, 64, 'false'
  );
  
  -- Ayah 69 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1023,
    'أَوَعَجِبۡتُمۡ أَن جَاۤءَكُمۡ ذِكۡرࣱ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلࣲ مِّنكُمۡ لِیُنذِرَكُمۡۚ وَٱذۡكُرُوۤا۟ إِذۡ جَعَلَكُمۡ خُلَفَاۤءَ مِنۢ بَعۡدِ قَوۡمِ نُوحࣲ وَزَادَكُمۡ فِی ٱلۡخَلۡقِ بَصۜۡطَةࣰۖ فَٱذۡكُرُوۤا۟ ءَالَاۤءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ',
    'اوعجبتم ان جاءكم ذكر من ربكم على رجل منكم لينذركم واذكروا اذ جعلكم خلفاء من بعد قوم نوح وزادكم في الخلق بسطة فاذكروا الاء الله لعلكم تفلحون',
    'أَوَعَجِ<rule class=qalaqah>بۡ</rule>تُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ ذِكۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ عَلَىٰ رَجُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ لِيُ<rule class=ikhafa>نذ</rule>ِرَكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>ذۡكُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذۡ جَعَلَكُمۡ خُلَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ قَوۡمِ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َزَادَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡخَلۡقِ بَصۜۡطَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَال<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهِ لَعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 8, 2, 159, 130, 64, 'false'
  );
  
  -- Ayah 70 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1024,
    'قَالُوۤا۟ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ یَعۡبُدُ ءَابَاۤؤُنَا فَأۡتِنَا بِمَا تَعِدُنَاۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'قالوا اجئتنا لنعبد الله وحده ونذر ما كان يعبد اباؤنا فاتنا بما تعدنا ان كنت من الصادقين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَجِئۡتَنَا لِنَعۡبُدَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَحۡدَهُ<rule class=madda_normal>ۥ</rule> وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا‌ۖ فَأۡتِنَا بِمَا تَعِدُن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٧٠',
    70, 8, 2, 159, 130, 64, 'false'
  );
  
  -- Ayah 71 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1025,
    'قَالَ قَدۡ وَقَعَ عَلَیۡكُم مِّن رَّبِّكُمۡ رِجۡسࣱ وَغَضَبٌۖ أَتُجَـٰدِلُونَنِی فِیۤ أَسۡمَاۤءࣲ سَمَّیۡتُمُوهَاۤ أَنتُمۡ وَءَابَاۤؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَـٰنࣲۚ فَٱنتَظِرُوۤا۟ إِنِّی مَعَكُم مِّنَ ٱلۡمُنتَظِرِینَ',
    'قال قد وقع عليكم من ربكم رجس وغضب اتجادلونني في اسماء سميتموها انتم واباؤكم ما نزل الله بها من سلطان فانتظروا اني معكم من المنتظرين',
    'قَالَ قَ<rule class=qalaqah>دۡ</rule> وَقَعَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ رِ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>و</rule>َغَضَبٌ‌ۖ أَتُجَ<rule class=madda_normal>ـٰ</rule>دِلُونَنِى ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>س</rule>َ<rule class=ghunnah>مّ</rule>َيۡتُمُوه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا نَزَّلَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َظِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>ِى مَعَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نت</rule>َظِر<rule class=madda_permissible>ِي</rule>نَ ٧١',
    71, 8, 2, 159, 130, 64, 'false'
  );
  
  -- Ayah 72 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1026,
    'فَأَنجَیۡنَـٰهُ وَٱلَّذِینَ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَقَطَعۡنَا دَابِرَ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۖ وَمَا كَانُوا۟ مُؤۡمِنِینَ',
    'فانجيناه والذين معه برحمة منا وقطعنا دابر الذين كذبوا باياتنا وما كانوا مؤمنين',
    'فَأَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مَعَهُ<rule class=madda_normal>ۥ</rule> بِرَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا وَقَطَعۡنَا دَابِرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا‌ۖ وَمَا كَانُو<rule class=slnt>اۡ</rule> مُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٧٢',
    72, 8, 2, 159, 130, 64, 'false'
  );
  
  -- Ayah 73 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1027,
    'وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَـٰلِحࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۖ قَدۡ جَاۤءَتۡكُم بَیِّنَةࣱ مِّن رَّبِّكُمۡۖ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَایَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِیۤ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوۤءࣲ فَیَأۡخُذَكُمۡ عَذَابٌ أَلِیمࣱ',
    'والى ثمود اخاهم صالحا قال يا قوم اعبدوا الله ما لكم من اله غيره قد جاءتكم بينة من ربكم هذه ناقة الله لكم اية فذروها تاكل في ارض الله ولا تمسوها بسوء فياخذكم عذاب اليم',
    'وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا‌ۗ</rule> <rule class=ikhafa>ق</rule>َالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_normal>ۥ</rule>‌ۖ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيِّنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۖ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> نَاقَةُ <rule class=ham_wasl>ٱ</rule>للَّهِ لَكُمۡ ءَايَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ف</rule>َذَرُوهَا تَأۡكُلۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡضِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَلَا تَمَسُّوهَا بِس<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ف</rule>َيَأۡخُذَكُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٧٣',
    73, 8, 2, 159, 131, 64, 'false'
  );
  
  -- Ayah 74 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1028,
    'وَٱذۡكُرُوۤا۟ إِذۡ جَعَلَكُمۡ خُلَفَاۤءَ مِنۢ بَعۡدِ عَادࣲ وَبَوَّأَكُمۡ فِی ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورࣰا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُیُوتࣰاۖ فَٱذۡكُرُوۤا۟ ءَالَاۤءَ ٱللَّهِ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ',
    'واذكروا اذ جعلكم خلفاء من بعد عاد وبواكم في الارض تتخذون من سهولها قصورا وتنحتون الجبال بيوتا فاذكروا الاء الله ولا تعثوا في الارض مفسدين',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذۡ جَعَلَكُمۡ خُلَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ عَا<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َبَوَّأَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ تَتَّخِذُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُهُولِهَا قُصُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َتَنۡحِتُونَ <rule class=ham_wasl>ٱ</rule>لۡجِبَالَ بُيُو<rule class=ikhafa>تًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَال<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا تَعۡثَوۡ<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٧٤',
    74, 8, 2, 160, 131, 64, 'false'
  );
  
  -- Ayah 75 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1029,
    'قَالَ ٱلۡمَلَأُ ٱلَّذِینَ ٱسۡتَكۡبَرُوا۟ مِن قَوۡمِهِۦ لِلَّذِینَ ٱسۡتُضۡعِفُوا۟ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَـٰلِحࣰا مُّرۡسَلࣱ مِّن رَّبِّهِۦۚ قَالُوۤا۟ إِنَّا بِمَاۤ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ',
    'قال الملا الذين استكبروا من قومه للذين استضعفوا لمن امن منهم اتعلمون ان صالحا مرسل من ربه قالوا انا بما ارسل به مؤمنون',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_normal>ِۦ</rule> لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتُضۡعِفُو<rule class=slnt>اۡ</rule> لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَ<rule class=ghunnah>نّ</rule>َ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>م</rule>ُّرۡسَ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule>‌ۚ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلَ بِه<rule class=madda_normal>ِۦ</rule> مُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 8, 2, 160, 131, 64, 'false'
  );
  
  -- Ayah 76 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1030,
    'قَالَ ٱلَّذِینَ ٱسۡتَكۡبَرُوۤا۟ إِنَّا بِٱلَّذِیۤ ءَامَنتُم بِهِۦ كَـٰفِرُونَ',
    'قال الذين استكبروا انا بالذي امنتم به كافرون',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَامَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٧٦',
    76, 8, 2, 160, 131, 64, 'false'
  );
  
  -- Ayah 77 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1031,
    'فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوۡا۟ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُوا۟ یَـٰصَـٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَاۤ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِینَ',
    'فعقروا الناقة وعتوا عن امر ربهم وقالوا يا صالح ائتنا بما تعدنا ان كنت من المرسلين',
    'فَعَقَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاقَةَ وَعَتَوۡ<rule class=slnt>اۡ</rule> عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>صَ<rule class=madda_normal>ـٰ</rule>لِحُ <rule class=ham_wasl>ٱ</rule>ئۡتِنَا بِمَا تَعِدُن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٧٧',
    77, 8, 2, 160, 131, 64, 'false'
  );
  
  -- Ayah 78 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1032,
    'فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُوا۟ فِی دَارِهِمۡ جَـٰثِمِینَ',
    'فاخذتهم الرجفة فاصبحوا في دارهم جاثمين',
    'فَأَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّ<rule class=qalaqah>جۡ</rule>فَةُ فَأَصۡبَحُو<rule class=slnt>اۡ</rule> فِى دَارِهِمۡ جَ<rule class=madda_normal>ـٰ</rule>ثِم<rule class=madda_permissible>ِي</rule>نَ ٧٨',
    78, 8, 2, 160, 131, 64, 'false'
  );
  
  -- Ayah 79 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1033,
    'فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ یَـٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّی وَنَصَحۡتُ لَكُمۡ وَلَـٰكِن لَّا تُحِبُّونَ ٱلنَّـٰصِحِینَ',
    'فتولى عنهم وقال يا قوم لقد ابلغتكم رسالة ربي ونصحت لكم ولكن لا تحبون الناصحين',
    'فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ لَقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=qalaqah>بۡ</rule>لَغۡتُكُمۡ رِسَالَةَ رَبِّى وَنَصَحۡتُ لَكُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تُحِبُّونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>صِح<rule class=madda_permissible>ِي</rule>نَ ٧٩',
    79, 8, 2, 160, 131, 64, 'false'
  );
  
  -- Ayah 80 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1034,
    'وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦۤ أَتَأۡتُونَ ٱلۡفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدࣲ مِّنَ ٱلۡعَـٰلَمِینَ',
    'ولوطا اذ قال لقومه اتاتون الفاحشة ما سبقكم بها من احد من العالمين',
    'وَلُوطًا إِذۡ قَالَ لِقَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَتَأۡتُونَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>حِشَةَ مَا سَبَقَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا مِنۡ أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٨٠',
    80, 8, 2, 160, 131, 64, 'false'
  );
  
  -- Ayah 81 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1035,
    'إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةࣰ مِّن دُونِ ٱلنِّسَاۤءِۚ بَلۡ أَنتُمۡ قَوۡمࣱ مُّسۡرِفُونَ',
    'انكم لتاتون الرجال شهوة من دون النساء بل انتم قوم مسرفون',
    'إِ<rule class=ghunnah>نّ</rule>َكُمۡ لَتَأۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّجَالَ شَهۡوَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ بَلۡ أَ<rule class=ikhafa>نت</rule>ُمۡ قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡرِف<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 8, 2, 160, 131, 64, 'false'
  );
  
  -- Ayah 82 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1036,
    'وَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوۤا۟ أَخۡرِجُوهُم مِّن قَرۡیَتِكُمۡۖ إِنَّهُمۡ أُنَاسࣱ یَتَطَهَّرُونَ',
    'وما كان جواب قومه الا ان قالوا اخرجوهم من قريتكم انهم اناس يتطهرون',
    'وَمَا كَانَ جَوَابَ قَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَخۡرِجُوه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَتِكُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ أُنَا<rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>ي</rule>َتَطَهَّر<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 8, 2, 161, 131, 64, 'false'
  );
  
  -- Ayah 83 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1037,
    'فَأَنجَیۡنَـٰهُ وَأَهۡلَهُۥۤ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَـٰبِرِینَ',
    'فانجيناه واهله الا امراته كانت من الغابرين',
    'فَأَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَأَهۡلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>مۡرَأَتَهُ<rule class=madda_normal>ۥ</rule> كَانَتۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 8, 2, 161, 131, 64, 'false'
  );
  
  -- Ayah 84 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1038,
    'وَأَمۡطَرۡنَا عَلَیۡهِم مَّطَرࣰاۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُجۡرِمِینَ',
    'وامطرنا عليهم مطرا فانظر كيف كان عاقبة المجرمين',
    'وَأَمۡطَرۡنَا عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّطَ<rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٨٤',
    84, 8, 2, 161, 131, 64, 'false'
  );
  
  -- Ayah 85 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1039,
    'وَإِلَىٰ مَدۡیَنَ أَخَاهُمۡ شُعَیۡبࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۖ قَدۡ جَاۤءَتۡكُم بَیِّنَةࣱ مِّن رَّبِّكُمۡۖ فَأَوۡفُوا۟ ٱلۡكَیۡلَ وَٱلۡمِیزَانَ وَلَا تَبۡخَسُوا۟ ٱلنَّاسَ أَشۡیَاۤءَهُمۡ وَلَا تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ بَعۡدَ إِصۡلَـٰحِهَاۚ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِینَ',
    'والى مدين اخاهم شعيبا قال يا قوم اعبدوا الله ما لكم من اله غيره قد جاءتكم بينة من ربكم فاوفوا الكيل والميزان ولا تبخسوا الناس اشياءهم ولا تفسدوا في الارض بعد اصلاحها ذلكم خير لكم ان كنتم مؤمنين',
    'وَإِلَىٰ مَ<rule class=qalaqah>دۡ</rule>يَنَ أَخَاهُمۡ شُعَيۡ<rule class=ikhafa>بًا‌ۗ</rule> <rule class=ikhafa>ق</rule>َالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_normal>ۥ</rule>‌ۖ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيِّنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۖ فَأَوۡفُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكَيۡلَ وَ<rule class=ham_wasl>ٱ</rule>لۡمِيزَانَ وَلَا تَ<rule class=qalaqah>بۡ</rule>خَسُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ أَشۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ وَلَا تُفۡسِدُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بَعۡدَ إِصۡلَ<rule class=madda_normal>ـٰ</rule>حِهَا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 8, 2, 161, 132, 64, 'false'
  );
  
  -- Ayah 86 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1040,
    'وَلَا تَقۡعُدُوا۟ بِكُلِّ صِرَ ٰ⁠طࣲ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِیلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجࣰاۚ وَٱذۡكُرُوۤا۟ إِذۡ كُنتُمۡ قَلِیلࣰا فَكَثَّرَكُمۡۖ وَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُفۡسِدِینَ',
    'ولا تقعدوا بكل صراط توعدون وتصدون عن سبيل الله من امن به وتبغونها عوجا واذكروا اذ كنتم قليلا فكثركم وانظروا كيف كان عاقبة المفسدين',
    'وَلَا تَ<rule class=qalaqah>قۡ</rule>عُدُو<rule class=slnt>اۡ</rule> بِكُلِّ صِر<rule class=madda_normal>ٰ</rule><rule class=ikhafa>طٍ</rule> <rule class=ikhafa>ت</rule>ُوعِدُونَ وَتَصُدُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَنۡ ءَامَنَ بِه<rule class=madda_normal>ِۦ</rule> وَتَ<rule class=qalaqah>بۡ</rule>غُونَهَا عِوَ<rule class=idgham_ghunnah>جًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذۡ كُ<rule class=ikhafa>نت</rule>ُمۡ قَلِيل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>َكَثَّرَكُمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 8, 2, 161, 132, 64, 'false'
  );
  
  -- Ayah 87 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1041,
    'وَإِن كَانَ طَاۤىِٕفَةࣱ مِّنكُمۡ ءَامَنُوا۟ بِٱلَّذِیۤ أُرۡسِلۡتُ بِهِۦ وَطَاۤىِٕفَةࣱ لَّمۡ یُؤۡمِنُوا۟ فَٱصۡبِرُوا۟ حَتَّىٰ یَحۡكُمَ ٱللَّهُ بَیۡنَنَاۚ وَهُوَ خَیۡرُ ٱلۡحَـٰكِمِینَ',
    'وان كان طائفة منكم امنوا بالذي ارسلت به وطائفة لم يؤمنوا فاصبروا حتى يحكم الله بيننا وهو خير الحاكمين',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُرۡسِلۡتُ بِه<rule class=madda_normal>ِۦ</rule> وَط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يُؤۡمِنُو<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule>صۡبِرُو<rule class=slnt>اۡ</rule> حَتَّىٰ يَحۡكُمَ <rule class=ham_wasl>ٱ</rule>للَّهُ بَيۡنَنَا‌ۚ وَهُوَ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>كِم<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 8, 2, 161, 132, 64, 'false'
  );
  
  -- Ayah 88 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1042,
    '۞ قَالَ ٱلۡمَلَأُ ٱلَّذِینَ ٱسۡتَكۡبَرُوا۟ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ یَـٰشُعَیۡبُ وَٱلَّذِینَ ءَامَنُوا۟ مَعَكَ مِن قَرۡیَتِنَاۤ أَوۡ لَتَعُودُنَّ فِی مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَـٰرِهِینَ',
    'قال الملا الذين استكبروا من قومه لنخرجنك يا شعيب والذين امنوا معك من قريتنا او لتعودن في ملتنا قال اولو كنا كارهين',
    '۞قَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_normal>ِۦ</rule> لَنُخۡرِجَ<rule class=ghunnah>نّ</rule>َكَ يَ<rule class=madda_normal>ـٰ</rule>شُعَيۡبُ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَتِن<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ لَتَعُودُ<rule class=ghunnah>نّ</rule>َ فِى مِلَّتِنَا‌ۚ قَالَ أَوَلَوۡ كُ<rule class=ghunnah>نّ</rule>َا كَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=madda_permissible>ِي</rule>نَ ٨٨',
    88, 9, 2, 162, 132, 65, 'false'
  );
  
  -- Ayah 89 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1043,
    'قَدِ ٱفۡتَرَیۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِی مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا یَكُونُ لَنَاۤ أَن نَّعُودَ فِیهَاۤ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَیۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَیۡنَنَا وَبَیۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَیۡرُ ٱلۡفَـٰتِحِینَ',
    'قد افترينا على الله كذبا ان عدنا في ملتكم بعد اذ نجانا الله منها وما يكون لنا ان نعود فيها الا ان يشاء الله ربنا وسع ربنا كل شيء علما على الله توكلنا ربنا افتح بيننا وبين قومنا بالحق وانت خير الفاتحين',
    'قَدِ <rule class=ham_wasl>ٱ</rule>فۡتَرَيۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا إِنۡ عُ<rule class=qalaqah>دۡ</rule>نَا فِى مِلَّتِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡدَ إِذۡ نَجَّ<rule class=madda_normal>ـٰ</rule>نَا <rule class=ham_wasl>ٱ</rule>للَّهُ مِنۡهَا‌ۚ وَمَا يَكُونُ لَن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّعُودَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّنَا‌ۚ وَسِعَ رَبُّنَا كُلَّ شَىۡءٍ عِلۡمًا‌ۚ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تَوَكَّلۡنَا‌ۚ رَبَّنَا <rule class=ham_wasl>ٱ</rule>فۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَأَ<rule class=ikhafa>نت</rule>َ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>تِح<rule class=madda_permissible>ِي</rule>نَ ٨٩',
    89, 9, 2, 162, 132, 65, 'false'
  );
  
  -- Ayah 90 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1044,
    'وَقَالَ ٱلۡمَلَأُ ٱلَّذِینَ كَفَرُوا۟ مِن قَوۡمِهِۦ لَىِٕنِ ٱتَّبَعۡتُمۡ شُعَیۡبًا إِنَّكُمۡ إِذࣰا لَّخَـٰسِرُونَ',
    'وقال الملا الذين كفروا من قومه لئن اتبعتم شعيبا انكم اذا لخاسرون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_normal>ِۦ</rule> لَئِنِ <rule class=ham_wasl>ٱ</rule>تَّبَعۡتُمۡ شُعَيۡبًا إِ<rule class=ghunnah>نّ</rule>َكُمۡ إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٩٠',
    90, 9, 2, 162, 132, 65, 'false'
  );
  
  -- Ayah 91 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1045,
    'فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُوا۟ فِی دَارِهِمۡ جَـٰثِمِینَ',
    'فاخذتهم الرجفة فاصبحوا في دارهم جاثمين',
    'فَأَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّ<rule class=qalaqah>جۡ</rule>فَةُ فَأَصۡبَحُو<rule class=slnt>اۡ</rule> فِى دَارِهِمۡ جَ<rule class=madda_normal>ـٰ</rule>ثِم<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 9, 2, 162, 132, 65, 'false'
  );
  
  -- Ayah 92 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1046,
    'ٱلَّذِینَ كَذَّبُوا۟ شُعَیۡبࣰا كَأَن لَّمۡ یَغۡنَوۡا۟ فِیهَاۚ ٱلَّذِینَ كَذَّبُوا۟ شُعَیۡبࣰا كَانُوا۟ هُمُ ٱلۡخَـٰسِرِینَ',
    'الذين كذبوا شعيبا كان لم يغنوا فيها الذين كذبوا شعيبا كانوا هم الخاسرين',
    'ٱلَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> شُعَيۡ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ك</rule>َأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَغۡنَوۡ<rule class=slnt>اۡ</rule> فِيهَا‌ۚ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> شُعَيۡ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٩٢',
    92, 9, 2, 162, 132, 65, 'false'
  );
  
  -- Ayah 93 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1047,
    'فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ یَـٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَـٰلَـٰتِ رَبِّی وَنَصَحۡتُ لَكُمۡۖ فَكَیۡفَ ءَاسَىٰ عَلَىٰ قَوۡمࣲ كَـٰفِرِینَ',
    'فتولى عنهم وقال يا قوم لقد ابلغتكم رسالات ربي ونصحت لكم فكيف اسى على قوم كافرين',
    'فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ لَقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=qalaqah>بۡ</rule>لَغۡتُكُمۡ رِسَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّى وَنَصَحۡتُ لَكُمۡ‌ۖ فَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ك</rule>َ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٩٣',
    93, 9, 2, 162, 132, 65, 'false'
  );
  
  -- Ayah 94 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1048,
    'وَمَاۤ أَرۡسَلۡنَا فِی قَرۡیَةࣲ مِّن نَّبِیٍّ إِلَّاۤ أَخَذۡنَاۤ أَهۡلَهَا بِٱلۡبَأۡسَاۤءِ وَٱلضَّرَّاۤءِ لَعَلَّهُمۡ یَضَّرَّعُونَ',
    'وما ارسلنا في قرية من نبي الا اخذنا اهلها بالباساء والضراء لعلهم يضرعون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا فِى قَرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّبِىٍّ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَخَذۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَهۡلَهَا بِ<rule class=ham_wasl>ٱ</rule>لۡبَأۡس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ لَعَلَّهُمۡ يَضَّرَّع<rule class=madda_permissible>ُو</rule>نَ ٩٤',
    94, 9, 2, 162, 133, 65, 'false'
  );
  
  -- Ayah 95 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1049,
    'ثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّیِّئَةِ ٱلۡحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدۡ مَسَّ ءَابَاۤءَنَا ٱلضَّرَّاۤءُ وَٱلسَّرَّاۤءُ فَأَخَذۡنَـٰهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ',
    'ثم بدلنا مكان السيئة الحسنة حتى عفوا وقالوا قد مس اباءنا الضراء والسراء فاخذناهم بغتة وهم لا يشعرون',
    'ثُ<rule class=ghunnah>مّ</rule>َ بَدَّلۡنَا مَكَانَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةِ <rule class=ham_wasl>ٱ</rule>لۡحَسَنَةَ حَتَّىٰ عَفَو<rule class=slnt>اۡ</rule> وَّقَالُو<rule class=slnt>اۡ</rule> قَ<rule class=qalaqah>دۡ</rule> مَسَّ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فَأَخَذۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َغۡتَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٩٥',
    95, 9, 2, 162, 133, 65, 'false'
  );
  
  -- Ayah 96 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1050,
    'وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰۤ ءَامَنُوا۟ وَٱتَّقَوۡا۟ لَفَتَحۡنَا عَلَیۡهِم بَرَكَـٰتࣲ مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ وَلَـٰكِن كَذَّبُوا۟ فَأَخَذۡنَـٰهُم بِمَا كَانُوا۟ یَكۡسِبُونَ',
    'ولو ان اهل القرى امنوا واتقوا لفتحنا عليهم بركات من السماء والارض ولكن كذبوا فاخذناهم بما كانوا يكسبون',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َ أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡقُرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> لَفَتَحۡنَا عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>َرَكَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبُو<rule class=slnt>اۡ</rule> فَأَخَذۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 9, 2, 163, 133, 65, 'false'
  );
  
  -- Ayah 97 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1051,
    'أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰۤ أَن یَأۡتِیَهُم بَأۡسُنَا بَیَـٰتࣰا وَهُمۡ نَاۤىِٕمُونَ',
    'افامن اهل القرى ان ياتيهم باسنا بياتا وهم نائمون',
    'أَفَأَمِنَ أَهۡلُ <rule class=ham_wasl>ٱ</rule>لۡقُرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َأۡسُنَا بَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تًا</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ ن<rule class=madda_obligatory_mottasel>َا</rule>ٓئِم<rule class=madda_permissible>ُو</rule>نَ ٩٧',
    97, 9, 2, 163, 133, 65, 'false'
  );
  
  -- Ayah 98 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1052,
    'أَوَأَمِنَ أَهۡلُ ٱلۡقُرَىٰۤ أَن یَأۡتِیَهُم بَأۡسُنَا ضُحࣰى وَهُمۡ یَلۡعَبُونَ',
    'اوامن اهل القرى ان ياتيهم باسنا ضحى وهم يلعبون',
    'أَوَأَمِنَ أَهۡلُ <rule class=ham_wasl>ٱ</rule>لۡقُرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َأۡسُنَا ضُ<rule class=idgham_ghunnah>حًى</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ يَلۡعَب<rule class=madda_permissible>ُو</rule>نَ ٩٨',
    98, 9, 2, 163, 133, 65, 'false'
  );
  
  -- Ayah 99 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1053,
    'أَفَأَمِنُوا۟ مَكۡرَ ٱللَّهِۚ فَلَا یَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَـٰسِرُونَ',
    'افامنوا مكر الله فلا يامن مكر الله الا القوم الخاسرون',
    'أَفَأَمِنُو<rule class=slnt>اۡ</rule> مَكۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ فَلَا يَأۡمَنُ مَكۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡقَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٩٩',
    99, 9, 2, 163, 133, 65, 'false'
  );
  
  -- Ayah 100 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1054,
    'أَوَلَمۡ یَهۡدِ لِلَّذِینَ یَرِثُونَ ٱلۡأَرۡضَ مِنۢ بَعۡدِ أَهۡلِهَاۤ أَن لَّوۡ نَشَاۤءُ أَصَبۡنَـٰهُم بِذُنُوبِهِمۡۚ وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَسۡمَعُونَ',
    'اولم يهد للذين يرثون الارض من بعد اهلها ان لو نشاء اصبناهم بذنوبهم ونطبع على قلوبهم فهم لا يسمعون',
    'أَوَلَمۡ يَهۡدِ لِلَّذِينَ يَرِثُونَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ أَهۡلِه<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡ نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ أَصَ<rule class=qalaqah>بۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذُنُوبِهِمۡ‌ۚ وَنَ<rule class=qalaqah>طۡ</rule>بَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَسۡمَع<rule class=madda_permissible>ُو</rule>نَ ١٠٠',
    100, 9, 2, 163, 134, 65, 'false'
  );
  
  -- Ayah 101 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1055,
    'تِلۡكَ ٱلۡقُرَىٰ نَقُصُّ عَلَیۡكَ مِنۡ أَنۢبَاۤىِٕهَاۚ وَلَقَدۡ جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَمَا كَانُوا۟ لِیُؤۡمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبۡلُۚ كَذَ ٰ⁠لِكَ یَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلۡكَـٰفِرِینَ',
    'تلك القرى نقص عليك من انبائها ولقد جاءتهم رسلهم بالبينات فما كانوا ليؤمنوا بما كذبوا من قبل كذلك يطبع الله على قلوب الكافرين',
    'تِلۡكَ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ نَقُصُّ عَلَيۡكَ مِنۡ أَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِهَا‌ۚ وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَمَا كَانُو<rule class=slnt>اۡ</rule> لِيُؤۡمِنُو<rule class=slnt>اۡ</rule> بِمَا كَذَّبُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَ<rule class=qalaqah>طۡ</rule>بَعُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ قُلُوبِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٠١',
    101, 9, 2, 163, 134, 65, 'false'
  );
  
  -- Ayah 102 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1056,
    'وَمَا وَجَدۡنَا لِأَكۡثَرِهِم مِّنۡ عَهۡدࣲۖ وَإِن وَجَدۡنَاۤ أَكۡثَرَهُمۡ لَفَـٰسِقِینَ',
    'وما وجدنا لاكثرهم من عهد وان وجدنا اكثرهم لفاسقين',
    'وَمَا وَجَ<rule class=qalaqah>دۡ</rule>نَا لِأَكۡثَرِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَهۡ<rule class=idgham_ghunnah>دٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َجَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡثَرَهُمۡ لَفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ١٠٢',
    102, 9, 2, 163, 134, 65, 'false'
  );
  
  -- Ayah 103 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1057,
    'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ بِـَٔایَـٰتِنَاۤ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ فَظَلَمُوا۟ بِهَاۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُفۡسِدِینَ',
    'ثم بعثنا من بعدهم موسى باياتنا الى فرعون وملئه فظلموا بها فانظر كيف كان عاقبة المفسدين',
    'ثُ<rule class=ghunnah>مّ</rule>َ بَعَثۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّوسَىٰ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ فِرۡعَوۡنَ وَمَلَإِ<rule class=slnt>يۡ</rule>ه<rule class=madda_normal>ِۦ</rule> فَظَلَمُو<rule class=slnt>اۡ</rule> بِهَا‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ١٠٣',
    103, 9, 2, 163, 134, 65, 'false'
  );
  
  -- Ayah 104 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1058,
    'وَقَالَ مُوسَىٰ یَـٰفِرۡعَوۡنُ إِنِّی رَسُولࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ',
    'وقال موسى يا فرعون اني رسول من رب العالمين',
    'وَقَالَ مُوسَىٰ يَ<rule class=madda_normal>ـٰ</rule>فِرۡعَوۡنُ إِ<rule class=ghunnah>نّ</rule>ِى رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٠٤',
    104, 9, 2, 163, 134, 65, 'false'
  );
  
  -- Ayah 105 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1059,
    'حَقِیقٌ عَلَىٰۤ أَن لَّاۤ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ قَدۡ جِئۡتُكُم بِبَیِّنَةࣲ مِّن رَّبِّكُمۡ فَأَرۡسِلۡ مَعِیَ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ',
    'حقيق على ان لا اقول على الله الا الحق قد جئتكم ببينة من ربكم فارسل معي بني اسرائيل',
    'حَقِيقٌ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَقُولَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡحَقَّ‌ۚ قَ<rule class=qalaqah>دۡ</rule> جِئۡتُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ فَأَرۡسِلۡ مَعِىَ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓء<rule class=madda_permissible>ِي</rule>لَ ١٠٥',
    105, 9, 2, 164, 134, 65, 'false'
  );
  
  -- Ayah 106 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1060,
    'قَالَ إِن كُنتَ جِئۡتَ بِـَٔایَةࣲ فَأۡتِ بِهَاۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'قال ان كنت جئت باية فات بها ان كنت من الصادقين',
    'قَالَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ جِئۡتَ بِـَٔـايَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َأۡتِ بِه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٠٦',
    106, 9, 2, 164, 134, 65, 'false'
  );
  
  -- Ayah 107 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1061,
    'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِیَ ثُعۡبَانࣱ مُّبِینࣱ',
    'فالقى عصاه فاذا هي ثعبان مبين',
    'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعۡبَا<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٠٧',
    107, 9, 2, 164, 134, 65, 'false'
  );
  
  -- Ayah 108 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1062,
    'وَنَزَعَ یَدَهُۥ فَإِذَا هِیَ بَیۡضَاۤءُ لِلنَّـٰظِرِینَ',
    'ونزع يده فاذا هي بيضاء للناظرين',
    'وَنَزَعَ يَدَهُ<rule class=madda_normal>ۥ</rule> فَإِذَا هِىَ بَيۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لِل<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>ظِر<rule class=madda_permissible>ِي</rule>نَ ١٠٨',
    108, 9, 2, 164, 134, 65, 'false'
  );
  
  -- Ayah 109 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1063,
    'قَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِیمࣱ',
    'قال الملا من قوم فرعون ان هذا لساحر عليم',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِ فِرۡعَوۡنَ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَسَ<rule class=madda_normal>ـٰ</rule>حِرٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٠٩',
    109, 9, 2, 164, 135, 65, 'false'
  );
  
  -- Ayah 110 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1064,
    'یُرِیدُ أَن یُخۡرِجَكُم مِّنۡ أَرۡضِكُمۡۖ فَمَاذَا تَأۡمُرُونَ',
    'يريد ان يخرجكم من ارضكم فماذا تامرون',
    'يُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡرِجَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَرۡضِكُمۡ‌ۖ فَمَاذَا تَأۡمُر<rule class=madda_permissible>ُو</rule>نَ ١١٠',
    110, 9, 2, 164, 135, 65, 'false'
  );
  
  -- Ayah 111 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1065,
    'قَالُوۤا۟ أَرۡجِهۡ وَأَخَاهُ وَأَرۡسِلۡ فِی ٱلۡمَدَاۤىِٕنِ حَـٰشِرِینَ',
    'قالوا ارجه واخاه وارسل في المدائن حاشرين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَرۡجِهۡ وَأَخَاهُ وَأَرۡسِلۡ فِى <rule class=ham_wasl>ٱ</rule>لۡمَد<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنِ حَ<rule class=madda_normal>ـٰ</rule>شِر<rule class=madda_permissible>ِي</rule>نَ ١١١',
    111, 9, 2, 164, 135, 65, 'false'
  );
  
  -- Ayah 112 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1066,
    'یَأۡتُوكَ بِكُلِّ سَـٰحِرٍ عَلِیمࣲ',
    'ياتوك بكل ساحر عليم',
    'يَأۡتُوكَ بِكُلِّ سَ<rule class=madda_normal>ـٰ</rule>حِرٍ عَل<rule class=madda_permissible>ِي</rule>مٍ ١١٢',
    112, 9, 2, 164, 135, 65, 'false'
  );
  
  -- Ayah 113 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1067,
    'وَجَاۤءَ ٱلسَّحَرَةُ فِرۡعَوۡنَ قَالُوۤا۟ إِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَـٰلِبِینَ',
    'وجاء السحرة فرعون قالوا ان لنا لاجرا ان كنا نحن الغالبين',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَرَةُ فِرۡعَوۡنَ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ لَنَا لَأَ<rule class=qalaqah>جۡ</rule>رًا إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا نَحۡنُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>لِب<rule class=madda_permissible>ِي</rule>نَ ١١٣',
    113, 9, 2, 164, 135, 65, 'false'
  );
  
  -- Ayah 114 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1068,
    'قَالَ نَعَمۡ وَإِنَّكُمۡ لَمِنَ ٱلۡمُقَرَّبِینَ',
    'قال نعم وانكم لمن المقربين',
    'قَالَ نَعَمۡ وَإِ<rule class=ghunnah>نّ</rule>َكُمۡ لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡمُقَرَّب<rule class=madda_permissible>ِي</rule>نَ ١١٤',
    114, 9, 2, 164, 135, 65, 'false'
  );
  
  -- Ayah 115 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1069,
    'قَالُوا۟ یَـٰمُوسَىٰۤ إِمَّاۤ أَن تُلۡقِیَ وَإِمَّاۤ أَن نَّكُونَ نَحۡنُ ٱلۡمُلۡقِینَ',
    'قالوا يا موسى اما ان تلقي واما ان نكون نحن الملقين',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُلۡقِىَ وَإِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّكُونَ نَحۡنُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡق<rule class=madda_permissible>ِي</rule>نَ ١١٥',
    115, 9, 2, 164, 135, 65, 'false'
  );
  
  -- Ayah 116 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1070,
    'قَالَ أَلۡقُوا۟ۖ فَلَمَّاۤ أَلۡقَوۡا۟ سَحَرُوۤا۟ أَعۡیُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ وَجَاۤءُو بِسِحۡرٍ عَظِیمࣲ',
    'قال القوا فلما القوا سحروا اعين الناس واسترهبوهم وجاءوا بسحر عظيم',
    'قَالَ أَلۡقُو<rule class=slnt>اۡ‌ۖ</rule> فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَلۡقَوۡ<rule class=slnt>اۡ</rule> سَحَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَعۡيُنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَ<rule class=ham_wasl>ٱ</rule>سۡتَرۡهَبُوهُمۡ وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو بِسِحۡرٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ١١٦',
    116, 9, 2, 164, 135, 65, 'false'
  );
  
  -- Ayah 117 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1071,
    '۞ وَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنۡ أَلۡقِ عَصَاكَۖ فَإِذَا هِیَ تَلۡقَفُ مَا یَأۡفِكُونَ',
    'واوحينا الى موسى ان الق عصاك فاذا هي تلقف ما يافكون',
    '۞وَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَنۡ أَلۡقِ عَصَاكَ‌ۖ فَإِذَا هِىَ تَلۡقَفُ مَا يَأۡفِك<rule class=madda_permissible>ُو</rule>نَ ١١٧',
    117, 9, 2, 164, 135, 66, 'false'
  );
  
  -- Ayah 118 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1072,
    'فَوَقَعَ ٱلۡحَقُّ وَبَطَلَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'فوقع الحق وبطل ما كانوا يعملون',
    'فَوَقَعَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَبَطَلَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١١٨',
    118, 9, 2, 164, 135, 66, 'false'
  );
  
  -- Ayah 119 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1073,
    'فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَـٰغِرِینَ',
    'فغلبوا هنالك وانقلبوا صاغرين',
    'فَغُلِبُو<rule class=slnt>اۡ</rule> هُنَالِكَ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>َلَبُو<rule class=slnt>اۡ</rule> صَ<rule class=madda_normal>ـٰ</rule>غِر<rule class=madda_permissible>ِي</rule>نَ ١١٩',
    119, 9, 2, 164, 135, 66, 'false'
  );
  
  -- Ayah 120 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1074,
    'وَأُلۡقِیَ ٱلسَّحَرَةُ سَـٰجِدِینَ',
    'والقي السحرة ساجدين',
    'وَأُلۡقِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَرَةُ سَ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ١٢٠',
    120, 9, 2, 164, 135, 66, 'false'
  );
  
  -- Ayah 121 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1075,
    'قَالُوۤا۟ ءَامَنَّا بِرَبِّ ٱلۡعَـٰلَمِینَ',
    'قالوا امنا برب العالمين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٢١',
    121, 9, 2, 165, 135, 66, 'false'
  );
  
  -- Ayah 122 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1076,
    'رَبِّ مُوسَىٰ وَهَـٰرُونَ',
    'رب موسى وهارون',
    'رَبِّ مُوسَىٰ وَهَ<rule class=madda_normal>ـٰ</rule>ر<rule class=madda_permissible>ُو</rule>نَ ١٢٢',
    122, 9, 2, 165, 135, 66, 'false'
  );
  
  -- Ayah 123 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1077,
    'قَالَ فِرۡعَوۡنُ ءَامَنتُم بِهِۦ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّ هَـٰذَا لَمَكۡرࣱ مَّكَرۡتُمُوهُ فِی ٱلۡمَدِینَةِ لِتُخۡرِجُوا۟ مِنۡهَاۤ أَهۡلَهَاۖ فَسَوۡفَ تَعۡلَمُونَ',
    'قال فرعون امنتم به قبل ان اذن لكم ان هذا لمكر مكرتموه في المدينة لتخرجوا منها اهلها فسوف تعلمون',
    'قَالَ فِرۡعَوۡنُ ءَامَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> قَ<rule class=qalaqah>بۡ</rule>لَ أَنۡ ءَاذَنَ لَكُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَمَكۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>َّكَرۡتُمُوهُ فِى <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ لِتُخۡرِجُو<rule class=slnt>اۡ</rule> مِنۡه<rule class=madda_obligatory_monfasel>َآ</rule> أَهۡلَهَا‌ۖ فَسَوۡفَ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٢٣',
    123, 9, 2, 165, 135, 66, 'false'
  );
  
  -- Ayah 124 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1078,
    'لَأُقَطِّعَنَّ أَیۡدِیَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَـٰفࣲ ثُمَّ لَأُصَلِّبَنَّكُمۡ أَجۡمَعِینَ',
    'لاقطعن ايديكم وارجلكم من خلاف ثم لاصلبنكم اجمعين',
    'لَأُقَطِّعَ<rule class=ghunnah>نّ</rule>َ أَيۡدِيَكُمۡ وَأَرۡجُلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خِلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>فٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ لَأُصَلِّبَ<rule class=ghunnah>نّ</rule>َكُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ١٢٤',
    124, 9, 2, 165, 135, 66, 'false'
  );
  
  -- Ayah 125 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1079,
    'قَالُوۤا۟ إِنَّاۤ إِلَىٰ رَبِّنَا مُنقَلِبُونَ',
    'قالوا انا الى ربنا منقلبون',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ رَبِّنَا مُ<rule class=ikhafa>نق</rule>َلِب<rule class=madda_permissible>ُو</rule>نَ ١٢٥',
    125, 9, 2, 165, 135, 66, 'false'
  );
  
  -- Ayah 126 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1080,
    'وَمَا تَنقِمُ مِنَّاۤ إِلَّاۤ أَنۡ ءَامَنَّا بِـَٔایَـٰتِ رَبِّنَا لَمَّا جَاۤءَتۡنَاۚ رَبَّنَاۤ أَفۡرِغۡ عَلَیۡنَا صَبۡرࣰا وَتَوَفَّنَا مُسۡلِمِینَ',
    'وما تنقم منا الا ان امنا بايات ربنا لما جاءتنا ربنا افرغ علينا صبرا وتوفنا مسلمين',
    'وَمَا تَ<rule class=ikhafa>نق</rule>ِمُ مِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡ ءَامَ<rule class=ghunnah>نّ</rule>َا بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّنَا لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡنَا‌ۚ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَفۡرِغۡ عَلَيۡنَا صَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َتَوَفَّنَا مُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ١٢٦',
    126, 9, 2, 165, 135, 66, 'false'
  );
  
  -- Ayah 127 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1081,
    'وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ أَتَذَرُ مُوسَىٰ وَقَوۡمَهُۥ لِیُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ وَیَذَرَكَ وَءَالِهَتَكَۚ قَالَ سَنُقَتِّلُ أَبۡنَاۤءَهُمۡ وَنَسۡتَحۡیِۦ نِسَاۤءَهُمۡ وَإِنَّا فَوۡقَهُمۡ قَـٰهِرُونَ',
    'وقال الملا من قوم فرعون اتذر موسى وقومه ليفسدوا في الارض ويذرك والهتك قال سنقتل ابناءهم ونستحيي نساءهم وانا فوقهم قاهرون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِ فِرۡعَوۡنَ أَتَذَرُ مُوسَىٰ وَقَوۡمَهُ<rule class=madda_normal>ۥ</rule> لِيُفۡسِدُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَيَذَرَكَ وَءَالِهَتَكَ‌ۚ قَالَ سَنُقَتِّلُ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ وَنَسۡتَحۡى<rule class=madda_normal>ِۦ</rule> نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ وَإِ<rule class=ghunnah>نّ</rule>َا فَوۡقَهُمۡ قَ<rule class=madda_normal>ـٰ</rule>هِر<rule class=madda_permissible>ُو</rule>نَ ١٢٧',
    127, 9, 2, 165, 136, 66, 'false'
  );
  
  -- Ayah 128 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1082,
    'قَالَ مُوسَىٰ لِقَوۡمِهِ ٱسۡتَعِینُوا۟ بِٱللَّهِ وَٱصۡبِرُوۤا۟ۖ إِنَّ ٱلۡأَرۡضَ لِلَّهِ یُورِثُهَا مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۖ وَٱلۡعَـٰقِبَةُ لِلۡمُتَّقِینَ',
    'قال موسى لقومه استعينوا بالله واصبروا ان الارض لله يورثها من يشاء من عباده والعاقبة للمتقين',
    'قَالَ مُوسَىٰ لِقَوۡمِهِ <rule class=ham_wasl>ٱ</rule>سۡتَعِينُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>صۡبِر<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ لِلَّهِ يُورِثُهَا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>قِبَةُ لِلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ١٢٨',
    128, 9, 2, 165, 136, 66, 'false'
  );
  
  -- Ayah 129 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1083,
    'قَالُوۤا۟ أُوذِینَا مِن قَبۡلِ أَن تَأۡتِیَنَا وَمِنۢ بَعۡدِ مَا جِئۡتَنَاۚ قَالَ عَسَىٰ رَبُّكُمۡ أَن یُهۡلِكَ عَدُوَّكُمۡ وَیَسۡتَخۡلِفَكُمۡ فِی ٱلۡأَرۡضِ فَیَنظُرَ كَیۡفَ تَعۡمَلُونَ',
    'قالوا اوذينا من قبل ان تاتينا ومن بعد ما جئتنا قال عسى ربكم ان يهلك عدوكم ويستخلفكم في الارض فينظر كيف تعملون',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أُوذِينَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡتِيَنَا وَم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا جِئۡتَنَا‌ۚ قَالَ عَسَىٰ رَبُّكُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُهۡلِكَ عَدُوَّكُمۡ وَيَسۡتَخۡلِفَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَيَ<rule class=ikhafa>نظ</rule>ُرَ كَيۡفَ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٢٩',
    129, 9, 2, 165, 136, 66, 'false'
  );
  
  -- Ayah 130 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1084,
    'وَلَقَدۡ أَخَذۡنَاۤ ءَالَ فِرۡعَوۡنَ بِٱلسِّنِینَ وَنَقۡصࣲ مِّنَ ٱلثَّمَرَ ٰ⁠تِ لَعَلَّهُمۡ یَذَّكَّرُونَ',
    'ولقد اخذنا ال فرعون بالسنين ونقص من الثمرات لعلهم يذكرون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَخَذۡن<rule class=madda_obligatory_monfasel>َآ</rule> ءَالَ فِرۡعَوۡنَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّنِينَ وَنَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>صٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ لَعَلَّهُمۡ يَذَّكَّر<rule class=madda_permissible>ُو</rule>نَ ١٣٠',
    130, 9, 2, 165, 137, 66, 'false'
  );
  
  -- Ayah 131 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1085,
    'فَإِذَا جَاۤءَتۡهُمُ ٱلۡحَسَنَةُ قَالُوا۟ لَنَا هَـٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَیِّئَةࣱ یَطَّیَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥۤۗ أَلَاۤ إِنَّمَا طَـٰۤىِٕرُهُمۡ عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'فاذا جاءتهم الحسنة قالوا لنا هذه وان تصبهم سيئة يطيروا بموسى ومن معه الا انما طائرهم عند الله ولكن اكثرهم لا يعلمون',
    'فَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَسَنَةُ قَالُو<rule class=slnt>اۡ</rule> لَنَا هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِ<rule class=qalaqah>بۡ</rule>هُمۡ سَيِّئَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َطَّيَّرُو<rule class=slnt>اۡ</rule> بِمُوسَىٰ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۗ</rule> أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا طَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرُهُمۡ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٣١',
    131, 9, 2, 166, 137, 66, 'false'
  );
  
  -- Ayah 132 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1086,
    'وَقَالُوا۟ مَهۡمَا تَأۡتِنَا بِهِۦ مِنۡ ءَایَةࣲ لِّتَسۡحَرَنَا بِهَا فَمَا نَحۡنُ لَكَ بِمُؤۡمِنِینَ',
    'وقالوا مهما تاتنا به من اية لتسحرنا بها فما نحن لك بمؤمنين',
    'وَقَالُو<rule class=slnt>اۡ</rule> مَهۡمَا تَأۡتِنَا بِه<rule class=madda_normal>ِۦ</rule> مِنۡ ءَايَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتَسۡحَرَنَا بِهَا فَمَا نَحۡنُ لَكَ بِمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٣٢',
    132, 9, 2, 166, 137, 66, 'false'
  );
  
  -- Ayah 133 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1087,
    'فَأَرۡسَلۡنَا عَلَیۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَایَـٰتࣲ مُّفَصَّلَـٰتࣲ فَٱسۡتَكۡبَرُوا۟ وَكَانُوا۟ قَوۡمࣰا مُّجۡرِمِینَ',
    'فارسلنا عليهم الطوفان والجراد والقمل والضفادع والدم ايات مفصلات فاستكبروا وكانوا قوما مجرمين',
    'فَأَرۡسَلۡنَا عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّوفَانَ وَ<rule class=ham_wasl>ٱ</rule>لۡجَرَادَ وَ<rule class=ham_wasl>ٱ</rule>لۡقُ<rule class=ghunnah>مّ</rule>َلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّفَادِعَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّمَ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّفَصَّلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> وَكَانُو<rule class=slnt>اۡ</rule> قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ١٣٣',
    133, 9, 2, 166, 137, 66, 'false'
  );
  
  -- Ayah 134 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1088,
    'وَلَمَّا وَقَعَ عَلَیۡهِمُ ٱلرِّجۡزُ قَالُوا۟ یَـٰمُوسَى ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَۖ لَىِٕن كَشَفۡتَ عَنَّا ٱلرِّجۡزَ لَنُؤۡمِنَنَّ لَكَ وَلَنُرۡسِلَنَّ مَعَكَ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ',
    'ولما وقع عليهم الرجز قالوا يا موسى ادع لنا ربك بما عهد عندك لئن كشفت عنا الرجز لنؤمنن لك ولنرسلن معك بني اسرائيل',
    'وَلَ<rule class=ghunnah>مّ</rule>َا وَقَعَ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّ<rule class=qalaqah>جۡ</rule>زُ قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>مُوسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ لَنَا رَبَّكَ بِمَا عَهِدَ عِ<rule class=ikhafa>ند</rule>َكَ‌ۖ لَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َشَفۡتَ عَ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّ<rule class=qalaqah>جۡ</rule>زَ لَنُؤۡمِنَ<rule class=ghunnah>نّ</rule>َ لَكَ وَلَنُرۡسِلَ<rule class=ghunnah>نّ</rule>َ مَعَكَ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓء<rule class=madda_permissible>ِي</rule>لَ ١٣٤',
    134, 9, 2, 166, 137, 66, 'false'
  );
  
  -- Ayah 135 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1089,
    'فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلرِّجۡزَ إِلَىٰۤ أَجَلٍ هُم بَـٰلِغُوهُ إِذَا هُمۡ یَنكُثُونَ',
    'فلما كشفنا عنهم الرجز الى اجل هم بالغوه اذا هم ينكثون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا كَشَفۡنَا عَنۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّ<rule class=qalaqah>جۡ</rule>زَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَلٍ ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َ<rule class=madda_normal>ـٰ</rule>لِغُوهُ إِذَا هُمۡ يَ<rule class=ikhafa>نك</rule>ُث<rule class=madda_permissible>ُو</rule>نَ ١٣٥',
    135, 9, 2, 166, 137, 66, 'false'
  );
  
  -- Ayah 136 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1090,
    'فَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَـٰهُمۡ فِی ٱلۡیَمِّ بِأَنَّهُمۡ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَكَانُوا۟ عَنۡهَا غَـٰفِلِینَ',
    'فانتقمنا منهم فاغرقناهم في اليم بانهم كذبوا باياتنا وكانوا عنها غافلين',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َقَمۡنَا مِنۡهُمۡ فَأَغۡرَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡيَ<rule class=ghunnah>مّ</rule>ِ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَكَانُو<rule class=slnt>اۡ</rule> عَنۡهَا غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ١٣٦',
    136, 9, 2, 166, 137, 66, 'false'
  );
  
  -- Ayah 137 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1091,
    'وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِینَ كَانُوا۟ یُسۡتَضۡعَفُونَ مَشَـٰرِقَ ٱلۡأَرۡضِ وَمَغَـٰرِبَهَا ٱلَّتِی بَـٰرَكۡنَا فِیهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ بِمَا صَبَرُوا۟ۖ وَدَمَّرۡنَا مَا كَانَ یَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُوا۟ یَعۡرِشُونَ',
    'واورثنا القوم الذين كانوا يستضعفون مشارق الارض ومغاربها التي باركنا فيها وتمت كلمت ربك الحسنى على بني اسرائيل بما صبروا ودمرنا ما كان يصنع فرعون وقومه وما كانوا يعرشون',
    'وَأَوۡرَثۡنَا <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَانُو<rule class=slnt>اۡ</rule> يُسۡتَضۡعَفُونَ مَشَ<rule class=madda_normal>ـٰ</rule>رِقَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَغَ<rule class=madda_normal>ـٰ</rule>رِبَهَا <rule class=ham_wasl>ٱ</rule>لَّتِى بَ<rule class=madda_normal>ـٰ</rule>رَكۡنَا فِيهَا‌ۖ وَتَ<rule class=ghunnah>مّ</rule>َتۡ كَلِمَتُ رَبِّكَ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ عَلَىٰ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ بِمَا صَبَرُو<rule class=slnt>اۡ‌ۖ</rule> وَدَ<rule class=ghunnah>مّ</rule>َرۡنَا مَا كَانَ يَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُ<rule class=madda_normal>ۥ</rule> وَمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡرِش<rule class=madda_permissible>ُو</rule>نَ ١٣٧',
    137, 9, 2, 166, 137, 66, 'false'
  );
  
  -- Ayah 138 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1092,
    'وَجَـٰوَزۡنَا بِبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱلۡبَحۡرَ فَأَتَوۡا۟ عَلَىٰ قَوۡمࣲ یَعۡكُفُونَ عَلَىٰۤ أَصۡنَامࣲ لَّهُمۡۚ قَالُوا۟ یَـٰمُوسَى ٱجۡعَل لَّنَاۤ إِلَـٰهࣰا كَمَا لَهُمۡ ءَالِهَةࣱۚ قَالَ إِنَّكُمۡ قَوۡمࣱ تَجۡهَلُونَ',
    'وجاوزنا ببني اسرائيل البحر فاتوا على قوم يعكفون على اصنام لهم قالوا يا موسى اجعل لنا الها كما لهم الهة قال انكم قوم تجهلون',
    'وَجَ<rule class=madda_normal>ـٰ</rule>وَزۡنَا بِبَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَ فَأَتَوۡ<rule class=slnt>اۡ</rule> عَلَىٰ قَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡكُفُونَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَصۡنَا<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ‌ۚ قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>مُوسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَل لَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>هًا</rule> <rule class=ikhafa>ك</rule>َمَا لَهُمۡ ءَالِهَ<rule class=ikhafa>ةٌ‌ۚ</rule> <rule class=ikhafa>ق</rule>َالَ إِ<rule class=ghunnah>نّ</rule>َكُمۡ قَوۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>هَل<rule class=madda_permissible>ُو</rule>نَ ١٣٨',
    138, 9, 2, 167, 137, 66, 'false'
  );
  
  -- Ayah 139 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1093,
    'إِنَّ هَـٰۤؤُلَاۤءِ مُتَبَّرࣱ مَّا هُمۡ فِیهِ وَبَـٰطِلࣱ مَّا كَانُوا۟ یَعۡمَلُونَ',
    'ان هؤلاء متبر ما هم فيه وباطل ما كانوا يعملون',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مُتَبَّ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا هُمۡ فِيهِ وَبَ<rule class=madda_normal>ـٰ</rule>طِ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٣٩',
    139, 9, 2, 167, 137, 66, 'false'
  );
  
  -- Ayah 140 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1094,
    'قَالَ أَغَیۡرَ ٱللَّهِ أَبۡغِیكُمۡ إِلَـٰهࣰا وَهُوَ فَضَّلَكُمۡ عَلَى ٱلۡعَـٰلَمِینَ',
    'قال اغير الله ابغيكم الها وهو فضلكم على العالمين',
    'قَالَ أَغَيۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ أَ<rule class=qalaqah>بۡ</rule>غِيكُمۡ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ فَضَّلَكُمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٤٠',
    140, 9, 2, 167, 137, 66, 'false'
  );
  
  -- Ayah 141 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1095,
    'وَإِذۡ أَنجَیۡنَـٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ یَسُومُونَكُمۡ سُوۤءَ ٱلۡعَذَابِ یُقَتِّلُونَ أَبۡنَاۤءَكُمۡ وَیَسۡتَحۡیُونَ نِسَاۤءَكُمۡۚ وَفِی ذَ ٰ⁠لِكُم بَلَاۤءࣱ مِّن رَّبِّكُمۡ عَظِیمࣱ',
    'واذ انجيناكم من ال فرعون يسومونكم سوء العذاب يقتلون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم',
    'وَإِذۡ أَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ‌ۖ يُقَتِّلُونَ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ وَيَسۡتَحۡيُونَ نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ‌ۚ وَفِى ذ<rule class=madda_normal>ٰ</rule>لِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َل<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٤١',
    141, 9, 2, 167, 137, 66, 'false'
  );
  
  -- Ayah 142 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1096,
    '۞ وَوَ ٰ⁠عَدۡنَا مُوسَىٰ ثَلَـٰثِینَ لَیۡلَةࣰ وَأَتۡمَمۡنَـٰهَا بِعَشۡرࣲ فَتَمَّ مِیقَـٰتُ رَبِّهِۦۤ أَرۡبَعِینَ لَیۡلَةࣰۚ وَقَالَ مُوسَىٰ لِأَخِیهِ هَـٰرُونَ ٱخۡلُفۡنِی فِی قَوۡمِی وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِیلَ ٱلۡمُفۡسِدِینَ',
    'وواعدنا موسى ثلاثين ليلة واتممناها بعشر فتم ميقات ربه اربعين ليلة وقال موسى لاخيه هارون اخلفني في قومي واصلح ولا تتبع سبيل المفسدين',
    '۞وَو<rule class=madda_normal>ٰ</rule>عَ<rule class=qalaqah>دۡ</rule>نَا مُوسَىٰ ثَلَ<rule class=madda_normal>ـٰ</rule>ثِينَ لَيۡلَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَتۡمَمۡنَ<rule class=madda_normal>ـٰ</rule>هَا بِعَشۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َتَ<rule class=ghunnah>مّ</rule>َ مِيقَ<rule class=madda_normal>ـٰ</rule>تُ رَبِّه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَرۡبَعِينَ لَيۡلَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ مُوسَىٰ لِأَخِيهِ هَ<rule class=madda_normal>ـٰ</rule>رُونَ <rule class=ham_wasl>ٱ</rule>خۡلُفۡنِى فِى قَوۡمِى وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِيلَ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ١٤٢',
    142, 9, 2, 167, 138, 67, 'false'
  );
  
  -- Ayah 143 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1097,
    'وَلَمَّا جَاۤءَ مُوسَىٰ لِمِیقَـٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِیۤ أَنظُرۡ إِلَیۡكَۚ قَالَ لَن تَرَىٰنِی وَلَـٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِیۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكࣰّا وَخَرَّ مُوسَىٰ صَعِقࣰاۚ فَلَمَّاۤ أَفَاقَ قَالَ سُبۡحَـٰنَكَ تُبۡتُ إِلَیۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِینَ',
    'ولما جاء موسى لميقاتنا وكلمه ربه قال رب ارني انظر اليك قال لن تراني ولكن انظر الى الجبل فان استقر مكانه فسوف تراني فلما تجلى ربه للجبل جعله دكا وخر موسى صعقا فلما افاق قال سبحانك تبت اليك وانا اول المؤمنين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مُوسَىٰ لِمِيقَ<rule class=madda_normal>ـٰ</rule>تِنَا وَكَلَّمَهُ<rule class=madda_normal>ۥ</rule> رَبُّهُ<rule class=madda_normal>ۥ</rule> قَالَ رَبِّ أَرِن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نظ</rule>ُرۡ إِلَيۡكَ‌ۚ قَالَ لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرَ<rule class=madda_normal>ٮٰ</rule>نِى وَلَ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡجَبَلِ فَإِنِ <rule class=ham_wasl>ٱ</rule>سۡتَقَرَّ مَكَانَهُ<rule class=madda_normal>ۥ</rule> فَسَوۡفَ تَرَ<rule class=madda_normal>ٮٰ</rule>نِى‌ۚ فَلَ<rule class=ghunnah>مّ</rule>َا تَجَلَّىٰ رَبُّهُ<rule class=madda_normal>ۥ</rule> لِلۡجَبَلِ جَعَلَهُ<rule class=madda_normal>ۥ</rule> دَك<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َخَرَّ مُوسَىٰ صَعِ<rule class=ikhafa>قًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَفَاقَ قَالَ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ تُ<rule class=qalaqah>بۡ</rule>تُ إِلَيۡكَ وَأَنَاۡ أَوَّلُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٤٣',
    143, 9, 2, 167, 138, 67, 'false'
  );
  
  -- Ayah 144 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1098,
    'قَالَ یَـٰمُوسَىٰۤ إِنِّی ٱصۡطَفَیۡتُكَ عَلَى ٱلنَّاسِ بِرِسَـٰلَـٰتِی وَبِكَلَـٰمِی فَخُذۡ مَاۤ ءَاتَیۡتُكَ وَكُن مِّنَ ٱلشَّـٰكِرِینَ',
    'قال يا موسى اني اصطفيتك على الناس برسالاتي وبكلامي فخذ ما اتيتك وكن من الشاكرين',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>ِى <rule class=ham_wasl>ٱ</rule>صۡطَفَيۡتُكَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِرِسَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِى وَبِكَلَ<rule class=madda_normal>ـٰ</rule>مِى فَخُذۡ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡتُكَ وَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ١٤٤',
    144, 9, 2, 168, 138, 67, 'false'
  );
  
  -- Ayah 145 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1099,
    'وَكَتَبۡنَا لَهُۥ فِی ٱلۡأَلۡوَاحِ مِن كُلِّ شَیۡءࣲ مَّوۡعِظَةࣰ وَتَفۡصِیلࣰا لِّكُلِّ شَیۡءࣲ فَخُذۡهَا بِقُوَّةࣲ وَأۡمُرۡ قَوۡمَكَ یَأۡخُذُوا۟ بِأَحۡسَنِهَاۚ سَأُو۟رِیكُمۡ دَارَ ٱلۡفَـٰسِقِینَ',
    'وكتبنا له في الالواح من كل شيء موعظة وتفصيلا لكل شيء فخذها بقوة وامر قومك ياخذوا باحسنها ساريكم دار الفاسقين',
    'وَكَتَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡوَاحِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>َّوۡعِظَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َتَفۡصِيل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َخُذۡهَا بِقُوَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َأۡمُرۡ قَوۡمَكَ يَأۡخُذُو<rule class=slnt>اۡ</rule> بِأَحۡسَنِهَا‌ۚ سَأُ<rule class=slnt>وۡ</rule>رِيكُمۡ دَارَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ١٤٥',
    145, 9, 2, 168, 138, 67, 'false'
  );
  
  -- Ayah 146 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1100,
    'سَأَصۡرِفُ عَنۡ ءَایَـٰتِیَ ٱلَّذِینَ یَتَكَبَّرُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَإِن یَرَوۡا۟ كُلَّ ءَایَةࣲ لَّا یُؤۡمِنُوا۟ بِهَا وَإِن یَرَوۡا۟ سَبِیلَ ٱلرُّشۡدِ لَا یَتَّخِذُوهُ سَبِیلࣰا وَإِن یَرَوۡا۟ سَبِیلَ ٱلۡغَیِّ یَتَّخِذُوهُ سَبِیلࣰاۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَكَانُوا۟ عَنۡهَا غَـٰفِلِینَ',
    'ساصرف عن اياتي الذين يتكبرون في الارض بغير الحق وان يروا كل اية لا يؤمنوا بها وان يروا سبيل الرشد لا يتخذوه سبيلا وان يروا سبيل الغي يتخذوه سبيلا ذلك بانهم كذبوا باياتنا وكانوا عنها غافلين',
    'سَأَصۡرِفُ عَنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَتَكَبَّرُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َرَوۡ<rule class=slnt>اۡ</rule> كُلَّ ءَايَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِنُو<rule class=slnt>اۡ</rule> بِهَا وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َرَوۡ<rule class=slnt>اۡ</rule> سَبِيلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّشۡدِ لَا يَتَّخِذُوهُ سَبِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َرَوۡ<rule class=slnt>اۡ</rule> سَبِيلَ <rule class=ham_wasl>ٱ</rule>لۡغَىِّ يَتَّخِذُوهُ سَبِيل<rule class=ikhafa>اً‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَكَانُو<rule class=slnt>اۡ</rule> عَنۡهَا غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ١٤٦',
    146, 9, 2, 168, 138, 67, 'false'
  );
  
  -- Ayah 147 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1101,
    'وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَلِقَاۤءِ ٱلۡـَٔاخِرَةِ حَبِطَتۡ أَعۡمَـٰلُهُمۡۚ هَلۡ یُجۡزَوۡنَ إِلَّا مَا كَانُوا۟ یَعۡمَلُونَ',
    'والذين كذبوا باياتنا ولقاء الاخرة حبطت اعمالهم هل يجزون الا ما كانوا يعملون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ حَبِطَتۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ‌ۚ هَلۡ يُ<rule class=qalaqah>جۡ</rule>زَوۡنَ إِلَّا مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٤٧',
    147, 9, 2, 168, 138, 67, 'false'
  );
  
  -- Ayah 148 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1102,
    'وَٱتَّخَذَ قَوۡمُ مُوسَىٰ مِنۢ بَعۡدِهِۦ مِنۡ حُلِیِّهِمۡ عِجۡلࣰا جَسَدࣰا لَّهُۥ خُوَارٌۚ أَلَمۡ یَرَوۡا۟ أَنَّهُۥ لَا یُكَلِّمُهُمۡ وَلَا یَهۡدِیهِمۡ سَبِیلًاۘ ٱتَّخَذُوهُ وَكَانُوا۟ ظَـٰلِمِینَ',
    'واتخذ قوم موسى من بعده من حليهم عجلا جسدا له خوار الم يروا انه لا يكلمهم ولا يهديهم سبيلا اتخذوه وكانوا ظالمين',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّخَذَ قَوۡمُ مُوسَىٰ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> مِنۡ حُلِيِّهِمۡ عِ<rule class=qalaqah>جۡ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ج</rule>َسَ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> خُوَارٌ‌ۚ أَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُكَلِّمُهُمۡ وَلَا يَهۡدِيهِمۡ سَبِيلاً‌ۘ <rule class=ham_wasl>ٱ</rule>تَّخَذُوهُ وَكَانُو<rule class=slnt>اۡ</rule> ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٤٨',
    148, 9, 2, 168, 139, 67, 'false'
  );
  
  -- Ayah 149 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1103,
    'وَلَمَّا سُقِطَ فِیۤ أَیۡدِیهِمۡ وَرَأَوۡا۟ أَنَّهُمۡ قَدۡ ضَلُّوا۟ قَالُوا۟ لَىِٕن لَّمۡ یَرۡحَمۡنَا رَبُّنَا وَیَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَـٰسِرِینَ',
    'ولما سقط في ايديهم وراوا انهم قد ضلوا قالوا لئن لم يرحمنا ربنا ويغفر لنا لنكونن من الخاسرين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا سُقِطَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَيۡدِيهِمۡ وَرَأَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ قَ<rule class=qalaqah>دۡ</rule> ضَلُّو<rule class=slnt>اۡ</rule> قَالُو<rule class=slnt>اۡ</rule> لَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَرۡحَمۡنَا رَبُّنَا وَيَغۡفِرۡ لَنَا لَنَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ١٤٩',
    149, 9, 2, 168, 139, 67, 'false'
  );
  
  -- Ayah 150 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1104,
    'وَلَمَّا رَجَعَ مُوسَىٰۤ إِلَىٰ قَوۡمِهِۦ غَضۡبَـٰنَ أَسِفࣰا قَالَ بِئۡسَمَا خَلَفۡتُمُونِی مِنۢ بَعۡدِیۤۖ أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡۖ وَأَلۡقَى ٱلۡأَلۡوَاحَ وَأَخَذَ بِرَأۡسِ أَخِیهِ یَجُرُّهُۥۤ إِلَیۡهِۚ قَالَ ٱبۡنَ أُمَّ إِنَّ ٱلۡقَوۡمَ ٱسۡتَضۡعَفُونِی وَكَادُوا۟ یَقۡتُلُونَنِی فَلَا تُشۡمِتۡ بِیَ ٱلۡأَعۡدَاۤءَ وَلَا تَجۡعَلۡنِی مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'ولما رجع موسى الى قومه غضبان اسفا قال بئسما خلفتموني من بعدي اعجلتم امر ربكم والقى الالواح واخذ براس اخيه يجره اليه قال ابن ام ان القوم استضعفوني وكادوا يقتلونني فلا تشمت بي الاعداء ولا تجعلني مع القوم الظالمين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا رَجَعَ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule> غَضۡبَ<rule class=madda_normal>ـٰ</rule>نَ أَسِ<rule class=ikhafa>فًا</rule> <rule class=ikhafa>ق</rule>َالَ بِئۡسَمَا خَلَفۡتُمُونِى م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡد<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡ‌ۖ وَأَلۡقَى <rule class=ham_wasl>ٱ</rule>لۡأَلۡوَاحَ وَأَخَذَ بِرَأۡسِ أَخِيهِ يَجُرُّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَيۡهِ‌ۚ قَالَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ أُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>سۡتَضۡعَفُونِى وَكَادُو<rule class=slnt>اۡ</rule> يَ<rule class=qalaqah>قۡ</rule>تُلُونَنِى فَلَا تُشۡمِتۡ بِىَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَلَا تَ<rule class=qalaqah>جۡ</rule>عَلۡنِى مَعَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٥٠',
    150, 9, 2, 169, 139, 67, 'false'
  );
  
  -- Ayah 151 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1105,
    'قَالَ رَبِّ ٱغۡفِرۡ لِی وَلِأَخِی وَأَدۡخِلۡنَا فِی رَحۡمَتِكَۖ وَأَنتَ أَرۡحَمُ ٱلرَّ ٰ⁠حِمِینَ',
    'قال رب اغفر لي ولاخي وادخلنا في رحمتك وانت ارحم الراحمين',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule>غۡفِرۡ لِى وَلِأَخِى وَأَ<rule class=qalaqah>دۡ</rule>خِلۡنَا فِى رَحۡمَتِكَ‌ۖ وَأَ<rule class=ikhafa>نت</rule>َ أَرۡحَمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>حِم<rule class=madda_permissible>ِي</rule>نَ ١٥١',
    151, 9, 2, 169, 139, 67, 'false'
  );
  
  -- Ayah 152 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1106,
    'إِنَّ ٱلَّذِینَ ٱتَّخَذُوا۟ ٱلۡعِجۡلَ سَیَنَالُهُمۡ غَضَبࣱ مِّن رَّبِّهِمۡ وَذِلَّةࣱ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَكَذَ ٰ⁠لِكَ نَجۡزِی ٱلۡمُفۡتَرِینَ',
    'ان الذين اتخذوا العجل سينالهم غضب من ربهم وذلة في الحياة الدنيا وكذلك نجزي المفترين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِ<rule class=qalaqah>جۡ</rule>لَ سَيَنَالُهُمۡ غَضَ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ وَذِلَّ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۚ وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لۡمُفۡتَر<rule class=madda_permissible>ِي</rule>نَ ١٥٢',
    152, 9, 2, 169, 140, 67, 'false'
  );
  
  -- Ayah 153 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1107,
    'وَٱلَّذِینَ عَمِلُوا۟ ٱلسَّیِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعۡدِهَا وَءَامَنُوۤا۟ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِیمࣱ',
    'والذين عملوا السيئات ثم تابوا من بعدها وامنوا ان ربك من بعدها لغفور رحيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ عَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ ثُ<rule class=ghunnah>مّ</rule>َ تَابُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهَا وَءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهَا لَغَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٥٣',
    153, 9, 2, 169, 140, 67, 'false'
  );
  
  -- Ayah 154 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1108,
    'وَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِی نُسۡخَتِهَا هُدࣰى وَرَحۡمَةࣱ لِّلَّذِینَ هُمۡ لِرَبِّهِمۡ یَرۡهَبُونَ',
    'ولما سكت عن موسى الغضب اخذ الالواح وفي نسختها هدى ورحمة للذين هم لربهم يرهبون',
    'وَلَ<rule class=ghunnah>مّ</rule>َا سَكَتَ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>ُّوسَى <rule class=ham_wasl>ٱ</rule>لۡغَضَبُ أَخَذَ <rule class=ham_wasl>ٱ</rule>لۡأَلۡوَاحَ‌ۖ وَفِى نُسۡخَتِهَا هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ هُمۡ لِرَبِّهِمۡ يَرۡهَب<rule class=madda_permissible>ُو</rule>نَ ١٥٤',
    154, 9, 2, 169, 140, 67, 'false'
  );
  
  -- Ayah 155 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1109,
    'وَٱخۡتَارَ مُوسَىٰ قَوۡمَهُۥ سَبۡعِینَ رَجُلࣰا لِّمِیقَـٰتِنَاۖ فَلَمَّاۤ أَخَذَتۡهُمُ ٱلرَّجۡفَةُ قَالَ رَبِّ لَوۡ شِئۡتَ أَهۡلَكۡتَهُم مِّن قَبۡلُ وَإِیَّـٰیَۖ أَتُهۡلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَاۤءُ مِنَّاۤۖ إِنۡ هِیَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَن تَشَاۤءُ وَتَهۡدِی مَن تَشَاۤءُۖ أَنتَ وَلِیُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَیۡرُ ٱلۡغَـٰفِرِینَ',
    'واختار موسى قومه سبعين رجلا لميقاتنا فلما اخذتهم الرجفة قال رب لو شئت اهلكتهم من قبل واياي اتهلكنا بما فعل السفهاء منا ان هي الا فتنتك تضل بها من تشاء وتهدي من تشاء انت ولينا فاغفر لنا وارحمنا وانت خير الغافرين',
    'وَ<rule class=ham_wasl>ٱ</rule>خۡتَارَ مُوسَىٰ قَوۡمَهُ<rule class=madda_normal>ۥ</rule> سَ<rule class=qalaqah>بۡ</rule>عِينَ رَجُل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمِيقَ<rule class=madda_normal>ـٰ</rule>تِنَا‌ۖ فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّ<rule class=qalaqah>جۡ</rule>فَةُ قَالَ رَبِّ لَوۡ شِئۡتَ أَهۡلَكۡتَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَإِيَّ<rule class=madda_normal>ـٰ</rule>ىَ‌ۖ أَتُهۡلِكُنَا بِمَا فَعَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّفَه<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِنۡ هِىَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَتَهۡدِى مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ أَ<rule class=ikhafa>نت</rule>َ وَلِيُّنَا فَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَنَا وَ<rule class=ham_wasl>ٱ</rule>رۡحَمۡنَا‌ۖ وَأَ<rule class=ikhafa>نت</rule>َ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٥٥',
    155, 9, 2, 169, 140, 67, 'false'
  );
  
  -- Ayah 156 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1110,
    '۞ وَٱكۡتُبۡ لَنَا فِی هَـٰذِهِ ٱلدُّنۡیَا حَسَنَةࣰ وَفِی ٱلۡـَٔاخِرَةِ إِنَّا هُدۡنَاۤ إِلَیۡكَۚ قَالَ عَذَابِیۤ أُصِیبُ بِهِۦ مَنۡ أَشَاۤءُۖ وَرَحۡمَتِی وَسِعَتۡ كُلَّ شَیۡءࣲۚ فَسَأَكۡتُبُهَا لِلَّذِینَ یَتَّقُونَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلَّذِینَ هُم بِـَٔایَـٰتِنَا یُؤۡمِنُونَ',
    'واكتب لنا في هذه الدنيا حسنة وفي الاخرة انا هدنا اليك قال عذابي اصيب به من اشاء ورحمتي وسعت كل شيء فساكتبها للذين يتقون ويؤتون الزكاة والذين هم باياتنا يؤمنون',
    '۞وَ<rule class=ham_wasl>ٱ</rule>كۡتُ<rule class=qalaqah>بۡ</rule> لَنَا فِى هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا حَسَنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َفِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ إِ<rule class=ghunnah>نّ</rule>َا هُ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ‌ۚ قَالَ عَذَاب<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُصِيبُ بِه<rule class=madda_normal>ِۦ</rule> مَنۡ أَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ وَرَحۡمَتِى وَسِعَتۡ كُلَّ ش<rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َسَأَكۡتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٥٦',
    156, 9, 2, 170, 140, 68, 'false'
  );
  
  -- Ayah 157 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1111,
    'ٱلَّذِینَ یَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِیَّ ٱلۡأُمِّیَّ ٱلَّذِی یَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِی ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِیلِ یَأۡمُرُهُم بِٱلۡمَعۡرُوفِ وَیَنۡهَىٰهُمۡ عَنِ ٱلۡمُنكَرِ وَیُحِلُّ لَهُمُ ٱلطَّیِّبَـٰتِ وَیُحَرِّمُ عَلَیۡهِمُ ٱلۡخَبَـٰۤىِٕثَ وَیَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَـٰلَ ٱلَّتِی كَانَتۡ عَلَیۡهِمۡۚ فَٱلَّذِینَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِیۤ أُنزِلَ مَعَهُۥۤ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'الذين يتبعون الرسول النبي الامي الذي يجدونه مكتوبا عندهم في التوراة والانجيل يامرهم بالمعروف وينهاهم عن المنكر ويحل لهم الطيبات ويحرم عليهم الخبائث ويضع عنهم اصرهم والاغلال التي كانت عليهم فالذين امنوا به وعزروه ونصروه واتبعوا النور الذي انزل معه اولئك هم المفلحون',
    'ٱلَّذِينَ يَتَّبِعُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىَّ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ghunnah>مّ</rule>ِىَّ <rule class=ham_wasl>ٱ</rule>لَّذِى يَجِدُونَهُ<rule class=madda_normal>ۥ</rule> مَكۡتُوبًا عِ<rule class=ikhafa>ند</rule>َهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلِ يَأۡمُرُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَيَنۡهَ<rule class=madda_normal>ـٰ</rule>هُمۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ وَيُحِلُّ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ وَيُحَرِّمُ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡخَبَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِثَ وَيَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡأَغۡلَ<rule class=madda_normal>ـٰ</rule>لَ <rule class=ham_wasl>ٱ</rule>لَّتِى كَانَتۡ عَلَيۡهِمۡ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> وَعَزَّرُوهُ وَنَصَرُوهُ وَ<rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ مَعَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۙ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٥٧',
    157, 9, 2, 170, 140, 68, 'false'
  );
  
  -- Ayah 158 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1112,
    'قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ إِنِّی رَسُولُ ٱللَّهِ إِلَیۡكُمۡ جَمِیعًا ٱلَّذِی لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ لَاۤ إِلَـٰهَ إِلَّا هُوَ یُحۡیِۦ وَیُمِیتُۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِیِّ ٱلۡأُمِّیِّ ٱلَّذِی یُؤۡمِنُ بِٱللَّهِ وَكَلِمَـٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمۡ تَهۡتَدُونَ',
    'قل يا ايها الناس اني رسول الله اليكم جميعا الذي له ملك السماوات والارض لا اله الا هو يحيي ويميت فامنوا بالله ورسوله النبي الامي الذي يؤمن بالله وكلماته واتبعوه لعلكم تهتدون',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِ<rule class=ghunnah>نّ</rule>ِى رَسُولُ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَيۡكُمۡ جَمِيعًا <rule class=ham_wasl>ٱ</rule>لَّذِى لَهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُ‌ۖ فَـَٔـامِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ghunnah>مّ</rule>ِىِّ <rule class=ham_wasl>ٱ</rule>لَّذِى يُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَكَلِمَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّبِعُوهُ لَعَلَّكُمۡ تَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٥٨',
    158, 9, 2, 170, 141, 68, 'false'
  );
  
  -- Ayah 159 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1113,
    'وَمِن قَوۡمِ مُوسَىٰۤ أُمَّةࣱ یَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ یَعۡدِلُونَ',
    'ومن قوم موسى امة يهدون بالحق وبه يعدلون',
    'وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَبِه<rule class=madda_normal>ِۦ</rule> يَعۡدِل<rule class=madda_permissible>ُو</rule>نَ ١٥٩',
    159, 9, 2, 170, 141, 68, 'false'
  );
  
  -- Ayah 160 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1114,
    'وَقَطَّعۡنَـٰهُمُ ٱثۡنَتَیۡ عَشۡرَةَ أَسۡبَاطًا أُمَمࣰاۚ وَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ إِذِ ٱسۡتَسۡقَىٰهُ قَوۡمُهُۥۤ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنۢبَجَسَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَیۡنࣰاۖ قَدۡ عَلِمَ كُلُّ أُنَاسࣲ مَّشۡرَبَهُمۡۚ وَظَلَّلۡنَا عَلَیۡهِمُ ٱلۡغَمَـٰمَ وَأَنزَلۡنَا عَلَیۡهِمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡۚ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'وقطعناهم اثنتي عشرة اسباطا امما واوحينا الى موسى اذ استسقاه قومه ان اضرب بعصاك الحجر فانبجست منه اثنتا عشرة عينا قد علم كل اناس مشربهم وظللنا عليهم الغمام وانزلنا عليهم المن والسلوى كلوا من طيبات ما رزقناكم وما ظلمونا ولكن كانوا انفسهم يظلمون',
    'وَقَطَّعۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>ثۡنَتَىۡ عَشۡرَةَ أَسۡبَاطًا أُمَ<rule class=idgham_ghunnah>مًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذِ <rule class=ham_wasl>ٱ</rule>سۡتَسۡقَ<rule class=madda_normal>ـٰ</rule>هُ قَوۡمُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَنِ <rule class=ham_wasl>ٱ</rule>ضۡرِب بِّعَصَاكَ <rule class=ham_wasl>ٱ</rule>لۡحَجَرَ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=iqlab>نۢب</rule>َجَسَتۡ مِنۡهُ <rule class=ham_wasl>ٱ</rule>ثۡنَتَا عَشۡرَةَ عَيۡ<rule class=ikhafa>نًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> عَلِمَ كُلُّ أُنَا<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّشۡرَبَهُمۡ‌ۚ وَظَلَّلۡنَا عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡغَمَ<rule class=madda_normal>ـٰ</rule>مَ وَأَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=ghunnah>نّ</rule>َ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلۡوَىٰ‌ۖ كُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=madda_normal>ـٰ</rule>تِ مَا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۚ وَمَا ظَلَمُونَا وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٦٠',
    160, 9, 2, 171, 141, 68, 'false'
  );
  
  -- Ayah 161 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1115,
    'وَإِذۡ قِیلَ لَهُمُ ٱسۡكُنُوا۟ هَـٰذِهِ ٱلۡقَرۡیَةَ وَكُلُوا۟ مِنۡهَا حَیۡثُ شِئۡتُمۡ وَقُولُوا۟ حِطَّةࣱ وَٱدۡخُلُوا۟ ٱلۡبَابَ سُجَّدࣰا نَّغۡفِرۡ لَكُمۡ خَطِیۤـَٔـٰتِكُمۡۚ سَنَزِیدُ ٱلۡمُحۡسِنِینَ',
    'واذ قيل لهم اسكنوا هذه القرية وكلوا منها حيث شئتم وقولوا حطة وادخلوا الباب سجدا نغفر لكم خطيئاتكم سنزيد المحسنين',
    'وَإِذۡ قِيلَ لَهُمُ <rule class=ham_wasl>ٱ</rule>سۡكُنُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةَ وَكُلُو<rule class=slnt>اۡ</rule> مِنۡهَا حَيۡثُ شِئۡتُمۡ وَقُولُو<rule class=slnt>اۡ</rule> حِطَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡبَابَ سُجَّ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>ن</rule>َّغۡفِرۡ لَكُمۡ خَطِ<rule class=madda_obligatory_mottasel>يٓ</rule>ـَٔ<rule class=madda_normal>ـٰ</rule>تِكُمۡ‌ۚ سَنَزِيدُ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٦١',
    161, 9, 2, 171, 141, 68, 'false'
  );
  
  -- Ayah 162 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1116,
    'فَبَدَّلَ ٱلَّذِینَ ظَلَمُوا۟ مِنۡهُمۡ قَوۡلًا غَیۡرَ ٱلَّذِی قِیلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَیۡهِمۡ رِجۡزࣰا مِّنَ ٱلسَّمَاۤءِ بِمَا كَانُوا۟ یَظۡلِمُونَ',
    'فبدل الذين ظلموا منهم قولا غير الذي قيل لهم فارسلنا عليهم رجزا من السماء بما كانوا يظلمون',
    'فَبَدَّلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ قَوۡلاً غَيۡرَ <rule class=ham_wasl>ٱ</rule>لَّذِى قِيلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>زًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٦٢',
    162, 9, 2, 171, 141, 68, 'false'
  );
  
  -- Ayah 163 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1117,
    'وَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡیَةِ ٱلَّتِی كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ یَعۡدُونَ فِی ٱلسَّبۡتِ إِذۡ تَأۡتِیهِمۡ حِیتَانُهُمۡ یَوۡمَ سَبۡتِهِمۡ شُرَّعࣰا وَیَوۡمَ لَا یَسۡبِتُونَ لَا تَأۡتِیهِمۡۚ كَذَ ٰ⁠لِكَ نَبۡلُوهُم بِمَا كَانُوا۟ یَفۡسُقُونَ',
    'واسالهم عن القرية التي كانت حاضرة البحر اذ يعدون في السبت اذ تاتيهم حيتانهم يوم سبتهم شرعا ويوم لا يسبتون لا تاتيهم كذلك نبلوهم بما كانوا يفسقون',
    'وَسۡــَٔلۡهُمۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةِ <rule class=ham_wasl>ٱ</rule>لَّتِى كَانَتۡ حَاضِرَةَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ إِذۡ يَعۡدُونَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=qalaqah>بۡ</rule>تِ إِذۡ تَأۡتِيهِمۡ حِيتَانُهُمۡ يَوۡمَ سَ<rule class=qalaqah>بۡ</rule>تِهِمۡ شُرَّ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َيَوۡمَ لَا يَسۡبِتُونَ‌ۙ لَا تَأۡتِيهِمۡ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>بۡ</rule>لُوه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡسُق<rule class=madda_permissible>ُو</rule>نَ ١٦٣',
    163, 9, 2, 171, 142, 68, 'false'
  );
  
  -- Ayah 164 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1118,
    'وَإِذۡ قَالَتۡ أُمَّةࣱ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابࣰا شَدِیدࣰاۖ قَالُوا۟ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ یَتَّقُونَ',
    'واذ قالت امة منهم لم تعظون قوما الله مهلكهم او معذبهم عذابا شديدا قالوا معذرة الى ربكم ولعلهم يتقون',
    'وَإِذۡ قَالَتۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا‌ۙ <rule class=ham_wasl>ٱ</rule>للَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=ikhafa>دًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ يَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٦٤',
    164, 9, 2, 172, 142, 68, 'false'
  );
  
  -- Ayah 165 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1119,
    'فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦۤ أَنجَیۡنَا ٱلَّذِینَ یَنۡهَوۡنَ عَنِ ٱلسُّوۤءِ وَأَخَذۡنَا ٱلَّذِینَ ظَلَمُوا۟ بِعَذَابِۭ بَـِٔیسِۭ بِمَا كَانُوا۟ یَفۡسُقُونَ',
    'فلما نسوا ما ذكروا به انجينا الذين ينهون عن السوء واخذنا الذين ظلموا بعذاب بئيس بما كانوا يفسقون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا نَسُو<rule class=slnt>اۡ</rule> مَا ذُكِّرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَ<rule class=ikhafa>نج</rule>َيۡنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَنۡهَوۡنَ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءِ وَأَخَذۡنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> بِعَذَا<rule class=iqlab>بِۭ</rule> <rule class=iqlab>ب</rule>َــِٔي<rule class=iqlab>سِۭ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡسُق<rule class=madda_permissible>ُو</rule>نَ ١٦٥',
    165, 9, 2, 172, 142, 68, 'false'
  );
  
  -- Ayah 166 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1120,
    'فَلَمَّا عَتَوۡا۟ عَن مَّا نُهُوا۟ عَنۡهُ قُلۡنَا لَهُمۡ كُونُوا۟ قِرَدَةً خَـٰسِـِٔینَ',
    'فلما عتوا عن ما نهوا عنه قلنا لهم كونوا قردة خاسئين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا عَتَوۡ<rule class=slnt>اۡ</rule> ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّا نُهُو<rule class=slnt>اۡ</rule> عَنۡهُ قُلۡنَا لَهُمۡ كُونُو<rule class=slnt>اۡ</rule> قِرَدَةً خَ<rule class=madda_normal>ـٰ</rule>سِــٔ<rule class=madda_permissible>ِي</rule>نَ ١٦٦',
    166, 9, 2, 172, 142, 68, 'false'
  );
  
  -- Ayah 167 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1121,
    'وَإِذۡ تَأَذَّنَ رَبُّكَ لَیَبۡعَثَنَّ عَلَیۡهِمۡ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ مَن یَسُومُهُمۡ سُوۤءَ ٱلۡعَذَابِۗ إِنَّ رَبَّكَ لَسَرِیعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورࣱ رَّحِیمࣱ',
    'واذ تاذن ربك ليبعثن عليهم الى يوم القيامة من يسومهم سوء العذاب ان ربك لسريع العقاب وانه لغفور رحيم',
    'وَإِذۡ تَأَذَّنَ رَبُّكَ لَيَ<rule class=qalaqah>بۡ</rule>عَثَ<rule class=ghunnah>نّ</rule>َ عَلَيۡهِمۡ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسُومُهُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَسَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡعِقَابِ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَغَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٦٧',
    167, 9, 2, 172, 142, 68, 'false'
  );
  
  -- Ayah 168 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1122,
    'وَقَطَّعۡنَـٰهُمۡ فِی ٱلۡأَرۡضِ أُمَمࣰاۖ مِّنۡهُمُ ٱلصَّـٰلِحُونَ وَمِنۡهُمۡ دُونَ ذَ ٰ⁠لِكَۖ وَبَلَوۡنَـٰهُم بِٱلۡحَسَنَـٰتِ وَٱلسَّیِّـَٔاتِ لَعَلَّهُمۡ یَرۡجِعُونَ',
    'وقطعناهم في الارض امما منهم الصالحون ومنهم دون ذلك وبلوناهم بالحسنات والسيئات لعلهم يرجعون',
    'وَقَطَّعۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أُمَ<rule class=idgham_ghunnah>مًا‌ۖ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحُونَ وَمِنۡهُمۡ دُونَ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۖ وَبَلَوۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَسَنَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ لَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ١٦٨',
    168, 9, 2, 172, 142, 68, 'false'
  );
  
  -- Ayah 169 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1123,
    'فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفࣱ وَرِثُوا۟ ٱلۡكِتَـٰبَ یَأۡخُذُونَ عَرَضَ هَـٰذَا ٱلۡأَدۡنَىٰ وَیَقُولُونَ سَیُغۡفَرُ لَنَا وَإِن یَأۡتِهِمۡ عَرَضࣱ مِّثۡلُهُۥ یَأۡخُذُوهُۚ أَلَمۡ یُؤۡخَذۡ عَلَیۡهِم مِّیثَـٰقُ ٱلۡكِتَـٰبِ أَن لَّا یَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّ وَدَرَسُوا۟ مَا فِیهِۗ وَٱلدَّارُ ٱلۡـَٔاخِرَةُ خَیۡرࣱ لِّلَّذِینَ یَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ',
    'فخلف من بعدهم خلف ورثوا الكتاب ياخذون عرض هذا الادنى ويقولون سيغفر لنا وان ياتهم عرض مثله ياخذوه الم يؤخذ عليهم ميثاق الكتاب ان لا يقولوا على الله الا الحق ودرسوا ما فيه والدار الاخرة خير للذين يتقون افلا تعقلون',
    'فَخَلَفَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ خَلۡ<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>و</rule>َرِثُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يَأۡخُذُونَ عَرَضَ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>دۡ</rule>نَىٰ وَيَقُولُونَ سَيُغۡفَرُ لَنَا وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِهِمۡ عَرَ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُهُ<rule class=madda_normal>ۥ</rule> يَأۡخُذُوهُ‌ۚ أَلَمۡ يُؤۡخَذۡ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule>قُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَقُولُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَدَرَسُو<rule class=slnt>اۡ</rule> مَا فِيهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةُ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ يَتَّقُونَ‌ۗ أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٦٩',
    169, 9, 2, 172, 142, 68, 'false'
  );
  
  -- Ayah 170 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1124,
    'وَٱلَّذِینَ یُمَسِّكُونَ بِٱلۡكِتَـٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِیعُ أَجۡرَ ٱلۡمُصۡلِحِینَ',
    'والذين يمسكون بالكتاب واقاموا الصلاة انا لا نضيع اجر المصلحين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُمَسِّكُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَأَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ إِ<rule class=ghunnah>نّ</rule>َا لَا نُضِيعُ أَ<rule class=qalaqah>جۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمُصۡلِح<rule class=madda_permissible>ِي</rule>نَ ١٧٠',
    170, 9, 2, 172, 142, 68, 'false'
  );
  
  -- Ayah 171 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1125,
    '۞ وَإِذۡ نَتَقۡنَا ٱلۡجَبَلَ فَوۡقَهُمۡ كَأَنَّهُۥ ظُلَّةࣱ وَظَنُّوۤا۟ أَنَّهُۥ وَاقِعُۢ بِهِمۡ خُذُوا۟ مَاۤ ءَاتَیۡنَـٰكُم بِقُوَّةࣲ وَٱذۡكُرُوا۟ مَا فِیهِ لَعَلَّكُمۡ تَتَّقُونَ',
    'واذ نتقنا الجبل فوقهم كانه ظلة وظنوا انه واقع بهم خذوا ما اتيناكم بقوة واذكروا ما فيه لعلكم تتقون',
    '۞وَإِذۡ نَتَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡجَبَلَ فَوۡقَهُمۡ كَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ظُلَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َظَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> وَاقِ<rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>ِهِمۡ خُذُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِقُوَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> مَا فِيهِ لَعَلَّكُمۡ تَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٧١',
    171, 9, 2, 173, 142, 69, 'false'
  );
  
  -- Ayah 172 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1126,
    'وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِیۤ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّیَّتَهُمۡ وَأَشۡهَدَهُمۡ عَلَىٰۤ أَنفُسِهِمۡ أَلَسۡتُ بِرَبِّكُمۡۖ قَالُوا۟ بَلَىٰ شَهِدۡنَاۤۚ أَن تَقُولُوا۟ یَوۡمَ ٱلۡقِیَـٰمَةِ إِنَّا كُنَّا عَنۡ هَـٰذَا غَـٰفِلِینَ',
    'واذ اخذ ربك من بني ادم من ظهورهم ذريتهم واشهدهم على انفسهم الست بربكم قالوا بلى شهدنا ان تقولوا يوم القيامة انا كنا عن هذا غافلين',
    'وَإِذۡ أَخَذَ رَبُّكَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َن<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَادَمَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>ُهُورِهِمۡ ذُرِّيَّتَهُمۡ وَأَشۡهَدَهُمۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ أَلَسۡتُ بِرَبِّكُمۡ‌ۖ قَالُو<rule class=slnt>اۡ</rule> بَلَىٰ‌ۛ شَهِ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ‌ۛ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولُو<rule class=slnt>اۡ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا عَنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ١٧٢',
    172, 9, 2, 173, 143, 69, 'false'
  );
  
  -- Ayah 173 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1127,
    'أَوۡ تَقُولُوۤا۟ إِنَّمَاۤ أَشۡرَكَ ءَابَاۤؤُنَا مِن قَبۡلُ وَكُنَّا ذُرِّیَّةࣰ مِّنۢ بَعۡدِهِمۡۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ ٱلۡمُبۡطِلُونَ',
    'او تقولوا انما اشرك اباؤنا من قبل وكنا ذرية من بعدهم افتهلكنا بما فعل المبطلون',
    'أَوۡ تَقُول<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡرَكَ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَكُ<rule class=ghunnah>نّ</rule>َا ذُرِّيَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ‌ۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>بۡ</rule>طِل<rule class=madda_permissible>ُو</rule>نَ ١٧٣',
    173, 9, 2, 173, 143, 69, 'false'
  );
  
  -- Ayah 174 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1128,
    'وَكَذَ ٰ⁠لِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ وَلَعَلَّهُمۡ یَرۡجِعُونَ',
    'وكذلك نفصل الايات ولعلهم يرجعون',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نُفَصِّلُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ وَلَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ١٧٤',
    174, 9, 2, 173, 143, 69, 'false'
  );
  
  -- Ayah 175 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1129,
    'وَٱتۡلُ عَلَیۡهِمۡ نَبَأَ ٱلَّذِیۤ ءَاتَیۡنَـٰهُ ءَایَـٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّیۡطَـٰنُ فَكَانَ مِنَ ٱلۡغَاوِینَ',
    'واتل عليهم نبا الذي اتيناه اياتنا فانسلخ منها فاتبعه الشيطان فكان من الغاوين',
    'وَ<rule class=ham_wasl>ٱ</rule>تۡلُ عَلَيۡهِمۡ نَبَأَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نس</rule>َلَخَ مِنۡهَا فَأَتۡبَعَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ فَكَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَاو<rule class=madda_permissible>ِي</rule>نَ ١٧٥',
    175, 9, 2, 173, 143, 69, 'false'
  );
  
  -- Ayah 176 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1130,
    'وَلَوۡ شِئۡنَا لَرَفَعۡنَـٰهُ بِهَا وَلَـٰكِنَّهُۥۤ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ فَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَیۡهِ یَلۡهَثۡ أَوۡ تَتۡرُكۡهُ یَلۡهَثۚ ذَّ ٰ⁠لِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۚ فَٱقۡصُصِ ٱلۡقَصَصَ لَعَلَّهُمۡ یَتَفَكَّرُونَ',
    'ولو شئنا لرفعناه بها ولكنه اخلد الى الارض واتبع هواه فمثله كمثل الكلب ان تحمل عليه يلهث او تتركه يلهث ذلك مثل القوم الذين كذبوا باياتنا فاقصص القصص لعلهم يتفكرون',
    'وَلَوۡ شِئۡنَا لَرَفَعۡنَ<rule class=madda_normal>ـٰ</rule>هُ بِهَا وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَخۡلَدَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule>تَّبَعَ هَوَ<rule class=madda_normal>ٮٰ</rule>هُ‌ۚ فَمَثَلُهُ<rule class=madda_normal>ۥ</rule> كَمَثَلِ <rule class=ham_wasl>ٱ</rule>لۡكَلۡبِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡمِلۡ عَلَيۡهِ يَلۡهَثۡ أَوۡ تَتۡرُكۡهُ يَلۡهَ<rule class=idgham_mutajanisayn>ث</rule>‌ۚ ذّ<rule class=madda_normal>ٰ</rule>لِكَ مَثَلُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا‌ۚ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>صُصِ <rule class=ham_wasl>ٱ</rule>لۡقَصَصَ لَعَلَّهُمۡ يَتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ١٧٦',
    176, 9, 2, 173, 143, 69, 'false'
  );
  
  -- Ayah 177 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1131,
    'سَاۤءَ مَثَلًا ٱلۡقَوۡمُ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَأَنفُسَهُمۡ كَانُوا۟ یَظۡلِمُونَ',
    'ساء مثلا القوم الذين كذبوا باياتنا وانفسهم كانوا يظلمون',
    'س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَثَلاً <rule class=ham_wasl>ٱ</rule>لۡقَوۡمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَأَ<rule class=ikhafa>نف</rule>ُسَهُمۡ كَانُو<rule class=slnt>اۡ</rule> يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٧٧',
    177, 9, 2, 173, 143, 69, 'false'
  );
  
  -- Ayah 178 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1132,
    'مَن یَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِیۖ وَمَن یُضۡلِلۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ',
    'من يهد الله فهو المهتدي ومن يضلل فاولئك هم الخاسرون',
    'م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَهُوَ <rule class=ham_wasl>ٱ</rule>لۡمُهۡتَدِى‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلۡ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ١٧٨',
    178, 9, 2, 173, 143, 69, 'false'
  );
  
  -- Ayah 179 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1133,
    'وَلَقَدۡ ذَرَأۡنَا لِجَهَنَّمَ كَثِیرࣰا مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ لَهُمۡ قُلُوبࣱ لَّا یَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡیُنࣱ لَّا یُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانࣱ لَّا یَسۡمَعُونَ بِهَاۤۚ أُو۟لَـٰۤىِٕكَ كَٱلۡأَنۡعَـٰمِ بَلۡ هُمۡ أَضَلُّۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡغَـٰفِلُونَ',
    'ولقد ذرانا لجهنم كثيرا من الجن والانس لهم قلوب لا يفقهون بها ولهم اعين لا يبصرون بها ولهم اذان لا يسمعون بها اولئك كالانعام بل هم اضل اولئك هم الغافلون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ذَرَأۡنَا لِجَهَ<rule class=ghunnah>نّ</rule>َمَ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ‌ۖ لَهُمۡ قُلُو<rule class=idgham_wo_ghunnah>بٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡيُ<rule class=idgham_wo_ghunnah>نٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُ<rule class=qalaqah>بۡ</rule>صِرُونَ بِهَا وَلَهُمۡ ءَاذَا<rule class=idgham_wo_ghunnah>نٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَسۡمَعُونَ بِه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ كَ<rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ بَلۡ هُمۡ أَضَلُّ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ١٧٩',
    179, 9, 2, 174, 143, 69, 'false'
  );
  
  -- Ayah 180 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1134,
    'وَلِلَّهِ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُوا۟ ٱلَّذِینَ یُلۡحِدُونَ فِیۤ أَسۡمَـٰۤىِٕهِۦۚ سَیُجۡزَوۡنَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'ولله الاسماء الحسنى فادعوه بها وذروا الذين يلحدون في اسمائه سيجزون ما كانوا يعملون',
    'وَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡأَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُوهُ بِهَا‌ۖ وَذَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُلۡحِدُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَسۡمَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِه<rule class=madda_normal>ِۦ‌ۚ</rule> سَيُ<rule class=qalaqah>جۡ</rule>زَوۡنَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٨٠',
    180, 9, 2, 174, 143, 69, 'false'
  );
  
  -- Ayah 181 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1135,
    'وَمِمَّنۡ خَلَقۡنَاۤ أُمَّةࣱ یَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ یَعۡدِلُونَ',
    'وممن خلقنا امة يهدون بالحق وبه يعدلون',
    'وَمِ<rule class=ghunnah>مّ</rule>َنۡ خَلَ<rule class=qalaqah>قۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَبِه<rule class=madda_normal>ِۦ</rule> يَعۡدِل<rule class=madda_permissible>ُو</rule>نَ ١٨١',
    181, 9, 2, 174, 143, 69, 'false'
  );
  
  -- Ayah 182 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1136,
    'وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا سَنَسۡتَدۡرِجُهُم مِّنۡ حَیۡثُ لَا یَعۡلَمُونَ',
    'والذين كذبوا باياتنا سنستدرجهم من حيث لا يعلمون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا سَنَسۡتَ<rule class=qalaqah>دۡ</rule>رِجُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ حَيۡثُ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٨٢',
    182, 9, 2, 174, 144, 69, 'false'
  );
  
  -- Ayah 183 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1137,
    'وَأُمۡلِی لَهُمۡۚ إِنَّ كَیۡدِی مَتِینٌ',
    'واملي لهم ان كيدي متين',
    'وَأُمۡلِى لَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ كَيۡدِى مَت<rule class=madda_permissible>ِي</rule>نٌ ١٨٣',
    183, 9, 2, 174, 144, 69, 'false'
  );
  
  -- Ayah 184 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1138,
    'أَوَلَمۡ یَتَفَكَّرُوا۟ۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِیرࣱ مُّبِینٌ',
    'اولم يتفكروا ما بصاحبهم من جنة ان هو الا نذير مبين',
    'أَوَلَمۡ يَتَفَكَّرُو<rule class=slnt>اۡ‌ۗ</rule> مَا بِصَاحِبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>ِ<rule class=ghunnah>نّ</rule>َةٍ‌ۚ إِنۡ هُوَ إِلَّا نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٨٤',
    184, 9, 2, 174, 144, 69, 'false'
  );
  
  -- Ayah 185 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1139,
    'أَوَلَمۡ یَنظُرُوا۟ فِی مَلَكُوتِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا خَلَقَ ٱللَّهُ مِن شَیۡءࣲ وَأَنۡ عَسَىٰۤ أَن یَكُونَ قَدِ ٱقۡتَرَبَ أَجَلُهُمۡۖ فَبِأَیِّ حَدِیثِۭ بَعۡدَهُۥ یُؤۡمِنُونَ',
    'اولم ينظروا في ملكوت السماوات والارض وما خلق الله من شيء وان عسى ان يكون قد اقترب اجلهم فباي حديث بعده يؤمنون',
    'أَوَلَمۡ يَ<rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> فِى مَلَكُوتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا خَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَنۡ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ قَدِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تَرَبَ أَجَلُهُمۡ‌ۖ فَبِأَىِّ حَدِي<rule class=iqlab>ثِۭ</rule> <rule class=iqlab>ب</rule>َعۡدَهُ<rule class=madda_normal>ۥ</rule> يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٨٥',
    185, 9, 2, 174, 144, 69, 'false'
  );
  
  -- Ayah 186 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1140,
    'مَن یُضۡلِلِ ٱللَّهُ فَلَا هَادِیَ لَهُۥۚ وَیَذَرُهُمۡ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ',
    'من يضلل الله فلا هادي له ويذرهم في طغيانهم يعمهون',
    'م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَلَا هَادِىَ لَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَيَذَرُهُمۡ فِى طُغۡيَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ يَعۡمَه<rule class=madda_permissible>ُو</rule>نَ ١٨٦',
    186, 9, 2, 174, 144, 69, 'false'
  );
  
  -- Ayah 187 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1141,
    'یَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَیَّانَ مُرۡسَىٰهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ رَبِّیۖ لَا یُجَلِّیهَا لِوَقۡتِهَاۤ إِلَّا هُوَۚ ثَقُلَتۡ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ لَا تَأۡتِیكُمۡ إِلَّا بَغۡتَةࣰۗ یَسۡـَٔلُونَكَ كَأَنَّكَ حَفِیٌّ عَنۡهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'يسالونك عن الساعة ايان مرساها قل انما علمها عند ربي لا يجليها لوقتها الا هو ثقلت في السماوات والارض لا تاتيكم الا بغتة يسالونك كانك حفي عنها قل انما علمها عند الله ولكن اكثر الناس لا يعلمون',
    'يَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ أَيَّانَ مُرۡسَ<rule class=madda_normal>ـٰ</rule>هَا‌ۖ قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا عِلۡمُهَا عِ<rule class=ikhafa>ند</rule>َ رَبِّى‌ۖ لَا يُجَلِّيهَا لِوَ<rule class=qalaqah>قۡ</rule>تِه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا هُوَ‌ۚ ثَقُلَتۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ لَا تَأۡتِيكُمۡ إِلَّا بَغۡتَ<rule class=idgham_ghunnah>ةً‌ۗ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡــَٔلُونَكَ كَأَ<rule class=ghunnah>نّ</rule>َكَ حَفِىٌّ عَنۡهَا‌ۖ قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا عِلۡمُهَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٨٧',
    187, 9, 2, 174, 144, 69, 'false'
  );
  
  -- Ayah 188 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1142,
    'قُل لَّاۤ أَمۡلِكُ لِنَفۡسِی نَفۡعࣰا وَلَا ضَرًّا إِلَّا مَا شَاۤءَ ٱللَّهُۚ وَلَوۡ كُنتُ أَعۡلَمُ ٱلۡغَیۡبَ لَٱسۡتَكۡثَرۡتُ مِنَ ٱلۡخَیۡرِ وَمَا مَسَّنِیَ ٱلسُّوۤءُۚ إِنۡ أَنَا۠ إِلَّا نَذِیرࣱ وَبَشِیرࣱ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'قل لا املك لنفسي نفعا ولا ضرا الا ما شاء الله ولو كنت اعلم الغيب لاستكثرت من الخير وما مسني السوء ان انا الا نذير وبشير لقوم يؤمنون',
    'قُل لّ<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡلِكُ لِنَفۡسِى نَفۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا ضَرًّا إِلَّا مَا ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَلَوۡ كُ<rule class=ikhafa>نت</rule>ُ أَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبَ لَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡثَرۡتُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ وَمَا مَسَّنِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ‌ۚ إِنۡ أَنَاۡ إِلَّا نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َبَشِي<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٨٨',
    188, 9, 2, 175, 144, 69, 'false'
  );
  
  -- Ayah 189 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1143,
    '۞ هُوَ ٱلَّذِی خَلَقَكُم مِّن نَّفۡسࣲ وَ ٰ⁠حِدَةࣲ وَجَعَلَ مِنۡهَا زَوۡجَهَا لِیَسۡكُنَ إِلَیۡهَاۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتۡ حَمۡلًا خَفِیفࣰا فَمَرَّتۡ بِهِۦۖ فَلَمَّاۤ أَثۡقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَىِٕنۡ ءَاتَیۡتَنَا صَـٰلِحࣰا لَّنَكُونَنَّ مِنَ ٱلشَّـٰكِرِینَ',
    'هو الذي خلقكم من نفس واحدة وجعل منها زوجها ليسكن اليها فلما تغشاها حملت حملا خفيفا فمرت به فلما اثقلت دعوا الله ربهما لئن اتيتنا صالحا لنكونن من الشاكرين',
    '۞هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ مِنۡهَا زَوۡجَهَا لِيَسۡكُنَ إِلَيۡهَا‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا تَغَشَّ<rule class=madda_normal>ـٰ</rule>هَا حَمَلَتۡ حَمۡلاً خَفِي<rule class=ikhafa>فًا</rule> <rule class=ikhafa>ف</rule>َمَرَّتۡ بِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَثۡقَلَ<rule class=idgham_mutajanisayn>ت</rule> دَّعَوَا <rule class=ham_wasl>ٱ</rule>للَّهَ رَبَّهُمَا لَئِنۡ ءَاتَيۡتَنَا صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_wo_ghunnah>حًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّنَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ١٨٩',
    189, 9, 2, 175, 145, 70, 'false'
  );
  
  -- Ayah 190 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1144,
    'فَلَمَّاۤ ءَاتَىٰهُمَا صَـٰلِحࣰا جَعَلَا لَهُۥ شُرَكَاۤءَ فِیمَاۤ ءَاتَىٰهُمَاۚ فَتَعَـٰلَى ٱللَّهُ عَمَّا یُشۡرِكُونَ',
    'فلما اتاهما صالحا جعلا له شركاء فيما اتاهما فتعالى الله عما يشركون',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمَا صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ج</rule>َعَلَا لَهُ<rule class=madda_normal>ۥ</rule> شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فِيم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمَا‌ۚ فَتَعَ<rule class=madda_normal>ـٰ</rule>لَى <rule class=ham_wasl>ٱ</rule>للَّهُ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ١٩٠',
    190, 9, 2, 175, 145, 70, 'false'
  );
  
  -- Ayah 191 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1145,
    'أَیُشۡرِكُونَ مَا لَا یَخۡلُقُ شَیۡـࣰٔا وَهُمۡ یُخۡلَقُونَ',
    'ايشركون ما لا يخلق شيئا وهم يخلقون',
    'أَيُشۡرِكُونَ مَا لَا يَخۡلُقُ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ يُخۡلَق<rule class=madda_permissible>ُو</rule>نَ ١٩١',
    191, 9, 2, 175, 145, 70, 'false'
  );
  
  -- Ayah 192 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1146,
    'وَلَا یَسۡتَطِیعُونَ لَهُمۡ نَصۡرࣰا وَلَاۤ أَنفُسَهُمۡ یَنصُرُونَ',
    'ولا يستطيعون لهم نصرا ولا انفسهم ينصرون',
    'وَلَا يَسۡتَطِيعُونَ لَهُمۡ نَصۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَ<rule class=ikhafa>نص</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ١٩٢',
    192, 9, 2, 175, 145, 70, 'false'
  );
  
  -- Ayah 193 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1147,
    'وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا یَتَّبِعُوكُمۡۚ سَوَاۤءٌ عَلَیۡكُمۡ أَدَعَوۡتُمُوهُمۡ أَمۡ أَنتُمۡ صَـٰمِتُونَ',
    'وان تدعوهم الى الهدى لا يتبعوكم سواء عليكم ادعوتموهم ام انتم صامتون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>عُوهُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ لَا يَتَّبِعُوكُمۡ‌ۚ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ عَلَيۡكُمۡ أَدَعَوۡتُمُوهُمۡ أَمۡ أَ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>مِت<rule class=madda_permissible>ُو</rule>نَ ١٩٣',
    193, 9, 2, 175, 145, 70, 'false'
  );
  
  -- Ayah 194 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1148,
    'إِنَّ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمۡثَالُكُمۡۖ فَٱدۡعُوهُمۡ فَلۡیَسۡتَجِیبُوا۟ لَكُمۡ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ان الذين تدعون من دون الله عباد امثالكم فادعوهم فليستجيبوا لكم ان كنتم صادقين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ عِبَادٌ أَمۡثَالُكُمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُوهُمۡ فَلۡيَسۡتَجِيبُو<rule class=slnt>اۡ</rule> لَكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٩٤',
    194, 9, 2, 175, 145, 70, 'false'
  );
  
  -- Ayah 195 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1149,
    'أَلَهُمۡ أَرۡجُلࣱ یَمۡشُونَ بِهَاۤۖ أَمۡ لَهُمۡ أَیۡدࣲ یَبۡطِشُونَ بِهَاۤۖ أَمۡ لَهُمۡ أَعۡیُنࣱ یُبۡصِرُونَ بِهَاۤۖ أَمۡ لَهُمۡ ءَاذَانࣱ یَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُوا۟ شُرَكَاۤءَكُمۡ ثُمَّ كِیدُونِ فَلَا تُنظِرُونِ',
    'الهم ارجل يمشون بها ام لهم ايد يبطشون بها ام لهم اعين يبصرون بها ام لهم اذان يسمعون بها قل ادعوا شركاءكم ثم كيدون فلا تنظرون',
    'أَلَهُمۡ أَرۡجُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>َمۡشُونَ بِه<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> أَمۡ لَهُمۡ أَيۡ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>طِشُونَ بِه<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> أَمۡ لَهُمۡ أَعۡيُ<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>بۡ</rule>صِرُونَ بِه<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> أَمۡ لَهُمۡ ءَاذَا<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡمَعُونَ بِهَا‌ۗ قُلِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ كِيدُونِ فَلَا تُ<rule class=ikhafa>نظ</rule>ِر<rule class=madda_permissible>ُو</rule>نِ ١٩٥',
    195, 9, 2, 175, 145, 70, 'false'
  );
  
  -- Ayah 196 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1150,
    'إِنَّ وَلِـِّۧیَ ٱللَّهُ ٱلَّذِی نَزَّلَ ٱلۡكِتَـٰبَۖ وَهُوَ یَتَوَلَّى ٱلصَّـٰلِحِینَ',
    'ان وليي الله الذي نزل الكتاب وهو يتولى الصالحين',
    'إِ<rule class=ghunnah>نّ</rule>َ وَلِــِّۧىَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى نَزَّلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ‌ۖ وَهُوَ يَتَوَلَّى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ١٩٦',
    196, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 197 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1151,
    'وَٱلَّذِینَ تَدۡعُونَ مِن دُونِهِۦ لَا یَسۡتَطِیعُونَ نَصۡرَكُمۡ وَلَاۤ أَنفُسَهُمۡ یَنصُرُونَ',
    'والذين تدعون من دونه لا يستطيعون نصركم ولا انفسهم ينصرون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> لَا يَسۡتَطِيعُونَ نَصۡرَكُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَ<rule class=ikhafa>نص</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ١٩٧',
    197, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 198 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1152,
    'وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا یَسۡمَعُوا۟ۖ وَتَرَىٰهُمۡ یَنظُرُونَ إِلَیۡكَ وَهُمۡ لَا یُبۡصِرُونَ',
    'وان تدعوهم الى الهدى لا يسمعوا وتراهم ينظرون اليك وهم لا يبصرون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>عُوهُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ لَا يَسۡمَعُو<rule class=slnt>اۡ‌ۖ</rule> وَتَرَ<rule class=madda_normal>ٮٰ</rule>هُمۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلَيۡكَ وَهُمۡ لَا يُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ١٩٨',
    198, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 199 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1153,
    'خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ بِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَـٰهِلِینَ',
    'خذ العفو وامر بالعرف واعرض عن الجاهلين',
    'خُذِ <rule class=ham_wasl>ٱ</rule>لۡعَفۡوَ وَأۡمُرۡ بِ<rule class=ham_wasl>ٱ</rule>لۡعُرۡفِ وَأَعۡرِضۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِل<rule class=madda_permissible>ِي</rule>نَ ١٩٩',
    199, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 200 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1154,
    'وَإِمَّا یَنزَغَنَّكَ مِنَ ٱلشَّیۡطَـٰنِ نَزۡغࣱ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِیعٌ عَلِیمٌ',
    'واما ينزغنك من الشيطان نزغ فاستعذ بالله انه سميع عليم',
    'وَإِ<rule class=ghunnah>مّ</rule>َا يَ<rule class=ikhafa>نز</rule>َغَ<rule class=ghunnah>نّ</rule>َكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ نَزۡ<rule class=ikhafa>غٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَعِذۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٠٠',
    200, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 201 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1155,
    'إِنَّ ٱلَّذِینَ ٱتَّقَوۡا۟ إِذَا مَسَّهُمۡ طَـٰۤىِٕفࣱ مِّنَ ٱلشَّیۡطَـٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبۡصِرُونَ',
    'ان الذين اتقوا اذا مسهم طائف من الشيطان تذكروا فاذا هم مبصرون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> إِذَا مَسَّهُمۡ طَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِ<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ تَذَكَّرُو<rule class=slnt>اۡ</rule> فَإِذَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٢٠١',
    201, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 202 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1156,
    'وَإِخۡوَ ٰ⁠نُهُمۡ یَمُدُّونَهُمۡ فِی ٱلۡغَیِّ ثُمَّ لَا یُقۡصِرُونَ',
    'واخوانهم يمدونهم في الغي ثم لا يقصرون',
    'وَإِخۡو<rule class=madda_normal>ٰ</rule>نُهُمۡ يَمُدُّونَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡغَىِّ ثُ<rule class=ghunnah>مّ</rule>َ لَا يُ<rule class=qalaqah>قۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٢٠٢',
    202, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 203 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1157,
    'وَإِذَا لَمۡ تَأۡتِهِم بِـَٔایَةࣲ قَالُوا۟ لَوۡلَا ٱجۡتَبَیۡتَهَاۚ قُلۡ إِنَّمَاۤ أَتَّبِعُ مَا یُوحَىٰۤ إِلَیَّ مِن رَّبِّیۚ هَـٰذَا بَصَاۤىِٕرُ مِن رَّبِّكُمۡ وَهُدࣰى وَرَحۡمَةࣱ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'واذا لم تاتهم باية قالوا لولا اجتبيتها قل انما اتبع ما يوحى الي من ربي هذا بصائر من ربكم وهدى ورحمة لقوم يؤمنون',
    'وَإِذَا لَمۡ تَأۡتِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> لَوۡلَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَبَيۡتَهَا‌ۚ قُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَتَّبِعُ مَا يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىَّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّى‌ۚ هَ<rule class=madda_normal>ـٰ</rule>ذَا بَص<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٢٠٣',
    203, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 204 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1158,
    'وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمۡ تُرۡحَمُونَ',
    'واذا قرئ القران فاستمعوا له وانصتوا لعلكم ترحمون',
    'وَإِذَا قُرِئَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانُ فَ<rule class=ham_wasl>ٱ</rule>سۡتَمِعُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> وَأَ<rule class=ikhafa>نص</rule>ِتُو<rule class=slnt>اۡ</rule> لَعَلَّكُمۡ تُرۡحَم<rule class=madda_permissible>ُو</rule>نَ ٢٠٤',
    204, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 205 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1159,
    'وَٱذۡكُر رَّبَّكَ فِی نَفۡسِكَ تَضَرُّعࣰا وَخِیفَةࣰ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلۡغَـٰفِلِینَ',
    'واذكر ربك في نفسك تضرعا وخيفة ودون الجهر من القول بالغدو والاصال ولا تكن من الغافلين',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُر رَّبَّكَ فِى نَفۡسِكَ تَضَرُّ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َخِيفَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َدُونَ <rule class=ham_wasl>ٱ</rule>لۡجَهۡرِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ بِ<rule class=ham_wasl>ٱ</rule>لۡغُدُوِّ وَ<rule class=ham_wasl>ٱ</rule>لۡأَصَالِ وَلَا تَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ٢٠٥',
    205, 9, 2, 176, 145, 70, 'false'
  );
  
  -- Ayah 206 Surah Al-Araaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    7,
    1160,
    'إِنَّ ٱلَّذِینَ عِندَ رَبِّكَ لَا یَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَیُسَبِّحُونَهُۥ وَلَهُۥ یَسۡجُدُونَ ۩',
    'ان الذين عند ربك لا يستكبرون عن عبادته ويسبحونه وله يسجدون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِه<rule class=madda_normal>ِۦ</rule> وَيُسَبِّحُونَهُ<rule class=madda_normal>ۥ</rule> وَلَهُ<rule class=madda_normal>ۥ</rule> يَسۡجُدُ<rule class=madda_permissible>و</rule>نَ ۩ ٢٠٦',
    206, 9, 2, 176, 145, 70, '{"id":1,"recommended":true,"obligatory":false}'
  );
  

-- Surah Al-Anfaal
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (8, 'سُورَةُ الأَنفَالِ', 'Al-Anfaal', 'The Spoils of War', 'Medinan', 75);

  -- Ayah 1 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1161,
    'یَسۡـَٔلُونَكَ عَنِ ٱلۡأَنفَالِۖ قُلِ ٱلۡأَنفَالُ لِلَّهِ وَٱلرَّسُولِۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصۡلِحُوا۟ ذَاتَ بَیۡنِكُمۡۖ وَأَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥۤ إِن كُنتُم مُّؤۡمِنِینَ',
    'يسالونك عن الانفال قل الانفال لله والرسول فاتقوا الله واصلحوا ذات بينكم واطيعوا الله ورسوله ان كنتم مؤمنين',
    'يَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>َالِ‌ۖ قُلِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>َالُ لِلَّهِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَصۡلِحُو<rule class=slnt>اۡ</rule> ذَاتَ بَيۡنِكُمۡ‌ۖ وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١',
    1, 9, 2, 177, 146, 71, 'false'
  );
  
  -- Ayah 2 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1162,
    'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِینَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِیَتۡ عَلَیۡهِمۡ ءَایَـٰتُهُۥ زَادَتۡهُمۡ إِیمَـٰنࣰا وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ',
    'انما المؤمنون الذين اذا ذكر الله وجلت قلوبهم واذا تليت عليهم اياته زادتهم ايمانا وعلى ربهم يتوكلون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ إِذَا ذُكِرَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُهُ<rule class=madda_normal>ۥ</rule> زَادَتۡهُمۡ إِيمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َعَلَىٰ رَبِّهِمۡ يَتَوَكَّل<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 9, 2, 177, 146, 71, 'false'
  );
  
  -- Ayah 3 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1163,
    'ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ',
    'الذين يقيمون الصلاة ومما رزقناهم ينفقون',
    'ٱلَّذِينَ يُقِيمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَمِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ يُ<rule class=ikhafa>نف</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 9, 2, 177, 146, 71, 'false'
  );
  
  -- Ayah 4 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1164,
    'أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقࣰّاۚ لَّهُمۡ دَرَجَـٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ',
    'اولئك هم المؤمنون حقا لهم درجات عند ربهم ومغفرة ورزق كريم',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ حَق<rule class=idgham_wo_ghunnah>ًّا‌ۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ دَرَجَ<rule class=madda_normal>ـٰ</rule>تٌ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ وَمَغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َرِزۡ<rule class=ikhafa>قٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٤',
    4, 9, 2, 177, 146, 71, 'false'
  );
  
  -- Ayah 5 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1165,
    'كَمَاۤ أَخۡرَجَكَ رَبُّكَ مِنۢ بَیۡتِكَ بِٱلۡحَقِّ وَإِنَّ فَرِیقࣰا مِّنَ ٱلۡمُؤۡمِنِینَ لَكَـٰرِهُونَ',
    'كما اخرجك ربك من بيتك بالحق وان فريقا من المؤمنين لكارهون',
    'كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡرَجَكَ رَبُّكَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡتِكَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَإِ<rule class=ghunnah>نّ</rule>َ فَرِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ لَكَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 9, 2, 177, 146, 71, 'false'
  );
  
  -- Ayah 6 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1166,
    'یُجَـٰدِلُونَكَ فِی ٱلۡحَقِّ بَعۡدَ مَا تَبَیَّنَ كَأَنَّمَا یُسَاقُونَ إِلَى ٱلۡمَوۡتِ وَهُمۡ یَنظُرُونَ',
    'يجادلونك في الحق بعدما تبين كانما يساقون الى الموت وهم ينظرون',
    'يُجَ<rule class=madda_normal>ـٰ</rule>دِلُونَكَ فِى <rule class=ham_wasl>ٱ</rule>لۡحَقِّ بَعۡدَ مَا تَبَيَّنَ كَأَ<rule class=ghunnah>نّ</rule>َمَا يُسَاقُونَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ وَهُمۡ يَ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 9, 2, 177, 146, 71, 'false'
  );
  
  -- Ayah 7 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1167,
    'وَإِذۡ یَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّاۤىِٕفَتَیۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَیۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَیُرِیدُ ٱللَّهُ أَن یُحِقَّ ٱلۡحَقَّ بِكَلِمَـٰتِهِۦ وَیَقۡطَعَ دَابِرَ ٱلۡكَـٰفِرِینَ',
    'واذ يعدكم الله احدى الطائفتين انها لكم وتودون ان غير ذات الشوكة تكون لكم ويريد الله ان يحق الحق بكلماته ويقطع دابر الكافرين',
    'وَإِذۡ يَعِدُكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ إِحۡدَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَتَيۡنِ أَ<rule class=ghunnah>نّ</rule>َهَا لَكُمۡ وَتَوَدُّونَ أَ<rule class=ghunnah>نّ</rule>َ غَيۡرَ ذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحِقَّ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ بِكَلِمَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَيَ<rule class=qalaqah>قۡ</rule>طَعَ دَابِرَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 9, 2, 177, 146, 71, 'false'
  );
  
  -- Ayah 8 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1168,
    'لِیُحِقَّ ٱلۡحَقَّ وَیُبۡطِلَ ٱلۡبَـٰطِلَ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ',
    'ليحق الحق ويبطل الباطل ولو كره المجرمون',
    'لِيُحِقَّ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَيُ<rule class=qalaqah>بۡ</rule>طِلَ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلَ وَلَوۡ كَرِهَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 9, 2, 177, 146, 71, 'false'
  );
  
  -- Ayah 9 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1169,
    'إِذۡ تَسۡتَغِیثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّی مُمِدُّكُم بِأَلۡفࣲ مِّنَ ٱلۡمَلَـٰۤىِٕكَةِ مُرۡدِفِینَ',
    'اذ تستغيثون ربكم فاستجاب لكم اني ممدكم بالف من الملائكة مردفين',
    'إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَجَابَ لَكُمۡ أَ<rule class=ghunnah>نّ</rule>ِى مُمِدُّك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَلۡ<rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ مُرۡدِف<rule class=madda_permissible>ِي</rule>نَ ٩',
    9, 9, 2, 178, 146, 71, 'false'
  );
  
  -- Ayah 10 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1170,
    'وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَىِٕنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمٌ',
    'وما جعله الله الا بشرى ولتطمئن به قلوبكم وما النصر الا من عند الله ان الله عزيز حكيم',
    'وَمَا جَعَلَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَّا بُشۡرَىٰ وَلِتَ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>َ بِه<rule class=madda_normal>ِۦ</rule> قُلُوبُكُمۡ‌ۚ وَمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصۡرُ إِلَّا مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ١٠',
    10, 9, 2, 178, 146, 71, 'false'
  );
  
  -- Ayah 11 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1171,
    'إِذۡ یُغَشِّیكُمُ ٱلنُّعَاسَ أَمَنَةࣰ مِّنۡهُ وَیُنَزِّلُ عَلَیۡكُم مِّنَ ٱلسَّمَاۤءِ مَاۤءࣰ لِّیُطَهِّرَكُم بِهِۦ وَیُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّیۡطَـٰنِ وَلِیَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَیُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ',
    'اذ يغشيكم النعاس امنة منه وينزل عليكم من السماء ماء ليطهركم به ويذهب عنكم رجز الشيطان وليربط على قلوبكم ويثبت به الاقدام',
    'إِذۡ يُغَشِّيكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُعَاسَ أَمَنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ وَيُنَزِّلُ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_wo_ghunnah>ءً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُطَهِّرَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> وَيُذۡهِبَ عَ<rule class=ikhafa>نك</rule>ُمۡ رِ<rule class=qalaqah>جۡ</rule>زَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>د<rule class=madda_permissible>َا</rule>مَ ١١',
    11, 9, 2, 178, 147, 71, 'false'
  );
  
  -- Ayah 12 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1172,
    'إِذۡ یُوحِی رَبُّكَ إِلَى ٱلۡمَلَـٰۤىِٕكَةِ أَنِّی مَعَكُمۡ فَثَبِّتُوا۟ ٱلَّذِینَ ءَامَنُوا۟ۚ سَأُلۡقِی فِی قُلُوبِ ٱلَّذِینَ كَفَرُوا۟ ٱلرُّعۡبَ فَٱضۡرِبُوا۟ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُوا۟ مِنۡهُمۡ كُلَّ بَنَانࣲ',
    'اذ يوحي ربك الى الملائكة اني معكم فثبتوا الذين امنوا سالقي في قلوب الذين كفروا الرعب فاضربوا فوق الاعناق واضربوا منهم كل بنان',
    'إِذۡ يُوحِى رَبُّكَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ أَ<rule class=ghunnah>نّ</rule>ِى مَعَكُمۡ فَثَبِّتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ‌ۚ</rule> سَأُلۡقِى فِى قُلُوبِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّعۡبَ فَ<rule class=ham_wasl>ٱ</rule>ضۡرِبُو<rule class=slnt>اۡ</rule> فَوۡقَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡنَاقِ وَ<rule class=ham_wasl>ٱ</rule>ضۡرِبُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ كُلَّ بَن<rule class=madda_permissible>َا</rule>نٍ ١٢',
    12, 9, 2, 178, 147, 71, 'false'
  );
  
  -- Ayah 13 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1173,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمۡ شَاۤقُّوا۟ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن یُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ',
    'ذلك بانهم شاقوا الله ورسوله ومن يشاقق الله ورسوله فان الله شديد العقاب',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ ش<rule class=madda_necessary>َا</rule>ٓقُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُشَاقِقِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٣',
    13, 9, 2, 178, 147, 71, 'false'
  );
  
  -- Ayah 14 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1174,
    'ذَ ٰ⁠لِكُمۡ فَذُوقُوهُ وَأَنَّ لِلۡكَـٰفِرِینَ عَذَابَ ٱلنَّارِ',
    'ذلكم فذوقوه وان للكافرين عذاب النار',
    'ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ فَذُوقُوهُ وَأَ<rule class=ghunnah>نّ</rule>َ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ١٤',
    14, 9, 2, 178, 147, 71, 'false'
  );
  
  -- Ayah 15 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1175,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا لَقِیتُمُ ٱلَّذِینَ كَفَرُوا۟ زَحۡفࣰا فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ',
    'يا ايها الذين امنوا اذا لقيتم الذين كفروا زحفا فلا تولوهم الادبار',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا لَقِيتُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> زَحۡ<rule class=ikhafa>فًا</rule> <rule class=ikhafa>ف</rule>َلَا تُوَلُّوهُمُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>دۡ</rule>ب<rule class=madda_permissible>َا</rule>رَ ١٥',
    15, 9, 2, 178, 147, 71, 'false'
  );
  
  -- Ayah 16 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1176,
    'وَمَن یُوَلِّهِمۡ یَوۡمَىِٕذࣲ دُبُرَهُۥۤ إِلَّا مُتَحَرِّفࣰا لِّقِتَالٍ أَوۡ مُتَحَیِّزًا إِلَىٰ فِئَةࣲ فَقَدۡ بَاۤءَ بِغَضَبࣲ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'ومن يولهم يومئذ دبره الا متحرفا لقتال او متحيزا الى فئة فقد باء بغضب من الله وماواه جهنم وبئس المصير',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُوَلِّهِمۡ يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>د</rule>ُبُرَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا مُتَحَرِّ<rule class=idgham_wo_ghunnah>فًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقِتَالٍ أَوۡ مُتَحَيِّزًا إِلَىٰ فِئَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َقَ<rule class=qalaqah>دۡ</rule> ب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِغَضَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٦',
    16, 9, 2, 178, 147, 71, 'false'
  );
  
  -- Ayah 17 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1177,
    'فَلَمۡ تَقۡتُلُوهُمۡ وَلَـٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَیۡتَ إِذۡ رَمَیۡتَ وَلَـٰكِنَّ ٱللَّهَ رَمَىٰ وَلِیُبۡلِیَ ٱلۡمُؤۡمِنِینَ مِنۡهُ بَلَاۤءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ',
    'فلم تقتلوهم ولكن الله قتلهم وما رميت اذ رميت ولكن الله رمى وليبلي المؤمنين منه بلاء حسنا ان الله سميع عليم',
    'فَلَمۡ تَ<rule class=qalaqah>قۡ</rule>تُلُوهُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَتَلَهُمۡ‌ۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ رَمَىٰ‌ۚ وَلِيُ<rule class=qalaqah>بۡ</rule>لِىَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ مِنۡهُ بَل<rule class=madda_obligatory_mottasel>َا</rule>ٓءً حَسَنًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٧',
    17, 9, 2, 179, 147, 71, 'false'
  );
  
  -- Ayah 18 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1178,
    'ذَ ٰ⁠لِكُمۡ وَأَنَّ ٱللَّهَ مُوهِنُ كَیۡدِ ٱلۡكَـٰفِرِینَ',
    'ذلكم وان الله موهن كيد الكافرين',
    'ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مُوهِنُ كَيۡدِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٨',
    18, 9, 2, 179, 147, 71, 'false'
  );
  
  -- Ayah 19 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1179,
    'إِن تَسۡتَفۡتِحُوا۟ فَقَدۡ جَاۤءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُوا۟ فَهُوَ خَیۡرࣱ لَّكُمۡۖ وَإِن تَعُودُوا۟ نَعُدۡ وَلَن تُغۡنِیَ عَنكُمۡ فِئَتُكُمۡ شَیۡـࣰٔا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِینَ',
    'ان تستفتحوا فقد جاءكم الفتح وان تنتهوا فهو خير لكم وان تعودوا نعد ولن تغني عنكم فئتكم شيئا ولو كثرت وان الله مع المؤمنين',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَفۡتِحُو<rule class=slnt>اۡ</rule> فَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمُ <rule class=ham_wasl>ٱ</rule>لۡفَتۡحُ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نت</rule>َهُو<rule class=slnt>اۡ</rule> فَهُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعُودُو<rule class=slnt>اۡ</rule> نَعُ<rule class=qalaqah>دۡ</rule> وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُغۡنِىَ عَ<rule class=ikhafa>نك</rule>ُمۡ فِئَتُكُمۡ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ كَثُرَتۡ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَعَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٩',
    19, 9, 2, 179, 147, 71, 'false'
  );
  
  -- Ayah 20 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1180,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوۡا۟ عَنۡهُ وَأَنتُمۡ تَسۡمَعُونَ',
    'يا ايها الذين امنوا اطيعوا الله ورسوله ولا تولوا عنه وانتم تسمعون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> وَلَا تَوَلَّوۡ<rule class=slnt>اۡ</rule> عَنۡهُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَسۡمَع<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 9, 2, 179, 148, 71, 'false'
  );
  
  -- Ayah 21 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1181,
    'وَلَا تَكُونُوا۟ كَٱلَّذِینَ قَالُوا۟ سَمِعۡنَا وَهُمۡ لَا یَسۡمَعُونَ',
    'ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون',
    'وَلَا تَكُونُو<rule class=slnt>اۡ</rule> كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ قَالُو<rule class=slnt>اۡ</rule> سَمِعۡنَا وَهُمۡ لَا يَسۡمَع<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 9, 2, 179, 148, 71, 'false'
  );
  
  -- Ayah 22 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1182,
    '۞ إِنَّ شَرَّ ٱلدَّوَاۤبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِینَ لَا یَعۡقِلُونَ',
    'ان شر الدواب عند الله الصم البكم الذين لا يعقلون',
    '۞إِ<rule class=ghunnah>نّ</rule>َ شَرَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّو<rule class=madda_necessary>َا</rule>ٓبِّ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّ<rule class=ghunnah>مّ</rule>ُ <rule class=ham_wasl>ٱ</rule>لۡبُكۡمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 9, 2, 179, 148, 72, 'false'
  );
  
  -- Ayah 23 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1183,
    'وَلَوۡ عَلِمَ ٱللَّهُ فِیهِمۡ خَیۡرࣰا لَّأَسۡمَعَهُمۡۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّوا۟ وَّهُم مُّعۡرِضُونَ',
    'ولو علم الله فيهم خيرا لاسمعهم ولو اسمعهم لتولوا وهم معرضون',
    'وَلَوۡ عَلِمَ <rule class=ham_wasl>ٱ</rule>للَّهُ فِيهِمۡ خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّأَسۡمَعَهُمۡ‌ۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّو<rule class=slnt>اۡ</rule> وَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 9, 2, 179, 148, 72, 'false'
  );
  
  -- Ayah 24 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1184,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱسۡتَجِیبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا یُحۡیِیكُمۡۖ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَحُولُ بَیۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ وَأَنَّهُۥۤ إِلَیۡهِ تُحۡشَرُونَ',
    'يا ايها الذين امنوا استجيبوا لله وللرسول اذا دعاكم لما يحييكم واعلموا ان الله يحول بين المرء وقلبه وانه اليه تحشرون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>سۡتَجِيبُو<rule class=slnt>اۡ</rule> لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَحُولُ بَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡمَرۡءِ وَقَلۡبِه<rule class=madda_normal>ِۦ</rule> وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَيۡهِ تُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 9, 2, 179, 148, 72, 'false'
  );
  
  -- Ayah 25 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1185,
    'وَٱتَّقُوا۟ فِتۡنَةࣰ لَّا تُصِیبَنَّ ٱلَّذِینَ ظَلَمُوا۟ مِنكُمۡ خَاۤصَّةࣰۖ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ',
    'واتقوا فتنة لا تصيبن الذين ظلموا منكم خاصة واعلموا ان الله شديد العقاب',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> فِتۡنَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تُصِيبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ خ<rule class=madda_necessary>َا</rule>ٓصَّ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢٥',
    25, 9, 2, 179, 148, 72, 'false'
  );
  
  -- Ayah 26 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1186,
    'وَٱذۡكُرُوۤا۟ إِذۡ أَنتُمۡ قَلِیلࣱ مُّسۡتَضۡعَفُونَ فِی ٱلۡأَرۡضِ تَخَافُونَ أَن یَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمۡ وَأَیَّدَكُم بِنَصۡرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّیِّبَـٰتِ لَعَلَّكُمۡ تَشۡكُرُونَ',
    'واذكروا اذ انتم قليل مستضعفون في الارض تخافون ان يتخطفكم الناس فاواكم وايدكم بنصره ورزقكم من الطيبات لعلكم تشكرون',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذۡ أَ<rule class=ikhafa>نت</rule>ُمۡ قَلِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَضۡعَفُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ تَخَافُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَخَطَّفَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ فَـَٔـاوَ<rule class=madda_normal>ٮٰ</rule>كُمۡ وَأَيَّدَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِنَصۡرِه<rule class=madda_normal>ِۦ</rule> وَرَزَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ لَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 9, 2, 180, 148, 72, 'false'
  );
  
  -- Ayah 27 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1187,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوۤا۟ أَمَـٰنَـٰتِكُمۡ وَأَنتُمۡ تَعۡلَمُونَ',
    'يا ايها الذين امنوا لا تخونوا الله والرسول وتخونوا اماناتكم وانتم تعلمون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَخُونُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ وَتَخُون<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمَ<rule class=madda_normal>ـٰ</rule>نَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 9, 2, 180, 148, 72, 'false'
  );
  
  -- Ayah 28 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1188,
    'وَٱعۡلَمُوۤا۟ أَنَّمَاۤ أَمۡوَ ٰ⁠لُكُمۡ وَأَوۡلَـٰدُكُمۡ فِتۡنَةࣱ وَأَنَّ ٱللَّهَ عِندَهُۥۤ أَجۡرٌ عَظِیمࣱ',
    'واعلموا انما اموالكم واولادكم فتنة وان الله عنده اجر عظيم',
    'وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لُكُمۡ وَأَوۡلَ<rule class=madda_normal>ـٰ</rule>دُكُمۡ فِتۡنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=qalaqah>جۡ</rule>رٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٢٨',
    28, 9, 2, 180, 148, 72, 'false'
  );
  
  -- Ayah 29 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1189,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن تَتَّقُوا۟ ٱللَّهَ یَجۡعَل لَّكُمۡ فُرۡقَانࣰا وَیُكَفِّرۡ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَیَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ',
    'يا ايها الذين امنوا ان تتقوا الله يجعل لكم فرقانا ويكفر عنكم سيئاتكم ويغفر لكم والله ذو الفضل العظيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>جۡ</rule>عَل لَّكُمۡ فُرۡقَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َيُكَفِّرۡ عَ<rule class=ikhafa>نك</rule>ُمۡ سَيِّـَٔـاتِكُمۡ وَيَغۡفِرۡ لَكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ ذُو <rule class=ham_wasl>ٱ</rule>لۡفَضۡلِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٢٩',
    29, 9, 2, 180, 149, 72, 'false'
  );
  
  -- Ayah 30 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1190,
    'وَإِذۡ یَمۡكُرُ بِكَ ٱلَّذِینَ كَفَرُوا۟ لِیُثۡبِتُوكَ أَوۡ یَقۡتُلُوكَ أَوۡ یُخۡرِجُوكَۚ وَیَمۡكُرُونَ وَیَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَیۡرُ ٱلۡمَـٰكِرِینَ',
    'واذ يمكر بك الذين كفروا ليثبتوك او يقتلوك او يخرجوك ويمكرون ويمكر الله والله خير الماكرين',
    'وَإِذۡ يَمۡكُرُ بِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لِيُثۡبِتُوكَ أَوۡ يَ<rule class=qalaqah>قۡ</rule>تُلُوكَ أَوۡ يُخۡرِجُوكَ‌ۚ وَيَمۡكُرُونَ وَيَمۡكُرُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ٣٠',
    30, 9, 2, 180, 149, 72, 'false'
  );
  
  -- Ayah 31 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1191,
    'وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا قَالُوا۟ قَدۡ سَمِعۡنَا لَوۡ نَشَاۤءُ لَقُلۡنَا مِثۡلَ هَـٰذَاۤ إِنۡ هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ',
    'واذا تتلى عليهم اياتنا قالوا قد سمعنا لو نشاء لقلنا مثل هذا ان هذا الا اساطير الاولين',
    'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا قَالُو<rule class=slnt>اۡ</rule> قَ<rule class=qalaqah>دۡ</rule> سَمِعۡنَا لَوۡ نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لَقُلۡنَا مِثۡلَ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ‌ۙ</rule> إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 9, 2, 180, 149, 72, 'false'
  );
  
  -- Ayah 32 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1192,
    'وَإِذۡ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَـٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَیۡنَا حِجَارَةࣰ مِّنَ ٱلسَّمَاۤءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِیمࣲ',
    'واذ قالوا اللهم ان كان هذا هو الحق من عندك فامطر علينا حجارة من السماء او ائتنا بعذاب اليم',
    'وَإِذۡ قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّهُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ هَ<rule class=madda_normal>ـٰ</rule>ذَا هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ مِنۡ عِ<rule class=ikhafa>ند</rule>ِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَوِ <rule class=ham_wasl>ٱ</rule>ئۡتِنَا بِعَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٣٢',
    32, 9, 2, 180, 149, 72, 'false'
  );
  
  -- Ayah 33 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1193,
    'وَمَا كَانَ ٱللَّهُ لِیُعَذِّبَهُمۡ وَأَنتَ فِیهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ یَسۡتَغۡفِرُونَ',
    'وما كان الله ليعذبهم وانت فيهم وما كان الله معذبهم وهم يستغفرون',
    'وَمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيُعَذِّبَهُمۡ وَأَ<rule class=ikhafa>نت</rule>َ فِيهِمۡ‌ۚ وَمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِر<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 9, 2, 180, 149, 72, 'false'
  );
  
  -- Ayah 34 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1194,
    'وَمَا لَهُمۡ أَلَّا یُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ یَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوۤا۟ أَوۡلِیَاۤءَهُۥۤۚ إِنۡ أَوۡلِیَاۤؤُهُۥۤ إِلَّا ٱلۡمُتَّقُونَ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'وما لهم الا يعذبهم الله وهم يصدون عن المسجد الحرام وما كانوا اولياءه ان اولياؤه الا المتقون ولكن اكثرهم لا يعلمون',
    'وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَهُمۡ يَصُدُّونَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ وَمَا كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِنۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡمُتَّقُونَ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 9, 2, 181, 149, 72, 'false'
  );
  
  -- Ayah 35 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1195,
    'وَمَا كَانَ صَلَاتُهُمۡ عِندَ ٱلۡبَیۡتِ إِلَّا مُكَاۤءࣰ وَتَصۡدِیَةࣰۚ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ',
    'وما كان صلاتهم عند البيت الا مكاء وتصدية فذوقوا العذاب بما كنتم تكفرون',
    'وَمَا كَانَ صَلَاتُهُمۡ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتِ إِلَّا مُك<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َتَصۡدِيَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ف</rule>َذُوقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 9, 2, 181, 149, 72, 'false'
  );
  
  -- Ayah 36 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1196,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ یُنفِقُونَ أَمۡوَ ٰ⁠لَهُمۡ لِیَصُدُّوا۟ عَن سَبِیلِ ٱللَّهِۚ فَسَیُنفِقُونَهَا ثُمَّ تَكُونُ عَلَیۡهِمۡ حَسۡرَةࣰ ثُمَّ یُغۡلَبُونَۗ وَٱلَّذِینَ كَفَرُوۤا۟ إِلَىٰ جَهَنَّمَ یُحۡشَرُونَ',
    'ان الذين كفروا ينفقون اموالهم ليصدوا عن سبيل الله فسينفقونها ثم تكون عليهم حسرة ثم يغلبون والذين كفروا الى جهنم يحشرون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> يُ<rule class=ikhafa>نف</rule>ِقُونَ أَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ لِيَصُدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ فَسَيُ<rule class=ikhafa>نف</rule>ِقُونَهَا ثُ<rule class=ghunnah>مّ</rule>َ تَكُونُ عَلَيۡهِمۡ حَسۡرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ يُغۡلَبُونَ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ جَهَ<rule class=ghunnah>نّ</rule>َمَ يُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 9, 2, 181, 149, 72, 'false'
  );
  
  -- Ayah 37 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1197,
    'لِیَمِیزَ ٱللَّهُ ٱلۡخَبِیثَ مِنَ ٱلطَّیِّبِ وَیَجۡعَلَ ٱلۡخَبِیثَ بَعۡضَهُۥ عَلَىٰ بَعۡضࣲ فَیَرۡكُمَهُۥ جَمِیعࣰا فَیَجۡعَلَهُۥ فِی جَهَنَّمَۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ',
    'ليميز الله الخبيث من الطيب ويجعل الخبيث بعضه على بعض فيركمه جميعا فيجعله في جهنم اولئك هم الخاسرون',
    'لِيَمِيزَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡخَبِيثَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبِ وَيَ<rule class=qalaqah>جۡ</rule>عَلَ <rule class=ham_wasl>ٱ</rule>لۡخَبِيثَ بَعۡضَهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ بَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ف</rule>َيَرۡكُمَهُ<rule class=madda_normal>ۥ</rule> جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َيَ<rule class=qalaqah>جۡ</rule>عَلَهُ<rule class=madda_normal>ۥ</rule> فِى جَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 9, 2, 181, 149, 72, 'false'
  );
  
  -- Ayah 38 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1198,
    'قُل لِّلَّذِینَ كَفَرُوۤا۟ إِن یَنتَهُوا۟ یُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ وَإِن یَعُودُوا۟ فَقَدۡ مَضَتۡ سُنَّتُ ٱلۡأَوَّلِینَ',
    'قل للذين كفروا ان ينتهوا يغفر لهم ما قد سلف وان يعودوا فقد مضت سنت الاولين',
    'قُل لِّلَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نت</rule>َهُو<rule class=slnt>اۡ</rule> يُغۡفَرۡ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا قَ<rule class=qalaqah>دۡ</rule> سَلَفَ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َعُودُو<rule class=slnt>اۡ</rule> فَقَ<rule class=qalaqah>دۡ</rule> مَضَتۡ سُ<rule class=ghunnah>نّ</rule>َتُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٣٨',
    38, 9, 2, 181, 150, 72, 'false'
  );
  
  -- Ayah 39 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1199,
    'وَقَـٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةࣱ وَیَكُونَ ٱلدِّینُ كُلُّهُۥ لِلَّهِۚ فَإِنِ ٱنتَهَوۡا۟ فَإِنَّ ٱللَّهَ بِمَا یَعۡمَلُونَ بَصِیرࣱ',
    'وقاتلوهم حتى لا تكون فتنة ويكون الدين كله لله فان انتهوا فان الله بما يعملون بصير',
    'وَقَ<rule class=madda_normal>ـٰ</rule>تِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َيَكُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينُ كُلُّهُ<rule class=madda_normal>ۥ</rule> لِلَّهِ‌ۚ فَإِنِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َهَوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِمَا يَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٣٩',
    39, 9, 2, 181, 150, 72, 'false'
  );
  
  -- Ayah 40 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1200,
    'وَإِن تَوَلَّوۡا۟ فَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِیرُ',
    'وان تولوا فاعلموا ان الله مولاكم نعم المولى ونعم النصير',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَوۡلَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۚ نِعۡمَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡلَىٰ وَنِعۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َص<rule class=madda_permissible>ِي</rule>رُ ٤٠',
    40, 9, 2, 181, 150, 72, 'false'
  );
  
  -- Ayah 41 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1201,
    '۞ وَٱعۡلَمُوۤا۟ أَنَّمَا غَنِمۡتُم مِّن شَیۡءࣲ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱبۡنِ ٱلسَّبِیلِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ وَمَاۤ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا یَوۡمَ ٱلۡفُرۡقَانِ یَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'واعلموا انما غنمتم من شيء فان لله خمسه وللرسول ولذي القربى واليتامى والمساكين وابن السبيل ان كنتم امنتم بالله وما انزلنا على عبدنا يوم الفرقان يوم التقى الجمعان والله على كل شيء قدير',
    '۞وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َمَا غَنِمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=ghunnah>نّ</rule>َ لِلَّهِ خُمُسَهُ<rule class=madda_normal>ۥ</rule> وَلِلرَّسُولِ وَلِذِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ ءَامَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَىٰ عَ<rule class=qalaqah>بۡ</rule>دِنَا يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡفُرۡقَانِ يَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ۡتَقَى <rule class=ham_wasl>ٱ</rule>لۡجَمۡعَانِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٤١',
    41, 10, 2, 182, 150, 73, 'false'
  );
  
  -- Ayah 42 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1202,
    'إِذۡ أَنتُم بِٱلۡعُدۡوَةِ ٱلدُّنۡیَا وَهُم بِٱلۡعُدۡوَةِ ٱلۡقُصۡوَىٰ وَٱلرَّكۡبُ أَسۡفَلَ مِنكُمۡۚ وَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِی ٱلۡمِیعَـٰدِ وَلَـٰكِن لِّیَقۡضِیَ ٱللَّهُ أَمۡرࣰا كَانَ مَفۡعُولࣰا لِّیَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَیِّنَةࣲ وَیَحۡیَىٰ مَنۡ حَیَّ عَنۢ بَیِّنَةࣲۗ وَإِنَّ ٱللَّهَ لَسَمِیعٌ عَلِیمٌ',
    'اذ انتم بالعدوة الدنيا وهم بالعدوة القصوى والركب اسفل منكم ولو تواعدتم لاختلفتم في الميعاد ولكن ليقضي الله امرا كان مفعولا ليهلك من هلك عن بينة ويحيى من حي عن بينة وان الله لسميع عليم',
    'إِذۡ أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعُ<rule class=qalaqah>دۡ</rule>وَةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعُ<rule class=qalaqah>دۡ</rule>وَةِ <rule class=ham_wasl>ٱ</rule>لۡقُصۡوَىٰ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّكۡبُ أَسۡفَلَ مِ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ وَلَوۡ تَوَاعَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ لَ<rule class=ham_wasl>ٱ</rule>خۡتَلَفۡتُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡمِيعَ<rule class=madda_normal>ـٰ</rule>دِ‌ۙ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَ<rule class=qalaqah>قۡ</rule>ضِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَمۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َانَ مَفۡعُول<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَهۡلِكَ مَنۡ هَلَكَ ع<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َيَحۡيَىٰ مَنۡ حَىَّ ع<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=idgham_ghunnah>ةٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَسَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٤٢',
    42, 10, 2, 182, 150, 73, 'false'
  );
  
  -- Ayah 43 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1203,
    'إِذۡ یُرِیكَهُمُ ٱللَّهُ فِی مَنَامِكَ قَلِیلࣰاۖ وَلَوۡ أَرَىٰكَهُمۡ كَثِیرࣰا لَّفَشِلۡتُمۡ وَلَتَنَـٰزَعۡتُمۡ فِی ٱلۡأَمۡرِ وَلَـٰكِنَّ ٱللَّهَ سَلَّمَۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'اذ يريكهم الله في منامك قليلا ولو اراكهم كثيرا لفشلتم ولتنازعتم في الامر ولكن الله سلم انه عليم بذات الصدور',
    'إِذۡ يُرِيكَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى مَنَامِكَ قَلِيل<rule class=idgham_ghunnah>اً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ أَرَ<rule class=madda_normal>ٮٰ</rule>كَهُمۡ كَثِي<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّفَشِلۡتُمۡ وَلَتَنَ<rule class=madda_normal>ـٰ</rule>زَعۡتُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَلَّمَ‌ۗ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٤٣',
    43, 10, 2, 182, 150, 73, 'false'
  );
  
  -- Ayah 44 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1204,
    'وَإِذۡ یُرِیكُمُوهُمۡ إِذِ ٱلۡتَقَیۡتُمۡ فِیۤ أَعۡیُنِكُمۡ قَلِیلࣰا وَیُقَلِّلُكُمۡ فِیۤ أَعۡیُنِهِمۡ لِیَقۡضِیَ ٱللَّهُ أَمۡرࣰا كَانَ مَفۡعُولࣰاۗ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ',
    'واذ يريكموهم اذ التقيتم في اعينكم قليلا ويقللكم في اعينهم ليقضي الله امرا كان مفعولا والى الله ترجع الامور',
    'وَإِذۡ يُرِيكُمُوهُمۡ إِذِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ۡتَقَيۡتُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡيُنِكُمۡ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َيُقَلِّلُكُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡيُنِهِمۡ لِيَ<rule class=qalaqah>قۡ</rule>ضِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَمۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َانَ مَفۡعُول<rule class=idgham_ghunnah>اً‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تُرۡجَعُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رُ ٤٤',
    44, 10, 2, 182, 150, 73, 'false'
  );
  
  -- Ayah 45 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1205,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا لَقِیتُمۡ فِئَةࣰ فَٱثۡبُتُوا۟ وَٱذۡكُرُوا۟ ٱللَّهَ كَثِیرࣰا لَّعَلَّكُمۡ تُفۡلِحُونَ',
    'يا ايها الذين امنوا اذا لقيتم فئة فاثبتوا واذكروا الله كثيرا لعلكم تفلحون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا لَقِيتُمۡ فِئَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>ثۡبُتُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ كَثِي<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 10, 2, 182, 151, 73, 'false'
  );
  
  -- Ayah 46 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1206,
    'وَأَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَـٰزَعُوا۟ فَتَفۡشَلُوا۟ وَتَذۡهَبَ رِیحُكُمۡۖ وَٱصۡبِرُوۤا۟ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِینَ',
    'واطيعوا الله ورسوله ولا تنازعوا فتفشلوا وتذهب ريحكم واصبروا ان الله مع الصابرين',
    'وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> وَلَا تَنَ<rule class=madda_normal>ـٰ</rule>زَعُو<rule class=slnt>اۡ</rule> فَتَفۡشَلُو<rule class=slnt>اۡ</rule> وَتَذۡهَبَ رِيحُكُمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>صۡبِر<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 10, 2, 183, 151, 73, 'false'
  );
  
  -- Ayah 47 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1207,
    'وَلَا تَكُونُوا۟ كَٱلَّذِینَ خَرَجُوا۟ مِن دِیَـٰرِهِم بَطَرࣰا وَرِئَاۤءَ ٱلنَّاسِ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِۚ وَٱللَّهُ بِمَا یَعۡمَلُونَ مُحِیطࣱ',
    'ولا تكونوا كالذين خرجوا من ديارهم بطرا ورئاء الناس ويصدون عن سبيل الله والله بما يعملون محيط',
    'وَلَا تَكُونُو<rule class=slnt>اۡ</rule> كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ خَرَجُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>َطَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َرِئ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَيَصُدُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا يَعۡمَلُونَ مُح<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ط</rule>ٌ ٤٧',
    47, 10, 2, 183, 151, 73, 'false'
  );
  
  -- Ayah 48 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1208,
    'وَإِذۡ زَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡیَوۡمَ مِنَ ٱلنَّاسِ وَإِنِّی جَارࣱ لَّكُمۡۖ فَلَمَّا تَرَاۤءَتِ ٱلۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَیۡهِ وَقَالَ إِنِّی بَرِیۤءࣱ مِّنكُمۡ إِنِّیۤ أَرَىٰ مَا لَا تَرَوۡنَ إِنِّیۤ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِیدُ ٱلۡعِقَابِ',
    'واذ زين لهم الشيطان اعمالهم وقال لا غالب لكم اليوم من الناس واني جار لكم فلما تراءت الفئتان نكص على عقبيه وقال اني بريء منكم اني ارى ما لا ترون اني اخاف الله والله شديد العقاب',
    'وَإِذۡ زَيَّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَإِ<rule class=ghunnah>نّ</rule>ِى جَا<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا تَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتِ <rule class=ham_wasl>ٱ</rule>لۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيۡهِ وَقَالَ إِ<rule class=ghunnah>نّ</rule>ِى بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَىٰ مَا لَا تَرَوۡنَ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٤٨',
    48, 10, 2, 183, 151, 73, 'false'
  );
  
  -- Ayah 49 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1209,
    'إِذۡ یَقُولُ ٱلۡمُنَـٰفِقُونَ وَٱلَّذِینَ فِی قُلُوبِهِم مَّرَضٌ غَرَّ هَـٰۤؤُلَاۤءِ دِینُهُمۡۗ وَمَن یَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ',
    'اذ يقول المنافقون والذين في قلوبهم مرض غر هؤلاء دينهم ومن يتوكل على الله فان الله عزيز حكيم',
    'إِذۡ يَقُولُ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقُونَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَضٌ غَرَّ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ دِينُهُمۡ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٤٩',
    49, 10, 2, 183, 152, 73, 'false'
  );
  
  -- Ayah 50 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1210,
    'وَلَوۡ تَرَىٰۤ إِذۡ یَتَوَفَّى ٱلَّذِینَ كَفَرُوا۟ ٱلۡمَلَـٰۤىِٕكَةُ یَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَـٰرَهُمۡ وَذُوقُوا۟ عَذَابَ ٱلۡحَرِیقِ',
    'ولو ترى اذ يتوفى الذين كفروا الملائكة يضربون وجوههم وادبارهم وذوقوا عذاب الحريق',
    'وَلَوۡ تَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذۡ يَتَوَفَّى <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ‌ۙ</rule> <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رَهُمۡ وَذُوقُو<rule class=slnt>اۡ</rule> عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡحَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ِ ٥٠',
    50, 10, 2, 183, 152, 73, 'false'
  );
  
  -- Ayah 51 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1211,
    'ذَ ٰ⁠لِكَ بِمَا قَدَّمَتۡ أَیۡدِیكُمۡ وَأَنَّ ٱللَّهَ لَیۡسَ بِظَلَّـٰمࣲ لِّلۡعَبِیدِ',
    'ذلك بما قدمت ايديكم وان الله ليس بظلام للعبيد',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَيۡسَ بِظَلَّ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَب<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٥١',
    51, 10, 2, 183, 152, 73, 'false'
  );
  
  -- Ayah 52 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1212,
    'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۚ إِنَّ ٱللَّهَ قَوِیࣱّ شَدِیدُ ٱلۡعِقَابِ',
    'كداب ال فرعون والذين من قبلهم كفروا بايات الله فاخذهم الله بذنوبهم ان الله قوي شديد العقاب',
    'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ‌ۙ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ كَفَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَأَخَذَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِذُنُوبِهِمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَوِ<rule class=ikhafa>ىٌّ</rule> <rule class=ikhafa>ش</rule>َدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٥٢',
    52, 10, 2, 183, 152, 73, 'false'
  );
  
  -- Ayah 53 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1213,
    'ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ لَمۡ یَكُ مُغَیِّرࣰا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ یُغَیِّرُوا۟ مَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ',
    'ذلك بان الله لم يك مغيرا نعمة انعمها على قوم حتى يغيروا ما بانفسهم وان الله سميع عليم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَمۡ يَكُ مُغَيِّ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>ن</rule>ِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُو<rule class=slnt>اۡ</rule> مَا بِأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۙ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٥٣',
    53, 10, 2, 184, 152, 73, 'false'
  );
  
  -- Ayah 54 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1214,
    'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَذَّبُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ فَأَهۡلَكۡنَـٰهُم بِذُنُوبِهِمۡ وَأَغۡرَقۡنَاۤ ءَالَ فِرۡعَوۡنَۚ وَكُلࣱّ كَانُوا۟ ظَـٰلِمِینَ',
    'كداب ال فرعون والذين من قبلهم كذبوا بايات ربهم فاهلكناهم بذنوبهم واغرقنا ال فرعون وكل كانوا ظالمين',
    'كَدَأۡبِ ءَالِ فِرۡعَوۡنَ‌ۙ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ فَأَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذُنُوبِهِمۡ وَأَغۡرَ<rule class=qalaqah>قۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> ءَالَ فِرۡعَوۡنَ‌ۚ وَكُ<rule class=ikhafa>لٌّ</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥٤',
    54, 10, 2, 184, 152, 73, 'false'
  );
  
  -- Ayah 55 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1215,
    'إِنَّ شَرَّ ٱلدَّوَاۤبِّ عِندَ ٱللَّهِ ٱلَّذِینَ كَفَرُوا۟ فَهُمۡ لَا یُؤۡمِنُونَ',
    'ان شر الدواب عند الله الذين كفروا فهم لا يؤمنون',
    'إِ<rule class=ghunnah>نّ</rule>َ شَرَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّو<rule class=madda_necessary>َا</rule>ٓبِّ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فَهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 10, 2, 184, 152, 73, 'false'
  );
  
  -- Ayah 56 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1216,
    'ٱلَّذِینَ عَـٰهَدتَّ مِنۡهُمۡ ثُمَّ یَنقُضُونَ عَهۡدَهُمۡ فِی كُلِّ مَرَّةࣲ وَهُمۡ لَا یَتَّقُونَ',
    'الذين عاهدت منهم ثم ينقضون عهدهم في كل مرة وهم لا يتقون',
    'ٱلَّذِينَ عَ<rule class=madda_normal>ـٰ</rule>هَ<rule class=idgham_mutajanisayn>د</rule>تَّ مِنۡهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يَ<rule class=ikhafa>نق</rule>ُضُونَ عَهۡدَهُمۡ فِى كُلِّ مَرَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَتَّق<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 10, 2, 184, 152, 73, 'false'
  );
  
  -- Ayah 57 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1217,
    'فَإِمَّا تَثۡقَفَنَّهُمۡ فِی ٱلۡحَرۡبِ فَشَرِّدۡ بِهِم مَّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ یَذَّكَّرُونَ',
    'فاما تثقفنهم في الحرب فشرد بهم من خلفهم لعلهم يذكرون',
    'فَإِ<rule class=ghunnah>مّ</rule>َا تَثۡقَفَ<rule class=ghunnah>نّ</rule>َهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡحَرۡبِ فَشَرِّ<rule class=qalaqah>دۡ</rule> بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ يَذَّكَّر<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 10, 2, 184, 152, 73, 'false'
  );
  
  -- Ayah 58 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1218,
    'وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِیَانَةࣰ فَٱنۢبِذۡ إِلَیۡهِمۡ عَلَىٰ سَوَاۤءٍۚ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡخَاۤىِٕنِینَ',
    'واما تخافن من قوم خيانة فانبذ اليهم على سواء ان الله لا يحب الخائنين',
    'وَإِ<rule class=ghunnah>مّ</rule>َا تَخَافَ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمٍ خِيَانَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=iqlab>نۢب</rule>ِذۡ إِلَيۡهِمۡ عَلَىٰ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡخ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِن<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 10, 2, 184, 152, 73, 'false'
  );
  
  -- Ayah 59 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1219,
    'وَلَا یَحۡسَبَنَّ ٱلَّذِینَ كَفَرُوا۟ سَبَقُوۤا۟ۚ إِنَّهُمۡ لَا یُعۡجِزُونَ',
    'ولا يحسبن الذين كفروا سبقوا انهم لا يعجزون',
    'وَلَا يَحۡسَبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> سَبَق<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَا يُعۡجِز<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 10, 2, 184, 153, 73, 'false'
  );
  
  -- Ayah 60 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1220,
    'وَأَعِدُّوا۟ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةࣲ وَمِن رِّبَاطِ ٱلۡخَیۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِینَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ یَعۡلَمُهُمۡۚ وَمَا تُنفِقُوا۟ مِن شَیۡءࣲ فِی سَبِیلِ ٱللَّهِ یُوَفَّ إِلَیۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ',
    'واعدوا لهم ما استطعتم من قوة ومن رباط الخيل ترهبون به عدو الله وعدوكم واخرين من دونهم لا تعلمونهم الله يعلمهم وما تنفقوا من شيء في سبيل الله يوف اليكم وانتم لا تظلمون',
    'وَأَعِدُّو<rule class=slnt>اۡ</rule> لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا <rule class=ham_wasl>ٱ</rule>سۡتَطَعۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُوَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّبَاطِ <rule class=ham_wasl>ٱ</rule>لۡخَيۡلِ تُرۡهِبُونَ بِه<rule class=madda_normal>ِۦ</rule> عَدُوَّ <rule class=ham_wasl>ٱ</rule>للَّهِ وَعَدُوَّكُمۡ وَءَاخَرِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِهِمۡ لَا تَعۡلَمُونَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُهُمۡ‌ۚ وَمَا تُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>ِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ يُوَفَّ إِلَيۡكُمۡ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 10, 2, 184, 153, 73, 'false'
  );
  
  -- Ayah 61 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1221,
    '۞ وَإِن جَنَحُوا۟ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'وان جنحوا للسلم فاجنح لها وتوكل على الله انه هو السميع العليم',
    '۞وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َنَحُو<rule class=slnt>اۡ</rule> لِلسَّلۡمِ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>نَحۡ لَهَا وَتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٦١',
    61, 10, 2, 184, 153, 74, 'false'
  );
  
  -- Ayah 62 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1222,
    'وَإِن یُرِیدُوۤا۟ أَن یَخۡدَعُوكَ فَإِنَّ حَسۡبَكَ ٱللَّهُۚ هُوَ ٱلَّذِیۤ أَیَّدَكَ بِنَصۡرِهِۦ وَبِٱلۡمُؤۡمِنِینَ',
    'وان يريدوا ان يخدعوك فان حسبك الله هو الذي ايدك بنصره وبالمؤمنين',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡدَعُوكَ فَإِ<rule class=ghunnah>نّ</rule>َ حَسۡبَكَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَيَّدَكَ بِنَصۡرِه<rule class=madda_normal>ِۦ</rule> وَبِ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٦٢',
    62, 10, 2, 185, 153, 74, 'false'
  );
  
  -- Ayah 63 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1223,
    'وَأَلَّفَ بَیۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِی ٱلۡأَرۡضِ جَمِیعࣰا مَّاۤ أَلَّفۡتَ بَیۡنَ قُلُوبِهِمۡ وَلَـٰكِنَّ ٱللَّهَ أَلَّفَ بَیۡنَهُمۡۚ إِنَّهُۥ عَزِیزٌ حَكِیمࣱ',
    'والف بين قلوبهم لو انفقت ما في الارض جميعا ما الفت بين قلوبهم ولكن الله الف بينهم انه عزيز حكيم',
    'وَأَلَّفَ بَيۡنَ قُلُوبِهِمۡ‌ۚ لَوۡ أَ<rule class=ikhafa>نف</rule>َ<rule class=qalaqah>قۡ</rule>تَ مَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ أَلَّفَ بَيۡنَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٦٣',
    63, 10, 2, 185, 153, 74, 'false'
  );
  
  -- Ayah 64 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1224,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ حَسۡبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِینَ',
    'يا ايها النبي حسبك الله ومن اتبعك من المؤمنين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ حَسۡبُكَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَمَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٦٤',
    64, 10, 2, 185, 153, 74, 'false'
  );
  
  -- Ayah 65 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1225,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ حَرِّضِ ٱلۡمُؤۡمِنِینَ عَلَى ٱلۡقِتَالِۚ إِن یَكُن مِّنكُمۡ عِشۡرُونَ صَـٰبِرُونَ یَغۡلِبُوا۟ مِا۟ئَتَیۡنِۚ وَإِن یَكُن مِّنكُم مِّا۟ئَةࣱ یَغۡلِبُوۤا۟ أَلۡفࣰا مِّنَ ٱلَّذِینَ كَفَرُوا۟ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَفۡقَهُونَ',
    'يا ايها النبي حرض المؤمنين على القتال ان يكن منكم عشرون صابرون يغلبوا مائتين وان يكن منكم مائة يغلبوا الفا من الذين كفروا بانهم قوم لا يفقهون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ حَرِّضِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡقِتَالِ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ عِشۡرُونَ صَ<rule class=madda_normal>ـٰ</rule>بِرُونَ يَغۡلِبُو<rule class=slnt>اۡ</rule> مِ<rule class=slnt>اۡ</rule>ئَتَيۡنِ‌ۚ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=slnt>اۡ</rule>ئَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َغۡلِب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَلۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَفۡقَه<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 10, 2, 185, 154, 74, 'false'
  );
  
  -- Ayah 66 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1226,
    'ٱلۡـَٔـٰنَ خَفَّفَ ٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِیكُمۡ ضَعۡفࣰاۚ فَإِن یَكُن مِّنكُم مِّا۟ئَةࣱ صَابِرَةࣱ یَغۡلِبُوا۟ مِا۟ئَتَیۡنِۚ وَإِن یَكُن مِّنكُمۡ أَلۡفࣱ یَغۡلِبُوۤا۟ أَلۡفَیۡنِ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِینَ',
    'الان خفف الله عنكم وعلم ان فيكم ضعفا فان يكن منكم مائة صابرة يغلبوا مائتين وان يكن منكم الف يغلبوا الفين باذن الله والله مع الصابرين',
    'ٱلۡـَٔ<rule class=madda_normal>ـٰ</rule>نَ خَفَّفَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَ<rule class=ikhafa>نك</rule>ُمۡ وَعَلِمَ أَ<rule class=ghunnah>نّ</rule>َ فِيكُمۡ ضَعۡ<rule class=ikhafa>فًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=slnt>اۡ</rule>ئَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ص</rule>َابِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َغۡلِبُو<rule class=slnt>اۡ</rule> مِ<rule class=slnt>اۡ</rule>ئَتَيۡنِ‌ۚ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ أَلۡ<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>ي</rule>َغۡلِب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَلۡفَيۡنِ بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 10, 2, 185, 154, 74, 'false'
  );
  
  -- Ayah 67 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1227,
    'مَا كَانَ لِنَبِیٍّ أَن یَكُونَ لَهُۥۤ أَسۡرَىٰ حَتَّىٰ یُثۡخِنَ فِی ٱلۡأَرۡضِۚ تُرِیدُونَ عَرَضَ ٱلدُّنۡیَا وَٱللَّهُ یُرِیدُ ٱلۡـَٔاخِرَةَۗ وَٱللَّهُ عَزِیزٌ حَكِیمࣱ',
    'ما كان لنبي ان يكون له اسرى حتى يثخن في الارض تريدون عرض الدنيا والله يريد الاخرة والله عزيز حكيم',
    'مَا كَانَ لِنَبِىٍّ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَسۡرَىٰ حَتَّىٰ يُثۡخِنَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ تُرِيدُونَ عَرَضَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُرِيدُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٦٧',
    67, 10, 2, 185, 154, 74, 'false'
  );
  
  -- Ayah 68 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1228,
    'لَّوۡلَا كِتَـٰبࣱ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِیمَاۤ أَخَذۡتُمۡ عَذَابٌ عَظِیمࣱ',
    'لولا كتاب من الله سبق لمسكم فيما اخذتم عذاب عظيم',
    'لَّوۡلَا كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ سَبَقَ لَمَسَّكُمۡ فِيم<rule class=madda_obligatory_monfasel>َآ</rule> أَخَذۡتُمۡ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٦٨',
    68, 10, 2, 185, 154, 74, 'false'
  );
  
  -- Ayah 69 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1229,
    'فَكُلُوا۟ مِمَّا غَنِمۡتُمۡ حَلَـٰلࣰا طَیِّبࣰاۚ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'فكلوا مما غنمتم حلالا طيبا واتقوا الله ان الله غفور رحيم',
    'فَكُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا غَنِمۡتُمۡ حَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ط</rule>َيِّ<rule class=idgham_ghunnah>بًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٦٩',
    69, 10, 2, 185, 154, 74, 'false'
  );
  
  -- Ayah 70 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1230,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ قُل لِّمَن فِیۤ أَیۡدِیكُم مِّنَ ٱلۡأَسۡرَىٰۤ إِن یَعۡلَمِ ٱللَّهُ فِی قُلُوبِكُمۡ خَیۡرࣰا یُؤۡتِكُمۡ خَیۡرࣰا مِّمَّاۤ أُخِذَ مِنكُمۡ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'يا ايها النبي قل لمن في ايديكم من الاسرى ان يعلم الله في قلوبكم خيرا يؤتكم خيرا مما اخذ منكم ويغفر لكم والله غفور رحيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ قُل لِّمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَيۡدِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَسۡرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَمِ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى قُلُوبِكُمۡ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡتِكُمۡ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أُخِذَ مِ<rule class=ikhafa>نك</rule>ُمۡ وَيَغۡفِرۡ لَكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٧٠',
    70, 10, 2, 186, 155, 74, 'false'
  );
  
  -- Ayah 71 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1231,
    'وَإِن یُرِیدُوا۟ خِیَانَتَكَ فَقَدۡ خَانُوا۟ ٱللَّهَ مِن قَبۡلُ فَأَمۡكَنَ مِنۡهُمۡۗ وَٱللَّهُ عَلِیمٌ حَكِیمٌ',
    'وان يريدوا خيانتك فقد خانوا الله من قبل فامكن منهم والله عليم حكيم',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيدُو<rule class=slnt>اۡ</rule> خِيَانَتَكَ فَقَ<rule class=qalaqah>دۡ</rule> خَانُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ فَأَمۡكَنَ مِنۡهُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٧١',
    71, 10, 2, 186, 155, 74, 'false'
  );
  
  -- Ayah 72 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1232,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ بِأَمۡوَ ٰ⁠لِهِمۡ وَأَنفُسِهِمۡ فِی سَبِیلِ ٱللَّهِ وَٱلَّذِینَ ءَاوَوا۟ وَّنَصَرُوۤا۟ أُو۟لَـٰۤىِٕكَ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضࣲۚ وَٱلَّذِینَ ءَامَنُوا۟ وَلَمۡ یُهَاجِرُوا۟ مَا لَكُم مِّن وَلَـٰیَتِهِم مِّن شَیۡءٍ حَتَّىٰ یُهَاجِرُوا۟ۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِی ٱلدِّینِ فَعَلَیۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَیۡنَكُمۡ وَبَیۡنَهُم مِّیثَـٰقࣱۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ',
    'ان الذين امنوا وهاجروا وجاهدوا باموالهم وانفسهم في سبيل الله والذين اووا ونصروا اولئك بعضهم اولياء بعض والذين امنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا وان استنصروكم في الدين فعليكم النصر الا على قوم بينكم وبينهم ميثاق والله بما تعملون بصير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَهَاجَرُو<rule class=slnt>اۡ</rule> وَجَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> بِأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَاوَو<rule class=slnt>اۡ</rule> وَّنَصَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ بَعۡضُهُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَلَمۡ يُهَاجِرُو<rule class=slnt>اۡ</rule> مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>يَتِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ حَتَّىٰ يُهَاجِرُو<rule class=slnt>اۡ‌ۚ</rule> وَإِنِ <rule class=ham_wasl>ٱ</rule>سۡتَ<rule class=ikhafa>نص</rule>َرُوكُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ فَعَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصۡرُ إِلَّا عَلَىٰ قَوۡ<rule class=iqlab>مِۭ</rule> <rule class=iqlab>ب</rule>َيۡنَكُمۡ وَبَيۡنَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>قٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٧٢',
    72, 10, 2, 186, 155, 74, 'false'
  );
  
  -- Ayah 73 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1233,
    'وَٱلَّذِینَ كَفَرُوا۟ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةࣱ فِی ٱلۡأَرۡضِ وَفَسَادࣱ كَبِیرࣱ',
    'والذين كفروا بعضهم اولياء بعض الا تفعلوه تكن فتنة في الارض وفساد كبير',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بَعۡضُهُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بَعۡضٍ‌ۚ إِلَّا تَفۡعَلُوهُ تَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِتۡنَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَفَسَا<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ك</rule>َب<rule class=madda_permissible>ِي</rule>رٌ ٧٣',
    73, 10, 2, 186, 155, 74, 'false'
  );
  
  -- Ayah 74 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1234,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِی سَبِیلِ ٱللَّهِ وَٱلَّذِینَ ءَاوَوا۟ وَّنَصَرُوۤا۟ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقࣰّاۚ لَّهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ',
    'والذين امنوا وهاجروا وجاهدوا في سبيل الله والذين اووا ونصروا اولئك هم المؤمنون حقا لهم مغفرة ورزق كريم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَهَاجَرُو<rule class=slnt>اۡ</rule> وَجَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَاوَو<rule class=slnt>اۡ</rule> وَّنَصَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ حَق<rule class=idgham_wo_ghunnah>ًّا‌ۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َرِزۡ<rule class=ikhafa>قٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٧٤',
    74, 10, 2, 186, 155, 74, 'false'
  );
  
  -- Ayah 75 Surah Al-Anfaal
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    8,
    1235,
    'وَٱلَّذِینَ ءَامَنُوا۟ مِنۢ بَعۡدُ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ مَعَكُمۡ فَأُو۟لَـٰۤىِٕكَ مِنكُمۡۚ وَأُو۟لُوا۟ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضࣲ فِی كِتَـٰبِ ٱللَّهِۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمُۢ',
    'والذين امنوا من بعد وهاجروا وجاهدوا معكم فاولئك منكم واولو الارحام بعضهم اولى ببعض في كتاب الله ان الله بكل شيء عليم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدُ وَهَاجَرُو<rule class=slnt>اۡ</rule> وَجَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> مَعَكُمۡ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مِ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ وَأُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ف</rule>ِى كِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مُۢ ٧٥',
    75, 10, 2, 186, 155, 74, 'false'
  );
  

-- Surah At-Tawba
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (9, 'سُورَةُ التَّوۡبَةِ', 'At-Tawba', 'The Repentance', 'Medinan', 129);

  -- Ayah 1 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1236,
    'بَرَاۤءَةࣱ مِّنَ ٱللَّهِ وَرَسُولِهِۦۤ إِلَى ٱلَّذِینَ عَـٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِینَ',
    'براءة من الله ورسوله الى الذين عاهدتم من المشركين',
    'بَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ عَ<rule class=madda_normal>ـٰ</rule>هَ<rule class=idgham_mutajanisayn>د</rule>تّ<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١',
    1, 10, 2, 187, 156, 75, 'false'
  );
  
  -- Ayah 2 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1237,
    'فَسِیحُوا۟ فِی ٱلۡأَرۡضِ أَرۡبَعَةَ أَشۡهُرࣲ وَٱعۡلَمُوۤا۟ أَنَّكُمۡ غَیۡرُ مُعۡجِزِی ٱللَّهِ وَأَنَّ ٱللَّهَ مُخۡزِی ٱلۡكَـٰفِرِینَ',
    'فسيحوا في الارض اربعة اشهر واعلموا انكم غير معجزي الله وان الله مخزي الكافرين',
    'فَسِيحُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَرۡبَعَةَ أَشۡهُ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َكُمۡ غَيۡرُ مُعۡجِزِى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۙ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡزِى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 10, 2, 187, 156, 75, 'false'
  );
  
  -- Ayah 3 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1238,
    'وَأَذَ ٰ⁠نࣱ مِّنَ ٱللَّهِ وَرَسُولِهِۦۤ إِلَى ٱلنَّاسِ یَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِیۤءࣱ مِّنَ ٱلۡمُشۡرِكِینَ وَرَسُولُهُۥۚ فَإِن تُبۡتُمۡ فَهُوَ خَیۡرࣱ لَّكُمۡۖ وَإِن تَوَلَّیۡتُمۡ فَٱعۡلَمُوۤا۟ أَنَّكُمۡ غَیۡرُ مُعۡجِزِی ٱللَّهِۗ وَبَشِّرِ ٱلَّذِینَ كَفَرُوا۟ بِعَذَابٍ أَلِیمٍ',
    'واذان من الله ورسوله الى الناس يوم الحج الاكبر ان الله بريء من المشركين ورسوله فان تبتم فهو خير لكم وان توليتم فاعلموا انكم غير معجزي الله وبشر الذين كفروا بعذاب اليم',
    'وَأَذ<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡحَجِّ <rule class=ham_wasl>ٱ</rule>لۡأَكۡبَرِ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ‌ۙ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule>‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>بۡ</rule>تُمۡ فَهُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّيۡتُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َكُمۡ غَيۡرُ مُعۡجِزِى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِعَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٣',
    3, 10, 2, 187, 156, 75, 'false'
  );
  
  -- Ayah 4 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1239,
    'إِلَّا ٱلَّذِینَ عَـٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِینَ ثُمَّ لَمۡ یَنقُصُوكُمۡ شَیۡـࣰٔا وَلَمۡ یُظَـٰهِرُوا۟ عَلَیۡكُمۡ أَحَدࣰا فَأَتِمُّوۤا۟ إِلَیۡهِمۡ عَهۡدَهُمۡ إِلَىٰ مُدَّتِهِمۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُتَّقِینَ',
    'الا الذين عاهدتم من المشركين ثم لم ينقصوكم شيئا ولم يظاهروا عليكم احدا فاتموا اليهم عهدهم الى مدتهم ان الله يحب المتقين',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ عَ<rule class=madda_normal>ـٰ</rule>هَ<rule class=idgham_mutajanisayn>د</rule>تّ<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ ثُ<rule class=ghunnah>مّ</rule>َ لَمۡ يَ<rule class=ikhafa>نق</rule>ُصُوكُمۡ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ يُظَ<rule class=madda_normal>ـٰ</rule>هِرُو<rule class=slnt>اۡ</rule> عَلَيۡكُمۡ أَحَ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َأَتِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِمۡ عَهۡدَهُمۡ إِلَىٰ مُدَّتِهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٤',
    4, 10, 2, 187, 156, 75, 'false'
  );
  
  -- Ayah 5 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1240,
    'فَإِذَا ٱنسَلَخَ ٱلۡأَشۡهُرُ ٱلۡحُرُمُ فَٱقۡتُلُوا۟ ٱلۡمُشۡرِكِینَ حَیۡثُ وَجَدتُّمُوهُمۡ وَخُذُوهُمۡ وَٱحۡصُرُوهُمۡ وَٱقۡعُدُوا۟ لَهُمۡ كُلَّ مَرۡصَدࣲۚ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِیلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'فاذا انسلخ الاشهر الحرم فاقتلوا المشركين حيث وجدتموهم وخذوهم واحصروهم واقعدوا لهم كل مرصد فان تابوا واقاموا الصلاة واتوا الزكاة فخلوا سبيلهم ان الله غفور رحيم',
    'فَإِذَا <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نس</rule>َلَخَ <rule class=ham_wasl>ٱ</rule>لۡأَشۡهُرُ <rule class=ham_wasl>ٱ</rule>لۡحُرُمُ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ حَيۡثُ وَجَ<rule class=idgham_mutajanisayn>د</rule>تُّمُوهُمۡ وَخُذُوهُمۡ وَ<rule class=ham_wasl>ٱ</rule>حۡصُرُوهُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>عُدُو<rule class=slnt>اۡ</rule> لَهُمۡ كُلَّ مَرۡصَ<rule class=ikhafa>دٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابُو<rule class=slnt>اۡ</rule> وَأَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ فَخَلُّو<rule class=slnt>اۡ</rule> سَبِيلَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٥',
    5, 10, 2, 187, 156, 75, 'false'
  );
  
  -- Ayah 6 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1241,
    'وَإِنۡ أَحَدࣱ مِّنَ ٱلۡمُشۡرِكِینَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ یَسۡمَعَ كَلَـٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَعۡلَمُونَ',
    'وان احد من المشركين استجارك فاجره حتى يسمع كلام الله ثم ابلغه مامنه ذلك بانهم قوم لا يعلمون',
    'وَإِنۡ أَحَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ <rule class=ham_wasl>ٱ</rule>سۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَ<rule class=madda_normal>ـٰ</rule>مَ <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=qalaqah>بۡ</rule>لِغۡهُ مَأۡمَنَهُ<rule class=madda_normal>ۥ</rule>‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 10, 2, 187, 156, 75, 'false'
  );
  
  -- Ayah 7 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1242,
    'كَیۡفَ یَكُونُ لِلۡمُشۡرِكِینَ عَهۡدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦۤ إِلَّا ٱلَّذِینَ عَـٰهَدتُّمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ فَمَا ٱسۡتَقَـٰمُوا۟ لَكُمۡ فَٱسۡتَقِیمُوا۟ لَهُمۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُتَّقِینَ',
    'كيف يكون للمشركين عهد عند الله وعند رسوله الا الذين عاهدتم عند المسجد الحرام فما استقاموا لكم فاستقيموا لهم ان الله يحب المتقين',
    'كَيۡفَ يَكُونُ لِلۡمُشۡرِكِينَ عَهۡدٌ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَعِ<rule class=ikhafa>ند</rule>َ رَسُولِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ عَ<rule class=madda_normal>ـٰ</rule>هَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ‌ۖ فَمَا <rule class=ham_wasl>ٱ</rule>سۡتَقَ<rule class=madda_normal>ـٰ</rule>مُو<rule class=slnt>اۡ</rule> لَكُمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَقِيمُو<rule class=slnt>اۡ</rule> لَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 10, 2, 188, 157, 75, 'false'
  );
  
  -- Ayah 8 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1243,
    'كَیۡفَ وَإِن یَظۡهَرُوا۟ عَلَیۡكُمۡ لَا یَرۡقُبُوا۟ فِیكُمۡ إِلࣰّا وَلَا ذِمَّةࣰۚ یُرۡضُونَكُم بِأَفۡوَ ٰ⁠هِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ فَـٰسِقُونَ',
    'كيف وان يظهروا عليكم لا يرقبوا فيكم الا ولا ذمة يرضونكم بافواههم وتابى قلوبهم واكثرهم فاسقون',
    'كَيۡفَ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َظۡهَرُو<rule class=slnt>اۡ</rule> عَلَيۡكُمۡ لَا يَرۡقُبُو<rule class=slnt>اۡ</rule> فِيكُمۡ إِل<rule class=idgham_ghunnah>اًّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا ذِ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>ُرۡضُونَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ فَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 10, 2, 188, 157, 75, 'false'
  );
  
  -- Ayah 9 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1244,
    'ٱشۡتَرَوۡا۟ بِـَٔایَـٰتِ ٱللَّهِ ثَمَنࣰا قَلِیلࣰا فَصَدُّوا۟ عَن سَبِیلِهِۦۤۚ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'اشتروا بايات الله ثمنا قليلا فصدوا عن سبيله انهم ساء ما كانوا يعملون',
    'ٱشۡتَرَوۡ<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>َصَدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 10, 2, 188, 157, 75, 'false'
  );
  
  -- Ayah 10 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1245,
    'لَا یَرۡقُبُونَ فِی مُؤۡمِنٍ إِلࣰّا وَلَا ذِمَّةࣰۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُعۡتَدُونَ',
    'لا يرقبون في مؤمن الا ولا ذمة واولئك هم المعتدون',
    'لَا يَرۡقُبُونَ فِى مُؤۡمِنٍ إِل<rule class=idgham_ghunnah>اًّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا ذِ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُعۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 10, 2, 188, 157, 75, 'false'
  );
  
  -- Ayah 11 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1246,
    'فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخۡوَ ٰ⁠نُكُمۡ فِی ٱلدِّینِۗ وَنُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡلَمُونَ',
    'فان تابوا واقاموا الصلاة واتوا الزكاة فاخوانكم في الدين ونفصل الايات لقوم يعلمون',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابُو<rule class=slnt>اۡ</rule> وَأَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ فَإِخۡو<rule class=madda_normal>ٰ</rule>نُكُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ‌ۗ وَنُفَصِّلُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 10, 2, 188, 157, 75, 'false'
  );
  
  -- Ayah 12 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1247,
    'وَإِن نَّكَثُوۤا۟ أَیۡمَـٰنَهُم مِّنۢ بَعۡدِ عَهۡدِهِمۡ وَطَعَنُوا۟ فِی دِینِكُمۡ فَقَـٰتِلُوۤا۟ أَىِٕمَّةَ ٱلۡكُفۡرِ إِنَّهُمۡ لَاۤ أَیۡمَـٰنَ لَهُمۡ لَعَلَّهُمۡ یَنتَهُونَ',
    'وان نكثوا ايمانهم من بعد عهدهم وطعنوا في دينكم فقاتلوا ائمة الكفر انهم لا ايمان لهم لعلهم ينتهون',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّكَث<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ عَهۡدِهِمۡ وَطَعَنُو<rule class=slnt>اۡ</rule> فِى دِينِكُمۡ فَقَ<rule class=madda_normal>ـٰ</rule>تِل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَئِ<rule class=ghunnah>مّ</rule>َةَ <rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ‌ۙ إِ<rule class=ghunnah>نّ</rule>َهُمۡ ل<rule class=madda_obligatory_monfasel>َآ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ لَهُمۡ لَعَلَّهُمۡ يَ<rule class=ikhafa>نت</rule>َه<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 10, 2, 188, 157, 75, 'false'
  );
  
  -- Ayah 13 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1248,
    'أَلَا تُقَـٰتِلُونَ قَوۡمࣰا نَّكَثُوۤا۟ أَیۡمَـٰنَهُمۡ وَهَمُّوا۟ بِإِخۡرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمۡ أَوَّلَ مَرَّةٍۚ أَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِینَ',
    'الا تقاتلون قوما نكثوا ايمانهم وهموا باخراج الرسول وهم بدءوكم اول مرة اتخشونهم فالله احق ان تخشوه ان كنتم مؤمنين',
    'أَلَا تُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَ قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>ن</rule>َّكَث<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نَهُمۡ وَهَ<rule class=ghunnah>مّ</rule>ُو<rule class=slnt>اۡ</rule> بِإِخۡرَاجِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َدَءُوكُمۡ أَوَّلَ مَرَّةٍ‌ۚ أَتَخۡشَوۡنَهُمۡ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَحَقُّ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َخۡشَوۡهُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 10, 2, 188, 157, 75, 'false'
  );
  
  -- Ayah 14 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1249,
    'قَـٰتِلُوهُمۡ یُعَذِّبۡهُمُ ٱللَّهُ بِأَیۡدِیكُمۡ وَیُخۡزِهِمۡ وَیَنصُرۡكُمۡ عَلَیۡهِمۡ وَیَشۡفِ صُدُورَ قَوۡمࣲ مُّؤۡمِنِینَ',
    'قاتلوهم يعذبهم الله بايديكم ويخزهم وينصركم عليهم ويشف صدور قوم مؤمنين',
    'قَ<rule class=madda_normal>ـٰ</rule>تِلُوهُمۡ يُعَذِّ<rule class=qalaqah>بۡ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِأَيۡدِيكُمۡ وَيُخۡزِهِمۡ وَيَ<rule class=ikhafa>نص</rule>ُرۡكُمۡ عَلَيۡهِمۡ وَيَشۡفِ صُدُورَ قَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٤',
    14, 10, 2, 189, 157, 75, 'false'
  );
  
  -- Ayah 15 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1250,
    'وَیُذۡهِبۡ غَیۡظَ قُلُوبِهِمۡۗ وَیَتُوبُ ٱللَّهُ عَلَىٰ مَن یَشَاۤءُۗ وَٱللَّهُ عَلِیمٌ حَكِیمٌ',
    'ويذهب غيظ قلوبهم ويتوب الله على من يشاء والله عليم حكيم',
    'وَيُذۡهِ<rule class=qalaqah>بۡ</rule> غَيۡظَ قُلُوبِهِمۡ‌ۗ وَيَتُوبُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ١٥',
    15, 10, 2, 189, 157, 75, 'false'
  );
  
  -- Ayah 16 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1251,
    'أَمۡ حَسِبۡتُمۡ أَن تُتۡرَكُوا۟ وَلَمَّا یَعۡلَمِ ٱللَّهُ ٱلَّذِینَ جَـٰهَدُوا۟ مِنكُمۡ وَلَمۡ یَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلۡمُؤۡمِنِینَ وَلِیجَةࣰۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ',
    'ام حسبتم ان تتركوا ولما يعلم الله الذين جاهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المؤمنين وليجة والله خبير بما تعملون',
    'أَمۡ حَسِ<rule class=qalaqah>بۡ</rule>تُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُتۡرَكُو<rule class=slnt>اۡ</rule> وَلَ<rule class=ghunnah>مّ</rule>َا يَعۡلَمِ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ جَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ وَلَمۡ يَتَّخِذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا رَسُولِه<rule class=madda_normal>ِۦ</rule> وَلَا <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَلِيجَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 10, 2, 189, 157, 75, 'false'
  );
  
  -- Ayah 17 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1252,
    'مَا كَانَ لِلۡمُشۡرِكِینَ أَن یَعۡمُرُوا۟ مَسَـٰجِدَ ٱللَّهِ شَـٰهِدِینَ عَلَىٰۤ أَنفُسِهِم بِٱلۡكُفۡرِۚ أُو۟لَـٰۤىِٕكَ حَبِطَتۡ أَعۡمَـٰلُهُمۡ وَفِی ٱلنَّارِ هُمۡ خَـٰلِدُونَ',
    'ما كان للمشركين ان يعمروا مساجد الله شاهدين على انفسهم بالكفر اولئك حبطت اعمالهم وفي النار هم خالدون',
    'مَا كَانَ لِلۡمُشۡرِكِينَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمُرُو<rule class=slnt>اۡ</rule> مَسَ<rule class=madda_normal>ـٰ</rule>جِدَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَ<rule class=madda_normal>ـٰ</rule>هِدِينَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ حَبِطَتۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ وَفِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ هُمۡ خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 10, 2, 189, 158, 75, 'false'
  );
  
  -- Ayah 18 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1253,
    'إِنَّمَا یَعۡمُرُ مَسَـٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ یَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰۤ أُو۟لَـٰۤىِٕكَ أَن یَكُونُوا۟ مِنَ ٱلۡمُهۡتَدِینَ',
    'انما يعمر مساجد الله من امن بالله واليوم الاخر واقام الصلاة واتى الزكاة ولم يخش الا الله فعسى اولئك ان يكونوا من المهتدين',
    'إِ<rule class=ghunnah>نّ</rule>َمَا يَعۡمُرُ مَسَ<rule class=madda_normal>ـٰ</rule>جِدَ <rule class=ham_wasl>ٱ</rule>للَّهِ مَنۡ ءَامَنَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَأَقَامَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَلَمۡ يَخۡشَ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ فَعَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ١٨',
    18, 10, 2, 189, 158, 75, 'false'
  );
  
  -- Ayah 19 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1254,
    '۞ أَجَعَلۡتُمۡ سِقَایَةَ ٱلۡحَاۤجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَجَـٰهَدَ فِی سَبِیلِ ٱللَّهِۚ لَا یَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'اجعلتم سقاية الحاج وعمارة المسجد الحرام كمن امن بالله واليوم الاخر وجاهد في سبيل الله لا يستوون عند الله والله لا يهدي القوم الظالمين',
    '۞أَجَعَلۡتُمۡ سِقَايَةَ <rule class=ham_wasl>ٱ</rule>لۡح<rule class=madda_necessary>َا</rule>ٓجِّ وَعِمَارَةَ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ كَمَنۡ ءَامَنَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَجَ<rule class=madda_normal>ـٰ</rule>هَدَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ لَا يَسۡتَوُ<rule class=madda_normal>ۥ</rule>نَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٩',
    19, 10, 2, 189, 158, 76, 'false'
  );
  
  -- Ayah 20 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1255,
    'ٱلَّذِینَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِی سَبِیلِ ٱللَّهِ بِأَمۡوَ ٰ⁠لِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَاۤىِٕزُونَ',
    'الذين امنوا وهاجروا وجاهدوا في سبيل الله باموالهم وانفسهم اعظم درجة عند الله واولئك هم الفائزون',
    'ٱلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَهَاجَرُو<rule class=slnt>اۡ</rule> وَجَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ أَعۡظَمُ دَرَجَةً عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡف<rule class=madda_obligatory_mottasel>َا</rule>ٓئِز<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 10, 2, 189, 158, 76, 'false'
  );
  
  -- Ayah 21 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1256,
    'یُبَشِّرُهُمۡ رَبُّهُم بِرَحۡمَةࣲ مِّنۡهُ وَرِضۡوَ ٰ⁠نࣲ وَجَنَّـٰتࣲ لَّهُمۡ فِیهَا نَعِیمࣱ مُّقِیمٌ',
    'يبشرهم ربهم برحمة منه ورضوان وجنات لهم فيها نعيم مقيم',
    'يُبَشِّرُهُمۡ رَبُّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ وَرِضۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َجَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ فِيهَا نَعِي<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّق<rule class=madda_permissible>ِي</rule>مٌ ٢١',
    21, 10, 2, 190, 158, 76, 'false'
  );
  
  -- Ayah 22 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1257,
    'خَـٰلِدِینَ فِیهَاۤ أَبَدًاۚ إِنَّ ٱللَّهَ عِندَهُۥۤ أَجۡرٌ عَظِیمࣱ',
    'خالدين فيها ابدا ان الله عنده اجر عظيم',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَدًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=qalaqah>جۡ</rule>رٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٢٢',
    22, 10, 2, 190, 158, 76, 'false'
  );
  
  -- Ayah 23 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1258,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوۤا۟ ءَابَاۤءَكُمۡ وَإِخۡوَ ٰ⁠نَكُمۡ أَوۡلِیَاۤءَ إِنِ ٱسۡتَحَبُّوا۟ ٱلۡكُفۡرَ عَلَى ٱلۡإِیمَـٰنِۚ وَمَن یَتَوَلَّهُم مِّنكُمۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ',
    'يا ايها الذين امنوا لا تتخذوا اباءكم واخوانكم اولياء ان استحبوا الكفر على الايمان ومن يتولهم منكم فاولئك هم الظالمون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَتَّخِذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ وَإِخۡو<rule class=madda_normal>ٰ</rule>نَكُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِنِ <rule class=ham_wasl>ٱ</rule>سۡتَحَبُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكُفۡرَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَلَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 10, 2, 190, 158, 76, 'false'
  );
  
  -- Ayah 24 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1259,
    'قُلۡ إِن كَانَ ءَابَاۤؤُكُمۡ وَأَبۡنَاۤؤُكُمۡ وَإِخۡوَ ٰ⁠نُكُمۡ وَأَزۡوَ ٰ⁠جُكُمۡ وَعَشِیرَتُكُمۡ وَأَمۡوَ ٰ⁠لٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَـٰرَةࣱ تَخۡشَوۡنَ كَسَادَهَا وَمَسَـٰكِنُ تَرۡضَوۡنَهَاۤ أَحَبَّ إِلَیۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادࣲ فِی سَبِیلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ یَأۡتِیَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ',
    'قل ان كان اباؤكم وابناؤكم واخوانكم وازواجكم وعشيرتكم واموال اقترفتموها وتجارة تخشون كسادها ومساكن ترضونها احب اليكم من الله ورسوله وجهاد في سبيله فتربصوا حتى ياتي الله بامره والله لا يهدي القوم الفاسقين',
    'قُلۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ وَأَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ وَإِخۡو<rule class=madda_normal>ٰ</rule>نُكُمۡ وَأَزۡو<rule class=madda_normal>ٰ</rule>جُكُمۡ وَعَشِيرَتُكُمۡ وَأَمۡو<rule class=madda_normal>ٰ</rule>لٌ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تَرَفۡتُمُوهَا وَتِجَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>َخۡشَوۡنَ كَسَادَهَا وَمَسَ<rule class=madda_normal>ـٰ</rule>كِنُ تَرۡضَوۡنَه<rule class=madda_obligatory_monfasel>َآ</rule> أَحَبَّ إِلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَجِهَا<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>ِى سَبِيلِه<rule class=madda_normal>ِۦ</rule> فَتَرَبَّصُو<rule class=slnt>اۡ</rule> حَتَّىٰ يَأۡتِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِأَمۡرِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 10, 2, 190, 158, 76, 'false'
  );
  
  -- Ayah 25 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1260,
    'لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِی مَوَاطِنَ كَثِیرَةࣲ وَیَوۡمَ حُنَیۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَیۡـࣰٔا وَضَاقَتۡ عَلَیۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّیۡتُم مُّدۡبِرِینَ',
    'لقد نصركم الله في مواطن كثيرة ويوم حنين اذ اعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الارض بما رحبت ثم وليتم مدبرين',
    'لَقَ<rule class=qalaqah>دۡ</rule> نَصَرَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى مَوَاطِنَ كَثِيرَ<rule class=idgham_ghunnah>ةٍ‌ۙ</rule> <rule class=idgham_ghunnah>و</rule>َيَوۡمَ حُنَيۡنٍ‌ۙ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَ<rule class=ikhafa>نك</rule>ُمۡ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َضَاقَتۡ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ بِمَا رَحُبَتۡ ثُ<rule class=ghunnah>مّ</rule>َ وَلَّيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>دۡ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 10, 2, 190, 159, 76, 'false'
  );
  
  -- Ayah 26 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1261,
    'ثُمَّ أَنزَلَ ٱللَّهُ سَكِینَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِینَ وَأَنزَلَ جُنُودࣰا لَّمۡ تَرَوۡهَا وَعَذَّبَ ٱلَّذِینَ كَفَرُوا۟ۚ وَذَ ٰ⁠لِكَ جَزَاۤءُ ٱلۡكَـٰفِرِینَ',
    'ثم انزل الله سكينته على رسوله وعلى المؤمنين وانزل جنودا لم تروها وعذب الذين كفروا وذلك جزاء الكافرين',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ سَكِينَتَهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ رَسُولِه<rule class=madda_normal>ِۦ</rule> وَعَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَأَ<rule class=ikhafa>نز</rule>َلَ جُنُو<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَرَوۡهَا وَعَذَّبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ‌ۚ</rule> وَذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٢٦',
    26, 10, 2, 190, 159, 76, 'false'
  );
  
  -- Ayah 27 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1262,
    'ثُمَّ یَتُوبُ ٱللَّهُ مِنۢ بَعۡدِ ذَ ٰ⁠لِكَ عَلَىٰ مَن یَشَاۤءُۗ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'ثم يتوب الله من بعد ذلك على من يشاء والله غفور رحيم',
    'ثُ<rule class=ghunnah>مّ</rule>َ يَتُوبُ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَىٰ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٢٧',
    27, 10, 2, 191, 159, 76, 'false'
  );
  
  -- Ayah 28 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1263,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسࣱ فَلَا یَقۡرَبُوا۟ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَـٰذَاۚ وَإِنۡ خِفۡتُمۡ عَیۡلَةࣰ فَسَوۡفَ یُغۡنِیكُمُ ٱللَّهُ مِن فَضۡلِهِۦۤ إِن شَاۤءَۚ إِنَّ ٱللَّهَ عَلِیمٌ حَكِیمࣱ',
    'يا ايها الذين امنوا انما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا وان خفتم عيلة فسوف يغنيكم الله من فضله ان شاء ان الله عليم حكيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكُونَ نَجَ<rule class=ikhafa>سٌ</rule> <rule class=ikhafa>ف</rule>َلَا يَ<rule class=qalaqah>قۡ</rule>رَبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدَ <rule class=ham_wasl>ٱ</rule>لۡحَرَامَ بَعۡدَ عَامِهِمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۚ وَإِنۡ خِفۡتُمۡ عَيۡلَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َسَوۡفَ يُغۡنِيكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٢٨',
    28, 10, 2, 191, 159, 76, 'false'
  );
  
  -- Ayah 29 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1264,
    'قَـٰتِلُوا۟ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَلَا یُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا یَدِینُونَ دِینَ ٱلۡحَقِّ مِنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ حَتَّىٰ یُعۡطُوا۟ ٱلۡجِزۡیَةَ عَن یَدࣲ وَهُمۡ صَـٰغِرُونَ',
    'قاتلوا الذين لا يؤمنون بالله ولا باليوم الاخر ولا يحرمون ما حرم الله ورسوله ولا يدينون دين الحق من الذين اوتوا الكتاب حتى يعطوا الجزية عن يد وهم صاغرون',
    'قَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا بِ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَلَا يُحَرِّمُونَ مَا حَرَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule> وَلَا يَدِينُونَ دِينَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ حَتَّىٰ يُعۡطُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡجِزۡيَةَ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ صَ<rule class=madda_normal>ـٰ</rule>غِر<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 10, 2, 191, 159, 76, 'false'
  );
  
  -- Ayah 30 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1265,
    'وَقَالَتِ ٱلۡیَهُودُ عُزَیۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَـٰرَى ٱلۡمَسِیحُ ٱبۡنُ ٱللَّهِۖ ذَ ٰ⁠لِكَ قَوۡلُهُم بِأَفۡوَ ٰ⁠هِهِمۡۖ یُضَـٰهِـُٔونَ قَوۡلَ ٱلَّذِینَ كَفَرُوا۟ مِن قَبۡلُۚ قَـٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ یُؤۡفَكُونَ',
    'وقالت اليهود عزير ابن الله وقالت النصارى المسيح ابن الله ذلك قولهم بافواههم يضاهئون قول الذين كفروا من قبل قاتلهم الله انى يؤفكون',
    'وَقَالَتِ <rule class=ham_wasl>ٱ</rule>لۡيَهُودُ عُزَيۡرٌ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَقَالَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَى <rule class=ham_wasl>ٱ</rule>لۡمَسِيحُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ ذ<rule class=madda_normal>ٰ</rule>لِكَ قَوۡلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ‌ۖ يُضَ<rule class=madda_normal>ـٰ</rule>هِــُٔونَ قَوۡلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۚ قَ<rule class=madda_normal>ـٰ</rule>تَلَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ أَ<rule class=ghunnah>نّ</rule>َىٰ يُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 10, 2, 191, 160, 76, 'false'
  );
  
  -- Ayah 31 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1266,
    'ٱتَّخَذُوۤا۟ أَحۡبَارَهُمۡ وَرُهۡبَـٰنَهُمۡ أَرۡبَابࣰا مِّن دُونِ ٱللَّهِ وَٱلۡمَسِیحَ ٱبۡنَ مَرۡیَمَ وَمَاۤ أُمِرُوۤا۟ إِلَّا لِیَعۡبُدُوۤا۟ إِلَـٰهࣰا وَ ٰ⁠حِدࣰاۖ لَّاۤ إِلَـٰهَ إِلَّا هُوَۚ سُبۡحَـٰنَهُۥ عَمَّا یُشۡرِكُونَ',
    'اتخذوا احبارهم ورهبانهم اربابا من دون الله والمسيح ابن مريم وما امروا الا ليعبدوا الها واحدا لا اله الا هو سبحانه عما يشركون',
    'ٱتَّخَذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَحۡبَارَهُمۡ وَرُهۡبَ<rule class=madda_normal>ـٰ</rule>نَهُمۡ أَرۡبَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسِيحَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُمِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا لِيَعۡبُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_wo_ghunnah>دًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۚ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 10, 2, 191, 160, 76, 'false'
  );
  
  -- Ayah 32 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1267,
    'یُرِیدُونَ أَن یُطۡفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفۡوَ ٰ⁠هِهِمۡ وَیَأۡبَى ٱللَّهُ إِلَّاۤ أَن یُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَـٰفِرُونَ',
    'يريدون ان يطفئوا نور الله بافواههم ويابى الله الا ان يتم نوره ولو كره الكافرون',
    'يُرِيدُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>طۡ</rule>فِــُٔو<rule class=slnt>اۡ</rule> نُورَ <rule class=ham_wasl>ٱ</rule>للَّهِ بِأَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ وَيَأۡبَى <rule class=ham_wasl>ٱ</rule>للَّهُ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُتِ<rule class=ghunnah>مّ</rule>َ نُورَهُ<rule class=madda_normal>ۥ</rule> وَلَوۡ كَرِهَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 10, 2, 192, 160, 76, 'false'
  );
  
  -- Ayah 33 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1268,
    'هُوَ ٱلَّذِیۤ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِینِ ٱلۡحَقِّ لِیُظۡهِرَهُۥ عَلَى ٱلدِّینِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ',
    'هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡسَلَ رَسُولَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَدِينِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ لِيُظۡهِرَهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ كُلِّه<rule class=madda_normal>ِۦ</rule> وَلَوۡ كَرِهَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 10, 2, 192, 160, 76, 'false'
  );
  
  -- Ayah 34 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1269,
    '۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ كَثِیرࣰا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَیَأۡكُلُونَ أَمۡوَ ٰ⁠لَ ٱلنَّاسِ بِٱلۡبَـٰطِلِ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِۗ وَٱلَّذِینَ یَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا یُنفِقُونَهَا فِی سَبِیلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِیمࣲ',
    'يا ايها الذين امنوا ان كثيرا من الاحبار والرهبان لياكلون اموال الناس بالباطل ويصدون عن سبيل الله والذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله فبشرهم بعذاب اليم',
    '۞يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡبَارِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّهۡبَانِ لَيَأۡكُلُونَ أَمۡو<rule class=madda_normal>ٰ</rule>لَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ وَيَصُدُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَكۡنِزُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذَّهَبَ وَ<rule class=ham_wasl>ٱ</rule>لۡفِضَّةَ وَلَا يُ<rule class=ikhafa>نف</rule>ِقُونَهَا فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَبَشِّرۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِعَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٣٤',
    34, 10, 2, 192, 160, 77, 'false'
  );
  
  -- Ayah 35 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1270,
    'یَوۡمَ یُحۡمَىٰ عَلَیۡهَا فِی نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَـٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُوا۟ مَا كُنتُمۡ تَكۡنِزُونَ',
    'يوم يحمى عليها في نار جهنم فتكوى بها جباههم وجنوبهم وظهورهم هذا ما كنزتم لانفسكم فذوقوا ما كنتم تكنزون',
    'يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِى نَارِ جَهَ<rule class=ghunnah>نّ</rule>َمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡ‌ۖ هَ<rule class=madda_normal>ـٰ</rule>ذَا مَا كَنَزۡتُمۡ لِأَ<rule class=ikhafa>نف</rule>ُسِكُمۡ فَذُوقُو<rule class=slnt>اۡ</rule> مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡنِز<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 10, 2, 192, 160, 77, 'false'
  );
  
  -- Ayah 36 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1271,
    'إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرࣰا فِی كِتَـٰبِ ٱللَّهِ یَوۡمَ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ مِنۡهَاۤ أَرۡبَعَةٌ حُرُمࣱۚ ذَ ٰ⁠لِكَ ٱلدِّینُ ٱلۡقَیِّمُۚ فَلَا تَظۡلِمُوا۟ فِیهِنَّ أَنفُسَكُمۡۚ وَقَـٰتِلُوا۟ ٱلۡمُشۡرِكِینَ كَاۤفَّةࣰ كَمَا یُقَـٰتِلُونَكُمۡ كَاۤفَّةࣰۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِینَ',
    'ان عدة الشهور عند الله اثنا عشر شهرا في كتاب الله يوم خلق السماوات والارض منها اربعة حرم ذلك الدين القيم فلا تظلموا فيهن انفسكم وقاتلوا المشركين كافة كما يقاتلونكم كافة واعلموا ان الله مع المتقين',
    'إِ<rule class=ghunnah>نّ</rule>َ عِدَّةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّهُورِ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>ثۡنَا عَشَرَ شَهۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>ِى كِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>للَّهِ يَوۡمَ خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ مِنۡه<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡبَعَةٌ حُرُ<rule class=ikhafa>مٌ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينُ <rule class=ham_wasl>ٱ</rule>لۡقَيِّمُ‌ۚ فَلَا تَظۡلِمُو<rule class=slnt>اۡ</rule> فِيهِ<rule class=ghunnah>نّ</rule>َ أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ‌ۚ وَقَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ ك<rule class=madda_necessary>َا</rule>ٓفَّ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ك</rule>َمَا يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَكُمۡ ك<rule class=madda_necessary>َا</rule>ٓفَّ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَعَ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 10, 2, 192, 160, 77, 'false'
  );
  
  -- Ayah 37 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1272,
    'إِنَّمَا ٱلنَّسِیۤءُ زِیَادَةࣱ فِی ٱلۡكُفۡرِۖ یُضَلُّ بِهِ ٱلَّذِینَ كَفَرُوا۟ یُحِلُّونَهُۥ عَامࣰا وَیُحَرِّمُونَهُۥ عَامࣰا لِّیُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَیُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُۚ زُیِّنَ لَهُمۡ سُوۤءُ أَعۡمَـٰلِهِمۡۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡكَـٰفِرِینَ',
    'انما النسيء زيادة في الكفر يضل به الذين كفروا يحلونه عاما ويحرمونه عاما ليواطئوا عدة ما حرم الله فيحلوا ما حرم الله زين لهم سوء اعمالهم والله لا يهدي القوم الكافرين',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َس<rule class=madda_obligatory_mottasel>ِى</rule>ٓءُ زِيَادَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ‌ۖ يُضَلُّ بِهِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> يُحِلُّونَهُ<rule class=madda_normal>ۥ</rule> عَا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َيُحَرِّمُونَهُ<rule class=madda_normal>ۥ</rule> عَا<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُوَاطِــُٔو<rule class=slnt>اۡ</rule> عِدَّةَ مَا حَرَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ فَيُحِلُّو<rule class=slnt>اۡ</rule> مَا حَرَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ زُيِّنَ لَهُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لِهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 10, 2, 193, 160, 77, 'false'
  );
  
  -- Ayah 38 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1273,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ مَا لَكُمۡ إِذَا قِیلَ لَكُمُ ٱنفِرُوا۟ فِی سَبِیلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِیتُم بِٱلۡحَیَوٰةِ ٱلدُّنۡیَا مِنَ ٱلۡـَٔاخِرَةِۚ فَمَا مَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا فِی ٱلۡـَٔاخِرَةِ إِلَّا قَلِیلٌ',
    'يا ايها الذين امنوا ما لكم اذا قيل لكم انفروا في سبيل الله اثاقلتم الى الارض ارضيتم بالحياة الدنيا من الاخرة فما متاع الحياة الدنيا في الاخرة الا قليل',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَا لَكُمۡ إِذَا قِيلَ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>ِرُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>ثَّاقَلۡتُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ أَرَضِيت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۚ فَمَا مَتَ<rule class=madda_normal>ـٰ</rule>عُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ إِلَّا قَل<rule class=madda_permissible>ِي</rule>لٌ ٣٨',
    38, 10, 2, 193, 161, 77, 'false'
  );
  
  -- Ayah 39 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1274,
    'إِلَّا تَنفِرُوا۟ یُعَذِّبۡكُمۡ عَذَابًا أَلِیمࣰا وَیَسۡتَبۡدِلۡ قَوۡمًا غَیۡرَكُمۡ وَلَا تَضُرُّوهُ شَیۡـࣰٔاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'الا تنفروا يعذبكم عذابا اليما ويستبدل قوما غيركم ولا تضروه شيئا والله على كل شيء قدير',
    'إِلَّا تَ<rule class=ikhafa>نف</rule>ِرُو<rule class=slnt>اۡ</rule> يُعَذِّ<rule class=qalaqah>بۡ</rule>كُمۡ عَذَابًا أَلِي<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َيَسۡتَ<rule class=qalaqah>بۡ</rule>دِلۡ قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّوهُ شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٣٩',
    39, 10, 2, 193, 161, 77, 'false'
  );
  
  -- Ayah 40 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1275,
    'إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِینَ كَفَرُوا۟ ثَانِیَ ٱثۡنَیۡنِ إِذۡ هُمَا فِی ٱلۡغَارِ إِذۡ یَقُولُ لِصَـٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِینَتَهُۥ عَلَیۡهِ وَأَیَّدَهُۥ بِجُنُودࣲ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِینَ كَفَرُوا۟ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِیَ ٱلۡعُلۡیَاۗ وَٱللَّهُ عَزِیزٌ حَكِیمٌ',
    'الا تنصروه فقد نصره الله اذ اخرجه الذين كفروا ثاني اثنين اذ هما في الغار اذ يقول لصاحبه لا تحزن ان الله معنا فانزل الله سكينته عليه وايده بجنود لم تروها وجعل كلمة الذين كفروا السفلى وكلمة الله هي العليا والله عزيز حكيم',
    'إِلَّا تَ<rule class=ikhafa>نص</rule>ُرُوهُ فَقَ<rule class=qalaqah>دۡ</rule> نَصَرَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ إِذۡ أَخۡرَجَهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> ثَانِىَ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ إِذۡ هُمَا فِى <rule class=ham_wasl>ٱ</rule>لۡغَارِ إِذۡ يَقُولُ لِصَ<rule class=madda_normal>ـٰ</rule>حِبِه<rule class=madda_normal>ِۦ</rule> لَا تَحۡزَنۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَعَنَا‌ۖ فَأَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ سَكِينَتَهُ<rule class=madda_normal>ۥ</rule> عَلَيۡهِ وَأَيَّدَهُ<rule class=madda_normal>ۥ</rule> بِجُنُو<rule class=idgham_wo_ghunnah>دٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّفۡلَىٰ‌ۗ وَكَلِمَةُ <rule class=ham_wasl>ٱ</rule>للَّهِ هِىَ <rule class=ham_wasl>ٱ</rule>لۡعُلۡيَا‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٤٠',
    40, 10, 2, 193, 161, 77, 'false'
  );
  
  -- Ayah 41 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1276,
    'ٱنفِرُوا۟ خِفَافࣰا وَثِقَالࣰا وَجَـٰهِدُوا۟ بِأَمۡوَ ٰ⁠لِكُمۡ وَأَنفُسِكُمۡ فِی سَبِیلِ ٱللَّهِۚ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ',
    'انفروا خفافا وثقالا وجاهدوا باموالكم وانفسكم في سبيل الله ذلكم خير لكم ان كنتم تعلمون',
    'ٱ<rule class=ikhafa>نف</rule>ِرُو<rule class=slnt>اۡ</rule> خِفَا<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َثِقَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َجَ<rule class=madda_normal>ـٰ</rule>هِدُو<rule class=slnt>اۡ</rule> بِأَمۡو<rule class=madda_normal>ٰ</rule>لِكُمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِكُمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 10, 2, 194, 161, 77, 'false'
  );
  
  -- Ayah 42 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1277,
    'لَوۡ كَانَ عَرَضࣰا قَرِیبࣰا وَسَفَرࣰا قَاصِدࣰا لَّٱتَّبَعُوكَ وَلَـٰكِنۢ بَعُدَتۡ عَلَیۡهِمُ ٱلشُّقَّةُۚ وَسَیَحۡلِفُونَ بِٱللَّهِ لَوِ ٱسۡتَطَعۡنَا لَخَرَجۡنَا مَعَكُمۡ یُهۡلِكُونَ أَنفُسَهُمۡ وَٱللَّهُ یَعۡلَمُ إِنَّهُمۡ لَكَـٰذِبُونَ',
    'لو كان عرضا قريبا وسفرا قاصدا لاتبعوك ولكن بعدت عليهم الشقة وسيحلفون بالله لو استطعنا لخرجنا معكم يهلكون انفسهم والله يعلم انهم لكاذبون',
    'لَوۡ كَانَ عَرَ<rule class=ikhafa>ضًا</rule> <rule class=ikhafa>ق</rule>َرِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َسَفَ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ق</rule>َاصِ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ham_wasl>ٱ</rule>تَّبَعُوكَ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعُدَتۡ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّقَّةُ‌ۚ وَسَيَحۡلِفُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ لَوِ <rule class=ham_wasl>ٱ</rule>سۡتَطَعۡنَا لَخَرَ<rule class=qalaqah>جۡ</rule>نَا مَعَكُمۡ يُهۡلِكُونَ أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 10, 2, 194, 161, 77, 'false'
  );
  
  -- Ayah 43 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1278,
    'عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ یَتَبَیَّنَ لَكَ ٱلَّذِینَ صَدَقُوا۟ وَتَعۡلَمَ ٱلۡكَـٰذِبِینَ',
    'عفا الله عنك لم اذنت لهم حتى يتبين لك الذين صدقوا وتعلم الكاذبين',
    'عَفَا <rule class=ham_wasl>ٱ</rule>للَّهُ عَ<rule class=ikhafa>نك</rule>َ لِمَ أَذِ<rule class=ikhafa>نت</rule>َ لَهُمۡ حَتَّىٰ يَتَبَيَّنَ لَكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ صَدَقُو<rule class=slnt>اۡ</rule> وَتَعۡلَمَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٤٣',
    43, 10, 2, 194, 162, 77, 'false'
  );
  
  -- Ayah 44 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1279,
    'لَا یَسۡتَـٔۡذِنُكَ ٱلَّذِینَ یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ أَن یُجَـٰهِدُوا۟ بِأَمۡوَ ٰ⁠لِهِمۡ وَأَنفُسِهِمۡۗ وَٱللَّهُ عَلِیمُۢ بِٱلۡمُتَّقِینَ',
    'لا يستاذنك الذين يؤمنون بالله واليوم الاخر ان يجاهدوا باموالهم وانفسهم والله عليم بالمتقين',
    'لَا يَسۡتَــٔۡذِنُكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجَ<rule class=madda_normal>ـٰ</rule>هِدُو<rule class=slnt>اۡ</rule> بِأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٤٤',
    44, 10, 2, 194, 162, 77, 'false'
  );
  
  -- Ayah 45 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1280,
    'إِنَّمَا یَسۡتَـٔۡذِنُكَ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَٱرۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ فِی رَیۡبِهِمۡ یَتَرَدَّدُونَ',
    'انما يستاذنك الذين لا يؤمنون بالله واليوم الاخر وارتابت قلوبهم فهم في ريبهم يترددون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا يَسۡتَــٔۡذِنُكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَ<rule class=ham_wasl>ٱ</rule>رۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ فِى رَيۡبِهِمۡ يَتَرَدَّد<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 10, 2, 194, 162, 77, 'false'
  );
  
  -- Ayah 46 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1281,
    '۞ وَلَوۡ أَرَادُوا۟ ٱلۡخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةࣰ وَلَـٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِیلَ ٱقۡعُدُوا۟ مَعَ ٱلۡقَـٰعِدِینَ',
    'ولو ارادوا الخروج لاعدوا له عدة ولكن كره الله انبعاثهم فثبطهم وقيل اقعدوا مع القاعدين',
    '۞وَلَوۡ أَرَادُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخُرُوجَ لَأَعَدُّو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> عُدَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َرِهَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=iqlab>نۢب</rule>ِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِيلَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>عُدُو<rule class=slnt>اۡ</rule> مَعَ <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>عِد<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 10, 2, 194, 162, 78, 'false'
  );
  
  -- Ayah 47 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1282,
    'لَوۡ خَرَجُوا۟ فِیكُم مَّا زَادُوكُمۡ إِلَّا خَبَالࣰا وَلَأَوۡضَعُوا۟ خِلَـٰلَكُمۡ یَبۡغُونَكُمُ ٱلۡفِتۡنَةَ وَفِیكُمۡ سَمَّـٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ',
    'لو خرجوا فيكم ما زادوكم الا خبالا ولاوضعوا خلالكم يبغونكم الفتنة وفيكم سماعون لهم والله عليم بالظالمين',
    'لَوۡ خَرَجُو<rule class=slnt>اۡ</rule> فِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا زَادُوكُمۡ إِلَّا خَبَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َلَأَوۡضَعُو<rule class=slnt>اۡ</rule> خِلَ<rule class=madda_normal>ـٰ</rule>لَكُمۡ يَ<rule class=qalaqah>بۡ</rule>غُونَكُمُ <rule class=ham_wasl>ٱ</rule>لۡفِتۡنَةَ وَفِيكُمۡ سَ<rule class=ghunnah>مّ</rule>َ<rule class=madda_normal>ـٰ</rule>عُونَ لَهُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 10, 2, 194, 162, 78, 'false'
  );
  
  -- Ayah 48 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1283,
    'لَقَدِ ٱبۡتَغَوُا۟ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُوا۟ لَكَ ٱلۡأُمُورَ حَتَّىٰ جَاۤءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَـٰرِهُونَ',
    'لقد ابتغوا الفتنة من قبل وقلبوا لك الامور حتى جاء الحق وظهر امر الله وهم كارهون',
    'لَقَدِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡفِتۡنَةَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَقَلَّبُو<rule class=slnt>اۡ</rule> لَكَ <rule class=ham_wasl>ٱ</rule>لۡأُمُورَ حَتَّىٰ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَظَهَرَ أَمۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَهُمۡ كَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 10, 2, 195, 162, 78, 'false'
  );
  
  -- Ayah 49 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1284,
    'وَمِنۡهُم مَّن یَقُولُ ٱئۡذَن لِّی وَلَا تَفۡتِنِّیۤۚ أَلَا فِی ٱلۡفِتۡنَةِ سَقَطُوا۟ۗ وَإِنَّ جَهَنَّمَ لَمُحِیطَةُۢ بِٱلۡكَـٰفِرِینَ',
    'ومنهم من يقول ائذن لي ولا تفتني الا في الفتنة سقطوا وان جهنم لمحيطة بالكافرين',
    'وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُ <rule class=ham_wasl>ٱ</rule>ئۡذ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّى وَلَا تَفۡتِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> أَلَا فِى <rule class=ham_wasl>ٱ</rule>لۡفِتۡنَةِ سَقَطُو<rule class=slnt>اۡ‌ۗ</rule> وَإِ<rule class=ghunnah>نّ</rule>َ جَهَ<rule class=ghunnah>نّ</rule>َمَ لَمُحِيطَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٤٩',
    49, 10, 2, 195, 162, 78, 'false'
  );
  
  -- Ayah 50 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1285,
    'إِن تُصِبۡكَ حَسَنَةࣱ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ مُصِیبَةࣱ یَقُولُوا۟ قَدۡ أَخَذۡنَاۤ أَمۡرَنَا مِن قَبۡلُ وَیَتَوَلَّوا۟ وَّهُمۡ فَرِحُونَ',
    'ان تصبك حسنة تسؤهم وان تصبك مصيبة يقولوا قد اخذنا امرنا من قبل ويتولوا وهم فرحون',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِ<rule class=qalaqah>بۡ</rule>كَ حَسَنَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>َسُؤۡهُمۡ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِ<rule class=qalaqah>بۡ</rule>كَ مُصِيبَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُو<rule class=slnt>اۡ</rule> قَ<rule class=qalaqah>دۡ</rule> أَخَذۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡرَنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَيَتَوَلَّو<rule class=slnt>اۡ</rule> وَّهُمۡ فَرِح<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 10, 2, 195, 162, 78, 'false'
  );
  
  -- Ayah 51 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1286,
    'قُل لَّن یُصِیبَنَاۤ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ',
    'قل لن يصيبنا الا ما كتب الله لنا هو مولانا وعلى الله فليتوكل المؤمنون',
    'قُل لّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُصِيبَن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا مَا كَتَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَنَا هُوَ مَوۡلَ<rule class=madda_normal>ـٰ</rule>نَا‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 10, 2, 195, 162, 78, 'false'
  );
  
  -- Ayah 52 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1287,
    'قُلۡ هَلۡ تَرَبَّصُونَ بِنَاۤ إِلَّاۤ إِحۡدَى ٱلۡحُسۡنَیَیۡنِۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أَن یُصِیبَكُمُ ٱللَّهُ بِعَذَابࣲ مِّنۡ عِندِهِۦۤ أَوۡ بِأَیۡدِینَاۖ فَتَرَبَّصُوۤا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ',
    'قل هل تربصون بنا الا احدى الحسنيين ونحن نتربص بكم ان يصيبكم الله بعذاب من عنده او بايدينا فتربصوا انا معكم متربصون',
    'قُلۡ هَلۡ تَرَبَّصُونَ بِن<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِحۡدَى <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَيَيۡنِ‌ۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُصِيبَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِعَذَا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡ بِأَيۡدِينَا‌ۖ فَتَرَبَّص<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا مَعَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّتَرَبِّص<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 10, 2, 195, 162, 78, 'false'
  );
  
  -- Ayah 53 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1288,
    'قُلۡ أَنفِقُوا۟ طَوۡعًا أَوۡ كَرۡهࣰا لَّن یُتَقَبَّلَ مِنكُمۡ إِنَّكُمۡ كُنتُمۡ قَوۡمࣰا فَـٰسِقِینَ',
    'قل انفقوا طوعا او كرها لن يتقبل منكم انكم كنتم قوما فاسقين',
    'قُلۡ أَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> طَوۡعًا أَوۡ كَرۡ<rule class=idgham_wo_ghunnah>هًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُتَقَبَّلَ مِ<rule class=ikhafa>نك</rule>ُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َكُمۡ كُ<rule class=ikhafa>نت</rule>ُمۡ قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 10, 2, 195, 162, 78, 'false'
  );
  
  -- Ayah 54 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1289,
    'وَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَـٰتُهُمۡ إِلَّاۤ أَنَّهُمۡ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا یَأۡتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا یُنفِقُونَ إِلَّا وَهُمۡ كَـٰرِهُونَ',
    'وما منعهم ان تقبل منهم نفقاتهم الا انهم كفروا بالله وبرسوله ولا ياتون الصلاة الا وهم كسالى ولا ينفقون الا وهم كارهون',
    'وَمَا مَنَعَهُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>قۡ</rule>بَلَ مِنۡهُمۡ نَفَقَ<rule class=madda_normal>ـٰ</rule>تُهُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ كَفَرُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَبِرَسُولِه<rule class=madda_normal>ِۦ</rule> وَلَا يَأۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا يُ<rule class=ikhafa>نف</rule>ِقُونَ إِلَّا وَهُمۡ كَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 10, 2, 195, 162, 78, 'false'
  );
  
  -- Ayah 55 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1290,
    'فَلَا تُعۡجِبۡكَ أَمۡوَ ٰ⁠لُهُمۡ وَلَاۤ أَوۡلَـٰدُهُمۡۚ إِنَّمَا یُرِیدُ ٱللَّهُ لِیُعَذِّبَهُم بِهَا فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَـٰفِرُونَ',
    'فلا تعجبك اموالهم ولا اولادهم انما يريد الله ليعذبهم بها في الحياة الدنيا وتزهق انفسهم وهم كافرون',
    'فَلَا تُعۡجِ<rule class=qalaqah>بۡ</rule>كَ أَمۡو<rule class=madda_normal>ٰ</rule>لُهُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دُهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َمَا يُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيُعَذِّبَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَتَزۡهَقَ أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ وَهُمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 10, 2, 196, 162, 78, 'false'
  );
  
  -- Ayah 56 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1291,
    'وَیَحۡلِفُونَ بِٱللَّهِ إِنَّهُمۡ لَمِنكُمۡ وَمَا هُم مِّنكُمۡ وَلَـٰكِنَّهُمۡ قَوۡمࣱ یَفۡرَقُونَ',
    'ويحلفون بالله انهم لمنكم وما هم منكم ولكنهم قوم يفرقون',
    'وَيَحۡلِفُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَمِ<rule class=ikhafa>نك</rule>ُمۡ وَمَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َهُمۡ قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>ي</rule>َفۡرَق<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 10, 2, 196, 162, 78, 'false'
  );
  
  -- Ayah 57 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1292,
    'لَوۡ یَجِدُونَ مَلۡجَـًٔا أَوۡ مَغَـٰرَ ٰ⁠تٍ أَوۡ مُدَّخَلࣰا لَّوَلَّوۡا۟ إِلَیۡهِ وَهُمۡ یَجۡمَحُونَ',
    'لو يجدون ملجا او مغارات او مدخلا لولوا اليه وهم يجمحون',
    'لَوۡ يَجِدُونَ مَلۡجَــًٔا أَوۡ مَغَ<rule class=madda_normal>ـٰ</rule>ر<rule class=madda_normal>ٰ</rule>تٍ أَوۡ مُدَّخَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوَلَّوۡ<rule class=slnt>اۡ</rule> إِلَيۡهِ وَهُمۡ يَ<rule class=qalaqah>جۡ</rule>مَح<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 10, 2, 196, 162, 78, 'false'
  );
  
  -- Ayah 58 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1293,
    'وَمِنۡهُم مَّن یَلۡمِزُكَ فِی ٱلصَّدَقَـٰتِ فَإِنۡ أُعۡطُوا۟ مِنۡهَا رَضُوا۟ وَإِن لَّمۡ یُعۡطَوۡا۟ مِنۡهَاۤ إِذَا هُمۡ یَسۡخَطُونَ',
    'ومنهم من يلمزك في الصدقات فان اعطوا منها رضوا وان لم يعطوا منها اذا هم يسخطون',
    'وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َلۡمِزُكَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّدَقَ<rule class=madda_normal>ـٰ</rule>تِ فَإِنۡ أُعۡطُو<rule class=slnt>اۡ</rule> مِنۡهَا رَضُو<rule class=slnt>اۡ</rule> وَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يُعۡطَوۡ<rule class=slnt>اۡ</rule> مِنۡه<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا هُمۡ يَسۡخَط<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 10, 2, 196, 162, 78, 'false'
  );
  
  -- Ayah 59 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1294,
    'وَلَوۡ أَنَّهُمۡ رَضُوا۟ مَاۤ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسۡبُنَا ٱللَّهُ سَیُؤۡتِینَا ٱللَّهُ مِن فَضۡلِهِۦ وَرَسُولُهُۥۤ إِنَّاۤ إِلَى ٱللَّهِ رَ ٰ⁠غِبُونَ',
    'ولو انهم رضوا ما اتاهم الله ورسوله وقالوا حسبنا الله سيؤتينا الله من فضله ورسوله انا الى الله راغبون',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ رَضُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule> وَقَالُو<rule class=slnt>اۡ</rule> حَسۡبُنَا <rule class=ham_wasl>ٱ</rule>للَّهُ سَيُؤۡتِينَا <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> وَرَسُولُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ ر<rule class=madda_normal>ٰ</rule>غِب<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 10, 2, 196, 162, 78, 'false'
  );
  
  -- Ayah 60 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1295,
    '۞ إِنَّمَا ٱلصَّدَقَـٰتُ لِلۡفُقَرَاۤءِ وَٱلۡمَسَـٰكِینِ وَٱلۡعَـٰمِلِینَ عَلَیۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِی ٱلرِّقَابِ وَٱلۡغَـٰرِمِینَ وَفِی سَبِیلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِیلِۖ فَرِیضَةࣰ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'انما الصدقات للفقراء والمساكين والعاملين عليها والمؤلفة قلوبهم وفي الرقاب والغارمين وفي سبيل الله وابن السبيل فريضة من الله والله عليم حكيم',
    '۞إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّدَقَ<rule class=madda_normal>ـٰ</rule>تُ لِلۡفُقَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينِ وَ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>مِلِينَ عَلَيۡهَا وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّقَابِ وَ<rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>رِمِينَ وَفِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ‌ۖ فَرِيضَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٦٠',
    60, 10, 2, 196, 163, 79, 'false'
  );
  
  -- Ayah 61 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1296,
    'وَمِنۡهُمُ ٱلَّذِینَ یُؤۡذُونَ ٱلنَّبِیَّ وَیَقُولُونَ هُوَ أُذُنࣱۚ قُلۡ أُذُنُ خَیۡرࣲ لَّكُمۡ یُؤۡمِنُ بِٱللَّهِ وَیُؤۡمِنُ لِلۡمُؤۡمِنِینَ وَرَحۡمَةࣱ لِّلَّذِینَ ءَامَنُوا۟ مِنكُمۡۚ وَٱلَّذِینَ یُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِیمࣱ',
    'ومنهم الذين يؤذون النبي ويقولون هو اذن قل اذن خير لكم يؤمن بالله ويؤمن للمؤمنين ورحمة للذين امنوا منكم والذين يؤذون رسول الله لهم عذاب اليم',
    'وَمِنۡهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡذُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىَّ وَيَقُولُونَ هُوَ أُذُ<rule class=ikhafa>نٌ‌ۚ</rule> <rule class=ikhafa>ق</rule>ُلۡ أُذُنُ خَيۡ<rule class=idgham_wo_ghunnah>رٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ يُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَيُؤۡمِنُ لِلۡمُؤۡمِنِينَ وَرَحۡمَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡذُونَ رَسُولَ <rule class=ham_wasl>ٱ</rule>للَّهِ لَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٦١',
    61, 10, 2, 196, 163, 79, 'false'
  );
  
  -- Ayah 62 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1297,
    'یَحۡلِفُونَ بِٱللَّهِ لَكُمۡ لِیُرۡضُوكُمۡ وَٱللَّهُ وَرَسُولُهُۥۤ أَحَقُّ أَن یُرۡضُوهُ إِن كَانُوا۟ مُؤۡمِنِینَ',
    'يحلفون بالله لكم ليرضوكم والله ورسوله احق ان يرضوه ان كانوا مؤمنين',
    'يَحۡلِفُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ لَكُمۡ لِيُرۡضُوكُمۡ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَحَقُّ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرۡضُوهُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> مُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٦٢',
    62, 10, 2, 197, 163, 79, 'false'
  );
  
  -- Ayah 63 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1298,
    'أَلَمۡ یَعۡلَمُوۤا۟ أَنَّهُۥ مَن یُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدࣰا فِیهَاۚ ذَ ٰ⁠لِكَ ٱلۡخِزۡیُ ٱلۡعَظِیمُ',
    'الم يعلموا انه من يحادد الله ورسوله فان له نار جهنم خالدا فيها ذلك الخزي العظيم',
    'أَلَمۡ يَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحَادِدِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> فَأَ<rule class=ghunnah>نّ</rule>َ لَهُ<rule class=madda_normal>ۥ</rule> نَارَ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>ِيهَا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡخِزۡىُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٦٣',
    63, 10, 2, 197, 163, 79, 'false'
  );
  
  -- Ayah 64 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1299,
    'یَحۡذَرُ ٱلۡمُنَـٰفِقُونَ أَن تُنَزَّلَ عَلَیۡهِمۡ سُورَةࣱ تُنَبِّئُهُم بِمَا فِی قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوۤا۟ إِنَّ ٱللَّهَ مُخۡرِجࣱ مَّا تَحۡذَرُونَ',
    'يحذر المنافقون ان تنزل عليهم سورة تنبئهم بما في قلوبهم قل استهزئوا ان الله مخرج ما تحذرون',
    'يَحۡذَرُ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقُونَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُنَزَّلَ عَلَيۡهِمۡ سُورَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>ُنَبِّئُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا فِى قُلُوبِهِمۡ‌ۚ قُلِ <rule class=ham_wasl>ٱ</rule>سۡتَهۡزِء<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡرِ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا تَحۡذَر<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 10, 2, 197, 163, 79, 'false'
  );
  
  -- Ayah 65 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1300,
    'وَلَىِٕن سَأَلۡتَهُمۡ لَیَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَایَـٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ',
    'ولئن سالتهم ليقولن انما كنا نخوض ونلعب قل ابالله واياته ورسوله كنتم تستهزئون',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َأَلۡتَهُمۡ لَيَقُولُ<rule class=ghunnah>نّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َمَا كُ<rule class=ghunnah>نّ</rule>َا نَخُوضُ وَنَلۡعَبُ‌ۚ قُلۡ أَبِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَرَسُولِه<rule class=madda_normal>ِۦ</rule> كُ<rule class=ikhafa>نت</rule>ُمۡ تَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 10, 2, 197, 163, 79, 'false'
  );
  
  -- Ayah 66 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1301,
    'لَا تَعۡتَذِرُوا۟ قَدۡ كَفَرۡتُم بَعۡدَ إِیمَـٰنِكُمۡۚ إِن نَّعۡفُ عَن طَاۤىِٕفَةࣲ مِّنكُمۡ نُعَذِّبۡ طَاۤىِٕفَةَۢ بِأَنَّهُمۡ كَانُوا۟ مُجۡرِمِینَ',
    'لا تعتذروا قد كفرتم بعد ايمانكم ان نعف عن طائفة منكم نعذب طائفة بانهم كانوا مجرمين',
    'لَا تَعۡتَذِرُو<rule class=slnt>اۡ</rule> قَ<rule class=qalaqah>دۡ</rule> كَفَرۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡدَ إِيمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّعۡفُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ نُعَذِّ<rule class=qalaqah>بۡ</rule> ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>ِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> مُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 10, 2, 197, 163, 79, 'false'
  );
  
  -- Ayah 67 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1302,
    'ٱلۡمُنَـٰفِقُونَ وَٱلۡمُنَـٰفِقَـٰتُ بَعۡضُهُم مِّنۢ بَعۡضࣲۚ یَأۡمُرُونَ بِٱلۡمُنكَرِ وَیَنۡهَوۡنَ عَنِ ٱلۡمَعۡرُوفِ وَیَقۡبِضُونَ أَیۡدِیَهُمۡۚ نَسُوا۟ ٱللَّهَ فَنَسِیَهُمۡۚ إِنَّ ٱلۡمُنَـٰفِقِینَ هُمُ ٱلۡفَـٰسِقُونَ',
    'المنافقون والمنافقات بعضهم من بعض يامرون بالمنكر وينهون عن المعروف ويقبضون ايديهم نسوا الله فنسيهم ان المنافقين هم الفاسقون',
    'ٱلۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقُونَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقَ<rule class=madda_normal>ـٰ</rule>تُ بَعۡضُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡ<rule class=idgham_ghunnah>ضٍ‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡمُرُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ وَيَنۡهَوۡنَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَيَ<rule class=qalaqah>قۡ</rule>بِضُونَ أَيۡدِيَهُمۡ‌ۚ نَسُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ فَنَسِيَهُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 10, 2, 197, 164, 79, 'false'
  );
  
  -- Ayah 68 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1303,
    'وَعَدَ ٱللَّهُ ٱلۡمُنَـٰفِقِینَ وَٱلۡمُنَـٰفِقَـٰتِ وَٱلۡكُفَّارَ نَارَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۚ هِیَ حَسۡبُهُمۡۚ وَلَعَنَهُمُ ٱللَّهُۖ وَلَهُمۡ عَذَابࣱ مُّقِیمࣱ',
    'وعد الله المنافقين والمنافقات والكفار نار جهنم خالدين فيها هي حسبهم ولعنهم الله ولهم عذاب مقيم',
    'وَعَدَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡكُفَّارَ نَارَ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ هِىَ حَسۡبُهُمۡ‌ۚ وَلَعَنَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَلَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّق<rule class=madda_permissible>ِي</rule>مٌ ٦٨',
    68, 10, 2, 197, 164, 79, 'false'
  );
  
  -- Ayah 69 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1304,
    'كَٱلَّذِینَ مِن قَبۡلِكُمۡ كَانُوۤا۟ أَشَدَّ مِنكُمۡ قُوَّةࣰ وَأَكۡثَرَ أَمۡوَ ٰ⁠لࣰا وَأَوۡلَـٰدࣰا فَٱسۡتَمۡتَعُوا۟ بِخَلَـٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَـٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِینَ مِن قَبۡلِكُم بِخَلَـٰقِهِمۡ وَخُضۡتُمۡ كَٱلَّذِی خَاضُوۤا۟ۚ أُو۟لَـٰۤىِٕكَ حَبِطَتۡ أَعۡمَـٰلُهُمۡ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ',
    'كالذين من قبلكم كانوا اشد منكم قوة واكثر اموالا واولادا فاستمتعوا بخلاقهم فاستمتعتم بخلاقكم كما استمتع الذين من قبلكم بخلاقهم وخضتم كالذي خاضوا اولئك حبطت اعمالهم في الدنيا والاخرة واولئك هم الخاسرون',
    'كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَشَدَّ مِ<rule class=ikhafa>نك</rule>ُمۡ قُوَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَكۡثَرَ أَمۡو<rule class=madda_normal>ٰ</rule>ل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َأَوۡلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَمۡتَعُو<rule class=slnt>اۡ</rule> بِخَلَ<rule class=madda_normal>ـٰ</rule>قِهِمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَمۡتَعۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَلَ<rule class=madda_normal>ـٰ</rule>قِكُمۡ كَمَا <rule class=ham_wasl>ٱ</rule>سۡتَمۡتَعَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَلَ<rule class=madda_normal>ـٰ</rule>قِهِمۡ وَخُضۡتُمۡ كَ<rule class=ham_wasl>ٱ</rule>لَّذِى خَاض<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ حَبِطَتۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 10, 2, 198, 164, 79, 'false'
  );
  
  -- Ayah 70 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1305,
    'أَلَمۡ یَأۡتِهِمۡ نَبَأُ ٱلَّذِینَ مِن قَبۡلِهِمۡ قَوۡمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَقَوۡمِ إِبۡرَ ٰ⁠هِیمَ وَأَصۡحَـٰبِ مَدۡیَنَ وَٱلۡمُؤۡتَفِكَـٰتِۚ أَتَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِۖ فَمَا كَانَ ٱللَّهُ لِیَظۡلِمَهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'الم ياتهم نبا الذين من قبلهم قوم نوح وعاد وثمود وقوم ابراهيم واصحاب مدين والمؤتفكات اتتهم رسلهم بالبينات فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون',
    'أَلَمۡ يَأۡتِهِمۡ نَبَأُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ قَوۡمِ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَا<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َثَمُودَ وَقَوۡمِ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَأَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ مَ<rule class=qalaqah>دۡ</rule>يَنَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡتَفِكَ<rule class=madda_normal>ـٰ</rule>تِ‌ۚ أَتَتۡهُمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ‌ۖ فَمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيَظۡلِمَهُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 10, 2, 198, 164, 79, 'false'
  );
  
  -- Ayah 71 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1306,
    'وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَـٰتُ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضࣲۚ یَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَیَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَیُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَیُطِیعُونَ ٱللَّهَ وَرَسُولَهُۥۤۚ أُو۟لَـٰۤىِٕكَ سَیَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ',
    'والمؤمنون والمؤمنات بعضهم اولياء بعض يامرون بالمعروف وينهون عن المنكر ويقيمون الصلاة ويؤتون الزكاة ويطيعون الله ورسوله اولئك سيرحمهم الله ان الله عزيز حكيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تُ بَعۡضُهُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡمُرُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ وَيُقِيمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَيُؤۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَيُطِيعُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ سَيَرۡحَمُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٧١',
    71, 10, 2, 198, 164, 79, 'false'
  );
  
  -- Ayah 72 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1307,
    'وَعَدَ ٱللَّهُ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا وَمَسَـٰكِنَ طَیِّبَةࣰ فِی جَنَّـٰتِ عَدۡنࣲۚ وَرِضۡوَ ٰ⁠نࣱ مِّنَ ٱللَّهِ أَكۡبَرُۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'وعد الله المؤمنين والمؤمنات جنات تجري من تحتها الانهار خالدين فيها ومساكن طيبة في جنات عدن ورضوان من الله اكبر ذلك هو الفوز العظيم',
    'وَعَدَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا وَمَسَ<rule class=madda_normal>ـٰ</rule>كِنَ طَيِّبَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>نٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َرِضۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ أَكۡبَرُ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٧٢',
    72, 10, 2, 198, 164, 79, 'false'
  );
  
  -- Ayah 73 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1308,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ جَـٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَـٰفِقِینَ وَٱغۡلُظۡ عَلَیۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'يا ايها النبي جاهد الكفار والمنافقين واغلظ عليهم وماواهم جهنم وبئس المصير',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ جَ<rule class=madda_normal>ـٰ</rule>هِدِ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ وَ<rule class=ham_wasl>ٱ</rule>غۡلُظۡ عَلَيۡهِمۡ‌ۚ وَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٧٣',
    73, 10, 2, 199, 165, 79, 'false'
  );
  
  -- Ayah 74 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1309,
    'یَحۡلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدۡ قَالُوا۟ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُوا۟ بَعۡدَ إِسۡلَـٰمِهِمۡ وَهَمُّوا۟ بِمَا لَمۡ یَنَالُوا۟ۚ وَمَا نَقَمُوۤا۟ إِلَّاۤ أَنۡ أَغۡنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضۡلِهِۦۚ فَإِن یَتُوبُوا۟ یَكُ خَیۡرࣰا لَّهُمۡۖ وَإِن یَتَوَلَّوۡا۟ یُعَذِّبۡهُمُ ٱللَّهُ عَذَابًا أَلِیمࣰا فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۚ وَمَا لَهُمۡ فِی ٱلۡأَرۡضِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ',
    'يحلفون بالله ما قالوا ولقد قالوا كلمة الكفر وكفروا بعد اسلامهم وهموا بما لم ينالوا وما نقموا الا ان اغناهم الله ورسوله من فضله فان يتوبوا يك خيرا لهم وان يتولوا يعذبهم الله عذابا اليما في الدنيا والاخرة وما لهم في الارض من ولي ولا نصير',
    'يَحۡلِفُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ مَا قَالُو<rule class=slnt>اۡ</rule> وَلَقَ<rule class=qalaqah>دۡ</rule> قَالُو<rule class=slnt>اۡ</rule> كَلِمَةَ <rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ وَكَفَرُو<rule class=slnt>اۡ</rule> بَعۡدَ إِسۡلَ<rule class=madda_normal>ـٰ</rule>مِهِمۡ وَهَ<rule class=ghunnah>مّ</rule>ُو<rule class=slnt>اۡ</rule> بِمَا لَمۡ يَنَالُو<rule class=slnt>اۡ‌ۚ</rule> وَمَا نَقَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡ أَغۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۚ فَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتُوبُو<rule class=slnt>اۡ</rule> يَكُ خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَلَّوۡ<rule class=slnt>اۡ</rule> يُعَذِّ<rule class=qalaqah>بۡ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَذَابًا أَلِي<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۚ وَمَا لَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَص<rule class=madda_permissible>ِي</rule>رٍ ٧٤',
    74, 10, 2, 199, 165, 79, 'false'
  );
  
  -- Ayah 75 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1310,
    '۞ وَمِنۡهُم مَّنۡ عَـٰهَدَ ٱللَّهَ لَىِٕنۡ ءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّـٰلِحِینَ',
    'ومنهم من عاهد الله لئن اتانا من فضله لنصدقن ولنكونن من الصالحين',
    '۞وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ عَ<rule class=madda_normal>ـٰ</rule>هَدَ <rule class=ham_wasl>ٱ</rule>للَّهَ لَئِنۡ ءَاتَ<rule class=madda_normal>ـٰ</rule>نَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> لَنَصَّدَّقَ<rule class=ghunnah>نّ</rule>َ وَلَنَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٧٥',
    75, 10, 2, 199, 165, 80, 'false'
  );
  
  -- Ayah 76 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1311,
    'فَلَمَّاۤ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعۡرِضُونَ',
    'فلما اتاهم من فضله بخلوا به وتولوا وهم معرضون',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> بَخِلُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> وَتَوَلَّو<rule class=slnt>اۡ</rule> وَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٧٦',
    76, 10, 2, 199, 165, 80, 'false'
  );
  
  -- Ayah 77 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1312,
    'فَأَعۡقَبَهُمۡ نِفَاقࣰا فِی قُلُوبِهِمۡ إِلَىٰ یَوۡمِ یَلۡقَوۡنَهُۥ بِمَاۤ أَخۡلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ یَكۡذِبُونَ',
    'فاعقبهم نفاقا في قلوبهم الى يوم يلقونه بما اخلفوا الله ما وعدوه وبما كانوا يكذبون',
    'فَأَعۡقَبَهُمۡ نِفَا<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ف</rule>ِى قُلُوبِهِمۡ إِلَىٰ يَوۡمِ يَلۡقَوۡنَهُ<rule class=madda_normal>ۥ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡلَفُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا وَعَدُوهُ وَبِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡذِب<rule class=madda_permissible>ُو</rule>نَ ٧٧',
    77, 10, 2, 199, 165, 80, 'false'
  );
  
  -- Ayah 78 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1313,
    'أَلَمۡ یَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَعۡلَمُ سِرَّهُمۡ وَنَجۡوَىٰهُمۡ وَأَنَّ ٱللَّهَ عَلَّـٰمُ ٱلۡغُیُوبِ',
    'الم يعلموا ان الله يعلم سرهم ونجواهم وان الله علام الغيوب',
    'أَلَمۡ يَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ سِرَّهُمۡ وَنَ<rule class=qalaqah>جۡ</rule>وَ<rule class=madda_normal>ٮٰ</rule>هُمۡ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَّ<rule class=madda_normal>ـٰ</rule>مُ <rule class=ham_wasl>ٱ</rule>لۡغُي<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ِ ٧٨',
    78, 10, 2, 199, 165, 80, 'false'
  );
  
  -- Ayah 79 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1314,
    'ٱلَّذِینَ یَلۡمِزُونَ ٱلۡمُطَّوِّعِینَ مِنَ ٱلۡمُؤۡمِنِینَ فِی ٱلصَّدَقَـٰتِ وَٱلَّذِینَ لَا یَجِدُونَ إِلَّا جُهۡدَهُمۡ فَیَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِیمٌ',
    'الذين يلمزون المطوعين من المؤمنين في الصدقات والذين لا يجدون الا جهدهم فيسخرون منهم سخر الله منهم ولهم عذاب اليم',
    'ٱلَّذِينَ يَلۡمِزُونَ <rule class=ham_wasl>ٱ</rule>لۡمُطَّوِّعِينَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّدَقَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَجِدُونَ إِلَّا جُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ‌ۙ سَخِرَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٧٩',
    79, 10, 2, 199, 165, 80, 'false'
  );
  
  -- Ayah 80 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1315,
    'ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ إِن تَسۡتَغۡفِرۡ لَهُمۡ سَبۡعِینَ مَرَّةࣰ فَلَن یَغۡفِرَ ٱللَّهُ لَهُمۡۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ',
    'استغفر لهم او لا تستغفر لهم ان تستغفر لهم سبعين مرة فلن يغفر الله لهم ذلك بانهم كفروا بالله ورسوله والله لا يهدي القوم الفاسقين',
    'ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَغۡفِرۡ لَهُمۡ سَ<rule class=qalaqah>بۡ</rule>عِينَ مَرَّ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغۡفِرَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُمۡ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَفَرُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٨٠',
    80, 10, 2, 200, 165, 80, 'false'
  );
  
  -- Ayah 81 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1316,
    'فَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَـٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوۤا۟ أَن یُجَـٰهِدُوا۟ بِأَمۡوَ ٰ⁠لِهِمۡ وَأَنفُسِهِمۡ فِی سَبِیلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِی ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرࣰّاۚ لَّوۡ كَانُوا۟ یَفۡقَهُونَ',
    'فرح المخلفون بمقعدهم خلاف رسول الله وكرهوا ان يجاهدوا باموالهم وانفسهم في سبيل الله وقالوا لا تنفروا في الحر قل نار جهنم اشد حرا لو كانوا يفقهون',
    'فَرِحَ <rule class=ham_wasl>ٱ</rule>لۡمُخَلَّفُونَ بِمَ<rule class=qalaqah>قۡ</rule>عَدِهِمۡ خِلَ<rule class=madda_normal>ـٰ</rule>فَ رَسُولِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَكَرِه<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجَ<rule class=madda_normal>ـٰ</rule>هِدُو<rule class=slnt>اۡ</rule> بِأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَقَالُو<rule class=slnt>اۡ</rule> لَا تَ<rule class=ikhafa>نف</rule>ِرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡحَرِّ‌ۗ قُلۡ نَارُ جَهَ<rule class=ghunnah>نّ</rule>َمَ أَشَدُّ حَر<rule class=idgham_wo_ghunnah>ًّا‌ۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡ كَانُو<rule class=slnt>اۡ</rule> يَفۡقَه<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 10, 2, 200, 166, 80, 'false'
  );
  
  -- Ayah 82 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1317,
    'فَلۡیَضۡحَكُوا۟ قَلِیلࣰا وَلۡیَبۡكُوا۟ كَثِیرࣰا جَزَاۤءَۢ بِمَا كَانُوا۟ یَكۡسِبُونَ',
    'فليضحكوا قليلا وليبكوا كثيرا جزاء بما كانوا يكسبون',
    'فَلۡيَضۡحَكُو<rule class=slnt>اۡ</rule> قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َلۡيَ<rule class=qalaqah>بۡ</rule>كُو<rule class=slnt>اۡ</rule> كَثِي<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ج</rule>َز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءَۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 10, 2, 200, 166, 80, 'false'
  );
  
  -- Ayah 83 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1318,
    'فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَاۤىِٕفَةࣲ مِّنۡهُمۡ فَٱسۡتَـٔۡذَنُوكَ لِلۡخُرُوجِ فَقُل لَّن تَخۡرُجُوا۟ مَعِیَ أَبَدࣰا وَلَن تُقَـٰتِلُوا۟ مَعِیَ عَدُوًّاۖ إِنَّكُمۡ رَضِیتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةࣲ فَٱقۡعُدُوا۟ مَعَ ٱلۡخَـٰلِفِینَ',
    'فان رجعك الله الى طائفة منهم فاستاذنوك للخروج فقل لن تخرجوا معي ابدا ولن تقاتلوا معي عدوا انكم رضيتم بالقعود اول مرة فاقعدوا مع الخالفين',
    'فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّجَعَكَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَىٰ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَــٔۡذَنُوكَ لِلۡخُرُوجِ فَقُل لَّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َخۡرُجُو<rule class=slnt>اۡ</rule> مَعِىَ أَبَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُقَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> مَعِىَ عَدُوًّا‌ۖ إِ<rule class=ghunnah>نّ</rule>َكُمۡ رَضِيت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡقُعُودِ أَوَّلَ مَرَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>عُدُو<rule class=slnt>اۡ</rule> مَعَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>لِف<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 10, 2, 200, 166, 80, 'false'
  );
  
  -- Ayah 84 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1319,
    'وَلَا تُصَلِّ عَلَىٰۤ أَحَدࣲ مِّنۡهُم مَّاتَ أَبَدࣰا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦۤۖ إِنَّهُمۡ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمۡ فَـٰسِقُونَ',
    'ولا تصل على احد منهم مات ابدا ولا تقم على قبره انهم كفروا بالله ورسوله وماتوا وهم فاسقون',
    'وَلَا تُصَلِّ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّاتَ أَبَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَقُمۡ عَلَىٰ قَ<rule class=qalaqah>بۡ</rule>رِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَفَرُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَمَاتُو<rule class=slnt>اۡ</rule> وَهُمۡ فَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 10, 2, 200, 166, 80, 'false'
  );
  
  -- Ayah 85 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1320,
    'وَلَا تُعۡجِبۡكَ أَمۡوَ ٰ⁠لُهُمۡ وَأَوۡلَـٰدُهُمۡۚ إِنَّمَا یُرِیدُ ٱللَّهُ أَن یُعَذِّبَهُم بِهَا فِی ٱلدُّنۡیَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَـٰفِرُونَ',
    'ولا تعجبك اموالهم واولادهم انما يريد الله ان يعذبهم بها في الدنيا وتزهق انفسهم وهم كافرون',
    'وَلَا تُعۡجِ<rule class=qalaqah>بۡ</rule>كَ أَمۡو<rule class=madda_normal>ٰ</rule>لُهُمۡ وَأَوۡلَ<rule class=madda_normal>ـٰ</rule>دُهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َمَا يُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعَذِّبَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَتَزۡهَقَ أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ وَهُمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٨٥',
    85, 10, 2, 200, 166, 80, 'false'
  );
  
  -- Ayah 86 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1321,
    'وَإِذَاۤ أُنزِلَتۡ سُورَةٌ أَنۡ ءَامِنُوا۟ بِٱللَّهِ وَجَـٰهِدُوا۟ مَعَ رَسُولِهِ ٱسۡتَـٔۡذَنَكَ أُو۟لُوا۟ ٱلطَّوۡلِ مِنۡهُمۡ وَقَالُوا۟ ذَرۡنَا نَكُن مَّعَ ٱلۡقَـٰعِدِینَ',
    'واذا انزلت سورة ان امنوا بالله وجاهدوا مع رسوله استاذنك اولو الطول منهم وقالوا ذرنا نكن مع القاعدين',
    'وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَتۡ سُورَةٌ أَنۡ ءَامِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَجَ<rule class=madda_normal>ـٰ</rule>هِدُو<rule class=slnt>اۡ</rule> مَعَ رَسُولِهِ <rule class=ham_wasl>ٱ</rule>سۡتَــٔۡذَنَكَ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّوۡلِ مِنۡهُمۡ وَقَالُو<rule class=slnt>اۡ</rule> ذَرۡنَا نَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>َّعَ <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>عِد<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 10, 2, 200, 166, 80, 'false'
  );
  
  -- Ayah 87 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1322,
    'رَضُوا۟ بِأَن یَكُونُوا۟ مَعَ ٱلۡخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَفۡقَهُونَ',
    'رضوا بان يكونوا مع الخوالف وطبع على قلوبهم فهم لا يفقهون',
    'رَضُو<rule class=slnt>اۡ</rule> بِأ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونُو<rule class=slnt>اۡ</rule> مَعَ <rule class=ham_wasl>ٱ</rule>لۡخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَه<rule class=madda_permissible>ُو</rule>نَ ٨٧',
    87, 10, 2, 201, 166, 80, 'false'
  );
  
  -- Ayah 88 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1323,
    'لَـٰكِنِ ٱلرَّسُولُ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ جَـٰهَدُوا۟ بِأَمۡوَ ٰ⁠لِهِمۡ وَأَنفُسِهِمۡۚ وَأُو۟لَـٰۤىِٕكَ لَهُمُ ٱلۡخَیۡرَ ٰ⁠تُۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'لكن الرسول والذين امنوا معه جاهدوا باموالهم وانفسهم واولئك لهم الخيرات واولئك هم المفلحون',
    'لَ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> جَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> بِأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۚ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تُ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 10, 2, 201, 166, 80, 'false'
  );
  
  -- Ayah 89 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1324,
    'أَعَدَّ ٱللَّهُ لَهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'اعد الله لهم جنات تجري من تحتها الانهار خالدين فيها ذلك الفوز العظيم',
    'أَعَدَّ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٨٩',
    89, 10, 2, 201, 166, 80, 'false'
  );
  
  -- Ayah 90 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1325,
    'وَجَاۤءَ ٱلۡمُعَذِّرُونَ مِنَ ٱلۡأَعۡرَابِ لِیُؤۡذَنَ لَهُمۡ وَقَعَدَ ٱلَّذِینَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥۚ سَیُصِیبُ ٱلَّذِینَ كَفَرُوا۟ مِنۡهُمۡ عَذَابٌ أَلِیمࣱ',
    'وجاء المعذرون من الاعراب ليؤذن لهم وقعد الذين كذبوا الله ورسوله سيصيب الذين كفروا منهم عذاب اليم',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡمُعَذِّرُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابِ لِيُؤۡذَنَ لَهُمۡ وَقَعَدَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule>‌ۚ سَيُصِيبُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٩٠',
    90, 10, 2, 201, 167, 80, 'false'
  );
  
  -- Ayah 91 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1326,
    'لَّیۡسَ عَلَى ٱلضُّعَفَاۤءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِینَ لَا یَجِدُونَ مَا یُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦۚ مَا عَلَى ٱلۡمُحۡسِنِینَ مِن سَبِیلࣲۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'ليس على الضعفاء ولا على المرضى ولا على الذين لا يجدون ما ينفقون حرج اذا نصحوا لله ورسوله ما على المحسنين من سبيل والله غفور رحيم',
    'لَّيۡسَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّعَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَلَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمَرۡضَىٰ وَلَا عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَجِدُونَ مَا يُ<rule class=ikhafa>نف</rule>ِقُونَ حَرَجٌ إِذَا نَصَحُو<rule class=slnt>اۡ</rule> لِلَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule>‌ۚ مَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِنِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِي<rule class=idgham_ghunnah>لٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٩١',
    91, 10, 2, 201, 167, 80, 'false'
  );
  
  -- Ayah 92 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1327,
    'وَلَا عَلَى ٱلَّذِینَ إِذَا مَاۤ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَاۤ أَجِدُ مَاۤ أَحۡمِلُكُمۡ عَلَیۡهِ تَوَلَّوا۟ وَّأَعۡیُنُهُمۡ تَفِیضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا یَجِدُوا۟ مَا یُنفِقُونَ',
    'ولا على الذين اذا ما اتوك لتحملهم قلت لا اجد ما احملكم عليه تولوا واعينهم تفيض من الدمع حزنا الا يجدوا ما ينفقون',
    'وَلَا عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ إِذَا م<rule class=madda_obligatory_monfasel>َآ</rule> أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ ل<rule class=madda_obligatory_monfasel>َآ</rule> أَجِدُ م<rule class=madda_obligatory_monfasel>َآ</rule> أَحۡمِلُكُمۡ عَلَيۡهِ تَوَلَّو<rule class=slnt>اۡ</rule> وَّأَعۡيُنُهُمۡ تَفِيضُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّمۡعِ حَزَنًا أَلَّا يَجِدُو<rule class=slnt>اۡ</rule> مَا يُ<rule class=ikhafa>نف</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٩٢',
    92, 10, 2, 201, 167, 80, 'false'
  );
  
  -- Ayah 93 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1328,
    '۞ إِنَّمَا ٱلسَّبِیلُ عَلَى ٱلَّذِینَ یَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِیَاۤءُۚ رَضُوا۟ بِأَن یَكُونُوا۟ مَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَعۡلَمُونَ',
    'انما السبيل على الذين يستاذنونك وهم اغنياء رضوا بان يكونوا مع الخوالف وطبع الله على قلوبهم فهم لا يعلمون',
    '۞إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلُ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَسۡتَــٔۡذِنُونَكَ وَهُمۡ أَغۡنِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ رَضُو<rule class=slnt>اۡ</rule> بِأ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونُو<rule class=slnt>اۡ</rule> مَعَ <rule class=ham_wasl>ٱ</rule>لۡخَوَالِفِ وَطَبَعَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 11, 2, 201, 167, 81, 'false'
  );
  
  -- Ayah 94 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1329,
    'یَعۡتَذِرُونَ إِلَیۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَیۡهِمۡۚ قُل لَّا تَعۡتَذِرُوا۟ لَن نُّؤۡمِنَ لَكُمۡ قَدۡ نَبَّأَنَا ٱللَّهُ مِنۡ أَخۡبَارِكُمۡۚ وَسَیَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'يعتذرون اليكم اذا رجعتم اليهم قل لا تعتذروا لن نؤمن لكم قد نبانا الله من اخباركم وسيرى الله عملكم ورسوله ثم تردون الى عالم الغيب والشهادة فينبئكم بما كنتم تعملون',
    'يَعۡتَذِرُونَ إِلَيۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَيۡهِمۡ‌ۚ قُل لَّا تَعۡتَذِرُو<rule class=slnt>اۡ</rule> ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّؤۡمِنَ لَكُمۡ قَ<rule class=qalaqah>دۡ</rule> نَبَّأَنَا <rule class=ham_wasl>ٱ</rule>للَّهُ مِنۡ أَخۡبَارِكُمۡ‌ۚ وَسَيَرَى <rule class=ham_wasl>ٱ</rule>للَّهُ عَمَلَكُمۡ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ تُرَدُّونَ إِلَىٰ عَ<rule class=madda_normal>ـٰ</rule>لِمِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ فَيُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٤',
    94, 11, 2, 202, 167, 81, 'false'
  );
  
  -- Ayah 95 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1330,
    'سَیَحۡلِفُونَ بِٱللَّهِ لَكُمۡ إِذَا ٱنقَلَبۡتُمۡ إِلَیۡهِمۡ لِتُعۡرِضُوا۟ عَنۡهُمۡۖ فَأَعۡرِضُوا۟ عَنۡهُمۡۖ إِنَّهُمۡ رِجۡسࣱۖ وَمَأۡوَىٰهُمۡ جَهَنَّمُ جَزَاۤءَۢ بِمَا كَانُوا۟ یَكۡسِبُونَ',
    'سيحلفون بالله لكم اذا انقلبتم اليهم لتعرضوا عنهم فاعرضوا عنهم انهم رجس وماواهم جهنم جزاء بما كانوا يكسبون',
    'سَيَحۡلِفُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ لَكُمۡ إِذَا <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>َلَ<rule class=qalaqah>بۡ</rule>تُمۡ إِلَيۡهِمۡ لِتُعۡرِضُو<rule class=slnt>اۡ</rule> عَنۡهُمۡ‌ۖ فَأَعۡرِضُو<rule class=slnt>اۡ</rule> عَنۡهُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ رِ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>سٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءَۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٩٥',
    95, 11, 2, 202, 167, 81, 'false'
  );
  
  -- Ayah 96 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1331,
    'یَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡا۟ عَنۡهُمۡۖ فَإِن تَرۡضَوۡا۟ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا یَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَـٰسِقِینَ',
    'يحلفون لكم لترضوا عنهم فان ترضوا عنهم فان الله لا يرضى عن القوم الفاسقين',
    'يَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡ<rule class=slnt>اۡ</rule> عَنۡهُمۡ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرۡضَوۡ<rule class=slnt>اۡ</rule> عَنۡهُمۡ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَرۡضَىٰ عَنِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٩٦',
    96, 11, 2, 202, 167, 81, 'false'
  );
  
  -- Ayah 97 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1332,
    'ٱلۡأَعۡرَابُ أَشَدُّ كُفۡرࣰا وَنِفَاقࣰا وَأَجۡدَرُ أَلَّا یَعۡلَمُوا۟ حُدُودَ مَاۤ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'الاعراب اشد كفرا ونفاقا واجدر الا يعلموا حدود ما انزل الله على رسوله والله عليم حكيم',
    'ٱلۡأَعۡرَابُ أَشَدُّ كُفۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنِفَا<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule>دَرُ أَلَّا يَعۡلَمُو<rule class=slnt>اۡ</rule> حُدُودَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ رَسُولِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٩٧',
    97, 11, 2, 202, 167, 81, 'false'
  );
  
  -- Ayah 98 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1333,
    'وَمِنَ ٱلۡأَعۡرَابِ مَن یَتَّخِذُ مَا یُنفِقُ مَغۡرَمࣰا وَیَتَرَبَّصُ بِكُمُ ٱلدَّوَاۤىِٕرَۚ عَلَیۡهِمۡ دَاۤىِٕرَةُ ٱلسَّوۡءِۗ وَٱللَّهُ سَمِیعٌ عَلِیمࣱ',
    'ومن الاعراب من يتخذ ما ينفق مغرما ويتربص بكم الدوائر عليهم دائرة السوء والله سميع عليم',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذُ مَا يُ<rule class=ikhafa>نف</rule>ِقُ مَغۡرَ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َيَتَرَبَّصُ بِكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّو<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرَ‌ۚ عَلَيۡهِمۡ د<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرَةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّوۡءِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٩٨',
    98, 11, 2, 202, 167, 81, 'false'
  );
  
  -- Ayah 99 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1334,
    'وَمِنَ ٱلۡأَعۡرَابِ مَن یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَیَتَّخِذُ مَا یُنفِقُ قُرُبَـٰتٍ عِندَ ٱللَّهِ وَصَلَوَ ٰ⁠تِ ٱلرَّسُولِۚ أَلَاۤ إِنَّهَا قُرۡبَةࣱ لَّهُمۡۚ سَیُدۡخِلُهُمُ ٱللَّهُ فِی رَحۡمَتِهِۦۤۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'ومن الاعراب من يؤمن بالله واليوم الاخر ويتخذ ما ينفق قربات عند الله وصلوات الرسول الا انها قربة لهم سيدخلهم الله في رحمته ان الله غفور رحيم',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ وَيَتَّخِذُ مَا يُ<rule class=ikhafa>نف</rule>ِقُ قُرُبَ<rule class=madda_normal>ـٰ</rule>تٍ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَصَلَو<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ‌ۚ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهَا قُرۡبَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ‌ۚ سَيُ<rule class=qalaqah>دۡ</rule>خِلُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى رَحۡمَتِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٩٩',
    99, 11, 2, 202, 167, 81, 'false'
  );
  
  -- Ayah 100 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1335,
    'وَٱلسَّـٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَـٰجِرِینَ وَٱلۡأَنصَارِ وَٱلَّذِینَ ٱتَّبَعُوهُم بِإِحۡسَـٰنࣲ رَّضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُ وَأَعَدَّ لَهُمۡ جَنَّـٰتࣲ تَجۡرِی تَحۡتَهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'والسابقون الاولون من المهاجرين والانصار والذين اتبعوهم باحسان رضي الله عنهم ورضوا عنه واعد لهم جنات تجري تحتها الانهار خالدين فيها ابدا ذلك الفوز العظيم',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>بِقُونَ <rule class=ham_wasl>ٱ</rule>لۡأَوَّلُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُهَ<rule class=madda_normal>ـٰ</rule>جِرِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نص</rule>َارِ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّبَعُوه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِإِحۡسَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>نٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّضِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَنۡهُمۡ وَرَضُو<rule class=slnt>اۡ</rule> عَنۡهُ وَأَعَدَّ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى تَحۡتَهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=ikhafa>دًا‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ١٠٠',
    100, 11, 2, 203, 168, 81, 'false'
  );
  
  -- Ayah 101 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1336,
    'وَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ مُنَـٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِینَةِ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَیۡنِ ثُمَّ یُرَدُّونَ إِلَىٰ عَذَابٍ عَظِیمࣲ',
    'وممن حولكم من الاعراب منافقون ومن اهل المدينة مردوا على النفاق لا تعلمهم نحن نعلمهم سنعذبهم مرتين ثم يردون الى عذاب عظيم',
    'وَمِ<rule class=ghunnah>مّ</rule>َنۡ حَوۡلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابِ مُنَ<rule class=madda_normal>ـٰ</rule>فِقُونَ‌ۖ وَمِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ‌ۖ مَرَدُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِفَاقِ لَا تَعۡلَمُهُمۡ‌ۖ نَحۡنُ نَعۡلَمُهُمۡ‌ۚ سَنُعَذِّبُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرَّتَيۡنِ ثُ<rule class=ghunnah>مّ</rule>َ يُرَدُّونَ إِلَىٰ عَذَابٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ١٠١',
    101, 11, 2, 203, 168, 81, 'false'
  );
  
  -- Ayah 102 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1337,
    'وَءَاخَرُونَ ٱعۡتَرَفُوا۟ بِذُنُوبِهِمۡ خَلَطُوا۟ عَمَلࣰا صَـٰلِحࣰا وَءَاخَرَ سَیِّئًا عَسَى ٱللَّهُ أَن یَتُوبَ عَلَیۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ',
    'واخرون اعترفوا بذنوبهم خلطوا عملا صالحا واخر سيئا عسى الله ان يتوب عليهم ان الله غفور رحيم',
    'وَءَاخَرُونَ <rule class=ham_wasl>ٱ</rule>عۡتَرَفُو<rule class=slnt>اۡ</rule> بِذُنُوبِهِمۡ خَلَطُو<rule class=slnt>اۡ</rule> عَمَل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ص</rule>َ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َءَاخَرَ سَيِّئًا عَسَى <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتُوبَ عَلَيۡهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٠٢',
    102, 11, 2, 203, 168, 81, 'false'
  );
  
  -- Ayah 103 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1338,
    'خُذۡ مِنۡ أَمۡوَ ٰ⁠لِهِمۡ صَدَقَةࣰ تُطَهِّرُهُمۡ وَتُزَكِّیهِم بِهَا وَصَلِّ عَلَیۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنࣱ لَّهُمۡۗ وَٱللَّهُ سَمِیعٌ عَلِیمٌ',
    'خذ من اموالهم صدقة تطهرهم وتزكيهم بها وصل عليهم ان صلاتك سكن لهم والله سميع عليم',
    'خُذۡ مِنۡ أَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ صَدَقَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>ُطَهِّرُهُمۡ وَتُزَكِّيه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا وَصَلِّ عَلَيۡهِمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ صَلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>تَكَ سَكَ<rule class=idgham_wo_ghunnah>نٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٠٣',
    103, 11, 2, 203, 168, 81, 'false'
  );
  
  -- Ayah 104 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1339,
    'أَلَمۡ یَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ هُوَ یَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَیَأۡخُذُ ٱلصَّدَقَـٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ',
    'الم يعلموا ان الله هو يقبل التوبة عن عباده وياخذ الصدقات وان الله هو التواب الرحيم',
    'أَلَمۡ يَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ يَ<rule class=qalaqah>قۡ</rule>بَلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡبَةَ عَنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule> وَيَأۡخُذُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّدَقَ<rule class=madda_normal>ـٰ</rule>تِ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوَّابُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٠٤',
    104, 11, 2, 203, 168, 81, 'false'
  );
  
  -- Ayah 105 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1340,
    'وَقُلِ ٱعۡمَلُوا۟ فَسَیَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'وقل اعملوا فسيرى الله عملكم ورسوله والمؤمنون وستردون الى عالم الغيب والشهادة فينبئكم بما كنتم تعملون',
    'وَقُلِ <rule class=ham_wasl>ٱ</rule>عۡمَلُو<rule class=slnt>اۡ</rule> فَسَيَرَى <rule class=ham_wasl>ٱ</rule>للَّهُ عَمَلَكُمۡ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ‌ۖ وَسَتُرَدُّونَ إِلَىٰ عَ<rule class=madda_normal>ـٰ</rule>لِمِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ فَيُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٠٥',
    105, 11, 2, 203, 168, 81, 'false'
  );
  
  -- Ayah 106 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1341,
    'وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ إِمَّا یُعَذِّبُهُمۡ وَإِمَّا یَتُوبُ عَلَیۡهِمۡۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'واخرون مرجون لامر الله اما يعذبهم واما يتوب عليهم والله عليم حكيم',
    'وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ghunnah>مّ</rule>َا يُعَذِّبُهُمۡ وَإِ<rule class=ghunnah>مّ</rule>َا يَتُوبُ عَلَيۡهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ١٠٦',
    106, 11, 2, 203, 168, 81, 'false'
  );
  
  -- Ayah 107 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1342,
    'وَٱلَّذِینَ ٱتَّخَذُوا۟ مَسۡجِدࣰا ضِرَارࣰا وَكُفۡرࣰا وَتَفۡرِیقَۢا بَیۡنَ ٱلۡمُؤۡمِنِینَ وَإِرۡصَادࣰا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ وَلَیَحۡلِفُنَّ إِنۡ أَرَدۡنَاۤ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ یَشۡهَدُ إِنَّهُمۡ لَكَـٰذِبُونَ',
    'والذين اتخذوا مسجدا ضرارا وكفرا وتفريقا بين المؤمنين وارصادا لمن حارب الله ورسوله من قبل وليحلفن ان اردنا الا الحسنى والله يشهد انهم لكاذبون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مَسۡجِ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ض</rule>ِرَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َكُفۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َتَفۡرِيق<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَإِرۡصَا<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَنۡ حَارَبَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۚ وَلَيَحۡلِفُ<rule class=ghunnah>نّ</rule>َ إِنۡ أَرَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَشۡهَدُ إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ١٠٧',
    107, 11, 2, 204, 168, 81, 'false'
  );
  
  -- Ayah 108 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1343,
    'لَا تَقُمۡ فِیهِ أَبَدࣰاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ یَوۡمٍ أَحَقُّ أَن تَقُومَ فِیهِۚ فِیهِ رِجَالࣱ یُحِبُّونَ أَن یَتَطَهَّرُوا۟ۚ وَٱللَّهُ یُحِبُّ ٱلۡمُطَّهِّرِینَ',
    'لا تقم فيه ابدا لمسجد اسس على التقوى من اول يوم احق ان تقوم فيه فيه رجال يحبون ان يتطهروا والله يحب المطهرين',
    'لَا تَقُمۡ فِيهِ أَبَ<rule class=idgham_wo_ghunnah>دًا‌ۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمَسۡجِدٌ أُسِّسَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=qalaqah>قۡ</rule>وَىٰ مِنۡ أَوَّلِ يَوۡمٍ أَحَقُّ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُومَ فِيهِ‌ۚ فِيهِ رِجَا<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُحِبُّونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَطَهَّرُو<rule class=slnt>اۡ‌ۚ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُطَّهِّر<rule class=madda_permissible>ِي</rule>نَ ١٠٨',
    108, 11, 2, 204, 168, 81, 'false'
  );
  
  -- Ayah 109 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1344,
    'أَفَمَنۡ أَسَّسَ بُنۡیَـٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَ ٰ⁠نٍ خَیۡرٌ أَم مَّنۡ أَسَّسَ بُنۡیَـٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارࣲ فَٱنۡهَارَ بِهِۦ فِی نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'افمن اسس بنيانه على تقوى من الله ورضوان خير ام من اسس بنيانه على شفا جرف هار فانهار به في نار جهنم والله لا يهدي القوم الظالمين',
    'أَفَمَنۡ أَسَّسَ بُنۡيَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ تَ<rule class=qalaqah>قۡ</rule>وَىٰ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرِضۡو<rule class=madda_normal>ٰ</rule>نٍ خَيۡرٌ أ<rule class=idgham_shafawi>َم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ أَسَّسَ بُنۡيَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ شَفَا جُرُفٍ هَا<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>نۡهَارَ بِه<rule class=madda_normal>ِۦ</rule> فِى نَارِ جَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٠٩',
    109, 11, 2, 204, 168, 81, 'false'
  );
  
  -- Ayah 110 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1345,
    'لَا یَزَالُ بُنۡیَـٰنُهُمُ ٱلَّذِی بَنَوۡا۟ رِیبَةࣰ فِی قُلُوبِهِمۡ إِلَّاۤ أَن تَقَطَّعَ قُلُوبُهُمۡۗ وَٱللَّهُ عَلِیمٌ حَكِیمٌ',
    'لا يزال بنيانهم الذي بنوا ريبة في قلوبهم الا ان تقطع قلوبهم والله عليم حكيم',
    'لَا يَزَالُ بُنۡيَ<rule class=madda_normal>ـٰ</rule>نُهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى بَنَوۡ<rule class=slnt>اۡ</rule> رِيبَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى قُلُوبِهِمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقَطَّعَ قُلُوبُهُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ١١٠',
    110, 11, 2, 204, 168, 81, 'false'
  );
  
  -- Ayah 111 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1346,
    '۞ إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِینَ أَنفُسَهُمۡ وَأَمۡوَ ٰ⁠لَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ یُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِ فَیَقۡتُلُونَ وَیُقۡتَلُونَۖ وَعۡدًا عَلَیۡهِ حَقࣰّا فِی ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِیلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُوا۟ بِبَیۡعِكُمُ ٱلَّذِی بَایَعۡتُم بِهِۦۚ وَذَ ٰ⁠لِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'ان الله اشترى من المؤمنين انفسهم واموالهم بان لهم الجنة يقاتلون في سبيل الله فيقتلون ويقتلون وعدا عليه حقا في التوراة والانجيل والقران ومن اوفى بعهده من الله فاستبشروا ببيعكم الذي بايعتم به وذلك هو الفوز العظيم',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>شۡتَرَىٰ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَأَمۡو<rule class=madda_normal>ٰ</rule>لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَ<rule class=ghunnah>نّ</rule>َ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ‌ۚ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَيَ<rule class=qalaqah>قۡ</rule>تُلُونَ وَيُ<rule class=qalaqah>قۡ</rule>تَلُونَ‌ۖ وَعۡدًا عَلَيۡهِ حَق<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلِ وَ<rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ‌ۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِه<rule class=madda_normal>ِۦ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>سۡتَ<rule class=qalaqah>بۡ</rule>شِرُو<rule class=slnt>اۡ</rule> بِبَيۡعِكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى بَايَعۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ١١١',
    111, 11, 2, 204, 169, 82, 'false'
  );
  
  -- Ayah 112 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1347,
    'ٱلتَّـٰۤىِٕبُونَ ٱلۡعَـٰبِدُونَ ٱلۡحَـٰمِدُونَ ٱلسَّـٰۤىِٕحُونَ ٱلرَّ ٰ⁠كِعُونَ ٱلسَّـٰجِدُونَ ٱلۡـَٔامِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَـٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ',
    'التائبون العابدون الحامدون السائحون الراكعون الساجدون الامرون بالمعروف والناهون عن المنكر والحافظون لحدود الله وبشر المؤمنين',
    'ٱ<rule class=laam_shamsiyah>ل</rule>تَّ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِبُونَ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>بِدُونَ <rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>مِدُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِحُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>كِعُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>جِدُونَ <rule class=ham_wasl>ٱ</rule>لۡأَمِرُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاهُونَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ وَ<rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>فِظُونَ لِحُدُودِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١١٢',
    112, 11, 2, 205, 169, 82, 'false'
  );
  
  -- Ayah 113 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1348,
    'مَا كَانَ لِلنَّبِیِّ وَٱلَّذِینَ ءَامَنُوۤا۟ أَن یَسۡتَغۡفِرُوا۟ لِلۡمُشۡرِكِینَ وَلَوۡ كَانُوۤا۟ أُو۟لِی قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَیَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَـٰبُ ٱلۡجَحِیمِ',
    'ما كان للنبي والذين امنوا ان يستغفروا للمشركين ولو كانوا اولي قربى من بعد ما تبين لهم انهم اصحاب الجحيم',
    'مَا كَانَ لِل<rule class=ghunnah>نّ</rule>َبِىِّ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَغۡفِرُو<rule class=slnt>اۡ</rule> لِلۡمُشۡرِكِينَ وَلَوۡ كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أُ<rule class=slnt>وۡ</rule>لِى قُرۡبَىٰ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا تَبَيَّنَ لَهُمۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ١١٣',
    113, 11, 2, 205, 169, 82, 'false'
  );
  
  -- Ayah 114 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1349,
    'وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَ ٰ⁠هِیمَ لِأَبِیهِ إِلَّا عَن مَّوۡعِدَةࣲ وَعَدَهَاۤ إِیَّاهُ فَلَمَّا تَبَیَّنَ لَهُۥۤ أَنَّهُۥ عَدُوࣱّ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَ ٰ⁠هِیمَ لَأَوَّ ٰ⁠هٌ حَلِیمࣱ',
    'وما كان استغفار ابراهيم لابيه الا عن موعدة وعدها اياه فلما تبين له انه عدو لله تبرا منه ان ابراهيم لاواه حليم',
    'وَمَا كَانَ <rule class=ham_wasl>ٱ</rule>سۡتِغۡفَارُ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ لِأَبِيهِ إِلَّا ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّوۡعِدَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَدَه<rule class=madda_obligatory_monfasel>َآ</rule> إِيَّاهُ فَلَ<rule class=ghunnah>مّ</rule>َا تَبَيَّنَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَدُ<rule class=idgham_wo_ghunnah>وٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّهِ تَبَرَّأَ مِنۡهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ لَأَوّ<rule class=madda_normal>ٰ</rule>هٌ حَل<rule class=madda_permissible>ِي</rule>مٌ ١١٤',
    114, 11, 2, 205, 169, 82, 'false'
  );
  
  -- Ayah 115 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1350,
    'وَمَا كَانَ ٱللَّهُ لِیُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ یُبَیِّنَ لَهُم مَّا یَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمٌ',
    'وما كان الله ليضل قوما بعد اذ هداهم حتى يبين لهم ما يتقون ان الله بكل شيء عليم',
    'وَمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيُضِلَّ قَوۡم<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َعۡدَ إِذۡ هَدَ<rule class=madda_normal>ٮٰ</rule>هُمۡ حَتَّىٰ يُبَيِّنَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَتَّقُونَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ١١٥',
    115, 11, 2, 205, 169, 82, 'false'
  );
  
  -- Ayah 116 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1351,
    'إِنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ یُحۡیِۦ وَیُمِیتُۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ',
    'ان الله له ملك السماوات والارض يحيي ويميت وما لكم من دون الله من ولي ولا نصير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُ‌ۚ وَمَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَص<rule class=madda_permissible>ِي</rule>رٍ ١١٦',
    116, 11, 2, 205, 169, 82, 'false'
  );
  
  -- Ayah 117 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1352,
    'لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِیِّ وَٱلۡمُهَـٰجِرِینَ وَٱلۡأَنصَارِ ٱلَّذِینَ ٱتَّبَعُوهُ فِی سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ یَزِیغُ قُلُوبُ فَرِیقࣲ مِّنۡهُمۡ ثُمَّ تَابَ عَلَیۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفࣱ رَّحِیمࣱ',
    'لقد تاب الله على النبي والمهاجرين والانصار الذين اتبعوه في ساعة العسرة من بعد ما كاد يزيغ قلوب فريق منهم ثم تاب عليهم انه بهم رءوف رحيم',
    'لَّقَ<rule class=idgham_mutajanisayn>د</rule> تَّابَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّ وَ<rule class=ham_wasl>ٱ</rule>لۡمُهَ<rule class=madda_normal>ـٰ</rule>جِرِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نص</rule>َارِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّبَعُوهُ فِى سَاعَةِ <rule class=ham_wasl>ٱ</rule>لۡعُسۡرَةِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِي<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ تَابَ عَلَيۡهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِهِمۡ رَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١١٧',
    117, 11, 2, 205, 169, 82, 'false'
  );
  
  -- Ayah 118 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1353,
    'وَعَلَى ٱلثَّلَـٰثَةِ ٱلَّذِینَ خُلِّفُوا۟ حَتَّىٰۤ إِذَا ضَاقَتۡ عَلَیۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَیۡهِمۡ أَنفُسُهُمۡ وَظَنُّوۤا۟ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّاۤ إِلَیۡهِ ثُمَّ تَابَ عَلَیۡهِمۡ لِیَتُوبُوۤا۟ۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ',
    'وعلى الثلاثة الذين خلفوا حتى اذا ضاقت عليهم الارض بما رحبت وضاقت عليهم انفسهم وظنوا ان لا ملجا من الله الا اليه ثم تاب عليهم ليتوبوا ان الله هو التواب الرحيم',
    'وَعَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّلَ<rule class=madda_normal>ـٰ</rule>ثَةِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خُلِّفُو<rule class=slnt>اۡ</rule> حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ضَاقَتۡ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَيۡهِمۡ أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ وَظَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا مَلۡجَأَ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ ثُ<rule class=ghunnah>مّ</rule>َ تَابَ عَلَيۡهِمۡ لِيَتُوب<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوَّابُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١١٨',
    118, 11, 2, 206, 169, 82, 'false'
  );
  
  -- Ayah 119 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1354,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّـٰدِقِینَ',
    'يا ايها الذين امنوا اتقوا الله وكونوا مع الصادقين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَكُونُو<rule class=slnt>اۡ</rule> مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١١٩',
    119, 11, 2, 206, 170, 82, 'false'
  );
  
  -- Ayah 120 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1355,
    'مَا كَانَ لِأَهۡلِ ٱلۡمَدِینَةِ وَمَنۡ حَوۡلَهُم مِّنَ ٱلۡأَعۡرَابِ أَن یَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا یَرۡغَبُوا۟ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ لَا یُصِیبُهُمۡ ظَمَأࣱ وَلَا نَصَبࣱ وَلَا مَخۡمَصَةࣱ فِی سَبِیلِ ٱللَّهِ وَلَا یَطَـُٔونَ مَوۡطِئࣰا یَغِیظُ ٱلۡكُفَّارَ وَلَا یَنَالُونَ مِنۡ عَدُوࣲّ نَّیۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلࣱ صَـٰلِحٌۚ إِنَّ ٱللَّهَ لَا یُضِیعُ أَجۡرَ ٱلۡمُحۡسِنِینَ',
    'ما كان لاهل المدينة ومن حولهم من الاعراب ان يتخلفوا عن رسول الله ولا يرغبوا بانفسهم عن نفسه ذلك بانهم لا يصيبهم ظما ولا نصب ولا مخمصة في سبيل الله ولا يطئون موطئا يغيظ الكفار ولا ينالون من عدو نيلا الا كتب لهم به عمل صالح ان الله لا يضيع اجر المحسنين',
    'مَا كَانَ لِأَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ وَمَنۡ حَوۡلَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَخَلَّفُو<rule class=slnt>اۡ</rule> ع<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا يَرۡغَبُو<rule class=slnt>اۡ</rule> بِأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ لَا يُصِيبُهُمۡ ظَمَ<rule class=idgham_ghunnah>أٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصَ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا مَخۡمَصَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا يَطَــُٔونَ مَوۡطِ<rule class=idgham_ghunnah>ئًا</rule> <rule class=idgham_ghunnah>ي</rule>َغِيظُ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارَ وَلَا يَنَالُونَ مِنۡ عَدُ<rule class=idgham_ghunnah>وٍّ</rule> <rule class=idgham_ghunnah>ن</rule>َّيۡلاً إِلَّا كُتِبَ لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> عَمَ<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ص</rule>َ<rule class=madda_normal>ـٰ</rule>لِحٌ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُضِيعُ أَ<rule class=qalaqah>جۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٢٠',
    120, 11, 2, 206, 170, 82, 'false'
  );
  
  -- Ayah 121 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1356,
    'وَلَا یُنفِقُونَ نَفَقَةࣰ صَغِیرَةࣰ وَلَا كَبِیرَةࣰ وَلَا یَقۡطَعُونَ وَادِیًا إِلَّا كُتِبَ لَهُمۡ لِیَجۡزِیَهُمُ ٱللَّهُ أَحۡسَنَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'ولا ينفقون نفقة صغيرة ولا كبيرة ولا يقطعون واديا الا كتب لهم ليجزيهم الله احسن ما كانوا يعملون',
    'وَلَا يُ<rule class=ikhafa>نف</rule>ِقُونَ نَفَقَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ص</rule>َغِيرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا كَبِيرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَ<rule class=qalaqah>قۡ</rule>طَعُونَ وَادِيًا إِلَّا كُتِبَ لَهُمۡ لِيَ<rule class=qalaqah>جۡ</rule>زِيَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ أَحۡسَنَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٢١',
    121, 11, 2, 206, 170, 82, 'false'
  );
  
  -- Ayah 122 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1357,
    '۞ وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِیَنفِرُوا۟ كَاۤفَّةࣰۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةࣲ مِّنۡهُمۡ طَاۤىِٕفَةࣱ لِّیَتَفَقَّهُوا۟ فِی ٱلدِّینِ وَلِیُنذِرُوا۟ قَوۡمَهُمۡ إِذَا رَجَعُوۤا۟ إِلَیۡهِمۡ لَعَلَّهُمۡ یَحۡذَرُونَ',
    'وما كان المؤمنون لينفروا كافة فلولا نفر من كل فرقة منهم طائفة ليتفقهوا في الدين ولينذروا قومهم اذا رجعوا اليهم لعلهم يحذرون',
    '۞وَمَا كَانَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ لِيَ<rule class=ikhafa>نف</rule>ِرُو<rule class=slnt>اۡ</rule> ك<rule class=madda_necessary>َا</rule>ٓفَّ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ف</rule>َلَوۡلَا نَفَرَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ فِرۡقَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَتَفَقَّهُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ وَلِيُ<rule class=ikhafa>نذ</rule>ِرُو<rule class=slnt>اۡ</rule> قَوۡمَهُمۡ إِذَا رَجَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِمۡ لَعَلَّهُمۡ يَحۡذَر<rule class=madda_permissible>ُو</rule>نَ ١٢٢',
    122, 11, 2, 206, 170, 83, 'false'
  );
  
  -- Ayah 123 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1358,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ قَـٰتِلُوا۟ ٱلَّذِینَ یَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡیَجِدُوا۟ فِیكُمۡ غِلۡظَةࣰۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِینَ',
    'يا ايها الذين امنوا قاتلوا الذين يلونكم من الكفار وليجدوا فيكم غلظة واعلموا ان الله مع المتقين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> قَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَلُونَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارِ وَلۡيَجِدُو<rule class=slnt>اۡ</rule> فِيكُمۡ غِلۡظَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَعَ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ١٢٣',
    123, 11, 2, 207, 171, 83, 'false'
  );
  
  -- Ayah 124 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1359,
    'وَإِذَا مَاۤ أُنزِلَتۡ سُورَةࣱ فَمِنۡهُم مَّن یَقُولُ أَیُّكُمۡ زَادَتۡهُ هَـٰذِهِۦۤ إِیمَـٰنࣰاۚ فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ فَزَادَتۡهُمۡ إِیمَـٰنࣰا وَهُمۡ یَسۡتَبۡشِرُونَ',
    'واذا ما انزلت سورة فمنهم من يقول ايكم زادته هذه ايمانا فاما الذين امنوا فزادتهم ايمانا وهم يستبشرون',
    'وَإِذَا م<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَتۡ سُورَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُ أَيُّكُمۡ زَادَتۡهُ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِيمَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> فَزَادَتۡهُمۡ إِيمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ يَسۡتَ<rule class=qalaqah>بۡ</rule>شِر<rule class=madda_permissible>ُو</rule>نَ ١٢٤',
    124, 11, 2, 207, 171, 83, 'false'
  );
  
  -- Ayah 125 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1360,
    'وَأَمَّا ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ وَمَاتُوا۟ وَهُمۡ كَـٰفِرُونَ',
    'واما الذين في قلوبهم مرض فزادتهم رجسا الى رجسهم وماتوا وهم كافرون',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَ<rule class=ikhafa>ضٌ</rule> <rule class=ikhafa>ف</rule>َزَادَتۡهُمۡ رِ<rule class=qalaqah>جۡ</rule>سًا إِلَىٰ رِ<rule class=qalaqah>جۡ</rule>سِهِمۡ وَمَاتُو<rule class=slnt>اۡ</rule> وَهُمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ١٢٥',
    125, 11, 2, 207, 171, 83, 'false'
  );
  
  -- Ayah 126 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1361,
    'أَوَلَا یَرَوۡنَ أَنَّهُمۡ یُفۡتَنُونَ فِی كُلِّ عَامࣲ مَّرَّةً أَوۡ مَرَّتَیۡنِ ثُمَّ لَا یَتُوبُونَ وَلَا هُمۡ یَذَّكَّرُونَ',
    'اولا يرون انهم يفتنون في كل عام مرة او مرتين ثم لا يتوبون ولا هم يذكرون',
    'أَوَلَا يَرَوۡنَ أَ<rule class=ghunnah>نّ</rule>َهُمۡ يُفۡتَنُونَ فِى كُلِّ عَا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>َّرَّةً أَوۡ مَرَّتَيۡنِ ثُ<rule class=ghunnah>مّ</rule>َ لَا يَتُوبُونَ وَلَا هُمۡ يَذَّكَّر<rule class=madda_permissible>ُو</rule>نَ ١٢٦',
    126, 11, 2, 207, 171, 83, 'false'
  );
  
  -- Ayah 127 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1362,
    'وَإِذَا مَاۤ أُنزِلَتۡ سُورَةࣱ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ یَرَىٰكُم مِّنۡ أَحَدࣲ ثُمَّ ٱنصَرَفُوا۟ۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمࣱ لَّا یَفۡقَهُونَ',
    'واذا ما انزلت سورة نظر بعضهم الى بعض هل يراكم من احد ثم انصرفوا صرف الله قلوبهم بانهم قوم لا يفقهون',
    'وَإِذَا م<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَتۡ سُورَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ن</rule>َّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ يَرَ<rule class=madda_normal>ٮٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَحَ<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نص</rule>َرَفُو<rule class=slnt>اۡ‌ۚ</rule> صَرَفَ <rule class=ham_wasl>ٱ</rule>للَّهُ قُلُوبَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَفۡقَه<rule class=madda_permissible>ُو</rule>نَ ١٢٧',
    127, 11, 2, 207, 171, 83, 'false'
  );
  
  -- Ayah 128 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1363,
    'لَقَدۡ جَاۤءَكُمۡ رَسُولࣱ مِّنۡ أَنفُسِكُمۡ عَزِیزٌ عَلَیۡهِ مَا عَنِتُّمۡ حَرِیصٌ عَلَیۡكُم بِٱلۡمُؤۡمِنِینَ رَءُوفࣱ رَّحِیمࣱ',
    'لقد جاءكم رسول من انفسكم عزيز عليه ما عنتم حريص عليكم بالمؤمنين رءوف رحيم',
    'لَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ رَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٢٨',
    128, 11, 2, 207, 171, 83, 'false'
  );
  
  -- Ayah 129 Surah At-Tawba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    9,
    1364,
    'فَإِن تَوَلَّوۡا۟ فَقُلۡ حَسۡبِیَ ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ عَلَیۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِیمِ',
    'فان تولوا فقل حسبي الله لا اله الا هو عليه توكلت وهو رب العرش العظيم',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَقُلۡ حَسۡبِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۖ عَلَيۡهِ تَوَكَّلۡتُ‌ۖ وَهُوَ رَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ١٢٩',
    129, 11, 2, 207, 171, 83, 'false'
  );
  

-- Surah Yunus
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (10, 'سُورَةُ يُونُسَ', 'Yunus', 'Jonas', 'Meccan', 109);

  -- Ayah 1 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1365,
    'الۤرۚ تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡحَكِیمِ',
    'الر تلك ايات الكتاب الحكيم',
    'ا<rule class=madda_necessary>لٓ</rule>ر‌ۚ تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ١',
    1, 11, 3, 208, 172, 83, 'false'
  );
  
  -- Ayah 2 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1366,
    'أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ أَوۡحَیۡنَاۤ إِلَىٰ رَجُلࣲ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِینَ ءَامَنُوۤا۟ أَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَـٰفِرُونَ إِنَّ هَـٰذَا لَسَـٰحِرࣱ مُّبِینٌ',
    'اكان للناس عجبا ان اوحينا الى رجل منهم ان انذر الناس وبشر الذين امنوا ان لهم قدم صدق عند ربهم قال الكافرون ان هذا لساحر مبين',
    'أَكَانَ لِل<rule class=ghunnah>نّ</rule>َاسِ عَجَبًا أَنۡ أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ رَجُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ أَنۡ أَ<rule class=ikhafa>نذ</rule>ِرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ لَهُمۡ قَدَمَ صِ<rule class=qalaqah>دۡ</rule>قٍ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ‌ۗ قَالَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرُونَ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَسَ<rule class=madda_normal>ـٰ</rule>حِ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٢',
    2, 11, 3, 208, 172, 83, 'false'
  );
  
  -- Ayah 3 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1367,
    'إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ یُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِیعٍ إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَ ٰ⁠لِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ',
    'ان ربكم الله الذي خلق السماوات والارض في ستة ايام ثم استوى على العرش يدبر الامر ما من شفيع الا من بعد اذنه ذلكم الله ربكم فاعبدوه افلا تذكرون',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فِى سِتَّةِ أَيَّا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ‌ۖ يُدَبِّرُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرَ‌ۖ مَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َفِيعٍ إِلَّا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ إِذۡنِه<rule class=madda_normal>ِۦ</rule>‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡبُدُوهُ‌ۚ أَفَلَا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 11, 3, 208, 172, 83, 'false'
  );
  
  -- Ayah 4 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1368,
    'إِلَیۡهِ مَرۡجِعُكُمۡ جَمِیعࣰاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ لِیَجۡزِیَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ بِٱلۡقِسۡطِۚ وَٱلَّذِینَ كَفَرُوا۟ لَهُمۡ شَرَابࣱ مِّنۡ حَمِیمࣲ وَعَذَابٌ أَلِیمُۢ بِمَا كَانُوا۟ یَكۡفُرُونَ',
    'اليه مرجعكم جميعا وعد الله حقا انه يبدا الخلق ثم يعيده ليجزي الذين امنوا وعملوا الصالحات بالقسط والذين كفروا لهم شراب من حميم وعذاب اليم بما كانوا يكفرون',
    'إِلَيۡهِ مَرۡجِعُكُمۡ جَمِي<rule class=idgham_ghunnah>عًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَقًّا‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَ<rule class=qalaqah>بۡ</rule>دَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَلۡقَ ثُ<rule class=ghunnah>مّ</rule>َ يُعِيدُهُ<rule class=madda_normal>ۥ</rule> لِيَ<rule class=qalaqah>جۡ</rule>زِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَهُمۡ شَرَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ حَمِي<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَذَابٌ أَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 11, 3, 208, 172, 83, 'false'
  );
  
  -- Ayah 5 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1369,
    'هُوَ ٱلَّذِی جَعَلَ ٱلشَّمۡسَ ضِیَاۤءࣰ وَٱلۡقَمَرَ نُورࣰا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُوا۟ عَدَدَ ٱلسِّنِینَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَ ٰ⁠لِكَ إِلَّا بِٱلۡحَقِّۚ یُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡلَمُونَ',
    'هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب ما خلق الله ذلك الا بالحق يفصل الايات لقوم يعلمون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ ضِي<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ نُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َقَدَّرَهُ<rule class=madda_normal>ۥ</rule> مَنَازِلَ لِتَعۡلَمُو<rule class=slnt>اۡ</rule> عَدَدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِسَابَ‌ۚ مَا خَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ ذ<rule class=madda_normal>ٰ</rule>لِكَ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ يُفَصِّلُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 11, 3, 208, 172, 83, 'false'
  );
  
  -- Ayah 6 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1370,
    'إِنَّ فِی ٱخۡتِلَـٰفِ ٱلَّیۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَّقُونَ',
    'ان في اختلاف الليل والنهار وما خلق الله في السماوات والارض لايات لقوم يتقون',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى <rule class=ham_wasl>ٱ</rule>خۡتِلَ<rule class=madda_normal>ـٰ</rule>فِ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَمَا خَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَّق<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 11, 3, 208, 172, 83, 'false'
  );
  
  -- Ayah 7 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1371,
    'إِنَّ ٱلَّذِینَ لَا یَرۡجُونَ لِقَاۤءَنَا وَرَضُوا۟ بِٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَٱطۡمَأَنُّوا۟ بِهَا وَٱلَّذِینَ هُمۡ عَنۡ ءَایَـٰتِنَا غَـٰفِلُونَ',
    'ان الذين لا يرجون لقاءنا ورضوا بالحياة الدنيا واطمانوا بها والذين هم عن اياتنا غافلون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَرۡجُونَ لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا وَرَضُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>طۡ</rule>مَأَ<rule class=ghunnah>نّ</rule>ُو<rule class=slnt>اۡ</rule> بِهَا وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ عَنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 11, 3, 209, 172, 83, 'false'
  );
  
  -- Ayah 8 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1372,
    'أُو۟لَـٰۤىِٕكَ مَأۡوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ یَكۡسِبُونَ',
    'اولئك ماواهم النار بما كانوا يكسبون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 11, 3, 209, 172, 83, 'false'
  );
  
  -- Ayah 9 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1373,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ یَهۡدِیهِمۡ رَبُّهُم بِإِیمَـٰنِهِمۡۖ تَجۡرِی مِن تَحۡتِهِمُ ٱلۡأَنۡهَـٰرُ فِی جَنَّـٰتِ ٱلنَّعِیمِ',
    'ان الذين امنوا وعملوا الصالحات يهديهم ربهم بايمانهم تجري من تحتهم الانهار في جنات النعيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ يَهۡدِيهِمۡ رَبُّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِإِيمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ‌ۖ تَ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َع<rule class=madda_permissible>ِي</rule>مِ ٩',
    9, 11, 3, 209, 172, 83, 'false'
  );
  
  -- Ayah 10 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1374,
    'دَعۡوَىٰهُمۡ فِیهَا سُبۡحَـٰنَكَ ٱللَّهُمَّ وَتَحِیَّتُهُمۡ فِیهَا سَلَـٰمࣱۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'دعواهم فيها سبحانك اللهم وتحيتهم فيها سلام واخر دعواهم ان الحمد لله رب العالمين',
    'دَعۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ فِيهَا سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّهُ<rule class=ghunnah>مّ</rule>َ وَتَحِيَّتُهُمۡ فِيهَا سَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َءَاخِرُ دَعۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ أَنِ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 11, 3, 209, 172, 83, 'false'
  );
  
  -- Ayah 11 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1375,
    '۞ وَلَوۡ یُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسۡتِعۡجَالَهُم بِٱلۡخَیۡرِ لَقُضِیَ إِلَیۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِینَ لَا یَرۡجُونَ لِقَاۤءَنَا فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ',
    'ولو يعجل الله للناس الشر استعجالهم بالخير لقضي اليهم اجلهم فنذر الذين لا يرجون لقاءنا في طغيانهم يعمهون',
    '۞وَلَوۡ يُعَجِّلُ <rule class=ham_wasl>ٱ</rule>للَّهُ لِل<rule class=ghunnah>نّ</rule>َاسِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّرَّ <rule class=ham_wasl>ٱ</rule>سۡتِعۡجَالَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ لَقُضِىَ إِلَيۡهِمۡ أَجَلُهُمۡ‌ۖ فَنَذَرُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَرۡجُونَ لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا فِى طُغۡيَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ يَعۡمَه<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 11, 3, 209, 173, 84, 'false'
  );
  
  -- Ayah 12 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1376,
    'وَإِذَا مَسَّ ٱلۡإِنسَـٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦۤ أَوۡ قَاعِدًا أَوۡ قَاۤىِٕمࣰا فَلَمَّا كَشَفۡنَا عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ یَدۡعُنَاۤ إِلَىٰ ضُرࣲّ مَّسَّهُۥۚ كَذَ ٰ⁠لِكَ زُیِّنَ لِلۡمُسۡرِفِینَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'واذا مس الانسان الضر دعانا لجنبه او قاعدا او قائما فلما كشفنا عنه ضره مر كان لم يدعنا الى ضر مسه كذلك زين للمسرفين ما كانوا يعملون',
    'وَإِذَا مَسَّ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّرُّ دَعَانَا لِجَ<rule class=iqlab>نۢب</rule>ِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡ قَاعِدًا أَوۡ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َلَ<rule class=ghunnah>مّ</rule>َا كَشَفۡنَا عَنۡهُ ضُرَّهُ<rule class=madda_normal>ۥ</rule> مَرَّ كَأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَ<rule class=qalaqah>دۡ</rule>عُن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ ضُ<rule class=idgham_ghunnah>رٍّ</rule> <rule class=idgham_ghunnah>م</rule>َّسَّهُ<rule class=madda_normal>ۥ</rule>‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ زُيِّنَ لِلۡمُسۡرِفِينَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 11, 3, 209, 173, 84, 'false'
  );
  
  -- Ayah 13 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1377,
    'وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ مِن قَبۡلِكُمۡ لَمَّا ظَلَمُوا۟ وَجَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ وَمَا كَانُوا۟ لِیُؤۡمِنُوا۟ۚ كَذَ ٰ⁠لِكَ نَجۡزِی ٱلۡقَوۡمَ ٱلۡمُجۡرِمِینَ',
    'ولقد اهلكنا القرون من قبلكم لما ظلموا وجاءتهم رسلهم بالبينات وما كانوا ليؤمنوا كذلك نجزي القوم المجرمين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَهۡلَكۡنَا <rule class=ham_wasl>ٱ</rule>لۡقُرُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ لَ<rule class=ghunnah>مّ</rule>َا ظَلَمُو<rule class=slnt>اۡ‌ۙ</rule> وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَمَا كَانُو<rule class=slnt>اۡ</rule> لِيُؤۡمِنُو<rule class=slnt>اۡ‌ۚ</rule> كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 11, 3, 209, 173, 84, 'false'
  );
  
  -- Ayah 14 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1378,
    'ثُمَّ جَعَلۡنَـٰكُمۡ خَلَـٰۤىِٕفَ فِی ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَیۡفَ تَعۡمَلُونَ',
    'ثم جعلناكم خلائف في الارض من بعدهم لننظر كيف تعملون',
    'ثُ<rule class=ghunnah>مّ</rule>َ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ خَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِفَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ لِنَ<rule class=ikhafa>نظ</rule>ُرَ كَيۡفَ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 11, 3, 209, 173, 84, 'false'
  );
  
  -- Ayah 15 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1379,
    'وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَاتُنَا بَیِّنَـٰتࣲ قَالَ ٱلَّذِینَ لَا یَرۡجُونَ لِقَاۤءَنَا ٱئۡتِ بِقُرۡءَانٍ غَیۡرِ هَـٰذَاۤ أَوۡ بَدِّلۡهُۚ قُلۡ مَا یَكُونُ لِیۤ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَاۤىِٕ نَفۡسِیۤۖ إِنۡ أَتَّبِعُ إِلَّا مَا یُوحَىٰۤ إِلَیَّۖ إِنِّیۤ أَخَافُ إِنۡ عَصَیۡتُ رَبِّی عَذَابَ یَوۡمٍ عَظِیمࣲ',
    'واذا تتلى عليهم اياتنا بينات قال الذين لا يرجون لقاءنا ائت بقران غير هذا او بدله قل ما يكون لي ان ابدله من تلقاء نفسي ان اتبع الا ما يوحى الي اني اخاف ان عصيت ربي عذاب يوم عظيم',
    'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَاتُنَا بَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ‌ۙ</rule> <rule class=ikhafa>ق</rule>َالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَرۡجُونَ لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا <rule class=ham_wasl>ٱ</rule>ئۡتِ بِقُرۡءَانٍ غَيۡرِ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ بَدِّلۡهُ‌ۚ قُلۡ مَا يَكُونُ ل<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡ أُبَدِّلَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ِلۡقَآىِٕ نَفۡس<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىَّ‌ۖ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ إِنۡ عَصَيۡتُ رَبِّى عَذَابَ يَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ١٥',
    15, 11, 3, 210, 173, 84, 'false'
  );
  
  -- Ayah 16 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1380,
    'قُل لَّوۡ شَاۤءَ ٱللَّهُ مَا تَلَوۡتُهُۥ عَلَیۡكُمۡ وَلَاۤ أَدۡرَىٰكُم بِهِۦۖ فَقَدۡ لَبِثۡتُ فِیكُمۡ عُمُرࣰا مِّن قَبۡلِهِۦۤۚ أَفَلَا تَعۡقِلُونَ',
    'قل لو شاء الله ما تلوته عليكم ولا ادراكم به فقد لبثت فيكم عمرا من قبله افلا تعقلون',
    'قُل لَّوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا تَلَوۡتُهُ<rule class=madda_normal>ۥ</rule> عَلَيۡكُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَقَ<rule class=qalaqah>دۡ</rule> لَبِثۡتُ فِيكُمۡ عُمُ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 11, 3, 210, 173, 84, 'false'
  );
  
  -- Ayah 17 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1381,
    'فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔایَـٰتِهِۦۤۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلۡمُجۡرِمُونَ',
    'فمن اظلم ممن افترى على الله كذبا او كذب باياته انه لا يفلح المجرمون',
    'فَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 11, 3, 210, 173, 84, 'false'
  );
  
  -- Ayah 18 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1382,
    'وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَضُرُّهُمۡ وَلَا یَنفَعُهُمۡ وَیَقُولُونَ هَـٰۤؤُلَاۤءِ شُفَعَـٰۤؤُنَا عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا یَعۡلَمُ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَلَا فِی ٱلۡأَرۡضِۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ',
    'ويعبدون من دون الله ما لا يضرهم ولا ينفعهم ويقولون هؤلاء شفعاؤنا عند الله قل اتنبئون الله بما لا يعلم في السماوات ولا في الارض سبحانه وتعالى عما يشركون',
    'وَيَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَضُرُّهُمۡ وَلَا يَ<rule class=ikhafa>نف</rule>َعُهُمۡ وَيَقُولُونَ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ شُفَعَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُنَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ قُلۡ أَتُنَبِّــُٔونَ <rule class=ham_wasl>ٱ</rule>للَّهَ بِمَا لَا يَعۡلَمُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَلَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> وَتَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 11, 3, 210, 173, 84, 'false'
  );
  
  -- Ayah 19 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1383,
    'وَمَا كَانَ ٱلنَّاسُ إِلَّاۤ أُمَّةࣰ وَ ٰ⁠حِدَةࣰ فَٱخۡتَلَفُوا۟ۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَقُضِیَ بَیۡنَهُمۡ فِیمَا فِیهِ یَخۡتَلِفُونَ',
    'وما كان الناس الا امة واحدة فاختلفوا ولولا كلمة سبقت من ربك لقضي بينهم فيما فيه يختلفون',
    'وَمَا كَانَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ‌ۚ</rule> وَلَوۡلَا كَلِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>س</rule>َبَقَتۡ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ لَقُضِىَ بَيۡنَهُمۡ فِيمَا فِيهِ يَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 11, 3, 210, 173, 84, 'false'
  );
  
  -- Ayah 20 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1384,
    'وَیَقُولُونَ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَةࣱ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَیۡبُ لِلَّهِ فَٱنتَظِرُوۤا۟ إِنِّی مَعَكُم مِّنَ ٱلۡمُنتَظِرِینَ',
    'ويقولون لولا انزل عليه اية من ربه فقل انما الغيب لله فانتظروا اني معكم من المنتظرين',
    'وَيَقُولُونَ لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡهِ ءَايَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule>‌ۖ فَقُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡغَيۡبُ لِلَّهِ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َظِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>ِى مَعَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نت</rule>َظِر<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 11, 3, 210, 173, 84, 'false'
  );
  
  -- Ayah 21 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1385,
    'وَإِذَاۤ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةࣰ مِّنۢ بَعۡدِ ضَرَّاۤءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرࣱ فِیۤ ءَایَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا یَكۡتُبُونَ مَا تَمۡكُرُونَ',
    'واذا اذقنا الناس رحمة من بعد ضراء مستهم اذا لهم مكر في اياتنا قل الله اسرع مكرا ان رسلنا يكتبون ما تمكرون',
    'وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَذَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ضَرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَسَّتۡهُمۡ إِذَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّكۡ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَاتِنَا‌ۚ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ أَسۡرَعُ مَكۡرًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رُسُلَنَا يَكۡتُبُونَ مَا تَمۡكُر<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 11, 3, 211, 174, 84, 'false'
  );
  
  -- Ayah 22 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1386,
    'هُوَ ٱلَّذِی یُسَیِّرُكُمۡ فِی ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰۤ إِذَا كُنتُمۡ فِی ٱلۡفُلۡكِ وَجَرَیۡنَ بِهِم بِرِیحࣲ طَیِّبَةࣲ وَفَرِحُوا۟ بِهَا جَاۤءَتۡهَا رِیحٌ عَاصِفࣱ وَجَاۤءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانࣲ وَظَنُّوۤا۟ أَنَّهُمۡ أُحِیطَ بِهِمۡ دَعَوُا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ لَىِٕنۡ أَنجَیۡتَنَا مِنۡ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِینَ',
    'هو الذي يسيركم في البر والبحر حتى اذا كنتم في الفلك وجرين بهم بريح طيبة وفرحوا بها جاءتها ريح عاصف وجاءهم الموج من كل مكان وظنوا انهم احيط بهم دعوا الله مخلصين له الدين لئن انجيتنا من هذه لنكونن من الشاكرين',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُسَيِّرُكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡبَرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا كُ<rule class=ikhafa>نت</rule>ُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ وَجَرَيۡنَ بِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرِي<rule class=ikhafa>حٍ</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َفَرِحُو<rule class=slnt>اۡ</rule> بِهَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهَا رِيحٌ عَاصِ<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>و</rule>َج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡجُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مَكَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َظَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ أُحِيطَ بِهِمۡ‌ۙ دَعَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡلِصِينَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ لَئِنۡ أَ<rule class=ikhafa>نج</rule>َيۡتَنَا مِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> لَنَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ٢٢',
    22, 11, 3, 211, 174, 84, 'false'
  );
  
  -- Ayah 23 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1387,
    'فَلَمَّاۤ أَنجَىٰهُمۡ إِذَا هُمۡ یَبۡغُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّۗ یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّمَا بَغۡیُكُمۡ عَلَىٰۤ أَنفُسِكُمۖ مَّتَـٰعَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ ثُمَّ إِلَیۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'فلما انجاهم اذا هم يبغون في الارض بغير الحق يا ايها الناس انما بغيكم على انفسكم متاع الحياة الدنيا ثم الينا مرجعكم فننبئكم بما كنتم تعملون',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نج</rule>َ<rule class=madda_normal>ـٰ</rule>هُمۡ إِذَا هُمۡ يَ<rule class=qalaqah>بۡ</rule>غُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۗ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِ<rule class=ghunnah>نّ</rule>َمَا بَغۡيُكُمۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِك<rule class=idgham_shafawi>ُم‌ۖ</rule> <rule class=idgham_shafawi>م</rule>َّتَ<rule class=madda_normal>ـٰ</rule>عَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ إِلَيۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 11, 3, 211, 174, 84, 'false'
  );
  
  -- Ayah 24 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1388,
    'إِنَّمَا مَثَلُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا كَمَاۤءٍ أَنزَلۡنَـٰهُ مِنَ ٱلسَّمَاۤءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا یَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَـٰمُ حَتَّىٰۤ إِذَاۤ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّیَّنَتۡ وَظَنَّ أَهۡلُهَاۤ أَنَّهُمۡ قَـٰدِرُونَ عَلَیۡهَاۤ أَتَىٰهَاۤ أَمۡرُنَا لَیۡلًا أَوۡ نَهَارࣰا فَجَعَلۡنَـٰهَا حَصِیدࣰا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ كَذَ ٰ⁠لِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَتَفَكَّرُونَ',
    'انما مثل الحياة الدنيا كماء انزلناه من السماء فاختلط به نبات الارض مما ياكل الناس والانعام حتى اذا اخذت الارض زخرفها وازينت وظن اهلها انهم قادرون عليها اتاها امرنا ليلا او نهارا فجعلناها حصيدا كان لم تغن بالامس كذلك نفصل الايات لقوم يتفكرون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا مَثَلُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا كَم<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَ<rule class=ham_wasl>ٱ</rule>خۡتَلَطَ بِه<rule class=madda_normal>ِۦ</rule> نَبَاتُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مِ<rule class=ghunnah>مّ</rule>َا يَأۡكُلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مُ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَخَذَتِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ زُخۡرُفَهَا وَ<rule class=ham_wasl>ٱ</rule>زَّيَّنَتۡ وَظَ<rule class=ghunnah>نّ</rule>َ أَهۡلُه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ قَ<rule class=madda_normal>ـٰ</rule>دِرُونَ عَلَيۡه<rule class=madda_obligatory_monfasel>َآ</rule> أَتَ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡرُنَا لَيۡلاً أَوۡ نَهَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هَا حَصِي<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ك</rule>َأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَغۡنَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَمۡسِ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نُفَصِّلُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 11, 3, 211, 174, 84, 'false'
  );
  
  -- Ayah 25 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1389,
    'وَٱللَّهُ یَدۡعُوۤا۟ إِلَىٰ دَارِ ٱلسَّلَـٰمِ وَیَهۡدِی مَن یَشَاۤءُ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'والله يدعو الى دار السلام ويهدي من يشاء الى صراط مستقيم',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=qalaqah>دۡ</rule>ع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ دَارِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَ<rule class=madda_normal>ـٰ</rule>مِ وَيَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٢٥',
    25, 11, 3, 211, 174, 84, 'false'
  );
  
  -- Ayah 26 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1390,
    '۞ لِّلَّذِینَ أَحۡسَنُوا۟ ٱلۡحُسۡنَىٰ وَزِیَادَةࣱۖ وَلَا یَرۡهَقُ وُجُوهَهُمۡ قَتَرࣱ وَلَا ذِلَّةٌۚ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'للذين احسنوا الحسنى وزيادة ولا يرهق وجوههم قتر ولا ذلة اولئك اصحاب الجنة هم فيها خالدون',
    '۞لِّلَّذِينَ أَحۡسَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ وَزِيَادَ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَرۡهَقُ وُجُوهَهُمۡ قَتَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا ذِلَّةٌ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 11, 3, 212, 174, 85, 'false'
  );
  
  -- Ayah 27 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1391,
    'وَٱلَّذِینَ كَسَبُوا۟ ٱلسَّیِّـَٔاتِ جَزَاۤءُ سَیِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةࣱۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنۡ عَاصِمࣲۖ كَأَنَّمَاۤ أُغۡشِیَتۡ وُجُوهُهُمۡ قِطَعࣰا مِّنَ ٱلَّیۡلِ مُظۡلِمًاۚ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'والذين كسبوا السيئات جزاء سيئة بمثلها وترهقهم ذلة ما لهم من الله من عاصم كانما اغشيت وجوههم قطعا من الليل مظلما اولئك اصحاب النار هم فيها خالدون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَسَبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ سَيِّئَ<rule class=iqlab>ةِۭ</rule> <rule class=iqlab>ب</rule>ِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>م</rule>َّا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مِنۡ عَاصِ<rule class=ikhafa>مٍ‌ۖ</rule> <rule class=ikhafa>ك</rule>َأَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُغۡشِيَتۡ وُجُوهُهُمۡ قِطَ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ مُظۡلِمًا‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 11, 3, 212, 174, 85, 'false'
  );
  
  -- Ayah 28 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1392,
    'وَیَوۡمَ نَحۡشُرُهُمۡ جَمِیعࣰا ثُمَّ نَقُولُ لِلَّذِینَ أَشۡرَكُوا۟ مَكَانَكُمۡ أَنتُمۡ وَشُرَكَاۤؤُكُمۡۚ فَزَیَّلۡنَا بَیۡنَهُمۡۖ وَقَالَ شُرَكَاۤؤُهُم مَّا كُنتُمۡ إِیَّانَا تَعۡبُدُونَ',
    'ويوم نحشرهم جميعا ثم نقول للذين اشركوا مكانكم انتم وشركاؤكم فزيلنا بينهم وقال شركاؤهم ما كنتم ايانا تعبدون',
    'وَيَوۡمَ نَحۡشُرُهُمۡ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ نَقُولُ لِلَّذِينَ أَشۡرَكُو<rule class=slnt>اۡ</rule> مَكَانَكُمۡ أَ<rule class=ikhafa>نت</rule>ُمۡ وَشُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ‌ۚ فَزَيَّلۡنَا بَيۡنَهُمۡ‌ۖ وَقَالَ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كُ<rule class=ikhafa>نت</rule>ُمۡ إِيَّانَا تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 11, 3, 212, 174, 85, 'false'
  );
  
  -- Ayah 29 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1393,
    'فَكَفَىٰ بِٱللَّهِ شَهِیدَۢا بَیۡنَنَا وَبَیۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَـٰفِلِینَ',
    'فكفى بالله شهيدا بيننا وبينكم ان كنا عن عبادتكم لغافلين',
    'فَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ شَهِيد<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَنَا وَبَيۡنَكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا عَنۡ عِبَادَتِكُمۡ لَغَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 11, 3, 212, 174, 85, 'false'
  );
  
  -- Ayah 30 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1394,
    'هُنَالِكَ تَبۡلُوا۟ كُلُّ نَفۡسࣲ مَّاۤ أَسۡلَفَتۡۚ وَرُدُّوۤا۟ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۖ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ',
    'هنالك تبلو كل نفس ما اسلفت وردوا الى الله مولاهم الحق وضل عنهم ما كانوا يفترون',
    'هُنَالِكَ تَ<rule class=qalaqah>بۡ</rule>لُو<rule class=slnt>اۡ</rule> كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡلَفَتۡ‌ۚ وَرُدّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَوۡلَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ وَضَلَّ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 11, 3, 212, 174, 85, 'false'
  );
  
  -- Ayah 31 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1395,
    'قُلۡ مَن یَرۡزُقُكُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ أَمَّن یَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَمَن یُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَیُخۡرِجُ ٱلۡمَیِّتَ مِنَ ٱلۡحَیِّ وَمَن یُدَبِّرُ ٱلۡأَمۡرَۚ فَسَیَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ',
    'قل من يرزقكم من السماء والارض امن يملك السمع والابصار ومن يخرج الحي من الميت ويخرج الميت من الحي ومن يدبر الامر فسيقولون الله فقل افلا تتقون',
    'قُلۡ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َرۡزُقُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡلِكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡحَىَّ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَيِّتِ وَيُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡمَيِّتَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَىِّ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُدَبِّرُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرَ‌ۚ فَسَيَقُولُونَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ فَقُلۡ أَفَلَا تَتَّق<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 11, 3, 212, 175, 85, 'false'
  );
  
  -- Ayah 32 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1396,
    'فَذَ ٰ⁠لِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَـٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ',
    'فذلكم الله ربكم الحق فماذا بعد الحق الا الضلال فانى تصرفون',
    'فَذ<rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّكُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۖ فَمَاذَا بَعۡدَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لُ‌ۖ فَأَ<rule class=ghunnah>نّ</rule>َىٰ تُصۡرَف<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 11, 3, 212, 175, 85, 'false'
  );
  
  -- Ayah 33 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1397,
    'كَذَ ٰ⁠لِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِینَ فَسَقُوۤا۟ أَنَّهُمۡ لَا یُؤۡمِنُونَ',
    'كذلك حقت كلمت ربك على الذين فسقوا انهم لا يؤمنون',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ فَسَق<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 11, 3, 212, 175, 85, 'false'
  );
  
  -- Ayah 34 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1398,
    'قُلۡ هَلۡ مِن شُرَكَاۤىِٕكُم مَّن یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥۚ قُلِ ٱللَّهُ یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥۖ فَأَنَّىٰ تُؤۡفَكُونَ',
    'قل هل من شركائكم من يبدا الخلق ثم يعيده قل الله يبدا الخلق ثم يعيده فانى تؤفكون',
    'قُلۡ هَلۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>دَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَلۡقَ ثُ<rule class=ghunnah>مّ</rule>َ يُعِيدُهُ<rule class=madda_normal>ۥ</rule>‌ۚ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=qalaqah>بۡ</rule>دَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَلۡقَ ثُ<rule class=ghunnah>مّ</rule>َ يُعِيدُهُ<rule class=madda_normal>ۥ</rule>‌ۖ فَأَ<rule class=ghunnah>نّ</rule>َىٰ تُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 11, 3, 213, 175, 85, 'false'
  );
  
  -- Ayah 35 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1399,
    'قُلۡ هَلۡ مِن شُرَكَاۤىِٕكُم مَّن یَهۡدِیۤ إِلَى ٱلۡحَقِّۚ قُلِ ٱللَّهُ یَهۡدِی لِلۡحَقِّۗ أَفَمَن یَهۡدِیۤ إِلَى ٱلۡحَقِّ أَحَقُّ أَن یُتَّبَعَ أَمَّن لَّا یَهِدِّیۤ إِلَّاۤ أَن یُهۡدَىٰۖ فَمَا لَكُمۡ كَیۡفَ تَحۡكُمُونَ',
    'قل هل من شركائكم من يهدي الى الحق قل الله يهدي للحق افمن يهدي الى الحق احق ان يتبع امن لا يهدي الا ان يهدى فما لكم كيف تحكمون',
    'قُلۡ هَلۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ يَهۡدِى لِلۡحَقِّ‌ۗ أَفَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡحَقِّ أَحَقُّ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُتَّبَعَ أَ<rule class=ghunnah>مّ</rule><rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَهِدّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُهۡدَىٰ‌ۖ فَمَا لَكُمۡ كَيۡفَ تَحۡكُم<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 11, 3, 213, 175, 85, 'false'
  );
  
  -- Ayah 36 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1400,
    'وَمَا یَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا یُغۡنِی مِنَ ٱلۡحَقِّ شَیۡـًٔاۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِمَا یَفۡعَلُونَ',
    'وما يتبع اكثرهم الا ظنا ان الظن لا يغني من الحق شيئا ان الله عليم بما يفعلون',
    'وَمَا يَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَ<rule class=ghunnah>نّ</rule>ًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>َ لَا يُغۡنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ شَيۡــًٔا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِمَا يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 11, 3, 213, 175, 85, 'false'
  );
  
  -- Ayah 37 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1401,
    'وَمَا كَانَ هَـٰذَا ٱلۡقُرۡءَانُ أَن یُفۡتَرَىٰ مِن دُونِ ٱللَّهِ وَلَـٰكِن تَصۡدِیقَ ٱلَّذِی بَیۡنَ یَدَیۡهِ وَتَفۡصِیلَ ٱلۡكِتَـٰبِ لَا رَیۡبَ فِیهِ مِن رَّبِّ ٱلۡعَـٰلَمِینَ',
    'وما كان هذا القران ان يفترى من دون الله ولكن تصديق الذي بين يديه وتفصيل الكتاب لا ريب فيه من رب العالمين',
    'وَمَا كَانَ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُفۡتَرَىٰ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصۡدِيقَ <rule class=ham_wasl>ٱ</rule>لَّذِى بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَا رَيۡبَ فِيهِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 11, 3, 213, 175, 85, 'false'
  );
  
  -- Ayah 38 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1402,
    'أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُوا۟ بِسُورَةࣲ مِّثۡلِهِۦ وَٱدۡعُوا۟ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ام يقولون افتراه قل فاتوا بسورة مثله وادعوا من استطعتم من دون الله ان كنتم صادقين',
    'أَمۡ يَقُولُونَ <rule class=ham_wasl>ٱ</rule>فۡتَرَ<rule class=madda_normal>ٮٰ</rule>هُ‌ۖ قُلۡ فَأۡتُو<rule class=slnt>اۡ</rule> بِسُورَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> مَنِ <rule class=ham_wasl>ٱ</rule>سۡتَطَعۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٣٨',
    38, 11, 3, 213, 175, 85, 'false'
  );
  
  -- Ayah 39 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1403,
    'بَلۡ كَذَّبُوا۟ بِمَا لَمۡ یُحِیطُوا۟ بِعِلۡمِهِۦ وَلَمَّا یَأۡتِهِمۡ تَأۡوِیلُهُۥۚ كَذَ ٰ⁠لِكَ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِینَ',
    'بل كذبوا بما لم يحيطوا بعلمه ولما ياتهم تاويله كذلك كذب الذين من قبلهم فانظر كيف كان عاقبة الظالمين',
    'بَلۡ كَذَّبُو<rule class=slnt>اۡ</rule> بِمَا لَمۡ يُحِيطُو<rule class=slnt>اۡ</rule> بِعِلۡمِه<rule class=madda_normal>ِۦ</rule> وَلَ<rule class=ghunnah>مّ</rule>َا يَأۡتِهِمۡ تَأۡوِيلُهُ<rule class=madda_normal>ۥ</rule>‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ كَذَّبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٣٩',
    39, 11, 3, 213, 175, 85, 'false'
  );
  
  -- Ayah 40 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1404,
    'وَمِنۡهُم مَّن یُؤۡمِنُ بِهِۦ وَمِنۡهُم مَّن لَّا یُؤۡمِنُ بِهِۦۚ وَرَبُّكَ أَعۡلَمُ بِٱلۡمُفۡسِدِینَ',
    'ومنهم من يؤمن به ومنهم من لا يؤمن به وربك اعلم بالمفسدين',
    'وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُ بِه<rule class=madda_normal>ِۦ</rule> وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِنُ بِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَرَبُّكَ أَعۡلَمُ بِ<rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 11, 3, 213, 175, 85, 'false'
  );
  
  -- Ayah 41 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1405,
    'وَإِن كَذَّبُوكَ فَقُل لِّی عَمَلِی وَلَكُمۡ عَمَلُكُمۡۖ أَنتُم بَرِیۤـُٔونَ مِمَّاۤ أَعۡمَلُ وَأَنَا۠ بَرِیۤءࣱ مِّمَّا تَعۡمَلُونَ',
    'وان كذبوك فقل لي عملي ولكم عملكم انتم بريئون مما اعمل وانا بريء مما تعملون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبُوكَ فَقُل لِّى عَمَلِى وَلَكُمۡ عَمَلُكُمۡ‌ۖ أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َرِ<rule class=madda_obligatory_mottasel>يٓ</rule>ــُٔونَ مِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَعۡمَلُ وَأَنَاۡ بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 11, 3, 213, 176, 85, 'false'
  );
  
  -- Ayah 42 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1406,
    'وَمِنۡهُم مَّن یَسۡتَمِعُونَ إِلَیۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُوا۟ لَا یَعۡقِلُونَ',
    'ومنهم من يستمعون اليك افانت تسمع الصم ولو كانوا لا يعقلون',
    'وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَمِعُونَ إِلَيۡكَ‌ۚ أَفَأَ<rule class=ikhafa>نت</rule>َ تُسۡمِعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّ<rule class=ghunnah>مّ</rule>َ وَلَوۡ كَانُو<rule class=slnt>اۡ</rule> لَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 11, 3, 213, 176, 85, 'false'
  );
  
  -- Ayah 43 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1407,
    'وَمِنۡهُم مَّن یَنظُرُ إِلَیۡكَۚ أَفَأَنتَ تَهۡدِی ٱلۡعُمۡیَ وَلَوۡ كَانُوا۟ لَا یُبۡصِرُونَ',
    'ومنهم من ينظر اليك افانت تهدي العمي ولو كانوا لا يبصرون',
    'وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نظ</rule>ُرُ إِلَيۡكَ‌ۚ أَفَأَ<rule class=ikhafa>نت</rule>َ تَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡعُمۡىَ وَلَوۡ كَانُو<rule class=slnt>اۡ</rule> لَا يُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 44 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1408,
    'إِنَّ ٱللَّهَ لَا یَظۡلِمُ ٱلنَّاسَ شَیۡـࣰٔا وَلَـٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'ان الله لا يظلم الناس شيئا ولكن الناس انفسهم يظلمون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَظۡلِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 45 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1409,
    'وَیَوۡمَ یَحۡشُرُهُمۡ كَأَن لَّمۡ یَلۡبَثُوۤا۟ إِلَّا سَاعَةࣰ مِّنَ ٱلنَّهَارِ یَتَعَارَفُونَ بَیۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِینَ كَذَّبُوا۟ بِلِقَاۤءِ ٱللَّهِ وَمَا كَانُوا۟ مُهۡتَدِینَ',
    'ويوم يحشرهم كان لم يلبثوا الا ساعة من النهار يتعارفون بينهم قد خسر الذين كذبوا بلقاء الله وما كانوا مهتدين',
    'وَيَوۡمَ يَحۡشُرُهُمۡ كَأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَلۡبَث<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا سَاعَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ يَتَعَارَفُونَ بَيۡنَهُمۡ‌ۚ قَ<rule class=qalaqah>دۡ</rule> خَسِرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَا كَانُو<rule class=slnt>اۡ</rule> مُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ٤٥',
    45, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 46 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1410,
    'وَإِمَّا نُرِیَنَّكَ بَعۡضَ ٱلَّذِی نَعِدُهُمۡ أَوۡ نَتَوَفَّیَنَّكَ فَإِلَیۡنَا مَرۡجِعُهُمۡ ثُمَّ ٱللَّهُ شَهِیدٌ عَلَىٰ مَا یَفۡعَلُونَ',
    'واما نرينك بعض الذي نعدهم او نتوفينك فالينا مرجعهم ثم الله شهيد على ما يفعلون',
    'وَإِ<rule class=ghunnah>مّ</rule>َا نُرِيَ<rule class=ghunnah>نّ</rule>َكَ بَعۡضَ <rule class=ham_wasl>ٱ</rule>لَّذِى نَعِدُهُمۡ أَوۡ نَتَوَفَّيَ<rule class=ghunnah>نّ</rule>َكَ فَإِلَيۡنَا مَرۡجِعُهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ شَهِيدٌ عَلَىٰ مَا يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 47 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1411,
    'وَلِكُلِّ أُمَّةࣲ رَّسُولࣱۖ فَإِذَا جَاۤءَ رَسُولُهُمۡ قُضِیَ بَیۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا یُظۡلَمُونَ',
    'ولكل امة رسول فاذا جاء رسولهم قضي بينهم بالقسط وهم لا يظلمون',
    'وَلِكُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُو<rule class=ikhafa>لٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَسُولُهُمۡ قُضِىَ بَيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 48 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1412,
    'وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ويقولون متى هذا الوعد ان كنتم صادقين',
    'وَيَقُولُونَ مَتَىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡوَعۡدُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٤٨',
    48, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 49 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1413,
    'قُل لَّاۤ أَمۡلِكُ لِنَفۡسِی ضَرࣰّا وَلَا نَفۡعًا إِلَّا مَا شَاۤءَ ٱللَّهُۗ لِكُلِّ أُمَّةٍ أَجَلٌۚ إِذَا جَاۤءَ أَجَلُهُمۡ فَلَا یَسۡتَـٔۡخِرُونَ سَاعَةࣰ وَلَا یَسۡتَقۡدِمُونَ',
    'قل لا املك لنفسي ضرا ولا نفعا الا ما شاء الله لكل امة اجل اذا جاء اجلهم فلا يستاخرون ساعة ولا يستقدمون',
    'قُل لّ<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡلِكُ لِنَفۡسِى ضَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَفۡعًا إِلَّا مَا ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ لِكُلِّ أُ<rule class=ghunnah>مّ</rule>َةٍ أَجَلٌ‌ۚ إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَجَلُهُمۡ فَلَا يَسۡتَــٔۡخِرُونَ سَاعَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَسۡتَ<rule class=qalaqah>قۡ</rule>دِم<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 50 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1414,
    'قُلۡ أَرَءَیۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَیَـٰتًا أَوۡ نَهَارࣰا مَّاذَا یَسۡتَعۡجِلُ مِنۡهُ ٱلۡمُجۡرِمُونَ',
    'قل ارايتم ان اتاكم عذابه بياتا او نهارا ماذا يستعجل منه المجرمون',
    'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَتَ<rule class=madda_normal>ـٰ</rule>كُمۡ عَذَابُهُ<rule class=madda_normal>ۥ</rule> بَيَ<rule class=madda_normal>ـٰ</rule>تًا أَوۡ نَهَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>َّاذَا يَسۡتَعۡجِلُ مِنۡهُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 51 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1415,
    'أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦۤۚ ءَاۤلۡـَٔـٰنَ وَقَدۡ كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ',
    'اثم اذا ما وقع امنتم به الان وقد كنتم به تستعجلون',
    'أَثُ<rule class=ghunnah>مّ</rule>َ إِذَا مَا وَقَعَ ءَامَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> ءَ<rule class=madda_necessary>ا</rule>ٓلۡـَٔ<rule class=madda_normal>ـٰ</rule>نَ وَقَ<rule class=qalaqah>دۡ</rule> كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> تَسۡتَعۡجِل<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 52 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1416,
    'ثُمَّ قِیلَ لِلَّذِینَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلۡخُلۡدِ هَلۡ تُجۡزَوۡنَ إِلَّا بِمَا كُنتُمۡ تَكۡسِبُونَ',
    'ثم قيل للذين ظلموا ذوقوا عذاب الخلد هل تجزون الا بما كنتم تكسبون',
    'ثُ<rule class=ghunnah>مّ</rule>َ قِيلَ لِلَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> ذُوقُو<rule class=slnt>اۡ</rule> عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡخُلۡدِ هَلۡ تُ<rule class=qalaqah>جۡ</rule>زَوۡنَ إِلَّا بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 11, 3, 214, 176, 85, 'false'
  );
  
  -- Ayah 53 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1417,
    '۞ وَیَسۡتَنۢبِـُٔونَكَ أَحَقٌّ هُوَۖ قُلۡ إِی وَرَبِّیۤ إِنَّهُۥ لَحَقࣱّۖ وَمَاۤ أَنتُم بِمُعۡجِزِینَ',
    'ويستنبئونك احق هو قل اي وربي انه لحق وما انتم بمعجزين',
    '۞وَيَسۡتَ<rule class=iqlab>نۢب</rule>ِــُٔونَكَ أَحَقٌّ هُوَ‌ۖ قُلۡ إِى وَرَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَحَ<rule class=idgham_ghunnah>قٌّ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُعۡجِز<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 11, 3, 214, 176, 86, 'false'
  );
  
  -- Ayah 54 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1418,
    'وَلَوۡ أَنَّ لِكُلِّ نَفۡسࣲ ظَلَمَتۡ مَا فِی ٱلۡأَرۡضِ لَٱفۡتَدَتۡ بِهِۦۗ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلۡعَذَابَۖ وَقُضِیَ بَیۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا یُظۡلَمُونَ',
    'ولو ان لكل نفس ظلمت ما في الارض لافتدت به واسروا الندامة لما راوا العذاب وقضي بينهم بالقسط وهم لا يظلمون',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َ لِكُلِّ نَفۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ظ</rule>َلَمَتۡ مَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لَ<rule class=ham_wasl>ٱ</rule>فۡتَدَتۡ بِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَأَسَرُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َدَامَةَ لَ<rule class=ghunnah>مّ</rule>َا رَأَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ‌ۖ وَقُضِىَ بَيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۚ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 11, 3, 215, 177, 86, 'false'
  );
  
  -- Ayah 55 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1419,
    'أَلَاۤ إِنَّ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۗ أَلَاۤ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'الا ان لله ما في السماوات والارض الا ان وعد الله حق ولكن اكثرهم لا يعلمون',
    'أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=idgham_ghunnah>قٌّ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 11, 3, 215, 177, 86, 'false'
  );
  
  -- Ayah 56 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1420,
    'هُوَ یُحۡیِۦ وَیُمِیتُ وَإِلَیۡهِ تُرۡجَعُونَ',
    'هو يحيي ويميت واليه ترجعون',
    'هُوَ يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُ وَإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 11, 3, 215, 177, 86, 'false'
  );
  
  -- Ayah 57 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1421,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ قَدۡ جَاۤءَتۡكُم مَّوۡعِظَةࣱ مِّن رَّبِّكُمۡ وَشِفَاۤءࣱ لِّمَا فِی ٱلصُّدُورِ وَهُدࣰى وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِینَ',
    'يا ايها الناس قد جاءتكم موعظة من ربكم وشفاء لما في الصدور وهدى ورحمة للمؤمنين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوۡعِظَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَشِف<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_wo_ghunnah>ءٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّدُورِ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٥٧',
    57, 11, 3, 215, 177, 86, 'false'
  );
  
  -- Ayah 58 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1422,
    'قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَ ٰ⁠لِكَ فَلۡیَفۡرَحُوا۟ هُوَ خَیۡرࣱ مِّمَّا یَجۡمَعُونَ',
    'قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون',
    'قُلۡ بِفَضۡلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَبِرَحۡمَتِه<rule class=madda_normal>ِۦ</rule> فَبِذ<rule class=madda_normal>ٰ</rule>لِكَ فَلۡيَفۡرَحُو<rule class=slnt>اۡ</rule> هُوَ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 11, 3, 215, 177, 86, 'false'
  );
  
  -- Ayah 59 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1423,
    'قُلۡ أَرَءَیۡتُم مَّاۤ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقࣲ فَجَعَلۡتُم مِّنۡهُ حَرَامࣰا وَحَلَـٰلࣰا قُلۡ ءَاۤللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى ٱللَّهِ تَفۡتَرُونَ',
    'قل ارايتم ما انزل الله لكم من رزق فجعلتم منه حراما وحلالا قل الله اذن لكم ام على الله تفترون',
    'قُلۡ أَرَءَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّزۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ف</rule>َجَعَلۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ حَرَا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َحَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ق</rule>ُلۡ ءَآللَّهُ أَذِنَ لَكُمۡ‌ۖ أَمۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 11, 3, 215, 177, 86, 'false'
  );
  
  -- Ayah 60 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1424,
    'وَمَا ظَنُّ ٱلَّذِینَ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ یَوۡمَ ٱلۡقِیَـٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَشۡكُرُونَ',
    'وما ظن الذين يفترون على الله الكذب يوم القيامة ان الله لذو فضل على الناس ولكن اكثرهم لا يشكرون',
    'وَمَا ظَ<rule class=ghunnah>نّ</rule>ُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَفۡتَرُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَذُو فَضۡلٍ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 11, 3, 215, 177, 86, 'false'
  );
  
  -- Ayah 61 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1425,
    'وَمَا تَكُونُ فِی شَأۡنࣲ وَمَا تَتۡلُوا۟ مِنۡهُ مِن قُرۡءَانࣲ وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَیۡكُمۡ شُهُودًا إِذۡ تُفِیضُونَ فِیهِۚ وَمَا یَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةࣲ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِ وَلَاۤ أَصۡغَرَ مِن ذَ ٰ⁠لِكَ وَلَاۤ أَكۡبَرَ إِلَّا فِی كِتَـٰبࣲ مُّبِینٍ',
    'وما تكون في شان وما تتلو منه من قران ولا تعملون من عمل الا كنا عليكم شهودا اذ تفيضون فيه وما يعزب عن ربك من مثقال ذرة في الارض ولا في السماء ولا اصغر من ذلك ولا اكبر الا في كتاب مبين',
    'وَمَا تَكُونُ فِى شَأۡ<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا تَتۡلُو<rule class=slnt>اۡ</rule> مِنۡهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُرۡءَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُ<rule class=ghunnah>نّ</rule>َا عَلَيۡكُمۡ شُهُودًا إِذۡ تُفِيضُونَ فِيهِ‌ۚ وَمَا يَعۡزُبُ ع<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡقَالِ ذَرَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَصۡغَرَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡبَرَ إِلَّا فِى كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٦١',
    61, 11, 3, 215, 178, 86, 'false'
  );
  
  -- Ayah 62 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1426,
    'أَلَاۤ إِنَّ أَوۡلِیَاۤءَ ٱللَّهِ لَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'الا ان اولياء الله لا خوف عليهم ولا هم يحزنون',
    'أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 63 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1427,
    'ٱلَّذِینَ ءَامَنُوا۟ وَكَانُوا۟ یَتَّقُونَ',
    'الذين امنوا وكانوا يتقون',
    'ٱلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَكَانُو<rule class=slnt>اۡ</rule> يَتَّق<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 64 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1428,
    'لَهُمُ ٱلۡبُشۡرَىٰ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَفِی ٱلۡـَٔاخِرَةِۚ لَا تَبۡدِیلَ لِكَلِمَـٰتِ ٱللَّهِۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'لهم البشرى في الحياة الدنيا وفي الاخرة لا تبديل لكلمات الله ذلك هو الفوز العظيم',
    'لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡبُشۡرَىٰ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَفِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۚ لَا تَ<rule class=qalaqah>بۡ</rule>دِيلَ لِكَلِمَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٦٤',
    64, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 65 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1429,
    'وَلَا یَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِیعًاۚ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'ولا يحزنك قولهم ان العزة لله جميعا هو السميع العليم',
    'وَلَا يَحۡزُ<rule class=ikhafa>نك</rule>َ قَوۡلُهُمۡ‌ۘ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعِزَّةَ لِلَّهِ جَمِيعًا‌ۚ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٦٥',
    65, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 66 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1430,
    'أَلَاۤ إِنَّ لِلَّهِ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَن فِی ٱلۡأَرۡضِۗ وَمَا یَتَّبِعُ ٱلَّذِینَ یَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَاۤءَۚ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا یَخۡرُصُونَ',
    'الا ان لله من في السماوات ومن في الارض وما يتبع الذين يدعون من دون الله شركاء ان يتبعون الا الظن وان هم الا يخرصون',
    'أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ لِلَّهِ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَمَا يَتَّبِعُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّبِعُونَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>َ وَإِنۡ هُمۡ إِلَّا يَخۡرُص<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 67 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1431,
    'هُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلَّیۡلَ لِتَسۡكُنُوا۟ فِیهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَسۡمَعُونَ',
    'هو الذي جعل لكم الليل لتسكنوا فيه والنهار مبصرا ان في ذلك لايات لقوم يسمعون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ لِتَسۡكُنُو<rule class=slnt>اۡ</rule> فِيهِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ مُ<rule class=qalaqah>بۡ</rule>صِرًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡمَع<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 68 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1432,
    'قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدࣰاۗ سُبۡحَـٰنَهُۥۖ هُوَ ٱلۡغَنِیُّۖ لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ إِنۡ عِندَكُم مِّن سُلۡطَـٰنِۭ بِهَـٰذَاۤۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ',
    'قالوا اتخذ الله ولدا سبحانه هو الغني له ما في السماوات وما في الارض ان عندكم من سلطان بهذا اتقولون على الله ما لا تعلمون',
    'قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَ<rule class=ikhafa>دًا‌ۗ</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule>‌ۖ هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَنِىُّ‌ۖ لَهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ إِنۡ عِ<rule class=ikhafa>ند</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>نِۭ</rule> <rule class=iqlab>ب</rule>ِهَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أَتَقُولُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 69 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1433,
    'قُلۡ إِنَّ ٱلَّذِینَ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا یُفۡلِحُونَ',
    'قل ان الذين يفترون على الله الكذب لا يفلحون',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَفۡتَرُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ لَا يُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 70 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1434,
    'مَتَـٰعࣱ فِی ٱلدُّنۡیَا ثُمَّ إِلَیۡنَا مَرۡجِعُهُمۡ ثُمَّ نُذِیقُهُمُ ٱلۡعَذَابَ ٱلشَّدِیدَ بِمَا كَانُوا۟ یَكۡفُرُونَ',
    'متاع في الدنيا ثم الينا مرجعهم ثم نذيقهم العذاب الشديد بما كانوا يكفرون',
    'مَتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>عٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا ثُ<rule class=ghunnah>مّ</rule>َ إِلَيۡنَا مَرۡجِعُهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ نُذِيقُهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّدِيدَ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 11, 3, 216, 178, 86, 'false'
  );
  
  -- Ayah 71 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1435,
    '۞ وَٱتۡلُ عَلَیۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ یَـٰقَوۡمِ إِن كَانَ كَبُرَ عَلَیۡكُم مَّقَامِی وَتَذۡكِیرِی بِـَٔایَـٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ فَأَجۡمِعُوۤا۟ أَمۡرَكُمۡ وَشُرَكَاۤءَكُمۡ ثُمَّ لَا یَكُنۡ أَمۡرُكُمۡ عَلَیۡكُمۡ غُمَّةࣰ ثُمَّ ٱقۡضُوۤا۟ إِلَیَّ وَلَا تُنظِرُونِ',
    'واتل عليهم نبا نوح اذ قال لقومه يا قوم ان كان كبر عليكم مقامي وتذكيري بايات الله فعلى الله توكلت فاجمعوا امركم وشركاءكم ثم لا يكن امركم عليكم غمة ثم اقضوا الي ولا تنظرون',
    '۞وَ<rule class=ham_wasl>ٱ</rule>تۡلُ عَلَيۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِه<rule class=madda_normal>ِۦ</rule> يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ كَبُرَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّقَامِى وَتَذۡكِيرِى بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تَوَكَّلۡتُ فَأَ<rule class=qalaqah>جۡ</rule>مِع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرَكُمۡ وَشُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ لَا يَكُنۡ أَمۡرُكُمۡ عَلَيۡكُمۡ غُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>ض<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىَّ وَلَا تُ<rule class=ikhafa>نظ</rule>ِر<rule class=madda_permissible>ُو</rule>نِ ٧١',
    71, 11, 3, 217, 179, 87, 'false'
  );
  
  -- Ayah 72 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1436,
    'فَإِن تَوَلَّیۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِینَ',
    'فان توليتم فما سالتكم من اجر ان اجري الا على الله وامرت ان اكون من المسلمين',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّيۡتُمۡ فَمَا سَأَلۡتُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَ<rule class=qalaqah>جۡ</rule>رٍ‌ۖ إِنۡ أَ<rule class=qalaqah>جۡ</rule>رِىَ إِلَّا عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٧٢',
    72, 11, 3, 217, 179, 87, 'false'
  );
  
  -- Ayah 73 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1437,
    'فَكَذَّبُوهُ فَنَجَّیۡنَـٰهُ وَمَن مَّعَهُۥ فِی ٱلۡفُلۡكِ وَجَعَلۡنَـٰهُمۡ خَلَـٰۤىِٕفَ وَأَغۡرَقۡنَا ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُنذَرِینَ',
    'فكذبوه فنجيناه ومن معه في الفلك وجعلناهم خلائف واغرقنا الذين كذبوا باياتنا فانظر كيف كان عاقبة المنذرين',
    'فَكَذَّبُوهُ فَنَجَّيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ خَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِفَ وَأَغۡرَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نذ</rule>َر<rule class=madda_permissible>ِي</rule>نَ ٧٣',
    73, 11, 3, 217, 179, 87, 'false'
  );
  
  -- Ayah 74 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1438,
    'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَاۤءُوهُم بِٱلۡبَیِّنَـٰتِ فَمَا كَانُوا۟ لِیُؤۡمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبۡلُۚ كَذَ ٰ⁠لِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِینَ',
    'ثم بعثنا من بعده رسلا الى قومهم فجاءوهم بالبينات فما كانوا ليؤمنوا بما كذبوا به من قبل كذلك نطبع على قلوب المعتدين',
    'ثُ<rule class=ghunnah>مّ</rule>َ بَعَثۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> رُسُلاً إِلَىٰ قَوۡمِهِمۡ فَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَمَا كَانُو<rule class=slnt>اۡ</rule> لِيُؤۡمِنُو<rule class=slnt>اۡ</rule> بِمَا كَذَّبُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>طۡ</rule>بَعُ عَلَىٰ قُلُوبِ <rule class=ham_wasl>ٱ</rule>لۡمُعۡتَد<rule class=madda_permissible>ِي</rule>نَ ٧٤',
    74, 11, 3, 217, 179, 87, 'false'
  );
  
  -- Ayah 75 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1439,
    'ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَـٰرُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ بِـَٔایَـٰتِنَا فَٱسۡتَكۡبَرُوا۟ وَكَانُوا۟ قَوۡمࣰا مُّجۡرِمِینَ',
    'ثم بعثنا من بعدهم موسى وهارون الى فرعون وملئه باياتنا فاستكبروا وكانوا قوما مجرمين',
    'ثُ<rule class=ghunnah>مّ</rule>َ بَعَثۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّوسَىٰ وَهَ<rule class=madda_normal>ـٰ</rule>رُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِ<rule class=slnt>يۡ</rule>ه<rule class=madda_normal>ِۦ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> وَكَانُو<rule class=slnt>اۡ</rule> قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٧٥',
    75, 11, 3, 217, 179, 87, 'false'
  );
  
  -- Ayah 76 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1440,
    'فَلَمَّا جَاۤءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوۤا۟ إِنَّ هَـٰذَا لَسِحۡرࣱ مُّبِینࣱ',
    'فلما جاءهم الحق من عندنا قالوا ان هذا لسحر مبين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ مِنۡ عِ<rule class=ikhafa>ند</rule>ِنَا قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَسِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٧٦',
    76, 11, 3, 217, 179, 87, 'false'
  );
  
  -- Ayah 77 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1441,
    'قَالَ مُوسَىٰۤ أَتَقُولُونَ لِلۡحَقِّ لَمَّا جَاۤءَكُمۡۖ أَسِحۡرٌ هَـٰذَا وَلَا یُفۡلِحُ ٱلسَّـٰحِرُونَ',
    'قال موسى اتقولون للحق لما جاءكم اسحر هذا ولا يفلح الساحرون',
    'قَالَ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَتَقُولُونَ لِلۡحَقِّ لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ‌ۖ أَسِحۡرٌ هَ<rule class=madda_normal>ـٰ</rule>ذَا وَلَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>حِر<rule class=madda_permissible>ُو</rule>نَ ٧٧',
    77, 11, 3, 217, 179, 87, 'false'
  );
  
  -- Ayah 78 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1442,
    'قَالُوۤا۟ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَیۡهِ ءَابَاۤءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِیَاۤءُ فِی ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِینَ',
    'قالوا اجئتنا لتلفتنا عما وجدنا عليه اباءنا وتكون لكما الكبرياء في الارض وما نحن لكما بمؤمنين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَجِئۡتَنَا لِتَلۡفِتَنَا عَ<rule class=ghunnah>مّ</rule>َا وَجَ<rule class=qalaqah>دۡ</rule>نَا عَلَيۡهِ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا وَتَكُونَ لَكُمَا <rule class=ham_wasl>ٱ</rule>لۡكِ<rule class=qalaqah>بۡ</rule>رِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٧٨',
    78, 11, 3, 217, 179, 87, 'false'
  );
  
  -- Ayah 79 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1443,
    'وَقَالَ فِرۡعَوۡنُ ٱئۡتُونِی بِكُلِّ سَـٰحِرٍ عَلِیمࣲ',
    'وقال فرعون ائتوني بكل ساحر عليم',
    'وَقَالَ فِرۡعَوۡنُ <rule class=ham_wasl>ٱ</rule>ئۡتُونِى بِكُلِّ سَ<rule class=madda_normal>ـٰ</rule>حِرٍ عَل<rule class=madda_permissible>ِي</rule>مٍ ٧٩',
    79, 11, 3, 218, 179, 87, 'false'
  );
  
  -- Ayah 80 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1444,
    'فَلَمَّا جَاۤءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰۤ أَلۡقُوا۟ مَاۤ أَنتُم مُّلۡقُونَ',
    'فلما جاء السحرة قال لهم موسى القوا ما انتم ملقون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَرَةُ قَالَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَلۡقُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلۡق<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 11, 3, 218, 179, 87, 'false'
  );
  
  -- Ayah 81 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1445,
    'فَلَمَّاۤ أَلۡقَوۡا۟ قَالَ مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَیُبۡطِلُهُۥۤ إِنَّ ٱللَّهَ لَا یُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِینَ',
    'فلما القوا قال موسى ما جئتم به السحر ان الله سيبطله ان الله لا يصلح عمل المفسدين',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَلۡقَوۡ<rule class=slnt>اۡ</rule> قَالَ مُوسَىٰ مَا جِئۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّحۡرُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَيُ<rule class=qalaqah>بۡ</rule>طِلُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُصۡلِحُ عَمَلَ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٨١',
    81, 11, 3, 218, 179, 87, 'false'
  );
  
  -- Ayah 82 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1446,
    'وَیُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَـٰتِهِۦ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ',
    'ويحق الله الحق بكلماته ولو كره المجرمون',
    'وَيُحِقُّ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ بِكَلِمَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَلَوۡ كَرِهَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 11, 3, 218, 179, 87, 'false'
  );
  
  -- Ayah 83 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1447,
    'فَمَاۤ ءَامَنَ لِمُوسَىٰۤ إِلَّا ذُرِّیَّةࣱ مِّن قَوۡمِهِۦ عَلَىٰ خَوۡفࣲ مِّن فِرۡعَوۡنَ وَمَلَإِی۟هِمۡ أَن یَفۡتِنَهُمۡۚ وَإِنَّ فِرۡعَوۡنَ لَعَالࣲ فِی ٱلۡأَرۡضِ وَإِنَّهُۥ لَمِنَ ٱلۡمُسۡرِفِینَ',
    'فما امن لموسى الا ذرية من قومه على خوف من فرعون وملئهم ان يفتنهم وان فرعون لعال في الارض وانه لمن المسرفين',
    'فَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَنَ لِمُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَّا ذُرِّيَّ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_normal>ِۦ</rule> عَلَىٰ خَوۡ<rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِرۡعَوۡنَ وَمَلَإِ<rule class=slnt>يۡ</rule>هِمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡتِنَهُمۡ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ فِرۡعَوۡنَ لَعَا<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡرِف<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 11, 3, 218, 180, 87, 'false'
  );
  
  -- Ayah 84 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1448,
    'وَقَالَ مُوسَىٰ یَـٰقَوۡمِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ فَعَلَیۡهِ تَوَكَّلُوۤا۟ إِن كُنتُم مُّسۡلِمِینَ',
    'وقال موسى يا قوم ان كنتم امنتم بالله فعليه توكلوا ان كنتم مسلمين',
    'وَقَالَ مُوسَىٰ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ ءَامَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ فَعَلَيۡهِ تَوَكَّل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٨٤',
    84, 11, 3, 218, 180, 87, 'false'
  );
  
  -- Ayah 85 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1449,
    'فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةࣰ لِّلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'فقالوا على الله توكلنا ربنا لا تجعلنا فتنة للقوم الظالمين',
    'فَقَالُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَ<rule class=qalaqah>جۡ</rule>عَلۡنَا فِتۡنَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 11, 3, 218, 180, 87, 'false'
  );
  
  -- Ayah 86 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1450,
    'وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ',
    'ونجنا برحمتك من القوم الكافرين',
    'وَنَجِّنَا بِرَحۡمَتِكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 11, 3, 218, 180, 87, 'false'
  );
  
  -- Ayah 87 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1451,
    'وَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰ وَأَخِیهِ أَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُیُوتࣰا وَٱجۡعَلُوا۟ بُیُوتَكُمۡ قِبۡلَةࣰ وَأَقِیمُوا۟ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ',
    'واوحينا الى موسى واخيه ان تبوا لقومكما بمصر بيوتا واجعلوا بيوتكم قبلة واقيموا الصلاة وبشر المؤمنين',
    'وَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مُوسَىٰ وَأَخِيهِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُيُو<rule class=idgham_ghunnah>تًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلُو<rule class=slnt>اۡ</rule> بُيُوتَكُمۡ قِ<rule class=qalaqah>بۡ</rule>لَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ‌ۗ وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 11, 3, 218, 180, 87, 'false'
  );
  
  -- Ayah 88 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1452,
    'وَقَالَ مُوسَىٰ رَبَّنَاۤ إِنَّكَ ءَاتَیۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِینَةࣰ وَأَمۡوَ ٰ⁠لࣰا فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا رَبَّنَا لِیُضِلُّوا۟ عَن سَبِیلِكَۖ رَبَّنَا ٱطۡمِسۡ عَلَىٰۤ أَمۡوَ ٰ⁠لِهِمۡ وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا یُؤۡمِنُوا۟ حَتَّىٰ یَرَوُا۟ ٱلۡعَذَابَ ٱلۡأَلِیمَ',
    'وقال موسى ربنا انك اتيت فرعون وملاه زينة واموالا في الحياة الدنيا ربنا ليضلوا عن سبيلك ربنا اطمس على اموالهم واشدد على قلوبهم فلا يؤمنوا حتى يروا العذاب الاليم',
    'وَقَالَ مُوسَىٰ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ ءَاتَيۡتَ فِرۡعَوۡنَ وَمَلَأَهُ<rule class=madda_normal>ۥ</rule> زِينَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَمۡو<rule class=madda_normal>ٰ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا رَبَّنَا لِيُضِلُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِكَ‌ۖ رَبَّنَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>طۡ</rule>مِسۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَ<rule class=ham_wasl>ٱ</rule>شۡدُ<rule class=qalaqah>دۡ</rule> عَلَىٰ قُلُوبِهِمۡ فَلَا يُؤۡمِنُو<rule class=slnt>اۡ</rule> حَتَّىٰ يَرَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ <rule class=ham_wasl>ٱ</rule>لۡأَل<rule class=madda_permissible>ِي</rule>مَ ٨٨',
    88, 11, 3, 218, 180, 87, 'false'
  );
  
  -- Ayah 89 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1453,
    'قَالَ قَدۡ أُجِیبَت دَّعۡوَتُكُمَا فَٱسۡتَقِیمَا وَلَا تَتَّبِعَاۤنِّ سَبِیلَ ٱلَّذِینَ لَا یَعۡلَمُونَ',
    'قال قد اجيبت دعوتكما فاستقيما ولا تتبعان سبيل الذين لا يعلمون',
    'قَالَ قَ<rule class=qalaqah>دۡ</rule> أُجِيبَ<rule class=idgham_mutajanisayn>ت</rule> دَّعۡوَتُكُمَا فَ<rule class=ham_wasl>ٱ</rule>سۡتَقِيمَا وَلَا تَتَّبِع<rule class=madda_necessary>َا</rule>ٓ<rule class=ghunnah>نّ</rule>ِ سَبِيلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨٩',
    89, 11, 3, 219, 180, 87, 'false'
  );
  
  -- Ayah 90 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1454,
    '۞ وَجَـٰوَزۡنَا بِبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡیࣰا وَعَدۡوًاۖ حَتَّىٰۤ إِذَاۤ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّا ٱلَّذِیۤ ءَامَنَتۡ بِهِۦ بَنُوۤا۟ إِسۡرَ ٰ⁠ۤءِیلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِینَ',
    'وجاوزنا ببني اسرائيل البحر فاتبعهم فرعون وجنوده بغيا وعدوا حتى اذا ادركه الغرق قال امنت انه لا اله الا الذي امنت به بنو اسرائيل وانا من المسلمين',
    '۞وَجَ<rule class=madda_normal>ـٰ</rule>وَزۡنَا بِبَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُ<rule class=madda_normal>ۥ</rule> بَغۡ<rule class=idgham_ghunnah>يًا</rule> <rule class=idgham_ghunnah>و</rule>َعَ<rule class=qalaqah>دۡ</rule>وًا‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَكَهُ <rule class=ham_wasl>ٱ</rule>لۡغَرَقُ قَالَ ءَامَ<rule class=ikhafa>نت</rule>ُ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَامَنَتۡ بِه<rule class=madda_normal>ِۦ</rule> بَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ وَأَنَاۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٩٠',
    90, 11, 3, 219, 180, 88, 'false'
  );
  
  -- Ayah 91 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1455,
    'ءَاۤلۡـَٔـٰنَ وَقَدۡ عَصَیۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِینَ',
    'الان وقد عصيت قبل وكنت من المفسدين',
    'ءَ<rule class=madda_necessary>آ</rule>لۡـَٔ<rule class=madda_normal>ـٰ</rule>نَ وَقَ<rule class=qalaqah>دۡ</rule> عَصَيۡتَ قَ<rule class=qalaqah>بۡ</rule>لُ وَكُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 11, 3, 219, 180, 88, 'false'
  );
  
  -- Ayah 92 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1456,
    'فَٱلۡیَوۡمَ نُنَجِّیكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَایَةࣰۚ وَإِنَّ كَثِیرࣰا مِّنَ ٱلنَّاسِ عَنۡ ءَایَـٰتِنَا لَغَـٰفِلُونَ',
    'فاليوم ننجيك ببدنك لتكون لمن خلفك اية وان كثيرا من الناس عن اياتنا لغافلون',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَايَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ عَنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا لَغَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ٩٢',
    92, 11, 3, 219, 180, 88, 'false'
  );
  
  -- Ayah 93 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1457,
    'وَلَقَدۡ بَوَّأۡنَا بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ مُبَوَّأَ صِدۡقࣲ وَرَزَقۡنَـٰهُم مِّنَ ٱلطَّیِّبَـٰتِ فَمَا ٱخۡتَلَفُوا۟ حَتَّىٰ جَاۤءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ یَقۡضِی بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ',
    'ولقد بوانا بني اسرائيل مبوا صدق ورزقناهم من الطيبات فما اختلفوا حتى جاءهم العلم ان ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> بَوَّأۡنَا بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ مُبَوَّأَ صِ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>و</rule>َرَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ فَمَا <rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> حَتَّىٰ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ يَ<rule class=qalaqah>قۡ</rule>ضِى بَيۡنَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فِيمَا كَانُو<rule class=slnt>اۡ</rule> فِيهِ يَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 11, 3, 219, 181, 88, 'false'
  );
  
  -- Ayah 94 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1458,
    'فَإِن كُنتَ فِی شَكࣲّ مِّمَّاۤ أَنزَلۡنَاۤ إِلَیۡكَ فَسۡـَٔلِ ٱلَّذِینَ یَقۡرَءُونَ ٱلۡكِتَـٰبَ مِن قَبۡلِكَۚ لَقَدۡ جَاۤءَكَ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِینَ',
    'فان كنت في شك مما انزلنا اليك فاسال الذين يقرءون الكتاب من قبلك لقد جاءك الحق من ربك فلا تكونن من الممترين',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ فِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ فَسۡــَٔلِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>قۡ</rule>رَءُونَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ‌ۚ لَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ فَلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُمۡتَر<rule class=madda_permissible>ِي</rule>نَ ٩٤',
    94, 11, 3, 219, 181, 88, 'false'
  );
  
  -- Ayah 95 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1459,
    'وَلَا تَكُونَنَّ مِنَ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَـٰسِرِینَ',
    'ولا تكونن من الذين كذبوا بايات الله فتكون من الخاسرين',
    'وَلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَتَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٩٥',
    95, 11, 3, 219, 181, 88, 'false'
  );
  
  -- Ayah 96 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1460,
    'إِنَّ ٱلَّذِینَ حَقَّتۡ عَلَیۡهِمۡ كَلِمَتُ رَبِّكَ لَا یُؤۡمِنُونَ',
    'ان الذين حقت عليهم كلمت ربك لا يؤمنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ حَقَّتۡ عَلَيۡهِمۡ كَلِمَتُ رَبِّكَ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 11, 3, 219, 181, 88, 'false'
  );
  
  -- Ayah 97 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1461,
    'وَلَوۡ جَاۤءَتۡهُمۡ كُلُّ ءَایَةٍ حَتَّىٰ یَرَوُا۟ ٱلۡعَذَابَ ٱلۡأَلِیمَ',
    'ولو جاءتهم كل اية حتى يروا العذاب الاليم',
    'وَلَوۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ كُلُّ ءَايَةٍ حَتَّىٰ يَرَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ <rule class=ham_wasl>ٱ</rule>لۡأَل<rule class=madda_permissible>ِي</rule>مَ ٩٧',
    97, 11, 3, 219, 181, 88, 'false'
  );
  
  -- Ayah 98 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1462,
    'فَلَوۡلَا كَانَتۡ قَرۡیَةٌ ءَامَنَتۡ فَنَفَعَهَاۤ إِیمَـٰنُهَاۤ إِلَّا قَوۡمَ یُونُسَ لَمَّاۤ ءَامَنُوا۟ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡیِ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَمَتَّعۡنَـٰهُمۡ إِلَىٰ حِینࣲ',
    'فلولا كانت قرية امنت فنفعها ايمانها الا قوم يونس لما امنوا كشفنا عنهم عذاب الخزي في الحياة الدنيا ومتعناهم الى حين',
    'فَلَوۡلَا كَانَتۡ قَرۡيَةٌ ءَامَنَتۡ فَنَفَعَه<rule class=madda_obligatory_monfasel>َآ</rule> إِيمَ<rule class=madda_normal>ـٰ</rule>نُه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا قَوۡمَ يُونُسَ لَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَامَنُو<rule class=slnt>اۡ</rule> كَشَفۡنَا عَنۡهُمۡ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡخِزۡىِ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَمَتَّعۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ إِلَىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٩٨',
    98, 11, 3, 220, 181, 88, 'false'
  );
  
  -- Ayah 99 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1463,
    'وَلَوۡ شَاۤءَ رَبُّكَ لَـَٔامَنَ مَن فِی ٱلۡأَرۡضِ كُلُّهُمۡ جَمِیعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ یَكُونُوا۟ مُؤۡمِنِینَ',
    'ولو شاء ربك لامن من في الارض كلهم جميعا افانت تكره الناس حتى يكونوا مؤمنين',
    'وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبُّكَ لَأَمَنَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ كُلُّهُمۡ جَمِيعًا‌ۚ أَفَأَ<rule class=ikhafa>نت</rule>َ تُكۡرِهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ حَتَّىٰ يَكُونُو<rule class=slnt>اۡ</rule> مُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٩٩',
    99, 11, 3, 220, 181, 88, 'false'
  );
  
  -- Ayah 100 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1464,
    'وَمَا كَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَیَجۡعَلُ ٱلرِّجۡسَ عَلَى ٱلَّذِینَ لَا یَعۡقِلُونَ',
    'وما كان لنفس ان تؤمن الا باذن الله ويجعل الرجس على الذين لا يعقلون',
    'وَمَا كَانَ لِنَفۡسٍ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُؤۡمِنَ إِلَّا بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَيَ<rule class=qalaqah>جۡ</rule>عَلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّ<rule class=qalaqah>جۡ</rule>سَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٠٠',
    100, 11, 3, 220, 181, 88, 'false'
  );
  
  -- Ayah 101 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1465,
    'قُلِ ٱنظُرُوا۟ مَاذَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَمَا تُغۡنِی ٱلۡـَٔایَـٰتُ وَٱلنُّذُرُ عَن قَوۡمࣲ لَّا یُؤۡمِنُونَ',
    'قل انظروا ماذا في السماوات والارض وما تغني الايات والنذر عن قوم لا يؤمنون',
    'قُلِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> مَاذَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَمَا تُغۡنِى <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُذُرُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٠١',
    101, 11, 3, 220, 181, 88, 'false'
  );
  
  -- Ayah 102 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1466,
    'فَهَلۡ یَنتَظِرُونَ إِلَّا مِثۡلَ أَیَّامِ ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلِهِمۡۚ قُلۡ فَٱنتَظِرُوۤا۟ إِنِّی مَعَكُم مِّنَ ٱلۡمُنتَظِرِینَ',
    'فهل ينتظرون الا مثل ايام الذين خلوا من قبلهم قل فانتظروا اني معكم من المنتظرين',
    'فَهَلۡ يَ<rule class=ikhafa>نت</rule>َظِرُونَ إِلَّا مِثۡلَ أَيَّامِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَلَوۡ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ قُلۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َظِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>ِى مَعَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نت</rule>َظِر<rule class=madda_permissible>ِي</rule>نَ ١٠٢',
    102, 11, 3, 220, 181, 88, 'false'
  );
  
  -- Ayah 103 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1467,
    'ثُمَّ نُنَجِّی رُسُلَنَا وَٱلَّذِینَ ءَامَنُوا۟ۚ كَذَ ٰ⁠لِكَ حَقًّا عَلَیۡنَا نُنجِ ٱلۡمُؤۡمِنِینَ',
    'ثم ننجي رسلنا والذين امنوا كذلك حقا علينا ننج المؤمنين',
    'ثُ<rule class=ghunnah>مّ</rule>َ نُنَجِّى رُسُلَنَا وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ‌ۚ</rule> كَذ<rule class=madda_normal>ٰ</rule>لِكَ حَقًّا عَلَيۡنَا نُ<rule class=ikhafa>نج</rule>ِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٠٣',
    103, 11, 3, 220, 181, 88, 'false'
  );
  
  -- Ayah 104 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1468,
    'قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِی شَكࣲّ مِّن دِینِی فَلَاۤ أَعۡبُدُ ٱلَّذِینَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَلَـٰكِنۡ أَعۡبُدُ ٱللَّهَ ٱلَّذِی یَتَوَفَّىٰكُمۡۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ',
    'قل يا ايها الناس ان كنتم في شك من ديني فلا اعبد الذين تعبدون من دون الله ولكن اعبد الله الذي يتوفاكم وامرت ان اكون من المؤمنين',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ فِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِينِى فَل<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡبُدُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَ<rule class=madda_normal>ـٰ</rule>كِنۡ أَعۡبُدُ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذِى يَتَوَفَّ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٠٤',
    104, 11, 3, 220, 182, 88, 'false'
  );
  
  -- Ayah 105 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1469,
    'وَأَنۡ أَقِمۡ وَجۡهَكَ لِلدِّینِ حَنِیفࣰا وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِینَ',
    'وان اقم وجهك للدين حنيفا ولا تكونن من المشركين',
    'وَأَنۡ أَقِمۡ وَ<rule class=qalaqah>جۡ</rule>هَكَ لِلدِّينِ حَنِي<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١٠٥',
    105, 11, 3, 220, 182, 88, 'false'
  );
  
  -- Ayah 106 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1470,
    'وَلَا تَدۡعُ مِن دُونِ ٱللَّهِ مَا لَا یَنفَعُكَ وَلَا یَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذࣰا مِّنَ ٱلظَّـٰلِمِینَ',
    'ولا تدع من دون الله ما لا ينفعك ولا يضرك فان فعلت فانك اذا من الظالمين',
    'وَلَا تَ<rule class=qalaqah>دۡ</rule>عُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَ<rule class=ikhafa>نف</rule>َعُكَ وَلَا يَضُرُّكَ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َعَلۡتَ فَإِ<rule class=ghunnah>نّ</rule>َكَ إِ<rule class=idgham_ghunnah>ذًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٠٦',
    106, 11, 3, 220, 182, 88, 'false'
  );
  
  -- Ayah 107 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1471,
    'وَإِن یَمۡسَسۡكَ ٱللَّهُ بِضُرࣲّ فَلَا كَاشِفَ لَهُۥۤ إِلَّا هُوَۖ وَإِن یُرِدۡكَ بِخَیۡرࣲ فَلَا رَاۤدَّ لِفَضۡلِهِۦۚ یُصِیبُ بِهِۦ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۚ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ',
    'وان يمسسك الله بضر فلا كاشف له الا هو وان يردك بخير فلا راد لفضله يصيب به من يشاء من عباده وهو الغفور الرحيم',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡسَسۡكَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِضُ<rule class=ikhafa>رٍّ</rule> <rule class=ikhafa>ف</rule>َلَا كَاشِفَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا هُوَ‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِ<rule class=qalaqah>دۡ</rule>كَ بِخَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َلَا ر<rule class=madda_necessary>َا</rule>ٓدَّ لِفَضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۚ يُصِيبُ بِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡغَفُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٠٧',
    107, 11, 3, 221, 182, 88, 'false'
  );
  
  -- Ayah 108 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1472,
    'قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ قَدۡ جَاۤءَكُمُ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا یَهۡتَدِی لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا یَضِلُّ عَلَیۡهَاۖ وَمَاۤ أَنَا۠ عَلَیۡكُم بِوَكِیلࣲ',
    'قل يا ايها الناس قد جاءكم الحق من ربكم فمن اهتدى فانما يهتدي لنفسه ومن ضل فانما يضل عليها وما انا عليكم بوكيل',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۖ فَمَنِ <rule class=ham_wasl>ٱ</rule>هۡتَدَىٰ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَهۡتَدِى لِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَّ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَضِلُّ عَلَيۡهَا‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ عَلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِوَك<rule class=madda_permissible>ِي</rule>لٍ ١٠٨',
    108, 11, 3, 221, 182, 88, 'false'
  );
  
  -- Ayah 109 Surah Yunus
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    10,
    1473,
    'وَٱتَّبِعۡ مَا یُوحَىٰۤ إِلَیۡكَ وَٱصۡبِرۡ حَتَّىٰ یَحۡكُمَ ٱللَّهُۚ وَهُوَ خَیۡرُ ٱلۡحَـٰكِمِینَ',
    'واتبع ما يوحى اليك واصبر حتى يحكم الله وهو خير الحاكمين',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّبِعۡ مَا يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡكَ وَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ حَتَّىٰ يَحۡكُمَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَهُوَ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>كِم<rule class=madda_permissible>ِي</rule>نَ ١٠٩',
    109, 11, 3, 221, 182, 88, 'false'
  );
  

-- Surah Hud
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (11, 'سُورَةُ هُودٍ', 'Hud', 'Hud', 'Meccan', 123);

  -- Ayah 1 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1474,
    'الۤرۚ كِتَـٰبٌ أُحۡكِمَتۡ ءَایَـٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِیمٍ خَبِیرٍ',
    'الر كتاب احكمت اياته ثم فصلت من لدن حكيم خبير',
    'ا<rule class=madda_necessary>لٓ</rule>ر‌ۚ كِتَ<rule class=madda_normal>ـٰ</rule>بٌ أُحۡكِمَتۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ فُصِّلَتۡ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُنۡ حَكِيمٍ خَب<rule class=madda_permissible>ِي</rule>رٍ ١',
    1, 11, 3, 221, 183, 88, 'false'
  );
  
  -- Ayah 2 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1475,
    'أَلَّا تَعۡبُدُوۤا۟ إِلَّا ٱللَّهَۚ إِنَّنِی لَكُم مِّنۡهُ نَذِیرࣱ وَبَشِیرࣱ',
    'الا تعبدوا الا الله انني لكم منه نذير وبشير',
    'أَلَّا تَعۡبُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َنِى لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َبَش<rule class=madda_permissible>ِي</rule>رٌ ٢',
    2, 11, 3, 221, 183, 88, 'false'
  );
  
  -- Ayah 3 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1476,
    'وَأَنِ ٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ ثُمَّ تُوبُوۤا۟ إِلَیۡهِ یُمَتِّعۡكُم مَّتَـٰعًا حَسَنًا إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى وَیُؤۡتِ كُلَّ ذِی فَضۡلࣲ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡا۟ فَإِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمࣲ كَبِیرٍ',
    'وان استغفروا ربكم ثم توبوا اليه يمتعكم متاعا حسنا الى اجل مسمى ويؤت كل ذي فضل فضله وان تولوا فاني اخاف عليكم عذاب يوم كبير',
    'وَأَنِ <rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ تُوب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِ يُمَتِّعۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّتَ<rule class=madda_normal>ـٰ</rule>عًا حَسَنًا إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=idgham_ghunnah>ًّى</rule> <rule class=idgham_ghunnah>و</rule>َيُؤۡتِ كُلَّ ذِى فَضۡ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َضۡلَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ك</rule>َب<rule class=madda_permissible>ِي</rule>رٍ ٣',
    3, 11, 3, 221, 183, 88, 'false'
  );
  
  -- Ayah 4 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1477,
    'إِلَى ٱللَّهِ مَرۡجِعُكُمۡۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'الى الله مرجعكم وهو على كل شيء قدير',
    'إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَرۡجِعُكُمۡ‌ۖ وَهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٤',
    4, 11, 3, 221, 183, 88, 'false'
  );
  
  -- Ayah 5 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1478,
    'أَلَاۤ إِنَّهُمۡ یَثۡنُونَ صُدُورَهُمۡ لِیَسۡتَخۡفُوا۟ مِنۡهُۚ أَلَا حِینَ یَسۡتَغۡشُونَ ثِیَابَهُمۡ یَعۡلَمُ مَا یُسِرُّونَ وَمَا یُعۡلِنُونَۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'الا انهم يثنون صدورهم ليستخفوا منه الا حين يستغشون ثيابهم يعلم ما يسرون وما يعلنون انه عليم بذات الصدور',
    'أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ يَثۡنُونَ صُدُورَهُمۡ لِيَسۡتَخۡفُو<rule class=slnt>اۡ</rule> مِنۡهُ‌ۚ أَلَا حِينَ يَسۡتَغۡشُونَ ثِيَابَهُمۡ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٥',
    5, 11, 3, 221, 183, 88, 'false'
  );
  
  -- Ayah 6 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1479,
    '۞ وَمَا مِن دَاۤبَّةࣲ فِی ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَیَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلࣱّ فِی كِتَـٰبࣲ مُّبِینࣲ',
    'وما من دابة في الارض الا على الله رزقها ويعلم مستقرها ومستودعها كل في كتاب مبين',
    '۞وَمَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِلَّا عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَا‌ۚ كُ<rule class=ikhafa>لٌّ</rule> <rule class=ikhafa>ف</rule>ِى كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٦',
    6, 12, 3, 222, 183, 89, 'false'
  );
  
  -- Ayah 7 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1480,
    'وَهُوَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ وَكَانَ عَرۡشُهُۥ عَلَى ٱلۡمَاۤءِ لِیَبۡلُوَكُمۡ أَیُّكُمۡ أَحۡسَنُ عَمَلࣰاۗ وَلَىِٕن قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَیَقُولَنَّ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ',
    'وهو الذي خلق السماوات والارض في ستة ايام وكان عرشه على الماء ليبلوكم ايكم احسن عملا ولئن قلت انكم مبعوثون من بعد الموت ليقولن الذين كفروا ان هذا الا سحر مبين',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فِى سِتَّةِ أَيَّا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ عَرۡشُهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ لِيَ<rule class=qalaqah>بۡ</rule>لُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَل<rule class=idgham_ghunnah>اً‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُلۡتَ إِ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=qalaqah>بۡ</rule>عُوثُونَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ لَيَقُولَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٧',
    7, 12, 3, 222, 183, 89, 'false'
  );
  
  -- Ayah 8 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1481,
    'وَلَىِٕنۡ أَخَّرۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِلَىٰۤ أُمَّةࣲ مَّعۡدُودَةࣲ لَّیَقُولُنَّ مَا یَحۡبِسُهُۥۤۗ أَلَا یَوۡمَ یَأۡتِیهِمۡ لَیۡسَ مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'ولئن اخرنا عنهم العذاب الى امة معدودة ليقولن ما يحبسه الا يوم ياتيهم ليس مصروفا عنهم وحاق بهم ما كانوا به يستهزئون',
    'وَلَئِنۡ أَخَّرۡنَا عَنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡدُودَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيَقُولُ<rule class=ghunnah>نّ</rule>َ مَا يَحۡبِسُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۗ</rule> أَلَا يَوۡمَ يَأۡتِيهِمۡ لَيۡسَ مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 12, 3, 222, 183, 89, 'false'
  );
  
  -- Ayah 9 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1482,
    'وَلَىِٕنۡ أَذَقۡنَا ٱلۡإِنسَـٰنَ مِنَّا رَحۡمَةࣰ ثُمَّ نَزَعۡنَـٰهَا مِنۡهُ إِنَّهُۥ لَیَـُٔوسࣱ كَفُورࣱ',
    'ولئن اذقنا الانسان منا رحمة ثم نزعناها منه انه ليئوس كفور',
    'وَلَئِنۡ أَذَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ مِ<rule class=ghunnah>نّ</rule>َا رَحۡمَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ نَزَعۡنَ<rule class=madda_normal>ـٰ</rule>هَا مِنۡهُ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَيَــُٔو<rule class=ikhafa>سٌ</rule> <rule class=ikhafa>ك</rule>َف<rule class=madda_permissible>ُو</rule>رٌ ٩',
    9, 12, 3, 222, 184, 89, 'false'
  );
  
  -- Ayah 10 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1483,
    'وَلَىِٕنۡ أَذَقۡنَـٰهُ نَعۡمَاۤءَ بَعۡدَ ضَرَّاۤءَ مَسَّتۡهُ لَیَقُولَنَّ ذَهَبَ ٱلسَّیِّـَٔاتُ عَنِّیۤۚ إِنَّهُۥ لَفَرِحࣱ فَخُورٌ',
    'ولئن اذقناه نعماء بعد ضراء مسته ليقولن ذهب السيئات عني انه لفرح فخور',
    'وَلَئِنۡ أَذَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ نَعۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بَعۡدَ ضَرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَسَّتۡهُ لَيَقُولَ<rule class=ghunnah>نّ</rule>َ ذَهَبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتُ عَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَفَرِ<rule class=ikhafa>حٌ</rule> <rule class=ikhafa>ف</rule>َخ<rule class=madda_permissible>ُو</rule>رٌ ١٠',
    10, 12, 3, 222, 184, 89, 'false'
  );
  
  -- Ayah 11 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1484,
    'إِلَّا ٱلَّذِینَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰۤىِٕكَ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرࣱ',
    'الا الذين صبروا وعملوا الصالحات اولئك لهم مغفرة واجر كبير',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ صَبَرُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ك</rule>َب<rule class=madda_permissible>ِي</rule>رٌ ١١',
    11, 12, 3, 222, 184, 89, 'false'
  );
  
  -- Ayah 12 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1485,
    'فَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا یُوحَىٰۤ إِلَیۡكَ وَضَاۤىِٕقُۢ بِهِۦ صَدۡرُكَ أَن یَقُولُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ كَنزٌ أَوۡ جَاۤءَ مَعَهُۥ مَلَكٌۚ إِنَّمَاۤ أَنتَ نَذِیرࣱۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ وَكِیلٌ',
    'فلعلك تارك بعض ما يوحى اليك وضائق به صدرك ان يقولوا لولا انزل عليه كنز او جاء معه ملك انما انت نذير والله على كل شيء وكيل',
    'فَلَعَلَّكَ تَارِ<rule class=iqlab>كُۢ</rule> <rule class=iqlab>ب</rule>َعۡضَ مَا يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡكَ وَض<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=iqlab>قُۢ</rule> <rule class=iqlab>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> صَ<rule class=qalaqah>دۡ</rule>رُكَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُو<rule class=slnt>اۡ</rule> لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡهِ كَ<rule class=ikhafa>نز</rule>ٌ أَوۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَعَهُ<rule class=madda_normal>ۥ</rule> مَلَكٌ‌ۚ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ نَذِي<rule class=idgham_ghunnah>رٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َك<rule class=madda_permissible>ِي</rule>لٌ ١٢',
    12, 12, 3, 222, 184, 89, 'false'
  );
  
  -- Ayah 13 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1486,
    'أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُوا۟ بِعَشۡرِ سُوَرࣲ مِّثۡلِهِۦ مُفۡتَرَیَـٰتࣲ وَٱدۡعُوا۟ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ام يقولون افتراه قل فاتوا بعشر سور مثله مفتريات وادعوا من استطعتم من دون الله ان كنتم صادقين',
    'أَمۡ يَقُولُونَ <rule class=ham_wasl>ٱ</rule>فۡتَرَ<rule class=madda_normal>ٮٰ</rule>هُ‌ۖ قُلۡ فَأۡتُو<rule class=slnt>اۡ</rule> بِعَشۡرِ سُوَ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلِه<rule class=madda_normal>ِۦ</rule> مُفۡتَرَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> مَنِ <rule class=ham_wasl>ٱ</rule>سۡتَطَعۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 12, 3, 223, 184, 89, 'false'
  );
  
  -- Ayah 14 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1487,
    'فَإِلَّمۡ یَسۡتَجِیبُوا۟ لَكُمۡ فَٱعۡلَمُوۤا۟ أَنَّمَاۤ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّاۤ إِلَـٰهَ إِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ',
    'فالم يستجيبوا لكم فاعلموا انما انزل بعلم الله وان لا اله الا هو فهل انتم مسلمون',
    'فَإِلَّمۡ يَسۡتَجِيبُو<rule class=slnt>اۡ</rule> لَكُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ بِعِلۡمِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۖ فَهَلۡ أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 12, 3, 223, 184, 89, 'false'
  );
  
  -- Ayah 15 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1488,
    'مَن كَانَ یُرِیدُ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا وَزِینَتَهَا نُوَفِّ إِلَیۡهِمۡ أَعۡمَـٰلَهُمۡ فِیهَا وَهُمۡ فِیهَا لَا یُبۡخَسُونَ',
    'من كان يريد الحياة الدنيا وزينتها نوف اليهم اعمالهم فيها وهم فيها لا يبخسون',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يُرِيدُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ فِيهَا وَهُمۡ فِيهَا لَا يُ<rule class=qalaqah>بۡ</rule>خَس<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 12, 3, 223, 184, 89, 'false'
  );
  
  -- Ayah 16 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1489,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَیۡسَ لَهُمۡ فِی ٱلۡـَٔاخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُوا۟ فِیهَا وَبَـٰطِلࣱ مَّا كَانُوا۟ یَعۡمَلُونَ',
    'اولئك الذين ليس لهم في الاخرة الا النار وحبط ما صنعوا فيها وباطل ما كانوا يعملون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَيۡسَ لَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ‌ۖ وَحَبِطَ مَا صَنَعُو<rule class=slnt>اۡ</rule> فِيهَا وَبَ<rule class=madda_normal>ـٰ</rule>طِ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 12, 3, 223, 184, 89, 'false'
  );
  
  -- Ayah 17 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1490,
    'أَفَمَن كَانَ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّهِۦ وَیَتۡلُوهُ شَاهِدࣱ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَـٰبُ مُوسَىٰۤ إِمَامࣰا وَرَحۡمَةًۚ أُو۟لَـٰۤىِٕكَ یُؤۡمِنُونَ بِهِۦۚ وَمَن یَكۡفُرۡ بِهِۦ مِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِی مِرۡیَةࣲ مِّنۡهُۚ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یُؤۡمِنُونَ',
    'افمن كان على بينة من ربه ويتلوه شاهد منه ومن قبله كتاب موسى اماما ورحمة اولئك يؤمنون به ومن يكفر به من الاحزاب فالنار موعده فلا تك في مرية منه انه الحق من ربك ولكن اكثر الناس لا يؤمنون',
    'أَفَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ عَلَىٰ بَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule> وَيَتۡلُوهُ شَاهِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> كِتَ<rule class=madda_normal>ـٰ</rule>بُ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِمَا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَةً‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يُؤۡمِنُونَ بِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرۡ بِه<rule class=madda_normal>ِۦ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡزَابِ فَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ مَوۡعِدُهُ<rule class=madda_normal>ۥ</rule>‌ۚ فَلَا تَكُ فِى مِرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 12, 3, 223, 184, 89, 'false'
  );
  
  -- Ayah 18 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1491,
    'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًاۚ أُو۟لَـٰۤىِٕكَ یُعۡرَضُونَ عَلَىٰ رَبِّهِمۡ وَیَقُولُ ٱلۡأَشۡهَـٰدُ هَـٰۤؤُلَاۤءِ ٱلَّذِینَ كَذَبُوا۟ عَلَىٰ رَبِّهِمۡۚ أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِینَ',
    'ومن اظلم ممن افترى على الله كذبا اولئك يعرضون على ربهم ويقول الاشهاد هؤلاء الذين كذبوا على ربهم الا لعنة الله على الظالمين',
    'وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يُعۡرَضُونَ عَلَىٰ رَبِّهِمۡ وَيَقُولُ <rule class=ham_wasl>ٱ</rule>لۡأَشۡهَ<rule class=madda_normal>ـٰ</rule>دُ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَبُو<rule class=slnt>اۡ</rule> عَلَىٰ رَبِّهِمۡ‌ۚ أَلَا لَعۡنَةُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٨',
    18, 12, 3, 223, 184, 89, 'false'
  );
  
  -- Ayah 19 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1492,
    'ٱلَّذِینَ یَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَیَبۡغُونَهَا عِوَجࣰا وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ كَـٰفِرُونَ',
    'الذين يصدون عن سبيل الله ويبغونها عوجا وهم بالاخرة هم كافرون',
    'ٱلَّذِينَ يَصُدُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَ<rule class=qalaqah>بۡ</rule>غُونَهَا عِوَ<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 12, 3, 223, 184, 89, 'false'
  );
  
  -- Ayah 20 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1493,
    'أُو۟لَـٰۤىِٕكَ لَمۡ یَكُونُوا۟ مُعۡجِزِینَ فِی ٱلۡأَرۡضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِیَاۤءَۘ یُضَـٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُوا۟ یَسۡتَطِیعُونَ ٱلسَّمۡعَ وَمَا كَانُوا۟ یُبۡصِرُونَ',
    'اولئك لم يكونوا معجزين في الارض وما كان لهم من دون الله من اولياء يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَمۡ يَكُونُو<rule class=slnt>اۡ</rule> مُعۡجِزِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا كَانَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مِنۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۘ يُضَ<rule class=madda_normal>ـٰ</rule>عَفُ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ‌ۚ مَا كَانُو<rule class=slnt>اۡ</rule> يَسۡتَطِيعُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَمَا كَانُو<rule class=slnt>اۡ</rule> يُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 12, 3, 224, 184, 89, 'false'
  );
  
  -- Ayah 21 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1494,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ',
    'اولئك الذين خسروا انفسهم وضل عنهم ما كانوا يفترون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَسِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَضَلَّ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 12, 3, 224, 184, 89, 'false'
  );
  
  -- Ayah 22 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1495,
    'لَا جَرَمَ أَنَّهُمۡ فِی ٱلۡـَٔاخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ',
    'لا جرم انهم في الاخرة هم الاخسرون',
    'لَا جَرَمَ أَ<rule class=ghunnah>نّ</rule>َهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمُ <rule class=ham_wasl>ٱ</rule>لۡأَخۡسَر<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 12, 3, 224, 184, 89, 'false'
  );
  
  -- Ayah 23 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1496,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَخۡبَتُوۤا۟ إِلَىٰ رَبِّهِمۡ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'ان الذين امنوا وعملوا الصالحات واخبتوا الى ربهم اولئك اصحاب الجنة هم فيها خالدون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَأَخۡبَت<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ رَبِّهِمۡ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 12, 3, 224, 184, 89, 'false'
  );
  
  -- Ayah 24 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1497,
    '۞ مَثَلُ ٱلۡفَرِیقَیۡنِ كَٱلۡأَعۡمَىٰ وَٱلۡأَصَمِّ وَٱلۡبَصِیرِ وَٱلسَّمِیعِۚ هَلۡ یَسۡتَوِیَانِ مَثَلًاۚ أَفَلَا تَذَكَّرُونَ',
    'مثل الفريقين كالاعمى والاصم والبصير والسميع هل يستويان مثلا افلا تذكرون',
    '۞مَثَلُ <rule class=ham_wasl>ٱ</rule>لۡفَرِيقَيۡنِ كَ<rule class=ham_wasl>ٱ</rule>لۡأَعۡمَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡأَصَ<rule class=ghunnah>مّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡبَصِيرِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعِ‌ۚ هَلۡ يَسۡتَوِيَانِ مَثَلاً‌ۚ أَفَلَا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 12, 3, 224, 184, 90, 'false'
  );
  
  -- Ayah 25 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1498,
    'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦۤ إِنِّی لَكُمۡ نَذِیرࣱ مُّبِینٌ',
    'ولقد ارسلنا نوحا الى قومه اني لكم نذير مبين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>ِى لَكُمۡ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٢٥',
    25, 12, 3, 224, 185, 90, 'false'
  );
  
  -- Ayah 26 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1499,
    'أَن لَّا تَعۡبُدُوۤا۟ إِلَّا ٱللَّهَۖ إِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمٍ أَلِیمࣲ',
    'ان لا تعبدوا الا الله اني اخاف عليكم عذاب يوم اليم',
    'أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَعۡبُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٢٦',
    26, 12, 3, 224, 185, 90, 'false'
  );
  
  -- Ayah 27 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1500,
    'فَقَالَ ٱلۡمَلَأُ ٱلَّذِینَ كَفَرُوا۟ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرࣰا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِینَ هُمۡ أَرَاذِلُنَا بَادِیَ ٱلرَّأۡیِ وَمَا نَرَىٰ لَكُمۡ عَلَیۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَـٰذِبِینَ',
    'فقال الملا الذين كفروا من قومه ما نراك الا بشرا مثلنا وما نراك اتبعك الا الذين هم اراذلنا بادي الراي وما نرى لكم علينا من فضل بل نظنكم كاذبين',
    'فَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_normal>ِۦ</rule> مَا نَرَ<rule class=madda_normal>ٮٰ</rule>كَ إِلَّا بَشَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلَنَا وَمَا نَرَ<rule class=madda_normal>ٮٰ</rule>كَ <rule class=ham_wasl>ٱ</rule>تَّبَعَكَ إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ أَرَاذِلُنَا بَادِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّأۡىِ وَمَا نَرَىٰ لَكُمۡ عَلَيۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡ<rule class=iqlab>لِۭ</rule> <rule class=iqlab>ب</rule>َلۡ نَظُ<rule class=ghunnah>نّ</rule>ُكُمۡ كَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 12, 3, 224, 185, 90, 'false'
  );
  
  -- Ayah 28 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1501,
    'قَالَ یَـٰقَوۡمِ أَرَءَیۡتُمۡ إِن كُنتُ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّی وَءَاتَىٰنِی رَحۡمَةࣰ مِّنۡ عِندِهِۦ فَعُمِّیَتۡ عَلَیۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَـٰرِهُونَ',
    'قال يا قوم ارايتم ان كنت على بينة من ربي واتاني رحمة من عنده فعميت عليكم انلزمكموها وانتم لها كارهون',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ أَرَءَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُ عَلَىٰ بَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّى وَءَاتَ<rule class=madda_normal>ـٰ</rule>نِى رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِه<rule class=madda_normal>ِۦ</rule> فَعُ<rule class=ghunnah>مّ</rule>ِيَتۡ عَلَيۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَهَا كَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 12, 3, 224, 185, 90, 'false'
  );
  
  -- Ayah 29 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1502,
    'وَیَـٰقَوۡمِ لَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مَالًاۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱللَّهِۚ وَمَاۤ أَنَا۠ بِطَارِدِ ٱلَّذِینَ ءَامَنُوۤا۟ۚ إِنَّهُم مُّلَـٰقُوا۟ رَبِّهِمۡ وَلَـٰكِنِّیۤ أَرَىٰكُمۡ قَوۡمࣰا تَجۡهَلُونَ',
    'ويا قوم لا اسالكم عليه مالا ان اجري الا على الله وما انا بطارد الذين امنوا انهم ملاقو ربهم ولكني اراكم قوما تجهلون',
    'وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ ل<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ مَالاً‌ۖ إِنۡ أَ<rule class=qalaqah>جۡ</rule>رِىَ إِلَّا عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ بِطَارِدِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلَ<rule class=madda_normal>ـٰ</rule>قُو<rule class=slnt>اۡ</rule> رَبِّهِمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَ<rule class=madda_normal>ٮٰ</rule>كُمۡ قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>هَل<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 12, 3, 225, 185, 90, 'false'
  );
  
  -- Ayah 30 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1503,
    'وَیَـٰقَوۡمِ مَن یَنصُرُنِی مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ',
    'ويا قوم من ينصرني من الله ان طردتهم افلا تذكرون',
    'وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرُنِى مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َرَ<rule class=idgham_mutajanisayn>د</rule>تُّهُمۡ‌ۚ أَفَلَا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 12, 3, 225, 185, 90, 'false'
  );
  
  -- Ayah 31 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1504,
    'وَلَاۤ أَقُولُ لَكُمۡ عِندِی خَزَاۤىِٕنُ ٱللَّهِ وَلَاۤ أَعۡلَمُ ٱلۡغَیۡبَ وَلَاۤ أَقُولُ إِنِّی مَلَكࣱ وَلَاۤ أَقُولُ لِلَّذِینَ تَزۡدَرِیۤ أَعۡیُنُكُمۡ لَن یُؤۡتِیَهُمُ ٱللَّهُ خَیۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِیۤ أَنفُسِهِمۡ إِنِّیۤ إِذࣰا لَّمِنَ ٱلظَّـٰلِمِینَ',
    'ولا اقول لكم عندي خزائن الله ولا اعلم الغيب ولا اقول اني ملك ولا اقول للذين تزدري اعينكم لن يؤتيهم الله خيرا الله اعلم بما في انفسهم اني اذا لمن الظالمين',
    'وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَقُولُ لَكُمۡ عِ<rule class=ikhafa>ند</rule>ِى خَز<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبَ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَقُولُ إِ<rule class=ghunnah>نّ</rule>ِى مَلَ<rule class=idgham_ghunnah>كٌ</rule> <rule class=idgham_ghunnah>و</rule>َل<rule class=madda_obligatory_monfasel>َآ</rule> أَقُولُ لِلَّذِينَ تَزۡدَر<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡيُنُكُمۡ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ خَيۡرًا‌ۖ <rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِمَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 12, 3, 225, 185, 90, 'false'
  );
  
  -- Ayah 32 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1505,
    'قَالُوا۟ یَـٰنُوحُ قَدۡ جَـٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَ ٰ⁠لَنَا فَأۡتِنَا بِمَا تَعِدُنَاۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'قالوا يا نوح قد جادلتنا فاكثرت جدالنا فاتنا بما تعدنا ان كنت من الصادقين',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>نُوحُ قَ<rule class=qalaqah>دۡ</rule> جَ<rule class=madda_normal>ـٰ</rule>دَلۡتَنَا فَأَكۡثَرۡتَ جِد<rule class=madda_normal>ٰ</rule>لَنَا فَأۡتِنَا بِمَا تَعِدُن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 12, 3, 225, 185, 90, 'false'
  );
  
  -- Ayah 33 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1506,
    'قَالَ إِنَّمَا یَأۡتِیكُم بِهِ ٱللَّهُ إِن شَاۤءَ وَمَاۤ أَنتُم بِمُعۡجِزِینَ',
    'قال انما ياتيكم به الله ان شاء وما انتم بمعجزين',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َمَا يَأۡتِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِ <rule class=ham_wasl>ٱ</rule>للَّهُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُعۡجِز<rule class=madda_permissible>ِي</rule>نَ ٣٣',
    33, 12, 3, 225, 185, 90, 'false'
  );
  
  -- Ayah 34 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1507,
    'وَلَا یَنفَعُكُمۡ نُصۡحِیۤ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ یُرِیدُ أَن یُغۡوِیَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَیۡهِ تُرۡجَعُونَ',
    'ولا ينفعكم نصحي ان اردت ان انصح لكم ان كان الله يريد ان يغويكم هو ربكم واليه ترجعون',
    'وَلَا يَ<rule class=ikhafa>نف</rule>َعُكُمۡ نُصۡح<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِنۡ أَرَ<rule class=idgham_mutajanisayn>د</rule>تُّ أَنۡ أَ<rule class=ikhafa>نص</rule>َحَ لَكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ <rule class=ham_wasl>ٱ</rule>للَّهُ يُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُغۡوِيَكُمۡ‌ۚ هُوَ رَبُّكُمۡ وَإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 12, 3, 225, 185, 90, 'false'
  );
  
  -- Ayah 35 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1508,
    'أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَیۡتُهُۥ فَعَلَیَّ إِجۡرَامِی وَأَنَا۠ بَرِیۤءࣱ مِّمَّا تُجۡرِمُونَ',
    'ام يقولون افتراه قل ان افتريته فعلي اجرامي وانا بريء مما تجرمون',
    'أَمۡ يَقُولُونَ <rule class=ham_wasl>ٱ</rule>فۡتَرَ<rule class=madda_normal>ٮٰ</rule>هُ‌ۖ قُلۡ إِنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَيۡتُهُ<rule class=madda_normal>ۥ</rule> فَعَلَىَّ إِ<rule class=qalaqah>جۡ</rule>رَامِى وَأَنَاۡ بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 12, 3, 225, 185, 90, 'false'
  );
  
  -- Ayah 36 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1509,
    'وَأُوحِیَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن یُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَىِٕسۡ بِمَا كَانُوا۟ یَفۡعَلُونَ',
    'واوحي الى نوح انه لن يؤمن من قومك الا من قد امن فلا تبتئس بما كانوا يفعلون',
    'وَأُوحِىَ إِلَىٰ نُوحٍ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِكَ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> ءَامَنَ فَلَا تَ<rule class=qalaqah>بۡ</rule>تَئِسۡ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 12, 3, 225, 186, 90, 'false'
  );
  
  -- Ayah 37 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1510,
    'وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡیُنِنَا وَوَحۡیِنَا وَلَا تُخَـٰطِبۡنِی فِی ٱلَّذِینَ ظَلَمُوۤا۟ إِنَّهُم مُّغۡرَقُونَ',
    'واصنع الفلك باعيننا ووحينا ولا تخاطبني في الذين ظلموا انهم مغرقون',
    'وَ<rule class=ham_wasl>ٱ</rule>صۡنَعِ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا وَلَا تُخَ<rule class=madda_normal>ـٰ</rule>طِ<rule class=qalaqah>بۡ</rule>نِى فِى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَم<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّغۡرَق<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 12, 3, 225, 186, 90, 'false'
  );
  
  -- Ayah 38 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1511,
    'وَیَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَیۡهِ مَلَأࣱ مِّن قَوۡمِهِۦ سَخِرُوا۟ مِنۡهُۚ قَالَ إِن تَسۡخَرُوا۟ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ',
    'ويصنع الفلك وكلما مر عليه ملا من قومه سخروا منه قال ان تسخروا منا فانا نسخر منكم كما تسخرون',
    'وَيَصۡنَعُ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَيۡهِ مَلَ<rule class=idgham_ghunnah>أٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_normal>ِۦ</rule> سَخِرُو<rule class=slnt>اۡ</rule> مِنۡهُ‌ۚ قَالَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡخَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>نّ</rule>َا فَإِ<rule class=ghunnah>نّ</rule>َا نَسۡخَرُ مِ<rule class=ikhafa>نك</rule>ُمۡ كَمَا تَسۡخَر<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 12, 3, 226, 186, 90, 'false'
  );
  
  -- Ayah 39 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1512,
    'فَسَوۡفَ تَعۡلَمُونَ مَن یَأۡتِیهِ عَذَابࣱ یُخۡزِیهِ وَیَحِلُّ عَلَیۡهِ عَذَابࣱ مُّقِیمٌ',
    'فسوف تعلمون من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم',
    'فَسَوۡفَ تَعۡلَمُونَ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيهِ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّق<rule class=madda_permissible>ِي</rule>مٌ ٣٩',
    39, 12, 3, 226, 186, 90, 'false'
  );
  
  -- Ayah 40 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1513,
    'حَتَّىٰۤ إِذَا جَاۤءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِیهَا مِن كُلࣲّ زَوۡجَیۡنِ ٱثۡنَیۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَیۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَاۤ ءَامَنَ مَعَهُۥۤ إِلَّا قَلِیلࣱ',
    'حتى اذا جاء امرنا وفار التنور قلنا احمل فيها من كل زوجين اثنين واهلك الا من سبق عليه القول ومن امن وما امن معه الا قليل',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُنَا وَفَارَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=ghunnah>نّ</rule>ُورُ قُلۡنَا <rule class=ham_wasl>ٱ</rule>حۡمِلۡ فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>ز</rule>َوۡجَيۡنِ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبَقَ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ وَمَنۡ ءَامَنَ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَنَ مَعَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا قَل<rule class=madda_permissible>ِي</rule>لٌ ٤٠',
    40, 12, 3, 226, 186, 90, 'false'
  );
  
  -- Ayah 41 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1514,
    '۞ وَقَالَ ٱرۡكَبُوا۟ فِیهَا بِسۡمِ ٱللَّهِ مَجۡرٜىٰهَا وَمُرۡسَىٰهَاۤۚ إِنَّ رَبِّی لَغَفُورࣱ رَّحِیمࣱ',
    'وقال اركبوا فيها بسم الله مجراها ومرساها ان ربي لغفور رحيم',
    '۞وَقَالَ <rule class=ham_wasl>ٱ</rule>رۡكَبُو<rule class=slnt>اۡ</rule> فِيهَا بِسۡمِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَ<rule class=qalaqah>جۡ</rule>ر۪<rule class=madda_normal>ٮٰ</rule>هَا وَمُرۡسَ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ رَبِّى لَغَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٤١',
    41, 12, 3, 226, 186, 91, 'false'
  );
  
  -- Ayah 42 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1515,
    'وَهِیَ تَجۡرِی بِهِمۡ فِی مَوۡجࣲ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِی مَعۡزِلࣲ یَـٰبُنَیَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَـٰفِرِینَ',
    'وهي تجري بهم في موج كالجبال ونادى نوح ابنه وكان في معزل يا بني اركب معنا ولا تكن مع الكافرين',
    'وَهِىَ تَ<rule class=qalaqah>جۡ</rule>رِى بِهِمۡ فِى مَوۡ<rule class=ikhafa>جٍ</rule> <rule class=ikhafa>ك</rule>َ<rule class=ham_wasl>ٱ</rule>لۡجِبَالِ وَنَادَىٰ نُوحٌ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَهُ<rule class=madda_normal>ۥ</rule> وَكَانَ فِى مَعۡزِ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_normal>ـٰ</rule>بُنَىَّ <rule class=ham_wasl>ٱ</rule>رۡكَ<rule class=idgham_mutajanisayn>ب</rule> <rule class=ghunnah>مّ</rule>َعَنَا وَلَا تَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>َّعَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 12, 3, 226, 186, 91, 'false'
  );
  
  -- Ayah 43 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1516,
    'قَالَ سَـَٔاوِیۤ إِلَىٰ جَبَلࣲ یَعۡصِمُنِی مِنَ ٱلۡمَاۤءِۚ قَالَ لَا عَاصِمَ ٱلۡیَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَیۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِینَ',
    'قال ساوي الى جبل يعصمني من الماء قال لا عاصم اليوم من امر الله الا من رحم وحال بينهما الموج فكان من المغرقين',
    'قَالَ سَـَٔـاو<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ جَبَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡصِمُنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ قَالَ لَا عَاصِمَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ مِنۡ أَمۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَّا م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِمَ‌ۚ وَحَالَ بَيۡنَهُمَا <rule class=ham_wasl>ٱ</rule>لۡمَوۡجُ فَكَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُغۡرَق<rule class=madda_permissible>ِي</rule>نَ ٤٣',
    43, 12, 3, 226, 186, 91, 'false'
  );
  
  -- Ayah 44 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1517,
    'وَقِیلَ یَـٰۤأَرۡضُ ٱبۡلَعِی مَاۤءَكِ وَیَـٰسَمَاۤءُ أَقۡلِعِی وَغِیضَ ٱلۡمَاۤءُ وَقُضِیَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِیِّۖ وَقِیلَ بُعۡدࣰا لِّلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'وقيل يا ارض ابلعي ماءك ويا سماء اقلعي وغيض الماء وقضي الامر واستوت على الجودي وقيل بعدا للقوم الظالمين',
    'وَقِيلَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَرۡضُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>لَعِى م<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكِ وَيَ<rule class=madda_normal>ـٰ</rule>سَم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ أَ<rule class=qalaqah>قۡ</rule>لِعِى وَغِيضَ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَقُضِىَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ وَ<rule class=ham_wasl>ٱ</rule>سۡتَوَتۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡجُودِىِّ‌ۖ وَقِيلَ بُعۡ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤٤',
    44, 12, 3, 226, 186, 91, 'false'
  );
  
  -- Ayah 45 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1518,
    'وَنَادَىٰ نُوحࣱ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِی مِنۡ أَهۡلِی وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَـٰكِمِینَ',
    'ونادى نوح ربه فقال رب ان ابني من اهلي وان وعدك الحق وانت احكم الحاكمين',
    'وَنَادَىٰ نُو<rule class=idgham_wo_ghunnah>حٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبَّهُ<rule class=madda_normal>ۥ</rule> فَقَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِى مِنۡ أَهۡلِى وَإِ<rule class=ghunnah>نّ</rule>َ وَعۡدَكَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَأَ<rule class=ikhafa>نت</rule>َ أَحۡكَمُ <rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>كِم<rule class=madda_permissible>ِي</rule>نَ ٤٥',
    45, 12, 3, 226, 186, 91, 'false'
  );
  
  -- Ayah 46 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1519,
    'قَالَ یَـٰنُوحُ إِنَّهُۥ لَیۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَیۡرُ صَـٰلِحࣲۖ فَلَا تَسۡـَٔلۡنِ مَا لَیۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّیۤ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَـٰهِلِینَ',
    'قال يا نوح انه ليس من اهلك انه عمل غير صالح فلا تسالن ما ليس لك به علم اني اعظك ان تكون من الجاهلين',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>نُوحُ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَيۡسَ مِنۡ أَهۡلِكَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَمَلٌ غَيۡرُ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َلَا تَسۡــَٔلۡنِ مَا لَيۡسَ لَكَ بِه<rule class=madda_normal>ِۦ</rule> عِلۡمٌ‌ۖ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعِظُكَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِل<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 12, 3, 227, 186, 91, 'false'
  );
  
  -- Ayah 47 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1520,
    'قَالَ رَبِّ إِنِّیۤ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَیۡسَ لِی بِهِۦ عِلۡمࣱۖ وَإِلَّا تَغۡفِرۡ لِی وَتَرۡحَمۡنِیۤ أَكُن مِّنَ ٱلۡخَـٰسِرِینَ',
    'قال رب اني اعوذ بك ان اسالك ما ليس لي به علم والا تغفر لي وترحمني اكن من الخاسرين',
    'قَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعُوذُ بِكَ أَنۡ أَسۡــَٔلَكَ مَا لَيۡسَ لِى بِه<rule class=madda_normal>ِۦ</rule> عِلۡ<rule class=idgham_ghunnah>مٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِلَّا تَغۡفِرۡ لِى وَتَرۡحَمۡن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 12, 3, 227, 186, 91, 'false'
  );
  
  -- Ayah 48 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1521,
    'قِیلَ یَـٰنُوحُ ٱهۡبِطۡ بِسَلَـٰمࣲ مِّنَّا وَبَرَكَـٰتٍ عَلَیۡكَ وَعَلَىٰۤ أُمَمࣲ مِّمَّن مَّعَكَۚ وَأُمَمࣱ سَنُمَتِّعُهُمۡ ثُمَّ یَمَسُّهُم مِّنَّا عَذَابٌ أَلِیمࣱ',
    'قيل يا نوح اهبط بسلام منا وبركات عليك وعلى امم ممن معك وامم سنمتعهم ثم يمسهم منا عذاب اليم',
    'قِيلَ يَ<rule class=madda_normal>ـٰ</rule>نُوحُ <rule class=ham_wasl>ٱ</rule>هۡبِ<rule class=qalaqah>طۡ</rule> بِسَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا وَبَرَكَ<rule class=madda_normal>ـٰ</rule>تٍ عَلَيۡكَ وَعَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُمَ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعَكَ‌ۚ وَأُمَ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>س</rule>َنُمَتِّعُهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يَمَسُّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٤٨',
    48, 12, 3, 227, 186, 91, 'false'
  );
  
  -- Ayah 49 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1522,
    'تِلۡكَ مِنۡ أَنۢبَاۤءِ ٱلۡغَیۡبِ نُوحِیهَاۤ إِلَیۡكَۖ مَا كُنتَ تَعۡلَمُهَاۤ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَـٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَـٰقِبَةَ لِلۡمُتَّقِینَ',
    'تلك من انباء الغيب نوحيها اليك ما كنت تعلمها انت ولا قومك من قبل هذا فاصبر ان العاقبة للمتقين',
    'تِلۡكَ مِنۡ أَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ نُوحِيه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ‌ۖ مَا كُ<rule class=ikhafa>نت</rule>َ تَعۡلَمُه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ وَلَا قَوۡمُكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۖ فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>قِبَةَ لِلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٤٩',
    49, 12, 3, 227, 186, 91, 'false'
  );
  
  -- Ayah 50 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1523,
    'وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ',
    'والى عاد اخاهم هودا قال يا قوم اعبدوا الله ما لكم من اله غيره ان انتم الا مفترون',
    'وَإِلَىٰ عَادٍ أَخَاهُمۡ هُو<rule class=ikhafa>دًا‌ۚ</rule> <rule class=ikhafa>ق</rule>َالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> إِنۡ أَ<rule class=ikhafa>نت</rule>ُمۡ إِلَّا مُفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 12, 3, 227, 187, 91, 'false'
  );
  
  -- Ayah 51 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1524,
    'یَـٰقَوۡمِ لَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ أَجۡرًاۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱلَّذِی فَطَرَنِیۤۚ أَفَلَا تَعۡقِلُونَ',
    'يا قوم لا اسالكم عليه اجرا ان اجري الا على الذي فطرني افلا تعقلون',
    'يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ ل<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ أَ<rule class=qalaqah>جۡ</rule>رًا‌ۖ إِنۡ أَ<rule class=qalaqah>جۡ</rule>رِىَ إِلَّا عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِى فَطَرَن<rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 12, 3, 227, 187, 91, 'false'
  );
  
  -- Ayah 52 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1525,
    'وَیَـٰقَوۡمِ ٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ ثُمَّ تُوبُوۤا۟ إِلَیۡهِ یُرۡسِلِ ٱلسَّمَاۤءَ عَلَیۡكُم مِّدۡرَارࣰا وَیَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡا۟ مُجۡرِمِینَ',
    'ويا قوم استغفروا ربكم ثم توبوا اليه يرسل السماء عليكم مدرارا ويزدكم قوة الى قوتكم ولا تتولوا مجرمين',
    'وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ تُوب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِ يُرۡسِلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=qalaqah>دۡ</rule>رَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َيَزِ<rule class=qalaqah>دۡ</rule>كُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡ<rule class=slnt>اۡ</rule> مُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٥٢',
    52, 12, 3, 227, 187, 91, 'false'
  );
  
  -- Ayah 53 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1526,
    'قَالُوا۟ یَـٰهُودُ مَا جِئۡتَنَا بِبَیِّنَةࣲ وَمَا نَحۡنُ بِتَارِكِیۤ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِینَ',
    'قالوا يا هود ما جئتنا ببينة وما نحن بتاركي الهتنا عن قولك وما نحن لك بمؤمنين',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>هُودُ مَا جِئۡتَنَا بِبَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا نَحۡنُ بِتَارِك<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَالِهَتِنَا عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 12, 3, 227, 187, 91, 'false'
  );
  
  -- Ayah 54 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1527,
    'إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوۤءࣲۗ قَالَ إِنِّیۤ أُشۡهِدُ ٱللَّهَ وَٱشۡهَدُوۤا۟ أَنِّی بَرِیۤءࣱ مِّمَّا تُشۡرِكُونَ',
    'ان نقول الا اعتراك بعض الهتنا بسوء قال اني اشهد الله واشهدوا اني بريء مما تشركون',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّقُولُ إِلَّا <rule class=ham_wasl>ٱ</rule>عۡتَرَ<rule class=madda_normal>ٮٰ</rule>كَ بَعۡضُ ءَالِهَتِنَا بِس<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ‌ۗ</rule> <rule class=ikhafa>ق</rule>َالَ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُشۡهِدُ <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>شۡهَد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>ِى بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 12, 3, 228, 187, 91, 'false'
  );
  
  -- Ayah 55 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1528,
    'مِن دُونِهِۦۖ فَكِیدُونِی جَمِیعࣰا ثُمَّ لَا تُنظِرُونِ',
    'من دونه فكيدوني جميعا ثم لا تنظرون',
    'مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَكِيدُونِى جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ لَا تُ<rule class=ikhafa>نظ</rule>ِر<rule class=madda_permissible>ُو</rule>نِ ٥٥',
    55, 12, 3, 228, 187, 91, 'false'
  );
  
  -- Ayah 56 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1529,
    'إِنِّی تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّی وَرَبِّكُمۚ مَّا مِن دَاۤبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِیَتِهَاۤۚ إِنَّ رَبِّی عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'اني توكلت على الله ربي وربكم ما من دابة الا هو اخذ بناصيتها ان ربي على صراط مستقيم',
    'إِ<rule class=ghunnah>نّ</rule>ِى تَوَكَّلۡتُ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ رَبِّى وَرَبِّك<rule class=idgham_shafawi>ُم‌ۚ</rule> <rule class=idgham_shafawi>م</rule>َّا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّةٍ إِلَّا هُوَ ءَاخِ<rule class=iqlab>ذُۢ</rule> <rule class=iqlab>ب</rule>ِنَاصِيَتِه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ رَبِّى عَلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٥٦',
    56, 12, 3, 228, 187, 91, 'false'
  );
  
  -- Ayah 57 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1530,
    'فَإِن تَوَلَّوۡا۟ فَقَدۡ أَبۡلَغۡتُكُم مَّاۤ أُرۡسِلۡتُ بِهِۦۤ إِلَیۡكُمۡۚ وَیَسۡتَخۡلِفُ رَبِّی قَوۡمًا غَیۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَیۡـًٔاۚ إِنَّ رَبِّی عَلَىٰ كُلِّ شَیۡءٍ حَفِیظࣱ',
    'فان تولوا فقد ابلغتكم ما ارسلت به اليكم ويستخلف ربي قوما غيركم ولا تضرونه شيئا ان ربي على كل شيء حفيظ',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=qalaqah>بۡ</rule>لَغۡتُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡتُ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَيۡكُمۡ‌ۚ وَيَسۡتَخۡلِفُ رَبِّى قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُ<rule class=madda_normal>ۥ</rule> شَيۡــًٔا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى عَلَىٰ كُلِّ شَىۡءٍ حَف<rule class=madda_permissible>ِي</rule>ظٌ ٥٧',
    57, 12, 3, 228, 187, 91, 'false'
  );
  
  -- Ayah 58 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1531,
    'وَلَمَّا جَاۤءَ أَمۡرُنَا نَجَّیۡنَا هُودࣰا وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَنَجَّیۡنَـٰهُم مِّنۡ عَذَابٍ غَلِیظࣲ',
    'ولما جاء امرنا نجينا هودا والذين امنوا معه برحمة منا ونجيناهم من عذاب غليظ',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُنَا نَجَّيۡنَا هُو<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> بِرَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا وَنَجَّيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَذَابٍ غَل<rule class=madda_permissible>ِي</rule>ظٍ ٥٨',
    58, 12, 3, 228, 187, 91, 'false'
  );
  
  -- Ayah 59 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1532,
    'وَتِلۡكَ عَادࣱۖ جَحَدُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ وَعَصَوۡا۟ رُسُلَهُۥ وَٱتَّبَعُوۤا۟ أَمۡرَ كُلِّ جَبَّارٍ عَنِیدࣲ',
    'وتلك عاد جحدوا بايات ربهم وعصوا رسله واتبعوا امر كل جبار عنيد',
    'وَتِلۡكَ عَا<rule class=ikhafa>دٌ‌ۖ</rule> <rule class=ikhafa>ج</rule>َحَدُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ وَعَصَوۡ<rule class=slnt>اۡ</rule> رُسُلَهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّبَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرَ كُلِّ جَبَّارٍ عَن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٥٩',
    59, 12, 3, 228, 187, 91, 'false'
  );
  
  -- Ayah 60 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1533,
    'وَأُتۡبِعُوا۟ فِی هَـٰذِهِ ٱلدُّنۡیَا لَعۡنَةࣰ وَیَوۡمَ ٱلۡقِیَـٰمَةِۗ أَلَاۤ إِنَّ عَادࣰا كَفَرُوا۟ رَبَّهُمۡۗ أَلَا بُعۡدࣰا لِّعَادࣲ قَوۡمِ هُودࣲ',
    'واتبعوا في هذه الدنيا لعنة ويوم القيامة الا ان عادا كفروا ربهم الا بعدا لعاد قوم هود',
    'وَأُتۡبِعُو<rule class=slnt>اۡ</rule> فِى هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا لَعۡنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ عَا<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ك</rule>َفَرُو<rule class=slnt>اۡ</rule> رَبَّهُمۡ‌ۗ أَلَا بُعۡ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّعَا<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ق</rule>َوۡمِ ه<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٍ ٦٠',
    60, 12, 3, 228, 187, 91, 'false'
  );
  
  -- Ayah 61 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1534,
    '۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَـٰلِحࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِیهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوۤا۟ إِلَیۡهِۚ إِنَّ رَبِّی قَرِیبࣱ مُّجِیبࣱ',
    'والى ثمود اخاهم صالحا قال يا قوم اعبدوا الله ما لكم من اله غيره هو انشاكم من الارض واستعمركم فيها فاستغفروه ثم توبوا اليه ان ربي قريب مجيب',
    '۞وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا‌ۚ</rule> <rule class=ikhafa>ق</rule>َالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_normal>ۥ</rule>‌ۖ هُوَ أَ<rule class=ikhafa>نش</rule>َأَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule>سۡتَعۡمَرَكُمۡ فِيهَا فَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرُوهُ ثُ<rule class=ghunnah>مّ</rule>َ تُوب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى قَرِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّج<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٦١',
    61, 12, 3, 228, 188, 92, 'false'
  );
  
  -- Ayah 62 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1535,
    'قَالُوا۟ یَـٰصَـٰلِحُ قَدۡ كُنتَ فِینَا مَرۡجُوࣰّا قَبۡلَ هَـٰذَاۤۖ أَتَنۡهَىٰنَاۤ أَن نَّعۡبُدَ مَا یَعۡبُدُ ءَابَاۤؤُنَا وَإِنَّنَا لَفِی شَكࣲّ مِّمَّا تَدۡعُونَاۤ إِلَیۡهِ مُرِیبࣲ',
    'قالوا يا صالح قد كنت فينا مرجوا قبل هذا اتنهانا ان نعبد ما يعبد اباؤنا واننا لفي شك مما تدعونا اليه مريب',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>صَ<rule class=madda_normal>ـٰ</rule>لِحُ قَ<rule class=qalaqah>دۡ</rule> كُ<rule class=ikhafa>نت</rule>َ فِينَا مَرۡجُو<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لَ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> أَتَنۡهَ<rule class=madda_normal>ـٰ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّعۡبُدَ مَا يَعۡبُدُ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا وَإِ<rule class=ghunnah>نّ</rule>َنَا لَفِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَ<rule class=qalaqah>دۡ</rule>عُون<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ مُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٦٢',
    62, 12, 3, 228, 188, 92, 'false'
  );
  
  -- Ayah 63 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1536,
    'قَالَ یَـٰقَوۡمِ أَرَءَیۡتُمۡ إِن كُنتُ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّی وَءَاتَىٰنِی مِنۡهُ رَحۡمَةࣰ فَمَن یَنصُرُنِی مِنَ ٱللَّهِ إِنۡ عَصَیۡتُهُۥۖ فَمَا تَزِیدُونَنِی غَیۡرَ تَخۡسِیرࣲ',
    'قال يا قوم ارايتم ان كنت على بينة من ربي واتاني منه رحمة فمن ينصرني من الله ان عصيته فما تزيدونني غير تخسير',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ أَرَءَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُ عَلَىٰ بَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّى وَءَاتَ<rule class=madda_normal>ـٰ</rule>نِى مِنۡهُ رَحۡمَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرُنِى مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِنۡ عَصَيۡتُهُ<rule class=madda_normal>ۥ</rule>‌ۖ فَمَا تَزِيدُونَنِى غَيۡرَ تَخۡس<rule class=madda_permissible>ِي</rule>رٍ ٦٣',
    63, 12, 3, 229, 188, 92, 'false'
  );
  
  -- Ayah 64 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1537,
    'وَیَـٰقَوۡمِ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَایَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِیۤ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوۤءࣲ فَیَأۡخُذَكُمۡ عَذَابࣱ قَرِیبࣱ',
    'ويا قوم هذه ناقة الله لكم اية فذروها تاكل في ارض الله ولا تمسوها بسوء فياخذكم عذاب قريب',
    'وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> نَاقَةُ <rule class=ham_wasl>ٱ</rule>للَّهِ لَكُمۡ ءَايَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َذَرُوهَا تَأۡكُلۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡضِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا تَمَسُّوهَا بِس<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ف</rule>َيَأۡخُذَكُمۡ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ق</rule>َر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٦٤',
    64, 12, 3, 229, 188, 92, 'false'
  );
  
  -- Ayah 65 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1538,
    'فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِی دَارِكُمۡ ثَلَـٰثَةَ أَیَّامࣲۖ ذَ ٰ⁠لِكَ وَعۡدٌ غَیۡرُ مَكۡذُوبࣲ',
    'فعقروها فقال تمتعوا في داركم ثلاثة ايام ذلك وعد غير مكذوب',
    'فَعَقَرُوهَا فَقَالَ تَمَتَّعُو<rule class=slnt>اۡ</rule> فِى دَارِكُمۡ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَةَ أَيَّا<rule class=ikhafa>مٍ‌ۖ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ وَعۡدٌ غَيۡرُ مَكۡذ<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ٍ ٦٥',
    65, 12, 3, 229, 188, 92, 'false'
  );
  
  -- Ayah 66 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1539,
    'فَلَمَّا جَاۤءَ أَمۡرُنَا نَجَّیۡنَا صَـٰلِحࣰا وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَمِنۡ خِزۡیِ یَوۡمِىِٕذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِیُّ ٱلۡعَزِیزُ',
    'فلما جاء امرنا نجينا صالحا والذين امنوا معه برحمة منا ومن خزي يومئذ ان ربك هو القوي العزيز',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُنَا نَجَّيۡنَا صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> بِرَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا وَمِنۡ خِزۡىِ يَوۡمِئِذٍ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡقَوِىُّ <rule class=ham_wasl>ٱ</rule>لۡعَز<rule class=madda_permissible>ِي</rule>زُ ٦٦',
    66, 12, 3, 229, 188, 92, 'false'
  );
  
  -- Ayah 67 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1540,
    'وَأَخَذَ ٱلَّذِینَ ظَلَمُوا۟ ٱلصَّیۡحَةُ فَأَصۡبَحُوا۟ فِی دِیَـٰرِهِمۡ جَـٰثِمِینَ',
    'واخذ الذين ظلموا الصيحة فاصبحوا في ديارهم جاثمين',
    'وَأَخَذَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡحَةُ فَأَصۡبَحُو<rule class=slnt>اۡ</rule> فِى دِيَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ جَ<rule class=madda_normal>ـٰ</rule>ثِم<rule class=madda_permissible>ِي</rule>نَ ٦٧',
    67, 12, 3, 229, 188, 92, 'false'
  );
  
  -- Ayah 68 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1541,
    'كَأَن لَّمۡ یَغۡنَوۡا۟ فِیهَاۤۗ أَلَاۤ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمۡۗ أَلَا بُعۡدࣰا لِّثَمُودَ',
    'كان لم يغنوا فيها الا ان ثمود كفروا ربهم الا بعدا لثمود',
    'كَأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَغۡنَوۡ<rule class=slnt>اۡ</rule> فِيه<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ ثَمُودَ<rule class=slnt>اۡ</rule> كَفَرُو<rule class=slnt>اۡ</rule> رَبَّهُمۡ‌ۗ أَلَا بُعۡ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّثَم<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>َ ٦٨',
    68, 12, 3, 229, 188, 92, 'false'
  );
  
  -- Ayah 69 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1542,
    'وَلَقَدۡ جَاۤءَتۡ رُسُلُنَاۤ إِبۡرَ ٰ⁠هِیمَ بِٱلۡبُشۡرَىٰ قَالُوا۟ سَلَـٰمࣰاۖ قَالَ سَلَـٰمࣱۖ فَمَا لَبِثَ أَن جَاۤءَ بِعِجۡلٍ حَنِیذࣲ',
    'ولقد جاءت رسلنا ابراهيم بالبشرى قالوا سلاما قال سلام فما لبث ان جاء بعجل حنيذ',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ رُسُلُن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ بِ<rule class=ham_wasl>ٱ</rule>لۡبُشۡرَىٰ قَالُو<rule class=slnt>اۡ</rule> سَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ سَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َمَا لَبِثَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِعِ<rule class=qalaqah>جۡ</rule>لٍ حَن<rule class=madda_permissible>ِي</rule>ذٍ ٦٩',
    69, 12, 3, 229, 189, 92, 'false'
  );
  
  -- Ayah 70 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1543,
    'فَلَمَّا رَءَاۤ أَیۡدِیَهُمۡ لَا تَصِلُ إِلَیۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِیفَةࣰۚ قَالُوا۟ لَا تَخَفۡ إِنَّاۤ أُرۡسِلۡنَاۤ إِلَىٰ قَوۡمِ لُوطࣲ',
    'فلما راى ايديهم لا تصل اليه نكرهم واوجس منهم خيفة قالوا لا تخف انا ارسلنا الى قوم لوط',
    'فَلَ<rule class=ghunnah>مّ</rule>َا رَء<rule class=madda_obligatory_monfasel>َآ</rule> أَيۡدِيَهُمۡ لَا تَصِلُ إِلَيۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِيفَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> لَا تَخَفۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ قَوۡمِ ل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ط</rule>ٍ ٧٠',
    70, 12, 3, 229, 189, 92, 'false'
  );
  
  -- Ayah 71 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1544,
    'وَٱمۡرَأَتُهُۥ قَاۤىِٕمَةࣱ فَضَحِكَتۡ فَبَشَّرۡنَـٰهَا بِإِسۡحَـٰقَ وَمِن وَرَاۤءِ إِسۡحَـٰقَ یَعۡقُوبَ',
    'وامراته قائمة فضحكت فبشرناها باسحاق ومن وراء اسحاق يعقوب',
    'وَ<rule class=ham_wasl>ٱ</rule>مۡرَأَتُهُ<rule class=madda_normal>ۥ</rule> ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َضَحِكَتۡ فَبَشَّرۡنَ<rule class=madda_normal>ـٰ</rule>هَا بِإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَم<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ يَعۡق<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>َ ٧١',
    71, 12, 3, 229, 189, 92, 'false'
  );
  
  -- Ayah 72 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1545,
    'قَالَتۡ یَـٰوَیۡلَتَىٰۤ ءَأَلِدُ وَأَنَا۠ عَجُوزࣱ وَهَـٰذَا بَعۡلِی شَیۡخًاۖ إِنَّ هَـٰذَا لَشَیۡءٌ عَجِیبࣱ',
    'قالت يا ويلتى االد وانا عجوز وهذا بعلي شيخا ان هذا لشيء عجيب',
    'قَالَتۡ يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَتَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَأَلِدُ وَأَنَاۡ عَجُو<rule class=idgham_ghunnah>زٌ</rule> <rule class=idgham_ghunnah>و</rule>َهَ<rule class=madda_normal>ـٰ</rule>ذَا بَعۡلِى شَيۡخًا‌ۖ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَشَىۡءٌ عَج<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٧٢',
    72, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 73 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1546,
    'قَالُوۤا۟ أَتَعۡجَبِینَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَـٰتُهُۥ عَلَیۡكُمۡ أَهۡلَ ٱلۡبَیۡتِۚ إِنَّهُۥ حَمِیدࣱ مَّجِیدࣱ',
    'قالوا اتعجبين من امر الله رحمت الله وبركاته عليكم اهل البيت انه حميد مجيد',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَتَعۡجَبِينَ مِنۡ أَمۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ رَحۡمَتُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَبَرَكَ<rule class=madda_normal>ـٰ</rule>تُهُ<rule class=madda_normal>ۥ</rule> عَلَيۡكُمۡ أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> حَمِي<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>َّج<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٧٣',
    73, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 74 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1547,
    'فَلَمَّا ذَهَبَ عَنۡ إِبۡرَ ٰ⁠هِیمَ ٱلرَّوۡعُ وَجَاۤءَتۡهُ ٱلۡبُشۡرَىٰ یُجَـٰدِلُنَا فِی قَوۡمِ لُوطٍ',
    'فلما ذهب عن ابراهيم الروع وجاءته البشرى يجادلنا في قوم لوط',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ذَهَبَ عَنۡ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّوۡعُ وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُ <rule class=ham_wasl>ٱ</rule>لۡبُشۡرَىٰ يُجَ<rule class=madda_normal>ـٰ</rule>دِلُنَا فِى قَوۡمِ ل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ط</rule>ٍ ٧٤',
    74, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 75 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1548,
    'إِنَّ إِبۡرَ ٰ⁠هِیمَ لَحَلِیمٌ أَوَّ ٰ⁠هࣱ مُّنِیبࣱ',
    'ان ابراهيم لحليم اواه منيب',
    'إِ<rule class=ghunnah>نّ</rule>َ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ لَحَلِيمٌ أَوّ<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٧٥',
    75, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 76 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1549,
    'یَـٰۤإِبۡرَ ٰ⁠هِیمُ أَعۡرِضۡ عَنۡ هَـٰذَاۤۖ إِنَّهُۥ قَدۡ جَاۤءَ أَمۡرُ رَبِّكَۖ وَإِنَّهُمۡ ءَاتِیهِمۡ عَذَابٌ غَیۡرُ مَرۡدُودࣲ',
    'يا ابراهيم اعرض عن هذا انه قد جاء امر ربك وانهم اتيهم عذاب غير مردود',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمُ أَعۡرِضۡ عَنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُ رَبِّكَ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ ءَاتِيهِمۡ عَذَابٌ غَيۡرُ مَرۡد<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٍ ٧٦',
    76, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 77 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1550,
    'وَلَمَّا جَاۤءَتۡ رُسُلُنَا لُوطࣰا سِیۤءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعࣰا وَقَالَ هَـٰذَا یَوۡمٌ عَصِیبࣱ',
    'ولما جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقال هذا يوم عصيب',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ رُسُلُنَا لُو<rule class=ikhafa>طًا</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ِى</rule>ٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا يَوۡمٌ عَص<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٧٧',
    77, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 78 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1551,
    'وَجَاۤءَهُۥ قَوۡمُهُۥ یُهۡرَعُونَ إِلَیۡهِ وَمِن قَبۡلُ كَانُوا۟ یَعۡمَلُونَ ٱلسَّیِّـَٔاتِۚ قَالَ یَـٰقَوۡمِ هَـٰۤؤُلَاۤءِ بَنَاتِی هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخۡزُونِ فِی ضَیۡفِیۤۖ أَلَیۡسَ مِنكُمۡ رَجُلࣱ رَّشِیدࣱ',
    'وجاءه قومه يهرعون اليه ومن قبل كانوا يعملون السيئات قال يا قوم هؤلاء بناتي هن اطهر لكم فاتقوا الله ولا تخزون في ضيفي اليس منكم رجل رشيد',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_normal>ۥ</rule> قَوۡمُهُ<rule class=madda_normal>ۥ</rule> يُهۡرَعُونَ إِلَيۡهِ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ كَانُو<rule class=slnt>اۡ</rule> يَعۡمَلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ‌ۚ قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بَنَاتِى هُ<rule class=ghunnah>نّ</rule>َ أَ<rule class=qalaqah>طۡ</rule>هَرُ لَكُمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَلَا تُخۡزُونِ فِى ضَيۡف<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> أَلَيۡسَ مِ<rule class=ikhafa>نك</rule>ُمۡ رَجُ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّش<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٧٨',
    78, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 79 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1552,
    'قَالُوا۟ لَقَدۡ عَلِمۡتَ مَا لَنَا فِی بَنَاتِكَ مِنۡ حَقࣲّ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِیدُ',
    'قالوا لقد علمت ما لنا في بناتك من حق وانك لتعلم ما نريد',
    'قَالُو<rule class=slnt>اۡ</rule> لَقَ<rule class=qalaqah>دۡ</rule> عَلِمۡتَ مَا لَنَا فِى بَنَاتِكَ مِنۡ حَ<rule class=idgham_ghunnah>قٍّ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َكَ لَتَعۡلَمُ مَا نُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٧٩',
    79, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 80 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1553,
    'قَالَ لَوۡ أَنَّ لِی بِكُمۡ قُوَّةً أَوۡ ءَاوِیۤ إِلَىٰ رُكۡنࣲ شَدِیدࣲ',
    'قال لو ان لي بكم قوة او اوي الى ركن شديد',
    'قَالَ لَوۡ أَ<rule class=ghunnah>نّ</rule>َ لِى بِكُمۡ قُوَّةً أَوۡ ءَاو<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ رُكۡ<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ش</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٨٠',
    80, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 81 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1554,
    'قَالُوا۟ یَـٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن یَصِلُوۤا۟ إِلَیۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعࣲ مِّنَ ٱلَّیۡلِ وَلَا یَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِیبُهَا مَاۤ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَیۡسَ ٱلصُّبۡحُ بِقَرِیبࣲ',
    'قالوا يا لوط انا رسل ربك لن يصلوا اليك فاسر باهلك بقطع من الليل ولا يلتفت منكم احد الا امراتك انه مصيبها ما اصابهم ان موعدهم الصبح اليس الصبح بقريب',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>لُوطُ إِ<rule class=ghunnah>نّ</rule>َا رُسُلُ رَبِّكَ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َصِل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡكَ‌ۖ فَأَسۡرِ بِأَهۡلِكَ بِقِ<rule class=qalaqah>طۡ</rule><rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَلَا يَلۡتَفِتۡ مِ<rule class=ikhafa>نك</rule>ُمۡ أَحَدٌ إِلَّا <rule class=ham_wasl>ٱ</rule>مۡرَأَتَكَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مُصِيبُهَا م<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ مَوۡعِدَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّ<rule class=qalaqah>بۡ</rule>حُ‌ۚ أَلَيۡسَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّ<rule class=qalaqah>بۡ</rule>حُ بِقَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٨١',
    81, 12, 3, 230, 189, 92, 'false'
  );
  
  -- Ayah 82 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1555,
    'فَلَمَّا جَاۤءَ أَمۡرُنَا جَعَلۡنَا عَـٰلِیَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَیۡهَا حِجَارَةࣰ مِّن سِجِّیلࣲ مَّنضُودࣲ',
    'فلما جاء امرنا جعلنا عاليها سافلها وامطرنا عليها حجارة من سجيل منضود',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُنَا جَعَلۡنَا عَ<rule class=madda_normal>ـٰ</rule>لِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ِجِّي<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=ikhafa>نض</rule><rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٍ ٨٢',
    82, 12, 3, 231, 189, 92, 'false'
  );
  
  -- Ayah 83 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1556,
    'مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِیَ مِنَ ٱلظَّـٰلِمِینَ بِبَعِیدࣲ',
    'مسومة عند ربك وما هي من الظالمين ببعيد',
    'مُّسَوَّمَةً عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ‌ۖ وَمَا هِىَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ بِبَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٨٣',
    83, 12, 3, 231, 189, 92, 'false'
  );
  
  -- Ayah 84 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1557,
    '۞ وَإِلَىٰ مَدۡیَنَ أَخَاهُمۡ شُعَیۡبࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۖ وَلَا تَنقُصُوا۟ ٱلۡمِكۡیَالَ وَٱلۡمِیزَانَۖ إِنِّیۤ أَرَىٰكُم بِخَیۡرࣲ وَإِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمࣲ مُّحِیطࣲ',
    'والى مدين اخاهم شعيبا قال يا قوم اعبدوا الله ما لكم من اله غيره ولا تنقصوا المكيال والميزان اني اراكم بخير واني اخاف عليكم عذاب يوم محيط',
    '۞وَإِلَىٰ مَ<rule class=qalaqah>دۡ</rule>يَنَ أَخَاهُمۡ شُعَيۡ<rule class=ikhafa>بًا‌ۚ</rule> <rule class=ikhafa>ق</rule>َالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَلَا تَ<rule class=ikhafa>نق</rule>ُصُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمِكۡيَالَ وَ<rule class=ham_wasl>ٱ</rule>لۡمِيزَانَ‌ۚ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَ<rule class=madda_normal>ٮٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَيۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّح<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ط</rule>ٍ ٨٤',
    84, 12, 3, 231, 190, 93, 'false'
  );
  
  -- Ayah 85 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1558,
    'وَیَـٰقَوۡمِ أَوۡفُوا۟ ٱلۡمِكۡیَالَ وَٱلۡمِیزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُوا۟ ٱلنَّاسَ أَشۡیَاۤءَهُمۡ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ',
    'ويا قوم اوفوا المكيال والميزان بالقسط ولا تبخسوا الناس اشياءهم ولا تعثوا في الارض مفسدين',
    'وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ أَوۡفُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمِكۡيَالَ وَ<rule class=ham_wasl>ٱ</rule>لۡمِيزَانَ بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۖ وَلَا تَ<rule class=qalaqah>بۡ</rule>خَسُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ أَشۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ وَلَا تَعۡثَوۡ<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 12, 3, 231, 190, 93, 'false'
  );
  
  -- Ayah 86 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1559,
    'بَقِیَّتُ ٱللَّهِ خَیۡرࣱ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِینَۚ وَمَاۤ أَنَا۠ عَلَیۡكُم بِحَفِیظࣲ',
    'بقيت الله خير لكم ان كنتم مؤمنين وما انا عليكم بحفيظ',
    'بَقِيَّتُ <rule class=ham_wasl>ٱ</rule>للَّهِ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِنِينَ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ عَلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِحَف<rule class=madda_permissible>ِي</rule>ظٍ ٨٦',
    86, 12, 3, 231, 190, 93, 'false'
  );
  
  -- Ayah 87 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1560,
    'قَالُوا۟ یَـٰشُعَیۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا یَعۡبُدُ ءَابَاۤؤُنَاۤ أَوۡ أَن نَّفۡعَلَ فِیۤ أَمۡوَ ٰ⁠لِنَا مَا نَشَـٰۤؤُا۟ۖ إِنَّكَ لَأَنتَ ٱلۡحَلِیمُ ٱلرَّشِیدُ',
    'قالوا يا شعيب اصلاتك تامرك ان نترك ما يعبد اباؤنا او ان نفعل في اموالنا ما نشاء انك لانت الحليم الرشيد',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>شُعَيۡبُ أَصَلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>تُكَ تَأۡمُرُكَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّتۡرُكَ مَا يَعۡبُدُ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُن<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡعَلَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لِنَا مَا نَشَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule>‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ لَأَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡحَلِيمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّش<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٨٧',
    87, 12, 3, 231, 190, 93, 'false'
  );
  
  -- Ayah 88 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1561,
    'قَالَ یَـٰقَوۡمِ أَرَءَیۡتُمۡ إِن كُنتُ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّی وَرَزَقَنِی مِنۡهُ رِزۡقًا حَسَنࣰاۚ وَمَاۤ أُرِیدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَاۤ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِیدُ إِلَّا ٱلۡإِصۡلَـٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِیقِیۤ إِلَّا بِٱللَّهِۚ عَلَیۡهِ تَوَكَّلۡتُ وَإِلَیۡهِ أُنِیبُ',
    'قال يا قوم ارايتم ان كنت على بينة من ربي ورزقني منه رزقا حسنا وما اريد ان اخالفكم الى ما انهاكم عنه ان اريد الا الاصلاح ما استطعت وما توفيقي الا بالله عليه توكلت واليه انيب',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ أَرَءَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُ عَلَىٰ بَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّى وَرَزَقَنِى مِنۡهُ رِزۡقًا حَسَ<rule class=idgham_ghunnah>نًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُرِيدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡهَ<rule class=madda_normal>ـٰ</rule>كُمۡ عَنۡهُ‌ۚ إِنۡ أُرِيدُ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡإِصۡلَ<rule class=madda_normal>ـٰ</rule>حَ مَا <rule class=ham_wasl>ٱ</rule>سۡتَطَعۡتُ‌ۚ وَمَا تَوۡفِيق<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَّا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ُ ٨٨',
    88, 12, 3, 231, 190, 93, 'false'
  );
  
  -- Ayah 89 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1562,
    'وَیَـٰقَوۡمِ لَا یَجۡرِمَنَّكُمۡ شِقَاقِیۤ أَن یُصِیبَكُم مِّثۡلُ مَاۤ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَـٰلِحࣲۚ وَمَا قَوۡمُ لُوطࣲ مِّنكُم بِبَعِیدࣲ',
    'ويا قوم لا يجرمنكم شقاقي ان يصيبكم مثل ما اصاب قوم نوح او قوم هود او قوم صالح وما قوم لوط منكم ببعيد',
    'وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ لَا يَ<rule class=qalaqah>جۡ</rule>رِمَ<rule class=ghunnah>نّ</rule>َكُمۡ شِقَاق<rule class=madda_obligatory_monfasel>ِىٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُصِيبَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّثۡلُ م<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا قَوۡمُ لُو<rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٨٩',
    89, 12, 3, 232, 190, 93, 'false'
  );
  
  -- Ayah 90 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1563,
    'وَٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ ثُمَّ تُوبُوۤا۟ إِلَیۡهِۚ إِنَّ رَبِّی رَحِیمࣱ وَدُودࣱ',
    'واستغفروا ربكم ثم توبوا اليه ان ربي رحيم ودود',
    'وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ تُوب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى رَحِي<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َد<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٌ ٩٠',
    90, 12, 3, 232, 190, 93, 'false'
  );
  
  -- Ayah 91 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1564,
    'قَالُوا۟ یَـٰشُعَیۡبُ مَا نَفۡقَهُ كَثِیرࣰا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِینَا ضَعِیفࣰاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَـٰكَۖ وَمَاۤ أَنتَ عَلَیۡنَا بِعَزِیزࣲ',
    'قالوا يا شعيب ما نفقه كثيرا مما تقول وانا لنراك فينا ضعيفا ولولا رهطك لرجمناك وما انت علينا بعزيز',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>شُعَيۡبُ مَا نَفۡقَهُ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَقُولُ وَإِ<rule class=ghunnah>نّ</rule>َا لَنَرَ<rule class=madda_normal>ٮٰ</rule>كَ فِينَا ضَعِي<rule class=idgham_ghunnah>فًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡلَا رَهۡطُكَ لَرَجَمۡنَ<rule class=madda_normal>ـٰ</rule>كَ‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ عَلَيۡنَا بِعَز<rule class=madda_permissible>ِي</rule>زٍ ٩١',
    91, 12, 3, 232, 190, 93, 'false'
  );
  
  -- Ayah 92 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1565,
    'قَالَ یَـٰقَوۡمِ أَرَهۡطِیۤ أَعَزُّ عَلَیۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَاۤءَكُمۡ ظِهۡرِیًّاۖ إِنَّ رَبِّی بِمَا تَعۡمَلُونَ مُحِیطࣱ',
    'قال يا قوم ارهطي اعز عليكم من الله واتخذتموه وراءكم ظهريا ان ربي بما تعملون محيط',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ أَرَهۡط<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعَزُّ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>تَّخَذۡتُمُوهُ وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ ظِهۡرِيًّا‌ۖ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى بِمَا تَعۡمَلُونَ مُح<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ط</rule>ٌ ٩٢',
    92, 12, 3, 232, 190, 93, 'false'
  );
  
  -- Ayah 93 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1566,
    'وَیَـٰقَوۡمِ ٱعۡمَلُوا۟ عَلَىٰ مَكَانَتِكُمۡ إِنِّی عَـٰمِلࣱۖ سَوۡفَ تَعۡلَمُونَ مَن یَأۡتِیهِ عَذَابࣱ یُخۡزِیهِ وَمَنۡ هُوَ كَـٰذِبࣱۖ وَٱرۡتَقِبُوۤا۟ إِنِّی مَعَكُمۡ رَقِیبࣱ',
    'ويا قوم اعملوا على مكانتكم اني عامل سوف تعلمون من ياتيه عذاب يخزيه ومن هو كاذب وارتقبوا اني معكم رقيب',
    'وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡمَلُو<rule class=slnt>اۡ</rule> عَلَىٰ مَكَانَتِكُمۡ إِ<rule class=ghunnah>نّ</rule>ِى عَ<rule class=madda_normal>ـٰ</rule>مِ<rule class=ikhafa>لٌ‌ۖ</rule> <rule class=ikhafa>س</rule>َوۡفَ تَعۡلَمُونَ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيهِ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡزِيهِ وَمَنۡ هُوَ كَ<rule class=madda_normal>ـٰ</rule>ذِ<rule class=idgham_ghunnah>بٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>رۡتَقِب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>ِى مَعَكُمۡ رَق<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٩٣',
    93, 12, 3, 232, 190, 93, 'false'
  );
  
  -- Ayah 94 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1567,
    'وَلَمَّا جَاۤءَ أَمۡرُنَا نَجَّیۡنَا شُعَیۡبࣰا وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَأَخَذَتِ ٱلَّذِینَ ظَلَمُوا۟ ٱلصَّیۡحَةُ فَأَصۡبَحُوا۟ فِی دِیَـٰرِهِمۡ جَـٰثِمِینَ',
    'ولما جاء امرنا نجينا شعيبا والذين امنوا معه برحمة منا واخذت الذين ظلموا الصيحة فاصبحوا في ديارهم جاثمين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُنَا نَجَّيۡنَا شُعَيۡ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> بِرَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا وَأَخَذَتِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡحَةُ فَأَصۡبَحُو<rule class=slnt>اۡ</rule> فِى دِيَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ جَ<rule class=madda_normal>ـٰ</rule>ثِم<rule class=madda_permissible>ِي</rule>نَ ٩٤',
    94, 12, 3, 232, 190, 93, 'false'
  );
  
  -- Ayah 95 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1568,
    'كَأَن لَّمۡ یَغۡنَوۡا۟ فِیهَاۤۗ أَلَا بُعۡدࣰا لِّمَدۡیَنَ كَمَا بَعِدَتۡ ثَمُودُ',
    'كان لم يغنوا فيها الا بعدا لمدين كما بعدت ثمود',
    'كَأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَغۡنَوۡ<rule class=slnt>اۡ</rule> فِيه<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> أَلَا بُعۡ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَ<rule class=qalaqah>دۡ</rule>يَنَ كَمَا بَعِدَتۡ ثَم<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ُ ٩٥',
    95, 12, 3, 232, 190, 93, 'false'
  );
  
  -- Ayah 96 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1569,
    'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔایَـٰتِنَا وَسُلۡطَـٰنࣲ مُّبِینٍ',
    'ولقد ارسلنا موسى باياتنا وسلطان مبين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا مُوسَىٰ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٩٦',
    96, 12, 3, 232, 191, 93, 'false'
  );
  
  -- Ayah 97 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1570,
    'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ فَٱتَّبَعُوۤا۟ أَمۡرَ فِرۡعَوۡنَۖ وَمَاۤ أَمۡرُ فِرۡعَوۡنَ بِرَشِیدࣲ',
    'الى فرعون وملئه فاتبعوا امر فرعون وما امر فرعون برشيد',
    'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِ<rule class=slnt>يۡ</rule>ه<rule class=madda_normal>ِۦ</rule> فَ<rule class=ham_wasl>ٱ</rule>تَّبَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرَ فِرۡعَوۡنَ‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡرُ فِرۡعَوۡنَ بِرَش<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٩٧',
    97, 12, 3, 232, 191, 93, 'false'
  );
  
  -- Ayah 98 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1571,
    'یَقۡدُمُ قَوۡمَهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ',
    'يقدم قومه يوم القيامة فاوردهم النار وبئس الورد المورود',
    'يَ<rule class=qalaqah>قۡ</rule>دُمُ قَوۡمَهُ<rule class=madda_normal>ۥ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فَأَوۡرَدَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡوِرۡدُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡر<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ُ ٩٨',
    98, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 99 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1572,
    'وَأُتۡبِعُوا۟ فِی هَـٰذِهِۦ لَعۡنَةࣰ وَیَوۡمَ ٱلۡقِیَـٰمَةِۚ بِئۡسَ ٱلرِّفۡدُ ٱلۡمَرۡفُودُ',
    'واتبعوا في هذه لعنة ويوم القيامة بئس الرفد المرفود',
    'وَأُتۡبِعُو<rule class=slnt>اۡ</rule> فِى هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> لَعۡنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ بِئۡسَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّفۡدُ <rule class=ham_wasl>ٱ</rule>لۡمَرۡف<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ُ ٩٩',
    99, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 100 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1573,
    'ذَ ٰ⁠لِكَ مِنۡ أَنۢبَاۤءِ ٱلۡقُرَىٰ نَقُصُّهُۥ عَلَیۡكَۖ مِنۡهَا قَاۤىِٕمࣱ وَحَصِیدࣱ',
    'ذلك من انباء القرى نقصه عليك منها قائم وحصيد',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ مِنۡ أَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ نَقُصُّهُ<rule class=madda_normal>ۥ</rule> عَلَيۡكَ‌ۖ مِنۡهَا ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َحَص<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٠٠',
    100, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 101 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1574,
    'وَمَا ظَلَمۡنَـٰهُمۡ وَلَـٰكِن ظَلَمُوۤا۟ أَنفُسَهُمۡۖ فَمَاۤ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِی یَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَیۡءࣲ لَّمَّا جَاۤءَ أَمۡرُ رَبِّكَۖ وَمَا زَادُوهُمۡ غَیۡرَ تَتۡبِیبࣲ',
    'وما ظلمناهم ولكن ظلموا انفسهم فما اغنت عنهم الهتهم التي يدعون من دون الله من شيء لما جاء امر ربك وما زادوهم غير تتبيب',
    'وَمَا ظَلَمۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>َلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ‌ۖ فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ <rule class=ham_wasl>ٱ</rule>لَّتِى يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_wo_ghunnah>َىۡءٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُ رَبِّكَ‌ۖ وَمَا زَادُوهُمۡ غَيۡرَ تَتۡب<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ١٠١',
    101, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 102 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1575,
    'وَكَذَ ٰ⁠لِكَ أَخۡذُ رَبِّكَ إِذَاۤ أَخَذَ ٱلۡقُرَىٰ وَهِیَ ظَـٰلِمَةٌۚ إِنَّ أَخۡذَهُۥۤ أَلِیمࣱ شَدِیدٌ',
    'وكذلك اخذ ربك اذا اخذ القرى وهي ظالمة ان اخذه اليم شديد',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَخۡذُ رَبِّكَ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَخَذَ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ وَهِىَ ظَ<rule class=madda_normal>ـٰ</rule>لِمَةٌ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ أَخۡذَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَلِي<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ش</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٠٢',
    102, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 103 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1576,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّمَنۡ خَافَ عَذَابَ ٱلۡـَٔاخِرَةِۚ ذَ ٰ⁠لِكَ یَوۡمࣱ مَّجۡمُوعࣱ لَّهُ ٱلنَّاسُ وَذَ ٰ⁠لِكَ یَوۡمࣱ مَّشۡهُودࣱ',
    'ان في ذلك لاية لمن خاف عذاب الاخرة ذلك يوم مجموع له الناس وذلك يوم مشهود',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَنۡ خَافَ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ يَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>جۡ</rule>مُو<rule class=idgham_wo_ghunnah>عٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ وَذ<rule class=madda_normal>ٰ</rule>لِكَ يَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>َّشۡه<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٌ ١٠٣',
    103, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 104 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1577,
    'وَمَا نُؤَخِّرُهُۥۤ إِلَّا لِأَجَلࣲ مَّعۡدُودࣲ',
    'وما نؤخره الا لاجل معدود',
    'وَمَا نُؤَخِّرُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا لِأَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡد<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٍ ١٠٤',
    104, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 105 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1578,
    'یَوۡمَ یَأۡتِ لَا تَكَلَّمُ نَفۡسٌ إِلَّا بِإِذۡنِهِۦۚ فَمِنۡهُمۡ شَقِیࣱّ وَسَعِیدࣱ',
    'يوم يات لا تكلم نفس الا باذنه فمنهم شقي وسعيد',
    'يَوۡمَ يَأۡتِ لَا تَكَلَّمُ نَفۡسٌ إِلَّا بِإِذۡنِه<rule class=madda_normal>ِۦ</rule>‌ۚ فَمِنۡهُمۡ شَقِ<rule class=idgham_ghunnah>ىٌّ</rule> <rule class=idgham_ghunnah>و</rule>َسَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٠٥',
    105, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 106 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1579,
    'فَأَمَّا ٱلَّذِینَ شَقُوا۟ فَفِی ٱلنَّارِ لَهُمۡ فِیهَا زَفِیرࣱ وَشَهِیقٌ',
    'فاما الذين شقوا ففي النار لهم فيها زفير وشهيق',
    'فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ شَقُو<rule class=slnt>اۡ</rule> فَفِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ لَهُمۡ فِيهَا زَفِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َشَه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ٌ ١٠٦',
    106, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 107 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1580,
    'خَـٰلِدِینَ فِیهَا مَا دَامَتِ ٱلسَّمَـٰوَ ٰ⁠تُ وَٱلۡأَرۡضُ إِلَّا مَا شَاۤءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالࣱ لِّمَا یُرِیدُ',
    'خالدين فيها ما دامت السماوات والارض الا ما شاء ربك ان ربك فعال لما يريد',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا مَا دَامَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ إِلَّا مَا ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبُّكَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ فَعَّا<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا يُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ١٠٧',
    107, 12, 3, 233, 191, 93, 'false'
  );
  
  -- Ayah 108 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1581,
    '۞ وَأَمَّا ٱلَّذِینَ سُعِدُوا۟ فَفِی ٱلۡجَنَّةِ خَـٰلِدِینَ فِیهَا مَا دَامَتِ ٱلسَّمَـٰوَ ٰ⁠تُ وَٱلۡأَرۡضُ إِلَّا مَا شَاۤءَ رَبُّكَۖ عَطَاۤءً غَیۡرَ مَجۡذُوذࣲ',
    'واما الذين سعدوا ففي الجنة خالدين فيها ما دامت السماوات والارض الا ما شاء ربك عطاء غير مجذوذ',
    '۞وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ سُعِدُو<rule class=slnt>اۡ</rule> فَفِى <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا مَا دَامَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ إِلَّا مَا ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبُّكَ‌ۖ عَط<rule class=madda_obligatory_mottasel>َا</rule>ٓءً غَيۡرَ مَ<rule class=qalaqah>جۡ</rule>ذ<rule class=madda_permissible>ُو</rule>ذٍ ١٠٨',
    108, 12, 3, 233, 191, 94, 'false'
  );
  
  -- Ayah 109 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1582,
    'فَلَا تَكُ فِی مِرۡیَةࣲ مِّمَّا یَعۡبُدُ هَـٰۤؤُلَاۤءِۚ مَا یَعۡبُدُونَ إِلَّا كَمَا یَعۡبُدُ ءَابَاۤؤُهُم مِّن قَبۡلُۚ وَإِنَّا لَمُوَفُّوهُمۡ نَصِیبَهُمۡ غَیۡرَ مَنقُوصࣲ',
    'فلا تك في مرية مما يعبد هؤلاء ما يعبدون الا كما يعبد اباؤهم من قبل وانا لموفوهم نصيبهم غير منقوص',
    'فَلَا تَكُ فِى مِرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَعۡبُدُ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ مَا يَعۡبُدُونَ إِلَّا كَمَا يَعۡبُدُ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َا لَمُوَفُّوهُمۡ نَصِيبَهُمۡ غَيۡرَ مَ<rule class=ikhafa>نق</rule><rule class=madda_permissible>ُو</rule>صٍ ١٠٩',
    109, 12, 3, 234, 191, 94, 'false'
  );
  
  -- Ayah 110 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1583,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ فَٱخۡتُلِفَ فِیهِۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَقُضِیَ بَیۡنَهُمۡۚ وَإِنَّهُمۡ لَفِی شَكࣲّ مِّنۡهُ مُرِیبࣲ',
    'ولقد اتينا موسى الكتاب فاختلف فيه ولولا كلمة سبقت من ربك لقضي بينهم وانهم لفي شك منه مريب',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ فَ<rule class=ham_wasl>ٱ</rule>خۡتُلِفَ فِيهِ‌ۚ وَلَوۡلَا كَلِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>س</rule>َبَقَتۡ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ لَقُضِىَ بَيۡنَهُمۡ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ لَفِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ مُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ١١٠',
    110, 12, 3, 234, 192, 94, 'false'
  );
  
  -- Ayah 111 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1584,
    'وَإِنَّ كُلࣰّا لَّمَّا لَیُوَفِّیَنَّهُمۡ رَبُّكَ أَعۡمَـٰلَهُمۡۚ إِنَّهُۥ بِمَا یَعۡمَلُونَ خَبِیرࣱ',
    'وان كلا لما ليوفينهم ربك اعمالهم انه بما يعملون خبير',
    'وَإِ<rule class=ghunnah>نّ</rule>َ كُل<rule class=idgham_wo_ghunnah>اًّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ghunnah>مّ</rule>َا لَيُوَفِّيَ<rule class=ghunnah>نّ</rule>َهُمۡ رَبُّكَ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِمَا يَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ١١١',
    111, 12, 3, 234, 192, 94, 'false'
  );
  
  -- Ayah 112 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1585,
    'فَٱسۡتَقِمۡ كَمَاۤ أُمِرۡتَ وَمَن تَابَ مَعَكَ وَلَا تَطۡغَوۡا۟ۚ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِیرࣱ',
    'فاستقم كما امرت ومن تاب معك ولا تطغوا انه بما تعملون بصير',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَقِمۡ كَم<rule class=madda_obligatory_monfasel>َآ</rule> أُمِرۡتَ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابَ مَعَكَ وَلَا تَ<rule class=qalaqah>طۡ</rule>غَوۡ<rule class=slnt>اۡ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ١١٢',
    112, 12, 3, 234, 192, 94, 'false'
  );
  
  -- Ayah 113 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1586,
    'وَلَا تَرۡكَنُوۤا۟ إِلَى ٱلَّذِینَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِیَاۤءَ ثُمَّ لَا تُنصَرُونَ',
    'ولا تركنوا الى الذين ظلموا فتمسكم النار وما لكم من دون الله من اولياء ثم لا تنصرون',
    'وَلَا تَرۡكَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> فَتَمَسَّكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ وَمَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مِنۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ثُ<rule class=ghunnah>مّ</rule>َ لَا تُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ١١٣',
    113, 12, 3, 234, 192, 94, 'false'
  );
  
  -- Ayah 114 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1587,
    'وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَیِ ٱلنَّهَارِ وَزُلَفࣰا مِّنَ ٱلَّیۡلِۚ إِنَّ ٱلۡحَسَنَـٰتِ یُذۡهِبۡنَ ٱلسَّیِّـَٔاتِۚ ذَ ٰ⁠لِكَ ذِكۡرَىٰ لِلذَّ ٰ⁠كِرِینَ',
    'واقم الصلاة طرفي النهار وزلفا من الليل ان الحسنات يذهبن السيئات ذلك ذكرى للذاكرين',
    'وَأَقِمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ طَرَفَىِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَزُلَ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡحَسَنَ<rule class=madda_normal>ـٰ</rule>تِ يُذۡهِ<rule class=qalaqah>بۡ</rule>نَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ ذِكۡرَىٰ لِلذّ<rule class=madda_normal>ٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ١١٤',
    114, 12, 3, 234, 192, 94, 'false'
  );
  
  -- Ayah 115 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1588,
    'وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا یُضِیعُ أَجۡرَ ٱلۡمُحۡسِنِینَ',
    'واصبر فان الله لا يضيع اجر المحسنين',
    'وَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُضِيعُ أَ<rule class=qalaqah>جۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١١٥',
    115, 12, 3, 234, 192, 94, 'false'
  );
  
  -- Ayah 116 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1589,
    'فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُو۟لُوا۟ بَقِیَّةࣲ یَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ فِی ٱلۡأَرۡضِ إِلَّا قَلِیلࣰا مِّمَّنۡ أَنجَیۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِینَ ظَلَمُوا۟ مَاۤ أُتۡرِفُوا۟ فِیهِ وَكَانُوا۟ مُجۡرِمِینَ',
    'فلولا كان من القرون من قبلكم اولو بقية ينهون عن الفساد في الارض الا قليلا ممن انجينا منهم واتبع الذين ظلموا ما اترفوا فيه وكانوا مجرمين',
    'فَلَوۡلَا كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقُرُونِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> بَقِيَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>َنۡهَوۡنَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡفَسَادِ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِلَّا قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َنۡ أَ<rule class=ikhafa>نج</rule>َيۡنَا مِنۡهُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>تَّبَعَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أُتۡرِفُو<rule class=slnt>اۡ</rule> فِيهِ وَكَانُو<rule class=slnt>اۡ</rule> مُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ١١٦',
    116, 12, 3, 234, 192, 94, 'false'
  );
  
  -- Ayah 117 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1590,
    'وَمَا كَانَ رَبُّكَ لِیُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمࣲ وَأَهۡلُهَا مُصۡلِحُونَ',
    'وما كان ربك ليهلك القرى بظلم واهلها مصلحون',
    'وَمَا كَانَ رَبُّكَ لِيُهۡلِكَ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ بِظُلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَهۡلُهَا مُصۡلِح<rule class=madda_permissible>ُو</rule>نَ ١١٧',
    117, 12, 3, 234, 192, 94, 'false'
  );
  
  -- Ayah 118 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1591,
    'وَلَوۡ شَاۤءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةࣰ وَ ٰ⁠حِدَةࣰۖ وَلَا یَزَالُونَ مُخۡتَلِفِینَ',
    'ولو شاء ربك لجعل الناس امة واحدة ولا يزالون مختلفين',
    'وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبُّكَ لَجَعَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَزَالُونَ مُخۡتَلِف<rule class=madda_permissible>ِي</rule>نَ ١١٨',
    118, 12, 3, 235, 192, 94, 'false'
  );
  
  -- Ayah 119 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1592,
    'إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَ ٰ⁠لِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِینَ',
    'الا من رحم ربك ولذلك خلقهم وتمت كلمة ربك لاملان جهنم من الجنة والناس اجمعين',
    'إِلَّا م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِمَ رَبُّكَ‌ۚ وَلِذ<rule class=madda_normal>ٰ</rule>لِكَ خَلَقَهُمۡ‌ۗ وَتَ<rule class=ghunnah>مّ</rule>َتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَ<rule class=ghunnah>نّ</rule>َ جَهَ<rule class=ghunnah>نّ</rule>َمَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>َةِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ١١٩',
    119, 12, 3, 235, 192, 94, 'false'
  );
  
  -- Ayah 120 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1593,
    'وَكُلࣰّا نَّقُصُّ عَلَیۡكَ مِنۡ أَنۢبَاۤءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ وَجَاۤءَكَ فِی هَـٰذِهِ ٱلۡحَقُّ وَمَوۡعِظَةࣱ وَذِكۡرَىٰ لِلۡمُؤۡمِنِینَ',
    'وكلا نقص عليك من انباء الرسل ما نثبت به فؤادك وجاءك في هذه الحق وموعظة وذكرى للمؤمنين',
    'وَكُل<rule class=idgham_ghunnah>اًّ</rule> <rule class=idgham_ghunnah>ن</rule>َّقُصُّ عَلَيۡكَ مِنۡ أَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلِ مَا نُثَبِّتُ بِه<rule class=madda_normal>ِۦ</rule> فُؤَادَكَ‌ۚ وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ فِى هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَمَوۡعِظَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َذِكۡرَىٰ لِلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٢٠',
    120, 12, 3, 235, 192, 94, 'false'
  );
  
  -- Ayah 121 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1594,
    'وَقُل لِّلَّذِینَ لَا یُؤۡمِنُونَ ٱعۡمَلُوا۟ عَلَىٰ مَكَانَتِكُمۡ إِنَّا عَـٰمِلُونَ',
    'وقل للذين لا يؤمنون اعملوا على مكانتكم انا عاملون',
    'وَقُل لِّلَّذِينَ لَا يُؤۡمِنُونَ <rule class=ham_wasl>ٱ</rule>عۡمَلُو<rule class=slnt>اۡ</rule> عَلَىٰ مَكَانَتِكُمۡ إِ<rule class=ghunnah>نّ</rule>َا عَ<rule class=madda_normal>ـٰ</rule>مِل<rule class=madda_permissible>ُو</rule>نَ ١٢١',
    121, 12, 3, 235, 192, 94, 'false'
  );
  
  -- Ayah 122 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1595,
    'وَٱنتَظِرُوۤا۟ إِنَّا مُنتَظِرُونَ',
    'وانتظروا انا منتظرون',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َظِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا مُ<rule class=ikhafa>نت</rule>َظِر<rule class=madda_permissible>ُو</rule>نَ ١٢٢',
    122, 12, 3, 235, 192, 94, 'false'
  );
  
  -- Ayah 123 Surah Hud
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    11,
    1596,
    'وَلِلَّهِ غَیۡبُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَإِلَیۡهِ یُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَیۡهِۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ',
    'ولله غيب السماوات والارض واليه يرجع الامر كله فاعبده وتوكل عليه وما ربك بغافل عما تعملون',
    'وَلِلَّهِ غَيۡبُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَإِلَيۡهِ يُرۡجَعُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ كُلُّهُ<rule class=madda_normal>ۥ</rule> فَ<rule class=ham_wasl>ٱ</rule>عۡبُ<rule class=qalaqah>دۡ</rule>هُ وَتَوَكَّلۡ عَلَيۡهِ‌ۚ وَمَا رَبُّكَ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٢٣',
    123, 12, 3, 235, 192, 94, 'false'
  );
  

-- Surah Yusuf
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (12, 'سُورَةُ يُوسُفَ', 'Yusuf', 'Joseph', 'Meccan', 111);

  -- Ayah 1 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1597,
    'الۤرۚ تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡمُبِینِ',
    'الر تلك ايات الكتاب المبين',
    'ا<rule class=madda_necessary>لٓ</rule>ر‌ۚ تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نِ ١',
    1, 12, 3, 235, 193, 94, 'false'
  );
  
  -- Ayah 2 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1598,
    'إِنَّاۤ أَنزَلۡنَـٰهُ قُرۡءَ ٰ⁠ نًا عَرَبِیࣰّا لَّعَلَّكُمۡ تَعۡقِلُونَ',
    'انا انزلناه قرانا عربيا لعلكم تعقلون',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ قُرۡء<rule class=madda_normal>ٰ</rule>نًا عَرَبِي<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّكُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 12, 3, 235, 193, 94, 'false'
  );
  
  -- Ayah 3 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1599,
    'نَحۡنُ نَقُصُّ عَلَیۡكَ أَحۡسَنَ ٱلۡقَصَصِ بِمَاۤ أَوۡحَیۡنَاۤ إِلَیۡكَ هَـٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ لَمِنَ ٱلۡغَـٰفِلِینَ',
    'نحن نقص عليك احسن القصص بما اوحينا اليك هذا القران وان كنت من قبله لمن الغافلين',
    'نَحۡنُ نَقُصُّ عَلَيۡكَ أَحۡسَنَ <rule class=ham_wasl>ٱ</rule>لۡقَصَصِ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ٣',
    3, 12, 3, 235, 193, 94, 'false'
  );
  
  -- Ayah 4 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1600,
    'إِذۡ قَالَ یُوسُفُ لِأَبِیهِ یَـٰۤأَبَتِ إِنِّی رَأَیۡتُ أَحَدَ عَشَرَ كَوۡكَبࣰا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَیۡتُهُمۡ لِی سَـٰجِدِینَ',
    'اذ قال يوسف لابيه يا ابت اني رايت احد عشر كوكبا والشمس والقمر رايتهم لي ساجدين',
    'إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَتِ إِ<rule class=ghunnah>نّ</rule>ِى رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ رَأَيۡتُهُمۡ لِى سَ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ٤',
    4, 12, 3, 235, 193, 94, 'false'
  );
  
  -- Ayah 5 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1601,
    'قَالَ یَـٰبُنَیَّ لَا تَقۡصُصۡ رُءۡیَاكَ عَلَىٰۤ إِخۡوَتِكَ فَیَكِیدُوا۟ لَكَ كَیۡدًاۖ إِنَّ ٱلشَّیۡطَـٰنَ لِلۡإِنسَـٰنِ عَدُوࣱّ مُّبِینࣱ',
    'قال يا بني لا تقصص رؤياك على اخوتك فيكيدوا لك كيدا ان الشيطان للانسان عدو مبين',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>بُنَىَّ لَا تَ<rule class=qalaqah>قۡ</rule>صُصۡ رُءۡيَاكَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِخۡوَتِكَ فَيَكِيدُو<rule class=slnt>اۡ</rule> لَكَ كَيۡدًا‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ لِلۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ عَدُ<rule class=idgham_ghunnah>وٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٥',
    5, 12, 3, 236, 193, 94, 'false'
  );
  
  -- Ayah 6 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1602,
    'وَكَذَ ٰ⁠لِكَ یَجۡتَبِیكَ رَبُّكَ وَیُعَلِّمُكَ مِن تَأۡوِیلِ ٱلۡأَحَادِیثِ وَیُتِمُّ نِعۡمَتَهُۥ عَلَیۡكَ وَعَلَىٰۤ ءَالِ یَعۡقُوبَ كَمَاۤ أَتَمَّهَا عَلَىٰۤ أَبَوَیۡكَ مِن قَبۡلُ إِبۡرَ ٰ⁠هِیمَ وَإِسۡحَـٰقَۚ إِنَّ رَبَّكَ عَلِیمٌ حَكِیمࣱ',
    'وكذلك يجتبيك ربك ويعلمك من تاويل الاحاديث ويتم نعمته عليك وعلى ال يعقوب كما اتمها على ابويك من قبل ابراهيم واسحاق ان ربك عليم حكيم',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ يَ<rule class=qalaqah>جۡ</rule>تَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡوِيلِ <rule class=ham_wasl>ٱ</rule>لۡأَحَادِيثِ وَيُتِ<rule class=ghunnah>مّ</rule>ُ نِعۡمَتَهُ<rule class=madda_normal>ۥ</rule> عَلَيۡكَ وَعَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَالِ يَعۡقُوبَ كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَتَ<rule class=ghunnah>مّ</rule>َهَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَبَوَيۡكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٦',
    6, 12, 3, 236, 193, 94, 'false'
  );
  
  -- Ayah 7 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1603,
    '۞ لَّقَدۡ كَانَ فِی یُوسُفَ وَإِخۡوَتِهِۦۤ ءَایَـٰتࣱ لِّلسَّاۤىِٕلِینَ',
    'لقد كان في يوسف واخوته ايات للسائلين',
    '۞لَّقَ<rule class=qalaqah>دۡ</rule> كَانَ فِى يُوسُفَ وَإِخۡوَتِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلسّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِل<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 12, 3, 236, 194, 95, 'false'
  );
  
  -- Ayah 8 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1604,
    'إِذۡ قَالُوا۟ لَیُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰۤ أَبِینَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِی ضَلَـٰلࣲ مُّبِینٍ',
    'اذ قالوا ليوسف واخوه احب الى ابينا منا ونحن عصبة ان ابانا لفي ضلال مبين',
    'إِذۡ قَالُو<rule class=slnt>اۡ</rule> لَيُوسُفُ وَأَخُوهُ أَحَبُّ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَبِينَا مِ<rule class=ghunnah>نّ</rule>َا وَنَحۡنُ عُصۡبَةٌ إِ<rule class=ghunnah>نّ</rule>َ أَبَانَا لَفِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٨',
    8, 12, 3, 236, 194, 95, 'false'
  );
  
  -- Ayah 9 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1605,
    'ٱقۡتُلُوا۟ یُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضࣰا یَخۡلُ لَكُمۡ وَجۡهُ أَبِیكُمۡ وَتَكُونُوا۟ مِنۢ بَعۡدِهِۦ قَوۡمࣰا صَـٰلِحِینَ',
    'اقتلوا يوسف او اطرحوه ارضا يخل لكم وجه ابيكم وتكونوا من بعده قوما صالحين',
    'ٱ<rule class=qalaqah>قۡ</rule>تُلُو<rule class=slnt>اۡ</rule> يُوسُفَ أَوِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>طۡ</rule>رَحُوهُ أَرۡ<rule class=idgham_ghunnah>ضًا</rule> <rule class=idgham_ghunnah>ي</rule>َخۡلُ لَكُمۡ وَ<rule class=qalaqah>جۡ</rule>هُ أَبِيكُمۡ وَتَكُونُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ص</rule>َ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٩',
    9, 12, 3, 236, 194, 95, 'false'
  );
  
  -- Ayah 10 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1606,
    'قَالَ قَاۤىِٕلࣱ مِّنۡهُمۡ لَا تَقۡتُلُوا۟ یُوسُفَ وَأَلۡقُوهُ فِی غَیَـٰبَتِ ٱلۡجُبِّ یَلۡتَقِطۡهُ بَعۡضُ ٱلسَّیَّارَةِ إِن كُنتُمۡ فَـٰعِلِینَ',
    'قال قائل منهم لا تقتلوا يوسف والقوه في غيابت الجب يلتقطه بعض السيارة ان كنتم فاعلين',
    'قَالَ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ لَا تَ<rule class=qalaqah>قۡ</rule>تُلُو<rule class=slnt>اۡ</rule> يُوسُفَ وَأَلۡقُوهُ فِى غَيَ<rule class=madda_normal>ـٰ</rule>بَتِ <rule class=ham_wasl>ٱ</rule>لۡجُبِّ يَلۡتَقِ<rule class=qalaqah>طۡ</rule>هُ بَعۡضُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيَّارَةِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ فَ<rule class=madda_normal>ـٰ</rule>عِل<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 12, 3, 236, 194, 95, 'false'
  );
  
  -- Ayah 11 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1607,
    'قَالُوا۟ یَـٰۤأَبَانَا مَا لَكَ لَا تَأۡمَ۬نَّا عَلَىٰ یُوسُفَ وَإِنَّا لَهُۥ لَنَـٰصِحُونَ',
    'قالوا يا ابانا ما لك لا تامنا على يوسف وانا له لناصحون',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَانَا مَا لَكَ لَا تَأۡمَ۫<rule class=ghunnah>نّ</rule>َا عَلَىٰ يُوسُفَ وَإِ<rule class=ghunnah>نّ</rule>َا لَهُ<rule class=madda_normal>ۥ</rule> لَنَ<rule class=madda_normal>ـٰ</rule>صِح<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 12, 3, 236, 194, 95, 'false'
  );
  
  -- Ayah 12 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1608,
    'أَرۡسِلۡهُ مَعَنَا غَدࣰا یَرۡتَعۡ وَیَلۡعَبۡ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ',
    'ارسله معنا غدا يرتع ويلعب وانا له لحافظون',
    'أَرۡسِلۡهُ مَعَنَا غَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>ي</rule>َرۡتَعۡ وَيَلۡعَ<rule class=qalaqah>بۡ</rule> وَإِ<rule class=ghunnah>نّ</rule>َا لَهُ<rule class=madda_normal>ۥ</rule> لَحَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 12, 3, 236, 194, 95, 'false'
  );
  
  -- Ayah 13 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1609,
    'قَالَ إِنِّی لَیَحۡزُنُنِیۤ أَن تَذۡهَبُوا۟ بِهِۦ وَأَخَافُ أَن یَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَـٰفِلُونَ',
    'قال اني ليحزنني ان تذهبوا به واخاف ان ياكله الذئب وانتم عنه غافلون',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>ِى لَيَحۡزُنُن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َذۡهَبُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> وَأَخَافُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡكُلَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّئۡبُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ عَنۡهُ غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 12, 3, 236, 194, 95, 'false'
  );
  
  -- Ayah 14 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1610,
    'قَالُوا۟ لَىِٕنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّاۤ إِذࣰا لَّخَـٰسِرُونَ',
    'قالوا لئن اكله الذئب ونحن عصبة انا اذا لخاسرون',
    'قَالُو<rule class=slnt>اۡ</rule> لَئِنۡ أَكَلَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 12, 3, 236, 194, 95, 'false'
  );
  
  -- Ayah 15 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1611,
    'فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجۡمَعُوۤا۟ أَن یَجۡعَلُوهُ فِی غَیَـٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَیۡنَاۤ إِلَیۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَـٰذَا وَهُمۡ لَا یَشۡعُرُونَ',
    'فلما ذهبوا به واجمعوا ان يجعلوه في غيابت الجب واوحينا اليه لتنبئنهم بامرهم هذا وهم لا يشعرون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ذَهَبُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> وَأَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>عَلُوهُ فِى غَيَ<rule class=madda_normal>ـٰ</rule>بَتِ <rule class=ham_wasl>ٱ</rule>لۡجُبِّ‌ۚ وَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ لَتُنَبِّئَ<rule class=ghunnah>نّ</rule>َه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَمۡرِهِمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا وَهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 12, 3, 237, 194, 95, 'false'
  );
  
  -- Ayah 16 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1612,
    'وَجَاۤءُوۤ أَبَاهُمۡ عِشَاۤءࣰ یَبۡكُونَ',
    'وجاءوا اباهم عشاء يبكون',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓء<rule class=madda_obligatory_monfasel>ُوٓ</rule> أَبَاهُمۡ عِش<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>ك<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 12, 3, 237, 194, 95, 'false'
  );
  
  -- Ayah 17 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1613,
    'قَالُوا۟ یَـٰۤأَبَانَاۤ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا یُوسُفَ عِندَ مَتَـٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَاۤ أَنتَ بِمُؤۡمِنࣲ لَّنَا وَلَوۡ كُنَّا صَـٰدِقِینَ',
    'قالوا يا ابانا انا ذهبنا نستبق وتركنا يوسف عند متاعنا فاكله الذئب وما انت بمؤمن لنا ولو كنا صادقين',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَان<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا ذَهَ<rule class=qalaqah>بۡ</rule>نَا نَسۡتَبِقُ وَتَرَكۡنَا يُوسُفَ عِ<rule class=ikhafa>ند</rule>َ مَتَ<rule class=madda_normal>ـٰ</rule>عِنَا فَأَكَلَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّئۡبُ‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ بِمُؤۡمِ<rule class=idgham_wo_ghunnah>نٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّنَا وَلَوۡ كُ<rule class=ghunnah>نّ</rule>َا صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 12, 3, 237, 194, 95, 'false'
  );
  
  -- Ayah 18 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1614,
    'وَجَاۤءُو عَلَىٰ قَمِیصِهِۦ بِدَمࣲ كَذِبࣲۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرࣰاۖ فَصَبۡرࣱ جَمِیلࣱۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ',
    'وجاءوا على قميصه بدم كذب قال بل سولت لكم انفسكم امرا فصبر جميل والله المستعان على ما تصفون',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو عَلَىٰ قَمِيصِه<rule class=madda_normal>ِۦ</rule> بِدَ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ك</rule>َذِ<rule class=ikhafa>بٍ‌ۚ</rule> <rule class=ikhafa>ق</rule>َالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَ<rule class=ikhafa>نف</rule>ُسُكُمۡ أَمۡ<rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َصَ<rule class=qalaqah>بۡ</rule><rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ج</rule>َمِي<rule class=idgham_ghunnah>لٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَعَانُ عَلَىٰ مَا تَصِف<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 12, 3, 237, 194, 95, 'false'
  );
  
  -- Ayah 19 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1615,
    'وَجَاۤءَتۡ سَیَّارَةࣱ فَأَرۡسَلُوا۟ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ یَـٰبُشۡرَىٰ هَـٰذَا غُلَـٰمࣱۚ وَأَسَرُّوهُ بِضَـٰعَةࣰۚ وَٱللَّهُ عَلِیمُۢ بِمَا یَعۡمَلُونَ',
    'وجاءت سيارة فارسلوا واردهم فادلى دلوه قال يا بشرى هذا غلام واسروه بضاعة والله عليم بما يعملون',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ سَيَّارَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َأَرۡسَلُو<rule class=slnt>اۡ</rule> وَارِدَهُمۡ فَأَ<rule class=qalaqah>دۡ</rule>لَىٰ دَلۡوَهُ<rule class=madda_normal>ۥ</rule>‌ۖ قَالَ يَ<rule class=madda_normal>ـٰ</rule>بُشۡرَىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا غُلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَسَرُّوهُ بِضَ<rule class=madda_normal>ـٰ</rule>عَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِمَا يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 12, 3, 237, 194, 95, 'false'
  );
  
  -- Ayah 20 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1616,
    'وَشَرَوۡهُ بِثَمَنِۭ بَخۡسࣲ دَرَ ٰ⁠هِمَ مَعۡدُودَةࣲ وَكَانُوا۟ فِیهِ مِنَ ٱلزَّ ٰ⁠هِدِینَ',
    'وشروه بثمن بخس دراهم معدودة وكانوا فيه من الزاهدين',
    'وَشَرَوۡهُ بِثَمَ<rule class=iqlab>نِۭ</rule> <rule class=iqlab>ب</rule>َخۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>د</rule>َر<rule class=madda_normal>ٰ</rule>هِمَ مَعۡدُودَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َكَانُو<rule class=slnt>اۡ</rule> فِيهِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زّ<rule class=madda_normal>ٰ</rule>هِد<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 12, 3, 237, 194, 95, 'false'
  );
  
  -- Ayah 21 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1617,
    'وَقَالَ ٱلَّذِی ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦۤ أَكۡرِمِی مَثۡوَىٰهُ عَسَىٰۤ أَن یَنفَعَنَاۤ أَوۡ نَتَّخِذَهُۥ وَلَدࣰاۚ وَكَذَ ٰ⁠لِكَ مَكَّنَّا لِیُوسُفَ فِی ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِیلِ ٱلۡأَحَادِیثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰۤ أَمۡرِهِۦ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'وقال الذي اشتراه من مصر لامراته اكرمي مثواه عسى ان ينفعنا او نتخذه ولدا وكذلك مكنا ليوسف في الارض ولنعلمه من تاويل الاحاديث والله غالب على امره ولكن اكثر الناس لا يعلمون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِى <rule class=ham_wasl>ٱ</rule>شۡتَرَ<rule class=madda_normal>ٮٰ</rule>هُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّصۡرَ لِ<rule class=ham_wasl>ٱ</rule>مۡرَأَتِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَكۡرِمِى مَثۡوَ<rule class=madda_normal>ٮٰ</rule>هُ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نف</rule>َعَن<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ نَتَّخِذَهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=idgham_ghunnah>دًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَذ<rule class=madda_normal>ٰ</rule>لِكَ مَكَّ<rule class=ghunnah>نّ</rule>َا لِيُوسُفَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلِنُعَلِّمَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡوِيلِ <rule class=ham_wasl>ٱ</rule>لۡأَحَادِيثِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَالِبٌ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡرِه<rule class=madda_normal>ِۦ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 12, 3, 237, 195, 95, 'false'
  );
  
  -- Ayah 22 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1618,
    'وَلَمَّا بَلَغَ أَشُدَّهُۥۤ ءَاتَیۡنَـٰهُ حُكۡمࣰا وَعِلۡمࣰاۚ وَكَذَ ٰ⁠لِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ',
    'ولما بلغ اشده اتيناه حكما وعلما وكذلك نجزي المحسنين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا بَلَغَ أَشُدَّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ حُكۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َعِلۡ<rule class=idgham_ghunnah>مًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٢٢',
    22, 12, 3, 237, 195, 95, 'false'
  );
  
  -- Ayah 23 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1619,
    'وَرَ ٰ⁠وَدَتۡهُ ٱلَّتِی هُوَ فِی بَیۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَ ٰ⁠بَ وَقَالَتۡ هَیۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّیۤ أَحۡسَنَ مَثۡوَایَۖ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ',
    'وراودته التي هو في بيتها عن نفسه وغلقت الابواب وقالت هيت لك قال معاذ الله انه ربي احسن مثواي انه لا يفلح الظالمون',
    'وَر<rule class=madda_normal>ٰ</rule>وَدَتۡهُ <rule class=ham_wasl>ٱ</rule>لَّتِى هُوَ فِى بَيۡتِهَا ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِه<rule class=madda_normal>ِۦ</rule> وَغَلَّقَتِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بَ وَقَالَتۡ هَيۡتَ لَكَ‌ۚ قَالَ مَعَاذَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡسَنَ مَثۡوَاىَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 12, 3, 238, 195, 95, 'false'
  );
  
  -- Ayah 24 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1620,
    'وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَاۤ أَن رَّءَا بُرۡهَـٰنَ رَبِّهِۦۚ كَذَ ٰ⁠لِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوۤءَ وَٱلۡفَحۡشَاۤءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِینَ',
    'ولقد همت به وهم بها لولا ان راى برهان ربه كذلك لنصرف عنه السوء والفحشاء انه من عبادنا المخلصين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> هَ<rule class=ghunnah>مّ</rule>َتۡ بِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَهَ<rule class=ghunnah>مّ</rule>َ بِهَا لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّءَا بُرۡهَ<rule class=madda_normal>ـٰ</rule>نَ رَبِّه<rule class=madda_normal>ِۦ</rule>‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ لِنَصۡرِفَ عَنۡهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ وَ<rule class=ham_wasl>ٱ</rule>لۡفَحۡش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مِنۡ عِبَادِنَا <rule class=ham_wasl>ٱ</rule>لۡمُخۡلَص<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 12, 3, 238, 195, 95, 'false'
  );
  
  -- Ayah 25 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1621,
    'وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِیصَهُۥ مِن دُبُرࣲ وَأَلۡفَیَا سَیِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَاۤءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوۤءًا إِلَّاۤ أَن یُسۡجَنَ أَوۡ عَذَابٌ أَلِیمࣱ',
    'واستبقا الباب وقدت قميصه من دبر والفيا سيدها لدى الباب قالت ما جزاء من اراد باهلك سوءا الا ان يسجن او عذاب اليم',
    'وَ<rule class=ham_wasl>ٱ</rule>سۡتَبَقَا <rule class=ham_wasl>ٱ</rule>لۡبَابَ وَقَدَّتۡ قَمِيصَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُبُ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَلۡفَيَا سَيِّدَهَا لَدَا <rule class=ham_wasl>ٱ</rule>لۡبَابِ‌ۚ قَالَتۡ مَا جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مَنۡ أَرَادَ بِأَهۡلِكَ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءًا إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُسۡجَنَ أَوۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٢٥',
    25, 12, 3, 238, 195, 95, 'false'
  );
  
  -- Ayah 26 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1622,
    'قَالَ هِیَ رَ ٰ⁠وَدَتۡنِی عَن نَّفۡسِیۚ وَشَهِدَ شَاهِدࣱ مِّنۡ أَهۡلِهَاۤ إِن كَانَ قَمِیصُهُۥ قُدَّ مِن قُبُلࣲ فَصَدَقَتۡ وَهُوَ مِنَ ٱلۡكَـٰذِبِینَ',
    'قال هي راودتني عن نفسي وشهد شاهد من اهلها ان كان قميصه قد من قبل فصدقت وهو من الكاذبين',
    'قَالَ هِىَ ر<rule class=madda_normal>ٰ</rule>وَدَتۡنِى ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِى‌ۚ وَشَهِدَ شَاهِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ قَمِيصُهُ<rule class=madda_normal>ۥ</rule> قُدَّ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُبُ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َصَدَقَتۡ وَهُوَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٢٦',
    26, 12, 3, 238, 195, 95, 'false'
  );
  
  -- Ayah 27 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1623,
    'وَإِن كَانَ قَمِیصُهُۥ قُدَّ مِن دُبُرࣲ فَكَذَبَتۡ وَهُوَ مِنَ ٱلصَّـٰدِقِینَ',
    'وان كان قميصه قد من دبر فكذبت وهو من الصادقين',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ قَمِيصُهُ<rule class=madda_normal>ۥ</rule> قُدَّ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُبُ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َكَذَبَتۡ وَهُوَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 12, 3, 238, 195, 95, 'false'
  );
  
  -- Ayah 28 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1624,
    'فَلَمَّا رَءَا قَمِیصَهُۥ قُدَّ مِن دُبُرࣲ قَالَ إِنَّهُۥ مِن كَیۡدِكُنَّۖ إِنَّ كَیۡدَكُنَّ عَظِیمࣱ',
    'فلما راى قميصه قد من دبر قال انه من كيدكن ان كيدكن عظيم',
    'فَلَ<rule class=ghunnah>مّ</rule>َا رَءَا قَمِيصَهُ<rule class=madda_normal>ۥ</rule> قُدَّ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُبُ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ق</rule>َالَ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َيۡدِكُ<rule class=ghunnah>نّ</rule>َ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ كَيۡدَكُ<rule class=ghunnah>نّ</rule>َ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٢٨',
    28, 12, 3, 238, 195, 95, 'false'
  );
  
  -- Ayah 29 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1625,
    'یُوسُفُ أَعۡرِضۡ عَنۡ هَـٰذَاۚ وَٱسۡتَغۡفِرِی لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔینَ',
    'يوسف اعرض عن هذا واستغفري لذنبك انك كنت من الخاطئين',
    'يُوسُفُ أَعۡرِضۡ عَنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۚ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرِى لِذَ<rule class=iqlab>نۢب</rule>ِكِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َكِ كُ<rule class=ikhafa>نت</rule>ِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَاطِــٔ<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 12, 3, 238, 195, 95, 'false'
  );
  
  -- Ayah 30 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1626,
    '۞ وَقَالَ نِسۡوَةࣱ فِی ٱلۡمَدِینَةِ ٱمۡرَأَتُ ٱلۡعَزِیزِ تُرَ ٰ⁠وِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'وقال نسوة في المدينة امرات العزيز تراود فتاها عن نفسه قد شغفها حبا انا لنراها في ضلال مبين',
    '۞وَقَالَ نِسۡوَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ <rule class=ham_wasl>ٱ</rule>مۡرَأَتُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ تُر<rule class=madda_normal>ٰ</rule>وِدُ فَتَ<rule class=madda_normal>ـٰ</rule>هَا ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ قَ<rule class=qalaqah>دۡ</rule> شَغَفَهَا حُبًّا‌ۖ إِ<rule class=ghunnah>نّ</rule>َا لَنَرَ<rule class=madda_normal>ٮٰ</rule>هَا فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٣٠',
    30, 12, 3, 238, 196, 96, 'false'
  );
  
  -- Ayah 31 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1627,
    'فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَیۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـࣰٔا وَءَاتَتۡ كُلَّ وَ ٰ⁠حِدَةࣲ مِّنۡهُنَّ سِكِّینࣰا وَقَالَتِ ٱخۡرُجۡ عَلَیۡهِنَّۖ فَلَمَّا رَأَیۡنَهُۥۤ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَیۡدِیَهُنَّ وَقُلۡنَ حَـٰشَ لِلَّهِ مَا هَـٰذَا بَشَرًا إِنۡ هَـٰذَاۤ إِلَّا مَلَكࣱ كَرِیمࣱ',
    'فلما سمعت بمكرهن ارسلت اليهن واعتدت لهن متكا واتت كل واحدة منهن سكينا وقالت اخرج عليهن فلما راينه اكبرنه وقطعن ايديهن وقلن حاش لله ما هذا بشرا ان هذا الا ملك كريم',
    'فَلَ<rule class=ghunnah>مّ</rule>َا سَمِعَتۡ بِمَكۡرِهِ<rule class=ghunnah>نّ</rule>َ أَرۡسَلَتۡ إِلَيۡهِ<rule class=ghunnah>نّ</rule>َ وَأَعۡتَدَتۡ لَهُ<rule class=ghunnah>نّ</rule>َ مُتَّكَـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َءَاتَتۡ كُلَّ و<rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ<rule class=ghunnah>نّ</rule>َ سِكِّي<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َقَالَتِ <rule class=ham_wasl>ٱ</rule>خۡرُ<rule class=qalaqah>جۡ</rule> عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا رَأَيۡنَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَكۡبَرۡنَهُ<rule class=madda_normal>ۥ</rule> وَقَطَّعۡنَ أَيۡدِيَهُ<rule class=ghunnah>نّ</rule>َ وَقُلۡنَ حَ<rule class=madda_normal>ـٰ</rule>شَ لِلَّهِ مَا هَ<rule class=madda_normal>ـٰ</rule>ذَا بَشَرًا إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا مَلَ<rule class=ikhafa>كٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٣١',
    31, 12, 3, 239, 196, 96, 'false'
  );
  
  -- Ayah 32 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1628,
    'قَالَتۡ فَذَ ٰ⁠لِكُنَّ ٱلَّذِی لُمۡتُنَّنِی فِیهِۖ وَلَقَدۡ رَ ٰ⁠وَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَىِٕن لَّمۡ یَفۡعَلۡ مَاۤ ءَامُرُهُۥ لَیُسۡجَنَنَّ وَلَیَكُونࣰا مِّنَ ٱلصَّـٰغِرِینَ',
    'قالت فذلكن الذي لمتنني فيه ولقد راودته عن نفسه فاستعصم ولئن لم يفعل ما امره ليسجنن وليكونا من الصاغرين',
    'قَالَتۡ فَذ<rule class=madda_normal>ٰ</rule>لِكُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِى لُمۡتُ<rule class=ghunnah>نّ</rule>َنِى فِيهِ‌ۖ وَلَقَ<rule class=qalaqah>دۡ</rule> ر<rule class=madda_normal>ٰ</rule>وَ<rule class=idgham_mutajanisayn>د</rule>تُّهُ<rule class=madda_normal>ۥ</rule> ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِه<rule class=madda_normal>ِۦ</rule> فَ<rule class=ham_wasl>ٱ</rule>سۡتَعۡصَمَ‌ۖ وَلَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَفۡعَلۡ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَامُرُهُ<rule class=madda_normal>ۥ</rule> لَيُسۡجَنَ<rule class=ghunnah>نّ</rule>َ وَلَيَكُو<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>غِر<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 12, 3, 239, 196, 96, 'false'
  );
  
  -- Ayah 33 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1629,
    'قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَیَّ مِمَّا یَدۡعُونَنِیۤ إِلَیۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّی كَیۡدَهُنَّ أَصۡبُ إِلَیۡهِنَّ وَأَكُن مِّنَ ٱلۡجَـٰهِلِینَ',
    'قال رب السجن احب الي مما يدعونني اليه والا تصرف عني كيدهن اصب اليهن واكن من الجاهلين',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=qalaqah>جۡ</rule>نُ أَحَبُّ إِلَىَّ مِ<rule class=ghunnah>مّ</rule>َا يَ<rule class=qalaqah>دۡ</rule>عُونَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ‌ۖ وَإِلَّا تَصۡرِفۡ عَ<rule class=ghunnah>نّ</rule>ِى كَيۡدَهُ<rule class=ghunnah>نّ</rule>َ أَصۡبُ إِلَيۡهِ<rule class=ghunnah>نّ</rule>َ وَأَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِل<rule class=madda_permissible>ِي</rule>نَ ٣٣',
    33, 12, 3, 239, 196, 96, 'false'
  );
  
  -- Ayah 34 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1630,
    'فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَیۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'فاستجاب له ربه فصرف عنه كيدهن انه هو السميع العليم',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَجَابَ لَهُ<rule class=madda_normal>ۥ</rule> رَبُّهُ<rule class=madda_normal>ۥ</rule> فَصَرَفَ عَنۡهُ كَيۡدَهُ<rule class=ghunnah>نّ</rule>َ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٣٤',
    34, 12, 3, 239, 196, 96, 'false'
  );
  
  -- Ayah 35 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1631,
    'ثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُا۟ ٱلۡـَٔایَـٰتِ لَیَسۡجُنُنَّهُۥ حَتَّىٰ حِینࣲ',
    'ثم بدا لهم من بعد ما راوا الايات ليسجننه حتى حين',
    'ثُ<rule class=ghunnah>مّ</rule>َ بَدَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا رَأَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لَيَسۡجُنُ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> حَتَّىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٣٥',
    35, 12, 3, 239, 196, 96, 'false'
  );
  
  -- Ayah 36 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1632,
    'وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَیَانِۖ قَالَ أَحَدُهُمَاۤ إِنِّیۤ أَرَىٰنِیۤ أَعۡصِرُ خَمۡرࣰاۖ وَقَالَ ٱلۡـَٔاخَرُ إِنِّیۤ أَرَىٰنِیۤ أَحۡمِلُ فَوۡقَ رَأۡسِی خُبۡزࣰا تَأۡكُلُ ٱلطَّیۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِیلِهِۦۤۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِینَ',
    'ودخل معه السجن فتيان قال احدهما اني اراني اعصر خمرا وقال الاخر اني اراني احمل فوق راسي خبزا تاكل الطير منه نبئنا بتاويله انا نراك من المحسنين',
    'وَدَخَلَ مَعَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=qalaqah>جۡ</rule>نَ فَتَيَانِ‌ۖ قَالَ أَحَدُهُم<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَ<rule class=madda_normal>ٮٰ</rule>ن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡصِرُ خَمۡ<rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ <rule class=ham_wasl>ٱ</rule>لۡأَخَرُ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَ<rule class=madda_normal>ٮٰ</rule>ن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡمِلُ فَوۡقَ رَأۡسِى خُ<rule class=qalaqah>بۡ</rule><rule class=ikhafa>زًا</rule> <rule class=ikhafa>ت</rule>َأۡكُلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرُ مِنۡهُ‌ۖ نَبِّئۡنَا بِتَأۡوِيلِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َا نَرَ<rule class=madda_normal>ٮٰ</rule>كَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 12, 3, 239, 197, 96, 'false'
  );
  
  -- Ayah 37 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1633,
    'قَالَ لَا یَأۡتِیكُمَا طَعَامࣱ تُرۡزَقَانِهِۦۤ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِیلِهِۦ قَبۡلَ أَن یَأۡتِیَكُمَاۚ ذَ ٰ⁠لِكُمَا مِمَّا عَلَّمَنِی رَبِّیۤۚ إِنِّی تَرَكۡتُ مِلَّةَ قَوۡمࣲ لَّا یُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ كَـٰفِرُونَ',
    'قال لا ياتيكما طعام ترزقانه الا نباتكما بتاويله قبل ان ياتيكما ذلكما مما علمني ربي اني تركت ملة قوم لا يؤمنون بالله وهم بالاخرة هم كافرون',
    'قَالَ لَا يَأۡتِيكُمَا طَعَا<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ت</rule>ُرۡزَقَانِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِيلِه<rule class=madda_normal>ِۦ</rule> قَ<rule class=qalaqah>بۡ</rule>لَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَكُمَا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمَا مِ<rule class=ghunnah>مّ</rule>َا عَلَّمَنِى رَبّ<rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>ِى تَرَكۡتُ مِلَّةَ قَوۡ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 12, 3, 239, 197, 96, 'false'
  );
  
  -- Ayah 38 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1634,
    'وَٱتَّبَعۡتُ مِلَّةَ ءَابَاۤءِیۤ إِبۡرَ ٰ⁠هِیمَ وَإِسۡحَـٰقَ وَیَعۡقُوبَۚ مَا كَانَ لَنَاۤ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَیۡءࣲۚ ذَ ٰ⁠لِكَ مِن فَضۡلِ ٱللَّهِ عَلَیۡنَا وَعَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَشۡكُرُونَ',
    'واتبعت ملة ابائي ابراهيم واسحاق ويعقوب ما كان لنا ان نشرك بالله من شيء ذلك من فضل الله علينا وعلى الناس ولكن اكثر الناس لا يشكرون',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّبَعۡتُ مِلَّةَ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓء<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ‌ۚ مَا كَانَ لَن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّشۡرِكَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡنَا وَعَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 12, 3, 240, 197, 96, 'false'
  );
  
  -- Ayah 39 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1635,
    'یَـٰصَـٰحِبَیِ ٱلسِّجۡنِ ءَأَرۡبَابࣱ مُّتَفَرِّقُونَ خَیۡرٌ أَمِ ٱللَّهُ ٱلۡوَ ٰ⁠حِدُ ٱلۡقَهَّارُ',
    'يا صاحبي السجن اارباب متفرقون خير ام الله الواحد القهار',
    'يَ<rule class=madda_normal>ـٰ</rule>صَ<rule class=madda_normal>ـٰ</rule>حِبَىِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=qalaqah>جۡ</rule>نِ ءَأَرۡبَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّتَفَرِّقُونَ خَيۡرٌ أَمِ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>حِدُ <rule class=ham_wasl>ٱ</rule>لۡقَهّ<rule class=madda_permissible>َا</rule>رُ ٣٩',
    39, 12, 3, 240, 197, 96, 'false'
  );
  
  -- Ayah 40 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1636,
    'مَا تَعۡبُدُونَ مِن دُونِهِۦۤ إِلَّاۤ أَسۡمَاۤءࣰ سَمَّیۡتُمُوهَاۤ أَنتُمۡ وَءَابَاۤؤُكُم مَّاۤ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَـٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعۡبُدُوۤا۟ إِلَّاۤ إِیَّاهُۚ ذَ ٰ⁠لِكَ ٱلدِّینُ ٱلۡقَیِّمُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'ما تعبدون من دونه الا اسماء سميتموها انتم واباؤكم ما انزل الله بها من سلطان ان الحكم الا لله امر الا تعبدوا الا اياه ذلك الدين القيم ولكن اكثر الناس لا يعلمون',
    'مَا تَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>س</rule>َ<rule class=ghunnah>مّ</rule>َيۡتُمُوه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلۡطَ<rule class=madda_normal>ـٰ</rule>نٍ‌ۚ إِنِ <rule class=ham_wasl>ٱ</rule>لۡحُكۡمُ إِلَّا لِلَّهِ‌ۚ أَمَرَ أَلَّا تَعۡبُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِيَّاهُ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينُ <rule class=ham_wasl>ٱ</rule>لۡقَيِّمُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 12, 3, 240, 197, 96, 'false'
  );
  
  -- Ayah 41 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1637,
    'یَـٰصَـٰحِبَیِ ٱلسِّجۡنِ أَمَّاۤ أَحَدُكُمَا فَیَسۡقِی رَبَّهُۥ خَمۡرࣰاۖ وَأَمَّا ٱلۡـَٔاخَرُ فَیُصۡلَبُ فَتَأۡكُلُ ٱلطَّیۡرُ مِن رَّأۡسِهِۦۚ قُضِیَ ٱلۡأَمۡرُ ٱلَّذِی فِیهِ تَسۡتَفۡتِیَانِ',
    'يا صاحبي السجن اما احدكما فيسقي ربه خمرا واما الاخر فيصلب فتاكل الطير من راسه قضي الامر الذي فيه تستفتيان',
    'يَ<rule class=madda_normal>ـٰ</rule>صَ<rule class=madda_normal>ـٰ</rule>حِبَىِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=qalaqah>جۡ</rule>نِ أَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَحَدُكُمَا فَيَسۡقِى رَبَّهُ<rule class=madda_normal>ۥ</rule> خَمۡ<rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡأَخَرُ فَيُصۡلَبُ فَتَأۡكُلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّأۡسِه<rule class=madda_normal>ِۦ</rule>‌ۚ قُضِىَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ <rule class=ham_wasl>ٱ</rule>لَّذِى فِيهِ تَسۡتَفۡتِي<rule class=madda_permissible>َا</rule>نِ ٤١',
    41, 12, 3, 240, 197, 96, 'false'
  );
  
  -- Ayah 42 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1638,
    'وَقَالَ لِلَّذِی ظَنَّ أَنَّهُۥ نَاجࣲ مِّنۡهُمَا ٱذۡكُرۡنِی عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّیۡطَـٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِی ٱلسِّجۡنِ بِضۡعَ سِنِینَ',
    'وقال للذي ظن انه ناج منهما اذكرني عند ربك فانساه الشيطان ذكر ربه فلبث في السجن بضع سنين',
    'وَقَالَ لِلَّذِى ظَ<rule class=ghunnah>نّ</rule>َ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> نَا<rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمَا <rule class=ham_wasl>ٱ</rule>ذۡكُرۡنِى عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ فَأَ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ ذِكۡرَ رَبِّه<rule class=madda_normal>ِۦ</rule> فَلَبِثَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=qalaqah>جۡ</rule>نِ بِضۡعَ سِن<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 12, 3, 240, 197, 96, 'false'
  );
  
  -- Ayah 43 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1639,
    'وَقَالَ ٱلۡمَلِكُ إِنِّیۤ أَرَىٰ سَبۡعَ بَقَرَ ٰ⁠تࣲ سِمَانࣲ یَأۡكُلُهُنَّ سَبۡعٌ عِجَافࣱ وَسَبۡعَ سُنۢبُلَـٰتٍ خُضۡرࣲ وَأُخَرَ یَابِسَـٰتࣲۖ یَـٰۤأَیُّهَا ٱلۡمَلَأُ أَفۡتُونِی فِی رُءۡیَـٰیَ إِن كُنتُمۡ لِلرُّءۡیَا تَعۡبُرُونَ',
    'وقال الملك اني ارى سبع بقرات سمان ياكلهن سبع عجاف وسبع سنبلات خضر واخر يابسات يا ايها الملا افتوني في رؤياي ان كنتم للرؤيا تعبرون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلِكُ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَىٰ سَ<rule class=qalaqah>بۡ</rule>عَ بَقَر<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>س</rule>ِمَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡكُلُهُ<rule class=ghunnah>نّ</rule>َ سَ<rule class=qalaqah>بۡ</rule>عٌ عِجَا<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>و</rule>َسَ<rule class=qalaqah>بۡ</rule>عَ سُ<rule class=iqlab>نۢب</rule>ُلَ<rule class=madda_normal>ـٰ</rule>تٍ خُضۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َأُخَرَ يَابِسَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ‌ۖ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ أَفۡتُونِى فِى رُءۡيَ<rule class=madda_normal>ـٰ</rule>ىَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ لِلرُّءۡيَا تَعۡبُر<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 12, 3, 240, 198, 96, 'false'
  );
  
  -- Ayah 44 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1640,
    'قَالُوۤا۟ أَضۡغَـٰثُ أَحۡلَـٰمࣲۖ وَمَا نَحۡنُ بِتَأۡوِیلِ ٱلۡأَحۡلَـٰمِ بِعَـٰلِمِینَ',
    'قالوا اضغاث احلام وما نحن بتاويل الاحلام بعالمين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَضۡغَ<rule class=madda_normal>ـٰ</rule>ثُ أَحۡلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا نَحۡنُ بِتَأۡوِيلِ <rule class=ham_wasl>ٱ</rule>لۡأَحۡلَ<rule class=madda_normal>ـٰ</rule>مِ بِعَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤٤',
    44, 12, 3, 241, 198, 96, 'false'
  );
  
  -- Ayah 45 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1641,
    'وَقَالَ ٱلَّذِی نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِیلِهِۦ فَأَرۡسِلُونِ',
    'وقال الذي نجا منهما وادكر بعد امة انا انبئكم بتاويله فارسلون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِى نَجَا مِنۡهُمَا وَ<rule class=ham_wasl>ٱ</rule>دَّكَرَ بَعۡدَ أُ<rule class=ghunnah>مّ</rule>َةٍ أَنَاۡ أُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِتَأۡوِيلِه<rule class=madda_normal>ِۦ</rule> فَأَرۡسِل<rule class=madda_permissible>ُو</rule>نِ ٤٥',
    45, 12, 3, 241, 198, 96, 'false'
  );
  
  -- Ayah 46 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1642,
    'یُوسُفُ أَیُّهَا ٱلصِّدِّیقُ أَفۡتِنَا فِی سَبۡعِ بَقَرَ ٰ⁠تࣲ سِمَانࣲ یَأۡكُلُهُنَّ سَبۡعٌ عِجَافࣱ وَسَبۡعِ سُنۢبُلَـٰتٍ خُضۡرࣲ وَأُخَرَ یَابِسَـٰتࣲ لَّعَلِّیۤ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ یَعۡلَمُونَ',
    'يوسف ايها الصديق افتنا في سبع بقرات سمان ياكلهن سبع عجاف وسبع سنبلات خضر واخر يابسات لعلي ارجع الى الناس لعلهم يعلمون',
    'يُوسُفُ أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّدِّيقُ أَفۡتِنَا فِى سَ<rule class=qalaqah>بۡ</rule>عِ بَقَر<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>س</rule>ِمَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡكُلُهُ<rule class=ghunnah>نّ</rule>َ سَ<rule class=qalaqah>بۡ</rule>عٌ عِجَا<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>و</rule>َسَ<rule class=qalaqah>بۡ</rule>عِ سُ<rule class=iqlab>نۢب</rule>ُلَ<rule class=madda_normal>ـٰ</rule>تٍ خُضۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َأُخَرَ يَابِسَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡجِعُ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَعَلَّهُمۡ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 12, 3, 241, 198, 96, 'false'
  );
  
  -- Ayah 47 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1643,
    'قَالَ تَزۡرَعُونَ سَبۡعَ سِنِینَ دَأَبࣰا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِی سُنۢبُلِهِۦۤ إِلَّا قَلِیلࣰا مِّمَّا تَأۡكُلُونَ',
    'قال تزرعون سبع سنين دابا فما حصدتم فذروه في سنبله الا قليلا مما تاكلون',
    'قَالَ تَزۡرَعُونَ سَ<rule class=qalaqah>بۡ</rule>عَ سِنِينَ دَأَ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َمَا حَصَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ فَذَرُوهُ فِى سُ<rule class=iqlab>نۢب</rule>ُلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 12, 3, 241, 198, 96, 'false'
  );
  
  -- Ayah 48 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1644,
    'ثُمَّ یَأۡتِی مِنۢ بَعۡدِ ذَ ٰ⁠لِكَ سَبۡعࣱ شِدَادࣱ یَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِیلࣰا مِّمَّا تُحۡصِنُونَ',
    'ثم ياتي من بعد ذلك سبع شداد ياكلن ما قدمتم لهن الا قليلا مما تحصنون',
    'ثُ<rule class=ghunnah>مّ</rule>َ يَأۡتِى م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ سَ<rule class=qalaqah>بۡ</rule><rule class=ikhafa>عٌ</rule> <rule class=ikhafa>ش</rule>ِدَا<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُ<rule class=ghunnah>نّ</rule>َ إِلَّا قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تُحۡصِن<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 12, 3, 241, 198, 96, 'false'
  );
  
  -- Ayah 49 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1645,
    'ثُمَّ یَأۡتِی مِنۢ بَعۡدِ ذَ ٰ⁠لِكَ عَامࣱ فِیهِ یُغَاثُ ٱلنَّاسُ وَفِیهِ یَعۡصِرُونَ',
    'ثم ياتي من بعد ذلك عام فيه يغاث الناس وفيه يعصرون',
    'ثُ<rule class=ghunnah>مّ</rule>َ يَأۡتِى م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَا<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ف</rule>ِيهِ يُغَاثُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ وَفِيهِ يَعۡصِر<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 12, 3, 241, 198, 96, 'false'
  );
  
  -- Ayah 50 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1646,
    'وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِی بِهِۦۖ فَلَمَّا جَاۤءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّـٰتِی قَطَّعۡنَ أَیۡدِیَهُنَّۚ إِنَّ رَبِّی بِكَیۡدِهِنَّ عَلِیمࣱ',
    'وقال الملك ائتوني به فلما جاءه الرسول قال ارجع الى ربك فاساله ما بال النسوة اللاتي قطعن ايديهن ان ربي بكيدهن عليم',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلِكُ <rule class=ham_wasl>ٱ</rule>ئۡتُونِى بِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ قَالَ <rule class=ham_wasl>ٱ</rule>رۡجِعۡ إِلَىٰ رَبِّكَ فَسۡــَٔلۡهُ مَا بَالُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِسۡوَةِ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>تِى قَطَّعۡنَ أَيۡدِيَهُ<rule class=ghunnah>نّ</rule>َ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى بِكَيۡدِهِ<rule class=ghunnah>نّ</rule>َ عَل<rule class=madda_permissible>ِي</rule>مٌ ٥٠',
    50, 12, 3, 241, 199, 96, 'false'
  );
  
  -- Ayah 51 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1647,
    'قَالَ مَا خَطۡبُكُنَّ إِذۡ رَ ٰ⁠وَدتُّنَّ یُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَـٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَیۡهِ مِن سُوۤءࣲۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِیزِ ٱلۡـَٔـٰنَ حَصۡحَصَ ٱلۡحَقُّ أَنَا۠ رَ ٰ⁠وَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِینَ',
    'قال ما خطبكن اذ راودتن يوسف عن نفسه قلن حاش لله ما علمنا عليه من سوء قالت امرات العزيز الان حصحص الحق انا راودته عن نفسه وانه لمن الصادقين',
    'قَالَ مَا خَ<rule class=qalaqah>طۡ</rule>بُكُ<rule class=ghunnah>نّ</rule>َ إِذۡ ر<rule class=madda_normal>ٰ</rule>وَ<rule class=idgham_mutajanisayn>د</rule>تُّ<rule class=ghunnah>نّ</rule>َ يُوسُفَ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۚ قُلۡنَ حَ<rule class=madda_normal>ـٰ</rule>شَ لِلَّهِ مَا عَلِمۡنَا عَلَيۡهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ‌ۚ</rule> <rule class=ikhafa>ق</rule>َالَتِ <rule class=ham_wasl>ٱ</rule>مۡرَأَتُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡـَٔ<rule class=madda_normal>ـٰ</rule>نَ حَصۡحَصَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ أَنَاۡ ر<rule class=madda_normal>ٰ</rule>وَ<rule class=idgham_mutajanisayn>د</rule>تُّهُ<rule class=madda_normal>ۥ</rule> ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِه<rule class=madda_normal>ِۦ</rule> وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٥١',
    51, 12, 3, 241, 199, 96, 'false'
  );
  
  -- Ayah 52 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1648,
    'ذَ ٰ⁠لِكَ لِیَعۡلَمَ أَنِّی لَمۡ أَخُنۡهُ بِٱلۡغَیۡبِ وَأَنَّ ٱللَّهَ لَا یَهۡدِی كَیۡدَ ٱلۡخَاۤىِٕنِینَ',
    'ذلك ليعلم اني لم اخنه بالغيب وان الله لا يهدي كيد الخائنين',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ لِيَعۡلَمَ أَ<rule class=ghunnah>نّ</rule>ِى لَمۡ أَخُنۡهُ بِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى كَيۡدَ <rule class=ham_wasl>ٱ</rule>لۡخ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِن<rule class=madda_permissible>ِي</rule>نَ ٥٢',
    52, 12, 3, 241, 199, 96, 'false'
  );
  
  -- Ayah 53 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1649,
    '۞ وَمَاۤ أُبَرِّئُ نَفۡسِیۤۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوۤءِ إِلَّا مَا رَحِمَ رَبِّیۤۚ إِنَّ رَبِّی غَفُورࣱ رَّحِیمࣱ',
    'وما ابرئ نفسي ان النفس لامارة بالسوء الا ما رحم ربي ان ربي غفور رحيم',
    '۞وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُبَرِّئُ نَفۡس<rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َفۡسَ لَأَ<rule class=ghunnah>مّ</rule>َارَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءِ إِلَّا مَا رَحِمَ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ رَبِّى غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٥٣',
    53, 13, 3, 242, 199, 97, 'false'
  );
  
  -- Ayah 54 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1650,
    'وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِی بِهِۦۤ أَسۡتَخۡلِصۡهُ لِنَفۡسِیۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡیَوۡمَ لَدَیۡنَا مَكِینٌ أَمِینࣱ',
    'وقال الملك ائتوني به استخلصه لنفسي فلما كلمه قال انك اليوم لدينا مكين امين',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلِكُ <rule class=ham_wasl>ٱ</rule>ئۡتُونِى بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَسۡتَخۡلِصۡهُ لِنَفۡسِى‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا كَلَّمَهُ<rule class=madda_normal>ۥ</rule> قَالَ إِ<rule class=ghunnah>نّ</rule>َكَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ لَدَيۡنَا مَكِينٌ أَم<rule class=madda_permissible>ِي</rule>نٌ ٥٤',
    54, 13, 3, 242, 199, 97, 'false'
  );
  
  -- Ayah 55 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1651,
    'قَالَ ٱجۡعَلۡنِی عَلَىٰ خَزَاۤىِٕنِ ٱلۡأَرۡضِۖ إِنِّی حَفِیظٌ عَلِیمࣱ',
    'قال اجعلني على خزائن الارض اني حفيظ عليم',
    'قَالَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡنِى عَلَىٰ خَز<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ إِ<rule class=ghunnah>نّ</rule>ِى حَفِيظٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٥٥',
    55, 13, 3, 242, 199, 97, 'false'
  );
  
  -- Ayah 56 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1652,
    'وَكَذَ ٰ⁠لِكَ مَكَّنَّا لِیُوسُفَ فِی ٱلۡأَرۡضِ یَتَبَوَّأُ مِنۡهَا حَیۡثُ یَشَاۤءُۚ نُصِیبُ بِرَحۡمَتِنَا مَن نَّشَاۤءُۖ وَلَا نُضِیعُ أَجۡرَ ٱلۡمُحۡسِنِینَ',
    'وكذلك مكنا ليوسف في الارض يتبوا منها حيث يشاء نصيب برحمتنا من نشاء ولا نضيع اجر المحسنين',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ مَكَّ<rule class=ghunnah>نّ</rule>َا لِيُوسُفَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يَتَبَوَّأُ مِنۡهَا حَيۡثُ يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ نُصِيبُ بِرَحۡمَتِنَا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ وَلَا نُضِيعُ أَ<rule class=qalaqah>جۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٥٦',
    56, 13, 3, 242, 199, 97, 'false'
  );
  
  -- Ayah 57 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1653,
    'وَلَأَجۡرُ ٱلۡـَٔاخِرَةِ خَیۡرࣱ لِّلَّذِینَ ءَامَنُوا۟ وَكَانُوا۟ یَتَّقُونَ',
    'ولاجر الاخرة خير للذين امنوا وكانوا يتقون',
    'وَلَأَ<rule class=qalaqah>جۡ</rule>رُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَكَانُو<rule class=slnt>اۡ</rule> يَتَّق<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 13, 3, 242, 199, 97, 'false'
  );
  
  -- Ayah 58 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1654,
    'وَجَاۤءَ إِخۡوَةُ یُوسُفَ فَدَخَلُوا۟ عَلَیۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ',
    'وجاء اخوة يوسف فدخلوا عليه فعرفهم وهم له منكرون',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِخۡوَةُ يُوسُفَ فَدَخَلُو<rule class=slnt>اۡ</rule> عَلَيۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُ<rule class=madda_normal>ۥ</rule> مُ<rule class=ikhafa>نك</rule>ِر<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 13, 3, 242, 200, 97, 'false'
  );
  
  -- Ayah 59 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1655,
    'وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِی بِأَخࣲ لَّكُم مِّنۡ أَبِیكُمۡۚ أَلَا تَرَوۡنَ أَنِّیۤ أُوفِی ٱلۡكَیۡلَ وَأَنَا۠ خَیۡرُ ٱلۡمُنزِلِینَ',
    'ولما جهزهم بجهازهم قال ائتوني باخ لكم من ابيكم الا ترون اني اوفي الكيل وانا خير المنزلين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا جَهَّزَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِجَهَازِهِمۡ قَالَ <rule class=ham_wasl>ٱ</rule>ئۡتُونِى بِأَ<rule class=idgham_wo_ghunnah>خٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَبِيكُمۡ‌ۚ أَلَا تَرَوۡنَ أَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُوفِى <rule class=ham_wasl>ٱ</rule>لۡكَيۡلَ وَأَنَاۡ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نز</rule>ِل<rule class=madda_permissible>ِي</rule>نَ ٥٩',
    59, 13, 3, 242, 200, 97, 'false'
  );
  
  -- Ayah 60 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1656,
    'فَإِن لَّمۡ تَأۡتُونِی بِهِۦ فَلَا كَیۡلَ لَكُمۡ عِندِی وَلَا تَقۡرَبُونِ',
    'فان لم تاتوني به فلا كيل لكم عندي ولا تقربون',
    'فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَأۡتُونِى بِه<rule class=madda_normal>ِۦ</rule> فَلَا كَيۡلَ لَكُمۡ عِ<rule class=ikhafa>ند</rule>ِى وَلَا تَ<rule class=qalaqah>قۡ</rule>رَب<rule class=madda_permissible>ُو</rule>نِ ٦٠',
    60, 13, 3, 242, 200, 97, 'false'
  );
  
  -- Ayah 61 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1657,
    'قَالُوا۟ سَنُرَ ٰ⁠وِدُ عَنۡهُ أَبَاهُ وَإِنَّا لَفَـٰعِلُونَ',
    'قالوا سنراود عنه اباه وانا لفاعلون',
    'قَالُو<rule class=slnt>اۡ</rule> سَنُر<rule class=madda_normal>ٰ</rule>وِدُ عَنۡهُ أَبَاهُ وَإِ<rule class=ghunnah>نّ</rule>َا لَفَ<rule class=madda_normal>ـٰ</rule>عِل<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 13, 3, 242, 200, 97, 'false'
  );
  
  -- Ayah 62 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1658,
    'وَقَالَ لِفِتۡیَـٰنِهِ ٱجۡعَلُوا۟ بِضَـٰعَتَهُمۡ فِی رِحَالِهِمۡ لَعَلَّهُمۡ یَعۡرِفُونَهَاۤ إِذَا ٱنقَلَبُوۤا۟ إِلَىٰۤ أَهۡلِهِمۡ لَعَلَّهُمۡ یَرۡجِعُونَ',
    'وقال لفتيانه اجعلوا بضاعتهم في رحالهم لعلهم يعرفونها اذا انقلبوا الى اهلهم لعلهم يرجعون',
    'وَقَالَ لِفِتۡيَ<rule class=madda_normal>ـٰ</rule>نِهِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلُو<rule class=slnt>اۡ</rule> بِضَ<rule class=madda_normal>ـٰ</rule>عَتَهُمۡ فِى رِحَالِهِمۡ لَعَلَّهُمۡ يَعۡرِفُونَه<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>َلَب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِهِمۡ لَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 13, 3, 242, 200, 97, 'false'
  );
  
  -- Ayah 63 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1659,
    'فَلَمَّا رَجَعُوۤا۟ إِلَىٰۤ أَبِیهِمۡ قَالُوا۟ یَـٰۤأَبَانَا مُنِعَ مِنَّا ٱلۡكَیۡلُ فَأَرۡسِلۡ مَعَنَاۤ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ',
    'فلما رجعوا الى ابيهم قالوا يا ابانا منع منا الكيل فارسل معنا اخانا نكتل وانا له لحافظون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا رَجَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَبِيهِمۡ قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَانَا مُنِعَ مِ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡكَيۡلُ فَأَرۡسِلۡ مَعَن<rule class=madda_obligatory_monfasel>َآ</rule> أَخَانَا نَكۡتَلۡ وَإِ<rule class=ghunnah>نّ</rule>َا لَهُ<rule class=madda_normal>ۥ</rule> لَحَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 13, 3, 242, 200, 97, 'false'
  );
  
  -- Ayah 64 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1660,
    'قَالَ هَلۡ ءَامَنُكُمۡ عَلَیۡهِ إِلَّا كَمَاۤ أَمِنتُكُمۡ عَلَىٰۤ أَخِیهِ مِن قَبۡلُ فَٱللَّهُ خَیۡرٌ حَـٰفِظࣰاۖ وَهُوَ أَرۡحَمُ ٱلرَّ ٰ⁠حِمِینَ',
    'قال هل امنكم عليه الا كما امنتكم على اخيه من قبل فالله خير حافظا وهو ارحم الراحمين',
    'قَالَ هَلۡ ءَامَنُكُمۡ عَلَيۡهِ إِلَّا كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَمِ<rule class=ikhafa>نت</rule>ُكُمۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَخِيهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَيۡرٌ حَ<rule class=madda_normal>ـٰ</rule>فِ<rule class=idgham_ghunnah>ظًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ أَرۡحَمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>حِم<rule class=madda_permissible>ِي</rule>نَ ٦٤',
    64, 13, 3, 243, 200, 97, 'false'
  );
  
  -- Ayah 65 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1661,
    'وَلَمَّا فَتَحُوا۟ مَتَـٰعَهُمۡ وَجَدُوا۟ بِضَـٰعَتَهُمۡ رُدَّتۡ إِلَیۡهِمۡۖ قَالُوا۟ یَـٰۤأَبَانَا مَا نَبۡغِیۖ هَـٰذِهِۦ بِضَـٰعَتُنَا رُدَّتۡ إِلَیۡنَاۖ وَنَمِیرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَیۡلَ بَعِیرࣲۖ ذَ ٰ⁠لِكَ كَیۡلࣱ یَسِیرࣱ',
    'ولما فتحوا متاعهم وجدوا بضاعتهم ردت اليهم قالوا يا ابانا ما نبغي هذه بضاعتنا ردت الينا ونمير اهلنا ونحفظ اخانا ونزداد كيل بعير ذلك كيل يسير',
    'وَلَ<rule class=ghunnah>مّ</rule>َا فَتَحُو<rule class=slnt>اۡ</rule> مَتَ<rule class=madda_normal>ـٰ</rule>عَهُمۡ وَجَدُو<rule class=slnt>اۡ</rule> بِضَ<rule class=madda_normal>ـٰ</rule>عَتَهُمۡ رُدَّتۡ إِلَيۡهِمۡ‌ۖ قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَانَا مَا نَ<rule class=qalaqah>بۡ</rule>غِى‌ۖ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> بِضَ<rule class=madda_normal>ـٰ</rule>عَتُنَا رُدَّتۡ إِلَيۡنَا‌ۖ وَنَمِيرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَيۡلَ بَعِي<rule class=ikhafa>رٍ‌ۖ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ كَيۡ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>َس<rule class=madda_permissible>ِي</rule>رٌ ٦٥',
    65, 13, 3, 243, 200, 97, 'false'
  );
  
  -- Ayah 66 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1662,
    'قَالَ لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقࣰا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِی بِهِۦۤ إِلَّاۤ أَن یُحَاطَ بِكُمۡۖ فَلَمَّاۤ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِیلࣱ',
    'قال لن ارسله معكم حتى تؤتون موثقا من الله لتاتنني به الا ان يحاط بكم فلما اتوه موثقهم قال الله على ما نقول وكيل',
    'قَالَ لَنۡ أُرۡسِلَهُ<rule class=madda_normal>ۥ</rule> مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِ<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ لَتَأۡتُ<rule class=ghunnah>نّ</rule>َنِى بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحَاطَ بِكُمۡ‌ۖ فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ مَا نَقُولُ وَك<rule class=madda_permissible>ِي</rule>لٌ ٦٦',
    66, 13, 3, 243, 200, 97, 'false'
  );
  
  -- Ayah 67 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1663,
    'وَقَالَ یَـٰبَنِیَّ لَا تَدۡخُلُوا۟ مِنۢ بَابࣲ وَ ٰ⁠حِدࣲ وَٱدۡخُلُوا۟ مِنۡ أَبۡوَ ٰ⁠بࣲ مُّتَفَرِّقَةࣲۖ وَمَاۤ أُغۡنِی عَنكُم مِّنَ ٱللَّهِ مِن شَیۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَیۡهِ تَوَكَّلۡتُۖ وَعَلَیۡهِ فَلۡیَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ',
    'وقال يا بني لا تدخلوا من باب واحد وادخلوا من ابواب متفرقة وما اغني عنكم من الله من شيء ان الحكم الا لله عليه توكلت وعليه فليتوكل المتوكلون',
    'وَقَالَ يَ<rule class=madda_normal>ـٰ</rule>بَنِىَّ لَا تَ<rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> مِنۡ أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّتَفَرِّقَ<rule class=idgham_ghunnah>ةٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُغۡنِى عَ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ‌ۖ إِنِ <rule class=ham_wasl>ٱ</rule>لۡحُكۡمُ إِلَّا لِلَّهِ‌ۖ عَلَيۡهِ تَوَكَّلۡتُ‌ۖ وَعَلَيۡهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُتَوَكِّل<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 13, 3, 243, 200, 97, 'false'
  );
  
  -- Ayah 68 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1664,
    'وَلَمَّا دَخَلُوا۟ مِنۡ حَیۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ یُغۡنِی عَنۡهُم مِّنَ ٱللَّهِ مِن شَیۡءٍ إِلَّا حَاجَةࣰ فِی نَفۡسِ یَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمࣲ لِّمَا عَلَّمۡنَـٰهُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'ولما دخلوا من حيث امرهم ابوهم ما كان يغني عنهم من الله من شيء الا حاجة في نفس يعقوب قضاها وانه لذو علم لما علمناه ولكن اكثر الناس لا يعلمون',
    'وَلَ<rule class=ghunnah>مّ</rule>َا دَخَلُو<rule class=slnt>اۡ</rule> مِنۡ حَيۡثُ أَمَرَهُمۡ أَبُوه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانَ يُغۡنِى عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ إِلَّا حَاجَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى نَفۡسِ يَعۡقُوبَ قَضَ<rule class=madda_normal>ـٰ</rule>هَا‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَذُو عِلۡ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا عَلَّمۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 13, 3, 243, 200, 97, 'false'
  );
  
  -- Ayah 69 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1665,
    'وَلَمَّا دَخَلُوا۟ عَلَىٰ یُوسُفَ ءَاوَىٰۤ إِلَیۡهِ أَخَاهُۖ قَالَ إِنِّیۤ أَنَا۠ أَخُوكَ فَلَا تَبۡتَىِٕسۡ بِمَا كَانُوا۟ یَعۡمَلُونَ',
    'ولما دخلوا على يوسف اوى اليه اخاه قال اني انا اخوك فلا تبتئس بما كانوا يعملون',
    'وَلَ<rule class=ghunnah>مّ</rule>َا دَخَلُو<rule class=slnt>اۡ</rule> عَلَىٰ يُوسُفَ ءَاوَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡهِ أَخَاهُ‌ۖ قَالَ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنَاۡ أَخُوكَ فَلَا تَ<rule class=qalaqah>بۡ</rule>تَئِسۡ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 13, 3, 243, 201, 97, 'false'
  );
  
  -- Ayah 70 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1666,
    'فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَایَةَ فِی رَحۡلِ أَخِیهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَیَّتُهَا ٱلۡعِیرُ إِنَّكُمۡ لَسَـٰرِقُونَ',
    'فلما جهزهم بجهازهم جعل السقاية في رحل اخيه ثم اذن مؤذن ايتها العير انكم لسارقون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا جَهَّزَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِجَهَازِهِمۡ جَعَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّقَايَةَ فِى رَحۡلِ أَخِيهِ ثُ<rule class=ghunnah>مّ</rule>َ أَذَّنَ مُؤَذِّنٌ أَيَّتُهَا <rule class=ham_wasl>ٱ</rule>لۡعِيرُ إِ<rule class=ghunnah>نّ</rule>َكُمۡ لَسَ<rule class=madda_normal>ـٰ</rule>رِق<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 13, 3, 244, 201, 97, 'false'
  );
  
  -- Ayah 71 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1667,
    'قَالُوا۟ وَأَقۡبَلُوا۟ عَلَیۡهِم مَّاذَا تَفۡقِدُونَ',
    'قالوا واقبلوا عليهم ماذا تفقدون',
    'قَالُو<rule class=slnt>اۡ</rule> وَأَ<rule class=qalaqah>قۡ</rule>بَلُو<rule class=slnt>اۡ</rule> عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّاذَا تَفۡقِد<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 13, 3, 244, 201, 97, 'false'
  );
  
  -- Ayah 72 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1668,
    'قَالُوا۟ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ وَلِمَن جَاۤءَ بِهِۦ حِمۡلُ بَعِیرࣲ وَأَنَا۠ بِهِۦ زَعِیمࣱ',
    'قالوا نفقد صواع الملك ولمن جاء به حمل بعير وانا به زعيم',
    'قَالُو<rule class=slnt>اۡ</rule> نَفۡقِدُ صُوَاعَ <rule class=ham_wasl>ٱ</rule>لۡمَلِكِ وَلِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِه<rule class=madda_normal>ِۦ</rule> حِمۡلُ بَعِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَنَاۡ بِه<rule class=madda_normal>ِۦ</rule> زَع<rule class=madda_permissible>ِي</rule>مٌ ٧٢',
    72, 13, 3, 244, 201, 97, 'false'
  );
  
  -- Ayah 73 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1669,
    'قَالُوا۟ تَٱللَّهِ لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِی ٱلۡأَرۡضِ وَمَا كُنَّا سَـٰرِقِینَ',
    'قالوا تالله لقد علمتم ما جئنا لنفسد في الارض وما كنا سارقين',
    'قَالُو<rule class=slnt>اۡ</rule> تَ<rule class=ham_wasl>ٱ</rule>للَّهِ لَقَ<rule class=qalaqah>دۡ</rule> عَلِمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا جِئۡنَا لِنُفۡسِدَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا كُ<rule class=ghunnah>نّ</rule>َا سَ<rule class=madda_normal>ـٰ</rule>رِق<rule class=madda_permissible>ِي</rule>نَ ٧٣',
    73, 13, 3, 244, 201, 97, 'false'
  );
  
  -- Ayah 74 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1670,
    'قَالُوا۟ فَمَا جَزَ ٰ⁠ۤؤُهُۥۤ إِن كُنتُمۡ كَـٰذِبِینَ',
    'قالوا فما جزاؤه ان كنتم كاذبين',
    'قَالُو<rule class=slnt>اۡ</rule> فَمَا جَز<rule class=madda_obligatory_mottasel>ٰ</rule>ٓؤُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ كَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٧٤',
    74, 13, 3, 244, 201, 97, 'false'
  );
  
  -- Ayah 75 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1671,
    'قَالُوا۟ جَزَ ٰ⁠ۤؤُهُۥ مَن وُجِدَ فِی رَحۡلِهِۦ فَهُوَ جَزَ ٰ⁠ۤؤُهُۥۚ كَذَ ٰ⁠لِكَ نَجۡزِی ٱلظَّـٰلِمِینَ',
    'قالوا جزاؤه من وجد في رحله فهو جزاؤه كذلك نجزي الظالمين',
    'قَالُو<rule class=slnt>اۡ</rule> جَز<rule class=madda_obligatory_mottasel>ٰ</rule>ٓؤُهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>و</rule>ُجِدَ فِى رَحۡلِه<rule class=madda_normal>ِۦ</rule> فَهُوَ جَز<rule class=madda_obligatory_mottasel>ٰ</rule>ٓؤُهُ<rule class=madda_normal>ۥ</rule>‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٧٥',
    75, 13, 3, 244, 201, 97, 'false'
  );
  
  -- Ayah 76 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1672,
    'فَبَدَأَ بِأَوۡعِیَتِهِمۡ قَبۡلَ وِعَاۤءِ أَخِیهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن وِعَاۤءِ أَخِیهِۚ كَذَ ٰ⁠لِكَ كِدۡنَا لِیُوسُفَۖ مَا كَانَ لِیَأۡخُذَ أَخَاهُ فِی دِینِ ٱلۡمَلِكِ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَـٰتࣲ مَّن نَّشَاۤءُۗ وَفَوۡقَ كُلِّ ذِی عِلۡمٍ عَلِیمࣱ',
    'فبدا باوعيتهم قبل وعاء اخيه ثم استخرجها من وعاء اخيه كذلك كدنا ليوسف ما كان لياخذ اخاه في دين الملك الا ان يشاء الله نرفع درجات من نشاء وفوق كل ذي علم عليم',
    'فَبَدَأَ بِأَوۡعِيَتِهِمۡ قَ<rule class=qalaqah>بۡ</rule>لَ وِع<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَخِيهِ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَخۡرَجَهَا م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>ِع<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَخِيهِ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ كِ<rule class=qalaqah>دۡ</rule>نَا لِيُوسُفَ‌ۖ مَا كَانَ لِيَأۡخُذَ أَخَاهُ فِى دِينِ <rule class=ham_wasl>ٱ</rule>لۡمَلِكِ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ نَرۡفَعُ دَرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَفَوۡقَ كُلِّ ذِى عِلۡمٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٧٦',
    76, 13, 3, 244, 201, 97, 'false'
  );
  
  -- Ayah 77 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1673,
    '۞ قَالُوۤا۟ إِن یَسۡرِقۡ فَقَدۡ سَرَقَ أَخࣱ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا یُوسُفُ فِی نَفۡسِهِۦ وَلَمۡ یُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرࣱّ مَّكَانࣰاۖ وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ',
    'قالوا ان يسرق فقد سرق اخ له من قبل فاسرها يوسف في نفسه ولم يبدها لهم قال انتم شر مكانا والله اعلم بما تصفون',
    '۞قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡرِ<rule class=qalaqah>قۡ</rule> فَقَ<rule class=qalaqah>دۡ</rule> سَرَقَ أَ<rule class=idgham_wo_ghunnah>خٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۚ فَأَسَرَّهَا يُوسُفُ فِى نَفۡسِه<rule class=madda_normal>ِۦ</rule> وَلَمۡ يُ<rule class=qalaqah>بۡ</rule>دِهَا لَهُمۡ‌ۚ قَالَ أَ<rule class=ikhafa>نت</rule>ُمۡ شَ<rule class=idgham_ghunnah>رٌّ</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=idgham_ghunnah>نًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِمَا تَصِف<rule class=madda_permissible>ُو</rule>نَ ٧٧',
    77, 13, 3, 244, 201, 98, 'false'
  );
  
  -- Ayah 78 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1674,
    'قَالُوا۟ یَـٰۤأَیُّهَا ٱلۡعَزِیزُ إِنَّ لَهُۥۤ أَبࣰا شَیۡخࣰا كَبِیرࣰا فَخُذۡ أَحَدَنَا مَكَانَهُۥۤۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِینَ',
    'قالوا يا ايها العزيز ان له ابا شيخا كبيرا فخذ احدنا مكانه انا نراك من المحسنين',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ إِ<rule class=ghunnah>نّ</rule>َ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َيۡ<rule class=ikhafa>خًا</rule> <rule class=ikhafa>ك</rule>َبِي<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َخُذۡ أَحَدَنَا مَكَانَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َا نَرَ<rule class=madda_normal>ٮٰ</rule>كَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٧٨',
    78, 13, 3, 244, 201, 98, 'false'
  );
  
  -- Ayah 79 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1675,
    'قَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَـٰعَنَا عِندَهُۥۤ إِنَّاۤ إِذࣰا لَّظَـٰلِمُونَ',
    'قال معاذ الله ان ناخذ الا من وجدنا متاعنا عنده انا اذا لظالمون',
    'قَالَ مَعَاذَ <rule class=ham_wasl>ٱ</rule>للَّهِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّأۡخُذَ إِلَّا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>و</rule>َجَ<rule class=qalaqah>دۡ</rule>نَا مَتَ<rule class=madda_normal>ـٰ</rule>عَنَا عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 13, 3, 245, 201, 98, 'false'
  );
  
  -- Ayah 80 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1676,
    'فَلَمَّا ٱسۡتَیۡـَٔسُوا۟ مِنۡهُ خَلَصُوا۟ نَجِیࣰّاۖ قَالَ كَبِیرُهُمۡ أَلَمۡ تَعۡلَمُوۤا۟ أَنَّ أَبَاكُمۡ قَدۡ أَخَذَ عَلَیۡكُم مَّوۡثِقࣰا مِّنَ ٱللَّهِ وَمِن قَبۡلُ مَا فَرَّطتُمۡ فِی یُوسُفَۖ فَلَنۡ أَبۡرَحَ ٱلۡأَرۡضَ حَتَّىٰ یَأۡذَنَ لِیۤ أَبِیۤ أَوۡ یَحۡكُمَ ٱللَّهُ لِیۖ وَهُوَ خَیۡرُ ٱلۡحَـٰكِمِینَ',
    'فلما استياسوا منه خلصوا نجيا قال كبيرهم الم تعلموا ان اباكم قد اخذ عليكم موثقا من الله ومن قبل ما فرطتم في يوسف فلن ابرح الارض حتى ياذن لي ابي او يحكم الله لي وهو خير الحاكمين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>سۡتَيۡــَٔسُو<rule class=slnt>اۡ</rule> مِنۡهُ خَلَصُو<rule class=slnt>اۡ</rule> نَجِي<rule class=ikhafa>ًّا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ كَبِيرُهُمۡ أَلَمۡ تَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ أَبَاكُمۡ قَ<rule class=qalaqah>دۡ</rule> أَخَذَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوۡثِ<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ مَا فَرَّطتُمۡ فِى يُوسُفَ‌ۖ فَلَنۡ أَ<rule class=qalaqah>بۡ</rule>رَحَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ حَتَّىٰ يَأۡذَنَ ل<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَب<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَوۡ يَحۡكُمَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِى‌ۖ وَهُوَ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>كِم<rule class=madda_permissible>ِي</rule>نَ ٨٠',
    80, 13, 3, 245, 202, 98, 'false'
  );
  
  -- Ayah 81 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1677,
    'ٱرۡجِعُوۤا۟ إِلَىٰۤ أَبِیكُمۡ فَقُولُوا۟ یَـٰۤأَبَانَاۤ إِنَّ ٱبۡنَكَ سَرَقَ وَمَا شَهِدۡنَاۤ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَیۡبِ حَـٰفِظِینَ',
    'ارجعوا الى ابيكم فقولوا يا ابانا ان ابنك سرق وما شهدنا الا بما علمنا وما كنا للغيب حافظين',
    'ٱرۡجِع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَبِيكُمۡ فَقُولُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَان<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَكَ سَرَقَ وَمَا شَهِ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا بِمَا عَلِمۡنَا وَمَا كُ<rule class=ghunnah>نّ</rule>َا لِلۡغَيۡبِ حَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ِي</rule>نَ ٨١',
    81, 13, 3, 245, 202, 98, 'false'
  );
  
  -- Ayah 82 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1678,
    'وَسۡـَٔلِ ٱلۡقَرۡیَةَ ٱلَّتِی كُنَّا فِیهَا وَٱلۡعِیرَ ٱلَّتِیۤ أَقۡبَلۡنَا فِیهَاۖ وَإِنَّا لَصَـٰدِقُونَ',
    'واسال القرية التي كنا فيها والعير التي اقبلنا فيها وانا لصادقون',
    'وَسۡــَٔلِ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةَ <rule class=ham_wasl>ٱ</rule>لَّتِى كُ<rule class=ghunnah>نّ</rule>َا فِيهَا وَ<rule class=ham_wasl>ٱ</rule>لۡعِيرَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>قۡ</rule>بَلۡنَا فِيهَا‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َا لَصَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 13, 3, 245, 202, 98, 'false'
  );
  
  -- Ayah 83 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1679,
    'قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرࣰاۖ فَصَبۡرࣱ جَمِیلٌۖ عَسَى ٱللَّهُ أَن یَأۡتِیَنِی بِهِمۡ جَمِیعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ',
    'قال بل سولت لكم انفسكم امرا فصبر جميل عسى الله ان ياتيني بهم جميعا انه هو العليم الحكيم',
    'قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَ<rule class=ikhafa>نف</rule>ُسُكُمۡ أَمۡ<rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َصَ<rule class=qalaqah>بۡ</rule><rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ج</rule>َمِيلٌ‌ۖ عَسَى <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَنِى بِهِمۡ جَمِيعًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِيمُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٨٣',
    83, 13, 3, 245, 202, 98, 'false'
  );
  
  -- Ayah 84 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1680,
    'وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ یَـٰۤأَسَفَىٰ عَلَىٰ یُوسُفَ وَٱبۡیَضَّتۡ عَیۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِیمࣱ',
    'وتولى عنهم وقال يا اسفى على يوسف وابيضت عيناه من الحزن فهو كظيم',
    'وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَسَفَىٰ عَلَىٰ يُوسُفَ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>يَضَّتۡ عَيۡنَاهُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحُزۡنِ فَهُوَ كَظ<rule class=madda_permissible>ِي</rule>مٌ ٨٤',
    84, 13, 3, 245, 202, 98, 'false'
  );
  
  -- Ayah 85 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1681,
    'قَالُوا۟ تَٱللَّهِ تَفۡتَؤُا۟ تَذۡكُرُ یُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَـٰلِكِینَ',
    'قالوا تالله تفتا تذكر يوسف حتى تكون حرضا او تكون من الهالكين',
    'قَالُو<rule class=slnt>اۡ</rule> تَ<rule class=ham_wasl>ٱ</rule>للَّهِ تَفۡتَؤُ<rule class=slnt>اۡ</rule> تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡهَ<rule class=madda_normal>ـٰ</rule>لِك<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 13, 3, 245, 202, 98, 'false'
  );
  
  -- Ayah 86 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1682,
    'قَالَ إِنَّمَاۤ أَشۡكُوا۟ بَثِّی وَحُزۡنِیۤ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ',
    'قال انما اشكو بثي وحزني الى الله واعلم من الله ما لا تعلمون',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡكُو<rule class=slnt>اۡ</rule> بَثِّى وَحُزۡن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَأَعۡلَمُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨٦',
    86, 13, 3, 245, 202, 98, 'false'
  );
  
  -- Ayah 87 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1683,
    'یَـٰبَنِیَّ ٱذۡهَبُوا۟ فَتَحَسَّسُوا۟ مِن یُوسُفَ وَأَخِیهِ وَلَا تَا۟یۡـَٔسُوا۟ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا یَا۟یۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَـٰفِرُونَ',
    'يا بني اذهبوا فتحسسوا من يوسف واخيه ولا تياسوا من روح الله انه لا يياس من روح الله الا القوم الكافرون',
    'يَ<rule class=madda_normal>ـٰ</rule>بَنِىَّ <rule class=ham_wasl>ٱ</rule>ذۡهَبُو<rule class=slnt>اۡ</rule> فَتَحَسَّسُو<rule class=slnt>اۡ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُوسُفَ وَأَخِيهِ وَلَا تَ<rule class=slnt>اۡ</rule>يۡــَٔسُو<rule class=slnt>اۡ</rule> م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّوۡحِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يَ<rule class=slnt>اۡ</rule>يۡــَٔسُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّوۡحِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡقَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٨٧',
    87, 13, 3, 246, 202, 98, 'false'
  );
  
  -- Ayah 88 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1684,
    'فَلَمَّا دَخَلُوا۟ عَلَیۡهِ قَالُوا۟ یَـٰۤأَیُّهَا ٱلۡعَزِیزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَـٰعَةࣲ مُّزۡجَىٰةࣲ فَأَوۡفِ لَنَا ٱلۡكَیۡلَ وَتَصَدَّقۡ عَلَیۡنَاۤۖ إِنَّ ٱللَّهَ یَجۡزِی ٱلۡمُتَصَدِّقِینَ',
    'فلما دخلوا عليه قالوا يا ايها العزيز مسنا واهلنا الضر وجئنا ببضاعة مزجاة فاوف لنا الكيل وتصدق علينا ان الله يجزي المتصدقين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا دَخَلُو<rule class=slnt>اۡ</rule> عَلَيۡهِ قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ مَسَّنَا وَأَهۡلَنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّرُّ وَجِئۡنَا بِبِضَ<rule class=madda_normal>ـٰ</rule>عَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّزۡجَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َأَوۡفِ لَنَا <rule class=ham_wasl>ٱ</rule>لۡكَيۡلَ وَتَصَدَّ<rule class=qalaqah>قۡ</rule> عَلَيۡن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لۡمُتَصَدِّق<rule class=madda_permissible>ِي</rule>نَ ٨٨',
    88, 13, 3, 246, 202, 98, 'false'
  );
  
  -- Ayah 89 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1685,
    'قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِیُوسُفَ وَأَخِیهِ إِذۡ أَنتُمۡ جَـٰهِلُونَ',
    'قال هل علمتم ما فعلتم بيوسف واخيه اذ انتم جاهلون',
    'قَالَ هَلۡ عَلِمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا فَعَلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِيُوسُفَ وَأَخِيهِ إِذۡ أَ<rule class=ikhafa>نت</rule>ُمۡ جَ<rule class=madda_normal>ـٰ</rule>هِل<rule class=madda_permissible>ُو</rule>نَ ٨٩',
    89, 13, 3, 246, 202, 98, 'false'
  );
  
  -- Ayah 90 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1686,
    'قَالُوۤا۟ أَءِنَّكَ لَأَنتَ یُوسُفُۖ قَالَ أَنَا۠ یُوسُفُ وَهَـٰذَاۤ أَخِیۖ قَدۡ مَنَّ ٱللَّهُ عَلَیۡنَاۤۖ إِنَّهُۥ مَن یَتَّقِ وَیَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا یُضِیعُ أَجۡرَ ٱلۡمُحۡسِنِینَ',
    'قالوا اانك لانت يوسف قال انا يوسف وهذا اخي قد من الله علينا انه من يتق ويصبر فان الله لا يضيع اجر المحسنين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَءِ<rule class=ghunnah>نّ</rule>َكَ لَأَ<rule class=ikhafa>نت</rule>َ يُوسُفُ‌ۖ قَالَ أَنَاۡ يُوسُفُ وَهَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> أَخِى‌ۖ قَ<rule class=qalaqah>دۡ</rule> مَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّقِ وَيَصۡبِرۡ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُضِيعُ أَ<rule class=qalaqah>جۡ</rule>رَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٩٠',
    90, 13, 3, 246, 202, 98, 'false'
  );
  
  -- Ayah 91 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1687,
    'قَالُوا۟ تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَیۡنَا وَإِن كُنَّا لَخَـٰطِـِٔینَ',
    'قالوا تالله لقد اثرك الله علينا وان كنا لخاطئين',
    'قَالُو<rule class=slnt>اۡ</rule> تَ<rule class=ham_wasl>ٱ</rule>للَّهِ لَقَ<rule class=qalaqah>دۡ</rule> ءَاثَرَكَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡنَا وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا لَخَ<rule class=madda_normal>ـٰ</rule>طِــٔ<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 13, 3, 246, 202, 98, 'false'
  );
  
  -- Ayah 92 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1688,
    'قَالَ لَا تَثۡرِیبَ عَلَیۡكُمُ ٱلۡیَوۡمَۖ یَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّ ٰ⁠حِمِینَ',
    'قال لا تثريب عليكم اليوم يغفر الله لكم وهو ارحم الراحمين',
    'قَالَ لَا تَثۡرِيبَ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ‌ۖ يَغۡفِرُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ‌ۖ وَهُوَ أَرۡحَمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>حِم<rule class=madda_permissible>ِي</rule>نَ ٩٢',
    92, 13, 3, 246, 202, 98, 'false'
  );
  
  -- Ayah 93 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1689,
    'ٱذۡهَبُوا۟ بِقَمِیصِی هَـٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِی یَأۡتِ بَصِیرࣰا وَأۡتُونِی بِأَهۡلِكُمۡ أَجۡمَعِینَ',
    'اذهبوا بقميصي هذا فالقوه على وجه ابي يات بصيرا واتوني باهلكم اجمعين',
    'ٱذۡهَبُو<rule class=slnt>اۡ</rule> بِقَمِيصِى هَ<rule class=madda_normal>ـٰ</rule>ذَا فَأَلۡقُوهُ عَلَىٰ وَ<rule class=qalaqah>جۡ</rule>هِ أَبِى يَأۡتِ بَصِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َأۡتُونِى بِأَهۡلِكُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٩٣',
    93, 13, 3, 246, 202, 98, 'false'
  );
  
  -- Ayah 94 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1690,
    'وَلَمَّا فَصَلَتِ ٱلۡعِیرُ قَالَ أَبُوهُمۡ إِنِّی لَأَجِدُ رِیحَ یُوسُفَۖ لَوۡلَاۤ أَن تُفَنِّدُونِ',
    'ولما فصلت العير قال ابوهم اني لاجد ريح يوسف لولا ان تفندون',
    'وَلَ<rule class=ghunnah>مّ</rule>َا فَصَلَتِ <rule class=ham_wasl>ٱ</rule>لۡعِيرُ قَالَ أَبُوهُمۡ إِ<rule class=ghunnah>نّ</rule>ِى لَأَجِدُ رِيحَ يُوسُفَ‌ۖ لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُفَ<rule class=ghunnah>نّ</rule>ِد<rule class=madda_permissible>ُو</rule>نِ ٩٤',
    94, 13, 3, 246, 203, 98, 'false'
  );
  
  -- Ayah 95 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1691,
    'قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِی ضَلَـٰلِكَ ٱلۡقَدِیمِ',
    'قالوا تالله انك لفي ضلالك القديم',
    'قَالُو<rule class=slnt>اۡ</rule> تَ<rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ghunnah>نّ</rule>َكَ لَفِى ضَلَ<rule class=madda_normal>ـٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡقَد<rule class=madda_permissible>ِي</rule>مِ ٩٥',
    95, 13, 3, 246, 203, 98, 'false'
  );
  
  -- Ayah 96 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1692,
    'فَلَمَّاۤ أَن جَاۤءَ ٱلۡبَشِیرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِیرࣰاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّیۤ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ',
    'فلما ان جاء البشير القاه على وجهه فارتد بصيرا قال الم اقل لكم اني اعلم من الله ما لا تعلمون',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡبَشِيرُ أَلۡقَ<rule class=madda_normal>ـٰ</rule>هُ عَلَىٰ وَ<rule class=qalaqah>جۡ</rule>هِه<rule class=madda_normal>ِۦ</rule> فَ<rule class=ham_wasl>ٱ</rule>رۡتَدَّ بَصِي<rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ أَلَمۡ أَقُل لَّكُمۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡلَمُ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 13, 3, 247, 203, 98, 'false'
  );
  
  -- Ayah 97 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1693,
    'قَالُوا۟ یَـٰۤأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَاۤ إِنَّا كُنَّا خَـٰطِـِٔینَ',
    'قالوا يا ابانا استغفر لنا ذنوبنا انا كنا خاطئين',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَانَا <rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرۡ لَنَا ذُنُوبَن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا خَ<rule class=madda_normal>ـٰ</rule>طِــٔ<rule class=madda_permissible>ِي</rule>نَ ٩٧',
    97, 13, 3, 247, 203, 98, 'false'
  );
  
  -- Ayah 98 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1694,
    'قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّیۤۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ',
    'قال سوف استغفر لكم ربي انه هو الغفور الرحيم',
    'قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَفُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٩٨',
    98, 13, 3, 247, 203, 98, 'false'
  );
  
  -- Ayah 99 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1695,
    'فَلَمَّا دَخَلُوا۟ عَلَىٰ یُوسُفَ ءَاوَىٰۤ إِلَیۡهِ أَبَوَیۡهِ وَقَالَ ٱدۡخُلُوا۟ مِصۡرَ إِن شَاۤءَ ٱللَّهُ ءَامِنِینَ',
    'فلما دخلوا على يوسف اوى اليه ابويه وقال ادخلوا مصر ان شاء الله امنين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا دَخَلُو<rule class=slnt>اۡ</rule> عَلَىٰ يُوسُفَ ءَاوَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡهِ أَبَوَيۡهِ وَقَالَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> مِصۡرَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ ءَامِن<rule class=madda_permissible>ِي</rule>نَ ٩٩',
    99, 13, 3, 247, 203, 98, 'false'
  );
  
  -- Ayah 100 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1696,
    'وَرَفَعَ أَبَوَیۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّوا۟ لَهُۥ سُجَّدࣰاۖ وَقَالَ یَـٰۤأَبَتِ هَـٰذَا تَأۡوِیلُ رُءۡیَـٰیَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّی حَقࣰّاۖ وَقَدۡ أَحۡسَنَ بِیۤ إِذۡ أَخۡرَجَنِی مِنَ ٱلسِّجۡنِ وَجَاۤءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّیۡطَـٰنُ بَیۡنِی وَبَیۡنَ إِخۡوَتِیۤۚ إِنَّ رَبِّی لَطِیفࣱ لِّمَا یَشَاۤءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ',
    'ورفع ابويه على العرش وخروا له سجدا وقال يا ابت هذا تاويل رؤياي من قبل قد جعلها ربي حقا وقد احسن بي اذ اخرجني من السجن وجاء بكم من البدو من بعد ان نزغ الشيطان بيني وبين اخوتي ان ربي لطيف لما يشاء انه هو العليم الحكيم',
    'وَرَفَعَ أَبَوَيۡهِ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ وَخَرُّو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> سُجَّ<rule class=idgham_ghunnah>دًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَتِ هَ<rule class=madda_normal>ـٰ</rule>ذَا تَأۡوِيلُ رُءۡيَ<rule class=madda_normal>ـٰ</rule>ىَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ قَ<rule class=qalaqah>دۡ</rule> جَعَلَهَا رَبِّى حَق<rule class=idgham_ghunnah>ًّا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َقَ<rule class=qalaqah>دۡ</rule> أَحۡسَنَ ب<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِذۡ أَخۡرَجَنِى مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=qalaqah>جۡ</rule>نِ وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=qalaqah>دۡ</rule>وِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّزَغَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ بَيۡنِى وَبَيۡنَ إِخۡوَت<rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ رَبِّى لَطِي<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِيمُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ١٠٠',
    100, 13, 3, 247, 203, 98, 'false'
  );
  
  -- Ayah 101 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1697,
    '۞ رَبِّ قَدۡ ءَاتَیۡتَنِی مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِی مِن تَأۡوِیلِ ٱلۡأَحَادِیثِۚ فَاطِرَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ أَنتَ وَلِیِّۦ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۖ تَوَفَّنِی مُسۡلِمࣰا وَأَلۡحِقۡنِی بِٱلصَّـٰلِحِینَ',
    'رب قد اتيتني من الملك وعلمتني من تاويل الاحاديث فاطر السماوات والارض انت وليي في الدنيا والاخرة توفني مسلما والحقني بالصالحين',
    '۞رَبِّ قَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡتَنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكِ وَعَلَّمۡتَنِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡوِيلِ <rule class=ham_wasl>ٱ</rule>لۡأَحَادِيثِ‌ۚ فَاطِرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَ<rule class=ikhafa>نت</rule>َ وَلِىّ<rule class=madda_normal>ِۦ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ تَوَفَّنِى مُسۡلِ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َأَلۡحِ<rule class=qalaqah>قۡ</rule>نِى بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ١٠١',
    101, 13, 3, 247, 203, 99, 'false'
  );
  
  -- Ayah 102 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1698,
    'ذَ ٰ⁠لِكَ مِنۡ أَنۢبَاۤءِ ٱلۡغَیۡبِ نُوحِیهِ إِلَیۡكَۖ وَمَا كُنتَ لَدَیۡهِمۡ إِذۡ أَجۡمَعُوۤا۟ أَمۡرَهُمۡ وَهُمۡ یَمۡكُرُونَ',
    'ذلك من انباء الغيب نوحيه اليك وما كنت لديهم اذ اجمعوا امرهم وهم يمكرون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ مِنۡ أَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ نُوحِيهِ إِلَيۡكَ‌ۖ وَمَا كُ<rule class=ikhafa>نت</rule>َ لَدَيۡهِمۡ إِذۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرَهُمۡ وَهُمۡ يَمۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٠٢',
    102, 13, 3, 247, 203, 99, 'false'
  );
  
  -- Ayah 103 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1699,
    'وَمَاۤ أَكۡثَرُ ٱلنَّاسِ وَلَوۡ حَرَصۡتَ بِمُؤۡمِنِینَ',
    'وما اكثر الناس ولو حرصت بمؤمنين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡثَرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَوۡ حَرَصۡتَ بِمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٠٣',
    103, 13, 3, 247, 203, 99, 'false'
  );
  
  -- Ayah 104 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1700,
    'وَمَا تَسۡـَٔلُهُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۚ إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَـٰلَمِینَ',
    'وما تسالهم عليه من اجر ان هو الا ذكر للعالمين',
    'وَمَا تَسۡــَٔلُهُمۡ عَلَيۡهِ مِنۡ أَ<rule class=qalaqah>جۡ</rule>رٍ‌ۚ إِنۡ هُوَ إِلَّا ذِكۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٠٤',
    104, 13, 3, 248, 203, 99, 'false'
  );
  
  -- Ayah 105 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1701,
    'وَكَأَیِّن مِّنۡ ءَایَةࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ یَمُرُّونَ عَلَیۡهَا وَهُمۡ عَنۡهَا مُعۡرِضُونَ',
    'وكاين من اية في السماوات والارض يمرون عليها وهم عنها معرضون',
    'وَكَأَيّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ ءَايَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يَمُرُّونَ عَلَيۡهَا وَهُمۡ عَنۡهَا مُعۡرِض<rule class=madda_permissible>ُو</rule>نَ ١٠٥',
    105, 13, 3, 248, 204, 99, 'false'
  );
  
  -- Ayah 106 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1702,
    'وَمَا یُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ',
    'وما يؤمن اكثرهم بالله الا وهم مشركون',
    'وَمَا يُؤۡمِنُ أَكۡثَرُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ إِلَّا وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّشۡرِك<rule class=madda_permissible>ُو</rule>نَ ١٠٦',
    106, 13, 3, 248, 204, 99, 'false'
  );
  
  -- Ayah 107 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1703,
    'أَفَأَمِنُوۤا۟ أَن تَأۡتِیَهُمۡ غَـٰشِیَةࣱ مِّنۡ عَذَابِ ٱللَّهِ أَوۡ تَأۡتِیَهُمُ ٱلسَّاعَةُ بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ',
    'افامنوا ان تاتيهم غاشية من عذاب الله او تاتيهم الساعة بغتة وهم لا يشعرون',
    'أَفَأَمِن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡتِيَهُمۡ غَ<rule class=madda_normal>ـٰ</rule>شِيَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عَذَابِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡ تَأۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ بَغۡتَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ١٠٧',
    107, 13, 3, 248, 204, 99, 'false'
  );
  
  -- Ayah 108 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1704,
    'قُلۡ هَـٰذِهِۦ سَبِیلِیۤ أَدۡعُوۤا۟ إِلَى ٱللَّهِۚ عَلَىٰ بَصِیرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِیۖ وَسُبۡحَـٰنَ ٱللَّهِ وَمَاۤ أَنَا۠ مِنَ ٱلۡمُشۡرِكِینَ',
    'قل هذه سبيلي ادعو الى الله على بصيرة انا ومن اتبعني وسبحان الله وما انا من المشركين',
    'قُلۡ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> سَبِيل<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>دۡ</rule>ع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ عَلَىٰ بَصِيرَةٍ أَنَاۡ وَمَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَنِى‌ۖ وَسُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١٠٨',
    108, 13, 3, 248, 204, 99, 'false'
  );
  
  -- Ayah 109 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1705,
    'وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالࣰا نُّوحِیۤ إِلَیۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰۤۗ أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡـَٔاخِرَةِ خَیۡرࣱ لِّلَّذِینَ ٱتَّقَوۡا۟ۚ أَفَلَا تَعۡقِلُونَ',
    'وما ارسلنا من قبلك الا رجالا نوحي اليهم من اهل القرى افلم يسيروا في الارض فينظروا كيف كان عاقبة الذين من قبلهم ولدار الاخرة خير للذين اتقوا افلا تعقلون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ إِلَّا رِجَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ن</rule>ُّوح<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡقُرَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۗ</rule> أَفَلَمۡ يَسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَيَ<rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۗ وَلَدَارُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ‌ۗ</rule> أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٠٩',
    109, 13, 3, 248, 204, 99, 'false'
  );
  
  -- Ayah 110 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1706,
    'حَتَّىٰۤ إِذَا ٱسۡتَیۡـَٔسَ ٱلرُّسُلُ وَظَنُّوۤا۟ أَنَّهُمۡ قَدۡ كُذِبُوا۟ جَاۤءَهُمۡ نَصۡرُنَا فَنُجِّیَ مَن نَّشَاۤءُۖ وَلَا یُرَدُّ بَأۡسُنَا عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِینَ',
    'حتى اذا استياس الرسل وظنوا انهم قد كذبوا جاءهم نصرنا فنجي من نشاء ولا يرد باسنا عن القوم المجرمين',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا <rule class=ham_wasl>ٱ</rule>سۡتَيۡــَٔسَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلُ وَظَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ قَ<rule class=qalaqah>دۡ</rule> كُذِبُو<rule class=slnt>اۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ نَصۡرُنَا فَنُجِّىَ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ وَلَا يُرَدُّ بَأۡسُنَا عَنِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ١١٠',
    110, 13, 3, 248, 204, 99, 'false'
  );
  
  -- Ayah 111 Surah Yusuf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    12,
    1707,
    'لَقَدۡ كَانَ فِی قَصَصِهِمۡ عِبۡرَةࣱ لِّأُو۟لِی ٱلۡأَلۡبَـٰبِۗ مَا كَانَ حَدِیثࣰا یُفۡتَرَىٰ وَلَـٰكِن تَصۡدِیقَ ٱلَّذِی بَیۡنَ یَدَیۡهِ وَتَفۡصِیلَ كُلِّ شَیۡءࣲ وَهُدࣰى وَرَحۡمَةࣰ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'لقد كان في قصصهم عبرة لاولي الالباب ما كان حديثا يفترى ولكن تصديق الذي بين يديه وتفصيل كل شيء وهدى ورحمة لقوم يؤمنون',
    'لَقَ<rule class=qalaqah>دۡ</rule> كَانَ فِى قَصَصِهِمۡ عِ<rule class=qalaqah>بۡ</rule>رَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_normal>ـٰ</rule>بِ‌ۗ مَا كَانَ حَدِي<rule class=idgham_ghunnah>ثًا</rule> <rule class=idgham_ghunnah>ي</rule>ُفۡتَرَىٰ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصۡدِيقَ <rule class=ham_wasl>ٱ</rule>لَّذِى بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١١١',
    111, 13, 3, 248, 204, 99, 'false'
  );
  

-- Surah Ar-Rad
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (13, 'سُورَةُ الرَّعۡدِ', 'Ar-Rad', 'The Thunder', 'Medinan', 43);

  -- Ayah 1 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1708,
    'الۤمۤرۚ تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِۗ وَٱلَّذِیۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ ٱلۡحَقُّ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یُؤۡمِنُونَ',
    'المر تلك ايات الكتاب والذي انزل اليك من ربك الحق ولكن اكثر الناس لا يؤمنون',
    'ا<rule class=madda_necessary>لٓ</rule><rule class=madda_necessary>مٓ</rule>ر‌ۚ تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 13, 3, 249, 205, 99, 'false'
  );
  
  -- Ayah 2 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1709,
    'ٱللَّهُ ٱلَّذِی رَفَعَ ٱلسَّمَـٰوَ ٰ⁠تِ بِغَیۡرِ عَمَدࣲ تَرَوۡنَهَاۖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِی لِأَجَلࣲ مُّسَمࣰّىۚ یُدَبِّرُ ٱلۡأَمۡرَ یُفَصِّلُ ٱلۡـَٔایَـٰتِ لَعَلَّكُم بِلِقَاۤءِ رَبِّكُمۡ تُوقِنُونَ',
    'الله الذي رفع السماوات بغير عمد ترونها ثم استوى على العرش وسخر الشمس والقمر كل يجري لاجل مسمى يدبر الامر يفصل الايات لعلكم بلقاء ربكم توقنون',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى رَفَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ بِغَيۡرِ عَمَ<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ت</rule>َرَوۡنَهَا‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ‌ۖ وَسَخَّرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ‌ۖ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>رِى لِأَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=idgham_ghunnah>ًّى‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>ُدَبِّرُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرَ يُفَصِّلُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لَعَلَّك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رَبِّكُمۡ تُوقِن<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 13, 3, 249, 205, 99, 'false'
  );
  
  -- Ayah 3 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1710,
    'وَهُوَ ٱلَّذِی مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِیهَا رَوَ ٰ⁠سِیَ وَأَنۡهَـٰرࣰاۖ وَمِن كُلِّ ٱلثَّمَرَ ٰ⁠تِ جَعَلَ فِیهَا زَوۡجَیۡنِ ٱثۡنَیۡنِۖ یُغۡشِی ٱلَّیۡلَ ٱلنَّهَارَۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ',
    'وهو الذي مد الارض وجعل فيها رواسي وانهارا ومن كل الثمرات جعل فيها زوجين اثنين يغشي الليل النهار ان في ذلك لايات لقوم يتفكرون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى مَدَّ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَجَعَلَ فِيهَا رَو<rule class=madda_normal>ٰ</rule>سِىَ وَأَنۡهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ جَعَلَ فِيهَا زَوۡجَيۡنِ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ‌ۖ يُغۡشِى <rule class=ham_wasl>ٱ</rule>لَّيۡلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 13, 3, 249, 205, 99, 'false'
  );
  
  -- Ayah 4 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1711,
    'وَفِی ٱلۡأَرۡضِ قِطَعࣱ مُّتَجَـٰوِرَ ٰ⁠تࣱ وَجَنَّـٰتࣱ مِّنۡ أَعۡنَـٰبࣲ وَزَرۡعࣱ وَنَخِیلࣱ صِنۡوَانࣱ وَغَیۡرُ صِنۡوَانࣲ یُسۡقَىٰ بِمَاۤءࣲ وَ ٰ⁠حِدࣲ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضࣲ فِی ٱلۡأُكُلِۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ',
    'وفي الارض قطع متجاورات وجنات من اعناب وزرع ونخيل صنوان وغير صنوان يسقى بماء واحد ونفضل بعضها على بعض في الاكل ان في ذلك لايات لقوم يعقلون',
    'وَفِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ قِطَ<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّتَجَ<rule class=madda_normal>ـٰ</rule>وِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>و</rule>َجَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَعۡنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َزَرۡ<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>و</rule>َنَخِي<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ص</rule>ِنۡوَا<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>و</rule>َغَيۡرُ صِنۡوَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُسۡقَىٰ بِم<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأُكُلِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 13, 3, 249, 205, 99, 'false'
  );
  
  -- Ayah 5 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1712,
    '۞ وَإِن تَعۡجَبۡ فَعَجَبࣱ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَ ٰ⁠بًا أَءِنَّا لَفِی خَلۡقࣲ جَدِیدٍۗ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡۖ وَأُو۟لَـٰۤىِٕكَ ٱلۡأَغۡلَـٰلُ فِیۤ أَعۡنَاقِهِمۡۖ وَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'وان تعجب فعجب قولهم ااذا كنا ترابا اانا لفي خلق جديد اولئك الذين كفروا بربهم واولئك الاغلال في اعناقهم واولئك اصحاب النار هم فيها خالدون',
    '۞وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡجَ<rule class=qalaqah>بۡ</rule> فَعَجَ<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ق</rule>َوۡلُهُمۡ أَءِذَا كُ<rule class=ghunnah>نّ</rule>َا تُر<rule class=madda_normal>ٰ</rule>بًا أَءِ<rule class=ghunnah>نّ</rule>َا لَفِى خَلۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ج</rule>َدِيدٍ‌ۗ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِرَبِّهِمۡ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لۡأَغۡلَ<rule class=madda_normal>ـٰ</rule>لُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡنَاقِهِمۡ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 13, 3, 249, 205, 100, 'false'
  );
  
  -- Ayah 6 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1713,
    'وَیَسۡتَعۡجِلُونَكَ بِٱلسَّیِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ وَقَدۡ خَلَتۡ مِن قَبۡلِهِمُ ٱلۡمَثُلَـٰتُۗ وَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةࣲ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ وَإِنَّ رَبَّكَ لَشَدِیدُ ٱلۡعِقَابِ',
    'ويستعجلونك بالسيئة قبل الحسنة وقد خلت من قبلهم المثلات وان ربك لذو مغفرة للناس على ظلمهم وان ربك لشديد العقاب',
    'وَيَسۡتَعۡجِلُونَكَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةِ قَ<rule class=qalaqah>بۡ</rule>لَ <rule class=ham_wasl>ٱ</rule>لۡحَسَنَةِ وَقَ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمُ <rule class=ham_wasl>ٱ</rule>لۡمَثُلَ<rule class=madda_normal>ـٰ</rule>تُ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَذُو مَغۡفِرَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ عَلَىٰ ظُلۡمِهِمۡ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَشَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٦',
    6, 13, 3, 250, 205, 100, 'false'
  );
  
  -- Ayah 7 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1714,
    'وَیَقُولُ ٱلَّذِینَ كَفَرُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَةࣱ مِّن رَّبِّهِۦۤۗ إِنَّمَاۤ أَنتَ مُنذِرࣱۖ وَلِكُلِّ قَوۡمٍ هَادٍ',
    'ويقول الذين كفروا لولا انزل عليه اية من ربه انما انت منذر ولكل قوم هاد',
    'وَيَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡهِ ءَايَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ مُ<rule class=ikhafa>نذ</rule>ِ<rule class=idgham_ghunnah>رٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلِكُلِّ قَوۡمٍ ه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ٍ ٧',
    7, 13, 3, 250, 205, 100, 'false'
  );
  
  -- Ayah 8 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1715,
    'ٱللَّهُ یَعۡلَمُ مَا تَحۡمِلُ كُلُّ أُنثَىٰ وَمَا تَغِیضُ ٱلۡأَرۡحَامُ وَمَا تَزۡدَادُۚ وَكُلُّ شَیۡءٍ عِندَهُۥ بِمِقۡدَارٍ',
    'الله يعلم ما تحمل كل انثى وما تغيض الارحام وما تزداد وكل شيء عنده بمقدار',
    'ٱللَّهُ يَعۡلَمُ مَا تَحۡمِلُ كُلُّ أُ<rule class=ikhafa>نث</rule>َىٰ وَمَا تَغِيضُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡحَامُ وَمَا تَزۡدَادُ‌ۖ وَكُلُّ شَىۡءٍ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> بِمِ<rule class=qalaqah>قۡ</rule>د<rule class=madda_permissible>َا</rule>رٍ ٨',
    8, 13, 3, 250, 206, 100, 'false'
  );
  
  -- Ayah 9 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1716,
    'عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡكَبِیرُ ٱلۡمُتَعَالِ',
    'عالم الغيب والشهادة الكبير المتعال',
    'عَ<rule class=madda_normal>ـٰ</rule>لِمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ <rule class=ham_wasl>ٱ</rule>لۡكَبِيرُ <rule class=ham_wasl>ٱ</rule>لۡمُتَع<rule class=madda_permissible>َا</rule>لِ ٩',
    9, 13, 3, 250, 206, 100, 'false'
  );
  
  -- Ayah 10 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1717,
    'سَوَاۤءࣱ مِّنكُم مَّنۡ أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ وَمَنۡ هُوَ مُسۡتَخۡفِۭ بِٱلَّیۡلِ وَسَارِبُۢ بِٱلنَّهَارِ',
    'سواء منكم من اسر القول ومن جهر به ومن هو مستخف بالليل وسارب بالنهار',
    'سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ أَسَرَّ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلَ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َهَرَ بِه<rule class=madda_normal>ِۦ</rule> وَمَنۡ هُوَ مُسۡتَخۡ<rule class=iqlab>فِۭ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَسَارِ<rule class=iqlab>بُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َه<rule class=madda_permissible>َا</rule>رِ ١٠',
    10, 13, 3, 250, 206, 100, 'false'
  );
  
  -- Ayah 11 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1718,
    'لَهُۥ مُعَقِّبَـٰتࣱ مِّنۢ بَیۡنِ یَدَیۡهِ وَمِنۡ خَلۡفِهِۦ یَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا یُغَیِّرُ مَا بِقَوۡمٍ حَتَّىٰ یُغَیِّرُوا۟ مَا بِأَنفُسِهِمۡۗ وَإِذَاۤ أَرَادَ ٱللَّهُ بِقَوۡمࣲ سُوۤءࣰا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ',
    'له معقبات من بين يديه ومن خلفه يحفظونه من امر الله ان الله لا يغير ما بقوم حتى يغيروا ما بانفسهم واذا اراد الله بقوم سوءا فلا مرد له وما لهم من دونه من وال',
    'لَهُ<rule class=madda_normal>ۥ</rule> مُعَقِّبَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِه<rule class=madda_normal>ِۦ</rule> يَحۡفَظُونَهُ<rule class=madda_normal>ۥ</rule> مِنۡ أَمۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُغَيِّرُ مَا بِقَوۡمٍ حَتَّىٰ يُغَيِّرُو<rule class=slnt>اۡ</rule> مَا بِأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۗ وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَرَادَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِقَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءًا</rule> <rule class=ikhafa>ف</rule>َلَا مَرَدَّ لَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَمَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_permissible>َا</rule>لٍ ١١',
    11, 13, 3, 250, 206, 100, 'false'
  );
  
  -- Ayah 12 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1719,
    'هُوَ ٱلَّذِی یُرِیكُمُ ٱلۡبَرۡقَ خَوۡفࣰا وَطَمَعࣰا وَیُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ',
    'هو الذي يريكم البرق خوفا وطمعا وينشئ السحاب الثقال',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُرِيكُمُ <rule class=ham_wasl>ٱ</rule>لۡبَرۡقَ خَوۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َطَمَ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َيُ<rule class=ikhafa>نش</rule>ِئُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثِّق<rule class=madda_permissible>َا</rule>لَ ١٢',
    12, 13, 3, 250, 206, 100, 'false'
  );
  
  -- Ayah 13 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1720,
    'وَیُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ وَٱلۡمَلَـٰۤىِٕكَةُ مِنۡ خِیفَتِهِۦ وَیُرۡسِلُ ٱلصَّوَ ٰ⁠عِقَ فَیُصِیبُ بِهَا مَن یَشَاۤءُ وَهُمۡ یُجَـٰدِلُونَ فِی ٱللَّهِ وَهُوَ شَدِیدُ ٱلۡمِحَالِ',
    'ويسبح الرعد بحمده والملائكة من خيفته ويرسل الصواعق فيصيب بها من يشاء وهم يجادلون في الله وهو شديد المحال',
    'وَيُسَبِّحُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّعۡدُ بِحَمۡدِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ مِنۡ خِيفَتِه<rule class=madda_normal>ِۦ</rule> وَيُرۡسِلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّو<rule class=madda_normal>ٰ</rule>عِقَ فَيُصِيبُ بِهَا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَهُمۡ يُجَ<rule class=madda_normal>ـٰ</rule>دِلُونَ فِى <rule class=ham_wasl>ٱ</rule>للَّهِ وَهُوَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡمِح<rule class=madda_permissible>َا</rule>لِ ١٣',
    13, 13, 3, 250, 206, 100, 'false'
  );
  
  -- Ayah 14 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1721,
    'لَهُۥ دَعۡوَةُ ٱلۡحَقِّۚ وَٱلَّذِینَ یَدۡعُونَ مِن دُونِهِۦ لَا یَسۡتَجِیبُونَ لَهُم بِشَیۡءٍ إِلَّا كَبَـٰسِطِ كَفَّیۡهِ إِلَى ٱلۡمَاۤءِ لِیَبۡلُغَ فَاهُ وَمَا هُوَ بِبَـٰلِغِهِۦۚ وَمَا دُعَاۤءُ ٱلۡكَـٰفِرِینَ إِلَّا فِی ضَلَـٰلࣲ',
    'له دعوة الحق والذين يدعون من دونه لا يستجيبون لهم بشيء الا كباسط كفيه الى الماء ليبلغ فاه وما هو ببالغه وما دعاء الكافرين الا في ضلال',
    'لَهُ<rule class=madda_normal>ۥ</rule> دَعۡوَةُ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> لَا يَسۡتَجِيبُونَ لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِشَىۡءٍ إِلَّا كَبَ<rule class=madda_normal>ـٰ</rule>سِطِ كَفَّيۡهِ إِلَى <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ لِيَ<rule class=qalaqah>بۡ</rule>لُغَ فَاهُ وَمَا هُوَ بِبَ<rule class=madda_normal>ـٰ</rule>لِغِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَمَا دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ إِلَّا فِى ضَلَ<rule class=madda_permissible>ـٰ</rule>لٍ ١٤',
    14, 13, 3, 251, 206, 100, 'false'
  );
  
  -- Ayah 15 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1722,
    'وَلِلَّهِ یَسۡجُدُ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ طَوۡعࣰا وَكَرۡهࣰا وَظِلَـٰلُهُم بِٱلۡغُدُوِّ وَٱلۡـَٔاصَالِ ۩',
    'ولله يسجد من في السماوات والارض طوعا وكرها وظلالهم بالغدو والاصال',
    'وَلِلَّهِ يَسۡجُدُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ طَوۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َكَرۡ<rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule>َظِلَ<rule class=madda_normal>ـٰ</rule>لُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡغُدُوِّ وَ<rule class=ham_wasl>ٱ</rule>لۡأَصَ<rule class=madda_permissible>ا</rule>لِ ۩ ١٥',
    15, 13, 3, 251, 206, 100, '{"id":2,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 16 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1723,
    'قُلۡ مَن رَّبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦۤ أَوۡلِیَاۤءَ لَا یَمۡلِكُونَ لِأَنفُسِهِمۡ نَفۡعࣰا وَلَا ضَرࣰّاۚ قُلۡ هَلۡ یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُ أَمۡ هَلۡ تَسۡتَوِی ٱلظُّلُمَـٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُوا۟ لِلَّهِ شُرَكَاۤءَ خَلَقُوا۟ كَخَلۡقِهِۦ فَتَشَـٰبَهَ ٱلۡخَلۡقُ عَلَیۡهِمۡۚ قُلِ ٱللَّهُ خَـٰلِقُ كُلِّ شَیۡءࣲ وَهُوَ ٱلۡوَ ٰ⁠حِدُ ٱلۡقَهَّـٰرُ',
    'قل من رب السماوات والارض قل الله قل افاتخذتم من دونه اولياء لا يملكون لانفسهم نفعا ولا ضرا قل هل يستوي الاعمى والبصير ام هل تستوي الظلمات والنور ام جعلوا لله شركاء خلقوا كخلقه فتشابه الخلق عليهم قل الله خالق كل شيء وهو الواحد القهار',
    'قُلۡ م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ قُلۡ أَفَ<rule class=ham_wasl>ٱ</rule>تَّخَذۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لَا يَمۡلِكُونَ لِأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ نَفۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا ضَر<rule class=ikhafa>ًّا‌ۚ</rule> <rule class=ikhafa>ق</rule>ُلۡ هَلۡ يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡأَعۡمَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡبَصِيرُ أَمۡ هَلۡ تَسۡتَوِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورُ‌ۗ أَمۡ جَعَلُو<rule class=slnt>اۡ</rule> لِلَّهِ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ خَلَقُو<rule class=slnt>اۡ</rule> كَخَلۡقِه<rule class=madda_normal>ِۦ</rule> فَتَشَ<rule class=madda_normal>ـٰ</rule>بَهَ <rule class=ham_wasl>ٱ</rule>لۡخَلۡقُ عَلَيۡهِمۡ‌ۚ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ خَ<rule class=madda_normal>ـٰ</rule>لِقُ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>حِدُ <rule class=ham_wasl>ٱ</rule>لۡقَهَّ<rule class=madda_permissible>ـٰ</rule>رُ ١٦',
    16, 13, 3, 251, 206, 100, 'false'
  );
  
  -- Ayah 17 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1724,
    'أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَسَالَتۡ أَوۡدِیَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّیۡلُ زَبَدࣰا رَّابِیࣰاۖ وَمِمَّا یُوقِدُونَ عَلَیۡهِ فِی ٱلنَّارِ ٱبۡتِغَاۤءَ حِلۡیَةٍ أَوۡ مَتَـٰعࣲ زَبَدࣱ مِّثۡلُهُۥۚ كَذَ ٰ⁠لِكَ یَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَـٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَیَذۡهَبُ جُفَاۤءࣰۖ وَأَمَّا مَا یَنفَعُ ٱلنَّاسَ فَیَمۡكُثُ فِی ٱلۡأَرۡضِۚ كَذَ ٰ⁠لِكَ یَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ',
    'انزل من السماء ماء فسالت اودية بقدرها فاحتمل السيل زبدا رابيا ومما يوقدون عليه في النار ابتغاء حلية او متاع زبد مثله كذلك يضرب الله الحق والباطل فاما الزبد فيذهب جفاء واما ما ينفع الناس فيمكث في الارض كذلك يضرب الله الامثال',
    'أَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َسَالَتۡ أَوۡدِيَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِقَدَرِهَا فَ<rule class=ham_wasl>ٱ</rule>حۡتَمَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيۡلُ زَبَ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّابِ<rule class=idgham_ghunnah>يًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمِ<rule class=ghunnah>مّ</rule>َا يُوقِدُونَ عَلَيۡهِ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ حِلۡيَةٍ أَوۡ مَتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>عٍ</rule> <rule class=ikhafa>ز</rule>َبَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُهُ<rule class=madda_normal>ۥ</rule>‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَضۡرِبُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلَ‌ۚ فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّبَدُ فَيَذۡهَبُ جُف<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>مّ</rule>َا مَا يَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ فَيَمۡكُثُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَضۡرِبُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡث<rule class=madda_permissible>َا</rule>لَ ١٧',
    17, 13, 3, 251, 206, 100, 'false'
  );
  
  -- Ayah 18 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1725,
    'لِلَّذِینَ ٱسۡتَجَابُوا۟ لِرَبِّهِمُ ٱلۡحُسۡنَىٰۚ وَٱلَّذِینَ لَمۡ یَسۡتَجِیبُوا۟ لَهُۥ لَوۡ أَنَّ لَهُم مَّا فِی ٱلۡأَرۡضِ جَمِیعࣰا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡا۟ بِهِۦۤۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ سُوۤءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ',
    'للذين استجابوا لربهم الحسنى والذين لم يستجيبوا له لو ان لهم ما في الارض جميعا ومثله معه لافتدوا به اولئك لهم سوء الحساب وماواهم جهنم وبئس المهاد',
    'لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَجَابُو<rule class=slnt>اۡ</rule> لِرَبِّهِمُ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَمۡ يَسۡتَجِيبُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> لَوۡ أَ<rule class=ghunnah>نّ</rule>َ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َمِثۡلَهُ<rule class=madda_normal>ۥ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> لَ<rule class=ham_wasl>ٱ</rule>فۡتَدَوۡ<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡحِسَابِ وَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمِه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ُ ١٨',
    18, 13, 3, 251, 206, 100, 'false'
  );
  
  -- Ayah 19 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1726,
    '۞ أَفَمَن یَعۡلَمُ أَنَّمَاۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰۤۚ إِنَّمَا یَتَذَكَّرُ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ',
    'افمن يعلم انما انزل اليك من ربك الحق كمن هو اعمى انما يتذكر اولو الالباب',
    '۞أَفَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَمُ أَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ كَمَنۡ هُوَ أَعۡمَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا يَتَذَكَّرُ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ١٩',
    19, 13, 3, 252, 207, 101, 'false'
  );
  
  -- Ayah 20 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1727,
    'ٱلَّذِینَ یُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا یَنقُضُونَ ٱلۡمِیثَـٰقَ',
    'الذين يوفون بعهد الله ولا ينقضون الميثاق',
    'ٱلَّذِينَ يُوفُونَ بِعَهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَا يَ<rule class=ikhafa>نق</rule>ُضُونَ <rule class=ham_wasl>ٱ</rule>لۡمِيثَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ق</rule>َ ٢٠',
    20, 13, 3, 252, 207, 101, 'false'
  );
  
  -- Ayah 21 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1728,
    'وَٱلَّذِینَ یَصِلُونَ مَاۤ أَمَرَ ٱللَّهُ بِهِۦۤ أَن یُوصَلَ وَیَخۡشَوۡنَ رَبَّهُمۡ وَیَخَافُونَ سُوۤءَ ٱلۡحِسَابِ',
    'والذين يصلون ما امر الله به ان يوصل ويخشون ربهم ويخافون سوء الحساب',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَصِلُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَمَرَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُوصَلَ وَيَخۡشَوۡنَ رَبَّهُمۡ وَيَخَافُونَ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢١',
    21, 13, 3, 252, 207, 101, 'false'
  );
  
  -- Ayah 22 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1729,
    'وَٱلَّذِینَ صَبَرُوا۟ ٱبۡتِغَاۤءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقۡنَـٰهُمۡ سِرࣰّا وَعَلَانِیَةࣰ وَیَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّیِّئَةَ أُو۟لَـٰۤىِٕكَ لَهُمۡ عُقۡبَى ٱلدَّارِ',
    'والذين صبروا ابتغاء وجه ربهم واقاموا الصلاة وانفقوا مما رزقناهم سرا وعلانية ويدرءون بالحسنة السيئة اولئك لهم عقبى الدار',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ صَبَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَ<rule class=qalaqah>جۡ</rule>هِ رَبِّهِمۡ وَأَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ سِر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َعَلَانِيَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َيَ<rule class=qalaqah>دۡ</rule>رَءُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَسَنَةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةَ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عُ<rule class=qalaqah>قۡ</rule>بَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>َا</rule>رِ ٢٢',
    22, 13, 3, 252, 207, 101, 'false'
  );
  
  -- Ayah 23 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1730,
    'جَنَّـٰتُ عَدۡنࣲ یَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَاۤىِٕهِمۡ وَأَزۡوَ ٰ⁠جِهِمۡ وَذُرِّیَّـٰتِهِمۡۖ وَٱلۡمَلَـٰۤىِٕكَةُ یَدۡخُلُونَ عَلَیۡهِم مِّن كُلِّ بَابࣲ',
    'جنات عدن يدخلونها ومن صلح من ابائهم وازواجهم وذرياتهم والملائكة يدخلون عليهم من كل باب',
    'جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>خُلُونَهَا وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َلَحَ مِنۡ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ وَأَزۡو<rule class=madda_normal>ٰ</rule>جِهِمۡ وَذُرِّيَّ<rule class=madda_normal>ـٰ</rule>تِهِمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ يَ<rule class=qalaqah>دۡ</rule>خُلُونَ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ ب<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٢٣',
    23, 13, 3, 252, 207, 101, 'false'
  );
  
  -- Ayah 24 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1731,
    'سَلَـٰمٌ عَلَیۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ',
    'سلام عليكم بما صبرتم فنعم عقبى الدار',
    'سَلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا صَبَرۡتُمۡ‌ۚ فَنِعۡمَ عُ<rule class=qalaqah>قۡ</rule>بَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>َا</rule>رِ ٢٤',
    24, 13, 3, 252, 207, 101, 'false'
  );
  
  -- Ayah 25 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1732,
    'وَٱلَّذِینَ یَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِیثَـٰقِهِۦ وَیَقۡطَعُونَ مَاۤ أَمَرَ ٱللَّهُ بِهِۦۤ أَن یُوصَلَ وَیُفۡسِدُونَ فِی ٱلۡأَرۡضِ أُو۟لَـٰۤىِٕكَ لَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوۤءُ ٱلدَّارِ',
    'والذين ينقضون عهد الله من بعد ميثاقه ويقطعون ما امر الله به ان يوصل ويفسدون في الارض اولئك لهم اللعنة ولهم سوء الدار',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=ikhafa>نق</rule>ُضُونَ عَهۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مِيثَ<rule class=madda_normal>ـٰ</rule>قِه<rule class=madda_normal>ِۦ</rule> وَيَ<rule class=qalaqah>قۡ</rule>طَعُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَمَرَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُوصَلَ وَيُفۡسِدُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۙ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّعۡنَةُ وَلَهُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>َا</rule>رِ ٢٥',
    25, 13, 3, 252, 207, 101, 'false'
  );
  
  -- Ayah 26 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1733,
    'ٱللَّهُ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ وَفَرِحُوا۟ بِٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَا فِی ٱلۡـَٔاخِرَةِ إِلَّا مَتَـٰعࣱ',
    'الله يبسط الرزق لمن يشاء ويقدر وفرحوا بالحياة الدنيا وما الحياة الدنيا في الاخرة الا متاع',
    'ٱللَّهُ يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَ<rule class=qalaqah>قۡ</rule>دِرُ‌ۚ وَفَرِحُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَمَا <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ إِلَّا مَتَ<rule class=madda_permissible>ـٰ</rule>عٌ ٢٦',
    26, 13, 3, 252, 207, 101, 'false'
  );
  
  -- Ayah 27 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1734,
    'وَیَقُولُ ٱلَّذِینَ كَفَرُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَةࣱ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ یُضِلُّ مَن یَشَاۤءُ وَیَهۡدِیۤ إِلَیۡهِ مَنۡ أَنَابَ',
    'ويقول الذين كفروا لولا انزل عليه اية من ربه قل ان الله يضل من يشاء ويهدي اليه من اناب',
    'وَيَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡهِ ءَايَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule>‌ۗ قُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُضِلُّ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ مَنۡ أَن<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>َ ٢٧',
    27, 13, 3, 252, 208, 101, 'false'
  );
  
  -- Ayah 28 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1735,
    'ٱلَّذِینَ ءَامَنُوا۟ وَتَطۡمَىِٕنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَىِٕنُّ ٱلۡقُلُوبُ',
    'الذين امنوا وتطمئن قلوبهم بذكر الله الا بذكر الله تطمئن القلوب',
    'ٱلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَتَ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>ُ قُلُوبُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ أَلَا بِذِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ تَ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>ُ <rule class=ham_wasl>ٱ</rule>لۡقُل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ُ ٢٨',
    28, 13, 3, 252, 208, 101, 'false'
  );
  
  -- Ayah 29 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1736,
    'ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَـَٔابࣲ',
    'الذين امنوا وعملوا الصالحات طوبى لهم وحسن ماب',
    'ٱلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَــٔ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٢٩',
    29, 13, 3, 253, 208, 101, 'false'
  );
  
  -- Ayah 30 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1737,
    'كَذَ ٰ⁠لِكَ أَرۡسَلۡنَـٰكَ فِیۤ أُمَّةࣲ قَدۡ خَلَتۡ مِن قَبۡلِهَاۤ أُمَمࣱ لِّتَتۡلُوَا۟ عَلَیۡهِمُ ٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ وَهُمۡ یَكۡفُرُونَ بِٱلرَّحۡمَـٰنِۚ قُلۡ هُوَ رَبِّی لَاۤ إِلَـٰهَ إِلَّا هُوَ عَلَیۡهِ تَوَكَّلۡتُ وَإِلَیۡهِ مَتَابِ',
    'كذلك ارسلناك في امة قد خلت من قبلها امم لتتلو عليهم الذي اوحينا اليك وهم يكفرون بالرحمن قل هو ربي لا اله الا هو عليه توكلت واليه متاب',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_obligatory_monfasel>َآ</rule> أُمَ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتَتۡلُوَ<rule class=slnt>اۡ</rule> عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ وَهُمۡ يَكۡفُرُونَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ قُلۡ هُوَ رَبِّى ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَت<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٣٠',
    30, 13, 3, 253, 208, 101, 'false'
  );
  
  -- Ayah 31 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1738,
    'وَلَوۡ أَنَّ قُرۡءَانࣰا سُیِّرَتۡ بِهِ ٱلۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ أَوۡ كُلِّمَ بِهِ ٱلۡمَوۡتَىٰۗ بَل لِّلَّهِ ٱلۡأَمۡرُ جَمِیعًاۗ أَفَلَمۡ یَا۟یۡـَٔسِ ٱلَّذِینَ ءَامَنُوۤا۟ أَن لَّوۡ یَشَاۤءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِیعࣰاۗ وَلَا یَزَالُ ٱلَّذِینَ كَفَرُوا۟ تُصِیبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوۡ تَحُلُّ قَرِیبࣰا مِّن دَارِهِمۡ حَتَّىٰ یَأۡتِیَ وَعۡدُ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا یُخۡلِفُ ٱلۡمِیعَادَ',
    'ولو ان قرانا سيرت به الجبال او قطعت به الارض او كلم به الموتى بل لله الامر جميعا افلم يياس الذين امنوا ان لو يشاء الله لهدى الناس جميعا ولا يزال الذين كفروا تصيبهم بما صنعوا قارعة او تحل قريبا من دارهم حتى ياتي وعد الله ان الله لا يخلف الميعاد',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َ قُرۡءَا<rule class=ikhafa>نًا</rule> <rule class=ikhafa>س</rule>ُيِّرَتۡ بِهِ <rule class=ham_wasl>ٱ</rule>لۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ أَوۡ كُلِّمَ بِهِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ‌ۗ بَل لِّلَّهِ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ جَمِيعًا‌ۗ أَفَلَمۡ يَ<rule class=slnt>اۡ</rule>يۡــَٔسِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡ يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهَدَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ جَمِي<rule class=idgham_ghunnah>عًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَزَالُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> تُصِيبُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا صَنَعُو<rule class=slnt>اۡ</rule> قَارِعَةٌ أَوۡ تَحُلُّ قَرِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>َارِهِمۡ حَتَّىٰ يَأۡتِىَ وَعۡدُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُخۡلِفُ <rule class=ham_wasl>ٱ</rule>لۡمِيع<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>َ ٣١',
    31, 13, 3, 253, 208, 101, 'false'
  );
  
  -- Ayah 32 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1739,
    'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلࣲ مِّن قَبۡلِكَ فَأَمۡلَیۡتُ لِلَّذِینَ كَفَرُوا۟ ثُمَّ أَخَذۡتُهُمۡۖ فَكَیۡفَ كَانَ عِقَابِ',
    'ولقد استهزئ برسل من قبلك فامليت للذين كفروا ثم اخذتهم فكيف كان عقاب',
    'وَلَقَدِ <rule class=ham_wasl>ٱ</rule>سۡتُهۡزِئَ بِرُسُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ فَأَمۡلَيۡتُ لِلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ أَخَذۡتُهُمۡ‌ۖ فَكَيۡفَ كَانَ عِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٣٢',
    32, 13, 3, 253, 209, 101, 'false'
  );
  
  -- Ayah 33 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1740,
    'أَفَمَنۡ هُوَ قَاۤىِٕمٌ عَلَىٰ كُلِّ نَفۡسِۭ بِمَا كَسَبَتۡۗ وَجَعَلُوا۟ لِلَّهِ شُرَكَاۤءَ قُلۡ سَمُّوهُمۡۚ أَمۡ تُنَبِّـُٔونَهُۥ بِمَا لَا یَعۡلَمُ فِی ٱلۡأَرۡضِ أَم بِظَـٰهِرࣲ مِّنَ ٱلۡقَوۡلِۗ بَلۡ زُیِّنَ لِلَّذِینَ كَفَرُوا۟ مَكۡرُهُمۡ وَصُدُّوا۟ عَنِ ٱلسَّبِیلِۗ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ',
    'افمن هو قائم على كل نفس بما كسبت وجعلوا لله شركاء قل سموهم ام تنبئونه بما لا يعلم في الارض ام بظاهر من القول بل زين للذين كفروا مكرهم وصدوا عن السبيل ومن يضلل الله فما له من هاد',
    'أَفَمَنۡ هُوَ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِمٌ عَلَىٰ كُلِّ نَفۡ<rule class=iqlab>سِۭ</rule> <rule class=iqlab>ب</rule>ِمَا كَسَبَتۡ‌ۗ وَجَعَلُو<rule class=slnt>اۡ</rule> لِلَّهِ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ قُلۡ سَ<rule class=ghunnah>مّ</rule>ُوهُمۡ‌ۚ أَمۡ تُنَبِّــُٔونَهُ<rule class=madda_normal>ۥ</rule> بِمَا لَا يَعۡلَمُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أ<rule class=ikhafa_shafawi>َم</rule> <rule class=ikhafa_shafawi>ب</rule>ِظَ<rule class=madda_normal>ـٰ</rule>هِ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ‌ۗ بَلۡ زُيِّنَ لِلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مَكۡرُهُمۡ وَصُدُّو<rule class=slnt>اۡ</rule> عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَمَا لَهُ<rule class=madda_normal>ۥ</rule> مِنۡ ه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ٍ ٣٣',
    33, 13, 3, 253, 209, 101, 'false'
  );
  
  -- Ayah 34 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1741,
    'لَّهُمۡ عَذَابࣱ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَشَقُّۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقࣲ',
    'لهم عذاب في الحياة الدنيا ولعذاب الاخرة اشق وما لهم من الله من واق',
    'لَّهُمۡ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَلَعَذَابُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ أَشَقُّ‌ۖ وَمَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ٍ ٣٤',
    34, 13, 3, 253, 209, 101, 'false'
  );
  
  -- Ayah 35 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1742,
    '۞ مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِی وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ أُكُلُهَا دَاۤىِٕمࣱ وَظِلُّهَاۚ تِلۡكَ عُقۡبَى ٱلَّذِینَ ٱتَّقَوا۟ۚ وَّعُقۡبَى ٱلۡكَـٰفِرِینَ ٱلنَّارُ',
    'مثل الجنة التي وعد المتقون تجري من تحتها الانهار اكلها دائم وظلها تلك عقبى الذين اتقوا وعقبى الكافرين النار',
    '۞مَّثَلُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ <rule class=ham_wasl>ٱ</rule>لَّتِى وُعِدَ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقُونَ‌ۖ تَ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۖ أُكُلُهَا د<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َظِلُّهَا‌ۚ تِلۡكَ عُ<rule class=qalaqah>قۡ</rule>بَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَو<rule class=slnt>اۡ‌ۖ</rule> وَّعُ<rule class=qalaqah>قۡ</rule>بَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رُ ٣٥',
    35, 13, 3, 254, 209, 102, 'false'
  );
  
  -- Ayah 36 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1743,
    'وَٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَفۡرَحُونَ بِمَاۤ أُنزِلَ إِلَیۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن یُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَاۤ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَاۤ أُشۡرِكَ بِهِۦۤۚ إِلَیۡهِ أَدۡعُوا۟ وَإِلَیۡهِ مَـَٔابِ',
    'والذين اتيناهم الكتاب يفرحون بما انزل اليك ومن الاحزاب من ينكر بعضه قل انما امرت ان اعبد الله ولا اشرك به اليه ادعو واليه ماب',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يَفۡرَحُونَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ‌ۖ وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡزَابِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=ikhafa>نك</rule>ِرُ بَعۡضَهُ<rule class=madda_normal>ۥ</rule>‌ۚ قُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُمِرۡتُ أَنۡ أَعۡبُدَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أُشۡرِكَ بِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِلَيۡهِ أَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> وَإِلَيۡهِ مَـَٔـ<rule class=madda_permissible>ا</rule><rule class=qalaqah>ب</rule>ِ ٣٦',
    36, 13, 3, 254, 209, 102, 'false'
  );
  
  -- Ayah 37 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1744,
    'وَكَذَ ٰ⁠لِكَ أَنزَلۡنَـٰهُ حُكۡمًا عَرَبِیࣰّاۚ وَلَىِٕنِ ٱتَّبَعۡتَ أَهۡوَاۤءَهُم بَعۡدَ مَا جَاۤءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِیࣲّ وَلَا وَاقࣲ',
    'وكذلك انزلناه حكما عربيا ولئن اتبعت اهواءهم بعدما جاءك من العلم ما لك من الله من ولي ولا واق',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ حُكۡمًا عَرَبِي<rule class=idgham_ghunnah>ًّا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَئِنِ <rule class=ham_wasl>ٱ</rule>تَّبَعۡتَ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi data-bs-original-title= title=>ب</rule>َعۡدَ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ مَا لَكَ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا و<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ٍ ٣٧',
    37, 13, 3, 254, 209, 102, 'false'
  );
  
  -- Ayah 38 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1745,
    'وَلَقَدۡ أَرۡسَلۡنَا رُسُلࣰا مِّن قَبۡلِكَ وَجَعَلۡنَا لَهُمۡ أَزۡوَ ٰ⁠جࣰا وَذُرِّیَّةࣰۚ وَمَا كَانَ لِرَسُولٍ أَن یَأۡتِیَ بِـَٔایَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ لِكُلِّ أَجَلࣲ كِتَابࣱ',
    'ولقد ارسلنا رسلا من قبلك وجعلنا لهم ازواجا وذرية وما كان لرسول ان ياتي باية الا باذن الله لكل اجل كتاب',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا رُسُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ وَجَعَلۡنَا لَهُمۡ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َذُرِّيَّ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ لِرَسُولٍ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِىَ بِـَٔـايَةٍ إِلَّا بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ لِكُلِّ أَجَ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ك</rule>ِت<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٣٨',
    38, 13, 3, 254, 210, 102, 'false'
  );
  
  -- Ayah 39 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1746,
    'یَمۡحُوا۟ ٱللَّهُ مَا یَشَاۤءُ وَیُثۡبِتُۖ وَعِندَهُۥۤ أُمُّ ٱلۡكِتَـٰبِ',
    'يمحو الله ما يشاء ويثبت وعنده ام الكتاب',
    'يَمۡحُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيُثۡبِتُ‌ۖ وَعِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أُ<rule class=ghunnah>مّ</rule>ُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٣٩',
    39, 13, 3, 254, 210, 102, 'false'
  );
  
  -- Ayah 40 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1747,
    'وَإِن مَّا نُرِیَنَّكَ بَعۡضَ ٱلَّذِی نَعِدُهُمۡ أَوۡ نَتَوَفَّیَنَّكَ فَإِنَّمَا عَلَیۡكَ ٱلۡبَلَـٰغُ وَعَلَیۡنَا ٱلۡحِسَابُ',
    'وان ما نرينك بعض الذي نعدهم او نتوفينك فانما عليك البلاغ وعلينا الحساب',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّا نُرِيَ<rule class=ghunnah>نّ</rule>َكَ بَعۡضَ <rule class=ham_wasl>ٱ</rule>لَّذِى نَعِدُهُمۡ أَوۡ نَتَوَفَّيَ<rule class=ghunnah>نّ</rule>َكَ فَإِ<rule class=ghunnah>نّ</rule>َمَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ وَعَلَيۡنَا <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ُ ٤٠',
    40, 13, 3, 254, 210, 102, 'false'
  );
  
  -- Ayah 41 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1748,
    'أَوَلَمۡ یَرَوۡا۟ أَنَّا نَأۡتِی ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۚ وَٱللَّهُ یَحۡكُمُ لَا مُعَقِّبَ لِحُكۡمِهِۦۚ وَهُوَ سَرِیعُ ٱلۡحِسَابِ',
    'اولم يروا انا ناتي الارض ننقصها من اطرافها والله يحكم لا معقب لحكمه وهو سريع الحساب',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َا نَأۡتِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ نَ<rule class=ikhafa>نق</rule>ُصُهَا مِنۡ أَ<rule class=qalaqah>طۡ</rule>رَافِهَا‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَحۡكُمُ لَا مُعَقِّبَ لِحُكۡمِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَهُوَ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٤١',
    41, 13, 3, 254, 210, 102, 'false'
  );
  
  -- Ayah 42 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1749,
    'وَقَدۡ مَكَرَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَلِلَّهِ ٱلۡمَكۡرُ جَمِیعࣰاۖ یَعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡسࣲۗ وَسَیَعۡلَمُ ٱلۡكُفَّـٰرُ لِمَنۡ عُقۡبَى ٱلدَّارِ',
    'وقد مكر الذين من قبلهم فلله المكر جميعا يعلم ما تكسب كل نفس وسيعلم الكفار لمن عقبى الدار',
    'وَقَ<rule class=qalaqah>دۡ</rule> مَكَرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ فَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡمَكۡرُ جَمِي<rule class=idgham_ghunnah>عًا‌ۖ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َسَيَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لۡكُفَّ<rule class=madda_normal>ـٰ</rule>رُ لِمَنۡ عُ<rule class=qalaqah>قۡ</rule>بَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>َا</rule>رِ ٤٢',
    42, 13, 3, 254, 210, 102, 'false'
  );
  
  -- Ayah 43 Surah Ar-Rad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    13,
    1750,
    'وَیَقُولُ ٱلَّذِینَ كَفَرُوا۟ لَسۡتَ مُرۡسَلࣰاۚ قُلۡ كَفَىٰ بِٱللَّهِ شَهِیدَۢا بَیۡنِی وَبَیۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَـٰبِ',
    'ويقول الذين كفروا لست مرسلا قل كفى بالله شهيدا بيني وبينكم ومن عنده علم الكتاب',
    'وَيَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَسۡتَ مُرۡسَل<rule class=ikhafa>اً‌ۚ</rule> <rule class=ikhafa>ق</rule>ُلۡ كَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ شَهِيد<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنِى وَبَيۡنَكُمۡ وَمَنۡ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> عِلۡمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٤٣',
    43, 13, 3, 255, 210, 102, 'false'
  );
  

-- Surah Ibrahim
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (14, 'سُورَةُ إِبۡرَاهِيمَ', 'Ibrahim', 'Abraham', 'Meccan', 52);

  -- Ayah 1 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1751,
    'الۤرۚ كِتَـٰبٌ أَنزَلۡنَـٰهُ إِلَیۡكَ لِتُخۡرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذۡنِ رَبِّهِمۡ إِلَىٰ صِرَ ٰ⁠طِ ٱلۡعَزِیزِ ٱلۡحَمِیدِ',
    'الر كتاب انزلناه اليك لتخرج الناس من الظلمات الى النور باذن ربهم الى صراط العزيز الحميد',
    'ا<rule class=madda_necessary>لٓ</rule>ر‌ۚ كِتَ<rule class=madda_normal>ـٰ</rule>بٌ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ إِلَيۡكَ لِتُخۡرِجَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِ بِإِذۡنِ رَبِّهِمۡ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule>طِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ١',
    1, 13, 3, 255, 211, 102, 'false'
  );
  
  -- Ayah 2 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1752,
    'ٱللَّهِ ٱلَّذِی لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۗ وَوَیۡلࣱ لِّلۡكَـٰفِرِینَ مِنۡ عَذَابࣲ شَدِیدٍ',
    'الله الذي له ما في السماوات وما في الارض وويل للكافرين من عذاب شديد',
    'ٱللَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى لَهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ مِنۡ عَذَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ش</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٢',
    2, 13, 3, 255, 211, 102, 'false'
  );
  
  -- Ayah 3 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1753,
    'ٱلَّذِینَ یَسۡتَحِبُّونَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا عَلَى ٱلۡـَٔاخِرَةِ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَیَبۡغُونَهَا عِوَجًاۚ أُو۟لَـٰۤىِٕكَ فِی ضَلَـٰلِۭ بَعِیدࣲ',
    'الذين يستحبون الحياة الدنيا على الاخرة ويصدون عن سبيل الله ويبغونها عوجا اولئك في ضلال بعيد',
    'ٱلَّذِينَ يَسۡتَحِبُّونَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَيَصُدُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَ<rule class=qalaqah>بۡ</rule>غُونَهَا عِوَجًا‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>لِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٣',
    3, 13, 3, 255, 211, 102, 'false'
  );
  
  -- Ayah 4 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1754,
    'وَمَاۤ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِیُبَیِّنَ لَهُمۡۖ فَیُضِلُّ ٱللَّهُ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'وما ارسلنا من رسول الا بلسان قومه ليبين لهم فيضل الله من يشاء ويهدي من يشاء وهو العزيز الحكيم',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولٍ إِلَّا بِلِسَانِ قَوۡمِه<rule class=madda_normal>ِۦ</rule> لِيُبَيِّنَ لَهُمۡ‌ۖ فَيُضِلُّ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٤',
    4, 13, 3, 255, 211, 102, 'false'
  );
  
  -- Ayah 5 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1755,
    'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔایَـٰتِنَاۤ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَیَّىٰمِ ٱللَّهِۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ',
    'ولقد ارسلنا موسى باياتنا ان اخرج قومك من الظلمات الى النور وذكرهم بايام الله ان في ذلك لايات لكل صبار شكور',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا مُوسَىٰ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡ أَخۡرِ<rule class=qalaqah>جۡ</rule> قَوۡمَكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِ وَذَكِّرۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَيَّ<rule class=madda_normal>ـٰ</rule>مِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ صَبَّا<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ش</rule>َك<rule class=madda_permissible>ُو</rule>رٍ ٥',
    5, 13, 3, 255, 211, 102, 'false'
  );
  
  -- Ayah 6 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1756,
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ یَسُومُونَكُمۡ سُوۤءَ ٱلۡعَذَابِ وَیُذَبِّحُونَ أَبۡنَاۤءَكُمۡ وَیَسۡتَحۡیُونَ نِسَاۤءَكُمۡۚ وَفِی ذَ ٰ⁠لِكُم بَلَاۤءࣱ مِّن رَّبِّكُمۡ عَظِیمࣱ',
    'واذ قال موسى لقومه اذكروا نعمة الله عليكم اذ انجاكم من ال فرعون يسومونكم سوء العذاب ويذبحون ابناءكم ويستحيون نساءكم وفي ذلكم بلاء من ربكم عظيم',
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ إِذۡ أَ<rule class=ikhafa>نج</rule>َ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ ءَالِ فِرۡعَوۡنَ يَسُومُونَكُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ وَيُذَبِّحُونَ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ وَيَسۡتَحۡيُونَ نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ‌ۚ وَفِى ذ<rule class=madda_normal>ٰ</rule>لِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َل<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٦',
    6, 13, 3, 256, 211, 102, 'false'
  );
  
  -- Ayah 7 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1757,
    'وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَىِٕن شَكَرۡتُمۡ لَأَزِیدَنَّكُمۡۖ وَلَىِٕن كَفَرۡتُمۡ إِنَّ عَذَابِی لَشَدِیدࣱ',
    'واذ تاذن ربكم لئن شكرتم لازيدنكم ولئن كفرتم ان عذابي لشديد',
    'وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َكَرۡتُمۡ لَأَزِيدَ<rule class=ghunnah>نّ</rule>َكُمۡ‌ۖ وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرۡتُمۡ إِ<rule class=ghunnah>نّ</rule>َ عَذَابِى لَشَد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٧',
    7, 13, 3, 256, 212, 102, 'false'
  );
  
  -- Ayah 8 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1758,
    'وَقَالَ مُوسَىٰۤ إِن تَكۡفُرُوۤا۟ أَنتُمۡ وَمَن فِی ٱلۡأَرۡضِ جَمِیعࣰا فَإِنَّ ٱللَّهَ لَغَنِیٌّ حَمِیدٌ',
    'وقال موسى ان تكفروا انتم ومن في الارض جميعا فان الله لغني حميد',
    'وَقَالَ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكۡفُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَغَنِىٌّ حَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٨',
    8, 13, 3, 256, 212, 102, 'false'
  );
  
  -- Ayah 9 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1759,
    'أَلَمۡ یَأۡتِكُمۡ نَبَؤُا۟ ٱلَّذِینَ مِن قَبۡلِكُمۡ قَوۡمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَٱلَّذِینَ مِنۢ بَعۡدِهِمۡ لَا یَعۡلَمُهُمۡ إِلَّا ٱللَّهُۚ جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَرَدُّوۤا۟ أَیۡدِیَهُمۡ فِیۤ أَفۡوَ ٰ⁠هِهِمۡ وَقَالُوۤا۟ إِنَّا كَفَرۡنَا بِمَاۤ أُرۡسِلۡتُم بِهِۦ وَإِنَّا لَفِی شَكࣲّ مِّمَّا تَدۡعُونَنَاۤ إِلَیۡهِ مُرِیبࣲ',
    'الم ياتكم نبا الذين من قبلكم قوم نوح وعاد وثمود والذين من بعدهم لا يعلمهم الا الله جاءتهم رسلهم بالبينات فردوا ايديهم في افواههم وقالوا انا كفرنا بما ارسلتم به وانا لفي شك مما تدعوننا اليه مريب',
    'أَلَمۡ يَأۡتِكُمۡ نَبَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ قَوۡمِ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَا<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َثَمُودَ‌ۛ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ‌ۛ لَا يَعۡلَمُهُمۡ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَرَدّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡدِيَهُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا كَفَرۡنَا بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> وَإِ<rule class=ghunnah>نّ</rule>َا لَفِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَ<rule class=qalaqah>دۡ</rule>عُونَن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ مُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٩',
    9, 13, 3, 256, 212, 102, 'false'
  );
  
  -- Ayah 10 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1760,
    '۞ قَالَتۡ رُسُلُهُمۡ أَفِی ٱللَّهِ شَكࣱّ فَاطِرِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ یَدۡعُوكُمۡ لِیَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ وَیُؤَخِّرَكُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّىۚ قَالُوۤا۟ إِنۡ أَنتُمۡ إِلَّا بَشَرࣱ مِّثۡلُنَا تُرِیدُونَ أَن تَصُدُّونَا عَمَّا كَانَ یَعۡبُدُ ءَابَاۤؤُنَا فَأۡتُونَا بِسُلۡطَـٰنࣲ مُّبِینࣲ',
    'قالت رسلهم افي الله شك فاطر السماوات والارض يدعوكم ليغفر لكم من ذنوبكم ويؤخركم الى اجل مسمى قالوا ان انتم الا بشر مثلنا تريدون ان تصدونا عما كان يعبد اباؤنا فاتونا بسلطان مبين',
    '۞قَالَتۡ رُسُلُهُمۡ أَفِى <rule class=ham_wasl>ٱ</rule>للَّهِ شَ<rule class=ikhafa>كٌّ</rule> <rule class=ikhafa>ف</rule>َاطِرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ يَ<rule class=qalaqah>دۡ</rule>عُوكُمۡ لِيَغۡفِرَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُنُوبِكُمۡ وَيُؤَخِّرَكُمۡ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=ikhafa>ًّى‌ۚ</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ أَ<rule class=ikhafa>نت</rule>ُمۡ إِلَّا بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُنَا تُرِيدُونَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َصُدُّونَا عَ<rule class=ghunnah>مّ</rule>َا كَانَ يَعۡبُدُ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا فَأۡتُونَا بِسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١٠',
    10, 13, 3, 256, 212, 103, 'false'
  );
  
  -- Ayah 11 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1761,
    'قَالَتۡ لَهُمۡ رُسُلُهُمۡ إِن نَّحۡنُ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ وَلَـٰكِنَّ ٱللَّهَ یَمُنُّ عَلَىٰ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۖ وَمَا كَانَ لَنَاۤ أَن نَّأۡتِیَكُم بِسُلۡطَـٰنٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ',
    'قالت لهم رسلهم ان نحن الا بشر مثلكم ولكن الله يمن على من يشاء من عباده وما كان لنا ان ناتيكم بسلطان الا باذن الله وعلى الله فليتوكل المؤمنون',
    'قَالَتۡ لَهُمۡ رُسُلُهُمۡ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّحۡنُ إِلَّا بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُكُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَمُ<rule class=ghunnah>نّ</rule>ُ عَلَىٰ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَا كَانَ لَن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّأۡتِيَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسُلۡطَ<rule class=madda_normal>ـٰ</rule>نٍ إِلَّا بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 13, 3, 257, 212, 103, 'false'
  );
  
  -- Ayah 12 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1762,
    'وَمَا لَنَاۤ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَاۤ ءَاذَیۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ',
    'وما لنا الا نتوكل على الله وقد هدانا سبلنا ولنصبرن على ما اذيتمونا وعلى الله فليتوكل المتوكلون',
    'وَمَا لَن<rule class=madda_obligatory_monfasel>َآ</rule> أَلَّا نَتَوَكَّلَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَقَ<rule class=qalaqah>دۡ</rule> هَدَ<rule class=madda_normal>ٮٰ</rule>نَا سُبُلَنَا‌ۚ وَلَنَصۡبِرَ<rule class=ghunnah>نّ</rule>َ عَلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاذَيۡتُمُونَا‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُتَوَكِّل<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 13, 3, 257, 212, 103, 'false'
  );
  
  -- Ayah 13 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1763,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ أَرۡضِنَاۤ أَوۡ لَتَعُودُنَّ فِی مِلَّتِنَاۖ فَأَوۡحَىٰۤ إِلَیۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ ٱلظَّـٰلِمِینَ',
    'وقال الذين كفروا لرسلهم لنخرجنكم من ارضنا او لتعودن في ملتنا فاوحى اليهم ربهم لنهلكن الظالمين',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لِرُسُلِهِمۡ لَنُخۡرِجَ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَرۡضِن<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ لَتَعُودُ<rule class=ghunnah>نّ</rule>َ فِى مِلَّتِنَا‌ۖ فَأَوۡحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 13, 3, 257, 213, 103, 'false'
  );
  
  -- Ayah 14 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1764,
    'وَلَنُسۡكِنَنَّكُمُ ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡۚ ذَ ٰ⁠لِكَ لِمَنۡ خَافَ مَقَامِی وَخَافَ وَعِیدِ',
    'ولنسكننكم الارض من بعدهم ذلك لمن خاف مقامي وخاف وعيد',
    'وَلَنُسۡكِنَ<rule class=ghunnah>نّ</rule>َكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ لِمَنۡ خَافَ مَقَامِى وَخَافَ وَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ١٤',
    14, 13, 3, 257, 213, 103, 'false'
  );
  
  -- Ayah 15 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1765,
    'وَٱسۡتَفۡتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِیدࣲ',
    'واستفتحوا وخاب كل جبار عنيد',
    'وَ<rule class=ham_wasl>ٱ</rule>سۡتَفۡتَحُو<rule class=slnt>اۡ</rule> وَخَابَ كُلُّ جَبَّارٍ عَن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ١٥',
    15, 13, 3, 257, 213, 103, 'false'
  );
  
  -- Ayah 16 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1766,
    'مِّن وَرَاۤىِٕهِۦ جَهَنَّمُ وَیُسۡقَىٰ مِن مَّاۤءࣲ صَدِیدࣲ',
    'من ورائه جهنم ويسقى من ماء صديد',
    'مّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِه<rule class=madda_normal>ِۦ</rule> جَهَ<rule class=ghunnah>نّ</rule>َمُ وَيُسۡقَىٰ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ص</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ١٦',
    16, 13, 3, 257, 213, 103, 'false'
  );
  
  -- Ayah 17 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1767,
    'یَتَجَرَّعُهُۥ وَلَا یَكَادُ یُسِیغُهُۥ وَیَأۡتِیهِ ٱلۡمَوۡتُ مِن كُلِّ مَكَانࣲ وَمَا هُوَ بِمَیِّتࣲۖ وَمِن وَرَاۤىِٕهِۦ عَذَابٌ غَلِیظࣱ',
    'يتجرعه ولا يكاد يسيغه وياتيه الموت من كل مكان وما هو بميت ومن ورائه عذاب غليظ',
    'يَتَجَرَّعُهُ<rule class=madda_normal>ۥ</rule> وَلَا يَكَادُ يُسِيغُهُ<rule class=madda_normal>ۥ</rule> وَيَأۡتِيهِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مَكَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا هُوَ بِمَيِّ<rule class=idgham_ghunnah>تٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِه<rule class=madda_normal>ِۦ</rule> عَذَابٌ غَل<rule class=madda_permissible>ِي</rule>ظٌ ١٧',
    17, 13, 3, 257, 213, 103, 'false'
  );
  
  -- Ayah 18 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1768,
    'مَّثَلُ ٱلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡۖ أَعۡمَـٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّیحُ فِی یَوۡمٍ عَاصِفࣲۖ لَّا یَقۡدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَیۡءࣲۚ ذَ ٰ⁠لِكَ هُوَ ٱلضَّلَـٰلُ ٱلۡبَعِیدُ',
    'مثل الذين كفروا بربهم اعمالهم كرماد اشتدت به الريح في يوم عاصف لا يقدرون مما كسبوا على شيء ذلك هو الضلال البعيد',
    'مَّثَلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِرَبِّهِمۡ‌ۖ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ كَرَمَادٍ <rule class=ham_wasl>ٱ</rule>شۡتَدَّتۡ بِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيحُ فِى يَوۡمٍ عَاصِ<rule class=idgham_wo_ghunnah>فٍ‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَ<rule class=qalaqah>قۡ</rule>دِرُونَ مِ<rule class=ghunnah>مّ</rule>َا كَسَبُو<rule class=slnt>اۡ</rule> عَلَىٰ ش<rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لُ <rule class=ham_wasl>ٱ</rule>لۡبَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ١٨',
    18, 13, 3, 257, 213, 103, 'false'
  );
  
  -- Ayah 19 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1769,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِن یَشَأۡ یُذۡهِبۡكُمۡ وَیَأۡتِ بِخَلۡقࣲ جَدِیدࣲ',
    'الم تر ان الله خلق السماوات والارض بالحق ان يشا يذهبكم ويات بخلق جديد',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َشَأۡ يُذۡهِ<rule class=qalaqah>بۡ</rule>كُمۡ وَيَأۡتِ بِخَلۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ج</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ١٩',
    19, 13, 3, 258, 213, 103, 'false'
  );
  
  -- Ayah 20 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1770,
    'وَمَا ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ بِعَزِیزࣲ',
    'وما ذلك على الله بعزيز',
    'وَمَا ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ بِعَز<rule class=madda_permissible>ِي</rule>زٍ ٢٠',
    20, 13, 3, 258, 213, 103, 'false'
  );
  
  -- Ayah 21 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1771,
    'وَبَرَزُوا۟ لِلَّهِ جَمِیعࣰا فَقَالَ ٱلضُّعَفَـٰۤؤُا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوۤا۟ إِنَّا كُنَّا لَكُمۡ تَبَعࣰا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا مِنۡ عَذَابِ ٱللَّهِ مِن شَیۡءࣲۚ قَالُوا۟ لَوۡ هَدَىٰنَا ٱللَّهُ لَهَدَیۡنَـٰكُمۡۖ سَوَاۤءٌ عَلَیۡنَاۤ أَجَزِعۡنَاۤ أَمۡ صَبَرۡنَا مَا لَنَا مِن مَّحِیصࣲ',
    'وبرزوا لله جميعا فقال الضعفاء للذين استكبروا انا كنا لكم تبعا فهل انتم مغنون عنا من عذاب الله من شيء قالوا لو هدانا الله لهديناكم سواء علينا اجزعنا ام صبرنا ما لنا من محيص',
    'وَبَرَزُو<rule class=slnt>اۡ</rule> لِلَّهِ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َقَالَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّعَفَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا لَكُمۡ تَبَ<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َهَلۡ أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّغۡنُونَ عَ<rule class=ghunnah>نّ</rule>َا مِنۡ عَذَابِ <rule class=ham_wasl>ٱ</rule>للَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> لَوۡ هَدَ<rule class=madda_normal>ٮٰ</rule>نَا <rule class=ham_wasl>ٱ</rule>للَّهُ لَهَدَيۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ عَلَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَجَزِعۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡ صَبَرۡنَا مَا لَنَا م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّح<rule class=madda_permissible>ِي</rule>صٍ ٢١',
    21, 13, 3, 258, 213, 103, 'false'
  );
  
  -- Ayah 22 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1772,
    'وَقَالَ ٱلشَّیۡطَـٰنُ لَمَّا قُضِیَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ فَأَخۡلَفۡتُكُمۡۖ وَمَا كَانَ لِیَ عَلَیۡكُم مِّن سُلۡطَـٰنٍ إِلَّاۤ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِیۖ فَلَا تَلُومُونِی وَلُومُوۤا۟ أَنفُسَكُمۖ مَّاۤ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَاۤ أَنتُم بِمُصۡرِخِیَّ إِنِّی كَفَرۡتُ بِمَاۤ أَشۡرَكۡتُمُونِ مِن قَبۡلُۗ إِنَّ ٱلظَّـٰلِمِینَ لَهُمۡ عَذَابٌ أَلِیمࣱ',
    'وقال الشيطان لما قضي الامر ان الله وعدكم وعد الحق ووعدتكم فاخلفتكم وما كان لي عليكم من سلطان الا ان دعوتكم فاستجبتم لي فلا تلوموني ولوموا انفسكم ما انا بمصرخكم وما انتم بمصرخي اني كفرت بما اشركتمون من قبل ان الظالمين لهم عذاب اليم',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ لَ<rule class=ghunnah>مّ</rule>َا قُضِىَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ وَعَدَكُمۡ وَعۡدَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَوَعَ<rule class=idgham_mutajanisayn>د</rule>تُّكُمۡ فَأَخۡلَفۡتُكُمۡ‌ۖ وَمَا كَانَ لِىَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلۡطَ<rule class=madda_normal>ـٰ</rule>نٍ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>َعَوۡتُكُمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَجَ<rule class=qalaqah>بۡ</rule>تُمۡ لِى‌ۖ فَلَا تَلُومُونِى وَلُوم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَك<rule class=idgham_shafawi>ُم‌ۖ</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ بِمُصۡرِخِكُمۡ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُصۡرِخِىَّ‌ۖ إِ<rule class=ghunnah>نّ</rule>ِى كَفَرۡتُ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡرَكۡتُمُونِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ لَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٢٢',
    22, 13, 3, 258, 214, 103, 'false'
  );
  
  -- Ayah 23 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1773,
    'وَأُدۡخِلَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا بِإِذۡنِ رَبِّهِمۡۖ تَحِیَّتُهُمۡ فِیهَا سَلَـٰمٌ',
    'وادخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار خالدين فيها باذن ربهم تحيتهم فيها سلام',
    'وَأُ<rule class=qalaqah>دۡ</rule>خِلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا بِإِذۡنِ رَبِّهِمۡ‌ۖ تَحِيَّتُهُمۡ فِيهَا سَلَ<rule class=madda_permissible>ـٰ</rule>مٌ ٢٣',
    23, 13, 3, 258, 214, 103, 'false'
  );
  
  -- Ayah 24 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1774,
    'أَلَمۡ تَرَ كَیۡفَ ضَرَبَ ٱللَّهُ مَثَلࣰا كَلِمَةࣰ طَیِّبَةࣰ كَشَجَرَةࣲ طَیِّبَةٍ أَصۡلُهَا ثَابِتࣱ وَفَرۡعُهَا فِی ٱلسَّمَاۤءِ',
    'الم تر كيف ضرب الله مثلا كلمة طيبة كشجرة طيبة اصلها ثابت وفرعها في السماء',
    'أَلَمۡ تَرَ كَيۡفَ ضَرَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَثَل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ك</rule>َلِمَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ك</rule>َشَجَرَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ط</rule>َيِّبَةٍ أَصۡلُهَا ثَابِ<rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>و</rule>َفَرۡعُهَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ٢٤',
    24, 13, 3, 258, 214, 103, 'false'
  );
  
  -- Ayah 25 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1775,
    'تُؤۡتِیۤ أُكُلَهَا كُلَّ حِینِۭ بِإِذۡنِ رَبِّهَاۗ وَیَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ یَتَذَكَّرُونَ',
    'تؤتي اكلها كل حين باذن ربها ويضرب الله الامثال للناس لعلهم يتذكرون',
    'تُؤۡت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُكُلَهَا كُلَّ حِي<rule class=iqlab>نِۭ</rule> <rule class=iqlab>ب</rule>ِإِذۡنِ رَبِّهَا‌ۗ وَيَضۡرِبُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡثَالَ لِل<rule class=ghunnah>نّ</rule>َاسِ لَعَلَّهُمۡ يَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 13, 3, 259, 214, 103, 'false'
  );
  
  -- Ayah 26 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1776,
    'وَمَثَلُ كَلِمَةٍ خَبِیثَةࣲ كَشَجَرَةٍ خَبِیثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن قَرَارࣲ',
    'ومثل كلمة خبيثة كشجرة خبيثة اجتثت من فوق الارض ما لها من قرار',
    'وَمَثَلُ كَلِمَةٍ خَبِيثَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ك</rule>َشَجَرَةٍ خَبِيثَةٍ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تُثَّتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مَا لَهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َر<rule class=madda_permissible>َا</rule>رٍ ٢٦',
    26, 13, 3, 259, 214, 103, 'false'
  );
  
  -- Ayah 27 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1777,
    'یُثَبِّتُ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَفِی ٱلۡـَٔاخِرَةِۖ وَیُضِلُّ ٱللَّهُ ٱلظَّـٰلِمِینَۚ وَیَفۡعَلُ ٱللَّهُ مَا یَشَاۤءُ',
    'يثبت الله الذين امنوا بالقول الثابت في الحياة الدنيا وفي الاخرة ويضل الله الظالمين ويفعل الله ما يشاء',
    'يُثَبِّتُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّابِتِ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَفِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ وَيُضِلُّ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ‌ۚ وَيَفۡعَلُ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ ٢٧',
    27, 13, 3, 259, 214, 103, 'false'
  );
  
  -- Ayah 28 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1778,
    '۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ بَدَّلُوا۟ نِعۡمَتَ ٱللَّهِ كُفۡرࣰا وَأَحَلُّوا۟ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ',
    'الم تر الى الذين بدلوا نعمت الله كفرا واحلوا قومهم دار البوار',
    '۞أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ بَدَّلُو<rule class=slnt>اۡ</rule> نِعۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ كُفۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َأَحَلُّو<rule class=slnt>اۡ</rule> قَوۡمَهُمۡ دَارَ <rule class=ham_wasl>ٱ</rule>لۡبَو<rule class=madda_permissible>َا</rule>رِ ٢٨',
    28, 13, 3, 259, 215, 104, 'false'
  );
  
  -- Ayah 29 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1779,
    'جَهَنَّمَ یَصۡلَوۡنَهَاۖ وَبِئۡسَ ٱلۡقَرَارُ',
    'جهنم يصلونها وبئس القرار',
    'جَهَ<rule class=ghunnah>نّ</rule>َمَ يَصۡلَوۡنَهَا‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡقَر<rule class=madda_permissible>َا</rule>رُ ٢٩',
    29, 13, 3, 259, 215, 104, 'false'
  );
  
  -- Ayah 30 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1780,
    'وَجَعَلُوا۟ لِلَّهِ أَندَادࣰا لِّیُضِلُّوا۟ عَن سَبِیلِهِۦۗ قُلۡ تَمَتَّعُوا۟ فَإِنَّ مَصِیرَكُمۡ إِلَى ٱلنَّارِ',
    'وجعلوا لله اندادا ليضلوا عن سبيله قل تمتعوا فان مصيركم الى النار',
    'وَجَعَلُو<rule class=slnt>اۡ</rule> لِلَّهِ أَ<rule class=ikhafa>ند</rule>َا<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُضِلُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِه<rule class=madda_normal>ِۦ</rule>‌ۗ قُلۡ تَمَتَّعُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ مَصِيرَكُمۡ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٣٠',
    30, 13, 3, 259, 215, 104, 'false'
  );
  
  -- Ayah 31 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1781,
    'قُل لِّعِبَادِیَ ٱلَّذِینَ ءَامَنُوا۟ یُقِیمُوا۟ ٱلصَّلَوٰةَ وَیُنفِقُوا۟ مِمَّا رَزَقۡنَـٰهُمۡ سِرࣰّا وَعَلَانِیَةࣰ مِّن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا بَیۡعࣱ فِیهِ وَلَا خِلَـٰلٌ',
    'قل لعبادي الذين امنوا يقيموا الصلاة وينفقوا مما رزقناهم سرا وعلانية من قبل ان ياتي يوم لا بيع فيه ولا خلال',
    'قُل لِّعِبَادِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> يُقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَيُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ سِر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َعَلَانِيَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِىَ يَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا بَيۡ<rule class=ikhafa>عٌ</rule> <rule class=ikhafa>ف</rule>ِيهِ وَلَا خِلَ<rule class=madda_permissible>ـٰ</rule>لٌ ٣١',
    31, 13, 3, 259, 215, 104, 'false'
  );
  
  -- Ayah 32 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1782,
    'ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَأَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَ ٰ⁠تِ رِزۡقࣰا لَّكُمۡۖ وَسَخَّرَ لَكُمُ ٱلۡفُلۡكَ لِتَجۡرِیَ فِی ٱلۡبَحۡرِ بِأَمۡرِهِۦۖ وَسَخَّرَ لَكُمُ ٱلۡأَنۡهَـٰرَ',
    'الله الذي خلق السماوات والارض وانزل من السماء ماء فاخرج به من الثمرات رزقا لكم وسخر لكم الفلك لتجري في البحر بامره وسخر لكم الانهار',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَأَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَخۡرَجَ بِه<rule class=madda_normal>ِۦ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ رِزۡ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۖ وَسَخَّرَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ لِتَ<rule class=qalaqah>جۡ</rule>رِىَ فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ بِأَمۡرِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَسَخَّرَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_permissible>ـٰ</rule>رَ ٣٢',
    32, 13, 3, 259, 215, 104, 'false'
  );
  
  -- Ayah 33 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1783,
    'وَسَخَّرَ لَكُمُ ٱلشَّمۡسَ وَٱلۡقَمَرَ دَاۤىِٕبَیۡنِۖ وَسَخَّرَ لَكُمُ ٱلَّیۡلَ وَٱلنَّهَارَ',
    'وسخر لكم الشمس والقمر دائبين وسخر لكم الليل والنهار',
    'وَسَخَّرَ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ د<rule class=madda_obligatory_mottasel>َا</rule>ٓئِبَيۡنِ‌ۖ وَسَخَّرَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َه<rule class=madda_permissible>َا</rule>رَ ٣٣',
    33, 13, 3, 259, 215, 104, 'false'
  );
  
  -- Ayah 34 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1784,
    'وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّوا۟ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَاۤۗ إِنَّ ٱلۡإِنسَـٰنَ لَظَلُومࣱ كَفَّارࣱ',
    'واتاكم من كل ما سالتموه وان تعدوا نعمت الله لا تحصوها ان الانسان لظلوم كفار',
    'وَءَاتَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مَا سَأَلۡتُمُوهُ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعُدُّو<rule class=slnt>اۡ</rule> نِعۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا تُحۡصُوه<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ لَظَلُو<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ك</rule>َفّ<rule class=madda_permissible>َا</rule>رٌ ٣٤',
    34, 13, 3, 260, 215, 104, 'false'
  );
  
  -- Ayah 35 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1785,
    'وَإِذۡ قَالَ إِبۡرَ ٰ⁠هِیمُ رَبِّ ٱجۡعَلۡ هَـٰذَا ٱلۡبَلَدَ ءَامِنࣰا وَٱجۡنُبۡنِی وَبَنِیَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ',
    'واذ قال ابراهيم رب اجعل هذا البلد امنا واجنبني وبني ان نعبد الاصنام',
    'وَإِذۡ قَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمُ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡبَلَدَ ءَامِ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>نُ<rule class=qalaqah>بۡ</rule>نِى وَبَنِىَّ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّعۡبُدَ <rule class=ham_wasl>ٱ</rule>لۡأَصۡن<rule class=madda_permissible>َا</rule>مَ ٣٥',
    35, 13, 3, 260, 216, 104, 'false'
  );
  
  -- Ayah 36 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1786,
    'رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِیرࣰا مِّنَ ٱلنَّاسِۖ فَمَن تَبِعَنِی فَإِنَّهُۥ مِنِّیۖ وَمَنۡ عَصَانِی فَإِنَّكَ غَفُورࣱ رَّحِیمࣱ',
    'رب انهن اضللن كثيرا من الناس فمن تبعني فانه مني ومن عصاني فانك غفور رحيم',
    'رَبِّ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=ghunnah>نّ</rule>َ أَضۡلَلۡنَ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۖ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبِعَنِى فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ghunnah>نّ</rule>ِى‌ۖ وَمَنۡ عَصَانِى فَإِ<rule class=ghunnah>نّ</rule>َكَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٣٦',
    36, 13, 3, 260, 216, 104, 'false'
  );
  
  -- Ayah 37 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1787,
    'رَّبَّنَاۤ إِنِّیۤ أَسۡكَنتُ مِن ذُرِّیَّتِی بِوَادٍ غَیۡرِ ذِی زَرۡعٍ عِندَ بَیۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِیُقِیمُوا۟ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةࣰ مِّنَ ٱلنَّاسِ تَهۡوِیۤ إِلَیۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَ ٰ⁠تِ لَعَلَّهُمۡ یَشۡكُرُونَ',
    'ربنا اني اسكنت من ذريتي بواد غير ذي زرع عند بيتك المحرم ربنا ليقيموا الصلاة فاجعل افئدة من الناس تهوي اليهم وارزقهم من الثمرات لعلهم يشكرون',
    'رَّبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَسۡكَ<rule class=ikhafa>نت</rule>ُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُرِّيَّتِى بِوَادٍ غَيۡرِ ذِى زَرۡعٍ عِ<rule class=ikhafa>ند</rule>َ بَيۡتِكَ <rule class=ham_wasl>ٱ</rule>لۡمُحَرَّمِ رَبَّنَا لِيُقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡ أَفۡــِٔدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ تَهۡو<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِمۡ وَ<rule class=ham_wasl>ٱ</rule>رۡزُ<rule class=qalaqah>قۡ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ لَعَلَّهُمۡ يَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 13, 3, 260, 216, 104, 'false'
  );
  
  -- Ayah 38 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1788,
    'رَبَّنَاۤ إِنَّكَ تَعۡلَمُ مَا نُخۡفِی وَمَا نُعۡلِنُۗ وَمَا یَخۡفَىٰ عَلَى ٱللَّهِ مِن شَیۡءࣲ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِ',
    'ربنا انك تعلم ما نخفي وما نعلن وما يخفى على الله من شيء في الارض ولا في السماء',
    'رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ تَعۡلَمُ مَا نُخۡفِى وَمَا نُعۡلِنُ‌ۗ وَمَا يَخۡفَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ٣٨',
    38, 13, 3, 260, 216, 104, 'false'
  );
  
  -- Ayah 39 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1789,
    'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی وَهَبَ لِی عَلَى ٱلۡكِبَرِ إِسۡمَـٰعِیلَ وَإِسۡحَـٰقَۚ إِنَّ رَبِّی لَسَمِیعُ ٱلدُّعَاۤءِ',
    'الحمد لله الذي وهب لي على الكبر اسماعيل واسحاق ان ربي لسميع الدعاء',
    'ٱلۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى وَهَبَ لِى عَلَى <rule class=ham_wasl>ٱ</rule>لۡكِبَرِ إِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى لَسَمِيعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّع<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ٣٩',
    39, 13, 3, 260, 216, 104, 'false'
  );
  
  -- Ayah 40 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1790,
    'رَبِّ ٱجۡعَلۡنِی مُقِیمَ ٱلصَّلَوٰةِ وَمِن ذُرِّیَّتِیۚ رَبَّنَا وَتَقَبَّلۡ دُعَاۤءِ',
    'رب اجعلني مقيم الصلاة ومن ذريتي ربنا وتقبل دعاء',
    'رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡنِى مُقِيمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُرِّيَّتِى‌ۚ رَبَّنَا وَتَقَبَّلۡ دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ٤٠',
    40, 13, 3, 260, 216, 104, 'false'
  );
  
  -- Ayah 41 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1791,
    'رَبَّنَا ٱغۡفِرۡ لِی وَلِوَ ٰ⁠لِدَیَّ وَلِلۡمُؤۡمِنِینَ یَوۡمَ یَقُومُ ٱلۡحِسَابُ',
    'ربنا اغفر لي ولوالدي وللمؤمنين يوم يقوم الحساب',
    'رَبَّنَا <rule class=ham_wasl>ٱ</rule>غۡفِرۡ لِى وَلِو<rule class=madda_normal>ٰ</rule>لِدَىَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ُ ٤١',
    41, 13, 3, 260, 216, 104, 'false'
  );
  
  -- Ayah 42 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1792,
    'وَلَا تَحۡسَبَنَّ ٱللَّهَ غَـٰفِلًا عَمَّا یَعۡمَلُ ٱلظَّـٰلِمُونَۚ إِنَّمَا یُؤَخِّرُهُمۡ لِیَوۡمࣲ تَشۡخَصُ فِیهِ ٱلۡأَبۡصَـٰرُ',
    'ولا تحسبن الله غافلا عما يعمل الظالمون انما يؤخرهم ليوم تشخص فيه الابصار',
    'وَلَا تَحۡسَبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَ<rule class=madda_normal>ـٰ</rule>فِلاً عَ<rule class=ghunnah>مّ</rule>َا يَعۡمَلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َمَا يُؤَخِّرُهُمۡ لِيَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ت</rule>َشۡخَصُ فِيهِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_permissible>ـٰ</rule>رُ ٤٢',
    42, 13, 3, 260, 217, 104, 'false'
  );
  
  -- Ayah 43 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1793,
    'مُهۡطِعِینَ مُقۡنِعِی رُءُوسِهِمۡ لَا یَرۡتَدُّ إِلَیۡهِمۡ طَرۡفُهُمۡۖ وَأَفۡـِٔدَتُهُمۡ هَوَاۤءࣱ',
    'مهطعين مقنعي رءوسهم لا يرتد اليهم طرفهم وافئدتهم هواء',
    'مُهۡطِعِينَ مُ<rule class=qalaqah>قۡ</rule>نِعِى رُءُوسِهِمۡ لَا يَرۡتَدُّ إِلَيۡهِمۡ طَرۡفُهُمۡ‌ۖ وَأَفۡــِٔدَتُهُمۡ هَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ ٤٣',
    43, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 44 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1794,
    'وَأَنذِرِ ٱلنَّاسَ یَوۡمَ یَأۡتِیهِمُ ٱلۡعَذَابُ فَیَقُولُ ٱلَّذِینَ ظَلَمُوا۟ رَبَّنَاۤ أَخِّرۡنَاۤ إِلَىٰۤ أَجَلࣲ قَرِیبࣲ نُّجِبۡ دَعۡوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَۗ أَوَلَمۡ تَكُونُوۤا۟ أَقۡسَمۡتُم مِّن قَبۡلُ مَا لَكُم مِّن زَوَالࣲ',
    'وانذر الناس يوم ياتيهم العذاب فيقول الذين ظلموا ربنا اخرنا الى اجل قريب نجب دعوتك ونتبع الرسل اولم تكونوا اقسمتم من قبل ما لكم من زوال',
    'وَأَ<rule class=ikhafa>نذ</rule>ِرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ يَوۡمَ يَأۡتِيهِمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ فَيَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَخِّرۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ق</rule>َرِي<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>ن</rule>ُّجِ<rule class=qalaqah>بۡ</rule> دَعۡوَتَكَ وَنَتَّبِعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلَ‌ۗ أَوَلَمۡ تَكُون<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>قۡ</rule>سَمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>َو<rule class=madda_permissible>َا</rule>لٍ ٤٤',
    44, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 45 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1795,
    'وَسَكَنتُمۡ فِی مَسَـٰكِنِ ٱلَّذِینَ ظَلَمُوۤا۟ أَنفُسَهُمۡ وَتَبَیَّنَ لَكُمۡ كَیۡفَ فَعَلۡنَا بِهِمۡ وَضَرَبۡنَا لَكُمُ ٱلۡأَمۡثَالَ',
    'وسكنتم في مساكن الذين ظلموا انفسهم وتبين لكم كيف فعلنا بهم وضربنا لكم الامثال',
    'وَسَكَ<rule class=ikhafa>نت</rule>ُمۡ فِى مَسَ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَتَبَيَّنَ لَكُمۡ كَيۡفَ فَعَلۡنَا بِهِمۡ وَضَرَ<rule class=qalaqah>بۡ</rule>نَا لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡث<rule class=madda_permissible>َا</rule>لَ ٤٥',
    45, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 46 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1796,
    'وَقَدۡ مَكَرُوا۟ مَكۡرَهُمۡ وَعِندَ ٱللَّهِ مَكۡرُهُمۡ وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ',
    'وقد مكروا مكرهم وعند الله مكرهم وان كان مكرهم لتزول منه الجبال',
    'وَقَ<rule class=qalaqah>دۡ</rule> مَكَرُو<rule class=slnt>اۡ</rule> مَكۡرَهُمۡ وَعِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ مَكۡرُهُمۡ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ <rule class=ham_wasl>ٱ</rule>لۡجِب<rule class=madda_permissible>َا</rule>لُ ٤٦',
    46, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 47 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1797,
    'فَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥۤۚ إِنَّ ٱللَّهَ عَزِیزࣱ ذُو ٱنتِقَامࣲ',
    'فلا تحسبن الله مخلف وعده رسله ان الله عزيز ذو انتقام',
    'فَلَا تَحۡسَبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡلِفَ وَعۡدِه<rule class=madda_normal>ِۦ</rule> رُسُلَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِي<rule class=ikhafa>زٌ</rule> <rule class=ikhafa>ذ</rule>ُو <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>ِق<rule class=madda_permissible>َا</rule>مٍ ٤٧',
    47, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 48 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1798,
    'یَوۡمَ تُبَدَّلُ ٱلۡأَرۡضُ غَیۡرَ ٱلۡأَرۡضِ وَٱلسَّمَـٰوَ ٰ⁠تُۖ وَبَرَزُوا۟ لِلَّهِ ٱلۡوَ ٰ⁠حِدِ ٱلۡقَهَّارِ',
    'يوم تبدل الارض غير الارض والسماوات وبرزوا لله الواحد القهار',
    'يَوۡمَ تُبَدَّلُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ غَيۡرَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ‌ۖ وَبَرَزُو<rule class=slnt>اۡ</rule> لِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>حِدِ <rule class=ham_wasl>ٱ</rule>لۡقَهّ<rule class=madda_permissible>َا</rule>رِ ٤٨',
    48, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 49 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1799,
    'وَتَرَى ٱلۡمُجۡرِمِینَ یَوۡمَىِٕذࣲ مُّقَرَّنِینَ فِی ٱلۡأَصۡفَادِ',
    'وترى المجرمين يومئذ مقرنين في الاصفاد',
    'وَتَرَى <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّقَرَّنِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَصۡف<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٤٩',
    49, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 50 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1800,
    'سَرَابِیلُهُم مِّن قَطِرَانࣲ وَتَغۡشَىٰ وُجُوهَهُمُ ٱلنَّارُ',
    'سرابيلهم من قطران وتغشى وجوههم النار',
    'سَرَابِيلُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َطِرَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َتَغۡشَىٰ وُجُوهَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رُ ٥٠',
    50, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 51 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1801,
    'لِیَجۡزِیَ ٱللَّهُ كُلَّ نَفۡسࣲ مَّا كَسَبَتۡۚ إِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ',
    'ليجزي الله كل نفس ما كسبت ان الله سريع الحساب',
    'لِيَ<rule class=qalaqah>جۡ</rule>زِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ كُلَّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا كَسَبَتۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٥١',
    51, 13, 3, 261, 217, 104, 'false'
  );
  
  -- Ayah 52 Surah Ibrahim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    14,
    1802,
    'هَـٰذَا بَلَـٰغࣱ لِّلنَّاسِ وَلِیُنذَرُوا۟ بِهِۦ وَلِیَعۡلَمُوۤا۟ أَنَّمَا هُوَ إِلَـٰهࣱ وَ ٰ⁠حِدࣱ وَلِیَذَّكَّرَ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ',
    'هذا بلاغ للناس ولينذروا به وليعلموا انما هو اله واحد وليذكر اولو الالباب',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا بَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>غٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ وَلِيُ<rule class=ikhafa>نذ</rule>َرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> وَلِيَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َمَا هُوَ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َلِيَذَّكَّرَ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٥٢',
    52, 13, 3, 261, 217, 104, 'false'
  );
  

-- Surah Al-Hijr
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (15, 'سُورَةُ الحِجۡرِ', 'Al-Hijr', 'The Rock', 'Meccan', 99);

  -- Ayah 1 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1803,
    'الۤرۚ تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ وَقُرۡءَانࣲ مُّبِینࣲ',
    'الر تلك ايات الكتاب وقران مبين',
    'ا<rule class=madda_necessary>لٓ</rule>ر‌ۚ تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَقُرۡءَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١',
    1, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 2 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1804,
    'رُّبَمَا یَوَدُّ ٱلَّذِینَ كَفَرُوا۟ لَوۡ كَانُوا۟ مُسۡلِمِینَ',
    'ربما يود الذين كفروا لو كانوا مسلمين',
    'رُّبَمَا يَوَدُّ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَوۡ كَانُو<rule class=slnt>اۡ</rule> مُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 3 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1805,
    'ذَرۡهُمۡ یَأۡكُلُوا۟ وَیَتَمَتَّعُوا۟ وَیُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ یَعۡلَمُونَ',
    'ذرهم ياكلوا ويتمتعوا ويلههم الامل فسوف يعلمون',
    'ذَرۡهُمۡ يَأۡكُلُو<rule class=slnt>اۡ</rule> وَيَتَمَتَّعُو<rule class=slnt>اۡ</rule> وَيُلۡهِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَمَلُ‌ۖ فَسَوۡفَ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 4 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1806,
    'وَمَاۤ أَهۡلَكۡنَا مِن قَرۡیَةٍ إِلَّا وَلَهَا كِتَابࣱ مَّعۡلُومࣱ',
    'وما اهلكنا من قرية الا ولها كتاب معلوم',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَهۡلَكۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ إِلَّا وَلَهَا كِتَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡل<rule class=madda_permissible>ُو</rule>مٌ ٤',
    4, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 5 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1807,
    'مَّا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا یَسۡتَـٔۡخِرُونَ',
    'ما تسبق من امة اجلها وما يستاخرون',
    'مَّا تَسۡبِقُ مِنۡ أُ<rule class=ghunnah>مّ</rule>َةٍ أَجَلَهَا وَمَا يَسۡتَــٔۡخِر<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 6 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1808,
    'وَقَالُوا۟ یَـٰۤأَیُّهَا ٱلَّذِی نُزِّلَ عَلَیۡهِ ٱلذِّكۡرُ إِنَّكَ لَمَجۡنُونࣱ',
    'وقالوا يا ايها الذي نزل عليه الذكر انك لمجنون',
    'وَقَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِى نُزِّلَ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرُ إِ<rule class=ghunnah>نّ</rule>َكَ لَمَ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نٌ ٦',
    6, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 7 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1809,
    'لَّوۡ مَا تَأۡتِینَا بِٱلۡمَلَـٰۤىِٕكَةِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'لو ما تاتينا بالملائكة ان كنت من الصادقين',
    'لَّوۡ مَا تَأۡتِينَا بِ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 8 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1810,
    'مَا نُنَزِّلُ ٱلۡمَلَـٰۤىِٕكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوۤا۟ إِذࣰا مُّنظَرِینَ',
    'ما ننزل الملائكة الا بالحق وما كانوا اذا منظرين',
    'مَا نُنَزِّلُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةَ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَمَا كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=idgham_ghunnah>ذًا</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 9 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1811,
    'إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ',
    'انا نحن نزلنا الذكر وانا له لحافظون',
    'إِ<rule class=ghunnah>نّ</rule>َا نَحۡنُ نَزَّلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَ وَإِ<rule class=ghunnah>نّ</rule>َا لَهُ<rule class=madda_normal>ۥ</rule> لَحَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 10 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1812,
    'وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ فِی شِیَعِ ٱلۡأَوَّلِینَ',
    'ولقد ارسلنا من قبلك في شيع الاولين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ فِى شِيَعِ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 11 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1813,
    'وَمَا یَأۡتِیهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'وما ياتيهم من رسول الا كانوا به يستهزئون',
    'وَمَا يَأۡتِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولٍ إِلَّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 12 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1814,
    'كَذَ ٰ⁠لِكَ نَسۡلُكُهُۥ فِی قُلُوبِ ٱلۡمُجۡرِمِینَ',
    'كذلك نسلكه في قلوب المجرمين',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَسۡلُكُهُ<rule class=madda_normal>ۥ</rule> فِى قُلُوبِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ١٢',
    12, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 13 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1815,
    'لَا یُؤۡمِنُونَ بِهِۦ وَقَدۡ خَلَتۡ سُنَّةُ ٱلۡأَوَّلِینَ',
    'لا يؤمنون به وقد خلت سنة الاولين',
    'لَا يُؤۡمِنُونَ بِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَقَ<rule class=qalaqah>دۡ</rule> خَلَتۡ سُ<rule class=ghunnah>نّ</rule>َةُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 14 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1816,
    'وَلَوۡ فَتَحۡنَا عَلَیۡهِم بَابࣰا مِّنَ ٱلسَّمَاۤءِ فَظَلُّوا۟ فِیهِ یَعۡرُجُونَ',
    'ولو فتحنا عليهم بابا من السماء فظلوا فيه يعرجون',
    'وَلَوۡ فَتَحۡنَا عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>َا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَظَلُّو<rule class=slnt>اۡ</rule> فِيهِ يَعۡرُج<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 15 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1817,
    'لَقَالُوۤا۟ إِنَّمَا سُكِّرَتۡ أَبۡصَـٰرُنَا بَلۡ نَحۡنُ قَوۡمࣱ مَّسۡحُورُونَ',
    'لقالوا انما سكرت ابصارنا بل نحن قوم مسحورون',
    'لَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا سُكِّرَتۡ أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُنَا بَلۡ نَحۡنُ قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>َّسۡحُور<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 14, 3, 262, 218, 105, 'false'
  );
  
  -- Ayah 16 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1818,
    'وَلَقَدۡ جَعَلۡنَا فِی ٱلسَّمَاۤءِ بُرُوجࣰا وَزَیَّنَّـٰهَا لِلنَّـٰظِرِینَ',
    'ولقد جعلنا في السماء بروجا وزيناها للناظرين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> جَعَلۡنَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بُرُو<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َزَيَّ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هَا لِل<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>ظِر<rule class=madda_permissible>ِي</rule>نَ ١٦',
    16, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 17 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1819,
    'وَحَفِظۡنَـٰهَا مِن كُلِّ شَیۡطَـٰنࣲ رَّجِیمٍ',
    'وحفظناها من كل شيطان رجيم',
    'وَحَفِظۡنَ<rule class=madda_normal>ـٰ</rule>هَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ شَيۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>نٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّج<rule class=madda_permissible>ِي</rule>مٍ ١٧',
    17, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 18 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1820,
    'إِلَّا مَنِ ٱسۡتَرَقَ ٱلسَّمۡعَ فَأَتۡبَعَهُۥ شِهَابࣱ مُّبِینࣱ',
    'الا من استرق السمع فاتبعه شهاب مبين',
    'إِلَّا مَنِ <rule class=ham_wasl>ٱ</rule>سۡتَرَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ فَأَتۡبَعَهُ<rule class=madda_normal>ۥ</rule> شِهَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٨',
    18, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 19 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1821,
    'وَٱلۡأَرۡضَ مَدَدۡنَـٰهَا وَأَلۡقَیۡنَا فِیهَا رَوَ ٰ⁠سِیَ وَأَنۢبَتۡنَا فِیهَا مِن كُلِّ شَیۡءࣲ مَّوۡزُونࣲ',
    'والارض مددناها والقينا فيها رواسي وانبتنا فيها من كل شيء موزون',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ مَدَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هَا وَأَلۡقَيۡنَا فِيهَا رَو<rule class=madda_normal>ٰ</rule>سِىَ وَأَ<rule class=iqlab>نۢب</rule>َتۡنَا فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>َّوۡز<rule class=madda_permissible>ُو</rule>نٍ ١٩',
    19, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 20 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1822,
    'وَجَعَلۡنَا لَكُمۡ فِیهَا مَعَـٰیِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَ ٰ⁠زِقِینَ',
    'وجعلنا لكم فيها معايش ومن لستم له برازقين',
    'وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَ<rule class=madda_normal>ـٰ</rule>يِشَ وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّسۡتُمۡ لَهُ<rule class=madda_normal>ۥ</rule> بِر<rule class=madda_normal>ٰ</rule>زِق<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 21 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1823,
    'وَإِن مِّن شَیۡءٍ إِلَّا عِندَنَا خَزَاۤىِٕنُهُۥ وَمَا نُنَزِّلُهُۥۤ إِلَّا بِقَدَرࣲ مَّعۡلُومࣲ',
    'وان من شيء الا عندنا خزائنه وما ننزله الا بقدر معلوم',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ إِلَّا عِ<rule class=ikhafa>ند</rule>َنَا خَز<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنُهُ<rule class=madda_normal>ۥ</rule> وَمَا نُنَزِّلُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا بِقَدَ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡل<rule class=madda_permissible>ُو</rule>مٍ ٢١',
    21, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 22 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1824,
    'وَأَرۡسَلۡنَا ٱلرِّیَـٰحَ لَوَ ٰ⁠قِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَسۡقَیۡنَـٰكُمُوهُ وَمَاۤ أَنتُمۡ لَهُۥ بِخَـٰزِنِینَ',
    'وارسلنا الرياح لواقح فانزلنا من السماء ماء فاسقيناكموه وما انتم له بخازنين',
    'وَأَرۡسَلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حَ لَو<rule class=madda_normal>ٰ</rule>قِحَ فَأَ<rule class=ikhafa>نز</rule>َلۡنَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَسۡقَيۡنَ<rule class=madda_normal>ـٰ</rule>كُمُوهُ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ لَهُ<rule class=madda_normal>ۥ</rule> بِخَ<rule class=madda_normal>ـٰ</rule>زِن<rule class=madda_permissible>ِي</rule>نَ ٢٢',
    22, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 23 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1825,
    'وَإِنَّا لَنَحۡنُ نُحۡیِۦ وَنُمِیتُ وَنَحۡنُ ٱلۡوَ ٰ⁠رِثُونَ',
    'وانا لنحن نحيي ونميت ونحن الوارثون',
    'وَإِ<rule class=ghunnah>نّ</rule>َا لَنَحۡنُ نُحۡى<rule class=madda_normal>ِۦ</rule> وَنُمِيتُ وَنَحۡنُ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>رِث<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 24 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1826,
    'وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِینَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِینَ',
    'ولقد علمنا المستقدمين منكم ولقد علمنا المستاخرين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> عَلِمۡنَا <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَ<rule class=qalaqah>قۡ</rule>دِمِينَ مِ<rule class=ikhafa>نك</rule>ُمۡ وَلَقَ<rule class=qalaqah>دۡ</rule> عَلِمۡنَا <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَــٔۡخِر<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 25 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1827,
    'وَإِنَّ رَبَّكَ هُوَ یَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِیمٌ عَلِیمࣱ',
    'وان ربك هو يحشرهم انه حكيم عليم',
    'وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ يَحۡشُرُهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> حَكِيمٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٥',
    25, 14, 3, 263, 219, 105, 'false'
  );
  
  -- Ayah 26 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1828,
    'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ مِن صَلۡصَـٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ',
    'ولقد خلقنا الانسان من صلصال من حما مسنون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َلۡصَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ حَمَ<rule class=idgham_ghunnah>إٍ</rule> <rule class=idgham_ghunnah>م</rule>َّسۡن<rule class=madda_permissible>ُو</rule>نٍ ٢٦',
    26, 14, 3, 263, 220, 105, 'false'
  );
  
  -- Ayah 27 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1829,
    'وَٱلۡجَاۤنَّ خَلَقۡنَـٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ',
    'والجان خلقناه من قبل من نار السموم',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡج<rule class=madda_necessary>َا</rule>ٓ<rule class=ghunnah>نّ</rule>َ خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّارِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_permissible>ُو</rule>مِ ٢٧',
    27, 14, 3, 263, 220, 105, 'false'
  );
  
  -- Ayah 28 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1830,
    'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰۤىِٕكَةِ إِنِّی خَـٰلِقُۢ بَشَرࣰا مِّن صَلۡصَـٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ',
    'واذ قال ربك للملائكة اني خالق بشرا من صلصال من حما مسنون',
    'وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ إِ<rule class=ghunnah>نّ</rule>ِى خَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=iqlab>قُۢ</rule> <rule class=iqlab>ب</rule>َشَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َلۡصَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ حَمَ<rule class=idgham_ghunnah>إٍ</rule> <rule class=idgham_ghunnah>م</rule>َّسۡن<rule class=madda_permissible>ُو</rule>نٍ ٢٨',
    28, 14, 3, 263, 220, 105, 'false'
  );
  
  -- Ayah 29 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1831,
    'فَإِذَا سَوَّیۡتُهُۥ وَنَفَخۡتُ فِیهِ مِن رُّوحِی فَقَعُوا۟ لَهُۥ سَـٰجِدِینَ',
    'فاذا سويته ونفخت فيه من روحي فقعوا له ساجدين',
    'فَإِذَا سَوَّيۡتُهُ<rule class=madda_normal>ۥ</rule> وَنَفَخۡتُ فِيهِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّوحِى فَقَعُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> سَ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 14, 3, 263, 220, 105, 'false'
  );
  
  -- Ayah 30 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1832,
    'فَسَجَدَ ٱلۡمَلَـٰۤىِٕكَةُ كُلُّهُمۡ أَجۡمَعُونَ',
    'فسجد الملائكة كلهم اجمعون',
    'فَسَجَدَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ كُلُّهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 14, 3, 263, 220, 105, 'false'
  );
  
  -- Ayah 31 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1833,
    'إِلَّاۤ إِبۡلِیسَ أَبَىٰۤ أَن یَكُونَ مَعَ ٱلسَّـٰجِدِینَ',
    'الا ابليس ابى ان يكون مع الساجدين',
    'إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>لِيسَ أَبَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 14, 3, 263, 220, 105, 'false'
  );
  
  -- Ayah 32 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1834,
    'قَالَ یَـٰۤإِبۡلِیسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّـٰجِدِینَ',
    'قال يا ابليس ما لك الا تكون مع الساجدين',
    'قَالَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>إِ<rule class=qalaqah>بۡ</rule>لِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 33 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1835,
    'قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَـٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ',
    'قال لم اكن لاسجد لبشر خلقته من صلصال من حما مسنون',
    'قَالَ لَمۡ أَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأَسۡجُدَ لِبَشَرٍ خَلَ<rule class=qalaqah>قۡ</rule>تَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َلۡصَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ حَمَ<rule class=idgham_ghunnah>إٍ</rule> <rule class=idgham_ghunnah>م</rule>َّسۡن<rule class=madda_permissible>ُو</rule>نٍ ٣٣',
    33, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 34 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1836,
    'قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِیمࣱ',
    'قال فاخرج منها فانك رجيم',
    'قَالَ فَ<rule class=ham_wasl>ٱ</rule>خۡرُ<rule class=qalaqah>جۡ</rule> مِنۡهَا فَإِ<rule class=ghunnah>نّ</rule>َكَ رَج<rule class=madda_permissible>ِي</rule>مٌ ٣٤',
    34, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 35 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1837,
    'وَإِنَّ عَلَیۡكَ ٱللَّعۡنَةَ إِلَىٰ یَوۡمِ ٱلدِّینِ',
    'وان عليك اللعنة الى يوم الدين',
    'وَإِ<rule class=ghunnah>نّ</rule>َ عَلَيۡكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّعۡنَةَ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ٣٥',
    35, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 36 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1838,
    'قَالَ رَبِّ فَأَنظِرۡنِیۤ إِلَىٰ یَوۡمِ یُبۡعَثُونَ',
    'قال رب فانظرني الى يوم يبعثون',
    'قَالَ رَبِّ فَأَ<rule class=ikhafa>نظ</rule>ِرۡن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ يَوۡمِ يُ<rule class=qalaqah>بۡ</rule>عَث<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 37 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1839,
    'قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِینَ',
    'قال فانك من المنظرين',
    'قَالَ فَإِ<rule class=ghunnah>نّ</rule>َكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 38 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1840,
    'إِلَىٰ یَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ',
    'الى يوم الوقت المعلوم',
    'إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡوَ<rule class=qalaqah>قۡ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡمَعۡل<rule class=madda_permissible>ُو</rule>مِ ٣٨',
    38, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 39 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1841,
    'قَالَ رَبِّ بِمَاۤ أَغۡوَیۡتَنِی لَأُزَیِّنَنَّ لَهُمۡ فِی ٱلۡأَرۡضِ وَلَأُغۡوِیَنَّهُمۡ أَجۡمَعِینَ',
    'قال رب بما اغويتني لازينن لهم في الارض ولاغوينهم اجمعين',
    'قَالَ رَبِّ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡوَيۡتَنِى لَأُزَيِّنَ<rule class=ghunnah>نّ</rule>َ لَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَأُغۡوِيَ<rule class=ghunnah>نّ</rule>َهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٣٩',
    39, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 40 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1842,
    'إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِینَ',
    'الا عبادك منهم المخلصين',
    'إِلَّا عِبَادَكَ مِنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡمُخۡلَص<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 41 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1843,
    'قَالَ هَـٰذَا صِرَ ٰ⁠طٌ عَلَیَّ مُسۡتَقِیمٌ',
    'قال هذا صراط علي مستقيم',
    'قَالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا صِر<rule class=madda_normal>ٰ</rule>طٌ عَلَىَّ مُسۡتَق<rule class=madda_permissible>ِي</rule>مٌ ٤١',
    41, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 42 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1844,
    'إِنَّ عِبَادِی لَیۡسَ لَكَ عَلَیۡهِمۡ سُلۡطَـٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلۡغَاوِینَ',
    'ان عبادي ليس لك عليهم سلطان الا من اتبعك من الغاوين',
    'إِ<rule class=ghunnah>نّ</rule>َ عِبَادِى لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَ<rule class=madda_normal>ـٰ</rule>نٌ إِلَّا مَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَاو<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 43 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1845,
    'وَإِنَّ جَهَنَّمَ لَمَوۡعِدُهُمۡ أَجۡمَعِینَ',
    'وان جهنم لموعدهم اجمعين',
    'وَإِ<rule class=ghunnah>نّ</rule>َ جَهَ<rule class=ghunnah>نّ</rule>َمَ لَمَوۡعِدُهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٤٣',
    43, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 44 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1846,
    'لَهَا سَبۡعَةُ أَبۡوَ ٰ⁠بࣲ لِّكُلِّ بَابࣲ مِّنۡهُمۡ جُزۡءࣱ مَّقۡسُومٌ',
    'لها سبعة ابواب لكل باب منهم جزء مقسوم',
    'لَهَا سَ<rule class=qalaqah>بۡ</rule>عَةُ أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule><rule class=idgham_wo_ghunnah>بٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ بَا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ جُزۡ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>قۡ</rule>س<rule class=madda_permissible>ُو</rule>مٌ ٤٤',
    44, 14, 3, 264, 220, 105, 'false'
  );
  
  -- Ayah 45 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1847,
    'إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَعُیُونٍ',
    'ان المتقين في جنات وعيون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقِينَ فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َعُي<rule class=madda_permissible>ُو</rule>نٍ ٤٥',
    45, 14, 3, 264, 221, 105, 'false'
  );
  
  -- Ayah 46 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1848,
    'ٱدۡخُلُوهَا بِسَلَـٰمٍ ءَامِنِینَ',
    'ادخلوها بسلام امنين',
    'ٱ<rule class=qalaqah>دۡ</rule>خُلُوهَا بِسَلَ<rule class=madda_normal>ـٰ</rule>مٍ ءَامِن<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 14, 3, 264, 221, 105, 'false'
  );
  
  -- Ayah 47 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1849,
    'وَنَزَعۡنَا مَا فِی صُدُورِهِم مِّنۡ غِلٍّ إِخۡوَ ٰ⁠نًا عَلَىٰ سُرُرࣲ مُّتَقَـٰبِلِینَ',
    'ونزعنا ما في صدورهم من غل اخوانا على سرر متقابلين',
    'وَنَزَعۡنَا مَا فِى صُدُورِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ غِلٍّ إِخۡو<rule class=madda_normal>ٰ</rule>نًا عَلَىٰ سُرُ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّتَقَ<rule class=madda_normal>ـٰ</rule>بِل<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 14, 3, 264, 221, 105, 'false'
  );
  
  -- Ayah 48 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1850,
    'لَا یَمَسُّهُمۡ فِیهَا نَصَبࣱ وَمَا هُم مِّنۡهَا بِمُخۡرَجِینَ',
    'لا يمسهم فيها نصب وما هم منها بمخرجين',
    'لَا يَمَسُّهُمۡ فِيهَا نَصَ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا بِمُخۡرَج<rule class=madda_permissible>ِي</rule>نَ ٤٨',
    48, 14, 3, 264, 221, 105, 'false'
  );
  
  -- Ayah 49 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1851,
    '۞ نَبِّئۡ عِبَادِیۤ أَنِّیۤ أَنَا ٱلۡغَفُورُ ٱلرَّحِیمُ',
    'نبئ عبادي اني انا الغفور الرحيم',
    '۞نَبِّئۡ عِبَاد<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنَا <rule class=ham_wasl>ٱ</rule>لۡغَفُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٤٩',
    49, 14, 3, 264, 221, 105, 'false'
  );
  
  -- Ayah 50 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1852,
    'وَأَنَّ عَذَابِی هُوَ ٱلۡعَذَابُ ٱلۡأَلِیمُ',
    'وان عذابي هو العذاب الاليم',
    'وَأَ<rule class=ghunnah>نّ</rule>َ عَذَابِى هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ <rule class=ham_wasl>ٱ</rule>لۡأَل<rule class=madda_permissible>ِي</rule>مُ ٥٠',
    50, 14, 3, 264, 221, 106, 'false'
  );
  
  -- Ayah 51 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1853,
    'وَنَبِّئۡهُمۡ عَن ضَیۡفِ إِبۡرَ ٰ⁠هِیمَ',
    'ونبئهم عن ضيف ابراهيم',
    'وَنَبِّئۡهُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َيۡفِ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>ه<rule class=madda_permissible>ِي</rule>مَ ٥١',
    51, 14, 3, 264, 221, 106, 'false'
  );
  
  -- Ayah 52 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1854,
    'إِذۡ دَخَلُوا۟ عَلَیۡهِ فَقَالُوا۟ سَلَـٰمࣰا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ',
    'اذ دخلوا عليه فقالوا سلاما قال انا منكم وجلون',
    'إِذۡ دَخَلُو<rule class=slnt>اۡ</rule> عَلَيۡهِ فَقَالُو<rule class=slnt>اۡ</rule> سَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مًا</rule> <rule class=ikhafa>ق</rule>َالَ إِ<rule class=ghunnah>نّ</rule>َا مِ<rule class=ikhafa>نك</rule>ُمۡ وَجِل<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 53 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1855,
    'قَالُوا۟ لَا تَوۡجَلۡ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ عَلِیمࣲ',
    'قالوا لا توجل انا نبشرك بغلام عليم',
    'قَالُو<rule class=slnt>اۡ</rule> لَا تَوۡجَلۡ إِ<rule class=ghunnah>نّ</rule>َا نُبَشِّرُكَ بِغُلَ<rule class=madda_normal>ـٰ</rule>مٍ عَل<rule class=madda_permissible>ِي</rule>مٍ ٥٣',
    53, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 54 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1856,
    'قَالَ أَبَشَّرۡتُمُونِی عَلَىٰۤ أَن مَّسَّنِیَ ٱلۡكِبَرُ فَبِمَ تُبَشِّرُونَ',
    'قال ابشرتموني على ان مسني الكبر فبم تبشرون',
    'قَالَ أَبَشَّرۡتُمُونِى عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّسَّنِىَ <rule class=ham_wasl>ٱ</rule>لۡكِبَرُ فَبِمَ تُبَشِّر<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 55 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1857,
    'قَالُوا۟ بَشَّرۡنَـٰكَ بِٱلۡحَقِّ فَلَا تَكُن مِّنَ ٱلۡقَـٰنِطِینَ',
    'قالوا بشرناك بالحق فلا تكن من القانطين',
    'قَالُو<rule class=slnt>اۡ</rule> بَشَّرۡنَ<rule class=madda_normal>ـٰ</rule>كَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ فَلَا تَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>نِط<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 56 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1858,
    'قَالَ وَمَن یَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦۤ إِلَّا ٱلضَّاۤلُّونَ',
    'قال ومن يقنط من رحمة ربه الا الضالون',
    'قَالَ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>نَطُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَةِ رَبِّه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضّ<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 57 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1859,
    'قَالَ فَمَا خَطۡبُكُمۡ أَیُّهَا ٱلۡمُرۡسَلُونَ',
    'قال فما خطبكم ايها المرسلون',
    'قَالَ فَمَا خَ<rule class=qalaqah>طۡ</rule>بُكُمۡ أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 58 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1860,
    'قَالُوۤا۟ إِنَّاۤ أُرۡسِلۡنَاۤ إِلَىٰ قَوۡمࣲ مُّجۡرِمِینَ',
    'قالوا انا ارسلنا الى قوم مجرمين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ قَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 59 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1861,
    'إِلَّاۤ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِینَ',
    'الا ال لوط انا لمنجوهم اجمعين',
    'إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> ءَالَ لُوطٍ إِ<rule class=ghunnah>نّ</rule>َا لَمُنَجُّوهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٥٩',
    59, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 60 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1862,
    'إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَاۤ إِنَّهَا لَمِنَ ٱلۡغَـٰبِرِینَ',
    'الا امراته قدرنا انها لمن الغابرين',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>مۡرَأَتَهُ<rule class=madda_normal>ۥ</rule> قَدَّرۡن<rule class=madda_obligatory_monfasel>َآ‌ۙ</rule> إِ<rule class=ghunnah>نّ</rule>َهَا لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٦٠',
    60, 14, 3, 265, 221, 106, 'false'
  );
  
  -- Ayah 61 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1863,
    'فَلَمَّا جَاۤءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ',
    'فلما جاء ال لوط المرسلون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ءَالَ لُوطٍ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 62 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1864,
    'قَالَ إِنَّكُمۡ قَوۡمࣱ مُّنكَرُونَ',
    'قال انكم قوم منكرون',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َكُمۡ قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=ikhafa>نك</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 63 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1865,
    'قَالُوا۟ بَلۡ جِئۡنَـٰكَ بِمَا كَانُوا۟ فِیهِ یَمۡتَرُونَ',
    'قالوا بل جئناك بما كانوا فيه يمترون',
    'قَالُو<rule class=slnt>اۡ</rule> بَلۡ جِئۡنَ<rule class=madda_normal>ـٰ</rule>كَ بِمَا كَانُو<rule class=slnt>اۡ</rule> فِيهِ يَمۡتَر<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 64 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1866,
    'وَأَتَیۡنَـٰكَ بِٱلۡحَقِّ وَإِنَّا لَصَـٰدِقُونَ',
    'واتيناك بالحق وانا لصادقون',
    'وَأَتَيۡنَ<rule class=madda_normal>ـٰ</rule>كَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَإِ<rule class=ghunnah>نّ</rule>َا لَصَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 65 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1867,
    'فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعࣲ مِّنَ ٱلَّیۡلِ وَٱتَّبِعۡ أَدۡبَـٰرَهُمۡ وَلَا یَلۡتَفِتۡ مِنكُمۡ أَحَدࣱ وَٱمۡضُوا۟ حَیۡثُ تُؤۡمَرُونَ',
    'فاسر باهلك بقطع من الليل واتبع ادبارهم ولا يلتفت منكم احد وامضوا حيث تؤمرون',
    'فَأَسۡرِ بِأَهۡلِكَ بِقِ<rule class=qalaqah>طۡ</rule><rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule>تَّبِعۡ أَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رَهُمۡ وَلَا يَلۡتَفِتۡ مِ<rule class=ikhafa>نك</rule>ُمۡ أَحَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>مۡضُو<rule class=slnt>اۡ</rule> حَيۡثُ تُؤۡمَر<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 66 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1868,
    'وَقَضَیۡنَاۤ إِلَیۡهِ ذَ ٰ⁠لِكَ ٱلۡأَمۡرَ أَنَّ دَابِرَ هَـٰۤؤُلَاۤءِ مَقۡطُوعࣱ مُّصۡبِحِینَ',
    'وقضينا اليه ذلك الامر ان دابر هؤلاء مقطوع مصبحين',
    'وَقَضَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرَ أَ<rule class=ghunnah>نّ</rule>َ دَابِرَ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مَ<rule class=qalaqah>قۡ</rule>طُو<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّصۡبِح<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 67 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1869,
    'وَجَاۤءَ أَهۡلُ ٱلۡمَدِینَةِ یَسۡتَبۡشِرُونَ',
    'وجاء اهل المدينة يستبشرون',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَهۡلُ <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ يَسۡتَ<rule class=qalaqah>بۡ</rule>شِر<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 68 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1870,
    'قَالَ إِنَّ هَـٰۤؤُلَاۤءِ ضَیۡفِی فَلَا تَفۡضَحُونِ',
    'قال ان هؤلاء ضيفي فلا تفضحون',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ضَيۡفِى فَلَا تَفۡضَح<rule class=madda_permissible>ُو</rule>نِ ٦٨',
    68, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 69 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1871,
    'وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخۡزُونِ',
    'واتقوا الله ولا تخزون',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَلَا تُخۡز<rule class=madda_permissible>ُو</rule>نِ ٦٩',
    69, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 70 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1872,
    'قَالُوۤا۟ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَـٰلَمِینَ',
    'قالوا اولم ننهك عن العالمين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوَلَمۡ نَنۡهَكَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٧٠',
    70, 14, 3, 265, 222, 106, 'false'
  );
  
  -- Ayah 71 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1873,
    'قَالَ هَـٰۤؤُلَاۤءِ بَنَاتِیۤ إِن كُنتُمۡ فَـٰعِلِینَ',
    'قال هؤلاء بناتي ان كنتم فاعلين',
    'قَالَ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بَنَات<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ فَ<rule class=madda_normal>ـٰ</rule>عِل<rule class=madda_permissible>ِي</rule>نَ ٧١',
    71, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 72 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1874,
    'لَعَمۡرُكَ إِنَّهُمۡ لَفِی سَكۡرَتِهِمۡ یَعۡمَهُونَ',
    'لعمرك انهم لفي سكرتهم يعمهون',
    'لَعَمۡرُكَ إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَفِى سَكۡرَتِهِمۡ يَعۡمَه<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 73 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1875,
    'فَأَخَذَتۡهُمُ ٱلصَّیۡحَةُ مُشۡرِقِینَ',
    'فاخذتهم الصيحة مشرقين',
    'فَأَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡحَةُ مُشۡرِق<rule class=madda_permissible>ِي</rule>نَ ٧٣',
    73, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 74 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1876,
    'فَجَعَلۡنَا عَـٰلِیَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَیۡهِمۡ حِجَارَةࣰ مِّن سِجِّیلٍ',
    'فجعلنا عاليها سافلها وامطرنا عليهم حجارة من سجيل',
    'فَجَعَلۡنَا عَ<rule class=madda_normal>ـٰ</rule>لِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ِجّ<rule class=madda_permissible>ِي</rule>لٍ ٧٤',
    74, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 75 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1877,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّلۡمُتَوَسِّمِینَ',
    'ان في ذلك لايات للمتوسمين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَوَسِّم<rule class=madda_permissible>ِي</rule>نَ ٧٥',
    75, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 76 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1878,
    'وَإِنَّهَا لَبِسَبِیلࣲ مُّقِیمٍ',
    'وانها لبسبيل مقيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َهَا لَبِسَبِي<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّق<rule class=madda_permissible>ِي</rule>مٍ ٧٦',
    76, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 77 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1879,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّلۡمُؤۡمِنِینَ',
    'ان في ذلك لاية للمؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٧٧',
    77, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 78 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1880,
    'وَإِن كَانَ أَصۡحَـٰبُ ٱلۡأَیۡكَةِ لَظَـٰلِمِینَ',
    'وان كان اصحاب الايكة لظالمين',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡأَيۡكَةِ لَظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٧٨',
    78, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 79 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1881,
    'فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامࣲ مُّبِینࣲ',
    'فانتقمنا منهم وانهما لبامام مبين',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َقَمۡنَا مِنۡهُمۡ وَإِ<rule class=ghunnah>نّ</rule>َهُمَا لَبِإِمَا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٧٩',
    79, 14, 3, 266, 222, 106, 'false'
  );
  
  -- Ayah 80 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1882,
    'وَلَقَدۡ كَذَّبَ أَصۡحَـٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِینَ',
    'ولقد كذب اصحاب الحجر المرسلين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> كَذَّبَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡحِ<rule class=qalaqah>جۡ</rule>رِ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٨٠',
    80, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 81 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1883,
    'وَءَاتَیۡنَـٰهُمۡ ءَایَـٰتِنَا فَكَانُوا۟ عَنۡهَا مُعۡرِضِینَ',
    'واتيناهم اياتنا فكانوا عنها معرضين',
    'وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَكَانُو<rule class=slnt>اۡ</rule> عَنۡهَا مُعۡرِض<rule class=madda_permissible>ِي</rule>نَ ٨١',
    81, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 82 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1884,
    'وَكَانُوا۟ یَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُیُوتًا ءَامِنِینَ',
    'وكانوا ينحتون من الجبال بيوتا امنين',
    'وَكَانُو<rule class=slnt>اۡ</rule> يَنۡحِتُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجِبَالِ بُيُوتًا ءَامِن<rule class=madda_permissible>ِي</rule>نَ ٨٢',
    82, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 83 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1885,
    'فَأَخَذَتۡهُمُ ٱلصَّیۡحَةُ مُصۡبِحِینَ',
    'فاخذتهم الصيحة مصبحين',
    'فَأَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡحَةُ مُصۡبِح<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 84 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1886,
    'فَمَاۤ أَغۡنَىٰ عَنۡهُم مَّا كَانُوا۟ یَكۡسِبُونَ',
    'فما اغنى عنهم ما كانوا يكسبون',
    'فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡنَىٰ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 85 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1887,
    'وَمَا خَلَقۡنَا ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَاۤ إِلَّا بِٱلۡحَقِّۗ وَإِنَّ ٱلسَّاعَةَ لَـَٔاتِیَةࣱۖ فَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِیلَ',
    'وما خلقنا السماوات والارض وما بينهما الا بالحق وان الساعة لاتية فاصفح الصفح الجميل',
    'وَمَا خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ لَأَتِيَ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>صۡفَحِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّفۡحَ <rule class=ham_wasl>ٱ</rule>لۡجَم<rule class=madda_permissible>ِي</rule>لَ ٨٥',
    85, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 86 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1888,
    'إِنَّ رَبَّكَ هُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِیمُ',
    'ان ربك هو الخلاق العليم',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡخَلَّ<rule class=madda_normal>ـٰ</rule>قُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٨٦',
    86, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 87 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1889,
    'وَلَقَدۡ ءَاتَیۡنَـٰكَ سَبۡعࣰا مِّنَ ٱلۡمَثَانِی وَٱلۡقُرۡءَانَ ٱلۡعَظِیمَ',
    'ولقد اتيناك سبعا من المثاني والقران العظيم',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>كَ سَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمَثَانِى وَ<rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مَ ٨٧',
    87, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 88 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1890,
    'لَا تَمُدَّنَّ عَیۡنَیۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦۤ أَزۡوَ ٰ⁠جࣰا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَیۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِینَ',
    'لا تمدن عينيك الى ما متعنا به ازواجا منهم ولا تحزن عليهم واخفض جناحك للمؤمنين',
    'لَا تَمُدَّ<rule class=ghunnah>نّ</rule>َ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَ<rule class=ham_wasl>ٱ</rule>خۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٨٨',
    88, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 89 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1891,
    'وَقُلۡ إِنِّیۤ أَنَا ٱلنَّذِیرُ ٱلۡمُبِینُ',
    'وقل اني انا النذير المبين',
    'وَقُلۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َذِيرُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ٨٩',
    89, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 90 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1892,
    'كَمَاۤ أَنزَلۡنَا عَلَى ٱلۡمُقۡتَسِمِینَ',
    'كما انزلنا على المقتسمين',
    'كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>قۡ</rule>تَسِم<rule class=madda_permissible>ِي</rule>نَ ٩٠',
    90, 14, 3, 266, 223, 106, 'false'
  );
  
  -- Ayah 91 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1893,
    'ٱلَّذِینَ جَعَلُوا۟ ٱلۡقُرۡءَانَ عِضِینَ',
    'الذين جعلوا القران عضين',
    'ٱلَّذِينَ جَعَلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ عِض<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 14, 3, 267, 223, 106, 'false'
  );
  
  -- Ayah 92 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1894,
    'فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِینَ',
    'فوربك لنسالنهم اجمعين',
    'فَوَرَبِّكَ لَنَسۡــَٔلَ<rule class=ghunnah>نّ</rule>َهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٩٢',
    92, 14, 3, 267, 223, 106, 'false'
  );
  
  -- Ayah 93 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1895,
    'عَمَّا كَانُوا۟ یَعۡمَلُونَ',
    'عما كانوا يعملون',
    'عَ<rule class=ghunnah>مّ</rule>َا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 14, 3, 267, 223, 106, 'false'
  );
  
  -- Ayah 94 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1896,
    'فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِینَ',
    'فاصدع بما تؤمر واعرض عن المشركين',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٩٤',
    94, 14, 3, 267, 223, 106, 'false'
  );
  
  -- Ayah 95 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1897,
    'إِنَّا كَفَیۡنَـٰكَ ٱلۡمُسۡتَهۡزِءِینَ',
    'انا كفيناك المستهزئين',
    'إِ<rule class=ghunnah>نّ</rule>َا كَفَيۡنَ<rule class=madda_normal>ـٰ</rule>كَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَهۡزِء<rule class=madda_permissible>ِي</rule>نَ ٩٥',
    95, 14, 3, 267, 223, 106, 'false'
  );
  
  -- Ayah 96 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1898,
    'ٱلَّذِینَ یَجۡعَلُونَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَۚ فَسَوۡفَ یَعۡلَمُونَ',
    'الذين يجعلون مع الله الها اخر فسوف يعلمون',
    'ٱلَّذِينَ يَ<rule class=qalaqah>جۡ</rule>عَلُونَ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ‌ۚ فَسَوۡفَ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 14, 3, 267, 223, 106, 'false'
  );
  
  -- Ayah 97 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1899,
    'وَلَقَدۡ نَعۡلَمُ أَنَّكَ یَضِیقُ صَدۡرُكَ بِمَا یَقُولُونَ',
    'ولقد نعلم انك يضيق صدرك بما يقولون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> نَعۡلَمُ أَ<rule class=ghunnah>نّ</rule>َكَ يَضِيقُ صَ<rule class=qalaqah>دۡ</rule>رُكَ بِمَا يَقُول<rule class=madda_permissible>ُو</rule>نَ ٩٧',
    97, 14, 3, 267, 223, 106, 'false'
  );
  
  -- Ayah 98 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1900,
    'فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَكُن مِّنَ ٱلسَّـٰجِدِینَ',
    'فسبح بحمد ربك وكن من الساجدين',
    'فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ٩٨',
    98, 14, 3, 267, 223, 106, 'false'
  );
  
  -- Ayah 99 Surah Al-Hijr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    15,
    1901,
    'وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ یَأۡتِیَكَ ٱلۡیَقِینُ',
    'واعبد ربك حتى ياتيك اليقين',
    'وَ<rule class=ham_wasl>ٱ</rule>عۡبُ<rule class=qalaqah>دۡ</rule> رَبَّكَ حَتَّىٰ يَأۡتِيَكَ <rule class=ham_wasl>ٱ</rule>لۡيَق<rule class=madda_permissible>ِي</rule>نُ ٩٩',
    99, 14, 3, 267, 223, 106, 'false'
  );
  

-- Surah An-Nahl
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (16, 'سُورَةُ النَّحۡلِ', 'An-Nahl', 'The Bee', 'Meccan', 128);

  -- Ayah 1 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1902,
    'أَتَىٰۤ أَمۡرُ ٱللَّهِ فَلَا تَسۡتَعۡجِلُوهُۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ',
    'اتى امر الله فلا تستعجلوه سبحانه وتعالى عما يشركون',
    'أَتَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ فَلَا تَسۡتَعۡجِلُوهُ‌ۚ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> وَتَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 14, 3, 267, 224, 107, 'false'
  );
  
  -- Ayah 2 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1903,
    'یُنَزِّلُ ٱلۡمَلَـٰۤىِٕكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۤ أَنۡ أَنذِرُوۤا۟ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّاۤ أَنَا۠ فَٱتَّقُونِ',
    'ينزل الملائكة بالروح من امره على من يشاء من عباده ان انذروا انه لا اله الا انا فاتقون',
    'يُنَزِّلُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّوحِ مِنۡ أَمۡرِه<rule class=madda_normal>ِۦ</rule> عَلَىٰ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَنۡ أَ<rule class=ikhafa>نذ</rule>ِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ فَ<rule class=ham_wasl>ٱ</rule>تَّق<rule class=madda_permissible>ُو</rule>نِ ٢',
    2, 14, 3, 267, 224, 107, 'false'
  );
  
  -- Ayah 3 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1904,
    'خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ',
    'خلق السماوات والارض بالحق تعالى عما يشركون',
    'خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ تَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 14, 3, 267, 224, 107, 'false'
  );
  
  -- Ayah 4 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1905,
    'خَلَقَ ٱلۡإِنسَـٰنَ مِن نُّطۡفَةࣲ فَإِذَا هُوَ خَصِیمࣱ مُّبِینࣱ',
    'خلق الانسان من نطفة فاذا هو خصيم مبين',
    'خَلَقَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّ<rule class=qalaqah>طۡ</rule>فَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َإِذَا هُوَ خَصِي<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٤',
    4, 14, 3, 267, 224, 107, 'false'
  );
  
  -- Ayah 5 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1906,
    'وَٱلۡأَنۡعَـٰمَ خَلَقَهَاۖ لَكُمۡ فِیهَا دِفۡءࣱ وَمَنَـٰفِعُ وَمِنۡهَا تَأۡكُلُونَ',
    'والانعام خلقها لكم فيها دفء ومنافع ومنها تاكلون',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مَ خَلَقَهَا‌ۗ لَكُمۡ فِيهَا دِفۡ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَنَ<rule class=madda_normal>ـٰ</rule>فِعُ وَمِنۡهَا تَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 14, 3, 267, 224, 107, 'false'
  );
  
  -- Ayah 6 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1907,
    'وَلَكُمۡ فِیهَا جَمَالٌ حِینَ تُرِیحُونَ وَحِینَ تَسۡرَحُونَ',
    'ولكم فيها جمال حين تريحون وحين تسرحون',
    'وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَح<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 14, 3, 267, 224, 107, 'false'
  );
  
  -- Ayah 7 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1908,
    'وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدࣲ لَّمۡ تَكُونُوا۟ بَـٰلِغِیهِ إِلَّا بِشِقِّ ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفࣱ رَّحِیمࣱ',
    'وتحمل اثقالكم الى بلد لم تكونوا بالغيه الا بشق الانفس ان ربكم لرءوف رحيم',
    'وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَ<rule class=idgham_wo_ghunnah>دٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَكُونُو<rule class=slnt>اۡ</rule> بَ<rule class=madda_normal>ـٰ</rule>لِغِيهِ إِلَّا بِشِقِّ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>ُسِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكُمۡ لَرَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٧',
    7, 14, 3, 268, 224, 107, 'false'
  );
  
  -- Ayah 8 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1909,
    'وَٱلۡخَیۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِیرَ لِتَرۡكَبُوهَا وَزِینَةࣰۚ وَیَخۡلُقُ مَا لَا تَعۡلَمُونَ',
    'والخيل والبغال والحمير لتركبوها وزينة ويخلق ما لا تعلمون',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡخَيۡلَ وَ<rule class=ham_wasl>ٱ</rule>لۡبِغَالَ وَ<rule class=ham_wasl>ٱ</rule>لۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َيَخۡلُقُ مَا لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 14, 3, 268, 224, 107, 'false'
  );
  
  -- Ayah 9 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1910,
    'وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِیلِ وَمِنۡهَا جَاۤىِٕرࣱۚ وَلَوۡ شَاۤءَ لَهَدَىٰكُمۡ أَجۡمَعِینَ',
    'وعلى الله قصد السبيل ومنها جائر ولو شاء لهداكم اجمعين',
    'وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ قَصۡدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ وَمِنۡهَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>رٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لَهَدَ<rule class=madda_normal>ٮٰ</rule>كُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٩',
    9, 14, 3, 268, 224, 107, 'false'
  );
  
  -- Ayah 10 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1911,
    'هُوَ ٱلَّذِیۤ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰۖ لَّكُم مِّنۡهُ شَرَابࣱ وَمِنۡهُ شَجَرࣱ فِیهِ تُسِیمُونَ',
    'هو الذي انزل من السماء ماء لكم منه شراب ومنه شجر فيه تسيمون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_wo_ghunnah>ءً‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ شَرَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َمِنۡهُ شَجَ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>ِيهِ تُسِيم<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 14, 3, 268, 225, 107, 'false'
  );
  
  -- Ayah 11 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1912,
    'یُنۢبِتُ لَكُم بِهِ ٱلزَّرۡعَ وَٱلزَّیۡتُونَ وَٱلنَّخِیلَ وَٱلۡأَعۡنَـٰبَ وَمِن كُلِّ ٱلثَّمَرَ ٰ⁠تِۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَتَفَكَّرُونَ',
    'ينبت لكم به الزرع والزيتون والنخيل والاعناب ومن كل الثمرات ان في ذلك لاية لقوم يتفكرون',
    'يُ<rule class=iqlab>نۢب</rule>ِتُ لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّرۡعَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّيۡتُونَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َخِيلَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَعۡنَ<rule class=madda_normal>ـٰ</rule>بَ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 14, 3, 268, 225, 107, 'false'
  );
  
  -- Ayah 12 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1913,
    'وَسَخَّرَ لَكُمُ ٱلَّیۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ وَٱلنُّجُومُ مُسَخَّرَ ٰ⁠تُۢ بِأَمۡرِهِۦۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ',
    'وسخر لكم الليل والنهار والشمس والقمر والنجوم مسخرات بامره ان في ذلك لايات لقوم يعقلون',
    'وَسَخَّرَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُجُومُ مُسَخَّر<rule class=madda_normal>ٰ</rule><rule class=iqlab>تُۢ</rule> <rule class=iqlab>ب</rule>ِأَمۡرِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 14, 3, 268, 225, 107, 'false'
  );
  
  -- Ayah 13 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1914,
    'وَمَا ذَرَأَ لَكُمۡ فِی ٱلۡأَرۡضِ مُخۡتَلِفًا أَلۡوَ ٰ⁠نُهُۥۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَذَّكَّرُونَ',
    'وما ذرا لكم في الارض مختلفا الوانه ان في ذلك لاية لقوم يذكرون',
    'وَمَا ذَرَأَ لَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُخۡتَلِفًا أَلۡو<rule class=madda_normal>ٰ</rule>نُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َذَّكَّر<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 14, 3, 268, 225, 107, 'false'
  );
  
  -- Ayah 14 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1915,
    'وَهُوَ ٱلَّذِی سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُوا۟ مِنۡهُ لَحۡمࣰا طَرِیࣰّا وَتَسۡتَخۡرِجُوا۟ مِنۡهُ حِلۡیَةࣰ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِیهِ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ',
    'وهو الذي سخر البحر لتاكلوا منه لحما طريا وتستخرجوا منه حلية تلبسونها وترى الفلك مواخر فيه ولتبتغوا من فضله ولعلكم تشكرون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى سَخَّرَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَ لِتَأۡكُلُو<rule class=slnt>اۡ</rule> مِنۡهُ لَحۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ط</rule>َرِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َتَسۡتَخۡرِجُو<rule class=slnt>اۡ</rule> مِنۡهُ حِلۡيَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َلۡبَسُونَهَا وَتَرَى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ مَوَاخِرَ فِيهِ وَلِتَ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> وَلَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 14, 3, 268, 225, 107, 'false'
  );
  
  -- Ayah 15 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1916,
    'وَأَلۡقَىٰ فِی ٱلۡأَرۡضِ رَوَ ٰ⁠سِیَ أَن تَمِیدَ بِكُمۡ وَأَنۡهَـٰرࣰا وَسُبُلࣰا لَّعَلَّكُمۡ تَهۡتَدُونَ',
    'والقى في الارض رواسي ان تميد بكم وانهارا وسبلا لعلكم تهتدون',
    'وَأَلۡقَىٰ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ رَو<rule class=madda_normal>ٰ</rule>سِىَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمِيدَ بِكُمۡ وَأَنۡهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َسُبُل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّكُمۡ تَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 14, 3, 269, 225, 107, 'false'
  );
  
  -- Ayah 16 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1917,
    'وَعَلَـٰمَـٰتࣲۚ وَبِٱلنَّجۡمِ هُمۡ یَهۡتَدُونَ',
    'وعلامات وبالنجم هم يهتدون',
    'وَعَلَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َبِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=qalaqah>جۡ</rule>مِ هُمۡ يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 14, 3, 269, 225, 107, 'false'
  );
  
  -- Ayah 17 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1918,
    'أَفَمَن یَخۡلُقُ كَمَن لَّا یَخۡلُقُۚ أَفَلَا تَذَكَّرُونَ',
    'افمن يخلق كمن لا يخلق افلا تذكرون',
    'أَفَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡلُقُ كَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَخۡلُقُ‌ۗ أَفَلَا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 14, 3, 269, 225, 107, 'false'
  );
  
  -- Ayah 18 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1919,
    'وَإِن تَعُدُّوا۟ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَاۤۗ إِنَّ ٱللَّهَ لَغَفُورࣱ رَّحِیمࣱ',
    'وان تعدوا نعمة الله لا تحصوها ان الله لغفور رحيم',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعُدُّو<rule class=slnt>اۡ</rule> نِعۡمَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا تُحۡصُوه<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَغَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٨',
    18, 14, 3, 269, 225, 107, 'false'
  );
  
  -- Ayah 19 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1920,
    'وَٱللَّهُ یَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ',
    'والله يعلم ما تسرون وما تعلنون',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِن<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 14, 3, 269, 225, 107, 'false'
  );
  
  -- Ayah 20 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1921,
    'وَٱلَّذِینَ یَدۡعُونَ مِن دُونِ ٱللَّهِ لَا یَخۡلُقُونَ شَیۡـࣰٔا وَهُمۡ یُخۡلَقُونَ',
    'والذين يدعون من دون الله لا يخلقون شيئا وهم يخلقون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا يَخۡلُقُونَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ يُخۡلَق<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 14, 3, 269, 225, 107, 'false'
  );
  
  -- Ayah 21 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1922,
    'أَمۡوَ ٰ⁠تٌ غَیۡرُ أَحۡیَاۤءࣲۖ وَمَا یَشۡعُرُونَ أَیَّانَ یُبۡعَثُونَ',
    'اموات غير احياء وما يشعرون ايان يبعثون',
    'أَمۡو<rule class=madda_normal>ٰ</rule>تٌ غَيۡرُ أَحۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا يَشۡعُرُونَ أَيَّانَ يُ<rule class=qalaqah>بۡ</rule>عَث<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 14, 3, 269, 225, 107, 'false'
  );
  
  -- Ayah 22 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1923,
    'إِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰ⁠حِدࣱۚ فَٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ قُلُوبُهُم مُّنكِرَةࣱ وَهُم مُّسۡتَكۡبِرُونَ',
    'الهكم اله واحد فالذين لا يؤمنون بالاخرة قلوبهم منكرة وهم مستكبرون',
    'إِلَ<rule class=madda_normal>ـٰ</rule>هُكُمۡ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=ikhafa>دٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ قُلُوبُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=ikhafa>نك</rule>ِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡتَكۡبِر<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 14, 3, 269, 226, 107, 'false'
  );
  
  -- Ayah 23 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1924,
    'لَا جَرَمَ أَنَّ ٱللَّهَ یَعۡلَمُ مَا یُسِرُّونَ وَمَا یُعۡلِنُونَۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡمُسۡتَكۡبِرِینَ',
    'لا جرم ان الله يعلم ما يسرون وما يعلنون انه لا يحب المستكبرين',
    'لَا جَرَمَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَكۡبِر<rule class=madda_permissible>ِي</rule>نَ ٢٣',
    23, 14, 3, 269, 226, 107, 'false'
  );
  
  -- Ayah 24 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1925,
    'وَإِذَا قِیلَ لَهُم مَّاذَاۤ أَنزَلَ رَبُّكُمۡ قَالُوۤا۟ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ',
    'واذا قيل لهم ماذا انزل ربكم قالوا اساطير الاولين',
    'وَإِذَا قِيلَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّاذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ رَبُّكُمۡ‌ۙ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 14, 3, 269, 226, 107, 'false'
  );
  
  -- Ayah 25 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1926,
    'لِیَحۡمِلُوۤا۟ أَوۡزَارَهُمۡ كَامِلَةࣰ یَوۡمَ ٱلۡقِیَـٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِینَ یُضِلُّونَهُم بِغَیۡرِ عِلۡمٍۗ أَلَا سَاۤءَ مَا یَزِرُونَ',
    'ليحملوا اوزارهم كاملة يوم القيامة ومن اوزار الذين يضلونهم بغير علم الا ساء ما يزرون',
    'لِيَحۡمِل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡزَارَهُمۡ كَامِلَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۙ وَمِنۡ أَوۡزَارِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُضِلُّونَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِغَيۡرِ عِلۡمٍ‌ۗ أَلَا س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا يَزِر<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 14, 3, 269, 226, 107, 'false'
  );
  
  -- Ayah 26 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1927,
    'قَدۡ مَكَرَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَأَتَى ٱللَّهُ بُنۡیَـٰنَهُم مِّنَ ٱلۡقَوَاعِدِ فَخَرَّ عَلَیۡهِمُ ٱلسَّقۡفُ مِن فَوۡقِهِمۡ وَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَیۡثُ لَا یَشۡعُرُونَ',
    'قد مكر الذين من قبلهم فاتى الله بنيانهم من القواعد فخر عليهم السقف من فوقهم واتاهم العذاب من حيث لا يشعرون',
    'قَ<rule class=qalaqah>دۡ</rule> مَكَرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ فَأَتَى <rule class=ham_wasl>ٱ</rule>للَّهُ بُنۡيَ<rule class=madda_normal>ـٰ</rule>نَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقَوَاعِدِ فَخَرَّ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=qalaqah>قۡ</rule>فُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهِمۡ وَأَتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 14, 3, 269, 227, 107, 'false'
  );
  
  -- Ayah 27 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1928,
    'ثُمَّ یَوۡمَ ٱلۡقِیَـٰمَةِ یُخۡزِیهِمۡ وَیَقُولُ أَیۡنَ شُرَكَاۤءِیَ ٱلَّذِینَ كُنتُمۡ تُشَـٰۤقُّونَ فِیهِمۡۚ قَالَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡیَ ٱلۡیَوۡمَ وَٱلسُّوۤءَ عَلَى ٱلۡكَـٰفِرِینَ',
    'ثم يوم القيامة يخزيهم ويقول اين شركائي الذين كنتم تشاقون فيهم قال الذين اوتوا العلم ان الخزي اليوم والسوء على الكافرين',
    'ثُ<rule class=ghunnah>مّ</rule>َ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ يُخۡزِيهِمۡ وَيَقُولُ أَيۡنَ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كُ<rule class=ikhafa>نت</rule>ُمۡ تُشَ<rule class=madda_necessary>ـٰٓ</rule>قُّونَ فِيهِمۡ‌ۚ قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡخِزۡىَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 14, 3, 270, 227, 107, 'false'
  );
  
  -- Ayah 28 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1929,
    'ٱلَّذِینَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰۤىِٕكَةُ ظَالِمِیۤ أَنفُسِهِمۡۖ فَأَلۡقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوۤءِۭۚ بَلَىٰۤۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'الذين تتوفاهم الملائكة ظالمي انفسهم فالقوا السلم ما كنا نعمل من سوء بلى ان الله عليم بما كنتم تعملون',
    'ٱلَّذِينَ تَتَوَفَّ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ ظَالِم<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۖ فَأَلۡقَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَمَ مَا كُ<rule class=ghunnah>نّ</rule>َا نَعۡمَلُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=iqlab>ءِۭ‌ۚ</rule> <rule class=iqlab>ب</rule>َلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 14, 3, 270, 227, 107, 'false'
  );
  
  -- Ayah 29 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1930,
    'فَٱدۡخُلُوۤا۟ أَبۡوَ ٰ⁠بَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِینَ',
    'فادخلوا ابواب جهنم خالدين فيها فلبئس مثوى المتكبرين',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بَ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۖ فَلَبِئۡسَ مَثۡوَى <rule class=ham_wasl>ٱ</rule>لۡمُتَكَبِّر<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 14, 3, 270, 227, 107, 'false'
  );
  
  -- Ayah 30 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1931,
    '۞ وَقِیلَ لِلَّذِینَ ٱتَّقَوۡا۟ مَاذَاۤ أَنزَلَ رَبُّكُمۡۚ قَالُوا۟ خَیۡرࣰاۗ لِّلَّذِینَ أَحۡسَنُوا۟ فِی هَـٰذِهِ ٱلدُّنۡیَا حَسَنَةࣱۚ وَلَدَارُ ٱلۡـَٔاخِرَةِ خَیۡرࣱۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِینَ',
    'وقيل للذين اتقوا ماذا انزل ربكم قالوا خيرا للذين احسنوا في هذه الدنيا حسنة ولدار الاخرة خير ولنعم دار المتقين',
    '۞وَقِيلَ لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> مَاذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ رَبُّكُمۡ‌ۚ قَالُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_wo_ghunnah>رًا‌ۗ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ أَحۡسَنُو<rule class=slnt>اۡ</rule> فِى هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا حَسَنَ<rule class=idgham_ghunnah>ةٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَدَارُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ خَيۡ<rule class=idgham_ghunnah>رٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَنِعۡمَ دَارُ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٣٠',
    30, 14, 3, 270, 227, 108, 'false'
  );
  
  -- Ayah 31 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1932,
    'جَنَّـٰتُ عَدۡنࣲ یَدۡخُلُونَهَا تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ لَهُمۡ فِیهَا مَا یَشَاۤءُونَۚ كَذَ ٰ⁠لِكَ یَجۡزِی ٱللَّهُ ٱلۡمُتَّقِینَ',
    'جنات عدن يدخلونها تجري من تحتها الانهار لهم فيها ما يشاءون كذلك يجزي الله المتقين',
    'جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>خُلُونَهَا تَ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۖ لَهُمۡ فِيهَا مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُونَ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 14, 3, 270, 227, 108, 'false'
  );
  
  -- Ayah 32 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1933,
    'ٱلَّذِینَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰۤىِٕكَةُ طَیِّبِینَ یَقُولُونَ سَلَـٰمٌ عَلَیۡكُمُ ٱدۡخُلُوا۟ ٱلۡجَنَّةَ بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'الذين تتوفاهم الملائكة طيبين يقولون سلام عليكم ادخلوا الجنة بما كنتم تعملون',
    'ٱلَّذِينَ تَتَوَفَّ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ طَيِّبِينَ‌ۙ يَقُولُونَ سَلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 14, 3, 270, 227, 108, 'false'
  );
  
  -- Ayah 33 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1934,
    'هَلۡ یَنظُرُونَ إِلَّاۤ أَن تَأۡتِیَهُمُ ٱلۡمَلَـٰۤىِٕكَةُ أَوۡ یَأۡتِیَ أَمۡرُ رَبِّكَۚ كَذَ ٰ⁠لِكَ فَعَلَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'هل ينظرون الا ان تاتيهم الملائكة او ياتي امر ربك كذلك فعل الذين من قبلهم وما ظلمهم الله ولكن كانوا انفسهم يظلمون',
    'هَلۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ أَوۡ يَأۡتِىَ أَمۡرُ رَبِّكَ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ فَعَلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ وَمَا ظَلَمَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 14, 3, 270, 227, 108, 'false'
  );
  
  -- Ayah 34 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1935,
    'فَأَصَابَهُمۡ سَیِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'فاصابهم سيئات ما عملوا وحاق بهم ما كانوا به يستهزئون',
    'فَأَصَابَهُمۡ سَيِّـَٔـاتُ مَا عَمِلُو<rule class=slnt>اۡ</rule> وَحَاقَ بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 14, 3, 270, 227, 108, 'false'
  );
  
  -- Ayah 35 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1936,
    'وَقَالَ ٱلَّذِینَ أَشۡرَكُوا۟ لَوۡ شَاۤءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن شَیۡءࣲ نَّحۡنُ وَلَاۤ ءَابَاۤؤُنَا وَلَا حَرَّمۡنَا مِن دُونِهِۦ مِن شَیۡءࣲۚ كَذَ ٰ⁠لِكَ فَعَلَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ فَهَلۡ عَلَى ٱلرُّسُلِ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ',
    'وقال الذين اشركوا لو شاء الله ما عبدنا من دونه من شيء نحن ولا اباؤنا ولا حرمنا من دونه من شيء كذلك فعل الذين من قبلهم فهل على الرسل الا البلاغ المبين',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَشۡرَكُو<rule class=slnt>اۡ</rule> لَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا عَبَ<rule class=qalaqah>دۡ</rule>نَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>ن</rule>َّحۡنُ وَل<rule class=madda_obligatory_monfasel>َآ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا وَلَا حَرَّمۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ فَعَلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ فَهَلۡ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ٣٥',
    35, 14, 3, 271, 228, 108, 'false'
  );
  
  -- Ayah 36 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1937,
    'وَلَقَدۡ بَعَثۡنَا فِی كُلِّ أُمَّةࣲ رَّسُولًا أَنِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱجۡتَنِبُوا۟ ٱلطَّـٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَیۡهِ ٱلضَّلَـٰلَةُۚ فَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُكَذِّبِینَ',
    'ولقد بعثنا في كل امة رسولا ان اعبدوا الله واجتنبوا الطاغوت فمنهم من هدى الله ومنهم من حقت عليه الضلالة فسيروا في الارض فانظروا كيف كان عاقبة المكذبين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> بَعَثۡنَا فِى كُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولاً أَنِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَنِبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّ<rule class=madda_normal>ـٰ</rule>غُوتَ‌ۖ فَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ هَدَى <rule class=ham_wasl>ٱ</rule>للَّهُ وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ حَقَّتۡ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لَةُ‌ۚ فَسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُكَذِّب<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 14, 3, 271, 228, 108, 'false'
  );
  
  -- Ayah 37 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1938,
    'إِن تَحۡرِصۡ عَلَىٰ هُدَىٰهُمۡ فَإِنَّ ٱللَّهَ لَا یَهۡدِی مَن یُضِلُّۖ وَمَا لَهُم مِّن نَّـٰصِرِینَ',
    'ان تحرص على هداهم فان الله لا يهدي من يضل وما لهم من ناصرين',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡرِصۡ عَلَىٰ هُدَ<rule class=madda_normal>ٮٰ</rule>هُمۡ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضِلُّ‌ۖ وَمَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 14, 3, 271, 228, 108, 'false'
  );
  
  -- Ayah 38 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1939,
    'وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَا یَبۡعَثُ ٱللَّهُ مَن یَمُوتُۚ بَلَىٰ وَعۡدًا عَلَیۡهِ حَقࣰّا وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'واقسموا بالله جهد ايمانهم لا يبعث الله من يموت بلى وعدا عليه حقا ولكن اكثر الناس لا يعلمون',
    'وَأَ<rule class=qalaqah>قۡ</rule>سَمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ جَهۡدَ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ‌ۙ لَا يَ<rule class=qalaqah>بۡ</rule>عَثُ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمُوتُ‌ۚ بَلَىٰ وَعۡدًا عَلَيۡهِ حَق<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 14, 3, 271, 228, 108, 'false'
  );
  
  -- Ayah 39 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1940,
    'لِیُبَیِّنَ لَهُمُ ٱلَّذِی یَخۡتَلِفُونَ فِیهِ وَلِیَعۡلَمَ ٱلَّذِینَ كَفَرُوۤا۟ أَنَّهُمۡ كَانُوا۟ كَـٰذِبِینَ',
    'ليبين لهم الذي يختلفون فيه وليعلم الذين كفروا انهم كانوا كاذبين',
    'لِيُبَيِّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى يَخۡتَلِفُونَ فِيهِ وَلِيَعۡلَمَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> كَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٣٩',
    39, 14, 3, 271, 228, 108, 'false'
  );
  
  -- Ayah 40 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1941,
    'إِنَّمَا قَوۡلُنَا لِشَیۡءٍ إِذَاۤ أَرَدۡنَـٰهُ أَن نَّقُولَ لَهُۥ كُن فَیَكُونُ',
    'انما قولنا لشيء اذا اردناه ان نقول له كن فيكون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا قَوۡلُنَا لِشَىۡءٍ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَرَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّقُولَ لَهُ<rule class=madda_normal>ۥ</rule> كُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َيَك<rule class=madda_permissible>ُو</rule>نُ ٤٠',
    40, 14, 3, 271, 228, 108, 'false'
  );
  
  -- Ayah 41 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1942,
    'وَٱلَّذِینَ هَاجَرُوا۟ فِی ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمۡ فِی ٱلدُّنۡیَا حَسَنَةࣰۖ وَلَأَجۡرُ ٱلۡـَٔاخِرَةِ أَكۡبَرُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ',
    'والذين هاجروا في الله من بعد ما ظلموا لنبوئنهم في الدنيا حسنة ولاجر الاخرة اكبر لو كانوا يعلمون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هَاجَرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ظُلِمُو<rule class=slnt>اۡ</rule> لَنُبَوِّئَ<rule class=ghunnah>نّ</rule>َهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا حَسَنَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَأَ<rule class=qalaqah>جۡ</rule>رُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ أَكۡبَرُ‌ۚ لَوۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 14, 3, 271, 229, 108, 'false'
  );
  
  -- Ayah 42 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1943,
    'ٱلَّذِینَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ',
    'الذين صبروا وعلى ربهم يتوكلون',
    'ٱلَّذِينَ صَبَرُو<rule class=slnt>اۡ</rule> وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّل<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 14, 3, 271, 229, 108, 'false'
  );
  
  -- Ayah 43 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1944,
    'وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالࣰا نُّوحِیۤ إِلَیۡهِمۡۖ فَسۡـَٔلُوۤا۟ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ',
    'وما ارسلنا من قبلك الا رجالا نوحي اليهم فاسالوا اهل الذكر ان كنتم لا تعلمون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ إِلَّا رِجَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ن</rule>ُّوح<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِمۡ‌ۚ فَسۡــَٔل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 14, 3, 272, 229, 108, 'false'
  );
  
  -- Ayah 44 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1945,
    'بِٱلۡبَیِّنَـٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَاۤ إِلَیۡكَ ٱلذِّكۡرَ لِتُبَیِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَیۡهِمۡ وَلَعَلَّهُمۡ یَتَفَكَّرُونَ',
    'بالبينات والزبر وانزلنا اليك الذكر لتبين للناس ما نزل اليهم ولعلهم يتفكرون',
    'بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زُّبُرِ‌ۗ وَأَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَ لِتُبَيِّنَ لِل<rule class=ghunnah>نّ</rule>َاسِ مَا نُزِّلَ إِلَيۡهِمۡ وَلَعَلَّهُمۡ يَتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 14, 3, 272, 229, 108, 'false'
  );
  
  -- Ayah 45 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1946,
    'أَفَأَمِنَ ٱلَّذِینَ مَكَرُوا۟ ٱلسَّیِّـَٔاتِ أَن یَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ أَوۡ یَأۡتِیَهُمُ ٱلۡعَذَابُ مِنۡ حَیۡثُ لَا یَشۡعُرُونَ',
    'افامن الذين مكروا السيئات ان يخسف الله بهم الارض او ياتيهم العذاب من حيث لا يشعرون',
    'أَفَأَمِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مَكَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡسِفَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ أَوۡ يَأۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 14, 3, 272, 229, 108, 'false'
  );
  
  -- Ayah 46 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1947,
    'أَوۡ یَأۡخُذَهُمۡ فِی تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِینَ',
    'او ياخذهم في تقلبهم فما هم بمعجزين',
    'أَوۡ يَأۡخُذَهُمۡ فِى تَقَلُّبِهِمۡ فَمَا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُعۡجِز<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 14, 3, 272, 229, 108, 'false'
  );
  
  -- Ayah 47 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1948,
    'أَوۡ یَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفࣲ فَإِنَّ رَبَّكُمۡ لَرَءُوفࣱ رَّحِیمٌ',
    'او ياخذهم على تخوف فان ربكم لرءوف رحيم',
    'أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّ<rule class=ikhafa>فٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ رَبَّكُمۡ لَرَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٤٧',
    47, 14, 3, 272, 229, 108, 'false'
  );
  
  -- Ayah 48 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1949,
    'أَوَلَمۡ یَرَوۡا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَیۡءࣲ یَتَفَیَّؤُا۟ ظِلَـٰلُهُۥ عَنِ ٱلۡیَمِینِ وَٱلشَّمَاۤىِٕلِ سُجَّدࣰا لِّلَّهِ وَهُمۡ دَ ٰ⁠خِرُونَ',
    'اولم يروا الى ما خلق الله من شيء يتفيا ظلاله عن اليمين والشمائل سجدا لله وهم داخرون',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> إِلَىٰ مَا خَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَيَّؤُ<rule class=slnt>اۡ</rule> ظِلَ<rule class=madda_normal>ـٰ</rule>لُهُ<rule class=madda_normal>ۥ</rule> عَنِ <rule class=ham_wasl>ٱ</rule>لۡيَمِينِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓئِلِ سُجَّ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّهِ وَهُمۡ د<rule class=madda_normal>ٰ</rule>خِر<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 14, 3, 272, 229, 108, 'false'
  );
  
  -- Ayah 49 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1950,
    'وَلِلَّهِ یَسۡجُدُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ مِن دَاۤبَّةࣲ وَٱلۡمَلَـٰۤىِٕكَةُ وَهُمۡ لَا یَسۡتَكۡبِرُونَ',
    'ولله يسجد ما في السماوات وما في الارض من دابة والملائكة وهم لا يستكبرون',
    'وَلِلَّهِ يَسۡجُدُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِر<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 14, 3, 272, 229, 108, 'false'
  );
  
  -- Ayah 50 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1951,
    'یَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَیَفۡعَلُونَ مَا یُؤۡمَرُونَ ۩',
    'يخافون ربهم من فوقهم ويفعلون ما يؤمرون',
    'يَخَافُونَ رَبَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُ<rule class=madda_permissible>و</rule>نَ ۩ ٥٠',
    50, 14, 3, 272, 229, 108, '{"id":3,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 51 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1952,
    '۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوۤا۟ إِلَـٰهَیۡنِ ٱثۡنَیۡنِۖ إِنَّمَا هُوَ إِلَـٰهࣱ وَ ٰ⁠حِدࣱ فَإِیَّـٰیَ فَٱرۡهَبُونِ',
    'وقال الله لا تتخذوا الهين اثنين انما هو اله واحد فاياي فارهبون',
    '۞وَقَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَا تَتَّخِذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَيۡنِ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َمَا هُوَ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=ikhafa>دٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِيَّ<rule class=madda_normal>ـٰ</rule>ىَ فَ<rule class=ham_wasl>ٱ</rule>رۡهَب<rule class=madda_permissible>ُو</rule>نِ ٥١',
    51, 14, 3, 272, 230, 109, 'false'
  );
  
  -- Ayah 52 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1953,
    'وَلَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَلَهُ ٱلدِّینُ وَاصِبًاۚ أَفَغَیۡرَ ٱللَّهِ تَتَّقُونَ',
    'وله ما في السماوات والارض وله الدين واصبا افغير الله تتقون',
    'وَلَهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينُ وَاصِبًا‌ۚ أَفَغَيۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ تَتَّق<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 14, 3, 272, 230, 109, 'false'
  );
  
  -- Ayah 53 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1954,
    'وَمَا بِكُم مِّن نِّعۡمَةࣲ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَیۡهِ تَجۡـَٔرُونَ',
    'وما بكم من نعمة فمن الله ثم اذا مسكم الضر فاليه تجارون',
    'وَمَا بِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ِّعۡمَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َمِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ إِذَا مَسَّكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّرُّ فَإِلَيۡهِ تَ<rule class=qalaqah>جۡ</rule>ــَٔر<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 14, 3, 272, 230, 109, 'false'
  );
  
  -- Ayah 54 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1955,
    'ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِیقࣱ مِّنكُم بِرَبِّهِمۡ یُشۡرِكُونَ',
    'ثم اذا كشف الضر عنكم اذا فريق منكم بربهم يشركون',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِذَا كَشَفَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّرَّ عَ<rule class=ikhafa>نك</rule>ُمۡ إِذَا فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرَبِّهِمۡ يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 14, 3, 272, 230, 109, 'false'
  );
  
  -- Ayah 55 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1956,
    'لِیَكۡفُرُوا۟ بِمَاۤ ءَاتَیۡنَـٰهُمۡۚ فَتَمَتَّعُوا۟ فَسَوۡفَ تَعۡلَمُونَ',
    'ليكفروا بما اتيناهم فتمتعوا فسوف تعلمون',
    'لِيَكۡفُرُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ‌ۚ فَتَمَتَّعُو<rule class=slnt>اۡ‌ۖ</rule> فَسَوۡفَ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 14, 3, 273, 230, 109, 'false'
  );
  
  -- Ayah 56 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1957,
    'وَیَجۡعَلُونَ لِمَا لَا یَعۡلَمُونَ نَصِیبࣰا مِّمَّا رَزَقۡنَـٰهُمۡۗ تَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَفۡتَرُونَ',
    'ويجعلون لما لا يعلمون نصيبا مما رزقناهم تالله لتسالن عما كنتم تفترون',
    'وَيَ<rule class=qalaqah>جۡ</rule>عَلُونَ لِمَا لَا يَعۡلَمُونَ نَصِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ‌ۗ تَ<rule class=ham_wasl>ٱ</rule>للَّهِ لَتُسۡــَٔلُ<rule class=ghunnah>نّ</rule>َ عَ<rule class=ghunnah>مّ</rule>َا كُ<rule class=ikhafa>نت</rule>ُمۡ تَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 14, 3, 273, 230, 109, 'false'
  );
  
  -- Ayah 57 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1958,
    'وَیَجۡعَلُونَ لِلَّهِ ٱلۡبَنَـٰتِ سُبۡحَـٰنَهُۥ وَلَهُم مَّا یَشۡتَهُونَ',
    'ويجعلون لله البنات سبحانه ولهم ما يشتهون',
    'وَيَ<rule class=qalaqah>جۡ</rule>عَلُونَ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡبَنَ<rule class=madda_normal>ـٰ</rule>تِ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule>‌ۙ وَلَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَشۡتَه<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 14, 3, 273, 230, 109, 'false'
  );
  
  -- Ayah 58 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1959,
    'وَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدࣰّا وَهُوَ كَظِیمࣱ',
    'واذا بشر احدهم بالانثى ظل وجهه مسودا وهو كظيم',
    'وَإِذَا بُشِّرَ أَحَدُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َىٰ ظَلَّ وَ<rule class=qalaqah>جۡ</rule>هُهُ<rule class=madda_normal>ۥ</rule> مُسۡوَد<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ كَظ<rule class=madda_permissible>ِي</rule>مٌ ٥٨',
    58, 14, 3, 273, 230, 109, 'false'
  );
  
  -- Ayah 59 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1960,
    'یَتَوَ ٰ⁠رَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوۤءِ مَا بُشِّرَ بِهِۦۤۚ أَیُمۡسِكُهُۥ عَلَىٰ هُونٍ أَمۡ یَدُسُّهُۥ فِی ٱلتُّرَابِۗ أَلَا سَاۤءَ مَا یَحۡكُمُونَ',
    'يتوارى من القوم من سوء ما بشر به ايمسكه على هون ام يدسه في التراب الا ساء ما يحكمون',
    'يَتَو<rule class=madda_normal>ٰ</rule>رَىٰ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ُو</rule>ٓءِ مَا بُشِّرَ بِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> أَيُمۡسِكُهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ هُونٍ أَمۡ يَدُسُّهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تُّرَابِ‌ۗ أَلَا س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا يَحۡكُم<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 14, 3, 273, 230, 109, 'false'
  );
  
  -- Ayah 60 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1961,
    'لِلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ مَثَلُ ٱلسَّوۡءِۖ وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'للذين لا يؤمنون بالاخرة مثل السوء ولله المثل الاعلى وهو العزيز الحكيم',
    'لِلَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ مَثَلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّوۡءِ‌ۖ وَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡمَثَلُ <rule class=ham_wasl>ٱ</rule>لۡأَعۡلَىٰ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٦٠',
    60, 14, 3, 273, 230, 109, 'false'
  );
  
  -- Ayah 61 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1962,
    'وَلَوۡ یُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَیۡهَا مِن دَاۤبَّةࣲ وَلَـٰكِن یُؤَخِّرُهُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّىۖ فَإِذَا جَاۤءَ أَجَلُهُمۡ لَا یَسۡتَـٔۡخِرُونَ سَاعَةࣰ وَلَا یَسۡتَقۡدِمُونَ',
    'ولو يؤاخذ الله الناس بظلمهم ما ترك عليها من دابة ولكن يؤخرهم الى اجل مسمى فاذا جاء اجلهم لا يستاخرون ساعة ولا يستقدمون',
    'وَلَوۡ يُؤَاخِذُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ بِظُلۡمِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا تَرَكَ عَلَيۡهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤَخِّرُهُمۡ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=ikhafa>ًّى‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَجَلُهُمۡ لَا يَسۡتَــٔۡخِرُونَ سَاعَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَسۡتَ<rule class=qalaqah>قۡ</rule>دِم<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 14, 3, 273, 231, 109, 'false'
  );
  
  -- Ayah 62 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1963,
    'وَیَجۡعَلُونَ لِلَّهِ مَا یَكۡرَهُونَۚ وَتَصِفُ أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفۡرَطُونَ',
    'ويجعلون لله ما يكرهون وتصف السنتهم الكذب ان لهم الحسنى لا جرم ان لهم النار وانهم مفرطون',
    'وَيَ<rule class=qalaqah>جۡ</rule>عَلُونَ لِلَّهِ مَا يَكۡرَهُونَ وَتَصِفُ أَلۡسِنَتُهُمُ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ أَ<rule class=ghunnah>نّ</rule>َ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ‌ۖ لَا جَرَمَ أَ<rule class=ghunnah>نّ</rule>َ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ وَأَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّفۡرَط<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 14, 3, 273, 231, 109, 'false'
  );
  
  -- Ayah 63 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1964,
    'تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَاۤ إِلَىٰۤ أُمَمࣲ مِّن قَبۡلِكَ فَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ فَهُوَ وَلِیُّهُمُ ٱلۡیَوۡمَ وَلَهُمۡ عَذَابٌ أَلِیمࣱ',
    'تالله لقد ارسلنا الى امم من قبلك فزين لهم الشيطان اعمالهم فهو وليهم اليوم ولهم عذاب اليم',
    'تَ<rule class=ham_wasl>ٱ</rule>للَّهِ لَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُمَ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ فَزَيَّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ فَهُوَ وَلِيُّهُمُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٦٣',
    63, 14, 3, 273, 231, 109, 'false'
  );
  
  -- Ayah 64 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1965,
    'وَمَاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ إِلَّا لِتُبَیِّنَ لَهُمُ ٱلَّذِی ٱخۡتَلَفُوا۟ فِیهِ وَهُدࣰى وَرَحۡمَةࣰ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'وما انزلنا عليك الكتاب الا لتبين لهم الذي اختلفوا فيه وهدى ورحمة لقوم يؤمنون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ إِلَّا لِتُبَيِّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى <rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> فِيهِ‌ۙ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 14, 3, 273, 231, 109, 'false'
  );
  
  -- Ayah 65 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1966,
    'وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَسۡمَعُونَ',
    'والله انزل من السماء ماء فاحيا به الارض بعد موتها ان في ذلك لاية لقوم يسمعون',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَحۡيَا بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَعۡدَ مَوۡتِه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡمَع<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 14, 3, 274, 231, 109, 'false'
  );
  
  -- Ayah 66 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1967,
    'وَإِنَّ لَكُمۡ فِی ٱلۡأَنۡعَـٰمِ لَعِبۡرَةࣰۖ نُّسۡقِیكُم مِّمَّا فِی بُطُونِهِۦ مِنۢ بَیۡنِ فَرۡثࣲ وَدَمࣲ لَّبَنًا خَالِصࣰا سَاۤىِٕغࣰا لِّلشَّـٰرِبِینَ',
    'وان لكم في الانعام لعبرة نسقيكم مما في بطونه من بين فرث ودم لبنا خالصا سائغا للشاربين',
    'وَإِ<rule class=ghunnah>نّ</rule>َ لَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ لَعِ<rule class=qalaqah>بۡ</rule>رَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>ن</rule>ُّسۡقِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا فِى بُطُونِه<rule class=madda_normal>ِۦ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ فَرۡ<rule class=idgham_ghunnah>ثٍ</rule> <rule class=idgham_ghunnah>و</rule>َدَ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّبَنًا خَالِ<rule class=ikhafa>صًا</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_wo_ghunnah>غًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلشَّ<rule class=madda_normal>ـٰ</rule>رِب<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 14, 3, 274, 232, 109, 'false'
  );
  
  -- Ayah 67 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1968,
    'وَمِن ثَمَرَ ٰ⁠تِ ٱلنَّخِیلِ وَٱلۡأَعۡنَـٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرࣰا وَرِزۡقًا حَسَنًاۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَعۡقِلُونَ',
    'ومن ثمرات النخيل والاعناب تتخذون منه سكرا ورزقا حسنا ان في ذلك لاية لقوم يعقلون',
    'وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َمَر<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َخِيلِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَعۡنَ<rule class=madda_normal>ـٰ</rule>بِ تَتَّخِذُونَ مِنۡهُ سَكَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َرِزۡقًا حَسَنًا‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 14, 3, 274, 232, 109, 'false'
  );
  
  -- Ayah 68 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1969,
    'وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِی مِنَ ٱلۡجِبَالِ بُیُوتࣰا وَمِنَ ٱلشَّجَرِ وَمِمَّا یَعۡرِشُونَ',
    'واوحى ربك الى النحل ان اتخذي من الجبال بيوتا ومن الشجر ومما يعرشون',
    'وَأَوۡحَىٰ رَبُّكَ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َحۡلِ أَنِ <rule class=ham_wasl>ٱ</rule>تَّخِذِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡجِبَالِ بُيُو<rule class=idgham_ghunnah>تًا</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرِ وَمِ<rule class=ghunnah>مّ</rule>َا يَعۡرِش<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 14, 3, 274, 232, 109, 'false'
  );
  
  -- Ayah 69 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1970,
    'ثُمَّ كُلِی مِن كُلِّ ٱلثَّمَرَ ٰ⁠تِ فَٱسۡلُكِی سُبُلَ رَبِّكِ ذُلُلࣰاۚ یَخۡرُجُ مِنۢ بُطُونِهَا شَرَابࣱ مُّخۡتَلِفٌ أَلۡوَ ٰ⁠نُهُۥ فِیهِ شِفَاۤءࣱ لِّلنَّاسِۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَتَفَكَّرُونَ',
    'ثم كلي من كل الثمرات فاسلكي سبل ربك ذللا يخرج من بطونها شراب مختلف الوانه فيه شفاء للناس ان في ذلك لاية لقوم يتفكرون',
    'ثُ<rule class=ghunnah>مّ</rule>َ كُلِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ فَ<rule class=ham_wasl>ٱ</rule>سۡلُكِى سُبُلَ رَبِّكِ ذُلُل<rule class=idgham_ghunnah>اً‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>َخۡرُجُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ُطُونِهَا شَرَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّخۡتَلِفٌ أَلۡو<rule class=madda_normal>ٰ</rule>نُهُ<rule class=madda_normal>ۥ</rule> فِيهِ شِف<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_wo_ghunnah>ءٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 14, 3, 274, 232, 109, 'false'
  );
  
  -- Ayah 70 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1971,
    'وَٱللَّهُ خَلَقَكُمۡ ثُمَّ یَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن یُرَدُّ إِلَىٰۤ أَرۡذَلِ ٱلۡعُمُرِ لِكَیۡ لَا یَعۡلَمَ بَعۡدَ عِلۡمࣲ شَیۡـًٔاۚ إِنَّ ٱللَّهَ عَلِیمࣱ قَدِیرࣱ',
    'والله خلقكم ثم يتوفاكم ومنكم من يرد الى ارذل العمر لكي لا يعلم بعد علم شيئا ان الله عليم قدير',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَلَقَكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يَتَوَفَّ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۚ وَمِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرَدُّ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَرۡذَلِ <rule class=ham_wasl>ٱ</rule>لۡعُمُرِ لِكَىۡ لَا يَعۡلَمَ بَعۡدَ عِلۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ش</rule>َيۡــًٔا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِي<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٧٠',
    70, 14, 3, 274, 232, 109, 'false'
  );
  
  -- Ayah 71 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1972,
    'وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضࣲ فِی ٱلرِّزۡقِۚ فَمَا ٱلَّذِینَ فُضِّلُوا۟ بِرَاۤدِّی رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ فَهُمۡ فِیهِ سَوَاۤءٌۚ أَفَبِنِعۡمَةِ ٱللَّهِ یَجۡحَدُونَ',
    'والله فضل بعضكم على بعض في الرزق فما الذين فضلوا برادي رزقهم على ما ملكت ايمانهم فهم فيه سواء افبنعمة الله يجحدون',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقِ‌ۚ فَمَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ فُضِّلُو<rule class=slnt>اۡ</rule> بِر<rule class=madda_necessary>َا</rule>ٓدِّى رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُهُمۡ فَهُمۡ فِيهِ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ‌ۚ أَفَبِنِعۡمَةِ <rule class=ham_wasl>ٱ</rule>للَّهِ يَ<rule class=qalaqah>جۡ</rule>حَد<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 14, 3, 274, 233, 109, 'false'
  );
  
  -- Ayah 72 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1973,
    'وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَ ٰ⁠جࣰا وَجَعَلَ لَكُم مِّنۡ أَزۡوَ ٰ⁠جِكُم بَنِینَ وَحَفَدَةࣰ وَرَزَقَكُم مِّنَ ٱلطَّیِّبَـٰتِۚ أَفَبِٱلۡبَـٰطِلِ یُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ یَكۡفُرُونَ',
    'والله جعل لكم من انفسكم ازواجا وجعل لكم من ازواجكم بنين وحفدة ورزقكم من الطيبات افبالباطل يؤمنون وبنعمت الله هم يكفرون',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ جَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَزۡو<rule class=madda_normal>ٰ</rule>جِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َنِينَ وَحَفَدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َرَزَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ‌ۚ أَفَبِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ يُؤۡمِنُونَ وَبِنِعۡمَتِ <rule class=ham_wasl>ٱ</rule>للَّهِ هُمۡ يَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 14, 3, 274, 233, 109, 'false'
  );
  
  -- Ayah 73 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1974,
    'وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَمۡلِكُ لَهُمۡ رِزۡقࣰا مِّنَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ شَیۡـࣰٔا وَلَا یَسۡتَطِیعُونَ',
    'ويعبدون من دون الله ما لا يملك لهم رزقا من السماوات والارض شيئا ولا يستطيعون',
    'وَيَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَمۡلِكُ لَهُمۡ رِزۡ<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَسۡتَطِيع<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 14, 3, 275, 233, 109, 'false'
  );
  
  -- Ayah 74 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1975,
    'فَلَا تَضۡرِبُوا۟ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ',
    'فلا تضربوا لله الامثال ان الله يعلم وانتم لا تعلمون',
    'فَلَا تَضۡرِبُو<rule class=slnt>اۡ</rule> لِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡأَمۡثَالَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٧٤',
    74, 14, 3, 275, 233, 109, 'false'
  );
  
  -- Ayah 75 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1976,
    '۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدࣰا مَّمۡلُوكࣰا لَّا یَقۡدِرُ عَلَىٰ شَیۡءࣲ وَمَن رَّزَقۡنَـٰهُ مِنَّا رِزۡقًا حَسَنࣰا فَهُوَ یُنفِقُ مِنۡهُ سِرࣰّا وَجَهۡرًاۖ هَلۡ یَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ',
    'ضرب الله مثلا عبدا مملوكا لا يقدر على شيء ومن رزقناه منا رزقا حسنا فهو ينفق منه سرا وجهرا هل يستوون الحمد لله بل اكثرهم لا يعلمون',
    '۞ضَرَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَثَلاً عَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>َّمۡلُو<rule class=idgham_wo_ghunnah>كًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَ<rule class=qalaqah>قۡ</rule>دِرُ عَلَىٰ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ مِ<rule class=ghunnah>نّ</rule>َا رِزۡقًا حَسَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َهُوَ يُ<rule class=ikhafa>نف</rule>ِقُ مِنۡهُ سِر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َجَهۡرًا‌ۖ هَلۡ يَسۡتَوُ<rule class=madda_normal>ۥ</rule>نَ‌ۚ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ‌ۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 14, 3, 275, 233, 110, 'false'
  );
  
  -- Ayah 76 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1977,
    'وَضَرَبَ ٱللَّهُ مَثَلࣰا رَّجُلَیۡنِ أَحَدُهُمَاۤ أَبۡكَمُ لَا یَقۡدِرُ عَلَىٰ شَیۡءࣲ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَیۡنَمَا یُوَجِّههُّ لَا یَأۡتِ بِخَیۡرٍ هَلۡ یَسۡتَوِی هُوَ وَمَن یَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'وضرب الله مثلا رجلين احدهما ابكم لا يقدر على شيء وهو كل على مولاه اينما يوجهه لا يات بخير هل يستوي هو ومن يامر بالعدل وهو على صراط مستقيم',
    'وَضَرَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَثَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّجُلَيۡنِ أَحَدُهُم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>كَمُ لَا يَ<rule class=qalaqah>قۡ</rule>دِرُ عَلَىٰ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ كَلٌّ عَلَىٰ مَوۡلَ<rule class=madda_normal>ـٰ</rule>هُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ‌ۖ هَلۡ يَسۡتَوِى هُوَ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡمُرُ بِ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>دۡ</rule>لِ‌ۙ وَهُوَ عَلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٧٦',
    76, 14, 3, 275, 233, 110, 'false'
  );
  
  -- Ayah 77 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1978,
    'وَلِلَّهِ غَیۡبُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَمَاۤ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'ولله غيب السماوات والارض وما امر الساعة الا كلمح البصر او هو اقرب ان الله على كل شيء قدير',
    'وَلِلَّهِ غَيۡبُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ إِلَّا كَلَمۡحِ <rule class=ham_wasl>ٱ</rule>لۡبَصَرِ أَوۡ هُوَ أَ<rule class=qalaqah>قۡ</rule>رَبُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٧٧',
    77, 14, 3, 275, 234, 110, 'false'
  );
  
  -- Ayah 78 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1979,
    'وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَـٰتِكُمۡ لَا تَعۡلَمُونَ شَیۡـࣰٔا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ',
    'والله اخرجكم من بطون امهاتكم لا تعلمون شيئا وجعل لكم السمع والابصار والافئدة لعلكم تشكرون',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَخۡرَجَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ُطُونِ أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ لَا تَعۡلَمُونَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَفۡــِٔدَةَ‌ۙ لَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 14, 3, 275, 234, 110, 'false'
  );
  
  -- Ayah 79 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1980,
    'أَلَمۡ یَرَوۡا۟ إِلَى ٱلطَّیۡرِ مُسَخَّرَ ٰ⁠تࣲ فِی جَوِّ ٱلسَّمَاۤءِ مَا یُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'الم يروا الى الطير مسخرات في جو السماء ما يمسكهن الا الله ان في ذلك لايات لقوم يؤمنون',
    'أَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرِ مُسَخَّر<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>ِى جَوِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مَا يُمۡسِكُهُ<rule class=ghunnah>نّ</rule>َ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 14, 3, 275, 234, 110, 'false'
  );
  
  -- Ayah 80 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1981,
    'وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُیُوتِكُمۡ سَكَنࣰا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَـٰمِ بُیُوتࣰا تَسۡتَخِفُّونَهَا یَوۡمَ ظَعۡنِكُمۡ وَیَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَاۤ أَثَـٰثࣰا وَمَتَـٰعًا إِلَىٰ حِینࣲ',
    'والله جعل لكم من بيوتكم سكنا وجعل لكم من جلود الانعام بيوتا تستخفونها يوم ظعنكم ويوم اقامتكم ومن اصوافها واوبارها واشعارها اثاثا ومتاعا الى حين',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ جَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ُيُوتِكُمۡ سَكَ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>ُلُودِ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ بُيُو<rule class=ikhafa>تًا</rule> <rule class=ikhafa>ت</rule>َسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ‌ۙ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِه<rule class=madda_obligatory_monfasel>َآ</rule> أَثَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>ثًا</rule> <rule class=idgham_ghunnah>و</rule>َمَتَ<rule class=madda_normal>ـٰ</rule>عًا إِلَىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٨٠',
    80, 14, 3, 276, 234, 110, 'false'
  );
  
  -- Ayah 81 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1982,
    'وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَـٰلࣰا وَجَعَلَ لَكُم مِّنَ ٱلۡجِبَالِ أَكۡنَـٰنࣰا وَجَعَلَ لَكُمۡ سَرَ ٰ⁠بِیلَ تَقِیكُمُ ٱلۡحَرَّ وَسَرَ ٰ⁠بِیلَ تَقِیكُم بَأۡسَكُمۡۚ كَذَ ٰ⁠لِكَ یُتِمُّ نِعۡمَتَهُۥ عَلَیۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ',
    'والله جعل لكم مما خلق ظلالا وجعل لكم من الجبال اكنانا وجعل لكم سرابيل تقيكم الحر وسرابيل تقيكم باسكم كذلك يتم نعمته عليكم لعلكم تسلمون',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ جَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا خَلَقَ ظِلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِبَالِ أَكۡنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ لَكُمۡ سَر<rule class=madda_normal>ٰ</rule>بِيلَ تَقِيكُمُ <rule class=ham_wasl>ٱ</rule>لۡحَرَّ وَسَر<rule class=madda_normal>ٰ</rule>بِيلَ تَقِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َأۡسَكُمۡ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُتِ<rule class=ghunnah>مّ</rule>ُ نِعۡمَتَهُ<rule class=madda_normal>ۥ</rule> عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 14, 3, 276, 234, 110, 'false'
  );
  
  -- Ayah 82 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1983,
    'فَإِن تَوَلَّوۡا۟ فَإِنَّمَا عَلَیۡكَ ٱلۡبَلَـٰغُ ٱلۡمُبِینُ',
    'فان تولوا فانما عليك البلاغ المبين',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َمَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ٨٢',
    82, 14, 3, 276, 234, 110, 'false'
  );
  
  -- Ayah 83 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1984,
    'یَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ یُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَـٰفِرُونَ',
    'يعرفون نعمت الله ثم ينكرونها واكثرهم الكافرون',
    'يَعۡرِفُونَ نِعۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ يُ<rule class=ikhafa>نك</rule>ِرُونَهَا وَأَكۡثَرُهُمُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٨٣',
    83, 14, 3, 276, 234, 110, 'false'
  );
  
  -- Ayah 84 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1985,
    'وَیَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةࣲ شَهِیدࣰا ثُمَّ لَا یُؤۡذَنُ لِلَّذِینَ كَفَرُوا۟ وَلَا هُمۡ یُسۡتَعۡتَبُونَ',
    'ويوم نبعث من كل امة شهيدا ثم لا يؤذن للذين كفروا ولا هم يستعتبون',
    'وَيَوۡمَ نَ<rule class=qalaqah>بۡ</rule>عَثُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ش</rule>َهِي<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَلَا هُمۡ يُسۡتَعۡتَب<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 14, 3, 276, 235, 110, 'false'
  );
  
  -- Ayah 85 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1986,
    'وَإِذَا رَءَا ٱلَّذِینَ ظَلَمُوا۟ ٱلۡعَذَابَ فَلَا یُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ یُنظَرُونَ',
    'واذا راى الذين ظلموا العذاب فلا يخفف عنهم ولا هم ينظرون',
    'وَإِذَا رَءَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ فَلَا يُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ يُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٨٥',
    85, 14, 3, 276, 235, 110, 'false'
  );
  
  -- Ayah 86 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1987,
    'وَإِذَا رَءَا ٱلَّذِینَ أَشۡرَكُوا۟ شُرَكَاۤءَهُمۡ قَالُوا۟ رَبَّنَا هَـٰۤؤُلَاۤءِ شُرَكَاۤؤُنَا ٱلَّذِینَ كُنَّا نَدۡعُوا۟ مِن دُونِكَۖ فَأَلۡقَوۡا۟ إِلَیۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَـٰذِبُونَ',
    'واذا راى الذين اشركوا شركاءهم قالوا ربنا هؤلاء شركاؤنا الذين كنا ندعو من دونك فالقوا اليهم القول انكم لكاذبون',
    'وَإِذَا رَءَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَشۡرَكُو<rule class=slnt>اۡ</rule> شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ قَالُو<rule class=slnt>اۡ</rule> رَبَّنَا هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كُ<rule class=ghunnah>نّ</rule>َا نَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِكَ‌ۖ فَأَلۡقَوۡ<rule class=slnt>اۡ</rule> إِلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلَ إِ<rule class=ghunnah>نّ</rule>َكُمۡ لَكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ٨٦',
    86, 14, 3, 276, 235, 110, 'false'
  );
  
  -- Ayah 87 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1988,
    'وَأَلۡقَوۡا۟ إِلَى ٱللَّهِ یَوۡمَىِٕذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ',
    'والقوا الى الله يومئذ السلم وضل عنهم ما كانوا يفترون',
    'وَأَلۡقَوۡ<rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَوۡمَئِذٍ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَمَ‌ۖ وَضَلَّ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٨٧',
    87, 14, 3, 276, 235, 110, 'false'
  );
  
  -- Ayah 88 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1989,
    'ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ زِدۡنَـٰهُمۡ عَذَابࣰا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُوا۟ یُفۡسِدُونَ',
    'الذين كفروا وصدوا عن سبيل الله زدناهم عذابا فوق العذاب بما كانوا يفسدون',
    'ٱلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَصَدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ زِ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َوۡقَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ بِمَا كَانُو<rule class=slnt>اۡ</rule> يُفۡسِد<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 14, 3, 277, 235, 110, 'false'
  );
  
  -- Ayah 89 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1990,
    'وَیَوۡمَ نَبۡعَثُ فِی كُلِّ أُمَّةࣲ شَهِیدًا عَلَیۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِیدًا عَلَىٰ هَـٰۤؤُلَاۤءِۚ وَنَزَّلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ تِبۡیَـٰنࣰا لِّكُلِّ شَیۡءࣲ وَهُدࣰى وَرَحۡمَةࣰ وَبُشۡرَىٰ لِلۡمُسۡلِمِینَ',
    'ويوم نبعث في كل امة شهيدا عليهم من انفسهم وجئنا بك شهيدا على هؤلاء ونزلنا عليك الكتاب تبيانا لكل شيء وهدى ورحمة وبشرى للمسلمين',
    'وَيَوۡمَ نَ<rule class=qalaqah>بۡ</rule>عَثُ فِى كُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ش</rule>َهِيدًا عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ وَنَزَّلۡنَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ تِ<rule class=qalaqah>بۡ</rule>يَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>نًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َبُشۡرَىٰ لِلۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٨٩',
    89, 14, 3, 277, 235, 110, 'false'
  );
  
  -- Ayah 90 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1991,
    '۞ إِنَّ ٱللَّهَ یَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَـٰنِ وَإِیتَاۤىِٕ ذِی ٱلۡقُرۡبَىٰ وَیَنۡهَىٰ عَنِ ٱلۡفَحۡشَاۤءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡیِۚ یَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ',
    'ان الله يامر بالعدل والاحسان وايتاء ذي القربى وينهى عن الفحشاء والمنكر والبغي يعظكم لعلكم تذكرون',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَأۡمُرُ بِ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>دۡ</rule>لِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِحۡسَ<rule class=madda_normal>ـٰ</rule>نِ وَإِيتَآىِٕ ذِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ <rule class=ham_wasl>ٱ</rule>لۡفَحۡش<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ وَ<rule class=ham_wasl>ٱ</rule>لۡبَغۡىِ‌ۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٩٠',
    90, 14, 3, 277, 236, 111, 'false'
  );
  
  -- Ayah 91 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1992,
    'وَأَوۡفُوا۟ بِعَهۡدِ ٱللَّهِ إِذَا عَـٰهَدتُّمۡ وَلَا تَنقُضُوا۟ ٱلۡأَیۡمَـٰنَ بَعۡدَ تَوۡكِیدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَیۡكُمۡ كَفِیلًاۚ إِنَّ ٱللَّهَ یَعۡلَمُ مَا تَفۡعَلُونَ',
    'واوفوا بعهد الله اذا عاهدتم ولا تنقضوا الايمان بعد توكيدها وقد جعلتم الله عليكم كفيلا ان الله يعلم ما تفعلون',
    'وَأَوۡفُو<rule class=slnt>اۡ</rule> بِعَهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِذَا عَ<rule class=madda_normal>ـٰ</rule>هَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ وَلَا تَ<rule class=ikhafa>نق</rule>ُضُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ بَعۡدَ تَوۡكِيدِهَا وَقَ<rule class=qalaqah>دۡ</rule> جَعَلۡتُمُ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَيۡكُمۡ كَفِيلاً‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ مَا تَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٩١',
    91, 14, 3, 277, 236, 111, 'false'
  );
  
  -- Ayah 92 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1993,
    'وَلَا تَكُونُوا۟ كَٱلَّتِی نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَـٰثࣰا تَتَّخِذُونَ أَیۡمَـٰنَكُمۡ دَخَلَۢا بَیۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِیَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا یَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَیُبَیِّنَنَّ لَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ مَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ',
    'ولا تكونوا كالتي نقضت غزلها من بعد قوة انكاثا تتخذون ايمانكم دخلا بينكم ان تكون امة هي اربى من امة انما يبلوكم الله به وليبينن لكم يوم القيامة ما كنتم فيه تختلفون',
    'وَلَا تَكُونُو<rule class=slnt>اۡ</rule> كَ<rule class=ham_wasl>ٱ</rule>لَّتِى نَقَضَتۡ غَزۡلَهَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ قُوَّةٍ أَ<rule class=ikhafa>نك</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>ثًا</rule> <rule class=ikhafa>ت</rule>َتَّخِذُونَ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ دَخَل<rule class=iqlab>اَۢ</rule> <rule class=iqlab>ب</rule>َيۡنَكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونَ أُ<rule class=ghunnah>مّ</rule>َةٌ هِىَ أَرۡبَىٰ مِنۡ أُ<rule class=ghunnah>مّ</rule>َةٍ‌ۚ إِ<rule class=ghunnah>نّ</rule>َمَا يَ<rule class=qalaqah>بۡ</rule>لُوكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَلَيُبَيِّنَ<rule class=ghunnah>نّ</rule>َ لَكُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ فِيهِ تَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ٩٢',
    92, 14, 3, 277, 236, 111, 'false'
  );
  
  -- Ayah 93 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1994,
    'وَلَوۡ شَاۤءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةࣰ وَ ٰ⁠حِدَةࣰ وَلَـٰكِن یُضِلُّ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ',
    'ولو شاء الله لجعلكم امة واحدة ولكن يضل من يشاء ويهدي من يشاء ولتسالن عما كنتم تعملون',
    'وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَجَعَلَكُمۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُضِلُّ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَلَتُسۡــَٔلُ<rule class=ghunnah>نّ</rule>َ عَ<rule class=ghunnah>مّ</rule>َا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 14, 3, 277, 236, 111, 'false'
  );
  
  -- Ayah 94 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1995,
    'وَلَا تَتَّخِذُوۤا۟ أَیۡمَـٰنَكُمۡ دَخَلَۢا بَیۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوۤءَ بِمَا صَدَدتُّمۡ عَن سَبِیلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِیمࣱ',
    'ولا تتخذوا ايمانكم دخلا بينكم فتزل قدم بعد ثبوتها وتذوقوا السوء بما صددتم عن سبيل الله ولكم عذاب عظيم',
    'وَلَا تَتَّخِذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ دَخَل<rule class=iqlab>اَۢ</rule> <rule class=iqlab>ب</rule>َيۡنَكُمۡ فَتَزِلَّ قَدَ<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>َعۡدَ ثُبُوتِهَا وَتَذُوقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ بِمَا صَدَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَلَكُمۡ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٩٤',
    94, 14, 3, 278, 236, 111, 'false'
  );
  
  -- Ayah 95 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1996,
    'وَلَا تَشۡتَرُوا۟ بِعَهۡدِ ٱللَّهِ ثَمَنࣰا قَلِیلًاۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ',
    'ولا تشتروا بعهد الله ثمنا قليلا انما عند الله هو خير لكم ان كنتم تعلمون',
    'وَلَا تَشۡتَرُو<rule class=slnt>اۡ</rule> بِعَهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهِ ثَمَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َلِيلاً‌ۚ إِ<rule class=ghunnah>نّ</rule>َمَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ هُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٩٥',
    95, 14, 3, 278, 236, 111, 'false'
  );
  
  -- Ayah 96 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1997,
    'مَا عِندَكُمۡ یَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقࣲۗ وَلَنَجۡزِیَنَّ ٱلَّذِینَ صَبَرُوۤا۟ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُوا۟ یَعۡمَلُونَ',
    'ما عندكم ينفد وما عند الله باق ولنجزين الذين صبروا اجرهم باحسن ما كانوا يعملون',
    'مَا عِ<rule class=ikhafa>ند</rule>َكُمۡ يَ<rule class=ikhafa>نف</rule>َدُ‌ۖ وَمَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ بَا<rule class=idgham_ghunnah>قٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َلَنَ<rule class=qalaqah>جۡ</rule>زِيَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ صَبَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>جۡ</rule>رَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَحۡسَنِ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 14, 3, 278, 236, 111, 'false'
  );
  
  -- Ayah 97 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1998,
    'مَنۡ عَمِلَ صَـٰلِحࣰا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَلَنُحۡیِیَنَّهُۥ حَیَوٰةࣰ طَیِّبَةࣰۖ وَلَنَجۡزِیَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُوا۟ یَعۡمَلُونَ',
    'من عمل صالحا من ذكر او انثى وهو مؤمن فلنحيينه حياة طيبة ولنجزينهم اجرهم باحسن ما كانوا يعملون',
    'مَنۡ عَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َكَرٍ أَوۡ أُ<rule class=ikhafa>نث</rule>َىٰ وَهُوَ مُؤۡمِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َلَنُحۡيِيَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> حَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule><rule class=ikhafa>ةً</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَنَ<rule class=qalaqah>جۡ</rule>زِيَ<rule class=ghunnah>نّ</rule>َهُمۡ أَ<rule class=qalaqah>جۡ</rule>رَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَحۡسَنِ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٧',
    97, 14, 3, 278, 236, 111, 'false'
  );
  
  -- Ayah 98 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    1999,
    'فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّیۡطَـٰنِ ٱلرَّجِیمِ',
    'فاذا قرات القران فاستعذ بالله من الشيطان الرجيم',
    'فَإِذَا قَرَأۡتَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ فَ<rule class=ham_wasl>ٱ</rule>سۡتَعِذۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّج<rule class=madda_permissible>ِي</rule>مِ ٩٨',
    98, 14, 3, 278, 236, 111, 'false'
  );
  
  -- Ayah 99 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2000,
    'إِنَّهُۥ لَیۡسَ لَهُۥ سُلۡطَـٰنٌ عَلَى ٱلَّذِینَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ',
    'انه ليس له سلطان على الذين امنوا وعلى ربهم يتوكلون',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَيۡسَ لَهُ<rule class=madda_normal>ۥ</rule> سُلۡطَ<rule class=madda_normal>ـٰ</rule>نٌ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّل<rule class=madda_permissible>ُو</rule>نَ ٩٩',
    99, 14, 3, 278, 236, 111, 'false'
  );
  
  -- Ayah 100 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2001,
    'إِنَّمَا سُلۡطَـٰنُهُۥ عَلَى ٱلَّذِینَ یَتَوَلَّوۡنَهُۥ وَٱلَّذِینَ هُم بِهِۦ مُشۡرِكُونَ',
    'انما سلطانه على الذين يتولونه والذين هم به مشركون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا سُلۡطَ<rule class=madda_normal>ـٰ</rule>نُهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَتَوَلَّوۡنَهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ١٠٠',
    100, 14, 3, 278, 236, 111, 'false'
  );
  
  -- Ayah 101 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2002,
    'وَإِذَا بَدَّلۡنَاۤ ءَایَةࣰ مَّكَانَ ءَایَةࣲ وَٱللَّهُ أَعۡلَمُ بِمَا یُنَزِّلُ قَالُوۤا۟ إِنَّمَاۤ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ',
    'واذا بدلنا اية مكان اية والله اعلم بما ينزل قالوا انما انت مفتر بل اكثرهم لا يعلمون',
    'وَإِذَا بَدَّلۡن<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>َّكَانَ ءَايَ<rule class=idgham_ghunnah>ةٍ‌ۙ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِمَا يُنَزِّلُ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ مُفۡتَ<rule class=iqlab>رِۭ‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ أَكۡثَرُهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٠١',
    101, 14, 3, 278, 237, 111, 'false'
  );
  
  -- Ayah 102 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2003,
    'قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِیُثَبِّتَ ٱلَّذِینَ ءَامَنُوا۟ وَهُدࣰى وَبُشۡرَىٰ لِلۡمُسۡلِمِینَ',
    'قل نزله روح القدس من ربك بالحق ليثبت الذين امنوا وهدى وبشرى للمسلمين',
    'قُلۡ نَزَّلَهُ<rule class=madda_normal>ۥ</rule> رُوحُ <rule class=ham_wasl>ٱ</rule>لۡقُدُسِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ لِيُثَبِّتَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َبُشۡرَىٰ لِلۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ١٠٢',
    102, 14, 3, 278, 237, 111, 'false'
  );
  
  -- Ayah 103 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2004,
    'وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ یَقُولُونَ إِنَّمَا یُعَلِّمُهُۥ بَشَرࣱۗ لِّسَانُ ٱلَّذِی یُلۡحِدُونَ إِلَیۡهِ أَعۡجَمِیࣱّ وَهَـٰذَا لِسَانٌ عَرَبِیࣱّ مُّبِینٌ',
    'ولقد نعلم انهم يقولون انما يعلمه بشر لسان الذي يلحدون اليه اعجمي وهذا لسان عربي مبين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> نَعۡلَمُ أَ<rule class=ghunnah>نّ</rule>َهُمۡ يَقُولُونَ إِ<rule class=ghunnah>نّ</rule>َمَا يُعَلِّمُهُ<rule class=madda_normal>ۥ</rule> بَشَ<rule class=idgham_wo_ghunnah>رٌ‌ۗ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّسَانُ <rule class=ham_wasl>ٱ</rule>لَّذِى يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِ<rule class=idgham_ghunnah>ىٌّ</rule> <rule class=idgham_ghunnah>و</rule>َهَ<rule class=madda_normal>ـٰ</rule>ذَا لِسَانٌ عَرَبِ<rule class=idgham_ghunnah>ىٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٠٣',
    103, 14, 3, 279, 237, 111, 'false'
  );
  
  -- Ayah 104 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2005,
    'إِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِـَٔایَـٰتِ ٱللَّهِ لَا یَهۡدِیهِمُ ٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِیمٌ',
    'ان الذين لا يؤمنون بايات الله لا يهديهم الله ولهم عذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا يَهۡدِيهِمُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١٠٤',
    104, 14, 3, 279, 237, 111, 'false'
  );
  
  -- Ayah 105 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2006,
    'إِنَّمَا یَفۡتَرِی ٱلۡكَذِبَ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِـَٔایَـٰتِ ٱللَّهِۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡكَـٰذِبُونَ',
    'انما يفتري الكذب الذين لا يؤمنون بايات الله واولئك هم الكاذبون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا يَفۡتَرِى <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ١٠٥',
    105, 14, 3, 279, 237, 111, 'false'
  );
  
  -- Ayah 106 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2007,
    'مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِیمَـٰنِهِۦۤ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَىِٕنُّۢ بِٱلۡإِیمَـٰنِ وَلَـٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرࣰا فَعَلَیۡهِمۡ غَضَبࣱ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِیمࣱ',
    'من كفر بالله من بعد ايمانه الا من اكره وقلبه مطمئن بالايمان ولكن من شرح بالكفر صدرا فعليهم غضب من الله ولهم عذاب عظيم',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ إِيمَ<rule class=madda_normal>ـٰ</rule>نِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُ<rule class=madda_normal>ۥ</rule> مُ<rule class=qalaqah>طۡ</rule>مَئِن<rule class=iqlab>ُّۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َرَحَ بِ<rule class=ham_wasl>ٱ</rule>لۡكُفۡرِ صَ<rule class=qalaqah>دۡ</rule><rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َعَلَيۡهِمۡ غَضَ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَهُمۡ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٠٦',
    106, 14, 3, 279, 237, 111, 'false'
  );
  
  -- Ayah 107 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2008,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمُ ٱسۡتَحَبُّوا۟ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا عَلَى ٱلۡـَٔاخِرَةِ وَأَنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡكَـٰفِرِینَ',
    'ذلك بانهم استحبوا الحياة الدنيا على الاخرة وان الله لا يهدي القوم الكافرين',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمُ <rule class=ham_wasl>ٱ</rule>سۡتَحَبُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٠٧',
    107, 14, 3, 279, 237, 111, 'false'
  );
  
  -- Ayah 108 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2009,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَـٰرِهِمۡۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡغَـٰفِلُونَ',
    'اولئك الذين طبع الله على قلوبهم وسمعهم وابصارهم واولئك هم الغافلون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ طَبَعَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ١٠٨',
    108, 14, 3, 279, 237, 111, 'false'
  );
  
  -- Ayah 109 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2010,
    'لَا جَرَمَ أَنَّهُمۡ فِی ٱلۡـَٔاخِرَةِ هُمُ ٱلۡخَـٰسِرُونَ',
    'لا جرم انهم في الاخرة هم الخاسرون',
    'لَا جَرَمَ أَ<rule class=ghunnah>نّ</rule>َهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ١٠٩',
    109, 14, 3, 279, 237, 111, 'false'
  );
  
  -- Ayah 110 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2011,
    'ثُمَّ إِنَّ رَبَّكَ لِلَّذِینَ هَاجَرُوا۟ مِنۢ بَعۡدِ مَا فُتِنُوا۟ ثُمَّ جَـٰهَدُوا۟ وَصَبَرُوۤا۟ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِیمࣱ',
    'ثم ان ربك للذين هاجروا من بعد ما فتنوا ثم جاهدوا وصبروا ان ربك من بعدها لغفور رحيم',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لِلَّذِينَ هَاجَرُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا فُتِنُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ جَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> وَصَبَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهَا لَغَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١١٠',
    110, 14, 3, 279, 237, 111, 'false'
  );
  
  -- Ayah 111 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2012,
    '۞ یَوۡمَ تَأۡتِی كُلُّ نَفۡسࣲ تُجَـٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ وَهُمۡ لَا یُظۡلَمُونَ',
    'يوم تاتي كل نفس تجادل عن نفسها وتوفى كل نفس ما عملت وهم لا يظلمون',
    '۞يَوۡمَ تَأۡتِى كُلُّ نَفۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ت</rule>ُجَ<rule class=madda_normal>ـٰ</rule>دِلُ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ١١١',
    111, 14, 3, 280, 238, 112, 'false'
  );
  
  -- Ayah 112 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2013,
    'وَضَرَبَ ٱللَّهُ مَثَلࣰا قَرۡیَةࣰ كَانَتۡ ءَامِنَةࣰ مُّطۡمَىِٕنَّةࣰ یَأۡتِیهَا رِزۡقُهَا رَغَدࣰا مِّن كُلِّ مَكَانࣲ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَ ٰ⁠قَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُوا۟ یَصۡنَعُونَ',
    'وضرب الله مثلا قرية كانت امنة مطمئنة ياتيها رزقها رغدا من كل مكان فكفرت بانعم الله فاذاقها الله لباس الجوع والخوف بما كانوا يصنعون',
    'وَضَرَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَثَل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ق</rule>َرۡيَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ك</rule>َانَتۡ ءَامِنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيهَا رِزۡقُهَا رَغَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مَكَا<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ف</rule>َكَفَرَتۡ بِأَنۡعُمِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَأَذ<rule class=madda_normal>ٰ</rule>قَهَا <rule class=ham_wasl>ٱ</rule>للَّهُ لِبَاسَ <rule class=ham_wasl>ٱ</rule>لۡجُوعِ وَ<rule class=ham_wasl>ٱ</rule>لۡخَوۡفِ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَصۡنَع<rule class=madda_permissible>ُو</rule>نَ ١١٢',
    112, 14, 3, 280, 238, 112, 'false'
  );
  
  -- Ayah 113 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2014,
    'وَلَقَدۡ جَاۤءَهُمۡ رَسُولࣱ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَـٰلِمُونَ',
    'ولقد جاءهم رسول منهم فكذبوه فاخذهم العذاب وهم ظالمون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ وَهُمۡ ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ١١٣',
    113, 14, 3, 280, 238, 112, 'false'
  );
  
  -- Ayah 114 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2015,
    'فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَـٰلࣰا طَیِّبࣰا وَٱشۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِیَّاهُ تَعۡبُدُونَ',
    'فكلوا مما رزقكم الله حلالا طيبا واشكروا نعمت الله ان كنتم اياه تعبدون',
    'فَكُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَقَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ حَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ط</rule>َيِّ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>شۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ إِيَّاهُ تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ١١٤',
    114, 14, 3, 280, 238, 112, 'false'
  );
  
  -- Ayah 115 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2016,
    'إِنَّمَا حَرَّمَ عَلَیۡكُمُ ٱلۡمَیۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِیرِ وَمَاۤ أُهِلَّ لِغَیۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَیۡرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'انما حرم عليكم الميتة والدم ولحم الخنزير وما اهل لغير الله به فمن اضطر غير باغ ولا عاد فان الله غفور رحيم',
    'إِ<rule class=ghunnah>نّ</rule>َمَا حَرَّمَ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَيۡتَةَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّمَ وَلَحۡمَ <rule class=ham_wasl>ٱ</rule>لۡخِ<rule class=ikhafa>نز</rule>ِيرِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُهِلَّ لِغَيۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَمَنِ <rule class=ham_wasl>ٱ</rule>ضۡطُرَّ غَيۡرَ بَا<rule class=idgham_ghunnah>غٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا عَا<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١١٥',
    115, 14, 3, 280, 238, 112, 'false'
  );
  
  -- Ayah 116 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2017,
    'وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَـٰذَا حَلَـٰلࣱ وَهَـٰذَا حَرَامࣱ لِّتَفۡتَرُوا۟ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِینَ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا یُفۡلِحُونَ',
    'ولا تقولوا لما تصف السنتكم الكذب هذا حلال وهذا حرام لتفتروا على الله الكذب ان الذين يفترون على الله الكذب لا يفلحون',
    'وَلَا تَقُولُو<rule class=slnt>اۡ</rule> لِمَا تَصِفُ أَلۡسِنَتُكُمُ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ هَ<rule class=madda_normal>ـٰ</rule>ذَا حَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>و</rule>َهَ<rule class=madda_normal>ـٰ</rule>ذَا حَرَا<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتَفۡتَرُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَفۡتَرُونَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ لَا يُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١١٦',
    116, 14, 3, 280, 238, 112, 'false'
  );
  
  -- Ayah 117 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2018,
    'مَتَـٰعࣱ قَلِیلࣱ وَلَهُمۡ عَذَابٌ أَلِیمࣱ',
    'متاع قليل ولهم عذاب اليم',
    'مَتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>عٌ</rule> <rule class=ikhafa>ق</rule>َلِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١١٧',
    117, 14, 3, 280, 238, 112, 'false'
  );
  
  -- Ayah 118 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2019,
    'وَعَلَى ٱلَّذِینَ هَادُوا۟ حَرَّمۡنَا مَا قَصَصۡنَا عَلَیۡكَ مِن قَبۡلُۖ وَمَا ظَلَمۡنَـٰهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'وعلى الذين هادوا حرمنا ما قصصنا عليك من قبل وما ظلمناهم ولكن كانوا انفسهم يظلمون',
    'وَعَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَادُو<rule class=slnt>اۡ</rule> حَرَّمۡنَا مَا قَصَصۡنَا عَلَيۡكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ وَمَا ظَلَمۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ١١٨',
    118, 14, 3, 280, 238, 112, 'false'
  );
  
  -- Ayah 119 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2020,
    'ثُمَّ إِنَّ رَبَّكَ لِلَّذِینَ عَمِلُوا۟ ٱلسُّوۤءَ بِجَهَـٰلَةࣲ ثُمَّ تَابُوا۟ مِنۢ بَعۡدِ ذَ ٰ⁠لِكَ وَأَصۡلَحُوۤا۟ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِیمٌ',
    'ثم ان ربك للذين عملوا السوء بجهالة ثم تابوا من بعد ذلك واصلحوا ان ربك من بعدها لغفور رحيم',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لِلَّذِينَ عَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ بِجَهَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ تَابُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ وَأَصۡلَح<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهَا لَغَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١١٩',
    119, 14, 3, 281, 238, 112, 'false'
  );
  
  -- Ayah 120 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2021,
    'إِنَّ إِبۡرَ ٰ⁠هِیمَ كَانَ أُمَّةࣰ قَانِتࣰا لِّلَّهِ حَنِیفࣰا وَلَمۡ یَكُ مِنَ ٱلۡمُشۡرِكِینَ',
    'ان ابراهيم كان امة قانتا لله حنيفا ولم يك من المشركين',
    'إِ<rule class=ghunnah>نّ</rule>َ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ كَانَ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ق</rule>َانِ<rule class=idgham_wo_ghunnah>تًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّهِ حَنِي<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ يَكُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١٢٠',
    120, 14, 3, 281, 239, 112, 'false'
  );
  
  -- Ayah 121 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2022,
    'شَاكِرࣰا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'شاكرا لانعمه اجتباه وهداه الى صراط مستقيم',
    'شَاكِ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأَنۡعُمِهِ‌ۚ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَبَ<rule class=madda_normal>ـٰ</rule>هُ وَهَدَ<rule class=madda_normal>ٮٰ</rule>هُ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ١٢١',
    121, 14, 3, 281, 239, 112, 'false'
  );
  
  -- Ayah 122 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2023,
    'وَءَاتَیۡنَـٰهُ فِی ٱلدُّنۡیَا حَسَنَةࣰۖ وَإِنَّهُۥ فِی ٱلۡـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِینَ',
    'واتيناه في الدنيا حسنة وانه في الاخرة لمن الصالحين',
    'وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا حَسَنَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ١٢٢',
    122, 14, 3, 281, 239, 112, 'false'
  );
  
  -- Ayah 123 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2024,
    'ثُمَّ أَوۡحَیۡنَاۤ إِلَیۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَ ٰ⁠هِیمَ حَنِیفࣰاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ',
    'ثم اوحينا اليك ان اتبع ملة ابراهيم حنيفا وما كان من المشركين',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ أَنِ <rule class=ham_wasl>ٱ</rule>تَّبِعۡ مِلَّةَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ حَنِي<rule class=idgham_ghunnah>فًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ١٢٣',
    123, 14, 3, 281, 239, 112, 'false'
  );
  
  -- Ayah 124 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2025,
    'إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِینَ ٱخۡتَلَفُوا۟ فِیهِۚ وَإِنَّ رَبَّكَ لَیَحۡكُمُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ',
    'انما جعل السبت على الذين اختلفوا فيه وان ربك ليحكم بينهم يوم القيامة فيما كانوا فيه يختلفون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا جُعِلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=qalaqah>بۡ</rule>تُ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>خۡتَلَفُو<rule class=slnt>اۡ</rule> فِيهِ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فِيمَا كَانُو<rule class=slnt>اۡ</rule> فِيهِ يَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ١٢٤',
    124, 14, 3, 281, 239, 112, 'false'
  );
  
  -- Ayah 125 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2026,
    'ٱدۡعُ إِلَىٰ سَبِیلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَـٰدِلۡهُم بِٱلَّتِی هِیَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ',
    'ادع الى سبيل ربك بالحكمة والموعظة الحسنة وجادلهم بالتي هي احسن ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين',
    'ٱ<rule class=qalaqah>دۡ</rule>عُ إِلَىٰ سَبِيلِ رَبِّكَ بِ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَوۡعِظَةِ <rule class=ham_wasl>ٱ</rule>لۡحَسَنَةِ‌ۖ وَجَ<rule class=madda_normal>ـٰ</rule>دِلۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لَّتِى هِىَ أَحۡسَنُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ أَعۡلَمُ بِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَهُوَ أَعۡلَمُ بِ<rule class=ham_wasl>ٱ</rule>لۡمُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ١٢٥',
    125, 14, 3, 281, 239, 112, 'false'
  );
  
  -- Ayah 126 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2027,
    'وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُوا۟ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَىِٕن صَبَرۡتُمۡ لَهُوَ خَیۡرࣱ لِّلصَّـٰبِرِینَ',
    'وان عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم لهو خير للصابرين',
    'وَإِنۡ عَاقَ<rule class=qalaqah>بۡ</rule>تُمۡ فَعَاقِبُو<rule class=slnt>اۡ</rule> بِمِثۡلِ مَا عُوقِ<rule class=qalaqah>بۡ</rule>ت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َبَرۡتُمۡ لَهُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلصَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ١٢٦',
    126, 14, 3, 281, 239, 112, 'false'
  );
  
  -- Ayah 127 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2028,
    'وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَیۡهِمۡ وَلَا تَكُ فِی ضَیۡقࣲ مِّمَّا یَمۡكُرُونَ',
    'واصبر وما صبرك الا بالله ولا تحزن عليهم ولا تك في ضيق مما يمكرون',
    'وَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ وَمَا صَ<rule class=qalaqah>بۡ</rule>رُكَ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِى ضَيۡ<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَمۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٢٧',
    127, 14, 3, 281, 239, 112, 'false'
  );
  
  -- Ayah 128 Surah An-Nahl
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    16,
    2029,
    'إِنَّ ٱللَّهَ مَعَ ٱلَّذِینَ ٱتَّقَوا۟ وَّٱلَّذِینَ هُم مُّحۡسِنُونَ',
    'ان الله مع الذين اتقوا والذين هم محسنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَعَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَو<rule class=slnt>اۡ</rule> وَّ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّحۡسِن<rule class=madda_permissible>ُو</rule>نَ ١٢٨',
    128, 14, 3, 281, 239, 112, 'false'
  );
  

-- Surah Al-Israa
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (17, 'سُورَةُ الإِسۡرَاءِ', 'Al-Israa', 'The Night Journey', 'Meccan', 111);

  -- Ayah 1 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2030,
    'سُبۡحَـٰنَ ٱلَّذِیۤ أَسۡرَىٰ بِعَبۡدِهِۦ لَیۡلࣰا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِی بَـٰرَكۡنَا حَوۡلَهُۥ لِنُرِیَهُۥ مِنۡ ءَایَـٰتِنَاۤۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ',
    'سبحان الذي اسرى بعبده ليلا من المسجد الحرام الى المسجد الاقصى الذي باركنا حوله لنريه من اياتنا انه هو السميع البصير',
    'سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَسۡرَىٰ بِعَ<rule class=qalaqah>بۡ</rule>دِه<rule class=madda_normal>ِۦ</rule> لَيۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ إِلَى <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>صَا <rule class=ham_wasl>ٱ</rule>لَّذِى بَ<rule class=madda_normal>ـٰ</rule>رَكۡنَا حَوۡلَهُ<rule class=madda_normal>ۥ</rule> لِنُرِيَهُ<rule class=madda_normal>ۥ</rule> مِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡبَص<rule class=madda_permissible>ِي</rule>رُ ١',
    1, 15, 4, 282, 240, 113, 'false'
  );
  
  -- Ayah 2 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2031,
    'وَءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَجَعَلۡنَـٰهُ هُدࣰى لِّبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِی وَكِیلࣰا',
    'واتينا موسى الكتاب وجعلناه هدى لبني اسرائيل الا تتخذوا من دوني وكيلا',
    'وَءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ هُ<rule class=idgham_wo_ghunnah>دًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّبَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ أَلَّا تَتَّخِذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِى وَكِيلاً ٢',
    2, 15, 4, 282, 240, 113, 'false'
  );
  
  -- Ayah 3 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2032,
    'ذُرِّیَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدࣰا شَكُورࣰا',
    'ذرية من حملنا مع نوح انه كان عبدا شكورا',
    'ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ عَ<rule class=qalaqah>بۡ</rule><rule class=ikhafa>دًا</rule> <rule class=ikhafa>ش</rule>َكُورًا ٣',
    3, 15, 4, 282, 240, 113, 'false'
  );
  
  -- Ayah 4 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2033,
    'وَقَضَیۡنَاۤ إِلَىٰ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ فِی ٱلۡكِتَـٰبِ لَتُفۡسِدُنَّ فِی ٱلۡأَرۡضِ مَرَّتَیۡنِ وَلَتَعۡلُنَّ عُلُوࣰّا كَبِیرࣰا',
    'وقضينا الى بني اسرائيل في الكتاب لتفسدن في الارض مرتين ولتعلن علوا كبيرا',
    'وَقَضَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَتُفۡسِدُ<rule class=ghunnah>نّ</rule>َ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُ<rule class=ghunnah>نّ</rule>َ عُلُو<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٤',
    4, 15, 4, 282, 240, 113, 'false'
  );
  
  -- Ayah 5 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2034,
    'فَإِذَا جَاۤءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَیۡكُمۡ عِبَادࣰا لَّنَاۤ أُو۟لِی بَأۡسࣲ شَدِیدࣲ فَجَاسُوا۟ خِلَـٰلَ ٱلدِّیَارِۚ وَكَانَ وَعۡدࣰا مَّفۡعُولࣰا',
    'فاذا جاء وعد اولاهما بعثنا عليكم عبادا لنا اولي باس شديد فجاسوا خلال الديار وكان وعدا مفعولا',
    'فَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَعۡدُ أُولَ<rule class=madda_normal>ـٰ</rule>هُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَا<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّن<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لِى بَأۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>َجَاسُو<rule class=slnt>اۡ</rule> خِلَ<rule class=madda_normal>ـٰ</rule>لَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّيَارِ‌ۚ وَكَانَ وَعۡ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>َّفۡعُولاً ٥',
    5, 15, 4, 282, 240, 113, 'false'
  );
  
  -- Ayah 6 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2035,
    'ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَیۡهِمۡ وَأَمۡدَدۡنَـٰكُم بِأَمۡوَ ٰ⁠لࣲ وَبَنِینَ وَجَعَلۡنَـٰكُمۡ أَكۡثَرَ نَفِیرًا',
    'ثم رددنا لكم الكرة عليهم وامددناكم باموال وبنين وجعلناكم اكثر نفيرا',
    'ثُ<rule class=ghunnah>مّ</rule>َ رَدَ<rule class=qalaqah>دۡ</rule>نَا لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَمۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َبَنِينَ وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ أَكۡثَرَ نَفِيرًا ٦',
    6, 15, 4, 282, 240, 113, 'false'
  );
  
  -- Ayah 7 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2036,
    'إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَاۤءَ وَعۡدُ ٱلۡـَٔاخِرَةِ لِیَسُـࣳۤـُٔوا۟ وُجُوهَكُمۡ وَلِیَدۡخُلُوا۟ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةࣲ وَلِیُتَبِّرُوا۟ مَا عَلَوۡا۟ تَتۡبِیرًا',
    'ان احسنتم احسنتم لانفسكم وان اساتم فلها فاذا جاء وعد الاخرة ليسوءوا وجوهكم وليدخلوا المسجد كما دخلوه اول مرة وليتبروا ما علوا تتبيرا',
    'إِنۡ أَحۡسَ<rule class=ikhafa>نت</rule>ُمۡ أَحۡسَ<rule class=ikhafa>نت</rule>ُمۡ لِأَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَا‌ۚ فَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَعۡدُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ لِيَسُ<rule class=madda_normal>ــۥٓ</rule>ــُٔو<rule class=slnt>اۡ</rule> وُجُوهَكُمۡ وَلِيَ<rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلِيُتَبِّرُو<rule class=slnt>اۡ</rule> مَا عَلَوۡ<rule class=slnt>اۡ</rule> تَتۡبِيرًا ٧',
    7, 15, 4, 282, 240, 113, 'false'
  );
  
  -- Ayah 8 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2037,
    'عَسَىٰ رَبُّكُمۡ أَن یَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَـٰفِرِینَ حَصِیرًا',
    'عسى ربكم ان يرحمكم وان عدتم عدنا وجعلنا جهنم للكافرين حصيرا',
    'عَسَىٰ رَبُّكُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َرۡحَمَكُمۡ‌ۚ وَإِنۡ عُ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ عُ<rule class=qalaqah>دۡ</rule>نَا‌ۘ وَجَعَلۡنَا جَهَ<rule class=ghunnah>نّ</rule>َمَ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ حَصِيرًا ٨',
    8, 15, 4, 283, 240, 113, 'false'
  );
  
  -- Ayah 9 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2038,
    'إِنَّ هَـٰذَا ٱلۡقُرۡءَانَ یَهۡدِی لِلَّتِی هِیَ أَقۡوَمُ وَیُبَشِّرُ ٱلۡمُؤۡمِنِینَ ٱلَّذِینَ یَعۡمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمۡ أَجۡرࣰا كَبِیرࣰا',
    'ان هذا القران يهدي للتي هي اقوم ويبشر المؤمنين الذين يعملون الصالحات ان لهم اجرا كبيرا',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ يَهۡدِى لِلَّتِى هِىَ أَ<rule class=qalaqah>قۡ</rule>وَمُ وَيُبَشِّرُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَعۡمَلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ أَ<rule class=ghunnah>نّ</rule>َ لَهُمۡ أَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٩',
    9, 15, 4, 283, 240, 113, 'false'
  );
  
  -- Ayah 10 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2039,
    'وَأَنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِیمࣰا',
    'وان الذين لا يؤمنون بالاخرة اعتدنا لهم عذابا اليما',
    'وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ أَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لَهُمۡ عَذَابًا أَلِيمًا ١٠',
    10, 15, 4, 283, 240, 113, 'false'
  );
  
  -- Ayah 11 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2040,
    'وَیَدۡعُ ٱلۡإِنسَـٰنُ بِٱلشَّرِّ دُعَاۤءَهُۥ بِٱلۡخَیۡرِۖ وَكَانَ ٱلۡإِنسَـٰنُ عَجُولࣰا',
    'ويدع الانسان بالشر دعاءه بالخير وكان الانسان عجولا',
    'وَيَ<rule class=qalaqah>دۡ</rule>عُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّرِّ دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ‌ۖ وَكَانَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ عَجُولاً ١١',
    11, 15, 4, 283, 241, 113, 'false'
  );
  
  -- Ayah 12 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2041,
    'وَجَعَلۡنَا ٱلَّیۡلَ وَٱلنَّهَارَ ءَایَتَیۡنِۖ فَمَحَوۡنَاۤ ءَایَةَ ٱلَّیۡلِ وَجَعَلۡنَاۤ ءَایَةَ ٱلنَّهَارِ مُبۡصِرَةࣰ لِّتَبۡتَغُوا۟ فَضۡلࣰا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُوا۟ عَدَدَ ٱلسِّنِینَ وَٱلۡحِسَابَۚ وَكُلَّ شَیۡءࣲ فَصَّلۡنَـٰهُ تَفۡصِیلࣰا',
    'وجعلنا الليل والنهار ايتين فمحونا اية الليل وجعلنا اية النهار مبصرة لتبتغوا فضلا من ربكم ولتعلموا عدد السنين والحساب وكل شيء فصلناه تفصيلا',
    'وَجَعَلۡنَا <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ ءَايَتَيۡنِ‌ۖ فَمَحَوۡن<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَةَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَجَعَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ مُ<rule class=qalaqah>بۡ</rule>صِرَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتَ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> فَضۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَلِتَعۡلَمُو<rule class=slnt>اۡ</rule> عَدَدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِسَابَ‌ۚ وَكُلَّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َصَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُ تَفۡصِيلاً ١٢',
    12, 15, 4, 283, 241, 113, 'false'
  );
  
  -- Ayah 13 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2042,
    'وَكُلَّ إِنسَـٰنٍ أَلۡزَمۡنَـٰهُ طَـٰۤىِٕرَهُۥ فِی عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ كِتَـٰبࣰا یَلۡقَىٰهُ مَنشُورًا',
    'وكل انسان الزمناه طائره في عنقه ونخرج له يوم القيامة كتابا يلقاه منشورا',
    'وَكُلَّ إِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نٍ أَلۡزَمۡنَ<rule class=madda_normal>ـٰ</rule>هُ طَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرَهُ<rule class=madda_normal>ۥ</rule> فِى عُنُقِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَنُخۡرِجُ لَهُ<rule class=madda_normal>ۥ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>ي</rule>َلۡقَ<rule class=madda_normal>ـٰ</rule>هُ مَ<rule class=ikhafa>نش</rule>ُورًا ١٣',
    13, 15, 4, 283, 241, 113, 'false'
  );
  
  -- Ayah 14 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2043,
    'ٱقۡرَأۡ كِتَـٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡیَوۡمَ عَلَیۡكَ حَسِیبࣰا',
    'اقرا كتابك كفى بنفسك اليوم عليك حسيبا',
    'ٱ<rule class=qalaqah>قۡ</rule>رَأۡ كِتَ<rule class=madda_normal>ـٰ</rule>بَكَ كَفَىٰ بِنَفۡسِكَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ عَلَيۡكَ حَسِيبًا ١٤',
    14, 15, 4, 283, 241, 113, 'false'
  );
  
  -- Ayah 15 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2044,
    'مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا یَهۡتَدِی لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا یَضِلُّ عَلَیۡهَاۚ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِینَ حَتَّىٰ نَبۡعَثَ رَسُولࣰا',
    'من اهتدى فانما يهتدي لنفسه ومن ضل فانما يضل عليها ولا تزر وازرة وزر اخرى وما كنا معذبين حتى نبعث رسولا',
    'مَّنِ <rule class=ham_wasl>ٱ</rule>هۡتَدَىٰ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَهۡتَدِى لِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَّ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَضِلُّ عَلَيۡهَا‌ۚ وَلَا تَزِرُ وَازِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>ِزۡرَ أُخۡرَىٰ‌ۗ وَمَا كُ<rule class=ghunnah>نّ</rule>َا مُعَذِّبِينَ حَتَّىٰ نَ<rule class=qalaqah>بۡ</rule>عَثَ رَسُولاً ١٥',
    15, 15, 4, 283, 241, 113, 'false'
  );
  
  -- Ayah 16 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2045,
    'وَإِذَاۤ أَرَدۡنَاۤ أَن نُّهۡلِكَ قَرۡیَةً أَمَرۡنَا مُتۡرَفِیهَا فَفَسَقُوا۟ فِیهَا فَحَقَّ عَلَیۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَـٰهَا تَدۡمِیرࣰا',
    'واذا اردنا ان نهلك قرية امرنا مترفيها ففسقوا فيها فحق عليها القول فدمرناها تدميرا',
    'وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَرَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُو<rule class=slnt>اۡ</rule> فِيهَا فَحَقَّ عَلَيۡهَا <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ فَدَ<rule class=ghunnah>مّ</rule>َرۡنَ<rule class=madda_normal>ـٰ</rule>هَا تَ<rule class=qalaqah>دۡ</rule>مِيرًا ١٦',
    16, 15, 4, 283, 241, 113, 'false'
  );
  
  -- Ayah 17 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2046,
    'وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحࣲۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِیرَۢا بَصِیرࣰا',
    'وكم اهلكنا من القرون من بعد نوح وكفى بربك بذنوب عباده خبيرا بصيرا',
    'وَكَمۡ أَهۡلَكۡنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡقُرُونِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ نُو<rule class=idgham_ghunnah>حٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِه<rule class=madda_normal>ِۦ</rule> خَبِير<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َصِيرًا ١٧',
    17, 15, 4, 283, 241, 113, 'false'
  );
  
  -- Ayah 18 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2047,
    'مَّن كَانَ یُرِیدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِیهَا مَا نَشَاۤءُ لِمَن نُّرِیدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ یَصۡلَىٰهَا مَذۡمُومࣰا مَّدۡحُورࣰا',
    'من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا',
    'مَّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يُرِيدُ <rule class=ham_wasl>ٱ</rule>لۡعَاجِلَةَ عَجَّلۡنَا لَهُ<rule class=madda_normal>ۥ</rule> فِيهَا مَا نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّرِيدُ ثُ<rule class=ghunnah>مّ</rule>َ جَعَلۡنَا لَهُ<rule class=madda_normal>ۥ</rule> جَهَ<rule class=ghunnah>نّ</rule>َمَ يَصۡلَ<rule class=madda_normal>ـٰ</rule>هَا مَذۡمُو<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>دۡ</rule>حُورًا ١٨',
    18, 15, 4, 284, 241, 113, 'false'
  );
  
  -- Ayah 19 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2048,
    'وَمَنۡ أَرَادَ ٱلۡـَٔاخِرَةَ وَسَعَىٰ لَهَا سَعۡیَهَا وَهُوَ مُؤۡمِنࣱ فَأُو۟لَـٰۤىِٕكَ كَانَ سَعۡیُهُم مَّشۡكُورࣰا',
    'ومن اراد الاخرة وسعى لها سعيها وهو مؤمن فاولئك كان سعيهم مشكورا',
    'وَمَنۡ أَرَادَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ كَانَ سَعۡيُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّشۡكُورًا ١٩',
    19, 15, 4, 284, 241, 113, 'false'
  );
  
  -- Ayah 20 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2049,
    'كُلࣰّا نُّمِدُّ هَـٰۤؤُلَاۤءِ وَهَـٰۤؤُلَاۤءِ مِنۡ عَطَاۤءِ رَبِّكَۚ وَمَا كَانَ عَطَاۤءُ رَبِّكَ مَحۡظُورًا',
    'كلا نمد هؤلاء وهؤلاء من عطاء ربك وما كان عطاء ربك محظورا',
    'كُل<rule class=idgham_ghunnah>اًّ</rule> <rule class=idgham_ghunnah>ن</rule>ُّمِدُّ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَهَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مِنۡ عَط<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رَبِّكَ‌ۚ وَمَا كَانَ عَط<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ رَبِّكَ مَحۡظُورًا ٢٠',
    20, 15, 4, 284, 241, 113, 'false'
  );
  
  -- Ayah 21 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2050,
    'ٱنظُرۡ كَیۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲۚ وَلَلۡـَٔاخِرَةُ أَكۡبَرُ دَرَجَـٰتࣲ وَأَكۡبَرُ تَفۡضِیلࣰا',
    'انظر كيف فضلنا بعضهم على بعض وللاخرة اكبر درجات واكبر تفضيلا',
    'ٱ<rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَلۡأَخِرَةُ أَكۡبَرُ دَرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَكۡبَرُ تَفۡضِيلاً ٢١',
    21, 15, 4, 284, 241, 113, 'false'
  );
  
  -- Ayah 22 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2051,
    'لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومࣰا مَّخۡذُولࣰا',
    'لا تجعل مع الله الها اخر فتقعد مذموما مخذولا',
    'لَّا تَ<rule class=qalaqah>جۡ</rule>عَلۡ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ فَتَ<rule class=qalaqah>قۡ</rule>عُدَ مَذۡمُو<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّخۡذُولاً ٢٢',
    22, 15, 4, 284, 241, 113, 'false'
  );
  
  -- Ayah 23 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2052,
    '۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوۤا۟ إِلَّاۤ إِیَّاهُ وَبِٱلۡوَ ٰ⁠لِدَیۡنِ إِحۡسَـٰنًاۚ إِمَّا یَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَاۤ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَاۤ أُفࣲّ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلࣰا كَرِیمࣰا',
    'وقضى ربك الا تعبدوا الا اياه وبالوالدين احسانا اما يبلغن عندك الكبر احدهما او كلاهما فلا تقل لهما اف ولا تنهرهما وقل لهما قولا كريما',
    '۞وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِيَّاهُ وَبِ<rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>لِدَيۡنِ إِحۡسَ<rule class=madda_normal>ـٰ</rule>نًا‌ۚ إِ<rule class=ghunnah>مّ</rule>َا يَ<rule class=qalaqah>بۡ</rule>لُغَ<rule class=ghunnah>نّ</rule>َ عِ<rule class=ikhafa>ند</rule>َكَ <rule class=ham_wasl>ٱ</rule>لۡكِبَرَ أَحَدُهُم<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=idgham_ghunnah>فٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ك</rule>َرِيمًا ٢٣',
    23, 15, 4, 284, 242, 114, 'false'
  );
  
  -- Ayah 24 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2053,
    'وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّیَانِی صَغِیرࣰا',
    'واخفض لهما جناح الذل من الرحمة وقل رب ارحمهما كما ربياني صغيرا',
    'وَ<rule class=ham_wasl>ٱ</rule>خۡفِضۡ لَهُمَا جَنَاحَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذُّلِّ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَةِ وَقُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبِّ <rule class=ham_wasl>ٱ</rule>رۡحَمۡهُمَا كَمَا رَبَّيَانِى صَغِيرًا ٢٤',
    24, 15, 4, 284, 242, 114, 'false'
  );
  
  -- Ayah 25 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2054,
    'رَّبُّكُمۡ أَعۡلَمُ بِمَا فِی نُفُوسِكُمۡۚ إِن تَكُونُوا۟ صَـٰلِحِینَ فَإِنَّهُۥ كَانَ لِلۡأَوَّ ٰ⁠بِینَ غَفُورࣰا',
    'ربكم اعلم بما في نفوسكم ان تكونوا صالحين فانه كان للاوابين غفورا',
    'رَّبُّكُمۡ أَعۡلَمُ بِمَا فِى نُفُوسِكُمۡ‌ۚ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونُو<rule class=slnt>اۡ</rule> صَ<rule class=madda_normal>ـٰ</rule>لِحِينَ فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ لِلۡأَوّ<rule class=madda_normal>ٰ</rule>بِينَ غَفُورًا ٢٥',
    25, 15, 4, 284, 242, 114, 'false'
  );
  
  -- Ayah 26 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2055,
    'وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِینَ وَٱبۡنَ ٱلسَّبِیلِ وَلَا تُبَذِّرۡ تَبۡذِیرًا',
    'وات ذا القربى حقه والمسكين وابن السبيل ولا تبذر تبذيرا',
    'وَءَاتِ ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ حَقَّهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡمِسۡكِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ وَلَا تُبَذِّرۡ تَ<rule class=qalaqah>بۡ</rule>ذِيرًا ٢٦',
    26, 15, 4, 284, 242, 114, 'false'
  );
  
  -- Ayah 27 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2056,
    'إِنَّ ٱلۡمُبَذِّرِینَ كَانُوۤا۟ إِخۡوَ ٰ⁠نَ ٱلشَّیَـٰطِینِۖ وَكَانَ ٱلشَّیۡطَـٰنُ لِرَبِّهِۦ كَفُورࣰا',
    'ان المبذرين كانوا اخوان الشياطين وكان الشيطان لربه كفورا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُبَذِّرِينَ كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِخۡو<rule class=madda_normal>ٰ</rule>نَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينِ‌ۖ وَكَانَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ لِرَبِّه<rule class=madda_normal>ِۦ</rule> كَفُورًا ٢٧',
    27, 15, 4, 284, 242, 114, 'false'
  );
  
  -- Ayah 28 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2057,
    'وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَاۤءَ رَحۡمَةࣲ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلࣰا مَّیۡسُورࣰا',
    'واما تعرضن عنهم ابتغاء رحمة من ربك ترجوها فقل لهم قولا ميسورا',
    'وَإِ<rule class=ghunnah>مّ</rule>َا تُعۡرِضَ<rule class=ghunnah>نّ</rule>َ عَنۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَحۡمَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّيۡسُورًا ٢٨',
    28, 15, 4, 285, 242, 114, 'false'
  );
  
  -- Ayah 29 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2058,
    'وَلَا تَجۡعَلۡ یَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومࣰا مَّحۡسُورًا',
    'ولا تجعل يدك مغلولة الى عنقك ولا تبسطها كل البسط فتقعد ملوما محسورا',
    'وَلَا تَ<rule class=qalaqah>جۡ</rule>عَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَ<rule class=qalaqah>بۡ</rule>سُ<rule class=qalaqah>طۡ</rule>هَا كُلَّ <rule class=ham_wasl>ٱ</rule>لۡبَسۡطِ فَتَ<rule class=qalaqah>قۡ</rule>عُدَ مَلُو<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّحۡسُورًا ٢٩',
    29, 15, 4, 285, 242, 114, 'false'
  );
  
  -- Ayah 30 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2059,
    'إِنَّ رَبَّكَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِیرَۢا بَصِیرࣰا',
    'ان ربك يبسط الرزق لمن يشاء ويقدر انه كان بعباده خبيرا بصيرا',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَ<rule class=qalaqah>قۡ</rule>دِرُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ بِعِبَادِه<rule class=madda_normal>ِۦ</rule> خَبِير<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َصِيرًا ٣٠',
    30, 15, 4, 285, 242, 114, 'false'
  );
  
  -- Ayah 31 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2060,
    'وَلَا تَقۡتُلُوۤا۟ أَوۡلَـٰدَكُمۡ خَشۡیَةَ إِمۡلَـٰقࣲۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِیَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـࣰٔا كَبِیرࣰا',
    'ولا تقتلوا اولادكم خشية املاق نحن نرزقهم واياكم ان قتلهم كان خطئا كبيرا',
    'وَلَا تَ<rule class=qalaqah>قۡ</rule>تُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دَكُمۡ خَشۡيَةَ إِمۡلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>قٍ‌ۖ</rule> <rule class=idgham_ghunnah>ن</rule>َّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ قَتۡلَهُمۡ كَانَ خِ<rule class=qalaqah>طۡ</rule>ـ<rule class=ikhafa>ـًٔا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٣١',
    31, 15, 4, 285, 243, 114, 'false'
  );
  
  -- Ayah 32 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2061,
    'وَلَا تَقۡرَبُوا۟ ٱلزِّنَىٰۤۖ إِنَّهُۥ كَانَ فَـٰحِشَةࣰ وَسَاۤءَ سَبِیلࣰا',
    'ولا تقربوا الزنا انه كان فاحشة وساء سبيلا',
    'وَلَا تَ<rule class=qalaqah>قۡ</rule>رَبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زِّنَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ فَ<rule class=madda_normal>ـٰ</rule>حِشَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ سَبِيلاً ٣٢',
    32, 15, 4, 285, 243, 114, 'false'
  );
  
  -- Ayah 33 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2062,
    'وَلَا تَقۡتُلُوا۟ ٱلنَّفۡسَ ٱلَّتِی حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومࣰا فَقَدۡ جَعَلۡنَا لِوَلِیِّهِۦ سُلۡطَـٰنࣰا فَلَا یُسۡرِف فِّی ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورࣰا',
    'ولا تقتلوا النفس التي حرم الله الا بالحق ومن قتل مظلوما فقد جعلنا لوليه سلطانا فلا يسرف في القتل انه كان منصورا',
    'وَلَا تَ<rule class=qalaqah>قۡ</rule>تُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َفۡسَ <rule class=ham_wasl>ٱ</rule>لَّتِى حَرَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۗ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُتِلَ مَظۡلُو<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َقَ<rule class=qalaqah>دۡ</rule> جَعَلۡنَا لِوَلِيِّه<rule class=madda_normal>ِۦ</rule> سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َلَا يُسۡرِف فِّى <rule class=ham_wasl>ٱ</rule>لۡقَتۡلِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ مَ<rule class=ikhafa>نص</rule>ُورًا ٣٣',
    33, 15, 4, 285, 243, 114, 'false'
  );
  
  -- Ayah 34 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2063,
    'وَلَا تَقۡرَبُوا۟ مَالَ ٱلۡیَتِیمِ إِلَّا بِٱلَّتِی هِیَ أَحۡسَنُ حَتَّىٰ یَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُوا۟ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولࣰا',
    'ولا تقربوا مال اليتيم الا بالتي هي احسن حتى يبلغ اشده واوفوا بالعهد ان العهد كان مسئولا',
    'وَلَا تَ<rule class=qalaqah>قۡ</rule>رَبُو<rule class=slnt>اۡ</rule> مَالَ <rule class=ham_wasl>ٱ</rule>لۡيَتِيمِ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لَّتِى هِىَ أَحۡسَنُ حَتَّىٰ يَ<rule class=qalaqah>بۡ</rule>لُغَ أَشُدَّهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَأَوۡفُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡعَهۡدِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَهۡدَ كَانَ مَسۡــُٔولاً ٣٤',
    34, 15, 4, 285, 243, 114, 'false'
  );
  
  -- Ayah 35 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2064,
    'وَأَوۡفُوا۟ ٱلۡكَیۡلَ إِذَا كِلۡتُمۡ وَزِنُوا۟ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِیمِۚ ذَ ٰ⁠لِكَ خَیۡرࣱ وَأَحۡسَنُ تَأۡوِیلࣰا',
    'واوفوا الكيل اذا كلتم وزنوا بالقسطاس المستقيم ذلك خير واحسن تاويلا',
    'وَأَوۡفُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطَاسِ <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَقِيمِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَحۡسَنُ تَأۡوِيلاً ٣٥',
    35, 15, 4, 285, 243, 114, 'false'
  );
  
  -- Ayah 36 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2065,
    'وَلَا تَقۡفُ مَا لَیۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُو۟لَـٰۤىِٕكَ كَانَ عَنۡهُ مَسۡـُٔولࣰا',
    'ولا تقف ما ليس لك به علم ان السمع والبصر والفؤاد كل اولئك كان عنه مسئولا',
    'وَلَا تَ<rule class=qalaqah>قۡ</rule>فُ مَا لَيۡسَ لَكَ بِه<rule class=madda_normal>ِۦ</rule> عِلۡمٌ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَ<rule class=ham_wasl>ٱ</rule>لۡبَصَرَ وَ<rule class=ham_wasl>ٱ</rule>لۡفُؤَادَ كُلُّ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ كَانَ عَنۡهُ مَسۡــُٔولاً ٣٦',
    36, 15, 4, 285, 243, 114, 'false'
  );
  
  -- Ayah 37 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2066,
    'وَلَا تَمۡشِ فِی ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولࣰا',
    'ولا تمش في الارض مرحا انك لن تخرق الارض ولن تبلغ الجبال طولا',
    'وَلَا تَمۡشِ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مَرَحًا‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َخۡرِقَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>بۡ</rule>لُغَ <rule class=ham_wasl>ٱ</rule>لۡجِبَالَ طُولاً ٣٧',
    37, 15, 4, 285, 243, 114, 'false'
  );
  
  -- Ayah 38 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2067,
    'كُلُّ ذَ ٰ⁠لِكَ كَانَ سَیِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهࣰا',
    'كل ذلك كان سيئه عند ربك مكروها',
    'كُلُّ ذ<rule class=madda_normal>ٰ</rule>لِكَ كَانَ سَيِّئُهُ<rule class=madda_normal>ۥ</rule> عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ مَكۡرُوهًا ٣٨',
    38, 15, 4, 285, 243, 114, 'false'
  );
  
  -- Ayah 39 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2068,
    'ذَ ٰ⁠لِكَ مِمَّاۤ أَوۡحَىٰۤ إِلَیۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتُلۡقَىٰ فِی جَهَنَّمَ مَلُومࣰا مَّدۡحُورًا',
    'ذلك مما اوحى اليك ربك من الحكمة ولا تجعل مع الله الها اخر فتلقى في جهنم ملوما مدحورا',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ مِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَوۡحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡكَ رَبُّكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةِ‌ۗ وَلَا تَ<rule class=qalaqah>جۡ</rule>عَلۡ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ فَتُلۡقَىٰ فِى جَهَ<rule class=ghunnah>نّ</rule>َمَ مَلُو<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>دۡ</rule>حُورًا ٣٩',
    39, 15, 4, 286, 243, 114, 'false'
  );
  
  -- Ayah 40 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2069,
    'أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِینَ وَٱتَّخَذَ مِنَ ٱلۡمَلَـٰۤىِٕكَةِ إِنَـٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِیمࣰا',
    'افاصفاكم ربكم بالبنين واتخذ من الملائكة اناثا انكم لتقولون قولا عظيما',
    'أَفَأَصۡفَ<rule class=madda_normal>ـٰ</rule>كُمۡ رَبُّك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَنِينَ وَ<rule class=ham_wasl>ٱ</rule>تَّخَذَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ إِنَ<rule class=madda_normal>ـٰ</rule>ثًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َكُمۡ لَتَقُولُونَ قَوۡلاً عَظِيمًا ٤٠',
    40, 15, 4, 286, 243, 114, 'false'
  );
  
  -- Ayah 41 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2070,
    'وَلَقَدۡ صَرَّفۡنَا فِی هَـٰذَا ٱلۡقُرۡءَانِ لِیَذَّكَّرُوا۟ وَمَا یَزِیدُهُمۡ إِلَّا نُفُورࣰا',
    'ولقد صرفنا في هذا القران ليذكروا وما يزيدهم الا نفورا',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> صَرَّفۡنَا فِى هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ لِيَذَّكَّرُو<rule class=slnt>اۡ</rule> وَمَا يَزِيدُهُمۡ إِلَّا نُفُورًا ٤١',
    41, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 42 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2071,
    'قُل لَّوۡ كَانَ مَعَهُۥۤ ءَالِهَةࣱ كَمَا یَقُولُونَ إِذࣰا لَّٱبۡتَغَوۡا۟ إِلَىٰ ذِی ٱلۡعَرۡشِ سَبِیلࣰا',
    'قل لو كان معه الهة كما يقولون اذا لابتغوا الى ذي العرش سبيلا',
    'قُل لَّوۡ كَانَ مَعَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> ءَالِهَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ك</rule>َمَا يَقُولُونَ إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغَوۡ<rule class=slnt>اۡ</rule> إِلَىٰ ذِى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ سَبِيلاً ٤٢',
    42, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 43 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2072,
    'سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یَقُولُونَ عُلُوࣰّا كَبِیرࣰا',
    'سبحانه وتعالى عما يقولون علوا كبيرا',
    'سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> وَتَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يَقُولُونَ عُلُو<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٤٣',
    43, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 44 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2073,
    'تُسَبِّحُ لَهُ ٱلسَّمَـٰوَ ٰ⁠تُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِیهِنَّۚ وَإِن مِّن شَیۡءٍ إِلَّا یُسَبِّحُ بِحَمۡدِهِۦ وَلَـٰكِن لَّا تَفۡقَهُونَ تَسۡبِیحَهُمۡۚ إِنَّهُۥ كَانَ حَلِیمًا غَفُورࣰا',
    'تسبح له السماوات السبع والارض ومن فيهن وان من شيء الا يسبح بحمده ولكن لا تفقهون تسبيحهم انه كان حليما غفورا',
    'تُسَبِّحُ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=qalaqah>بۡ</rule>عُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِيهِ<rule class=ghunnah>نّ</rule>َ‌ۚ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِه<rule class=madda_normal>ِۦ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَفۡقَهُونَ تَسۡبِيحَهُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ حَلِيمًا غَفُورًا ٤٤',
    44, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 45 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2074,
    'وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَیۡنَكَ وَبَیۡنَ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ حِجَابࣰا مَّسۡتُورࣰا',
    'واذا قرات القران جعلنا بينك وبين الذين لا يؤمنون بالاخرة حجابا مستورا',
    'وَإِذَا قَرَأۡتَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ حِجَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>َّسۡتُورًا ٤٥',
    45, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 46 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2075,
    'وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن یَفۡقَهُوهُ وَفِیۤ ءَاذَانِهِمۡ وَقۡرࣰاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِی ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡا۟ عَلَىٰۤ أَدۡبَـٰرِهِمۡ نُفُورࣰا',
    'وجعلنا على قلوبهم اكنة ان يفقهوه وفي اذانهم وقرا واذا ذكرت ربك في القران وحده ولوا على ادبارهم نفورا',
    'وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِ<rule class=ghunnah>نّ</rule>َةً أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡقَهُوهُ وَف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاذَانِهِمۡ وَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِذَا ذَكَرۡتَ رَبَّكَ فِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ وَحۡدَهُ<rule class=madda_normal>ۥ</rule> وَلَّوۡ<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ نُفُورًا ٤٦',
    46, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 47 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2076,
    'نَّحۡنُ أَعۡلَمُ بِمَا یَسۡتَمِعُونَ بِهِۦۤ إِذۡ یَسۡتَمِعُونَ إِلَیۡكَ وَإِذۡ هُمۡ نَجۡوَىٰۤ إِذۡ یَقُولُ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلࣰا مَّسۡحُورًا',
    'نحن اعلم بما يستمعون به اذ يستمعون اليك واذ هم نجوى اذ يقول الظالمون ان تتبعون الا رجلا مسحورا',
    'نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَ<rule class=qalaqah>جۡ</rule>وَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذۡ يَقُولُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَّبِعُونَ إِلَّا رَجُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّسۡحُورًا ٤٧',
    47, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 48 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2077,
    'ٱنظُرۡ كَیۡفَ ضَرَبُوا۟ لَكَ ٱلۡأَمۡثَالَ فَضَلُّوا۟ فَلَا یَسۡتَطِیعُونَ سَبِیلࣰا',
    'انظر كيف ضربوا لك الامثال فضلوا فلا يستطيعون سبيلا',
    'ٱ<rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ ضَرَبُو<rule class=slnt>اۡ</rule> لَكَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡثَالَ فَضَلُّو<rule class=slnt>اۡ</rule> فَلَا يَسۡتَطِيعُونَ سَبِيلاً ٤٨',
    48, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 49 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2078,
    'وَقَالُوۤا۟ أَءِذَا كُنَّا عِظَـٰمࣰا وَرُفَـٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقࣰا جَدِیدࣰا',
    'وقالوا ااذا كنا عظاما ورفاتا اانا لمبعوثون خلقا جديدا',
    'وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَءِذَا كُ<rule class=ghunnah>نّ</rule>َا عِظَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َرُفَ<rule class=madda_normal>ـٰ</rule>تًا أَءِ<rule class=ghunnah>نّ</rule>َا لَمَ<rule class=qalaqah>بۡ</rule>عُوثُونَ خَلۡ<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ج</rule>َدِيدًا ٤٩',
    49, 15, 4, 286, 244, 114, 'false'
  );
  
  -- Ayah 50 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2079,
    '۞ قُلۡ كُونُوا۟ حِجَارَةً أَوۡ حَدِیدًا',
    'قل كونوا حجارة او حديدا',
    '۞قُلۡ كُونُو<rule class=slnt>اۡ</rule> حِجَارَةً أَوۡ حَدِيدًا ٥٠',
    50, 15, 4, 287, 244, 115, 'false'
  );
  
  -- Ayah 51 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2080,
    'أَوۡ خَلۡقࣰا مِّمَّا یَكۡبُرُ فِی صُدُورِكُمۡۚ فَسَیَقُولُونَ مَن یُعِیدُنَاۖ قُلِ ٱلَّذِی فَطَرَكُمۡ أَوَّلَ مَرَّةࣲۚ فَسَیُنۡغِضُونَ إِلَیۡكَ رُءُوسَهُمۡ وَیَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰۤ أَن یَكُونَ قَرِیبࣰا',
    'او خلقا مما يكبر في صدوركم فسيقولون من يعيدنا قل الذي فطركم اول مرة فسينغضون اليك رءوسهم ويقولون متى هو قل عسى ان يكون قريبا',
    'أَوۡ خَلۡ<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَكۡبُرُ فِى صُدُورِكُمۡ‌ۚ فَسَيَقُولُونَ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعِيدُنَا‌ۖ قُلِ <rule class=ham_wasl>ٱ</rule>لَّذِى فَطَرَكُمۡ أَوَّلَ مَرَّ<rule class=ikhafa>ةٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَ‌ۖ قُلۡ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ قَرِيبًا ٥١',
    51, 15, 4, 287, 244, 115, 'false'
  );
  
  -- Ayah 52 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2081,
    'یَوۡمَ یَدۡعُوكُمۡ فَتَسۡتَجِیبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِیلࣰا',
    'يوم يدعوكم فتستجيبون بحمده وتظنون ان لبثتم الا قليلا',
    'يَوۡمَ يَ<rule class=qalaqah>دۡ</rule>عُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِه<rule class=madda_normal>ِۦ</rule> وَتَظُ<rule class=ghunnah>نّ</rule>ُونَ إ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّبِثۡتُمۡ إِلَّا قَلِيلاً ٥٢',
    52, 15, 4, 287, 244, 115, 'false'
  );
  
  -- Ayah 53 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2082,
    'وَقُل لِّعِبَادِی یَقُولُوا۟ ٱلَّتِی هِیَ أَحۡسَنُۚ إِنَّ ٱلشَّیۡطَـٰنَ یَنزَغُ بَیۡنَهُمۡۚ إِنَّ ٱلشَّیۡطَـٰنَ كَانَ لِلۡإِنسَـٰنِ عَدُوࣰّا مُّبِینࣰا',
    'وقل لعبادي يقولوا التي هي احسن ان الشيطان ينزغ بينهم ان الشيطان كان للانسان عدوا مبينا',
    'وَقُل لِّعِبَادِى يَقُولُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّتِى هِىَ أَحۡسَنُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ يَ<rule class=ikhafa>نز</rule>َغُ بَيۡنَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ كَانَ لِلۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ عَدُو<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ٥٣',
    53, 15, 4, 287, 245, 115, 'false'
  );
  
  -- Ayah 54 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2083,
    'رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن یَشَأۡ یَرۡحَمۡكُمۡ أَوۡ إِن یَشَأۡ یُعَذِّبۡكُمۡۚ وَمَاۤ أَرۡسَلۡنَـٰكَ عَلَیۡهِمۡ وَكِیلࣰا',
    'ربكم اعلم بكم ان يشا يرحمكم او ان يشا يعذبكم وما ارسلناك عليهم وكيلا',
    'رَّبُّكُمۡ أَعۡلَمُ بِكُمۡ‌ۖ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َشَأۡ يَرۡحَمۡكُمۡ أَوۡ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َشَأۡ يُعَذِّ<rule class=qalaqah>بۡ</rule>كُمۡ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ عَلَيۡهِمۡ وَكِيلاً ٥٤',
    54, 15, 4, 287, 245, 115, 'false'
  );
  
  -- Ayah 55 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2084,
    'وَرَبُّكَ أَعۡلَمُ بِمَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِیِّـۧنَ عَلَىٰ بَعۡضࣲۖ وَءَاتَیۡنَا دَاوُۥدَ زَبُورࣰا',
    'وربك اعلم بمن في السماوات والارض ولقد فضلنا بعض النبيين على بعض واتينا داوود زبورا',
    'وَرَبُّكَ أَعۡلَمُ بِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَلَقَ<rule class=qalaqah>دۡ</rule> فَضَّلۡنَا بَعۡضَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ عَلَىٰ بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َءَاتَيۡنَا دَاوُ<rule class=madda_normal>ۥ</rule>دَ زَبُورًا ٥٥',
    55, 15, 4, 287, 245, 115, 'false'
  );
  
  -- Ayah 56 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2085,
    'قُلِ ٱدۡعُوا۟ ٱلَّذِینَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا یَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِیلًا',
    'قل ادعوا الذين زعمتم من دونه فلا يملكون كشف الضر عنكم ولا تحويلا',
    'قُلِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ زَعَمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> فَلَا يَمۡلِكُونَ كَشۡفَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّرِّ عَ<rule class=ikhafa>نك</rule>ُمۡ وَلَا تَحۡوِيلاً ٥٦',
    56, 15, 4, 287, 245, 115, 'false'
  );
  
  -- Ayah 57 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2086,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ یَدۡعُونَ یَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِیلَةَ أَیُّهُمۡ أَقۡرَبُ وَیَرۡجُونَ رَحۡمَتَهُۥ وَیَخَافُونَ عَذَابَهُۥۤۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورࣰا',
    'اولئك الذين يدعون يبتغون الى ربهم الوسيلة ايهم اقرب ويرجون رحمته ويخافون عذابه ان عذاب ربك كان محذورا',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ يَ<rule class=qalaqah>بۡ</rule>تَغُونَ إِلَىٰ رَبِّهِمُ <rule class=ham_wasl>ٱ</rule>لۡوَسِيلَةَ أَيُّهُمۡ أَ<rule class=qalaqah>قۡ</rule>رَبُ وَيَرۡجُونَ رَحۡمَتَهُ<rule class=madda_normal>ۥ</rule> وَيَخَافُونَ عَذَابَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ عَذَابَ رَبِّكَ كَانَ مَحۡذُورًا ٥٧',
    57, 15, 4, 287, 245, 115, 'false'
  );
  
  -- Ayah 58 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2087,
    'وَإِن مِّن قَرۡیَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ یَوۡمِ ٱلۡقِیَـٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابࣰا شَدِیدࣰاۚ كَانَ ذَ ٰ⁠لِكَ فِی ٱلۡكِتَـٰبِ مَسۡطُورࣰا',
    'وان من قرية الا نحن مهلكوها قبل يوم القيامة او معذبوها عذابا شديدا كان ذلك في الكتاب مسطورا',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَ<rule class=qalaqah>بۡ</rule>لَ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ أَوۡ مُعَذِّبُوهَا عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=ikhafa>دًا‌ۚ</rule> <rule class=ikhafa>ك</rule>َانَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مَسۡطُورًا ٥٨',
    58, 15, 4, 287, 245, 115, 'false'
  );
  
  -- Ayah 59 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2088,
    'وَمَا مَنَعَنَاۤ أَن نُّرۡسِلَ بِٱلۡـَٔایَـٰتِ إِلَّاۤ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَیۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةࣰ فَظَلَمُوا۟ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡـَٔایَـٰتِ إِلَّا تَخۡوِیفࣰا',
    'وما منعنا ان نرسل بالايات الا ان كذب بها الاولون واتينا ثمود الناقة مبصرة فظلموا بها وما نرسل بالايات الا تخويفا',
    'وَمَا مَنَعَن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّرۡسِلَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبَ بِهَا <rule class=ham_wasl>ٱ</rule>لۡأَوَّلُونَ‌ۚ وَءَاتَيۡنَا ثَمُودَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاقَةَ مُ<rule class=qalaqah>بۡ</rule>صِرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َظَلَمُو<rule class=slnt>اۡ</rule> بِهَا‌ۚ وَمَا نُرۡسِلُ بِ<rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ إِلَّا تَخۡوِيفًا ٥٩',
    59, 15, 4, 288, 245, 115, 'false'
  );
  
  -- Ayah 60 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2089,
    'وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡیَا ٱلَّتِیۤ أَرَیۡنَـٰكَ إِلَّا فِتۡنَةࣰ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِی ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا یَزِیدُهُمۡ إِلَّا طُغۡیَـٰنࣰا كَبِیرࣰا',
    'واذ قلنا لك ان ربك احاط بالناس وما جعلنا الرؤيا التي اريناك الا فتنة للناس والشجرة الملعونة في القران ونخوفهم فما يزيدهم الا طغيانا كبيرا',
    'وَإِذۡ قُلۡنَا لَكَ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ أَحَاطَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۚ وَمَا جَعَلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّءۡيَا <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَيۡنَ<rule class=madda_normal>ـٰ</rule>كَ إِلَّا فِتۡنَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرَةَ <rule class=ham_wasl>ٱ</rule>لۡمَلۡعُونَةَ فِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ‌ۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نًا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٦٠',
    60, 15, 4, 288, 245, 115, 'false'
  );
  
  -- Ayah 61 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2090,
    'وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِینࣰا',
    'واذ قلنا للملائكة اسجدوا لادم فسجدوا الا ابليس قال ااسجد لمن خلقت طينا',
    'وَإِذۡ قُلۡنَا لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ <rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> لِأَدَمَ فَسَجَد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>لِيسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَ<rule class=qalaqah>قۡ</rule>تَ طِينًا ٦١',
    61, 15, 4, 288, 246, 115, 'false'
  );
  
  -- Ayah 62 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2091,
    'قَالَ أَرَءَیۡتَكَ هَـٰذَا ٱلَّذِی كَرَّمۡتَ عَلَیَّ لَىِٕنۡ أَخَّرۡتَنِ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّیَّتَهُۥۤ إِلَّا قَلِیلࣰا',
    'قال ارايتك هذا الذي كرمت علي لئن اخرتن الى يوم القيامة لاحتنكن ذريته الا قليلا',
    'قَالَ أَرَءَيۡتَكَ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى كَرَّمۡتَ عَلَىَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ لَأَحۡتَنِكَ<rule class=ghunnah>نّ</rule>َ ذُرِّيَّتَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا قَلِيلاً ٦٢',
    62, 15, 4, 288, 246, 115, 'false'
  );
  
  -- Ayah 63 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2092,
    'قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ جَهَنَّمَ جَزَاۤؤُكُمۡ جَزَاۤءࣰ مَّوۡفُورࣰا',
    'قال اذهب فمن تبعك منهم فان جهنم جزاؤكم جزاء موفورا',
    'قَالَ <rule class=ham_wasl>ٱ</rule>ذۡهَ<rule class=qalaqah>بۡ</rule> فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبِعَكَ مِنۡهُمۡ فَإِ<rule class=ghunnah>نّ</rule>َ جَهَ<rule class=ghunnah>نّ</rule>َمَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>م</rule>َّوۡفُورًا ٦٣',
    63, 15, 4, 288, 246, 115, 'false'
  );
  
  -- Ayah 64 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2093,
    'وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَیۡهِم بِخَیۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِی ٱلۡأَمۡوَ ٰ⁠لِ وَٱلۡأَوۡلَـٰدِ وَعِدۡهُمۡۚ وَمَا یَعِدُهُمُ ٱلشَّیۡطَـٰنُ إِلَّا غُرُورًا',
    'واستفزز من استطعت منهم بصوتك واجلب عليهم بخيلك ورجلك وشاركهم في الاموال والاولاد وعدهم وما يعدهم الشيطان الا غرورا',
    'وَ<rule class=ham_wasl>ٱ</rule>سۡتَفۡزِزۡ مَنِ <rule class=ham_wasl>ٱ</rule>سۡتَطَعۡتَ مِنۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِصَوۡتِكَ وَأَ<rule class=qalaqah>جۡ</rule>لِ<rule class=qalaqah>بۡ</rule> عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَيۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَمۡو<rule class=madda_normal>ٰ</rule>لِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَوۡلَ<rule class=madda_normal>ـٰ</rule>دِ وَعِ<rule class=qalaqah>دۡ</rule>هُمۡ‌ۚ وَمَا يَعِدُهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ إِلَّا غُرُورًا ٦٤',
    64, 15, 4, 288, 246, 115, 'false'
  );
  
  -- Ayah 65 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2094,
    'إِنَّ عِبَادِی لَیۡسَ لَكَ عَلَیۡهِمۡ سُلۡطَـٰنࣱۚ وَكَفَىٰ بِرَبِّكَ وَكِیلࣰا',
    'ان عبادي ليس لك عليهم سلطان وكفى بربك وكيلا',
    'إِ<rule class=ghunnah>نّ</rule>َ عِبَادِى لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَفَىٰ بِرَبِّكَ وَكِيلاً ٦٥',
    65, 15, 4, 288, 246, 115, 'false'
  );
  
  -- Ayah 66 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2095,
    'رَّبُّكُمُ ٱلَّذِی یُزۡجِی لَكُمُ ٱلۡفُلۡكَ فِی ٱلۡبَحۡرِ لِتَبۡتَغُوا۟ مِن فَضۡلِهِۦۤۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِیمࣰا',
    'ربكم الذي يزجي لكم الفلك في البحر لتبتغوا من فضله انه كان بكم رحيما',
    'رَّبُّكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى يُزۡجِى لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ لِتَ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ بِكُمۡ رَحِيمًا ٦٦',
    66, 15, 4, 288, 246, 115, 'false'
  );
  
  -- Ayah 67 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2096,
    'وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِی ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّاۤ إِیَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَـٰنُ كَفُورًا',
    'واذا مسكم الضر في البحر ضل من تدعون الا اياه فلما نجاكم الى البر اعرضتم وكان الانسان كفورا',
    'وَإِذَا مَسَّكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّرُّ فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ ضَلَّ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>عُونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِيَّاهُ‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا نَجَّ<rule class=madda_normal>ـٰ</rule>كُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡبَرِّ أَعۡرَضۡتُمۡ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ كَفُورًا ٦٧',
    67, 15, 4, 289, 246, 115, 'false'
  );
  
  -- Ayah 68 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2097,
    'أَفَأَمِنتُمۡ أَن یَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ یُرۡسِلَ عَلَیۡكُمۡ حَاصِبࣰا ثُمَّ لَا تَجِدُوا۟ لَكُمۡ وَكِیلًا',
    'افامنتم ان يخسف بكم جانب البر او يرسل عليكم حاصبا ثم لا تجدوا لكم وكيلا',
    'أَفَأَمِ<rule class=ikhafa>نت</rule>ُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡسِفَ بِكُمۡ جَانِبَ <rule class=ham_wasl>ٱ</rule>لۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ لَا تَجِدُو<rule class=slnt>اۡ</rule> لَكُمۡ وَكِيلاً ٦٨',
    68, 15, 4, 289, 246, 115, 'false'
  );
  
  -- Ayah 69 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2098,
    'أَمۡ أَمِنتُمۡ أَن یُعِیدَكُمۡ فِیهِ تَارَةً أُخۡرَىٰ فَیُرۡسِلَ عَلَیۡكُمۡ قَاصِفࣰا مِّنَ ٱلرِّیحِ فَیُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُوا۟ لَكُمۡ عَلَیۡنَا بِهِۦ تَبِیعࣰا',
    'ام امنتم ان يعيدكم فيه تارة اخرى فيرسل عليكم قاصفا من الريح فيغرقكم بما كفرتم ثم لا تجدوا لكم علينا به تبيعا',
    'أَمۡ أَمِ<rule class=ikhafa>نت</rule>ُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعِيدَكُمۡ فِيهِ تَارَةً أُخۡرَىٰ فَيُرۡسِلَ عَلَيۡكُمۡ قَاصِ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيحِ فَيُغۡرِقَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَفَرۡتُمۡ‌ۙ ثُ<rule class=ghunnah>مّ</rule>َ لَا تَجِدُو<rule class=slnt>اۡ</rule> لَكُمۡ عَلَيۡنَا بِه<rule class=madda_normal>ِۦ</rule> تَبِيعًا ٦٩',
    69, 15, 4, 289, 246, 115, 'false'
  );
  
  -- Ayah 70 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2099,
    '۞ وَلَقَدۡ كَرَّمۡنَا بَنِیۤ ءَادَمَ وَحَمَلۡنَـٰهُمۡ فِی ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَـٰهُم مِّنَ ٱلطَّیِّبَـٰتِ وَفَضَّلۡنَـٰهُمۡ عَلَىٰ كَثِیرࣲ مِّمَّنۡ خَلَقۡنَا تَفۡضِیلࣰا',
    'ولقد كرمنا بني ادم وحملناهم في البر والبحر ورزقناهم من الطيبات وفضلناهم على كثير ممن خلقنا تفضيلا',
    '۞وَلَقَ<rule class=qalaqah>دۡ</rule> كَرَّمۡنَا بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَادَمَ وَحَمَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡبَرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ وَرَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ وَفَضَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ عَلَىٰ كَثِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َنۡ خَلَ<rule class=qalaqah>قۡ</rule>نَا تَفۡضِيلاً ٧٠',
    70, 15, 4, 289, 246, 116, 'false'
  );
  
  -- Ayah 71 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2100,
    'یَوۡمَ نَدۡعُوا۟ كُلَّ أُنَاسِۭ بِإِمَـٰمِهِمۡۖ فَمَنۡ أُوتِیَ كِتَـٰبَهُۥ بِیَمِینِهِۦ فَأُو۟لَـٰۤىِٕكَ یَقۡرَءُونَ كِتَـٰبَهُمۡ وَلَا یُظۡلَمُونَ فَتِیلࣰا',
    'يوم ندعو كل اناس بامامهم فمن اوتي كتابه بيمينه فاولئك يقرءون كتابهم ولا يظلمون فتيلا',
    'يَوۡمَ نَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> كُلَّ أُنَا<rule class=iqlab>سِۭ</rule> <rule class=iqlab>ب</rule>ِإِمَ<rule class=madda_normal>ـٰ</rule>مِهِمۡ‌ۖ فَمَنۡ أُوتِىَ كِتَ<rule class=madda_normal>ـٰ</rule>بَهُ<rule class=madda_normal>ۥ</rule> بِيَمِينِه<rule class=madda_normal>ِۦ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَ<rule class=qalaqah>قۡ</rule>رَءُونَ كِتَ<rule class=madda_normal>ـٰ</rule>بَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلاً ٧١',
    71, 15, 4, 289, 247, 116, 'false'
  );
  
  -- Ayah 72 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2101,
    'وَمَن كَانَ فِی هَـٰذِهِۦۤ أَعۡمَىٰ فَهُوَ فِی ٱلۡـَٔاخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِیلࣰا',
    'ومن كان في هذه اعمى فهو في الاخرة اعمى واضل سبيلا',
    'وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ فِى هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَعۡمَىٰ فَهُوَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلاً ٧٢',
    72, 15, 4, 289, 247, 116, 'false'
  );
  
  -- Ayah 73 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2102,
    'وَإِن كَادُوا۟ لَیَفۡتِنُونَكَ عَنِ ٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ لِتَفۡتَرِیَ عَلَیۡنَا غَیۡرَهُۥۖ وَإِذࣰا لَّٱتَّخَذُوكَ خَلِیلࣰا',
    'وان كادوا ليفتنونك عن الذي اوحينا اليك لتفتري علينا غيره واذا لاتخذوك خليلا',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َادُو<rule class=slnt>اۡ</rule> لَيَفۡتِنُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ لِتَفۡتَرِىَ عَلَيۡنَا غَيۡرَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَإِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ham_wasl>ٱ</rule>تَّخَذُوكَ خَلِيلاً ٧٣',
    73, 15, 4, 289, 247, 116, 'false'
  );
  
  -- Ayah 74 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2103,
    'وَلَوۡلَاۤ أَن ثَبَّتۡنَـٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَیۡهِمۡ شَیۡـࣰٔا قَلِیلًا',
    'ولولا ان ثبتناك لقد كدت تركن اليهم شيئا قليلا',
    'وَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َبَّتۡنَ<rule class=madda_normal>ـٰ</rule>كَ لَقَ<rule class=qalaqah>دۡ</rule> كِ<rule class=idgham_mutajanisayn>د</rule>تَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـ<rule class=ikhafa>ـًٔا</rule> <rule class=ikhafa>ق</rule>َلِيلاً ٧٤',
    74, 15, 4, 289, 247, 116, 'false'
  );
  
  -- Ayah 75 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2104,
    'إِذࣰا لَّأَذَقۡنَـٰكَ ضِعۡفَ ٱلۡحَیَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَیۡنَا نَصِیرࣰا',
    'اذا لاذقناك ضعف الحياة وضعف الممات ثم لا تجد لك علينا نصيرا',
    'إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّأَذَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كَ ضِعۡفَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَضِعۡفَ <rule class=ham_wasl>ٱ</rule>لۡمَمَاتِ ثُ<rule class=ghunnah>مّ</rule>َ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرًا ٧٥',
    75, 15, 4, 289, 247, 116, 'false'
  );
  
  -- Ayah 76 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2105,
    'وَإِن كَادُوا۟ لَیَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِیُخۡرِجُوكَ مِنۡهَاۖ وَإِذࣰا لَّا یَلۡبَثُونَ خِلَـٰفَكَ إِلَّا قَلِیلࣰا',
    'وان كادوا ليستفزونك من الارض ليخرجوك منها واذا لا يلبثون خلافك الا قليلا',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َادُو<rule class=slnt>اۡ</rule> لَيَسۡتَفِزُّونَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَا‌ۖ وَإِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَلۡبَثُونَ خِلَ<rule class=madda_normal>ـٰ</rule>فَكَ إِلَّا قَلِيلاً ٧٦',
    76, 15, 4, 290, 247, 116, 'false'
  );
  
  -- Ayah 77 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2106,
    'سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِیلًا',
    'سنة من قد ارسلنا قبلك من رسلنا ولا تجد لسنتنا تحويلا',
    'سُ<rule class=ghunnah>نّ</rule>َةَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا قَ<rule class=qalaqah>بۡ</rule>لَكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّسُلِنَا‌ۖ وَلَا تَجِدُ لِسُ<rule class=ghunnah>نّ</rule>َتِنَا تَحۡوِيلاً ٧٧',
    77, 15, 4, 290, 247, 116, 'false'
  );
  
  -- Ayah 78 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2107,
    'أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّیۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودࣰا',
    'اقم الصلاة لدلوك الشمس الى غسق الليل وقران الفجر ان قران الفجر كان مشهودا',
    'أَقِمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ لِدُلُوكِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسِ إِلَىٰ غَسَقِ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَقُرۡءَانَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=qalaqah>جۡ</rule>رِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ قُرۡءَانَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=qalaqah>جۡ</rule>رِ كَانَ مَشۡهُودًا ٧٨',
    78, 15, 4, 290, 248, 116, 'false'
  );
  
  -- Ayah 79 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2108,
    'وَمِنَ ٱلَّیۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةࣰ لَّكَ عَسَىٰۤ أَن یَبۡعَثَكَ رَبُّكَ مَقَامࣰا مَّحۡمُودࣰا',
    'ومن الليل فتهجد به نافلة لك عسى ان يبعثك ربك مقاما محمودا',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ فَتَهَجَّ<rule class=qalaqah>دۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> نَافِلَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكَ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>عَثَكَ رَبُّكَ مَقَا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّحۡمُودًا ٧٩',
    79, 15, 4, 290, 248, 116, 'false'
  );
  
  -- Ayah 80 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2109,
    'وَقُل رَّبِّ أَدۡخِلۡنِی مُدۡخَلَ صِدۡقࣲ وَأَخۡرِجۡنِی مُخۡرَجَ صِدۡقࣲ وَٱجۡعَل لِّی مِن لَّدُنكَ سُلۡطَـٰنࣰا نَّصِیرࣰا',
    'وقل رب ادخلني مدخل صدق واخرجني مخرج صدق واجعل لي من لدنك سلطانا نصيرا',
    'وَقُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبِّ أَ<rule class=qalaqah>دۡ</rule>خِلۡنِى مُ<rule class=qalaqah>دۡ</rule>خَلَ صِ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَخۡرِ<rule class=qalaqah>جۡ</rule>نِى مُخۡرَجَ صِ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَل لِّى م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ikhafa>نك</rule>َ سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>ن</rule>َّصِيرًا ٨٠',
    80, 15, 4, 290, 248, 116, 'false'
  );
  
  -- Ayah 81 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2110,
    'وَقُلۡ جَاۤءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَـٰطِلُۚ إِنَّ ٱلۡبَـٰطِلَ كَانَ زَهُوقࣰا',
    'وقل جاء الحق وزهق الباطل ان الباطل كان زهوقا',
    'وَقُلۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَزَهَقَ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلَ كَانَ زَهُوقًا ٨١',
    81, 15, 4, 290, 248, 116, 'false'
  );
  
  -- Ayah 82 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2111,
    'وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَاۤءࣱ وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِینَ وَلَا یَزِیدُ ٱلظَّـٰلِمِینَ إِلَّا خَسَارࣰا',
    'وننزل من القران ما هو شفاء ورحمة للمؤمنين ولا يزيد الظالمين الا خسارا',
    'وَنُنَزِّلُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ مَا هُوَ شِف<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُؤۡمِنِينَ‌ۙ وَلَا يَزِيدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ إِلَّا خَسَارًا ٨٢',
    82, 15, 4, 290, 248, 116, 'false'
  );
  
  -- Ayah 83 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2112,
    'وَإِذَاۤ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَـٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ یَـُٔوسࣰا',
    'واذا انعمنا على الانسان اعرض وناى بجانبه واذا مسه الشر كان يئوسا',
    'وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡعَمۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ أَعۡرَضَ وَنَـَٔـا بِجَانِبِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَإِذَا مَسَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّرُّ كَانَ يَــُٔوسًا ٨٣',
    83, 15, 4, 290, 248, 116, 'false'
  );
  
  -- Ayah 84 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2113,
    'قُلۡ كُلࣱّ یَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِیلࣰا',
    'قل كل يعمل على شاكلته فربكم اعلم بمن هو اهدى سبيلا',
    'قُلۡ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلُ عَلَىٰ شَاكِلَتِه<rule class=madda_normal>ِۦ</rule> فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِيلاً ٨٤',
    84, 15, 4, 290, 248, 116, 'false'
  );
  
  -- Ayah 85 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2114,
    'وَیَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّی وَمَاۤ أُوتِیتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِیلࣰا',
    'ويسالونك عن الروح قل الروح من امر ربي وما اوتيتم من العلم الا قليلا',
    'وَيَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّوحِ‌ۖ قُلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّوحُ مِنۡ أَمۡرِ رَبِّى وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِيت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ إِلَّا قَلِيلاً ٨٥',
    85, 15, 4, 290, 249, 116, 'false'
  );
  
  -- Ayah 86 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2115,
    'وَلَىِٕن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَیۡنَا وَكِیلًا',
    'ولئن شئنا لنذهبن بالذي اوحينا اليك ثم لا تجد لك به علينا وكيلا',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ِئۡنَا لَنَذۡهَبَ<rule class=ghunnah>نّ</rule>َ بِ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ ثُ<rule class=ghunnah>مّ</rule>َ لَا تَجِدُ لَكَ بِه<rule class=madda_normal>ِۦ</rule> عَلَيۡنَا وَكِيلاً ٨٦',
    86, 15, 4, 290, 249, 116, 'false'
  );
  
  -- Ayah 87 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2116,
    'إِلَّا رَحۡمَةࣰ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَیۡكَ كَبِیرࣰا',
    'الا رحمة من ربك ان فضله كان عليك كبيرا',
    'إِلَّا رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فَضۡلَهُ<rule class=madda_normal>ۥ</rule> كَانَ عَلَيۡكَ كَبِيرًا ٨٧',
    87, 15, 4, 291, 249, 116, 'false'
  );
  
  -- Ayah 88 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2117,
    'قُل لَّىِٕنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰۤ أَن یَأۡتُوا۟ بِمِثۡلِ هَـٰذَا ٱلۡقُرۡءَانِ لَا یَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضࣲ ظَهِیرࣰا',
    'قل لئن اجتمعت الانس والجن على ان ياتوا بمثل هذا القران لا ياتون بمثله ولو كان بعضهم لبعض ظهيرا',
    'قُل لَّئِنِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَمَعَتِ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ُ وَ<rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ُ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتُو<rule class=slnt>اۡ</rule> بِمِثۡلِ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِه<rule class=madda_normal>ِۦ</rule> وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ظ</rule>َهِيرًا ٨٨',
    88, 15, 4, 291, 249, 116, 'false'
  );
  
  -- Ayah 89 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2118,
    'وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِی هَـٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲ فَأَبَىٰۤ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورࣰا',
    'ولقد صرفنا للناس في هذا القران من كل مثل فابى اكثر الناس الا كفورا',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> صَرَّفۡنَا لِل<rule class=ghunnah>نّ</rule>َاسِ فِى هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مَثَ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َأَبَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَكۡثَرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ إِلَّا كُفُورًا ٨٩',
    89, 15, 4, 291, 249, 116, 'false'
  );
  
  -- Ayah 90 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2119,
    'وَقَالُوا۟ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ یَنۢبُوعًا',
    'وقالوا لن نؤمن لك حتى تفجر لنا من الارض ينبوعا',
    'وَقَالُو<rule class=slnt>اۡ</rule> ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يَ<rule class=iqlab>نۢب</rule>ُوعًا ٩٠',
    90, 15, 4, 291, 249, 116, 'false'
  );
  
  -- Ayah 91 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2120,
    'أَوۡ تَكُونَ لَكَ جَنَّةࣱ مِّن نَّخِیلࣲ وَعِنَبࣲ فَتُفَجِّرَ ٱلۡأَنۡهَـٰرَ خِلَـٰلَهَا تَفۡجِیرًا',
    'او تكون لك جنة من نخيل وعنب فتفجر الانهار خلالها تفجيرا',
    'أَوۡ تَكُونَ لَكَ جَ<rule class=ghunnah>نّ</rule>َ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّخِي<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َعِنَ<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ف</rule>َتُفَجِّرَ <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رَ خِلَ<rule class=madda_normal>ـٰ</rule>لَهَا تَفۡجِيرًا ٩١',
    91, 15, 4, 291, 249, 116, 'false'
  );
  
  -- Ayah 92 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2121,
    'أَوۡ تُسۡقِطَ ٱلسَّمَاۤءَ كَمَا زَعَمۡتَ عَلَیۡنَا كِسَفًا أَوۡ تَأۡتِیَ بِٱللَّهِ وَٱلۡمَلَـٰۤىِٕكَةِ قَبِیلًا',
    'او تسقط السماء كما زعمت علينا كسفا او تاتي بالله والملائكة قبيلا',
    'أَوۡ تُسۡقِطَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِىَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ قَبِيلاً ٩٢',
    92, 15, 4, 291, 249, 116, 'false'
  );
  
  -- Ayah 93 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2122,
    'أَوۡ یَكُونَ لَكَ بَیۡتࣱ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِی ٱلسَّمَاۤءِ وَلَن نُّؤۡمِنَ لِرُقِیِّكَ حَتَّىٰ تُنَزِّلَ عَلَیۡنَا كِتَـٰبࣰا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّی هَلۡ كُنتُ إِلَّا بَشَرࣰا رَّسُولࣰا',
    'او يكون لك بيت من زخرف او ترقى في السماء ولن نؤمن لرقيك حتى تنزل علينا كتابا نقرؤه قل سبحان ربي هل كنت الا بشرا رسولا',
    'أَوۡ يَكُونَ لَكَ بَيۡ<rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>ُخۡرُفٍ أَوۡ تَرۡقَىٰ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>قۡ</rule>رَؤُهُ<rule class=madda_normal>ۥ</rule>‌ۗ قُلۡ سُ<rule class=qalaqah>بۡ</rule>حَانَ رَبِّى هَلۡ كُ<rule class=ikhafa>نت</rule>ُ إِلَّا بَشَ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولاً ٩٣',
    93, 15, 4, 291, 249, 116, 'false'
  );
  
  -- Ayah 94 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2123,
    'وَمَا مَنَعَ ٱلنَّاسَ أَن یُؤۡمِنُوۤا۟ إِذۡ جَاۤءَهُمُ ٱلۡهُدَىٰۤ إِلَّاۤ أَن قَالُوۤا۟ أَبَعَثَ ٱللَّهُ بَشَرࣰا رَّسُولࣰا',
    'وما منع الناس ان يؤمنوا اذ جاءهم الهدى الا ان قالوا ابعث الله بشرا رسولا',
    'وَمَا مَنَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡهُدَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَبَعَثَ <rule class=ham_wasl>ٱ</rule>للَّهُ بَشَ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولاً ٩٤',
    94, 15, 4, 291, 250, 116, 'false'
  );
  
  -- Ayah 95 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2124,
    'قُل لَّوۡ كَانَ فِی ٱلۡأَرۡضِ مَلَـٰۤىِٕكَةࣱ یَمۡشُونَ مُطۡمَىِٕنِّینَ لَنَزَّلۡنَا عَلَیۡهِم مِّنَ ٱلسَّمَاۤءِ مَلَكࣰا رَّسُولࣰا',
    'قل لو كان في الارض ملائكة يمشون مطمئنين لنزلنا عليهم من السماء ملكا رسولا',
    'قُل لَّوۡ كَانَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َمۡشُونَ مُ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>ِينَ لَنَزَّلۡنَا عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مَلَ<rule class=idgham_wo_ghunnah>كًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولاً ٩٥',
    95, 15, 4, 291, 250, 116, 'false'
  );
  
  -- Ayah 96 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2125,
    'قُلۡ كَفَىٰ بِٱللَّهِ شَهِیدَۢا بَیۡنِی وَبَیۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِیرَۢا بَصِیرࣰا',
    'قل كفى بالله شهيدا بيني وبينكم انه كان بعباده خبيرا بصيرا',
    'قُلۡ كَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ شَهِيد<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنِى وَبَيۡنَكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ بِعِبَادِه<rule class=madda_normal>ِۦ</rule> خَبِير<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َصِيرًا ٩٦',
    96, 15, 4, 291, 250, 116, 'false'
  );
  
  -- Ayah 97 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2126,
    'وَمَن یَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن یُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِیَاۤءَ مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡیࣰا وَبُكۡمࣰا وَصُمࣰّاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَـٰهُمۡ سَعِیرࣰا',
    'ومن يهد الله فهو المهتد ومن يضلل فلن تجد لهم اولياء من دونه ونحشرهم يوم القيامة على وجوههم عميا وبكما وصما ماواهم جهنم كلما خبت زدناهم سعيرا',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَهُوَ <rule class=ham_wasl>ٱ</rule>لۡمُهۡتَدِ‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلۡ فَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لَهُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَنَحۡشُرُهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡ<rule class=idgham_ghunnah>يًا</rule> <rule class=idgham_ghunnah>و</rule>َبُكۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َصُم<rule class=idgham_ghunnah>ًّا‌ۖ</rule> <rule class=idgham_ghunnah>م</rule>َّأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۖ كُلَّمَا خَبَتۡ زِ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ سَعِيرًا ٩٧',
    97, 15, 4, 292, 250, 116, 'false'
  );
  
  -- Ayah 98 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2127,
    'ذَ ٰ⁠لِكَ جَزَاۤؤُهُم بِأَنَّهُمۡ كَفَرُوا۟ بِـَٔایَـٰتِنَا وَقَالُوۤا۟ أَءِذَا كُنَّا عِظَـٰمࣰا وَرُفَـٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقࣰا جَدِیدًا',
    'ذلك جزاؤهم بانهم كفروا باياتنا وقالوا ااذا كنا عظاما ورفاتا اانا لمبعوثون خلقا جديدا',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَفَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَءِذَا كُ<rule class=ghunnah>نّ</rule>َا عِظَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َرُفَ<rule class=madda_normal>ـٰ</rule>تًا أَءِ<rule class=ghunnah>نّ</rule>َا لَمَ<rule class=qalaqah>بۡ</rule>عُوثُونَ خَلۡ<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ج</rule>َدِيدًا ٩٨',
    98, 15, 4, 292, 250, 116, 'false'
  );
  
  -- Ayah 99 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2128,
    '۞ أَوَلَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰۤ أَن یَخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَلࣰا لَّا رَیۡبَ فِیهِ فَأَبَى ٱلظَّـٰلِمُونَ إِلَّا كُفُورࣰا',
    'اولم يروا ان الله الذي خلق السماوات والارض قادر على ان يخلق مثلهم وجعل لهم اجلا لا ريب فيه فابى الظالمون الا كفورا',
    '۞أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ قَادِرٌ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا رَيۡبَ فِيهِ فَأَبَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ إِلَّا كُفُورًا ٩٩',
    99, 15, 4, 292, 250, 117, 'false'
  );
  
  -- Ayah 100 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2129,
    'قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَاۤىِٕنَ رَحۡمَةِ رَبِّیۤ إِذࣰا لَّأَمۡسَكۡتُمۡ خَشۡیَةَ ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَـٰنُ قَتُورࣰا',
    'قل لو انتم تملكون خزائن رحمة ربي اذا لامسكتم خشية الانفاق وكان الانسان قتورا',
    'قُل لَّوۡ أَ<rule class=ikhafa>نت</rule>ُمۡ تَمۡلِكُونَ خَز<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنَ رَحۡمَةِ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّأَمۡسَكۡتُمۡ خَشۡيَةَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نف</rule>َاقِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ قَتُورًا ١٠٠',
    100, 15, 4, 292, 250, 117, 'false'
  );
  
  -- Ayah 101 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2130,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَىٰ تِسۡعَ ءَایَـٰتِۭ بَیِّنَـٰتࣲۖ فَسۡـَٔلۡ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ إِذۡ جَاۤءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ إِنِّی لَأَظُنُّكَ یَـٰمُوسَىٰ مَسۡحُورࣰا',
    'ولقد اتينا موسى تسع ايات بينات فاسال بني اسرائيل اذ جاءهم فقال له فرعون اني لاظنك يا موسى مسحورا',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َسۡــَٔلۡ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ فَقَالَ لَهُ<rule class=madda_normal>ۥ</rule> فِرۡعَوۡنُ إِ<rule class=ghunnah>نّ</rule>ِى لَأَظُ<rule class=ghunnah>نّ</rule>ُكَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ مَسۡحُورًا ١٠١',
    101, 15, 4, 292, 251, 117, 'false'
  );
  
  -- Ayah 102 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2131,
    'قَالَ لَقَدۡ عَلِمۡتَ مَاۤ أَنزَلَ هَـٰۤؤُلَاۤءِ إِلَّا رَبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ بَصَاۤىِٕرَ وَإِنِّی لَأَظُنُّكَ یَـٰفِرۡعَوۡنُ مَثۡبُورࣰا',
    'قال لقد علمت ما انزل هؤلاء الا رب السماوات والارض بصائر واني لاظنك يا فرعون مثبورا',
    'قَالَ لَقَ<rule class=qalaqah>دۡ</rule> عَلِمۡتَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِلَّا رَبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بَص<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرَ وَإِ<rule class=ghunnah>نّ</rule>ِى لَأَظُ<rule class=ghunnah>نّ</rule>ُكَ يَ<rule class=madda_normal>ـٰ</rule>فِرۡعَوۡنُ مَثۡبُورًا ١٠٢',
    102, 15, 4, 292, 251, 117, 'false'
  );
  
  -- Ayah 103 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2132,
    'فَأَرَادَ أَن یَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَـٰهُ وَمَن مَّعَهُۥ جَمِیعࣰا',
    'فاراد ان يستفزهم من الارض فاغرقناه ومن معه جميعا',
    'فَأَرَادَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَفِزَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَأَغۡرَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعَهُ<rule class=madda_normal>ۥ</rule> جَمِيعًا ١٠٣',
    103, 15, 4, 292, 251, 117, 'false'
  );
  
  -- Ayah 104 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2133,
    'وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱسۡكُنُوا۟ ٱلۡأَرۡضَ فَإِذَا جَاۤءَ وَعۡدُ ٱلۡـَٔاخِرَةِ جِئۡنَا بِكُمۡ لَفِیفࣰا',
    'وقلنا من بعده لبني اسرائيل اسكنوا الارض فاذا جاء وعد الاخرة جئنا بكم لفيفا',
    'وَقُلۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> لِبَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>سۡكُنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَعۡدُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ جِئۡنَا بِكُمۡ لَفِيفًا ١٠٤',
    104, 15, 4, 292, 251, 117, 'false'
  );
  
  -- Ayah 105 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2134,
    'وَبِٱلۡحَقِّ أَنزَلۡنَـٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا مُبَشِّرࣰا وَنَذِیرࣰا',
    'وبالحق انزلناه وبالحق نزل وما ارسلناك الا مبشرا ونذيرا',
    'وَبِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَبِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ نَزَلَ‌ۗ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ إِلَّا مُبَشِّ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَذِيرًا ١٠٥',
    105, 15, 4, 293, 251, 117, 'false'
  );
  
  -- Ayah 106 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2135,
    'وَقُرۡءَانࣰا فَرَقۡنَـٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثࣲ وَنَزَّلۡنَـٰهُ تَنزِیلࣰا',
    'وقرانا فرقناه لتقراه على الناس على مكث ونزلناه تنزيلا',
    'وَقُرۡءَا<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َرَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ لِتَ<rule class=qalaqah>قۡ</rule>رَأَهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ عَلَىٰ مُكۡ<rule class=idgham_ghunnah>ثٍ</rule> <rule class=idgham_ghunnah>و</rule>َنَزَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُ تَ<rule class=ikhafa>نز</rule>ِيلاً ١٠٦',
    106, 15, 4, 293, 251, 117, 'false'
  );
  
  -- Ayah 107 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2136,
    'قُلۡ ءَامِنُوا۟ بِهِۦۤ أَوۡ لَا تُؤۡمِنُوۤا۟ۚ إِنَّ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ مِن قَبۡلِهِۦۤ إِذَا یُتۡلَىٰ عَلَیۡهِمۡ یَخِرُّونَ لِلۡأَذۡقَانِ سُجَّدࣰا',
    'قل امنوا به او لا تؤمنوا ان الذين اوتوا العلم من قبله اذا يتلى عليهم يخرون للاذقان سجدا',
    'قُلۡ ءَامِنُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡ لَا تُؤۡمِن<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَ لِلۡأَذۡقَانِ سُجَّدًا ١٠٧',
    107, 15, 4, 293, 251, 117, 'false'
  );
  
  -- Ayah 108 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2137,
    'وَیَقُولُونَ سُبۡحَـٰنَ رَبِّنَاۤ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولࣰا',
    'ويقولون سبحان ربنا ان كان وعد ربنا لمفعولا',
    'وَيَقُولُونَ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ رَبِّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ وَعۡدُ رَبِّنَا لَمَفۡعُولاً ١٠٨',
    108, 15, 4, 293, 251, 117, 'false'
  );
  
  -- Ayah 109 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2138,
    'وَیَخِرُّونَ لِلۡأَذۡقَانِ یَبۡكُونَ وَیَزِیدُهُمۡ خُشُوعࣰا ۩',
    'ويخرون للاذقان يبكون ويزيدهم خشوعا',
    'وَيَخِرُّونَ لِلۡأَذۡقَانِ يَ<rule class=qalaqah>بۡ</rule>كُونَ وَيَزِيدُهُمۡ خُشُوعًا ۩ ١٠٩',
    109, 15, 4, 293, 251, 117, '{"id":4,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 110 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2139,
    'قُلِ ٱدۡعُوا۟ ٱللَّهَ أَوِ ٱدۡعُوا۟ ٱلرَّحۡمَـٰنَۖ أَیࣰّا مَّا تَدۡعُوا۟ فَلَهُ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَیۡنَ ذَ ٰ⁠لِكَ سَبِیلࣰا',
    'قل ادعوا الله او ادعوا الرحمن ايا ما تدعوا فله الاسماء الحسنى ولا تجهر بصلاتك ولا تخافت بها وابتغ بين ذلك سبيلا',
    'قُلِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ أَوِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نَ‌ۖ أَي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>َّا تَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> فَلَهُ <rule class=ham_wasl>ٱ</rule>لۡأَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ‌ۚ وَلَا تَ<rule class=qalaqah>جۡ</rule>هَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغِ بَيۡنَ ذ<rule class=madda_normal>ٰ</rule>لِكَ سَبِيلاً ١١٠',
    110, 15, 4, 293, 251, 117, 'false'
  );
  
  -- Ayah 111 Surah Al-Israa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    17,
    2140,
    'وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی لَمۡ یَتَّخِذۡ وَلَدࣰا وَلَمۡ یَكُن لَّهُۥ شَرِیكࣱ فِی ٱلۡمُلۡكِ وَلَمۡ یَكُن لَّهُۥ وَلِیࣱّ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِیرَۢا',
    'وقل الحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا',
    'وَقُلِ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى لَمۡ يَتَّخِذۡ وَلَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> شَرِي<rule class=ikhafa>كٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡمُلۡكِ وَلَمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> وَلِ<rule class=idgham_ghunnah>ىٌّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذُّلِّ‌ۖ وَكَبِّرۡهُ تَكۡبِيرَۢا ١١١',
    111, 15, 4, 293, 251, 117, 'false'
  );
  

-- Surah Al-Kahf
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (18, 'سُورَةُ الكَهۡفِ', 'Al-Kahf', 'The Cave', 'Meccan', 110);

  -- Ayah 1 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2141,
    'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِیۤ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَـٰبَ وَلَمۡ یَجۡعَل لَّهُۥ عِوَجَاۜ',
    'الحمد لله الذي انزل على عبده الكتاب ولم يجعل له عوجا',
    'ٱلۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلَ عَلَىٰ عَ<rule class=qalaqah>بۡ</rule>دِهِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَلَمۡ يَ<rule class=qalaqah>جۡ</rule>عَل لَّهُ<rule class=madda_normal>ۥ</rule> عِوَجَاۜ ١',
    1, 15, 4, 293, 252, 117, 'false'
  );
  
  -- Ayah 2 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2142,
    'قَیِّمࣰا لِّیُنذِرَ بَأۡسࣰا شَدِیدࣰا مِّن لَّدُنۡهُ وَیُبَشِّرَ ٱلۡمُؤۡمِنِینَ ٱلَّذِینَ یَعۡمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنࣰا',
    'قيما لينذر باسا شديدا من لدنه ويبشر المؤمنين الذين يعملون الصالحات ان لهم اجرا حسنا',
    'قَيِّ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُ<rule class=ikhafa>نذ</rule>ِرَ بَأۡ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُنۡهُ وَيُبَشِّرَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَعۡمَلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ أَ<rule class=ghunnah>نّ</rule>َ لَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رًا حَسَنًا ٢',
    2, 15, 4, 293, 252, 117, 'false'
  );
  
  -- Ayah 3 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2143,
    'مَّـٰكِثِینَ فِیهِ أَبَدࣰا',
    'ماكثين فيه ابدا',
    'مَّ<rule class=madda_normal>ـٰ</rule>كِثِينَ فِيهِ أَبَدًا ٣',
    3, 15, 4, 293, 252, 117, 'false'
  );
  
  -- Ayah 4 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2144,
    'وَیُنذِرَ ٱلَّذِینَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدࣰا',
    'وينذر الذين قالوا اتخذ الله ولدا',
    'وَيُ<rule class=ikhafa>نذ</rule>ِرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَلَدًا ٤',
    4, 15, 4, 293, 252, 117, 'false'
  );
  
  -- Ayah 5 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2145,
    'مَّا لَهُم بِهِۦ مِنۡ عِلۡمࣲ وَلَا لِـَٔابَاۤىِٕهِمۡۚ كَبُرَتۡ كَلِمَةࣰ تَخۡرُجُ مِنۡ أَفۡوَ ٰ⁠هِهِمۡۚ إِن یَقُولُونَ إِلَّا كَذِبࣰا',
    'ما لهم به من علم ولا لابائهم كبرت كلمة تخرج من افواههم ان يقولون الا كذبا',
    'مَّا لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مِنۡ عِلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا لِأَب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ‌ۚ كَبُرَتۡ كَلِمَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َخۡرُجُ مِنۡ أَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُونَ إِلَّا كَذِبًا ٥',
    5, 15, 4, 294, 252, 117, 'false'
  );
  
  -- Ayah 6 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2146,
    'فَلَعَلَّكَ بَـٰخِعࣱ نَّفۡسَكَ عَلَىٰۤ ءَاثَـٰرِهِمۡ إِن لَّمۡ یُؤۡمِنُوا۟ بِهَـٰذَا ٱلۡحَدِیثِ أَسَفًا',
    'فلعلك باخع نفسك على اثارهم ان لم يؤمنوا بهذا الحديث اسفا',
    'فَلَعَلَّكَ بَ<rule class=madda_normal>ـٰ</rule>خِ<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسَكَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاثَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ إ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يُؤۡمِنُو<rule class=slnt>اۡ</rule> بِهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡحَدِيثِ أَسَفًا ٦',
    6, 15, 4, 294, 252, 117, 'false'
  );
  
  -- Ayah 7 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2147,
    'إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِینَةࣰ لَّهَا لِنَبۡلُوَهُمۡ أَیُّهُمۡ أَحۡسَنُ عَمَلࣰا',
    'انا جعلنا ما على الارض زينة لها لنبلوهم ايهم احسن عملا',
    'إِ<rule class=ghunnah>نّ</rule>َا جَعَلۡنَا مَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ زِينَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهَا لِنَ<rule class=qalaqah>بۡ</rule>لُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلاً ٧',
    7, 15, 4, 294, 252, 117, 'false'
  );
  
  -- Ayah 8 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2148,
    'وَإِنَّا لَجَـٰعِلُونَ مَا عَلَیۡهَا صَعِیدࣰا جُرُزًا',
    'وانا لجاعلون ما عليها صعيدا جرزا',
    'وَإِ<rule class=ghunnah>نّ</rule>َا لَجَ<rule class=madda_normal>ـٰ</rule>عِلُونَ مَا عَلَيۡهَا صَعِي<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ج</rule>ُرُزًا ٨',
    8, 15, 4, 294, 252, 117, 'false'
  );
  
  -- Ayah 9 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2149,
    'أَمۡ حَسِبۡتَ أَنَّ أَصۡحَـٰبَ ٱلۡكَهۡفِ وَٱلرَّقِیمِ كَانُوا۟ مِنۡ ءَایَـٰتِنَا عَجَبًا',
    'ام حسبت ان اصحاب الكهف والرقيم كانوا من اياتنا عجبا',
    'أَمۡ حَسِ<rule class=qalaqah>بۡ</rule>تَ أَ<rule class=ghunnah>نّ</rule>َ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لۡكَهۡفِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّقِيمِ كَانُو<rule class=slnt>اۡ</rule> مِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا عَجَبًا ٩',
    9, 15, 4, 294, 252, 117, 'false'
  );
  
  -- Ayah 10 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2150,
    'إِذۡ أَوَى ٱلۡفِتۡیَةُ إِلَى ٱلۡكَهۡفِ فَقَالُوا۟ رَبَّنَاۤ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةࣰ وَهَیِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدࣰا',
    'اذ اوى الفتية الى الكهف فقالوا ربنا اتنا من لدنك رحمة وهيئ لنا من امرنا رشدا',
    'إِذۡ أَوَى <rule class=ham_wasl>ٱ</rule>لۡفِتۡيَةُ إِلَى <rule class=ham_wasl>ٱ</rule>لۡكَهۡفِ فَقَالُو<rule class=slnt>اۡ</rule> رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتِنَا م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ikhafa>نك</rule>َ رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدًا ١٠',
    10, 15, 4, 294, 252, 117, 'false'
  );
  
  -- Ayah 11 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2151,
    'فَضَرَبۡنَا عَلَىٰۤ ءَاذَانِهِمۡ فِی ٱلۡكَهۡفِ سِنِینَ عَدَدࣰا',
    'فضربنا على اذانهم في الكهف سنين عددا',
    'فَضَرَ<rule class=qalaqah>بۡ</rule>نَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاذَانِهِمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكَهۡفِ سِنِينَ عَدَدًا ١١',
    11, 15, 4, 294, 252, 117, 'false'
  );
  
  -- Ayah 12 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2152,
    'ثُمَّ بَعَثۡنَـٰهُمۡ لِنَعۡلَمَ أَیُّ ٱلۡحِزۡبَیۡنِ أَحۡصَىٰ لِمَا لَبِثُوۤا۟ أَمَدࣰا',
    'ثم بعثناهم لنعلم اي الحزبين احصى لما لبثوا امدا',
    'ثُ<rule class=ghunnah>مّ</rule>َ بَعَثۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ لِنَعۡلَمَ أَىُّ <rule class=ham_wasl>ٱ</rule>لۡحِزۡبَيۡنِ أَحۡصَىٰ لِمَا لَبِث<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمَدًا ١٢',
    12, 15, 4, 294, 252, 117, 'false'
  );
  
  -- Ayah 13 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2153,
    'نَّحۡنُ نَقُصُّ عَلَیۡكَ نَبَأَهُم بِٱلۡحَقِّۚ إِنَّهُمۡ فِتۡیَةٌ ءَامَنُوا۟ بِرَبِّهِمۡ وَزِدۡنَـٰهُمۡ هُدࣰى',
    'نحن نقص عليك نباهم بالحق انهم فتية امنوا بربهم وزدناهم هدى',
    'نَّحۡنُ نَقُصُّ عَلَيۡكَ نَبَأَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُمۡ فِتۡيَةٌ ءَامَنُو<rule class=slnt>اۡ</rule> بِرَبِّهِمۡ وَزِ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ هُدًى ١٣',
    13, 15, 4, 294, 253, 117, 'false'
  );
  
  -- Ayah 14 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2154,
    'وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ لَن نَّدۡعُوَا۟ مِن دُونِهِۦۤ إِلَـٰهࣰاۖ لَّقَدۡ قُلۡنَاۤ إِذࣰا شَطَطًا',
    'وربطنا على قلوبهم اذ قاموا فقالوا ربنا رب السماوات والارض لن ندعو من دونه الها لقد قلنا اذا شططا',
    'وَرَبَ<rule class=qalaqah>طۡ</rule>نَا عَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُو<rule class=slnt>اۡ</rule> فَقَالُو<rule class=slnt>اۡ</rule> رَبُّنَا رَبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>دۡ</rule>عُوَ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>هًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّقَ<rule class=qalaqah>دۡ</rule> قُلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ذًا</rule> <rule class=ikhafa>ش</rule>َطَطًا ١٤',
    14, 15, 4, 294, 253, 117, 'false'
  );
  
  -- Ayah 15 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2155,
    'هَـٰۤؤُلَاۤءِ قَوۡمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦۤ ءَالِهَةࣰۖ لَّوۡلَا یَأۡتُونَ عَلَیۡهِم بِسُلۡطَـٰنِۭ بَیِّنࣲۖ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰا',
    'هؤلاء قومنا اتخذوا من دونه الهة لولا ياتون عليهم بسلطان بين فمن اظلم ممن افترى على الله كذبا',
    'هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ قَوۡمُنَا <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> ءَالِهَ<rule class=idgham_wo_ghunnah>ةً‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡلَا يَأۡتُونَ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>نِۭ</rule> <rule class=iqlab>ب</rule>َيِّ<rule class=ikhafa>نٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا ١٥',
    15, 15, 4, 294, 253, 117, 'false'
  );
  
  -- Ayah 16 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2156,
    'وَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا یَعۡبُدُونَ إِلَّا ٱللَّهَ فَأۡوُۥۤا۟ إِلَى ٱلۡكَهۡفِ یَنشُرۡ لَكُمۡ رَبُّكُم مِّن رَّحۡمَتِهِۦ وَیُهَیِّئۡ لَكُم مِّنۡ أَمۡرِكُم مِّرۡفَقࣰا',
    'واذ اعتزلتموهم وما يعبدون الا الله فاووا الى الكهف ينشر لكم ربكم من رحمته ويهيئ لكم من امركم مرفقا',
    'وَإِذِ <rule class=ham_wasl>ٱ</rule>عۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَ فَأۡوُ<rule class=madda_obligatory_monfasel>ۥٓاۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡكَهۡفِ يَ<rule class=ikhafa>نش</rule>ُرۡ لَكُمۡ رَبُّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَتِه<rule class=madda_normal>ِۦ</rule> وَيُهَيِّئۡ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَمۡرِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّرۡفَقًا ١٦',
    16, 15, 4, 295, 253, 117, 'false'
  );
  
  -- Ayah 17 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2157,
    '۞ وَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَ ٰ⁠وَرُ عَن كَهۡفِهِمۡ ذَاتَ ٱلۡیَمِینِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِی فَجۡوَةࣲ مِّنۡهُۚ ذَ ٰ⁠لِكَ مِنۡ ءَایَـٰتِ ٱللَّهِۗ مَن یَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن یُضۡلِلۡ فَلَن تَجِدَ لَهُۥ وَلِیࣰّا مُّرۡشِدࣰا',
    'وترى الشمس اذا طلعت تزاور عن كهفهم ذات اليمين واذا غربت تقرضهم ذات الشمال وهم في فجوة منه ذلك من ايات الله من يهد الله فهو المهتد ومن يضلل فلن تجد له وليا مرشدا',
    '۞وَتَرَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ إِذَا طَلَعَت تَّز<rule class=madda_normal>ٰ</rule>وَرُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َهۡفِهِمۡ ذَاتَ <rule class=ham_wasl>ٱ</rule>لۡيَمِينِ وَإِذَا غَرَبَت تَّ<rule class=qalaqah>قۡ</rule>رِضُهُمۡ ذَاتَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شِّمَالِ وَهُمۡ فِى فَ<rule class=qalaqah>جۡ</rule>وَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ مِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَهُوَ <rule class=ham_wasl>ٱ</rule>لۡمُهۡتَدِ‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلۡ فَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لَهُ<rule class=madda_normal>ۥ</rule> وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ُّرۡشِدًا ١٧',
    17, 15, 4, 295, 253, 118, 'false'
  );
  
  -- Ayah 18 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2158,
    'وَتَحۡسَبُهُمۡ أَیۡقَاظࣰا وَهُمۡ رُقُودࣱۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡیَمِینِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم بَـٰسِطࣱ ذِرَاعَیۡهِ بِٱلۡوَصِیدِۚ لَوِ ٱطَّلَعۡتَ عَلَیۡهِمۡ لَوَلَّیۡتَ مِنۡهُمۡ فِرَارࣰا وَلَمُلِئۡتَ مِنۡهُمۡ رُعۡبࣰا',
    'وتحسبهم ايقاظا وهم رقود ونقلبهم ذات اليمين وذات الشمال وكلبهم باسط ذراعيه بالوصيد لو اطلعت عليهم لوليت منهم فرارا ولملئت منهم رعبا',
    'وَتَحۡسَبُهُمۡ أَيۡقَا<rule class=idgham_ghunnah>ظًا</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ رُقُو<rule class=idgham_ghunnah>دٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َنُقَلِّبُهُمۡ ذَاتَ <rule class=ham_wasl>ٱ</rule>لۡيَمِينِ وَذَاتَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شِّمَالِ‌ۖ وَكَلۡبُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َ<rule class=madda_normal>ـٰ</rule>سِ<rule class=ikhafa>طٌ</rule> <rule class=ikhafa>ذ</rule>ِرَاعَيۡهِ بِ<rule class=ham_wasl>ٱ</rule>لۡوَصِيدِ‌ۚ لَوِ <rule class=ham_wasl>ٱ</rule>طَّلَعۡتَ عَلَيۡهِمۡ لَوَلَّيۡتَ مِنۡهُمۡ فِرَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َلَمُلِئۡتَ مِنۡهُمۡ رُعۡبًا ١٨',
    18, 15, 4, 295, 254, 118, 'false'
  );
  
  -- Ayah 19 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2159,
    'وَكَذَ ٰ⁠لِكَ بَعَثۡنَـٰهُمۡ لِیَتَسَاۤءَلُوا۟ بَیۡنَهُمۡۚ قَالَ قَاۤىِٕلࣱ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُوا۟ لَبِثۡنَا یَوۡمًا أَوۡ بَعۡضَ یَوۡمࣲۚ قَالُوا۟ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوۤا۟ أَحَدَكُم بِوَرِقِكُمۡ هَـٰذِهِۦۤ إِلَى ٱلۡمَدِینَةِ فَلۡیَنظُرۡ أَیُّهَاۤ أَزۡكَىٰ طَعَامࣰا فَلۡیَأۡتِكُم بِرِزۡقࣲ مِّنۡهُ وَلۡیَتَلَطَّفۡ وَلَا یُشۡعِرَنَّ بِكُمۡ أَحَدًا',
    'وكذلك بعثناهم ليتساءلوا بينهم قال قائل منهم كم لبثتم قالوا لبثنا يوما او بعض يوم قالوا ربكم اعلم بما لبثتم فابعثوا احدكم بورقكم هذه الى المدينة فلينظر ايها ازكى طعاما فلياتكم برزق منه وليتلطف ولا يشعرن بكم احدا',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ بَعَثۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ لِيَتَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَلُو<rule class=slnt>اۡ</rule> بَيۡنَهُمۡ‌ۚ قَالَ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ كَمۡ لَبِثۡتُمۡ‌ۖ قَالُو<rule class=slnt>اۡ</rule> لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡ<rule class=ikhafa>مٍ‌ۚ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>عَث<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَحَدَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِوَرِقِكُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ فَلۡيَ<rule class=ikhafa>نظ</rule>ُرۡ أَيُّه<rule class=madda_obligatory_monfasel>َآ</rule> أَزۡكَىٰ طَعَا<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َلۡيَأۡتِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرِزۡ<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَ<rule class=ghunnah>نّ</rule>َ بِكُمۡ أَحَدًا ١٩',
    19, 15, 4, 295, 254, 118, 'false'
  );
  
  -- Ayah 20 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2160,
    'إِنَّهُمۡ إِن یَظۡهَرُوا۟ عَلَیۡكُمۡ یَرۡجُمُوكُمۡ أَوۡ یُعِیدُوكُمۡ فِی مِلَّتِهِمۡ وَلَن تُفۡلِحُوۤا۟ إِذًا أَبَدࣰا',
    'انهم ان يظهروا عليكم يرجموكم او يعيدوكم في ملتهم ولن تفلحوا اذا ابدا',
    'إِ<rule class=ghunnah>نّ</rule>َهُمۡ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َظۡهَرُو<rule class=slnt>اۡ</rule> عَلَيۡكُمۡ يَرۡجُمُوكُمۡ أَوۡ يُعِيدُوكُمۡ فِى مِلَّتِهِمۡ وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُفۡلِح<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذًا أَبَدًا ٢٠',
    20, 15, 4, 295, 254, 118, 'false'
  );
  
  -- Ayah 21 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2161,
    'وَكَذَ ٰ⁠لِكَ أَعۡثَرۡنَا عَلَیۡهِمۡ لِیَعۡلَمُوۤا۟ أَنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَأَنَّ ٱلسَّاعَةَ لَا رَیۡبَ فِیهَاۤ إِذۡ یَتَنَـٰزَعُونَ بَیۡنَهُمۡ أَمۡرَهُمۡۖ فَقَالُوا۟ ٱبۡنُوا۟ عَلَیۡهِم بُنۡیَـٰنࣰاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِینَ غَلَبُوا۟ عَلَىٰۤ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَیۡهِم مَّسۡجِدࣰا',
    'وكذلك اعثرنا عليهم ليعلموا ان وعد الله حق وان الساعة لا ريب فيها اذ يتنازعون بينهم امرهم فقالوا ابنوا عليهم بنيانا ربهم اعلم بهم قال الذين غلبوا على امرهم لنتخذن عليهم مسجدا',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=idgham_ghunnah>قٌّ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ لَا رَيۡبَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> إِذۡ يَتَنَ<rule class=madda_normal>ـٰ</rule>زَعُونَ بَيۡنَهُمۡ أَمۡرَهُمۡ‌ۖ فَقَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُو<rule class=slnt>اۡ</rule> عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ُنۡيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>نًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبُّهُمۡ أَعۡلَمُ بِهِمۡ‌ۚ قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ غَلَبُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡرِهِمۡ لَنَتَّخِذَ<rule class=ghunnah>نّ</rule>َ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّسۡجِدًا ٢١',
    21, 15, 4, 296, 254, 118, 'false'
  );
  
  -- Ayah 22 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2162,
    'سَیَقُولُونَ ثَلَـٰثَةࣱ رَّابِعُهُمۡ كَلۡبُهُمۡ وَیَقُولُونَ خَمۡسَةࣱ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَیۡبِۖ وَیَقُولُونَ سَبۡعَةࣱ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّیۤ أَعۡلَمُ بِعِدَّتِهِم مَّا یَعۡلَمُهُمۡ إِلَّا قَلِیلࣱۗ فَلَا تُمَارِ فِیهِمۡ إِلَّا مِرَاۤءࣰ ظَـٰهِرࣰا وَلَا تَسۡتَفۡتِ فِیهِم مِّنۡهُمۡ أَحَدࣰا',
    'سيقولون ثلاثة رابعهم كلبهم ويقولون خمسة سادسهم كلبهم رجما بالغيب ويقولون سبعة وثامنهم كلبهم قل ربي اعلم بعدتهم ما يعلمهم الا قليل فلا تمار فيهم الا مراء ظاهرا ولا تستفت فيهم منهم احدا',
    'سَيَقُولُونَ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>س</rule>َادِسُهُمۡ كَلۡبُهُمۡ رَ<rule class=qalaqah>جۡ</rule>م<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ‌ۖ وَيَقُولُونَ سَ<rule class=qalaqah>بۡ</rule>عَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َثَامِنُهُمۡ كَلۡبُهُمۡ‌ۚ قُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡلَمُ بِعِدَّتِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا يَعۡلَمُهُمۡ إِلَّا قَلِي<rule class=ikhafa>لٌ‌ۗ</rule> <rule class=ikhafa>ف</rule>َلَا تُمَارِ فِيهِمۡ إِلَّا مِر<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ظ</rule>َ<rule class=madda_normal>ـٰ</rule>هِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَسۡتَفۡتِ فِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُمۡ أَحَدًا ٢٢',
    22, 15, 4, 296, 254, 118, 'false'
  );
  
  -- Ayah 23 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2163,
    'وَلَا تَقُولَنَّ لِشَا۟یۡءٍ إِنِّی فَاعِلࣱ ذَ ٰ⁠لِكَ غَدًا',
    'ولا تقولن لشيء اني فاعل ذلك غدا',
    'وَلَا تَقُولَ<rule class=ghunnah>نّ</rule>َ لِشَ<rule class=slnt>اۡ</rule>ىۡءٍ إِ<rule class=ghunnah>نّ</rule>ِى فَاعِ<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ غَدًا ٢٣',
    23, 15, 4, 296, 255, 118, 'false'
  );
  
  -- Ayah 24 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2164,
    'إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ إِذَا نَسِیتَ وَقُلۡ عَسَىٰۤ أَن یَهۡدِیَنِ رَبِّی لِأَقۡرَبَ مِنۡ هَـٰذَا رَشَدࣰا',
    'الا ان يشاء الله واذكر ربك اذا نسيت وقل عسى ان يهدين ربي لاقرب من هذا رشدا',
    'إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>ذۡكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلۡ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِيَنِ رَبِّى لِأَ<rule class=qalaqah>قۡ</rule>رَبَ مِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا رَشَدًا ٢٤',
    24, 15, 4, 296, 255, 118, 'false'
  );
  
  -- Ayah 25 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2165,
    'وَلَبِثُوا۟ فِی كَهۡفِهِمۡ ثَلَـٰثَ مِا۟ئَةࣲ سِنِینَ وَٱزۡدَادُوا۟ تِسۡعࣰا',
    'ولبثوا في كهفهم ثلاث مائة سنين وازدادوا تسعا',
    'وَلَبِثُو<rule class=slnt>اۡ</rule> فِى كَهۡفِهِمۡ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَ مِ<rule class=slnt>اۡ</rule>ئَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>س</rule>ِنِينَ وَ<rule class=ham_wasl>ٱ</rule>زۡدَادُو<rule class=slnt>اۡ</rule> تِسۡعًا ٢٥',
    25, 15, 4, 296, 255, 118, 'false'
  );
  
  -- Ayah 26 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2166,
    'قُلِ ٱللَّهُ أَعۡلَمُ بِمَا لَبِثُوا۟ۖ لَهُۥ غَیۡبُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِیࣲّ وَلَا یُشۡرِكُ فِی حُكۡمِهِۦۤ أَحَدࣰا',
    'قل الله اعلم بما لبثوا له غيب السماوات والارض ابصر به واسمع ما لهم من دونه من ولي ولا يشرك في حكمه احدا',
    'قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِمَا لَبِثُو<rule class=slnt>اۡ‌ۖ</rule> لَهُ<rule class=madda_normal>ۥ</rule> غَيۡبُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ أَ<rule class=qalaqah>بۡ</rule>صِرۡ بِه<rule class=madda_normal>ِۦ</rule> وَأَسۡمِعۡ‌ۚ مَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُشۡرِكُ فِى حُكۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَحَدًا ٢٦',
    26, 15, 4, 296, 255, 118, 'false'
  );
  
  -- Ayah 27 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2167,
    'وَٱتۡلُ مَاۤ أُوحِیَ إِلَیۡكَ مِن كِتَابِ رَبِّكَۖ لَا مُبَدِّلَ لِكَلِمَـٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلۡتَحَدࣰا',
    'واتل ما اوحي اليك من كتاب ربك لا مبدل لكلماته ولن تجد من دونه ملتحدا',
    'وَ<rule class=ham_wasl>ٱ</rule>تۡلُ م<rule class=madda_obligatory_monfasel>َآ</rule> أُوحِىَ إِلَيۡكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ِتَابِ رَبِّكَ‌ۖ لَا مُبَدِّلَ لِكَلِمَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> مُلۡتَحَدًا ٢٧',
    27, 15, 4, 296, 255, 118, 'false'
  );
  
  -- Ayah 28 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2168,
    'وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِینَ یَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِیِّ یُرِیدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَیۡنَاكَ عَنۡهُمۡ تُرِیدُ زِینَةَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطࣰا',
    'واصبر نفسك مع الذين يدعون ربهم بالغداة والعشي يريدون وجهه ولا تعد عيناك عنهم تريد زينة الحياة الدنيا ولا تطع من اغفلنا قلبه عن ذكرنا واتبع هواه وكان امره فرطا',
    'وَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ نَفۡسَكَ مَعَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ رَبَّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡغَدَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَ<rule class=ham_wasl>ٱ</rule>لۡعَشِىِّ يُرِيدُونَ وَ<rule class=qalaqah>جۡ</rule>هَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُ<rule class=madda_normal>ۥ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِنَا وَ<rule class=ham_wasl>ٱ</rule>تَّبَعَ هَوَ<rule class=madda_normal>ٮٰ</rule>هُ وَكَانَ أَمۡرُهُ<rule class=madda_normal>ۥ</rule> فُرُطًا ٢٨',
    28, 15, 4, 297, 255, 118, 'false'
  );
  
  -- Ayah 29 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2169,
    'وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَاۤءَ فَلۡیُؤۡمِن وَمَن شَاۤءَ فَلۡیَكۡفُرۡۚ إِنَّاۤ أَعۡتَدۡنَا لِلظَّـٰلِمِینَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ وَإِن یَسۡتَغِیثُوا۟ یُغَاثُوا۟ بِمَاۤءࣲ كَٱلۡمُهۡلِ یَشۡوِی ٱلۡوُجُوهَۚ بِئۡسَ ٱلشَّرَابُ وَسَاۤءَتۡ مُرۡتَفَقًا',
    'وقل الحق من ربكم فمن شاء فليؤمن ومن شاء فليكفر انا اعتدنا للظالمين نارا احاط بهم سرادقها وان يستغيثوا يغاثوا بماء كالمهل يشوي الوجوه بئس الشراب وساءت مرتفقا',
    'وَقُلِ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ‌ۖ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَلۡيُؤۡم<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَلۡيَكۡفُرۡ‌ۚ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَا‌ۚ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَغِيثُو<rule class=slnt>اۡ</rule> يُغَاثُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ك</rule>َ<rule class=ham_wasl>ٱ</rule>لۡمُهۡلِ يَشۡوِى <rule class=ham_wasl>ٱ</rule>لۡوُجُوهَ‌ۚ بِئۡسَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّرَابُ وَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ مُرۡتَفَقًا ٢٩',
    29, 15, 4, 297, 255, 118, 'false'
  );
  
  -- Ayah 30 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2170,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ إِنَّا لَا نُضِیعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا',
    'ان الذين امنوا وعملوا الصالحات انا لا نضيع اجر من احسن عملا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ إِ<rule class=ghunnah>نّ</rule>َا لَا نُضِيعُ أَ<rule class=qalaqah>جۡ</rule>رَ مَنۡ أَحۡسَنَ عَمَلاً ٣٠',
    30, 15, 4, 297, 255, 118, 'false'
  );
  
  -- Ayah 31 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2171,
    'أُو۟لَـٰۤىِٕكَ لَهُمۡ جَنَّـٰتُ عَدۡنࣲ تَجۡرِی مِن تَحۡتِهِمُ ٱلۡأَنۡهَـٰرُ یُحَلَّوۡنَ فِیهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَیَلۡبَسُونَ ثِیَابًا خُضۡرࣰا مِّن سُندُسࣲ وَإِسۡتَبۡرَقࣲ مُّتَّكِـِٔینَ فِیهَا عَلَى ٱلۡأَرَاۤىِٕكِۚ نِعۡمَ ٱلثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقࣰا',
    'اولئك لهم جنات عدن تجري من تحتهم الانهار يحلون فيها من اساور من ذهب ويلبسون ثيابا خضرا من سندس واستبرق متكئين فيها على الارائك نعم الثواب وحسنت مرتفقا',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ عَ<rule class=qalaqah>دۡ</rule><rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َهَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َيَلۡبَسُونَ ثِيَابًا خُضۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُ<rule class=ikhafa>ند</rule>ُ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِسۡتَ<rule class=qalaqah>بۡ</rule>رَ<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّتَّكِــِٔينَ فِيهَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكِ‌ۚ نِعۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقًا ٣١',
    31, 15, 4, 297, 255, 118, 'false'
  );
  
  -- Ayah 32 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2172,
    '۞ وَٱضۡرِبۡ لَهُم مَّثَلࣰا رَّجُلَیۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَیۡنِ مِنۡ أَعۡنَـٰبࣲ وَحَفَفۡنَـٰهُمَا بِنَخۡلࣲ وَجَعَلۡنَا بَیۡنَهُمَا زَرۡعࣰا',
    'واضرب لهم مثلا رجلين جعلنا لاحدهما جنتين من اعناب وحففناهما بنخل وجعلنا بينهما زرعا',
    '۞وَ<rule class=ham_wasl>ٱ</rule>ضۡرِ<rule class=qalaqah>بۡ</rule> لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّثَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَ<rule class=ghunnah>نّ</rule>َتَيۡنِ مِنۡ أَعۡنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َحَفَفۡنَ<rule class=madda_normal>ـٰ</rule>هُمَا بِنَخۡ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلۡنَا بَيۡنَهُمَا زَرۡعًا ٣٢',
    32, 15, 4, 297, 256, 119, 'false'
  );
  
  -- Ayah 33 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2173,
    'كِلۡتَا ٱلۡجَنَّتَیۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَیۡـࣰٔاۚ وَفَجَّرۡنَا خِلَـٰلَهُمَا نَهَرࣰا',
    'كلتا الجنتين اتت اكلها ولم تظلم منه شيئا وفجرنا خلالهما نهرا',
    'كِلۡتَا <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡل<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َفَجَّرۡنَا خِلَ<rule class=madda_normal>ـٰ</rule>لَهُمَا نَهَرًا ٣٣',
    33, 15, 4, 297, 256, 119, 'false'
  );
  
  -- Ayah 34 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2174,
    'وَكَانَ لَهُۥ ثَمَرࣱ فَقَالَ لِصَـٰحِبِهِۦ وَهُوَ یُحَاوِرُهُۥۤ أَنَا۠ أَكۡثَرُ مِنكَ مَالࣰا وَأَعَزُّ نَفَرࣰا',
    'وكان له ثمر فقال لصاحبه وهو يحاوره انا اكثر منك مالا واعز نفرا',
    'وَكَانَ لَهُ<rule class=madda_normal>ۥ</rule> ثَمَ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َقَالَ لِصَ<rule class=madda_normal>ـٰ</rule>حِبِه<rule class=madda_normal>ِۦ</rule> وَهُوَ يُحَاوِرُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَنَاۡ أَكۡثَرُ مِ<rule class=ikhafa>نك</rule>َ مَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َأَعَزُّ نَفَرًا ٣٤',
    34, 15, 4, 297, 256, 119, 'false'
  );
  
  -- Ayah 35 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2175,
    'وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمࣱ لِّنَفۡسِهِۦ قَالَ مَاۤ أَظُنُّ أَن تَبِیدَ هَـٰذِهِۦۤ أَبَدࣰا',
    'ودخل جنته وهو ظالم لنفسه قال ما اظن ان تبيد هذه ابدا',
    'وَدَخَلَ جَ<rule class=ghunnah>نّ</rule>َتَهُ<rule class=madda_normal>ۥ</rule> وَهُوَ ظَالِ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّنَفۡسِه<rule class=madda_normal>ِۦ</rule> قَالَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَظُ<rule class=ghunnah>نّ</rule>ُ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبِيدَ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَبَدًا ٣٥',
    35, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 36 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2176,
    'وَمَاۤ أَظُنُّ ٱلسَّاعَةَ قَاۤىِٕمَةࣰ وَلَىِٕن رُّدِدتُّ إِلَىٰ رَبِّی لَأَجِدَنَّ خَیۡرࣰا مِّنۡهَا مُنقَلَبࣰا',
    'وما اظن الساعة قائمة ولئن رددت الى ربي لاجدن خيرا منها منقلبا',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَظُ<rule class=ghunnah>نّ</rule>ُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّدِ<rule class=idgham_mutajanisayn>د</rule>تُّ إِلَىٰ رَبِّى لَأَجِدَ<rule class=ghunnah>نّ</rule>َ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا مُ<rule class=ikhafa>نق</rule>َلَبًا ٣٦',
    36, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 37 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2177,
    'قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ یُحَاوِرُهُۥۤ أَكَفَرۡتَ بِٱلَّذِی خَلَقَكَ مِن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ سَوَّىٰكَ رَجُلࣰا',
    'قال له صاحبه وهو يحاوره اكفرت بالذي خلقك من تراب ثم من نطفة ثم سواك رجلا',
    'قَالَ لَهُ<rule class=madda_normal>ۥ</rule> صَاحِبُهُ<rule class=madda_normal>ۥ</rule> وَهُوَ يُحَاوِرُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَكَفَرۡتَ بِ<rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّ<rule class=qalaqah>طۡ</rule>فَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ سَوَّ<rule class=madda_normal>ٮٰ</rule>كَ رَجُلاً ٣٧',
    37, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 38 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2178,
    'لَّـٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّی وَلَاۤ أُشۡرِكُ بِرَبِّیۤ أَحَدࣰا',
    'لكنا هو الله ربي ولا اشرك بربي احدا',
    'لَّ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َاۡ هُوَ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبِّى وَل<rule class=madda_obligatory_monfasel>َآ</rule> أُشۡرِكُ بِرَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحَدًا ٣٨',
    38, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 39 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2179,
    'وَلَوۡلَاۤ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَاۤءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالࣰا وَوَلَدࣰا',
    'ولولا اذ دخلت جنتك قلت ما شاء الله لا قوة الا بالله ان ترن انا اقل منك مالا وولدا',
    'وَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> إِذۡ دَخَلۡتَ جَ<rule class=ghunnah>نّ</rule>َتَكَ قُلۡتَ مَا ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَا قُوَّةَ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرَنِ أَنَاۡ أَقَلَّ مِ<rule class=ikhafa>نك</rule>َ مَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َوَلَدًا ٣٩',
    39, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 40 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2180,
    'فَعَسَىٰ رَبِّیۤ أَن یُؤۡتِیَنِ خَیۡرࣰا مِّن جَنَّتِكَ وَیُرۡسِلَ عَلَیۡهَا حُسۡبَانࣰا مِّنَ ٱلسَّمَاۤءِ فَتُصۡبِحَ صَعِیدࣰا زَلَقًا',
    'فعسى ربي ان يؤتين خيرا من جنتك ويرسل عليها حسبانا من السماء فتصبح صعيدا زلقا',
    'فَعَسَىٰ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡتِيَنِ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َ<rule class=ghunnah>نّ</rule>َتِكَ وَيُرۡسِلَ عَلَيۡهَا حُسۡبَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَتُصۡبِحَ صَعِي<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ز</rule>َلَقًا ٤٠',
    40, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 41 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2181,
    'أَوۡ یُصۡبِحَ مَاۤؤُهَا غَوۡرࣰا فَلَن تَسۡتَطِیعَ لَهُۥ طَلَبࣰا',
    'او يصبح ماؤها غورا فلن تستطيع له طلبا',
    'أَوۡ يُصۡبِحَ م<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهَا غَوۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَطِيعَ لَهُ<rule class=madda_normal>ۥ</rule> طَلَبًا ٤١',
    41, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 42 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2182,
    'وَأُحِیطَ بِثَمَرِهِۦ فَأَصۡبَحَ یُقَلِّبُ كَفَّیۡهِ عَلَىٰ مَاۤ أَنفَقَ فِیهَا وَهِیَ خَاوِیَةٌ عَلَىٰ عُرُوشِهَا وَیَقُولُ یَـٰلَیۡتَنِی لَمۡ أُشۡرِكۡ بِرَبِّیۤ أَحَدࣰا',
    'واحيط بثمره فاصبح يقلب كفيه على ما انفق فيها وهي خاوية على عروشها ويقول يا ليتني لم اشرك بربي احدا',
    'وَأُحِيطَ بِثَمَرِه<rule class=madda_normal>ِۦ</rule> فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َقَ فِيهَا وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَنِى لَمۡ أُشۡرِكۡ بِرَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحَدًا ٤٢',
    42, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 43 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2183,
    'وَلَمۡ تَكُن لَّهُۥ فِئَةࣱ یَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا',
    'ولم تكن له فئة ينصرونه من دون الله وما كان منتصرا',
    'وَلَمۡ تَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> فِئَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرُونَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَا كَانَ مُ<rule class=ikhafa>نت</rule>َصِرًا ٤٣',
    43, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 44 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2184,
    'هُنَالِكَ ٱلۡوَلَـٰیَةُ لِلَّهِ ٱلۡحَقِّۚ هُوَ خَیۡرࣱ ثَوَابࣰا وَخَیۡرٌ عُقۡبࣰا',
    'هنالك الولاية لله الحق هو خير ثوابا وخير عقبا',
    'هُنَالِكَ <rule class=ham_wasl>ٱ</rule>لۡوَلَ<rule class=madda_normal>ـٰ</rule>يَةُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ هُوَ خَيۡ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ث</rule>َوَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َخَيۡرٌ عُ<rule class=qalaqah>قۡ</rule>بًا ٤٤',
    44, 15, 4, 298, 256, 119, 'false'
  );
  
  -- Ayah 45 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2185,
    'وَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا كَمَاۤءٍ أَنزَلۡنَـٰهُ مِنَ ٱلسَّمَاۤءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ فَأَصۡبَحَ هَشِیمࣰا تَذۡرُوهُ ٱلرِّیَـٰحُۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ مُّقۡتَدِرًا',
    'واضرب لهم مثل الحياة الدنيا كماء انزلناه من السماء فاختلط به نبات الارض فاصبح هشيما تذروه الرياح وكان الله على كل شيء مقتدرا',
    'وَ<rule class=ham_wasl>ٱ</rule>ضۡرِ<rule class=qalaqah>بۡ</rule> لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّثَلَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا كَم<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَ<rule class=ham_wasl>ٱ</rule>خۡتَلَطَ بِه<rule class=madda_normal>ِۦ</rule> نَبَاتُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَأَصۡبَحَ هَشِي<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ت</rule>َذۡرُوهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حُ‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَدِرًا ٤٥',
    45, 15, 4, 298, 257, 119, 'false'
  );
  
  -- Ayah 46 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2186,
    'ٱلۡمَالُ وَٱلۡبَنُونَ زِینَةُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَٱلۡبَـٰقِیَـٰتُ ٱلصَّـٰلِحَـٰتُ خَیۡرٌ عِندَ رَبِّكَ ثَوَابࣰا وَخَیۡرٌ أَمَلࣰا',
    'المال والبنون زينة الحياة الدنيا والباقيات الصالحات خير عند ربك ثوابا وخير املا',
    'ٱلۡمَالُ وَ<rule class=ham_wasl>ٱ</rule>لۡبَنُونَ زِينَةُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>قِيَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تُ خَيۡرٌ عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ ثَوَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َخَيۡرٌ أَمَلاً ٤٦',
    46, 15, 4, 299, 257, 119, 'false'
  );
  
  -- Ayah 47 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2187,
    'وَیَوۡمَ نُسَیِّرُ ٱلۡجِبَالَ وَتَرَى ٱلۡأَرۡضَ بَارِزَةࣰ وَحَشَرۡنَـٰهُمۡ فَلَمۡ نُغَادِرۡ مِنۡهُمۡ أَحَدࣰا',
    'ويوم نسير الجبال وترى الارض بارزة وحشرناهم فلم نغادر منهم احدا',
    'وَيَوۡمَ نُسَيِّرُ <rule class=ham_wasl>ٱ</rule>لۡجِبَالَ وَتَرَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَارِزَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َحَشَرۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فَلَمۡ نُغَادِرۡ مِنۡهُمۡ أَحَدًا ٤٧',
    47, 15, 4, 299, 257, 119, 'false'
  );
  
  -- Ayah 48 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2188,
    'وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفࣰّا لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَـٰكُمۡ أَوَّلَ مَرَّةِۭۚ بَلۡ زَعَمۡتُمۡ أَلَّن نَّجۡعَلَ لَكُم مَّوۡعِدࣰا',
    'وعرضوا على ربك صفا لقد جئتمونا كما خلقناكم اول مرة بل زعمتم الن نجعل لكم موعدا',
    'وَعُرِضُو<rule class=slnt>اۡ</rule> عَلَىٰ رَبِّكَ صَف<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّقَ<rule class=qalaqah>دۡ</rule> جِئۡتُمُونَا كَمَا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ أَوَّلَ مَرَّ<rule class=iqlab>ةِۭ‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ زَعَمۡتُمۡ أَلّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>جۡ</rule>عَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوۡعِدًا ٤٨',
    48, 15, 4, 299, 257, 119, 'false'
  );
  
  -- Ayah 49 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2189,
    'وَوُضِعَ ٱلۡكِتَـٰبُ فَتَرَى ٱلۡمُجۡرِمِینَ مُشۡفِقِینَ مِمَّا فِیهِ وَیَقُولُونَ یَـٰوَیۡلَتَنَا مَالِ هَـٰذَا ٱلۡكِتَـٰبِ لَا یُغَادِرُ صَغِیرَةࣰ وَلَا كَبِیرَةً إِلَّاۤ أَحۡصَىٰهَاۚ وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرࣰاۗ وَلَا یَظۡلِمُ رَبُّكَ أَحَدࣰا',
    'ووضع الكتاب فترى المجرمين مشفقين مما فيه ويقولون يا ويلتنا مال هذا الكتاب لا يغادر صغيرة ولا كبيرة الا احصاها ووجدوا ما عملوا حاضرا ولا يظلم ربك احدا',
    'وَوُضِعَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بُ فَتَرَى <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ مُشۡفِقِينَ مِ<rule class=ghunnah>مّ</rule>َا فِيهِ وَيَقُولُونَ يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَتَنَا مَالِ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَا يُغَادِرُ صَغِيرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا كَبِيرَةً إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَحۡصَ<rule class=madda_normal>ـٰ</rule>هَا‌ۚ وَوَجَدُو<rule class=slnt>اۡ</rule> مَا عَمِلُو<rule class=slnt>اۡ</rule> حَاضِ<rule class=idgham_ghunnah>رًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَظۡلِمُ رَبُّكَ أَحَدًا ٤٩',
    49, 15, 4, 299, 257, 119, 'false'
  );
  
  -- Ayah 50 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2190,
    'وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦۤۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّیَّتَهُۥۤ أَوۡلِیَاۤءَ مِن دُونِی وَهُمۡ لَكُمۡ عَدُوُّۢۚ بِئۡسَ لِلظَّـٰلِمِینَ بَدَلࣰا',
    'واذ قلنا للملائكة اسجدوا لادم فسجدوا الا ابليس كان من الجن ففسق عن امر ربه افتتخذونه وذريته اولياء من دوني وهم لكم عدو بئس للظالمين بدلا',
    'وَإِذۡ قُلۡنَا لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ <rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> لِأَدَمَ فَسَجَد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>لِيسَ كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ فَفَسَقَ عَنۡ أَمۡرِ رَبِّه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> أَفَتَتَّخِذُونَهُ<rule class=madda_normal>ۥ</rule> وَذُرِّيَّتَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِى وَهُمۡ لَكُمۡ عَدُو<rule class=iqlab>ُّۢ‌ۚ</rule> <rule class=iqlab>ب</rule>ِئۡسَ لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ بَدَلاً ٥٠',
    50, 15, 4, 299, 258, 119, 'false'
  );
  
  -- Ayah 51 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2191,
    '۞ مَّاۤ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَلَا خَلۡقَ أَنفُسِهِمۡ وَمَا كُنتُ مُتَّخِذَ ٱلۡمُضِلِّینَ عَضُدࣰا',
    'ما اشهدتهم خلق السماوات والارض ولا خلق انفسهم وما كنت متخذ المضلين عضدا',
    '۞مّ<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡهَ<rule class=idgham_mutajanisayn>د</rule>تُّهُمۡ خَلۡقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا خَلۡقَ أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ وَمَا كُ<rule class=ikhafa>نت</rule>ُ مُتَّخِذَ <rule class=ham_wasl>ٱ</rule>لۡمُضِلِّينَ عَضُدًا ٥١',
    51, 15, 4, 299, 258, 120, 'false'
  );
  
  -- Ayah 52 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2192,
    'وَیَوۡمَ یَقُولُ نَادُوا۟ شُرَكَاۤءِیَ ٱلَّذِینَ زَعَمۡتُمۡ فَدَعَوۡهُمۡ فَلَمۡ یَسۡتَجِیبُوا۟ لَهُمۡ وَجَعَلۡنَا بَیۡنَهُم مَّوۡبِقࣰا',
    'ويوم يقول نادوا شركائي الذين زعمتم فدعوهم فلم يستجيبوا لهم وجعلنا بينهم موبقا',
    'وَيَوۡمَ يَقُولُ نَادُو<rule class=slnt>اۡ</rule> شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ زَعَمۡتُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُو<rule class=slnt>اۡ</rule> لَهُمۡ وَجَعَلۡنَا بَيۡنَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوۡبِقًا ٥٢',
    52, 15, 4, 299, 258, 120, 'false'
  );
  
  -- Ayah 53 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2193,
    'وَرَءَا ٱلۡمُجۡرِمُونَ ٱلنَّارَ فَظَنُّوۤا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمۡ یَجِدُوا۟ عَنۡهَا مَصۡرِفࣰا',
    'وراى المجرمون النار فظنوا انهم مواقعوها ولم يجدوا عنها مصرفا',
    'وَرَءَا <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ فَظَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوَاقِعُوهَا وَلَمۡ يَجِدُو<rule class=slnt>اۡ</rule> عَنۡهَا مَصۡرِفًا ٥٣',
    53, 15, 4, 299, 258, 120, 'false'
  );
  
  -- Ayah 54 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2194,
    'وَلَقَدۡ صَرَّفۡنَا فِی هَـٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلࣲۚ وَكَانَ ٱلۡإِنسَـٰنُ أَكۡثَرَ شَیۡءࣲ جَدَلࣰا',
    'ولقد صرفنا في هذا القران للناس من كل مثل وكان الانسان اكثر شيء جدلا',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> صَرَّفۡنَا فِى هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ لِل<rule class=ghunnah>نّ</rule>َاسِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مَثَ<rule class=idgham_ghunnah>لٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ أَكۡثَرَ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ج</rule>َدَلاً ٥٤',
    54, 15, 4, 300, 259, 120, 'false'
  );
  
  -- Ayah 55 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2195,
    'وَمَا مَنَعَ ٱلنَّاسَ أَن یُؤۡمِنُوۤا۟ إِذۡ جَاۤءَهُمُ ٱلۡهُدَىٰ وَیَسۡتَغۡفِرُوا۟ رَبَّهُمۡ إِلَّاۤ أَن تَأۡتِیَهُمۡ سُنَّةُ ٱلۡأَوَّلِینَ أَوۡ یَأۡتِیَهُمُ ٱلۡعَذَابُ قُبُلࣰا',
    'وما منع الناس ان يؤمنوا اذ جاءهم الهدى ويستغفروا ربهم الا ان تاتيهم سنة الاولين او ياتيهم العذاب قبلا',
    'وَمَا مَنَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَيَسۡتَغۡفِرُو<rule class=slnt>اۡ</rule> رَبَّهُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡتِيَهُمۡ سُ<rule class=ghunnah>نّ</rule>َةُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّلِينَ أَوۡ يَأۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ قُبُلاً ٥٥',
    55, 15, 4, 300, 259, 120, 'false'
  );
  
  -- Ayah 56 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2196,
    'وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِینَ إِلَّا مُبَشِّرِینَ وَمُنذِرِینَۚ وَیُجَـٰدِلُ ٱلَّذِینَ كَفَرُوا۟ بِٱلۡبَـٰطِلِ لِیُدۡحِضُوا۟ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوۤا۟ ءَایَـٰتِی وَمَاۤ أُنذِرُوا۟ هُزُوࣰا',
    'وما نرسل المرسلين الا مبشرين ومنذرين ويجادل الذين كفروا بالباطل ليدحضوا به الحق واتخذوا اياتي وما انذروا هزوا',
    'وَمَا نُرۡسِلُ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُ<rule class=ikhafa>نذ</rule>ِرِينَ‌ۚ وَيُجَ<rule class=madda_normal>ـٰ</rule>دِلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ لِيُ<rule class=qalaqah>دۡ</rule>حِضُو<rule class=slnt>اۡ</rule> بِهِ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>تَّخَذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِى وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نذ</rule>ِرُو<rule class=slnt>اۡ</rule> هُزُوًا ٥٦',
    56, 15, 4, 300, 259, 120, 'false'
  );
  
  -- Ayah 57 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2197,
    'وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔایَـٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِیَ مَا قَدَّمَتۡ یَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن یَفۡقَهُوهُ وَفِیۤ ءَاذَانِهِمۡ وَقۡرࣰاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن یَهۡتَدُوۤا۟ إِذًا أَبَدࣰا',
    'ومن اظلم ممن ذكر بايات ربه فاعرض عنها ونسي ما قدمت يداه انا جعلنا على قلوبهم اكنة ان يفقهوه وفي اذانهم وقرا وان تدعهم الى الهدى فلن يهتدوا اذا ابدا',
    'وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُكِّرَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّه<rule class=madda_normal>ِۦ</rule> فَأَعۡرَضَ عَنۡهَا وَنَسِىَ مَا قَدَّمَتۡ يَدَاهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِ<rule class=ghunnah>نّ</rule>َةً أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡقَهُوهُ وَف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاذَانِهِمۡ وَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>عُهُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ فَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡتَد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذًا أَبَدًا ٥٧',
    57, 15, 4, 300, 259, 120, 'false'
  );
  
  -- Ayah 58 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2198,
    'وَرَبُّكَ ٱلۡغَفُورُ ذُو ٱلرَّحۡمَةِۖ لَوۡ یُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلۡعَذَابَۚ بَل لَّهُم مَّوۡعِدࣱ لَّن یَجِدُوا۟ مِن دُونِهِۦ مَوۡىِٕلࣰا',
    'وربك الغفور ذو الرحمة لو يؤاخذهم بما كسبوا لعجل لهم العذاب بل لهم موعد لن يجدوا من دونه موئلا',
    'وَرَبُّكَ <rule class=ham_wasl>ٱ</rule>لۡغَفُورُ ذُو <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَةِ‌ۖ لَوۡ يُؤَاخِذُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَسَبُو<rule class=slnt>اۡ</rule> لَعَجَّلَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ‌ۚ بَل لَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوۡعِ<rule class=idgham_wo_ghunnah>دٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َجِدُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> مَوۡئِلاً ٥٨',
    58, 15, 4, 300, 259, 120, 'false'
  );
  
  -- Ayah 59 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2199,
    'وَتِلۡكَ ٱلۡقُرَىٰۤ أَهۡلَكۡنَـٰهُمۡ لَمَّا ظَلَمُوا۟ وَجَعَلۡنَا لِمَهۡلِكِهِم مَّوۡعِدࣰا',
    'وتلك القرى اهلكناهم لما ظلموا وجعلنا لمهلكهم موعدا',
    'وَتِلۡكَ <rule class=ham_wasl>ٱ</rule>لۡقُرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ لَ<rule class=ghunnah>مّ</rule>َا ظَلَمُو<rule class=slnt>اۡ</rule> وَجَعَلۡنَا لِمَهۡلِكِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّوۡعِدًا ٥٩',
    59, 15, 4, 300, 259, 120, 'false'
  );
  
  -- Ayah 60 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2200,
    'وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَاۤ أَبۡرَحُ حَتَّىٰۤ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَیۡنِ أَوۡ أَمۡضِیَ حُقُبࣰا',
    'واذ قال موسى لفتاه لا ابرح حتى ابلغ مجمع البحرين او امضي حقبا',
    'وَإِذۡ قَالَ مُوسَىٰ لِفَتَ<rule class=madda_normal>ـٰ</rule>هُ ل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>رَحُ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=qalaqah>بۡ</rule>لُغَ مَ<rule class=qalaqah>جۡ</rule>مَعَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَيۡنِ أَوۡ أَمۡضِىَ حُقُبًا ٦٠',
    60, 15, 4, 300, 260, 120, 'false'
  );
  
  -- Ayah 61 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2201,
    'فَلَمَّا بَلَغَا مَجۡمَعَ بَیۡنِهِمَا نَسِیَا حُوتَهُمَا فَٱتَّخَذَ سَبِیلَهُۥ فِی ٱلۡبَحۡرِ سَرَبࣰا',
    'فلما بلغا مجمع بينهما نسيا حوتهما فاتخذ سبيله في البحر سربا',
    'فَلَ<rule class=ghunnah>مّ</rule>َا بَلَغَا مَ<rule class=qalaqah>جۡ</rule>مَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَ<rule class=ham_wasl>ٱ</rule>تَّخَذَ سَبِيلَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ سَرَبًا ٦١',
    61, 15, 4, 300, 260, 120, 'false'
  );
  
  -- Ayah 62 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2202,
    'فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَاۤءَنَا لَقَدۡ لَقِینَا مِن سَفَرِنَا هَـٰذَا نَصَبࣰا',
    'فلما جاوزا قال لفتاه اتنا غداءنا لقد لقينا من سفرنا هذا نصبا',
    'فَلَ<rule class=ghunnah>مّ</rule>َا جَاوَزَا قَالَ لِفَتَ<rule class=madda_normal>ـٰ</rule>هُ ءَاتِنَا غَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا لَقَ<rule class=qalaqah>دۡ</rule> لَقِينَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َفَرِنَا هَ<rule class=madda_normal>ـٰ</rule>ذَا نَصَبًا ٦٢',
    62, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 63 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2203,
    'قَالَ أَرَءَیۡتَ إِذۡ أَوَیۡنَاۤ إِلَى ٱلصَّخۡرَةِ فَإِنِّی نَسِیتُ ٱلۡحُوتَ وَمَاۤ أَنسَىٰنِیهُ إِلَّا ٱلشَّیۡطَـٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِیلَهُۥ فِی ٱلۡبَحۡرِ عَجَبࣰا',
    'قال ارايت اذ اوينا الى الصخرة فاني نسيت الحوت وما انسانيه الا الشيطان ان اذكره واتخذ سبيله في البحر عجبا',
    'قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّخۡرَةِ فَإِ<rule class=ghunnah>نّ</rule>ِى نَسِيتُ <rule class=ham_wasl>ٱ</rule>لۡحُوتَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡسَ<rule class=madda_normal>ـٰ</rule>نِيهُ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ أَنۡ أَذۡكُرَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّخَذَ سَبِيلَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ عَجَبًا ٦٣',
    63, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 64 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2204,
    'قَالَ ذَ ٰ⁠لِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰۤ ءَاثَارِهِمَا قَصَصࣰا',
    'قال ذلك ما كنا نبغ فارتدا على اثارهما قصصا',
    'قَالَ ذ<rule class=madda_normal>ٰ</rule>لِكَ مَا كُ<rule class=ghunnah>نّ</rule>َا نَ<rule class=qalaqah>بۡ</rule>غِ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>رۡتَدَّا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاثَارِهِمَا قَصَصًا ٦٤',
    64, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 65 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2205,
    'فَوَجَدَا عَبۡدࣰا مِّنۡ عِبَادِنَاۤ ءَاتَیۡنَـٰهُ رَحۡمَةࣰ مِّنۡ عِندِنَا وَعَلَّمۡنَـٰهُ مِن لَّدُنَّا عِلۡمࣰا',
    'فوجدا عبدا من عبادنا اتيناه رحمة من عندنا وعلمناه من لدنا علما',
    'فَوَجَدَا عَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِبَادِن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِنَا وَعَلَّمۡنَ<rule class=madda_normal>ـٰ</rule>هُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ghunnah>نّ</rule>َا عِلۡمًا ٦٥',
    65, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 66 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2206,
    'قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰۤ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدࣰا',
    'قال له موسى هل اتبعك على ان تعلمن مما علمت رشدا',
    'قَالَ لَهُ<rule class=madda_normal>ۥ</rule> مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُعَلِّمَنِ مِ<rule class=ghunnah>مّ</rule>َا عُلِّمۡتَ رُشۡدًا ٦٦',
    66, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 67 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2207,
    'قَالَ إِنَّكَ لَن تَسۡتَطِیعَ مَعِیَ صَبۡرࣰا',
    'قال انك لن تستطيع معي صبرا',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َكَ لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَطِيعَ مَعِىَ صَ<rule class=qalaqah>بۡ</rule>رًا ٦٧',
    67, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 68 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2208,
    'وَكَیۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرࣰا',
    'وكيف تصبر على ما لم تحط به خبرا',
    'وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِ<rule class=qalaqah>طۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> خُ<rule class=qalaqah>بۡ</rule>رًا ٦٨',
    68, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 69 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2209,
    'قَالَ سَتَجِدُنِیۤ إِن شَاۤءَ ٱللَّهُ صَابِرࣰا وَلَاۤ أَعۡصِی لَكَ أَمۡرࣰا',
    'قال ستجدني ان شاء الله صابرا ولا اعصي لك امرا',
    'قَالَ سَتَجِدُن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ صَابِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َل<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡصِى لَكَ أَمۡرًا ٦٩',
    69, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 70 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2210,
    'قَالَ فَإِنِ ٱتَّبَعۡتَنِی فَلَا تَسۡـَٔلۡنِی عَن شَیۡءٍ حَتَّىٰۤ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرࣰا',
    'قال فان اتبعتني فلا تسالني عن شيء حتى احدث لك منه ذكرا',
    'قَالَ فَإِنِ <rule class=ham_wasl>ٱ</rule>تَّبَعۡتَنِى فَلَا تَسۡــَٔلۡنِى عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرًا ٧٠',
    70, 15, 4, 301, 260, 120, 'false'
  );
  
  -- Ayah 71 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2211,
    'فَٱنطَلَقَا حَتَّىٰۤ إِذَا رَكِبَا فِی ٱلسَّفِینَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَیۡـًٔا إِمۡرࣰا',
    'فانطلقا حتى اذا ركبا في السفينة خرقها قال اخرقتها لتغرق اهلها لقد جئت شيئا امرا',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نط</rule>َلَقَا حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا رَكِبَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّفِينَةِ خَرَقَهَا‌ۖ قَالَ أَخَرَ<rule class=qalaqah>قۡ</rule>تَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَ<rule class=qalaqah>دۡ</rule> جِئۡتَ شَيۡــًٔا إِمۡرًا ٧١',
    71, 15, 4, 301, 261, 120, 'false'
  );
  
  -- Ayah 72 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2212,
    'قَالَ أَلَمۡ أَقُلۡ إِنَّكَ لَن تَسۡتَطِیعَ مَعِیَ صَبۡرࣰا',
    'قال الم اقل انك لن تستطيع معي صبرا',
    'قَالَ أَلَمۡ أَقُلۡ إِ<rule class=ghunnah>نّ</rule>َكَ لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَطِيعَ مَعِىَ صَ<rule class=qalaqah>بۡ</rule>رًا ٧٢',
    72, 15, 4, 301, 261, 120, 'false'
  );
  
  -- Ayah 73 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2213,
    'قَالَ لَا تُؤَاخِذۡنِی بِمَا نَسِیتُ وَلَا تُرۡهِقۡنِی مِنۡ أَمۡرِی عُسۡرࣰا',
    'قال لا تؤاخذني بما نسيت ولا ترهقني من امري عسرا',
    'قَالَ لَا تُؤَاخِذۡنِى بِمَا نَسِيتُ وَلَا تُرۡهِ<rule class=qalaqah>قۡ</rule>نِى مِنۡ أَمۡرِى عُسۡرًا ٧٣',
    73, 15, 4, 301, 261, 120, 'false'
  );
  
  -- Ayah 74 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2214,
    'فَٱنطَلَقَا حَتَّىٰۤ إِذَا لَقِیَا غُلَـٰمࣰا فَقَتَلَهُۥ قَالَ أَقَتَلۡتَ نَفۡسࣰا زَكِیَّةَۢ بِغَیۡرِ نَفۡسࣲ لَّقَدۡ جِئۡتَ شَیۡـࣰٔا نُّكۡرࣰا',
    'فانطلقا حتى اذا لقيا غلاما فقتله قال اقتلت نفسا زكية بغير نفس لقد جئت شيئا نكرا',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نط</rule>َلَقَا حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا لَقِيَا غُلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َقَتَلَهُ<rule class=madda_normal>ۥ</rule> قَالَ أَقَتَلۡتَ نَفۡ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ز</rule>َكِيَّ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>ِغَيۡرِ نَفۡ<rule class=idgham_wo_ghunnah>سٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّقَ<rule class=qalaqah>دۡ</rule> جِئۡتَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>ن</rule>ُّكۡرًا ٧٤',
    74, 15, 4, 301, 261, 120, 'false'
  );
  
  -- Ayah 75 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2215,
    '۞ قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِیعَ مَعِیَ صَبۡرࣰا',
    'قال الم اقل لك انك لن تستطيع معي صبرا',
    '۞قَالَ أَلَمۡ أَقُل لَّكَ إِ<rule class=ghunnah>نّ</rule>َكَ لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡتَطِيعَ مَعِىَ صَ<rule class=qalaqah>بۡ</rule>رًا ٧٥',
    75, 16, 4, 302, 261, 121, 'false'
  );
  
  -- Ayah 76 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2216,
    'قَالَ إِن سَأَلۡتُكَ عَن شَیۡءِۭ بَعۡدَهَا فَلَا تُصَـٰحِبۡنِیۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّی عُذۡرࣰا',
    'قال ان سالتك عن شيء بعدها فلا تصاحبني قد بلغت من لدني عذرا',
    'قَالَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َأَلۡتُكَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡ<rule class=iqlab>ءِۭ</rule> <rule class=iqlab>ب</rule>َعۡدَهَا فَلَا تُصَ<rule class=madda_normal>ـٰ</rule>حِ<rule class=qalaqah>بۡ</rule>نِى‌ۖ قَ<rule class=qalaqah>دۡ</rule> بَلَغۡتَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ghunnah>نّ</rule>ِى عُذۡرًا ٧٦',
    76, 16, 4, 302, 261, 121, 'false'
  );
  
  -- Ayah 77 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2217,
    'فَٱنطَلَقَا حَتَّىٰۤ إِذَاۤ أَتَیَاۤ أَهۡلَ قَرۡیَةٍ ٱسۡتَطۡعَمَاۤ أَهۡلَهَا فَأَبَوۡا۟ أَن یُضَیِّفُوهُمَا فَوَجَدَا فِیهَا جِدَارࣰا یُرِیدُ أَن یَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَیۡهِ أَجۡرࣰا',
    'فانطلقا حتى اذا اتيا اهل قرية استطعما اهلها فابوا ان يضيفوهما فوجدا فيها جدارا يريد ان ينقض فاقامه قال لو شئت لاتخذت عليه اجرا',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نط</rule>َلَقَا حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَتَي<rule class=madda_obligatory_monfasel>َآ</rule> أَهۡلَ قَرۡيَةٍ <rule class=ham_wasl>ٱ</rule>سۡتَ<rule class=qalaqah>طۡ</rule>عَم<rule class=madda_obligatory_monfasel>َآ</rule> أَهۡلَهَا فَأَبَوۡ<rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضَيِّفُوهُمَا فَوَجَدَا فِيهَا جِدَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نق</rule>َضَّ فَأَقَامَهُ<rule class=madda_normal>ۥ</rule>‌ۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَيۡهِ أَ<rule class=qalaqah>جۡ</rule>رًا ٧٧',
    77, 16, 4, 302, 261, 121, 'false'
  );
  
  -- Ayah 78 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2218,
    'قَالَ هَـٰذَا فِرَاقُ بَیۡنِی وَبَیۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِیلِ مَا لَمۡ تَسۡتَطِع عَّلَیۡهِ صَبۡرًا',
    'قال هذا فراق بيني وبينك سانبئك بتاويل ما لم تستطع عليه صبرا',
    'قَالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا فِرَاقُ بَيۡنِى وَبَيۡنِكَ‌ۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَ<rule class=qalaqah>بۡ</rule>رًا ٧٨',
    78, 16, 4, 302, 261, 121, 'false'
  );
  
  -- Ayah 79 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2219,
    'أَمَّا ٱلسَّفِینَةُ فَكَانَتۡ لِمَسَـٰكِینَ یَعۡمَلُونَ فِی ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِیبَهَا وَكَانَ وَرَاۤءَهُم مَّلِكࣱ یَأۡخُذُ كُلَّ سَفِینَةٍ غَصۡبࣰا',
    'اما السفينة فكانت لمساكين يعملون في البحر فاردت ان اعيبها وكان وراءهم ملك ياخذ كل سفينة غصبا',
    'أَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّفِينَةُ فَكَانَتۡ لِمَسَ<rule class=madda_normal>ـٰ</rule>كِينَ يَعۡمَلُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ فَأَرَ<rule class=idgham_mutajanisayn>د</rule>تُّ أَنۡ أَعِيبَهَا وَكَانَ وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّلِ<rule class=idgham_ghunnah>كٌ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡخُذُ كُلَّ سَفِينَةٍ غَصۡبًا ٧٩',
    79, 16, 4, 302, 261, 121, 'false'
  );
  
  -- Ayah 80 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2220,
    'وَأَمَّا ٱلۡغُلَـٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَیۡنِ فَخَشِینَاۤ أَن یُرۡهِقَهُمَا طُغۡیَـٰنࣰا وَكُفۡرࣰا',
    'واما الغلام فكان ابواه مؤمنين فخشينا ان يرهقهما طغيانا وكفرا',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡغُلَ<rule class=madda_normal>ـٰ</rule>مُ فَكَانَ أَبَوَاهُ مُؤۡمِنَيۡنِ فَخَشِين<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرۡهِقَهُمَا طُغۡيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َكُفۡرًا ٨٠',
    80, 16, 4, 302, 261, 121, 'false'
  );
  
  -- Ayah 81 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2221,
    'فَأَرَدۡنَاۤ أَن یُبۡدِلَهُمَا رَبُّهُمَا خَیۡرࣰا مِّنۡهُ زَكَوٰةࣰ وَأَقۡرَبَ رُحۡمࣰا',
    'فاردنا ان يبدلهما ربهما خيرا منه زكاة واقرب رحما',
    'فَأَرَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>بۡ</rule>دِلَهُمَا رَبُّهُمَا خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ زَكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>قۡ</rule>رَبَ رُحۡمًا ٨١',
    81, 16, 4, 302, 261, 121, 'false'
  );
  
  -- Ayah 82 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2222,
    'وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَـٰمَیۡنِ یَتِیمَیۡنِ فِی ٱلۡمَدِینَةِ وَكَانَ تَحۡتَهُۥ كَنزࣱ لَّهُمَا وَكَانَ أَبُوهُمَا صَـٰلِحࣰا فَأَرَادَ رَبُّكَ أَن یَبۡلُغَاۤ أَشُدَّهُمَا وَیَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةࣰ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِیۚ ذَ ٰ⁠لِكَ تَأۡوِیلُ مَا لَمۡ تَسۡطِع عَّلَیۡهِ صَبۡرࣰا',
    'واما الجدار فكان لغلامين يتيمين في المدينة وكان تحته كنز لهما وكان ابوهما صالحا فاراد ربك ان يبلغا اشدهما ويستخرجا كنزهما رحمة من ربك وما فعلته عن امري ذلك تاويل ما لم تسطع عليه صبرا',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡجِدَارُ فَكَانَ لِغُلَ<rule class=madda_normal>ـٰ</rule>مَيۡنِ يَتِيمَيۡنِ فِى <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ وَكَانَ تَحۡتَهُ<rule class=madda_normal>ۥ</rule> كَن<rule class=idgham_wo_ghunnah>زٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمَا وَكَانَ أَبُوهُمَا صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َأَرَادَ رَبُّكَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>لُغ<rule class=madda_obligatory_monfasel>َآ</rule> أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَ<rule class=ikhafa>نز</rule>َهُمَا رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۚ وَمَا فَعَلۡتُهُ<rule class=madda_normal>ۥ</rule> عَنۡ أَمۡرِى‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَ<rule class=qalaqah>بۡ</rule>رًا ٨٢',
    82, 16, 4, 302, 261, 121, 'false'
  );
  
  -- Ayah 83 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2223,
    'وَیَسۡـَٔلُونَكَ عَن ذِی ٱلۡقَرۡنَیۡنِۖ قُلۡ سَأَتۡلُوا۟ عَلَیۡكُم مِّنۡهُ ذِكۡرًا',
    'ويسالونك عن ذي القرنين قل ساتلو عليكم منه ذكرا',
    'وَيَسۡــَٔلُونَكَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡقَرۡنَيۡنِ‌ۖ قُلۡ سَأَتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ ذِكۡرًا ٨٣',
    83, 16, 4, 302, 262, 121, 'false'
  );
  
  -- Ayah 84 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2224,
    'إِنَّا مَكَّنَّا لَهُۥ فِی ٱلۡأَرۡضِ وَءَاتَیۡنَـٰهُ مِن كُلِّ شَیۡءࣲ سَبَبࣰا',
    'انا مكنا له في الارض واتيناه من كل شيء سببا',
    'إِ<rule class=ghunnah>نّ</rule>َا مَكَّ<rule class=ghunnah>نّ</rule>َا لَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>س</rule>َبَبًا ٨٤',
    84, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 85 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2225,
    'فَأَتۡبَعَ سَبَبًا',
    'فاتبع سببا',
    'فَأَتۡبَعَ سَبَبًا ٨٥',
    85, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 86 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2226,
    'حَتَّىٰۤ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِی عَیۡنٍ حَمِئَةࣲ وَوَجَدَ عِندَهَا قَوۡمࣰاۖ قُلۡنَا یَـٰذَا ٱلۡقَرۡنَیۡنِ إِمَّاۤ أَن تُعَذِّبَ وَإِمَّاۤ أَن تَتَّخِذَ فِیهِمۡ حُسۡنࣰا',
    'حتى اذا بلغ مغرب الشمس وجدها تغرب في عين حمئة ووجد عندها قوما قلنا يا ذا القرنين اما ان تعذب واما ان تتخذ فيهم حسنا',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا بَلَغَ مَغۡرِبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسِ وَجَدَهَا تَغۡرُبُ فِى عَيۡنٍ حَمِئَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َوَجَدَ عِ<rule class=ikhafa>ند</rule>َهَا قَوۡ<rule class=ikhafa>مًا‌ۗ</rule> <rule class=ikhafa>ق</rule>ُلۡنَا يَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقَرۡنَيۡنِ إِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُعَذِّبَ وَإِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَّخِذَ فِيهِمۡ حُسۡنًا ٨٦',
    86, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 87 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2227,
    'قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ یُرَدُّ إِلَىٰ رَبِّهِۦ فَیُعَذِّبُهُۥ عَذَابࣰا نُّكۡرࣰا',
    'قال اما من ظلم فسوف نعذبه ثم يرد الى ربه فيعذبه عذابا نكرا',
    'قَالَ أَ<rule class=ghunnah>مّ</rule>َا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>َلَمَ فَسَوۡفَ نُعَذِّبُهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ يُرَدُّ إِلَىٰ رَبِّه<rule class=madda_normal>ِۦ</rule> فَيُعَذِّبُهُ<rule class=madda_normal>ۥ</rule> عَذَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>ن</rule>ُّكۡرًا ٨٧',
    87, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 88 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2228,
    'وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَلَهُۥ جَزَاۤءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا یُسۡرࣰا',
    'واما من امن وعمل صالحا فله جزاء الحسنى وسنقول له من امرنا يسرا',
    'وَأَ<rule class=ghunnah>مّ</rule>َا مَنۡ ءَامَنَ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َلَهُ<rule class=madda_normal>ۥ</rule> جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءً <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ‌ۖ وَسَنَقُولُ لَهُ<rule class=madda_normal>ۥ</rule> مِنۡ أَمۡرِنَا يُسۡرًا ٨٨',
    88, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 89 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2229,
    'ثُمَّ أَتۡبَعَ سَبَبًا',
    'ثم اتبع سببا',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَتۡبَعَ سَبَبًا ٨٩',
    89, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 90 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2230,
    'حَتَّىٰۤ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمࣲ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرࣰا',
    'حتى اذا بلغ مطلع الشمس وجدها تطلع على قوم لم نجعل لهم من دونها سترا',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا بَلَغَ مَ<rule class=qalaqah>طۡ</rule>لِعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسِ وَجَدَهَا تَ<rule class=qalaqah>طۡ</rule>لُعُ عَلَىٰ قَوۡ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ نَ<rule class=qalaqah>جۡ</rule>عَل لَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِهَا سِتۡرًا ٩٠',
    90, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 91 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2231,
    'كَذَ ٰ⁠لِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَیۡهِ خُبۡرࣰا',
    'كذلك وقد احطنا بما لديه خبرا',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ وَقَ<rule class=qalaqah>دۡ</rule> أَحَ<rule class=qalaqah>طۡ</rule>نَا بِمَا لَدَيۡهِ خُ<rule class=qalaqah>بۡ</rule>رًا ٩١',
    91, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 92 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2232,
    'ثُمَّ أَتۡبَعَ سَبَبًا',
    'ثم اتبع سببا',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَتۡبَعَ سَبَبًا ٩٢',
    92, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 93 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2233,
    'حَتَّىٰۤ إِذَا بَلَغَ بَیۡنَ ٱلسَّدَّیۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمࣰا لَّا یَكَادُونَ یَفۡقَهُونَ قَوۡلࣰا',
    'حتى اذا بلغ بين السدين وجد من دونهما قوما لا يكادون يفقهون قولا',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا بَلَغَ بَيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّدَّيۡنِ وَجَدَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِهِمَا قَوۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَكَادُونَ يَفۡقَهُونَ قَوۡلاً ٩٣',
    93, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 94 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2234,
    'قَالُوا۟ یَـٰذَا ٱلۡقَرۡنَیۡنِ إِنَّ یَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِی ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰۤ أَن تَجۡعَلَ بَیۡنَنَا وَبَیۡنَهُمۡ سَدࣰّا',
    'قالوا يا ذا القرنين ان ياجوج وماجوج مفسدون في الارض فهل نجعل لك خرجا على ان تجعل بيننا وبينهم سدا',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقَرۡنَيۡنِ إِ<rule class=ghunnah>نّ</rule>َ يَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَهَلۡ نَ<rule class=qalaqah>جۡ</rule>عَلُ لَكَ خَرۡجًا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>عَلَ بَيۡنَنَا وَبَيۡنَهُمۡ سَدًّا ٩٤',
    94, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 95 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2235,
    'قَالَ مَا مَكَّنِّی فِیهِ رَبِّی خَیۡرࣱ فَأَعِینُونِی بِقُوَّةٍ أَجۡعَلۡ بَیۡنَكُمۡ وَبَیۡنَهُمۡ رَدۡمًا',
    'قال ما مكني فيه ربي خير فاعينوني بقوة اجعل بينكم وبينهم ردما',
    'قَالَ مَا مَكَّ<rule class=ghunnah>نّ</rule>ِى فِيهِ رَبِّى خَيۡ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َأَعِينُونِى بِقُوَّةٍ أَ<rule class=qalaqah>جۡ</rule>عَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَ<rule class=qalaqah>دۡ</rule>مًا ٩٥',
    95, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 96 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2236,
    'ءَاتُونِی زُبَرَ ٱلۡحَدِیدِۖ حَتَّىٰۤ إِذَا سَاوَىٰ بَیۡنَ ٱلصَّدَفَیۡنِ قَالَ ٱنفُخُوا۟ۖ حَتَّىٰۤ إِذَا جَعَلَهُۥ نَارࣰا قَالَ ءَاتُونِیۤ أُفۡرِغۡ عَلَیۡهِ قِطۡرࣰا',
    'اتوني زبر الحديد حتى اذا ساوى بين الصدفين قال انفخوا حتى اذا جعله نارا قال اتوني افرغ عليه قطرا',
    'ءَاتُونِى زُبَرَ <rule class=ham_wasl>ٱ</rule>لۡحَدِيدِ‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا سَاوَىٰ بَيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّدَفَيۡنِ قَالَ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>ُخُو<rule class=slnt>اۡ‌ۖ</rule> حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا جَعَلَهُ<rule class=madda_normal>ۥ</rule> نَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ق</rule>َالَ ءَاتُون<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُفۡرِغۡ عَلَيۡهِ قِ<rule class=qalaqah>طۡ</rule>رًا ٩٦',
    96, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 97 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2237,
    'فَمَا ٱسۡطَـٰعُوۤا۟ أَن یَظۡهَرُوهُ وَمَا ٱسۡتَطَـٰعُوا۟ لَهُۥ نَقۡبࣰا',
    'فما اسطاعوا ان يظهروه وما استطاعوا له نقبا',
    'فَمَا <rule class=ham_wasl>ٱ</rule>سۡطَ<rule class=madda_normal>ـٰ</rule>ع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َظۡهَرُوهُ وَمَا <rule class=ham_wasl>ٱ</rule>سۡتَطَ<rule class=madda_normal>ـٰ</rule>عُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> نَ<rule class=qalaqah>قۡ</rule>بًا ٩٧',
    97, 16, 4, 303, 262, 121, 'false'
  );
  
  -- Ayah 98 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2238,
    'قَالَ هَـٰذَا رَحۡمَةࣱ مِّن رَّبِّیۖ فَإِذَا جَاۤءَ وَعۡدُ رَبِّی جَعَلَهُۥ دَكَّاۤءَۖ وَكَانَ وَعۡدُ رَبِّی حَقࣰّا',
    'قال هذا رحمة من ربي فاذا جاء وعد ربي جعله دكاء وكان وعد ربي حقا',
    'قَالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا رَحۡمَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّى‌ۖ فَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَعۡدُ رَبِّى جَعَلَهُ<rule class=madda_normal>ۥ</rule> دَكّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۖ وَكَانَ وَعۡدُ رَبِّى حَقًّا ٩٨',
    98, 16, 4, 304, 262, 121, 'false'
  );
  
  -- Ayah 99 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2239,
    '۞ وَتَرَكۡنَا بَعۡضَهُمۡ یَوۡمَىِٕذࣲ یَمُوجُ فِی بَعۡضࣲۖ وَنُفِخَ فِی ٱلصُّورِ فَجَمَعۡنَـٰهُمۡ جَمۡعࣰا',
    'وتركنا بعضهم يومئذ يموج في بعض ونفخ في الصور فجمعناهم جمعا',
    '۞وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َمُوجُ فِى بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َنُفِخَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ فَجَمَعۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ جَمۡعًا ٩٩',
    99, 16, 4, 304, 262, 122, 'false'
  );
  
  -- Ayah 100 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2240,
    'وَعَرَضۡنَا جَهَنَّمَ یَوۡمَىِٕذࣲ لِّلۡكَـٰفِرِینَ عَرۡضًا',
    'وعرضنا جهنم يومئذ للكافرين عرضا',
    'وَعَرَضۡنَا جَهَ<rule class=ghunnah>نّ</rule>َمَ يَوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَرۡضًا ١٠٠',
    100, 16, 4, 304, 262, 122, 'false'
  );
  
  -- Ayah 101 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2241,
    'ٱلَّذِینَ كَانَتۡ أَعۡیُنُهُمۡ فِی غِطَاۤءٍ عَن ذِكۡرِی وَكَانُوا۟ لَا یَسۡتَطِیعُونَ سَمۡعًا',
    'الذين كانت اعينهم في غطاء عن ذكري وكانوا لا يستطيعون سمعا',
    'ٱلَّذِينَ كَانَتۡ أَعۡيُنُهُمۡ فِى غِط<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِى وَكَانُو<rule class=slnt>اۡ</rule> لَا يَسۡتَطِيعُونَ سَمۡعًا ١٠١',
    101, 16, 4, 304, 262, 122, 'false'
  );
  
  -- Ayah 102 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2242,
    'أَفَحَسِبَ ٱلَّذِینَ كَفَرُوۤا۟ أَن یَتَّخِذُوا۟ عِبَادِی مِن دُونِیۤ أَوۡلِیَاۤءَۚ إِنَّاۤ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَـٰفِرِینَ نُزُلࣰا',
    'افحسب الذين كفروا ان يتخذوا عبادي من دوني اولياء انا اعتدنا جهنم للكافرين نزلا',
    'أَفَحَسِبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذُو<rule class=slnt>اۡ</rule> عِبَادِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُون<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَعۡتَ<rule class=qalaqah>دۡ</rule>نَا جَهَ<rule class=ghunnah>نّ</rule>َمَ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ نُزُلاً ١٠٢',
    102, 16, 4, 304, 263, 122, 'false'
  );
  
  -- Ayah 103 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2243,
    'قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِینَ أَعۡمَـٰلًا',
    'قل هل ننبئكم بالاخسرين اعمالا',
    'قُلۡ هَلۡ نُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأَخۡسَرِينَ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لاً ١٠٣',
    103, 16, 4, 304, 263, 122, 'false'
  );
  
  -- Ayah 104 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2244,
    'ٱلَّذِینَ ضَلَّ سَعۡیُهُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَهُمۡ یَحۡسَبُونَ أَنَّهُمۡ یُحۡسِنُونَ صُنۡعًا',
    'الذين ضل سعيهم في الحياة الدنيا وهم يحسبون انهم يحسنون صنعا',
    'ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَ<rule class=ghunnah>نّ</rule>َهُمۡ يُحۡسِنُونَ صُنۡعًا ١٠٤',
    104, 16, 4, 304, 263, 122, 'false'
  );
  
  -- Ayah 105 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2245,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ وَلِقَاۤىِٕهِۦ فَحَبِطَتۡ أَعۡمَـٰلُهُمۡ فَلَا نُقِیمُ لَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ وَزۡنࣰا',
    'اولئك الذين كفروا بايات ربهم ولقائه فحبطت اعمالهم فلا نقيم لهم يوم القيامة وزنا',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ وَلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِه<rule class=madda_normal>ِۦ</rule> فَحَبِطَتۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ وَزۡنًا ١٠٥',
    105, 16, 4, 304, 263, 122, 'false'
  );
  
  -- Ayah 106 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2246,
    'ذَ ٰ⁠لِكَ جَزَاۤؤُهُمۡ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوۤا۟ ءَایَـٰتِی وَرُسُلِی هُزُوًا',
    'ذلك جزاؤهم جهنم بما كفروا واتخذوا اياتي ورسلي هزوا',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ بِمَا كَفَرُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّخَذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِى وَرُسُلِى هُزُوًا ١٠٦',
    106, 16, 4, 304, 263, 122, 'false'
  );
  
  -- Ayah 107 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2247,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ كَانَتۡ لَهُمۡ جَنَّـٰتُ ٱلۡفِرۡدَوۡسِ نُزُلًا',
    'ان الذين امنوا وعملوا الصالحات كانت لهم جنات الفردوس نزلا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ كَانَتۡ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡفِرۡدَوۡسِ نُزُلاً ١٠٧',
    107, 16, 4, 304, 263, 122, 'false'
  );
  
  -- Ayah 108 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2248,
    'خَـٰلِدِینَ فِیهَا لَا یَبۡغُونَ عَنۡهَا حِوَلࣰا',
    'خالدين فيها لا يبغون عنها حولا',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا لَا يَ<rule class=qalaqah>بۡ</rule>غُونَ عَنۡهَا حِوَلاً ١٠٨',
    108, 16, 4, 304, 263, 122, 'false'
  );
  
  -- Ayah 109 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2249,
    'قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادࣰا لِّكَلِمَـٰتِ رَبِّی لَنَفِدَ ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَـٰتُ رَبِّی وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدࣰا',
    'قل لو كان البحر مدادا لكلمات ربي لنفد البحر قبل ان تنفد كلمات ربي ولو جئنا بمثله مددا',
    'قُل لَّوۡ كَانَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرُ مِدَا<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكَلِمَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّى لَنَفِدَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرُ قَ<rule class=qalaqah>بۡ</rule>لَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نف</rule>َدَ كَلِمَ<rule class=madda_normal>ـٰ</rule>تُ رَبِّى وَلَوۡ جِئۡنَا بِمِثۡلِه<rule class=madda_normal>ِۦ</rule> مَدَدًا ١٠٩',
    109, 16, 4, 304, 263, 122, 'false'
  );
  
  -- Ayah 110 Surah Al-Kahf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    18,
    2250,
    'قُلۡ إِنَّمَاۤ أَنَا۠ بَشَرࣱ مِّثۡلُكُمۡ یُوحَىٰۤ إِلَیَّ أَنَّمَاۤ إِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰ⁠حِدࣱۖ فَمَن كَانَ یَرۡجُوا۟ لِقَاۤءَ رَبِّهِۦ فَلۡیَعۡمَلۡ عَمَلࣰا صَـٰلِحࣰا وَلَا یُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦۤ أَحَدَۢا',
    'قل انما انا بشر مثلكم يوحى الي انما الهكم اله واحد فمن كان يرجو لقاء ربه فليعمل عملا صالحا ولا يشرك بعبادة ربه احدا',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُكُمۡ يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىَّ أَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هُكُمۡ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=ikhafa>دٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يَرۡجُو<rule class=slnt>اۡ</rule> لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبِّه<rule class=madda_normal>ِۦ</rule> فَلۡيَعۡمَلۡ عَمَل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ص</rule>َ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَحَدَۢا ١١٠',
    110, 16, 4, 304, 263, 122, 'false'
  );
  

-- Surah Maryam
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (19, 'سُورَةُ مَرۡيَمَ', 'Maryam', 'Mary', 'Meccan', 98);

  -- Ayah 1 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2251,
    'كۤهیعۤصۤ',
    'كهيعص',
    '<rule class=madda_necessary>كٓ</rule>هي<rule class=madda_necessary>عٓ</rule><rule class=madda_necessary>صٓ</rule> ١',
    1, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 2 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2252,
    'ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِیَّاۤ',
    'ذكر رحمت ربك عبده زكريا',
    'ذِكۡرُ رَحۡمَتِ رَبِّكَ عَ<rule class=qalaqah>بۡ</rule>دَهُ<rule class=madda_normal>ۥ</rule> زَكَرِيَّآ ٢',
    2, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 3 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2253,
    'إِذۡ نَادَىٰ رَبَّهُۥ نِدَاۤءً خَفِیࣰّا',
    'اذ نادى ربه نداء خفيا',
    'إِذۡ نَادَىٰ رَبَّهُ<rule class=madda_normal>ۥ</rule> نِد<rule class=madda_obligatory_mottasel>َا</rule>ٓءً خَفِيًّا ٣',
    3, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 4 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2254,
    'قَالَ رَبِّ إِنِّی وَهَنَ ٱلۡعَظۡمُ مِنِّی وَٱشۡتَعَلَ ٱلرَّأۡسُ شَیۡبࣰا وَلَمۡ أَكُنۢ بِدُعَاۤىِٕكَ رَبِّ شَقِیࣰّا',
    'قال رب اني وهن العظم مني واشتعل الراس شيبا ولم اكن بدعائك رب شقيا',
    'قَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى وَهَنَ <rule class=ham_wasl>ٱ</rule>لۡعَظۡمُ مِ<rule class=ghunnah>نّ</rule>ِى وَ<rule class=ham_wasl>ٱ</rule>شۡتَعَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّأۡسُ شَيۡ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ أَك<rule class=iqlab>ُنۢ</rule> <rule class=iqlab>ب</rule>ِدُع<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكَ رَبِّ شَقِيًّا ٤',
    4, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 5 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2255,
    'وَإِنِّی خِفۡتُ ٱلۡمَوَ ٰ⁠لِیَ مِن وَرَاۤءِی وَكَانَتِ ٱمۡرَأَتِی عَاقِرࣰا فَهَبۡ لِی مِن لَّدُنكَ وَلِیࣰّا',
    'واني خفت الموالي من ورائي وكانت امراتي عاقرا فهب لي من لدنك وليا',
    'وَإِ<rule class=ghunnah>نّ</rule>ِى خِفۡتُ <rule class=ham_wasl>ٱ</rule>لۡمَو<rule class=madda_normal>ٰ</rule>لِىَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِى وَكَانَتِ <rule class=ham_wasl>ٱ</rule>مۡرَأَتِى عَاقِ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َهَ<rule class=qalaqah>بۡ</rule> لِى م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ikhafa>نك</rule>َ وَلِيًّا ٥',
    5, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 6 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2256,
    'یَرِثُنِی وَیَرِثُ مِنۡ ءَالِ یَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِیࣰّا',
    'يرثني ويرث من ال يعقوب واجعله رب رضيا',
    'يَرِثُنِى وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡهُ رَبِّ رَضِيًّا ٦',
    6, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 7 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2257,
    'یَـٰزَكَرِیَّاۤ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ ٱسۡمُهُۥ یَحۡیَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِیࣰّا',
    'يا زكريا انا نبشرك بغلام اسمه يحيى لم نجعل له من قبل سميا',
    'يَ<rule class=madda_normal>ـٰ</rule>زَكَرِيّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا نُبَشِّرُكَ بِغُلَ<rule class=madda_normal>ـٰ</rule>مٍ <rule class=ham_wasl>ٱ</rule>سۡمُهُ<rule class=madda_normal>ۥ</rule> يَحۡيَىٰ لَمۡ نَ<rule class=qalaqah>جۡ</rule>عَل لَّهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ سَمِيًّا ٧',
    7, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 8 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2258,
    'قَالَ رَبِّ أَنَّىٰ یَكُونُ لِی غُلَـٰمࣱ وَكَانَتِ ٱمۡرَأَتِی عَاقِرࣰا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِیࣰّا',
    'قال رب انى يكون لي غلام وكانت امراتي عاقرا وقد بلغت من الكبر عتيا',
    'قَالَ رَبِّ أَ<rule class=ghunnah>نّ</rule>َىٰ يَكُونُ لِى غُلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَتِ <rule class=ham_wasl>ٱ</rule>مۡرَأَتِى عَاقِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َقَ<rule class=qalaqah>دۡ</rule> بَلَغۡتُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكِبَرِ عِتِيًّا ٨',
    8, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 9 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2259,
    'قَالَ كَذَ ٰ⁠لِكَ قَالَ رَبُّكَ هُوَ عَلَیَّ هَیِّنࣱ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ شَیۡـࣰٔا',
    'قال كذلك قال ربك هو علي هين وقد خلقتك من قبل ولم تك شيئا',
    'قَالَ كَذ<rule class=madda_normal>ٰ</rule>لِكَ قَالَ رَبُّكَ هُوَ عَلَىَّ هَيِّ<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>و</rule>َقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>تُكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَلَمۡ تَكُ شَيۡــًٔا ٩',
    9, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 10 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2260,
    'قَالَ رَبِّ ٱجۡعَل لِّیۤ ءَایَةࣰۖ قَالَ ءَایَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَ لَیَالࣲ سَوِیࣰّا',
    'قال رب اجعل لي اية قال ايتك الا تكلم الناس ثلاث ليال سويا',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَل لّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ق</rule>َالَ ءَايَتُكَ أَلَّا تُكَلِّمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَ لَيَا<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>س</rule>َوِيًّا ١٠',
    10, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 11 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2261,
    'فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰۤ إِلَیۡهِمۡ أَن سَبِّحُوا۟ بُكۡرَةࣰ وَعَشِیࣰّا',
    'فخرج على قومه من المحراب فاوحى اليهم ان سبحوا بكرة وعشيا',
    'فَخَرَجَ عَلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡمِحۡرَابِ فَأَوۡحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡهِمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِّحُو<rule class=slnt>اۡ</rule> بُكۡرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َعَشِيًّا ١١',
    11, 16, 4, 305, 264, 122, 'false'
  );
  
  -- Ayah 12 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2262,
    'یَـٰیَحۡیَىٰ خُذِ ٱلۡكِتَـٰبَ بِقُوَّةࣲۖ وَءَاتَیۡنَـٰهُ ٱلۡحُكۡمَ صَبِیࣰّا',
    'يا يحيى خذ الكتاب بقوة واتيناه الحكم صبيا',
    'يَ<rule class=madda_normal>ـٰ</rule>يَحۡيَىٰ خُذِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِقُوَّ<rule class=idgham_ghunnah>ةٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>لۡحُكۡمَ صَبِيًّا ١٢',
    12, 16, 4, 306, 264, 122, 'false'
  );
  
  -- Ayah 13 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2263,
    'وَحَنَانࣰا مِّن لَّدُنَّا وَزَكَوٰةࣰۖ وَكَانَ تَقِیࣰّا',
    'وحنانا من لدنا وزكاة وكان تقيا',
    'وَحَنَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ghunnah>نّ</rule>َا وَزَكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ تَقِيًّا ١٣',
    13, 16, 4, 306, 264, 122, 'false'
  );
  
  -- Ayah 14 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2264,
    'وَبَرَّۢا بِوَ ٰ⁠لِدَیۡهِ وَلَمۡ یَكُن جَبَّارًا عَصِیࣰّا',
    'وبرا بوالديه ولم يكن جبارا عصيا',
    'وَبَرّ<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِو<rule class=madda_normal>ٰ</rule>لِدَيۡهِ وَلَمۡ يَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َبَّارًا عَصِيًّا ١٤',
    14, 16, 4, 306, 264, 122, 'false'
  );
  
  -- Ayah 15 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2265,
    'وَسَلَـٰمٌ عَلَیۡهِ یَوۡمَ وُلِدَ وَیَوۡمَ یَمُوتُ وَیَوۡمَ یُبۡعَثُ حَیࣰّا',
    'وسلام عليه يوم ولد ويوم يموت ويوم يبعث حيا',
    'وَسَلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُ<rule class=qalaqah>بۡ</rule>عَثُ حَيًّا ١٥',
    15, 16, 4, 306, 264, 122, 'false'
  );
  
  -- Ayah 16 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2266,
    'وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ مَرۡیَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانࣰا شَرۡقِیࣰّا',
    'واذكر في الكتاب مريم اذ انتبذت من اهلها مكانا شرقيا',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مَرۡيَمَ إِذِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َبَذَتۡ مِنۡ أَهۡلِهَا مَكَا<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ش</rule>َرۡقِيًّا ١٦',
    16, 16, 4, 306, 265, 122, 'false'
  );
  
  -- Ayah 17 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2267,
    'فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابࣰا فَأَرۡسَلۡنَاۤ إِلَیۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرࣰا سَوِیࣰّا',
    'فاتخذت من دونهم حجابا فارسلنا اليها روحنا فتمثل لها بشرا سويا',
    'فَ<rule class=ham_wasl>ٱ</rule>تَّخَذَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِهِمۡ حِجَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َأَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>س</rule>َوِيًّا ١٧',
    17, 16, 4, 306, 265, 122, 'false'
  );
  
  -- Ayah 18 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2268,
    'قَالَتۡ إِنِّیۤ أَعُوذُ بِٱلرَّحۡمَـٰنِ مِنكَ إِن كُنتَ تَقِیࣰّا',
    'قالت اني اعوذ بالرحمن منك ان كنت تقيا',
    'قَالَتۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعُوذُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ مِ<rule class=ikhafa>نك</rule>َ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ تَقِيًّا ١٨',
    18, 16, 4, 306, 265, 122, 'false'
  );
  
  -- Ayah 19 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2269,
    'قَالَ إِنَّمَاۤ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَـٰمࣰا زَكِیࣰّا',
    'قال انما انا رسول ربك لاهب لك غلاما زكيا',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مًا</rule> <rule class=ikhafa>ز</rule>َكِيًّا ١٩',
    19, 16, 4, 306, 265, 122, 'false'
  );
  
  -- Ayah 20 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2270,
    'قَالَتۡ أَنَّىٰ یَكُونُ لِی غُلَـٰمࣱ وَلَمۡ یَمۡسَسۡنِی بَشَرࣱ وَلَمۡ أَكُ بَغِیࣰّا',
    'قالت انى يكون لي غلام ولم يمسسني بشر ولم اك بغيا',
    'قَالَتۡ أَ<rule class=ghunnah>نّ</rule>َىٰ يَكُونُ لِى غُلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ يَمۡسَسۡنِى بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ أَكُ بَغِيًّا ٢٠',
    20, 16, 4, 306, 265, 122, 'false'
  );
  
  -- Ayah 21 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2271,
    'قَالَ كَذَ ٰ⁠لِكِ قَالَ رَبُّكِ هُوَ عَلَیَّ هَیِّنࣱۖ وَلِنَجۡعَلَهُۥۤ ءَایَةࣰ لِّلنَّاسِ وَرَحۡمَةࣰ مِّنَّاۚ وَكَانَ أَمۡرࣰا مَّقۡضِیࣰّا',
    'قال كذلك قال ربك هو علي هين ولنجعله اية للناس ورحمة منا وكان امرا مقضيا',
    'قَالَ كَذ<rule class=madda_normal>ٰ</rule>لِكِ قَالَ رَبُّكِ هُوَ عَلَىَّ هَيِّ<rule class=idgham_ghunnah>نٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلِنَ<rule class=qalaqah>جۡ</rule>عَلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> ءَايَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ وَرَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا‌ۚ وَكَانَ أَمۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>قۡ</rule>ضِيًّا ٢١',
    21, 16, 4, 306, 265, 122, 'false'
  );
  
  -- Ayah 22 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2272,
    '۞ فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ مَكَانࣰا قَصِیࣰّا',
    'فحملته فانتبذت به مكانا قصيا',
    '۞فَحَمَلَتۡهُ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َبَذَتۡ بِه<rule class=madda_normal>ِۦ</rule> مَكَا<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َصِيًّا ٢٢',
    22, 16, 4, 306, 265, 123, 'false'
  );
  
  -- Ayah 23 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2273,
    'فَأَجَاۤءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ یَـٰلَیۡتَنِی مِتُّ قَبۡلَ هَـٰذَا وَكُنتُ نَسۡیࣰا مَّنسِیࣰّا',
    'فاجاءها المخاض الى جذع النخلة قالت يا ليتني مت قبل هذا وكنت نسيا منسيا',
    'فَأَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهَا <rule class=ham_wasl>ٱ</rule>لۡمَخَاضُ إِلَىٰ جِذۡعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َخۡلَةِ قَالَتۡ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَنِى مِتُّ قَ<rule class=qalaqah>بۡ</rule>لَ هَ<rule class=madda_normal>ـٰ</rule>ذَا وَكُ<rule class=ikhafa>نت</rule>ُ نَسۡ<rule class=idgham_ghunnah>يًا</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=ikhafa>نس</rule>ِيًّا ٢٣',
    23, 16, 4, 306, 265, 123, 'false'
  );
  
  -- Ayah 24 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2274,
    'فَنَادَىٰهَا مِن تَحۡتِهَاۤ أَلَّا تَحۡزَنِی قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِیࣰّا',
    'فناداها من تحتها الا تحزني قد جعل ربك تحتك سريا',
    'فَنَادَ<rule class=madda_normal>ٮٰ</rule>هَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِه<rule class=madda_obligatory_monfasel>َآ</rule> أَلَّا تَحۡزَنِى قَ<rule class=qalaqah>دۡ</rule> جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيًّا ٢٤',
    24, 16, 4, 306, 265, 123, 'false'
  );
  
  -- Ayah 25 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2275,
    'وَهُزِّیۤ إِلَیۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَـٰقِطۡ عَلَیۡكِ رُطَبࣰا جَنِیࣰّا',
    'وهزي اليك بجذع النخلة تساقط عليك رطبا جنيا',
    'وَهُزّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡكِ بِجِذۡعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َخۡلَةِ تُسَ<rule class=madda_normal>ـٰ</rule>قِ<rule class=qalaqah>طۡ</rule> عَلَيۡكِ رُطَ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ج</rule>َنِيًّا ٢٥',
    25, 16, 4, 306, 265, 123, 'false'
  );
  
  -- Ayah 26 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2276,
    'فَكُلِی وَٱشۡرَبِی وَقَرِّی عَیۡنࣰاۖ فَإِمَّا تَرَیِنَّ مِنَ ٱلۡبَشَرِ أَحَدࣰا فَقُولِیۤ إِنِّی نَذَرۡتُ لِلرَّحۡمَـٰنِ صَوۡمࣰا فَلَنۡ أُكَلِّمَ ٱلۡیَوۡمَ إِنسِیࣰّا',
    'فكلي واشربي وقري عينا فاما ترين من البشر احدا فقولي اني نذرت للرحمن صوما فلن اكلم اليوم انسيا',
    'فَكُلِى وَ<rule class=ham_wasl>ٱ</rule>شۡرَبِى وَقَرِّى عَيۡ<rule class=ikhafa>نًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>مّ</rule>َا تَرَيِ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡبَشَرِ أَحَ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َقُول<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ghunnah>نّ</rule>ِى نَذَرۡتُ لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ صَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َلَنۡ أُكَلِّمَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ إِ<rule class=ikhafa>نس</rule>ِيًّا ٢٦',
    26, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 27 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2277,
    'فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُوا۟ یَـٰمَرۡیَمُ لَقَدۡ جِئۡتِ شَیۡـࣰٔا فَرِیࣰّا',
    'فاتت به قومها تحمله قالوا يا مريم لقد جئت شيئا فريا',
    'فَأَتَتۡ بِه<rule class=madda_normal>ِۦ</rule> قَوۡمَهَا تَحۡمِلُهُ<rule class=madda_normal>ۥ</rule>‌ۖ قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>مَرۡيَمُ لَقَ<rule class=qalaqah>دۡ</rule> جِئۡتِ شَيۡـ<rule class=ikhafa>ـًٔا</rule> <rule class=ikhafa>ف</rule>َرِيًّا ٢٧',
    27, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 28 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2278,
    'یَـٰۤأُخۡتَ هَـٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءࣲ وَمَا كَانَتۡ أُمُّكِ بَغِیࣰّا',
    'يا اخت هارون ما كان ابوك امرا سوء وما كانت امك بغيا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أُخۡتَ هَ<rule class=madda_normal>ـٰ</rule>رُونَ مَا كَانَ أَبُوكِ <rule class=ham_wasl>ٱ</rule>مۡرَأَ سَوۡ<rule class=idgham_ghunnah>ءٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَتۡ أُ<rule class=ghunnah>مّ</rule>ُكِ بَغِيًّا ٢٨',
    28, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 29 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2279,
    'فَأَشَارَتۡ إِلَیۡهِۖ قَالُوا۟ كَیۡفَ نُكَلِّمُ مَن كَانَ فِی ٱلۡمَهۡدِ صَبِیࣰّا',
    'فاشارت اليه قالوا كيف نكلم من كان في المهد صبيا',
    'فَأَشَارَتۡ إِلَيۡهِ‌ۖ قَالُو<rule class=slnt>اۡ</rule> كَيۡفَ نُكَلِّمُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ فِى <rule class=ham_wasl>ٱ</rule>لۡمَهۡدِ صَبِيًّا ٢٩',
    29, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 30 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2280,
    'قَالَ إِنِّی عَبۡدُ ٱللَّهِ ءَاتَىٰنِیَ ٱلۡكِتَـٰبَ وَجَعَلَنِی نَبِیࣰّا',
    'قال اني عبد الله اتاني الكتاب وجعلني نبيا',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>ِى عَ<rule class=qalaqah>بۡ</rule>دُ <rule class=ham_wasl>ٱ</rule>للَّهِ ءَاتَ<rule class=madda_normal>ـٰ</rule>نِىَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَجَعَلَنِى نَبِيًّا ٣٠',
    30, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 31 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2281,
    'وَجَعَلَنِی مُبَارَكًا أَیۡنَ مَا كُنتُ وَأَوۡصَـٰنِی بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَیࣰّا',
    'وجعلني مباركا اين ما كنت واوصاني بالصلاة والزكاة ما دمت حيا',
    'وَجَعَلَنِى مُبَارَكًا أَيۡنَ مَا كُ<rule class=ikhafa>نت</rule>ُ وَأَوۡصَ<rule class=madda_normal>ـٰ</rule>نِى بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ مَا دُمۡتُ حَيًّا ٣١',
    31, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 32 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2282,
    'وَبَرَّۢا بِوَ ٰ⁠لِدَتِی وَلَمۡ یَجۡعَلۡنِی جَبَّارࣰا شَقِیࣰّا',
    'وبرا بوالدتي ولم يجعلني جبارا شقيا',
    'وَبَرّ<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِو<rule class=madda_normal>ٰ</rule>لِدَتِى وَلَمۡ يَ<rule class=qalaqah>جۡ</rule>عَلۡنِى جَبَّا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ش</rule>َقِيًّا ٣٢',
    32, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 33 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2283,
    'وَٱلسَّلَـٰمُ عَلَیَّ یَوۡمَ وُلِدتُّ وَیَوۡمَ أَمُوتُ وَیَوۡمَ أُبۡعَثُ حَیࣰّا',
    'والسلام علي يوم ولدت ويوم اموت ويوم ابعث حيا',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَ<rule class=madda_normal>ـٰ</rule>مُ عَلَىَّ يَوۡمَ وُلِ<rule class=idgham_mutajanisayn>د</rule>تُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُ<rule class=qalaqah>بۡ</rule>عَثُ حَيًّا ٣٣',
    33, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 34 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2284,
    'ذَ ٰ⁠لِكَ عِیسَى ٱبۡنُ مَرۡیَمَۖ قَوۡلَ ٱلۡحَقِّ ٱلَّذِی فِیهِ یَمۡتَرُونَ',
    'ذلك عيسى ابن مريم قول الحق الذي فيه يمترون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ‌ۚ قَوۡلَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ <rule class=ham_wasl>ٱ</rule>لَّذِى فِيهِ يَمۡتَر<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 35 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2285,
    'مَا كَانَ لِلَّهِ أَن یَتَّخِذَ مِن وَلَدࣲۖ سُبۡحَـٰنَهُۥۤۚ إِذَا قَضَىٰۤ أَمۡرࣰا فَإِنَّمَا یَقُولُ لَهُۥ كُن فَیَكُونُ',
    'ما كان لله ان يتخذ من ولد سبحانه اذا قضى امرا فانما يقول له كن فيكون',
    'مَا كَانَ لِلَّهِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=ikhafa>دٍ‌ۖ</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِذَا قَضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َمَا يَقُولُ لَهُ<rule class=madda_normal>ۥ</rule> كُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َيَك<rule class=madda_permissible>ُو</rule>نُ ٣٥',
    35, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 36 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2286,
    'وَإِنَّ ٱللَّهَ رَبِّی وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَـٰذَا صِرَ ٰ⁠طࣱ مُّسۡتَقِیمࣱ',
    'وان الله ربي وربكم فاعبدوه هذا صراط مستقيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ رَبِّى وَرَبُّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡبُدُوهُ‌ۚ هَ<rule class=madda_normal>ـٰ</rule>ذَا صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٌ ٣٦',
    36, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 37 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2287,
    'فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَیۡنِهِمۡۖ فَوَیۡلࣱ لِّلَّذِینَ كَفَرُوا۟ مِن مَّشۡهَدِ یَوۡمٍ عَظِیمٍ',
    'فاختلف الاحزاب من بينهم فويل للذين كفروا من مشهد يوم عظيم',
    'فَ<rule class=ham_wasl>ٱ</rule>خۡتَلَفَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡزَابُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِهِمۡ‌ۖ فَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّشۡهَدِ يَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ٣٧',
    37, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 38 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2288,
    'أَسۡمِعۡ بِهِمۡ وَأَبۡصِرۡ یَوۡمَ یَأۡتُونَنَاۖ لَـٰكِنِ ٱلظَّـٰلِمُونَ ٱلۡیَوۡمَ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'اسمع بهم وابصر يوم ياتوننا لكن الظالمون اليوم في ضلال مبين',
    'أَسۡمِعۡ بِهِمۡ وَأَ<rule class=qalaqah>بۡ</rule>صِرۡ يَوۡمَ يَأۡتُونَنَا‌ۖ لَ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٣٨',
    38, 16, 4, 307, 265, 123, 'false'
  );
  
  -- Ayah 39 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2289,
    'وَأَنذِرۡهُمۡ یَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِیَ ٱلۡأَمۡرُ وَهُمۡ فِی غَفۡلَةࣲ وَهُمۡ لَا یُؤۡمِنُونَ',
    'وانذرهم يوم الحسرة اذ قضي الامر وهم في غفلة وهم لا يؤمنون',
    'وَأَ<rule class=ikhafa>نذ</rule>ِرۡهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡحَسۡرَةِ إِذۡ قُضِىَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ وَهُمۡ فِى غَفۡلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 16, 4, 308, 265, 123, 'false'
  );
  
  -- Ayah 40 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2290,
    'إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَیۡهَا وَإِلَیۡنَا یُرۡجَعُونَ',
    'انا نحن نرث الارض ومن عليها والينا يرجعون',
    'إِ<rule class=ghunnah>نّ</rule>َا نَحۡنُ نَرِثُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَنۡ عَلَيۡهَا وَإِلَيۡنَا يُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 16, 4, 308, 265, 123, 'false'
  );
  
  -- Ayah 41 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2291,
    'وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ إِبۡرَ ٰ⁠هِیمَۚ إِنَّهُۥ كَانَ صِدِّیقࣰا نَّبِیًّا',
    'واذكر في الكتاب ابراهيم انه كان صديقا نبيا',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ صِدِّي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>ن</rule>َّبِيًّا ٤١',
    41, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 42 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2292,
    'إِذۡ قَالَ لِأَبِیهِ یَـٰۤأَبَتِ لِمَ تَعۡبُدُ مَا لَا یَسۡمَعُ وَلَا یُبۡصِرُ وَلَا یُغۡنِی عَنكَ شَیۡـࣰٔا',
    'اذ قال لابيه يا ابت لم تعبد ما لا يسمع ولا يبصر ولا يغني عنك شيئا',
    'إِذۡ قَالَ لِأَبِيهِ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُ<rule class=qalaqah>بۡ</rule>صِرُ وَلَا يُغۡنِى عَ<rule class=ikhafa>نك</rule>َ شَيۡــًٔا ٤٢',
    42, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 43 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2293,
    'یَـٰۤأَبَتِ إِنِّی قَدۡ جَاۤءَنِی مِنَ ٱلۡعِلۡمِ مَا لَمۡ یَأۡتِكَ فَٱتَّبِعۡنِیۤ أَهۡدِكَ صِرَ ٰ⁠طࣰا سَوِیࣰّا',
    'يا ابت اني قد جاءني من العلم ما لم ياتك فاتبعني اهدك صراطا سويا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَتِ إِ<rule class=ghunnah>نّ</rule>ِى قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَ<rule class=ham_wasl>ٱ</rule>تَّبِعۡن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَهۡدِكَ صِر<rule class=madda_normal>ٰ</rule><rule class=ikhafa>طًا</rule> <rule class=ikhafa>س</rule>َوِيًّا ٤٣',
    43, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 44 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2294,
    'یَـٰۤأَبَتِ لَا تَعۡبُدِ ٱلشَّیۡطَـٰنَۖ إِنَّ ٱلشَّیۡطَـٰنَ كَانَ لِلرَّحۡمَـٰنِ عَصِیࣰّا',
    'يا ابت لا تعبد الشيطان ان الشيطان كان للرحمن عصيا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَتِ لَا تَعۡبُدِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ كَانَ لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ عَصِيًّا ٤٤',
    44, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 45 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2295,
    'یَـٰۤأَبَتِ إِنِّیۤ أَخَافُ أَن یَمَسَّكَ عَذَابࣱ مِّنَ ٱلرَّحۡمَـٰنِ فَتَكُونَ لِلشَّیۡطَـٰنِ وَلِیࣰّا',
    'يا ابت اني اخاف ان يمسك عذاب من الرحمن فتكون للشيطان وليا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَتِ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمَسَّكَ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ فَتَكُونَ لِلشَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ وَلِيًّا ٤٥',
    45, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 46 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2296,
    'قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِی یَـٰۤإِبۡرَ ٰ⁠هِیمُۖ لَىِٕن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِی مَلِیࣰّا',
    'قال اراغب انت عن الهتي يا ابراهيم لئن لم تنته لارجمنك واهجرني مليا',
    'قَالَ أَرَاغِبٌ أَ<rule class=ikhafa>نت</rule>َ عَنۡ ءَالِهَتِى يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمُ‌ۖ لَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَ<rule class=ikhafa>نت</rule>َهِ لَأَرۡجُمَ<rule class=ghunnah>نّ</rule>َكَ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>هۡجُرۡنِى مَلِيًّا ٤٦',
    46, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 47 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2297,
    'قَالَ سَلَـٰمٌ عَلَیۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّیۤۖ إِنَّهُۥ كَانَ بِی حَفِیࣰّا',
    'قال سلام عليك ساستغفر لك ربي انه كان بي حفيا',
    'قَالَ سَلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَيۡكَ‌ۖ سَأَسۡتَغۡفِرُ لَكَ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ بِى حَفِيًّا ٤٧',
    47, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 48 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2298,
    'وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُوا۟ رَبِّی عَسَىٰۤ أَلَّاۤ أَكُونَ بِدُعَاۤءِ رَبِّی شَقِیࣰّا',
    'واعتزلكم وما تدعون من دون الله وادعو ربي عسى الا اكون بدعاء ربي شقيا',
    'وَأَعۡتَزِلُكُمۡ وَمَا تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَأَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> رَبِّى عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَكُونَ بِدُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رَبِّى شَقِيًّا ٤٨',
    48, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 49 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2299,
    'فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا یَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَۖ وَكُلࣰّا جَعَلۡنَا نَبِیࣰّا',
    'فلما اعتزلهم وما يعبدون من دون الله وهبنا له اسحاق ويعقوب وكلا جعلنا نبيا',
    'فَلَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>عۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَهَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ‌ۖ وَكُل<rule class=ikhafa>اًّ</rule> <rule class=ikhafa>ج</rule>َعَلۡنَا نَبِيًّا ٤٩',
    49, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 50 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2300,
    'وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِیࣰّا',
    'ووهبنا لهم من رحمتنا وجعلنا لهم لسان صدق عليا',
    'وَوَهَ<rule class=qalaqah>بۡ</rule>نَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِ<rule class=qalaqah>دۡ</rule>قٍ عَلِيًّا ٥٠',
    50, 16, 4, 308, 266, 123, 'false'
  );
  
  -- Ayah 51 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2301,
    'وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ مُوسَىٰۤۚ إِنَّهُۥ كَانَ مُخۡلَصࣰا وَكَانَ رَسُولࣰا نَّبِیࣰّا',
    'واذكر في الكتاب موسى انه كان مخلصا وكان رسولا نبيا',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ مُخۡلَ<rule class=idgham_ghunnah>صًا</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ رَسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ن</rule>َّبِيًّا ٥١',
    51, 16, 4, 308, 267, 123, 'false'
  );
  
  -- Ayah 52 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2302,
    'وَنَـٰدَیۡنَـٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَیۡمَنِ وَقَرَّبۡنَـٰهُ نَجِیࣰّا',
    'وناديناه من جانب الطور الايمن وقربناه نجيا',
    'وَنَ<rule class=madda_normal>ـٰ</rule>دَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َانِبِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّورِ <rule class=ham_wasl>ٱ</rule>لۡأَيۡمَنِ وَقَرَّ<rule class=qalaqah>بۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ نَجِيًّا ٥٢',
    52, 16, 4, 309, 267, 123, 'false'
  );
  
  -- Ayah 53 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2303,
    'وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَاۤ أَخَاهُ هَـٰرُونَ نَبِیࣰّا',
    'ووهبنا له من رحمتنا اخاه هارون نبيا',
    'وَوَهَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَتِن<rule class=madda_obligatory_monfasel>َآ</rule> أَخَاهُ هَ<rule class=madda_normal>ـٰ</rule>رُونَ نَبِيًّا ٥٣',
    53, 16, 4, 309, 267, 123, 'false'
  );
  
  -- Ayah 54 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2304,
    'وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ إِسۡمَـٰعِیلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولࣰا نَّبِیࣰّا',
    'واذكر في الكتاب اسماعيل انه كان صادق الوعد وكان رسولا نبيا',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ إِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ صَادِقَ <rule class=ham_wasl>ٱ</rule>لۡوَعۡدِ وَكَانَ رَسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ن</rule>َّبِيًّا ٥٤',
    54, 16, 4, 309, 267, 123, 'false'
  );
  
  -- Ayah 55 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2305,
    'وَكَانَ یَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِیࣰّا',
    'وكان يامر اهله بالصلاة والزكاة وكان عند ربه مرضيا',
    'وَكَانَ يَأۡمُرُ أَهۡلَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَكَانَ عِ<rule class=ikhafa>ند</rule>َ رَبِّه<rule class=madda_normal>ِۦ</rule> مَرۡضِيًّا ٥٥',
    55, 16, 4, 309, 267, 123, 'false'
  );
  
  -- Ayah 56 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2306,
    'وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ إِدۡرِیسَۚ إِنَّهُۥ كَانَ صِدِّیقࣰا نَّبِیࣰّا',
    'واذكر في الكتاب ادريس انه كان صديقا نبيا',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ إِ<rule class=qalaqah>دۡ</rule>رِيسَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ صِدِّي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>ن</rule>َّبِيًّا ٥٦',
    56, 16, 4, 309, 267, 123, 'false'
  );
  
  -- Ayah 57 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2307,
    'وَرَفَعۡنَـٰهُ مَكَانًا عَلِیًّا',
    'ورفعناه مكانا عليا',
    'وَرَفَعۡنَ<rule class=madda_normal>ـٰ</rule>هُ مَكَانًا عَلِيًّا ٥٧',
    57, 16, 4, 309, 267, 123, 'false'
  );
  
  -- Ayah 58 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2308,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ أَنۡعَمَ ٱللَّهُ عَلَیۡهِم مِّنَ ٱلنَّبِیِّـۧنَ مِن ذُرِّیَّةِ ءَادَمَ وَمِمَّنۡ حَمَلۡنَا مَعَ نُوحࣲ وَمِن ذُرِّیَّةِ إِبۡرَ ٰ⁠هِیمَ وَإِسۡرَ ٰ⁠ۤءِیلَ وَمِمَّنۡ هَدَیۡنَا وَٱجۡتَبَیۡنَاۤۚ إِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُ ٱلرَّحۡمَـٰنِ خَرُّوا۟ سُجَّدࣰا وَبُكِیࣰّا ۩',
    'اولئك الذين انعم الله عليهم من النبيين من ذرية ادم وممن حملنا مع نوح ومن ذرية ابراهيم واسرائيل وممن هدينا واجتبينا اذا تتلى عليهم ايات الرحمن خروا سجدا وبكيا',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَنۡعَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُرِّيَّةِ ءَادَمَ وَمِ<rule class=ghunnah>مّ</rule>َنۡ حَمَلۡنَا مَعَ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُرِّيَّةِ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَإِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ وَمِ<rule class=ghunnah>مّ</rule>َنۡ هَدَيۡنَا وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَبَيۡن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ خَرُّو<rule class=slnt>اۡ</rule> سُجَّ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َبُكِيًّا ۩ ٥٨',
    58, 16, 4, 309, 267, 123, '{"id":5,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 59 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2309,
    '۞ فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَ ٰ⁠تِۖ فَسَوۡفَ یَلۡقَوۡنَ غَیًّا',
    'فخلف من بعدهم خلف اضاعوا الصلاة واتبعوا الشهوات فسوف يلقون غيا',
    '۞فَخَلَفَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ خَلۡفٌ أَضَاعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَو<rule class=madda_normal>ٰ</rule>تِ‌ۖ فَسَوۡفَ يَلۡقَوۡنَ غَيًّا ٥٩',
    59, 16, 4, 309, 267, 124, 'false'
  );
  
  -- Ayah 60 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2310,
    'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَأُو۟لَـٰۤىِٕكَ یَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا یُظۡلَمُونَ شَیۡـࣰٔا',
    'الا من تاب وامن وعمل صالحا فاولئك يدخلون الجنة ولا يظلمون شيئا',
    'إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابَ وَءَامَنَ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَ<rule class=qalaqah>دۡ</rule>خُلُونَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ وَلَا يُظۡلَمُونَ شَيۡــًٔا ٦٠',
    60, 16, 4, 309, 267, 124, 'false'
  );
  
  -- Ayah 61 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2311,
    'جَنَّـٰتِ عَدۡنٍ ٱلَّتِی وَعَدَ ٱلرَّحۡمَـٰنُ عِبَادَهُۥ بِٱلۡغَیۡبِۚ إِنَّهُۥ كَانَ وَعۡدُهُۥ مَأۡتِیࣰّا',
    'جنات عدن التي وعد الرحمن عباده بالغيب انه كان وعده ماتيا',
    'جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ عَ<rule class=qalaqah>دۡ</rule>نٍ <rule class=ham_wasl>ٱ</rule>لَّتِى وَعَدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ عِبَادَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ وَعۡدُهُ<rule class=madda_normal>ۥ</rule> مَأۡتِيًّا ٦١',
    61, 16, 4, 309, 267, 124, 'false'
  );
  
  -- Ayah 62 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2312,
    'لَّا یَسۡمَعُونَ فِیهَا لَغۡوًا إِلَّا سَلَـٰمࣰاۖ وَلَهُمۡ رِزۡقُهُمۡ فِیهَا بُكۡرَةࣰ وَعَشِیࣰّا',
    'لا يسمعون فيها لغوا الا سلاما ولهم رزقهم فيها بكرة وعشيا',
    'لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا إِلَّا سَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ رِزۡقُهُمۡ فِيهَا بُكۡرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َعَشِيًّا ٦٢',
    62, 16, 4, 309, 267, 124, 'false'
  );
  
  -- Ayah 63 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2313,
    'تِلۡكَ ٱلۡجَنَّةُ ٱلَّتِی نُورِثُ مِنۡ عِبَادِنَا مَن كَانَ تَقِیࣰّا',
    'تلك الجنة التي نورث من عبادنا من كان تقيا',
    'تِلۡكَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةُ <rule class=ham_wasl>ٱ</rule>لَّتِى نُورِثُ مِنۡ عِبَادِنَا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ تَقِيًّا ٦٣',
    63, 16, 4, 309, 267, 124, 'false'
  );
  
  -- Ayah 64 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2314,
    'وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَۖ لَهُۥ مَا بَیۡنَ أَیۡدِینَا وَمَا خَلۡفَنَا وَمَا بَیۡنَ ذَ ٰ⁠لِكَۚ وَمَا كَانَ رَبُّكَ نَسِیࣰّا',
    'وما نتنزل الا بامر ربك له ما بين ايدينا وما خلفنا وما بين ذلك وما كان ربك نسيا',
    'وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَ‌ۖ لَهُ<rule class=madda_normal>ۥ</rule> مَا بَيۡنَ أَيۡدِينَا وَمَا خَلۡفَنَا وَمَا بَيۡنَ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۚ وَمَا كَانَ رَبُّكَ نَسِيًّا ٦٤',
    64, 16, 4, 309, 267, 124, 'false'
  );
  
  -- Ayah 65 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2315,
    'رَّبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَـٰدَتِهِۦۚ هَلۡ تَعۡلَمُ لَهُۥ سَمِیࣰّا',
    'رب السماوات والارض وما بينهما فاعبده واصطبر لعبادته هل تعلم له سميا',
    'رَّبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا فَ<rule class=ham_wasl>ٱ</rule>عۡبُ<rule class=qalaqah>دۡ</rule>هُ وَ<rule class=ham_wasl>ٱ</rule>صۡطَبِرۡ لِعِبَ<rule class=madda_normal>ـٰ</rule>دَتِه<rule class=madda_normal>ِۦ</rule>‌ۚ هَلۡ تَعۡلَمُ لَهُ<rule class=madda_normal>ۥ</rule> سَمِيًّا ٦٥',
    65, 16, 4, 310, 267, 124, 'false'
  );
  
  -- Ayah 66 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2316,
    'وَیَقُولُ ٱلۡإِنسَـٰنُ أَءِذَا مَا مِتُّ لَسَوۡفَ أُخۡرَجُ حَیًّا',
    'ويقول الانسان ااذا ما مت لسوف اخرج حيا',
    'وَيَقُولُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ أَءِذَا مَا مِتُّ لَسَوۡفَ أُخۡرَجُ حَيًّا ٦٦',
    66, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 67 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2317,
    'أَوَلَا یَذۡكُرُ ٱلۡإِنسَـٰنُ أَنَّا خَلَقۡنَـٰهُ مِن قَبۡلُ وَلَمۡ یَكُ شَیۡـࣰٔا',
    'اولا يذكر الانسان انا خلقناه من قبل ولم يك شيئا',
    'أَوَلَا يَذۡكُرُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ أَ<rule class=ghunnah>نّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَلَمۡ يَكُ شَيۡــًٔا ٦٧',
    67, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 68 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2318,
    'فَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّیَـٰطِینَ ثُمَّ لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِیࣰّا',
    'فوربك لنحشرنهم والشياطين ثم لنحضرنهم حول جهنم جثيا',
    'فَوَرَبِّكَ لَنَحۡشُرَ<rule class=ghunnah>نّ</rule>َهُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينَ ثُ<rule class=ghunnah>مّ</rule>َ لَنُحۡضِرَ<rule class=ghunnah>نّ</rule>َهُمۡ حَوۡلَ جَهَ<rule class=ghunnah>نّ</rule>َمَ جِثِيًّا ٦٨',
    68, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 69 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2319,
    'ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِیعَةٍ أَیُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَـٰنِ عِتِیࣰّا',
    'ثم لننزعن من كل شيعة ايهم اشد على الرحمن عتيا',
    'ثُ<rule class=ghunnah>مّ</rule>َ لَنَ<rule class=ikhafa>نز</rule>ِعَ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ عِتِيًّا ٦٩',
    69, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 70 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2320,
    'ثُمَّ لَنَحۡنُ أَعۡلَمُ بِٱلَّذِینَ هُمۡ أَوۡلَىٰ بِهَا صِلِیࣰّا',
    'ثم لنحن اعلم بالذين هم اولى بها صليا',
    'ثُ<rule class=ghunnah>مّ</rule>َ لَنَحۡنُ أَعۡلَمُ بِ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ أَوۡلَىٰ بِهَا صِلِيًّا ٧٠',
    70, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 71 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2321,
    'وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ حَتۡمࣰا مَّقۡضِیࣰّا',
    'وان منكم الا واردها كان على ربك حتما مقضيا',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ إِلَّا وَارِدُهَا‌ۚ كَانَ عَلَىٰ رَبِّكَ حَتۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>قۡ</rule>ضِيًّا ٧١',
    71, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 72 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2322,
    'ثُمَّ نُنَجِّی ٱلَّذِینَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّـٰلِمِینَ فِیهَا جِثِیࣰّا',
    'ثم ننجي الذين اتقوا ونذر الظالمين فيها جثيا',
    'ثُ<rule class=ghunnah>مّ</rule>َ نُنَجِّى <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَو<rule class=slnt>اۡ</rule> وَّنَذَرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ فِيهَا جِثِيًّا ٧٢',
    72, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 73 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2323,
    'وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ قَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوۤا۟ أَیُّ ٱلۡفَرِیقَیۡنِ خَیۡرࣱ مَّقَامࣰا وَأَحۡسَنُ نَدِیࣰّا',
    'واذا تتلى عليهم اياتنا بينات قال الذين كفروا للذين امنوا اي الفريقين خير مقاما واحسن نديا',
    'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا بَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ق</rule>َالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لِلَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَىُّ <rule class=ham_wasl>ٱ</rule>لۡفَرِيقَيۡنِ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>َّقَا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َأَحۡسَنُ نَدِيًّا ٧٣',
    73, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 74 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2324,
    'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَـٰثࣰا وَرِءۡیࣰا',
    'وكم اهلكنا قبلهم من قرن هم احسن اثاثا ورئيا',
    'وَكَمۡ أَهۡلَكۡنَا قَ<rule class=qalaqah>بۡ</rule>لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡنٍ هُمۡ أَحۡسَنُ أَثَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>ثًا</rule> <rule class=idgham_ghunnah>و</rule>َرِءۡيًا ٧٤',
    74, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 75 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2325,
    'قُلۡ مَن كَانَ فِی ٱلضَّلَـٰلَةِ فَلۡیَمۡدُدۡ لَهُ ٱلرَّحۡمَـٰنُ مَدًّاۚ حَتَّىٰۤ إِذَا رَأَوۡا۟ مَا یُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَیَعۡلَمُونَ مَنۡ هُوَ شَرࣱّ مَّكَانࣰا وَأَضۡعَفُ جُندࣰا',
    'قل من كان في الضلالة فليمدد له الرحمن مدا حتى اذا راوا ما يوعدون اما العذاب واما الساعة فسيعلمون من هو شر مكانا واضعف جندا',
    'قُلۡ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لَةِ فَلۡيَمۡدُ<rule class=qalaqah>دۡ</rule> لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ مَدًّا‌ۚ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا رَأَوۡ<rule class=slnt>اۡ</rule> مَا يُوعَدُونَ إِ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ وَإِ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَ<rule class=idgham_ghunnah>رٌّ</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َأَضۡعَفُ جُ<rule class=ikhafa>ند</rule>ًا ٧٥',
    75, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 76 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2326,
    'وَیَزِیدُ ٱللَّهُ ٱلَّذِینَ ٱهۡتَدَوۡا۟ هُدࣰىۗ وَٱلۡبَـٰقِیَـٰتُ ٱلصَّـٰلِحَـٰتُ خَیۡرٌ عِندَ رَبِّكَ ثَوَابࣰا وَخَیۡرࣱ مَّرَدًّا',
    'ويزيد الله الذين اهتدوا هدى والباقيات الصالحات خير عند ربك ثوابا وخير مردا',
    'وَيَزِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>هۡتَدَوۡ<rule class=slnt>اۡ</rule> هُ<rule class=idgham_ghunnah>دًى‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>قِيَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تُ خَيۡرٌ عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ ثَوَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َخَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>َّرَدًّا ٧٦',
    76, 16, 4, 310, 268, 124, 'false'
  );
  
  -- Ayah 77 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2327,
    'أَفَرَءَیۡتَ ٱلَّذِی كَفَرَ بِـَٔایَـٰتِنَا وَقَالَ لَأُوتَیَنَّ مَالࣰا وَوَلَدًا',
    'افرايت الذي كفر باياتنا وقال لاوتين مالا وولدا',
    'أَفَرَءَيۡتَ <rule class=ham_wasl>ٱ</rule>لَّذِى كَفَرَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَقَالَ لَأُوتَيَ<rule class=ghunnah>نّ</rule>َ مَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َوَلَدًا ٧٧',
    77, 16, 4, 311, 268, 124, 'false'
  );
  
  -- Ayah 78 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2328,
    'أَطَّلَعَ ٱلۡغَیۡبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَـٰنِ عَهۡدࣰا',
    'اطلع الغيب ام اتخذ عند الرحمن عهدا',
    'أَطَّلَعَ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبَ أَمِ <rule class=ham_wasl>ٱ</rule>تَّخَذَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ عَهۡدًا ٧٨',
    78, 16, 4, 311, 268, 124, 'false'
  );
  
  -- Ayah 79 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2329,
    'كَلَّاۚ سَنَكۡتُبُ مَا یَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدࣰّا',
    'كلا سنكتب ما يقول ونمد له من العذاب مدا',
    'كَلَّا‌ۚ سَنَكۡتُبُ مَا يَقُولُ وَنَمُدُّ لَهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ مَدًّا ٧٩',
    79, 16, 4, 311, 268, 124, 'false'
  );
  
  -- Ayah 80 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2330,
    'وَنَرِثُهُۥ مَا یَقُولُ وَیَأۡتِینَا فَرۡدࣰا',
    'ونرثه ما يقول وياتينا فردا',
    'وَنَرِثُهُ<rule class=madda_normal>ۥ</rule> مَا يَقُولُ وَيَأۡتِينَا فَرۡدًا ٨٠',
    80, 16, 4, 311, 268, 124, 'false'
  );
  
  -- Ayah 81 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2331,
    'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةࣰ لِّیَكُونُوا۟ لَهُمۡ عِزࣰّا',
    'واتخذوا من دون الله الهة ليكونوا لهم عزا',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ ءَالِهَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَكُونُو<rule class=slnt>اۡ</rule> لَهُمۡ عِزًّا ٨١',
    81, 16, 4, 311, 268, 124, 'false'
  );
  
  -- Ayah 82 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2332,
    'كَلَّاۚ سَیَكۡفُرُونَ بِعِبَادَتِهِمۡ وَیَكُونُونَ عَلَیۡهِمۡ ضِدًّا',
    'كلا سيكفرون بعبادتهم ويكونون عليهم ضدا',
    'كَلَّا‌ۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ عَلَيۡهِمۡ ضِدًّا ٨٢',
    82, 16, 4, 311, 268, 124, 'false'
  );
  
  -- Ayah 83 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2333,
    'أَلَمۡ تَرَ أَنَّاۤ أَرۡسَلۡنَا ٱلشَّیَـٰطِینَ عَلَى ٱلۡكَـٰفِرِینَ تَؤُزُّهُمۡ أَزࣰّا',
    'الم تر انا ارسلنا الشياطين على الكافرين تؤزهم ازا',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ تَؤُزُّهُمۡ أَزًّا ٨٣',
    83, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 84 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2334,
    'فَلَا تَعۡجَلۡ عَلَیۡهِمۡۖ إِنَّمَا نَعُدُّ لَهُمۡ عَدࣰّا',
    'فلا تعجل عليهم انما نعد لهم عدا',
    'فَلَا تَعۡجَلۡ عَلَيۡهِمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َمَا نَعُدُّ لَهُمۡ عَدًّا ٨٤',
    84, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 85 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2335,
    'یَوۡمَ نَحۡشُرُ ٱلۡمُتَّقِینَ إِلَى ٱلرَّحۡمَـٰنِ وَفۡدࣰا',
    'يوم نحشر المتقين الى الرحمن وفدا',
    'يَوۡمَ نَحۡشُرُ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقِينَ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ وَفۡدًا ٨٥',
    85, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 86 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2336,
    'وَنَسُوقُ ٱلۡمُجۡرِمِینَ إِلَىٰ جَهَنَّمَ وِرۡدࣰا',
    'ونسوق المجرمين الى جهنم وردا',
    'وَنَسُوقُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ إِلَىٰ جَهَ<rule class=ghunnah>نّ</rule>َمَ وِرۡدًا ٨٦',
    86, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 87 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2337,
    'لَّا یَمۡلِكُونَ ٱلشَّفَـٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَـٰنِ عَهۡدࣰا',
    'لا يملكون الشفاعة الا من اتخذ عند الرحمن عهدا',
    'لَّا يَمۡلِكُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّفَ<rule class=madda_normal>ـٰ</rule>عَةَ إِلَّا مَنِ <rule class=ham_wasl>ٱ</rule>تَّخَذَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ عَهۡدًا ٨٧',
    87, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 88 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2338,
    'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحۡمَـٰنُ وَلَدࣰا',
    'وقالوا اتخذ الرحمن ولدا',
    'وَقَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّخَذَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ وَلَدًا ٨٨',
    88, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 89 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2339,
    'لَّقَدۡ جِئۡتُمۡ شَیۡـًٔا إِدࣰّا',
    'لقد جئتم شيئا ادا',
    'لَّقَ<rule class=qalaqah>دۡ</rule> جِئۡتُمۡ شَيۡــًٔا إِدًّا ٨٩',
    89, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 90 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2340,
    'تَكَادُ ٱلسَّمَـٰوَ ٰ⁠تُ یَتَفَطَّرۡنَ مِنۡهُ وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا',
    'تكاد السماوات يتفطرن منه وتنشق الارض وتخر الجبال هدا',
    'تَكَادُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ يَتَفَطَّرۡنَ مِنۡهُ وَتَ<rule class=ikhafa>نش</rule>َقُّ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَتَخِرُّ <rule class=ham_wasl>ٱ</rule>لۡجِبَالُ هَدًّا ٩٠',
    90, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 91 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2341,
    'أَن دَعَوۡا۟ لِلرَّحۡمَـٰنِ وَلَدࣰا',
    'ان دعوا للرحمن ولدا',
    'أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>َعَوۡ<rule class=slnt>اۡ</rule> لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ وَلَدًا ٩١',
    91, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 92 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2342,
    'وَمَا یَنۢبَغِی لِلرَّحۡمَـٰنِ أَن یَتَّخِذَ وَلَدًا',
    'وما ينبغي للرحمن ان يتخذ ولدا',
    'وَمَا يَ<rule class=iqlab>نۢب</rule>َغِى لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذَ وَلَدًا ٩٢',
    92, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 93 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2343,
    'إِن كُلُّ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ إِلَّاۤ ءَاتِی ٱلرَّحۡمَـٰنِ عَبۡدࣰا',
    'ان كل من في السماوات والارض الا اتي الرحمن عبدا',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلُّ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ عَ<rule class=qalaqah>بۡ</rule>دًا ٩٣',
    93, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 94 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2344,
    'لَّقَدۡ أَحۡصَىٰهُمۡ وَعَدَّهُمۡ عَدࣰّا',
    'لقد احصاهم وعدهم عدا',
    'لَّقَ<rule class=qalaqah>دۡ</rule> أَحۡصَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَعَدَّهُمۡ عَدًّا ٩٤',
    94, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 95 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2345,
    'وَكُلُّهُمۡ ءَاتِیهِ یَوۡمَ ٱلۡقِیَـٰمَةِ فَرۡدًا',
    'وكلهم اتيه يوم القيامة فردا',
    'وَكُلُّهُمۡ ءَاتِيهِ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فَرۡدًا ٩٥',
    95, 16, 4, 311, 269, 124, 'false'
  );
  
  -- Ayah 96 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2346,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَیَجۡعَلُ لَهُمُ ٱلرَّحۡمَـٰنُ وُدࣰّا',
    'ان الذين امنوا وعملوا الصالحات سيجعل لهم الرحمن ودا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ سَيَ<rule class=qalaqah>جۡ</rule>عَلُ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ وُدًّا ٩٦',
    96, 16, 4, 312, 269, 124, 'false'
  );
  
  -- Ayah 97 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2347,
    'فَإِنَّمَا یَسَّرۡنَـٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلۡمُتَّقِینَ وَتُنذِرَ بِهِۦ قَوۡمࣰا لُّدࣰّا',
    'فانما يسرناه بلسانك لتبشر به المتقين وتنذر به قوما لدا',
    'فَإِ<rule class=ghunnah>نّ</rule>َمَا يَسَّرۡنَ<rule class=madda_normal>ـٰ</rule>هُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقِينَ وَتُ<rule class=ikhafa>نذ</rule>ِرَ بِه<rule class=madda_normal>ِۦ</rule> قَوۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ُّدًّا ٩٧',
    97, 16, 4, 312, 269, 124, 'false'
  );
  
  -- Ayah 98 Surah Maryam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    19,
    2348,
    'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هَلۡ تُحِسُّ مِنۡهُم مِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا',
    'وكم اهلكنا قبلهم من قرن هل تحس منهم من احد او تسمع لهم ركزا',
    'وَكَمۡ أَهۡلَكۡنَا قَ<rule class=qalaqah>بۡ</rule>لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡنٍ هَلۡ تُحِسُّ مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا ٩٨',
    98, 16, 4, 312, 269, 124, 'false'
  );
  

-- Surah Taa-Haa
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (20, 'سُورَةُ طه', 'Taa-Haa', 'Taa-Haa', 'Meccan', 135);

  -- Ayah 1 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2349,
    'طه',
    'طه',
    'طه ١',
    1, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 2 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2350,
    'مَاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰۤ',
    'ما انزلنا عليك القران لتشقى',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ لِتَشۡقَىٰٓ ٢',
    2, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 3 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2351,
    'إِلَّا تَذۡكِرَةࣰ لِّمَن یَخۡشَىٰ',
    'الا تذكرة لمن يخشى',
    'إِلَّا تَذۡكِرَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡشَىٰ ٣',
    3, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 4 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2352,
    'تَنزِیلࣰا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَـٰوَ ٰ⁠تِ ٱلۡعُلَى',
    'تنزيلا ممن خلق الارض والسماوات العلى',
    'تَ<rule class=ikhafa>نز</rule>ِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َنۡ خَلَقَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡعُلَى ٤',
    4, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 5 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2353,
    'ٱلرَّحۡمَـٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ',
    'الرحمن على العرش استوى',
    'ٱ<rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ <rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ ٥',
    5, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 6 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2354,
    'لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ',
    'له ما في السماوات وما في الارض وما بينهما وما تحت الثرى',
    'لَهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّرَىٰ ٦',
    6, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 7 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2355,
    'وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ یَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى',
    'وان تجهر بالقول فانه يعلم السر واخفى',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>هَرۡ بِ<rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَعۡلَمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّرَّ وَأَخۡفَى ٧',
    7, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 8 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2356,
    'ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰ',
    'الله لا اله الا هو له الاسماء الحسنى',
    'ٱللَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۖ لَهُ <rule class=ham_wasl>ٱ</rule>لۡأَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ ٨',
    8, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 9 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2357,
    'وَهَلۡ أَتَىٰكَ حَدِیثُ مُوسَىٰۤ',
    'وهل اتاك حديث موسى',
    'وَهَلۡ أَتَ<rule class=madda_normal>ـٰ</rule>كَ حَدِيثُ مُوسَىٰٓ ٩',
    9, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 10 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2358,
    'إِذۡ رَءَا نَارࣰا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوۤا۟ إِنِّیۤ ءَانَسۡتُ نَارࣰا لَّعَلِّیۤ ءَاتِیكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدࣰى',
    'اذ راى نارا فقال لاهله امكثوا اني انست نارا لعلي اتيكم منها بقبس او اجد على النار هدى',
    'إِذۡ رَءَا نَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َقَالَ لِأَهۡلِهِ <rule class=ham_wasl>ٱ</rule>مۡكُث<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَانَسۡتُ نَا<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاتِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ هُدًى ١٠',
    10, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 11 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2359,
    'فَلَمَّاۤ أَتَىٰهَا نُودِیَ یَـٰمُوسَىٰۤ',
    'فلما اتاها نودي يا موسى',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَتَ<rule class=madda_normal>ـٰ</rule>هَا نُودِىَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰٓ ١١',
    11, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 12 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2360,
    'إِنِّیۤ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَیۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوࣰى',
    'اني انا ربك فاخلع نعليك انك بالواد المقدس طوى',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنَاۡ رَبُّكَ فَ<rule class=ham_wasl>ٱ</rule>خۡلَعۡ نَعۡلَيۡكَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ بِ<rule class=ham_wasl>ٱ</rule>لۡوَادِ <rule class=ham_wasl>ٱ</rule>لۡمُقَدَّسِ طُوًى ١٢',
    12, 16, 4, 312, 270, 125, 'false'
  );
  
  -- Ayah 13 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2361,
    'وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا یُوحَىٰۤ',
    'وانا اخترتك فاستمع لما يوحى',
    'وَأَنَا <rule class=ham_wasl>ٱ</rule>خۡتَرۡتُكَ فَ<rule class=ham_wasl>ٱ</rule>سۡتَمِعۡ لِمَا يُوحَىٰٓ ١٣',
    13, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 14 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2362,
    'إِنَّنِیۤ أَنَا ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّاۤ أَنَا۠ فَٱعۡبُدۡنِی وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِیۤ',
    'انني انا الله لا اله الا انا فاعبدني واقم الصلاة لذكري',
    'إِ<rule class=ghunnah>نّ</rule>َن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنَا <rule class=ham_wasl>ٱ</rule>للَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ فَ<rule class=ham_wasl>ٱ</rule>عۡبُ<rule class=qalaqah>دۡ</rule>نِى وَأَقِمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ لِذِكۡرِىٓ ١٤',
    14, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 15 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2363,
    'إِنَّ ٱلسَّاعَةَ ءَاتِیَةٌ أَكَادُ أُخۡفِیهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ',
    'ان الساعة اتية اكاد اخفيها لتجزى كل نفس بما تسعى',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ ءَاتِيَةٌ أَكَادُ أُخۡفِيهَا لِتُ<rule class=qalaqah>جۡ</rule>زَىٰ كُلُّ نَفۡ<rule class=iqlab>سِۭ</rule> <rule class=iqlab>ب</rule>ِمَا تَسۡعَىٰ ١٥',
    15, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 16 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2364,
    'فَلَا یَصُدَّنَّكَ عَنۡهَا مَن لَّا یُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ',
    'فلا يصدنك عنها من لا يؤمن بها واتبع هواه فتردى',
    'فَلَا يَصُدَّ<rule class=ghunnah>نّ</rule>َكَ عَنۡهَا م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِنُ بِهَا وَ<rule class=ham_wasl>ٱ</rule>تَّبَعَ هَوَ<rule class=madda_normal>ٮٰ</rule>هُ فَتَرۡدَىٰ ١٦',
    16, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 17 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2365,
    'وَمَا تِلۡكَ بِیَمِینِكَ یَـٰمُوسَىٰ',
    'وما تلك بيمينك يا موسى',
    'وَمَا تِلۡكَ بِيَمِينِكَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ١٧',
    17, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 18 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2366,
    'قَالَ هِیَ عَصَایَ أَتَوَكَّؤُا۟ عَلَیۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِی وَلِیَ فِیهَا مَـَٔارِبُ أُخۡرَىٰ',
    'قال هي عصاي اتوكا عليها واهش بها على غنمي ولي فيها مارب اخرى',
    'قَالَ هِىَ عَصَاىَ أَتَوَكَّؤُ<rule class=slnt>اۡ</rule> عَلَيۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِى وَلِىَ فِيهَا مَـَٔـارِبُ أُخۡرَىٰ ١٨',
    18, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 19 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2367,
    'قَالَ أَلۡقِهَا یَـٰمُوسَىٰ',
    'قال القها يا موسى',
    'قَالَ أَلۡقِهَا يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ١٩',
    19, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 20 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2368,
    'فَأَلۡقَىٰهَا فَإِذَا هِیَ حَیَّةࣱ تَسۡعَىٰ',
    'فالقاها فاذا هي حية تسعى',
    'فَأَلۡقَ<rule class=madda_normal>ـٰ</rule>هَا فَإِذَا هِىَ حَيَّ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>َسۡعَىٰ ٢٠',
    20, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 21 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2369,
    'قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِیدُهَا سِیرَتَهَا ٱلۡأُولَىٰ',
    'قال خذها ولا تخف سنعيدها سيرتها الاولى',
    'قَالَ خُذۡهَا وَلَا تَخَفۡ‌ۖ سَنُعِيدُهَا سِيرَتَهَا <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ ٢١',
    21, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 22 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2370,
    'وَٱضۡمُمۡ یَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَیۡضَاۤءَ مِنۡ غَیۡرِ سُوۤءٍ ءَایَةً أُخۡرَىٰ',
    'واضمم يدك الى جناحك تخرج بيضاء من غير سوء اية اخرى',
    'وَ<rule class=ham_wasl>ٱ</rule>ضۡمُمۡ يَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُ<rule class=qalaqah>جۡ</rule> بَيۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِنۡ غَيۡرِ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءٍ ءَايَةً أُخۡرَىٰ ٢٢',
    22, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 23 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2371,
    'لِنُرِیَكَ مِنۡ ءَایَـٰتِنَا ٱلۡكُبۡرَى',
    'لنريك من اياتنا الكبرى',
    'لِنُرِيَكَ مِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا <rule class=ham_wasl>ٱ</rule>لۡكُ<rule class=qalaqah>بۡ</rule>رَى ٢٣',
    23, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 24 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2372,
    'ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ',
    'اذهب الى فرعون انه طغى',
    'ٱذۡهَ<rule class=qalaqah>بۡ</rule> إِلَىٰ فِرۡعَوۡنَ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> طَغَىٰ ٢٤',
    24, 16, 4, 313, 270, 125, 'false'
  );
  
  -- Ayah 25 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2373,
    'قَالَ رَبِّ ٱشۡرَحۡ لِی صَدۡرِی',
    'قال رب اشرح لي صدري',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule>شۡرَحۡ لِى صَ<rule class=qalaqah>دۡ</rule>رِى ٢٥',
    25, 16, 4, 313, 271, 125, 'false'
  );
  
