  -- Ayah 35 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2383,
    'إِنَّكَ كُنتَ بِنَا بَصِیرࣰا',
    'انك كنت بنا بصيرا',
    'إِ<rule class=ghunnah>نّ</rule>َكَ كُ<rule class=ikhafa>نت</rule>َ بِنَا بَصِيرًا ٣٥',
    35, 16, 4, 313, 271, 125, 'false'
  );
  
  -- Ayah 36 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2384,
    'قَالَ قَدۡ أُوتِیتَ سُؤۡلَكَ یَـٰمُوسَىٰ',
    'قال قد اوتيت سؤلك يا موسى',
    'قَالَ قَ<rule class=qalaqah>دۡ</rule> أُوتِيتَ سُؤۡلَكَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ٣٦',
    36, 16, 4, 313, 271, 125, 'false'
  );
  
  -- Ayah 37 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2385,
    'وَلَقَدۡ مَنَنَّا عَلَیۡكَ مَرَّةً أُخۡرَىٰۤ',
    'ولقد مننا عليك مرة اخرى',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> مَنَ<rule class=ghunnah>نّ</rule>َا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ ٣٧',
    37, 16, 4, 313, 271, 125, 'false'
  );
  
  -- Ayah 38 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2386,
    'إِذۡ أَوۡحَیۡنَاۤ إِلَىٰۤ أُمِّكَ مَا یُوحَىٰۤ',
    'اذ اوحينا الى امك ما يوحى',
    'إِذۡ أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=ghunnah>مّ</rule>ِكَ مَا يُوحَىٰٓ ٣٨',
    38, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 39 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2387,
    'أَنِ ٱقۡذِفِیهِ فِی ٱلتَّابُوتِ فَٱقۡذِفِیهِ فِی ٱلۡیَمِّ فَلۡیُلۡقِهِ ٱلۡیَمُّ بِٱلسَّاحِلِ یَأۡخُذۡهُ عَدُوࣱّ لِّی وَعَدُوࣱّ لَّهُۥۚ وَأَلۡقَیۡتُ عَلَیۡكَ مَحَبَّةࣰ مِّنِّی وَلِتُصۡنَعَ عَلَىٰ عَیۡنِیۤ',
    'ان اقذفيه في التابوت فاقذفيه في اليم فليلقه اليم بالساحل ياخذه عدو لي وعدو له والقيت عليك محبة مني ولتصنع على عيني',
    'أَنِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>ذِفِيهِ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّابُوتِ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>ذِفِيهِ فِى <rule class=ham_wasl>ٱ</rule>لۡيَ<rule class=ghunnah>مّ</rule>ِ فَلۡيُلۡقِهِ <rule class=ham_wasl>ٱ</rule>لۡيَ<rule class=ghunnah>مّ</rule>ُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاحِلِ يَأۡخُذۡهُ عَدُ<rule class=idgham_wo_ghunnah>وٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّى وَعَدُ<rule class=idgham_wo_ghunnah>وٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَأَلۡقَيۡتُ عَلَيۡكَ مَحَبَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>ِى وَلِتُصۡنَعَ عَلَىٰ عَيۡنِىٓ ٣٩',
    39, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 40 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2388,
    'إِذۡ تَمۡشِیۤ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن یَكۡفُلُهُۥۖ فَرَجَعۡنَـٰكَ إِلَىٰۤ أُمِّكَ كَیۡ تَقَرَّ عَیۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسࣰا فَنَجَّیۡنَـٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّـٰكَ فُتُونࣰاۚ فَلَبِثۡتَ سِنِینَ فِیۤ أَهۡلِ مَدۡیَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرࣲ یَـٰمُوسَىٰ',
    'اذ تمشي اختك فتقول هل ادلكم على من يكفله فرجعناك الى امك كي تقر عينها ولا تحزن وقتلت نفسا فنجيناك من الغم وفتناك فتونا فلبثت سنين في اهل مدين ثم جئت على قدر يا موسى',
    'إِذۡ تَمۡش<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُلُهُ<rule class=madda_normal>ۥ</rule>‌ۖ فَرَجَعۡنَ<rule class=madda_normal>ـٰ</rule>كَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=ghunnah>مّ</rule>ِكَ كَىۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ‌ۚ وَقَتَلۡتَ نَفۡ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ف</rule>َنَجَّيۡنَ<rule class=madda_normal>ـٰ</rule>كَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=ghunnah>مّ</rule>ِ وَفَتَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>كَ فُتُو<rule class=ikhafa>نًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َلَبِثۡتَ سِنِينَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَهۡلِ مَ<rule class=qalaqah>دۡ</rule>يَنَ ثُ<rule class=ghunnah>مّ</rule>َ جِئۡتَ عَلَىٰ قَدَ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ٤٠',
    40, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 41 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2389,
    'وَٱصۡطَنَعۡتُكَ لِنَفۡسِی',
    'واصطنعتك لنفسي',
    'وَ<rule class=ham_wasl>ٱ</rule>صۡطَنَعۡتُكَ لِنَفۡسِى ٤١',
    41, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 42 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2390,
    'ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔایَـٰتِی وَلَا تَنِیَا فِی ذِكۡرِی',
    'اذهب انت واخوك باياتي ولا تنيا في ذكري',
    'ٱذۡهَ<rule class=qalaqah>بۡ</rule> أَ<rule class=ikhafa>نت</rule>َ وَأَخُوكَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِى وَلَا تَنِيَا فِى ذِكۡرِى ٤٢',
    42, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 43 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2391,
    'ٱذۡهَبَاۤ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ',
    'اذهبا الى فرعون انه طغى',
    'ٱذۡهَب<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ فِرۡعَوۡنَ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> طَغَىٰ ٤٣',
    43, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 44 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2392,
    'فَقُولَا لَهُۥ قَوۡلࣰا لَّیِّنࣰا لَّعَلَّهُۥ یَتَذَكَّرُ أَوۡ یَخۡشَىٰ',
    'فقولا له قولا لينا لعله يتذكر او يخشى',
    'فَقُولَا لَهُ<rule class=madda_normal>ۥ</rule> قَوۡل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيِّ<rule class=idgham_wo_ghunnah>نًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّهُ<rule class=madda_normal>ۥ</rule> يَتَذَكَّرُ أَوۡ يَخۡشَىٰ ٤٤',
    44, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 45 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2393,
    'قَالَا رَبَّنَاۤ إِنَّنَا نَخَافُ أَن یَفۡرُطَ عَلَیۡنَاۤ أَوۡ أَن یَطۡغَىٰ',
    'قالا ربنا اننا نخاف ان يفرط علينا او ان يطغى',
    'قَالَا رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َنَا نَخَافُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡرُطَ عَلَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>طۡ</rule>غَىٰ ٤٥',
    45, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 46 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2394,
    'قَالَ لَا تَخَافَاۤۖ إِنَّنِی مَعَكُمَاۤ أَسۡمَعُ وَأَرَىٰ',
    'قال لا تخافا انني معكما اسمع وارى',
    'قَالَ لَا تَخَاف<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َنِى مَعَكُم<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡمَعُ وَأَرَىٰ ٤٦',
    46, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 47 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2395,
    'فَأۡتِیَاهُ فَقُولَاۤ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَـٰكَ بِـَٔایَةࣲ مِّن رَّبِّكَۖ وَٱلسَّلَـٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰۤ',
    'فاتياه فقولا انا رسولا ربك فارسل معنا بني اسرائيل ولا تعذبهم قد جئناك باية من ربك والسلام على من اتبع الهدى',
    'فَأۡتِيَاهُ فَقُول<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ وَلَا تُعَذِّ<rule class=qalaqah>بۡ</rule>هُمۡ‌ۖ قَ<rule class=qalaqah>دۡ</rule> جِئۡنَ<rule class=madda_normal>ـٰ</rule>كَ بِـَٔـايَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَ<rule class=madda_normal>ـٰ</rule>مُ عَلَىٰ مَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰٓ ٤٧',
    47, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 48 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2396,
    'إِنَّا قَدۡ أُوحِیَ إِلَیۡنَاۤ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ',
    'انا قد اوحي الينا ان العذاب على من كذب وتولى',
    'إِ<rule class=ghunnah>نّ</rule>َا قَ<rule class=qalaqah>دۡ</rule> أُوحِىَ إِلَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ عَلَىٰ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبَ وَتَوَلَّىٰ ٤٨',
    48, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 49 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2397,
    'قَالَ فَمَن رَّبُّكُمَا یَـٰمُوسَىٰ',
    'قال فمن ربكما يا موسى',
    'قَالَ فَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبُّكُمَا يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ٤٩',
    49, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 50 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2398,
    'قَالَ رَبُّنَا ٱلَّذِیۤ أَعۡطَىٰ كُلَّ شَیۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ',
    'قال ربنا الذي اعطى كل شيء خلقه ثم هدى',
    'قَالَ رَبُّنَا <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡطَىٰ كُلَّ شَىۡءٍ خَلۡقَهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ هَدَىٰ ٥٠',
    50, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 51 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2399,
    'قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ',
    'قال فما بال القرون الاولى',
    'قَالَ فَمَا بَالُ <rule class=ham_wasl>ٱ</rule>لۡقُرُونِ <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ ٥١',
    51, 16, 4, 314, 271, 125, 'false'
  );
  
  -- Ayah 52 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2400,
    'قَالَ عِلۡمُهَا عِندَ رَبِّی فِی كِتَـٰبࣲۖ لَّا یَضِلُّ رَبِّی وَلَا یَنسَى',
    'قال علمها عند ربي في كتاب لا يضل ربي ولا ينسى',
    'قَالَ عِلۡمُهَا عِ<rule class=ikhafa>ند</rule>َ رَبِّى فِى كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>بٍ‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَضِلُّ رَبِّى وَلَا يَ<rule class=ikhafa>نس</rule>َى ٥٢',
    52, 16, 4, 315, 271, 125, 'false'
  );
  
  -- Ayah 53 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2401,
    'ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدࣰا وَسَلَكَ لَكُمۡ فِیهَا سُبُلࣰا وَأَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجۡنَا بِهِۦۤ أَزۡوَ ٰ⁠جࣰا مِّن نَّبَاتࣲ شَتَّىٰ',
    'الذي جعل لكم الارض مهدا وسلك لكم فيها سبلا وانزل من السماء ماء فاخرجنا به ازواجا من نبات شتى',
    'ٱلَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ مَهۡ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َسَلَكَ لَكُمۡ فِيهَا سُبُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَخۡرَ<rule class=qalaqah>جۡ</rule>نَا بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّبَا<rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ش</rule>َتَّىٰ ٥٣',
    53, 16, 4, 315, 271, 125, 'false'
  );
  
  -- Ayah 54 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2402,
    'كُلُوا۟ وَٱرۡعَوۡا۟ أَنۡعَـٰمَكُمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّأُو۟لِی ٱلنُّهَىٰ',
    'كلوا وارعوا انعامكم ان في ذلك لايات لاولي النهى',
    'كُلُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>رۡعَوۡ<rule class=slnt>اۡ</rule> أَنۡعَ<rule class=madda_normal>ـٰ</rule>مَكُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُهَىٰ ٥٤',
    54, 16, 4, 315, 271, 125, 'false'
  );
  
  -- Ayah 55 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2403,
    '۞ مِنۡهَا خَلَقۡنَـٰكُمۡ وَفِیهَا نُعِیدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ',
    'منها خلقناكم وفيها نعيدكم ومنها نخرجكم تارة اخرى',
    '۞مِنۡهَا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ ٥٥',
    55, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 56 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2404,
    'وَلَقَدۡ أَرَیۡنَـٰهُ ءَایَـٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ',
    'ولقد اريناه اياتنا كلها فكذب وابى',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ ٥٦',
    56, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 57 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2405,
    'قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ یَـٰمُوسَىٰ',
    'قال اجئتنا لتخرجنا من ارضنا بسحرك يا موسى',
    'قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ٥٧',
    57, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 58 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2406,
    'فَلَنَأۡتِیَنَّكَ بِسِحۡرࣲ مِّثۡلِهِۦ فَٱجۡعَلۡ بَیۡنَنَا وَبَیۡنَكَ مَوۡعِدࣰا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَاۤ أَنتَ مَكَانࣰا سُوࣰى',
    'فلناتينك بسحر مثله فاجعل بيننا وبينك موعدا لا نخلفه نحن ولا انت مكانا سوى',
    'فَلَنَأۡتِيَ<rule class=ghunnah>نّ</rule>َكَ بِسِحۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلِه<rule class=madda_normal>ِۦ</rule> فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا نُخۡلِفُهُ<rule class=madda_normal>ۥ</rule> نَحۡنُ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ مَكَا<rule class=ikhafa>نًا</rule> <rule class=ikhafa>سُ</rule>وًى ٥٨',
    58, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 59 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2407,
    'قَالَ مَوۡعِدُكُمۡ یَوۡمُ ٱلزِّینَةِ وَأَن یُحۡشَرَ ٱلنَّاسُ ضُحࣰى',
    'قال موعدكم يوم الزينة وان يحشر الناس ضحى',
    'قَالَ مَوۡعِدُكُمۡ يَوۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زِّينَةِ وَأ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحۡشَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ ضُحًى ٥٩',
    59, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 60 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2408,
    'فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَیۡدَهُۥ ثُمَّ أَتَىٰ',
    'فتولى فرعون فجمع كيده ثم اتى',
    'فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ أَتَىٰ ٦٠',
    60, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 61 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2409,
    'قَالَ لَهُم مُّوسَىٰ وَیۡلَكُمۡ لَا تَفۡتَرُوا۟ عَلَى ٱللَّهِ كَذِبࣰا فَیُسۡحِتَكُم بِعَذَابࣲۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ',
    'قال لهم موسى ويلكم لا تفتروا على الله كذبا فيسحتكم بعذاب وقد خاب من افترى',
    'قَالَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َيُسۡحِتَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِعَذَا<rule class=idgham_ghunnah>بٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َقَ<rule class=qalaqah>دۡ</rule> خَابَ مَنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ ٦١',
    61, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 62 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2410,
    'فَتَنَـٰزَعُوۤا۟ أَمۡرَهُم بَیۡنَهُمۡ وَأَسَرُّوا۟ ٱلنَّجۡوَىٰ',
    'فتنازعوا امرهم بينهم واسروا النجوى',
    'فَتَنَ<rule class=madda_normal>ـٰ</rule>زَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَهُمۡ وَأَسَرُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=qalaqah>جۡ</rule>وَىٰ ٦٢',
    62, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 63 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2411,
    'قَالُوۤا۟ إِنۡ هَـٰذَ ٰ⁠نِ لَسَـٰحِرَ ٰ⁠نِ یُرِیدَانِ أَن یُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَیَذۡهَبَا بِطَرِیقَتِكُمُ ٱلۡمُثۡلَىٰ',
    'قالوا ان هذان لساحران يريدان ان يخرجاكم من ارضكم بسحرهما ويذهبا بطريقتكم المثلى',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_normal>ٰ</rule>نِ لَسَ<rule class=madda_normal>ـٰ</rule>حِر<rule class=madda_normal>ٰ</rule>نِ يُرِيدَانِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡرِجَاك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَرۡضِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ <rule class=ham_wasl>ٱ</rule>لۡمُثۡلَىٰ ٦٣',
    63, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 64 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2412,
    'فَأَجۡمِعُوا۟ كَیۡدَكُمۡ ثُمَّ ٱئۡتُوا۟ صَفࣰّاۚ وَقَدۡ أَفۡلَحَ ٱلۡیَوۡمَ مَنِ ٱسۡتَعۡلَىٰ',
    'فاجمعوا كيدكم ثم ائتوا صفا وقد افلح اليوم من استعلى',
    'فَأَ<rule class=qalaqah>جۡ</rule>مِعُو<rule class=slnt>اۡ</rule> كَيۡدَكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>ئۡتُو<rule class=slnt>اۡ</rule> صَف<rule class=idgham_ghunnah>ًّا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َقَ<rule class=qalaqah>دۡ</rule> أَفۡلَحَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ مَنِ <rule class=ham_wasl>ٱ</rule>سۡتَعۡلَىٰ ٦٤',
    64, 16, 4, 315, 272, 126, 'false'
  );
  
  -- Ayah 65 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2413,
    'قَالُوا۟ یَـٰمُوسَىٰۤ إِمَّاۤ أَن تُلۡقِیَ وَإِمَّاۤ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ',
    'قالوا يا موسى اما ان تلقي واما ان نكون اول من القى',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُلۡقِىَ وَإِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ ٦٥',
    65, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 66 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2414,
    'قَالَ بَلۡ أَلۡقُوا۟ۖ فَإِذَا حِبَالُهُمۡ وَعِصِیُّهُمۡ یُخَیَّلُ إِلَیۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ',
    'قال بل القوا فاذا حبالهم وعصيهم يخيل اليه من سحرهم انها تسعى',
    'قَالَ بَلۡ أَلۡقُو<rule class=slnt>اۡ‌ۖ</rule> فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ِحۡرِهِمۡ أَ<rule class=ghunnah>نّ</rule>َهَا تَسۡعَىٰ ٦٦',
    66, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 67 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2415,
    'فَأَوۡجَسَ فِی نَفۡسِهِۦ خِیفَةࣰ مُّوسَىٰ',
    'فاوجس في نفسه خيفة موسى',
    'فَأَوۡجَسَ فِى نَفۡسِه<rule class=madda_normal>ِۦ</rule> خِيفَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ُّوسَىٰ ٦٧',
    67, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 68 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2416,
    'قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ',
    'قلنا لا تخف انك انت الاعلى',
    'قُلۡنَا لَا تَخَفۡ إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَعۡلَىٰ ٦٨',
    68, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 69 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2417,
    'وَأَلۡقِ مَا فِی یَمِینِكَ تَلۡقَفۡ مَا صَنَعُوۤا۟ۖ إِنَّمَا صَنَعُوا۟ كَیۡدُ سَـٰحِرࣲۖ وَلَا یُفۡلِحُ ٱلسَّاحِرُ حَیۡثُ أَتَىٰ',
    'والق ما في يمينك تلقف ما صنعوا انما صنعوا كيد ساحر ولا يفلح الساحر حيث اتى',
    'وَأَلۡقِ مَا فِى يَمِينِكَ تَلۡقَفۡ مَا صَنَع<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا صَنَعُو<rule class=slnt>اۡ</rule> كَيۡدُ سَ<rule class=madda_normal>ـٰ</rule>حِ<rule class=idgham_ghunnah>رٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاحِرُ حَيۡثُ أَتَىٰ ٦٩',
    69, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 70 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2418,
    'فَأُلۡقِیَ ٱلسَّحَرَةُ سُجَّدࣰا قَالُوۤا۟ ءَامَنَّا بِرَبِّ هَـٰرُونَ وَمُوسَىٰ',
    'فالقي السحرة سجدا قالوا امنا برب هارون وموسى',
    'فَأُلۡقِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَرَةُ سُجَّ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِرَبِّ هَ<rule class=madda_normal>ـٰ</rule>رُونَ وَمُوسَىٰ ٧٠',
    70, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 71 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2419,
    'قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِیرُكُمُ ٱلَّذِی عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَیۡدِیَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَـٰفࣲ وَلَأُصَلِّبَنَّكُمۡ فِی جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَیُّنَاۤ أَشَدُّ عَذَابࣰا وَأَبۡقَىٰ',
    'قال امنتم له قبل ان اذن لكم انه لكبيركم الذي علمكم السحر فلاقطعن ايديكم وارجلكم من خلاف ولاصلبنكم في جذوع النخل ولتعلمن اينا اشد عذابا وابقى',
    'قَالَ ءَامَ<rule class=ikhafa>نت</rule>ُمۡ لَهُ<rule class=madda_normal>ۥ</rule> قَ<rule class=qalaqah>بۡ</rule>لَ أَنۡ ءَاذَنَ لَكُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَكَبِيرُكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى عَلَّمَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّحۡرَ‌ۖ فَلَأُقَطِّعَ<rule class=ghunnah>نّ</rule>َ أَيۡدِيَكُمۡ وَأَرۡجُلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَأُصَلِّبَ<rule class=ghunnah>نّ</rule>َكُمۡ فِى جُذُوعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َخۡلِ وَلَتَعۡلَمُ<rule class=ghunnah>نّ</rule>َ أَيُّن<rule class=madda_obligatory_monfasel>َآ</rule> أَشَدُّ عَذَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>بۡ</rule>قَىٰ ٧١',
    71, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 72 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2420,
    'قَالُوا۟ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَاۤءَنَا مِنَ ٱلۡبَیِّنَـٰتِ وَٱلَّذِی فَطَرَنَاۖ فَٱقۡضِ مَاۤ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِی هَـٰذِهِ ٱلۡحَیَوٰةَ ٱلدُّنۡیَاۤ',
    'قالوا لن نؤثرك على ما جاءنا من البينات والذي فطرنا فاقض ما انت قاض انما تقضي هذه الحياة الدنيا',
    'قَالُو<rule class=slnt>اۡ</rule> ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّؤۡثِرَكَ عَلَىٰ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لَّذِى فَطَرَنَا‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>ضِ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ قَاضٍ‌ۖ إِ<rule class=ghunnah>نّ</rule>َمَا تَ<rule class=qalaqah>قۡ</rule>ضِى هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَآ ٧٢',
    72, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 73 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2421,
    'إِنَّاۤ ءَامَنَّا بِرَبِّنَا لِیَغۡفِرَ لَنَا خَطَـٰیَـٰنَا وَمَاۤ أَكۡرَهۡتَنَا عَلَیۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَیۡرࣱ وَأَبۡقَىٰۤ',
    'انا امنا بربنا ليغفر لنا خطايانا وما اكرهتنا عليه من السحر والله خير وابقى',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَ<rule class=madda_normal>ـٰ</rule>يَ<rule class=madda_normal>ـٰ</rule>نَا وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡرَهۡتَنَا عَلَيۡهِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّحۡرِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>بۡ</rule>قَىٰٓ ٧٣',
    73, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 74 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2422,
    'إِنَّهُۥ مَن یَأۡتِ رَبَّهُۥ مُجۡرِمࣰا فَإِنَّ لَهُۥ جَهَنَّمَ لَا یَمُوتُ فِیهَا وَلَا یَحۡیَىٰ',
    'انه من يات ربه مجرما فان له جهنم لا يموت فيها ولا يحيى',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِ رَبَّهُ<rule class=madda_normal>ۥ</rule> مُ<rule class=qalaqah>جۡ</rule>رِ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ لَهُ<rule class=madda_normal>ۥ</rule> جَهَ<rule class=ghunnah>نّ</rule>َمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ ٧٤',
    74, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 75 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2423,
    'وَمَن یَأۡتِهِۦ مُؤۡمِنࣰا قَدۡ عَمِلَ ٱلصَّـٰلِحَـٰتِ فَأُو۟لَـٰۤىِٕكَ لَهُمُ ٱلدَّرَجَـٰتُ ٱلۡعُلَىٰ',
    'ومن ياته مؤمنا قد عمل الصالحات فاولئك لهم الدرجات العلى',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِه<rule class=madda_normal>ِۦ</rule> مُؤۡمِ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> عَمِلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّرَجَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡعُلَىٰ ٧٥',
    75, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 76 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2424,
    'جَنَّـٰتُ عَدۡنࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَذَ ٰ⁠لِكَ جَزَاۤءُ مَن تَزَكَّىٰ',
    'جنات عدن تجري من تحتها الانهار خالدين فيها وذلك جزاء من تزكى',
    'جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ عَ<rule class=qalaqah>دۡ</rule><rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َزَكَّىٰ ٧٦',
    76, 16, 4, 316, 272, 126, 'false'
  );
  
  -- Ayah 77 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2425,
    'وَلَقَدۡ أَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنۡ أَسۡرِ بِعِبَادِی فَٱضۡرِبۡ لَهُمۡ طَرِیقࣰا فِی ٱلۡبَحۡرِ یَبَسࣰا لَّا تَخَـٰفُ دَرَكࣰا وَلَا تَخۡشَىٰ',
    'ولقد اوحينا الى موسى ان اسر بعبادي فاضرب لهم طريقا في البحر يبسا لا تخاف دركا ولا تخشى',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَنۡ أَسۡرِ بِعِبَادِى فَ<rule class=ham_wasl>ٱ</rule>ضۡرِ<rule class=qalaqah>بۡ</rule> لَهُمۡ طَرِي<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ يَبَ<rule class=idgham_wo_ghunnah>سًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَخَ<rule class=madda_normal>ـٰ</rule>فُ دَرَ<rule class=idgham_ghunnah>كًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَخۡشَىٰ ٧٧',
    77, 16, 4, 317, 273, 126, 'false'
  );
  
  -- Ayah 78 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2426,
    'فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِیَهُم مِّنَ ٱلۡیَمِّ مَا غَشِیَهُمۡ',
    'فاتبعهم فرعون بجنوده فغشيهم من اليم ما غشيهم',
    'فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِه<rule class=madda_normal>ِۦ</rule> فَغَشِيَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡيَ<rule class=ghunnah>مّ</rule>ِ مَا غَشِيَهُمۡ ٧٨',
    78, 16, 4, 317, 273, 126, 'false'
  );
  
  -- Ayah 79 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2427,
    'وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ',
    'واضل فرعون قومه وما هدى',
    'وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُ<rule class=madda_normal>ۥ</rule> وَمَا هَدَىٰ ٧٩',
    79, 16, 4, 317, 273, 126, 'false'
  );
  
  -- Ayah 80 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2428,
    'یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ قَدۡ أَنجَیۡنَـٰكُم مِّنۡ عَدُوِّكُمۡ وَوَ ٰ⁠عَدۡنَـٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَیۡمَنَ وَنَزَّلۡنَا عَلَیۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ',
    'يا بني اسرائيل قد انجيناكم من عدوكم وواعدناكم جانب الطور الايمن ونزلنا عليكم المن والسلوى',
    'يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ قَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَدُوِّكُمۡ وَو<rule class=madda_normal>ٰ</rule>عَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ جَانِبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّورِ <rule class=ham_wasl>ٱ</rule>لۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=ghunnah>نّ</rule>َ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلۡوَىٰ ٨٠',
    80, 16, 4, 317, 273, 126, 'false'
  );
  
  -- Ayah 81 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2429,
    'كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡ وَلَا تَطۡغَوۡا۟ فِیهِ فَیَحِلَّ عَلَیۡكُمۡ غَضَبِیۖ وَمَن یَحۡلِلۡ عَلَیۡهِ غَضَبِی فَقَدۡ هَوَىٰ',
    'كلوا من طيبات ما رزقناكم ولا تطغوا فيه فيحل عليكم غضبي ومن يحلل عليه غضبي فقد هوى',
    'كُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=madda_normal>ـٰ</rule>تِ مَا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ وَلَا تَ<rule class=qalaqah>طۡ</rule>غَوۡ<rule class=slnt>اۡ</rule> فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِى‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َحۡلِلۡ عَلَيۡهِ غَضَبِى فَقَ<rule class=qalaqah>دۡ</rule> هَوَىٰ ٨١',
    81, 16, 4, 317, 273, 126, 'false'
  );
  
  -- Ayah 82 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2430,
    'وَإِنِّی لَغَفَّارࣱ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحࣰا ثُمَّ ٱهۡتَدَىٰ',
    'واني لغفار لمن تاب وامن وعمل صالحا ثم اهتدى',
    'وَإِ<rule class=ghunnah>نّ</rule>ِى لَغَفَّا<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابَ وَءَامَنَ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>هۡتَدَىٰ ٨٢',
    82, 16, 4, 317, 273, 126, 'false'
  );
  
  -- Ayah 83 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2431,
    '۞ وَمَاۤ أَعۡجَلَكَ عَن قَوۡمِكَ یَـٰمُوسَىٰ',
    'وما اعجلك عن قومك يا موسى',
    '۞وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡجَلَكَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِكَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ ٨٣',
    83, 16, 4, 317, 273, 127, 'false'
  );
  
  -- Ayah 84 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2432,
    'قَالَ هُمۡ أُو۟لَاۤءِ عَلَىٰۤ أَثَرِی وَعَجِلۡتُ إِلَیۡكَ رَبِّ لِتَرۡضَىٰ',
    'قال هم اولاء على اثري وعجلت اليك رب لترضى',
    'قَالَ هُمۡ أُ<rule class=slnt>وۡ</rule>ل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَثَرِى وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ ٨٤',
    84, 16, 4, 317, 273, 127, 'false'
  );
  
  -- Ayah 85 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2433,
    'قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِیُّ',
    'قال فانا قد فتنا قومك من بعدك واضلهم السامري',
    'قَالَ فَإِ<rule class=ghunnah>نّ</rule>َا قَ<rule class=qalaqah>دۡ</rule> فَتَ<rule class=ghunnah>نّ</rule>َا قَوۡمَكَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِكَ وَأَضَلَّهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّامِرِىُّ ٨٥',
    85, 16, 4, 317, 273, 127, 'false'
  );
  
  -- Ayah 86 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2434,
    'فَرَجَعَ مُوسَىٰۤ إِلَىٰ قَوۡمِهِۦ غَضۡبَـٰنَ أَسِفࣰاۚ قَالَ یَـٰقَوۡمِ أَلَمۡ یَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَیۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن یَحِلَّ عَلَیۡكُمۡ غَضَبࣱ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِی',
    'فرجع موسى الى قومه غضبان اسفا قال يا قوم الم يعدكم ربكم وعدا حسنا افطال عليكم العهد ام اردتم ان يحل عليكم غضب من ربكم فاخلفتم موعدي',
    'فَرَجَعَ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule> غَضۡبَ<rule class=madda_normal>ـٰ</rule>نَ أَسِ<rule class=ikhafa>فًا‌ۚ</rule> <rule class=ikhafa>ق</rule>َالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ أَلَمۡ يَعِ<rule class=qalaqah>دۡ</rule>كُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًا‌ۚ أَفَطَالَ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡعَهۡدُ أَمۡ أَرَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َحِلَّ عَلَيۡكُمۡ غَضَ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ فَأَخۡلَفۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوۡعِدِى ٨٦',
    86, 16, 4, 317, 273, 127, 'false'
  );
  
  -- Ayah 87 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2435,
    'قَالُوا۟ مَاۤ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَـٰكِنَّا حُمِّلۡنَاۤ أَوۡزَارࣰا مِّن زِینَةِ ٱلۡقَوۡمِ فَقَذَفۡنَـٰهَا فَكَذَ ٰ⁠لِكَ أَلۡقَى ٱلسَّامِرِیُّ',
    'قالوا ما اخلفنا موعدك بملكنا ولكنا حملنا اوزارا من زينة القوم فقذفناها فكذلك القى السامري',
    'قَالُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َا حُ<rule class=ghunnah>مّ</rule>ِلۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡزَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>ِينَةِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ فَقَذَفۡنَ<rule class=madda_normal>ـٰ</rule>هَا فَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَلۡقَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّامِرِىُّ ٨٧',
    87, 16, 4, 317, 273, 127, 'false'
  );
  
  -- Ayah 88 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2436,
    'فَأَخۡرَجَ لَهُمۡ عِجۡلࣰا جَسَدࣰا لَّهُۥ خُوَارࣱ فَقَالُوا۟ هَـٰذَاۤ إِلَـٰهُكُمۡ وَإِلَـٰهُ مُوسَىٰ فَنَسِیَ',
    'فاخرج لهم عجلا جسدا له خوار فقالوا هذا الهكم واله موسى فنسي',
    'فَأَخۡرَجَ لَهُمۡ عِ<rule class=qalaqah>جۡ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ج</rule>َسَ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> خُوَا<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َقَالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هُكُمۡ وَإِلَ<rule class=madda_normal>ـٰ</rule>هُ مُوسَىٰ فَنَسِىَ ٨٨',
    88, 16, 4, 318, 273, 127, 'false'
  );
  
  -- Ayah 89 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2437,
    'أَفَلَا یَرَوۡنَ أَلَّا یَرۡجِعُ إِلَیۡهِمۡ قَوۡلࣰا وَلَا یَمۡلِكُ لَهُمۡ ضَرࣰّا وَلَا نَفۡعࣰا',
    'افلا يرون الا يرجع اليهم قولا ولا يملك لهم ضرا ولا نفعا',
    'أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَمۡلِكُ لَهُمۡ ضَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَفۡعًا ٨٩',
    89, 16, 4, 318, 273, 127, 'false'
  );
  
  -- Ayah 90 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2438,
    'وَلَقَدۡ قَالَ لَهُمۡ هَـٰرُونُ مِن قَبۡلُ یَـٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَـٰنُ فَٱتَّبِعُونِی وَأَطِیعُوۤا۟ أَمۡرِی',
    'ولقد قال لهم هارون من قبل يا قوم انما فتنتم به وان ربكم الرحمن فاتبعوني واطيعوا امري',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> قَالَ لَهُمۡ هَ<rule class=madda_normal>ـٰ</rule>رُونُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ghunnah>نّ</rule>َمَا فُتِ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ فَ<rule class=ham_wasl>ٱ</rule>تَّبِعُونِى وَأَطِيع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرِى ٩٠',
    90, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 91 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2439,
    'قَالُوا۟ لَن نَّبۡرَحَ عَلَیۡهِ عَـٰكِفِینَ حَتَّىٰ یَرۡجِعَ إِلَیۡنَا مُوسَىٰ',
    'قالوا لن نبرح عليه عاكفين حتى يرجع الينا موسى',
    'قَالُو<rule class=slnt>اۡ</rule> ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>بۡ</rule>رَحَ عَلَيۡهِ عَ<rule class=madda_normal>ـٰ</rule>كِفِينَ حَتَّىٰ يَرۡجِعَ إِلَيۡنَا مُوسَىٰ ٩١',
    91, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 92 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2440,
    'قَالَ یَـٰهَـٰرُونُ مَا مَنَعَكَ إِذۡ رَأَیۡتَهُمۡ ضَلُّوۤا۟',
    'قال يا هارون ما منعك اذ رايتهم ضلوا',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>هَ<rule class=madda_normal>ـٰ</rule>رُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓ<rule class=slnt>اۡ</rule> ٩٢',
    92, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 93 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2441,
    'أَلَّا تَتَّبِعَنِۖ أَفَعَصَیۡتَ أَمۡرِی',
    'الا تتبعن افعصيت امري',
    'أَلَّا تَتَّبِعَنِ‌ۖ أَفَعَصَيۡتَ أَمۡرِى ٩٣',
    93, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 94 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2442,
    'قَالَ یَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡیَتِی وَلَا بِرَأۡسِیۤۖ إِنِّی خَشِیتُ أَن تَقُولَ فَرَّقۡتَ بَیۡنَ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ وَلَمۡ تَرۡقُبۡ قَوۡلِی',
    'قال يا ابن ام لا تاخذ بلحيتي ولا براسي اني خشيت ان تقول فرقت بين بني اسرائيل ولم ترقب قولي',
    'قَالَ يَ<rule class=qalaqah>بۡ</rule>نَؤُ<rule class=ghunnah>مّ</rule>َ لَا تَأۡخُذۡ بِلِحۡيَتِى وَلَا بِرَأۡس<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>ِى خَشِيتُ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولَ فَرَّ<rule class=qalaqah>قۡ</rule>تَ بَيۡنَ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ وَلَمۡ تَرۡقُ<rule class=qalaqah>بۡ</rule> قَوۡلِى ٩٤',
    94, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 95 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2443,
    'قَالَ فَمَا خَطۡبُكَ یَـٰسَـٰمِرِیُّ',
    'قال فما خطبك يا سامري',
    'قَالَ فَمَا خَ<rule class=qalaqah>طۡ</rule>بُكَ يَ<rule class=madda_normal>ـٰ</rule>سَ<rule class=madda_normal>ـٰ</rule>مِرِىُّ ٩٥',
    95, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 96 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2444,
    'قَالَ بَصُرۡتُ بِمَا لَمۡ یَبۡصُرُوا۟ بِهِۦ فَقَبَضۡتُ قَبۡضَةࣰ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَ ٰ⁠لِكَ سَوَّلَتۡ لِی نَفۡسِی',
    'قال بصرت بما لم يبصروا به فقبضت قبضة من اثر الرسول فنبذتها وكذلك سولت لي نفسي',
    'قَالَ بَصُرۡتُ بِمَا لَمۡ يَ<rule class=qalaqah>بۡ</rule>صُرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> فَقَبَضۡتُ قَ<rule class=qalaqah>بۡ</rule>ضَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَثَرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ فَنَبَذۡتُهَا وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ سَوَّلَتۡ لِى نَفۡسِى ٩٦',
    96, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 97 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2445,
    'قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِی ٱلۡحَیَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدࣰا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰۤ إِلَـٰهِكَ ٱلَّذِی ظَلۡتَ عَلَیۡهِ عَاكِفࣰاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِی ٱلۡیَمِّ نَسۡفًا',
    'قال فاذهب فان لك في الحياة ان تقول لا مساس وان لك موعدا لن تخلفه وانظر الى الهك الذي ظلت عليه عاكفا لنحرقنه ثم لننسفنه في اليم نسفا',
    'قَالَ فَ<rule class=ham_wasl>ٱ</rule>ذۡهَ<rule class=qalaqah>بۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ لَكَ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولَ لَا مِسَاسَ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َ لَكَ مَوۡعِ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُخۡلَفَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هِكَ <rule class=ham_wasl>ٱ</rule>لَّذِى ظَلۡتَ عَلَيۡهِ عَاكِ<rule class=idgham_wo_ghunnah>فًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّنُحَرِّقَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ لَنَ<rule class=ikhafa>نس</rule>ِفَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡيَ<rule class=ghunnah>مّ</rule>ِ نَسۡفًا ٩٧',
    97, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 98 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2446,
    'إِنَّمَاۤ إِلَـٰهُكُمُ ٱللَّهُ ٱلَّذِی لَاۤ إِلَـٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَیۡءٍ عِلۡمࣰا',
    'انما الهكم الله الذي لا اله الا هو وسع كل شيء علما',
    'إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هُكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۚ وَسِعَ كُلَّ شَىۡءٍ عِلۡمًا ٩٨',
    98, 16, 4, 318, 274, 127, 'false'
  );
  
  -- Ayah 99 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2447,
    'كَذَ ٰ⁠لِكَ نَقُصُّ عَلَیۡكَ مِنۡ أَنۢبَاۤءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَیۡنَـٰكَ مِن لَّدُنَّا ذِكۡرࣰا',
    'كذلك نقص عليك من انباء ما قد سبق وقد اتيناك من لدنا ذكرا',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مَا قَ<rule class=qalaqah>دۡ</rule> سَبَقَ‌ۚ وَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>كَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ghunnah>نّ</rule>َا ذِكۡرًا ٩٩',
    99, 16, 4, 319, 274, 127, 'false'
  );
  
  -- Ayah 100 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2448,
    'مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ یَحۡمِلُ یَوۡمَ ٱلۡقِیَـٰمَةِ وِزۡرًا',
    'من اعرض عنه فانه يحمل يوم القيامة وزرا',
    'مَّنۡ أَعۡرَضَ عَنۡهُ فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَحۡمِلُ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ وِزۡرًا ١٠٠',
    100, 16, 4, 319, 274, 127, 'false'
  );
  
  -- Ayah 101 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2449,
    'خَـٰلِدِینَ فِیهِۖ وَسَاۤءَ لَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ حِمۡلࣰا',
    'خالدين فيه وساء لهم يوم القيامة حملا',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهِ‌ۖ وَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ حِمۡلاً ١٠١',
    101, 16, 4, 319, 274, 127, 'false'
  );
  
  -- Ayah 102 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2450,
    'یَوۡمَ یُنفَخُ فِی ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِینَ یَوۡمَىِٕذࣲ زُرۡقࣰا',
    'يوم ينفخ في الصور ونحشر المجرمين يومئذ زرقا',
    'يَوۡمَ يُ<rule class=ikhafa>نف</rule>َخُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ‌ۚ وَنَحۡشُرُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ز</rule>ُرۡقًا ١٠٢',
    102, 16, 4, 319, 274, 127, 'false'
  );
  
  -- Ayah 103 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2451,
    'یَتَخَـٰفَتُونَ بَیۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرࣰا',
    'يتخافتون بينهم ان لبثتم الا عشرا',
    'يَتَخَ<rule class=madda_normal>ـٰ</rule>فَتُونَ بَيۡنَهُمۡ إ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّبِثۡتُمۡ إِلَّا عَشۡرًا ١٠٣',
    103, 16, 4, 319, 274, 127, 'false'
  );
  
  -- Ayah 104 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2452,
    'نَّحۡنُ أَعۡلَمُ بِمَا یَقُولُونَ إِذۡ یَقُولُ أَمۡثَلُهُمۡ طَرِیقَةً إِن لَّبِثۡتُمۡ إِلَّا یَوۡمࣰا',
    'نحن اعلم بما يقولون اذ يقول امثلهم طريقة ان لبثتم الا يوما',
    'نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ أَمۡثَلُهُمۡ طَرِيقَةً إ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّبِثۡتُمۡ إِلَّا يَوۡمًا ١٠٤',
    104, 16, 4, 319, 274, 127, 'false'
  );
  
  -- Ayah 105 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2453,
    'وَیَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ یَنسِفُهَا رَبِّی نَسۡفࣰا',
    'ويسالونك عن الجبال فقل ينسفها ربي نسفا',
    'وَيَسۡــَٔلُونَكَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡجِبَالِ فَقُلۡ يَ<rule class=ikhafa>نس</rule>ِفُهَا رَبِّى نَسۡفًا ١٠٥',
    105, 16, 4, 319, 275, 127, 'false'
  );
  
  -- Ayah 106 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2454,
    'فَیَذَرُهَا قَاعࣰا صَفۡصَفࣰا',
    'فيذرها قاعا صفصفا',
    'فَيَذَرُهَا قَا<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ص</rule>َفۡصَفًا ١٠٦',
    106, 16, 4, 319, 275, 127, 'false'
  );
  
  -- Ayah 107 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2455,
    'لَّا تَرَىٰ فِیهَا عِوَجࣰا وَلَاۤ أَمۡتࣰا',
    'لا ترى فيها عوجا ولا امتا',
    'لَّا تَرَىٰ فِيهَا عِوَ<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َل<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡتًا ١٠٧',
    107, 16, 4, 319, 275, 127, 'false'
  );
  
  -- Ayah 108 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2456,
    'یَوۡمَىِٕذࣲ یَتَّبِعُونَ ٱلدَّاعِیَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَـٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسࣰا',
    'يومئذ يتبعون الداعي لا عوج له وخشعت الاصوات للرحمن فلا تسمع الا همسا',
    'يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَّبِعُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّاعِىَ لَا عِوَجَ لَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَخَشَعَتِ <rule class=ham_wasl>ٱ</rule>لۡأَصۡوَاتُ لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ فَلَا تَسۡمَعُ إِلَّا هَمۡسًا ١٠٨',
    108, 16, 4, 319, 275, 127, 'false'
  );
  
  -- Ayah 109 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2457,
    'یَوۡمَىِٕذࣲ لَّا تَنفَعُ ٱلشَّفَـٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَـٰنُ وَرَضِیَ لَهُۥ قَوۡلࣰا',
    'يومئذ لا تنفع الشفاعة الا من اذن له الرحمن ورضي له قولا',
    'يَوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّفَ<rule class=madda_normal>ـٰ</rule>عَةُ إِلَّا مَنۡ أَذِنَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ وَرَضِىَ لَهُ<rule class=madda_normal>ۥ</rule> قَوۡلاً ١٠٩',
    109, 16, 4, 319, 275, 127, 'false'
  );
  
  -- Ayah 110 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2458,
    'یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡ وَلَا یُحِیطُونَ بِهِۦ عِلۡمࣰا',
    'يعلم ما بين ايديهم وما خلفهم ولا يحيطون به علما',
    'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِه<rule class=madda_normal>ِۦ</rule> عِلۡمًا ١١٠',
    110, 16, 4, 319, 275, 127, 'false'
  );
  
  -- Ayah 111 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2459,
    '۞ وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَیِّ ٱلۡقَیُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمࣰا',
    'وعنت الوجوه للحي القيوم وقد خاب من حمل ظلما',
    '۞وَعَنَتِ <rule class=ham_wasl>ٱ</rule>لۡوُجُوهُ لِلۡحَىِّ <rule class=ham_wasl>ٱ</rule>لۡقَيُّومِ‌ۖ وَقَ<rule class=qalaqah>دۡ</rule> خَابَ مَنۡ حَمَلَ ظُلۡمًا ١١١',
    111, 16, 4, 319, 275, 128, 'false'
  );
  
  -- Ayah 112 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2460,
    'وَمَن یَعۡمَلۡ مِنَ ٱلصَّـٰلِحَـٰتِ وَهُوَ مُؤۡمِنࣱ فَلَا یَخَافُ ظُلۡمࣰا وَلَا هَضۡمࣰا',
    'ومن يعمل من الصالحات وهو مؤمن فلا يخاف ظلما ولا هضما',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلۡ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَهُوَ مُؤۡمِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َلَا يَخَافُ ظُلۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا هَضۡمًا ١١٢',
    112, 16, 4, 319, 275, 128, 'false'
  );
  
  -- Ayah 113 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2461,
    'وَكَذَ ٰ⁠لِكَ أَنزَلۡنَـٰهُ قُرۡءَانًا عَرَبِیࣰّا وَصَرَّفۡنَا فِیهِ مِنَ ٱلۡوَعِیدِ لَعَلَّهُمۡ یَتَّقُونَ أَوۡ یُحۡدِثُ لَهُمۡ ذِكۡرࣰا',
    'وكذلك انزلناه قرانا عربيا وصرفنا فيه من الوعيد لعلهم يتقون او يحدث لهم ذكرا',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ قُرۡءَانًا عَرَبِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َصَرَّفۡنَا فِيهِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرًا ١١٣',
    113, 16, 4, 319, 275, 128, 'false'
  );
  
  -- Ayah 114 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2462,
    'فَتَعَـٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن یُقۡضَىٰۤ إِلَیۡكَ وَحۡیُهُۥۖ وَقُل رَّبِّ زِدۡنِی عِلۡمࣰا',
    'فتعالى الله الملك الحق ولا تعجل بالقران من قبل ان يقضى اليك وحيه وقل رب زدني علما',
    'فَتَعَ<rule class=madda_normal>ـٰ</rule>لَى <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمَلِكُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۗ وَلَا تَعۡجَلۡ بِ<rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>قۡ</rule>ضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡكَ وَحۡيُهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَقُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبِّ زِ<rule class=qalaqah>دۡ</rule>نِى عِلۡمًا ١١٤',
    114, 16, 4, 320, 275, 128, 'false'
  );
  
  -- Ayah 115 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2463,
    'وَلَقَدۡ عَهِدۡنَاۤ إِلَىٰۤ ءَادَمَ مِن قَبۡلُ فَنَسِیَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمࣰا',
    'ولقد عهدنا الى ادم من قبل فنسي ولم نجد له عزما',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> عَهِ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَادَمَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ فَنَسِىَ وَلَمۡ نَجِ<rule class=qalaqah>دۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> عَزۡمًا ١١٥',
    115, 16, 4, 320, 275, 128, 'false'
  );
  
  -- Ayah 116 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2464,
    'وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ أَبَىٰ',
    'واذ قلنا للملائكة اسجدوا لادم فسجدوا الا ابليس ابى',
    'وَإِذۡ قُلۡنَا لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ <rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> لِأَدَمَ فَسَجَد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>لِيسَ أَبَىٰ ١١٦',
    116, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 117 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2465,
    'فَقُلۡنَا یَـٰۤـَٔادَمُ إِنَّ هَـٰذَا عَدُوࣱّ لَّكَ وَلِزَوۡجِكَ فَلَا یُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰۤ',
    'فقلنا يا ادم ان هذا عدو لك ولزوجك فلا يخرجنكما من الجنة فتشقى',
    'فَقُلۡنَا يَ<rule class=madda_obligatory_mottasel>ـٰٓـ</rule>ـَٔـادَمُ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا عَدُ<rule class=idgham_wo_ghunnah>وٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَ<rule class=ghunnah>نّ</rule>َكُمَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ فَتَشۡقَىٰٓ ١١٧',
    117, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 118 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2466,
    'إِنَّ لَكَ أَلَّا تَجُوعَ فِیهَا وَلَا تَعۡرَىٰ',
    'ان لك الا تجوع فيها ولا تعرى',
    'إِ<rule class=ghunnah>نّ</rule>َ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ ١١٨',
    118, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 119 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2467,
    'وَأَنَّكَ لَا تَظۡمَؤُا۟ فِیهَا وَلَا تَضۡحَىٰ',
    'وانك لا تظما فيها ولا تضحى',
    'وَأَ<rule class=ghunnah>نّ</rule>َكَ لَا تَظۡمَؤُ<rule class=slnt>اۡ</rule> فِيهَا وَلَا تَضۡحَىٰ ١١٩',
    119, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 120 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2468,
    'فَوَسۡوَسَ إِلَیۡهِ ٱلشَّیۡطَـٰنُ قَالَ یَـٰۤـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكࣲ لَّا یَبۡلَىٰ',
    'فوسوس اليه الشيطان قال يا ادم هل ادلك على شجرة الخلد وملك لا يبلى',
    'فَوَسۡوَسَ إِلَيۡهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ قَالَ يَ<rule class=madda_obligatory_mottasel>ـٰٓـ</rule>ـَٔـادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ <rule class=ham_wasl>ٱ</rule>لۡخُلۡدِ وَمُلۡ<rule class=idgham_wo_ghunnah>كٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَ<rule class=qalaqah>بۡ</rule>لَىٰ ١٢٠',
    120, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 121 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2469,
    'فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَ ٰ⁠ تُهُمَا وَطَفِقَا یَخۡصِفَانِ عَلَیۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰۤ ءَادَمُ رَبَّهُۥ فَغَوَىٰ',
    'فاكلا منها فبدت لهما سواتهما وطفقا يخصفان عليهما من ورق الجنة وعصى ادم ربه فغوى',
    'فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡء<rule class=madda_normal>ٰ</rule>تُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َرَقِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ‌ۚ وَعَصَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَادَمُ رَبَّهُ<rule class=madda_normal>ۥ</rule> فَغَوَىٰ ١٢١',
    121, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 122 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2470,
    'ثُمَّ ٱجۡتَبَـٰهُ رَبُّهُۥ فَتَابَ عَلَیۡهِ وَهَدَىٰ',
    'ثم اجتباه ربه فتاب عليه وهدى',
    'ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَبَ<rule class=madda_normal>ـٰ</rule>هُ رَبُّهُ<rule class=madda_normal>ۥ</rule> فَتَابَ عَلَيۡهِ وَهَدَىٰ ١٢٢',
    122, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 123 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2471,
    'قَالَ ٱهۡبِطَا مِنۡهَا جَمِیعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ فَإِمَّا یَأۡتِیَنَّكُم مِّنِّی هُدࣰى فَمَنِ ٱتَّبَعَ هُدَایَ فَلَا یَضِلُّ وَلَا یَشۡقَىٰ',
    'قال اهبطا منها جميعا بعضكم لبعض عدو فاما ياتينكم مني هدى فمن اتبع هداي فلا يضل ولا يشقى',
    'قَالَ <rule class=ham_wasl>ٱ</rule>هۡبِطَا مِنۡهَا جَمِيع<rule class=iqlab>َۢا‌ۖ</rule> <rule class=iqlab>ب</rule>َعۡضُكُمۡ لِبَعۡضٍ عَدُ<rule class=ikhafa>وٌّ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>مّ</rule>َا يَأۡتِيَ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>نّ</rule>ِى هُ<rule class=ikhafa>دًى</rule> <rule class=ikhafa>ف</rule>َمَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَ هُدَاىَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ ١٢٣',
    123, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 124 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2472,
    'وَمَنۡ أَعۡرَضَ عَن ذِكۡرِی فَإِنَّ لَهُۥ مَعِیشَةࣰ ضَنكࣰا وَنَحۡشُرُهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ أَعۡمَىٰ',
    'ومن اعرض عن ذكري فان له معيشة ضنكا ونحشره يوم القيامة اعمى',
    'وَمَنۡ أَعۡرَضَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِى فَإِ<rule class=ghunnah>نّ</rule>َ لَهُ<rule class=madda_normal>ۥ</rule> مَعِيشَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ض</rule>َن<rule class=idgham_ghunnah>كًا</rule> <rule class=idgham_ghunnah>و</rule>َنَحۡشُرُهُ<rule class=madda_normal>ۥ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ أَعۡمَىٰ ١٢٤',
    124, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 125 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2473,
    'قَالَ رَبِّ لِمَ حَشَرۡتَنِیۤ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِیرࣰا',
    'قال رب لم حشرتني اعمى وقد كنت بصيرا',
    'قَالَ رَبِّ لِمَ حَشَرۡتَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡمَىٰ وَقَ<rule class=qalaqah>دۡ</rule> كُ<rule class=ikhafa>نت</rule>ُ بَصِيرًا ١٢٥',
    125, 16, 4, 320, 276, 128, 'false'
  );
  
  -- Ayah 126 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2474,
    'قَالَ كَذَ ٰ⁠لِكَ أَتَتۡكَ ءَایَـٰتُنَا فَنَسِیتَهَاۖ وَكَذَ ٰ⁠لِكَ ٱلۡیَوۡمَ تُنسَىٰ',
    'قال كذلك اتتك اياتنا فنسيتها وكذلك اليوم تنسى',
    'قَالَ كَذ<rule class=madda_normal>ٰ</rule>لِكَ أَتَتۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا فَنَسِيتَهَا‌ۖ وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ تُ<rule class=ikhafa>نس</rule>َىٰ ١٢٦',
    126, 16, 4, 321, 276, 128, 'false'
  );
  
  -- Ayah 127 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2475,
    'وَكَذَ ٰ⁠لِكَ نَجۡزِی مَنۡ أَسۡرَفَ وَلَمۡ یُؤۡمِنۢ بِـَٔایَـٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَشَدُّ وَأَبۡقَىٰۤ',
    'وكذلك نجزي من اسرف ولم يؤمن بايات ربه ولعذاب الاخرة اشد وابقى',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّه<rule class=madda_normal>ِۦ</rule>‌ۚ وَلَعَذَابُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ أَشَدُّ وَأَ<rule class=qalaqah>بۡ</rule>قَىٰٓ ١٢٧',
    127, 16, 4, 321, 276, 128, 'false'
  );
  
  -- Ayah 128 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2476,
    'أَفَلَمۡ یَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ یَمۡشُونَ فِی مَسَـٰكِنِهِمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّأُو۟لِی ٱلنُّهَىٰ',
    'افلم يهد لهم كم اهلكنا قبلهم من القرون يمشون في مساكنهم ان في ذلك لايات لاولي النهى',
    'أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَ<rule class=qalaqah>بۡ</rule>لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقُرُونِ يَمۡشُونَ فِى مَسَ<rule class=madda_normal>ـٰ</rule>كِنِهِمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُهَىٰ ١٢٨',
    128, 16, 4, 321, 276, 128, 'false'
  );
  
  -- Ayah 129 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2477,
    'وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامࣰا وَأَجَلࣱ مُّسَمࣰّى',
    'ولولا كلمة سبقت من ربك لكان لزاما واجل مسمى',
    'وَلَوۡلَا كَلِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>س</rule>َبَقَتۡ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ لَكَانَ لِزَا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َأَجَ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَ<rule class=ghunnah>مّ</rule>ًى ١٢٩',
    129, 16, 4, 321, 277, 128, 'false'
  );
  
  -- Ayah 130 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2478,
    'فَٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَاۤىِٕ ٱلَّیۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ',
    'فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل غروبها ومن اناء الليل فسبح واطراف النهار لعلك ترضى',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَ<rule class=qalaqah>بۡ</rule>لَ طُلُوعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسِ وَقَ<rule class=qalaqah>بۡ</rule>لَ غُرُوبِهَا‌ۖ وَمِنۡ ءَانَآىِٕ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ فَسَبِّحۡ وَأَ<rule class=qalaqah>طۡ</rule>رَافَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ لَعَلَّكَ تَرۡضَىٰ ١٣٠',
    130, 16, 4, 321, 277, 128, 'false'
  );
  
  -- Ayah 131 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2479,
    'وَلَا تَمُدَّنَّ عَیۡنَیۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦۤ أَزۡوَ ٰ⁠جࣰا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا لِنَفۡتِنَهُمۡ فِیهِۚ وَرِزۡقُ رَبِّكَ خَیۡرࣱ وَأَبۡقَىٰ',
    'ولا تمدن عينيك الى ما متعنا به ازواجا منهم زهرة الحياة الدنيا لنفتنهم فيه ورزق ربك خير وابقى',
    'وَلَا تَمُدَّ<rule class=ghunnah>نّ</rule>َ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ زَهۡرَةَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِ‌ۚ وَرِزۡقُ رَبِّكَ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>بۡ</rule>قَىٰ ١٣١',
    131, 16, 4, 321, 277, 128, 'false'
  );
  
  -- Ayah 132 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2480,
    'وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَیۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقࣰاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَـٰقِبَةُ لِلتَّقۡوَىٰ',
    'وامر اهلك بالصلاة واصطبر عليها لا نسالك رزقا نحن نرزقك والعاقبة للتقوى',
    'وَأۡمُرۡ أَهۡلَكَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَ<rule class=ham_wasl>ٱ</rule>صۡطَبِرۡ عَلَيۡهَا‌ۖ لَا نَسۡــَٔلُكَ رِزۡ<rule class=idgham_ghunnah>قًا‌ۖ</rule> <rule class=idgham_ghunnah>ن</rule>َّحۡنُ نَرۡزُقُكَ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>قِبَةُ لِلتَّ<rule class=qalaqah>قۡ</rule>وَىٰ ١٣٢',
    132, 16, 4, 321, 277, 128, 'false'
  );
  
  -- Ayah 133 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2481,
    'وَقَالُوا۟ لَوۡلَا یَأۡتِینَا بِـَٔایَةࣲ مِّن رَّبِّهِۦۤۚ أَوَلَمۡ تَأۡتِهِم بَیِّنَةُ مَا فِی ٱلصُّحُفِ ٱلۡأُولَىٰ',
    'وقالوا لولا ياتينا باية من ربه اولم تاتهم بينة ما في الصحف الاولى',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَوۡلَا يَأۡتِينَا بِـَٔـايَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> أَوَلَمۡ تَأۡتِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>َيِّنَةُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّحُفِ <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ ١٣٣',
    133, 16, 4, 321, 277, 128, 'false'
  );
  
  -- Ayah 134 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2482,
    'وَلَوۡ أَنَّاۤ أَهۡلَكۡنَـٰهُم بِعَذَابࣲ مِّن قَبۡلِهِۦ لَقَالُوا۟ رَبَّنَا لَوۡلَاۤ أَرۡسَلۡتَ إِلَیۡنَا رَسُولࣰا فَنَتَّبِعَ ءَایَـٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ',
    'ولو انا اهلكناهم بعذاب من قبله لقالوا ربنا لولا ارسلت الينا رسولا فنتبع اياتك من قبل ان نذل ونخزى',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِعَذَا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> لَقَالُو<rule class=slnt>اۡ</rule> رَبَّنَا لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡتَ إِلَيۡنَا رَسُول<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>َنَتَّبِعَ ءَايَ<rule class=madda_normal>ـٰ</rule>تِكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّذِلَّ وَنَخۡزَىٰ ١٣٤',
    134, 16, 4, 321, 277, 128, 'false'
  );
  
  -- Ayah 135 Surah Taa-Haa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    20,
    2483,
    'قُلۡ كُلࣱّ مُّتَرَبِّصࣱ فَتَرَبَّصُوا۟ۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَـٰبُ ٱلصِّرَ ٰ⁠طِ ٱلسَّوِیِّ وَمَنِ ٱهۡتَدَىٰ',
    'قل كل متربص فتربصوا فستعلمون من اصحاب الصراط السوي ومن اهتدى',
    'قُلۡ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّتَرَبِّ<rule class=ikhafa>صٌ</rule> <rule class=ikhafa>ف</rule>َتَرَبَّصُو<rule class=slnt>اۡ‌ۖ</rule> فَسَتَعۡلَمُونَ مَنۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّر<rule class=madda_normal>ٰ</rule>طِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّوِىِّ وَمَنِ <rule class=ham_wasl>ٱ</rule>هۡتَدَىٰ ١٣٥',
    135, 16, 4, 321, 277, 128, 'false'
  );
  

-- Surah Al-Anbiyaa
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (21, 'سُورَةُ الأَنبِيَاءِ', 'Al-Anbiyaa', 'The Prophets', 'Meccan', 112);

  -- Ayah 1 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2484,
    'ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِی غَفۡلَةࣲ مُّعۡرِضُونَ',
    'اقترب للناس حسابهم وهم في غفلة معرضون',
    'ٱ<rule class=qalaqah>قۡ</rule>تَرَبَ لِل<rule class=ghunnah>نّ</rule>َاسِ حِسَابُهُمۡ وَهُمۡ فِى غَفۡلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 2 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2485,
    'مَا یَأۡتِیهِم مِّن ذِكۡرࣲ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ یَلۡعَبُونَ',
    'ما ياتيهم من ذكر من ربهم محدث الا استمعوه وهم يلعبون',
    'مَا يَأۡتِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّحۡدَثٍ إِلَّا <rule class=ham_wasl>ٱ</rule>سۡتَمَعُوهُ وَهُمۡ يَلۡعَب<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 3 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2486,
    'لَاهِیَةࣰ قُلُوبُهُمۡۗ وَأَسَرُّوا۟ ٱلنَّجۡوَى ٱلَّذِینَ ظَلَمُوا۟ هَلۡ هَـٰذَاۤ إِلَّا بَشَرࣱ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ',
    'لاهية قلوبهم واسروا النجوى الذين ظلموا هل هذا الا بشر مثلكم افتاتون السحر وانتم تبصرون',
    'لَاهِيَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ق</rule>ُلُوبُهُمۡ‌ۗ وَأَسَرُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=qalaqah>جۡ</rule>وَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> هَلۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُكُمۡ‌ۖ أَفَتَأۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّحۡرَ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 4 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2487,
    'قَالَ رَبِّی یَعۡلَمُ ٱلۡقَوۡلَ فِی ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'قال ربي يعلم القول في السماء والارض وهو السميع العليم',
    'قَالَ رَبِّى يَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٤',
    4, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 5 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2488,
    'بَلۡ قَالُوۤا۟ أَضۡغَـٰثُ أَحۡلَـٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرࣱ فَلۡیَأۡتِنَا بِـَٔایَةࣲ كَمَاۤ أُرۡسِلَ ٱلۡأَوَّلُونَ',
    'بل قالوا اضغاث احلام بل افتراه بل هو شاعر فلياتنا باية كما ارسل الاولون',
    'بَلۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَضۡغَ<rule class=madda_normal>ـٰ</rule>ثُ أَحۡلَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>مِۭ</rule> <rule class=iqlab>ب</rule>َلِ <rule class=ham_wasl>ٱ</rule>فۡتَرَ<rule class=madda_normal>ٮٰ</rule>هُ بَلۡ هُوَ شَاعِ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َلۡيَأۡتِنَا بِـَٔـايَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ك</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلَ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 6 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2489,
    'مَاۤ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡیَةٍ أَهۡلَكۡنَـٰهَاۤۖ أَفَهُمۡ یُؤۡمِنُونَ',
    'ما امنت قبلهم من قرية اهلكناها افهم يؤمنون',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَنَتۡ قَ<rule class=qalaqah>بۡ</rule>لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ أَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> أَفَهُمۡ يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 7 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2490,
    'وَمَاۤ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالࣰا نُّوحِیۤ إِلَیۡهِمۡۖ فَسۡـَٔلُوۤا۟ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ',
    'وما ارسلنا قبلك الا رجالا نوحي اليهم فاسالوا اهل الذكر ان كنتم لا تعلمون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا قَ<rule class=qalaqah>بۡ</rule>لَكَ إِلَّا رِجَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ن</rule>ُّوح<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِمۡ‌ۖ فَسۡــَٔل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 8 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2491,
    'وَمَا جَعَلۡنَـٰهُمۡ جَسَدࣰا لَّا یَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَـٰلِدِینَ',
    'وما جعلناهم جسدا لا ياكلون الطعام وما كانوا خالدين',
    'وَمَا جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ جَسَ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَأۡكُلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّعَامَ وَمَا كَانُو<rule class=slnt>اۡ</rule> خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 9 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2492,
    'ثُمَّ صَدَقۡنَـٰهُمُ ٱلۡوَعۡدَ فَأَنجَیۡنَـٰهُمۡ وَمَن نَّشَاۤءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِینَ',
    'ثم صدقناهم الوعد فانجيناهم ومن نشاء واهلكنا المسرفين',
    'ثُ<rule class=ghunnah>مّ</rule>َ صَدَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡوَعۡدَ فَأَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَأَهۡلَكۡنَا <rule class=ham_wasl>ٱ</rule>لۡمُسۡرِف<rule class=madda_permissible>ِي</rule>نَ ٩',
    9, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 10 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2493,
    'لَقَدۡ أَنزَلۡنَاۤ إِلَیۡكُمۡ كِتَـٰبࣰا فِیهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ',
    'لقد انزلنا اليكم كتابا فيه ذكركم افلا تعقلون',
    'لَقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكُمۡ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>ِيهِ ذِكۡرُكُمۡ‌ۖ أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 17, 4, 322, 278, 129, 'false'
  );
  
  -- Ayah 11 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2494,
    'وَكَمۡ قَصَمۡنَا مِن قَرۡیَةࣲ كَانَتۡ ظَالِمَةࣰ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِینَ',
    'وكم قصمنا من قرية كانت ظالمة وانشانا بعدها قوما اخرين',
    'وَكَمۡ قَصَمۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ك</rule>َانَتۡ ظَالِمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نش</rule>َأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَر<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 12 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2495,
    'فَلَمَّاۤ أَحَسُّوا۟ بَأۡسَنَاۤ إِذَا هُم مِّنۡهَا یَرۡكُضُونَ',
    'فلما احسوا باسنا اذا هم منها يركضون',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَحَسُّو<rule class=slnt>اۡ</rule> بَأۡسَن<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا يَرۡكُض<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 13 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2496,
    'لَا تَرۡكُضُوا۟ وَٱرۡجِعُوۤا۟ إِلَىٰ مَاۤ أُتۡرِفۡتُمۡ فِیهِ وَمَسَـٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ',
    'لا تركضوا وارجعوا الى ما اترفتم فيه ومساكنكم لعلكم تسالون',
    'لَا تَرۡكُضُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>رۡجِع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أُتۡرِفۡتُمۡ فِيهِ وَمَسَ<rule class=madda_normal>ـٰ</rule>كِنِكُمۡ لَعَلَّكُمۡ تُسۡــَٔل<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 14 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2497,
    'قَالُوا۟ یَـٰوَیۡلَنَاۤ إِنَّا كُنَّا ظَـٰلِمِینَ',
    'قالوا يا ويلنا انا كنا ظالمين',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٤',
    14, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 15 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2498,
    'فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَـٰهُمۡ حَصِیدًا خَـٰمِدِینَ',
    'فما زالت تلك دعواهم حتى جعلناهم حصيدا خامدين',
    'فَمَا زَالَت تِّلۡكَ دَعۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ حَتَّىٰ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ حَصِيدًا خَ<rule class=madda_normal>ـٰ</rule>مِد<rule class=madda_permissible>ِي</rule>نَ ١٥',
    15, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 16 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2499,
    'وَمَا خَلَقۡنَا ٱلسَّمَاۤءَ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا لَـٰعِبِینَ',
    'وما خلقنا السماء والارض وما بينهما لاعبين',
    'وَمَا خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُمَا لَ<rule class=madda_normal>ـٰ</rule>عِب<rule class=madda_permissible>ِي</rule>نَ ١٦',
    16, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 17 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2500,
    'لَوۡ أَرَدۡنَاۤ أَن نَّتَّخِذَ لَهۡوࣰا لَّٱتَّخَذۡنَـٰهُ مِن لَّدُنَّاۤ إِن كُنَّا فَـٰعِلِینَ',
    'لو اردنا ان نتخذ لهوا لاتخذناه من لدنا ان كنا فاعلين',
    'لَوۡ أَرَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّتَّخِذَ لَهۡ<rule class=idgham_wo_ghunnah>وًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ham_wasl>ٱ</rule>تَّخَذۡنَ<rule class=madda_normal>ـٰ</rule>هُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا فَ<rule class=madda_normal>ـٰ</rule>عِل<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 18 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2501,
    'بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَـٰطِلِ فَیَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقࣱۚ وَلَكُمُ ٱلۡوَیۡلُ مِمَّا تَصِفُونَ',
    'بل نقذف بالحق على الباطل فيدمغه فاذا هو زاهق ولكم الويل مما تصفون',
    'بَلۡ نَ<rule class=qalaqah>قۡ</rule>ذِفُ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ عَلَى <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ فَيَ<rule class=qalaqah>دۡ</rule>مَغُهُ<rule class=madda_normal>ۥ</rule> فَإِذَا هُوَ زَاهِ<rule class=idgham_ghunnah>قٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَكُمُ <rule class=ham_wasl>ٱ</rule>لۡوَيۡلُ مِ<rule class=ghunnah>مّ</rule>َا تَصِف<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 19 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2502,
    'وَلَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا یَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا یَسۡتَحۡسِرُونَ',
    'وله من في السماوات والارض ومن عنده لا يستكبرون عن عبادته ولا يستحسرون',
    'وَلَهُ<rule class=madda_normal>ۥ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَمَنۡ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِه<rule class=madda_normal>ِۦ</rule> وَلَا يَسۡتَحۡسِر<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 20 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2503,
    'یُسَبِّحُونَ ٱلَّیۡلَ وَٱلنَّهَارَ لَا یَفۡتُرُونَ',
    'يسبحون الليل والنهار لا يفترون',
    'يُسَبِّحُونَ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ لَا يَفۡتُر<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 21 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2504,
    'أَمِ ٱتَّخَذُوۤا۟ ءَالِهَةࣰ مِّنَ ٱلۡأَرۡضِ هُمۡ یُنشِرُونَ',
    'ام اتخذوا الهة من الارض هم ينشرون',
    'أَمِ <rule class=ham_wasl>ٱ</rule>تَّخَذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَالِهَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ هُمۡ يُ<rule class=ikhafa>نش</rule>ِر<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 22 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2505,
    'لَوۡ كَانَ فِیهِمَاۤ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَـٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا یَصِفُونَ',
    'لو كان فيهما الهة الا الله لفسدتا فسبحان الله رب العرش عما يصفون',
    'لَوۡ كَانَ فِيهِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَالِهَةٌ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ لَفَسَدَتَا‌ۚ فَسُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ عَ<rule class=ghunnah>مّ</rule>َا يَصِف<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 23 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2506,
    'لَا یُسۡـَٔلُ عَمَّا یَفۡعَلُ وَهُمۡ یُسۡـَٔلُونَ',
    'لا يسال عما يفعل وهم يسالون',
    'لَا يُسۡــَٔلُ عَ<rule class=ghunnah>مّ</rule>َا يَفۡعَلُ وَهُمۡ يُسۡــَٔل<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 24 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2507,
    'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ ءَالِهَةࣰۖ قُلۡ هَاتُوا۟ بُرۡهَـٰنَكُمۡۖ هَـٰذَا ذِكۡرُ مَن مَّعِیَ وَذِكۡرُ مَن قَبۡلِیۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ',
    'ام اتخذوا من دونه الهة قل هاتوا برهانكم هذا ذكر من معي وذكر من قبلي بل اكثرهم لا يعلمون الحق فهم معرضون',
    'أَمِ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> ءَالِهَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ق</rule>ُلۡ هَاتُو<rule class=slnt>اۡ</rule> بُرۡهَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ‌ۖ هَ<rule class=madda_normal>ـٰ</rule>ذَا ذِكۡرُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعِىَ وَذِكۡرُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِى‌ۗ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ‌ۖ فَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 17, 4, 323, 279, 129, 'false'
  );
  
  -- Ayah 25 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2508,
    'وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِیۤ إِلَیۡهِ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّاۤ أَنَا۠ فَٱعۡبُدُونِ',
    'وما ارسلنا من قبلك من رسول الا نوحي اليه انه لا اله الا انا فاعبدون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولٍ إِلَّا نُوح<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ فَ<rule class=ham_wasl>ٱ</rule>عۡبُد<rule class=madda_permissible>ُو</rule>نِ ٢٥',
    25, 17, 4, 324, 279, 129, 'false'
  );
  
  -- Ayah 26 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2509,
    'وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحۡمَـٰنُ وَلَدࣰاۗ سُبۡحَـٰنَهُۥۚ بَلۡ عِبَادࣱ مُّكۡرَمُونَ',
    'وقالوا اتخذ الرحمن ولدا سبحانه بل عباد مكرمون',
    'وَقَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّخَذَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ وَلَ<rule class=ikhafa>دًا‌ۗ</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule>‌ۚ بَلۡ عِبَا<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّكۡرَم<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 17, 4, 324, 279, 129, 'false'
  );
  
  -- Ayah 27 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2510,
    'لَا یَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ یَعۡمَلُونَ',
    'لا يسبقونه بالقول وهم بامره يعملون',
    'لَا يَسۡبِقُونَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَمۡرِه<rule class=madda_normal>ِۦ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 17, 4, 324, 279, 129, 'false'
  );
  
  -- Ayah 28 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2511,
    'یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡ وَلَا یَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡیَتِهِۦ مُشۡفِقُونَ',
    'يعلم ما بين ايديهم وما خلفهم ولا يشفعون الا لمن ارتضى وهم من خشيته مشفقون',
    'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ <rule class=ham_wasl>ٱ</rule>رۡتَضَىٰ وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خَشۡيَتِه<rule class=madda_normal>ِۦ</rule> مُشۡفِق<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 17, 4, 324, 279, 129, 'false'
  );
  
  -- Ayah 29 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2512,
    '۞ وَمَن یَقُلۡ مِنۡهُمۡ إِنِّیۤ إِلَـٰهࣱ مِّن دُونِهِۦ فَذَ ٰ⁠لِكَ نَجۡزِیهِ جَهَنَّمَۚ كَذَ ٰ⁠لِكَ نَجۡزِی ٱلظَّـٰلِمِینَ',
    'ومن يقل منهم اني اله من دونه فذلك نجزيه جهنم كذلك نجزي الظالمين',
    '۞وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُلۡ مِنۡهُمۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> فَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِيهِ جَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 17, 4, 324, 279, 130, 'false'
  );
  
  -- Ayah 30 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2513,
    'أَوَلَمۡ یَرَ ٱلَّذِینَ كَفَرُوۤا۟ أَنَّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقࣰا فَفَتَقۡنَـٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَاۤءِ كُلَّ شَیۡءٍ حَیٍّۚ أَفَلَا یُؤۡمِنُونَ',
    'اولم ير الذين كفروا ان السماوات والارض كانتا رتقا ففتقناهما وجعلنا من الماء كل شيء حي افلا يؤمنون',
    'أَوَلَمۡ يَرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ كَانَتَا رَتۡ<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ف</rule>َفَتَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمَا‌ۖ وَجَعَلۡنَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ كُلَّ شَىۡءٍ حَىٍّ‌ۖ أَفَلَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 17, 4, 324, 280, 130, 'false'
  );
  
  -- Ayah 31 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2514,
    'وَجَعَلۡنَا فِی ٱلۡأَرۡضِ رَوَ ٰ⁠سِیَ أَن تَمِیدَ بِهِمۡ وَجَعَلۡنَا فِیهَا فِجَاجࣰا سُبُلࣰا لَّعَلَّهُمۡ یَهۡتَدُونَ',
    'وجعلنا في الارض رواسي ان تميد بهم وجعلنا فيها فجاجا سبلا لعلهم يهتدون',
    'وَجَعَلۡنَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ رَو<rule class=madda_normal>ٰ</rule>سِىَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَا<rule class=ikhafa>جًا</rule> <rule class=ikhafa>س</rule>ُبُل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّهُمۡ يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 17, 4, 324, 280, 130, 'false'
  );
  
  -- Ayah 32 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2515,
    'وَجَعَلۡنَا ٱلسَّمَاۤءَ سَقۡفࣰا مَّحۡفُوظࣰاۖ وَهُمۡ عَنۡ ءَایَـٰتِهَا مُعۡرِضُونَ',
    'وجعلنا السماء سقفا محفوظا وهم عن اياتها معرضون',
    'وَجَعَلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ سَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>َّحۡفُو<rule class=idgham_ghunnah>ظًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ عَنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِهَا مُعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 17, 4, 324, 280, 130, 'false'
  );
  
  -- Ayah 33 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2516,
    'وَهُوَ ٱلَّذِی خَلَقَ ٱلَّیۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ فِی فَلَكࣲ یَسۡبَحُونَ',
    'وهو الذي خلق الليل والنهار والشمس والقمر كل في فلك يسبحون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ‌ۖ كُ<rule class=ikhafa>لٌّ</rule> <rule class=ikhafa>ف</rule>ِى فَلَ<rule class=idgham_ghunnah>كٍ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡبَح<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 17, 4, 324, 280, 130, 'false'
  );
  
  -- Ayah 34 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2517,
    'وَمَا جَعَلۡنَا لِبَشَرࣲ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِی۟ن مِّتَّ فَهُمُ ٱلۡخَـٰلِدُونَ',
    'وما جعلنا لبشر من قبلك الخلد افان مت فهم الخالدون',
    'وَمَا جَعَلۡنَا لِبَشَ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡخُلۡدَ‌ۖ أَفَإِ<rule class=slnt>يۡ</rule><rule class=idgham_ghunnah>ن</rule> <rule class=idgham_ghunnah>م</rule>ِّتَّ فَهُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 17, 4, 324, 280, 130, 'false'
  );
  
  -- Ayah 35 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2518,
    'كُلُّ نَفۡسࣲ ذَاۤىِٕقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَیۡرِ فِتۡنَةࣰۖ وَإِلَیۡنَا تُرۡجَعُونَ',
    'كل نفس ذائقة الموت ونبلوكم بالشر والخير فتنة والينا ترجعون',
    'كُلُّ نَفۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِقَةُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ‌ۗ وَنَ<rule class=qalaqah>بۡ</rule>لُوك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ فِتۡنَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِلَيۡنَا تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 17, 4, 324, 280, 130, 'false'
  );
  
  -- Ayah 36 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2519,
    'وَإِذَا رَءَاكَ ٱلَّذِینَ كَفَرُوۤا۟ إِن یَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَـٰذَا ٱلَّذِی یَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَـٰنِ هُمۡ كَـٰفِرُونَ',
    'واذا راك الذين كفروا ان يتخذونك الا هزوا اهذا الذي يذكر الهتكم وهم بذكر الرحمن هم كافرون',
    'وَإِذَا رَءَاكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذُونَكَ إِلَّا هُزُوًا أَهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى يَذۡكُرُ ءَالِهَتَكُمۡ وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذِكۡرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ هُمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 17, 4, 325, 280, 130, 'false'
  );
  
  -- Ayah 37 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2520,
    'خُلِقَ ٱلۡإِنسَـٰنُ مِنۡ عَجَلࣲۚ سَأُو۟رِیكُمۡ ءَایَـٰتِی فَلَا تَسۡتَعۡجِلُونِ',
    'خلق الانسان من عجل ساريكم اياتي فلا تستعجلون',
    'خُلِقَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ مِنۡ عَجَ<rule class=ikhafa>لٍ‌ۚ</rule> <rule class=ikhafa>س</rule>َأُ<rule class=slnt>وۡ</rule>رِيكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِى فَلَا تَسۡتَعۡجِل<rule class=madda_permissible>ُو</rule>نِ ٣٧',
    37, 17, 4, 325, 280, 130, 'false'
  );
  
  -- Ayah 38 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2521,
    'وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ويقولون متى هذا الوعد ان كنتم صادقين',
    'وَيَقُولُونَ مَتَىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡوَعۡدُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٣٨',
    38, 17, 4, 325, 280, 130, 'false'
  );
  
  -- Ayah 39 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2522,
    'لَوۡ یَعۡلَمُ ٱلَّذِینَ كَفَرُوا۟ حِینَ لَا یَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ یُنصَرُونَ',
    'لو يعلم الذين كفروا حين لا يكفون عن وجوههم النار ولا عن ظهورهم ولا هم ينصرون',
    'لَوۡ يَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> حِينَ لَا يَكُفُّونَ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>و</rule>ُجُوهِهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ وَلَا عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>ُهُورِهِمۡ وَلَا هُمۡ يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 17, 4, 325, 280, 130, 'false'
  );
  
  -- Ayah 40 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2523,
    'بَلۡ تَأۡتِیهِم بَغۡتَةࣰ فَتَبۡهَتُهُمۡ فَلَا یَسۡتَطِیعُونَ رَدَّهَا وَلَا هُمۡ یُنظَرُونَ',
    'بل تاتيهم بغتة فتبهتهم فلا يستطيعون ردها ولا هم ينظرون',
    'بَلۡ تَأۡتِيه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>َغۡتَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َتَ<rule class=qalaqah>بۡ</rule>هَتُهُمۡ فَلَا يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 17, 4, 325, 280, 130, 'false'
  );
  
  -- Ayah 41 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2524,
    'وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلࣲ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِینَ سَخِرُوا۟ مِنۡهُم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'ولقد استهزئ برسل من قبلك فحاق بالذين سخروا منهم ما كانوا به يستهزئون',
    'وَلَقَدِ <rule class=ham_wasl>ٱ</rule>سۡتُهۡزِئَ بِرُسُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ فَحَاقَ بِ<rule class=ham_wasl>ٱ</rule>لَّذِينَ سَخِرُو<rule class=slnt>اۡ</rule> مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 17, 4, 325, 280, 130, 'false'
  );
  
  -- Ayah 42 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2525,
    'قُلۡ مَن یَكۡلَؤُكُم بِٱلَّیۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَـٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ',
    'قل من يكلؤكم بالليل والنهار من الرحمن بل هم عن ذكر ربهم معرضون',
    'قُلۡ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡلَؤُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ‌ۗ بَلۡ هُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِ رَبِّه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 17, 4, 325, 281, 130, 'false'
  );
  
  -- Ayah 43 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2526,
    'أَمۡ لَهُمۡ ءَالِهَةࣱ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا یَسۡتَطِیعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا یُصۡحَبُونَ',
    'ام لهم الهة تمنعهم من دوننا لا يستطيعون نصر انفسهم ولا هم منا يصحبون',
    'أَمۡ لَهُمۡ ءَالِهَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>َمۡنَعُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِنَا‌ۚ لَا يَسۡتَطِيعُونَ نَصۡرَ أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ وَلَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا يُصۡحَب<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 17, 4, 325, 281, 130, 'false'
  );
  
  -- Ayah 44 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2527,
    'بَلۡ مَتَّعۡنَا هَـٰۤؤُلَاۤءِ وَءَابَاۤءَهُمۡ حَتَّىٰ طَالَ عَلَیۡهِمُ ٱلۡعُمُرُۗ أَفَلَا یَرَوۡنَ أَنَّا نَأۡتِی ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۤۚ أَفَهُمُ ٱلۡغَـٰلِبُونَ',
    'بل متعنا هؤلاء واباءهم حتى طال عليهم العمر افلا يرون انا ناتي الارض ننقصها من اطرافها افهم الغالبون',
    'بَلۡ مَتَّعۡنَا هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡعُمُرُ‌ۗ أَفَلَا يَرَوۡنَ أَ<rule class=ghunnah>نّ</rule>َا نَأۡتِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ نَ<rule class=ikhafa>نق</rule>ُصُهَا مِنۡ أَ<rule class=qalaqah>طۡ</rule>رَافِه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أَفَهُمُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>لِب<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 17, 4, 325, 281, 130, 'false'
  );
  
  -- Ayah 45 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2528,
    'قُلۡ إِنَّمَاۤ أُنذِرُكُم بِٱلۡوَحۡیِۚ وَلَا یَسۡمَعُ ٱلصُّمُّ ٱلدُّعَاۤءَ إِذَا مَا یُنذَرُونَ',
    'قل انما انذركم بالوحي ولا يسمع الصم الدعاء اذا ما ينذرون',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نذ</rule>ِرُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡوَحۡىِ‌ۚ وَلَا يَسۡمَعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّ<rule class=ghunnah>مّ</rule>ُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِذَا مَا يُ<rule class=ikhafa>نذ</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 17, 4, 326, 281, 130, 'false'
  );
  
  -- Ayah 46 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2529,
    'وَلَىِٕن مَّسَّتۡهُمۡ نَفۡحَةࣱ مِّنۡ عَذَابِ رَبِّكَ لَیَقُولُنَّ یَـٰوَیۡلَنَاۤ إِنَّا كُنَّا ظَـٰلِمِینَ',
    'ولئن مستهم نفحة من عذاب ربك ليقولن يا ويلنا انا كنا ظالمين',
    'وَلَئ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّسَّتۡهُمۡ نَفۡحَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عَذَابِ رَبِّكَ لَيَقُولُ<rule class=ghunnah>نّ</rule>َ يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 17, 4, 326, 281, 130, 'false'
  );
  
  -- Ayah 47 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2530,
    'وَنَضَعُ ٱلۡمَوَ ٰ⁠زِینَ ٱلۡقِسۡطَ لِیَوۡمِ ٱلۡقِیَـٰمَةِ فَلَا تُظۡلَمُ نَفۡسࣱ شَیۡـࣰٔاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلٍ أَتَیۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَـٰسِبِینَ',
    'ونضع الموازين القسط ليوم القيامة فلا تظلم نفس شيئا وان كان مثقال حبة من خردل اتينا بها وكفى بنا حاسبين',
    'وَنَضَعُ <rule class=ham_wasl>ٱ</rule>لۡمَو<rule class=madda_normal>ٰ</rule>زِينَ <rule class=ham_wasl>ٱ</rule>لۡقِسۡطَ لِيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فَلَا تُظۡلَمُ نَفۡ<rule class=ikhafa>سٌ</rule> <rule class=ikhafa>ش</rule>َيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِثۡقَالَ حَبَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَا‌ۗ وَكَفَىٰ بِنَا حَ<rule class=madda_normal>ـٰ</rule>سِب<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 17, 4, 326, 281, 130, 'false'
  );
  
  -- Ayah 48 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2531,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَىٰ وَهَـٰرُونَ ٱلۡفُرۡقَانَ وَضِیَاۤءࣰ وَذِكۡرࣰا لِّلۡمُتَّقِینَ',
    'ولقد اتينا موسى وهارون الفرقان وضياء وذكرا للمتقين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَىٰ وَهَ<rule class=madda_normal>ـٰ</rule>رُونَ <rule class=ham_wasl>ٱ</rule>لۡفُرۡقَانَ وَضِي<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َذِكۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٤٨',
    48, 17, 4, 326, 281, 130, 'false'
  );
  
  -- Ayah 49 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2532,
    'ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ',
    'الذين يخشون ربهم بالغيب وهم من الساعة مشفقون',
    'ٱلَّذِينَ يَخۡشَوۡنَ رَبَّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ مُشۡفِق<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 17, 4, 326, 281, 130, 'false'
  );
  
  -- Ayah 50 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2533,
    'وَهَـٰذَا ذِكۡرࣱ مُّبَارَكٌ أَنزَلۡنَـٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ',
    'وهذا ذكر مبارك انزلناه افانتم له منكرون',
    'وَهَ<rule class=madda_normal>ـٰ</rule>ذَا ذِكۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّبَارَكٌ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ‌ۚ أَفَأَ<rule class=ikhafa>نت</rule>ُمۡ لَهُ<rule class=madda_normal>ۥ</rule> مُ<rule class=ikhafa>نك</rule>ِر<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 17, 4, 326, 281, 130, 'false'
  );
  
  -- Ayah 51 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2534,
    '۞ وَلَقَدۡ ءَاتَیۡنَاۤ إِبۡرَ ٰ⁠هِیمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَـٰلِمِینَ',
    'ولقد اتينا ابراهيم رشده من قبل وكنا به عالمين',
    '۞وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ رُشۡدَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَكُ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_normal>ِۦ</rule> عَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥١',
    51, 17, 4, 326, 282, 131, 'false'
  );
  
  -- Ayah 52 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2535,
    'إِذۡ قَالَ لِأَبِیهِ وَقَوۡمِهِۦ مَا هَـٰذِهِ ٱلتَّمَاثِیلُ ٱلَّتِیۤ أَنتُمۡ لَهَا عَـٰكِفُونَ',
    'اذ قال لابيه وقومه ما هذه التماثيل التي انتم لها عاكفون',
    'إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِه<rule class=madda_normal>ِۦ</rule> مَا هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّمَاثِيلُ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ لَهَا عَ<rule class=madda_normal>ـٰ</rule>كِف<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 17, 4, 326, 282, 131, 'false'
  );
  
  -- Ayah 53 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2536,
    'قَالُوا۟ وَجَدۡنَاۤ ءَابَاۤءَنَا لَهَا عَـٰبِدِینَ',
    'قالوا وجدنا اباءنا لها عابدين',
    'قَالُو<rule class=slnt>اۡ</rule> وَجَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا لَهَا عَ<rule class=madda_normal>ـٰ</rule>بِد<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 17, 4, 326, 282, 131, 'false'
  );
  
  -- Ayah 54 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2537,
    'قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَاۤؤُكُمۡ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'قال لقد كنتم انتم واباؤكم في ضلال مبين',
    'قَالَ لَقَ<rule class=qalaqah>دۡ</rule> كُ<rule class=ikhafa>نت</rule>ُمۡ أَ<rule class=ikhafa>نت</rule>ُمۡ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٥٤',
    54, 17, 4, 326, 282, 131, 'false'
  );
  
  -- Ayah 55 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2538,
    'قَالُوۤا۟ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّـٰعِبِینَ',
    'قالوا اجئتنا بالحق ام انت من اللاعبين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَجِئۡتَنَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ أَمۡ أَ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّ<rule class=madda_normal>ـٰ</rule>عِب<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 17, 4, 326, 282, 131, 'false'
  );
  
  -- Ayah 56 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2539,
    'قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ ٱلَّذِی فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَ ٰ⁠لِكُم مِّنَ ٱلشَّـٰهِدِینَ',
    'قال بل ربكم رب السماوات والارض الذي فطرهن وانا على ذلكم من الشاهدين',
    'قَالَ بَ<rule class=idgham_mutaqaribayn>ل</rule> رَّبُّكُمۡ رَبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ <rule class=ham_wasl>ٱ</rule>لَّذِى فَطَرَهُ<rule class=ghunnah>نّ</rule>َ وَأَنَاۡ عَلَىٰ ذ<rule class=madda_normal>ٰ</rule>لِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>هِد<rule class=madda_permissible>ِي</rule>نَ ٥٦',
    56, 17, 4, 326, 282, 131, 'false'
  );
  
  -- Ayah 57 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2540,
    'وَتَٱللَّهِ لَأَكِیدَنَّ أَصۡنَـٰمَكُم بَعۡدَ أَن تُوَلُّوا۟ مُدۡبِرِینَ',
    'وتالله لاكيدن اصنامكم بعد ان تولوا مدبرين',
    'وَتَ<rule class=ham_wasl>ٱ</rule>للَّهِ لَأَكِيدَ<rule class=ghunnah>نّ</rule>َ أَصۡنَ<rule class=madda_normal>ـٰ</rule>مَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡدَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُوَلُّو<rule class=slnt>اۡ</rule> مُ<rule class=qalaqah>دۡ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٥٧',
    57, 17, 4, 326, 282, 131, 'false'
  );
  
  -- Ayah 58 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2541,
    'فَجَعَلَهُمۡ جُذَ ٰ⁠ذًا إِلَّا كَبِیرࣰا لَّهُمۡ لَعَلَّهُمۡ إِلَیۡهِ یَرۡجِعُونَ',
    'فجعلهم جذاذا الا كبيرا لهم لعلهم اليه يرجعون',
    'فَجَعَلَهُمۡ جُذ<rule class=madda_normal>ٰ</rule>ذًا إِلَّا كَبِي<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 59 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2542,
    'قَالُوا۟ مَن فَعَلَ هَـٰذَا بِـَٔالِهَتِنَاۤ إِنَّهُۥ لَمِنَ ٱلظَّـٰلِمِینَ',
    'قالوا من فعل هذا بالهتنا انه لمن الظالمين',
    'قَالُو<rule class=slnt>اۡ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َعَلَ هَ<rule class=madda_normal>ـٰ</rule>ذَا بِـَٔـالِهَتِن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥٩',
    59, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 60 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2543,
    'قَالُوا۟ سَمِعۡنَا فَتࣰى یَذۡكُرُهُمۡ یُقَالُ لَهُۥۤ إِبۡرَ ٰ⁠هِیمُ',
    'قالوا سمعنا فتى يذكرهم يقال له ابراهيم',
    'قَالُو<rule class=slnt>اۡ</rule> سَمِعۡنَا فَ<rule class=idgham_ghunnah>تًى</rule> <rule class=idgham_ghunnah>ي</rule>َذۡكُرُهُمۡ يُقَالُ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>ه<rule class=madda_permissible>ِي</rule>مُ ٦٠',
    60, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 61 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2544,
    'قَالُوا۟ فَأۡتُوا۟ بِهِۦ عَلَىٰۤ أَعۡیُنِ ٱلنَّاسِ لَعَلَّهُمۡ یَشۡهَدُونَ',
    'قالوا فاتوا به على اعين الناس لعلهم يشهدون',
    'قَالُو<rule class=slnt>اۡ</rule> فَأۡتُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَعۡيُنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَعَلَّهُمۡ يَشۡهَد<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 62 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2545,
    'قَالُوۤا۟ ءَأَنتَ فَعَلۡتَ هَـٰذَا بِـَٔالِهَتِنَا یَـٰۤإِبۡرَ ٰ⁠هِیمُ',
    'قالوا اانت فعلت هذا بالهتنا يا ابراهيم',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَأَ<rule class=ikhafa>نت</rule>َ فَعَلۡتَ هَ<rule class=madda_normal>ـٰ</rule>ذَا بِـَٔـالِهَتِنَا يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>ه<rule class=madda_permissible>ِي</rule>مُ ٦٢',
    62, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 63 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2546,
    'قَالَ بَلۡ فَعَلَهُۥ كَبِیرُهُمۡ هَـٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُوا۟ یَنطِقُونَ',
    'قال بل فعله كبيرهم هذا فاسالوهم ان كانوا ينطقون',
    'قَالَ بَلۡ فَعَلَهُ<rule class=madda_normal>ۥ</rule> كَبِيرُهُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا فَسۡــَٔلُوهُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> يَ<rule class=ikhafa>نط</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 64 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2547,
    'فَرَجَعُوۤا۟ إِلَىٰۤ أَنفُسِهِمۡ فَقَالُوۤا۟ إِنَّكُمۡ أَنتُمُ ٱلظَّـٰلِمُونَ',
    'فرجعوا الى انفسهم فقالوا انكم انتم الظالمون',
    'فَرَجَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ فَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َكُمۡ أَ<rule class=ikhafa>نت</rule>ُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 65 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2548,
    'ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَـٰۤؤُلَاۤءِ یَنطِقُونَ',
    'ثم نكسوا على رءوسهم لقد علمت ما هؤلاء ينطقون',
    'ثُ<rule class=ghunnah>مّ</rule>َ نُكِسُو<rule class=slnt>اۡ</rule> عَلَىٰ رُءُوسِهِمۡ لَقَ<rule class=qalaqah>دۡ</rule> عَلِمۡتَ مَا هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ يَ<rule class=ikhafa>نط</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 66 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2549,
    'قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَنفَعُكُمۡ شَیۡـࣰٔا وَلَا یَضُرُّكُمۡ',
    'قال افتعبدون من دون الله ما لا ينفعكم شيئا ولا يضركم',
    'قَالَ أَفَتَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَ<rule class=ikhafa>نف</rule>َعُكُمۡ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَضُرُّكُمۡ ٦٦',
    66, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 67 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2550,
    'أُفࣲّ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ',
    'اف لكم ولما تعبدون من دون الله افلا تعقلون',
    'أُ<rule class=idgham_wo_ghunnah>فٍّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَلِمَا تَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 68 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2551,
    'قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوۤا۟ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَـٰعِلِینَ',
    'قالوا حرقوه وانصروا الهتكم ان كنتم فاعلين',
    'قَالُو<rule class=slnt>اۡ</rule> حَرِّقُوهُ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نص</rule>ُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَالِهَتَكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ فَ<rule class=madda_normal>ـٰ</rule>عِل<rule class=madda_permissible>ِي</rule>نَ ٦٨',
    68, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 69 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2552,
    'قُلۡنَا یَـٰنَارُ كُونِی بَرۡدࣰا وَسَلَـٰمًا عَلَىٰۤ إِبۡرَ ٰ⁠هِیمَ',
    'قلنا يا نار كوني بردا وسلاما على ابراهيم',
    'قُلۡنَا يَ<rule class=madda_normal>ـٰ</rule>نَارُ كُونِى بَرۡ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َسَلَ<rule class=madda_normal>ـٰ</rule>مًا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>ه<rule class=madda_permissible>ِي</rule>مَ ٦٩',
    69, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 70 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2553,
    'وَأَرَادُوا۟ بِهِۦ كَیۡدࣰا فَجَعَلۡنَـٰهُمُ ٱلۡأَخۡسَرِینَ',
    'وارادوا به كيدا فجعلناهم الاخسرين',
    'وَأَرَادُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> كَيۡ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡأَخۡسَر<rule class=madda_permissible>ِي</rule>نَ ٧٠',
    70, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 71 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2554,
    'وَنَجَّیۡنَـٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِی بَـٰرَكۡنَا فِیهَا لِلۡعَـٰلَمِینَ',
    'ونجيناه ولوطا الى الارض التي باركنا فيها للعالمين',
    'وَنَجَّيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَلُوطًا إِلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ <rule class=ham_wasl>ٱ</rule>لَّتِى بَ<rule class=madda_normal>ـٰ</rule>رَكۡنَا فِيهَا لِلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٧١',
    71, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 72 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2555,
    'وَوَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَ نَافِلَةࣰۖ وَكُلࣰّا جَعَلۡنَا صَـٰلِحِینَ',
    'ووهبنا له اسحاق ويعقوب نافلة وكلا جعلنا صالحين',
    'وَوَهَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ نَافِلَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َكُل<rule class=ikhafa>اًّ</rule> <rule class=ikhafa>ج</rule>َعَلۡنَا صَ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٧٢',
    72, 17, 4, 327, 282, 131, 'false'
  );
  
  -- Ayah 73 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2556,
    'وَجَعَلۡنَـٰهُمۡ أَىِٕمَّةࣰ یَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَیۡنَاۤ إِلَیۡهِمۡ فِعۡلَ ٱلۡخَیۡرَ ٰ⁠تِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِیتَاۤءَ ٱلزَّكَوٰةِۖ وَكَانُوا۟ لَنَا عَـٰبِدِینَ',
    'وجعلناهم ائمة يهدون بامرنا واوحينا اليهم فعل الخيرات واقام الصلاة وايتاء الزكاة وكانوا لنا عابدين',
    'وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ أَئِ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِمۡ فِعۡلَ <rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تِ وَإِقَامَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَإِيت<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ‌ۖ وَكَانُو<rule class=slnt>اۡ</rule> لَنَا عَ<rule class=madda_normal>ـٰ</rule>بِد<rule class=madda_permissible>ِي</rule>نَ ٧٣',
    73, 17, 4, 328, 282, 131, 'false'
  );
  
  -- Ayah 74 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2557,
    'وَلُوطًا ءَاتَیۡنَـٰهُ حُكۡمࣰا وَعِلۡمࣰا وَنَجَّیۡنَـٰهُ مِنَ ٱلۡقَرۡیَةِ ٱلَّتِی كَانَت تَّعۡمَلُ ٱلۡخَبَـٰۤىِٕثَۚ إِنَّهُمۡ كَانُوا۟ قَوۡمَ سَوۡءࣲ فَـٰسِقِینَ',
    'ولوطا اتيناه حكما وعلما ونجيناه من القرية التي كانت تعمل الخبائث انهم كانوا قوم سوء فاسقين',
    'وَلُوطًا ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ حُكۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َعِلۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َنَجَّيۡنَ<rule class=madda_normal>ـٰ</rule>هُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةِ <rule class=ham_wasl>ٱ</rule>لَّتِى كَانَت تَّعۡمَلُ <rule class=ham_wasl>ٱ</rule>لۡخَبَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِثَ‌ۗ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> قَوۡمَ سَوۡ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٧٤',
    74, 17, 4, 328, 282, 131, 'false'
  );
  
  -- Ayah 75 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2558,
    'وَأَدۡخَلۡنَـٰهُ فِی رَحۡمَتِنَاۤۖ إِنَّهُۥ مِنَ ٱلصَّـٰلِحِینَ',
    'وادخلناه في رحمتنا انه من الصالحين',
    'وَأَ<rule class=qalaqah>دۡ</rule>خَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ فِى رَحۡمَتِن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٧٥',
    75, 17, 4, 328, 282, 131, 'false'
  );
  
  -- Ayah 76 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2559,
    'وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّیۡنَـٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِیمِ',
    'ونوحا اذ نادى من قبل فاستجبنا له فنجيناه واهله من الكرب العظيم',
    'وَنُوحًا إِذۡ نَادَىٰ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ فَ<rule class=ham_wasl>ٱ</rule>سۡتَجَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_normal>ۥ</rule> فَنَجَّيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَأَهۡلَهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَرۡبِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٧٦',
    76, 17, 4, 328, 283, 131, 'false'
  );
  
  -- Ayah 77 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2560,
    'وَنَصَرۡنَـٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمَ سَوۡءࣲ فَأَغۡرَقۡنَـٰهُمۡ أَجۡمَعِینَ',
    'ونصرناه من القوم الذين كذبوا باياتنا انهم كانوا قوم سوء فاغرقناهم اجمعين',
    'وَنَصَرۡنَ<rule class=madda_normal>ـٰ</rule>هُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> قَوۡمَ سَوۡ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ف</rule>َأَغۡرَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٧٧',
    77, 17, 4, 328, 283, 131, 'false'
  );
  
  -- Ayah 78 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2561,
    'وَدَاوُۥدَ وَسُلَیۡمَـٰنَ إِذۡ یَحۡكُمَانِ فِی ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِیهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَـٰهِدِینَ',
    'وداوود وسليمان اذ يحكمان في الحرث اذ نفشت فيه غنم القوم وكنا لحكمهم شاهدين',
    'وَدَاوُ<rule class=madda_normal>ۥ</rule>دَ وَسُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ إِذۡ يَحۡكُمَانِ فِى <rule class=ham_wasl>ٱ</rule>لۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ وَكُ<rule class=ghunnah>نّ</rule>َا لِحُكۡمِهِمۡ شَ<rule class=madda_normal>ـٰ</rule>هِد<rule class=madda_permissible>ِي</rule>نَ ٧٨',
    78, 17, 4, 328, 283, 131, 'false'
  );
  
  -- Ayah 79 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2562,
    'فَفَهَّمۡنَـٰهَا سُلَیۡمَـٰنَۚ وَكُلًّا ءَاتَیۡنَا حُكۡمࣰا وَعِلۡمࣰاۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ یُسَبِّحۡنَ وَٱلطَّیۡرَۚ وَكُنَّا فَـٰعِلِینَ',
    'ففهمناها سليمان وكلا اتينا حكما وعلما وسخرنا مع داوود الجبال يسبحن والطير وكنا فاعلين',
    'فَفَهَّمۡنَ<rule class=madda_normal>ـٰ</rule>هَا سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ‌ۚ وَكُلاًّ ءَاتَيۡنَا حُكۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َعِلۡ<rule class=idgham_ghunnah>مًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َسَخَّرۡنَا مَعَ دَاوُ<rule class=madda_normal>ۥ</rule>دَ <rule class=ham_wasl>ٱ</rule>لۡجِبَالَ يُسَبِّحۡنَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرَ‌ۚ وَكُ<rule class=ghunnah>نّ</rule>َا فَ<rule class=madda_normal>ـٰ</rule>عِل<rule class=madda_permissible>ِي</rule>نَ ٧٩',
    79, 17, 4, 328, 283, 131, 'false'
  );
  
  -- Ayah 80 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2563,
    'وَعَلَّمۡنَـٰهُ صَنۡعَةَ لَبُوسࣲ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَـٰكِرُونَ',
    'وعلمناه صنعة لبوس لكم لتحصنكم من باسكم فهل انتم شاكرون',
    'وَعَلَّمۡنَ<rule class=madda_normal>ـٰ</rule>هُ صَنۡعَةَ لَبُو<rule class=idgham_wo_ghunnah>سٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ لِتُحۡصِنَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َأۡسِكُمۡ‌ۖ فَهَلۡ أَ<rule class=ikhafa>نت</rule>ُمۡ شَ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 17, 4, 328, 283, 131, 'false'
  );
  
  -- Ayah 81 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2564,
    'وَلِسُلَیۡمَـٰنَ ٱلرِّیحَ عَاصِفَةࣰ تَجۡرِی بِأَمۡرِهِۦۤ إِلَى ٱلۡأَرۡضِ ٱلَّتِی بَـٰرَكۡنَا فِیهَاۚ وَكُنَّا بِكُلِّ شَیۡءٍ عَـٰلِمِینَ',
    'ولسليمان الريح عاصفة تجري بامره الى الارض التي باركنا فيها وكنا بكل شيء عالمين',
    'وَلِسُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيحَ عَاصِفَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى بِأَمۡرِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ <rule class=ham_wasl>ٱ</rule>لَّتِى بَ<rule class=madda_normal>ـٰ</rule>رَكۡنَا فِيهَا‌ۚ وَكُ<rule class=ghunnah>نّ</rule>َا بِكُلِّ شَىۡءٍ عَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٨١',
    81, 17, 4, 328, 283, 131, 'false'
  );
  
  -- Ayah 82 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2565,
    'وَمِنَ ٱلشَّیَـٰطِینِ مَن یَغُوصُونَ لَهُۥ وَیَعۡمَلُونَ عَمَلࣰا دُونَ ذَ ٰ⁠لِكَۖ وَكُنَّا لَهُمۡ حَـٰفِظِینَ',
    'ومن الشياطين من يغوصون له ويعملون عملا دون ذلك وكنا لهم حافظين',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغُوصُونَ لَهُ<rule class=madda_normal>ۥ</rule> وَيَعۡمَلُونَ عَمَل<rule class=ikhafa>اً</rule> <rule class=ikhafa>د</rule>ُونَ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۖ وَكُ<rule class=ghunnah>نّ</rule>َا لَهُمۡ حَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ِي</rule>نَ ٨٢',
    82, 17, 4, 329, 283, 131, 'false'
  );
  
  -- Ayah 83 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2566,
    '۞ وَأَیُّوبَ إِذۡ نَادَىٰ رَبَّهُۥۤ أَنِّی مَسَّنِیَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّ ٰ⁠حِمِینَ',
    'وايوب اذ نادى ربه اني مسني الضر وانت ارحم الراحمين',
    '۞وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=ghunnah>نّ</rule>ِى مَسَّنِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّرُّ وَأَ<rule class=ikhafa>نت</rule>َ أَرۡحَمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>حِم<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 17, 4, 329, 283, 132, 'false'
  );
  
  -- Ayah 84 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2567,
    'فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرࣲّۖ وَءَاتَیۡنَـٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةࣰ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَـٰبِدِینَ',
    'فاستجبنا له فكشفنا ما به من ضر واتيناه اهله ومثلهم معهم رحمة من عندنا وذكرى للعابدين',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَجَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_normal>ۥ</rule> فَكَشَفۡنَا مَا بِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>ُ<rule class=idgham_ghunnah>رٍّ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ أَهۡلَهُ<rule class=madda_normal>ۥ</rule> وَمِثۡلَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّعَهُمۡ رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِنَا وَذِكۡرَىٰ لِلۡعَ<rule class=madda_normal>ـٰ</rule>بِد<rule class=madda_permissible>ِي</rule>نَ ٨٤',
    84, 17, 4, 329, 283, 132, 'false'
  );
  
  -- Ayah 85 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2568,
    'وَإِسۡمَـٰعِیلَ وَإِدۡرِیسَ وَذَا ٱلۡكِفۡلِۖ كُلࣱّ مِّنَ ٱلصَّـٰبِرِینَ',
    'واسماعيل وادريس وذا الكفل كل من الصابرين',
    'وَإِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَإِ<rule class=qalaqah>دۡ</rule>رِيسَ وَذَا <rule class=ham_wasl>ٱ</rule>لۡكِفۡلِ‌ۖ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 17, 4, 329, 283, 132, 'false'
  );
  
  -- Ayah 86 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2569,
    'وَأَدۡخَلۡنَـٰهُمۡ فِی رَحۡمَتِنَاۤۖ إِنَّهُم مِّنَ ٱلصَّـٰلِحِینَ',
    'وادخلناهم في رحمتنا انهم من الصالحين',
    'وَأَ<rule class=qalaqah>دۡ</rule>خَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى رَحۡمَتِن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 17, 4, 329, 283, 132, 'false'
  );
  
  -- Ayah 87 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2570,
    'وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَـٰضِبࣰا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَیۡهِ فَنَادَىٰ فِی ٱلظُّلُمَـٰتِ أَن لَّاۤ إِلَـٰهَ إِلَّاۤ أَنتَ سُبۡحَـٰنَكَ إِنِّی كُنتُ مِنَ ٱلظَّـٰلِمِینَ',
    'وذا النون اذ ذهب مغاضبا فظن ان لن نقدر عليه فنادى في الظلمات ان لا اله الا انت سبحانك اني كنت من الظالمين',
    'وَذَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُونِ إِذ ذَّهَبَ مُغَ<rule class=madda_normal>ـٰ</rule>ضِ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َظَ<rule class=ghunnah>نّ</rule>َ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>قۡ</rule>دِرَ عَلَيۡهِ فَنَادَىٰ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ إِ<rule class=ghunnah>نّ</rule>ِى كُ<rule class=ikhafa>نت</rule>ُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 17, 4, 329, 283, 132, 'false'
  );
  
  -- Ayah 88 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2571,
    'فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّیۡنَـٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَ ٰ⁠لِكَ نُـۨجِی ٱلۡمُؤۡمِنِینَ',
    'فاستجبنا له ونجيناه من الغم وكذلك ننجي المؤمنين',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَجَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_normal>ۥ</rule> وَنَجَّيۡنَ<rule class=madda_normal>ـٰ</rule>هُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=ghunnah>مّ</rule>ِ‌ۚ وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ نُـۨجِى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٨٨',
    88, 17, 4, 329, 283, 132, 'false'
  );
  
  -- Ayah 89 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2572,
    'وَزَكَرِیَّاۤ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِی فَرۡدࣰا وَأَنتَ خَیۡرُ ٱلۡوَ ٰ⁠رِثِینَ',
    'وزكريا اذ نادى ربه رب لا تذرني فردا وانت خير الوارثين',
    'وَزَكَرِيّ<rule class=madda_obligatory_monfasel>َآ</rule> إِذۡ نَادَىٰ رَبَّهُ<rule class=madda_normal>ۥ</rule> رَبِّ لَا تَذَرۡنِى فَرۡ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نت</rule>َ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>رِث<rule class=madda_permissible>ِي</rule>نَ ٨٩',
    89, 17, 4, 329, 283, 132, 'false'
  );
  
  -- Ayah 90 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2573,
    'فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ یَحۡیَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥۤۚ إِنَّهُمۡ كَانُوا۟ یُسَـٰرِعُونَ فِی ٱلۡخَیۡرَ ٰ⁠تِ وَیَدۡعُونَنَا رَغَبࣰا وَرَهَبࣰاۖ وَكَانُوا۟ لَنَا خَـٰشِعِینَ',
    'فاستجبنا له ووهبنا له يحيى واصلحنا له زوجه انهم كانوا يسارعون في الخيرات ويدعوننا رغبا ورهبا وكانوا لنا خاشعين',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَجَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_normal>ۥ</rule> وَوَهَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_normal>ۥ</rule> يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُ<rule class=madda_normal>ۥ</rule> زَوۡجَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> يُسَ<rule class=madda_normal>ـٰ</rule>رِعُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تِ وَيَ<rule class=qalaqah>دۡ</rule>عُونَنَا رَغَ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َرَهَ<rule class=idgham_ghunnah>بًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َكَانُو<rule class=slnt>اۡ</rule> لَنَا خَ<rule class=madda_normal>ـٰ</rule>شِع<rule class=madda_permissible>ِي</rule>نَ ٩٠',
    90, 17, 4, 329, 283, 132, 'false'
  );
  
  -- Ayah 91 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2574,
    'وَٱلَّتِیۤ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِیهَا مِن رُّوحِنَا وَجَعَلۡنَـٰهَا وَٱبۡنَهَاۤ ءَایَةࣰ لِّلۡعَـٰلَمِینَ',
    'والتي احصنت فرجها فنفخنا فيها من روحنا وجعلناها وابنها اية للعالمين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّوحِنَا وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هَا وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَه<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 17, 4, 330, 283, 132, 'false'
  );
  
  -- Ayah 92 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2575,
    'إِنَّ هَـٰذِهِۦۤ أُمَّتُكُمۡ أُمَّةࣰ وَ ٰ⁠حِدَةࣰ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ',
    'ان هذه امتكم امة واحدة وانا ربكم فاعبدون',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أُ<rule class=ghunnah>مّ</rule>َتُكُمۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَنَاۡ رَبُّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡبُد<rule class=madda_permissible>ُو</rule>نِ ٩٢',
    92, 17, 4, 330, 283, 132, 'false'
  );
  
  -- Ayah 93 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2576,
    'وَتَقَطَّعُوۤا۟ أَمۡرَهُم بَیۡنَهُمۡۖ كُلٌّ إِلَیۡنَا رَ ٰ⁠جِعُونَ',
    'وتقطعوا امرهم بينهم كل الينا راجعون',
    'وَتَقَطَّع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَهُمۡ‌ۖ كُلٌّ إِلَيۡنَا ر<rule class=madda_normal>ٰ</rule>جِع<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 17, 4, 330, 283, 132, 'false'
  );
  
  -- Ayah 94 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2577,
    'فَمَن یَعۡمَلۡ مِنَ ٱلصَّـٰلِحَـٰتِ وَهُوَ مُؤۡمِنࣱ فَلَا كُفۡرَانَ لِسَعۡیِهِۦ وَإِنَّا لَهُۥ كَـٰتِبُونَ',
    'فمن يعمل من الصالحات وهو مؤمن فلا كفران لسعيه وانا له كاتبون',
    'فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلۡ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَهُوَ مُؤۡمِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َلَا كُفۡرَانَ لِسَعۡيِه<rule class=madda_normal>ِۦ</rule> وَإِ<rule class=ghunnah>نّ</rule>َا لَهُ<rule class=madda_normal>ۥ</rule> كَ<rule class=madda_normal>ـٰ</rule>تِب<rule class=madda_permissible>ُو</rule>نَ ٩٤',
    94, 17, 4, 330, 284, 132, 'false'
  );
  
  -- Ayah 95 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2578,
    'وَحَرَ ٰ⁠مٌ عَلَىٰ قَرۡیَةٍ أَهۡلَكۡنَـٰهَاۤ أَنَّهُمۡ لَا یَرۡجِعُونَ',
    'وحرام على قرية اهلكناها انهم لا يرجعون',
    'وَحَر<rule class=madda_normal>ٰ</rule>مٌ عَلَىٰ قَرۡيَةٍ أَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ لَا يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٩٥',
    95, 17, 4, 330, 284, 132, 'false'
  );
  
  -- Ayah 96 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2579,
    'حَتَّىٰۤ إِذَا فُتِحَتۡ یَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبࣲ یَنسِلُونَ',
    'حتى اذا فتحت ياجوج وماجوج وهم من كل حدب ينسلون',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ حَدَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نس</rule>ِل<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 17, 4, 330, 284, 132, 'false'
  );
  
  -- Ayah 97 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2580,
    'وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِیَ شَـٰخِصَةٌ أَبۡصَـٰرُ ٱلَّذِینَ كَفَرُوا۟ یَـٰوَیۡلَنَا قَدۡ كُنَّا فِی غَفۡلَةࣲ مِّنۡ هَـٰذَا بَلۡ كُنَّا ظَـٰلِمِینَ',
    'واقترب الوعد الحق فاذا هي شاخصة ابصار الذين كفروا يا ويلنا قد كنا في غفلة من هذا بل كنا ظالمين',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تَرَبَ <rule class=ham_wasl>ٱ</rule>لۡوَعۡدُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ فَإِذَا هِىَ شَ<rule class=madda_normal>ـٰ</rule>خِصَةٌ أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَنَا قَ<rule class=qalaqah>دۡ</rule> كُ<rule class=ghunnah>نّ</rule>َا فِى غَفۡلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا بَلۡ كُ<rule class=ghunnah>نّ</rule>َا ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٩٧',
    97, 17, 4, 330, 284, 132, 'false'
  );
  
  -- Ayah 98 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2581,
    'إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَ ٰ⁠رِدُونَ',
    'انكم وما تعبدون من دون الله حصب جهنم انتم لها واردون',
    'إِ<rule class=ghunnah>نّ</rule>َكُمۡ وَمَا تَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ حَصَبُ جَهَ<rule class=ghunnah>نّ</rule>َمَ أَ<rule class=ikhafa>نت</rule>ُمۡ لَهَا و<rule class=madda_normal>ٰ</rule>رِد<rule class=madda_permissible>ُو</rule>نَ ٩٨',
    98, 17, 4, 330, 284, 132, 'false'
  );
  
  -- Ayah 99 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2582,
    'لَوۡ كَانَ هَـٰۤؤُلَاۤءِ ءَالِهَةࣰ مَّا وَرَدُوهَاۖ وَكُلࣱّ فِیهَا خَـٰلِدُونَ',
    'لو كان هؤلاء الهة ما وردوها وكل فيها خالدون',
    'لَوۡ كَانَ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ءَالِهَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>َّا وَرَدُوهَا‌ۖ وَكُ<rule class=ikhafa>لٌّ</rule> <rule class=ikhafa>ف</rule>ِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٩٩',
    99, 17, 4, 330, 284, 132, 'false'
  );
  
  -- Ayah 100 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2583,
    'لَهُمۡ فِیهَا زَفِیرࣱ وَهُمۡ فِیهَا لَا یَسۡمَعُونَ',
    'لهم فيها زفير وهم فيها لا يسمعون',
    'لَهُمۡ فِيهَا زَفِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ فِيهَا لَا يَسۡمَع<rule class=madda_permissible>ُو</rule>نَ ١٠٠',
    100, 17, 4, 330, 284, 132, 'false'
  );
  
  -- Ayah 101 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2584,
    'إِنَّ ٱلَّذِینَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰۤ أُو۟لَـٰۤىِٕكَ عَنۡهَا مُبۡعَدُونَ',
    'ان الذين سبقت لهم منا الحسنى اولئك عنها مبعدون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ سَبَقَتۡ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ عَنۡهَا مُ<rule class=qalaqah>بۡ</rule>عَد<rule class=madda_permissible>ُو</rule>نَ ١٠١',
    101, 17, 4, 330, 284, 132, 'false'
  );
  
  -- Ayah 102 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2585,
    'لَا یَسۡمَعُونَ حَسِیسَهَاۖ وَهُمۡ فِی مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَـٰلِدُونَ',
    'لا يسمعون حسيسها وهم في ما اشتهت انفسهم خالدون',
    'لَا يَسۡمَعُونَ حَسِيسَهَا‌ۖ وَهُمۡ فِى مَا <rule class=ham_wasl>ٱ</rule>شۡتَهَتۡ أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ١٠٢',
    102, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 103 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2586,
    'لَا یَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَـٰۤىِٕكَةُ هَـٰذَا یَوۡمُكُمُ ٱلَّذِی كُنتُمۡ تُوعَدُونَ',
    'لا يحزنهم الفزع الاكبر وتتلقاهم الملائكة هذا يومكم الذي كنتم توعدون',
    'لَا يَحۡزُنُهُمُ <rule class=ham_wasl>ٱ</rule>لۡفَزَعُ <rule class=ham_wasl>ٱ</rule>لۡأَكۡبَرُ وَتَتَلَقَّ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ هَ<rule class=madda_normal>ـٰ</rule>ذَا يَوۡمُكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى كُ<rule class=ikhafa>نت</rule>ُمۡ تُوعَد<rule class=madda_permissible>ُو</rule>نَ ١٠٣',
    103, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 104 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2587,
    'یَوۡمَ نَطۡوِی ٱلسَّمَاۤءَ كَطَیِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَاۤ أَوَّلَ خَلۡقࣲ نُّعِیدُهُۥۚ وَعۡدًا عَلَیۡنَاۤۚ إِنَّا كُنَّا فَـٰعِلِینَ',
    'يوم نطوي السماء كطي السجل للكتب كما بدانا اول خلق نعيده وعدا علينا انا كنا فاعلين',
    'يَوۡمَ نَ<rule class=qalaqah>طۡ</rule>وِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ كَطَىِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّجِلِّ لِلۡكُتُبِ‌ۚ كَمَا بَدَأۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَوَّلَ خَلۡ<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>ن</rule>ُّعِيدُهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَعۡدًا عَلَيۡن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا فَ<rule class=madda_normal>ـٰ</rule>عِل<rule class=madda_permissible>ِي</rule>نَ ١٠٤',
    104, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 105 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2588,
    'وَلَقَدۡ كَتَبۡنَا فِی ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ یَرِثُهَا عِبَادِیَ ٱلصَّـٰلِحُونَ',
    'ولقد كتبنا في الزبور من بعد الذكر ان الارض يرثها عبادي الصالحون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> كَتَ<rule class=qalaqah>بۡ</rule>نَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّبُورِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرِ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ يَرِثُهَا عِبَادِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ُو</rule>نَ ١٠٥',
    105, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 106 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2589,
    'إِنَّ فِی هَـٰذَا لَبَلَـٰغࣰا لِّقَوۡمٍ عَـٰبِدِینَ',
    'ان في هذا لبلاغا لقوم عابدين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى هَ<rule class=madda_normal>ـٰ</rule>ذَا لَبَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>غًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡمٍ عَ<rule class=madda_normal>ـٰ</rule>بِد<rule class=madda_permissible>ِي</rule>نَ ١٠٦',
    106, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 107 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2590,
    'وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا رَحۡمَةࣰ لِّلۡعَـٰلَمِینَ',
    'وما ارسلناك الا رحمة للعالمين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ إِلَّا رَحۡمَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٠٧',
    107, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 108 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2591,
    'قُلۡ إِنَّمَا یُوحَىٰۤ إِلَیَّ أَنَّمَاۤ إِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰ⁠حِدࣱۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ',
    'قل انما يوحى الي انما الهكم اله واحد فهل انتم مسلمون',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىَّ أَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هُكُمۡ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=ikhafa>دٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َهَلۡ أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡلِم<rule class=madda_permissible>ُو</rule>نَ ١٠٨',
    108, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 109 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2592,
    'فَإِن تَوَلَّوۡا۟ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَاۤءࣲۖ وَإِنۡ أَدۡرِیۤ أَقَرِیبٌ أَم بَعِیدࣱ مَّا تُوعَدُونَ',
    'فان تولوا فقل اذنتكم على سواء وان ادري اقريب ام بعيد ما توعدون',
    'فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَقُلۡ ءَاذَ<rule class=ikhafa>نت</rule>ُكُمۡ عَلَىٰ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِنۡ أَ<rule class=qalaqah>دۡ</rule>ر<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَقَرِيبٌ أ<rule class=ikhafa_shafawi>َم</rule> <rule class=ikhafa_shafawi>ب</rule>َعِي<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا تُوعَد<rule class=madda_permissible>ُو</rule>نَ ١٠٩',
    109, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 110 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2593,
    'إِنَّهُۥ یَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَیَعۡلَمُ مَا تَكۡتُمُونَ',
    'انه يعلم الجهر من القول ويعلم ما تكتمون',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لۡجَهۡرَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُم<rule class=madda_permissible>ُو</rule>نَ ١١٠',
    110, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 111 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2594,
    'وَإِنۡ أَدۡرِی لَعَلَّهُۥ فِتۡنَةࣱ لَّكُمۡ وَمَتَـٰعٌ إِلَىٰ حِینࣲ',
    'وان ادري لعله فتنة لكم ومتاع الى حين',
    'وَإِنۡ أَ<rule class=qalaqah>دۡ</rule>رِى لَعَلَّهُ<rule class=madda_normal>ۥ</rule> فِتۡنَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَمَتَ<rule class=madda_normal>ـٰ</rule>عٌ إِلَىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ١١١',
    111, 17, 4, 331, 284, 132, 'false'
  );
  
  -- Ayah 112 Surah Al-Anbiyaa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    21,
    2595,
    'قَـٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَـٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ',
    'قال رب احكم بالحق وربنا الرحمن المستعان على ما تصفون',
    'قَ<rule class=madda_normal>ـٰ</rule>لَ رَبِّ <rule class=ham_wasl>ٱ</rule>حۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۗ وَرَبُّنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَعَانُ عَلَىٰ مَا تَصِف<rule class=madda_permissible>ُو</rule>نَ ١١٢',
    112, 17, 4, 331, 284, 132, 'false'
  );
  

-- Surah Al-Hajj
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (22, 'سُورَةُ الحَجِّ', 'Al-Hajj', 'The Pilgrimage', 'Medinan', 78);

  -- Ayah 1 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2596,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَیۡءٌ عَظِیمࣱ',
    'يا ايها الناس اتقوا ربكم ان زلزلة الساعة شيء عظيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ زَلۡزَلَةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ شَىۡءٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١',
    1, 17, 4, 332, 285, 133, 'false'
  );
  
  -- Ayah 2 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2597,
    'یَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّاۤ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَـٰرَىٰ وَمَا هُم بِسُكَـٰرَىٰ وَلَـٰكِنَّ عَذَابَ ٱللَّهِ شَدِیدࣱ',
    'يوم ترونها تذهل كل مرضعة عما ارضعت وتضع كل ذات حمل حملها وترى الناس سكارى وما هم بسكارى ولكن عذاب الله شديد',
    'يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ سُكَ<rule class=madda_normal>ـٰ</rule>رَىٰ وَمَا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسُكَ<rule class=madda_normal>ـٰ</rule>رَىٰ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ عَذَابَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٢',
    2, 17, 4, 332, 285, 133, 'false'
  );
  
  -- Ayah 3 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2598,
    'وَمِنَ ٱلنَّاسِ مَن یُجَـٰدِلُ فِی ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَیَتَّبِعُ كُلَّ شَیۡطَـٰنࣲ مَّرِیدࣲ',
    'ومن الناس من يجادل في الله بغير علم ويتبع كل شيطان مريد',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجَ<rule class=madda_normal>ـٰ</rule>دِلُ فِى <rule class=ham_wasl>ٱ</rule>للَّهِ بِغَيۡرِ عِلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َيَتَّبِعُ كُلَّ شَيۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>َّر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٣',
    3, 17, 4, 332, 285, 133, 'false'
  );
  
  -- Ayah 4 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2599,
    'كُتِبَ عَلَیۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ یُضِلُّهُۥ وَیَهۡدِیهِ إِلَىٰ عَذَابِ ٱلسَّعِیرِ',
    'كتب عليه انه من تولاه فانه يضله ويهديه الى عذاب السعير',
    'كُتِبَ عَلَيۡهِ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّاهُ فَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يُضِلُّهُ<rule class=madda_normal>ۥ</rule> وَيَهۡدِيهِ إِلَىٰ عَذَابِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّع<rule class=madda_permissible>ِي</rule>رِ ٤',
    4, 17, 4, 332, 285, 133, 'false'
  );
  
  -- Ayah 5 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2600,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِی رَیۡبࣲ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَـٰكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ مِنۡ عَلَقَةࣲ ثُمَّ مِن مُّضۡغَةࣲ مُّخَلَّقَةࣲ وَغَیۡرِ مُخَلَّقَةࣲ لِّنُبَیِّنَ لَكُمۡۚ وَنُقِرُّ فِی ٱلۡأَرۡحَامِ مَا نَشَاۤءُ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى ثُمَّ نُخۡرِجُكُمۡ طِفۡلࣰا ثُمَّ لِتَبۡلُغُوۤا۟ أَشُدَّكُمۡۖ وَمِنكُم مَّن یُتَوَفَّىٰ وَمِنكُم مَّن یُرَدُّ إِلَىٰۤ أَرۡذَلِ ٱلۡعُمُرِ لِكَیۡلَا یَعۡلَمَ مِنۢ بَعۡدِ عِلۡمࣲ شَیۡـࣰٔاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةࣰ فَإِذَاۤ أَنزَلۡنَا عَلَیۡهَا ٱلۡمَاۤءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِیجࣲ',
    'يا ايها الناس ان كنتم في ريب من البعث فانا خلقناكم من تراب ثم من نطفة ثم من علقة ثم من مضغة مخلقة وغير مخلقة لنبين لكم ونقر في الارحام ما نشاء الى اجل مسمى ثم نخرجكم طفلا ثم لتبلغوا اشدكم ومنكم من يتوفى ومنكم من يرد الى ارذل العمر لكيلا يعلم من بعد علم شيئا وترى الارض هامدة فاذا انزلنا عليها الماء اهتزت وربت وانبتت من كل زوج بهيج',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ فِى رَيۡ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡبَعۡثِ فَإِ<rule class=ghunnah>نّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّ<rule class=qalaqah>طۡ</rule>فَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ مِنۡ عَلَقَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّضۡغَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّخَلَّقَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َغَيۡرِ مُخَلَّقَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّنُبَيِّنَ لَكُمۡ‌ۚ وَنُقِرُّ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡحَامِ مَا نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=ikhafa>ًّى</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ نُخۡرِجُكُمۡ طِفۡل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ لِتَ<rule class=qalaqah>بۡ</rule>لُغ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَشُدَّكُمۡ‌ۖ وَمِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُتَوَفَّىٰ وَمِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرَدُّ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَرۡذَلِ <rule class=ham_wasl>ٱ</rule>لۡعُمُرِ لِكَيۡلَا يَعۡلَمَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ عِلۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ش</rule>َيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َتَرَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ هَامِدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡهَا <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>هۡتَزَّتۡ وَرَبَتۡ وَأَ<rule class=iqlab>نۢب</rule>َتَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ زَوۡ<rule class=iqlab>جِۭ</rule> <rule class=iqlab>ب</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ج</rule>ٍ ٥',
    5, 17, 4, 332, 285, 133, 'false'
  );
  
  -- Ayah 6 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2601,
    'ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ یُحۡیِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'ذلك بان الله هو الحق وانه يحيي الموتى وانه على كل شيء قدير',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٦',
    6, 17, 4, 333, 285, 133, 'false'
  );
  
  -- Ayah 7 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2602,
    'وَأَنَّ ٱلسَّاعَةَ ءَاتِیَةࣱ لَّا رَیۡبَ فِیهَا وَأَنَّ ٱللَّهَ یَبۡعَثُ مَن فِی ٱلۡقُبُورِ',
    'وان الساعة اتية لا ريب فيها وان الله يبعث من في القبور',
    'وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ ءَاتِيَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا رَيۡبَ فِيهَا وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>بۡ</rule>عَثُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡقُب<rule class=madda_permissible>ُو</rule>رِ ٧',
    7, 17, 4, 333, 285, 133, 'false'
  );
  
  -- Ayah 8 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2603,
    'وَمِنَ ٱلنَّاسِ مَن یُجَـٰدِلُ فِی ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَلَا هُدࣰى وَلَا كِتَـٰبࣲ مُّنِیرࣲ',
    'ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجَ<rule class=madda_normal>ـٰ</rule>دِلُ فِى <rule class=ham_wasl>ٱ</rule>للَّهِ بِغَيۡرِ عِلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َلَا كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّن<rule class=madda_permissible>ِي</rule>رٍ ٨',
    8, 17, 4, 333, 285, 133, 'false'
  );
  
  -- Ayah 9 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2604,
    'ثَانِیَ عِطۡفِهِۦ لِیُضِلَّ عَن سَبِیلِ ٱللَّهِۖ لَهُۥ فِی ٱلدُّنۡیَا خِزۡیࣱۖ وَنُذِیقُهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ عَذَابَ ٱلۡحَرِیقِ',
    'ثاني عطفه ليضل عن سبيل الله له في الدنيا خزي ونذيقه يوم القيامة عذاب الحريق',
    'ثَانِىَ عِ<rule class=qalaqah>طۡ</rule>فِه<rule class=madda_normal>ِۦ</rule> لِيُضِلَّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ لَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا خِزۡ<rule class=idgham_ghunnah>ىٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َنُذِيقُهُ<rule class=madda_normal>ۥ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡحَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ِ ٩',
    9, 17, 4, 333, 285, 133, 'false'
  );
  
  -- Ayah 10 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2605,
    'ذَ ٰ⁠لِكَ بِمَا قَدَّمَتۡ یَدَاكَ وَأَنَّ ٱللَّهَ لَیۡسَ بِظَلَّـٰمࣲ لِّلۡعَبِیدِ',
    'ذلك بما قدمت يداك وان الله ليس بظلام للعبيد',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِمَا قَدَّمَتۡ يَدَاكَ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَيۡسَ بِظَلَّ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَب<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ١٠',
    10, 17, 4, 333, 285, 133, 'false'
  );
  
  -- Ayah 11 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2606,
    'وَمِنَ ٱلنَّاسِ مَن یَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفࣲۖ فَإِنۡ أَصَابَهُۥ خَیۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةَۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِینُ',
    'ومن الناس من يعبد الله على حرف فان اصابه خير اطمان به وان اصابته فتنة انقلب على وجهه خسر الدنيا والاخرة ذلك هو الخسران المبين',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡبُدُ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ حَرۡ<rule class=ikhafa>فٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِنۡ أَصَابَهُ<rule class=madda_normal>ۥ</rule> خَيۡرٌ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>طۡ</rule>مَأَ<rule class=ghunnah>نّ</rule>َ بِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>َلَبَ عَلَىٰ وَ<rule class=qalaqah>جۡ</rule>هِه<rule class=madda_normal>ِۦ</rule> خَسِرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡخُسۡرَانُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ١١',
    11, 17, 4, 333, 286, 133, 'false'
  );
  
  -- Ayah 12 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2607,
    'یَدۡعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا یَضُرُّهُۥ وَمَا لَا یَنفَعُهُۥۚ ذَ ٰ⁠لِكَ هُوَ ٱلضَّلَـٰلُ ٱلۡبَعِیدُ',
    'يدعو من دون الله ما لا يضره وما لا ينفعه ذلك هو الضلال البعيد',
    'يَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَضُرُّهُ<rule class=madda_normal>ۥ</rule> وَمَا لَا يَ<rule class=ikhafa>نف</rule>َعُهُ<rule class=madda_normal>ۥ</rule>‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لُ <rule class=ham_wasl>ٱ</rule>لۡبَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ١٢',
    12, 17, 4, 333, 286, 133, 'false'
  );
  
  -- Ayah 13 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2608,
    'یَدۡعُوا۟ لَمَن ضَرُّهُۥۤ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِیرُ',
    'يدعو لمن ضره اقرب من نفعه لبئس المولى ولبئس العشير',
    'يَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> لَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َرُّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=qalaqah>قۡ</rule>رَبُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡعِه<rule class=madda_normal>ِۦ</rule>‌ۚ لَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡلَىٰ وَلَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡعَش<rule class=madda_permissible>ِي</rule>رُ ١٣',
    13, 17, 4, 333, 286, 133, 'false'
  );
  
  -- Ayah 14 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2609,
    'إِنَّ ٱللَّهَ یُدۡخِلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۚ إِنَّ ٱللَّهَ یَفۡعَلُ مَا یُرِیدُ',
    'ان الله يدخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار ان الله يفعل ما يريد',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُ<rule class=qalaqah>دۡ</rule>خِلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَفۡعَلُ مَا يُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ١٤',
    14, 17, 4, 333, 286, 133, 'false'
  );
  
  -- Ayah 15 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2610,
    'مَن كَانَ یَظُنُّ أَن لَّن یَنصُرَهُ ٱللَّهُ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ فَلۡیَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَاۤءِ ثُمَّ لۡیَقۡطَعۡ فَلۡیَنظُرۡ هَلۡ یُذۡهِبَنَّ كَیۡدُهُۥ مَا یَغِیظُ',
    'من كان يظن ان لن ينصره الله في الدنيا والاخرة فليمدد بسبب الى السماء ثم ليقطع فلينظر هل يذهبن كيده ما يغيظ',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يَظُ<rule class=ghunnah>نّ</rule>ُ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ فَلۡيَمۡدُ<rule class=qalaqah>دۡ</rule> بِسَبَبٍ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ثُ<rule class=ghunnah>مّ</rule>َ لۡيَ<rule class=qalaqah>قۡ</rule>طَعۡ فَلۡيَ<rule class=ikhafa>نظ</rule>ُرۡ هَلۡ يُذۡهِبَ<rule class=ghunnah>نّ</rule>َ كَيۡدُهُ<rule class=madda_normal>ۥ</rule> مَا يَغ<rule class=madda_permissible>ِي</rule>ظُ ١٥',
    15, 17, 4, 333, 286, 133, 'false'
  );
  
  -- Ayah 16 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2611,
    'وَكَذَ ٰ⁠لِكَ أَنزَلۡنَـٰهُ ءَایَـٰتِۭ بَیِّنَـٰتࣲ وَأَنَّ ٱللَّهَ یَهۡدِی مَن یُرِیدُ',
    'وكذلك انزلناه ايات بينات وان الله يهدي من يريد',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ١٦',
    16, 17, 4, 334, 286, 133, 'false'
  );
  
  -- Ayah 17 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2612,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَادُوا۟ وَٱلصَّـٰبِـِٔینَ وَٱلنَّصَـٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِینَ أَشۡرَكُوۤا۟ إِنَّ ٱللَّهَ یَفۡصِلُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ',
    'ان الذين امنوا والذين هادوا والصابئين والنصارى والمجوس والذين اشركوا ان الله يفصل بينهم يوم القيامة ان الله على كل شيء شهيد',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هَادُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِــِٔينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َصَ<rule class=madda_normal>ـٰ</rule>رَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَجُوسَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ أَشۡرَك<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ش</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٧',
    17, 17, 4, 334, 286, 133, 'false'
  );
  
  -- Ayah 18 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2613,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ یَسۡجُدُ لَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَن فِی ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَاۤبُّ وَكَثِیرࣱ مِّنَ ٱلنَّاسِۖ وَكَثِیرٌ حَقَّ عَلَیۡهِ ٱلۡعَذَابُۗ وَمَن یُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ یَفۡعَلُ مَا یَشَاۤءُ ۩',
    'الم تر ان الله يسجد له من في السماوات ومن في الارض والشمس والقمر والنجوم والجبال والشجر والدواب وكثير من الناس وكثير حق عليه العذاب ومن يهن الله فما له من مكرم ان الله يفعل ما يشاء',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَسۡجُدُ لَهُ<rule class=madda_normal>ۥ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسُ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُجُومُ وَ<rule class=ham_wasl>ٱ</rule>لۡجِبَالُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّو<rule class=madda_necessary>َا</rule>ٓبُّ وَكَثِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُهِنِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَمَا لَهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّكۡرِمٍ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَفۡعَلُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ ۩ ١٨',
    18, 17, 4, 334, 286, 133, '{"id":6,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 19 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2614,
    '۞ هَـٰذَانِ خَصۡمَانِ ٱخۡتَصَمُوا۟ فِی رَبِّهِمۡۖ فَٱلَّذِینَ كَفَرُوا۟ قُطِّعَتۡ لَهُمۡ ثِیَابࣱ مِّن نَّارࣲ یُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِیمُ',
    'هذان خصمان اختصموا في ربهم فالذين كفروا قطعت لهم ثياب من نار يصب من فوق رءوسهم الحميم',
    '۞هَ<rule class=madda_normal>ـٰ</rule>ذَانِ خَصۡمَانِ <rule class=ham_wasl>ٱ</rule>خۡتَصَمُو<rule class=slnt>اۡ</rule> فِى رَبِّهِمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> قُطِّعَتۡ لَهُمۡ ثِيَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّا<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُصَبُّ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِ رُءُوسِهِمُ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule>مُ ١٩',
    19, 17, 4, 334, 286, 134, 'false'
  );
  
  -- Ayah 20 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2615,
    'یُصۡهَرُ بِهِۦ مَا فِی بُطُونِهِمۡ وَٱلۡجُلُودُ',
    'يصهر به ما في بطونهم والجلود',
    'يُصۡهَرُ بِه<rule class=madda_normal>ِۦ</rule> مَا فِى بُطُونِهِمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡجُل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ُ ٢٠',
    20, 17, 4, 334, 286, 134, 'false'
  );
  
  -- Ayah 21 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2616,
    'وَلَهُم مَّقَـٰمِعُ مِنۡ حَدِیدࣲ',
    'ولهم مقامع من حديد',
    'وَلَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّقَ<rule class=madda_normal>ـٰ</rule>مِعُ مِنۡ حَد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٢١',
    21, 17, 4, 334, 286, 134, 'false'
  );
  
  -- Ayah 22 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2617,
    'كُلَّمَاۤ أَرَادُوۤا۟ أَن یَخۡرُجُوا۟ مِنۡهَا مِنۡ غَمٍّ أُعِیدُوا۟ فِیهَا وَذُوقُوا۟ عَذَابَ ٱلۡحَرِیقِ',
    'كلما ارادوا ان يخرجوا منها من غم اعيدوا فيها وذوقوا عذاب الحريق',
    'كُلَّم<rule class=madda_obligatory_monfasel>َآ</rule> أَرَاد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡرُجُو<rule class=slnt>اۡ</rule> مِنۡهَا مِنۡ غَ<rule class=ghunnah>مّ</rule>ٍ أُعِيدُو<rule class=slnt>اۡ</rule> فِيهَا وَذُوقُو<rule class=slnt>اۡ</rule> عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡحَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ِ ٢٢',
    22, 17, 4, 334, 286, 134, 'false'
  );
  
  -- Ayah 23 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2618,
    'إِنَّ ٱللَّهَ یُدۡخِلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ یُحَلَّوۡنَ فِیهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰاۖ وَلِبَاسُهُمۡ فِیهَا حَرِیرࣱ',
    'ان الله يدخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار يحلون فيها من اساور من ذهب ولؤلؤا ولباسهم فيها حرير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُ<rule class=qalaqah>دۡ</rule>خِلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َهَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َلُؤۡلُ<rule class=idgham_ghunnah>ؤًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلِبَاسُهُمۡ فِيهَا حَر<rule class=madda_permissible>ِي</rule>رٌ ٢٣',
    23, 17, 4, 334, 287, 134, 'false'
  );
  
  -- Ayah 24 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2619,
    'وَهُدُوۤا۟ إِلَى ٱلطَّیِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوۤا۟ إِلَىٰ صِرَ ٰ⁠طِ ٱلۡحَمِیدِ',
    'وهدوا الى الطيب من القول وهدوا الى صراط الحميد',
    'وَهُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ وَهُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ صِر<rule class=madda_normal>ٰ</rule>طِ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٢٤',
    24, 17, 4, 335, 287, 134, 'false'
  );
  
  -- Ayah 25 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2620,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِی جَعَلۡنَـٰهُ لِلنَّاسِ سَوَاۤءً ٱلۡعَـٰكِفُ فِیهِ وَٱلۡبَادِۚ وَمَن یُرِدۡ فِیهِ بِإِلۡحَادِۭ بِظُلۡمࣲ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِیمࣲ',
    'ان الذين كفروا ويصدون عن سبيل الله والمسجد الحرام الذي جعلناه للناس سواء العاكف فيه والباد ومن يرد فيه بالحاد بظلم نذقه من عذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَيَصُدُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ لِل<rule class=ghunnah>نّ</rule>َاسِ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءً <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>كِفُ فِيهِ وَ<rule class=ham_wasl>ٱ</rule>لۡبَادِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِ<rule class=qalaqah>دۡ</rule> فِيهِ بِإِلۡحَا<rule class=iqlab>دِۭ</rule> <rule class=iqlab>ب</rule>ِظُلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ن</rule>ُّذِ<rule class=qalaqah>قۡ</rule>هُ مِنۡ عَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٢٥',
    25, 17, 4, 335, 287, 134, 'false'
  );
  
  -- Ayah 26 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2621,
    'وَإِذۡ بَوَّأۡنَا لِإِبۡرَ ٰ⁠هِیمَ مَكَانَ ٱلۡبَیۡتِ أَن لَّا تُشۡرِكۡ بِی شَیۡـࣰٔا وَطَهِّرۡ بَیۡتِیَ لِلطَّاۤىِٕفِینَ وَٱلۡقَاۤىِٕمِینَ وَٱلرُّكَّعِ ٱلسُّجُودِ',
    'واذ بوانا لابراهيم مكان البيت ان لا تشرك بي شيئا وطهر بيتي للطائفين والقائمين والركع السجود',
    'وَإِذۡ بَوَّأۡنَا لِإِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ مَكَانَ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتِ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تُشۡرِكۡ بِى شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َطَهِّرۡ بَيۡتِىَ لِلطّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِمِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّكَّعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّج<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ِ ٢٦',
    26, 17, 4, 335, 288, 134, 'false'
  );
  
  -- Ayah 27 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2622,
    'وَأَذِّن فِی ٱلنَّاسِ بِٱلۡحَجِّ یَأۡتُوكَ رِجَالࣰا وَعَلَىٰ كُلِّ ضَامِرࣲ یَأۡتِینَ مِن كُلِّ فَجٍّ عَمِیقࣲ',
    'واذن في الناس بالحج ياتوك رجالا وعلى كل ضامر ياتين من كل فج عميق',
    'وَأَذِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِ<rule class=ham_wasl>ٱ</rule>لۡحَجِّ يَأۡتُوكَ رِجَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َعَلَىٰ كُلِّ ضَامِ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ فَجٍّ عَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ٍ ٢٧',
    27, 17, 4, 335, 288, 134, 'false'
  );
  
  -- Ayah 28 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2623,
    'لِّیَشۡهَدُوا۟ مَنَـٰفِعَ لَهُمۡ وَیَذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ فِیۤ أَیَّامࣲ مَّعۡلُومَـٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِیمَةِ ٱلۡأَنۡعَـٰمِۖ فَكُلُوا۟ مِنۡهَا وَأَطۡعِمُوا۟ ٱلۡبَاۤىِٕسَ ٱلۡفَقِیرَ',
    'ليشهدوا منافع لهم ويذكروا اسم الله في ايام معلومات على ما رزقهم من بهيمة الانعام فكلوا منها واطعموا البائس الفقير',
    'لِّيَشۡهَدُو<rule class=slnt>اۡ</rule> مَنَ<rule class=madda_normal>ـٰ</rule>فِعَ لَهُمۡ وَيَذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>سۡمَ <rule class=ham_wasl>ٱ</rule>للَّهِ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَيَّا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡلُومَ<rule class=madda_normal>ـٰ</rule>تٍ عَلَىٰ مَا رَزَقَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َهِيمَةِ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ‌ۖ فَكُلُو<rule class=slnt>اۡ</rule> مِنۡهَا وَأَ<rule class=qalaqah>طۡ</rule>عِمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِسَ <rule class=ham_wasl>ٱ</rule>لۡفَق<rule class=madda_permissible>ِي</rule>رَ ٢٨',
    28, 17, 4, 335, 288, 134, 'false'
  );
  
  -- Ayah 29 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2624,
    'ثُمَّ لۡیَقۡضُوا۟ تَفَثَهُمۡ وَلۡیُوفُوا۟ نُذُورَهُمۡ وَلۡیَطَّوَّفُوا۟ بِٱلۡبَیۡتِ ٱلۡعَتِیقِ',
    'ثم ليقضوا تفثهم وليوفوا نذورهم وليطوفوا بالبيت العتيق',
    'ثُ<rule class=ghunnah>مّ</rule>َ لۡيَ<rule class=qalaqah>قۡ</rule>ضُو<rule class=slnt>اۡ</rule> تَفَثَهُمۡ وَلۡيُوفُو<rule class=slnt>اۡ</rule> نُذُورَهُمۡ وَلۡيَطَّوَّفُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡبَيۡتِ <rule class=ham_wasl>ٱ</rule>لۡعَت<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ِ ٢٩',
    29, 17, 4, 335, 288, 134, 'false'
  );
  
  -- Ayah 30 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2625,
    'ذَ ٰ⁠لِكَۖ وَمَن یُعَظِّمۡ حُرُمَـٰتِ ٱللَّهِ فَهُوَ خَیۡرࣱ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَـٰمُ إِلَّا مَا یُتۡلَىٰ عَلَیۡكُمۡۖ فَٱجۡتَنِبُوا۟ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَـٰنِ وَٱجۡتَنِبُوا۟ قَوۡلَ ٱلزُّورِ',
    'ذلك ومن يعظم حرمات الله فهو خير له عند ربه واحلت لكم الانعام الا ما يتلى عليكم فاجتنبوا الرجس من الاوثان واجتنبوا قول الزور',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعَظِّمۡ حُرُمَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَهُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> عِ<rule class=ikhafa>ند</rule>َ رَبِّه<rule class=madda_normal>ِۦ</rule>‌ۗ وَأُحِلَّتۡ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَنِبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّ<rule class=qalaqah>جۡ</rule>سَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَوۡثَ<rule class=madda_normal>ـٰ</rule>نِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَنِبُو<rule class=slnt>اۡ</rule> قَوۡلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زّ<rule class=madda_permissible>ُو</rule>رِ ٣٠',
    30, 17, 4, 335, 288, 134, 'false'
  );
  
  -- Ayah 31 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2626,
    'حُنَفَاۤءَ لِلَّهِ غَیۡرَ مُشۡرِكِینَ بِهِۦۚ وَمَن یُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَاۤءِ فَتَخۡطَفُهُ ٱلطَّیۡرُ أَوۡ تَهۡوِی بِهِ ٱلرِّیحُ فِی مَكَانࣲ سَحِیقࣲ',
    'حنفاء لله غير مشركين به ومن يشرك بالله فكانما خر من السماء فتخطفه الطير او تهوي به الريح في مكان سحيق',
    'حُنَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُشۡرِكۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ فَكَأَ<rule class=ghunnah>نّ</rule>َمَا خَرَّ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَتَخۡطَفُهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرُ أَوۡ تَهۡوِى بِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيحُ فِى مَكَا<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>س</rule>َح<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ٍ ٣١',
    31, 17, 4, 336, 288, 134, 'false'
  );
  
  -- Ayah 32 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2627,
    'ذَ ٰ⁠لِكَۖ وَمَن یُعَظِّمۡ شَعَـٰۤىِٕرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ',
    'ذلك ومن يعظم شعائر الله فانها من تقوى القلوب',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعَظِّمۡ شَعَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَإِ<rule class=ghunnah>نّ</rule>َهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>قۡ</rule>وَى <rule class=ham_wasl>ٱ</rule>لۡقُل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ِ ٣٢',
    32, 17, 4, 336, 288, 134, 'false'
  );
  
  -- Ayah 33 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2628,
    'لَكُمۡ فِیهَا مَنَـٰفِعُ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى ثُمَّ مَحِلُّهَاۤ إِلَى ٱلۡبَیۡتِ ٱلۡعَتِیقِ',
    'لكم فيها منافع الى اجل مسمى ثم محلها الى البيت العتيق',
    'لَكُمۡ فِيهَا مَنَ<rule class=madda_normal>ـٰ</rule>فِعُ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=ikhafa>ًّى</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ مَحِلُّه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡبَيۡتِ <rule class=ham_wasl>ٱ</rule>لۡعَت<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ِ ٣٣',
    33, 17, 4, 336, 288, 134, 'false'
  );
  
  -- Ayah 34 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2629,
    'وَلِكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكࣰا لِّیَذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِیمَةِ ٱلۡأَنۡعَـٰمِۗ فَإِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰ⁠حِدࣱ فَلَهُۥۤ أَسۡلِمُوا۟ۗ وَبَشِّرِ ٱلۡمُخۡبِتِینَ',
    'ولكل امة جعلنا منسكا ليذكروا اسم الله على ما رزقهم من بهيمة الانعام فالهكم اله واحد فله اسلموا وبشر المخبتين',
    'وَلِكُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ج</rule>َعَلۡنَا مَ<rule class=ikhafa>نس</rule>َ<rule class=idgham_wo_ghunnah>كًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>سۡمَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَىٰ مَا رَزَقَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َهِيمَةِ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ‌ۗ فَإِلَ<rule class=madda_normal>ـٰ</rule>هُكُمۡ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَسۡلِمُو<rule class=slnt>اۡ‌ۗ</rule> وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لۡمُخۡبِت<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 17, 4, 336, 289, 134, 'false'
  );
  
  -- Ayah 35 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2630,
    'ٱلَّذِینَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّـٰبِرِینَ عَلَىٰ مَاۤ أَصَابَهُمۡ وَٱلۡمُقِیمِی ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ',
    'الذين اذا ذكر الله وجلت قلوبهم والصابرين على ما اصابهم والمقيمي الصلاة ومما رزقناهم ينفقون',
    'ٱلَّذِينَ إِذَا ذُكِرَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِرِينَ عَلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَهُمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡمُقِيمِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَمِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ يُ<rule class=ikhafa>نف</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 17, 4, 336, 289, 134, 'false'
  );
  
  -- Ayah 36 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2631,
    'وَٱلۡبُدۡنَ جَعَلۡنَـٰهَا لَكُم مِّن شَعَـٰۤىِٕرِ ٱللَّهِ لَكُمۡ فِیهَا خَیۡرࣱۖ فَٱذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ عَلَیۡهَا صَوَاۤفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُوا۟ مِنۡهَا وَأَطۡعِمُوا۟ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَ ٰ⁠لِكَ سَخَّرۡنَـٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ',
    'والبدن جعلناها لكم من شعائر الله لكم فيها خير فاذكروا اسم الله عليها صواف فاذا وجبت جنوبها فكلوا منها واطعموا القانع والمعتر كذلك سخرناها لكم لعلكم تشكرون',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡبُ<rule class=qalaqah>دۡ</rule>نَ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َعَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَكُمۡ فِيهَا خَيۡ<rule class=ikhafa>رٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>سۡمَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡهَا صَو<rule class=madda_necessary>َا</rule>ٓفَّ‌ۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُو<rule class=slnt>اۡ</rule> مِنۡهَا وَأَ<rule class=qalaqah>طۡ</rule>عِمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡقَانِعَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُعۡتَرَّ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ سَخَّرۡنَ<rule class=madda_normal>ـٰ</rule>هَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 17, 4, 336, 289, 134, 'false'
  );
  
  -- Ayah 37 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2632,
    'لَن یَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَاۤؤُهَا وَلَـٰكِن یَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَ ٰ⁠لِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِینَ',
    'لن ينال الله لحومها ولا دماؤها ولكن يناله التقوى منكم كذلك سخرها لكم لتكبروا الله على ما هداكم وبشر المحسنين',
    'ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َنَالَ <rule class=ham_wasl>ٱ</rule>للَّهَ لُحُومُهَا وَلَا دِم<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهَا وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َنَالُهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=qalaqah>قۡ</rule>وَىٰ مِ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ مَا هَدَ<rule class=madda_normal>ٮٰ</rule>كُمۡ‌ۗ وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 17, 4, 336, 289, 134, 'false'
  );
  
  -- Ayah 38 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2633,
    '۞ إِنَّ ٱللَّهَ یُدَ ٰ⁠فِعُ عَنِ ٱلَّذِینَ ءَامَنُوۤا۟ۗ إِنَّ ٱللَّهَ لَا یُحِبُّ كُلَّ خَوَّانࣲ كَفُورٍ',
    'ان الله يدافع عن الذين امنوا ان الله لا يحب كل خوان كفور',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُد<rule class=madda_normal>ٰ</rule>فِعُ عَنِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ كُلَّ خَوَّا<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ك</rule>َف<rule class=madda_permissible>ُو</rule>رٍ ٣٨',
    38, 17, 4, 336, 289, 135, 'false'
  );
  
  -- Ayah 39 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2634,
    'أُذِنَ لِلَّذِینَ یُقَـٰتَلُونَ بِأَنَّهُمۡ ظُلِمُوا۟ۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِیرٌ',
    'اذن للذين يقاتلون بانهم ظلموا وان الله على نصرهم لقدير',
    'أُذِنَ لِلَّذِينَ يُقَ<rule class=madda_normal>ـٰ</rule>تَلُونَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ ظُلِمُو<rule class=slnt>اۡ‌ۚ</rule> وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَد<rule class=madda_permissible>ِي</rule>رٌ ٣٩',
    39, 17, 4, 337, 290, 135, 'false'
  );
  
  -- Ayah 40 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2635,
    'ٱلَّذِینَ أُخۡرِجُوا۟ مِن دِیَـٰرِهِم بِغَیۡرِ حَقٍّ إِلَّاۤ أَن یَقُولُوا۟ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّهُدِّمَتۡ صَوَ ٰ⁠مِعُ وَبِیَعࣱ وَصَلَوَ ٰ⁠تࣱ وَمَسَـٰجِدُ یُذۡكَرُ فِیهَا ٱسۡمُ ٱللَّهِ كَثِیرࣰاۗ وَلَیَنصُرَنَّ ٱللَّهُ مَن یَنصُرُهُۥۤۚ إِنَّ ٱللَّهَ لَقَوِیٌّ عَزِیزٌ',
    'الذين اخرجوا من ديارهم بغير حق الا ان يقولوا ربنا الله ولولا دفع الله الناس بعضهم ببعض لهدمت صوامع وبيع وصلوات ومساجد يذكر فيها اسم الله كثيرا ولينصرن الله من ينصره ان الله لقوي عزيز',
    'ٱلَّذِينَ أُخۡرِجُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِغَيۡرِ حَقٍّ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُو<rule class=slnt>اۡ</rule> رَبُّنَا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ وَلَوۡلَا دَفۡعُ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ بَعۡضَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَعۡ<rule class=idgham_wo_ghunnah>ضٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُدِّمَتۡ صَو<rule class=madda_normal>ٰ</rule>مِعُ وَبِيَ<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>و</rule>َصَلَو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَسَ<rule class=madda_normal>ـٰ</rule>جِدُ يُذۡكَرُ فِيهَا <rule class=ham_wasl>ٱ</rule>سۡمُ <rule class=ham_wasl>ٱ</rule>للَّهِ كَثِي<rule class=idgham_ghunnah>رًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َلَيَ<rule class=ikhafa>نص</rule>ُرَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَقَوِىٌّ عَز<rule class=madda_permissible>ِي</rule>زٌ ٤٠',
    40, 17, 4, 337, 290, 135, 'false'
  );
  
  -- Ayah 41 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2636,
    'ٱلَّذِینَ إِن مَّكَّنَّـٰهُمۡ فِی ٱلۡأَرۡضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلۡمَعۡرُوفِ وَنَهَوۡا۟ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَـٰقِبَةُ ٱلۡأُمُورِ',
    'الذين ان مكناهم في الارض اقاموا الصلاة واتوا الزكاة وامروا بالمعروف ونهوا عن المنكر ولله عاقبة الامور',
    'ٱلَّذِينَ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّكَّ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَمَرُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَنَهَوۡ<rule class=slnt>اۡ</rule> عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ‌ۗ وَلِلَّهِ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رِ ٤١',
    41, 17, 4, 337, 290, 135, 'false'
  );
  
  -- Ayah 42 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2637,
    'وَإِن یُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَثَمُودُ',
    'وان يكذبوك فقد كذبت قبلهم قوم نوح وعاد وثمود',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَذِّبُوكَ فَقَ<rule class=qalaqah>دۡ</rule> كَذَّبَتۡ قَ<rule class=qalaqah>بۡ</rule>لَهُمۡ قَوۡمُ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَا<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َثَم<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ُ ٤٢',
    42, 17, 4, 337, 290, 135, 'false'
  );
  
  -- Ayah 43 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2638,
    'وَقَوۡمُ إِبۡرَ ٰ⁠هِیمَ وَقَوۡمُ لُوطࣲ',
    'وقوم ابراهيم وقوم لوط',
    'وَقَوۡمُ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَقَوۡمُ ل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ط</rule>ٍ ٤٣',
    43, 17, 4, 337, 290, 135, 'false'
  );
  
  -- Ayah 44 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2639,
    'وَأَصۡحَـٰبُ مَدۡیَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَیۡتُ لِلۡكَـٰفِرِینَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَیۡفَ كَانَ نَكِیرِ',
    'واصحاب مدين وكذب موسى فامليت للكافرين ثم اخذتهم فكيف كان نكير',
    'وَأَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ مَ<rule class=qalaqah>دۡ</rule>يَنَ‌ۖ وَكُذِّبَ مُوسَىٰ فَأَمۡلَيۡتُ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ ثُ<rule class=ghunnah>مّ</rule>َ أَخَذۡتُهُمۡ‌ۖ فَكَيۡفَ كَانَ نَك<rule class=madda_permissible>ِي</rule>رِ ٤٤',
    44, 17, 4, 337, 290, 135, 'false'
  );
  
  -- Ayah 45 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2640,
    'فَكَأَیِّن مِّن قَرۡیَةٍ أَهۡلَكۡنَـٰهَا وَهِیَ ظَالِمَةࣱ فَهِیَ خَاوِیَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرࣲ مُّعَطَّلَةࣲ وَقَصۡرࣲ مَّشِیدٍ',
    'فكاين من قرية اهلكناها وهي ظالمة فهي خاوية على عروشها وبئر معطلة وقصر مشيد',
    'فَكَأَيّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ أَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>هَا وَهِىَ ظَالِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّعَطَّلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َقَصۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>َّش<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٤٥',
    45, 17, 4, 337, 290, 135, 'false'
  );
  
  -- Ayah 46 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2641,
    'أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبࣱ یَعۡقِلُونَ بِهَاۤ أَوۡ ءَاذَانࣱ یَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَـٰرُ وَلَـٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِی فِی ٱلصُّدُورِ',
    'افلم يسيروا في الارض فتكون لهم قلوب يعقلون بها او اذان يسمعون بها فانها لا تعمى الابصار ولكن تعمى القلوب التي في الصدور',
    'أَفَلَمۡ يَسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُو<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِلُونَ بِه<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ ءَاذَا<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡمَعُونَ بِهَا‌ۖ فَإِ<rule class=ghunnah>نّ</rule>َهَا لَا تَعۡمَى <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡمَى <rule class=ham_wasl>ٱ</rule>لۡقُلُوبُ <rule class=ham_wasl>ٱ</rule>لَّتِى فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٤٦',
    46, 17, 4, 337, 290, 135, 'false'
  );
  
  -- Ayah 47 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2642,
    'وَیَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن یُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ یَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةࣲ مِّمَّا تَعُدُّونَ',
    'ويستعجلونك بالعذاب ولن يخلف الله وعده وان يوما عند ربك كالف سنة مما تعدون',
    'وَيَسۡتَعۡجِلُونَكَ بِ<rule class=ham_wasl>ٱ</rule>لۡعَذَابِ وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡلِفَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَعۡدَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ يَوۡمًا عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ كَأَلۡفِ سَنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَعُدّ<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 17, 4, 338, 290, 135, 'false'
  );
  
  -- Ayah 48 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2643,
    'وَكَأَیِّن مِّن قَرۡیَةٍ أَمۡلَیۡتُ لَهَا وَهِیَ ظَالِمَةࣱ ثُمَّ أَخَذۡتُهَا وَإِلَیَّ ٱلۡمَصِیرُ',
    'وكاين من قرية امليت لها وهي ظالمة ثم اخذتها والي المصير',
    'وَكَأَيّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِىَ ظَالِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ أَخَذۡتُهَا وَإِلَىَّ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٤٨',
    48, 17, 4, 338, 290, 135, 'false'
  );
  
  -- Ayah 49 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2644,
    'قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّمَاۤ أَنَا۠ لَكُمۡ نَذِیرࣱ مُّبِینࣱ',
    'قل يا ايها الناس انما انا لكم نذير مبين',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ لَكُمۡ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٤٩',
    49, 17, 4, 338, 291, 135, 'false'
  );
  
  -- Ayah 50 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2645,
    'فَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ',
    'فالذين امنوا وعملوا الصالحات لهم مغفرة ورزق كريم',
    'فَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َرِزۡ<rule class=ikhafa>قٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٥٠',
    50, 17, 4, 338, 291, 135, 'false'
  );
  
  -- Ayah 51 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2646,
    'وَٱلَّذِینَ سَعَوۡا۟ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ',
    'والذين سعوا في اياتنا معاجزين اولئك اصحاب الجحيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ سَعَوۡ<rule class=slnt>اۡ</rule> ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا مُعَ<rule class=madda_normal>ـٰ</rule>جِزِينَ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ٥١',
    51, 17, 4, 338, 291, 135, 'false'
  );
  
  -- Ayah 52 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2647,
    'وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولࣲ وَلَا نَبِیٍّ إِلَّاۤ إِذَا تَمَنَّىٰۤ أَلۡقَى ٱلشَّیۡطَـٰنُ فِیۤ أُمۡنِیَّتِهِۦ فَیَنسَخُ ٱللَّهُ مَا یُلۡقِی ٱلشَّیۡطَـٰنُ ثُمَّ یُحۡكِمُ ٱللَّهُ ءَایَـٰتِهِۦۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'وما ارسلنا من قبلك من رسول ولا نبي الا اذا تمنى القى الشيطان في امنيته فينسخ الله ما يلقي الشيطان ثم يحكم الله اياته والله عليم حكيم',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُو<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَبِىٍّ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا تَمَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَلۡقَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُمۡنِيَّتِه<rule class=madda_normal>ِۦ</rule> فَيَ<rule class=ikhafa>نس</rule>َخُ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا يُلۡقِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ ثُ<rule class=ghunnah>مّ</rule>َ يُحۡكِمُ <rule class=ham_wasl>ٱ</rule>للَّهُ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٥٢',
    52, 17, 4, 338, 291, 135, 'false'
  );
  
  -- Ayah 53 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2648,
    'لِّیَجۡعَلَ مَا یُلۡقِی ٱلشَّیۡطَـٰنُ فِتۡنَةࣰ لِّلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ وَٱلۡقَاسِیَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِینَ لَفِی شِقَاقِۭ بَعِیدࣲ',
    'ليجعل ما يلقي الشيطان فتنة للذين في قلوبهم مرض والقاسية قلوبهم وان الظالمين لفي شقاق بعيد',
    'لِّيَ<rule class=qalaqah>جۡ</rule>عَلَ مَا يُلۡقِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ فِتۡنَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡقَاسِيَةِ قُلُوبُهُمۡ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ لَفِى شِقَا<rule class=iqlab>قِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٥٣',
    53, 17, 4, 338, 291, 135, 'false'
  );
  
  -- Ayah 54 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2649,
    'وَلِیَعۡلَمَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَیُؤۡمِنُوا۟ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِینَ ءَامَنُوۤا۟ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'وليعلم الذين اوتوا العلم انه الحق من ربك فيؤمنوا به فتخبت له قلوبهم وان الله لهاد الذين امنوا الى صراط مستقيم',
    'وَلِيَعۡلَمَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ أَ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ فَيُؤۡمِنُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> فَتُخۡبِتَ لَهُ<rule class=madda_normal>ۥ</rule> قُلُوبُهُمۡ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَهَادِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٥٤',
    54, 17, 4, 338, 291, 135, 'false'
  );
  
  -- Ayah 55 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2650,
    'وَلَا یَزَالُ ٱلَّذِینَ كَفَرُوا۟ فِی مِرۡیَةࣲ مِّنۡهُ حَتَّىٰ تَأۡتِیَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ یَأۡتِیَهُمۡ عَذَابُ یَوۡمٍ عَقِیمٍ',
    'ولا يزال الذين كفروا في مرية منه حتى تاتيهم الساعة بغتة او ياتيهم عذاب يوم عقيم',
    'وَلَا يَزَالُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فِى مِرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَق<rule class=madda_permissible>ِي</rule>مٍ ٥٥',
    55, 17, 4, 338, 291, 135, 'false'
  );
  
  -- Ayah 56 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2651,
    'ٱلۡمُلۡكُ یَوۡمَىِٕذࣲ لِّلَّهِ یَحۡكُمُ بَیۡنَهُمۡۚ فَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فِی جَنَّـٰتِ ٱلنَّعِیمِ',
    'الملك يومئذ لله يحكم بينهم فالذين امنوا وعملوا الصالحات في جنات النعيم',
    'ٱلۡمُلۡكُ يَوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َع<rule class=madda_permissible>ِي</rule>مِ ٥٦',
    56, 17, 4, 339, 291, 135, 'false'
  );
  
  -- Ayah 57 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2652,
    'وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَا فَأُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مُّهِینࣱ',
    'والذين كفروا وكذبوا باياتنا فاولئك لهم عذاب مهين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَكَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّه<rule class=madda_permissible>ِي</rule>نٌ ٥٧',
    57, 17, 4, 339, 291, 135, 'false'
  );
  
  -- Ayah 58 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2653,
    'وَٱلَّذِینَ هَاجَرُوا۟ فِی سَبِیلِ ٱللَّهِ ثُمَّ قُتِلُوۤا۟ أَوۡ مَاتُوا۟ لَیَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنࣰاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ',
    'والذين هاجروا في سبيل الله ثم قتلوا او ماتوا ليرزقنهم الله رزقا حسنا وان الله لهو خير الرازقين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هَاجَرُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ قُتِل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡ مَاتُو<rule class=slnt>اۡ</rule> لَيَرۡزُقَ<rule class=ghunnah>نّ</rule>َهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رِزۡقًا حَسَ<rule class=idgham_ghunnah>نًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَهُوَ خَيۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>زِق<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 17, 4, 339, 292, 135, 'false'
  );
  
  -- Ayah 59 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2654,
    'لَیُدۡخِلَنَّهُم مُّدۡخَلࣰا یَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِیمٌ حَلِیمࣱ',
    'ليدخلنهم مدخلا يرضونه وان الله لعليم حليم',
    'لَيُ<rule class=qalaqah>دۡ</rule>خِلَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>دۡ</rule>خَل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ي</rule>َرۡضَوۡنَهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَلِيمٌ حَل<rule class=madda_permissible>ِي</rule>مٌ ٥٩',
    59, 17, 4, 339, 292, 135, 'false'
  );
  
  -- Ayah 60 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2655,
    '۞ ذَ ٰ⁠لِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِیَ عَلَیۡهِ لَیَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ',
    'ذلك ومن عاقب بمثل ما عوقب به ثم بغي عليه لينصرنه الله ان الله لعفو غفور',
    '۞ذ<rule class=madda_normal>ٰ</rule>لِكَ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِه<rule class=madda_normal>ِۦ</rule> ثُ<rule class=ghunnah>مّ</rule>َ بُغِىَ عَلَيۡهِ لَيَ<rule class=ikhafa>نص</rule>ُرَ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَفُوٌّ غَف<rule class=madda_permissible>ُو</rule>رٌ ٦٠',
    60, 17, 4, 339, 292, 136, 'false'
  );
  
  -- Ayah 61 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2656,
    'ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَأَنَّ ٱللَّهَ سَمِیعُۢ بَصِیرࣱ',
    'ذلك بان الله يولج الليل في النهار ويولج النهار في الليل وان الله سميع بصير',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُولِجُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَيُولِجُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ فِى <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِي<rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>َص<rule class=madda_permissible>ِي</rule>رٌ ٦١',
    61, 17, 4, 339, 292, 136, 'false'
  );
  
  -- Ayah 62 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2657,
    'ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا یَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ',
    'ذلك بان الله هو الحق وان ما يدعون من دونه هو الباطل وان الله هو العلي الكبير',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَأَ<rule class=ghunnah>نّ</rule>َ مَا يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلُ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِىُّ <rule class=ham_wasl>ٱ</rule>لۡكَب<rule class=madda_permissible>ِي</rule>رُ ٦٢',
    62, 17, 4, 339, 292, 136, 'false'
  );
  
  -- Ayah 63 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2658,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِیفٌ خَبِیرࣱ',
    'الم تر ان الله انزل من السماء ماء فتصبح الارض مخضرة ان الله لطيف خبير',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ أَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َتُصۡبِحُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ مُخۡضَرَّةً‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَطِيفٌ خَب<rule class=madda_permissible>ِي</rule>رٌ ٦٣',
    63, 17, 4, 339, 292, 136, 'false'
  );
  
  -- Ayah 64 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2659,
    'لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ',
    'له ما في السماوات وما في الارض وان الله لهو الغني الحميد',
    'لَّهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡغَنِىُّ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٦٤',
    64, 17, 4, 339, 292, 136, 'false'
  );
  
  -- Ayah 65 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2660,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِی ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِی فِی ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَیُمۡسِكُ ٱلسَّمَاۤءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦۤۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفࣱ رَّحِیمࣱ',
    'الم تر ان الله سخر لكم ما في الارض والفلك تجري في البحر بامره ويمسك السماء ان تقع على الارض الا باذنه ان الله بالناس لرءوف رحيم',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَخَّرَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ تَ<rule class=qalaqah>جۡ</rule>رِى فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ بِأَمۡرِه<rule class=madda_normal>ِۦ</rule> وَيُمۡسِكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقَعَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِلَّا بِإِذۡنِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَرَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٦٥',
    65, 17, 4, 340, 293, 136, 'false'
  );
  
  -- Ayah 66 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2661,
    'وَهُوَ ٱلَّذِیۤ أَحۡیَاكُمۡ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡۗ إِنَّ ٱلۡإِنسَـٰنَ لَكَفُورࣱ',
    'وهو الذي احياكم ثم يميتكم ثم يحييكم ان الانسان لكفور',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡيَاكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يُمِيتُكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يُحۡيِيكُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ لَكَف<rule class=madda_permissible>ُو</rule>رٌ ٦٦',
    66, 17, 4, 340, 293, 136, 'false'
  );
  
  -- Ayah 67 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2662,
    'لِّكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا یُنَـٰزِعُنَّكَ فِی ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدࣰى مُّسۡتَقِیمࣲ',
    'لكل امة جعلنا منسكا هم ناسكوه فلا ينازعنك في الامر وادع الى ربك انك لعلى هدى مستقيم',
    'لِّكُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ج</rule>َعَلۡنَا مَ<rule class=ikhafa>نس</rule>َكًا هُمۡ نَاسِكُوهُ‌ۖ فَلَا يُنَ<rule class=madda_normal>ـٰ</rule>زِعُ<rule class=ghunnah>نّ</rule>َكَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ إِلَىٰ رَبِّكَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ لَعَلَىٰ هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٦٧',
    67, 17, 4, 340, 293, 136, 'false'
  );
  
  -- Ayah 68 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2663,
    'وَإِن جَـٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ',
    'وان جادلوك فقل الله اعلم بما تعملون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َ<rule class=madda_normal>ـٰ</rule>دَلُوكَ فَقُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 17, 4, 340, 293, 136, 'false'
  );
  
  -- Ayah 69 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2664,
    'ٱللَّهُ یَحۡكُمُ بَیۡنَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ',
    'الله يحكم بينكم يوم القيامة فيما كنتم فيه تختلفون',
    'ٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فِيمَا كُ<rule class=ikhafa>نت</rule>ُمۡ فِيهِ تَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 17, 4, 340, 293, 136, 'false'
  );
  
  -- Ayah 70 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2665,
    'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِی ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ إِنَّ ذَ ٰ⁠لِكَ فِی كِتَـٰبٍۚ إِنَّ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ',
    'الم تعلم ان الله يعلم ما في السماء والارض ان ذلك في كتاب ان ذلك على الله يسير',
    'أَلَمۡ تَعۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ فِى كِتَ<rule class=madda_normal>ـٰ</rule>بٍ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَس<rule class=madda_permissible>ِي</rule>رٌ ٧٠',
    70, 17, 4, 340, 293, 136, 'false'
  );
  
  -- Ayah 71 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2666,
    'وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ سُلۡطَـٰنࣰا وَمَا لَیۡسَ لَهُم بِهِۦ عِلۡمࣱۗ وَمَا لِلظَّـٰلِمِینَ مِن نَّصِیرࣲ',
    'ويعبدون من دون الله ما لم ينزل به سلطانا وما ليس لهم به علم وما للظالمين من نصير',
    'وَيَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَمۡ يُنَزِّلۡ بِه<rule class=madda_normal>ِۦ</rule> سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َمَا لَيۡسَ لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> عِلۡ<rule class=idgham_ghunnah>مٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َمَا لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّص<rule class=madda_permissible>ِي</rule>رٍ ٧١',
    71, 17, 4, 340, 293, 136, 'false'
  );
  
  -- Ayah 72 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2667,
    'وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ تَعۡرِفُ فِی وُجُوهِ ٱلَّذِینَ كَفَرُوا۟ ٱلۡمُنكَرَۖ یَكَادُونَ یَسۡطُونَ بِٱلَّذِینَ یَتۡلُونَ عَلَیۡهِمۡ ءَایَـٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرࣲّ مِّن ذَ ٰ⁠لِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِینَ كَفَرُوا۟ۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'واذا تتلى عليهم اياتنا بينات تعرف في وجوه الذين كفروا المنكر يكادون يسطون بالذين يتلون عليهم اياتنا قل افانبئكم بشر من ذلكم النار وعدها الله الذين كفروا وبئس المصير',
    'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا بَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َعۡرِفُ فِى وُجُوهِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرَ‌ۖ يَكَادُونَ يَسۡطُونَ بِ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا‌ۗ قُلۡ أَفَأُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِشَ<rule class=idgham_ghunnah>رٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكُمُ‌ۗ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ وَعَدَهَا <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ‌ۖ</rule> وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٧٢',
    72, 17, 4, 340, 293, 136, 'false'
  );
  
  -- Ayah 73 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2668,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ ضُرِبَ مَثَلࣱ فَٱسۡتَمِعُوا۟ لَهُۥۤۚ إِنَّ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن یَخۡلُقُوا۟ ذُبَابࣰا وَلَوِ ٱجۡتَمَعُوا۟ لَهُۥۖ وَإِن یَسۡلُبۡهُمُ ٱلذُّبَابُ شَیۡـࣰٔا لَّا یَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ',
    'يا ايها الناس ضرب مثل فاستمعوا له ان الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له وان يسلبهم الذباب شيئا لا يستنقذوه منه ضعف الطالب والمطلوب',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ ضُرِبَ مَثَ<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَمِعُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡلُقُو<rule class=slnt>اۡ</rule> ذُبَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َلَوِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَمَعُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡلُ<rule class=qalaqah>بۡ</rule>هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذُّبَابُ شَيۡـ<rule class=idgham_wo_ghunnah>ـًٔا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَسۡتَ<rule class=ikhafa>نق</rule>ِذُوهُ مِنۡهُ‌ۚ ضَعُفَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّالِبُ وَ<rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=qalaqah>طۡ</rule>ل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ُ ٧٣',
    73, 17, 4, 341, 294, 136, 'false'
  );
  
  -- Ayah 74 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2669,
    'مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدۡرِهِۦۤۚ إِنَّ ٱللَّهَ لَقَوِیٌّ عَزِیزٌ',
    'ما قدروا الله حق قدره ان الله لقوي عزيز',
    'مَا قَدَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ حَقَّ قَ<rule class=qalaqah>دۡ</rule>رِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَقَوِىٌّ عَز<rule class=madda_permissible>ِي</rule>زٌ ٧٤',
    74, 17, 4, 341, 294, 136, 'false'
  );
  
  -- Ayah 75 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2670,
    'ٱللَّهُ یَصۡطَفِی مِنَ ٱلۡمَلَـٰۤىِٕكَةِ رُسُلࣰا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرࣱ',
    'الله يصطفي من الملائكة رسلا ومن الناس ان الله سميع بصير',
    'ٱللَّهُ يَصۡطَفِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ رُسُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِي<rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>َص<rule class=madda_permissible>ِي</rule>رٌ ٧٥',
    75, 17, 4, 341, 294, 136, 'false'
  );
  
  -- Ayah 76 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2671,
    'یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ',
    'يعلم ما بين ايديهم وما خلفهم والى الله ترجع الامور',
    'يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ‌ۗ وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تُرۡجَعُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رُ ٧٦',
    76, 17, 4, 341, 294, 136, 'false'
  );
  
  -- Ayah 77 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2672,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱرۡكَعُوا۟ وَٱسۡجُدُوا۟ وَٱعۡبُدُوا۟ رَبَّكُمۡ وَٱفۡعَلُوا۟ ٱلۡخَیۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ ۩',
    'يا ايها الذين امنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>رۡكَعُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ وَ<rule class=ham_wasl>ٱ</rule>فۡعَلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُ<rule class=madda_permissible>و</rule>نَ ۩ ٧٧',
    77, 17, 4, 341, 294, 136, '{"id":7,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 78 Surah Al-Hajj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    22,
    2673,
    'وَجَـٰهِدُوا۟ فِی ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَیۡكُمۡ فِی ٱلدِّینِ مِنۡ حَرَجࣲۚ مِّلَّةَ أَبِیكُمۡ إِبۡرَ ٰ⁠هِیمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِینَ مِن قَبۡلُ وَفِی هَـٰذَا لِیَكُونَ ٱلرَّسُولُ شَهِیدًا عَلَیۡكُمۡ وَتَكُونُوا۟ شُهَدَاۤءَ عَلَى ٱلنَّاسِۚ فَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعۡتَصِمُوا۟ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِیرُ',
    'وجاهدوا في الله حق جهاده هو اجتباكم وما جعل عليكم في الدين من حرج ملة ابيكم ابراهيم هو سماكم المسلمين من قبل وفي هذا ليكون الرسول شهيدا عليكم وتكونوا شهداء على الناس فاقيموا الصلاة واتوا الزكاة واعتصموا بالله هو مولاكم فنعم المولى ونعم النصير',
    'وَجَ<rule class=madda_normal>ـٰ</rule>هِدُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>للَّهِ حَقَّ جِهَادِه<rule class=madda_normal>ِۦ</rule>‌ۚ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَبَ<rule class=madda_normal>ـٰ</rule>كُمۡ وَمَا جَعَلَ عَلَيۡكُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ مِنۡ حَرَ<rule class=idgham_ghunnah>جٍ‌ۚ</rule> <rule class=idgham_ghunnah>م</rule>ِّلَّةَ أَبِيكُمۡ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ‌ۚ هُوَ سَ<rule class=ghunnah>مّ</rule>َ<rule class=madda_normal>ـٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِمِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَفِى هَ<rule class=madda_normal>ـٰ</rule>ذَا لِيَكُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُو<rule class=slnt>اۡ</rule> شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ‌ۚ فَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَ<rule class=ham_wasl>ٱ</rule>عۡتَصِمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ هُوَ مَوۡلَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ فَنِعۡمَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡلَىٰ وَنِعۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َص<rule class=madda_permissible>ِي</rule>رُ ٧٨',
    78, 17, 4, 341, 294, 136, 'false'
  );
  

-- Surah Al-Muminoon
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (23, 'سُورَةُ المُؤۡمِنُونَ', 'Al-Muminoon', 'The Believers', 'Meccan', 118);

  -- Ayah 1 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2674,
    'قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ',
    'قد افلح المؤمنون',
    'قَ<rule class=qalaqah>دۡ</rule> أَفۡلَحَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 2 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2675,
    'ٱلَّذِینَ هُمۡ فِی صَلَاتِهِمۡ خَـٰشِعُونَ',
    'الذين هم في صلاتهم خاشعون',
    'ٱلَّذِينَ هُمۡ فِى صَلَاتِهِمۡ خَ<rule class=madda_normal>ـٰ</rule>شِع<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 3 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2676,
    'وَٱلَّذِینَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ',
    'والذين هم عن اللغو معرضون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّغۡوِ مُعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 4 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2677,
    'وَٱلَّذِینَ هُمۡ لِلزَّكَوٰةِ فَـٰعِلُونَ',
    'والذين هم للزكاة فاعلون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ لِلزَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ فَ<rule class=madda_normal>ـٰ</rule>عِل<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 5 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2678,
    'وَٱلَّذِینَ هُمۡ لِفُرُوجِهِمۡ حَـٰفِظُونَ',
    'والذين هم لفروجهم حافظون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 6 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2679,
    'إِلَّا عَلَىٰۤ أَزۡوَ ٰ⁠جِهِمۡ أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ فَإِنَّهُمۡ غَیۡرُ مَلُومِینَ',
    'الا على ازواجهم او ما ملكت ايمانهم فانهم غير ملومين',
    'إِلَّا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule>جِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُهُمۡ فَإِ<rule class=ghunnah>نّ</rule>َهُمۡ غَيۡرُ مَلُوم<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 7 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2680,
    'فَمَنِ ٱبۡتَغَىٰ وَرَاۤءَ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡعَادُونَ',
    'فمن ابتغى وراء ذلك فاولئك هم العادون',
    'فَمَنِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغَىٰ وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡعَاد<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 8 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2681,
    'وَٱلَّذِینَ هُمۡ لِأَمَـٰنَـٰتِهِمۡ وَعَهۡدِهِمۡ رَ ٰ⁠عُونَ',
    'والذين هم لاماناتهم وعهدهم راعون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ لِأَمَ<rule class=madda_normal>ـٰ</rule>نَ<rule class=madda_normal>ـٰ</rule>تِهِمۡ وَعَهۡدِهِمۡ ر<rule class=madda_normal>ٰ</rule>ع<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 9 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2682,
    'وَٱلَّذِینَ هُمۡ عَلَىٰ صَلَوَ ٰ⁠تِهِمۡ یُحَافِظُونَ',
    'والذين هم على صلواتهم يحافظون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ عَلَىٰ صَلَو<rule class=madda_normal>ٰ</rule>تِهِمۡ يُحَافِظ<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 10 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2683,
    'أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡوَ ٰ⁠رِثُونَ',
    'اولئك هم الوارثون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>رِث<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 11 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2684,
    'ٱلَّذِینَ یَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِیهَا خَـٰلِدُونَ',
    'الذين يرثون الفردوس هم فيها خالدون',
    'ٱلَّذِينَ يَرِثُونَ <rule class=ham_wasl>ٱ</rule>لۡفِرۡدَوۡسَ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 12 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2685,
    'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ مِن سُلَـٰلَةࣲ مِّن طِینࣲ',
    'ولقد خلقنا الانسان من سلالة من طين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule><rule class=madda_permissible>ِي</rule>نٍ ١٢',
    12, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 13 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2686,
    'ثُمَّ جَعَلۡنَـٰهُ نُطۡفَةࣰ فِی قَرَارࣲ مَّكِینࣲ',
    'ثم جعلناه نطفة في قرار مكين',
    'ثُ<rule class=ghunnah>مّ</rule>َ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ نُ<rule class=qalaqah>طۡ</rule>فَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى قَرَا<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>َّك<rule class=madda_permissible>ِي</rule>نٍ ١٣',
    13, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 14 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2687,
    'ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةࣰ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةࣰ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَـٰمࣰا فَكَسَوۡنَا ٱلۡعِظَـٰمَ لَحۡمࣰا ثُمَّ أَنشَأۡنَـٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَـٰلِقِینَ',
    'ثم خلقنا النطفة علقة فخلقنا العلقة مضغة فخلقنا المضغة عظاما فكسونا العظام لحما ثم انشاناه خلقا اخر فتبارك الله احسن الخالقين',
    'ثُ<rule class=ghunnah>مّ</rule>َ خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُ<rule class=qalaqah>طۡ</rule>فَةَ عَلَقَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َخَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡعَلَقَةَ مُضۡغَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َخَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡمُضۡغَةَ عِظَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َكَسَوۡنَا <rule class=ham_wasl>ٱ</rule>لۡعِظَ<rule class=madda_normal>ـٰ</rule>مَ لَحۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=ikhafa>نش</rule>َأۡنَ<rule class=madda_normal>ـٰ</rule>هُ خَلۡقًا ءَاخَرَ‌ۚ فَتَبَارَكَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَحۡسَنُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>لِق<rule class=madda_permissible>ِي</rule>نَ ١٤',
    14, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 15 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2688,
    'ثُمَّ إِنَّكُم بَعۡدَ ذَ ٰ⁠لِكَ لَمَیِّتُونَ',
    'ثم انكم بعد ذلك لميتون',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ لَمَيِّت<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 16 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2689,
    'ثُمَّ إِنَّكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ تُبۡعَثُونَ',
    'ثم انكم يوم القيامة تبعثون',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َكُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ تُ<rule class=qalaqah>بۡ</rule>عَث<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 17 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2690,
    'وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَاۤىِٕقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَـٰفِلِینَ',
    'ولقد خلقنا فوقكم سبع طرائق وما كنا عن الخلق غافلين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>نَا فَوۡقَكُمۡ سَ<rule class=qalaqah>بۡ</rule>عَ طَر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِقَ وَمَا كُ<rule class=ghunnah>نّ</rule>َا عَنِ <rule class=ham_wasl>ٱ</rule>لۡخَلۡقِ غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 18, 4, 342, 295, 137, 'false'
  );
  
  -- Ayah 18 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2691,
    'وَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءَۢ بِقَدَرࣲ فَأَسۡكَنَّـٰهُ فِی ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَـٰدِرُونَ',
    'وانزلنا من السماء ماء بقدر فاسكناه في الارض وانا على ذهاب به لقادرون',
    'وَأَ<rule class=ikhafa>نز</rule>َلۡنَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءَۢ</rule> <rule class=iqlab>ب</rule>ِقَدَ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َأَسۡكَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َا عَلَىٰ ذَهَا<rule class=iqlab>بِۭ</rule> <rule class=iqlab>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> لَقَ<rule class=madda_normal>ـٰ</rule>دِر<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 18, 4, 343, 295, 137, 'false'
  );
  
  -- Ayah 19 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2692,
    'فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّـٰتࣲ مِّن نَّخِیلࣲ وَأَعۡنَـٰبࣲ لَّكُمۡ فِیهَا فَوَ ٰ⁠كِهُ كَثِیرَةࣱ وَمِنۡهَا تَأۡكُلُونَ',
    'فانشانا لكم به جنات من نخيل واعناب لكم فيها فواكه كثيرة ومنها تاكلون',
    'فَأَ<rule class=ikhafa>نش</rule>َأۡنَا لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّخِي<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَعۡنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>بٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ فِيهَا فَو<rule class=madda_normal>ٰ</rule>كِهُ كَثِيرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َمِنۡهَا تَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 18, 4, 343, 295, 137, 'false'
  );
  
  -- Ayah 20 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2693,
    'وَشَجَرَةࣰ تَخۡرُجُ مِن طُورِ سَیۡنَاۤءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغࣲ لِّلۡـَٔاكِلِینَ',
    'وشجرة تخرج من طور سيناء تنبت بالدهن وصبغ للاكلين',
    'وَشَجَرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َخۡرُجُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>ُورِ سَيۡن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ تَ<rule class=iqlab>نۢب</rule>ُتُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّهۡنِ وَصِ<rule class=qalaqah>بۡ</rule><rule class=idgham_wo_ghunnah>غٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡأَكِل<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 18, 4, 343, 295, 137, 'false'
  );
  
  -- Ayah 21 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2694,
    'وَإِنَّ لَكُمۡ فِی ٱلۡأَنۡعَـٰمِ لَعِبۡرَةࣰۖ نُّسۡقِیكُم مِّمَّا فِی بُطُونِهَا وَلَكُمۡ فِیهَا مَنَـٰفِعُ كَثِیرَةࣱ وَمِنۡهَا تَأۡكُلُونَ',
    'وان لكم في الانعام لعبرة نسقيكم مما في بطونها ولكم فيها منافع كثيرة ومنها تاكلون',
    'وَإِ<rule class=ghunnah>نّ</rule>َ لَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ لَعِ<rule class=qalaqah>بۡ</rule>رَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>ن</rule>ُّسۡقِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا فِى بُطُونِهَا وَلَكُمۡ فِيهَا مَنَ<rule class=madda_normal>ـٰ</rule>فِعُ كَثِيرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َمِنۡهَا تَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 18, 4, 343, 295, 137, 'false'
  );
  
  -- Ayah 22 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2695,
    'وَعَلَیۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ',
    'وعليها وعلى الفلك تحملون',
    'وَعَلَيۡهَا وَعَلَى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ تُحۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 18, 4, 343, 295, 137, 'false'
  );
  
  -- Ayah 23 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2696,
    'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤۚ أَفَلَا تَتَّقُونَ',
    'ولقد ارسلنا نوحا الى قومه فقال يا قوم اعبدوا الله ما لكم من اله غيره افلا تتقون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule> فَقَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> أَفَلَا تَتَّق<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 18, 4, 343, 296, 137, 'false'
  );
  
  -- Ayah 24 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2697,
    'فَقَالَ ٱلۡمَلَؤُا۟ ٱلَّذِینَ كَفَرُوا۟ مِن قَوۡمِهِۦ مَا هَـٰذَاۤ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ یُرِیدُ أَن یَتَفَضَّلَ عَلَیۡكُمۡ وَلَوۡ شَاۤءَ ٱللَّهُ لَأَنزَلَ مَلَـٰۤىِٕكَةࣰ مَّا سَمِعۡنَا بِهَـٰذَا فِیۤ ءَابَاۤىِٕنَا ٱلۡأَوَّلِینَ',
    'فقال الملا الذين كفروا من قومه ما هذا الا بشر مثلكم يريد ان يتفضل عليكم ولو شاء الله لانزل ملائكة ما سمعنا بهذا في ابائنا الاولين',
    'فَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِه<rule class=madda_normal>ِۦ</rule> مَا هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُكُمۡ يُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَأَ<rule class=ikhafa>نز</rule>َلَ مَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>َّا سَمِعۡنَا بِهَ<rule class=madda_normal>ـٰ</rule>ذَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنَا <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 18, 4, 343, 296, 137, 'false'
  );
  
  -- Ayah 25 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2698,
    'إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةࣱ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِینࣲ',
    'ان هو الا رجل به جنة فتربصوا به حتى حين',
    'إِنۡ هُوَ إِلَّا رَجُ<rule class=iqlab>لُۢ</rule> <rule class=iqlab>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> جِ<rule class=ghunnah>نّ</rule>َ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َتَرَبَّصُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> حَتَّىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٢٥',
    25, 18, 4, 343, 296, 137, 'false'
  );
  
  -- Ayah 26 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2699,
    'قَالَ رَبِّ ٱنصُرۡنِی بِمَا كَذَّبُونِ',
    'قال رب انصرني بما كذبون',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نص</rule>ُرۡنِى بِمَا كَذَّب<rule class=madda_permissible>ُو</rule>نِ ٢٦',
    26, 18, 4, 343, 296, 137, 'false'
  );
  
  -- Ayah 27 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2700,
    'فَأَوۡحَیۡنَاۤ إِلَیۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡیُنِنَا وَوَحۡیِنَا فَإِذَا جَاۤءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِیهَا مِن كُلࣲّ زَوۡجَیۡنِ ٱثۡنَیۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَیۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَـٰطِبۡنِی فِی ٱلَّذِینَ ظَلَمُوۤا۟ إِنَّهُم مُّغۡرَقُونَ',
    'فاوحينا اليه ان اصنع الفلك باعيننا ووحينا فاذا جاء امرنا وفار التنور فاسلك فيها من كل زوجين اثنين واهلك الا من سبق عليه القول منهم ولا تخاطبني في الذين ظلموا انهم مغرقون',
    'فَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ أَنِ <rule class=ham_wasl>ٱ</rule>صۡنَعِ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُنَا وَفَارَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=ghunnah>نّ</rule>ُورُ‌ۙ فَ<rule class=ham_wasl>ٱ</rule>سۡلُكۡ فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>ز</rule>َوۡجَيۡنِ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبَقَ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ مِنۡهُمۡ‌ۖ وَلَا تُخَ<rule class=madda_normal>ـٰ</rule>طِ<rule class=qalaqah>بۡ</rule>نِى فِى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَم<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّغۡرَق<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 18, 4, 343, 296, 137, 'false'
  );
  
  -- Ayah 28 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2701,
    'فَإِذَا ٱسۡتَوَیۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'فاذا استويت انت ومن معك على الفلك فقل الحمد لله الذي نجانا من القوم الظالمين',
    'فَإِذَا <rule class=ham_wasl>ٱ</rule>سۡتَوَيۡتَ أَ<rule class=ikhafa>نت</rule>َ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعَكَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ فَقُلِ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى نَجَّ<rule class=madda_normal>ـٰ</rule>نَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٨',
    28, 18, 4, 344, 296, 137, 'false'
  );
  
  -- Ayah 29 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2702,
    'وَقُل رَّبِّ أَنزِلۡنِی مُنزَلࣰا مُّبَارَكࣰا وَأَنتَ خَیۡرُ ٱلۡمُنزِلِینَ',
    'وقل رب انزلني منزلا مباركا وانت خير المنزلين',
    'وَقُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبِّ أَ<rule class=ikhafa>نز</rule>ِلۡنِى مُ<rule class=ikhafa>نز</rule>َل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ُّبَارَ<rule class=idgham_ghunnah>كًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نت</rule>َ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نز</rule>ِل<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 18, 4, 344, 296, 137, 'false'
  );
  
  -- Ayah 30 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2703,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ وَإِن كُنَّا لَمُبۡتَلِینَ',
    'ان في ذلك لايات وان كنا لمبتلين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا لَمُ<rule class=qalaqah>بۡ</rule>تَل<rule class=madda_permissible>ِي</rule>نَ ٣٠',
    30, 18, 4, 344, 296, 137, 'false'
  );
  
  -- Ayah 31 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2704,
    'ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِینَ',
    'ثم انشانا من بعدهم قرنا اخرين',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=ikhafa>نش</rule>َأۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ قَرۡنًا ءَاخَر<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 18, 4, 344, 296, 137, 'false'
  );
  
  -- Ayah 32 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2705,
    'فَأَرۡسَلۡنَا فِیهِمۡ رَسُولࣰا مِّنۡهُمۡ أَنِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤۚ أَفَلَا تَتَّقُونَ',
    'فارسلنا فيهم رسولا منهم ان اعبدوا الله ما لكم من اله غيره افلا تتقون',
    'فَأَرۡسَلۡنَا فِيهِمۡ رَسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ أَنِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> أَفَلَا تَتَّق<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 18, 4, 344, 296, 137, 'false'
  );
  
  -- Ayah 33 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2706,
    'وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَاۤءِ ٱلۡـَٔاخِرَةِ وَأَتۡرَفۡنَـٰهُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا مَا هَـٰذَاۤ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ یَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَیَشۡرَبُ مِمَّا تَشۡرَبُونَ',
    'وقال الملا من قومه الذين كفروا وكذبوا بلقاء الاخرة واترفناهم في الحياة الدنيا ما هذا الا بشر مثلكم ياكل مما تاكلون منه ويشرب مما تشربون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِهِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَكَذَّبُو<rule class=slnt>اۡ</rule> بِلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَأَتۡرَفۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا مَا هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُكُمۡ يَأۡكُلُ مِ<rule class=ghunnah>مّ</rule>َا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِ<rule class=ghunnah>مّ</rule>َا تَشۡرَب<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 18, 4, 344, 297, 137, 'false'
  );
  
  -- Ayah 34 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2707,
    'وَلَىِٕنۡ أَطَعۡتُم بَشَرࣰا مِّثۡلَكُمۡ إِنَّكُمۡ إِذࣰا لَّخَـٰسِرُونَ',
    'ولئن اطعتم بشرا مثلكم انكم اذا لخاسرون',
    'وَلَئِنۡ أَطَعۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َشَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلَكُمۡ إِ<rule class=ghunnah>نّ</rule>َكُمۡ إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 18, 4, 344, 297, 137, 'false'
  );
  
  -- Ayah 35 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2708,
    'أَیَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابࣰا وَعِظَـٰمًا أَنَّكُم مُّخۡرَجُونَ',
    'ايعدكم انكم اذا متم وكنتم ترابا وعظاما انكم مخرجون',
    'أَيَعِدُكُمۡ أَ<rule class=ghunnah>نّ</rule>َكُمۡ إِذَا مِتُّمۡ وَكُ<rule class=ikhafa>نت</rule>ُمۡ تُرَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َعِظَ<rule class=madda_normal>ـٰ</rule>مًا أَ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّخۡرَج<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 18, 4, 344, 297, 137, 'false'
  );
  
  -- Ayah 36 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2709,
    '۞ هَیۡهَاتَ هَیۡهَاتَ لِمَا تُوعَدُونَ',
    'هيهات هيهات لما توعدون',
    '۞هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَد<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 18, 4, 344, 297, 138, 'false'
  );
  
  -- Ayah 37 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2710,
    'إِنۡ هِیَ إِلَّا حَیَاتُنَا ٱلدُّنۡیَا نَمُوتُ وَنَحۡیَا وَمَا نَحۡنُ بِمَبۡعُوثِینَ',
    'ان هي الا حياتنا الدنيا نموت ونحيا وما نحن بمبعوثين',
    'إِنۡ هِىَ إِلَّا حَيَاتُنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَ<rule class=qalaqah>بۡ</rule>عُوث<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 18, 4, 344, 297, 138, 'false'
  );
  
  -- Ayah 38 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2711,
    'إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِینَ',
    'ان هو الا رجل افترى على الله كذبا وما نحن له بمؤمنين',
    'إِنۡ هُوَ إِلَّا رَجُلٌ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َمَا نَحۡنُ لَهُ<rule class=madda_normal>ۥ</rule> بِمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٣٨',
    38, 18, 4, 344, 297, 138, 'false'
  );
  
  -- Ayah 39 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2712,
    'قَالَ رَبِّ ٱنصُرۡنِی بِمَا كَذَّبُونِ',
    'قال رب انصرني بما كذبون',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نص</rule>ُرۡنِى بِمَا كَذَّب<rule class=madda_permissible>ُو</rule>نِ ٣٩',
    39, 18, 4, 344, 297, 138, 'false'
  );
  
  -- Ayah 40 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2713,
    'قَالَ عَمَّا قَلِیلࣲ لَّیُصۡبِحُنَّ نَـٰدِمِینَ',
    'قال عما قليل ليصبحن نادمين',
    'قَالَ عَ<rule class=ghunnah>مّ</rule>َا قَلِي<rule class=idgham_wo_ghunnah>لٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيُصۡبِحُ<rule class=ghunnah>نّ</rule>َ نَ<rule class=madda_normal>ـٰ</rule>دِم<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 18, 4, 344, 297, 138, 'false'
  );
  
  -- Ayah 41 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2714,
    'فَأَخَذَتۡهُمُ ٱلصَّیۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَـٰهُمۡ غُثَاۤءࣰۚ فَبُعۡدࣰا لِّلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'فاخذتهم الصيحة بالحق فجعلناهم غثاء فبعدا للقوم الظالمين',
    'فَأَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡحَةُ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ فَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ غُث<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً‌ۚ</rule> <rule class=ikhafa>ف</rule>َبُعۡ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤١',
    41, 18, 4, 344, 297, 138, 'false'
  );
  
  -- Ayah 42 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2715,
    'ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِینَ',
    'ثم انشانا من بعدهم قرونا اخرين',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَ<rule class=ikhafa>نش</rule>َأۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ قُرُونًا ءَاخَر<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 18, 4, 344, 297, 138, 'false'
  );
  
  -- Ayah 43 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2716,
    'مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا یَسۡتَـٔۡخِرُونَ',
    'ما تسبق من امة اجلها وما يستاخرون',
    'مَا تَسۡبِقُ مِنۡ أُ<rule class=ghunnah>مّ</rule>َةٍ أَجَلَهَا وَمَا يَسۡتَــٔۡخِر<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 18, 4, 345, 297, 138, 'false'
  );
  
  -- Ayah 44 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2717,
    'ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَاۤءَ أُمَّةࣰ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضࣰا وَجَعَلۡنَـٰهُمۡ أَحَادِیثَۚ فَبُعۡدࣰا لِّقَوۡمࣲ لَّا یُؤۡمِنُونَ',
    'ثم ارسلنا رسلنا تترى كل ما جاء امة رسولها كذبوه فاتبعنا بعضهم بعضا وجعلناهم احاديث فبعدا لقوم لا يؤمنون',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَا‌ۖ كُلَّ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولُهَا كَذَّبُوهُ‌ۚ فَأَتۡبَعۡنَا بَعۡضَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡ<rule class=idgham_ghunnah>ضًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ أَحَادِيثَ‌ۚ فَبُعۡ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 18, 4, 345, 297, 138, 'false'
  );
  
  -- Ayah 45 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2718,
    'ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَـٰرُونَ بِـَٔایَـٰتِنَا وَسُلۡطَـٰنࣲ مُّبِینٍ',
    'ثم ارسلنا موسى واخاه هارون باياتنا وسلطان مبين',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَ<rule class=madda_normal>ـٰ</rule>رُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٤٥',
    45, 18, 4, 345, 297, 138, 'false'
  );
  
  -- Ayah 46 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2719,
    'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ فَٱسۡتَكۡبَرُوا۟ وَكَانُوا۟ قَوۡمًا عَالِینَ',
    'الى فرعون وملئه فاستكبروا وكانوا قوما عالين',
    'إِلَىٰ فِرۡعَوۡنَ وَمَلَإِ<rule class=slnt>يۡ</rule>ه<rule class=madda_normal>ِۦ</rule> فَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> وَكَانُو<rule class=slnt>اۡ</rule> قَوۡمًا عَال<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 18, 4, 345, 297, 138, 'false'
  );
  
  -- Ayah 47 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2720,
    'فَقَالُوۤا۟ أَنُؤۡمِنُ لِبَشَرَیۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَـٰبِدُونَ',
    'فقالوا انؤمن لبشرين مثلنا وقومهما لنا عابدون',
    'فَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَ<rule class=madda_normal>ـٰ</rule>بِد<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 18, 4, 345, 297, 138, 'false'
  );
  
  -- Ayah 48 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2721,
    'فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلۡمُهۡلَكِینَ',
    'فكذبوهما فكانوا من المهلكين',
    'فَكَذَّبُوهُمَا فَكَانُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُهۡلَك<rule class=madda_permissible>ِي</rule>نَ ٤٨',
    48, 18, 4, 345, 297, 138, 'false'
  );
  
  -- Ayah 49 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2722,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ لَعَلَّهُمۡ یَهۡتَدُونَ',
    'ولقد اتينا موسى الكتاب لعلهم يهتدون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ لَعَلَّهُمۡ يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 18, 4, 345, 297, 138, 'false'
  );
  
  -- Ayah 50 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2723,
    'وَجَعَلۡنَا ٱبۡنَ مَرۡیَمَ وَأُمَّهُۥۤ ءَایَةࣰ وَءَاوَیۡنَـٰهُمَاۤ إِلَىٰ رَبۡوَةࣲ ذَاتِ قَرَارࣲ وَمَعِینࣲ',
    'وجعلنا ابن مريم وامه اية واويناهما الى ربوة ذات قرار ومعين',
    'وَجَعَلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ مَرۡيَمَ وَأُ<rule class=ghunnah>مّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> ءَايَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َءَاوَيۡنَ<rule class=madda_normal>ـٰ</rule>هُم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ رَ<rule class=qalaqah>بۡ</rule>وَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ذ</rule>َاتِ قَرَا<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَع<rule class=madda_permissible>ِي</rule>نٍ ٥٠',
    50, 18, 4, 345, 297, 138, 'false'
  );
  
  -- Ayah 51 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2724,
    'یَـٰۤأَیُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّیِّبَـٰتِ وَٱعۡمَلُوا۟ صَـٰلِحًاۖ إِنِّی بِمَا تَعۡمَلُونَ عَلِیمࣱ',
    'يا ايها الرسل كلوا من الطيبات واعملوا صالحا اني بما تعملون عليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلُ كُلُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>عۡمَلُو<rule class=slnt>اۡ</rule> صَ<rule class=madda_normal>ـٰ</rule>لِحًا‌ۖ إِ<rule class=ghunnah>نّ</rule>ِى بِمَا تَعۡمَلُونَ عَل<rule class=madda_permissible>ِي</rule>مٌ ٥١',
    51, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 52 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2725,
    'وَإِنَّ هَـٰذِهِۦۤ أُمَّتُكُمۡ أُمَّةࣰ وَ ٰ⁠حِدَةࣰ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ',
    'وان هذه امتكم امة واحدة وانا ربكم فاتقون',
    'وَإِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أُ<rule class=ghunnah>مّ</rule>َتُكُمۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَنَاۡ رَبُّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>تَّق<rule class=madda_permissible>ُو</rule>نِ ٥٢',
    52, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 53 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2726,
    'فَتَقَطَّعُوۤا۟ أَمۡرَهُم بَیۡنَهُمۡ زُبُرࣰاۖ كُلُّ حِزۡبِۭ بِمَا لَدَیۡهِمۡ فَرِحُونَ',
    'فتقطعوا امرهم بينهم زبرا كل حزب بما لديهم فرحون',
    'فَتَقَطَّع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَهُمۡ زُبُ<rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ك</rule>ُلُّ حِزۡ<rule class=iqlab>بِۭ</rule> <rule class=iqlab>ب</rule>ِمَا لَدَيۡهِمۡ فَرِح<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 54 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2727,
    'فَذَرۡهُمۡ فِی غَمۡرَتِهِمۡ حَتَّىٰ حِینٍ',
    'فذرهم في غمرتهم حتى حين',
    'فَذَرۡهُمۡ فِى غَمۡرَتِهِمۡ حَتَّىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٥٤',
    54, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 55 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2728,
    'أَیَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالࣲ وَبَنِینَ',
    'ايحسبون انما نمدهم به من مال وبنين',
    'أَيَحۡسَبُونَ أَ<rule class=ghunnah>نّ</rule>َمَا نُمِدُّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّا<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َبَن<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 56 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2729,
    'نُسَارِعُ لَهُمۡ فِی ٱلۡخَیۡرَ ٰ⁠تِۚ بَل لَّا یَشۡعُرُونَ',
    'نسارع لهم في الخيرات بل لا يشعرون',
    'نُسَارِعُ لَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تِ‌ۚ بَل لَّا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 57 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2730,
    'إِنَّ ٱلَّذِینَ هُم مِّنۡ خَشۡیَةِ رَبِّهِم مُّشۡفِقُونَ',
    'ان الذين هم من خشية ربهم مشفقون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خَشۡيَةِ رَبِّه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّشۡفِق<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 58 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2731,
    'وَٱلَّذِینَ هُم بِـَٔایَـٰتِ رَبِّهِمۡ یُؤۡمِنُونَ',
    'والذين هم بايات ربهم يؤمنون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 59 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2732,
    'وَٱلَّذِینَ هُم بِرَبِّهِمۡ لَا یُشۡرِكُونَ',
    'والذين هم بربهم لا يشركون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرَبِّهِمۡ لَا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 18, 4, 345, 298, 138, 'false'
  );
  
  -- Ayah 60 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2733,
    'وَٱلَّذِینَ یُؤۡتُونَ مَاۤ ءَاتَوا۟ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَ ٰ⁠جِعُونَ',
    'والذين يؤتون ما اتوا وقلوبهم وجلة انهم الى ربهم راجعون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡتُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَو<rule class=slnt>اۡ</rule> وَّقُلُوبُهُمۡ وَجِلَةٌ أَ<rule class=ghunnah>نّ</rule>َهُمۡ إِلَىٰ رَبِّهِمۡ ر<rule class=madda_normal>ٰ</rule>جِع<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 61 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2734,
    'أُو۟لَـٰۤىِٕكَ یُسَـٰرِعُونَ فِی ٱلۡخَیۡرَ ٰ⁠تِ وَهُمۡ لَهَا سَـٰبِقُونَ',
    'اولئك يسارعون في الخيرات وهم لها سابقون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يُسَ<rule class=madda_normal>ـٰ</rule>رِعُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تِ وَهُمۡ لَهَا سَ<rule class=madda_normal>ـٰ</rule>بِق<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 62 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2735,
    'وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَیۡنَا كِتَـٰبࣱ یَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا یُظۡلَمُونَ',
    'ولا نكلف نفسا الا وسعها ولدينا كتاب ينطق بالحق وهم لا يظلمون',
    'وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَا‌ۖ وَلَدَيۡنَا كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نط</rule>ِقُ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 63 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2736,
    'بَلۡ قُلُوبُهُمۡ فِی غَمۡرَةࣲ مِّنۡ هَـٰذَا وَلَهُمۡ أَعۡمَـٰلࣱ مِّن دُونِ ذَ ٰ⁠لِكَ هُمۡ لَهَا عَـٰمِلُونَ',
    'بل قلوبهم في غمرة من هذا ولهم اعمال من دون ذلك هم لها عاملون',
    'بَلۡ قُلُوبُهُمۡ فِى غَمۡرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا وَلَهُمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُمۡ لَهَا عَ<rule class=madda_normal>ـٰ</rule>مِل<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 64 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2737,
    'حَتَّىٰۤ إِذَاۤ أَخَذۡنَا مُتۡرَفِیهِم بِٱلۡعَذَابِ إِذَا هُمۡ یَجۡـَٔرُونَ',
    'حتى اذا اخذنا مترفيهم بالعذاب اذا هم يجارون',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَخَذۡنَا مُتۡرَفِيه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعَذَابِ إِذَا هُمۡ يَ<rule class=qalaqah>جۡ</rule>ــَٔر<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 65 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2738,
    'لَا تَجۡـَٔرُوا۟ ٱلۡیَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ',
    'لا تجاروا اليوم انكم منا لا تنصرون',
    'لَا تَ<rule class=qalaqah>جۡ</rule>ــَٔرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا لَا تُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 66 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2739,
    'قَدۡ كَانَتۡ ءَایَـٰتِی تُتۡلَىٰ عَلَیۡكُمۡ فَكُنتُمۡ عَلَىٰۤ أَعۡقَـٰبِكُمۡ تَنكِصُونَ',
    'قد كانت اياتي تتلى عليكم فكنتم على اعقابكم تنكصون',
    'قَ<rule class=qalaqah>دۡ</rule> كَانَتۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِى تُتۡلَىٰ عَلَيۡكُمۡ فَكُ<rule class=ikhafa>نت</rule>ُمۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَعۡقَ<rule class=madda_normal>ـٰ</rule>بِكُمۡ تَ<rule class=ikhafa>نك</rule>ِص<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 67 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2740,
    'مُسۡتَكۡبِرِینَ بِهِۦ سَـٰمِرࣰا تَهۡجُرُونَ',
    'مستكبرين به سامرا تهجرون',
    'مُسۡتَكۡبِرِينَ بِه<rule class=madda_normal>ِۦ</rule> سَ<rule class=madda_normal>ـٰ</rule>مِ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ت</rule>َهۡجُر<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 68 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2741,
    'أَفَلَمۡ یَدَّبَّرُوا۟ ٱلۡقَوۡلَ أَمۡ جَاۤءَهُم مَّا لَمۡ یَأۡتِ ءَابَاۤءَهُمُ ٱلۡأَوَّلِینَ',
    'افلم يدبروا القول ام جاءهم ما لم يات اباءهم الاولين',
    'أَفَلَمۡ يَدَّبَّرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡقَوۡلَ أَمۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا لَمۡ يَأۡتِ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٦٨',
    68, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 69 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2742,
    'أَمۡ لَمۡ یَعۡرِفُوا۟ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ',
    'ام لم يعرفوا رسولهم فهم له منكرون',
    'أَمۡ لَمۡ يَعۡرِفُو<rule class=slnt>اۡ</rule> رَسُولَهُمۡ فَهُمۡ لَهُ<rule class=madda_normal>ۥ</rule> مُ<rule class=ikhafa>نك</rule>ِر<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 70 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2743,
    'أَمۡ یَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَاۤءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَـٰرِهُونَ',
    'ام يقولون به جنة بل جاءهم بالحق واكثرهم للحق كارهون',
    'أَمۡ يَقُولُونَ بِه<rule class=madda_normal>ِۦ</rule> جِ<rule class=ghunnah>نّ</rule>َ<rule class=iqlab>ةُۢ‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 71 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2744,
    'وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَاۤءَهُمۡ لَفَسَدَتِ ٱلسَّمَـٰوَ ٰ⁠تُ وَٱلۡأَرۡضُ وَمَن فِیهِنَّۚ بَلۡ أَتَیۡنَـٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ',
    'ولو اتبع الحق اهواءهم لفسدت السماوات والارض ومن فيهن بل اتيناهم بذكرهم فهم عن ذكرهم معرضون',
    'وَلَوِ <rule class=ham_wasl>ٱ</rule>تَّبَعَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ لَفَسَدَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِيهِ<rule class=ghunnah>نّ</rule>َ‌ۚ بَلۡ أَتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذِكۡرِهِمۡ فَهُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 72 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2745,
    'أَمۡ تَسۡـَٔلُهُمۡ خَرۡجࣰا فَخَرَاجُ رَبِّكَ خَیۡرࣱۖ وَهُوَ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ',
    'ام تسالهم خرجا فخراج ربك خير وهو خير الرازقين',
    'أَمۡ تَسۡــَٔلُهُمۡ خَرۡ<rule class=ikhafa>جًا</rule> <rule class=ikhafa>ف</rule>َخَرَاجُ رَبِّكَ خَيۡ<rule class=idgham_ghunnah>رٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ خَيۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>زِق<rule class=madda_permissible>ِي</rule>نَ ٧٢',
    72, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 73 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2746,
    'وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'وانك لتدعوهم الى صراط مستقيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َكَ لَتَ<rule class=qalaqah>دۡ</rule>عُوهُمۡ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٧٣',
    73, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 74 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2747,
    'وَإِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ عَنِ ٱلصِّرَ ٰ⁠طِ لَنَـٰكِبُونَ',
    'وان الذين لا يؤمنون بالاخرة عن الصراط لناكبون',
    'وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّر<rule class=madda_normal>ٰ</rule>طِ لَنَ<rule class=madda_normal>ـٰ</rule>كِب<rule class=madda_permissible>ُو</rule>نَ ٧٤',
    74, 18, 4, 346, 298, 138, 'false'
  );
  
  -- Ayah 75 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2748,
    '۞ وَلَوۡ رَحِمۡنَـٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرࣲّ لَّلَجُّوا۟ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ',
    'ولو رحمناهم وكشفنا ما بهم من ضر للجوا في طغيانهم يعمهون',
    '۞وَلَوۡ رَحِمۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَكَشَفۡنَا مَا بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>ُ<rule class=idgham_wo_ghunnah>رٍّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّلَجُّو<rule class=slnt>اۡ</rule> فِى طُغۡيَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ يَعۡمَه<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 18, 4, 347, 298, 139, 'false'
  );
  
  -- Ayah 76 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2749,
    'وَلَقَدۡ أَخَذۡنَـٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُوا۟ لِرَبِّهِمۡ وَمَا یَتَضَرَّعُونَ',
    'ولقد اخذناهم بالعذاب فما استكانوا لربهم وما يتضرعون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَخَذۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعَذَابِ فَمَا <rule class=ham_wasl>ٱ</rule>سۡتَكَانُو<rule class=slnt>اۡ</rule> لِرَبِّهِمۡ وَمَا يَتَضَرَّع<rule class=madda_permissible>ُو</rule>نَ ٧٦',
    76, 18, 4, 347, 298, 139, 'false'
  );
  
  -- Ayah 77 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2750,
    'حَتَّىٰۤ إِذَا فَتَحۡنَا عَلَیۡهِم بَابࣰا ذَا عَذَابࣲ شَدِیدٍ إِذَا هُمۡ فِیهِ مُبۡلِسُونَ',
    'حتى اذا فتحنا عليهم بابا ذا عذاب شديد اذا هم فيه مبلسون',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا فَتَحۡنَا عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>َا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ذ</rule>َا عَذَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ش</rule>َدِيدٍ إِذَا هُمۡ فِيهِ مُ<rule class=qalaqah>بۡ</rule>لِس<rule class=madda_permissible>ُو</rule>نَ ٧٧',
    77, 18, 4, 347, 298, 139, 'false'
  );
  
  -- Ayah 78 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2751,
    'وَهُوَ ٱلَّذِیۤ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ',
    'وهو الذي انشا لكم السمع والابصار والافئدة قليلا ما تشكرون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نش</rule>َأَ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَفۡــِٔدَةَ‌ۚ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 79 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2752,
    'وَهُوَ ٱلَّذِی ذَرَأَكُمۡ فِی ٱلۡأَرۡضِ وَإِلَیۡهِ تُحۡشَرُونَ',
    'وهو الذي ذراكم في الارض واليه تحشرون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى ذَرَأَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَإِلَيۡهِ تُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 80 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2753,
    'وَهُوَ ٱلَّذِی یُحۡیِۦ وَیُمِیتُ وَلَهُ ٱخۡتِلَـٰفُ ٱلَّیۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ',
    'وهو الذي يحيي ويميت وله اختلاف الليل والنهار افلا تعقلون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُ وَلَهُ <rule class=ham_wasl>ٱ</rule>خۡتِلَ<rule class=madda_normal>ـٰ</rule>فُ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ‌ۚ أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 81 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2754,
    'بَلۡ قَالُوا۟ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ',
    'بل قالوا مثل ما قال الاولون',
    'بَلۡ قَالُو<rule class=slnt>اۡ</rule> مِثۡلَ مَا قَالَ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 82 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2755,
    'قَالُوۤا۟ أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَـٰمًا أَءِنَّا لَمَبۡعُوثُونَ',
    'قالوا ااذا متنا وكنا ترابا وعظاما اانا لمبعوثون',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَءِذَا مِتۡنَا وَكُ<rule class=ghunnah>نّ</rule>َا تُرَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َعِظَ<rule class=madda_normal>ـٰ</rule>مًا أَءِ<rule class=ghunnah>نّ</rule>َا لَمَ<rule class=qalaqah>بۡ</rule>عُوث<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 83 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2756,
    'لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَاۤؤُنَا هَـٰذَا مِن قَبۡلُ إِنۡ هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ',
    'لقد وعدنا نحن واباؤنا هذا من قبل ان هذا الا اساطير الاولين',
    'لَقَ<rule class=qalaqah>دۡ</rule> وُعِ<rule class=qalaqah>دۡ</rule>نَا نَحۡنُ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا هَ<rule class=madda_normal>ـٰ</rule>ذَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 84 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2757,
    'قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِیهَاۤ إِن كُنتُمۡ تَعۡلَمُونَ',
    'قل لمن الارض ومن فيها ان كنتم تعلمون',
    'قُل لِّمَنِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِيه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 85 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2758,
    'سَیَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ',
    'سيقولون لله قل افلا تذكرون',
    'سَيَقُولُونَ لِلَّهِ‌ۚ قُلۡ أَفَلَا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٨٥',
    85, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 86 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2759,
    'قُلۡ مَن رَّبُّ ٱلسَّمَـٰوَ ٰ⁠تِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِیمِ',
    'قل من رب السماوات السبع ورب العرش العظيم',
    'قُلۡ م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=qalaqah>بۡ</rule>عِ وَرَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٨٦',
    86, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 87 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2760,
    'سَیَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ',
    'سيقولون لله قل افلا تتقون',
    'سَيَقُولُونَ لِلَّهِ‌ۚ قُلۡ أَفَلَا تَتَّق<rule class=madda_permissible>ُو</rule>نَ ٨٧',
    87, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 88 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2761,
    'قُلۡ مَنۢ بِیَدِهِۦ مَلَكُوتُ كُلِّ شَیۡءࣲ وَهُوَ یُجِیرُ وَلَا یُجَارُ عَلَیۡهِ إِن كُنتُمۡ تَعۡلَمُونَ',
    'قل من بيده ملكوت كل شيء وهو يجير ولا يجار عليه ان كنتم تعلمون',
    'قُلۡ م<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>ِيَدِه<rule class=madda_normal>ِۦ</rule> مَلَكُوتُ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 89 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2762,
    'سَیَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ',
    'سيقولون لله قل فانى تسحرون',
    'سَيَقُولُونَ لِلَّهِ‌ۚ قُلۡ فَأَ<rule class=ghunnah>نّ</rule>َىٰ تُسۡحَر<rule class=madda_permissible>ُو</rule>نَ ٨٩',
    89, 18, 4, 347, 299, 139, 'false'
  );
  
  -- Ayah 90 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2763,
    'بَلۡ أَتَیۡنَـٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَـٰذِبُونَ',
    'بل اتيناهم بالحق وانهم لكاذبون',
    'بَلۡ أَتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ لَكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ٩٠',
    90, 18, 4, 348, 299, 139, 'false'
  );
  
  -- Ayah 91 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2764,
    'مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدࣲ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَـٰهٍۚ إِذࣰا لَّذَهَبَ كُلُّ إِلَـٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲۚ سُبۡحَـٰنَ ٱللَّهِ عَمَّا یَصِفُونَ',
    'ما اتخذ الله من ولد وما كان معه من اله اذا لذهب كل اله بما خلق ولعلا بعضهم على بعض سبحان الله عما يصفون',
    'مَا <rule class=ham_wasl>ٱ</rule>تَّخَذَ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ مَعَهُ<rule class=madda_normal>ۥ</rule> مِنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ‌ۚ إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّذَهَبَ كُلُّ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>هِۭ</rule> <rule class=iqlab>ب</rule>ِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡ<rule class=ikhafa>ضٍ‌ۚ</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَ<rule class=ghunnah>مّ</rule>َا يَصِف<rule class=madda_permissible>ُو</rule>نَ ٩١',
    91, 18, 4, 348, 299, 139, 'false'
  );
  
  -- Ayah 92 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2765,
    'عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ',
    'عالم الغيب والشهادة فتعالى عما يشركون',
    'عَ<rule class=madda_normal>ـٰ</rule>لِمِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ فَتَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٩٢',
    92, 18, 4, 348, 299, 139, 'false'
  );
  
  -- Ayah 93 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2766,
    'قُل رَّبِّ إِمَّا تُرِیَنِّی مَا یُوعَدُونَ',
    'قل رب اما تريني ما يوعدون',
    'قُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبِّ إِ<rule class=ghunnah>مّ</rule>َا تُرِيَ<rule class=ghunnah>نّ</rule>ِى مَا يُوعَد<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 94 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2767,
    'رَبِّ فَلَا تَجۡعَلۡنِی فِی ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'رب فلا تجعلني في القوم الظالمين',
    'رَبِّ فَلَا تَ<rule class=qalaqah>جۡ</rule>عَلۡنِى فِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٩٤',
    94, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 95 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2768,
    'وَإِنَّا عَلَىٰۤ أَن نُّرِیَكَ مَا نَعِدُهُمۡ لَقَـٰدِرُونَ',
    'وانا على ان نريك ما نعدهم لقادرون',
    'وَإِ<rule class=ghunnah>نّ</rule>َا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّرِيَكَ مَا نَعِدُهُمۡ لَقَ<rule class=madda_normal>ـٰ</rule>دِر<rule class=madda_permissible>ُو</rule>نَ ٩٥',
    95, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 96 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2769,
    'ٱدۡفَعۡ بِٱلَّتِی هِیَ أَحۡسَنُ ٱلسَّیِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا یَصِفُونَ',
    'ادفع بالتي هي احسن السيئة نحن اعلم بما يصفون',
    'ٱ<rule class=qalaqah>دۡ</rule>فَعۡ بِ<rule class=ham_wasl>ٱ</rule>لَّتِى هِىَ أَحۡسَنُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةَ‌ۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِف<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 97 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2770,
    'وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَ ٰ⁠تِ ٱلشَّیَـٰطِینِ',
    'وقل رب اعوذ بك من همزات الشياطين',
    'وَقُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَز<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>ط<rule class=madda_permissible>ِي</rule>نِ ٩٧',
    97, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 98 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2771,
    'وَأَعُوذُ بِكَ رَبِّ أَن یَحۡضُرُونِ',
    'واعوذ بك رب ان يحضرون',
    'وَأَعُوذُ بِكَ رَبِّ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َحۡضُر<rule class=madda_permissible>ُو</rule>نِ ٩٨',
    98, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 99 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2772,
    'حَتَّىٰۤ إِذَا جَاۤءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ',
    'حتى اذا جاء احدهم الموت قال رب ارجعون',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَحَدَهُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule>رۡجِع<rule class=madda_permissible>ُو</rule>نِ ٩٩',
    99, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 100 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2773,
    'لَعَلِّیۤ أَعۡمَلُ صَـٰلِحࣰا فِیمَا تَرَكۡتُۚ كَلَّاۤۚ إِنَّهَا كَلِمَةٌ هُوَ قَاۤىِٕلُهَاۖ وَمِن وَرَاۤىِٕهِم بَرۡزَخٌ إِلَىٰ یَوۡمِ یُبۡعَثُونَ',
    'لعلي اعمل صالحا فيما تركت كلا انها كلمة هو قائلها ومن ورائهم برزخ الى يوم يبعثون',
    'لَعَلّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡمَلُ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>ِيمَا تَرَكۡتُ‌ۚ كَلّ<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهَا كَلِمَةٌ هُوَ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِلُهَا‌ۖ وَم<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>َرۡزَخٌ إِلَىٰ يَوۡمِ يُ<rule class=qalaqah>بۡ</rule>عَث<rule class=madda_permissible>ُو</rule>نَ ١٠٠',
    100, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 101 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2774,
    'فَإِذَا نُفِخَ فِی ٱلصُّورِ فَلَاۤ أَنسَابَ بَیۡنَهُمۡ یَوۡمَىِٕذࣲ وَلَا یَتَسَاۤءَلُونَ',
    'فاذا نفخ في الصور فلا انساب بينهم يومئذ ولا يتساءلون',
    'فَإِذَا نُفِخَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ فَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نس</rule>َابَ بَيۡنَهُمۡ يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَتَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَل<rule class=madda_permissible>ُو</rule>نَ ١٠١',
    101, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 102 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2775,
    'فَمَن ثَقُلَتۡ مَوَ ٰ⁠زِینُهُۥ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'فمن ثقلت موازينه فاولئك هم المفلحون',
    'فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َقُلَتۡ مَو<rule class=madda_normal>ٰ</rule>زِينُهُ<rule class=madda_normal>ۥ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٠٢',
    102, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 103 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2776,
    'وَمَنۡ خَفَّتۡ مَوَ ٰ⁠زِینُهُۥ فَأُو۟لَـٰۤىِٕكَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ فِی جَهَنَّمَ خَـٰلِدُونَ',
    'ومن خفت موازينه فاولئك الذين خسروا انفسهم في جهنم خالدون',
    'وَمَنۡ خَفَّتۡ مَو<rule class=madda_normal>ٰ</rule>زِينُهُ<rule class=madda_normal>ۥ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَسِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ فِى جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ١٠٣',
    103, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 104 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2777,
    'تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِیهَا كَـٰلِحُونَ',
    'تلفح وجوههم النار وهم فيها كالحون',
    'تَلۡفَحُ وُجُوهَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ وَهُمۡ فِيهَا كَ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ُو</rule>نَ ١٠٤',
    104, 18, 4, 348, 300, 139, 'false'
  );
  
  -- Ayah 105 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2778,
    'أَلَمۡ تَكُنۡ ءَایَـٰتِی تُتۡلَىٰ عَلَیۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ',
    'الم تكن اياتي تتلى عليكم فكنتم بها تكذبون',
    'أَلَمۡ تَكُنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِى تُتۡلَىٰ عَلَيۡكُمۡ فَكُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا تُكَذِّب<rule class=madda_permissible>ُو</rule>نَ ١٠٥',
    105, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 106 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2779,
    'قَالُوا۟ رَبَّنَا غَلَبَتۡ عَلَیۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمࣰا ضَاۤلِّینَ',
    'قالوا ربنا غلبت علينا شقوتنا وكنا قوما ضالين',
    'قَالُو<rule class=slnt>اۡ</rule> رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِ<rule class=qalaqah>قۡ</rule>وَتُنَا وَكُ<rule class=ghunnah>نّ</rule>َا قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ض</rule><rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ِي</rule>نَ ١٠٦',
    106, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 107 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2780,
    'رَبَّنَاۤ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَـٰلِمُونَ',
    'ربنا اخرجنا منها فان عدنا فانا ظالمون',
    'رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡرِ<rule class=qalaqah>جۡ</rule>نَا مِنۡهَا فَإِنۡ عُ<rule class=qalaqah>دۡ</rule>نَا فَإِ<rule class=ghunnah>نّ</rule>َا ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ١٠٧',
    107, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 108 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2781,
    'قَالَ ٱخۡسَـُٔوا۟ فِیهَا وَلَا تُكَلِّمُونِ',
    'قال اخسئوا فيها ولا تكلمون',
    'قَالَ <rule class=ham_wasl>ٱ</rule>خۡسَــُٔو<rule class=slnt>اۡ</rule> فِيهَا وَلَا تُكَلِّم<rule class=madda_permissible>ُو</rule>نِ ١٠٨',
    108, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 109 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2782,
    'إِنَّهُۥ كَانَ فَرِیقࣱ مِّنۡ عِبَادِی یَقُولُونَ رَبَّنَاۤ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَیۡرُ ٱلرَّ ٰ⁠حِمِینَ',
    'انه كان فريق من عبادي يقولون ربنا امنا فاغفر لنا وارحمنا وانت خير الراحمين',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِبَادِى يَقُولُونَ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا فَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَنَا وَ<rule class=ham_wasl>ٱ</rule>رۡحَمۡنَا وَأَ<rule class=ikhafa>نت</rule>َ خَيۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>حِم<rule class=madda_permissible>ِي</rule>نَ ١٠٩',
    109, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 110 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2783,
    'فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِیًّا حَتَّىٰۤ أَنسَوۡكُمۡ ذِكۡرِی وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ',
    'فاتخذتموهم سخريا حتى انسوكم ذكري وكنتم منهم تضحكون',
    'فَ<rule class=ham_wasl>ٱ</rule>تَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نس</rule>َوۡكُمۡ ذِكۡرِى وَكُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُمۡ تَضۡحَك<rule class=madda_permissible>ُو</rule>نَ ١١٠',
    110, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 111 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2784,
    'إِنِّی جَزَیۡتُهُمُ ٱلۡیَوۡمَ بِمَا صَبَرُوۤا۟ أَنَّهُمۡ هُمُ ٱلۡفَاۤىِٕزُونَ',
    'اني جزيتهم اليوم بما صبروا انهم هم الفائزون',
    'إِ<rule class=ghunnah>نّ</rule>ِى جَزَيۡتُهُمُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ بِمَا صَبَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ هُمُ <rule class=ham_wasl>ٱ</rule>لۡف<rule class=madda_obligatory_mottasel>َا</rule>ٓئِز<rule class=madda_permissible>ُو</rule>نَ ١١١',
    111, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 112 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2785,
    'قَـٰلَ كَمۡ لَبِثۡتُمۡ فِی ٱلۡأَرۡضِ عَدَدَ سِنِینَ',
    'قال كم لبثتم في الارض عدد سنين',
    'قَ<rule class=madda_normal>ـٰ</rule>لَ كَمۡ لَبِثۡتُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ عَدَدَ سِن<rule class=madda_permissible>ِي</rule>نَ ١١٢',
    112, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 113 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2786,
    'قَالُوا۟ لَبِثۡنَا یَوۡمًا أَوۡ بَعۡضَ یَوۡمࣲ فَسۡـَٔلِ ٱلۡعَاۤدِّینَ',
    'قالوا لبثنا يوما او بعض يوم فاسال العادين',
    'قَالُو<rule class=slnt>اۡ</rule> لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ف</rule>َسۡــَٔلِ <rule class=ham_wasl>ٱ</rule>لۡع<rule class=madda_necessary>َا</rule>ٓدّ<rule class=madda_permissible>ِي</rule>نَ ١١٣',
    113, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 114 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2787,
    'قَـٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِیلࣰاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ',
    'قال ان لبثتم الا قليلا لو انكم كنتم تعلمون',
    'قَ<rule class=madda_normal>ـٰ</rule>لَ إ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّبِثۡتُمۡ إِلَّا قَلِيل<rule class=idgham_wo_ghunnah>اً‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡ أَ<rule class=ghunnah>نّ</rule>َكُمۡ كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١١٤',
    114, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 115 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2788,
    'أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَـٰكُمۡ عَبَثࣰا وَأَنَّكُمۡ إِلَیۡنَا لَا تُرۡجَعُونَ',
    'افحسبتم انما خلقناكم عبثا وانكم الينا لا ترجعون',
    'أَفَحَسِ<rule class=qalaqah>بۡ</rule>تُمۡ أَ<rule class=ghunnah>نّ</rule>َمَا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ عَبَ<rule class=idgham_ghunnah>ثًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َكُمۡ إِلَيۡنَا لَا تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ١١٥',
    115, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 116 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2789,
    'فَتَعَـٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَاۤ إِلَـٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِیمِ',
    'فتعالى الله الملك الحق لا اله الا هو رب العرش الكريم',
    'فَتَعَ<rule class=madda_normal>ـٰ</rule>لَى <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمَلِكُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۖ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ رَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ <rule class=ham_wasl>ٱ</rule>لۡكَر<rule class=madda_permissible>ِي</rule>مِ ١١٦',
    116, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 117 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2790,
    'وَمَن یَدۡعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ لَا بُرۡهَـٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦۤۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلۡكَـٰفِرُونَ',
    'ومن يدع مع الله الها اخر لا برهان له به فانما حسابه عند ربه انه لا يفلح الكافرون',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>عُ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ لَا بُرۡهَ<rule class=madda_normal>ـٰ</rule>نَ لَهُ<rule class=madda_normal>ۥ</rule> بِه<rule class=madda_normal>ِۦ</rule> فَإِ<rule class=ghunnah>نّ</rule>َمَا حِسَابُهُ<rule class=madda_normal>ۥ</rule> عِ<rule class=ikhafa>ند</rule>َ رَبِّه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ١١٧',
    117, 18, 4, 349, 300, 139, 'false'
  );
  
  -- Ayah 118 Surah Al-Muminoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    23,
    2791,
    'وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَیۡرُ ٱلرَّ ٰ⁠حِمِینَ',
    'وقل رب اغفر وارحم وانت خير الراحمين',
    'وَقُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبِّ <rule class=ham_wasl>ٱ</rule>غۡفِرۡ وَ<rule class=ham_wasl>ٱ</rule>رۡحَمۡ وَأَ<rule class=ikhafa>نت</rule>َ خَيۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>حِم<rule class=madda_permissible>ِي</rule>نَ ١١٨',
    118, 18, 4, 349, 300, 139, 'false'
  );
  

-- Surah An-Noor
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (24, 'سُورَةُ النُّورِ', 'An-Noor', 'The Light', 'Medinan', 64);

  -- Ayah 1 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2792,
    'سُورَةٌ أَنزَلۡنَـٰهَا وَفَرَضۡنَـٰهَا وَأَنزَلۡنَا فِیهَاۤ ءَایَـٰتِۭ بَیِّنَـٰتࣲ لَّعَلَّكُمۡ تَذَكَّرُونَ',
    'سورة انزلناها وفرضناها وانزلنا فيها ايات بينات لعلكم تذكرون',
    'سُورَةٌ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هَا وَفَرَضۡنَ<rule class=madda_normal>ـٰ</rule>هَا وَأَ<rule class=ikhafa>نز</rule>َلۡنَا فِيه<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّكُمۡ تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 2 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2793,
    'ٱلزَّانِیَةُ وَٱلزَّانِی فَٱجۡلِدُوا۟ كُلَّ وَ ٰ⁠حِدࣲ مِّنۡهُمَا مِا۟ئَةَ جَلۡدَةࣲۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةࣱ فِی دِینِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۖ وَلۡیَشۡهَدۡ عَذَابَهُمَا طَاۤىِٕفَةࣱ مِّنَ ٱلۡمُؤۡمِنِینَ',
    'الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة ولا تاخذكم بهما رافة في دين الله ان كنتم تؤمنون بالله واليوم الاخر وليشهد عذابهما طائفة من المؤمنين',
    'ٱ<rule class=laam_shamsiyah>ل</rule>زَّانِيَةُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّانِى فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>لِدُو<rule class=slnt>اۡ</rule> كُلَّ و<rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمَا مِ<rule class=slnt>اۡ</rule>ئَةَ جَلۡدَ<rule class=idgham_ghunnah>ةٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَأۡخُذۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِمَا رَأۡفَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى دِينِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ‌ۖ وَلۡيَشۡهَ<rule class=qalaqah>دۡ</rule> عَذَابَهُمَا ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 3 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2794,
    'ٱلزَّانِی لَا یَنكِحُ إِلَّا زَانِیَةً أَوۡ مُشۡرِكَةࣰ وَٱلزَّانِیَةُ لَا یَنكِحُهَاۤ إِلَّا زَانٍ أَوۡ مُشۡرِكࣱۚ وَحُرِّمَ ذَ ٰ⁠لِكَ عَلَى ٱلۡمُؤۡمِنِینَ',
    'الزاني لا ينكح الا زانية او مشركة والزانية لا ينكحها الا زان او مشرك وحرم ذلك على المؤمنين',
    'ٱ<rule class=laam_shamsiyah>ل</rule>زَّانِى لَا يَ<rule class=ikhafa>نك</rule>ِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّانِيَةُ لَا يَ<rule class=ikhafa>نك</rule>ِحُه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا زَانٍ أَوۡ مُشۡرِ<rule class=idgham_ghunnah>كٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َحُرِّمَ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٣',
    3, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 4 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2795,
    'وَٱلَّذِینَ یَرۡمُونَ ٱلۡمُحۡصَنَـٰتِ ثُمَّ لَمۡ یَأۡتُوا۟ بِأَرۡبَعَةِ شُهَدَاۤءَ فَٱجۡلِدُوهُمۡ ثَمَـٰنِینَ جَلۡدَةࣰ وَلَا تَقۡبَلُوا۟ لَهُمۡ شَهَـٰدَةً أَبَدࣰاۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ',
    'والذين يرمون المحصنات ثم لم ياتوا باربعة شهداء فاجلدوهم ثمانين جلدة ولا تقبلوا لهم شهادة ابدا واولئك هم الفاسقون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَرۡمُونَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡصَنَ<rule class=madda_normal>ـٰ</rule>تِ ثُ<rule class=ghunnah>مّ</rule>َ لَمۡ يَأۡتُو<rule class=slnt>اۡ</rule> بِأَرۡبَعَةِ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>لِدُوهُمۡ ثَمَ<rule class=madda_normal>ـٰ</rule>نِينَ جَلۡدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَ<rule class=qalaqah>قۡ</rule>بَلُو<rule class=slnt>اۡ</rule> لَهُمۡ شَهَ<rule class=madda_normal>ـٰ</rule>دَةً أَبَ<rule class=idgham_ghunnah>دًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 5 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2796,
    'إِلَّا ٱلَّذِینَ تَابُوا۟ مِنۢ بَعۡدِ ذَ ٰ⁠لِكَ وَأَصۡلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'الا الذين تابوا من بعد ذلك واصلحوا فان الله غفور رحيم',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَابُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ وَأَصۡلَحُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٥',
    5, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 6 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2797,
    'وَٱلَّذِینَ یَرۡمُونَ أَزۡوَ ٰ⁠جَهُمۡ وَلَمۡ یَكُن لَّهُمۡ شُهَدَاۤءُ إِلَّاۤ أَنفُسُهُمۡ فَشَهَـٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَـٰدَ ٰ⁠تِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِینَ',
    'والذين يرمون ازواجهم ولم يكن لهم شهداء الا انفسهم فشهادة احدهم اربع شهادات بالله انه لمن الصادقين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَرۡمُونَ أَزۡو<rule class=madda_normal>ٰ</rule>جَهُمۡ وَلَمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ فَشَهَ<rule class=madda_normal>ـٰ</rule>دَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَ<rule class=madda_normal>ـٰ</rule>د<rule class=madda_normal>ٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۙ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 7 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2798,
    'وَٱلۡخَـٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَیۡهِ إِن كَانَ مِنَ ٱلۡكَـٰذِبِینَ',
    'والخامسة ان لعنت الله عليه ان كان من الكاذبين',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>مِسَةُ أَ<rule class=ghunnah>نّ</rule>َ لَعۡنَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 8 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2799,
    'وَیَدۡرَؤُا۟ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَـٰدَ ٰ⁠تِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَـٰذِبِینَ',
    'ويدرا عنها العذاب ان تشهد اربع شهادات بالله انه لمن الكاذبين',
    'وَيَ<rule class=qalaqah>دۡ</rule>رَؤُ<rule class=slnt>اۡ</rule> عَنۡهَا <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َشۡهَدَ أَرۡبَعَ شَهَ<rule class=madda_normal>ـٰ</rule>د<rule class=madda_normal>ٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۙ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 9 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2800,
    'وَٱلۡخَـٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَیۡهَاۤ إِن كَانَ مِنَ ٱلصَّـٰدِقِینَ',
    'والخامسة ان غضب الله عليها ان كان من الصادقين',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>مِسَةَ أَ<rule class=ghunnah>نّ</rule>َ غَضَبَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٩',
    9, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 10 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2801,
    'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِیمٌ',
    'ولولا فضل الله عليكم ورحمته وان الله تواب حكيم',
    'وَلَوۡلَا فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُ<rule class=madda_normal>ۥ</rule> وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ تَوَّابٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ١٠',
    10, 18, 4, 350, 301, 140, 'false'
  );
  
  -- Ayah 11 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2802,
    'إِنَّ ٱلَّذِینَ جَاۤءُو بِٱلۡإِفۡكِ عُصۡبَةࣱ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرࣰّا لَّكُمۖ بَلۡ هُوَ خَیۡرࣱ لَّكُمۡۚ لِكُلِّ ٱمۡرِئࣲ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِی تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِیمࣱ',
    'ان الذين جاءوا بالافك عصبة منكم لا تحسبوه شرا لكم بل هو خير لكم لكل امرئ منهم ما اكتسب من الاثم والذي تولى كبره منهم له عذاب عظيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو بِ<rule class=ham_wasl>ٱ</rule>لۡإِفۡكِ عُصۡبَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ لَا تَحۡسَبُوهُ شَر<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّك<rule class=ikhafa_shafawi>ُم‌ۖ</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ هُوَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۚ لِكُلِّ <rule class=ham_wasl>ٱ</rule>مۡرِى<rule class=idgham_ghunnah>ٍٕ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا <rule class=ham_wasl>ٱ</rule>كۡتَسَبَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِى تَوَلَّىٰ كِ<rule class=qalaqah>بۡ</rule>رَهُ<rule class=madda_normal>ۥ</rule> مِنۡهُمۡ لَهُ<rule class=madda_normal>ۥ</rule> عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١١',
    11, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 12 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2803,
    'لَّوۡلَاۤ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَـٰتُ بِأَنفُسِهِمۡ خَیۡرࣰا وَقَالُوا۟ هَـٰذَاۤ إِفۡكࣱ مُّبِینࣱ',
    'لولا اذ سمعتموه ظن المؤمنون والمؤمنات بانفسهم خيرا وقالوا هذا افك مبين',
    'لَّوۡل<rule class=madda_obligatory_monfasel>َآ</rule> إِذۡ سَمِعۡتُمُوهُ ظَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تُ بِأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َقَالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِفۡ<rule class=idgham_ghunnah>كٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٢',
    12, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 13 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2804,
    'لَّوۡلَا جَاۤءُو عَلَیۡهِ بِأَرۡبَعَةِ شُهَدَاۤءَۚ فَإِذۡ لَمۡ یَأۡتُوا۟ بِٱلشُّهَدَاۤءِ فَأُو۟لَـٰۤىِٕكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَـٰذِبُونَ',
    'لولا جاءوا عليه باربعة شهداء فاذ لم ياتوا بالشهداء فاولئك عند الله هم الكاذبون',
    'لَّوۡلَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ فَإِذۡ لَمۡ يَأۡتُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ هُمُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 14 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2805,
    'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ لَمَسَّكُمۡ فِی مَاۤ أَفَضۡتُمۡ فِیهِ عَذَابٌ عَظِیمٌ',
    'ولولا فضل الله عليكم ورحمته في الدنيا والاخرة لمسكم في ما افضتم فيه عذاب عظيم',
    'وَلَوۡلَا فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ لَمَسَّكُمۡ فِى م<rule class=madda_obligatory_monfasel>َآ</rule> أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٤',
    14, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 15 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2806,
    'إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَیۡسَ لَكُم بِهِۦ عِلۡمࣱ وَتَحۡسَبُونَهُۥ هَیِّنࣰا وَهُوَ عِندَ ٱللَّهِ عَظِیمࣱ',
    'اذ تلقونه بالسنتكم وتقولون بافواهكم ما ليس لكم به علم وتحسبونه هينا وهو عند الله عظيم',
    'إِذۡ تَلَقَّوۡنَهُ<rule class=madda_normal>ۥ</rule> بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا لَيۡسَ لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> عِلۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َتَحۡسَبُونَهُ<rule class=madda_normal>ۥ</rule> هَيِّ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٥',
    15, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 16 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2807,
    'وَلَوۡلَاۤ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا یَكُونُ لَنَاۤ أَن نَّتَكَلَّمَ بِهَـٰذَا سُبۡحَـٰنَكَ هَـٰذَا بُهۡتَـٰنٌ عَظِیمࣱ',
    'ولولا اذ سمعتموه قلتم ما يكون لنا ان نتكلم بهذا سبحانك هذا بهتان عظيم',
    'وَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> إِذۡ سَمِعۡتُمُوهُ قُلۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَكُونُ لَن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّتَكَلَّمَ بِهَ<rule class=madda_normal>ـٰ</rule>ذَا سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ هَ<rule class=madda_normal>ـٰ</rule>ذَا بُهۡتَ<rule class=madda_normal>ـٰ</rule>نٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٦',
    16, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 17 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2808,
    'یَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثۡلِهِۦۤ أَبَدًا إِن كُنتُم مُّؤۡمِنِینَ',
    'يعظكم الله ان تعودوا لمثله ابدا ان كنتم مؤمنين',
    'يَعِظُكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعُودُو<rule class=slnt>اۡ</rule> لِمِثۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَبَدًا إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 18 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2809,
    'وَیُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِۚ وَٱللَّهُ عَلِیمٌ حَكِیمٌ',
    'ويبين الله لكم الايات والله عليم حكيم',
    'وَيُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ١٨',
    18, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 19 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2810,
    'إِنَّ ٱلَّذِینَ یُحِبُّونَ أَن تَشِیعَ ٱلۡفَـٰحِشَةُ فِی ٱلَّذِینَ ءَامَنُوا۟ لَهُمۡ عَذَابٌ أَلِیمࣱ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۚ وَٱللَّهُ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ',
    'ان الذين يحبون ان تشيع الفاحشة في الذين امنوا لهم عذاب اليم في الدنيا والاخرة والله يعلم وانتم لا تعلمون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُحِبُّونَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َشِيعَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>حِشَةُ فِى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَهُمۡ عَذَابٌ أَلِي<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 20 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2811,
    'وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفࣱ رَّحِیمࣱ',
    'ولولا فضل الله عليكم ورحمته وان الله رءوف رحيم',
    'وَلَوۡلَا فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُ<rule class=madda_normal>ۥ</rule> وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ رَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٢٠',
    20, 18, 4, 351, 302, 140, 'false'
  );
  
  -- Ayah 21 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2812,
    '۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَ ٰ⁠تِ ٱلشَّیۡطَـٰنِۚ وَمَن یَتَّبِعۡ خُطُوَ ٰ⁠تِ ٱلشَّیۡطَـٰنِ فَإِنَّهُۥ یَأۡمُرُ بِٱلۡفَحۡشَاۤءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدࣰا وَلَـٰكِنَّ ٱللَّهَ یُزَكِّی مَن یَشَاۤءُۗ وَٱللَّهُ سَمِیعٌ عَلِیمࣱ',
    'يا ايها الذين امنوا لا تتبعوا خطوات الشيطان ومن يتبع خطوات الشيطان فانه يامر بالفحشاء والمنكر ولولا فضل الله عليكم ورحمته ما زكى منكم من احد ابدا ولكن الله يزكي من يشاء والله سميع عليم',
    '۞يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَتَّبِعُو<rule class=slnt>اۡ</rule> خُطُو<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّبِعۡ خُطُو<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَأۡمُرُ بِ<rule class=ham_wasl>ٱ</rule>لۡفَحۡش<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ‌ۚ وَلَوۡلَا فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُ<rule class=madda_normal>ۥ</rule> مَا زَكَىٰ مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَحَدٍ أَبَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُزَكِّى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢١',
    21, 18, 4, 352, 303, 141, 'false'
  );
  
  -- Ayah 22 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2813,
    'وَلَا یَأۡتَلِ أُو۟لُوا۟ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن یُؤۡتُوۤا۟ أُو۟لِی ٱلۡقُرۡبَىٰ وَٱلۡمَسَـٰكِینَ وَٱلۡمُهَـٰجِرِینَ فِی سَبِیلِ ٱللَّهِۖ وَلۡیَعۡفُوا۟ وَلۡیَصۡفَحُوۤا۟ۗ أَلَا تُحِبُّونَ أَن یَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمٌ',
    'ولا ياتل اولو الفضل منكم والسعة ان يؤتوا اولي القربى والمساكين والمهاجرين في سبيل الله وليعفوا وليصفحوا الا تحبون ان يغفر الله لكم والله غفور رحيم',
    'وَلَا يَأۡتَلِ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡفَضۡلِ مِ<rule class=ikhafa>نك</rule>ُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّعَةِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡت<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُهَ<rule class=madda_normal>ـٰ</rule>جِرِينَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَلۡيَعۡفُو<rule class=slnt>اۡ</rule> وَلۡيَصۡفَح<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۗ</rule> أَلَا تُحِبُّونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغۡفِرَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٢٢',
    22, 18, 4, 352, 303, 141, 'false'
  );
  
  -- Ayah 23 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2814,
    'إِنَّ ٱلَّذِینَ یَرۡمُونَ ٱلۡمُحۡصَنَـٰتِ ٱلۡغَـٰفِلَـٰتِ ٱلۡمُؤۡمِنَـٰتِ لُعِنُوا۟ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَلَهُمۡ عَذَابٌ عَظِیمࣱ',
    'ان الذين يرمون المحصنات الغافلات المؤمنات لعنوا في الدنيا والاخرة ولهم عذاب عظيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَرۡمُونَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡصَنَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>فِلَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ لُعِنُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَلَهُمۡ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٢٣',
    23, 18, 4, 352, 303, 141, 'false'
  );
  
  -- Ayah 24 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2815,
    'یَوۡمَ تَشۡهَدُ عَلَیۡهِمۡ أَلۡسِنَتُهُمۡ وَأَیۡدِیهِمۡ وَأَرۡجُلُهُم بِمَا كَانُوا۟ یَعۡمَلُونَ',
    'يوم تشهد عليهم السنتهم وايديهم وارجلهم بما كانوا يعملون',
    'يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 18, 4, 352, 303, 141, 'false'
  );
  
  -- Ayah 25 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2816,
    'یَوۡمَىِٕذࣲ یُوَفِّیهِمُ ٱللَّهُ دِینَهُمُ ٱلۡحَقَّ وَیَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِینُ',
    'يومئذ يوفيهم الله دينهم الحق ويعلمون ان الله هو الحق المبين',
    'يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوَفِّيهِمُ <rule class=ham_wasl>ٱ</rule>للَّهُ دِينَهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَيَعۡلَمُونَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ٢٥',
    25, 18, 4, 352, 303, 141, 'false'
  );
  
  -- Ayah 26 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2817,
    'ٱلۡخَبِیثَـٰتُ لِلۡخَبِیثِینَ وَٱلۡخَبِیثُونَ لِلۡخَبِیثَـٰتِۖ وَٱلطَّیِّبَـٰتُ لِلطَّیِّبِینَ وَٱلطَّیِّبُونَ لِلطَّیِّبَـٰتِۚ أُو۟لَـٰۤىِٕكَ مُبَرَّءُونَ مِمَّا یَقُولُونَۖ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ',
    'الخبيثات للخبيثين والخبيثون للخبيثات والطيبات للطيبين والطيبون للطيبات اولئك مبرءون مما يقولون لهم مغفرة ورزق كريم',
    'ٱلۡخَبِيثَ<rule class=madda_normal>ـٰ</rule>تُ لِلۡخَبِيثِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡخَبِيثُونَ لِلۡخَبِيثَ<rule class=madda_normal>ـٰ</rule>تِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تُ لِلطَّيِّبِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبُونَ لِلطَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مُبَرَّءُونَ مِ<rule class=ghunnah>مّ</rule>َا يَقُولُونَ‌ۖ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َرِزۡ<rule class=ikhafa>قٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٢٦',
    26, 18, 4, 352, 303, 141, 'false'
  );
  
  -- Ayah 27 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2818,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَدۡخُلُوا۟ بُیُوتًا غَیۡرَ بُیُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰۤ أَهۡلِهَاۚ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ',
    'يا ايها الذين امنوا لا تدخلوا بيوتا غير بيوتكم حتى تستانسوا وتسلموا على اهلها ذلكم خير لكم لعلكم تذكرون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَ<rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُو<rule class=slnt>اۡ</rule> وَتُسَلِّمُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِهَا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ لَعَلَّكُمۡ تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 18, 4, 352, 304, 141, 'false'
  );
  
  -- Ayah 28 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2819,
    'فَإِن لَّمۡ تَجِدُوا۟ فِیهَاۤ أَحَدࣰا فَلَا تَدۡخُلُوهَا حَتَّىٰ یُؤۡذَنَ لَكُمۡۖ وَإِن قِیلَ لَكُمُ ٱرۡجِعُوا۟ فَٱرۡجِعُوا۟ۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِیمࣱ',
    'فان لم تجدوا فيها احدا فلا تدخلوها حتى يؤذن لكم وان قيل لكم ارجعوا فارجعوا هو ازكى لكم والله بما تعملون عليم',
    'فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَجِدُو<rule class=slnt>اۡ</rule> فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَحَ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َلَا تَ<rule class=qalaqah>دۡ</rule>خُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ِيلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>رۡجِعُو<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule>رۡجِعُو<rule class=slnt>اۡ‌ۖ</rule> هُوَ أَزۡكَىٰ لَكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ عَل<rule class=madda_permissible>ِي</rule>مٌ ٢٨',
    28, 18, 4, 353, 304, 141, 'false'
  );
  
  -- Ayah 29 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2820,
    'لَّیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَن تَدۡخُلُوا۟ بُیُوتًا غَیۡرَ مَسۡكُونَةࣲ فِیهَا مَتَـٰعࣱ لَّكُمۡۚ وَٱللَّهُ یَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ',
    'ليس عليكم جناح ان تدخلوا بيوتا غير مسكونة فيها متاع لكم والله يعلم ما تبدون وما تكتمون',
    'لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> بُيُوتًا غَيۡرَ مَسۡكُونَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِيهَا مَتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>عٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ مَا تُ<rule class=qalaqah>بۡ</rule>دُونَ وَمَا تَكۡتُم<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 18, 4, 353, 304, 141, 'false'
  );
  
  -- Ayah 30 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2821,
    'قُل لِّلۡمُؤۡمِنِینَ یَغُضُّوا۟ مِنۡ أَبۡصَـٰرِهِمۡ وَیَحۡفَظُوا۟ فُرُوجَهُمۡۚ ذَ ٰ⁠لِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا یَصۡنَعُونَ',
    'قل للمؤمنين يغضوا من ابصارهم ويحفظوا فروجهم ذلك ازكى لهم ان الله خبير بما يصنعون',
    'قُل لِّلۡمُؤۡمِنِينَ يَغُضُّو<rule class=slnt>اۡ</rule> مِنۡ أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ وَيَحۡفَظُو<rule class=slnt>اۡ</rule> فُرُوجَهُمۡ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ أَزۡكَىٰ لَهُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا يَصۡنَع<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 18, 4, 353, 304, 141, 'false'
  );
  
  -- Ayah 31 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2822,
    'وَقُل لِّلۡمُؤۡمِنَـٰتِ یَغۡضُضۡنَ مِنۡ أَبۡصَـٰرِهِنَّ وَیَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا یُبۡدِینَ زِینَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡیَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُیُوبِهِنَّۖ وَلَا یُبۡدِینَ زِینَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَاۤىِٕهِنَّ أَوۡ ءَابَاۤءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَاۤىِٕهِنَّ أَوۡ أَبۡنَاۤءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَ ٰ⁠نِهِنَّ أَوۡ بَنِیۤ إِخۡوَ ٰ⁠نِهِنَّ أَوۡ بَنِیۤ أَخَوَ ٰ⁠تِهِنَّ أَوۡ نِسَاۤىِٕهِنَّ أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُهُنَّ أَوِ ٱلتَّـٰبِعِینَ غَیۡرِ أُو۟لِی ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِینَ لَمۡ یَظۡهَرُوا۟ عَلَىٰ عَوۡرَ ٰ⁠تِ ٱلنِّسَاۤءِۖ وَلَا یَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِیُعۡلَمَ مَا یُخۡفِینَ مِن زِینَتِهِنَّۚ وَتُوبُوۤا۟ إِلَى ٱللَّهِ جَمِیعًا أَیُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ',
    'وقل للمؤمنات يغضضن من ابصارهن ويحفظن فروجهن ولا يبدين زينتهن الا ما ظهر منها وليضربن بخمرهن على جيوبهن ولا يبدين زينتهن الا لبعولتهن او ابائهن او اباء بعولتهن او ابنائهن او ابناء بعولتهن او اخوانهن او بني اخوانهن او بني اخواتهن او نسائهن او ما ملكت ايمانهن او التابعين غير اولي الاربة من الرجال او الطفل الذين لم يظهروا على عورات النساء ولا يضربن بارجلهن ليعلم ما يخفين من زينتهن وتوبوا الى الله جميعا ايه المؤمنون لعلكم تفلحون',
    'وَقُل لِّلۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ يَغۡضُضۡنَ مِنۡ أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رِهِ<rule class=ghunnah>نّ</rule>َ وَيَحۡفَظۡنَ فُرُوجَهُ<rule class=ghunnah>نّ</rule>َ وَلَا يُ<rule class=qalaqah>بۡ</rule>دِينَ زِينَتَهُ<rule class=ghunnah>نّ</rule>َ إِلَّا مَا ظَهَرَ مِنۡهَا‌ۖ وَلۡيَضۡرِ<rule class=qalaqah>بۡ</rule>نَ بِخُمُرِهِ<rule class=ghunnah>نّ</rule>َ عَلَىٰ جُيُوبِهِ<rule class=ghunnah>نّ</rule>َ‌ۖ وَلَا يُ<rule class=qalaqah>بۡ</rule>دِينَ زِينَتَهُ<rule class=ghunnah>نّ</rule>َ إِلَّا لِبُعُولَتِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بُعُولَتِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بُعُولَتِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ إِخۡو<rule class=madda_normal>ٰ</rule>نِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِخۡو<rule class=madda_normal>ٰ</rule>نِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَو<rule class=madda_normal>ٰ</rule>تِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِ<rule class=ghunnah>نّ</rule>َ أَوۡ مَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُهُ<rule class=ghunnah>نّ</rule>َ أَوِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=madda_normal>ـٰ</rule>بِعِينَ غَيۡرِ أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡإِرۡبَةِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّجَالِ أَوِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طِّفۡلِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَمۡ يَظۡهَرُو<rule class=slnt>اۡ</rule> عَلَىٰ عَوۡر<rule class=madda_normal>ٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۖ وَلَا يَضۡرِ<rule class=qalaqah>بۡ</rule>نَ بِأَرۡجُلِهِ<rule class=ghunnah>نّ</rule>َ لِيُعۡلَمَ مَا يُخۡفِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>ِينَتِهِ<rule class=ghunnah>نّ</rule>َ‌ۚ وَتُوب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ جَمِيعًا أَيُّهَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 18, 4, 353, 304, 141, 'false'
  );
  
  -- Ayah 32 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2823,
    'وَأَنكِحُوا۟ ٱلۡأَیَـٰمَىٰ مِنكُمۡ وَٱلصَّـٰلِحِینَ مِنۡ عِبَادِكُمۡ وَإِمَاۤىِٕكُمۡۚ إِن یَكُونُوا۟ فُقَرَاۤءَ یُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَ ٰ⁠سِعٌ عَلِیمࣱ',
    'وانكحوا الايامى منكم والصالحين من عبادكم وامائكم ان يكونوا فقراء يغنهم الله من فضله والله واسع عليم',
    'وَأَ<rule class=ikhafa>نك</rule>ِحُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>مَىٰ مِ<rule class=ikhafa>نك</rule>ُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحِينَ مِنۡ عِبَادِكُمۡ وَإِم<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونُو<rule class=slnt>اۡ</rule> فُقَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ يُغۡنِهِمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ و<rule class=madda_normal>ٰ</rule>سِعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٣٢',
    32, 18, 4, 354, 304, 141, 'false'
  );
  
  -- Ayah 33 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2824,
    'وَلۡیَسۡتَعۡفِفِ ٱلَّذِینَ لَا یَجِدُونَ نِكَاحًا حَتَّىٰ یُغۡنِیَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِینَ یَبۡتَغُونَ ٱلۡكِتَـٰبَ مِمَّا مَلَكَتۡ أَیۡمَـٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِیهِمۡ خَیۡرࣰاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِیۤ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُوا۟ فَتَیَـٰتِكُمۡ عَلَى ٱلۡبِغَاۤءِ إِنۡ أَرَدۡنَ تَحَصُّنࣰا لِّتَبۡتَغُوا۟ عَرَضَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَمَن یُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَ ٰ⁠هِهِنَّ غَفُورࣱ رَّحِیمࣱ',
    'وليستعفف الذين لا يجدون نكاحا حتى يغنيهم الله من فضله والذين يبتغون الكتاب مما ملكت ايمانكم فكاتبوهم ان علمتم فيهم خيرا واتوهم من مال الله الذي اتاكم ولا تكرهوا فتياتكم على البغاء ان اردن تحصنا لتبتغوا عرض الحياة الدنيا ومن يكرههن فان الله من بعد اكراههن غفور رحيم',
    'وَلۡيَسۡتَعۡفِفِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>بۡ</rule>تَغُونَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِ<rule class=ghunnah>مّ</rule>َا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِيهِمۡ خَيۡ<rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َءَاتُوه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّالِ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۚ وَلَا تُكۡرِهُو<rule class=slnt>اۡ</rule> فَتَيَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡبِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِنۡ أَرَ<rule class=qalaqah>دۡ</rule>نَ تَحَصُّ<rule class=idgham_wo_ghunnah>نًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتَ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> عَرَضَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُكۡرِههُّ<rule class=ghunnah>نّ</rule>َ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ إِكۡر<rule class=madda_normal>ٰ</rule>هِهِ<rule class=ghunnah>نّ</rule>َ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٣٣',
    33, 18, 4, 354, 304, 141, 'false'
  );
  
  -- Ayah 34 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2825,
    'وَلَقَدۡ أَنزَلۡنَاۤ إِلَیۡكُمۡ ءَایَـٰتࣲ مُّبَیِّنَـٰتࣲ وَمَثَلࣰا مِّنَ ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلِكُمۡ وَمَوۡعِظَةࣰ لِّلۡمُتَّقِینَ',
    'ولقد انزلنا اليكم ايات مبينات ومثلا من الذين خلوا من قبلكم وموعظة للمتقين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّبَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَثَل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَلَوۡ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ وَمَوۡعِظَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 18, 4, 354, 304, 141, 'false'
  );
  
  -- Ayah 35 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2826,
    '۞ ٱللَّهُ نُورُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةࣲ فِیهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِی زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبࣱ دُرِّیࣱّ یُوقَدُ مِن شَجَرَةࣲ مُّبَـٰرَكَةࣲ زَیۡتُونَةࣲ لَّا شَرۡقِیَّةࣲ وَلَا غَرۡبِیَّةࣲ یَكَادُ زَیۡتُهَا یُضِیۤءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارࣱۚ نُّورٌ عَلَىٰ نُورࣲۚ یَهۡدِی ٱللَّهُ لِنُورِهِۦ مَن یَشَاۤءُۚ وَیَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَـٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'الله نور السماوات والارض مثل نوره كمشكاة فيها مصباح المصباح في زجاجة الزجاجة كانها كوكب دري يوقد من شجرة مباركة زيتونة لا شرقية ولا غربية يكاد زيتها يضيء ولو لم تمسسه نار نور على نور يهدي الله لنوره من يشاء ويضرب الله الامثال للناس والله بكل شيء عليم',
    '۞ٱللَّهُ نُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ مَثَلُ نُورِه<rule class=madda_normal>ِۦ</rule> كَمِشۡكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule><rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِيهَا مِصۡبَاحٌ‌ۖ <rule class=ham_wasl>ٱ</rule>لۡمِصۡبَاحُ فِى زُجَاجَةٍ‌ۖ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زُّجَاجَةُ كَأَ<rule class=ghunnah>نّ</rule>َهَا كَوۡكَ<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>د</rule>ُرِّ<rule class=idgham_ghunnah>ىٌّ</rule> <rule class=idgham_ghunnah>ي</rule>ُوقَدُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َجَرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّبَ<rule class=madda_normal>ـٰ</rule>رَكَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ز</rule>َيۡتُونَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا شَرۡقِيَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا غَرۡبِيَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>َكَادُ زَيۡتُهَا يُض<rule class=madda_obligatory_mottasel>ِى</rule>ٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَا<rule class=idgham_ghunnah>رٌ‌ۚ</rule> <rule class=idgham_ghunnah>ن</rule>ُّورٌ عَلَىٰ نُو<rule class=idgham_ghunnah>رٍ‌ۗ</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِى <rule class=ham_wasl>ٱ</rule>للَّهُ لِنُورِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَيَضۡرِبُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡثَ<rule class=madda_normal>ـٰ</rule>لَ لِل<rule class=ghunnah>نّ</rule>َاسِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٣٥',
    35, 18, 4, 354, 305, 142, 'false'
  );
  
  -- Ayah 36 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2827,
    'فِی بُیُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَیُذۡكَرَ فِیهَا ٱسۡمُهُۥ یُسَبِّحُ لَهُۥ فِیهَا بِٱلۡغُدُوِّ وَٱلۡـَٔاصَالِ',
    'في بيوت اذن الله ان ترفع ويذكر فيها اسمه يسبح له فيها بالغدو والاصال',
    'فِى بُيُوتٍ أَذِنَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرۡفَعَ وَيُذۡكَرَ فِيهَا <rule class=ham_wasl>ٱ</rule>سۡمُهُ<rule class=madda_normal>ۥ</rule> يُسَبِّحُ لَهُ<rule class=madda_normal>ۥ</rule> فِيهَا بِ<rule class=ham_wasl>ٱ</rule>لۡغُدُوِّ وَ<rule class=ham_wasl>ٱ</rule>لۡأَص<rule class=madda_permissible>َا</rule>لِ ٣٦',
    36, 18, 4, 354, 305, 142, 'false'
  );
  
  -- Ayah 37 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2828,
    'رِجَالࣱ لَّا تُلۡهِیهِمۡ تِجَـٰرَةࣱ وَلَا بَیۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِیتَاۤءِ ٱلزَّكَوٰةِ یَخَافُونَ یَوۡمࣰا تَتَقَلَّبُ فِیهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَـٰرُ',
    'رجال لا تلهيهم تجارة ولا بيع عن ذكر الله واقام الصلاة وايتاء الزكاة يخافون يوما تتقلب فيه القلوب والابصار',
    'رِجَا<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تُلۡهِيهِمۡ تِجَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا بَيۡعٌ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَإِقَامِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَإِيت<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ‌ۙ يَخَافُونَ يَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ت</rule>َتَقَلَّبُ فِيهِ <rule class=ham_wasl>ٱ</rule>لۡقُلُوبُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_permissible>ـٰ</rule>رُ ٣٧',
    37, 18, 4, 355, 305, 142, 'false'
  );
  
  -- Ayah 38 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2829,
    'لِیَجۡزِیَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُوا۟ وَیَزِیدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ یَرۡزُقُ مَن یَشَاۤءُ بِغَیۡرِ حِسَابࣲ',
    'ليجزيهم الله احسن ما عملوا ويزيدهم من فضله والله يرزق من يشاء بغير حساب',
    'لِيَ<rule class=qalaqah>جۡ</rule>زِيَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ أَحۡسَنَ مَا عَمِلُو<rule class=slnt>اۡ</rule> وَيَزِيدَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَرۡزُقُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بِغَيۡرِ حِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٣٨',
    38, 18, 4, 355, 305, 142, 'false'
  );
  
  -- Ayah 39 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2830,
    'وَٱلَّذِینَ كَفَرُوۤا۟ أَعۡمَـٰلُهُمۡ كَسَرَابِۭ بِقِیعَةࣲ یَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَاۤءً حَتَّىٰۤ إِذَا جَاۤءَهُۥ لَمۡ یَجِدۡهُ شَیۡـࣰٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥۗ وَٱللَّهُ سَرِیعُ ٱلۡحِسَابِ',
    'والذين كفروا اعمالهم كسراب بقيعة يحسبه الظمان ماء حتى اذا جاءه لم يجده شيئا ووجد الله عنده فوفاه حسابه والله سريع الحساب',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُهُمۡ كَسَرَا<rule class=iqlab>بِۭ</rule> <rule class=iqlab>ب</rule>ِقِيعَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>َحۡسَبُهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّمۡـَٔـانُ م<rule class=madda_obligatory_mottasel>َا</rule>ٓءً حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_normal>ۥ</rule> لَمۡ يَجِ<rule class=qalaqah>دۡ</rule>هُ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َوَجَدَ <rule class=ham_wasl>ٱ</rule>للَّهَ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> فَوَفَّ<rule class=madda_normal>ـٰ</rule>هُ حِسَابَهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٣٩',
    39, 18, 4, 355, 305, 142, 'false'
  );
  
  -- Ayah 40 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2831,
    'أَوۡ كَظُلُمَـٰتࣲ فِی بَحۡرࣲ لُّجِّیࣲّ یَغۡشَىٰهُ مَوۡجࣱ مِّن فَوۡقِهِۦ مَوۡجࣱ مِّن فَوۡقِهِۦ سَحَابࣱۚ ظُلُمَـٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَاۤ أَخۡرَجَ یَدَهُۥ لَمۡ یَكَدۡ یَرَىٰهَاۗ وَمَن لَّمۡ یَجۡعَلِ ٱللَّهُ لَهُۥ نُورࣰا فَمَا لَهُۥ مِن نُّورٍ',
    'او كظلمات في بحر لجي يغشاه موج من فوقه موج من فوقه سحاب ظلمات بعضها فوق بعض اذا اخرج يده لم يكد يراها ومن لم يجعل الله له نورا فما له من نور',
    'أَوۡ كَظُلُمَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>ِى بَحۡ<rule class=idgham_wo_ghunnah>رٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ُّجِّ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>ي</rule>َغۡشَ<rule class=madda_normal>ـٰ</rule>هُ مَوۡ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِه<rule class=madda_normal>ِۦ</rule> مَوۡ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِه<rule class=madda_normal>ِۦ</rule> سَحَا<rule class=ikhafa>بٌ‌ۚ</rule> <rule class=ikhafa>ظ</rule>ُلُمَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تُۢ</rule> <rule class=iqlab>ب</rule>َعۡضُهَا فَوۡقَ بَعۡضٍ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡرَجَ يَدَهُ<rule class=madda_normal>ۥ</rule> لَمۡ يَكَ<rule class=qalaqah>دۡ</rule> يَرَ<rule class=madda_normal>ٮٰ</rule>هَا‌ۗ وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَ<rule class=qalaqah>جۡ</rule>عَلِ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُ<rule class=madda_normal>ۥ</rule> نُو<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َمَا لَهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ّ<rule class=madda_permissible>ُو</rule>رٍ ٤٠',
    40, 18, 4, 355, 305, 142, 'false'
  );
  
  -- Ayah 41 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2832,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ یُسَبِّحُ لَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَٱلطَّیۡرُ صَـٰۤفَّـٰتࣲۖ كُلࣱّ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِیحَهُۥۗ وَٱللَّهُ عَلِیمُۢ بِمَا یَفۡعَلُونَ',
    'الم تر ان الله يسبح له من في السماوات والارض والطير صافات كل قد علم صلاته وتسبيحه والله عليم بما يفعلون',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُسَبِّحُ لَهُ<rule class=madda_normal>ۥ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرُ صَ<rule class=madda_necessary>ـٰٓ</rule>فَّ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ‌ۖ</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>لٌّ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> عَلِمَ صَلَاتَهُ<rule class=madda_normal>ۥ</rule> وَتَسۡبِيحَهُ<rule class=madda_normal>ۥ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِمَا يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 18, 4, 355, 306, 142, 'false'
  );
  
  -- Ayah 42 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2833,
    'وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ وَإِلَى ٱللَّهِ ٱلۡمَصِیرُ',
    'ولله ملك السماوات والارض والى الله المصير',
    'وَلِلَّهِ مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٤٢',
    42, 18, 4, 355, 306, 142, 'false'
  );
  
  -- Ayah 43 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2834,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ یُزۡجِی سَحَابࣰا ثُمَّ یُؤَلِّفُ بَیۡنَهُۥ ثُمَّ یَجۡعَلُهُۥ رُكَامࣰا فَتَرَى ٱلۡوَدۡقَ یَخۡرُجُ مِنۡ خِلَـٰلِهِۦ وَیُنَزِّلُ مِنَ ٱلسَّمَاۤءِ مِن جِبَالࣲ فِیهَا مِنۢ بَرَدࣲ فَیُصِیبُ بِهِۦ مَن یَشَاۤءُ وَیَصۡرِفُهُۥ عَن مَّن یَشَاۤءُۖ یَكَادُ سَنَا بَرۡقِهِۦ یَذۡهَبُ بِٱلۡأَبۡصَـٰرِ',
    'الم تر ان الله يزجي سحابا ثم يؤلف بينه ثم يجعله ركاما فترى الودق يخرج من خلاله وينزل من السماء من جبال فيها من برد فيصيب به من يشاء ويصرفه عن من يشاء يكاد سنا برقه يذهب بالابصار',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُزۡجِى سَحَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ يُؤَلِّفُ بَيۡنَهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ يَ<rule class=qalaqah>جۡ</rule>عَلُهُ<rule class=madda_normal>ۥ</rule> رُكَا<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َتَرَى <rule class=ham_wasl>ٱ</rule>لۡوَ<rule class=qalaqah>دۡ</rule>قَ يَخۡرُجُ مِنۡ خِلَ<rule class=madda_normal>ـٰ</rule>لِه<rule class=madda_normal>ِۦ</rule> وَيُنَزِّلُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>ِبَا<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>ِيهَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َرَ<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>َيُصِيبُ بِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَصۡرِفُهُ<rule class=madda_normal>ۥ</rule> ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ يَكَادُ سَنَا بَرۡقِه<rule class=madda_normal>ِۦ</rule> يَذۡهَبُ بِ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_permissible>ـٰ</rule>رِ ٤٣',
    43, 18, 4, 355, 306, 142, 'false'
  );
  
  -- Ayah 44 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2835,
    'یُقَلِّبُ ٱللَّهُ ٱلَّیۡلَ وَٱلنَّهَارَۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَعِبۡرَةࣰ لِّأُو۟لِی ٱلۡأَبۡصَـٰرِ',
    'يقلب الله الليل والنهار ان في ذلك لعبرة لاولي الابصار',
    'يُقَلِّبُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَعِ<rule class=qalaqah>بۡ</rule>رَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_permissible>ـٰ</rule>رِ ٤٤',
    44, 18, 4, 356, 306, 142, 'false'
  );
  
  -- Ayah 45 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2836,
    'وَٱللَّهُ خَلَقَ كُلَّ دَاۤبَّةࣲ مِّن مَّاۤءࣲۖ فَمِنۡهُم مَّن یَمۡشِی عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن یَمۡشِی عَلَىٰ رِجۡلَیۡنِ وَمِنۡهُم مَّن یَمۡشِی عَلَىٰۤ أَرۡبَعࣲۚ یَخۡلُقُ ٱللَّهُ مَا یَشَاۤءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'والله خلق كل دابة من ماء فمنهم من يمشي على بطنه ومنهم من يمشي على رجلين ومنهم من يمشي على اربع يخلق الله ما يشاء ان الله على كل شيء قدير',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَلَقَ كُلَّ د<rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡشِى عَلَىٰ بَ<rule class=qalaqah>طۡ</rule>نِه<rule class=madda_normal>ِۦ</rule> وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡشِى عَلَىٰ رِ<rule class=qalaqah>جۡ</rule>لَيۡنِ وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡشِى عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَرۡبَ<rule class=idgham_ghunnah>عٍ‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>َخۡلُقُ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٤٥',
    45, 18, 4, 356, 306, 142, 'false'
  );
  
  -- Ayah 46 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2837,
    'لَّقَدۡ أَنزَلۡنَاۤ ءَایَـٰتࣲ مُّبَیِّنَـٰتࣲۚ وَٱللَّهُ یَهۡدِی مَن یَشَاۤءُ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'لقد انزلنا ايات مبينات والله يهدي من يشاء الى صراط مستقيم',
    'لَّقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّبَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ يَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٤٦',
    46, 18, 4, 356, 306, 142, 'false'
  );
  
  -- Ayah 47 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2838,
    'وَیَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ یَتَوَلَّىٰ فَرِیقࣱ مِّنۡهُم مِّنۢ بَعۡدِ ذَ ٰ⁠لِكَۚ وَمَاۤ أُو۟لَـٰۤىِٕكَ بِٱلۡمُؤۡمِنِینَ',
    'ويقولون امنا بالله وبالرسول واطعنا ثم يتولى فريق منهم من بعد ذلك وما اولئك بالمؤمنين',
    'وَيَقُولُونَ ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَبِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ وَأَطَعۡنَا ثُ<rule class=ghunnah>مّ</rule>َ يَتَوَلَّىٰ فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ بِ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 18, 4, 356, 306, 142, 'false'
  );
  
  -- Ayah 48 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2839,
    'وَإِذَا دُعُوۤا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِیَحۡكُمَ بَیۡنَهُمۡ إِذَا فَرِیقࣱ مِّنۡهُم مُّعۡرِضُونَ',
    'واذا دعوا الى الله ورسوله ليحكم بينهم اذا فريق منهم معرضون',
    'وَإِذَا دُع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 18, 4, 356, 306, 142, 'false'
  );
  
  -- Ayah 49 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2840,
    'وَإِن یَكُن لَّهُمُ ٱلۡحَقُّ یَأۡتُوۤا۟ إِلَیۡهِ مُذۡعِنِینَ',
    'وان يكن لهم الحق ياتوا اليه مذعنين',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ يَأۡت<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِ مُذۡعِن<rule class=madda_permissible>ِي</rule>نَ ٤٩',
    49, 18, 4, 356, 306, 142, 'false'
  );
  
  -- Ayah 50 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2841,
    'أَفِی قُلُوبِهِم مَّرَضٌ أَمِ ٱرۡتَابُوۤا۟ أَمۡ یَخَافُونَ أَن یَحِیفَ ٱللَّهُ عَلَیۡهِمۡ وَرَسُولُهُۥۚ بَلۡ أُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ',
    'افي قلوبهم مرض ام ارتابوا ام يخافون ان يحيف الله عليهم ورسوله بل اولئك هم الظالمون',
    'أَفِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَضٌ أَمِ <rule class=ham_wasl>ٱ</rule>رۡتَاب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡ يَخَافُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َحِيفَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمۡ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule>‌ۚ بَلۡ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 18, 4, 356, 306, 142, 'false'
  );
  
  -- Ayah 51 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2842,
    'إِنَّمَا كَانَ قَوۡلَ ٱلۡمُؤۡمِنِینَ إِذَا دُعُوۤا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِیَحۡكُمَ بَیۡنَهُمۡ أَن یَقُولُوا۟ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'انما كان قول المؤمنين اذا دعوا الى الله ورسوله ليحكم بينهم ان يقولوا سمعنا واطعنا واولئك هم المفلحون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا كَانَ قَوۡلَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ إِذَا دُع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> لِيَحۡكُمَ بَيۡنَهُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُو<rule class=slnt>اۡ</rule> سَمِعۡنَا وَأَطَعۡنَا‌ۚ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 18, 4, 356, 307, 142, 'false'
  );
  
  -- Ayah 52 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2843,
    'وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَیَخۡشَ ٱللَّهَ وَیَتَّقۡهِ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَاۤىِٕزُونَ',
    'ومن يطع الله ورسوله ويخش الله ويتقه فاولئك هم الفائزون',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُطِعِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> وَيَخۡشَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَيَتَّ<rule class=qalaqah>قۡ</rule>هِ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡف<rule class=madda_obligatory_mottasel>َا</rule>ٓئِز<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 18, 4, 356, 307, 142, 'false'
  );
  
  -- Ayah 53 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2844,
    '۞ وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَىِٕنۡ أَمَرۡتَهُمۡ لَیَخۡرُجُنَّۖ قُل لَّا تُقۡسِمُوا۟ۖ طَاعَةࣱ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا تَعۡمَلُونَ',
    'واقسموا بالله جهد ايمانهم لئن امرتهم ليخرجن قل لا تقسموا طاعة معروفة ان الله خبير بما تعملون',
    '۞وَأَ<rule class=qalaqah>قۡ</rule>سَمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ جَهۡدَ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُ<rule class=ghunnah>نّ</rule>َ‌ۖ قُل لَّا تُ<rule class=qalaqah>قۡ</rule>سِمُو<rule class=slnt>اۡ‌ۖ</rule> طَاعَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُوفَةٌ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 18, 4, 356, 307, 143, 'false'
  );
  
  -- Ayah 54 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2845,
    'قُلۡ أَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡا۟ فَإِنَّمَا عَلَیۡهِ مَا حُمِّلَ وَعَلَیۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِیعُوهُ تَهۡتَدُوا۟ۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ',
    'قل اطيعوا الله واطيعوا الرسول فان تولوا فانما عليه ما حمل وعليكم ما حملتم وان تطيعوه تهتدوا وما على الرسول الا البلاغ المبين',
    'قُلۡ أَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡ<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َمَا عَلَيۡهِ مَا حُ<rule class=ghunnah>مّ</rule>ِلَ وَعَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا حُ<rule class=ghunnah>مّ</rule>ِلۡتُمۡ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُطِيعُوهُ تَهۡتَدُو<rule class=slnt>اۡ‌ۚ</rule> وَمَا عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ٥٤',
    54, 18, 4, 357, 307, 143, 'false'
  );
  
  -- Ayah 55 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2846,
    'وَعَدَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَیَسۡتَخۡلِفَنَّهُمۡ فِی ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِینَ مِن قَبۡلِهِمۡ وَلَیُمَكِّنَنَّ لَهُمۡ دِینَهُمُ ٱلَّذِی ٱرۡتَضَىٰ لَهُمۡ وَلَیُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنࣰاۚ یَعۡبُدُونَنِی لَا یُشۡرِكُونَ بِی شَیۡـࣰٔاۚ وَمَن كَفَرَ بَعۡدَ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ',
    'وعد الله الذين امنوا منكم وعملوا الصالحات ليستخلفنهم في الارض كما استخلف الذين من قبلهم وليمكنن لهم دينهم الذي ارتضى لهم وليبدلنهم من بعد خوفهم امنا يعبدونني لا يشركون بي شيئا ومن كفر بعد ذلك فاولئك هم الفاسقون',
    'وَعَدَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَيَسۡتَخۡلِفَ<rule class=ghunnah>نّ</rule>َهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ كَمَا <rule class=ham_wasl>ٱ</rule>سۡتَخۡلَفَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ وَلَيُمَكِّنَ<rule class=ghunnah>نّ</rule>َ لَهُمۡ دِينَهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى <rule class=ham_wasl>ٱ</rule>رۡتَضَىٰ لَهُمۡ وَلَيُبَدِّلَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ خَوۡفِهِمۡ أَمۡ<rule class=idgham_ghunnah>نًا‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡبُدُونَنِى لَا يُشۡرِكُونَ بِى شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ بَعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 18, 4, 357, 307, 143, 'false'
  );
  
  -- Ayah 56 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2847,
    'وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِیعُوا۟ ٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ',
    'واقيموا الصلاة واتوا الزكاة واطيعوا الرسول لعلكم ترحمون',
    'وَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ لَعَلَّكُمۡ تُرۡحَم<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 18, 4, 357, 307, 143, 'false'
  );
  
  -- Ayah 57 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2848,
    'لَا تَحۡسَبَنَّ ٱلَّذِینَ كَفَرُوا۟ مُعۡجِزِینَ فِی ٱلۡأَرۡضِۚ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِیرُ',
    'لا تحسبن الذين كفروا معجزين في الارض وماواهم النار ولبئس المصير',
    'لَا تَحۡسَبَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مُعۡجِزِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ‌ۖ وَلَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٥٧',
    57, 18, 4, 357, 307, 143, 'false'
  );
  
  -- Ayah 58 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2849,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لِیَسۡتَـٔۡذِنكُمُ ٱلَّذِینَ مَلَكَتۡ أَیۡمَـٰنُكُمۡ وَٱلَّذِینَ لَمۡ یَبۡلُغُوا۟ ٱلۡحُلُمَ مِنكُمۡ ثَلَـٰثَ مَرَّ ٰ⁠تࣲۚ مِّن قَبۡلِ صَلَوٰةِ ٱلۡفَجۡرِ وَحِینَ تَضَعُونَ ثِیَابَكُم مِّنَ ٱلظَّهِیرَةِ وَمِنۢ بَعۡدِ صَلَوٰةِ ٱلۡعِشَاۤءِۚ ثَلَـٰثُ عَوۡرَ ٰ⁠تࣲ لَّكُمۡۚ لَیۡسَ عَلَیۡكُمۡ وَلَا عَلَیۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّ ٰ⁠فُونَ عَلَیۡكُم بَعۡضُكُمۡ عَلَىٰ بَعۡضࣲۚ كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'يا ايها الذين امنوا ليستاذنكم الذين ملكت ايمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات من قبل صلاة الفجر وحين تضعون ثيابكم من الظهيرة ومن بعد صلاة العشاء ثلاث عورات لكم ليس عليكم ولا عليهم جناح بعدهن طوافون عليكم بعضكم على بعض كذلك يبين الله لكم الايات والله عليم حكيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لِيَسۡتَــٔۡذِ<rule class=ikhafa>نك</rule>ُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُكُمۡ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَمۡ يَ<rule class=qalaqah>بۡ</rule>لُغُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحُلُمَ مِ<rule class=ikhafa>نك</rule>ُمۡ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَ مَرّ<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٍ‌ۚ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ صَلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=qalaqah>جۡ</rule>رِ وَحِينَ تَضَعُونَ ثِيَابَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّهِيرَةِ وَم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ صَلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule>لۡعِش<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ ثَلَ<rule class=madda_normal>ـٰ</rule>ثُ عَوۡر<rule class=madda_normal>ٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ‌ۚ لَيۡسَ عَلَيۡكُمۡ وَلَا عَلَيۡهِمۡ جُنَا<rule class=iqlab>حُۢ</rule> <rule class=iqlab>ب</rule>َعۡدَهُ<rule class=ghunnah>نّ</rule>َ‌ۚ طَوّ<rule class=madda_normal>ٰ</rule>فُونَ عَلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضُكُمۡ عَلَىٰ بَعۡ<rule class=ikhafa>ضٍ‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٥٨',
    58, 18, 4, 357, 308, 143, 'false'
  );
  
  -- Ayah 59 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2850,
    'وَإِذَا بَلَغَ ٱلۡأَطۡفَـٰلُ مِنكُمُ ٱلۡحُلُمَ فَلۡیَسۡتَـٔۡذِنُوا۟ كَمَا ٱسۡتَـٔۡذَنَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ لَكُمۡ ءَایَـٰتِهِۦۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'واذا بلغ الاطفال منكم الحلم فليستاذنوا كما استاذن الذين من قبلهم كذلك يبين الله لكم اياته والله عليم حكيم',
    'وَإِذَا بَلَغَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>طۡ</rule>فَ<rule class=madda_normal>ـٰ</rule>لُ مِ<rule class=ikhafa>نك</rule>ُمُ <rule class=ham_wasl>ٱ</rule>لۡحُلُمَ فَلۡيَسۡتَــٔۡذِنُو<rule class=slnt>اۡ</rule> كَمَا <rule class=ham_wasl>ٱ</rule>سۡتَــٔۡذَنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٥٩',
    59, 18, 4, 358, 308, 143, 'false'
  );
  
  -- Ayah 60 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2851,
    'وَٱلۡقَوَ ٰ⁠عِدُ مِنَ ٱلنِّسَاۤءِ ٱلَّـٰتِی لَا یَرۡجُونَ نِكَاحࣰا فَلَیۡسَ عَلَیۡهِنَّ جُنَاحٌ أَن یَضَعۡنَ ثِیَابَهُنَّ غَیۡرَ مُتَبَرِّجَـٰتِۭ بِزِینَةࣲۖ وَأَن یَسۡتَعۡفِفۡنَ خَیۡرࣱ لَّهُنَّۗ وَٱللَّهُ سَمِیعٌ عَلِیمࣱ',
    'والقواعد من النساء اللاتي لا يرجون نكاحا فليس عليهن جناح ان يضعن ثيابهن غير متبرجات بزينة وان يستعففن خير لهن والله سميع عليم',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡقَو<rule class=madda_normal>ٰ</rule>عِدُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>تِى لَا يَرۡجُونَ نِكَا<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َلَيۡسَ عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ جُنَاحٌ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضَعۡنَ ثِيَابَهُ<rule class=ghunnah>نّ</rule>َ غَيۡرَ مُتَبَرِّجَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>ِزِينَ<rule class=idgham_ghunnah>ةٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَعۡفِفۡنَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=ghunnah>نّ</rule>َ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٦٠',
    60, 18, 4, 358, 308, 143, 'false'
  );
  
  -- Ayah 61 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2852,
    'لَّیۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجࣱ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجࣱ وَلَا عَلَى ٱلۡمَرِیضِ حَرَجࣱ وَلَا عَلَىٰۤ أَنفُسِكُمۡ أَن تَأۡكُلُوا۟ مِنۢ بُیُوتِكُمۡ أَوۡ بُیُوتِ ءَابَاۤىِٕكُمۡ أَوۡ بُیُوتِ أُمَّهَـٰتِكُمۡ أَوۡ بُیُوتِ إِخۡوَ ٰ⁠نِكُمۡ أَوۡ بُیُوتِ أَخَوَ ٰ⁠تِكُمۡ أَوۡ بُیُوتِ أَعۡمَـٰمِكُمۡ أَوۡ بُیُوتِ عَمَّـٰتِكُمۡ أَوۡ بُیُوتِ أَخۡوَ ٰ⁠لِكُمۡ أَوۡ بُیُوتِ خَـٰلَـٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥۤ أَوۡ صَدِیقِكُمۡۚ لَیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَن تَأۡكُلُوا۟ جَمِیعًا أَوۡ أَشۡتَاتࣰاۚ فَإِذَا دَخَلۡتُم بُیُوتࣰا فَسَلِّمُوا۟ عَلَىٰۤ أَنفُسِكُمۡ تَحِیَّةࣰ مِّنۡ عِندِ ٱللَّهِ مُبَـٰرَكَةࣰ طَیِّبَةࣰۚ كَذَ ٰ⁠لِكَ یُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ',
    'ليس على الاعمى حرج ولا على الاعرج حرج ولا على المريض حرج ولا على انفسكم ان تاكلوا من بيوتكم او بيوت ابائكم او بيوت امهاتكم او بيوت اخوانكم او بيوت اخواتكم او بيوت اعمامكم او بيوت عماتكم او بيوت اخوالكم او بيوت خالاتكم او ما ملكتم مفاتحه او صديقكم ليس عليكم جناح ان تاكلوا جميعا او اشتاتا فاذا دخلتم بيوتا فسلموا على انفسكم تحية من عند الله مباركة طيبة كذلك يبين الله لكم الايات لعلكم تعقلون',
    'لَّيۡسَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَعۡمَىٰ حَرَ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَجِ حَرَ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمَرِيضِ حَرَ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡكُلُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ُيُوتِكُمۡ أَوۡ بُيُوتِ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ أَوۡ بُيُوتِ أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ أَوۡ بُيُوتِ إِخۡو<rule class=madda_normal>ٰ</rule>نِكُمۡ أَوۡ بُيُوتِ أَخَو<rule class=madda_normal>ٰ</rule>تِكُمۡ أَوۡ بُيُوتِ أَعۡمَ<rule class=madda_normal>ـٰ</rule>مِكُمۡ أَوۡ بُيُوتِ عَ<rule class=ghunnah>مّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِكُمۡ أَوۡ بُيُوتِ أَخۡو<rule class=madda_normal>ٰ</rule>لِكُمۡ أَوۡ بُيُوتِ خَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ أَوۡ مَا مَلَكۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّفَاتِحَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَوۡ صَدِيقِكُمۡ‌ۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡكُلُو<rule class=slnt>اۡ</rule> جَمِيعًا أَوۡ أَشۡتَا<rule class=ikhafa>تًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِذَا دَخَلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ُيُو<rule class=ikhafa>تًا</rule> <rule class=ikhafa>ف</rule>َسَلِّمُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ تَحِيَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ مُبَ<rule class=madda_normal>ـٰ</rule>رَكَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ يُبَيِّنُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لَعَلَّكُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 18, 4, 358, 308, 143, 'false'
  );
  
  -- Ayah 62 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2853,
    'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰۤ أَمۡرࣲ جَامِعࣲ لَّمۡ یَذۡهَبُوا۟ حَتَّىٰ یَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِینَ یَسۡتَـٔۡذِنُونَكَ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ یُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ فَإِذَا ٱسۡتَـٔۡذَنُوكَ لِبَعۡضِ شَأۡنِهِمۡ فَأۡذَن لِّمَن شِئۡتَ مِنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'انما المؤمنون الذين امنوا بالله ورسوله واذا كانوا معه على امر جامع لم يذهبوا حتى يستاذنوه ان الذين يستاذنونك اولئك الذين يؤمنون بالله ورسوله فاذا استاذنوك لبعض شانهم فاذن لمن شئت منهم واستغفر لهم الله ان الله غفور رحيم',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَإِذَا كَانُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ج</rule>َامِ<rule class=idgham_wo_ghunnah>عٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَذۡهَبُو<rule class=slnt>اۡ</rule> حَتَّىٰ يَسۡتَــٔۡذِنُوهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَسۡتَــٔۡذِنُونَكَ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule>‌ۚ فَإِذَا <rule class=ham_wasl>ٱ</rule>سۡتَــٔۡذَنُوكَ لِبَعۡضِ شَأۡنِهِمۡ فَأۡذ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ِئۡتَ مِنۡهُمۡ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرۡ لَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٦٢',
    62, 18, 4, 359, 309, 143, 'false'
  );
  
  -- Ayah 63 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2854,
    'لَّا تَجۡعَلُوا۟ دُعَاۤءَ ٱلرَّسُولِ بَیۡنَكُمۡ كَدُعَاۤءِ بَعۡضِكُم بَعۡضࣰاۚ قَدۡ یَعۡلَمُ ٱللَّهُ ٱلَّذِینَ یَتَسَلَّلُونَ مِنكُمۡ لِوَاذࣰاۚ فَلۡیَحۡذَرِ ٱلَّذِینَ یُخَالِفُونَ عَنۡ أَمۡرِهِۦۤ أَن تُصِیبَهُمۡ فِتۡنَةٌ أَوۡ یُصِیبَهُمۡ عَذَابٌ أَلِیمٌ',
    'لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا قد يعلم الله الذين يتسللون منكم لواذا فليحذر الذين يخالفون عن امره ان تصيبهم فتنة او يصيبهم عذاب اليم',
    'لَّا تَ<rule class=qalaqah>جۡ</rule>عَلُو<rule class=slnt>اۡ</rule> دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ بَيۡنَكُمۡ كَدُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بَعۡضِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡ<rule class=ikhafa>ضًا‌ۚ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> يَعۡلَمُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَتَسَلَّلُونَ مِ<rule class=ikhafa>نك</rule>ُمۡ لِوَا<rule class=ikhafa>ذًا‌ۚ</rule> <rule class=ikhafa>ف</rule>َلۡيَحۡذَرِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُخَالِفُونَ عَنۡ أَمۡرِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِيبَهُمۡ فِتۡنَةٌ أَوۡ يُصِيبَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٦٣',
    63, 18, 4, 359, 309, 143, 'false'
  );
  
  -- Ayah 64 Surah An-Noor
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    24,
    2855,
    'أَلَاۤ إِنَّ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ قَدۡ یَعۡلَمُ مَاۤ أَنتُمۡ عَلَیۡهِ وَیَوۡمَ یُرۡجَعُونَ إِلَیۡهِ فَیُنَبِّئُهُم بِمَا عَمِلُوا۟ۗ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمُۢ',
    'الا ان لله ما في السماوات والارض قد يعلم ما انتم عليه ويوم يرجعون اليه فينبئهم بما عملوا والله بكل شيء عليم',
    'أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ قَ<rule class=qalaqah>دۡ</rule> يَعۡلَمُ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ عَلَيۡهِ وَيَوۡمَ يُرۡجَعُونَ إِلَيۡهِ فَيُنَبِّئُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا عَمِلُو<rule class=slnt>اۡ‌ۗ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مُۢ ٦٤',
    64, 18, 4, 359, 309, 143, 'false'
  );
  

-- Surah Al-Furqaan
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (25, 'سُورَةُ الفُرۡقَانِ', 'Al-Furqaan', 'The Criterion', 'Meccan', 77);

  -- Ayah 1 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2856,
    'تَبَارَكَ ٱلَّذِی نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِیَكُونَ لِلۡعَـٰلَمِینَ نَذِیرًا',
    'تبارك الذي نزل الفرقان على عبده ليكون للعالمين نذيرا',
    'تَبَارَكَ <rule class=ham_wasl>ٱ</rule>لَّذِى نَزَّلَ <rule class=ham_wasl>ٱ</rule>لۡفُرۡقَانَ عَلَىٰ عَ<rule class=qalaqah>بۡ</rule>دِه<rule class=madda_normal>ِۦ</rule> لِيَكُونَ لِلۡعَ<rule class=madda_normal>ـٰ</rule>لَمِينَ نَذِيرًا ١',
    1, 18, 4, 359, 310, 144, 'false'
  );
  
  -- Ayah 2 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2857,
    'ٱلَّذِی لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَلَمۡ یَتَّخِذۡ وَلَدࣰا وَلَمۡ یَكُن لَّهُۥ شَرِیكࣱ فِی ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَیۡءࣲ فَقَدَّرَهُۥ تَقۡدِیرࣰا',
    'الذي له ملك السماوات والارض ولم يتخذ ولدا ولم يكن له شريك في الملك وخلق كل شيء فقدره تقديرا',
    'ٱلَّذِى لَهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَمۡ يَتَّخِذۡ وَلَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> شَرِي<rule class=ikhafa>كٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡمُلۡكِ وَخَلَقَ كُلَّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َقَدَّرَهُ<rule class=madda_normal>ۥ</rule> تَ<rule class=qalaqah>قۡ</rule>دِيرًا ٢',
    2, 18, 4, 359, 310, 144, 'false'
  );
  
  -- Ayah 3 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2858,
    'وَٱتَّخَذُوا۟ مِن دُونِهِۦۤ ءَالِهَةࣰ لَّا یَخۡلُقُونَ شَیۡـࣰٔا وَهُمۡ یُخۡلَقُونَ وَلَا یَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرࣰّا وَلَا نَفۡعࣰا وَلَا یَمۡلِكُونَ مَوۡتࣰا وَلَا حَیَوٰةࣰ وَلَا نُشُورࣰا',
    'واتخذوا من دونه الهة لا يخلقون شيئا وهم يخلقون ولا يملكون لانفسهم ضرا ولا نفعا ولا يملكون موتا ولا حياة ولا نشورا',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> ءَالِهَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَخۡلُقُونَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ يُخۡلَقُونَ وَلَا يَمۡلِكُونَ لِأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ ضَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَفۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَمۡلِكُونَ مَوۡ<rule class=idgham_ghunnah>تًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا حَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا نُشُورًا ٣',
    3, 18, 4, 360, 310, 144, 'false'
  );
  
  -- Ayah 4 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2859,
    'وَقَالَ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّاۤ إِفۡكٌ ٱفۡتَرَىٰهُ وَأَعَانَهُۥ عَلَیۡهِ قَوۡمٌ ءَاخَرُونَۖ فَقَدۡ جَاۤءُو ظُلۡمࣰا وَزُورࣰا',
    'وقال الذين كفروا ان هذا الا افك افتراه واعانه عليه قوم اخرون فقد جاءوا ظلما وزورا',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِفۡكٌ <rule class=ham_wasl>ٱ</rule>فۡتَرَ<rule class=madda_normal>ٮٰ</rule>هُ وَأَعَانَهُ<rule class=madda_normal>ۥ</rule> عَلَيۡهِ قَوۡمٌ ءَاخَرُونَ‌ۖ فَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو ظُلۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َزُورًا ٤',
    4, 18, 4, 360, 310, 144, 'false'
  );
  
  -- Ayah 5 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2860,
    'وَقَالُوۤا۟ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ٱكۡتَتَبَهَا فَهِیَ تُمۡلَىٰ عَلَیۡهِ بُكۡرَةࣰ وَأَصِیلࣰا',
    'وقالوا اساطير الاولين اكتتبها فهي تملى عليه بكرة واصيلا',
    'وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّلِينَ <rule class=ham_wasl>ٱ</rule>كۡتَتَبَهَا فَهِىَ تُمۡلَىٰ عَلَيۡهِ بُكۡرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَصِيلاً ٥',
    5, 18, 4, 360, 310, 144, 'false'
  );
  
  -- Ayah 6 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2861,
    'قُلۡ أَنزَلَهُ ٱلَّذِی یَعۡلَمُ ٱلسِّرَّ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورࣰا رَّحِیمࣰا',
    'قل انزله الذي يعلم السر في السماوات والارض انه كان غفورا رحيما',
    'قُلۡ أَ<rule class=ikhafa>نز</rule>َلَهُ <rule class=ham_wasl>ٱ</rule>لَّذِى يَعۡلَمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّرَّ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٦',
    6, 18, 4, 360, 310, 144, 'false'
  );
  
  -- Ayah 7 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2862,
    'وَقَالُوا۟ مَالِ هَـٰذَا ٱلرَّسُولِ یَأۡكُلُ ٱلطَّعَامَ وَیَمۡشِی فِی ٱلۡأَسۡوَاقِ لَوۡلَاۤ أُنزِلَ إِلَیۡهِ مَلَكࣱ فَیَكُونَ مَعَهُۥ نَذِیرًا',
    'وقالوا مال هذا الرسول ياكل الطعام ويمشي في الاسواق لولا انزل اليه ملك فيكون معه نذيرا',
    'وَقَالُو<rule class=slnt>اۡ</rule> مَالِ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ يَأۡكُلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّعَامَ وَيَمۡشِى فِى <rule class=ham_wasl>ٱ</rule>لۡأَسۡوَاقِ‌ۙ لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡهِ مَلَ<rule class=ikhafa>كٌ</rule> <rule class=ikhafa>ف</rule>َيَكُونَ مَعَهُ<rule class=madda_normal>ۥ</rule> نَذِيرًا ٧',
    7, 18, 4, 360, 310, 144, 'false'
  );
  
  -- Ayah 8 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2863,
    'أَوۡ یُلۡقَىٰۤ إِلَیۡهِ كَنزٌ أَوۡ تَكُونُ لَهُۥ جَنَّةࣱ یَأۡكُلُ مِنۡهَاۚ وَقَالَ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلࣰا مَّسۡحُورًا',
    'او يلقى اليه كنز او تكون له جنة ياكل منها وقال الظالمون ان تتبعون الا رجلا مسحورا',
    'أَوۡ يُلۡقَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡهِ كَ<rule class=ikhafa>نز</rule>ٌ أَوۡ تَكُونُ لَهُ<rule class=madda_normal>ۥ</rule> جَ<rule class=ghunnah>نّ</rule>َ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡكُلُ مِنۡهَا‌ۚ وَقَالَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَّبِعُونَ إِلَّا رَجُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّسۡحُورًا ٨',
    8, 18, 4, 360, 310, 144, 'false'
  );
  
  -- Ayah 9 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2864,
    'ٱنظُرۡ كَیۡفَ ضَرَبُوا۟ لَكَ ٱلۡأَمۡثَـٰلَ فَضَلُّوا۟ فَلَا یَسۡتَطِیعُونَ سَبِیلࣰا',
    'انظر كيف ضربوا لك الامثال فضلوا فلا يستطيعون سبيلا',
    'ٱ<rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ ضَرَبُو<rule class=slnt>اۡ</rule> لَكَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡثَ<rule class=madda_normal>ـٰ</rule>لَ فَضَلُّو<rule class=slnt>اۡ</rule> فَلَا يَسۡتَطِيعُونَ سَبِيلاً ٩',
    9, 18, 4, 360, 310, 144, 'false'
  );
  
  -- Ayah 10 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2865,
    'تَبَارَكَ ٱلَّذِیۤ إِن شَاۤءَ جَعَلَ لَكَ خَیۡرࣰا مِّن ذَ ٰ⁠لِكَ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ وَیَجۡعَل لَّكَ قُصُورَۢا',
    'تبارك الذي ان شاء جعل لك خيرا من ذلك جنات تجري من تحتها الانهار ويجعل لك قصورا',
    'تَبَارَكَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ جَعَلَ لَكَ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ وَيَ<rule class=qalaqah>جۡ</rule>عَل لَّكَ قُصُورَۢا ١٠',
    10, 18, 4, 360, 311, 144, 'false'
  );
  
  -- Ayah 11 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2866,
    'بَلۡ كَذَّبُوا۟ بِٱلسَّاعَةِۖ وَأَعۡتَدۡنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِیرًا',
    'بل كذبوا بالساعة واعتدنا لمن كذب بالساعة سعيرا',
    'بَلۡ كَذَّبُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ‌ۖ وَأَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ سَعِيرًا ١١',
    11, 18, 4, 360, 311, 144, 'false'
  );
  
  -- Ayah 12 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2867,
    'إِذَا رَأَتۡهُم مِّن مَّكَانِۭ بَعِیدࣲ سَمِعُوا۟ لَهَا تَغَیُّظࣰا وَزَفِیرࣰا',
    'اذا راتهم من مكان بعيد سمعوا لها تغيظا وزفيرا',
    'إِذَا رَأَتۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=iqlab>نِۭ</rule> <rule class=iqlab>ب</rule>َعِي<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>س</rule>َمِعُو<rule class=slnt>اۡ</rule> لَهَا تَغَيُّ<rule class=idgham_ghunnah>ظًا</rule> <rule class=idgham_ghunnah>و</rule>َزَفِيرًا ١٢',
    12, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 13 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2868,
    'وَإِذَاۤ أُلۡقُوا۟ مِنۡهَا مَكَانࣰا ضَیِّقࣰا مُّقَرَّنِینَ دَعَوۡا۟ هُنَالِكَ ثُبُورࣰا',
    'واذا القوا منها مكانا ضيقا مقرنين دعوا هنالك ثبورا',
    'وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أُلۡقُو<rule class=slnt>اۡ</rule> مِنۡهَا مَكَا<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ض</rule>َيِّ<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ُّقَرَّنِينَ دَعَوۡ<rule class=slnt>اۡ</rule> هُنَالِكَ ثُبُورًا ١٣',
    13, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 14 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2869,
    'لَّا تَدۡعُوا۟ ٱلۡیَوۡمَ ثُبُورࣰا وَ ٰ⁠حِدࣰا وَٱدۡعُوا۟ ثُبُورࣰا كَثِیرࣰا',
    'لا تدعوا اليوم ثبورا واحدا وادعوا ثبورا كثيرا',
    'لَّا تَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ ثُبُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> ثُبُو<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َثِيرًا ١٤',
    14, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 15 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2870,
    'قُلۡ أَذَ ٰ⁠لِكَ خَیۡرٌ أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِی وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ لَهُمۡ جَزَاۤءࣰ وَمَصِیرࣰا',
    'قل اذلك خير ام جنة الخلد التي وعد المتقون كانت لهم جزاء ومصيرا',
    'قُلۡ أَذ<rule class=madda_normal>ٰ</rule>لِكَ خَيۡرٌ أَمۡ جَ<rule class=ghunnah>نّ</rule>َةُ <rule class=ham_wasl>ٱ</rule>لۡخُلۡدِ <rule class=ham_wasl>ٱ</rule>لَّتِى وُعِدَ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقُونَ‌ۚ كَانَتۡ لَهُمۡ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َمَصِيرًا ١٥',
    15, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 16 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2871,
    'لَّهُمۡ فِیهَا مَا یَشَاۤءُونَ خَـٰلِدِینَۚ كَانَ عَلَىٰ رَبِّكَ وَعۡدࣰا مَّسۡـُٔولࣰا',
    'لهم فيها ما يشاءون خالدين كان على ربك وعدا مسئولا',
    'لَّهُمۡ فِيهَا مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُونَ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ‌ۚ كَانَ عَلَىٰ رَبِّكَ وَعۡ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>َّسۡــُٔولاً ١٦',
    16, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 17 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2872,
    'وَیَوۡمَ یَحۡشُرُهُمۡ وَمَا یَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَیَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِی هَـٰۤؤُلَاۤءِ أَمۡ هُمۡ ضَلُّوا۟ ٱلسَّبِیلَ',
    'ويوم يحشرهم وما يعبدون من دون الله فيقول اانتم اضللتم عبادي هؤلاء ام هم ضلوا السبيل',
    'وَيَوۡمَ يَحۡشُرُهُمۡ وَمَا يَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَيَقُولُ ءَأَ<rule class=ikhafa>نت</rule>ُمۡ أَضۡلَلۡتُمۡ عِبَادِى هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَمۡ هُمۡ ضَلُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لَ ١٧',
    17, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 18 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2873,
    'قَالُوا۟ سُبۡحَـٰنَكَ مَا كَانَ یَنۢبَغِی لَنَاۤ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِیَاۤءَ وَلَـٰكِن مَّتَّعۡتَهُمۡ وَءَابَاۤءَهُمۡ حَتَّىٰ نَسُوا۟ ٱلذِّكۡرَ وَكَانُوا۟ قَوۡمَۢا بُورࣰا',
    'قالوا سبحانك ما كان ينبغي لنا ان نتخذ من دونك من اولياء ولكن متعتهم واباءهم حتى نسوا الذكر وكانوا قوما بورا',
    'قَالُو<rule class=slnt>اۡ</rule> سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ مَا كَانَ يَ<rule class=iqlab>نۢب</rule>َغِى لَن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّتَّخِذَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِكَ مِنۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّتَّعۡتَهُمۡ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ حَتَّىٰ نَسُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَ وَكَانُو<rule class=slnt>اۡ</rule> قَوۡم<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ُورًا ١٨',
    18, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 19 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2874,
    'فَقَدۡ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسۡتَطِیعُونَ صَرۡفࣰا وَلَا نَصۡرࣰاۚ وَمَن یَظۡلِم مِّنكُمۡ نُذِقۡهُ عَذَابࣰا كَبِیرࣰا',
    'فقد كذبوكم بما تقولون فما تستطيعون صرفا ولا نصرا ومن يظلم منكم نذقه عذابا كبيرا',
    'فَقَ<rule class=qalaqah>دۡ</rule> كَذَّبُوك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا تَقُولُونَ فَمَا تَسۡتَطِيعُونَ صَرۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصۡ<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َظۡل<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ نُذِ<rule class=qalaqah>قۡ</rule>هُ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ١٩',
    19, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 20 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2875,
    'وَمَاۤ أَرۡسَلۡنَا قَبۡلَكَ مِنَ ٱلۡمُرۡسَلِینَ إِلَّاۤ إِنَّهُمۡ لَیَأۡكُلُونَ ٱلطَّعَامَ وَیَمۡشُونَ فِی ٱلۡأَسۡوَاقِۗ وَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضࣲ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِیرࣰا',
    'وما ارسلنا قبلك من المرسلين الا انهم لياكلون الطعام ويمشون في الاسواق وجعلنا بعضكم لبعض فتنة اتصبرون وكان ربك بصيرا',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا قَ<rule class=qalaqah>بۡ</rule>لَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَلِينَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَيَأۡكُلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّعَامَ وَيَمۡشُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَسۡوَاقِ‌ۗ وَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ف</rule>ِتۡنَةً أَتَصۡبِرُونَ‌ۗ وَكَانَ رَبُّكَ بَصِيرًا ٢٠',
    20, 18, 4, 361, 311, 144, 'false'
  );
  
  -- Ayah 21 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2876,
    '۞ وَقَالَ ٱلَّذِینَ لَا یَرۡجُونَ لِقَاۤءَنَا لَوۡلَاۤ أُنزِلَ عَلَیۡنَا ٱلۡمَلَـٰۤىِٕكَةُ أَوۡ نَرَىٰ رَبَّنَاۗ لَقَدِ ٱسۡتَكۡبَرُوا۟ فِیۤ أَنفُسِهِمۡ وَعَتَوۡ عُتُوࣰّا كَبِیرࣰا',
    'وقال الذين لا يرجون لقاءنا لولا انزل علينا الملائكة او نرى ربنا لقد استكبروا في انفسهم وعتوا عتوا كبيرا',
    '۞وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَرۡجُونَ لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡنَا <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ أَوۡ نَرَىٰ رَبَّنَا‌ۗ لَقَدِ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ وَعَتَوۡ عُتُو<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٢١',
    21, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 22 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2877,
    'یَوۡمَ یَرَوۡنَ ٱلۡمَلَـٰۤىِٕكَةَ لَا بُشۡرَىٰ یَوۡمَىِٕذࣲ لِّلۡمُجۡرِمِینَ وَیَقُولُونَ حِجۡرࣰا مَّحۡجُورࣰا',
    'يوم يرون الملائكة لا بشرى يومئذ للمجرمين ويقولون حجرا محجورا',
    'يَوۡمَ يَرَوۡنَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةَ لَا بُشۡرَىٰ يَوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ وَيَقُولُونَ حِ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>َّحۡجُورًا ٢٢',
    22, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 23 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2878,
    'وَقَدِمۡنَاۤ إِلَىٰ مَا عَمِلُوا۟ مِنۡ عَمَلࣲ فَجَعَلۡنَـٰهُ هَبَاۤءࣰ مَّنثُورًا',
    'وقدمنا الى ما عملوا من عمل فجعلناه هباء منثورا',
    'وَقَدِمۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مَا عَمِلُو<rule class=slnt>اۡ</rule> مِنۡ عَمَ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ هَب<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=ikhafa>نث</rule>ُورًا ٢٣',
    23, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 24 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2879,
    'أَصۡحَـٰبُ ٱلۡجَنَّةِ یَوۡمَىِٕذٍ خَیۡرࣱ مُّسۡتَقَرࣰّا وَأَحۡسَنُ مَقِیلࣰا',
    'اصحاب الجنة يومئذ خير مستقرا واحسن مقيلا',
    'أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ يَوۡمَئِذٍ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َأَحۡسَنُ مَقِيلاً ٢٤',
    24, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 25 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2880,
    'وَیَوۡمَ تَشَقَّقُ ٱلسَّمَاۤءُ بِٱلۡغَمَـٰمِ وَنُزِّلَ ٱلۡمَلَـٰۤىِٕكَةُ تَنزِیلًا',
    'ويوم تشقق السماء بالغمام ونزل الملائكة تنزيلا',
    'وَيَوۡمَ تَشَقَّقُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بِ<rule class=ham_wasl>ٱ</rule>لۡغَمَ<rule class=madda_normal>ـٰ</rule>مِ وَنُزِّلَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ تَ<rule class=ikhafa>نز</rule>ِيلاً ٢٥',
    25, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 26 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2881,
    'ٱلۡمُلۡكُ یَوۡمَىِٕذٍ ٱلۡحَقُّ لِلرَّحۡمَـٰنِۚ وَكَانَ یَوۡمًا عَلَى ٱلۡكَـٰفِرِینَ عَسِیرࣰا',
    'الملك يومئذ الحق للرحمن وكان يوما على الكافرين عسيرا',
    'ٱلۡمُلۡكُ يَوۡمَئِذٍ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ وَكَانَ يَوۡمًا عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَسِيرًا ٢٦',
    26, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 27 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2882,
    'وَیَوۡمَ یَعَضُّ ٱلظَّالِمُ عَلَىٰ یَدَیۡهِ یَقُولُ یَـٰلَیۡتَنِی ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِیلࣰا',
    'ويوم يعض الظالم على يديه يقول يا ليتني اتخذت مع الرسول سبيلا',
    'وَيَوۡمَ يَعَضُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّالِمُ عَلَىٰ يَدَيۡهِ يَقُولُ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَنِى <rule class=ham_wasl>ٱ</rule>تَّخَذۡتُ مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ سَبِيلاً ٢٧',
    27, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 28 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2883,
    'یَـٰوَیۡلَتَىٰ لَیۡتَنِی لَمۡ أَتَّخِذۡ فُلَانًا خَلِیلࣰا',
    'يا ويلتى ليتني لم اتخذ فلانا خليلا',
    'يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَتَىٰ لَيۡتَنِى لَمۡ أَتَّخِذۡ فُلَانًا خَلِيلاً ٢٨',
    28, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 29 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2884,
    'لَّقَدۡ أَضَلَّنِی عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَاۤءَنِیۗ وَكَانَ ٱلشَّیۡطَـٰنُ لِلۡإِنسَـٰنِ خَذُولࣰا',
    'لقد اضلني عن الذكر بعد اذ جاءني وكان الشيطان للانسان خذولا',
    'لَّقَ<rule class=qalaqah>دۡ</rule> أَضَلَّنِى عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرِ بَعۡدَ إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنِى‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ لِلۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ خَذُولاً ٢٩',
    29, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 30 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2885,
    'وَقَالَ ٱلرَّسُولُ یَـٰرَبِّ إِنَّ قَوۡمِی ٱتَّخَذُوا۟ هَـٰذَا ٱلۡقُرۡءَانَ مَهۡجُورࣰا',
    'وقال الرسول يا رب ان قومي اتخذوا هذا القران مهجورا',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ يَ<rule class=madda_normal>ـٰ</rule>رَبِّ إِ<rule class=ghunnah>نّ</rule>َ قَوۡمِى <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ مَهۡجُورًا ٣٠',
    30, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 31 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2886,
    'وَكَذَ ٰ⁠لِكَ جَعَلۡنَا لِكُلِّ نَبِیٍّ عَدُوࣰّا مِّنَ ٱلۡمُجۡرِمِینَۗ وَكَفَىٰ بِرَبِّكَ هَادِیࣰا وَنَصِیرࣰا',
    'وكذلك جعلنا لكل نبي عدوا من المجرمين وكفى بربك هاديا ونصيرا',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ جَعَلۡنَا لِكُلِّ نَبِىٍّ عَدُو<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ‌ۗ وَكَفَىٰ بِرَبِّكَ هَادِ<rule class=idgham_ghunnah>يًا</rule> <rule class=idgham_ghunnah>و</rule>َنَصِيرًا ٣١',
    31, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 32 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2887,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَوۡلَا نُزِّلَ عَلَیۡهِ ٱلۡقُرۡءَانُ جُمۡلَةࣰ وَ ٰ⁠حِدَةࣰۚ كَذَ ٰ⁠لِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَـٰهُ تَرۡتِیلࣰا',
    'وقال الذين كفروا لولا نزل عليه القران جملة واحدة كذلك لنثبت به فؤادك ورتلناه ترتيلا',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَوۡلَا نُزِّلَ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانُ جُمۡلَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ لِنُثَبِّتَ بِه<rule class=madda_normal>ِۦ</rule> فُؤَادَكَ‌ۖ وَرَتَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُ تَرۡتِيلاً ٣٢',
    32, 19, 4, 362, 312, 145, 'false'
  );
  
  -- Ayah 33 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2888,
    'وَلَا یَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَـٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِیرًا',
    'ولا ياتونك بمثل الا جئناك بالحق واحسن تفسيرا',
    'وَلَا يَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَ<rule class=madda_normal>ـٰ</rule>كَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَأَحۡسَنَ تَفۡسِيرًا ٣٣',
    33, 19, 4, 363, 312, 145, 'false'
  );
  
  -- Ayah 34 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2889,
    'ٱلَّذِینَ یُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُو۟لَـٰۤىِٕكَ شَرࣱّ مَّكَانࣰا وَأَضَلُّ سَبِیلࣰا',
    'الذين يحشرون على وجوههم الى جهنم اولئك شر مكانا واضل سبيلا',
    'ٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَ<rule class=ghunnah>نّ</rule>َمَ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ شَ<rule class=idgham_ghunnah>رٌّ</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َأَضَلُّ سَبِيلاً ٣٤',
    34, 19, 4, 363, 312, 145, 'false'
  );
  
  -- Ayah 35 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2890,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَجَعَلۡنَا مَعَهُۥۤ أَخَاهُ هَـٰرُونَ وَزِیرࣰا',
    'ولقد اتينا موسى الكتاب وجعلنا معه اخاه هارون وزيرا',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَجَعَلۡنَا مَعَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَخَاهُ هَ<rule class=madda_normal>ـٰ</rule>رُونَ وَزِيرًا ٣٥',
    35, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 36 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2891,
    'فَقُلۡنَا ٱذۡهَبَاۤ إِلَى ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا فَدَمَّرۡنَـٰهُمۡ تَدۡمِیرࣰا',
    'فقلنا اذهبا الى القوم الذين كذبوا باياتنا فدمرناهم تدميرا',
    'فَقُلۡنَا <rule class=ham_wasl>ٱ</rule>ذۡهَب<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَدَ<rule class=ghunnah>مّ</rule>َرۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ تَ<rule class=qalaqah>دۡ</rule>مِيرًا ٣٦',
    36, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 37 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2892,
    'وَقَوۡمَ نُوحࣲ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغۡرَقۡنَـٰهُمۡ وَجَعَلۡنَـٰهُمۡ لِلنَّاسِ ءَایَةࣰۖ وَأَعۡتَدۡنَا لِلظَّـٰلِمِینَ عَذَابًا أَلِیمࣰا',
    'وقوم نوح لما كذبوا الرسل اغرقناهم وجعلناهم للناس اية واعتدنا للظالمين عذابا اليما',
    'وَقَوۡمَ نُو<rule class=idgham_wo_ghunnah>حٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ghunnah>مّ</rule>َا كَذَّبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلَ أَغۡرَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ لِل<rule class=ghunnah>نّ</rule>َاسِ ءَايَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ عَذَابًا أَلِيمًا ٣٧',
    37, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 38 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2893,
    'وَعَادࣰا وَثَمُودَا۟ وَأَصۡحَـٰبَ ٱلرَّسِّ وَقُرُونَۢا بَیۡنَ ذَ ٰ⁠لِكَ كَثِیرࣰا',
    'وعادا وثمود واصحاب الرس وقرونا بين ذلك كثيرا',
    'وَعَا<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َثَمُودَ<rule class=slnt>اۡ</rule> وَأَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسِّ وَقُرُون<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَ ذ<rule class=madda_normal>ٰ</rule>لِكَ كَثِيرًا ٣٨',
    38, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 39 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2894,
    'وَكُلࣰّا ضَرَبۡنَا لَهُ ٱلۡأَمۡثَـٰلَۖ وَكُلࣰّا تَبَّرۡنَا تَتۡبِیرࣰا',
    'وكلا ضربنا له الامثال وكلا تبرنا تتبيرا',
    'وَكُل<rule class=ikhafa>اًّ</rule> <rule class=ikhafa>ض</rule>َرَ<rule class=qalaqah>بۡ</rule>نَا لَهُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡثَ<rule class=madda_normal>ـٰ</rule>لَ‌ۖ وَكُل<rule class=ikhafa>اًّ</rule> <rule class=ikhafa>ت</rule>َبَّرۡنَا تَتۡبِيرًا ٣٩',
    39, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 40 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2895,
    'وَلَقَدۡ أَتَوۡا۟ عَلَى ٱلۡقَرۡیَةِ ٱلَّتِیۤ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ یَكُونُوا۟ یَرَوۡنَهَاۚ بَلۡ كَانُوا۟ لَا یَرۡجُونَ نُشُورࣰا',
    'ولقد اتوا على القرية التي امطرت مطر السوء افلم يكونوا يرونها بل كانوا لا يرجون نشورا',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَتَوۡ<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةِ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُمۡطِرَتۡ مَطَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّوۡءِ‌ۚ أَفَلَمۡ يَكُونُو<rule class=slnt>اۡ</rule> يَرَوۡنَهَا‌ۚ بَلۡ كَانُو<rule class=slnt>اۡ</rule> لَا يَرۡجُونَ نُشُورًا ٤٠',
    40, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 41 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2896,
    'وَإِذَا رَأَوۡكَ إِن یَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَـٰذَا ٱلَّذِی بَعَثَ ٱللَّهُ رَسُولًا',
    'واذا راوك ان يتخذونك الا هزوا اهذا الذي بعث الله رسولا',
    'وَإِذَا رَأَوۡكَ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذُونَكَ إِلَّا هُزُوًا أَهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى بَعَثَ <rule class=ham_wasl>ٱ</rule>للَّهُ رَسُولاً ٤١',
    41, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 42 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2897,
    'إِن كَادَ لَیُضِلُّنَا عَنۡ ءَالِهَتِنَا لَوۡلَاۤ أَن صَبَرۡنَا عَلَیۡهَاۚ وَسَوۡفَ یَعۡلَمُونَ حِینَ یَرَوۡنَ ٱلۡعَذَابَ مَنۡ أَضَلُّ سَبِیلًا',
    'ان كاد ليضلنا عن الهتنا لولا ان صبرنا عليها وسوف يعلمون حين يرون العذاب من اضل سبيلا',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َادَ لَيُضِلُّنَا عَنۡ ءَالِهَتِنَا لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َبَرۡنَا عَلَيۡهَا‌ۚ وَسَوۡفَ يَعۡلَمُونَ حِينَ يَرَوۡنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ مَنۡ أَضَلُّ سَبِيلاً ٤٢',
    42, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 43 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2898,
    'أَرَءَیۡتَ مَنِ ٱتَّخَذَ إِلَـٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَیۡهِ وَكِیلًا',
    'ارايت من اتخذ الهه هواه افانت تكون عليه وكيلا',
    'أَرَءَيۡتَ مَنِ <rule class=ham_wasl>ٱ</rule>تَّخَذَ إِلَ<rule class=madda_normal>ـٰ</rule>هَهُ<rule class=madda_normal>ۥ</rule> هَوَ<rule class=madda_normal>ٮٰ</rule>هُ أَفَأَ<rule class=ikhafa>نت</rule>َ تَكُونُ عَلَيۡهِ وَكِيلاً ٤٣',
    43, 19, 4, 363, 313, 145, 'false'
  );
  
  -- Ayah 44 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2899,
    'أَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ یَسۡمَعُونَ أَوۡ یَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَـٰمِ بَلۡ هُمۡ أَضَلُّ سَبِیلًا',
    'ام تحسب ان اكثرهم يسمعون او يعقلون ان هم الا كالانعام بل هم اضل سبيلا',
    'أَمۡ تَحۡسَبُ أَ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَ‌ۚ إِنۡ هُمۡ إِلَّا كَ<rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ‌ۖ بَلۡ هُمۡ أَضَلُّ سَبِيلاً ٤٤',
    44, 19, 4, 364, 313, 145, 'false'
  );
  
  -- Ayah 45 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2900,
    'أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَیۡفَ مَدَّ ٱلظِّلَّ وَلَوۡ شَاۤءَ لَجَعَلَهُۥ سَاكِنࣰا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَیۡهِ دَلِیلࣰا',
    'الم تر الى ربك كيف مد الظل ولو شاء لجعله ساكنا ثم جعلنا الشمس عليه دليلا',
    'أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظِّلَّ وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لَجَعَلَهُ<rule class=madda_normal>ۥ</rule> سَاكِ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ جَعَلۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ عَلَيۡهِ دَلِيلاً ٤٥',
    45, 19, 4, 364, 314, 145, 'false'
  );
  
  -- Ayah 46 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2901,
    'ثُمَّ قَبَضۡنَـٰهُ إِلَیۡنَا قَبۡضࣰا یَسِیرࣰا',
    'ثم قبضناه الينا قبضا يسيرا',
    'ثُ<rule class=ghunnah>مّ</rule>َ قَبَضۡنَ<rule class=madda_normal>ـٰ</rule>هُ إِلَيۡنَا قَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>ضًا</rule> <rule class=idgham_ghunnah>ي</rule>َسِيرًا ٤٦',
    46, 19, 4, 364, 314, 145, 'false'
  );
  
  -- Ayah 47 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2902,
    'وَهُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلَّیۡلَ لِبَاسࣰا وَٱلنَّوۡمَ سُبَاتࣰا وَجَعَلَ ٱلنَّهَارَ نُشُورࣰا',
    'وهو الذي جعل لكم الليل لباسا والنوم سباتا وجعل النهار نشورا',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ لِبَا<rule class=idgham_ghunnah>سًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َوۡمَ سُبَا<rule class=idgham_ghunnah>تًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ نُشُورًا ٤٧',
    47, 19, 4, 364, 314, 145, 'false'
  );
  
  -- Ayah 48 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2903,
    'وَهُوَ ٱلَّذِیۤ أَرۡسَلَ ٱلرِّیَـٰحَ بُشۡرَۢا بَیۡنَ یَدَیۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ طَهُورࣰا',
    'وهو الذي ارسل الرياح بشرا بين يدي رحمته وانزلنا من السماء ماء طهورا',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡسَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حَ بُشۡر<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَ يَدَىۡ رَحۡمَتِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَأَ<rule class=ikhafa>نز</rule>َلۡنَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ط</rule>َهُورًا ٤٨',
    48, 19, 4, 364, 314, 145, 'false'
  );
  
  -- Ayah 49 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2904,
    'لِّنُحۡـِۧیَ بِهِۦ بَلۡدَةࣰ مَّیۡتࣰا وَنُسۡقِیَهُۥ مِمَّا خَلَقۡنَاۤ أَنۡعَـٰمࣰا وَأَنَاسِیَّ كَثِیرࣰا',
    'لنحيي به بلدة ميتا ونسقيه مما خلقنا انعاما واناسي كثيرا',
    'لِّنُحۡــِۧىَ بِه<rule class=madda_normal>ِۦ</rule> بَلۡدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>َّيۡ<rule class=idgham_ghunnah>تًا</rule> <rule class=idgham_ghunnah>و</rule>َنُسۡقِيَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ghunnah>مّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡعَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َأَنَاسِىَّ كَثِيرًا ٤٩',
    49, 19, 4, 364, 314, 145, 'false'
  );
  
  -- Ayah 50 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2905,
    'وَلَقَدۡ صَرَّفۡنَـٰهُ بَیۡنَهُمۡ لِیَذَّكَّرُوا۟ فَأَبَىٰۤ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورࣰا',
    'ولقد صرفناه بينهم ليذكروا فابى اكثر الناس الا كفورا',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> صَرَّفۡنَ<rule class=madda_normal>ـٰ</rule>هُ بَيۡنَهُمۡ لِيَذَّكَّرُو<rule class=slnt>اۡ</rule> فَأَبَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَكۡثَرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ إِلَّا كُفُورًا ٥٠',
    50, 19, 4, 364, 314, 145, 'false'
  );
  
  -- Ayah 51 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2906,
    'وَلَوۡ شِئۡنَا لَبَعَثۡنَا فِی كُلِّ قَرۡیَةࣲ نَّذِیرࣰا',
    'ولو شئنا لبعثنا في كل قرية نذيرا',
    'وَلَوۡ شِئۡنَا لَبَعَثۡنَا فِى كُلِّ قَرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ن</rule>َّذِيرًا ٥١',
    51, 19, 4, 364, 314, 145, 'false'
  );
  
  -- Ayah 52 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2907,
    'فَلَا تُطِعِ ٱلۡكَـٰفِرِینَ وَجَـٰهِدۡهُم بِهِۦ جِهَادࣰا كَبِیرࣰا',
    'فلا تطع الكافرين وجاهدهم به جهادا كبيرا',
    'فَلَا تُطِعِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ وَجَ<rule class=madda_normal>ـٰ</rule>هِ<rule class=qalaqah>دۡ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> جِهَا<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٥٢',
    52, 19, 4, 364, 314, 145, 'false'
  );
  
  -- Ayah 53 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2908,
    '۞ وَهُوَ ٱلَّذِی مَرَجَ ٱلۡبَحۡرَیۡنِ هَـٰذَا عَذۡبࣱ فُرَاتࣱ وَهَـٰذَا مِلۡحٌ أُجَاجࣱ وَجَعَلَ بَیۡنَهُمَا بَرۡزَخࣰا وَحِجۡرࣰا مَّحۡجُورࣰا',
    'وهو الذي مرج البحرين هذا عذب فرات وهذا ملح اجاج وجعل بينهما برزخا وحجرا محجورا',
    '۞وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى مَرَجَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَيۡنِ هَ<rule class=madda_normal>ـٰ</rule>ذَا عَذۡ<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ف</rule>ُرَا<rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>و</rule>َهَ<rule class=madda_normal>ـٰ</rule>ذَا مِلۡحٌ أُجَا<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ بَيۡنَهُمَا بَرۡزَ<rule class=idgham_ghunnah>خًا</rule> <rule class=idgham_ghunnah>و</rule>َحِ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>َّحۡجُورًا ٥٣',
    53, 19, 4, 364, 314, 146, 'false'
  );
  
  -- Ayah 54 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2909,
    'وَهُوَ ٱلَّذِی خَلَقَ مِنَ ٱلۡمَاۤءِ بَشَرࣰا فَجَعَلَهُۥ نَسَبࣰا وَصِهۡرࣰاۗ وَكَانَ رَبُّكَ قَدِیرࣰا',
    'وهو الذي خلق من الماء بشرا فجعله نسبا وصهرا وكان ربك قديرا',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بَشَ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َجَعَلَهُ<rule class=madda_normal>ۥ</rule> نَسَ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َصِهۡ<rule class=idgham_ghunnah>رًا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ رَبُّكَ قَدِيرًا ٥٤',
    54, 19, 4, 364, 314, 146, 'false'
  );
  
  -- Ayah 55 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2910,
    'وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَنفَعُهُمۡ وَلَا یَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِیرࣰا',
    'ويعبدون من دون الله ما لا ينفعهم ولا يضرهم وكان الكافر على ربه ظهيرا',
    'وَيَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَا يَ<rule class=ikhafa>نف</rule>َعُهُمۡ وَلَا يَضُرُّهُمۡ‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>لۡكَافِرُ عَلَىٰ رَبِّه<rule class=madda_normal>ِۦ</rule> ظَهِيرًا ٥٥',
    55, 19, 4, 364, 314, 146, 'false'
  );
  
  -- Ayah 56 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2911,
    'وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا مُبَشِّرࣰا وَنَذِیرࣰا',
    'وما ارسلناك الا مبشرا ونذيرا',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ إِلَّا مُبَشِّ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَذِيرًا ٥٦',
    56, 19, 4, 365, 314, 146, 'false'
  );
  
  -- Ayah 57 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2912,
    'قُلۡ مَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍ إِلَّا مَن شَاۤءَ أَن یَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِیلࣰا',
    'قل ما اسالكم عليه من اجر الا من شاء ان يتخذ الى ربه سبيلا',
    'قُلۡ م<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ مِنۡ أَ<rule class=qalaqah>جۡ</rule>رٍ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذَ إِلَىٰ رَبِّه<rule class=madda_normal>ِۦ</rule> سَبِيلاً ٥٧',
    57, 19, 4, 365, 314, 146, 'false'
  );
  
  -- Ayah 58 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2913,
    'وَتَوَكَّلۡ عَلَى ٱلۡحَیِّ ٱلَّذِی لَا یَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِیرًا',
    'وتوكل على الحي الذي لا يموت وسبح بحمده وكفى به بذنوب عباده خبيرا',
    'وَتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡحَىِّ <rule class=ham_wasl>ٱ</rule>لَّذِى لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَكَفَىٰ بِه<rule class=madda_normal>ِۦ</rule> بِذُنُوبِ عِبَادِه<rule class=madda_normal>ِۦ</rule> خَبِيرًا ٥٨',
    58, 19, 4, 365, 314, 146, 'false'
  );
  
  -- Ayah 59 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2914,
    'ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ٱلرَّحۡمَـٰنُ فَسۡـَٔلۡ بِهِۦ خَبِیرࣰا',
    'الذي خلق السماوات والارض وما بينهما في ستة ايام ثم استوى على العرش الرحمن فاسال به خبيرا',
    'ٱلَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُمَا فِى سِتَّةِ أَيَّا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ‌ۚ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ فَسۡــَٔلۡ بِه<rule class=madda_normal>ِۦ</rule> خَبِيرًا ٥٩',
    59, 19, 4, 365, 314, 146, 'false'
  );
  
  -- Ayah 60 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2915,
    'وَإِذَا قِیلَ لَهُمُ ٱسۡجُدُوا۟ لِلرَّحۡمَـٰنِ قَالُوا۟ وَمَا ٱلرَّحۡمَـٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورࣰا ۩',
    'واذا قيل لهم اسجدوا للرحمن قالوا وما الرحمن انسجد لما تامرنا وزادهم نفورا',
    'وَإِذَا قِيلَ لَهُمُ <rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ قَالُو<rule class=slnt>اۡ</rule> وَمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورًا ۩ ٦٠',
    60, 19, 4, 365, 314, 146, '{"id":8,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 61 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2916,
    'تَبَارَكَ ٱلَّذِی جَعَلَ فِی ٱلسَّمَاۤءِ بُرُوجࣰا وَجَعَلَ فِیهَا سِرَ ٰ⁠جࣰا وَقَمَرࣰا مُّنِیرࣰا',
    'تبارك الذي جعل في السماء بروجا وجعل فيها سراجا وقمرا منيرا',
    'تَبَارَكَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بُرُو<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ فِيهَا سِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َقَمَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ُّنِيرًا ٦١',
    61, 19, 4, 365, 315, 146, 'false'
  );
  
  -- Ayah 62 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2917,
    'وَهُوَ ٱلَّذِی جَعَلَ ٱلَّیۡلَ وَٱلنَّهَارَ خِلۡفَةࣰ لِّمَنۡ أَرَادَ أَن یَذَّكَّرَ أَوۡ أَرَادَ شُكُورࣰا',
    'وهو الذي جعل الليل والنهار خلفة لمن اراد ان يذكر او اراد شكورا',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ خِلۡفَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَنۡ أَرَادَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َذَّكَّرَ أَوۡ أَرَادَ شُكُورًا ٦٢',
    62, 19, 4, 365, 315, 146, 'false'
  );
  
  -- Ayah 63 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2918,
    'وَعِبَادُ ٱلرَّحۡمَـٰنِ ٱلَّذِینَ یَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنࣰا وَإِذَا خَاطَبَهُمُ ٱلۡجَـٰهِلُونَ قَالُوا۟ سَلَـٰمࣰا',
    'وعباد الرحمن الذين يمشون على الارض هونا واذا خاطبهم الجاهلون قالوا سلاما',
    'وَعِبَادُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَمۡشُونَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ هَوۡ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َإِذَا خَاطَبَهُمُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِلُونَ قَالُو<rule class=slnt>اۡ</rule> سَلَ<rule class=madda_normal>ـٰ</rule>مًا ٦٣',
    63, 19, 4, 365, 315, 146, 'false'
  );
  
  -- Ayah 64 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2919,
    'وَٱلَّذِینَ یَبِیتُونَ لِرَبِّهِمۡ سُجَّدࣰا وَقِیَـٰمࣰا',
    'والذين يبيتون لربهم سجدا وقياما',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َقِيَ<rule class=madda_normal>ـٰ</rule>مًا ٦٤',
    64, 19, 4, 365, 315, 146, 'false'
  );
  
  -- Ayah 65 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2920,
    'وَٱلَّذِینَ یَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا',
    'والذين يقولون ربنا اصرف عنا عذاب جهنم ان عذابها كان غراما',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَقُولُونَ رَبَّنَا <rule class=ham_wasl>ٱ</rule>صۡرِفۡ عَ<rule class=ghunnah>نّ</rule>َا عَذَابَ جَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ عَذَابَهَا كَانَ غَرَامًا ٦٥',
    65, 19, 4, 365, 315, 146, 'false'
  );
  
  -- Ayah 66 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2921,
    'إِنَّهَا سَاۤءَتۡ مُسۡتَقَرࣰّا وَمُقَامࣰا',
    'انها ساءت مستقرا ومقاما',
    'إِ<rule class=ghunnah>نّ</rule>َهَا س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ مُسۡتَقَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َمُقَامًا ٦٦',
    66, 19, 4, 365, 315, 146, 'false'
  );
  
  -- Ayah 67 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2922,
    'وَٱلَّذِینَ إِذَاۤ أَنفَقُوا۟ لَمۡ یُسۡرِفُوا۟ وَلَمۡ یَقۡتُرُوا۟ وَكَانَ بَیۡنَ ذَ ٰ⁠لِكَ قَوَامࣰا',
    'والذين اذا انفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قواما',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ</rule> لَمۡ يُسۡرِفُو<rule class=slnt>اۡ</rule> وَلَمۡ يَ<rule class=qalaqah>قۡ</rule>تُرُو<rule class=slnt>اۡ</rule> وَكَانَ بَيۡنَ ذ<rule class=madda_normal>ٰ</rule>لِكَ قَوَامًا ٦٧',
    67, 19, 4, 365, 315, 146, 'false'
  );
  
  -- Ayah 68 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2923,
    'وَٱلَّذِینَ لَا یَدۡعُونَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ وَلَا یَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِی حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا یَزۡنُونَۚ وَمَن یَفۡعَلۡ ذَ ٰ⁠لِكَ یَلۡقَ أَثَامࣰا',
    'والذين لا يدعون مع الله الها اخر ولا يقتلون النفس التي حرم الله الا بالحق ولا يزنون ومن يفعل ذلك يلق اثاما',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَ<rule class=qalaqah>دۡ</rule>عُونَ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ وَلَا يَ<rule class=qalaqah>قۡ</rule>تُلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َفۡسَ <rule class=ham_wasl>ٱ</rule>لَّتِى حَرَّمَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَلَا يَزۡنُونَ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلۡ ذ<rule class=madda_normal>ٰ</rule>لِكَ يَلۡقَ أَثَامًا ٦٨',
    68, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 69 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2924,
    'یُضَـٰعَفۡ لَهُ ٱلۡعَذَابُ یَوۡمَ ٱلۡقِیَـٰمَةِ وَیَخۡلُدۡ فِیهِۦ مُهَانًا',
    'يضاعف له العذاب يوم القيامة ويخلد فيه مهانا',
    'يُضَ<rule class=madda_normal>ـٰ</rule>عَفۡ لَهُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ وَيَخۡلُ<rule class=qalaqah>دۡ</rule> فِيه<rule class=madda_normal>ِۦ</rule> مُهَانًا ٦٩',
    69, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 70 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2925,
    'إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلࣰا صَـٰلِحࣰا فَأُو۟لَـٰۤىِٕكَ یُبَدِّلُ ٱللَّهُ سَیِّـَٔاتِهِمۡ حَسَنَـٰتࣲۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا',
    'الا من تاب وامن وعمل عملا صالحا فاولئك يبدل الله سيئاتهم حسنات وكان الله غفورا رحيما',
    'إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابَ وَءَامَنَ وَعَمِلَ عَمَل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ص</rule>َ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يُبَدِّلُ <rule class=ham_wasl>ٱ</rule>للَّهُ سَيِّـَٔـاتِهِمۡ حَسَنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٧٠',
    70, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 71 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2926,
    'وَمَن تَابَ وَعَمِلَ صَـٰلِحࣰا فَإِنَّهُۥ یَتُوبُ إِلَى ٱللَّهِ مَتَابࣰا',
    'ومن تاب وعمل صالحا فانه يتوب الى الله متابا',
    'وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابَ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَتُوبُ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مَتَابًا ٧١',
    71, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 72 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2927,
    'وَٱلَّذِینَ لَا یَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغۡوِ مَرُّوا۟ كِرَامࣰا',
    'والذين لا يشهدون الزور واذا مروا باللغو مروا كراما',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَشۡهَدُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زُّورَ وَإِذَا مَرُّو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّغۡوِ مَرُّو<rule class=slnt>اۡ</rule> كِرَامًا ٧٢',
    72, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 73 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2928,
    'وَٱلَّذِینَ إِذَا ذُكِّرُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ لَمۡ یَخِرُّوا۟ عَلَیۡهَا صُمࣰّا وَعُمۡیَانࣰا',
    'والذين اذا ذكروا بايات ربهم لم يخروا عليها صما وعميانا',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ إِذَا ذُكِّرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ لَمۡ يَخِرُّو<rule class=slnt>اۡ</rule> عَلَيۡهَا صُم<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َعُمۡيَانًا ٧٣',
    73, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 74 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2929,
    'وَٱلَّذِینَ یَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَ ٰ⁠جِنَا وَذُرِّیَّـٰتِنَا قُرَّةَ أَعۡیُنࣲ وَٱجۡعَلۡنَا لِلۡمُتَّقِینَ إِمَامًا',
    'والذين يقولون ربنا هب لنا من ازواجنا وذرياتنا قرة اعين واجعلنا للمتقين اماما',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَقُولُونَ رَبَّنَا هَ<rule class=qalaqah>بۡ</rule> لَنَا مِنۡ أَزۡو<rule class=madda_normal>ٰ</rule>جِنَا وَذُرِّيَّ<rule class=madda_normal>ـٰ</rule>تِنَا قُرَّةَ أَعۡيُ<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡنَا لِلۡمُتَّقِينَ إِمَامًا ٧٤',
    74, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 75 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2930,
    'أُو۟لَـٰۤىِٕكَ یُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُوا۟ وَیُلَقَّوۡنَ فِیهَا تَحِیَّةࣰ وَسَلَـٰمًا',
    'اولئك يجزون الغرفة بما صبروا ويلقون فيها تحية وسلاما',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يُ<rule class=qalaqah>جۡ</rule>زَوۡنَ <rule class=ham_wasl>ٱ</rule>لۡغُرۡفَةَ بِمَا صَبَرُو<rule class=slnt>اۡ</rule> وَيُلَقَّوۡنَ فِيهَا تَحِيَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َسَلَ<rule class=madda_normal>ـٰ</rule>مًا ٧٥',
    75, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 76 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2931,
    'خَـٰلِدِینَ فِیهَاۚ حَسُنَتۡ مُسۡتَقَرࣰّا وَمُقَامࣰا',
    'خالدين فيها حسنت مستقرا ومقاما',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ حَسُنَتۡ مُسۡتَقَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َمُقَامًا ٧٦',
    76, 19, 4, 366, 315, 146, 'false'
  );
  
  -- Ayah 77 Surah Al-Furqaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    25,
    2932,
    'قُلۡ مَا یَعۡبَؤُا۟ بِكُمۡ رَبِّی لَوۡلَا دُعَاۤؤُكُمۡۖ فَقَدۡ كَذَّبۡتُمۡ فَسَوۡفَ یَكُونُ لِزَامَۢا',
    'قل ما يعبا بكم ربي لولا دعاؤكم فقد كذبتم فسوف يكون لزاما',
    'قُلۡ مَا يَعۡبَؤُ<rule class=slnt>اۡ</rule> بِكُمۡ رَبِّى لَوۡلَا دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ‌ۖ فَقَ<rule class=qalaqah>دۡ</rule> كَذَّ<rule class=qalaqah>بۡ</rule>تُمۡ فَسَوۡفَ يَكُونُ لِزَامَۢا ٧٧',
    77, 19, 4, 366, 315, 146, 'false'
  );
  

-- Surah Ash-Shuaraa
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (26, 'سُورَةُ الشُّعَرَاءِ', 'Ash-Shuaraa', 'The Poets', 'Meccan', 227);

  -- Ayah 1 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2933,
    'طسۤمۤ',
    'طسم',
    'ط<rule class=madda_necessary>سٓ</rule><rule class=madda_necessary>مٓ</rule> ١',
    1, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 2 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2934,
    'تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡمُبِینِ',
    'تلك ايات الكتاب المبين',
    'تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نِ ٢',
    2, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 3 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2935,
    'لَعَلَّكَ بَـٰخِعࣱ نَّفۡسَكَ أَلَّا یَكُونُوا۟ مُؤۡمِنِینَ',
    'لعلك باخع نفسك الا يكونوا مؤمنين',
    'لَعَلَّكَ بَ<rule class=madda_normal>ـٰ</rule>خِ<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسَكَ أَلَّا يَكُونُو<rule class=slnt>اۡ</rule> مُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٣',
    3, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 4 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2936,
    'إِن نَّشَأۡ نُنَزِّلۡ عَلَیۡهِم مِّنَ ٱلسَّمَاۤءِ ءَایَةࣰ فَظَلَّتۡ أَعۡنَـٰقُهُمۡ لَهَا خَـٰضِعِینَ',
    'ان نشا ننزل عليهم من السماء اية فظلت اعناقهم لها خاضعين',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّشَأۡ نُنَزِّلۡ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ءَايَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َظَلَّتۡ أَعۡنَ<rule class=madda_normal>ـٰ</rule>قُهُمۡ لَهَا خَ<rule class=madda_normal>ـٰ</rule>ضِع<rule class=madda_permissible>ِي</rule>نَ ٤',
    4, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 5 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2937,
    'وَمَا یَأۡتِیهِم مِّن ذِكۡرࣲ مِّنَ ٱلرَّحۡمَـٰنِ مُحۡدَثٍ إِلَّا كَانُوا۟ عَنۡهُ مُعۡرِضِینَ',
    'وما ياتيهم من ذكر من الرحمن محدث الا كانوا عنه معرضين',
    'وَمَا يَأۡتِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ مُحۡدَثٍ إِلَّا كَانُو<rule class=slnt>اۡ</rule> عَنۡهُ مُعۡرِض<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 6 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2938,
    'فَقَدۡ كَذَّبُوا۟ فَسَیَأۡتِیهِمۡ أَنۢبَـٰۤؤُا۟ مَا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'فقد كذبوا فسياتيهم انباء ما كانوا به يستهزئون',
    'فَقَ<rule class=qalaqah>دۡ</rule> كَذَّبُو<rule class=slnt>اۡ</rule> فَسَيَأۡتِيهِمۡ أَ<rule class=iqlab>نۢب</rule>َ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> مَا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 7 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2939,
    'أَوَلَمۡ یَرَوۡا۟ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِیهَا مِن كُلِّ زَوۡجࣲ كَرِیمٍ',
    'اولم يروا الى الارض كم انبتنا فيها من كل زوج كريم',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ كَمۡ أَ<rule class=iqlab>نۢب</rule>َتۡنَا فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ زَوۡ<rule class=ikhafa>جٍ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٍ ٧',
    7, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 8 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2940,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ',
    'ان في ذلك لاية وما كان اكثرهم مؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ أَكۡثَرُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 9 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2941,
    'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ',
    'وان ربك لهو العزيز الرحيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٩',
    9, 19, 5, 367, 316, 147, 'false'
  );
  
  -- Ayah 10 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2942,
    'وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰۤ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'واذ نادى ربك موسى ان ائت القوم الظالمين',
    'وَإِذۡ نَادَىٰ رَبُّكَ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَنِ <rule class=ham_wasl>ٱ</rule>ئۡتِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 11 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2943,
    'قَوۡمَ فِرۡعَوۡنَۚ أَلَا یَتَّقُونَ',
    'قوم فرعون الا يتقون',
    'قَوۡمَ فِرۡعَوۡنَ‌ۚ أَلَا يَتَّق<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 12 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2944,
    'قَالَ رَبِّ إِنِّیۤ أَخَافُ أَن یُكَذِّبُونِ',
    'قال رب اني اخاف ان يكذبون',
    'قَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَذِّب<rule class=madda_permissible>ُو</rule>نِ ١٢',
    12, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 13 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2945,
    'وَیَضِیقُ صَدۡرِی وَلَا یَنطَلِقُ لِسَانِی فَأَرۡسِلۡ إِلَىٰ هَـٰرُونَ',
    'ويضيق صدري ولا ينطلق لساني فارسل الى هارون',
    'وَيَضِيقُ صَ<rule class=qalaqah>دۡ</rule>رِى وَلَا يَ<rule class=ikhafa>نط</rule>َلِقُ لِسَانِى فَأَرۡسِلۡ إِلَىٰ هَ<rule class=madda_normal>ـٰ</rule>ر<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 14 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2946,
    'وَلَهُمۡ عَلَیَّ ذَنۢبࣱ فَأَخَافُ أَن یَقۡتُلُونِ',
    'ولهم علي ذنب فاخاف ان يقتلون',
    'وَلَهُمۡ عَلَىَّ ذَ<rule class=iqlab>نۢب</rule><rule class=ikhafa>ٌ</rule> <rule class=ikhafa>ف</rule>َأَخَافُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>تُل<rule class=madda_permissible>ُو</rule>نِ ١٤',
    14, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 15 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2947,
    'قَالَ كَلَّاۖ فَٱذۡهَبَا بِـَٔایَـٰتِنَاۤۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ',
    'قال كلا فاذهبا باياتنا انا معكم مستمعون',
    'قَالَ كَلَّا‌ۖ فَ<rule class=ham_wasl>ٱ</rule>ذۡهَبَا بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َا مَعَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡتَمِع<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 16 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2948,
    'فَأۡتِیَا فِرۡعَوۡنَ فَقُولَاۤ إِنَّا رَسُولُ رَبِّ ٱلۡعَـٰلَمِینَ',
    'فاتيا فرعون فقولا انا رسول رب العالمين',
    'فَأۡتِيَا فِرۡعَوۡنَ فَقُول<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا رَسُولُ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٦',
    16, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 17 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2949,
    'أَنۡ أَرۡسِلۡ مَعَنَا بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ',
    'ان ارسل معنا بني اسرائيل',
    'أَنۡ أَرۡسِلۡ مَعَنَا بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓء<rule class=madda_permissible>ِي</rule>لَ ١٧',
    17, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 18 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2950,
    'قَالَ أَلَمۡ نُرَبِّكَ فِینَا وَلِیدࣰا وَلَبِثۡتَ فِینَا مِنۡ عُمُرِكَ سِنِینَ',
    'قال الم نربك فينا وليدا ولبثت فينا من عمرك سنين',
    'قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِي<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِن<rule class=madda_permissible>ِي</rule>نَ ١٨',
    18, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 19 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2951,
    'وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِی فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَـٰفِرِینَ',
    'وفعلت فعلتك التي فعلت وانت من الكافرين',
    'وَفَعَلۡتَ فَعۡلَتَكَ <rule class=ham_wasl>ٱ</rule>لَّتِى فَعَلۡتَ وَأَ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٩',
    19, 19, 5, 367, 317, 147, 'false'
  );
  
  -- Ayah 20 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2952,
    'قَالَ فَعَلۡتُهَاۤ إِذࣰا وَأَنَا۠ مِنَ ٱلضَّاۤلِّینَ',
    'قال فعلتها اذا وانا من الضالين',
    'قَالَ فَعَلۡتُه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=idgham_ghunnah>ذًا</rule> <rule class=idgham_ghunnah>و</rule>َأَنَاۡ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضّ<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 21 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2953,
    'فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ فَوَهَبَ لِی رَبِّی حُكۡمࣰا وَجَعَلَنِی مِنَ ٱلۡمُرۡسَلِینَ',
    'ففررت منكم لما خفتكم فوهب لي ربي حكما وجعلني من المرسلين',
    'فَفَرَرۡتُ مِ<rule class=ikhafa>نك</rule>ُمۡ لَ<rule class=ghunnah>مّ</rule>َا خِفۡتُكُمۡ فَوَهَبَ لِى رَبِّى حُكۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٢١',
    21, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 22 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2954,
    'وَتِلۡكَ نِعۡمَةࣱ تَمُنُّهَا عَلَیَّ أَنۡ عَبَّدتَّ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ',
    'وتلك نعمة تمنها علي ان عبدت بني اسرائيل',
    'وَتِلۡكَ نِعۡمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>َمُ<rule class=ghunnah>نّ</rule>ُهَا عَلَىَّ أَنۡ عَبَّ<rule class=idgham_mutajanisayn>د</rule>تَّ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓء<rule class=madda_permissible>ِي</rule>لَ ٢٢',
    22, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 23 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2955,
    'قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَـٰلَمِینَ',
    'قال فرعون وما رب العالمين',
    'قَالَ فِرۡعَوۡنُ وَمَا رَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٢٣',
    23, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 24 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2956,
    'قَالَ رَبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۤۖ إِن كُنتُم مُّوقِنِینَ',
    'قال رب السماوات والارض وما بينهما ان كنتم موقنين',
    'قَالَ رَبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُم<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوقِن<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 25 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2957,
    'قَالَ لِمَنۡ حَوۡلَهُۥۤ أَلَا تَسۡتَمِعُونَ',
    'قال لمن حوله الا تستمعون',
    'قَالَ لِمَنۡ حَوۡلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَلَا تَسۡتَمِع<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 26 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2958,
    'قَالَ رَبُّكُمۡ وَرَبُّ ءَابَاۤىِٕكُمُ ٱلۡأَوَّلِینَ',
    'قال ربكم ورب ابائكم الاولين',
    'قَالَ رَبُّكُمۡ وَرَبُّ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٢٦',
    26, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 27 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2959,
    'قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِیۤ أُرۡسِلَ إِلَیۡكُمۡ لَمَجۡنُونࣱ',
    'قال ان رسولكم الذي ارسل اليكم لمجنون',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َ رَسُولَكُمُ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُرۡسِلَ إِلَيۡكُمۡ لَمَ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نٌ ٢٧',
    27, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 28 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2960,
    'قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَیۡنَهُمَاۤۖ إِن كُنتُمۡ تَعۡقِلُونَ',
    'قال رب المشرق والمغرب وما بينهما ان كنتم تعقلون',
    'قَالَ رَبُّ <rule class=ham_wasl>ٱ</rule>لۡمَشۡرِقِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَغۡرِبِ وَمَا بَيۡنَهُم<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 29 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2961,
    'قَالَ لَىِٕنِ ٱتَّخَذۡتَ إِلَـٰهًا غَیۡرِی لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِینَ',
    'قال لئن اتخذت الها غيري لاجعلنك من المسجونين',
    'قَالَ لَئِنِ <rule class=ham_wasl>ٱ</rule>تَّخَذۡتَ إِلَ<rule class=madda_normal>ـٰ</rule>هًا غَيۡرِى لَأَ<rule class=qalaqah>جۡ</rule>عَلَ<rule class=ghunnah>نّ</rule>َكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجُون<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 30 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2962,
    'قَالَ أَوَلَوۡ جِئۡتُكَ بِشَیۡءࣲ مُّبِینࣲ',
    'قال اولو جئتك بشيء مبين',
    'قَالَ أَوَلَوۡ جِئۡتُكَ بِش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٣٠',
    30, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 31 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2963,
    'قَالَ فَأۡتِ بِهِۦۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'قال فات به ان كنت من الصادقين',
    'قَالَ فَأۡتِ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 32 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2964,
    'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِیَ ثُعۡبَانࣱ مُّبِینࣱ',
    'فالقى عصاه فاذا هي ثعبان مبين',
    'فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعۡبَا<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٣٢',
    32, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 33 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2965,
    'وَنَزَعَ یَدَهُۥ فَإِذَا هِیَ بَیۡضَاۤءُ لِلنَّـٰظِرِینَ',
    'ونزع يده فاذا هي بيضاء للناظرين',
    'وَنَزَعَ يَدَهُ<rule class=madda_normal>ۥ</rule> فَإِذَا هِىَ بَيۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لِل<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>ظِر<rule class=madda_permissible>ِي</rule>نَ ٣٣',
    33, 19, 5, 368, 317, 147, 'false'
  );
  
  -- Ayah 34 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2966,
    'قَالَ لِلۡمَلَإِ حَوۡلَهُۥۤ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِیمࣱ',
    'قال للملا حوله ان هذا لساحر عليم',
    'قَالَ لِلۡمَلَإِ حَوۡلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَسَ<rule class=madda_normal>ـٰ</rule>حِرٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ٣٤',
    34, 19, 5, 368, 318, 147, 'false'
  );
  
  -- Ayah 35 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2967,
    'یُرِیدُ أَن یُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ',
    'يريد ان يخرجكم من ارضكم بسحره فماذا تامرون',
    'يُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡرِجَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَرۡضِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسِحۡرِه<rule class=madda_normal>ِۦ</rule> فَمَاذَا تَأۡمُر<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 19, 5, 368, 318, 147, 'false'
  );
  
  -- Ayah 36 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2968,
    'قَالُوۤا۟ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِی ٱلۡمَدَاۤىِٕنِ حَـٰشِرِینَ',
    'قالوا ارجه واخاه وابعث في المدائن حاشرين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَرۡجِهۡ وَأَخَاهُ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>عَثۡ فِى <rule class=ham_wasl>ٱ</rule>لۡمَد<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنِ حَ<rule class=madda_normal>ـٰ</rule>شِر<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 19, 5, 368, 318, 147, 'false'
  );
  
  -- Ayah 37 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2969,
    'یَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِیمࣲ',
    'ياتوك بكل سحار عليم',
    'يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَل<rule class=madda_permissible>ِي</rule>مٍ ٣٧',
    37, 19, 5, 368, 318, 147, 'false'
  );
  
  -- Ayah 38 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2970,
    'فَجُمِعَ ٱلسَّحَرَةُ لِمِیقَـٰتِ یَوۡمࣲ مَّعۡلُومࣲ',
    'فجمع السحرة لميقات يوم معلوم',
    'فَجُمِعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَرَةُ لِمِيقَ<rule class=madda_normal>ـٰ</rule>تِ يَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡل<rule class=madda_permissible>ُو</rule>مٍ ٣٨',
    38, 19, 5, 368, 318, 147, 'false'
  );
  
  -- Ayah 39 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2971,
    'وَقِیلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ',
    'وقيل للناس هل انتم مجتمعون',
    'وَقِيلَ لِل<rule class=ghunnah>نّ</rule>َاسِ هَلۡ أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>جۡ</rule>تَمِع<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 19, 5, 368, 318, 147, 'false'
  );
  
  -- Ayah 40 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2972,
    'لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُوا۟ هُمُ ٱلۡغَـٰلِبِینَ',
    'لعلنا نتبع السحرة ان كانوا هم الغالبين',
    'لَعَلَّنَا نَتَّبِعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَرَةَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> هُمُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>لِب<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 41 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2973,
    'فَلَمَّا جَاۤءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرۡعَوۡنَ أَىِٕنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَـٰلِبِینَ',
    'فلما جاء السحرة قالوا لفرعون ائن لنا لاجرا ان كنا نحن الغالبين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَرَةُ قَالُو<rule class=slnt>اۡ</rule> لِفِرۡعَوۡنَ أَئِ<rule class=ghunnah>نّ</rule>َ لَنَا لَأَ<rule class=qalaqah>جۡ</rule>رًا إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا نَحۡنُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>لِب<rule class=madda_permissible>ِي</rule>نَ ٤١',
    41, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 42 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2974,
    'قَالَ نَعَمۡ وَإِنَّكُمۡ إِذࣰا لَّمِنَ ٱلۡمُقَرَّبِینَ',
    'قال نعم وانكم اذا لمن المقربين',
    'قَالَ نَعَمۡ وَإِ<rule class=ghunnah>نّ</rule>َكُمۡ إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمِنَ <rule class=ham_wasl>ٱ</rule>لۡمُقَرَّب<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 43 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2975,
    'قَالَ لَهُم مُّوسَىٰۤ أَلۡقُوا۟ مَاۤ أَنتُم مُّلۡقُونَ',
    'قال لهم موسى القوا ما انتم ملقون',
    'قَالَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَلۡقُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلۡق<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 44 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2976,
    'فَأَلۡقَوۡا۟ حِبَالَهُمۡ وَعِصِیَّهُمۡ وَقَالُوا۟ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَـٰلِبُونَ',
    'فالقوا حبالهم وعصيهم وقالوا بعزة فرعون انا لنحن الغالبون',
    'فَأَلۡقَوۡ<rule class=slnt>اۡ</rule> حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُو<rule class=slnt>اۡ</rule> بِعِزَّةِ فِرۡعَوۡنَ إِ<rule class=ghunnah>نّ</rule>َا لَنَحۡنُ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>لِب<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 45 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2977,
    'فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِیَ تَلۡقَفُ مَا یَأۡفِكُونَ',
    'فالقى موسى عصاه فاذا هي تلقف ما يافكون',
    'فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِىَ تَلۡقَفُ مَا يَأۡفِك<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 46 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2978,
    'فَأُلۡقِیَ ٱلسَّحَرَةُ سَـٰجِدِینَ',
    'فالقي السحرة ساجدين',
    'فَأُلۡقِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَرَةُ سَ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 47 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2979,
    'قَالُوۤا۟ ءَامَنَّا بِرَبِّ ٱلۡعَـٰلَمِینَ',
    'قالوا امنا برب العالمين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 48 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2980,
    'رَبِّ مُوسَىٰ وَهَـٰرُونَ',
    'رب موسى وهارون',
    'رَبِّ مُوسَىٰ وَهَ<rule class=madda_normal>ـٰ</rule>ر<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 49 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2981,
    'قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِیرُكُمُ ٱلَّذِی عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَیۡدِیَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَـٰفࣲ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِینَ',
    'قال امنتم له قبل ان اذن لكم انه لكبيركم الذي علمكم السحر فلسوف تعلمون لاقطعن ايديكم وارجلكم من خلاف ولاصلبنكم اجمعين',
    'قَالَ ءَامَ<rule class=ikhafa>نت</rule>ُمۡ لَهُ<rule class=madda_normal>ۥ</rule> قَ<rule class=qalaqah>بۡ</rule>لَ أَنۡ ءَاذَنَ لَكُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَكَبِيرُكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى عَلَّمَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَ‌ۚ لَأُقَطِّعَ<rule class=ghunnah>نّ</rule>َ أَيۡدِيَكُمۡ وَأَرۡجُلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَأُصَلِّبَ<rule class=ghunnah>نّ</rule>َكُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٤٩',
    49, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 50 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2982,
    'قَالُوا۟ لَا ضَیۡرَۖ إِنَّاۤ إِلَىٰ رَبِّنَا مُنقَلِبُونَ',
    'قالوا لا ضير انا الى ربنا منقلبون',
    'قَالُو<rule class=slnt>اۡ</rule> لَا ضَيۡرَ‌ۖ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ رَبِّنَا مُ<rule class=ikhafa>نق</rule>َلِب<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 51 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2983,
    'إِنَّا نَطۡمَعُ أَن یَغۡفِرَ لَنَا رَبُّنَا خَطَـٰیَـٰنَاۤ أَن كُنَّاۤ أَوَّلَ ٱلۡمُؤۡمِنِینَ',
    'انا نطمع ان يغفر لنا ربنا خطايانا ان كنا اول المؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َا نَ<rule class=qalaqah>طۡ</rule>مَعُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغۡفِرَ لَنَا رَبُّنَا خَطَ<rule class=madda_normal>ـٰ</rule>يَ<rule class=madda_normal>ـٰ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَوَّلَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٥١',
    51, 19, 5, 369, 318, 147, 'false'
  );
  
  -- Ayah 52 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2984,
    '۞ وَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنۡ أَسۡرِ بِعِبَادِیۤ إِنَّكُم مُّتَّبَعُونَ',
    'واوحينا الى موسى ان اسر بعبادي انكم متبعون',
    '۞وَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَنۡ أَسۡرِ بِعِبَاد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّتَّبَع<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 19, 5, 369, 318, 148, 'false'
  );
  
  -- Ayah 53 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2985,
    'فَأَرۡسَلَ فِرۡعَوۡنُ فِی ٱلۡمَدَاۤىِٕنِ حَـٰشِرِینَ',
    'فارسل فرعون في المدائن حاشرين',
    'فَأَرۡسَلَ فِرۡعَوۡنُ فِى <rule class=ham_wasl>ٱ</rule>لۡمَد<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنِ حَ<rule class=madda_normal>ـٰ</rule>شِر<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 19, 5, 369, 319, 148, 'false'
  );
  
  -- Ayah 54 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2986,
    'إِنَّ هَـٰۤؤُلَاۤءِ لَشِرۡذِمَةࣱ قَلِیلُونَ',
    'ان هؤلاء لشرذمة قليلون',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ لَشِرۡذِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ق</rule>َلِيل<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 19, 5, 369, 319, 148, 'false'
  );
  
  -- Ayah 55 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2987,
    'وَإِنَّهُمۡ لَنَا لَغَاۤىِٕظُونَ',
    'وانهم لنا لغائظون',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ لَنَا لَغ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِظ<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 19, 5, 369, 319, 148, 'false'
  );
  
  -- Ayah 56 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2988,
    'وَإِنَّا لَجَمِیعٌ حَـٰذِرُونَ',
    'وانا لجميع حاذرون',
    'وَإِ<rule class=ghunnah>نّ</rule>َا لَجَمِيعٌ حَ<rule class=madda_normal>ـٰ</rule>ذِر<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 19, 5, 369, 319, 148, 'false'
  );
  
  -- Ayah 57 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2989,
    'فَأَخۡرَجۡنَـٰهُم مِّن جَنَّـٰتࣲ وَعُیُونࣲ',
    'فاخرجناهم من جنات وعيون',
    'فَأَخۡرَ<rule class=qalaqah>جۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َعُي<rule class=madda_permissible>ُو</rule>نٍ ٥٧',
    57, 19, 5, 369, 319, 148, 'false'
  );
  
  -- Ayah 58 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2990,
    'وَكُنُوزࣲ وَمَقَامࣲ كَرِیمࣲ',
    'وكنوز ومقام كريم',
    'وَكُنُو<rule class=idgham_ghunnah>زٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَقَا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٍ ٥٨',
    58, 19, 5, 369, 319, 148, 'false'
  );
  
  -- Ayah 59 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2991,
    'كَذَ ٰ⁠لِكَۖ وَأَوۡرَثۡنَـٰهَا بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ',
    'كذلك واورثناها بني اسرائيل',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ وَأَوۡرَثۡنَ<rule class=madda_normal>ـٰ</rule>هَا بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓء<rule class=madda_permissible>ِي</rule>لَ ٥٩',
    59, 19, 5, 369, 319, 148, 'false'
  );
  
  -- Ayah 60 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2992,
    'فَأَتۡبَعُوهُم مُّشۡرِقِینَ',
    'فاتبعوهم مشرقين',
    'فَأَتۡبَعُوه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّشۡرِق<rule class=madda_permissible>ِي</rule>نَ ٦٠',
    60, 19, 5, 369, 319, 148, 'false'
  );
  
  -- Ayah 61 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2993,
    'فَلَمَّا تَرَ ٰ⁠ۤءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَـٰبُ مُوسَىٰۤ إِنَّا لَمُدۡرَكُونَ',
    'فلما تراءى الجمعان قال اصحاب موسى انا لمدركون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا تَر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءَا <rule class=ham_wasl>ٱ</rule>لۡجَمۡعَانِ قَالَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َا لَمُ<rule class=qalaqah>دۡ</rule>رَك<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 62 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2994,
    'قَالَ كَلَّاۤۖ إِنَّ مَعِیَ رَبِّی سَیَهۡدِینِ',
    'قال كلا ان معي ربي سيهدين',
    'قَالَ كَلّ<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َ مَعِىَ رَبِّى سَيَهۡد<rule class=madda_permissible>ِي</rule>نِ ٦٢',
    62, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 63 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2995,
    'فَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقࣲ كَٱلطَّوۡدِ ٱلۡعَظِیمِ',
    'فاوحينا الى موسى ان اضرب بعصاك البحر فانفلق فكان كل فرق كالطود العظيم',
    'فَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَنِ <rule class=ham_wasl>ٱ</rule>ضۡرِب بِّعَصَاكَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>َلَقَ فَكَانَ كُلُّ فِرۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ك</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّوۡدِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٦٣',
    63, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 64 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2996,
    'وَأَزۡلَفۡنَا ثَمَّ ٱلۡـَٔاخَرِینَ',
    'وازلفنا ثم الاخرين',
    'وَأَزۡلَفۡنَا ثَ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَخَر<rule class=madda_permissible>ِي</rule>نَ ٦٤',
    64, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 65 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2997,
    'وَأَنجَیۡنَا مُوسَىٰ وَمَن مَّعَهُۥۤ أَجۡمَعِینَ',
    'وانجينا موسى ومن معه اجمعين',
    'وَأَ<rule class=ikhafa>نج</rule>َيۡنَا مُوسَىٰ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٦٥',
    65, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 66 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2998,
    'ثُمَّ أَغۡرَقۡنَا ٱلۡـَٔاخَرِینَ',
    'ثم اغرقنا الاخرين',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَغۡرَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡأَخَر<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 67 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    2999,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ',
    'ان في ذلك لاية وما كان اكثرهم مؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ أَكۡثَرُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٦٧',
    67, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 68 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3000,
    'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ',
    'وان ربك لهو العزيز الرحيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٦٨',
    68, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 69 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3001,
    'وَٱتۡلُ عَلَیۡهِمۡ نَبَأَ إِبۡرَ ٰ⁠هِیمَ',
    'واتل عليهم نبا ابراهيم',
    'وَ<rule class=ham_wasl>ٱ</rule>تۡلُ عَلَيۡهِمۡ نَبَأَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>ه<rule class=madda_permissible>ِي</rule>مَ ٦٩',
    69, 19, 5, 370, 319, 148, 'false'
  );
  
  -- Ayah 70 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3002,
    'إِذۡ قَالَ لِأَبِیهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ',
    'اذ قال لابيه وقومه ما تعبدون',
    'إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِه<rule class=madda_normal>ِۦ</rule> مَا تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 71 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3003,
    'قَالُوا۟ نَعۡبُدُ أَصۡنَامࣰا فَنَظَلُّ لَهَا عَـٰكِفِینَ',
    'قالوا نعبد اصناما فنظل لها عاكفين',
    'قَالُو<rule class=slnt>اۡ</rule> نَعۡبُدُ أَصۡنَا<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َنَظَلُّ لَهَا عَ<rule class=madda_normal>ـٰ</rule>كِف<rule class=madda_permissible>ِي</rule>نَ ٧١',
    71, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 72 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3004,
    'قَالَ هَلۡ یَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ',
    'قال هل يسمعونكم اذ تدعون',
    'قَالَ هَلۡ يَسۡمَعُونَكُمۡ إِذۡ تَ<rule class=qalaqah>دۡ</rule>ع<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 73 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3005,
    'أَوۡ یَنفَعُونَكُمۡ أَوۡ یَضُرُّونَ',
    'او ينفعونكم او يضرون',
    'أَوۡ يَ<rule class=ikhafa>نف</rule>َعُونَكُمۡ أَوۡ يَضُرّ<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 74 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3006,
    'قَالُوا۟ بَلۡ وَجَدۡنَاۤ ءَابَاۤءَنَا كَذَ ٰ⁠لِكَ یَفۡعَلُونَ',
    'قالوا بل وجدنا اباءنا كذلك يفعلون',
    'قَالُو<rule class=slnt>اۡ</rule> بَلۡ وَجَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٧٤',
    74, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 75 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3007,
    'قَالَ أَفَرَءَیۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ',
    'قال افرايتم ما كنتم تعبدون',
    'قَالَ أَفَرَءَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 76 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3008,
    'أَنتُمۡ وَءَابَاۤؤُكُمُ ٱلۡأَقۡدَمُونَ',
    'انتم واباؤكم الاقدمون',
    'أَ<rule class=ikhafa>نت</rule>ُمۡ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>دَم<rule class=madda_permissible>ُو</rule>نَ ٧٦',
    76, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 77 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3009,
    'فَإِنَّهُمۡ عَدُوࣱّ لِّیۤ إِلَّا رَبَّ ٱلۡعَـٰلَمِینَ',
    'فانهم عدو لي الا رب العالمين',
    'فَإِ<rule class=ghunnah>نّ</rule>َهُمۡ عَدُ<rule class=idgham_wo_ghunnah>وٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَّا رَبَّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٧٧',
    77, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 78 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3010,
    'ٱلَّذِی خَلَقَنِی فَهُوَ یَهۡدِینِ',
    'الذي خلقني فهو يهدين',
    'ٱلَّذِى خَلَقَنِى فَهُوَ يَهۡد<rule class=madda_permissible>ِي</rule>نِ ٧٨',
    78, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 79 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3011,
    'وَٱلَّذِی هُوَ یُطۡعِمُنِی وَیَسۡقِینِ',
    'والذي هو يطعمني ويسقين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِى هُوَ يُ<rule class=qalaqah>طۡ</rule>عِمُنِى وَيَسۡق<rule class=madda_permissible>ِي</rule>نِ ٧٩',
    79, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 80 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3012,
    'وَإِذَا مَرِضۡتُ فَهُوَ یَشۡفِینِ',
    'واذا مرضت فهو يشفين',
    'وَإِذَا مَرِضۡتُ فَهُوَ يَشۡف<rule class=madda_permissible>ِي</rule>نِ ٨٠',
    80, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 81 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3013,
    'وَٱلَّذِی یُمِیتُنِی ثُمَّ یُحۡیِینِ',
    'والذي يميتني ثم يحيين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِى يُمِيتُنِى ثُ<rule class=ghunnah>مّ</rule>َ يُحۡي<rule class=madda_permissible>ِي</rule>نِ ٨١',
    81, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 82 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3014,
    'وَٱلَّذِیۤ أَطۡمَعُ أَن یَغۡفِرَ لِی خَطِیۤـَٔتِی یَوۡمَ ٱلدِّینِ',
    'والذي اطمع ان يغفر لي خطيئتي يوم الدين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>طۡ</rule>مَعُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغۡفِرَ لِى خَطِ<rule class=madda_obligatory_mottasel>يٓ</rule>ــَٔتِى يَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ٨٢',
    82, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 83 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3015,
    'رَبِّ هَبۡ لِی حُكۡمࣰا وَأَلۡحِقۡنِی بِٱلصَّـٰلِحِینَ',
    'رب هب لي حكما والحقني بالصالحين',
    'رَبِّ هَ<rule class=qalaqah>بۡ</rule> لِى حُكۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َأَلۡحِ<rule class=qalaqah>قۡ</rule>نِى بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 19, 5, 370, 320, 148, 'false'
  );
  
  -- Ayah 84 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3016,
    'وَٱجۡعَل لِّی لِسَانَ صِدۡقࣲ فِی ٱلۡـَٔاخِرِینَ',
    'واجعل لي لسان صدق في الاخرين',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَل لِّى لِسَانَ صِ<rule class=qalaqah>دۡ</rule><rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَخِر<rule class=madda_permissible>ِي</rule>نَ ٨٤',
    84, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 85 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3017,
    'وَٱجۡعَلۡنِی مِن وَرَثَةِ جَنَّةِ ٱلنَّعِیمِ',
    'واجعلني من ورثة جنة النعيم',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَلۡنِى م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َرَثَةِ جَ<rule class=ghunnah>نّ</rule>َةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َع<rule class=madda_permissible>ِي</rule>مِ ٨٥',
    85, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 86 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3018,
    'وَٱغۡفِرۡ لِأَبِیۤ إِنَّهُۥ كَانَ مِنَ ٱلضَّاۤلِّینَ',
    'واغفر لابي انه كان من الضالين',
    'وَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لِأَب<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضّ<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 87 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3019,
    'وَلَا تُخۡزِنِی یَوۡمَ یُبۡعَثُونَ',
    'ولا تخزني يوم يبعثون',
    'وَلَا تُخۡزِنِى يَوۡمَ يُ<rule class=qalaqah>بۡ</rule>عَث<rule class=madda_permissible>ُو</rule>نَ ٨٧',
    87, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 88 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3020,
    'یَوۡمَ لَا یَنفَعُ مَالࣱ وَلَا بَنُونَ',
    'يوم لا ينفع مال ولا بنون',
    'يَوۡمَ لَا يَ<rule class=ikhafa>نف</rule>َعُ مَا<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا بَن<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 89 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3021,
    'إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبࣲ سَلِیمࣲ',
    'الا من اتى الله بقلب سليم',
    'إِلَّا مَنۡ أَتَى <rule class=ham_wasl>ٱ</rule>للَّهَ بِقَلۡ<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>س</rule>َل<rule class=madda_permissible>ِي</rule>مٍ ٨٩',
    89, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 90 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3022,
    'وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِینَ',
    'وازلفت الجنة للمتقين',
    'وَأُزۡلِفَتِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةُ لِلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٩٠',
    90, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 91 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3023,
    'وَبُرِّزَتِ ٱلۡجَحِیمُ لِلۡغَاوِینَ',
    'وبرزت الجحيم للغاوين',
    'وَبُرِّزَتِ <rule class=ham_wasl>ٱ</rule>لۡجَحِيمُ لِلۡغَاو<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 92 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3024,
    'وَقِیلَ لَهُمۡ أَیۡنَ مَا كُنتُمۡ تَعۡبُدُونَ',
    'وقيل لهم اين ما كنتم تعبدون',
    'وَقِيلَ لَهُمۡ أَيۡنَ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٩٢',
    92, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 93 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3025,
    'مِن دُونِ ٱللَّهِ هَلۡ یَنصُرُونَكُمۡ أَوۡ یَنتَصِرُونَ',
    'من دون الله هل ينصرونكم او ينتصرون',
    'مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ هَلۡ يَ<rule class=ikhafa>نص</rule>ُرُونَكُمۡ أَوۡ يَ<rule class=ikhafa>نت</rule>َصِر<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 94 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3026,
    'فَكُبۡكِبُوا۟ فِیهَا هُمۡ وَٱلۡغَاوُۥنَ',
    'فكبكبوا فيها هم والغاوون',
    'فَكُ<rule class=qalaqah>بۡ</rule>كِبُو<rule class=slnt>اۡ</rule> فِيهَا هُمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡغَاوُ<rule class=madda_permissible>ۥ</rule>نَ ٩٤',
    94, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 95 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3027,
    'وَجُنُودُ إِبۡلِیسَ أَجۡمَعُونَ',
    'وجنود ابليس اجمعون',
    'وَجُنُودُ إِ<rule class=qalaqah>بۡ</rule>لِيسَ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ُو</rule>نَ ٩٥',
    95, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 96 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3028,
    'قَالُوا۟ وَهُمۡ فِیهَا یَخۡتَصِمُونَ',
    'قالوا وهم فيها يختصمون',
    'قَالُو<rule class=slnt>اۡ</rule> وَهُمۡ فِيهَا يَخۡتَصِم<rule class=madda_permissible>ُو</rule>نَ ٩٦',
    96, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 97 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3029,
    'تَٱللَّهِ إِن كُنَّا لَفِی ضَلَـٰلࣲ مُّبِینٍ',
    'تالله ان كنا لفي ضلال مبين',
    'تَ<rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا لَفِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٩٧',
    97, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 98 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3030,
    'إِذۡ نُسَوِّیكُم بِرَبِّ ٱلۡعَـٰلَمِینَ',
    'اذ نسويكم برب العالمين',
    'إِذۡ نُسَوِّيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٩٨',
    98, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 99 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3031,
    'وَمَاۤ أَضَلَّنَاۤ إِلَّا ٱلۡمُجۡرِمُونَ',
    'وما اضلنا الا المجرمون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَضَلَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٩٩',
    99, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 100 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3032,
    'فَمَا لَنَا مِن شَـٰفِعِینَ',
    'فما لنا من شافعين',
    'فَمَا لَنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َ<rule class=madda_normal>ـٰ</rule>فِع<rule class=madda_permissible>ِي</rule>نَ ١٠٠',
    100, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 101 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3033,
    'وَلَا صَدِیقٍ حَمِیمࣲ',
    'ولا صديق حميم',
    'وَلَا صَدِيقٍ حَم<rule class=madda_permissible>ِي</rule>مٍ ١٠١',
    101, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 102 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3034,
    'فَلَوۡ أَنَّ لَنَا كَرَّةࣰ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ',
    'فلو ان لنا كرة فنكون من المؤمنين',
    'فَلَوۡ أَ<rule class=ghunnah>نّ</rule>َ لَنَا كَرَّ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َنَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٠٢',
    102, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 103 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3035,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ',
    'ان في ذلك لاية وما كان اكثرهم مؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ أَكۡثَرُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٠٣',
    103, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 104 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3036,
    'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ',
    'وان ربك لهو العزيز الرحيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٠٤',
    104, 19, 5, 371, 320, 148, 'false'
  );
  
  -- Ayah 105 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3037,
    'كَذَّبَتۡ قَوۡمُ نُوحٍ ٱلۡمُرۡسَلِینَ',
    'كذبت قوم نوح المرسلين',
    'كَذَّبَتۡ قَوۡمُ نُوحٍ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ١٠٥',
    105, 19, 5, 371, 321, 148, 'false'
  );
  
  -- Ayah 106 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3038,
    'إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ أَلَا تَتَّقُونَ',
    'اذ قال لهم اخوهم نوح الا تتقون',
    'إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ أَلَا تَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٠٦',
    106, 19, 5, 371, 321, 148, 'false'
  );
  
  -- Ayah 107 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3039,
    'إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ',
    'اني لكم رسول امين',
    'إِ<rule class=ghunnah>نّ</rule>ِى لَكُمۡ رَسُولٌ أَم<rule class=madda_permissible>ِي</rule>نٌ ١٠٧',
