    3065,
    'أَمَدَّكُم بِأَنۡعَـٰمࣲ وَبَنِینَ',
    'امدكم بانعام وبنين',
    'أَمَدَّك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَنۡعَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َبَن<rule class=madda_permissible>ِي</rule>نَ ١٣٣',
    133, 19, 5, 372, 322, 149, 'false'
  );
  
