    'وَجَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َعُي<rule class=madda_permissible>ُو</rule>نٍ ١٣٤',
    134, 19, 5, 372, 322, 149, 'false'
  );
  
  -- Ayah 135 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
