    3069,
    'إِنۡ هَـٰذَاۤ إِلَّا خُلُقُ ٱلۡأَوَّلِینَ',
    'ان هذا الا خلق الاولين',
    'إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا خُلُقُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ١٣٧',
    137, 19, 5, 373, 322, 149, 'false'
  );
  
  -- Ayah 138 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3070,
    'وَمَا نَحۡنُ بِمُعَذَّبِینَ',
    'وما نحن بمعذبين',
    'وَمَا نَحۡنُ بِمُعَذَّب<rule class=madda_permissible>ِي</rule>نَ ١٣٨',
    138, 19, 5, 373, 322, 149, 'false'
  );
  
  -- Ayah 139 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3071,
    'فَكَذَّبُوهُ فَأَهۡلَكۡنَـٰهُمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ',
    'فكذبوه فاهلكناهم ان في ذلك لاية وما كان اكثرهم مؤمنين',
    'فَكَذَّبُوهُ فَأَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ أَكۡثَرُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٣٩',
    139, 19, 5, 373, 322, 149, 'false'
  );
  
  -- Ayah 140 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3072,
