  -- Ayah 145 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3077,
    'وَمَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَـٰلَمِینَ',
    'وما اسالكم عليه من اجر ان اجري الا على رب العالمين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ مِنۡ أَ<rule class=qalaqah>جۡ</rule>رٍ‌ۖ إِنۡ أَ<rule class=qalaqah>جۡ</rule>رِىَ إِلَّا عَلَىٰ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٤٥',
    145, 19, 5, 373, 323, 149, 'false'
  );
  
