    'فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َعُي<rule class=madda_permissible>ُو</rule>نٍ ١٤٧',
    147, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 148 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3080,
    'وَزُرُوعࣲ وَنَخۡلࣲ طَلۡعُهَا هَضِیمࣱ',
    'وزروع ونخل طلعها هضيم',
    'وَزُرُو<rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>و</rule>َنَخۡ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ط</rule>َلۡعُهَا هَض<rule class=madda_permissible>ِي</rule>مٌ ١٤٨',
    148, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 149 Surah Ash-Shuaraa
