  VALUES (
    26,
    3081,
    'وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُیُوتࣰا فَـٰرِهِینَ',
    'وتنحتون من الجبال بيوتا فارهين',
    'وَتَنۡحِتُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجِبَالِ بُيُو<rule class=ikhafa>تًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=madda_normal>ـٰ</rule>رِه<rule class=madda_permissible>ِي</rule>نَ ١٤٩',
    149, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 150 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3082,
    'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ',
    'فاتقوا الله واطيعون',
