    150, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 151 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3083,
    'وَلَا تُطِیعُوۤا۟ أَمۡرَ ٱلۡمُسۡرِفِینَ',
    'ولا تطيعوا امر المسرفين',
    'وَلَا تُطِيع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡرَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡرِف<rule class=madda_permissible>ِي</rule>نَ ١٥١',
    151, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 152 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3084,
    'ٱلَّذِینَ یُفۡسِدُونَ فِی ٱلۡأَرۡضِ وَلَا یُصۡلِحُونَ',
    'الذين يفسدون في الارض ولا يصلحون',
    'ٱلَّذِينَ يُفۡسِدُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا يُصۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٥٢',
    152, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 153 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3085,
    'قَالُوۤا۟ إِنَّمَاۤ أَنتَ مِنَ ٱلۡمُسَحَّرِینَ',
    'قالوا انما انت من المسحرين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُسَحَّر<rule class=madda_permissible>ِي</rule>نَ ١٥٣',
    153, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 154 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3086,
    'مَاۤ أَنتَ إِلَّا بَشَرࣱ مِّثۡلُنَا فَأۡتِ بِـَٔایَةٍ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'ما انت الا بشر مثلنا فات باية ان كنت من الصادقين',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ إِلَّا بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُنَا فَأۡتِ بِـَٔـايَةٍ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٥٤',
    154, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 155 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3087,
    'قَالَ هَـٰذِهِۦ نَاقَةࣱ لَّهَا شِرۡبࣱ وَلَكُمۡ شِرۡبُ یَوۡمࣲ مَّعۡلُومࣲ',
    'قال هذه ناقة لها شرب ولكم شرب يوم معلوم',
    'قَالَ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> نَاقَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهَا شِرۡ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَكُمۡ شِرۡبُ يَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡل<rule class=madda_permissible>ُو</rule>مٍ ١٥٥',
    155, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 156 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3088,
    'وَلَا تَمَسُّوهَا بِسُوۤءࣲ فَیَأۡخُذَكُمۡ عَذَابُ یَوۡمٍ عَظِیمࣲ',
    'ولا تمسوها بسوء فياخذكم عذاب يوم عظيم',
    'وَلَا تَمَسُّوهَا بِس<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ف</rule>َيَأۡخُذَكُمۡ عَذَابُ يَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ١٥٦',
    156, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 157 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3089,
    'فَعَقَرُوهَا فَأَصۡبَحُوا۟ نَـٰدِمِینَ',
    'فعقروها فاصبحوا نادمين',
    'فَعَقَرُوهَا فَأَصۡبَحُو<rule class=slnt>اۡ</rule> نَ<rule class=madda_normal>ـٰ</rule>دِم<rule class=madda_permissible>ِي</rule>نَ ١٥٧',
    157, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 158 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3090,
    'فَأَخَذَهُمُ ٱلۡعَذَابُۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ',
    'فاخذهم العذاب ان في ذلك لاية وما كان اكثرهم مؤمنين',
    'فَأَخَذَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ أَكۡثَرُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٥٨',
    158, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 159 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3091,
    'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ',
    'وان ربك لهو العزيز الرحيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٥٩',
    159, 19, 5, 373, 323, 149, 'false'
  );
  
  -- Ayah 160 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3092,
    'كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِینَ',
    'كذبت قوم لوط المرسلين',
    'كَذَّبَتۡ قَوۡمُ لُوطٍ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ١٦٠',
    160, 19, 5, 374, 324, 149, 'false'
  );
  
  -- Ayah 161 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3093,
    'إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا تَتَّقُونَ',
    'اذ قال لهم اخوهم لوط الا تتقون',
    'إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا تَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٦١',
    161, 19, 5, 374, 324, 149, 'false'
  );
  
  -- Ayah 162 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3094,
    'إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ',
    'اني لكم رسول امين',
    'إِ<rule class=ghunnah>نّ</rule>ِى لَكُمۡ رَسُولٌ أَم<rule class=madda_permissible>ِي</rule>نٌ ١٦٢',
    162, 19, 5, 374, 324, 149, 'false'
  );
  
  -- Ayah 163 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3095,
    'فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ',
    'فاتقوا الله واطيعون',
    'فَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطِيع<rule class=madda_permissible>ُو</rule>نِ ١٦٣',
    163, 19, 5, 374, 324, 149, 'false'
  );
  
  -- Ayah 164 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3096,
    'وَمَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَـٰلَمِینَ',
    'وما اسالكم عليه من اجر ان اجري الا على رب العالمين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ مِنۡ أَ<rule class=qalaqah>جۡ</rule>رٍ‌ۖ إِنۡ أَ<rule class=qalaqah>جۡ</rule>رِىَ إِلَّا عَلَىٰ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٦٤',
    164, 19, 5, 374, 324, 149, 'false'
  );
  
  -- Ayah 165 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3097,
    'أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَـٰلَمِینَ',
    'اتاتون الذكران من العالمين',
    'أَتَأۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذُّكۡرَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٦٥',
    165, 19, 5, 374, 324, 149, 'false'
  );
  
  -- Ayah 166 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3098,
    'وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّكُم مِّنۡ أَزۡوَ ٰ⁠جِكُمۚ بَلۡ أَنتُمۡ قَوۡمٌ عَادُونَ',
    'وتذرون ما خلق لكم ربكم من ازواجكم بل انتم قوم عادون',
    'وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَزۡو<rule class=madda_normal>ٰ</rule>جِك<rule class=ikhafa_shafawi>ُم‌ۚ</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ أَ<rule class=ikhafa>نت</rule>ُمۡ قَوۡمٌ عَاد<rule class=madda_permissible>ُو</rule>نَ ١٦٦',
    166, 19, 5, 374, 324, 149, 'false'
  );
  
  -- Ayah 167 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3099,
    'قَالُوا۟ لَىِٕن لَّمۡ تَنتَهِ یَـٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِینَ',
    'قالوا لئن لم تنته يا لوط لتكونن من المخرجين',
    'قَالُو<rule class=slnt>اۡ</rule> لَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَ<rule class=ikhafa>نت</rule>َهِ يَ<rule class=madda_normal>ـٰ</rule>لُوطُ لَتَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُخۡرَج<rule class=madda_permissible>ِي</rule>نَ ١٦٧',
    167, 19, 5, 374, 324, 149, 'false'
  );
  
