    'قَالَ إِ<rule class=ghunnah>نّ</rule>ِى لِعَمَلِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقَال<rule class=madda_permissible>ِي</rule>نَ ١٦٨',
    168, 19, 5, 374, 324, 149, 'false'
  );
  
  -- Ayah 169 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
