  );
  
  -- Ayah 180 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3112,
    'وَمَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَـٰلَمِینَ',
    'وما اسالكم عليه من اجر ان اجري الا على رب العالمين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ مِنۡ أَ<rule class=qalaqah>جۡ</rule>رٍ‌ۖ إِنۡ أَ<rule class=qalaqah>جۡ</rule>رِىَ إِلَّا عَلَىٰ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٨٠',
    180, 19, 5, 374, 325, 149, 'false'
  );
  
  -- Ayah 181 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3113,
    '۞ أَوۡفُوا۟ ٱلۡكَیۡلَ وَلَا تَكُونُوا۟ مِنَ ٱلۡمُخۡسِرِینَ',
    'اوفوا الكيل ولا تكونوا من المخسرين',
    '۞أَوۡفُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكَيۡلَ وَلَا تَكُونُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُخۡسِر<rule class=madda_permissible>ِي</rule>نَ ١٨١',
    181, 19, 5, 374, 325, 150, 'false'
  );
  
  -- Ayah 182 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3114,
    'وَزِنُوا۟ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِیمِ',
    'وزنوا بالقسطاس المستقيم',
    'وَزِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطَاسِ <rule class=ham_wasl>ٱ</rule>لۡمُسۡتَق<rule class=madda_permissible>ِي</rule>مِ ١٨٢',
    182, 19, 5, 374, 325, 150, 'false'
  );
  
  -- Ayah 183 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3115,
    'وَلَا تَبۡخَسُوا۟ ٱلنَّاسَ أَشۡیَاۤءَهُمۡ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ',
    'ولا تبخسوا الناس اشياءهم ولا تعثوا في الارض مفسدين',
    'وَلَا تَ<rule class=qalaqah>بۡ</rule>خَسُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ أَشۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ وَلَا تَعۡثَوۡ<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ١٨٣',
    183, 19, 5, 374, 325, 150, 'false'
  );
  
  -- Ayah 184 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3116,
    'وَٱتَّقُوا۟ ٱلَّذِی خَلَقَكُمۡ وَٱلۡجِبِلَّةَ ٱلۡأَوَّلِینَ',
    'واتقوا الذي خلقكم والجبلة الاولين',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَكُمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡجِبِلَّةَ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ١٨٤',
    184, 19, 5, 375, 325, 150, 'false'
  );
  
  -- Ayah 185 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3117,
    'قَالُوۤا۟ إِنَّمَاۤ أَنتَ مِنَ ٱلۡمُسَحَّرِینَ',
    'قالوا انما انت من المسحرين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُسَحَّر<rule class=madda_permissible>ِي</rule>نَ ١٨٥',
    185, 19, 5, 375, 325, 150, 'false'
  );
  
  -- Ayah 186 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3118,
    'وَمَاۤ أَنتَ إِلَّا بَشَرࣱ مِّثۡلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلۡكَـٰذِبِینَ',
    'وما انت الا بشر مثلنا وان نظنك لمن الكاذبين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ إِلَّا بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُنَا وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّظُ<rule class=ghunnah>نّ</rule>ُكَ لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ١٨٦',
    186, 19, 5, 375, 325, 150, 'false'
  );
  
  -- Ayah 187 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3119,
    'فَأَسۡقِطۡ عَلَیۡنَا كِسَفࣰا مِّنَ ٱلسَّمَاۤءِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'فاسقط علينا كسفا من السماء ان كنت من الصادقين',
    'فَأَسۡقِ<rule class=qalaqah>طۡ</rule> عَلَيۡنَا كِسَ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٨٧',
    187, 19, 5, 375, 325, 150, 'false'
  );
  
  -- Ayah 188 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3120,
    'قَالَ رَبِّیۤ أَعۡلَمُ بِمَا تَعۡمَلُونَ',
    'قال ربي اعلم بما تعملون',
    'قَالَ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡلَمُ بِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٨٨',
    188, 19, 5, 375, 325, 150, 'false'
  );
  
  -- Ayah 189 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3121,
    'فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ یَوۡمِ ٱلظُّلَّةِۚ إِنَّهُۥ كَانَ عَذَابَ یَوۡمٍ عَظِیمٍ',
    'فكذبوه فاخذهم عذاب يوم الظلة انه كان عذاب يوم عظيم',
    'فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ يَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلَّةِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ عَذَابَ يَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ١٨٩',
    189, 19, 5, 375, 325, 150, 'false'
  );
  
  -- Ayah 190 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3122,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ',
    'ان في ذلك لاية وما كان اكثرهم مؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ أَكۡثَرُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٩٠',
    190, 19, 5, 375, 325, 150, 'false'
  );
  
  -- Ayah 191 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3123,
    'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ',
    'وان ربك لهو العزيز الرحيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٩١',
    191, 19, 5, 375, 325, 150, 'false'
  );
  
  -- Ayah 192 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3124,
    'وَإِنَّهُۥ لَتَنزِیلُ رَبِّ ٱلۡعَـٰلَمِینَ',
    'وانه لتنزيل رب العالمين',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَتَ<rule class=ikhafa>نز</rule>ِيلُ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٩٢',
    192, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 193 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3125,
    'نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِینُ',
    'نزل به الروح الامين',
    'نَزَلَ بِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّوحُ <rule class=ham_wasl>ٱ</rule>لۡأَم<rule class=madda_permissible>ِي</rule>نُ ١٩٣',
    193, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 194 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3126,
    'عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِینَ',
    'على قلبك لتكون من المنذرين',
    'عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نذ</rule>ِر<rule class=madda_permissible>ِي</rule>نَ ١٩٤',
    194, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 195 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3127,
    'بِلِسَانٍ عَرَبِیࣲّ مُّبِینࣲ',
    'بلسان عربي مبين',
    'بِلِسَانٍ عَرَبِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١٩٥',
    195, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 196 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3128,
    'وَإِنَّهُۥ لَفِی زُبُرِ ٱلۡأَوَّلِینَ',
    'وانه لفي زبر الاولين',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَفِى زُبُرِ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ١٩٦',
    196, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 197 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3129,
    'أَوَلَمۡ یَكُن لَّهُمۡ ءَایَةً أَن یَعۡلَمَهُۥ عُلَمَـٰۤؤُا۟ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ',
    'اولم يكن لهم اية ان يعلمه علماء بني اسرائيل',
    'أَوَلَمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ ءَايَةً أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَمَهُ<rule class=madda_normal>ۥ</rule> عُلَمَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓء<rule class=madda_permissible>ِي</rule>لَ ١٩٧',
    197, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 198 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3130,
    'وَلَوۡ نَزَّلۡنَـٰهُ عَلَىٰ بَعۡضِ ٱلۡأَعۡجَمِینَ',
    'ولو نزلناه على بعض الاعجمين',
    'وَلَوۡ نَزَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُ عَلَىٰ بَعۡضِ <rule class=ham_wasl>ٱ</rule>لۡأَعۡجَم<rule class=madda_permissible>ِي</rule>نَ ١٩٨',
    198, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 199 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3131,
    'فَقَرَأَهُۥ عَلَیۡهِم مَّا كَانُوا۟ بِهِۦ مُؤۡمِنِینَ',
    'فقراه عليهم ما كانوا به مؤمنين',
    'فَقَرَأَهُ<rule class=madda_normal>ۥ</rule> عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> مُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٩٩',
    199, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 200 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3132,
    'كَذَ ٰ⁠لِكَ سَلَكۡنَـٰهُ فِی قُلُوبِ ٱلۡمُجۡرِمِینَ',
    'كذلك سلكناه في قلوب المجرمين',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ سَلَكۡنَ<rule class=madda_normal>ـٰ</rule>هُ فِى قُلُوبِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٢٠٠',
    200, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 201 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3133,
    'لَا یُؤۡمِنُونَ بِهِۦ حَتَّىٰ یَرَوُا۟ ٱلۡعَذَابَ ٱلۡأَلِیمَ',
    'لا يؤمنون به حتى يروا العذاب الاليم',
    'لَا يُؤۡمِنُونَ بِه<rule class=madda_normal>ِۦ</rule> حَتَّىٰ يَرَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ <rule class=ham_wasl>ٱ</rule>لۡأَل<rule class=madda_permissible>ِي</rule>مَ ٢٠١',
    201, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 202 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3134,
    'فَیَأۡتِیَهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ',
    'فياتيهم بغتة وهم لا يشعرون',
    'فَيَأۡتِيَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َغۡتَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٢٠٢',
    202, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 203 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3135,
    'فَیَقُولُوا۟ هَلۡ نَحۡنُ مُنظَرُونَ',
    'فيقولوا هل نحن منظرون',
    'فَيَقُولُو<rule class=slnt>اۡ</rule> هَلۡ نَحۡنُ مُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٢٠٣',
    203, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 204 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3136,
    'أَفَبِعَذَابِنَا یَسۡتَعۡجِلُونَ',
    'افبعذابنا يستعجلون',
    'أَفَبِعَذَابِنَا يَسۡتَعۡجِل<rule class=madda_permissible>ُو</rule>نَ ٢٠٤',
    204, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 205 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3137,
    'أَفَرَءَیۡتَ إِن مَّتَّعۡنَـٰهُمۡ سِنِینَ',
    'افرايت ان متعناهم سنين',
    'أَفَرَءَيۡتَ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّتَّعۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ سِن<rule class=madda_permissible>ِي</rule>نَ ٢٠٥',
    205, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 206 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3138,
    'ثُمَّ جَاۤءَهُم مَّا كَانُوا۟ یُوعَدُونَ',
    'ثم جاءهم ما كانوا يوعدون',
    'ثُ<rule class=ghunnah>مّ</rule>َ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يُوعَد<rule class=madda_permissible>ُو</rule>نَ ٢٠٦',
    206, 19, 5, 375, 326, 150, 'false'
  );
  
  -- Ayah 207 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3139,
    'مَاۤ أَغۡنَىٰ عَنۡهُم مَّا كَانُوا۟ یُمَتَّعُونَ',
    'ما اغنى عنهم ما كانوا يمتعون',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡنَىٰ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يُمَتَّع<rule class=madda_permissible>ُو</rule>نَ ٢٠٧',
    207, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 208 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3140,
    'وَمَاۤ أَهۡلَكۡنَا مِن قَرۡیَةٍ إِلَّا لَهَا مُنذِرُونَ',
    'وما اهلكنا من قرية الا لها منذرون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَهۡلَكۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ إِلَّا لَهَا مُ<rule class=ikhafa>نذ</rule>ِر<rule class=madda_permissible>ُو</rule>نَ ٢٠٨',
    208, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 209 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3141,
    'ذِكۡرَىٰ وَمَا كُنَّا ظَـٰلِمِینَ',
    'ذكرى وما كنا ظالمين',
    'ذِكۡرَىٰ وَمَا كُ<rule class=ghunnah>نّ</rule>َا ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٠٩',
    209, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 210 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3142,
    'وَمَا تَنَزَّلَتۡ بِهِ ٱلشَّیَـٰطِینُ',
    'وما تنزلت به الشياطين',
    'وَمَا تَنَزَّلَتۡ بِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>ط<rule class=madda_permissible>ِي</rule>نُ ٢١٠',
    210, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 211 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3143,
    'وَمَا یَنۢبَغِی لَهُمۡ وَمَا یَسۡتَطِیعُونَ',
    'وما ينبغي لهم وما يستطيعون',
    'وَمَا يَ<rule class=iqlab>نۢب</rule>َغِى لَهُمۡ وَمَا يَسۡتَطِيع<rule class=madda_permissible>ُو</rule>نَ ٢١١',
    211, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 212 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3144,
    'إِنَّهُمۡ عَنِ ٱلسَّمۡعِ لَمَعۡزُولُونَ',
    'انهم عن السمع لمعزولون',
    'إِ<rule class=ghunnah>نّ</rule>َهُمۡ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعِ لَمَعۡزُول<rule class=madda_permissible>ُو</rule>نَ ٢١٢',
    212, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 213 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3145,
    'فَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِینَ',
    'فلا تدع مع الله الها اخر فتكون من المعذبين',
    'فَلَا تَ<rule class=qalaqah>دۡ</rule>عُ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ فَتَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُعَذَّب<rule class=madda_permissible>ِي</rule>نَ ٢١٣',
    213, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 214 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3146,
    'وَأَنذِرۡ عَشِیرَتَكَ ٱلۡأَقۡرَبِینَ',
    'وانذر عشيرتك الاقربين',
    'وَأَ<rule class=ikhafa>نذ</rule>ِرۡ عَشِيرَتَكَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>قۡ</rule>رَب<rule class=madda_permissible>ِي</rule>نَ ٢١٤',
    214, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 215 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3147,
    'وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِینَ',
    'واخفض جناحك لمن اتبعك من المؤمنين',
    'وَ<rule class=ham_wasl>ٱ</rule>خۡفِضۡ جَنَاحَكَ لِمَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢١٥',
    215, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 216 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3148,
    'فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّی بَرِیۤءࣱ مِّمَّا تَعۡمَلُونَ',
    'فان عصوك فقل اني بريء مما تعملون',
    'فَإِنۡ عَصَوۡكَ فَقُلۡ إِ<rule class=ghunnah>نّ</rule>ِى بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢١٦',
    216, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 217 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3149,
    'وَتَوَكَّلۡ عَلَى ٱلۡعَزِیزِ ٱلرَّحِیمِ',
    'وتوكل على العزيز الرحيم',
    'وَتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مِ ٢١٧',
    217, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 218 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3150,
    'ٱلَّذِی یَرَىٰكَ حِینَ تَقُومُ',
    'الذي يراك حين تقوم',
    'ٱلَّذِى يَرَ<rule class=madda_normal>ٮٰ</rule>كَ حِينَ تَق<rule class=madda_permissible>ُو</rule>مُ ٢١٨',
    218, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 219 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3151,
    'وَتَقَلُّبَكَ فِی ٱلسَّـٰجِدِینَ',
    'وتقلبك في الساجدين',
    'وَتَقَلُّبَكَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ٢١٩',
    219, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 220 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3152,
    'إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'انه هو السميع العليم',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٢٢٠',
    220, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 221 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3153,
    'هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّیَـٰطِینُ',
    'هل انبئكم على من تنزل الشياطين',
    'هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َنَزَّلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>ط<rule class=madda_permissible>ِي</rule>نُ ٢٢١',
    221, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 222 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3154,
    'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِیمࣲ',
    'تنزل على كل افاك اثيم',
    'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَث<rule class=madda_permissible>ِي</rule>مٍ ٢٢٢',
    222, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 223 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3155,
    'یُلۡقُونَ ٱلسَّمۡعَ وَأَكۡثَرُهُمۡ كَـٰذِبُونَ',
    'يلقون السمع واكثرهم كاذبون',
    'يُلۡقُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَأَكۡثَرُهُمۡ كَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ٢٢٣',
    223, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 224 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3156,
    'وَٱلشُّعَرَاۤءُ یَتَّبِعُهُمُ ٱلۡغَاوُۥنَ',
    'والشعراء يتبعهم الغاوون',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّعَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ يَتَّبِعُهُمُ <rule class=ham_wasl>ٱ</rule>لۡغَاوُ<rule class=madda_permissible>ۥ</rule>نَ ٢٢٤',
    224, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 225 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3157,
    'أَلَمۡ تَرَ أَنَّهُمۡ فِی كُلِّ وَادࣲ یَهِیمُونَ',
    'الم تر انهم في كل واد يهيمون',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َهُمۡ فِى كُلِّ وَا<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>ي</rule>َهِيم<rule class=madda_permissible>ُو</rule>نَ ٢٢٥',
    225, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 226 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3158,
    'وَأَنَّهُمۡ یَقُولُونَ مَا لَا یَفۡعَلُونَ',
    'وانهم يقولون ما لا يفعلون',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُمۡ يَقُولُونَ مَا لَا يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٢٢٦',
    226, 19, 5, 376, 326, 150, 'false'
  );
  
  -- Ayah 227 Surah Ash-Shuaraa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    26,
    3159,
    'إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِیرࣰا وَٱنتَصَرُوا۟ مِنۢ بَعۡدِ مَا ظُلِمُوا۟ۗ وَسَیَعۡلَمُ ٱلَّذِینَ ظَلَمُوۤا۟ أَیَّ مُنقَلَبࣲ یَنقَلِبُونَ',
    'الا الذين امنوا وعملوا الصالحات وذكروا الله كثيرا وانتصروا من بعد ما ظلموا وسيعلم الذين ظلموا اي منقلب ينقلبون',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَذَكَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َصَرُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ظُلِمُو<rule class=slnt>اۡ‌ۗ</rule> وَسَيَعۡلَمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَىَّ مُ<rule class=ikhafa>نق</rule>َلَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نق</rule>َلِب<rule class=madda_permissible>ُو</rule>نَ ٢٢٧',
    227, 19, 5, 376, 326, 150, 'false'
  );
  

-- Surah An-Naml
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (27, 'سُورَةُ النَّمۡلِ', 'An-Naml', 'The Ant', 'Meccan', 93);

  -- Ayah 1 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3160,
    'طسۤۚ تِلۡكَ ءَایَـٰتُ ٱلۡقُرۡءَانِ وَكِتَابࣲ مُّبِینٍ',
    'طس تلك ايات القران وكتاب مبين',
    'ط<rule class=madda_necessary>سٓ</rule>‌ۚ تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ وَكِتَا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١',
    1, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 2 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3161,
    'هُدࣰى وَبُشۡرَىٰ لِلۡمُؤۡمِنِینَ',
    'هدى وبشرى للمؤمنين',
    'هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َبُشۡرَىٰ لِلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 3 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3162,
    'ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ',
    'الذين يقيمون الصلاة ويؤتون الزكاة وهم بالاخرة هم يوقنون',
    'ٱلَّذِينَ يُقِيمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَيُؤۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمۡ يُوقِن<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 4 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3163,
    'إِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ زَیَّنَّا لَهُمۡ أَعۡمَـٰلَهُمۡ فَهُمۡ یَعۡمَهُونَ',
    'ان الذين لا يؤمنون بالاخرة زينا لهم اعمالهم فهم يعمهون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ زَيَّ<rule class=ghunnah>نّ</rule>َا لَهُمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ فَهُمۡ يَعۡمَه<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 5 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3164,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَهُمۡ سُوۤءُ ٱلۡعَذَابِ وَهُمۡ فِی ٱلۡـَٔاخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ',
    'اولئك الذين لهم سوء العذاب وهم في الاخرة هم الاخسرون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَهُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ وَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمُ <rule class=ham_wasl>ٱ</rule>لۡأَخۡسَر<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 6 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3165,
    'وَإِنَّكَ لَتُلَقَّى ٱلۡقُرۡءَانَ مِن لَّدُنۡ حَكِیمٍ عَلِیمٍ',
    'وانك لتلقى القران من لدن حكيم عليم',
    'وَإِ<rule class=ghunnah>نّ</rule>َكَ لَتُلَقَّى <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُنۡ حَكِيمٍ عَل<rule class=madda_permissible>ِي</rule>مٍ ٦',
    6, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 7 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3166,
    'إِذۡ قَالَ مُوسَىٰ لِأَهۡلِهِۦۤ إِنِّیۤ ءَانَسۡتُ نَارࣰا سَـَٔاتِیكُم مِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِیكُم بِشِهَابࣲ قَبَسࣲ لَّعَلَّكُمۡ تَصۡطَلُونَ',
    'اذ قال موسى لاهله اني انست نارا ساتيكم منها بخبر او اتيكم بشهاب قبس لعلكم تصطلون',
    'إِذۡ قَالَ مُوسَىٰ لِأَهۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَانَسۡتُ نَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>س</rule>َـَٔـاتِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِشِهَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ق</rule>َبَ<rule class=idgham_wo_ghunnah>سٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّكُمۡ تَصۡطَل<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 8 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3167,
    'فَلَمَّا جَاۤءَهَا نُودِیَ أَنۢ بُورِكَ مَن فِی ٱلنَّارِ وَمَنۡ حَوۡلَهَا وَسُبۡحَـٰنَ ٱللَّهِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'فلما جاءها نودي ان بورك من في النار ومن حولها وسبحان الله رب العالمين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهَا نُودِىَ أ<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>ُورِكَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ وَمَنۡ حَوۡلَهَا وَسُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 9 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3168,
    'یَـٰمُوسَىٰۤ إِنَّهُۥۤ أَنَا ٱللَّهُ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'يا موسى انه انا الله العزيز الحكيم',
    'يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَنَا <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٩',
    9, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 10 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3169,
    'وَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَاۤنࣱّ وَلَّىٰ مُدۡبِرࣰا وَلَمۡ یُعَقِّبۡۚ یَـٰمُوسَىٰ لَا تَخَفۡ إِنِّی لَا یَخَافُ لَدَیَّ ٱلۡمُرۡسَلُونَ',
    'والق عصاك فلما راها تهتز كانها جان ولى مدبرا ولم يعقب يا موسى لا تخف اني لا يخاف لدي المرسلون',
    'وَأَلۡقِ عَصَاكَ‌ۚ فَلَ<rule class=ghunnah>مّ</rule>َا رَءَاهَا تَهۡتَزُّ كَأَ<rule class=ghunnah>نّ</rule>َهَا ج<rule class=madda_necessary>َا</rule>ٓ<rule class=idgham_ghunnah>نٌّ</rule> <rule class=idgham_ghunnah>و</rule>َلَّىٰ مُ<rule class=qalaqah>دۡ</rule>بِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ يُعَقِّ<rule class=qalaqah>بۡ</rule>‌ۚ يَ<rule class=madda_normal>ـٰ</rule>مُوسَىٰ لَا تَخَفۡ إِ<rule class=ghunnah>نّ</rule>ِى لَا يَخَافُ لَدَىَّ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 11 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3170,
    'إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ سُوۤءࣲ فَإِنِّی غَفُورࣱ رَّحِیمࣱ',
    'الا من ظلم ثم بدل حسنا بعد سوء فاني غفور رحيم',
    'إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>َلَمَ ثُ<rule class=ghunnah>مّ</rule>َ بَدَّلَ حُسۡن<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َعۡدَ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>ِى غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١١',
    11, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 12 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3171,
    'وَأَدۡخِلۡ یَدَكَ فِی جَیۡبِكَ تَخۡرُجۡ بَیۡضَاۤءَ مِنۡ غَیۡرِ سُوۤءࣲۖ فِی تِسۡعِ ءَایَـٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ',
    'وادخل يدك في جيبك تخرج بيضاء من غير سوء في تسع ايات الى فرعون وقومه انهم كانوا قوما فاسقين',
    'وَأَ<rule class=qalaqah>دۡ</rule>خِلۡ يَدَكَ فِى جَيۡبِكَ تَخۡرُ<rule class=qalaqah>جۡ</rule> بَيۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِنۡ غَيۡرِ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=ikhafa>ءٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>ِى تِسۡعِ ءَايَ<rule class=madda_normal>ـٰ</rule>تٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ١٢',
    12, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 13 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3172,
    'فَلَمَّا جَاۤءَتۡهُمۡ ءَایَـٰتُنَا مُبۡصِرَةࣰ قَالُوا۟ هَـٰذَا سِحۡرࣱ مُّبِینࣱ',
    'فلما جاءتهم اياتنا مبصرة قالوا هذا سحر مبين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا مُ<rule class=qalaqah>بۡ</rule>صِرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٣',
    13, 19, 5, 377, 327, 151, 'false'
  );
  
  -- Ayah 14 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3173,
    'وَجَحَدُوا۟ بِهَا وَٱسۡتَیۡقَنَتۡهَاۤ أَنفُسُهُمۡ ظُلۡمࣰا وَعُلُوࣰّاۚ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُفۡسِدِینَ',
    'وجحدوا بها واستيقنتها انفسهم ظلما وعلوا فانظر كيف كان عاقبة المفسدين',
    'وَجَحَدُو<rule class=slnt>اۡ</rule> بِهَا وَ<rule class=ham_wasl>ٱ</rule>سۡتَيۡقَنَتۡه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>ُسُهُمۡ ظُلۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َعُلُو<rule class=ikhafa>ًّا‌ۚ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ١٤',
    14, 19, 5, 378, 327, 151, 'false'
  );
  
  -- Ayah 15 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3174,
    'وَلَقَدۡ ءَاتَیۡنَا دَاوُۥدَ وَسُلَیۡمَـٰنَ عِلۡمࣰاۖ وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی فَضَّلَنَا عَلَىٰ كَثِیرࣲ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِینَ',
    'ولقد اتينا داوود وسليمان علما وقالا الحمد لله الذي فضلنا على كثير من عباده المؤمنين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا دَاوُ<rule class=madda_normal>ۥ</rule>دَ وَسُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ عِلۡ<rule class=idgham_ghunnah>مًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَا <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى فَضَّلَنَا عَلَىٰ كَثِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِبَادِهِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٥',
    15, 19, 5, 378, 328, 151, 'false'
  );
  
  -- Ayah 16 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3175,
    'وَوَرِثَ سُلَیۡمَـٰنُ دَاوُۥدَۖ وَقَالَ یَـٰۤأَیُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّیۡرِ وَأُوتِینَا مِن كُلِّ شَیۡءٍۖ إِنَّ هَـٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِینُ',
    'وورث سليمان داوود وقال يا ايها الناس علمنا منطق الطير واوتينا من كل شيء ان هذا لهو الفضل المبين',
    'وَوَرِثَ سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نُ دَاوُ<rule class=madda_normal>ۥ</rule>دَ‌ۖ وَقَالَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ عُلِّمۡنَا مَ<rule class=ikhafa>نط</rule>ِقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرِ وَأُوتِينَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ شَىۡءٍ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَهُوَ <rule class=ham_wasl>ٱ</rule>لۡفَضۡلُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ١٦',
    16, 19, 5, 378, 328, 151, 'false'
  );
  
  -- Ayah 17 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3176,
    'وَحُشِرَ لِسُلَیۡمَـٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّیۡرِ فَهُمۡ یُوزَعُونَ',
    'وحشر لسليمان جنوده من الجن والانس والطير فهم يوزعون',
    'وَحُشِرَ لِسُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ جُنُودُهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرِ فَهُمۡ يُوزَع<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 19, 5, 378, 328, 151, 'false'
  );
  
  -- Ayah 18 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3177,
    'حَتَّىٰۤ إِذَاۤ أَتَوۡا۟ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةࣱ یَـٰۤأَیُّهَا ٱلنَّمۡلُ ٱدۡخُلُوا۟ مَسَـٰكِنَكُمۡ لَا یَحۡطِمَنَّكُمۡ سُلَیۡمَـٰنُ وَجُنُودُهُۥ وَهُمۡ لَا یَشۡعُرُونَ',
    'حتى اذا اتوا على واد النمل قالت نملة يا ايها النمل ادخلوا مساكنكم لا يحطمنكم سليمان وجنوده وهم لا يشعرون',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَتَوۡ<rule class=slnt>اۡ</rule> عَلَىٰ وَادِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َمۡلِ قَالَتۡ نَمۡلَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َمۡلُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> مَسَ<rule class=madda_normal>ـٰ</rule>كِنَكُمۡ لَا يَحۡطِمَ<rule class=ghunnah>نّ</rule>َكُمۡ سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نُ وَجُنُودُهُ<rule class=madda_normal>ۥ</rule> وَهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 19, 5, 378, 328, 151, 'false'
  );
  
  -- Ayah 19 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3178,
    'فَتَبَسَّمَ ضَاحِكࣰا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِیۤ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِیۤ أَنۡعَمۡتَ عَلَیَّ وَعَلَىٰ وَ ٰ⁠لِدَیَّ وَأَنۡ أَعۡمَلَ صَـٰلِحࣰا تَرۡضَىٰهُ وَأَدۡخِلۡنِی بِرَحۡمَتِكَ فِی عِبَادِكَ ٱلصَّـٰلِحِینَ',
    'فتبسم ضاحكا من قولها وقال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلى والدي وان اعمل صالحا ترضاه وادخلني برحمتك في عبادك الصالحين',
    'فَتَبَسَّمَ ضَاحِ<rule class=idgham_ghunnah>كًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡ أَشۡكُرَ نِعۡمَتَكَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡعَمۡتَ عَلَىَّ وَعَلَىٰ و<rule class=madda_normal>ٰ</rule>لِدَىَّ وَأَنۡ أَعۡمَلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ت</rule>َرۡضَ<rule class=madda_normal>ـٰ</rule>هُ وَأَ<rule class=qalaqah>دۡ</rule>خِلۡنِى بِرَحۡمَتِكَ فِى عِبَادِكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ١٩',
    19, 19, 5, 378, 328, 151, 'false'
  );
  
  -- Ayah 20 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3179,
    'وَتَفَقَّدَ ٱلطَّیۡرَ فَقَالَ مَا لِیَ لَاۤ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَاۤىِٕبِینَ',
    'وتفقد الطير فقال ما لي لا ارى الهدهد ام كان من الغائبين',
    'وَتَفَقَّدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرَ فَقَالَ مَا لِىَ ل<rule class=madda_obligatory_monfasel>َآ</rule> أَرَى <rule class=ham_wasl>ٱ</rule>لۡهُ<rule class=qalaqah>دۡ</rule>هُدَ أَمۡ كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِب<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 19, 5, 378, 328, 151, 'false'
  );
  
  -- Ayah 21 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3180,
    'لَأُعَذِّبَنَّهُۥ عَذَابࣰا شَدِیدًا أَوۡ لَأَا۟ذۡبَحَنَّهُۥۤ أَوۡ لَیَأۡتِیَنِّی بِسُلۡطَـٰنࣲ مُّبِینࣲ',
    'لاعذبنه عذابا شديدا او لاذبحنه او لياتيني بسلطان مبين',
    'لَأُعَذِّبَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َدِيدًا أَوۡ لَأَ<rule class=slnt>اۡ</rule>ذۡبَحَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَوۡ لَيَأۡتِيَ<rule class=ghunnah>نّ</rule>ِى بِسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٢١',
    21, 19, 5, 378, 328, 151, 'false'
  );
  
  -- Ayah 22 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3181,
    'فَمَكَثَ غَیۡرَ بَعِیدࣲ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإࣲ یَقِینٍ',
    'فمكث غير بعيد فقال احطت بما لم تحط به وجئتك من سبا بنبا يقين',
    'فَمَكَثَ غَيۡرَ بَعِي<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ف</rule>َقَالَ أَحَطتُ بِمَا لَمۡ تُحِ<rule class=qalaqah>طۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> وَجِئۡتُكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبَ<rule class=iqlab>إِۭ</rule> <rule class=iqlab>ب</rule>ِنَبَ<rule class=idgham_ghunnah>إٍ</rule> <rule class=idgham_ghunnah>ي</rule>َق<rule class=madda_permissible>ِي</rule>نٍ ٢٢',
    22, 19, 5, 378, 328, 151, 'false'
  );
  
  -- Ayah 23 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3182,
    'إِنِّی وَجَدتُّ ٱمۡرَأَةࣰ تَمۡلِكُهُمۡ وَأُوتِیَتۡ مِن كُلِّ شَیۡءࣲ وَلَهَا عَرۡشٌ عَظِیمࣱ',
    'اني وجدت امراة تملكهم واوتيت من كل شيء ولها عرش عظيم',
    'إِ<rule class=ghunnah>نّ</rule>ِى وَجَ<rule class=idgham_mutajanisayn>د</rule>تُّ <rule class=ham_wasl>ٱ</rule>مۡرَأَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َمۡلِكُهُمۡ وَأُوتِيَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَهَا عَرۡشٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٢٣',
    23, 19, 5, 379, 328, 151, 'false'
  );
  
  -- Ayah 24 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3183,
    'وَجَدتُّهَا وَقَوۡمَهَا یَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِیلِ فَهُمۡ لَا یَهۡتَدُونَ',
    'وجدتها وقومها يسجدون للشمس من دون الله وزين لهم الشيطان اعمالهم فصدهم عن السبيل فهم لا يهتدون',
    'وَجَ<rule class=idgham_mutajanisayn>د</rule>تُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَزَيَّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ فَصَدَّهُمۡ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ فَهُمۡ لَا يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 19, 5, 379, 328, 151, 'false'
  );
  
  -- Ayah 25 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3184,
    'أَلَّا یَسۡجُدُوا۟ لِلَّهِ ٱلَّذِی یُخۡرِجُ ٱلۡخَبۡءَ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَیَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ',
    'الا يسجدوا لله الذي يخرج الخبء في السماوات والارض ويعلم ما تخفون وما تعلنون',
    'أَلَّا يَسۡجُدُو<rule class=slnt>اۡ</rule> لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى يُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=qalaqah>بۡ</rule>ءَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِن<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 19, 5, 379, 328, 151, 'false'
  );
  
  -- Ayah 26 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3185,
    'ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِیمِ ۩',
    'الله لا اله الا هو رب العرش العظيم',
    'ٱللَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ رَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ <rule class=ham_wasl>ٱ</rule>لۡعَظِ<rule class=madda_permissible>ي</rule>مِ ۩ ٢٦',
    26, 19, 5, 379, 328, 151, '{"id":9,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 27 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3186,
    '۞ قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَـٰذِبِینَ',
    'قال سننظر اصدقت ام كنت من الكاذبين',
    '۞قَالَ سَنَ<rule class=ikhafa>نظ</rule>ُرُ أَصَدَ<rule class=qalaqah>قۡ</rule>تَ أَمۡ كُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 19, 5, 379, 328, 152, 'false'
  );
  
  -- Ayah 28 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3187,
    'ٱذۡهَب بِّكِتَـٰبِی هَـٰذَا فَأَلۡقِهۡ إِلَیۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا یَرۡجِعُونَ',
    'اذهب بكتابي هذا فالقه اليهم ثم تول عنهم فانظر ماذا يرجعون',
    'ٱذۡهَب بِّكِتَ<rule class=madda_normal>ـٰ</rule>بِى هَ<rule class=madda_normal>ـٰ</rule>ذَا فَأَلۡقِهۡ إِلَيۡهِمۡ ثُ<rule class=ghunnah>مّ</rule>َ تَوَلَّ عَنۡهُمۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ مَاذَا يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 19, 5, 379, 328, 152, 'false'
  );
  
  -- Ayah 29 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3188,
    'قَالَتۡ یَـٰۤأَیُّهَا ٱلۡمَلَؤُا۟ إِنِّیۤ أُلۡقِیَ إِلَیَّ كِتَـٰبࣱ كَرِیمٌ',
    'قالت يا ايها الملا اني القي الي كتاب كريم',
    'قَالَتۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمَلَؤُ<rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُلۡقِىَ إِلَىَّ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٢٩',
    29, 19, 5, 379, 328, 152, 'false'
  );
  
  -- Ayah 30 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3189,
    'إِنَّهُۥ مِن سُلَیۡمَـٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ',
    'انه من سليمان وانه بسم الله الرحمن الرحيم',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِسۡمِ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مِ ٣٠',
    30, 19, 5, 379, 328, 152, 'false'
  );
  
  -- Ayah 31 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3190,
    'أَلَّا تَعۡلُوا۟ عَلَیَّ وَأۡتُونِی مُسۡلِمِینَ',
    'الا تعلوا علي واتوني مسلمين',
    'أَلَّا تَعۡلُو<rule class=slnt>اۡ</rule> عَلَىَّ وَأۡتُونِى مُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 19, 5, 379, 328, 152, 'false'
  );
  
  -- Ayah 32 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3191,
    'قَالَتۡ یَـٰۤأَیُّهَا ٱلۡمَلَؤُا۟ أَفۡتُونِی فِیۤ أَمۡرِی مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ',
    'قالت يا ايها الملا افتوني في امري ما كنت قاطعة امرا حتى تشهدون',
    'قَالَتۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمَلَؤُ<rule class=slnt>اۡ</rule> أَفۡتُونِى ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمۡرِى مَا كُ<rule class=ikhafa>نت</rule>ُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَد<rule class=madda_permissible>ُو</rule>نِ ٣٢',
    32, 19, 5, 379, 329, 152, 'false'
  );
  
  -- Ayah 33 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3192,
    'قَالُوا۟ نَحۡنُ أُو۟لُوا۟ قُوَّةࣲ وَأُو۟لُوا۟ بَأۡسࣲ شَدِیدࣲ وَٱلۡأَمۡرُ إِلَیۡكِ فَٱنظُرِی مَاذَا تَأۡمُرِینَ',
    'قالوا نحن اولو قوة واولو باس شديد والامر اليك فانظري ماذا تامرين',
    'قَالُو<rule class=slnt>اۡ</rule> نَحۡنُ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> قُوَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َأُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> بَأۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ إِلَيۡكِ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرِى مَاذَا تَأۡمُر<rule class=madda_permissible>ِي</rule>نَ ٣٣',
    33, 19, 5, 379, 329, 152, 'false'
  );
  
  -- Ayah 34 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3193,
    'قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُوا۟ قَرۡیَةً أَفۡسَدُوهَا وَجَعَلُوۤا۟ أَعِزَّةَ أَهۡلِهَاۤ أَذِلَّةࣰۚ وَكَذَ ٰ⁠لِكَ یَفۡعَلُونَ',
    'قالت ان الملوك اذا دخلوا قرية افسدوها وجعلوا اعزة اهلها اذلة وكذلك يفعلون',
    'قَالَتۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُلُوكَ إِذَا دَخَلُو<rule class=slnt>اۡ</rule> قَرۡيَةً أَفۡسَدُوهَا وَجَعَل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَعِزَّةَ أَهۡلِه<rule class=madda_obligatory_monfasel>َآ</rule> أَذِلَّ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َكَذ<rule class=madda_normal>ٰ</rule>لِكَ يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 19, 5, 379, 329, 152, 'false'
  );
  
  -- Ayah 35 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3194,
    'وَإِنِّی مُرۡسِلَةٌ إِلَیۡهِم بِهَدِیَّةࣲ فَنَاظِرَةُۢ بِمَ یَرۡجِعُ ٱلۡمُرۡسَلُونَ',
    'واني مرسلة اليهم بهدية فناظرة بم يرجع المرسلون',
    'وَإِ<rule class=ghunnah>نّ</rule>ِى مُرۡسِلَةٌ إِلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَدِيَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َنَاظِرَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِمَ يَرۡجِعُ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 19, 5, 379, 329, 152, 'false'
  );
  
  -- Ayah 36 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3195,
    'فَلَمَّا جَاۤءَ سُلَیۡمَـٰنَ قَالَ أَتُمِدُّونَنِ بِمَالࣲ فَمَاۤ ءَاتَىٰنِۦَ ٱللَّهُ خَیۡرࣱ مِّمَّاۤ ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِیَّتِكُمۡ تَفۡرَحُونَ',
    'فلما جاء سليمان قال اتمدونن بمال فما اتاني الله خير مما اتاكم بل انتم بهديتكم تفرحون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ قَالَ أَتُمِدُّونَنِ بِمَا<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>ن<rule class=madda_normal>ِۦ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَدِيَّتِكُمۡ تَفۡرَح<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 37 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3196,
    'ٱرۡجِعۡ إِلَیۡهِمۡ فَلَنَأۡتِیَنَّهُم بِجُنُودࣲ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَاۤ أَذِلَّةࣰ وَهُمۡ صَـٰغِرُونَ',
    'ارجع اليهم فلناتينهم بجنود لا قبل لهم بها ولنخرجنهم منها اذلة وهم صاغرون',
    'ٱرۡجِعۡ إِلَيۡهِمۡ فَلَنَأۡتِيَ<rule class=ghunnah>نّ</rule>َه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِجُنُو<rule class=idgham_wo_ghunnah>دٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا قِبَلَ لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا وَلَنُخۡرِجَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡه<rule class=madda_obligatory_monfasel>َآ</rule> أَذِلَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ صَ<rule class=madda_normal>ـٰ</rule>غِر<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 38 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3197,
    'قَالَ یَـٰۤأَیُّهَا ٱلۡمَلَؤُا۟ أَیُّكُمۡ یَأۡتِینِی بِعَرۡشِهَا قَبۡلَ أَن یَأۡتُونِی مُسۡلِمِینَ',
    'قال يا ايها الملا ايكم ياتيني بعرشها قبل ان ياتوني مسلمين',
    'قَالَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمَلَؤُ<rule class=slnt>اۡ</rule> أَيُّكُمۡ يَأۡتِينِى بِعَرۡشِهَا قَ<rule class=qalaqah>بۡ</rule>لَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتُونِى مُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٣٨',
    38, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 39 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3198,
    'قَالَ عِفۡرِیتࣱ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِیكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّی عَلَیۡهِ لَقَوِیٌّ أَمِینࣱ',
    'قال عفريت من الجن انا اتيك به قبل ان تقوم من مقامك واني عليه لقوي امين',
    'قَالَ عِفۡرِي<rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ أَنَاۡ ءَاتِيكَ بِه<rule class=madda_normal>ِۦ</rule> قَ<rule class=qalaqah>بۡ</rule>لَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُومَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّقَامِكَ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>ِى عَلَيۡهِ لَقَوِىٌّ أَم<rule class=madda_permissible>ِي</rule>نٌ ٣٩',
    39, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 40 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3199,
    'قَالَ ٱلَّذِی عِندَهُۥ عِلۡمࣱ مِّنَ ٱلۡكِتَـٰبِ أَنَا۠ ءَاتِیكَ بِهِۦ قَبۡلَ أَن یَرۡتَدَّ إِلَیۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَـٰذَا مِن فَضۡلِ رَبِّی لِیَبۡلُوَنِیۤ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا یَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّی غَنِیࣱّ كَرِیمࣱ',
    'قال الذي عنده علم من الكتاب انا اتيك به قبل ان يرتد اليك طرفك فلما راه مستقرا عنده قال هذا من فضل ربي ليبلوني ااشكر ام اكفر ومن شكر فانما يشكر لنفسه ومن كفر فان ربي غني كريم',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِى عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> عِلۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ أَنَاۡ ءَاتِيكَ بِه<rule class=madda_normal>ِۦ</rule> قَ<rule class=qalaqah>بۡ</rule>لَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َرۡتَدَّ إِلَيۡكَ طَرۡفُكَ‌ۚ فَلَ<rule class=ghunnah>مّ</rule>َا رَءَاهُ مُسۡتَقِرًّا عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> قَالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِ رَبِّى لِيَ<rule class=qalaqah>بۡ</rule>لُوَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَأَشۡكُرُ أَمۡ أَكۡفُرُ‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َكَرَ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَشۡكُرُ لِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ فَإِ<rule class=ghunnah>نّ</rule>َ رَبِّى غَنِ<rule class=ikhafa>ىٌّ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٤٠',
    40, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 41 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3200,
    'قَالَ نَكِّرُوا۟ لَهَا عَرۡشَهَا نَنظُرۡ أَتَهۡتَدِیۤ أَمۡ تَكُونُ مِنَ ٱلَّذِینَ لَا یَهۡتَدُونَ',
    'قال نكروا لها عرشها ننظر اتهتدي ام تكون من الذين لا يهتدون',
    'قَالَ نَكِّرُو<rule class=slnt>اۡ</rule> لَهَا عَرۡشَهَا نَ<rule class=ikhafa>نظ</rule>ُرۡ أَتَهۡتَد<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمۡ تَكُونُ مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 42 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3201,
    'فَلَمَّا جَاۤءَتۡ قِیلَ أَهَـٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِینَا ٱلۡعِلۡمَ مِن قَبۡلِهَا وَكُنَّا مُسۡلِمِینَ',
    'فلما جاءت قيل اهكذا عرشك قالت كانه هو واوتينا العلم من قبلها وكنا مسلمين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ قِيلَ أَهَ<rule class=madda_normal>ـٰ</rule>كَذَا عَرۡشُكِ‌ۖ قَالَتۡ كَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ‌ۚ وَأُوتِينَا <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهَا وَكُ<rule class=ghunnah>نّ</rule>َا مُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 43 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3202,
    'وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن قَوۡمࣲ كَـٰفِرِینَ',
    'وصدها ما كانت تعبد من دون الله انها كانت من قوم كافرين',
    'وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهَا كَانَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ك</rule>َ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٤٣',
    43, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 44 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3203,
    'قِیلَ لَهَا ٱدۡخُلِی ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةࣰ وَكَشَفَتۡ عَن سَاقَیۡهَاۚ قَالَ إِنَّهُۥ صَرۡحࣱ مُّمَرَّدࣱ مِّن قَوَارِیرَۗ قَالَتۡ رَبِّ إِنِّی ظَلَمۡتُ نَفۡسِی وَأَسۡلَمۡتُ مَعَ سُلَیۡمَـٰنَ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'قيل لها ادخلي الصرح فلما راته حسبته لجة وكشفت عن ساقيها قال انه صرح ممرد من قوارير قالت رب اني ظلمت نفسي واسلمت مع سليمان لله رب العالمين',
    'قِيلَ لَهَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّرۡحَ‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا رَأَتۡهُ حَسِبَتۡهُ لُجَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َكَشَفَتۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َاقَيۡهَا‌ۚ قَالَ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> صَرۡ<rule class=idgham_ghunnah>حٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّمَرَّ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوَارِيرَ‌ۗ قَالَتۡ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى ظَلَمۡتُ نَفۡسِى وَأَسۡلَمۡتُ مَعَ سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ لِلَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٤٤',
    44, 19, 5, 380, 329, 152, 'false'
  );
  
  -- Ayah 45 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3204,
    'وَلَقَدۡ أَرۡسَلۡنَاۤ إِلَىٰ ثَمُودَ أَخَاهُمۡ صَـٰلِحًا أَنِ ٱعۡبُدُوا۟ ٱللَّهَ فَإِذَا هُمۡ فَرِیقَانِ یَخۡتَصِمُونَ',
    'ولقد ارسلنا الى ثمود اخاهم صالحا ان اعبدوا الله فاذا هم فريقان يختصمون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ ثَمُودَ أَخَاهُمۡ صَ<rule class=madda_normal>ـٰ</rule>لِحًا أَنِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ فَإِذَا هُمۡ فَرِيقَانِ يَخۡتَصِم<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 46 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3205,
    'قَالَ یَـٰقَوۡمِ لِمَ تَسۡتَعۡجِلُونَ بِٱلسَّیِّئَةِ قَبۡلَ ٱلۡحَسَنَةِۖ لَوۡلَا تَسۡتَغۡفِرُونَ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ',
    'قال يا قوم لم تستعجلون بالسيئة قبل الحسنة لولا تستغفرون الله لعلكم ترحمون',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ لِمَ تَسۡتَعۡجِلُونَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةِ قَ<rule class=qalaqah>بۡ</rule>لَ <rule class=ham_wasl>ٱ</rule>لۡحَسَنَةِ‌ۖ لَوۡلَا تَسۡتَغۡفِرُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَلَّكُمۡ تُرۡحَم<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 47 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3206,
    'قَالُوا۟ ٱطَّیَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَـٰۤىِٕرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمࣱ تُفۡتَنُونَ',
    'قالوا اطيرنا بك وبمن معك قال طائركم عند الله بل انتم قوم تفتنون',
    'قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>طَّيَّرۡنَا بِكَ وَبِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعَكَ‌ۚ قَالَ طَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرُكُمۡ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ بَلۡ أَ<rule class=ikhafa>نت</rule>ُمۡ قَوۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ت</rule>ُفۡتَن<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 48 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3207,
    'وَكَانَ فِی ٱلۡمَدِینَةِ تِسۡعَةُ رَهۡطࣲ یُفۡسِدُونَ فِی ٱلۡأَرۡضِ وَلَا یُصۡلِحُونَ',
    'وكان في المدينة تسعة رهط يفسدون في الارض ولا يصلحون',
    'وَكَانَ فِى <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ تِسۡعَةُ رَهۡ<rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُفۡسِدُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا يُصۡلِح<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 49 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3208,
    'قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَیِّتَنَّهُۥ وَأَهۡلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِیِّهِۦ مَا شَهِدۡنَا مَهۡلِكَ أَهۡلِهِۦ وَإِنَّا لَصَـٰدِقُونَ',
    'قالوا تقاسموا بالله لنبيتنه واهله ثم لنقولن لوليه ما شهدنا مهلك اهله وانا لصادقون',
    'قَالُو<rule class=slnt>اۡ</rule> تَقَاسَمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ لَنُبَيِّتَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> وَأَهۡلَهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ لَنَقُولَ<rule class=ghunnah>نّ</rule>َ لِوَلِيِّه<rule class=madda_normal>ِۦ</rule> مَا شَهِ<rule class=qalaqah>دۡ</rule>نَا مَهۡلِكَ أَهۡلِه<rule class=madda_normal>ِۦ</rule> وَإِ<rule class=ghunnah>نّ</rule>َا لَصَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 50 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3209,
    'وَمَكَرُوا۟ مَكۡرࣰا وَمَكَرۡنَا مَكۡرࣰا وَهُمۡ لَا یَشۡعُرُونَ',
    'ومكروا مكرا ومكرنا مكرا وهم لا يشعرون',
    'وَمَكَرُو<rule class=slnt>اۡ</rule> مَكۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َمَكَرۡنَا مَكۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 51 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3210,
    'فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ مَكۡرِهِمۡ أَنَّا دَمَّرۡنَـٰهُمۡ وَقَوۡمَهُمۡ أَجۡمَعِینَ',
    'فانظر كيف كان عاقبة مكرهم انا دمرناهم وقومهم اجمعين',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ مَكۡرِهِمۡ أَ<rule class=ghunnah>نّ</rule>َا دَ<rule class=ghunnah>مّ</rule>َرۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَقَوۡمَهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٥١',
    51, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 52 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3211,
    'فَتِلۡكَ بُیُوتُهُمۡ خَاوِیَةَۢ بِمَا ظَلَمُوۤا۟ۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَعۡلَمُونَ',
    'فتلك بيوتهم خاوية بما ظلموا ان في ذلك لاية لقوم يعلمون',
    'فَتِلۡكَ بُيُوتُهُمۡ خَاوِيَ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>ِمَا ظَلَم<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۗ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 53 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3212,
    'وَأَنجَیۡنَا ٱلَّذِینَ ءَامَنُوا۟ وَكَانُوا۟ یَتَّقُونَ',
    'وانجينا الذين امنوا وكانوا يتقون',
    'وَأَ<rule class=ikhafa>نج</rule>َيۡنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَكَانُو<rule class=slnt>اۡ</rule> يَتَّق<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 54 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3213,
    'وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦۤ أَتَأۡتُونَ ٱلۡفَـٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ',
    'ولوطا اذ قال لقومه اتاتون الفاحشة وانتم تبصرون',
    'وَلُوطًا إِذۡ قَالَ لِقَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَتَأۡتُونَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>حِشَةَ وَأَ<rule class=ikhafa>نت</rule>ُمۡ تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 55 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3214,
    'أَىِٕنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةࣰ مِّن دُونِ ٱلنِّسَاۤءِۚ بَلۡ أَنتُمۡ قَوۡمࣱ تَجۡهَلُونَ',
    'ائنكم لتاتون الرجال شهوة من دون النساء بل انتم قوم تجهلون',
    'أَئِ<rule class=ghunnah>نّ</rule>َكُمۡ لَتَأۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّجَالَ شَهۡوَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۚ بَلۡ أَ<rule class=ikhafa>نت</rule>ُمۡ قَوۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>هَل<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 19, 5, 381, 330, 152, 'false'
  );
  
  -- Ayah 56 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3215,
    '۞ فَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوۤا۟ أَخۡرِجُوۤا۟ ءَالَ لُوطࣲ مِّن قَرۡیَتِكُمۡۖ إِنَّهُمۡ أُنَاسࣱ یَتَطَهَّرُونَ',
    'فما كان جواب قومه الا ان قالوا اخرجوا ال لوط من قريتكم انهم اناس يتطهرون',
    '۞فَمَا كَانَ جَوَابَ قَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَخۡرِج<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَالَ لُو<rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَتِكُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ أُنَا<rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>ي</rule>َتَطَهَّر<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 20, 5, 382, 330, 153, 'false'
  );
  
  -- Ayah 57 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3216,
    'فَأَنجَیۡنَـٰهُ وَأَهۡلَهُۥۤ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَـٰهَا مِنَ ٱلۡغَـٰبِرِینَ',
    'فانجيناه واهله الا امراته قدرناها من الغابرين',
    'فَأَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَأَهۡلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>مۡرَأَتَهُ<rule class=madda_normal>ۥ</rule> قَدَّرۡنَ<rule class=madda_normal>ـٰ</rule>هَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٥٧',
    57, 20, 5, 382, 330, 153, 'false'
  );
  
  -- Ayah 58 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3217,
    'وَأَمۡطَرۡنَا عَلَیۡهِم مَّطَرࣰاۖ فَسَاۤءَ مَطَرُ ٱلۡمُنذَرِینَ',
    'وامطرنا عليهم مطرا فساء مطر المنذرين',
    'وَأَمۡطَرۡنَا عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّطَ<rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَطَرُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نذ</rule>َر<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 20, 5, 382, 330, 153, 'false'
  );
  
  -- Ayah 59 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3218,
    'قُلِ ٱلۡحَمۡدُ لِلَّهِ وَسَلَـٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِینَ ٱصۡطَفَىٰۤۗ ءَاۤللَّهُ خَیۡرٌ أَمَّا یُشۡرِكُونَ',
    'قل الحمد لله وسلام على عباده الذين اصطفى الله خير اما يشركون',
    'قُلِ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ وَسَلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَىٰ عِبَادِهِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>صۡطَفَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۗ</rule> ءَآللَّهُ خَيۡرٌ أَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 20, 5, 382, 331, 153, 'false'
  );
  
  -- Ayah 60 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3219,
    'أَمَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَنۢبَتۡنَا بِهِۦ حَدَاۤىِٕقَ ذَاتَ بَهۡجَةࣲ مَّا كَانَ لَكُمۡ أَن تُنۢبِتُوا۟ شَجَرَهَاۤۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ بَلۡ هُمۡ قَوۡمࣱ یَعۡدِلُونَ',
    'امن خلق السماوات والارض وانزل لكم من السماء ماء فانبتنا به حدائق ذات بهجة ما كان لكم ان تنبتوا شجرها االه مع الله بل هم قوم يعدلون',
    'أَ<rule class=ghunnah>مّ</rule>َنۡ خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَأَ<rule class=ikhafa>نز</rule>َلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=iqlab>نۢب</rule>َتۡنَا بِه<rule class=madda_normal>ِۦ</rule> حَد<rule class=madda_obligatory_mottasel>َا</rule>ٓئِقَ ذَاتَ بَهۡجَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا كَانَ لَكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=iqlab>نۢب</rule>ِتُو<rule class=slnt>اۡ</rule> شَجَرَه<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> أَءِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ بَلۡ هُمۡ قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡدِل<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 20, 5, 382, 331, 153, 'false'
  );
  
  -- Ayah 61 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3220,
    'أَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارࣰا وَجَعَلَ خِلَـٰلَهَاۤ أَنۡهَـٰرࣰا وَجَعَلَ لَهَا رَوَ ٰ⁠سِیَ وَجَعَلَ بَیۡنَ ٱلۡبَحۡرَیۡنِ حَاجِزًاۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ',
    'امن جعل الارض قرارا وجعل خلالها انهارا وجعل لها رواسي وجعل بين البحرين حاجزا االه مع الله بل اكثرهم لا يعلمون',
    'أَ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َعَلَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ قَرَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ خِلَ<rule class=madda_normal>ـٰ</rule>لَه<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ لَهَا رَو<rule class=madda_normal>ٰ</rule>سِىَ وَجَعَلَ بَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَيۡنِ حَاجِزًا‌ۗ أَءِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 20, 5, 382, 331, 153, 'false'
  );
  
  -- Ayah 62 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3221,
    'أَمَّن یُجِیبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَیَكۡشِفُ ٱلسُّوۤءَ وَیَجۡعَلُكُمۡ خُلَفَاۤءَ ٱلۡأَرۡضِۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ قَلِیلࣰا مَّا تَذَكَّرُونَ',
    'امن يجيب المضطر اذا دعاه ويكشف السوء ويجعلكم خلفاء الارض االه مع الله قليلا ما تذكرون',
    'أَ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجِيبُ <rule class=ham_wasl>ٱ</rule>لۡمُضۡطَرَّ إِذَا دَعَاهُ وَيَكۡشِفُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ وَيَ<rule class=qalaqah>جۡ</rule>عَلُكُمۡ خُلَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ أَءِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 20, 5, 382, 331, 153, 'false'
  );
  
  -- Ayah 63 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3222,
    'أَمَّن یَهۡدِیكُمۡ فِی ظُلُمَـٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ وَمَن یُرۡسِلُ ٱلرِّیَـٰحَ بُشۡرَۢا بَیۡنَ یَدَیۡ رَحۡمَتِهِۦۤۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ تَعَـٰلَى ٱللَّهُ عَمَّا یُشۡرِكُونَ',
    'امن يهديكم في ظلمات البر والبحر ومن يرسل الرياح بشرا بين يدي رحمته االه مع الله تعالى الله عما يشركون',
    'أَ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِيكُمۡ فِى ظُلُمَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡبَرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرۡسِلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حَ بُشۡر<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَ يَدَىۡ رَحۡمَتِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۗ</rule> أَءِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ تَعَ<rule class=madda_normal>ـٰ</rule>لَى <rule class=ham_wasl>ٱ</rule>للَّهُ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 20, 5, 382, 331, 153, 'false'
  );
  
  -- Ayah 64 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3223,
    'أَمَّن یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ وَمَن یَرۡزُقُكُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ قُلۡ هَاتُوا۟ بُرۡهَـٰنَكُمۡ إِن كُنتُمۡ صَـٰدِقِینَ',
    'امن يبدا الخلق ثم يعيده ومن يرزقكم من السماء والارض االه مع الله قل هاتوا برهانكم ان كنتم صادقين',
    'أَ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>دَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَلۡقَ ثُ<rule class=ghunnah>مّ</rule>َ يُعِيدُهُ<rule class=madda_normal>ۥ</rule> وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َرۡزُقُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ أَءِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ قُلۡ هَاتُو<rule class=slnt>اۡ</rule> بُرۡهَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٦٤',
    64, 20, 5, 383, 331, 153, 'false'
  );
  
  -- Ayah 65 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3224,
    'قُل لَّا یَعۡلَمُ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ ٱلۡغَیۡبَ إِلَّا ٱللَّهُۚ وَمَا یَشۡعُرُونَ أَیَّانَ یُبۡعَثُونَ',
    'قل لا يعلم من في السماوات والارض الغيب الا الله وما يشعرون ايان يبعثون',
    'قُل لَّا يَعۡلَمُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبَ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَمَا يَشۡعُرُونَ أَيَّانَ يُ<rule class=qalaqah>بۡ</rule>عَث<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 20, 5, 383, 331, 153, 'false'
  );
  
  -- Ayah 66 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3225,
    'بَلِ ٱدَّ ٰ⁠رَكَ عِلۡمُهُمۡ فِی ٱلۡـَٔاخِرَةِۚ بَلۡ هُمۡ فِی شَكࣲّ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ',
    'بل ادارك علمهم في الاخرة بل هم في شك منها بل هم منها عمون',
    'بَلِ <rule class=ham_wasl>ٱ</rule>دّ<rule class=madda_normal>ٰ</rule>رَكَ عِلۡمُهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۚ بَلۡ هُمۡ فِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا‌ۖ بَلۡ ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا عَم<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 20, 5, 383, 331, 153, 'false'
  );
  
  -- Ayah 67 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3226,
    'وَقَالَ ٱلَّذِینَ كَفَرُوۤا۟ أَءِذَا كُنَّا تُرَ ٰ⁠بࣰا وَءَابَاۤؤُنَاۤ أَىِٕنَّا لَمُخۡرَجُونَ',
    'وقال الذين كفروا ااذا كنا ترابا واباؤنا ائنا لمخرجون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَءِذَا كُ<rule class=ghunnah>نّ</rule>َا تُر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُن<rule class=madda_obligatory_monfasel>َآ</rule> أَئِ<rule class=ghunnah>نّ</rule>َا لَمُخۡرَج<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 68 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3227,
    'لَقَدۡ وُعِدۡنَا هَـٰذَا نَحۡنُ وَءَابَاۤؤُنَا مِن قَبۡلُ إِنۡ هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ',
    'لقد وعدنا هذا نحن واباؤنا من قبل ان هذا الا اساطير الاولين',
    'لَقَ<rule class=qalaqah>دۡ</rule> وُعِ<rule class=qalaqah>دۡ</rule>نَا هَ<rule class=madda_normal>ـٰ</rule>ذَا نَحۡنُ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٦٨',
    68, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 69 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3228,
    'قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُجۡرِمِینَ',
    'قل سيروا في الارض فانظروا كيف كان عاقبة المجرمين',
    'قُلۡ سِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٦٩',
    69, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 70 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3229,
    'وَلَا تَحۡزَنۡ عَلَیۡهِمۡ وَلَا تَكُن فِی ضَیۡقࣲ مِّمَّا یَمۡكُرُونَ',
    'ولا تحزن عليهم ولا تكن في ضيق مما يمكرون',
    'وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى ضَيۡ<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَمۡكُر<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 71 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3230,
    'وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ويقولون متى هذا الوعد ان كنتم صادقين',
    'وَيَقُولُونَ مَتَىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡوَعۡدُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٧١',
    71, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 72 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3231,
    'قُلۡ عَسَىٰۤ أَن یَكُونَ رَدِفَ لَكُم بَعۡضُ ٱلَّذِی تَسۡتَعۡجِلُونَ',
    'قل عسى ان يكون ردف لكم بعض الذي تستعجلون',
    'قُلۡ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ رَدِفَ لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضُ <rule class=ham_wasl>ٱ</rule>لَّذِى تَسۡتَعۡجِل<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 73 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3232,
    'وَإِنَّ رَبَّكَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَشۡكُرُونَ',
    'وان ربك لذو فضل على الناس ولكن اكثرهم لا يشكرون',
    'وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَذُو فَضۡلٍ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 74 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3233,
    'وَإِنَّ رَبَّكَ لَیَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا یُعۡلِنُونَ',
    'وان ربك ليعلم ما تكن صدورهم وما يعلنون',
    'وَإِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَيَعۡلَمُ مَا تُكِ<rule class=ghunnah>نّ</rule>ُ صُدُورُهُمۡ وَمَا يُعۡلِن<rule class=madda_permissible>ُو</rule>نَ ٧٤',
    74, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 75 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3234,
    'وَمَا مِنۡ غَاۤىِٕبَةࣲ فِی ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ إِلَّا فِی كِتَـٰبࣲ مُّبِینٍ',
    'وما من غائبة في السماء والارض الا في كتاب مبين',
    'وَمَا مِنۡ غ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِبَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِلَّا فِى كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٧٥',
    75, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 76 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3235,
    'إِنَّ هَـٰذَا ٱلۡقُرۡءَانَ یَقُصُّ عَلَىٰ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ أَكۡثَرَ ٱلَّذِی هُمۡ فِیهِ یَخۡتَلِفُونَ',
    'ان هذا القران يقص على بني اسرائيل اكثر الذي هم فيه يختلفون',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ يَقُصُّ عَلَىٰ بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule>لَّذِى هُمۡ فِيهِ يَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ٧٦',
    76, 20, 5, 383, 332, 153, 'false'
  );
  
  -- Ayah 77 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3236,
    'وَإِنَّهُۥ لَهُدࣰى وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِینَ',
    'وانه لهدى ورحمة للمؤمنين',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٧٧',
    77, 20, 5, 384, 332, 153, 'false'
  );
  
  -- Ayah 78 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3237,
    'إِنَّ رَبَّكَ یَقۡضِی بَیۡنَهُم بِحُكۡمِهِۦۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡعَلِیمُ',
    'ان ربك يقضي بينهم بحكمه وهو العزيز العليم',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ يَ<rule class=qalaqah>قۡ</rule>ضِى بَيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِحُكۡمِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٧٨',
    78, 20, 5, 384, 332, 153, 'false'
  );
  
  -- Ayah 79 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3238,
    'فَتَوَكَّلۡ عَلَى ٱللَّهِۖ إِنَّكَ عَلَى ٱلۡحَقِّ ٱلۡمُبِینِ',
    'فتوكل على الله انك على الحق المبين',
    'فَتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡحَقِّ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نِ ٧٩',
    79, 20, 5, 384, 332, 153, 'false'
  );
  
  -- Ayah 80 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3239,
    'إِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَاۤءَ إِذَا وَلَّوۡا۟ مُدۡبِرِینَ',
    'انك لا تسمع الموتى ولا تسمع الصم الدعاء اذا ولوا مدبرين',
    'إِ<rule class=ghunnah>نّ</rule>َكَ لَا تُسۡمِعُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ وَلَا تُسۡمِعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِذَا وَلَّوۡ<rule class=slnt>اۡ</rule> مُ<rule class=qalaqah>دۡ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٨٠',
    80, 20, 5, 384, 332, 153, 'false'
  );
  
  -- Ayah 81 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3240,
    'وَمَاۤ أَنتَ بِهَـٰدِی ٱلۡعُمۡیِ عَن ضَلَـٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن یُؤۡمِنُ بِـَٔایَـٰتِنَا فَهُم مُّسۡلِمُونَ',
    'وما انت بهادي العمي عن ضلالتهم ان تسمع الا من يؤمن باياتنا فهم مسلمون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ بِهَ<rule class=madda_normal>ـٰ</rule>دِى <rule class=ham_wasl>ٱ</rule>لۡعُمۡىِ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَ<rule class=madda_normal>ـٰ</rule>لَتِهِمۡ‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُسۡمِعُ إِلَّا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 20, 5, 384, 332, 153, 'false'
  );
  
  -- Ayah 82 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3241,
    '۞ وَإِذَا وَقَعَ ٱلۡقَوۡلُ عَلَیۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَاۤبَّةࣰ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔایَـٰتِنَا لَا یُوقِنُونَ',
    'واذا وقع القول عليهم اخرجنا لهم دابة من الارض تكلمهم ان الناس كانوا باياتنا لا يوقنون',
    '۞وَإِذَا وَقَعَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ عَلَيۡهِمۡ أَخۡرَ<rule class=qalaqah>جۡ</rule>نَا لَهُمۡ د<rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ تُكَلِّمُهُمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ كَانُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا لَا يُوقِن<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 20, 5, 384, 332, 154, 'false'
  );
  
  -- Ayah 83 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3242,
    'وَیَوۡمَ نَحۡشُرُ مِن كُلِّ أُمَّةࣲ فَوۡجࣰا مِّمَّن یُكَذِّبُ بِـَٔایَـٰتِنَا فَهُمۡ یُوزَعُونَ',
    'ويوم نحشر من كل امة فوجا ممن يكذب باياتنا فهم يوزعون',
    'وَيَوۡمَ نَحۡشُرُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َوۡ<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَذِّبُ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَهُمۡ يُوزَع<rule class=madda_permissible>ُو</rule>نَ ٨٣',
    83, 20, 5, 384, 333, 154, 'false'
  );
  
  -- Ayah 84 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3243,
    'حَتَّىٰۤ إِذَا جَاۤءُو قَالَ أَكَذَّبۡتُم بِـَٔایَـٰتِی وَلَمۡ تُحِیطُوا۟ بِهَا عِلۡمًا أَمَّاذَا كُنتُمۡ تَعۡمَلُونَ',
    'حتى اذا جاءوا قال اكذبتم باياتي ولم تحيطوا بها علما اماذا كنتم تعملون',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو قَالَ أَكَذَّ<rule class=qalaqah>بۡ</rule>ت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِى وَلَمۡ تُحِيطُو<rule class=slnt>اۡ</rule> بِهَا عِلۡمًا أَ<rule class=ghunnah>مّ</rule>َاذَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 20, 5, 384, 333, 154, 'false'
  );
  
  -- Ayah 85 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3244,
    'وَوَقَعَ ٱلۡقَوۡلُ عَلَیۡهِم بِمَا ظَلَمُوا۟ فَهُمۡ لَا یَنطِقُونَ',
    'ووقع القول عليهم بما ظلموا فهم لا ينطقون',
    'وَوَقَعَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا ظَلَمُو<rule class=slnt>اۡ</rule> فَهُمۡ لَا يَ<rule class=ikhafa>نط</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٨٥',
    85, 20, 5, 384, 333, 154, 'false'
  );
  
  -- Ayah 86 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3245,
    'أَلَمۡ یَرَوۡا۟ أَنَّا جَعَلۡنَا ٱلَّیۡلَ لِیَسۡكُنُوا۟ فِیهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'الم يروا انا جعلنا الليل ليسكنوا فيه والنهار مبصرا ان في ذلك لايات لقوم يؤمنون',
    'أَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َا جَعَلۡنَا <rule class=ham_wasl>ٱ</rule>لَّيۡلَ لِيَسۡكُنُو<rule class=slnt>اۡ</rule> فِيهِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ مُ<rule class=qalaqah>بۡ</rule>صِرًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٨٦',
    86, 20, 5, 384, 333, 154, 'false'
  );
  
  -- Ayah 87 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3246,
    'وَیَوۡمَ یُنفَخُ فِی ٱلصُّورِ فَفَزِعَ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَن فِی ٱلۡأَرۡضِ إِلَّا مَن شَاۤءَ ٱللَّهُۚ وَكُلٌّ أَتَوۡهُ دَ ٰ⁠خِرِینَ',
    'ويوم ينفخ في الصور ففزع من في السماوات ومن في الارض الا من شاء الله وكل اتوه داخرين',
    'وَيَوۡمَ يُ<rule class=ikhafa>نف</rule>َخُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ فَفَزِعَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَكُلٌّ أَتَوۡهُ د<rule class=madda_normal>ٰ</rule>خِر<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 20, 5, 384, 333, 154, 'false'
  );
  
  -- Ayah 88 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3247,
    'وَتَرَى ٱلۡجِبَالَ تَحۡسَبُهَا جَامِدَةࣰ وَهِیَ تَمُرُّ مَرَّ ٱلسَّحَابِۚ صُنۡعَ ٱللَّهِ ٱلَّذِیۤ أَتۡقَنَ كُلَّ شَیۡءٍۚ إِنَّهُۥ خَبِیرُۢ بِمَا تَفۡعَلُونَ',
    'وترى الجبال تحسبها جامدة وهي تمر مر السحاب صنع الله الذي اتقن كل شيء انه خبير بما تفعلون',
    'وَتَرَى <rule class=ham_wasl>ٱ</rule>لۡجِبَالَ تَحۡسَبُهَا جَامِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َهِىَ تَمُرُّ مَرَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّحَابِ‌ۚ صُنۡعَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَتۡقَنَ كُلَّ شَىۡءٍ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 20, 5, 384, 333, 154, 'false'
  );
  
  -- Ayah 89 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3248,
    'مَن جَاۤءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَیۡرࣱ مِّنۡهَا وَهُم مِّن فَزَعࣲ یَوۡمَىِٕذٍ ءَامِنُونَ',
    'من جاء بالحسنة فله خير منها وهم من فزع يومئذ امنون',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَسَنَةِ فَلَهُ<rule class=madda_normal>ۥ</rule> خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َزَ<rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَئِذٍ ءَامِن<rule class=madda_permissible>ُو</rule>نَ ٨٩',
    89, 20, 5, 385, 333, 154, 'false'
  );
  
  -- Ayah 90 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3249,
    'وَمَن جَاۤءَ بِٱلسَّیِّئَةِ فَكُبَّتۡ وُجُوهُهُمۡ فِی ٱلنَّارِ هَلۡ تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ',
    'ومن جاء بالسيئة فكبت وجوههم في النار هل تجزون الا ما كنتم تعملون',
    'وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةِ فَكُبَّتۡ وُجُوهُهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ هَلۡ تُ<rule class=qalaqah>جۡ</rule>زَوۡنَ إِلَّا مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٠',
    90, 20, 5, 385, 333, 154, 'false'
  );
  
  -- Ayah 91 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3250,
    'إِنَّمَاۤ أُمِرۡتُ أَنۡ أَعۡبُدَ رَبَّ هَـٰذِهِ ٱلۡبَلۡدَةِ ٱلَّذِی حَرَّمَهَا وَلَهُۥ كُلُّ شَیۡءࣲۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِینَ',
    'انما امرت ان اعبد رب هذه البلدة الذي حرمها وله كل شيء وامرت ان اكون من المسلمين',
    'إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُمِرۡتُ أَنۡ أَعۡبُدَ رَبَّ هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡبَلۡدَةِ <rule class=ham_wasl>ٱ</rule>لَّذِى حَرَّمَهَا وَلَهُ<rule class=madda_normal>ۥ</rule> كُلُّ ش<rule class=idgham_ghunnah>َىۡءٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأُمِرۡتُ أَنۡ أَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٩١',
    91, 20, 5, 385, 333, 154, 'false'
  );
  
  -- Ayah 92 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3251,
    'وَأَنۡ أَتۡلُوَا۟ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا یَهۡتَدِی لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَقُلۡ إِنَّمَاۤ أَنَا۠ مِنَ ٱلۡمُنذِرِینَ',
    'وان اتلو القران فمن اهتدى فانما يهتدي لنفسه ومن ضل فقل انما انا من المنذرين',
    'وَأَنۡ أَتۡلُوَ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ‌ۖ فَمَنِ <rule class=ham_wasl>ٱ</rule>هۡتَدَىٰ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَهۡتَدِى لِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَّ فَقُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نذ</rule>ِر<rule class=madda_permissible>ِي</rule>نَ ٩٢',
    92, 20, 5, 385, 333, 154, 'false'
  );
  
  -- Ayah 93 Surah An-Naml
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    27,
    3252,
    'وَقُلِ ٱلۡحَمۡدُ لِلَّهِ سَیُرِیكُمۡ ءَایَـٰتِهِۦ فَتَعۡرِفُونَهَاۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ',
    'وقل الحمد لله سيريكم اياته فتعرفونها وما ربك بغافل عما تعملون',
    'وَقُلِ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ سَيُرِيكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> فَتَعۡرِفُونَهَا‌ۚ وَمَا رَبُّكَ بِغَ<rule class=madda_normal>ـٰ</rule>فِلٍ عَ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٩٣',
    93, 20, 5, 385, 333, 154, 'false'
  );
  

-- Surah Al-Qasas
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (28, 'سُورَةُ القَصَصِ', 'Al-Qasas', 'The Stories', 'Meccan', 88);

  -- Ayah 1 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3253,
    'طسۤمۤ',
    'طسم',
    'ط<rule class=madda_necessary>سٓ</rule><rule class=madda_necessary>مٓ</rule> ١',
    1, 20, 5, 385, 334, 154, 'false'
  );
  
  -- Ayah 2 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3254,
    'تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡمُبِینِ',
    'تلك ايات الكتاب المبين',
    'تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نِ ٢',
    2, 20, 5, 385, 334, 154, 'false'
  );
  
  -- Ayah 3 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3255,
    'نَتۡلُوا۟ عَلَیۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمࣲ یُؤۡمِنُونَ',
    'نتلو عليك من نبا موسى وفرعون بالحق لقوم يؤمنون',
    'نَتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡكَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 20, 5, 385, 334, 154, 'false'
  );
  
  -- Ayah 4 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3256,
    'إِنَّ فِرۡعَوۡنَ عَلَا فِی ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِیَعࣰا یَسۡتَضۡعِفُ طَاۤىِٕفَةࣰ مِّنۡهُمۡ یُذَبِّحُ أَبۡنَاۤءَهُمۡ وَیَسۡتَحۡیِۦ نِسَاۤءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِینَ',
    'ان فرعون علا في الارض وجعل اهلها شيعا يستضعف طائفة منهم يذبح ابناءهم ويستحيي نساءهم انه كان من المفسدين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِرۡعَوۡنَ عَلَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَضۡعِفُ ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ يُذَبِّحُ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ وَيَسۡتَحۡى<rule class=madda_normal>ِۦ</rule> نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٤',
    4, 20, 5, 385, 334, 154, 'false'
  );
  
  -- Ayah 5 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3257,
    'وَنُرِیدُ أَن نَّمُنَّ عَلَى ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ فِی ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَىِٕمَّةࣰ وَنَجۡعَلَهُمُ ٱلۡوَ ٰ⁠رِثِینَ',
    'ونريد ان نمن على الذين استضعفوا في الارض ونجعلهم ائمة ونجعلهم الوارثين',
    'وَنُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّمُ<rule class=ghunnah>نّ</rule>َ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتُضۡعِفُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَنَ<rule class=qalaqah>جۡ</rule>عَلَهُمۡ أَئِ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َنَ<rule class=qalaqah>جۡ</rule>عَلَهُمُ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>رِث<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 20, 5, 385, 334, 154, 'false'
  );
  
  -- Ayah 6 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3258,
    'وَنُمَكِّنَ لَهُمۡ فِی ٱلۡأَرۡضِ وَنُرِیَ فِرۡعَوۡنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُوا۟ یَحۡذَرُونَ',
    'ونمكن لهم في الارض ونري فرعون وهامان وجنودهما منهم ما كانوا يحذرون',
    'وَنُمَكِّنَ لَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَنُرِىَ فِرۡعَوۡنَ وَهَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_normal>ـٰ</rule>نَ وَجُنُودَهُمَا مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَحۡذَر<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 20, 5, 386, 334, 154, 'false'
  );
  
  -- Ayah 7 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3259,
    'وَأَوۡحَیۡنَاۤ إِلَىٰۤ أُمِّ مُوسَىٰۤ أَنۡ أَرۡضِعِیهِۖ فَإِذَا خِفۡتِ عَلَیۡهِ فَأَلۡقِیهِ فِی ٱلۡیَمِّ وَلَا تَخَافِی وَلَا تَحۡزَنِیۤۖ إِنَّا رَاۤدُّوهُ إِلَیۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِینَ',
    'واوحينا الى ام موسى ان ارضعيه فاذا خفت عليه فالقيه في اليم ولا تخافي ولا تحزني انا رادوه اليك وجاعلوه من المرسلين',
    'وَأَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=ghunnah>مّ</rule>ِ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَنۡ أَرۡضِعِيهِ‌ۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِى <rule class=ham_wasl>ٱ</rule>لۡيَ<rule class=ghunnah>مّ</rule>ِ وَلَا تَخَافِى وَلَا تَحۡزَن<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َا ر<rule class=madda_necessary>َا</rule>ٓدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 20, 5, 386, 334, 154, 'false'
  );
  
  -- Ayah 8 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3260,
    'فَٱلۡتَقَطَهُۥۤ ءَالُ فِرۡعَوۡنَ لِیَكُونَ لَهُمۡ عَدُوࣰّا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا كَانُوا۟ خَـٰطِـِٔینَ',
    'فالتقطه ال فرعون ليكون لهم عدوا وحزنا ان فرعون وهامان وجنودهما كانوا خاطئين',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡتَقَطَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُو<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َحَزَنًا‌ۗ إِ<rule class=ghunnah>نّ</rule>َ فِرۡعَوۡنَ وَهَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_normal>ـٰ</rule>نَ وَجُنُودَهُمَا كَانُو<rule class=slnt>اۡ</rule> خَ<rule class=madda_normal>ـٰ</rule>طِــٔ<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 20, 5, 386, 334, 154, 'false'
  );
  
  -- Ayah 9 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3261,
    'وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَیۡنࣲ لِّی وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰۤ أَن یَنفَعَنَاۤ أَوۡ نَتَّخِذَهُۥ وَلَدࣰا وَهُمۡ لَا یَشۡعُرُونَ',
    'وقالت امرات فرعون قرت عين لي ولك لا تقتلوه عسى ان ينفعنا او نتخذه ولدا وهم لا يشعرون',
    'وَقَالَتِ <rule class=ham_wasl>ٱ</rule>مۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡ<rule class=idgham_wo_ghunnah>نٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّى وَلَكَ‌ۖ لَا تَ<rule class=qalaqah>قۡ</rule>تُلُوهُ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نف</rule>َعَن<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ نَتَّخِذَهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 20, 5, 386, 334, 154, 'false'
  );
  
  -- Ayah 10 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3262,
    'وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَـٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِی بِهِۦ لَوۡلَاۤ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ',
    'واصبح فؤاد ام موسى فارغا ان كادت لتبدي به لولا ان ربطنا على قلبها لتكون من المؤمنين',
    'وَأَصۡبَحَ فُؤَادُ أُ<rule class=ghunnah>مّ</rule>ِ مُوسَىٰ فَ<rule class=madda_normal>ـٰ</rule>رِغًا‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َادَتۡ لَتُ<rule class=qalaqah>بۡ</rule>دِى بِه<rule class=madda_normal>ِۦ</rule> لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبَ<rule class=qalaqah>طۡ</rule>نَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 20, 5, 386, 334, 154, 'false'
  );
  
  -- Ayah 11 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3263,
    'وَقَالَتۡ لِأُخۡتِهِۦ قُصِّیهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبࣲ وَهُمۡ لَا یَشۡعُرُونَ',
    'وقالت لاخته قصيه فبصرت به عن جنب وهم لا يشعرون',
    'وَقَالَتۡ لِأُخۡتِه<rule class=madda_normal>ِۦ</rule> قُصِّيهِ‌ۖ فَبَصُرَتۡ بِه<rule class=madda_normal>ِۦ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>ُنُ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 20, 5, 386, 334, 154, 'false'
  );
  
  -- Ayah 12 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3264,
    '۞ وَحَرَّمۡنَا عَلَیۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰۤ أَهۡلِ بَیۡتࣲ یَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَـٰصِحُونَ',
    'وحرمنا عليه المراضع من قبل فقالت هل ادلكم على اهل بيت يكفلونه لكم وهم له ناصحون',
    '۞وَحَرَّمۡنَا عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡمَرَاضِعَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِ بَيۡ<rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُلُونَهُ<rule class=madda_normal>ۥ</rule> لَكُمۡ وَهُمۡ لَهُ<rule class=madda_normal>ۥ</rule> نَ<rule class=madda_normal>ـٰ</rule>صِح<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 20, 5, 386, 334, 155, 'false'
  );
  
  -- Ayah 13 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3265,
    'فَرَدَدۡنَـٰهُ إِلَىٰۤ أُمِّهِۦ كَیۡ تَقَرَّ عَیۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'فرددناه الى امه كي تقر عينها ولا تحزن ولتعلم ان وعد الله حق ولكن اكثرهم لا يعلمون',
    'فَرَدَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=ghunnah>مّ</rule>ِه<rule class=madda_normal>ِۦ</rule> كَىۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=idgham_ghunnah>قٌّ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 20, 5, 386, 334, 155, 'false'
  );
  
  -- Ayah 14 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3266,
    'وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰۤ ءَاتَیۡنَـٰهُ حُكۡمࣰا وَعِلۡمࣰاۚ وَكَذَ ٰ⁠لِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ',
    'ولما بلغ اشده واستوى اتيناه حكما وعلما وكذلك نجزي المحسنين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا بَلَغَ أَشُدَّهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>سۡتَوَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ حُكۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َعِلۡ<rule class=idgham_ghunnah>مًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٤',
    14, 20, 5, 387, 335, 155, 'false'
  );
  
  -- Ayah 15 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3267,
    'وَدَخَلَ ٱلۡمَدِینَةَ عَلَىٰ حِینِ غَفۡلَةࣲ مِّنۡ أَهۡلِهَا فَوَجَدَ فِیهَا رَجُلَیۡنِ یَقۡتَتِلَانِ هَـٰذَا مِن شِیعَتِهِۦ وَهَـٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَـٰثَهُ ٱلَّذِی مِن شِیعَتِهِۦ عَلَى ٱلَّذِی مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَیۡهِۖ قَالَ هَـٰذَا مِنۡ عَمَلِ ٱلشَّیۡطَـٰنِۖ إِنَّهُۥ عَدُوࣱّ مُّضِلࣱّ مُّبِینࣱ',
    'ودخل المدينة على حين غفلة من اهلها فوجد فيها رجلين يقتتلان هذا من شيعته وهذا من عدوه فاستغاثه الذي من شيعته على الذي من عدوه فوكزه موسى فقضى عليه قال هذا من عمل الشيطان انه عدو مضل مبين',
    'وَدَخَلَ <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَهۡلِهَا فَوَجَدَ فِيهَا رَجُلَيۡنِ يَ<rule class=qalaqah>قۡ</rule>تَتِلَانِ هَ<rule class=madda_normal>ـٰ</rule>ذَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ِيعَتِه<rule class=madda_normal>ِۦ</rule> وَهَ<rule class=madda_normal>ـٰ</rule>ذَا مِنۡ عَدُوِّه<rule class=madda_normal>ِۦ</rule>‌ۖ فَ<rule class=ham_wasl>ٱ</rule>سۡتَغَ<rule class=madda_normal>ـٰ</rule>ثَهُ <rule class=ham_wasl>ٱ</rule>لَّذِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ِيعَتِه<rule class=madda_normal>ِۦ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِى مِنۡ عَدُوِّه<rule class=madda_normal>ِۦ</rule> فَوَكَزَهُ<rule class=madda_normal>ۥ</rule> مُوسَىٰ فَقَضَىٰ عَلَيۡهِ‌ۖ قَالَ هَ<rule class=madda_normal>ـٰ</rule>ذَا مِنۡ عَمَلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَدُ<rule class=idgham_ghunnah>وٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّضِ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٥',
    15, 20, 5, 387, 335, 155, 'false'
  );
  
  -- Ayah 16 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3268,
    'قَالَ رَبِّ إِنِّی ظَلَمۡتُ نَفۡسِی فَٱغۡفِرۡ لِی فَغَفَرَ لَهُۥۤۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ',
    'قال رب اني ظلمت نفسي فاغفر لي فغفر له انه هو الغفور الرحيم',
    'قَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى ظَلَمۡتُ نَفۡسِى فَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لِى فَغَفَرَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَفُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ١٦',
    16, 20, 5, 387, 335, 155, 'false'
  );
  
  -- Ayah 17 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3269,
    'قَالَ رَبِّ بِمَاۤ أَنۡعَمۡتَ عَلَیَّ فَلَنۡ أَكُونَ ظَهِیرࣰا لِّلۡمُجۡرِمِینَ',
    'قال رب بما انعمت علي فلن اكون ظهيرا للمجرمين',
    'قَالَ رَبِّ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡعَمۡتَ عَلَىَّ فَلَنۡ أَكُونَ ظَهِي<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 20, 5, 387, 335, 155, 'false'
  );
  
  -- Ayah 18 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3270,
    'فَأَصۡبَحَ فِی ٱلۡمَدِینَةِ خَاۤىِٕفࣰا یَتَرَقَّبُ فَإِذَا ٱلَّذِی ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ یَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰۤ إِنَّكَ لَغَوِیࣱّ مُّبِینࣱ',
    'فاصبح في المدينة خائفا يترقب فاذا الذي استنصره بالامس يستصرخه قال له موسى انك لغوي مبين',
    'فَأَصۡبَحَ فِى <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ خ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>ي</rule>َتَرَقَّبُ فَإِذَا <rule class=ham_wasl>ٱ</rule>لَّذِى <rule class=ham_wasl>ٱ</rule>سۡتَ<rule class=ikhafa>نص</rule>َرَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡأَمۡسِ يَسۡتَصۡرِخُهُ<rule class=madda_normal>ۥ</rule>‌ۚ قَالَ لَهُ<rule class=madda_normal>ۥ</rule> مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ لَغَوِ<rule class=idgham_ghunnah>ىٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٨',
    18, 20, 5, 387, 335, 155, 'false'
  );
  
  -- Ayah 19 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3271,
    'فَلَمَّاۤ أَنۡ أَرَادَ أَن یَبۡطِشَ بِٱلَّذِی هُوَ عَدُوࣱّ لَّهُمَا قَالَ یَـٰمُوسَىٰۤ أَتُرِیدُ أَن تَقۡتُلَنِی كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِیدُ إِلَّاۤ أَن تَكُونَ جَبَّارࣰا فِی ٱلۡأَرۡضِ وَمَا تُرِیدُ أَن تَكُونَ مِنَ ٱلۡمُصۡلِحِینَ',
    'فلما ان اراد ان يبطش بالذي هو عدو لهما قال يا موسى اتريد ان تقتلني كما قتلت نفسا بالامس ان تريد الا ان تكون جبارا في الارض وما تريد ان تكون من المصلحين',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَنۡ أَرَادَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>طِشَ بِ<rule class=ham_wasl>ٱ</rule>لَّذِى هُوَ عَدُ<rule class=idgham_wo_ghunnah>وٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمَا قَالَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَتُرِيدُ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>قۡ</rule>تُلَنِى كَمَا قَتَلۡتَ نَفۡس<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأَمۡسِ‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرِيدُ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونَ جَبَّا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا تُرِيدُ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُصۡلِح<rule class=madda_permissible>ِي</rule>نَ ١٩',
    19, 20, 5, 387, 335, 155, 'false'
  );
  
  -- Ayah 20 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3272,
    'وَجَاۤءَ رَجُلࣱ مِّنۡ أَقۡصَا ٱلۡمَدِینَةِ یَسۡعَىٰ قَالَ یَـٰمُوسَىٰۤ إِنَّ ٱلۡمَلَأَ یَأۡتَمِرُونَ بِكَ لِیَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّی لَكَ مِنَ ٱلنَّـٰصِحِینَ',
    'وجاء رجل من اقصى المدينة يسعى قال يا موسى ان الملا ياتمرون بك ليقتلوك فاخرج اني لك من الناصحين',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَجُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَ<rule class=qalaqah>قۡ</rule>صَا <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ يَسۡعَىٰ قَالَ يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمَلَأَ يَأۡتَمِرُونَ بِكَ لِيَ<rule class=qalaqah>قۡ</rule>تُلُوكَ فَ<rule class=ham_wasl>ٱ</rule>خۡرُ<rule class=qalaqah>جۡ</rule> إِ<rule class=ghunnah>نّ</rule>ِى لَكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>صِح<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 20, 5, 387, 335, 155, 'false'
  );
  
  -- Ayah 21 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3273,
    'فَخَرَجَ مِنۡهَا خَاۤىِٕفࣰا یَتَرَقَّبُۖ قَالَ رَبِّ نَجِّنِی مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'فخرج منها خائفا يترقب قال رب نجني من القوم الظالمين',
    'فَخَرَجَ مِنۡهَا خ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>ي</rule>َتَرَقَّبُ‌ۖ قَالَ رَبِّ نَجِّنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢١',
    21, 20, 5, 387, 335, 155, 'false'
  );
  
  -- Ayah 22 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3274,
    'وَلَمَّا تَوَجَّهَ تِلۡقَاۤءَ مَدۡیَنَ قَالَ عَسَىٰ رَبِّیۤ أَن یَهۡدِیَنِی سَوَاۤءَ ٱلسَّبِیلِ',
    'ولما توجه تلقاء مدين قال عسى ربي ان يهديني سواء السبيل',
    'وَلَ<rule class=ghunnah>مّ</rule>َا تَوَجَّهَ تِلۡق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَ<rule class=qalaqah>دۡ</rule>يَنَ قَالَ عَسَىٰ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِيَنِى سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لِ ٢٢',
    22, 20, 5, 388, 336, 155, 'false'
  );
  
  -- Ayah 23 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3275,
    'وَلَمَّا وَرَدَ مَاۤءَ مَدۡیَنَ وَجَدَ عَلَیۡهِ أُمَّةࣰ مِّنَ ٱلنَّاسِ یَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَیۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِی حَتَّىٰ یُصۡدِرَ ٱلرِّعَاۤءُۖ وَأَبُونَا شَیۡخࣱ كَبِیرࣱ',
    'ولما ورد ماء مدين وجد عليه امة من الناس يسقون ووجد من دونهم امراتين تذودان قال ما خطبكما قالتا لا نسقي حتى يصدر الرعاء وابونا شيخ كبير',
    'وَلَ<rule class=ghunnah>مّ</rule>َا وَرَدَ م<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَ<rule class=qalaqah>دۡ</rule>يَنَ وَجَدَ عَلَيۡهِ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ يَسۡقُونَ وَوَجَدَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِهِمُ <rule class=ham_wasl>ٱ</rule>مۡرَأَتَيۡنِ تَذُودَانِ‌ۖ قَالَ مَا خَ<rule class=qalaqah>طۡ</rule>بُكُمَا‌ۖ قَالَتَا لَا نَسۡقِى حَتَّىٰ يُصۡدِرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّع<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ وَأَبُونَا شَيۡ<rule class=ikhafa>خٌ</rule> <rule class=ikhafa>ك</rule>َب<rule class=madda_permissible>ِي</rule>رٌ ٢٣',
    23, 20, 5, 388, 336, 155, 'false'
  );
  
  -- Ayah 24 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3276,
    'فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰۤ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّی لِمَاۤ أَنزَلۡتَ إِلَیَّ مِنۡ خَیۡرࣲ فَقِیرࣱ',
    'فسقى لهما ثم تولى الى الظل فقال رب اني لما انزلت الي من خير فقير',
    'فَسَقَىٰ لَهُمَا ثُ<rule class=ghunnah>مّ</rule>َ تَوَلَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظِّلِّ فَقَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى لِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡتَ إِلَىَّ مِنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َق<rule class=madda_permissible>ِي</rule>رٌ ٢٤',
    24, 20, 5, 388, 336, 155, 'false'
  );
  
  -- Ayah 25 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3277,
    'فَجَاۤءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِی عَلَى ٱسۡتِحۡیَاۤءࣲ قَالَتۡ إِنَّ أَبِی یَدۡعُوكَ لِیَجۡزِیَكَ أَجۡرَ مَا سَقَیۡتَ لَنَاۚ فَلَمَّا جَاۤءَهُۥ وَقَصَّ عَلَیۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'فجاءته احداهما تمشي على استحياء قالت ان ابي يدعوك ليجزيك اجر ما سقيت لنا فلما جاءه وقص عليه القصص قال لا تخف نجوت من القوم الظالمين',
    'فَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُ إِحۡدَ<rule class=madda_normal>ٮٰ</rule>هُمَا تَمۡشِى عَلَى <rule class=ham_wasl>ٱ</rule>سۡتِحۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>ق</rule>َالَتۡ إِ<rule class=ghunnah>نّ</rule>َ أَبِى يَ<rule class=qalaqah>دۡ</rule>عُوكَ لِيَ<rule class=qalaqah>جۡ</rule>زِيَكَ أَ<rule class=qalaqah>جۡ</rule>رَ مَا سَقَيۡتَ لَنَا‌ۚ فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_normal>ۥ</rule> وَقَصَّ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡقَصَصَ قَالَ لَا تَخَفۡ‌ۖ نَجَوۡتَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 20, 5, 388, 336, 155, 'false'
  );
  
  -- Ayah 26 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3278,
    'قَالَتۡ إِحۡدَىٰهُمَا یَـٰۤأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَیۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِیُّ ٱلۡأَمِینُ',
    'قالت احداهما يا ابت استاجره ان خير من استاجرت القوي الامين',
    'قَالَتۡ إِحۡدَ<rule class=madda_normal>ٮٰ</rule>هُمَا يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَبَتِ <rule class=ham_wasl>ٱ</rule>سۡتَــٔۡجِرۡهُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ خَيۡرَ مَنِ <rule class=ham_wasl>ٱ</rule>سۡتَــٔۡجَرۡتَ <rule class=ham_wasl>ٱ</rule>لۡقَوِىُّ <rule class=ham_wasl>ٱ</rule>لۡأَم<rule class=madda_permissible>ِي</rule>نُ ٢٦',
    26, 20, 5, 388, 336, 155, 'false'
  );
  
  -- Ayah 27 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3279,
    'قَالَ إِنِّیۤ أُرِیدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَیَّ هَـٰتَیۡنِ عَلَىٰۤ أَن تَأۡجُرَنِی ثَمَـٰنِیَ حِجَجࣲۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرࣰا فَمِنۡ عِندِكَۖ وَمَاۤ أُرِیدُ أَنۡ أَشُقَّ عَلَیۡكَۚ سَتَجِدُنِیۤ إِن شَاۤءَ ٱللَّهُ مِنَ ٱلصَّـٰلِحِینَ',
    'قال اني اريد ان انكحك احدى ابنتي هاتين على ان تاجرني ثماني حجج فان اتممت عشرا فمن عندك وما اريد ان اشق عليك ستجدني ان شاء الله من الصالحين',
    'قَالَ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُرِيدُ أَنۡ أُ<rule class=ikhafa>نك</rule>ِحَكَ إِحۡدَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَتَىَّ هَ<rule class=madda_normal>ـٰ</rule>تَيۡنِ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡجُرَنِى ثَمَ<rule class=madda_normal>ـٰ</rule>نِىَ حِجَ<rule class=ikhafa>جٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِنۡ أَتۡمَمۡتَ عَشۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َمِنۡ عِ<rule class=ikhafa>ند</rule>ِكَ‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَ‌ۚ سَتَجِدُن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 20, 5, 388, 336, 155, 'false'
  );
  
  -- Ayah 28 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3280,
    'قَالَ ذَ ٰ⁠لِكَ بَیۡنِی وَبَیۡنَكَۖ أَیَّمَا ٱلۡأَجَلَیۡنِ قَضَیۡتُ فَلَا عُدۡوَ ٰ⁠نَ عَلَیَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِیلࣱ',
    'قال ذلك بيني وبينك ايما الاجلين قضيت فلا عدوان علي والله على ما نقول وكيل',
    'قَالَ ذ<rule class=madda_normal>ٰ</rule>لِكَ بَيۡنِى وَبَيۡنَكَ‌ۖ أَيَّمَا <rule class=ham_wasl>ٱ</rule>لۡأَجَلَيۡنِ قَضَيۡتُ فَلَا عُ<rule class=qalaqah>دۡ</rule>و<rule class=madda_normal>ٰ</rule>نَ عَلَىَّ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ مَا نَقُولُ وَك<rule class=madda_permissible>ِي</rule>لٌ ٢٨',
    28, 20, 5, 388, 336, 155, 'false'
  );
  
  -- Ayah 29 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3281,
    '۞ فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦۤ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارࣰاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوۤا۟ إِنِّیۤ ءَانَسۡتُ نَارࣰا لَّعَلِّیۤ ءَاتِیكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةࣲ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ',
    'فلما قضى موسى الاجل وسار باهله انس من جانب الطور نارا قال لاهله امكثوا اني انست نارا لعلي اتيكم منها بخبر او جذوة من النار لعلكم تصطلون',
    '۞فَلَ<rule class=ghunnah>مّ</rule>َا قَضَىٰ مُوسَى <rule class=ham_wasl>ٱ</rule>لۡأَجَلَ وَسَارَ بِأَهۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> ءَانَسَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َانِبِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّورِ نَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ق</rule>َالَ لِأَهۡلِهِ <rule class=ham_wasl>ٱ</rule>مۡكُث<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَانَسۡتُ نَا<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاتِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ لَعَلَّكُمۡ تَصۡطَل<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 20, 5, 389, 337, 156, 'false'
  );
  
  -- Ayah 30 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3282,
    'فَلَمَّاۤ أَتَىٰهَا نُودِیَ مِن شَـٰطِىِٕ ٱلۡوَادِ ٱلۡأَیۡمَنِ فِی ٱلۡبُقۡعَةِ ٱلۡمُبَـٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن یَـٰمُوسَىٰۤ إِنِّیۤ أَنَا ٱللَّهُ رَبُّ ٱلۡعَـٰلَمِینَ',
    'فلما اتاها نودي من شاطئ الواد الايمن في البقعة المباركة من الشجرة ان يا موسى اني انا الله رب العالمين',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَتَ<rule class=madda_normal>ـٰ</rule>هَا نُودِىَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َ<rule class=madda_normal>ـٰ</rule>طِىِٕ <rule class=ham_wasl>ٱ</rule>لۡوَادِ <rule class=ham_wasl>ٱ</rule>لۡأَيۡمَنِ فِى <rule class=ham_wasl>ٱ</rule>لۡبُ<rule class=qalaqah>قۡ</rule>عَةِ <rule class=ham_wasl>ٱ</rule>لۡمُبَ<rule class=madda_normal>ـٰ</rule>رَكَةِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرَةِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنَا <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٣٠',
    30, 20, 5, 389, 337, 156, 'false'
  );
  
  -- Ayah 31 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3283,
    'وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَاۤنࣱّ وَلَّىٰ مُدۡبِرࣰا وَلَمۡ یُعَقِّبۡۚ یَـٰمُوسَىٰۤ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡـَٔامِنِینَ',
    'وان الق عصاك فلما راها تهتز كانها جان ولى مدبرا ولم يعقب يا موسى اقبل ولا تخف انك من الامنين',
    'وَأَنۡ أَلۡقِ عَصَاكَ‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا رَءَاهَا تَهۡتَزُّ كَأَ<rule class=ghunnah>نّ</rule>َهَا ج<rule class=madda_necessary>َا</rule>ٓ<rule class=idgham_ghunnah>نٌّ</rule> <rule class=idgham_ghunnah>و</rule>َلَّىٰ مُ<rule class=qalaqah>دۡ</rule>بِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َلَمۡ يُعَقِّ<rule class=qalaqah>بۡ</rule>‌ۚ يَ<rule class=madda_normal>ـٰ</rule>مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=qalaqah>قۡ</rule>بِلۡ وَلَا تَخَفۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَمِن<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 20, 5, 389, 337, 156, 'false'
  );
  
  -- Ayah 32 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3284,
    'ٱسۡلُكۡ یَدَكَ فِی جَیۡبِكَ تَخۡرُجۡ بَیۡضَاۤءَ مِنۡ غَیۡرِ سُوۤءࣲ وَٱضۡمُمۡ إِلَیۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَ ٰ⁠نِكَ بُرۡهَـٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ',
    'اسلك يدك في جيبك تخرج بيضاء من غير سوء واضمم اليك جناحك من الرهب فذانك برهانان من ربك الى فرعون وملئه انهم كانوا قوما فاسقين',
    'ٱسۡلُكۡ يَدَكَ فِى جَيۡبِكَ تَخۡرُ<rule class=qalaqah>جۡ</rule> بَيۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِنۡ غَيۡرِ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓ<rule class=idgham_ghunnah>ءٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>ضۡمُمۡ إِلَيۡكَ جَنَاحَكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّهۡبِ‌ۖ فَذ<rule class=madda_normal>ٰ</rule>نِكَ بُرۡهَ<rule class=madda_normal>ـٰ</rule>نَانِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِ<rule class=slnt>يۡ</rule>ه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 20, 5, 389, 337, 156, 'false'
  );
  
  -- Ayah 33 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3285,
    'قَالَ رَبِّ إِنِّی قَتَلۡتُ مِنۡهُمۡ نَفۡسࣰا فَأَخَافُ أَن یَقۡتُلُونِ',
    'قال رب اني قتلت منهم نفسا فاخاف ان يقتلون',
    'قَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى قَتَلۡتُ مِنۡهُمۡ نَفۡ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ف</rule>َأَخَافُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>تُل<rule class=madda_permissible>ُو</rule>نِ ٣٣',
    33, 20, 5, 389, 337, 156, 'false'
  );
  
  -- Ayah 34 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3286,
    'وَأَخِی هَـٰرُونُ هُوَ أَفۡصَحُ مِنِّی لِسَانࣰا فَأَرۡسِلۡهُ مَعِیَ رِدۡءࣰا یُصَدِّقُنِیۤۖ إِنِّیۤ أَخَافُ أَن یُكَذِّبُونِ',
    'واخي هارون هو افصح مني لسانا فارسله معي ردءا يصدقني اني اخاف ان يكذبون',
    'وَأَخِى هَ<rule class=madda_normal>ـٰ</rule>رُونُ هُوَ أَفۡصَحُ مِ<rule class=ghunnah>نّ</rule>ِى لِسَا<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َأَرۡسِلۡهُ مَعِىَ رِ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>ءًا</rule> <rule class=idgham_ghunnah>ي</rule>ُصَدِّقُن<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَذِّب<rule class=madda_permissible>ُو</rule>نِ ٣٤',
    34, 20, 5, 389, 337, 156, 'false'
  );
  
  -- Ayah 35 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3287,
    'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِیكَ وَنَجۡعَلُ لَكُمَا سُلۡطَـٰنࣰا فَلَا یَصِلُونَ إِلَیۡكُمَا بِـَٔایَـٰتِنَاۤۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَـٰلِبُونَ',
    'قال سنشد عضدك باخيك ونجعل لكما سلطانا فلا يصلون اليكما باياتنا انتما ومن اتبعكما الغالبون',
    'قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَ<rule class=qalaqah>جۡ</rule>عَلُ لَكُمَا سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َلَا يَصِلُونَ إِلَيۡكُمَا‌ۚ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمَا وَمَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَكُمَا <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>لِب<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 20, 5, 389, 337, 156, 'false'
  );
  
  -- Ayah 36 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3288,
    'فَلَمَّا جَاۤءَهُم مُّوسَىٰ بِـَٔایَـٰتِنَا بَیِّنَـٰتࣲ قَالُوا۟ مَا هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّفۡتَرࣰى وَمَا سَمِعۡنَا بِهَـٰذَا فِیۤ ءَابَاۤىِٕنَا ٱلۡأَوَّلِینَ',
    'فلما جاءهم موسى باياتنا بينات قالوا ما هذا الا سحر مفترى وما سمعنا بهذا في ابائنا الاولين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوسَىٰ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا بَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> مَا هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّفۡتَ<rule class=idgham_ghunnah>رًى</rule> <rule class=idgham_ghunnah>و</rule>َمَا سَمِعۡنَا بِهَ<rule class=madda_normal>ـٰ</rule>ذَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنَا <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 20, 5, 390, 337, 156, 'false'
  );
  
  -- Ayah 37 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3289,
    'وَقَالَ مُوسَىٰ رَبِّیۤ أَعۡلَمُ بِمَن جَاۤءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ',
    'وقال موسى ربي اعلم بمن جاء بالهدى من عنده ومن تكون له عاقبة الدار انه لا يفلح الظالمون',
    'وَقَالَ مُوسَىٰ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡلَمُ بِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ مِنۡ عِ<rule class=ikhafa>ند</rule>ِه<rule class=madda_normal>ِۦ</rule> وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُونُ لَهُ<rule class=madda_normal>ۥ</rule> عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 20, 5, 390, 337, 156, 'false'
  );
  
  -- Ayah 38 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3290,
    'وَقَالَ فِرۡعَوۡنُ یَـٰۤأَیُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَـٰهٍ غَیۡرِی فَأَوۡقِدۡ لِی یَـٰهَـٰمَـٰنُ عَلَى ٱلطِّینِ فَٱجۡعَل لِّی صَرۡحࣰا لَّعَلِّیۤ أَطَّلِعُ إِلَىٰۤ إِلَـٰهِ مُوسَىٰ وَإِنِّی لَأَظُنُّهُۥ مِنَ ٱلۡكَـٰذِبِینَ',
    'وقال فرعون يا ايها الملا ما علمت لكم من اله غيري فاوقد لي يا هامان على الطين فاجعل لي صرحا لعلي اطلع الى اله موسى واني لاظنه من الكاذبين',
    'وَقَالَ فِرۡعَوۡنُ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ مَا عَلِمۡتُ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ غَيۡرِى فَأَوۡقِ<rule class=qalaqah>دۡ</rule> لِى يَ<rule class=madda_normal>ـٰ</rule>هَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_normal>ـٰ</rule>نُ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طِّينِ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>عَل لِّى صَرۡ<rule class=idgham_wo_ghunnah>حًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَطَّلِعُ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هِ مُوسَىٰ وَإِ<rule class=ghunnah>نّ</rule>ِى لَأَظُ<rule class=ghunnah>نّ</rule>ُهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٣٨',
    38, 20, 5, 390, 337, 156, 'false'
  );
  
  -- Ayah 39 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3291,
    'وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَظَنُّوۤا۟ أَنَّهُمۡ إِلَیۡنَا لَا یُرۡجَعُونَ',
    'واستكبر هو وجنوده في الارض بغير الحق وظنوا انهم الينا لا يرجعون',
    'وَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرَ هُوَ وَجُنُودُهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَظَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ إِلَيۡنَا لَا يُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 20, 5, 390, 337, 156, 'false'
  );
  
  -- Ayah 40 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3292,
    'فَأَخَذۡنَـٰهُ وَجُنُودَهُۥ فَنَبَذۡنَـٰهُمۡ فِی ٱلۡیَمِّۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِینَ',
    'فاخذناه وجنوده فنبذناهم في اليم فانظر كيف كان عاقبة الظالمين',
    'فَأَخَذۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَجُنُودَهُ<rule class=madda_normal>ۥ</rule> فَنَبَذۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡيَ<rule class=ghunnah>مّ</rule>ِ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 20, 5, 390, 337, 156, 'false'
  );
  
  -- Ayah 41 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3293,
    'وَجَعَلۡنَـٰهُمۡ أَىِٕمَّةࣰ یَدۡعُونَ إِلَى ٱلنَّارِۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ لَا یُنصَرُونَ',
    'وجعلناهم ائمة يدعون الى النار ويوم القيامة لا ينصرون',
    'وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ أَئِ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>عُونَ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ وَيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ لَا يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 20, 5, 390, 337, 156, 'false'
  );
  
  -- Ayah 42 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3294,
    'وَأَتۡبَعۡنَـٰهُمۡ فِی هَـٰذِهِ ٱلدُّنۡیَا لَعۡنَةࣰۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِینَ',
    'واتبعناهم في هذه الدنيا لعنة ويوم القيامة هم من المقبوحين',
    'وَأَتۡبَعۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا لَعۡنَ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=qalaqah>قۡ</rule>بُوح<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 20, 5, 390, 337, 156, 'false'
  );
  
  -- Ayah 43 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3295,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ مِنۢ بَعۡدِ مَاۤ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَاۤىِٕرَ لِلنَّاسِ وَهُدࣰى وَرَحۡمَةࣰ لَّعَلَّهُمۡ یَتَذَكَّرُونَ',
    'ولقد اتينا موسى الكتاب من بعد ما اهلكنا القرون الاولى بصائر للناس وهدى ورحمة لعلهم يتذكرون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ م<rule class=madda_obligatory_monfasel>َآ</rule> أَهۡلَكۡنَا <rule class=ham_wasl>ٱ</rule>لۡقُرُونَ <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ بَص<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرَ لِل<rule class=ghunnah>نّ</rule>َاسِ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّهُمۡ يَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 20, 5, 390, 338, 156, 'false'
  );
  
  -- Ayah 44 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3296,
    'وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِیِّ إِذۡ قَضَیۡنَاۤ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّـٰهِدِینَ',
    'وما كنت بجانب الغربي اذ قضينا الى موسى الامر وما كنت من الشاهدين',
    'وَمَا كُ<rule class=ikhafa>نت</rule>َ بِجَانِبِ <rule class=ham_wasl>ٱ</rule>لۡغَرۡبِىِّ إِذۡ قَضَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ مُوسَى <rule class=ham_wasl>ٱ</rule>لۡأَمۡرَ وَمَا كُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>هِد<rule class=madda_permissible>ِي</rule>نَ ٤٤',
    44, 20, 5, 391, 338, 156, 'false'
  );
  
  -- Ayah 45 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3297,
    'وَلَـٰكِنَّاۤ أَنشَأۡنَا قُرُونࣰا فَتَطَاوَلَ عَلَیۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِیࣰا فِیۤ أَهۡلِ مَدۡیَنَ تَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِنَا وَلَـٰكِنَّا كُنَّا مُرۡسِلِینَ',
    'ولكنا انشانا قرونا فتطاول عليهم العمر وما كنت ثاويا في اهل مدين تتلو عليهم اياتنا ولكنا كنا مرسلين',
    'وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نش</rule>َأۡنَا قُرُو<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َتَطَاوَلَ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡعُمُرُ‌ۚ وَمَا كُ<rule class=ikhafa>نت</rule>َ ثَاوِ<rule class=ikhafa>يًا</rule> <rule class=ikhafa>ف</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَهۡلِ مَ<rule class=qalaqah>دۡ</rule>يَنَ تَتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا مُرۡسِل<rule class=madda_permissible>ِي</rule>نَ ٤٥',
    45, 20, 5, 391, 338, 156, 'false'
  );
  
  -- Ayah 46 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3298,
    'وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذۡ نَادَیۡنَا وَلَـٰكِن رَّحۡمَةࣰ مِّن رَّبِّكَ لِتُنذِرَ قَوۡمࣰا مَّاۤ أَتَىٰهُم مِّن نَّذِیرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ یَتَذَكَّرُونَ',
    'وما كنت بجانب الطور اذ نادينا ولكن رحمة من ربك لتنذر قوما ما اتاهم من نذير من قبلك لعلهم يتذكرون',
    'وَمَا كُ<rule class=ikhafa>نت</rule>َ بِجَانِبِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّورِ إِذۡ نَادَيۡنَا وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ لِتُ<rule class=ikhafa>نذ</rule>ِرَ قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَتَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّذِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ لَعَلَّهُمۡ يَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 20, 5, 391, 338, 156, 'false'
  );
  
  -- Ayah 47 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3299,
    'وَلَوۡلَاۤ أَن تُصِیبَهُم مُّصِیبَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ فَیَقُولُوا۟ رَبَّنَا لَوۡلَاۤ أَرۡسَلۡتَ إِلَیۡنَا رَسُولࣰا فَنَتَّبِعَ ءَایَـٰتِكَ وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ',
    'ولولا ان تصيبهم مصيبة بما قدمت ايديهم فيقولوا ربنا لولا ارسلت الينا رسولا فنتبع اياتك ونكون من المؤمنين',
    'وَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِيبَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّصِيبَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَيَقُولُو<rule class=slnt>اۡ</rule> رَبَّنَا لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡتَ إِلَيۡنَا رَسُول<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>َنَتَّبِعَ ءَايَ<rule class=madda_normal>ـٰ</rule>تِكَ وَنَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 20, 5, 391, 338, 156, 'false'
  );
  
  -- Ayah 48 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3300,
    'فَلَمَّا جَاۤءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوا۟ لَوۡلَاۤ أُوتِیَ مِثۡلَ مَاۤ أُوتِیَ مُوسَىٰۤۚ أَوَلَمۡ یَكۡفُرُوا۟ بِمَاۤ أُوتِیَ مُوسَىٰ مِن قَبۡلُۖ قَالُوا۟ سِحۡرَانِ تَظَـٰهَرَا وَقَالُوۤا۟ إِنَّا بِكُلࣲّ كَـٰفِرُونَ',
    'فلما جاءهم الحق من عندنا قالوا لولا اوتي مثل ما اوتي موسى اولم يكفروا بما اوتي موسى من قبل قالوا سحران تظاهرا وقالوا انا بكل كافرون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ مِنۡ عِ<rule class=ikhafa>ند</rule>ِنَا قَالُو<rule class=slnt>اۡ</rule> لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِىَ مِثۡلَ م<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِىَ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۚ</rule> أَوَلَمۡ يَكۡفُرُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِىَ مُوسَىٰ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ قَالُو<rule class=slnt>اۡ</rule> سِحۡرَانِ تَظَ<rule class=madda_normal>ـٰ</rule>هَرَا وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا بِكُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>ك</rule>َ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 20, 5, 391, 338, 156, 'false'
  );
  
  -- Ayah 49 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3301,
    'قُلۡ فَأۡتُوا۟ بِكِتَـٰبࣲ مِّنۡ عِندِ ٱللَّهِ هُوَ أَهۡدَىٰ مِنۡهُمَاۤ أَتَّبِعۡهُ إِن كُنتُمۡ صَـٰدِقِینَ',
    'قل فاتوا بكتاب من عند الله هو اهدى منهما اتبعه ان كنتم صادقين',
    'قُلۡ فَأۡتُو<rule class=slnt>اۡ</rule> بِكِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ هُوَ أَهۡدَىٰ مِنۡهُم<rule class=madda_obligatory_monfasel>َآ</rule> أَتَّبِعۡهُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٤٩',
    49, 20, 5, 391, 338, 156, 'false'
  );
  
  -- Ayah 50 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3302,
    'فَإِن لَّمۡ یَسۡتَجِیبُوا۟ لَكَ فَٱعۡلَمۡ أَنَّمَا یَتَّبِعُونَ أَهۡوَاۤءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَیۡرِ هُدࣰى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'فان لم يستجيبوا لك فاعلم انما يتبعون اهواءهم ومن اضل ممن اتبع هواه بغير هدى من الله ان الله لا يهدي القوم الظالمين',
    'فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَسۡتَجِيبُو<rule class=slnt>اۡ</rule> لَكَ فَ<rule class=ham_wasl>ٱ</rule>عۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َمَا يَتَّبِعُونَ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ‌ۚ وَمَنۡ أَضَلُّ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَ هَوَ<rule class=madda_normal>ٮٰ</rule>هُ بِغَيۡرِ هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥٠',
    50, 20, 5, 391, 338, 156, 'false'
  );
  
  -- Ayah 51 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3303,
    '۞ وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ یَتَذَكَّرُونَ',
    'ولقد وصلنا لهم القول لعلهم يتذكرون',
    '۞وَلَقَ<rule class=qalaqah>دۡ</rule> وَصَّلۡنَا لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 52 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3304,
    'ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ مِن قَبۡلِهِۦ هُم بِهِۦ یُؤۡمِنُونَ',
    'الذين اتيناهم الكتاب من قبله هم به يؤمنون',
    'ٱلَّذِينَ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 53 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3305,
    'وَإِذَا یُتۡلَىٰ عَلَیۡهِمۡ قَالُوۤا۟ ءَامَنَّا بِهِۦۤ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَاۤ إِنَّا كُنَّا مِن قَبۡلِهِۦ مُسۡلِمِینَ',
    'واذا يتلى عليهم قالوا امنا به انه الحق من ربنا انا كنا من قبله مسلمين',
    'وَإِذَا يُتۡلَىٰ عَلَيۡهِمۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> مُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 54 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3306,
    'أُو۟لَـٰۤىِٕكَ یُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَیۡنِ بِمَا صَبَرُوا۟ وَیَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّیِّئَةَ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ',
    'اولئك يؤتون اجرهم مرتين بما صبروا ويدرءون بالحسنة السيئة ومما رزقناهم ينفقون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يُؤۡتَوۡنَ أَ<rule class=qalaqah>جۡ</rule>رَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرَّتَيۡنِ بِمَا صَبَرُو<rule class=slnt>اۡ</rule> وَيَ<rule class=qalaqah>دۡ</rule>رَءُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَسَنَةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةَ وَمِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ يُ<rule class=ikhafa>نف</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 55 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3307,
    'وَإِذَا سَمِعُوا۟ ٱللَّغۡوَ أَعۡرَضُوا۟ عَنۡهُ وَقَالُوا۟ لَنَاۤ أَعۡمَـٰلُنَا وَلَكُمۡ أَعۡمَـٰلُكُمۡ سَلَـٰمٌ عَلَیۡكُمۡ لَا نَبۡتَغِی ٱلۡجَـٰهِلِینَ',
    'واذا سمعوا اللغو اعرضوا عنه وقالوا لنا اعمالنا ولكم اعمالكم سلام عليكم لا نبتغي الجاهلين',
    'وَإِذَا سَمِعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّغۡوَ أَعۡرَضُو<rule class=slnt>اۡ</rule> عَنۡهُ وَقَالُو<rule class=slnt>اۡ</rule> لَن<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُنَا وَلَكُمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُكُمۡ سَلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَيۡكُمۡ لَا نَ<rule class=qalaqah>بۡ</rule>تَغِى <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِل<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 56 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3308,
    'إِنَّكَ لَا تَهۡدِی مَنۡ أَحۡبَبۡتَ وَلَـٰكِنَّ ٱللَّهَ یَهۡدِی مَن یَشَاۤءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ',
    'انك لا تهدي من احببت ولكن الله يهدي من يشاء وهو اعلم بالمهتدين',
    'إِ<rule class=ghunnah>نّ</rule>َكَ لَا تَهۡدِى مَنۡ أَحۡبَ<rule class=qalaqah>بۡ</rule>تَ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَهُوَ أَعۡلَمُ بِ<rule class=ham_wasl>ٱ</rule>لۡمُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ٥٦',
    56, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 57 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3309,
    'وَقَالُوۤا۟ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَاۤۚ أَوَلَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنࣰا یُجۡبَىٰۤ إِلَیۡهِ ثَمَرَ ٰ⁠تُ كُلِّ شَیۡءࣲ رِّزۡقࣰا مِّن لَّدُنَّا وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'وقالوا ان نتبع الهدى معك نتخطف من ارضنا اولم نمكن لهم حرما امنا يجبى اليه ثمرات كل شيء رزقا من لدنا ولكن اكثرهم لا يعلمون',
    'وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّتَّبِعِ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أَوَلَمۡ نُمَكّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ حَرَمًا ءَامِ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>جۡ</rule>بَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡهِ ثَمَر<rule class=madda_normal>ٰ</rule>تُ كُلِّ ش<rule class=idgham_wo_ghunnah>َىۡءٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّزۡ<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدُ<rule class=ghunnah>نّ</rule>َا وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 58 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3310,
    'وَكَمۡ أَهۡلَكۡنَا مِن قَرۡیَةِۭ بَطِرَتۡ مَعِیشَتَهَاۖ فَتِلۡكَ مَسَـٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِیلࣰاۖ وَكُنَّا نَحۡنُ ٱلۡوَ ٰ⁠رِثِینَ',
    'وكم اهلكنا من قرية بطرت معيشتها فتلك مساكنهم لم تسكن من بعدهم الا قليلا وكنا نحن الوارثين',
    'وَكَمۡ أَهۡلَكۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَ<rule class=iqlab>ةِۭ</rule> <rule class=iqlab>ب</rule>َطِرَتۡ مَعِيشَتَهَا‌ۖ فَتِلۡكَ مَسَ<rule class=madda_normal>ـٰ</rule>كِنُهُمۡ لَمۡ تُسۡك<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ إِلَّا قَلِيل<rule class=idgham_ghunnah>اً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َكُ<rule class=ghunnah>نّ</rule>َا نَحۡنُ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>رِث<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 59 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3311,
    'وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ یَبۡعَثَ فِیۤ أُمِّهَا رَسُولࣰا یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِی ٱلۡقُرَىٰۤ إِلَّا وَأَهۡلُهَا ظَـٰلِمُونَ',
    'وما كان ربك مهلك القرى حتى يبعث في امها رسولا يتلو عليهم اياتنا وما كنا مهلكي القرى الا واهلها ظالمون',
    'وَمَا كَانَ رَبُّكَ مُهۡلِكَ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ حَتَّىٰ يَ<rule class=qalaqah>بۡ</rule>عَثَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ghunnah>مّ</rule>ِهَا رَسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ي</rule>َتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا‌ۚ وَمَا كُ<rule class=ghunnah>نّ</rule>َا مُهۡلِكِى <rule class=ham_wasl>ٱ</rule>لۡقُرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَّا وَأَهۡلُهَا ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 20, 5, 392, 339, 157, 'false'
  );
  
  -- Ayah 60 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3312,
    'وَمَاۤ أُوتِیتُم مِّن شَیۡءࣲ فَمَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَزِینَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَیۡرࣱ وَأَبۡقَىٰۤۚ أَفَلَا تَعۡقِلُونَ',
    'وما اوتيتم من شيء فمتاع الحياة الدنيا وزينتها وما عند الله خير وابقى افلا تعقلون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِيت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َمَتَ<rule class=madda_normal>ـٰ</rule>عُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَزِينَتُهَا‌ۚ وَمَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>بۡ</rule>قَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۚ</rule> أَفَلَا تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 20, 5, 393, 339, 157, 'false'
  );
  
  -- Ayah 61 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3313,
    'أَفَمَن وَعَدۡنَـٰهُ وَعۡدًا حَسَنࣰا فَهُوَ لَـٰقِیهِ كَمَن مَّتَّعۡنَـٰهُ مَتَـٰعَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا ثُمَّ هُوَ یَوۡمَ ٱلۡقِیَـٰمَةِ مِنَ ٱلۡمُحۡضَرِینَ',
    'افمن وعدناه وعدا حسنا فهو لاقيه كمن متعناه متاع الحياة الدنيا ثم هو يوم القيامة من المحضرين',
    'أَفَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>و</rule>َعَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ وَعۡدًا حَسَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َهُوَ لَ<rule class=madda_normal>ـٰ</rule>قِيهِ كَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّتَّعۡنَ<rule class=madda_normal>ـٰ</rule>هُ مَتَ<rule class=madda_normal>ـٰ</rule>عَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا ثُ<rule class=ghunnah>مّ</rule>َ هُوَ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡضَر<rule class=madda_permissible>ِي</rule>نَ ٦١',
    61, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 62 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3314,
    'وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ أَیۡنَ شُرَكَاۤءِیَ ٱلَّذِینَ كُنتُمۡ تَزۡعُمُونَ',
    'ويوم يناديهم فيقول اين شركائي الذين كنتم تزعمون',
    'وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كُ<rule class=ikhafa>نت</rule>ُمۡ تَزۡعُم<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 63 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3315,
    'قَالَ ٱلَّذِینَ حَقَّ عَلَیۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَـٰۤؤُلَاۤءِ ٱلَّذِینَ أَغۡوَیۡنَاۤ أَغۡوَیۡنَـٰهُمۡ كَمَا غَوَیۡنَاۖ تَبَرَّأۡنَاۤ إِلَیۡكَۖ مَا كَانُوۤا۟ إِیَّانَا یَعۡبُدُونَ',
    'قال الذين حق عليهم القول ربنا هؤلاء الذين اغوينا اغويناهم كما غوينا تبرانا اليك ما كانوا ايانا يعبدون',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ حَقَّ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ رَبَّنَا هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَغۡوَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡوَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ كَمَا غَوَيۡنَا‌ۖ تَبَرَّأۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ‌ۖ مَا كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِيَّانَا يَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 64 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3316,
    'وَقِیلَ ٱدۡعُوا۟ شُرَكَاۤءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ یَسۡتَجِیبُوا۟ لَهُمۡ وَرَأَوُا۟ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُوا۟ یَهۡتَدُونَ',
    'وقيل ادعوا شركاءكم فدعوهم فلم يستجيبوا لهم وراوا العذاب لو انهم كانوا يهتدون',
    'وَقِيلَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُو<rule class=slnt>اۡ</rule> لَهُمۡ وَرَأَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ‌ۚ لَوۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 65 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3317,
    'وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ مَاذَاۤ أَجَبۡتُمُ ٱلۡمُرۡسَلِینَ',
    'ويوم يناديهم فيقول ماذا اجبتم المرسلين',
    'وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ مَاذ<rule class=madda_obligatory_monfasel>َآ</rule> أَجَ<rule class=qalaqah>بۡ</rule>تُمُ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٦٥',
    65, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 66 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3318,
    'فَعَمِیَتۡ عَلَیۡهِمُ ٱلۡأَنۢبَاۤءُ یَوۡمَىِٕذࣲ فَهُمۡ لَا یَتَسَاۤءَلُونَ',
    'فعميت عليهم الانباء يومئذ فهم لا يتساءلون',
    'فَعَمِيَتۡ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءُ يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ف</rule>َهُمۡ لَا يَتَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَل<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 67 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3319,
    'فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَعَسَىٰۤ أَن یَكُونَ مِنَ ٱلۡمُفۡلِحِینَ',
    'فاما من تاب وامن وعمل صالحا فعسى ان يكون من المفلحين',
    'فَأَ<rule class=ghunnah>مّ</rule>َا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َابَ وَءَامَنَ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َعَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ِي</rule>نَ ٦٧',
    67, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 68 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3320,
    'وَرَبُّكَ یَخۡلُقُ مَا یَشَاۤءُ وَیَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِیَرَةُۚ سُبۡحَـٰنَ ٱللَّهِ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ',
    'وربك يخلق ما يشاء ويختار ما كان لهم الخيرة سبحان الله وتعالى عما يشركون',
    'وَرَبُّكَ يَخۡلُقُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَخۡتَارُ‌ۗ مَا كَانَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡخِيَرَةُ‌ۚ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَتَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 69 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3321,
    'وَرَبُّكَ یَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا یُعۡلِنُونَ',
    'وربك يعلم ما تكن صدورهم وما يعلنون',
    'وَرَبُّكَ يَعۡلَمُ مَا تُكِ<rule class=ghunnah>نّ</rule>ُ صُدُورُهُمۡ وَمَا يُعۡلِن<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 70 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3322,
    'وَهُوَ ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ لَهُ ٱلۡحَمۡدُ فِی ٱلۡأُولَىٰ وَٱلۡـَٔاخِرَةِۖ وَلَهُ ٱلۡحُكۡمُ وَإِلَیۡهِ تُرۡجَعُونَ',
    'وهو الله لا اله الا هو له الحمد في الاولى والاخرة وله الحكم واليه ترجعون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>للَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۖ لَهُ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ فِى <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ وَلَهُ <rule class=ham_wasl>ٱ</rule>لۡحُكۡمُ وَإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 20, 5, 393, 340, 157, 'false'
  );
  
  -- Ayah 71 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3323,
    'قُلۡ أَرَءَیۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَیۡكُمُ ٱلَّیۡلَ سَرۡمَدًا إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ مَنۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِ یَأۡتِیكُم بِضِیَاۤءٍۚ أَفَلَا تَسۡمَعُونَ',
    'قل ارايتم ان جعل الله عليكم الليل سرمدا الى يوم القيامة من اله غير الله ياتيكم بضياء افلا تسمعون',
    'قُلۡ أَرَءَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َعَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ مَنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٌ غَيۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ يَأۡتِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِضِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ‌ۖ أَفَلَا تَسۡمَع<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 20, 5, 394, 340, 157, 'false'
  );
  
  -- Ayah 72 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3324,
    'قُلۡ أَرَءَیۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَیۡكُمُ ٱلنَّهَارَ سَرۡمَدًا إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ مَنۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِ یَأۡتِیكُم بِلَیۡلࣲ تَسۡكُنُونَ فِیهِۚ أَفَلَا تُبۡصِرُونَ',
    'قل ارايتم ان جعل الله عليكم النهار سرمدا الى يوم القيامة من اله غير الله ياتيكم بليل تسكنون فيه افلا تبصرون',
    'قُلۡ أَرَءَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َعَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ سَرۡمَدًا إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ مَنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٌ غَيۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ يَأۡتِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِلَيۡ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ت</rule>َسۡكُنُونَ فِيهِ‌ۖ أَفَلَا تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 20, 5, 394, 340, 157, 'false'
  );
  
  -- Ayah 73 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3325,
    'وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّیۡلَ وَٱلنَّهَارَ لِتَسۡكُنُوا۟ فِیهِ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ',
    'ومن رحمته جعل لكم الليل والنهار لتسكنوا فيه ولتبتغوا من فضله ولعلكم تشكرون',
    'وَم<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَتِه<rule class=madda_normal>ِۦ</rule> جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ لِتَسۡكُنُو<rule class=slnt>اۡ</rule> فِيهِ وَلِتَ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> وَلَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 20, 5, 394, 340, 157, 'false'
  );
  
  -- Ayah 74 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3326,
    'وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ أَیۡنَ شُرَكَاۤءِیَ ٱلَّذِینَ كُنتُمۡ تَزۡعُمُونَ',
    'ويوم يناديهم فيقول اين شركائي الذين كنتم تزعمون',
    'وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كُ<rule class=ikhafa>نت</rule>ُمۡ تَزۡعُم<rule class=madda_permissible>ُو</rule>نَ ٧٤',
    74, 20, 5, 394, 340, 157, 'false'
  );
  
  -- Ayah 75 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3327,
    'وَنَزَعۡنَا مِن كُلِّ أُمَّةࣲ شَهِیدࣰا فَقُلۡنَا هَاتُوا۟ بُرۡهَـٰنَكُمۡ فَعَلِمُوۤا۟ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ',
    'ونزعنا من كل امة شهيدا فقلنا هاتوا برهانكم فعلموا ان الحق لله وضل عنهم ما كانوا يفترون',
    'وَنَزَعۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ش</rule>َهِي<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>َقُلۡنَا هَاتُو<rule class=slnt>اۡ</rule> بُرۡهَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ فَعَلِم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ لِلَّهِ وَضَلَّ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 20, 5, 394, 340, 157, 'false'
  );
  
  -- Ayah 76 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3328,
    '۞ إِنَّ قَـٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَیۡهِمۡۖ وَءَاتَیۡنَـٰهُ مِنَ ٱلۡكُنُوزِ مَاۤ إِنَّ مَفَاتِحَهُۥ لَتَنُوۤأُ بِٱلۡعُصۡبَةِ أُو۟لِی ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡفَرِحِینَ',
    'ان قارون كان من قوم موسى فبغى عليهم واتيناه من الكنوز ما ان مفاتحه لتنوء بالعصبة اولي القوة اذ قال له قومه لا تفرح ان الله لا يحب الفرحين',
    '۞إِ<rule class=ghunnah>نّ</rule>َ قَ<rule class=madda_normal>ـٰ</rule>رُونَ كَانَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡ‌ۖ وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكُنُوزِ م<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ مَفَاتِحَهُ<rule class=madda_normal>ۥ</rule> لَتَن<rule class=madda_obligatory_mottasel>ُو</rule>ٓأُ بِ<rule class=ham_wasl>ٱ</rule>لۡعُصۡبَةِ أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡقُوَّةِ إِذۡ قَالَ لَهُ<rule class=madda_normal>ۥ</rule> قَوۡمُهُ<rule class=madda_normal>ۥ</rule> لَا تَفۡرَحۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡفَرِح<rule class=madda_permissible>ِي</rule>نَ ٧٦',
    76, 20, 5, 394, 341, 158, 'false'
  );
  
  -- Ayah 77 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3329,
    'وَٱبۡتَغِ فِیمَاۤ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡـَٔاخِرَةَۖ وَلَا تَنسَ نَصِیبَكَ مِنَ ٱلدُّنۡیَاۖ وَأَحۡسِن كَمَاۤ أَحۡسَنَ ٱللَّهُ إِلَیۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِی ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡمُفۡسِدِینَ',
    'وابتغ فيما اتاك الله الدار الاخرة ولا تنس نصيبك من الدنيا واحسن كما احسن الله اليك ولا تبغ الفساد في الارض ان الله لا يحب المفسدين',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغِ فِيم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>كَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ‌ۖ وَلَا تَ<rule class=ikhafa>نس</rule>َ نَصِيبَكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَأَحۡسِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَحۡسَنَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَيۡكَ‌ۖ وَلَا تَ<rule class=qalaqah>بۡ</rule>غِ <rule class=ham_wasl>ٱ</rule>لۡفَسَادَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٧٧',
    77, 20, 5, 394, 341, 158, 'false'
  );
  
  -- Ayah 78 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3330,
    'قَالَ إِنَّمَاۤ أُوتِیتُهُۥ عَلَىٰ عِلۡمٍ عِندِیۤۚ أَوَلَمۡ یَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةࣰ وَأَكۡثَرُ جَمۡعࣰاۚ وَلَا یُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ',
    'قال انما اوتيته على علم عندي اولم يعلم ان الله قد اهلك من قبله من القرون من هو اشد منه قوة واكثر جمعا ولا يسال عن ذنوبهم المجرمون',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِيتُهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ عِلۡمٍ عِ<rule class=ikhafa>ند</rule><rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> أَوَلَمۡ يَعۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَ<rule class=qalaqah>دۡ</rule> أَهۡلَكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَكۡثَرُ جَمۡ<rule class=idgham_ghunnah>عًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُسۡــَٔلُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُنُوبِهِمُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 20, 5, 395, 341, 158, 'false'
  );
  
  -- Ayah 79 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3331,
    'فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِی زِینَتِهِۦۖ قَالَ ٱلَّذِینَ یُرِیدُونَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا یَـٰلَیۡتَ لَنَا مِثۡلَ مَاۤ أُوتِیَ قَـٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِیمࣲ',
    'فخرج على قومه في زينته قال الذين يريدون الحياة الدنيا يا ليت لنا مثل ما اوتي قارون انه لذو حظ عظيم',
    'فَخَرَجَ عَلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule> فِى زِينَتِه<rule class=madda_normal>ِۦ</rule>‌ۖ قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُرِيدُونَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَ لَنَا مِثۡلَ م<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِىَ قَ<rule class=madda_normal>ـٰ</rule>رُونُ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَذُو حَظٍّ عَظ<rule class=madda_permissible>ِي</rule>مٍ ٧٩',
    79, 20, 5, 395, 341, 158, 'false'
  );
  
  -- Ayah 80 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3332,
    'وَقَالَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ وَیۡلَكُمۡ ثَوَابُ ٱللَّهِ خَیۡرࣱ لِّمَنۡ ءَامَنَ وَعَمِلَ صَـٰلِحࣰاۚ وَلَا یُلَقَّىٰهَاۤ إِلَّا ٱلصَّـٰبِرُونَ',
    'وقال الذين اوتوا العلم ويلكم ثواب الله خير لمن امن وعمل صالحا ولا يلقاها الا الصابرون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ <rule class=ham_wasl>ٱ</rule>للَّهِ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَنۡ ءَامَنَ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُلَقَّ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 20, 5, 395, 341, 158, 'false'
  );
  
  -- Ayah 81 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3333,
    'فَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةࣲ یَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِینَ',
    'فخسفنا به وبداره الارض فما كان له من فئة ينصرونه من دون الله وما كان من المنتصرين',
    'فَخَسَفۡنَا بِه<rule class=madda_normal>ِۦ</rule> وَبِدَارِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فَمَا كَانَ لَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِئَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرُونَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَا كَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نت</rule>َصِر<rule class=madda_permissible>ِي</rule>نَ ٨١',
    81, 20, 5, 395, 341, 158, 'false'
  );
  
  -- Ayah 82 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3334,
    'وَأَصۡبَحَ ٱلَّذِینَ تَمَنَّوۡا۟ مَكَانَهُۥ بِٱلۡأَمۡسِ یَقُولُونَ وَیۡكَأَنَّ ٱللَّهَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُۖ لَوۡلَاۤ أَن مَّنَّ ٱللَّهُ عَلَیۡنَا لَخَسَفَ بِنَاۖ وَیۡكَأَنَّهُۥ لَا یُفۡلِحُ ٱلۡكَـٰفِرُونَ',
    'واصبح الذين تمنوا مكانه بالامس يقولون ويكان الله يبسط الرزق لمن يشاء من عباده ويقدر لولا ان من الله علينا لخسف بنا ويكانه لا يفلح الكافرون',
    'وَأَصۡبَحَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَمَ<rule class=ghunnah>نّ</rule>َوۡ<rule class=slnt>اۡ</rule> مَكَانَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡأَمۡسِ يَقُولُونَ وَيۡكَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule> وَيَ<rule class=qalaqah>قۡ</rule>دِرُ‌ۖ لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡنَا لَخَسَفَ بِنَا‌ۖ وَيۡكَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُفۡلِحُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 20, 5, 395, 341, 158, 'false'
  );
  
  -- Ayah 83 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3335,
    'تِلۡكَ ٱلدَّارُ ٱلۡـَٔاخِرَةُ نَجۡعَلُهَا لِلَّذِینَ لَا یُرِیدُونَ عُلُوࣰّا فِی ٱلۡأَرۡضِ وَلَا فَسَادࣰاۚ وَٱلۡعَـٰقِبَةُ لِلۡمُتَّقِینَ',
    'تلك الدار الاخرة نجعلها للذين لا يريدون علوا في الارض ولا فسادا والعاقبة للمتقين',
    'تِلۡكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةُ نَ<rule class=qalaqah>جۡ</rule>عَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُو<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا فَسَا<rule class=idgham_ghunnah>دًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>قِبَةُ لِلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 20, 5, 395, 341, 158, 'false'
  );
  
  -- Ayah 84 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3336,
    'مَن جَاۤءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَیۡرࣱ مِّنۡهَاۖ وَمَن جَاۤءَ بِٱلسَّیِّئَةِ فَلَا یُجۡزَى ٱلَّذِینَ عَمِلُوا۟ ٱلسَّیِّـَٔاتِ إِلَّا مَا كَانُوا۟ یَعۡمَلُونَ',
    'من جاء بالحسنة فله خير منها ومن جاء بالسيئة فلا يجزى الذين عملوا السيئات الا ما كانوا يعملون',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَسَنَةِ فَلَهُ<rule class=madda_normal>ۥ</rule> خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةِ فَلَا يُ<rule class=qalaqah>جۡ</rule>زَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ عَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ إِلَّا مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 20, 5, 395, 341, 158, 'false'
  );
  
  -- Ayah 85 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3337,
    'إِنَّ ٱلَّذِی فَرَضَ عَلَیۡكَ ٱلۡقُرۡءَانَ لَرَاۤدُّكَ إِلَىٰ مَعَادࣲۚ قُل رَّبِّیۤ أَعۡلَمُ مَن جَاۤءَ بِٱلۡهُدَىٰ وَمَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'ان الذي فرض عليك القران لرادك الى معاد قل ربي اعلم من جاء بالهدى ومن هو في ضلال مبين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِى فَرَضَ عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ لَر<rule class=madda_necessary>َا</rule>ٓدُّكَ إِلَىٰ مَعَا<rule class=ikhafa>دٍ‌ۚ</rule> <rule class=ikhafa>ق</rule>ُ<rule class=idgham_mutaqaribayn>ل</rule> رَّبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡلَمُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَمَنۡ هُوَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٨٥',
    85, 20, 5, 396, 341, 158, 'false'
  );
  
  -- Ayah 86 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3338,
    'وَمَا كُنتَ تَرۡجُوۤا۟ أَن یُلۡقَىٰۤ إِلَیۡكَ ٱلۡكِتَـٰبُ إِلَّا رَحۡمَةࣰ مِّن رَّبِّكَۖ فَلَا تَكُونَنَّ ظَهِیرࣰا لِّلۡكَـٰفِرِینَ',
    'وما كنت ترجو ان يلقى اليك الكتاب الا رحمة من ربك فلا تكونن ظهيرا للكافرين',
    'وَمَا كُ<rule class=ikhafa>نت</rule>َ تَرۡج<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُلۡقَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بُ إِلَّا رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۖ فَلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ ظَهِي<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 20, 5, 396, 341, 158, 'false'
  );
  
  -- Ayah 87 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3339,
    'وَلَا یَصُدُّنَّكَ عَنۡ ءَایَـٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَیۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِینَ',
    'ولا يصدنك عن ايات الله بعد اذ انزلت اليك وادع الى ربك ولا تكونن من المشركين',
    'وَلَا يَصُدُّ<rule class=ghunnah>نّ</rule>َكَ عَنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ بَعۡدَ إِذۡ أُ<rule class=ikhafa>نز</rule>ِلَتۡ إِلَيۡكَ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ إِلَىٰ رَبِّكَ‌ۖ وَلَا تَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 20, 5, 396, 341, 158, 'false'
  );
  
  -- Ayah 88 Surah Al-Qasas
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    28,
    3340,
    'وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَۘ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ كُلُّ شَیۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَیۡهِ تُرۡجَعُونَ',
    'ولا تدع مع الله الها اخر لا اله الا هو كل شيء هالك الا وجهه له الحكم واليه ترجعون',
    'وَلَا تَ<rule class=qalaqah>دۡ</rule>عُ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ‌ۘ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۚ كُلُّ شَىۡءٍ هَالِكٌ إِلَّا وَ<rule class=qalaqah>جۡ</rule>هَهُ<rule class=madda_normal>ۥ</rule>‌ۚ لَهُ <rule class=ham_wasl>ٱ</rule>لۡحُكۡمُ وَإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 20, 5, 396, 341, 158, 'false'
  );
  

-- Surah Al-Ankaboot
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (29, 'سُورَةُ العَنكَبُوتِ', 'Al-Ankaboot', 'The Spider', 'Meccan', 69);

  -- Ayah 1 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3341,
    'الۤمۤ',
    'الم',
    'ا<rule class=madda_necessary>لٓ</rule><rule class=madda_necessary>مٓ</rule> ١',
    1, 20, 5, 396, 342, 159, 'false'
  );
  
  -- Ayah 2 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3342,
    'أَحَسِبَ ٱلنَّاسُ أَن یُتۡرَكُوۤا۟ أَن یَقُولُوۤا۟ ءَامَنَّا وَهُمۡ لَا یُفۡتَنُونَ',
    'احسب الناس ان يتركوا ان يقولوا امنا وهم لا يفتنون',
    'أَحَسِبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُتۡرَك<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُول<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا وَهُمۡ لَا يُفۡتَن<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 20, 5, 396, 342, 159, 'false'
  );
  
  -- Ayah 3 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3343,
    'وَلَقَدۡ فَتَنَّا ٱلَّذِینَ مِن قَبۡلِهِمۡۖ فَلَیَعۡلَمَنَّ ٱللَّهُ ٱلَّذِینَ صَدَقُوا۟ وَلَیَعۡلَمَنَّ ٱلۡكَـٰذِبِینَ',
    'ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكاذبين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> فَتَ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۖ فَلَيَعۡلَمَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ صَدَقُو<rule class=slnt>اۡ</rule> وَلَيَعۡلَمَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ِي</rule>نَ ٣',
    3, 20, 5, 396, 342, 159, 'false'
  );
  
  -- Ayah 4 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3344,
    'أَمۡ حَسِبَ ٱلَّذِینَ یَعۡمَلُونَ ٱلسَّیِّـَٔاتِ أَن یَسۡبِقُونَاۚ سَاۤءَ مَا یَحۡكُمُونَ',
    'ام حسب الذين يعملون السيئات ان يسبقونا ساء ما يحكمون',
    'أَمۡ حَسِبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَعۡمَلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡبِقُونَا‌ۚ س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا يَحۡكُم<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 20, 5, 396, 342, 159, 'false'
  );
  
  -- Ayah 5 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3345,
    'مَن كَانَ یَرۡجُوا۟ لِقَاۤءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَـَٔاتࣲۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'من كان يرجو لقاء الله فان اجل الله لات وهو السميع العليم',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يَرۡجُو<rule class=slnt>اۡ</rule> لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَإِ<rule class=ghunnah>نّ</rule>َ أَجَلَ <rule class=ham_wasl>ٱ</rule>للَّهِ لَأَ<rule class=idgham_ghunnah>تٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٥',
    5, 20, 5, 396, 342, 159, 'false'
  );
  
  -- Ayah 6 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3346,
    'وَمَن جَـٰهَدَ فَإِنَّمَا یُجَـٰهِدُ لِنَفۡسِهِۦۤۚ إِنَّ ٱللَّهَ لَغَنِیٌّ عَنِ ٱلۡعَـٰلَمِینَ',
    'ومن جاهد فانما يجاهد لنفسه ان الله لغني عن العالمين',
    'وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َ<rule class=madda_normal>ـٰ</rule>هَدَ فَإِ<rule class=ghunnah>نّ</rule>َمَا يُجَ<rule class=madda_normal>ـٰ</rule>هِدُ لِنَفۡسِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَغَنِىٌّ عَنِ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 20, 5, 396, 342, 159, 'false'
  );
  
  -- Ayah 7 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3347,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَلَنَجۡزِیَنَّهُمۡ أَحۡسَنَ ٱلَّذِی كَانُوا۟ یَعۡمَلُونَ',
    'والذين امنوا وعملوا الصالحات لنكفرن عنهم سيئاتهم ولنجزينهم احسن الذي كانوا يعملون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَنُكَفِّرَ<rule class=ghunnah>نّ</rule>َ عَنۡهُمۡ سَيِّـَٔـاتِهِمۡ وَلَنَ<rule class=qalaqah>جۡ</rule>زِيَ<rule class=ghunnah>نّ</rule>َهُمۡ أَحۡسَنَ <rule class=ham_wasl>ٱ</rule>لَّذِى كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 20, 5, 397, 342, 159, 'false'
  );
  
  -- Ayah 8 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3348,
    'وَوَصَّیۡنَا ٱلۡإِنسَـٰنَ بِوَ ٰ⁠لِدَیۡهِ حُسۡنࣰاۖ وَإِن جَـٰهَدَاكَ لِتُشۡرِكَ بِی مَا لَیۡسَ لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۤۚ إِلَیَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'ووصينا الانسان بوالديه حسنا وان جاهداك لتشرك بي ما ليس لك به علم فلا تطعهما الي مرجعكم فانبئكم بما كنتم تعملون',
    'وَوَصَّيۡنَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ بِو<rule class=madda_normal>ٰ</rule>لِدَيۡهِ حُسۡ<rule class=idgham_ghunnah>نًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َ<rule class=madda_normal>ـٰ</rule>هَدَاكَ لِتُشۡرِكَ بِى مَا لَيۡسَ لَكَ بِه<rule class=madda_normal>ِۦ</rule> عِلۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ف</rule>َلَا تُطِعۡهُم<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِلَىَّ مَرۡجِعُكُمۡ فَأُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 20, 5, 397, 342, 159, 'false'
  );
  
  -- Ayah 9 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3349,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُدۡخِلَنَّهُمۡ فِی ٱلصَّـٰلِحِینَ',
    'والذين امنوا وعملوا الصالحات لندخلنهم في الصالحين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَنُ<rule class=qalaqah>دۡ</rule>خِلَ<rule class=ghunnah>نّ</rule>َهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٩',
    9, 20, 5, 397, 342, 159, 'false'
  );
  
  -- Ayah 10 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3350,
    'وَمِنَ ٱلنَّاسِ مَن یَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَاۤ أُوذِیَ فِی ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ وَلَىِٕن جَاۤءَ نَصۡرࣱ مِّن رَّبِّكَ لَیَقُولُنَّ إِنَّا كُنَّا مَعَكُمۡۚ أَوَلَیۡسَ ٱللَّهُ بِأَعۡلَمَ بِمَا فِی صُدُورِ ٱلۡعَـٰلَمِینَ',
    'ومن الناس من يقول امنا بالله فاذا اوذي في الله جعل فتنة الناس كعذاب الله ولئن جاء نصر من ربك ليقولن انا كنا معكم اوليس الله باعلم بما في صدور العالمين',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُ ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ فَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أُوذِىَ فِى <rule class=ham_wasl>ٱ</rule>للَّهِ جَعَلَ فِتۡنَةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ كَعَذَابِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ نَصۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ لَيَقُولُ<rule class=ghunnah>نّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا مَعَكُمۡ‌ۚ أَوَلَيۡسَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِأَعۡلَمَ بِمَا فِى صُدُورِ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 20, 5, 397, 342, 159, 'false'
  );
  
  -- Ayah 11 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3351,
    'وَلَیَعۡلَمَنَّ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَلَیَعۡلَمَنَّ ٱلۡمُنَـٰفِقِینَ',
    'وليعلمن الله الذين امنوا وليعلمن المنافقين',
    'وَلَيَعۡلَمَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَلَيَعۡلَمَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِق<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 20, 5, 397, 342, 159, 'false'
  );
  
  -- Ayah 12 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3352,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِیلَنَا وَلۡنَحۡمِلۡ خَطَـٰیَـٰكُمۡ وَمَا هُم بِحَـٰمِلِینَ مِنۡ خَطَـٰیَـٰهُم مِّن شَیۡءٍۖ إِنَّهُمۡ لَكَـٰذِبُونَ',
    'وقال الذين كفروا للذين امنوا اتبعوا سبيلنا ولنحمل خطاياكم وما هم بحاملين من خطاياهم من شيء انهم لكاذبون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لِلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّبِعُو<rule class=slnt>اۡ</rule> سَبِيلَنَا وَلۡنَحۡمِلۡ خَطَ<rule class=madda_normal>ـٰ</rule>يَ<rule class=madda_normal>ـٰ</rule>كُمۡ وَمَا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِحَ<rule class=madda_normal>ـٰ</rule>مِلِينَ مِنۡ خَطَ<rule class=madda_normal>ـٰ</rule>يَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 20, 5, 397, 342, 159, 'false'
  );
  
  -- Ayah 13 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3353,
    'وَلَیَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالࣰا مَّعَ أَثۡقَالِهِمۡۖ وَلَیُسۡـَٔلُنَّ یَوۡمَ ٱلۡقِیَـٰمَةِ عَمَّا كَانُوا۟ یَفۡتَرُونَ',
    'وليحملن اثقالهم واثقالا مع اثقالهم وليسالن يوم القيامة عما كانوا يفترون',
    'وَلَيَحۡمِلُ<rule class=ghunnah>نّ</rule>َ أَثۡقَالَهُمۡ وَأَثۡقَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّعَ أَثۡقَالِهِمۡ‌ۖ وَلَيُسۡــَٔلُ<rule class=ghunnah>نّ</rule>َ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ عَ<rule class=ghunnah>مّ</rule>َا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 20, 5, 397, 342, 159, 'false'
  );
  
  -- Ayah 14 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3354,
    'وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِیهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِینَ عَامࣰا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَـٰلِمُونَ',
    'ولقد ارسلنا نوحا الى قومه فلبث فيهم الف سنة الا خمسين عاما فاخذهم الطوفان وهم ظالمون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule> فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَا<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َأَخَذَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طُّوفَانُ وَهُمۡ ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 20, 5, 397, 343, 159, 'false'
  );
  
  -- Ayah 15 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3355,
    'فَأَنجَیۡنَـٰهُ وَأَصۡحَـٰبَ ٱلسَّفِینَةِ وَجَعَلۡنَـٰهَاۤ ءَایَةࣰ لِّلۡعَـٰلَمِینَ',
    'فانجيناه واصحاب السفينة وجعلناها اية للعالمين',
    'فَأَ<rule class=ikhafa>نج</rule>َيۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَأَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّفِينَةِ وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٥',
    15, 20, 5, 398, 343, 159, 'false'
  );
  
  -- Ayah 16 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3356,
    'وَإِبۡرَ ٰ⁠هِیمَ إِذۡ قَالَ لِقَوۡمِهِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُۖ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ',
    'وابراهيم اذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم ان كنتم تعلمون',
    'وَإِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ إِذۡ قَالَ لِقَوۡمِهِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>تَّقُوهُ‌ۖ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 20, 5, 398, 343, 159, 'false'
  );
  
  -- Ayah 17 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3357,
    'إِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَـٰنࣰا وَتَخۡلُقُونَ إِفۡكًاۚ إِنَّ ٱلَّذِینَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ لَا یَمۡلِكُونَ لَكُمۡ رِزۡقࣰا فَٱبۡتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُوا۟ لَهُۥۤۖ إِلَیۡهِ تُرۡجَعُونَ',
    'انما تعبدون من دون الله اوثانا وتخلقون افكا ان الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له اليه ترجعون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا تَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡثَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َتَخۡلُقُونَ إِفۡكًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا يَمۡلِكُونَ لَكُمۡ رِزۡ<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ وَ<rule class=ham_wasl>ٱ</rule>عۡبُدُوهُ وَ<rule class=ham_wasl>ٱ</rule>شۡكُرُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> إِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 20, 5, 398, 343, 159, 'false'
  );
  
  -- Ayah 18 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3358,
    'وَإِن تُكَذِّبُوا۟ فَقَدۡ كَذَّبَ أُمَمࣱ مِّن قَبۡلِكُمۡۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ',
    'وان تكذبوا فقد كذب امم من قبلكم وما على الرسول الا البلاغ المبين',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُكَذِّبُو<rule class=slnt>اۡ</rule> فَقَ<rule class=qalaqah>دۡ</rule> كَذَّبَ أُمَ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكُمۡ‌ۖ وَمَا عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ١٨',
    18, 20, 5, 398, 343, 159, 'false'
  );
  
  -- Ayah 19 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3359,
    'أَوَلَمۡ یَرَوۡا۟ كَیۡفَ یُبۡدِئُ ٱللَّهُ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥۤۚ إِنَّ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ',
    'اولم يروا كيف يبدئ الله الخلق ثم يعيده ان ذلك على الله يسير',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> كَيۡفَ يُ<rule class=qalaqah>بۡ</rule>دِئُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡخَلۡقَ ثُ<rule class=ghunnah>مّ</rule>َ يُعِيدُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَس<rule class=madda_permissible>ِي</rule>رٌ ١٩',
    19, 20, 5, 398, 343, 159, 'false'
  );
  
  -- Ayah 20 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3360,
    'قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ یُنشِئُ ٱلنَّشۡأَةَ ٱلۡـَٔاخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'قل سيروا في الارض فانظروا كيف بدا الخلق ثم الله ينشئ النشاة الاخرة ان الله على كل شيء قدير',
    'قُلۡ سِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ بَدَأَ <rule class=ham_wasl>ٱ</rule>لۡخَلۡقَ‌ۚ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ يُ<rule class=ikhafa>نش</rule>ِئُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َشۡأَةَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٢٠',
    20, 20, 5, 398, 343, 159, 'false'
  );
  
  -- Ayah 21 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3361,
    'یُعَذِّبُ مَن یَشَاۤءُ وَیَرۡحَمُ مَن یَشَاۤءُۖ وَإِلَیۡهِ تُقۡلَبُونَ',
    'يعذب من يشاء ويرحم من يشاء واليه تقلبون',
    'يُعَذِّبُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَرۡحَمُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ وَإِلَيۡهِ تُ<rule class=qalaqah>قۡ</rule>لَب<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 20, 5, 398, 343, 159, 'false'
  );
  
  -- Ayah 22 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3362,
    'وَمَاۤ أَنتُم بِمُعۡجِزِینَ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ',
    'وما انتم بمعجزين في الارض ولا في السماء وما لكم من دون الله من ولي ولا نصير',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُعۡجِزِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ‌ۖ وَمَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَص<rule class=madda_permissible>ِي</rule>رٍ ٢٢',
    22, 20, 5, 398, 343, 159, 'false'
  );
  
  -- Ayah 23 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3363,
    'وَٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ وَلِقَاۤىِٕهِۦۤ أُو۟لَـٰۤىِٕكَ یَىِٕسُوا۟ مِن رَّحۡمَتِی وَأُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ أَلِیمࣱ',
    'والذين كفروا بايات الله ولقائه اولئك يئسوا من رحمتي واولئك لهم عذاب اليم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَئِسُو<rule class=slnt>اۡ</rule> م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَتِى وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٢٣',
    23, 20, 5, 398, 344, 159, 'false'
  );
  
  -- Ayah 24 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3364,
    'فَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوا۟ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'فما كان جواب قومه الا ان قالوا اقتلوه او حرقوه فانجاه الله من النار ان في ذلك لايات لقوم يؤمنون',
    'فَمَا كَانَ جَوَابَ قَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُلُوهُ أَوۡ حَرِّقُوهُ فَأَ<rule class=ikhafa>نج</rule>َ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 20, 5, 399, 344, 159, 'false'
  );
  
  -- Ayah 25 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3365,
    'وَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَـٰنࣰا مَّوَدَّةَ بَیۡنِكُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ ثُمَّ یَوۡمَ ٱلۡقِیَـٰمَةِ یَكۡفُرُ بَعۡضُكُم بِبَعۡضࣲ وَیَلۡعَنُ بَعۡضُكُم بَعۡضࣰا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِینَ',
    'وقال انما اتخذتم من دون الله اوثانا مودة بينكم في الحياة الدنيا ثم يوم القيامة يكفر بعضكم ببعض ويلعن بعضكم بعضا وماواكم النار وما لكم من ناصرين',
    'وَقَالَ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>تَّخَذۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡثَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>َّوَدَّةَ بَيۡنِكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ يَكۡفُرُ بَعۡضُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>و</rule>َيَلۡعَنُ بَعۡضُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡ<rule class=idgham_ghunnah>ضًا</rule> <rule class=idgham_ghunnah>و</rule>َمَأۡوَ<rule class=madda_normal>ٮٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ وَمَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 20, 5, 399, 344, 159, 'false'
  );
  
  -- Ayah 26 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3366,
    '۞ فَـَٔامَنَ لَهُۥ لُوطࣱۘ وَقَالَ إِنِّی مُهَاجِرٌ إِلَىٰ رَبِّیۤۖ إِنَّهُۥ هُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'فامن له لوط وقال اني مهاجر الى ربي انه هو العزيز الحكيم',
    '۞فَـَٔـامَنَ لَهُ<rule class=madda_normal>ۥ</rule> لُو<rule class=idgham_ghunnah>طٌ‌ۘ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ إِ<rule class=ghunnah>نّ</rule>ِى مُهَاجِرٌ إِلَىٰ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٢٦',
    26, 20, 5, 399, 344, 160, 'false'
  );
  
  -- Ayah 27 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3367,
    'وَوَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَ وَجَعَلۡنَا فِی ذُرِّیَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَـٰبَ وَءَاتَیۡنَـٰهُ أَجۡرَهُۥ فِی ٱلدُّنۡیَاۖ وَإِنَّهُۥ فِی ٱلۡـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِینَ',
    'ووهبنا له اسحاق ويعقوب وجعلنا في ذريته النبوة والكتاب واتيناه اجره في الدنيا وانه في الاخرة لمن الصالحين',
    'وَوَهَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ وَجَعَلۡنَا فِى ذُرِّيَّتِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُبُوَّةَ وَ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ أَ<rule class=qalaqah>جۡ</rule>رَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 20, 5, 399, 344, 160, 'false'
  );
  
  -- Ayah 28 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3368,
    'وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦۤ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدࣲ مِّنَ ٱلۡعَـٰلَمِینَ',
    'ولوطا اذ قال لقومه انكم لتاتون الفاحشة ما سبقكم بها من احد من العالمين',
    'وَلُوطًا إِذۡ قَالَ لِقَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>َكُمۡ لَتَأۡتُونَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>حِشَةَ مَا سَبَقَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا مِنۡ أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٢٨',
    28, 20, 5, 399, 344, 160, 'false'
  );
  
  -- Ayah 29 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3369,
    'أَىِٕنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ ٱلسَّبِیلَ وَتَأۡتُونَ فِی نَادِیكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوا۟ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'ائنكم لتاتون الرجال وتقطعون السبيل وتاتون في ناديكم المنكر فما كان جواب قومه الا ان قالوا ائتنا بعذاب الله ان كنت من الصادقين',
    'أَئِ<rule class=ghunnah>نّ</rule>َكُمۡ لَتَأۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّجَالَ وَتَ<rule class=qalaqah>قۡ</rule>طَعُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلَ وَتَأۡتُونَ فِى نَادِيكُمُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرَ‌ۖ فَمَا كَانَ جَوَابَ قَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>ئۡتِنَا بِعَذَابِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 20, 5, 399, 344, 160, 'false'
  );
  
  -- Ayah 30 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3370,
    'قَالَ رَبِّ ٱنصُرۡنِی عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِینَ',
    'قال رب انصرني على القوم المفسدين',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نص</rule>ُرۡنِى عَلَى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡمُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٣٠',
    30, 20, 5, 399, 344, 160, 'false'
  );
  
  -- Ayah 31 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3371,
    'وَلَمَّا جَاۤءَتۡ رُسُلُنَاۤ إِبۡرَ ٰ⁠هِیمَ بِٱلۡبُشۡرَىٰ قَالُوۤا۟ إِنَّا مُهۡلِكُوۤا۟ أَهۡلِ هَـٰذِهِ ٱلۡقَرۡیَةِۖ إِنَّ أَهۡلَهَا كَانُوا۟ ظَـٰلِمِینَ',
    'ولما جاءت رسلنا ابراهيم بالبشرى قالوا انا مهلكو اهل هذه القرية ان اهلها كانوا ظالمين',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ رُسُلُن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ بِ<rule class=ham_wasl>ٱ</rule>لۡبُشۡرَىٰ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا مُهۡلِك<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡلِ هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ أَهۡلَهَا كَانُو<rule class=slnt>اۡ</rule> ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 20, 5, 400, 345, 160, 'false'
  );
  
  -- Ayah 32 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3372,
    'قَالَ إِنَّ فِیهَا لُوطࣰاۚ قَالُوا۟ نَحۡنُ أَعۡلَمُ بِمَن فِیهَاۖ لَنُنَجِّیَنَّهُۥ وَأَهۡلَهُۥۤ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَـٰبِرِینَ',
    'قال ان فيها لوطا قالوا نحن اعلم بمن فيها لننجينه واهله الا امراته كانت من الغابرين',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َ فِيهَا لُو<rule class=ikhafa>طًا‌ۚ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> نَحۡنُ أَعۡلَمُ بِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِيهَا‌ۖ لَنُنَجِّيَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> وَأَهۡلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>مۡرَأَتَهُ<rule class=madda_normal>ۥ</rule> كَانَتۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 20, 5, 400, 345, 160, 'false'
  );
  
  -- Ayah 33 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3373,
    'وَلَمَّاۤ أَن جَاۤءَتۡ رُسُلُنَا لُوطࣰا سِیۤءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعࣰاۖ وَقَالُوا۟ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا ٱمۡرَأَتَكَ كَانَتۡ مِنَ ٱلۡغَـٰبِرِینَ',
    'ولما ان جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقالوا لا تخف ولا تحزن انا منجوك واهلك الا امراتك كانت من الغابرين',
    'وَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ رُسُلُنَا لُو<rule class=ikhafa>طًا</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ِى</rule>ٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َقَالُو<rule class=slnt>اۡ</rule> لَا تَخَفۡ وَلَا تَحۡزَنۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا <rule class=ham_wasl>ٱ</rule>مۡرَأَتَكَ كَانَتۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٣٣',
    33, 20, 5, 400, 345, 160, 'false'
  );
  
  -- Ayah 34 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3374,
    'إِنَّا مُنزِلُونَ عَلَىٰۤ أَهۡلِ هَـٰذِهِ ٱلۡقَرۡیَةِ رِجۡزࣰا مِّنَ ٱلسَّمَاۤءِ بِمَا كَانُوا۟ یَفۡسُقُونَ',
    'انا منزلون على اهل هذه القرية رجزا من السماء بما كانوا يفسقون',
    'إِ<rule class=ghunnah>نّ</rule>َا مُ<rule class=ikhafa>نز</rule>ِلُونَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِ هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةِ رِ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>زًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡسُق<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 20, 5, 400, 345, 160, 'false'
  );
  
  -- Ayah 35 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3375,
    'وَلَقَد تَّرَكۡنَا مِنۡهَاۤ ءَایَةَۢ بَیِّنَةࣰ لِّقَوۡمࣲ یَعۡقِلُونَ',
    'ولقد تركنا منها اية بينة لقوم يعقلون',
    'وَلَقَ<rule class=idgham_mutajanisayn>د</rule> تَّرَكۡنَا مِنۡه<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 20, 5, 400, 345, 160, 'false'
  );
  
  -- Ayah 36 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3376,
    'وَإِلَىٰ مَدۡیَنَ أَخَاهُمۡ شُعَیۡبࣰا فَقَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱرۡجُوا۟ ٱلۡیَوۡمَ ٱلۡـَٔاخِرَ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ',
    'والى مدين اخاهم شعيبا فقال يا قوم اعبدوا الله وارجوا اليوم الاخر ولا تعثوا في الارض مفسدين',
    'وَإِلَىٰ مَ<rule class=qalaqah>دۡ</rule>يَنَ أَخَاهُمۡ شُعَيۡ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َقَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>رۡجُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَ وَلَا تَعۡثَوۡ<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مُفۡسِد<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 20, 5, 400, 345, 160, 'false'
  );
  
  -- Ayah 37 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3377,
    'فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُوا۟ فِی دَارِهِمۡ جَـٰثِمِینَ',
    'فكذبوه فاخذتهم الرجفة فاصبحوا في دارهم جاثمين',
    'فَكَذَّبُوهُ فَأَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّ<rule class=qalaqah>جۡ</rule>فَةُ فَأَصۡبَحُو<rule class=slnt>اۡ</rule> فِى دَارِهِمۡ جَ<rule class=madda_normal>ـٰ</rule>ثِم<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 20, 5, 400, 345, 160, 'false'
  );
  
  -- Ayah 38 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3378,
    'وَعَادࣰا وَثَمُودَا۟ وَقَد تَّبَیَّنَ لَكُم مِّن مَّسَـٰكِنِهِمۡۖ وَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِیلِ وَكَانُوا۟ مُسۡتَبۡصِرِینَ',
    'وعادا وثمود وقد تبين لكم من مساكنهم وزين لهم الشيطان اعمالهم فصدهم عن السبيل وكانوا مستبصرين',
    'وَعَا<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َثَمُودَ<rule class=slnt>اۡ</rule> وَقَ<rule class=idgham_mutajanisayn>د</rule> تَّبَيَّنَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّسَ<rule class=madda_normal>ـٰ</rule>كِنِهِمۡ‌ۖ وَزَيَّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ فَصَدَّهُمۡ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ وَكَانُو<rule class=slnt>اۡ</rule> مُسۡتَ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ٣٨',
    38, 20, 5, 400, 345, 160, 'false'
  );
  
  -- Ayah 39 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3379,
    'وَقَـٰرُونَ وَفِرۡعَوۡنَ وَهَـٰمَـٰنَۖ وَلَقَدۡ جَاۤءَهُم مُّوسَىٰ بِٱلۡبَیِّنَـٰتِ فَٱسۡتَكۡبَرُوا۟ فِی ٱلۡأَرۡضِ وَمَا كَانُوا۟ سَـٰبِقِینَ',
    'وقارون وفرعون وهامان ولقد جاءهم موسى بالبينات فاستكبروا في الارض وما كانوا سابقين',
    'وَقَ<rule class=madda_normal>ـٰ</rule>رُونَ وَفِرۡعَوۡنَ وَهَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_normal>ـٰ</rule>نَ‌ۖ وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوسَىٰ بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا كَانُو<rule class=slnt>اۡ</rule> سَ<rule class=madda_normal>ـٰ</rule>بِق<rule class=madda_permissible>ِي</rule>نَ ٣٩',
    39, 20, 5, 401, 345, 160, 'false'
  );
  
  -- Ayah 40 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3380,
    'فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَیۡهِ حَاصِبࣰا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّیۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِیَظۡلِمَهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'فكلا اخذنا بذنبه فمنهم من ارسلنا عليه حاصبا ومنهم من اخذته الصيحة ومنهم من خسفنا به الارض ومنهم من اغرقنا وما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون',
    'فَكُلاًّ أَخَذۡنَا بِذَ<rule class=iqlab>نۢب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ أَرۡسَلۡنَا عَلَيۡهِ حَاصِ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ أَخَذَتۡهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡحَةُ وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ خَسَفۡنَا بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ أَغۡرَ<rule class=qalaqah>قۡ</rule>نَا‌ۚ وَمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيَظۡلِمَهُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 20, 5, 401, 345, 160, 'false'
  );
  
  -- Ayah 41 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3381,
    'مَثَلُ ٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوۡلِیَاۤءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَیۡتࣰاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُیُوتِ لَبَیۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ',
    'مثل الذين اتخذوا من دون الله اولياء كمثل العنكبوت اتخذت بيتا وان اوهن البيوت لبيت العنكبوت لو كانوا يعلمون',
    'مَثَلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ كَمَثَلِ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=ikhafa>نك</rule>َبُوتِ <rule class=ham_wasl>ٱ</rule>تَّخَذَتۡ بَيۡ<rule class=idgham_ghunnah>تًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ أَوۡهَنَ <rule class=ham_wasl>ٱ</rule>لۡبُيُوتِ لَبَيۡتُ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=ikhafa>نك</rule>َبُوتِ‌ۖ لَوۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 20, 5, 401, 345, 160, 'false'
  );
  
  -- Ayah 42 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3382,
    'إِنَّ ٱللَّهَ یَعۡلَمُ مَا یَدۡعُونَ مِن دُونِهِۦ مِن شَیۡءࣲۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'ان الله يعلم ما يدعون من دونه من شيء وهو العزيز الحكيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ مَا يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_ghunnah>َىۡءٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٤٢',
    42, 20, 5, 401, 345, 160, 'false'
  );
  
  -- Ayah 43 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3383,
    'وَتِلۡكَ ٱلۡأَمۡثَـٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا یَعۡقِلُهَاۤ إِلَّا ٱلۡعَـٰلِمُونَ',
    'وتلك الامثال نضربها للناس وما يعقلها الا العالمون',
    'وَتِلۡكَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡثَ<rule class=madda_normal>ـٰ</rule>لُ نَضۡرِبُهَا لِل<rule class=ghunnah>نّ</rule>َاسِ‌ۖ وَمَا يَعۡقِلُه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 20, 5, 401, 345, 160, 'false'
  );
  
  -- Ayah 44 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3384,
    'خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّلۡمُؤۡمِنِینَ',
    'خلق الله السماوات والارض بالحق ان في ذلك لاية للمؤمنين',
    'خَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٤٤',
    44, 20, 5, 401, 345, 160, 'false'
  );
  
  -- Ayah 45 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3385,
    'ٱتۡلُ مَاۤ أُوحِیَ إِلَیۡكَ مِنَ ٱلۡكِتَـٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَاۤءِ وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ یَعۡلَمُ مَا تَصۡنَعُونَ',
    'اتل ما اوحي اليك من الكتاب واقم الصلاة ان الصلاة تنهى عن الفحشاء والمنكر ولذكر الله اكبر والله يعلم ما تصنعون',
    'ٱتۡلُ م<rule class=madda_obligatory_monfasel>َآ</rule> أُوحِىَ إِلَيۡكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَأَقِمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ تَنۡهَىٰ عَنِ <rule class=ham_wasl>ٱ</rule>لۡفَحۡش<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ‌ۗ وَلَذِكۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ أَكۡبَرُ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ مَا تَصۡنَع<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 20, 5, 401, 346, 160, 'false'
  );
  
  -- Ayah 46 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3386,
    '۞ وَلَا تُجَـٰدِلُوۤا۟ أَهۡلَ ٱلۡكِتَـٰبِ إِلَّا بِٱلَّتِی هِیَ أَحۡسَنُ إِلَّا ٱلَّذِینَ ظَلَمُوا۟ مِنۡهُمۡۖ وَقُولُوۤا۟ ءَامَنَّا بِٱلَّذِیۤ أُنزِلَ إِلَیۡنَا وَأُنزِلَ إِلَیۡكُمۡ وَإِلَـٰهُنَا وَإِلَـٰهُكُمۡ وَ ٰ⁠حِدࣱ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ',
    'ولا تجادلوا اهل الكتاب الا بالتي هي احسن الا الذين ظلموا منهم وقولوا امنا بالذي انزل الينا وانزل اليكم والهنا والهكم واحد ونحن له مسلمون',
    '۞وَلَا تُجَ<rule class=madda_normal>ـٰ</rule>دِل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لَّتِى هِىَ أَحۡسَنُ إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ‌ۖ وَقُول<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡنَا وَأُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكُمۡ وَإِلَ<rule class=madda_normal>ـٰ</rule>هُنَا وَإِلَ<rule class=madda_normal>ـٰ</rule>هُكُمۡ و<rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َنَحۡنُ لَهُ<rule class=madda_normal>ۥ</rule> مُسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 21, 5, 402, 346, 161, 'false'
  );
  
  -- Ayah 47 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3387,
    'وَكَذَ ٰ⁠لِكَ أَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَۚ فَٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَـٰۤؤُلَاۤءِ مَن یُؤۡمِنُ بِهِۦۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا ٱلۡكَـٰفِرُونَ',
    'وكذلك انزلنا اليك الكتاب فالذين اتيناهم الكتاب يؤمنون به ومن هؤلاء من يؤمن به وما يجحد باياتنا الا الكافرون',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ‌ۚ فَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يُؤۡمِنُونَ بِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمِنۡ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُ بِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَمَا يَ<rule class=qalaqah>جۡ</rule>حَدُ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 21, 5, 402, 346, 161, 'false'
  );
  
  -- Ayah 48 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3388,
    'وَمَا كُنتَ تَتۡلُوا۟ مِن قَبۡلِهِۦ مِن كِتَـٰبࣲ وَلَا تَخُطُّهُۥ بِیَمِینِكَۖ إِذࣰا لَّٱرۡتَابَ ٱلۡمُبۡطِلُونَ',
    'وما كنت تتلو من قبله من كتاب ولا تخطه بيمينك اذا لارتاب المبطلون',
    'وَمَا كُ<rule class=ikhafa>نت</rule>َ تَتۡلُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَخُطُّهُ<rule class=madda_normal>ۥ</rule> بِيَمِينِكَ‌ۖ إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ham_wasl>ٱ</rule>رۡتَابَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>بۡ</rule>طِل<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 21, 5, 402, 346, 161, 'false'
  );
  
  -- Ayah 49 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3389,
    'بَلۡ هُوَ ءَایَـٰتُۢ بَیِّنَـٰتࣱ فِی صُدُورِ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا ٱلظَّـٰلِمُونَ',
    'بل هو ايات بينات في صدور الذين اوتوا العلم وما يجحد باياتنا الا الظالمون',
    'بَلۡ هُوَ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تُۢ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ف</rule>ِى صُدُورِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ‌ۚ وَمَا يَ<rule class=qalaqah>جۡ</rule>حَدُ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 21, 5, 402, 346, 161, 'false'
  );
  
  -- Ayah 50 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3390,
    'وَقَالُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَـٰتࣱ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡـَٔایَـٰتُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینٌ',
    'وقالوا لولا انزل عليه ايات من ربه قل انما الايات عند الله وانما انا نذير مبين',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡهِ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule>‌ۖ قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَإِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٥٠',
    50, 21, 5, 402, 346, 161, 'false'
  );
  
  -- Ayah 51 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3391,
    'أَوَلَمۡ یَكۡفِهِمۡ أَنَّاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ یُتۡلَىٰ عَلَیۡهِمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَرَحۡمَةࣰ وَذِكۡرَىٰ لِقَوۡمࣲ یُؤۡمِنُونَ',
    'اولم يكفهم انا انزلنا عليك الكتاب يتلى عليهم ان في ذلك لرحمة وذكرى لقوم يؤمنون',
    'أَوَلَمۡ يَكۡفِهِمۡ أَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ يُتۡلَىٰ عَلَيۡهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَرَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َذِكۡرَىٰ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 21, 5, 402, 346, 161, 'false'
  );
  
  -- Ayah 52 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3392,
    'قُلۡ كَفَىٰ بِٱللَّهِ بَیۡنِی وَبَیۡنَكُمۡ شَهِیدࣰاۖ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۗ وَٱلَّذِینَ ءَامَنُوا۟ بِٱلۡبَـٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ',
    'قل كفى بالله بيني وبينكم شهيدا يعلم ما في السماوات والارض والذين امنوا بالباطل وكفروا بالله اولئك هم الخاسرون',
    'قُلۡ كَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ بَيۡنِى وَبَيۡنَكُمۡ شَهِي<rule class=idgham_ghunnah>دًا‌ۖ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ وَكَفَرُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 21, 5, 402, 347, 161, 'false'
  );
  
  -- Ayah 53 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3393,
    'وَیَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَوۡلَاۤ أَجَلࣱ مُّسَمࣰّى لَّجَاۤءَهُمُ ٱلۡعَذَابُۚ وَلَیَأۡتِیَنَّهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ',
    'ويستعجلونك بالعذاب ولولا اجل مسمى لجاءهم العذاب ولياتينهم بغتة وهم لا يشعرون',
    'وَيَسۡتَعۡجِلُونَكَ بِ<rule class=ham_wasl>ٱ</rule>لۡعَذَابِ‌ۚ وَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَجَ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=idgham_wo_ghunnah>ًّى</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ وَلَيَأۡتِيَ<rule class=ghunnah>نّ</rule>َه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َغۡتَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 54 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3394,
    'یَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِیطَةُۢ بِٱلۡكَـٰفِرِینَ',
    'يستعجلونك بالعذاب وان جهنم لمحيطة بالكافرين',
    'يَسۡتَعۡجِلُونَكَ بِ<rule class=ham_wasl>ٱ</rule>لۡعَذَابِ وَإِ<rule class=ghunnah>نّ</rule>َ جَهَ<rule class=ghunnah>نّ</rule>َمَ لَمُحِيطَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٥٤',
    54, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 55 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3395,
    'یَوۡمَ یَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ وَیَقُولُ ذُوقُوا۟ مَا كُنتُمۡ تَعۡمَلُونَ',
    'يوم يغشاهم العذاب من فوقهم ومن تحت ارجلهم ويقول ذوقوا ما كنتم تعملون',
    'يَوۡمَ يَغۡشَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهِمۡ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِ أَرۡجُلِهِمۡ وَيَقُولُ ذُوقُو<rule class=slnt>اۡ</rule> مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 56 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3396,
    'یَـٰعِبَادِیَ ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ أَرۡضِی وَ ٰ⁠سِعَةࣱ فَإِیَّـٰیَ فَٱعۡبُدُونِ',
    'يا عبادي الذين امنوا ان ارضي واسعة فاياي فاعبدون',
    'يَ<rule class=madda_normal>ـٰ</rule>عِبَادِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ أَرۡضِى و<rule class=madda_normal>ٰ</rule>سِعَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َإِيَّ<rule class=madda_normal>ـٰ</rule>ىَ فَ<rule class=ham_wasl>ٱ</rule>عۡبُد<rule class=madda_permissible>ُو</rule>نِ ٥٦',
    56, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 57 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3397,
    'كُلُّ نَفۡسࣲ ذَاۤىِٕقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَیۡنَا تُرۡجَعُونَ',
    'كل نفس ذائقة الموت ثم الينا ترجعون',
    'كُلُّ نَفۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِقَةُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ إِلَيۡنَا تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 58 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3398,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفࣰا تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَـٰمِلِینَ',
    'والذين امنوا وعملوا الصالحات لنبوئنهم من الجنة غرفا تجري من تحتها الانهار خالدين فيها نعم اجر العاملين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَنُبَوِّئَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ غُرَ<rule class=ikhafa>فًا</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ نِعۡمَ أَ<rule class=qalaqah>جۡ</rule>رُ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>مِل<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 59 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3399,
    'ٱلَّذِینَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ',
    'الذين صبروا وعلى ربهم يتوكلون',
    'ٱلَّذِينَ صَبَرُو<rule class=slnt>اۡ</rule> وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّل<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 60 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3400,
    'وَكَأَیِّن مِّن دَاۤبَّةࣲ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ یَرۡزُقُهَا وَإِیَّاكُمۡۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'وكاين من دابة لا تحمل رزقها الله يرزقها واياكم وهو السميع العليم',
    'وَكَأَيّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَحۡمِلُ رِزۡقَهَا <rule class=ham_wasl>ٱ</rule>للَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٦٠',
    60, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 61 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3401,
    'وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ لَیَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ یُؤۡفَكُونَ',
    'ولئن سالتهم من خلق السماوات والارض وسخر الشمس والقمر ليقولن الله فانى يؤفكون',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َأَلۡتَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَسَخَّرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ لَيَقُولُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ فَأَ<rule class=ghunnah>نّ</rule>َىٰ يُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 62 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3402,
    'ٱللَّهُ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُ لَهُۥۤۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'الله يبسط الرزق لمن يشاء من عباده ويقدر له ان الله بكل شيء عليم',
    'ٱللَّهُ يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule> وَيَ<rule class=qalaqah>قۡ</rule>دِرُ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٦٢',
    62, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 63 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3403,
    'وَلَىِٕن سَأَلۡتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ مِنۢ بَعۡدِ مَوۡتِهَا لَیَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡقِلُونَ',
    'ولئن سالتهم من نزل من السماء ماء فاحيا به الارض من بعد موتها ليقولن الله قل الحمد لله بل اكثرهم لا يعقلون',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َأَلۡتَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّزَّلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَحۡيَا بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَوۡتِهَا لَيَقُولُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ قُلِ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ‌ۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 21, 5, 403, 347, 161, 'false'
  );
  
  -- Ayah 64 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3404,
    'وَمَا هَـٰذِهِ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا لَهۡوࣱ وَلَعِبࣱۚ وَإِنَّ ٱلدَّارَ ٱلۡـَٔاخِرَةَ لَهِیَ ٱلۡحَیَوَانُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ',
    'وما هذه الحياة الدنيا الا لهو ولعب وان الدار الاخرة لهي الحيوان لو كانوا يعلمون',
    'وَمَا هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡي<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا لَهۡ<rule class=idgham_ghunnah>وٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَعِ<rule class=idgham_ghunnah>بٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ لَهِىَ <rule class=ham_wasl>ٱ</rule>لۡحَيَوَانُ‌ۚ لَوۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 21, 5, 404, 348, 161, 'false'
  );
  
  -- Ayah 65 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3405,
    'فَإِذَا رَكِبُوا۟ فِی ٱلۡفُلۡكِ دَعَوُا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ یُشۡرِكُونَ',
    'فاذا ركبوا في الفلك دعوا الله مخلصين له الدين فلما نجاهم الى البر اذا هم يشركون',
    'فَإِذَا رَكِبُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ دَعَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡلِصِينَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ فَلَ<rule class=ghunnah>مّ</rule>َا نَجَّ<rule class=madda_normal>ـٰ</rule>هُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡبَرِّ إِذَا هُمۡ يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 21, 5, 404, 348, 161, 'false'
  );
  
  -- Ayah 66 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3406,
    'لِیَكۡفُرُوا۟ بِمَاۤ ءَاتَیۡنَـٰهُمۡ وَلِیَتَمَتَّعُوا۟ۚ فَسَوۡفَ یَعۡلَمُونَ',
    'ليكفروا بما اتيناهم وليتمتعوا فسوف يعلمون',
    'لِيَكۡفُرُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَلِيَتَمَتَّعُو<rule class=slnt>اۡ‌ۖ</rule> فَسَوۡفَ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 21, 5, 404, 348, 161, 'false'
  );
  
  -- Ayah 67 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3407,
    'أَوَلَمۡ یَرَوۡا۟ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنࣰا وَیُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَـٰطِلِ یُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ یَكۡفُرُونَ',
    'اولم يروا انا جعلنا حرما امنا ويتخطف الناس من حولهم افبالباطل يؤمنون وبنعمة الله يكفرون',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َا جَعَلۡنَا حَرَمًا ءَامِ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َيُتَخَطَّفُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ مِنۡ حَوۡلِهِمۡ‌ۚ أَفَبِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ <rule class=ham_wasl>ٱ</rule>للَّهِ يَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 21, 5, 404, 348, 161, 'false'
  );
  
  -- Ayah 68 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3408,
    'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ لَمَّا جَاۤءَهُۥۤۚ أَلَیۡسَ فِی جَهَنَّمَ مَثۡوࣰى لِّلۡكَـٰفِرِینَ',
    'ومن اظلم ممن افترى على الله كذبا او كذب بالحق لما جاءه اليس في جهنم مثوى للكافرين',
    'وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا أَوۡ كَذَّبَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> أَلَيۡسَ فِى جَهَ<rule class=ghunnah>نّ</rule>َمَ مَثۡ<rule class=idgham_wo_ghunnah>وًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٦٨',
    68, 21, 5, 404, 348, 161, 'false'
  );
  
  -- Ayah 69 Surah Al-Ankaboot
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    29,
    3409,
    'وَٱلَّذِینَ جَـٰهَدُوا۟ فِینَا لَنَهۡدِیَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِینَ',
    'والذين جاهدوا فينا لنهدينهم سبلنا وان الله لمع المحسنين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ جَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> فِينَا لَنَهۡدِيَ<rule class=ghunnah>نّ</rule>َهُمۡ سُبُلَنَا‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَمَعَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٦٩',
    69, 21, 5, 404, 348, 161, 'false'
  );
  

-- Surah Ar-Room
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (30, 'سُورَةُ الرُّومِ', 'Ar-Room', 'The Romans', 'Meccan', 60);

  -- Ayah 1 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3410,
    'الۤمۤ',
    'الم',
    'ا<rule class=madda_necessary>لٓ</rule><rule class=madda_necessary>مٓ</rule> ١',
    1, 21, 5, 404, 349, 162, 'false'
  );
  
  -- Ayah 2 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3411,
    'غُلِبَتِ ٱلرُّومُ',
    'غلبت الروم',
    'غُلِبَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_permissible>ُو</rule>مُ ٢',
    2, 21, 5, 404, 349, 162, 'false'
  );
  
  -- Ayah 3 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3412,
    'فِیۤ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَیَغۡلِبُونَ',
    'في ادنى الارض وهم من بعد غلبهم سيغلبون',
    'ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>دۡ</rule>نَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ غَلَبِهِمۡ سَيَغۡلِب<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 21, 5, 404, 349, 162, 'false'
  );
  
  -- Ayah 4 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3413,
    'فِی بِضۡعِ سِنِینَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَیَوۡمَىِٕذࣲ یَفۡرَحُ ٱلۡمُؤۡمِنُونَ',
    'في بضع سنين لله الامر من قبل ومن بعد ويومئذ يفرح المؤمنون',
    'فِى بِضۡعِ سِنِينَ‌ۗ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدُ‌ۚ وَيَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َفۡرَحُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 21, 5, 404, 349, 162, 'false'
  );
  
  -- Ayah 5 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3414,
    'بِنَصۡرِ ٱللَّهِۚ یَنصُرُ مَن یَشَاۤءُۖ وَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ',
    'بنصر الله ينصر من يشاء وهو العزيز الرحيم',
    'بِنَصۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ يَ<rule class=ikhafa>نص</rule>ُرُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٥',
    5, 21, 5, 404, 349, 162, 'false'
  );
  
  -- Ayah 6 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3415,
    'وَعۡدَ ٱللَّهِۖ لَا یُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'وعد الله لا يخلف الله وعده ولكن اكثر الناس لا يعلمون',
    'وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ لَا يُخۡلِفُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَعۡدَهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 21, 5, 405, 349, 162, 'false'
  );
  
  -- Ayah 7 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3416,
    'یَعۡلَمُونَ ظَـٰهِرࣰا مِّنَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَهُمۡ عَنِ ٱلۡـَٔاخِرَةِ هُمۡ غَـٰفِلُونَ',
    'يعلمون ظاهرا من الحياة الدنيا وهم عن الاخرة هم غافلون',
    'يَعۡلَمُونَ ظَ<rule class=madda_normal>ـٰ</rule>هِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَهُمۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمۡ غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 21, 5, 405, 349, 162, 'false'
  );
  
  -- Ayah 8 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3417,
    'أَوَلَمۡ یَتَفَكَّرُوا۟ فِیۤ أَنفُسِهِمۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَاۤ إِلَّا بِٱلۡحَقِّ وَأَجَلࣲ مُّسَمࣰّىۗ وَإِنَّ كَثِیرࣰا مِّنَ ٱلنَّاسِ بِلِقَاۤىِٕ رَبِّهِمۡ لَكَـٰفِرُونَ',
    'اولم يتفكروا في انفسهم ما خلق الله السماوات والارض وما بينهما الا بالحق واجل مسمى وان كثيرا من الناس بلقاء ربهم لكافرون',
    'أَوَلَمۡ يَتَفَكَّرُو<rule class=slnt>اۡ</rule> ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِه<rule class=idgham_shafawi>ِم‌ۗ</rule> <rule class=idgham_shafawi>م</rule>َّا خَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَأَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=idgham_ghunnah>ًّى‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِلِقَآىِٕ رَبِّهِمۡ لَكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 21, 5, 405, 349, 162, 'false'
  );
  
  -- Ayah 9 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3418,
    'أَوَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَانُوۤا۟ أَشَدَّ مِنۡهُمۡ قُوَّةࣰ وَأَثَارُوا۟ ٱلۡأَرۡضَ وَعَمَرُوهَاۤ أَكۡثَرَ مِمَّا عَمَرُوهَا وَجَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِۖ فَمَا كَانَ ٱللَّهُ لِیَظۡلِمَهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ',
    'اولم يسيروا في الارض فينظروا كيف كان عاقبة الذين من قبلهم كانوا اشد منهم قوة واثاروا الارض وعمروها اكثر مما عمروها وجاءتهم رسلهم بالبينات فما كان الله ليظلمهم ولكن كانوا انفسهم يظلمون',
    'أَوَلَمۡ يَسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَيَ<rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَشَدَّ مِنۡهُمۡ قُوَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَثَارُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَعَمَرُوه<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡثَرَ مِ<rule class=ghunnah>مّ</rule>َا عَمَرُوهَا وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ‌ۖ فَمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيَظۡلِمَهُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ يَظۡلِم<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 21, 5, 405, 349, 162, 'false'
  );
  
  -- Ayah 10 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3419,
    'ثُمَّ كَانَ عَـٰقِبَةَ ٱلَّذِینَ أَسَـٰۤـُٔوا۟ ٱلسُّوۤأَىٰۤ أَن كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا یَسۡتَهۡزِءُونَ',
    'ثم كان عاقبة الذين اساءوا السواى ان كذبوا بايات الله وكانوا بها يستهزئون',
    'ثُ<rule class=ghunnah>مّ</rule>َ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَسَ<rule class=madda_obligatory_mottasel>ـٰٓـ</rule>ــُٔو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓأَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَكَانُو<rule class=slnt>اۡ</rule> بِهَا يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 21, 5, 405, 349, 162, 'false'
  );
  
  -- Ayah 11 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3420,
    'ٱللَّهُ یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ ثُمَّ إِلَیۡهِ تُرۡجَعُونَ',
    'الله يبدا الخلق ثم يعيده ثم اليه ترجعون',
    'ٱللَّهُ يَ<rule class=qalaqah>بۡ</rule>دَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَلۡقَ ثُ<rule class=ghunnah>مّ</rule>َ يُعِيدُهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ إِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 21, 5, 405, 350, 162, 'false'
  );
  
  -- Ayah 12 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3421,
    'وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یُبۡلِسُ ٱلۡمُجۡرِمُونَ',
    'ويوم تقوم الساعة يبلس المجرمون',
    'وَيَوۡمَ تَقُومُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ يُ<rule class=qalaqah>بۡ</rule>لِسُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 21, 5, 405, 350, 162, 'false'
  );
  
  -- Ayah 13 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3422,
    'وَلَمۡ یَكُن لَّهُم مِّن شُرَكَاۤىِٕهِمۡ شُفَعَـٰۤؤُا۟ وَكَانُوا۟ بِشُرَكَاۤىِٕهِمۡ كَـٰفِرِینَ',
    'ولم يكن لهم من شركائهم شفعاء وكانوا بشركائهم كافرين',
    'وَلَمۡ يَك<rule class=idgham_wo_ghunnah>ُن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ شُفَعَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> وَكَانُو<rule class=slnt>اۡ</rule> بِشُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 21, 5, 405, 350, 162, 'false'
  );
  
  -- Ayah 14 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3423,
    'وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یَوۡمَىِٕذࣲ یَتَفَرَّقُونَ',
    'ويوم تقوم الساعة يومئذ يتفرقون',
    'وَيَوۡمَ تَقُومُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَرَّق<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 21, 5, 405, 350, 162, 'false'
  );
  
  -- Ayah 15 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3424,
    'فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَهُمۡ فِی رَوۡضَةࣲ یُحۡبَرُونَ',
    'فاما الذين امنوا وعملوا الصالحات فهم في روضة يحبرون',
    'فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فَهُمۡ فِى رَوۡضَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُحۡبَر<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 21, 5, 405, 350, 162, 'false'
  );
  
  -- Ayah 16 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3425,
    'وَأَمَّا ٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَا وَلِقَاۤىِٕ ٱلۡـَٔاخِرَةِ فَأُو۟لَـٰۤىِٕكَ فِی ٱلۡعَذَابِ مُحۡضَرُونَ',
    'واما الذين كفروا وكذبوا باياتنا ولقاء الاخرة فاولئك في العذاب محضرون',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَكَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَلِقَآىِٕ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ فِى <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ مُحۡضَر<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 21, 5, 406, 350, 162, 'false'
  );
  
  -- Ayah 17 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3426,
    'فَسُبۡحَـٰنَ ٱللَّهِ حِینَ تُمۡسُونَ وَحِینَ تُصۡبِحُونَ',
    'فسبحان الله حين تمسون وحين تصبحون',
    'فَسُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ حِينَ تُمۡسُونَ وَحِينَ تُصۡبِح<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 21, 5, 406, 350, 162, 'false'
  );
  
  -- Ayah 18 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3427,
    'وَلَهُ ٱلۡحَمۡدُ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَعَشِیࣰّا وَحِینَ تُظۡهِرُونَ',
    'وله الحمد في السماوات والارض وعشيا وحين تظهرون',
    'وَلَهُ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَعَشِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َحِينَ تُظۡهِر<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 21, 5, 406, 350, 162, 'false'
  );
  
  -- Ayah 19 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3428,
    'یُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَیُخۡرِجُ ٱلۡمَیِّتَ مِنَ ٱلۡحَیِّ وَیُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ وَكَذَ ٰ⁠لِكَ تُخۡرَجُونَ',
    'يخرج الحي من الميت ويخرج الميت من الحي ويحيي الارض بعد موتها وكذلك تخرجون',
    'يُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡحَىَّ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَيِّتِ وَيُخۡرِجُ <rule class=ham_wasl>ٱ</rule>لۡمَيِّتَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَىِّ وَيُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَعۡدَ مَوۡتِهَا‌ۚ وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ تُخۡرَج<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 21, 5, 406, 350, 162, 'false'
  );
  
  -- Ayah 20 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3429,
    'وَمِنۡ ءَایَـٰتِهِۦۤ أَنۡ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ إِذَاۤ أَنتُم بَشَرࣱ تَنتَشِرُونَ',
    'ومن اياته ان خلقكم من تراب ثم اذا انتم بشر تنتشرون',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَنۡ خَلَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َشَ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نت</rule>َشِر<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 21, 5, 406, 351, 162, 'false'
  );
  
  -- Ayah 21 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3430,
    'وَمِنۡ ءَایَـٰتِهِۦۤ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَ ٰ⁠جࣰا لِّتَسۡكُنُوۤا۟ إِلَیۡهَا وَجَعَلَ بَیۡنَكُم مَّوَدَّةࣰ وَرَحۡمَةًۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ',
    'ومن اياته ان خلق لكم من انفسكم ازواجا لتسكنوا اليها وجعل بينكم مودة ورحمة ان في ذلك لايات لقوم يتفكرون',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَنۡ خَلَقَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_wo_ghunnah>جًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتَسۡكُن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهَا وَجَعَلَ بَيۡنَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوَدَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَةً‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 21, 5, 406, 351, 162, 'false'
  );
  
  -- Ayah 22 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3431,
    'وَمِنۡ ءَایَـٰتِهِۦ خَلۡقُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَٱخۡتِلَـٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَ ٰ⁠نِكُمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّلۡعَـٰلِمِینَ',
    'ومن اياته خلق السماوات والارض واختلاف السنتكم والوانكم ان في ذلك لايات للعالمين',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> خَلۡقُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule>خۡتِلَ<rule class=madda_normal>ـٰ</rule>فُ أَلۡسِنَتِكُمۡ وَأَلۡو<rule class=madda_normal>ٰ</rule>نِكُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٢',
    22, 21, 5, 406, 351, 162, 'false'
  );
  
  -- Ayah 23 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3432,
    'وَمِنۡ ءَایَـٰتِهِۦ مَنَامُكُم بِٱلَّیۡلِ وَٱلنَّهَارِ وَٱبۡتِغَاۤؤُكُم مِّن فَضۡلِهِۦۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَسۡمَعُونَ',
    'ومن اياته منامكم بالليل والنهار وابتغاؤكم من فضله ان في ذلك لايات لقوم يسمعون',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> مَنَامُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡمَع<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 21, 5, 406, 351, 162, 'false'
  );
  
  -- Ayah 24 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3433,
    'وَمِنۡ ءَایَـٰتِهِۦ یُرِیكُمُ ٱلۡبَرۡقَ خَوۡفࣰا وَطَمَعࣰا وَیُنَزِّلُ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَیُحۡیِۦ بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ',
    'ومن اياته يريكم البرق خوفا وطمعا وينزل من السماء ماء فيحيي به الارض بعد موتها ان في ذلك لايات لقوم يعقلون',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> يُرِيكُمُ <rule class=ham_wasl>ٱ</rule>لۡبَرۡقَ خَوۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َطَمَ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َيُنَزِّلُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َيُحۡى<rule class=madda_normal>ِۦ</rule> بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَعۡدَ مَوۡتِه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 21, 5, 406, 351, 162, 'false'
  );
  
  -- Ayah 25 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3434,
    'وَمِنۡ ءَایَـٰتِهِۦۤ أَن تَقُومَ ٱلسَّمَاۤءُ وَٱلۡأَرۡضُ بِأَمۡرِهِۦۚ ثُمَّ إِذَا دَعَاكُمۡ دَعۡوَةࣰ مِّنَ ٱلۡأَرۡضِ إِذَاۤ أَنتُمۡ تَخۡرُجُونَ',
    'ومن اياته ان تقوم السماء والارض بامره ثم اذا دعاكم دعوة من الارض اذا انتم تخرجون',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُومَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ بِأَمۡرِه<rule class=madda_normal>ِۦ</rule>‌ۚ ثُ<rule class=ghunnah>مّ</rule>َ إِذَا دَعَاكُمۡ دَعۡوَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ تَخۡرُج<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 21, 5, 407, 351, 162, 'false'
  );
  
  -- Ayah 26 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3435,
    'وَلَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ كُلࣱّ لَّهُۥ قَـٰنِتُونَ',
    'وله من في السماوات والارض كل له قانتون',
    'وَلَهُ<rule class=madda_normal>ۥ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ كُ<rule class=idgham_wo_ghunnah>لٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> قَ<rule class=madda_normal>ـٰ</rule>نِت<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 21, 5, 407, 351, 162, 'false'
  );
  
  -- Ayah 27 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3436,
    'وَهُوَ ٱلَّذِی یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ وَهُوَ أَهۡوَنُ عَلَیۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'وهو الذي يبدا الخلق ثم يعيده وهو اهون عليه وله المثل الاعلى في السماوات والارض وهو العزيز الحكيم',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يَ<rule class=qalaqah>بۡ</rule>دَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَلۡقَ ثُ<rule class=ghunnah>مّ</rule>َ يُعِيدُهُ<rule class=madda_normal>ۥ</rule> وَهُوَ أَهۡوَنُ عَلَيۡهِ‌ۚ وَلَهُ <rule class=ham_wasl>ٱ</rule>لۡمَثَلُ <rule class=ham_wasl>ٱ</rule>لۡأَعۡلَىٰ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٢٧',
    27, 21, 5, 407, 351, 162, 'false'
  );
  
  -- Ayah 28 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3437,
    'ضَرَبَ لَكُم مَّثَلࣰا مِّنۡ أَنفُسِكُمۡۖ هَل لَّكُم مِّن مَّا مَلَكَتۡ أَیۡمَـٰنُكُم مِّن شُرَكَاۤءَ فِی مَا رَزَقۡنَـٰكُمۡ فَأَنتُمۡ فِیهِ سَوَاۤءࣱ تَخَافُونَهُمۡ كَخِیفَتِكُمۡ أَنفُسَكُمۡۚ كَذَ ٰ⁠لِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡقِلُونَ',
    'ضرب لكم مثلا من انفسكم هل لكم من ما ملكت ايمانكم من شركاء في ما رزقناكم فانتم فيه سواء تخافونهم كخيفتكم انفسكم كذلك نفصل الايات لقوم يعقلون',
    'ضَرَبَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّثَل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۖ هَل لَّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فِى مَا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ فَأَ<rule class=ikhafa>نت</rule>ُمۡ فِيهِ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٌ</rule> <rule class=ikhafa>ت</rule>َخَافُونَهُمۡ كَخِيفَتِكُمۡ أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نُفَصِّلُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لِقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 21, 5, 407, 352, 162, 'false'
  );
  
  -- Ayah 29 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3438,
    'بَلِ ٱتَّبَعَ ٱلَّذِینَ ظَلَمُوۤا۟ أَهۡوَاۤءَهُم بِغَیۡرِ عِلۡمࣲۖ فَمَن یَهۡدِی مَنۡ أَضَلَّ ٱللَّهُۖ وَمَا لَهُم مِّن نَّـٰصِرِینَ',
    'بل اتبع الذين ظلموا اهواءهم بغير علم فمن يهدي من اضل الله وما لهم من ناصرين',
    'بَلِ <rule class=ham_wasl>ٱ</rule>تَّبَعَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِغَيۡرِ عِلۡ<rule class=ikhafa>مٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِى مَنۡ أَضَلَّ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَمَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 21, 5, 407, 352, 162, 'false'
  );
  
  -- Ayah 30 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3439,
    'فَأَقِمۡ وَجۡهَكَ لِلدِّینِ حَنِیفࣰاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِی فَطَرَ ٱلنَّاسَ عَلَیۡهَاۚ لَا تَبۡدِیلَ لِخَلۡقِ ٱللَّهِۚ ذَ ٰ⁠لِكَ ٱلدِّینُ ٱلۡقَیِّمُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'فاقم وجهك للدين حنيفا فطرت الله التي فطر الناس عليها لا تبديل لخلق الله ذلك الدين القيم ولكن اكثر الناس لا يعلمون',
    'فَأَقِمۡ وَ<rule class=qalaqah>جۡ</rule>هَكَ لِلدِّينِ حَنِي<rule class=ikhafa>فًا‌ۚ</rule> <rule class=ikhafa>ف</rule>ِ<rule class=qalaqah>طۡ</rule>رَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّتِى فَطَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ عَلَيۡهَا‌ۚ لَا تَ<rule class=qalaqah>بۡ</rule>دِيلَ لِخَلۡقِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينُ <rule class=ham_wasl>ٱ</rule>لۡقَيِّمُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 21, 5, 407, 352, 162, 'false'
  );
  
  -- Ayah 31 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3440,
    '۞ مُنِیبِینَ إِلَیۡهِ وَٱتَّقُوهُ وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلۡمُشۡرِكِینَ',
    'منيبين اليه واتقوه واقيموا الصلاة ولا تكونوا من المشركين',
    '۞مُنِيبِينَ إِلَيۡهِ وَ<rule class=ham_wasl>ٱ</rule>تَّقُوهُ وَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَلَا تَكُونُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 21, 5, 407, 352, 163, 'false'
  );
  
  -- Ayah 32 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3441,
    'مِنَ ٱلَّذِینَ فَرَّقُوا۟ دِینَهُمۡ وَكَانُوا۟ شِیَعࣰاۖ كُلُّ حِزۡبِۭ بِمَا لَدَیۡهِمۡ فَرِحُونَ',
    'من الذين فرقوا دينهم وكانوا شيعا كل حزب بما لديهم فرحون',
    'مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ فَرَّقُو<rule class=slnt>اۡ</rule> دِينَهُمۡ وَكَانُو<rule class=slnt>اۡ</rule> شِيَ<rule class=ikhafa>عًا‌ۖ</rule> <rule class=ikhafa>ك</rule>ُلُّ حِزۡ<rule class=iqlab>بِۭ</rule> <rule class=iqlab>ب</rule>ِمَا لَدَيۡهِمۡ فَرِح<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 21, 5, 407, 352, 163, 'false'
  );
  
  -- Ayah 33 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3442,
    'وَإِذَا مَسَّ ٱلنَّاسَ ضُرࣱّ دَعَوۡا۟ رَبَّهُم مُّنِیبِینَ إِلَیۡهِ ثُمَّ إِذَاۤ أَذَاقَهُم مِّنۡهُ رَحۡمَةً إِذَا فَرِیقࣱ مِّنۡهُم بِرَبِّهِمۡ یُشۡرِكُونَ',
    'واذا مس الناس ضر دعوا ربهم منيبين اليه ثم اذا اذاقهم منه رحمة اذا فريق منهم بربهم يشركون',
    'وَإِذَا مَسَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ ضُ<rule class=ikhafa>رٌّ</rule> <rule class=ikhafa>د</rule>َعَوۡ<rule class=slnt>اۡ</rule> رَبَّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّنِيبِينَ إِلَيۡهِ ثُ<rule class=ghunnah>مّ</rule>َ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَذَاقَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ رَحۡمَةً إِذَا فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرَبِّهِمۡ يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 21, 5, 408, 352, 163, 'false'
  );
  
  -- Ayah 34 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3443,
    'لِیَكۡفُرُوا۟ بِمَاۤ ءَاتَیۡنَـٰهُمۡۚ فَتَمَتَّعُوا۟ فَسَوۡفَ تَعۡلَمُونَ',
    'ليكفروا بما اتيناهم فتمتعوا فسوف تعلمون',
    'لِيَكۡفُرُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ‌ۚ فَتَمَتَّعُو<rule class=slnt>اۡ</rule> فَسَوۡفَ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 21, 5, 408, 352, 163, 'false'
  );
  
  -- Ayah 35 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3444,
    'أَمۡ أَنزَلۡنَا عَلَیۡهِمۡ سُلۡطَـٰنࣰا فَهُوَ یَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ یُشۡرِكُونَ',
    'ام انزلنا عليهم سلطانا فهو يتكلم بما كانوا به يشركون',
    'أَمۡ أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡهِمۡ سُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َهُوَ يَتَكَلَّمُ بِمَا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 21, 5, 408, 352, 163, 'false'
  );
  
  -- Ayah 36 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3445,
    'وَإِذَاۤ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةࣰ فَرِحُوا۟ بِهَاۖ وَإِن تُصِبۡهُمۡ سَیِّئَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ إِذَا هُمۡ یَقۡنَطُونَ',
    'واذا اذقنا الناس رحمة فرحوا بها وان تصبهم سيئة بما قدمت ايديهم اذا هم يقنطون',
    'وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَذَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ رَحۡمَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َرِحُو<rule class=slnt>اۡ</rule> بِهَا‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِ<rule class=qalaqah>بۡ</rule>هُمۡ سَيِّئَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَ<rule class=qalaqah>قۡ</rule>نَط<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 21, 5, 408, 352, 163, 'false'
  );
  
  -- Ayah 37 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3446,
    'أَوَلَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'اولم يروا ان الله يبسط الرزق لمن يشاء ويقدر ان في ذلك لايات لقوم يؤمنون',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَ<rule class=qalaqah>قۡ</rule>دِرُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 21, 5, 408, 352, 163, 'false'
  );
  
  -- Ayah 38 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3447,
    'فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِینَ وَٱبۡنَ ٱلسَّبِیلِۚ ذَ ٰ⁠لِكَ خَیۡرࣱ لِّلَّذِینَ یُرِیدُونَ وَجۡهَ ٱللَّهِۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'فات ذا القربى حقه والمسكين وابن السبيل ذلك خير للذين يريدون وجه الله واولئك هم المفلحون',
    'فَـَٔـاتِ ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ حَقَّهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡمِسۡكِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ يُرِيدُونَ وَ<rule class=qalaqah>جۡ</rule>هَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 21, 5, 408, 352, 163, 'false'
  );
  
  -- Ayah 39 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3448,
    'وَمَاۤ ءَاتَیۡتُم مِّن رِّبࣰا لِّیَرۡبُوَا۟ فِیۤ أَمۡوَ ٰ⁠لِ ٱلنَّاسِ فَلَا یَرۡبُوا۟ عِندَ ٱللَّهِۖ وَمَاۤ ءَاتَیۡتُم مِّن زَكَوٰةࣲ تُرِیدُونَ وَجۡهَ ٱللَّهِ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُضۡعِفُونَ',
    'وما اتيتم من ربا ليربو في اموال الناس فلا يربو عند الله وما اتيتم من زكاة تريدون وجه الله فاولئك هم المضعفون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّ<rule class=idgham_wo_ghunnah>بًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَرۡبُوَ<rule class=slnt>اۡ</rule> ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ فَلَا يَرۡبُو<rule class=slnt>اۡ</rule> عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>َكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule><rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ت</rule>ُرِيدُونَ وَ<rule class=qalaqah>جۡ</rule>هَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُضۡعِف<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 21, 5, 408, 352, 163, 'false'
  );
  
  -- Ayah 40 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3449,
    'ٱللَّهُ ٱلَّذِی خَلَقَكُمۡ ثُمَّ رَزَقَكُمۡ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡۖ هَلۡ مِن شُرَكَاۤىِٕكُم مَّن یَفۡعَلُ مِن ذَ ٰ⁠لِكُم مِّن شَیۡءࣲۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ',
    'الله الذي خلقكم ثم رزقكم ثم يميتكم ثم يحييكم هل من شركائكم من يفعل من ذلكم من شيء سبحانه وتعالى عما يشركون',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ رَزَقَكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يُمِيتُكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يُحۡيِيكُمۡ‌ۖ هَلۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>س</rule>ُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> وَتَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 21, 5, 408, 352, 163, 'false'
  );
  
  -- Ayah 41 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3450,
    'ظَهَرَ ٱلۡفَسَادُ فِی ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَیۡدِی ٱلنَّاسِ لِیُذِیقَهُم بَعۡضَ ٱلَّذِی عَمِلُوا۟ لَعَلَّهُمۡ یَرۡجِعُونَ',
    'ظهر الفساد في البر والبحر بما كسبت ايدي الناس ليذيقهم بعض الذي عملوا لعلهم يرجعون',
    'ظَهَرَ <rule class=ham_wasl>ٱ</rule>لۡفَسَادُ فِى <rule class=ham_wasl>ٱ</rule>لۡبَرِّ وَ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لِيُذِيقَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضَ <rule class=ham_wasl>ٱ</rule>لَّذِى عَمِلُو<rule class=slnt>اۡ</rule> لَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 21, 5, 408, 353, 163, 'false'
  );
  
  -- Ayah 42 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3451,
    'قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِینَ',
    'قل سيروا في الارض فانظروا كيف كان عاقبة الذين من قبل كان اكثرهم مشركين',
    'قُلۡ سِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۚ كَانَ أَكۡثَرُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٤٢',
    42, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 43 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3452,
    'فَأَقِمۡ وَجۡهَكَ لِلدِّینِ ٱلۡقَیِّمِ مِن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۖ یَوۡمَىِٕذࣲ یَصَّدَّعُونَ',
    'فاقم وجهك للدين القيم من قبل ان ياتي يوم لا مرد له من الله يومئذ يصدعون',
    'فَأَقِمۡ وَ<rule class=qalaqah>جۡ</rule>هَكَ لِلدِّينِ <rule class=ham_wasl>ٱ</rule>لۡقَيِّمِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِىَ يَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا مَرَدَّ لَهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َصَّدَّع<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 44 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3453,
    'مَن كَفَرَ فَعَلَیۡهِ كُفۡرُهُۥۖ وَمَنۡ عَمِلَ صَـٰلِحࣰا فَلِأَنفُسِهِمۡ یَمۡهَدُونَ',
    'من كفر فعليه كفره ومن عمل صالحا فلانفسهم يمهدون',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ فَعَلَيۡهِ كُفۡرُهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَمَنۡ عَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َلِأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ يَمۡهَد<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 45 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3454,
    'لِیَجۡزِیَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِن فَضۡلِهِۦۤۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡكَـٰفِرِینَ',
    'ليجزي الذين امنوا وعملوا الصالحات من فضله انه لا يحب الكافرين',
    'لِيَ<rule class=qalaqah>جۡ</rule>زِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٤٥',
    45, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 46 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3455,
    'وَمِنۡ ءَایَـٰتِهِۦۤ أَن یُرۡسِلَ ٱلرِّیَاحَ مُبَشِّرَ ٰ⁠تࣲ وَلِیُذِیقَكُم مِّن رَّحۡمَتِهِۦ وَلِتَجۡرِیَ ٱلۡفُلۡكُ بِأَمۡرِهِۦ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ',
    'ومن اياته ان يرسل الرياح مبشرات وليذيقكم من رحمته ولتجري الفلك بامره ولتبتغوا من فضله ولعلكم تشكرون',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرۡسِلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَاحَ مُبَشِّر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َلِيُذِيقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَتِه<rule class=madda_normal>ِۦ</rule> وَلِتَ<rule class=qalaqah>جۡ</rule>رِىَ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكُ بِأَمۡرِه<rule class=madda_normal>ِۦ</rule> وَلِتَ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> وَلَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 47 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3456,
    'وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَاۤءُوهُم بِٱلۡبَیِّنَـٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِینَ أَجۡرَمُوا۟ۖ وَكَانَ حَقًّا عَلَیۡنَا نَصۡرُ ٱلۡمُؤۡمِنِینَ',
    'ولقد ارسلنا من قبلك رسلا الى قومهم فجاءوهم بالبينات فانتقمنا من الذين اجرموا وكان حقا علينا نصر المؤمنين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ رُسُلاً إِلَىٰ قَوۡمِهِمۡ فَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َقَمۡنَا مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَ<rule class=qalaqah>جۡ</rule>رَمُو<rule class=slnt>اۡ‌ۖ</rule> وَكَانَ حَقًّا عَلَيۡنَا نَصۡرُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 48 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3457,
    'ٱللَّهُ ٱلَّذِی یُرۡسِلُ ٱلرِّیَـٰحَ فَتُثِیرُ سَحَابࣰا فَیَبۡسُطُهُۥ فِی ٱلسَّمَاۤءِ كَیۡفَ یَشَاۤءُ وَیَجۡعَلُهُۥ كِسَفࣰا فَتَرَى ٱلۡوَدۡقَ یَخۡرُجُ مِنۡ خِلَـٰلِهِۦۖ فَإِذَاۤ أَصَابَ بِهِۦ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۤ إِذَا هُمۡ یَسۡتَبۡشِرُونَ',
    'الله الذي يرسل الرياح فتثير سحابا فيبسطه في السماء كيف يشاء ويجعله كسفا فترى الودق يخرج من خلاله فاذا اصاب به من يشاء من عباده اذا هم يستبشرون',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى يُرۡسِلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حَ فَتُثِيرُ سَحَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َيَ<rule class=qalaqah>بۡ</rule>سُطُهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ كَيۡفَ يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَ<rule class=qalaqah>جۡ</rule>عَلُهُ<rule class=madda_normal>ۥ</rule> كِسَ<rule class=ikhafa>فًا</rule> <rule class=ikhafa>ف</rule>َتَرَى <rule class=ham_wasl>ٱ</rule>لۡوَ<rule class=qalaqah>دۡ</rule>قَ يَخۡرُجُ مِنۡ خِلَ<rule class=madda_normal>ـٰ</rule>لِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَ بِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِذَا هُمۡ يَسۡتَ<rule class=qalaqah>بۡ</rule>شِر<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 49 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3458,
    'وَإِن كَانُوا۟ مِن قَبۡلِ أَن یُنَزَّلَ عَلَیۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِینَ',
    'وان كانوا من قبل ان ينزل عليهم من قبله لمبلسين',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُنَزَّلَ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> لَمُ<rule class=qalaqah>بۡ</rule>لِس<rule class=madda_permissible>ِي</rule>نَ ٤٩',
    49, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 50 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3459,
    'فَٱنظُرۡ إِلَىٰۤ ءَاثَـٰرِ رَحۡمَتِ ٱللَّهِ كَیۡفَ یُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۤۚ إِنَّ ذَ ٰ⁠لِكَ لَمُحۡیِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'فانظر الى اثار رحمت الله كيف يحيي الارض بعد موتها ان ذلك لمحيي الموتى وهو على كل شيء قدير',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاثَ<rule class=madda_normal>ـٰ</rule>رِ رَحۡمَتِ <rule class=ham_wasl>ٱ</rule>للَّهِ كَيۡفَ يُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَعۡدَ مَوۡتِه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ لَمُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ‌ۖ وَهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٥٠',
    50, 21, 5, 409, 353, 163, 'false'
  );
  
  -- Ayah 51 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3460,
    'وَلَىِٕنۡ أَرۡسَلۡنَا رِیحࣰا فَرَأَوۡهُ مُصۡفَرࣰّا لَّظَلُّوا۟ مِنۢ بَعۡدِهِۦ یَكۡفُرُونَ',
    'ولئن ارسلنا ريحا فراوه مصفرا لظلوا من بعده يكفرون',
    'وَلَئِنۡ أَرۡسَلۡنَا رِي<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َرَأَوۡهُ مُصۡفَر<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّظَلُّو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> يَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 21, 5, 410, 353, 163, 'false'
  );
  
  -- Ayah 52 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3461,
    'فَإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَاۤءَ إِذَا وَلَّوۡا۟ مُدۡبِرِینَ',
    'فانك لا تسمع الموتى ولا تسمع الصم الدعاء اذا ولوا مدبرين',
    'فَإِ<rule class=ghunnah>نّ</rule>َكَ لَا تُسۡمِعُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ وَلَا تُسۡمِعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِذَا وَلَّوۡ<rule class=slnt>اۡ</rule> مُ<rule class=qalaqah>دۡ</rule>بِر<rule class=madda_permissible>ِي</rule>نَ ٥٢',
    52, 21, 5, 410, 353, 163, 'false'
  );
  
  -- Ayah 53 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3462,
    'وَمَاۤ أَنتَ بِهَـٰدِ ٱلۡعُمۡیِ عَن ضَلَـٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن یُؤۡمِنُ بِـَٔایَـٰتِنَا فَهُم مُّسۡلِمُونَ',
    'وما انت بهاد العمي عن ضلالتهم ان تسمع الا من يؤمن باياتنا فهم مسلمون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ بِهَ<rule class=madda_normal>ـٰ</rule>دِ <rule class=ham_wasl>ٱ</rule>لۡعُمۡىِ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَ<rule class=madda_normal>ـٰ</rule>لَتِهِمۡ‌ۖ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُسۡمِعُ إِلَّا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا فَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 21, 5, 410, 353, 163, 'false'
  );
  
  -- Ayah 54 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3463,
    '۞ ٱللَّهُ ٱلَّذِی خَلَقَكُم مِّن ضَعۡفࣲ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفࣲ قُوَّةࣰ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةࣲ ضَعۡفࣰا وَشَیۡبَةࣰۚ یَخۡلُقُ مَا یَشَاۤءُۚ وَهُوَ ٱلۡعَلِیمُ ٱلۡقَدِیرُ',
    'الله الذي خلقكم من ضعف ثم جعل من بعد ضعف قوة ثم جعل من بعد قوة ضعفا وشيبة يخلق ما يشاء وهو العليم القدير',
    '۞ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َعۡ<rule class=ikhafa>فٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ جَعَلَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ضَعۡ<rule class=ikhafa>فٍ</rule> <rule class=ikhafa>ق</rule>ُوَّ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ جَعَلَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ قُوَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ض</rule>َعۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َشَيۡبَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>َخۡلُقُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِيمُ <rule class=ham_wasl>ٱ</rule>لۡقَد<rule class=madda_permissible>ِي</rule>رُ ٥٤',
    54, 21, 5, 410, 354, 164, 'false'
  );
  
  -- Ayah 55 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3464,
    'وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُوا۟ غَیۡرَ سَاعَةࣲۚ كَذَ ٰ⁠لِكَ كَانُوا۟ یُؤۡفَكُونَ',
    'ويوم تقوم الساعة يقسم المجرمون ما لبثوا غير ساعة كذلك كانوا يؤفكون',
    'وَيَوۡمَ تَقُومُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ يُ<rule class=qalaqah>قۡ</rule>سِمُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمُونَ مَا لَبِثُو<rule class=slnt>اۡ</rule> غَيۡرَ سَاعَ<rule class=ikhafa>ةٍ‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ كَانُو<rule class=slnt>اۡ</rule> يُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 21, 5, 410, 354, 164, 'false'
  );
  
  -- Ayah 56 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3465,
    'وَقَالَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ وَٱلۡإِیمَـٰنَ لَقَدۡ لَبِثۡتُمۡ فِی كِتَـٰبِ ٱللَّهِ إِلَىٰ یَوۡمِ ٱلۡبَعۡثِۖ فَهَـٰذَا یَوۡمُ ٱلۡبَعۡثِ وَلَـٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ',
    'وقال الذين اوتوا العلم والايمان لقد لبثتم في كتاب الله الى يوم البعث فهذا يوم البعث ولكنكم كنتم لا تعلمون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ وَ<rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نَ لَقَ<rule class=qalaqah>دۡ</rule> لَبِثۡتُمۡ فِى كِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡبَعۡثِ‌ۖ فَهَ<rule class=madda_normal>ـٰ</rule>ذَا يَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡبَعۡثِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َكُمۡ كُ<rule class=ikhafa>نت</rule>ُمۡ لَا تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 21, 5, 410, 354, 164, 'false'
  );
  
  -- Ayah 57 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3466,
    'فَیَوۡمَىِٕذࣲ لَّا یَنفَعُ ٱلَّذِینَ ظَلَمُوا۟ مَعۡذِرَتُهُمۡ وَلَا هُمۡ یُسۡتَعۡتَبُونَ',
    'فيومئذ لا ينفع الذين ظلموا معذرتهم ولا هم يستعتبون',
    'فَيَوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> مَعۡذِرَتُهُمۡ وَلَا هُمۡ يُسۡتَعۡتَب<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 21, 5, 410, 354, 164, 'false'
  );
  
  -- Ayah 58 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3467,
    'وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِی هَـٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲۚ وَلَىِٕن جِئۡتَهُم بِـَٔایَةࣲ لَّیَقُولَنَّ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ أَنتُمۡ إِلَّا مُبۡطِلُونَ',
    'ولقد ضربنا للناس في هذا القران من كل مثل ولئن جئتهم باية ليقولن الذين كفروا ان انتم الا مبطلون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ضَرَ<rule class=qalaqah>بۡ</rule>نَا لِل<rule class=ghunnah>نّ</rule>َاسِ فِى هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مَثَ<rule class=idgham_ghunnah>لٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>ِئۡتَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيَقُولَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ أَ<rule class=ikhafa>نت</rule>ُمۡ إِلَّا مُ<rule class=qalaqah>بۡ</rule>طِل<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 21, 5, 410, 354, 164, 'false'
  );
  
  -- Ayah 59 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3468,
    'كَذَ ٰ⁠لِكَ یَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِینَ لَا یَعۡلَمُونَ',
    'كذلك يطبع الله على قلوب الذين لا يعلمون',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَ<rule class=qalaqah>طۡ</rule>بَعُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ قُلُوبِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 21, 5, 410, 354, 164, 'false'
  );
  
  -- Ayah 60 Surah Ar-Room
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    30,
    3469,
    'فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ وَلَا یَسۡتَخِفَّنَّكَ ٱلَّذِینَ لَا یُوقِنُونَ',
    'فاصبر ان وعد الله حق ولا يستخفنك الذين لا يوقنون',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ إِ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=idgham_ghunnah>قٌّ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَسۡتَخِفَّ<rule class=ghunnah>نّ</rule>َكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُوقِن<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 21, 5, 410, 354, 164, 'false'
  );
  

-- Surah Luqman
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (31, 'سُورَةُ لُقۡمَانَ', 'Luqman', 'Luqman', 'Meccan', 34);

  -- Ayah 1 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3470,
    'الۤمۤ',
    'الم',
    'ا<rule class=madda_necessary>لٓ</rule><rule class=madda_necessary>مٓ</rule> ١',
    1, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 2 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3471,
    'تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡحَكِیمِ',
    'تلك ايات الكتاب الحكيم',
    'تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ٢',
    2, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 3 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3472,
    'هُدࣰى وَرَحۡمَةࣰ لِّلۡمُحۡسِنِینَ',
    'هدى ورحمة للمحسنين',
    'هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٣',
    3, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 4 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3473,
    'ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ',
    'الذين يقيمون الصلاة ويؤتون الزكاة وهم بالاخرة هم يوقنون',
    'ٱلَّذِينَ يُقِيمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَيُؤۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمۡ يُوقِن<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 5 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3474,
    'أُو۟لَـٰۤىِٕكَ عَلَىٰ هُدࣰى مِّن رَّبِّهِمۡۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'اولئك على هدى من ربهم واولئك هم المفلحون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ عَلَىٰ هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 6 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3475,
    'وَمِنَ ٱلنَّاسِ مَن یَشۡتَرِی لَهۡوَ ٱلۡحَدِیثِ لِیُضِلَّ عَن سَبِیلِ ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَیَتَّخِذَهَا هُزُوًاۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مُّهِینࣱ',
    'ومن الناس من يشتري لهو الحديث ليضل عن سبيل الله بغير علم ويتخذها هزوا اولئك لهم عذاب مهين',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َشۡتَرِى لَهۡوَ <rule class=ham_wasl>ٱ</rule>لۡحَدِيثِ لِيُضِلَّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِغَيۡرِ عِلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َيَتَّخِذَهَا هُزُوًا‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّه<rule class=madda_permissible>ِي</rule>نٌ ٦',
    6, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 7 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3476,
    'وَإِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا وَلَّىٰ مُسۡتَكۡبِرࣰا كَأَن لَّمۡ یَسۡمَعۡهَا كَأَنَّ فِیۤ أُذُنَیۡهِ وَقۡرࣰاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِیمٍ',
    'واذا تتلى عليه اياتنا ولى مستكبرا كان لم يسمعها كان في اذنيه وقرا فبشره بعذاب اليم',
    'وَإِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا وَلَّىٰ مُسۡتَكۡبِ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَسۡمَعۡهَا كَأَ<rule class=ghunnah>نّ</rule>َ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُذُنَيۡهِ وَ<rule class=qalaqah>قۡ</rule><rule class=ikhafa>رًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َبَشِّرۡهُ بِعَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٧',
    7, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 8 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3477,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمۡ جَنَّـٰتُ ٱلنَّعِیمِ',
    'ان الذين امنوا وعملوا الصالحات لهم جنات النعيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َع<rule class=madda_permissible>ِي</rule>مِ ٨',
    8, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 9 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3478,
    'خَـٰلِدِینَ فِیهَاۖ وَعۡدَ ٱللَّهِ حَقࣰّاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'خالدين فيها وعد الله حقا وهو العزيز الحكيم',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۖ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَق<rule class=idgham_ghunnah>ًّا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٩',
    9, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 10 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3479,
    'خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ بِغَیۡرِ عَمَدࣲ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِی ٱلۡأَرۡضِ رَوَ ٰ⁠سِیَ أَن تَمِیدَ بِكُمۡ وَبَثَّ فِیهَا مِن كُلِّ دَاۤبَّةࣲۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَنۢبَتۡنَا فِیهَا مِن كُلِّ زَوۡجࣲ كَرِیمٍ',
    'خلق السماوات بغير عمد ترونها والقى في الارض رواسي ان تميد بكم وبث فيها من كل دابة وانزلنا من السماء ماء فانبتنا فيها من كل زوج كريم',
    'خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ بِغَيۡرِ عَمَ<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ت</rule>َرَوۡنَهَا‌ۖ وَأَلۡقَىٰ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ رَو<rule class=madda_normal>ٰ</rule>سِىَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمِيدَ بِكُمۡ وَبَثَّ فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ د<rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_ghunnah>ةٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نز</rule>َلۡنَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=iqlab>نۢب</rule>َتۡنَا فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ زَوۡ<rule class=ikhafa>جٍ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٍ ١٠',
    10, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 11 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3480,
    'هَـٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِی مَاذَا خَلَقَ ٱلَّذِینَ مِن دُونِهِۦۚ بَلِ ٱلظَّـٰلِمُونَ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'هذا خلق الله فاروني ماذا خلق الذين من دونه بل الظالمون في ضلال مبين',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا خَلۡقُ <rule class=ham_wasl>ٱ</rule>للَّهِ فَأَرُونِى مَاذَا خَلَقَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule>‌ۚ بَلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١١',
    11, 21, 5, 411, 355, 164, 'false'
  );
  
  -- Ayah 12 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3481,
    'وَلَقَدۡ ءَاتَیۡنَا لُقۡمَـٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن یَشۡكُرۡ فَإِنَّمَا یَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِیٌّ حَمِیدࣱ',
    'ولقد اتينا لقمان الحكمة ان اشكر لله ومن يشكر فانما يشكر لنفسه ومن كفر فان الله غني حميد',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا لُ<rule class=qalaqah>قۡ</rule>مَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ أَنِ <rule class=ham_wasl>ٱ</rule>شۡكُرۡ لِلَّهِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َشۡكُرۡ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَشۡكُرُ لِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَنِىٌّ حَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٢',
    12, 21, 5, 412, 356, 164, 'false'
  );
  
  -- Ayah 13 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3482,
    'وَإِذۡ قَالَ لُقۡمَـٰنُ لِٱبۡنِهِۦ وَهُوَ یَعِظُهُۥ یَـٰبُنَیَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِیمࣱ',
    'واذ قال لقمان لابنه وهو يعظه يا بني لا تشرك بالله ان الشرك لظلم عظيم',
    'وَإِذۡ قَالَ لُ<rule class=qalaqah>قۡ</rule>مَ<rule class=madda_normal>ـٰ</rule>نُ لِ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِه<rule class=madda_normal>ِۦ</rule> وَهُوَ يَعِظُهُ<rule class=madda_normal>ۥ</rule> يَ<rule class=madda_normal>ـٰ</rule>بُنَىَّ لَا تُشۡرِكۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شِّرۡكَ لَظُلۡمٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٣',
    13, 21, 5, 412, 356, 164, 'false'
  );
  
  -- Ayah 14 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3483,
    'وَوَصَّیۡنَا ٱلۡإِنسَـٰنَ بِوَ ٰ⁠لِدَیۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنࣲ وَفِصَـٰلُهُۥ فِی عَامَیۡنِ أَنِ ٱشۡكُرۡ لِی وَلِوَ ٰ⁠لِدَیۡكَ إِلَیَّ ٱلۡمَصِیرُ',
    'ووصينا الانسان بوالديه حملته امه وهنا على وهن وفصاله في عامين ان اشكر لي ولوالديك الي المصير',
    'وَوَصَّيۡنَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ بِو<rule class=madda_normal>ٰ</rule>لِدَيۡهِ حَمَلَتۡهُ أُ<rule class=ghunnah>مّ</rule>ُهُ<rule class=madda_normal>ۥ</rule> وَهۡنًا عَلَىٰ وَهۡ<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َفِصَ<rule class=madda_normal>ـٰ</rule>لُهُ<rule class=madda_normal>ۥ</rule> فِى عَامَيۡنِ أَنِ <rule class=ham_wasl>ٱ</rule>شۡكُرۡ لِى وَلِو<rule class=madda_normal>ٰ</rule>لِدَيۡكَ إِلَىَّ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٤',
    14, 21, 5, 412, 356, 164, 'false'
  );
  
  -- Ayah 15 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3484,
    'وَإِن جَـٰهَدَاكَ عَلَىٰۤ أَن تُشۡرِكَ بِی مَا لَیۡسَ لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِی ٱلدُّنۡیَا مَعۡرُوفࣰاۖ وَٱتَّبِعۡ سَبِیلَ مَنۡ أَنَابَ إِلَیَّۚ ثُمَّ إِلَیَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'وان جاهداك على ان تشرك بي ما ليس لك به علم فلا تطعهما وصاحبهما في الدنيا معروفا واتبع سبيل من اناب الي ثم الي مرجعكم فانبئكم بما كنتم تعملون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َ<rule class=madda_normal>ـٰ</rule>هَدَاكَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُشۡرِكَ بِى مَا لَيۡسَ لَكَ بِه<rule class=madda_normal>ِۦ</rule> عِلۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ف</rule>َلَا تُطِعۡهُمَا‌ۖ وَصَاحِ<rule class=qalaqah>بۡ</rule>هُمَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا مَعۡرُو<rule class=idgham_ghunnah>فًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَىَّ‌ۚ ثُ<rule class=ghunnah>مّ</rule>َ إِلَىَّ مَرۡجِعُكُمۡ فَأُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 21, 5, 412, 356, 164, 'false'
  );
  
  -- Ayah 16 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3485,
    'یَـٰبُنَیَّ إِنَّهَاۤ إِن تَكُ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلࣲ فَتَكُن فِی صَخۡرَةٍ أَوۡ فِی ٱلسَّمَـٰوَ ٰ⁠تِ أَوۡ فِی ٱلۡأَرۡضِ یَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِیفٌ خَبِیرࣱ',
    'يا بني انها ان تك مثقال حبة من خردل فتكن في صخرة او في السماوات او في الارض يات بها الله ان الله لطيف خبير',
    'يَ<rule class=madda_normal>ـٰ</rule>بُنَىَّ إِ<rule class=ghunnah>نّ</rule>َه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكُ مِثۡقَالَ حَبَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ خَرۡدَ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َتَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى صَخۡرَةٍ أَوۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ أَوۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يَأۡتِ بِهَا <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَطِيفٌ خَب<rule class=madda_permissible>ِي</rule>رٌ ١٦',
    16, 21, 5, 412, 356, 164, 'false'
  );
  
  -- Ayah 17 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3486,
    'یَـٰبُنَیَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَاۤ أَصَابَكَۖ إِنَّ ذَ ٰ⁠لِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ',
    'يا بني اقم الصلاة وامر بالمعروف وانه عن المنكر واصبر على ما اصابك ان ذلك من عزم الامور',
    'يَ<rule class=madda_normal>ـٰ</rule>بُنَىَّ أَقِمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأۡمُرۡ بِ<rule class=ham_wasl>ٱ</rule>لۡمَعۡرُوفِ وَ<rule class=ham_wasl>ٱ</rule>نۡهَ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نك</rule>َرِ وَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ عَلَىٰ م<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَكَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ مِنۡ عَزۡمِ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رِ ١٧',
    17, 21, 5, 412, 356, 164, 'false'
  );
  
  -- Ayah 18 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3487,
    'وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِی ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا یُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورࣲ',
    'ولا تصعر خدك للناس ولا تمش في الارض مرحا ان الله لا يحب كل مختال فخور',
    'وَلَا تُصَعِّرۡ خَدَّكَ لِل<rule class=ghunnah>نّ</rule>َاسِ وَلَا تَمۡشِ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مَرَحًا‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يُحِبُّ كُلَّ مُخۡتَا<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َخ<rule class=madda_permissible>ُو</rule>رٍ ١٨',
    18, 21, 5, 412, 356, 164, 'false'
  );
  
  -- Ayah 19 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3488,
    'وَٱقۡصِدۡ فِی مَشۡیِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَ ٰ⁠تِ لَصَوۡتُ ٱلۡحَمِیرِ',
    'واقصد في مشيك واغضض من صوتك ان انكر الاصوات لصوت الحمير',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>صِ<rule class=qalaqah>دۡ</rule> فِى مَشۡيِكَ وَ<rule class=ham_wasl>ٱ</rule>غۡضُضۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َوۡتِكَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ أَ<rule class=ikhafa>نك</rule>َرَ <rule class=ham_wasl>ٱ</rule>لۡأَصۡو<rule class=madda_normal>ٰ</rule>تِ لَصَوۡتُ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule>رِ ١٩',
    19, 21, 5, 412, 356, 164, 'false'
  );
  
  -- Ayah 20 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3489,
    'أَلَمۡ تَرَوۡا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَیۡكُمۡ نِعَمَهُۥ ظَـٰهِرَةࣰ وَبَاطِنَةࣰۗ وَمِنَ ٱلنَّاسِ مَن یُجَـٰدِلُ فِی ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَلَا هُدࣰى وَلَا كِتَـٰبࣲ مُّنِیرࣲ',
    'الم تروا ان الله سخر لكم ما في السماوات وما في الارض واسبغ عليكم نعمه ظاهرة وباطنة ومن الناس من يجادل في الله بغير علم ولا هدى ولا كتاب منير',
    'أَلَمۡ تَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَخَّرَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُ<rule class=madda_normal>ۥ</rule> ظَ<rule class=madda_normal>ـٰ</rule>هِرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َبَاطِنَ<rule class=idgham_ghunnah>ةً‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجَ<rule class=madda_normal>ـٰ</rule>دِلُ فِى <rule class=ham_wasl>ٱ</rule>للَّهِ بِغَيۡرِ عِلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َلَا كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّن<rule class=madda_permissible>ِي</rule>رٍ ٢٠',
    20, 21, 5, 413, 357, 164, 'false'
  );
  
  -- Ayah 21 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3490,
    'وَإِذَا قِیلَ لَهُمُ ٱتَّبِعُوا۟ مَاۤ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَیۡهِ ءَابَاۤءَنَاۤۚ أَوَلَوۡ كَانَ ٱلشَّیۡطَـٰنُ یَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِیرِ',
    'واذا قيل لهم اتبعوا ما انزل الله قالوا بل نتبع ما وجدنا عليه اباءنا اولو كان الشيطان يدعوهم الى عذاب السعير',
    'وَإِذَا قِيلَ لَهُمُ <rule class=ham_wasl>ٱ</rule>تَّبِعُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ قَالُو<rule class=slnt>اۡ</rule> بَلۡ نَتَّبِعُ مَا وَجَ<rule class=qalaqah>دۡ</rule>نَا عَلَيۡهِ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أَوَلَوۡ كَانَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ يَ<rule class=qalaqah>دۡ</rule>عُوهُمۡ إِلَىٰ عَذَابِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّع<rule class=madda_permissible>ِي</rule>رِ ٢١',
    21, 21, 5, 413, 357, 164, 'false'
  );
  
  -- Ayah 22 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3491,
    '۞ وَمَن یُسۡلِمۡ وَجۡهَهُۥۤ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنࣱ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَـٰقِبَةُ ٱلۡأُمُورِ',
    'ومن يسلم وجهه الى الله وهو محسن فقد استمسك بالعروة الوثقى والى الله عاقبة الامور',
    '۞وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُسۡلِمۡ وَ<rule class=qalaqah>جۡ</rule>هَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَهُوَ مُحۡسِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َقَدِ <rule class=ham_wasl>ٱ</rule>سۡتَمۡسَكَ بِ<rule class=ham_wasl>ٱ</rule>لۡعُرۡوَةِ <rule class=ham_wasl>ٱ</rule>لۡوُثۡقَىٰ‌ۗ وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رِ ٢٢',
    22, 21, 5, 413, 357, 165, 'false'
  );
  
  -- Ayah 23 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3492,
    'وَمَن كَفَرَ فَلَا یَحۡزُنكَ كُفۡرُهُۥۤۚ إِلَیۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوۤا۟ۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'ومن كفر فلا يحزنك كفره الينا مرجعهم فننبئهم بما عملوا ان الله عليم بذات الصدور',
    'وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ فَلَا يَحۡزُ<rule class=ikhafa>نك</rule>َ كُفۡرُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِلَيۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا عَمِل<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٢٣',
    23, 21, 5, 413, 357, 165, 'false'
  );
  
  -- Ayah 24 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3493,
    'نُمَتِّعُهُمۡ قَلِیلࣰا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِیظࣲ',
    'نمتعهم قليلا ثم نضطرهم الى عذاب غليظ',
    'نُمَتِّعُهُمۡ قَلِيل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَل<rule class=madda_permissible>ِي</rule>ظٍ ٢٤',
    24, 21, 5, 413, 357, 165, 'false'
  );
  
  -- Ayah 25 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3494,
    'وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ لَیَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ',
    'ولئن سالتهم من خلق السماوات والارض ليقولن الله قل الحمد لله بل اكثرهم لا يعلمون',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َأَلۡتَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ لَيَقُولُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ قُلِ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ‌ۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 21, 5, 413, 357, 165, 'false'
  );
  
  -- Ayah 26 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3495,
    'لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ',
    'لله ما في السماوات والارض ان الله هو الغني الحميد',
    'لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَنِىُّ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٢٦',
    26, 21, 5, 413, 357, 165, 'false'
  );
  
  -- Ayah 27 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3496,
    'وَلَوۡ أَنَّمَا فِی ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَـٰمࣱ وَٱلۡبَحۡرُ یَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرࣲ مَّا نَفِدَتۡ كَلِمَـٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ',
    'ولو انما في الارض من شجرة اقلام والبحر يمده من بعده سبعة ابحر ما نفدت كلمات الله ان الله عزيز حكيم',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َجَرَةٍ أَ<rule class=qalaqah>قۡ</rule>لَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرُ يَمُدُّهُ<rule class=madda_normal>ۥ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> سَ<rule class=qalaqah>بۡ</rule>عَةُ أَ<rule class=qalaqah>بۡ</rule>حُ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا نَفِدَتۡ كَلِمَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِيزٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٢٧',
    27, 21, 5, 413, 357, 165, 'false'
  );
  
  -- Ayah 28 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3497,
    'مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسࣲ وَ ٰ⁠حِدَةٍۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرٌ',
    'ما خلقكم ولا بعثكم الا كنفس واحدة ان الله سميع بصير',
    'مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَةٍ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِي<rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>َص<rule class=madda_permissible>ِي</rule>رٌ ٢٨',
    28, 21, 5, 413, 357, 165, 'false'
  );
  
  -- Ayah 29 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3498,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِیۤ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِیرࣱ',
    'الم تر ان الله يولج الليل في النهار ويولج النهار في الليل وسخر الشمس والقمر كل يجري الى اجل مسمى وان الله بما تعملون خبير',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُولِجُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَيُولِجُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ فِى <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَسَخَّرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>ر<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=idgham_ghunnah>ًّى</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِمَا تَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ٢٩',
    29, 21, 5, 414, 357, 165, 'false'
  );
  
  -- Ayah 30 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3499,
    'ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا یَدۡعُونَ مِن دُونِهِ ٱلۡبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ',
    'ذلك بان الله هو الحق وان ما يدعون من دونه الباطل وان الله هو العلي الكبير',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَأَ<rule class=ghunnah>نّ</rule>َ مَا يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِهِ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلُ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِىُّ <rule class=ham_wasl>ٱ</rule>لۡكَب<rule class=madda_permissible>ِي</rule>رُ ٣٠',
    30, 21, 5, 414, 357, 165, 'false'
  );
  
  -- Ayah 31 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3500,
    'أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِی فِی ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِیُرِیَكُم مِّنۡ ءَایَـٰتِهِۦۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ',
    'الم تر ان الفلك تجري في البحر بنعمت الله ليريكم من اياته ان في ذلك لايات لكل صبار شكور',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ تَ<rule class=qalaqah>جۡ</rule>رِى فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ بِنِعۡمَتِ <rule class=ham_wasl>ٱ</rule>للَّهِ لِيُرِيَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ صَبَّا<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ش</rule>َك<rule class=madda_permissible>ُو</rule>رٍ ٣١',
    31, 21, 5, 414, 357, 165, 'false'
  );
  
  -- Ayah 32 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3501,
    'وَإِذَا غَشِیَهُم مَّوۡجࣱ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدࣱۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا كُلُّ خَتَّارࣲ كَفُورࣲ',
    'واذا غشيهم موج كالظلل دعوا الله مخلصين له الدين فلما نجاهم الى البر فمنهم مقتصد وما يجحد باياتنا الا كل ختار كفور',
    'وَإِذَا غَشِيَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوۡ<rule class=ikhafa>جٌ</rule> <rule class=ikhafa>ك</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلَلِ دَعَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡلِصِينَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ فَلَ<rule class=ghunnah>مّ</rule>َا نَجَّ<rule class=madda_normal>ـٰ</rule>هُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡبَرِّ فَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَصِ<rule class=idgham_ghunnah>دٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا يَ<rule class=qalaqah>جۡ</rule>حَدُ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا كُلُّ خَتَّا<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ك</rule>َف<rule class=madda_permissible>ُو</rule>رٍ ٣٢',
    32, 21, 5, 414, 357, 165, 'false'
  );
  
  -- Ayah 33 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3502,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمۡ وَٱخۡشَوۡا۟ یَوۡمࣰا لَّا یَجۡزِی وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَیۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَلَا یَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ',
    'يا ايها الناس اتقوا ربكم واخشوا يوما لا يجزي والد عن ولده ولا مولود هو جاز عن والده شيئا ان وعد الله حق فلا تغرنكم الحياة الدنيا ولا يغرنكم بالله الغرور',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ وَ<rule class=ham_wasl>ٱ</rule>خۡشَوۡ<rule class=slnt>اۡ</rule> يَوۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَ<rule class=qalaqah>جۡ</rule>زِى وَالِدٌ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>و</rule>َلَدِه<rule class=madda_normal>ِۦ</rule> وَلَا مَوۡلُودٌ هُوَ جَازٍ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>و</rule>َالِدِه<rule class=madda_normal>ِۦ</rule> شَيۡــًٔا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=ikhafa>قٌّ‌ۖ</rule> <rule class=ikhafa>ف</rule>َلَا تَغُرَّ<rule class=ghunnah>نّ</rule>َكُمُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَلَا يَغُرَّ<rule class=ghunnah>نّ</rule>َك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡغَر<rule class=madda_permissible>ُو</rule>رُ ٣٣',
    33, 21, 5, 414, 357, 165, 'false'
  );
  
  -- Ayah 34 Surah Luqman
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    31,
    3503,
    'إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَیُنَزِّلُ ٱلۡغَیۡثَ وَیَعۡلَمُ مَا فِی ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِی نَفۡسࣱ مَّاذَا تَكۡسِبُ غَدࣰاۖ وَمَا تَدۡرِی نَفۡسُۢ بِأَیِّ أَرۡضࣲ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِیمٌ خَبِیرُۢ',
    'ان الله عنده علم الساعة وينزل الغيث ويعلم ما في الارحام وما تدري نفس ماذا تكسب غدا وما تدري نفس باي ارض تموت ان الله عليم خبير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> عِلۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ وَيُنَزِّلُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡثَ وَيَعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡحَامِ‌ۖ وَمَا تَ<rule class=qalaqah>دۡ</rule>رِى نَفۡ<rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>م</rule>َّاذَا تَكۡسِبُ غَ<rule class=idgham_ghunnah>دًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا تَ<rule class=qalaqah>دۡ</rule>رِى نَفۡ<rule class=iqlab>سُۢ</rule> <rule class=iqlab>ب</rule>ِأَىِّ أَرۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ت</rule>َمُوتُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِيمٌ خَب<rule class=madda_permissible>ِي</rule>رُۢ ٣٤',
    34, 21, 5, 414, 357, 165, 'false'
  );
  

-- Surah As-Sajda
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (32, 'سُورَةُ السَّجۡدَةِ', 'As-Sajda', 'The Prostration', 'Meccan', 30);

  -- Ayah 1 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3504,
    'الۤمۤ',
    'الم',
    'ا<rule class=madda_necessary>لٓ</rule><rule class=madda_necessary>مٓ</rule> ١',
    1, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 2 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3505,
    'تَنزِیلُ ٱلۡكِتَـٰبِ لَا رَیۡبَ فِیهِ مِن رَّبِّ ٱلۡعَـٰلَمِینَ',
    'تنزيل الكتاب لا ريب فيه من رب العالمين',
    'تَ<rule class=ikhafa>نز</rule>ِيلُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَا رَيۡبَ فِيهِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 3 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3506,
    'أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمࣰا مَّاۤ أَتَىٰهُم مِّن نَّذِیرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ یَهۡتَدُونَ',
    'ام يقولون افتراه بل هو الحق من ربك لتنذر قوما ما اتاهم من نذير من قبلك لعلهم يهتدون',
    'أَمۡ يَقُولُونَ <rule class=ham_wasl>ٱ</rule>فۡتَرَ&gt;ٮٰهُ‌ۚ بَلۡ هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ لِتُ<rule class=ikhafa>نذ</rule>ِرَ قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَتَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّذِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ لَعَلَّهُمۡ يَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 4 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3507,
    'ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِیࣲّ وَلَا شَفِیعٍۚ أَفَلَا تَتَذَكَّرُونَ',
    'الله الذي خلق السماوات والارض وما بينهما في ستة ايام ثم استوى على العرش ما لكم من دونه من ولي ولا شفيع افلا تتذكرون',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُمَا فِى سِتَّةِ أَيَّا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ‌ۖ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا شَفِيعٍ‌ۚ أَفَلَا تَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 5 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3508,
    'یُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَاۤءِ إِلَى ٱلۡأَرۡضِ ثُمَّ یَعۡرُجُ إِلَیۡهِ فِی یَوۡمࣲ كَانَ مِقۡدَارُهُۥۤ أَلۡفَ سَنَةࣲ مِّمَّا تَعُدُّونَ',
    'يدبر الامر من السماء الى الارض ثم يعرج اليه في يوم كان مقداره الف سنة مما تعدون',
    'يُدَبِّرُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ ثُ<rule class=ghunnah>مّ</rule>َ يَعۡرُجُ إِلَيۡهِ فِى يَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ك</rule>َانَ مِ<rule class=qalaqah>قۡ</rule>دَارُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَلۡفَ سَنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَعُدّ<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 6 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3509,
    'ذَ ٰ⁠لِكَ عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡعَزِیزُ ٱلرَّحِیمُ',
    'ذلك عالم الغيب والشهادة العزيز الرحيم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ عَ<rule class=madda_normal>ـٰ</rule>لِمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٦',
    6, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 7 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3510,
    'ٱلَّذِیۤ أَحۡسَنَ كُلَّ شَیۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَـٰنِ مِن طِینࣲ',
    'الذي احسن كل شيء خلقه وبدا خلق الانسان من طين',
    'ٱلَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡسَنَ كُلَّ شَىۡءٍ خَلَقَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَبَدَأَ خَلۡقَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule><rule class=madda_permissible>ِي</rule>نٍ ٧',
    7, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 8 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3511,
    'ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَـٰلَةࣲ مِّن مَّاۤءࣲ مَّهِینࣲ',
    'ثم جعل نسله من سلالة من ماء مهين',
    'ثُ<rule class=ghunnah>مّ</rule>َ جَعَلَ نَسۡلَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٍ</rule> <rule class=idgham_ghunnah>م</rule>َّه<rule class=madda_permissible>ِي</rule>نٍ ٨',
    8, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 9 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3512,
    'ثُمَّ سَوَّىٰهُ وَنَفَخَ فِیهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ',
    'ثم سواه ونفخ فيه من روحه وجعل لكم السمع والابصار والافئدة قليلا ما تشكرون',
    'ثُ<rule class=ghunnah>مّ</rule>َ سَوَّ<rule class=madda_normal>ٮٰ</rule>هُ وَنَفَخَ فِيهِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّوحِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَجَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَفۡــِٔدَةَ‌ۚ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 10 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3513,
    'وَقَالُوۤا۟ أَءِذَا ضَلَلۡنَا فِی ٱلۡأَرۡضِ أَءِنَّا لَفِی خَلۡقࣲ جَدِیدِۭۚ بَلۡ هُم بِلِقَاۤءِ رَبِّهِمۡ كَـٰفِرُونَ',
    'وقالوا ااذا ضللنا في الارض اانا لفي خلق جديد بل هم بلقاء ربهم كافرون',
    'وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَءِذَا ضَلَلۡنَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَءِ<rule class=ghunnah>نّ</rule>َا لَفِى خَلۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ج</rule>َدِي<rule class=iqlab>دِۭ‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِلِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رَبِّهِمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 21, 5, 415, 358, 165, 'false'
  );
  
  -- Ayah 11 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3514,
    '۞ قُلۡ یَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِی وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ',
    'قل يتوفاكم ملك الموت الذي وكل بكم ثم الى ربكم ترجعون',
    '۞قُلۡ يَتَوَفَّ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّلَكُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ <rule class=ham_wasl>ٱ</rule>لَّذِى وُكِّلَ بِكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ إِلَىٰ رَبِّكُمۡ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 21, 5, 415, 358, 166, 'false'
  );
  
  -- Ayah 12 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3515,
    'وَلَوۡ تَرَىٰۤ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُوا۟ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَاۤ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَـٰلِحًا إِنَّا مُوقِنُونَ',
    'ولو ترى اذ المجرمون ناكسو رءوسهم عند ربهم ربنا ابصرنا وسمعنا فارجعنا نعمل صالحا انا موقنون',
    'وَلَوۡ تَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمُونَ نَاكِسُو<rule class=slnt>اۡ</rule> رُءُوسِهِمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>صَرۡنَا وَسَمِعۡنَا فَ<rule class=ham_wasl>ٱ</rule>رۡجِعۡنَا نَعۡمَلۡ صَ<rule class=madda_normal>ـٰ</rule>لِحًا إِ<rule class=ghunnah>نّ</rule>َا مُوقِن<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 21, 5, 416, 359, 166, 'false'
  );
  
  -- Ayah 13 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3516,
    'وَلَوۡ شِئۡنَا لَـَٔاتَیۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَـٰكِنۡ حَقَّ ٱلۡقَوۡلُ مِنِّی لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِینَ',
    'ولو شئنا لاتينا كل نفس هداها ولكن حق القول مني لاملان جهنم من الجنة والناس اجمعين',
    'وَلَوۡ شِئۡنَا لَأَتَيۡنَا كُلَّ نَفۡسٍ هُدَ<rule class=madda_normal>ٮٰ</rule>هَا وَلَ<rule class=madda_normal>ـٰ</rule>كِنۡ حَقَّ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ مِ<rule class=ghunnah>نّ</rule>ِى لَأَمۡلَأَ<rule class=ghunnah>نّ</rule>َ جَهَ<rule class=ghunnah>نّ</rule>َمَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>َةِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 21, 5, 416, 359, 166, 'false'
  );
  
  -- Ayah 14 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3517,
    'فَذُوقُوا۟ بِمَا نَسِیتُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَاۤ إِنَّا نَسِینَـٰكُمۡۖ وَذُوقُوا۟ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'فذوقوا بما نسيتم لقاء يومكم هذا انا نسيناكم وذوقوا عذاب الخلد بما كنتم تعملون',
    'فَذُوقُو<rule class=slnt>اۡ</rule> بِمَا نَسِيتُمۡ لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ يَوۡمِكُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا نَسِينَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ وَذُوقُو<rule class=slnt>اۡ</rule> عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡخُلۡدِ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 21, 5, 416, 359, 166, 'false'
  );
  
  -- Ayah 15 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3518,
    'إِنَّمَا یُؤۡمِنُ بِـَٔایَـٰتِنَا ٱلَّذِینَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدࣰا وَسَبَّحُوا۟ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا یَسۡتَكۡبِرُونَ ۩',
    'انما يؤمن باياتنا الذين اذا ذكروا بها خروا سجدا وسبحوا بحمد ربهم وهم لا يستكبرون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا يُؤۡمِنُ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ إِذَا ذُكِّرُو<rule class=slnt>اۡ</rule> بِهَا خَرُّو<rule class=slnt>اۡ</rule> سُجَّ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َسَبَّحُو<rule class=slnt>اۡ</rule> بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُ<rule class=madda_permissible>و</rule>نَ ۩ ١٥',
    15, 21, 5, 416, 359, 166, '{"id":10,"recommended":false,"obligatory":true}'
  );
  
  -- Ayah 16 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3519,
    'تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ یَدۡعُونَ رَبَّهُمۡ خَوۡفࣰا وَطَمَعࣰا وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ',
    'تتجافى جنوبهم عن المضاجع يدعون ربهم خوفا وطمعا ومما رزقناهم ينفقون',
    'تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمَضَاجِعِ يَ<rule class=qalaqah>دۡ</rule>عُونَ رَبَّهُمۡ خَوۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َطَمَ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َمِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ يُ<rule class=ikhafa>نف</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 21, 5, 416, 359, 166, 'false'
  );
  
  -- Ayah 17 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3520,
    'فَلَا تَعۡلَمُ نَفۡسࣱ مَّاۤ أُخۡفِیَ لَهُم مِّن قُرَّةِ أَعۡیُنࣲ جَزَاۤءَۢ بِمَا كَانُوا۟ یَعۡمَلُونَ',
    'فلا تعلم نفس ما اخفي لهم من قرة اعين جزاء بما كانوا يعملون',
    'فَلَا تَعۡلَمُ نَفۡ<rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أُخۡفِىَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُرَّةِ أَعۡيُ<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ج</rule>َز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءَۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 21, 5, 416, 359, 166, 'false'
  );
  
  -- Ayah 18 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3521,
    'أَفَمَن كَانَ مُؤۡمِنࣰا كَمَن كَانَ فَاسِقࣰاۚ لَّا یَسۡتَوُۥنَ',
    'افمن كان مؤمنا كمن كان فاسقا لا يستوون',
    'أَفَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مُؤۡمِ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ك</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ فَاسِ<rule class=idgham_wo_ghunnah>قًا‌ۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَسۡتَوُ<rule class=madda_permissible>ۥ</rule>نَ ١٨',
    18, 21, 5, 416, 359, 166, 'false'
  );
  
  -- Ayah 19 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3522,
    'أَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمۡ جَنَّـٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُوا۟ یَعۡمَلُونَ',
    'اما الذين امنوا وعملوا الصالحات فلهم جنات الماوى نزلا بما كانوا يعملون',
    'أَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فَلَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡمَأۡوَىٰ نُزُل<rule class=iqlab>اَۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 21, 5, 416, 359, 166, 'false'
  );
  
  -- Ayah 20 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3523,
    'وَأَمَّا ٱلَّذِینَ فَسَقُوا۟ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَاۤ أَرَادُوۤا۟ أَن یَخۡرُجُوا۟ مِنۡهَاۤ أُعِیدُوا۟ فِیهَا وَقِیلَ لَهُمۡ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِی كُنتُم بِهِۦ تُكَذِّبُونَ',
    'واما الذين فسقوا فماواهم النار كلما ارادوا ان يخرجوا منها اعيدوا فيها وقيل لهم ذوقوا عذاب النار الذي كنتم به تكذبون',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ فَسَقُو<rule class=slnt>اۡ</rule> فَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ‌ۖ كُلَّم<rule class=madda_obligatory_monfasel>َآ</rule> أَرَاد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡرُجُو<rule class=slnt>اۡ</rule> مِنۡه<rule class=madda_obligatory_monfasel>َآ</rule> أُعِيدُو<rule class=slnt>اۡ</rule> فِيهَا وَقِيلَ لَهُمۡ ذُوقُو<rule class=slnt>اۡ</rule> عَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ <rule class=ham_wasl>ٱ</rule>لَّذِى كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> تُكَذِّب<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 21, 5, 416, 359, 166, 'false'
  );
  
  -- Ayah 21 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3524,
    'وَلَنُذِیقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ لَعَلَّهُمۡ یَرۡجِعُونَ',
    'ولنذيقنهم من العذاب الادنى دون العذاب الاكبر لعلهم يرجعون',
    'وَلَنُذِيقَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>دۡ</rule>نَىٰ دُونَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ <rule class=ham_wasl>ٱ</rule>لۡأَكۡبَرِ لَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 21, 5, 417, 359, 166, 'false'
  );
  
  -- Ayah 22 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3525,
    'وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔایَـٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَاۤۚ إِنَّا مِنَ ٱلۡمُجۡرِمِینَ مُنتَقِمُونَ',
    'ومن اظلم ممن ذكر بايات ربه ثم اعرض عنها انا من المجرمين منتقمون',
    'وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُكِّرَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّه<rule class=madda_normal>ِۦ</rule> ثُ<rule class=ghunnah>مّ</rule>َ أَعۡرَضَ عَنۡه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َا مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ مُ<rule class=ikhafa>نت</rule>َقِم<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 21, 5, 417, 359, 166, 'false'
  );
  
  -- Ayah 23 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3526,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ فَلَا تَكُن فِی مِرۡیَةࣲ مِّن لِّقَاۤىِٕهِۦۖ وَجَعَلۡنَـٰهُ هُدࣰى لِّبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ',
    'ولقد اتينا موسى الكتاب فلا تكن في مرية من لقائه وجعلناه هدى لبني اسرائيل',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ فَلَا تَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى مِرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِه<rule class=madda_normal>ِۦ‌ۖ</rule> وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ هُ<rule class=idgham_wo_ghunnah>دًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّبَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓء<rule class=madda_permissible>ِي</rule>لَ ٢٣',
    23, 21, 5, 417, 360, 166, 'false'
  );
  
  -- Ayah 24 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3527,
    'وَجَعَلۡنَا مِنۡهُمۡ أَىِٕمَّةࣰ یَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُوا۟ۖ وَكَانُوا۟ بِـَٔایَـٰتِنَا یُوقِنُونَ',
    'وجعلنا منهم ائمة يهدون بامرنا لما صبروا وكانوا باياتنا يوقنون',
    'وَجَعَلۡنَا مِنۡهُمۡ أَئِ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدُونَ بِأَمۡرِنَا لَ<rule class=ghunnah>مّ</rule>َا صَبَرُو<rule class=slnt>اۡ‌ۖ</rule> وَكَانُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا يُوقِن<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 21, 5, 417, 360, 166, 'false'
  );
  
  -- Ayah 25 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3528,
    'إِنَّ رَبَّكَ هُوَ یَفۡصِلُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ',
    'ان ربك هو يفصل بينهم يوم القيامة فيما كانوا فيه يختلفون',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فِيمَا كَانُو<rule class=slnt>اۡ</rule> فِيهِ يَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 21, 5, 417, 360, 166, 'false'
  );
  
  -- Ayah 26 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3529,
    'أَوَلَمۡ یَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ یَمۡشُونَ فِی مَسَـٰكِنِهِمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتٍۚ أَفَلَا یَسۡمَعُونَ',
    'اولم يهد لهم كم اهلكنا من قبلهم من القرون يمشون في مساكنهم ان في ذلك لايات افلا يسمعون',
    'أَوَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقُرُونِ يَمۡشُونَ فِى مَسَ<rule class=madda_normal>ـٰ</rule>كِنِهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule>تٍ‌ۖ أَفَلَا يَسۡمَع<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 21, 5, 417, 360, 166, 'false'
  );
  
  -- Ayah 27 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3530,
    'أَوَلَمۡ یَرَوۡا۟ أَنَّا نَسُوقُ ٱلۡمَاۤءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ زَرۡعࣰا تَأۡكُلُ مِنۡهُ أَنۡعَـٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا یُبۡصِرُونَ',
    'اولم يروا انا نسوق الماء الى الارض الجرز فنخرج به زرعا تاكل منه انعامهم وانفسهم افلا يبصرون',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َا نَسُوقُ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ <rule class=ham_wasl>ٱ</rule>لۡجُرُزِ فَنُخۡرِجُ بِه<rule class=madda_normal>ِۦ</rule> زَرۡ<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ت</rule>َأۡكُلُ مِنۡهُ أَنۡعَ<rule class=madda_normal>ـٰ</rule>مُهُمۡ وَأَ<rule class=ikhafa>نف</rule>ُسُهُمۡ‌ۖ أَفَلَا يُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 21, 5, 417, 360, 166, 'false'
  );
  
  -- Ayah 28 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3531,
    'وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ويقولون متى هذا الفتح ان كنتم صادقين',
    'وَيَقُولُونَ مَتَىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡفَتۡحُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٢٨',
    28, 21, 5, 417, 360, 166, 'false'
  );
  
  -- Ayah 29 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3532,
    'قُلۡ یَوۡمَ ٱلۡفَتۡحِ لَا یَنفَعُ ٱلَّذِینَ كَفَرُوۤا۟ إِیمَـٰنُهُمۡ وَلَا هُمۡ یُنظَرُونَ',
    'قل يوم الفتح لا ينفع الذين كفروا ايمانهم ولا هم ينظرون',
    'قُلۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡفَتۡحِ لَا يَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِيمَ<rule class=madda_normal>ـٰ</rule>نُهُمۡ وَلَا هُمۡ يُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 21, 5, 417, 360, 166, 'false'
  );
  
  -- Ayah 30 Surah As-Sajda
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    32,
    3533,
    'فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ',
    'فاعرض عنهم وانتظر انهم منتظرون',
    'فَأَعۡرِضۡ عَنۡهُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َظِرۡ إِ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=ikhafa>نت</rule>َظِر<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 21, 5, 417, 360, 166, 'false'
  );
  

-- Surah Al-Ahzaab
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (33, 'سُورَةُ الأَحۡزَابِ', 'Al-Ahzaab', 'The Clans', 'Medinan', 73);

  -- Ayah 1 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3534,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ ٱتَّقِ ٱللَّهۚ وَلَا تُطِعِ ٱلۡكَـٰفِرِینَ وَٱلۡمُنَـٰفِقِینَۗ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا',
    'يا ايها النبي اتق الله ولا تطع الكافرين والمنافقين ان الله كان عليما حكيما',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ <rule class=ham_wasl>ٱ</rule>تَّقِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَلَا تُطِعِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلِيمًا حَكِيمًا ١',
    1, 21, 5, 418, 361, 167, 'false'
  );
  
  -- Ayah 2 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3535,
    'وَٱتَّبِعۡ مَا یُوحَىٰۤ إِلَیۡكَ مِن رَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا',
    'واتبع ما يوحى اليك من ربك ان الله كان بما تعملون خبيرا',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّبِعۡ مَا يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَيۡكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرًا ٢',
    2, 21, 5, 418, 361, 167, 'false'
  );
  
  -- Ayah 3 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3536,
    'وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلࣰا',
    'وتوكل على الله وكفى بالله وكيلا',
    'وَتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَكِيلاً ٣',
    3, 21, 5, 418, 361, 167, 'false'
  );
  
  -- Ayah 4 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3537,
    'مَّا جَعَلَ ٱللَّهُ لِرَجُلࣲ مِّن قَلۡبَیۡنِ فِی جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَ ٰ⁠جَكُمُ ٱلَّـٰۤـِٔی تُظَـٰهِرُونَ مِنۡهُنَّ أُمَّهَـٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِیَاۤءَكُمۡ أَبۡنَاۤءَكُمۡۚ ذَ ٰ⁠لِكُمۡ قَوۡلُكُم بِأَفۡوَ ٰ⁠هِكُمۡۖ وَٱللَّهُ یَقُولُ ٱلۡحَقَّ وَهُوَ یَهۡدِی ٱلسَّبِیلَ',
    'ما جعل الله لرجل من قلبين في جوفه وما جعل ازواجكم اللائي تظاهرون منهن امهاتكم وما جعل ادعياءكم ابناءكم ذلكم قولكم بافواهكم والله يقول الحق وهو يهدي السبيل',
    'مَّا جَعَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِرَجُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َلۡبَيۡنِ فِى جَوۡفِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَمَا جَعَلَ أَزۡو<rule class=madda_normal>ٰ</rule>جَكُمُ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_obligatory_mottasel>ــٰٓ</rule>ــِٔى تُظَ<rule class=madda_normal>ـٰ</rule>هِرُونَ مِنۡهُ<rule class=ghunnah>نّ</rule>َ أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ‌ۚ وَمَا جَعَلَ أَ<rule class=qalaqah>دۡ</rule>عِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ قَوۡلُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَفۡو<rule class=madda_normal>ٰ</rule>هِكُمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَقُولُ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَهُوَ يَهۡدِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لَ ٤',
    4, 21, 5, 418, 361, 167, 'false'
  );
  
  -- Ayah 5 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3538,
    'ٱدۡعُوهُمۡ لِـَٔابَاۤىِٕهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوۤا۟ ءَابَاۤءَهُمۡ فَإِخۡوَ ٰ⁠نُكُمۡ فِی ٱلدِّینِ وَمَوَ ٰ⁠لِیكُمۡۚ وَلَیۡسَ عَلَیۡكُمۡ جُنَاحࣱ فِیمَاۤ أَخۡطَأۡتُم بِهِۦ وَلَـٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمًا',
    'ادعوهم لابائهم هو اقسط عند الله فان لم تعلموا اباءهم فاخوانكم في الدين ومواليكم وليس عليكم جناح فيما اخطاتم به ولكن ما تعمدت قلوبكم وكان الله غفورا رحيما',
    'ٱ<rule class=qalaqah>دۡ</rule>عُوهُمۡ لِأَب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ هُوَ أَ<rule class=qalaqah>قۡ</rule>سَطُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ فَإِخۡو<rule class=madda_normal>ٰ</rule>نُكُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ وَمَو<rule class=madda_normal>ٰ</rule>لِيكُمۡ‌ۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَا<rule class=ikhafa>حٌ</rule> <rule class=ikhafa>ف</rule>ِيم<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡطَأۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّا تَعَ<rule class=ghunnah>مّ</rule>َدَتۡ قُلُوبُكُمۡ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٥',
    5, 21, 5, 418, 361, 167, 'false'
  );
  
  -- Ayah 6 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3539,
    'ٱلنَّبِیُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِینَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَ ٰ⁠جُهُۥۤ أُمَّهَـٰتُهُمۡۗ وَأُو۟لُوا۟ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضࣲ فِی كِتَـٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِینَ وَٱلۡمُهَـٰجِرِینَ إِلَّاۤ أَن تَفۡعَلُوۤا۟ إِلَىٰۤ أَوۡلِیَاۤىِٕكُم مَّعۡرُوفࣰاۚ كَانَ ذَ ٰ⁠لِكَ فِی ٱلۡكِتَـٰبِ مَسۡطُورࣰا',
    'النبي اولى بالمؤمنين من انفسهم وازواجه امهاتهم واولو الارحام بعضهم اولى ببعض في كتاب الله من المؤمنين والمهاجرين الا ان تفعلوا الى اوليائكم معروفا كان ذلك في الكتاب مسطورا',
    'ٱ<rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ أَوۡلَىٰ بِ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ مِنۡ أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ‌ۖ وَأَزۡو<rule class=madda_normal>ٰ</rule>جُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تُهُمۡ‌ۗ وَأُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ف</rule>ِى كِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>للَّهِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُهَ<rule class=madda_normal>ـٰ</rule>جِرِينَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َفۡعَل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓئِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّعۡرُو<rule class=ikhafa>فًا‌ۚ</rule> <rule class=ikhafa>ك</rule>َانَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فِى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مَسۡطُورًا ٦',
    6, 21, 5, 418, 361, 167, 'false'
  );
  
  -- Ayah 7 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3540,
    'وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِیِّـۧنَ مِیثَـٰقَهُمۡ وَمِنكَ وَمِن نُّوحࣲ وَإِبۡرَ ٰ⁠هِیمَ وَمُوسَىٰ وَعِیسَى ٱبۡنِ مَرۡیَمَۖ وَأَخَذۡنَا مِنۡهُم مِّیثَـٰقًا غَلِیظࣰا',
    'واذ اخذنا من النبيين ميثاقهم ومنك ومن نوح وابراهيم وموسى وعيسى ابن مريم واخذنا منهم ميثاقا غليظا',
    'وَإِذۡ أَخَذۡنَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ مِيثَ<rule class=madda_normal>ـٰ</rule>قَهُمۡ وَمِ<rule class=ikhafa>نك</rule>َ وَم<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَمُوسَىٰ وَعِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ مَرۡيَمَ‌ۖ وَأَخَذۡنَا مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّيثَ<rule class=madda_normal>ـٰ</rule>قًا غَلِيظًا ٧',
    7, 21, 5, 419, 361, 167, 'false'
  );
  
  -- Ayah 8 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3541,
    'لِّیَسۡـَٔلَ ٱلصَّـٰدِقِینَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَـٰفِرِینَ عَذَابًا أَلِیمࣰا',
    'ليسال الصادقين عن صدقهم واعد للكافرين عذابا اليما',
    'لِّيَسۡــَٔلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِقِينَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>ِ<rule class=qalaqah>دۡ</rule>قِهِمۡ‌ۚ وَأَعَدَّ لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَابًا أَلِيمًا ٨',
    8, 21, 5, 419, 361, 167, 'false'
  );
  
  -- Ayah 9 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3542,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ جَاۤءَتۡكُمۡ جُنُودࣱ فَأَرۡسَلۡنَا عَلَیۡهِمۡ رِیحࣰا وَجُنُودࣰا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرًا',
    'يا ايها الذين امنوا اذكروا نعمة الله عليكم اذ جاءتكم جنود فارسلنا عليهم ريحا وجنودا لم تروها وكان الله بما تعملون بصيرا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَةَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡ إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡكُمۡ جُنُو<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َأَرۡسَلۡنَا عَلَيۡهِمۡ رِي<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َجُنُو<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَرَوۡهَا‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ٩',
    9, 21, 5, 419, 362, 167, 'false'
  );
  
  -- Ayah 10 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3543,
    'إِذۡ جَاۤءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَـٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠',
    'اذ جاءوكم من فوقكم ومن اسفل منكم واذ زاغت الابصار وبلغت القلوب الحناجر وتظنون بالله الظنونا',
    'إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِ<rule class=ikhafa>نك</rule>ُمۡ وَإِذۡ زَاغَتِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُ وَبَلَغَتِ <rule class=ham_wasl>ٱ</rule>لۡقُلُوبُ <rule class=ham_wasl>ٱ</rule>لۡحَنَاجِرَ وَتَظُ<rule class=ghunnah>نّ</rule>ُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّنُونَاۡ ١٠',
    10, 21, 5, 419, 362, 167, 'false'
  );
  
  -- Ayah 11 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3544,
    'هُنَالِكَ ٱبۡتُلِیَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُوا۟ زِلۡزَالࣰا شَدِیدࣰا',
    'هنالك ابتلي المؤمنون وزلزلوا زلزالا شديدا',
    'هُنَالِكَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تُلِىَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ وَزُلۡزِلُو<rule class=slnt>اۡ</rule> زِلۡزَال<rule class=ikhafa>اً</rule> <rule class=ikhafa>ش</rule>َدِيدًا ١١',
    11, 21, 5, 419, 362, 167, 'false'
  );
  
  -- Ayah 12 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3545,
    'وَإِذۡ یَقُولُ ٱلۡمُنَـٰفِقُونَ وَٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥۤ إِلَّا غُرُورࣰا',
    'واذ يقول المنافقون والذين في قلوبهم مرض ما وعدنا الله ورسوله الا غرورا',
    'وَإِذۡ يَقُولُ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقُونَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا وَعَدَنَا <rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا غُرُورًا ١٢',
    12, 21, 5, 419, 362, 167, 'false'
  );
  
  -- Ayah 13 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3546,
    'وَإِذۡ قَالَت طَّاۤىِٕفَةࣱ مِّنۡهُمۡ یَـٰۤأَهۡلَ یَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُوا۟ۚ وَیَسۡتَـٔۡذِنُ فَرِیقࣱ مِّنۡهُمُ ٱلنَّبِیَّ یَقُولُونَ إِنَّ بُیُوتَنَا عَوۡرَةࣱ وَمَا هِیَ بِعَوۡرَةٍۖ إِن یُرِیدُونَ إِلَّا فِرَارࣰا',
    'واذ قالت طائفة منهم يا اهل يثرب لا مقام لكم فارجعوا ويستاذن فريق منهم النبي يقولون ان بيوتنا عورة وما هي بعورة ان يريدون الا فرارا',
    'وَإِذۡ قَالَ<rule class=idgham_mutajanisayn>ت</rule> طّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَ<rule class=ham_wasl>ٱ</rule>رۡجِعُو<rule class=slnt>اۡ‌ۚ</rule> وَيَسۡتَــٔۡذِنُ فَرِي<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىَّ يَقُولُونَ إِ<rule class=ghunnah>نّ</rule>َ بُيُوتَنَا عَوۡرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَا هِىَ بِعَوۡرَةٍ‌ۖ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيدُونَ إِلَّا فِرَارًا ١٣',
    13, 21, 5, 419, 362, 167, 'false'
  );
  
  -- Ayah 14 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3547,
    'وَلَوۡ دُخِلَتۡ عَلَیۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُىِٕلُوا۟ ٱلۡفِتۡنَةَ لَـَٔاتَوۡهَا وَمَا تَلَبَّثُوا۟ بِهَاۤ إِلَّا یَسِیرࣰا',
    'ولو دخلت عليهم من اقطارها ثم سئلوا الفتنة لاتوها وما تلبثوا بها الا يسيرا',
    'وَلَوۡ دُخِلَتۡ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَ<rule class=qalaqah>قۡ</rule>طَارِهَا ثُ<rule class=ghunnah>مّ</rule>َ سُئِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡفِتۡنَةَ لَأَتَوۡهَا وَمَا تَلَبَّثُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا يَسِيرًا ١٤',
    14, 21, 5, 419, 362, 167, 'false'
  );
  
  -- Ayah 15 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3548,
    'وَلَقَدۡ كَانُوا۟ عَـٰهَدُوا۟ ٱللَّهَ مِن قَبۡلُ لَا یُوَلُّونَ ٱلۡأَدۡبَـٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولࣰا',
    'ولقد كانوا عاهدوا الله من قبل لا يولون الادبار وكان عهد الله مسئولا',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> كَانُو<rule class=slnt>اۡ</rule> عَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ لَا يُوَلُّونَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رَ‌ۚ وَكَانَ عَهۡدُ <rule class=ham_wasl>ٱ</rule>للَّهِ مَسۡــُٔولاً ١٥',
    15, 21, 5, 419, 362, 167, 'false'
  );
  
  -- Ayah 16 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3549,
    'قُل لَّن یَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذࣰا لَّا تُمَتَّعُونَ إِلَّا قَلِیلࣰا',
    'قل لن ينفعكم الفرار ان فررتم من الموت او القتل واذا لا تمتعون الا قليلا',
    'قُل لّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نف</rule>َعَكُمُ <rule class=ham_wasl>ٱ</rule>لۡفِرَارُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َرَرۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ أَوِ <rule class=ham_wasl>ٱ</rule>لۡقَتۡلِ وَإِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تُمَتَّعُونَ إِلَّا قَلِيلاً ١٦',
    16, 21, 5, 420, 362, 167, 'false'
  );
  
  -- Ayah 17 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3550,
    'قُلۡ مَن ذَا ٱلَّذِی یَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوۤءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةࣰۚ وَلَا یَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِیࣰّا وَلَا نَصِیرࣰا',
    'قل من ذا الذي يعصمكم من الله ان اراد بكم سوءا او اراد بكم رحمة ولا يجدون لهم من دون الله وليا ولا نصيرا',
    'قُلۡ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِى يَعۡصِمُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِنۡ أَرَادَ بِكُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَجِدُونَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصِيرًا ١٧',
    17, 21, 5, 420, 362, 167, 'false'
  );
  
  -- Ayah 18 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3551,
    '۞ قَدۡ یَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِینَ مِنكُمۡ وَٱلۡقَاۤىِٕلِینَ لِإِخۡوَ ٰ⁠نِهِمۡ هَلُمَّ إِلَیۡنَاۖ وَلَا یَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِیلًا',
    'قد يعلم الله المعوقين منكم والقائلين لاخوانهم هلم الينا ولا ياتون الباس الا قليلا',
    '۞قَ<rule class=qalaqah>دۡ</rule> يَعۡلَمُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُعَوِّقِينَ مِ<rule class=ikhafa>نك</rule>ُمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِلِينَ لِإِخۡو<rule class=madda_normal>ٰ</rule>نِهِمۡ هَلُ<rule class=ghunnah>مّ</rule>َ إِلَيۡنَا‌ۖ وَلَا يَأۡتُونَ <rule class=ham_wasl>ٱ</rule>لۡبَأۡسَ إِلَّا قَلِيلاً ١٨',
    18, 21, 5, 420, 362, 168, 'false'
  );
  
  -- Ayah 19 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3552,
    'أَشِحَّةً عَلَیۡكُمۡۖ فَإِذَا جَاۤءَ ٱلۡخَوۡفُ رَأَیۡتَهُمۡ یَنظُرُونَ إِلَیۡكَ تَدُورُ أَعۡیُنُهُمۡ كَٱلَّذِی یُغۡشَىٰ عَلَیۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَیۡرِۚ أُو۟لَـٰۤىِٕكَ لَمۡ یُؤۡمِنُوا۟ فَأَحۡبَطَ ٱللَّهُ أَعۡمَـٰلَهُمۡۚ وَكَانَ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣰا',
    'اشحة عليكم فاذا جاء الخوف رايتهم ينظرون اليك تدور اعينهم كالذي يغشى عليه من الموت فاذا ذهب الخوف سلقوكم بالسنة حداد اشحة على الخير اولئك لم يؤمنوا فاحبط الله اعمالهم وكان ذلك على الله يسيرا',
    'أَشِحَّةً عَلَيۡكُمۡ‌ۖ فَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡخَوۡفُ رَأَيۡتَهُمۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَ<rule class=ham_wasl>ٱ</rule>لَّذِى يُغۡشَىٰ عَلَيۡهِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ‌ۖ فَإِذَا ذَهَبَ <rule class=ham_wasl>ٱ</rule>لۡخَوۡفُ سَلَقُوك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى <rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَمۡ يُؤۡمِنُو<rule class=slnt>اۡ</rule> فَأَحۡبَطَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ‌ۚ وَكَانَ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَسِيرًا ١٩',
    19, 21, 5, 420, 362, 168, 'false'
  );
  
  -- Ayah 20 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3553,
    'یَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ یَذۡهَبُوا۟ۖ وَإِن یَأۡتِ ٱلۡأَحۡزَابُ یَوَدُّوا۟ لَوۡ أَنَّهُم بَادُونَ فِی ٱلۡأَعۡرَابِ یَسۡـَٔلُونَ عَنۡ أَنۢبَاۤىِٕكُمۡۖ وَلَوۡ كَانُوا۟ فِیكُم مَّا قَـٰتَلُوۤا۟ إِلَّا قَلِیلࣰا',
    'يحسبون الاحزاب لم يذهبوا وان يات الاحزاب يودوا لو انهم بادون في الاعراب يسالون عن انبائكم ولو كانوا فيكم ما قاتلوا الا قليلا',
    'يَحۡسَبُونَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡزَابَ لَمۡ يَذۡهَبُو<rule class=slnt>اۡ‌ۖ</rule> وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِ <rule class=ham_wasl>ٱ</rule>لۡأَحۡزَابُ يَوَدُّو<rule class=slnt>اۡ</rule> لَوۡ أَ<rule class=ghunnah>نّ</rule>َه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َادُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابِ يَسۡــَٔلُونَ عَنۡ أَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ‌ۖ وَلَوۡ كَانُو<rule class=slnt>اۡ</rule> فِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا قَ<rule class=madda_normal>ـٰ</rule>تَل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا قَلِيلاً ٢٠',
    20, 21, 5, 420, 362, 168, 'false'
  );
  
  -- Ayah 21 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3554,
    'لَّقَدۡ كَانَ لَكُمۡ فِی رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةࣱ لِّمَن كَانَ یَرۡجُوا۟ ٱللَّهَ وَٱلۡیَوۡمَ ٱلۡـَٔاخِرَ وَذَكَرَ ٱللَّهَ كَثِیرࣰا',
    'لقد كان لكم في رسول الله اسوة حسنة لمن كان يرجو الله واليوم الاخر وذكر الله كثيرا',
    'لَّقَ<rule class=qalaqah>دۡ</rule> كَانَ لَكُمۡ فِى رَسُولِ <rule class=ham_wasl>ٱ</rule>للَّهِ أُسۡوَةٌ حَسَنَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يَرۡجُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَ وَذَكَرَ <rule class=ham_wasl>ٱ</rule>للَّهَ كَثِيرًا ٢١',
    21, 21, 5, 420, 363, 168, 'false'
  );
  
  -- Ayah 22 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3555,
    'وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُوا۟ هَـٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّاۤ إِیمَـٰنࣰا وَتَسۡلِیمࣰا',
    'ولما راى المؤمنون الاحزاب قالوا هذا ما وعدنا الله ورسوله وصدق الله ورسوله وما زادهم الا ايمانا وتسليما',
    'وَلَ<rule class=ghunnah>مّ</rule>َا رَءَا <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡزَابَ قَالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا مَا وَعَدَنَا <rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule> وَصَدَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَمَا زَادَهُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِيمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َتَسۡلِيمًا ٢٢',
    22, 21, 5, 420, 363, 168, 'false'
  );
  
  -- Ayah 23 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3556,
    'مِّنَ ٱلۡمُؤۡمِنِینَ رِجَالࣱ صَدَقُوا۟ مَا عَـٰهَدُوا۟ ٱللَّهَ عَلَیۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن یَنتَظِرُۖ وَمَا بَدَّلُوا۟ تَبۡدِیلࣰا',
    'من المؤمنين رجال صدقوا ما عاهدوا الله عليه فمنهم من قضى نحبه ومنهم من ينتظر وما بدلوا تبديلا',
    'مِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ رِجَا<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ص</rule>َدَقُو<rule class=slnt>اۡ</rule> مَا عَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَيۡهِ‌ۖ فَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َضَىٰ نَحۡبَهُ<rule class=madda_normal>ۥ</rule> وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نت</rule>َظِرُ‌ۖ وَمَا بَدَّلُو<rule class=slnt>اۡ</rule> تَ<rule class=qalaqah>بۡ</rule>دِيلاً ٢٣',
    23, 21, 5, 421, 363, 168, 'false'
  );
  
  -- Ayah 24 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3557,
    'لِّیَجۡزِیَ ٱللَّهُ ٱلصَّـٰدِقِینَ بِصِدۡقِهِمۡ وَیُعَذِّبَ ٱلۡمُنَـٰفِقِینَ إِن شَاۤءَ أَوۡ یَتُوبَ عَلَیۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا',
    'ليجزي الله الصادقين بصدقهم ويعذب المنافقين ان شاء او يتوب عليهم ان الله كان غفورا رحيما',
    'لِّيَ<rule class=qalaqah>جۡ</rule>زِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِقِينَ بِصِ<rule class=qalaqah>دۡ</rule>قِهِمۡ وَيُعَذِّبَ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَوۡ يَتُوبَ عَلَيۡهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٢٤',
    24, 21, 5, 421, 363, 168, 'false'
  );
  
  -- Ayah 25 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3558,
    'وَرَدَّ ٱللَّهُ ٱلَّذِینَ كَفَرُوا۟ بِغَیۡظِهِمۡ لَمۡ یَنَالُوا۟ خَیۡرࣰاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِینَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِیًّا عَزِیزࣰا',
    'ورد الله الذين كفروا بغيظهم لم ينالوا خيرا وكفى الله المؤمنين القتال وكان الله قويا عزيزا',
    'وَرَدَّ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِغَيۡظِهِمۡ لَمۡ يَنَالُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَفَى <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ <rule class=ham_wasl>ٱ</rule>لۡقِتَالَ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ قَوِيًّا عَزِيزًا ٢٥',
    25, 21, 5, 421, 363, 168, 'false'
  );
  
  -- Ayah 26 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3559,
    'وَأَنزَلَ ٱلَّذِینَ ظَـٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ مِن صَیَاصِیهِمۡ وَقَذَفَ فِی قُلُوبِهِمُ ٱلرُّعۡبَ فَرِیقࣰا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِیقࣰا',
    'وانزل الذين ظاهروهم من اهل الكتاب من صياصيهم وقذف في قلوبهم الرعب فريقا تقتلون وتاسرون فريقا',
    'وَأَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَ<rule class=madda_normal>ـٰ</rule>هَرُوه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َيَاصِيهِمۡ وَقَذَفَ فِى قُلُوبِهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّعۡبَ فَرِي<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>قۡ</rule>تُلُونَ وَتَأۡسِرُونَ فَرِيقًا ٢٦',
    26, 21, 5, 421, 363, 168, 'false'
  );
  
  -- Ayah 27 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3560,
    'وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِیَـٰرَهُمۡ وَأَمۡوَ ٰ⁠لَهُمۡ وَأَرۡضࣰا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣰا',
    'واورثكم ارضهم وديارهم واموالهم وارضا لم تطئوها وكان الله على كل شيء قديرا',
    'وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَ<rule class=madda_normal>ـٰ</rule>رَهُمۡ وَأَمۡو<rule class=madda_normal>ٰ</rule>لَهُمۡ وَأَرۡ<rule class=idgham_wo_ghunnah>ضًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَطَــُٔوهَا‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َدِيرًا ٢٧',
    27, 21, 5, 421, 363, 168, 'false'
  );
  
  -- Ayah 28 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3561,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ قُل لِّأَزۡوَ ٰ⁠جِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا وَزِینَتَهَا فَتَعَالَیۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحࣰا جَمِیلࣰا',
    'يا ايها النبي قل لازواجك ان كنتن تردن الحياة الدنيا وزينتها فتعالين امتعكن واسرحكن سراحا جميلا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ قُل لِّأَزۡو<rule class=madda_normal>ٰ</rule>جِكَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُ<rule class=ghunnah>نّ</rule>َ تُرِ<rule class=qalaqah>دۡ</rule>نَ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُ<rule class=ghunnah>نّ</rule>َ وَأُسَرِّحۡكُ<rule class=ghunnah>نّ</rule>َ سَرَا<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ج</rule>َمِيلاً ٢٨',
    28, 21, 5, 421, 364, 168, 'false'
  );
  
  -- Ayah 29 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3562,
    'وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡـَٔاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَـٰتِ مِنكُنَّ أَجۡرًا عَظِیمࣰا',
    'وان كنتن تردن الله ورسوله والدار الاخرة فان الله اعد للمحسنات منكن اجرا عظيما',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُ<rule class=ghunnah>نّ</rule>َ تُرِ<rule class=qalaqah>دۡ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ أَعَدَّ لِلۡمُحۡسِنَ<rule class=madda_normal>ـٰ</rule>تِ مِ<rule class=ikhafa>نك</rule>ُ<rule class=ghunnah>نّ</rule>َ أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ٢٩',
    29, 21, 5, 421, 364, 168, 'false'
  );
  
  -- Ayah 30 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3563,
    'یَـٰنِسَاۤءَ ٱلنَّبِیِّ مَن یَأۡتِ مِنكُنَّ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲ یُضَـٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَیۡنِۚ وَكَانَ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣰا',
    'يا نساء النبي من يات منكن بفاحشة مبينة يضاعف لها العذاب ضعفين وكان ذلك على الله يسيرا',
    'يَ<rule class=madda_normal>ـٰ</rule>نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِ مِ<rule class=ikhafa>نك</rule>ُ<rule class=ghunnah>نّ</rule>َ بِفَ<rule class=madda_normal>ـٰ</rule>حِشَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّبَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُضَ<rule class=madda_normal>ـٰ</rule>عَفۡ لَهَا <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ ضِعۡفَيۡنِ‌ۚ وَكَانَ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَسِيرًا ٣٠',
    30, 21, 5, 421, 364, 168, 'false'
  );
  
  -- Ayah 31 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3564,
    '۞ وَمَن یَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَـٰلِحࣰا نُّؤۡتِهَاۤ أَجۡرَهَا مَرَّتَیۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقࣰا كَرِیمࣰا',
    'ومن يقنت منكن لله ورسوله وتعمل صالحا نؤتها اجرها مرتين واعتدنا لها رزقا كريما',
    '۞وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>نُتۡ مِ<rule class=ikhafa>نك</rule>ُ<rule class=ghunnah>نّ</rule>َ لِلَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَتَعۡمَلۡ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>ن</rule>ُّؤۡتِه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>جۡ</rule>رَهَا مَرَّتَيۡنِ وَأَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لَهَا رِزۡ<rule class=ikhafa>قًا</rule> <rule class=ikhafa>ك</rule>َرِيمًا ٣١',
    31, 22, 5, 422, 364, 169, 'false'
  );
  
  -- Ayah 32 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3565,
    'یَـٰنِسَاۤءَ ٱلنَّبِیِّ لَسۡتُنَّ كَأَحَدࣲ مِّنَ ٱلنِّسَاۤءِ إِنِ ٱتَّقَیۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَیَطۡمَعَ ٱلَّذِی فِی قَلۡبِهِۦ مَرَضࣱ وَقُلۡنَ قَوۡلࣰا مَّعۡرُوفࣰا',
    'يا نساء النبي لستن كاحد من النساء ان اتقيتن فلا تخضعن بالقول فيطمع الذي في قلبه مرض وقلن قولا معروفا',
    'يَ<rule class=madda_normal>ـٰ</rule>نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّ لَسۡتُ<rule class=ghunnah>نّ</rule>َ كَأَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِۚ إِنِ <rule class=ham_wasl>ٱ</rule>تَّقَيۡتُ<rule class=ghunnah>نّ</rule>َ فَلَا تَخۡضَعۡنَ بِ<rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ فَيَ<rule class=qalaqah>طۡ</rule>مَعَ <rule class=ham_wasl>ٱ</rule>لَّذِى فِى قَلۡبِه<rule class=madda_normal>ِۦ</rule> مَرَ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>و</rule>َقُلۡنَ قَوۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُوفًا ٣٢',
    32, 22, 5, 422, 364, 169, 'false'
  );
  
  -- Ayah 33 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3566,
    'وَقَرۡنَ فِی بُیُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَـٰهِلِیَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِینَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥۤۚ إِنَّمَا یُرِیدُ ٱللَّهُ لِیُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَیۡتِ وَیُطَهِّرَكُمۡ تَطۡهِیرࣰا',
    'وقرن في بيوتكن ولا تبرجن تبرج الجاهلية الاولى واقمن الصلاة واتين الزكاة واطعن الله ورسوله انما يريد الله ليذهب عنكم الرجس اهل البيت ويطهركم تطهيرا',
    'وَقَرۡنَ فِى بُيُوتِكُ<rule class=ghunnah>نّ</rule>َ وَلَا تَبَرَّ<rule class=qalaqah>جۡ</rule>نَ تَبَرُّجَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِلِيَّةِ <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰۖ وَأَقِمۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتِينَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَطِعۡنَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُۚ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا يُرِيدُ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيُذۡهِبَ عَ<rule class=ikhafa>نك</rule>ُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّ<rule class=qalaqah>جۡ</rule>سَ أَهۡلَ <rule class=ham_wasl>ٱ</rule>لۡبَيۡتِ وَيُطَهِّرَكُمۡ تَ<rule class=qalaqah>طۡ</rule>هِيرًا ٣٣',
    33, 22, 5, 422, 364, 169, 'false'
  );
  
  -- Ayah 34 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3567,
    'وَٱذۡكُرۡنَ مَا یُتۡلَىٰ فِی بُیُوتِكُنَّ مِنۡ ءَایَـٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِیفًا خَبِیرًا',
    'واذكرن ما يتلى في بيوتكن من ايات الله والحكمة ان الله كان لطيفا خبيرا',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡنَ مَا يُتۡلَىٰ فِى بُيُوتِكُ<rule class=ghunnah>نّ</rule>َ مِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةِۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ لَطِيفًا خَبِيرًا ٣٤',
    34, 22, 5, 422, 364, 169, 'false'
  );
  
  -- Ayah 35 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3568,
    'إِنَّ ٱلۡمُسۡلِمِینَ وَٱلۡمُسۡلِمَـٰتِ وَٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ وَٱلۡقَـٰنِتِینَ وَٱلۡقَـٰنِتَـٰتِ وَٱلصَّـٰدِقِینَ وَٱلصَّـٰدِقَـٰتِ وَٱلصَّـٰبِرِینَ وَٱلصَّـٰبِرَ ٰ⁠تِ وَٱلۡخَـٰشِعِینَ وَٱلۡخَـٰشِعَـٰتِ وَٱلۡمُتَصَدِّقِینَ وَٱلۡمُتَصَدِّقَـٰتِ وَٱلصَّـٰۤىِٕمِینَ وَٱلصَّـٰۤىِٕمَـٰتِ وَٱلۡحَـٰفِظِینَ فُرُوجَهُمۡ وَٱلۡحَـٰفِظَـٰتِ وَٱلذَّ ٰ⁠كِرِینَ ٱللَّهَ كَثِیرࣰا وَٱلذَّ ٰ⁠كِرَ ٰ⁠تِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةࣰ وَأَجۡرًا عَظِیمࣰا',
    'ان المسلمين والمسلمات والمؤمنين والمؤمنات والقانتين والقانتات والصادقين والصادقات والصابرين والصابرات والخاشعين والخاشعات والمتصدقين والمتصدقات والصائمين والصائمات والحافظين فروجهم والحافظات والذاكرين الله كثيرا والذاكرات اعد الله لهم مغفرة واجرا عظيما',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِمِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُسۡلِمَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>نِتِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>نِتَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِقِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِقَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِرِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِر<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>شِعِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>شِعَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُتَصَدِّقِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُتَصَدِّقَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِمِينَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِمَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>فِظِينَ فُرُوجَهُمۡ وَ<rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>فِظَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذّ<rule class=madda_normal>ٰ</rule>كِرِينَ <rule class=ham_wasl>ٱ</rule>للَّهَ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذّ<rule class=madda_normal>ٰ</rule>كِر<rule class=madda_normal>ٰ</rule>تِ أَعَدَّ <rule class=ham_wasl>ٱ</rule>للَّهُ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ٣٥',
    35, 22, 5, 422, 365, 169, 'false'
  );
  
  -- Ayah 36 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3569,
    'وَمَا كَانَ لِمُؤۡمِنࣲ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥۤ أَمۡرًا أَن یَكُونَ لَهُمُ ٱلۡخِیَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن یَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَـٰلࣰا مُّبِینࣰا',
    'وما كان لمؤمن ولا مؤمنة اذا قضى الله ورسوله امرا ان يكون لهم الخيرة من امرهم ومن يعص الله ورسوله فقد ضل ضلالا مبينا',
    'وَمَا كَانَ لِمُؤۡمِ<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا مُؤۡمِنَةٍ إِذَا قَضَى <rule class=ham_wasl>ٱ</rule>للَّهُ وَرَسُولُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَمۡرًا أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡصِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> فَقَ<rule class=qalaqah>دۡ</rule> ضَلَّ ضَلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ٣٦',
    36, 22, 5, 423, 365, 169, 'false'
  );
  
  -- Ayah 37 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3570,
    'وَإِذۡ تَقُولُ لِلَّذِیۤ أَنۡعَمَ ٱللَّهُ عَلَیۡهِ وَأَنۡعَمۡتَ عَلَیۡهِ أَمۡسِكۡ عَلَیۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِی فِی نَفۡسِكَ مَا ٱللَّهُ مُبۡدِیهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَیۡدࣱ مِّنۡهَا وَطَرࣰا زَوَّجۡنَـٰكَهَا لِكَیۡ لَا یَكُونَ عَلَى ٱلۡمُؤۡمِنِینَ حَرَجࣱ فِیۤ أَزۡوَ ٰ⁠جِ أَدۡعِیَاۤىِٕهِمۡ إِذَا قَضَوۡا۟ مِنۡهُنَّ وَطَرࣰاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولࣰا',
    'واذ تقول للذي انعم الله عليه وانعمت عليه امسك عليك زوجك واتق الله وتخفي في نفسك ما الله مبديه وتخشى الناس والله احق ان تخشاه فلما قضى زيد منها وطرا زوجناكها لكي لا يكون على المؤمنين حرج في ازواج ادعيائهم اذا قضوا منهن وطرا وكان امر الله مفعولا',
    'وَإِذۡ تَقُولُ لِلَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡعَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَ<rule class=ham_wasl>ٱ</rule>تَّقِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَتُخۡفِى فِى نَفۡسِكَ مَا <rule class=ham_wasl>ٱ</rule>للَّهُ مُ<rule class=qalaqah>بۡ</rule>دِيهِ وَتَخۡشَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَحَقُّ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َخۡشَ<rule class=madda_normal>ـٰ</rule>هُۖ فَلَ<rule class=ghunnah>مّ</rule>َا قَضَىٰ زَيۡ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا وَطَ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ز</rule>َوَّ<rule class=qalaqah>جۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كَهَا لِكَىۡ لَا يَكُونَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ حَرَ<rule class=ikhafa>جٌ</rule> <rule class=ikhafa>ف</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule>جِ أَ<rule class=qalaqah>دۡ</rule>عِي<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ إِذَا قَضَوۡ<rule class=slnt>اۡ</rule> مِنۡهُ<rule class=ghunnah>نّ</rule>َ وَطَ<rule class=idgham_ghunnah>رًاۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ أَمۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ مَفۡعُولاً ٣٧',
    37, 22, 5, 423, 365, 169, 'false'
  );
  
  -- Ayah 38 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3571,
    'مَّا كَانَ عَلَى ٱلنَّبِیِّ مِنۡ حَرَجࣲ فِیمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِی ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرࣰا مَّقۡدُورًا',
    'ما كان على النبي من حرج فيما فرض الله له سنة الله في الذين خلوا من قبل وكان امر الله قدرا مقدورا',
    'مَّا كَانَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّ مِنۡ حَرَ<rule class=ikhafa>جٍ</rule> <rule class=ikhafa>ف</rule>ِيمَا فَرَضَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُۖ<rule class=madda_normal>ۥ</rule> سُ<rule class=ghunnah>نّ</rule>َةَ <rule class=ham_wasl>ٱ</rule>للَّهِ فِى <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَلَوۡ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُۚ وَكَانَ أَمۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ قَدَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>قۡ</rule>دُورًا ٣٨',
    38, 22, 5, 423, 365, 169, 'false'
  );
  
  -- Ayah 39 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3572,
    'ٱلَّذِینَ یُبَلِّغُونَ رِسَـٰلَـٰتِ ٱللَّهِ وَیَخۡشَوۡنَهُۥ وَلَا یَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِیبࣰا',
    'الذين يبلغون رسالات الله ويخشونه ولا يخشون احدا الا الله وكفى بالله حسيبا',
    'ٱلَّذِينَ يُبَلِّغُونَ رِسَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَيَخۡشَوۡنَهُ<rule class=madda_normal>ۥ</rule> وَلَا يَخۡشَوۡنَ أَحَدًا إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَۗ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ حَسِيبًا ٣٩',
    39, 22, 5, 423, 365, 169, 'false'
  );
  
  -- Ayah 40 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3573,
    'مَّا كَانَ مُحَمَّدٌ أَبَاۤ أَحَدࣲ مِّن رِّجَالِكُمۡ وَلَـٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِیِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣰا',
    'ما كان محمد ابا احد من رجالكم ولكن رسول الله وخاتم النبيين وكان الله بكل شيء عليما',
    'مَّا كَانَ مُحَ<rule class=ghunnah>مّ</rule>َدٌ أَب<rule class=madda_obligatory_monfasel>َآ</rule> أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّجَالِكُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَخَاتَمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ شَىۡءٍ عَلِيمًا ٤٠',
    40, 22, 5, 423, 365, 169, 'false'
  );
  
  -- Ayah 41 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3574,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱذۡكُرُوا۟ ٱللَّهَ ذِكۡرࣰا كَثِیرࣰا',
    'يا ايها الذين امنوا اذكروا الله ذكرا كثيرا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ ذِكۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َثِيرًا ٤١',
    41, 22, 5, 423, 366, 169, 'false'
  );
  
  -- Ayah 42 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3575,
    'وَسَبِّحُوهُ بُكۡرَةࣰ وَأَصِیلًا',
    'وسبحوه بكرة واصيلا',
    'وَسَبِّحُوهُ بُكۡرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَصِيلاً ٤٢',
    42, 22, 5, 423, 366, 169, 'false'
  );
  
  -- Ayah 43 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3576,
    'هُوَ ٱلَّذِی یُصَلِّی عَلَیۡكُمۡ وَمَلَـٰۤىِٕكَتُهُۥ لِیُخۡرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِینَ رَحِیمࣰا',
    'هو الذي يصلي عليكم وملائكته ليخرجكم من الظلمات الى النور وكان بالمؤمنين رحيما',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُصَلِّى عَلَيۡكُمۡ وَمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَتُهُ<rule class=madda_normal>ۥ</rule> لِيُخۡرِجَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِۚ وَكَانَ بِ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ رَحِيمًا ٤٣',
    43, 22, 5, 423, 366, 169, 'false'
  );
  
  -- Ayah 44 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3577,
    'تَحِیَّتُهُمۡ یَوۡمَ یَلۡقَوۡنَهُۥ سَلَـٰمࣱۚ وَأَعَدَّ لَهُمۡ أَجۡرࣰا كَرِیمࣰا',
    'تحيتهم يوم يلقونه سلام واعد لهم اجرا كريما',
    'تَحِيَّتُهُمۡ يَوۡمَ يَلۡقَوۡنَهُ<rule class=madda_normal>ۥ</rule> سَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مٌۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَعَدَّ لَهُمۡ أَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َرِيمًا ٤٤',
    44, 22, 5, 424, 366, 169, 'false'
  );
  
  -- Ayah 45 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3578,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِنَّاۤ أَرۡسَلۡنَـٰكَ شَـٰهِدࣰا وَمُبَشِّرࣰا وَنَذِیرࣰا',
    'يا ايها النبي انا ارسلناك شاهدا ومبشرا ونذيرا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ شَ<rule class=madda_normal>ـٰ</rule>هِ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َمُبَشِّ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَذِيرًا ٤٥',
    45, 22, 5, 424, 366, 169, 'false'
  );
  
  -- Ayah 46 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3579,
    'وَدَاعِیًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجࣰا مُّنِیرࣰا',
    'وداعيا الى الله باذنه وسراجا منيرا',
    'وَدَاعِيًا إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ بِإِذۡنِه<rule class=madda_normal>ِۦ</rule> وَسِرَا<rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>م</rule>ُّنِيرًا ٤٦',
    46, 22, 5, 424, 366, 169, 'false'
  );
  
  -- Ayah 47 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3580,
    'وَبَشِّرِ ٱلۡمُؤۡمِنِینَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلࣰا كَبِیرࣰا',
    'وبشر المؤمنين بان لهم من الله فضلا كبيرا',
    'وَبَشِّرِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ بِأَ<rule class=ghunnah>نّ</rule>َ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَضۡل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٤٧',
    47, 22, 5, 424, 366, 169, 'false'
  );
  
  -- Ayah 48 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3581,
    'وَلَا تُطِعِ ٱلۡكَـٰفِرِینَ وَٱلۡمُنَـٰفِقِینَ وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلࣰا',
    'ولا تطع الكافرين والمنافقين ودع اذاهم وتوكل على الله وكفى بالله وكيلا',
    'وَلَا تُطِعِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ وَدَعۡ أَذَ<rule class=madda_normal>ٮٰ</rule>هُمۡ وَتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَكِيلاً ٤٨',
    48, 22, 5, 424, 366, 169, 'false'
  );
  
  -- Ayah 49 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3582,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَـٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَیۡهِنَّ مِنۡ عِدَّةࣲ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحࣰا جَمِیلࣰا',
    'يا ايها الذين امنوا اذا نكحتم المؤمنات ثم طلقتموهن من قبل ان تمسوهن فما لكم عليهن من عدة تعتدونها فمتعوهن وسرحوهن سراحا جميلا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا نَكَحۡتُمُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ ثُ<rule class=ghunnah>مّ</rule>َ طَلَّ<rule class=qalaqah>قۡ</rule>تُمُوهُ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َمَسُّوهُ<rule class=ghunnah>نّ</rule>َ فَمَا لَكُمۡ عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ مِنۡ عِدَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ت</rule>َعۡتَدُّونَهَاۖ فَمَتِّعُوهُ<rule class=ghunnah>نّ</rule>َ وَسَرِّحُوهُ<rule class=ghunnah>نّ</rule>َ سَرَا<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ج</rule>َمِيلاً ٤٩',
    49, 22, 5, 424, 366, 169, 'false'
  );
  
  -- Ayah 50 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3583,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِنَّاۤ أَحۡلَلۡنَا لَكَ أَزۡوَ ٰ⁠جَكَ ٱلَّـٰتِیۤ ءَاتَیۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ یَمِینُكَ مِمَّاۤ أَفَاۤءَ ٱللَّهُ عَلَیۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّـٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَـٰلَـٰتِكَ ٱلَّـٰتِی هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةࣰ مُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِیِّ إِنۡ أَرَادَ ٱلنَّبِیُّ أَن یَسۡتَنكِحَهَا خَالِصَةࣰ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِینَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا عَلَیۡهِمۡ فِیۤ أَزۡوَ ٰ⁠جِهِمۡ وَمَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ لِكَیۡلَا یَكُونَ عَلَیۡكَ حَرَجࣱۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا',
    'يا ايها النبي انا احللنا لك ازواجك اللاتي اتيت اجورهن وما ملكت يمينك مما افاء الله عليك وبنات عمك وبنات عماتك وبنات خالك وبنات خالاتك اللاتي هاجرن معك وامراة مؤمنة ان وهبت نفسها للنبي ان اراد النبي ان يستنكحها خالصة لك من دون المؤمنين قد علمنا ما فرضنا عليهم في ازواجهم وما ملكت ايمانهم لكيلا يكون عليك حرج وكان الله غفورا رحيما',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَحۡلَلۡنَا لَكَ أَزۡو<rule class=madda_normal>ٰ</rule>جَكَ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>ت<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاتَيۡتَ أُجُورَهُ<rule class=ghunnah>نّ</rule>َ وَمَا مَلَكَتۡ يَمِينُكَ مِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡكَ وَبَنَاتِ عَ<rule class=ghunnah>مّ</rule>ِكَ وَبَنَاتِ عَ<rule class=ghunnah>مّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِكَ <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_normal>ـٰ</rule>تِى هَاجَرۡنَ مَعَكَ وَ<rule class=ham_wasl>ٱ</rule>مۡرَأَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنَةً إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َهَبَتۡ نَفۡسَهَا لِل<rule class=ghunnah>نّ</rule>َبِىِّ إِنۡ أَرَادَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَ<rule class=ikhafa>نك</rule>ِحَهَا خَالِصَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَۗ قَ<rule class=qalaqah>دۡ</rule> عَلِمۡنَا مَا فَرَضۡنَا عَلَيۡهِمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule>جِهِمۡ وَمَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُهُمۡ لِكَيۡلَا يَكُونَ عَلَيۡكَ حَرَ<rule class=idgham_ghunnah>جٌۗ</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٥٠',
    50, 22, 5, 424, 366, 169, 'false'
  );
  
  -- Ayah 51 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3584,
    '۞ تُرۡجِی مَن تَشَاۤءُ مِنۡهُنَّ وَتُـٔۡوِیۤ إِلَیۡكَ مَن تَشَاۤءُۖ وَمَنِ ٱبۡتَغَیۡتَ مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَیۡكَۚ ذَ ٰ⁠لِكَ أَدۡنَىٰۤ أَن تَقَرَّ أَعۡیُنُهُنَّ وَلَا یَحۡزَنَّ وَیَرۡضَیۡنَ بِمَاۤ ءَاتَیۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ یَعۡلَمُ مَا فِی قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِیمًا حَلِیمࣰا',
    'ترجي من تشاء منهن وتؤوي اليك من تشاء ومن ابتغيت ممن عزلت فلا جناح عليك ذلك ادنى ان تقر اعينهن ولا يحزن ويرضين بما اتيتهن كلهن والله يعلم ما في قلوبكم وكان الله عليما حليما',
    '۞تُرۡجِى مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡهُ<rule class=ghunnah>نّ</rule>َ وَتُــٔۡو<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡكَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُۖ وَمَنِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغَيۡتَ مِ<rule class=ghunnah>مّ</rule>َنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَيۡكَۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ أَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقَرَّ أَعۡيُنُهُ<rule class=ghunnah>نّ</rule>َ وَلَا يَحۡزَ<rule class=ghunnah>نّ</rule>َ وَيَرۡضَيۡنَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡتَهُ<rule class=ghunnah>نّ</rule>َ كُلُّهُ<rule class=ghunnah>نّ</rule>َۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ مَا فِى قُلُوبِكُمۡۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمًا حَلِيمًا ٥١',
    51, 22, 5, 425, 366, 170, 'false'
  );
  
  -- Ayah 52 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3585,
    'لَّا یَحِلُّ لَكَ ٱلنِّسَاۤءُ مِنۢ بَعۡدُ وَلَاۤ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَ ٰ⁠جࣲ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ یَمِینُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ رَّقِیبࣰا',
    'لا يحل لك النساء من بعد ولا ان تبدل بهن من ازواج ولو اعجبك حسنهن الا ما ملكت يمينك وكان الله على كل شيء رقيبا',
    'لَّا يَحِلُّ لَكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدُ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبَدَّلَ بِهِ<rule class=ghunnah>نّ</rule>َ مِنۡ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ أَعۡجَبَكَ حُسۡنُهُ<rule class=ghunnah>نّ</rule>َ إِلَّا مَا مَلَكَتۡ يَمِينُكَۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=idgham_wo_ghunnah>َىۡءٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّقِيبًا ٥٢',
    52, 22, 5, 425, 366, 170, 'false'
  );
  
  -- Ayah 53 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3586,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَدۡخُلُوا۟ بُیُوتَ ٱلنَّبِیِّ إِلَّاۤ أَن یُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَیۡرَ نَـٰظِرِینَ إِنَىٰهُ وَلَـٰكِنۡ إِذَا دُعِیتُمۡ فَٱدۡخُلُوا۟ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُوا۟ وَلَا مُسۡتَـٔۡنِسِینَ لِحَدِیثٍۚ إِنَّ ذَ ٰ⁠لِكُمۡ كَانَ یُؤۡذِی ٱلنَّبِیَّ فَیَسۡتَحۡیِۦ مِنكُمۡۖ وَٱللَّهُ لَا یَسۡتَحۡیِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَـٰعࣰا فَسۡـَٔلُوهُنَّ مِن وَرَاۤءِ حِجَابࣲۚ ذَ ٰ⁠لِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُوا۟ رَسُولَ ٱللَّهِ وَلَاۤ أَن تَنكِحُوۤا۟ أَزۡوَ ٰ⁠جَهُۥ مِنۢ بَعۡدِهِۦۤ أَبَدًاۚ إِنَّ ذَ ٰ⁠لِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِیمًا',
    'يا ايها الذين امنوا لا تدخلوا بيوت النبي الا ان يؤذن لكم الى طعام غير ناظرين اناه ولكن اذا دعيتم فادخلوا فاذا طعمتم فانتشروا ولا مستانسين لحديث ان ذلكم كان يؤذي النبي فيستحيي منكم والله لا يستحيي من الحق واذا سالتموهن متاعا فاسالوهن من وراء حجاب ذلكم اطهر لقلوبكم وقلوبهن وما كان لكم ان تؤذوا رسول الله ولا ان تنكحوا ازواجه من بعده ابدا ان ذلكم كان عند الله عظيما',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَ<rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> بُيُوتَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَيۡرَ نَ<rule class=madda_normal>ـٰ</rule>ظِرِينَ إِنَ<rule class=madda_normal>ـٰ</rule>هُ وَلَ<rule class=madda_normal>ـٰ</rule>كِنۡ إِذَا دُعِيتُمۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> فَإِذَا طَعِمۡتُمۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َشِرُو<rule class=slnt>اۡ</rule> وَلَا مُسۡتَــٔۡنِسِينَ لِحَدِيثٍۚ إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ كَانَ يُؤۡذِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىَّ فَيَسۡتَحۡى<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَسۡتَحۡى<rule class=madda_normal>ِۦ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُ<rule class=ghunnah>نّ</rule>َ مَتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َسۡــَٔلُوهُ<rule class=ghunnah>نّ</rule>َ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ حِجَا<rule class=ikhafa>بٍۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكُمۡ أَ<rule class=qalaqah>طۡ</rule>هَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِ<rule class=ghunnah>نّ</rule>َۚ وَمَا كَانَ لَكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُؤۡذُو<rule class=slnt>اۡ</rule> رَسُولَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نك</rule>ِح<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَزۡو<rule class=madda_normal>ٰ</rule>جَهُ<rule class=madda_normal>ۥ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَبَدًاۚ إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ كَانَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ عَظِيمًا ٥٣',
    53, 22, 5, 425, 367, 170, 'false'
  );
  
  -- Ayah 54 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3587,
    'إِن تُبۡدُوا۟ شَیۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَیۡءٍ عَلِیمࣰا',
    'ان تبدوا شيئا او تخفوه فان الله كان بكل شيء عليما',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>بۡ</rule>دُو<rule class=slnt>اۡ</rule> شَيۡــًٔا أَوۡ تُخۡفُوهُ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِكُلِّ شَىۡءٍ عَلِيمًا ٥٤',
    54, 22, 5, 425, 367, 170, 'false'
  );
  
  -- Ayah 55 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3588,
    'لَّا جُنَاحَ عَلَیۡهِنَّ فِیۤ ءَابَاۤىِٕهِنَّ وَلَاۤ أَبۡنَاۤىِٕهِنَّ وَلَاۤ إِخۡوَ ٰ⁠نِهِنَّ وَلَاۤ أَبۡنَاۤءِ إِخۡوَ ٰ⁠نِهِنَّ وَلَاۤ أَبۡنَاۤءِ أَخَوَ ٰ⁠تِهِنَّ وَلَا نِسَاۤىِٕهِنَّ وَلَا مَا مَلَكَتۡ أَیۡمَـٰنُهُنَّۗ وَٱتَّقِینَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدًا',
    'لا جناح عليهن في ابائهن ولا ابنائهن ولا اخوانهن ولا ابناء اخوانهن ولا ابناء اخواتهن ولا نسائهن ولا ما ملكت ايمانهن واتقين الله ان الله كان على كل شيء شهيدا',
    'لَّا جُنَاحَ عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِ<rule class=ghunnah>نّ</rule>َ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِ<rule class=ghunnah>نّ</rule>َ وَل<rule class=madda_obligatory_monfasel>َآ</rule> إِخۡو<rule class=madda_normal>ٰ</rule>نِهِ<rule class=ghunnah>نّ</rule>َ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِخۡو<rule class=madda_normal>ٰ</rule>نِهِ<rule class=ghunnah>نّ</rule>َ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أَخَو<rule class=madda_normal>ٰ</rule>تِهِ<rule class=ghunnah>نّ</rule>َ وَلَا نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِ<rule class=ghunnah>نّ</rule>َ وَلَا مَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُهُ<rule class=ghunnah>نّ</rule>َۗ وَ<rule class=ham_wasl>ٱ</rule>تَّقِينَ <rule class=ham_wasl>ٱ</rule>للَّهَۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ش</rule>َهِيدًا ٥٥',
    55, 22, 5, 426, 367, 170, 'false'
  );
  
  -- Ayah 56 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3589,
    'إِنَّ ٱللَّهَ وَمَلَـٰۤىِٕكَتَهُۥ یُصَلُّونَ عَلَى ٱلنَّبِیِّۚ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ صَلُّوا۟ عَلَیۡهِ وَسَلِّمُوا۟ تَسۡلِیمًا',
    'ان الله وملائكته يصلون على النبي يا ايها الذين امنوا صلوا عليه وسلموا تسليما',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ وَمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَتَهُ<rule class=madda_normal>ۥ</rule> يُصَلُّونَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّۚ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> صَلُّو<rule class=slnt>اۡ</rule> عَلَيۡهِ وَسَلِّمُو<rule class=slnt>اۡ</rule> تَسۡلِيمًا ٥٦',
    56, 22, 5, 426, 367, 170, 'false'
  );
  
  -- Ayah 57 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3590,
    'إِنَّ ٱلَّذِینَ یُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابࣰا مُّهِینࣰا',
    'ان الذين يؤذون الله ورسوله لعنهم الله في الدنيا والاخرة واعد لهم عذابا مهينا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡذُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> لَعَنَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَأَعَدَّ لَهُمۡ عَذَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ُّهِينًا ٥٧',
    57, 22, 5, 426, 367, 170, 'false'
  );
  
  -- Ayah 58 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3591,
    'وَٱلَّذِینَ یُؤۡذُونَ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ بِغَیۡرِ مَا ٱكۡتَسَبُوا۟ فَقَدِ ٱحۡتَمَلُوا۟ بُهۡتَـٰنࣰا وَإِثۡمࣰا مُّبِینࣰا',
    'والذين يؤذون المؤمنين والمؤمنات بغير ما اكتسبوا فقد احتملوا بهتانا واثما مبينا',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُؤۡذُونَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ بِغَيۡرِ مَا <rule class=ham_wasl>ٱ</rule>كۡتَسَبُو<rule class=slnt>اۡ</rule> فَقَدِ <rule class=ham_wasl>ٱ</rule>حۡتَمَلُو<rule class=slnt>اۡ</rule> بُهۡتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َإِثۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ٥٨',
    58, 22, 5, 426, 367, 170, 'false'
  );
  
  -- Ayah 59 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3592,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ قُل لِّأَزۡوَ ٰ⁠جِكَ وَبَنَاتِكَ وَنِسَاۤءِ ٱلۡمُؤۡمِنِینَ یُدۡنِینَ عَلَیۡهِنَّ مِن جَلَـٰبِیبِهِنَّۚ ذَ ٰ⁠لِكَ أَدۡنَىٰۤ أَن یُعۡرَفۡنَ فَلَا یُؤۡذَیۡنَۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا',
    'يا ايها النبي قل لازواجك وبناتك ونساء المؤمنين يدنين عليهن من جلابيبهن ذلك ادنى ان يعرفن فلا يؤذين وكان الله غفورا رحيما',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ قُل لِّأَزۡو<rule class=madda_normal>ٰ</rule>جِكَ وَبَنَاتِكَ وَنِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ يُ<rule class=qalaqah>دۡ</rule>نِينَ عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َلَ<rule class=madda_normal>ـٰ</rule>بِيبِهِ<rule class=ghunnah>نّ</rule>َۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ أَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعۡرَفۡنَ فَلَا يُؤۡذَيۡنَۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ٥٩',
    59, 22, 5, 426, 368, 170, 'false'
  );
  
  -- Ayah 60 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3593,
    '۞ لَّىِٕن لَّمۡ یَنتَهِ ٱلۡمُنَـٰفِقُونَ وَٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ وَٱلۡمُرۡجِفُونَ فِی ٱلۡمَدِینَةِ لَنُغۡرِیَنَّكَ بِهِمۡ ثُمَّ لَا یُجَاوِرُونَكَ فِیهَاۤ إِلَّا قَلِیلࣰا',
    'لئن لم ينته المنافقون والذين في قلوبهم مرض والمرجفون في المدينة لنغرينك بهم ثم لا يجاورونك فيها الا قليلا',
    '۞لَّئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَ<rule class=ikhafa>نت</rule>َهِ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقُونَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡمُرۡجِفُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ لَنُغۡرِيَ<rule class=ghunnah>نّ</rule>َكَ بِهِمۡ ثُ<rule class=ghunnah>مّ</rule>َ لَا يُجَاوِرُونَكَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا قَلِيلاً ٦٠',
    60, 22, 5, 426, 368, 171, 'false'
  );
  
  -- Ayah 61 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3594,
    'مَّلۡعُونِینَۖ أَیۡنَمَا ثُقِفُوۤا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقۡتِیلࣰا',
    'ملعونين اينما ثقفوا اخذوا وقتلوا تقتيلا',
    'مَّلۡعُونِينَۖ أَيۡنَمَا ثُقِف<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أُخِذُو<rule class=slnt>اۡ</rule> وَقُتِّلُو<rule class=slnt>اۡ</rule> تَ<rule class=qalaqah>قۡ</rule>تِيلاً ٦١',
    61, 22, 5, 426, 368, 171, 'false'
  );
  
  -- Ayah 62 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3595,
    'سُنَّةَ ٱللَّهِ فِی ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِیلࣰا',
    'سنة الله في الذين خلوا من قبل ولن تجد لسنة الله تبديلا',
    'سُ<rule class=ghunnah>نّ</rule>َةَ <rule class=ham_wasl>ٱ</rule>للَّهِ فِى <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَلَوۡ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُۖ وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لِسُ<rule class=ghunnah>نّ</rule>َةِ <rule class=ham_wasl>ٱ</rule>للَّهِ تَ<rule class=qalaqah>بۡ</rule>دِيلاً ٦٢',
    62, 22, 5, 426, 368, 171, 'false'
  );
  
  -- Ayah 63 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3596,
    'یَسۡـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِۚ وَمَا یُدۡرِیكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِیبًا',
    'يسالك الناس عن الساعة قل انما علمها عند الله وما يدريك لعل الساعة تكون قريبا',
    'يَسۡــَٔلُكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِۖ قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا عِلۡمُهَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِۚ وَمَا يُ<rule class=qalaqah>دۡ</rule>رِيكَ لَعَلَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ تَكُونُ قَرِيبًا ٦٣',
    63, 22, 5, 427, 368, 171, 'false'
  );
  
  -- Ayah 64 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3597,
    'إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَـٰفِرِینَ وَأَعَدَّ لَهُمۡ سَعِیرًا',
    'ان الله لعن الكافرين واعد لهم سعيرا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ وَأَعَدَّ لَهُمۡ سَعِيرًا ٦٤',
    64, 22, 5, 427, 368, 171, 'false'
  );
  
  -- Ayah 65 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3598,
    'خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ لَّا یَجِدُونَ وَلِیࣰّا وَلَا نَصِیرࣰا',
    'خالدين فيها ابدا لا يجدون وليا ولا نصيرا',
    'خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=idgham_wo_ghunnah>دًاۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَجِدُونَ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصِيرًا ٦٥',
    65, 22, 5, 427, 368, 171, 'false'
  );
  
  -- Ayah 66 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3599,
    'یَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِی ٱلنَّارِ یَقُولُونَ یَـٰلَیۡتَنَاۤ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠',
    'يوم تقلب وجوههم في النار يقولون يا ليتنا اطعنا الله واطعنا الرسولا',
    'يَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ يَقُولُونَ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَن<rule class=madda_obligatory_monfasel>َآ</rule> أَطَعۡنَا <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطَعۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَاۡ ٦٦',
    66, 22, 5, 427, 368, 171, 'false'
  );
  
  -- Ayah 67 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3600,
    'وَقَالُوا۟ رَبَّنَاۤ إِنَّاۤ أَطَعۡنَا سَادَتَنَا وَكُبَرَاۤءَنَا فَأَضَلُّونَا ٱلسَّبِیلَا۠',
    'وقالوا ربنا انا اطعنا سادتنا وكبراءنا فاضلونا السبيلا',
    'وَقَالُو<rule class=slnt>اۡ</rule> رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَطَعۡنَا سَادَتَنَا وَكُبَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا فَأَضَلُّونَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلَاۡ ٦٧',
    67, 22, 5, 427, 368, 171, 'false'
  );
  
  -- Ayah 68 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3601,
    'رَبَّنَاۤ ءَاتِهِمۡ ضِعۡفَیۡنِ مِنَ ٱلۡعَذَابِ وَٱلۡعَنۡهُمۡ لَعۡنࣰا كَبِیرࣰا',
    'ربنا اتهم ضعفين من العذاب والعنهم لعنا كبيرا',
    'رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتِهِمۡ ضِعۡفَيۡنِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ وَ<rule class=ham_wasl>ٱ</rule>لۡعَنۡهُمۡ لَعۡ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٦٨',
    68, 22, 5, 427, 368, 171, 'false'
  );
  
  -- Ayah 69 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3602,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِینَ ءَاذَوۡا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ۚ وَكَانَ عِندَ ٱللَّهِ وَجِیهࣰا',
    'يا ايها الذين امنوا لا تكونوا كالذين اذوا موسى فبراه الله مما قالوا وكان عند الله وجيها',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَكُونُو<rule class=slnt>اۡ</rule> كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَاذَوۡ<rule class=slnt>اۡ</rule> مُوسَىٰ فَبَرَّأَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ghunnah>مّ</rule>َا قَالُو<rule class=slnt>اۡۚ</rule> وَكَانَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَجِيهًا ٦٩',
    69, 22, 5, 427, 369, 171, 'false'
  );
  
  -- Ayah 70 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3603,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوۡلࣰا سَدِیدࣰا',
    'يا ايها الذين امنوا اتقوا الله وقولوا قولا سديدا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَقُولُو<rule class=slnt>اۡ</rule> قَوۡل<rule class=ikhafa>اً</rule> <rule class=ikhafa>س</rule>َدِيدًا ٧٠',
    70, 22, 5, 427, 369, 171, 'false'
  );
  
  -- Ayah 71 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3604,
    'یُصۡلِحۡ لَكُمۡ أَعۡمَـٰلَكُمۡ وَیَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِیمًا',
    'يصلح لكم اعمالكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزا عظيما',
    'يُصۡلِحۡ لَكُمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَكُمۡ وَيَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُطِعِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> فَقَ<rule class=qalaqah>دۡ</rule> فَازَ فَوۡزًا عَظِيمًا ٧١',
    71, 22, 5, 427, 369, 171, 'false'
  );
  
  -- Ayah 72 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3605,
    'إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَیۡنَ أَن یَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَـٰنُۖ إِنَّهُۥ كَانَ ظَلُومࣰا جَهُولࣰا',
    'انا عرضنا الامانة على السماوات والارض والجبال فابين ان يحملنها واشفقن منها وحملها الانسان انه كان ظلوما جهولا',
    'إِ<rule class=ghunnah>نّ</rule>َا عَرَضۡنَا <rule class=ham_wasl>ٱ</rule>لۡأَمَانَةَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule>لۡجِبَالِ فَأَبَيۡنَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َحۡمِلۡنَهَا وَأَشۡفَ<rule class=qalaqah>قۡ</rule>نَ مِنۡهَا وَحَمَلَهَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ ظَلُو<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ج</rule>َهُولاً ٧٢',
    72, 22, 5, 427, 369, 171, 'false'
  );
  
  -- Ayah 73 Surah Al-Ahzaab
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    33,
    3606,
    'لِّیُعَذِّبَ ٱللَّهُ ٱلۡمُنَـٰفِقِینَ وَٱلۡمُنَـٰفِقَـٰتِ وَٱلۡمُشۡرِكِینَ وَٱلۡمُشۡرِكَـٰتِ وَیَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمَۢا',
    'ليعذب الله المنافقين والمنافقات والمشركين والمشركات ويتوب الله على المؤمنين والمؤمنات وكان الله غفورا رحيما',
    'لِّيُعَذِّبَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكَ<rule class=madda_normal>ـٰ</rule>تِ وَيَتُوبَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمَۢا ٧٣',
    73, 22, 5, 427, 369, 171, 'false'
  );
  

-- Surah Saba
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (34, 'سُورَةُ سَبَإٍ', 'Saba', 'Sheba', 'Meccan', 54);

  -- Ayah 1 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3607,
    'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ وَلَهُ ٱلۡحَمۡدُ فِی ٱلۡـَٔاخِرَةِۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡخَبِیرُ',
    'الحمد لله الذي له ما في السماوات وما في الارض وله الحمد في الاخرة وهو الحكيم الخبير',
    'ٱلۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى لَهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَهُ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡحَكِيمُ <rule class=ham_wasl>ٱ</rule>لۡخَب<rule class=madda_permissible>ِي</rule>رُ ١',
    1, 22, 5, 428, 370, 171, 'false'
  );
  
  -- Ayah 2 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3608,
    'یَعۡلَمُ مَا یَلِجُ فِی ٱلۡأَرۡضِ وَمَا یَخۡرُجُ مِنۡهَا وَمَا یَنزِلُ مِنَ ٱلسَّمَاۤءِ وَمَا یَعۡرُجُ فِیهَاۚ وَهُوَ ٱلرَّحِیمُ ٱلۡغَفُورُ',
    'يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو الرحيم الغفور',
    'يَعۡلَمُ مَا يَلِجُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَ<rule class=ikhafa>نز</rule>ِلُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَمَا يَعۡرُجُ فِيهَاۚ وَهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحِيمُ <rule class=ham_wasl>ٱ</rule>لۡغَف<rule class=madda_permissible>ُو</rule>رُ ٢',
    2, 22, 5, 428, 370, 171, 'false'
  );
  
  -- Ayah 3 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3609,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَا تَأۡتِینَا ٱلسَّاعَةُۖ قُلۡ بَلَىٰ وَرَبِّی لَتَأۡتِیَنَّكُمۡ عَـٰلِمِ ٱلۡغَیۡبِۖ لَا یَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّةࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَلَا فِی ٱلۡأَرۡضِ وَلَاۤ أَصۡغَرُ مِن ذَ ٰ⁠لِكَ وَلَاۤ أَكۡبَرُ إِلَّا فِی كِتَـٰبࣲ مُّبِینࣲ',
    'وقال الذين كفروا لا تاتينا الساعة قل بلى وربي لتاتينكم عالم الغيب لا يعزب عنه مثقال ذرة في السماوات ولا في الارض ولا اصغر من ذلك ولا اكبر الا في كتاب مبين',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَا تَأۡتِينَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُۖ قُلۡ بَلَىٰ وَرَبِّى لَتَأۡتِيَ<rule class=ghunnah>نّ</rule>َكُمۡ عَ<rule class=madda_normal>ـٰ</rule>لِمِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِۖ لَا يَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَلَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَصۡغَرُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡبَرُ إِلَّا فِى كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٣',
    3, 22, 5, 428, 370, 171, 'false'
  );
  
  -- Ayah 4 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3610,
    'لِّیَجۡزِیَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِۚ أُو۟لَـٰۤىِٕكَ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ',
    'ليجزي الذين امنوا وعملوا الصالحات اولئك لهم مغفرة ورزق كريم',
    'لِّيَ<rule class=qalaqah>جۡ</rule>زِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َرِزۡ<rule class=ikhafa>قٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٤',
    4, 22, 5, 428, 370, 171, 'false'
  );
  
  -- Ayah 5 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3611,
    'وَٱلَّذِینَ سَعَوۡ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مِّن رِّجۡزٍ أَلِیمࣱ',
    'والذين سعوا في اياتنا معاجزين اولئك لهم عذاب من رجز اليم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ سَعَوۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا مُعَ<rule class=madda_normal>ـٰ</rule>جِزِينَ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّ<rule class=qalaqah>جۡ</rule>زٍ أَل<rule class=madda_permissible>ِي</rule>مٌ ٥',
    5, 22, 5, 428, 370, 171, 'false'
  );
  
  -- Ayah 6 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3612,
    'وَیَرَى ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ ٱلَّذِیۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَیَهۡدِیۤ إِلَىٰ صِرَ ٰ⁠طِ ٱلۡعَزِیزِ ٱلۡحَمِیدِ',
    'ويرى الذين اوتوا العلم الذي انزل اليك من ربك هو الحق ويهدي الى صراط العزيز الحميد',
    'وَيَرَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ وَيَهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ صِر<rule class=madda_normal>ٰ</rule>طِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٦',
    6, 22, 5, 428, 370, 171, 'false'
  );
  
  -- Ayah 7 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3613,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلࣲ یُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِی خَلۡقࣲ جَدِیدٍ',
    'وقال الذين كفروا هل ندلكم على رجل ينبئكم اذا مزقتم كل ممزق انكم لفي خلق جديد',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُنَبِّئُكُمۡ إِذَا مُزِّ<rule class=qalaqah>قۡ</rule>تُمۡ كُلَّ مُمَزَّقٍ إِ<rule class=ghunnah>نّ</rule>َكُمۡ لَفِى خَلۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ج</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٧',
    7, 22, 5, 428, 370, 171, 'false'
  );
  
  -- Ayah 8 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3614,
    'أَفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةُۢۗ بَلِ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ فِی ٱلۡعَذَابِ وَٱلضَّلَـٰلِ ٱلۡبَعِیدِ',
    'افترى على الله كذبا ام به جنة بل الذين لا يؤمنون بالاخرة في العذاب والضلال البعيد',
    'أَفۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا أ<rule class=ikhafa_shafawi>َم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> جِ<rule class=ghunnah>نّ</rule>َۗ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>َلِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ فِى <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضَّلَ<rule class=madda_normal>ـٰ</rule>لِ <rule class=ham_wasl>ٱ</rule>لۡبَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٨',
    8, 22, 5, 429, 370, 171, 'false'
  );
  
  -- Ayah 9 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3615,
    'أَفَلَمۡ یَرَوۡا۟ إِلَىٰ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَیۡهِمۡ كِسَفࣰا مِّنَ ٱلسَّمَاۤءِۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّكُلِّ عَبۡدࣲ مُّنِیبࣲ',
    'افلم يروا الى ما بين ايديهم وما خلفهم من السماء والارض ان نشا نخسف بهم الارض او نسقط عليهم كسفا من السماء ان في ذلك لاية لكل عبد منيب',
    'أَفَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّشَأۡ نَخۡسِفۡ بِهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ أَوۡ نُسۡقِ<rule class=qalaqah>طۡ</rule> عَلَيۡهِمۡ كِسَ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ عَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٩',
    9, 22, 5, 429, 370, 171, 'false'
  );
  
  -- Ayah 10 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3616,
    '۞ وَلَقَدۡ ءَاتَیۡنَا دَاوُۥدَ مِنَّا فَضۡلࣰاۖ یَـٰجِبَالُ أَوِّبِی مَعَهُۥ وَٱلطَّیۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِیدَ',
    'ولقد اتينا داوود منا فضلا يا جبال اوبي معه والطير والنا له الحديد',
    '۞وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا دَاوُ<rule class=madda_normal>ۥ</rule>دَ مِ<rule class=ghunnah>نّ</rule>َا فَضۡل<rule class=idgham_ghunnah>اًۖ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_normal>ـٰ</rule>جِبَالُ أَوِّبِى مَعَهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرَۖ وَأَلَ<rule class=ghunnah>نّ</rule>َا لَهُ <rule class=ham_wasl>ٱ</rule>لۡحَد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>َ ١٠',
    10, 22, 5, 429, 371, 172, 'false'
  );
  
  -- Ayah 11 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3617,
    'أَنِ ٱعۡمَلۡ سَـٰبِغَـٰتࣲ وَقَدِّرۡ فِی ٱلسَّرۡدِۖ وَٱعۡمَلُوا۟ صَـٰلِحًاۖ إِنِّی بِمَا تَعۡمَلُونَ بَصِیرࣱ',
    'ان اعمل سابغات وقدر في السرد واعملوا صالحا اني بما تعملون بصير',
    'أَنِ <rule class=ham_wasl>ٱ</rule>عۡمَلۡ سَ<rule class=madda_normal>ـٰ</rule>بِغَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َقَدِّرۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّرۡدِۖ وَ<rule class=ham_wasl>ٱ</rule>عۡمَلُو<rule class=slnt>اۡ</rule> صَ<rule class=madda_normal>ـٰ</rule>لِحًاۖ إِ<rule class=ghunnah>نّ</rule>ِى بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ١١',
    11, 22, 5, 429, 371, 172, 'false'
  );
  
  -- Ayah 12 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3618,
    'وَلِسُلَیۡمَـٰنَ ٱلرِّیحَ غُدُوُّهَا شَهۡرࣱ وَرَوَاحُهَا شَهۡرࣱۖ وَأَسَلۡنَا لَهُۥ عَیۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن یَعۡمَلُ بَیۡنَ یَدَیۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن یَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِیرِ',
    'ولسليمان الريح غدوها شهر ورواحها شهر واسلنا له عين القطر ومن الجن من يعمل بين يديه باذن ربه ومن يزغ منهم عن امرنا نذقه من عذاب السعير',
    'وَلِسُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيحَ غُدُوُّهَا شَهۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َرَوَاحُهَا شَهۡ<rule class=idgham_ghunnah>رٌۖ</rule> <rule class=idgham_ghunnah>و</rule>َأَسَلۡنَا لَهُ<rule class=madda_normal>ۥ</rule> عَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡقِ<rule class=qalaqah>طۡ</rule>رِۖ وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلُ بَيۡنَ يَدَيۡهِ بِإِذۡنِ رَبِّهِ<rule class=madda_normal>ۖۦ</rule> وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِ<rule class=qalaqah>قۡ</rule>هُ مِنۡ عَذَابِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّع<rule class=madda_permissible>ِي</rule>رِ ١٢',
    12, 22, 5, 429, 371, 172, 'false'
  );
  
  -- Ayah 13 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3619,
    'یَعۡمَلُونَ لَهُۥ مَا یَشَاۤءُ مِن مَّحَـٰرِیبَ وَتَمَـٰثِیلَ وَجِفَانࣲ كَٱلۡجَوَابِ وَقُدُورࣲ رَّاسِیَـٰتٍۚ ٱعۡمَلُوۤا۟ ءَالَ دَاوُۥدَ شُكۡرࣰاۚ وَقَلِیلࣱ مِّنۡ عِبَادِیَ ٱلشَّكُورُ',
    'يعملون له ما يشاء من محاريب وتماثيل وجفان كالجواب وقدور راسيات اعملوا ال داوود شكرا وقليل من عبادي الشكور',
    'يَعۡمَلُونَ لَهُ<rule class=madda_normal>ۥ</rule> مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّحَ<rule class=madda_normal>ـٰ</rule>رِيبَ وَتَمَ<rule class=madda_normal>ـٰ</rule>ثِيلَ وَجِفَا<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ك</rule>َ<rule class=ham_wasl>ٱ</rule>لۡجَوَابِ وَقُدُو<rule class=idgham_wo_ghunnah>رٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّاسِيَ<rule class=madda_normal>ـٰ</rule>تٍۚ <rule class=ham_wasl>ٱ</rule>عۡمَل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَالَ دَاوُ<rule class=madda_normal>ۥ</rule>دَ شُكۡ<rule class=idgham_ghunnah>رًاۚ</rule> <rule class=idgham_ghunnah>و</rule>َقَلِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِبَادِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّك<rule class=madda_permissible>ُو</rule>رُ ١٣',
    13, 22, 5, 429, 371, 172, 'false'
  );
  
  -- Ayah 14 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3620,
    'فَلَمَّا قَضَیۡنَا عَلَیۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦۤ إِلَّا دَاۤبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَیَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُوا۟ یَعۡلَمُونَ ٱلۡغَیۡبَ مَا لَبِثُوا۟ فِی ٱلۡعَذَابِ ٱلۡمُهِینِ',
    'فلما قضينا عليه الموت ما دلهم على موته الا دابة الارض تاكل منساته فلما خر تبينت الجن ان لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا قَضَيۡنَا عَلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا د<rule class=madda_necessary>َا</rule>ٓبَّةُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ تَأۡكُلُ مِ<rule class=ikhafa>نس</rule>َأَتَهُۖ<rule class=madda_normal>ۥ</rule> فَلَ<rule class=ghunnah>مّ</rule>َا خَرَّ تَبَيَّنَتِ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ُ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡلَمُونَ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبَ مَا لَبِثُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ <rule class=ham_wasl>ٱ</rule>لۡمُه<rule class=madda_permissible>ِي</rule>نِ ١٤',
    14, 22, 5, 429, 371, 172, 'false'
  );
  
  -- Ayah 15 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3621,
    'لَقَدۡ كَانَ لِسَبَإࣲ فِی مَسۡكَنِهِمۡ ءَایَةࣱۖ جَنَّتَانِ عَن یَمِینࣲ وَشِمَالࣲۖ كُلُوا۟ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُوا۟ لَهُۥۚ بَلۡدَةࣱ طَیِّبَةࣱ وَرَبٌّ غَفُورࣱ',
    'لقد كان لسبا في مسكنهم اية جنتان عن يمين وشمال كلوا من رزق ربكم واشكروا له بلدة طيبة ورب غفور',
    'لَقَ<rule class=qalaqah>دۡ</rule> كَانَ لِسَبَ<rule class=ikhafa>إٍ</rule> <rule class=ikhafa>ف</rule>ِى مَسۡكَنِهِمۡ ءَايَ<rule class=ikhafa>ةٌۖ</rule> <rule class=ikhafa>ج</rule>َ<rule class=ghunnah>نّ</rule>َتَانِ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمِي<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َشِمَا<rule class=ikhafa>لٍۖ</rule> <rule class=ikhafa>ك</rule>ُلُو<rule class=slnt>اۡ</rule> م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّزۡقِ رَبِّكُمۡ وَ<rule class=ham_wasl>ٱ</rule>شۡكُرُو<rule class=slnt>اۡ</rule> لَهُۚ<rule class=madda_normal>ۥ</rule> بَلۡدَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ط</rule>َيِّبَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َرَبٌّ غَف<rule class=madda_permissible>ُو</rule>رٌ ١٥',
    15, 22, 5, 430, 371, 172, 'false'
  );
  
  -- Ayah 16 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3622,
    'فَأَعۡرَضُوا۟ فَأَرۡسَلۡنَا عَلَیۡهِمۡ سَیۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَـٰهُم بِجَنَّتَیۡهِمۡ جَنَّتَیۡنِ ذَوَاتَیۡ أُكُلٍ خَمۡطࣲ وَأَثۡلࣲ وَشَیۡءࣲ مِّن سِدۡرࣲ قَلِیلࣲ',
    'فاعرضوا فارسلنا عليهم سيل العرم وبدلناهم بجنتيهم جنتين ذواتي اكل خمط واثل وشيء من سدر قليل',
    'فَأَعۡرَضُو<rule class=slnt>اۡ</rule> فَأَرۡسَلۡنَا عَلَيۡهِمۡ سَيۡلَ <rule class=ham_wasl>ٱ</rule>لۡعَرِمِ وَبَدَّلۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِجَ<rule class=ghunnah>نّ</rule>َتَيۡهِمۡ جَ<rule class=ghunnah>نّ</rule>َتَيۡنِ ذَوَات<rule class=madda_obligatory_monfasel>َىۡ</rule> أُكُلٍ خَمۡ<rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَثۡ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ِ<rule class=qalaqah>دۡ</rule><rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ق</rule>َل<rule class=madda_permissible>ِي</rule>لٍ ١٦',
    16, 22, 5, 430, 371, 172, 'false'
  );
  
  -- Ayah 17 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3623,
    'ذَ ٰ⁠لِكَ جَزَیۡنَـٰهُم بِمَا كَفَرُوا۟ۖ وَهَلۡ نُجَـٰزِیۤ إِلَّا ٱلۡكَفُورَ',
    'ذلك جزيناهم بما كفروا وهل نجازي الا الكفور',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ جَزَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَفَرُو<rule class=slnt>اۡۖ</rule> وَهَلۡ نُجَ<rule class=madda_normal>ـٰ</rule>ز<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡكَف<rule class=madda_permissible>ُو</rule>رَ ١٧',
    17, 22, 5, 430, 371, 172, 'false'
  );
  
  -- Ayah 18 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3624,
    'وَجَعَلۡنَا بَیۡنَهُمۡ وَبَیۡنَ ٱلۡقُرَى ٱلَّتِی بَـٰرَكۡنَا فِیهَا قُرࣰى ظَـٰهِرَةࣰ وَقَدَّرۡنَا فِیهَا ٱلسَّیۡرَۖ سِیرُوا۟ فِیهَا لَیَالِیَ وَأَیَّامًا ءَامِنِینَ',
    'وجعلنا بينهم وبين القرى التي باركنا فيها قرى ظاهرة وقدرنا فيها السير سيروا فيها ليالي واياما امنين',
    'وَجَعَلۡنَا بَيۡنَهُمۡ وَبَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡقُرَى <rule class=ham_wasl>ٱ</rule>لَّتِى بَ<rule class=madda_normal>ـٰ</rule>رَكۡنَا فِيهَا قُ<rule class=ikhafa>رًى</rule> <rule class=ikhafa>ظ</rule>َ<rule class=madda_normal>ـٰ</rule>هِرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َقَدَّرۡنَا فِيهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيۡرَۖ سِيرُو<rule class=slnt>اۡ</rule> فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِن<rule class=madda_permissible>ِي</rule>نَ ١٨',
    18, 22, 5, 430, 371, 172, 'false'
  );
  
  -- Ayah 19 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3625,
    'فَقَالُوا۟ رَبَّنَا بَـٰعِدۡ بَیۡنَ أَسۡفَارِنَا وَظَلَمُوۤا۟ أَنفُسَهُمۡ فَجَعَلۡنَـٰهُمۡ أَحَادِیثَ وَمَزَّقۡنَـٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ',
    'فقالوا ربنا باعد بين اسفارنا وظلموا انفسهم فجعلناهم احاديث ومزقناهم كل ممزق ان في ذلك لايات لكل صبار شكور',
    'فَقَالُو<rule class=slnt>اۡ</rule> رَبَّنَا بَ<rule class=madda_normal>ـٰ</rule>عِ<rule class=qalaqah>دۡ</rule> بَيۡنَ أَسۡفَارِنَا وَظَلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ فَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ أَحَادِيثَ وَمَزَّ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ كُلَّ مُمَزَّقٍۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ صَبَّا<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ش</rule>َك<rule class=madda_permissible>ُو</rule>رٍ ١٩',
    19, 22, 5, 430, 371, 172, 'false'
  );
  
  -- Ayah 20 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3626,
    'وَلَقَدۡ صَدَّقَ عَلَیۡهِمۡ إِبۡلِیسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِیقࣰا مِّنَ ٱلۡمُؤۡمِنِینَ',
    'ولقد صدق عليهم ابليس ظنه فاتبعوه الا فريقا من المؤمنين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> صَدَّقَ عَلَيۡهِمۡ إِ<rule class=qalaqah>بۡ</rule>لِيسُ ظَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> فَ<rule class=ham_wasl>ٱ</rule>تَّبَعُوهُ إِلَّا فَرِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 22, 5, 430, 371, 172, 'false'
  );
  
  -- Ayah 21 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3627,
    'وَمَا كَانَ لَهُۥ عَلَیۡهِم مِّن سُلۡطَـٰنٍ إِلَّا لِنَعۡلَمَ مَن یُؤۡمِنُ بِٱلۡـَٔاخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِی شَكࣲّۗ وَرَبُّكَ عَلَىٰ كُلِّ شَیۡءٍ حَفِیظࣱ',
    'وما كان له عليهم من سلطان الا لنعلم من يؤمن بالاخرة ممن هو منها في شك وربك على كل شيء حفيظ',
    'وَمَا كَانَ لَهُ<rule class=madda_normal>ۥ</rule> عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلۡطَ<rule class=madda_normal>ـٰ</rule>نٍ إِلَّا لِنَعۡلَمَ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ مِ<rule class=ghunnah>مّ</rule>َنۡ هُوَ مِنۡهَا فِى شَ<rule class=idgham_ghunnah>كٍّۗ</rule> <rule class=idgham_ghunnah>و</rule>َرَبُّكَ عَلَىٰ كُلِّ شَىۡءٍ حَف<rule class=madda_permissible>ِي</rule>ظٌ ٢١',
    21, 22, 5, 430, 371, 172, 'false'
  );
  
  -- Ayah 22 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3628,
    'قُلِ ٱدۡعُوا۟ ٱلَّذِینَ زَعَمۡتُم مِّن دُونِ ٱللَّهِ لَا یَمۡلِكُونَ مِثۡقَالَ ذَرَّةࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَلَا فِی ٱلۡأَرۡضِ وَمَا لَهُمۡ فِیهِمَا مِن شِرۡكࣲ وَمَا لَهُۥ مِنۡهُم مِّن ظَهِیرࣲ',
    'قل ادعوا الذين زعمتم من دون الله لا يملكون مثقال ذرة في السماوات ولا في الارض وما لهم فيهما من شرك وما له منهم من ظهير',
    'قُلِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ زَعَمۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِۖ لَا يَمۡلِكُونَ مِثۡقَالَ ذَرَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَلَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا لَهُمۡ فِيهِمَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ِرۡ<rule class=idgham_ghunnah>كٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا لَهُ<rule class=madda_normal>ۥ</rule> مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>َه<rule class=madda_permissible>ِي</rule>رٍ ٢٢',
    22, 22, 5, 430, 372, 172, 'false'
  );
  
  -- Ayah 23 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3629,
    'وَلَا تَنفَعُ ٱلشَّفَـٰعَةُ عِندَهُۥۤ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ حَتَّىٰۤ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُوا۟ مَاذَا قَالَ رَبُّكُمۡۖ قَالُوا۟ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ',
    'ولا تنفع الشفاعة عنده الا لمن اذن له حتى اذا فزع عن قلوبهم قالوا ماذا قال ربكم قالوا الحق وهو العلي الكبير',
    'وَلَا تَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّفَ<rule class=madda_normal>ـٰ</rule>عَةُ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا لِمَنۡ أَذِنَ لَهُۚ<rule class=madda_normal>ۥ</rule> حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا فُزِّعَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُلُوبِهِمۡ قَالُو<rule class=slnt>اۡ</rule> مَاذَا قَالَ رَبُّكُمۡۖ قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَقَّۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِىُّ <rule class=ham_wasl>ٱ</rule>لۡكَب<rule class=madda_permissible>ِي</rule>رُ ٢٣',
    23, 22, 5, 431, 372, 172, 'false'
  );
  
  -- Ayah 24 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3630,
    '۞ قُلۡ مَن یَرۡزُقُكُم مِّنَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ قُلِ ٱللَّهُۖ وَإِنَّاۤ أَوۡ إِیَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'قل من يرزقكم من السماوات والارض قل الله وانا او اياكم لعلى هدى او في ضلال مبين',
    '۞قُلۡ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َرۡزُقُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِۖ قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُۖ وَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ إِيَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٢٤',
    24, 22, 5, 431, 372, 173, 'false'
  );
  
  -- Ayah 25 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3631,
    'قُل لَّا تُسۡـَٔلُونَ عَمَّاۤ أَجۡرَمۡنَا وَلَا نُسۡـَٔلُ عَمَّا تَعۡمَلُونَ',
    'قل لا تسالون عما اجرمنا ولا نسال عما تعملون',
    'قُل لَّا تُسۡــَٔلُونَ عَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>جۡ</rule>رَمۡنَا وَلَا نُسۡــَٔلُ عَ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 22, 5, 431, 372, 173, 'false'
  );
  
  -- Ayah 26 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3632,
    'قُلۡ یَجۡمَعُ بَیۡنَنَا رَبُّنَا ثُمَّ یَفۡتَحُ بَیۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِیمُ',
    'قل يجمع بيننا ربنا ثم يفتح بيننا بالحق وهو الفتاح العليم',
    'قُلۡ يَ<rule class=qalaqah>جۡ</rule>مَعُ بَيۡنَنَا رَبُّنَا ثُ<rule class=ghunnah>مّ</rule>َ يَفۡتَحُ بَيۡنَنَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡفَتَّاحُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٢٦',
    26, 22, 5, 431, 372, 173, 'false'
  );
  
  -- Ayah 27 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3633,
    'قُلۡ أَرُونِیَ ٱلَّذِینَ أَلۡحَقۡتُم بِهِۦ شُرَكَاۤءَۖ كَلَّاۚ بَلۡ هُوَ ٱللَّهُ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'قل اروني الذين الحقتم به شركاء كلا بل هو الله العزيز الحكيم',
    'قُلۡ أَرُونِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَلۡحَ<rule class=qalaqah>قۡ</rule>ت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَۖ كَلَّاۚ بَلۡ هُوَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٢٧',
    27, 22, 5, 431, 372, 173, 'false'
  );
  
  -- Ayah 28 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3634,
    'وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا كَاۤفَّةࣰ لِّلنَّاسِ بَشِیرࣰا وَنَذِیرࣰا وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'وما ارسلناك الا كافة للناس بشيرا ونذيرا ولكن اكثر الناس لا يعلمون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ إِلَّا ك<rule class=madda_necessary>َا</rule>ٓفَّ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّل<rule class=ghunnah>نّ</rule>َاسِ بَشِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَذِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 22, 5, 431, 372, 173, 'false'
  );
  
  -- Ayah 29 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3635,
    'وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ويقولون متى هذا الوعد ان كنتم صادقين',
    'وَيَقُولُونَ مَتَىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡوَعۡدُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 22, 5, 431, 372, 173, 'false'
  );
  
  -- Ayah 30 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3636,
    'قُل لَّكُم مِّیعَادُ یَوۡمࣲ لَّا تَسۡتَـٔۡخِرُونَ عَنۡهُ سَاعَةࣰ وَلَا تَسۡتَقۡدِمُونَ',
    'قل لكم ميعاد يوم لا تستاخرون عنه ساعة ولا تستقدمون',
    'قُل لَّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّيعَادُ يَوۡ<rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَسۡتَــٔۡخِرُونَ عَنۡهُ سَاعَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَسۡتَ<rule class=qalaqah>قۡ</rule>دِم<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 22, 5, 431, 372, 173, 'false'
  );
  
  -- Ayah 31 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3637,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَن نُّؤۡمِنَ بِهَـٰذَا ٱلۡقُرۡءَانِ وَلَا بِٱلَّذِی بَیۡنَ یَدَیۡهِۗ وَلَوۡ تَرَىٰۤ إِذِ ٱلظَّـٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ یَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ یَقُولُ ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوا۟ لَوۡلَاۤ أَنتُمۡ لَكُنَّا مُؤۡمِنِینَ',
    'وقال الذين كفروا لن نؤمن بهذا القران ولا بالذي بين يديه ولو ترى اذ الظالمون موقوفون عند ربهم يرجع بعضهم الى بعض القول يقول الذين استضعفوا للذين استكبروا لولا انتم لكنا مؤمنين',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّؤۡمِنَ بِهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ وَلَا بِ<rule class=ham_wasl>ٱ</rule>لَّذِى بَيۡنَ يَدَيۡهِۗ وَلَوۡ تَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ مَوۡقُوفُونَ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ يَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلَ يَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتُضۡعِفُو<rule class=slnt>اۡ</rule> لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ لَكُ<rule class=ghunnah>نّ</rule>َا مُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 22, 5, 431, 373, 173, 'false'
  );
  
  -- Ayah 32 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3638,
    'قَالَ ٱلَّذِینَ ٱسۡتَكۡبَرُوا۟ لِلَّذِینَ ٱسۡتُضۡعِفُوۤا۟ أَنَحۡنُ صَدَدۡنَـٰكُمۡ عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَاۤءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِینَ',
    'قال الذين استكبروا للذين استضعفوا انحن صددناكم عن الهدى بعد اذ جاءكم بل كنتم مجرمين',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتُضۡعِف<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَنَحۡنُ صَدَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>كُمۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ بَعۡدَ إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=ikhafa_shafawi>ُمۖ</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ كُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 22, 5, 432, 373, 173, 'false'
  );
  
  -- Ayah 33 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3639,
    'وَقَالَ ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوا۟ بَلۡ مَكۡرُ ٱلَّیۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَاۤ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥۤ أَندَادࣰاۚ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلۡعَذَابَۚ وَجَعَلۡنَا ٱلۡأَغۡلَـٰلَ فِیۤ أَعۡنَاقِ ٱلَّذِینَ كَفَرُوا۟ۖ هَلۡ یُجۡزَوۡنَ إِلَّا مَا كَانُوا۟ یَعۡمَلُونَ',
    'وقال الذين استضعفوا للذين استكبروا بل مكر الليل والنهار اذ تامروننا ان نكفر بالله ونجعل له اندادا واسروا الندامة لما راوا العذاب وجعلنا الاغلال في اعناق الذين كفروا هل يجزون الا ما كانوا يعملون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتُضۡعِفُو<rule class=slnt>اۡ</rule> لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> بَلۡ مَكۡرُ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ إِذۡ تَأۡمُرُونَن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّكۡفُرَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَنَ<rule class=qalaqah>جۡ</rule>عَلَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=ikhafa>ند</rule>َا<rule class=idgham_ghunnah>دًاۚ</rule> <rule class=idgham_ghunnah>و</rule>َأَسَرُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َدَامَةَ لَ<rule class=ghunnah>مّ</rule>َا رَأَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ وَجَعَلۡنَا <rule class=ham_wasl>ٱ</rule>لۡأَغۡلَ<rule class=madda_normal>ـٰ</rule>لَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡنَاقِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡۚ</rule> هَلۡ يُ<rule class=qalaqah>جۡ</rule>زَوۡنَ إِلَّا مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 22, 5, 432, 373, 173, 'false'
  );
  
  -- Ayah 34 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3640,
    'وَمَاۤ أَرۡسَلۡنَا فِی قَرۡیَةࣲ مِّن نَّذِیرٍ إِلَّا قَالَ مُتۡرَفُوهَاۤ إِنَّا بِمَاۤ أُرۡسِلۡتُم بِهِۦ كَـٰفِرُونَ',
    'وما ارسلنا في قرية من نذير الا قال مترفوها انا بما ارسلتم به كافرون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا فِى قَرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّذِيرٍ إِلَّا قَالَ مُتۡرَفُوه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 22, 5, 432, 373, 173, 'false'
  );
  
  -- Ayah 35 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3641,
    'وَقَالُوا۟ نَحۡنُ أَكۡثَرُ أَمۡوَ ٰ⁠لࣰا وَأَوۡلَـٰدࣰا وَمَا نَحۡنُ بِمُعَذَّبِینَ',
    'وقالوا نحن اكثر اموالا واولادا وما نحن بمعذبين',
    'وَقَالُو<rule class=slnt>اۡ</rule> نَحۡنُ أَكۡثَرُ أَمۡو<rule class=madda_normal>ٰ</rule>ل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َأَوۡلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َمَا نَحۡنُ بِمُعَذَّب<rule class=madda_permissible>ِي</rule>نَ ٣٥',
    35, 22, 5, 432, 373, 173, 'false'
  );
  
  -- Ayah 36 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3642,
    'قُلۡ إِنَّ رَبِّی یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'قل ان ربي يبسط الرزق لمن يشاء ويقدر ولكن اكثر الناس لا يعلمون',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَ<rule class=qalaqah>قۡ</rule>دِرُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 22, 5, 432, 373, 173, 'false'
  );
  
  -- Ayah 37 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3643,
    'وَمَاۤ أَمۡوَ ٰ⁠لُكُمۡ وَلَاۤ أَوۡلَـٰدُكُم بِٱلَّتِی تُقَرِّبُكُمۡ عِندَنَا زُلۡفَىٰۤ إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَأُو۟لَـٰۤىِٕكَ لَهُمۡ جَزَاۤءُ ٱلضِّعۡفِ بِمَا عَمِلُوا۟ وَهُمۡ فِی ٱلۡغُرُفَـٰتِ ءَامِنُونَ',
    'وما اموالكم ولا اولادكم بالتي تقربكم عندنا زلفى الا من امن وعمل صالحا فاولئك لهم جزاء الضعف بما عملوا وهم في الغرفات امنون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لُكُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لَّتِى تُقَرِّبُكُمۡ عِ<rule class=ikhafa>ند</rule>َنَا زُلۡفَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضِّعۡفِ بِمَا عَمِلُو<rule class=slnt>اۡ</rule> وَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡغُرُفَ<rule class=madda_normal>ـٰ</rule>تِ ءَامِن<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 22, 5, 432, 374, 173, 'false'
  );
  
  -- Ayah 38 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3644,
    'وَٱلَّذِینَ یَسۡعَوۡنَ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ فِی ٱلۡعَذَابِ مُحۡضَرُونَ',
    'والذين يسعون في اياتنا معاجزين اولئك في العذاب محضرون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَسۡعَوۡنَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا مُعَ<rule class=madda_normal>ـٰ</rule>جِزِينَ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ فِى <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ مُحۡضَر<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 22, 5, 432, 374, 173, 'false'
  );
  
  -- Ayah 39 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3645,
    'قُلۡ إِنَّ رَبِّی یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُ لَهُۥۚ وَمَاۤ أَنفَقۡتُم مِّن شَیۡءࣲ فَهُوَ یُخۡلِفُهُۥۖ وَهُوَ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ',
    'قل ان ربي يبسط الرزق لمن يشاء من عباده ويقدر له وما انفقتم من شيء فهو يخلفه وهو خير الرازقين',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule> وَيَ<rule class=qalaqah>قۡ</rule>دِرُ لَهُ<rule class=madda_normal>ۥ</rule>ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َ<rule class=qalaqah>قۡ</rule>ت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َهُوَ يُخۡلِفُهُۖ<rule class=madda_normal>ۥ</rule> وَهُوَ خَيۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>زِق<rule class=madda_permissible>ِي</rule>نَ ٣٩',
    39, 22, 5, 432, 374, 173, 'false'
  );
  
  -- Ayah 40 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3646,
    'وَیَوۡمَ یَحۡشُرُهُمۡ جَمِیعࣰا ثُمَّ یَقُولُ لِلۡمَلَـٰۤىِٕكَةِ أَهَـٰۤؤُلَاۤءِ إِیَّاكُمۡ كَانُوا۟ یَعۡبُدُونَ',
    'ويوم يحشرهم جميعا ثم يقول للملائكة اهؤلاء اياكم كانوا يعبدون',
    'وَيَوۡمَ يَحۡشُرُهُمۡ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ يَقُولُ لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ أَهَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِيَّاكُمۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 22, 5, 433, 374, 173, 'false'
  );
  
  -- Ayah 41 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3647,
    'قَالُوا۟ سُبۡحَـٰنَكَ أَنتَ وَلِیُّنَا مِن دُونِهِمۖ بَلۡ كَانُوا۟ یَعۡبُدُونَ ٱلۡجِنَّۖ أَكۡثَرُهُم بِهِم مُّؤۡمِنُونَ',
    'قالوا سبحانك انت ولينا من دونهم بل كانوا يعبدون الجن اكثرهم بهم مؤمنون',
    'قَالُو<rule class=slnt>اۡ</rule> سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَكَ أَ<rule class=ikhafa>نت</rule>َ وَلِيُّنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=ikhafa_shafawi>ِمۖ</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡبُدُونَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>َۖ أَكۡثَرُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 22, 5, 433, 374, 173, 'false'
  );
  
  -- Ayah 42 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3648,
    'فَٱلۡیَوۡمَ لَا یَمۡلِكُ بَعۡضُكُمۡ لِبَعۡضࣲ نَّفۡعࣰا وَلَا ضَرࣰّا وَنَقُولُ لِلَّذِینَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِی كُنتُم بِهَا تُكَذِّبُونَ',
    'فاليوم لا يملك بعضكم لبعض نفعا ولا ضرا ونقول للذين ظلموا ذوقوا عذاب النار التي كنتم بها تكذبون',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ لَا يَمۡلِكُ بَعۡضُكُمۡ لِبَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا ضَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َنَقُولُ لِلَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> ذُوقُو<rule class=slnt>اۡ</rule> عَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ <rule class=ham_wasl>ٱ</rule>لَّتِى كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا تُكَذِّب<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 22, 5, 433, 374, 173, 'false'
  );
  
  -- Ayah 43 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3649,
    'وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ قَالُوا۟ مَا هَـٰذَاۤ إِلَّا رَجُلࣱ یُرِیدُ أَن یَصُدَّكُمۡ عَمَّا كَانَ یَعۡبُدُ ءَابَاۤؤُكُمۡ وَقَالُوا۟ مَا هَـٰذَاۤ إِلَّاۤ إِفۡكࣱ مُّفۡتَرࣰىۚ وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِلۡحَقِّ لَمَّا جَاۤءَهُمۡ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ',
    'واذا تتلى عليهم اياتنا بينات قالوا ما هذا الا رجل يريد ان يصدكم عما كان يعبد اباؤكم وقالوا ما هذا الا افك مفترى وقال الذين كفروا للحق لما جاءهم ان هذا الا سحر مبين',
    'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا بَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> مَا هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا رَجُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َصُدَّكُمۡ عَ<rule class=ghunnah>مّ</rule>َا كَانَ يَعۡبُدُ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ وَقَالُو<rule class=slnt>اۡ</rule> مَا هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِفۡ<rule class=idgham_ghunnah>كٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّفۡتَ<rule class=idgham_ghunnah>رًىۚ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لِلۡحَقِّ لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٤٣',
    43, 22, 5, 433, 374, 173, 'false'
  );
  
  -- Ayah 44 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3650,
    'وَمَاۤ ءَاتَیۡنَـٰهُم مِّن كُتُبࣲ یَدۡرُسُونَهَاۖ وَمَاۤ أَرۡسَلۡنَاۤ إِلَیۡهِمۡ قَبۡلَكَ مِن نَّذِیرࣲ',
    'وما اتيناهم من كتب يدرسونها وما ارسلنا اليهم قبلك من نذير',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُتُ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>رُسُونَهَاۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِمۡ قَ<rule class=qalaqah>بۡ</rule>لَكَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّذ<rule class=madda_permissible>ِي</rule>رٍ ٤٤',
    44, 22, 5, 433, 374, 173, 'false'
  );
  
  -- Ayah 45 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3651,
    'وَكَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ وَمَا بَلَغُوا۟ مِعۡشَارَ مَاۤ ءَاتَیۡنَـٰهُمۡ فَكَذَّبُوا۟ رُسُلِیۖ فَكَیۡفَ كَانَ نَكِیرِ',
    'وكذب الذين من قبلهم وما بلغوا معشار ما اتيناهم فكذبوا رسلي فكيف كان نكير',
    'وَكَذَّبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ وَمَا بَلَغُو<rule class=slnt>اۡ</rule> مِعۡشَارَ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فَكَذَّبُو<rule class=slnt>اۡ</rule> رُسُلِىۖ فَكَيۡفَ كَانَ نَك<rule class=madda_permissible>ِي</rule>رِ ٤٥',
    45, 22, 5, 433, 374, 173, 'false'
  );
  
  -- Ayah 46 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3652,
    '۞ قُلۡ إِنَّمَاۤ أَعِظُكُم بِوَ ٰ⁠حِدَةٍۖ أَن تَقُومُوا۟ لِلَّهِ مَثۡنَىٰ وَفُرَ ٰ⁠دَىٰ ثُمَّ تَتَفَكَّرُوا۟ۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِیرࣱ لَّكُم بَیۡنَ یَدَیۡ عَذَابࣲ شَدِیدࣲ',
    'قل انما اعظكم بواحدة ان تقوموا لله مثنى وفرادى ثم تتفكروا ما بصاحبكم من جنة ان هو الا نذير لكم بين يدي عذاب شديد',
    '۞قُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَعِظُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِو<rule class=madda_normal>ٰ</rule>حِدَةٍۖ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُومُو<rule class=slnt>اۡ</rule> لِلَّهِ مَثۡنَىٰ وَفُر<rule class=madda_normal>ٰ</rule>دَىٰ ثُ<rule class=ghunnah>مّ</rule>َ تَتَفَكَّرُو<rule class=slnt>اۡۚ</rule> مَا بِصَاحِبِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>ِ<rule class=ghunnah>نّ</rule>َةٍۚ إِنۡ هُوَ إِلَّا نَذِي<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَ يَدَىۡ عَذَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ش</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٤٦',
    46, 22, 5, 433, 375, 174, 'false'
  );
  
  -- Ayah 47 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3653,
    'قُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرࣲ فَهُوَ لَكُمۡۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱللَّهِۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدࣱ',
    'قل ما سالتكم من اجر فهو لكم ان اجري الا على الله وهو على كل شيء شهيد',
    'قُلۡ مَا سَأَلۡتُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َهُوَ لَكُمۡۖ إِنۡ أَ<rule class=qalaqah>جۡ</rule>رِىَ إِلَّا عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِۖ وَهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ش</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٤٧',
    47, 22, 5, 433, 375, 174, 'false'
  );
  
  -- Ayah 48 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3654,
    'قُلۡ إِنَّ رَبِّی یَقۡذِفُ بِٱلۡحَقِّ عَلَّـٰمُ ٱلۡغُیُوبِ',
    'قل ان ربي يقذف بالحق علام الغيوب',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َ رَبِّى يَ<rule class=qalaqah>قۡ</rule>ذِفُ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ عَلَّ<rule class=madda_normal>ـٰ</rule>مُ <rule class=ham_wasl>ٱ</rule>لۡغُي<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ِ ٤٨',
    48, 22, 5, 433, 375, 174, 'false'
  );
  
  -- Ayah 49 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3655,
    'قُلۡ جَاۤءَ ٱلۡحَقُّ وَمَا یُبۡدِئُ ٱلۡبَـٰطِلُ وَمَا یُعِیدُ',
    'قل جاء الحق وما يبدئ الباطل وما يعيد',
    'قُلۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَمَا يُ<rule class=qalaqah>بۡ</rule>دِئُ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلُ وَمَا يُع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٤٩',
    49, 22, 5, 434, 375, 174, 'false'
  );
  
  -- Ayah 50 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3656,
    'قُلۡ إِن ضَلَلۡتُ فَإِنَّمَاۤ أَضِلُّ عَلَىٰ نَفۡسِیۖ وَإِنِ ٱهۡتَدَیۡتُ فَبِمَا یُوحِیۤ إِلَیَّ رَبِّیۤۚ إِنَّهُۥ سَمِیعࣱ قَرِیبࣱ',
    'قل ان ضللت فانما اضل على نفسي وان اهتديت فبما يوحي الي ربي انه سميع قريب',
    'قُلۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَلۡتُ فَإِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَضِلُّ عَلَىٰ نَفۡسِىۖ وَإِنِ <rule class=ham_wasl>ٱ</rule>هۡتَدَيۡتُ فَبِمَا يُوح<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىَّ رَبّ<rule class=madda_obligatory_monfasel>ِىٓۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> سَمِي<rule class=ikhafa>عٌ</rule> <rule class=ikhafa>ق</rule>َر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٥٠',
    50, 22, 5, 434, 375, 174, 'false'
  );
  
  -- Ayah 51 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3657,
    'وَلَوۡ تَرَىٰۤ إِذۡ فَزِعُوا۟ فَلَا فَوۡتَ وَأُخِذُوا۟ مِن مَّكَانࣲ قَرِیبࣲ',
    'ولو ترى اذ فزعوا فلا فوت واخذوا من مكان قريب',
    'وَلَوۡ تَرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذۡ فَزِعُو<rule class=slnt>اۡ</rule> فَلَا فَوۡتَ وَأُخِذُو<rule class=slnt>اۡ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ق</rule>َر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٥١',
    51, 22, 5, 434, 375, 174, 'false'
  );
  
  -- Ayah 52 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3658,
    'وَقَالُوۤا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانِۭ بَعِیدࣲ',
    'وقالوا امنا به وانى لهم التناوش من مكان بعيد',
    'وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_normal>ِۦ</rule> وَأَ<rule class=ghunnah>نّ</rule>َىٰ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّنَاوُشُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=iqlab>نِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٥٢',
    52, 22, 5, 434, 375, 174, 'false'
  );
  
  -- Ayah 53 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3659,
    'وَقَدۡ كَفَرُوا۟ بِهِۦ مِن قَبۡلُۖ وَیَقۡذِفُونَ بِٱلۡغَیۡبِ مِن مَّكَانِۭ بَعِیدࣲ',
    'وقد كفروا به من قبل ويقذفون بالغيب من مكان بعيد',
    'وَقَ<rule class=qalaqah>دۡ</rule> كَفَرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُۖ وَيَ<rule class=qalaqah>قۡ</rule>ذِفُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=iqlab>نِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٥٣',
    53, 22, 5, 434, 375, 174, 'false'
  );
  
  -- Ayah 54 Surah Saba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    34,
    3660,
    'وَحِیلَ بَیۡنَهُمۡ وَبَیۡنَ مَا یَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡیَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُوا۟ فِی شَكࣲّ مُّرِیبِۭ',
    'وحيل بينهم وبين ما يشتهون كما فعل باشياعهم من قبل انهم كانوا في شك مريب',
    'وَحِيلَ بَيۡنَهُمۡ وَبَيۡنَ مَا يَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡيَاعِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُۚ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> فِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ُّر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ِۭ ٥٤',
    54, 22, 5, 434, 375, 174, 'false'
  );
  

-- Surah Faatir
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (35, 'سُورَةُ فَاطِرٍ', 'Faatir', 'The Originator', 'Meccan', 45);

  -- Ayah 1 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3661,
    'ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَـٰۤىِٕكَةِ رُسُلًا أُو۟لِیۤ أَجۡنِحَةࣲ مَّثۡنَىٰ وَثُلَـٰثَ وَرُبَـٰعَۚ یَزِیدُ فِی ٱلۡخَلۡقِ مَا یَشَاۤءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'الحمد لله فاطر السماوات والارض جاعل الملائكة رسلا اولي اجنحة مثنى وثلاث ورباع يزيد في الخلق ما يشاء ان الله على كل شيء قدير',
    'ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَاعِلِ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ رُسُلاً أُ<rule class=slnt>وۡ</rule>ل<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>جۡ</rule>نِحَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>َّثۡنَىٰ وَثُلَ<rule class=madda_normal>ـٰ</rule>ثَ وَرُبَ<rule class=madda_normal>ـٰ</rule>عَۚ يَزِيدُ فِى <rule class=ham_wasl>ٱ</rule>لۡخَلۡقِ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١',
    1, 22, 5, 434, 376, 174, 'false'
  );
  
  -- Ayah 2 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3662,
    'مَّا یَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةࣲ فَلَا مُمۡسِكَ لَهَاۖ وَمَا یُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'ما يفتح الله للناس من رحمة فلا ممسك لها وما يمسك فلا مرسل له من بعده وهو العزيز الحكيم',
    'مَّا يَفۡتَحِ <rule class=ham_wasl>ٱ</rule>للَّهُ لِل<rule class=ghunnah>نّ</rule>َاسِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َلَا مُمۡسِكَ لَهَاۖ وَمَا يُمۡسِكۡ فَلَا مُرۡسِلَ لَهُ<rule class=madda_normal>ۥ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِ<rule class=madda_normal>ۚۦ</rule> وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٢',
    2, 22, 5, 434, 376, 174, 'false'
  );
  
  -- Ayah 3 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3663,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ ٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡۚ هَلۡ مِنۡ خَـٰلِقٍ غَیۡرُ ٱللَّهِ یَرۡزُقُكُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ',
    'يا ايها الناس اذكروا نعمت الله عليكم هل من خالق غير الله يرزقكم من السماء والارض لا اله الا هو فانى تؤفكون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ <rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَتَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَلَيۡكُمۡۚ هَلۡ مِنۡ خَ<rule class=madda_normal>ـٰ</rule>لِقٍ غَيۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ يَرۡزُقُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِۚ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَۖ فَأَ<rule class=ghunnah>نّ</rule>َىٰ تُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 22, 5, 434, 376, 174, 'false'
  );
  
  -- Ayah 4 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3664,
    'وَإِن یُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلࣱ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ',
    'وان يكذبوك فقد كذبت رسل من قبلك والى الله ترجع الامور',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَذِّبُوكَ فَقَ<rule class=qalaqah>دۡ</rule> كُذِّبَتۡ رُسُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَۚ وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تُرۡجَعُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رُ ٤',
    4, 22, 5, 435, 376, 174, 'false'
  );
  
  -- Ayah 5 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3665,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَلَا یَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ',
    'يا ايها الناس ان وعد الله حق فلا تغرنكم الحياة الدنيا ولا يغرنكم بالله الغرور',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=ikhafa>قٌّۖ</rule> <rule class=ikhafa>ف</rule>َلَا تَغُرَّ<rule class=ghunnah>نّ</rule>َكُمُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَاۖ وَلَا يَغُرَّ<rule class=ghunnah>نّ</rule>َك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡغَر<rule class=madda_permissible>ُو</rule>رُ ٥',
    5, 22, 5, 435, 376, 174, 'false'
  );
  
  -- Ayah 6 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3666,
    'إِنَّ ٱلشَّیۡطَـٰنَ لَكُمۡ عَدُوࣱّ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا یَدۡعُوا۟ حِزۡبَهُۥ لِیَكُونُوا۟ مِنۡ أَصۡحَـٰبِ ٱلسَّعِیرِ',
    'ان الشيطان لكم عدو فاتخذوه عدوا انما يدعو حزبه ليكونوا من اصحاب السعير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ لَكُمۡ عَدُ<rule class=ikhafa>وٌّ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>تَّخِذُوهُ عَدُوًّاۚ إِ<rule class=ghunnah>نّ</rule>َمَا يَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> حِزۡبَهُ<rule class=madda_normal>ۥ</rule> لِيَكُونُو<rule class=slnt>اۡ</rule> مِنۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّع<rule class=madda_permissible>ِي</rule>رِ ٦',
    6, 22, 5, 435, 376, 174, 'false'
  );
  
  -- Ayah 7 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3667,
    'ٱلَّذِینَ كَفَرُوا۟ لَهُمۡ عَذَابࣱ شَدِیدࣱۖ وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرٌ',
    'الذين كفروا لهم عذاب شديد والذين امنوا وعملوا الصالحات لهم مغفرة واجر كبير',
    'ٱلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَهُمۡ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دٌۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ك</rule>َب<rule class=madda_permissible>ِي</rule>رٌ ٧',
    7, 22, 5, 435, 376, 174, 'false'
  );
  
  -- Ayah 8 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3668,
    'أَفَمَن زُیِّنَ لَهُۥ سُوۤءُ عَمَلِهِۦ فَرَءَاهُ حَسَنࣰاۖ فَإِنَّ ٱللَّهَ یُضِلُّ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَیۡهِمۡ حَسَرَ ٰ⁠تٍۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِمَا یَصۡنَعُونَ',
    'افمن زين له سوء عمله فراه حسنا فان الله يضل من يشاء ويهدي من يشاء فلا تذهب نفسك عليهم حسرات ان الله عليم بما يصنعون',
    'أَفَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>ُيِّنَ لَهُ<rule class=madda_normal>ۥ</rule> س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ عَمَلِه<rule class=madda_normal>ِۦ</rule> فَرَءَاهُ حَسَ<rule class=ikhafa>نًاۖ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُضِلُّ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَهۡدِى م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُۖ فَلَا تَذۡهَ<rule class=qalaqah>بۡ</rule> نَفۡسُكَ عَلَيۡهِمۡ حَسَر<rule class=madda_normal>ٰ</rule>تٍۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِمَا يَصۡنَع<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 22, 5, 435, 377, 174, 'false'
  );
  
  -- Ayah 9 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3669,
    'وَٱللَّهُ ٱلَّذِیۤ أَرۡسَلَ ٱلرِّیَـٰحَ فَتُثِیرُ سَحَابࣰا فَسُقۡنَـٰهُ إِلَىٰ بَلَدࣲ مَّیِّتࣲ فَأَحۡیَیۡنَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ كَذَ ٰ⁠لِكَ ٱلنُّشُورُ',
    'والله الذي ارسل الرياح فتثير سحابا فسقناه الى بلد ميت فاحيينا به الارض بعد موتها كذلك النشور',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡسَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حَ فَتُثِيرُ سَحَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َسُ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ إِلَىٰ بَلَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>َّيِّ<rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>َأَحۡيَيۡنَا بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُش<rule class=madda_permissible>ُو</rule>رُ ٩',
    9, 22, 5, 435, 377, 174, 'false'
  );
  
  -- Ayah 10 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3670,
    'مَن كَانَ یُرِیدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِیعًاۚ إِلَیۡهِ یَصۡعَدُ ٱلۡكَلِمُ ٱلطَّیِّبُ وَٱلۡعَمَلُ ٱلصَّـٰلِحُ یَرۡفَعُهُۥۚ وَٱلَّذِینَ یَمۡكُرُونَ ٱلسَّیِّـَٔاتِ لَهُمۡ عَذَابࣱ شَدِیدࣱۖ وَمَكۡرُ أُو۟لَـٰۤىِٕكَ هُوَ یَبُورُ',
    'من كان يريد العزة فلله العزة جميعا اليه يصعد الكلم الطيب والعمل الصالح يرفعه والذين يمكرون السيئات لهم عذاب شديد ومكر اولئك هو يبور',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يُرِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِزَّةَ فَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡعِزَّةُ جَمِيعًاۚ إِلَيۡهِ يَصۡعَدُ <rule class=ham_wasl>ٱ</rule>لۡكَلِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبُ وَ<rule class=ham_wasl>ٱ</rule>لۡعَمَلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحُ يَرۡفَعُهُۚ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَمۡكُرُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ لَهُمۡ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دٌۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَكۡرُ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُوَ يَب<rule class=madda_permissible>ُو</rule>رُ ١٠',
    10, 22, 5, 435, 377, 174, 'false'
  );
  
  -- Ayah 11 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3671,
    'وَٱللَّهُ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ جَعَلَكُمۡ أَزۡوَ ٰ⁠جࣰاۚ وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا یُعَمَّرُ مِن مُّعَمَّرࣲ وَلَا یُنقَصُ مِنۡ عُمُرِهِۦۤ إِلَّا فِی كِتَـٰبٍۚ إِنَّ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ',
    'والله خلقكم من تراب ثم من نطفة ثم جعلكم ازواجا وما تحمل من انثى ولا تضع الا بعلمه وما يعمر من معمر ولا ينقص من عمره الا في كتاب ان ذلك على الله يسير',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَلَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّ<rule class=qalaqah>طۡ</rule>فَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ جَعَلَكُمۡ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًاۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا تَحۡمِلُ مِنۡ أُ<rule class=ikhafa>نث</rule>َىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِ<rule class=madda_normal>ۚۦ</rule> وَمَا يُعَ<rule class=ghunnah>مّ</rule>َرُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّعَ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُ<rule class=ikhafa>نق</rule>َصُ مِنۡ عُمُرِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا فِى كِتَ<rule class=madda_normal>ـٰ</rule>بٍۚ إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَس<rule class=madda_permissible>ِي</rule>رٌ ١١',
    11, 22, 5, 435, 377, 174, 'false'
  );
  
  -- Ayah 12 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3672,
    'وَمَا یَسۡتَوِی ٱلۡبَحۡرَانِ هَـٰذَا عَذۡبࣱ فُرَاتࣱ سَاۤىِٕغࣱ شَرَابُهُۥ وَهَـٰذَا مِلۡحٌ أُجَاجࣱۖ وَمِن كُلࣲّ تَأۡكُلُونَ لَحۡمࣰا طَرِیࣰّا وَتَسۡتَخۡرِجُونَ حِلۡیَةࣰ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ فِیهِ مَوَاخِرَ لِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ',
    'وما يستوي البحران هذا عذب فرات سائغ شرابه وهذا ملح اجاج ومن كل تاكلون لحما طريا وتستخرجون حلية تلبسونها وترى الفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون',
    'وَمَا يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَانِ هَ<rule class=madda_normal>ـٰ</rule>ذَا عَذۡ<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ف</rule>ُرَا<rule class=ikhafa>تٌ</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=ikhafa>غٌ</rule> <rule class=ikhafa>ش</rule>َرَابُهُ<rule class=madda_normal>ۥ</rule> وَهَ<rule class=madda_normal>ـٰ</rule>ذَا مِلۡحٌ أُجَا<rule class=idgham_ghunnah>جٌۖ</rule> <rule class=idgham_ghunnah>و</rule>َمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>ت</rule>َأۡكُلُونَ لَحۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ط</rule>َرِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َتَسۡتَخۡرِجُونَ حِلۡيَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َلۡبَسُونَهَاۖ وَتَرَى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكَ فِيهِ مَوَاخِرَ لِتَ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> وَلَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 22, 5, 436, 377, 174, 'false'
  );
  
  -- Ayah 13 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3673,
    'یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِی لِأَجَلࣲ مُّسَمࣰّىۚ ذَ ٰ⁠لِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِینَ تَدۡعُونَ مِن دُونِهِۦ مَا یَمۡلِكُونَ مِن قِطۡمِیرٍ',
    'يولج الليل في النهار ويولج النهار في الليل وسخر الشمس والقمر كل يجري لاجل مسمى ذلكم الله ربكم له الملك والذين تدعون من دونه ما يملكون من قطمير',
    'يُولِجُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَيُولِجُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ فِى <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَسَخَّرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>رِى لِأَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=ikhafa>ًّىۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّكُمۡ لَهُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكُۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> مَا يَمۡلِكُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ِ<rule class=qalaqah>طۡ</rule>م<rule class=madda_permissible>ِي</rule>رٍ ١٣',
    13, 22, 5, 436, 377, 174, 'false'
  );
  
  -- Ayah 14 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3674,
    'إِن تَدۡعُوهُمۡ لَا یَسۡمَعُوا۟ دُعَاۤءَكُمۡ وَلَوۡ سَمِعُوا۟ مَا ٱسۡتَجَابُوا۟ لَكُمۡۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ یَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا یُنَبِّئُكَ مِثۡلُ خَبِیرࣲ',
    'ان تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم ويوم القيامة يكفرون بشرككم ولا ينبئك مثل خبير',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>عُوهُمۡ لَا يَسۡمَعُو<rule class=slnt>اۡ</rule> دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ وَلَوۡ سَمِعُو<rule class=slnt>اۡ</rule> مَا <rule class=ham_wasl>ٱ</rule>سۡتَجَابُو<rule class=slnt>اۡ</rule> لَكُمۡۖ وَيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ يَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا يُنَبِّئُكَ مِثۡلُ خَب<rule class=madda_permissible>ِي</rule>رٍ ١٤',
    14, 22, 5, 436, 377, 174, 'false'
  );
  
  -- Ayah 15 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3675,
    '۞ یَـٰۤأَیُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَاۤءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ',
    'يا ايها الناس انتم الفقراء الى الله والله هو الغني الحميد',
    '۞يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ أَ<rule class=ikhafa>نت</rule>ُمُ <rule class=ham_wasl>ٱ</rule>لۡفُقَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَنِىُّ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ١٥',
    15, 22, 5, 436, 378, 175, 'false'
  );
  
  -- Ayah 16 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3676,
    'إِن یَشَأۡ یُذۡهِبۡكُمۡ وَیَأۡتِ بِخَلۡقࣲ جَدِیدࣲ',
    'ان يشا يذهبكم ويات بخلق جديد',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َشَأۡ يُذۡهِ<rule class=qalaqah>بۡ</rule>كُمۡ وَيَأۡتِ بِخَلۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ج</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ١٦',
    16, 22, 5, 436, 378, 175, 'false'
  );
  
  -- Ayah 17 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3677,
    'وَمَا ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ بِعَزِیزࣲ',
    'وما ذلك على الله بعزيز',
    'وَمَا ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ بِعَز<rule class=madda_permissible>ِي</rule>زٍ ١٧',
    17, 22, 5, 436, 378, 175, 'false'
  );
  
  -- Ayah 18 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3678,
    'وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ وَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا یُحۡمَلۡ مِنۡهُ شَیۡءࣱ وَلَوۡ كَانَ ذَا قُرۡبَىٰۤۗ إِنَّمَا تُنذِرُ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا یَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِیرُ',
    'ولا تزر وازرة وزر اخرى وان تدع مثقلة الى حملها لا يحمل منه شيء ولو كان ذا قربى انما تنذر الذين يخشون ربهم بالغيب واقاموا الصلاة ومن تزكى فانما يتزكى لنفسه والى الله المصير',
    'وَلَا تَزِرُ وَازِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>ِزۡرَ أُخۡرَىٰۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>دۡ</rule>عُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا يُحۡمَلۡ مِنۡهُ ش<rule class=idgham_ghunnah>َىۡءٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَوۡ كَانَ ذَا قُرۡبَ<rule class=madda_obligatory_monfasel>ىٰٓۗ</rule> إِ<rule class=ghunnah>نّ</rule>َمَا تُ<rule class=ikhafa>نذ</rule>ِرُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَخۡشَوۡنَ رَبَّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَأَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَۚ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َزَكَّىٰ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَتَزَكَّىٰ لِنَفۡسِهِ<rule class=madda_normal>ۚۦ</rule> وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٨',
    18, 22, 5, 436, 378, 175, 'false'
  );
  
  -- Ayah 19 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3679,
    'وَمَا یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُ',
    'وما يستوي الاعمى والبصير',
    'وَمَا يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡأَعۡمَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡبَص<rule class=madda_permissible>ِي</rule>رُ ١٩',
    19, 22, 5, 437, 378, 175, 'false'
  );
  
  -- Ayah 20 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3680,
    'وَلَا ٱلظُّلُمَـٰتُ وَلَا ٱلنُّورُ',
    'ولا الظلمات ولا النور',
    'وَلَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تُ وَلَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>ُو</rule>رُ ٢٠',
    20, 22, 5, 437, 378, 175, 'false'
  );
  
  -- Ayah 21 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3681,
    'وَلَا ٱلظِّلُّ وَلَا ٱلۡحَرُورُ',
    'ولا الظل ولا الحرور',
    'وَلَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظِّلُّ وَلَا <rule class=ham_wasl>ٱ</rule>لۡحَر<rule class=madda_permissible>ُو</rule>رُ ٢١',
    21, 22, 5, 437, 378, 175, 'false'
  );
  
  -- Ayah 22 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3682,
    'وَمَا یَسۡتَوِی ٱلۡأَحۡیَاۤءُ وَلَا ٱلۡأَمۡوَ ٰ⁠تُۚ إِنَّ ٱللَّهَ یُسۡمِعُ مَن یَشَاۤءُۖ وَمَاۤ أَنتَ بِمُسۡمِعࣲ مَّن فِی ٱلۡقُبُورِ',
    'وما يستوي الاحياء ولا الاموات ان الله يسمع من يشاء وما انت بمسمع من في القبور',
    'وَمَا يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡأَحۡي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَلَا <rule class=ham_wasl>ٱ</rule>لۡأَمۡو<rule class=madda_normal>ٰ</rule>تُۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُسۡمِعُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ بِمُسۡمِ<rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡقُب<rule class=madda_permissible>ُو</rule>رِ ٢٢',
    22, 22, 5, 437, 378, 175, 'false'
  );
  
  -- Ayah 23 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3683,
    'إِنۡ أَنتَ إِلَّا نَذِیرٌ',
    'ان انت الا نذير',
    'إِنۡ أَ<rule class=ikhafa>نت</rule>َ إِلَّا نَذ<rule class=madda_permissible>ِي</rule>رٌ ٢٣',
    23, 22, 5, 437, 378, 175, 'false'
  );
  
  -- Ayah 24 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3684,
    'إِنَّاۤ أَرۡسَلۡنَـٰكَ بِٱلۡحَقِّ بَشِیرࣰا وَنَذِیرࣰاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِیهَا نَذِیرࣱ',
    'انا ارسلناك بالحق بشيرا ونذيرا وان من امة الا خلا فيها نذير',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ بَشِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَذِي<rule class=idgham_ghunnah>رًاۚ</rule> <rule class=idgham_ghunnah>و</rule>َإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أُ<rule class=ghunnah>مّ</rule>َةٍ إِلَّا خَلَا فِيهَا نَذ<rule class=madda_permissible>ِي</rule>رٌ ٢٤',
    24, 22, 5, 437, 378, 175, 'false'
  );
  
  -- Ayah 25 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3685,
    'وَإِن یُكَذِّبُوكَ فَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ وَبِٱلزُّبُرِ وَبِٱلۡكِتَـٰبِ ٱلۡمُنِیرِ',
    'وان يكذبوك فقد كذب الذين من قبلهم جاءتهم رسلهم بالبينات وبالزبر وبالكتاب المنير',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَذِّبُوكَ فَقَ<rule class=qalaqah>دۡ</rule> كَذَّبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَبِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زُّبُرِ وَبِ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡمُن<rule class=madda_permissible>ِي</rule>رِ ٢٥',
    25, 22, 5, 437, 378, 175, 'false'
  );
  
  -- Ayah 26 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3686,
    'ثُمَّ أَخَذۡتُ ٱلَّذِینَ كَفَرُوا۟ۖ فَكَیۡفَ كَانَ نَكِیرِ',
    'ثم اخذت الذين كفروا فكيف كان نكير',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَخَذۡتُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡۖ</rule> فَكَيۡفَ كَانَ نَك<rule class=madda_permissible>ِي</rule>رِ ٢٦',
    26, 22, 5, 437, 378, 175, 'false'
  );
  
  -- Ayah 27 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3687,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَ ٰ⁠تࣲ مُّخۡتَلِفًا أَلۡوَ ٰ⁠نُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِیضࣱ وَحُمۡرࣱ مُّخۡتَلِفٌ أَلۡوَ ٰ⁠نُهَا وَغَرَابِیبُ سُودࣱ',
    'الم تر ان الله انزل من السماء ماء فاخرجنا به ثمرات مختلفا الوانها ومن الجبال جدد بيض وحمر مختلف الوانها وغرابيب سود',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ أَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َأَخۡرَ<rule class=qalaqah>جۡ</rule>نَا بِه<rule class=madda_normal>ِۦ</rule> ثَمَر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّخۡتَلِفًا أَلۡو<rule class=madda_normal>ٰ</rule>نُهَاۚ وَمِنَ <rule class=ham_wasl>ٱ</rule>لۡجِبَالِ جُدَ<rule class=iqlab>دُۢ</rule> <rule class=iqlab>ب</rule>ِي<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>و</rule>َحُمۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّخۡتَلِفٌ أَلۡو<rule class=madda_normal>ٰ</rule>نُهَا وَغَرَابِيبُ س<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٌ ٢٧',
    27, 22, 5, 437, 379, 175, 'false'
  );
  
  -- Ayah 28 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3688,
    'وَمِنَ ٱلنَّاسِ وَٱلدَّوَاۤبِّ وَٱلۡأَنۡعَـٰمِ مُخۡتَلِفٌ أَلۡوَ ٰ⁠نُهُۥ كَذَ ٰ⁠لِكَۗ إِنَّمَا یَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَـٰۤؤُا۟ۗ إِنَّ ٱللَّهَ عَزِیزٌ غَفُورٌ',
    'ومن الناس والدواب والانعام مختلف الوانه كذلك انما يخشى الله من عباده العلماء ان الله عزيز غفور',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّو<rule class=madda_necessary>َا</rule>ٓبِّ وَ<rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ مُخۡتَلِفٌ أَلۡو<rule class=madda_normal>ٰ</rule>نُهُ<rule class=madda_normal>ۥ</rule> كَذ<rule class=madda_normal>ٰ</rule>لِكَۗ إِ<rule class=ghunnah>نّ</rule>َمَا يَخۡشَى <rule class=ham_wasl>ٱ</rule>للَّهَ مِنۡ عِبَادِهِ <rule class=ham_wasl>ٱ</rule>لۡعُلَمَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule>ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَزِيزٌ غَف<rule class=madda_permissible>ُو</rule>رٌ ٢٨',
    28, 22, 5, 437, 379, 175, 'false'
  );
  
  -- Ayah 29 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3689,
    'إِنَّ ٱلَّذِینَ یَتۡلُونَ كِتَـٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقۡنَـٰهُمۡ سِرࣰّا وَعَلَانِیَةࣰ یَرۡجُونَ تِجَـٰرَةࣰ لَّن تَبُورَ',
    'ان الذين يتلون كتاب الله واقاموا الصلاة وانفقوا مما رزقناهم سرا وعلانية يرجون تجارة لن تبور',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَتۡلُونَ كِتَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَأَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ سِر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َعَلَانِيَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َرۡجُونَ تِجَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َب<rule class=madda_permissible>ُو</rule>رَ ٢٩',
    29, 22, 5, 437, 379, 175, 'false'
  );
  
  -- Ayah 30 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3690,
    'لِیُوَفِّیَهُمۡ أُجُورَهُمۡ وَیَزِیدَهُم مِّن فَضۡلِهِۦۤۚ إِنَّهُۥ غَفُورࣱ شَكُورࣱ',
    'ليوفيهم اجورهم ويزيدهم من فضله انه غفور شكور',
    'لِيُوَفِّيَهُمۡ أُجُورَهُمۡ وَيَزِيدَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِهِ<rule class=madda_obligatory_monfasel>ۚۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> غَفُو<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ش</rule>َك<rule class=madda_permissible>ُو</rule>رٌ ٣٠',
    30, 22, 5, 437, 379, 175, 'false'
  );
  
  -- Ayah 31 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3691,
    'وَٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ مِنَ ٱلۡكِتَـٰبِ هُوَ ٱلۡحَقُّ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِیرُۢ بَصِیرࣱ',
    'والذي اوحينا اليك من الكتاب هو الحق مصدقا لما بين يديه ان الله بعباده لخبير بصير',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَيۡهِۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِعِبَادِه<rule class=madda_normal>ِۦ</rule> لَخَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>َص<rule class=madda_permissible>ِي</rule>رٌ ٣١',
    31, 22, 5, 438, 379, 175, 'false'
  );
  
  -- Ayah 32 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3692,
    'ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَـٰبَ ٱلَّذِینَ ٱصۡطَفَیۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمࣱ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدࣱ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَیۡرَ ٰ⁠تِ بِإِذۡنِ ٱللَّهِۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِیرُ',
    'ثم اورثنا الكتاب الذين اصطفينا من عبادنا فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرات باذن الله ذلك هو الفضل الكبير',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَوۡرَثۡنَا <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>صۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّنَفۡسِه<rule class=madda_normal>ِۦ</rule> وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَصِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َمِنۡهُمۡ سَابِ<rule class=iqlab>قُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡخَيۡر<rule class=madda_normal>ٰ</rule>تِ بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَضۡلُ <rule class=ham_wasl>ٱ</rule>لۡكَب<rule class=madda_permissible>ِي</rule>رُ ٣٢',
    32, 22, 5, 438, 379, 175, 'false'
  );
  
  -- Ayah 33 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3693,
    'جَنَّـٰتُ عَدۡنࣲ یَدۡخُلُونَهَا یُحَلَّوۡنَ فِیهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰاۖ وَلِبَاسُهُمۡ فِیهَا حَرِیرࣱ',
    'جنات عدن يدخلونها يحلون فيها من اساور من ذهب ولؤلؤا ولباسهم فيها حرير',
    'جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>خُلُونَهَا يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َهَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َلُؤۡلُ<rule class=idgham_ghunnah>ؤًاۖ</rule> <rule class=idgham_ghunnah>و</rule>َلِبَاسُهُمۡ فِيهَا حَر<rule class=madda_permissible>ِي</rule>رٌ ٣٣',
    33, 22, 5, 438, 379, 175, 'false'
  );
  
  -- Ayah 34 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3694,
    'وَقَالُوا۟ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِیۤ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورࣱ شَكُورٌ',
    'وقالوا الحمد لله الذي اذهب عنا الحزن ان ربنا لغفور شكور',
    'وَقَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَذۡهَبَ عَ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡحَزَنَۖ إِ<rule class=ghunnah>نّ</rule>َ رَبَّنَا لَغَفُو<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ش</rule>َك<rule class=madda_permissible>ُو</rule>رٌ ٣٤',
    34, 22, 5, 438, 379, 175, 'false'
  );
  
  -- Ayah 35 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3695,
    'ٱلَّذِیۤ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا یَمَسُّنَا فِیهَا نَصَبࣱ وَلَا یَمَسُّنَا فِیهَا لُغُوبࣱ',
    'الذي احلنا دار المقامة من فضله لا يمسنا فيها نصب ولا يمسنا فيها لغوب',
    'ٱلَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحَلَّنَا دَارَ <rule class=ham_wasl>ٱ</rule>لۡمُقَامَةِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> لَا يَمَسُّنَا فِيهَا نَصَ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَمَسُّنَا فِيهَا لُغ<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ٌ ٣٥',
    35, 22, 5, 438, 379, 175, 'false'
  );
  
  -- Ayah 36 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3696,
    'وَٱلَّذِینَ كَفَرُوا۟ لَهُمۡ نَارُ جَهَنَّمَ لَا یُقۡضَىٰ عَلَیۡهِمۡ فَیَمُوتُوا۟ وَلَا یُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَ ٰ⁠لِكَ نَجۡزِی كُلَّ كَفُورࣲ',
    'والذين كفروا لهم نار جهنم لا يقضى عليهم فيموتوا ولا يخفف عنهم من عذابها كذلك نجزي كل كفور',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَهُمۡ نَارُ جَهَ<rule class=ghunnah>نّ</rule>َمَ لَا يُ<rule class=qalaqah>قۡ</rule>ضَىٰ عَلَيۡهِمۡ فَيَمُوتُو<rule class=slnt>اۡ</rule> وَلَا يُخَفَّفُ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَذَابِهَاۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى كُلَّ كَف<rule class=madda_permissible>ُو</rule>رٍ ٣٦',
    36, 22, 5, 438, 379, 175, 'false'
  );
  
  -- Ayah 37 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3697,
    'وَهُمۡ یَصۡطَرِخُونَ فِیهَا رَبَّنَاۤ أَخۡرِجۡنَا نَعۡمَلۡ صَـٰلِحًا غَیۡرَ ٱلَّذِی كُنَّا نَعۡمَلُۚ أَوَلَمۡ نُعَمِّرۡكُم مَّا یَتَذَكَّرُ فِیهِ مَن تَذَكَّرَ وَجَاۤءَكُمُ ٱلنَّذِیرُۖ فَذُوقُوا۟ فَمَا لِلظَّـٰلِمِینَ مِن نَّصِیرٍ',
    'وهم يصطرخون فيها ربنا اخرجنا نعمل صالحا غير الذي كنا نعمل اولم نعمركم ما يتذكر فيه من تذكر وجاءكم النذير فذوقوا فما للظالمين من نصير',
    'وَهُمۡ يَصۡطَرِخُونَ فِيهَا رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡرِ<rule class=qalaqah>جۡ</rule>نَا نَعۡمَلۡ صَ<rule class=madda_normal>ـٰ</rule>لِحًا غَيۡرَ <rule class=ham_wasl>ٱ</rule>لَّذِى كُ<rule class=ghunnah>نّ</rule>َا نَعۡمَلُۚ أَوَلَمۡ نُعَ<rule class=ghunnah>مّ</rule>ِرۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَتَذَكَّرُ فِيهِ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َذَكَّرَ وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َذِيرُۖ فَذُوقُو<rule class=slnt>اۡ</rule> فَمَا لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّص<rule class=madda_permissible>ِي</rule>رٍ ٣٧',
    37, 22, 5, 438, 379, 175, 'false'
  );
  
  -- Ayah 38 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3698,
    'إِنَّ ٱللَّهَ عَـٰلِمُ غَیۡبِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'ان الله عالم غيب السماوات والارض انه عليم بذات الصدور',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَ<rule class=madda_normal>ـٰ</rule>لِمُ غَيۡبِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٣٨',
    38, 22, 5, 438, 380, 175, 'false'
  );
  
  -- Ayah 39 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3699,
    'هُوَ ٱلَّذِی جَعَلَكُمۡ خَلَـٰۤىِٕفَ فِی ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَیۡهِ كُفۡرُهُۥۖ وَلَا یَزِیدُ ٱلۡكَـٰفِرِینَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتࣰاۖ وَلَا یَزِیدُ ٱلۡكَـٰفِرِینَ كُفۡرُهُمۡ إِلَّا خَسَارࣰا',
    'هو الذي جعلكم خلائف في الارض فمن كفر فعليه كفره ولا يزيد الكافرين كفرهم عند ربهم الا مقتا ولا يزيد الكافرين كفرهم الا خسارا',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَكُمۡ خَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِفَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِۚ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرَ فَعَلَيۡهِ كُفۡرُهُۖ<rule class=madda_normal>ۥ</rule> وَلَا يَزِيدُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ كُفۡرُهُمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ إِلَّا مَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>تًاۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَزِيدُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ كُفۡرُهُمۡ إِلَّا خَسَارًا ٣٩',
    39, 22, 5, 439, 380, 175, 'false'
  );
  
  -- Ayah 40 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3700,
    'قُلۡ أَرَءَیۡتُمۡ شُرَكَاۤءَكُمُ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِی مَاذَا خَلَقُوا۟ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكࣱ فِی ٱلسَّمَـٰوَ ٰ⁠تِ أَمۡ ءَاتَیۡنَـٰهُمۡ كِتَـٰبࣰا فَهُمۡ عَلَىٰ بَیِّنَتࣲ مِّنۡهُۚ بَلۡ إِن یَعِدُ ٱلظَّـٰلِمُونَ بَعۡضُهُم بَعۡضًا إِلَّا غُرُورًا',
    'قل ارايتم شركاءكم الذين تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السماوات ام اتيناهم كتابا فهم على بينت منه بل ان يعد الظالمون بعضهم بعضا الا غرورا',
    'قُلۡ أَرَءَيۡتُمۡ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَرُونِى مَاذَا خَلَقُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَمۡ لَهُمۡ شِرۡ<rule class=ikhafa>كٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ أَمۡ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َهُمۡ عَلَىٰ بَيِّنَ<rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُۚ بَلۡ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َعِدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ بَعۡضُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضًا إِلَّا غُرُورًا ٤٠',
    40, 22, 5, 439, 380, 175, 'false'
  );
  
  -- Ayah 41 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3701,
    '۞ إِنَّ ٱللَّهَ یُمۡسِكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَىِٕن زَالَتَاۤ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدࣲ مِّنۢ بَعۡدِهِۦۤۚ إِنَّهُۥ كَانَ حَلِیمًا غَفُورࣰا',
    'ان الله يمسك السماوات والارض ان تزولا ولئن زالتا ان امسكهما من احد من بعده انه كان حليما غفورا',
    '۞إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُمۡسِكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َزُولَاۚ وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>َالَت<rule class=madda_obligatory_monfasel>َآ</rule> إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِ<rule class=madda_obligatory_monfasel>ۚۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ حَلِيمًا غَفُورًا ٤١',
    41, 22, 5, 439, 380, 176, 'false'
  );
  
  -- Ayah 42 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3702,
    'وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَىِٕن جَاۤءَهُمۡ نَذِیرࣱ لَّیَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَاۤءَهُمۡ نَذِیرࣱ مَّا زَادَهُمۡ إِلَّا نُفُورًا',
    'واقسموا بالله جهد ايمانهم لئن جاءهم نذير ليكونن اهدى من احدى الامم فلما جاءهم نذير ما زادهم الا نفورا',
    'وَأَ<rule class=qalaqah>قۡ</rule>سَمُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ جَهۡدَ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ لَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ نَذِي<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيَكُونُ<rule class=ghunnah>نّ</rule>َ أَهۡدَىٰ مِنۡ إِحۡدَى <rule class=ham_wasl>ٱ</rule>لۡأُمَمِۖ فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا زَادَهُمۡ إِلَّا نُفُورًا ٤٢',
    42, 22, 5, 439, 380, 176, 'false'
  );
  
  -- Ayah 43 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3703,
    'ٱسۡتِكۡبَارࣰا فِی ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّیِّىِٕۚ وَلَا یَحِیقُ ٱلۡمَكۡرُ ٱلسَّیِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ یَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِینَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِیلࣰاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِیلًا',
    'استكبارا في الارض ومكر السيئ ولا يحيق المكر السيئ الا باهله فهل ينظرون الا سنت الاولين فلن تجد لسنت الله تبديلا ولن تجد لسنت الله تحويلا',
    'ٱسۡتِكۡبَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَكۡرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّىِٕۚ وَلَا يَحِيقُ <rule class=ham_wasl>ٱ</rule>لۡمَكۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئُ إِلَّا بِأَهۡلِهِ<rule class=madda_normal>ۚۦ</rule> فَهَلۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلَّا سُ<rule class=ghunnah>نّ</rule>َتَ <rule class=ham_wasl>ٱ</rule>لۡأَوَّلِينَۚ فَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لِسُ<rule class=ghunnah>نّ</rule>َتِ <rule class=ham_wasl>ٱ</rule>للَّهِ تَ<rule class=qalaqah>بۡ</rule>دِيل<rule class=idgham_ghunnah>اًۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لِسُ<rule class=ghunnah>نّ</rule>َتِ <rule class=ham_wasl>ٱ</rule>للَّهِ تَحۡوِيلاً ٤٣',
    43, 22, 5, 439, 380, 176, 'false'
  );
  
  -- Ayah 44 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3704,
    'أَوَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡ وَكَانُوۤا۟ أَشَدَّ مِنۡهُمۡ قُوَّةࣰۚ وَمَا كَانَ ٱللَّهُ لِیُعۡجِزَهُۥ مِن شَیۡءࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَلَا فِی ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِیمࣰا قَدِیرࣰا',
    'اولم يسيروا في الارض فينظروا كيف كان عاقبة الذين من قبلهم وكانوا اشد منهم قوة وما كان الله ليعجزه من شيء في السماوات ولا في الارض انه كان عليما قديرا',
    'أَوَلَمۡ يَسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَيَ<rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ وَكَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَشَدَّ مِنۡهُمۡ قُوَّۚ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِيُعۡجِزَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَلَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ عَلِي<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ق</rule>َدِيرًا ٤٤',
    44, 22, 5, 439, 380, 176, 'false'
  );
  
  -- Ayah 45 Surah Faatir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    35,
    3705,
    'وَلَوۡ یُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَاۤبَّةࣲ وَلَـٰكِن یُؤَخِّرُهُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّىۖ فَإِذَا جَاۤءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِیرَۢا',
    'ولو يؤاخذ الله الناس بما كسبوا ما ترك على ظهرها من دابة ولكن يؤخرهم الى اجل مسمى فاذا جاء اجلهم فان الله كان بعباده بصيرا',
    'وَلَوۡ يُؤَاخِذُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ بِمَا كَسَبُو<rule class=slnt>اۡ</rule> مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤَخِّرُهُمۡ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=ikhafa>ًّىۖ</rule> <rule class=ikhafa>ف</rule>َإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَجَلُهُمۡ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ بِعِبَادِه<rule class=madda_normal>ِۦ</rule> بَصِيرَۢا ٤٥',
    45, 22, 5, 440, 380, 176, 'false'
  );
  

-- Surah Yaseen
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (36, 'سُورَةُ يسٓ', 'Yaseen', 'Yaseen', 'Meccan', 83);

  -- Ayah 1 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3706,
    'یسۤ',
    'يس',
    'ي<rule class=madda_necessary>سٓ</rule> ١',
    1, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 2 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3707,
    'وَٱلۡقُرۡءَانِ ٱلۡحَكِیمِ',
    'والقران الحكيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ٢',
    2, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 3 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3708,
    'إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِینَ',
    'انك لمن المرسلين',
    'إِ<rule class=ghunnah>نّ</rule>َكَ لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٣',
    3, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 4 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3709,
    'عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'على صراط مستقيم',
    'عَلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٤',
    4, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 5 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3710,
    'تَنزِیلَ ٱلۡعَزِیزِ ٱلرَّحِیمِ',
    'تنزيل العزيز الرحيم',
    'تَ<rule class=ikhafa>نز</rule>ِيلَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مِ ٥',
    5, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 6 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3711,
    'لِتُنذِرَ قَوۡمࣰا مَّاۤ أُنذِرَ ءَابَاۤؤُهُمۡ فَهُمۡ غَـٰفِلُونَ',
    'لتنذر قوما ما انذر اباؤهم فهم غافلون',
    'لِتُ<rule class=ikhafa>نذ</rule>ِرَ قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نذ</rule>ِرَ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُمۡ فَهُمۡ غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 7 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3712,
    'لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰۤ أَكۡثَرِهِمۡ فَهُمۡ لَا یُؤۡمِنُونَ',
    'لقد حق القول على اكثرهم فهم لا يؤمنون',
    'لَقَ<rule class=qalaqah>دۡ</rule> حَقَّ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَكۡثَرِهِمۡ فَهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 8 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3713,
    'إِنَّا جَعَلۡنَا فِیۤ أَعۡنَـٰقِهِمۡ أَغۡلَـٰلࣰا فَهِیَ إِلَى ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ',
    'انا جعلنا في اعناقهم اغلالا فهي الى الاذقان فهم مقمحون',
    'إِ<rule class=ghunnah>نّ</rule>َا جَعَلۡنَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡنَ<rule class=madda_normal>ـٰ</rule>قِهِمۡ أَغۡلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>َهِىَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡأَذۡقَانِ فَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>قۡ</rule>مَح<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 9 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3714,
    'وَجَعَلۡنَا مِنۢ بَیۡنِ أَیۡدِیهِمۡ سَدࣰّا وَمِنۡ خَلۡفِهِمۡ سَدࣰّا فَأَغۡشَیۡنَـٰهُمۡ فَهُمۡ لَا یُبۡصِرُونَ',
    'وجعلنا من بين ايديهم سدا ومن خلفهم سدا فاغشيناهم فهم لا يبصرون',
    'وَجَعَلۡنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ أَيۡدِيهِمۡ سَد<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َمِنۡ خَلۡفِهِمۡ سَد<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ف</rule>َأَغۡشَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فَهُمۡ لَا يُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 10 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3715,
    'وَسَوَاۤءٌ عَلَیۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا یُؤۡمِنُونَ',
    'وسواء عليهم اانذرتهم ام لم تنذرهم لا يؤمنون',
    'وَسَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ عَلَيۡهِمۡ ءَأَ<rule class=ikhafa>نذ</rule>َرۡتَهُمۡ أَمۡ لَمۡ تُ<rule class=ikhafa>نذ</rule>ِرۡهُمۡ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 11 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3716,
    'إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِیَ ٱلرَّحۡمَـٰنَ بِٱلۡغَیۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةࣲ وَأَجۡرࣲ كَرِیمٍ',
    'انما تنذر من اتبع الذكر وخشي الرحمن بالغيب فبشره بمغفرة واجر كريم',
    'إِ<rule class=ghunnah>نّ</rule>َمَا تُ<rule class=ikhafa>نذ</rule>ِرُ مَنِ <rule class=ham_wasl>ٱ</rule>تَّبَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَ وَخَشِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نَ بِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٍ ١١',
    11, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 12 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3717,
    'إِنَّا نَحۡنُ نُحۡیِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُوا۟ وَءَاثَـٰرَهُمۡۚ وَكُلَّ شَیۡءٍ أَحۡصَیۡنَـٰهُ فِیۤ إِمَامࣲ مُّبِینࣲ',
    'انا نحن نحيي الموتى ونكتب ما قدموا واثارهم وكل شيء احصيناه في امام مبين',
    'إِ<rule class=ghunnah>نّ</rule>َا نَحۡنُ نُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُو<rule class=slnt>اۡ</rule> وَءَاثَ<rule class=madda_normal>ـٰ</rule>رَهُمۡۚ وَكُلَّ شَىۡءٍ أَحۡصَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِمَا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١٢',
    12, 22, 5, 440, 381, 176, 'false'
  );
  
  -- Ayah 13 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3718,
    'وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَـٰبَ ٱلۡقَرۡیَةِ إِذۡ جَاۤءَهَا ٱلۡمُرۡسَلُونَ',
    'واضرب لهم مثلا اصحاب القرية اذ جاءها المرسلون',
    'وَ<rule class=ham_wasl>ٱ</rule>ضۡرِ<rule class=qalaqah>بۡ</rule> لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّثَلاً أَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَةِ إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهَا <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 14 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3719,
    'إِذۡ أَرۡسَلۡنَاۤ إِلَیۡهِمُ ٱثۡنَیۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثࣲ فَقَالُوۤا۟ إِنَّاۤ إِلَیۡكُم مُّرۡسَلُونَ',
    'اذ ارسلنا اليهم اثنين فكذبوهما فعززنا بثالث فقالوا انا اليكم مرسلون',
    'إِذۡ أَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>ثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِ<rule class=ikhafa>ثٍ</rule> <rule class=ikhafa>ف</rule>َقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّرۡسَل<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 15 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3720,
    'قَالُوا۟ مَاۤ أَنتُمۡ إِلَّا بَشَرࣱ مِّثۡلُنَا وَمَاۤ أَنزَلَ ٱلرَّحۡمَـٰنُ مِن شَیۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ',
    'قالوا ما انتم الا بشر مثلنا وما انزل الرحمن من شيء ان انتم الا تكذبون',
    'قَالُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ إِلَّا بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُنَا وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ إِنۡ أَ<rule class=ikhafa>نت</rule>ُمۡ إِلَّا تَكۡذِب<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 16 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3721,
    'قَالُوا۟ رَبُّنَا یَعۡلَمُ إِنَّاۤ إِلَیۡكُمۡ لَمُرۡسَلُونَ',
    'قالوا ربنا يعلم انا اليكم لمرسلون',
    'قَالُو<rule class=slnt>اۡ</rule> رَبُّنَا يَعۡلَمُ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكُمۡ لَمُرۡسَل<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 17 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3722,
    'وَمَا عَلَیۡنَاۤ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ',
    'وما علينا الا البلاغ المبين',
    'وَمَا عَلَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ١٧',
    17, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 18 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3723,
    'قَالُوۤا۟ إِنَّا تَطَیَّرۡنَا بِكُمۡۖ لَىِٕن لَّمۡ تَنتَهُوا۟ لَنَرۡجُمَنَّكُمۡ وَلَیَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِیمࣱ',
    'قالوا انا تطيرنا بكم لئن لم تنتهوا لنرجمنكم وليمسنكم منا عذاب اليم',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا تَطَيَّرۡنَا بِكُمۡۖ لَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَ<rule class=ikhafa>نت</rule>َهُو<rule class=slnt>اۡ</rule> لَنَرۡجُمَ<rule class=ghunnah>نّ</rule>َكُمۡ وَلَيَمَسَّ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١٨',
    18, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 19 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3724,
    'قَالُوا۟ طَـٰۤىِٕرُكُم مَّعَكُمۡ أَىِٕن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمࣱ مُّسۡرِفُونَ',
    'قالوا طائركم معكم ائن ذكرتم بل انتم قوم مسرفون',
    'قَالُو<rule class=slnt>اۡ</rule> طَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّعَكُمۡۚ أَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُكِّرۡت<rule class=ikhafa_shafawi>ُمۚ</rule> <rule class=ikhafa_shafawi>ب</rule>َلۡ أَ<rule class=ikhafa>نت</rule>ُمۡ قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡرِف<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 20 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3725,
    'وَجَاۤءَ مِنۡ أَقۡصَا ٱلۡمَدِینَةِ رَجُلࣱ یَسۡعَىٰ قَالَ یَـٰقَوۡمِ ٱتَّبِعُوا۟ ٱلۡمُرۡسَلِینَ',
    'وجاء من اقصى المدينة رجل يسعى قال يا قوم اتبعوا المرسلين',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مِنۡ أَ<rule class=qalaqah>قۡ</rule>صَا <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ رَجُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡعَىٰ قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>تَّبِعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 21 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3726,
    'ٱتَّبِعُوا۟ مَن لَّا یَسۡـَٔلُكُمۡ أَجۡرࣰا وَهُم مُّهۡتَدُونَ',
    'اتبعوا من لا يسالكم اجرا وهم مهتدون',
    'ٱتَّبِعُو<rule class=slnt>اۡ</rule> م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَسۡــَٔلُكُمۡ أَ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 22 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3727,
    'وَمَا لِیَ لَاۤ أَعۡبُدُ ٱلَّذِی فَطَرَنِی وَإِلَیۡهِ تُرۡجَعُونَ',
    'وما لي لا اعبد الذي فطرني واليه ترجعون',
    'وَمَا لِىَ ل<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡبُدُ <rule class=ham_wasl>ٱ</rule>لَّذِى فَطَرَنِى وَإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 23 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3728,
    'ءَأَتَّخِذُ مِن دُونِهِۦۤ ءَالِهَةً إِن یُرِدۡنِ ٱلرَّحۡمَـٰنُ بِضُرࣲّ لَّا تُغۡنِ عَنِّی شَفَـٰعَتُهُمۡ شَیۡـࣰٔا وَلَا یُنقِذُونِ',
    'ااتخذ من دونه الهة ان يردن الرحمن بضر لا تغن عني شفاعتهم شيئا ولا ينقذون',
    'ءَأَتَّخِذُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> ءَالِهَةً إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُرِ<rule class=qalaqah>دۡ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ بِضُ<rule class=idgham_wo_ghunnah>رٍّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تُغۡنِ عَ<rule class=ghunnah>نّ</rule>ِى شَفَ<rule class=madda_normal>ـٰ</rule>عَتُهُمۡ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يُ<rule class=ikhafa>نق</rule>ِذ<rule class=madda_permissible>ُو</rule>نِ ٢٣',
    23, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 24 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3729,
    'إِنِّیۤ إِذࣰا لَّفِی ضَلَـٰلࣲ مُّبِینٍ',
    'اني اذا لفي ضلال مبين',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّفِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٢٤',
    24, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 25 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3730,
    'إِنِّیۤ ءَامَنتُ بِرَبِّكُمۡ فَٱسۡمَعُونِ',
    'اني امنت بربكم فاسمعون',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَامَ<rule class=ikhafa>نت</rule>ُ بِرَبِّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡمَع<rule class=madda_permissible>ُو</rule>نِ ٢٥',
    25, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 26 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3731,
    'قِیلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ یَـٰلَیۡتَ قَوۡمِی یَعۡلَمُونَ',
    'قيل ادخل الجنة قال يا ليت قومي يعلمون',
    'قِيلَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَۖ قَالَ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَ قَوۡمِى يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 27 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3732,
    'بِمَا غَفَرَ لِی رَبِّی وَجَعَلَنِی مِنَ ٱلۡمُكۡرَمِینَ',
    'بما غفر لي ربي وجعلني من المكرمين',
    'بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُكۡرَم<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 22, 5, 441, 382, 176, 'false'
  );
  
  -- Ayah 28 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3733,
    '۞ وَمَاۤ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندࣲ مِّنَ ٱلسَّمَاۤءِ وَمَا كُنَّا مُنزِلِینَ',
    'وما انزلنا على قومه من بعده من جند من السماء وما كنا منزلين',
    '۞وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَىٰ قَوۡمِه<rule class=madda_normal>ِۦ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>ُن<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَمَا كُ<rule class=ghunnah>نّ</rule>َا مُ<rule class=ikhafa>نز</rule>ِل<rule class=madda_permissible>ِي</rule>نَ ٢٨',
    28, 23, 5, 442, 382, 177, 'false'
  );
  
  -- Ayah 29 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3734,
    'إِن كَانَتۡ إِلَّا صَیۡحَةࣰ وَ ٰ⁠حِدَةࣰ فَإِذَا هُمۡ خَـٰمِدُونَ',
    'ان كانت الا صيحة واحدة فاذا هم خامدون',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَتۡ إِلَّا صَيۡحَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َإِذَا هُمۡ خَ<rule class=madda_normal>ـٰ</rule>مِد<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 23, 5, 442, 382, 177, 'false'
  );
  
  -- Ayah 30 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3735,
    'یَـٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا یَأۡتِیهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'يا حسرة على العباد ما ياتيهم من رسول الا كانوا به يستهزئون',
    'يَ<rule class=madda_normal>ـٰ</rule>حَسۡرَةً عَلَى <rule class=ham_wasl>ٱ</rule>لۡعِبَادِ‌ۚ مَا يَأۡتِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولٍ إِلَّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 23, 5, 442, 382, 177, 'false'
  );
  
  -- Ayah 31 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3736,
    'أَلَمۡ یَرَوۡا۟ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ أَنَّهُمۡ إِلَیۡهِمۡ لَا یَرۡجِعُونَ',
    'الم يروا كم اهلكنا قبلهم من القرون انهم اليهم لا يرجعون',
    'أَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> كَمۡ أَهۡلَكۡنَا قَ<rule class=qalaqah>بۡ</rule>لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقُرُونِ أَ<rule class=ghunnah>نّ</rule>َهُمۡ إِلَيۡهِمۡ لَا يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 23, 5, 442, 382, 177, 'false'
  );
  
  -- Ayah 32 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3737,
    'وَإِن كُلࣱّ لَّمَّا جَمِیعࣱ لَّدَیۡنَا مُحۡضَرُونَ',
    'وان كل لما جميع لدينا محضرون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=idgham_wo_ghunnah>لٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ghunnah>مّ</rule>َا جَمِي<rule class=idgham_wo_ghunnah>عٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدَيۡنَا مُحۡضَر<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 23, 5, 442, 382, 177, 'false'
  );
  
  -- Ayah 33 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3738,
    'وَءَایَةࣱ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَیۡتَةُ أَحۡیَیۡنَـٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبࣰّا فَمِنۡهُ یَأۡكُلُونَ',
    'واية لهم الارض الميتة احييناها واخرجنا منها حبا فمنه ياكلون',
    'وَءَايَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ <rule class=ham_wasl>ٱ</rule>لۡمَيۡتَةُ أَحۡيَيۡنَ<rule class=madda_normal>ـٰ</rule>هَا وَأَخۡرَ<rule class=qalaqah>جۡ</rule>نَا مِنۡهَا حَب<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ف</rule>َمِنۡهُ يَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 23, 5, 442, 383, 177, 'false'
  );
  
  -- Ayah 34 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3739,
    'وَجَعَلۡنَا فِیهَا جَنَّـٰتࣲ مِّن نَّخِیلࣲ وَأَعۡنَـٰبࣲ وَفَجَّرۡنَا فِیهَا مِنَ ٱلۡعُیُونِ',
    'وجعلنا فيها جنات من نخيل واعناب وفجرنا فيها من العيون',
    'وَجَعَلۡنَا فِيهَا جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّخِي<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَعۡنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َفَجَّرۡنَا فِيهَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡعُي<rule class=madda_permissible>ُو</rule>نِ ٣٤',
    34, 23, 5, 442, 383, 177, 'false'
  );
  
  -- Ayah 35 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3740,
    'لِیَأۡكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتۡهُ أَیۡدِیهِمۡۚ أَفَلَا یَشۡكُرُونَ',
    'لياكلوا من ثمره وما عملته ايديهم افلا يشكرون',
    'لِيَأۡكُلُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َمَرِه<rule class=madda_normal>ِۦ</rule> وَمَا عَمِلَتۡهُ أَيۡدِيهِمۡ‌ۖ أَفَلَا يَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 23, 5, 442, 383, 177, 'false'
  );
  
  -- Ayah 36 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3741,
    'سُبۡحَـٰنَ ٱلَّذِی خَلَقَ ٱلۡأَزۡوَ ٰ⁠جَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا یَعۡلَمُونَ',
    'سبحان الذي خلق الازواج كلها مما تنبت الارض ومن انفسهم ومما لا يعلمون',
    'سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule>لۡأَزۡو<rule class=madda_normal>ٰ</rule>جَ كُلَّهَا مِ<rule class=ghunnah>مّ</rule>َا تُ<rule class=iqlab>نۢب</rule>ِتُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَمِنۡ أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ وَمِ<rule class=ghunnah>مّ</rule>َا لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 23, 5, 442, 383, 177, 'false'
  );
  
  -- Ayah 37 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3742,
    'وَءَایَةࣱ لَّهُمُ ٱلَّیۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ',
    'واية لهم الليل نسلخ منه النهار فاذا هم مظلمون',
    'وَءَايَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمُ <rule class=ham_wasl>ٱ</rule>لَّيۡلُ نَسۡلَخُ مِنۡهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ فَإِذَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّظۡلِم<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 23, 5, 442, 383, 177, 'false'
  );
  
  -- Ayah 38 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3743,
    'وَٱلشَّمۡسُ تَجۡرِی لِمُسۡتَقَرࣲّ لَّهَاۚ ذَ ٰ⁠لِكَ تَقۡدِیرُ ٱلۡعَزِیزِ ٱلۡعَلِیمِ',
    'والشمس تجري لمستقر لها ذلك تقدير العزيز العليم',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسُ تَ<rule class=qalaqah>جۡ</rule>رِى لِمُسۡتَقَ<rule class=idgham_wo_ghunnah>رٍّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهَا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ تَ<rule class=qalaqah>قۡ</rule>دِيرُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مِ ٣٨',
    38, 23, 5, 442, 383, 177, 'false'
  );
  
  -- Ayah 39 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3744,
    'وَٱلۡقَمَرَ قَدَّرۡنَـٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِیمِ',
    'والقمر قدرناه منازل حتى عاد كالعرجون القديم',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ قَدَّرۡنَ<rule class=madda_normal>ـٰ</rule>هُ مَنَازِلَ حَتَّىٰ عَادَ كَ<rule class=ham_wasl>ٱ</rule>لۡعُرۡجُونِ <rule class=ham_wasl>ٱ</rule>لۡقَد<rule class=madda_permissible>ِي</rule>مِ ٣٩',
    39, 23, 5, 442, 383, 177, 'false'
  );
  
  -- Ayah 40 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3745,
    'لَا ٱلشَّمۡسُ یَنۢبَغِی لَهَاۤ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّیۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلࣱّ فِی فَلَكࣲ یَسۡبَحُونَ',
    'لا الشمس ينبغي لها ان تدرك القمر ولا الليل سابق النهار وكل في فلك يسبحون',
    'لَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسُ يَ<rule class=iqlab>نۢب</rule>َغِى لَه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>دۡ</rule>رِكَ <rule class=ham_wasl>ٱ</rule>لۡقَمَرَ وَلَا <rule class=ham_wasl>ٱ</rule>لَّيۡلُ سَابِقُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ‌ۚ وَكُ<rule class=ikhafa>لٌّ</rule> <rule class=ikhafa>ف</rule>ِى فَلَ<rule class=idgham_ghunnah>كٍ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡبَح<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 23, 5, 442, 383, 177, 'false'
  );
  
  -- Ayah 41 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3746,
    'وَءَایَةࣱ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّیَّتَهُمۡ فِی ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ',
    'واية لهم انا حملنا ذريتهم في الفلك المشحون',
    'وَءَايَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ أَ<rule class=ghunnah>نّ</rule>َا حَمَلۡنَا ذُرِّيَّتَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ <rule class=ham_wasl>ٱ</rule>لۡمَشۡح<rule class=madda_permissible>ُو</rule>نِ ٤١',
    41, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 42 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3747,
    'وَخَلَقۡنَا لَهُم مِّن مِّثۡلِهِۦ مَا یَرۡكَبُونَ',
    'وخلقنا لهم من مثله ما يركبون',
    'وَخَلَ<rule class=qalaqah>قۡ</rule>نَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلِه<rule class=madda_normal>ِۦ</rule> مَا يَرۡكَب<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 43 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3748,
    'وَإِن نَّشَأۡ نُغۡرِقۡهُمۡ فَلَا صَرِیخَ لَهُمۡ وَلَا هُمۡ یُنقَذُونَ',
    'وان نشا نغرقهم فلا صريخ لهم ولا هم ينقذون',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّشَأۡ نُغۡرِ<rule class=qalaqah>قۡ</rule>هُمۡ فَلَا صَرِيخَ لَهُمۡ وَلَا هُمۡ يُ<rule class=ikhafa>نق</rule>َذ<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 44 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3749,
    'إِلَّا رَحۡمَةࣰ مِّنَّا وَمَتَـٰعًا إِلَىٰ حِینࣲ',
    'الا رحمة منا ومتاعا الى حين',
    'إِلَّا رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا وَمَتَ<rule class=madda_normal>ـٰ</rule>عًا إِلَىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٤٤',
    44, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 45 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3750,
    'وَإِذَا قِیلَ لَهُمُ ٱتَّقُوا۟ مَا بَیۡنَ أَیۡدِیكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَمُونَ',
    'واذا قيل لهم اتقوا ما بين ايديكم وما خلفكم لعلكم ترحمون',
    'وَإِذَا قِيلَ لَهُمُ <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> مَا بَيۡنَ أَيۡدِيكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَم<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 46 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3751,
    'وَمَا تَأۡتِیهِم مِّنۡ ءَایَةࣲ مِّنۡ ءَایَـٰتِ رَبِّهِمۡ إِلَّا كَانُوا۟ عَنۡهَا مُعۡرِضِینَ',
    'وما تاتيهم من اية من ايات ربهم الا كانوا عنها معرضين',
    'وَمَا تَأۡتِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ ءَايَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ إِلَّا كَانُو<rule class=slnt>اۡ</rule> عَنۡهَا مُعۡرِض<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 47 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3752,
    'وَإِذَا قِیلَ لَهُمۡ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوۤا۟ أَنُطۡعِمُ مَن لَّوۡ یَشَاۤءُ ٱللَّهُ أَطۡعَمَهُۥۤ إِنۡ أَنتُمۡ إِلَّا فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'واذا قيل لهم انفقوا مما رزقكم الله قال الذين كفروا للذين امنوا انطعم من لو يشاء الله اطعمه ان انتم الا في ضلال مبين',
    'وَإِذَا قِيلَ لَهُمۡ أَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا رَزَقَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لِلَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَنُ<rule class=qalaqah>طۡ</rule>عِمُ م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّوۡ يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=qalaqah>طۡ</rule>عَمَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِنۡ أَ<rule class=ikhafa>نت</rule>ُمۡ إِلَّا فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٤٧',
    47, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 48 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3753,
    'وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ويقولون متى هذا الوعد ان كنتم صادقين',
    'وَيَقُولُونَ مَتَىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡوَعۡدُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٤٨',
    48, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 49 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3754,
    'مَا یَنظُرُونَ إِلَّا صَیۡحَةࣰ وَ ٰ⁠حِدَةࣰ تَأۡخُذُهُمۡ وَهُمۡ یَخِصِّمُونَ',
    'ما ينظرون الا صيحة واحدة تاخذهم وهم يخصمون',
    'مَا يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلَّا صَيۡحَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َأۡخُذُهُمۡ وَهُمۡ يَخِصِّم<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 50 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3755,
    'فَلَا یَسۡتَطِیعُونَ تَوۡصِیَةࣰ وَلَاۤ إِلَىٰۤ أَهۡلِهِمۡ یَرۡجِعُونَ',
    'فلا يستطيعون توصية ولا الى اهلهم يرجعون',
    'فَلَا يَسۡتَطِيعُونَ تَوۡصِيَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِهِمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 23, 5, 443, 383, 177, 'false'
  );
  
  -- Ayah 51 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3756,
    'وَنُفِخَ فِی ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ یَنسِلُونَ',
    'ونفخ في الصور فاذا هم من الاجداث الى ربهم ينسلون',
    'وَنُفِخَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ فَإِذَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>جۡ</rule>دَاثِ إِلَىٰ رَبِّهِمۡ يَ<rule class=ikhafa>نس</rule>ِل<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 23, 5, 443, 384, 177, 'false'
  );
  
  -- Ayah 52 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3757,
    'قَالُوا۟ یَـٰوَیۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَـٰذَا مَا وَعَدَ ٱلرَّحۡمَـٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ',
    'قالوا يا ويلنا من بعثنا من مرقدنا هذا ما وعد الرحمن وصدق المرسلون',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَنَا م<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>َعَثَنَا م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّرۡقَدِنَاۜ‌ۗ هَ<rule class=madda_normal>ـٰ</rule>ذَا مَا وَعَدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ وَصَدَقَ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 23, 5, 443, 384, 177, 'false'
  );
  
  -- Ayah 53 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3758,
    'إِن كَانَتۡ إِلَّا صَیۡحَةࣰ وَ ٰ⁠حِدَةࣰ فَإِذَا هُمۡ جَمِیعࣱ لَّدَیۡنَا مُحۡضَرُونَ',
    'ان كانت الا صيحة واحدة فاذا هم جميع لدينا محضرون',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَتۡ إِلَّا صَيۡحَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َإِذَا هُمۡ جَمِي<rule class=idgham_wo_ghunnah>عٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّدَيۡنَا مُحۡضَر<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 23, 5, 443, 384, 177, 'false'
  );
  
  -- Ayah 54 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3759,
    'فَٱلۡیَوۡمَ لَا تُظۡلَمُ نَفۡسࣱ شَیۡـࣰٔا وَلَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ',
    'فاليوم لا تظلم نفس شيئا ولا تجزون الا ما كنتم تعملون',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ لَا تُظۡلَمُ نَفۡ<rule class=ikhafa>سٌ</rule> <rule class=ikhafa>ش</rule>َيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا تُ<rule class=qalaqah>جۡ</rule>زَوۡنَ إِلَّا مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 23, 5, 443, 384, 177, 'false'
  );
  
  -- Ayah 55 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3760,
    'إِنَّ أَصۡحَـٰبَ ٱلۡجَنَّةِ ٱلۡیَوۡمَ فِی شُغُلࣲ فَـٰكِهُونَ',
    'ان اصحاب الجنة اليوم في شغل فاكهون',
    'إِ<rule class=ghunnah>نّ</rule>َ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ فِى شُغُ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=madda_normal>ـٰ</rule>كِه<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 23, 5, 444, 384, 177, 'false'
  );
  
  -- Ayah 56 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3761,
    'هُمۡ وَأَزۡوَ ٰ⁠جُهُمۡ فِی ظِلَـٰلٍ عَلَى ٱلۡأَرَاۤىِٕكِ مُتَّكِـُٔونَ',
    'هم وازواجهم في ظلال على الارائك متكئون',
    'هُمۡ وَأَزۡو<rule class=madda_normal>ٰ</rule>جُهُمۡ فِى ظِلَ<rule class=madda_normal>ـٰ</rule>لٍ عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكِ مُتَّكِــٔ<rule class=madda_permissible>ُو</rule>نَ ٥٦',
    56, 23, 5, 444, 384, 177, 'false'
  );
  
  -- Ayah 57 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3762,
    'لَهُمۡ فِیهَا فَـٰكِهَةࣱ وَلَهُم مَّا یَدَّعُونَ',
    'لهم فيها فاكهة ولهم ما يدعون',
    'لَهُمۡ فِيهَا فَ<rule class=madda_normal>ـٰ</rule>كِهَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَدَّع<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 23, 5, 444, 384, 177, 'false'
  );
  
  -- Ayah 58 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3763,
    'سَلَـٰمࣱ قَوۡلࣰا مِّن رَّبࣲّ رَّحِیمࣲ',
    'سلام قولا من رب رحيم',
    'سَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ق</rule>َوۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّ<rule class=idgham_wo_ghunnah>بٍّ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٍ ٥٨',
    58, 23, 5, 444, 384, 177, 'false'
  );
  
  -- Ayah 59 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3764,
    'وَٱمۡتَـٰزُوا۟ ٱلۡیَوۡمَ أَیُّهَا ٱلۡمُجۡرِمُونَ',
    'وامتازوا اليوم ايها المجرمون',
    'وَ<rule class=ham_wasl>ٱ</rule>مۡتَ<rule class=madda_normal>ـٰ</rule>زُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 23, 5, 444, 384, 177, 'false'
  );
  
  -- Ayah 60 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3765,
    '۞ أَلَمۡ أَعۡهَدۡ إِلَیۡكُمۡ یَـٰبَنِیۤ ءَادَمَ أَن لَّا تَعۡبُدُوا۟ ٱلشَّیۡطَـٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینࣱ',
    'الم اعهد اليكم يا بني ادم ان لا تعبدوا الشيطان انه لكم عدو مبين',
    '۞أَلَمۡ أَعۡهَ<rule class=qalaqah>دۡ</rule> إِلَيۡكُمۡ يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَادَمَ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَعۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَكُمۡ عَدُ<rule class=idgham_ghunnah>وٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٦٠',
    60, 23, 5, 444, 384, 178, 'false'
  );
  
  -- Ayah 61 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3766,
    'وَأَنِ ٱعۡبُدُونِیۚ هَـٰذَا صِرَ ٰ⁠طࣱ مُّسۡتَقِیمࣱ',
    'وان اعبدوني هذا صراط مستقيم',
    'وَأَنِ <rule class=ham_wasl>ٱ</rule>عۡبُدُونِى‌ۚ هَ<rule class=madda_normal>ـٰ</rule>ذَا صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٌ ٦١',
    61, 23, 5, 444, 384, 178, 'false'
  );
  
  -- Ayah 62 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3767,
    'وَلَقَدۡ أَضَلَّ مِنكُمۡ جِبِلࣰّا كَثِیرًاۖ أَفَلَمۡ تَكُونُوا۟ تَعۡقِلُونَ',
    'ولقد اضل منكم جبلا كثيرا افلم تكونوا تعقلون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَضَلَّ مِ<rule class=ikhafa>نك</rule>ُمۡ جِبِل<rule class=ikhafa>اًّ</rule> <rule class=ikhafa>ك</rule>َثِيرًا‌ۖ أَفَلَمۡ تَكُونُو<rule class=slnt>اۡ</rule> تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 23, 5, 444, 384, 178, 'false'
  );
  
  -- Ayah 63 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3768,
    'هَـٰذِهِۦ جَهَنَّمُ ٱلَّتِی كُنتُمۡ تُوعَدُونَ',
    'هذه جهنم التي كنتم توعدون',
    'هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> جَهَ<rule class=ghunnah>نّ</rule>َمُ <rule class=ham_wasl>ٱ</rule>لَّتِى كُ<rule class=ikhafa>نت</rule>ُمۡ تُوعَد<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 23, 5, 444, 384, 178, 'false'
  );
  
  -- Ayah 64 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3769,
    'ٱصۡلَوۡهَا ٱلۡیَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ',
    'اصلوها اليوم بما كنتم تكفرون',
    'ٱصۡلَوۡهَا <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 23, 5, 444, 384, 178, 'false'
  );
  
  -- Ayah 65 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3770,
    'ٱلۡیَوۡمَ نَخۡتِمُ عَلَىٰۤ أَفۡوَ ٰ⁠هِهِمۡ وَتُكَلِّمُنَاۤ أَیۡدِیهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُوا۟ یَكۡسِبُونَ',
    'اليوم نختم على افواههم وتكلمنا ايديهم وتشهد ارجلهم بما كانوا يكسبون',
    'ٱلۡيَوۡمَ نَخۡتِمُ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ وَتُكَلِّمُن<rule class=madda_obligatory_monfasel>َآ</rule> أَيۡدِيهِمۡ وَتَشۡهَدُ أَرۡجُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٦٥',
    65, 23, 5, 444, 384, 178, 'false'
  );
  
  -- Ayah 66 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3771,
    'وَلَوۡ نَشَاۤءُ لَطَمَسۡنَا عَلَىٰۤ أَعۡیُنِهِمۡ فَٱسۡتَبَقُوا۟ ٱلصِّرَ ٰ⁠طَ فَأَنَّىٰ یُبۡصِرُونَ',
    'ولو نشاء لطمسنا على اعينهم فاستبقوا الصراط فانى يبصرون',
    'وَلَوۡ نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لَطَمَسۡنَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَعۡيُنِهِمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَبَقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّر<rule class=madda_normal>ٰ</rule>طَ فَأَ<rule class=ghunnah>نّ</rule>َىٰ يُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 23, 5, 444, 384, 178, 'false'
  );
  
  -- Ayah 67 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3772,
    'وَلَوۡ نَشَاۤءُ لَمَسَخۡنَـٰهُمۡ عَلَىٰ مَكَانَتِهِمۡ فَمَا ٱسۡتَطَـٰعُوا۟ مُضِیࣰّا وَلَا یَرۡجِعُونَ',
    'ولو نشاء لمسخناهم على مكانتهم فما استطاعوا مضيا ولا يرجعون',
    'وَلَوۡ نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لَمَسَخۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ عَلَىٰ مَكَانَتِهِمۡ فَمَا <rule class=ham_wasl>ٱ</rule>سۡتَطَ<rule class=madda_normal>ـٰ</rule>عُو<rule class=slnt>اۡ</rule> مُضِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 23, 5, 444, 384, 178, 'false'
  );
  
  -- Ayah 68 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3773,
    'وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِی ٱلۡخَلۡقِۚ أَفَلَا یَعۡقِلُونَ',
    'ومن نعمره ننكسه في الخلق افلا يعقلون',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّعَ<rule class=ghunnah>مّ</rule>ِرۡهُ نُنَكِّسۡهُ فِى <rule class=ham_wasl>ٱ</rule>لۡخَلۡقِ‌ۖ أَفَلَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 23, 5, 444, 385, 178, 'false'
  );
  
  -- Ayah 69 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3774,
    'وَمَا عَلَّمۡنَـٰهُ ٱلشِّعۡرَ وَمَا یَنۢبَغِی لَهُۥۤۚ إِنۡ هُوَ إِلَّا ذِكۡرࣱ وَقُرۡءَانࣱ مُّبِینࣱ',
    'وما علمناه الشعر وما ينبغي له ان هو الا ذكر وقران مبين',
    'وَمَا عَلَّمۡنَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شِّعۡرَ وَمَا يَ<rule class=iqlab>نۢب</rule>َغِى لَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِنۡ هُوَ إِلَّا ذِكۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َقُرۡءَا<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٦٩',
    69, 23, 5, 444, 385, 178, 'false'
  );
  
  -- Ayah 70 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3775,
    'لِّیُنذِرَ مَن كَانَ حَیࣰّا وَیَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَـٰفِرِینَ',
    'لينذر من كان حيا ويحق القول على الكافرين',
    'لِّيُ<rule class=ikhafa>نذ</rule>ِرَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ حَي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َيَحِقَّ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٧٠',
    70, 23, 5, 444, 385, 178, 'false'
  );
  
  -- Ayah 71 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3776,
    'أَوَلَمۡ یَرَوۡا۟ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَیۡدِینَاۤ أَنۡعَـٰمࣰا فَهُمۡ لَهَا مَـٰلِكُونَ',
    'اولم يروا انا خلقنا لهم مما عملت ايدينا انعاما فهم لها مالكون',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>نَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا عَمِلَتۡ أَيۡدِين<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡعَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َهُمۡ لَهَا مَ<rule class=madda_normal>ـٰ</rule>لِك<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 72 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3777,
    'وَذَلَّلۡنَـٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا یَأۡكُلُونَ',
    'وذللناها لهم فمنها ركوبهم ومنها ياكلون',
    'وَذَلَّلۡنَ<rule class=madda_normal>ـٰ</rule>هَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا يَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 73 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3778,
    'وَلَهُمۡ فِیهَا مَنَـٰفِعُ وَمَشَارِبُۚ أَفَلَا یَشۡكُرُونَ',
    'ولهم فيها منافع ومشارب افلا يشكرون',
    'وَلَهُمۡ فِيهَا مَنَ<rule class=madda_normal>ـٰ</rule>فِعُ وَمَشَارِبُ‌ۖ أَفَلَا يَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 74 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3779,
    'وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةࣰ لَّعَلَّهُمۡ یُنصَرُونَ',
    'واتخذوا من دون الله الهة لعلهم ينصرون',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ ءَالِهَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّهُمۡ يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٧٤',
    74, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 75 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3780,
    'لَا یَسۡتَطِیعُونَ نَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُندࣱ مُّحۡضَرُونَ',
    'لا يستطيعون نصرهم وهم لهم جند محضرون',
    'لَا يَسۡتَطِيعُونَ نَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُن<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّحۡضَر<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 76 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3781,
    'فَلَا یَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا یُسِرُّونَ وَمَا یُعۡلِنُونَ',
    'فلا يحزنك قولهم انا نعلم ما يسرون وما يعلنون',
    'فَلَا يَحۡزُ<rule class=ikhafa>نك</rule>َ قَوۡلُهُمۡ‌ۘ إِ<rule class=ghunnah>نّ</rule>َا نَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِن<rule class=madda_permissible>ُو</rule>نَ ٧٦',
    76, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 77 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3782,
    'أَوَلَمۡ یَرَ ٱلۡإِنسَـٰنُ أَنَّا خَلَقۡنَـٰهُ مِن نُّطۡفَةࣲ فَإِذَا هُوَ خَصِیمࣱ مُّبِینࣱ',
    'اولم ير الانسان انا خلقناه من نطفة فاذا هو خصيم مبين',
    'أَوَلَمۡ يَرَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ أَ<rule class=ghunnah>نّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّ<rule class=qalaqah>طۡ</rule>فَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َإِذَا هُوَ خَصِي<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٧٧',
    77, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 78 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3783,
    'وَضَرَبَ لَنَا مَثَلࣰا وَنَسِیَ خَلۡقَهُۥۖ قَالَ مَن یُحۡیِ ٱلۡعِظَـٰمَ وَهِیَ رَمِیمࣱ',
    'وضرب لنا مثلا ونسي خلقه قال من يحيي العظام وهي رميم',
    'وَضَرَبَ لَنَا مَثَل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َنَسِىَ خَلۡقَهُ<rule class=madda_normal>ۥ</rule>‌ۖ قَالَ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡعِظَ<rule class=madda_normal>ـٰ</rule>مَ وَهِىَ رَم<rule class=madda_permissible>ِي</rule>مٌ ٧٨',
    78, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 79 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3784,
    'قُلۡ یُحۡیِیهَا ٱلَّذِیۤ أَنشَأَهَاۤ أَوَّلَ مَرَّةࣲۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِیمٌ',
    'قل يحييها الذي انشاها اول مرة وهو بكل خلق عليم',
    'قُلۡ يُحۡيِيهَا <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نش</rule>َأَه<rule class=madda_obligatory_monfasel>َآ</rule> أَوَّلَ مَرَّ<rule class=idgham_ghunnah>ةٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ بِكُلِّ خَلۡقٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٧٩',
    79, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 80 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3785,
    'ٱلَّذِی جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارࣰا فَإِذَاۤ أَنتُم مِّنۡهُ تُوقِدُونَ',
    'الذي جعل لكم من الشجر الاخضر نارا فاذا انتم منه توقدون',
    'ٱلَّذِى جَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرِ <rule class=ham_wasl>ٱ</rule>لۡأَخۡضَرِ نَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ تُوقِد<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 81 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3786,
    'أَوَلَیۡسَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِقَـٰدِرٍ عَلَىٰۤ أَن یَخۡلُقَ مِثۡلَهُمۚ بَلَىٰ وَهُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِیمُ',
    'اوليس الذي خلق السماوات والارض بقادر على ان يخلق مثلهم بلى وهو الخلاق العليم',
    'أَوَلَيۡسَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِقَ<rule class=madda_normal>ـٰ</rule>دِرٍ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡلُقَ مِثۡلَه<rule class=ikhafa_shafawi>ُم‌ۚ</rule> <rule class=ikhafa_shafawi>ب</rule>َلَىٰ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡخَلَّ<rule class=madda_normal>ـٰ</rule>قُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٨١',
    81, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 82 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3787,
    'إِنَّمَاۤ أَمۡرُهُۥۤ إِذَاۤ أَرَادَ شَیۡـًٔا أَن یَقُولَ لَهُۥ كُن فَیَكُونُ',
    'انما امره اذا اراد شيئا ان يقول له كن فيكون',
    'إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡرُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَرَادَ شَيۡــًٔا أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولَ لَهُ<rule class=madda_normal>ۥ</rule> كُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َيَك<rule class=madda_permissible>ُو</rule>نُ ٨٢',
    82, 23, 5, 445, 385, 178, 'false'
  );
  
  -- Ayah 83 Surah Yaseen
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    36,
    3788,
    'فَسُبۡحَـٰنَ ٱلَّذِی بِیَدِهِۦ مَلَكُوتُ كُلِّ شَیۡءࣲ وَإِلَیۡهِ تُرۡجَعُونَ',
    'فسبحان الذي بيده ملكوت كل شيء واليه ترجعون',
    'فَسُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>لَّذِى بِيَدِه<rule class=madda_normal>ِۦ</rule> مَلَكُوتُ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٨٣',
    83, 23, 5, 445, 385, 178, 'false'
  );
  

-- Surah As-Saaffaat
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (37, 'سُورَةُ الصَّافَّاتِ', 'As-Saaffaat', 'Those drawn up in Ranks', 'Meccan', 182);

  -- Ayah 1 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3789,
    'وَٱلصَّـٰۤفَّـٰتِ صَفࣰّا',
    'والصافات صفا',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_necessary>ـٰٓ</rule>فَّ<rule class=madda_normal>ـٰ</rule>تِ صَفًّا ١',
    1, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 2 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3790,
    'فَٱلزَّ ٰ⁠جِرَ ٰ⁠تِ زَجۡرࣰا',
    'فالزاجرات زجرا',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زّ<rule class=madda_normal>ٰ</rule>جِر<rule class=madda_normal>ٰ</rule>تِ زَ<rule class=qalaqah>جۡ</rule>رًا ٢',
    2, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 3 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3791,
    'فَٱلتَّـٰلِیَـٰتِ ذِكۡرًا',
    'فالتاليات ذكرا',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=madda_normal>ـٰ</rule>لِيَ<rule class=madda_normal>ـٰ</rule>تِ ذِكۡرًا ٣',
    3, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 4 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3792,
    'إِنَّ إِلَـٰهَكُمۡ لَوَ ٰ⁠حِدࣱ',
    'ان الهكم لواحد',
    'إِ<rule class=ghunnah>نّ</rule>َ إِلَ<rule class=madda_normal>ـٰ</rule>هَكُمۡ لَو<rule class=madda_normal>ٰ</rule>حِ<rule class=qalaqah>د</rule>ٌ ٤',
    4, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 5 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3793,
    'رَّبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا وَرَبُّ ٱلۡمَشَـٰرِقِ',
    'رب السماوات والارض وما بينهما ورب المشارق',
    'رَّبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ <rule class=ham_wasl>ٱ</rule>لۡمَشَ<rule class=madda_normal>ـٰ</rule>رِ<rule class=qalaqah>ق</rule>ِ ٥',
    5, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 6 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3794,
    'إِنَّا زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِزِینَةٍ ٱلۡكَوَاكِبِ',
    'انا زينا السماء الدنيا بزينة الكواكب',
    'إِ<rule class=ghunnah>نّ</rule>َا زَيَّ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا بِزِينَةٍ <rule class=ham_wasl>ٱ</rule>لۡكَوَاكِ<rule class=qalaqah>ب</rule>ِ ٦',
    6, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 7 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3795,
    'وَحِفۡظࣰا مِّن كُلِّ شَیۡطَـٰنࣲ مَّارِدࣲ',
    'وحفظا من كل شيطان مارد',
    'وَحِفۡ<rule class=idgham_ghunnah>ظًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ شَيۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>َّارِ<rule class=qalaqah>د</rule>ٍ ٧',
    7, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 8 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3796,
    'لَّا یَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَیُقۡذَفُونَ مِن كُلِّ جَانِبࣲ',
    'لا يسمعون الى الملا الاعلى ويقذفون من كل جانب',
    'لَّا يَسَّ<rule class=ghunnah>مّ</rule>َعُونَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡمَلَإِ <rule class=ham_wasl>ٱ</rule>لۡأَعۡلَىٰ وَيُ<rule class=qalaqah>قۡ</rule>ذَفُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ جَانِ<rule class=qalaqah>ب</rule>ٍ ٨',
    8, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 9 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3797,
    'دُحُورࣰاۖ وَلَهُمۡ عَذَابࣱ وَاصِبٌ',
    'دحورا ولهم عذاب واصب',
    'دُحُو<rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َاصِ<rule class=qalaqah>ب</rule>ٌ ٩',
    9, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 10 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3798,
    'إِلَّا مَنۡ خَطِفَ ٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابࣱ ثَاقِبࣱ',
    'الا من خطف الخطفة فاتبعه شهاب ثاقب',
    'إِلَّا مَنۡ خَطِفَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=qalaqah>طۡ</rule>فَةَ فَأَتۡبَعَهُ<rule class=madda_normal>ۥ</rule> شِهَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ث</rule>َاقِ<rule class=qalaqah>ب</rule>ٌ ١٠',
    10, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 11 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3799,
    'فَٱسۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا أَم مَّنۡ خَلَقۡنَاۤۚ إِنَّا خَلَقۡنَـٰهُم مِّن طِینࣲ لَّازِبِۭ',
    'فاستفتهم اهم اشد خلقا ام من خلقنا انا خلقناهم من طين لازب',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا أ<rule class=idgham_shafawi>َم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ خَلَ<rule class=qalaqah>قۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>ِي<rule class=idgham_wo_ghunnah>نٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّازِ<rule class=qalaqah>ب</rule>ِۭ ١١',
    11, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 12 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3800,
    'بَلۡ عَجِبۡتَ وَیَسۡخَرُونَ',
    'بل عجبت ويسخرون',
    'بَلۡ عَجِ<rule class=qalaqah>بۡ</rule>تَ وَيَسۡخَر<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 13 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3801,
    'وَإِذَا ذُكِّرُوا۟ لَا یَذۡكُرُونَ',
    'واذا ذكروا لا يذكرون',
    'وَإِذَا ذُكِّرُو<rule class=slnt>اۡ</rule> لَا يَذۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 14 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3802,
    'وَإِذَا رَأَوۡا۟ ءَایَةࣰ یَسۡتَسۡخِرُونَ',
    'واذا راوا اية يستسخرون',
    'وَإِذَا رَأَوۡ<rule class=slnt>اۡ</rule> ءَايَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَسۡخِر<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 15 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3803,
    'وَقَالُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینٌ',
    'وقالوا ان هذا الا سحر مبين',
    'وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٥',
    15, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 16 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3804,
    'أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَـٰمًا أَءِنَّا لَمَبۡعُوثُونَ',
    'ااذا متنا وكنا ترابا وعظاما اانا لمبعوثون',
    'أَءِذَا مِتۡنَا وَكُ<rule class=ghunnah>نّ</rule>َا تُرَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َعِظَ<rule class=madda_normal>ـٰ</rule>مًا أَءِ<rule class=ghunnah>نّ</rule>َا لَمَ<rule class=qalaqah>بۡ</rule>عُوث<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 17 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3805,
    'أَوَءَابَاۤؤُنَا ٱلۡأَوَّلُونَ',
    'اواباؤنا الاولون',
    'أَوَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 18 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3806,
    'قُلۡ نَعَمۡ وَأَنتُمۡ دَ ٰ⁠خِرُونَ',
    'قل نعم وانتم داخرون',
    'قُلۡ نَعَمۡ وَأَ<rule class=ikhafa>نت</rule>ُمۡ د<rule class=madda_normal>ٰ</rule>خِر<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 19 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3807,
    'فَإِنَّمَا هِیَ زَجۡرَةࣱ وَ ٰ⁠حِدَةࣱ فَإِذَا هُمۡ یَنظُرُونَ',
    'فانما هي زجرة واحدة فاذا هم ينظرون',
    'فَإِ<rule class=ghunnah>نّ</rule>َمَا هِىَ زَ<rule class=qalaqah>جۡ</rule>رَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َإِذَا هُمۡ يَ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 20 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3808,
    'وَقَالُوا۟ یَـٰوَیۡلَنَا هَـٰذَا یَوۡمُ ٱلدِّینِ',
    'وقالوا يا ويلنا هذا يوم الدين',
    'وَقَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>وَيۡلَنَا هَ<rule class=madda_normal>ـٰ</rule>ذَا يَوۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ٢٠',
    20, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 21 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3809,
    'هَـٰذَا یَوۡمُ ٱلۡفَصۡلِ ٱلَّذِی كُنتُم بِهِۦ تُكَذِّبُونَ',
    'هذا يوم الفصل الذي كنتم به تكذبون',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا يَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡفَصۡلِ <rule class=ham_wasl>ٱ</rule>لَّذِى كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> تُكَذِّب<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 23, 6, 446, 386, 178, 'false'
  );
  
  -- Ayah 22 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3810,
    '۞ ٱحۡشُرُوا۟ ٱلَّذِینَ ظَلَمُوا۟ وَأَزۡوَ ٰ⁠جَهُمۡ وَمَا كَانُوا۟ یَعۡبُدُونَ',
    'احشروا الذين ظلموا وازواجهم وما كانوا يعبدون',
    '۞ٱحۡشُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> وَأَزۡو<rule class=madda_normal>ٰ</rule>جَهُمۡ وَمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 23, 6, 446, 387, 179, 'false'
  );
  
  -- Ayah 23 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3811,
    'مِن دُونِ ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَ ٰ⁠طِ ٱلۡجَحِیمِ',
    'من دون الله فاهدوهم الى صراط الجحيم',
    'مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَ<rule class=ham_wasl>ٱ</rule>هۡدُوهُمۡ إِلَىٰ صِر<rule class=madda_normal>ٰ</rule>طِ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ٢٣',
    23, 23, 6, 446, 387, 179, 'false'
  );
  
  -- Ayah 24 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3812,
    'وَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ',
    'وقفوهم انهم مسئولون',
    'وَقِفُوهُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّسۡــُٔول<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 23, 6, 446, 387, 179, 'false'
  );
  
  -- Ayah 25 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3813,
    'مَا لَكُمۡ لَا تَنَاصَرُونَ',
    'ما لكم لا تناصرون',
    'مَا لَكُمۡ لَا تَنَاصَر<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 26 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3814,
    'بَلۡ هُمُ ٱلۡیَوۡمَ مُسۡتَسۡلِمُونَ',
    'بل هم اليوم مستسلمون',
    'بَلۡ هُمُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ مُسۡتَسۡلِم<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 27 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3815,
    'وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ یَتَسَاۤءَلُونَ',
    'واقبل بعضهم على بعض يتساءلون',
    'وَأَ<rule class=qalaqah>قۡ</rule>بَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَل<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 28 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3816,
    'قَالُوۤا۟ إِنَّكُمۡ كُنتُمۡ تَأۡتُونَنَا عَنِ ٱلۡیَمِینِ',
    'قالوا انكم كنتم تاتوننا عن اليمين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َكُمۡ كُ<rule class=ikhafa>نت</rule>ُمۡ تَأۡتُونَنَا عَنِ <rule class=ham_wasl>ٱ</rule>لۡيَم<rule class=madda_permissible>ِي</rule>نِ ٢٨',
    28, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 29 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3817,
    'قَالُوا۟ بَل لَّمۡ تَكُونُوا۟ مُؤۡمِنِینَ',
    'قالوا بل لم تكونوا مؤمنين',
    'قَالُو<rule class=slnt>اۡ</rule> بَل لَّمۡ تَكُونُو<rule class=slnt>اۡ</rule> مُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 30 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3818,
    'وَمَا كَانَ لَنَا عَلَیۡكُم مِّن سُلۡطَـٰنِۭۖ بَلۡ كُنتُمۡ قَوۡمࣰا طَـٰغِینَ',
    'وما كان لنا عليكم من سلطان بل كنتم قوما طاغين',
    'وَمَا كَانَ لَنَا عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>نِۭ‌ۖ</rule> <rule class=iqlab>ب</rule>َلۡ كُ<rule class=ikhafa>نت</rule>ُمۡ قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ط</rule>َ<rule class=madda_normal>ـٰ</rule>غ<rule class=madda_permissible>ِي</rule>نَ ٣٠',
    30, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 31 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3819,
    'فَحَقَّ عَلَیۡنَا قَوۡلُ رَبِّنَاۤۖ إِنَّا لَذَاۤىِٕقُونَ',
    'فحق علينا قول ربنا انا لذائقون',
    'فَحَقَّ عَلَيۡنَا قَوۡلُ رَبِّن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َا لَذ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِق<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 32 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3820,
    'فَأَغۡوَیۡنَـٰكُمۡ إِنَّا كُنَّا غَـٰوِینَ',
    'فاغويناكم انا كنا غاوين',
    'فَأَغۡوَيۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا غَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 33 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3821,
    'فَإِنَّهُمۡ یَوۡمَىِٕذࣲ فِی ٱلۡعَذَابِ مُشۡتَرِكُونَ',
    'فانهم يومئذ في العذاب مشتركون',
    'فَإِ<rule class=ghunnah>نّ</rule>َهُمۡ يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ مُشۡتَرِك<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 34 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3822,
    'إِنَّا كَذَ ٰ⁠لِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِینَ',
    'انا كذلك نفعل بالمجرمين',
    'إِ<rule class=ghunnah>نّ</rule>َا كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَفۡعَلُ بِ<rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 35 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3823,
    'إِنَّهُمۡ كَانُوۤا۟ إِذَا قِیلَ لَهُمۡ لَاۤ إِلَـٰهَ إِلَّا ٱللَّهُ یَسۡتَكۡبِرُونَ',
    'انهم كانوا اذا قيل لهم لا اله الا الله يستكبرون',
    'إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا قِيلَ لَهُمۡ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ يَسۡتَكۡبِر<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 36 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3824,
    'وَیَقُولُونَ أَىِٕنَّا لَتَارِكُوۤا۟ ءَالِهَتِنَا لِشَاعِرࣲ مَّجۡنُونِۭ',
    'ويقولون ائنا لتاركو الهتنا لشاعر مجنون',
    'وَيَقُولُونَ أَئِ<rule class=ghunnah>نّ</rule>َا لَتَارِك<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَالِهَتِنَا لِشَاعِ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نِۭ ٣٦',
    36, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 37 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3825,
    'بَلۡ جَاۤءَ بِٱلۡحَقِّ وَصَدَّقَ ٱلۡمُرۡسَلِینَ',
    'بل جاء بالحق وصدق المرسلين',
    'بَلۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَصَدَّقَ <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 23, 6, 447, 387, 179, 'false'
  );
  
  -- Ayah 38 Surah As-Saaffaat
