  VALUES (
    37,
    3855,
    'ثُمَّ إِنَّ لَهُمۡ عَلَیۡهَا لَشَوۡبࣰا مِّنۡ حَمِیمࣲ',
    'ثم ان لهم عليها لشوبا من حميم',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َ لَهُمۡ عَلَيۡهَا لَشَوۡ<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ حَم<rule class=madda_permissible>ِي</rule>مٍ ٦٧',
    67, 23, 6, 448, 387, 179, 'false'
  );
  
  -- Ayah 68 Surah As-Saaffaat
