    68, 23, 6, 448, 387, 179, 'false'
  );
  
  -- Ayah 69 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3857,
    'إِنَّهُمۡ أَلۡفَوۡا۟ ءَابَاۤءَهُمۡ ضَاۤلِّینَ',
    'انهم الفوا اباءهم ضالين',
    'إِ<rule class=ghunnah>نّ</rule>َهُمۡ أَلۡفَوۡ<rule class=slnt>اۡ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ ض<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ِي</rule>نَ ٦٩',
    69, 23, 6, 448, 387, 179, 'false'
  );
  
  -- Ayah 70 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3858,
    'فَهُمۡ عَلَىٰۤ ءَاثَـٰرِهِمۡ یُهۡرَعُونَ',
    'فهم على اثارهم يهرعون',
    'فَهُمۡ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاثَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ يُهۡرَع<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 23, 6, 448, 387, 179, 'false'
  );
  
  -- Ayah 71 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
