    'ولقد ضل قبلهم اكثر الاولين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ضَلَّ قَ<rule class=qalaqah>بۡ</rule>لَهُمۡ أَكۡثَرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٧١',
    71, 23, 6, 448, 387, 179, 'false'
  );
  
  -- Ayah 72 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3860,
    'وَلَقَدۡ أَرۡسَلۡنَا فِیهِم مُّنذِرِینَ',
    'ولقد ارسلنا فيهم منذرين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا فِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=ikhafa>نذ</rule>ِر<rule class=madda_permissible>ِي</rule>نَ ٧٢',
    72, 23, 6, 448, 387, 179, 'false'
  );
  
  -- Ayah 73 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3861,
    'فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُنذَرِینَ',
    'فانظر كيف كان عاقبة المنذرين',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نذ</rule>َر<rule class=madda_permissible>ِي</rule>نَ ٧٣',
    73, 23, 6, 448, 387, 179, 'false'
  );
  
  -- Ayah 74 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
