    'إِلَّا عِبَادَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡمُخۡلَص<rule class=madda_permissible>ِي</rule>نَ ٧٤',
    74, 23, 6, 448, 387, 179, 'false'
  );
  
  -- Ayah 75 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
