    'ثم اغرقنا الاخرين',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَغۡرَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡأَخَر<rule class=madda_permissible>ِي</rule>نَ ٨٢',
    82, 23, 6, 449, 388, 179, 'false'
  );
  
  -- Ayah 83 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
