    3871,
    '۞ وَإِنَّ مِن شِیعَتِهِۦ لَإِبۡرَ ٰ⁠هِیمَ',
    'وان من شيعته لابراهيم',
    '۞وَإِ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>ِيعَتِه<rule class=madda_normal>ِۦ</rule> لَإِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>ه<rule class=madda_permissible>ِي</rule>مَ ٨٣',
    83, 23, 6, 449, 388, 180, 'false'
  );
  
  -- Ayah 84 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3872,
