    'ائفكا الهة دون الله تريدون',
    'أَئِفۡكًا ءَالِهَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>د</rule>ُونَ <rule class=ham_wasl>ٱ</rule>للَّهِ تُرِيد<rule class=madda_permissible>ُو</rule>نَ ٨٦',
    86, 23, 6, 449, 388, 180, 'false'
  );
  
  -- Ayah 87 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3875,
    'فَمَا ظَنُّكُم بِرَبِّ ٱلۡعَـٰلَمِینَ',
    'فما ظنكم برب العالمين',
    'فَمَا ظَ<rule class=ghunnah>نّ</rule>ُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 23, 6, 449, 388, 180, 'false'
  );
  
  -- Ayah 88 Surah As-Saaffaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    37,
    3876,
