    'انهم لهم المنصورون',
    'إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=ikhafa>نص</rule>ُور<rule class=madda_permissible>ُو</rule>نَ ١٧٢',
    172, 23, 6, 452, 390, 181, 'false'
