  );
  

-- Surah Saad
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (38, 'سُورَةُ صٓ', 'Saad', 'The letter Saad', 'Meccan', 88);

  -- Ayah 1 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3971,
    'صۤۚ وَٱلۡقُرۡءَانِ ذِی ٱلذِّكۡرِ',
    'ص والقران ذي الذكر',
    '<rule class=madda_necessary>صٓ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ ذِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرِ ١',
    1, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 2 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3972,
    'بَلِ ٱلَّذِینَ كَفَرُوا۟ فِی عِزَّةࣲ وَشِقَاقࣲ',
    'بل الذين كفروا في عزة وشقاق',
    'بَلِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فِى عِزَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َشِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ٍ ٢',
    2, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 3 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3973,
    'كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنࣲ فَنَادَوا۟ وَّلَاتَ حِینَ مَنَاصࣲ',
    'كم اهلكنا من قبلهم من قرن فنادوا ولات حين مناص',
    'كَمۡ أَهۡلَكۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡ<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ف</rule>َنَادَو<rule class=slnt>اۡ</rule> وَّلَاتَ حِينَ مَن<rule class=madda_permissible>َا</rule>صٍ ٣',
    3, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 4 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3974,
    'وَعَجِبُوۤا۟ أَن جَاۤءَهُم مُّنذِرࣱ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَـٰفِرُونَ هَـٰذَا سَـٰحِرࣱ كَذَّابٌ',
    'وعجبوا ان جاءهم منذر منهم وقال الكافرون هذا ساحر كذاب',
    'وَعَجِب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=ikhafa>نذ</rule>ِ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ‌ۖ وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرُونَ هَ<rule class=madda_normal>ـٰ</rule>ذَا سَ<rule class=madda_normal>ـٰ</rule>حِ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ك</rule>َذّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٤',
    4, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 5 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3975,
    'أَجَعَلَ ٱلۡـَٔالِهَةَ إِلَـٰهࣰا وَ ٰ⁠حِدًاۖ إِنَّ هَـٰذَا لَشَیۡءٌ عُجَابࣱ',
    'اجعل الالهة الها واحدا ان هذا لشيء عجاب',
    'أَجَعَلَ <rule class=ham_wasl>ٱ</rule>لۡأَلِهَةَ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدًا‌ۖ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَشَىۡءٌ عُج<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٥',
    5, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 6 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3976,
    'وَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُوا۟ وَٱصۡبِرُوا۟ عَلَىٰۤ ءَالِهَتِكُمۡۖ إِنَّ هَـٰذَا لَشَیۡءࣱ یُرَادُ',
    'وانطلق الملا منهم ان امشوا واصبروا على الهتكم ان هذا لشيء يراد',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نط</rule>َلَقَ <rule class=ham_wasl>ٱ</rule>لۡمَلَأُ مِنۡهُمۡ أَنِ <rule class=ham_wasl>ٱ</rule>مۡشُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>صۡبِرُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَالِهَتِكُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَش<rule class=idgham_ghunnah>َىۡءٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُر<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ُ ٦',
    6, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 7 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3977,
    'مَا سَمِعۡنَا بِهَـٰذَا فِی ٱلۡمِلَّةِ ٱلۡـَٔاخِرَةِ إِنۡ هَـٰذَاۤ إِلَّا ٱخۡتِلَـٰقٌ',
    'ما سمعنا بهذا في الملة الاخرة ان هذا الا اختلاق',
    'مَا سَمِعۡنَا بِهَ<rule class=madda_normal>ـٰ</rule>ذَا فِى <rule class=ham_wasl>ٱ</rule>لۡمِلَّةِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ إِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>خۡتِلَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ق</rule>ٌ ٧',
    7, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 8 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3978,
    'أَءُنزِلَ عَلَیۡهِ ٱلذِّكۡرُ مِنۢ بَیۡنِنَاۚ بَلۡ هُمۡ فِی شَكࣲّ مِّن ذِكۡرِیۚ بَل لَّمَّا یَذُوقُوا۟ عَذَابِ',
    'اانزل عليه الذكر من بيننا بل هم في شك من ذكري بل لما يذوقوا عذاب',
    'أَءُ<rule class=ikhafa>نز</rule>ِلَ عَلَيۡهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِنَا‌ۚ بَلۡ هُمۡ فِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِى‌ۖ بَل لَّ<rule class=ghunnah>مّ</rule>َا يَذُوقُو<rule class=slnt>اۡ</rule> عَذ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٨',
    8, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 9 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3979,
    'أَمۡ عِندَهُمۡ خَزَاۤىِٕنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِیزِ ٱلۡوَهَّابِ',
    'ام عندهم خزائن رحمة ربك العزيز الوهاب',
    'أَمۡ عِ<rule class=ikhafa>ند</rule>َهُمۡ خَز<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنُ رَحۡمَةِ رَبِّكَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡوَهّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٩',
    9, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 10 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3980,
    'أَمۡ لَهُم مُّلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۖ فَلۡیَرۡتَقُوا۟ فِی ٱلۡأَسۡبَـٰبِ',
    'ام لهم ملك السماوات والارض وما بينهما فليرتقوا في الاسباب',
    'أَمۡ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا‌ۖ فَلۡيَرۡتَقُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَسۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ١٠',
    10, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 11 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3981,
    'جُندࣱ مَّا هُنَالِكَ مَهۡزُومࣱ مِّنَ ٱلۡأَحۡزَابِ',
    'جند ما هنالك مهزوم من الاحزاب',
    'جُن<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا هُنَالِكَ مَهۡزُو<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡز<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١١',
    11, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 12 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3982,
    'كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ',
    'كذبت قبلهم قوم نوح وعاد وفرعون ذو الاوتاد',
    'كَذَّبَتۡ قَ<rule class=qalaqah>بۡ</rule>لَهُمۡ قَوۡمُ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَا<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َفِرۡعَوۡنُ ذُو <rule class=ham_wasl>ٱ</rule>لۡأَوۡت<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ١٢',
    12, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 13 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3983,
    'وَثَمُودُ وَقَوۡمُ لُوطࣲ وَأَصۡحَـٰبُ لۡـَٔیۡكَةِۚ أُو۟لَـٰۤىِٕكَ ٱلۡأَحۡزَابُ',
    'وثمود وقوم لوط واصحاب الايكة اولئك الاحزاب',
    'وَثَمُودُ وَقَوۡمُ لُو<rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ لۡــَٔيۡكَةِ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡز<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ُ ١٣',
    13, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 14 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3984,
    'إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ',
    'ان كل الا كذب الرسل فحق عقاب',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلٌّ إِلَّا كَذَّبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلَ فَحَقَّ عِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٤',
    14, 23, 6, 453, 391, 181, 'false'
  );
  
  -- Ayah 15 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3985,
    'وَمَا یَنظُرُ هَـٰۤؤُلَاۤءِ إِلَّا صَیۡحَةࣰ وَ ٰ⁠حِدَةࣰ مَّا لَهَا مِن فَوَاقࣲ',
    'وما ينظر هؤلاء الا صيحة واحدة ما لها من فواق',
    'وَمَا يَ<rule class=ikhafa>نظ</rule>ُرُ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِلَّا صَيۡحَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>َّا لَهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َو<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ٍ ١٥',
    15, 23, 6, 453, 392, 181, 'false'
  );
  
  -- Ayah 16 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3986,
    'وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبۡلَ یَوۡمِ ٱلۡحِسَابِ',
    'وقالوا ربنا عجل لنا قطنا قبل يوم الحساب',
    'وَقَالُو<rule class=slnt>اۡ</rule> رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَ<rule class=qalaqah>بۡ</rule>لَ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٦',
    16, 23, 6, 453, 392, 181, 'false'
  );
  
  -- Ayah 17 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3987,
    'ٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَیۡدِۖ إِنَّهُۥۤ أَوَّابٌ',
    'اصبر على ما يقولون واذكر عبدنا داوود ذا الايد انه اواب',
    'ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ عَ<rule class=qalaqah>بۡ</rule>دَنَا دَاوُ<rule class=madda_normal>ۥ</rule>دَ ذَا <rule class=ham_wasl>ٱ</rule>لۡأَيۡدِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَوّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ١٧',
    17, 23, 6, 454, 392, 181, 'false'
  );
  
  -- Ayah 18 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3988,
    'إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ یُسَبِّحۡنَ بِٱلۡعَشِیِّ وَٱلۡإِشۡرَاقِ',
    'انا سخرنا الجبال معه يسبحن بالعشي والاشراق',
    'إِ<rule class=ghunnah>نّ</rule>َا سَخَّرۡنَا <rule class=ham_wasl>ٱ</rule>لۡجِبَالَ مَعَهُ<rule class=madda_normal>ۥ</rule> يُسَبِّحۡنَ بِ<rule class=ham_wasl>ٱ</rule>لۡعَشِىِّ وَ<rule class=ham_wasl>ٱ</rule>لۡإِشۡر<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ِ ١٨',
    18, 23, 6, 454, 392, 181, 'false'
  );
  
  -- Ayah 19 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3989,
    'وَٱلطَّیۡرَ مَحۡشُورَةࣰۖ كُلࣱّ لَّهُۥۤ أَوَّابࣱ',
    'والطير محشورة كل له اواب',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرَ مَحۡشُورَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ك</rule>ُ<rule class=idgham_wo_ghunnah>لٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَوّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ١٩',
    19, 23, 6, 454, 392, 181, 'false'
  );
  
  -- Ayah 20 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3990,
    'وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَیۡنَـٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ',
    'وشددنا ملكه واتيناه الحكمة وفصل الخطاب',
    'وَشَدَ<rule class=qalaqah>دۡ</rule>نَا مُلۡكَهُ<rule class=madda_normal>ۥ</rule> وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَفَصۡلَ <rule class=ham_wasl>ٱ</rule>لۡخِط<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢٠',
    20, 23, 6, 454, 392, 181, 'false'
  );
  
  -- Ayah 21 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3991,
    '۞ وَهَلۡ أَتَىٰكَ نَبَؤُا۟ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُوا۟ ٱلۡمِحۡرَابَ',
    'وهل اتاك نبا الخصم اذ تسوروا المحراب',
    '۞وَهَلۡ أَتَ<rule class=madda_normal>ـٰ</rule>كَ نَبَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡخَصۡمِ إِذۡ تَسَوَّرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمِحۡر<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>َ ٢١',
    21, 23, 6, 454, 392, 182, 'false'
  );
  
  -- Ayah 22 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3992,
    'إِذۡ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُوا۟ لَا تَخَفۡۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضࣲ فَٱحۡكُم بَیۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ وَٱهۡدِنَاۤ إِلَىٰ سَوَاۤءِ ٱلصِّرَ ٰ⁠طِ',
    'اذ دخلوا على داوود ففزع منهم قالوا لا تخف خصمان بغى بعضنا على بعض فاحكم بيننا بالحق ولا تشطط واهدنا الى سواء الصراط',
    'إِذۡ دَخَلُو<rule class=slnt>اۡ</rule> عَلَىٰ دَاوُ<rule class=madda_normal>ۥ</rule>دَ فَفَزِعَ مِنۡهُمۡ‌ۖ قَالُو<rule class=slnt>اۡ</rule> لَا تَخَفۡ‌ۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>حۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَنَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَلَا تُشۡطِ<rule class=qalaqah>طۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>هۡدِن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّر<rule class=madda_permissible>ٰ</rule><rule class=qalaqah>ط</rule>ِ ٢٢',
    22, 23, 6, 454, 392, 182, 'false'
  );
  
  -- Ayah 23 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3993,
    'إِنَّ هَـٰذَاۤ أَخِی لَهُۥ تِسۡعࣱ وَتِسۡعُونَ نَعۡجَةࣰ وَلِیَ نَعۡجَةࣱ وَ ٰ⁠حِدَةࣱ فَقَالَ أَكۡفِلۡنِیهَا وَعَزَّنِی فِی ٱلۡخِطَابِ',
    'ان هذا اخي له تسع وتسعون نعجة ولي نعجة واحدة فقال اكفلنيها وعزني في الخطاب',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> أَخِى لَهُ<rule class=madda_normal>ۥ</rule> تِسۡ<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>و</rule>َتِسۡعُونَ نَعۡجَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلِىَ نَعۡجَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َقَالَ أَكۡفِلۡنِيهَا وَعَزَّنِى فِى <rule class=ham_wasl>ٱ</rule>لۡخِط<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢٣',
    23, 23, 6, 454, 392, 182, 'false'
  );
  
  -- Ayah 24 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3994,
    'قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِیرࣰا مِّنَ ٱلۡخُلَطَاۤءِ لَیَبۡغِی بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَقَلِیلࣱ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّـٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّ رَاكِعࣰا وَأَنَابَ ۩',
    'قال لقد ظلمك بسؤال نعجتك الى نعاجه وان كثيرا من الخلطاء ليبغي بعضهم على بعض الا الذين امنوا وعملوا الصالحات وقليل ما هم وظن داوود انما فتناه فاستغفر ربه وخر راكعا واناب',
    'قَالَ لَقَ<rule class=qalaqah>دۡ</rule> ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡخُلَط<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ لَيَ<rule class=qalaqah>بۡ</rule>غِى بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَقَلِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا هُمۡ‌ۗ وَظَ<rule class=ghunnah>نّ</rule>َ دَاوُ<rule class=madda_normal>ۥ</rule>دُ أَ<rule class=ghunnah>نّ</rule>َمَا فَتَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هُ فَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفَرَ رَبَّهُ<rule class=madda_normal>ۥ</rule> وَخَرَّ رَاكِ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َأَنَ<rule class=madda_permissible>ا</rule><rule class=qalaqah>ب</rule>َ ۩ ٢٤',
    24, 23, 6, 454, 392, 182, '{"id":11,"recommended":true,"obligatory":false}'
  );
  
  -- Ayah 25 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3995,
    'فَغَفَرۡنَا لَهُۥ ذَ ٰ⁠لِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابࣲ',
    'فغفرنا له ذلك وان له عندنا لزلفى وحسن ماب',
    'فَغَفَرۡنَا لَهُ<rule class=madda_normal>ۥ</rule> ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َ لَهُ<rule class=madda_normal>ۥ</rule> عِ<rule class=ikhafa>ند</rule>َنَا لَزُلۡفَىٰ وَحُسۡنَ مَــٔ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٢٥',
    25, 23, 6, 454, 392, 182, 'false'
  );
  
  -- Ayah 26 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3996,
    'یَـٰدَاوُۥدُ إِنَّا جَعَلۡنَـٰكَ خَلِیفَةࣰ فِی ٱلۡأَرۡضِ فَٱحۡكُم بَیۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَیُضِلَّكَ عَن سَبِیلِ ٱللَّهِۚ إِنَّ ٱلَّذِینَ یَضِلُّونَ عَن سَبِیلِ ٱللَّهِ لَهُمۡ عَذَابࣱ شَدِیدُۢ بِمَا نَسُوا۟ یَوۡمَ ٱلۡحِسَابِ',
    'يا داوود انا جعلناك خليفة في الارض فاحكم بين الناس بالحق ولا تتبع الهوى فيضلك عن سبيل الله ان الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب',
    'يَ<rule class=madda_normal>ـٰ</rule>دَاوُ<rule class=madda_normal>ۥ</rule>دُ إِ<rule class=ghunnah>نّ</rule>َا جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ خَلِيفَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَ<rule class=ham_wasl>ٱ</rule>حۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَلَا تَتَّبِعِ <rule class=ham_wasl>ٱ</rule>لۡهَوَىٰ فَيُضِلَّكَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَضِلُّونَ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَهُمۡ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=iqlab>دُۢ</rule> <rule class=iqlab>ب</rule>ِمَا نَسُو<rule class=slnt>اۡ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢٦',
    26, 23, 6, 454, 392, 182, 'false'
  );
  
  -- Ayah 27 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3997,
    'وَمَا خَلَقۡنَا ٱلسَّمَاۤءَ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا بَـٰطِلࣰاۚ ذَ ٰ⁠لِكَ ظَنُّ ٱلَّذِینَ كَفَرُوا۟ۚ فَوَیۡلࣱ لِّلَّذِینَ كَفَرُوا۟ مِنَ ٱلنَّارِ',
    'وما خلقنا السماء والارض وما بينهما باطلا ذلك ظن الذين كفروا فويل للذين كفروا من النار',
    'وَمَا خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُمَا بَ<rule class=madda_normal>ـٰ</rule>طِل<rule class=ikhafa>اً‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ ظَ<rule class=ghunnah>نّ</rule>ُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ‌ۚ</rule> فَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٢٧',
    27, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 28 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3998,
    'أَمۡ نَجۡعَلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ كَٱلۡمُفۡسِدِینَ فِی ٱلۡأَرۡضِ أَمۡ نَجۡعَلُ ٱلۡمُتَّقِینَ كَٱلۡفُجَّارِ',
    'ام نجعل الذين امنوا وعملوا الصالحات كالمفسدين في الارض ام نجعل المتقين كالفجار',
    'أَمۡ نَ<rule class=qalaqah>جۡ</rule>عَلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ كَ<rule class=ham_wasl>ٱ</rule>لۡمُفۡسِدِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَمۡ نَ<rule class=qalaqah>جۡ</rule>عَلُ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقِينَ كَ<rule class=ham_wasl>ٱ</rule>لۡفُجّ<rule class=madda_permissible>َا</rule>رِ ٢٨',
    28, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 29 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    3999,
    'كِتَـٰبٌ أَنزَلۡنَـٰهُ إِلَیۡكَ مُبَـٰرَكࣱ لِّیَدَّبَّرُوۤا۟ ءَایَـٰتِهِۦ وَلِیَتَذَكَّرَ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ',
    'كتاب انزلناه اليك مبارك ليدبروا اياته وليتذكر اولو الالباب',
    'كِتَ<rule class=madda_normal>ـٰ</rule>بٌ أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ إِلَيۡكَ مُبَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=idgham_wo_ghunnah>كٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَدَّبَّر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَلِيَتَذَكَّرَ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٢٩',
    29, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 30 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4000,
    'وَوَهَبۡنَا لِدَاوُۥدَ سُلَیۡمَـٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥۤ أَوَّابٌ',
    'ووهبنا لداوود سليمان نعم العبد انه اواب',
    'وَوَهَ<rule class=qalaqah>بۡ</rule>نَا لِدَاوُ<rule class=madda_normal>ۥ</rule>دَ سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ‌ۚ نِعۡمَ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>بۡ</rule>دُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَوّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٣٠',
    30, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 31 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4001,
    'إِذۡ عُرِضَ عَلَیۡهِ بِٱلۡعَشِیِّ ٱلصَّـٰفِنَـٰتُ ٱلۡجِیَادُ',
    'اذ عرض عليه بالعشي الصافنات الجياد',
    'إِذۡ عُرِضَ عَلَيۡهِ بِ<rule class=ham_wasl>ٱ</rule>لۡعَشِىِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>فِنَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡجِي<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ُ ٣١',
    31, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 32 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4002,
    'فَقَالَ إِنِّیۤ أَحۡبَبۡتُ حُبَّ ٱلۡخَیۡرِ عَن ذِكۡرِ رَبِّی حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ',
    'فقال اني احببت حب الخير عن ذكر ربي حتى توارت بالحجاب',
    'فَقَالَ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡبَ<rule class=qalaqah>بۡ</rule>تُ حُبَّ <rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِ رَبِّى حَتَّىٰ تَوَارَتۡ بِ<rule class=ham_wasl>ٱ</rule>لۡحِج<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٣٢',
    32, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 33 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4003,
    'رُدُّوهَا عَلَیَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ',
    'ردوها علي فطفق مسحا بالسوق والاعناق',
    'رُدُّوهَا عَلَىَّ‌ۖ فَطَفِقَ مَسۡح<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّوقِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَعۡن<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ِ ٣٣',
    33, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 34 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4004,
    'وَلَقَدۡ فَتَنَّا سُلَیۡمَـٰنَ وَأَلۡقَیۡنَا عَلَىٰ كُرۡسِیِّهِۦ جَسَدࣰا ثُمَّ أَنَابَ',
    'ولقد فتنا سليمان والقينا على كرسيه جسدا ثم اناب',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> فَتَ<rule class=ghunnah>نّ</rule>َا سُلَيۡمَ<rule class=madda_normal>ـٰ</rule>نَ وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّه<rule class=madda_normal>ِۦ</rule> جَسَ<rule class=ikhafa>دًا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ أَن<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>َ ٣٤',
    34, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 35 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4005,
    'قَالَ رَبِّ ٱغۡفِرۡ لِی وَهَبۡ لِی مُلۡكࣰا لَّا یَنۢبَغِی لِأَحَدࣲ مِّنۢ بَعۡدِیۤۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ',
    'قال رب اغفر لي وهب لي ملكا لا ينبغي لاحد من بعدي انك انت الوهاب',
    'قَالَ رَبِّ <rule class=ham_wasl>ٱ</rule>غۡفِرۡ لِى وَهَ<rule class=qalaqah>بۡ</rule> لِى مُلۡ<rule class=idgham_wo_ghunnah>كًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَ<rule class=iqlab>نۢب</rule>َغِى لِأَحَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡد<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡوَهّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ُ ٣٥',
    35, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 36 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4006,
    'فَسَخَّرۡنَا لَهُ ٱلرِّیحَ تَجۡرِی بِأَمۡرِهِۦ رُخَاۤءً حَیۡثُ أَصَابَ',
    'فسخرنا له الريح تجري بامره رخاء حيث اصاب',
    'فَسَخَّرۡنَا لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيحَ تَ<rule class=qalaqah>جۡ</rule>رِى بِأَمۡرِه<rule class=madda_normal>ِۦ</rule> رُخ<rule class=madda_obligatory_mottasel>َا</rule>ٓءً حَيۡثُ أَص<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>َ ٣٦',
    36, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 37 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4007,
    'وَٱلشَّیَـٰطِینَ كُلَّ بَنَّاۤءࣲ وَغَوَّاصࣲ',
    'والشياطين كل بناء وغواص',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيَ<rule class=madda_normal>ـٰ</rule>طِينَ كُلَّ بَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٍ</rule> <rule class=idgham_ghunnah>و</rule>َغَوّ<rule class=madda_permissible>َا</rule>صٍ ٣٧',
    37, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 38 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4008,
    'وَءَاخَرِینَ مُقَرَّنِینَ فِی ٱلۡأَصۡفَادِ',
    'واخرين مقرنين في الاصفاد',
    'وَءَاخَرِينَ مُقَرَّنِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَصۡف<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٣٨',
    38, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 39 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4009,
    'هَـٰذَا عَطَاۤؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَیۡرِ حِسَابࣲ',
    'هذا عطاؤنا فامنن او امسك بغير حساب',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا عَط<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُنَا فَ<rule class=ham_wasl>ٱ</rule>مۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٣٩',
    39, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 40 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4010,
    'وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابࣲ',
    'وان له عندنا لزلفى وحسن ماب',
    'وَإِ<rule class=ghunnah>نّ</rule>َ لَهُ<rule class=madda_normal>ۥ</rule> عِ<rule class=ikhafa>ند</rule>َنَا لَزُلۡفَىٰ وَحُسۡنَ مَــٔ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٤٠',
    40, 23, 6, 455, 393, 182, 'false'
  );
  
  -- Ayah 41 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4011,
    'وَٱذۡكُرۡ عَبۡدَنَاۤ أَیُّوبَ إِذۡ نَادَىٰ رَبَّهُۥۤ أَنِّی مَسَّنِیَ ٱلشَّیۡطَـٰنُ بِنُصۡبࣲ وَعَذَابٍ',
    'واذكر عبدنا ايوب اذ نادى ربه اني مسني الشيطان بنصب وعذاب',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ عَ<rule class=qalaqah>بۡ</rule>دَن<rule class=madda_obligatory_monfasel>َآ</rule> أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=ghunnah>نّ</rule>ِى مَسَّنِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ بِنُصۡ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَذ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٤١',
    41, 23, 6, 455, 394, 182, 'false'
  );
  
  -- Ayah 42 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4012,
    'ٱرۡكُضۡ بِرِجۡلِكَۖ هَـٰذَا مُغۡتَسَلُۢ بَارِدࣱ وَشَرَابࣱ',
    'اركض برجلك هذا مغتسل بارد وشراب',
    'ٱرۡكُضۡ بِرِ<rule class=qalaqah>جۡ</rule>لِكَ‌ۖ هَ<rule class=madda_normal>ـٰ</rule>ذَا مُغۡتَسَ<rule class=iqlab>لُۢ</rule> <rule class=iqlab>ب</rule>َارِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َشَر<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٤٢',
    42, 23, 6, 455, 394, 182, 'false'
  );
  
  -- Ayah 43 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4013,
    'وَوَهَبۡنَا لَهُۥۤ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةࣰ مِّنَّا وَذِكۡرَىٰ لِأُو۟لِی ٱلۡأَلۡبَـٰبِ',
    'ووهبنا له اهله ومثلهم معهم رحمة منا وذكرى لاولي الالباب',
    'وَوَهَ<rule class=qalaqah>بۡ</rule>نَا لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَهۡلَهُ<rule class=madda_normal>ۥ</rule> وَمِثۡلَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّعَهُمۡ رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا وَذِكۡرَىٰ لِأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٤٣',
    43, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 44 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4014,
    'وَخُذۡ بِیَدِكَ ضِغۡثࣰا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَـٰهُ صَابِرࣰاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥۤ أَوَّابࣱ',
    'وخذ بيدك ضغثا فاضرب به ولا تحنث انا وجدناه صابرا نعم العبد انه اواب',
    'وَخُذۡ بِيَدِكَ ضِغۡ<rule class=ikhafa>ثًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>ضۡرِب بِّه<rule class=madda_normal>ِۦ</rule> وَلَا تَحۡنَثۡ‌ۗ إِ<rule class=ghunnah>نّ</rule>َا وَجَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ صَابِ<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>ن</rule>ِّعۡمَ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>بۡ</rule>دُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَوّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٤٤',
    44, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 45 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4015,
    'وَٱذۡكُرۡ عِبَـٰدَنَاۤ إِبۡرَ ٰ⁠هِیمَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ أُو۟لِی ٱلۡأَیۡدِی وَٱلۡأَبۡصَـٰرِ',
    'واذكر عبادنا ابراهيم واسحاق ويعقوب اولي الايدي والابصار',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ عِبَ<rule class=madda_normal>ـٰ</rule>دَن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَإِسۡحَ<rule class=madda_normal>ـٰ</rule>قَ وَيَعۡقُوبَ أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَيۡدِى وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_permissible>ـٰ</rule>رِ ٤٥',
    45, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 46 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4016,
    'إِنَّاۤ أَخۡلَصۡنَـٰهُم بِخَالِصَةࣲ ذِكۡرَى ٱلدَّارِ',
    'انا اخلصناهم بخالصة ذكرى الدار',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَخۡلَصۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِخَالِصَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ذ</rule>ِكۡرَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>َا</rule>رِ ٤٦',
    46, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 47 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4017,
    'وَإِنَّهُمۡ عِندَنَا لَمِنَ ٱلۡمُصۡطَفَیۡنَ ٱلۡأَخۡیَارِ',
    'وانهم عندنا لمن المصطفين الاخيار',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ عِ<rule class=ikhafa>ند</rule>َنَا لَمِنَ <rule class=ham_wasl>ٱ</rule>لۡمُصۡطَفَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡأَخۡي<rule class=madda_permissible>َا</rule>رِ ٤٧',
    47, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 48 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4018,
    'وَٱذۡكُرۡ إِسۡمَـٰعِیلَ وَٱلۡیَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلࣱّ مِّنَ ٱلۡأَخۡیَارِ',
    'واذكر اسماعيل واليسع وذا الكفل وكل من الاخيار',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ إِسۡمَ<rule class=madda_normal>ـٰ</rule>عِيلَ وَ<rule class=ham_wasl>ٱ</rule>لۡيَسَعَ وَذَا <rule class=ham_wasl>ٱ</rule>لۡكِفۡلِ‌ۖ وَكُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَخۡي<rule class=madda_permissible>َا</rule>رِ ٤٨',
    48, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 49 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4019,
    'هَـٰذَا ذِكۡرࣱۚ وَإِنَّ لِلۡمُتَّقِینَ لَحُسۡنَ مَـَٔابࣲ',
    'هذا ذكر وان للمتقين لحسن ماب',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا ذِكۡ<rule class=idgham_ghunnah>رٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ لِلۡمُتَّقِينَ لَحُسۡنَ مَــٔ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٤٩',
    49, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 50 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4020,
    'جَنَّـٰتِ عَدۡنࣲ مُّفَتَّحَةࣰ لَّهُمُ ٱلۡأَبۡوَ ٰ⁠بُ',
    'جنات عدن مفتحة لهم الابواب',
    'جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّفَتَّحَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_permissible>ٰ</rule><rule class=qalaqah>ب</rule>ُ ٥٠',
    50, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 51 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4021,
    'مُتَّكِـِٔینَ فِیهَا یَدۡعُونَ فِیهَا بِفَـٰكِهَةࣲ كَثِیرَةࣲ وَشَرَابࣲ',
    'متكئين فيها يدعون فيها بفاكهة كثيرة وشراب',
    'مُتَّكِــِٔينَ فِيهَا يَ<rule class=qalaqah>دۡ</rule>عُونَ فِيهَا بِفَ<rule class=madda_normal>ـٰ</rule>كِهَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ك</rule>َثِيرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َشَر<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٥١',
    51, 23, 6, 456, 394, 182, 'false'
  );
  
  -- Ayah 52 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4022,
    '۞ وَعِندَهُمۡ قَـٰصِرَ ٰ⁠تُ ٱلطَّرۡفِ أَتۡرَابٌ',
    'وعندهم قاصرات الطرف اتراب',
    '۞وَعِ<rule class=ikhafa>ند</rule>َهُمۡ قَ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_normal>ٰ</rule>تُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّرۡفِ أَتۡر<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٥٢',
    52, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 53 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4023,
    'هَـٰذَا مَا تُوعَدُونَ لِیَوۡمِ ٱلۡحِسَابِ',
    'هذا ما توعدون ليوم الحساب',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا مَا تُوعَدُونَ لِيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٥٣',
    53, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 54 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4024,
    'إِنَّ هَـٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ',
    'ان هذا لرزقنا ما له من نفاد',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَرِزۡقُنَا مَا لَهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّف<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ٍ ٥٤',
    54, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 55 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4025,
    'هَـٰذَاۚ وَإِنَّ لِلطَّـٰغِینَ لَشَرَّ مَـَٔابࣲ',
    'هذا وان للطاغين لشر ماب',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ لِلطَّ<rule class=madda_normal>ـٰ</rule>غِينَ لَشَرَّ مَــٔ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٥٥',
    55, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 56 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4026,
    'جَهَنَّمَ یَصۡلَوۡنَهَا فَبِئۡسَ ٱلۡمِهَادُ',
    'جهنم يصلونها فبئس المهاد',
    'جَهَ<rule class=ghunnah>نّ</rule>َمَ يَصۡلَوۡنَهَا فَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمِه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ُ ٥٦',
    56, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 57 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4027,
    'هَـٰذَا فَلۡیَذُوقُوهُ حَمِیمࣱ وَغَسَّاقࣱ',
    'هذا فليذوقوه حميم وغساق',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا فَلۡيَذُوقُوهُ حَمِي<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َغَسّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ٌ ٥٧',
    57, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 58 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4028,
    'وَءَاخَرُ مِن شَكۡلِهِۦۤ أَزۡوَ ٰ⁠جٌ',
    'واخر من شكله ازواج',
    'وَءَاخَرُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َكۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَزۡو<rule class=madda_permissible>ٰ</rule><rule class=qalaqah>ج</rule>ٌ ٥٨',
    58, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 59 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4029,
    'هَـٰذَا فَوۡجࣱ مُّقۡتَحِمࣱ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُوا۟ ٱلنَّارِ',
    'هذا فوج مقتحم معكم لا مرحبا بهم انهم صالو النار',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا فَوۡ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَحِ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعَكُمۡ‌ۖ لَا مَرۡحَب<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُمۡ صَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٥٩',
    59, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 60 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4030,
    'قَالُوا۟ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ',
    'قالوا بل انتم لا مرحبا بكم انتم قدمتموه لنا فبئس القرار',
    'قَالُو<rule class=slnt>اۡ</rule> بَلۡ أَ<rule class=ikhafa>نت</rule>ُمۡ لَا مَرۡحَب<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِكُمۡ‌ۖ أَ<rule class=ikhafa>نت</rule>ُمۡ قَدَّمۡتُمُوهُ لَنَا‌ۖ فَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡقَر<rule class=madda_permissible>َا</rule>رُ ٦٠',
    60, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 61 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4031,
    'قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَـٰذَا فَزِدۡهُ عَذَابࣰا ضِعۡفࣰا فِی ٱلنَّارِ',
    'قالوا ربنا من قدم لنا هذا فزده عذابا ضعفا في النار',
    'قَالُو<rule class=slnt>اۡ</rule> رَبَّنَا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َدَّمَ لَنَا هَ<rule class=madda_normal>ـٰ</rule>ذَا فَزِ<rule class=qalaqah>دۡ</rule>هُ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ض</rule>ِعۡ<rule class=ikhafa>فًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٦١',
    61, 23, 6, 456, 394, 183, 'false'
  );
  
  -- Ayah 62 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4032,
    'وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالࣰا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ',
    'وقالوا ما لنا لا نرى رجالا كنا نعدهم من الاشرار',
    'وَقَالُو<rule class=slnt>اۡ</rule> مَا لَنَا لَا نَرَىٰ رِجَال<rule class=ikhafa>اً</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َا نَعُدُّه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَشۡر<rule class=madda_permissible>َا</rule>رِ ٦٢',
    62, 23, 6, 457, 394, 183, 'false'
  );
  
  -- Ayah 63 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4033,
    'أَتَّخَذۡنَـٰهُمۡ سِخۡرِیًّا أَمۡ زَاغَتۡ عَنۡهُمُ ٱلۡأَبۡصَـٰرُ',
    'اتخذناهم سخريا ام زاغت عنهم الابصار',
    'أَتَّخَذۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ سِخۡرِيًّا أَمۡ زَاغَتۡ عَنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_permissible>ـٰ</rule>رُ ٦٣',
    63, 23, 6, 457, 394, 183, 'false'
  );
  
  -- Ayah 64 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4034,
    'إِنَّ ذَ ٰ⁠لِكَ لَحَقࣱّ تَخَاصُمُ أَهۡلِ ٱلنَّارِ',
    'ان ذلك لحق تخاصم اهل النار',
    'إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ لَحَ<rule class=ikhafa>قٌّ</rule> <rule class=ikhafa>ت</rule>َخَاصُمُ أَهۡلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٦٤',
    64, 23, 6, 457, 394, 183, 'false'
  );
  
  -- Ayah 65 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4035,
    'قُلۡ إِنَّمَاۤ أَنَا۠ مُنذِرࣱۖ وَمَا مِنۡ إِلَـٰهٍ إِلَّا ٱللَّهُ ٱلۡوَ ٰ⁠حِدُ ٱلۡقَهَّارُ',
    'قل انما انا منذر وما من اله الا الله الواحد القهار',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ مُ<rule class=ikhafa>نذ</rule>ِ<rule class=idgham_ghunnah>رٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َمَا مِنۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٍ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>حِدُ <rule class=ham_wasl>ٱ</rule>لۡقَهّ<rule class=madda_permissible>َا</rule>رُ ٦٥',
    65, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 66 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4036,
    'رَبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا ٱلۡعَزِیزُ ٱلۡغَفَّـٰرُ',
    'رب السماوات والارض وما بينهما العزيز الغفار',
    'رَبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡغَفَّ<rule class=madda_permissible>ـٰ</rule>رُ ٦٦',
    66, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 67 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4037,
    'قُلۡ هُوَ نَبَؤٌا۟ عَظِیمٌ',
    'قل هو نبا عظيم',
    'قُلۡ هُوَ نَبَؤٌاۡ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٦٧',
    67, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 68 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4038,
    'أَنتُمۡ عَنۡهُ مُعۡرِضُونَ',
    'انتم عنه معرضون',
    'أَ<rule class=ikhafa>نت</rule>ُمۡ عَنۡهُ مُعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 69 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4039,
    'مَا كَانَ لِیَ مِنۡ عِلۡمِۭ بِٱلۡمَلَإِ ٱلۡأَعۡلَىٰۤ إِذۡ یَخۡتَصِمُونَ',
    'ما كان لي من علم بالملا الاعلى اذ يختصمون',
    'مَا كَانَ لِىَ مِنۡ عِلۡ<rule class=iqlab>مِۭ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَلَإِ <rule class=ham_wasl>ٱ</rule>لۡأَعۡلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذۡ يَخۡتَصِم<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 70 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4040,
    'إِن یُوحَىٰۤ إِلَیَّ إِلَّاۤ أَنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینٌ',
    'ان يوحى الي الا انما انا نذير مبين',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىَّ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٧٠',
    70, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 71 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4041,
    'إِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰۤىِٕكَةِ إِنِّی خَـٰلِقُۢ بَشَرࣰا مِّن طِینࣲ',
    'اذ قال ربك للملائكة اني خالق بشرا من طين',
    'إِذۡ قَالَ رَبُّكَ لِلۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةِ إِ<rule class=ghunnah>نّ</rule>ِى خَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=iqlab>قُۢ</rule> <rule class=iqlab>ب</rule>َشَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule><rule class=madda_permissible>ِي</rule>نٍ ٧١',
    71, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 72 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4042,
    'فَإِذَا سَوَّیۡتُهُۥ وَنَفَخۡتُ فِیهِ مِن رُّوحِی فَقَعُوا۟ لَهُۥ سَـٰجِدِینَ',
    'فاذا سويته ونفخت فيه من روحي فقعوا له ساجدين',
    'فَإِذَا سَوَّيۡتُهُ<rule class=madda_normal>ۥ</rule> وَنَفَخۡتُ فِيهِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّوحِى فَقَعُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> سَ<rule class=madda_normal>ـٰ</rule>جِد<rule class=madda_permissible>ِي</rule>نَ ٧٢',
    72, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 73 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4043,
    'فَسَجَدَ ٱلۡمَلَـٰۤىِٕكَةُ كُلُّهُمۡ أَجۡمَعُونَ',
    'فسجد الملائكة كلهم اجمعون',
    'فَسَجَدَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ كُلُّهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 74 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4044,
    'إِلَّاۤ إِبۡلِیسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَـٰفِرِینَ',
    'الا ابليس استكبر وكان من الكافرين',
    'إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=qalaqah>بۡ</rule>لِيسَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرَ وَكَانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٧٤',
    74, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 75 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4045,
    'قَالَ یَـٰۤإِبۡلِیسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِیَدَیَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ مِنَ ٱلۡعَالِینَ',
    'قال يا ابليس ما منعك ان تسجد لما خلقت بيدي استكبرت ام كنت من العالين',
    'قَالَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>إِ<rule class=qalaqah>بۡ</rule>لِيسُ مَا مَنَعَكَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َسۡجُدَ لِمَا خَلَ<rule class=qalaqah>قۡ</rule>تُ بِيَدَىَّ‌ۖ أَسۡتَكۡبَرۡتَ أَمۡ كُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعَال<rule class=madda_permissible>ِي</rule>نَ ٧٥',
    75, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 76 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4046,
    'قَالَ أَنَا۠ خَیۡرࣱ مِّنۡهُ خَلَقۡتَنِی مِن نَّارࣲ وَخَلَقۡتَهُۥ مِن طِینࣲ',
    'قال انا خير منه خلقتني من نار وخلقته من طين',
    'قَالَ أَنَاۡ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ‌ۖ خَلَ<rule class=qalaqah>قۡ</rule>تَنِى م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّا<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َخَلَ<rule class=qalaqah>قۡ</rule>تَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule><rule class=madda_permissible>ِي</rule>نٍ ٧٦',
    76, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 77 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4047,
    'قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِیمࣱ',
    'قال فاخرج منها فانك رجيم',
    'قَالَ فَ<rule class=ham_wasl>ٱ</rule>خۡرُ<rule class=qalaqah>جۡ</rule> مِنۡهَا فَإِ<rule class=ghunnah>نّ</rule>َكَ رَج<rule class=madda_permissible>ِي</rule>مٌ ٧٧',
    77, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 78 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4048,
    'وَإِنَّ عَلَیۡكَ لَعۡنَتِیۤ إِلَىٰ یَوۡمِ ٱلدِّینِ',
    'وان عليك لعنتي الى يوم الدين',
    'وَإِ<rule class=ghunnah>نّ</rule>َ عَلَيۡكَ لَعۡنَت<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ٧٨',
    78, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 79 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4049,
    'قَالَ رَبِّ فَأَنظِرۡنِیۤ إِلَىٰ یَوۡمِ یُبۡعَثُونَ',
    'قال رب فانظرني الى يوم يبعثون',
    'قَالَ رَبِّ فَأَ<rule class=ikhafa>نظ</rule>ِرۡن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ يَوۡمِ يُ<rule class=qalaqah>بۡ</rule>عَث<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 80 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4050,
    'قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِینَ',
    'قال فانك من المنظرين',
    'قَالَ فَإِ<rule class=ghunnah>نّ</rule>َكَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ِي</rule>نَ ٨٠',
    80, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 81 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4051,
    'إِلَىٰ یَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ',
    'الى يوم الوقت المعلوم',
    'إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡوَ<rule class=qalaqah>قۡ</rule>تِ <rule class=ham_wasl>ٱ</rule>لۡمَعۡل<rule class=madda_permissible>ُو</rule>مِ ٨١',
    81, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 82 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4052,
    'قَالَ فَبِعِزَّتِكَ لَأُغۡوِیَنَّهُمۡ أَجۡمَعِینَ',
    'قال فبعزتك لاغوينهم اجمعين',
    'قَالَ فَبِعِزَّتِكَ لَأُغۡوِيَ<rule class=ghunnah>نّ</rule>َهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٨٢',
    82, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 83 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4053,
    'إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِینَ',
    'الا عبادك منهم المخلصين',
    'إِلَّا عِبَادَكَ مِنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡمُخۡلَص<rule class=madda_permissible>ِي</rule>نَ ٨٣',
    83, 23, 6, 457, 395, 183, 'false'
  );
  
  -- Ayah 84 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4054,
    'قَالَ فَٱلۡحَقُّ وَٱلۡحَقَّ أَقُولُ',
    'قال فالحق والحق اقول',
    'قَالَ فَ<rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَ<rule class=ham_wasl>ٱ</rule>لۡحَقَّ أَق<rule class=madda_permissible>ُو</rule>لُ ٨٤',
    84, 23, 6, 458, 395, 183, 'false'
  );
  
  -- Ayah 85 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4055,
    'لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنۡهُمۡ أَجۡمَعِینَ',
    'لاملان جهنم منك وممن تبعك منهم اجمعين',
    'لَأَمۡلَأَ<rule class=ghunnah>نّ</rule>َ جَهَ<rule class=ghunnah>نّ</rule>َمَ مِ<rule class=ikhafa>نك</rule>َ وَمِ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبِعَكَ مِنۡهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٨٥',
    85, 23, 6, 458, 395, 183, 'false'
  );
  
  -- Ayah 86 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4056,
    'قُلۡ مَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرࣲ وَمَاۤ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِینَ',
    'قل ما اسالكم عليه من اجر وما انا من المتكلفين',
    'قُلۡ م<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ مِنۡ أَ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُتَكَلِّف<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 23, 6, 458, 395, 183, 'false'
  );
  
  -- Ayah 87 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4057,
    'إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَـٰلَمِینَ',
    'ان هو الا ذكر للعالمين',
    'إِنۡ هُوَ إِلَّا ذِكۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 23, 6, 458, 395, 183, 'false'
  );
  
  -- Ayah 88 Surah Saad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    38,
    4058,
    'وَلَتَعۡلَمُنَّ نَبَأَهُۥ بَعۡدَ حِینِۭ',
    'ولتعلمن نباه بعد حين',
    'وَلَتَعۡلَمُ<rule class=ghunnah>نّ</rule>َ نَبَأَهُ<rule class=madda_normal>ۥ</rule> بَعۡدَ ح<rule class=madda_permissible>ِي</rule>نِۭ ٨٨',
    88, 23, 6, 458, 395, 183, 'false'
  );
  

-- Surah Az-Zumar
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (39, 'سُورَةُ الزُّمَرِ', 'Az-Zumar', 'The Groups', 'Meccan', 75);

  -- Ayah 1 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4059,
    'تَنزِیلُ ٱلۡكِتَـٰبِ مِنَ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ',
    'تنزيل الكتاب من الله العزيز الحكيم',
    'تَ<rule class=ikhafa>نز</rule>ِيلُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ١',
    1, 23, 6, 458, 396, 183, 'false'
  );
  
  -- Ayah 2 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4060,
    'إِنَّاۤ أَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصࣰا لَّهُ ٱلدِّینَ',
    'انا انزلنا اليك الكتاب بالحق فاعبد الله مخلصا له الدين',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ فَ<rule class=ham_wasl>ٱ</rule>عۡبُدِ <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡلِ<rule class=idgham_wo_ghunnah>صًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 23, 6, 458, 396, 183, 'false'
  );
  
  -- Ayah 3 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4061,
    'أَلَا لِلَّهِ ٱلدِّینُ ٱلۡخَالِصُۚ وَٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ أَوۡلِیَاۤءَ مَا نَعۡبُدُهُمۡ إِلَّا لِیُقَرِّبُونَاۤ إِلَى ٱللَّهِ زُلۡفَىٰۤ إِنَّ ٱللَّهَ یَحۡكُمُ بَیۡنَهُمۡ فِی مَا هُمۡ فِیهِ یَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا یَهۡدِی مَنۡ هُوَ كَـٰذِبࣱ كَفَّارࣱ',
    'الا لله الدين الخالص والذين اتخذوا من دونه اولياء ما نعبدهم الا ليقربونا الى الله زلفى ان الله يحكم بينهم في ما هم فيه يختلفون ان الله لا يهدي من هو كاذب كفار',
    'أَلَا لِلَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينُ <rule class=ham_wasl>ٱ</rule>لۡخَالِصُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُون<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ زُلۡفَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَحۡكُمُ بَيۡنَهُمۡ فِى مَا هُمۡ فِيهِ يَخۡتَلِفُونَ‌ۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى مَنۡ هُوَ كَ<rule class=madda_normal>ـٰ</rule>ذِ<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ك</rule>َفّ<rule class=madda_permissible>َا</rule>رٌ ٣',
    3, 23, 6, 458, 396, 183, 'false'
  );
  
  -- Ayah 4 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4062,
    'لَّوۡ أَرَادَ ٱللَّهُ أَن یَتَّخِذَ وَلَدࣰا لَّٱصۡطَفَىٰ مِمَّا یَخۡلُقُ مَا یَشَاۤءُۚ سُبۡحَـٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَ ٰ⁠حِدُ ٱلۡقَهَّارُ',
    'لو اراد الله ان يتخذ ولدا لاصطفى مما يخلق ما يشاء سبحانه هو الله الواحد القهار',
    'لَّوۡ أَرَادَ <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّخِذَ وَلَ<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ham_wasl>ٱ</rule>صۡطَفَىٰ مِ<rule class=ghunnah>مّ</rule>َا يَخۡلُقُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule>‌ۖ هُوَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>حِدُ <rule class=ham_wasl>ٱ</rule>لۡقَهّ<rule class=madda_permissible>َا</rule>رُ ٤',
    4, 23, 6, 458, 396, 183, 'false'
  );
  
  -- Ayah 5 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4063,
    'خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ یُكَوِّرُ ٱلَّیۡلَ عَلَى ٱلنَّهَارِ وَیُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّیۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِی لِأَجَلࣲ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِیزُ ٱلۡغَفَّـٰرُ',
    'خلق السماوات والارض بالحق يكور الليل على النهار ويكور النهار على الليل وسخر الشمس والقمر كل يجري لاجل مسمى الا هو العزيز الغفار',
    'خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ يُكَوِّرُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَيُكَوِّرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّيۡلِ‌ۖ وَسَخَّرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرَ‌ۖ كُ<rule class=idgham_ghunnah>لٌّ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>رِى لِأَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَ<rule class=ghunnah>مّ</rule>ًى‌ۗ أَلَا هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡغَفَّ<rule class=madda_permissible>ـٰ</rule>رُ ٥',
    5, 23, 6, 458, 396, 183, 'false'
  );
  
  -- Ayah 6 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4064,
    'خَلَقَكُم مِّن نَّفۡسࣲ وَ ٰ⁠حِدَةࣲ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَـٰمِ ثَمَـٰنِیَةَ أَزۡوَ ٰ⁠جࣲۚ یَخۡلُقُكُمۡ فِی بُطُونِ أُمَّهَـٰتِكُمۡ خَلۡقࣰا مِّنۢ بَعۡدِ خَلۡقࣲ فِی ظُلُمَـٰتࣲ ثَلَـٰثࣲۚ ذَ ٰ⁠لِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ',
    'خلقكم من نفس واحدة ثم جعل منها زوجها وانزل لكم من الانعام ثمانية ازواج يخلقكم في بطون امهاتكم خلقا من بعد خلق في ظلمات ثلاث ذلكم الله ربكم له الملك لا اله الا هو فانى تصرفون',
    'خَلَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَ<rule class=ikhafa>نز</rule>َلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ ثَمَ<rule class=madda_normal>ـٰ</rule>نِيَةَ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جٍ‌ۚ</rule> <rule class=idgham_ghunnah>ي</rule>َخۡلُقُكُمۡ فِى بُطُونِ أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ خَلۡ<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ خَلۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ف</rule>ِى ظُلُمَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ث</rule>َلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>ثٍ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّكُمۡ لَهُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكُ‌ۖ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۖ فَأَ<rule class=ghunnah>نّ</rule>َىٰ تُصۡرَف<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 23, 6, 459, 396, 183, 'false'
  );
  
  -- Ayah 7 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4065,
    'إِن تَكۡفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِیٌّ عَنكُمۡۖ وَلَا یَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُوا۟ یَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'ان تكفروا فان الله غني عنكم ولا يرضى لعباده الكفر وان تشكروا يرضه لكم ولا تزر وازرة وزر اخرى ثم الى ربكم مرجعكم فينبئكم بما كنتم تعملون انه عليم بذات الصدور',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َكۡفُرُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَنِىٌّ عَ<rule class=ikhafa>نك</rule>ُمۡ‌ۖ وَلَا يَرۡضَىٰ لِعِبَادِهِ <rule class=ham_wasl>ٱ</rule>لۡكُفۡرَ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َشۡكُرُو<rule class=slnt>اۡ</rule> يَرۡضَهُ لَكُمۡ‌ۗ وَلَا تَزِرُ وَازِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>ِزۡرَ أُخۡرَىٰ‌ۗ ثُ<rule class=ghunnah>مّ</rule>َ إِلَىٰ رَبِّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرۡجِعُكُمۡ فَيُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَلُونَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٧',
    7, 23, 6, 459, 396, 183, 'false'
  );
  
  -- Ayah 8 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4066,
    '۞ وَإِذَا مَسَّ ٱلۡإِنسَـٰنَ ضُرࣱّ دَعَا رَبَّهُۥ مُنِیبًا إِلَیۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةࣰ مِّنۡهُ نَسِیَ مَا كَانَ یَدۡعُوۤا۟ إِلَیۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادࣰا لِّیُضِلَّ عَن سَبِیلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِیلًا إِنَّكَ مِنۡ أَصۡحَـٰبِ ٱلنَّارِ',
    'واذا مس الانسان ضر دعا ربه منيبا اليه ثم اذا خوله نعمة منه نسي ما كان يدعو اليه من قبل وجعل لله اندادا ليضل عن سبيله قل تمتع بكفرك قليلا انك من اصحاب النار',
    '۞وَإِذَا مَسَّ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ ضُ<rule class=ikhafa>رٌّ</rule> <rule class=ikhafa>د</rule>َعَا رَبَّهُ<rule class=madda_normal>ۥ</rule> مُنِيبًا إِلَيۡهِ ثُ<rule class=ghunnah>مّ</rule>َ إِذَا خَوَّلَهُ<rule class=madda_normal>ۥ</rule> نِعۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ نَسِىَ مَا كَانَ يَ<rule class=qalaqah>دۡ</rule>ع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ وَجَعَلَ لِلَّهِ أَ<rule class=ikhafa>ند</rule>َا<rule class=idgham_wo_ghunnah>دًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُضِلَّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِه<rule class=madda_normal>ِۦ</rule>‌ۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِيلاً‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ مِنۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٨',
    8, 23, 6, 459, 396, 184, 'false'
  );
  
  -- Ayah 9 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4067,
    'أَمَّنۡ هُوَ قَـٰنِتٌ ءَانَاۤءَ ٱلَّیۡلِ سَاجِدࣰا وَقَاۤىِٕمࣰا یَحۡذَرُ ٱلۡـَٔاخِرَةَ وَیَرۡجُوا۟ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ یَسۡتَوِی ٱلَّذِینَ یَعۡلَمُونَ وَٱلَّذِینَ لَا یَعۡلَمُونَۗ إِنَّمَا یَتَذَكَّرُ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ',
    'امن هو قانت اناء الليل ساجدا وقائما يحذر الاخرة ويرجو رحمة ربه قل هل يستوي الذين يعلمون والذين لا يعلمون انما يتذكر اولو الالباب',
    'أَ<rule class=ghunnah>مّ</rule>َنۡ هُوَ قَ<rule class=madda_normal>ـٰ</rule>نِتٌ ءَان<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ سَاجِ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>ي</rule>َحۡذَرُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ وَيَرۡجُو<rule class=slnt>اۡ</rule> رَحۡمَةَ رَبِّه<rule class=madda_normal>ِۦ</rule>‌ۗ قُلۡ هَلۡ يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَعۡلَمُونَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَعۡلَمُونَ‌ۗ إِ<rule class=ghunnah>نّ</rule>َمَا يَتَذَكَّرُ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٩',
    9, 23, 6, 459, 396, 184, 'false'
  );
  
  -- Ayah 10 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4068,
    'قُلۡ یَـٰعِبَادِ ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمۡۚ لِلَّذِینَ أَحۡسَنُوا۟ فِی هَـٰذِهِ ٱلدُّنۡیَا حَسَنَةࣱۗ وَأَرۡضُ ٱللَّهِ وَ ٰ⁠سِعَةٌۗ إِنَّمَا یُوَفَّى ٱلصَّـٰبِرُونَ أَجۡرَهُم بِغَیۡرِ حِسَابࣲ',
    'قل يا عباد الذين امنوا اتقوا ربكم للذين احسنوا في هذه الدنيا حسنة وارض الله واسعة انما يوفى الصابرون اجرهم بغير حساب',
    'قُلۡ يَ<rule class=madda_normal>ـٰ</rule>عِبَادِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ‌ۚ لِلَّذِينَ أَحۡسَنُو<rule class=slnt>اۡ</rule> فِى هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا حَسَنَ<rule class=idgham_ghunnah>ةٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َأَرۡضُ <rule class=ham_wasl>ٱ</rule>للَّهِ و<rule class=madda_normal>ٰ</rule>سِعَةٌ‌ۗ إِ<rule class=ghunnah>نّ</rule>َمَا يُوَفَّى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِرُونَ أَ<rule class=qalaqah>جۡ</rule>رَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِغَيۡرِ حِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ١٠',
    10, 23, 6, 459, 397, 184, 'false'
  );
  
  -- Ayah 11 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4069,
    'قُلۡ إِنِّیۤ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصࣰا لَّهُ ٱلدِّینَ',
    'قل اني امرت ان اعبد الله مخلصا له الدين',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أُمِرۡتُ أَنۡ أَعۡبُدَ <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡلِ<rule class=idgham_wo_ghunnah>صًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 12 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4070,
    'وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِینَ',
    'وامرت لان اكون اول المسلمين',
    'وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ١٢',
    12, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 13 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4071,
    'قُلۡ إِنِّیۤ أَخَافُ إِنۡ عَصَیۡتُ رَبِّی عَذَابَ یَوۡمٍ عَظِیمࣲ',
    'قل اني اخاف ان عصيت ربي عذاب يوم عظيم',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ إِنۡ عَصَيۡتُ رَبِّى عَذَابَ يَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ١٣',
    13, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 14 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4072,
    'قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصࣰا لَّهُۥ دِینِی',
    'قل الله اعبد مخلصا له ديني',
    'قُلِ <rule class=ham_wasl>ٱ</rule>للَّهَ أَعۡبُدُ مُخۡلِ<rule class=idgham_wo_ghunnah>صًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> دِينِى ١٤',
    14, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 15 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4073,
    'فَٱعۡبُدُوا۟ مَا شِئۡتُم مِّن دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَـٰسِرِینَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ وَأَهۡلِیهِمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۗ أَلَا ذَ ٰ⁠لِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِینُ',
    'فاعبدوا ما شئتم من دونه قل ان الخاسرين الذين خسروا انفسهم واهليهم يوم القيامة الا ذلك هو الخسران المبين',
    'فَ<rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> مَا شِئۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule>‌ۗ قُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِرِينَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَسِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ أَلَا ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡخُسۡرَانُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ١٥',
    15, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 16 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4074,
    'لَهُم مِّن فَوۡقِهِمۡ ظُلَلࣱ مِّنَ ٱلنَّارِ وَمِن تَحۡتِهِمۡ ظُلَلࣱۚ ذَ ٰ⁠لِكَ یُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ یَـٰعِبَادِ فَٱتَّقُونِ',
    'لهم من فوقهم ظلل من النار ومن تحتهم ظلل ذلك يخوف الله به عباده يا عباد فاتقون',
    'لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهِمۡ ظُلَ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهِمۡ ظُلَ<rule class=ikhafa>لٌ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ يُخَوِّفُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِه<rule class=madda_normal>ِۦ</rule> عِبَادَهُ<rule class=madda_normal>ۥ</rule>‌ۚ يَ<rule class=madda_normal>ـٰ</rule>عِبَادِ فَ<rule class=ham_wasl>ٱ</rule>تَّق<rule class=madda_permissible>ُو</rule>نِ ١٦',
    16, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 17 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4075,
    'وَٱلَّذِینَ ٱجۡتَنَبُوا۟ ٱلطَّـٰغُوتَ أَن یَعۡبُدُوهَا وَأَنَابُوۤا۟ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ',
    'والذين اجتنبوا الطاغوت ان يعبدوها وانابوا الى الله لهم البشرى فبشر عباد',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَنَبُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّ<rule class=madda_normal>ـٰ</rule>غُوتَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡبُدُوهَا وَأَنَاب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡبُشۡرَىٰ‌ۚ فَبَشِّرۡ عِب<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ١٧',
    17, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 18 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4076,
    'ٱلَّذِینَ یَسۡتَمِعُونَ ٱلۡقَوۡلَ فَیَتَّبِعُونَ أَحۡسَنَهُۥۤۚ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ هَدَىٰهُمُ ٱللَّهُۖ وَأُو۟لَـٰۤىِٕكَ هُمۡ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ',
    'الذين يستمعون القول فيتبعون احسنه اولئك الذين هداهم الله واولئك هم اولو الالباب',
    'ٱلَّذِينَ يَسۡتَمِعُونَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلَ فَيَتَّبِعُونَ أَحۡسَنَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَدَ<rule class=madda_normal>ٮٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمۡ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ١٨',
    18, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 19 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4077,
    'أَفَمَنۡ حَقَّ عَلَیۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِی ٱلنَّارِ',
    'افمن حق عليه كلمة العذاب افانت تنقذ من في النار',
    'أَفَمَنۡ حَقَّ عَلَيۡهِ كَلِمَةُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ أَفَأَ<rule class=ikhafa>نت</rule>َ تُ<rule class=ikhafa>نق</rule>ِذُ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ١٩',
    19, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 20 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4078,
    'لَـٰكِنِ ٱلَّذِینَ ٱتَّقَوۡا۟ رَبَّهُمۡ لَهُمۡ غُرَفࣱ مِّن فَوۡقِهَا غُرَفࣱ مَّبۡنِیَّةࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ وَعۡدَ ٱللَّهِ لَا یُخۡلِفُ ٱللَّهُ ٱلۡمِیعَادَ',
    'لكن الذين اتقوا ربهم لهم غرف من فوقها غرف مبنية تجري من تحتها الانهار وعد الله لا يخلف الله الميعاد',
    'لَ<rule class=madda_normal>ـٰ</rule>كِنِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> رَبَّهُمۡ لَهُمۡ غُرَ<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهَا غُرَ<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>بۡ</rule>نِيَّ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۖ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ لَا يُخۡلِفُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡمِيع<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>َ ٢٠',
    20, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 21 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4079,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَسَلَكَهُۥ یَنَـٰبِیعَ فِی ٱلۡأَرۡضِ ثُمَّ یُخۡرِجُ بِهِۦ زَرۡعࣰا مُّخۡتَلِفًا أَلۡوَ ٰ⁠نُهُۥ ثُمَّ یَهِیجُ فَتَرَىٰهُ مُصۡفَرࣰّا ثُمَّ یَجۡعَلُهُۥ حُطَـٰمًاۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَذِكۡرَىٰ لِأُو۟لِی ٱلۡأَلۡبَـٰبِ',
    'الم تر ان الله انزل من السماء ماء فسلكه ينابيع في الارض ثم يخرج به زرعا مختلفا الوانه ثم يهيج فتراه مصفرا ثم يجعله حطاما ان في ذلك لذكرى لاولي الالباب',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ أَ<rule class=ikhafa>نز</rule>َلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءً</rule> <rule class=ikhafa>ف</rule>َسَلَكَهُ<rule class=madda_normal>ۥ</rule> يَنَ<rule class=madda_normal>ـٰ</rule>بِيعَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ ثُ<rule class=ghunnah>مّ</rule>َ يُخۡرِجُ بِه<rule class=madda_normal>ِۦ</rule> زَرۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>م</rule>ُّخۡتَلِفًا أَلۡو<rule class=madda_normal>ٰ</rule>نُهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ يَهِيجُ فَتَرَ<rule class=madda_normal>ٮٰ</rule>هُ مُصۡفَر<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ يَ<rule class=qalaqah>جۡ</rule>عَلُهُ<rule class=madda_normal>ۥ</rule> حُطَ<rule class=madda_normal>ـٰ</rule>مًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَذِكۡرَىٰ لِأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٢١',
    21, 23, 6, 460, 397, 184, 'false'
  );
  
  -- Ayah 22 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4080,
    'أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَـٰمِ فَهُوَ عَلَىٰ نُورࣲ مِّن رَّبِّهِۦۚ فَوَیۡلࣱ لِّلۡقَـٰسِیَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُو۟لَـٰۤىِٕكَ فِی ضَلَـٰلࣲ مُّبِینٍ',
    'افمن شرح الله صدره للاسلام فهو على نور من ربه فويل للقاسية قلوبهم من ذكر الله اولئك في ضلال مبين',
    'أَفَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َرَحَ <rule class=ham_wasl>ٱ</rule>للَّهُ صَ<rule class=qalaqah>دۡ</rule>رَهُ<rule class=madda_normal>ۥ</rule> لِلۡإِسۡلَ<rule class=madda_normal>ـٰ</rule>مِ فَهُوَ عَلَىٰ نُو<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule>‌ۚ فَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡقَ<rule class=madda_normal>ـٰ</rule>سِيَةِ قُلُوبُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٢٢',
    22, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 23 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4081,
    'ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِیثِ كِتَـٰبࣰا مُّتَشَـٰبِهࣰا مَّثَانِیَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِینُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَ ٰ⁠لِكَ هُدَى ٱللَّهِ یَهۡدِی بِهِۦ مَن یَشَاۤءُۚ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ',
    'الله نزل احسن الحديث كتابا متشابها مثاني تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم الى ذكر الله ذلك هدى الله يهدي به من يشاء ومن يضلل الله فما له من هاد',
    'ٱللَّهُ نَزَّلَ أَحۡسَنَ <rule class=ham_wasl>ٱ</rule>لۡحَدِيثِ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ُّتَشَ<rule class=madda_normal>ـٰ</rule>بِ<rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>م</rule>َّثَانِىَ تَ<rule class=qalaqah>قۡ</rule>شَعِرُّ مِنۡهُ جُلُودُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَخۡشَوۡنَ رَبَّهُمۡ ثُ<rule class=ghunnah>مّ</rule>َ تَلِينُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُدَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَهۡدِى بِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَمَا لَهُ<rule class=madda_normal>ۥ</rule> مِنۡ ه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ٍ ٢٣',
    23, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 24 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4082,
    'أَفَمَن یَتَّقِی بِوَجۡهِهِۦ سُوۤءَ ٱلۡعَذَابِ یَوۡمَ ٱلۡقِیَـٰمَةِۚ وَقِیلَ لِلظَّـٰلِمِینَ ذُوقُوا۟ مَا كُنتُمۡ تَكۡسِبُونَ',
    'افمن يتقي بوجهه سوء العذاب يوم القيامة وقيل للظالمين ذوقوا ما كنتم تكسبون',
    'أَفَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّقِى بِوَ<rule class=qalaqah>جۡ</rule>هِه<rule class=madda_normal>ِۦ</rule> س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ وَقِيلَ لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ ذُوقُو<rule class=slnt>اۡ</rule> مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 25 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4083,
    'كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَیۡثُ لَا یَشۡعُرُونَ',
    'كذب الذين من قبلهم فاتاهم العذاب من حيث لا يشعرون',
    'كَذَّبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ فَأَتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 26 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4084,
    'فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡیَ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَكۡبَرُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ',
    'فاذاقهم الله الخزي في الحياة الدنيا ولعذاب الاخرة اكبر لو كانوا يعلمون',
    'فَأَذَاقَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡخِزۡىَ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَلَعَذَابُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ أَكۡبَرُ‌ۚ لَوۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 27 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4085,
    'وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِی هَـٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲ لَّعَلَّهُمۡ یَتَذَكَّرُونَ',
    'ولقد ضربنا للناس في هذا القران من كل مثل لعلهم يتذكرون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ضَرَ<rule class=qalaqah>بۡ</rule>نَا لِل<rule class=ghunnah>نّ</rule>َاسِ فِى هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مَثَ<rule class=idgham_wo_ghunnah>لٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّهُمۡ يَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 28 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4086,
    'قُرۡءَانًا عَرَبِیًّا غَیۡرَ ذِی عِوَجࣲ لَّعَلَّهُمۡ یَتَّقُونَ',
    'قرانا عربيا غير ذي عوج لعلهم يتقون',
    'قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِى عِوَ<rule class=idgham_wo_ghunnah>جٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّهُمۡ يَتَّق<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 29 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4087,
    'ضَرَبَ ٱللَّهُ مَثَلࣰا رَّجُلࣰا فِیهِ شُرَكَاۤءُ مُتَشَـٰكِسُونَ وَرَجُلࣰا سَلَمࣰا لِّرَجُلٍ هَلۡ یَسۡتَوِیَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ',
    'ضرب الله مثلا رجلا فيه شركاء متشاكسون ورجلا سلما لرجل هل يستويان مثلا الحمد لله بل اكثرهم لا يعلمون',
    'ضَرَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَثَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّجُل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>ِيهِ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مُتَشَ<rule class=madda_normal>ـٰ</rule>كِسُونَ وَرَجُل<rule class=ikhafa>اً</rule> <rule class=ikhafa>س</rule>َلَ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّرَجُلٍ هَلۡ يَسۡتَوِيَانِ مَثَلاً‌ۚ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ‌ۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 30 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4088,
    'إِنَّكَ مَیِّتࣱ وَإِنَّهُم مَّیِّتُونَ',
    'انك ميت وانهم ميتون',
    'إِ<rule class=ghunnah>نّ</rule>َكَ مَيِّ<rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّيِّت<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 31 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4089,
    'ثُمَّ إِنَّكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ',
    'ثم انكم يوم القيامة عند ربكم تختصمون',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َكُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ عِ<rule class=ikhafa>ند</rule>َ رَبِّكُمۡ تَخۡتَصِم<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 23, 6, 461, 398, 184, 'false'
  );
  
  -- Ayah 32 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4090,
    '۞ فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَاۤءَهُۥۤۚ أَلَیۡسَ فِی جَهَنَّمَ مَثۡوࣰى لِّلۡكَـٰفِرِینَ',
    'فمن اظلم ممن كذب على الله وكذب بالصدق اذ جاءه اليس في جهنم مثوى للكافرين',
    '۞فَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَبَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَكَذَّبَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّ<rule class=qalaqah>دۡ</rule>قِ إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> أَلَيۡسَ فِى جَهَ<rule class=ghunnah>نّ</rule>َمَ مَثۡ<rule class=idgham_wo_ghunnah>وًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 33 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4091,
    'وَٱلَّذِی جَاۤءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦۤ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُتَّقُونَ',
    'والذي جاء بالصدق وصدق به اولئك هم المتقون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِى ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّ<rule class=qalaqah>دۡ</rule>قِ وَصَدَّقَ بِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۙ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 34 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4092,
    'لَهُم مَّا یَشَاۤءُونَ عِندَ رَبِّهِمۡۚ ذَ ٰ⁠لِكَ جَزَاۤءُ ٱلۡمُحۡسِنِینَ',
    'لهم ما يشاءون عند ربهم ذلك جزاء المحسنين',
    'لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُونَ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 35 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4093,
    'لِیُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِی عَمِلُوا۟ وَیَجۡزِیَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِی كَانُوا۟ یَعۡمَلُونَ',
    'ليكفر الله عنهم اسوا الذي عملوا ويجزيهم اجرهم باحسن الذي كانوا يعملون',
    'لِيُكَفِّرَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَنۡهُمۡ أَسۡوَأَ <rule class=ham_wasl>ٱ</rule>لَّذِى عَمِلُو<rule class=slnt>اۡ</rule> وَيَ<rule class=qalaqah>جۡ</rule>زِيَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَحۡسَنِ <rule class=ham_wasl>ٱ</rule>لَّذِى كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 36 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4094,
    'أَلَیۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَیُخَوِّفُونَكَ بِٱلَّذِینَ مِن دُونِهِۦۚ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ',
    'اليس الله بكاف عبده ويخوفونك بالذين من دونه ومن يضلل الله فما له من هاد',
    'أَلَيۡسَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِكَافٍ عَ<rule class=qalaqah>بۡ</rule>دَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَيُخَوِّفُونَكَ بِ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَمَا لَهُ<rule class=madda_normal>ۥ</rule> مِنۡ ه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ٍ ٣٦',
    36, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 37 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4095,
    'وَمَن یَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ أَلَیۡسَ ٱللَّهُ بِعَزِیزࣲ ذِی ٱنتِقَامࣲ',
    'ومن يهد الله فما له من مضل اليس الله بعزيز ذي انتقام',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَمَا لَهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّضِلٍّ‌ۗ أَلَيۡسَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِعَزِي<rule class=ikhafa>زٍ</rule> <rule class=ikhafa>ذ</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>ِق<rule class=madda_permissible>َا</rule>مٍ ٣٧',
    37, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 38 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4096,
    'وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ لَیَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَیۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِیَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَـٰشِفَـٰتُ ضُرِّهِۦۤ أَوۡ أَرَادَنِی بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَـٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِیَ ٱللَّهُۖ عَلَیۡهِ یَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ',
    'ولئن سالتهم من خلق السماوات والارض ليقولن الله قل افرايتم ما تدعون من دون الله ان ارادني الله بضر هل هن كاشفات ضره او ارادني برحمة هل هن ممسكات رحمته قل حسبي الله عليه يتوكل المتوكلون',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َأَلۡتَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ لَيَقُولُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ قُلۡ أَفَرَءَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِنۡ أَرَادَنِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِضُرٍّ هَلۡ هُ<rule class=ghunnah>نّ</rule>َ كَ<rule class=madda_normal>ـٰ</rule>شِفَ<rule class=madda_normal>ـٰ</rule>تُ ضُرِّه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡ أَرَادَنِى بِرَحۡمَةٍ هَلۡ هُ<rule class=ghunnah>نّ</rule>َ مُمۡسِكَ<rule class=madda_normal>ـٰ</rule>تُ رَحۡمَتِه<rule class=madda_normal>ِۦ</rule>‌ۚ قُلۡ حَسۡبِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ عَلَيۡهِ يَتَوَكَّلُ <rule class=ham_wasl>ٱ</rule>لۡمُتَوَكِّل<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 39 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4097,
    'قُلۡ یَـٰقَوۡمِ ٱعۡمَلُوا۟ عَلَىٰ مَكَانَتِكُمۡ إِنِّی عَـٰمِلࣱۖ فَسَوۡفَ تَعۡلَمُونَ',
    'قل يا قوم اعملوا على مكانتكم اني عامل فسوف تعلمون',
    'قُلۡ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>عۡمَلُو<rule class=slnt>اۡ</rule> عَلَىٰ مَكَانَتِكُمۡ إِ<rule class=ghunnah>نّ</rule>ِى عَ<rule class=madda_normal>ـٰ</rule>مِ<rule class=ikhafa>لٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َسَوۡفَ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 40 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4098,
    'مَن یَأۡتِیهِ عَذَابࣱ یُخۡزِیهِ وَیَحِلُّ عَلَیۡهِ عَذَابࣱ مُّقِیمٌ',
    'من ياتيه عذاب يخزيه ويحل عليه عذاب مقيم',
    'م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيهِ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّق<rule class=madda_permissible>ِي</rule>مٌ ٤٠',
    40, 24, 6, 462, 399, 185, 'false'
  );
  
  -- Ayah 41 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4099,
    'إِنَّاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا یَضِلُّ عَلَیۡهَاۖ وَمَاۤ أَنتَ عَلَیۡهِم بِوَكِیلٍ',
    'انا انزلنا عليك الكتاب للناس بالحق فمن اهتدى فلنفسه ومن ضل فانما يضل عليها وما انت عليهم بوكيل',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ لِل<rule class=ghunnah>نّ</rule>َاسِ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ فَمَنِ <rule class=ham_wasl>ٱ</rule>هۡتَدَىٰ فَلِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَّ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَضِلُّ عَلَيۡهَا‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِوَك<rule class=madda_permissible>ِي</rule>لٍ ٤١',
    41, 24, 6, 463, 399, 185, 'false'
  );
  
  -- Ayah 42 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4100,
    'ٱللَّهُ یَتَوَفَّى ٱلۡأَنفُسَ حِینَ مَوۡتِهَا وَٱلَّتِی لَمۡ تَمُتۡ فِی مَنَامِهَاۖ فَیُمۡسِكُ ٱلَّتِی قَضَىٰ عَلَیۡهَا ٱلۡمَوۡتَ وَیُرۡسِلُ ٱلۡأُخۡرَىٰۤ إِلَىٰۤ أَجَلࣲ مُّسَمًّىۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ',
    'الله يتوفى الانفس حين موتها والتي لم تمت في منامها فيمسك التي قضى عليها الموت ويرسل الاخرى الى اجل مسمى ان في ذلك لايات لقوم يتفكرون',
    'ٱللَّهُ يَتَوَفَّى <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>ُسَ حِينَ مَوۡتِهَا وَ<rule class=ham_wasl>ٱ</rule>لَّتِى لَمۡ تَمُتۡ فِى مَنَامِهَا‌ۖ فَيُمۡسِكُ <rule class=ham_wasl>ٱ</rule>لَّتِى قَضَىٰ عَلَيۡهَا <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ وَيُرۡسِلُ <rule class=ham_wasl>ٱ</rule>لۡأُخۡرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَ<rule class=ghunnah>مّ</rule>ًى‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 24, 6, 463, 400, 185, 'false'
  );
  
  -- Ayah 43 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4101,
    'أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَاۤءَۚ قُلۡ أَوَلَوۡ كَانُوا۟ لَا یَمۡلِكُونَ شَیۡـࣰٔا وَلَا یَعۡقِلُونَ',
    'ام اتخذوا من دون الله شفعاء قل اولو كانوا لا يملكون شيئا ولا يعقلون',
    'أَمِ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ شُفَع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۚ قُلۡ أَوَلَوۡ كَانُو<rule class=slnt>اۡ</rule> لَا يَمۡلِكُونَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 24, 6, 463, 400, 185, 'false'
  );
  
  -- Ayah 44 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4102,
    'قُل لِّلَّهِ ٱلشَّفَـٰعَةُ جَمِیعࣰاۖ لَّهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ ثُمَّ إِلَیۡهِ تُرۡجَعُونَ',
    'قل لله الشفاعة جميعا له ملك السماوات والارض ثم اليه ترجعون',
    'قُل لِّلَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّفَ<rule class=madda_normal>ـٰ</rule>عَةُ جَمِي<rule class=idgham_wo_ghunnah>عًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ إِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 24, 6, 463, 400, 185, 'false'
  );
  
  -- Ayah 45 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4103,
    'وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِینَ مِن دُونِهِۦۤ إِذَا هُمۡ یَسۡتَبۡشِرُونَ',
    'واذا ذكر الله وحده اشمازت قلوب الذين لا يؤمنون بالاخرة واذا ذكر الذين من دونه اذا هم يستبشرون',
    'وَإِذَا ذُكِرَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَحۡدَهُ <rule class=ham_wasl>ٱ</rule>شۡمَأَزَّتۡ قُلُوبُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ وَإِذَا ذُكِرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِذَا هُمۡ يَسۡتَ<rule class=qalaqah>بۡ</rule>شِر<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 24, 6, 463, 400, 185, 'false'
  );
  
  -- Ayah 46 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4104,
    'قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ عَـٰلِمَ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ أَنتَ تَحۡكُمُ بَیۡنَ عِبَادِكَ فِی مَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ',
    'قل اللهم فاطر السماوات والارض عالم الغيب والشهادة انت تحكم بين عبادك في ما كانوا فيه يختلفون',
    'قُلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّهُ<rule class=ghunnah>مّ</rule>َ فَاطِرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ عَ<rule class=madda_normal>ـٰ</rule>لِمَ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ أَ<rule class=ikhafa>نت</rule>َ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِى مَا كَانُو<rule class=slnt>اۡ</rule> فِيهِ يَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 24, 6, 463, 400, 185, 'false'
  );
  
  -- Ayah 47 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4105,
    'وَلَوۡ أَنَّ لِلَّذِینَ ظَلَمُوا۟ مَا فِی ٱلۡأَرۡضِ جَمِیعࣰا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡا۟ بِهِۦ مِن سُوۤءِ ٱلۡعَذَابِ یَوۡمَ ٱلۡقِیَـٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ یَكُونُوا۟ یَحۡتَسِبُونَ',
    'ولو ان للذين ظلموا ما في الارض جميعا ومثله معه لافتدوا به من سوء العذاب يوم القيامة وبدا لهم من الله ما لم يكونوا يحتسبون',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َ لِلَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َمِثۡلَهُ<rule class=madda_normal>ۥ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> لَ<rule class=ham_wasl>ٱ</rule>فۡتَدَوۡ<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule><rule class=madda_obligatory_mottasel>ُو</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ وَبَدَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مَا لَمۡ يَكُونُو<rule class=slnt>اۡ</rule> يَحۡتَسِب<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 24, 6, 463, 400, 185, 'false'
  );
  
  -- Ayah 48 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4106,
    'وَبَدَا لَهُمۡ سَیِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'وبدا لهم سيئات ما كسبوا وحاق بهم ما كانوا به يستهزئون',
    'وَبَدَا لَهُمۡ سَيِّـَٔـاتُ مَا كَسَبُو<rule class=slnt>اۡ</rule> وَحَاقَ بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 24, 6, 464, 400, 185, 'false'
  );
  
  -- Ayah 49 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4107,
    'فَإِذَا مَسَّ ٱلۡإِنسَـٰنَ ضُرࣱّ دَعَانَا ثُمَّ إِذَا خَوَّلۡنَـٰهُ نِعۡمَةࣰ مِّنَّا قَالَ إِنَّمَاۤ أُوتِیتُهُۥ عَلَىٰ عِلۡمِۭۚ بَلۡ هِیَ فِتۡنَةࣱ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'فاذا مس الانسان ضر دعانا ثم اذا خولناه نعمة منا قال انما اوتيته على علم بل هي فتنة ولكن اكثرهم لا يعلمون',
    'فَإِذَا مَسَّ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ ضُ<rule class=ikhafa>رٌّ</rule> <rule class=ikhafa>د</rule>َعَانَا ثُ<rule class=ghunnah>مّ</rule>َ إِذَا خَوَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُ نِعۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا قَالَ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِيتُهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ عِلۡ<rule class=iqlab>مِۭ‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ هِىَ فِتۡنَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 24, 6, 464, 400, 185, 'false'
  );
  
  -- Ayah 50 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4108,
    'قَدۡ قَالَهَا ٱلَّذِینَ مِن قَبۡلِهِمۡ فَمَاۤ أَغۡنَىٰ عَنۡهُم مَّا كَانُوا۟ یَكۡسِبُونَ',
    'قد قالها الذين من قبلهم فما اغنى عنهم ما كانوا يكسبون',
    'قَ<rule class=qalaqah>دۡ</rule> قَالَهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡنَىٰ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 24, 6, 464, 400, 185, 'false'
  );
  
  -- Ayah 51 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4109,
    'فَأَصَابَهُمۡ سَیِّـَٔاتُ مَا كَسَبُوا۟ۚ وَٱلَّذِینَ ظَلَمُوا۟ مِنۡ هَـٰۤؤُلَاۤءِ سَیُصِیبُهُمۡ سَیِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعۡجِزِینَ',
    'فاصابهم سيئات ما كسبوا والذين ظلموا من هؤلاء سيصيبهم سيئات ما كسبوا وما هم بمعجزين',
    'فَأَصَابَهُمۡ سَيِّـَٔـاتُ مَا كَسَبُو<rule class=slnt>اۡ‌ۚ</rule> وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> مِنۡ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ سَيُصِيبُهُمۡ سَيِّـَٔـاتُ مَا كَسَبُو<rule class=slnt>اۡ</rule> وَمَا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُعۡجِز<rule class=madda_permissible>ِي</rule>نَ ٥١',
    51, 24, 6, 464, 400, 185, 'false'
  );
  
  -- Ayah 52 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4110,
    'أَوَلَمۡ یَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ',
    'اولم يعلموا ان الله يبسط الرزق لمن يشاء ويقدر ان في ذلك لايات لقوم يؤمنون',
    'أَوَلَمۡ يَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَ<rule class=qalaqah>قۡ</rule>دِرُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٥٢',
    52, 24, 6, 464, 400, 185, 'false'
  );
  
  -- Ayah 53 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4111,
    '۞ قُلۡ یَـٰعِبَادِیَ ٱلَّذِینَ أَسۡرَفُوا۟ عَلَىٰۤ أَنفُسِهِمۡ لَا تَقۡنَطُوا۟ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ یَغۡفِرُ ٱلذُّنُوبَ جَمِیعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ',
    'قل يا عبادي الذين اسرفوا على انفسهم لا تقنطوا من رحمة الله ان الله يغفر الذنوب جميعا انه هو الغفور الرحيم',
    '۞قُلۡ يَ<rule class=madda_normal>ـٰ</rule>عِبَادِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَسۡرَفُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ لَا تَ<rule class=qalaqah>قۡ</rule>نَطُو<rule class=slnt>اۡ</rule> م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَةِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَغۡفِرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذُّنُوبَ جَمِيعًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَفُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٥٣',
    53, 24, 6, 464, 401, 186, 'false'
  );
  
  -- Ayah 54 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4112,
    'وَأَنِیبُوۤا۟ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُوا۟ لَهُۥ مِن قَبۡلِ أَن یَأۡتِیَكُمُ ٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ',
    'وانيبوا الى ربكم واسلموا له من قبل ان ياتيكم العذاب ثم لا تنصرون',
    'وَأَنِيب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَكُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ ثُ<rule class=ghunnah>مّ</rule>َ لَا تُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٥٤',
    54, 24, 6, 464, 401, 186, 'false'
  );
  
  -- Ayah 55 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4113,
    'وَٱتَّبِعُوۤا۟ أَحۡسَنَ مَاۤ أُنزِلَ إِلَیۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن یَأۡتِیَكُمُ ٱلۡعَذَابُ بَغۡتَةࣰ وَأَنتُمۡ لَا تَشۡعُرُونَ',
    'واتبعوا احسن ما انزل اليكم من ربكم من قبل ان ياتيكم العذاب بغتة وانتم لا تشعرون',
    'وَ<rule class=ham_wasl>ٱ</rule>تَّبِع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَحۡسَنَ م<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَ إِلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَكُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ بَغۡتَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٥٥',
    55, 24, 6, 464, 401, 186, 'false'
  );
  
  -- Ayah 56 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4114,
    'أَن تَقُولَ نَفۡسࣱ یَـٰحَسۡرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِی جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّـٰخِرِینَ',
    'ان تقول نفس يا حسرتا على ما فرطت في جنب الله وان كنت لمن الساخرين',
    'أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولَ نَفۡ<rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=madda_normal>ـٰ</rule>حَسۡرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَ<rule class=iqlab>نۢب</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُ لَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>خِر<rule class=madda_permissible>ِي</rule>نَ ٥٦',
    56, 24, 6, 464, 401, 186, 'false'
  );
  
  -- Ayah 57 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4115,
    'أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِی لَكُنتُ مِنَ ٱلۡمُتَّقِینَ',
    'او تقول لو ان الله هداني لكنت من المتقين',
    'أَوۡ تَقُولَ لَوۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هَدَ<rule class=madda_normal>ٮٰ</rule>نِى لَكُ<rule class=ikhafa>نت</rule>ُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٥٧',
    57, 24, 6, 465, 401, 186, 'false'
  );
  
  -- Ayah 58 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4116,
    'أَوۡ تَقُولَ حِینَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِی كَرَّةࣰ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِینَ',
    'او تقول حين ترى العذاب لو ان لي كرة فاكون من المحسنين',
    'أَوۡ تَقُولَ حِينَ تَرَى <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ لَوۡ أَ<rule class=ghunnah>نّ</rule>َ لِى كَرَّ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َأَكُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ٥٨',
    58, 24, 6, 465, 401, 186, 'false'
  );
  
  -- Ayah 59 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4117,
    'بَلَىٰ قَدۡ جَاۤءَتۡكَ ءَایَـٰتِی فَكَذَّبۡتَ بِهَا وَٱسۡتَكۡبَرۡتَ وَكُنتَ مِنَ ٱلۡكَـٰفِرِینَ',
    'بلى قد جاءتك اياتي فكذبت بها واستكبرت وكنت من الكافرين',
    'بَلَىٰ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تِى فَكَذَّ<rule class=qalaqah>بۡ</rule>تَ بِهَا وَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرۡتَ وَكُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٥٩',
    59, 24, 6, 465, 401, 186, 'false'
  );
  
  -- Ayah 60 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4118,
    'وَیَوۡمَ ٱلۡقِیَـٰمَةِ تَرَى ٱلَّذِینَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَیۡسَ فِی جَهَنَّمَ مَثۡوࣰى لِّلۡمُتَكَبِّرِینَ',
    'ويوم القيامة ترى الذين كذبوا على الله وجوههم مسودة اليس في جهنم مثوى للمتكبرين',
    'وَيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ تَرَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَبُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وُجُوهُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡوَدَّةٌ‌ۚ أَلَيۡسَ فِى جَهَ<rule class=ghunnah>نّ</rule>َمَ مَثۡ<rule class=idgham_wo_ghunnah>وًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَكَبِّر<rule class=madda_permissible>ِي</rule>نَ ٦٠',
    60, 24, 6, 465, 401, 186, 'false'
  );
  
  -- Ayah 61 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4119,
    'وَیُنَجِّی ٱللَّهُ ٱلَّذِینَ ٱتَّقَوۡا۟ بِمَفَازَتِهِمۡ لَا یَمَسُّهُمُ ٱلسُّوۤءُ وَلَا هُمۡ یَحۡزَنُونَ',
    'وينجي الله الذين اتقوا بمفازتهم لا يمسهم السوء ولا هم يحزنون',
    'وَيُنَجِّى <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 24, 6, 465, 401, 186, 'false'
  );
  
  -- Ayah 62 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4120,
    'ٱللَّهُ خَـٰلِقُ كُلِّ شَیۡءࣲۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ وَكِیلࣱ',
    'الله خالق كل شيء وهو على كل شيء وكيل',
    'ٱللَّهُ خَ<rule class=madda_normal>ـٰ</rule>لِقُ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ عَلَىٰ كُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َك<rule class=madda_permissible>ِي</rule>لٌ ٦٢',
    62, 24, 6, 465, 401, 186, 'false'
  );
  
  -- Ayah 63 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4121,
    'لَّهُۥ مَقَالِیدُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۗ وَٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ',
    'له مقاليد السماوات والارض والذين كفروا بايات الله اولئك هم الخاسرون',
    'لَّهُ<rule class=madda_normal>ۥ</rule> مَقَالِيدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 24, 6, 465, 401, 186, 'false'
  );
  
  -- Ayah 64 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4122,
    'قُلۡ أَفَغَیۡرَ ٱللَّهِ تَأۡمُرُوۤنِّیۤ أَعۡبُدُ أَیُّهَا ٱلۡجَـٰهِلُونَ',
    'قل افغير الله تامروني اعبد ايها الجاهلون',
    'قُلۡ أَفَغَيۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ تَأۡمُر<rule class=madda_necessary>ُو</rule>ٓ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡبُدُ أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِل<rule class=madda_permissible>ُو</rule>نَ ٦٤',
    64, 24, 6, 465, 402, 186, 'false'
  );
  
  -- Ayah 65 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4123,
    'وَلَقَدۡ أُوحِیَ إِلَیۡكَ وَإِلَى ٱلَّذِینَ مِن قَبۡلِكَ لَىِٕنۡ أَشۡرَكۡتَ لَیَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَـٰسِرِینَ',
    'ولقد اوحي اليك والى الذين من قبلك لئن اشركت ليحبطن عملك ولتكونن من الخاسرين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أُوحِىَ إِلَيۡكَ وَإِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ لَئِنۡ أَشۡرَكۡتَ لَيَحۡبَطَ<rule class=ghunnah>نّ</rule>َ عَمَلُكَ وَلَتَكُونَ<rule class=ghunnah>نّ</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٦٥',
    65, 24, 6, 465, 402, 186, 'false'
  );
  
  -- Ayah 66 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4124,
    'بَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّـٰكِرِینَ',
    'بل الله فاعبد وكن من الشاكرين',
    'بَلِ <rule class=ham_wasl>ٱ</rule>للَّهَ فَ<rule class=ham_wasl>ٱ</rule>عۡبُ<rule class=qalaqah>دۡ</rule> وَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّ<rule class=madda_normal>ـٰ</rule>كِر<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 24, 6, 465, 402, 186, 'false'
  );
  
  -- Ayah 67 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4125,
    'وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدۡرِهِۦ وَٱلۡأَرۡضُ جَمِیعࣰا قَبۡضَتُهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ وَٱلسَّمَـٰوَ ٰ⁠تُ مَطۡوِیَّـٰتُۢ بِیَمِینِهِۦۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ',
    'وما قدروا الله حق قدره والارض جميعا قبضته يوم القيامة والسماوات مطويات بيمينه سبحانه وتعالى عما يشركون',
    'وَمَا قَدَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ حَقَّ قَ<rule class=qalaqah>دۡ</rule>رِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>ضَتُهُ<rule class=madda_normal>ۥ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ مَ<rule class=qalaqah>طۡ</rule>وِيَّ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تُۢ</rule> <rule class=iqlab>ب</rule>ِيَمِينِه<rule class=madda_normal>ِۦ</rule>‌ۚ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> وَتَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 24, 6, 465, 402, 186, 'false'
  );
  
  -- Ayah 68 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4126,
    'وَنُفِخَ فِی ٱلصُّورِ فَصَعِقَ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَن فِی ٱلۡأَرۡضِ إِلَّا مَن شَاۤءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِیهِ أُخۡرَىٰ فَإِذَا هُمۡ قِیَامࣱ یَنظُرُونَ',
    'ونفخ في الصور فصعق من في السماوات ومن في الارض الا من شاء الله ثم نفخ فيه اخرى فاذا هم قيام ينظرون',
    'وَنُفِخَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ فَصَعِقَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ نُفِخَ فِيهِ أُخۡرَىٰ فَإِذَا هُمۡ قِيَا<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 24, 6, 466, 402, 186, 'false'
  );
  
  -- Ayah 69 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4127,
    'وَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلۡكِتَـٰبُ وَجِا۟یۤءَ بِٱلنَّبِیِّـۧنَ وَٱلشُّهَدَاۤءِ وَقُضِیَ بَیۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا یُظۡلَمُونَ',
    'واشرقت الارض بنور ربها ووضع الكتاب وجيء بالنبيين والشهداء وقضي بينهم بالحق وهم لا يظلمون',
    'وَأَشۡرَقَتِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بُ وَجِ<rule class=slnt>اۡ</rule><rule class=madda_obligatory_mottasel>ىٓ</rule>ءَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِيِّـ<rule class=madda_normal>ـۧ</rule>نَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَقُضِىَ بَيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 24, 6, 466, 402, 186, 'false'
  );
  
  -- Ayah 70 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4128,
    'وَوُفِّیَتۡ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا یَفۡعَلُونَ',
    'ووفيت كل نفس ما عملت وهو اعلم بما يفعلون',
    'وَوُفِّيَتۡ كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 24, 6, 466, 402, 186, 'false'
  );
  
  -- Ayah 71 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4129,
    'وَسِیقَ ٱلَّذِینَ كَفَرُوۤا۟ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰۤ إِذَا جَاۤءُوهَا فُتِحَتۡ أَبۡوَ ٰ⁠بُهَا وَقَالَ لَهُمۡ خَزَنَتُهَاۤ أَلَمۡ یَأۡتِكُمۡ رُسُلࣱ مِّنكُمۡ یَتۡلُونَ عَلَیۡكُمۡ ءَایَـٰتِ رَبِّكُمۡ وَیُنذِرُونَكُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَاۚ قَالُوا۟ بَلَىٰ وَلَـٰكِنۡ حَقَّتۡ كَلِمَةُ ٱلۡعَذَابِ عَلَى ٱلۡكَـٰفِرِینَ',
    'وسيق الذين كفروا الى جهنم زمرا حتى اذا جاءوها فتحت ابوابها وقال لهم خزنتها الم ياتكم رسل منكم يتلون عليكم ايات ربكم وينذرونكم لقاء يومكم هذا قالوا بلى ولكن حقت كلمة العذاب على الكافرين',
    'وَسِيقَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ جَهَ<rule class=ghunnah>نّ</rule>َمَ زُمَرًا‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوهَا فُتِحَتۡ أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بُهَا وَقَالَ لَهُمۡ خَزَنَتُه<rule class=madda_obligatory_monfasel>َآ</rule> أَلَمۡ يَأۡتِكُمۡ رُسُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ يَتۡلُونَ عَلَيۡكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّكُمۡ وَيُ<rule class=ikhafa>نذ</rule>ِرُونَكُمۡ لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ يَوۡمِكُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۚ قَالُو<rule class=slnt>اۡ</rule> بَلَىٰ وَلَ<rule class=madda_normal>ـٰ</rule>كِنۡ حَقَّتۡ كَلِمَةُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٧١',
    71, 24, 6, 466, 403, 186, 'false'
  );
  
  -- Ayah 72 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4130,
    'قِیلَ ٱدۡخُلُوۤا۟ أَبۡوَ ٰ⁠بَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِینَ',
    'قيل ادخلوا ابواب جهنم خالدين فيها فبئس مثوى المتكبرين',
    'قِيلَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بَ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۖ فَبِئۡسَ مَثۡوَى <rule class=ham_wasl>ٱ</rule>لۡمُتَكَبِّر<rule class=madda_permissible>ِي</rule>نَ ٧٢',
    72, 24, 6, 466, 403, 186, 'false'
  );
  
  -- Ayah 73 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4131,
    'وَسِیقَ ٱلَّذِینَ ٱتَّقَوۡا۟ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ حَتَّىٰۤ إِذَا جَاۤءُوهَا وَفُتِحَتۡ أَبۡوَ ٰ⁠بُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَـٰمٌ عَلَیۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَـٰلِدِینَ',
    'وسيق الذين اتقوا ربهم الى الجنة زمرا حتى اذا جاءوها وفتحت ابوابها وقال لهم خزنتها سلام عليكم طبتم فادخلوها خالدين',
    'وَسِيقَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّقَوۡ<rule class=slnt>اۡ</rule> رَبَّهُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ زُمَرًا‌ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوهَا وَفُتِحَتۡ أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَ<rule class=madda_normal>ـٰ</rule>مٌ عَلَيۡكُمۡ طِ<rule class=qalaqah>بۡ</rule>تُمۡ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلُوهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ِي</rule>نَ ٧٣',
    73, 24, 6, 466, 403, 186, 'false'
  );
  
  -- Ayah 74 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4132,
    'وَقَالُوا۟ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ نَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَیۡثُ نَشَاۤءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَـٰمِلِینَ',
    'وقالوا الحمد لله الذي صدقنا وعده واورثنا الارض نتبوا من الجنة حيث نشاء فنعم اجر العاملين',
    'وَقَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى صَدَقَنَا وَعۡدَهُ<rule class=madda_normal>ۥ</rule> وَأَوۡرَثَنَا <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ نَتَبَوَّأُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ حَيۡثُ نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ فَنِعۡمَ أَ<rule class=qalaqah>جۡ</rule>رُ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>مِل<rule class=madda_permissible>ِي</rule>نَ ٧٤',
    74, 24, 6, 466, 403, 186, 'false'
  );
  
  -- Ayah 75 Surah Az-Zumar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    39,
    4133,
    'وَتَرَى ٱلۡمَلَـٰۤىِٕكَةَ حَاۤفِّینَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ یُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡۚ وَقُضِیَ بَیۡنَهُم بِٱلۡحَقِّۚ وَقِیلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'وترى الملائكة حافين من حول العرش يسبحون بحمد ربهم وقضي بينهم بالحق وقيل الحمد لله رب العالمين',
    'وَتَرَى <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةَ ح<rule class=madda_necessary>َا</rule>ٓفِّينَ مِنۡ حَوۡلِ <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ‌ۖ وَقُضِىَ بَيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَقِيلَ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٧٥',
    75, 24, 6, 467, 403, 186, 'false'
  );
  

-- Surah Ghafir
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (40, 'سُورَةُ غَافِرٍ', 'Ghafir', 'The Forgiver', 'Meccan', 85);

  -- Ayah 1 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4134,
    'حمۤ',
    'حم',
    'ح<rule class=madda_necessary>مٓ</rule> ١',
    1, 24, 6, 467, 404, 187, 'false'
  );
  
  -- Ayah 2 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4135,
    'تَنزِیلُ ٱلۡكِتَـٰبِ مِنَ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡعَلِیمِ',
    'تنزيل الكتاب من الله العزيز العليم',
    'تَ<rule class=ikhafa>نز</rule>ِيلُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مِ ٢',
    2, 24, 6, 467, 404, 187, 'false'
  );
  
  -- Ayah 3 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4136,
    'غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِیدِ ٱلۡعِقَابِ ذِی ٱلطَّوۡلِۖ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ إِلَیۡهِ ٱلۡمَصِیرُ',
    'غافر الذنب وقابل التوب شديد العقاب ذي الطول لا اله الا هو اليه المصير',
    'غَافِرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذَّ<rule class=iqlab>نۢب</rule>ِ وَقَابِلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡبِ شَدِيدِ <rule class=ham_wasl>ٱ</rule>لۡعِقَابِ ذِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّوۡلِۖ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَۖ إِلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٣',
    3, 24, 6, 467, 404, 187, 'false'
  );
  
  -- Ayah 4 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4137,
    'مَا یُجَـٰدِلُ فِیۤ ءَایَـٰتِ ٱللَّهِ إِلَّا ٱلَّذِینَ كَفَرُوا۟ فَلَا یَغۡرُرۡكَ تَقَلُّبُهُمۡ فِی ٱلۡبِلَـٰدِ',
    'ما يجادل في ايات الله الا الذين كفروا فلا يغررك تقلبهم في البلاد',
    'مَا يُجَ<rule class=madda_normal>ـٰ</rule>دِلُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡبِلَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>د</rule>ِ ٤',
    4, 24, 6, 467, 404, 187, 'false'
  );
  
  -- Ayah 5 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4138,
    'كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَٱلۡأَحۡزَابُ مِنۢ بَعۡدِهِمۡۖ وَهَمَّتۡ كُلُّ أُمَّةِۭ بِرَسُولِهِمۡ لِیَأۡخُذُوهُۖ وَجَـٰدَلُوا۟ بِٱلۡبَـٰطِلِ لِیُدۡحِضُوا۟ بِهِ ٱلۡحَقَّ فَأَخَذۡتُهُمۡۖ فَكَیۡفَ كَانَ عِقَابِ',
    'كذبت قبلهم قوم نوح والاحزاب من بعدهم وهمت كل امة برسولهم لياخذوه وجادلوا بالباطل ليدحضوا به الحق فاخذتهم فكيف كان عقاب',
    'كَذَّبَتۡ قَ<rule class=qalaqah>بۡ</rule>لَهُمۡ قَوۡمُ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لۡأَحۡزَابُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡۖ وَهَ<rule class=ghunnah>مّ</rule>َتۡ كُلُّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=iqlab>ةِۭ</rule> <rule class=iqlab>ب</rule>ِرَسُولِهِمۡ لِيَأۡخُذُوهُۖ وَجَ<rule class=madda_normal>ـٰ</rule>دَلُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلِ لِيُ<rule class=qalaqah>دۡ</rule>حِضُو<rule class=slnt>اۡ</rule> بِهِ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ فَأَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٥',
    5, 24, 6, 467, 404, 187, 'false'
  );
  
  -- Ayah 6 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4139,
    'وَكَذَ ٰ⁠لِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِینَ كَفَرُوۤا۟ أَنَّهُمۡ أَصۡحَـٰبُ ٱلنَّارِ',
    'وكذلك حقت كلمت ربك على الذين كفروا انهم اصحاب النار',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٦',
    6, 24, 6, 467, 404, 187, 'false'
  );
  
  -- Ayah 7 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4140,
    'ٱلَّذِینَ یَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ یُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَیُؤۡمِنُونَ بِهِۦ وَیَسۡتَغۡفِرُونَ لِلَّذِینَ ءَامَنُوا۟ۖ رَبَّنَا وَسِعۡتَ كُلَّ شَیۡءࣲ رَّحۡمَةࣰ وَعِلۡمࣰا فَٱغۡفِرۡ لِلَّذِینَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِیلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِیمِ',
    'الذين يحملون العرش ومن حوله يسبحون بحمد ربهم ويؤمنون به ويستغفرون للذين امنوا ربنا وسعت كل شيء رحمة وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم',
    'ٱلَّذِينَ يَحۡمِلُونَ <rule class=ham_wasl>ٱ</rule>لۡعَرۡشَ وَمَنۡ حَوۡلَهُ<rule class=madda_normal>ۥ</rule> يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِه<rule class=madda_normal>ِۦ</rule> وَيَسۡتَغۡفِرُونَ لِلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> رَبَّنَا وَسِعۡتَ كُلَّ ش<rule class=idgham_wo_ghunnah>َىۡءٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َعِلۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لِلَّذِينَ تَابُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> سَبِيلَكَ وَقِهِمۡ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ٧',
    7, 24, 6, 467, 404, 187, 'false'
  );
  
  -- Ayah 8 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4141,
    'رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّـٰتِ عَدۡنٍ ٱلَّتِی وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَاۤىِٕهِمۡ وَأَزۡوَ ٰ⁠جِهِمۡ وَذُرِّیَّـٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'ربنا وادخلهم جنات عدن التي وعدتهم ومن صلح من ابائهم وازواجهم وذرياتهم انك انت العزيز الحكيم',
    'رَبَّنَا وَأَ<rule class=qalaqah>دۡ</rule>خِلۡهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ عَ<rule class=qalaqah>دۡ</rule>نٍ <rule class=ham_wasl>ٱ</rule>لَّتِى وَعَ<rule class=idgham_mutajanisayn>د</rule>تَّهُمۡ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َلَحَ مِنۡ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ وَأَزۡو<rule class=madda_normal>ٰ</rule>جِهِمۡ وَذُرِّيَّ<rule class=madda_normal>ـٰ</rule>تِهِمۡۚ إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٨',
    8, 24, 6, 468, 404, 187, 'false'
  );
  
  -- Ayah 9 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4142,
    'وَقِهِمُ ٱلسَّیِّـَٔاتِۚ وَمَن تَقِ ٱلسَّیِّـَٔاتِ یَوۡمَىِٕذࣲ فَقَدۡ رَحِمۡتَهُۥۚ وَذَ ٰ⁠لِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'وقهم السيئات ومن تق السيئات يومئذ فقد رحمته وذلك هو الفوز العظيم',
    'وَقِهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِۚ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ف</rule>َقَ<rule class=qalaqah>دۡ</rule> رَحِمۡتَهُ<rule class=madda_normal>ۥ</rule>ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٩',
    9, 24, 6, 468, 404, 187, 'false'
  );
  
  -- Ayah 10 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4143,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ یُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِیمَـٰنِ فَتَكۡفُرُونَ',
    'ان الذين كفروا ينادون لمقت الله اكبر من مقتكم انفسكم اذ تدعون الى الايمان فتكفرون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> يُنَادَوۡنَ لَمَ<rule class=qalaqah>قۡ</rule>تُ <rule class=ham_wasl>ٱ</rule>للَّهِ أَكۡبَرُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>قۡ</rule>تِكُمۡ أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ إِذۡ تُ<rule class=qalaqah>دۡ</rule>عَوۡنَ إِلَى <rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ فَتَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 24, 6, 468, 405, 187, 'false'
  );
  
  -- Ayah 11 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4144,
    'قَالُوا۟ رَبَّنَاۤ أَمَتَّنَا ٱثۡنَتَیۡنِ وَأَحۡیَیۡتَنَا ٱثۡنَتَیۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُوجࣲ مِّن سَبِیلࣲ',
    'قالوا ربنا امتنا اثنتين واحييتنا اثنتين فاعترفنا بذنوبنا فهل الى خروج من سبيل',
    'قَالُو<rule class=slnt>اۡ</rule> رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَمَتَّنَا <rule class=ham_wasl>ٱ</rule>ثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا <rule class=ham_wasl>ٱ</rule>ثۡنَتَيۡنِ فَ<rule class=ham_wasl>ٱ</rule>عۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُو<rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َب<rule class=madda_permissible>ِي</rule>لٍ ١١',
    11, 24, 6, 468, 405, 187, 'false'
  );
  
  -- Ayah 12 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4145,
    'ذَ ٰ⁠لِكُم بِأَنَّهُۥۤ إِذَا دُعِیَ ٱللَّهُ وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن یُشۡرَكۡ بِهِۦ تُؤۡمِنُوا۟ۚ فَٱلۡحُكۡمُ لِلَّهِ ٱلۡعَلِیِّ ٱلۡكَبِیرِ',
    'ذلكم بانه اذا دعي الله وحده كفرتم وان يشرك به تؤمنوا فالحكم لله العلي الكبير',
    'ذ<rule class=madda_normal>ٰ</rule>لِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِذَا دُعِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَحۡدَهُ<rule class=madda_normal>ۥ</rule> كَفَرۡتُمۡۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُشۡرَكۡ بِه<rule class=madda_normal>ِۦ</rule> تُؤۡمِنُو<rule class=slnt>اۡۚ</rule> فَ<rule class=ham_wasl>ٱ</rule>لۡحُكۡمُ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡعَلِىِّ <rule class=ham_wasl>ٱ</rule>لۡكَب<rule class=madda_permissible>ِي</rule>رِ ١٢',
    12, 24, 6, 468, 405, 187, 'false'
  );
  
  -- Ayah 13 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4146,
    'هُوَ ٱلَّذِی یُرِیكُمۡ ءَایَـٰتِهِۦ وَیُنَزِّلُ لَكُم مِّنَ ٱلسَّمَاۤءِ رِزۡقࣰاۚ وَمَا یَتَذَكَّرُ إِلَّا مَن یُنِیبُ',
    'هو الذي يريكم اياته وينزل لكم من السماء رزقا وما يتذكر الا من ينيب',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُرِيكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَيُنَزِّلُ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رِزۡ<rule class=idgham_ghunnah>قًاۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا يَتَذَكَّرُ إِلَّا م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ُ ١٣',
    13, 24, 6, 468, 405, 187, 'false'
  );
  
  -- Ayah 14 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4147,
    'فَٱدۡعُوا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ وَلَوۡ كَرِهَ ٱلۡكَـٰفِرُونَ',
    'فادعوا الله مخلصين له الدين ولو كره الكافرون',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡلِصِينَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ وَلَوۡ كَرِهَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 24, 6, 468, 405, 187, 'false'
  );
  
  -- Ayah 15 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4148,
    'رَفِیعُ ٱلدَّرَجَـٰتِ ذُو ٱلۡعَرۡشِ یُلۡقِی ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦ لِیُنذِرَ یَوۡمَ ٱلتَّلَاقِ',
    'رفيع الدرجات ذو العرش يلقي الروح من امره على من يشاء من عباده لينذر يوم التلاق',
    'رَفِيعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّرَجَ<rule class=madda_normal>ـٰ</rule>تِ ذُو <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ يُلۡقِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّوحَ مِنۡ أَمۡرِه<rule class=madda_normal>ِۦ</rule> عَلَىٰ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule> لِيُ<rule class=ikhafa>نذ</rule>ِرَ يَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّل<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ِ ١٥',
    15, 24, 6, 468, 405, 187, 'false'
  );
  
  -- Ayah 16 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4149,
    'یَوۡمَ هُم بَـٰرِزُونَۖ لَا یَخۡفَىٰ عَلَى ٱللَّهِ مِنۡهُمۡ شَیۡءࣱۚ لِّمَنِ ٱلۡمُلۡكُ ٱلۡیَوۡمَۖ لِلَّهِ ٱلۡوَ ٰ⁠حِدِ ٱلۡقَهَّارِ',
    'يوم هم بارزون لا يخفى على الله منهم شيء لمن الملك اليوم لله الواحد القهار',
    'يَوۡمَ ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َ<rule class=madda_normal>ـٰ</rule>رِزُونَۖ لَا يَخۡفَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ مِنۡهُمۡ ش<rule class=idgham_wo_ghunnah>َىۡءٌۚ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَنِ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَۖ لِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡو<rule class=madda_normal>ٰ</rule>حِدِ <rule class=ham_wasl>ٱ</rule>لۡقَهّ<rule class=madda_permissible>َا</rule>رِ ١٦',
    16, 24, 6, 468, 405, 187, 'false'
  );
  
  -- Ayah 17 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4150,
    'ٱلۡیَوۡمَ تُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡۚ لَا ظُلۡمَ ٱلۡیَوۡمَۚ إِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ',
    'اليوم تجزى كل نفس بما كسبت لا ظلم اليوم ان الله سريع الحساب',
    'ٱلۡيَوۡمَ تُ<rule class=qalaqah>جۡ</rule>زَىٰ كُلُّ نَفۡ<rule class=iqlab>سِۭ</rule> <rule class=iqlab>ب</rule>ِمَا كَسَبَتۡۚ لَا ظُلۡمَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَرِيعُ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ١٧',
    17, 24, 6, 469, 405, 187, 'false'
  );
  
  -- Ayah 18 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4151,
    'وَأَنذِرۡهُمۡ یَوۡمَ ٱلۡـَٔازِفَةِ إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ كَـٰظِمِینَۚ مَا لِلظَّـٰلِمِینَ مِنۡ حَمِیمࣲ وَلَا شَفِیعࣲ یُطَاعُ',
    'وانذرهم يوم الازفة اذ القلوب لدى الحناجر كاظمين ما للظالمين من حميم ولا شفيع يطاع',
    'وَأَ<rule class=ikhafa>نذ</rule>ِرۡهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡأَزِفَةِ إِذِ <rule class=ham_wasl>ٱ</rule>لۡقُلُوبُ لَدَى <rule class=ham_wasl>ٱ</rule>لۡحَنَاجِرِ كَ<rule class=madda_normal>ـٰ</rule>ظِمِينَۚ مَا لِلظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ مِنۡ حَمِي<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا شَفِي<rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُط<rule class=madda_permissible>َا</rule>عُ ١٨',
    18, 24, 6, 469, 405, 187, 'false'
  );
  
  -- Ayah 19 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4152,
    'یَعۡلَمُ خَاۤىِٕنَةَ ٱلۡأَعۡیُنِ وَمَا تُخۡفِی ٱلصُّدُورُ',
    'يعلم خائنة الاعين وما تخفي الصدور',
    'يَعۡلَمُ خ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنَةَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡيُنِ وَمَا تُخۡفِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رُ ١٩',
    19, 24, 6, 469, 405, 187, 'false'
  );
  
  -- Ayah 20 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4153,
    'وَٱللَّهُ یَقۡضِی بِٱلۡحَقِّۖ وَٱلَّذِینَ یَدۡعُونَ مِن دُونِهِۦ لَا یَقۡضُونَ بِشَیۡءٍۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ',
    'والله يقضي بالحق والذين يدعون من دونه لا يقضون بشيء ان الله هو السميع البصير',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=qalaqah>قۡ</rule>ضِى بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> لَا يَ<rule class=qalaqah>قۡ</rule>ضُونَ بِشَىۡءٍۗ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡبَص<rule class=madda_permissible>ِي</rule>رُ ٢٠',
    20, 24, 6, 469, 405, 187, 'false'
  );
  
  -- Ayah 21 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4154,
    '۞ أَوَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ كَانُوا۟ مِن قَبۡلِهِمۡۚ كَانُوا۟ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةࣰ وَءَاثَارࣰا فِی ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقࣲ',
    'اولم يسيروا في الارض فينظروا كيف كان عاقبة الذين كانوا من قبلهم كانوا هم اشد منهم قوة واثارا في الارض فاخذهم الله بذنوبهم وما كان لهم من الله من واق',
    '۞أَوَلَمۡ يَسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَيَ<rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَانُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡۚ كَانُو<rule class=slnt>اۡ</rule> هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َءَاثَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَأَخَذَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ بِذُنُوبِهِمۡ وَمَا كَانَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ٍ ٢١',
    21, 24, 6, 469, 406, 188, 'false'
  );
  
  -- Ayah 22 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4155,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمۡ كَانَت تَّأۡتِیهِمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُۚ إِنَّهُۥ قَوِیࣱّ شَدِیدُ ٱلۡعِقَابِ',
    'ذلك بانهم كانت تاتيهم رسلهم بالبينات فكفروا فاخذهم الله انه قوي شديد العقاب',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَانَت تَّأۡتِيهِمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَكَفَرُو<rule class=slnt>اۡ</rule> فَأَخَذَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> قَوِ<rule class=ikhafa>ىٌّ</rule> <rule class=ikhafa>ش</rule>َدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢٢',
    22, 24, 6, 469, 406, 188, 'false'
  );
  
  -- Ayah 23 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4156,
    'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔایَـٰتِنَا وَسُلۡطَـٰنࣲ مُّبِینٍ',
    'ولقد ارسلنا موسى باياتنا وسلطان مبين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا مُوسَىٰ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٢٣',
    23, 24, 6, 469, 406, 188, 'false'
  );
  
  -- Ayah 24 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4157,
    'إِلَىٰ فِرۡعَوۡنَ وَهَـٰمَـٰنَ وَقَـٰرُونَ فَقَالُوا۟ سَـٰحِرࣱ كَذَّابࣱ',
    'الى فرعون وهامان وقارون فقالوا ساحر كذاب',
    'إِلَىٰ فِرۡعَوۡنَ وَهَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_normal>ـٰ</rule>نَ وَقَ<rule class=madda_normal>ـٰ</rule>رُونَ فَقَالُو<rule class=slnt>اۡ</rule> سَ<rule class=madda_normal>ـٰ</rule>حِ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ك</rule>َذّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٢٤',
    24, 24, 6, 469, 406, 188, 'false'
  );
  
  -- Ayah 25 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4158,
    'فَلَمَّا جَاۤءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُوا۟ ٱقۡتُلُوۤا۟ أَبۡنَاۤءَ ٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ وَٱسۡتَحۡیُوا۟ نِسَاۤءَهُمۡۚ وَمَا كَیۡدُ ٱلۡكَـٰفِرِینَ إِلَّا فِی ضَلَـٰلࣲ',
    'فلما جاءهم بالحق من عندنا قالوا اقتلوا ابناء الذين امنوا معه واستحيوا نساءهم وما كيد الكافرين الا في ضلال',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ مِنۡ عِ<rule class=ikhafa>ند</rule>ِنَا قَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>سۡتَحۡيُو<rule class=slnt>اۡ</rule> نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡۚ وَمَا كَيۡدُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ إِلَّا فِى ضَلَ<rule class=madda_permissible>ـٰ</rule>لٍ ٢٥',
    25, 24, 6, 469, 406, 188, 'false'
  );
  
  -- Ayah 26 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4159,
    'وَقَالَ فِرۡعَوۡنُ ذَرُونِیۤ أَقۡتُلۡ مُوسَىٰ وَلۡیَدۡعُ رَبَّهُۥۤۖ إِنِّیۤ أَخَافُ أَن یُبَدِّلَ دِینَكُمۡ أَوۡ أَن یُظۡهِرَ فِی ٱلۡأَرۡضِ ٱلۡفَسَادَ',
    'وقال فرعون ذروني اقتل موسى وليدع ربه اني اخاف ان يبدل دينكم او ان يظهر في الارض الفساد',
    'وَقَالَ فِرۡعَوۡنُ ذَرُون<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>قۡ</rule>تُلۡ مُوسَىٰ وَلۡيَ<rule class=qalaqah>دۡ</rule>عُ رَبَّهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُبَدِّلَ دِينَكُمۡ أَوۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُظۡهِرَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ <rule class=ham_wasl>ٱ</rule>لۡفَس<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>َ ٢٦',
    26, 24, 6, 470, 406, 188, 'false'
  );
  
  -- Ayah 27 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4160,
    'وَقَالَ مُوسَىٰۤ إِنِّی عُذۡتُ بِرَبِّی وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرࣲ لَّا یُؤۡمِنُ بِیَوۡمِ ٱلۡحِسَابِ',
    'وقال موسى اني عذت بربي وربكم من كل متكبر لا يؤمن بيوم الحساب',
    'وَقَالَ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>ِى عُذۡتُ بِرَبِّى وَرَبِّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ مُتَكَبِّ<rule class=idgham_wo_ghunnah>رٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِنُ بِيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡحِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٢٧',
    27, 24, 6, 470, 406, 188, 'false'
  );
  
  -- Ayah 28 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4161,
    'وَقَالَ رَجُلࣱ مُّؤۡمِنࣱ مِّنۡ ءَالِ فِرۡعَوۡنَ یَكۡتُمُ إِیمَـٰنَهُۥۤ أَتَقۡتُلُونَ رَجُلًا أَن یَقُولَ رَبِّیَ ٱللَّهُ وَقَدۡ جَاۤءَكُم بِٱلۡبَیِّنَـٰتِ مِن رَّبِّكُمۡۖ وَإِن یَكُ كَـٰذِبࣰا فَعَلَیۡهِ كَذِبُهُۥۖ وَإِن یَكُ صَادِقࣰا یُصِبۡكُم بَعۡضُ ٱلَّذِی یَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا یَهۡدِی مَنۡ هُوَ مُسۡرِفࣱ كَذَّابࣱ',
    'وقال رجل مؤمن من ال فرعون يكتم ايمانه اتقتلون رجلا ان يقول ربي الله وقد جاءكم بالبينات من ربكم وان يك كاذبا فعليه كذبه وان يك صادقا يصبكم بعض الذي يعدكم ان الله لا يهدي من هو مسرف كذاب',
    'وَقَالَ رَجُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِ<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَ<rule class=madda_normal>ـٰ</rule>نَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَتَ<rule class=qalaqah>قۡ</rule>تُلُونَ رَجُلاً أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولَ رَبِّىَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َكُ كَ<rule class=madda_normal>ـٰ</rule>ذِ<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ف</rule>َعَلَيۡهِ كَذِبُهُ<rule class=madda_normal>ۥ</rule>ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َكُ صَادِ<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>ي</rule>ُصِ<rule class=qalaqah>بۡ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضُ <rule class=ham_wasl>ٱ</rule>لَّذِى يَعِدُكُمۡۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى مَنۡ هُوَ مُسۡرِ<rule class=ikhafa>فٌ</rule> <rule class=ikhafa>ك</rule>َذّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٢٨',
    28, 24, 6, 470, 407, 188, 'false'
  );
  
  -- Ayah 29 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4162,
    'یَـٰقَوۡمِ لَكُمُ ٱلۡمُلۡكُ ٱلۡیَوۡمَ ظَـٰهِرِینَ فِی ٱلۡأَرۡضِ فَمَن یَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ إِن جَاۤءَنَاۚ قَالَ فِرۡعَوۡنُ مَاۤ أُرِیكُمۡ إِلَّا مَاۤ أَرَىٰ وَمَاۤ أَهۡدِیكُمۡ إِلَّا سَبِیلَ ٱلرَّشَادِ',
    'يا قوم لكم الملك اليوم ظاهرين في الارض فمن ينصرنا من باس الله ان جاءنا قال فرعون ما اريكم الا ما ارى وما اهديكم الا سبيل الرشاد',
    'يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ ظَ<rule class=madda_normal>ـٰ</rule>هِرِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرُنَا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َأۡسِ <rule class=ham_wasl>ٱ</rule>للَّهِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَاۚ قَالَ فِرۡعَوۡنُ م<rule class=madda_obligatory_monfasel>َآ</rule> أُرِيكُمۡ إِلَّا م<rule class=madda_obligatory_monfasel>َآ</rule> أَرَىٰ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَهۡدِيكُمۡ إِلَّا سَبِيلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّش<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٢٩',
    29, 24, 6, 470, 407, 188, 'false'
  );
  
  -- Ayah 30 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4163,
    'وَقَالَ ٱلَّذِیۤ ءَامَنَ یَـٰقَوۡمِ إِنِّیۤ أَخَافُ عَلَیۡكُم مِّثۡلَ یَوۡمِ ٱلۡأَحۡزَابِ',
    'وقال الذي امن يا قوم اني اخاف عليكم مثل يوم الاحزاب',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَامَنَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّثۡلَ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَحۡز<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٣٠',
    30, 24, 6, 470, 407, 188, 'false'
  );
  
  -- Ayah 31 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4164,
    'مِثۡلَ دَأۡبِ قَوۡمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَٱلَّذِینَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ یُرِیدُ ظُلۡمࣰا لِّلۡعِبَادِ',
    'مثل داب قوم نوح وعاد وثمود والذين من بعدهم وما الله يريد ظلما للعباد',
    'مِثۡلَ دَأۡبِ قَوۡمِ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَا<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َثَمُودَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡۚ وَمَا <rule class=ham_wasl>ٱ</rule>للَّهُ يُرِيدُ ظُلۡ<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعِب<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٣١',
    31, 24, 6, 470, 407, 188, 'false'
  );
  
  -- Ayah 32 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4165,
    'وَیَـٰقَوۡمِ إِنِّیۤ أَخَافُ عَلَیۡكُمۡ یَوۡمَ ٱلتَّنَادِ',
    'ويا قوم اني اخاف عليكم يوم التناد',
    'وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ عَلَيۡكُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّن<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٣٢',
    32, 24, 6, 470, 407, 188, 'false'
  );
  
  -- Ayah 33 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4166,
    'یَوۡمَ تُوَلُّونَ مُدۡبِرِینَ مَا لَكُم مِّنَ ٱللَّهِ مِنۡ عَاصِمࣲۗ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ',
    'يوم تولون مدبرين ما لكم من الله من عاصم ومن يضلل الله فما له من هاد',
    'يَوۡمَ تُوَلُّونَ مُ<rule class=qalaqah>دۡ</rule>بِرِينَ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مِنۡ عَاصِ<rule class=idgham_ghunnah>مٍۗ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَمَا لَهُ<rule class=madda_normal>ۥ</rule> مِنۡ ه<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ٍ ٣٣',
    33, 24, 6, 470, 407, 188, 'false'
  );
  
  -- Ayah 34 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4167,
    'وَلَقَدۡ جَاۤءَكُمۡ یُوسُفُ مِن قَبۡلُ بِٱلۡبَیِّنَـٰتِ فَمَا زِلۡتُمۡ فِی شَكࣲّ مِّمَّا جَاۤءَكُم بِهِۦۖ حَتَّىٰۤ إِذَا هَلَكَ قُلۡتُمۡ لَن یَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولࣰاۚ كَذَ ٰ⁠لِكَ یُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفࣱ مُّرۡتَابٌ',
    'ولقد جاءكم يوسف من قبل بالبينات فما زلتم في شك مما جاءكم به حتى اذا هلك قلتم لن يبعث الله من بعده رسولا كذلك يضل الله من هو مسرف مرتاب',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ يُوسُفُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَمَا زِلۡتُمۡ فِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>ۖ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا هَلَكَ قُلۡتُمۡ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>عَثَ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule> رَسُوۚل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ يُضِلُّ <rule class=ham_wasl>ٱ</rule>للَّهُ مَنۡ هُوَ مُسۡرِ<rule class=idgham_ghunnah>فٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّرۡت<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٌ ٣٤',
    34, 24, 6, 471, 407, 188, 'false'
  );
  
  -- Ayah 35 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4168,
    'ٱلَّذِینَ یُجَـٰدِلُونَ فِیۤ ءَایَـٰتِ ٱللَّهِ بِغَیۡرِ سُلۡطَـٰنٍ أَتَىٰهُمۡۖ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِینَ ءَامَنُوا۟ۚ كَذَ ٰ⁠لِكَ یَطۡبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلۡبِ مُتَكَبِّرࣲ جَبَّارࣲ',
    'الذين يجادلون في ايات الله بغير سلطان اتاهم كبر مقتا عند الله وعند الذين امنوا كذلك يطبع الله على كل قلب متكبر جبار',
    'ٱلَّذِينَ يُجَ<rule class=madda_normal>ـٰ</rule>دِلُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِغَيۡرِ سُلۡطَ<rule class=madda_normal>ـٰ</rule>نٍ أَتَ<rule class=madda_normal>ـٰ</rule>هُمۡۖ كَبُرَ مَ<rule class=qalaqah>قۡ</rule>تًا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَعِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡۚ</rule> كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَ<rule class=qalaqah>طۡ</rule>بَعُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ قَلۡبِ مُتَكَبِّ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ج</rule>َبّ<rule class=madda_permissible>َا</rule>رٍ ٣٥',
    35, 24, 6, 471, 407, 188, 'false'
  );
  
  -- Ayah 36 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4169,
    'وَقَالَ فِرۡعَوۡنُ یَـٰهَـٰمَـٰنُ ٱبۡنِ لِی صَرۡحࣰا لَّعَلِّیۤ أَبۡلُغُ ٱلۡأَسۡبَـٰبَ',
    'وقال فرعون يا هامان ابن لي صرحا لعلي ابلغ الاسباب',
    'وَقَالَ فِرۡعَوۡنُ يَ<rule class=madda_normal>ـٰ</rule>هَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_normal>ـٰ</rule>نُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ لِى صَرۡ<rule class=idgham_wo_ghunnah>حًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>بۡ</rule>لُغُ <rule class=ham_wasl>ٱ</rule>لۡأَسۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>َ ٣٦',
    36, 24, 6, 471, 407, 188, 'false'
  );
  
  -- Ayah 37 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4170,
    'أَسۡبَـٰبَ ٱلسَّمَـٰوَ ٰ⁠تِ فَأَطَّلِعَ إِلَىٰۤ إِلَـٰهِ مُوسَىٰ وَإِنِّی لَأَظُنُّهُۥ كَـٰذِبࣰاۚ وَكَذَ ٰ⁠لِكَ زُیِّنَ لِفِرۡعَوۡنَ سُوۤءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِیلِۚ وَمَا كَیۡدُ فِرۡعَوۡنَ إِلَّا فِی تَبَابࣲ',
    'اسباب السماوات فاطلع الى اله موسى واني لاظنه كاذبا وكذلك زين لفرعون سوء عمله وصد عن السبيل وما كيد فرعون الا في تباب',
    'أَسۡبَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ فَأَطَّلِعَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هِ مُوسَىٰ وَإِ<rule class=ghunnah>نّ</rule>ِى لَأَظُ<rule class=ghunnah>نّ</rule>ُهُ<rule class=madda_normal>ۥ</rule> كَ<rule class=madda_normal>ـٰ</rule>ذِ<rule class=idgham_ghunnah>بًاۚ</rule> <rule class=idgham_ghunnah>و</rule>َكَذ<rule class=madda_normal>ٰ</rule>لِكَ زُيِّنَ لِفِرۡعَوۡنَ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ عَمَلِه<rule class=madda_normal>ِۦ</rule> وَصُدَّ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِۚ وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِى تَب<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٣٧',
    37, 24, 6, 471, 407, 188, 'false'
  );
  
  -- Ayah 38 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4171,
    'وَقَالَ ٱلَّذِیۤ ءَامَنَ یَـٰقَوۡمِ ٱتَّبِعُونِ أَهۡدِكُمۡ سَبِیلَ ٱلرَّشَادِ',
    'وقال الذي امن يا قوم اتبعون اهدكم سبيل الرشاد',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَامَنَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ <rule class=ham_wasl>ٱ</rule>تَّبِعُونِ أَهۡدِكُمۡ سَبِيلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّش<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٣٨',
    38, 24, 6, 471, 408, 188, 'false'
  );
  
  -- Ayah 39 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4172,
    'یَـٰقَوۡمِ إِنَّمَا هَـٰذِهِ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا مَتَـٰعࣱ وَإِنَّ ٱلۡـَٔاخِرَةَ هِیَ دَارُ ٱلۡقَرَارِ',
    'يا قوم انما هذه الحياة الدنيا متاع وان الاخرة هي دار القرار',
    'يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ghunnah>نّ</rule>َمَا هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا مَتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةَ هِىَ دَارُ <rule class=ham_wasl>ٱ</rule>لۡقَر<rule class=madda_permissible>َا</rule>رِ ٣٩',
    39, 24, 6, 471, 408, 188, 'false'
  );
  
  -- Ayah 40 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4173,
    'مَنۡ عَمِلَ سَیِّئَةࣰ فَلَا یُجۡزَىٰۤ إِلَّا مِثۡلَهَاۖ وَمَنۡ عَمِلَ صَـٰلِحࣰا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَأُو۟لَـٰۤىِٕكَ یَدۡخُلُونَ ٱلۡجَنَّةَ یُرۡزَقُونَ فِیهَا بِغَیۡرِ حِسَابࣲ',
    'من عمل سيئة فلا يجزى الا مثلها ومن عمل صالحا من ذكر او انثى وهو مؤمن فاولئك يدخلون الجنة يرزقون فيها بغير حساب',
    'مَنۡ عَمِلَ سَيِّئَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َلَا يُ<rule class=qalaqah>جۡ</rule>زَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَّا مِثۡلَهَاۖ وَمَنۡ عَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َكَرٍ أَوۡ أُ<rule class=ikhafa>نث</rule>َىٰ وَهُوَ مُؤۡمِ<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يَ<rule class=qalaqah>دۡ</rule>خُلُونَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ٤٠',
    40, 24, 6, 471, 408, 188, 'false'
  );
  
  -- Ayah 41 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4174,
    '۞ وَیَـٰقَوۡمِ مَا لِیۤ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِیۤ إِلَى ٱلنَّارِ',
    'ويا قوم ما لي ادعوكم الى النجاة وتدعونني الى النار',
    '۞وَيَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ مَا ل<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>دۡ</rule>عُوكُمۡ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َجَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ وَتَ<rule class=qalaqah>دۡ</rule>عُونَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٤١',
    41, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 42 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4175,
    'تَدۡعُونَنِی لِأَكۡفُرَ بِٱللَّهِ وَأُشۡرِكَ بِهِۦ مَا لَیۡسَ لِی بِهِۦ عِلۡمࣱ وَأَنَا۠ أَدۡعُوكُمۡ إِلَى ٱلۡعَزِیزِ ٱلۡغَفَّـٰرِ',
    'تدعونني لاكفر بالله واشرك به ما ليس لي به علم وانا ادعوكم الى العزيز الغفار',
    'تَ<rule class=qalaqah>دۡ</rule>عُونَنِى لِأَكۡفُرَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَأُشۡرِكَ بِه<rule class=madda_normal>ِۦ</rule> مَا لَيۡسَ لِى بِه<rule class=madda_normal>ِۦ</rule> عِلۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَنَاۡ أَ<rule class=qalaqah>دۡ</rule>عُوكُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡغَفَّ<rule class=madda_permissible>ـٰ</rule>رِ ٤٢',
    42, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 43 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4176,
    'لَا جَرَمَ أَنَّمَا تَدۡعُونَنِیۤ إِلَیۡهِ لَیۡسَ لَهُۥ دَعۡوَةࣱ فِی ٱلدُّنۡیَا وَلَا فِی ٱلۡـَٔاخِرَةِ وَأَنَّ مَرَدَّنَاۤ إِلَى ٱللَّهِ وَأَنَّ ٱلۡمُسۡرِفِینَ هُمۡ أَصۡحَـٰبُ ٱلنَّارِ',
    'لا جرم انما تدعونني اليه ليس له دعوة في الدنيا ولا في الاخرة وان مردنا الى الله وان المسرفين هم اصحاب النار',
    'لَا جَرَمَ أَ<rule class=ghunnah>نّ</rule>َمَا تَ<rule class=qalaqah>دۡ</rule>عُونَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ لَيۡسَ لَهُ<rule class=madda_normal>ۥ</rule> دَعۡوَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَلَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ وَأَ<rule class=ghunnah>نّ</rule>َ مَرَدَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُسۡرِفِينَ هُمۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٤٣',
    43, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 44 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4177,
    'فَسَتَذۡكُرُونَ مَاۤ أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡرِیۤ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِیرُۢ بِٱلۡعِبَادِ',
    'فستذكرون ما اقول لكم وافوض امري الى الله ان الله بصير بالعباد',
    'فَسَتَذۡكُرُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡر<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بَصِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعِب<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٤٤',
    44, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 45 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4178,
    'فَوَقَىٰهُ ٱللَّهُ سَیِّـَٔاتِ مَا مَكَرُوا۟ۖ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوۤءُ ٱلۡعَذَابِ',
    'فوقاه الله سيئات ما مكروا وحاق بال فرعون سوء العذاب',
    'فَوَقَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>للَّهُ سَيِّـَٔـاتِ مَا مَكَرُو<rule class=slnt>اۡۖ</rule> وَحَاقَ بِـَٔـالِ فِرۡعَوۡنَ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡعَذ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٤٥',
    45, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 46 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4179,
    'ٱلنَّارُ یُعۡرَضُونَ عَلَیۡهَا غُدُوࣰّا وَعَشِیࣰّاۚ وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوۤا۟ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ',
    'النار يعرضون عليها غدوا وعشيا ويوم تقوم الساعة ادخلوا ال فرعون اشد العذاب',
    'ٱ<rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ يُعۡرَضُونَ عَلَيۡهَا غُدُو<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َعَشِي<rule class=idgham_ghunnah>ًّاۖ</rule> <rule class=idgham_ghunnah>و</rule>َيَوۡمَ تَقُومُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ أَ<rule class=qalaqah>دۡ</rule>خِل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَالَ فِرۡعَوۡنَ أَشَدَّ <rule class=ham_wasl>ٱ</rule>لۡعَذ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٤٦',
    46, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 47 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4180,
    'وَإِذۡ یَتَحَاۤجُّونَ فِی ٱلنَّارِ فَیَقُولُ ٱلضُّعَفَـٰۤؤُا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوۤا۟ إِنَّا كُنَّا لَكُمۡ تَبَعࣰا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِیبࣰا مِّنَ ٱلنَّارِ',
    'واذ يتحاجون في النار فيقول الضعفاء للذين استكبروا انا كنا لكم تبعا فهل انتم مغنون عنا نصيبا من النار',
    'وَإِذۡ يَتَح<rule class=madda_necessary>َا</rule>ٓجُّونَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ فَيَقُولُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضُّعَفَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> لِلَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا لَكُمۡ تَبَ<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َهَلۡ أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّغۡنُونَ عَ<rule class=ghunnah>نّ</rule>َا نَصِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٤٧',
    47, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 48 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4181,
    'قَالَ ٱلَّذِینَ ٱسۡتَكۡبَرُوۤا۟ إِنَّا كُلࣱّ فِیهَاۤ إِنَّ ٱللَّهَ قَدۡ حَكَمَ بَیۡنَ ٱلۡعِبَادِ',
    'قال الذين استكبروا انا كل فيها ان الله قد حكم بين العباد',
    'قَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ikhafa>لٌّ</rule> <rule class=ikhafa>ف</rule>ِيه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَ<rule class=qalaqah>دۡ</rule> حَكَمَ بَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡعِب<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ٤٨',
    48, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 49 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4182,
    'وَقَالَ ٱلَّذِینَ فِی ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدۡعُوا۟ رَبَّكُمۡ یُخَفِّفۡ عَنَّا یَوۡمࣰا مِّنَ ٱلۡعَذَابِ',
    'وقال الذين في النار لخزنة جهنم ادعوا ربكم يخفف عنا يوما من العذاب',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ لِخَزَنَةِ جَهَ<rule class=ghunnah>نّ</rule>َمَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ يُخَفِّفۡ عَ<rule class=ghunnah>نّ</rule>َا يَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعَذ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٤٩',
    49, 24, 6, 472, 408, 189, 'false'
  );
  
  -- Ayah 50 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4183,
    'قَالُوۤا۟ أَوَلَمۡ تَكُ تَأۡتِیكُمۡ رُسُلُكُم بِٱلۡبَیِّنَـٰتِۖ قَالُوا۟ بَلَىٰۚ قَالُوا۟ فَٱدۡعُوا۟ۗ وَمَا دُعَـٰۤؤُا۟ ٱلۡكَـٰفِرِینَ إِلَّا فِی ضَلَـٰلٍ',
    'قالوا اولم تك تاتيكم رسلكم بالبينات قالوا بلى قالوا فادعوا وما دعاء الكافرين الا في ضلال',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوَلَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِۖ قَالُو<rule class=slnt>اۡ</rule> بَلَىٰۚ قَالُو<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡۗ</rule> وَمَا دُعَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ إِلَّا فِى ضَلَ<rule class=madda_permissible>ـٰ</rule>لٍ ٥٠',
    50, 24, 6, 473, 408, 189, 'false'
  );
  
  -- Ayah 51 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4184,
    'إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِینَ ءَامَنُوا۟ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَیَوۡمَ یَقُومُ ٱلۡأَشۡهَـٰدُ',
    'انا لننصر رسلنا والذين امنوا في الحياة الدنيا ويوم يقوم الاشهاد',
    'إِ<rule class=ghunnah>نّ</rule>َا لَنَ<rule class=ikhafa>نص</rule>ُرُ رُسُلَنَا وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَيَوۡمَ يَقُومُ <rule class=ham_wasl>ٱ</rule>لۡأَشۡهَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>د</rule>ُ ٥١',
    51, 24, 6, 473, 409, 189, 'false'
  );
  
  -- Ayah 52 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4185,
    'یَوۡمَ لَا یَنفَعُ ٱلظَّـٰلِمِینَ مَعۡذِرَتُهُمۡۖ وَلَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوۤءُ ٱلدَّارِ',
    'يوم لا ينفع الظالمين معذرتهم ولهم اللعنة ولهم سوء الدار',
    'يَوۡمَ لَا يَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ مَعۡذِرَتُهُمۡۖ وَلَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّعۡنَةُ وَلَهُمۡ س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>َا</rule>رِ ٥٢',
    52, 24, 6, 473, 409, 189, 'false'
  );
  
  -- Ayah 53 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4186,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱلۡكِتَـٰبَ',
    'ولقد اتينا موسى الهدى واورثنا بني اسرائيل الكتاب',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَأَوۡرَثۡنَا بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>َ ٥٣',
    53, 24, 6, 473, 409, 189, 'false'
  );
  
  -- Ayah 54 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4187,
    'هُدࣰى وَذِكۡرَىٰ لِأُو۟لِی ٱلۡأَلۡبَـٰبِ',
    'هدى وذكرى لاولي الالباب',
    'هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َذِكۡرَىٰ لِأُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_permissible>ـٰ</rule><rule class=qalaqah>ب</rule>ِ ٥٤',
    54, 24, 6, 473, 409, 189, 'false'
  );
  
  -- Ayah 55 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4188,
    'فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِیِّ وَٱلۡإِبۡكَـٰرِ',
    'فاصبر ان وعد الله حق واستغفر لذنبك وسبح بحمد ربك بالعشي والابكار',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ إِ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=idgham_ghunnah>قٌّ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرۡ لِذَ<rule class=iqlab>نۢب</rule>ِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِ<rule class=ham_wasl>ٱ</rule>لۡعَشِىِّ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=qalaqah>بۡ</rule>كَ<rule class=madda_permissible>ـٰ</rule>رِ ٥٥',
    55, 24, 6, 473, 409, 189, 'false'
  );
  
  -- Ayah 56 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4189,
    'إِنَّ ٱلَّذِینَ یُجَـٰدِلُونَ فِیۤ ءَایَـٰتِ ٱللَّهِ بِغَیۡرِ سُلۡطَـٰنٍ أَتَىٰهُمۡ إِن فِی صُدُورِهِمۡ إِلَّا كِبۡرࣱ مَّا هُم بِبَـٰلِغِیهِۚ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ',
    'ان الذين يجادلون في ايات الله بغير سلطان اتاهم ان في صدورهم الا كبر ما هم ببالغيه فاستعذ بالله انه هو السميع البصير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُجَ<rule class=madda_normal>ـٰ</rule>دِلُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِغَيۡرِ سُلۡطَ<rule class=madda_normal>ـٰ</rule>نٍ أَتَ<rule class=madda_normal>ـٰ</rule>هُمۡۙ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى صُدُورِهِمۡ إِلَّا كِ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَ<rule class=madda_normal>ـٰ</rule>لِغِيهِۚ فَ<rule class=ham_wasl>ٱ</rule>سۡتَعِذۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡبَص<rule class=madda_permissible>ِي</rule>رُ ٥٦',
    56, 24, 6, 473, 409, 189, 'false'
  );
  
  -- Ayah 57 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4190,
    'لَخَلۡقُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ أَكۡبَرُ مِنۡ خَلۡقِ ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'لخلق السماوات والارض اكبر من خلق الناس ولكن اكثر الناس لا يعلمون',
    'لَخَلۡقُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَكۡبَرُ مِنۡ خَلۡقِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 24, 6, 473, 409, 189, 'false'
  );
  
  -- Ayah 58 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4191,
    'وَمَا یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُ وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَلَا ٱلۡمُسِیۤءُۚ قَلِیلࣰا مَّا تَتَذَكَّرُونَ',
    'وما يستوي الاعمى والبصير والذين امنوا وعملوا الصالحات ولا المسيء قليلا ما تتذكرون',
    'وَمَا يَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡأَعۡمَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡبَصِيرُ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَلَا <rule class=ham_wasl>ٱ</rule>لۡمُس<rule class=madda_obligatory_mottasel>ِى</rule>ٓءُۚ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 24, 6, 473, 409, 189, 'false'
  );
  
  -- Ayah 59 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4192,
    'إِنَّ ٱلسَّاعَةَ لَـَٔاتِیَةࣱ لَّا رَیۡبَ فِیهَا وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یُؤۡمِنُونَ',
    'ان الساعة لاتية لا ريب فيها ولكن اكثر الناس لا يؤمنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ لَأَتِيَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا رَيۡبَ فِيهَا وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 24, 6, 474, 409, 189, 'false'
  );
  
  -- Ayah 60 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4193,
    'وَقَالَ رَبُّكُمُ ٱدۡعُونِیۤ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِینَ یَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِی سَیَدۡخُلُونَ جَهَنَّمَ دَاخِرِینَ',
    'وقال ربكم ادعوني استجب لكم ان الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين',
    'وَقَالَ رَبُّكُمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُون<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَسۡتَجِ<rule class=qalaqah>بۡ</rule> لَكُمۡۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِى سَيَ<rule class=qalaqah>دۡ</rule>خُلُونَ جَهَ<rule class=ghunnah>نّ</rule>َمَ دَاخِر<rule class=madda_permissible>ِي</rule>نَ ٦٠',
    60, 24, 6, 474, 409, 189, 'false'
  );
  
  -- Ayah 61 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4194,
    'ٱللَّهُ ٱلَّذِی جَعَلَ لَكُمُ ٱلَّیۡلَ لِتَسۡكُنُوا۟ فِیهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَشۡكُرُونَ',
    'الله الذي جعل لكم الليل لتسكنوا فيه والنهار مبصرا ان الله لذو فضل على الناس ولكن اكثر الناس لا يشكرون',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ لِتَسۡكُنُو<rule class=slnt>اۡ</rule> فِيهِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ مُ<rule class=qalaqah>بۡ</rule>صِرًاۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَذُو فَضۡلٍ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 24, 6, 474, 410, 189, 'false'
  );
  
  -- Ayah 62 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4195,
    'ذَ ٰ⁠لِكُمُ ٱللَّهُ رَبُّكُمۡ خَـٰلِقُ كُلِّ شَیۡءࣲ لَّاۤ إِلَـٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ',
    'ذلكم الله ربكم خالق كل شيء لا اله الا هو فانى تؤفكون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّكُمۡ خَ<rule class=madda_normal>ـٰ</rule>لِقُ كُلِّ ش<rule class=idgham_wo_ghunnah>َىۡءٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَۖ فَأَ<rule class=ghunnah>نّ</rule>َىٰ تُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٦٢',
    62, 24, 6, 474, 410, 189, 'false'
  );
  
  -- Ayah 63 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4196,
    'كَذَ ٰ⁠لِكَ یُؤۡفَكُ ٱلَّذِینَ كَانُوا۟ بِـَٔایَـٰتِ ٱللَّهِ یَجۡحَدُونَ',
    'كذلك يؤفك الذين كانوا بايات الله يجحدون',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُؤۡفَكُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَانُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ يَ<rule class=qalaqah>جۡ</rule>حَد<rule class=madda_permissible>ُو</rule>نَ ٦٣',
    63, 24, 6, 474, 410, 189, 'false'
  );
  
  -- Ayah 64 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4197,
    'ٱللَّهُ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارࣰا وَٱلسَّمَاۤءَ بِنَاۤءࣰ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَكُم مِّنَ ٱلطَّیِّبَـٰتِۚ ذَ ٰ⁠لِكُمُ ٱللَّهُ رَبُّكُمۡۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَـٰلَمِینَ',
    'الله الذي جعل لكم الارض قرارا والسماء بناء وصوركم فاحسن صوركم ورزقكم من الطيبات ذلكم الله ربكم فتبارك الله رب العالمين',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ قَرَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِن<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّكُمۡۖ فَتَبَارَكَ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٦٤',
    64, 24, 6, 474, 410, 189, 'false'
  );
  
  -- Ayah 65 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4198,
    'هُوَ ٱلۡحَیُّ لَاۤ إِلَـٰهَ إِلَّا هُوَ فَٱدۡعُوهُ مُخۡلِصِینَ لَهُ ٱلدِّینَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'هو الحي لا اله الا هو فادعوه مخلصين له الدين الحمد لله رب العالمين',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَىُّ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُوهُ مُخۡلِصِينَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَۗ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ لِلَّهِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٦٥',
    65, 24, 6, 474, 410, 189, 'false'
  );
  
  -- Ayah 66 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4199,
    '۞ قُلۡ إِنِّی نُهِیتُ أَنۡ أَعۡبُدَ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَاۤءَنِیَ ٱلۡبَیِّنَـٰتُ مِن رَّبِّی وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَـٰلَمِینَ',
    'قل اني نهيت ان اعبد الذين تدعون من دون الله لما جاءني البينات من ربي وامرت ان اسلم لرب العالمين',
    '۞قُلۡ إِ<rule class=ghunnah>نّ</rule>ِى نُهِيتُ أَنۡ أَعۡبُدَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنِىَ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّى وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٦٦',
    66, 24, 6, 474, 410, 190, 'false'
  );
  
  -- Ayah 67 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4200,
    'هُوَ ٱلَّذِی خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ مِنۡ عَلَقَةࣲ ثُمَّ یُخۡرِجُكُمۡ طِفۡلࣰا ثُمَّ لِتَبۡلُغُوۤا۟ أَشُدَّكُمۡ ثُمَّ لِتَكُونُوا۟ شُیُوخࣰاۚ وَمِنكُم مَّن یُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوۤا۟ أَجَلࣰا مُّسَمࣰّى وَلَعَلَّكُمۡ تَعۡقِلُونَ',
    'هو الذي خلقكم من تراب ثم من نطفة ثم من علقة ثم يخرجكم طفلا ثم لتبلغوا اشدكم ثم لتكونوا شيوخا ومنكم من يتوفى من قبل ولتبلغوا اجلا مسمى ولعلكم تعقلون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُرَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّ<rule class=qalaqah>طۡ</rule>فَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ مِنۡ عَلَقَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ يُخۡرِجُكُمۡ طِفۡل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ لِتَ<rule class=qalaqah>بۡ</rule>لُغ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَشُدَّكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ لِتَكُونُو<rule class=slnt>اۡ</rule> شُيُو<rule class=idgham_ghunnah>خًاۚ</rule> <rule class=idgham_ghunnah>و</rule>َمِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُتَوَفَّىٰ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُۖ وَلِتَ<rule class=qalaqah>بۡ</rule>لُغ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَجَل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=idgham_ghunnah>ًّى</rule> <rule class=idgham_ghunnah>و</rule>َلَعَلَّكُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٦٧',
    67, 24, 6, 475, 410, 190, 'false'
  );
  
  -- Ayah 68 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4201,
    'هُوَ ٱلَّذِی یُحۡیِۦ وَیُمِیتُۖ فَإِذَا قَضَىٰۤ أَمۡرࣰا فَإِنَّمَا یَقُولُ لَهُۥ كُن فَیَكُونُ',
    'هو الذي يحيي ويميت فاذا قضى امرا فانما يقول له كن فيكون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُۖ فَإِذَا قَضَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َمَا يَقُولُ لَهُ<rule class=madda_normal>ۥ</rule> كُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َيَك<rule class=madda_permissible>ُو</rule>نُ ٦٨',
    68, 24, 6, 475, 410, 190, 'false'
  );
  
  -- Ayah 69 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4202,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِینَ یُجَـٰدِلُونَ فِیۤ ءَایَـٰتِ ٱللَّهِ أَنَّىٰ یُصۡرَفُونَ',
    'الم تر الى الذين يجادلون في ايات الله انى يصرفون',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُجَ<rule class=madda_normal>ـٰ</rule>دِلُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَ<rule class=ghunnah>نّ</rule>َىٰ يُصۡرَف<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 70 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4203,
    'ٱلَّذِینَ كَذَّبُوا۟ بِٱلۡكِتَـٰبِ وَبِمَاۤ أَرۡسَلۡنَا بِهِۦ رُسُلَنَاۖ فَسَوۡفَ یَعۡلَمُونَ',
    'الذين كذبوا بالكتاب وبما ارسلنا به رسلنا فسوف يعلمون',
    'ٱلَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَبِم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا بِه<rule class=madda_normal>ِۦ</rule> رُسُلَنَاۖ فَسَوۡفَ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 71 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4204,
    'إِذِ ٱلۡأَغۡلَـٰلُ فِیۤ أَعۡنَـٰقِهِمۡ وَٱلسَّلَـٰسِلُ یُسۡحَبُونَ',
    'اذ الاغلال في اعناقهم والسلاسل يسحبون',
    'إِذِ <rule class=ham_wasl>ٱ</rule>لۡأَغۡلَ<rule class=madda_normal>ـٰ</rule>لُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡنَ<rule class=madda_normal>ـٰ</rule>قِهِمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَ<rule class=madda_normal>ـٰ</rule>سِلُ يُسۡحَب<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 72 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4205,
    'فِی ٱلۡحَمِیمِ ثُمَّ فِی ٱلنَّارِ یُسۡجَرُونَ',
    'في الحميم ثم في النار يسجرون',
    'فِى <rule class=ham_wasl>ٱ</rule>لۡحَمِيمِ ثُ<rule class=ghunnah>مّ</rule>َ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ يُسۡجَر<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 73 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4206,
    'ثُمَّ قِیلَ لَهُمۡ أَیۡنَ مَا كُنتُمۡ تُشۡرِكُونَ',
    'ثم قيل لهم اين ما كنتم تشركون',
    'ثُ<rule class=ghunnah>مّ</rule>َ قِيلَ لَهُمۡ أَيۡنَ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 74 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4207,
    'مِن دُونِ ٱللَّهِۖ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمۡ نَكُن نَّدۡعُوا۟ مِن قَبۡلُ شَیۡـࣰٔاۚ كَذَ ٰ⁠لِكَ یُضِلُّ ٱللَّهُ ٱلۡكَـٰفِرِینَ',
    'من دون الله قالوا ضلوا عنا بل لم نكن ندعو من قبل شيئا كذلك يضل الله الكافرين',
    'مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِۖ قَالُو<rule class=slnt>اۡ</rule> ضَلُّو<rule class=slnt>اۡ</rule> عَ<rule class=ghunnah>نّ</rule>َا بَل لَّمۡ نَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ شَيۡـ<rule class=ikhafa>ـًٔاۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ يُضِلُّ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٧٤',
    74, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 75 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4208,
    'ذَ ٰ⁠لِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ',
    'ذلكم بما كنتم تفرحون في الارض بغير الحق وبما كنتم تمرحون',
    'ذ<rule class=madda_normal>ٰ</rule>لِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَفۡرَحُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَبِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَمۡرَح<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 76 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4209,
    'ٱدۡخُلُوۤا۟ أَبۡوَ ٰ⁠بَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِینَ',
    'ادخلوا ابواب جهنم خالدين فيها فبئس مثوى المتكبرين',
    'ٱ<rule class=qalaqah>دۡ</rule>خُل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بَ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى <rule class=ham_wasl>ٱ</rule>لۡمُتَكَبِّر<rule class=madda_permissible>ِي</rule>نَ ٧٦',
    76, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 77 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4210,
    'فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۚ فَإِمَّا نُرِیَنَّكَ بَعۡضَ ٱلَّذِی نَعِدُهُمۡ أَوۡ نَتَوَفَّیَنَّكَ فَإِلَیۡنَا یُرۡجَعُونَ',
    'فاصبر ان وعد الله حق فاما نرينك بعض الذي نعدهم او نتوفينك فالينا يرجعون',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ إِ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَۚ<rule class=ikhafa>قٌّ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>مّ</rule>َا نُرِيَ<rule class=ghunnah>نّ</rule>َكَ بَعۡضَ <rule class=ham_wasl>ٱ</rule>لَّذِى نَعِدُهُمۡ أَوۡ نَتَوَفَّيَ<rule class=ghunnah>نّ</rule>َكَ فَإِلَيۡنَا يُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٧٧',
    77, 24, 6, 475, 411, 190, 'false'
  );
  
  -- Ayah 78 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4211,
    'وَلَقَدۡ أَرۡسَلۡنَا رُسُلࣰا مِّن قَبۡلِكَ مِنۡهُم مَّن قَصَصۡنَا عَلَیۡكَ وَمِنۡهُم مَّن لَّمۡ نَقۡصُصۡ عَلَیۡكَۗ وَمَا كَانَ لِرَسُولٍ أَن یَأۡتِیَ بِـَٔایَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ فَإِذَا جَاۤءَ أَمۡرُ ٱللَّهِ قُضِیَ بِٱلۡحَقِّ وَخَسِرَ هُنَالِكَ ٱلۡمُبۡطِلُونَ',
    'ولقد ارسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك وما كان لرسول ان ياتي باية الا باذن الله فاذا جاء امر الله قضي بالحق وخسر هنالك المبطلون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا رُسُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َصَصۡنَا عَلَيۡكَ وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ نَ<rule class=qalaqah>قۡ</rule>صُصۡ عَلَيۡكَۗ وَمَا كَانَ لِرَسُولٍ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِىَ بِـَٔـايَةٍ إِلَّا بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِۚ فَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ قُضِىَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَخَسِرَ هُنَالِكَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>بۡ</rule>طِل<rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 24, 6, 476, 411, 190, 'false'
  );
  
  -- Ayah 79 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4212,
    'ٱللَّهُ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَنۡعَـٰمَ لِتَرۡكَبُوا۟ مِنۡهَا وَمِنۡهَا تَأۡكُلُونَ',
    'الله الذي جعل لكم الانعام لتركبوا منها ومنها تاكلون',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مَ لِتَرۡكَبُو<rule class=slnt>اۡ</rule> مِنۡهَا وَمِنۡهَا تَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 24, 6, 476, 412, 190, 'false'
  );
  
  -- Ayah 80 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4213,
    'وَلَكُمۡ فِیهَا مَنَـٰفِعُ وَلِتَبۡلُغُوا۟ عَلَیۡهَا حَاجَةࣰ فِی صُدُورِكُمۡ وَعَلَیۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ',
    'ولكم فيها منافع ولتبلغوا عليها حاجة في صدوركم وعليها وعلى الفلك تحملون',
    'وَلَكُمۡ فِيهَا مَنَ<rule class=madda_normal>ـٰ</rule>فِعُ وَلِتَ<rule class=qalaqah>بۡ</rule>لُغُو<rule class=slnt>اۡ</rule> عَلَيۡهَا حَاجَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ تُحۡمَل<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 24, 6, 476, 412, 190, 'false'
  );
  
  -- Ayah 81 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4214,
    'وَیُرِیكُمۡ ءَایَـٰتِهِۦ فَأَیَّ ءَایَـٰتِ ٱللَّهِ تُنكِرُونَ',
    'ويريكم اياته فاي ايات الله تنكرون',
    'وَيُرِيكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> فَأَىَّ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ تُ<rule class=ikhafa>نك</rule>ِر<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 24, 6, 476, 412, 190, 'false'
  );
  
  -- Ayah 82 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4215,
    'أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَانُوۤا۟ أَكۡثَرَ مِنۡهُمۡ وَأَشَدَّ قُوَّةࣰ وَءَاثَارࣰا فِی ٱلۡأَرۡضِ فَمَاۤ أَغۡنَىٰ عَنۡهُم مَّا كَانُوا۟ یَكۡسِبُونَ',
    'افلم يسيروا في الارض فينظروا كيف كان عاقبة الذين من قبلهم كانوا اكثر منهم واشد قوة واثارا في الارض فما اغنى عنهم ما كانوا يكسبون',
    'أَفَلَمۡ يَسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَيَ<rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡۚ كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَكۡثَرَ مِنۡهُمۡ وَأَشَدَّ قُوَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َءَاثَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡنَىٰ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 24, 6, 476, 412, 190, 'false'
  );
  
  -- Ayah 83 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4216,
    'فَلَمَّا جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'فلما جاءتهم رسلهم بالبينات فرحوا بما عندهم من العلم وحاق بهم ما كانوا به يستهزئون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَرِحُو<rule class=slnt>اۡ</rule> بِمَا عِ<rule class=ikhafa>ند</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ وَحَاقَ بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٨٣',
    83, 24, 6, 476, 412, 190, 'false'
  );
  
  -- Ayah 84 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4217,
    'فَلَمَّا رَأَوۡا۟ بَأۡسَنَا قَالُوۤا۟ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِینَ',
    'فلما راوا باسنا قالوا امنا بالله وحده وكفرنا بما كنا به مشركين',
    'فَلَ<rule class=ghunnah>مّ</rule>َا رَأَوۡ<rule class=slnt>اۡ</rule> بَأۡسَنَا قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَحۡدَهُ<rule class=madda_normal>ۥ</rule> وَكَفَرۡنَا بِمَا كُ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_normal>ِۦ</rule> مُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٨٤',
    84, 24, 6, 476, 412, 190, 'false'
  );
  
  -- Ayah 85 Surah Ghafir
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    40,
    4218,
    'فَلَمۡ یَكُ یَنفَعُهُمۡ إِیمَـٰنُهُمۡ لَمَّا رَأَوۡا۟ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِی قَدۡ خَلَتۡ فِی عِبَادِهِۦۖ وَخَسِرَ هُنَالِكَ ٱلۡكَـٰفِرُونَ',
    'فلم يك ينفعهم ايمانهم لما راوا باسنا سنت الله التي قد خلت في عباده وخسر هنالك الكافرون',
    'فَلَمۡ يَكُ يَ<rule class=ikhafa>نف</rule>َعُهُمۡ إِيمَ<rule class=madda_normal>ـٰ</rule>نُهُمۡ لَ<rule class=ghunnah>مّ</rule>َا رَأَوۡ<rule class=slnt>اۡ</rule> بَأۡسَنَاۖ سُ<rule class=ghunnah>نّ</rule>َتَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّتِى قَ<rule class=qalaqah>دۡ</rule> خَلَتۡ فِى عِبَادِهِ<rule class=madda_normal>ۖۦ</rule> وَخَسِرَ هُنَالِكَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٨٥',
    85, 24, 6, 476, 412, 190, 'false'
  );
  

-- Surah Fussilat
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (41, 'سُورَةُ فُصِّلَتۡ', 'Fussilat', 'Explained in detail', 'Meccan', 54);

  -- Ayah 1 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4219,
    'حمۤ',
    'حم',
    'ح<rule class=madda_necessary>مٓ</rule> ١',
    1, 24, 6, 477, 413, 190, 'false'
  );
  
  -- Ayah 2 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4220,
    'تَنزِیلࣱ مِّنَ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ',
    'تنزيل من الرحمن الرحيم',
    'تَ<rule class=ikhafa>نز</rule>ِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مِ ٢',
    2, 24, 6, 477, 413, 190, 'false'
  );
  
  -- Ayah 3 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4221,
    'كِتَـٰبࣱ فُصِّلَتۡ ءَایَـٰتُهُۥ قُرۡءَانًا عَرَبِیࣰّا لِّقَوۡمࣲ یَعۡلَمُونَ',
    'كتاب فصلت اياته قرانا عربيا لقوم يعلمون',
    'كِتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ف</rule>ُصِّلَتۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُهُ<rule class=madda_normal>ۥ</rule> قُرۡءَانًا عَرَبِي<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 24, 6, 477, 413, 190, 'false'
  );
  
  -- Ayah 4 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4222,
    'بَشِیرࣰا وَنَذِیرࣰا فَأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا یَسۡمَعُونَ',
    'بشيرا ونذيرا فاعرض اكثرهم فهم لا يسمعون',
    'بَشِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَذِي<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا يَسۡمَع<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 24, 6, 477, 413, 190, 'false'
  );
  
  -- Ayah 5 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4223,
    'وَقَالُوا۟ قُلُوبُنَا فِیۤ أَكِنَّةࣲ مِّمَّا تَدۡعُونَاۤ إِلَیۡهِ وَفِیۤ ءَاذَانِنَا وَقۡرࣱ وَمِنۢ بَیۡنِنَا وَبَیۡنِكَ حِجَابࣱ فَٱعۡمَلۡ إِنَّنَا عَـٰمِلُونَ',
    'وقالوا قلوبنا في اكنة مما تدعونا اليه وفي اذاننا وقر ومن بيننا وبينك حجاب فاعمل اننا عاملون',
    'وَقَالُو<rule class=slnt>اۡ</rule> قُلُوبُنَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَكِ<rule class=ghunnah>نّ</rule>َ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَ<rule class=qalaqah>دۡ</rule>عُون<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ وَف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاذَانِنَا وَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِنَا وَبَيۡنِكَ حِجَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>عۡمَلۡ إِ<rule class=ghunnah>نّ</rule>َنَا عَ<rule class=madda_normal>ـٰ</rule>مِل<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 24, 6, 477, 413, 190, 'false'
  );
  
  -- Ayah 6 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4224,
    'قُلۡ إِنَّمَاۤ أَنَا۠ بَشَرࣱ مِّثۡلُكُمۡ یُوحَىٰۤ إِلَیَّ أَنَّمَاۤ إِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰ⁠حِدࣱ فَٱسۡتَقِیمُوۤا۟ إِلَیۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَیۡلࣱ لِّلۡمُشۡرِكِینَ',
    'قل انما انا بشر مثلكم يوحى الي انما الهكم اله واحد فاستقيموا اليه واستغفروه وويل للمشركين',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ بَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُكُمۡ يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىَّ أَ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هُكُمۡ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِ<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَقِيم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرُوهُ‌ۗ وَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُشۡرِك<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 24, 6, 477, 413, 190, 'false'
  );
  
  -- Ayah 7 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4225,
    'ٱلَّذِینَ لَا یُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ كَـٰفِرُونَ',
    'الذين لا يؤتون الزكاة وهم بالاخرة هم كافرون',
    'ٱلَّذِينَ لَا يُؤۡتُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ هُمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 24, 6, 477, 413, 190, 'false'
  );
  
  -- Ayah 8 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4226,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمۡ أَجۡرٌ غَیۡرُ مَمۡنُونࣲ',
    'ان الذين امنوا وعملوا الصالحات لهم اجر غير ممنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رٌ غَيۡرُ مَمۡن<rule class=madda_permissible>ُو</rule>نٍ ٨',
    8, 24, 6, 477, 413, 190, 'false'
  );
  
  -- Ayah 9 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4227,
    '۞ قُلۡ أَىِٕنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِی خَلَقَ ٱلۡأَرۡضَ فِی یَوۡمَیۡنِ وَتَجۡعَلُونَ لَهُۥۤ أَندَادࣰاۚ ذَ ٰ⁠لِكَ رَبُّ ٱلۡعَـٰلَمِینَ',
    'قل ائنكم لتكفرون بالذي خلق الارض في يومين وتجعلون له اندادا ذلك رب العالمين',
    '۞قُلۡ أَئِ<rule class=ghunnah>نّ</rule>َكُمۡ لَتَكۡفُرُونَ بِ<rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فِى يَوۡمَيۡنِ وَتَ<rule class=qalaqah>جۡ</rule>عَلُونَ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=ikhafa>ند</rule>َا<rule class=ikhafa>دًا‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ رَبُّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٩',
    9, 24, 6, 477, 414, 191, 'false'
  );
  
  -- Ayah 10 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4228,
    'وَجَعَلَ فِیهَا رَوَ ٰ⁠سِیَ مِن فَوۡقِهَا وَبَـٰرَكَ فِیهَا وَقَدَّرَ فِیهَاۤ أَقۡوَ ٰ⁠تَهَا فِیۤ أَرۡبَعَةِ أَیَّامࣲ سَوَاۤءࣰ لِّلسَّاۤىِٕلِینَ',
    'وجعل فيها رواسي من فوقها وبارك فيها وقدر فيها اقواتها في اربعة ايام سواء للسائلين',
    'وَجَعَلَ فِيهَا رَو<rule class=madda_normal>ٰ</rule>سِىَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهَا وَبَ<rule class=madda_normal>ـٰ</rule>رَكَ فِيهَا وَقَدَّرَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>قۡ</rule>و<rule class=madda_normal>ٰ</rule>تَهَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡبَعَةِ أَيَّا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>س</rule>َو<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_wo_ghunnah>ءً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلسّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِل<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 24, 6, 477, 414, 191, 'false'
  );
  
  -- Ayah 11 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4229,
    'ثُمَّ ٱسۡتَوَىٰۤ إِلَى ٱلسَّمَاۤءِ وَهِیَ دُخَانࣱ فَقَالَ لَهَا وَلِلۡأَرۡضِ ٱئۡتِیَا طَوۡعًا أَوۡ كَرۡهࣰا قَالَتَاۤ أَتَیۡنَا طَاۤىِٕعِینَ',
    'ثم استوى الى السماء وهي دخان فقال لها وللارض ائتيا طوعا او كرها قالتا اتينا طائعين',
    'ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَوَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَهِىَ دُخَا<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ف</rule>َقَالَ لَهَا وَلِلۡأَرۡضِ <rule class=ham_wasl>ٱ</rule>ئۡتِيَا طَوۡعًا أَوۡ كَرۡ<rule class=ikhafa>هًا</rule> <rule class=ikhafa>ق</rule>َالَت<rule class=madda_obligatory_monfasel>َآ</rule> أَتَيۡنَا ط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِع<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 24, 6, 477, 414, 191, 'false'
  );
  
  -- Ayah 12 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4230,
    'فَقَضَىٰهُنَّ سَبۡعَ سَمَـٰوَاتࣲ فِی یَوۡمَیۡنِ وَأَوۡحَىٰ فِی كُلِّ سَمَاۤءٍ أَمۡرَهَاۚ وَزَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِمَصَـٰبِیحَ وَحِفۡظࣰاۚ ذَ ٰ⁠لِكَ تَقۡدِیرُ ٱلۡعَزِیزِ ٱلۡعَلِیمِ',
    'فقضاهن سبع سماوات في يومين واوحى في كل سماء امرها وزينا السماء الدنيا بمصابيح وحفظا ذلك تقدير العزيز العليم',
    'فَقَضَ<rule class=madda_normal>ـٰ</rule>هُ<rule class=ghunnah>نّ</rule>َ سَ<rule class=qalaqah>بۡ</rule>عَ سَمَ<rule class=madda_normal>ـٰ</rule>وَا<rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>ِى يَوۡمَيۡنِ وَأَوۡحَىٰ فِى كُلِّ سَم<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ أَمۡرَهَا‌ۚ وَزَيَّ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا بِمَصَ<rule class=madda_normal>ـٰ</rule>بِيحَ وَحِفۡ<rule class=ikhafa>ظًا‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ تَ<rule class=qalaqah>قۡ</rule>دِيرُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مِ ١٢',
    12, 24, 6, 478, 414, 191, 'false'
  );
  
  -- Ayah 13 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4231,
    'فَإِنۡ أَعۡرَضُوا۟ فَقُلۡ أَنذَرۡتُكُمۡ صَـٰعِقَةࣰ مِّثۡلَ صَـٰعِقَةِ عَادࣲ وَثَمُودَ',
    'فان اعرضوا فقل انذرتكم صاعقة مثل صاعقة عاد وثمود',
    'فَإِنۡ أَعۡرَضُو<rule class=slnt>اۡ</rule> فَقُلۡ أَ<rule class=ikhafa>نذ</rule>َرۡتُكُمۡ صَ<rule class=madda_normal>ـٰ</rule>عِقَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلَ صَ<rule class=madda_normal>ـٰ</rule>عِقَةِ عَا<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َثَم<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>َ ١٣',
    13, 24, 6, 478, 414, 191, 'false'
  );
  
  -- Ayah 14 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4232,
    'إِذۡ جَاۤءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَیۡنِ أَیۡدِیهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُدُوۤا۟ إِلَّا ٱللَّهَۖ قَالُوا۟ لَوۡ شَاۤءَ رَبُّنَا لَأَنزَلَ مَلَـٰۤىِٕكَةࣰ فَإِنَّا بِمَاۤ أُرۡسِلۡتُم بِهِۦ كَـٰفِرُونَ',
    'اذ جاءتهم الرسل من بين ايديهم ومن خلفهم الا تعبدوا الا الله قالوا لو شاء ربنا لانزل ملائكة فانا بما ارسلتم به كافرون',
    'إِذۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ قَالُو<rule class=slnt>اۡ</rule> لَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبُّنَا لَأَ<rule class=ikhafa>نز</rule>َلَ مَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َا بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 24, 6, 478, 414, 191, 'false'
  );
  
  -- Ayah 15 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4233,
    'فَأَمَّا عَادࣱ فَٱسۡتَكۡبَرُوا۟ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَقَالُوا۟ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ ٱلَّذِی خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةࣰۖ وَكَانُوا۟ بِـَٔایَـٰتِنَا یَجۡحَدُونَ',
    'فاما عاد فاستكبروا في الارض بغير الحق وقالوا من اشد منا قوة اولم يروا ان الله الذي خلقهم هو اشد منهم قوة وكانوا باياتنا يجحدون',
    'فَأَ<rule class=ghunnah>مّ</rule>َا عَا<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَقَالُو<rule class=slnt>اۡ</rule> مَنۡ أَشَدُّ مِ<rule class=ghunnah>نّ</rule>َا قُوَّةً‌ۖ أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّ<rule class=idgham_ghunnah>ةً‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َكَانُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا يَ<rule class=qalaqah>جۡ</rule>حَد<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 24, 6, 478, 414, 191, 'false'
  );
  
  -- Ayah 16 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4234,
    'فَأَرۡسَلۡنَا عَلَیۡهِمۡ رِیحࣰا صَرۡصَرࣰا فِیۤ أَیَّامࣲ نَّحِسَاتࣲ لِّنُذِیقَهُمۡ عَذَابَ ٱلۡخِزۡیِ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَخۡزَىٰۖ وَهُمۡ لَا یُنصَرُونَ',
    'فارسلنا عليهم ريحا صرصرا في ايام نحسات لنذيقهم عذاب الخزي في الحياة الدنيا ولعذاب الاخرة اخزى وهم لا ينصرون',
    'فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِي<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ص</rule>َرۡصَ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَيَّا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ن</rule>َّحِسَا<rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّنُذِيقَهُمۡ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡخِزۡىِ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَلَعَذَابُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ أَخۡزَىٰ‌ۖ وَهُمۡ لَا يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 24, 6, 478, 414, 191, 'false'
  );
  
  -- Ayah 17 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4235,
    'وَأَمَّا ثَمُودُ فَهَدَیۡنَـٰهُمۡ فَٱسۡتَحَبُّوا۟ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ فَأَخَذَتۡهُمۡ صَـٰعِقَةُ ٱلۡعَذَابِ ٱلۡهُونِ بِمَا كَانُوا۟ یَكۡسِبُونَ',
    'واما ثمود فهديناهم فاستحبوا العمى على الهدى فاخذتهم صاعقة العذاب الهون بما كانوا يكسبون',
    'وَأَ<rule class=ghunnah>مّ</rule>َا ثَمُودُ فَهَدَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَحَبُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَمَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ فَأَخَذَتۡهُمۡ صَ<rule class=madda_normal>ـٰ</rule>عِقَةُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ <rule class=ham_wasl>ٱ</rule>لۡهُونِ بِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 24, 6, 478, 414, 191, 'false'
  );
  
  -- Ayah 18 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4236,
    'وَنَجَّیۡنَا ٱلَّذِینَ ءَامَنُوا۟ وَكَانُوا۟ یَتَّقُونَ',
    'ونجينا الذين امنوا وكانوا يتقون',
    'وَنَجَّيۡنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَكَانُو<rule class=slnt>اۡ</rule> يَتَّق<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 24, 6, 478, 414, 191, 'false'
  );
  
  -- Ayah 19 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4237,
    'وَیَوۡمَ یُحۡشَرُ أَعۡدَاۤءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ یُوزَعُونَ',
    'ويوم يحشر اعداء الله الى النار فهم يوزعون',
    'وَيَوۡمَ يُحۡشَرُ أَعۡد<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ فَهُمۡ يُوزَع<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 24, 6, 478, 415, 191, 'false'
  );
  
  -- Ayah 20 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4238,
    'حَتَّىٰۤ إِذَا مَا جَاۤءُوهَا شَهِدَ عَلَیۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَـٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُوا۟ یَعۡمَلُونَ',
    'حتى اذا ما جاءوها شهد عليهم سمعهم وابصارهم وجلودهم بما كانوا يعملون',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوهَا شَهِدَ عَلَيۡهِمۡ سَمۡعُهُمۡ وَأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُهُمۡ وَجُلُودُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 24, 6, 478, 415, 191, 'false'
  );
  
  -- Ayah 21 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4239,
    'وَقَالُوا۟ لِجُلُودِهِمۡ لِمَ شَهِدتُّمۡ عَلَیۡنَاۖ قَالُوۤا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِیۤ أَنطَقَ كُلَّ شَیۡءࣲۚ وَهُوَ خَلَقَكُمۡ أَوَّلَ مَرَّةࣲ وَإِلَیۡهِ تُرۡجَعُونَ',
    'وقالوا لجلودهم لم شهدتم علينا قالوا انطقنا الله الذي انطق كل شيء وهو خلقكم اول مرة واليه ترجعون',
    'وَقَالُو<rule class=slnt>اۡ</rule> لِجُلُودِهِمۡ لِمَ شَهِ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ عَلَيۡنَا‌ۖ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نط</rule>َقَنَا <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نط</rule>َقَ كُلَّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ خَلَقَكُمۡ أَوَّلَ مَرَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 24, 6, 479, 415, 191, 'false'
  );
  
  -- Ayah 22 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4240,
    'وَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن یَشۡهَدَ عَلَیۡكُمۡ سَمۡعُكُمۡ وَلَاۤ أَبۡصَـٰرُكُمۡ وَلَا جُلُودُكُمۡ وَلَـٰكِن ظَنَنتُمۡ أَنَّ ٱللَّهَ لَا یَعۡلَمُ كَثِیرࣰا مِّمَّا تَعۡمَلُونَ',
    'وما كنتم تستترون ان يشهد عليكم سمعكم ولا ابصاركم ولا جلودكم ولكن ظننتم ان الله لا يعلم كثيرا مما تعملون',
    'وَمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَسۡتَتِرُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُكُمۡ وَلَا جُلُودُكُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ظ</rule>َنَ<rule class=ikhafa>نت</rule>ُمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَعۡلَمُ كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 24, 6, 479, 415, 191, 'false'
  );
  
  -- Ayah 23 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4241,
    'وَذَ ٰ⁠لِكُمۡ ظَنُّكُمُ ٱلَّذِی ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم مِّنَ ٱلۡخَـٰسِرِینَ',
    'وذلكم ظنكم الذي ظننتم بربكم ارداكم فاصبحتم من الخاسرين',
    'وَذ<rule class=madda_normal>ٰ</rule>لِكُمۡ ظَ<rule class=ghunnah>نّ</rule>ُكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى ظَنَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرَبِّكُمۡ أَرۡدَ<rule class=madda_normal>ٮٰ</rule>كُمۡ فَأَصۡبَحۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٢٣',
    23, 24, 6, 479, 415, 191, 'false'
  );
  
  -- Ayah 24 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4242,
    'فَإِن یَصۡبِرُوا۟ فَٱلنَّارُ مَثۡوࣰى لَّهُمۡۖ وَإِن یَسۡتَعۡتِبُوا۟ فَمَا هُم مِّنَ ٱلۡمُعۡتَبِینَ',
    'فان يصبروا فالنار مثوى لهم وان يستعتبوا فما هم من المعتبين',
    'فَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َصۡبِرُو<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ مَثۡ<rule class=idgham_wo_ghunnah>وًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَعۡتِبُو<rule class=slnt>اۡ</rule> فَمَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُعۡتَب<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 24, 6, 479, 415, 191, 'false'
  );
  
  -- Ayah 25 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4243,
    '۞ وَقَیَّضۡنَا لَهُمۡ قُرَنَاۤءَ فَزَیَّنُوا۟ لَهُم مَّا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَیۡهِمُ ٱلۡقَوۡلُ فِیۤ أُمَمࣲ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُوا۟ خَـٰسِرِینَ',
    'وقيضنا لهم قرناء فزينوا لهم ما بين ايديهم وما خلفهم وحق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خاسرين',
    '۞وَقَيَّضۡنَا لَهُمۡ قُرَن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَزَيَّنُو<rule class=slnt>اۡ</rule> لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُمَ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> خَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 24, 6, 479, 415, 192, 'false'
  );
  
  -- Ayah 26 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4244,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَا تَسۡمَعُوا۟ لِهَـٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡا۟ فِیهِ لَعَلَّكُمۡ تَغۡلِبُونَ',
    'وقال الذين كفروا لا تسمعوا لهذا القران والغوا فيه لعلكم تغلبون',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَا تَسۡمَعُو<rule class=slnt>اۡ</rule> لِهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ وَ<rule class=ham_wasl>ٱ</rule>لۡغَوۡ<rule class=slnt>اۡ</rule> فِيهِ لَعَلَّكُمۡ تَغۡلِب<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 24, 6, 479, 416, 192, 'false'
  );
  
  -- Ayah 27 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4245,
    'فَلَنُذِیقَنَّ ٱلَّذِینَ كَفَرُوا۟ عَذَابࣰا شَدِیدࣰا وَلَنَجۡزِیَنَّهُمۡ أَسۡوَأَ ٱلَّذِی كَانُوا۟ یَعۡمَلُونَ',
    'فلنذيقن الذين كفروا عذابا شديدا ولنجزينهم اسوا الذي كانوا يعملون',
    'فَلَنُذِيقَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َلَنَ<rule class=qalaqah>جۡ</rule>زِيَ<rule class=ghunnah>نّ</rule>َهُمۡ أَسۡوَأَ <rule class=ham_wasl>ٱ</rule>لَّذِى كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 24, 6, 479, 416, 192, 'false'
  );
  
  -- Ayah 28 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4246,
    'ذَ ٰ⁠لِكَ جَزَاۤءُ أَعۡدَاۤءِ ٱللَّهِ ٱلنَّارُۖ لَهُمۡ فِیهَا دَارُ ٱلۡخُلۡدِ جَزَاۤءَۢ بِمَا كَانُوا۟ بِـَٔایَـٰتِنَا یَجۡحَدُونَ',
    'ذلك جزاء اعداء الله النار لهم فيها دار الخلد جزاء بما كانوا باياتنا يجحدون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ أَعۡد<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ‌ۖ لَهُمۡ فِيهَا دَارُ <rule class=ham_wasl>ٱ</rule>لۡخُلۡدِ‌ۖ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءَۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا يَ<rule class=qalaqah>جۡ</rule>حَد<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 24, 6, 479, 416, 192, 'false'
  );
  
  -- Ayah 29 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4247,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ رَبَّنَاۤ أَرِنَا ٱلَّذَیۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِیَكُونَا مِنَ ٱلۡأَسۡفَلِینَ',
    'وقال الذين كفروا ربنا ارنا اللذين اضلانا من الجن والانس نجعلهما تحت اقدامنا ليكونا من الاسفلين',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَرِنَا <rule class=ham_wasl>ٱ</rule>لَّذَيۡنِ أَضَلَّانَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ نَ<rule class=qalaqah>جۡ</rule>عَلۡهُمَا تَحۡتَ أَ<rule class=qalaqah>قۡ</rule>دَامِنَا لِيَكُونَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَسۡفَل<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 24, 6, 479, 416, 192, 'false'
  );
  
  -- Ayah 30 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4248,
    'إِنَّ ٱلَّذِینَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَـٰمُوا۟ تَتَنَزَّلُ عَلَیۡهِمُ ٱلۡمَلَـٰۤىِٕكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحۡزَنُوا۟ وَأَبۡشِرُوا۟ بِٱلۡجَنَّةِ ٱلَّتِی كُنتُمۡ تُوعَدُونَ',
    'ان الذين قالوا ربنا الله ثم استقاموا تتنزل عليهم الملائكة الا تخافوا ولا تحزنوا وابشروا بالجنة التي كنتم توعدون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَالُو<rule class=slnt>اۡ</rule> رَبُّنَا <rule class=ham_wasl>ٱ</rule>للَّهُ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَقَ<rule class=madda_normal>ـٰ</rule>مُو<rule class=slnt>اۡ</rule> تَتَنَزَّلُ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ أَلَّا تَخَافُو<rule class=slnt>اۡ</rule> وَلَا تَحۡزَنُو<rule class=slnt>اۡ</rule> وَأَ<rule class=qalaqah>بۡ</rule>شِرُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ <rule class=ham_wasl>ٱ</rule>لَّتِى كُ<rule class=ikhafa>نت</rule>ُمۡ تُوعَد<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 24, 6, 480, 416, 192, 'false'
  );
  
  -- Ayah 31 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4249,
    'نَحۡنُ أَوۡلِیَاۤؤُكُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَفِی ٱلۡـَٔاخِرَةِۖ وَلَكُمۡ فِیهَا مَا تَشۡتَهِیۤ أَنفُسُكُمۡ وَلَكُمۡ فِیهَا مَا تَدَّعُونَ',
    'نحن اولياؤكم في الحياة الدنيا وفي الاخرة ولكم فيها ما تشتهي انفسكم ولكم فيها ما تدعون',
    'نَحۡنُ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَفِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ‌ۖ وَلَكُمۡ فِيهَا مَا تَشۡتَه<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسُكُمۡ وَلَكُمۡ فِيهَا مَا تَدَّع<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 24, 6, 480, 416, 192, 'false'
  );
  
  -- Ayah 32 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4250,
    'نُزُلࣰا مِّنۡ غَفُورࣲ رَّحِیمࣲ',
    'نزلا من غفور رحيم',
    'نُزُل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ غَفُو<rule class=idgham_wo_ghunnah>رٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٍ ٣٢',
    32, 24, 6, 480, 416, 192, 'false'
  );
  
  -- Ayah 33 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4251,
    'وَمَنۡ أَحۡسَنُ قَوۡلࣰا مِّمَّن دَعَاۤ إِلَى ٱللَّهِ وَعَمِلَ صَـٰلِحࣰا وَقَالَ إِنَّنِی مِنَ ٱلۡمُسۡلِمِینَ',
    'ومن احسن قولا ممن دعا الى الله وعمل صالحا وقال انني من المسلمين',
    'وَمَنۡ أَحۡسَنُ قَوۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>َع<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَعَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ إِ<rule class=ghunnah>نّ</rule>َنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٣٣',
    33, 24, 6, 480, 417, 192, 'false'
  );
  
  -- Ayah 34 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4252,
    'وَلَا تَسۡتَوِی ٱلۡحَسَنَةُ وَلَا ٱلسَّیِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِی هِیَ أَحۡسَنُ فَإِذَا ٱلَّذِی بَیۡنَكَ وَبَیۡنَهُۥ عَدَ ٰ⁠وَةࣱ كَأَنَّهُۥ وَلِیٌّ حَمِیمࣱ',
    'ولا تستوي الحسنة ولا السيئة ادفع بالتي هي احسن فاذا الذي بينك وبينه عداوة كانه ولي حميم',
    'وَلَا تَسۡتَوِى <rule class=ham_wasl>ٱ</rule>لۡحَسَنَةُ وَلَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّئَةُ‌ۚ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>فَعۡ بِ<rule class=ham_wasl>ٱ</rule>لَّتِى هِىَ أَحۡسَنُ فَإِذَا <rule class=ham_wasl>ٱ</rule>لَّذِى بَيۡنَكَ وَبَيۡنَهُ<rule class=madda_normal>ۥ</rule> عَد<rule class=madda_normal>ٰ</rule>وَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ك</rule>َأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> وَلِىٌّ حَم<rule class=madda_permissible>ِي</rule>مٌ ٣٤',
    34, 24, 6, 480, 417, 192, 'false'
  );
  
  -- Ayah 35 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4253,
    'وَمَا یُلَقَّىٰهَاۤ إِلَّا ٱلَّذِینَ صَبَرُوا۟ وَمَا یُلَقَّىٰهَاۤ إِلَّا ذُو حَظٍّ عَظِیمࣲ',
    'وما يلقاها الا الذين صبروا وما يلقاها الا ذو حظ عظيم',
    'وَمَا يُلَقَّ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ صَبَرُو<rule class=slnt>اۡ</rule> وَمَا يُلَقَّ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا ذُو حَظٍّ عَظ<rule class=madda_permissible>ِي</rule>مٍ ٣٥',
    35, 24, 6, 480, 417, 192, 'false'
  );
  
  -- Ayah 36 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4254,
    'وَإِمَّا یَنزَغَنَّكَ مِنَ ٱلشَّیۡطَـٰنِ نَزۡغࣱ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'واما ينزغنك من الشيطان نزغ فاستعذ بالله انه هو السميع العليم',
    'وَإِ<rule class=ghunnah>مّ</rule>َا يَ<rule class=ikhafa>نز</rule>َغَ<rule class=ghunnah>نّ</rule>َكَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ نَزۡ<rule class=ikhafa>غٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَعِذۡ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٣٦',
    36, 24, 6, 480, 417, 192, 'false'
  );
  
  -- Ayah 37 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4255,
    'وَمِنۡ ءَایَـٰتِهِ ٱلَّیۡلُ وَٱلنَّهَارُ وَٱلشَّمۡسُ وَٱلۡقَمَرُۚ لَا تَسۡجُدُوا۟ لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَٱسۡجُدُوا۟ لِلَّهِ ٱلَّذِی خَلَقَهُنَّ إِن كُنتُمۡ إِیَّاهُ تَعۡبُدُونَ',
    'ومن اياته الليل والنهار والشمس والقمر لا تسجدوا للشمس ولا للقمر واسجدوا لله الذي خلقهن ان كنتم اياه تعبدون',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِهِ <rule class=ham_wasl>ٱ</rule>لَّيۡلُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسُ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرُ‌ۚ لَا تَسۡجُدُو<rule class=slnt>اۡ</rule> لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَ<rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> لِلَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَهُ<rule class=ghunnah>نّ</rule>َ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ إِيَّاهُ تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 24, 6, 480, 417, 192, 'false'
  );
  
  -- Ayah 38 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4256,
    'فَإِنِ ٱسۡتَكۡبَرُوا۟ فَٱلَّذِینَ عِندَ رَبِّكَ یُسَبِّحُونَ لَهُۥ بِٱلَّیۡلِ وَٱلنَّهَارِ وَهُمۡ لَا یَسۡـَٔمُونَ ۩',
    'فان استكبروا فالذين عند ربك يسبحون له بالليل والنهار وهم لا يسامون',
    'فَإِنِ <rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ يُسَبِّحُونَ لَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَهُمۡ لَا يَسۡــَٔمُ<rule class=madda_permissible>و</rule>نَ ۩ ٣٨',
    38, 24, 6, 480, 417, 192, '{"id":12,"recommended":false,"obligatory":true}'
  );
  
  -- Ayah 39 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4257,
    'وَمِنۡ ءَایَـٰتِهِۦۤ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَـٰشِعَةࣰ فَإِذَاۤ أَنزَلۡنَا عَلَیۡهَا ٱلۡمَاۤءَ ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِیۤ أَحۡیَاهَا لَمُحۡیِ ٱلۡمَوۡتَىٰۤۚ إِنَّهُۥ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'ومن اياته انك ترى الارض خاشعة فاذا انزلنا عليها الماء اهتزت وربت ان الذي احياها لمحيي الموتى انه على كل شيء قدير',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَ<rule class=ghunnah>نّ</rule>َكَ تَرَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ خَ<rule class=madda_normal>ـٰ</rule>شِعَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا عَلَيۡهَا <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>هۡتَزَّتۡ وَرَبَتۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡيَاهَا لَمُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٣٩',
    39, 24, 6, 481, 417, 192, 'false'
  );
  
  -- Ayah 40 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4258,
    'إِنَّ ٱلَّذِینَ یُلۡحِدُونَ فِیۤ ءَایَـٰتِنَا لَا یَخۡفَوۡنَ عَلَیۡنَاۤۗ أَفَمَن یُلۡقَىٰ فِی ٱلنَّارِ خَیۡرٌ أَم مَّن یَأۡتِیۤ ءَامِنࣰا یَوۡمَ ٱلۡقِیَـٰمَةِۚ ٱعۡمَلُوا۟ مَا شِئۡتُمۡ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِیرٌ',
    'ان الذين يلحدون في اياتنا لا يخفون علينا افمن يلقى في النار خير ام من ياتي امنا يوم القيامة اعملوا ما شئتم انه بما تعملون بصير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُلۡحِدُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا لَا يَخۡفَوۡنَ عَلَيۡن<rule class=madda_obligatory_monfasel>َآ‌ۗ</rule> أَفَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُلۡقَىٰ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ خَيۡرٌ أ<rule class=idgham_shafawi>َم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡت<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَامِ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ <rule class=ham_wasl>ٱ</rule>عۡمَلُو<rule class=slnt>اۡ</rule> مَا شِئۡتُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٤٠',
    40, 24, 6, 481, 417, 192, 'false'
  );
  
  -- Ayah 41 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4259,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ بِٱلذِّكۡرِ لَمَّا جَاۤءَهُمۡۖ وَإِنَّهُۥ لَكِتَـٰبٌ عَزِیزࣱ',
    'ان الذين كفروا بالذكر لما جاءهم وانه لكتاب عزيز',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرِ لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَكِتَ<rule class=madda_normal>ـٰ</rule>بٌ عَز<rule class=madda_permissible>ِي</rule>زٌ ٤١',
    41, 24, 6, 481, 417, 192, 'false'
  );
  
  -- Ayah 42 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4260,
    'لَّا یَأۡتِیهِ ٱلۡبَـٰطِلُ مِنۢ بَیۡنِ یَدَیۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ تَنزِیلࣱ مِّنۡ حَكِیمٍ حَمِیدࣲ',
    'لا ياتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد',
    'لَّا يَأۡتِيهِ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِه<rule class=madda_normal>ِۦ</rule>‌ۖ تَ<rule class=ikhafa>نز</rule>ِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ حَكِيمٍ حَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٤٢',
    42, 24, 6, 481, 417, 192, 'false'
  );
  
  -- Ayah 43 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4261,
    'مَّا یُقَالُ لَكَ إِلَّا مَا قَدۡ قِیلَ لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةࣲ وَذُو عِقَابٍ أَلِیمࣲ',
    'ما يقال لك الا ما قد قيل للرسل من قبلك ان ربك لذو مغفرة وذو عقاب اليم',
    'مَّا يُقَالُ لَكَ إِلَّا مَا قَ<rule class=qalaqah>دۡ</rule> قِيلَ لِلرُّسُلِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَذُو مَغۡفِرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َذُو عِقَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٤٣',
    43, 24, 6, 481, 417, 192, 'false'
  );
  
  -- Ayah 44 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4262,
    'وَلَوۡ جَعَلۡنَـٰهُ قُرۡءَانًا أَعۡجَمِیࣰّا لَّقَالُوا۟ لَوۡلَا فُصِّلَتۡ ءَایَـٰتُهُۥۤۖ ءَا۬عۡجَمِیࣱّ وَعَرَبِیࣱّۗ قُلۡ هُوَ لِلَّذِینَ ءَامَنُوا۟ هُدࣰى وَشِفَاۤءࣱۚ وَٱلَّذِینَ لَا یُؤۡمِنُونَ فِیۤ ءَاذَانِهِمۡ وَقۡرࣱ وَهُوَ عَلَیۡهِمۡ عَمًىۚ أُو۟لَـٰۤىِٕكَ یُنَادَوۡنَ مِن مَّكَانِۭ بَعِیدࣲ',
    'ولو جعلناه قرانا اعجميا لقالوا لولا فصلت اياته ااعجمي وعربي قل هو للذين امنوا هدى وشفاء والذين لا يؤمنون في اذانهم وقر وهو عليهم عمى اولئك ينادون من مكان بعيد',
    'وَلَوۡ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ قُرۡءَانًا أَعۡجَمِي<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّقَالُو<rule class=slnt>اۡ</rule> لَوۡلَا فُصِّلَتۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۖ</rule> ءَا۠عۡجَمِ<rule class=idgham_ghunnah>ىٌّ۬</rule> <rule class=idgham_ghunnah>و</rule>َعَرَبِ<rule class=ikhafa>ىٌّ‌ۗ</rule> <rule class=ikhafa>ق</rule>ُلۡ هُوَ لِلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َشِف<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاذَانِهِمۡ وَ<rule class=qalaqah>قۡ</rule><rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ عَلَيۡهِمۡ عَمًى‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ يُنَادَوۡنَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=iqlab>نِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٤٤',
    44, 24, 6, 481, 417, 192, 'false'
  );
  
  -- Ayah 45 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4263,
    'وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ فَٱخۡتُلِفَ فِیهِۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَقُضِیَ بَیۡنَهُمۡۚ وَإِنَّهُمۡ لَفِی شَكࣲّ مِّنۡهُ مُرِیبࣲ',
    'ولقد اتينا موسى الكتاب فاختلف فيه ولولا كلمة سبقت من ربك لقضي بينهم وانهم لفي شك منه مريب',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا مُوسَى <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ فَ<rule class=ham_wasl>ٱ</rule>خۡتُلِفَ فِيهِ‌ۗ وَلَوۡلَا كَلِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>س</rule>َبَقَتۡ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ لَقُضِىَ بَيۡنَهُمۡ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ لَفِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ مُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٤٥',
    45, 24, 6, 481, 418, 192, 'false'
  );
  
  -- Ayah 46 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4264,
    'مَّنۡ عَمِلَ صَـٰلِحࣰا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَاۤءَ فَعَلَیۡهَاۗ وَمَا رَبُّكَ بِظَلَّـٰمࣲ لِّلۡعَبِیدِ',
    'من عمل صالحا فلنفسه ومن اساء فعليها وما ربك بظلام للعبيد',
    'مَّنۡ عَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َلِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَنۡ أَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَعَلَيۡهَا‌ۗ وَمَا رَبُّكَ بِظَلَّ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَب<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٤٦',
    46, 24, 6, 481, 418, 192, 'false'
  );
  
  -- Ayah 47 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4265,
    '۞ إِلَیۡهِ یُرَدُّ عِلۡمُ ٱلسَّاعَةِۚ وَمَا تَخۡرُجُ مِن ثَمَرَ ٰ⁠تࣲ مِّنۡ أَكۡمَامِهَا وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَیَوۡمَ یُنَادِیهِمۡ أَیۡنَ شُرَكَاۤءِی قَالُوۤا۟ ءَاذَنَّـٰكَ مَا مِنَّا مِن شَهِیدࣲ',
    'اليه يرد علم الساعة وما تخرج من ثمرات من اكمامها وما تحمل من انثى ولا تضع الا بعلمه ويوم يناديهم اين شركائي قالوا اذناك ما منا من شهيد',
    '۞إِلَيۡهِ يُرَدُّ عِلۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ‌ۚ وَمَا تَخۡرُجُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َمَر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَكۡمَامِهَا وَمَا تَحۡمِلُ مِنۡ أُ<rule class=ikhafa>نث</rule>َىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَيَوۡمَ يُنَادِيهِمۡ أَيۡنَ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءِى قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَاذَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>كَ مَا مِ<rule class=ghunnah>نّ</rule>َا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٤٧',
    47, 25, 6, 482, 418, 193, 'false'
  );
  
  -- Ayah 48 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4266,
    'وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَدۡعُونَ مِن قَبۡلُۖ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِیصࣲ',
    'وضل عنهم ما كانوا يدعون من قبل وظنوا ما لهم من محيص',
    'وَضَلَّ عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ وَظَ<rule class=ghunnah>نّ</rule>ُو<rule class=slnt>اۡ</rule> مَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّح<rule class=madda_permissible>ِي</rule>صٍ ٤٨',
    48, 25, 6, 482, 418, 193, 'false'
  );
  
  -- Ayah 49 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4267,
    'لَّا یَسۡـَٔمُ ٱلۡإِنسَـٰنُ مِن دُعَاۤءِ ٱلۡخَیۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَیَـُٔوسࣱ قَنُوطࣱ',
    'لا يسام الانسان من دعاء الخير وان مسه الشر فيئوس قنوط',
    'لَّا يَسۡــَٔمُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّسَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّرُّ فَيَــُٔو<rule class=ikhafa>سٌ</rule> <rule class=ikhafa>ق</rule>َن<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ط</rule>ٌ ٤٩',
    49, 25, 6, 482, 418, 193, 'false'
  );
  
  -- Ayah 50 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4268,
    'وَلَىِٕنۡ أَذَقۡنَـٰهُ رَحۡمَةࣰ مِّنَّا مِنۢ بَعۡدِ ضَرَّاۤءَ مَسَّتۡهُ لَیَقُولَنَّ هَـٰذَا لِی وَمَاۤ أَظُنُّ ٱلسَّاعَةَ قَاۤىِٕمَةࣰ وَلَىِٕن رُّجِعۡتُ إِلَىٰ رَبِّیۤ إِنَّ لِی عِندَهُۥ لَلۡحُسۡنَىٰۚ فَلَنُنَبِّئَنَّ ٱلَّذِینَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِیقَنَّهُم مِّنۡ عَذَابٍ غَلِیظࣲ',
    'ولئن اذقناه رحمة منا من بعد ضراء مسته ليقولن هذا لي وما اظن الساعة قائمة ولئن رجعت الى ربي ان لي عنده للحسنى فلننبئن الذين كفروا بما عملوا ولنذيقنهم من عذاب غليظ',
    'وَلَئِنۡ أَذَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ ضَرّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَسَّتۡهُ لَيَقُولَ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لِى وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَظُ<rule class=ghunnah>نّ</rule>ُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّجِعۡتُ إِلَىٰ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=ghunnah>نّ</rule>َ لِى عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> لَلۡحُسۡنَىٰ‌ۚ فَلَنُنَبِّئَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِمَا عَمِلُو<rule class=slnt>اۡ</rule> وَلَنُذِيقَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَذَابٍ غَل<rule class=madda_permissible>ِي</rule>ظٍ ٥٠',
    50, 25, 6, 482, 418, 193, 'false'
  );
  
  -- Ayah 51 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4269,
    'وَإِذَاۤ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَـٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَاۤءٍ عَرِیضࣲ',
    'واذا انعمنا على الانسان اعرض وناى بجانبه واذا مسه الشر فذو دعاء عريض',
    'وَإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡعَمۡنَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ أَعۡرَضَ وَنَـَٔـا بِجَانِبِه<rule class=madda_normal>ِۦ</rule> وَإِذَا مَسَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّرُّ فَذُو دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ عَر<rule class=madda_permissible>ِي</rule>ضٍ ٥١',
    51, 25, 6, 482, 418, 193, 'false'
  );
  
  -- Ayah 52 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4270,
    'قُلۡ أَرَءَیۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ ثُمَّ كَفَرۡتُم بِهِۦ مَنۡ أَضَلُّ مِمَّنۡ هُوَ فِی شِقَاقِۭ بَعِیدࣲ',
    'قل ارايتم ان كان من عند الله ثم كفرتم به من اضل ممن هو في شقاق بعيد',
    'قُلۡ أَرَءَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ كَفَرۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مَنۡ أَضَلُّ مِ<rule class=ghunnah>مّ</rule>َنۡ هُوَ فِى شِقَا<rule class=iqlab>قِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٥٢',
    52, 25, 6, 482, 418, 193, 'false'
  );
  
  -- Ayah 53 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4271,
    'سَنُرِیهِمۡ ءَایَـٰتِنَا فِی ٱلۡـَٔافَاقِ وَفِیۤ أَنفُسِهِمۡ حَتَّىٰ یَتَبَیَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ أَوَلَمۡ یَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ',
    'سنريهم اياتنا في الافاق وفي انفسهم حتى يتبين لهم انه الحق اولم يكف بربك انه على كل شيء شهيد',
    'سَنُرِيهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَفَاقِ وَف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ حَتَّىٰ يَتَبَيَّنَ لَهُمۡ أَ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۗ أَوَلَمۡ يَكۡفِ بِرَبِّكَ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ش</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٥٣',
    53, 25, 6, 482, 418, 193, 'false'
  );
  
  -- Ayah 54 Surah Fussilat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    41,
    4272,
    'أَلَاۤ إِنَّهُمۡ فِی مِرۡیَةࣲ مِّن لِّقَاۤءِ رَبِّهِمۡۗ أَلَاۤ إِنَّهُۥ بِكُلِّ شَیۡءࣲ مُّحِیطُۢ',
    'الا انهم في مرية من لقاء ربهم الا انه بكل شيء محيط',
    'أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ فِى مِرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّق<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رَبِّهِمۡ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِكُلِّ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّح<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ط</rule>ُۢ ٥٤',
    54, 25, 6, 482, 418, 193, 'false'
  );
  

-- Surah Ash-Shura
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (42, 'سُورَةُ الشُّورَىٰ', 'Ash-Shura', 'Consultation', 'Meccan', 53);

  -- Ayah 1 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4273,
    'حمۤ',
    'حم',
    'ح<rule class=madda_necessary>مٓ</rule> ١',
    1, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 2 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4274,
    'عۤسۤقۤ',
    'عسق',
    '<rule class=madda_necessary>عٓ</rule><rule class=madda_necessary>سٓ</rule><rule class=madda_necessary>قٓ</rule> ٢',
    2, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 3 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4275,
    'كَذَ ٰ⁠لِكَ یُوحِیۤ إِلَیۡكَ وَإِلَى ٱلَّذِینَ مِن قَبۡلِكَ ٱللَّهُ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'كذلك يوحي اليك والى الذين من قبلك الله العزيز الحكيم',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ يُوح<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡكَ وَإِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٣',
    3, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 4 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4276,
    'لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَلِیُّ ٱلۡعَظِیمُ',
    'له ما في السماوات وما في الارض وهو العلي العظيم',
    'لَهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِىُّ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٤',
    4, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 5 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4277,
    'تَكَادُ ٱلسَّمَـٰوَ ٰ⁠تُ یَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ وَٱلۡمَلَـٰۤىِٕكَةُ یُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَیَسۡتَغۡفِرُونَ لِمَن فِی ٱلۡأَرۡضِۗ أَلَاۤ إِنَّ ٱللَّهَ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ',
    'تكاد السماوات يتفطرن من فوقهن والملائكة يسبحون بحمد ربهم ويستغفرون لمن في الارض الا ان الله هو الغفور الرحيم',
    'تَكَادُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تُ يَتَفَطَّرۡنَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َوۡقِهِ<rule class=ghunnah>نّ</rule>َ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيَسۡتَغۡفِرُونَ لِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَفُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٥',
    5, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 6 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4278,
    'وَٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ أَوۡلِیَاۤءَ ٱللَّهُ حَفِیظٌ عَلَیۡهِمۡ وَمَاۤ أَنتَ عَلَیۡهِم بِوَكِیلࣲ',
    'والذين اتخذوا من دونه اولياء الله حفيظ عليهم وما انت عليهم بوكيل',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ حَفِيظٌ عَلَيۡهِمۡ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِوَك<rule class=madda_permissible>ِي</rule>لٍ ٦',
    6, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 7 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4279,
    'وَكَذَ ٰ⁠لِكَ أَوۡحَیۡنَاۤ إِلَیۡكَ قُرۡءَانًا عَرَبِیࣰّا لِّتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَا وَتُنذِرَ یَوۡمَ ٱلۡجَمۡعِ لَا رَیۡبَ فِیهِۚ فَرِیقࣱ فِی ٱلۡجَنَّةِ وَفَرِیقࣱ فِی ٱلسَّعِیرِ',
    'وكذلك اوحينا اليك قرانا عربيا لتنذر ام القرى ومن حولها وتنذر يوم الجمع لا ريب فيه فريق في الجنة وفريق في السعير',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ قُرۡءَانًا عَرَبِي<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّتُ<rule class=ikhafa>نذ</rule>ِرَ أُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ وَمَنۡ حَوۡلَهَا وَتُ<rule class=ikhafa>نذ</rule>ِرَ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡجَمۡعِ لَا رَيۡبَ فِيهِ‌ۚ فَرِي<rule class=ikhafa>قٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ وَفَرِي<rule class=ikhafa>قٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّع<rule class=madda_permissible>ِي</rule>رِ ٧',
    7, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 8 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4280,
    'وَلَوۡ شَاۤءَ ٱللَّهُ لَجَعَلَهُمۡ أُمَّةࣰ وَ ٰ⁠حِدَةࣰ وَلَـٰكِن یُدۡخِلُ مَن یَشَاۤءُ فِی رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمُونَ مَا لَهُم مِّن وَلِیࣲّ وَلَا نَصِیرٍ',
    'ولو شاء الله لجعلهم امة واحدة ولكن يدخل من يشاء في رحمته والظالمون ما لهم من ولي ولا نصير',
    'وَلَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَجَعَلَهُمۡ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>دۡ</rule>خِلُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فِى رَحۡمَتِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمُونَ مَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَص<rule class=madda_permissible>ِي</rule>رٍ ٨',
    8, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 9 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4281,
    'أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ أَوۡلِیَاۤءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِیُّ وَهُوَ یُحۡیِ ٱلۡمَوۡتَىٰ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'ام اتخذوا من دونه اولياء فالله هو الولي وهو يحيي الموتى وهو على كل شيء قدير',
    'أَمِ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>للَّهُ هُوَ <rule class=ham_wasl>ٱ</rule>لۡوَلِىُّ وَهُوَ يُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ وَهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٩',
    9, 25, 6, 483, 419, 193, 'false'
  );
  
  -- Ayah 10 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4282,
    'وَمَا ٱخۡتَلَفۡتُمۡ فِیهِ مِن شَیۡءࣲ فَحُكۡمُهُۥۤ إِلَى ٱللَّهِۚ ذَ ٰ⁠لِكُمُ ٱللَّهُ رَبِّی عَلَیۡهِ تَوَكَّلۡتُ وَإِلَیۡهِ أُنِیبُ',
    'وما اختلفتم فيه من شيء فحكمه الى الله ذلكم الله ربي عليه توكلت واليه انيب',
    'وَمَا <rule class=ham_wasl>ٱ</rule>خۡتَلَفۡتُمۡ فِيهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َحُكۡمُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبِّى عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ُ ١٠',
    10, 25, 6, 483, 420, 193, 'false'
  );
  
  -- Ayah 11 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4283,
    'فَاطِرُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَ ٰ⁠جࣰا وَمِنَ ٱلۡأَنۡعَـٰمِ أَزۡوَ ٰ⁠جࣰا یَذۡرَؤُكُمۡ فِیهِۚ لَیۡسَ كَمِثۡلِهِۦ شَیۡءࣱۖ وَهُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ',
    'فاطر السماوات والارض جعل لكم من انفسكم ازواجا ومن الانعام ازواجا يذرؤكم فيه ليس كمثله شيء وهو السميع البصير',
    'فَاطِرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ جَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ أَزۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>جًا‌ۖ</rule> <rule class=idgham_ghunnah>ي</rule>َذۡرَؤُكُمۡ فِيهِ‌ۚ لَيۡسَ كَمِثۡلِه<rule class=madda_normal>ِۦ</rule> ش<rule class=idgham_ghunnah>َىۡءٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡبَص<rule class=madda_permissible>ِي</rule>رُ ١١',
    11, 25, 6, 484, 420, 193, 'false'
  );
  
  -- Ayah 12 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4284,
    'لَهُۥ مَقَالِیدُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّهُۥ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'له مقاليد السماوات والارض يبسط الرزق لمن يشاء ويقدر انه بكل شيء عليم',
    'لَهُ<rule class=madda_normal>ۥ</rule> مَقَالِيدُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ يَ<rule class=qalaqah>بۡ</rule>سُطُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَ<rule class=qalaqah>قۡ</rule>دِرُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٢',
    12, 25, 6, 484, 420, 193, 'false'
  );
  
  -- Ayah 13 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4285,
    '۞ شَرَعَ لَكُم مِّنَ ٱلدِّینِ مَا وَصَّىٰ بِهِۦ نُوحࣰا وَٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ وَمَا وَصَّیۡنَا بِهِۦۤ إِبۡرَ ٰ⁠هِیمَ وَمُوسَىٰ وَعِیسَىٰۤۖ أَنۡ أَقِیمُوا۟ ٱلدِّینَ وَلَا تَتَفَرَّقُوا۟ فِیهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِینَ مَا تَدۡعُوهُمۡ إِلَیۡهِۚ ٱللَّهُ یَجۡتَبِیۤ إِلَیۡهِ مَن یَشَاۤءُ وَیَهۡدِیۤ إِلَیۡهِ مَن یُنِیبُ',
    'شرع لكم من الدين ما وصى به نوحا والذي اوحينا اليك وما وصينا به ابراهيم وموسى وعيسى ان اقيموا الدين ولا تتفرقوا فيه كبر على المشركين ما تدعوهم اليه الله يجتبي اليه من يشاء ويهدي اليه من ينيب',
    '۞شَرَعَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ مَا وَصَّىٰ بِه<rule class=madda_normal>ِۦ</rule> نُو<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ وَمَا وَصَّيۡنَا بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَمُوسَىٰ وَعِيسَ<rule class=madda_obligatory_monfasel>ىٰٓ‌ۖ</rule> أَنۡ أَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ وَلَا تَتَفَرَّقُو<rule class=slnt>اۡ</rule> فِيهِ‌ۚ كَبُرَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ مَا تَ<rule class=qalaqah>دۡ</rule>عُوهُمۡ إِلَيۡهِ‌ۚ <rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=qalaqah>جۡ</rule>تَب<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ُ ١٣',
    13, 25, 6, 484, 420, 194, 'false'
  );
  
  -- Ayah 14 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4286,
    'وَمَا تَفَرَّقُوۤا۟ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَهُمُ ٱلۡعِلۡمُ بَغۡیَۢا بَیۡنَهُمۡۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى لَّقُضِیَ بَیۡنَهُمۡۚ وَإِنَّ ٱلَّذِینَ أُورِثُوا۟ ٱلۡكِتَـٰبَ مِنۢ بَعۡدِهِمۡ لَفِی شَكࣲّ مِّنۡهُ مُرِیبࣲ',
    'وما تفرقوا الا من بعد ما جاءهم العلم بغيا بينهم ولولا كلمة سبقت من ربك الى اجل مسمى لقضي بينهم وان الذين اورثوا الكتاب من بعدهم لفي شك منه مريب',
    'وَمَا تَفَرَّق<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمُ بَغۡي<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَهُمۡ‌ۚ وَلَوۡلَا كَلِمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>س</rule>َبَقَتۡ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=idgham_wo_ghunnah>ًّى</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّقُضِىَ بَيۡنَهُمۡ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُورِثُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ لَفِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ مُر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ١٤',
    14, 25, 6, 484, 420, 194, 'false'
  );
  
  -- Ayah 15 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4287,
    'فَلِذَ ٰ⁠لِكَ فَٱدۡعُۖ وَٱسۡتَقِمۡ كَمَاۤ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَاۤءَهُمۡۖ وَقُلۡ ءَامَنتُ بِمَاۤ أَنزَلَ ٱللَّهُ مِن كِتَـٰبࣲۖ وَأُمِرۡتُ لِأَعۡدِلَ بَیۡنَكُمُۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمۡۖ لَنَاۤ أَعۡمَـٰلُنَا وَلَكُمۡ أَعۡمَـٰلُكُمۡۖ لَا حُجَّةَ بَیۡنَنَا وَبَیۡنَكُمُۖ ٱللَّهُ یَجۡمَعُ بَیۡنَنَاۖ وَإِلَیۡهِ ٱلۡمَصِیرُ',
    'فلذلك فادع واستقم كما امرت ولا تتبع اهواءهم وقل امنت بما انزل الله من كتاب وامرت لاعدل بينكم الله ربنا وربكم لنا اعمالنا ولكم اعمالكم لا حجة بيننا وبينكم الله يجمع بيننا واليه المصير',
    'فَلِذ<rule class=madda_normal>ٰ</rule>لِكَ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>سۡتَقِمۡ كَم<rule class=madda_obligatory_monfasel>َآ</rule> أُمِرۡتَ‌ۖ وَلَا تَتَّبِعۡ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ‌ۖ وَقُلۡ ءَامَ<rule class=ikhafa>نت</rule>ُ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َأُمِرۡتُ لِأَعۡدِلَ بَيۡنَكُمُ‌ۖ <rule class=ham_wasl>ٱ</rule>للَّهُ رَبُّنَا وَرَبُّكُمۡ‌ۖ لَن<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُنَا وَلَكُمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُكُمۡ‌ۖ لَا حُجَّةَ بَيۡنَنَا وَبَيۡنَكُمُ‌ۖ <rule class=ham_wasl>ٱ</rule>للَّهُ يَ<rule class=qalaqah>جۡ</rule>مَعُ بَيۡنَنَا‌ۖ وَإِلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٥',
    15, 25, 6, 484, 420, 194, 'false'
  );
  
  -- Ayah 16 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4288,
    'وَٱلَّذِینَ یُحَاۤجُّونَ فِی ٱللَّهِ مِنۢ بَعۡدِ مَا ٱسۡتُجِیبَ لَهُۥ حُجَّتُهُمۡ دَاحِضَةٌ عِندَ رَبِّهِمۡ وَعَلَیۡهِمۡ غَضَبࣱ وَلَهُمۡ عَذَابࣱ شَدِیدٌ',
    'والذين يحاجون في الله من بعد ما استجيب له حجتهم داحضة عند ربهم وعليهم غضب ولهم عذاب شديد',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُح<rule class=madda_necessary>َا</rule>ٓجُّونَ فِى <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا <rule class=ham_wasl>ٱ</rule>سۡتُجِيبَ لَهُ<rule class=madda_normal>ۥ</rule> حُجَّتُهُمۡ دَاحِضَةٌ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ وَعَلَيۡهِمۡ غَضَ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ش</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٦',
    16, 25, 6, 485, 420, 194, 'false'
  );
  
  -- Ayah 17 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4289,
    'ٱللَّهُ ٱلَّذِیۤ أَنزَلَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ وَٱلۡمِیزَانَۗ وَمَا یُدۡرِیكَ لَعَلَّ ٱلسَّاعَةَ قَرِیبࣱ',
    'الله الذي انزل الكتاب بالحق والميزان وما يدريك لعل الساعة قريب',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَ<rule class=ham_wasl>ٱ</rule>لۡمِيزَانَ‌ۗ وَمَا يُ<rule class=qalaqah>دۡ</rule>رِيكَ لَعَلَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ قَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ١٧',
    17, 25, 6, 485, 420, 194, 'false'
  );
  
  -- Ayah 18 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4290,
    'یَسۡتَعۡجِلُ بِهَا ٱلَّذِینَ لَا یُؤۡمِنُونَ بِهَاۖ وَٱلَّذِینَ ءَامَنُوا۟ مُشۡفِقُونَ مِنۡهَا وَیَعۡلَمُونَ أَنَّهَا ٱلۡحَقُّۗ أَلَاۤ إِنَّ ٱلَّذِینَ یُمَارُونَ فِی ٱلسَّاعَةِ لَفِی ضَلَـٰلِۭ بَعِیدٍ',
    'يستعجل بها الذين لا يؤمنون بها والذين امنوا مشفقون منها ويعلمون انها الحق الا ان الذين يمارون في الساعة لفي ضلال بعيد',
    'يَسۡتَعۡجِلُ بِهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِهَا‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مُشۡفِقُونَ مِنۡهَا وَيَعۡلَمُونَ أَ<rule class=ghunnah>نّ</rule>َهَا <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُمَارُونَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ لَفِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>لِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ١٨',
    18, 25, 6, 485, 420, 194, 'false'
  );
  
  -- Ayah 19 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4291,
    'ٱللَّهُ لَطِیفُۢ بِعِبَادِهِۦ یَرۡزُقُ مَن یَشَاۤءُۖ وَهُوَ ٱلۡقَوِیُّ ٱلۡعَزِیزُ',
    'الله لطيف بعباده يرزق من يشاء وهو القوي العزيز',
    'ٱللَّهُ لَطِي<rule class=iqlab>فُۢ</rule> <rule class=iqlab>ب</rule>ِعِبَادِه<rule class=madda_normal>ِۦ</rule> يَرۡزُقُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡقَوِىُّ <rule class=ham_wasl>ٱ</rule>لۡعَز<rule class=madda_permissible>ِي</rule>زُ ١٩',
    19, 25, 6, 485, 420, 194, 'false'
  );
  
  -- Ayah 20 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4292,
    'مَن كَانَ یُرِیدُ حَرۡثَ ٱلۡـَٔاخِرَةِ نَزِدۡ لَهُۥ فِی حَرۡثِهِۦۖ وَمَن كَانَ یُرِیدُ حَرۡثَ ٱلدُّنۡیَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِی ٱلۡـَٔاخِرَةِ مِن نَّصِیبٍ',
    'من كان يريد حرث الاخرة نزد له في حرثه ومن كان يريد حرث الدنيا نؤته منها وما له في الاخرة من نصيب',
    'مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يُرِيدُ حَرۡثَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ نَزِ<rule class=qalaqah>دۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> فِى حَرۡثِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يُرِيدُ حَرۡثَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا نُؤۡتِه<rule class=madda_normal>ِۦ</rule> مِنۡهَا وَمَا لَهُ<rule class=madda_normal>ۥ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّص<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٢٠',
    20, 25, 6, 485, 421, 194, 'false'
  );
  
  -- Ayah 21 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4293,
    'أَمۡ لَهُمۡ شُرَكَـٰۤؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّینِ مَا لَمۡ یَأۡذَنۢ بِهِ ٱللَّهُۚ وَلَوۡلَا كَلِمَةُ ٱلۡفَصۡلِ لَقُضِیَ بَیۡنَهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِینَ لَهُمۡ عَذَابٌ أَلِیمࣱ',
    'ام لهم شركاء شرعوا لهم من الدين ما لم ياذن به الله ولولا كلمة الفصل لقضي بينهم وان الظالمين لهم عذاب اليم',
    'أَمۡ لَهُمۡ شُرَكَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُ<rule class=slnt>اۡ</rule> شَرَعُو<rule class=slnt>اۡ</rule> لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ مَا لَمۡ يَأۡذ<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>ِهِ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَلَوۡلَا كَلِمَةُ <rule class=ham_wasl>ٱ</rule>لۡفَصۡلِ لَقُضِىَ بَيۡنَهُمۡ‌ۗ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ لَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٢١',
    21, 25, 6, 485, 421, 194, 'false'
  );
  
  -- Ayah 22 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4294,
    'تَرَى ٱلظَّـٰلِمِینَ مُشۡفِقِینَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعُۢ بِهِمۡۗ وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فِی رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا یَشَاۤءُونَ عِندَ رَبِّهِمۡۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِیرُ',
    'ترى الظالمين مشفقين مما كسبوا وهو واقع بهم والذين امنوا وعملوا الصالحات في روضات الجنات لهم ما يشاءون عند ربهم ذلك هو الفضل الكبير',
    'تَرَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ مُشۡفِقِينَ مِ<rule class=ghunnah>مّ</rule>َا كَسَبُو<rule class=slnt>اۡ</rule> وَهُوَ وَاقِ<rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>ِهِمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فِى رَوۡضَاتِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َاتِ‌ۖ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُونَ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَضۡلُ <rule class=ham_wasl>ٱ</rule>لۡكَب<rule class=madda_permissible>ِي</rule>رُ ٢٢',
    22, 25, 6, 485, 421, 194, 'false'
  );
  
  -- Ayah 23 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4295,
    'ذَ ٰ⁠لِكَ ٱلَّذِی یُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِۗ قُل لَّاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ أَجۡرًا إِلَّا ٱلۡمَوَدَّةَ فِی ٱلۡقُرۡبَىٰۗ وَمَن یَقۡتَرِفۡ حَسَنَةࣰ نَّزِدۡ لَهُۥ فِیهَا حُسۡنًاۚ إِنَّ ٱللَّهَ غَفُورࣱ شَكُورٌ',
    'ذلك الذي يبشر الله عباده الذين امنوا وعملوا الصالحات قل لا اسالكم عليه اجرا الا المودة في القربى ومن يقترف حسنة نزد له فيها حسنا ان الله غفور شكور',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُبَشِّرُ <rule class=ham_wasl>ٱ</rule>للَّهُ عِبَادَهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ‌ۗ قُل لّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡــَٔلُكُمۡ عَلَيۡهِ أَ<rule class=qalaqah>جۡ</rule>رًا إِلَّا <rule class=ham_wasl>ٱ</rule>لۡمَوَدَّةَ فِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>تَرِفۡ حَسَنَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ن</rule>َّزِ<rule class=qalaqah>دۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> فِيهَا حُسۡنًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ش</rule>َك<rule class=madda_permissible>ُو</rule>رٌ ٢٣',
    23, 25, 6, 486, 421, 194, 'false'
  );
  
  -- Ayah 24 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4296,
    'أَمۡ یَقُولُونَ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰاۖ فَإِن یَشَإِ ٱللَّهُ یَخۡتِمۡ عَلَىٰ قَلۡبِكَۗ وَیَمۡحُ ٱللَّهُ ٱلۡبَـٰطِلَ وَیُحِقُّ ٱلۡحَقَّ بِكَلِمَـٰتِهِۦۤۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'ام يقولون افترى على الله كذبا فان يشا الله يختم على قلبك ويمح الله الباطل ويحق الحق بكلماته انه عليم بذات الصدور',
    'أَمۡ يَقُولُونَ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِ<rule class=ikhafa>بًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َشَإِ <rule class=ham_wasl>ٱ</rule>للَّهُ يَخۡتِمۡ عَلَىٰ قَلۡبِكَ‌ۗ وَيَمۡحُ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلَ وَيُحِقُّ <rule class=ham_wasl>ٱ</rule>لۡحَقَّ بِكَلِمَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٢٤',
    24, 25, 6, 486, 421, 194, 'false'
  );
  
  -- Ayah 25 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4297,
    'وَهُوَ ٱلَّذِی یَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَیَعۡفُوا۟ عَنِ ٱلسَّیِّـَٔاتِ وَیَعۡلَمُ مَا تَفۡعَلُونَ',
    'وهو الذي يقبل التوبة عن عباده ويعفو عن السيئات ويعلم ما تفعلون',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يَ<rule class=qalaqah>قۡ</rule>بَلُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡبَةَ عَنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule> وَيَعۡفُو<rule class=slnt>اۡ</rule> عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ وَيَعۡلَمُ مَا تَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 25, 6, 486, 421, 194, 'false'
  );
  
  -- Ayah 26 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4298,
    'وَیَسۡتَجِیبُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَیَزِیدُهُم مِّن فَضۡلِهِۦۚ وَٱلۡكَـٰفِرُونَ لَهُمۡ عَذَابࣱ شَدِیدࣱ',
    'ويستجيب الذين امنوا وعملوا الصالحات ويزيدهم من فضله والكافرون لهم عذاب شديد',
    'وَيَسۡتَجِيبُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَيَزِيدُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرُونَ لَهُمۡ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ش</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٢٦',
    26, 25, 6, 486, 421, 194, 'false'
  );
  
  -- Ayah 27 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4299,
    '۞ وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡا۟ فِی ٱلۡأَرۡضِ وَلَـٰكِن یُنَزِّلُ بِقَدَرࣲ مَّا یَشَاۤءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِیرُۢ بَصِیرࣱ',
    'ولو بسط الله الرزق لعباده لبغوا في الارض ولكن ينزل بقدر ما يشاء انه بعباده خبير بصير',
    '۞وَلَوۡ بَسَطَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّزۡقَ لِعِبَادِه<rule class=madda_normal>ِۦ</rule> لَبَغَوۡ<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>ُنَزِّلُ بِقَدَ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِعِبَادِه<rule class=madda_normal>ِۦ</rule> خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>َص<rule class=madda_permissible>ِي</rule>رٌ ٢٧',
    27, 25, 6, 486, 421, 195, 'false'
  );
  
  -- Ayah 28 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4300,
    'وَهُوَ ٱلَّذِی یُنَزِّلُ ٱلۡغَیۡثَ مِنۢ بَعۡدِ مَا قَنَطُوا۟ وَیَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِیُّ ٱلۡحَمِیدُ',
    'وهو الذي ينزل الغيث من بعد ما قنطوا وينشر رحمته وهو الولي الحميد',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُنَزِّلُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡثَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا قَنَطُو<rule class=slnt>اۡ</rule> وَيَ<rule class=ikhafa>نش</rule>ُرُ رَحۡمَتَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡوَلِىُّ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٢٨',
    28, 25, 6, 486, 421, 195, 'false'
  );
  
  -- Ayah 29 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4301,
    'وَمِنۡ ءَایَـٰتِهِۦ خَلۡقُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِیهِمَا مِن دَاۤبَّةࣲۚ وَهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا یَشَاۤءُ قَدِیرࣱ',
    'ومن اياته خلق السماوات والارض وما بث فيهما من دابة وهو على جمعهم اذا يشاء قدير',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> خَلۡقُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَثَّ فِيهِمَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّ<rule class=idgham_ghunnah>ةٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ قَد<rule class=madda_permissible>ِي</rule>رٌ ٢٩',
    29, 25, 6, 486, 421, 195, 'false'
  );
  
  -- Ayah 30 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4302,
    'وَمَاۤ أَصَـٰبَكُم مِّن مُّصِیبَةࣲ فَبِمَا كَسَبَتۡ أَیۡدِیكُمۡ وَیَعۡفُوا۟ عَن كَثِیرࣲ',
    'وما اصابكم من مصيبة فبما كسبت ايديكم ويعفو عن كثير',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَصَ<rule class=madda_normal>ـٰ</rule>بَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّصِيبَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َبِمَا كَسَبَتۡ أَيۡدِيكُمۡ وَيَعۡفُو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َث<rule class=madda_permissible>ِي</rule>رٍ ٣٠',
    30, 25, 6, 486, 422, 195, 'false'
  );
  
  -- Ayah 31 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4303,
    'وَمَاۤ أَنتُم بِمُعۡجِزِینَ فِی ٱلۡأَرۡضِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ',
    'وما انتم بمعجزين في الارض وما لكم من دون الله من ولي ولا نصير',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمُعۡجِزِينَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَمَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَص<rule class=madda_permissible>ِي</rule>رٍ ٣١',
    31, 25, 6, 486, 422, 195, 'false'
  );
  
  -- Ayah 32 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4304,
    'وَمِنۡ ءَایَـٰتِهِ ٱلۡجَوَارِ فِی ٱلۡبَحۡرِ كَٱلۡأَعۡلَـٰمِ',
    'ومن اياته الجوار في البحر كالاعلام',
    'وَمِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِهِ <rule class=ham_wasl>ٱ</rule>لۡجَوَارِ فِى <rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ كَ<rule class=ham_wasl>ٱ</rule>لۡأَعۡلَ<rule class=madda_permissible>ـٰ</rule>مِ ٣٢',
    32, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 33 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4305,
    'إِن یَشَأۡ یُسۡكِنِ ٱلرِّیحَ فَیَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورٍ',
    'ان يشا يسكن الريح فيظللن رواكد على ظهره ان في ذلك لايات لكل صبار شكور',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َشَأۡ يُسۡكِنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيحَ فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ صَبَّا<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ش</rule>َك<rule class=madda_permissible>ُو</rule>رٍ ٣٣',
    33, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 34 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4306,
    'أَوۡ یُوبِقۡهُنَّ بِمَا كَسَبُوا۟ وَیَعۡفُ عَن كَثِیرࣲ',
    'او يوبقهن بما كسبوا ويعف عن كثير',
    'أَوۡ يُوبِ<rule class=qalaqah>قۡ</rule>هُ<rule class=ghunnah>نّ</rule>َ بِمَا كَسَبُو<rule class=slnt>اۡ</rule> وَيَعۡفُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َث<rule class=madda_permissible>ِي</rule>رٍ ٣٤',
    34, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 35 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4307,
    'وَیَعۡلَمَ ٱلَّذِینَ یُجَـٰدِلُونَ فِیۤ ءَایَـٰتِنَا مَا لَهُم مِّن مَّحِیصࣲ',
    'ويعلم الذين يجادلون في اياتنا ما لهم من محيص',
    'وَيَعۡلَمَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُجَ<rule class=madda_normal>ـٰ</rule>دِلُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا مَا لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّح<rule class=madda_permissible>ِي</rule>صٍ ٣٥',
    35, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 36 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4308,
    'فَمَاۤ أُوتِیتُم مِّن شَیۡءࣲ فَمَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَمَا عِندَ ٱللَّهِ خَیۡرࣱ وَأَبۡقَىٰ لِلَّذِینَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ',
    'فما اوتيتم من شيء فمتاع الحياة الدنيا وما عند الله خير وابقى للذين امنوا وعلى ربهم يتوكلون',
    'فَم<rule class=madda_obligatory_monfasel>َآ</rule> أُوتِيت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َمَتَ<rule class=madda_normal>ـٰ</rule>عُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَمَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>بۡ</rule>قَىٰ لِلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّل<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 37 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4309,
    'وَٱلَّذِینَ یَجۡتَنِبُونَ كَبَـٰۤىِٕرَ ٱلۡإِثۡمِ وَٱلۡفَوَ ٰ⁠حِشَ وَإِذَا مَا غَضِبُوا۟ هُمۡ یَغۡفِرُونَ',
    'والذين يجتنبون كبائر الاثم والفواحش واذا ما غضبوا هم يغفرون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>جۡ</rule>تَنِبُونَ كَبَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرَ <rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَ<rule class=ham_wasl>ٱ</rule>لۡفَو<rule class=madda_normal>ٰ</rule>حِشَ وَإِذَا مَا غَضِبُو<rule class=slnt>اۡ</rule> هُمۡ يَغۡفِر<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 38 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4310,
    'وَٱلَّذِینَ ٱسۡتَجَابُوا۟ لِرَبِّهِمۡ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَیۡنَهُمۡ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ',
    'والذين استجابوا لربهم واقاموا الصلاة وامرهم شورى بينهم ومما رزقناهم ينفقون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>سۡتَجَابُو<rule class=slnt>اۡ</rule> لِرَبِّهِمۡ وَأَقَامُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَمۡرُهُمۡ شُورَىٰ بَيۡنَهُمۡ وَمِ<rule class=ghunnah>مّ</rule>َا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ يُ<rule class=ikhafa>نف</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 39 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4311,
    'وَٱلَّذِینَ إِذَاۤ أَصَابَهُمُ ٱلۡبَغۡیُ هُمۡ یَنتَصِرُونَ',
    'والذين اذا اصابهم البغي هم ينتصرون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَغۡىُ هُمۡ يَ<rule class=ikhafa>نت</rule>َصِر<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 40 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4312,
    'وَجَزَ ٰ⁠ۤؤُا۟ سَیِّئَةࣲ سَیِّئَةࣱ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا یُحِبُّ ٱلظَّـٰلِمِینَ',
    'وجزاء سيئة سيئة مثلها فمن عفا واصلح فاجره على الله انه لا يحب الظالمين',
    'وَجَز<rule class=madda_obligatory_mottasel>ٰ</rule>ٓؤُ<rule class=slnt>اۡ</rule> سَيِّئَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>س</rule>َيِّئَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلُهَا‌ۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَ<rule class=qalaqah>جۡ</rule>رُهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَا يُحِبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 41 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4313,
    'وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُو۟لَـٰۤىِٕكَ مَا عَلَیۡهِم مِّن سَبِیلٍ',
    'ولمن انتصر بعد ظلمه فاولئك ما عليهم من سبيل',
    'وَلَمَنِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َصَرَ بَعۡدَ ظُلۡمِه<rule class=madda_normal>ِۦ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ مَا عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َب<rule class=madda_permissible>ِي</rule>لٍ ٤١',
    41, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 42 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4314,
    'إِنَّمَا ٱلسَّبِیلُ عَلَى ٱلَّذِینَ یَظۡلِمُونَ ٱلنَّاسَ وَیَبۡغُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ أَلِیمࣱ',
    'انما السبيل على الذين يظلمون الناس ويبغون في الارض بغير الحق اولئك لهم عذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلُ عَلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَظۡلِمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ وَيَ<rule class=qalaqah>بۡ</rule>غُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٤٢',
    42, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 43 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4315,
    'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَ ٰ⁠لِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ',
    'ولمن صبر وغفر ان ذلك لمن عزم الامور',
    'وَلَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َبَرَ وَغَفَرَ إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ لَمِنۡ عَزۡمِ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رِ ٤٣',
    43, 25, 6, 487, 422, 195, 'false'
  );
  
  -- Ayah 44 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4316,
    'وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِیࣲّ مِّنۢ بَعۡدِهِۦۗ وَتَرَى ٱلظَّـٰلِمِینَ لَمَّا رَأَوُا۟ ٱلۡعَذَابَ یَقُولُونَ هَلۡ إِلَىٰ مَرَدࣲّ مِّن سَبِیلࣲ',
    'ومن يضلل الله فما له من ولي من بعده وترى الظالمين لما راوا العذاب يقولون هل الى مرد من سبيل',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَمَا لَهُ<rule class=madda_normal>ۥ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َلِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِه<rule class=madda_normal>ِۦ</rule>‌ۗ وَتَرَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ لَ<rule class=ghunnah>مّ</rule>َا رَأَوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ يَقُولُونَ هَلۡ إِلَىٰ مَرَ<rule class=idgham_ghunnah>دٍّ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َب<rule class=madda_permissible>ِي</rule>لٍ ٤٤',
    44, 25, 6, 487, 423, 195, 'false'
  );
  
  -- Ayah 45 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4317,
    'وَتَرَىٰهُمۡ یُعۡرَضُونَ عَلَیۡهَا خَـٰشِعِینَ مِنَ ٱلذُّلِّ یَنظُرُونَ مِن طَرۡفٍ خَفِیࣲّۗ وَقَالَ ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ ٱلۡخَـٰسِرِینَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ وَأَهۡلِیهِمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۗ أَلَاۤ إِنَّ ٱلظَّـٰلِمِینَ فِی عَذَابࣲ مُّقِیمࣲ',
    'وتراهم يعرضون عليها خاشعين من الذل ينظرون من طرف خفي وقال الذين امنوا ان الخاسرين الذين خسروا انفسهم واهليهم يوم القيامة الا ان الظالمين في عذاب مقيم',
    'وَتَرَ<rule class=madda_normal>ٮٰ</rule>هُمۡ يُعۡرَضُونَ عَلَيۡهَا خَ<rule class=madda_normal>ـٰ</rule>شِعِينَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذُّلِّ يَ<rule class=ikhafa>نظ</rule>ُرُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َرۡفٍ خَفِ<rule class=idgham_ghunnah>ىٍّ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِرِينَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ خَسِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ وَأَهۡلِيهِمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ فِى عَذَا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّق<rule class=madda_permissible>ِي</rule>مٍ ٤٥',
    45, 25, 6, 488, 423, 195, 'false'
  );
  
  -- Ayah 46 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4318,
    'وَمَا كَانَ لَهُم مِّنۡ أَوۡلِیَاۤءَ یَنصُرُونَهُم مِّن دُونِ ٱللَّهِۗ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِیلٍ',
    'وما كان لهم من اولياء ينصرونهم من دون الله ومن يضلل الله فما له من سبيل',
    'وَمَا كَانَ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ يَ<rule class=ikhafa>نص</rule>ُرُونَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضۡلِلِ <rule class=ham_wasl>ٱ</rule>للَّهُ فَمَا لَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َب<rule class=madda_permissible>ِي</rule>لٍ ٤٦',
    46, 25, 6, 488, 423, 195, 'false'
  );
  
  -- Ayah 47 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4319,
    'ٱسۡتَجِیبُوا۟ لِرَبِّكُم مِّن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم مِّن مَّلۡجَإࣲ یَوۡمَىِٕذࣲ وَمَا لَكُم مِّن نَّكِیرࣲ',
    'استجيبوا لربكم من قبل ان ياتي يوم لا مرد له من الله ما لكم من ملجا يومئذ وما لكم من نكير',
    'ٱسۡتَجِيبُو<rule class=slnt>اۡ</rule> لِرَبِّك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِىَ يَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا مَرَدَّ لَهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ مَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّلۡجَ<rule class=idgham_ghunnah>إٍ</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّك<rule class=madda_permissible>ِي</rule>رٍ ٤٧',
    47, 25, 6, 488, 423, 195, 'false'
  );
  
  -- Ayah 48 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4320,
    'فَإِنۡ أَعۡرَضُوا۟ فَمَاۤ أَرۡسَلۡنَـٰكَ عَلَیۡهِمۡ حَفِیظًاۖ إِنۡ عَلَیۡكَ إِلَّا ٱلۡبَلَـٰغُۗ وَإِنَّاۤ إِذَاۤ أَذَقۡنَا ٱلۡإِنسَـٰنَ مِنَّا رَحۡمَةࣰ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَیِّئَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ فَإِنَّ ٱلۡإِنسَـٰنَ كَفُورࣱ',
    'فان اعرضوا فما ارسلناك عليهم حفيظا ان عليك الا البلاغ وانا اذا اذقنا الانسان منا رحمة فرح بها وان تصبهم سيئة بما قدمت ايديهم فان الانسان كفور',
    'فَإِنۡ أَعۡرَضُو<rule class=slnt>اۡ</rule> فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ عَلَيۡهِمۡ حَفِيظًا‌ۖ إِنۡ عَلَيۡكَ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ‌ۗ وَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَذَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ مِ<rule class=ghunnah>نّ</rule>َا رَحۡمَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َرِحَ بِهَا‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِ<rule class=qalaqah>بۡ</rule>هُمۡ سَيِّئَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ كَف<rule class=madda_permissible>ُو</rule>رٌ ٤٨',
    48, 25, 6, 488, 423, 195, 'false'
  );
  
  -- Ayah 49 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4321,
    'لِّلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ یَخۡلُقُ مَا یَشَاۤءُۚ یَهَبُ لِمَن یَشَاۤءُ إِنَـٰثࣰا وَیَهَبُ لِمَن یَشَاۤءُ ٱلذُّكُورَ',
    'لله ملك السماوات والارض يخلق ما يشاء يهب لمن يشاء اناثا ويهب لمن يشاء الذكور',
    'لِّلَّهِ مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ يَخۡلُقُ مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ يَهَبُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ إِنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>ثًا</rule> <rule class=idgham_ghunnah>و</rule>َيَهَبُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذُّك<rule class=madda_permissible>ُو</rule>رَ ٤٩',
    49, 25, 6, 488, 423, 195, 'false'
  );
  
  -- Ayah 50 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4322,
    'أَوۡ یُزَوِّجُهُمۡ ذُكۡرَانࣰا وَإِنَـٰثࣰاۖ وَیَجۡعَلُ مَن یَشَاۤءُ عَقِیمًاۚ إِنَّهُۥ عَلِیمࣱ قَدِیرࣱ',
    'او يزوجهم ذكرانا واناثا ويجعل من يشاء عقيما انه عليم قدير',
    'أَوۡ يُزَوِّجُهُمۡ ذُكۡرَا<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َإِنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>ثًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َيَ<rule class=qalaqah>جۡ</rule>عَلُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ عَقِيمًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلِي<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٥٠',
    50, 25, 6, 488, 423, 195, 'false'
  );
  
  -- Ayah 51 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4323,
    '۞ وَمَا كَانَ لِبَشَرٍ أَن یُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡیًا أَوۡ مِن وَرَاۤىِٕ حِجَابٍ أَوۡ یُرۡسِلَ رَسُولࣰا فَیُوحِیَ بِإِذۡنِهِۦ مَا یَشَاۤءُۚ إِنَّهُۥ عَلِیٌّ حَكِیمࣱ',
    'وما كان لبشر ان يكلمه الله الا وحيا او من وراء حجاب او يرسل رسولا فيوحي باذنه ما يشاء انه علي حكيم',
    '۞وَمَا كَانَ لِبَشَرٍ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَلِّمَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَّا وَحۡيًا أَوۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َرَآىِٕ حِجَابٍ أَوۡ يُرۡسِلَ رَسُول<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>َيُوحِىَ بِإِذۡنِه<rule class=madda_normal>ِۦ</rule> مَا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلِىٌّ حَك<rule class=madda_permissible>ِي</rule>مٌ ٥١',
    51, 25, 6, 488, 423, 196, 'false'
  );
  
  -- Ayah 52 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4324,
    'وَكَذَ ٰ⁠لِكَ أَوۡحَیۡنَاۤ إِلَیۡكَ رُوحࣰا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِی مَا ٱلۡكِتَـٰبُ وَلَا ٱلۡإِیمَـٰنُ وَلَـٰكِن جَعَلۡنَـٰهُ نُورࣰا نَّهۡدِی بِهِۦ مَن نَّشَاۤءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِیۤ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'وكذلك اوحينا اليك روحا من امرنا ما كنت تدري ما الكتاب ولا الايمان ولكن جعلناه نورا نهدي به من نشاء من عبادنا وانك لتهدي الى صراط مستقيم',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ أَوۡحَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ رُو<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَمۡرِنَا‌ۚ مَا كُ<rule class=ikhafa>نت</rule>َ تَ<rule class=qalaqah>دۡ</rule>رِى مَا <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بُ وَلَا <rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نُ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ نُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>ن</rule>َّهۡدِى بِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مِنۡ عِبَادِنَا‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َكَ لَتَهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٥٢',
    52, 25, 6, 489, 423, 196, 'false'
  );
  
  -- Ayah 53 Surah Ash-Shura
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    42,
    4325,
    'صِرَ ٰ⁠طِ ٱللَّهِ ٱلَّذِی لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۗ أَلَاۤ إِلَى ٱللَّهِ تَصِیرُ ٱلۡأُمُورُ',
    'صراط الله الذي له ما في السماوات وما في الارض الا الى الله تصير الامور',
    'صِر<rule class=madda_normal>ٰ</rule>طِ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّذِى لَهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۗ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تَصِيرُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رُ ٥٣',
    53, 25, 6, 489, 423, 196, 'false'
  );
  

-- Surah Az-Zukhruf
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (43, 'سُورَةُ الزُّخۡرُفِ', 'Az-Zukhruf', 'Ornaments of gold', 'Meccan', 89);

  -- Ayah 1 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4326,
    'حمۤ',
    'حم',
    'ح<rule class=madda_necessary>مٓ</rule> ١',
    1, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 2 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4327,
    'وَٱلۡكِتَـٰبِ ٱلۡمُبِینِ',
    'والكتاب المبين',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نِ ٢',
    2, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 3 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4328,
    'إِنَّا جَعَلۡنَـٰهُ قُرۡءَ ٰ⁠ نًا عَرَبِیࣰّا لَّعَلَّكُمۡ تَعۡقِلُونَ',
    'انا جعلناه قرانا عربيا لعلكم تعقلون',
    'إِ<rule class=ghunnah>نّ</rule>َا جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ قُرۡء<rule class=madda_normal>ٰ</rule>نًا عَرَبِي<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّكُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 4 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4329,
    'وَإِنَّهُۥ فِیۤ أُمِّ ٱلۡكِتَـٰبِ لَدَیۡنَا لَعَلِیٌّ حَكِیمٌ',
    'وانه في ام الكتاب لدينا لعلي حكيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُ<rule class=ghunnah>مّ</rule>ِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَدَيۡنَا لَعَلِىٌّ حَك<rule class=madda_permissible>ِي</rule>مٌ ٤',
    4, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 5 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4330,
    'أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمࣰا مُّسۡرِفِینَ',
    'افنضرب عنكم الذكر صفحا ان كنتم قوما مسرفين',
    'أَفَنَضۡرِبُ عَ<rule class=ikhafa>نك</rule>ُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَ صَفۡحًا أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡرِف<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 6 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4331,
    'وَكَمۡ أَرۡسَلۡنَا مِن نَّبِیࣲّ فِی ٱلۡأَوَّلِینَ',
    'وكم ارسلنا من نبي في الاولين',
    'وَكَمۡ أَرۡسَلۡنَا م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّبِ<rule class=ikhafa>ىٍّ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 7 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4332,
    'وَمَا یَأۡتِیهِم مِّن نَّبِیٍّ إِلَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'وما ياتيهم من نبي الا كانوا به يستهزئون',
    'وَمَا يَأۡتِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّبِىٍّ إِلَّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 8 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4333,
    'فَأَهۡلَكۡنَاۤ أَشَدَّ مِنۡهُم بَطۡشࣰا وَمَضَىٰ مَثَلُ ٱلۡأَوَّلِینَ',
    'فاهلكنا اشد منهم بطشا ومضى مثل الاولين',
    'فَأَهۡلَكۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَشَدَّ مِنۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َ<rule class=qalaqah>طۡ</rule><rule class=idgham_ghunnah>شًا</rule> <rule class=idgham_ghunnah>و</rule>َمَضَىٰ مَثَلُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 9 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4334,
    'وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ لَیَقُولُنَّ خَلَقَهُنَّ ٱلۡعَزِیزُ ٱلۡعَلِیمُ',
    'ولئن سالتهم من خلق السماوات والارض ليقولن خلقهن العزيز العليم',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َأَلۡتَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ لَيَقُولُ<rule class=ghunnah>نّ</rule>َ خَلَقَهُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٩',
    9, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 10 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4335,
    'ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدࣰا وَجَعَلَ لَكُمۡ فِیهَا سُبُلࣰا لَّعَلَّكُمۡ تَهۡتَدُونَ',
    'الذي جعل لكم الارض مهدا وجعل لكم فيها سبلا لعلكم تهتدون',
    'ٱلَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ مَهۡ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ لَكُمۡ فِيهَا سُبُل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّكُمۡ تَهۡتَد<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 25, 6, 489, 424, 196, 'false'
  );
  
  -- Ayah 11 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4336,
    'وَٱلَّذِی نَزَّلَ مِنَ ٱلسَّمَاۤءِ مَاۤءَۢ بِقَدَرࣲ فَأَنشَرۡنَا بِهِۦ بَلۡدَةࣰ مَّیۡتࣰاۚ كَذَ ٰ⁠لِكَ تُخۡرَجُونَ',
    'والذي نزل من السماء ماء بقدر فانشرنا به بلدة ميتا كذلك تخرجون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِى نَزَّلَ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءَۢ</rule> <rule class=iqlab>ب</rule>ِقَدَ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=ikhafa>نش</rule>َرۡنَا بِه<rule class=madda_normal>ِۦ</rule> بَلۡدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>َّيۡ<rule class=ikhafa>تًا‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ تُخۡرَج<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 25, 6, 490, 424, 196, 'false'
  );
  
  -- Ayah 12 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4337,
    'وَٱلَّذِی خَلَقَ ٱلۡأَزۡوَ ٰ⁠جَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَـٰمِ مَا تَرۡكَبُونَ',
    'والذي خلق الازواج كلها وجعل لكم من الفلك والانعام ما تركبون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule>لۡأَزۡو<rule class=madda_normal>ٰ</rule>جَ كُلَّهَا وَجَعَلَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مِ مَا تَرۡكَب<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 25, 6, 490, 424, 196, 'false'
  );
  
  -- Ayah 13 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4338,
    'لِتَسۡتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُوا۟ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَیۡتُمۡ عَلَیۡهِ وَتَقُولُوا۟ سُبۡحَـٰنَ ٱلَّذِی سَخَّرَ لَنَا هَـٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِینَ',
    'لتستووا على ظهوره ثم تذكروا نعمة ربكم اذا استويتم عليه وتقولوا سبحان الذي سخر لنا هذا وما كنا له مقرنين',
    'لِتَسۡتَوُ<rule class=madda_normal>ۥ</rule>اۡ عَلَىٰ ظُهُورِه<rule class=madda_normal>ِۦ</rule> ثُ<rule class=ghunnah>مّ</rule>َ تَذۡكُرُو<rule class=slnt>اۡ</rule> نِعۡمَةَ رَبِّكُمۡ إِذَا <rule class=ham_wasl>ٱ</rule>سۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُو<rule class=slnt>اۡ</rule> سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>لَّذِى سَخَّرَ لَنَا هَ<rule class=madda_normal>ـٰ</rule>ذَا وَمَا كُ<rule class=ghunnah>نّ</rule>َا لَهُ<rule class=madda_normal>ۥ</rule> مُ<rule class=qalaqah>قۡ</rule>رِن<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 25, 6, 490, 424, 196, 'false'
  );
  
  -- Ayah 14 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4339,
    'وَإِنَّاۤ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ',
    'وانا الى ربنا لمنقلبون',
    'وَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ رَبِّنَا لَمُ<rule class=ikhafa>نق</rule>َلِب<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 25, 6, 490, 424, 196, 'false'
  );
  
  -- Ayah 15 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4340,
    'وَجَعَلُوا۟ لَهُۥ مِنۡ عِبَادِهِۦ جُزۡءًاۚ إِنَّ ٱلۡإِنسَـٰنَ لَكَفُورࣱ مُّبِینٌ',
    'وجعلوا له من عباده جزءا ان الانسان لكفور مبين',
    'وَجَعَلُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> مِنۡ عِبَادِه<rule class=madda_normal>ِۦ</rule> جُزۡءًا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ لَكَفُو<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٥',
    15, 25, 6, 490, 424, 196, 'false'
  );
  
  -- Ayah 16 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4341,
    'أَمِ ٱتَّخَذَ مِمَّا یَخۡلُقُ بَنَاتࣲ وَأَصۡفَىٰكُم بِٱلۡبَنِینَ',
    'ام اتخذ مما يخلق بنات واصفاكم بالبنين',
    'أَمِ <rule class=ham_wasl>ٱ</rule>تَّخَذَ مِ<rule class=ghunnah>مّ</rule>َا يَخۡلُقُ بَنَا<rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَصۡفَ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَن<rule class=madda_permissible>ِي</rule>نَ ١٦',
    16, 25, 6, 490, 425, 196, 'false'
  );
  
  -- Ayah 17 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4342,
    'وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحۡمَـٰنِ مَثَلࣰا ظَلَّ وَجۡهُهُۥ مُسۡوَدࣰّا وَهُوَ كَظِیمٌ',
    'واذا بشر احدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم',
    'وَإِذَا بُشِّرَ أَحَدُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا ضَرَبَ لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ مَثَل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ظ</rule>َلَّ وَ<rule class=qalaqah>جۡ</rule>هُهُ<rule class=madda_normal>ۥ</rule> مُسۡوَد<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ كَظ<rule class=madda_permissible>ِي</rule>مٌ ١٧',
    17, 25, 6, 490, 425, 196, 'false'
  );
  
  -- Ayah 18 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4343,
    'أَوَمَن یُنَشَّؤُا۟ فِی ٱلۡحِلۡیَةِ وَهُوَ فِی ٱلۡخِصَامِ غَیۡرُ مُبِینࣲ',
    'اومن ينشا في الحلية وهو في الخصام غير مبين',
    'أَوَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُنَشَّؤُ<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡحِلۡيَةِ وَهُوَ فِى <rule class=ham_wasl>ٱ</rule>لۡخِصَامِ غَيۡرُ مُب<rule class=madda_permissible>ِي</rule>نٍ ١٨',
    18, 25, 6, 490, 425, 196, 'false'
  );
  
  -- Ayah 19 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4344,
    'وَجَعَلُوا۟ ٱلۡمَلَـٰۤىِٕكَةَ ٱلَّذِینَ هُمۡ عِبَـٰدُ ٱلرَّحۡمَـٰنِ إِنَـٰثًاۚ أَشَهِدُوا۟ خَلۡقَهُمۡۚ سَتُكۡتَبُ شَهَـٰدَتُهُمۡ وَیُسۡـَٔلُونَ',
    'وجعلوا الملائكة الذين هم عباد الرحمن اناثا اشهدوا خلقهم ستكتب شهادتهم ويسالون',
    'وَجَعَلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ عِبَ<rule class=madda_normal>ـٰ</rule>دُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ إِنَ<rule class=madda_normal>ـٰ</rule>ثًا‌ۚ أَشَهِدُو<rule class=slnt>اۡ</rule> خَلۡقَهُمۡ‌ۚ سَتُكۡتَبُ شَهَ<rule class=madda_normal>ـٰ</rule>دَتُهُمۡ وَيُسۡــَٔل<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 25, 6, 490, 425, 196, 'false'
  );
  
  -- Ayah 20 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4345,
    'وَقَالُوا۟ لَوۡ شَاۤءَ ٱلرَّحۡمَـٰنُ مَا عَبَدۡنَـٰهُمۗ مَّا لَهُم بِذَ ٰ⁠لِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا یَخۡرُصُونَ',
    'وقالوا لو شاء الرحمن ما عبدناهم ما لهم بذلك من علم ان هم الا يخرصون',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَوۡ ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ مَا عَبَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم‌ۗ</rule> <rule class=idgham_shafawi>م</rule>َّا لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذ<rule class=madda_normal>ٰ</rule>لِكَ مِنۡ عِلۡمٍ‌ۖ إِنۡ هُمۡ إِلَّا يَخۡرُص<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 25, 6, 490, 425, 196, 'false'
  );
  
  -- Ayah 21 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4346,
    'أَمۡ ءَاتَیۡنَـٰهُمۡ كِتَـٰبࣰا مِّن قَبۡلِهِۦ فَهُم بِهِۦ مُسۡتَمۡسِكُونَ',
    'ام اتيناهم كتابا من قبله فهم به مستمسكون',
    'أَمۡ ءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> فَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مُسۡتَمۡسِك<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 25, 6, 490, 425, 196, 'false'
  );
  
  -- Ayah 22 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4347,
    'بَلۡ قَالُوۤا۟ إِنَّا وَجَدۡنَاۤ ءَابَاۤءَنَا عَلَىٰۤ أُمَّةࣲ وَإِنَّا عَلَىٰۤ ءَاثَـٰرِهِم مُّهۡتَدُونَ',
    'بل قالوا انا وجدنا اباءنا على امة وانا على اثارهم مهتدون',
    'بَلۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا وَجَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاثَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 25, 6, 490, 425, 196, 'false'
  );
  
  -- Ayah 23 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4348,
    'وَكَذَ ٰ⁠لِكَ مَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ فِی قَرۡیَةࣲ مِّن نَّذِیرٍ إِلَّا قَالَ مُتۡرَفُوهَاۤ إِنَّا وَجَدۡنَاۤ ءَابَاۤءَنَا عَلَىٰۤ أُمَّةࣲ وَإِنَّا عَلَىٰۤ ءَاثَـٰرِهِم مُّقۡتَدُونَ',
    'وكذلك ما ارسلنا من قبلك في قرية من نذير الا قال مترفوها انا وجدنا اباءنا على امة وانا على اثارهم مقتدون',
    'وَكَذ<rule class=madda_normal>ٰ</rule>لِكَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ فِى قَرۡيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّذِيرٍ إِلَّا قَالَ مُتۡرَفُوه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا وَجَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاثَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَد<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 25, 6, 491, 425, 196, 'false'
  );
  
  -- Ayah 24 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4349,
    '۞ قَـٰلَ أَوَلَوۡ جِئۡتُكُم بِأَهۡدَىٰ مِمَّا وَجَدتُّمۡ عَلَیۡهِ ءَابَاۤءَكُمۡۖ قَالُوۤا۟ إِنَّا بِمَاۤ أُرۡسِلۡتُم بِهِۦ كَـٰفِرُونَ',
    'قال اولو جئتكم باهدى مما وجدتم عليه اباءكم قالوا انا بما ارسلتم به كافرون',
    '۞قَ<rule class=madda_normal>ـٰ</rule>لَ أَوَلَوۡ جِئۡتُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَهۡدَىٰ مِ<rule class=ghunnah>مّ</rule>َا وَجَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ عَلَيۡهِ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ‌ۖ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا بِم<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 25, 6, 491, 425, 197, 'false'
  );
  
  -- Ayah 25 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4350,
    'فَٱنتَقَمۡنَا مِنۡهُمۡۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُكَذِّبِینَ',
    'فانتقمنا منهم فانظر كيف كان عاقبة المكذبين',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َقَمۡنَا مِنۡهُمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرۡ كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لۡمُكَذِّب<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 25, 6, 491, 425, 197, 'false'
  );
  
  -- Ayah 26 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4351,
    'وَإِذۡ قَالَ إِبۡرَ ٰ⁠هِیمُ لِأَبِیهِ وَقَوۡمِهِۦۤ إِنَّنِی بَرَاۤءࣱ مِّمَّا تَعۡبُدُونَ',
    'واذ قال ابراهيم لابيه وقومه انني براء مما تعبدون',
    'وَإِذۡ قَالَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمُ لِأَبِيهِ وَقَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ghunnah>نّ</rule>َنِى بَر<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 25, 6, 491, 426, 197, 'false'
  );
  
  -- Ayah 27 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4352,
    'إِلَّا ٱلَّذِی فَطَرَنِی فَإِنَّهُۥ سَیَهۡدِینِ',
    'الا الذي فطرني فانه سيهدين',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِى فَطَرَنِى فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> سَيَهۡد<rule class=madda_permissible>ِي</rule>نِ ٢٧',
    27, 25, 6, 491, 426, 197, 'false'
  );
  
  -- Ayah 28 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4353,
    'وَجَعَلَهَا كَلِمَةَۢ بَاقِیَةࣰ فِی عَقِبِهِۦ لَعَلَّهُمۡ یَرۡجِعُونَ',
    'وجعلها كلمة باقية في عقبه لعلهم يرجعون',
    'وَجَعَلَهَا كَلِمَ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>َاقِيَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى عَقِبِه<rule class=madda_normal>ِۦ</rule> لَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 25, 6, 491, 426, 197, 'false'
  );
  
  -- Ayah 29 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4354,
    'بَلۡ مَتَّعۡتُ هَـٰۤؤُلَاۤءِ وَءَابَاۤءَهُمۡ حَتَّىٰ جَاۤءَهُمُ ٱلۡحَقُّ وَرَسُولࣱ مُّبِینࣱ',
    'بل متعت هؤلاء واباءهم حتى جاءهم الحق ورسول مبين',
    'بَلۡ مَتَّعۡتُ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ حَتَّىٰ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ وَرَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٢٩',
    29, 25, 6, 491, 426, 197, 'false'
  );
  
  -- Ayah 30 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4355,
    'وَلَمَّا جَاۤءَهُمُ ٱلۡحَقُّ قَالُوا۟ هَـٰذَا سِحۡرࣱ وَإِنَّا بِهِۦ كَـٰفِرُونَ',
    'ولما جاءهم الحق قالوا هذا سحر وانا به كافرون',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ قَالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_normal>ِۦ</rule> كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 25, 6, 491, 426, 197, 'false'
  );
  
  -- Ayah 31 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4356,
    'وَقَالُوا۟ لَوۡلَا نُزِّلَ هَـٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلࣲ مِّنَ ٱلۡقَرۡیَتَیۡنِ عَظِیمٍ',
    'وقالوا لولا نزل هذا القران على رجل من القريتين عظيم',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَوۡلَا نُزِّلَ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانُ عَلَىٰ رَجُ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقَرۡيَتَيۡنِ عَظ<rule class=madda_permissible>ِي</rule>مٍ ٣١',
    31, 25, 6, 491, 426, 197, 'false'
  );
  
  -- Ayah 32 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4357,
    'أَهُمۡ یَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَیۡنَهُم مَّعِیشَتَهُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضࣲ دَرَجَـٰتࣲ لِّیَتَّخِذَ بَعۡضُهُم بَعۡضࣰا سُخۡرِیࣰّاۗ وَرَحۡمَتُ رَبِّكَ خَیۡرࣱ مِّمَّا یَجۡمَعُونَ',
    'اهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون',
    'أَهُمۡ يَ<rule class=qalaqah>قۡ</rule>سِمُونَ رَحۡمَتَ رَبِّكَ‌ۚ نَحۡنُ قَسَمۡنَا بَيۡنَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّعِيشَتَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡ<rule class=ikhafa>ضٍ</rule> <rule class=ikhafa>د</rule>َرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَتَّخِذَ بَعۡضُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡ<rule class=ikhafa>ضًا</rule> <rule class=ikhafa>س</rule>ُخۡرِي<rule class=idgham_ghunnah>ًّا‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَتُ رَبِّكَ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 25, 6, 491, 426, 197, 'false'
  );
  
  -- Ayah 33 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4358,
    'وَلَوۡلَاۤ أَن یَكُونَ ٱلنَّاسُ أُمَّةࣰ وَ ٰ⁠حِدَةࣰ لَّجَعَلۡنَا لِمَن یَكۡفُرُ بِٱلرَّحۡمَـٰنِ لِبُیُوتِهِمۡ سُقُفࣰا مِّن فِضَّةࣲ وَمَعَارِجَ عَلَیۡهَا یَظۡهَرُونَ',
    'ولولا ان يكون الناس امة واحدة لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضة ومعارج عليها يظهرون',
    'وَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ أُ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّجَعَلۡنَا لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكۡفُرُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ لِبُيُوتِهِمۡ سُقُ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِضَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَعَارِجَ عَلَيۡهَا يَظۡهَر<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 25, 6, 491, 426, 197, 'false'
  );
  
  -- Ayah 34 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4359,
    'وَلِبُیُوتِهِمۡ أَبۡوَ ٰ⁠بࣰا وَسُرُرًا عَلَیۡهَا یَتَّكِـُٔونَ',
    'ولبيوتهم ابوابا وسررا عليها يتكئون',
    'وَلِبُيُوتِهِمۡ أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َسُرُرًا عَلَيۡهَا يَتَّكِــٔ<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 25, 6, 492, 426, 197, 'false'
  );
  
  -- Ayah 35 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4360,
    'وَزُخۡرُفࣰاۚ وَإِن كُلُّ ذَ ٰ⁠لِكَ لَمَّا مَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَٱلۡـَٔاخِرَةُ عِندَ رَبِّكَ لِلۡمُتَّقِینَ',
    'وزخرفا وان كل ذلك لما متاع الحياة الدنيا والاخرة عند ربك للمتقين',
    'وَزُخۡرُ<rule class=idgham_ghunnah>فًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلُّ ذ<rule class=madda_normal>ٰ</rule>لِكَ لَ<rule class=ghunnah>مّ</rule>َا مَتَ<rule class=madda_normal>ـٰ</rule>عُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةُ عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ لِلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٣٥',
    35, 25, 6, 492, 426, 197, 'false'
  );
  
  -- Ayah 36 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4361,
    'وَمَن یَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَـٰنِ نُقَیِّضۡ لَهُۥ شَیۡطَـٰنࣰا فَهُوَ لَهُۥ قَرِینࣱ',
    'ومن يعش عن ذكر الرحمن نقيض له شيطانا فهو له قرين',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡشُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ نُقَيِّضۡ لَهُ<rule class=madda_normal>ۥ</rule> شَيۡطَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َهُوَ لَهُ<rule class=madda_normal>ۥ</rule> قَر<rule class=madda_permissible>ِي</rule>نٌ ٣٦',
    36, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 37 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4362,
    'وَإِنَّهُمۡ لَیَصُدُّونَهُمۡ عَنِ ٱلسَّبِیلِ وَیَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ',
    'وانهم ليصدونهم عن السبيل ويحسبون انهم مهتدون',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ لَيَصُدُّونَهُمۡ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ وَيَحۡسَبُونَ أَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 38 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4363,
    'حَتَّىٰۤ إِذَا جَاۤءَنَا قَالَ یَـٰلَیۡتَ بَیۡنِی وَبَیۡنَكَ بُعۡدَ ٱلۡمَشۡرِقَیۡنِ فَبِئۡسَ ٱلۡقَرِینُ',
    'حتى اذا جاءنا قال يا ليت بيني وبينك بعد المشرقين فبئس القرين',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا قَالَ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَ بَيۡنِى وَبَيۡنَكَ بُعۡدَ <rule class=ham_wasl>ٱ</rule>لۡمَشۡرِقَيۡنِ فَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡقَر<rule class=madda_permissible>ِي</rule>نُ ٣٨',
    38, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 39 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4364,
    'وَلَن یَنفَعَكُمُ ٱلۡیَوۡمَ إِذ ظَّلَمۡتُمۡ أَنَّكُمۡ فِی ٱلۡعَذَابِ مُشۡتَرِكُونَ',
    'ولن ينفعكم اليوم اذ ظلمتم انكم في العذاب مشتركون',
    'وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نف</rule>َعَكُمُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ إِ<rule class=idgham_mutajanisayn>ذ</rule> ظَّلَمۡتُمۡ أَ<rule class=ghunnah>نّ</rule>َكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ مُشۡتَرِك<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 40 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4365,
    'أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ أَوۡ تَهۡدِی ٱلۡعُمۡیَ وَمَن كَانَ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'افانت تسمع الصم او تهدي العمي ومن كان في ضلال مبين',
    'أَفَأَ<rule class=ikhafa>نت</rule>َ تُسۡمِعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّ<rule class=ghunnah>مّ</rule>َ أَوۡ تَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡعُمۡىَ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٤٠',
    40, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 41 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4366,
    'فَإِمَّا نَذۡهَبَنَّ بِكَ فَإِنَّا مِنۡهُم مُّنتَقِمُونَ',
    'فاما نذهبن بك فانا منهم منتقمون',
    'فَإِ<rule class=ghunnah>مّ</rule>َا نَذۡهَبَ<rule class=ghunnah>نّ</rule>َ بِكَ فَإِ<rule class=ghunnah>نّ</rule>َا مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=ikhafa>نت</rule>َقِم<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 42 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4367,
    'أَوۡ نُرِیَنَّكَ ٱلَّذِی وَعَدۡنَـٰهُمۡ فَإِنَّا عَلَیۡهِم مُّقۡتَدِرُونَ',
    'او نرينك الذي وعدناهم فانا عليهم مقتدرون',
    'أَوۡ نُرِيَ<rule class=ghunnah>نّ</rule>َكَ <rule class=ham_wasl>ٱ</rule>لَّذِى وَعَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ فَإِ<rule class=ghunnah>نّ</rule>َا عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَدِر<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 43 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4368,
    'فَٱسۡتَمۡسِكۡ بِٱلَّذِیۤ أُوحِیَ إِلَیۡكَۖ إِنَّكَ عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'فاستمسك بالذي اوحي اليك انك على صراط مستقيم',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَمۡسِكۡ بِ<rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُوحِىَ إِلَيۡكَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َكَ عَلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٤٣',
    43, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 44 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4369,
    'وَإِنَّهُۥ لَذِكۡرࣱ لَّكَ وَلِقَوۡمِكَۖ وَسَوۡفَ تُسۡـَٔلُونَ',
    'وانه لذكر لك ولقومك وسوف تسالون',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَذِكۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكَ وَلِقَوۡمِكَ‌ۖ وَسَوۡفَ تُسۡــَٔل<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 45 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4370,
    'وَسۡـَٔلۡ مَنۡ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رُّسُلِنَاۤ أَجَعَلۡنَا مِن دُونِ ٱلرَّحۡمَـٰنِ ءَالِهَةࣰ یُعۡبَدُونَ',
    'واسال من ارسلنا من قبلك من رسلنا اجعلنا من دون الرحمن الهة يعبدون',
    'وَسۡــَٔلۡ مَنۡ أَرۡسَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِكَ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّسُلِن<rule class=madda_obligatory_monfasel>َآ</rule> أَجَعَلۡنَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ ءَالِهَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>ُعۡبَد<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 25, 6, 492, 427, 197, 'false'
  );
  
  -- Ayah 46 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4371,
    'وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔایَـٰتِنَاۤ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ فَقَالَ إِنِّی رَسُولُ رَبِّ ٱلۡعَـٰلَمِینَ',
    'ولقد ارسلنا موسى باياتنا الى فرعون وملئه فقال اني رسول رب العالمين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا مُوسَىٰ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ فِرۡعَوۡنَ وَمَلَإِ<rule class=slnt>يۡ</rule>ه<rule class=madda_normal>ِۦ</rule> فَقَالَ إِ<rule class=ghunnah>نّ</rule>ِى رَسُولُ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 25, 6, 492, 428, 197, 'false'
  );
  
  -- Ayah 47 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4372,
    'فَلَمَّا جَاۤءَهُم بِـَٔایَـٰتِنَاۤ إِذَا هُم مِّنۡهَا یَضۡحَكُونَ',
    'فلما جاءهم باياتنا اذا هم منها يضحكون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهَا يَضۡحَك<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 25, 6, 492, 428, 197, 'false'
  );
  
  -- Ayah 48 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4373,
    'وَمَا نُرِیهِم مِّنۡ ءَایَةٍ إِلَّا هِیَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَـٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ یَرۡجِعُونَ',
    'وما نريهم من اية الا هي اكبر من اختها واخذناهم بالعذاب لعلهم يرجعون',
    'وَمَا نُرِيه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ ءَايَةٍ إِلَّا هِىَ أَكۡبَرُ مِنۡ أُخۡتِهَا‌ۖ وَأَخَذۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡعَذَابِ لَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 49 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4374,
    'وَقَالُوا۟ یَـٰۤأَیُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ',
    'وقالوا يا ايه الساحر ادع لنا ربك بما عهد عندك اننا لمهتدون',
    'وَقَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاحِرُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>عُ لَنَا رَبَّكَ بِمَا عَهِدَ عِ<rule class=ikhafa>ند</rule>َكَ إِ<rule class=ghunnah>نّ</rule>َنَا لَمُهۡتَد<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 50 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4375,
    'فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِذَا هُمۡ یَنكُثُونَ',
    'فلما كشفنا عنهم العذاب اذا هم ينكثون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا كَشَفۡنَا عَنۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ إِذَا هُمۡ يَ<rule class=ikhafa>نك</rule>ُث<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 51 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4376,
    'وَنَادَىٰ فِرۡعَوۡنُ فِی قَوۡمِهِۦ قَالَ یَـٰقَوۡمِ أَلَیۡسَ لِی مُلۡكُ مِصۡرَ وَهَـٰذِهِ ٱلۡأَنۡهَـٰرُ تَجۡرِی مِن تَحۡتِیۤۚ أَفَلَا تُبۡصِرُونَ',
    'ونادى فرعون في قومه قال يا قوم اليس لي ملك مصر وهذه الانهار تجري من تحتي افلا تبصرون',
    'وَنَادَىٰ فِرۡعَوۡنُ فِى قَوۡمِه<rule class=madda_normal>ِۦ</rule> قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ أَلَيۡسَ لِى مُلۡكُ مِصۡرَ وَهَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ تَ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡت<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> أَفَلَا تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٥١',
    51, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 52 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4377,
    'أَمۡ أَنَا۠ خَیۡرࣱ مِّنۡ هَـٰذَا ٱلَّذِی هُوَ مَهِینࣱ وَلَا یَكَادُ یُبِینُ',
    'ام انا خير من هذا الذي هو مهين ولا يكاد يبين',
    'أَمۡ أَنَاۡ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى هُوَ مَهِي<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَكَادُ يُب<rule class=madda_permissible>ِي</rule>نُ ٥٢',
    52, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 53 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4378,
    'فَلَوۡلَاۤ أُلۡقِیَ عَلَیۡهِ أَسۡوِرَةࣱ مِّن ذَهَبٍ أَوۡ جَاۤءَ مَعَهُ ٱلۡمَلَـٰۤىِٕكَةُ مُقۡتَرِنِینَ',
    'فلولا القي عليه اسورة من ذهب او جاء معه الملائكة مقترنين',
    'فَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أُلۡقِىَ عَلَيۡهِ أَسۡوِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َهَبٍ أَوۡ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَعَهُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ مُ<rule class=qalaqah>قۡ</rule>تَرِن<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 54 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4379,
    'فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ',
    'فاستخف قومه فاطاعوه انهم كانوا قوما فاسقين',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡتَخَفَّ قَوۡمَهُ<rule class=madda_normal>ۥ</rule> فَأَطَاعُوهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٥٤',
    54, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 55 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4380,
    'فَلَمَّاۤ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَـٰهُمۡ أَجۡمَعِینَ',
    'فلما اسفونا انتقمنا منهم فاغرقناهم اجمعين',
    'فَلَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَاسَفُونَا <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َقَمۡنَا مِنۡهُمۡ فَأَغۡرَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 56 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4381,
    'فَجَعَلۡنَـٰهُمۡ سَلَفࣰا وَمَثَلࣰا لِّلۡـَٔاخِرِینَ',
    'فجعلناهم سلفا ومثلا للاخرين',
    'فَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ سَلَ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>و</rule>َمَثَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡأَخِر<rule class=madda_permissible>ِي</rule>نَ ٥٦',
    56, 25, 6, 493, 428, 197, 'false'
  );
  
  -- Ayah 57 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4382,
    '۞ وَلَمَّا ضُرِبَ ٱبۡنُ مَرۡیَمَ مَثَلًا إِذَا قَوۡمُكَ مِنۡهُ یَصِدُّونَ',
    'ولما ضرب ابن مريم مثلا اذا قومك منه يصدون',
    '۞وَلَ<rule class=ghunnah>مّ</rule>َا ضُرِبَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ مَثَلاً إِذَا قَوۡمُكَ مِنۡهُ يَصِدّ<rule class=madda_permissible>ُو</rule>نَ ٥٧',
    57, 25, 6, 493, 429, 198, 'false'
  );
  
  -- Ayah 58 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4383,
    'وَقَالُوۤا۟ ءَأَ ٰ⁠لِهَتُنَا خَیۡرٌ أَمۡ هُوَۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢاۚ بَلۡ هُمۡ قَوۡمٌ خَصِمُونَ',
    'وقالوا االهتنا خير ام هو ما ضربوه لك الا جدلا بل هم قوم خصمون',
    'وَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَأ<rule class=madda_normal>ٰ</rule>لِهَتُنَا خَيۡرٌ أَمۡ هُوَ‌ۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَل<rule class=iqlab>اَۢ‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ هُمۡ قَوۡمٌ خَصِم<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 25, 6, 493, 429, 198, 'false'
  );
  
  -- Ayah 59 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4384,
    'إِنۡ هُوَ إِلَّا عَبۡدٌ أَنۡعَمۡنَا عَلَیۡهِ وَجَعَلۡنَـٰهُ مَثَلࣰا لِّبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ',
    'ان هو الا عبد انعمنا عليه وجعلناه مثلا لبني اسرائيل',
    'إِنۡ هُوَ إِلَّا عَ<rule class=qalaqah>بۡ</rule>دٌ أَنۡعَمۡنَا عَلَيۡهِ وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ مَثَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّبَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓء<rule class=madda_permissible>ِي</rule>لَ ٥٩',
    59, 25, 6, 493, 429, 198, 'false'
  );
  
  -- Ayah 60 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4385,
    'وَلَوۡ نَشَاۤءُ لَجَعَلۡنَا مِنكُم مَّلَـٰۤىِٕكَةࣰ فِی ٱلۡأَرۡضِ یَخۡلُفُونَ',
    'ولو نشاء لجعلنا منكم ملائكة في الارض يخلفون',
    'وَلَوۡ نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لَجَعَلۡنَا مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يَخۡلُف<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 25, 6, 493, 429, 198, 'false'
  );
  
  -- Ayah 61 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4386,
    'وَإِنَّهُۥ لَعِلۡمࣱ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَـٰذَا صِرَ ٰ⁠طࣱ مُّسۡتَقِیمࣱ',
    'وانه لعلم للساعة فلا تمترن بها واتبعون هذا صراط مستقيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَعِلۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلسَّاعَةِ فَلَا تَمۡتَرُ<rule class=ghunnah>نّ</rule>َ بِهَا وَ<rule class=ham_wasl>ٱ</rule>تَّبِعُونِ‌ۚ هَ<rule class=madda_normal>ـٰ</rule>ذَا صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٌ ٦١',
    61, 25, 6, 494, 429, 198, 'false'
  );
  
  -- Ayah 62 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4387,
    'وَلَا یَصُدَّنَّكُمُ ٱلشَّیۡطَـٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینࣱ',
    'ولا يصدنكم الشيطان انه لكم عدو مبين',
    'وَلَا يَصُدَّ<rule class=ghunnah>نّ</rule>َكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَكُمۡ عَدُ<rule class=idgham_ghunnah>وٌّ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٦٢',
    62, 25, 6, 494, 429, 198, 'false'
  );
  
  -- Ayah 63 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4388,
    'وَلَمَّا جَاۤءَ عِیسَىٰ بِٱلۡبَیِّنَـٰتِ قَالَ قَدۡ جِئۡتُكُم بِٱلۡحِكۡمَةِ وَلِأُبَیِّنَ لَكُم بَعۡضَ ٱلَّذِی تَخۡتَلِفُونَ فِیهِۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ',
    'ولما جاء عيسى بالبينات قال قد جئتكم بالحكمة ولابين لكم بعض الذي تختلفون فيه فاتقوا الله واطيعون',
    'وَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ عِيسَىٰ بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ قَالَ قَ<rule class=qalaqah>دۡ</rule> جِئۡتُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةِ وَلِأُبَيِّنَ لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضَ <rule class=ham_wasl>ٱ</rule>لَّذِى تَخۡتَلِفُونَ فِيهِ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطِيع<rule class=madda_permissible>ُو</rule>نِ ٦٣',
    63, 25, 6, 494, 429, 198, 'false'
  );
  
  -- Ayah 64 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4389,
    'إِنَّ ٱللَّهَ هُوَ رَبِّی وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَـٰذَا صِرَ ٰ⁠طࣱ مُّسۡتَقِیمࣱ',
    'ان الله هو ربي وربكم فاعبدوه هذا صراط مستقيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ رَبِّى وَرَبُّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>عۡبُدُوهُ‌ۚ هَ<rule class=madda_normal>ـٰ</rule>ذَا صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٌ ٦٤',
    64, 25, 6, 494, 429, 198, 'false'
  );
  
  -- Ayah 65 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4390,
    'فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَیۡنِهِمۡۖ فَوَیۡلࣱ لِّلَّذِینَ ظَلَمُوا۟ مِنۡ عَذَابِ یَوۡمٍ أَلِیمٍ',
    'فاختلف الاحزاب من بينهم فويل للذين ظلموا من عذاب يوم اليم',
    'فَ<rule class=ham_wasl>ٱ</rule>خۡتَلَفَ <rule class=ham_wasl>ٱ</rule>لۡأَحۡزَابُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِهِمۡ‌ۖ فَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> مِنۡ عَذَابِ يَوۡمٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٦٥',
    65, 25, 6, 494, 429, 198, 'false'
  );
  
  -- Ayah 66 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4391,
    'هَلۡ یَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِیَهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ',
    'هل ينظرون الا الساعة ان تاتيهم بغتة وهم لا يشعرون',
    'هَلۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡتِيَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َغۡتَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َهُمۡ لَا يَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٦٦',
    66, 25, 6, 494, 429, 198, 'false'
  );
  
  -- Ayah 67 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4392,
    'ٱلۡأَخِلَّاۤءُ یَوۡمَىِٕذِۭ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِینَ',
    'الاخلاء يومئذ بعضهم لبعض عدو الا المتقين',
    'ٱلۡأَخِلّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ يَوۡمَئِ<rule class=iqlab>ذِۭ</rule> <rule class=iqlab>ب</rule>َعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٦٧',
    67, 25, 6, 494, 429, 198, 'false'
  );
  
  -- Ayah 68 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4393,
    'یَـٰعِبَادِ لَا خَوۡفٌ عَلَیۡكُمُ ٱلۡیَوۡمَ وَلَاۤ أَنتُمۡ تَحۡزَنُونَ',
    'يا عباد لا خوف عليكم اليوم ولا انتم تحزنون',
    'يَ<rule class=madda_normal>ـٰ</rule>عِبَادِ لَا خَوۡفٌ عَلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ تَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ٦٨',
    68, 25, 6, 494, 430, 198, 'false'
  );
  
  -- Ayah 69 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4394,
    'ٱلَّذِینَ ءَامَنُوا۟ بِـَٔایَـٰتِنَا وَكَانُوا۟ مُسۡلِمِینَ',
    'الذين امنوا باياتنا وكانوا مسلمين',
    'ٱلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا وَكَانُو<rule class=slnt>اۡ</rule> مُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٦٩',
    69, 25, 6, 494, 430, 198, 'false'
  );
  
  -- Ayah 70 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4395,
    'ٱدۡخُلُوا۟ ٱلۡجَنَّةَ أَنتُمۡ وَأَزۡوَ ٰ⁠جُكُمۡ تُحۡبَرُونَ',
    'ادخلوا الجنة انتم وازواجكم تحبرون',
    'ٱ<rule class=qalaqah>دۡ</rule>خُلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ أَ<rule class=ikhafa>نت</rule>ُمۡ وَأَزۡو<rule class=madda_normal>ٰ</rule>جُكُمۡ تُحۡبَر<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 25, 6, 494, 430, 198, 'false'
  );
  
  -- Ayah 71 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4396,
    'یُطَافُ عَلَیۡهِم بِصِحَافࣲ مِّن ذَهَبࣲ وَأَكۡوَابࣲۖ وَفِیهَا مَا تَشۡتَهِیهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡیُنُۖ وَأَنتُمۡ فِیهَا خَـٰلِدُونَ',
    'يطاف عليهم بصحاف من ذهب واكواب وفيها ما تشتهيه الانفس وتلذ الاعين وانتم فيها خالدون',
    'يُطَافُ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِصِحَا<rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َهَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَكۡوَا<rule class=idgham_ghunnah>بٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َفِيهَا مَا تَشۡتَهِيهِ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>ُسُ وَتَلَذُّ <rule class=ham_wasl>ٱ</rule>لۡأَعۡيُنُ‌ۖ وَأَ<rule class=ikhafa>نت</rule>ُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٧١',
    71, 25, 6, 494, 430, 198, 'false'
  );
  
  -- Ayah 72 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4397,
    'وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِیۤ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'وتلك الجنة التي اورثتموها بما كنتم تعملون',
    'وَتِلۡكَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةُ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُورِثۡتُمُوهَا بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٧٢',
    72, 25, 6, 494, 430, 198, 'false'
  );
  
  -- Ayah 73 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4398,
    'لَكُمۡ فِیهَا فَـٰكِهَةࣱ كَثِیرَةࣱ مِّنۡهَا تَأۡكُلُونَ',
    'لكم فيها فاكهة كثيرة منها تاكلون',
    'لَكُمۡ فِيهَا فَ<rule class=madda_normal>ـٰ</rule>كِهَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ك</rule>َثِيرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهَا تَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ٧٣',
    73, 25, 6, 494, 430, 198, 'false'
  );
  
  -- Ayah 74 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4399,
    'إِنَّ ٱلۡمُجۡرِمِینَ فِی عَذَابِ جَهَنَّمَ خَـٰلِدُونَ',
    'ان المجرمين في عذاب جهنم خالدون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ فِى عَذَابِ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ٧٤',
    74, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 75 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4400,
    'لَا یُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِیهِ مُبۡلِسُونَ',
    'لا يفتر عنهم وهم فيه مبلسون',
    'لَا يُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِيهِ مُ<rule class=qalaqah>بۡ</rule>لِس<rule class=madda_permissible>ُو</rule>نَ ٧٥',
    75, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 76 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4401,
    'وَمَا ظَلَمۡنَـٰهُمۡ وَلَـٰكِن كَانُوا۟ هُمُ ٱلظَّـٰلِمِینَ',
    'وما ظلمناهم ولكن كانوا هم الظالمين',
    'وَمَا ظَلَمۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٧٦',
    76, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 77 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4402,
    'وَنَادَوۡا۟ یَـٰمَـٰلِكُ لِیَقۡضِ عَلَیۡنَا رَبُّكَۖ قَالَ إِنَّكُم مَّـٰكِثُونَ',
    'ونادوا يا مالك ليقض علينا ربك قال انكم ماكثون',
    'وَنَادَوۡ<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>مَ<rule class=madda_normal>ـٰ</rule>لِكُ لِيَ<rule class=qalaqah>قۡ</rule>ضِ عَلَيۡنَا رَبُّكَ‌ۖ قَالَ إِ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=madda_normal>ـٰ</rule>كِث<rule class=madda_permissible>ُو</rule>نَ ٧٧',
    77, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 78 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4403,
    'لَقَدۡ جِئۡنَـٰكُم بِٱلۡحَقِّ وَلَـٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَـٰرِهُونَ',
    'لقد جئناكم بالحق ولكن اكثركم للحق كارهون',
    'لَقَ<rule class=qalaqah>دۡ</rule> جِئۡنَ<rule class=madda_normal>ـٰ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَكُمۡ لِلۡحَقِّ كَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=madda_permissible>ُو</rule>نَ ٧٨',
    78, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 79 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4404,
    'أَمۡ أَبۡرَمُوۤا۟ أَمۡرࣰا فَإِنَّا مُبۡرِمُونَ',
    'ام ابرموا امرا فانا مبرمون',
    'أَمۡ أَ<rule class=qalaqah>بۡ</rule>رَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َا مُ<rule class=qalaqah>بۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 80 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4405,
    'أَمۡ یَحۡسَبُونَ أَنَّا لَا نَسۡمَعُ سِرَّهُمۡ وَنَجۡوَىٰهُمۚ بَلَىٰ وَرُسُلُنَا لَدَیۡهِمۡ یَكۡتُبُونَ',
    'ام يحسبون انا لا نسمع سرهم ونجواهم بلى ورسلنا لديهم يكتبون',
    'أَمۡ يَحۡسَبُونَ أَ<rule class=ghunnah>نّ</rule>َا لَا نَسۡمَعُ سِرَّهُمۡ وَنَ<rule class=qalaqah>جۡ</rule>وَ<rule class=madda_normal>ٮٰ</rule>ه<rule class=ikhafa_shafawi>ُم‌ۚ</rule> <rule class=ikhafa_shafawi>ب</rule>َلَىٰ وَرُسُلُنَا لَدَيۡهِمۡ يَكۡتُب<rule class=madda_permissible>ُو</rule>نَ ٨٠',
    80, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 81 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4406,
    'قُلۡ إِن كَانَ لِلرَّحۡمَـٰنِ وَلَدࣱ فَأَنَا۠ أَوَّلُ ٱلۡعَـٰبِدِینَ',
    'قل ان كان للرحمن ولد فانا اول العابدين',
    'قُلۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ لِلرَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ وَلَ<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َأَنَاۡ أَوَّلُ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>بِد<rule class=madda_permissible>ِي</rule>نَ ٨١',
    81, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 82 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4407,
    'سُبۡحَـٰنَ رَبِّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ رَبِّ ٱلۡعَرۡشِ عَمَّا یَصِفُونَ',
    'سبحان رب السماوات والارض رب العرش عما يصفون',
    'سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ عَ<rule class=ghunnah>مّ</rule>َا يَصِف<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 83 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4408,
    'فَذَرۡهُمۡ یَخُوضُوا۟ وَیَلۡعَبُوا۟ حَتَّىٰ یُلَـٰقُوا۟ یَوۡمَهُمُ ٱلَّذِی یُوعَدُونَ',
    'فذرهم يخوضوا ويلعبوا حتى يلاقوا يومهم الذي يوعدون',
    'فَذَرۡهُمۡ يَخُوضُو<rule class=slnt>اۡ</rule> وَيَلۡعَبُو<rule class=slnt>اۡ</rule> حَتَّىٰ يُلَ<rule class=madda_normal>ـٰ</rule>قُو<rule class=slnt>اۡ</rule> يَوۡمَهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى يُوعَد<rule class=madda_permissible>ُو</rule>نَ ٨٣',
    83, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 84 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4409,
    'وَهُوَ ٱلَّذِی فِی ٱلسَّمَاۤءِ إِلَـٰهࣱ وَفِی ٱلۡأَرۡضِ إِلَـٰهࣱۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡعَلِیمُ',
    'وهو الذي في السماء اله وفي الارض اله وهو الحكيم العليم',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ</rule> <rule class=idgham_ghunnah>و</rule>َفِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>هٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule>لۡحَكِيمُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٨٤',
    84, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 85 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4410,
    'وَتَبَارَكَ ٱلَّذِی لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا وَعِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَإِلَیۡهِ تُرۡجَعُونَ',
    'وتبارك الذي له ملك السماوات والارض وما بينهما وعنده علم الساعة واليه ترجعون',
    'وَتَبَارَكَ <rule class=ham_wasl>ٱ</rule>لَّذِى لَهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا وَعِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> عِلۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةِ وَإِلَيۡهِ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ٨٥',
    85, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 86 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4411,
    'وَلَا یَمۡلِكُ ٱلَّذِینَ یَدۡعُونَ مِن دُونِهِ ٱلشَّفَـٰعَةَ إِلَّا مَن شَهِدَ بِٱلۡحَقِّ وَهُمۡ یَعۡلَمُونَ',
    'ولا يملك الذين يدعون من دونه الشفاعة الا من شهد بالحق وهم يعلمون',
    'وَلَا يَمۡلِكُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّفَ<rule class=madda_normal>ـٰ</rule>عَةَ إِلَّا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َهِدَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَهُمۡ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨٦',
    86, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 87 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4412,
    'وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَهُمۡ لَیَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ یُؤۡفَكُونَ',
    'ولئن سالتهم من خلقهم ليقولن الله فانى يؤفكون',
    'وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َأَلۡتَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ خَلَقَهُمۡ لَيَقُولُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ فَأَ<rule class=ghunnah>نّ</rule>َىٰ يُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٨٧',
    87, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 88 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4413,
    'وَقِیلِهِۦ یَـٰرَبِّ إِنَّ هَـٰۤؤُلَاۤءِ قَوۡمࣱ لَّا یُؤۡمِنُونَ',
    'وقيله يا رب ان هؤلاء قوم لا يؤمنون',
    'وَقِيلِه<rule class=madda_normal>ِۦ</rule> يَ<rule class=madda_normal>ـٰ</rule>رَبِّ إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ قَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٨٨',
    88, 25, 6, 495, 430, 198, 'false'
  );
  
  -- Ayah 89 Surah Az-Zukhruf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    43,
    4414,
    'فَٱصۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَـٰمࣱۚ فَسَوۡفَ یَعۡلَمُونَ',
    'فاصفح عنهم وقل سلام فسوف يعلمون',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َسَوۡفَ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨٩',
    89, 25, 6, 495, 430, 198, 'false'
  );
  

-- Surah Ad-Dukhaan
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (44, 'سُورَةُ الدُّخَانِ', 'Ad-Dukhaan', 'The Smoke', 'Meccan', 59);

  -- Ayah 1 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4415,
    'حمۤ',
    'حم',
    'ح<rule class=madda_necessary>مٓ</rule> ١',
    1, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 2 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4416,
    'وَٱلۡكِتَـٰبِ ٱلۡمُبِینِ',
    'والكتاب المبين',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نِ ٢',
    2, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 3 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4417,
    'إِنَّاۤ أَنزَلۡنَـٰهُ فِی لَیۡلَةࣲ مُّبَـٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِینَ',
    'انا انزلناه في ليلة مباركة انا كنا منذرين',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ فِى لَيۡلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّبَ<rule class=madda_normal>ـٰ</rule>رَكَةٍ‌ۚ إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا مُ<rule class=ikhafa>نذ</rule>ِر<rule class=madda_permissible>ِي</rule>نَ ٣',
    3, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 4 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4418,
    'فِیهَا یُفۡرَقُ كُلُّ أَمۡرٍ حَكِیمٍ',
    'فيها يفرق كل امر حكيم',
    'فِيهَا يُفۡرَقُ كُلُّ أَمۡرٍ حَك<rule class=madda_permissible>ِي</rule>مٍ ٤',
    4, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 5 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4419,
    'أَمۡرࣰا مِّنۡ عِندِنَاۤۚ إِنَّا كُنَّا مُرۡسِلِینَ',
    'امرا من عندنا انا كنا مرسلين',
    'أَمۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِن<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا مُرۡسِل<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 6 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4420,
    'رَحۡمَةࣰ مِّن رَّبِّكَۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ',
    'رحمة من ربك انه هو السميع العليم',
    'رَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمِيعُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٦',
    6, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 7 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4421,
    'رَبِّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۤۖ إِن كُنتُم مُّوقِنِینَ',
    'رب السماوات والارض وما بينهما ان كنتم موقنين',
    'رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُم<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّوقِن<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 8 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4422,
    'لَاۤ إِلَـٰهَ إِلَّا هُوَ یُحۡیِۦ وَیُمِیتُۖ رَبُّكُمۡ وَرَبُّ ءَابَاۤىِٕكُمُ ٱلۡأَوَّلِینَ',
    'لا اله الا هو يحيي ويميت ربكم ورب ابائكم الاولين',
    'ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُ‌ۖ رَبُّكُمۡ وَرَبُّ ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 9 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4423,
    'بَلۡ هُمۡ فِی شَكࣲّ یَلۡعَبُونَ',
    'بل هم في شك يلعبون',
    'بَلۡ هُمۡ فِى شَ<rule class=idgham_ghunnah>كٍّ</rule> <rule class=idgham_ghunnah>ي</rule>َلۡعَب<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 10 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4424,
    'فَٱرۡتَقِبۡ یَوۡمَ تَأۡتِی ٱلسَّمَاۤءُ بِدُخَانࣲ مُّبِینࣲ',
    'فارتقب يوم تاتي السماء بدخان مبين',
    'فَ<rule class=ham_wasl>ٱ</rule>رۡتَقِ<rule class=qalaqah>بۡ</rule> يَوۡمَ تَأۡتِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بِدُخَا<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١٠',
    10, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 11 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4425,
    'یَغۡشَى ٱلنَّاسَۖ هَـٰذَا عَذَابٌ أَلِیمࣱ',
    'يغشى الناس هذا عذاب اليم',
    'يَغۡشَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ‌ۖ هَ<rule class=madda_normal>ـٰ</rule>ذَا عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١١',
    11, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 12 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4426,
    'رَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ',
    'ربنا اكشف عنا العذاب انا مؤمنون',
    'رَّبَّنَا <rule class=ham_wasl>ٱ</rule>كۡشِفۡ عَ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ إِ<rule class=ghunnah>نّ</rule>َا مُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 13 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4427,
    'أَنَّىٰ لَهُمُ ٱلذِّكۡرَىٰ وَقَدۡ جَاۤءَهُمۡ رَسُولࣱ مُّبِینࣱ',
    'انى لهم الذكرى وقد جاءهم رسول مبين',
    'أَ<rule class=ghunnah>نّ</rule>َىٰ لَهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَىٰ وَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ١٣',
    13, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 14 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4428,
    'ثُمَّ تَوَلَّوۡا۟ عَنۡهُ وَقَالُوا۟ مُعَلَّمࣱ مَّجۡنُونٌ',
    'ثم تولوا عنه وقالوا معلم مجنون',
    'ثُ<rule class=ghunnah>مّ</rule>َ تَوَلَّوۡ<rule class=slnt>اۡ</rule> عَنۡهُ وَقَالُو<rule class=slnt>اۡ</rule> مُعَلَّ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نٌ ١٤',
    14, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 15 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4429,
    'إِنَّا كَاشِفُوا۟ ٱلۡعَذَابِ قَلِیلًاۚ إِنَّكُمۡ عَاۤىِٕدُونَ',
    'انا كاشفو العذاب قليلا انكم عائدون',
    'إِ<rule class=ghunnah>نّ</rule>َا كَاشِفُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ قَلِيلاً‌ۚ إِ<rule class=ghunnah>نّ</rule>َكُمۡ ع<rule class=madda_obligatory_mottasel>َا</rule>ٓئِد<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 16 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4430,
    'یَوۡمَ نَبۡطِشُ ٱلۡبَطۡشَةَ ٱلۡكُبۡرَىٰۤ إِنَّا مُنتَقِمُونَ',
    'يوم نبطش البطشة الكبرى انا منتقمون',
    'يَوۡمَ نَ<rule class=qalaqah>بۡ</rule>طِشُ <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=qalaqah>طۡ</rule>شَةَ <rule class=ham_wasl>ٱ</rule>لۡكُ<rule class=qalaqah>بۡ</rule>رَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َا مُ<rule class=ikhafa>نت</rule>َقِم<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 25, 6, 496, 431, 198, 'false'
  );
  
  -- Ayah 17 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4431,
    '۞ وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَاۤءَهُمۡ رَسُولࣱ كَرِیمٌ',
    'ولقد فتنا قبلهم قوم فرعون وجاءهم رسول كريم',
    '۞وَلَقَ<rule class=qalaqah>دۡ</rule> فَتَ<rule class=ghunnah>نّ</rule>َا قَ<rule class=qalaqah>بۡ</rule>لَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ رَسُو<rule class=ikhafa>لٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ١٧',
    17, 25, 6, 496, 431, 199, 'false'
  );
  
  -- Ayah 18 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4432,
    'أَنۡ أَدُّوۤا۟ إِلَیَّ عِبَادَ ٱللَّهِۖ إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ',
    'ان ادوا الي عباد الله اني لكم رسول امين',
    'أَنۡ أَدّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىَّ عِبَادَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>ِى لَكُمۡ رَسُولٌ أَم<rule class=madda_permissible>ِي</rule>نٌ ١٨',
    18, 25, 6, 496, 431, 199, 'false'
  );
  
  -- Ayah 19 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4433,
    'وَأَن لَّا تَعۡلُوا۟ عَلَى ٱللَّهِۖ إِنِّیۤ ءَاتِیكُم بِسُلۡطَـٰنࣲ مُّبِینࣲ',
    'وان لا تعلوا على الله اني اتيكم بسلطان مبين',
    'وَأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تَعۡلُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاتِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ١٩',
    19, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 20 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4434,
    'وَإِنِّی عُذۡتُ بِرَبِّی وَرَبِّكُمۡ أَن تَرۡجُمُونِ',
    'واني عذت بربي وربكم ان ترجمون',
    'وَإِ<rule class=ghunnah>نّ</rule>ِى عُذۡتُ بِرَبِّى وَرَبِّكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َرۡجُم<rule class=madda_permissible>ُو</rule>نِ ٢٠',
    20, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 21 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4435,
    'وَإِن لَّمۡ تُؤۡمِنُوا۟ لِی فَٱعۡتَزِلُونِ',
    'وان لم تؤمنوا لي فاعتزلون',
    'وَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تُؤۡمِنُو<rule class=slnt>اۡ</rule> لِى فَ<rule class=ham_wasl>ٱ</rule>عۡتَزِل<rule class=madda_permissible>ُو</rule>نِ ٢١',
    21, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 22 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4436,
    'فَدَعَا رَبَّهُۥۤ أَنَّ هَـٰۤؤُلَاۤءِ قَوۡمࣱ مُّجۡرِمُونَ',
    'فدعا ربه ان هؤلاء قوم مجرمون',
    'فَدَعَا رَبَّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 23 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4437,
    'فَأَسۡرِ بِعِبَادِی لَیۡلًا إِنَّكُم مُّتَّبَعُونَ',
    'فاسر بعبادي ليلا انكم متبعون',
    'فَأَسۡرِ بِعِبَادِى لَيۡلاً إِ<rule class=ghunnah>نّ</rule>َك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّتَّبَع<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 24 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4438,
    'وَٱتۡرُكِ ٱلۡبَحۡرَ رَهۡوًاۖ إِنَّهُمۡ جُندࣱ مُّغۡرَقُونَ',
    'واترك البحر رهوا انهم جند مغرقون',
    'وَ<rule class=ham_wasl>ٱ</rule>تۡرُكِ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَ رَهۡوًا‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ جُن<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّغۡرَق<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 25 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4439,
    'كَمۡ تَرَكُوا۟ مِن جَنَّـٰتࣲ وَعُیُونࣲ',
    'كم تركوا من جنات وعيون',
    'كَمۡ تَرَكُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>َ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َعُي<rule class=madda_permissible>ُو</rule>نٍ ٢٥',
    25, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 26 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4440,
    'وَزُرُوعࣲ وَمَقَامࣲ كَرِیمࣲ',
    'وزروع ومقام كريم',
    'وَزُرُو<rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَقَا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٍ ٢٦',
    26, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 27 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4441,
    'وَنَعۡمَةࣲ كَانُوا۟ فِیهَا فَـٰكِهِینَ',
    'ونعمة كانوا فيها فاكهين',
    'وَنَعۡمَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> فِيهَا فَ<rule class=madda_normal>ـٰ</rule>كِه<rule class=madda_permissible>ِي</rule>نَ ٢٧',
    27, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 28 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4442,
    'كَذَ ٰ⁠لِكَۖ وَأَوۡرَثۡنَـٰهَا قَوۡمًا ءَاخَرِینَ',
    'كذلك واورثناها قوما اخرين',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۖ وَأَوۡرَثۡنَ<rule class=madda_normal>ـٰ</rule>هَا قَوۡمًا ءَاخَر<rule class=madda_permissible>ِي</rule>نَ ٢٨',
    28, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 29 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4443,
    'فَمَا بَكَتۡ عَلَیۡهِمُ ٱلسَّمَاۤءُ وَٱلۡأَرۡضُ وَمَا كَانُوا۟ مُنظَرِینَ',
    'فما بكت عليهم السماء والارض وما كانوا منظرين',
    'فَمَا بَكَتۡ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَمَا كَانُو<rule class=slnt>اۡ</rule> مُ<rule class=ikhafa>نظ</rule>َر<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 25, 6, 497, 431, 199, 'false'
  );
  
  -- Ayah 30 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4444,
    'وَلَقَدۡ نَجَّیۡنَا بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ مِنَ ٱلۡعَذَابِ ٱلۡمُهِینِ',
    'ولقد نجينا بني اسرائيل من العذاب المهين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> نَجَّيۡنَا بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ <rule class=ham_wasl>ٱ</rule>لۡمُه<rule class=madda_permissible>ِي</rule>نِ ٣٠',
    30, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 31 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4445,
    'مِن فِرۡعَوۡنَۚ إِنَّهُۥ كَانَ عَالِیࣰا مِّنَ ٱلۡمُسۡرِفِینَ',
    'من فرعون انه كان عاليا من المسرفين',
    'مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِرۡعَوۡنَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ عَالِ<rule class=idgham_ghunnah>يًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡرِف<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 32 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4446,
    'وَلَقَدِ ٱخۡتَرۡنَـٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَـٰلَمِینَ',
    'ولقد اخترناهم على علم على العالمين',
    'وَلَقَدِ <rule class=ham_wasl>ٱ</rule>خۡتَرۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ عَلَىٰ عِلۡمٍ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 33 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4447,
    'وَءَاتَیۡنَـٰهُم مِّنَ ٱلۡـَٔایَـٰتِ مَا فِیهِ بَلَـٰۤؤࣱا۟ مُّبِینٌ',
    'واتيناهم من الايات ما فيه بلاء مبين',
    'وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ مَا فِيهِ بَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule><rule class=idgham_ghunnah>ؤٌاۡ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٣٣',
    33, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 34 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4448,
    'إِنَّ هَـٰۤؤُلَاۤءِ لَیَقُولُونَ',
    'ان هؤلاء ليقولون',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ لَيَقُول<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 35 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4449,
    'إِنۡ هِیَ إِلَّا مَوۡتَتُنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُنشَرِینَ',
    'ان هي الا موتتنا الاولى وما نحن بمنشرين',
    'إِنۡ هِىَ إِلَّا مَوۡتَتُنَا <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ وَمَا نَحۡنُ بِمُ<rule class=ikhafa>نش</rule>َر<rule class=madda_permissible>ِي</rule>نَ ٣٥',
    35, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 36 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4450,
    'فَأۡتُوا۟ بِـَٔابَاۤىِٕنَاۤ إِن كُنتُمۡ صَـٰدِقِینَ',
    'فاتوا بابائنا ان كنتم صادقين',
    'فَأۡتُو<rule class=slnt>اۡ</rule> بِـَٔـاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 37 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4451,
    'أَهُمۡ خَیۡرٌ أَمۡ قَوۡمُ تُبَّعࣲ وَٱلَّذِینَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَـٰهُمۡۚ إِنَّهُمۡ كَانُوا۟ مُجۡرِمِینَ',
    'اهم خير ام قوم تبع والذين من قبلهم اهلكناهم انهم كانوا مجرمين',
    'أَهُمۡ خَيۡرٌ أَمۡ قَوۡمُ تُبَّ<rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ أَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> مُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 38 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4452,
    'وَمَا خَلَقۡنَا ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا لَـٰعِبِینَ',
    'وما خلقنا السماوات والارض وما بينهما لاعبين',
    'وَمَا خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُمَا لَ<rule class=madda_normal>ـٰ</rule>عِب<rule class=madda_permissible>ِي</rule>نَ ٣٨',
    38, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 39 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4453,
    'مَا خَلَقۡنَـٰهُمَاۤ إِلَّا بِٱلۡحَقِّ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'ما خلقناهما الا بالحق ولكن اكثرهم لا يعلمون',
    'مَا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 25, 6, 497, 432, 199, 'false'
  );
  
  -- Ayah 40 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4454,
    'إِنَّ یَوۡمَ ٱلۡفَصۡلِ مِیقَـٰتُهُمۡ أَجۡمَعِینَ',
    'ان يوم الفصل ميقاتهم اجمعين',
    'إِ<rule class=ghunnah>نّ</rule>َ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡفَصۡلِ مِيقَ<rule class=madda_normal>ـٰ</rule>تُهُمۡ أَ<rule class=qalaqah>جۡ</rule>مَع<rule class=madda_permissible>ِي</rule>نَ ٤٠',
    40, 25, 6, 498, 432, 199, 'false'
  );
  
  -- Ayah 41 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4455,
    'یَوۡمَ لَا یُغۡنِی مَوۡلًى عَن مَّوۡلࣰى شَیۡـࣰٔا وَلَا هُمۡ یُنصَرُونَ',
    'يوم لا يغني مولى عن مولى شيئا ولا هم ينصرون',
    'يَوۡمَ لَا يُغۡنِى مَوۡلًى ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّوۡ<rule class=ikhafa>لًى</rule> <rule class=ikhafa>ش</rule>َيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا هُمۡ يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 25, 6, 498, 432, 199, 'false'
  );
  
  -- Ayah 42 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4456,
    'إِلَّا مَن رَّحِمَ ٱللَّهُۚ إِنَّهُۥ هُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ',
    'الا من رحم الله انه هو العزيز الرحيم',
    'إِلَّا م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِمَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٤٢',
    42, 25, 6, 498, 432, 199, 'false'
  );
  
  -- Ayah 43 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4457,
    'إِنَّ شَجَرَتَ ٱلزَّقُّومِ',
    'ان شجرت الزقوم',
    'إِ<rule class=ghunnah>نّ</rule>َ شَجَرَتَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّقّ<rule class=madda_permissible>ُو</rule>مِ ٤٣',
    43, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 44 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
