    4458,
    'طَعَامُ ٱلۡأَثِیمِ',
    'طعام الاثيم',
    'طَعَامُ <rule class=ham_wasl>ٱ</rule>لۡأَث<rule class=madda_permissible>ِي</rule>مِ ٤٤',
    44, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 45 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4459,
    'كَٱلۡمُهۡلِ یَغۡلِی فِی ٱلۡبُطُونِ',
    'كالمهل يغلي في البطون',
    'كَ<rule class=ham_wasl>ٱ</rule>لۡمُهۡلِ يَغۡلِى فِى <rule class=ham_wasl>ٱ</rule>لۡبُط<rule class=madda_permissible>ُو</rule>نِ ٤٥',
    45, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 46 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4460,
    'كَغَلۡیِ ٱلۡحَمِیمِ',
    'كغلي الحميم',
    'كَغَلۡىِ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule>مِ ٤٦',
    46, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 47 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4461,
    'خُذُوهُ فَٱعۡتِلُوهُ إِلَىٰ سَوَاۤءِ ٱلۡجَحِیمِ',
    'خذوه فاعتلوه الى سواء الجحيم',
    'خُذُوهُ فَ<rule class=ham_wasl>ٱ</rule>عۡتِلُوهُ إِلَىٰ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ٤٧',
    47, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 48 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4462,
    'ثُمَّ صُبُّوا۟ فَوۡقَ رَأۡسِهِۦ مِنۡ عَذَابِ ٱلۡحَمِیمِ',
    'ثم صبوا فوق راسه من عذاب الحميم',
    'ثُ<rule class=ghunnah>مّ</rule>َ صُبُّو<rule class=slnt>اۡ</rule> فَوۡقَ رَأۡسِه<rule class=madda_normal>ِۦ</rule> مِنۡ عَذَابِ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule>مِ ٤٨',
    48, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 49 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4463,
    'ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡكَرِیمُ',
    'ذق انك انت العزيز الكريم',
    'ذُ<rule class=qalaqah>قۡ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡكَر<rule class=madda_permissible>ِي</rule>مُ ٤٩',
    49, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 50 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4464,
    'إِنَّ هَـٰذَا مَا كُنتُم بِهِۦ تَمۡتَرُونَ',
    'ان هذا ما كنتم به تمترون',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا مَا كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> تَمۡتَر<rule class=madda_permissible>ُو</rule>نَ ٥٠',
    50, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 51 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4465,
    'إِنَّ ٱلۡمُتَّقِینَ فِی مَقَامٍ أَمِینࣲ',
    'ان المتقين في مقام امين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقِينَ فِى مَقَامٍ أَم<rule class=madda_permissible>ِي</rule>نٍ ٥١',
    51, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 52 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4466,
    'فِی جَنَّـٰتࣲ وَعُیُونࣲ',
    'في جنات وعيون',
    'فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َعُي<rule class=madda_permissible>ُو</rule>نٍ ٥٢',
    52, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 53 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4467,
    'یَلۡبَسُونَ مِن سُندُسࣲ وَإِسۡتَبۡرَقࣲ مُّتَقَـٰبِلِینَ',
    'يلبسون من سندس واستبرق متقابلين',
    'يَلۡبَسُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُ<rule class=ikhafa>ند</rule>ُ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِسۡتَ<rule class=qalaqah>بۡ</rule>رَ<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّتَقَ<rule class=madda_normal>ـٰ</rule>بِل<rule class=madda_permissible>ِي</rule>نَ ٥٣',
    53, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 54 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4468,
    'كَذَ ٰ⁠لِكَ وَزَوَّجۡنَـٰهُم بِحُورٍ عِینࣲ',
    'كذلك وزوجناهم بحور عين',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ وَزَوَّ<rule class=qalaqah>جۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِحُورٍ ع<rule class=madda_permissible>ِي</rule>نٍ ٥٤',
    54, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 55 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4469,
    'یَدۡعُونَ فِیهَا بِكُلِّ فَـٰكِهَةٍ ءَامِنِینَ',
    'يدعون فيها بكل فاكهة امنين',
    'يَ<rule class=qalaqah>دۡ</rule>عُونَ فِيهَا بِكُلِّ فَ<rule class=madda_normal>ـٰ</rule>كِهَةٍ ءَامِن<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 56 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4470,
    'لَا یَذُوقُونَ فِیهَا ٱلۡمَوۡتَ إِلَّا ٱلۡمَوۡتَةَ ٱلۡأُولَىٰۖ وَوَقَىٰهُمۡ عَذَابَ ٱلۡجَحِیمِ',
    'لا يذوقون فيها الموت الا الموتة الاولى ووقاهم عذاب الجحيم',
    'لَا يَذُوقُونَ فِيهَا <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَةَ <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ‌ۖ وَوَقَ<rule class=madda_normal>ـٰ</rule>هُمۡ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ٥٦',
    56, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 57 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4471,
    'فَضۡلࣰا مِّن رَّبِّكَۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'فضلا من ربك ذلك هو الفوز العظيم',
    'فَضۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٥٧',
    57, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 58 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4472,
    'فَإِنَّمَا یَسَّرۡنَـٰهُ بِلِسَانِكَ لَعَلَّهُمۡ یَتَذَكَّرُونَ',
    'فانما يسرناه بلسانك لعلهم يتذكرون',
    'فَإِ<rule class=ghunnah>نّ</rule>َمَا يَسَّرۡنَ<rule class=madda_normal>ـٰ</rule>هُ بِلِسَانِكَ لَعَلَّهُمۡ يَتَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٥٨',
    58, 25, 6, 498, 433, 199, 'false'
  );
  
  -- Ayah 59 Surah Ad-Dukhaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    44,
    4473,
    'فَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ',
    'فارتقب انهم مرتقبون',
    'فَ<rule class=ham_wasl>ٱ</rule>رۡتَقِ<rule class=qalaqah>بۡ</rule> إِ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّرۡتَقِب<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 25, 6, 498, 433, 199, 'false'
  );
  

-- Surah Al-Jaathiya
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (45, 'سُورَةُ الجَاثِيَةِ', 'Al-Jaathiya', 'Crouching', 'Meccan', 37);

  -- Ayah 1 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4474,
    'حمۤ',
    'حم',
    'ح<rule class=madda_necessary>مٓ</rule> ١',
    1, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 2 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4475,
    'تَنزِیلُ ٱلۡكِتَـٰبِ مِنَ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ',
    'تنزيل الكتاب من الله العزيز الحكيم',
    'تَ<rule class=ikhafa>نز</rule>ِيلُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ٢',
    2, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 3 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4476,
    'إِنَّ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ لَـَٔایَـٰتࣲ لِّلۡمُؤۡمِنِینَ',
    'ان في السماوات والارض لايات للمؤمنين',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٣',
    3, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 4 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4477,
    'وَفِی خَلۡقِكُمۡ وَمَا یَبُثُّ مِن دَاۤبَّةٍ ءَایَـٰتࣱ لِّقَوۡمࣲ یُوقِنُونَ',
    'وفي خلقكم وما يبث من دابة ايات لقوم يوقنون',
    'وَفِى خَلۡقِكُمۡ وَمَا يَبُثُّ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule><rule class=madda_necessary>َا</rule>ٓبَّةٍ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوقِن<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 5 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4478,
    'وَٱخۡتِلَـٰفِ ٱلَّیۡلِ وَٱلنَّهَارِ وَمَاۤ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَاۤءِ مِن رِّزۡقࣲ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِیفِ ٱلرِّیَـٰحِ ءَایَـٰتࣱ لِّقَوۡمࣲ یَعۡقِلُونَ',
    'واختلاف الليل والنهار وما انزل الله من السماء من رزق فاحيا به الارض بعد موتها وتصريف الرياح ايات لقوم يعقلون',
    'وَ<rule class=ham_wasl>ٱ</rule>خۡتِلَ<rule class=madda_normal>ـٰ</rule>فِ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّزۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ف</rule>َأَحۡيَا بِهِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِيفِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيَ<rule class=madda_normal>ـٰ</rule>حِ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 6 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4479,
    'تِلۡكَ ءَایَـٰتُ ٱللَّهِ نَتۡلُوهَا عَلَیۡكَ بِٱلۡحَقِّۖ فَبِأَیِّ حَدِیثِۭ بَعۡدَ ٱللَّهِ وَءَایَـٰتِهِۦ یُؤۡمِنُونَ',
    'تلك ايات الله نتلوها عليك بالحق فباي حديث بعد الله واياته يؤمنون',
    'تِلۡكَ ءَايَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>للَّهِ نَتۡلُوهَا عَلَيۡكَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ فَبِأَىِّ حَدِي<rule class=iqlab>ثِۭ</rule> <rule class=iqlab>ب</rule>َعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 7 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4480,
    'وَیۡلࣱ لِّكُلِّ أَفَّاكٍ أَثِیمࣲ',
    'ويل لكل افاك اثيم',
    'وَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ أَفَّاكٍ أَث<rule class=madda_permissible>ِي</rule>مٍ ٧',
    7, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 8 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4481,
    'یَسۡمَعُ ءَایَـٰتِ ٱللَّهِ تُتۡلَىٰ عَلَیۡهِ ثُمَّ یُصِرُّ مُسۡتَكۡبِرࣰا كَأَن لَّمۡ یَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِیمࣲ',
    'يسمع ايات الله تتلى عليه ثم يصر مستكبرا كان لم يسمعها فبشره بعذاب اليم',
    'يَسۡمَعُ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ تُتۡلَىٰ عَلَيۡهِ ثُ<rule class=ghunnah>مّ</rule>َ يُصِرُّ مُسۡتَكۡبِ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَسۡمَعۡهَا‌ۖ فَبَشِّرۡهُ بِعَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٨',
    8, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 9 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4482,
    'وَإِذَا عَلِمَ مِنۡ ءَایَـٰتِنَا شَیۡـًٔا ٱتَّخَذَهَا هُزُوًاۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مُّهِینࣱ',
    'واذا علم من اياتنا شيئا اتخذها هزوا اولئك لهم عذاب مهين',
    'وَإِذَا عَلِمَ مِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِنَا شَيۡــًٔا <rule class=ham_wasl>ٱ</rule>تَّخَذَهَا هُزُوًا‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ لَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّه<rule class=madda_permissible>ِي</rule>نٌ ٩',
    9, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 10 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4483,
    'مِّن وَرَاۤىِٕهِمۡ جَهَنَّمُۖ وَلَا یُغۡنِی عَنۡهُم مَّا كَسَبُوا۟ شَیۡـࣰٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوۡلِیَاۤءَۖ وَلَهُمۡ عَذَابٌ عَظِیمٌ',
    'من ورائهم جهنم ولا يغني عنهم ما كسبوا شيئا ولا ما اتخذوا من دون الله اولياء ولهم عذاب عظيم',
    'مّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۖ وَلَا يُغۡنِى عَنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا كَسَبُو<rule class=slnt>اۡ</rule> شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا مَا <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ‌ۖ وَلَهُمۡ عَذَابٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٠',
    10, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 11 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4484,
    'هَـٰذَا هُدࣰىۖ وَٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ لَهُمۡ عَذَابࣱ مِّن رِّجۡزٍ أَلِیمٌ',
    'هذا هدى والذين كفروا بايات ربهم لهم عذاب من رجز اليم',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا هُ<rule class=idgham_ghunnah>دًى‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ لَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّ<rule class=qalaqah>جۡ</rule>زٍ أَل<rule class=madda_permissible>ِي</rule>مٌ ١١',
    11, 25, 6, 499, 434, 199, 'false'
  );
  
  -- Ayah 12 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4485,
    '۞ ٱللَّهُ ٱلَّذِی سَخَّرَ لَكُمُ ٱلۡبَحۡرَ لِتَجۡرِیَ ٱلۡفُلۡكُ فِیهِ بِأَمۡرِهِۦ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ',
    'الله الذي سخر لكم البحر لتجري الفلك فيه بامره ولتبتغوا من فضله ولعلكم تشكرون',
    '۞ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى سَخَّرَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡبَحۡرَ لِتَ<rule class=qalaqah>جۡ</rule>رِىَ <rule class=ham_wasl>ٱ</rule>لۡفُلۡكُ فِيهِ بِأَمۡرِه<rule class=madda_normal>ِۦ</rule> وَلِتَ<rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِه<rule class=madda_normal>ِۦ</rule> وَلَعَلَّكُمۡ تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 25, 6, 499, 435, 200, 'false'
  );
  
  -- Ayah 13 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4486,
    'وَسَخَّرَ لَكُم مَّا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ جَمِیعࣰا مِّنۡهُۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ',
    'وسخر لكم ما في السماوات وما في الارض جميعا منه ان في ذلك لايات لقوم يتفكرون',
    'وَسَخَّرَ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَأَيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 25, 6, 499, 435, 200, 'false'
  );
  
  -- Ayah 14 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4487,
    'قُل لِّلَّذِینَ ءَامَنُوا۟ یَغۡفِرُوا۟ لِلَّذِینَ لَا یَرۡجُونَ أَیَّامَ ٱللَّهِ لِیَجۡزِیَ قَوۡمَۢا بِمَا كَانُوا۟ یَكۡسِبُونَ',
    'قل للذين امنوا يغفروا للذين لا يرجون ايام الله ليجزي قوما بما كانوا يكسبون',
    'قُل لِّلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> يَغۡفِرُو<rule class=slnt>اۡ</rule> لِلَّذِينَ لَا يَرۡجُونَ أَيَّامَ <rule class=ham_wasl>ٱ</rule>للَّهِ لِيَ<rule class=qalaqah>جۡ</rule>زِىَ قَوۡم<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 25, 6, 500, 435, 200, 'false'
  );
  
  -- Ayah 15 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4488,
    'مَنۡ عَمِلَ صَـٰلِحࣰا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَاۤءَ فَعَلَیۡهَاۖ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ',
    'من عمل صالحا فلنفسه ومن اساء فعليها ثم الى ربكم ترجعون',
    'مَنۡ عَمِلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َلِنَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَنۡ أَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَعَلَيۡهَا‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ إِلَىٰ رَبِّكُمۡ تُرۡجَع<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 25, 6, 500, 435, 200, 'false'
  );
  
  -- Ayah 16 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4489,
    'وَلَقَدۡ ءَاتَیۡنَا بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱلۡكِتَـٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ وَرَزَقۡنَـٰهُم مِّنَ ٱلطَّیِّبَـٰتِ وَفَضَّلۡنَـٰهُمۡ عَلَى ٱلۡعَـٰلَمِینَ',
    'ولقد اتينا بني اسرائيل الكتاب والحكم والنبوة ورزقناهم من الطيبات وفضلناهم على العالمين',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ءَاتَيۡنَا بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحُكۡمَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُبُوَّةَ وَرَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيِّبَ<rule class=madda_normal>ـٰ</rule>تِ وَفَضَّلۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٦',
    16, 25, 6, 500, 435, 200, 'false'
  );
  
  -- Ayah 17 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4490,
    'وَءَاتَیۡنَـٰهُم بَیِّنَـٰتࣲ مِّنَ ٱلۡأَمۡرِۖ فَمَا ٱخۡتَلَفُوۤا۟ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَهُمُ ٱلۡعِلۡمُ بَغۡیَۢا بَیۡنَهُمۡۚ إِنَّ رَبَّكَ یَقۡضِی بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ',
    'واتيناهم بينات من الامر فما اختلفوا الا من بعد ما جاءهم العلم بغيا بينهم ان ربك يقضي بينهم يوم القيامة فيما كانوا فيه يختلفون',
    'وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ‌ۖ فَمَا <rule class=ham_wasl>ٱ</rule>خۡتَلَف<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمُ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمُ بَغۡي<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ يَ<rule class=qalaqah>قۡ</rule>ضِى بَيۡنَهُمۡ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ فِيمَا كَانُو<rule class=slnt>اۡ</rule> فِيهِ يَخۡتَلِف<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 25, 6, 500, 435, 200, 'false'
  );
  
  -- Ayah 18 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4491,
    'ثُمَّ جَعَلۡنَـٰكَ عَلَىٰ شَرِیعَةࣲ مِّنَ ٱلۡأَمۡرِ فَٱتَّبِعۡهَا وَلَا تَتَّبِعۡ أَهۡوَاۤءَ ٱلَّذِینَ لَا یَعۡلَمُونَ',
    'ثم جعلناك على شريعة من الامر فاتبعها ولا تتبع اهواء الذين لا يعلمون',
    'ثُ<rule class=ghunnah>مّ</rule>َ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ عَلَىٰ شَرِيعَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ فَ<rule class=ham_wasl>ٱ</rule>تَّبِعۡهَا وَلَا تَتَّبِعۡ أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 25, 6, 500, 435, 200, 'false'
  );
  
  -- Ayah 19 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4492,
    'إِنَّهُمۡ لَن یُغۡنُوا۟ عَنكَ مِنَ ٱللَّهِ شَیۡـࣰٔاۚ وَإِنَّ ٱلظَّـٰلِمِینَ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضࣲۖ وَٱللَّهُ وَلِیُّ ٱلۡمُتَّقِینَ',
    'انهم لن يغنوا عنك من الله شيئا وان الظالمين بعضهم اولياء بعض والله ولي المتقين',
    'إِ<rule class=ghunnah>نّ</rule>َهُمۡ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُغۡنُو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>نك</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡـ<rule class=idgham_ghunnah>ـًٔا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ بَعۡضُهُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بَعۡ<rule class=idgham_ghunnah>ضٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ وَلِىُّ <rule class=ham_wasl>ٱ</rule>لۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ١٩',
    19, 25, 6, 500, 435, 200, 'false'
  );
  
  -- Ayah 20 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4493,
    'هَـٰذَا بَصَـٰۤىِٕرُ لِلنَّاسِ وَهُدࣰى وَرَحۡمَةࣱ لِّقَوۡمࣲ یُوقِنُونَ',
    'هذا بصائر للناس وهدى ورحمة لقوم يوقنون',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا بَصَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرُ لِل<rule class=ghunnah>نّ</rule>َاسِ وَهُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّقَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوقِن<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 25, 6, 500, 435, 200, 'false'
  );
  
  -- Ayah 21 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4494,
    'أَمۡ حَسِبَ ٱلَّذِینَ ٱجۡتَرَحُوا۟ ٱلسَّیِّـَٔاتِ أَن نَّجۡعَلَهُمۡ كَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَوَاۤءࣰ مَّحۡیَاهُمۡ وَمَمَاتُهُمۡۚ سَاۤءَ مَا یَحۡكُمُونَ',
    'ام حسب الذين اجترحوا السيئات ان نجعلهم كالذين امنوا وعملوا الصالحات سواء محياهم ومماتهم ساء ما يحكمون',
    'أَمۡ حَسِبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَرَحُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّيِّـَٔـاتِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>جۡ</rule>عَلَهُمۡ كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>م</rule>َّحۡيَاهُمۡ وَمَمَاتُهُمۡ‌ۚ س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا يَحۡكُم<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 25, 6, 500, 435, 200, 'false'
  );
  
  -- Ayah 22 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4495,
    'وَخَلَقَ ٱللَّهُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَلِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ وَهُمۡ لَا یُظۡلَمُونَ',
    'وخلق الله السماوات والارض بالحق ولتجزى كل نفس بما كسبت وهم لا يظلمون',
    'وَخَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَلِتُ<rule class=qalaqah>جۡ</rule>زَىٰ كُلُّ نَفۡ<rule class=iqlab>سِۭ</rule> <rule class=iqlab>ب</rule>ِمَا كَسَبَتۡ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 25, 6, 500, 436, 200, 'false'
  );
  
  -- Ayah 23 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4496,
    'أَفَرَءَیۡتَ مَنِ ٱتَّخَذَ إِلَـٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمࣲ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَـٰوَةࣰ فَمَن یَهۡدِیهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ',
    'افرايت من اتخذ الهه هواه واضله الله على علم وختم على سمعه وقلبه وجعل على بصره غشاوة فمن يهديه من بعد الله افلا تذكرون',
    'أَفَرَءَيۡتَ مَنِ <rule class=ham_wasl>ٱ</rule>تَّخَذَ إِلَ<rule class=madda_normal>ـٰ</rule>هَهُ<rule class=madda_normal>ۥ</rule> هَوَ<rule class=madda_normal>ٮٰ</rule>هُ وَأَضَلَّهُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ عِلۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َخَتَمَ عَلَىٰ سَمۡعِه<rule class=madda_normal>ِۦ</rule> وَقَلۡبِه<rule class=madda_normal>ِۦ</rule> وَجَعَلَ عَلَىٰ بَصَرِه<rule class=madda_normal>ِۦ</rule> غِشَ<rule class=madda_normal>ـٰ</rule>وَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدِيهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ أَفَلَا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 25, 6, 501, 436, 200, 'false'
  );
  
  -- Ayah 24 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4497,
    'وَقَالُوا۟ مَا هِیَ إِلَّا حَیَاتُنَا ٱلدُّنۡیَا نَمُوتُ وَنَحۡیَا وَمَا یُهۡلِكُنَاۤ إِلَّا ٱلدَّهۡرُۚ وَمَا لَهُم بِذَ ٰ⁠لِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا یَظُنُّونَ',
    'وقالوا ما هي الا حياتنا الدنيا نموت ونحيا وما يهلكنا الا الدهر وما لهم بذلك من علم ان هم الا يظنون',
    'وَقَالُو<rule class=slnt>اۡ</rule> مَا هِىَ إِلَّا حَيَاتُنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا يُهۡلِكُن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّهۡرُ‌ۚ وَمَا لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذ<rule class=madda_normal>ٰ</rule>لِكَ مِنۡ عِلۡمٍ‌ۖ إِنۡ هُمۡ إِلَّا يَظُ<rule class=ghunnah>نّ</rule><rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 25, 6, 501, 436, 200, 'false'
  );
  
  -- Ayah 25 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4498,
    'وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ مَّا كَانَ حُجَّتَهُمۡ إِلَّاۤ أَن قَالُوا۟ ٱئۡتُوا۟ بِـَٔابَاۤىِٕنَاۤ إِن كُنتُمۡ صَـٰدِقِینَ',
    'واذا تتلى عليهم اياتنا بينات ما كان حجتهم الا ان قالوا ائتوا بابائنا ان كنتم صادقين',
    'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا بَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا كَانَ حُجَّتَهُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>ئۡتُو<rule class=slnt>اۡ</rule> بِـَٔـاب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 25, 6, 501, 436, 200, 'false'
  );
  
  -- Ayah 26 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4499,
    'قُلِ ٱللَّهُ یُحۡیِیكُمۡ ثُمَّ یُمِیتُكُمۡ ثُمَّ یَجۡمَعُكُمۡ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ لَا رَیۡبَ فِیهِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ',
    'قل الله يحييكم ثم يميتكم ثم يجمعكم الى يوم القيامة لا ريب فيه ولكن اكثر الناس لا يعلمون',
    'قُلِ <rule class=ham_wasl>ٱ</rule>للَّهُ يُحۡيِيكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يُمِيتُكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ يَ<rule class=qalaqah>جۡ</rule>مَعُكُمۡ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ لَا رَيۡبَ فِيهِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 25, 6, 501, 436, 200, 'false'
  );
  
  -- Ayah 27 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4500,
    'وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یَوۡمَىِٕذࣲ یَخۡسَرُ ٱلۡمُبۡطِلُونَ',
    'ولله ملك السماوات والارض ويوم تقوم الساعة يومئذ يخسر المبطلون',
    'وَلِلَّهِ مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَيَوۡمَ تَقُومُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َخۡسَرُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>بۡ</rule>طِل<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 25, 6, 501, 437, 200, 'false'
  );
  
  -- Ayah 28 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4501,
    'وَتَرَىٰ كُلَّ أُمَّةࣲ جَاثِیَةࣰۚ كُلُّ أُمَّةࣲ تُدۡعَىٰۤ إِلَىٰ كِتَـٰبِهَا ٱلۡیَوۡمَ تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ',
    'وترى كل امة جاثية كل امة تدعى الى كتابها اليوم تجزون ما كنتم تعملون',
    'وَتَرَىٰ كُلَّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ج</rule>َاثِيَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ك</rule>ُلُّ أُ<rule class=ghunnah>مّ</rule>َ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>دۡ</rule>عَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىٰ كِتَ<rule class=madda_normal>ـٰ</rule>بِهَا <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ تُ<rule class=qalaqah>جۡ</rule>زَوۡنَ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 25, 6, 501, 437, 200, 'false'
  );
  
  -- Ayah 29 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4502,
    'هَـٰذَا كِتَـٰبُنَا یَنطِقُ عَلَیۡكُم بِٱلۡحَقِّۚ إِنَّا كُنَّا نَسۡتَنسِخُ مَا كُنتُمۡ تَعۡمَلُونَ',
    'هذا كتابنا ينطق عليكم بالحق انا كنا نستنسخ ما كنتم تعملون',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا كِتَ<rule class=madda_normal>ـٰ</rule>بُنَا يَ<rule class=ikhafa>نط</rule>ِقُ عَلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا نَسۡتَ<rule class=ikhafa>نس</rule>ِخُ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 25, 6, 501, 437, 200, 'false'
  );
  
  -- Ayah 30 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4503,
    'فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَیُدۡخِلُهُمۡ رَبُّهُمۡ فِی رَحۡمَتِهِۦۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَوۡزُ ٱلۡمُبِینُ',
    'فاما الذين امنوا وعملوا الصالحات فيدخلهم ربهم في رحمته ذلك هو الفوز المبين',
    'فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فَيُ<rule class=qalaqah>دۡ</rule>خِلُهُمۡ رَبُّهُمۡ فِى رَحۡمَتِه<rule class=madda_normal>ِۦ</rule>‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ٣٠',
    30, 25, 6, 501, 437, 200, 'false'
  );
  
  -- Ayah 31 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4504,
    'وَأَمَّا ٱلَّذِینَ كَفَرُوۤا۟ أَفَلَمۡ تَكُنۡ ءَایَـٰتِی تُتۡلَىٰ عَلَیۡكُمۡ فَٱسۡتَكۡبَرۡتُمۡ وَكُنتُمۡ قَوۡمࣰا مُّجۡرِمِینَ',
    'واما الذين كفروا افلم تكن اياتي تتلى عليكم فاستكبرتم وكنتم قوما مجرمين',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَفَلَمۡ تَكُنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِى تُتۡلَىٰ عَلَيۡكُمۡ فَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرۡتُمۡ وَكُ<rule class=ikhafa>نت</rule>ُمۡ قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 25, 6, 501, 437, 200, 'false'
  );
  
  -- Ayah 32 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4505,
    'وَإِذَا قِیلَ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَٱلسَّاعَةُ لَا رَیۡبَ فِیهَا قُلۡتُم مَّا نَدۡرِی مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنࣰّا وَمَا نَحۡنُ بِمُسۡتَیۡقِنِینَ',
    'واذا قيل ان وعد الله حق والساعة لا ريب فيها قلتم ما ندري ما الساعة ان نظن الا ظنا وما نحن بمستيقنين',
    'وَإِذَا قِيلَ إِ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=idgham_ghunnah>قٌّ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ لَا رَيۡبَ فِيهَا قُلۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا نَ<rule class=qalaqah>دۡ</rule>رِى مَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّظُ<rule class=ghunnah>نّ</rule>ُ إِلَّا ظَن<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َمَا نَحۡنُ بِمُسۡتَيۡقِن<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 25, 6, 501, 437, 200, 'false'
  );
  
  -- Ayah 33 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4506,
    'وَبَدَا لَهُمۡ سَیِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'وبدا لهم سيئات ما عملوا وحاق بهم ما كانوا به يستهزئون',
    'وَبَدَا لَهُمۡ سَيِّـَٔـاتُ مَا عَمِلُو<rule class=slnt>اۡ</rule> وَحَاقَ بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 25, 6, 502, 437, 200, 'false'
  );
  
  -- Ayah 34 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4507,
    'وَقِیلَ ٱلۡیَوۡمَ نَنسَىٰكُمۡ كَمَا نَسِیتُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِینَ',
    'وقيل اليوم ننساكم كما نسيتم لقاء يومكم هذا وماواكم النار وما لكم من ناصرين',
    'وَقِيلَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ نَ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>كُمۡ كَمَا نَسِيتُمۡ لِق<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ يَوۡمِكُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا وَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ وَمَا لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=madda_normal>ـٰ</rule>صِر<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 25, 6, 502, 437, 200, 'false'
  );
  
  -- Ayah 35 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4508,
    'ذَ ٰ⁠لِكُم بِأَنَّكُمُ ٱتَّخَذۡتُمۡ ءَایَـٰتِ ٱللَّهِ هُزُوࣰا وَغَرَّتۡكُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۚ فَٱلۡیَوۡمَ لَا یُخۡرَجُونَ مِنۡهَا وَلَا هُمۡ یُسۡتَعۡتَبُونَ',
    'ذلكم بانكم اتخذتم ايات الله هزوا وغرتكم الحياة الدنيا فاليوم لا يخرجون منها ولا هم يستعتبون',
    'ذ<rule class=madda_normal>ٰ</rule>لِك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَ<rule class=ghunnah>نّ</rule>َكُمُ <rule class=ham_wasl>ٱ</rule>تَّخَذۡتُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ هُزُ<rule class=idgham_ghunnah>وًا</rule> <rule class=idgham_ghunnah>و</rule>َغَرَّتۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۚ فَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ لَا يُخۡرَجُونَ مِنۡهَا وَلَا هُمۡ يُسۡتَعۡتَب<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 25, 6, 502, 437, 200, 'false'
  );
  
  -- Ayah 36 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4509,
    'فَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَـٰوَ ٰ⁠تِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَـٰلَمِینَ',
    'فلله الحمد رب السماوات ورب الارض رب العالمين',
    'فَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَرَبِّ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ رَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 25, 6, 502, 437, 200, 'false'
  );
  
  -- Ayah 37 Surah Al-Jaathiya
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    45,
    4510,
    'وَلَهُ ٱلۡكِبۡرِیَاۤءُ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'وله الكبرياء في السماوات والارض وهو العزيز الحكيم',
    'وَلَهُ <rule class=ham_wasl>ٱ</rule>لۡكِ<rule class=qalaqah>بۡ</rule>رِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٣٧',
    37, 25, 6, 502, 437, 200, 'false'
  );
  

-- Surah Al-Ahqaf
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (46, 'سُورَةُ الأَحۡقَافِ', 'Al-Ahqaf', 'The Dunes', 'Meccan', 35);

  -- Ayah 1 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4511,
    'حمۤ',
    'حم',
    'ح<rule class=madda_necessary>مٓ</rule> ١',
    1, 26, 6, 502, 438, 201, 'false'
  );
  
  -- Ayah 2 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4512,
    'تَنزِیلُ ٱلۡكِتَـٰبِ مِنَ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ',
    'تنزيل الكتاب من الله العزيز الحكيم',
    'تَ<rule class=ikhafa>نز</rule>ِيلُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ٢',
    2, 26, 6, 502, 438, 201, 'false'
  );
  
  -- Ayah 3 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4513,
    'مَا خَلَقۡنَا ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَاۤ إِلَّا بِٱلۡحَقِّ وَأَجَلࣲ مُّسَمࣰّىۚ وَٱلَّذِینَ كَفَرُوا۟ عَمَّاۤ أُنذِرُوا۟ مُعۡرِضُونَ',
    'ما خلقنا السماوات والارض وما بينهما الا بالحق واجل مسمى والذين كفروا عما انذروا معرضون',
    'مَا خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُم<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَأَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَم<rule class=idgham_ghunnah>ًّى‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> عَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نذ</rule>ِرُو<rule class=slnt>اۡ</rule> مُعۡرِض<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 26, 6, 502, 438, 201, 'false'
  );
  
  -- Ayah 4 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4514,
    'قُلۡ أَرَءَیۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِی مَاذَا خَلَقُوا۟ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكࣱ فِی ٱلسَّمَـٰوَ ٰ⁠تِۖ ٱئۡتُونِی بِكِتَـٰبࣲ مِّن قَبۡلِ هَـٰذَاۤ أَوۡ أَثَـٰرَةࣲ مِّنۡ عِلۡمٍ إِن كُنتُمۡ صَـٰدِقِینَ',
    'قل ارايتم ما تدعون من دون الله اروني ماذا خلقوا من الارض ام لهم شرك في السماوات ائتوني بكتاب من قبل هذا او اثارة من علم ان كنتم صادقين',
    'قُلۡ أَرَءَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا تَ<rule class=qalaqah>دۡ</rule>عُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَرُونِى مَاذَا خَلَقُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَمۡ لَهُمۡ شِرۡ<rule class=ikhafa>كٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ‌ۖ <rule class=ham_wasl>ٱ</rule>ئۡتُونِى بِكِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡ أَثَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِلۡمٍ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٤',
    4, 26, 6, 502, 438, 201, 'false'
  );
  
  -- Ayah 5 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4515,
    'وَمَنۡ أَضَلُّ مِمَّن یَدۡعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا یَسۡتَجِیبُ لَهُۥۤ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ وَهُمۡ عَن دُعَاۤىِٕهِمۡ غَـٰفِلُونَ',
    'ومن اضل ممن يدعو من دون الله من لا يستجيب له الى يوم القيامة وهم عن دعائهم غافلون',
    'وَمَنۡ أَضَلُّ مِ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَسۡتَجِيبُ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ وَهُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُع<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ غَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 26, 6, 502, 438, 201, 'false'
  );
  
  -- Ayah 6 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4516,
    'وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمۡ أَعۡدَاۤءࣰ وَكَانُوا۟ بِعِبَادَتِهِمۡ كَـٰفِرِینَ',
    'واذا حشر الناس كانوا لهم اعداء وكانوا بعبادتهم كافرين',
    'وَإِذَا حُشِرَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ كَانُو<rule class=slnt>اۡ</rule> لَهُمۡ أَعۡد<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َكَانُو<rule class=slnt>اۡ</rule> بِعِبَادَتِهِمۡ كَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 26, 6, 503, 438, 201, 'false'
  );
  
  -- Ayah 7 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4517,
    'وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ قَالَ ٱلَّذِینَ كَفَرُوا۟ لِلۡحَقِّ لَمَّا جَاۤءَهُمۡ هَـٰذَا سِحۡرࣱ مُّبِینٌ',
    'واذا تتلى عليهم اياتنا بينات قال الذين كفروا للحق لما جاءهم هذا سحر مبين',
    'وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا بَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ق</rule>َالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لِلۡحَقِّ لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٧',
    7, 26, 6, 503, 438, 201, 'false'
  );
  
  -- Ayah 8 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4518,
    'أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَیۡتُهُۥ فَلَا تَمۡلِكُونَ لِی مِنَ ٱللَّهِ شَیۡـًٔاۖ هُوَ أَعۡلَمُ بِمَا تُفِیضُونَ فِیهِۚ كَفَىٰ بِهِۦ شَهِیدَۢا بَیۡنِی وَبَیۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ',
    'ام يقولون افتراه قل ان افتريته فلا تملكون لي من الله شيئا هو اعلم بما تفيضون فيه كفى به شهيدا بيني وبينكم وهو الغفور الرحيم',
    'أَمۡ يَقُولُونَ <rule class=ham_wasl>ٱ</rule>فۡتَرَ<rule class=madda_normal>ٮٰ</rule>هُ‌ۖ قُلۡ إِنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَيۡتُهُ<rule class=madda_normal>ۥ</rule> فَلَا تَمۡلِكُونَ لِى مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡــًٔا‌ۖ هُوَ أَعۡلَمُ بِمَا تُفِيضُونَ فِيهِ‌ۖ كَفَىٰ بِه<rule class=madda_normal>ِۦ</rule> شَهِيد<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َيۡنِى وَبَيۡنَكُمۡ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡغَفُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٨',
    8, 26, 6, 503, 438, 201, 'false'
  );
  
  -- Ayah 9 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4519,
    'قُلۡ مَا كُنتُ بِدۡعࣰا مِّنَ ٱلرُّسُلِ وَمَاۤ أَدۡرِی مَا یُفۡعَلُ بِی وَلَا بِكُمۡۖ إِنۡ أَتَّبِعُ إِلَّا مَا یُوحَىٰۤ إِلَیَّ وَمَاۤ أَنَا۠ إِلَّا نَذِیرࣱ مُّبِینࣱ',
    'قل ما كنت بدعا من الرسل وما ادري ما يفعل بي ولا بكم ان اتبع الا ما يوحى الي وما انا الا نذير مبين',
    'قُلۡ مَا كُ<rule class=ikhafa>نت</rule>ُ بِ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلِ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رِى مَا يُفۡعَلُ بِى وَلَا بِكُمۡ‌ۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىَّ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ إِلَّا نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٩',
    9, 26, 6, 503, 438, 201, 'false'
  );
  
  -- Ayah 10 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4520,
    'قُلۡ أَرَءَیۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ وَكَفَرۡتُم بِهِۦ وَشَهِدَ شَاهِدࣱ مِّنۢ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ عَلَىٰ مِثۡلِهِۦ فَـَٔامَنَ وَٱسۡتَكۡبَرۡتُمۡۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'قل ارايتم ان كان من عند الله وكفرتم به وشهد شاهد من بني اسرائيل على مثله فامن واستكبرتم ان الله لا يهدي القوم الظالمين',
    'قُلۡ أَرَءَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِنۡ عِ<rule class=ikhafa>ند</rule>ِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَكَفَرۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> وَشَهِدَ شَاهِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ عَلَىٰ مِثۡلِه<rule class=madda_normal>ِۦ</rule> فَـَٔـامَنَ وَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرۡتُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 26, 6, 503, 438, 201, 'false'
  );
  
  -- Ayah 11 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4521,
    'وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوا۟ لَوۡ كَانَ خَیۡرࣰا مَّا سَبَقُونَاۤ إِلَیۡهِۚ وَإِذۡ لَمۡ یَهۡتَدُوا۟ بِهِۦ فَسَیَقُولُونَ هَـٰذَاۤ إِفۡكࣱ قَدِیمࣱ',
    'وقال الذين كفروا للذين امنوا لو كان خيرا ما سبقونا اليه واذ لم يهتدوا به فسيقولون هذا افك قديم',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لِلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَوۡ كَانَ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>َّا سَبَقُون<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡهِ‌ۚ وَإِذۡ لَمۡ يَهۡتَدُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> فَسَيَقُولُونَ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِفۡ<rule class=ikhafa>كٌ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>مٌ ١١',
    11, 26, 6, 503, 439, 201, 'false'
  );
  
  -- Ayah 12 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4522,
    'وَمِن قَبۡلِهِۦ كِتَـٰبُ مُوسَىٰۤ إِمَامࣰا وَرَحۡمَةࣰۚ وَهَـٰذَا كِتَـٰبࣱ مُّصَدِّقࣱ لِّسَانًا عَرَبِیࣰّا لِّیُنذِرَ ٱلَّذِینَ ظَلَمُوا۟ وَبُشۡرَىٰ لِلۡمُحۡسِنِینَ',
    'ومن قبله كتاب موسى اماما ورحمة وهذا كتاب مصدق لسانا عربيا لينذر الذين ظلموا وبشرى للمحسنين',
    'وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=madda_normal>ِۦ</rule> كِتَ<rule class=madda_normal>ـٰ</rule>بُ مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِمَا<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َهَ<rule class=madda_normal>ـٰ</rule>ذَا كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّصَدِّ<rule class=idgham_wo_ghunnah>قٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّسَانًا عَرَبِي<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُ<rule class=ikhafa>نذ</rule>ِرَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> وَبُشۡرَىٰ لِلۡمُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٢',
    12, 26, 6, 503, 439, 201, 'false'
  );
  
  -- Ayah 13 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4523,
    'إِنَّ ٱلَّذِینَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَـٰمُوا۟ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ',
    'ان الذين قالوا ربنا الله ثم استقاموا فلا خوف عليهم ولا هم يحزنون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَالُو<rule class=slnt>اۡ</rule> رَبُّنَا <rule class=ham_wasl>ٱ</rule>للَّهُ ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَقَ<rule class=madda_normal>ـٰ</rule>مُو<rule class=slnt>اۡ</rule> فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَن<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 26, 6, 503, 439, 201, 'false'
  );
  
  -- Ayah 14 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4524,
    'أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِ خَـٰلِدِینَ فِیهَا جَزَاۤءَۢ بِمَا كَانُوا۟ یَعۡمَلُونَ',
    'اولئك اصحاب الجنة خالدين فيها جزاء بما كانوا يعملون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءَۢ</rule> <rule class=iqlab>ب</rule>ِمَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 26, 6, 503, 439, 201, 'false'
  );
  
  -- Ayah 15 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4525,
    'وَوَصَّیۡنَا ٱلۡإِنسَـٰنَ بِوَ ٰ⁠لِدَیۡهِ إِحۡسَـٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهࣰا وَوَضَعَتۡهُ كُرۡهࣰاۖ وَحَمۡلُهُۥ وَفِصَـٰلُهُۥ ثَلَـٰثُونَ شَهۡرًاۚ حَتَّىٰۤ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِینَ سَنَةࣰ قَالَ رَبِّ أَوۡزِعۡنِیۤ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِیۤ أَنۡعَمۡتَ عَلَیَّ وَعَلَىٰ وَ ٰ⁠لِدَیَّ وَأَنۡ أَعۡمَلَ صَـٰلِحࣰا تَرۡضَىٰهُ وَأَصۡلِحۡ لِی فِی ذُرِّیَّتِیۤۖ إِنِّی تُبۡتُ إِلَیۡكَ وَإِنِّی مِنَ ٱلۡمُسۡلِمِینَ',
    'ووصينا الانسان بوالديه احسانا حملته امه كرها ووضعته كرها وحمله وفصاله ثلاثون شهرا حتى اذا بلغ اشده وبلغ اربعين سنة قال رب اوزعني ان اشكر نعمتك التي انعمت علي وعلى والدي وان اعمل صالحا ترضاه واصلح لي في ذريتي اني تبت اليك واني من المسلمين',
    'وَوَصَّيۡنَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ بِو<rule class=madda_normal>ٰ</rule>لِدَيۡهِ إِحۡسَ<rule class=madda_normal>ـٰ</rule>نًا‌ۖ حَمَلَتۡهُ أُ<rule class=ghunnah>مّ</rule>ُهُ<rule class=madda_normal>ۥ</rule> كُرۡ<rule class=idgham_ghunnah>هًا</rule> <rule class=idgham_ghunnah>و</rule>َوَضَعَتۡهُ كُرۡ<rule class=idgham_ghunnah>هًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َحَمۡلُهُ<rule class=madda_normal>ۥ</rule> وَفِصَ<rule class=madda_normal>ـٰ</rule>لُهُ<rule class=madda_normal>ۥ</rule> ثَلَ<rule class=madda_normal>ـٰ</rule>ثُونَ شَهۡرًا‌ۚ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا بَلَغَ أَشُدَّهُ<rule class=madda_normal>ۥ</rule> وَبَلَغَ أَرۡبَعِينَ سَنَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ق</rule>َالَ رَبِّ أَوۡزِعۡن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡ أَشۡكُرَ نِعۡمَتَكَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡعَمۡتَ عَلَىَّ وَعَلَىٰ و<rule class=madda_normal>ٰ</rule>لِدَىَّ وَأَنۡ أَعۡمَلَ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ت</rule>َرۡضَ<rule class=madda_normal>ـٰ</rule>هُ وَأَصۡلِحۡ لِى فِى ذُرِّيَّت<rule class=madda_obligatory_monfasel>ِىٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>ِى تُ<rule class=qalaqah>بۡ</rule>تُ إِلَيۡكَ وَإِ<rule class=ghunnah>نّ</rule>ِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ١٥',
    15, 26, 6, 504, 439, 201, 'false'
  );
  
  -- Ayah 16 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4526,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ نَتَقَبَّلُ عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَیِّـَٔاتِهِمۡ فِیۤ أَصۡحَـٰبِ ٱلۡجَنَّةِۖ وَعۡدَ ٱلصِّدۡقِ ٱلَّذِی كَانُوا۟ یُوعَدُونَ',
    'اولئك الذين نتقبل عنهم احسن ما عملوا ونتجاوز عن سيئاتهم في اصحاب الجنة وعد الصدق الذي كانوا يوعدون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ نَتَقَبَّلُ عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُو<rule class=slnt>اۡ</rule> وَنَتَجَاوَزُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َيِّـَٔـاتِهِمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ‌ۖ وَعۡدَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّ<rule class=qalaqah>دۡ</rule>قِ <rule class=ham_wasl>ٱ</rule>لَّذِى كَانُو<rule class=slnt>اۡ</rule> يُوعَد<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 26, 6, 504, 439, 201, 'false'
  );
  
  -- Ayah 17 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4527,
    'وَٱلَّذِی قَالَ لِوَ ٰ⁠لِدَیۡهِ أُفࣲّ لَّكُمَاۤ أَتَعِدَانِنِیۤ أَنۡ أُخۡرَجَ وَقَدۡ خَلَتِ ٱلۡقُرُونُ مِن قَبۡلِی وَهُمَا یَسۡتَغِیثَانِ ٱللَّهَ وَیۡلَكَ ءَامِنۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ فَیَقُولُ مَا هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ',
    'والذي قال لوالديه اف لكما اتعدانني ان اخرج وقد خلت القرون من قبلي وهما يستغيثان الله ويلك امن ان وعد الله حق فيقول ما هذا الا اساطير الاولين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِى قَالَ لِو<rule class=madda_normal>ٰ</rule>لِدَيۡهِ أُ<rule class=idgham_wo_ghunnah>فٍّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُم<rule class=madda_obligatory_monfasel>َآ</rule> أَتَعِدَانِن<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَنۡ أُخۡرَجَ وَقَ<rule class=qalaqah>دۡ</rule> خَلَتِ <rule class=ham_wasl>ٱ</rule>لۡقُرُونُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِى وَهُمَا يَسۡتَغِيثَانِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَيۡلَكَ ءَامِنۡ إِ<rule class=ghunnah>نّ</rule>َ وَعۡدَ <rule class=ham_wasl>ٱ</rule>للَّهِ حَ<rule class=ikhafa>قٌّ</rule> <rule class=ikhafa>ف</rule>َيَقُولُ مَا هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 26, 6, 504, 439, 201, 'false'
  );
  
  -- Ayah 18 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4528,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ حَقَّ عَلَیۡهِمُ ٱلۡقَوۡلُ فِیۤ أُمَمࣲ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُوا۟ خَـٰسِرِینَ',
    'اولئك الذين حق عليهم القول في امم قد خلت من قبلهم من الجن والانس انهم كانوا خاسرين',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ حَقَّ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أُمَ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> خَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ِي</rule>نَ ١٨',
    18, 26, 6, 504, 439, 201, 'false'
  );
  
  -- Ayah 19 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4529,
    'وَلِكُلࣲّ دَرَجَـٰتࣱ مِّمَّا عَمِلُوا۟ۖ وَلِیُوَفِّیَهُمۡ أَعۡمَـٰلَهُمۡ وَهُمۡ لَا یُظۡلَمُونَ',
    'ولكل درجات مما عملوا وليوفيهم اعمالهم وهم لا يظلمون',
    'وَلِكُ<rule class=ikhafa>لٍّ</rule> <rule class=ikhafa>د</rule>َرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا عَمِلُو<rule class=slnt>اۡ‌ۖ</rule> وَلِيُوَفِّيَهُمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ وَهُمۡ لَا يُظۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 26, 6, 504, 439, 201, 'false'
  );
  
  -- Ayah 20 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4530,
    'وَیَوۡمَ یُعۡرَضُ ٱلَّذِینَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَیِّبَـٰتِكُمۡ فِی حَیَاتِكُمُ ٱلدُّنۡیَا وَٱسۡتَمۡتَعۡتُم بِهَا فَٱلۡیَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَسۡتَكۡبِرُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ',
    'ويوم يعرض الذين كفروا على النار اذهبتم طيباتكم في حياتكم الدنيا واستمتعتم بها فاليوم تجزون عذاب الهون بما كنتم تستكبرون في الارض بغير الحق وبما كنتم تفسقون',
    'وَيَوۡمَ يُعۡرَضُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ أَذۡهَ<rule class=qalaqah>بۡ</rule>تُمۡ طَيِّبَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ فِى حَيَاتِكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا وَ<rule class=ham_wasl>ٱ</rule>سۡتَمۡتَعۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا فَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ تُ<rule class=qalaqah>جۡ</rule>زَوۡنَ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡهُونِ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَسۡتَكۡبِرُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ بِغَيۡرِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَبِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَفۡسُق<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 26, 6, 504, 439, 201, 'false'
  );
  
  -- Ayah 21 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4531,
    '۞ وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَیۡنِ یَدَیۡهِ وَمِنۡ خَلۡفِهِۦۤ أَلَّا تَعۡبُدُوۤا۟ إِلَّا ٱللَّهَ إِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمٍ عَظِیمࣲ',
    'واذكر اخا عاد اذ انذر قومه بالاحقاف وقد خلت النذر من بين يديه ومن خلفه الا تعبدوا الا الله اني اخاف عليكم عذاب يوم عظيم',
    '۞وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرۡ أَخَا عَادٍ إِذۡ أَ<rule class=ikhafa>نذ</rule>َرَ قَوۡمَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡأَحۡقَافِ وَقَ<rule class=qalaqah>دۡ</rule> خَلَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُذُرُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَلَّا تَعۡبُد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهَ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ٢١',
    21, 26, 6, 505, 440, 202, 'false'
  );
  
  -- Ayah 22 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4532,
    'قَالُوۤا۟ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَاۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ',
    'قالوا اجئتنا لتافكنا عن الهتنا فاتنا بما تعدنا ان كنت من الصادقين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>َ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٢٢',
    22, 26, 6, 505, 440, 202, 'false'
  );
  
  -- Ayah 23 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4533,
    'قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّاۤ أُرۡسِلۡتُ بِهِۦ وَلَـٰكِنِّیۤ أَرَىٰكُمۡ قَوۡمࣰا تَجۡهَلُونَ',
    'قال انما العلم عند الله وابلغكم ما ارسلت به ولكني اراكم قوما تجهلون',
    'قَالَ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡعِلۡمُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَأُبَلِّغُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡتُ بِه<rule class=madda_normal>ِۦ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرَ<rule class=madda_normal>ٮٰ</rule>كُمۡ قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>هَل<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 26, 6, 505, 440, 202, 'false'
  );
  
  -- Ayah 24 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4534,
    'فَلَمَّا رَأَوۡهُ عَارِضࣰا مُّسۡتَقۡبِلَ أَوۡدِیَتِهِمۡ قَالُوا۟ هَـٰذَا عَارِضࣱ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِیحࣱ فِیهَا عَذَابٌ أَلِیمࣱ',
    'فلما راوه عارضا مستقبل اوديتهم قالوا هذا عارض ممطرنا بل هو ما استعجلتم به ريح فيها عذاب اليم',
    'فَلَ<rule class=ghunnah>مّ</rule>َا رَأَوۡهُ عَارِ<rule class=idgham_ghunnah>ضًا</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَ<rule class=qalaqah>قۡ</rule>بِلَ أَوۡدِيَتِهِمۡ قَالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا عَارِ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّمۡطِرُنَا‌ۚ بَلۡ هُوَ مَا <rule class=ham_wasl>ٱ</rule>سۡتَعۡجَلۡت<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۖ رِي<rule class=ikhafa>حٌ</rule> <rule class=ikhafa>ف</rule>ِيهَا عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٢٤',
    24, 26, 6, 505, 440, 202, 'false'
  );
  
  -- Ayah 25 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4535,
    'تُدَمِّرُ كُلَّ شَیۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُوا۟ لَا یُرَىٰۤ إِلَّا مَسَـٰكِنُهُمۡۚ كَذَ ٰ⁠لِكَ نَجۡزِی ٱلۡقَوۡمَ ٱلۡمُجۡرِمِینَ',
    'تدمر كل شيء بامر ربها فاصبحوا لا يرى الا مساكنهم كذلك نجزي القوم المجرمين',
    'تُدَ<rule class=ghunnah>مّ</rule>ِرُ كُلَّ شَىۡ<rule class=iqlab>ءِۭ</rule> <rule class=iqlab>ب</rule>ِأَمۡرِ رَبِّهَا فَأَصۡبَحُو<rule class=slnt>اۡ</rule> لَا يُرَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَّا مَسَ<rule class=madda_normal>ـٰ</rule>كِنُهُمۡ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 26, 6, 505, 440, 202, 'false'
  );
  
  -- Ayah 26 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4536,
    'وَلَقَدۡ مَكَّنَّـٰهُمۡ فِیمَاۤ إِن مَّكَّنَّـٰكُمۡ فِیهِ وَجَعَلۡنَا لَهُمۡ سَمۡعࣰا وَأَبۡصَـٰرࣰا وَأَفۡـِٔدَةࣰ فَمَاۤ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَاۤ أَبۡصَـٰرُهُمۡ وَلَاۤ أَفۡـِٔدَتُهُم مِّن شَیۡءٍ إِذۡ كَانُوا۟ یَجۡحَدُونَ بِـَٔایَـٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ',
    'ولقد مكناهم فيما ان مكناكم فيه وجعلنا لهم سمعا وابصارا وافئدة فما اغنى عنهم سمعهم ولا ابصارهم ولا افئدتهم من شيء اذ كانوا يجحدون بايات الله وحاق بهم ما كانوا به يستهزئون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> مَكَّ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هُمۡ فِيم<rule class=madda_obligatory_monfasel>َآ</rule> إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّكَّ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>كُمۡ فِيهِ وَجَعَلۡنَا لَهُمۡ سَمۡ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َأَفۡــِٔدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُهُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَفۡــِٔدَتُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ إِذۡ كَانُو<rule class=slnt>اۡ</rule> يَ<rule class=qalaqah>جۡ</rule>حَدُونَ بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَحَاقَ بِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَسۡتَهۡزِء<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 26, 6, 505, 440, 202, 'false'
  );
  
  -- Ayah 27 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4537,
    'وَلَقَدۡ أَهۡلَكۡنَا مَا حَوۡلَكُم مِّنَ ٱلۡقُرَىٰ وَصَرَّفۡنَا ٱلۡـَٔایَـٰتِ لَعَلَّهُمۡ یَرۡجِعُونَ',
    'ولقد اهلكنا ما حولكم من القرى وصرفنا الايات لعلهم يرجعون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَهۡلَكۡنَا مَا حَوۡلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ وَصَرَّفۡنَا <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لَعَلَّهُمۡ يَرۡجِع<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 26, 6, 505, 441, 202, 'false'
  );
  
  -- Ayah 28 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4538,
    'فَلَوۡلَا نَصَرَهُمُ ٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرۡبَانًا ءَالِهَةَۢۖ بَلۡ ضَلُّوا۟ عَنۡهُمۡۚ وَذَ ٰ⁠لِكَ إِفۡكُهُمۡ وَمَا كَانُوا۟ یَفۡتَرُونَ',
    'فلولا نصرهم الذين اتخذوا من دون الله قربانا الهة بل ضلوا عنهم وذلك افكهم وما كانوا يفترون',
    'فَلَوۡلَا نَصَرَهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّخَذُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ قُرۡبَانًا ءَالِهَ<rule class=iqlab>ةَۢ‌ۖ</rule> <rule class=iqlab>ب</rule>َلۡ ضَلُّو<rule class=slnt>اۡ</rule> عَنۡهُمۡ‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ إِفۡكُهُمۡ وَمَا كَانُو<rule class=slnt>اۡ</rule> يَفۡتَر<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 26, 6, 505, 441, 202, 'false'
  );
  
  -- Ayah 29 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4539,
    'وَإِذۡ صَرَفۡنَاۤ إِلَیۡكَ نَفَرࣰا مِّنَ ٱلۡجِنِّ یَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوۤا۟ أَنصِتُوا۟ۖ فَلَمَّا قُضِیَ وَلَّوۡا۟ إِلَىٰ قَوۡمِهِم مُّنذِرِینَ',
    'واذ صرفنا اليك نفرا من الجن يستمعون القران فلما حضروه قالوا انصتوا فلما قضي ولوا الى قومهم منذرين',
    'وَإِذۡ صَرَفۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكَ نَفَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ يَسۡتَمِعُونَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ فَلَ<rule class=ghunnah>مّ</rule>َا حَضَرُوهُ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نص</rule>ِتُو<rule class=slnt>اۡ‌ۖ</rule> فَلَ<rule class=ghunnah>مّ</rule>َا قُضِىَ وَلَّوۡ<rule class=slnt>اۡ</rule> إِلَىٰ قَوۡمِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=ikhafa>نذ</rule>ِر<rule class=madda_permissible>ِي</rule>نَ ٢٩',
    29, 26, 6, 506, 441, 202, 'false'
  );
  
  -- Ayah 30 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4540,
    'قَالُوا۟ یَـٰقَوۡمَنَاۤ إِنَّا سَمِعۡنَا كِتَـٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ یَهۡدِیۤ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِیقࣲ مُّسۡتَقِیمࣲ',
    'قالوا يا قومنا انا سمعنا كتابا انزل من بعد موسى مصدقا لما بين يديه يهدي الى الحق والى طريق مستقيم',
    'قَالُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_normal>ـٰ</rule>قَوۡمَن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا سَمِعۡنَا كِتَ<rule class=madda_normal>ـٰ</rule>بًا أُ<rule class=ikhafa>نز</rule>ِلَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مُوسَىٰ مُصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَيۡهِ يَهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَإِلَىٰ طَرِي<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٣٠',
    30, 26, 6, 506, 441, 202, 'false'
  );
  
  -- Ayah 31 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4541,
    'یَـٰقَوۡمَنَاۤ أَجِیبُوا۟ دَاعِیَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ یَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَیُجِرۡكُم مِّنۡ عَذَابٍ أَلِیمࣲ',
    'يا قومنا اجيبوا داعي الله وامنوا به يغفر لكم من ذنوبكم ويجركم من عذاب اليم',
    'يَ<rule class=madda_normal>ـٰ</rule>قَوۡمَن<rule class=madda_obligatory_monfasel>َآ</rule> أَجِيبُو<rule class=slnt>اۡ</rule> دَاعِىَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَءَامِنُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule> يَغۡفِرۡ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُنُوبِكُمۡ وَيُجِرۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٣١',
    31, 26, 6, 506, 441, 202, 'false'
  );
  
  -- Ayah 32 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4542,
    'وَمَن لَّا یُجِبۡ دَاعِیَ ٱللَّهِ فَلَیۡسَ بِمُعۡجِزࣲ فِی ٱلۡأَرۡضِ وَلَیۡسَ لَهُۥ مِن دُونِهِۦۤ أَوۡلِیَاۤءُۚ أُو۟لَـٰۤىِٕكَ فِی ضَلَـٰلࣲ مُّبِینٍ',
    'ومن لا يجب داعي الله فليس بمعجز في الارض وليس له من دونه اولياء اولئك في ضلال مبين',
    'وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُجِ<rule class=qalaqah>بۡ</rule> دَاعِىَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَلَيۡسَ بِمُعۡجِ<rule class=ikhafa>زٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَيۡسَ لَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٣٢',
    32, 26, 6, 506, 441, 202, 'false'
  );
  
  -- Ayah 33 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4543,
    'أَوَلَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَلَمۡ یَعۡیَ بِخَلۡقِهِنَّ بِقَـٰدِرٍ عَلَىٰۤ أَن یُحۡـِۧیَ ٱلۡمَوۡتَىٰۚ بَلَىٰۤۚ إِنَّهُۥ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'اولم يروا ان الله الذي خلق السماوات والارض ولم يعي بخلقهن بقادر على ان يحيي الموتى بلى انه على كل شيء قدير',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَلَمۡ يَعۡىَ بِخَلۡقِهِ<rule class=ghunnah>نّ</rule>َ بِقَ<rule class=madda_normal>ـٰ</rule>دِرٍ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحۡــِۧىَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ‌ۚ بَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٣٣',
    33, 26, 6, 506, 441, 202, 'false'
  );
  
  -- Ayah 34 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4544,
    'وَیَوۡمَ یُعۡرَضُ ٱلَّذِینَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَیۡسَ هَـٰذَا بِٱلۡحَقِّۖ قَالُوا۟ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ',
    'ويوم يعرض الذين كفروا على النار اليس هذا بالحق قالوا بلى وربنا قال فذوقوا العذاب بما كنتم تكفرون',
    'وَيَوۡمَ يُعۡرَضُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ أَلَيۡسَ هَ<rule class=madda_normal>ـٰ</rule>ذَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ قَالُو<rule class=slnt>اۡ</rule> بَلَىٰ وَرَبِّنَا‌ۚ قَالَ فَذُوقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ بِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 26, 6, 506, 441, 202, 'false'
  );
  
  -- Ayah 35 Surah Al-Ahqaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    46,
    4545,
    'فَٱصۡبِرۡ كَمَا صَبَرَ أُو۟لُوا۟ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ یَوۡمَ یَرَوۡنَ مَا یُوعَدُونَ لَمۡ یَلۡبَثُوۤا۟ إِلَّا سَاعَةࣰ مِّن نَّهَارِۭۚ بَلَـٰغࣱۚ فَهَلۡ یُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَـٰسِقُونَ',
    'فاصبر كما صبر اولو العزم من الرسل ولا تستعجل لهم كانهم يوم يرون ما يوعدون لم يلبثوا الا ساعة من نهار بلاغ فهل يهلك الا القوم الفاسقون',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ كَمَا صَبَرَ أُ<rule class=slnt>وۡ</rule>لُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعَزۡمِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡ‌ۚ كَأَ<rule class=ghunnah>نّ</rule>َهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَث<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا سَاعَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّهَا<rule class=iqlab>رِۭ‌ۚ</rule> <rule class=iqlab>ب</rule>َلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>غٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َهَلۡ يُهۡلَكُ إِلَّا <rule class=ham_wasl>ٱ</rule>لۡقَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 26, 6, 506, 441, 202, 'false'
  );
  

-- Surah Muhammad
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (47, 'سُورَةُ مُحَمَّدٍ', 'Muhammad', 'Muhammad', 'Medinan', 38);

  -- Ayah 1 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4546,
    'ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ أَضَلَّ أَعۡمَـٰلَهُمۡ',
    'الذين كفروا وصدوا عن سبيل الله اضل اعمالهم',
    'ٱلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَصَدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَضَلَّ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ ١',
    1, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 2 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4547,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدࣲ وَهُوَ ٱلۡحَقُّ مِن رَّبِّهِمۡ كَفَّرَ عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَأَصۡلَحَ بَالَهُمۡ',
    'والذين امنوا وعملوا الصالحات وامنوا بما نزل على محمد وهو الحق من ربهم كفر عنهم سيئاتهم واصلح بالهم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَءَامَنُو<rule class=slnt>اۡ</rule> بِمَا نُزِّلَ عَلَىٰ مُحَ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ‌ۙ كَفَّرَ عَنۡهُمۡ سَيِّـَٔـاتِهِمۡ وَأَصۡلَحَ بَالَهُمۡ ٢',
    2, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 3 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4548,
    'ذَ ٰ⁠لِكَ بِأَنَّ ٱلَّذِینَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلۡبَـٰطِلَ وَأَنَّ ٱلَّذِینَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلۡحَقَّ مِن رَّبِّهِمۡۚ كَذَ ٰ⁠لِكَ یَضۡرِبُ ٱللَّهُ لِلنَّاسِ أَمۡثَـٰلَهُمۡ',
    'ذلك بان الذين كفروا اتبعوا الباطل وان الذين امنوا اتبعوا الحق من ربهم كذلك يضرب الله للناس امثالهم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡبَ<rule class=madda_normal>ـٰ</rule>طِلَ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡحَقَّ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ يَضۡرِبُ <rule class=ham_wasl>ٱ</rule>للَّهُ لِل<rule class=ghunnah>نّ</rule>َاسِ أَمۡثَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ ٣',
    3, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 4 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4549,
    'فَإِذَا لَقِیتُمُ ٱلَّذِینَ كَفَرُوا۟ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰۤ إِذَاۤ أَثۡخَنتُمُوهُمۡ فَشُدُّوا۟ ٱلۡوَثَاقَ فَإِمَّا مَنَّۢا بَعۡدُ وَإِمَّا فِدَاۤءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ ذَ ٰ⁠لِكَۖ وَلَوۡ یَشَاۤءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَـٰكِن لِّیَبۡلُوَا۟ بَعۡضَكُم بِبَعۡضࣲۗ وَٱلَّذِینَ قُتِلُوا۟ فِی سَبِیلِ ٱللَّهِ فَلَن یُضِلَّ أَعۡمَـٰلَهُمۡ',
    'فاذا لقيتم الذين كفروا فضرب الرقاب حتى اذا اثخنتموهم فشدوا الوثاق فاما منا بعد واما فداء حتى تضع الحرب اوزارها ذلك ولو يشاء الله لانتصر منهم ولكن ليبلو بعضكم ببعض والذين قتلوا في سبيل الله فلن يضل اعمالهم',
    'فَإِذَا لَقِيتُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فَضَرۡبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّقَابِ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أَثۡخَ<rule class=ikhafa>نت</rule>ُمُوهُمۡ فَشُدُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡوَثَاقَ فَإِ<rule class=ghunnah>مّ</rule>َا مَ<rule class=ghunnah>نّ</rule><rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َعۡدُ وَإِ<rule class=ghunnah>مّ</rule>َا فِد<rule class=madda_obligatory_mottasel>َا</rule>ٓءً حَتَّىٰ تَضَعَ <rule class=ham_wasl>ٱ</rule>لۡحَرۡبُ أَوۡزَارَهَا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ وَلَوۡ يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>للَّهُ لَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َصَرَ مِنۡهُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيَ<rule class=qalaqah>بۡ</rule>لُوَ<rule class=slnt>اۡ</rule> بَعۡضَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَعۡ<rule class=idgham_ghunnah>ضٍ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ قُتِلُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُضِلَّ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ ٤',
    4, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 5 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4550,
    'سَیَهۡدِیهِمۡ وَیُصۡلِحُ بَالَهُمۡ',
    'سيهديهم ويصلح بالهم',
    'سَيَهۡدِيهِمۡ وَيُصۡلِحُ بَالَهُمۡ ٥',
    5, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 6 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4551,
    'وَیُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ',
    'ويدخلهم الجنة عرفها لهم',
    'وَيُ<rule class=qalaqah>دۡ</rule>خِلُهُمُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةَ عَرَّفَهَا لَهُمۡ ٦',
    6, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 7 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4552,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن تَنصُرُوا۟ ٱللَّهَ یَنصُرۡكُمۡ وَیُثَبِّتۡ أَقۡدَامَكُمۡ',
    'يا ايها الذين امنوا ان تنصروا الله ينصركم ويثبت اقدامكم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نص</rule>ُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=ikhafa>نص</rule>ُرۡكُمۡ وَيُثَبِّتۡ أَ<rule class=qalaqah>قۡ</rule>دَامَكُمۡ ٧',
    7, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 8 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4553,
    'وَٱلَّذِینَ كَفَرُوا۟ فَتَعۡسࣰا لَّهُمۡ وَأَضَلَّ أَعۡمَـٰلَهُمۡ',
    'والذين كفروا فتعسا لهم واضل اعمالهم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فَتَعۡ<rule class=idgham_wo_ghunnah>سًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ وَأَضَلَّ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ ٨',
    8, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 9 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4554,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمۡ كَرِهُوا۟ مَاۤ أَنزَلَ ٱللَّهُ فَأَحۡبَطَ أَعۡمَـٰلَهُمۡ',
    'ذلك بانهم كرهوا ما انزل الله فاحبط اعمالهم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ كَرِهُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ فَأَحۡبَطَ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ ٩',
    9, 26, 6, 507, 442, 202, 'false'
  );
  
  -- Ayah 10 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4555,
    '۞ أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَیۡهِمۡۖ وَلِلۡكَـٰفِرِینَ أَمۡثَـٰلُهَا',
    'افلم يسيروا في الارض فينظروا كيف كان عاقبة الذين من قبلهم دمر الله عليهم وللكافرين امثالها',
    '۞أَفَلَمۡ يَسِيرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ فَيَ<rule class=ikhafa>نظ</rule>ُرُو<rule class=slnt>اۡ</rule> كَيۡفَ كَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ دَ<rule class=ghunnah>مّ</rule>َرَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمۡ‌ۖ وَلِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ أَمۡثَ<rule class=madda_normal>ـٰ</rule>لُهَا ١٠',
    10, 26, 6, 507, 442, 203, 'false'
  );
  
  -- Ayah 11 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4556,
    'ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِینَ ءَامَنُوا۟ وَأَنَّ ٱلۡكَـٰفِرِینَ لَا مَوۡلَىٰ لَهُمۡ',
    'ذلك بان الله مولى الذين امنوا وان الكافرين لا مولى لهم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ مَوۡلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ لَا مَوۡلَىٰ لَهُمۡ ١١',
    11, 26, 6, 507, 442, 203, 'false'
  );
  
  -- Ayah 12 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4557,
    'إِنَّ ٱللَّهَ یُدۡخِلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ وَٱلَّذِینَ كَفَرُوا۟ یَتَمَتَّعُونَ وَیَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَـٰمُ وَٱلنَّارُ مَثۡوࣰى لَّهُمۡ',
    'ان الله يدخل الذين امنوا وعملوا الصالحات جنات تجري من تحتها الانهار والذين كفروا يتمتعون وياكلون كما تاكل الانعام والنار مثوى لهم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُ<rule class=qalaqah>دۡ</rule>خِلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ <rule class=ham_wasl>ٱ</rule>لۡأَنۡعَ<rule class=madda_normal>ـٰ</rule>مُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ مَثۡ<rule class=idgham_wo_ghunnah>وًى</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ ١٢',
    12, 26, 6, 508, 443, 203, 'false'
  );
  
  -- Ayah 13 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4558,
    'وَكَأَیِّن مِّن قَرۡیَةٍ هِیَ أَشَدُّ قُوَّةࣰ مِّن قَرۡیَتِكَ ٱلَّتِیۤ أَخۡرَجَتۡكَ أَهۡلَكۡنَـٰهُمۡ فَلَا نَاصِرَ لَهُمۡ',
    'وكاين من قرية هي اشد قوة من قريتك التي اخرجتك اهلكناهم فلا ناصر لهم',
    'وَكَأَيّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ هِىَ أَشَدُّ قُوَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَتِكَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخۡرَجَتۡكَ أَهۡلَكۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فَلَا نَاصِرَ لَهُمۡ ١٣',
    13, 26, 6, 508, 443, 203, 'false'
  );
  
  -- Ayah 14 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4559,
    'أَفَمَن كَانَ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّهِۦ كَمَن زُیِّنَ لَهُۥ سُوۤءُ عَمَلِهِۦ وَٱتَّبَعُوۤا۟ أَهۡوَاۤءَهُم',
    'افمن كان على بينة من ربه كمن زين له سوء عمله واتبعوا اهواءهم',
    'أَفَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ عَلَىٰ بَيِّنَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule> كَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>ُيِّنَ لَهُ<rule class=madda_normal>ۥ</rule> س<rule class=madda_obligatory_mottasel>ُو</rule>ٓءُ عَمَلِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّبَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُم ١٤',
    14, 26, 6, 508, 443, 203, 'false'
  );
  
  -- Ayah 15 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4560,
    'مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِی وُعِدَ ٱلۡمُتَّقُونَۖ فِیهَاۤ أَنۡهَـٰرࣱ مِّن مَّاۤءٍ غَیۡرِ ءَاسِنࣲ وَأَنۡهَـٰرࣱ مِّن لَّبَنࣲ لَّمۡ یَتَغَیَّرۡ طَعۡمُهُۥ وَأَنۡهَـٰرࣱ مِّنۡ خَمۡرࣲ لَّذَّةࣲ لِّلشَّـٰرِبِینَ وَأَنۡهَـٰرࣱ مِّنۡ عَسَلࣲ مُّصَفࣰّىۖ وَلَهُمۡ فِیهَا مِن كُلِّ ٱلثَّمَرَ ٰ⁠تِ وَمَغۡفِرَةࣱ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَـٰلِدࣱ فِی ٱلنَّارِ وَسُقُوا۟ مَاۤءً حَمِیمࣰا فَقَطَّعَ أَمۡعَاۤءَهُمۡ',
    'مثل الجنة التي وعد المتقون فيها انهار من ماء غير اسن وانهار من لبن لم يتغير طعمه وانهار من خمر لذة للشاربين وانهار من عسل مصفى ولهم فيها من كل الثمرات ومغفرة من ربهم كمن هو خالد في النار وسقوا ماء حميما فقطع امعاءهم',
    'مَّثَلُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ <rule class=ham_wasl>ٱ</rule>لَّتِى وُعِدَ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقُونَ‌ۖ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَنۡهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ غَيۡرِ ءَاسِ<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَنۡهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّبَ<rule class=idgham_wo_ghunnah>نٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَتَغَيَّرۡ طَعۡمُهُ<rule class=madda_normal>ۥ</rule> وَأَنۡهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ خَمۡ<rule class=idgham_wo_ghunnah>رٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّذَّ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلشَّ<rule class=madda_normal>ـٰ</rule>رِبِينَ وَأَنۡهَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عَسَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّصَف<rule class=idgham_ghunnah>ًّى‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَهُمۡ فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّمَر<rule class=madda_normal>ٰ</rule>تِ وَمَغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ‌ۖ كَمَنۡ هُوَ خَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ وَسُقُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_mottasel>َا</rule>ٓءً حَمِي<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َقَطَّعَ أَمۡع<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ ١٥',
    15, 26, 6, 508, 443, 203, 'false'
  );
  
  -- Ayah 16 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4561,
    'وَمِنۡهُم مَّن یَسۡتَمِعُ إِلَیۡكَ حَتَّىٰۤ إِذَا خَرَجُوا۟ مِنۡ عِندِكَ قَالُوا۟ لِلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ مَاذَا قَالَ ءَانِفًاۚ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَٱتَّبَعُوۤا۟ أَهۡوَاۤءَهُمۡ',
    'ومنهم من يستمع اليك حتى اذا خرجوا من عندك قالوا للذين اوتوا العلم ماذا قال انفا اولئك الذين طبع الله على قلوبهم واتبعوا اهواءهم',
    'وَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَمِعُ إِلَيۡكَ حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا خَرَجُو<rule class=slnt>اۡ</rule> مِنۡ عِ<rule class=ikhafa>ند</rule>ِكَ قَالُو<rule class=slnt>اۡ</rule> لِلَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ مَاذَا قَالَ ءَانِفًا‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ طَبَعَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ قُلُوبِهِمۡ وَ<rule class=ham_wasl>ٱ</rule>تَّبَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ ١٦',
    16, 26, 6, 508, 443, 203, 'false'
  );
  
  -- Ayah 17 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4562,
    'وَٱلَّذِینَ ٱهۡتَدَوۡا۟ زَادَهُمۡ هُدࣰى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ',
    'والذين اهتدوا زادهم هدى واتاهم تقواهم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>هۡتَدَوۡ<rule class=slnt>اۡ</rule> زَادَهُمۡ هُ<rule class=idgham_ghunnah>دًى</rule> <rule class=idgham_ghunnah>و</rule>َءَاتَ<rule class=madda_normal>ـٰ</rule>هُمۡ تَ<rule class=qalaqah>قۡ</rule>وَ<rule class=madda_normal>ٮٰ</rule>هُمۡ ١٧',
    17, 26, 6, 508, 443, 203, 'false'
  );
  
  -- Ayah 18 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4563,
    'فَهَلۡ یَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِیَهُم بَغۡتَةࣰۖ فَقَدۡ جَاۤءَ أَشۡرَاطُهَاۚ فَأَنَّىٰ لَهُمۡ إِذَا جَاۤءَتۡهُمۡ ذِكۡرَىٰهُمۡ',
    'فهل ينظرون الا الساعة ان تاتيهم بغتة فقد جاء اشراطها فانى لهم اذا جاءتهم ذكراهم',
    'فَهَلۡ يَ<rule class=ikhafa>نظ</rule>ُرُونَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َأۡتِيَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َغۡتَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ف</rule>َقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَشۡرَاطُهَا‌ۚ فَأَ<rule class=ghunnah>نّ</rule>َىٰ لَهُمۡ إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمۡ ذِكۡرَ<rule class=madda_normal>ٮٰ</rule>هُمۡ ١٨',
    18, 26, 6, 508, 443, 203, 'false'
  );
  
  -- Ayah 19 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4564,
    'فَٱعۡلَمۡ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِۗ وَٱللَّهُ یَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَىٰكُمۡ',
    'فاعلم انه لا اله الا الله واستغفر لذنبك وللمؤمنين والمؤمنات والله يعلم متقلبكم ومثواكم',
    'فَ<rule class=ham_wasl>ٱ</rule>عۡلَمۡ أَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا <rule class=ham_wasl>ٱ</rule>للَّهُ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرۡ لِذَ<rule class=iqlab>نۢب</rule>ِكَ وَلِلۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَ<rule class=madda_normal>ٮٰ</rule>كُمۡ ١٩',
    19, 26, 6, 508, 443, 203, 'false'
  );
  
  -- Ayah 20 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4565,
    'وَیَقُولُ ٱلَّذِینَ ءَامَنُوا۟ لَوۡلَا نُزِّلَتۡ سُورَةࣱۖ فَإِذَاۤ أُنزِلَتۡ سُورَةࣱ مُّحۡكَمَةࣱ وَذُكِرَ فِیهَا ٱلۡقِتَالُ رَأَیۡتَ ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ یَنظُرُونَ إِلَیۡكَ نَظَرَ ٱلۡمَغۡشِیِّ عَلَیۡهِ مِنَ ٱلۡمَوۡتِۖ فَأَوۡلَىٰ لَهُمۡ',
    'ويقول الذين امنوا لولا نزلت سورة فاذا انزلت سورة محكمة وذكر فيها القتال رايت الذين في قلوبهم مرض ينظرون اليك نظر المغشي عليه من الموت فاولى لهم',
    'وَيَقُولُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَوۡلَا نُزِّلَتۡ سُورَ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َإِذ<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=ikhafa>نز</rule>ِلَتۡ سُورَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّحۡكَمَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َذُكِرَ فِيهَا <rule class=ham_wasl>ٱ</rule>لۡقِتَالُ‌ۙ رَأَيۡتَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَ<rule class=idgham_ghunnah>ضٌ</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نظ</rule>ُرُونَ إِلَيۡكَ نَظَرَ <rule class=ham_wasl>ٱ</rule>لۡمَغۡشِىِّ عَلَيۡهِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ‌ۖ فَأَوۡلَىٰ لَهُمۡ ٢٠',
    20, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 21 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4566,
    'طَاعَةࣱ وَقَوۡلࣱ مَّعۡرُوفࣱۚ فَإِذَا عَزَمَ ٱلۡأَمۡرُ فَلَوۡ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَیۡرࣰا لَّهُمۡ',
    'طاعة وقول معروف فاذا عزم الامر فلو صدقوا الله لكان خيرا لهم',
    'طَاعَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َقَوۡ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>َّعۡرُو<rule class=ikhafa>فٌ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِذَا عَزَمَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ فَلَوۡ صَدَقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ لَكَانَ خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ ٢١',
    21, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 22 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4567,
    'فَهَلۡ عَسَیۡتُمۡ إِن تَوَلَّیۡتُمۡ أَن تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ وَتُقَطِّعُوۤا۟ أَرۡحَامَكُمۡ',
    'فهل عسيتم ان توليتم ان تفسدوا في الارض وتقطعوا ارحامكم',
    'فَهَلۡ عَسَيۡتُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّيۡتُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُفۡسِدُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَتُقَطِّع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَرۡحَامَكُمۡ ٢٢',
    22, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 23 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4568,
    'أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰۤ أَبۡصَـٰرَهُمۡ',
    'اولئك الذين لعنهم الله فاصمهم واعمى ابصارهم',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَعَنَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ فَأَصَ<rule class=ghunnah>مّ</rule>َهُمۡ وَأَعۡمَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَهُمۡ ٢٣',
    23, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 24 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4569,
    'أَفَلَا یَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَاۤ',
    'افلا يتدبرون القران ام على قلوب اقفالها',
    'أَفَلَا يَتَدَبَّرُونَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَ<rule class=qalaqah>قۡ</rule>فَالُهَآ ٢٤',
    24, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 25 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4570,
    'إِنَّ ٱلَّذِینَ ٱرۡتَدُّوا۟ عَلَىٰۤ أَدۡبَـٰرِهِم مِّنۢ بَعۡدِ مَا تَبَیَّنَ لَهُمُ ٱلۡهُدَى ٱلشَّیۡطَـٰنُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ لَهُمۡ',
    'ان الذين ارتدوا على ادبارهم من بعد ما تبين لهم الهدى الشيطان سول لهم واملى لهم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>رۡتَدُّو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا تَبَيَّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡهُدَى‌ۙ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ لَهُمۡ ٢٥',
    25, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 26 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4571,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَالُوا۟ لِلَّذِینَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِیعُكُمۡ فِی بَعۡضِ ٱلۡأَمۡرِۖ وَٱللَّهُ یَعۡلَمُ إِسۡرَارَهُمۡ',
    'ذلك بانهم قالوا للذين كرهوا ما نزل الله سنطيعكم في بعض الامر والله يعلم اسرارهم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَالُو<rule class=slnt>اۡ</rule> لِلَّذِينَ كَرِهُو<rule class=slnt>اۡ</rule> مَا نَزَّلَ <rule class=ham_wasl>ٱ</rule>للَّهُ سَنُطِيعُكُمۡ فِى بَعۡضِ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ إِسۡرَارَهُمۡ ٢٦',
    26, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 27 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4572,
    'فَكَیۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَـٰۤىِٕكَةُ یَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَـٰرَهُمۡ',
    'فكيف اذا توفتهم الملائكة يضربون وجوههم وادبارهم',
    'فَكَيۡفَ إِذَا تَوَفَّتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رَهُمۡ ٢٧',
    27, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 28 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4573,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَاۤ أَسۡخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضۡوَ ٰ⁠نَهُۥ فَأَحۡبَطَ أَعۡمَـٰلَهُمۡ',
    'ذلك بانهم اتبعوا ما اسخط الله وكرهوا رضوانه فاحبط اعمالهم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمُ <rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡخَطَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَكَرِهُو<rule class=slnt>اۡ</rule> رِضۡو<rule class=madda_normal>ٰ</rule>نَهُ<rule class=madda_normal>ۥ</rule> فَأَحۡبَطَ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ ٢٨',
    28, 26, 6, 509, 444, 203, 'false'
  );
  
  -- Ayah 29 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4574,
    'أَمۡ حَسِبَ ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضٌ أَن لَّن یُخۡرِجَ ٱللَّهُ أَضۡغَـٰنَهُمۡ',
    'ام حسب الذين في قلوبهم مرض ان لن يخرج الله اضغانهم',
    'أَمۡ حَسِبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ فِى قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّرَضٌ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُخۡرِجَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَضۡغَ<rule class=madda_normal>ـٰ</rule>نَهُمۡ ٢٩',
    29, 26, 6, 509, 445, 203, 'false'
  );
  
  -- Ayah 30 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4575,
    'وَلَوۡ نَشَاۤءُ لَأَرَیۡنَـٰكَهُمۡ فَلَعَرَفۡتَهُم بِسِیمَـٰهُمۡۚ وَلَتَعۡرِفَنَّهُمۡ فِی لَحۡنِ ٱلۡقَوۡلِۚ وَٱللَّهُ یَعۡلَمُ أَعۡمَـٰلَكُمۡ',
    'ولو نشاء لاريناكهم فلعرفتهم بسيماهم ولتعرفنهم في لحن القول والله يعلم اعمالكم',
    'وَلَوۡ نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لَأَرَيۡنَ<rule class=madda_normal>ـٰ</rule>كَهُمۡ فَلَعَرَفۡتَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسِيمَ<rule class=madda_normal>ـٰ</rule>هُمۡ‌ۚ وَلَتَعۡرِفَ<rule class=ghunnah>نّ</rule>َهُمۡ فِى لَحۡنِ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَكُمۡ ٣٠',
    30, 26, 6, 510, 445, 203, 'false'
  );
  
  -- Ayah 31 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4576,
    'وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَـٰهِدِینَ مِنكُمۡ وَٱلصَّـٰبِرِینَ وَنَبۡلُوَا۟ أَخۡبَارَكُمۡ',
    'ولنبلونكم حتى نعلم المجاهدين منكم والصابرين ونبلو اخباركم',
    'وَلَنَ<rule class=qalaqah>بۡ</rule>لُوَ<rule class=ghunnah>نّ</rule>َكُمۡ حَتَّىٰ نَعۡلَمَ <rule class=ham_wasl>ٱ</rule>لۡمُجَ<rule class=madda_normal>ـٰ</rule>هِدِينَ مِ<rule class=ikhafa>نك</rule>ُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>بِرِينَ وَنَ<rule class=qalaqah>بۡ</rule>لُو<rule class=madda_obligatory_monfasel>َ<rule class=slnt>اۡ</rule></rule> أَخۡبَارَكُمۡ ٣١',
    31, 26, 6, 510, 445, 203, 'false'
  );
  
  -- Ayah 32 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4577,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ وَشَاۤقُّوا۟ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَیَّنَ لَهُمُ ٱلۡهُدَىٰ لَن یَضُرُّوا۟ ٱللَّهَ شَیۡـࣰٔا وَسَیُحۡبِطُ أَعۡمَـٰلَهُمۡ',
    'ان الذين كفروا وصدوا عن سبيل الله وشاقوا الرسول من بعد ما تبين لهم الهدى لن يضروا الله شيئا وسيحبط اعمالهم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَصَدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَش<rule class=madda_necessary>َا</rule>ٓقُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا تَبَيَّنَ لَهُمُ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضُرُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َسَيُحۡبِطُ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ ٣٢',
    32, 26, 6, 510, 445, 203, 'false'
  );
  
  -- Ayah 33 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4578,
    '۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَ وَلَا تُبۡطِلُوۤا۟ أَعۡمَـٰلَكُمۡ',
    'يا ايها الذين امنوا اطيعوا الله واطيعوا الرسول ولا تبطلوا اعمالكم',
    '۞يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ وَلَا تُ<rule class=qalaqah>بۡ</rule>طِل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَكُمۡ ٣٣',
    33, 26, 6, 510, 445, 204, 'false'
  );
  
  -- Ayah 34 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4579,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمۡ كُفَّارࣱ فَلَن یَغۡفِرَ ٱللَّهُ لَهُمۡ',
    'ان الذين كفروا وصدوا عن سبيل الله ثم ماتوا وهم كفار فلن يغفر الله لهم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَصَدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ ثُ<rule class=ghunnah>مّ</rule>َ مَاتُو<rule class=slnt>اۡ</rule> وَهُمۡ كُفَّا<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغۡفِرَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُمۡ ٣٤',
    34, 26, 6, 510, 445, 204, 'false'
  );
  
  -- Ayah 35 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4580,
    'فَلَا تَهِنُوا۟ وَتَدۡعُوۤا۟ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ وَلَن یَتِرَكُمۡ أَعۡمَـٰلَكُمۡ',
    'فلا تهنوا وتدعوا الى السلم وانتم الاعلون والله معكم ولن يتركم اعمالكم',
    'فَلَا تَهِنُو<rule class=slnt>اۡ</rule> وَتَ<rule class=qalaqah>دۡ</rule>ع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلۡمِ وَأَ<rule class=ikhafa>نت</rule>ُمُ <rule class=ham_wasl>ٱ</rule>لۡأَعۡلَوۡنَ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ مَعَكُمۡ وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتِرَكُمۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَكُمۡ ٣٥',
    35, 26, 6, 510, 445, 204, 'false'
  );
  
  -- Ayah 36 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4581,
    'إِنَّمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَا لَعِبࣱ وَلَهۡوࣱۚ وَإِن تُؤۡمِنُوا۟ وَتَتَّقُوا۟ یُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا یَسۡـَٔلۡكُمۡ أَمۡوَ ٰ⁠لَكُمۡ',
    'انما الحياة الدنيا لعب ولهو وان تؤمنوا وتتقوا يؤتكم اجوركم ولا يسالكم اموالكم',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا لَعِ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَهۡ<rule class=idgham_ghunnah>وٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُؤۡمِنُو<rule class=slnt>اۡ</rule> وَتَتَّقُو<rule class=slnt>اۡ</rule> يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡــَٔلۡكُمۡ أَمۡو<rule class=madda_normal>ٰ</rule>لَكُمۡ ٣٦',
    36, 26, 6, 510, 445, 204, 'false'
  );
  
  -- Ayah 37 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4582,
    'إِن یَسۡـَٔلۡكُمُوهَا فَیُحۡفِكُمۡ تَبۡخَلُوا۟ وَیُخۡرِجۡ أَضۡغَـٰنَكُمۡ',
    'ان يسالكموها فيحفكم تبخلوا ويخرج اضغانكم',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡــَٔلۡكُمُوهَا فَيُحۡفِكُمۡ تَ<rule class=qalaqah>بۡ</rule>خَلُو<rule class=slnt>اۡ</rule> وَيُخۡرِ<rule class=qalaqah>جۡ</rule> أَضۡغَ<rule class=madda_normal>ـٰ</rule>نَكُمۡ ٣٧',
    37, 26, 6, 510, 445, 204, 'false'
  );
  
  -- Ayah 38 Surah Muhammad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    47,
    4583,
    'هَـٰۤأَنتُمۡ هَـٰۤؤُلَاۤءِ تُدۡعَوۡنَ لِتُنفِقُوا۟ فِی سَبِیلِ ٱللَّهِ فَمِنكُم مَّن یَبۡخَلُۖ وَمَن یَبۡخَلۡ فَإِنَّمَا یَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِیُّ وَأَنتُمُ ٱلۡفُقَرَاۤءُۚ وَإِن تَتَوَلَّوۡا۟ یَسۡتَبۡدِلۡ قَوۡمًا غَیۡرَكُمۡ ثُمَّ لَا یَكُونُوۤا۟ أَمۡثَـٰلَكُم',
    'ها انتم هؤلاء تدعون لتنفقوا في سبيل الله فمنكم من يبخل ومن يبخل فانما يبخل عن نفسه والله الغني وانتم الفقراء وان تتولوا يستبدل قوما غيركم ثم لا يكونوا امثالكم',
    'هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَ<rule class=ikhafa>نت</rule>ُمۡ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ تُ<rule class=qalaqah>دۡ</rule>عَوۡنَ لِتُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَمِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>خَلُ‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>خَلۡ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَ<rule class=qalaqah>بۡ</rule>خَلُ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡغَنِىُّ وَأَ<rule class=ikhafa>نت</rule>ُمُ <rule class=ham_wasl>ٱ</rule>لۡفُقَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَوَلَّوۡ<rule class=slnt>اۡ</rule> يَسۡتَ<rule class=qalaqah>بۡ</rule>دِلۡ قَوۡمًا غَيۡرَكُمۡ ثُ<rule class=ghunnah>مّ</rule>َ لَا يَكُون<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَمۡثَ<rule class=madda_normal>ـٰ</rule>لَكُم ٣٨',
    38, 26, 6, 510, 445, 204, 'false'
  );
  

-- Surah Al-Fath
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (48, 'سُورَةُ الفَتۡحِ', 'Al-Fath', 'The Victory', 'Medinan', 29);

  -- Ayah 1 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4584,
    'إِنَّا فَتَحۡنَا لَكَ فَتۡحࣰا مُّبِینࣰا',
    'انا فتحنا لك فتحا مبينا',
    'إِ<rule class=ghunnah>نّ</rule>َا فَتَحۡنَا لَكَ فَتۡ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>م</rule>ُّبِينًا ١',
    1, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 2 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4585,
    'لِّیَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَیُتِمَّ نِعۡمَتَهُۥ عَلَیۡكَ وَیَهۡدِیَكَ صِرَ ٰ⁠طࣰا مُّسۡتَقِیمࣰا',
    'ليغفر لك الله ما تقدم من ذنبك وما تاخر ويتم نعمته عليك ويهديك صراطا مستقيما',
    'لِّيَغۡفِرَ لَكَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَا تَقَدَّمَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َ<rule class=iqlab>نۢب</rule>ِكَ وَمَا تَأَخَّرَ وَيُتِ<rule class=ghunnah>مّ</rule>َ نِعۡمَتَهُ<rule class=madda_normal>ۥ</rule> عَلَيۡكَ وَيَهۡدِيَكَ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طًا</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقِيمًا ٢',
    2, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 3 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4586,
    'وَیَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِیزًا',
    'وينصرك الله نصرا عزيزا',
    'وَيَ<rule class=ikhafa>نص</rule>ُرَكَ <rule class=ham_wasl>ٱ</rule>للَّهُ نَصۡرًا عَزِيزًا ٣',
    3, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 4 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4587,
    'هُوَ ٱلَّذِیۤ أَنزَلَ ٱلسَّكِینَةَ فِی قُلُوبِ ٱلۡمُؤۡمِنِینَ لِیَزۡدَادُوۤا۟ إِیمَـٰنࣰا مَّعَ إِیمَـٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا',
    'هو الذي انزل السكينة في قلوب المؤمنين ليزدادوا ايمانا مع ايمانهم ولله جنود السماوات والارض وكان الله عليما حكيما',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّكِينَةَ فِى قُلُوبِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ لِيَزۡدَاد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِيمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>م</rule>َّعَ إِيمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ‌ۗ وَلِلَّهِ جُنُودُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمًا حَكِيمًا ٤',
    4, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 5 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4588,
    'لِّیُدۡخِلَ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا وَیُكَفِّرَ عَنۡهُمۡ سَیِّـَٔاتِهِمۡۚ وَكَانَ ذَ ٰ⁠لِكَ عِندَ ٱللَّهِ فَوۡزًا عَظِیمࣰا',
    'ليدخل المؤمنين والمؤمنات جنات تجري من تحتها الانهار خالدين فيها ويكفر عنهم سيئاتهم وكان ذلك عند الله فوزا عظيما',
    'لِّيُ<rule class=qalaqah>دۡ</rule>خِلَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا وَيُكَفِّرَ عَنۡهُمۡ سَيِّـَٔـاتِهِمۡ‌ۚ وَكَانَ ذ<rule class=madda_normal>ٰ</rule>لِكَ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ فَوۡزًا عَظِيمًا ٥',
    5, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 6 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4589,
    'وَیُعَذِّبَ ٱلۡمُنَـٰفِقِینَ وَٱلۡمُنَـٰفِقَـٰتِ وَٱلۡمُشۡرِكِینَ وَٱلۡمُشۡرِكَـٰتِ ٱلظَّاۤنِّینَ بِٱللَّهِ ظَنَّ ٱلسَّوۡءِۚ عَلَیۡهِمۡ دَاۤىِٕرَةُ ٱلسَّوۡءِۖ وَغَضِبَ ٱللَّهُ عَلَیۡهِمۡ وَلَعَنَهُمۡ وَأَعَدَّ لَهُمۡ جَهَنَّمَۖ وَسَاۤءَتۡ مَصِیرࣰا',
    'ويعذب المنافقين والمنافقات والمشركين والمشركات الظانين بالله ظن السوء عليهم دائرة السوء وغضب الله عليهم ولعنهم واعد لهم جهنم وساءت مصيرا',
    'وَيُعَذِّبَ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقَ<rule class=madda_normal>ـٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظّ<rule class=madda_necessary>َا</rule>ٓ<rule class=ghunnah>نّ</rule>ِينَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ ظَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّوۡءِ‌ۚ عَلَيۡهِمۡ د<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرَةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّوۡءِ‌ۖ وَغَضِبَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمۡ وَلَعَنَهُمۡ وَأَعَدَّ لَهُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۖ وَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ مَصِيرًا ٦',
    6, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 7 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4590,
    'وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَزِیزًا حَكِیمًا',
    'ولله جنود السماوات والارض وكان الله عزيزا حكيما',
    'وَلِلَّهِ جُنُودُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزًا حَكِيمًا ٧',
    7, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 8 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4591,
    'إِنَّاۤ أَرۡسَلۡنَـٰكَ شَـٰهِدࣰا وَمُبَشِّرࣰا وَنَذِیرࣰا',
    'انا ارسلناك شاهدا ومبشرا ونذيرا',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>كَ شَ<rule class=madda_normal>ـٰ</rule>هِ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َمُبَشِّ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َنَذِيرًا ٨',
    8, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 9 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4592,
    'لِّتُؤۡمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ وَتُسَبِّحُوهُ بُكۡرَةࣰ وَأَصِیلًا',
    'لتؤمنوا بالله ورسوله وتعزروه وتوقروه وتسبحوه بكرة واصيلا',
    'لِّتُؤۡمِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ وَتُسَبِّحُوهُ بُكۡرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَصِيلاً ٩',
    9, 26, 6, 511, 446, 204, 'false'
  );
  
  -- Ayah 10 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4593,
    'إِنَّ ٱلَّذِینَ یُبَایِعُونَكَ إِنَّمَا یُبَایِعُونَ ٱللَّهَ یَدُ ٱللَّهِ فَوۡقَ أَیۡدِیهِمۡۚ فَمَن نَّكَثَ فَإِنَّمَا یَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ بِمَا عَـٰهَدَ عَلَیۡهُ ٱللَّهَ فَسَیُؤۡتِیهِ أَجۡرًا عَظِیمࣰا',
    'ان الذين يبايعونك انما يبايعون الله يد الله فوق ايديهم فمن نكث فانما ينكث على نفسه ومن اوفى بما عاهد عليه الله فسيؤتيه اجرا عظيما',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُبَايِعُونَكَ إِ<rule class=ghunnah>نّ</rule>َمَا يُبَايِعُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ يَدُ <rule class=ham_wasl>ٱ</rule>للَّهِ فَوۡقَ أَيۡدِيهِمۡ‌ۚ فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّكَثَ فَإِ<rule class=ghunnah>نّ</rule>َمَا يَ<rule class=ikhafa>نك</rule>ُثُ عَلَىٰ نَفۡسِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَنۡ أَوۡفَىٰ بِمَا عَ<rule class=madda_normal>ـٰ</rule>هَدَ عَلَيۡهُ <rule class=ham_wasl>ٱ</rule>للَّهَ فَسَيُؤۡتِيهِ أَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمًا ١٠',
    10, 26, 6, 512, 446, 204, 'false'
  );
  
  -- Ayah 11 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4594,
    'سَیَقُولُ لَكَ ٱلۡمُخَلَّفُونَ مِنَ ٱلۡأَعۡرَابِ شَغَلَتۡنَاۤ أَمۡوَ ٰ⁠لُنَا وَأَهۡلُونَا فَٱسۡتَغۡفِرۡ لَنَاۚ یَقُولُونَ بِأَلۡسِنَتِهِم مَّا لَیۡسَ فِی قُلُوبِهِمۡۚ قُلۡ فَمَن یَمۡلِكُ لَكُم مِّنَ ٱللَّهِ شَیۡـًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرَۢا',
    'سيقول لك المخلفون من الاعراب شغلتنا اموالنا واهلونا فاستغفر لنا يقولون بالسنتهم ما ليس في قلوبهم قل فمن يملك لكم من الله شيئا ان اراد بكم ضرا او اراد بكم نفعا بل كان الله بما تعملون خبيرا',
    'سَيَقُولُ لَكَ <rule class=ham_wasl>ٱ</rule>لۡمُخَلَّفُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابِ شَغَلَتۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لُنَا وَأَهۡلُونَا فَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرۡ لَنَا‌ۚ يَقُولُونَ بِأَلۡسِنَتِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا لَيۡسَ فِى قُلُوبِهِمۡ‌ۚ قُلۡ فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡلِكُ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡــًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡع<rule class=iqlab>َۢا‌ۚ</rule> <rule class=iqlab>ب</rule>َلۡ كَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ خَبِيرَۢا ١١',
    11, 26, 6, 512, 447, 204, 'false'
  );
  
  -- Ayah 12 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4595,
    'بَلۡ ظَنَنتُمۡ أَن لَّن یَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰۤ أَهۡلِیهِمۡ أَبَدࣰا وَزُیِّنَ ذَ ٰ⁠لِكَ فِی قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ وَكُنتُمۡ قَوۡمَۢا بُورࣰا',
    'بل ظننتم ان لن ينقلب الرسول والمؤمنون الى اهليهم ابدا وزين ذلك في قلوبكم وظننتم ظن السوء وكنتم قوما بورا',
    'بَلۡ ظَنَ<rule class=ikhafa>نت</rule>ُمۡ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نق</rule>َلِبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِيهِمۡ أَبَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َزُيِّنَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فِى قُلُوبِكُمۡ وَظَنَ<rule class=ikhafa>نت</rule>ُمۡ ظَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّوۡءِ وَكُ<rule class=ikhafa>نت</rule>ُمۡ قَوۡم<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ُورًا ١٢',
    12, 26, 6, 512, 447, 204, 'false'
  );
  
  -- Ayah 13 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4596,
    'وَمَن لَّمۡ یُؤۡمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّاۤ أَعۡتَدۡنَا لِلۡكَـٰفِرِینَ سَعِیرࣰا',
    'ومن لم يؤمن بالله ورسوله فانا اعتدنا للكافرين سعيرا',
    'وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يُؤۡم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> فَإِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ سَعِيرًا ١٣',
    13, 26, 6, 512, 447, 204, 'false'
  );
  
  -- Ayah 14 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4597,
    'وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ یَغۡفِرُ لِمَن یَشَاۤءُ وَیُعَذِّبُ مَن یَشَاۤءُۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا',
    'ولله ملك السماوات والارض يغفر لمن يشاء ويعذب من يشاء وكان الله غفورا رحيما',
    'وَلِلَّهِ مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ يَغۡفِرُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيُعَذِّبُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحِيمًا ١٤',
    14, 26, 6, 512, 447, 204, 'false'
  );
  
  -- Ayah 15 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4598,
    'سَیَقُولُ ٱلۡمُخَلَّفُونَ إِذَا ٱنطَلَقۡتُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ یُرِیدُونَ أَن یُبَدِّلُوا۟ كَلَـٰمَ ٱللَّهِۚ قُل لَّن تَتَّبِعُونَا كَذَ ٰ⁠لِكُمۡ قَالَ ٱللَّهُ مِن قَبۡلُۖ فَسَیَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُوا۟ لَا یَفۡقَهُونَ إِلَّا قَلِیلࣰا',
    'سيقول المخلفون اذا انطلقتم الى مغانم لتاخذوها ذرونا نتبعكم يريدون ان يبدلوا كلام الله قل لن تتبعونا كذلكم قال الله من قبل فسيقولون بل تحسدوننا بل كانوا لا يفقهون الا قليلا',
    'سَيَقُولُ <rule class=ham_wasl>ٱ</rule>لۡمُخَلَّفُونَ إِذَا <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نط</rule>َلَ<rule class=qalaqah>قۡ</rule>تُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡ‌ۖ يُرِيدُونَ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُبَدِّلُو<rule class=slnt>اۡ</rule> كَلَ<rule class=madda_normal>ـٰ</rule>مَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ قُل لَّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَّبِعُونَا كَذ<rule class=madda_normal>ٰ</rule>لِكُمۡ قَالَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ فَسَيَقُولُونَ بَلۡ تَحۡسُدُونَنَا‌ۚ بَلۡ كَانُو<rule class=slnt>اۡ</rule> لَا يَفۡقَهُونَ إِلَّا قَلِيلاً ١٥',
    15, 26, 6, 512, 447, 204, 'false'
  );
  
  -- Ayah 16 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4599,
    'قُل لِّلۡمُخَلَّفِینَ مِنَ ٱلۡأَعۡرَابِ سَتُدۡعَوۡنَ إِلَىٰ قَوۡمٍ أُو۟لِی بَأۡسࣲ شَدِیدࣲ تُقَـٰتِلُونَهُمۡ أَوۡ یُسۡلِمُونَۖ فَإِن تُطِیعُوا۟ یُؤۡتِكُمُ ٱللَّهُ أَجۡرًا حَسَنࣰاۖ وَإِن تَتَوَلَّوۡا۟ كَمَا تَوَلَّیۡتُم مِّن قَبۡلُ یُعَذِّبۡكُمۡ عَذَابًا أَلِیمࣰا',
    'قل للمخلفين من الاعراب ستدعون الى قوم اولي باس شديد تقاتلونهم او يسلمون فان تطيعوا يؤتكم الله اجرا حسنا وان تتولوا كما توليتم من قبل يعذبكم عذابا اليما',
    'قُل لِّلۡمُخَلَّفِينَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابِ سَتُ<rule class=qalaqah>دۡ</rule>عَوۡنَ إِلَىٰ قَوۡمٍ أُ<rule class=slnt>وۡ</rule>لِى بَأۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=ikhafa>دٍ</rule> <rule class=ikhafa>ت</rule>ُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَهُمۡ أَوۡ يُسۡلِمُونَ‌ۖ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُطِيعُو<rule class=slnt>اۡ</rule> يُؤۡتِكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=qalaqah>جۡ</rule>رًا حَسَ<rule class=idgham_ghunnah>نًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتَوَلَّوۡ<rule class=slnt>اۡ</rule> كَمَا تَوَلَّيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ يُعَذِّ<rule class=qalaqah>بۡ</rule>كُمۡ عَذَابًا أَلِيمًا ١٦',
    16, 26, 6, 513, 447, 204, 'false'
  );
  
  -- Ayah 17 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4600,
    'لَّیۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجࣱ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجࣱ وَلَا عَلَى ٱلۡمَرِیضِ حَرَجࣱۗ وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ یُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ وَمَن یَتَوَلَّ یُعَذِّبۡهُ عَذَابًا أَلِیمࣰا',
    'ليس على الاعمى حرج ولا على الاعرج حرج ولا على المريض حرج ومن يطع الله ورسوله يدخله جنات تجري من تحتها الانهار ومن يتول يعذبه عذابا اليما',
    'لَّيۡسَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَعۡمَىٰ حَرَ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَجِ حَرَ<rule class=idgham_ghunnah>جٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡمَرِيضِ حَرَ<rule class=idgham_ghunnah>جٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُطِعِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> يُ<rule class=qalaqah>دۡ</rule>خِلۡهُ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَلَّ يُعَذِّ<rule class=qalaqah>بۡ</rule>هُ عَذَابًا أَلِيمًا ١٧',
    17, 26, 6, 513, 447, 204, 'false'
  );
  
  -- Ayah 18 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4601,
    '۞ لَّقَدۡ رَضِیَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِینَ إِذۡ یُبَایِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِی قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِینَةَ عَلَیۡهِمۡ وَأَثَـٰبَهُمۡ فَتۡحࣰا قَرِیبࣰا',
    'لقد رضي الله عن المؤمنين اذ يبايعونك تحت الشجرة فعلم ما في قلوبهم فانزل السكينة عليهم واثابهم فتحا قريبا',
    '۞لَّقَ<rule class=qalaqah>دۡ</rule> رَضِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرَةِ فَعَلِمَ مَا فِى قُلُوبِهِمۡ فَأَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّكِينَةَ عَلَيۡهِمۡ وَأَثَ<rule class=madda_normal>ـٰ</rule>بَهُمۡ فَتۡ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ق</rule>َرِيبًا ١٨',
    18, 26, 6, 513, 448, 205, 'false'
  );
  
  -- Ayah 19 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4602,
    'وَمَغَانِمَ كَثِیرَةࣰ یَأۡخُذُونَهَاۗ وَكَانَ ٱللَّهُ عَزِیزًا حَكِیمࣰا',
    'ومغانم كثيرة ياخذونها وكان الله عزيزا حكيما',
    'وَمَغَانِمَ كَثِيرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>َأۡخُذُونَهَا‌ۗ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَزِيزًا حَكِيمًا ١٩',
    19, 26, 6, 513, 448, 205, 'false'
  );
  
  -- Ayah 20 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4603,
    'وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِیرَةࣰ تَأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَـٰذِهِۦ وَكَفَّ أَیۡدِیَ ٱلنَّاسِ عَنكُمۡ وَلِتَكُونَ ءَایَةࣰ لِّلۡمُؤۡمِنِینَ وَیَهۡدِیَكُمۡ صِرَ ٰ⁠طࣰا مُّسۡتَقِیمࣰا',
    'وعدكم الله مغانم كثيرة تاخذونها فعجل لكم هذه وكف ايدي الناس عنكم ولتكون اية للمؤمنين ويهديكم صراطا مستقيما',
    'وَعَدَكُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مَغَانِمَ كَثِيرَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ت</rule>َأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> وَكَفَّ أَيۡدِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ عَ<rule class=ikhafa>نك</rule>ُمۡ وَلِتَكُونَ ءَايَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُؤۡمِنِينَ وَيَهۡدِيَكُمۡ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طًا</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقِيمًا ٢٠',
    20, 26, 6, 513, 448, 205, 'false'
  );
  
  -- Ayah 21 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4604,
    'وَأُخۡرَىٰ لَمۡ تَقۡدِرُوا۟ عَلَیۡهَا قَدۡ أَحَاطَ ٱللَّهُ بِهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣰا',
    'واخرى لم تقدروا عليها قد احاط الله بها وكان الله على كل شيء قديرا',
    'وَأُخۡرَىٰ لَمۡ تَ<rule class=qalaqah>قۡ</rule>دِرُو<rule class=slnt>اۡ</rule> عَلَيۡهَا قَ<rule class=qalaqah>دۡ</rule> أَحَاطَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِهَا‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َدِيرًا ٢١',
    21, 26, 6, 513, 448, 205, 'false'
  );
  
  -- Ayah 22 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4605,
    'وَلَوۡ قَـٰتَلَكُمُ ٱلَّذِینَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلۡأَدۡبَـٰرَ ثُمَّ لَا یَجِدُونَ وَلِیࣰّا وَلَا نَصِیرࣰا',
    'ولو قاتلكم الذين كفروا لولوا الادبار ثم لا يجدون وليا ولا نصيرا',
    'وَلَوۡ قَ<rule class=madda_normal>ـٰ</rule>تَلَكُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَوَلَّوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رَ ثُ<rule class=ghunnah>مّ</rule>َ لَا يَجِدُونَ وَلِي<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَصِيرًا ٢٢',
    22, 26, 6, 513, 448, 205, 'false'
  );
  
  -- Ayah 23 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4606,
    'سُنَّةَ ٱللَّهِ ٱلَّتِی قَدۡ خَلَتۡ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِیلࣰا',
    'سنة الله التي قد خلت من قبل ولن تجد لسنة الله تبديلا',
    'سُ<rule class=ghunnah>نّ</rule>َةَ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لَّتِى قَ<rule class=qalaqah>دۡ</rule> خَلَتۡ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ وَلَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َجِدَ لِسُ<rule class=ghunnah>نّ</rule>َةِ <rule class=ham_wasl>ٱ</rule>للَّهِ تَ<rule class=qalaqah>بۡ</rule>دِيلاً ٢٣',
    23, 26, 6, 513, 448, 205, 'false'
  );
  
  -- Ayah 24 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4607,
    'وَهُوَ ٱلَّذِی كَفَّ أَیۡدِیَهُمۡ عَنكُمۡ وَأَیۡدِیَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ بَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَیۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرًا',
    'وهو الذي كف ايديهم عنكم وايديكم عنهم ببطن مكة من بعد ان اظفركم عليهم وكان الله بما تعملون بصيرا',
    'وَهُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى كَفَّ أَيۡدِيَهُمۡ عَ<rule class=ikhafa>نك</rule>ُمۡ وَأَيۡدِيَكُمۡ عَنۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِبَ<rule class=qalaqah>طۡ</rule>نِ مَكَّةَ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَيۡهِمۡ‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ٢٤',
    24, 26, 6, 514, 448, 205, 'false'
  );
  
  -- Ayah 25 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4608,
    'هُمُ ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَٱلۡهَدۡیَ مَعۡكُوفًا أَن یَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالࣱ مُّؤۡمِنُونَ وَنِسَاۤءࣱ مُّؤۡمِنَـٰتࣱ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِیبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَیۡرِ عِلۡمࣲۖ لِّیُدۡخِلَ ٱللَّهُ فِی رَحۡمَتِهِۦ مَن یَشَاۤءُۚ لَوۡ تَزَیَّلُوا۟ لَعَذَّبۡنَا ٱلَّذِینَ كَفَرُوا۟ مِنۡهُمۡ عَذَابًا أَلِیمًا',
    'هم الذين كفروا وصدوكم عن المسجد الحرام والهدي معكوفا ان يبلغ محله ولولا رجال مؤمنون ونساء مؤمنات لم تعلموهم ان تطئوهم فتصيبكم منهم معرة بغير علم ليدخل الله في رحمته من يشاء لو تزيلوا لعذبنا الذين كفروا منهم عذابا اليما',
    'هُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَصَدُّوكُمۡ عَنِ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدِ <rule class=ham_wasl>ٱ</rule>لۡحَرَامِ وَ<rule class=ham_wasl>ٱ</rule>لۡهَ<rule class=qalaqah>دۡ</rule>ىَ مَعۡكُوفًا أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>لُغَ مَحِلَّهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَلَوۡلَا رِجَا<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنُونَ وَنِس<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَعۡلَمُوهُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َطَــُٔوهُمۡ فَتُصِيبَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّعَرَّ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>ِغَيۡرِ عِلۡ<rule class=idgham_wo_ghunnah>مٍ‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُ<rule class=qalaqah>دۡ</rule>خِلَ <rule class=ham_wasl>ٱ</rule>للَّهُ فِى رَحۡمَتِه<rule class=madda_normal>ِۦ</rule> م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ لَوۡ تَزَيَّلُو<rule class=slnt>اۡ</rule> لَعَذَّ<rule class=qalaqah>بۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ عَذَابًا أَلِيمًا ٢٥',
    25, 26, 6, 514, 448, 205, 'false'
  );
  
  -- Ayah 26 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4609,
    'إِذۡ جَعَلَ ٱلَّذِینَ كَفَرُوا۟ فِی قُلُوبِهِمُ ٱلۡحَمِیَّةَ حَمِیَّةَ ٱلۡجَـٰهِلِیَّةِ فَأَنزَلَ ٱللَّهُ سَكِینَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِینَ وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ وَكَانُوۤا۟ أَحَقَّ بِهَا وَأَهۡلَهَاۚ وَكَانَ ٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣰا',
    'اذ جعل الذين كفروا في قلوبهم الحمية حمية الجاهلية فانزل الله سكينته على رسوله وعلى المؤمنين والزمهم كلمة التقوى وكانوا احق بها واهلها وكان الله بكل شيء عليما',
    'إِذۡ جَعَلَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> فِى قُلُوبِهِمُ <rule class=ham_wasl>ٱ</rule>لۡحَمِيَّةَ حَمِيَّةَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>هِلِيَّةِ فَأَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ سَكِينَتَهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ رَسُولِه<rule class=madda_normal>ِۦ</rule> وَعَلَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَأَلۡزَمَهُمۡ كَلِمَةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=qalaqah>قۡ</rule>وَىٰ وَكَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَحَقَّ بِهَا وَأَهۡلَهَا‌ۚ وَكَانَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ شَىۡءٍ عَلِيمًا ٢٦',
    26, 26, 6, 514, 448, 205, 'false'
  );
  
  -- Ayah 27 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4610,
    'لَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡیَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ إِن شَاۤءَ ٱللَّهُ ءَامِنِینَ مُحَلِّقِینَ رُءُوسَكُمۡ وَمُقَصِّرِینَ لَا تَخَافُونَۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُوا۟ فَجَعَلَ مِن دُونِ ذَ ٰ⁠لِكَ فَتۡحࣰا قَرِیبًا',
    'لقد صدق الله رسوله الرؤيا بالحق لتدخلن المسجد الحرام ان شاء الله امنين محلقين رءوسكم ومقصرين لا تخافون فعلم ما لم تعلموا فجعل من دون ذلك فتحا قريبا',
    'لَّقَ<rule class=qalaqah>دۡ</rule> صَدَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ رَسُولَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّءۡيَا بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ لَتَ<rule class=qalaqah>دۡ</rule>خُلُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمَسۡجِدَ <rule class=ham_wasl>ٱ</rule>لۡحَرَامَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمۡ وَمُقَصِّرِينَ لَا تَخَافُونَ‌ۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُو<rule class=slnt>اۡ</rule> فَجَعَلَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَتۡ<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ق</rule>َرِيبًا ٢٧',
    27, 26, 6, 514, 449, 205, 'false'
  );
  
  -- Ayah 28 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4611,
    'هُوَ ٱلَّذِیۤ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِینِ ٱلۡحَقِّ لِیُظۡهِرَهُۥ عَلَى ٱلدِّینِ كُلِّهِۦۚ وَكَفَىٰ بِٱللَّهِ شَهِیدࣰا',
    'هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله وكفى بالله شهيدا',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡسَلَ رَسُولَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَدِينِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ لِيُظۡهِرَهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ كُلِّه<rule class=madda_normal>ِۦ</rule>‌ۚ وَكَفَىٰ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ شَهِيدًا ٢٨',
    28, 26, 6, 514, 449, 205, 'false'
  );
  
  -- Ayah 29 Surah Al-Fath
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    48,
    4612,
    'مُّحَمَّدࣱ رَّسُولُ ٱللَّهِۚ وَٱلَّذِینَ مَعَهُۥۤ أَشِدَّاۤءُ عَلَى ٱلۡكُفَّارِ رُحَمَاۤءُ بَیۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعࣰا سُجَّدࣰا یَبۡتَغُونَ فَضۡلࣰا مِّنَ ٱللَّهِ وَرِضۡوَ ٰ⁠نࣰاۖ سِیمَاهُمۡ فِی وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَ ٰ⁠لِكَ مَثَلُهُمۡ فِی ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِی ٱلۡإِنجِیلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ عَلَىٰ سُوقِهِۦ یُعۡجِبُ ٱلزُّرَّاعَ لِیَغِیظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنۡهُم مَّغۡفِرَةࣰ وَأَجۡرًا عَظِیمَۢا',
    'محمد رسول الله والذين معه اشداء على الكفار رحماء بينهم تراهم ركعا سجدا يبتغون فضلا من الله ورضوانا سيماهم في وجوههم من اثر السجود ذلك مثلهم في التوراة ومثلهم في الانجيل كزرع اخرج شطاه فازره فاستغلظ فاستوى على سوقه يعجب الزراع ليغيظ بهم الكفار وعد الله الذين امنوا وعملوا الصالحات منهم مغفرة واجرا عظيما',
    'مُّحَ<rule class=ghunnah>مّ</rule>َ<rule class=idgham_wo_ghunnah>دٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مَعَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَشِدّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكُفَّارِ رُحَم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ بَيۡنَهُمۡ‌ۖ تَرَ<rule class=madda_normal>ٮٰ</rule>هُمۡ رُكَّ<rule class=ikhafa>عًا</rule> <rule class=ikhafa>س</rule>ُجَّ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>تَغُونَ فَضۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرِضۡو<rule class=madda_normal>ٰ</rule><rule class=ikhafa>نًا‌ۖ</rule> <rule class=ikhafa>س</rule>ِيمَاهُمۡ فِى وُجُوهِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَثَرِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّجُودِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ مَثَلُهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةِ‌ۚ وَمَثَلُهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلِ كَزَرۡعٍ أَخۡرَجَ شَ<rule class=qalaqah>طۡ</rule>ــَٔهُ<rule class=madda_normal>ۥ</rule> فَـَٔـازَرَهُ<rule class=madda_normal>ۥ</rule> فَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡلَظَ فَ<rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ عَلَىٰ سُوقِه<rule class=madda_normal>ِۦ</rule> يُعۡجِبُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زُّرَّاعَ لِيَغِيظَ بِهِمُ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارَ‌ۗ وَعَدَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule>رًا عَظِيمَۢا ٢٩',
    29, 26, 6, 515, 449, 205, 'false'
  );
  

-- Surah Al-Hujuraat
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (49, 'سُورَةُ الحُجُرَاتِ', 'Al-Hujuraat', 'The Inner Apartments', 'Medinan', 18);

  -- Ayah 1 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4613,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَیۡنَ یَدَیِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ',
    'يا ايها الذين امنوا لا تقدموا بين يدي الله ورسوله واتقوا الله ان الله سميع عليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تُقَدِّمُو<rule class=slnt>اۡ</rule> بَيۡنَ يَدَىِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِيعٌ عَل<rule class=madda_permissible>ِي</rule>مٌ ١',
    1, 26, 6, 515, 450, 206, 'false'
  );
  
  -- Ayah 2 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4614,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَرۡفَعُوۤا۟ أَصۡوَ ٰ⁠تَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِیِّ وَلَا تَجۡهَرُوا۟ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَـٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ',
    'يا ايها الذين امنوا لا ترفعوا اصواتكم فوق صوت النبي ولا تجهروا له بالقول كجهر بعضكم لبعض ان تحبط اعمالكم وانتم لا تشعرون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَرۡفَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَصۡو<rule class=madda_normal>ٰ</rule>تَكُمۡ فَوۡقَ صَوۡتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىِّ وَلَا تَ<rule class=qalaqah>جۡ</rule>هَرُو<rule class=slnt>اۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡبَطَ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لُكُمۡ وَأَ<rule class=ikhafa>نت</rule>ُمۡ لَا تَشۡعُر<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 26, 6, 515, 450, 206, 'false'
  );
  
  -- Ayah 3 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4615,
    'إِنَّ ٱلَّذِینَ یَغُضُّونَ أَصۡوَ ٰ⁠تَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱمۡتَحَنَ ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةࣱ وَأَجۡرٌ عَظِیمٌ',
    'ان الذين يغضون اصواتهم عند رسول الله اولئك الذين امتحن الله قلوبهم للتقوى لهم مغفرة واجر عظيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَغُضُّونَ أَصۡو<rule class=madda_normal>ٰ</rule>تَهُمۡ عِ<rule class=ikhafa>ند</rule>َ رَسُولِ <rule class=ham_wasl>ٱ</rule>للَّهِ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>مۡتَحَنَ <rule class=ham_wasl>ٱ</rule>للَّهُ قُلُوبَهُمۡ لِلتَّ<rule class=qalaqah>قۡ</rule>وَىٰ‌ۚ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule>رٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ٣',
    3, 26, 6, 515, 450, 206, 'false'
  );
  
  -- Ayah 4 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4616,
    'إِنَّ ٱلَّذِینَ یُنَادُونَكَ مِن وَرَاۤءِ ٱلۡحُجُرَ ٰ⁠تِ أَكۡثَرُهُمۡ لَا یَعۡقِلُونَ',
    'ان الذين ينادونك من وراء الحجرات اكثرهم لا يعقلون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُنَادُونَكَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡحُجُر<rule class=madda_normal>ٰ</rule>تِ أَكۡثَرُهُمۡ لَا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 26, 6, 515, 450, 206, 'false'
  );
  
  -- Ayah 5 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4617,
    'وَلَوۡ أَنَّهُمۡ صَبَرُوا۟ حَتَّىٰ تَخۡرُجَ إِلَیۡهِمۡ لَكَانَ خَیۡرࣰا لَّهُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'ولو انهم صبروا حتى تخرج اليهم لكان خيرا لهم والله غفور رحيم',
    'وَلَوۡ أَ<rule class=ghunnah>نّ</rule>َهُمۡ صَبَرُو<rule class=slnt>اۡ</rule> حَتَّىٰ تَخۡرُجَ إِلَيۡهِمۡ لَكَانَ خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٥',
    5, 26, 6, 516, 450, 206, 'false'
  );
  
  -- Ayah 6 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4618,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن جَاۤءَكُمۡ فَاسِقُۢ بِنَبَإࣲ فَتَبَیَّنُوۤا۟ أَن تُصِیبُوا۟ قَوۡمَۢا بِجَهَـٰلَةࣲ فَتُصۡبِحُوا۟ عَلَىٰ مَا فَعَلۡتُمۡ نَـٰدِمِینَ',
    'يا ايها الذين امنوا ان جاءكم فاسق بنبا فتبينوا ان تصيبوا قوما بجهالة فتصبحوا على ما فعلتم نادمين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ فَاسِ<rule class=iqlab>قُۢ</rule> <rule class=iqlab>ب</rule>ِنَبَ<rule class=ikhafa>إٍ</rule> <rule class=ikhafa>ف</rule>َتَبَيَّن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُصِيبُو<rule class=slnt>اۡ</rule> قَوۡم<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِجَهَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َتُصۡبِحُو<rule class=slnt>اۡ</rule> عَلَىٰ مَا فَعَلۡتُمۡ نَ<rule class=madda_normal>ـٰ</rule>دِم<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 26, 6, 516, 450, 206, 'false'
  );
  
  -- Ayah 7 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4619,
    'وَٱعۡلَمُوۤا۟ أَنَّ فِیكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ یُطِیعُكُمۡ فِی كَثِیرࣲ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ وَلَـٰكِنَّ ٱللَّهَ حَبَّبَ إِلَیۡكُمُ ٱلۡإِیمَـٰنَ وَزَیَّنَهُۥ فِی قُلُوبِكُمۡ وَكَرَّهَ إِلَیۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡیَانَۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلرَّ ٰ⁠شِدُونَ',
    'واعلموا ان فيكم رسول الله لو يطيعكم في كثير من الامر لعنتم ولكن الله حبب اليكم الايمان وزينه في قلوبكم وكره اليكم الكفر والفسوق والعصيان اولئك هم الراشدون',
    'وَ<rule class=ham_wasl>ٱ</rule>عۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ فِيكُمۡ رَسُولَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ لَوۡ يُطِيعُكُمۡ فِى كَثِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرِ لَعَنِتُّمۡ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ حَبَّبَ إِلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نَ وَزَيَّنَهُ<rule class=madda_normal>ۥ</rule> فِى قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡكُفۡرَ وَ<rule class=ham_wasl>ٱ</rule>لۡفُسُوقَ وَ<rule class=ham_wasl>ٱ</rule>لۡعِصۡيَانَ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>شِد<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 26, 6, 516, 450, 206, 'false'
  );
  
  -- Ayah 8 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4620,
    'فَضۡلࣰا مِّنَ ٱللَّهِ وَنِعۡمَةࣰۚ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'فضلا من الله ونعمة والله عليم حكيم',
    'فَضۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَنِعۡمَ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ٨',
    8, 26, 6, 516, 450, 206, 'false'
  );
  
  -- Ayah 9 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4621,
    'وَإِن طَاۤىِٕفَتَانِ مِنَ ٱلۡمُؤۡمِنِینَ ٱقۡتَتَلُوا۟ فَأَصۡلِحُوا۟ بَیۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَـٰتِلُوا۟ ٱلَّتِی تَبۡغِی حَتَّىٰ تَفِیۤءَ إِلَىٰۤ أَمۡرِ ٱللَّهِۚ فَإِن فَاۤءَتۡ فَأَصۡلِحُوا۟ بَیۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوۤا۟ۖ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُقۡسِطِینَ',
    'وان طائفتان من المؤمنين اقتتلوا فاصلحوا بينهما فان بغت احداهما على الاخرى فقاتلوا التي تبغي حتى تفيء الى امر الله فان فاءت فاصلحوا بينهما بالعدل واقسطوا ان الله يحب المقسطين',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَتَانِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تَتَلُو<rule class=slnt>اۡ</rule> فَأَصۡلِحُو<rule class=slnt>اۡ</rule> بَيۡنَهُمَا‌ۖ فَإ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َغَتۡ إِحۡدَ<rule class=madda_normal>ٮٰ</rule>هُمَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡأُخۡرَىٰ فَقَ<rule class=madda_normal>ـٰ</rule>تِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّتِى تَ<rule class=qalaqah>بۡ</rule>غِى حَتَّىٰ تَف<rule class=madda_obligatory_mottasel>ِى</rule>ٓءَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ فَأَصۡلِحُو<rule class=slnt>اۡ</rule> بَيۡنَهُمَا بِ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=qalaqah>دۡ</rule>لِ وَأَ<rule class=qalaqah>قۡ</rule>سِط<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>قۡ</rule>سِط<rule class=madda_permissible>ِي</rule>نَ ٩',
    9, 26, 6, 516, 450, 206, 'false'
  );
  
  -- Ayah 10 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4622,
    'إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةࣱ فَأَصۡلِحُوا۟ بَیۡنَ أَخَوَیۡكُمۡۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ',
    'انما المؤمنون اخوة فاصلحوا بين اخويكم واتقوا الله لعلكم ترحمون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ إِخۡوَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>َأَصۡلِحُو<rule class=slnt>اۡ</rule> بَيۡنَ أَخَوَيۡكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَلَّكُمۡ تُرۡحَم<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 26, 6, 516, 450, 206, 'false'
  );
  
  -- Ayah 11 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4623,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا یَسۡخَرۡ قَوۡمࣱ مِّن قَوۡمٍ عَسَىٰۤ أَن یَكُونُوا۟ خَیۡرࣰا مِّنۡهُمۡ وَلَا نِسَاۤءࣱ مِّن نِّسَاۤءٍ عَسَىٰۤ أَن یَكُنَّ خَیۡرࣰا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوۤا۟ أَنفُسَكُمۡ وَلَا تَنَابَزُوا۟ بِٱلۡأَلۡقَـٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِیمَـٰنِۚ وَمَن لَّمۡ یَتُبۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ',
    'يا ايها الذين امنوا لا يسخر قوم من قوم عسى ان يكونوا خيرا منهم ولا نساء من نساء عسى ان يكن خيرا منهن ولا تلمزوا انفسكم ولا تنابزوا بالالقاب بئس الاسم الفسوق بعد الايمان ومن لم يتب فاولئك هم الظالمون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا يَسۡخَرۡ قَوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡمٍ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُونُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ وَلَا نِس<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ِّس<rule class=madda_obligatory_mottasel>َا</rule>ٓءٍ عَسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َكُ<rule class=ghunnah>نّ</rule>َ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ<rule class=ghunnah>نّ</rule>َ‌ۖ وَلَا تَلۡمِز<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ وَلَا تَنَابَزُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡأَلۡقَ<rule class=madda_normal>ـٰ</rule>بِ‌ۖ بِئۡسَ <rule class=ham_wasl>ٱ</rule>لِ<rule class=ham_wasl>ٱ</rule>سۡمُ <rule class=ham_wasl>ٱ</rule>لۡفُسُوقُ بَعۡدَ <rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ وَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَتُ<rule class=qalaqah>بۡ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 26, 6, 516, 451, 206, 'false'
  );
  
  -- Ayah 12 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4624,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱجۡتَنِبُوا۟ كَثِیرࣰا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمࣱۖ وَلَا تَجَسَّسُوا۟ وَلَا یَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَیُحِبُّ أَحَدُكُمۡ أَن یَأۡكُلَ لَحۡمَ أَخِیهِ مَیۡتࣰا فَكَرِهۡتُمُوهُۚ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابࣱ رَّحِیمࣱ',
    'يا ايها الذين امنوا اجتنبوا كثيرا من الظن ان بعض الظن اثم ولا تجسسوا ولا يغتب بعضكم بعضا ايحب احدكم ان ياكل لحم اخيه ميتا فكرهتموه واتقوا الله ان الله تواب رحيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَنِبُو<rule class=slnt>اۡ</rule> كَثِي<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>ِ إِ<rule class=ghunnah>نّ</rule>َ بَعۡضَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>ِ إِثۡ<rule class=idgham_ghunnah>مٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَجَسَّسُو<rule class=slnt>اۡ</rule> وَلَا يَغۡتَب بَّعۡضُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َعۡضًا‌ۚ أَيُحِبُّ أَحَدُكُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡكُلَ لَحۡمَ أَخِيهِ مَيۡ<rule class=ikhafa>تًا</rule> <rule class=ikhafa>ف</rule>َكَرِهۡتُمُوهُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ تَوَّا<rule class=idgham_wo_ghunnah>بٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٢',
    12, 26, 6, 517, 451, 206, 'false'
  );
  
  -- Ayah 13 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4625,
    'یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَـٰكُم مِّن ذَكَرࣲ وَأُنثَىٰ وَجَعَلۡنَـٰكُمۡ شُعُوبࣰا وَقَبَاۤىِٕلَ لِتَعَارَفُوۤا۟ۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِیمٌ خَبِیرࣱ',
    'يا ايها الناس انا خلقناكم من ذكر وانثى وجعلناكم شعوبا وقبائل لتعارفوا ان اكرمكم عند الله اتقاكم ان الله عليم خبير',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ إِ<rule class=ghunnah>نّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َكَ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َأُ<rule class=ikhafa>نث</rule>َىٰ وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ شُعُو<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>و</rule>َقَب<rule class=madda_obligatory_mottasel>َا</rule>ٓئِلَ لِتَعَارَف<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ أَكۡرَمَكُمۡ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ أَتۡقَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلِيمٌ خَب<rule class=madda_permissible>ِي</rule>رٌ ١٣',
    13, 26, 6, 517, 451, 206, 'false'
  );
  
  -- Ayah 14 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4626,
    '۞ قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُوا۟ وَلَـٰكِن قُولُوۤا۟ أَسۡلَمۡنَا وَلَمَّا یَدۡخُلِ ٱلۡإِیمَـٰنُ فِی قُلُوبِكُمۡۖ وَإِن تُطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا یَلِتۡكُم مِّنۡ أَعۡمَـٰلِكُمۡ شَیۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ',
    'قالت الاعراب امنا قل لم تؤمنوا ولكن قولوا اسلمنا ولما يدخل الايمان في قلوبكم وان تطيعوا الله ورسوله لا يلتكم من اعمالكم شيئا ان الله غفور رحيم',
    '۞قَالَتِ <rule class=ham_wasl>ٱ</rule>لۡأَعۡرَابُ ءَامَ<rule class=ghunnah>نّ</rule>َا‌ۖ قُل لَّمۡ تُؤۡمِنُو<rule class=slnt>اۡ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُول<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَسۡلَمۡنَا وَلَ<rule class=ghunnah>مّ</rule>َا يَ<rule class=qalaqah>دۡ</rule>خُلِ <rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نُ فِى قُلُوبِكُمۡ‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> لَا يَلِتۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَعۡمَ<rule class=madda_normal>ـٰ</rule>لِكُمۡ شَيۡــًٔا‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٤',
    14, 26, 6, 517, 451, 207, 'false'
  );
  
  -- Ayah 15 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4627,
    'إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ یَرۡتَابُوا۟ وَجَـٰهَدُوا۟ بِأَمۡوَ ٰ⁠لِهِمۡ وَأَنفُسِهِمۡ فِی سَبِیلِ ٱللَّهِۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلصَّـٰدِقُونَ',
    'انما المؤمنون الذين امنوا بالله ورسوله ثم لم يرتابوا وجاهدوا باموالهم وانفسهم في سبيل الله اولئك هم الصادقون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُونَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> ثُ<rule class=ghunnah>مّ</rule>َ لَمۡ يَرۡتَابُو<rule class=slnt>اۡ</rule> وَجَ<rule class=madda_normal>ـٰ</rule>هَدُو<rule class=slnt>اۡ</rule> بِأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِهِمۡ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 26, 6, 517, 451, 207, 'false'
  );
  
  -- Ayah 16 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4628,
    'قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِینِكُمۡ وَٱللَّهُ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'قل اتعلمون الله بدينكم والله يعلم ما في السماوات وما في الارض والله بكل شيء عليم',
    'قُلۡ أَتُعَلِّمُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ بِدِينِكُمۡ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ١٦',
    16, 26, 6, 517, 451, 207, 'false'
  );
  
  -- Ayah 17 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4629,
    'یَمُنُّونَ عَلَیۡكَ أَنۡ أَسۡلَمُوا۟ۖ قُل لَّا تَمُنُّوا۟ عَلَیَّ إِسۡلَـٰمَكُمۖ بَلِ ٱللَّهُ یَمُنُّ عَلَیۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِیمَـٰنِ إِن كُنتُمۡ صَـٰدِقِینَ',
    'يمنون عليك ان اسلموا قل لا تمنوا علي اسلامكم بل الله يمن عليكم ان هداكم للايمان ان كنتم صادقين',
    'يَمُ<rule class=ghunnah>نّ</rule>ُونَ عَلَيۡكَ أَنۡ أَسۡلَمُو<rule class=slnt>اۡ‌ۖ</rule> قُل لَّا تَمُ<rule class=ghunnah>نّ</rule>ُو<rule class=slnt>اۡ</rule> عَلَىَّ إِسۡلَ<rule class=madda_normal>ـٰ</rule>مَك<rule class=ikhafa_shafawi>ُم‌ۖ</rule> <rule class=ikhafa_shafawi>ب</rule>َلِ <rule class=ham_wasl>ٱ</rule>للَّهُ يَمُ<rule class=ghunnah>نّ</rule>ُ عَلَيۡكُمۡ أَنۡ هَدَ<rule class=madda_normal>ٮٰ</rule>كُمۡ لِلۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 26, 6, 517, 451, 207, 'false'
  );
  
  -- Ayah 18 Surah Al-Hujuraat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    49,
    4630,
    'إِنَّ ٱللَّهَ یَعۡلَمُ غَیۡبَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِیرُۢ بِمَا تَعۡمَلُونَ',
    'ان الله يعلم غيب السماوات والارض والله بصير بما تعملون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ غَيۡبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بَصِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 26, 6, 517, 451, 207, 'false'
  );
  

-- Surah Qaaf
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (50, 'سُورَةُ قٓ', 'Qaaf', 'The letter Qaaf', 'Meccan', 45);

  -- Ayah 1 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4631,
    'قۤۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِیدِ',
    'ق والقران المجيد',
    '<rule class=madda_necessary>قٓ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ <rule class=ham_wasl>ٱ</rule>لۡمَج<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ١',
    1, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 2 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4632,
    'بَلۡ عَجِبُوۤا۟ أَن جَاۤءَهُم مُّنذِرࣱ مِّنۡهُمۡ فَقَالَ ٱلۡكَـٰفِرُونَ هَـٰذَا شَیۡءٌ عَجِیبٌ',
    'بل عجبوا ان جاءهم منذر منهم فقال الكافرون هذا شيء عجيب',
    'بَلۡ عَجِب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=ikhafa>نذ</rule>ِ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ فَقَالَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرُونَ هَ<rule class=madda_normal>ـٰ</rule>ذَا شَىۡءٌ عَج<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٌ ٢',
    2, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 3 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4633,
    'أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰاۖ ذَ ٰ⁠لِكَ رَجۡعُۢ بَعِیدࣱ',
    'ااذا متنا وكنا ترابا ذلك رجع بعيد',
    'أَءِذَا مِتۡنَا وَكُ<rule class=ghunnah>نّ</rule>َا تُرَا<rule class=ikhafa>بًا‌ۖ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ رَ<rule class=qalaqah>جۡ</rule><rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٣',
    3, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 4 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4634,
    'قَدۡ عَلِمۡنَا مَا تَنقُصُ ٱلۡأَرۡضُ مِنۡهُمۡۖ وَعِندَنَا كِتَـٰبٌ حَفِیظُۢ',
    'قد علمنا ما تنقص الارض منهم وعندنا كتاب حفيظ',
    'قَ<rule class=qalaqah>دۡ</rule> عَلِمۡنَا مَا تَ<rule class=ikhafa>نق</rule>ُصُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ مِنۡهُمۡ‌ۖ وَعِ<rule class=ikhafa>ند</rule>َنَا كِتَ<rule class=madda_normal>ـٰ</rule>بٌ حَف<rule class=madda_permissible>ِي</rule>ظُۢ ٤',
    4, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 5 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4635,
    'بَلۡ كَذَّبُوا۟ بِٱلۡحَقِّ لَمَّا جَاۤءَهُمۡ فَهُمۡ فِیۤ أَمۡرࣲ مَّرِیجٍ',
    'بل كذبوا بالحق لما جاءهم فهم في امر مريج',
    'بَلۡ كَذَّبُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ لَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ فَهُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>َّر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ج</rule>ٍ ٥',
    5, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 6 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4636,
    'أَفَلَمۡ یَنظُرُوۤا۟ إِلَى ٱلسَّمَاۤءِ فَوۡقَهُمۡ كَیۡفَ بَنَیۡنَـٰهَا وَزَیَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجࣲ',
    'افلم ينظروا الى السماء فوقهم كيف بنيناها وزيناها وما لها من فروج',
    'أَفَلَمۡ يَ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ فَوۡقَهُمۡ كَيۡفَ بَنَيۡنَ<rule class=madda_normal>ـٰ</rule>هَا وَزَيَّ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>هَا وَمَا لَهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ُر<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ج</rule>ٍ ٦',
    6, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 7 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4637,
    'وَٱلۡأَرۡضَ مَدَدۡنَـٰهَا وَأَلۡقَیۡنَا فِیهَا رَوَ ٰ⁠سِیَ وَأَنۢبَتۡنَا فِیهَا مِن كُلِّ زَوۡجِۭ بَهِیجࣲ',
    'والارض مددناها والقينا فيها رواسي وانبتنا فيها من كل زوج بهيج',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ مَدَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هَا وَأَلۡقَيۡنَا فِيهَا رَو<rule class=madda_normal>ٰ</rule>سِىَ وَأَ<rule class=iqlab>نۢب</rule>َتۡنَا فِيهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ زَوۡ<rule class=iqlab>جِۭ</rule> <rule class=iqlab>ب</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ج</rule>ٍ ٧',
    7, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 8 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4638,
    'تَبۡصِرَةࣰ وَذِكۡرَىٰ لِكُلِّ عَبۡدࣲ مُّنِیبࣲ',
    'تبصرة وذكرى لكل عبد منيب',
    'تَ<rule class=qalaqah>بۡ</rule>صِرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َذِكۡرَىٰ لِكُلِّ عَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٨',
    8, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 9 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4639,
    'وَنَزَّلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ مُّبَـٰرَكࣰا فَأَنۢبَتۡنَا بِهِۦ جَنَّـٰتࣲ وَحَبَّ ٱلۡحَصِیدِ',
    'ونزلنا من السماء ماء مباركا فانبتنا به جنات وحب الحصيد',
    'وَنَزَّلۡنَا مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ م<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>م</rule>ُّبَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=ikhafa>كًا</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=iqlab>نۢب</rule>َتۡنَا بِه<rule class=madda_normal>ِۦ</rule> جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َحَبَّ <rule class=ham_wasl>ٱ</rule>لۡحَص<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٩',
    9, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 10 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4640,
    'وَٱلنَّخۡلَ بَاسِقَـٰتࣲ لَّهَا طَلۡعࣱ نَّضِیدࣱ',
    'والنخل باسقات لها طلع نضيد',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َخۡلَ بَاسِقَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهَا طَلۡ<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>ن</rule>َّض<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٠',
    10, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 11 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4641,
    'رِّزۡقࣰا لِّلۡعِبَادِۖ وَأَحۡیَیۡنَا بِهِۦ بَلۡدَةࣰ مَّیۡتࣰاۚ كَذَ ٰ⁠لِكَ ٱلۡخُرُوجُ',
    'رزقا للعباد واحيينا به بلدة ميتا كذلك الخروج',
    'رِّزۡ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعِبَادِ‌ۖ وَأَحۡيَيۡنَا بِه<rule class=madda_normal>ِۦ</rule> بَلۡدَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>َّيۡ<rule class=ikhafa>تًا‌ۚ</rule> <rule class=ikhafa>ك</rule>َذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡخُر<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ج</rule>ُ ١١',
    11, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 12 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4642,
    'كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَأَصۡحَـٰبُ ٱلرَّسِّ وَثَمُودُ',
    'كذبت قبلهم قوم نوح واصحاب الرس وثمود',
    'كَذَّبَتۡ قَ<rule class=qalaqah>بۡ</rule>لَهُمۡ قَوۡمُ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسِّ وَثَم<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ُ ١٢',
    12, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 13 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4643,
    'وَعَادࣱ وَفِرۡعَوۡنُ وَإِخۡوَ ٰ⁠نُ لُوطࣲ',
    'وعاد وفرعون واخوان لوط',
    'وَعَا<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َفِرۡعَوۡنُ وَإِخۡو<rule class=madda_normal>ٰ</rule>نُ ل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ط</rule>ٍ ١٣',
    13, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 14 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4644,
    'وَأَصۡحَـٰبُ ٱلۡأَیۡكَةِ وَقَوۡمُ تُبَّعࣲۚ كُلࣱّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِیدِ',
    'واصحاب الايكة وقوم تبع كل كذب الرسل فحق وعيد',
    'وَأَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡأَيۡكَةِ وَقَوۡمُ تُبَّ<rule class=ikhafa>عٍ‌ۚ</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>لٌّ</rule> <rule class=ikhafa>ك</rule>َذَّبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّسُلَ فَحَقَّ وَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ١٤',
    14, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 15 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4645,
    'أَفَعَیِینَا بِٱلۡخَلۡقِ ٱلۡأَوَّلِۚ بَلۡ هُمۡ فِی لَبۡسࣲ مِّنۡ خَلۡقࣲ جَدِیدࣲ',
    'افعيينا بالخلق الاول بل هم في لبس من خلق جديد',
    'أَفَعَيِينَا بِ<rule class=ham_wasl>ٱ</rule>لۡخَلۡقِ <rule class=ham_wasl>ٱ</rule>لۡأَوَّلِ‌ۚ بَلۡ هُمۡ فِى لَ<rule class=qalaqah>بۡ</rule><rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ خَلۡ<rule class=ikhafa>قٍ</rule> <rule class=ikhafa>ج</rule>َد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ١٥',
    15, 26, 7, 518, 452, 207, 'false'
  );
  
  -- Ayah 16 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4646,
    'وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَیۡهِ مِنۡ حَبۡلِ ٱلۡوَرِیدِ',
    'ولقد خلقنا الانسان ونعلم ما توسوس به نفسه ونحن اقرب اليه من حبل الوريد',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِه<rule class=madda_normal>ِۦ</rule> نَفۡسُهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَنَحۡنُ أَ<rule class=qalaqah>قۡ</rule>رَبُ إِلَيۡهِ مِنۡ حَ<rule class=qalaqah>بۡ</rule>لِ <rule class=ham_wasl>ٱ</rule>لۡوَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ١٦',
    16, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 17 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4647,
    'إِذۡ یَتَلَقَّى ٱلۡمُتَلَقِّیَانِ عَنِ ٱلۡیَمِینِ وَعَنِ ٱلشِّمَالِ قَعِیدࣱ',
    'اذ يتلقى المتلقيان عن اليمين وعن الشمال قعيد',
    'إِذۡ يَتَلَقَّى <rule class=ham_wasl>ٱ</rule>لۡمُتَلَقِّيَانِ عَنِ <rule class=ham_wasl>ٱ</rule>لۡيَمِينِ وَعَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شِّمَالِ قَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٧',
    17, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 18 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4648,
    'مَّا یَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَیۡهِ رَقِیبٌ عَتِیدࣱ',
    'ما يلفظ من قول الا لديه رقيب عتيد',
    'مَّا يَلۡفِظُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َوۡلٍ إِلَّا لَدَيۡهِ رَقِيبٌ عَت<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ١٨',
    18, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 19 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4649,
    'وَجَاۤءَتۡ سَكۡرَةُ ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَ ٰ⁠لِكَ مَا كُنتَ مِنۡهُ تَحِیدُ',
    'وجاءت سكرة الموت بالحق ذلك ما كنت منه تحيد',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ سَكۡرَةُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتِ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۖ ذ<rule class=madda_normal>ٰ</rule>لِكَ مَا كُ<rule class=ikhafa>نت</rule>َ مِنۡهُ تَح<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ١٩',
    19, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 20 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4650,
    'وَنُفِخَ فِی ٱلصُّورِۚ ذَ ٰ⁠لِكَ یَوۡمُ ٱلۡوَعِیدِ',
    'ونفخ في الصور ذلك يوم الوعيد',
    'وَنُفِخَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ يَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡوَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٢٠',
    20, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 21 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4651,
    'وَجَاۤءَتۡ كُلُّ نَفۡسࣲ مَّعَهَا سَاۤىِٕقࣱ وَشَهِیدࣱ',
    'وجاءت كل نفس معها سائق وشهيد',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡ كُلُّ نَفۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>َّعَهَا س<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=idgham_ghunnah>قٌ</rule> <rule class=idgham_ghunnah>و</rule>َشَه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٢١',
    21, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 22 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4652,
    'لَّقَدۡ كُنتَ فِی غَفۡلَةࣲ مِّنۡ هَـٰذَا فَكَشَفۡنَا عَنكَ غِطَاۤءَكَ فَبَصَرُكَ ٱلۡیَوۡمَ حَدِیدࣱ',
    'لقد كنت في غفلة من هذا فكشفنا عنك غطاءك فبصرك اليوم حديد',
    'لَّقَ<rule class=qalaqah>دۡ</rule> كُ<rule class=ikhafa>نت</rule>َ فِى غَفۡلَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا فَكَشَفۡنَا عَ<rule class=ikhafa>نك</rule>َ غِط<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ فَبَصَرُكَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ حَد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٢٢',
    22, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 23 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4653,
    'وَقَالَ قَرِینُهُۥ هَـٰذَا مَا لَدَیَّ عَتِیدٌ',
    'وقال قرينه هذا ما لدي عتيد',
    'وَقَالَ قَرِينُهُ<rule class=madda_normal>ۥ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا مَا لَدَىَّ عَت<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٢٣',
    23, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 24 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4654,
    'أَلۡقِیَا فِی جَهَنَّمَ كُلَّ كَفَّارٍ عَنِیدࣲ',
    'القيا في جهنم كل كفار عنيد',
    'أَلۡقِيَا فِى جَهَ<rule class=ghunnah>نّ</rule>َمَ كُلَّ كَفَّارٍ عَن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٢٤',
    24, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 25 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4655,
    'مَّنَّاعࣲ لِّلۡخَیۡرِ مُعۡتَدࣲ مُّرِیبٍ',
    'مناع للخير معتد مريب',
    'مَّ<rule class=ghunnah>نّ</rule>َا<rule class=idgham_wo_ghunnah>عٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡخَيۡرِ مُعۡتَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٢٥',
    25, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 26 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4656,
    'ٱلَّذِی جَعَلَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَأَلۡقِیَاهُ فِی ٱلۡعَذَابِ ٱلشَّدِیدِ',
    'الذي جعل مع الله الها اخر فالقياه في العذاب الشديد',
    'ٱلَّذِى جَعَلَ مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ فَأَلۡقِيَاهُ فِى <rule class=ham_wasl>ٱ</rule>لۡعَذَابِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٢٦',
    26, 26, 7, 519, 453, 207, 'false'
  );
  
  -- Ayah 27 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4657,
    '۞ قَالَ قَرِینُهُۥ رَبَّنَا مَاۤ أَطۡغَیۡتُهُۥ وَلَـٰكِن كَانَ فِی ضَلَـٰلِۭ بَعِیدࣲ',
    'قال قرينه ربنا ما اطغيته ولكن كان في ضلال بعيد',
    '۞قَالَ قَرِينُهُ<rule class=madda_normal>ۥ</rule> رَبَّنَا م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>طۡ</rule>غَيۡتُهُ<rule class=madda_normal>ۥ</rule> وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>لِۭ</rule> <rule class=iqlab>ب</rule>َع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٢٧',
    27, 26, 7, 519, 453, 208, 'false'
  );
  
  -- Ayah 28 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4658,
    'قَالَ لَا تَخۡتَصِمُوا۟ لَدَیَّ وَقَدۡ قَدَّمۡتُ إِلَیۡكُم بِٱلۡوَعِیدِ',
    'قال لا تختصموا لدي وقد قدمت اليكم بالوعيد',
    'قَالَ لَا تَخۡتَصِمُو<rule class=slnt>اۡ</rule> لَدَىَّ وَقَ<rule class=qalaqah>دۡ</rule> قَدَّمۡتُ إِلَيۡك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡوَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٢٨',
    28, 26, 7, 519, 453, 208, 'false'
  );
  
  -- Ayah 29 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4659,
    'مَا یُبَدَّلُ ٱلۡقَوۡلُ لَدَیَّ وَمَاۤ أَنَا۠ بِظَلَّـٰمࣲ لِّلۡعَبِیدِ',
    'ما يبدل القول لدي وما انا بظلام للعبيد',
    'مَا يُبَدَّلُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلُ لَدَىَّ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ بِظَلَّ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>مٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَب<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٢٩',
    29, 26, 7, 519, 453, 208, 'false'
  );
  
  -- Ayah 30 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4660,
    'یَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِیدࣲ',
    'يوم نقول لجهنم هل امتلات وتقول هل من مزيد',
    'يَوۡمَ نَقُولُ لِجَهَ<rule class=ghunnah>نّ</rule>َمَ هَلِ <rule class=ham_wasl>ٱ</rule>مۡتَلَأۡتِ وَتَقُولُ هَلۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّز<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٣٠',
    30, 26, 7, 519, 454, 208, 'false'
  );
  
  -- Ayah 31 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4661,
    'وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِینَ غَیۡرَ بَعِیدٍ',
    'وازلفت الجنة للمتقين غير بعيد',
    'وَأُزۡلِفَتِ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةُ لِلۡمُتَّقِينَ غَيۡرَ بَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٍ ٣١',
    31, 26, 7, 519, 454, 208, 'false'
  );
  
  -- Ayah 32 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4662,
    'هَـٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِیظࣲ',
    'هذا ما توعدون لكل اواب حفيظ',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَف<rule class=madda_permissible>ِي</rule>ظٍ ٣٢',
    32, 26, 7, 519, 454, 208, 'false'
  );
  
  -- Ayah 33 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4663,
    'مَّنۡ خَشِیَ ٱلرَّحۡمَـٰنَ بِٱلۡغَیۡبِ وَجَاۤءَ بِقَلۡبࣲ مُّنِیبٍ',
    'من خشي الرحمن بالغيب وجاء بقلب منيب',
    'مَّنۡ خَشِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نَ بِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِقَلۡ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّن<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٣٣',
    33, 26, 7, 519, 454, 208, 'false'
  );
  
  -- Ayah 34 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4664,
    'ٱدۡخُلُوهَا بِسَلَـٰمࣲۖ ذَ ٰ⁠لِكَ یَوۡمُ ٱلۡخُلُودِ',
    'ادخلوها بسلام ذلك يوم الخلود',
    'ٱ<rule class=qalaqah>دۡ</rule>خُلُوهَا بِسَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مٍ‌ۖ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ يَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡخُل<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ِ ٣٤',
    34, 26, 7, 519, 454, 208, 'false'
  );
  
  -- Ayah 35 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4665,
    'لَهُم مَّا یَشَاۤءُونَ فِیهَا وَلَدَیۡنَا مَزِیدࣱ',
    'لهم ما يشاءون فيها ولدينا مزيد',
    'لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّا يَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُونَ فِيهَا وَلَدَيۡنَا مَز<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٣٥',
    35, 26, 7, 519, 454, 208, 'false'
  );
  
  -- Ayah 36 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4666,
    'وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشࣰا فَنَقَّبُوا۟ فِی ٱلۡبِلَـٰدِ هَلۡ مِن مَّحِیصٍ',
    'وكم اهلكنا قبلهم من قرن هم اشد منهم بطشا فنقبوا في البلاد هل من محيص',
    'وَكَمۡ أَهۡلَكۡنَا قَ<rule class=qalaqah>بۡ</rule>لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡنٍ هُمۡ أَشَدُّ مِنۡه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َ<rule class=qalaqah>طۡ</rule><rule class=ikhafa>شًا</rule> <rule class=ikhafa>ف</rule>َنَقَّبُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡبِلَ<rule class=madda_normal>ـٰ</rule>دِ هَلۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّح<rule class=madda_permissible>ِي</rule>صٍ ٣٦',
    36, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 37 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4667,
    'إِنَّ فِی ذَ ٰ⁠لِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِیدࣱ',
    'ان في ذلك لذكرى لمن كان له قلب او القى السمع وهو شهيد',
    'إِ<rule class=ghunnah>نّ</rule>َ فِى ذ<rule class=madda_normal>ٰ</rule>لِكَ لَذِكۡرَىٰ لِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ لَهُ<rule class=madda_normal>ۥ</rule> قَلۡبٌ أَوۡ أَلۡقَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَهُوَ شَه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٣٧',
    37, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 38 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4668,
    'وَلَقَدۡ خَلَقۡنَا ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا فِی سِتَّةِ أَیَّامࣲ وَمَا مَسَّنَا مِن لُّغُوبࣲ',
    'ولقد خلقنا السماوات والارض وما بينهما في ستة ايام وما مسنا من لغوب',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ وَمَا بَيۡنَهُمَا فِى سِتَّةِ أَيَّا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا مَسَّنَا م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ُّغ<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ٍ ٣٨',
    38, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 39 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4669,
    'فَٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ',
    'فاصبر على ما يقولون وسبح بحمد ربك قبل طلوع الشمس وقبل الغروب',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَ<rule class=qalaqah>بۡ</rule>لَ طُلُوعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسِ وَقَ<rule class=qalaqah>بۡ</rule>لَ <rule class=ham_wasl>ٱ</rule>لۡغُر<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ب</rule>ِ ٣٩',
    39, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 40 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4670,
    'وَمِنَ ٱلَّیۡلِ فَسَبِّحۡهُ وَأَدۡبَـٰرَ ٱلسُّجُودِ',
    'ومن الليل فسبحه وادبار السجود',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ فَسَبِّحۡهُ وَأَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّج<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ِ ٤٠',
    40, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 41 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4671,
    'وَٱسۡتَمِعۡ یَوۡمَ یُنَادِ ٱلۡمُنَادِ مِن مَّكَانࣲ قَرِیبࣲ',
    'واستمع يوم يناد المناد من مكان قريب',
    'وَ<rule class=ham_wasl>ٱ</rule>سۡتَمِعۡ يَوۡمَ يُنَادِ <rule class=ham_wasl>ٱ</rule>لۡمُنَادِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّكَا<rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ق</rule>َر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ب</rule>ٍ ٤١',
    41, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 42 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4672,
    'یَوۡمَ یَسۡمَعُونَ ٱلصَّیۡحَةَ بِٱلۡحَقِّۚ ذَ ٰ⁠لِكَ یَوۡمُ ٱلۡخُرُوجِ',
    'يوم يسمعون الصيحة بالحق ذلك يوم الخروج',
    'يَوۡمَ يَسۡمَعُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّيۡحَةَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ يَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡخُر<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ج</rule>ِ ٤٢',
    42, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 43 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4673,
    'إِنَّا نَحۡنُ نُحۡیِۦ وَنُمِیتُ وَإِلَیۡنَا ٱلۡمَصِیرُ',
    'انا نحن نحيي ونميت والينا المصير',
    'إِ<rule class=ghunnah>نّ</rule>َا نَحۡنُ نُحۡى<rule class=madda_normal>ِۦ</rule> وَنُمِيتُ وَإِلَيۡنَا <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٤٣',
    43, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 44 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4674,
    'یَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ عَنۡهُمۡ سِرَاعࣰاۚ ذَ ٰ⁠لِكَ حَشۡرٌ عَلَیۡنَا یَسِیرࣱ',
    'يوم تشقق الارض عنهم سراعا ذلك حشر علينا يسير',
    'يَوۡمَ تَشَقَّقُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ عَنۡهُمۡ سِرَا<rule class=ikhafa>عًا‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ حَشۡرٌ عَلَيۡنَا يَس<rule class=madda_permissible>ِي</rule>رٌ ٤٤',
    44, 26, 7, 520, 454, 208, 'false'
  );
  
  -- Ayah 45 Surah Qaaf
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    50,
    4675,
    'نَّحۡنُ أَعۡلَمُ بِمَا یَقُولُونَۖ وَمَاۤ أَنتَ عَلَیۡهِم بِجَبَّارࣲۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن یَخَافُ وَعِیدِ',
    'نحن اعلم بما يقولون وما انت عليهم بجبار فذكر بالقران من يخاف وعيد',
    'نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ‌ۖ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِجَبَّا<rule class=ikhafa>رٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َذَكِّرۡ بِ<rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخَافُ وَع<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٤٥',
    45, 26, 7, 520, 454, 208, 'false'
  );
  

-- Surah Adh-Dhaariyat
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (51, 'سُورَةُ الذَّارِيَاتِ', 'Adh-Dhaariyat', 'The Winnowing Winds', 'Meccan', 60);

  -- Ayah 1 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4676,
    'وَٱلذَّ ٰ⁠رِیَـٰتِ ذَرۡوࣰا',
    'والذاريات ذروا',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذّ<rule class=madda_normal>ٰ</rule>رِيَ<rule class=madda_normal>ـٰ</rule>تِ ذَرۡوًا ١',
    1, 26, 7, 520, 455, 208, 'false'
  );
  
  -- Ayah 2 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4677,
    'فَٱلۡحَـٰمِلَـٰتِ وِقۡرࣰا',
    'فالحاملات وقرا',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>مِلَ<rule class=madda_normal>ـٰ</rule>تِ وِ<rule class=qalaqah>قۡ</rule>رًا ٢',
    2, 26, 7, 520, 455, 208, 'false'
  );
  
  -- Ayah 3 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4678,
    'فَٱلۡجَـٰرِیَـٰتِ یُسۡرࣰا',
    'فالجاريات يسرا',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=madda_normal>ـٰ</rule>رِيَ<rule class=madda_normal>ـٰ</rule>تِ يُسۡرًا ٣',
    3, 26, 7, 520, 455, 208, 'false'
  );
  
  -- Ayah 4 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4679,
    'فَٱلۡمُقَسِّمَـٰتِ أَمۡرًا',
    'فالمقسمات امرا',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡمُقَسِّمَ<rule class=madda_normal>ـٰ</rule>تِ أَمۡرًا ٤',
    4, 26, 7, 520, 455, 208, 'false'
  );
  
  -- Ayah 5 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4680,
    'إِنَّمَا تُوعَدُونَ لَصَادِقࣱ',
    'انما توعدون لصادق',
    'إِ<rule class=ghunnah>نّ</rule>َمَا تُوعَدُونَ لَصَادِ<rule class=qalaqah>ق</rule>ٌ ٥',
    5, 26, 7, 520, 455, 208, 'false'
  );
  
  -- Ayah 6 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4681,
    'وَإِنَّ ٱلدِّینَ لَوَ ٰ⁠قِعࣱ',
    'وان الدين لواقع',
    'وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ لَو<rule class=madda_normal>ٰ</rule>قِعٌ ٦',
    6, 26, 7, 520, 455, 208, 'false'
  );
  
  -- Ayah 7 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4682,
    'وَٱلسَّمَاۤءِ ذَاتِ ٱلۡحُبُكِ',
    'والسماء ذات الحبك',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ذَاتِ <rule class=ham_wasl>ٱ</rule>لۡحُبُكِ ٧',
    7, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 8 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4683,
    'إِنَّكُمۡ لَفِی قَوۡلࣲ مُّخۡتَلِفࣲ',
    'انكم لفي قول مختلف',
    'إِ<rule class=ghunnah>نّ</rule>َكُمۡ لَفِى قَوۡ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّخۡتَلِفٍ ٨',
    8, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 9 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4684,
    'یُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ',
    'يؤفك عنه من افك',
    'يُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ ٩',
    9, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 10 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4685,
    'قُتِلَ ٱلۡخَرَّ ٰ⁠صُونَ',
    'قتل الخراصون',
    'قُتِلَ <rule class=ham_wasl>ٱ</rule>لۡخَرّ<rule class=madda_normal>ٰ</rule>ص<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 11 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4686,
    'ٱلَّذِینَ هُمۡ فِی غَمۡرَةࣲ سَاهُونَ',
    'الذين هم في غمرة ساهون',
    'ٱلَّذِينَ هُمۡ فِى غَمۡرَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>س</rule>َاه<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 12 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4687,
    'یَسۡـَٔلُونَ أَیَّانَ یَوۡمُ ٱلدِّینِ',
    'يسالون ايان يوم الدين',
    'يَسۡــَٔلُونَ أَيَّانَ يَوۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ١٢',
    12, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 13 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4688,
    'یَوۡمَ هُمۡ عَلَى ٱلنَّارِ یُفۡتَنُونَ',
    'يوم هم على النار يفتنون',
    'يَوۡمَ هُمۡ عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ يُفۡتَن<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 14 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4689,
    'ذُوقُوا۟ فِتۡنَتَكُمۡ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ',
    'ذوقوا فتنتكم هذا الذي كنتم به تستعجلون',
    'ذُوقُو<rule class=slnt>اۡ</rule> فِتۡنَتَكُمۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> تَسۡتَعۡجِل<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 15 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4690,
    'إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَعُیُونٍ',
    'ان المتقين في جنات وعيون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقِينَ فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َعُي<rule class=madda_permissible>ُو</rule>نٍ ١٥',
    15, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 16 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4691,
    'ءَاخِذِینَ مَاۤ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُوا۟ قَبۡلَ ذَ ٰ⁠لِكَ مُحۡسِنِینَ',
    'اخذين ما اتاهم ربهم انهم كانوا قبل ذلك محسنين',
    'ءَاخِذِينَ م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمۡ رَبُّهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> قَ<rule class=qalaqah>بۡ</rule>لَ ذ<rule class=madda_normal>ٰ</rule>لِكَ مُحۡسِن<rule class=madda_permissible>ِي</rule>نَ ١٦',
    16, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 17 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4692,
    'كَانُوا۟ قَلِیلࣰا مِّنَ ٱلَّیۡلِ مَا یَهۡجَعُونَ',
    'كانوا قليلا من الليل ما يهجعون',
    'كَانُو<rule class=slnt>اۡ</rule> قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ مَا يَهۡجَع<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 18 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4693,
    'وَبِٱلۡأَسۡحَارِ هُمۡ یَسۡتَغۡفِرُونَ',
    'وبالاسحار هم يستغفرون',
    'وَبِ<rule class=ham_wasl>ٱ</rule>لۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِر<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 19 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4694,
    'وَفِیۤ أَمۡوَ ٰ⁠لِهِمۡ حَقࣱّ لِّلسَّاۤىِٕلِ وَٱلۡمَحۡرُومِ',
    'وفي اموالهم حق للسائل والمحروم',
    'وَف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ حَ<rule class=idgham_wo_ghunnah>قٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلسّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِلِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَحۡر<rule class=madda_permissible>ُو</rule>مِ ١٩',
    19, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 20 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4695,
    'وَفِی ٱلۡأَرۡضِ ءَایَـٰتࣱ لِّلۡمُوقِنِینَ',
    'وفي الارض ايات للموقنين',
    'وَفِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُوقِن<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 21 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4696,
    'وَفِیۤ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ',
    'وفي انفسكم افلا تبصرون',
    'وَف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۚ أَفَلَا تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 22 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4697,
    'وَفِی ٱلسَّمَاۤءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ',
    'وفي السماء رزقكم وما توعدون',
    'وَفِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رِزۡقُكُمۡ وَمَا تُوعَد<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 23 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4698,
    'فَوَرَبِّ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقࣱّ مِّثۡلَ مَاۤ أَنَّكُمۡ تَنطِقُونَ',
    'فورب السماء والارض انه لحق مثل ما انكم تنطقون',
    'فَوَرَبِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَحَ<rule class=idgham_ghunnah>قٌّ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ghunnah>نّ</rule>َكُمۡ تَ<rule class=ikhafa>نط</rule>ِق<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 26, 7, 521, 455, 208, 'false'
  );
  
  -- Ayah 24 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4699,
    'هَلۡ أَتَىٰكَ حَدِیثُ ضَیۡفِ إِبۡرَ ٰ⁠هِیمَ ٱلۡمُكۡرَمِینَ',
    'هل اتاك حديث ضيف ابراهيم المكرمين',
    'هَلۡ أَتَ<rule class=madda_normal>ـٰ</rule>كَ حَدِيثُ ضَيۡفِ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ <rule class=ham_wasl>ٱ</rule>لۡمُكۡرَم<rule class=madda_permissible>ِي</rule>نَ ٢٤',
    24, 26, 7, 521, 456, 208, 'false'
  );
  
  -- Ayah 25 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4700,
    'إِذۡ دَخَلُوا۟ عَلَیۡهِ فَقَالُوا۟ سَلَـٰمࣰاۖ قَالَ سَلَـٰمࣱ قَوۡمࣱ مُّنكَرُونَ',
    'اذ دخلوا عليه فقالوا سلاما قال سلام قوم منكرون',
    'إِذۡ دَخَلُو<rule class=slnt>اۡ</rule> عَلَيۡهِ فَقَالُو<rule class=slnt>اۡ</rule> سَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َالَ سَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ق</rule>َوۡ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=ikhafa>نك</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 26, 7, 521, 456, 208, 'false'
  );
  
  -- Ayah 26 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4701,
    'فَرَاغَ إِلَىٰۤ أَهۡلِهِۦ فَجَاۤءَ بِعِجۡلࣲ سَمِینࣲ',
    'فراغ الى اهله فجاء بعجل سمين',
    'فَرَاغَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِه<rule class=madda_normal>ِۦ</rule> فَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بِعِ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>لٍ</rule> <rule class=ikhafa>س</rule>َم<rule class=madda_permissible>ِي</rule>نٍ ٢٦',
    26, 26, 7, 521, 456, 208, 'false'
  );
  
  -- Ayah 27 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4702,
    'فَقَرَّبَهُۥۤ إِلَیۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ',
    'فقربه اليهم قال الا تاكلون',
    'فَقَرَّبَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُل<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 26, 7, 521, 456, 208, 'false'
  );
  
  -- Ayah 28 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4703,
    'فَأَوۡجَسَ مِنۡهُمۡ خِیفَةࣰۖ قَالُوا۟ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَـٰمٍ عَلِیمࣲ',
    'فاوجس منهم خيفة قالوا لا تخف وبشروه بغلام عليم',
    'فَأَوۡجَسَ مِنۡهُمۡ خِيفَ<rule class=ikhafa>ةً‌ۖ</rule> <rule class=ikhafa>ق</rule>َالُو<rule class=slnt>اۡ</rule> لَا تَخَفۡ‌ۖ وَبَشَّرُوهُ بِغُلَ<rule class=madda_normal>ـٰ</rule>مٍ عَل<rule class=madda_permissible>ِي</rule>مٍ ٢٨',
    28, 26, 7, 521, 456, 208, 'false'
  );
  
  -- Ayah 29 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4704,
    'فَأَقۡبَلَتِ ٱمۡرَأَتُهُۥ فِی صَرَّةࣲ فَصَكَّتۡ وَجۡهَهَا وَقَالَتۡ عَجُوزٌ عَقِیمࣱ',
    'فاقبلت امراته في صرة فصكت وجهها وقالت عجوز عقيم',
    'فَأَ<rule class=qalaqah>قۡ</rule>بَلَتِ <rule class=ham_wasl>ٱ</rule>مۡرَأَتُهُ<rule class=madda_normal>ۥ</rule> فِى صَرَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َصَكَّتۡ وَ<rule class=qalaqah>جۡ</rule>هَهَا وَقَالَتۡ عَجُوزٌ عَق<rule class=madda_permissible>ِي</rule>مٌ ٢٩',
    29, 26, 7, 521, 456, 208, 'false'
  );
  
  -- Ayah 30 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4705,
    'قَالُوا۟ كَذَ ٰ⁠لِكِ قَالَ رَبُّكِۖ إِنَّهُۥ هُوَ ٱلۡحَكِیمُ ٱلۡعَلِیمُ',
    'قالوا كذلك قال ربك انه هو الحكيم العليم',
    'قَالُو<rule class=slnt>اۡ</rule> كَذ<rule class=madda_normal>ٰ</rule>لِكِ قَالَ رَبُّكِ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡحَكِيمُ <rule class=ham_wasl>ٱ</rule>لۡعَل<rule class=madda_permissible>ِي</rule>مُ ٣٠',
    30, 26, 7, 521, 456, 208, 'false'
  );
  
  -- Ayah 31 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4706,
    '۞ قَالَ فَمَا خَطۡبُكُمۡ أَیُّهَا ٱلۡمُرۡسَلُونَ',
    'قال فما خطبكم ايها المرسلون',
    '۞قَالَ فَمَا خَ<rule class=qalaqah>طۡ</rule>بُكُمۡ أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمُرۡسَل<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 32 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4707,
    'قَالُوۤا۟ إِنَّاۤ أُرۡسِلۡنَاۤ إِلَىٰ قَوۡمࣲ مُّجۡرِمِینَ',
    'قالوا انا ارسلنا الى قوم مجرمين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ قَوۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٣٢',
    32, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 33 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4708,
    'لِنُرۡسِلَ عَلَیۡهِمۡ حِجَارَةࣰ مِّن طِینࣲ',
    'لنرسل عليهم حجارة من طين',
    'لِنُرۡسِلَ عَلَيۡهِمۡ حِجَارَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule><rule class=madda_permissible>ِي</rule>نٍ ٣٣',
    33, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 34 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4709,
    'مُّسَوَّمَةً عِندَ رَبِّكَ لِلۡمُسۡرِفِینَ',
    'مسومة عند ربك للمسرفين',
    'مُّسَوَّمَةً عِ<rule class=ikhafa>ند</rule>َ رَبِّكَ لِلۡمُسۡرِف<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 35 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4710,
    'فَأَخۡرَجۡنَا مَن كَانَ فِیهَا مِنَ ٱلۡمُؤۡمِنِینَ',
    'فاخرجنا من كان فيها من المؤمنين',
    'فَأَخۡرَ<rule class=qalaqah>جۡ</rule>نَا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ فِيهَا مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٣٥',
    35, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 36 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4711,
    'فَمَا وَجَدۡنَا فِیهَا غَیۡرَ بَیۡتࣲ مِّنَ ٱلۡمُسۡلِمِینَ',
    'فما وجدنا فيها غير بيت من المسلمين',
    'فَمَا وَجَ<rule class=qalaqah>دۡ</rule>نَا فِيهَا غَيۡرَ بَيۡ<rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِم<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 37 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4712,
    'وَتَرَكۡنَا فِیهَاۤ ءَایَةࣰ لِّلَّذِینَ یَخَافُونَ ٱلۡعَذَابَ ٱلۡأَلِیمَ',
    'وتركنا فيها اية للذين يخافون العذاب الاليم',
    'وَتَرَكۡنَا فِيه<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ يَخَافُونَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابَ <rule class=ham_wasl>ٱ</rule>لۡأَل<rule class=madda_permissible>ِي</rule>مَ ٣٧',
    37, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 38 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4713,
    'وَفِی مُوسَىٰۤ إِذۡ أَرۡسَلۡنَـٰهُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَـٰنࣲ مُّبِینࣲ',
    'وفي موسى اذ ارسلناه الى فرعون بسلطان مبين',
    'وَفِى مُوسَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذۡ أَرۡسَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٣٨',
    38, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 39 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4714,
    'فَتَوَلَّىٰ بِرُكۡنِهِۦ وَقَالَ سَـٰحِرٌ أَوۡ مَجۡنُونࣱ',
    'فتولى بركنه وقال ساحر او مجنون',
    'فَتَوَلَّىٰ بِرُكۡنِه<rule class=madda_normal>ِۦ</rule> وَقَالَ سَ<rule class=madda_normal>ـٰ</rule>حِرٌ أَوۡ مَ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نٌ ٣٩',
    39, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 40 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4715,
    'فَأَخَذۡنَـٰهُ وَجُنُودَهُۥ فَنَبَذۡنَـٰهُمۡ فِی ٱلۡیَمِّ وَهُوَ مُلِیمࣱ',
    'فاخذناه وجنوده فنبذناهم في اليم وهو مليم',
    'فَأَخَذۡنَ<rule class=madda_normal>ـٰ</rule>هُ وَجُنُودَهُ<rule class=madda_normal>ۥ</rule> فَنَبَذۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡيَ<rule class=ghunnah>مّ</rule>ِ وَهُوَ مُل<rule class=madda_permissible>ِي</rule>مٌ ٤٠',
    40, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 41 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4716,
    'وَفِی عَادٍ إِذۡ أَرۡسَلۡنَا عَلَیۡهِمُ ٱلرِّیحَ ٱلۡعَقِیمَ',
    'وفي عاد اذ ارسلنا عليهم الريح العقيم',
    'وَفِى عَادٍ إِذۡ أَرۡسَلۡنَا عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رِّيحَ <rule class=ham_wasl>ٱ</rule>لۡعَق<rule class=madda_permissible>ِي</rule>مَ ٤١',
    41, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 42 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4717,
    'مَا تَذَرُ مِن شَیۡءٍ أَتَتۡ عَلَیۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِیمِ',
    'ما تذر من شيء اتت عليه الا جعلته كالرميم',
    'مَا تَذَرُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ أَتَتۡ عَلَيۡهِ إِلَّا جَعَلَتۡهُ كَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّم<rule class=madda_permissible>ِي</rule>مِ ٤٢',
    42, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 43 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4718,
    'وَفِی ثَمُودَ إِذۡ قِیلَ لَهُمۡ تَمَتَّعُوا۟ حَتَّىٰ حِینࣲ',
    'وفي ثمود اذ قيل لهم تمتعوا حتى حين',
    'وَفِى ثَمُودَ إِذۡ قِيلَ لَهُمۡ تَمَتَّعُو<rule class=slnt>اۡ</rule> حَتَّىٰ ح<rule class=madda_permissible>ِي</rule>نٍ ٤٣',
    43, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 44 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4719,
    'فَعَتَوۡا۟ عَنۡ أَمۡرِ رَبِّهِمۡ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ وَهُمۡ یَنظُرُونَ',
    'فعتوا عن امر ربهم فاخذتهم الصاعقة وهم ينظرون',
    'فَعَتَوۡ<rule class=slnt>اۡ</rule> عَنۡ أَمۡرِ رَبِّهِمۡ فَأَخَذَتۡهُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>عِقَةُ وَهُمۡ يَ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 45 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4720,
    'فَمَا ٱسۡتَطَـٰعُوا۟ مِن قِیَامࣲ وَمَا كَانُوا۟ مُنتَصِرِینَ',
    'فما استطاعوا من قيام وما كانوا منتصرين',
    'فَمَا <rule class=ham_wasl>ٱ</rule>سۡتَطَ<rule class=madda_normal>ـٰ</rule>عُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ِيَا<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا كَانُو<rule class=slnt>اۡ</rule> مُ<rule class=ikhafa>نت</rule>َصِر<rule class=madda_permissible>ِي</rule>نَ ٤٥',
    45, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 46 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4721,
    'وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ',
    'وقوم نوح من قبل انهم كانوا قوما فاسقين',
    'وَقَوۡمَ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> قَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 27, 7, 522, 456, 209, 'false'
  );
  
  -- Ayah 47 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4722,
    'وَٱلسَّمَاۤءَ بَنَیۡنَـٰهَا بِأَیۡی۟دࣲ وَإِنَّا لَمُوسِعُونَ',
    'والسماء بنيناها بايد وانا لموسعون',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ بَنَيۡنَ<rule class=madda_normal>ـٰ</rule>هَا بِأَيۡ<rule class=slnt>يۡ</rule><rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َا لَمُوسِع<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 27, 7, 522, 457, 209, 'false'
  );
  
  -- Ayah 48 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4723,
    'وَٱلۡأَرۡضَ فَرَشۡنَـٰهَا فَنِعۡمَ ٱلۡمَـٰهِدُونَ',
    'والارض فرشناها فنعم الماهدون',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فَرَشۡنَ<rule class=madda_normal>ـٰ</rule>هَا فَنِعۡمَ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=madda_normal>ـٰ</rule>هِد<rule class=madda_permissible>ُو</rule>نَ ٤٨',
    48, 27, 7, 522, 457, 209, 'false'
  );
  
  -- Ayah 49 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4724,
    'وَمِن كُلِّ شَیۡءٍ خَلَقۡنَا زَوۡجَیۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ',
    'ومن كل شيء خلقنا زوجين لعلكم تذكرون',
    'وَمِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ شَىۡءٍ خَلَ<rule class=qalaqah>قۡ</rule>نَا زَوۡجَيۡنِ لَعَلَّكُمۡ تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٤٩',
    49, 27, 7, 522, 457, 209, 'false'
  );
  
  -- Ayah 50 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4725,
    'فَفِرُّوۤا۟ إِلَى ٱللَّهِۖ إِنِّی لَكُم مِّنۡهُ نَذِیرࣱ مُّبِینࣱ',
    'ففروا الى الله اني لكم منه نذير مبين',
    'فَفِرّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ إِ<rule class=ghunnah>نّ</rule>ِى لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٥٠',
    50, 27, 7, 522, 457, 209, 'false'
  );
  
  -- Ayah 51 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4726,
    'وَلَا تَجۡعَلُوا۟ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَۖ إِنِّی لَكُم مِّنۡهُ نَذِیرࣱ مُّبِینࣱ',
    'ولا تجعلوا مع الله الها اخر اني لكم منه نذير مبين',
    'وَلَا تَ<rule class=qalaqah>جۡ</rule>عَلُو<rule class=slnt>اۡ</rule> مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَ<rule class=madda_normal>ـٰ</rule>هًا ءَاخَرَ‌ۖ إِ<rule class=ghunnah>نّ</rule>ِى لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡهُ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٥١',
    51, 27, 7, 522, 457, 209, 'false'
  );
  
  -- Ayah 52 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4727,
    'كَذَ ٰ⁠لِكَ مَاۤ أَتَى ٱلَّذِینَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوۡ مَجۡنُونٌ',
    'كذلك ما اتى الذين من قبلهم من رسول الا قالوا ساحر او مجنون',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَتَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُولٍ إِلَّا قَالُو<rule class=slnt>اۡ</rule> سَاحِرٌ أَوۡ مَ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نٌ ٥٢',
    52, 27, 7, 523, 457, 209, 'false'
  );
  
  -- Ayah 53 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4728,
    'أَتَوَاصَوۡا۟ بِهِۦۚ بَلۡ هُمۡ قَوۡمࣱ طَاغُونَ',
    'اتواصوا به بل هم قوم طاغون',
    'أَتَوَاصَوۡ<rule class=slnt>اۡ</rule> بِه<rule class=madda_normal>ِۦ</rule>‌ۚ بَلۡ هُمۡ قَوۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ط</rule>َاغ<rule class=madda_permissible>ُو</rule>نَ ٥٣',
    53, 27, 7, 523, 457, 209, 'false'
  );
  
  -- Ayah 54 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4729,
    'فَتَوَلَّ عَنۡهُمۡ فَمَاۤ أَنتَ بِمَلُومࣲ',
    'فتول عنهم فما انت بملوم',
    'فَتَوَلَّ عَنۡهُمۡ فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ بِمَل<rule class=madda_permissible>ُو</rule>مٍ ٥٤',
    54, 27, 7, 523, 457, 209, 'false'
  );
  
  -- Ayah 55 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4730,
    'وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِینَ',
    'وذكر فان الذكرى تنفع المؤمنين',
    'وَذَكِّرۡ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَىٰ تَ<rule class=ikhafa>نف</rule>َعُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٥٥',
    55, 27, 7, 523, 457, 209, 'false'
  );
  
  -- Ayah 56 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4731,
    'وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِیَعۡبُدُونِ',
    'وما خلقت الجن والانس الا ليعبدون',
    'وَمَا خَلَ<rule class=qalaqah>قۡ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>َ وَ<rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ إِلَّا لِيَعۡبُد<rule class=madda_permissible>ُو</rule>نِ ٥٦',
    56, 27, 7, 523, 457, 209, 'false'
  );
  
  -- Ayah 57 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4732,
    'مَاۤ أُرِیدُ مِنۡهُم مِّن رِّزۡقࣲ وَمَاۤ أُرِیدُ أَن یُطۡعِمُونِ',
    'ما اريد منهم من رزق وما اريد ان يطعمون',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> أُرِيدُ مِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّزۡ<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أُرِيدُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>طۡ</rule>عِم<rule class=madda_permissible>ُو</rule>نِ ٥٧',
    57, 27, 7, 523, 457, 209, 'false'
  );
  
  -- Ayah 58 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4733,
    'إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِینُ',
    'ان الله هو الرزاق ذو القوة المتين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّزَّاقُ ذُو <rule class=ham_wasl>ٱ</rule>لۡقُوَّةِ <rule class=ham_wasl>ٱ</rule>لۡمَت<rule class=madda_permissible>ِي</rule>نُ ٥٨',
    58, 27, 7, 523, 457, 209, 'false'
  );
  
  -- Ayah 59 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4734,
    'فَإِنَّ لِلَّذِینَ ظَلَمُوا۟ ذَنُوبࣰا مِّثۡلَ ذَنُوبِ أَصۡحَـٰبِهِمۡ فَلَا یَسۡتَعۡجِلُونِ',
    'فان للذين ظلموا ذنوبا مثل ذنوب اصحابهم فلا يستعجلون',
    'فَإِ<rule class=ghunnah>نّ</rule>َ لِلَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> ذَنُو<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلَ ذَنُوبِ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِهِمۡ فَلَا يَسۡتَعۡجِل<rule class=madda_permissible>ُو</rule>نِ ٥٩',
    59, 27, 7, 523, 457, 209, 'false'
  );
  
  -- Ayah 60 Surah Adh-Dhaariyat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    51,
    4735,
    'فَوَیۡلࣱ لِّلَّذِینَ كَفَرُوا۟ مِن یَوۡمِهِمُ ٱلَّذِی یُوعَدُونَ',
    'فويل للذين كفروا من يومهم الذي يوعدون',
    'فَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمِهِمُ <rule class=ham_wasl>ٱ</rule>لَّذِى يُوعَد<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 27, 7, 523, 457, 209, 'false'
  );
  

-- Surah At-Tur
