  -- Ayah 6 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4741,
    'وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ',
    'والبحر المسجور',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡبَحۡرِ <rule class=ham_wasl>ٱ</rule>لۡمَسۡج<rule class=madda_permissible>ُو</rule>رِ ٦',
    6, 27, 7, 523, 458, 209, 'false'
