    'مَّا لَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>َافِعٍ ٨',
    8, 27, 7, 523, 458, 209, 'false'
