    'يَوۡمَ تَمُورُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مَوۡرًا ٩',
    9, 27, 7, 523, 458, 209, 'false'
  );
  
  -- Ayah 10 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4745,
    'وَتَسِیرُ ٱلۡجِبَالُ سَیۡرࣰا',
