    'وَتَسِيرُ <rule class=ham_wasl>ٱ</rule>لۡجِبَالُ سَيۡرًا ١٠',
    10, 27, 7, 523, 458, 209, 'false'
  );
  
  -- Ayah 11 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4746,
    'فَوَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ',
    'فويل يومئذ للمكذبين',
    'فَوَيۡ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُكَذِّب<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 27, 7, 523, 458, 209, 'false'
  );
  
  -- Ayah 12 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4747,
    'ٱلَّذِینَ هُمۡ فِی خَوۡضࣲ یَلۡعَبُونَ',
    'الذين هم في خوض يلعبون',
    'ٱلَّذِينَ هُمۡ فِى خَوۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>ي</rule>َلۡعَب<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 27, 7, 523, 458, 209, 'false'
  );
  
  -- Ayah 13 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4748,
    'یَوۡمَ یُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا',
    'يوم يدعون الى نار جهنم دعا',
    'يَوۡمَ يُدَعُّونَ إِلَىٰ نَارِ جَهَ<rule class=ghunnah>نّ</rule>َمَ دَعًّا ١٣',
    13, 27, 7, 523, 458, 209, 'false'
  );
  
  -- Ayah 14 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4749,
    'هَـٰذِهِ ٱلنَّارُ ٱلَّتِی كُنتُم بِهَا تُكَذِّبُونَ',
    'هذه النار التي كنتم بها تكذبون',
    'هَ<rule class=madda_normal>ـٰ</rule>ذِهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ <rule class=ham_wasl>ٱ</rule>لَّتِى كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَا تُكَذِّب<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 27, 7, 523, 458, 209, 'false'
  );
  
  -- Ayah 15 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4750,
    'أَفَسِحۡرٌ هَـٰذَاۤ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ',
    'افسحر هذا ام انتم لا تبصرون',
    'أَفَسِحۡرٌ هَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡ أَ<rule class=ikhafa>نت</rule>ُمۡ لَا تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 16 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4751,
    'ٱصۡلَوۡهَا فَٱصۡبِرُوۤا۟ أَوۡ لَا تَصۡبِرُوا۟ سَوَاۤءٌ عَلَیۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ',
    'اصلوها فاصبروا او لا تصبروا سواء عليكم انما تجزون ما كنتم تعملون',
    'ٱصۡلَوۡهَا فَ<rule class=ham_wasl>ٱ</rule>صۡبِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَوۡ لَا تَصۡبِرُو<rule class=slnt>اۡ</rule> سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ عَلَيۡكُمۡ‌ۖ إِ<rule class=ghunnah>نّ</rule>َمَا تُ<rule class=qalaqah>جۡ</rule>زَوۡنَ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 17 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4752,
    'إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَنَعِیمࣲ',
    'ان المتقين في جنات ونعيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقِينَ فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َنَع<rule class=madda_permissible>ِي</rule>مٍ ١٧',
    17, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 18 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4753,
    'فَـٰكِهِینَ بِمَاۤ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِیمِ',
    'فاكهين بما اتاهم ربهم ووقاهم ربهم عذاب الجحيم',
    'فَ<rule class=madda_normal>ـٰ</rule>كِهِينَ بِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُمۡ رَبُّهُمۡ وَوَقَ<rule class=madda_normal>ـٰ</rule>هُمۡ رَبُّهُمۡ عَذَابَ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ١٨',
    18, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 19 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4754,
    'كُلُوا۟ وَٱشۡرَبُوا۟ هَنِیۤـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'كلوا واشربوا هنيئا بما كنتم تعملون',
    'كُلُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>شۡرَبُو<rule class=slnt>اۡ</rule> هَنِ<rule class=madda_obligatory_mottasel>يٓـ</rule>ـ<rule class=iqlab>ـَٔۢا</rule> <rule class=iqlab>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 20 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4755,
    'مُتَّكِـِٔینَ عَلَىٰ سُرُرࣲ مَّصۡفُوفَةࣲۖ وَزَوَّجۡنَـٰهُم بِحُورٍ عِینࣲ',
    'متكئين على سرر مصفوفة وزوجناهم بحور عين',
    'مُتَّكِــِٔينَ عَلَىٰ سُرُ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>َّصۡفُوفَ<rule class=idgham_ghunnah>ةٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َزَوَّ<rule class=qalaqah>جۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِحُورٍ ع<rule class=madda_permissible>ِي</rule>نٍ ٢٠',
    20, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 21 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4756,
    'وَٱلَّذِینَ ءَامَنُوا۟ وَٱتَّبَعَتۡهُمۡ ذُرِّیَّتُهُم بِإِیمَـٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّیَّتَهُمۡ وَمَاۤ أَلَتۡنَـٰهُم مِّنۡ عَمَلِهِم مِّن شَیۡءࣲۚ كُلُّ ٱمۡرِىِٕۭ بِمَا كَسَبَ رَهِینࣱ',
    'والذين امنوا واتبعتهم ذريتهم بايمان الحقنا بهم ذريتهم وما التناهم من عملهم من شيء كل امرئ بما كسب رهين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّبَعَتۡهُمۡ ذُرِّيَّتُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِإِيمَ<rule class=madda_normal>ـٰ</rule>نٍ أَلۡحَ<rule class=qalaqah>قۡ</rule>نَا بِهِمۡ ذُرِّيَّتَهُمۡ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَلَتۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَمَلِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=ikhafa>َىۡءٍ‌ۚ</rule> <rule class=ikhafa>ك</rule>ُلُّ <rule class=ham_wasl>ٱ</rule>مۡرِى<rule class=iqlab>ِٕۭ</rule> <rule class=iqlab>ب</rule>ِمَا كَسَبَ رَه<rule class=madda_permissible>ِي</rule>نٌ ٢١',
    21, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 22 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4757,
    'وَأَمۡدَدۡنَـٰهُم بِفَـٰكِهَةࣲ وَلَحۡمࣲ مِّمَّا یَشۡتَهُونَ',
    'وامددناهم بفاكهة ولحم مما يشتهون',
    'وَأَمۡدَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِفَ<rule class=madda_normal>ـٰ</rule>كِهَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَحۡ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَشۡتَه<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 23 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4758,
    'یَتَنَـٰزَعُونَ فِیهَا كَأۡسࣰا لَّا لَغۡوࣱ فِیهَا وَلَا تَأۡثِیمࣱ',
    'يتنازعون فيها كاسا لا لغو فيها ولا تاثيم',
    'يَتَنَ<rule class=madda_normal>ـٰ</rule>زَعُونَ فِيهَا كَأۡ<rule class=idgham_wo_ghunnah>سًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا لَغۡ<rule class=ikhafa>وٌ</rule> <rule class=ikhafa>ف</rule>ِيهَا وَلَا تَأۡث<rule class=madda_permissible>ِي</rule>مٌ ٢٣',
    23, 27, 7, 524, 458, 209, 'false'
  );
  
  -- Ayah 24 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4759,
    '۞ وَیَطُوفُ عَلَیۡهِمۡ غِلۡمَانࣱ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤࣱ مَّكۡنُونࣱ',
    'ويطوف عليهم غلمان لهم كانهم لؤلؤ مكنون',
    '۞وَيَطُوفُ عَلَيۡهِمۡ غِلۡمَا<rule class=idgham_wo_ghunnah>نٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ كَأَ<rule class=ghunnah>نّ</rule>َهُمۡ لُؤۡلُ<rule class=idgham_ghunnah>ؤٌ</rule> <rule class=idgham_ghunnah>م</rule>َّكۡن<rule class=madda_permissible>ُو</rule>نٌ ٢٤',
    24, 27, 7, 524, 458, 210, 'false'
  );
  
  -- Ayah 25 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4760,
    'وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ یَتَسَاۤءَلُونَ',
    'واقبل بعضهم على بعض يتساءلون',
    'وَأَ<rule class=qalaqah>قۡ</rule>بَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡ<rule class=idgham_ghunnah>ضٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَل<rule class=madda_permissible>ُو</rule>نَ ٢٥',
    25, 27, 7, 524, 458, 210, 'false'
  );
  
  -- Ayah 26 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4761,
    'قَالُوۤا۟ إِنَّا كُنَّا قَبۡلُ فِیۤ أَهۡلِنَا مُشۡفِقِینَ',
    'قالوا انا كنا قبل في اهلنا مشفقين',
    'قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا قَ<rule class=qalaqah>بۡ</rule>لُ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَهۡلِنَا مُشۡفِق<rule class=madda_permissible>ِي</rule>نَ ٢٦',
    26, 27, 7, 524, 458, 210, 'false'
  );
  
  -- Ayah 27 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4762,
    'فَمَنَّ ٱللَّهُ عَلَیۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ',
    'فمن الله علينا ووقانا عذاب السموم',
    'فَمَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡنَا وَوَقَ<rule class=madda_normal>ـٰ</rule>نَا عَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_permissible>ُو</rule>مِ ٢٧',
    27, 27, 7, 524, 458, 210, 'false'
  );
  
  -- Ayah 28 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4763,
    'إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِیمُ',
    'انا كنا من قبل ندعوه انه هو البر الرحيم',
    'إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ نَ<rule class=qalaqah>دۡ</rule>عُوهُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ <rule class=ham_wasl>ٱ</rule>لۡبَرُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٢٨',
    28, 27, 7, 524, 458, 210, 'false'
  );
  
  -- Ayah 29 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4764,
    'فَذَكِّرۡ فَمَاۤ أَنتَ بِنِعۡمَتِ رَبِّكَ بِكَاهِنࣲ وَلَا مَجۡنُونٍ',
    'فذكر فما انت بنعمت ربك بكاهن ولا مجنون',
    'فَذَكِّرۡ فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ بِنِعۡمَتِ رَبِّكَ بِكَاهِ<rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا مَ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نٍ ٢٩',
    29, 27, 7, 524, 459, 210, 'false'
  );
  
  -- Ayah 30 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4765,
    'أَمۡ یَقُولُونَ شَاعِرࣱ نَّتَرَبَّصُ بِهِۦ رَیۡبَ ٱلۡمَنُونِ',
    'ام يقولون شاعر نتربص به ريب المنون',
    'أَمۡ يَقُولُونَ شَاعِ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>ن</rule>َّتَرَبَّصُ بِه<rule class=madda_normal>ِۦ</rule> رَيۡبَ <rule class=ham_wasl>ٱ</rule>لۡمَن<rule class=madda_permissible>ُو</rule>نِ ٣٠',
    30, 27, 7, 524, 459, 210, 'false'
  );
  
  -- Ayah 31 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4766,
    'قُلۡ تَرَبَّصُوا۟ فَإِنِّی مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِینَ',
    'قل تربصوا فاني معكم من المتربصين',
    'قُلۡ تَرَبَّصُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>ِى مَعَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡمُتَرَبِّص<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 27, 7, 524, 459, 210, 'false'
  );
  
  -- Ayah 32 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4767,
    'أَمۡ تَأۡمُرُهُمۡ أَحۡلَـٰمُهُم بِهَـٰذَاۤۚ أَمۡ هُمۡ قَوۡمࣱ طَاغُونَ',
    'ام تامرهم احلامهم بهذا ام هم قوم طاغون',
    'أَمۡ تَأۡمُرُهُمۡ أَحۡلَ<rule class=madda_normal>ـٰ</rule>مُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهَ<rule class=madda_normal>ـٰ</rule>ذ<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أَمۡ هُمۡ قَوۡ<rule class=ikhafa>مٌ</rule> <rule class=ikhafa>ط</rule>َاغ<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 33 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4768,
    'أَمۡ یَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا یُؤۡمِنُونَ',
    'ام يقولون تقوله بل لا يؤمنون',
    'أَمۡ يَقُولُونَ تَقَوَّلَهُ<rule class=madda_normal>ۥ</rule>‌ۚ بَل لَّا يُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 34 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4769,
    'فَلۡیَأۡتُوا۟ بِحَدِیثࣲ مِّثۡلِهِۦۤ إِن كَانُوا۟ صَـٰدِقِینَ',
    'فلياتوا بحديث مثله ان كانوا صادقين',
    'فَلۡيَأۡتُو<rule class=slnt>اۡ</rule> بِحَدِي<rule class=idgham_ghunnah>ثٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّثۡلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٣٤',
    34, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 35 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4770,
    'أَمۡ خُلِقُوا۟ مِنۡ غَیۡرِ شَیۡءٍ أَمۡ هُمُ ٱلۡخَـٰلِقُونَ',
    'ام خلقوا من غير شيء ام هم الخالقون',
    'أَمۡ خُلِقُو<rule class=slnt>اۡ</rule> مِنۡ غَيۡرِ شَىۡءٍ أَمۡ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>لِق<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 36 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4771,
    'أَمۡ خَلَقُوا۟ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَۚ بَل لَّا یُوقِنُونَ',
    'ام خلقوا السماوات والارض بل لا يوقنون',
    'أَمۡ خَلَقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ‌ۚ بَل لَّا يُوقِن<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 37 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4772,
    'أَمۡ عِندَهُمۡ خَزَاۤىِٕنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۣیۡطِرُونَ',
    'ام عندهم خزائن ربك ام هم المصيطرون',
    'أَمۡ عِ<rule class=ikhafa>ند</rule>َهُمۡ خَز<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنُ رَبِّكَ أَمۡ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُصَۣيۡطِر<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 38 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4773,
    'أَمۡ لَهُمۡ سُلَّمࣱ یَسۡتَمِعُونَ فِیهِۖ فَلۡیَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَـٰنࣲ مُّبِینٍ',
    'ام لهم سلم يستمعون فيه فليات مستمعهم بسلطان مبين',
    'أَمۡ لَهُمۡ سُلَّ<rule class=idgham_ghunnah>مٌ</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَمِعُونَ فِيهِ‌ۖ فَلۡيَأۡتِ مُسۡتَمِعُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسُلۡطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٣٨',
    38, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 39 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4774,
    'أَمۡ لَهُ ٱلۡبَنَـٰتُ وَلَكُمُ ٱلۡبَنُونَ',
    'ام له البنات ولكم البنون',
    'أَمۡ لَهُ <rule class=ham_wasl>ٱ</rule>لۡبَنَ<rule class=madda_normal>ـٰ</rule>تُ وَلَكُمُ <rule class=ham_wasl>ٱ</rule>لۡبَن<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 40 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4775,
    'أَمۡ تَسۡـَٔلُهُمۡ أَجۡرࣰا فَهُم مِّن مَّغۡرَمࣲ مُّثۡقَلُونَ',
    'ام تسالهم اجرا فهم من مغرم مثقلون',
    'أَمۡ تَسۡــَٔلُهُمۡ أَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّغۡرَ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّثۡقَل<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 41 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4776,
    'أَمۡ عِندَهُمُ ٱلۡغَیۡبُ فَهُمۡ یَكۡتُبُونَ',
    'ام عندهم الغيب فهم يكتبون',
    'أَمۡ عِ<rule class=ikhafa>ند</rule>َهُمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبُ فَهُمۡ يَكۡتُب<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 42 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4777,
    'أَمۡ یُرِیدُونَ كَیۡدࣰاۖ فَٱلَّذِینَ كَفَرُوا۟ هُمُ ٱلۡمَكِیدُونَ',
    'ام يريدون كيدا فالذين كفروا هم المكيدون',
    'أَمۡ يُرِيدُونَ كَيۡ<rule class=ikhafa>دًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> هُمُ <rule class=ham_wasl>ٱ</rule>لۡمَكِيد<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 43 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4778,
    'أَمۡ لَهُمۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِۚ سُبۡحَـٰنَ ٱللَّهِ عَمَّا یُشۡرِكُونَ',
    'ام لهم اله غير الله سبحان الله عما يشركون',
    'أَمۡ لَهُمۡ إِلَ<rule class=madda_normal>ـٰ</rule>هٌ غَيۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 44 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4779,
    'وَإِن یَرَوۡا۟ كِسۡفࣰا مِّنَ ٱلسَّمَاۤءِ سَاقِطࣰا یَقُولُوا۟ سَحَابࣱ مَّرۡكُومࣱ',
    'وان يروا كسفا من السماء ساقطا يقولوا سحاب مركوم',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َرَوۡ<rule class=slnt>اۡ</rule> كِسۡ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ سَاقِ<rule class=idgham_ghunnah>طًا</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُو<rule class=slnt>اۡ</rule> سَحَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>َّرۡك<rule class=madda_permissible>ُو</rule>مٌ ٤٤',
    44, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 45 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4780,
    'فَذَرۡهُمۡ حَتَّىٰ یُلَـٰقُوا۟ یَوۡمَهُمُ ٱلَّذِی فِیهِ یُصۡعَقُونَ',
    'فذرهم حتى يلاقوا يومهم الذي فيه يصعقون',
    'فَذَرۡهُمۡ حَتَّىٰ يُلَ<rule class=madda_normal>ـٰ</rule>قُو<rule class=slnt>اۡ</rule> يَوۡمَهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى فِيهِ يُصۡعَق<rule class=madda_permissible>ُو</rule>نَ ٤٥',
    45, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 46 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4781,
    'یَوۡمَ لَا یُغۡنِی عَنۡهُمۡ كَیۡدُهُمۡ شَیۡـࣰٔا وَلَا هُمۡ یُنصَرُونَ',
    'يوم لا يغني عنهم كيدهم شيئا ولا هم ينصرون',
    'يَوۡمَ لَا يُغۡنِى عَنۡهُمۡ كَيۡدُهُمۡ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا هُمۡ يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 47 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4782,
    'وَإِنَّ لِلَّذِینَ ظَلَمُوا۟ عَذَابࣰا دُونَ ذَ ٰ⁠لِكَ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ',
    'وان للذين ظلموا عذابا دون ذلك ولكن اكثرهم لا يعلمون',
    'وَإِ<rule class=ghunnah>نّ</rule>َ لِلَّذِينَ ظَلَمُو<rule class=slnt>اۡ</rule> عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>د</rule>ُونَ ذ<rule class=madda_normal>ٰ</rule>لِكَ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ أَكۡثَرَهُمۡ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 48 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4783,
    'وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡیُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِینَ تَقُومُ',
    'واصبر لحكم ربك فانك باعيننا وسبح بحمد ربك حين تقوم',
    'وَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِ<rule class=ghunnah>نّ</rule>َكَ بِأَعۡيُنِنَا‌ۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِينَ تَق<rule class=madda_permissible>ُو</rule>مُ ٤٨',
    48, 27, 7, 525, 459, 210, 'false'
  );
  
  -- Ayah 49 Surah At-Tur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    52,
    4784,
    'وَمِنَ ٱلَّیۡلِ فَسَبِّحۡهُ وَإِدۡبَـٰرَ ٱلنُّجُومِ',
    'ومن الليل فسبحه وادبار النجوم',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ فَسَبِّحۡهُ وَإِ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُج<rule class=madda_permissible>ُو</rule>مِ ٤٩',
    49, 27, 7, 525, 459, 210, 'false'
  );
  

-- Surah An-Najm
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (53, 'سُورَةُ النَّجۡمِ', 'An-Najm', 'The Star', 'Meccan', 62);

  -- Ayah 1 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4785,
    'وَٱلنَّجۡمِ إِذَا هَوَىٰ',
    'والنجم اذا هوى',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=qalaqah>جۡ</rule>مِ إِذَا هَوَىٰ ١',
    1, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 2 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4786,
    'مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ',
    'ما ضل صاحبكم وما غوى',
    'مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ ٢',
    2, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 3 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4787,
    'وَمَا یَنطِقُ عَنِ ٱلۡهَوَىٰۤ',
    'وما ينطق عن الهوى',
    'وَمَا يَ<rule class=ikhafa>نط</rule>ِقُ عَنِ <rule class=ham_wasl>ٱ</rule>لۡهَوَىٰٓ ٣',
    3, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 4 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4788,
    'إِنۡ هُوَ إِلَّا وَحۡیࣱ یُوحَىٰ',
    'ان هو الا وحي يوحى',
    'إِنۡ هُوَ إِلَّا وَحۡ<rule class=idgham_ghunnah>ىٌ</rule> <rule class=idgham_ghunnah>ي</rule>ُوحَىٰ ٤',
    4, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 5 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4789,
    'عَلَّمَهُۥ شَدِیدُ ٱلۡقُوَىٰ',
    'علمه شديد القوى',
    'عَلَّمَهُ<rule class=madda_normal>ۥ</rule> شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡقُوَىٰ ٥',
    5, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 6 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4790,
    'ذُو مِرَّةࣲ فَٱسۡتَوَىٰ',
    'ذو مرة فاستوى',
    'ذُو مِرَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ ٦',
    6, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 7 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4791,
    'وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ',
    'وهو بالافق الاعلى',
    'وَهُوَ بِ<rule class=ham_wasl>ٱ</rule>لۡأُفُقِ <rule class=ham_wasl>ٱ</rule>لۡأَعۡلَىٰ ٧',
    7, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 8 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4792,
    'ثُمَّ دَنَا فَتَدَلَّىٰ',
    'ثم دنا فتدلى',
    'ثُ<rule class=ghunnah>مّ</rule>َ دَنَا فَتَدَلَّىٰ ٨',
    8, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 9 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4793,
    'فَكَانَ قَابَ قَوۡسَیۡنِ أَوۡ أَدۡنَىٰ',
    'فكان قاب قوسين او ادنى',
    'فَكَانَ قَابَ قَوۡسَيۡنِ أَوۡ أَ<rule class=qalaqah>دۡ</rule>نَىٰ ٩',
    9, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 10 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4794,
    'فَأَوۡحَىٰۤ إِلَىٰ عَبۡدِهِۦ مَاۤ أَوۡحَىٰ',
    'فاوحى الى عبده ما اوحى',
    'فَأَوۡحَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَىٰ عَ<rule class=qalaqah>بۡ</rule>دِه<rule class=madda_normal>ِۦ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡحَىٰ ١٠',
    10, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 11 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4795,
    'مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰۤ',
    'ما كذب الفؤاد ما راى',
    'مَا كَذَبَ <rule class=ham_wasl>ٱ</rule>لۡفُؤَادُ مَا رَأَىٰٓ ١١',
    11, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 12 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4796,
    'أَفَتُمَـٰرُونَهُۥ عَلَىٰ مَا یَرَىٰ',
    'افتمارونه على ما يرى',
    'أَفَتُمَ<rule class=madda_normal>ـٰ</rule>رُونَهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ مَا يَرَىٰ ١٢',
    12, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 13 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4797,
    'وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ',
    'ولقد راه نزلة اخرى',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> رَءَاهُ نَزۡلَةً أُخۡرَىٰ ١٣',
    13, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 14 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4798,
    'عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ',
    'عند سدرة المنتهى',
    'عِ<rule class=ikhafa>ند</rule>َ سِ<rule class=qalaqah>دۡ</rule>رَةِ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نت</rule>َهَىٰ ١٤',
    14, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 15 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4799,
    'عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰۤ',
    'عندها جنة الماوى',
    'عِ<rule class=ikhafa>ند</rule>َهَا جَ<rule class=ghunnah>نّ</rule>َةُ <rule class=ham_wasl>ٱ</rule>لۡمَأۡوَىٰٓ ١٥',
    15, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 16 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4800,
    'إِذۡ یَغۡشَى ٱلسِّدۡرَةَ مَا یَغۡشَىٰ',
    'اذ يغشى السدرة ما يغشى',
    'إِذۡ يَغۡشَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سِّ<rule class=qalaqah>دۡ</rule>رَةَ مَا يَغۡشَىٰ ١٦',
    16, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 17 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4801,
    'مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ',
    'ما زاغ البصر وما طغى',
    'مَا زَاغَ <rule class=ham_wasl>ٱ</rule>لۡبَصَرُ وَمَا طَغَىٰ ١٧',
    17, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 18 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4802,
    'لَقَدۡ رَأَىٰ مِنۡ ءَایَـٰتِ رَبِّهِ ٱلۡكُبۡرَىٰۤ',
    'لقد راى من ايات ربه الكبرى',
    'لَقَ<rule class=qalaqah>دۡ</rule> رَأَىٰ مِنۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِ <rule class=ham_wasl>ٱ</rule>لۡكُ<rule class=qalaqah>بۡ</rule>رَىٰٓ ١٨',
    18, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 19 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4803,
    'أَفَرَءَیۡتُمُ ٱللَّـٰتَ وَٱلۡعُزَّىٰ',
    'افرايتم اللات والعزى',
    'أَفَرَءَيۡتُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّ<rule class=madda_normal>ـٰ</rule>تَ وَ<rule class=ham_wasl>ٱ</rule>لۡعُزَّىٰ ١٩',
    19, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 20 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4804,
    'وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰۤ',
    'ومناة الثالثة الاخرى',
    'وَمَنَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّالِثَةَ <rule class=ham_wasl>ٱ</rule>لۡأُخۡرَىٰٓ ٢٠',
    20, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 21 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4805,
    'أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ',
    'الكم الذكر وله الانثى',
    'أَلَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذَّكَرُ وَلَهُ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َىٰ ٢١',
    21, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 22 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4806,
    'تِلۡكَ إِذࣰا قِسۡمَةࣱ ضِیزَىٰۤ',
    'تلك اذا قسمة ضيزى',
    'تِلۡكَ إِ<rule class=ikhafa>ذًا</rule> <rule class=ikhafa>ق</rule>ِسۡمَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ض</rule>ِيزَىٰٓ ٢٢',
    22, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 23 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4807,
    'إِنۡ هِیَ إِلَّاۤ أَسۡمَاۤءࣱ سَمَّیۡتُمُوهَاۤ أَنتُمۡ وَءَابَاۤؤُكُم مَّاۤ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَـٰنٍۚ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَاۤءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰۤ',
    'ان هي الا اسماء سميتموها انتم واباؤكم ما انزل الله بها من سلطان ان يتبعون الا الظن وما تهوى الانفس ولقد جاءهم من ربهم الهدى',
    'إِنۡ هِىَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٌ</rule> <rule class=ikhafa>س</rule>َ<rule class=ghunnah>مّ</rule>َيۡتُمُوه<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ وَءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ُلۡطَ<rule class=madda_normal>ـٰ</rule>نٍ‌ۚ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّبِعُونَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>َ وَمَا تَهۡوَى <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=ikhafa>نف</rule>ُسُ‌ۖ وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمُ <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰٓ ٢٣',
    23, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 24 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4808,
    'أَمۡ لِلۡإِنسَـٰنِ مَا تَمَنَّىٰ',
    'ام للانسان ما تمنى',
    'أَمۡ لِلۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ مَا تَمَ<rule class=ghunnah>نّ</rule>َىٰ ٢٤',
    24, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 25 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4809,
    'فَلِلَّهِ ٱلۡـَٔاخِرَةُ وَٱلۡأُولَىٰ',
    'فلله الاخرة والاولى',
    'فَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةُ وَ<rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ ٢٥',
    25, 27, 7, 526, 460, 210, 'false'
  );
  
  -- Ayah 26 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4810,
    '۞ وَكَم مِّن مَّلَكࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ لَا تُغۡنِی شَفَـٰعَتُهُمۡ شَیۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن یَأۡذَنَ ٱللَّهُ لِمَن یَشَاۤءُ وَیَرۡضَىٰۤ',
    'وكم من ملك في السماوات لا تغني شفاعتهم شيئا الا من بعد ان ياذن الله لمن يشاء ويرضى',
    '۞وَك<rule class=idgham_shafawi>َم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّلَ<rule class=ikhafa>كٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ لَا تُغۡنِى شَفَ<rule class=madda_normal>ـٰ</rule>عَتُهُمۡ شَيۡــًٔا إِلَّا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡذَنَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ وَيَرۡضَىٰٓ ٢٦',
    26, 27, 7, 526, 461, 211, 'false'
  );
  
  -- Ayah 27 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4811,
    'إِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ لَیُسَمُّونَ ٱلۡمَلَـٰۤىِٕكَةَ تَسۡمِیَةَ ٱلۡأُنثَىٰ',
    'ان الذين لا يؤمنون بالاخرة ليسمون الملائكة تسمية الانثى',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَا يُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ لَيُسَ<rule class=ghunnah>مّ</rule>ُونَ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةَ تَسۡمِيَةَ <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َىٰ ٢٧',
    27, 27, 7, 527, 461, 211, 'false'
  );
  
  -- Ayah 28 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4812,
    'وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا یُغۡنِی مِنَ ٱلۡحَقِّ شَیۡـࣰٔا',
    'وما لهم به من علم ان يتبعون الا الظن وان الظن لا يغني من الحق شيئا',
    'وَمَا لَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مِنۡ عِلۡمٍ‌ۖ إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّبِعُونَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>َ‌ۖ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=ghunnah>نّ</rule>َ لَا يُغۡنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ شَيۡــًٔا ٢٨',
    28, 27, 7, 527, 461, 211, 'false'
  );
  
  -- Ayah 29 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4813,
    'فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ یُرِدۡ إِلَّا ٱلۡحَیَوٰةَ ٱلدُّنۡیَا',
    'فاعرض عن من تولى عن ذكرنا ولم يرد الا الحياة الدنيا',
    'فَأَعۡرِضۡ ع<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّىٰ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِنَا وَلَمۡ يُرِ<rule class=qalaqah>دۡ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا ٢٩',
    29, 27, 7, 527, 461, 211, 'false'
  );
  
  -- Ayah 30 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4814,
    'ذَ ٰ⁠لِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ',
    'ذلك مبلغهم من العلم ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بمن اهتدى',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ مَ<rule class=qalaqah>بۡ</rule>لَغُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡعِلۡمِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ أَعۡلَمُ بِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِه<rule class=madda_normal>ِۦ</rule> وَهُوَ أَعۡلَمُ بِمَنِ <rule class=ham_wasl>ٱ</rule>هۡتَدَىٰ ٣٠',
    30, 27, 7, 527, 461, 211, 'false'
  );
  
  -- Ayah 31 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4815,
    'وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ لِیَجۡزِیَ ٱلَّذِینَ أَسَـٰۤـُٔوا۟ بِمَا عَمِلُوا۟ وَیَجۡزِیَ ٱلَّذِینَ أَحۡسَنُوا۟ بِٱلۡحُسۡنَى',
    'ولله ما في السماوات وما في الارض ليجزي الذين اساءوا بما عملوا ويجزي الذين احسنوا بالحسنى',
    'وَلِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ لِيَ<rule class=qalaqah>جۡ</rule>زِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَسَ<rule class=madda_obligatory_mottasel>ـٰٓـ</rule>ــُٔو<rule class=slnt>اۡ</rule> بِمَا عَمِلُو<rule class=slnt>اۡ</rule> وَيَ<rule class=qalaqah>جۡ</rule>زِىَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَحۡسَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡحُسۡنَى ٣١',
    31, 27, 7, 527, 461, 211, 'false'
  );
  
  -- Ayah 32 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4816,
    'ٱلَّذِینَ یَجۡتَنِبُونَ كَبَـٰۤىِٕرَ ٱلۡإِثۡمِ وَٱلۡفَوَ ٰ⁠حِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَ ٰ⁠سِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةࣱ فِی بُطُونِ أُمَّهَـٰتِكُمۡۖ فَلَا تُزَكُّوۤا۟ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰۤ',
    'الذين يجتنبون كبائر الاثم والفواحش الا اللمم ان ربك واسع المغفرة هو اعلم بكم اذ انشاكم من الارض واذ انتم اجنة في بطون امهاتكم فلا تزكوا انفسكم هو اعلم بمن اتقى',
    'ٱلَّذِينَ يَ<rule class=qalaqah>جۡ</rule>تَنِبُونَ كَبَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِرَ <rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَ<rule class=ham_wasl>ٱ</rule>لۡفَو<rule class=madda_normal>ٰ</rule>حِشَ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّمَمَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ و<rule class=madda_normal>ٰ</rule>سِعُ <rule class=ham_wasl>ٱ</rule>لۡمَغۡفِرَةِ‌ۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَ<rule class=ikhafa>نش</rule>َأَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَإِذۡ أَ<rule class=ikhafa>نت</rule>ُمۡ أَجِ<rule class=ghunnah>نّ</rule>َ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى بُطُونِ أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تِكُمۡ‌ۖ فَلَا تُزَكّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ‌ۖ هُوَ أَعۡلَمُ بِمَنِ <rule class=ham_wasl>ٱ</rule>تَّقَىٰٓ ٣٢',
    32, 27, 7, 527, 461, 211, 'false'
  );
  
  -- Ayah 33 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4817,
    'أَفَرَءَیۡتَ ٱلَّذِی تَوَلَّىٰ',
    'افرايت الذي تولى',
    'أَفَرَءَيۡتَ <rule class=ham_wasl>ٱ</rule>لَّذِى تَوَلَّىٰ ٣٣',
    33, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 34 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4818,
    'وَأَعۡطَىٰ قَلِیلࣰا وَأَكۡدَىٰۤ',
    'واعطى قليلا واكدى',
    'وَأَعۡطَىٰ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َأَكۡدَىٰٓ ٣٤',
    34, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 35 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4819,
    'أَعِندَهُۥ عِلۡمُ ٱلۡغَیۡبِ فَهُوَ یَرَىٰۤ',
    'اعنده علم الغيب فهو يرى',
    'أَعِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_normal>ۥ</rule> عِلۡمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ فَهُوَ يَرَىٰٓ ٣٥',
    35, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 36 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4820,
    'أَمۡ لَمۡ یُنَبَّأۡ بِمَا فِی صُحُفِ مُوسَىٰ',
    'ام لم ينبا بما في صحف موسى',
    'أَمۡ لَمۡ يُنَبَّأۡ بِمَا فِى صُحُفِ مُوسَىٰ ٣٦',
    36, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 37 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4821,
    'وَإِبۡرَ ٰ⁠هِیمَ ٱلَّذِی وَفَّىٰۤ',
    'وابراهيم الذي وفى',
    'وَإِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ <rule class=ham_wasl>ٱ</rule>لَّذِى وَفَّىٰٓ ٣٧',
    37, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 38 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4822,
    'أَلَّا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰ',
    'الا تزر وازرة وزر اخرى',
    'أَلَّا تَزِرُ وَازِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>ِزۡرَ أُخۡرَىٰ ٣٨',
    38, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 39 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4823,
    'وَأَن لَّیۡسَ لِلۡإِنسَـٰنِ إِلَّا مَا سَعَىٰ',
    'وان ليس للانسان الا ما سعى',
    'وَأ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّيۡسَ لِلۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ إِلَّا مَا سَعَىٰ ٣٩',
    39, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 40 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4824,
    'وَأَنَّ سَعۡیَهُۥ سَوۡفَ یُرَىٰ',
    'وان سعيه سوف يرى',
    'وَأَ<rule class=ghunnah>نّ</rule>َ سَعۡيَهُ<rule class=madda_normal>ۥ</rule> سَوۡفَ يُرَىٰ ٤٠',
    40, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 41 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4825,
    'ثُمَّ یُجۡزَىٰهُ ٱلۡجَزَاۤءَ ٱلۡأَوۡفَىٰ',
    'ثم يجزاه الجزاء الاوفى',
    'ثُ<rule class=ghunnah>مّ</rule>َ يُ<rule class=qalaqah>جۡ</rule>زَ<rule class=madda_normal>ٮٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>لۡجَز<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>لۡأَوۡفَىٰ ٤١',
    41, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 42 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4826,
    'وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ',
    'وان الى ربك المنتهى',
    'وَأَ<rule class=ghunnah>نّ</rule>َ إِلَىٰ رَبِّكَ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نت</rule>َهَىٰ ٤٢',
    42, 27, 7, 527, 462, 211, 'false'
  );
  
  -- Ayah 43 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
