  -- Ayah 45 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4829,
    'وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَیۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ',
    'وانه خلق الزوجين الذكر والانثى',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّوۡجَيۡنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذَّكَرَ وَ<rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َىٰ ٤٥',
    45, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 46 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4830,
    'مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ',
    'من نطفة اذا تمنى',
    'م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّ<rule class=qalaqah>طۡ</rule>فَةٍ إِذَا تُمۡنَىٰ ٤٦',
    46, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 47 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
