    'وانه هو اغنى واقنى',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ أَغۡنَىٰ وَأَ<rule class=qalaqah>قۡ</rule>نَىٰ ٤٨',
    48, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 49 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4833,
    'وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ',
    'وانه هو رب الشعرى',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> هُوَ رَبُّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شِّعۡرَىٰ ٤٩',
    49, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 50 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4834,
    'وَأَنَّهُۥۤ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ',
    'وانه اهلك عادا الاولى',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَهۡلَكَ عَادًا <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰ ٥٠',
    50, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 51 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4835,
    'وَثَمُودَا۟ فَمَاۤ أَبۡقَىٰ',
    'وثمود فما ابقى',
    'وَثَمُودَ<rule class=slnt>اۡ</rule> فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>قَىٰ ٥١',
    51, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 52 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4836,
    'وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُوا۟ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ',
    'وقوم نوح من قبل انهم كانوا هم اظلم واطغى',
    'وَقَوۡمَ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ كَانُو<rule class=slnt>اۡ</rule> هُمۡ أَظۡلَمَ وَأَ<rule class=qalaqah>طۡ</rule>غَىٰ ٥٢',
    52, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 53 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4837,
    'وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ',
    'والمؤتفكة اهوى',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡتَفِكَةَ أَهۡوَىٰ ٥٣',
    53, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 54 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4838,
    'فَغَشَّىٰهَا مَا غَشَّىٰ',
    'فغشاها ما غشى',
    'فَغَشَّ<rule class=madda_normal>ـٰ</rule>هَا مَا غَشَّىٰ ٥٤',
    54, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 55 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4839,
    'فَبِأَیِّ ءَالَاۤءِ رَبِّكَ تَتَمَارَىٰ',
    'فباي الاء ربك تتمارى',
    'فَبِأَىِّ ءَال<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ رَبِّكَ تَتَمَارَىٰ ٥٥',
    55, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 56 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4840,
    'هَـٰذَا نَذِیرࣱ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰۤ',
    'هذا نذير من النذر الاولى',
    'هَ<rule class=madda_normal>ـٰ</rule>ذَا نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُذُرِ <rule class=ham_wasl>ٱ</rule>لۡأُولَىٰٓ ٥٦',
    56, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 57 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4841,
    'أَزِفَتِ ٱلۡـَٔازِفَةُ',
    'ازفت الازفة',
    'أَزِفَتِ <rule class=ham_wasl>ٱ</rule>لۡأَزِفَةُ ٥٧',
    57, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 58 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4842,
    'لَیۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ',
    'ليس لها من دون الله كاشفة',
    'لَيۡسَ لَهَا مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ كَاشِفَةٌ ٥٨',
    58, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 59 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4843,
    'أَفَمِنۡ هَـٰذَا ٱلۡحَدِیثِ تَعۡجَبُونَ',
    'افمن هذا الحديث تعجبون',
    'أَفَمِنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡحَدِيثِ تَعۡجَب<rule class=madda_permissible>ُو</rule>نَ ٥٩',
    59, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 60 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4844,
    'وَتَضۡحَكُونَ وَلَا تَبۡكُونَ',
    'وتضحكون ولا تبكون',
    'وَتَضۡحَكُونَ وَلَا تَ<rule class=qalaqah>بۡ</rule>ك<rule class=madda_permissible>ُو</rule>نَ ٦٠',
    60, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 61 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4845,
    'وَأَنتُمۡ سَـٰمِدُونَ',
    'وانتم سامدون',
    'وَأَ<rule class=ikhafa>نت</rule>ُمۡ سَ<rule class=madda_normal>ـٰ</rule>مِد<rule class=madda_permissible>ُو</rule>نَ ٦١',
    61, 27, 7, 528, 462, 211, 'false'
  );
  
  -- Ayah 62 Surah An-Najm
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    53,
    4846,
    'فَٱسۡجُدُوا۟ لِلَّهِ وَٱعۡبُدُوا۟ ۩',
    'فاسجدوا لله واعبدوا',
    'فَ<rule class=ham_wasl>ٱ</rule>سۡجُدُو<rule class=slnt>اۡ</rule> لِلَّهِ وَ<rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> ۩ ٦٢',
    62, 27, 7, 528, 462, 211, '{"id":13,"recommended":false,"obligatory":true}'
  );
  

-- Surah Al-Qamar
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (54, 'سُورَةُ القَمَرِ', 'Al-Qamar', 'The Moon', 'Meccan', 55);

  -- Ayah 1 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4847,
    'ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ',
    'اقتربت الساعة وانشق القمر',
    'ٱ<rule class=qalaqah>قۡ</rule>تَرَبَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نش</rule>َقَّ <rule class=ham_wasl>ٱ</rule>لۡقَمَرُ ١',
    1, 27, 7, 528, 463, 211, 'false'
  );
  
  -- Ayah 2 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4848,
    'وَإِن یَرَوۡا۟ ءَایَةࣰ یُعۡرِضُوا۟ وَیَقُولُوا۟ سِحۡرࣱ مُّسۡتَمِرࣱّ',
    'وان يروا اية يعرضوا ويقولوا سحر مستمر',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َرَوۡ<rule class=slnt>اۡ</rule> ءَايَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ي</rule>ُعۡرِضُو<rule class=slnt>اۡ</rule> وَيَقُولُو<rule class=slnt>اۡ</rule> سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَمِرٌّ ٢',
    2, 27, 7, 528, 463, 211, 'false'
  );
  
  -- Ayah 3 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4849,
    'وَكَذَّبُوا۟ وَٱتَّبَعُوۤا۟ أَهۡوَاۤءَهُمۡۚ وَكُلُّ أَمۡرࣲ مُّسۡتَقِرࣱّ',
    'وكذبوا واتبعوا اهواءهم وكل امر مستقر',
    'وَكَذَّبُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّبَع<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَهۡو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ‌ۚ وَكُلُّ أَمۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقِرٌّ ٣',
    3, 27, 7, 528, 463, 211, 'false'
  );
  
  -- Ayah 4 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4850,
    'وَلَقَدۡ جَاۤءَهُم مِّنَ ٱلۡأَنۢبَاۤءِ مَا فِیهِ مُزۡدَجَرٌ',
    'ولقد جاءهم من الانباء ما فيه مزدجر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=iqlab>نۢب</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مَا فِيهِ مُزۡدَجَرٌ ٤',
    4, 27, 7, 528, 463, 211, 'false'
  );
  
  -- Ayah 5 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4851,
    'حِكۡمَةُۢ بَـٰلِغَةࣱۖ فَمَا تُغۡنِ ٱلنُّذُرُ',
    'حكمة بالغة فما تغن النذر',
    'حِكۡمَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>َ<rule class=madda_normal>ـٰ</rule>لِغَ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َمَا تُغۡنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُذُرُ ٥',
    5, 27, 7, 528, 463, 211, 'false'
  );
  
  -- Ayah 6 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4852,
    'فَتَوَلَّ عَنۡهُمۡۘ یَوۡمَ یَدۡعُ ٱلدَّاعِ إِلَىٰ شَیۡءࣲ نُّكُرٍ',
    'فتول عنهم يوم يدع الداع الى شيء نكر',
    'فَتَوَلَّ عَنۡهُمۡ‌ۘ يَوۡمَ يَ<rule class=qalaqah>دۡ</rule>عُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّاعِ إِلَىٰ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>ن</rule>ُّكُرٍ ٦',
    6, 27, 7, 528, 463, 211, 'false'
  );
  
  -- Ayah 7 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4853,
    'خُشَّعًا أَبۡصَـٰرُهُمۡ یَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادࣱ مُّنتَشِرࣱ',
    'خشعا ابصارهم يخرجون من الاجداث كانهم جراد منتشر',
    'خُشَّعًا أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُهُمۡ يَخۡرُجُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>جۡ</rule>دَاثِ كَأَ<rule class=ghunnah>نّ</rule>َهُمۡ جَرَا<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=ikhafa>نت</rule>َشِرٌ ٧',
    7, 27, 7, 529, 463, 211, 'false'
  );
  
  -- Ayah 8 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4854,
    'مُّهۡطِعِینَ إِلَى ٱلدَّاعِۖ یَقُولُ ٱلۡكَـٰفِرُونَ هَـٰذَا یَوۡمٌ عَسِرࣱ',
    'مهطعين الى الداع يقول الكافرون هذا يوم عسر',
    'مُّهۡطِعِينَ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّاعِ‌ۖ يَقُولُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرُونَ هَ<rule class=madda_normal>ـٰ</rule>ذَا يَوۡمٌ عَسِرٌ ٨',
    8, 27, 7, 529, 463, 211, 'false'
  );
  
  -- Ayah 9 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4855,
    '۞ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ فَكَذَّبُوا۟ عَبۡدَنَا وَقَالُوا۟ مَجۡنُونࣱ وَٱزۡدُجِرَ',
    'كذبت قبلهم قوم نوح فكذبوا عبدنا وقالوا مجنون وازدجر',
    '۞كَذَّبَتۡ قَ<rule class=qalaqah>بۡ</rule>لَهُمۡ قَوۡمُ نُو<rule class=ikhafa>حٍ</rule> <rule class=ikhafa>ف</rule>َكَذَّبُو<rule class=slnt>اۡ</rule> عَ<rule class=qalaqah>بۡ</rule>دَنَا وَقَالُو<rule class=slnt>اۡ</rule> مَ<rule class=qalaqah>جۡ</rule>نُو<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>زۡدُجِرَ ٩',
    9, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 10 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4856,
    'فَدَعَا رَبَّهُۥۤ أَنِّی مَغۡلُوبࣱ فَٱنتَصِرۡ',
    'فدعا ربه اني مغلوب فانتصر',
    'فَدَعَا رَبَّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=ghunnah>نّ</rule>ِى مَغۡلُو<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َصِرۡ ١٠',
    10, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 11 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4857,
    'فَفَتَحۡنَاۤ أَبۡوَ ٰ⁠بَ ٱلسَّمَاۤءِ بِمَاۤءࣲ مُّنۡهَمِرࣲ',
    'ففتحنا ابواب السماء بماء منهمر',
    'فَفَتَحۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>بۡ</rule>و<rule class=madda_normal>ٰ</rule>بَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ بِم<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّنۡهَمِرٍ ١١',
    11, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 12 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4858,
    'وَفَجَّرۡنَا ٱلۡأَرۡضَ عُیُونࣰا فَٱلۡتَقَى ٱلۡمَاۤءُ عَلَىٰۤ أَمۡرࣲ قَدۡ قُدِرَ',
    'وفجرنا الارض عيونا فالتقى الماء على امر قد قدر',
    'وَفَجَّرۡنَا <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ عُيُو<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>لۡتَقَى <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَمۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> قُدِرَ ١٢',
    12, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 13 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4859,
    'وَحَمَلۡنَـٰهُ عَلَىٰ ذَاتِ أَلۡوَ ٰ⁠حࣲ وَدُسُرࣲ',
    'وحملناه على ذات الواح ودسر',
    'وَحَمَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ عَلَىٰ ذَاتِ أَلۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َدُسُرٍ ١٣',
    13, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 14 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4860,
    'تَجۡرِی بِأَعۡیُنِنَا جَزَاۤءࣰ لِّمَن كَانَ كُفِرَ',
    'تجري باعيننا جزاء لمن كان كفر',
    'تَ<rule class=qalaqah>جۡ</rule>رِى بِأَعۡيُنِنَا جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_wo_ghunnah>ءً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ كُفِرَ ١٤',
    14, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 15 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4861,
    'وَلَقَد تَّرَكۡنَـٰهَاۤ ءَایَةࣰ فَهَلۡ مِن مُّدَّكِرࣲ',
    'ولقد تركناها اية فهل من مدكر',
    'وَلَقَ<rule class=idgham_mutajanisayn>د</rule> تَّرَكۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َهَلۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّدَّكِرٍ ١٥',
    15, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 16 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4862,
    'فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ',
    'فكيف كان عذابي ونذر',
    'فَكَيۡفَ كَانَ عَذَابِى وَنُذُرِ ١٦',
    16, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 17 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4863,
    'وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ',
    'ولقد يسرنا القران للذكر فهل من مدكر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> يَسَّرۡنَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّدَّكِرٍ ١٧',
    17, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 18 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4864,
    'كَذَّبَتۡ عَادࣱ فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ',
    'كذبت عاد فكيف كان عذابي ونذر',
    'كَذَّبَتۡ عَا<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َكَيۡفَ كَانَ عَذَابِى وَنُذُرِ ١٨',
    18, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 19 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4865,
    'إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ رِیحࣰا صَرۡصَرࣰا فِی یَوۡمِ نَحۡسࣲ مُّسۡتَمِرࣲّ',
    'انا ارسلنا عليهم ريحا صرصرا في يوم نحس مستمر',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا عَلَيۡهِمۡ رِي<rule class=ikhafa>حًا</rule> <rule class=ikhafa>ص</rule>َرۡصَ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>ِى يَوۡمِ نَحۡ<rule class=idgham_ghunnah>سٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَمِرٍّ ١٩',
    19, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 20 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4866,
    'تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلࣲ مُّنقَعِرࣲ',
    'تنزع الناس كانهم اعجاز نخل منقعر',
    'تَ<rule class=ikhafa>نز</rule>ِعُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ كَأَ<rule class=ghunnah>نّ</rule>َهُمۡ أَعۡجَازُ نَخۡ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=ikhafa>نق</rule>َعِرٍ ٢٠',
    20, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 21 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4867,
    'فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ',
    'فكيف كان عذابي ونذر',
    'فَكَيۡفَ كَانَ عَذَابِى وَنُذُرِ ٢١',
    21, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 22 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4868,
    'وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ',
    'ولقد يسرنا القران للذكر فهل من مدكر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> يَسَّرۡنَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّدَّكِرٍ ٢٢',
    22, 27, 7, 529, 463, 212, 'false'
  );
  
  -- Ayah 23 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4869,
    'كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ',
    'كذبت ثمود بالنذر',
    'كَذَّبَتۡ ثَمُودُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُذُرِ ٢٣',
    23, 27, 7, 529, 464, 212, 'false'
  );
  
  -- Ayah 24 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4870,
    'فَقَالُوۤا۟ أَبَشَرࣰا مِّنَّا وَ ٰ⁠حِدࣰا نَّتَّبِعُهُۥۤ إِنَّاۤ إِذࣰا لَّفِی ضَلَـٰلࣲ وَسُعُرٍ',
    'فقالوا ابشرا منا واحدا نتبعه انا اذا لفي ضلال وسعر',
    'فَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَبَشَ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>نّ</rule>َا و<rule class=madda_normal>ٰ</rule>حِ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>ن</rule>َّتَّبِعُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=idgham_wo_ghunnah>ذًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّفِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َسُعُرٍ ٢٤',
    24, 27, 7, 529, 464, 212, 'false'
  );
  
  -- Ayah 25 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4871,
    'أَءُلۡقِیَ ٱلذِّكۡرُ عَلَیۡهِ مِنۢ بَیۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرࣱ',
    'االقي الذكر عليه من بيننا بل هو كذاب اشر',
    'أَءُلۡقِىَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرُ عَلَيۡهِ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرٌ ٢٥',
    25, 27, 7, 529, 464, 212, 'false'
  );
  
  -- Ayah 26 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4872,
    'سَیَعۡلَمُونَ غَدࣰا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ',
    'سيعلمون غدا من الكذاب الاشر',
    'سَيَعۡلَمُونَ غَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>م</rule>َّنِ <rule class=ham_wasl>ٱ</rule>لۡكَذَّابُ <rule class=ham_wasl>ٱ</rule>لۡأَشِرُ ٢٦',
    26, 27, 7, 529, 464, 212, 'false'
  );
  
  -- Ayah 27 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4873,
    'إِنَّا مُرۡسِلُوا۟ ٱلنَّاقَةِ فِتۡنَةࣰ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ',
    'انا مرسلو الناقة فتنة لهم فارتقبهم واصطبر',
    'إِ<rule class=ghunnah>نّ</rule>َا مُرۡسِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاقَةِ فِتۡنَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ فَ<rule class=ham_wasl>ٱ</rule>رۡتَقِ<rule class=qalaqah>بۡ</rule>هُمۡ وَ<rule class=ham_wasl>ٱ</rule>صۡطَبِرۡ ٢٧',
    27, 27, 7, 529, 464, 212, 'false'
  );
  
  -- Ayah 28 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4874,
    'وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَاۤءَ قِسۡمَةُۢ بَیۡنَهُمۡۖ كُلُّ شِرۡبࣲ مُّحۡتَضَرࣱ',
    'ونبئهم ان الماء قسمة بينهم كل شرب محتضر',
    'وَنَبِّئۡهُمۡ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ قِسۡمَ<rule class=iqlab>ةُۢ</rule> <rule class=iqlab>ب</rule>َيۡنَهُمۡ‌ۖ كُلُّ شِرۡ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّحۡتَضَرٌ ٢٨',
    28, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 29 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4875,
    'فَنَادَوۡا۟ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ',
    'فنادوا صاحبهم فتعاطى فعقر',
    'فَنَادَوۡ<rule class=slnt>اۡ</rule> صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ ٢٩',
    29, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 30 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4876,
    'فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ',
    'فكيف كان عذابي ونذر',
    'فَكَيۡفَ كَانَ عَذَابِى وَنُذُرِ ٣٠',
    30, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 31 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4877,
    'إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ صَیۡحَةࣰ وَ ٰ⁠حِدَةࣰ فَكَانُوا۟ كَهَشِیمِ ٱلۡمُحۡتَظِرِ',
    'انا ارسلنا عليهم صيحة واحدة فكانوا كهشيم المحتظر',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا عَلَيۡهِمۡ صَيۡحَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َكَانُو<rule class=slnt>اۡ</rule> كَهَشِيمِ <rule class=ham_wasl>ٱ</rule>لۡمُحۡتَظِرِ ٣١',
    31, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 32 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4878,
    'وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ',
    'ولقد يسرنا القران للذكر فهل من مدكر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> يَسَّرۡنَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّدَّكِرٍ ٣٢',
    32, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 33 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4879,
    'كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ',
    'كذبت قوم لوط بالنذر',
    'كَذَّبَتۡ قَوۡمُ لُو<rule class=iqlab>طِۭ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُذُرِ ٣٣',
    33, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 34 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4880,
    'إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ حَاصِبًا إِلَّاۤ ءَالَ لُوطࣲۖ نَّجَّیۡنَـٰهُم بِسَحَرࣲ',
    'انا ارسلنا عليهم حاصبا الا ال لوط نجيناهم بسحر',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا عَلَيۡهِمۡ حَاصِبًا إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> ءَالَ لُو<rule class=idgham_ghunnah>طٍ‌ۖ</rule> <rule class=idgham_ghunnah>ن</rule>َّجَّيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسَحَرٍ ٣٤',
    34, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 35 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4881,
    'نِّعۡمَةࣰ مِّنۡ عِندِنَاۚ كَذَ ٰ⁠لِكَ نَجۡزِی مَن شَكَرَ',
    'نعمة من عندنا كذلك نجزي من شكر',
    'نِّعۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ عِ<rule class=ikhafa>ند</rule>ِنَا‌ۚ كَذ<rule class=madda_normal>ٰ</rule>لِكَ نَ<rule class=qalaqah>جۡ</rule>زِى مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َكَرَ ٣٥',
    35, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 36 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4882,
    'وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡا۟ بِٱلنُّذُرِ',
    'ولقد انذرهم بطشتنا فتماروا بالنذر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نذ</rule>َرَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َ<rule class=qalaqah>طۡ</rule>شَتَنَا فَتَمَارَوۡ<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُذُرِ ٣٦',
    36, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 37 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4883,
    'وَلَقَدۡ رَ ٰ⁠وَدُوهُ عَن ضَیۡفِهِۦ فَطَمَسۡنَاۤ أَعۡیُنَهُمۡ فَذُوقُوا۟ عَذَابِی وَنُذُرِ',
    'ولقد راودوه عن ضيفه فطمسنا اعينهم فذوقوا عذابي ونذر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ر<rule class=madda_normal>ٰ</rule>وَدُوهُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َيۡفِه<rule class=madda_normal>ِۦ</rule> فَطَمَسۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡيُنَهُمۡ فَذُوقُو<rule class=slnt>اۡ</rule> عَذَابِى وَنُذُرِ ٣٧',
    37, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 38 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4884,
    'وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابࣱ مُّسۡتَقِرࣱّ',
    'ولقد صبحهم بكرة عذاب مستقر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> صَبَّحَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ُكۡرَةً عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَقِرٌّ ٣٨',
    38, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 39 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4885,
    'فَذُوقُوا۟ عَذَابِی وَنُذُرِ',
    'فذوقوا عذابي ونذر',
    'فَذُوقُو<rule class=slnt>اۡ</rule> عَذَابِى وَنُذُرِ ٣٩',
    39, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 40 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4886,
    'وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ',
    'ولقد يسرنا القران للذكر فهل من مدكر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> يَسَّرۡنَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّدَّكِرٍ ٤٠',
    40, 27, 7, 530, 464, 212, 'false'
  );
  
  -- Ayah 41 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4887,
    'وَلَقَدۡ جَاۤءَ ءَالَ فِرۡعَوۡنَ ٱلنُّذُرُ',
    'ولقد جاء ال فرعون النذر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ءَالَ فِرۡعَوۡنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُذُرُ ٤١',
    41, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 42 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4888,
    'كَذَّبُوا۟ بِـَٔایَـٰتِنَا كُلِّهَا فَأَخَذۡنَـٰهُمۡ أَخۡذَ عَزِیزࣲ مُّقۡتَدِرٍ',
    'كذبوا باياتنا كلها فاخذناهم اخذ عزيز مقتدر',
    'كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا كُلِّهَا فَأَخَذۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ أَخۡذَ عَزِي<rule class=idgham_ghunnah>زٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَدِرٍ ٤٢',
    42, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 43 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4889,
    'أَكُفَّارُكُمۡ خَیۡرࣱ مِّنۡ أُو۟لَـٰۤىِٕكُمۡ أَمۡ لَكُم بَرَاۤءَةࣱ فِی ٱلزُّبُرِ',
    'اكفاركم خير من اولئكم ام لكم براءة في الزبر',
    'أَكُفَّارُكُمۡ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكُمۡ أَمۡ لَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زُّبُرِ ٤٣',
    43, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 44 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4890,
    'أَمۡ یَقُولُونَ نَحۡنُ جَمِیعࣱ مُّنتَصِرࣱ',
    'ام يقولون نحن جميع منتصر',
    'أَمۡ يَقُولُونَ نَحۡنُ جَمِي<rule class=idgham_ghunnah>عٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=ikhafa>نت</rule>َصِرٌ ٤٤',
    44, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 45 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4891,
    'سَیُهۡزَمُ ٱلۡجَمۡعُ وَیُوَلُّونَ ٱلدُّبُرَ',
    'سيهزم الجمع ويولون الدبر',
    'سَيُهۡزَمُ <rule class=ham_wasl>ٱ</rule>لۡجَمۡعُ وَيُوَلُّونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّبُرَ ٤٥',
    45, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 46 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4892,
    'بَلِ ٱلسَّاعَةُ مَوۡعِدُهُمۡ وَٱلسَّاعَةُ أَدۡهَىٰ وَأَمَرُّ',
    'بل الساعة موعدهم والساعة ادهى وامر',
    'بَلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ مَوۡعِدُهُمۡ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاعَةُ أَ<rule class=qalaqah>دۡ</rule>هَىٰ وَأَمَرُّ ٤٦',
    46, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 47 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4893,
    'إِنَّ ٱلۡمُجۡرِمِینَ فِی ضَلَـٰلࣲ وَسُعُرࣲ',
    'ان المجرمين في ضلال وسعر',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِمِينَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َسُعُرٍ ٤٧',
    47, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 48 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4894,
    'یَوۡمَ یُسۡحَبُونَ فِی ٱلنَّارِ عَلَىٰ وُجُوهِهِمۡ ذُوقُوا۟ مَسَّ سَقَرَ',
    'يوم يسحبون في النار على وجوههم ذوقوا مس سقر',
    'يَوۡمَ يُسۡحَبُونَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ عَلَىٰ وُجُوهِهِمۡ ذُوقُو<rule class=slnt>اۡ</rule> مَسَّ سَقَرَ ٤٨',
    48, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 49 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4895,
    'إِنَّا كُلَّ شَیۡءٍ خَلَقۡنَـٰهُ بِقَدَرࣲ',
    'انا كل شيء خلقناه بقدر',
    'إِ<rule class=ghunnah>نّ</rule>َا كُلَّ شَىۡءٍ خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ بِقَدَرٍ ٤٩',
    49, 27, 7, 530, 465, 212, 'false'
  );
  
  -- Ayah 50 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4896,
    'وَمَاۤ أَمۡرُنَاۤ إِلَّا وَ ٰ⁠حِدَةࣱ كَلَمۡحِۭ بِٱلۡبَصَرِ',
    'وما امرنا الا واحدة كلمح بالبصر',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡرُن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا و<rule class=madda_normal>ٰ</rule>حِدَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ك</rule>َلَمۡ<rule class=iqlab>حِۭ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَصَرِ ٥٠',
    50, 27, 7, 531, 465, 212, 'false'
  );
  
  -- Ayah 51 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4897,
    'وَلَقَدۡ أَهۡلَكۡنَاۤ أَشۡیَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرࣲ',
    'ولقد اهلكنا اشياعكم فهل من مدكر',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَهۡلَكۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَشۡيَاعَكُمۡ فَهَلۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّدَّكِرٍ ٥١',
    51, 27, 7, 531, 465, 212, 'false'
  );
  
  -- Ayah 52 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4898,
    'وَكُلُّ شَیۡءࣲ فَعَلُوهُ فِی ٱلزُّبُرِ',
    'وكل شيء فعلوه في الزبر',
    'وَكُلُّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ف</rule>َعَلُوهُ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زُّبُرِ ٥٢',
    52, 27, 7, 531, 465, 212, 'false'
  );
  
  -- Ayah 53 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4899,
    'وَكُلُّ صَغِیرࣲ وَكَبِیرࣲ مُّسۡتَطَرٌ',
    'وكل صغير وكبير مستطر',
    'وَكُلُّ صَغِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َكَبِي<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَطَرٌ ٥٣',
    53, 27, 7, 531, 465, 212, 'false'
  );
  
  -- Ayah 54 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4900,
    'إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَنَهَرࣲ',
    'ان المتقين في جنات ونهر',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُتَّقِينَ فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َنَهَرٍ ٥٤',
    54, 27, 7, 531, 465, 212, 'false'
  );
  
  -- Ayah 55 Surah Al-Qamar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    54,
    4901,
    'فِی مَقۡعَدِ صِدۡقٍ عِندَ مَلِیكࣲ مُّقۡتَدِرِۭ',
    'في مقعد صدق عند مليك مقتدر',
    'فِى مَ<rule class=qalaqah>قۡ</rule>عَدِ صِ<rule class=qalaqah>دۡ</rule>قٍ عِ<rule class=ikhafa>ند</rule>َ مَلِي<rule class=idgham_ghunnah>كٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّ<rule class=qalaqah>قۡ</rule>تَدِرِۭ ٥٥',
    55, 27, 7, 531, 465, 212, 'false'
  );
  

-- Surah Ar-Rahmaan
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (55, 'سُورَةُ الرَّحۡمَٰن', 'Ar-Rahmaan', 'The Beneficent', 'Medinan', 78);

  -- Ayah 1 Surah Ar-Rahmaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    55,
    4902,
    'ٱلرَّحۡمَـٰنُ',
    'الرحمن',
    'ٱ<rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_permissible>ـٰ</rule>نُ ١',
    1, 27, 7, 531, 466, 213, 'false'
  );
  
  -- Ayah 2 Surah Ar-Rahmaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    55,
    4903,
    'عَلَّمَ ٱلۡقُرۡءَانَ',
    'علم القران',
    'عَلَّمَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡء<rule class=madda_permissible>َا</rule>نَ ٢',
    2, 27, 7, 531, 466, 213, 'false'
  );
  
  -- Ayah 3 Surah Ar-Rahmaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    55,
    4904,
    'خَلَقَ ٱلۡإِنسَـٰنَ',
    'خلق الانسان',
    'خَلَقَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_permissible>ـٰ</rule>نَ ٣',
    3, 27, 7, 531, 466, 213, 'false'
  );
  
  -- Ayah 4 Surah Ar-Rahmaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    55,
    4905,
    'عَلَّمَهُ ٱلۡبَیَانَ',
    'علمه البيان',
    'عَلَّمَهُ <rule class=ham_wasl>ٱ</rule>لۡبَي<rule class=madda_permissible>َا</rule>نَ ٤',
    4, 27, 7, 531, 466, 213, 'false'
  );
  
  -- Ayah 5 Surah Ar-Rahmaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    55,
    4906,
    'ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانࣲ',
    'الشمس والقمر بحسبان',
    'ٱ<rule class=laam_shamsiyah>ل</rule>شَّمۡسُ وَ<rule class=ham_wasl>ٱ</rule>لۡقَمَرُ بِحُسۡب<rule class=madda_permissible>َا</rule>نٍ ٥',
    5, 27, 7, 531, 466, 213, 'false'
  );
  
  -- Ayah 6 Surah Ar-Rahmaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    55,
    4907,
    'وَٱلنَّجۡمُ وَٱلشَّجَرُ یَسۡجُدَانِ',
    'والنجم والشجر يسجدان',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=qalaqah>جۡ</rule>مُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّجَرُ يَسۡجُد<rule class=madda_permissible>َا</rule>نِ ٦',
    6, 27, 7, 531, 466, 213, 'false'
  );
  
  -- Ayah 7 Surah Ar-Rahmaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    55,
    4908,
    'وَٱلسَّمَاۤءَ رَفَعَهَا وَوَضَعَ ٱلۡمِیزَانَ',
    'والسماء رفعها ووضع الميزان',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَفَعَهَا وَوَضَعَ <rule class=ham_wasl>ٱ</rule>لۡمِيز<rule class=madda_permissible>َا</rule>نَ ٧',
    7, 27, 7, 531, 466, 213, 'false'
