  -- Ayah 69 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5048,
    'ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ',
    'اانتم انزلتموه من المزن ام نحن المنزلون',
    'ءَأَ<rule class=ikhafa>نت</rule>ُمۡ أَ<rule class=ikhafa>نز</rule>َلۡتُمُوهُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُزۡنِ أَمۡ نَحۡنُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=ikhafa>نز</rule>ِل<rule class=madda_permissible>ُو</rule>نَ ٦٩',
    69, 27, 7, 536, 470, 214, 'false'
  );
  
  -- Ayah 70 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5049,
    'لَوۡ نَشَاۤءُ جَعَلۡنَـٰهُ أُجَاجࣰا فَلَوۡلَا تَشۡكُرُونَ',
    'لو نشاء جعلناه اجاجا فلولا تشكرون',
    'لَوۡ نَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ جَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ أُجَا<rule class=ikhafa>جًا</rule> <rule class=ikhafa>ف</rule>َلَوۡلَا تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٧٠',
    70, 27, 7, 536, 470, 214, 'false'
