    'فسبح باسم ربك العظيم',
    'فَسَبِّحۡ بِ<rule class=ham_wasl>ٱ</rule>سۡمِ رَبِّكَ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٧٤',
    74, 27, 7, 536, 470, 214, 'false'
  );
  
  -- Ayah 75 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5054,
