    '۞فَل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=qalaqah>قۡ</rule>سِمُ بِمَو<rule class=madda_normal>ٰ</rule>قِعِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُج<rule class=madda_permissible>ُو</rule>مِ ٧٥',
    75, 27, 7, 536, 471, 215, 'false'
  );
  
  -- Ayah 76 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
