    'انه لقران كريم',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَقُرۡءَا<rule class=ikhafa>نٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ٧٧',
    77, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 78 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
