    5057,
    'فِی كِتَـٰبࣲ مَّكۡنُونࣲ',
    'في كتاب مكنون',
    'فِى كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>َّكۡن<rule class=madda_permissible>ُو</rule>نٍ ٧٨',
    78, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 79 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5058,
    'لَّا یَمَسُّهُۥۤ إِلَّا ٱلۡمُطَهَّرُونَ',
    'لا يمسه الا المطهرون',
    'لَّا يَمَسُّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡمُطَهَّر<rule class=madda_permissible>ُو</rule>نَ ٧٩',
    79, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 80 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5059,
    'تَنزِیلࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ',
    'تنزيل من رب العالمين',
    'تَ<rule class=ikhafa>نز</rule>ِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٨٠',
    80, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 81 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5060,
    'أَفَبِهَـٰذَا ٱلۡحَدِیثِ أَنتُم مُّدۡهِنُونَ',
    'افبهذا الحديث انتم مدهنون',
    'أَفَبِهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡحَدِيثِ أَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّ<rule class=qalaqah>دۡ</rule>هِن<rule class=madda_permissible>ُو</rule>نَ ٨١',
    81, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 82 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5061,
    'وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ',
    'وتجعلون رزقكم انكم تكذبون',
    'وَتَ<rule class=qalaqah>جۡ</rule>عَلُونَ رِزۡقَكُمۡ أَ<rule class=ghunnah>نّ</rule>َكُمۡ تُكَذِّب<rule class=madda_permissible>ُو</rule>نَ ٨٢',
    82, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 83 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5062,
    'فَلَوۡلَاۤ إِذَا بَلَغَتِ ٱلۡحُلۡقُومَ',
    'فلولا اذا بلغت الحلقوم',
    'فَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا بَلَغَتِ <rule class=ham_wasl>ٱ</rule>لۡحُلۡق<rule class=madda_permissible>ُو</rule>مَ ٨٣',
    83, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 84 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5063,
    'وَأَنتُمۡ حِینَىِٕذࣲ تَنظُرُونَ',
    'وانتم حينئذ تنظرون',
    'وَأَ<rule class=ikhafa>نت</rule>ُمۡ حِينَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ٨٤',
    84, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 85 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5064,
    'وَنَحۡنُ أَقۡرَبُ إِلَیۡهِ مِنكُمۡ وَلَـٰكِن لَّا تُبۡصِرُونَ',
    'ونحن اقرب اليه منكم ولكن لا تبصرون',
    'وَنَحۡنُ أَ<rule class=qalaqah>قۡ</rule>رَبُ إِلَيۡهِ مِ<rule class=ikhafa>نك</rule>ُمۡ وَلَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٨٥',
    85, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 86 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5065,
    'فَلَوۡلَاۤ إِن كُنتُمۡ غَیۡرَ مَدِینِینَ',
    'فلولا ان كنتم غير مدينين',
    'فَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ غَيۡرَ مَدِين<rule class=madda_permissible>ِي</rule>نَ ٨٦',
    86, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 87 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5066,
    'تَرۡجِعُونَهَاۤ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ترجعونها ان كنتم صادقين',
    'تَرۡجِعُونَه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٨٧',
    87, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 88 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5067,
    'فَأَمَّاۤ إِن كَانَ مِنَ ٱلۡمُقَرَّبِینَ',
    'فاما ان كان من المقربين',
    'فَأَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُقَرَّب<rule class=madda_permissible>ِي</rule>نَ ٨٨',
    88, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 89 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5068,
    'فَرَوۡحࣱ وَرَیۡحَانࣱ وَجَنَّتُ نَعِیمࣲ',
    'فروح وريحان وجنت نعيم',
    'فَرَوۡ<rule class=idgham_ghunnah>حٌ</rule> <rule class=idgham_ghunnah>و</rule>َرَيۡحَا<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>و</rule>َجَ<rule class=ghunnah>نّ</rule>َتُ نَع<rule class=madda_permissible>ِي</rule>مٍ ٨٩',
    89, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 90 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5069,
    'وَأَمَّاۤ إِن كَانَ مِنۡ أَصۡحَـٰبِ ٱلۡیَمِینِ',
    'واما ان كان من اصحاب اليمين',
    'وَأَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِنۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡيَم<rule class=madda_permissible>ِي</rule>نِ ٩٠',
    90, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 91 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5070,
    'فَسَلَـٰمࣱ لَّكَ مِنۡ أَصۡحَـٰبِ ٱلۡیَمِینِ',
    'فسلام لك من اصحاب اليمين',
    'فَسَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكَ مِنۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡيَم<rule class=madda_permissible>ِي</rule>نِ ٩١',
    91, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 92 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5071,
    'وَأَمَّاۤ إِن كَانَ مِنَ ٱلۡمُكَذِّبِینَ ٱلضَّاۤلِّینَ',
    'واما ان كان من المكذبين الضالين',
    'وَأَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمُكَذِّبِينَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ضّ<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ِي</rule>نَ ٩٢',
    92, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 93 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5072,
    'فَنُزُلࣱ مِّنۡ حَمِیمࣲ',
    'فنزل من حميم',
    'فَنُزُ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ حَم<rule class=madda_permissible>ِي</rule>مٍ ٩٣',
    93, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 94 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5073,
    'وَتَصۡلِیَةُ جَحِیمٍ',
    'وتصلية جحيم',
    'وَتَصۡلِيَةُ جَح<rule class=madda_permissible>ِي</rule>مٍ ٩٤',
    94, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 95 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5074,
    'إِنَّ هَـٰذَا لَهُوَ حَقُّ ٱلۡیَقِینِ',
    'ان هذا لهو حق اليقين',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا لَهُوَ حَقُّ <rule class=ham_wasl>ٱ</rule>لۡيَق<rule class=madda_permissible>ِي</rule>نِ ٩٥',
    95, 27, 7, 537, 471, 215, 'false'
  );
  
  -- Ayah 96 Surah Al-Waaqia
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    56,
    5075,
    'فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِیمِ',
    'فسبح باسم ربك العظيم',
    'فَسَبِّحۡ بِ<rule class=ham_wasl>ٱ</rule>سۡمِ رَبِّكَ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٩٦',
    96, 27, 7, 537, 471, 215, 'false'
  );
  

-- Surah Al-Hadid
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (57, 'سُورَةُ الحَدِيدِ', 'Al-Hadid', 'The Iron', 'Medinan', 29);

  -- Ayah 1 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5076,
    'سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'سبح لله ما في السماوات والارض وهو العزيز الحكيم',
    'سَبَّحَ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ١',
    1, 27, 7, 537, 472, 215, 'false'
  );
  
  -- Ayah 2 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5077,
    'لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ یُحۡیِۦ وَیُمِیتُۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'له ملك السماوات والارض يحيي ويميت وهو على كل شيء قدير',
    'لَهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ يُحۡى<rule class=madda_normal>ِۦ</rule> وَيُمِيتُ‌ۖ وَهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٢',
    2, 27, 7, 537, 472, 215, 'false'
  );
  
  -- Ayah 3 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5078,
    'هُوَ ٱلۡأَوَّلُ وَٱلۡـَٔاخِرُ وَٱلظَّـٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَیۡءٍ عَلِیمٌ',
    'هو الاول والاخر والظاهر والباطن وهو بكل شيء عليم',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لۡأَوَّلُ وَ<rule class=ham_wasl>ٱ</rule>لۡأَخِرُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>هِرُ وَ<rule class=ham_wasl>ٱ</rule>لۡبَاطِنُ‌ۖ وَهُوَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٣',
    3, 27, 7, 537, 472, 215, 'false'
  );
  
  -- Ayah 4 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5079,
    'هُوَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ یَعۡلَمُ مَا یَلِجُ فِی ٱلۡأَرۡضِ وَمَا یَخۡرُجُ مِنۡهَا وَمَا یَنزِلُ مِنَ ٱلسَّمَاۤءِ وَمَا یَعۡرُجُ فِیهَاۖ وَهُوَ مَعَكُمۡ أَیۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ',
    'هو الذي خلق السماوات والارض في ستة ايام ثم استوى على العرش يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو معكم اين ما كنتم والله بما تعملون بصير',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فِى سِتَّةِ أَيَّا<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>سۡتَوَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>لۡعَرۡشِ‌ۚ يَعۡلَمُ مَا يَلِجُ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا يَخۡرُجُ مِنۡهَا وَمَا يَ<rule class=ikhafa>نز</rule>ِلُ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَمَا يَعۡرُجُ فِيهَا‌ۖ وَهُوَ مَعَكُمۡ أَيۡنَ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٤',
    4, 27, 7, 538, 472, 215, 'false'
  );
  
  -- Ayah 5 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5080,
    'لَّهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ',
    'له ملك السماوات والارض والى الله ترجع الامور',
    'لَّهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَإِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تُرۡجَعُ <rule class=ham_wasl>ٱ</rule>لۡأُم<rule class=madda_permissible>ُو</rule>رُ ٥',
    5, 27, 7, 538, 472, 215, 'false'
  );
  
  -- Ayah 6 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5081,
    'یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِۚ وَهُوَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'يولج الليل في النهار ويولج النهار في الليل وهو عليم بذات الصدور',
    'يُولِجُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ وَيُولِجُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ فِى <rule class=ham_wasl>ٱ</rule>لَّيۡلِ‌ۚ وَهُوَ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٦',
    6, 27, 7, 538, 472, 215, 'false'
  );
  
  -- Ayah 7 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5082,
    'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِینَ فِیهِۖ فَٱلَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَأَنفَقُوا۟ لَهُمۡ أَجۡرࣱ كَبِیرࣱ',
    'امنوا بالله ورسوله وانفقوا مما جعلكم مستخلفين فيه فالذين امنوا منكم وانفقوا لهم اجر كبير',
    'ءَامِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَأَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> مِ<rule class=ghunnah>مّ</rule>َا جَعَلَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡتَخۡلَفِينَ فِيهِ‌ۖ فَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ وَأَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ</rule> لَهُمۡ أَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ك</rule>َب<rule class=madda_permissible>ِي</rule>رٌ ٧',
    7, 27, 7, 538, 472, 215, 'false'
  );
  
  -- Ayah 8 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5083,
    'وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ یَدۡعُوكُمۡ لِتُؤۡمِنُوا۟ بِرَبِّكُمۡ وَقَدۡ أَخَذَ مِیثَـٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِینَ',
    'وما لكم لا تؤمنون بالله والرسول يدعوكم لتؤمنوا بربكم وقد اخذ ميثاقكم ان كنتم مؤمنين',
    'وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ‌ۙ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ يَ<rule class=qalaqah>دۡ</rule>عُوكُمۡ لِتُؤۡمِنُو<rule class=slnt>اۡ</rule> بِرَبِّكُمۡ وَقَ<rule class=qalaqah>دۡ</rule> أَخَذَ مِيثَ<rule class=madda_normal>ـٰ</rule>قَكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 27, 7, 538, 472, 215, 'false'
  );
  
  -- Ayah 9 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5084,
    'هُوَ ٱلَّذِی یُنَزِّلُ عَلَىٰ عَبۡدِهِۦۤ ءَایَـٰتِۭ بَیِّنَـٰتࣲ لِّیُخۡرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ لَرَءُوفࣱ رَّحِیمࣱ',
    'هو الذي ينزل على عبده ايات بينات ليخرجكم من الظلمات الى النور وان الله بكم لرءوف رحيم',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُنَزِّلُ عَلَىٰ عَ<rule class=qalaqah>بۡ</rule>دِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُخۡرِجَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِكُمۡ لَرَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٩',
    9, 27, 7, 538, 472, 215, 'false'
  );
  
  -- Ayah 10 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5085,
    'وَمَا لَكُمۡ أَلَّا تُنفِقُوا۟ فِی سَبِیلِ ٱللَّهِ وَلِلَّهِ مِیرَ ٰ⁠ثُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ لَا یَسۡتَوِی مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ وَقَـٰتَلَۚ أُو۟لَـٰۤىِٕكَ أَعۡظَمُ دَرَجَةࣰ مِّنَ ٱلَّذِینَ أَنفَقُوا۟ مِنۢ بَعۡدُ وَقَـٰتَلُوا۟ۚ وَكُلࣰّا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ',
    'وما لكم الا تنفقوا في سبيل الله ولله ميراث السماوات والارض لا يستوي منكم من انفق من قبل الفتح وقاتل اولئك اعظم درجة من الذين انفقوا من بعد وقاتلوا وكلا وعد الله الحسنى والله بما تعملون خبير',
    'وَمَا لَكُمۡ أَلَّا تُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلِلَّهِ مِير<rule class=madda_normal>ٰ</rule>ثُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ لَا يَسۡتَوِى مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّنۡ أَ<rule class=ikhafa>نف</rule>َقَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ <rule class=ham_wasl>ٱ</rule>لۡفَتۡحِ وَقَ<rule class=madda_normal>ـٰ</rule>تَلَ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَعۡظَمُ دَرَجَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ</rule> م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدُ وَقَ<rule class=madda_normal>ـٰ</rule>تَلُو<rule class=slnt>اۡ‌ۚ</rule> وَكُل<rule class=idgham_ghunnah>اًّ</rule> <rule class=idgham_ghunnah>و</rule>َعَدَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ١٠',
    10, 27, 7, 538, 472, 215, 'false'
  );
  
  -- Ayah 11 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5086,
    'مَّن ذَا ٱلَّذِی یُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنࣰا فَیُضَـٰعِفَهُۥ لَهُۥ وَلَهُۥۤ أَجۡرࣱ كَرِیمࣱ',
    'من ذا الذي يقرض الله قرضا حسنا فيضاعفه له وله اجر كريم',
    'مَّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>َا <rule class=ham_wasl>ٱ</rule>لَّذِى يُ<rule class=qalaqah>قۡ</rule>رِضُ <rule class=ham_wasl>ٱ</rule>للَّهَ قَرۡضًا حَسَ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>َيُضَ<rule class=madda_normal>ـٰ</rule>عِفَهُ<rule class=madda_normal>ۥ</rule> لَهُ<rule class=madda_normal>ۥ</rule> وَلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ١١',
    11, 27, 7, 538, 473, 215, 'false'
  );
  
  -- Ayah 12 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5087,
    'یَوۡمَ تَرَى ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ یَسۡعَىٰ نُورُهُم بَیۡنَ أَیۡدِیهِمۡ وَبِأَیۡمَـٰنِهِمۖ بُشۡرَىٰكُمُ ٱلۡیَوۡمَ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'يوم ترى المؤمنين والمؤمنات يسعى نورهم بين ايديهم وبايمانهم بشراكم اليوم جنات تجري من تحتها الانهار خالدين فيها ذلك هو الفوز العظيم',
    'يَوۡمَ تَرَى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ يَسۡعَىٰ نُورُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَ<rule class=madda_normal>ـٰ</rule>نِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ُشۡرَ<rule class=madda_normal>ٮٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ١٢',
    12, 27, 7, 539, 473, 215, 'false'
  );
  
  -- Ayah 13 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5088,
    'یَوۡمَ یَقُولُ ٱلۡمُنَـٰفِقُونَ وَٱلۡمُنَـٰفِقَـٰتُ لِلَّذِینَ ءَامَنُوا۟ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِیلَ ٱرۡجِعُوا۟ وَرَاۤءَكُمۡ فَٱلۡتَمِسُوا۟ نُورࣰاۖ فَضُرِبَ بَیۡنَهُم بِسُورࣲ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِیهِ ٱلرَّحۡمَةُ وَظَـٰهِرُهُۥ مِن قِبَلِهِ ٱلۡعَذَابُ',
    'يوم يقول المنافقون والمنافقات للذين امنوا انظرونا نقتبس من نوركم قيل ارجعوا وراءكم فالتمسوا نورا فضرب بينهم بسور له باب باطنه فيه الرحمة وظاهره من قبله العذاب',
    'يَوۡمَ يَقُولُ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقُونَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقَ<rule class=madda_normal>ـٰ</rule>تُ لِلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نظ</rule>ُرُونَا نَ<rule class=qalaqah>قۡ</rule>تَبِسۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّورِكُمۡ قِيلَ <rule class=ham_wasl>ٱ</rule>رۡجِعُو<rule class=slnt>اۡ</rule> وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمۡ فَ<rule class=ham_wasl>ٱ</rule>لۡتَمِسُو<rule class=slnt>اۡ</rule> نُو<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َضُرِبَ بَيۡنَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِسُو<rule class=idgham_wo_ghunnah>رٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُ<rule class=madda_normal>ۥ</rule> بَا<rule class=iqlab>بُۢ</rule> <rule class=iqlab>ب</rule>َاطِنُهُ<rule class=madda_normal>ۥ</rule> فِيهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَةُ وَظَ<rule class=madda_normal>ـٰ</rule>هِرُهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ِبَلِهِ <rule class=ham_wasl>ٱ</rule>لۡعَذ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ُ ١٣',
    13, 27, 7, 539, 473, 215, 'false'
  );
  
  -- Ayah 14 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5089,
    'یُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُوا۟ بَلَىٰ وَلَـٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِیُّ حَتَّىٰ جَاۤءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ',
    'ينادونهم الم نكن معكم قالوا بلى ولكنكم فتنتم انفسكم وتربصتم وارتبتم وغرتكم الاماني حتى جاء امر الله وغركم بالله الغرور',
    'يُنَادُونَهُمۡ أَلَمۡ نَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>َّعَكُمۡ‌ۖ قَالُو<rule class=slnt>اۡ</rule> بَلَىٰ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َكُمۡ فَتَ<rule class=ikhafa>نت</rule>ُمۡ أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ وَتَرَبَّصۡتُمۡ وَ<rule class=ham_wasl>ٱ</rule>رۡتَ<rule class=qalaqah>بۡ</rule>تُمۡ وَغَرَّتۡكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَمَانِىُّ حَتَّىٰ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَمۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَغَرَّك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡغَر<rule class=madda_permissible>ُو</rule>رُ ١٤',
    14, 27, 7, 539, 473, 215, 'false'
  );
  
  -- Ayah 15 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5090,
    'فَٱلۡیَوۡمَ لَا یُؤۡخَذُ مِنكُمۡ فِدۡیَةࣱ وَلَا مِنَ ٱلَّذِینَ كَفَرُوا۟ۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِیَ مَوۡلَىٰكُمۡۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'فاليوم لا يؤخذ منكم فدية ولا من الذين كفروا ماواكم النار هي مولاكم وبئس المصير',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ لَا يُؤۡخَذُ مِ<rule class=ikhafa>نك</rule>ُمۡ فِ<rule class=qalaqah>دۡ</rule>يَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَا مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ‌ۚ</rule> مَأۡوَ<rule class=madda_normal>ٮٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارُ‌ۖ هِىَ مَوۡلَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٥',
    15, 27, 7, 539, 473, 215, 'false'
  );
  
  -- Ayah 16 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5091,
    '۞ أَلَمۡ یَأۡنِ لِلَّذِینَ ءَامَنُوۤا۟ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا یَكُونُوا۟ كَٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلُ فَطَالَ عَلَیۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ',
    'الم يان للذين امنوا ان تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين اوتوا الكتاب من قبل فطال عليهم الامد فقست قلوبهم وكثير منهم فاسقون',
    '۞أَلَمۡ يَأۡنِ لِلَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَمَا نَزَلَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَلَا يَكُونُو<rule class=slnt>اۡ</rule> كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ فَطَالَ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡ‌ۖ وَكَثِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ فَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 27, 7, 539, 473, 216, 'false'
  );
  
  -- Ayah 17 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5092,
    'ٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَیَّنَّا لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ',
    'اعلموا ان الله يحيي الارض بعد موتها قد بينا لكم الايات لعلكم تعقلون',
    'ٱعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحۡىِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بَعۡدَ مَوۡتِهَا‌ۚ قَ<rule class=qalaqah>دۡ</rule> بَيَّ<rule class=ghunnah>نّ</rule>َا لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَيَ<rule class=madda_normal>ـٰ</rule>تِ لَعَلَّكُمۡ تَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 27, 7, 539, 473, 216, 'false'
  );
  
  -- Ayah 18 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5093,
    'إِنَّ ٱلۡمُصَّدِّقِینَ وَٱلۡمُصَّدِّقَـٰتِ وَأَقۡرَضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰا یُضَـٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرࣱ كَرِیمࣱ',
    'ان المصدقين والمصدقات واقرضوا الله قرضا حسنا يضاعف لهم ولهم اجر كريم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُصَّدِّقِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُصَّدِّقَ<rule class=madda_normal>ـٰ</rule>تِ وَأَ<rule class=qalaqah>قۡ</rule>رَضُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ قَرۡضًا حَسَ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>ي</rule>ُضَ<rule class=madda_normal>ـٰ</rule>عَفُ لَهُمۡ وَلَهُمۡ أَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٌ ١٨',
    18, 27, 7, 539, 473, 216, 'false'
  );
  
  -- Ayah 19 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5094,
    'وَٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۤ أُو۟لَـٰۤىِٕكَ هُمُ ٱلصِّدِّیقُونَۖ وَٱلشُّهَدَاۤءُ عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ',
    'والذين امنوا بالله ورسله اولئك هم الصديقون والشهداء عند ربهم لهم اجرهم ونورهم والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرُسُلِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صِّدِّيقُونَ‌ۖ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شُّهَد<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ لَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رُهُمۡ وَنُورُهُمۡ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَكَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ١٩',
    19, 27, 7, 540, 473, 216, 'false'
  );
  
  -- Ayah 20 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5095,
    'ٱعۡلَمُوۤا۟ أَنَّمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَا لَعِبࣱ وَلَهۡوࣱ وَزِینَةࣱ وَتَفَاخُرُۢ بَیۡنَكُمۡ وَتَكَاثُرࣱ فِی ٱلۡأَمۡوَ ٰ⁠لِ وَٱلۡأَوۡلَـٰدِۖ كَمَثَلِ غَیۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ یَهِیجُ فَتَرَىٰهُ مُصۡفَرࣰّا ثُمَّ یَكُونُ حُطَـٰمࣰاۖ وَفِی ٱلۡـَٔاخِرَةِ عَذَابࣱ شَدِیدࣱ وَمَغۡفِرَةࣱ مِّنَ ٱللَّهِ وَرِضۡوَ ٰ⁠نࣱۚ وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا مَتَـٰعُ ٱلۡغُرُورِ',
    'اعلموا انما الحياة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الاموال والاولاد كمثل غيث اعجب الكفار نباته ثم يهيج فتراه مصفرا ثم يكون حطاما وفي الاخرة عذاب شديد ومغفرة من الله ورضوان وما الحياة الدنيا الا متاع الغرور',
    'ٱعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا لَعِ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَهۡ<rule class=idgham_ghunnah>وٌ</rule> <rule class=idgham_ghunnah>و</rule>َزِينَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َتَفَاخُ<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>َيۡنَكُمۡ وَتَكَاثُ<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَمۡو<rule class=madda_normal>ٰ</rule>لِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَوۡلَ<rule class=madda_normal>ـٰ</rule>دِ‌ۖ كَمَثَلِ غَيۡثٍ أَعۡجَبَ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارَ نَبَاتُهُ<rule class=madda_normal>ۥ</rule> ثُ<rule class=ghunnah>مّ</rule>َ يَهِيجُ فَتَرَ<rule class=madda_normal>ٮٰ</rule>هُ مُصۡفَر<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ث</rule>ُ<rule class=ghunnah>مّ</rule>َ يَكُونُ حُطَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َفِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ عَذَا<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرِضۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡي<rule class=madda_obligatory_monfasel>َآ</rule> إِلَّا مَتَ<rule class=madda_normal>ـٰ</rule>عُ <rule class=ham_wasl>ٱ</rule>لۡغُر<rule class=madda_permissible>ُو</rule>رِ ٢٠',
    20, 27, 7, 540, 474, 216, 'false'
  );
  
  -- Ayah 21 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5096,
    'سَابِقُوۤا۟ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۚ ذَ ٰ⁠لِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ',
    'سابقوا الى مغفرة من ربكم وجنة عرضها كعرض السماء والارض اعدت للذين امنوا بالله ورسله ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم',
    'سَابِق<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَىٰ مَغۡفِرَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكُمۡ وَجَ<rule class=ghunnah>نّ</rule>َةٍ عَرۡضُهَا كَعَرۡضِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أُعِدَّتۡ لِلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرُسُلِه<rule class=madda_normal>ِۦ</rule>‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ يُؤۡتِيهِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ ذُو <rule class=ham_wasl>ٱ</rule>لۡفَضۡلِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٢١',
    21, 27, 7, 540, 474, 216, 'false'
  );
  
  -- Ayah 22 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5097,
    'مَاۤ أَصَابَ مِن مُّصِیبَةࣲ فِی ٱلۡأَرۡضِ وَلَا فِیۤ أَنفُسِكُمۡ إِلَّا فِی كِتَـٰبࣲ مِّن قَبۡلِ أَن نَّبۡرَأَهَاۤۚ إِنَّ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ',
    'ما اصاب من مصيبة في الارض ولا في انفسكم الا في كتاب من قبل ان نبراها ان ذلك على الله يسير',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّصِيبَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِكُمۡ إِلَّا فِى كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>بۡ</rule>رَأَه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ ذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَس<rule class=madda_permissible>ِي</rule>رٌ ٢٢',
    22, 27, 7, 540, 474, 216, 'false'
  );
  
  -- Ayah 23 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5098,
    'لِّكَیۡلَا تَأۡسَوۡا۟ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُوا۟ بِمَاۤ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا یُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورٍ',
    'لكيلا تاسوا على ما فاتكم ولا تفرحوا بما اتاكم والله لا يحب كل مختال فخور',
    'لِّكَيۡلَا تَأۡسَوۡ<rule class=slnt>اۡ</rule> عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُو<rule class=slnt>اۡ</rule> بِم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يُحِبُّ كُلَّ مُخۡتَا<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َخ<rule class=madda_permissible>ُو</rule>رٍ ٢٣',
    23, 27, 7, 540, 474, 216, 'false'
  );
  
  -- Ayah 24 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5099,
    'ٱلَّذِینَ یَبۡخَلُونَ وَیَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِۗ وَمَن یَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ',
    'الذين يبخلون ويامرون الناس بالبخل ومن يتول فان الله هو الغني الحميد',
    'ٱلَّذِينَ يَ<rule class=qalaqah>بۡ</rule>خَلُونَ وَيَأۡمُرُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ بِ<rule class=ham_wasl>ٱ</rule>لۡبُخۡلِ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَلَّ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَنِىُّ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٢٤',
    24, 27, 7, 540, 474, 216, 'false'
  );
  
  -- Ayah 25 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5100,
    'لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَیِّنَـٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَـٰبَ وَٱلۡمِیزَانَ لِیَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِیدَ فِیهِ بَأۡسࣱ شَدِیدࣱ وَمَنَـٰفِعُ لِلنَّاسِ وَلِیَعۡلَمَ ٱللَّهُ مَن یَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَیۡبِۚ إِنَّ ٱللَّهَ قَوِیٌّ عَزِیزࣱ',
    'لقد ارسلنا رسلنا بالبينات وانزلنا معهم الكتاب والميزان ليقوم الناس بالقسط وانزلنا الحديد فيه باس شديد ومنافع للناس وليعلم الله من ينصره ورسله بالغيب ان الله قوي عزيز',
    'لَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا رُسُلَنَا بِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ وَأَ<rule class=ikhafa>نز</rule>َلۡنَا مَعَهُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡمِيزَانَ لِيَقُومَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ بِ<rule class=ham_wasl>ٱ</rule>لۡقِسۡطِ‌ۖ وَأَ<rule class=ikhafa>نز</rule>َلۡنَا <rule class=ham_wasl>ٱ</rule>لۡحَدِيدَ فِيهِ بَأۡ<rule class=ikhafa>سٌ</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َمَنَ<rule class=madda_normal>ـٰ</rule>فِعُ لِل<rule class=ghunnah>نّ</rule>َاسِ وَلِيَعۡلَمَ <rule class=ham_wasl>ٱ</rule>للَّهُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=ikhafa>نص</rule>ُرُهُ<rule class=madda_normal>ۥ</rule> وَرُسُلَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَوِىٌّ عَز<rule class=madda_permissible>ِي</rule>زٌ ٢٥',
    25, 27, 7, 541, 474, 216, 'false'
  );
  
  -- Ayah 26 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5101,
    'وَلَقَدۡ أَرۡسَلۡنَا نُوحࣰا وَإِبۡرَ ٰ⁠هِیمَ وَجَعَلۡنَا فِی ذُرِّیَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَـٰبَۖ فَمِنۡهُم مُّهۡتَدࣲۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ',
    'ولقد ارسلنا نوحا وابراهيم وجعلنا في ذريتهما النبوة والكتاب فمنهم مهتد وكثير منهم فاسقون',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> أَرۡسَلۡنَا نُو<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَجَعَلۡنَا فِى ذُرِّيَّتِهِمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُبُوَّةَ وَ<rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ‌ۖ فَمِنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّهۡتَ<rule class=idgham_ghunnah>دٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َكَثِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ فَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٢٦',
    26, 27, 7, 541, 475, 216, 'false'
  );
  
  -- Ayah 27 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5102,
    'ثُمَّ قَفَّیۡنَا عَلَىٰۤ ءَاثَـٰرِهِم بِرُسُلِنَا وَقَفَّیۡنَا بِعِیسَى ٱبۡنِ مَرۡیَمَ وَءَاتَیۡنَـٰهُ ٱلۡإِنجِیلَۖ وَجَعَلۡنَا فِی قُلُوبِ ٱلَّذِینَ ٱتَّبَعُوهُ رَأۡفَةࣰ وَرَحۡمَةࣰۚ وَرَهۡبَانِیَّةً ٱبۡتَدَعُوهَا مَا كَتَبۡنَـٰهَا عَلَیۡهِمۡ إِلَّا ٱبۡتِغَاۤءَ رِضۡوَ ٰ⁠نِ ٱللَّهِ فَمَا رَعَوۡهَا حَقَّ رِعَایَتِهَاۖ فَـَٔاتَیۡنَا ٱلَّذِینَ ءَامَنُوا۟ مِنۡهُمۡ أَجۡرَهُمۡۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ',
    'ثم قفينا على اثارهم برسلنا وقفينا بعيسى ابن مريم واتيناه الانجيل وجعلنا في قلوب الذين اتبعوه رافة ورحمة ورهبانية ابتدعوها ما كتبناها عليهم الا ابتغاء رضوان الله فما رعوها حق رعايتها فاتينا الذين امنوا منهم اجرهم وكثير منهم فاسقون',
    'ثُ<rule class=ghunnah>مّ</rule>َ قَفَّيۡنَا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَاثَ<rule class=madda_normal>ـٰ</rule>رِه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرُسُلِنَا وَقَفَّيۡنَا بِعِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ مَرۡيَمَ وَءَاتَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نج</rule>ِيلَ وَجَعَلۡنَا فِى قُلُوبِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ <rule class=ham_wasl>ٱ</rule>تَّبَعُوهُ رَأۡفَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َرَحۡمَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َرَهۡبَانِيَّةً <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَدَعُوهَا مَا كَتَ<rule class=qalaqah>بۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هَا عَلَيۡهِمۡ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رِضۡو<rule class=madda_normal>ٰ</rule>نِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَمَا رَعَوۡهَا حَقَّ رِعَايَتِهَا‌ۖ فَـَٔـاتَيۡنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ أَ<rule class=qalaqah>جۡ</rule>رَهُمۡ‌ۖ وَكَثِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ فَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 27, 7, 541, 475, 216, 'false'
  );
  
  -- Ayah 28 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5103,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ یُؤۡتِكُمۡ كِفۡلَیۡنِ مِن رَّحۡمَتِهِۦ وَیَجۡعَل لَّكُمۡ نُورࣰا تَمۡشُونَ بِهِۦ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'يا ايها الذين امنوا اتقوا الله وامنوا برسوله يؤتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم والله غفور رحيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَءَامِنُو<rule class=slnt>اۡ</rule> بِرَسُولِه<rule class=madda_normal>ِۦ</rule> يُؤۡتِكُمۡ كِفۡلَيۡنِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّحۡمَتِه<rule class=madda_normal>ِۦ</rule> وَيَ<rule class=qalaqah>جۡ</rule>عَل لَّكُمۡ نُو<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ت</rule>َمۡشُونَ بِه<rule class=madda_normal>ِۦ</rule> وَيَغۡفِرۡ لَكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٢٨',
    28, 27, 7, 541, 475, 216, 'false'
  );
  
  -- Ayah 29 Surah Al-Hadid
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    57,
    5104,
    'لِّئَلَّا یَعۡلَمَ أَهۡلُ ٱلۡكِتَـٰبِ أَلَّا یَقۡدِرُونَ عَلَىٰ شَیۡءࣲ مِّن فَضۡلِ ٱللَّهِ وَأَنَّ ٱلۡفَضۡلَ بِیَدِ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ',
    'لئلا يعلم اهل الكتاب الا يقدرون على شيء من فضل الله وان الفضل بيد الله يؤتيه من يشاء والله ذو الفضل العظيم',
    'لِّئَلَّا يَعۡلَمَ أَهۡلُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ أَلَّا يَ<rule class=qalaqah>قۡ</rule>دِرُونَ عَلَىٰ ش<rule class=idgham_ghunnah>َىۡءٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۙ وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡفَضۡلَ بِيَدِ <rule class=ham_wasl>ٱ</rule>للَّهِ يُؤۡتِيهِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ ذُو <rule class=ham_wasl>ٱ</rule>لۡفَضۡلِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٢٩',
    29, 27, 7, 541, 475, 216, 'false'
  );
  

-- Surah Al-Mujaadila
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (58, 'سُورَةُ المُجَادلَةِ', 'Al-Mujaadila', 'The Pleading Woman', 'Medinan', 22);

  -- Ayah 1 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5105,
    'قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِی تُجَـٰدِلُكَ فِی زَوۡجِهَا وَتَشۡتَكِیۤ إِلَى ٱللَّهِ وَٱللَّهُ یَسۡمَعُ تَحَاوُرَكُمَاۤۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرٌ',
    'قد سمع الله قول التي تجادلك في زوجها وتشتكي الى الله والله يسمع تحاوركما ان الله سميع بصير',
    'قَ<rule class=qalaqah>دۡ</rule> سَمِعَ <rule class=ham_wasl>ٱ</rule>للَّهُ قَوۡلَ <rule class=ham_wasl>ٱ</rule>لَّتِى تُجَ<rule class=madda_normal>ـٰ</rule>دِلُكَ فِى زَوۡجِهَا وَتَشۡتَك<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَسۡمَعُ تَحَاوُرَكُم<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ سَمِي<rule class=iqlab>عُۢ</rule> <rule class=iqlab>ب</rule>َص<rule class=madda_permissible>ِي</rule>رٌ ١',
    1, 28, 7, 542, 476, 217, 'false'
  );
  
  -- Ayah 2 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5106,
    'ٱلَّذِینَ یُظَـٰهِرُونَ مِنكُم مِّن نِّسَاۤىِٕهِم مَّا هُنَّ أُمَّهَـٰتِهِمۡۖ إِنۡ أُمَّهَـٰتُهُمۡ إِلَّا ٱلَّـٰۤـِٔی وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَیَقُولُونَ مُنكَرࣰا مِّنَ ٱلۡقَوۡلِ وَزُورࣰاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ',
    'الذين يظاهرون منكم من نسائهم ما هن امهاتهم ان امهاتهم الا اللائي ولدنهم وانهم ليقولون منكرا من القول وزورا وان الله لعفو غفور',
    'ٱلَّذِينَ يُظَ<rule class=madda_normal>ـٰ</rule>هِرُونَ مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ِّس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا هُ<rule class=ghunnah>نّ</rule>َ أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تِهِمۡ‌ۖ إِنۡ أُ<rule class=ghunnah>مّ</rule>َهَ<rule class=madda_normal>ـٰ</rule>تُهُمۡ إِلَّا <rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_obligatory_mottasel>ــٰٓ</rule>ــِٔى وَلَ<rule class=qalaqah>دۡ</rule>نَهُمۡ‌ۚ وَإِ<rule class=ghunnah>نّ</rule>َهُمۡ لَيَقُولُونَ مُ<rule class=ikhafa>نك</rule>َ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡلِ وَزُو<rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَعَفُوٌّ غَف<rule class=madda_permissible>ُو</rule>رٌ ٢',
    2, 28, 7, 542, 476, 217, 'false'
  );
  
  -- Ayah 3 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5107,
    'وَٱلَّذِینَ یُظَـٰهِرُونَ مِن نِّسَاۤىِٕهِمۡ ثُمَّ یَعُودُونَ لِمَا قَالُوا۟ فَتَحۡرِیرُ رَقَبَةࣲ مِّن قَبۡلِ أَن یَتَمَاۤسَّاۚ ذَ ٰ⁠لِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ',
    'والذين يظاهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبة من قبل ان يتماسا ذلكم توعظون به والله بما تعملون خبير',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُظَ<rule class=madda_normal>ـٰ</rule>هِرُونَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ِّس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ ثُ<rule class=ghunnah>مّ</rule>َ يَعُودُونَ لِمَا قَالُو<rule class=slnt>اۡ</rule> فَتَحۡرِيرُ رَقَبَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَم<rule class=madda_necessary>َا</rule>ٓسَّا‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ تُوعَظُونَ بِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ٣',
    3, 28, 7, 542, 476, 217, 'false'
  );
  
  -- Ayah 4 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5108,
    'فَمَن لَّمۡ یَجِدۡ فَصِیَامُ شَهۡرَیۡنِ مُتَتَابِعَیۡنِ مِن قَبۡلِ أَن یَتَمَاۤسَّاۖ فَمَن لَّمۡ یَسۡتَطِعۡ فَإِطۡعَامُ سِتِّینَ مِسۡكِینࣰاۚ ذَ ٰ⁠لِكَ لِتُؤۡمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَـٰفِرِینَ عَذَابٌ أَلِیمٌ',
    'فمن لم يجد فصيام شهرين متتابعين من قبل ان يتماسا فمن لم يستطع فاطعام ستين مسكينا ذلك لتؤمنوا بالله ورسوله وتلك حدود الله وللكافرين عذاب اليم',
    'فَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَجِ<rule class=qalaqah>دۡ</rule> فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَم<rule class=madda_necessary>َا</rule>ٓسَّا‌ۖ فَم<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَسۡتَطِعۡ فَإِ<rule class=qalaqah>طۡ</rule>عَامُ سِتِّينَ مِسۡكِي<rule class=ikhafa>نًا‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ لِتُؤۡمِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَتِلۡكَ حُدُودُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَلِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٤',
    4, 28, 7, 542, 476, 217, 'false'
  );
  
  -- Ayah 5 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5109,
    'إِنَّ ٱلَّذِینَ یُحَاۤدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَاۤ ءَایَـٰتِۭ بَیِّنَـٰتࣲۚ وَلِلۡكَـٰفِرِینَ عَذَابࣱ مُّهِینࣱ',
    'ان الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم وقد انزلنا ايات بينات وللكافرين عذاب مهين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُح<rule class=madda_necessary>َا</rule>ٓدُّونَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> كُبِتُو<rule class=slnt>اۡ</rule> كَمَا كُبِتَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ‌ۚ وَقَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نز</rule>َلۡن<rule class=madda_obligatory_monfasel>َآ</rule> ءَايَ<rule class=madda_normal>ـٰ</rule><rule class=iqlab>تِۭ</rule> <rule class=iqlab>ب</rule>َيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َلِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّه<rule class=madda_permissible>ِي</rule>نٌ ٥',
    5, 28, 7, 542, 476, 217, 'false'
  );
  
  -- Ayah 6 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5110,
    'یَوۡمَ یَبۡعَثُهُمُ ٱللَّهُ جَمِیعࣰا فَیُنَبِّئُهُم بِمَا عَمِلُوۤا۟ۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ',
    'يوم يبعثهم الله جميعا فينبئهم بما عملوا احصاه الله ونسوه والله على كل شيء شهيد',
    'يَوۡمَ يَ<rule class=qalaqah>بۡ</rule>عَثُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َيُنَبِّئُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا عَمِل<rule class=madda_obligatory_monfasel>ُوٓ<rule class=slnt>اۡ</rule>‌ۚ</rule> أَحۡصَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>للَّهُ وَنَسُوهُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ش</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٦',
    6, 28, 7, 542, 476, 217, 'false'
  );
  
  -- Ayah 7 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5111,
    'أَلَمۡ تَرَ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ مَا یَكُونُ مِن نَّجۡوَىٰ ثَلَـٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَاۤ أَدۡنَىٰ مِن ذَ ٰ⁠لِكَ وَلَاۤ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَیۡنَ مَا كَانُوا۟ۖ ثُمَّ یُنَبِّئُهُم بِمَا عَمِلُوا۟ یَوۡمَ ٱلۡقِیَـٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمٌ',
    'الم تر ان الله يعلم ما في السماوات وما في الارض ما يكون من نجوى ثلاثة الا هو رابعهم ولا خمسة الا هو سادسهم ولا ادنى من ذلك ولا اكثر الا هو معهم اين ما كانوا ثم ينبئهم بما عملوا يوم القيامة ان الله بكل شيء عليم',
    'أَلَمۡ تَرَ أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ مَا يَكُونُ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>جۡ</rule>وَىٰ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>نَىٰ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَيۡنَ مَا كَانُو<rule class=slnt>اۡ‌ۖ</rule> ثُ<rule class=ghunnah>مّ</rule>َ يُنَبِّئُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا عَمِلُو<rule class=slnt>اۡ</rule> يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ٧',
    7, 28, 7, 543, 477, 217, 'false'
  );
  
  -- Ayah 8 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5112,
    'أَلَمۡ تَرَ إِلَى ٱلَّذِینَ نُهُوا۟ عَنِ ٱلنَّجۡوَىٰ ثُمَّ یَعُودُونَ لِمَا نُهُوا۟ عَنۡهُ وَیَتَنَـٰجَوۡنَ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰ⁠نِ وَمَعۡصِیَتِ ٱلرَّسُولِۖ وَإِذَا جَاۤءُوكَ حَیَّوۡكَ بِمَا لَمۡ یُحَیِّكَ بِهِ ٱللَّهُ وَیَقُولُونَ فِیۤ أَنفُسِهِمۡ لَوۡلَا یُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ جَهَنَّمُ یَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِیرُ',
    'الم تر الى الذين نهوا عن النجوى ثم يعودون لما نهوا عنه ويتناجون بالاثم والعدوان ومعصيت الرسول واذا جاءوك حيوك بما لم يحيك به الله ويقولون في انفسهم لولا يعذبنا الله بما نقول حسبهم جهنم يصلونها فبئس المصير',
    'أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ نُهُو<rule class=slnt>اۡ</rule> عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=qalaqah>جۡ</rule>وَىٰ ثُ<rule class=ghunnah>مّ</rule>َ يَعُودُونَ لِمَا نُهُو<rule class=slnt>اۡ</rule> عَنۡهُ وَيَتَنَ<rule class=madda_normal>ـٰ</rule>جَوۡنَ بِ<rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَ<rule class=ham_wasl>ٱ</rule>لۡعُ<rule class=qalaqah>دۡ</rule>و<rule class=madda_normal>ٰ</rule>نِ وَمَعۡصِيَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ وَإِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُوكَ حَيَّوۡكَ بِمَا لَمۡ يُحَيِّكَ بِهِ <rule class=ham_wasl>ٱ</rule>للَّهُ وَيَقُولُونَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ لَوۡلَا يُعَذِّبُنَا <rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا نَقُولُ‌ۚ حَسۡبُهُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ يَصۡلَوۡنَهَا‌ۖ فَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٨',
    8, 28, 7, 543, 477, 217, 'false'
  );
  
  -- Ayah 9 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5113,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا تَنَـٰجَیۡتُمۡ فَلَا تَتَنَـٰجَوۡا۟ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰ⁠نِ وَمَعۡصِیَتِ ٱلرَّسُولِ وَتَنَـٰجَوۡا۟ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ إِلَیۡهِ تُحۡشَرُونَ',
    'يا ايها الذين امنوا اذا تناجيتم فلا تتناجوا بالاثم والعدوان ومعصيت الرسول وتناجوا بالبر والتقوى واتقوا الله الذي اليه تحشرون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا تَنَ<rule class=madda_normal>ـٰ</rule>جَيۡتُمۡ فَلَا تَتَنَ<rule class=madda_normal>ـٰ</rule>جَوۡ<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡإِثۡمِ وَ<rule class=ham_wasl>ٱ</rule>لۡعُ<rule class=qalaqah>دۡ</rule>و<rule class=madda_normal>ٰ</rule>نِ وَمَعۡصِيَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولِ وَتَنَ<rule class=madda_normal>ـٰ</rule>جَوۡ<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡبِرِّ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=qalaqah>قۡ</rule>وَىٰ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَيۡهِ تُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 28, 7, 543, 477, 217, 'false'
  );
  
  -- Ayah 10 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5114,
    'إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّیۡطَـٰنِ لِیَحۡزُنَ ٱلَّذِینَ ءَامَنُوا۟ وَلَیۡسَ بِضَاۤرِّهِمۡ شَیۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ',
    'انما النجوى من الشيطان ليحزن الذين امنوا وليس بضارهم شيئا الا باذن الله وعلى الله فليتوكل المؤمنون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=qalaqah>جۡ</rule>وَىٰ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ لِيَحۡزُنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَلَيۡسَ بِض<rule class=madda_necessary>َا</rule>ٓرِّهِمۡ شَيۡــًٔا إِلَّا بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 28, 7, 543, 477, 217, 'false'
  );
  
  -- Ayah 11 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5115,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا قِیلَ لَكُمۡ تَفَسَّحُوا۟ فِی ٱلۡمَجَـٰلِسِ فَٱفۡسَحُوا۟ یَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِیلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ یَرۡفَعِ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ دَرَجَـٰتࣲۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ',
    'يا ايها الذين امنوا اذا قيل لكم تفسحوا في المجالس فافسحوا يفسح الله لكم واذا قيل انشزوا فانشزوا يرفع الله الذين امنوا منكم والذين اوتوا العلم درجات والله بما تعملون خبير',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا قِيلَ لَكُمۡ تَفَسَّحُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡمَجَ<rule class=madda_normal>ـٰ</rule>لِسِ فَ<rule class=ham_wasl>ٱ</rule>فۡسَحُو<rule class=slnt>اۡ</rule> يَفۡسَحِ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ‌ۖ وَإِذَا قِيلَ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نش</rule>ُزُو<rule class=slnt>اۡ</rule> فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نش</rule>ُزُو<rule class=slnt>اۡ</rule> يَرۡفَعِ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِلۡمَ دَرَجَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ١١',
    11, 28, 7, 543, 477, 217, 'false'
  );
  
  -- Ayah 12 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5116,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نَـٰجَیۡتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَیۡنَ یَدَیۡ نَجۡوَىٰكُمۡ صَدَقَةࣰۚ ذَ ٰ⁠لِكَ خَیۡرࣱ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ',
    'يا ايها الذين امنوا اذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقة ذلك خير لكم واطهر فان لم تجدوا فان الله غفور رحيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا نَ<rule class=madda_normal>ـٰ</rule>جَيۡتُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ فَقَدِّمُو<rule class=slnt>اۡ</rule> بَيۡنَ يَدَىۡ نَ<rule class=qalaqah>جۡ</rule>وَ<rule class=madda_normal>ٮٰ</rule>كُمۡ صَدَقَ<rule class=ikhafa>ةً‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ وَأَ<rule class=qalaqah>طۡ</rule>هَرُ‌ۚ فَإ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ تَجِدُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٢',
    12, 28, 7, 544, 477, 217, 'false'
  );
  
  -- Ayah 13 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5117,
    'ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُوا۟ بَیۡنَ یَدَیۡ نَجۡوَىٰكُمۡ صَدَقَـٰتࣲۚ فَإِذۡ لَمۡ تَفۡعَلُوا۟ وَتَابَ ٱللَّهُ عَلَیۡكُمۡ فَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ',
    'ااشفقتم ان تقدموا بين يدي نجواكم صدقات فاذ لم تفعلوا وتاب الله عليكم فاقيموا الصلاة واتوا الزكاة واطيعوا الله ورسوله والله خبير بما تعملون',
    'ءَأَشۡفَ<rule class=qalaqah>قۡ</rule>تُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُقَدِّمُو<rule class=slnt>اۡ</rule> بَيۡنَ يَدَىۡ نَ<rule class=qalaqah>جۡ</rule>وَ<rule class=madda_normal>ٮٰ</rule>كُمۡ صَدَقَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ‌ۚ</rule> <rule class=ikhafa>ف</rule>َإِذۡ لَمۡ تَفۡعَلُو<rule class=slnt>اۡ</rule> وَتَابَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡكُمۡ فَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 28, 7, 544, 477, 217, 'false'
  );
  
  -- Ayah 14 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5118,
    '۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ تَوَلَّوۡا۟ قَوۡمًا غَضِبَ ٱللَّهُ عَلَیۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَیَحۡلِفُونَ عَلَى ٱلۡكَذِبِ وَهُمۡ یَعۡلَمُونَ',
    'الم تر الى الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون على الكذب وهم يعلمون',
    '۞أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ تَوَلَّوۡ<rule class=slnt>اۡ</rule> قَوۡمًا غَضِبَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ وَلَا مِنۡهُمۡ وَيَحۡلِفُونَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَذِبِ وَهُمۡ يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 28, 7, 544, 478, 218, 'false'
  );
  
  -- Ayah 15 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5119,
    'أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰا شَدِیدًاۖ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'اعد الله لهم عذابا شديدا انهم ساء ما كانوا يعملون',
    'أَعَدَّ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُمۡ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َدِيدًا‌ۖ إِ<rule class=ghunnah>نّ</rule>َهُمۡ س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 28, 7, 544, 478, 218, 'false'
  );
  
  -- Ayah 16 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5120,
    'ٱتَّخَذُوۤا۟ أَیۡمَـٰنَهُمۡ جُنَّةࣰ فَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ فَلَهُمۡ عَذَابࣱ مُّهِینࣱ',
    'اتخذوا ايمانهم جنة فصدوا عن سبيل الله فلهم عذاب مهين',
    'ٱتَّخَذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نَهُمۡ جُ<rule class=ghunnah>نّ</rule>َ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َصَدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ فَلَهُمۡ عَذَا<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّه<rule class=madda_permissible>ِي</rule>نٌ ١٦',
    16, 28, 7, 544, 478, 218, 'false'
  );
  
  -- Ayah 17 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5121,
    'لَّن تُغۡنِیَ عَنۡهُمۡ أَمۡوَ ٰ⁠لُهُمۡ وَلَاۤ أَوۡلَـٰدُهُم مِّنَ ٱللَّهِ شَیۡـًٔاۚ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ',
    'لن تغني عنهم اموالهم ولا اولادهم من الله شيئا اولئك اصحاب النار هم فيها خالدون',
    'لَّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُغۡنِىَ عَنۡهُمۡ أَمۡو<rule class=madda_normal>ٰ</rule>لُهُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡــًٔا‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ‌ۖ هُمۡ فِيهَا خَ<rule class=madda_normal>ـٰ</rule>لِد<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 28, 7, 544, 478, 218, 'false'
  );
  
  -- Ayah 18 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5122,
    'یَوۡمَ یَبۡعَثُهُمُ ٱللَّهُ جَمِیعࣰا فَیَحۡلِفُونَ لَهُۥ كَمَا یَحۡلِفُونَ لَكُمۡ وَیَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَیۡءٍۚ أَلَاۤ إِنَّهُمۡ هُمُ ٱلۡكَـٰذِبُونَ',
    'يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم على شيء الا انهم هم الكاذبون',
    'يَوۡمَ يَ<rule class=qalaqah>بۡ</rule>عَثُهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ جَمِي<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َيَحۡلِفُونَ لَهُ<rule class=madda_normal>ۥ</rule> كَمَا يَحۡلِفُونَ لَكُمۡ‌ۖ وَيَحۡسَبُونَ أَ<rule class=ghunnah>نّ</rule>َهُمۡ عَلَىٰ شَىۡءٍ‌ۚ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ هُمُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 28, 7, 544, 478, 218, 'false'
  );
  
  -- Ayah 19 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5123,
    'ٱسۡتَحۡوَذَ عَلَیۡهِمُ ٱلشَّیۡطَـٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُو۟لَـٰۤىِٕكَ حِزۡبُ ٱلشَّیۡطَـٰنِۚ أَلَاۤ إِنَّ حِزۡبَ ٱلشَّیۡطَـٰنِ هُمُ ٱلۡخَـٰسِرُونَ',
    'استحوذ عليهم الشيطان فانساهم ذكر الله اولئك حزب الشيطان الا ان حزب الشيطان هم الخاسرون',
    'ٱسۡتَحۡوَذَ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نُ فَأَ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>هُمۡ ذِكۡرَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ حِزۡبُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ حِزۡبَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 28, 7, 544, 478, 218, 'false'
  );
  
  -- Ayah 20 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5124,
    'إِنَّ ٱلَّذِینَ یُحَاۤدُّونَ ٱللَّهَ وَرَسُولَهُۥۤ أُو۟لَـٰۤىِٕكَ فِی ٱلۡأَذَلِّینَ',
    'ان الذين يحادون الله ورسوله اولئك في الاذلين',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُح<rule class=madda_necessary>َا</rule>ٓدُّونَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَذَلّ<rule class=madda_permissible>ِي</rule>نَ ٢٠',
    20, 28, 7, 544, 478, 218, 'false'
  );
  
  -- Ayah 21 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5125,
    'كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِیۤۚ إِنَّ ٱللَّهَ قَوِیٌّ عَزِیزࣱ',
    'كتب الله لاغلبن انا ورسلي ان الله قوي عزيز',
    'كَتَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَأَغۡلِبَ<rule class=ghunnah>نّ</rule>َ أَنَاۡ وَرُسُل<rule class=madda_obligatory_monfasel>ِىٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَوِىٌّ عَز<rule class=madda_permissible>ِي</rule>زٌ ٢١',
    21, 28, 7, 544, 478, 218, 'false'
  );
  
  -- Ayah 22 Surah Al-Mujaadila
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    58,
    5126,
    'لَّا تَجِدُ قَوۡمࣰا یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ یُوَاۤدُّونَ مَنۡ حَاۤدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوۤا۟ ءَابَاۤءَهُمۡ أَوۡ أَبۡنَاۤءَهُمۡ أَوۡ إِخۡوَ ٰ⁠نَهُمۡ أَوۡ عَشِیرَتَهُمۡۚ أُو۟لَـٰۤىِٕكَ كَتَبَ فِی قُلُوبِهِمُ ٱلۡإِیمَـٰنَ وَأَیَّدَهُم بِرُوحࣲ مِّنۡهُۖ وَیُدۡخِلُهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ رَضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُۚ أُو۟لَـٰۤىِٕكَ حِزۡبُ ٱللَّهِۚ أَلَاۤ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ',
    'لا تجد قوما يؤمنون بالله واليوم الاخر يوادون من حاد الله ورسوله ولو كانوا اباءهم او ابناءهم او اخوانهم او عشيرتهم اولئك كتب في قلوبهم الايمان وايدهم بروح منه ويدخلهم جنات تجري من تحتها الانهار خالدين فيها رضي الله عنهم ورضوا عنه اولئك حزب الله الا ان حزب الله هم المفلحون',
    'لَّا تَجِدُ قَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ يُو<rule class=madda_necessary>َا</rule>ٓدُّونَ مَنۡ ح<rule class=madda_necessary>َا</rule>ٓدَّ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> وَلَوۡ كَان<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> ءَاب<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ أَوۡ أَ<rule class=qalaqah>بۡ</rule>ن<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ أَوۡ إِخۡو<rule class=madda_normal>ٰ</rule>نَهُمۡ أَوۡ عَشِيرَتَهُمۡ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ كَتَبَ فِى قُلُوبِهِمُ <rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نَ وَأَيَّدَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِرُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُ‌ۖ وَيُ<rule class=qalaqah>دۡ</rule>خِلُهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۚ رَضِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَنۡهُمۡ وَرَضُو<rule class=slnt>اۡ</rule> عَنۡهُ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ حِزۡبُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ أَل<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ حِزۡبَ <rule class=ham_wasl>ٱ</rule>للَّهِ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٢٢',
    22, 28, 7, 545, 478, 218, 'false'
  );
  

-- Surah Al-Hashr
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (59, 'سُورَةُ الحَشۡرِ', 'Al-Hashr', 'The Exile', 'Medinan', 24);

  -- Ayah 1 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5127,
    'سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'سبح لله ما في السماوات وما في الارض وهو العزيز الحكيم',
    'سَبَّحَ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ١',
    1, 28, 7, 545, 479, 218, 'false'
  );
  
  -- Ayah 2 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5128,
    'هُوَ ٱلَّذِیۤ أَخۡرَجَ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ مِن دِیَـٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن یَخۡرُجُوا۟ۖ وَظَنُّوۤا۟ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَیۡثُ لَمۡ یَحۡتَسِبُوا۟ۖ وَقَذَفَ فِی قُلُوبِهِمُ ٱلرُّعۡبَۚ یُخۡرِبُونَ بُیُوتَهُم بِأَیۡدِیهِمۡ وَأَیۡدِی ٱلۡمُؤۡمِنِینَ فَٱعۡتَبِرُوا۟ یَـٰۤأُو۟لِی ٱلۡأَبۡصَـٰرِ',
    'هو الذي اخرج الذين كفروا من اهل الكتاب من ديارهم لاول الحشر ما ظننتم ان يخرجوا وظنوا انهم مانعتهم حصونهم من الله فاتاهم الله من حيث لم يحتسبوا وقذف في قلوبهم الرعب يخربون بيوتهم بايديهم وايدي المؤمنين فاعتبروا يا اولي الابصار',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخۡرَجَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ لِأَوَّلِ <rule class=ham_wasl>ٱ</rule>لۡحَشۡرِ‌ۚ مَا ظَنَ<rule class=ikhafa>نت</rule>ُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡرُجُو<rule class=slnt>اۡ‌ۖ</rule> وَظَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّانِعَتُهُمۡ حُصُونُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَأَتَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُو<rule class=slnt>اۡ‌ۖ</rule> وَقَذَفَ فِى قُلُوبِهِمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّعۡبَ‌ۚ يُخۡرِبُونَ بُيُوتَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَيۡدِيهِمۡ وَأَيۡدِى <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ فَ<rule class=ham_wasl>ٱ</rule>عۡتَبِرُو<rule class=slnt>اۡ</rule> يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_permissible>ـٰ</rule>رِ ٢',
    2, 28, 7, 545, 479, 218, 'false'
  );
  
  -- Ayah 3 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5129,
    'وَلَوۡلَاۤ أَن كَتَبَ ٱللَّهُ عَلَیۡهِمُ ٱلۡجَلَاۤءَ لَعَذَّبَهُمۡ فِی ٱلدُّنۡیَاۖ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابُ ٱلنَّارِ',
    'ولولا ان كتب الله عليهم الجلاء لعذبهم في الدنيا ولهم في الاخرة عذاب النار',
    'وَلَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َتَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمُ <rule class=ham_wasl>ٱ</rule>لۡجَل<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لَعَذَّبَهُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا‌ۖ وَلَهُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ عَذَابُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule><rule class=madda_permissible>َا</rule>رِ ٣',
    3, 28, 7, 545, 479, 218, 'false'
  );
  
  -- Ayah 4 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5130,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمۡ شَاۤقُّوا۟ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن یُشَاۤقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ',
    'ذلك بانهم شاقوا الله ورسوله ومن يشاق الله فان الله شديد العقاب',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ ش<rule class=madda_necessary>َا</rule>ٓقُّو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule>‌ۖ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُش<rule class=madda_necessary>َا</rule>ٓقِّ <rule class=ham_wasl>ٱ</rule>للَّهَ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٤',
    4, 28, 7, 546, 479, 218, 'false'
  );
  
  -- Ayah 5 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5131,
    'مَا قَطَعۡتُم مِّن لِّینَةٍ أَوۡ تَرَكۡتُمُوهَا قَاۤىِٕمَةً عَلَىٰۤ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِیُخۡزِیَ ٱلۡفَـٰسِقِینَ',
    'ما قطعتم من لينة او تركتموها قائمة على اصولها فباذن الله وليخزي الفاسقين',
    'مَا قَطَعۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّينَةٍ أَوۡ تَرَكۡتُمُوهَا ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِمَةً عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أُصُولِهَا فَبِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَلِيُخۡزِىَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 28, 7, 546, 479, 218, 'false'
  );
  
  -- Ayah 6 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5132,
    'وَمَاۤ أَفَاۤءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَاۤ أَوۡجَفۡتُمۡ عَلَیۡهِ مِنۡ خَیۡلࣲ وَلَا رِكَابࣲ وَلَـٰكِنَّ ٱللَّهَ یُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن یَشَاۤءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'وما افاء الله على رسوله منهم فما اوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله على من يشاء والله على كل شيء قدير',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ رَسُولِه<rule class=madda_normal>ِۦ</rule> مِنۡهُمۡ فَم<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡجَفۡتُمۡ عَلَيۡهِ مِنۡ خَيۡ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا رِكَا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُسَلِّطُ رُسُلَهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٦',
    6, 28, 7, 546, 479, 218, 'false'
  );
  
  -- Ayah 7 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5133,
    'مَّاۤ أَفَاۤءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱبۡنِ ٱلسَّبِیلِ كَیۡ لَا یَكُونَ دُولَةَۢ بَیۡنَ ٱلۡأَغۡنِیَاۤءِ مِنكُمۡۚ وَمَاۤ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُوا۟ۚ وَٱتَّقُوا۟ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ',
    'ما افاء الله على رسوله من اهل القرى فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل كي لا يكون دولة بين الاغنياء منكم وما اتاكم الرسول فخذوه وما نهاكم عنه فانتهوا واتقوا الله ان الله شديد العقاب',
    'مّ<rule class=madda_obligatory_monfasel>َآ</rule> أَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ رَسُولِه<rule class=madda_normal>ِۦ</rule> مِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى <rule class=ham_wasl>ٱ</rule>لۡقُرۡبَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡيَتَ<rule class=madda_normal>ـٰ</rule>مَىٰ وَ<rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>كِينِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلِ كَىۡ لَا يَكُونَ دُولَ<rule class=iqlab>ةَۢ</rule> <rule class=iqlab>ب</rule>َيۡنَ <rule class=ham_wasl>ٱ</rule>لۡأَغۡنِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ مِ<rule class=ikhafa>نك</rule>ُمۡ‌ۚ وَم<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولُ فَخُذُوهُ وَمَا نَهَ<rule class=madda_normal>ـٰ</rule>كُمۡ عَنۡهُ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َهُو<rule class=slnt>اۡ‌ۚ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ شَدِيدُ <rule class=ham_wasl>ٱ</rule>لۡعِق<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ِ ٧',
    7, 28, 7, 546, 479, 218, 'false'
  );
  
  -- Ayah 8 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5134,
    'لِلۡفُقَرَاۤءِ ٱلۡمُهَـٰجِرِینَ ٱلَّذِینَ أُخۡرِجُوا۟ مِن دِیَـٰرِهِمۡ وَأَمۡوَ ٰ⁠لِهِمۡ یَبۡتَغُونَ فَضۡلࣰا مِّنَ ٱللَّهِ وَرِضۡوَ ٰ⁠نࣰا وَیَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥۤۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلصَّـٰدِقُونَ',
    'للفقراء المهاجرين الذين اخرجوا من ديارهم واموالهم يبتغون فضلا من الله ورضوانا وينصرون الله ورسوله اولئك هم الصادقون',
    'لِلۡفُقَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ <rule class=ham_wasl>ٱ</rule>لۡمُهَ<rule class=madda_normal>ـٰ</rule>جِرِينَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُخۡرِجُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ وَأَمۡو<rule class=madda_normal>ٰ</rule>لِهِمۡ يَ<rule class=qalaqah>بۡ</rule>تَغُونَ فَضۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرِضۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َيَ<rule class=ikhafa>نص</rule>ُرُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 28, 7, 546, 479, 218, 'false'
  );
  
  -- Ayah 9 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5135,
    'وَٱلَّذِینَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِیمَـٰنَ مِن قَبۡلِهِمۡ یُحِبُّونَ مَنۡ هَاجَرَ إِلَیۡهِمۡ وَلَا یَجِدُونَ فِی صُدُورِهِمۡ حَاجَةࣰ مِّمَّاۤ أُوتُوا۟ وَیُؤۡثِرُونَ عَلَىٰۤ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةࣱۚ وَمَن یُوقَ شُحَّ نَفۡسِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'والذين تبوءوا الدار والايمان من قبلهم يحبون من هاجر اليهم ولا يجدون في صدورهم حاجة مما اوتوا ويؤثرون على انفسهم ولو كان بهم خصاصة ومن يوق شح نفسه فاولئك هم المفلحون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ تَبَوَّءُو <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّارَ وَ<rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِى صُدُورِهِمۡ حَاجَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أُوتُو<rule class=slnt>اۡ</rule> وَيُؤۡثِرُونَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ikhafa>نف</rule>ُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَ<rule class=idgham_ghunnah>ةٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُوقَ شُحَّ نَفۡسِه<rule class=madda_normal>ِۦ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 28, 7, 546, 479, 218, 'false'
  );
  
  -- Ayah 10 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5136,
    'وَٱلَّذِینَ جَاۤءُو مِنۢ بَعۡدِهِمۡ یَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَ ٰ⁠نِنَا ٱلَّذِینَ سَبَقُونَا بِٱلۡإِیمَـٰنِ وَلَا تَجۡعَلۡ فِی قُلُوبِنَا غِلࣰّا لِّلَّذِینَ ءَامَنُوا۟ رَبَّنَاۤ إِنَّكَ رَءُوفࣱ رَّحِیمٌ',
    'والذين جاءوا من بعدهم يقولون ربنا اغفر لنا ولاخواننا الذين سبقونا بالايمان ولا تجعل في قلوبنا غلا للذين امنوا ربنا انك رءوف رحيم',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءُو م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِهِمۡ يَقُولُونَ رَبَّنَا <rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَنَا وَلِإِخۡو<rule class=madda_normal>ٰ</rule>نِنَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ سَبَقُونَا بِ<rule class=ham_wasl>ٱ</rule>لۡإِيمَ<rule class=madda_normal>ـٰ</rule>نِ وَلَا تَ<rule class=qalaqah>جۡ</rule>عَلۡ فِى قُلُوبِنَا غِل<rule class=idgham_wo_ghunnah>اًّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ رَءُو<rule class=idgham_wo_ghunnah>فٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٠',
    10, 28, 7, 547, 479, 218, 'false'
  );
  
  -- Ayah 11 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5137,
    '۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ نَافَقُوا۟ یَقُولُونَ لِإِخۡوَ ٰ⁠نِهِمُ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَىِٕنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِیعُ فِیكُمۡ أَحَدًا أَبَدࣰا وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ یَشۡهَدُ إِنَّهُمۡ لَكَـٰذِبُونَ',
    'الم تر الى الذين نافقوا يقولون لاخوانهم الذين كفروا من اهل الكتاب لئن اخرجتم لنخرجن معكم ولا نطيع فيكم احدا ابدا وان قوتلتم لننصرنكم والله يشهد انهم لكاذبون',
    '۞أَلَمۡ تَرَ إِلَى <rule class=ham_wasl>ٱ</rule>لَّذِينَ نَافَقُو<rule class=slnt>اۡ</rule> يَقُولُونَ لِإِخۡو<rule class=madda_normal>ٰ</rule>نِهِمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ لَئِنۡ أُخۡرِ<rule class=qalaqah>جۡ</rule>تُمۡ لَنَخۡرُجَ<rule class=ghunnah>نّ</rule>َ مَعَكُمۡ وَلَا نُطِيعُ فِيكُمۡ أَحَدًا أَبَ<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُوتِلۡتُمۡ لَنَ<rule class=ikhafa>نص</rule>ُرَ<rule class=ghunnah>نّ</rule>َكُمۡ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَشۡهَدُ إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 28, 7, 547, 480, 219, 'false'
  );
  
  -- Ayah 12 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5138,
    'لَىِٕنۡ أُخۡرِجُوا۟ لَا یَخۡرُجُونَ مَعَهُمۡ وَلَىِٕن قُوتِلُوا۟ لَا یَنصُرُونَهُمۡ وَلَىِٕن نَّصَرُوهُمۡ لَیُوَلُّنَّ ٱلۡأَدۡبَـٰرَ ثُمَّ لَا یُنصَرُونَ',
    'لئن اخرجوا لا يخرجون معهم ولئن قوتلوا لا ينصرونهم ولئن نصروهم ليولن الادبار ثم لا ينصرون',
    'لَئِنۡ أُخۡرِجُو<rule class=slnt>اۡ</rule> لَا يَخۡرُجُونَ مَعَهُمۡ وَلَئِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُوتِلُو<rule class=slnt>اۡ</rule> لَا يَ<rule class=ikhafa>نص</rule>ُرُونَهُمۡ وَلَئ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>َّصَرُوهُمۡ لَيُوَلُّ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>دۡ</rule>بَ<rule class=madda_normal>ـٰ</rule>رَ ثُ<rule class=ghunnah>مّ</rule>َ لَا يُ<rule class=ikhafa>نص</rule>َر<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 28, 7, 547, 480, 219, 'false'
  );
  
  -- Ayah 13 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5139,
    'لَأَنتُمۡ أَشَدُّ رَهۡبَةࣰ فِی صُدُورِهِم مِّنَ ٱللَّهِۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَفۡقَهُونَ',
    'لانتم اشد رهبة في صدورهم من الله ذلك بانهم قوم لا يفقهون',
    'لَأَ<rule class=ikhafa>نت</rule>ُمۡ أَشَدُّ رَهۡبَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى صُدُورِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَفۡقَه<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 28, 7, 547, 480, 219, 'false'
  );
  
  -- Ayah 14 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5140,
    'لَا یُقَـٰتِلُونَكُمۡ جَمِیعًا إِلَّا فِی قُرࣰى مُّحَصَّنَةٍ أَوۡ مِن وَرَاۤءِ جُدُرِۭۚ بَأۡسُهُم بَیۡنَهُمۡ شَدِیدࣱۚ تَحۡسَبُهُمۡ جَمِیعࣰا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَ ٰ⁠لِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَعۡقِلُونَ',
    'لا يقاتلونكم جميعا الا في قرى محصنة او من وراء جدر باسهم بينهم شديد تحسبهم جميعا وقلوبهم شتى ذلك بانهم قوم لا يعقلون',
    'لَا يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَكُمۡ جَمِيعًا إِلَّا فِى قُ<rule class=idgham_ghunnah>رًى</rule> <rule class=idgham_ghunnah>م</rule>ُّحَصَّنَةٍ أَوۡ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>َر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ جُدُ<rule class=iqlab>رِۭ‌ۚ</rule> <rule class=iqlab>ب</rule>َأۡسُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>َيۡنَهُمۡ شَدِي<rule class=ikhafa>دٌ‌ۚ</rule> <rule class=ikhafa>ت</rule>َحۡسَبُهُمۡ جَمِي<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َقُلُوبُهُمۡ شَتَّىٰ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ قَوۡ<rule class=idgham_wo_ghunnah>مٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَعۡقِل<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 28, 7, 547, 480, 219, 'false'
  );
  
  -- Ayah 15 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5141,
    'كَمَثَلِ ٱلَّذِینَ مِن قَبۡلِهِمۡ قَرِیبࣰاۖ ذَاقُوا۟ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ',
    'كمثل الذين من قبلهم قريبا ذاقوا وبال امرهم ولهم عذاب اليم',
    'كَمَثَلِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ قَرِي<rule class=ikhafa>بًا‌ۖ</rule> <rule class=ikhafa>ذ</rule>َاقُو<rule class=slnt>اۡ</rule> وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١٥',
    15, 28, 7, 547, 480, 219, 'false'
  );
  
  -- Ayah 16 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5142,
    'كَمَثَلِ ٱلشَّیۡطَـٰنِ إِذۡ قَالَ لِلۡإِنسَـٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ قَالَ إِنِّی بَرِیۤءࣱ مِّنكَ إِنِّیۤ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَـٰلَمِینَ',
    'كمثل الشيطان اذ قال للانسان اكفر فلما كفر قال اني بريء منك اني اخاف الله رب العالمين',
    'كَمَثَلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّيۡطَ<rule class=madda_normal>ـٰ</rule>نِ إِذۡ قَالَ لِلۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ <rule class=ham_wasl>ٱ</rule>كۡفُرۡ فَلَ<rule class=ghunnah>مّ</rule>َا كَفَرَ قَالَ إِ<rule class=ghunnah>نّ</rule>ِى بَر<rule class=madda_obligatory_mottasel>ِى</rule>ٓ<rule class=idgham_ghunnah>ءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>َ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَخَافُ <rule class=ham_wasl>ٱ</rule>للَّهَ رَبَّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ١٦',
    16, 28, 7, 547, 480, 219, 'false'
  );
  
  -- Ayah 17 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5143,
    'فَكَانَ عَـٰقِبَتَهُمَاۤ أَنَّهُمَا فِی ٱلنَّارِ خَـٰلِدَیۡنِ فِیهَاۚ وَذَ ٰ⁠لِكَ جَزَ ٰ⁠ۤؤُا۟ ٱلظَّـٰلِمِینَ',
    'فكان عاقبتهما انهما في النار خالدين فيها وذلك جزاء الظالمين',
    'فَكَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَتَهُم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ghunnah>نّ</rule>َهُمَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ خَ<rule class=madda_normal>ـٰ</rule>لِدَيۡنِ فِيهَا‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ جَز<rule class=madda_obligatory_mottasel>ٰ</rule>ٓؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 28, 7, 548, 480, 219, 'false'
  );
  
  -- Ayah 18 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5144,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسࣱ مَّا قَدَّمَتۡ لِغَدࣲۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا تَعۡمَلُونَ',
    'يا ايها الذين امنوا اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله ان الله خبير بما تعملون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَلۡتَ<rule class=ikhafa>نظ</rule>ُرۡ نَفۡ<rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا قَدَّمَتۡ لِغَ<rule class=idgham_ghunnah>دٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١٨',
    18, 28, 7, 548, 481, 219, 'false'
  );
  
  -- Ayah 19 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5145,
    'وَلَا تَكُونُوا۟ كَٱلَّذِینَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ',
    'ولا تكونوا كالذين نسوا الله فانساهم انفسهم اولئك هم الفاسقون',
    'وَلَا تَكُونُو<rule class=slnt>اۡ</rule> كَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ نَسُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ فَأَ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>هُمۡ أَ<rule class=ikhafa>نف</rule>ُسَهُمۡ‌ۚ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 28, 7, 548, 481, 219, 'false'
  );
  
  -- Ayah 20 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5146,
    'لَا یَسۡتَوِیۤ أَصۡحَـٰبُ ٱلنَّارِ وَأَصۡحَـٰبُ ٱلۡجَنَّةِۚ أَصۡحَـٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَاۤىِٕزُونَ',
    'لا يستوي اصحاب النار واصحاب الجنة اصحاب الجنة هم الفائزون',
    'لَا يَسۡتَو<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ وَأَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ‌ۚ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ هُمُ <rule class=ham_wasl>ٱ</rule>لۡف<rule class=madda_obligatory_mottasel>َا</rule>ٓئِز<rule class=madda_permissible>ُو</rule>نَ ٢٠',
    20, 28, 7, 548, 481, 219, 'false'
  );
  
  -- Ayah 21 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5147,
    'لَوۡ أَنزَلۡنَا هَـٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلࣲ لَّرَأَیۡتَهُۥ خَـٰشِعࣰا مُّتَصَدِّعࣰا مِّنۡ خَشۡیَةِ ٱللَّهِۚ وَتِلۡكَ ٱلۡأَمۡثَـٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ یَتَفَكَّرُونَ',
    'لو انزلنا هذا القران على جبل لرايته خاشعا متصدعا من خشية الله وتلك الامثال نضربها للناس لعلهم يتفكرون',
    'لَوۡ أَ<rule class=ikhafa>نز</rule>َلۡنَا هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ عَلَىٰ جَبَ<rule class=idgham_wo_ghunnah>لٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّرَأَيۡتَهُ<rule class=madda_normal>ۥ</rule> خَ<rule class=madda_normal>ـٰ</rule>شِ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>م</rule>ُّتَصَدِّ<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ خَشۡيَةِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَتِلۡكَ <rule class=ham_wasl>ٱ</rule>لۡأَمۡثَ<rule class=madda_normal>ـٰ</rule>لُ نَضۡرِبُهَا لِل<rule class=ghunnah>نّ</rule>َاسِ لَعَلَّهُمۡ يَتَفَكَّر<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 28, 7, 548, 481, 219, 'false'
  );
  
  -- Ayah 22 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5148,
    'هُوَ ٱللَّهُ ٱلَّذِی لَاۤ إِلَـٰهَ إِلَّا هُوَۖ عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِۖ هُوَ ٱلرَّحۡمَـٰنُ ٱلرَّحِیمُ',
    'هو الله الذي لا اله الا هو عالم الغيب والشهادة هو الرحمن الرحيم',
    'هُوَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۖ عَ<rule class=madda_normal>ـٰ</rule>لِمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ‌ۖ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّح<rule class=madda_permissible>ِي</rule>مُ ٢٢',
    22, 28, 7, 548, 481, 219, 'false'
  );
  
  -- Ayah 23 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5149,
    'هُوَ ٱللَّهُ ٱلَّذِی لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَـٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَیۡمِنُ ٱلۡعَزِیزُ ٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَـٰنَ ٱللَّهِ عَمَّا یُشۡرِكُونَ',
    'هو الله الذي لا اله الا هو الملك القدوس السلام المؤمن المهيمن العزيز الجبار المتكبر سبحان الله عما يشركون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ <rule class=ham_wasl>ٱ</rule>لۡمَلِكُ <rule class=ham_wasl>ٱ</rule>لۡقُدُّوسُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّلَ<rule class=madda_normal>ـٰ</rule>مُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنُ <rule class=ham_wasl>ٱ</rule>لۡمُهَيۡمِنُ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡجَبَّارُ <rule class=ham_wasl>ٱ</rule>لۡمُتَكَبِّرُ‌ۚ سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>للَّهِ عَ<rule class=ghunnah>مّ</rule>َا يُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 28, 7, 548, 481, 219, 'false'
  );
  
  -- Ayah 24 Surah Al-Hashr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    59,
    5150,
    'هُوَ ٱللَّهُ ٱلۡخَـٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰۚ یُسَبِّحُ لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'هو الله الخالق البارئ المصور له الاسماء الحسنى يسبح له ما في السماوات والارض وهو العزيز الحكيم',
    'هُوَ <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>لِقُ <rule class=ham_wasl>ٱ</rule>لۡبَارِئُ <rule class=ham_wasl>ٱ</rule>لۡمُصَوِّرُ‌ۖ لَهُ <rule class=ham_wasl>ٱ</rule>لۡأَسۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule>لۡحُسۡنَىٰ‌ۚ يُسَبِّحُ لَهُ<rule class=madda_normal>ۥ</rule> مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٢٤',
    24, 28, 7, 548, 481, 219, 'false'
  );
  

-- Surah Al-Mumtahana
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (60, 'سُورَةُ المُمۡتَحنَةِ', 'Al-Mumtahana', 'She that is to be examined', 'Medinan', 13);

  -- Ayah 1 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5151,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّی وَعَدُوَّكُمۡ أَوۡلِیَاۤءَ تُلۡقُونَ إِلَیۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُوا۟ بِمَا جَاۤءَكُم مِّنَ ٱلۡحَقِّ یُخۡرِجُونَ ٱلرَّسُولَ وَإِیَّاكُمۡ أَن تُؤۡمِنُوا۟ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَـٰدࣰا فِی سَبِیلِی وَٱبۡتِغَاۤءَ مَرۡضَاتِیۚ تُسِرُّونَ إِلَیۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَاۤ أَخۡفَیۡتُمۡ وَمَاۤ أَعۡلَنتُمۡۚ وَمَن یَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَاۤءَ ٱلسَّبِیلِ',
    'يا ايها الذين امنوا لا تتخذوا عدوي وعدوكم اولياء تلقون اليهم بالمودة وقد كفروا بما جاءكم من الحق يخرجون الرسول واياكم ان تؤمنوا بالله ربكم ان كنتم خرجتم جهادا في سبيلي وابتغاء مرضاتي تسرون اليهم بالمودة وانا اعلم بما اخفيتم وما اعلنتم ومن يفعله منكم فقد ضل سواء السبيل',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَتَّخِذُو<rule class=slnt>اۡ</rule> عَدُوِّى وَعَدُوَّكُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ تُلۡقُونَ إِلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَوَدَّةِ وَقَ<rule class=qalaqah>دۡ</rule> كَفَرُو<rule class=slnt>اۡ</rule> بِمَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ يُخۡرِجُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ وَإِيَّاكُمۡ‌ۙ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُؤۡمِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ رَبِّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ خَرَ<rule class=qalaqah>جۡ</rule>تُمۡ جِهَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>دًا</rule> <rule class=ikhafa>ف</rule>ِى سَبِيلِى وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تِغ<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَرۡضَاتِى‌ۚ تُسِرُّونَ إِلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡمَوَدَّةِ وَأَنَاۡ أَعۡلَمُ بِم<rule class=madda_obligatory_monfasel>َآ</rule> أَخۡفَيۡتُمۡ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡلَ<rule class=ikhafa>نت</rule>ُمۡ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلۡهُ مِ<rule class=ikhafa>نك</rule>ُمۡ فَقَ<rule class=qalaqah>دۡ</rule> ضَلَّ سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّب<rule class=madda_permissible>ِي</rule>لِ ١',
    1, 28, 7, 549, 482, 219, 'false'
  );
  
  -- Ayah 2 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5152,
    'إِن یَثۡقَفُوكُمۡ یَكُونُوا۟ لَكُمۡ أَعۡدَاۤءࣰ وَیَبۡسُطُوۤا۟ إِلَیۡكُمۡ أَیۡدِیَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوۤءِ وَوَدُّوا۟ لَوۡ تَكۡفُرُونَ',
    'ان يثقفوكم يكونوا لكم اعداء ويبسطوا اليكم ايديهم والسنتهم بالسوء وودوا لو تكفرون',
    'إ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َثۡقَفُوكُمۡ يَكُونُو<rule class=slnt>اۡ</rule> لَكُمۡ أَعۡد<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َيَ<rule class=qalaqah>بۡ</rule>سُط<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡكُمۡ أَيۡدِيَهُمۡ وَأَلۡسِنَتَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_obligatory_mottasel>ُو</rule>ٓءِ وَوَدُّو<rule class=slnt>اۡ</rule> لَوۡ تَكۡفُر<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 28, 7, 549, 482, 219, 'false'
  );
  
  -- Ayah 3 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5153,
    'لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَاۤ أَوۡلَـٰدُكُمۡۚ یَوۡمَ ٱلۡقِیَـٰمَةِ یَفۡصِلُ بَیۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ',
    'لن تنفعكم ارحامكم ولا اولادكم يوم القيامة يفصل بينكم والله بما تعملون بصير',
    'لَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نف</rule>َعَكُمۡ أَرۡحَامُكُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دُكُمۡ‌ۚ يَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ يَفۡصِلُ بَيۡنَكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٣',
    3, 28, 7, 549, 482, 219, 'false'
  );
  
  -- Ayah 4 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5154,
    'قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةࣱ فِیۤ إِبۡرَ ٰ⁠هِیمَ وَٱلَّذِینَ مَعَهُۥۤ إِذۡ قَالُوا۟ لِقَوۡمِهِمۡ إِنَّا بُرَءَ ٰۤ⁠ ؤُا۟ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَیۡنَنَا وَبَیۡنَكُمُ ٱلۡعَدَ ٰ⁠وَةُ وَٱلۡبَغۡضَاۤءُ أَبَدًا حَتَّىٰ تُؤۡمِنُوا۟ بِٱللَّهِ وَحۡدَهُۥۤ إِلَّا قَوۡلَ إِبۡرَ ٰ⁠هِیمَ لِأَبِیهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَاۤ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَیۡءࣲۖ رَّبَّنَا عَلَیۡكَ تَوَكَّلۡنَا وَإِلَیۡكَ أَنَبۡنَا وَإِلَیۡكَ ٱلۡمَصِیرُ',
    'قد كانت لكم اسوة حسنة في ابراهيم والذين معه اذ قالوا لقومهم انا براء منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العداوة والبغضاء ابدا حتى تؤمنوا بالله وحده الا قول ابراهيم لابيه لاستغفرن لك وما املك لك من الله من شيء ربنا عليك توكلنا واليك انبنا واليك المصير',
    'قَ<rule class=qalaqah>دۡ</rule> كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَ<rule class=ikhafa>ةٌ</rule> <rule class=ikhafa>ف</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ مَعَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِذۡ قَالُو<rule class=slnt>اۡ</rule> لِقَوۡمِهِمۡ إِ<rule class=ghunnah>نّ</rule>َا بُرَء<rule class=madda_obligatory_mottasel>ٰ</rule>ٓؤُ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>نك</rule>ُمۡ وَمِ<rule class=ghunnah>مّ</rule>َا تَعۡبُدُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَيۡنَنَا وَبَيۡنَكُمُ <rule class=ham_wasl>ٱ</rule>لۡعَد<rule class=madda_normal>ٰ</rule>وَةُ وَ<rule class=ham_wasl>ٱ</rule>لۡبَغۡض<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ أَبَدًا حَتَّىٰ تُؤۡمِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَحۡدَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا قَوۡلَ إِ<rule class=qalaqah>بۡ</rule>ر<rule class=madda_normal>ٰ</rule>هِيمَ لِأَبِيهِ لَأَسۡتَغۡفِرَ<rule class=ghunnah>نّ</rule>َ لَكَ وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡلِكُ لَكَ مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=idgham_wo_ghunnah>َىۡءٍ‌ۖ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَ<rule class=qalaqah>بۡ</rule>نَا وَإِلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٤',
    4, 28, 7, 549, 482, 219, 'false'
  );
  
  -- Ayah 5 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5155,
    'رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةࣰ لِّلَّذِینَ كَفَرُوا۟ وَٱغۡفِرۡ لَنَا رَبَّنَاۤۖ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا انك انت العزيز الحكيم',
    'رَبَّنَا لَا تَ<rule class=qalaqah>جۡ</rule>عَلۡنَا فِتۡنَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَنَا رَبَّن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ أَ<rule class=ikhafa>نت</rule>َ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٥',
    5, 28, 7, 549, 482, 219, 'false'
  );
  
  -- Ayah 6 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5156,
    'لَقَدۡ كَانَ لَكُمۡ فِیهِمۡ أُسۡوَةٌ حَسَنَةࣱ لِّمَن كَانَ یَرۡجُوا۟ ٱللَّهَ وَٱلۡیَوۡمَ ٱلۡـَٔاخِرَۚ وَمَن یَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ',
    'لقد كان لكم فيهم اسوة حسنة لمن كان يرجو الله واليوم الاخر ومن يتول فان الله هو الغني الحميد',
    'لَقَ<rule class=qalaqah>دۡ</rule> كَانَ لَكُمۡ فِيهِمۡ أُسۡوَةٌ حَسَنَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يَرۡجُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَلَّ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡغَنِىُّ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ُ ٦',
    6, 28, 7, 550, 482, 219, 'false'
  );
  
  -- Ayah 7 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5157,
    '۞ عَسَى ٱللَّهُ أَن یَجۡعَلَ بَیۡنَكُمۡ وَبَیۡنَ ٱلَّذِینَ عَادَیۡتُم مِّنۡهُم مَّوَدَّةࣰۚ وَٱللَّهُ قَدِیرࣱۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'عسى الله ان يجعل بينكم وبين الذين عاديتم منهم مودة والله قدير والله غفور رحيم',
    '۞عَسَى <rule class=ham_wasl>ٱ</rule>للَّهُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>عَلَ بَيۡنَكُمۡ وَبَيۡنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ عَادَيۡت<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّوَدَّ<rule class=idgham_ghunnah>ةً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ قَدِي<rule class=idgham_ghunnah>رٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ٧',
    7, 28, 7, 550, 483, 220, 'false'
  );
  
  -- Ayah 8 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5158,
    'لَّا یَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِینَ لَمۡ یُقَـٰتِلُوكُمۡ فِی ٱلدِّینِ وَلَمۡ یُخۡرِجُوكُم مِّن دِیَـٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوۤا۟ إِلَیۡهِمۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُقۡسِطِینَ',
    'لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم ان تبروهم وتقسطوا اليهم ان الله يحب المقسطين',
    'لَّا يَنۡهَ<rule class=madda_normal>ـٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَنِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ لَمۡ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُوكُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ وَلَمۡ يُخۡرِجُوك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َبَرُّوهُمۡ وَتُ<rule class=qalaqah>قۡ</rule>سِط<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهِمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>قۡ</rule>سِط<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 28, 7, 550, 483, 220, 'false'
  );
  
  -- Ayah 9 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5159,
    'إِنَّمَا یَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِینَ قَـٰتَلُوكُمۡ فِی ٱلدِّینِ وَأَخۡرَجُوكُم مِّن دِیَـٰرِكُمۡ وَظَـٰهَرُوا۟ عَلَىٰۤ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن یَتَوَلَّهُمۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ',
    'انما ينهاكم الله عن الذين قاتلوكم في الدين واخرجوكم من دياركم وظاهروا على اخراجكم ان تولوهم ومن يتولهم فاولئك هم الظالمون',
    'إِ<rule class=ghunnah>نّ</rule>َمَا يَنۡهَ<rule class=madda_normal>ـٰ</rule>كُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَنِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ قَ<rule class=madda_normal>ـٰ</rule>تَلُوكُمۡ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ وَأَخۡرَجُوك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ِيَ<rule class=madda_normal>ـٰ</rule>رِكُمۡ وَظَ<rule class=madda_normal>ـٰ</rule>هَرُو<rule class=slnt>اۡ</rule> عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِخۡرَاجِكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّوۡهُمۡ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَلَّهُمۡ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 28, 7, 550, 483, 220, 'false'
  );
  
  -- Ayah 10 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5160,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا جَاۤءَكُمُ ٱلۡمُؤۡمِنَـٰتُ مُهَـٰجِرَ ٰ⁠تࣲ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِیمَـٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَـٰتࣲ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلࣱّ لَّهُمۡ وَلَا هُمۡ یَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّاۤ أَنفَقُوا۟ۚ وَلَا جُنَاحَ عَلَیۡكُمۡ أَن تَنكِحُوهُنَّ إِذَاۤ ءَاتَیۡتُمُوهُنَّ أُجُورَهُنَّۚ وَلَا تُمۡسِكُوا۟ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُوا۟ مَاۤ أَنفَقۡتُمۡ وَلۡیَسۡـَٔلُوا۟ مَاۤ أَنفَقُوا۟ۚ ذَ ٰ⁠لِكُمۡ حُكۡمُ ٱللَّهِ یَحۡكُمُ بَیۡنَكُمۡۖ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ',
    'يا ايها الذين امنوا اذا جاءكم المؤمنات مهاجرات فامتحنوهن الله اعلم بايمانهن فان علمتموهن مؤمنات فلا ترجعوهن الى الكفار لا هن حل لهم ولا هم يحلون لهن واتوهم ما انفقوا ولا جناح عليكم ان تنكحوهن اذا اتيتموهن اجورهن ولا تمسكوا بعصم الكوافر واسالوا ما انفقتم وليسالوا ما انفقوا ذلكم حكم الله يحكم بينكم والله عليم حكيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكُمُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تُ مُهَ<rule class=madda_normal>ـٰ</rule>جِر<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>مۡتَحِنُوهُ<rule class=ghunnah>نّ</rule>َ‌ۖ <rule class=ham_wasl>ٱ</rule>للَّهُ أَعۡلَمُ بِإِيمَ<rule class=madda_normal>ـٰ</rule>نِهِ<rule class=ghunnah>نّ</rule>َ‌ۖ فَإِنۡ عَلِمۡتُمُوهُ<rule class=ghunnah>نّ</rule>َ مُؤۡمِنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ف</rule>َلَا تَرۡجِعُوهُ<rule class=ghunnah>نّ</rule>َ إِلَى <rule class=ham_wasl>ٱ</rule>لۡكُفَّارِ‌ۖ لَا هُ<rule class=ghunnah>نّ</rule>َ حِ<rule class=idgham_wo_ghunnah>لٌّ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّهُمۡ وَلَا هُمۡ يَحِلُّونَ لَهُ<rule class=ghunnah>نّ</rule>َ‌ۖ وَءَاتُوه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ‌ۚ</rule> وَلَا جُنَاحَ عَلَيۡكُمۡ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َ<rule class=ikhafa>نك</rule>ِحُوهُ<rule class=ghunnah>نّ</rule>َ إِذ<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَيۡتُمُوهُ<rule class=ghunnah>نّ</rule>َ أُجُورَهُ<rule class=ghunnah>نّ</rule>َ‌ۚ وَلَا تُمۡسِكُو<rule class=slnt>اۡ</rule> بِعِصَمِ <rule class=ham_wasl>ٱ</rule>لۡكَوَافِرِ وَسۡــَٔلُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َ<rule class=qalaqah>قۡ</rule>تُمۡ وَلۡيَسۡــَٔلُو<rule class=slnt>اۡ</rule> م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ‌ۚ</rule> ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ حُكۡمُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ يَحۡكُمُ بَيۡنَكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِيمٌ حَك<rule class=madda_permissible>ِي</rule>مٌ ١٠',
    10, 28, 7, 550, 483, 220, 'false'
  );
  
  -- Ayah 11 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5161,
    'وَإِن فَاتَكُمۡ شَیۡءࣱ مِّنۡ أَزۡوَ ٰ⁠جِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ فَـَٔاتُوا۟ ٱلَّذِینَ ذَهَبَتۡ أَزۡوَ ٰ⁠جُهُم مِّثۡلَ مَاۤ أَنفَقُوا۟ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ أَنتُم بِهِۦ مُؤۡمِنُونَ',
    'وان فاتكم شيء من ازواجكم الى الكفار فعاقبتم فاتوا الذين ذهبت ازواجهم مثل ما انفقوا واتقوا الله الذي انتم به مؤمنون',
    'وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َاتَكُمۡ ش<rule class=idgham_ghunnah>َىۡءٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَزۡو<rule class=madda_normal>ٰ</rule>جِكُمۡ إِلَى <rule class=ham_wasl>ٱ</rule>لۡكُفَّارِ فَعَاقَ<rule class=qalaqah>بۡ</rule>تُمۡ فَـَٔـاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ ذَهَبَتۡ أَزۡو<rule class=madda_normal>ٰ</rule>جُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّثۡلَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نف</rule>َقُو<rule class=slnt>اۡ‌ۚ</rule> وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> مُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 28, 7, 550, 483, 220, 'false'
  );
  
  -- Ayah 12 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5162,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِذَا جَاۤءَكَ ٱلۡمُؤۡمِنَـٰتُ یُبَایِعۡنَكَ عَلَىٰۤ أَن لَّا یُشۡرِكۡنَ بِٱللَّهِ شَیۡـࣰٔا وَلَا یَسۡرِقۡنَ وَلَا یَزۡنِینَ وَلَا یَقۡتُلۡنَ أَوۡلَـٰدَهُنَّ وَلَا یَأۡتِینَ بِبُهۡتَـٰنࣲ یَفۡتَرِینَهُۥ بَیۡنَ أَیۡدِیهِنَّ وَأَرۡجُلِهِنَّ وَلَا یَعۡصِینَكَ فِی مَعۡرُوفࣲ فَبَایِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ',
    'يا ايها النبي اذا جاءك المؤمنات يبايعنك على ان لا يشركن بالله شيئا ولا يسرقن ولا يزنين ولا يقتلن اولادهن ولا ياتين ببهتان يفترينه بين ايديهن وارجلهن ولا يعصينك في معروف فبايعهن واستغفر لهن الله ان الله غفور رحيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تُ يُبَايِعۡنَكَ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُشۡرِكۡنَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَسۡرِ<rule class=qalaqah>قۡ</rule>نَ وَلَا يَزۡنِينَ وَلَا يَ<rule class=qalaqah>قۡ</rule>تُلۡنَ أَوۡلَ<rule class=madda_normal>ـٰ</rule>دَهُ<rule class=ghunnah>نّ</rule>َ وَلَا يَأۡتِينَ بِبُهۡتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٍ</rule> <rule class=idgham_ghunnah>ي</rule>َفۡتَرِينَهُ<rule class=madda_normal>ۥ</rule> بَيۡنَ أَيۡدِيهِ<rule class=ghunnah>نّ</rule>َ وَأَرۡجُلِهِ<rule class=ghunnah>نّ</rule>َ وَلَا يَعۡصِينَكَ فِى مَعۡرُو<rule class=ikhafa>فٍ‌ۙ</rule> <rule class=ikhafa>ف</rule>َبَايِعۡهُ<rule class=ghunnah>نّ</rule>َ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرۡ لَهُ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٢',
    12, 28, 7, 551, 483, 220, 'false'
  );
  
  -- Ayah 13 Surah Al-Mumtahana
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    60,
    5163,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَوَلَّوۡا۟ قَوۡمًا غَضِبَ ٱللَّهُ عَلَیۡهِمۡ قَدۡ یَىِٕسُوا۟ مِنَ ٱلۡـَٔاخِرَةِ كَمَا یَىِٕسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَـٰبِ ٱلۡقُبُورِ',
    'يا ايها الذين امنوا لا تتولوا قوما غضب الله عليهم قد يئسوا من الاخرة كما يئس الكفار من اصحاب القبور',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تَتَوَلَّوۡ<rule class=slnt>اۡ</rule> قَوۡمًا غَضِبَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِمۡ قَ<rule class=qalaqah>دۡ</rule> يَئِسُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ كَمَا يَئِسَ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارُ مِنۡ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡقُب<rule class=madda_permissible>ُو</rule>رِ ١٣',
    13, 28, 7, 551, 483, 220, 'false'
  );
  

-- Surah As-Saff
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (61, 'سُورَةُ الصَّفِّ', 'As-Saff', 'The Ranks', 'Medinan', 14);

  -- Ayah 1 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5164,
    'سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'سبح لله ما في السماوات وما في الارض وهو العزيز الحكيم',
    'سَبَّحَ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ١',
    1, 28, 7, 551, 484, 220, 'false'
  );
  
  -- Ayah 2 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5165,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ',
    'يا ايها الذين امنوا لم تقولون ما لا تفعلون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لِمَ تَقُولُونَ مَا لَا تَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 28, 7, 551, 484, 220, 'false'
  );
  
  -- Ayah 3 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5166,
    'كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفۡعَلُونَ',
    'كبر مقتا عند الله ان تقولوا ما لا تفعلون',
    'كَبُرَ مَ<rule class=qalaqah>قۡ</rule>تًا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولُو<rule class=slnt>اۡ</rule> مَا لَا تَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 28, 7, 551, 484, 220, 'false'
  );
  
  -- Ayah 4 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5167,
    'إِنَّ ٱللَّهَ یُحِبُّ ٱلَّذِینَ یُقَـٰتِلُونَ فِی سَبِیلِهِۦ صَفࣰّا كَأَنَّهُم بُنۡیَـٰنࣱ مَّرۡصُوصࣱ',
    'ان الله يحب الذين يقاتلون في سبيله صفا كانهم بنيان مرصوص',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحِبُّ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَ فِى سَبِيلِه<rule class=madda_normal>ِۦ</rule> صَف<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ك</rule>َأَ<rule class=ghunnah>نّ</rule>َه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ُنۡيَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>َّرۡص<rule class=madda_permissible>ُو</rule>صٌ ٤',
    4, 28, 7, 551, 484, 220, 'false'
  );
  
  -- Ayah 5 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5168,
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ یَـٰقَوۡمِ لِمَ تُؤۡذُونَنِی وَقَد تَّعۡلَمُونَ أَنِّی رَسُولُ ٱللَّهِ إِلَیۡكُمۡۖ فَلَمَّا زَاغُوۤا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ',
    'واذ قال موسى لقومه يا قوم لم تؤذونني وقد تعلمون اني رسول الله اليكم فلما زاغوا ازاغ الله قلوبهم والله لا يهدي القوم الفاسقين',
    'وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِه<rule class=madda_normal>ِۦ</rule> يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ لِمَ تُؤۡذُونَنِى وَقَ<rule class=idgham_mutajanisayn>د</rule> تَّعۡلَمُونَ أَ<rule class=ghunnah>نّ</rule>ِى رَسُولُ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَيۡكُمۡ‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا زَاغ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَزَاغَ <rule class=ham_wasl>ٱ</rule>للَّهُ قُلُوبَهُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 28, 7, 551, 484, 220, 'false'
  );
  
  -- Ayah 6 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5169,
    'وَإِذۡ قَالَ عِیسَى ٱبۡنُ مَرۡیَمَ یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ إِنِّی رَسُولُ ٱللَّهِ إِلَیۡكُم مُّصَدِّقࣰا لِّمَا بَیۡنَ یَدَیَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولࣲ یَأۡتِی مِنۢ بَعۡدِی ٱسۡمُهُۥۤ أَحۡمَدُۖ فَلَمَّا جَاۤءَهُم بِٱلۡبَیِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحۡرࣱ مُّبِینࣱ',
    'واذ قال عيسى ابن مريم يا بني اسرائيل اني رسول الله اليكم مصدقا لما بين يدي من التوراة ومبشرا برسول ياتي من بعدي اسمه احمد فلما جاءهم بالبينات قالوا هذا سحر مبين',
    'وَإِذۡ قَالَ عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ يَ<rule class=madda_normal>ـٰ</rule>بَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ إِ<rule class=ghunnah>نّ</rule>ِى رَسُولُ <rule class=ham_wasl>ٱ</rule>للَّهِ إِلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّصَدِّ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّمَا بَيۡنَ يَدَىَّ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةِ وَمُبَشِّر<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِرَسُو<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِى م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِى <rule class=ham_wasl>ٱ</rule>سۡمُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَحۡمَدُ‌ۖ فَلَ<rule class=ghunnah>مّ</rule>َا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ قَالُو<rule class=slnt>اۡ</rule> هَ<rule class=madda_normal>ـٰ</rule>ذَا سِحۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٦',
    6, 28, 7, 552, 484, 220, 'false'
  );
  
  -- Ayah 7 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5170,
    'وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُوَ یُدۡعَىٰۤ إِلَى ٱلۡإِسۡلَـٰمِۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'ومن اظلم ممن افترى على الله الكذب وهو يدعى الى الاسلام والله لا يهدي القوم الظالمين',
    'وَمَنۡ أَظۡلَمُ مِ<rule class=ghunnah>مّ</rule>َنِ <rule class=ham_wasl>ٱ</rule>فۡتَرَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡكَذِبَ وَهُوَ يُ<rule class=qalaqah>دۡ</rule>عَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡإِسۡلَ<rule class=madda_normal>ـٰ</rule>مِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 28, 7, 552, 484, 220, 'false'
  );
  
  -- Ayah 8 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5171,
    'یُرِیدُونَ لِیُطۡفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفۡوَ ٰ⁠هِهِمۡ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَـٰفِرُونَ',
    'يريدون ليطفئوا نور الله بافواههم والله متم نوره ولو كره الكافرون',
    'يُرِيدُونَ لِيُ<rule class=qalaqah>طۡ</rule>فِــُٔو<rule class=slnt>اۡ</rule> نُورَ <rule class=ham_wasl>ٱ</rule>للَّهِ بِأَفۡو<rule class=madda_normal>ٰ</rule>هِهِمۡ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ مُتِ<rule class=ghunnah>مّ</rule>ُ نُورِه<rule class=madda_normal>ِۦ</rule> وَلَوۡ كَرِهَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 28, 7, 552, 484, 220, 'false'
  );
  
  -- Ayah 9 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5172,
    'هُوَ ٱلَّذِیۤ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِینِ ٱلۡحَقِّ لِیُظۡهِرَهُۥ عَلَى ٱلدِّینِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ',
    'هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَرۡسَلَ رَسُولَهُ<rule class=madda_normal>ۥ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡهُدَىٰ وَدِينِ <rule class=ham_wasl>ٱ</rule>لۡحَقِّ لِيُظۡهِرَهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينِ كُلِّه<rule class=madda_normal>ِۦ</rule> وَلَوۡ كَرِهَ <rule class=ham_wasl>ٱ</rule>لۡمُشۡرِك<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 28, 7, 552, 484, 220, 'false'
  );
  
  -- Ayah 10 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5173,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَـٰرَةࣲ تُنجِیكُم مِّنۡ عَذَابٍ أَلِیمࣲ',
    'يا ايها الذين امنوا هل ادلكم على تجارة تنجيكم من عذاب اليم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَ<rule class=madda_normal>ـٰ</rule>رَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ت</rule>ُ<rule class=ikhafa>نج</rule>ِيك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ١٠',
    10, 28, 7, 552, 485, 220, 'false'
  );
  
  -- Ayah 11 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5174,
    'تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَـٰهِدُونَ فِی سَبِیلِ ٱللَّهِ بِأَمۡوَ ٰ⁠لِكُمۡ وَأَنفُسِكُمۡۚ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ',
    'تؤمنون بالله ورسوله وتجاهدون في سبيل الله باموالكم وانفسكم ذلكم خير لكم ان كنتم تعلمون',
    'تُؤۡمِنُونَ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَتُجَ<rule class=madda_normal>ـٰ</rule>هِدُونَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ بِأَمۡو<rule class=madda_normal>ٰ</rule>لِكُمۡ وَأَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 28, 7, 552, 485, 220, 'false'
  );
  
  -- Ayah 12 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5175,
    'یَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَیُدۡخِلۡكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ وَمَسَـٰكِنَ طَیِّبَةࣰ فِی جَنَّـٰتِ عَدۡنࣲۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'يغفر لكم ذنوبكم ويدخلكم جنات تجري من تحتها الانهار ومساكن طيبة في جنات عدن ذلك الفوز العظيم',
    'يَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَيُ<rule class=qalaqah>دۡ</rule>خِلۡكُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ وَمَسَ<rule class=madda_normal>ـٰ</rule>كِنَ طَيِّبَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>ِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ عَ<rule class=qalaqah>دۡ</rule><rule class=ikhafa>نٍ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ١٢',
    12, 28, 7, 552, 485, 220, 'false'
  );
  
  -- Ayah 13 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5176,
    'وَأُخۡرَىٰ تُحِبُّونَهَاۖ نَصۡرࣱ مِّنَ ٱللَّهِ وَفَتۡحࣱ قَرِیبࣱۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ',
    'واخرى تحبونها نصر من الله وفتح قريب وبشر المؤمنين',
    'وَأُخۡرَىٰ تُحِبُّونَهَا‌ۖ نَصۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَفَتۡ<rule class=ikhafa>حٌ</rule> <rule class=ikhafa>ق</rule>َرِي<rule class=idgham_ghunnah>بٌ‌ۗ</rule> <rule class=idgham_ghunnah>و</rule>َبَشِّرِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 28, 7, 552, 485, 220, 'false'
  );
  
  -- Ayah 14 Surah As-Saff
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    61,
    5177,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُونُوۤا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِیسَى ٱبۡنُ مَرۡیَمَ لِلۡحَوَارِیِّـۧنَ مَنۡ أَنصَارِیۤ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِیُّونَ نَحۡنُ أَنصَارُ ٱللَّهِۖ فَـَٔامَنَت طَّاۤىِٕفَةࣱ مِّنۢ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ وَكَفَرَت طَّاۤىِٕفَةࣱۖ فَأَیَّدۡنَا ٱلَّذِینَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُوا۟ ظَـٰهِرِینَ',
    'يا ايها الذين امنوا كونوا انصار الله كما قال عيسى ابن مريم للحواريين من انصاري الى الله قال الحواريون نحن انصار الله فامنت طائفة من بني اسرائيل وكفرت طائفة فايدنا الذين امنوا على عدوهم فاصبحوا ظاهرين',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> كُون<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نص</rule>َارَ <rule class=ham_wasl>ٱ</rule>للَّهِ كَمَا قَالَ عِيسَى <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نُ مَرۡيَمَ لِلۡحَوَارِيِّـ<rule class=madda_normal>ـۧ</rule>نَ مَنۡ أَ<rule class=ikhafa>نص</rule>َار<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ قَالَ <rule class=ham_wasl>ٱ</rule>لۡحَوَارِيُّونَ نَحۡنُ أَ<rule class=ikhafa>نص</rule>َارُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ فَـَٔـامَنَ<rule class=idgham_mutajanisayn>ت</rule> طّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِسۡر<rule class=madda_obligatory_mottasel>ٰ</rule>ٓءِيلَ وَكَفَرَ<rule class=idgham_mutajanisayn>ت</rule> طّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َأَيَّ<rule class=qalaqah>دۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُو<rule class=slnt>اۡ</rule> ظَ<rule class=madda_normal>ـٰ</rule>هِر<rule class=madda_permissible>ِي</rule>نَ ١٤',
    14, 28, 7, 552, 485, 220, 'false'
  );
  

-- Surah Al-Jumua
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (62, 'سُورَةُ الجُمُعَةِ', 'Al-Jumua', 'Friday', 'Medinan', 11);

  -- Ayah 1 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5178,
    'یُسَبِّحُ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ',
    'يسبح لله ما في السماوات وما في الارض الملك القدوس العزيز الحكيم',
    'يُسَبِّحُ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ <rule class=ham_wasl>ٱ</rule>لۡمَلِكِ <rule class=ham_wasl>ٱ</rule>لۡقُدُّوسِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مِ ١',
    1, 28, 7, 553, 486, 221, 'false'
  );
  
  -- Ayah 2 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5179,
    'هُوَ ٱلَّذِی بَعَثَ فِی ٱلۡأُمِّیِّـۧنَ رَسُولࣰا مِّنۡهُمۡ یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِهِۦ وَیُزَكِّیهِمۡ وَیُعَلِّمُهُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُوا۟ مِن قَبۡلُ لَفِی ضَلَـٰلࣲ مُّبِینࣲ',
    'هو الذي بعث في الاميين رسولا منهم يتلو عليهم اياته ويزكيهم ويعلمهم الكتاب والحكمة وان كانوا من قبل لفي ضلال مبين',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى بَعَثَ فِى <rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ghunnah>مّ</rule>ِيِّـ<rule class=madda_normal>ـۧ</rule>نَ رَسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ يَتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule> وَيُزَكِّيهِمۡ وَيُعَلِّمُهُمُ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ وَ<rule class=ham_wasl>ٱ</rule>لۡحِكۡمَةَ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ لَفِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٢',
    2, 28, 7, 553, 486, 221, 'false'
  );
  
  -- Ayah 3 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5180,
    'وَءَاخَرِینَ مِنۡهُمۡ لَمَّا یَلۡحَقُوا۟ بِهِمۡۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'واخرين منهم لما يلحقوا بهم وهو العزيز الحكيم',
    'وَءَاخَرِينَ مِنۡهُمۡ لَ<rule class=ghunnah>مّ</rule>َا يَلۡحَقُو<rule class=slnt>اۡ</rule> بِهِمۡ‌ۚ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٣',
    3, 28, 7, 553, 486, 221, 'false'
  );
  
  -- Ayah 4 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5181,
    'ذَ ٰ⁠لِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ',
    'ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ فَضۡلُ <rule class=ham_wasl>ٱ</rule>للَّهِ يُؤۡتِيهِ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ ذُو <rule class=ham_wasl>ٱ</rule>لۡفَضۡلِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٤',
    4, 28, 7, 553, 486, 221, 'false'
  );
  
  -- Ayah 5 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5182,
    'مَثَلُ ٱلَّذِینَ حُمِّلُوا۟ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ یَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ یَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ',
    'مثل الذين حملوا التوراة ثم لم يحملوها كمثل الحمار يحمل اسفارا بئس مثل القوم الذين كذبوا بايات الله والله لا يهدي القوم الظالمين',
    'مَثَلُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ حُ<rule class=ghunnah>مّ</rule>ِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّوۡرَ<rule class=madda_normal>ٮٰ</rule>ةَ ثُ<rule class=ghunnah>مّ</rule>َ لَمۡ يَحۡمِلُوهَا كَمَثَلِ <rule class=ham_wasl>ٱ</rule>لۡحِمَارِ يَحۡمِلُ أَسۡفَار<rule class=iqlab>َۢا‌ۚ</rule> <rule class=iqlab>ب</rule>ِئۡسَ مَثَلُ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 28, 7, 553, 486, 221, 'false'
  );
  
  -- Ayah 6 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5183,
    'قُلۡ یَـٰۤأَیُّهَا ٱلَّذِینَ هَادُوۤا۟ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِیَاۤءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلۡمَوۡتَ إِن كُنتُمۡ صَـٰدِقِینَ',
    'قل يا ايها الذين هادوا ان زعمتم انكم اولياء لله من دون الناس فتمنوا الموت ان كنتم صادقين',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ هَاد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ز</rule>َعَمۡتُمۡ أَ<rule class=ghunnah>نّ</rule>َكُمۡ أَوۡلِي<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ لِلَّهِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ فَتَمَ<rule class=ghunnah>نّ</rule>َوُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 28, 7, 553, 486, 221, 'false'
  );
  
  -- Ayah 7 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5184,
    'وَلَا یَتَمَنَّوۡنَهُۥۤ أَبَدَۢا بِمَا قَدَّمَتۡ أَیۡدِیهِمۡۚ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ',
    'ولا يتمنونه ابدا بما قدمت ايديهم والله عليم بالظالمين',
    'وَلَا يَتَمَ<rule class=ghunnah>نّ</rule>َوۡنَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَبَد<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِمَا قَدَّمَتۡ أَيۡدِيهِمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 28, 7, 553, 486, 221, 'false'
  );
  
  -- Ayah 8 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5185,
    'قُلۡ إِنَّ ٱلۡمَوۡتَ ٱلَّذِی تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَـٰقِیكُمۡۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ',
    'قل ان الموت الذي تفرون منه فانه ملاقيكم ثم تردون الى عالم الغيب والشهادة فينبئكم بما كنتم تعملون',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ <rule class=ham_wasl>ٱ</rule>لَّذِى تَفِرُّونَ مِنۡهُ فَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> مُلَ<rule class=madda_normal>ـٰ</rule>قِيكُمۡ‌ۖ ثُ<rule class=ghunnah>مّ</rule>َ تُرَدُّونَ إِلَىٰ عَ<rule class=madda_normal>ـٰ</rule>لِمِ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ فَيُنَبِّئُك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 28, 7, 553, 486, 221, 'false'
  );
  
  -- Ayah 9 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5186,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نُودِیَ لِلصَّلَوٰةِ مِن یَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡا۟ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُوا۟ ٱلۡبَیۡعَۚ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ',
    'يا ايها الذين امنوا اذا نودي للصلاة من يوم الجمعة فاسعوا الى ذكر الله وذروا البيع ذلكم خير لكم ان كنتم تعلمون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِذَا نُودِىَ لِلصَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمِ <rule class=ham_wasl>ٱ</rule>لۡجُمُعَةِ فَ<rule class=ham_wasl>ٱ</rule>سۡعَوۡ<rule class=slnt>اۡ</rule> إِلَىٰ ذِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَذَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡبَيۡعَ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ خَيۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 28, 7, 554, 487, 221, 'false'
  );
  
  -- Ayah 10 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5187,
    'فَإِذَا قُضِیَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِی ٱلۡأَرۡضِ وَٱبۡتَغُوا۟ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُوا۟ ٱللَّهَ كَثِیرࣰا لَّعَلَّكُمۡ تُفۡلِحُونَ',
    'فاذا قضيت الصلاة فانتشروا في الارض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون',
    'فَإِذَا قُضِيَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةُ فَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َشِرُو<rule class=slnt>اۡ</rule> فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ كَثِي<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّعَلَّكُمۡ تُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٠',
    10, 28, 7, 554, 487, 221, 'false'
  );
  
  -- Ayah 11 Surah Al-Jumua
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    62,
    5188,
    'وَإِذَا رَأَوۡا۟ تِجَـٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوۤا۟ إِلَیۡهَا وَتَرَكُوكَ قَاۤىِٕمࣰاۚ قُلۡ مَا عِندَ ٱللَّهِ خَیۡرࣱ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَـٰرَةِۚ وَٱللَّهُ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ',
    'واذا راوا تجارة او لهوا انفضوا اليها وتركوك قائما قل ما عند الله خير من اللهو ومن التجارة والله خير الرازقين',
    'وَإِذَا رَأَوۡ<rule class=slnt>اۡ</rule> تِجَ<rule class=madda_normal>ـٰ</rule>رَةً أَوۡ لَهۡوًا <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>َضّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَيۡهَا وَتَرَكُوكَ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=ikhafa>مًا‌ۚ</rule> <rule class=ikhafa>ق</rule>ُلۡ مَا عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّهۡوِ وَمِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تِّجَ<rule class=madda_normal>ـٰ</rule>رَةِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَيۡرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رّ<rule class=madda_normal>ٰ</rule>زِق<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 28, 7, 554, 487, 221, 'false'
  );
  

-- Surah Al-Munaafiqoon
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (63, 'سُورَةُ المُنَافِقُونَ', 'Al-Munaafiqoon', 'The Hypocrites', 'Medinan', 11);

  -- Ayah 1 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5189,
    'إِذَا جَاۤءَكَ ٱلۡمُنَـٰفِقُونَ قَالُوا۟ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ یَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ یَشۡهَدُ إِنَّ ٱلۡمُنَـٰفِقِینَ لَكَـٰذِبُونَ',
    'اذا جاءك المنافقون قالوا نشهد انك لرسول الله والله يعلم انك لرسوله والله يشهد ان المنافقين لكاذبون',
    'إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَكَ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقُونَ قَالُو<rule class=slnt>اۡ</rule> نَشۡهَدُ إِ<rule class=ghunnah>نّ</rule>َكَ لَرَسُولُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَعۡلَمُ إِ<rule class=ghunnah>نّ</rule>َكَ لَرَسُولُهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يَشۡهَدُ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ لَكَ<rule class=madda_normal>ـٰ</rule>ذِب<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 28, 7, 554, 488, 221, 'false'
  );
  
  -- Ayah 2 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5190,
    'ٱتَّخَذُوۤا۟ أَیۡمَـٰنَهُمۡ جُنَّةࣰ فَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِۚ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ',
    'اتخذوا ايمانهم جنة فصدوا عن سبيل الله انهم ساء ما كانوا يعملون',
    'ٱتَّخَذ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَيۡمَ<rule class=madda_normal>ـٰ</rule>نَهُمۡ جُ<rule class=ghunnah>نّ</rule>َ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َصَدُّو<rule class=slnt>اۡ</rule> عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُمۡ س<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ مَا كَانُو<rule class=slnt>اۡ</rule> يَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 28, 7, 554, 488, 221, 'false'
  );
  
  -- Ayah 3 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5191,
    'ذَ ٰ⁠لِكَ بِأَنَّهُمۡ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَفۡقَهُونَ',
    'ذلك بانهم امنوا ثم كفروا فطبع على قلوبهم فهم لا يفقهون',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُمۡ ءَامَنُو<rule class=slnt>اۡ</rule> ثُ<rule class=ghunnah>مّ</rule>َ كَفَرُو<rule class=slnt>اۡ</rule> فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَفۡقَه<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 28, 7, 554, 488, 221, 'false'
  );
  
  -- Ayah 4 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5192,
    '۞ وَإِذَا رَأَیۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن یَقُولُوا۟ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبࣱ مُّسَنَّدَةࣱۖ یَحۡسَبُونَ كُلَّ صَیۡحَةٍ عَلَیۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَـٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ یُؤۡفَكُونَ',
    'واذا رايتهم تعجبك اجسامهم وان يقولوا تسمع لقولهم كانهم خشب مسندة يحسبون كل صيحة عليهم هم العدو فاحذرهم قاتلهم الله انى يؤفكون',
    '۞وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَ<rule class=qalaqah>جۡ</rule>سَامُهُمۡ‌ۖ وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َقُولُو<rule class=slnt>اۡ</rule> تَسۡمَعۡ لِقَوۡلِهِمۡ‌ۖ كَأَ<rule class=ghunnah>نّ</rule>َهُمۡ خُشُ<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَ<rule class=ghunnah>نّ</rule>َدَ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>ي</rule>َحۡسَبُونَ كُلَّ صَيۡحَةٍ عَلَيۡهِمۡ‌ۚ هُمُ <rule class=ham_wasl>ٱ</rule>لۡعَدُوُّ فَ<rule class=ham_wasl>ٱ</rule>حۡذَرۡهُمۡ‌ۚ قَ<rule class=madda_normal>ـٰ</rule>تَلَهُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۖ أَ<rule class=ghunnah>نّ</rule>َىٰ يُؤۡفَك<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 28, 7, 554, 488, 222, 'false'
  );
  
  -- Ayah 5 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5193,
    'وَإِذَا قِیلَ لَهُمۡ تَعَالَوۡا۟ یَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡا۟ رُءُوسَهُمۡ وَرَأَیۡتَهُمۡ یَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ',
    'واذا قيل لهم تعالوا يستغفر لكم رسول الله لووا رءوسهم ورايتهم يصدون وهم مستكبرون',
    'وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡ<rule class=slnt>اۡ</rule> يَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ <rule class=ham_wasl>ٱ</rule>للَّهِ لَوَّوۡ<rule class=slnt>اۡ</rule> رُءُوسَهُمۡ وَرَأَيۡتَهُمۡ يَصُدُّونَ وَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّسۡتَكۡبِر<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 28, 7, 555, 488, 222, 'false'
  );
  
  -- Ayah 6 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5194,
    'سَوَاۤءٌ عَلَیۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن یَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ',
    'سواء عليهم استغفرت لهم ام لم تستغفر لهم لن يغفر الله لهم ان الله لا يهدي القوم الفاسقين',
    'سَو<rule class=madda_obligatory_mottasel>َا</rule>ٓءٌ عَلَيۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َغۡفِرَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ لَا يَهۡدِى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=madda_normal>ـٰ</rule>سِق<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 28, 7, 555, 488, 222, 'false'
  );
  
  -- Ayah 7 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5195,
    'هُمُ ٱلَّذِینَ یَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ یَنفَضُّوا۟ۗ وَلِلَّهِ خَزَاۤىِٕنُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَلَـٰكِنَّ ٱلۡمُنَـٰفِقِینَ لَا یَفۡقَهُونَ',
    'هم الذين يقولون لا تنفقوا على من عند رسول الله حتى ينفضوا ولله خزائن السماوات والارض ولكن المنافقين لا يفقهون',
    'هُمُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَقُولُونَ لَا تُ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> عَلَىٰ مَنۡ عِ<rule class=ikhafa>ند</rule>َ رَسُولِ <rule class=ham_wasl>ٱ</rule>للَّهِ حَتَّىٰ يَ<rule class=ikhafa>نف</rule>َضُّو<rule class=slnt>اۡ‌ۗ</rule> وَلِلَّهِ خَز<rule class=madda_obligatory_mottasel>َا</rule>ٓئِنُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ لَا يَفۡقَه<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 28, 7, 555, 488, 222, 'false'
  );
  
  -- Ayah 8 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5196,
    'یَقُولُونَ لَىِٕن رَّجَعۡنَاۤ إِلَى ٱلۡمَدِینَةِ لَیُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِینَ وَلَـٰكِنَّ ٱلۡمُنَـٰفِقِینَ لَا یَعۡلَمُونَ',
    'يقولون لئن رجعنا الى المدينة ليخرجن الاعز منها الاذل ولله العزة ولرسوله وللمؤمنين ولكن المنافقين لا يعلمون',
    'يَقُولُونَ لَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّجَعۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>لۡمَدِينَةِ لَيُخۡرِجَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَعَزُّ مِنۡهَا <rule class=ham_wasl>ٱ</rule>لۡأَذَلَّ‌ۚ وَلِلَّهِ <rule class=ham_wasl>ٱ</rule>لۡعِزَّةُ وَلِرَسُولِه<rule class=madda_normal>ِۦ</rule> وَلِلۡمُؤۡمِنِينَ وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٨',
    8, 28, 7, 555, 488, 222, 'false'
  );
  
  -- Ayah 9 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5197,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُلۡهِكُمۡ أَمۡوَ ٰ⁠لُكُمۡ وَلَاۤ أَوۡلَـٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن یَفۡعَلۡ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ',
    'يا ايها الذين امنوا لا تلهكم اموالكم ولا اولادكم عن ذكر الله ومن يفعل ذلك فاولئك هم الخاسرون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> لَا تُلۡهِكُمۡ أَمۡو<rule class=madda_normal>ٰ</rule>لُكُمۡ وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَوۡلَ<rule class=madda_normal>ـٰ</rule>دُكُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َفۡعَلۡ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>سِر<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 28, 7, 555, 489, 222, 'false'
  );
  
  -- Ayah 10 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5198,
    'وَأَنفِقُوا۟ مِن مَّا رَزَقۡنَـٰكُم مِّن قَبۡلِ أَن یَأۡتِیَ أَحَدَكُمُ ٱلۡمَوۡتُ فَیَقُولَ رَبِّ لَوۡلَاۤ أَخَّرۡتَنِیۤ إِلَىٰۤ أَجَلࣲ قَرِیبࣲ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِینَ',
    'وانفقوا من ما رزقناكم من قبل ان ياتي احدكم الموت فيقول رب لولا اخرتني الى اجل قريب فاصدق واكن من الصالحين',
    'وَأَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّا رَزَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِىَ أَحَدَكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَخَّرۡتَن<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ق</rule>َرِي<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ف</rule>َأَصَّدَّقَ وَأَك<rule class=idgham_ghunnah>ُن</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 28, 7, 555, 489, 222, 'false'
  );
  
  -- Ayah 11 Surah Al-Munaafiqoon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    63,
    5199,
    'وَلَن یُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَاۤءَ أَجَلُهَاۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ',
    'ولن يؤخر الله نفسا اذا جاء اجلها والله خبير بما تعملون',
    'وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤَخِّرَ <rule class=ham_wasl>ٱ</rule>للَّهُ نَفۡسًا إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ أَجَلُهَا‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ خَبِي<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِمَا تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ١١',
    11, 28, 7, 555, 489, 222, 'false'
  );
  

-- Surah At-Taghaabun
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (64, 'سُورَةُ التَّغَابُنِ', 'At-Taghaabun', 'Mutual Disillusion', 'Medinan', 18);

  -- Ayah 1 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5200,
    'یُسَبِّحُ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'يسبح لله ما في السماوات وما في الارض له الملك وله الحمد وهو على كل شيء قدير',
    'يُسَبِّحُ لِلَّهِ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَمَا فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۖ لَهُ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكُ وَلَهُ <rule class=ham_wasl>ٱ</rule>لۡحَمۡدُ‌ۖ وَهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١',
    1, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 2 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5201,
    'هُوَ ٱلَّذِی خَلَقَكُمۡ فَمِنكُمۡ كَافِرࣱ وَمِنكُم مُّؤۡمِنࣱۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرٌ',
    'هو الذي خلقكم فمنكم كافر ومنكم مؤمن والله بما تعملون بصير',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَكُمۡ فَمِ<rule class=ikhafa>نك</rule>ُمۡ كَافِ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َمِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡمِ<rule class=idgham_ghunnah>نٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ بَص<rule class=madda_permissible>ِي</rule>رٌ ٢',
    2, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 3 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5202,
    'خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَیۡهِ ٱلۡمَصِیرُ',
    'خلق السماوات والارض بالحق وصوركم فاحسن صوركم واليه المصير',
    'خَلَقَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ‌ۖ وَإِلَيۡهِ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٣',
    3, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 4 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5203,
    'یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَیَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'يعلم ما في السماوات والارض ويعلم ما تسرون وما تعلنون والله عليم بذات الصدور',
    'يَعۡلَمُ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَيَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ٤',
    4, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 5 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5204,
    'أَلَمۡ یَأۡتِكُمۡ نَبَؤُا۟ ٱلَّذِینَ كَفَرُوا۟ مِن قَبۡلُ فَذَاقُوا۟ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ',
    'الم ياتكم نبا الذين كفروا من قبل فذاقوا وبال امرهم ولهم عذاب اليم',
    'أَلَمۡ يَأۡتِكُمۡ نَبَؤُ<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لُ فَذَاقُو<rule class=slnt>اۡ</rule> وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ٥',
    5, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 6 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5205,
    'ذَ ٰ⁠لِكَ بِأَنَّهُۥ كَانَت تَّأۡتِیهِمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَقَالُوۤا۟ أَبَشَرࣱ یَهۡدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِیٌّ حَمِیدࣱ',
    'ذلك بانه كانت تاتيهم رسلهم بالبينات فقالوا ابشر يهدوننا فكفروا وتولوا واستغنى الله والله غني حميد',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ بِأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَت تَّأۡتِيهِمۡ رُسُلُه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡبَيِّنَ<rule class=madda_normal>ـٰ</rule>تِ فَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَبَشَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>ي</rule>َهۡدُونَنَا فَكَفَرُو<rule class=slnt>اۡ</rule> وَتَوَلَّو<rule class=slnt>اۡ‌ۚ</rule> وَّ<rule class=ham_wasl>ٱ</rule>سۡتَغۡنَى <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَنِىٌّ حَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٦',
    6, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 7 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5206,
    'زَعَمَ ٱلَّذِینَ كَفَرُوۤا۟ أَن لَّن یُبۡعَثُوا۟ۚ قُلۡ بَلَىٰ وَرَبِّی لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ',
    'زعم الذين كفروا ان لن يبعثوا قل بلى وربي لتبعثن ثم لتنبؤن بما عملتم وذلك على الله يسير',
    'زَعَمَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>بۡ</rule>عَثُو<rule class=slnt>اۡ‌ۚ</rule> قُلۡ بَلَىٰ وَرَبِّى لَتُ<rule class=qalaqah>بۡ</rule>عَثُ<rule class=ghunnah>نّ</rule>َ ثُ<rule class=ghunnah>مّ</rule>َ لَتُنَبَّؤُ<rule class=ghunnah>نّ</rule>َ بِمَا عَمِلۡتُمۡ‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ يَس<rule class=madda_permissible>ِي</rule>رٌ ٧',
    7, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 8 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5207,
    'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِیۤ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ',
    'فامنوا بالله ورسوله والنور الذي انزلنا والله بما تعملون خبير',
    'فَـَٔـامِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَرَسُولِه<rule class=madda_normal>ِۦ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَا‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِمَا تَعۡمَلُونَ خَب<rule class=madda_permissible>ِي</rule>رٌ ٨',
    8, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 9 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5208,
    'یَوۡمَ یَجۡمَعُكُمۡ لِیَوۡمِ ٱلۡجَمۡعِۖ ذَ ٰ⁠لِكَ یَوۡمُ ٱلتَّغَابُنِۗ وَمَن یُؤۡمِنۢ بِٱللَّهِ وَیَعۡمَلۡ صَـٰلِحࣰا یُكَفِّرۡ عَنۡهُ سَیِّـَٔاتِهِۦ وَیُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ',
    'يوم يجمعكم ليوم الجمع ذلك يوم التغابن ومن يؤمن بالله ويعمل صالحا يكفر عنه سيئاته ويدخله جنات تجري من تحتها الانهار خالدين فيها ابدا ذلك الفوز العظيم',
    'يَوۡمَ يَ<rule class=qalaqah>جۡ</rule>مَعُكُمۡ لِيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡجَمۡعِ‌ۖ ذ<rule class=madda_normal>ٰ</rule>لِكَ يَوۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّغَابُنِ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَيَعۡمَلۡ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>ي</rule>ُكَفِّرۡ عَنۡهُ سَيِّـَٔـاتِه<rule class=madda_normal>ِۦ</rule> وَيُ<rule class=qalaqah>دۡ</rule>خِلۡهُ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=ikhafa>دًا‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مُ ٩',
    9, 28, 7, 556, 490, 222, 'false'
  );
  
  -- Ayah 10 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5209,
    'وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِ خَـٰلِدِینَ فِیهَاۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'والذين كفروا وكذبوا باياتنا اولئك اصحاب النار خالدين فيها وبئس المصير',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَكَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِن<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيهَا‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ١٠',
    10, 28, 7, 557, 490, 222, 'false'
  );
  
  -- Ayah 11 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5210,
    'مَاۤ أَصَابَ مِن مُّصِیبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن یُؤۡمِنۢ بِٱللَّهِ یَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ',
    'ما اصاب من مصيبة الا باذن الله ومن يؤمن بالله يهد قلبه والله بكل شيء عليم',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> أَصَابَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ُّصِيبَةٍ إِلَّا بِإِذۡنِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ يَهۡدِ قَلۡبَهُ<rule class=madda_normal>ۥ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ بِكُلِّ شَىۡءٍ عَل<rule class=madda_permissible>ِي</rule>مٌ ١١',
    11, 28, 7, 557, 491, 222, 'false'
  );
  
  -- Ayah 12 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5211,
    'وَأَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَۚ فَإِن تَوَلَّیۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ',
    'واطيعوا الله واطيعوا الرسول فان توليتم فانما على رسولنا البلاغ المبين',
    'وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَأَطِيعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ‌ۚ فَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َوَلَّيۡتُمۡ فَإِ<rule class=ghunnah>نّ</rule>َمَا عَلَىٰ رَسُولِنَا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=madda_normal>ـٰ</rule>غُ <rule class=ham_wasl>ٱ</rule>لۡمُب<rule class=madda_permissible>ِي</rule>نُ ١٢',
    12, 28, 7, 557, 491, 222, 'false'
  );
  
  -- Ayah 13 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5212,
    'ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ',
    'الله لا اله الا هو وعلى الله فليتوكل المؤمنون',
    'ٱللَّهُ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ‌ۚ وَعَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَلۡيَتَوَكَّلِ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ١٣',
    13, 28, 7, 557, 491, 222, 'false'
  );
  
  -- Ayah 14 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5213,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ مِنۡ أَزۡوَ ٰ⁠جِكُمۡ وَأَوۡلَـٰدِكُمۡ عَدُوࣰّا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُوا۟ وَتَصۡفَحُوا۟ وَتَغۡفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ',
    'يا ايها الذين امنوا ان من ازواجكم واولادكم عدوا لكم فاحذروهم وان تعفوا وتصفحوا وتغفروا فان الله غفور رحيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَن<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ مِنۡ أَزۡو<rule class=madda_normal>ٰ</rule>جِكُمۡ وَأَوۡلَ<rule class=madda_normal>ـٰ</rule>دِكُمۡ عَدُو<rule class=idgham_wo_ghunnah>ًّا</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ فَ<rule class=ham_wasl>ٱ</rule>حۡذَرُوهُمۡ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعۡفُو<rule class=slnt>اۡ</rule> وَتَصۡفَحُو<rule class=slnt>اۡ</rule> وَتَغۡفِرُو<rule class=slnt>اۡ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١٤',
    14, 28, 7, 557, 491, 222, 'false'
  );
  
  -- Ayah 15 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5214,
    'إِنَّمَاۤ أَمۡوَ ٰ⁠لُكُمۡ وَأَوۡلَـٰدُكُمۡ فِتۡنَةࣱۚ وَٱللَّهُ عِندَهُۥۤ أَجۡرٌ عَظِیمࣱ',
    'انما اموالكم واولادكم فتنة والله عنده اجر عظيم',
    'إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡو<rule class=madda_normal>ٰ</rule>لُكُمۡ وَأَوۡلَ<rule class=madda_normal>ـٰ</rule>دُكُمۡ فِتۡنَ<rule class=idgham_ghunnah>ةٌ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>للَّهُ عِ<rule class=ikhafa>ند</rule>َهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=qalaqah>جۡ</rule>رٌ عَظ<rule class=madda_permissible>ِي</rule>مٌ ١٥',
    15, 28, 7, 557, 491, 222, 'false'
  );
  
  -- Ayah 16 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5215,
    'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُوا۟ وَأَطِیعُوا۟ وَأَنفِقُوا۟ خَیۡرࣰا لِّأَنفُسِكُمۡۗ وَمَن یُوقَ شُحَّ نَفۡسِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ',
    'فاتقوا الله ما استطعتم واسمعوا واطيعوا وانفقوا خيرا لانفسكم ومن يوق شح نفسه فاولئك هم المفلحون',
    'فَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مَا <rule class=ham_wasl>ٱ</rule>سۡتَطَعۡتُمۡ وَ<rule class=ham_wasl>ٱ</rule>سۡمَعُو<rule class=slnt>اۡ</rule> وَأَطِيعُو<rule class=slnt>اۡ</rule> وَأَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> خَيۡ<rule class=idgham_wo_ghunnah>رًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأَ<rule class=ikhafa>نف</rule>ُسِكُمۡ‌ۗ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُوقَ شُحَّ نَفۡسِه<rule class=madda_normal>ِۦ</rule> فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡمُفۡلِح<rule class=madda_permissible>ُو</rule>نَ ١٦',
    16, 28, 7, 557, 491, 222, 'false'
  );
  
  -- Ayah 17 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5216,
    'إِن تُقۡرِضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰا یُضَـٰعِفۡهُ لَكُمۡ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِیمٌ',
    'ان تقرضوا الله قرضا حسنا يضاعفه لكم ويغفر لكم والله شكور حليم',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُ<rule class=qalaqah>قۡ</rule>رِضُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ قَرۡضًا حَسَ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>ي</rule>ُضَ<rule class=madda_normal>ـٰ</rule>عِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ شَكُورٌ حَل<rule class=madda_permissible>ِي</rule>مٌ ١٧',
    17, 28, 7, 557, 491, 222, 'false'
  );
  
  -- Ayah 18 Surah At-Taghaabun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    64,
    5217,
    'عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡعَزِیزُ ٱلۡحَكِیمُ',
    'عالم الغيب والشهادة العزيز الحكيم',
    'عَ<rule class=madda_normal>ـٰ</rule>لِمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ١٨',
    18, 28, 7, 557, 491, 222, 'false'
  );
  

-- Surah At-Talaaq
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (65, 'سُورَةُ الطَّلَاقِ', 'At-Talaaq', 'Divorce', 'Medinan', 12);

  -- Ayah 1 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5218,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَاۤءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُوا۟ ٱلۡعِدَّةَۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُیُوتِهِنَّ وَلَا یَخۡرُجۡنَ إِلَّاۤ أَن یَأۡتِینَ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن یَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِی لَعَلَّ ٱللَّهَ یُحۡدِثُ بَعۡدَ ذَ ٰ⁠لِكَ أَمۡرࣰا',
    'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العدة واتقوا الله ربكم لا تخرجوهن من بيوتهن ولا يخرجن الا ان ياتين بفاحشة مبينة وتلك حدود الله ومن يتعد حدود الله فقد ظلم نفسه لا تدري لعل الله يحدث بعد ذلك امرا',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ إِذَا طَلَّ<rule class=qalaqah>قۡ</rule>تُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ِس<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَطَلِّقُوهُ<rule class=ghunnah>نّ</rule>َ لِعِدَّتِهِ<rule class=ghunnah>نّ</rule>َ وَأَحۡصُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡعِدَّةَ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ رَبَّكُمۡ‌ۖ لَا تُخۡرِجُوهُ<rule class=ghunnah>نّ</rule>َ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ُيُوتِهِ<rule class=ghunnah>نّ</rule>َ وَلَا يَخۡرُ<rule class=qalaqah>جۡ</rule>نَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِينَ بِفَ<rule class=madda_normal>ـٰ</rule>حِشَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّبَيِّنَ<rule class=idgham_ghunnah>ةٍ‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َتِلۡكَ حُدُودُ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَعَدَّ حُدُودَ <rule class=ham_wasl>ٱ</rule>للَّهِ فَقَ<rule class=qalaqah>دۡ</rule> ظَلَمَ نَفۡسَهُ<rule class=madda_normal>ۥ</rule>‌ۚ لَا تَ<rule class=qalaqah>دۡ</rule>رِى لَعَلَّ <rule class=ham_wasl>ٱ</rule>للَّهَ يُحۡدِثُ بَعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ أَمۡرًا ١',
    1, 28, 7, 558, 492, 223, 'false'
  );
  
  -- Ayah 2 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5219,
    'فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفࣲ وَأَشۡهِدُوا۟ ذَوَیۡ عَدۡلࣲ مِّنكُمۡ وَأَقِیمُوا۟ ٱلشَّهَـٰدَةَ لِلَّهِۚ ذَ ٰ⁠لِكُمۡ یُوعَظُ بِهِۦ مَن كَانَ یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ وَمَن یَتَّقِ ٱللَّهَ یَجۡعَل لَّهُۥ مَخۡرَجࣰا',
    'فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروف واشهدوا ذوي عدل منكم واقيموا الشهادة لله ذلكم يوعظ به من كان يؤمن بالله واليوم الاخر ومن يتق الله يجعل له مخرجا',
    'فَإِذَا بَلَغۡنَ أَجَلَهُ<rule class=ghunnah>نّ</rule>َ فَأَمۡسِكُوهُ<rule class=ghunnah>نّ</rule>َ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُ<rule class=ghunnah>نّ</rule>َ بِمَعۡرُو<rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَشۡهِدُو<rule class=slnt>اۡ</rule> ذَوَىۡ عَ<rule class=qalaqah>دۡ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُمۡ وَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّهَ<rule class=madda_normal>ـٰ</rule>دَةَ لِلَّهِ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكُمۡ يُوعَظُ بِه<rule class=madda_normal>ِۦ</rule> مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ يُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡأَخِرِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّقِ <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>جۡ</rule>عَل لَّهُ<rule class=madda_normal>ۥ</rule> مَخۡرَجًا ٢',
    2, 28, 7, 558, 492, 223, 'false'
  );
  
  -- Ayah 3 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5220,
    'وَیَرۡزُقۡهُ مِنۡ حَیۡثُ لَا یَحۡتَسِبُۚ وَمَن یَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥۤۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَیۡءࣲ قَدۡرࣰا',
    'ويرزقه من حيث لا يحتسب ومن يتوكل على الله فهو حسبه ان الله بالغ امره قد جعل الله لكل شيء قدرا',
    'وَيَرۡزُ<rule class=qalaqah>قۡ</rule>هُ مِنۡ حَيۡثُ لَا يَحۡتَسِبُ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَوَكَّلۡ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَهُوَ حَسۡبُهُ<rule class=madda_obligatory_monfasel>ۥٓ‌ۚ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ بَ<rule class=madda_normal>ـٰ</rule>لِغُ أَمۡرِه<rule class=madda_normal>ِۦ</rule>‌ۚ قَ<rule class=qalaqah>دۡ</rule> جَعَلَ <rule class=ham_wasl>ٱ</rule>للَّهُ لِكُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule>رًا ٣',
    3, 28, 7, 558, 492, 223, 'false'
  );
  
  -- Ayah 4 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5221,
    'وَٱلَّـٰۤـِٔی یَىِٕسۡنَ مِنَ ٱلۡمَحِیضِ مِن نِّسَاۤىِٕكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَـٰثَةُ أَشۡهُرࣲ وَٱلَّـٰۤـِٔی لَمۡ یَحِضۡنَۚ وَأُو۟لَـٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن یَضَعۡنَ حَمۡلَهُنَّۚ وَمَن یَتَّقِ ٱللَّهَ یَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ یُسۡرࣰا',
    'واللائي يئسن من المحيض من نسائكم ان ارتبتم فعدتهن ثلاثة اشهر واللائي لم يحضن واولات الاحمال اجلهن ان يضعن حملهن ومن يتق الله يجعل له من امره يسرا',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_obligatory_mottasel>ــٰٓ</rule>ــِٔى يَئِسۡنَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡمَحِيضِ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ِّس<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكُمۡ إِنِ <rule class=ham_wasl>ٱ</rule>رۡتَ<rule class=qalaqah>بۡ</rule>تُمۡ فَعِدَّتُهُ<rule class=ghunnah>نّ</rule>َ ثَلَ<rule class=madda_normal>ـٰ</rule>ثَةُ أَشۡهُ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>لَّ<rule class=madda_obligatory_mottasel>ــٰٓ</rule>ــِٔى لَمۡ يَحِضۡنَ‌ۚ وَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_normal>ـٰ</rule>تُ <rule class=ham_wasl>ٱ</rule>لۡأَحۡمَالِ أَجَلُهُ<rule class=ghunnah>نّ</rule>َ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َضَعۡنَ حَمۡلَهُ<rule class=ghunnah>نّ</rule>َ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّقِ <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=qalaqah>جۡ</rule>عَل لَّهُ<rule class=madda_normal>ۥ</rule> مِنۡ أَمۡرِه<rule class=madda_normal>ِۦ</rule> يُسۡرًا ٤',
    4, 28, 7, 558, 492, 223, 'false'
  );
  
  -- Ayah 5 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5222,
    'ذَ ٰ⁠لِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥۤ إِلَیۡكُمۡۚ وَمَن یَتَّقِ ٱللَّهَ یُكَفِّرۡ عَنۡهُ سَیِّـَٔاتِهِۦ وَیُعۡظِمۡ لَهُۥۤ أَجۡرًا',
    'ذلك امر الله انزله اليكم ومن يتق الله يكفر عنه سيئاته ويعظم له اجرا',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ أَمۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ أَ<rule class=ikhafa>نز</rule>َلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَيۡكُمۡ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َتَّقِ <rule class=ham_wasl>ٱ</rule>للَّهَ يُكَفِّرۡ عَنۡهُ سَيِّـَٔـاتِه<rule class=madda_normal>ِۦ</rule> وَيُعۡظِمۡ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَ<rule class=qalaqah>جۡ</rule>رًا ٥',
    5, 28, 7, 558, 492, 223, 'false'
  );
  
  -- Ayah 6 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5223,
    'أَسۡكِنُوهُنَّ مِنۡ حَیۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَاۤرُّوهُنَّ لِتُضَیِّقُوا۟ عَلَیۡهِنَّۚ وَإِن كُنَّ أُو۟لَـٰتِ حَمۡلࣲ فَأَنفِقُوا۟ عَلَیۡهِنَّ حَتَّىٰ یَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُوا۟ بَیۡنَكُم بِمَعۡرُوفࣲۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥۤ أُخۡرَىٰ',
    'اسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا عليهن وان كن اولات حمل فانفقوا عليهن حتى يضعن حملهن فان ارضعن لكم فاتوهن اجورهن واتمروا بينكم بمعروف وان تعاسرتم فسترضع له اخرى',
    'أَسۡكِنُوهُ<rule class=ghunnah>نّ</rule>َ مِنۡ حَيۡثُ سَكَ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>و</rule>ُ<rule class=qalaqah>جۡ</rule>دِكُمۡ وَلَا تُض<rule class=madda_necessary>َا</rule>ٓرُّوهُ<rule class=ghunnah>نّ</rule>َ لِتُضَيِّقُو<rule class=slnt>اۡ</rule> عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ‌ۚ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ghunnah>نّ</rule>َ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِ حَمۡ<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َأَ<rule class=ikhafa>نف</rule>ِقُو<rule class=slnt>اۡ</rule> عَلَيۡهِ<rule class=ghunnah>نّ</rule>َ حَتَّىٰ يَضَعۡنَ حَمۡلَهُ<rule class=ghunnah>نّ</rule>َ‌ۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔـاتُوهُ<rule class=ghunnah>نّ</rule>َ أُجُورَهُ<rule class=ghunnah>نّ</rule>َ‌ۖ وَأۡتَمِرُو<rule class=slnt>اۡ</rule> بَيۡنَك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَعۡرُو<rule class=idgham_ghunnah>فٍ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أُخۡرَىٰ ٦',
    6, 28, 7, 559, 492, 223, 'false'
  );
  
  -- Ayah 7 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5224,
    'لِیُنفِقۡ ذُو سَعَةࣲ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَیۡهِ رِزۡقُهُۥ فَلۡیُنفِقۡ مِمَّاۤ ءَاتَىٰهُ ٱللَّهُۚ لَا یُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَاۤ ءَاتَىٰهَاۚ سَیَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرࣲ یُسۡرࣰا',
    'لينفق ذو سعة من سعته ومن قدر عليه رزقه فلينفق مما اتاه الله لا يكلف الله نفسا الا ما اتاها سيجعل الله بعد عسر يسرا',
    'لِيُ<rule class=ikhafa>نف</rule>ِ<rule class=qalaqah>قۡ</rule> ذُو سَعَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َعَتِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُدِرَ عَلَيۡهِ رِزۡقُهُ<rule class=madda_normal>ۥ</rule> فَلۡيُ<rule class=ikhafa>نف</rule>ِ<rule class=qalaqah>قۡ</rule> مِ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ لَا يُكَلِّفُ <rule class=ham_wasl>ٱ</rule>للَّهُ نَفۡسًا إِلَّا م<rule class=madda_obligatory_monfasel>َآ</rule> ءَاتَ<rule class=madda_normal>ـٰ</rule>هَا‌ۚ سَيَ<rule class=qalaqah>جۡ</rule>عَلُ <rule class=ham_wasl>ٱ</rule>للَّهُ بَعۡدَ عُسۡ<rule class=idgham_ghunnah>رٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُسۡرًا ٧',
    7, 28, 7, 559, 492, 223, 'false'
  );
  
  -- Ayah 8 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5225,
    'وَكَأَیِّن مِّن قَرۡیَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَـٰهَا حِسَابࣰا شَدِیدࣰا وَعَذَّبۡنَـٰهَا عَذَابࣰا نُّكۡرࣰا',
    'وكاين من قرية عتت عن امر ربها ورسله فحاسبناها حسابا شديدا وعذبناها عذابا نكرا',
    'وَكَأَيّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َرۡيَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِه<rule class=madda_normal>ِۦ</rule> فَحَاسَ<rule class=qalaqah>بۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هَا حِسَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َعَذَّ<rule class=qalaqah>بۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هَا عَذَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>ن</rule>ُّكۡرًا ٨',
    8, 28, 7, 559, 493, 223, 'false'
  );
  
  -- Ayah 9 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5226,
    'فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَـٰقِبَةُ أَمۡرِهَا خُسۡرًا',
    'فذاقت وبال امرها وكان عاقبة امرها خسرا',
    'فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَ<rule class=madda_normal>ـٰ</rule>قِبَةُ أَمۡرِهَا خُسۡرًا ٩',
    9, 28, 7, 559, 493, 223, 'false'
  );
  
  -- Ayah 10 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5227,
    'أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰا شَدِیدࣰاۖ فَٱتَّقُوا۟ ٱللَّهَ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ ٱلَّذِینَ ءَامَنُوا۟ۚ قَدۡ أَنزَلَ ٱللَّهُ إِلَیۡكُمۡ ذِكۡرࣰا',
    'اعد الله لهم عذابا شديدا فاتقوا الله يا اولي الالباب الذين امنوا قد انزل الله اليكم ذكرا',
    'أَعَدَّ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُمۡ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=ikhafa>دًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>تَّقُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule>لۡأَلۡبَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ‌ۚ</rule> قَ<rule class=qalaqah>دۡ</rule> أَ<rule class=ikhafa>نز</rule>َلَ <rule class=ham_wasl>ٱ</rule>للَّهُ إِلَيۡكُمۡ ذِكۡرًا ١٠',
    10, 28, 7, 559, 493, 223, 'false'
  );
  
  -- Ayah 11 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5228,
    'رَّسُولࣰا یَتۡلُوا۟ عَلَیۡكُمۡ ءَایَـٰتِ ٱللَّهِ مُبَیِّنَـٰتࣲ لِّیُخۡرِجَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَمَن یُؤۡمِنۢ بِٱللَّهِ وَیَعۡمَلۡ صَـٰلِحࣰا یُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا',
    'رسولا يتلو عليكم ايات الله مبينات ليخرج الذين امنوا وعملوا الصالحات من الظلمات الى النور ومن يؤمن بالله ويعمل صالحا يدخله جنات تجري من تحتها الانهار خالدين فيها ابدا قد احسن الله له رزقا',
    'رَّسُول<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>ي</rule>َتۡلُو<rule class=slnt>اۡ</rule> عَلَيۡكُمۡ ءَايَ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule>للَّهِ مُبَيِّنَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_wo_ghunnah>تٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُخۡرِجَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظُّلُمَ<rule class=madda_normal>ـٰ</rule>تِ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُورِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>للَّهِ وَيَعۡمَلۡ صَ<rule class=madda_normal>ـٰ</rule>لِ<rule class=idgham_ghunnah>حًا</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>دۡ</rule>خِلۡهُ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=ikhafa>دًا‌ۖ</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> أَحۡسَنَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَهُ<rule class=madda_normal>ۥ</rule> رِزۡقًا ١١',
    11, 28, 7, 559, 493, 223, 'false'
  );
  
  -- Ayah 12 Surah At-Talaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    65,
    5229,
    'ٱللَّهُ ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ یَتَنَزَّلُ ٱلۡأَمۡرُ بَیۡنَهُنَّ لِتَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَیۡءٍ عِلۡمَۢا',
    'الله الذي خلق سبع سماوات ومن الارض مثلهن يتنزل الامر بينهن لتعلموا ان الله على كل شيء قدير وان الله قد احاط بكل شيء علما',
    'ٱللَّهُ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَقَ سَ<rule class=qalaqah>بۡ</rule>عَ سَمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َمِنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مِثۡلَهُ<rule class=ghunnah>نّ</rule>َ يَتَنَزَّلُ <rule class=ham_wasl>ٱ</rule>لۡأَمۡرُ بَيۡنَهُ<rule class=ghunnah>نّ</rule>َ لِتَعۡلَم<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َدِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ قَ<rule class=qalaqah>دۡ</rule> أَحَاطَ بِكُلِّ شَىۡءٍ عِلۡمَۢا ١٢',
    12, 28, 7, 559, 493, 223, 'false'
  );
  

-- Surah At-Tahrim
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (66, 'سُورَةُ التَّحۡرِيمِ', 'At-Tahrim', 'The Prohibition', 'Medinan', 12);

  -- Ayah 1 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5230,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ لِمَ تُحَرِّمُ مَاۤ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِی مَرۡضَاتَ أَزۡوَ ٰ⁠جِكَۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ',
    'يا ايها النبي لم تحرم ما احل الله لك تبتغي مرضات ازواجك والله غفور رحيم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ لِمَ تُحَرِّمُ م<rule class=madda_obligatory_monfasel>َآ</rule> أَحَلَّ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكَ‌ۖ تَ<rule class=qalaqah>بۡ</rule>تَغِى مَرۡضَاتَ أَزۡو<rule class=madda_normal>ٰ</rule>جِكَ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مٌ ١',
    1, 28, 7, 560, 494, 224, 'false'
  );
  
  -- Ayah 2 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5231,
    'قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَیۡمَـٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ',
    'قد فرض الله لكم تحلة ايمانكم والله مولاكم وهو العليم الحكيم',
    'قَ<rule class=qalaqah>دۡ</rule> فَرَضَ <rule class=ham_wasl>ٱ</rule>للَّهُ لَكُمۡ تَحِلَّةَ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نِكُمۡ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ مَوۡلَ<rule class=madda_normal>ـٰ</rule>كُمۡ‌ۖ وَهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَلِيمُ <rule class=ham_wasl>ٱ</rule>لۡحَك<rule class=madda_permissible>ِي</rule>مُ ٢',
    2, 28, 7, 560, 494, 224, 'false'
  );
  
  -- Ayah 3 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5232,
    'وَإِذۡ أَسَرَّ ٱلنَّبِیُّ إِلَىٰ بَعۡضِ أَزۡوَ ٰ⁠جِهِۦ حَدِیثࣰا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَیۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضࣲۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَـٰذَاۖ قَالَ نَبَّأَنِیَ ٱلۡعَلِیمُ ٱلۡخَبِیرُ',
    'واذ اسر النبي الى بعض ازواجه حديثا فلما نبات به واظهره الله عليه عرف بعضه واعرض عن بعض فلما نباها به قالت من انباك هذا قال نباني العليم الخبير',
    'وَإِذۡ أَسَرَّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ إِلَىٰ بَعۡضِ أَزۡو<rule class=madda_normal>ٰ</rule>جِه<rule class=madda_normal>ِۦ</rule> حَدِي<rule class=ikhafa>ثًا</rule> <rule class=ikhafa>ف</rule>َلَ<rule class=ghunnah>مّ</rule>َا نَبَّأَتۡ بِه<rule class=madda_normal>ِۦ</rule> وَأَظۡهَرَهُ <rule class=ham_wasl>ٱ</rule>للَّهُ عَلَيۡهِ عَرَّفَ بَعۡضَهُ<rule class=madda_normal>ۥ</rule> وَأَعۡرَضَ ع<rule class=iqlab>َنۢ</rule> <rule class=iqlab>ب</rule>َعۡ<rule class=ikhafa>ضٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َلَ<rule class=ghunnah>مّ</rule>َا نَبَّأَهَا بِه<rule class=madda_normal>ِۦ</rule> قَالَتۡ مَنۡ أَ<rule class=iqlab>نۢب</rule>َأَكَ هَ<rule class=madda_normal>ـٰ</rule>ذَا‌ۖ قَالَ نَبَّأَنِىَ <rule class=ham_wasl>ٱ</rule>لۡعَلِيمُ <rule class=ham_wasl>ٱ</rule>لۡخَب<rule class=madda_permissible>ِي</rule>رُ ٣',
    3, 28, 7, 560, 494, 224, 'false'
  );
  
  -- Ayah 4 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5233,
    'إِن تَتُوبَاۤ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَـٰهَرَا عَلَیۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِیلُ وَصَـٰلِحُ ٱلۡمُؤۡمِنِینَۖ وَٱلۡمَلَـٰۤىِٕكَةُ بَعۡدَ ذَ ٰ⁠لِكَ ظَهِیرٌ',
    'ان تتوبا الى الله فقد صغت قلوبكما وان تظاهرا عليه فان الله هو مولاه وجبريل وصالح المؤمنين والملائكة بعد ذلك ظهير',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َتُوب<rule class=madda_obligatory_monfasel>َآ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ فَقَ<rule class=qalaqah>دۡ</rule> صَغَتۡ قُلُوبُكُمَا‌ۖ وَإِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َظَ<rule class=madda_normal>ـٰ</rule>هَرَا عَلَيۡهِ فَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ هُوَ مَوۡلَ<rule class=madda_normal>ـٰ</rule>هُ وَجِ<rule class=qalaqah>بۡ</rule>رِيلُ وَصَ<rule class=madda_normal>ـٰ</rule>لِحُ <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ‌ۖ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ بَعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ ظَه<rule class=madda_permissible>ِي</rule>رٌ ٤',
    4, 28, 7, 560, 494, 224, 'false'
  );
  
  -- Ayah 5 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5234,
    'عَسَىٰ رَبُّهُۥۤ إِن طَلَّقَكُنَّ أَن یُبۡدِلَهُۥۤ أَزۡوَ ٰ⁠جًا خَیۡرࣰا مِّنكُنَّ مُسۡلِمَـٰتࣲ مُّؤۡمِنَـٰتࣲ قَـٰنِتَـٰتࣲ تَـٰۤىِٕبَـٰتٍ عَـٰبِدَ ٰ⁠تࣲ سَـٰۤىِٕحَـٰتࣲ ثَیِّبَـٰتࣲ وَأَبۡكَارࣰا',
    'عسى ربه ان طلقكن ان يبدله ازواجا خيرا منكن مسلمات مؤمنات قانتات تائبات عابدات سائحات ثيبات وابكارا',
    'عَسَىٰ رَبُّهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ط</rule>َلَّقَكُ<rule class=ghunnah>نّ</rule>َ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>بۡ</rule>دِلَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule>جًا خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>نك</rule>ُ<rule class=ghunnah>نّ</rule>َ مُسۡلِمَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّؤۡمِنَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ق</rule>َ<rule class=madda_normal>ـٰ</rule>نِتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِبَ<rule class=madda_normal>ـٰ</rule>تٍ عَ<rule class=madda_normal>ـٰ</rule>بِد<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>س</rule>َ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِحَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ث</rule>َيِّبَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>بۡ</rule>كَارًا ٥',
    5, 28, 7, 560, 494, 224, 'false'
  );
  
  -- Ayah 6 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5235,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ قُوۤا۟ أَنفُسَكُمۡ وَأَهۡلِیكُمۡ نَارࣰا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَیۡهَا مَلَـٰۤىِٕكَةٌ غِلَاظࣱ شِدَادࣱ لَّا یَعۡصُونَ ٱللَّهَ مَاۤ أَمَرَهُمۡ وَیَفۡعَلُونَ مَا یُؤۡمَرُونَ',
    'يا ايها الذين امنوا قوا انفسكم واهليكم نارا وقودها الناس والحجارة عليها ملائكة غلاظ شداد لا يعصون الله ما امرهم ويفعلون ما يؤمرون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> ق<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَ<rule class=ikhafa>نف</rule>ُسَكُمۡ وَأَهۡلِيكُمۡ نَا<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َقُودُهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ وَ<rule class=ham_wasl>ٱ</rule>لۡحِجَارَةُ عَلَيۡهَا مَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةٌ غِلَا<rule class=ikhafa>ظٌ</rule> <rule class=ikhafa>ش</rule>ِدَا<rule class=idgham_wo_ghunnah>دٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَعۡصُونَ <rule class=ham_wasl>ٱ</rule>للَّهَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَمَرَهُمۡ وَيَفۡعَلُونَ مَا يُؤۡمَر<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 28, 7, 560, 494, 224, 'false'
  );
  
  -- Ayah 7 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5236,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ كَفَرُوا۟ لَا تَعۡتَذِرُوا۟ ٱلۡیَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ',
    'يا ايها الذين كفروا لا تعتذروا اليوم انما تجزون ما كنتم تعملون',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَا تَعۡتَذِرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َمَا تُ<rule class=qalaqah>جۡ</rule>زَوۡنَ مَا كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡمَل<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 28, 7, 560, 494, 224, 'false'
  );
  
  -- Ayah 8 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5237,
    'یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ تُوبُوۤا۟ إِلَى ٱللَّهِ تَوۡبَةࣰ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن یُكَفِّرَ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَیُدۡخِلَكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ یَوۡمَ لَا یُخۡزِی ٱللَّهُ ٱلنَّبِیَّ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥۖ نُورُهُمۡ یَسۡعَىٰ بَیۡنَ أَیۡدِیهِمۡ وَبِأَیۡمَـٰنِهِمۡ یَقُولُونَ رَبَّنَاۤ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَاۤۖ إِنَّكَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ',
    'يا ايها الذين امنوا توبوا الى الله توبة نصوحا عسى ربكم ان يكفر عنكم سيئاتكم ويدخلكم جنات تجري من تحتها الانهار يوم لا يخزي الله النبي والذين امنوا معه نورهم يسعى بين ايديهم وبايمانهم يقولون ربنا اتمم لنا نورنا واغفر لنا انك على كل شيء قدير',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> تُوب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule>للَّهِ تَوۡبَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>ن</rule>َّصُوحًا عَسَىٰ رَبُّكُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَفِّرَ عَ<rule class=ikhafa>نك</rule>ُمۡ سَيِّـَٔـاتِكُمۡ وَيُ<rule class=qalaqah>دۡ</rule>خِلَكُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ يَوۡمَ لَا يُخۡزِى <rule class=ham_wasl>ٱ</rule>للَّهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىَّ وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مَعَهُ<rule class=madda_normal>ۥ</rule>‌ۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَ<rule class=madda_normal>ـٰ</rule>نِهِمۡ يَقُولُونَ رَبَّن<rule class=madda_obligatory_monfasel>َآ</rule> أَتۡمِمۡ لَنَا نُورَنَا وَ<rule class=ham_wasl>ٱ</rule>غۡفِرۡ لَن<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َكَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ٨',
    8, 28, 7, 561, 495, 224, 'false'
  );
  
  -- Ayah 9 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5238,
    'یَـٰۤأَیُّهَا ٱلنَّبِیُّ جَـٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَـٰفِقِینَ وَٱغۡلُظۡ عَلَیۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'يا ايها النبي جاهد الكفار والمنافقين واغلظ عليهم وماواهم جهنم وبئس المصير',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َبِىُّ جَ<rule class=madda_normal>ـٰ</rule>هِدِ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُنَ<rule class=madda_normal>ـٰ</rule>فِقِينَ وَ<rule class=ham_wasl>ٱ</rule>غۡلُظۡ عَلَيۡهِمۡ‌ۚ وَمَأۡوَ<rule class=madda_normal>ٮٰ</rule>هُمۡ جَهَ<rule class=ghunnah>نّ</rule>َمُ‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٩',
    9, 28, 7, 561, 495, 224, 'false'
  );
  
  -- Ayah 10 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5239,
    'ضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِینَ كَفَرُوا۟ ٱمۡرَأَتَ نُوحࣲ وَٱمۡرَأَتَ لُوطࣲۖ كَانَتَا تَحۡتَ عَبۡدَیۡنِ مِنۡ عِبَادِنَا صَـٰلِحَیۡنِ فَخَانَتَاهُمَا فَلَمۡ یُغۡنِیَا عَنۡهُمَا مِنَ ٱللَّهِ شَیۡـࣰٔا وَقِیلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّ ٰ⁠خِلِینَ',
    'ضرب الله مثلا للذين كفروا امرات نوح وامرات لوط كانتا تحت عبدين من عبادنا صالحين فخانتاهما فلم يغنيا عنهما من الله شيئا وقيل ادخلا النار مع الداخلين',
    'ضَرَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَثَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>مۡرَأَتَ نُو<rule class=idgham_ghunnah>حٍ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>مۡرَأَتَ لُو<rule class=ikhafa>طٍ‌ۖ</rule> <rule class=ikhafa>ك</rule>َانَتَا تَحۡتَ عَ<rule class=qalaqah>بۡ</rule>دَيۡنِ مِنۡ عِبَادِنَا صَ<rule class=madda_normal>ـٰ</rule>لِحَيۡنِ فَخَانَتَاهُمَا فَلَمۡ يُغۡنِيَا عَنۡهُمَا مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ شَيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َقِيلَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارَ مَعَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_normal>ٰ</rule>خِل<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 28, 7, 561, 495, 224, 'false'
  );
  
  -- Ayah 11 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5240,
    'وَضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِینَ ءَامَنُوا۟ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِی عِندَكَ بَیۡتࣰا فِی ٱلۡجَنَّةِ وَنَجِّنِی مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِی مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ',
    'وضرب الله مثلا للذين امنوا امرات فرعون اذ قالت رب ابن لي عندك بيتا في الجنة ونجني من فرعون وعمله ونجني من القوم الظالمين',
    'وَضَرَبَ <rule class=ham_wasl>ٱ</rule>للَّهُ مَثَل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>مۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نِ لِى عِ<rule class=ikhafa>ند</rule>َكَ بَيۡ<rule class=ikhafa>تًا</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ وَنَجِّنِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِرۡعَوۡنَ وَعَمَلِه<rule class=madda_normal>ِۦ</rule> وَنَجِّنِى مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 28, 7, 561, 495, 224, 'false'
  );
  
  -- Ayah 12 Surah At-Tahrim
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    66,
    5241,
    'وَمَرۡیَمَ ٱبۡنَتَ عِمۡرَ ٰ⁠نَ ٱلَّتِیۤ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِیهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَـٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَـٰنِتِینَ',
    'ومريم ابنت عمران التي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمات ربها وكتبه وكانت من القانتين',
    'وَمَرۡيَمَ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>نَتَ عِمۡر<rule class=madda_normal>ٰ</rule>نَ <rule class=ham_wasl>ٱ</rule>لَّت<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهِ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ُّوحِنَا وَصَدَّقَتۡ بِكَلِمَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهَا وَكُتُبِه<rule class=madda_normal>ِۦ</rule> وَكَانَتۡ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>نِت<rule class=madda_permissible>ِي</rule>نَ ١٢',
    12, 28, 7, 561, 495, 224, 'false'
  );
  

-- Surah Al-Mulk
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (67, 'سُورَةُ المُلۡكِ', 'Al-Mulk', 'The Sovereignty', 'Meccan', 30);

  -- Ayah 1 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5242,
    'تَبَـٰرَكَ ٱلَّذِی بِیَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ',
    'تبارك الذي بيده الملك وهو على كل شيء قدير',
    'تَبَ<rule class=madda_normal>ـٰ</rule>رَكَ <rule class=ham_wasl>ٱ</rule>لَّذِى بِيَدِهِ <rule class=ham_wasl>ٱ</rule>لۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ق</rule>َد<rule class=madda_permissible>ِي</rule>رٌ ١',
    1, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 2 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5243,
    'ٱلَّذِی خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَیَوٰةَ لِیَبۡلُوَكُمۡ أَیُّكُمۡ أَحۡسَنُ عَمَلࣰاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡغَفُورُ',
    'الذي خلق الموت والحياة ليبلوكم ايكم احسن عملا وهو العزيز الغفور',
    'ٱلَّذِى خَلَقَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَ وَ<rule class=ham_wasl>ٱ</rule>لۡحَيَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ لِيَ<rule class=qalaqah>بۡ</rule>لُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَل<rule class=idgham_ghunnah>اً‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزُ <rule class=ham_wasl>ٱ</rule>لۡغَف<rule class=madda_permissible>ُو</rule>رُ ٢',
    2, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 3 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5244,
    'ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ طِبَاقࣰاۖ مَّا تَرَىٰ فِی خَلۡقِ ٱلرَّحۡمَـٰنِ مِن تَفَـٰوُتࣲۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورࣲ',
    'الذي خلق سبع سماوات طباقا ما ترى في خلق الرحمن من تفاوت فارجع البصر هل ترى من فطور',
    'ٱلَّذِى خَلَقَ سَ<rule class=qalaqah>بۡ</rule>عَ سَمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ط</rule>ِبَا<rule class=idgham_ghunnah>قًا‌ۖ</rule> <rule class=idgham_ghunnah>م</rule>َّا تَرَىٰ فِى خَلۡقِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َفَ<rule class=madda_normal>ـٰ</rule>وُ<rule class=ikhafa>تٍ‌ۖ</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>رۡجِعِ <rule class=ham_wasl>ٱ</rule>لۡبَصَرَ هَلۡ تَرَىٰ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ُط<rule class=madda_permissible>ُو</rule>رٍ ٣',
    3, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 4 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5245,
    'ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَیۡنِ یَنقَلِبۡ إِلَیۡكَ ٱلۡبَصَرُ خَاسِئࣰا وَهُوَ حَسِیرࣱ',
    'ثم ارجع البصر كرتين ينقلب اليك البصر خاسئا وهو حسير',
    'ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>رۡجِعِ <rule class=ham_wasl>ٱ</rule>لۡبَصَرَ كَرَّتَيۡنِ يَ<rule class=ikhafa>نق</rule>َلِ<rule class=qalaqah>بۡ</rule> إِلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡبَصَرُ خَاسِ<rule class=idgham_ghunnah>ئًا</rule> <rule class=idgham_ghunnah>و</rule>َهُوَ حَس<rule class=madda_permissible>ِي</rule>رٌ ٤',
    4, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 5 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5246,
    'وَلَقَدۡ زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِمَصَـٰبِیحَ وَجَعَلۡنَـٰهَا رُجُومࣰا لِّلشَّیَـٰطِینِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِیرِ',
    'ولقد زينا السماء الدنيا بمصابيح وجعلناها رجوما للشياطين واعتدنا لهم عذاب السعير',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> زَيَّ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دُّنۡيَا بِمَصَ<rule class=madda_normal>ـٰ</rule>بِيحَ وَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هَا رُجُو<rule class=idgham_wo_ghunnah>مًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلشَّيَ<rule class=madda_normal>ـٰ</rule>طِينِ‌ۖ وَأَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لَهُمۡ عَذَابَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّع<rule class=madda_permissible>ِي</rule>رِ ٥',
    5, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 6 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5247,
    'وَلِلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِیرُ',
    'وللذين كفروا بربهم عذاب جهنم وبئس المصير',
    'وَلِلَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> بِرَبِّهِمۡ عَذَابُ جَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۖ وَبِئۡسَ <rule class=ham_wasl>ٱ</rule>لۡمَص<rule class=madda_permissible>ِي</rule>رُ ٦',
    6, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 7 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5248,
    'إِذَاۤ أُلۡقُوا۟ فِیهَا سَمِعُوا۟ لَهَا شَهِیقࣰا وَهِیَ تَفُورُ',
    'اذا القوا فيها سمعوا لها شهيقا وهي تفور',
    'إِذ<rule class=madda_obligatory_monfasel>َآ</rule> أُلۡقُو<rule class=slnt>اۡ</rule> فِيهَا سَمِعُو<rule class=slnt>اۡ</rule> لَهَا شَهِي<rule class=idgham_ghunnah>قًا</rule> <rule class=idgham_ghunnah>و</rule>َهِىَ تَف<rule class=madda_permissible>ُو</rule>رُ ٧',
    7, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 8 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5249,
    'تَكَادُ تَمَیَّزُ مِنَ ٱلۡغَیۡظِۖ كُلَّمَاۤ أُلۡقِیَ فِیهَا فَوۡجࣱ سَأَلَهُمۡ خَزَنَتُهَاۤ أَلَمۡ یَأۡتِكُمۡ نَذِیرࣱ',
    'تكاد تميز من الغيظ كلما القي فيها فوج سالهم خزنتها الم ياتكم نذير',
    'تَكَادُ تَمَيَّزُ مِنَ <rule class=ham_wasl>ٱ</rule>لۡغَيۡظِ‌ۖ كُلَّم<rule class=madda_obligatory_monfasel>َآ</rule> أُلۡقِىَ فِيهَا فَوۡ<rule class=ikhafa>جٌ</rule> <rule class=ikhafa>س</rule>َأَلَهُمۡ خَزَنَتُه<rule class=madda_obligatory_monfasel>َآ</rule> أَلَمۡ يَأۡتِكُمۡ نَذ<rule class=madda_permissible>ِي</rule>رٌ ٨',
    8, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 9 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5250,
    'قَالُوا۟ بَلَىٰ قَدۡ جَاۤءَنَا نَذِیرࣱ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَیۡءٍ إِنۡ أَنتُمۡ إِلَّا فِی ضَلَـٰلࣲ كَبِیرࣲ',
    'قالوا بلى قد جاءنا نذير فكذبنا وقلنا ما نزل الله من شيء ان انتم الا في ضلال كبير',
    'قَالُو<rule class=slnt>اۡ</rule> بَلَىٰ قَ<rule class=qalaqah>دۡ</rule> ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَنَا نَذِي<rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ف</rule>َكَذَّ<rule class=qalaqah>بۡ</rule>نَا وَقُلۡنَا مَا نَزَّلَ <rule class=ham_wasl>ٱ</rule>للَّهُ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َىۡءٍ إِنۡ أَ<rule class=ikhafa>نت</rule>ُمۡ إِلَّا فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ك</rule>َب<rule class=madda_permissible>ِي</rule>رٍ ٩',
    9, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 10 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5251,
    'وَقَالُوا۟ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِیۤ أَصۡحَـٰبِ ٱلسَّعِیرِ',
    'وقالوا لو كنا نسمع او نعقل ما كنا في اصحاب السعير',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَوۡ كُ<rule class=ghunnah>نّ</rule>َا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُ<rule class=ghunnah>نّ</rule>َا ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّع<rule class=madda_permissible>ِي</rule>رِ ١٠',
    10, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 11 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5252,
    'فَٱعۡتَرَفُوا۟ بِذَنۢبِهِمۡ فَسُحۡقࣰا لِّأَصۡحَـٰبِ ٱلسَّعِیرِ',
    'فاعترفوا بذنبهم فسحقا لاصحاب السعير',
    'فَ<rule class=ham_wasl>ٱ</rule>عۡتَرَفُو<rule class=slnt>اۡ</rule> بِذَ<rule class=iqlab>نۢب</rule>ِهِمۡ فَسُحۡ<rule class=idgham_wo_ghunnah>قًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّأَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّع<rule class=madda_permissible>ِي</rule>رِ ١١',
    11, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 12 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5253,
    'إِنَّ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرࣱ',
    'ان الذين يخشون ربهم بالغيب لهم مغفرة واجر كبير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ يَخۡشَوۡنَ رَبَّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّغۡفِرَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رٌ</rule> <rule class=ikhafa>ك</rule>َب<rule class=madda_permissible>ِي</rule>رٌ ١٢',
    12, 29, 7, 562, 496, 225, 'false'
  );
  
  -- Ayah 13 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5254,
    'وَأَسِرُّوا۟ قَوۡلَكُمۡ أَوِ ٱجۡهَرُوا۟ بِهِۦۤۖ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ',
    'واسروا قولكم او اجهروا به انه عليم بذات الصدور',
    'وَأَسِرُّو<rule class=slnt>اۡ</rule> قَوۡلَكُمۡ أَوِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>هَرُو<rule class=slnt>اۡ</rule> بِه<rule class=madda_obligatory_monfasel>ِۦٓ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلِي<rule class=iqlab>مُۢ</rule> <rule class=iqlab>ب</rule>ِذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ١٣',
    13, 29, 7, 563, 496, 225, 'false'
  );
  
  -- Ayah 14 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5255,
    'أَلَا یَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِیفُ ٱلۡخَبِیرُ',
    'الا يعلم من خلق وهو اللطيف الخبير',
    'أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>لَّطِيفُ <rule class=ham_wasl>ٱ</rule>لۡخَب<rule class=madda_permissible>ِي</rule>رُ ١٤',
    14, 29, 7, 563, 496, 225, 'false'
  );
  
  -- Ayah 15 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5256,
    'هُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولࣰا فَٱمۡشُوا۟ فِی مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزۡقِهِۦۖ وَإِلَیۡهِ ٱلنُّشُورُ',
    'هو الذي جعل لكم الارض ذلولا فامشوا في مناكبها وكلوا من رزقه واليه النشور',
    'هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ ذَلُول<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>مۡشُو<rule class=slnt>اۡ</rule> فِى مَنَاكِبِهَا وَكُلُو<rule class=slnt>اۡ</rule> م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>ِّزۡقِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَإِلَيۡهِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>ُش<rule class=madda_permissible>ُو</rule>رُ ١٥',
    15, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 16 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5257,
    'ءَأَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِیَ تَمُورُ',
    'اامنتم من في السماء ان يخسف بكم الارض فاذا هي تمور',
    'ءَأَمِ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َخۡسِفَ بِكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ فَإِذَا هِىَ تَم<rule class=madda_permissible>ُو</rule>رُ ١٦',
    16, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 17 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5258,
    'أَمۡ أَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یُرۡسِلَ عَلَیۡكُمۡ حَاصِبࣰاۖ فَسَتَعۡلَمُونَ كَیۡفَ نَذِیرِ',
    'ام امنتم من في السماء ان يرسل عليكم حاصبا فستعلمون كيف نذير',
    'أَمۡ أَمِ<rule class=ikhafa>نت</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُرۡسِلَ عَلَيۡكُمۡ حَاصِ<rule class=ikhafa>بًا‌ۖ</rule> <rule class=ikhafa>ف</rule>َسَتَعۡلَمُونَ كَيۡفَ نَذ<rule class=madda_permissible>ِي</rule>رِ ١٧',
    17, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 18 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5259,
    'وَلَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَكَیۡفَ كَانَ نَكِیرِ',
    'ولقد كذب الذين من قبلهم فكيف كان نكير',
    'وَلَقَ<rule class=qalaqah>دۡ</rule> كَذَّبَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِهِمۡ فَكَيۡفَ كَانَ نَك<rule class=madda_permissible>ِي</rule>رِ ١٨',
    18, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 19 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5260,
    'أَوَلَمۡ یَرَوۡا۟ إِلَى ٱلطَّیۡرِ فَوۡقَهُمۡ صَـٰۤفَّـٰتࣲ وَیَقۡبِضۡنَۚ مَا یُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَـٰنُۚ إِنَّهُۥ بِكُلِّ شَیۡءِۭ بَصِیرٌ',
    'اولم يروا الى الطير فوقهم صافات ويقبضن ما يمسكهن الا الرحمن انه بكل شيء بصير',
    'أَوَلَمۡ يَرَوۡ<rule class=slnt>اۡ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّيۡرِ فَوۡقَهُمۡ صَ<rule class=madda_necessary>ـٰٓ</rule>فَّ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َيَ<rule class=qalaqah>قۡ</rule>بِضۡنَ‌ۚ مَا يُمۡسِكُهُ<rule class=ghunnah>نّ</rule>َ إِلَّا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> بِكُلِّ شَىۡ<rule class=iqlab>ءِۭ</rule> <rule class=iqlab>ب</rule>َص<rule class=madda_permissible>ِي</rule>رٌ ١٩',
    19, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 20 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5261,
    'أَمَّنۡ هَـٰذَا ٱلَّذِی هُوَ جُندࣱ لَّكُمۡ یَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَـٰنِۚ إِنِ ٱلۡكَـٰفِرُونَ إِلَّا فِی غُرُورٍ',
    'امن هذا الذي هو جند لكم ينصركم من دون الرحمن ان الكافرون الا في غرور',
    'أَ<rule class=ghunnah>مّ</rule>َنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى هُوَ جُن<rule class=idgham_wo_ghunnah>دٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّكُمۡ يَ<rule class=ikhafa>نص</rule>ُرُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ‌ۚ إِنِ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرُونَ إِلَّا فِى غُر<rule class=madda_permissible>ُو</rule>رٍ ٢٠',
    20, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 21 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5262,
    'أَمَّنۡ هَـٰذَا ٱلَّذِی یَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّوا۟ فِی عُتُوࣲّ وَنُفُورٍ',
    'امن هذا الذي يرزقكم ان امسك رزقه بل لجوا في عتو ونفور',
    'أَ<rule class=ghunnah>مّ</rule>َنۡ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى يَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُ<rule class=madda_normal>ۥ</rule>‌ۚ بَل لَّجُّو<rule class=slnt>اۡ</rule> فِى عُتُ<rule class=idgham_ghunnah>وٍّ</rule> <rule class=idgham_ghunnah>و</rule>َنُف<rule class=madda_permissible>ُو</rule>رٍ ٢١',
    21, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 22 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5263,
    'أَفَمَن یَمۡشِی مُكِبًّا عَلَىٰ وَجۡهِهِۦۤ أَهۡدَىٰۤ أَمَّن یَمۡشِی سَوِیًّا عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ',
    'افمن يمشي مكبا على وجهه اهدى امن يمشي سويا على صراط مستقيم',
    'أَفَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡشِى مُكِبًّا عَلَىٰ وَ<rule class=qalaqah>جۡ</rule>هِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَهۡدَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَ<rule class=ghunnah>مّ</rule><rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َمۡشِى سَوِيًّا عَلَىٰ صِر<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>طٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسۡتَق<rule class=madda_permissible>ِي</rule>مٍ ٢٢',
    22, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 23 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5264,
    'قُلۡ هُوَ ٱلَّذِیۤ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ',
    'قل هو الذي انشاكم وجعل لكم السمع والابصار والافئدة قليلا ما تشكرون',
    'قُلۡ هُوَ <rule class=ham_wasl>ٱ</rule>لَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=ikhafa>نش</rule>َأَكُمۡ وَجَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمۡعَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رَ وَ<rule class=ham_wasl>ٱ</rule>لۡأَفۡــِٔدَةَ‌ۖ قَلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تَشۡكُر<rule class=madda_permissible>ُو</rule>نَ ٢٣',
    23, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 24 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5265,
    'قُلۡ هُوَ ٱلَّذِی ذَرَأَكُمۡ فِی ٱلۡأَرۡضِ وَإِلَیۡهِ تُحۡشَرُونَ',
    'قل هو الذي ذراكم في الارض واليه تحشرون',
    'قُلۡ هُوَ <rule class=ham_wasl>ٱ</rule>لَّذِى ذَرَأَكُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَإِلَيۡهِ تُحۡشَر<rule class=madda_permissible>ُو</rule>نَ ٢٤',
    24, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 25 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5266,
    'وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ',
    'ويقولون متى هذا الوعد ان كنتم صادقين',
    'وَيَقُولُونَ مَتَىٰ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡوَعۡدُ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُ<rule class=ikhafa>نت</rule>ُمۡ صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٢٥',
    25, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 26 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5267,
    'قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینࣱ',
    'قل انما العلم عند الله وانما انا نذير مبين',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َمَا <rule class=ham_wasl>ٱ</rule>لۡعِلۡمُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ وَإِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٢٦',
    26, 29, 7, 563, 497, 225, 'false'
  );
  
  -- Ayah 27 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5268,
    'فَلَمَّا رَأَوۡهُ زُلۡفَةࣰ سِیۤـَٔتۡ وُجُوهُ ٱلَّذِینَ كَفَرُوا۟ وَقِیلَ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تَدَّعُونَ',
    'فلما راوه زلفة سيئت وجوه الذين كفروا وقيل هذا الذي كنتم به تدعون',
    'فَلَ<rule class=ghunnah>مّ</rule>َا رَأَوۡهُ زُلۡفَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>س</rule>ِ<rule class=madda_obligatory_mottasel>يٓ</rule>ــَٔتۡ وُجُوهُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> وَقِيلَ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> تَدَّع<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 29, 7, 564, 497, 225, 'false'
  );
  
  -- Ayah 28 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5269,
    'قُلۡ أَرَءَیۡتُمۡ إِنۡ أَهۡلَكَنِیَ ٱللَّهُ وَمَن مَّعِیَ أَوۡ رَحِمَنَا فَمَن یُجِیرُ ٱلۡكَـٰفِرِینَ مِنۡ عَذَابٍ أَلِیمࣲ',
    'قل ارايتم ان اهلكني الله ومن معي او رحمنا فمن يجير الكافرين من عذاب اليم',
    'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَهۡلَكَنِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>م</rule>َّعِىَ أَوۡ رَحِمَنَا فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجِيرُ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ مِنۡ عَذَابٍ أَل<rule class=madda_permissible>ِي</rule>مٍ ٢٨',
    28, 29, 7, 564, 497, 225, 'false'
  );
  
  -- Ayah 29 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5270,
    'قُلۡ هُوَ ٱلرَّحۡمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَیۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ',
    'قل هو الرحمن امنا به وعليه توكلنا فستعلمون من هو في ضلال مبين',
    'قُلۡ هُوَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ ءَامَ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_normal>ِۦ</rule> وَعَلَيۡهِ تَوَكَّلۡنَا‌ۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِى ضَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٍ ٢٩',
    29, 29, 7, 564, 497, 225, 'false'
  );
  
  -- Ayah 30 Surah Al-Mulk
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    67,
    5271,
    'قُلۡ أَرَءَیۡتُمۡ إِنۡ أَصۡبَحَ مَاۤؤُكُمۡ غَوۡرࣰا فَمَن یَأۡتِیكُم بِمَاۤءࣲ مَّعِینِۭ',
    'قل ارايتم ان اصبح ماؤكم غورا فمن ياتيكم بماء معين',
    'قُلۡ أَرَءَيۡتُمۡ إِنۡ أَصۡبَحَ م<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُكُمۡ غَوۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِم<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءٍ</rule> <rule class=idgham_ghunnah>م</rule>َّع<rule class=madda_permissible>ِي</rule>نِۭ ٣٠',
    30, 29, 7, 564, 497, 225, 'false'
  );
  

-- Surah Al-Qalam
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (68, 'سُورَةُ القَلَمِ', 'Al-Qalam', 'The Pen', 'Meccan', 52);

  -- Ayah 1 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5272,
    'نۤۚ وَٱلۡقَلَمِ وَمَا یَسۡطُرُونَ',
    'ن والقلم وما يسطرون',
    '<rule class=madda_necessary>نٓ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule>لۡقَلَمِ وَمَا يَسۡطُر<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 2 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5273,
    'مَاۤ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونࣲ',
    'ما انت بنعمة ربك بمجنون',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>َ بِنِعۡمَةِ رَبِّكَ بِمَ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نٍ ٢',
    2, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 3 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5274,
    'وَإِنَّ لَكَ لَأَجۡرًا غَیۡرَ مَمۡنُونࣲ',
    'وان لك لاجرا غير ممنون',
    'وَإِ<rule class=ghunnah>نّ</rule>َ لَكَ لَأَ<rule class=qalaqah>جۡ</rule>رًا غَيۡرَ مَمۡن<rule class=madda_permissible>ُو</rule>نٍ ٣',
    3, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 4 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5275,
    'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِیمࣲ',
    'وانك لعلى خلق عظيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َكَ لَعَلَىٰ خُلُقٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ٤',
    4, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 5 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5276,
    'فَسَتُبۡصِرُ وَیُبۡصِرُونَ',
    'فستبصر ويبصرون',
    'فَسَتُ<rule class=qalaqah>بۡ</rule>صِرُ وَيُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 6 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5277,
    'بِأَییِّكُمُ ٱلۡمَفۡتُونُ',
    'باييكم المفتون',
    'بِأَييِّكُمُ <rule class=ham_wasl>ٱ</rule>لۡمَفۡت<rule class=madda_permissible>ُو</rule>نُ ٦',
    6, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 7 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5278,
    'إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ',
    'ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ هُوَ أَعۡلَمُ بِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ض</rule>َلَّ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َبِيلِه<rule class=madda_normal>ِۦ</rule> وَهُوَ أَعۡلَمُ بِ<rule class=ham_wasl>ٱ</rule>لۡمُهۡتَد<rule class=madda_permissible>ِي</rule>نَ ٧',
    7, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 8 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5279,
    'فَلَا تُطِعِ ٱلۡمُكَذِّبِینَ',
    'فلا تطع المكذبين',
    'فَلَا تُطِعِ <rule class=ham_wasl>ٱ</rule>لۡمُكَذِّب<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 9 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5280,
    'وَدُّوا۟ لَوۡ تُدۡهِنُ فَیُدۡهِنُونَ',
    'ودوا لو تدهن فيدهنون',
    'وَدُّو<rule class=slnt>اۡ</rule> لَوۡ تُ<rule class=qalaqah>دۡ</rule>هِنُ فَيُ<rule class=qalaqah>دۡ</rule>هِن<rule class=madda_permissible>ُو</rule>نَ ٩',
    9, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 10 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5281,
    'وَلَا تُطِعۡ كُلَّ حَلَّافࣲ مَّهِینٍ',
    'ولا تطع كل حلاف مهين',
    'وَلَا تُطِعۡ كُلَّ حَلَّا<rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>م</rule>َّه<rule class=madda_permissible>ِي</rule>نٍ ١٠',
    10, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 11 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5282,
    'هَمَّازࣲ مَّشَّاۤءِۭ بِنَمِیمࣲ',
    'هماز مشاء بنميم',
    'هَ<rule class=ghunnah>مّ</rule>َا<rule class=idgham_ghunnah>زٍ</rule> <rule class=idgham_ghunnah>م</rule>َّشّ<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=iqlab>ءِۭ</rule> <rule class=iqlab>ب</rule>ِنَم<rule class=madda_permissible>ِي</rule>مٍ ١١',
    11, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 12 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5283,
    'مَّنَّاعࣲ لِّلۡخَیۡرِ مُعۡتَدٍ أَثِیمٍ',
    'مناع للخير معتد اثيم',
    'مَّ<rule class=ghunnah>نّ</rule>َا<rule class=idgham_wo_ghunnah>عٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡخَيۡرِ مُعۡتَدٍ أَث<rule class=madda_permissible>ِي</rule>مٍ ١٢',
    12, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 13 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5284,
    'عُتُلِّۭ بَعۡدَ ذَ ٰ⁠لِكَ زَنِیمٍ',
    'عتل بعد ذلك زنيم',
    'عُتُل<rule class=iqlab>ِّۭ</rule> <rule class=iqlab>ب</rule>َعۡدَ ذ<rule class=madda_normal>ٰ</rule>لِكَ زَن<rule class=madda_permissible>ِي</rule>مٍ ١٣',
    13, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 14 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5285,
    'أَن كَانَ ذَا مَالࣲ وَبَنِینَ',
    'ان كان ذا مال وبنين',
    'أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ ذَا مَا<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َبَن<rule class=madda_permissible>ِي</rule>نَ ١٤',
    14, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 15 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5286,
    'إِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا قَالَ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ',
    'اذا تتلى عليه اياتنا قال اساطير الاولين',
    'إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا قَالَ أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ١٥',
    15, 29, 7, 564, 498, 226, 'false'
  );
  
  -- Ayah 16 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5287,
    'سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ',
    'سنسمه على الخرطوم',
    'سَنَسِمُهُ<rule class=madda_normal>ۥ</rule> عَلَى <rule class=ham_wasl>ٱ</rule>لۡخُرۡط<rule class=madda_permissible>ُو</rule>مِ ١٦',
    16, 29, 7, 565, 498, 226, 'false'
  );
  
  -- Ayah 17 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5288,
    'إِنَّا بَلَوۡنَـٰهُمۡ كَمَا بَلَوۡنَاۤ أَصۡحَـٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُوا۟ لَیَصۡرِمُنَّهَا مُصۡبِحِینَ',
    'انا بلوناهم كما بلونا اصحاب الجنة اذ اقسموا ليصرمنها مصبحين',
    'إِ<rule class=ghunnah>نّ</rule>َا بَلَوۡنَ<rule class=madda_normal>ـٰ</rule>هُمۡ كَمَا بَلَوۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَصۡحَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لۡجَ<rule class=ghunnah>نّ</rule>َةِ إِذۡ أَ<rule class=qalaqah>قۡ</rule>سَمُو<rule class=slnt>اۡ</rule> لَيَصۡرِمُ<rule class=ghunnah>نّ</rule>َهَا مُصۡبِح<rule class=madda_permissible>ِي</rule>نَ ١٧',
    17, 29, 7, 565, 498, 226, 'false'
  );
  
