  -- Ayah 28 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5299,
    'قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ',
    'قال اوسطهم الم اقل لكم لولا تسبحون',
    'قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّح<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 29, 7, 565, 498, 226, 'false'
