  -- Ayah 29 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5300,
    'قَالُوا۟ سُبۡحَـٰنَ رَبِّنَاۤ إِنَّا كُنَّا ظَـٰلِمِینَ',
    'قالوا سبحان ربنا انا كنا ظالمين',
    'قَالُو<rule class=slnt>اۡ</rule> سُ<rule class=qalaqah>بۡ</rule>حَ<rule class=madda_normal>ـٰ</rule>نَ رَبِّن<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا ظَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ِي</rule>نَ ٢٩',
