  -- Ayah 32 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5303,
    'عَسَىٰ رَبُّنَاۤ أَن یُبۡدِلَنَا خَیۡرࣰا مِّنۡهَاۤ إِنَّاۤ إِلَىٰ رَبِّنَا رَ ٰ⁠غِبُونَ',
    'عسى ربنا ان يبدلنا خيرا منها انا الى ربنا راغبون',
    'عَسَىٰ رَبُّن<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>بۡ</rule>دِلَنَا خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡه<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ رَبِّنَا ر<rule class=madda_normal>ٰ</rule>غِب<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 29, 7, 565, 498, 226, 'false'
  );
  
  -- Ayah 33 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5304,
    'كَذَ ٰ⁠لِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَكۡبَرُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ',
    'كذلك العذاب ولعذاب الاخرة اكبر لو كانوا يعلمون',
    'كَذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡعَذَابُ‌ۖ وَلَعَذَابُ <rule class=ham_wasl>ٱ</rule>لۡأَخِرَةِ أَكۡبَرُ‌ۚ لَوۡ كَانُو<rule class=slnt>اۡ</rule> يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 29, 7, 565, 498, 226, 'false'
  );
  
  -- Ayah 34 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5305,
    'إِنَّ لِلۡمُتَّقِینَ عِندَ رَبِّهِمۡ جَنَّـٰتِ ٱلنَّعِیمِ',
    'ان للمتقين عند ربهم جنات النعيم',
    'إِ<rule class=ghunnah>نّ</rule>َ لِلۡمُتَّقِينَ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َع<rule class=madda_permissible>ِي</rule>مِ ٣٤',
    34, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 35 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5306,
    'أَفَنَجۡعَلُ ٱلۡمُسۡلِمِینَ كَٱلۡمُجۡرِمِینَ',
    'افنجعل المسلمين كالمجرمين',
    'أَفَنَ<rule class=qalaqah>جۡ</rule>عَلُ <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِمِينَ كَ<rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>جۡ</rule>رِم<rule class=madda_permissible>ِي</rule>نَ ٣٥',
    35, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 36 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5307,
    'مَا لَكُمۡ كَیۡفَ تَحۡكُمُونَ',
    'ما لكم كيف تحكمون',
    'مَا لَكُمۡ كَيۡفَ تَحۡكُم<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 37 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5308,
    'أَمۡ لَكُمۡ كِتَـٰبࣱ فِیهِ تَدۡرُسُونَ',
    'ام لكم كتاب فيه تدرسون',
    'أَمۡ لَكُمۡ كِتَ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ف</rule>ِيهِ تَ<rule class=qalaqah>دۡ</rule>رُس<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 38 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5309,
    'إِنَّ لَكُمۡ فِیهِ لَمَا تَخَیَّرُونَ',
    'ان لكم فيه لما تخيرون',
    'إِ<rule class=ghunnah>نّ</rule>َ لَكُمۡ فِيهِ لَمَا تَخَيَّر<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 39 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5310,
    'أَمۡ لَكُمۡ أَیۡمَـٰنٌ عَلَیۡنَا بَـٰلِغَةٌ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ',
    'ام لكم ايمان علينا بالغة الى يوم القيامة ان لكم لما تحكمون',
    'أَمۡ لَكُمۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نٌ عَلَيۡنَا بَ<rule class=madda_normal>ـٰ</rule>لِغَةٌ إِلَىٰ يَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡقِيَ<rule class=madda_normal>ـٰ</rule>مَةِ‌ۙ إِ<rule class=ghunnah>نّ</rule>َ لَكُمۡ لَمَا تَحۡكُم<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 40 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5311,
    'سَلۡهُمۡ أَیُّهُم بِذَ ٰ⁠لِكَ زَعِیمٌ',
    'سلهم ايهم بذلك زعيم',
    'سَلۡهُمۡ أَيُّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذ<rule class=madda_normal>ٰ</rule>لِكَ زَع<rule class=madda_permissible>ِي</rule>مٌ ٤٠',
    40, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 41 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5312,
    'أَمۡ لَهُمۡ شُرَكَاۤءُ فَلۡیَأۡتُوا۟ بِشُرَكَاۤىِٕهِمۡ إِن كَانُوا۟ صَـٰدِقِینَ',
    'ام لهم شركاء فلياتوا بشركائهم ان كانوا صادقين',
    'أَمۡ لَهُمۡ شُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فَلۡيَأۡتُو<rule class=slnt>اۡ</rule> بِشُرَك<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهِمۡ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانُو<rule class=slnt>اۡ</rule> صَ<rule class=madda_normal>ـٰ</rule>دِق<rule class=madda_permissible>ِي</rule>نَ ٤١',
    41, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 42 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5313,
    'یَوۡمَ یُكۡشَفُ عَن سَاقࣲ وَیُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا یَسۡتَطِیعُونَ',
    'يوم يكشف عن ساق ويدعون الى السجود فلا يستطيعون',
    'يَوۡمَ يُكۡشَفُ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َا<rule class=idgham_ghunnah>قٍ</rule> <rule class=idgham_ghunnah>و</rule>َيُ<rule class=qalaqah>دۡ</rule>عَوۡنَ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّجُودِ فَلَا يَسۡتَطِيع<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 29, 7, 565, 499, 226, 'false'
  );
  
  -- Ayah 43 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5314,
    'خَـٰشِعَةً أَبۡصَـٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةࣱۖ وَقَدۡ كَانُوا۟ یُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَـٰلِمُونَ',
    'خاشعة ابصارهم ترهقهم ذلة وقد كانوا يدعون الى السجود وهم سالمون',
    'خَ<rule class=madda_normal>ـٰ</rule>شِعَةً أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُهُمۡ تَرۡهَقُهُمۡ ذِلَّ<rule class=idgham_ghunnah>ةٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َقَ<rule class=qalaqah>دۡ</rule> كَانُو<rule class=slnt>اۡ</rule> يُ<rule class=qalaqah>دۡ</rule>عَوۡنَ إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سُّجُودِ وَهُمۡ سَ<rule class=madda_normal>ـٰ</rule>لِم<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 44 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5315,
    'فَذَرۡنِی وَمَن یُكَذِّبُ بِهَـٰذَا ٱلۡحَدِیثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَیۡثُ لَا یَعۡلَمُونَ',
    'فذرني ومن يكذب بهذا الحديث سنستدرجهم من حيث لا يعلمون',
    'فَذَرۡنِى وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُكَذِّبُ بِهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡحَدِيثِ‌ۖ سَنَسۡتَ<rule class=qalaqah>دۡ</rule>رِجُه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ حَيۡثُ لَا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 45 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5316,
    'وَأُمۡلِی لَهُمۡۚ إِنَّ كَیۡدِی مَتِینٌ',
    'واملي لهم ان كيدي متين',
    'وَأُمۡلِى لَهُمۡ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ كَيۡدِى مَت<rule class=madda_permissible>ِي</rule>نٌ ٤٥',
    45, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 46 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5317,
    'أَمۡ تَسۡـَٔلُهُمۡ أَجۡرࣰا فَهُم مِّن مَّغۡرَمࣲ مُّثۡقَلُونَ',
    'ام تسالهم اجرا فهم من مغرم مثقلون',
    'أَمۡ تَسۡــَٔلُهُمۡ أَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّغۡرَ<rule class=idgham_ghunnah>مٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّثۡقَل<rule class=madda_permissible>ُو</rule>نَ ٤٦',
    46, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 47 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5318,
    'أَمۡ عِندَهُمُ ٱلۡغَیۡبُ فَهُمۡ یَكۡتُبُونَ',
    'ام عندهم الغيب فهم يكتبون',
    'أَمۡ عِ<rule class=ikhafa>ند</rule>َهُمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبُ فَهُمۡ يَكۡتُب<rule class=madda_permissible>ُو</rule>نَ ٤٧',
    47, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 48 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5319,
    'فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومࣱ',
    'فاصبر لحكم ربك ولا تكن كصاحب الحوت اذ نادى وهو مكظوم',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َصَاحِبِ <rule class=ham_wasl>ٱ</rule>لۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظ<rule class=madda_permissible>ُو</rule>مٌ ٤٨',
    48, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 49 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5320,
    'لَّوۡلَاۤ أَن تَدَ ٰ⁠رَكَهُۥ نِعۡمَةࣱ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَاۤءِ وَهُوَ مَذۡمُومࣱ',
    'لولا ان تداركه نعمة من ربه لنبذ بالعراء وهو مذموم',
    'لَّوۡل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َد<rule class=madda_normal>ٰ</rule>رَكَهُ<rule class=madda_normal>ۥ</rule> نِعۡمَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّه<rule class=madda_normal>ِۦ</rule> لَنُبِذَ بِ<rule class=ham_wasl>ٱ</rule>لۡعَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَهُوَ مَذۡم<rule class=madda_permissible>ُو</rule>مٌ ٤٩',
    49, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 50 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5321,
    'فَٱجۡتَبَـٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِینَ',
    'فاجتباه ربه فجعله من الصالحين',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>جۡ</rule>تَبَ<rule class=madda_normal>ـٰ</rule>هُ رَبُّهُ<rule class=madda_normal>ۥ</rule> فَجَعَلَهُ<rule class=madda_normal>ۥ</rule> مِنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِح<rule class=madda_permissible>ِي</rule>نَ ٥٠',
    50, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 51 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5322,
    'وَإِن یَكَادُ ٱلَّذِینَ كَفَرُوا۟ لَیُزۡلِقُونَكَ بِأَبۡصَـٰرِهِمۡ لَمَّا سَمِعُوا۟ ٱلذِّكۡرَ وَیَقُولُونَ إِنَّهُۥ لَمَجۡنُونࣱ',
    'وان يكاد الذين كفروا ليزلقونك بابصارهم لما سمعوا الذكر ويقولون انه لمجنون',
    'وَإ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ي</rule>َكَادُ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> لَيُزۡلِقُونَكَ بِأَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رِهِمۡ لَ<rule class=ghunnah>مّ</rule>َا سَمِعُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَ وَيَقُولُونَ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَمَ<rule class=qalaqah>جۡ</rule>ن<rule class=madda_permissible>ُو</rule>نٌ ٥١',
    51, 29, 7, 566, 499, 226, 'false'
  );
  
  -- Ayah 52 Surah Al-Qalam
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    68,
    5323,
    'وَمَا هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَـٰلَمِینَ',
    'وما هو الا ذكر للعالمين',
    'وَمَا هُوَ إِلَّا ذِكۡ<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٥٢',
    52, 29, 7, 566, 499, 226, 'false'
  );
  

-- Surah Al-Haaqqa
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (69, 'سُورَةُ الحَاقَّةِ', 'Al-Haaqqa', 'The Reality', 'Meccan', 52);

  -- Ayah 1 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5324,
    'ٱلۡحَاۤقَّةُ',
    'الحاقة',
    'ٱلۡح<rule class=madda_necessary>َا</rule>ٓقَّةُ ١',
    1, 29, 7, 566, 500, 227, 'false'
  );
  
  -- Ayah 2 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5325,
    'مَا ٱلۡحَاۤقَّةُ',
    'ما الحاقة',
    'مَا <rule class=ham_wasl>ٱ</rule>لۡح<rule class=madda_necessary>َا</rule>ٓقَّةُ ٢',
    2, 29, 7, 566, 500, 227, 'false'
  );
  
  -- Ayah 3 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5326,
    'وَمَاۤ أَدۡرَىٰكَ مَا ٱلۡحَاۤقَّةُ',
    'وما ادراك ما الحاقة',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>كَ مَا <rule class=ham_wasl>ٱ</rule>لۡح<rule class=madda_necessary>َا</rule>ٓقَّةُ ٣',
    3, 29, 7, 566, 500, 227, 'false'
  );
  
  -- Ayah 4 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5327,
    'كَذَّبَتۡ ثَمُودُ وَعَادُۢ بِٱلۡقَارِعَةِ',
    'كذبت ثمود وعاد بالقارعة',
    'كَذَّبَتۡ ثَمُودُ وَعَا<rule class=iqlab>دُۢ</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule>لۡقَارِعَةِ ٤',
    4, 29, 7, 566, 500, 227, 'false'
  );
  
  -- Ayah 5 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5328,
    'فَأَمَّا ثَمُودُ فَأُهۡلِكُوا۟ بِٱلطَّاغِیَةِ',
    'فاما ثمود فاهلكوا بالطاغية',
    'فَأَ<rule class=ghunnah>مّ</rule>َا ثَمُودُ فَأُهۡلِكُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّاغِيَةِ ٥',
    5, 29, 7, 566, 500, 227, 'false'
  );
  
  -- Ayah 6 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5329,
    'وَأَمَّا عَادࣱ فَأُهۡلِكُوا۟ بِرِیحࣲ صَرۡصَرٍ عَاتِیَةࣲ',
    'واما عاد فاهلكوا بريح صرصر عاتية',
    'وَأَ<rule class=ghunnah>مّ</rule>َا عَا<rule class=ikhafa>دٌ</rule> <rule class=ikhafa>ف</rule>َأُهۡلِكُو<rule class=slnt>اۡ</rule> بِرِي<rule class=ikhafa>حٍ</rule> <rule class=ikhafa>ص</rule>َرۡصَرٍ عَاتِيَةٍ ٦',
    6, 29, 7, 566, 500, 227, 'false'
  );
  
  -- Ayah 7 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5330,
    'سَخَّرَهَا عَلَیۡهِمۡ سَبۡعَ لَیَالࣲ وَثَمَـٰنِیَةَ أَیَّامٍ حُسُومࣰاۖ فَتَرَى ٱلۡقَوۡمَ فِیهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِیَةࣲ',
    'سخرها عليهم سبع ليال وثمانية ايام حسوما فترى القوم فيها صرعى كانهم اعجاز نخل خاوية',
    'سَخَّرَهَا عَلَيۡهِمۡ سَ<rule class=qalaqah>بۡ</rule>عَ لَيَا<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َثَمَ<rule class=madda_normal>ـٰ</rule>نِيَةَ أَيَّامٍ حُسُو<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ف</rule>َتَرَى <rule class=ham_wasl>ٱ</rule>لۡقَوۡمَ فِيهَا صَرۡعَىٰ كَأَ<rule class=ghunnah>نّ</rule>َهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِيَةٍ ٧',
    7, 29, 7, 566, 500, 227, 'false'
  );
  
  -- Ayah 8 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5331,
    'فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِیَةࣲ',
    'فهل ترى لهم من باقية',
    'فَهَلۡ تَرَىٰ لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َاقِيَةٍ ٨',
    8, 29, 7, 566, 500, 227, 'false'
  );
  
  -- Ayah 9 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5332,
    'وَجَاۤءَ فِرۡعَوۡنُ وَمَن قَبۡلَهُۥ وَٱلۡمُؤۡتَفِكَـٰتُ بِٱلۡخَاطِئَةِ',
    'وجاء فرعون ومن قبله والمؤتفكات بالخاطئة',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فِرۡعَوۡنُ وَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لَهُ<rule class=madda_normal>ۥ</rule> وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡتَفِكَ<rule class=madda_normal>ـٰ</rule>تُ بِ<rule class=ham_wasl>ٱ</rule>لۡخَاطِئَةِ ٩',
    9, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 10 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5333,
    'فَعَصَوۡا۟ رَسُولَ رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَةࣰ رَّابِیَةً',
    'فعصوا رسول ربهم فاخذهم اخذة رابية',
    'فَعَصَوۡ<rule class=slnt>اۡ</rule> رَسُولَ رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَ<rule class=idgham_wo_ghunnah>ةً</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّابِيَةً ١٠',
    10, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 11 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5334,
    'إِنَّا لَمَّا طَغَا ٱلۡمَاۤءُ حَمَلۡنَـٰكُمۡ فِی ٱلۡجَارِیَةِ',
    'انا لما طغى الماء حملناكم في الجارية',
    'إِ<rule class=ghunnah>نّ</rule>َا لَ<rule class=ghunnah>مّ</rule>َا طَغَا <rule class=ham_wasl>ٱ</rule>لۡم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ حَمَلۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡجَارِيَةِ ١١',
    11, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 12 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5335,
    'لِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةࣰ وَتَعِیَهَاۤ أُذُنࣱ وَ ٰ⁠عِیَةࣱ',
    'لنجعلها لكم تذكرة وتعيها اذن واعية',
    'لِنَ<rule class=qalaqah>جۡ</rule>عَلَهَا لَكُمۡ تَذۡكِرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َتَعِيَه<rule class=madda_obligatory_monfasel>َآ</rule> أُذُ<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>عِيَةٌ ١٢',
    12, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 13 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5336,
    'فَإِذَا نُفِخَ فِی ٱلصُّورِ نَفۡخَةࣱ وَ ٰ⁠حِدَةࣱ',
    'فاذا نفخ في الصور نفخة واحدة',
    'فَإِذَا نُفِخَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّورِ نَفۡخَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَةٌ ١٣',
    13, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 14 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5337,
    'وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةࣰ وَ ٰ⁠حِدَةࣰ',
    'وحملت الارض والجبال فدكتا دكة واحدة',
    'وَحُمِلَتِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَ<rule class=ham_wasl>ٱ</rule>لۡجِبَالُ فَدُكَّتَا دَكَّ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule><rule class=madda_normal>ٰ</rule>حِدَةً ١٤',
    14, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 15 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5338,
    'فَیَوۡمَىِٕذࣲ وَقَعَتِ ٱلۡوَاقِعَةُ',
    'فيومئذ وقعت الواقعة',
    'فَيَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>و</rule>َقَعَتِ <rule class=ham_wasl>ٱ</rule>لۡوَاقِعَةُ ١٥',
    15, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 16 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5339,
    'وَٱنشَقَّتِ ٱلسَّمَاۤءُ فَهِیَ یَوۡمَىِٕذࣲ وَاهِیَةࣱ',
    'وانشقت السماء فهي يومئذ واهية',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نش</rule>َقَّتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فَهِىَ يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>و</rule>َاهِيَةٌ ١٦',
    16, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 17 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5340,
    'وَٱلۡمَلَكُ عَلَىٰۤ أَرۡجَاۤىِٕهَاۚ وَیَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ یَوۡمَىِٕذࣲ ثَمَـٰنِیَةࣱ',
    'والملك على ارجائها ويحمل عرش ربك فوقهم يومئذ ثمانية',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَكُ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَرۡج<rule class=madda_obligatory_mottasel>َا</rule>ٓئِهَا‌ۚ وَيَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ث</rule>َمَ<rule class=madda_normal>ـٰ</rule>نِيَةٌ ١٧',
    17, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 18 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5341,
    'یَوۡمَىِٕذࣲ تُعۡرَضُونَ لَا تَخۡفَىٰ مِنكُمۡ خَافِیَةࣱ',
    'يومئذ تعرضون لا تخفى منكم خافية',
    'يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ت</rule>ُعۡرَضُونَ لَا تَخۡفَىٰ مِ<rule class=ikhafa>نك</rule>ُمۡ خَافِيَةٌ ١٨',
    18, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 19 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5342,
    'فَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ بِیَمِینِهِۦ فَیَقُولُ هَاۤؤُمُ ٱقۡرَءُوا۟ كِتَـٰبِیَهۡ',
    'فاما من اوتي كتابه بيمينه فيقول هاؤم اقرءوا كتابيه',
    'فَأَ<rule class=ghunnah>مّ</rule>َا مَنۡ أُوتِىَ كِتَ<rule class=madda_normal>ـٰ</rule>بَهُ<rule class=madda_normal>ۥ</rule> بِيَمِينِه<rule class=madda_normal>ِۦ</rule> فَيَقُولُ ه<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُمُ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>رَءُو<rule class=slnt>اۡ</rule> كِتَ<rule class=madda_normal>ـٰ</rule>بِيَهۡ ١٩',
    19, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 20 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5343,
    'إِنِّی ظَنَنتُ أَنِّی مُلَـٰقٍ حِسَابِیَهۡ',
    'اني ظننت اني ملاق حسابيه',
    'إِ<rule class=ghunnah>نّ</rule>ِى ظَنَ<rule class=ikhafa>نت</rule>ُ أَ<rule class=ghunnah>نّ</rule>ِى مُلَ<rule class=madda_normal>ـٰ</rule>قٍ حِسَابِيَهۡ ٢٠',
    20, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 21 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5344,
    'فَهُوَ فِی عِیشَةࣲ رَّاضِیَةࣲ',
    'فهو في عيشة راضية',
    'فَهُوَ فِى عِيشَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّاضِيَةٍ ٢١',
    21, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 22 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5345,
    'فِی جَنَّةٍ عَالِیَةࣲ',
    'في جنة عالية',
    'فِى جَ<rule class=ghunnah>نّ</rule>َةٍ عَالِيَةٍ ٢٢',
    22, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 23 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5346,
    'قُطُوفُهَا دَانِیَةࣱ',
    'قطوفها دانية',
    'قُطُوفُهَا دَانِيَةٌ ٢٣',
    23, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 24 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5347,
    'كُلُوا۟ وَٱشۡرَبُوا۟ هَنِیۤـَٔۢا بِمَاۤ أَسۡلَفۡتُمۡ فِی ٱلۡأَیَّامِ ٱلۡخَالِیَةِ',
    'كلوا واشربوا هنيئا بما اسلفتم في الايام الخالية',
    'كُلُو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>شۡرَبُو<rule class=slnt>اۡ</rule> هَنِ<rule class=madda_obligatory_mottasel>يٓـ</rule>ـ<rule class=iqlab>ـَٔۢا</rule> <rule class=iqlab>ب</rule>ِم<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡلَفۡتُمۡ فِى <rule class=ham_wasl>ٱ</rule>لۡأَيَّامِ <rule class=ham_wasl>ٱ</rule>لۡخَالِيَةِ ٢٤',
    24, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 25 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5348,
    'وَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ بِشِمَالِهِۦ فَیَقُولُ یَـٰلَیۡتَنِی لَمۡ أُوتَ كِتَـٰبِیَهۡ',
    'واما من اوتي كتابه بشماله فيقول يا ليتني لم اوت كتابيه',
    'وَأَ<rule class=ghunnah>مّ</rule>َا مَنۡ أُوتِىَ كِتَ<rule class=madda_normal>ـٰ</rule>بَهُ<rule class=madda_normal>ۥ</rule> بِشِمَالِه<rule class=madda_normal>ِۦ</rule> فَيَقُولُ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَنِى لَمۡ أُوتَ كِتَ<rule class=madda_normal>ـٰ</rule>بِيَهۡ ٢٥',
    25, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 26 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5349,
    'وَلَمۡ أَدۡرِ مَا حِسَابِیَهۡ',
    'ولم ادر ما حسابيه',
    'وَلَمۡ أَ<rule class=qalaqah>دۡ</rule>رِ مَا حِسَابِيَهۡ ٢٦',
    26, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 27 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5350,
    'یَـٰلَیۡتَهَا كَانَتِ ٱلۡقَاضِیَةَ',
    'يا ليتها كانت القاضية',
    'يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَهَا كَانَتِ <rule class=ham_wasl>ٱ</rule>لۡقَاضِيَةَ ٢٧',
    27, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 28 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5351,
    'مَاۤ أَغۡنَىٰ عَنِّی مَالِیَهۡۜ',
    'ما اغنى عني ماليه',
    'م<rule class=madda_obligatory_monfasel>َآ</rule> أَغۡنَىٰ عَ<rule class=ghunnah>نّ</rule>ِى مَالِيَهۡۜ ٢٨',
    28, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 29 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5352,
    'هَلَكَ عَنِّی سُلۡطَـٰنِیَهۡ',
    'هلك عني سلطانيه',
    'هَلَكَ عَ<rule class=ghunnah>نّ</rule>ِى سُلۡطَ<rule class=madda_normal>ـٰ</rule>نِيَهۡ ٢٩',
    29, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 30 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5353,
    'خُذُوهُ فَغُلُّوهُ',
    'خذوه فغلوه',
    'خُذُوهُ فَغُلّ<rule class=madda_permissible>ُو</rule>هُ ٣٠',
    30, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 31 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5354,
    'ثُمَّ ٱلۡجَحِیمَ صَلُّوهُ',
    'ثم الجحيم صلوه',
    'ثُ<rule class=ghunnah>مّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡجَحِيمَ صَلّ<rule class=madda_permissible>ُو</rule>هُ ٣١',
    31, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 32 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5355,
    'ثُمَّ فِی سِلۡسِلَةࣲ ذَرۡعُهَا سَبۡعُونَ ذِرَاعࣰا فَٱسۡلُكُوهُ',
    'ثم في سلسلة ذرعها سبعون ذراعا فاسلكوه',
    'ثُ<rule class=ghunnah>مّ</rule>َ فِى سِلۡسِلَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ذ</rule>َرۡعُهَا سَ<rule class=qalaqah>بۡ</rule>عُونَ ذِرَا<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ف</rule>َ<rule class=ham_wasl>ٱ</rule>سۡلُك<rule class=madda_permissible>ُو</rule>هُ ٣٢',
    32, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 33 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5356,
    'إِنَّهُۥ كَانَ لَا یُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِیمِ',
    'انه كان لا يؤمن بالله العظيم',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ لَا يُؤۡمِنُ بِ<rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٣٣',
    33, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 34 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5357,
    'وَلَا یَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِینِ',
    'ولا يحض على طعام المسكين',
    'وَلَا يَحُضُّ عَلَىٰ طَعَامِ <rule class=ham_wasl>ٱ</rule>لۡمِسۡك<rule class=madda_permissible>ِي</rule>نِ ٣٤',
    34, 29, 7, 567, 500, 227, 'false'
  );
  
  -- Ayah 35 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5358,
    'فَلَیۡسَ لَهُ ٱلۡیَوۡمَ هَـٰهُنَا حَمِیمࣱ',
    'فليس له اليوم هاهنا حميم',
    'فَلَيۡسَ لَهُ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ هَ<rule class=madda_normal>ـٰ</rule>هُنَا حَم<rule class=madda_permissible>ِي</rule>مٌ ٣٥',
    35, 29, 7, 568, 500, 227, 'false'
  );
  
  -- Ayah 36 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5359,
    'وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِینࣲ',
    'ولا طعام الا من غسلين',
    'وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡل<rule class=madda_permissible>ِي</rule>نٍ ٣٦',
    36, 29, 7, 568, 500, 227, 'false'
  );
  
  -- Ayah 37 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5360,
    'لَّا یَأۡكُلُهُۥۤ إِلَّا ٱلۡخَـٰطِـُٔونَ',
    'لا ياكله الا الخاطئون',
    'لَّا يَأۡكُلُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا <rule class=ham_wasl>ٱ</rule>لۡخَ<rule class=madda_normal>ـٰ</rule>طِــٔ<rule class=madda_permissible>ُو</rule>نَ ٣٧',
    37, 29, 7, 568, 500, 227, 'false'
  );
  
  -- Ayah 38 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5361,
    'فَلَاۤ أُقۡسِمُ بِمَا تُبۡصِرُونَ',
    'فلا اقسم بما تبصرون',
    'فَل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=qalaqah>قۡ</rule>سِمُ بِمَا تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٣٨',
    38, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 39 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5362,
    'وَمَا لَا تُبۡصِرُونَ',
    'وما لا تبصرون',
    'وَمَا لَا تُ<rule class=qalaqah>بۡ</rule>صِر<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 40 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5363,
    'إِنَّهُۥ لَقَوۡلُ رَسُولࣲ كَرِیمࣲ',
    'انه لقول رسول كريم',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَقَوۡلُ رَسُو<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ك</rule>َر<rule class=madda_permissible>ِي</rule>مٍ ٤٠',
    40, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 41 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5364,
    'وَمَا هُوَ بِقَوۡلِ شَاعِرࣲۚ قَلِیلࣰا مَّا تُؤۡمِنُونَ',
    'وما هو بقول شاعر قليلا ما تؤمنون',
    'وَمَا هُوَ بِقَوۡلِ شَاعِ<rule class=ikhafa>رٍ‌ۚ</rule> <rule class=ikhafa>ق</rule>َلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تُؤۡمِن<rule class=madda_permissible>ُو</rule>نَ ٤١',
    41, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 42 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5365,
    'وَلَا بِقَوۡلِ كَاهِنࣲۚ قَلِیلࣰا مَّا تَذَكَّرُونَ',
    'ولا بقول كاهن قليلا ما تذكرون',
    'وَلَا بِقَوۡلِ كَاهِ<rule class=ikhafa>نٍ‌ۚ</rule> <rule class=ikhafa>ق</rule>َلِيل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>م</rule>َّا تَذَكَّر<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 43 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5366,
    'تَنزِیلࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ',
    'تنزيل من رب العالمين',
    'تَ<rule class=ikhafa>نز</rule>ِي<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٤٣',
    43, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 44 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5367,
    'وَلَوۡ تَقَوَّلَ عَلَیۡنَا بَعۡضَ ٱلۡأَقَاوِیلِ',
    'ولو تقول علينا بعض الاقاويل',
    'وَلَوۡ تَقَوَّلَ عَلَيۡنَا بَعۡضَ <rule class=ham_wasl>ٱ</rule>لۡأَقَاو<rule class=madda_permissible>ِي</rule>لِ ٤٤',
    44, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 45 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5368,
    'لَأَخَذۡنَا مِنۡهُ بِٱلۡیَمِینِ',
    'لاخذنا منه باليمين',
    'لَأَخَذۡنَا مِنۡهُ بِ<rule class=ham_wasl>ٱ</rule>لۡيَم<rule class=madda_permissible>ِي</rule>نِ ٤٥',
    45, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 46 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5369,
    'ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِینَ',
    'ثم لقطعنا منه الوتين',
    'ثُ<rule class=ghunnah>مّ</rule>َ لَقَطَعۡنَا مِنۡهُ <rule class=ham_wasl>ٱ</rule>لۡوَت<rule class=madda_permissible>ِي</rule>نَ ٤٦',
    46, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 47 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5370,
    'فَمَا مِنكُم مِّنۡ أَحَدٍ عَنۡهُ حَـٰجِزِینَ',
    'فما منكم من احد عنه حاجزين',
    'فَمَا مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ أَحَدٍ عَنۡهُ حَ<rule class=madda_normal>ـٰ</rule>جِز<rule class=madda_permissible>ِي</rule>نَ ٤٧',
    47, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 48 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5371,
    'وَإِنَّهُۥ لَتَذۡكِرَةࣱ لِّلۡمُتَّقِینَ',
    'وانه لتذكرة للمتقين',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَتَذۡكِرَ<rule class=idgham_wo_ghunnah>ةٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُتَّق<rule class=madda_permissible>ِي</rule>نَ ٤٨',
    48, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 49 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5372,
    'وَإِنَّا لَنَعۡلَمُ أَنَّ مِنكُم مُّكَذِّبِینَ',
    'وانا لنعلم ان منكم مكذبين',
    'وَإِ<rule class=ghunnah>نّ</rule>َا لَنَعۡلَمُ أَ<rule class=ghunnah>نّ</rule>َ مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ُّكَذِّب<rule class=madda_permissible>ِي</rule>نَ ٤٩',
    49, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 50 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5373,
    'وَإِنَّهُۥ لَحَسۡرَةٌ عَلَى ٱلۡكَـٰفِرِینَ',
    'وانه لحسرة على الكافرين',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَحَسۡرَةٌ عَلَى <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ِي</rule>نَ ٥٠',
    50, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 51 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5374,
    'وَإِنَّهُۥ لَحَقُّ ٱلۡیَقِینِ',
    'وانه لحق اليقين',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَحَقُّ <rule class=ham_wasl>ٱ</rule>لۡيَق<rule class=madda_permissible>ِي</rule>نِ ٥١',
    51, 29, 7, 568, 501, 227, 'false'
  );
  
  -- Ayah 52 Surah Al-Haaqqa
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    69,
    5375,
    'فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِیمِ',
    'فسبح باسم ربك العظيم',
    'فَسَبِّحۡ بِ<rule class=ham_wasl>ٱ</rule>سۡمِ رَبِّكَ <rule class=ham_wasl>ٱ</rule>لۡعَظ<rule class=madda_permissible>ِي</rule>مِ ٥٢',
    52, 29, 7, 568, 501, 227, 'false'
  );
  

-- Surah Al-Maaarij
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (70, 'سُورَةُ المَعَارِجِ', 'Al-Maaarij', 'The Ascending Stairways', 'Meccan', 44);

  -- Ayah 1 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5376,
    'سَأَلَ سَاۤىِٕلُۢ بِعَذَابࣲ وَاقِعࣲ',
    'سال سائل بعذاب واقع',
    'سَأَلَ س<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=iqlab>لُۢ</rule> <rule class=iqlab>ب</rule>ِعَذَا<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َاقِعٍ ١',
    1, 29, 7, 568, 502, 227, 'false'
  );
  
  -- Ayah 2 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5377,
    'لِّلۡكَـٰفِرِینَ لَیۡسَ لَهُۥ دَافِعࣱ',
    'للكافرين ليس له دافع',
    'لِّلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ لَيۡسَ لَهُ<rule class=madda_normal>ۥ</rule> دَافِعٌ ٢',
    2, 29, 7, 568, 502, 227, 'false'
  );
  
  -- Ayah 3 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5378,
    'مِّنَ ٱللَّهِ ذِی ٱلۡمَعَارِجِ',
    'من الله ذي المعارج',
    'مِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ ذِى <rule class=ham_wasl>ٱ</rule>لۡمَعَارِ<rule class=qalaqah>ج</rule>ِ ٣',
    3, 29, 7, 568, 502, 227, 'false'
  );
  
  -- Ayah 4 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5379,
    'تَعۡرُجُ ٱلۡمَلَـٰۤىِٕكَةُ وَٱلرُّوحُ إِلَیۡهِ فِی یَوۡمࣲ كَانَ مِقۡدَارُهُۥ خَمۡسِینَ أَلۡفَ سَنَةࣲ',
    'تعرج الملائكة والروح اليه في يوم كان مقداره خمسين الف سنة',
    'تَعۡرُجُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّوحُ إِلَيۡهِ فِى يَوۡ<rule class=ikhafa>مٍ</rule> <rule class=ikhafa>ك</rule>َانَ مِ<rule class=qalaqah>قۡ</rule>دَارُهُ<rule class=madda_normal>ۥ</rule> خَمۡسِينَ أَلۡفَ سَنَةٍ ٤',
    4, 29, 7, 568, 502, 227, 'false'
  );
  
  -- Ayah 5 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5380,
    'فَٱصۡبِرۡ صَبۡرࣰا جَمِیلًا',
    'فاصبر صبرا جميلا',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ صَ<rule class=qalaqah>بۡ</rule><rule class=ikhafa>رًا</rule> <rule class=ikhafa>ج</rule>َمِيلاً ٥',
    5, 29, 7, 568, 502, 227, 'false'
  );
  
  -- Ayah 6 Surah Al-Maaarij
