  VALUES (
    70,
    5400,
    'لِّلسَّاۤىِٕلِ وَٱلۡمَحۡرُومِ',
    'للسائل والمحروم',
    'لِّلسّ<rule class=madda_obligatory_mottasel>َا</rule>ٓئِلِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَحۡر<rule class=madda_permissible>ُو</rule>مِ ٢٥',
    25, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 26 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5401,
    'وَٱلَّذِینَ یُصَدِّقُونَ بِیَوۡمِ ٱلدِّینِ',
    'والذين يصدقون بيوم الدين',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ يُصَدِّقُونَ بِيَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ٢٦',
    26, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 27 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5402,
    'وَٱلَّذِینَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ',
    'والذين هم من عذاب ربهم مشفقون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ عَذَابِ رَبِّه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّشۡفِق<rule class=madda_permissible>ُو</rule>نَ ٢٧',
    27, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 28 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5403,
