    'ان عذاب ربهم غير مامون',
    'إِ<rule class=ghunnah>نّ</rule>َ عَذَابَ رَبِّهِمۡ غَيۡرُ مَأۡم<rule class=madda_permissible>ُو</rule>نٍ ٢٨',
    28, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 29 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5404,
    'وَٱلَّذِینَ هُمۡ لِفُرُوجِهِمۡ حَـٰفِظُونَ',
    'والذين هم لفروجهم حافظون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 30 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5405,
    'إِلَّا عَلَىٰۤ أَزۡوَ ٰ⁠جِهِمۡ أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ فَإِنَّهُمۡ غَیۡرُ مَلُومِینَ',
    'الا على ازواجهم او ما ملكت ايمانهم فانهم غير ملومين',
    'إِلَّا عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَزۡو<rule class=madda_normal>ٰ</rule>جِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَ<rule class=madda_normal>ـٰ</rule>نُهُمۡ فَإِ<rule class=ghunnah>نّ</rule>َهُمۡ غَيۡرُ مَلُوم<rule class=madda_permissible>ِي</rule>نَ ٣٠',
    30, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 31 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5406,
    'فَمَنِ ٱبۡتَغَىٰ وَرَاۤءَ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡعَادُونَ',
    'فمن ابتغى وراء ذلك فاولئك هم العادون',
    'فَمَنِ <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَغَىٰ وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ذ<rule class=madda_normal>ٰ</rule>لِكَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمُ <rule class=ham_wasl>ٱ</rule>لۡعَاد<rule class=madda_permissible>ُو</rule>نَ ٣١',
    31, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 32 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5407,
    'وَٱلَّذِینَ هُمۡ لِأَمَـٰنَـٰتِهِمۡ وَعَهۡدِهِمۡ رَ ٰ⁠عُونَ',
    'والذين هم لاماناتهم وعهدهم راعون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ لِأَمَ<rule class=madda_normal>ـٰ</rule>نَ<rule class=madda_normal>ـٰ</rule>تِهِمۡ وَعَهۡدِهِمۡ ر<rule class=madda_normal>ٰ</rule>ع<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 33 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5408,
    'وَٱلَّذِینَ هُم بِشَهَـٰدَ ٰ⁠تِهِمۡ قَاۤىِٕمُونَ',
    'والذين هم بشهاداتهم قائمون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِشَهَ<rule class=madda_normal>ـٰ</rule>د<rule class=madda_normal>ٰ</rule>تِهِمۡ ق<rule class=madda_obligatory_mottasel>َا</rule>ٓئِم<rule class=madda_permissible>ُو</rule>نَ ٣٣',
    33, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 34 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5409,
    'وَٱلَّذِینَ هُمۡ عَلَىٰ صَلَاتِهِمۡ یُحَافِظُونَ',
    'والذين هم على صلاتهم يحافظون',
    'وَ<rule class=ham_wasl>ٱ</rule>لَّذِينَ هُمۡ عَلَىٰ صَلَاتِهِمۡ يُحَافِظ<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 35 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5410,
    'أُو۟لَـٰۤىِٕكَ فِی جَنَّـٰتࣲ مُّكۡرَمُونَ',
    'اولئك في جنات مكرمون',
    'أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ فِى جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّكۡرَم<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 29, 7, 569, 502, 228, 'false'
  );
  
  -- Ayah 36 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5411,
    'فَمَالِ ٱلَّذِینَ كَفَرُوا۟ قِبَلَكَ مُهۡطِعِینَ',
    'فمال الذين كفروا قبلك مهطعين',
    'فَمَالِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> قِبَلَكَ مُهۡطِع<rule class=madda_permissible>ِي</rule>نَ ٣٦',
    36, 29, 7, 569, 503, 228, 'false'
  );
  
  -- Ayah 37 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5412,
    'عَنِ ٱلۡیَمِینِ وَعَنِ ٱلشِّمَالِ عِزِینَ',
    'عن اليمين وعن الشمال عزين',
    'عَنِ <rule class=ham_wasl>ٱ</rule>لۡيَمِينِ وَعَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شِّمَالِ عِز<rule class=madda_permissible>ِي</rule>نَ ٣٧',
    37, 29, 7, 569, 503, 228, 'false'
  );
  
  -- Ayah 38 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5413,
    'أَیَطۡمَعُ كُلُّ ٱمۡرِئࣲ مِّنۡهُمۡ أَن یُدۡخَلَ جَنَّةَ نَعِیمࣲ',
    'ايطمع كل امرئ منهم ان يدخل جنة نعيم',
    'أَيَ<rule class=qalaqah>طۡ</rule>مَعُ كُلُّ <rule class=ham_wasl>ٱ</rule>مۡرِى<rule class=idgham_ghunnah>ٍٕ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُ<rule class=qalaqah>دۡ</rule>خَلَ جَ<rule class=ghunnah>نّ</rule>َةَ نَع<rule class=madda_permissible>ِي</rule>مٍ ٣٨',
    38, 29, 7, 569, 503, 228, 'false'
  );
  
  -- Ayah 39 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5414,
    'كَلَّاۤۖ إِنَّا خَلَقۡنَـٰهُم مِّمَّا یَعۡلَمُونَ',
    'كلا انا خلقناهم مما يعلمون',
    'كَلّ<rule class=madda_obligatory_monfasel>َآ‌ۖ</rule> إِ<rule class=ghunnah>نّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ghunnah>مّ</rule>َا يَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٣٩',
    39, 29, 7, 569, 503, 228, 'false'
  );
  
  -- Ayah 40 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5415,
    'فَلَاۤ أُقۡسِمُ بِرَبِّ ٱلۡمَشَـٰرِقِ وَٱلۡمَغَـٰرِبِ إِنَّا لَقَـٰدِرُونَ',
    'فلا اقسم برب المشارق والمغارب انا لقادرون',
    'فَل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=qalaqah>قۡ</rule>سِمُ بِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡمَشَ<rule class=madda_normal>ـٰ</rule>رِقِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَغَ<rule class=madda_normal>ـٰ</rule>رِبِ إِ<rule class=ghunnah>نّ</rule>َا لَقَ<rule class=madda_normal>ـٰ</rule>دِر<rule class=madda_permissible>ُو</rule>نَ ٤٠',
    40, 29, 7, 570, 503, 228, 'false'
  );
  
  -- Ayah 41 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5416,
    'عَلَىٰۤ أَن نُّبَدِّلَ خَیۡرࣰا مِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوقِینَ',
    'على ان نبدل خيرا منهم وما نحن بمسبوقين',
    'عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّبَدِّلَ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوق<rule class=madda_permissible>ِي</rule>نَ ٤١',
    41, 29, 7, 570, 503, 228, 'false'
  );
  
  -- Ayah 42 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5417,
    'فَذَرۡهُمۡ یَخُوضُوا۟ وَیَلۡعَبُوا۟ حَتَّىٰ یُلَـٰقُوا۟ یَوۡمَهُمُ ٱلَّذِی یُوعَدُونَ',
    'فذرهم يخوضوا ويلعبوا حتى يلاقوا يومهم الذي يوعدون',
    'فَذَرۡهُمۡ يَخُوضُو<rule class=slnt>اۡ</rule> وَيَلۡعَبُو<rule class=slnt>اۡ</rule> حَتَّىٰ يُلَ<rule class=madda_normal>ـٰ</rule>قُو<rule class=slnt>اۡ</rule> يَوۡمَهُمُ <rule class=ham_wasl>ٱ</rule>لَّذِى يُوعَد<rule class=madda_permissible>ُو</rule>نَ ٤٢',
    42, 29, 7, 570, 503, 228, 'false'
  );
  
  -- Ayah 43 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5418,
    'یَوۡمَ یَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ سِرَاعࣰا كَأَنَّهُمۡ إِلَىٰ نُصُبࣲ یُوفِضُونَ',
    'يوم يخرجون من الاجداث سراعا كانهم الى نصب يوفضون',
    'يَوۡمَ يَخۡرُجُونَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>جۡ</rule>دَاثِ سِرَا<rule class=ikhafa>عًا</rule> <rule class=ikhafa>ك</rule>َأَ<rule class=ghunnah>نّ</rule>َهُمۡ إِلَىٰ نُصُ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>ي</rule>ُوفِض<rule class=madda_permissible>ُو</rule>نَ ٤٣',
    43, 29, 7, 570, 503, 228, 'false'
  );
  
  -- Ayah 44 Surah Al-Maaarij
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    70,
    5419,
    'خَـٰشِعَةً أَبۡصَـٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةࣱۚ ذَ ٰ⁠لِكَ ٱلۡیَوۡمُ ٱلَّذِی كَانُوا۟ یُوعَدُونَ',
    'خاشعة ابصارهم ترهقهم ذلة ذلك اليوم الذي كانوا يوعدون',
    'خَ<rule class=madda_normal>ـٰ</rule>شِعَةً أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُهُمۡ تَرۡهَقُهُمۡ ذِلَّ<rule class=ikhafa>ةٌ‌ۚ</rule> <rule class=ikhafa>ذ</rule><rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمُ <rule class=ham_wasl>ٱ</rule>لَّذِى كَانُو<rule class=slnt>اۡ</rule> يُوعَد<rule class=madda_permissible>ُو</rule>نَ ٤٤',
    44, 29, 7, 570, 503, 228, 'false'
  );
  

-- Surah Nooh
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (71, 'سُورَةُ نُوحٍ', 'Nooh', 'Noah', 'Meccan', 28);

  -- Ayah 1 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5420,
    'إِنَّاۤ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦۤ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن یَأۡتِیَهُمۡ عَذَابٌ أَلِیمࣱ',
    'انا ارسلنا نوحا الى قومه ان انذر قومك من قبل ان ياتيهم عذاب اليم',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَنۡ أَ<rule class=ikhafa>نذ</rule>ِرۡ قَوۡمَكَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>بۡ</rule>لِ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َأۡتِيَهُمۡ عَذَابٌ أَل<rule class=madda_permissible>ِي</rule>مٌ ١',
    1, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 2 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5421,
    'قَالَ یَـٰقَوۡمِ إِنِّی لَكُمۡ نَذِیرࣱ مُّبِینٌ',
    'قال يا قوم اني لكم نذير مبين',
    'قَالَ يَ<rule class=madda_normal>ـٰ</rule>قَوۡمِ إِ<rule class=ghunnah>نّ</rule>ِى لَكُمۡ نَذِي<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّب<rule class=madda_permissible>ِي</rule>نٌ ٢',
    2, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 3 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5422,
    'أَنِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِیعُونِ',
    'ان اعبدوا الله واتقوه واطيعون',
    'أَنِ <rule class=ham_wasl>ٱ</rule>عۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ وَ<rule class=ham_wasl>ٱ</rule>تَّقُوهُ وَأَطِيع<rule class=madda_permissible>ُو</rule>نِ ٣',
    3, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 4 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5423,
    'یَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَیُؤَخِّرۡكُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَاۤءَ لَا یُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ',
    'يغفر لكم من ذنوبكم ويؤخركم الى اجل مسمى ان اجل الله اذا جاء لا يؤخر لو كنتم تعلمون',
    'يَغۡفِرۡ لَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ُنُوبِكُمۡ وَيُؤَخِّرۡكُمۡ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَجَ<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّسَ<rule class=ghunnah>مّ</rule>ًى‌ۚ إِ<rule class=ghunnah>نّ</rule>َ أَجَلَ <rule class=ham_wasl>ٱ</rule>للَّهِ إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ لَا يُؤَخَّرُ‌ۖ لَوۡ كُ<rule class=ikhafa>نت</rule>ُمۡ تَعۡلَم<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 5 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5424,
    'قَالَ رَبِّ إِنِّی دَعَوۡتُ قَوۡمِی لَیۡلࣰا وَنَهَارࣰا',
    'قال رب اني دعوت قومي ليلا ونهارا',
    'قَالَ رَبِّ إِ<rule class=ghunnah>نّ</rule>ِى دَعَوۡتُ قَوۡمِى لَيۡل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َنَهَارًا ٥',
    5, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 6 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5425,
    'فَلَمۡ یَزِدۡهُمۡ دُعَاۤءِیۤ إِلَّا فِرَارࣰا',
    'فلم يزدهم دعائي الا فرارا',
    'فَلَمۡ يَزِ<rule class=qalaqah>دۡ</rule>هُمۡ دُع<rule class=madda_obligatory_mottasel>َا</rule>ٓء<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَّا فِرَارًا ٦',
    6, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 7 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5426,
    'وَإِنِّی كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوۤا۟ أَصَـٰبِعَهُمۡ فِیۤ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡا۟ ثِیَابَهُمۡ وَأَصَرُّوا۟ وَٱسۡتَكۡبَرُوا۟ ٱسۡتِكۡبَارࣰا',
    'واني كلما دعوتهم لتغفر لهم جعلوا اصابعهم في اذانهم واستغشوا ثيابهم واصروا واستكبروا استكبارا',
    'وَإِ<rule class=ghunnah>نّ</rule>ِى كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَل<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَصَ<rule class=madda_normal>ـٰ</rule>بِعَهُمۡ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> ءَاذَانِهِمۡ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡشَوۡ<rule class=slnt>اۡ</rule> ثِيَابَهُمۡ وَأَصَرُّو<rule class=slnt>اۡ</rule> وَ<rule class=ham_wasl>ٱ</rule>سۡتَكۡبَرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>سۡتِكۡبَارًا ٧',
    7, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 8 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5427,
    'ثُمَّ إِنِّی دَعَوۡتُهُمۡ جِهَارࣰا',
    'ثم اني دعوتهم جهارا',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>ِى دَعَوۡتُهُمۡ جِهَارًا ٨',
    8, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 9 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5428,
    'ثُمَّ إِنِّیۤ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارࣰا',
    'ثم اني اعلنت لهم واسررت لهم اسرارا',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>ِىٓ</rule> أَعۡلَ<rule class=ikhafa>نت</rule>ُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارًا ٩',
    9, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 10 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5429,
    'فَقُلۡتُ ٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارࣰا',
    'فقلت استغفروا ربكم انه كان غفارا',
    'فَقُلۡتُ <rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرُو<rule class=slnt>اۡ</rule> رَبَّكُمۡ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ غَفَّارًا ١٠',
    10, 29, 7, 570, 504, 228, 'false'
  );
  
  -- Ayah 11 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5430,
    'یُرۡسِلِ ٱلسَّمَاۤءَ عَلَیۡكُم مِّدۡرَارࣰا',
    'يرسل السماء عليكم مدرارا',
    'يُرۡسِلِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ عَلَيۡك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=qalaqah>دۡ</rule>رَارًا ١١',
    11, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 12 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5431,
    'وَیُمۡدِدۡكُم بِأَمۡوَ ٰ⁠لࣲ وَبَنِینَ وَیَجۡعَل لَّكُمۡ جَنَّـٰتࣲ وَیَجۡعَل لَّكُمۡ أَنۡهَـٰرࣰا',
    'ويمددكم باموال وبنين ويجعل لكم جنات ويجعل لكم انهارا',
    'وَيُمۡدِ<rule class=qalaqah>دۡ</rule>ك<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَمۡو<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>و</rule>َبَنِينَ وَيَ<rule class=qalaqah>جۡ</rule>عَل لَّكُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>تٍ</rule> <rule class=idgham_ghunnah>و</rule>َيَ<rule class=qalaqah>جۡ</rule>عَل لَّكُمۡ أَنۡهَ<rule class=madda_normal>ـٰ</rule>رًا ١٢',
    12, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 13 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5432,
    'مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارࣰا',
    'ما لكم لا ترجون لله وقارا',
    'مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارًا ١٣',
    13, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 14 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5433,
    'وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا',
    'وقد خلقكم اطوارا',
    'وَقَ<rule class=qalaqah>دۡ</rule> خَلَقَكُمۡ أَ<rule class=qalaqah>طۡ</rule>وَارًا ١٤',
    14, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 15 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5434,
    'أَلَمۡ تَرَوۡا۟ كَیۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ طِبَاقࣰا',
    'الم تروا كيف خلق الله سبع سماوات طباقا',
    'أَلَمۡ تَرَوۡ<rule class=slnt>اۡ</rule> كَيۡفَ خَلَقَ <rule class=ham_wasl>ٱ</rule>للَّهُ سَ<rule class=qalaqah>بۡ</rule>عَ سَمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule><rule class=ikhafa>تٍ</rule> <rule class=ikhafa>ط</rule>ِبَاقًا ١٥',
    15, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 16 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5435,
    'وَجَعَلَ ٱلۡقَمَرَ فِیهِنَّ نُورࣰا وَجَعَلَ ٱلشَّمۡسَ سِرَاجࣰا',
    'وجعل القمر فيهن نورا وجعل الشمس سراجا',
    'وَجَعَلَ <rule class=ham_wasl>ٱ</rule>لۡقَمَرَ فِيهِ<rule class=ghunnah>نّ</rule>َ نُو<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َجَعَلَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شَّمۡسَ سِرَاجًا ١٦',
    16, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 17 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5436,
    'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتࣰا',
    'والله انبتكم من الارض نباتا',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ أَ<rule class=iqlab>نۢب</rule>َتَك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ نَبَاتًا ١٧',
    17, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 18 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5437,
    'ثُمَّ یُعِیدُكُمۡ فِیهَا وَیُخۡرِجُكُمۡ إِخۡرَاجࣰا',
    'ثم يعيدكم فيها ويخرجكم اخراجا',
    'ثُ<rule class=ghunnah>مّ</rule>َ يُعِيدُكُمۡ فِيهَا وَيُخۡرِجُكُمۡ إِخۡرَاجًا ١٨',
    18, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 19 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5438,
    'وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطࣰا',
    'والله جعل لكم الارض بساطا',
    'وَ<rule class=ham_wasl>ٱ</rule>للَّهُ جَعَلَ لَكُمُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضَ بِسَاطًا ١٩',
    19, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 20 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5439,
    'لِّتَسۡلُكُوا۟ مِنۡهَا سُبُلࣰا فِجَاجࣰا',
    'لتسلكوا منها سبلا فجاجا',
    'لِّتَسۡلُكُو<rule class=slnt>اۡ</rule> مِنۡهَا سُبُل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ف</rule>ِجَاجًا ٢٠',
    20, 29, 7, 571, 504, 228, 'false'
  );
  
  -- Ayah 21 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5440,
    'قَالَ نُوحࣱ رَّبِّ إِنَّهُمۡ عَصَوۡنِی وَٱتَّبَعُوا۟ مَن لَّمۡ یَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥۤ إِلَّا خَسَارࣰا',
    'قال نوح رب انهم عصوني واتبعوا من لم يزده ماله وولده الا خسارا',
    'قَالَ نُو<rule class=idgham_wo_ghunnah>حٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ إِ<rule class=ghunnah>نّ</rule>َهُمۡ عَصَوۡنِى وَ<rule class=ham_wasl>ٱ</rule>تَّبَعُو<rule class=slnt>اۡ</rule> م<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَزِ<rule class=qalaqah>دۡ</rule>هُ مَالُهُ<rule class=madda_normal>ۥ</rule> وَوَلَدُهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> إِلَّا خَسَارًا ٢١',
    21, 29, 7, 571, 505, 228, 'false'
  );
  
  -- Ayah 22 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5441,
    'وَمَكَرُوا۟ مَكۡرࣰا كُبَّارࣰا',
    'ومكروا مكرا كبارا',
    'وَمَكَرُو<rule class=slnt>اۡ</rule> مَكۡ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>ُبَّارًا ٢٢',
    22, 29, 7, 571, 505, 228, 'false'
  );
  
  -- Ayah 23 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5442,
    'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدࣰّا وَلَا سُوَاعࣰا وَلَا یَغُوثَ وَیَعُوقَ وَنَسۡرࣰا',
    'وقالوا لا تذرن الهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا',
    'وَقَالُو<rule class=slnt>اۡ</rule> لَا تَذَرُ<rule class=ghunnah>نّ</rule>َ ءَالِهَتَكُمۡ وَلَا تَذَرُ<rule class=ghunnah>نّ</rule>َ وَد<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا سُوَا<rule class=idgham_ghunnah>عًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا يَغُوثَ وَيَعُوقَ وَنَسۡرًا ٢٣',
    23, 29, 7, 571, 505, 228, 'false'
  );
  
  -- Ayah 24 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5443,
    'وَقَدۡ أَضَلُّوا۟ كَثِیرࣰاۖ وَلَا تَزِدِ ٱلظَّـٰلِمِینَ إِلَّا ضَلَـٰلࣰا',
    'وقد اضلوا كثيرا ولا تزد الظالمين الا ضلالا',
    'وَقَ<rule class=qalaqah>دۡ</rule> أَضَلُّو<rule class=slnt>اۡ</rule> كَثِي<rule class=idgham_ghunnah>رًا‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َلَا تَزِدِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ إِلَّا ضَلَ<rule class=madda_normal>ـٰ</rule>لاً ٢٤',
    24, 29, 7, 571, 505, 228, 'false'
  );
  
  -- Ayah 25 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5444,
    'مِّمَّا خَطِیۤـَٔـٰتِهِمۡ أُغۡرِقُوا۟ فَأُدۡخِلُوا۟ نَارࣰا فَلَمۡ یَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارࣰا',
    'مما خطيئاتهم اغرقوا فادخلوا نارا فلم يجدوا لهم من دون الله انصارا',
    'مِّ<rule class=ghunnah>مّ</rule>َا خَط<rule class=madda_obligatory_mottasel>ِيٓ</rule>ـَٔ<rule class=madda_normal>ـٰ</rule>تِهِمۡ أُغۡرِقُو<rule class=slnt>اۡ</rule> فَأُ<rule class=qalaqah>دۡ</rule>خِلُو<rule class=slnt>اۡ</rule> نَا<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ف</rule>َلَمۡ يَجِدُو<rule class=slnt>اۡ</rule> لَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَ<rule class=ikhafa>نص</rule>َارًا ٢٥',
    25, 29, 7, 571, 505, 228, 'false'
  );
  
  -- Ayah 26 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5445,
    'وَقَالَ نُوحࣱ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَـٰفِرِینَ دَیَّارًا',
    'وقال نوح رب لا تذر على الارض من الكافرين ديارا',
    'وَقَالَ نُو<rule class=idgham_wo_ghunnah>حٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّ لَا تَذَرۡ عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ مِنَ <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ دَيَّارًا ٢٦',
    26, 29, 7, 571, 505, 228, 'false'
  );
  
  -- Ayah 27 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5446,
    'إِنَّكَ إِن تَذَرۡهُمۡ یُضِلُّوا۟ عِبَادَكَ وَلَا یَلِدُوۤا۟ إِلَّا فَاجِرࣰا كَفَّارࣰا',
    'انك ان تذرهم يضلوا عبادك ولا يلدوا الا فاجرا كفارا',
    'إِ<rule class=ghunnah>نّ</rule>َكَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َذَرۡهُمۡ يُضِلُّو<rule class=slnt>اۡ</rule> عِبَادَكَ وَلَا يَلِد<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا فَاجِ<rule class=ikhafa>رًا</rule> <rule class=ikhafa>ك</rule>َفَّارًا ٢٧',
    27, 29, 7, 571, 505, 228, 'false'
  );
  
  -- Ayah 28 Surah Nooh
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    71,
    5447,
    'رَّبِّ ٱغۡفِرۡ لِی وَلِوَ ٰ⁠لِدَیَّ وَلِمَن دَخَلَ بَیۡتِیَ مُؤۡمِنࣰا وَلِلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِۖ وَلَا تَزِدِ ٱلظَّـٰلِمِینَ إِلَّا تَبَارَۢا',
    'رب اغفر لي ولوالدي ولمن دخل بيتي مؤمنا وللمؤمنين والمؤمنات ولا تزد الظالمين الا تبارا',
    'رَّبِّ <rule class=ham_wasl>ٱ</rule>غۡفِرۡ لِى وَلِو<rule class=madda_normal>ٰ</rule>لِدَىَّ وَلِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>َخَلَ بَيۡتِىَ مُؤۡمِ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َلِلۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ وَلَا تَزِدِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ إِلَّا تَبَارَۢا ٢٨',
    28, 29, 7, 571, 505, 228, 'false'
  );
  

-- Surah Al-Jinn
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (72, 'سُورَةُ الجِنِّ', 'Al-Jinn', 'The Jinn', 'Meccan', 28);

  -- Ayah 1 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5448,
    'قُلۡ أُوحِیَ إِلَیَّ أَنَّهُ ٱسۡتَمَعَ نَفَرࣱ مِّنَ ٱلۡجِنِّ فَقَالُوۤا۟ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبࣰا',
    'قل اوحي الي انه استمع نفر من الجن فقالوا انا سمعنا قرانا عجبا',
    'قُلۡ أُوحِىَ إِلَىَّ أَ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>سۡتَمَعَ نَفَ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ فَقَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َا سَمِعۡنَا قُرۡءَانًا عَجَبًا ١',
    1, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 2 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5449,
    'یَهۡدِیۤ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَاۤ أَحَدࣰا',
    'يهدي الى الرشد فامنا به ولن نشرك بربنا احدا',
    'يَهۡد<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّشۡدِ فَـَٔـامَ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_normal>ِۦ</rule>‌ۖ وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّشۡرِكَ بِرَبِّن<rule class=madda_obligatory_monfasel>َآ</rule> أَحَدًا ٢',
    2, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 3 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5450,
    'وَأَنَّهُۥ تَعَـٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَـٰحِبَةࣰ وَلَا وَلَدࣰا',
    'وانه تعالى جد ربنا ما اتخذ صاحبة ولا ولدا',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> تَعَ<rule class=madda_normal>ـٰ</rule>لَىٰ جَدُّ رَبِّنَا مَا <rule class=ham_wasl>ٱ</rule>تَّخَذَ صَ<rule class=madda_normal>ـٰ</rule>حِبَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َلَا وَلَدًا ٣',
    3, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 4 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5451,
    'وَأَنَّهُۥ كَانَ یَقُولُ سَفِیهُنَا عَلَى ٱللَّهِ شَطَطࣰا',
    'وانه كان يقول سفيهنا على الله شططا',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ يَقُولُ سَفِيهُنَا عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ شَطَطًا ٤',
    4, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 5 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5452,
    'وَأَنَّا ظَنَنَّاۤ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبࣰا',
    'وانا ظننا ان لن تقول الانس والجن على الله كذبا',
    'وَأَ<rule class=ghunnah>نّ</rule>َا ظَنَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َقُولَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ُ وَ<rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ُ عَلَى <rule class=ham_wasl>ٱ</rule>للَّهِ كَذِبًا ٥',
    5, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 6 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5453,
    'وَأَنَّهُۥ كَانَ رِجَالࣱ مِّنَ ٱلۡإِنسِ یَعُوذُونَ بِرِجَالࣲ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقࣰا',
    'وانه كان رجال من الانس يعوذون برجال من الجن فزادوهم رهقا',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ رِجَا<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>ِ يَعُوذُونَ بِرِجَا<rule class=idgham_ghunnah>لٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لۡجِ<rule class=ghunnah>نّ</rule>ِ فَزَادُوهُمۡ رَهَقًا ٦',
    6, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 7 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5454,
    'وَأَنَّهُمۡ ظَنُّوا۟ كَمَا ظَنَنتُمۡ أَن لَّن یَبۡعَثَ ٱللَّهُ أَحَدࣰا',
    'وانهم ظنوا كما ظننتم ان لن يبعث الله احدا',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُمۡ ظَ<rule class=ghunnah>نّ</rule>ُو<rule class=slnt>اۡ</rule> كَمَا ظَنَ<rule class=ikhafa>نت</rule>ُمۡ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>بۡ</rule>عَثَ <rule class=ham_wasl>ٱ</rule>للَّهُ أَحَدًا ٧',
    7, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 8 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5455,
    'وَأَنَّا لَمَسۡنَا ٱلسَّمَاۤءَ فَوَجَدۡنَـٰهَا مُلِئَتۡ حَرَسࣰا شَدِیدࣰا وَشُهُبࣰا',
    'وانا لمسنا السماء فوجدناها ملئت حرسا شديدا وشهبا',
    'وَأَ<rule class=ghunnah>نّ</rule>َا لَمَسۡنَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ فَوَجَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هَا مُلِئَتۡ حَرَ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ش</rule>َدِي<rule class=idgham_ghunnah>دًا</rule> <rule class=idgham_ghunnah>و</rule>َشُهُبًا ٨',
    8, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 9 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5456,
    'وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَـٰعِدَ لِلسَّمۡعِۖ فَمَن یَسۡتَمِعِ ٱلۡـَٔانَ یَجِدۡ لَهُۥ شِهَابࣰا رَّصَدࣰا',
    'وانا كنا نقعد منها مقاعد للسمع فمن يستمع الان يجد له شهابا رصدا',
    'وَأَ<rule class=ghunnah>نّ</rule>َا كُ<rule class=ghunnah>نّ</rule>َا نَ<rule class=qalaqah>قۡ</rule>عُدُ مِنۡهَا مَقَ<rule class=madda_normal>ـٰ</rule>عِدَ لِلسَّمۡعِ‌ۖ فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َسۡتَمِعِ <rule class=ham_wasl>ٱ</rule>لۡأَنَ يَجِ<rule class=qalaqah>دۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> شِهَا<rule class=idgham_wo_ghunnah>بًا</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّصَدًا ٩',
    9, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 10 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5457,
    'وَأَنَّا لَا نَدۡرِیۤ أَشَرٌّ أُرِیدَ بِمَن فِی ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدࣰا',
    'وانا لا ندري اشر اريد بمن في الارض ام اراد بهم ربهم رشدا',
    'وَأَ<rule class=ghunnah>نّ</rule>َا لَا نَ<rule class=qalaqah>دۡ</rule>ر<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَشَرٌّ أُرِيدَ بِمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدًا ١٠',
    10, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 11 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5458,
    'وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَ ٰ⁠لِكَۖ كُنَّا طَرَاۤىِٕقَ قِدَدࣰا',
    'وانا منا الصالحون ومنا دون ذلك كنا طرائق قددا',
    'وَأَ<rule class=ghunnah>نّ</rule>َا مِ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحُونَ وَمِ<rule class=ghunnah>نّ</rule>َا دُونَ ذ<rule class=madda_normal>ٰ</rule>لِكَ‌ۖ كُ<rule class=ghunnah>نّ</rule>َا طَر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِقَ قِدَدًا ١١',
    11, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 12 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5459,
    'وَأَنَّا ظَنَنَّاۤ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِی ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبࣰا',
    'وانا ظننا ان لن نعجز الله في الارض ولن نعجزه هربا',
    'وَأَ<rule class=ghunnah>نّ</rule>َا ظَنَ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّعۡجِزَ <rule class=ham_wasl>ٱ</rule>للَّهَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>ُّعۡجِزَهُ<rule class=madda_normal>ۥ</rule> هَرَبًا ١٢',
    12, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 13 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5460,
    'وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰۤ ءَامَنَّا بِهِۦۖ فَمَن یُؤۡمِنۢ بِرَبِّهِۦ فَلَا یَخَافُ بَخۡسࣰا وَلَا رَهَقࣰا',
    'وانا لما سمعنا الهدى امنا به فمن يؤمن بربه فلا يخاف بخسا ولا رهقا',
    'وَأَ<rule class=ghunnah>نّ</rule>َا لَ<rule class=ghunnah>مّ</rule>َا سَمِعۡنَا <rule class=ham_wasl>ٱ</rule>لۡهُدَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> ءَامَ<rule class=ghunnah>نّ</rule>َا بِه<rule class=madda_normal>ِۦ</rule>‌ۖ فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡم<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>ِرَبِّه<rule class=madda_normal>ِۦ</rule> فَلَا يَخَافُ بَخۡ<rule class=idgham_ghunnah>سًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا رَهَقًا ١٣',
    13, 29, 7, 572, 506, 229, 'false'
  );
  
  -- Ayah 14 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5461,
    'وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَـٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُو۟لَـٰۤىِٕكَ تَحَرَّوۡا۟ رَشَدࣰا',
    'وانا منا المسلمون ومنا القاسطون فمن اسلم فاولئك تحروا رشدا',
    'وَأَ<rule class=ghunnah>نّ</rule>َا مِ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡمُسۡلِمُونَ وَمِ<rule class=ghunnah>نّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>سِطُونَ‌ۖ فَمَنۡ أَسۡلَمَ فَأُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ تَحَرَّوۡ<rule class=slnt>اۡ</rule> رَشَدًا ١٤',
    14, 29, 7, 573, 506, 229, 'false'
  );
  
  -- Ayah 15 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5462,
    'وَأَمَّا ٱلۡقَـٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبࣰا',
    'واما القاسطون فكانوا لجهنم حطبا',
    'وَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=madda_normal>ـٰ</rule>سِطُونَ فَكَانُو<rule class=slnt>اۡ</rule> لِجَهَ<rule class=ghunnah>نّ</rule>َمَ حَطَبًا ١٥',
    15, 29, 7, 573, 506, 229, 'false'
  );
  
  -- Ayah 16 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5463,
    'وَأَلَّوِ ٱسۡتَقَـٰمُوا۟ عَلَى ٱلطَّرِیقَةِ لَأَسۡقَیۡنَـٰهُم مَّاۤءً غَدَقࣰا',
    'وان لو استقاموا على الطريقة لاسقيناهم ماء غدقا',
    'وَأَلَّوِ <rule class=ham_wasl>ٱ</rule>سۡتَقَ<rule class=madda_normal>ـٰ</rule>مُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّرِيقَةِ لَأَسۡقَيۡنَ<rule class=madda_normal>ـٰ</rule>ه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ّ<rule class=madda_obligatory_mottasel>َا</rule>ٓءً غَدَقًا ١٦',
    16, 29, 7, 573, 506, 229, 'false'
  );
  
  -- Ayah 17 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5464,
    'لِّنَفۡتِنَهُمۡ فِیهِۚ وَمَن یُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ یَسۡلُكۡهُ عَذَابࣰا صَعَدࣰا',
    'لنفتنهم فيه ومن يعرض عن ذكر ربه يسلكه عذابا صعدا',
    'لِّنَفۡتِنَهُمۡ فِيهِ‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُعۡرِضۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ذ</rule>ِكۡرِ رَبِّه<rule class=madda_normal>ِۦ</rule> يَسۡلُكۡهُ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ص</rule>َعَدًا ١٧',
    17, 29, 7, 573, 506, 229, 'false'
  );
  
  -- Ayah 18 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5465,
    'وَأَنَّ ٱلۡمَسَـٰجِدَ لِلَّهِ فَلَا تَدۡعُوا۟ مَعَ ٱللَّهِ أَحَدࣰا',
    'وان المساجد لله فلا تدعوا مع الله احدا',
    'وَأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡمَسَ<rule class=madda_normal>ـٰ</rule>جِدَ لِلَّهِ فَلَا تَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> مَعَ <rule class=ham_wasl>ٱ</rule>للَّهِ أَحَدًا ١٨',
    18, 29, 7, 573, 506, 229, 'false'
  );
  
  -- Ayah 19 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5466,
    'وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ یَدۡعُوهُ كَادُوا۟ یَكُونُونَ عَلَیۡهِ لِبَدࣰا',
    'وانه لما قام عبد الله يدعوه كادوا يكونون عليه لبدا',
    'وَأَ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لَ<rule class=ghunnah>مّ</rule>َا قَامَ عَ<rule class=qalaqah>بۡ</rule>دُ <rule class=ham_wasl>ٱ</rule>للَّهِ يَ<rule class=qalaqah>دۡ</rule>عُوهُ كَادُو<rule class=slnt>اۡ</rule> يَكُونُونَ عَلَيۡهِ لِبَدًا ١٩',
    19, 29, 7, 573, 506, 229, 'false'
  );
  
  -- Ayah 20 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5467,
    'قُلۡ إِنَّمَاۤ أَدۡعُوا۟ رَبِّی وَلَاۤ أُشۡرِكُ بِهِۦۤ أَحَدࣰا',
    'قل انما ادعو ربي ولا اشرك به احدا',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>َم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>عُو<rule class=slnt>اۡ</rule> رَبِّى وَل<rule class=madda_obligatory_monfasel>َآ</rule> أُشۡرِكُ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَحَدًا ٢٠',
    20, 29, 7, 573, 507, 229, 'false'
  );
  
  -- Ayah 21 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5468,
    'قُلۡ إِنِّی لَاۤ أَمۡلِكُ لَكُمۡ ضَرࣰّا وَلَا رَشَدࣰا',
    'قل اني لا املك لكم ضرا ولا رشدا',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>ِى ل<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡلِكُ لَكُمۡ ضَر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>و</rule>َلَا رَشَدًا ٢١',
    21, 29, 7, 573, 507, 229, 'false'
  );
  
  -- Ayah 22 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5469,
    'قُلۡ إِنِّی لَن یُجِیرَنِی مِنَ ٱللَّهِ أَحَدࣱ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا',
    'قل اني لن يجيرني من الله احد ولن اجد من دونه ملتحدا',
    'قُلۡ إِ<rule class=ghunnah>نّ</rule>ِى ل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُجِيرَنِى مِنَ <rule class=ham_wasl>ٱ</rule>للَّهِ أَحَ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>و</rule>َلَنۡ أَجِدَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>ُونِه<rule class=madda_normal>ِۦ</rule> مُلۡتَحَدًا ٢٢',
    22, 29, 7, 573, 507, 229, 'false'
  );
  
  -- Ayah 23 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5470,
    'إِلَّا بَلَـٰغࣰا مِّنَ ٱللَّهِ وَرِسَـٰلَـٰتِهِۦۚ وَمَن یَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۤ أَبَدًا',
    'الا بلاغا من الله ورسالاته ومن يعص الله ورسوله فان له نار جهنم خالدين فيها ابدا',
    'إِلَّا بَلَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>غًا</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ وَرِسَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡصِ <rule class=ham_wasl>ٱ</rule>للَّهَ وَرَسُولَهُ<rule class=madda_normal>ۥ</rule> فَإِ<rule class=ghunnah>نّ</rule>َ لَهُ<rule class=madda_normal>ۥ</rule> نَارَ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَدًا ٢٣',
    23, 29, 7, 573, 507, 229, 'false'
  );
  
  -- Ayah 24 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5471,
    'حَتَّىٰۤ إِذَا رَأَوۡا۟ مَا یُوعَدُونَ فَسَیَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرࣰا وَأَقَلُّ عَدَدࣰا',
    'حتى اذا راوا ما يوعدون فسيعلمون من اضعف ناصرا واقل عددا',
    'حَتَّ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> إِذَا رَأَوۡ<rule class=slnt>اۡ</rule> مَا يُوعَدُونَ فَسَيَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َأَقَلُّ عَدَدًا ٢٤',
    24, 29, 7, 573, 507, 229, 'false'
  );
  
  -- Ayah 25 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5472,
    'قُلۡ إِنۡ أَدۡرِیۤ أَقَرِیبࣱ مَّا تُوعَدُونَ أَمۡ یَجۡعَلُ لَهُۥ رَبِّیۤ أَمَدًا',
    'قل ان ادري اقريب ما توعدون ام يجعل له ربي امدا',
    'قُلۡ إِنۡ أَ<rule class=qalaqah>دۡ</rule>ر<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَقَرِي<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا تُوعَدُونَ أَمۡ يَ<rule class=qalaqah>جۡ</rule>عَلُ لَهُ<rule class=madda_normal>ۥ</rule> رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَمَدًا ٢٥',
    25, 29, 7, 573, 507, 229, 'false'
  );
  
  -- Ayah 26 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5473,
    'عَـٰلِمُ ٱلۡغَیۡبِ فَلَا یُظۡهِرُ عَلَىٰ غَیۡبِهِۦۤ أَحَدًا',
    'عالم الغيب فلا يظهر على غيبه احدا',
    'عَ<rule class=madda_normal>ـٰ</rule>لِمُ <rule class=ham_wasl>ٱ</rule>لۡغَيۡبِ فَلَا يُظۡهِرُ عَلَىٰ غَيۡبِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> أَحَدًا ٢٦',
    26, 29, 7, 573, 507, 229, 'false'
  );
  
  -- Ayah 27 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5474,
    'إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولࣲ فَإِنَّهُۥ یَسۡلُكُ مِنۢ بَیۡنِ یَدَیۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدࣰا',
    'الا من ارتضى من رسول فانه يسلك من بين يديه ومن خلفه رصدا',
    'إِلَّا مَنِ <rule class=ham_wasl>ٱ</rule>رۡتَضَىٰ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّسُو<rule class=ikhafa>لٍ</rule> <rule class=ikhafa>ف</rule>َإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> يَسۡلُكُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِه<rule class=madda_normal>ِۦ</rule> رَصَدًا ٢٧',
    27, 29, 7, 573, 507, 229, 'false'
  );
  
  -- Ayah 28 Surah Al-Jinn
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    72,
    5475,
    'لِّیَعۡلَمَ أَن قَدۡ أَبۡلَغُوا۟ رِسَـٰلَـٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَیۡهِمۡ وَأَحۡصَىٰ كُلَّ شَیۡءٍ عَدَدَۢا',
    'ليعلم ان قد ابلغوا رسالات ربهم واحاط بما لديهم واحصى كل شيء عددا',
    'لِّيَعۡلَمَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>َ<rule class=qalaqah>دۡ</rule> أَ<rule class=qalaqah>بۡ</rule>لَغُو<rule class=slnt>اۡ</rule> رِسَ<rule class=madda_normal>ـٰ</rule>لَ<rule class=madda_normal>ـٰ</rule>تِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَيۡهِمۡ وَأَحۡصَىٰ كُلَّ شَىۡءٍ عَدَدَۢا ٢٨',
    28, 29, 7, 573, 507, 229, 'false'
  );
  

-- Surah Al-Muzzammil
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (73, 'سُورَةُ المُزَّمِّلِ', 'Al-Muzzammil', 'The Enshrouded One', 'Meccan', 20);

  -- Ayah 1 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5476,
    'یَـٰۤأَیُّهَا ٱلۡمُزَّمِّلُ',
    'يا ايها المزمل',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡمُزَّ<rule class=ghunnah>مّ</rule>ِلُ ١',
    1, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 2 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5477,
    'قُمِ ٱلَّیۡلَ إِلَّا قَلِیلࣰا',
    'قم الليل الا قليلا',
    'قُمِ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ إِلَّا قَلِيلاً ٢',
    2, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 3 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5478,
    'نِّصۡفَهُۥۤ أَوِ ٱنقُصۡ مِنۡهُ قَلِیلًا',
    'نصفه او انقص منه قليلا',
    'نِّصۡفَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَوِ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>ُصۡ مِنۡهُ قَلِيلاً ٣',
    3, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 4 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5479,
    'أَوۡ زِدۡ عَلَیۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِیلًا',
    'او زد عليه ورتل القران ترتيلا',
    'أَوۡ زِ<rule class=qalaqah>دۡ</rule> عَلَيۡهِ وَرَتِّلِ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ تَرۡتِيلاً ٤',
    4, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 5 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5480,
    'إِنَّا سَنُلۡقِی عَلَیۡكَ قَوۡلࣰا ثَقِیلًا',
    'انا سنلقي عليك قولا ثقيلا',
    'إِ<rule class=ghunnah>نّ</rule>َا سَنُلۡقِى عَلَيۡكَ قَوۡل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ث</rule>َقِيلاً ٥',
    5, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 6 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5481,
    'إِنَّ نَاشِئَةَ ٱلَّیۡلِ هِیَ أَشَدُّ وَطۡـࣰٔا وَأَقۡوَمُ قِیلًا',
    'ان ناشئة الليل هي اشد وطئا واقوم قيلا',
    'إِ<rule class=ghunnah>نّ</rule>َ نَاشِئَةَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ هِىَ أَشَدُّ وَ<rule class=qalaqah>طۡ</rule>ـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>و</rule>َأَ<rule class=qalaqah>قۡ</rule>وَمُ قِيلاً ٦',
    6, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 7 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5482,
    'إِنَّ لَكَ فِی ٱلنَّهَارِ سَبۡحࣰا طَوِیلࣰا',
    'ان لك في النهار سبحا طويلا',
    'إِ<rule class=ghunnah>نّ</rule>َ لَكَ فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارِ سَ<rule class=qalaqah>بۡ</rule><rule class=ikhafa>حًا</rule> <rule class=ikhafa>ط</rule>َوِيلاً ٧',
    7, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 8 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5483,
    'وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَیۡهِ تَبۡتِیلࣰا',
    'واذكر اسم ربك وتبتل اليه تبتيلا',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرِ <rule class=ham_wasl>ٱ</rule>سۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَ<rule class=qalaqah>بۡ</rule>تِيلاً ٨',
    8, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 9 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5484,
    'رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَاۤ إِلَـٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِیلࣰا',
    'رب المشرق والمغرب لا اله الا هو فاتخذه وكيلا',
    'رَّبُّ <rule class=ham_wasl>ٱ</rule>لۡمَشۡرِقِ وَ<rule class=ham_wasl>ٱ</rule>لۡمَغۡرِبِ ل<rule class=madda_obligatory_monfasel>َآ</rule> إِلَ<rule class=madda_normal>ـٰ</rule>هَ إِلَّا هُوَ فَ<rule class=ham_wasl>ٱ</rule>تَّخِذۡهُ وَكِيلاً ٩',
    9, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 10 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5485,
    'وَٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرࣰا جَمِیلࣰا',
    'واصبر على ما يقولون واهجرهم هجرا جميلا',
    'وَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَ<rule class=ham_wasl>ٱ</rule>هۡجُرۡهُمۡ هَ<rule class=qalaqah>جۡ</rule><rule class=ikhafa>رًا</rule> <rule class=ikhafa>ج</rule>َمِيلاً ١٠',
    10, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 11 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5486,
    'وَذَرۡنِی وَٱلۡمُكَذِّبِینَ أُو۟لِی ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِیلًا',
    'وذرني والمكذبين اولي النعمة ومهلهم قليلا',
    'وَذَرۡنِى وَ<rule class=ham_wasl>ٱ</rule>لۡمُكَذِّبِينَ أُ<rule class=slnt>وۡ</rule>لِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َعۡمَةِ وَمَهِّلۡهُمۡ قَلِيلاً ١١',
    11, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 12 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5487,
    'إِنَّ لَدَیۡنَاۤ أَنكَالࣰا وَجَحِیمࣰا',
    'ان لدينا انكالا وجحيما',
    'إِ<rule class=ghunnah>نّ</rule>َ لَدَيۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نك</rule>َال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َجَحِيمًا ١٢',
    12, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 13 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5488,
    'وَطَعَامࣰا ذَا غُصَّةࣲ وَعَذَابًا أَلِیمࣰا',
    'وطعاما ذا غصة وعذابا اليما',
    'وَطَعَا<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ذ</rule>َا غُصَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َعَذَابًا أَلِيمًا ١٣',
    13, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 14 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5489,
    'یَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ وَكَانَتِ ٱلۡجِبَالُ كَثِیبࣰا مَّهِیلًا',
    'يوم ترجف الارض والجبال وكانت الجبال كثيبا مهيلا',
    'يَوۡمَ تَرۡجُفُ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ وَ<rule class=ham_wasl>ٱ</rule>لۡجِبَالُ وَكَانَتِ <rule class=ham_wasl>ٱ</rule>لۡجِبَالُ كَثِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>م</rule>َّهِيلاً ١٤',
    14, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 15 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5490,
    'إِنَّاۤ أَرۡسَلۡنَاۤ إِلَیۡكُمۡ رَسُولࣰا شَـٰهِدًا عَلَیۡكُمۡ كَمَاۤ أَرۡسَلۡنَاۤ إِلَىٰ فِرۡعَوۡنَ رَسُولࣰا',
    'انا ارسلنا اليكم رسولا شاهدا عليكم كما ارسلنا الى فرعون رسولا',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَيۡكُمۡ رَسُول<rule class=ikhafa>اً</rule> <rule class=ikhafa>ش</rule>َ<rule class=madda_normal>ـٰ</rule>هِدًا عَلَيۡكُمۡ كَم<rule class=madda_obligatory_monfasel>َآ</rule> أَرۡسَلۡن<rule class=madda_obligatory_monfasel>َآ</rule> إِلَىٰ فِرۡعَوۡنَ رَسُولاً ١٥',
    15, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 16 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5491,
    'فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ فَأَخَذۡنَـٰهُ أَخۡذࣰا وَبِیلࣰا',
    'فعصى فرعون الرسول فاخذناه اخذا وبيلا',
    'فَعَصَىٰ فِرۡعَوۡنُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّسُولَ فَأَخَذۡنَ<rule class=madda_normal>ـٰ</rule>هُ أَخۡ<rule class=idgham_ghunnah>ذًا</rule> <rule class=idgham_ghunnah>و</rule>َبِيلاً ١٦',
    16, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 17 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5492,
    'فَكَیۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ یَوۡمࣰا یَجۡعَلُ ٱلۡوِلۡدَ ٰ⁠نَ شِیبًا',
    'فكيف تتقون ان كفرتم يوما يجعل الولدان شيبا',
    'فَكَيۡفَ تَتَّقُونَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َفَرۡتُمۡ يَوۡ<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>جۡ</rule>عَلُ <rule class=ham_wasl>ٱ</rule>لۡوِلۡد<rule class=madda_normal>ٰ</rule>نَ شِيبًا ١٧',
    17, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 18 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5493,
    'ٱلسَّمَاۤءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا',
    'السماء منفطر به كان وعده مفعولا',
    'ٱ<rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ مُ<rule class=ikhafa>نف</rule>َطِ<rule class=iqlab>رُۢ</rule> <rule class=iqlab>ب</rule>ِه<rule class=madda_normal>ِۦ</rule>‌ۚ كَانَ وَعۡدُهُ<rule class=madda_normal>ۥ</rule> مَفۡعُولاً ١٨',
    18, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 19 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5494,
    'إِنَّ هَـٰذِهِۦ تَذۡكِرَةࣱۖ فَمَن شَاۤءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِیلًا',
    'ان هذه تذكرة فمن شاء اتخذ الى ربه سبيلا',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> تَذۡكِرَ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>تَّخَذَ إِلَىٰ رَبِّه<rule class=madda_normal>ِۦ</rule> سَبِيلاً ١٩',
    19, 29, 7, 574, 508, 229, 'false'
  );
  
  -- Ayah 20 Surah Al-Muzzammil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    73,
    5495,
    '۞ إِنَّ رَبَّكَ یَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَیِ ٱلَّیۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَاۤىِٕفَةࣱ مِّنَ ٱلَّذِینَ مَعَكَۚ وَٱللَّهُ یُقَدِّرُ ٱلَّیۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَیۡكُمۡۖ فَٱقۡرَءُوا۟ مَا تَیَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَیَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ یَضۡرِبُونَ فِی ٱلۡأَرۡضِ یَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ یُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِۖ فَٱقۡرَءُوا۟ مَا تَیَسَّرَ مِنۡهُۚ وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقۡرِضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰاۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنۡ خَیۡرࣲ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَیۡرࣰا وَأَعۡظَمَ أَجۡرࣰاۚ وَٱسۡتَغۡفِرُوا۟ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمُۢ',
    'ان ربك يعلم انك تقوم ادنى من ثلثي الليل ونصفه وثلثه وطائفة من الذين معك والله يقدر الليل والنهار علم ان لن تحصوه فتاب عليكم فاقرءوا ما تيسر من القران علم ان سيكون منكم مرضى واخرون يضربون في الارض يبتغون من فضل الله واخرون يقاتلون في سبيل الله فاقرءوا ما تيسر منه واقيموا الصلاة واتوا الزكاة واقرضوا الله قرضا حسنا وما تقدموا لانفسكم من خير تجدوه عند الله هو خيرا واعظم اجرا واستغفروا الله ان الله غفور رحيم',
    '۞إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ يَعۡلَمُ أَ<rule class=ghunnah>نّ</rule>َكَ تَقُومُ أَ<rule class=qalaqah>دۡ</rule>نَىٰ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>ُلُثَىِ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ وَنِصۡفَهُ<rule class=madda_normal>ۥ</rule> وَثُلُثَهُ<rule class=madda_normal>ۥ</rule> وَط<rule class=madda_obligatory_mottasel>َا</rule>ٓئِفَ<rule class=idgham_ghunnah>ةٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ مَعَكَ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ يُقَدِّرُ <rule class=ham_wasl>ٱ</rule>لَّيۡلَ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َهَارَ‌ۚ عَلِمَ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>ُحۡصُوهُ فَتَابَ عَلَيۡكُمۡ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>رَءُو<rule class=slnt>اۡ</rule> مَا تَيَسَّرَ مِنَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانِ‌ۚ عَلِمَ أَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>َيَكُونُ مِ<rule class=ikhafa>نك</rule><rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّرۡضَىٰ‌ۙ وَءَاخَرُونَ يَضۡرِبُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ يَ<rule class=qalaqah>بۡ</rule>تَغُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>َضۡلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۙ وَءَاخَرُونَ يُقَ<rule class=madda_normal>ـٰ</rule>تِلُونَ فِى سَبِيلِ <rule class=ham_wasl>ٱ</rule>للَّهِ‌ۖ فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>رَءُو<rule class=slnt>اۡ</rule> مَا تَيَسَّرَ مِنۡهُ‌ۚ وَأَقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَءَاتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَأَ<rule class=qalaqah>قۡ</rule>رِضُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ قَرۡضًا حَسَ<rule class=idgham_ghunnah>نًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َمَا تُقَدِّمُو<rule class=slnt>اۡ</rule> لِأَ<rule class=ikhafa>نف</rule>ُسِك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خَيۡ<rule class=ikhafa>رٍ</rule> <rule class=ikhafa>ت</rule>َجِدُوهُ عِ<rule class=ikhafa>ند</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهِ هُوَ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َأَعۡظَمَ أَ<rule class=qalaqah>جۡ</rule><rule class=idgham_ghunnah>رًا‌ۚ</rule> <rule class=idgham_ghunnah>و</rule>َ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ‌ۖ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ غَفُو<rule class=idgham_wo_ghunnah>رٌ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّح<rule class=madda_permissible>ِي</rule>مُۢ ٢٠',
    20, 29, 7, 575, 509, 230, 'false'
  );
  

-- Surah Al-Muddaththir
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (74, 'سُورَةُ المُدَّثِّرِ', 'Al-Muddaththir', 'The Cloaked One', 'Meccan', 56);

  -- Ayah 1 Surah Al-Muddaththir
