-- Surah Al-Qiyaama
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (75, 'سُورَةُ القِيَامَةِ', 'Al-Qiyaama', 'The Resurrection', 'Meccan', 40);

  -- Ayah 1 Surah Al-Qiyaama
