    'تَظُنُّ أَن یُفۡعَلَ بِهَا فَاقِرَةࣱ',
    'تظن ان يفعل بها فاقرة',
    'تَظُ<rule class=ghunnah>نّ</rule>ُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُفۡعَلَ بِهَا فَاقِرَةٌ ٢٥',
    25, 29, 7, 578, 512, 231, 'false'
  );
  
  -- Ayah 26 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5577,
    'كَلَّاۤ إِذَا بَلَغَتِ ٱلتَّرَاقِیَ',
    'كلا اذا بلغت التراقي',
    'كَلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا بَلَغَتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّرَاقِىَ ٢٦',
    26, 29, 7, 578, 512, 231, 'false'
  );
  
  -- Ayah 27 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5578,
    'وَقِیلَ مَنۡۜ رَاقࣲ',
    'وقيل من راق',
    'وَقِيلَ م<rule class=idgham_wo_ghunnah>َنۡۜ</rule> <rule class=idgham_wo_ghunnah>ر</rule><rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ٍ ٢٧',
    27, 29, 7, 578, 512, 231, 'false'
  );
  
  -- Ayah 28 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5579,
    'وَظَنَّ أَنَّهُ ٱلۡفِرَاقُ',
    'وظن انه الفراق',
    'وَظَ<rule class=ghunnah>نّ</rule>َ أَ<rule class=ghunnah>نّ</rule>َهُ <rule class=ham_wasl>ٱ</rule>لۡفِر<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ُ ٢٨',
    28, 29, 7, 578, 512, 231, 'false'
  );
  
  -- Ayah 29 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5580,
    'وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ',
    'والتفت الساق بالساق',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡتَفَّتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّاقُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سّ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ِ ٢٩',
    29, 29, 7, 578, 512, 231, 'false'
  );
  
  -- Ayah 30 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5581,
    'إِلَىٰ رَبِّكَ یَوۡمَىِٕذٍ ٱلۡمَسَاقُ',
    'الى ربك يومئذ المساق',
    'إِلَىٰ رَبِّكَ يَوۡمَئِذٍ <rule class=ham_wasl>ٱ</rule>لۡمَس<rule class=madda_permissible>َا</rule><rule class=qalaqah>ق</rule>ُ ٣٠',
    30, 29, 7, 578, 512, 231, 'false'
  );
  
  -- Ayah 31 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5582,
    'فَلَا صَدَّقَ وَلَا صَلَّىٰ',
    'فلا صدق ولا صلى',
    'فَلَا صَدَّقَ وَلَا صَلَّىٰ ٣١',
    31, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 32 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5583,
    'وَلَـٰكِن كَذَّبَ وَتَوَلَّىٰ',
    'ولكن كذب وتولى',
    'وَلَ<rule class=madda_normal>ـٰ</rule>كِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبَ وَتَوَلَّىٰ ٣٢',
    32, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 33 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5584,
    'ثُمَّ ذَهَبَ إِلَىٰۤ أَهۡلِهِۦ یَتَمَطَّىٰۤ',
    'ثم ذهب الى اهله يتمطى',
    'ثُ<rule class=ghunnah>مّ</rule>َ ذَهَبَ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِه<rule class=madda_normal>ِۦ</rule> يَتَمَطَّىٰٓ ٣٣',
    33, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 34 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5585,
    'أَوۡلَىٰ لَكَ فَأَوۡلَىٰ',
    'اولى لك فاولى',
    'أَوۡلَىٰ لَكَ فَأَوۡلَىٰ ٣٤',
    34, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 35 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5586,
    'ثُمَّ أَوۡلَىٰ لَكَ فَأَوۡلَىٰۤ',
    'ثم اولى لك فاولى',
    'ثُ<rule class=ghunnah>مّ</rule>َ أَوۡلَىٰ لَكَ فَأَوۡلَىٰٓ ٣٥',
    35, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 36 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5587,
    'أَیَحۡسَبُ ٱلۡإِنسَـٰنُ أَن یُتۡرَكَ سُدًى',
    'ايحسب الانسان ان يترك سدى',
    'أَيَحۡسَبُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُتۡرَكَ سُدًى ٣٦',
    36, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 37 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5588,
    'أَلَمۡ یَكُ نُطۡفَةࣰ مِّن مَّنِیࣲّ یُمۡنَىٰ',
    'الم يك نطفة من مني يمنى',
    'أَلَمۡ يَكُ نُ<rule class=qalaqah>طۡ</rule>فَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>َّنِ<rule class=idgham_ghunnah>ىٍّ</rule> <rule class=idgham_ghunnah>ي</rule>ُمۡنَىٰ ٣٧',
    37, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 38 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5589,
    'ثُمَّ كَانَ عَلَقَةࣰ فَخَلَقَ فَسَوَّىٰ',
    'ثم كان علقة فخلق فسوى',
    'ثُ<rule class=ghunnah>مّ</rule>َ كَانَ عَلَقَ<rule class=ikhafa>ةً</rule> <rule class=ikhafa>ف</rule>َخَلَقَ فَسَوَّىٰ ٣٨',
    38, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 39 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5590,
    'فَجَعَلَ مِنۡهُ ٱلزَّوۡجَیۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰۤ',
    'فجعل منه الزوجين الذكر والانثى',
    'فَجَعَلَ مِنۡهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّوۡجَيۡنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذَّكَرَ وَ<rule class=ham_wasl>ٱ</rule>لۡأُ<rule class=ikhafa>نث</rule>َىٰٓ ٣٩',
    39, 29, 7, 578, 513, 231, 'false'
  );
  
  -- Ayah 40 Surah Al-Qiyaama
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    75,
    5591,
    'أَلَیۡسَ ذَ ٰ⁠لِكَ بِقَـٰدِرٍ عَلَىٰۤ أَن یُحۡـِۧیَ ٱلۡمَوۡتَىٰ',
    'اليس ذلك بقادر على ان يحيي الموتى',
    'أَلَيۡسَ ذ<rule class=madda_normal>ٰ</rule>لِكَ بِقَ<rule class=madda_normal>ـٰ</rule>دِرٍ عَلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُحۡــِۧىَ <rule class=ham_wasl>ٱ</rule>لۡمَوۡتَىٰ ٤٠',
    40, 29, 7, 578, 513, 231, 'false'
  );
  

-- Surah Al-Insaan
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (76, 'سُورَةُ الإِنسَانِ', 'Al-Insaan', 'Man', 'Medinan', 31);

  -- Ayah 1 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5592,
    'هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَـٰنِ حِینࣱ مِّنَ ٱلدَّهۡرِ لَمۡ یَكُن شَیۡـࣰٔا مَّذۡكُورًا',
    'هل اتى على الانسان حين من الدهر لم يكن شيئا مذكورا',
    'هَلۡ أَتَىٰ عَلَى <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نِ حِي<rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دَّهۡرِ لَمۡ يَكُ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule>َيۡـ<rule class=idgham_ghunnah>ـًٔا</rule> <rule class=idgham_ghunnah>م</rule>َّذۡكُورًا ١',
    1, 29, 7, 578, 514, 231, 'false'
  );
  
  -- Ayah 2 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5593,
    'إِنَّا خَلَقۡنَا ٱلۡإِنسَـٰنَ مِن نُّطۡفَةٍ أَمۡشَاجࣲ نَّبۡتَلِیهِ فَجَعَلۡنَـٰهُ سَمِیعَۢا بَصِیرًا',
    'انا خلقنا الانسان من نطفة امشاج نبتليه فجعلناه سميعا بصيرا',
    'إِ<rule class=ghunnah>نّ</rule>َا خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>ن</rule>ُّ<rule class=qalaqah>طۡ</rule>فَةٍ أَمۡشَا<rule class=idgham_ghunnah>جٍ</rule> <rule class=idgham_ghunnah>ن</rule>َّ<rule class=qalaqah>بۡ</rule>تَلِيهِ فَجَعَلۡنَ<rule class=madda_normal>ـٰ</rule>هُ سَمِيع<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>َصِيرًا ٢',
    2, 29, 7, 578, 514, 231, 'false'
  );
  
  -- Ayah 3 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5594,
    'إِنَّا هَدَیۡنَـٰهُ ٱلسَّبِیلَ إِمَّا شَاكِرࣰا وَإِمَّا كَفُورًا',
    'انا هديناه السبيل اما شاكرا واما كفورا',
    'إِ<rule class=ghunnah>نّ</rule>َا هَدَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّبِيلَ إِ<rule class=ghunnah>مّ</rule>َا شَاكِ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>و</rule>َإِ<rule class=ghunnah>مّ</rule>َا كَفُورًا ٣',
    3, 29, 7, 578, 514, 231, 'false'
  );
  
  -- Ayah 4 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5595,
    'إِنَّاۤ أَعۡتَدۡنَا لِلۡكَـٰفِرِینَ سَلَـٰسِلَا۟ وَأَغۡلَـٰلࣰا وَسَعِیرًا',
    'انا اعتدنا للكافرين سلاسل واغلالا وسعيرا',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَعۡتَ<rule class=qalaqah>دۡ</rule>نَا لِلۡكَ<rule class=madda_normal>ـٰ</rule>فِرِينَ سَلَ<rule class=madda_normal>ـٰ</rule>سِلَ<rule class=slnt>اۡ</rule> وَأَغۡلَ<rule class=madda_normal>ـٰ</rule>ل<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َسَعِيرًا ٤',
    4, 29, 7, 578, 514, 231, 'false'
  );
  
  -- Ayah 5 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5596,
    'إِنَّ ٱلۡأَبۡرَارَ یَشۡرَبُونَ مِن كَأۡسࣲ كَانَ مِزَاجُهَا كَافُورًا',
    'ان الابرار يشربون من كاس كان مزاجها كافورا',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>رَارَ يَشۡرَبُونَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َأۡ<rule class=ikhafa>سٍ</rule> <rule class=ikhafa>ك</rule>َانَ مِزَاجُهَا كَافُورًا ٥',
    5, 29, 7, 578, 514, 231, 'false'
  );
  
  -- Ayah 6 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5597,
    'عَیۡنࣰا یَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ یُفَجِّرُونَهَا تَفۡجِیرࣰا',
    'عينا يشرب بها عباد الله يفجرونها تفجيرا',
    'عَيۡ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>ي</rule>َشۡرَبُ بِهَا عِبَادُ <rule class=ham_wasl>ٱ</rule>للَّهِ يُفَجِّرُونَهَا تَفۡجِيرًا ٦',
    6, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 7 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5598,
    'یُوفُونَ بِٱلنَّذۡرِ وَیَخَافُونَ یَوۡمࣰا كَانَ شَرُّهُۥ مُسۡتَطِیرࣰا',
    'يوفون بالنذر ويخافون يوما كان شره مستطيرا',
    'يُوفُونَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َذۡرِ وَيَخَافُونَ يَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ك</rule>َانَ شَرُّهُ<rule class=madda_normal>ۥ</rule> مُسۡتَطِيرًا ٧',
    7, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 8 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5599,
    'وَیُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِینࣰا وَیَتِیمࣰا وَأَسِیرًا',
    'ويطعمون الطعام على حبه مسكينا ويتيما واسيرا',
    'وَيُ<rule class=qalaqah>طۡ</rule>عِمُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّعَامَ عَلَىٰ حُبِّه<rule class=madda_normal>ِۦ</rule> مِسۡكِي<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>و</rule>َيَتِي<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َأَسِيرًا ٨',
    8, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 9 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5600,
    'إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِیدُ مِنكُمۡ جَزَاۤءࣰ وَلَا شُكُورًا',
    'انما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكورا',
    'إِ<rule class=ghunnah>نّ</rule>َمَا نُ<rule class=qalaqah>طۡ</rule>عِمُكُمۡ لِوَ<rule class=qalaqah>جۡ</rule>هِ <rule class=ham_wasl>ٱ</rule>للَّهِ لَا نُرِيدُ مِ<rule class=ikhafa>نك</rule>ُمۡ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َلَا شُكُورًا ٩',
    9, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 10 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5601,
    'إِنَّا نَخَافُ مِن رَّبِّنَا یَوۡمًا عَبُوسࣰا قَمۡطَرِیرࣰا',
    'انا نخاف من ربنا يوما عبوسا قمطريرا',
    'إِ<rule class=ghunnah>نّ</rule>َا نَخَافُ م<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّنَا يَوۡمًا عَبُو<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ق</rule>َمۡطَرِيرًا ١٠',
    10, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 11 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5602,
    'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَ ٰ⁠لِكَ ٱلۡیَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةࣰ وَسُرُورࣰا',
    'فوقاهم الله شر ذلك اليوم ولقاهم نضرة وسرورا',
    'فَوَقَ<rule class=madda_normal>ـٰ</rule>هُمُ <rule class=ham_wasl>ٱ</rule>للَّهُ شَرَّ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ وَلَقَّ<rule class=madda_normal>ـٰ</rule>هُمۡ نَضۡرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َسُرُورًا ١١',
    11, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 12 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5603,
    'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةࣰ وَحَرِیرࣰا',
    'وجزاهم بما صبروا جنة وحريرا',
    'وَجَزَ<rule class=madda_normal>ٮٰ</rule>ه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِمَا صَبَرُو<rule class=slnt>اۡ</rule> جَ<rule class=ghunnah>نّ</rule>َ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َحَرِيرًا ١٢',
    12, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 13 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5604,
    'مُّتَّكِـِٔینَ فِیهَا عَلَى ٱلۡأَرَاۤىِٕكِۖ لَا یَرَوۡنَ فِیهَا شَمۡسࣰا وَلَا زَمۡهَرِیرࣰا',
    'متكئين فيها على الارائك لا يرون فيها شمسا ولا زمهريرا',
    'مُّتَّكِــِٔينَ فِيهَا عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكِ‌ۖ لَا يَرَوۡنَ فِيهَا شَمۡ<rule class=idgham_ghunnah>سًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا زَمۡهَرِيرًا ١٣',
    13, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 14 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5605,
    'وَدَانِیَةً عَلَیۡهِمۡ ظِلَـٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِیلࣰا',
    'ودانية عليهم ظلالها وذللت قطوفها تذليلا',
    'وَدَانِيَةً عَلَيۡهِمۡ ظِلَ<rule class=madda_normal>ـٰ</rule>لُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِيلاً ١٤',
    14, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 15 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5606,
    'وَیُطَافُ عَلَیۡهِم بِـَٔانِیَةࣲ مِّن فِضَّةࣲ وَأَكۡوَابࣲ كَانَتۡ قَوَارِیرَا۠',
    'ويطاف عليهم بانية من فضة واكواب كانت قواريرا',
    'وَيُطَافُ عَلَيۡه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِـَٔـانِيَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِضَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َأَكۡوَا<rule class=ikhafa>بٍ</rule> <rule class=ikhafa>ك</rule>َانَتۡ قَوَارِيرَاۡ ١٥',
    15, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 16 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5607,
    'قَوَارِیرَا۟ مِن فِضَّةࣲ قَدَّرُوهَا تَقۡدِیرࣰا',
    'قوارير من فضة قدروها تقديرا',
    'قَوَارِيرَ<rule class=slnt>اۡ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِضَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ق</rule>َدَّرُوهَا تَ<rule class=qalaqah>قۡ</rule>دِيرًا ١٦',
    16, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 17 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5608,
    'وَیُسۡقَوۡنَ فِیهَا كَأۡسࣰا كَانَ مِزَاجُهَا زَنجَبِیلًا',
    'ويسقون فيها كاسا كان مزاجها زنجبيلا',
    'وَيُسۡقَوۡنَ فِيهَا كَأۡ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>ك</rule>َانَ مِزَاجُهَا زَ<rule class=ikhafa>نج</rule>َبِيلاً ١٧',
    17, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 18 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5609,
    'عَیۡنࣰا فِیهَا تُسَمَّىٰ سَلۡسَبِیلࣰا',
    'عينا فيها تسمى سلسبيلا',
    'عَيۡ<rule class=ikhafa>نًا</rule> <rule class=ikhafa>ف</rule>ِيهَا تُسَ<rule class=ghunnah>مّ</rule>َىٰ سَلۡسَبِيلاً ١٨',
    18, 29, 7, 579, 514, 231, 'false'
  );
  
  -- Ayah 19 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5610,
    '۞ وَیَطُوفُ عَلَیۡهِمۡ وِلۡدَ ٰ⁠نࣱ مُّخَلَّدُونَ إِذَا رَأَیۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤࣰا مَّنثُورࣰا',
    'ويطوف عليهم ولدان مخلدون اذا رايتهم حسبتهم لؤلؤا منثورا',
    '۞وَيَطُوفُ عَلَيۡهِمۡ وِلۡد<rule class=madda_normal>ٰ</rule><rule class=idgham_ghunnah>نٌ</rule> <rule class=idgham_ghunnah>م</rule>ُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِ<rule class=qalaqah>بۡ</rule>تَهُمۡ لُؤۡلُ<rule class=idgham_ghunnah>ؤًا</rule> <rule class=idgham_ghunnah>م</rule>َّ<rule class=ikhafa>نث</rule>ُورًا ١٩',
    19, 29, 7, 579, 514, 232, 'false'
  );
  
  -- Ayah 20 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5611,
    'وَإِذَا رَأَیۡتَ ثَمَّ رَأَیۡتَ نَعِیمࣰا وَمُلۡكࣰا كَبِیرًا',
    'واذا رايت ثم رايت نعيما وملكا كبيرا',
    'وَإِذَا رَأَيۡتَ ثَ<rule class=ghunnah>مّ</rule>َ رَأَيۡتَ نَعِي<rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>و</rule>َمُلۡ<rule class=ikhafa>كًا</rule> <rule class=ikhafa>ك</rule>َبِيرًا ٢٠',
    20, 29, 7, 579, 514, 232, 'false'
  );
  
  -- Ayah 21 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5612,
    'عَـٰلِیَهُمۡ ثِیَابُ سُندُسٍ خُضۡرࣱ وَإِسۡتَبۡرَقࣱۖ وَحُلُّوۤا۟ أَسَاوِرَ مِن فِضَّةࣲ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابࣰا طَهُورًا',
    'عاليهم ثياب سندس خضر واستبرق وحلوا اساور من فضة وسقاهم ربهم شرابا طهورا',
    'عَ<rule class=madda_normal>ـٰ</rule>لِيَهُمۡ ثِيَابُ سُ<rule class=ikhafa>ند</rule>ُسٍ خُضۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>و</rule>َإِسۡتَ<rule class=qalaqah>بۡ</rule>رَ<rule class=idgham_ghunnah>قٌ‌ۖ</rule> <rule class=idgham_ghunnah>و</rule>َحُلّ<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> أَسَاوِرَ مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ف</rule>ِضَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َسَقَ<rule class=madda_normal>ـٰ</rule>هُمۡ رَبُّهُمۡ شَرَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ط</rule>َهُورًا ٢١',
    21, 29, 7, 579, 514, 232, 'false'
  );
  
  -- Ayah 22 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5613,
    'إِنَّ هَـٰذَا كَانَ لَكُمۡ جَزَاۤءࣰ وَكَانَ سَعۡیُكُم مَّشۡكُورًا',
    'ان هذا كان لكم جزاء وكان سعيكم مشكورا',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذَا كَانَ لَكُمۡ جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>و</rule>َكَانَ سَعۡيُك<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّشۡكُورًا ٢٢',
    22, 29, 7, 579, 514, 232, 'false'
  );
  
  -- Ayah 23 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5614,
    'إِنَّا نَحۡنُ نَزَّلۡنَا عَلَیۡكَ ٱلۡقُرۡءَانَ تَنزِیلࣰا',
    'انا نحن نزلنا عليك القران تنزيلا',
    'إِ<rule class=ghunnah>نّ</rule>َا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ <rule class=ham_wasl>ٱ</rule>لۡقُرۡءَانَ تَ<rule class=ikhafa>نز</rule>ِيلاً ٢٣',
    23, 29, 7, 579, 515, 232, 'false'
  );
  
  -- Ayah 24 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5615,
    'فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورࣰا',
    'فاصبر لحكم ربك ولا تطع منهم اثما او كفورا',
    'فَ<rule class=ham_wasl>ٱ</rule>صۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورًا ٢٤',
    24, 29, 7, 579, 515, 232, 'false'
  );
  
  -- Ayah 25 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5616,
    'وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةࣰ وَأَصِیلࣰا',
    'واذكر اسم ربك بكرة واصيلا',
    'وَ<rule class=ham_wasl>ٱ</rule>ذۡكُرِ <rule class=ham_wasl>ٱ</rule>سۡمَ رَبِّكَ بُكۡرَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>و</rule>َأَصِيلاً ٢٥',
    25, 29, 7, 579, 515, 232, 'false'
  );
  
  -- Ayah 26 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5617,
    'وَمِنَ ٱلَّیۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَیۡلࣰا طَوِیلًا',
    'ومن الليل فاسجد له وسبحه ليلا طويلا',
    'وَمِنَ <rule class=ham_wasl>ٱ</rule>لَّيۡلِ فَ<rule class=ham_wasl>ٱ</rule>سۡجُ<rule class=qalaqah>دۡ</rule> لَهُ<rule class=madda_normal>ۥ</rule> وَسَبِّحۡهُ لَيۡل<rule class=ikhafa>اً</rule> <rule class=ikhafa>ط</rule>َوِيلاً ٢٦',
    26, 29, 7, 580, 515, 232, 'false'
  );
  
  -- Ayah 27 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5618,
    'إِنَّ هَـٰۤؤُلَاۤءِ یُحِبُّونَ ٱلۡعَاجِلَةَ وَیَذَرُونَ وَرَاۤءَهُمۡ یَوۡمࣰا ثَقِیلࣰا',
    'ان هؤلاء يحبون العاجلة ويذرون وراءهم يوما ثقيلا',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ يُحِبُّونَ <rule class=ham_wasl>ٱ</rule>لۡعَاجِلَةَ وَيَذَرُونَ وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَهُمۡ يَوۡ<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ث</rule>َقِيلاً ٢٧',
    27, 29, 7, 580, 515, 232, 'false'
  );
  
  -- Ayah 28 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5619,
    'نَّحۡنُ خَلَقۡنَـٰهُمۡ وَشَدَدۡنَاۤ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَاۤ أَمۡثَـٰلَهُمۡ تَبۡدِیلًا',
    'نحن خلقناهم وشددنا اسرهم واذا شئنا بدلنا امثالهم تبديلا',
    'نَّحۡنُ خَلَ<rule class=qalaqah>قۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُمۡ وَشَدَ<rule class=qalaqah>دۡ</rule>ن<rule class=madda_obligatory_monfasel>َآ</rule> أَسۡرَهُمۡ‌ۖ وَإِذَا شِئۡنَا بَدَّلۡن<rule class=madda_obligatory_monfasel>َآ</rule> أَمۡثَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ تَ<rule class=qalaqah>بۡ</rule>دِيلاً ٢٨',
    28, 29, 7, 580, 515, 232, 'false'
  );
  
  -- Ayah 29 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5620,
    'إِنَّ هَـٰذِهِۦ تَذۡكِرَةࣱۖ فَمَن شَاۤءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِیلࣰا',
    'ان هذه تذكرة فمن شاء اتخذ الى ربه سبيلا',
    'إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_normal>ـٰ</rule>ذِه<rule class=madda_normal>ِۦ</rule> تَذۡكِرَ<rule class=ikhafa>ةٌ‌ۖ</rule> <rule class=ikhafa>ف</rule>َمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>تَّخَذَ إِلَىٰ رَبِّه<rule class=madda_normal>ِۦ</rule> سَبِيلاً ٢٩',
    29, 29, 7, 580, 515, 232, 'false'
  );
  
  -- Ayah 30 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5621,
    'وَمَا تَشَاۤءُونَ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا',
    'وما تشاءون الا ان يشاء الله ان الله كان عليما حكيما',
    'وَمَا تَش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُونَ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>للَّهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ كَانَ عَلِيمًا حَكِيمًا ٣٠',
    30, 29, 7, 580, 515, 232, 'false'
  );
  
  -- Ayah 31 Surah Al-Insaan
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    76,
    5622,
    'یُدۡخِلُ مَن یَشَاۤءُ فِی رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمِینَ أَعَدَّ لَهُمۡ عَذَابًا أَلِیمَۢا',
    'يدخل من يشاء في رحمته والظالمين اعد لهم عذابا اليما',
    'يُ<rule class=qalaqah>دۡ</rule>خِلُ م<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َش<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ فِى رَحۡمَتِه<rule class=madda_normal>ِۦ</rule>‌ۚ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ظَّ<rule class=madda_normal>ـٰ</rule>لِمِينَ أَعَدَّ لَهُمۡ عَذَابًا أَلِيمَۢا ٣١',
    31, 29, 7, 580, 515, 232, 'false'
  );
  

