    'وَكَذَّبُوا۟ بِـَٔایَـٰتِنَا كِذَّابࣰا',
    'وكذبوا باياتنا كذابا',
    'وَكَذَّبُو<rule class=slnt>اۡ</rule> بِـَٔـايَ<rule class=madda_normal>ـٰ</rule>تِنَا كِذَّابًا ٢٨',
    28, 30, 7, 582, 518, 233, 'false'
  );
  
  -- Ayah 29 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    78,
    5701,
    'وَكُلَّ شَیۡءٍ أَحۡصَیۡنَـٰهُ كِتَـٰبࣰا',
    'وكل شيء احصيناه كتابا',
    'وَكُلَّ شَىۡءٍ أَحۡصَيۡنَ<rule class=madda_normal>ـٰ</rule>هُ كِتَ<rule class=madda_normal>ـٰ</rule>بًا ٢٩',
    29, 30, 7, 582, 518, 233, 'false'
  );
  
  -- Ayah 30 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    78,
    5702,
    'فَذُوقُوا۟ فَلَن نَّزِیدَكُمۡ إِلَّا عَذَابًا',
    'فذوقوا فلن نزيدكم الا عذابا',
    'فَذُوقُو<rule class=slnt>اۡ</rule> فَل<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ن</rule>َّزِيدَكُمۡ إِلَّا عَذَابًا ٣٠',
    30, 30, 7, 582, 518, 233, 'false'
  );
  
  -- Ayah 31 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
