    5704,
    'حَدَاۤىِٕقَ وَأَعۡنَـٰبࣰا',
    'حدائق واعنابا',
    'حَد<rule class=madda_obligatory_mottasel>َا</rule>ٓئِقَ وَأَعۡنَ<rule class=madda_normal>ـٰ</rule>بًا ٣٢',
    32, 30, 7, 583, 519, 233, 'false'
  );
  
  -- Ayah 33 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
