    'وَكَأۡ<rule class=ikhafa>سًا</rule> <rule class=ikhafa>د</rule>ِهَاقًا ٣٤',
    34, 30, 7, 583, 519, 233, 'false'
  );
  
  -- Ayah 35 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    78,
    5707,
    'لَّا یَسۡمَعُونَ فِیهَا لَغۡوࣰا وَلَا كِذَّ ٰ⁠بࣰا',
    'لا يسمعون فيها لغوا ولا كذابا',
    'لَّا يَسۡمَعُونَ فِيهَا لَغۡ<rule class=idgham_ghunnah>وًا</rule> <rule class=idgham_ghunnah>و</rule>َلَا كِذّ<rule class=madda_normal>ٰ</rule>بًا ٣٥',
    35, 30, 7, 583, 519, 233, 'false'
  );
  
  -- Ayah 36 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    78,
    5708,
    'جَزَاۤءࣰ مِّن رَّبِّكَ عَطَاۤءً حِسَابࣰا',
    'جزاء من ربك عطاء حسابا',
    'جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=idgham_ghunnah>ءً</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّكَ عَط<rule class=madda_obligatory_mottasel>َا</rule>ٓءً حِسَابًا ٣٦',
    36, 30, 7, 583, 519, 233, 'false'
  );
  
  -- Ayah 37 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    78,
    5709,
    'رَّبِّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا ٱلرَّحۡمَـٰنِۖ لَا یَمۡلِكُونَ مِنۡهُ خِطَابࣰا',
    'رب السماوات والارض وما بينهما الرحمن لا يملكون منه خطابا',
    'رَّبِّ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ وَمَا بَيۡنَهُمَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نِ‌ۖ لَا يَمۡلِكُونَ مِنۡهُ خِطَابًا ٣٧',
    37, 30, 7, 583, 519, 233, 'false'
  );
  
  -- Ayah 38 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    78,
    5710,
    'یَوۡمَ یَقُومُ ٱلرُّوحُ وَٱلۡمَلَـٰۤىِٕكَةُ صَفࣰّاۖ لَّا یَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَـٰنُ وَقَالَ صَوَابࣰا',
    'يوم يقوم الروح والملائكة صفا لا يتكلمون الا من اذن له الرحمن وقال صوابا',
    'يَوۡمَ يَقُومُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّوحُ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ صَف<rule class=idgham_wo_ghunnah>ًّا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّحۡمَ<rule class=madda_normal>ـٰ</rule>نُ وَقَالَ صَوَابًا ٣٨',
    38, 30, 7, 583, 519, 233, 'false'
  );
  
  -- Ayah 39 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    78,
    5711,
    'ذَ ٰ⁠لِكَ ٱلۡیَوۡمُ ٱلۡحَقُّۖ فَمَن شَاۤءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا',
    'ذلك اليوم الحق فمن شاء اتخذ الى ربه مابا',
    'ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡيَوۡمُ <rule class=ham_wasl>ٱ</rule>لۡحَقُّ‌ۖ فَمَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ش</rule><rule class=madda_obligatory_mottasel>َا</rule>ٓءَ <rule class=ham_wasl>ٱ</rule>تَّخَذَ إِلَىٰ رَبِّه<rule class=madda_normal>ِۦ</rule> مَـَٔـابًا ٣٩',
    39, 30, 7, 583, 519, 233, 'false'
  );
  
  -- Ayah 40 Surah An-Naba
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    78,
    5712,
    'إِنَّاۤ أَنذَرۡنَـٰكُمۡ عَذَابࣰا قَرِیبࣰا یَوۡمَ یَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ یَدَاهُ وَیَقُولُ ٱلۡكَافِرُ یَـٰلَیۡتَنِی كُنتُ تُرَ ٰ⁠بَۢا',
    'انا انذرناكم عذابا قريبا يوم ينظر المرء ما قدمت يداه ويقول الكافر يا ليتني كنت ترابا',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نذ</rule>َرۡنَ<rule class=madda_normal>ـٰ</rule>كُمۡ عَذَا<rule class=ikhafa>بًا</rule> <rule class=ikhafa>ق</rule>َرِي<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَ يَ<rule class=ikhafa>نظ</rule>ُرُ <rule class=ham_wasl>ٱ</rule>لۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ <rule class=ham_wasl>ٱ</rule>لۡكَافِرُ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَنِى كُ<rule class=ikhafa>نت</rule>ُ تُر<rule class=madda_normal>ٰ</rule>بَۢا ٤٠',
    40, 30, 7, 583, 519, 233, 'false'
  );
  

-- Surah An-Naaziaat
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (79, 'سُورَةُ النَّازِعَاتِ', 'An-Naaziaat', 'Those who drag forth', 'Meccan', 46);

  -- Ayah 1 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5713,
    'وَٱلنَّـٰزِعَـٰتِ غَرۡقࣰا',
    'والنازعات غرقا',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>زِعَ<rule class=madda_normal>ـٰ</rule>تِ غَرۡقًا ١',
    1, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 2 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5714,
    'وَٱلنَّـٰشِطَـٰتِ نَشۡطࣰا',
    'والناشطات نشطا',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>شِطَ<rule class=madda_normal>ـٰ</rule>تِ نَشۡطًا ٢',
    2, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 3 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5715,
    'وَٱلسَّـٰبِحَـٰتِ سَبۡحࣰا',
    'والسابحات سبحا',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>بِحَ<rule class=madda_normal>ـٰ</rule>تِ سَ<rule class=qalaqah>بۡ</rule>حًا ٣',
    3, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 4 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5716,
    'فَٱلسَّـٰبِقَـٰتِ سَبۡقࣰا',
    'فالسابقات سبقا',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّ<rule class=madda_normal>ـٰ</rule>بِقَ<rule class=madda_normal>ـٰ</rule>تِ سَ<rule class=qalaqah>بۡ</rule>قًا ٤',
    4, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 5 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5717,
    'فَٱلۡمُدَبِّرَ ٰ⁠تِ أَمۡرࣰا',
    'فالمدبرات امرا',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡمُدَبِّر<rule class=madda_normal>ٰ</rule>تِ أَمۡرًا ٥',
    5, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 6 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5718,
    'یَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ',
    'يوم ترجف الراجفة',
    'يَوۡمَ تَرۡجُفُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّاجِفَةُ ٦',
    6, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 7 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5719,
    'تَتۡبَعُهَا ٱلرَّادِفَةُ',
    'تتبعها الرادفة',
    'تَتۡبَعُهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّادِفَةُ ٧',
    7, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 8 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5720,
    'قُلُوبࣱ یَوۡمَىِٕذࣲ وَاجِفَةٌ',
    'قلوب يومئذ واجفة',
    'قُلُو<rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>و</rule>َاجِفَةٌ ٨',
    8, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 9 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5721,
    'أَبۡصَـٰرُهَا خَـٰشِعَةࣱ',
    'ابصارها خاشعة',
    'أَ<rule class=qalaqah>بۡ</rule>صَ<rule class=madda_normal>ـٰ</rule>رُهَا خَ<rule class=madda_normal>ـٰ</rule>شِعَةٌ ٩',
    9, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 10 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5722,
    'یَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِی ٱلۡحَافِرَةِ',
    'يقولون اانا لمردودون في الحافرة',
    'يَقُولُونَ أَءِ<rule class=ghunnah>نّ</rule>َا لَمَرۡدُودُونَ فِى <rule class=ham_wasl>ٱ</rule>لۡحَافِرَةِ ١٠',
    10, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 11 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5723,
    'أَءِذَا كُنَّا عِظَـٰمࣰا نَّخِرَةࣰ',
    'ااذا كنا عظاما نخرة',
    'أَءِذَا كُ<rule class=ghunnah>نّ</rule>َا عِظَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>مًا</rule> <rule class=idgham_ghunnah>ن</rule>َّخِرَةً ١١',
    11, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 12 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5724,
    'قَالُوا۟ تِلۡكَ إِذࣰا كَرَّةٌ خَاسِرَةࣱ',
    'قالوا تلك اذا كرة خاسرة',
    'قَالُو<rule class=slnt>اۡ</rule> تِلۡكَ إِ<rule class=ikhafa>ذًا</rule> <rule class=ikhafa>ك</rule>َرَّةٌ خَاسِرَةٌ ١٢',
    12, 30, 7, 583, 520, 233, 'false'
  );
  
  -- Ayah 13 Surah An-Naaziaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    79,
    5725,
    'فَإِنَّمَا هِیَ زَجۡرَةࣱ وَ ٰ⁠حِدَةࣱ',
    'فانما هي زجرة واحدة',
