-- Surah Al-Infitaar
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (82, 'سُورَةُ الانفِطَارِ', 'Al-Infitaar', 'The Cleaving', 'Meccan', 19);

  -- Ayah 1 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5830,
    'إِذَا ٱلسَّمَاۤءُ ٱنفَطَرَتۡ',
    'اذا السماء انفطرت',
    'إِذَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نف</rule>َطَرَتۡ ١',
    1, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 2 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5831,
    'وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ',
    'واذا الكواكب انتثرت',
    'وَإِذَا <rule class=ham_wasl>ٱ</rule>لۡكَوَاكِبُ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نت</rule>َثَرَتۡ ٢',
    2, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 3 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5832,
    'وَإِذَا ٱلۡبِحَارُ فُجِّرَتۡ',
    'واذا البحار فجرت',
    'وَإِذَا <rule class=ham_wasl>ٱ</rule>لۡبِحَارُ فُجِّرَتۡ ٣',
    3, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 4 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5833,
    'وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ',
    'واذا القبور بعثرت',
    'وَإِذَا <rule class=ham_wasl>ٱ</rule>لۡقُبُورُ بُعۡثِرَتۡ ٤',
    4, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 5 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5834,
    'عَلِمَتۡ نَفۡسࣱ مَّا قَدَّمَتۡ وَأَخَّرَتۡ',
    'علمت نفس ما قدمت واخرت',
    'عَلِمَتۡ نَفۡ<rule class=idgham_ghunnah>سٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا قَدَّمَتۡ وَأَخَّرَتۡ ٥',
    5, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 6 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5835,
    'یَـٰۤأَیُّهَا ٱلۡإِنسَـٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِیمِ',
    'يا ايها الانسان ما غرك بربك الكريم',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ مَا غَرَّكَ بِرَبِّكَ <rule class=ham_wasl>ٱ</rule>لۡكَر<rule class=madda_permissible>ِي</rule>مِ ٦',
    6, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 7 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5836,
    'ٱلَّذِی خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ',
    'الذي خلقك فسواك فعدلك',
    'ٱلَّذِى خَلَقَكَ فَسَوَّ<rule class=madda_normal>ٮٰ</rule>كَ فَعَدَلَكَ ٧',
    7, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 8 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5837,
    'فِیۤ أَیِّ صُورَةࣲ مَّا شَاۤءَ رَكَّبَكَ',
    'في اي صورة ما شاء ركبك',
    'ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَىِّ صُورَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>َّا ش<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَكَّبَكَ ٨',
    8, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 9 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5838,
    'كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّینِ',
    'كلا بل تكذبون بالدين',
    'كَلَّا بَلۡ تُكَذِّبُونَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ٩',
    9, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 10 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5839,
    'وَإِنَّ عَلَیۡكُمۡ لَحَـٰفِظِینَ',
    'وان عليكم لحافظين',
    'وَإِ<rule class=ghunnah>نّ</rule>َ عَلَيۡكُمۡ لَحَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 11 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5840,
    'كِرَامࣰا كَـٰتِبِینَ',
    'كراما كاتبين',
    'كِرَا<rule class=ikhafa>مًا</rule> <rule class=ikhafa>ك</rule>َ<rule class=madda_normal>ـٰ</rule>تِب<rule class=madda_permissible>ِي</rule>نَ ١١',
    11, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 12 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5841,
    'یَعۡلَمُونَ مَا تَفۡعَلُونَ',
    'يعلمون ما تفعلون',
    'يَعۡلَمُونَ مَا تَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ١٢',
    12, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 13 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5842,
    'إِنَّ ٱلۡأَبۡرَارَ لَفِی نَعِیمࣲ',
    'ان الابرار لفي نعيم',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>رَارَ لَفِى نَع<rule class=madda_permissible>ِي</rule>مٍ ١٣',
    13, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 14 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5843,
    'وَإِنَّ ٱلۡفُجَّارَ لَفِی جَحِیمࣲ',
    'وان الفجار لفي جحيم',
    'وَإِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡفُجَّارَ لَفِى جَح<rule class=madda_permissible>ِي</rule>مٍ ١٤',
    14, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 15 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5844,
    'یَصۡلَوۡنَهَا یَوۡمَ ٱلدِّینِ',
    'يصلونها يوم الدين',
    'يَصۡلَوۡنَهَا يَوۡمَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ١٥',
    15, 30, 7, 587, 524, 235, 'false'
  );
  
  -- Ayah 16 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
