  -- Ayah 18 Surah Al-Infitaar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    82,
    5847,
    'ثُمَّ مَاۤ أَدۡرَىٰكَ مَا یَوۡمُ ٱلدِّینِ',
    'ثم ما ادراك ما يوم الدين',
    'ثُ<rule class=ghunnah>مّ</rule>َ م<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>كَ مَا يَوۡمُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ١٨',
    18, 30, 7, 587, 524, 235, 'false'
