    19, 30, 7, 587, 524, 235, 'false'
  );
  

-- Surah Al-Mutaffifin
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (83, 'سُورَةُ المُطَفِّفِينَ', 'Al-Mutaffifin', 'Defrauding', 'Meccan', 36);

  -- Ayah 1 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5849,
    'وَیۡلࣱ لِّلۡمُطَفِّفِینَ',
    'ويل للمطففين',
    'وَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُطَفِّف<rule class=madda_permissible>ِي</rule>نَ ١',
    1, 30, 7, 587, 525, 235, 'false'
  );
  
  -- Ayah 2 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5850,
    'ٱلَّذِینَ إِذَا ٱكۡتَالُوا۟ عَلَى ٱلنَّاسِ یَسۡتَوۡفُونَ',
    'الذين اذا اكتالوا على الناس يستوفون',
    'ٱلَّذِينَ إِذَا <rule class=ham_wasl>ٱ</rule>كۡتَالُو<rule class=slnt>اۡ</rule> عَلَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسِ يَسۡتَوۡف<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 30, 7, 587, 525, 235, 'false'
  );
  
  -- Ayah 3 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5851,
    'وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ یُخۡسِرُونَ',
    'واذا كالوهم او وزنوهم يخسرون',
    'وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِر<rule class=madda_permissible>ُو</rule>نَ ٣',
    3, 30, 7, 587, 525, 235, 'false'
  );
  
  -- Ayah 4 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5852,
    'أَلَا یَظُنُّ أُو۟لَـٰۤىِٕكَ أَنَّهُم مَّبۡعُوثُونَ',
    'الا يظن اولئك انهم مبعوثون',
    'أَلَا يَظُ<rule class=ghunnah>نّ</rule>ُ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ أَ<rule class=ghunnah>نّ</rule>َه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>َّ<rule class=qalaqah>بۡ</rule>عُوث<rule class=madda_permissible>ُو</rule>نَ ٤',
    4, 30, 7, 587, 525, 235, 'false'
  );
  
  -- Ayah 5 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5853,
    'لِیَوۡمٍ عَظِیمࣲ',
    'ليوم عظيم',
    'لِيَوۡمٍ عَظ<rule class=madda_permissible>ِي</rule>مٍ ٥',
    5, 30, 7, 587, 525, 235, 'false'
  );
  
  -- Ayah 6 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5854,
    'یَوۡمَ یَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَـٰلَمِینَ',
    'يوم يقوم الناس لرب العالمين',
    'يَوۡمَ يَقُومُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ لِرَبِّ <rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>لَم<rule class=madda_permissible>ِي</rule>نَ ٦',
    6, 30, 7, 587, 525, 235, 'false'
  );
  
  -- Ayah 7 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5855,
    'كَلَّاۤ إِنَّ كِتَـٰبَ ٱلۡفُجَّارِ لَفِی سِجِّینࣲ',
    'كلا ان كتاب الفجار لفي سجين',
    'كَلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ كِتَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لۡفُجَّارِ لَفِى سِجّ<rule class=madda_permissible>ِي</rule>نٍ ٧',
    7, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 8 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5856,
    'وَمَاۤ أَدۡرَىٰكَ مَا سِجِّینࣱ',
    'وما ادراك ما سجين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>كَ مَا سِجّ<rule class=madda_permissible>ِي</rule>نٌ ٨',
    8, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 9 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5857,
    'كِتَـٰبࣱ مَّرۡقُومࣱ',
    'كتاب مرقوم',
    'كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>َّرۡق<rule class=madda_permissible>ُو</rule>مٌ ٩',
    9, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 10 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5858,
    'وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ',
    'ويل يومئذ للمكذبين',
    'وَيۡ<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>ي</rule>َوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُكَذِّب<rule class=madda_permissible>ِي</rule>نَ ١٠',
    10, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 11 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5859,
    'ٱلَّذِینَ یُكَذِّبُونَ بِیَوۡمِ ٱلدِّینِ',
    'الذين يكذبون بيوم الدين',
    'ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ١١',
    11, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 12 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5860,
    'وَمَا یُكَذِّبُ بِهِۦۤ إِلَّا كُلُّ مُعۡتَدٍ أَثِیمٍ',
    'وما يكذب به الا كل معتد اثيم',
    'وَمَا يُكَذِّبُ بِه<rule class=madda_obligatory_monfasel>ِۦٓ</rule> إِلَّا كُلُّ مُعۡتَدٍ أَث<rule class=madda_permissible>ِي</rule>مٍ ١٢',
    12, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 13 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5861,
    'إِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا قَالَ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ',
    'اذا تتلى عليه اياتنا قال اساطير الاولين',
    'إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَ<rule class=madda_normal>ـٰ</rule>تُنَا قَالَ أَسَ<rule class=madda_normal>ـٰ</rule>طِيرُ <rule class=ham_wasl>ٱ</rule>لۡأَوَّل<rule class=madda_permissible>ِي</rule>نَ ١٣',
    13, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 14 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5862,
    'كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ یَكۡسِبُونَ',
    'كلا بل ران على قلوبهم ما كانوا يكسبون',
    'كَلَّا‌ۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>َّا كَانُو<rule class=slnt>اۡ</rule> يَكۡسِب<rule class=madda_permissible>ُو</rule>نَ ١٤',
    14, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 15 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5863,
    'كَلَّاۤ إِنَّهُمۡ عَن رَّبِّهِمۡ یَوۡمَىِٕذࣲ لَّمَحۡجُوبُونَ',
    'كلا انهم عن ربهم يومئذ لمحجوبون',
    'كَلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َهُمۡ ع<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّبِّهِمۡ يَوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمَحۡجُوب<rule class=madda_permissible>ُو</rule>نَ ١٥',
    15, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 16 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5864,
    'ثُمَّ إِنَّهُمۡ لَصَالُوا۟ ٱلۡجَحِیمِ',
    'ثم انهم لصالو الجحيم',
    'ثُ<rule class=ghunnah>مّ</rule>َ إِ<rule class=ghunnah>نّ</rule>َهُمۡ لَصَالُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡجَح<rule class=madda_permissible>ِي</rule>مِ ١٦',
    16, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 17 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5865,
    'ثُمَّ یُقَالُ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تُكَذِّبُونَ',
    'ثم يقال هذا الذي كنتم به تكذبون',
    'ثُ<rule class=ghunnah>مّ</rule>َ يُقَالُ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لَّذِى كُ<rule class=ikhafa>نت</rule><rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِه<rule class=madda_normal>ِۦ</rule> تُكَذِّب<rule class=madda_permissible>ُو</rule>نَ ١٧',
    17, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 18 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5866,
    'كَلَّاۤ إِنَّ كِتَـٰبَ ٱلۡأَبۡرَارِ لَفِی عِلِّیِّینَ',
    'كلا ان كتاب الابرار لفي عليين',
    'كَلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ كِتَ<rule class=madda_normal>ـٰ</rule>بَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>رَارِ لَفِى عِلِّيّ<rule class=madda_permissible>ِي</rule>نَ ١٨',
    18, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 19 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5867,
    'وَمَاۤ أَدۡرَىٰكَ مَا عِلِّیُّونَ',
    'وما ادراك ما عليون',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>كَ مَا عِلِّيّ<rule class=madda_permissible>ُو</rule>نَ ١٩',
    19, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 20 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5868,
    'كِتَـٰبࣱ مَّرۡقُومࣱ',
    'كتاب مرقوم',
    'كِتَ<rule class=madda_normal>ـٰ</rule><rule class=idgham_ghunnah>بٌ</rule> <rule class=idgham_ghunnah>م</rule>َّرۡق<rule class=madda_permissible>ُو</rule>مٌ ٢٠',
    20, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 21 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5869,
    'یَشۡهَدُهُ ٱلۡمُقَرَّبُونَ',
    'يشهده المقربون',
    'يَشۡهَدُهُ <rule class=ham_wasl>ٱ</rule>لۡمُقَرَّب<rule class=madda_permissible>ُو</rule>نَ ٢١',
    21, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 22 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
