  -- Ayah 28 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5876,
    'عَیۡنࣰا یَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ',
    'عينا يشرب بها المقربون',
    'عَيۡ<rule class=idgham_ghunnah>نًا</rule> <rule class=idgham_ghunnah>ي</rule>َشۡرَبُ بِهَا <rule class=ham_wasl>ٱ</rule>لۡمُقَرَّب<rule class=madda_permissible>ُو</rule>نَ ٢٨',
    28, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 29 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5877,
    'إِنَّ ٱلَّذِینَ أَجۡرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِینَ ءَامَنُوا۟ یَضۡحَكُونَ',
    'ان الذين اجرموا كانوا من الذين امنوا يضحكون',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أَ<rule class=qalaqah>جۡ</rule>رَمُو<rule class=slnt>اۡ</rule> كَانُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> يَضۡحَك<rule class=madda_permissible>ُو</rule>نَ ٢٩',
    29, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 30 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5878,
    'وَإِذَا مَرُّوا۟ بِهِمۡ یَتَغَامَزُونَ',
    'واذا مروا بهم يتغامزون',
    'وَإِذَا مَرُّو<rule class=slnt>اۡ</rule> بِهِمۡ يَتَغَامَز<rule class=madda_permissible>ُو</rule>نَ ٣٠',
    30, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 31 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5879,
    'وَإِذَا ٱنقَلَبُوۤا۟ إِلَىٰۤ أَهۡلِهِمُ ٱنقَلَبُوا۟ فَكِهِینَ',
    'واذا انقلبوا الى اهلهم انقلبوا فكهين',
    'وَإِذَا <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>َلَب<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِهِمُ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نق</rule>َلَبُو<rule class=slnt>اۡ</rule> فَكِه<rule class=madda_permissible>ِي</rule>نَ ٣١',
    31, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 32 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5880,
    'وَإِذَا رَأَوۡهُمۡ قَالُوۤا۟ إِنَّ هَـٰۤؤُلَاۤءِ لَضَاۤلُّونَ',
    'واذا راوهم قالوا ان هؤلاء لضالون',
    'وَإِذَا رَأَوۡهُمۡ قَال<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِ<rule class=ghunnah>نّ</rule>َ هَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ؤُل<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ لَض<rule class=madda_necessary>َا</rule>ٓلّ<rule class=madda_permissible>ُو</rule>نَ ٣٢',
    32, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 33 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5881,
    'وَمَاۤ أُرۡسِلُوا۟ عَلَیۡهِمۡ حَـٰفِظِینَ',
    'وما ارسلوا عليهم حافظين',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُرۡسِلُو<rule class=slnt>اۡ</rule> عَلَيۡهِمۡ حَ<rule class=madda_normal>ـٰ</rule>فِظ<rule class=madda_permissible>ِي</rule>نَ ٣٣',
    33, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 34 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5882,
    'فَٱلۡیَوۡمَ ٱلَّذِینَ ءَامَنُوا۟ مِنَ ٱلۡكُفَّارِ یَضۡحَكُونَ',
    'فاليوم الذين امنوا من الكفار يضحكون',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> مِنَ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارِ يَضۡحَك<rule class=madda_permissible>ُو</rule>نَ ٣٤',
    34, 30, 7, 588, 525, 235, 'false'
  );
  
  -- Ayah 35 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5883,
    'عَلَى ٱلۡأَرَاۤىِٕكِ یَنظُرُونَ',
    'على الارائك ينظرون',
    'عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِكِ يَ<rule class=ikhafa>نظ</rule>ُر<rule class=madda_permissible>ُو</rule>نَ ٣٥',
    35, 30, 7, 589, 525, 235, 'false'
  );
  
  -- Ayah 36 Surah Al-Mutaffifin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    83,
    5884,
    'هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُوا۟ یَفۡعَلُونَ',
    'هل ثوب الكفار ما كانوا يفعلون',
    'هَلۡ ثُوِّبَ <rule class=ham_wasl>ٱ</rule>لۡكُفَّارُ مَا كَانُو<rule class=slnt>اۡ</rule> يَفۡعَل<rule class=madda_permissible>ُو</rule>نَ ٣٦',
    36, 30, 7, 589, 525, 235, 'false'
  );
  

-- Surah Al-Inshiqaaq
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (84, 'سُورَةُ الانشِقَاقِ', 'Al-Inshiqaaq', 'The Splitting Open', 'Meccan', 25);

  -- Ayah 1 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5885,
    'إِذَا ٱلسَّمَاۤءُ ٱنشَقَّتۡ',
    'اذا السماء انشقت',
    'إِذَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءُ <rule class=ham_wasl>ٱ</rule><rule class=ikhafa>نش</rule>َقَّتۡ ١',
    1, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 2 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5886,
    'وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ',
    'واذنت لربها وحقت',
    'وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ ٢',
    2, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 3 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5887,
    'وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ',
    'واذا الارض مدت',
    'وَإِذَا <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ مُدَّتۡ ٣',
    3, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 4 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5888,
    'وَأَلۡقَتۡ مَا فِیهَا وَتَخَلَّتۡ',
    'والقت ما فيها وتخلت',
    'وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ ٤',
    4, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 5 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5889,
    'وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ',
    'واذنت لربها وحقت',
    'وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ ٥',
    5, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 6 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5890,
    'یَـٰۤأَیُّهَا ٱلۡإِنسَـٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحࣰا فَمُلَـٰقِیهِ',
    'يا ايها الانسان انك كادح الى ربك كدحا فملاقيه',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ إِ<rule class=ghunnah>نّ</rule>َكَ كَادِحٌ إِلَىٰ رَبِّكَ كَ<rule class=qalaqah>دۡ</rule><rule class=ikhafa>حًا</rule> <rule class=ikhafa>ف</rule>َمُلَ<rule class=madda_normal>ـٰ</rule>ق<rule class=madda_permissible>ِي</rule>هِ ٦',
    6, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 7 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5891,
    'فَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ بِیَمِینِهِۦ',
    'فاما من اوتي كتابه بيمينه',
    'فَأَ<rule class=ghunnah>مّ</rule>َا مَنۡ أُوتِىَ كِتَ<rule class=madda_normal>ـٰ</rule>بَهُ<rule class=madda_normal>ۥ</rule> بِيَمِينِهِۦ ٧',
    7, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 8 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5892,
    'فَسَوۡفَ یُحَاسَبُ حِسَابࣰا یَسِیرࣰا',
    'فسوف يحاسب حسابا يسيرا',
    'فَسَوۡفَ يُحَاسَبُ حِسَا<rule class=idgham_ghunnah>بًا</rule> <rule class=idgham_ghunnah>ي</rule>َسِيرًا ٨',
    8, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 9 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5893,
    'وَیَنقَلِبُ إِلَىٰۤ أَهۡلِهِۦ مَسۡرُورࣰا',
    'وينقلب الى اهله مسرورا',
    'وَيَ<rule class=ikhafa>نق</rule>َلِبُ إِلَ<rule class=madda_obligatory_monfasel>ىٰٓ</rule> أَهۡلِه<rule class=madda_normal>ِۦ</rule> مَسۡرُورًا ٩',
    9, 30, 7, 589, 526, 236, 'false'
  );
  
  -- Ayah 10 Surah Al-Inshiqaaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    84,
    5894,
    'وَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ وَرَاۤءَ ظَهۡرِهِۦ',
    'واما من اوتي كتابه وراء ظهره',
    'وَأَ<rule class=ghunnah>مّ</rule>َا مَنۡ أُوتِىَ كِتَ<rule class=madda_normal>ـٰ</rule>بَهُ<rule class=madda_normal>ۥ</rule> وَر<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ ظَهۡرِهِۦ ١٠',
    10, 30, 7, 589, 526, 236, 'false'
  );
  
