    25, 30, 7, 589, 526, 236, 'false'
  );
  

-- Surah Al-Burooj
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (85, 'سُورَةُ البُرُوجِ', 'Al-Burooj', 'The Constellations', 'Meccan', 22);

  -- Ayah 1 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5910,
    'وَٱلسَّمَاۤءِ ذَاتِ ٱلۡبُرُوجِ',
    'والسماء ذات البروج',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ذَاتِ <rule class=ham_wasl>ٱ</rule>لۡبُر<rule class=madda_permissible>ُو</rule><rule class=qalaqah>ج</rule>ِ ١',
    1, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 2 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5911,
    'وَٱلۡیَوۡمِ ٱلۡمَوۡعُودِ',
    'واليوم الموعود',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡيَوۡمِ <rule class=ham_wasl>ٱ</rule>لۡمَوۡع<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ِ ٢',
    2, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 3 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5912,
    'وَشَاهِدࣲ وَمَشۡهُودࣲ',
    'وشاهد ومشهود',
    'وَشَاهِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَشۡه<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٍ ٣',
    3, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 4 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5913,
    'قُتِلَ أَصۡحَـٰبُ ٱلۡأُخۡدُودِ',
    'قتل اصحاب الاخدود',
    'قُتِلَ أَصۡحَ<rule class=madda_normal>ـٰ</rule>بُ <rule class=ham_wasl>ٱ</rule>لۡأُخۡد<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ِ ٤',
    4, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 5 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5914,
    'ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ',
    'النار ذات الوقود',
    'ٱ<rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َارِ ذَاتِ <rule class=ham_wasl>ٱ</rule>لۡوَق<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ِ ٥',
    5, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 6 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5915,
    'إِذۡ هُمۡ عَلَیۡهَا قُعُودࣱ',
    'اذ هم عليها قعود',
    'إِذۡ هُمۡ عَلَيۡهَا قُع<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٌ ٦',
    6, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 7 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5916,
    'وَهُمۡ عَلَىٰ مَا یَفۡعَلُونَ بِٱلۡمُؤۡمِنِینَ شُهُودࣱ',
    'وهم على ما يفعلون بالمؤمنين شهود',
    'وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ شُه<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٌ ٧',
    7, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 8 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5917,
    'وَمَا نَقَمُوا۟ مِنۡهُمۡ إِلَّاۤ أَن یُؤۡمِنُوا۟ بِٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَمِیدِ',
    'وما نقموا منهم الا ان يؤمنوا بالله العزيز الحميد',
    'وَمَا نَقَمُو<rule class=slnt>اۡ</rule> مِنۡهُمۡ إِلّ<rule class=madda_obligatory_monfasel>َآ</rule> أ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>ُؤۡمِنُو<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡعَزِيزِ <rule class=ham_wasl>ٱ</rule>لۡحَم<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ِ ٨',
    8, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 9 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5918,
    'ٱلَّذِی لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ',
    'الذي له ملك السماوات والارض والله على كل شيء شهيد',
    'ٱلَّذِى لَهُ<rule class=madda_normal>ۥ</rule> مُلۡكُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّمَ<rule class=madda_normal>ـٰ</rule>و<rule class=madda_normal>ٰ</rule>تِ وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ‌ۚ وَ<rule class=ham_wasl>ٱ</rule>للَّهُ عَلَىٰ كُلِّ ش<rule class=ikhafa>َىۡءٍ</rule> <rule class=ikhafa>ش</rule>َه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٩',
    9, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 10 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5919,
    'إِنَّ ٱلَّذِینَ فَتَنُوا۟ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ ثُمَّ لَمۡ یَتُوبُوا۟ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِیقِ',
    'ان الذين فتنوا المؤمنين والمؤمنات ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب الحريق',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ فَتَنُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنِينَ وَ<rule class=ham_wasl>ٱ</rule>لۡمُؤۡمِنَ<rule class=madda_normal>ـٰ</rule>تِ ثُ<rule class=ghunnah>مّ</rule>َ لَمۡ يَتُوبُو<rule class=slnt>اۡ</rule> فَلَهُمۡ عَذَابُ جَهَ<rule class=ghunnah>نّ</rule>َمَ وَلَهُمۡ عَذَابُ <rule class=ham_wasl>ٱ</rule>لۡحَر<rule class=madda_permissible>ِي</rule><rule class=qalaqah>ق</rule>ِ ١٠',
    10, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 11 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    85,
    5920,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمۡ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡكَبِیرُ',
    'ان الذين امنوا وعملوا الصالحات لهم جنات تجري من تحتها الانهار ذلك الفوز الكبير',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ لَهُمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule><rule class=ikhafa>تٌ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لۡفَوۡزُ <rule class=ham_wasl>ٱ</rule>لۡكَب<rule class=madda_permissible>ِي</rule>رُ ١١',
    11, 30, 7, 590, 527, 236, 'false'
  );
  
  -- Ayah 12 Surah Al-Burooj
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
