-- Surah At-Taariq
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (86, 'سُورَةُ الطَّارِقِ', 'At-Taariq', 'The Morning Star', 'Meccan', 17);

  -- Ayah 1 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5932,
    'وَٱلسَّمَاۤءِ وَٱلطَّارِقِ',
    'والسماء والطارق',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّارِ<rule class=qalaqah>ق</rule>ِ ١',
    1, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 2 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5933,
    'وَمَاۤ أَدۡرَىٰكَ مَا ٱلطَّارِقُ',
    'وما ادراك ما الطارق',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>كَ مَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>طَّارِ<rule class=qalaqah>ق</rule>ُ ٢',
    2, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 3 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5934,
    'ٱلنَّجۡمُ ٱلثَّاقِبُ',
    'النجم الثاقب',
    'ٱ<rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َ<rule class=qalaqah>جۡ</rule>مُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ثَّاقِ<rule class=qalaqah>ب</rule>ُ ٣',
    3, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 4 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5935,
    'إِن كُلُّ نَفۡسࣲ لَّمَّا عَلَیۡهَا حَافِظࣱ',
    'ان كل نفس لما عليها حافظ',
    'إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلُّ نَفۡ<rule class=idgham_wo_ghunnah>سٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ghunnah>مّ</rule>َا عَلَيۡهَا حَافِظٌ ٤',
    4, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 5 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5936,
    'فَلۡیَنظُرِ ٱلۡإِنسَـٰنُ مِمَّ خُلِقَ',
    'فلينظر الانسان مم خلق',
    'فَلۡيَ<rule class=ikhafa>نظ</rule>ُرِ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ مِ<rule class=ghunnah>مّ</rule>َ خُلِ<rule class=qalaqah>ق</rule>َ ٥',
    5, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 6 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5937,
    'خُلِقَ مِن مَّاۤءࣲ دَافِقࣲ',
    'خلق من ماء دافق',
    'خُلِقَ م<rule class=idgham_ghunnah>ِن</rule> <rule class=idgham_ghunnah>م</rule>ّ<rule class=madda_obligatory_mottasel>َا</rule>ٓ<rule class=ikhafa>ءٍ</rule> <rule class=ikhafa>د</rule>َافِ<rule class=qalaqah>ق</rule>ٍ ٦',
    6, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 7 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5938,
    'یَخۡرُجُ مِنۢ بَیۡنِ ٱلصُّلۡبِ وَٱلتَّرَاۤىِٕبِ',
    'يخرج من بين الصلب والترائب',
    'يَخۡرُجُ م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َيۡنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّلۡبِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِ<rule class=qalaqah>ب</rule>ِ ٧',
    7, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 8 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5939,
    'إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرࣱ',
    'انه على رجعه لقادر',
    'إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ رَ<rule class=qalaqah>جۡ</rule>عِه<rule class=madda_normal>ِۦ</rule> لَقَادِرٌ ٨',
    8, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 9 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5940,
    'یَوۡمَ تُبۡلَى ٱلسَّرَاۤىِٕرُ',
    'يوم تبلى السرائر',
    'يَوۡمَ تُ<rule class=qalaqah>بۡ</rule>لَى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّر<rule class=madda_obligatory_mottasel>َا</rule>ٓئِرُ ٩',
    9, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 10 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5941,
    'فَمَا لَهُۥ مِن قُوَّةࣲ وَلَا نَاصِرࣲ',
    'فما له من قوة ولا ناصر',
    'فَمَا لَهُ<rule class=madda_normal>ۥ</rule> مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ق</rule>ُوَّ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>و</rule>َلَا نَاصِرٍ ١٠',
    10, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 11 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5942,
    'وَٱلسَّمَاۤءِ ذَاتِ ٱلرَّجۡعِ',
    'والسماء ذات الرجع',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>سَّم<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ ذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رَّ<rule class=qalaqah>جۡ</rule>عِ ١١',
    11, 30, 7, 591, 528, 236, 'false'
  );
  
  -- Ayah 12 Surah At-Taariq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    86,
    5943,
    'وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ',
    'والارض ذات الصدع',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡأَرۡضِ ذَاتِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=qalaqah>دۡ</rule>عِ ١٢',
    12, 30, 7, 591, 528, 236, 'false'
