    'فَأَكۡثَرُوا۟ فِیهَا ٱلۡفَسَادَ',
    'فاكثروا فيها الفساد',
    'فَأَكۡثَرُو<rule class=slnt>اۡ</rule> فِيهَا <rule class=ham_wasl>ٱ</rule>لۡفَس<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>َ ١٢',
    12, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 13 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6006,
    'فَصَبَّ عَلَیۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ',
    'فصب عليهم ربك سوط عذاب',
    'فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذ<rule class=madda_permissible>َا</rule><rule class=qalaqah>ب</rule>ٍ ١٣',
    13, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 14 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6007,
    'إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ',
    'ان ربك لبالمرصاد',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّكَ لَبِ<rule class=ham_wasl>ٱ</rule>لۡمِرۡص<rule class=madda_permissible>َا</rule><rule class=qalaqah>د</rule>ِ ١٤',
    14, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 15 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6008,
    'فَأَمَّا ٱلۡإِنسَـٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَیَقُولُ رَبِّیۤ أَكۡرَمَنِ',
    'فاما الانسان اذا ما ابتلاه ربه فاكرمه ونعمه فيقول ربي اكرمن',
    'فَأَ<rule class=ghunnah>مّ</rule>َا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ إِذَا مَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَلَ<rule class=madda_normal>ـٰ</rule>هُ رَبُّهُ<rule class=madda_normal>ۥ</rule> فَأَكۡرَمَهُ<rule class=madda_normal>ۥ</rule> وَنَعَّمَهُ<rule class=madda_normal>ۥ</rule> فَيَقُولُ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَكۡرَمَنِ ١٥',
    15, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 16 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6009,
    'وَأَمَّاۤ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَیۡهِ رِزۡقَهُۥ فَیَقُولُ رَبِّیۤ أَهَـٰنَنِ',
    'واما اذا ما ابتلاه فقدر عليه رزقه فيقول ربي اهانن',
    'وَأَ<rule class=ghunnah>مّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> إِذَا مَا <rule class=ham_wasl>ٱ</rule><rule class=qalaqah>بۡ</rule>تَلَ<rule class=madda_normal>ـٰ</rule>هُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُ<rule class=madda_normal>ۥ</rule> فَيَقُولُ رَبّ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَهَ<rule class=madda_normal>ـٰ</rule>نَنِ ١٦',
    16, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 17 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6010,
    'كَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡیَتِیمَ',
    'كلا بل لا تكرمون اليتيم',
    'كَلَّا‌ۖ بَل لَّا تُكۡرِمُونَ <rule class=ham_wasl>ٱ</rule>لۡيَت<rule class=madda_permissible>ِي</rule>مَ ١٧',
    17, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 18 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6011,
    'وَلَا تَحَـٰۤضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِینِ',
    'ولا تحاضون على طعام المسكين',
    'وَلَا تَحَ<rule class=madda_necessary>ـٰٓ</rule>ضُّونَ عَلَىٰ طَعَامِ <rule class=ham_wasl>ٱ</rule>لۡمِسۡك<rule class=madda_permissible>ِي</rule>نِ ١٨',
    18, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 19 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6012,
    'وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلࣰا لَّمࣰّا',
    'وتاكلون التراث اكلا لما',
    'وَتَأۡكُلُونَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تُّرَاثَ أَكۡل<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّ<rule class=ghunnah>مّ</rule>ًا ١٩',
    19, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 20 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6013,
    'وَتُحِبُّونَ ٱلۡمَالَ حُبࣰّا جَمࣰّا',
    'وتحبون المال حبا جما',
    'وَتُحِبُّونَ <rule class=ham_wasl>ٱ</rule>لۡمَالَ حُب<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ج</rule>َ<rule class=ghunnah>مّ</rule>ًا ٢٠',
    20, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 21 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6014,
    'كَلَّاۤۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكࣰّا دَكࣰّا',
    'كلا اذا دكت الارض دكا دكا',
    'كَلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِذَا دُكَّتِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ دَك<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>د</rule>َكًّا ٢١',
    21, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 22 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6015,
    'وَجَاۤءَ رَبُّكَ وَٱلۡمَلَكُ صَفࣰّا صَفࣰّا',
    'وجاء ربك والملك صفا صفا',
    'وَج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ رَبُّكَ وَ<rule class=ham_wasl>ٱ</rule>لۡمَلَكُ صَف<rule class=ikhafa>ًّا</rule> <rule class=ikhafa>ص</rule>َفًّا ٢٢',
    22, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 23 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6016,
    'وَجِا۟یۤءَ یَوۡمَىِٕذِۭ بِجَهَنَّمَۚ یَوۡمَىِٕذࣲ یَتَذَكَّرُ ٱلۡإِنسَـٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ',
    'وجيء يومئذ بجهنم يومئذ يتذكر الانسان وانى له الذكرى',
    'وَجِ<rule class=slnt>اۡ</rule><rule class=madda_obligatory_mottasel>ىٓ</rule>ءَ يَوۡمَئِ<rule class=iqlab>ذِۭ</rule> <rule class=iqlab>ب</rule>ِجَهَ<rule class=ghunnah>نّ</rule>َمَ‌ۚ يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َتَذَكَّرُ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ وَأَ<rule class=ghunnah>نّ</rule>َىٰ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>ذِّكۡرَىٰ ٢٣',
    23, 30, 7, 593, 531, 237, 'false'
  );
  
  -- Ayah 24 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6017,
    'یَقُولُ یَـٰلَیۡتَنِی قَدَّمۡتُ لِحَیَاتِی',
    'يقول يا ليتني قدمت لحياتي',
    'يَقُولُ يَ<rule class=madda_normal>ـٰ</rule>لَيۡتَنِى قَدَّمۡتُ لِحَيَاتِى ٢٤',
    24, 30, 7, 594, 531, 237, 'false'
  );
  
  -- Ayah 25 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6018,
    'فَیَوۡمَىِٕذࣲ لَّا یُعَذِّبُ عَذَابَهُۥۤ أَحَدࣱ',
    'فيومئذ لا يعذب عذابه احد',
    'فَيَوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّا يُعَذِّبُ عَذَابَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَحَ<rule class=qalaqah>د</rule>ٌ ٢٥',
    25, 30, 7, 594, 531, 237, 'false'
  );
  
  -- Ayah 26 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6019,
    'وَلَا یُوثِقُ وَثَاقَهُۥۤ أَحَدࣱ',
    'ولا يوثق وثاقه احد',
    'وَلَا يُوثِقُ وَثَاقَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَحَ<rule class=qalaqah>د</rule>ٌ ٢٦',
    26, 30, 7, 594, 531, 237, 'false'
  );
  
  -- Ayah 27 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6020,
    'یَـٰۤأَیَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَىِٕنَّةُ',
    'يا ايتها النفس المطمئنة',
    'يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيَّتُهَا <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َفۡسُ <rule class=ham_wasl>ٱ</rule>لۡمُ<rule class=qalaqah>طۡ</rule>مَئِ<rule class=ghunnah>نّ</rule>َةُ ٢٧',
    27, 30, 7, 594, 531, 237, 'false'
  );
  
  -- Ayah 28 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6021,
    'ٱرۡجِعِیۤ إِلَىٰ رَبِّكِ رَاضِیَةࣰ مَّرۡضِیَّةࣰ',
    'ارجعي الى ربك راضية مرضية',
    'ٱرۡجِع<rule class=madda_obligatory_monfasel>ِىٓ</rule> إِلَىٰ رَبِّكِ رَاضِيَ<rule class=idgham_ghunnah>ةً</rule> <rule class=idgham_ghunnah>م</rule>َّرۡضِيَّةً ٢٨',
    28, 30, 7, 594, 531, 237, 'false'
  );
  
  -- Ayah 29 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6022,
    'فَٱدۡخُلِی فِی عِبَـٰدِی',
    'فادخلي في عبادي',
    'فَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلِى فِى عِبَ<rule class=madda_normal>ـٰ</rule>دِى ٢٩',
    29, 30, 7, 594, 531, 237, 'false'
  );
  
  -- Ayah 30 Surah Al-Fajr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    89,
    6023,
    'وَٱدۡخُلِی جَنَّتِی',
    'وادخلي جنتي',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>دۡ</rule>خُلِى جَ<rule class=ghunnah>نّ</rule>َتِى ٣٠',
    30, 30, 7, 594, 531, 237, 'false'
  );
  

-- Surah Al-Balad
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (90, 'سُورَةُ البَلَدِ', 'Al-Balad', 'The City', 'Meccan', 20);

  -- Ayah 1 Surah Al-Balad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    90,
    6024,
    'لَاۤ أُقۡسِمُ بِهَـٰذَا ٱلۡبَلَدِ',
    'لا اقسم بهذا البلد',
    'ل<rule class=madda_obligatory_monfasel>َآ</rule> أُ<rule class=qalaqah>قۡ</rule>سِمُ بِهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=qalaqah>د</rule>ِ ١',
    1, 30, 7, 594, 532, 238, 'false'
  );
  
  -- Ayah 2 Surah Al-Balad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    90,
    6025,
    'وَأَنتَ حِلُّۢ بِهَـٰذَا ٱلۡبَلَدِ',
    'وانت حل بهذا البلد',
    'وَأَ<rule class=ikhafa>نت</rule>َ حِل<rule class=iqlab>ُّۢ</rule> <rule class=iqlab>ب</rule>ِهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡبَلَ<rule class=qalaqah>د</rule>ِ ٢',
    2, 30, 7, 594, 532, 238, 'false'
  );
  
  -- Ayah 3 Surah Al-Balad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    90,
    6026,
    'وَوَالِدࣲ وَمَا وَلَدَ',
    'ووالد وما ولد',
    'وَوَالِ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>و</rule>َمَا وَلَ<rule class=qalaqah>د</rule>َ ٣',
    3, 30, 7, 594, 532, 238, 'false'
  );
  
  -- Ayah 4 Surah Al-Balad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    90,
    6027,
    'لَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ فِی كَبَدٍ',
    'لقد خلقنا الانسان في كبد',
    'لَقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ فِى كَبَ<rule class=qalaqah>د</rule>ٍ ٤',
    4, 30, 7, 594, 532, 238, 'false'
  );
  
  -- Ayah 5 Surah Al-Balad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    90,
    6028,
    'أَیَحۡسَبُ أَن لَّن یَقۡدِرَ عَلَیۡهِ أَحَدࣱ',
    'ايحسب ان لن يقدر عليه احد',
    'أَيَحۡسَبُ أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ل</rule>ّ<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َ<rule class=qalaqah>قۡ</rule>دِرَ عَلَيۡهِ أَحَ<rule class=qalaqah>د</rule>ٌ ٥',
    5, 30, 7, 594, 532, 238, 'false'
  );
  
  -- Ayah 6 Surah Al-Balad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    90,
    6029,
    'یَقُولُ أَهۡلَكۡتُ مَالࣰا لُّبَدًا',
    'يقول اهلكت مالا لبدا',
    'يَقُولُ أَهۡلَكۡتُ مَال<rule class=idgham_wo_ghunnah>اً</rule> <rule class=idgham_wo_ghunnah>ل</rule>ُّبَدًا ٦',
    6, 30, 7, 594, 532, 238, 'false'
  );
  
  -- Ayah 7 Surah Al-Balad
