    'وَقَ<rule class=qalaqah>دۡ</rule> خَابَ مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>د</rule>َسَّ<rule class=madda_normal>ـٰ</rule>هَا ١٠',
    10, 30, 7, 595, 533, 238, 'false'
  );
  
  -- Ayah 11 Surah Ash-Shams
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    91,
    6054,
    'كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَاۤ',
    'كذبت ثمود بطغواها',
    'كَذَّبَتۡ ثَمُودُ بِطَغۡوَ<rule class=madda_normal>ٮٰ</rule>هَآ ١١',
    11, 30, 7, 595, 533, 238, 'false'
  );
  
  -- Ayah 12 Surah Ash-Shams
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
