    'إِذِ <rule class=ham_wasl>ٱ</rule><rule class=iqlab>نۢب</rule>َعَثَ أَشۡقَ<rule class=madda_normal>ـٰ</rule>هَا ١٢',
    12, 30, 7, 595, 533, 238, 'false'
  );
  
  -- Ayah 13 Surah Ash-Shams
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    91,
    6056,
    'فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡیَـٰهَا',
