  -- Ayah 14 Surah Ash-Shams
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    91,
    6057,
    'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَیۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا',
    'فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسواها',
    'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِذَ<rule class=iqlab>نۢب</rule>ِهِمۡ فَسَوَّ<rule class=madda_normal>ٮٰ</rule>هَا ١٤',
    14, 30, 7, 595, 533, 238, 'false'
  );
  
  -- Ayah 15 Surah Ash-Shams
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
