-- Surah At-Tin
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (95, 'سُورَةُ التِّينِ', 'At-Tin', 'The Fig', 'Meccan', 8);

  -- Ayah 1 Surah At-Tin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    95,
    6099,
    'وَٱلتِّینِ وَٱلزَّیۡتُونِ',
    'والتين والزيتون',
    'وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تِّينِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّيۡت<rule class=madda_permissible>ُو</rule>نِ ١',
    1, 30, 7, 597, 537, 239, 'false'
  );
  
  -- Ayah 2 Surah At-Tin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    95,
    6100,
    'وَطُورِ سِینِینَ',
    'وطور سينين',
    'وَطُورِ سِين<rule class=madda_permissible>ِي</rule>نَ ٢',
    2, 30, 7, 597, 537, 239, 'false'
  );
  
  -- Ayah 3 Surah At-Tin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    95,
    6101,
    'وَهَـٰذَا ٱلۡبَلَدِ ٱلۡأَمِینِ',
    'وهذا البلد الامين',
    'وَهَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡبَلَدِ <rule class=ham_wasl>ٱ</rule>لۡأَم<rule class=madda_permissible>ِي</rule>نِ ٣',
    3, 30, 7, 597, 537, 239, 'false'
  );
  
  -- Ayah 4 Surah At-Tin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    95,
    6102,
    'لَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ فِیۤ أَحۡسَنِ تَقۡوِیمࣲ',
    'لقد خلقنا الانسان في احسن تقويم',
    'لَقَ<rule class=qalaqah>دۡ</rule> خَلَ<rule class=qalaqah>قۡ</rule>نَا <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ ف<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَحۡسَنِ تَ<rule class=qalaqah>قۡ</rule>و<rule class=madda_permissible>ِي</rule>مٍ ٤',
    4, 30, 7, 597, 537, 239, 'false'
  );
  
  -- Ayah 5 Surah At-Tin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    95,
    6103,
    'ثُمَّ رَدَدۡنَـٰهُ أَسۡفَلَ سَـٰفِلِینَ',
    'ثم رددناه اسفل سافلين',
    'ثُ<rule class=ghunnah>مّ</rule>َ رَدَ<rule class=qalaqah>دۡ</rule>نَ<rule class=madda_normal>ـٰ</rule>هُ أَسۡفَلَ سَ<rule class=madda_normal>ـٰ</rule>فِل<rule class=madda_permissible>ِي</rule>نَ ٥',
    5, 30, 7, 597, 537, 239, 'false'
  );
  
  -- Ayah 6 Surah At-Tin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    95,
    6104,
    'إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمۡ أَجۡرٌ غَیۡرُ مَمۡنُونࣲ',
    'الا الذين امنوا وعملوا الصالحات فلهم اجر غير ممنون',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ فَلَهُمۡ أَ<rule class=qalaqah>جۡ</rule>رٌ غَيۡرُ مَمۡن<rule class=madda_permissible>ُو</rule>نٍ ٦',
    6, 30, 7, 597, 537, 239, 'false'
  );
  
  -- Ayah 7 Surah At-Tin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    95,
    6105,
    'فَمَا یُكَذِّبُكَ بَعۡدُ بِٱلدِّینِ',
    'فما يكذبك بعد بالدين',
    'فَمَا يُكَذِّبُكَ بَعۡدُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ٧',
    7, 30, 7, 597, 537, 239, 'false'
  );
  
  -- Ayah 8 Surah At-Tin
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    95,
    6106,
    'أَلَیۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَـٰكِمِینَ',
    'اليس الله باحكم الحاكمين',
    'أَلَيۡسَ <rule class=ham_wasl>ٱ</rule>للَّهُ بِأَحۡكَمِ <rule class=ham_wasl>ٱ</rule>لۡحَ<rule class=madda_normal>ـٰ</rule>كِم<rule class=madda_permissible>ِي</rule>نَ ٨',
    8, 30, 7, 597, 537, 239, 'false'
  );
  

-- Surah Al-Alaq
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (96, 'سُورَةُ العَلَقِ', 'Al-Alaq', 'The Clot', 'Meccan', 19);

  -- Ayah 1 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6107,
    'ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِی خَلَقَ',
    'اقرا باسم ربك الذي خلق',
    'ٱ<rule class=qalaqah>قۡ</rule>رَأۡ بِ<rule class=ham_wasl>ٱ</rule>سۡمِ رَبِّكَ <rule class=ham_wasl>ٱ</rule>لَّذِى خَلَ<rule class=qalaqah>ق</rule>َ ١',
    1, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 2 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
