    6108,
    'خَلَقَ ٱلۡإِنسَـٰنَ مِنۡ عَلَقٍ',
    'خلق الانسان من علق',
    'خَلَقَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ مِنۡ عَلَ<rule class=qalaqah>ق</rule>ٍ ٢',
    2, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 3 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6109,
    'ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ',
    'اقرا وربك الاكرم',
    'ٱ<rule class=qalaqah>قۡ</rule>رَأۡ وَرَبُّكَ <rule class=ham_wasl>ٱ</rule>لۡأَكۡرَمُ ٣',
    3, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 4 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6110,
    'ٱلَّذِی عَلَّمَ بِٱلۡقَلَمِ',
    'الذي علم بالقلم',
    'ٱلَّذِى عَلَّمَ بِ<rule class=ham_wasl>ٱ</rule>لۡقَلَمِ ٤',
    4, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 5 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6111,
    'عَلَّمَ ٱلۡإِنسَـٰنَ مَا لَمۡ یَعۡلَمۡ',
    'علم الانسان ما لم يعلم',
    'عَلَّمَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ مَا لَمۡ يَعۡلَمۡ ٥',
    5, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 6 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6112,
    'كَلَّاۤ إِنَّ ٱلۡإِنسَـٰنَ لَیَطۡغَىٰۤ',
    'كلا ان الانسان ليطغى',
    'كَلّ<rule class=madda_obligatory_monfasel>َآ</rule> إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ لَيَ<rule class=qalaqah>طۡ</rule>غَىٰٓ ٦',
    6, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 7 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6113,
    'أَن رَّءَاهُ ٱسۡتَغۡنَىٰۤ',
    'ان راه استغنى',
    'أ<rule class=idgham_wo_ghunnah>َن</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّءَاهُ <rule class=ham_wasl>ٱ</rule>سۡتَغۡنَىٰٓ ٧',
    7, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 8 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6114,
    'إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰۤ',
    'ان الى ربك الرجعى',
    'إِ<rule class=ghunnah>نّ</rule>َ إِلَىٰ رَبِّكَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّ<rule class=qalaqah>جۡ</rule>عَىٰٓ ٨',
    8, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 9 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6115,
    'أَرَءَیۡتَ ٱلَّذِی یَنۡهَىٰ',
    'ارايت الذي ينهى',
    'أَرَءَيۡتَ <rule class=ham_wasl>ٱ</rule>لَّذِى يَنۡهَىٰ ٩',
    9, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 10 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6116,
    'عَبۡدًا إِذَا صَلَّىٰۤ',
    'عبدا اذا صلى',
    'عَ<rule class=qalaqah>بۡ</rule>دًا إِذَا صَلَّىٰٓ ١٠',
    10, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 11 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6117,
    'أَرَءَیۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰۤ',
    'ارايت ان كان على الهدى',
    'أَرَءَيۡتَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َانَ عَلَى <rule class=ham_wasl>ٱ</rule>لۡهُدَىٰٓ ١١',
    11, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 12 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6118,
    'أَوۡ أَمَرَ بِٱلتَّقۡوَىٰۤ',
    'او امر بالتقوى',
    'أَوۡ أَمَرَ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>تَّ<rule class=qalaqah>قۡ</rule>وَىٰٓ ١٢',
    12, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 13 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6119,
    'أَرَءَیۡتَ إِن كَذَّبَ وَتَوَلَّىٰۤ',
    'ارايت ان كذب وتولى',
    'أَرَءَيۡتَ إِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>َذَّبَ وَتَوَلَّىٰٓ ١٣',
    13, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 14 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6120,
    'أَلَمۡ یَعۡلَم بِأَنَّ ٱللَّهَ یَرَىٰ',
    'الم يعلم بان الله يرى',
    'أَلَمۡ يَعۡل<rule class=ikhafa_shafawi>َم</rule> <rule class=ikhafa_shafawi>ب</rule>ِأَ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>للَّهَ يَرَىٰ ١٤',
    14, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 15 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6121,
    'كَلَّا لَىِٕن لَّمۡ یَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِیَةِ',
    'كلا لئن لم ينته لنسفعا بالناصية',
    'كَلَّا لَئ<rule class=idgham_wo_ghunnah>ِن</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّمۡ يَ<rule class=ikhafa>نت</rule>َهِ لَنَسۡفَع<rule class=iqlab>َۢا</rule> <rule class=iqlab>ب</rule>ِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاصِيَةِ ١٥',
    15, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 16 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6122,
    'نَاصِیَةࣲ كَـٰذِبَةٍ خَاطِئَةࣲ',
    'ناصية كاذبة خاطئة',
    'نَاصِيَ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ك</rule>َ<rule class=madda_normal>ـٰ</rule>ذِبَةٍ خَاطِئَةٍ ١٦',
    16, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 17 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6123,
    'فَلۡیَدۡعُ نَادِیَهُۥ',
    'فليدع ناديه',
    'فَلۡيَ<rule class=qalaqah>دۡ</rule>عُ نَادِيَهُۥ ١٧',
    17, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 18 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6124,
    'سَنَدۡعُ ٱلزَّبَانِیَةَ',
    'سندع الزبانية',
    'سَنَ<rule class=qalaqah>دۡ</rule>عُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّبَانِيَةَ ١٨',
    18, 30, 7, 597, 538, 239, 'false'
  );
  
  -- Ayah 19 Surah Al-Alaq
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    96,
    6125,
    'كَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡ وَٱقۡتَرِب ۩',
    'كلا لا تطعه واسجد واقترب',
    'كَلَّا لَا تُطِعۡهُ وَ<rule class=ham_wasl>ٱ</rule>سۡجُ<rule class=qalaqah>دۡ</rule> وَ<rule class=ham_wasl>ٱ</rule><rule class=qalaqah>قۡ</rule>تَرِ<rule class=qalaqah>ب</rule> ۩ ١٩',
    19, 30, 7, 597, 538, 239, '{"id":15,"recommended":false,"obligatory":true}'
  );
  

-- Surah Al-Qadr
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (97, 'سُورَةُ القَدۡرِ', 'Al-Qadr', 'The Power, Fate', 'Meccan', 5);

  -- Ayah 1 Surah Al-Qadr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    97,
    6126,
    'إِنَّاۤ أَنزَلۡنَـٰهُ فِی لَیۡلَةِ ٱلۡقَدۡرِ',
    'انا انزلناه في ليلة القدر',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نز</rule>َلۡنَ<rule class=madda_normal>ـٰ</rule>هُ فِى لَيۡلَةِ <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=qalaqah>دۡ</rule>رِ ١',
    1, 30, 7, 598, 539, 239, 'false'
  );
  
  -- Ayah 2 Surah Al-Qadr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    97,
    6127,
    'وَمَاۤ أَدۡرَىٰكَ مَا لَیۡلَةُ ٱلۡقَدۡرِ',
    'وما ادراك ما ليلة القدر',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>كَ مَا لَيۡلَةُ <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=qalaqah>دۡ</rule>رِ ٢',
    2, 30, 7, 598, 539, 239, 'false'
  );
  
  -- Ayah 3 Surah Al-Qadr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    97,
    6128,
    'لَیۡلَةُ ٱلۡقَدۡرِ خَیۡرࣱ مِّنۡ أَلۡفِ شَهۡرࣲ',
    'ليلة القدر خير من الف شهر',
    'لَيۡلَةُ <rule class=ham_wasl>ٱ</rule>لۡقَ<rule class=qalaqah>دۡ</rule>رِ خَيۡ<rule class=idgham_ghunnah>رٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنۡ أَلۡفِ شَهۡرٍ ٣',
    3, 30, 7, 598, 539, 239, 'false'
  );
  
  -- Ayah 4 Surah Al-Qadr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    97,
    6129,
    'تَنَزَّلُ ٱلۡمَلَـٰۤىِٕكَةُ وَٱلرُّوحُ فِیهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرࣲ',
    'تنزل الملائكة والروح فيها باذن ربهم من كل امر',
    'تَنَزَّلُ <rule class=ham_wasl>ٱ</rule>لۡمَلَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَةُ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>رُّوحُ فِيهَا بِإِذۡنِ رَبِّه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ك</rule>ُلِّ أَمۡرٍ ٤',
    4, 30, 7, 598, 539, 239, 'false'
  );
  
  -- Ayah 5 Surah Al-Qadr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    97,
    6130,
    'سَلَـٰمٌ هِیَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ',
    'سلام هي حتى مطلع الفجر',
    'سَلَ<rule class=madda_normal>ـٰ</rule>مٌ هِىَ حَتَّىٰ مَ<rule class=qalaqah>طۡ</rule>لَعِ <rule class=ham_wasl>ٱ</rule>لۡفَ<rule class=qalaqah>جۡ</rule>رِ ٥',
    5, 30, 7, 598, 539, 239, 'false'
  );
  

-- Surah Al-Bayyina
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (98, 'سُورَةُ البَيِّنَةِ', 'Al-Bayyina', 'The Evidence', 'Medinan', 8);

  -- Ayah 1 Surah Al-Bayyina
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    98,
    6131,
    'لَمۡ یَكُنِ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ وَٱلۡمُشۡرِكِینَ مُنفَكِّینَ حَتَّىٰ تَأۡتِیَهُمُ ٱلۡبَیِّنَةُ',
    'لم يكن الذين كفروا من اهل الكتاب والمشركين منفكين حتى تاتيهم البينة',
    'لَمۡ يَكُنِ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ مُ<rule class=ikhafa>نف</rule>َكِّينَ حَتَّىٰ تَأۡتِيَهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَةُ ١',
    1, 30, 7, 598, 540, 239, 'false'
  );
  
  -- Ayah 2 Surah Al-Bayyina
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    98,
    6132,
    'رَسُولࣱ مِّنَ ٱللَّهِ یَتۡلُوا۟ صُحُفࣰا مُّطَهَّرَةࣰ',
    'رسول من الله يتلو صحفا مطهرة',
    'رَسُو<rule class=idgham_ghunnah>لٌ</rule> <rule class=idgham_ghunnah>م</rule>ِّنَ <rule class=ham_wasl>ٱ</rule>للَّهِ يَتۡلُو<rule class=slnt>اۡ</rule> صُحُ<rule class=idgham_ghunnah>فًا</rule> <rule class=idgham_ghunnah>م</rule>ُّطَهَّرَةً ٢',
    2, 30, 7, 598, 540, 239, 'false'
  );
  
  -- Ayah 3 Surah Al-Bayyina
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    98,
    6133,
    'فِیهَا كُتُبࣱ قَیِّمَةࣱ',
    'فيها كتب قيمة',
    'فِيهَا كُتُ<rule class=ikhafa>بٌ</rule> <rule class=ikhafa>ق</rule>َيِّمَةٌ ٣',
    3, 30, 7, 598, 540, 239, 'false'
  );
  
  -- Ayah 4 Surah Al-Bayyina
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    98,
    6134,
    'وَمَا تَفَرَّقَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَةُ',
    'وما تفرق الذين اوتوا الكتاب الا من بعد ما جاءتهم البينة',
    'وَمَا تَفَرَّقَ <rule class=ham_wasl>ٱ</rule>لَّذِينَ أُوتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بَ إِلَّا م<rule class=iqlab>ِنۢ</rule> <rule class=iqlab>ب</rule>َعۡدِ مَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَتۡهُمُ <rule class=ham_wasl>ٱ</rule>لۡبَيِّنَةُ ٤',
    4, 30, 7, 598, 540, 239, 'false'
  );
  
  -- Ayah 5 Surah Al-Bayyina
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    98,
    6135,
    'وَمَاۤ أُمِرُوۤا۟ إِلَّا لِیَعۡبُدُوا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ حُنَفَاۤءَ وَیُقِیمُوا۟ ٱلصَّلَوٰةَ وَیُؤۡتُوا۟ ٱلزَّكَوٰةَۚ وَذَ ٰ⁠لِكَ دِینُ ٱلۡقَیِّمَةِ',
    'وما امروا الا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاة ويؤتوا الزكاة وذلك دين القيمة',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أُمِر<rule class=madda_obligatory_mottasel>ُوٓ</rule><rule class=slnt>اۡ</rule> إِلَّا لِيَعۡبُدُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule>للَّهَ مُخۡلِصِينَ لَهُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دِّينَ حُنَف<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ وَيُقِيمُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّلَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ وَيُؤۡتُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>زَّكَ<rule class=slnt>و</rule><rule class=madda_normal>ٰ</rule>ةَ‌ۚ وَذ<rule class=madda_normal>ٰ</rule>لِكَ دِينُ <rule class=ham_wasl>ٱ</rule>لۡقَيِّمَةِ ٥',
    5, 30, 7, 598, 540, 239, 'false'
  );
  
  -- Ayah 6 Surah Al-Bayyina
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    98,
    6136,
    'إِنَّ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ وَٱلۡمُشۡرِكِینَ فِی نَارِ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۤۚ أُو۟لَـٰۤىِٕكَ هُمۡ شَرُّ ٱلۡبَرِیَّةِ',
    'ان الذين كفروا من اهل الكتاب والمشركين في نار جهنم خالدين فيها اولئك هم شر البرية',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ كَفَرُو<rule class=slnt>اۡ</rule> مِنۡ أَهۡلِ <rule class=ham_wasl>ٱ</rule>لۡكِتَ<rule class=madda_normal>ـٰ</rule>بِ وَ<rule class=ham_wasl>ٱ</rule>لۡمُشۡرِكِينَ فِى نَارِ جَهَ<rule class=ghunnah>نّ</rule>َمَ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ‌ۚ</rule> أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمۡ شَرُّ <rule class=ham_wasl>ٱ</rule>لۡبَرِيَّةِ ٦',
    6, 30, 7, 598, 540, 239, 'false'
  );
  
  -- Ayah 7 Surah Al-Bayyina
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    98,
    6137,
    'إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰۤىِٕكَ هُمۡ خَیۡرُ ٱلۡبَرِیَّةِ',
    'ان الذين امنوا وعملوا الصالحات اولئك هم خير البرية',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ أُ<rule class=slnt>وۡ</rule>لَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>ئِكَ هُمۡ خَيۡرُ <rule class=ham_wasl>ٱ</rule>لۡبَرِيَّةِ ٧',
    7, 30, 7, 598, 540, 239, 'false'
  );
  
  -- Ayah 8 Surah Al-Bayyina
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    98,
    6138,
    'جَزَاۤؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّـٰتُ عَدۡنࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ رَّضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُۚ ذَ ٰ⁠لِكَ لِمَنۡ خَشِیَ رَبَّهُۥ',
    'جزاؤهم عند ربهم جنات عدن تجري من تحتها الانهار خالدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك لمن خشي ربه',
    'جَز<rule class=madda_obligatory_mottasel>َا</rule>ٓؤُهُمۡ عِ<rule class=ikhafa>ند</rule>َ رَبِّهِمۡ جَ<rule class=ghunnah>نّ</rule>َ<rule class=madda_normal>ـٰ</rule>تُ عَ<rule class=qalaqah>دۡ</rule><rule class=ikhafa>نٍ</rule> <rule class=ikhafa>ت</rule>َ<rule class=qalaqah>جۡ</rule>رِى مِ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ت</rule>َحۡتِهَا <rule class=ham_wasl>ٱ</rule>لۡأَنۡهَ<rule class=madda_normal>ـٰ</rule>رُ خَ<rule class=madda_normal>ـٰ</rule>لِدِينَ فِيه<rule class=madda_obligatory_monfasel>َآ</rule> أَبَ<rule class=idgham_wo_ghunnah>دًا‌ۖ</rule> <rule class=idgham_wo_ghunnah>ر</rule>َّضِىَ <rule class=ham_wasl>ٱ</rule>للَّهُ عَنۡهُمۡ وَرَضُو<rule class=slnt>اۡ</rule> عَنۡهُ‌ۚ ذ<rule class=madda_normal>ٰ</rule>لِكَ لِمَنۡ خَشِىَ رَبَّهُۥ ٨',
    8, 30, 7, 599, 540, 239, 'false'
  );
  

-- Surah Az-Zalzala
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (99, 'سُورَةُ الزَّلۡزَلَةِ', 'Az-Zalzala', 'The Earthquake', 'Medinan', 8);

  -- Ayah 1 Surah Az-Zalzala
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    99,
    6139,
    'إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا',
    'اذا زلزلت الارض زلزالها',
    'إِذَا زُلۡزِلَتِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ زِلۡزَالَهَا ١',
    1, 30, 7, 599, 541, 239, 'false'
  );
  
  -- Ayah 2 Surah Az-Zalzala
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    99,
    6140,
    'وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا',
    'واخرجت الارض اثقالها',
    'وَأَخۡرَجَتِ <rule class=ham_wasl>ٱ</rule>لۡأَرۡضُ أَثۡقَالَهَا ٢',
    2, 30, 7, 599, 541, 239, 'false'
  );
  
  -- Ayah 3 Surah Az-Zalzala
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    99,
    6141,
    'وَقَالَ ٱلۡإِنسَـٰنُ مَا لَهَا',
    'وقال الانسان ما لها',
    'وَقَالَ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نُ مَا لَهَا ٣',
    3, 30, 7, 599, 541, 239, 'false'
  );
  
  -- Ayah 4 Surah Az-Zalzala
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    99,
    6142,
    'یَوۡمَىِٕذࣲ تُحَدِّثُ أَخۡبَارَهَا',
    'يومئذ تحدث اخبارها',
    'يَوۡمَئِ<rule class=ikhafa>ذٍ</rule> <rule class=ikhafa>ت</rule>ُحَدِّثُ أَخۡبَارَهَا ٤',
    4, 30, 7, 599, 541, 239, 'false'
  );
  
  -- Ayah 5 Surah Az-Zalzala
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    99,
    6143,
    'بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا',
    'بان ربك اوحى لها',
    'بِأَ<rule class=ghunnah>نّ</rule>َ رَبَّكَ أَوۡحَىٰ لَهَا ٥',
    5, 30, 7, 599, 541, 239, 'false'
  );
  
  -- Ayah 6 Surah Az-Zalzala
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    99,
    6144,
    'یَوۡمَىِٕذࣲ یَصۡدُرُ ٱلنَّاسُ أَشۡتَاتࣰا لِّیُرَوۡا۟ أَعۡمَـٰلَهُمۡ',
    'يومئذ يصدر الناس اشتاتا ليروا اعمالهم',
    'يَوۡمَئِ<rule class=idgham_ghunnah>ذٍ</rule> <rule class=idgham_ghunnah>ي</rule>َصۡدُرُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ أَشۡتَا<rule class=idgham_wo_ghunnah>تًا</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّيُرَوۡ<rule class=slnt>اۡ</rule> أَعۡمَ<rule class=madda_normal>ـٰ</rule>لَهُمۡ ٦',
    6, 30, 7, 599, 541, 239, 'false'
  );
  
  -- Ayah 7 Surah Az-Zalzala
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    99,
    6145,
    'فَمَن یَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَیۡرࣰا یَرَهُۥ',
    'فمن يعمل مثقال ذرة خيرا يره',
    'فَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡ<rule class=idgham_ghunnah>رًا</rule> <rule class=idgham_ghunnah>ي</rule>َرَهُۥ ٧',
    7, 30, 7, 599, 541, 239, 'false'
  );
  
  -- Ayah 8 Surah Az-Zalzala
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    99,
    6146,
    'وَمَن یَعۡمَلۡ مِثۡقَالَ ذَرَّةࣲ شَرࣰّا یَرَهُۥ',
    'ومن يعمل مثقال ذرة شرا يره',
    'وَم<rule class=idgham_ghunnah>َن</rule> <rule class=idgham_ghunnah>ي</rule>َعۡمَلۡ مِثۡقَالَ ذَرَّ<rule class=ikhafa>ةٍ</rule> <rule class=ikhafa>ش</rule>َر<rule class=idgham_ghunnah>ًّا</rule> <rule class=idgham_ghunnah>ي</rule>َرَهُۥ ٨',
    8, 30, 7, 599, 541, 239, 'false'
  );
  

-- Surah Al-Aadiyaat
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (100, 'سُورَةُ العَادِيَاتِ', 'Al-Aadiyaat', 'The Chargers', 'Meccan', 11);

  -- Ayah 1 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6147,
    'وَٱلۡعَـٰدِیَـٰتِ ضَبۡحࣰا',
    'والعاديات ضبحا',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡعَ<rule class=madda_normal>ـٰ</rule>دِيَ<rule class=madda_normal>ـٰ</rule>تِ ضَ<rule class=qalaqah>بۡ</rule>حًا ١',
    1, 30, 7, 599, 542, 239, 'false'
  );
  
  -- Ayah 2 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6148,
    'فَٱلۡمُورِیَـٰتِ قَدۡحࣰا',
    'فالموريات قدحا',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡمُورِيَ<rule class=madda_normal>ـٰ</rule>تِ قَ<rule class=qalaqah>دۡ</rule>حًا ٢',
    2, 30, 7, 599, 542, 239, 'false'
  );
  
  -- Ayah 3 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6149,
    'فَٱلۡمُغِیرَ ٰ⁠تِ صُبۡحࣰا',
    'فالمغيرات صبحا',
    'فَ<rule class=ham_wasl>ٱ</rule>لۡمُغِير<rule class=madda_normal>ٰ</rule>تِ صُ<rule class=qalaqah>بۡ</rule>حًا ٣',
    3, 30, 7, 599, 542, 239, 'false'
  );
  
  -- Ayah 4 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6150,
    'فَأَثَرۡنَ بِهِۦ نَقۡعࣰا',
    'فاثرن به نقعا',
    'فَأَثَرۡنَ بِه<rule class=madda_normal>ِۦ</rule> نَ<rule class=qalaqah>قۡ</rule>عًا ٤',
    4, 30, 7, 599, 542, 239, 'false'
  );
  
  -- Ayah 5 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6151,
    'فَوَسَطۡنَ بِهِۦ جَمۡعًا',
    'فوسطن به جمعا',
    'فَوَسَ<rule class=qalaqah>طۡ</rule>نَ بِه<rule class=madda_normal>ِۦ</rule> جَمۡعًا ٥',
    5, 30, 7, 599, 542, 239, 'false'
  );
  
  -- Ayah 6 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6152,
    'إِنَّ ٱلۡإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودࣱ',
    'ان الانسان لربه لكنود',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ لِرَبِّه<rule class=madda_normal>ِۦ</rule> لَكَن<rule class=madda_permissible>ُو</rule><rule class=qalaqah>د</rule>ٌ ٦',
    6, 30, 7, 599, 542, 239, 'false'
  );
  
  -- Ayah 7 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6153,
    'وَإِنَّهُۥ عَلَىٰ ذَ ٰ⁠لِكَ لَشَهِیدࣱ',
    'وانه على ذلك لشهيد',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> عَلَىٰ ذ<rule class=madda_normal>ٰ</rule>لِكَ لَشَه<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٧',
    7, 30, 7, 599, 542, 239, 'false'
  );
  
  -- Ayah 8 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6154,
    'وَإِنَّهُۥ لِحُبِّ ٱلۡخَیۡرِ لَشَدِیدٌ',
    'وانه لحب الخير لشديد',
    'وَإِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> لِحُبِّ <rule class=ham_wasl>ٱ</rule>لۡخَيۡرِ لَشَد<rule class=madda_permissible>ِي</rule><rule class=qalaqah>د</rule>ٌ ٨',
    8, 30, 7, 599, 542, 239, 'false'
  );
  
  -- Ayah 9 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6155,
    '۞ أَفَلَا یَعۡلَمُ إِذَا بُعۡثِرَ مَا فِی ٱلۡقُبُورِ',
    'افلا يعلم اذا بعثر ما في القبور',
    '۞أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِى <rule class=ham_wasl>ٱ</rule>لۡقُب<rule class=madda_permissible>ُو</rule>رِ ٩',
    9, 30, 7, 599, 542, 240, 'false'
  );
  
  -- Ayah 10 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6156,
    'وَحُصِّلَ مَا فِی ٱلصُّدُورِ',
    'وحصل ما في الصدور',
    'وَحُصِّلَ مَا فِى <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صُّد<rule class=madda_permissible>ُو</rule>رِ ١٠',
    10, 30, 7, 600, 542, 240, 'false'
  );
  
  -- Ayah 11 Surah Al-Aadiyaat
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    100,
    6157,
    'إِنَّ رَبَّهُم بِهِمۡ یَوۡمَىِٕذࣲ لَّخَبِیرُۢ',
    'ان ربهم بهم يومئذ لخبير',
    'إِ<rule class=ghunnah>نّ</rule>َ رَبَّه<rule class=ikhafa_shafawi>ُم</rule> <rule class=ikhafa_shafawi>ب</rule>ِهِمۡ يَوۡمَئِ<rule class=idgham_wo_ghunnah>ذٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>َّخَب<rule class=madda_permissible>ِي</rule>رُۢ ١١',
    11, 30, 7, 600, 542, 240, 'false'
  );
  

-- Surah Al-Qaaria
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (101, 'سُورَةُ القَارِعَةِ', 'Al-Qaaria', 'The Calamity', 'Meccan', 11);

  -- Ayah 1 Surah Al-Qaaria
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    101,
    6158,
    'ٱلۡقَارِعَةُ',
    'القارعة',
    'ٱلۡقَارِعَةُ ١',
    1, 30, 7, 600, 543, 240, 'false'
  );
  
  -- Ayah 2 Surah Al-Qaaria
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    101,
    6159,
    'مَا ٱلۡقَارِعَةُ',
    'ما القارعة',
    'مَا <rule class=ham_wasl>ٱ</rule>لۡقَارِعَةُ ٢',
    2, 30, 7, 600, 543, 240, 'false'
  );
  
  -- Ayah 3 Surah Al-Qaaria
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    101,
    6160,
    'وَمَاۤ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ',
    'وما ادراك ما القارعة',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>كَ مَا <rule class=ham_wasl>ٱ</rule>لۡقَارِعَةُ ٣',
    3, 30, 7, 600, 543, 240, 'false'
  );
  
  -- Ayah 4 Surah Al-Qaaria
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    101,
    6161,
    'یَوۡمَ یَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ',
    'يوم يكون الناس كالفراش المبثوث',
    'يَوۡمَ يَكُونُ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسُ كَ<rule class=ham_wasl>ٱ</rule>لۡفَرَاشِ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=qalaqah>بۡ</rule>ث<rule class=madda_permissible>ُو</rule>ثِ ٤',
    4, 30, 7, 600, 543, 240, 'false'
  );
  
  -- Ayah 5 Surah Al-Qaaria
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    101,
    6162,
    'وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ',
    'وتكون الجبال كالعهن المنفوش',
    'وَتَكُونُ <rule class=ham_wasl>ٱ</rule>لۡجِبَالُ كَ<rule class=ham_wasl>ٱ</rule>لۡعِهۡنِ <rule class=ham_wasl>ٱ</rule>لۡمَ<rule class=ikhafa>نف</rule><rule class=madda_permissible>ُو</rule>شِ ٥',
    5, 30, 7, 600, 543, 240, 'false'
  );
  
  -- Ayah 6 Surah Al-Qaaria
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    101,
    6163,
    'فَأَمَّا مَن ثَقُلَتۡ مَوَ ٰ⁠زِینُهُۥ',
    'فاما من ثقلت موازينه',
    'فَأَ<rule class=ghunnah>مّ</rule>َا مَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ث</rule>َقُلَتۡ مَو<rule class=madda_normal>ٰ</rule>زِينُهُۥ ٦',
