    6, 30, 7, 600, 544, 240, 'false'
  );
  
  -- Ayah 7 Surah At-Takaathur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    102,
    6175,
    'ثُمَّ لَتَرَوُنَّهَا عَیۡنَ ٱلۡیَقِینِ',
    'ثم لترونها عين اليقين',
    'ثُ<rule class=ghunnah>مّ</rule>َ لَتَرَوُ<rule class=ghunnah>نّ</rule>َهَا عَيۡنَ <rule class=ham_wasl>ٱ</rule>لۡيَق<rule class=madda_permissible>ِي</rule>نِ ٧',
    7, 30, 7, 600, 544, 240, 'false'
  );
  
  -- Ayah 8 Surah At-Takaathur
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    102,
    6176,
    'ثُمَّ لَتُسۡـَٔلُنَّ یَوۡمَىِٕذٍ عَنِ ٱلنَّعِیمِ',
    'ثم لتسالن يومئذ عن النعيم',
    'ثُ<rule class=ghunnah>مّ</rule>َ لَتُسۡــَٔلُ<rule class=ghunnah>نّ</rule>َ يَوۡمَئِذٍ عَنِ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َع<rule class=madda_permissible>ِي</rule>مِ ٨',
    8, 30, 7, 600, 544, 240, 'false'
  );
  

-- Surah Al-Asr
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (103, 'سُورَةُ العَصۡرِ', 'Al-Asr', 'The Declining Day, Epoch', 'Meccan', 3);

  -- Ayah 1 Surah Al-Asr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    103,
    6177,
    'وَٱلۡعَصۡرِ',
    'والعصر',
    'وَ<rule class=ham_wasl>ٱ</rule>لۡعَصۡرِ ١',
    1, 30, 7, 601, 545, 240, 'false'
  );
  
  -- Ayah 2 Surah Al-Asr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    103,
    6178,
    'إِنَّ ٱلۡإِنسَـٰنَ لَفِی خُسۡرٍ',
    'ان الانسان لفي خسر',
    'إِ<rule class=ghunnah>نّ</rule>َ <rule class=ham_wasl>ٱ</rule>لۡإِ<rule class=ikhafa>نس</rule>َ<rule class=madda_normal>ـٰ</rule>نَ لَفِى خُسۡرٍ ٢',
    2, 30, 7, 601, 545, 240, 'false'
  );
  
  -- Ayah 3 Surah Al-Asr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    103,
    6179,
    'إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوۡا۟ بِٱلۡحَقِّ وَتَوَاصَوۡا۟ بِٱلصَّبۡرِ',
    'الا الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر',
    'إِلَّا <rule class=ham_wasl>ٱ</rule>لَّذِينَ ءَامَنُو<rule class=slnt>اۡ</rule> وَعَمِلُو<rule class=slnt>اۡ</rule> <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=madda_normal>ـٰ</rule>لِحَ<rule class=madda_normal>ـٰ</rule>تِ وَتَوَاصَوۡ<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule>لۡحَقِّ وَتَوَاصَوۡ<rule class=slnt>اۡ</rule> بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صَّ<rule class=qalaqah>بۡ</rule>رِ ٣',
    3, 30, 7, 601, 545, 240, 'false'
  );
  

-- Surah Al-Humaza
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (104, 'سُورَةُ الهُمَزَةِ', 'Al-Humaza', 'The Traducer', 'Meccan', 9);

  -- Ayah 1 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6180,
    'وَیۡلࣱ لِّكُلِّ هُمَزَةࣲ لُّمَزَةٍ',
    'ويل لكل همزة لمزة',
    'وَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّكُلِّ هُمَزَ<rule class=idgham_wo_ghunnah>ةٍ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ُّمَزَةٍ ١',
    1, 30, 7, 601, 546, 240, 'false'
  );
  
  -- Ayah 2 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6181,
    'ٱلَّذِی جَمَعَ مَالࣰا وَعَدَّدَهُۥ',
    'الذي جمع مالا وعدده',
    'ٱلَّذِى جَمَعَ مَال<rule class=idgham_ghunnah>اً</rule> <rule class=idgham_ghunnah>و</rule>َعَدَّدَهُۥ ٢',
    2, 30, 7, 601, 546, 240, 'false'
  );
  
  -- Ayah 3 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6182,
    'یَحۡسَبُ أَنَّ مَالَهُۥۤ أَخۡلَدَهُۥ',
    'يحسب ان ماله اخلده',
    'يَحۡسَبُ أَ<rule class=ghunnah>نّ</rule>َ مَالَهُ<rule class=madda_obligatory_monfasel>ۥٓ</rule> أَخۡلَدَهُۥ ٣',
    3, 30, 7, 601, 546, 240, 'false'
  );
  
  -- Ayah 4 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6183,
    'كَلَّاۖ لَیُنۢبَذَنَّ فِی ٱلۡحُطَمَةِ',
    'كلا لينبذن في الحطمة',
    'كَلَّا‌ۖ لَيُ<rule class=iqlab>نۢب</rule>َذَ<rule class=ghunnah>نّ</rule>َ فِى <rule class=ham_wasl>ٱ</rule>لۡحُطَمَةِ ٤',
    4, 30, 7, 601, 546, 240, 'false'
  );
  
  -- Ayah 5 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6184,
    'وَمَاۤ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ',
    'وما ادراك ما الحطمة',
    'وَم<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=qalaqah>دۡ</rule>رَ<rule class=madda_normal>ٮٰ</rule>كَ مَا <rule class=ham_wasl>ٱ</rule>لۡحُطَمَةُ ٥',
    5, 30, 7, 601, 546, 240, 'false'
  );
  
  -- Ayah 6 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6185,
    'نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ',
    'نار الله الموقدة',
    'نَارُ <rule class=ham_wasl>ٱ</rule>للَّهِ <rule class=ham_wasl>ٱ</rule>لۡمُوقَدَةُ ٦',
    6, 30, 7, 601, 546, 240, 'false'
  );
  
  -- Ayah 7 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6186,
    'ٱلَّتِی تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ',
    'التي تطلع على الافئدة',
    'ٱلَّتِى تَطَّلِعُ عَلَى <rule class=ham_wasl>ٱ</rule>لۡأَفۡــِٔدَةِ ٧',
    7, 30, 7, 601, 546, 240, 'false'
  );
  
  -- Ayah 8 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6187,
    'إِنَّهَا عَلَیۡهِم مُّؤۡصَدَةࣱ',
    'انها عليهم مؤصدة',
    'إِ<rule class=ghunnah>نّ</rule>َهَا عَلَيۡه<rule class=idgham_shafawi>ِم</rule> <rule class=idgham_shafawi>م</rule>ُّؤۡصَدَةٌ ٨',
    8, 30, 7, 601, 546, 240, 'false'
  );
  
  -- Ayah 9 Surah Al-Humaza
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    104,
    6188,
    'فِی عَمَدࣲ مُّمَدَّدَةِۭ',
    'في عمد ممددة',
    'فِى عَمَ<rule class=idgham_ghunnah>دٍ</rule> <rule class=idgham_ghunnah>م</rule>ُّمَدَّدَةِۭ ٩',
    9, 30, 7, 601, 546, 240, 'false'
  );
  

-- Surah Al-Fil
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (105, 'سُورَةُ الفِيلِ', 'Al-Fil', 'The Elephant', 'Meccan', 5);

  -- Ayah 1 Surah Al-Fil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    105,
    6189,
    'أَلَمۡ تَرَ كَیۡفَ فَعَلَ رَبُّكَ بِأَصۡحَـٰبِ ٱلۡفِیلِ',
    'الم تر كيف فعل ربك باصحاب الفيل',
    'أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَ<rule class=madda_normal>ـٰ</rule>بِ <rule class=ham_wasl>ٱ</rule>لۡف<rule class=madda_permissible>ِي</rule>لِ ١',
    1, 30, 7, 601, 547, 240, 'false'
  );
  
  -- Ayah 2 Surah Al-Fil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    105,
    6190,
    'أَلَمۡ یَجۡعَلۡ كَیۡدَهُمۡ فِی تَضۡلِیلࣲ',
    'الم يجعل كيدهم في تضليل',
    'أَلَمۡ يَ<rule class=qalaqah>جۡ</rule>عَلۡ كَيۡدَهُمۡ فِى تَضۡل<rule class=madda_permissible>ِي</rule>لٍ ٢',
    2, 30, 7, 601, 547, 240, 'false'
  );
  
  -- Ayah 3 Surah Al-Fil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    105,
    6191,
    'وَأَرۡسَلَ عَلَیۡهِمۡ طَیۡرًا أَبَابِیلَ',
    'وارسل عليهم طيرا ابابيل',
    'وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَاب<rule class=madda_permissible>ِي</rule>لَ ٣',
    3, 30, 7, 601, 547, 240, 'false'
  );
  
  -- Ayah 4 Surah Al-Fil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    105,
    6192,
    'تَرۡمِیهِم بِحِجَارَةࣲ مِّن سِجِّیلࣲ',
    'ترميهم بحجارة من سجيل',
    'تَرۡمِيه<rule class=ikhafa_shafawi>ِم</rule> <rule class=ikhafa_shafawi>ب</rule>ِحِجَارَ<rule class=idgham_ghunnah>ةٍ</rule> <rule class=idgham_ghunnah>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>س</rule>ِجّ<rule class=madda_permissible>ِي</rule>لٍ ٤',
    4, 30, 7, 601, 547, 240, 'false'
  );
  
  -- Ayah 5 Surah Al-Fil
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    105,
    6193,
    'فَجَعَلَهُمۡ كَعَصۡفࣲ مَّأۡكُولِۭ',
    'فجعلهم كعصف ماكول',
    'فَجَعَلَهُمۡ كَعَصۡ<rule class=idgham_ghunnah>فٍ</rule> <rule class=idgham_ghunnah>م</rule>َّأۡك<rule class=madda_permissible>ُو</rule>لِۭ ٥',
    5, 30, 7, 601, 547, 240, 'false'
  );
  

-- Surah Quraish
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (106, 'سُورَةُ قُرَيۡشٍ', 'Quraish', 'Quraysh', 'Meccan', 4);

  -- Ayah 1 Surah Quraish
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    106,
    6194,
    'لِإِیلَـٰفِ قُرَیۡشٍ',
    'لايلاف قريش',
    'لِإِيلَ<rule class=madda_normal>ـٰ</rule>فِ قُر<rule class=madda_permissible>َي</rule>ۡشٍ ١',
    1, 30, 7, 602, 548, 240, 'false'
  );
  
  -- Ayah 2 Surah Quraish
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    106,
    6195,
    'إِۦلَـٰفِهِمۡ رِحۡلَةَ ٱلشِّتَاۤءِ وَٱلصَّیۡفِ',
    'ايلافهم رحلة الشتاء والصيف',
    'إ<rule class=madda_normal>ِۦ</rule>لَ<rule class=madda_normal>ـٰ</rule>فِهِمۡ رِحۡلَةَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>شِّت<rule class=madda_obligatory_mottasel>َا</rule>ٓءِ وَ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>صّ<rule class=madda_permissible>َي</rule>ۡفِ ٢',
    2, 30, 7, 602, 548, 240, 'false'
  );
  
  -- Ayah 3 Surah Quraish
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    106,
    6196,
    'فَلۡیَعۡبُدُوا۟ رَبَّ هَـٰذَا ٱلۡبَیۡتِ',
    'فليعبدوا رب هذا البيت',
    'فَلۡيَعۡبُدُو<rule class=slnt>اۡ</rule> رَبَّ هَ<rule class=madda_normal>ـٰ</rule>ذَا <rule class=ham_wasl>ٱ</rule>لۡب<rule class=madda_permissible>َي</rule>ۡتِ ٣',
    3, 30, 7, 602, 548, 240, 'false'
  );
  
  -- Ayah 4 Surah Quraish
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    106,
    6197,
    'ٱلَّذِیۤ أَطۡعَمَهُم مِّن جُوعࣲ وَءَامَنَهُم مِّنۡ خَوۡفِۭ',
    'الذي اطعمهم من جوع وامنهم من خوف',
    'ٱلَّذ<rule class=madda_obligatory_monfasel>ِىٓ</rule> أَ<rule class=qalaqah>طۡ</rule>عَمَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ج</rule>ُو<rule class=idgham_ghunnah>عٍ</rule> <rule class=idgham_ghunnah>و</rule>َءَامَنَه<rule class=idgham_shafawi>ُم</rule> <rule class=idgham_shafawi>م</rule>ِّنۡ خ<rule class=madda_permissible>َو</rule>ۡفِۭ ٤',
    4, 30, 7, 602, 548, 240, 'false'
  );
  

-- Surah Al-Maaun
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (107, 'سُورَةُ المَاعُونِ', 'Al-Maaun', 'Almsgiving', 'Meccan', 7);

  -- Ayah 1 Surah Al-Maaun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    107,
    6198,
    'أَرَءَیۡتَ ٱلَّذِی یُكَذِّبُ بِٱلدِّینِ',
    'ارايت الذي يكذب بالدين',
    'أَرَءَيۡتَ <rule class=ham_wasl>ٱ</rule>لَّذِى يُكَذِّبُ بِ<rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule>دّ<rule class=madda_permissible>ِي</rule>نِ ١',
    1, 30, 7, 602, 549, 240, 'false'
  );
  
  -- Ayah 2 Surah Al-Maaun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    107,
    6199,
    'فَذَ ٰ⁠لِكَ ٱلَّذِی یَدُعُّ ٱلۡیَتِیمَ',
    'فذلك الذي يدع اليتيم',
    'فَذ<rule class=madda_normal>ٰ</rule>لِكَ <rule class=ham_wasl>ٱ</rule>لَّذِى يَدُعُّ <rule class=ham_wasl>ٱ</rule>لۡيَت<rule class=madda_permissible>ِي</rule>مَ ٢',
    2, 30, 7, 602, 549, 240, 'false'
  );
  
  -- Ayah 3 Surah Al-Maaun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    107,
    6200,
    'وَلَا یَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِینِ',
    'ولا يحض على طعام المسكين',
    'وَلَا يَحُضُّ عَلَىٰ طَعَامِ <rule class=ham_wasl>ٱ</rule>لۡمِسۡك<rule class=madda_permissible>ِي</rule>نِ ٣',
    3, 30, 7, 602, 549, 240, 'false'
  );
  
  -- Ayah 4 Surah Al-Maaun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    107,
    6201,
    'فَوَیۡلࣱ لِّلۡمُصَلِّینَ',
    'فويل للمصلين',
    'فَوَيۡ<rule class=idgham_wo_ghunnah>لٌ</rule> <rule class=idgham_wo_ghunnah>ل</rule>ِّلۡمُصَلّ<rule class=madda_permissible>ِي</rule>نَ ٤',
    4, 30, 7, 602, 549, 240, 'false'
  );
  
  -- Ayah 5 Surah Al-Maaun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    107,
    6202,
    'ٱلَّذِینَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ',
    'الذين هم عن صلاتهم ساهون',
    'ٱلَّذِينَ هُمۡ عَ<rule class=ikhafa>ن</rule> <rule class=ikhafa>ص</rule>َلَاتِهِمۡ سَاه<rule class=madda_permissible>ُو</rule>نَ ٥',
    5, 30, 7, 602, 549, 240, 'false'
  );
  
  -- Ayah 6 Surah Al-Maaun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    107,
    6203,
    'ٱلَّذِینَ هُمۡ یُرَاۤءُونَ',
    'الذين هم يراءون',
    'ٱلَّذِينَ هُمۡ يُر<rule class=madda_obligatory_mottasel>َا</rule>ٓء<rule class=madda_permissible>ُو</rule>نَ ٦',
    6, 30, 7, 602, 549, 240, 'false'
  );
  
  -- Ayah 7 Surah Al-Maaun
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    107,
    6204,
    'وَیَمۡنَعُونَ ٱلۡمَاعُونَ',
    'ويمنعون الماعون',
    'وَيَمۡنَعُونَ <rule class=ham_wasl>ٱ</rule>لۡمَاع<rule class=madda_permissible>ُو</rule>نَ ٧',
    7, 30, 7, 602, 549, 240, 'false'
  );
  

-- Surah Al-Kawthar
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (108, 'سُورَةُ الكَوۡثَرِ', 'Al-Kawthar', 'Abundance', 'Meccan', 3);

  -- Ayah 1 Surah Al-Kawthar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    108,
    6205,
    'إِنَّاۤ أَعۡطَیۡنَـٰكَ ٱلۡكَوۡثَرَ',
    'انا اعطيناك الكوثر',
    'إِ<rule class=ghunnah>نّ</rule><rule class=madda_obligatory_monfasel>َآ</rule> أَعۡطَيۡنَ<rule class=madda_normal>ـٰ</rule>كَ <rule class=ham_wasl>ٱ</rule>لۡكَوۡثَرَ ١',
    1, 30, 7, 602, 550, 240, 'false'
  );
  
  -- Ayah 2 Surah Al-Kawthar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    108,
    6206,
    'فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ',
    'فصل لربك وانحر',
    'فَصَلِّ لِرَبِّكَ وَ<rule class=ham_wasl>ٱ</rule>نۡحَرۡ ٢',
    2, 30, 7, 602, 550, 240, 'false'
  );
  
  -- Ayah 3 Surah Al-Kawthar
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    108,
    6207,
    'إِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ',
    'ان شانئك هو الابتر',
    'إِ<rule class=ghunnah>نّ</rule>َ شَانِئَكَ هُوَ <rule class=ham_wasl>ٱ</rule>لۡأَ<rule class=qalaqah>بۡ</rule>تَرُ ٣',
    3, 30, 7, 602, 550, 240, 'false'
  );
  

-- Surah Al-Kaafiroon
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (109, 'سُورَةُ الكَافِرُونَ', 'Al-Kaafiroon', 'The Disbelievers', 'Meccan', 6);

  -- Ayah 1 Surah Al-Kaafiroon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    109,
    6208,
    'قُلۡ یَـٰۤأَیُّهَا ٱلۡكَـٰفِرُونَ',
    'قل يا ايها الكافرون',
    'قُلۡ يَ<rule class=madda_obligatory_mottasel>ـٰٓ</rule>أَيُّهَا <rule class=ham_wasl>ٱ</rule>لۡكَ<rule class=madda_normal>ـٰ</rule>فِر<rule class=madda_permissible>ُو</rule>نَ ١',
    1, 30, 7, 603, 551, 240, 'false'
  );
  
  -- Ayah 2 Surah Al-Kaafiroon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    109,
    6209,
    'لَاۤ أَعۡبُدُ مَا تَعۡبُدُونَ',
    'لا اعبد ما تعبدون',
    'ل<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡبُدُ مَا تَعۡبُد<rule class=madda_permissible>ُو</rule>نَ ٢',
    2, 30, 7, 603, 551, 240, 'false'
  );
  
  -- Ayah 3 Surah Al-Kaafiroon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    109,
    6210,
    'وَلَاۤ أَنتُمۡ عَـٰبِدُونَ مَاۤ أَعۡبُدُ',
    'ولا انتم عابدون ما اعبد',
    'وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ عَ<rule class=madda_normal>ـٰ</rule>بِدُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡبُ<rule class=qalaqah>د</rule>ُ ٣',
    3, 30, 7, 603, 551, 240, 'false'
  );
  
  -- Ayah 4 Surah Al-Kaafiroon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    109,
    6211,
    'وَلَاۤ أَنَا۠ عَابِدࣱ مَّا عَبَدتُّمۡ',
    'ولا انا عابد ما عبدتم',
    'وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَنَاۡ عَابِ<rule class=idgham_ghunnah>دٌ</rule> <rule class=idgham_ghunnah>م</rule>َّا عَبَ<rule class=idgham_mutajanisayn>د</rule>تُّمۡ ٤',
    4, 30, 7, 603, 551, 240, 'false'
  );
  
  -- Ayah 5 Surah Al-Kaafiroon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    109,
    6212,
    'وَلَاۤ أَنتُمۡ عَـٰبِدُونَ مَاۤ أَعۡبُدُ',
    'ولا انتم عابدون ما اعبد',
    'وَل<rule class=madda_obligatory_monfasel>َآ</rule> أَ<rule class=ikhafa>نت</rule>ُمۡ عَ<rule class=madda_normal>ـٰ</rule>بِدُونَ م<rule class=madda_obligatory_monfasel>َآ</rule> أَعۡبُ<rule class=qalaqah>د</rule>ُ ٥',
    5, 30, 7, 603, 551, 240, 'false'
  );
  
  -- Ayah 6 Surah Al-Kaafiroon
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    109,
    6213,
    'لَكُمۡ دِینُكُمۡ وَلِیَ دِینِ',
    'لكم دينكم ولي دين',
    'لَكُمۡ دِينُكُمۡ وَلِىَ د<rule class=madda_permissible>ِي</rule>نِ ٦',
    6, 30, 7, 603, 551, 240, 'false'
  );
  

-- Surah An-Nasr
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (110, 'سُورَةُ النَّصۡرِ', 'An-Nasr', 'Divine Support', 'Medinan', 3);

  -- Ayah 1 Surah An-Nasr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    110,
    6214,
    'إِذَا جَاۤءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ',
    'اذا جاء نصر الله والفتح',
    'إِذَا ج<rule class=madda_obligatory_mottasel>َا</rule>ٓءَ نَصۡرُ <rule class=ham_wasl>ٱ</rule>للَّهِ وَ<rule class=ham_wasl>ٱ</rule>لۡفَتۡحُ ١',
    1, 30, 7, 603, 552, 240, 'false'
  );
  
  -- Ayah 2 Surah An-Nasr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    110,
    6215,
    'وَرَأَیۡتَ ٱلنَّاسَ یَدۡخُلُونَ فِی دِینِ ٱللَّهِ أَفۡوَاجࣰا',
    'ورايت الناس يدخلون في دين الله افواجا',
    'وَرَأَيۡتَ <rule class=ham_wasl>ٱ</rule><rule class=laam_shamsiyah>ل</rule><rule class=ghunnah>نّ</rule>َاسَ يَ<rule class=qalaqah>دۡ</rule>خُلُونَ فِى دِينِ <rule class=ham_wasl>ٱ</rule>للَّهِ أَفۡوَاجًا ٢',
    2, 30, 7, 603, 552, 240, 'false'
  );
  
  -- Ayah 3 Surah An-Nasr
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    110,
    6216,
    'فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا',
    'فسبح بحمد ربك واستغفره انه كان توابا',
    'فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَ<rule class=ham_wasl>ٱ</rule>سۡتَغۡفِرۡهُ‌ۚ إِ<rule class=ghunnah>نّ</rule>َهُ<rule class=madda_normal>ۥ</rule> كَانَ تَوَّابَۢا ٣',
    3, 30, 7, 603, 552, 240, 'false'
  );
  

-- Surah Al-Masad
INSERT INTO surah (number, name, english_name, english_name_translation, revelation_type, number_of_ayahs)
VALUES (111, 'سُورَةُ المَسَدِ', 'Al-Masad', 'The Palm Fibre', 'Meccan', 5);

  -- Ayah 1 Surah Al-Masad
  INSERT INTO ayah (surah_number_fk, number, text, imlaei_simple_text, qpc_tajweed_text, number_in_surah, juz, manzil, page, ruku, hizb_quarter, sajda)
  VALUES (
    111,
    6217,
    'تَبَّتۡ یَدَاۤ أَبِی لَهَبࣲ وَتَبَّ',
    'تبت يدا ابي لهب وتب',
    'تَبَّتۡ يَد<rule class=madda_obligatory_monfasel>َآ</rule> أَبِى لَهَ<rule class=idgham_ghunnah>بٍ</rule> <rule class=idgham_ghunnah>و</rule>َتَ<rule class=qalaqah>ب</rule>َّ ١',
    1, 30, 7, 603, 553, 240, 'false'
  );
  
  -- Ayah 2 Surah Al-Masad
